--
-- Name: _adapt_folvy_pos_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._adapt_folvy_pos_order(p_sale_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale     sale%rowtype;
  v_acc      uuid;
  v_payload  jsonb;
  v_line     jsonb;
  v_mi       menu_item%rowtype;
  v_comp_mi  menu_item%rowtype;
  v_repr     jsonb;
  v_qty      numeric;
  v_parent   uuid;
  v_comp     uuid;
  v_m        jsonb;
  v_c        jsonb;
  v_opt      record;
  v_count    integer := 0;
  v_pt       text;
begin
  select * into v_sale from sale where id = p_sale_id;
  if not found then return 0; end if;
  if v_sale.source <> 'folvy_pos' or v_sale.raw_tab is null then return 0; end if;
  v_acc := v_sale.account_id;
  v_payload := v_sale.raw_tab::jsonb;

  delete from sale_line
  where sale_id = p_sale_id and coalesce(map_source, '') <> 'manual';

  if jsonb_typeof(v_payload->'lines') <> 'array' then return 0; end if;

  for v_line in select * from jsonb_array_elements(v_payload->'lines')
  loop
    v_repr := public._shop_reprice_line(v_acc, v_line);
    v_qty  := coalesce((v_line->>'quantity')::numeric, 1);
    v_pt   := coalesce(v_line->>'productType', 'item');

    select * into v_mi from menu_item
    where id = (v_line->>'menuItemId')::uuid and account_id = v_acc;
    if not found then v_mi := null; end if;

    insert into sale_line (account_id, sale_id, product_name, raw_text, line_type,
                           quantity, unit_price, line_total, menu_item_id, kitchen_note,
                           map_source, map_needs_review, unmapped_reason,
                           external_source, external_product_id, external_brand_id)
    values (v_acc, p_sale_id,
            coalesce(v_mi.name, v_repr->>'name'),
            coalesce(v_mi.name, v_repr->>'name'),
            'product',
            v_qty,
            (v_repr->>'unitPrice')::numeric,
            (v_repr->>'lineTotal')::numeric,
            v_mi.id,
            nullif(btrim(v_line->>'kitchenNote'), ''),
            case when v_mi.id is not null then 'pos' else 'unmapped' end,
            (v_mi.id is null),
            case when v_mi.id is null then 'no_menu_item' else null end,
            'folvy_pos', (v_line->>'menuItemId'), v_mi.brand_id::text)
    returning id into v_parent;
    v_count := v_count + 1;

    if jsonb_typeof(v_line->'modifiers') = 'array' then
      for v_m in select * from jsonb_array_elements(v_line->'modifiers')
      loop
        select mo.id, mo.name, mo.price_impact into v_opt
        from modifier_option mo
        join modifier_group mg on mg.id = mo.modifier_group_id
        join modifier_group_assignment mga on mga.modifier_group_id = mg.id
        where mo.id = (v_m->>'optionId')::uuid and mga.menu_item_id = v_mi.id
          and mo.is_active and mg.is_active
        limit 1;
        if not found then v_opt := null; end if;

        insert into sale_line (account_id, sale_id, product_name, raw_text, line_type,
                               quantity, unit_price, line_total, modifier_option_id,
                               map_source, map_needs_review, parent_sale_line_id,
                               external_source, external_product_id, external_brand_id)
        values (v_acc, p_sale_id,
                coalesce(v_opt.name, 'modificador'), coalesce(v_opt.name, 'modificador'),
                'modifier',
                coalesce((v_m->>'qty')::numeric, 1),
                coalesce(v_opt.price_impact, 0),
                coalesce(v_opt.price_impact, 0) * coalesce((v_m->>'qty')::numeric, 1),
                v_opt.id,
                case when v_opt.id is not null then 'pos' else 'unmapped' end,
                (v_opt.id is null), v_parent,
                'folvy_pos', (v_m->>'optionId'), v_mi.brand_id::text);
        v_count := v_count + 1;
      end loop;
    end if;

    if v_pt = 'combo' and jsonb_typeof(v_line->'combo') = 'array' then
      for v_c in select * from jsonb_array_elements(v_line->'combo')
      loop
        select * into v_comp_mi from menu_item
        where id = (v_c->>'menuItemId')::uuid and account_id = v_acc;
        if not found then v_comp_mi := null; end if;

        insert into sale_line (account_id, sale_id, product_name, raw_text, line_type,
                               quantity, unit_price, line_total, menu_item_id,
                               map_source, map_needs_review, unmapped_reason, parent_sale_line_id,
                               external_source, external_product_id, external_brand_id)
        values (v_acc, p_sale_id,
                coalesce(v_comp_mi.name, 'combo_item'), coalesce(v_comp_mi.name, 'combo_item'),
                'combo_item',
                1, 0, 0, v_comp_mi.id,
                case when v_comp_mi.id is not null then 'pos' else 'unmapped' end,
                (v_comp_mi.id is null),
                case when v_comp_mi.id is null then 'no_menu_item' else null end,
                v_parent,
                'folvy_pos', (v_c->>'menuItemId'), v_comp_mi.brand_id::text)
        returning id into v_comp;
        v_count := v_count + 1;

        if jsonb_typeof(v_c->'modifiers') = 'array' then
          for v_m in select * from jsonb_array_elements(v_c->'modifiers')
          loop
            select mo.id, mo.name, mo.price_impact into v_opt
            from modifier_option mo
            join modifier_group mg on mg.id = mo.modifier_group_id
            join modifier_group_assignment mga on mga.modifier_group_id = mg.id
            where mo.id = (v_m->>'optionId')::uuid and mga.menu_item_id = v_comp_mi.id
              and mo.is_active and mg.is_active
            limit 1;
            if not found then v_opt := null; end if;

            insert into sale_line (account_id, sale_id, product_name, raw_text, line_type,
                                   quantity, unit_price, line_total, modifier_option_id,
                                   map_source, map_needs_review, parent_sale_line_id,
                                   external_source, external_product_id, external_brand_id)
            values (v_acc, p_sale_id,
                    coalesce(v_opt.name, 'modificador'), coalesce(v_opt.name, 'modificador'),
                    'modifier',
                    coalesce((v_m->>'qty')::numeric, 1),
                    coalesce(v_opt.price_impact, 0),
                    coalesce(v_opt.price_impact, 0) * coalesce((v_m->>'qty')::numeric, 1),
                    v_opt.id,
                    case when v_opt.id is not null then 'pos' else 'unmapped' end,
                    (v_opt.id is null), v_comp,
                    'folvy_pos', (v_m->>'optionId'), v_comp_mi.brand_id::text);
            v_count := v_count + 1;
          end loop;
        end if;
      end loop;
    end if;
  end loop;

  return v_count;
end;
$$;


--
-- Name: _allergens_of_recipe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._allergens_of_recipe(p_recipe_item_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('code', a.code, 'name_es', a.name_es, 'icon', a.icon) order by a.position), '[]'::jsonb)
  from recipe_item_allergen ria
  join allergen a on a.code = ria.allergen_code
  where ria.recipe_item_id = p_recipe_item_id;
$$;


--
-- Name: _apply_inventory_count_core(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._apply_inventory_count_core(p_count_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_user_name text DEFAULT NULL::text, p_partial boolean DEFAULT false) RETURNS TABLE(adjustments integer, items_recomputed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_location_id uuid;
  v_status text;
  v_is_opening boolean;
  v_instant timestamptz;
  v_missing integer;
  v_faltan text;
  v_need uuid[];
  v_adj integer := 0;
  v_rec integer := 0;
  v_mtype text;
  v_note text;
  v_delta numeric;
  r RECORD;
  v_kind text;
BEGIN
  -- H8: FOR UPDATE serializa aprobaciones concurrentes del MISMO conteo.
  SELECT account_id, location_id, status, is_opening, kind,
         COALESCE(started_at, closed_at, created_at, now())
    INTO v_account_id, v_location_id, v_status, v_is_opening, v_kind, v_instant
    FROM public.inventory_count WHERE id = p_count_id
    FOR UPDATE;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'apply_inventory_count: conteo % no existe', p_count_id;
  END IF;

  IF v_status = 'aprobado' THEN
    RETURN QUERY SELECT 0, 0;
    RETURN;
  END IF;
  IF v_status <> 'en_revision' THEN
    RAISE EXCEPTION 'apply_inventory_count: el conteo debe estar en revisión (está en %)', v_status;
  END IF;

  IF v_kind = 'cycle' THEN
    -- AUTOCONTEO (Julio, 21/10/2026): se aplica entero, con cualquier
    -- diferencia, sin motivos. La diferencia queda guardada en la línea
    -- (variance_*, la calcula el cierre) y nunca frena. Las apartadas siguen
    -- fuera por el filtro de excluded_at de abajo.
    v_need := '{}'::uuid[];
    v_missing := 0;
  ELSE
    SELECT COALESCE(array_agg(q.line_id), '{}'::uuid[]) INTO v_need
      FROM public.count_lines_requiring_reason(p_count_id) q;

    SELECT COUNT(*), string_agg(q.item_name, ', ' ORDER BY q.item_name)
      INTO v_missing, v_faltan
      FROM public.count_lines_requiring_reason(p_count_id) q
      JOIN public.inventory_count_line l ON l.id = q.line_id
     WHERE l.reason_code IS NULL OR l.reason_code = '';

    IF NOT v_is_opening AND NOT p_partial AND v_missing > 0 THEN
      RAISE EXCEPTION 'Faltan motivos en % producto%: %.',
        v_missing, CASE WHEN v_missing = 1 THEN '' ELSE 's' END, v_faltan;
    END IF;
  END IF;

  IF v_is_opening THEN
    v_mtype := 'apertura';
    v_note  := 'Inventario de apertura (stock inicial)';
  ELSE
    v_mtype := 'ajuste';
    v_note  := 'Ajuste por conteo de inventario';
  END IF;

  -- Idempotencia: elimina cualquier asiento previo generado por ESTE conteo.
  DELETE FROM public.stock_movement
    WHERE source_type = 'inventory_count'
      AND source_id   = p_count_id;

  FOR r IN
    SELECT l.recipe_item_id,
           l.counted_qty,
           COALESCE(l.counted_at, v_instant) AS line_instant,
           COALESCE((
             SELECT SUM(sm.qty_base)
               FROM public.stock_movement sm
              WHERE sm.recipe_item_id = l.recipe_item_id
                AND sm.location_id    = v_location_id
                AND sm.occurred_at    < COALESCE(l.counted_at, v_instant)
           ), 0) AS ledger_before,
           -- `avg_unit_cost` a secas, sin COALESCE a 0 (corrección de Julio §1.1, 10/09).
           ril.avg_unit_cost AS unit_cost
      FROM public.inventory_count_line l
      LEFT JOIN public.recipe_item_location_stock ril
        ON ril.recipe_item_id = l.recipe_item_id
       AND ril.location_id = v_location_id
       AND ril.account_id  = v_account_id
     WHERE l.inventory_count_id = p_count_id
       AND l.counted_qty IS NOT NULL
       -- Una línea apartada NO se aplica (11/09): la aparta una persona o el
       -- trigger del ajuste a mano. Es lo único que decide por encima del recuento.
       AND l.excluded_at IS NULL
       AND (
         NOT p_partial
         OR NOT (l.id = ANY(v_need))
         OR (l.reason_code IS NOT NULL AND l.reason_code <> '')
       )
     ORDER BY l.recipe_item_id
  LOOP
    v_delta := r.counted_qty - r.ledger_before;
    IF abs(v_delta) > 0.0000001 THEN
      INSERT INTO public.stock_movement (
        account_id, location_id, recipe_item_id, movement_type, qty_base,
        unit_cost, cost_provisional, source_type, source_id, occurred_at,
        created_by, created_by_name, notes
      ) VALUES (
        v_account_id, v_location_id, r.recipe_item_id, v_mtype, v_delta,
        r.unit_cost, false, 'inventory_count', p_count_id, r.line_instant,
        p_user_id, p_user_name, v_note
      );
      v_adj := v_adj + 1;
    END IF;
    -- El NÚCLEO del recálculo: recompute_location_stock lleva su propia guarda
    -- de cuenta y, de noche y sin usuario, la tumbaría (medido en staging el
    -- 21/10, run 406). La guarda de cuenta ya la hace apply_inventory_count.
    PERFORM public.recompute_location_stock_core(r.recipe_item_id, v_location_id);
    v_rec := v_rec + 1;
  END LOOP;

  IF v_missing > 0 AND p_partial THEN
    UPDATE public.inventory_count
      SET updated_at = now()
      WHERE id = p_count_id;
  ELSE
    UPDATE public.inventory_count
      SET status = 'aprobado',
          approved_at = now(),
          approved_by = p_user_id,
          approved_by_name = p_user_name,
          updated_at = now()
      WHERE id = p_count_id;
  END IF;

  RETURN QUERY SELECT v_adj, v_rec;
END;
$$;


--
-- Name: _article_weighted_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._article_weighted_cost(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item    recipe_item%rowtype;
  v_days    integer;
  v_hoy     date;
  v_desde   date;
  v_lineas  jsonb;
  v_n       integer;
  v_desc    integer;
  v_amt     numeric;
  v_qty     numeric;
  v_med     numeric;
  v_last    record;
  v_metodo  text;
  v_coste   numeric;
  v_ultima  jsonb := null;
begin
  select * into v_item from recipe_item where id = p_item_id;
  if not found then
    raise exception '_article_weighted_cost: item % no existe', p_item_id;
  end if;

  select ks.cost_window_days_default into v_days
    from kitchen_settings ks where ks.account_id = v_item.account_id;
  v_days  := coalesce(v_days, 90);
  v_hoy   := (now() at time zone 'Europe/Madrid')::date;
  v_desde := v_hoy - v_days;

  with elig as (
    select grl.id, gr.code, gr.receipt_date, s.name as proveedor, grl.product_name,
           grl.qty_in_base as q, grl.doc_amount as a,
           grl.doc_amount / grl.qty_in_base as eur
      from goods_receipt_line grl
      join goods_receipt gr
        on gr.id = grl.goods_receipt_id and gr.account_id = v_item.account_id
      left join supplier s on s.id = gr.supplier_id
     where grl.recipe_item_id = p_item_id
       and grl.account_id     = v_item.account_id
       and gr.status in ('recibido', 'confirmado')
       and not grl.not_goods
       and grl.qty_in_base > 0
       and grl.doc_amount is not null
       and gr.receipt_date >= v_desde
       and exists (select 1 from stock_movement sm
                    where sm.source_type = 'goods_receipt_line'
                      and sm.source_id   = grl.id
                      and sm.movement_type = 'recepcion')
  ), med as (
    select percentile_cont(0.5) within group (order by eur) as m from elig where a > 0
  ), marcadas as (
    select e.*,
           case when e.a <= 0                          then 'importe_no_positivo'
                when med.m > 0 and e.eur > 3 * med.m   then 'mas_de_3x_la_mediana'
                when med.m > 0 and e.eur < med.m / 3   then 'menos_de_un_tercio_de_la_mediana'
           end as motivo
      from elig e cross join med
  )
  select coalesce(jsonb_agg(jsonb_build_object(
             'linea_id', id, 'albaran', code, 'fecha', receipt_date,
             'proveedor', proveedor, 'producto', product_name,
             'cantidad', q, 'importe', a, 'eur_unidad', eur,
             'entra', motivo is null, 'motivo', motivo)
           order by receipt_date desc, code), '[]'::jsonb),
         count(*),
         count(*) filter (where motivo is not null),
         sum(a) filter (where motivo is null),
         sum(q) filter (where motivo is null),
         (select m from med)
    into v_lineas, v_n, v_desc, v_amt, v_qty, v_med
    from marcadas;

  if v_n - v_desc >= 2 then
    v_metodo := 'media';
    v_coste  := v_amt / v_qty;
  elsif v_n - v_desc = 1 then
    v_metodo := 'poco_dato';
    v_coste  := v_amt / v_qty;
  else
    select gr.code, gr.receipt_date, grl.doc_amount / grl.qty_in_base as eur
      into v_last
      from goods_receipt_line grl
      join goods_receipt gr
        on gr.id = grl.goods_receipt_id and gr.account_id = v_item.account_id
     where grl.recipe_item_id = p_item_id
       and grl.account_id     = v_item.account_id
       and gr.status in ('recibido', 'confirmado')
       and not grl.not_goods
       and grl.qty_in_base > 0
       and grl.doc_amount > 0
       and exists (select 1 from stock_movement sm
                    where sm.source_type = 'goods_receipt_line'
                      and sm.source_id   = grl.id
                      and sm.movement_type = 'recepcion')
     order by gr.receipt_date desc, grl.created_at desc
     limit 1;
    if found then
      v_metodo := 'ultima_conocida';
      v_coste  := v_last.eur;
      v_ultima := jsonb_build_object('albaran', v_last.code, 'fecha', v_last.receipt_date,
                                     'eur_unidad', v_last.eur);
    else
      v_metodo := 'sin_compras';
      v_coste  := null;
    end if;
  end if;

  return jsonb_build_object(
    'recipe_item_id',  p_item_id,
    'ventana_dias',    v_days,
    'desde',           v_desde,
    'metodo',          v_metodo,
    'coste',           v_coste,
    'lineas_ventana',  v_n,
    'descartadas',     v_desc,
    'pct_descartadas', case when v_n > 0 then round(100.0 * v_desc / v_n, 1) else 0 end,
    'cantidad',        v_qty,
    'importe',         v_amt,
    'mediana',         v_med,
    'ultima_compra',   v_ultima,
    'lineas',          v_lineas);
end;
$$;


--
-- Name: _assert_location_in_scope(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._assert_location_in_scope(p_location_id uuid, p_fn text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_location_id is null then
    return;  -- cada funcion decide si el local es obligatorio
  end if;
  if not (p_location_id = any(public.current_user_location_ids())) then
    raise exception '%: sin acceso al local %. Tu usuario no tiene ese local en su alcance.',
      p_fn, p_location_id;
  end if;
end;
$$;


--
-- Name: _autoconteo_aplicar(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._autoconteo_aplicar(p_count_id uuid, p_via text, p_user_id uuid, p_user_name text) RETURNS TABLE(final_status text, adjustments integer, items_recomputed integer, counted_lines integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind text;
  v_status text;
  v_counted integer;
  v_adj integer := 0;
  v_rec integer := 0;
begin
  if p_via not in ('al_terminar', 'cron', 'rezagado') then
    raise exception '_autoconteo_aplicar: forma desconocida «%»', p_via;
  end if;

  select kind, status into v_kind, v_status
    from public.inventory_count where id = p_count_id
    for update;
  if v_kind is null then
    raise exception '_autoconteo_aplicar: conteo % no existe', p_count_id;
  end if;
  if v_kind <> 'cycle' then
    -- Un inventario manual o de seguridad no se aplica solo, nunca.
    raise exception '_autoconteo_aplicar: % no es un autoconteo (es %): no se aplica solo', p_count_id, v_kind;
  end if;
  if v_status in ('aprobado', 'anulado') then
    return query select v_status, 0, 0,
      (select count(*)::int from public.inventory_count_line l
        where l.inventory_count_id = p_count_id and l.counted_qty is not null and l.excluded_at is null);
    return;
  end if;

  select count(*)::int into v_counted
    from public.inventory_count_line l
   where l.inventory_count_id = p_count_id and l.counted_qty is not null and l.excluded_at is null;

  if v_counted = 0 then
    -- Nadie contó nada: no hay nada que aplicar, y aprobarlo diría «aplicado»
    -- sin haber tocado el stock. Se anula, y se dice por qué.
    update public.inventory_count
       set status = 'anulado',
           notes = concat_ws(E'\n', notes, 'Anulado solo: nadie contó nada antes de preparar el siguiente.'),
           auto_applied_via = p_via,
           auto_apply_error = null,
           auto_apply_failed_at = null,
           updated_at = now()
     where id = p_count_id;
    return query select 'anulado'::text, 0, 0, 0;
    return;
  end if;

  if v_status in ('abierto', 'contando') then
    perform public._close_inventory_count_core(p_count_id);
  end if;

  select a.adjustments, a.items_recomputed into v_adj, v_rec
    from public._apply_inventory_count_core(p_count_id, p_user_id, p_user_name, false) a;

  update public.inventory_count
     set auto_applied_via = p_via, auto_apply_error = null, auto_apply_failed_at = null
   where id = p_count_id;

  return query select (select status from public.inventory_count where id = p_count_id), v_adj, v_rec, v_counted;
end;
$$;


--
-- Name: _autoinventory_queue_core(uuid, uuid, integer, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._autoinventory_queue_core(p_account_id uuid, p_location_id uuid, p_window_days integer DEFAULT 30, p_coverage_target numeric DEFAULT 80, p_w_value numeric DEFAULT 0.35, p_w_rotation numeric DEFAULT 0.35, p_w_risk numeric DEFAULT 0.30) RETURNS TABLE(recipe_item_id uuid, name text, code text, base_unit text, qty_on_hand numeric, stock_value numeric, rotation_eur numeric, risk_eur numeric, must_count boolean, critical_reason text, score numeric, score_value numeric, score_rotation numeric, score_risk numeric, abc_rich text, coverage_pct numeric, in_scope boolean, rank integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  RETURN QUERY
  WITH universe AS (
    SELECT ri.id, ri.name, ri.code,
           ku.abbreviation AS base_unit,
           ri.computed_cost,
           ri.is_operational_critical,
           ri.operational_min_qty
    FROM public.recipe_item ri
    LEFT JOIN public.kitchen_unit ku ON ku.id = ri.base_unit_id
    WHERE ri.account_id = p_account_id
      AND ri.type IN ('raw', 'packaging')
      AND ri.is_active = true
  ),
  stk AS (
    SELECT s.recipe_item_id, s.qty_on_hand, s.stock_value, s.avg_unit_cost
    FROM public.recipe_item_location_stock s
    WHERE s.account_id = p_account_id AND s.location_id = p_location_id
  ),
  rot AS (
    SELECT m.recipe_item_id, SUM(ABS(m.qty_base)) AS rot_qty
    FROM public.stock_movement m
    WHERE m.account_id = p_account_id
      AND m.location_id = p_location_id
      AND m.movement_type = 'consumo'
      AND m.occurred_at >= now() - make_interval(days => p_window_days)
    GROUP BY m.recipe_item_id
  ),
  var_risk AS (
    SELECT icl.recipe_item_id, SUM(ABS(COALESCE(icl.variance_value, 0))) AS var_eur
    FROM public.inventory_count_line icl
    JOIN public.inventory_count ic ON ic.id = icl.inventory_count_id
    WHERE icl.account_id = p_account_id
      AND ic.location_id = p_location_id
    GROUP BY icl.recipe_item_id
  ),
  waste_risk AS (
    SELECT w.recipe_item_id, SUM(COALESCE(w.cost_eur, 0)) AS waste_eur
    FROM public.stock_waste w
    WHERE w.account_id = p_account_id AND w.location_id = p_location_id
    GROUP BY w.recipe_item_id
  ),
  raw_scores AS (
    SELECT
      u.id, u.name, u.code, u.base_unit,
      u.is_operational_critical, u.operational_min_qty,
      COALESCE(s.qty_on_hand, 0) AS qty_on_hand,
      COALESCE(s.stock_value, 0) AS stock_value,
      COALESCE(r.rot_qty, 0) * COALESCE(u.computed_cost, s.avg_unit_cost, 0) AS rotation_eur,
      COALESCE(vr.var_eur, 0) + COALESCE(wr.waste_eur, 0) AS risk_eur
    FROM universe u
    LEFT JOIN stk        s  ON s.recipe_item_id  = u.id
    LEFT JOIN rot        r  ON r.recipe_item_id  = u.id
    LEFT JOIN var_risk   vr ON vr.recipe_item_id = u.id
    LEFT JOIN waste_risk wr ON wr.recipe_item_id = u.id
  ),
  maxes AS (
    SELECT
      NULLIF(MAX(stock_value),  0) AS mx_val,
      NULLIF(MAX(rotation_eur), 0) AS mx_rot,
      NULLIF(MAX(risk_eur),     0) AS mx_risk
    FROM raw_scores
  ),
  scored AS (
    SELECT
      rs.*,
      COALESCE(rs.stock_value  / m.mx_val,  0) AS n_val,
      COALESCE(rs.rotation_eur / m.mx_rot,  0) AS n_rot,
      COALESCE(rs.risk_eur     / m.mx_risk, 0) AS n_risk,
      ( rs.is_operational_critical
        OR (rs.operational_min_qty IS NOT NULL AND rs.qty_on_hand < rs.operational_min_qty)
        OR rs.qty_on_hand < 0                                          -- NEGATIVO: error físico seguro
        OR (rs.qty_on_hand = 0 AND rs.rotation_eur > 0)                -- A CERO con rotación: ¿agotado o sin registrar?
      ) AS must_count,
      CASE
        WHEN rs.qty_on_hand < 0 THEN 'stock negativo (revisar)'
        WHEN rs.is_operational_critical
             AND rs.operational_min_qty IS NOT NULL
             AND rs.qty_on_hand < rs.operational_min_qty THEN 'critico + bajo minimo'
        WHEN rs.is_operational_critical THEN 'critico operativo'
        WHEN rs.operational_min_qty IS NOT NULL
             AND rs.qty_on_hand < rs.operational_min_qty THEN 'bajo minimo'
        WHEN rs.qty_on_hand = 0 AND rs.rotation_eur > 0 THEN 'a cero, ¿agotado?'
        ELSE NULL
      END AS critical_reason
    FROM raw_scores rs CROSS JOIN maxes m
  ),
  ranked AS (
    SELECT
      sc.*,
      ROUND(p_w_value * sc.n_val + p_w_rotation * sc.n_rot + p_w_risk * sc.n_risk, 4) AS score,
      ROW_NUMBER() OVER w AS rank,
      SUM(sc.stock_value) OVER (w ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_value,
      SUM(sc.stock_value) OVER () AS tot_value
    FROM scored sc
    WINDOW w AS (
      ORDER BY sc.must_count DESC,
               (p_w_value * sc.n_val + p_w_rotation * sc.n_rot + p_w_risk * sc.n_risk) DESC,
               sc.stock_value DESC
    )
  )
  SELECT
    rk.id, rk.name, rk.code, rk.base_unit,
    ROUND(rk.qty_on_hand, 4), ROUND(rk.stock_value, 2),
    ROUND(rk.rotation_eur, 2), ROUND(rk.risk_eur, 2),
    rk.must_count, rk.critical_reason,
    rk.score, ROUND(rk.n_val, 4), ROUND(rk.n_rot, 4), ROUND(rk.n_risk, 4),
    CASE WHEN rk.tot_value > 0 THEN
      CASE WHEN rk.cum_value / rk.tot_value * 100 <= 80 THEN 'A'
           WHEN rk.cum_value / rk.tot_value * 100 <= 95 THEN 'B'
           ELSE 'C' END
    END AS abc_rich,
    CASE WHEN rk.tot_value > 0 THEN ROUND(rk.cum_value / rk.tot_value * 100, 2) END AS coverage_pct,
    ( rk.must_count
      OR (rk.tot_value > 0 AND rk.cum_value / rk.tot_value * 100 <= p_coverage_target)
    ) AS in_scope,
    rk.rank::integer
  FROM ranked rk
  ORDER BY rk.rank;
END;
$$;


--
-- Name: _availability_panel_core(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._availability_panel_core(p_account_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(product_key text, name text, representative_menu_item_id uuid, recipe_item_id uuid, location_id uuid, location_name text, brands integer, brand_names text[], otros_nombres text[], photo_url text, source_folvy boolean, source_last boolean, reason text, available_until timestamp with time zone, set_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with
  last_off as (
    select ecp.organization_product_id::text as matricula, elm.location_id as loc
    from external_catalog_product ecp
    join external_location_map elm
      on elm.account_id = ecp.account_id and elm.source='lastapp'
     and elm.external_location_id = ecp.external_location_id::text and elm.is_active
    where ecp.account_id = p_account_id and ecp.source='lastapp' and ecp.is_enabled=false
      -- 28/08/2026 · Julio: LAST FUERA DEL PANEL DEL 86, todas las marcas y locales.
      -- Provisional. Para revertir: quitar el "and false" de la linea siguiente.
      and false
    group by ecp.organization_product_id::text, elm.location_id
  ),
  folvy_off as (
    select pa.external_id as matricula, pa.recipe_item_id as rec_id, pa.location_id as loc,
           pa.reason as r_reason, pa.available_until as r_until, pa.set_at as r_set
    from product_availability pa
    where pa.account_id = p_account_id and pa.is_available = false
  ),
  ident as (
    select mi.external_id,
           max(mi.recipe_item_id::text)                                        as rec,
           min(mi.name)                                                        as nm,
           min(mi.id::text)                                                    as repr_id,
           count(distinct mi.brand_id)                                         as brs,
           array_agg(distinct b.name) filter (where b.name is not null)        as bnames,
           (array_agg(mi.photo_url) filter (where mi.photo_url is not null))[1] as photo
    from menu_item mi
    left join brand b on b.id = mi.brand_id
    where mi.account_id = p_account_id and mi.external_id is not null
    group by mi.external_id
  ),
  ident_rec as (
    select mi.recipe_item_id,
           max(mi.recipe_item_id::text)                                        as rec,
           min(mi.name)                                                        as nm,
           min(mi.id::text)                                                    as repr_id,
           count(distinct mi.brand_id)                                         as brs,
           array_agg(distinct b.name) filter (where b.name is not null)        as bnames,
           (array_agg(mi.photo_url) filter (where mi.photo_url is not null))[1] as photo
    from menu_item mi
    left join brand b on b.id = mi.brand_id
    where mi.account_id = p_account_id and mi.recipe_item_id is not null
    group by mi.recipe_item_id
  ),
  unioned as (
    select matricula, null::uuid as rec_id, loc, true as s_last, false as s_folvy,
           null::text as u_reason, null::timestamptz as u_until, null::timestamptz as u_set
    from last_off
    union all
    select matricula, rec_id, loc, false, true, r_reason, r_until, r_set
    from folvy_off
  ),
  exp as (
    select u.matricula, u.loc, u.s_last, u.s_folvy, u.u_reason, u.u_until, u.u_set,
           coalesce(ie.rec, ir.rec)                     as rec,
           coalesce(ie.nm, ir.nm)                       as nm,
           coalesce(ie.repr_id, ir.repr_id)             as repr_id,
           coalesce(ie.brs, ir.brs)                     as brs,
           coalesce(ie.photo, ir.photo)                 as photo,
           (ie.external_id is not null or ir.recipe_item_id is not null) as i_ext,
           bn as brand_name
    from unioned u
    left join ident ie on ie.external_id = u.matricula
    left join ident_rec ir
           on ie.external_id is null and ir.recipe_item_id = u.rec_id
    left join lateral unnest(coalesce(ie.bnames, ir.bnames, array[]::text[])) as bn on true
  ),
  grouped as (
    select coalesce(rec, matricula)                                           as pkey,
           (array_agg(nm       order by s_folvy desc, (nm is null),
                                        u_set desc nulls last, repr_id))[1]    as nm,
           (array_agg(repr_id  order by s_folvy desc, (nm is null),
                                        u_set desc nulls last, repr_id))[1]    as repr,
           (array_agg(u_reason order by s_folvy desc, (nm is null),
                                        u_set desc nulls last, repr_id))[1]    as g_reason,
           (array_agg(u_until  order by s_folvy desc, (nm is null),
                                        u_set desc nulls last, repr_id))[1]    as g_until,
           (array_agg(u_set    order by s_folvy desc, (nm is null),
                                        u_set desc nulls last, repr_id))[1]    as g_set,
           max(rec)                                                           as rec,
           loc,
           max(brs)                                                           as brs,
           array_agg(distinct brand_name) filter (where brand_name is not null) as bnames,
           array_agg(distinct nm) filter (where nm is not null)                as all_names,
           (array_agg(photo) filter (where photo is not null))[1]            as photo,
           bool_or(s_folvy)                                                   as s_folvy,
           bool_or(s_last)                                                    as s_last,
           bool_or(i_ext)                                                     as tiene_ficha
    from exp
    group by coalesce(rec, matricula), loc
  )
  select g.pkey, coalesce(g.nm,'(producto)'), g.repr::uuid, g.rec::uuid,
         g.loc, l.name, coalesce(g.brs,0)::int, g.bnames,
         (select array_agg(x) from unnest(coalesce(g.all_names, array[]::text[])) x
           where x is distinct from g.nm),
         g.photo,
         g.s_folvy, g.s_last,
         coalesce(g.g_reason,'manual'), g.g_until, g.g_set
  from grouped g
  left join locations l on l.id = g.loc
  where (p_location_id is null or g.loc = p_location_id or g.loc is null)
    and g.tiene_ficha and coalesce(g.brs,0) > 0
  order by g.nm;
end;
$$;


--
-- Name: _aviso_falta_en_vault(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._aviso_falta_en_vault(p_que text, p_venta uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  begin
    perform public._queue_system_alert(
      'vault',
      'Sin llamar a ' || p_que || ': falta un ajuste en el Vault',
      format('El pedido %s no ha llamado a %s porque falta project_url (o su secreto) en el Vault de este proyecto. El pedido se ha guardado; la llamada no ha salido.', p_venta, p_que),
      'vault-' || p_que
    );
  exception when others then
    raise warning '_aviso_falta_en_vault: no se pudo avisar de % (venta %): %', p_que, p_venta, sqlerrm;
  end;
end $$;


--
-- Name: _aviso_olvido_responder(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._aviso_olvido_responder(p_log_id uuid, p_respuesta text, p_hora timestamp with time zone, p_via text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  l public.clockout_reminder_log;
  v_siguiente timestamptz;
  v_hora timestamptz;
  v_peticion public.clock_correction_request;
  v_existente uuid;
  v_motivo text;
  v_hhmm text;
begin
  if p_respuesta not in ('a_su_hora', 'otra_hora', 'sigo') then
    raise exception 'RESPUESTA_INVALIDA' using errcode = '22023';
  end if;
  select * into l from public.clockout_reminder_log where id = p_log_id for update;
  if not found or l.entrada_at is null then
    return jsonb_build_object('resultado', 'no_existe', 'texto', 'No encontramos ese aviso. Si te falta la salida, pídela desde tu portal.');
  end if;
  if l.correction_request_id is not null then
    return jsonb_build_object('resultado', 'ya_respondida', 'peticion_id', l.correction_request_id,
      'texto', 'Ya nos contestaste: tu encargado tiene la petición para revisarla.');
  end if;

  if not exists (select 1 from public.clock_entries ce where ce.id = l.clock_entry_id and not ce.voided) then
    return jsonb_build_object('resultado', 'anulada', 'texto', 'Esa entrada ya no está en tu registro: no hace falta nada.');
  end if;
  -- ¿Sigue abierta? Si ya hay algo fichado después, no hace falta nada.
  select min(n.datetime) into v_siguiente from public.clock_entries n
   where n.employee_id = l.employee_id and not n.voided and n.id <> l.clock_entry_id and n.datetime > l.entrada_at;
  if v_siguiente is not null then
    update public.clockout_reminder_log set respuesta = p_respuesta, respondida_at = now(), respondida_via = p_via, updated_at = now() where id = l.id;
    return jsonb_build_object('resultado', 'ya_fichada',
      'texto', format('Ya tienes fichado lo siguiente a las %s. No hace falta nada más.', to_char(v_siguiente at time zone 'Europe/Madrid', 'HH24:MI')));
  end if;

  if p_respuesta = 'sigo' then
    update public.clockout_reminder_log set respuesta = 'sigo', respondida_at = now(), respondida_via = p_via, updated_at = now() where id = l.id;
    return jsonb_build_object('resultado', 'apuntado', 'texto', 'Apuntado. Acuérdate de fichar la salida al terminar.');
  end if;

  v_hora := case when p_respuesta = 'a_su_hora' then l.fin_turno else p_hora end;
  if v_hora is null then
    -- «Otra hora» por WhatsApp (o «a su hora» sin turno): la hora la pone en el portal.
    update public.clockout_reminder_log set respuesta = p_respuesta, respondida_at = now(), respondida_via = p_via, updated_at = now() where id = l.id;
    return jsonb_build_object('resultado', 'pide_hora', 'texto', 'Dinos a qué hora saliste desde tu portal. Tu encargado lo revisará.');
  end if;
  if v_hora <= l.entrada_at then
    raise exception 'HORA_ANTES_DE_LA_ENTRADA' using errcode = '22023', hint = 'La salida tiene que ser después de la entrada.';
  end if;
  if v_hora > now() + interval '5 minutes' then
    raise exception 'HORA_FUTURA' using errcode = '22023', hint = 'La salida no puede ser una hora que aún no ha llegado.';
  end if;

  v_hhmm := to_char(v_hora at time zone 'Europe/Madrid', 'HH24:MI');
  -- Si ya hay una petición de esa salida (la pidió desde «Reportar olvido»), se enlaza.
  select r.id into v_existente from public.clock_correction_request r
   where r.employee_id = l.employee_id and r.kind = 'add' and r.proposed_type = 'salida'
     and r.status in ('pending', 'approved') and r.proposed_datetime > l.entrada_at
   order by r.created_at desc limit 1;
  if v_existente is not null then
    update public.clockout_reminder_log set respuesta = p_respuesta, respondida_at = now(), respondida_via = p_via,
           correction_request_id = v_existente, updated_at = now() where id = l.id;
    return jsonb_build_object('resultado', 'ya_pedida', 'peticion_id', v_existente,
      'texto', 'Ya tenías pedida esa salida: tu encargado la tiene para revisarla.');
  end if;

  v_motivo := format('Respuesta al aviso de olvido (%s): %s.',
                     case p_via when 'whatsapp' then 'WhatsApp' else 'portal' end,
                     case when p_respuesta = 'a_su_hora' then format('salí a mi hora, a las %s', v_hhmm)
                          else format('salí a las %s', v_hhmm) end);
  insert into public.clock_correction_request(
    account_id, employee_id, requested_by_employee_id, clock_entry_id, kind, proposed_type, proposed_datetime, reason)
  values (l.account_id, l.employee_id, l.employee_id, null, 'add', 'salida', v_hora, v_motivo)
  returning * into v_peticion;
  insert into public.clock_entry_audit(
    clock_entry_id, employee_id, account_id, action, actor_employee_id, actor_label, reason, after, peticion_id)
  values (null, l.employee_id, l.account_id, 'request', l.employee_id,
          case p_via when 'whatsapp' then 'WhatsApp (aviso de olvido)' else 'Portal (aviso de olvido)' end,
          v_motivo, to_jsonb(v_peticion), v_peticion.id);
  update public.clockout_reminder_log set respuesta = p_respuesta, respondida_at = now(), respondida_via = p_via,
         correction_request_id = v_peticion.id, updated_at = now() where id = l.id;
  return jsonb_build_object('resultado', 'peticion', 'peticion_id', v_peticion.id, 'hora', v_hhmm,
    'texto', format('Hecho: le hemos pedido a tu encargado que apunte tu salida a las %s. Lo verás en tu portal cuando la apruebe.', v_hhmm));
end $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: bank_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_settings (
    company_id uuid NOT NULL,
    account_id uuid NOT NULL,
    treasury_series smallint DEFAULT 3 NOT NULL,
    validate_safe boolean DEFAULT false NOT NULL,
    cutover_date date,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    updated_by_name text,
    CONSTRAINT bank_settings_treasury_series_check CHECK ((treasury_series = ANY (ARRAY[3, 4])))
);


--
-- Name: TABLE bank_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_settings IS 'B01. Por empresa: serie de tesorería de los asientos del banco (3 como el C04; Foodint 4, como Diez desde 04/2025), «validar solo lo seguro» (apagado por defecto) y la fecha de corte: antes de ella un extracto solo enlaza con lo que ya está en el libro y no crea asientos.';


--
-- Name: _bank_ajustes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_ajustes(p_company uuid) RETURNS public.bank_settings
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.bank_settings;
begin
  select * into v from public.bank_settings where company_id = p_company;
  if v.company_id is null then
    -- Sin fila: los valores por defecto. El corte, el de la empresa (lo traído llega hasta imported_until).
    v.company_id := p_company; v.treasury_series := 3; v.validate_safe := false;
    select max(imported_until) + 1 into v.cutover_date from public.fiscal_year where company_id = p_company and imported_until is not null;
  end if;
  return v;
end $$;


--
-- Name: _bank_contraparte_limpia(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_contraparte_limpia(p text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare s text; w text; r text := ''; c text; prev text := ' '; i int;
begin
  if p is null then return null; end if;
  s := upper(p);
  s := regexp_replace(s, '[*X•·]{3,} ?[0-9]{4}', ' ', 'g');
  s := regexp_replace(s, '[A-Z]{2}[0-9]{2}[A-Z0-9]{10,}', ' ', 'g');
  s := regexp_replace(s, '[0-9]{5,}', ' ', 'g');
  s := regexp_replace(s, '[^[:alpha:][:digit:] &.-]', ' ', 'g');
  s := trim(regexp_replace(s, '\s+', ' ', 'g'));
  s := regexp_replace(s, '^[ -]+|[ -]+$', '', 'g');
  if s = '' then return null; end if;
  -- Mayúscula en cada letra que no va detrás de otra letra o cifra (no initcap:
  -- deja «S.L.» como «S.l.»; esto es lo mismo que hace el front).
  s := lower(s);
  for i in 1..length(s) loop
    c := substr(s, i, 1);
    r := r || case when c ~ '[[:alpha:]]' and prev !~ '[[:alpha:][:digit:]]' then upper(c) else c end;
    prev := c;
  end loop;
  s := r;
  foreach w in array array['De', 'Del', 'La', 'Las', 'Los', 'El', 'Y', 'En'] loop
    s := regexp_replace(s, ' ' || w || '(?= )', ' ' || lower(w), 'g');
  end loop;
  foreach w in array array['Sl', 'Sa', 'Slu', 'Sc', 'Cb'] loop
    s := regexp_replace(s, '(?<![[:alpha:][:digit:]])' || w || '(?![[:alpha:][:digit:]])', upper(w), 'g');
  end loop;
  return s;
end $_$;


--
-- Name: _bank_cuenta_572(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_cuenta_572(p_treasury uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select ca.code from public.company_account_link l join public.company_account ca on ca.id = l.company_account_id
   where l.entity = 'bank_account' and l.entity_id = p_treasury::text and l.role = 'principal' limit 1
$$;


--
-- Name: _bank_cuenta_de_empresa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_cuenta_de_empresa(p_company uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v uuid;
begin
  select account_id into v from public.company where id = p_company;
  if v is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  -- B01c: la función de cada noche (conta-banco-agregador) llama con la clave de servicio, sin persona.
  if not (public.current_user_is_admin_or_manager_of(v) or auth.role() = 'service_role') then
    raise exception 'Solo un administrador o un encargado de la cuenta trabaja los bancos.' using errcode = '42501';
  end if;
  return v;
end $$;


--
-- Name: _bank_factura_aprobada_con_pago(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_factura_aprobada_con_pago() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_pagado numeric; v_fecha date; v_metodo text; v_mov public.bank_movement;
begin
  if new.status <> 'aprobada' or old.status = 'aprobada' or new.paid_at is not null then return null; end if;
  select coalesce(sum(i.amount), 0) into v_pagado from public.bank_match_item i join public.bank_match b on b.id = i.match_id
   where i.supplier_invoice_id = new.id and b.status = 'vivo';
  if v_pagado = 0 or v_pagado < coalesce(new.grand_total, 0) - 0.005 then return null; end if;
  select m.* into v_mov from public.bank_match_item i join public.bank_match b on b.id = i.match_id join public.bank_movement m on m.id = b.movement_id
   where i.supplier_invoice_id = new.id and b.status = 'vivo' order by m.op_date desc limit 1;
  v_fecha := v_mov.op_date;
  v_metodo := case when v_mov.common_code = '03' or v_mov.bank_concept ~* 'RECIBO|ADEUDO|DOMICILIA' then 'direct_debit' else 'transfer' end;
  begin
    perform public.mark_supplier_invoice_paid(new.id, v_fecha, v_metodo);
    perform public._bank_log(v_mov.account_id, v_mov.company_id, v_mov.id, null, null, 'validado', 'folvy',
      format('La factura %s se ha aprobado y ya tenía su pago casado: la he marcado pagada el %s.', coalesce(new.invoice_number, ''), to_char(v_fecha, 'DD/MM/YYYY')),
      jsonb_build_object('factura', new.id, 'pagada', v_fecha));
  exception when others then
    perform public._bank_log(v_mov.account_id, v_mov.company_id, v_mov.id, null, null, 'por_aclarar', 'folvy',
      format('La factura %s se ha aprobado y ya tenía su pago casado, pero no he podido marcarla pagada: %s', coalesce(new.invoice_number, ''), sqlerrm),
      jsonb_build_object('factura', new.id));
  end;
  return null;
end $$;


--
-- Name: _bank_log(uuid, uuid, uuid, uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_log(p_account uuid, p_company uuid, p_mov uuid, p_match uuid, p_ext uuid, p_accion text, p_por text, p_resumen text, p_detalle jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.bank_activity_log (account_id, company_id, movement_id, match_id, statement_id, action, by_who, summary, detail, created_by, created_by_name)
  values (p_account, p_company, p_mov, p_match, p_ext, p_accion, p_por, p_resumen, coalesce(p_detalle, '{}'::jsonb), auth.uid(),
          case when p_por = 'folvy' then 'Folvy' else public.conta_nombre_actor() end)
$$;


--
-- Name: _bank_mes_estado(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_mes_estado(p_treasury uuid, p_mes date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_t public.treasury_account; v_desde date := date_trunc('month', p_mes)::date; v_hasta date; v_572 text;
  v_banco numeric; v_libro numeric; v_n int; v_suma numeric; v_extracto date;
  v_corte date; v_vispera date; v_banco_ap numeric; v_libro_ap numeric; v_contable numeric; v_apertura jsonb;
  v_espera int; v_espera_de jsonb;
begin
  v_hasta := (v_desde + interval '1 month - 1 day')::date;
  select * into v_t from public.treasury_account where id = p_treasury;
  v_572 := public._bank_cuenta_572(p_treasury);
  -- El saldo del banco a fin de mes: el del último extracto que llega hasta ese día (con saldos).
  select s.closing_balance, s.period_to into v_banco, v_extracto from public.bank_statement s
   where s.treasury_account_id = p_treasury and s.closing_balance is not null and s.period_to <= v_hasta
   order by s.period_to desc, s.imported_at desc limit 1;
  if v_extracto is not null and v_extracto < v_hasta and exists (select 1 from public.bank_movement m
       where m.treasury_account_id = p_treasury and m.op_date > v_extracto and m.op_date <= v_hasta) then
    v_banco := null;  -- hay movimientos después del último saldo conocido: el saldo de fin de mes no se sabe
  end if;
  select coalesce(sum(jl.debit - jl.credit), 0) into v_libro
    from public.journal_line jl join public.journal_entry je on je.id = jl.entry_id join public.company_account ca on ca.id = jl.company_account_id
   where ca.company_id = v_t.company_id and ca.code = v_572 and je.status in ('validado', 'anulado', 'propuesto')
     and je.entry_date <= v_hasta and je.source_type <> 'closing';
  v_contable := v_libro;
  -- B02 · El punto de partida (regla de Julio, 16/10): desde la fecha de corte,
  -- se parte del saldo del EXTRACTO a la víspera, no del contable, porque hasta
  -- esa fecha la contabilidad está cerrada y casi sin conciliar. Lo mismo que
  -- puntoDePartida (src/modules/conta/lib/conciliarVista.ts). Sin ese saldo,
  -- el contable de siempre, y la pantalla lo dice.
  select b.cutover_date into v_corte from public.bank_settings b where b.company_id = v_t.company_id;
  if v_corte is not null and v_hasta >= v_corte then
    v_vispera := v_corte - 1;
    select s.opening_balance into v_banco_ap from public.bank_statement s
     where s.treasury_account_id = p_treasury and s.period_from = v_corte and s.opening_balance is not null order by s.imported_at desc limit 1;
    if v_banco_ap is null then
      select s.closing_balance into v_banco_ap from public.bank_statement s
       where s.treasury_account_id = p_treasury and s.period_to = v_vispera and s.closing_balance is not null order by s.imported_at desc limit 1;
    end if;
    select coalesce(sum(jl.debit - jl.credit), 0) into v_libro_ap
      from public.journal_line jl join public.journal_entry je on je.id = jl.entry_id join public.company_account ca on ca.id = jl.company_account_id
     where ca.company_id = v_t.company_id and ca.code = v_572 and je.status in ('validado', 'anulado', 'propuesto')
       and je.entry_date <= v_vispera and je.source_type <> 'closing';
    if v_banco_ap is not null then v_libro := v_banco_ap + (v_libro - v_libro_ap); end if;
    v_apertura := jsonb_build_object('fecha', v_vispera, 'saldo_banco', v_banco_ap, 'saldo_libro', v_libro_ap);
  end if;
  select count(*), coalesce(sum(amount), 0) into v_n, v_suma from public.bank_movement
   where treasury_account_id = p_treasury and op_date between v_desde and v_hasta and status not in ('casado', 'ignorado');
  -- B02 · Los traspasos que esperan el extracto de otra cuenta (siguen sin casar: cuentan en sueltos).
  select count(*), coalesce(jsonb_agg(distinct coalesce(proposal->>'esperaExtracto', 'otra cuenta')), '[]'::jsonb)
    into v_espera, v_espera_de from public.bank_movement
   where treasury_account_id = p_treasury and op_date between v_desde and v_hasta and status = 'espera_extracto';
  return jsonb_build_object('mes', v_desde, 'hasta', v_hasta, 'cuenta', v_572, 'saldo_banco', v_banco, 'extracto_hasta', v_extracto,
    'saldo_libro', v_libro, 'diferencia', case when v_banco is null then null else v_banco - v_libro end,
    'sueltos', v_n, 'sueltos_importe', v_suma,
    'saldo_contable', v_contable, 'apertura', v_apertura, 'esperan', v_espera, 'esperan_de', v_espera_de);
end $$;


--
-- Name: _bank_movimiento_sin_tarjetas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_movimiento_sin_tarjetas() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.bank_concept := public._bank_ocultar_tarjetas(new.bank_concept);
  new.clean_concept := public._bank_ocultar_tarjetas(new.clean_concept);
  new.document_no := public._bank_ocultar_tarjetas(new.document_no);
  new.reference_1 := public._bank_ocultar_tarjetas(new.reference_1);
  new.reference_2 := public._bank_ocultar_tarjetas(new.reference_2);
  new.fingerprint := public._bank_ocultar_tarjetas(new.fingerprint);
  return new;
end $$;


--
-- Name: _bank_ocultar_tarjetas(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_ocultar_tarjetas(p text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare v_t text; r text := p;
begin
  if p is null or p !~ '[0-9]{15}' then return p; end if;
  for v_t in select distinct x[1] from regexp_matches(p, '(?<![0-9])([0-9]{15,19})(?![0-9])', 'g') x loop
    if public._bank_parece_tarjeta(v_t) then
      r := regexp_replace(r, '(?<![0-9])' || v_t || '(?![0-9])', '····' || right(v_t, 4), 'g');
    end if;
  end loop;
  return r;
end $$;


--
-- Name: FUNCTION _bank_ocultar_tarjetas(p text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._bank_ocultar_tarjetas(p text) IS 'B01 (15/10, criterio de la 0192). Deja solo las 4 últimas («····1234») de cada tira de 15 a 19 cifras que empieza como Visa, Mastercard o Amex y pasa Luhn. La usa el disparador bank_movement_sin_tarjetas.';


--
-- Name: _bank_parece_tarjeta(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_parece_tarjeta(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select p ~ '^[0-9]{15,19}$'
     and (p ~ '^4' or p ~ '^5[1-5]' or left(p, 4)::int between 2221 and 2720 or p ~ '^3[47]')
     and public._bank_pasa_luhn(p)
$_$;


--
-- Name: _bank_pasa_luhn(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_pasa_luhn(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select p ~ '^[0-9]{13,19}$' and (
    select sum(case when (length(p) - i) % 2 = 1 then (case when d * 2 > 9 then d * 2 - 9 else d * 2 end) else d end) % 10 = 0
      from (select i, substr(p, i, 1)::int d from generate_series(1, length(p)) i) q)
$_$;


--
-- Name: _bank_regla_corregida(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bank_regla_corregida(p_rule uuid, p_movement uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.bank_rule; v_n integer;
begin
  select * into v from public.bank_rule where id = p_rule for update;
  if v.id is null then return; end if;
  v_n := coalesce(v.corrections, 0) + 1;
  update public.bank_rule set corrections = v_n, updated_at = now() where id = p_rule;
  insert into public.bank_rule_log (account_id, rule_id, action, before, after, created_by, created_by_name)
  values (v.account_id, p_rule, 'cambiada', jsonb_build_object('correcciones', v_n - 1), jsonb_build_object('correcciones', v_n, 'movimiento', p_movement),
          auth.uid(), public.conta_nombre_actor());
  if v_n >= 2 and v.status = 'activa' then
    update public.bank_rule set status = 'apagada', updated_at = now() where id = p_rule;
    insert into public.bank_rule_log (account_id, rule_id, action, before, after, created_by, created_by_name)
    values (v.account_id, p_rule, 'apagada', jsonb_build_object('estado', 'activa'), jsonb_build_object('estado', 'apagada', 'por', 'dos correcciones'),
            null, 'Folvy');
    perform public._bank_log(v.account_id, v.company_id, p_movement, null, null, 'regla', 'folvy',
      'He apagado la regla «' || v.words || '»: la has corregido dos veces. Puedes volver a encenderla en Reglas.',
      jsonb_build_object('regla', p_rule, 'correcciones', v_n));
  end if;
end $$;


--
-- Name: _batch_yield_in_base(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._batch_yield_in_base(p_item_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item  recipe_item%ROWTYPE;
  v_base  kitchen_unit%ROWTYPE;
  v_yield numeric;
BEGIN
  IF p_item_id IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- (a) DECLARADO: se normaliza a la unidad base del ítem.
  IF v_item.batch_yield IS NOT NULL AND v_item.batch_yield > 0 THEN
    v_yield := public._qty_in_base(
                 p_item_id,
                 v_item.batch_yield,
                 COALESCE(v_item.batch_yield_unit_id, v_item.base_unit_id));
    IF v_yield IS NOT NULL AND v_yield > 0 THEN
      RETURN v_yield;
    END IF;
    RETURN NULL;
  END IF;

  -- (b) AUTO-YIELD: suma de las líneas medibles EN LA UNIDAD BASE DEL PADRE.
  SELECT * INTO v_base FROM kitchen_unit WHERE id = v_item.base_unit_id;
  IF v_base.id IS NULL THEN RETURN NULL; END IF;

  SELECT SUM(COALESCE(rl.quantity_gross, rl.quantity_net)
             * lu.factor_to_base / v_base.factor_to_base)
    INTO v_yield
  FROM recipe_line rl
  JOIN kitchen_unit lu ON lu.id = rl.unit_id
  WHERE rl.parent_item_id = p_item_id
    AND lu.dimension = v_base.dimension;

  IF v_yield IS NOT NULL AND v_yield > 0 THEN
    RETURN v_yield;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION _batch_yield_in_base(p_item_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._batch_yield_in_base(p_item_id uuid) IS 'Rendimiento del batch expresado en la unidad base del ítem. Declarado (batch_yield + su unidad, normalizado con _qty_in_base) o automático (suma de las líneas medibles en esa base). NULL = sin rendimiento aplicable.';


--
-- Name: _build_test_ticket(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._build_test_ticket(p_name text, p_ip text, p_port integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'title', 'PRUEBA',
    'widthMm', 80,
    'blocks', jsonb_build_array(
      jsonb_build_object('kind','banner','text','PRUEBA'),
      jsonb_build_object('kind','text','text','Folvy','align','center','size',2,'bold',true),
      jsonb_build_object('kind','rule'),
      jsonb_build_object('kind','row','left','Impresora','right', coalesce(p_name,'-')),
      jsonb_build_object('kind','row','left','IP','right',
        coalesce(p_ip,'-') || ':' || coalesce(p_port, 9100)::text),
      jsonb_build_object('kind','row','left','Hora','right',
        to_char(now() at time zone 'Europe/Madrid', 'DD/MM HH24:MI:SS')),
      jsonb_build_object('kind','space','lines',1),
      jsonb_build_object('kind','text','text','Si ves este ticket, la impresora esta conectada.','align','center'),
      jsonb_build_object('kind','cut')
    )
  );
$$;


--
-- Name: _certificado_paso(text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._certificado_paso(p_nombre text, p_hora timestamp with time zone, p_fuente text, p_nota text DEFAULT NULL::text, p_fuerza text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  -- `jsonb_strip_nulls` es lo que cumple la regla dura: una clave sin valor
  -- desaparece en vez de imprimirse en blanco. `hora_madrid` nula solo ocurre
  -- cuando el estado ya dice «no_disponible» y la nota explica por que.
  select jsonb_strip_nulls(jsonb_build_object(
    'paso',        p_nombre,
    'fuente',      p_fuente,
    'estado',      case when p_hora is null then 'no_disponible' else 'ok' end,
    'hora_madrid', case when p_hora is null then null
                        else to_char(p_hora at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI:SS') end,
    'hora_utc',    case when p_hora is null then null
                        else to_char(p_hora at time zone 'UTC', 'DD/MM/YYYY HH24:MI:SS') || ' UTC' end,
    'fuerza',      p_fuerza,
    'nota',        p_nota));
$$;


--
-- Name: FUNCTION _certificado_paso(p_nombre text, p_hora timestamp with time zone, p_fuente text, p_nota text, p_fuerza text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._certificado_paso(p_nombre text, p_hora timestamp with time zone, p_fuente text, p_nota text, p_fuerza text) IS 'C9 L3 §5: un paso del certificado. Da la hora en Madrid (regla 4) y en UTC etiquetada. Sin hora -> «no_disponible» con motivo; sin nota -> la clave no aparece, nunca en blanco.';


--
-- Name: _clock_audit_conformidad(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clock_audit_conformidad() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_peticion text := nullif(current_setting('app.clock_peticion_id', true), '');
begin
  if new.action in ('create_manual', 'edit', 'void', 'restore') then
    if v_peticion is not null then
      new.peticion_id := v_peticion::uuid;
    elsif auth.uid() is not null
      and new.employee_id is not null
      and not public.current_user_is_employee(new.employee_id, new.account_id) then
      new.conformidad := 'pendiente';
    end if;
  end if;
  return new;
end $$;


--
-- Name: _clock_entry_audit_alta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clock_entry_audit_alta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_up public.user_profiles; v_propia boolean; v_motivo text;
begin
  if exists (select 1 from public.clock_entry_audit a where a.clock_entry_id = new.id and a.action in ('create', 'create_manual')) then
    return null;
  end if;
  if auth.uid() is not null then
    select * into v_up from public.user_profiles up
     where up.user_id = auth.uid() and up.account_id = new.account_id and up.active
     order by (up.employee_id = new.employee_id) desc nulls last limit 1;
  end if;
  v_propia := v_up.employee_id is not null and v_up.employee_id = new.employee_id;
  v_motivo := case
    when auth.uid() is null then 'Alta desde el servidor'
    when v_propia then 'Fichaje propio'
    else coalesce(nullif(current_setting('app.clock_edit_reason', true), ''), nullif(new.address, ''), 'Marca para otra persona, sin motivo escrito')
  end;
  insert into public.clock_entry_audit (clock_entry_id, employee_id, account_id, action, actor_user_id, actor_employee_id, actor_label, reason, before, after)
  values (new.id, new.employee_id, new.account_id, 'create', auth.uid(), v_up.employee_id,
          coalesce(v_up.role, case when auth.uid() is null then 'servidor' else 'sin perfil' end),
          v_motivo, null,
          public._clock_snapshot(new) || jsonb_build_object(
            'via', coalesce(new.source, 'sin origen'),
            'para_otra_persona', not v_propia,
            'hora_servidor', now()));
  return null;
end $$;


--
-- Name: _clock_entry_quien_y_hora(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clock_entry_quien_y_hora() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  -- fichar() ya ha comprobado quién y ha puesto la hora (L1a).
  if coalesce(current_setting('app.fichar', true), '') = 'on' then return new; end if;
  -- El servidor (funciones con la clave de servicio, SQL) no pasa por aquí.
  if auth.uid() is null then return new; end if;
  v_cuenta := coalesce(new.account_id, (select e.account_id from public.employees e where e.id = new.employee_id));
  -- El administrador y el encargado pueden poner una marca a otra persona
  -- (kiosko, ficha, correcciones): deja rastro en la auditoría (abajo).
  if public.current_user_is_admin_or_manager_of(v_cuenta) then return new; end if;
  -- El trabajador, solo para sí mismo.
  if not public.current_user_is_employee(new.employee_id, v_cuenta) then
    raise exception 'NO_AUTORIZADO: solo puedes fichar por ti'
      using hint = 'Solo puedes fichar por ti. Si hay que corregir el fichaje de otra persona, lo hace el encargado.', errcode = '42501';
  end if;
  if coalesce(new.source, '') = 'manual' then
    raise exception 'NO_AUTORIZADO: una marca puesta a mano la pone el encargado'
      using hint = 'Para corregir un fichaje, pide la corrección desde «Mis fichajes».', errcode = '42501';
  end if;
  -- La hora es la del servidor. La «efectiva» (redondeada al turno) se respeta
  -- solo si cae a menos de 30 min de ahora; si no, también es la del servidor.
  new.real_datetime := now();
  if new.datetime is null or abs(extract(epoch from (new.datetime - now()))) > 1800 then
    new.datetime := now();
  end if;
  return new;
end $$;


--
-- Name: clock_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clock_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    type text NOT NULL,
    datetime timestamp with time zone DEFAULT now() NOT NULL,
    real_datetime timestamp with time zone,
    lat double precision,
    lng double precision,
    address text,
    scheduled text,
    rounding_applied boolean DEFAULT false,
    diff_minutes integer,
    source text DEFAULT 'manual'::text,
    location_id_at_clock uuid,
    photo_data_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    voided boolean DEFAULT false NOT NULL,
    account_id uuid NOT NULL,
    break_attested boolean,
    break_attest_reason text,
    stale_prev_open_at timestamp with time zone,
    distance_m integer,
    within_radius boolean,
    declared_at timestamp with time zone,
    ubicacion_borrada_at timestamp with time zone,
    anonimizado_at timestamp with time zone,
    CONSTRAINT clock_entries_source_check CHECK ((source = ANY (ARRAY['kiosko'::text, 'movil'::text, 'tablet'::text, 'manual'::text]))),
    CONSTRAINT clock_entries_type_check CHECK ((type = ANY (ARRAY['entrada'::text, 'salida'::text, 'pausa_inicio'::text, 'pausa_fin'::text])))
);


--
-- Name: COLUMN clock_entries.break_attested; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clock_entries.break_attested IS 'F1.5 Atestacion: el trabajador confirma al fichar salida si disfruto su descanso. NULL = no preguntado.';


--
-- Name: COLUMN clock_entries.stale_prev_open_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clock_entries.stale_prev_open_at IS 'Si este fichaje es una ENTRADA aceptada habiendo otra jornada abierta y RANCIA (>= 12 h), aqui queda cuando empezo esa jornada anterior. Deja rastro de que se olvido una salida sin tocar la fila vieja. NULL = el caso normal.';


--
-- Name: COLUMN clock_entries.distance_m; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clock_entries.distance_m IS 'L1a: metros entre el móvil y el local al fichar. Se queda cuando se borran las coordenadas (a los 3 meses).';


--
-- Name: COLUMN clock_entries.within_radius; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clock_entries.within_radius IS 'L1a: si el fichaje cayó dentro del radio del local. Null: sin ubicación, o el local sin coordenadas.';


--
-- Name: COLUMN clock_entries.declared_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clock_entries.declared_at IS 'L1a: la hora del móvil cuando se fichó sin cobertura (hora declarada). created_at es la hora en que llegó al servidor; el informe enseña las dos.';


--
-- Name: COLUMN clock_entries.ubicacion_borrada_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clock_entries.ubicacion_borrada_at IS 'L1a: cuándo se borraron las coordenadas (conservación: 3 meses).';


--
-- Name: COLUMN clock_entries.anonimizado_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clock_entries.anonimizado_at IS 'L1a: cuándo se anonimizó la marca (conservación: 4 años).';


--
-- Name: CONSTRAINT clock_entries_source_check ON clock_entries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT clock_entries_source_check ON public.clock_entries IS 'L00 (27/10/2026). movil = portal del trabajador; tablet = kiosko del local; manual = puesto a mano; kiosko = filas anteriores al 27/10/2026, tablet o móvil sin distinguir.';


--
-- Name: _clock_snapshot(public.clock_entries); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clock_snapshot(r public.clock_entries) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  select jsonb_build_object(
    'id', r.id, 'type', r.type, 'datetime', r.datetime, 'real_datetime', r.real_datetime,
    'source', r.source, 'address', r.address, 'scheduled', r.scheduled,
    'rounding_applied', r.rounding_applied, 'diff_minutes', r.diff_minutes,
    'location_id_at_clock', r.location_id_at_clock, 'voided', r.voided
  )
$$;


--
-- Name: _close_inventory_count_core(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._close_inventory_count_core(p_count_id uuid) RETURNS TABLE(lines_total integer, lines_counted integer, lines_ok integer, lines_out integer, lines_uncounted integer, total_variance_value numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_location_id uuid;
  v_status text;
  v_tol_a numeric; v_tol_b numeric; v_tol_c numeric;
BEGIN
  SELECT account_id, location_id, status INTO v_account_id, v_location_id, v_status
    FROM public.inventory_count WHERE id = p_count_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'close_inventory_count: conteo % no existe', p_count_id;
  END IF;

  -- Las guardas de cuenta y de asignación viven en close_inventory_count.

  IF v_status NOT IN ('abierto', 'contando', 'en_revision') THEN
    RAISE EXCEPTION 'close_inventory_count: el conteo está en % y no se puede cerrar', v_status;
  END IF;

  PERFORM public.rebase_count_system_qty(p_count_id);

  SELECT COALESCE(tol_a_pct,2), COALESCE(tol_b_pct,3), COALESCE(tol_c_pct,5)
    INTO v_tol_a, v_tol_b, v_tol_c
    FROM public.supply_settings WHERE account_id = v_account_id;
  v_tol_a := COALESCE(v_tol_a,2); v_tol_b := COALESCE(v_tol_b,3); v_tol_c := COALESCE(v_tol_c,5);

  UPDATE public.inventory_count_line l
  SET
    variance_qty = l.counted_qty - l.system_qty,
    variance_pct = CASE WHEN COALESCE(l.system_qty,0) <> 0
                        THEN (l.counted_qty - l.system_qty) / l.system_qty * 100
                        ELSE NULL END,
    -- CAMBIO 10/09: sin coste fiable, NULL. Nunca 0 callado.
    variance_value = (l.counted_qty - l.system_qty) * ril.avg_unit_cost,
    within_tolerance = CASE
      WHEN l.counted_qty IS NULL THEN NULL
      WHEN COALESCE(l.system_qty,0) = 0 THEN (l.counted_qty = 0)
      ELSE abs((l.counted_qty - l.system_qty) / l.system_qty * 100) <=
           CASE l.abc_class WHEN 'A' THEN v_tol_a WHEN 'B' THEN v_tol_b ELSE v_tol_c END
    END
  FROM public.recipe_item_location_stock ril
  WHERE l.inventory_count_id = p_count_id
    AND ril.recipe_item_id = l.recipe_item_id
    AND ril.location_id = v_location_id
    AND ril.account_id = v_account_id;

  -- Sin fila de stock del artículo en el local: no hay con qué valorar. NULL,
  -- que es lo que es, y la pantalla lo dirá con palabras.
  UPDATE public.inventory_count_line l
  SET
    variance_qty = l.counted_qty - l.system_qty,
    variance_pct = CASE WHEN COALESCE(l.system_qty,0) <> 0
                        THEN (l.counted_qty - l.system_qty) / l.system_qty * 100
                        ELSE NULL END,
    variance_value = NULL,
    within_tolerance = CASE
      WHEN l.counted_qty IS NULL THEN NULL
      WHEN COALESCE(l.system_qty,0) = 0 THEN (l.counted_qty = 0)
      ELSE abs((l.counted_qty - l.system_qty) / l.system_qty * 100) <=
           CASE l.abc_class WHEN 'A' THEN v_tol_a WHEN 'B' THEN v_tol_b ELSE v_tol_c END
    END
  WHERE l.inventory_count_id = p_count_id
    AND l.counted_qty IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.recipe_item_location_stock ril
      WHERE ril.recipe_item_id = l.recipe_item_id
        AND ril.location_id = v_location_id AND ril.account_id = v_account_id
    );

  -- SANEAMIENTO: si el sistema estaba en NEGATIVO, el conteo lo corrige pero NO
  -- es merma del período: variación económica 0 y dentro de tolerancia.
  UPDATE public.inventory_count_line l
  SET variance_value = 0,
      within_tolerance = true
  WHERE l.inventory_count_id = p_count_id
    AND l.counted_qty IS NOT NULL
    AND COALESCE(l.system_qty, 0) < 0;

  -- LA APERTURA NO CALCULA DIFERENCIAS (10/09, noche): NULL y no cero, y va
  -- el último a propósito para que el saneamiento de arriba no lo pise.
  UPDATE public.inventory_count_line l
     SET variance_qty      = NULL,
         variance_pct      = NULL,
         variance_value    = NULL,
         within_tolerance  = NULL
    FROM public.inventory_count ic
   WHERE ic.id = p_count_id
     AND l.inventory_count_id = p_count_id
     AND COALESCE(ic.is_opening, false);

  UPDATE public.inventory_count
    SET status = 'en_revision', closed_at = now(), updated_at = now()
    WHERE id = p_count_id;

  RETURN QUERY
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE counted_qty IS NOT NULL)::integer,
    COUNT(*) FILTER (WHERE counted_qty IS NOT NULL AND within_tolerance = true)::integer,
    COUNT(*) FILTER (WHERE counted_qty IS NOT NULL AND within_tolerance = false)::integer,
    COUNT(*) FILTER (WHERE counted_qty IS NULL)::integer,
    COALESCE(SUM(variance_value) FILTER (WHERE counted_qty IS NOT NULL), 0)
  FROM public.inventory_count_line
  WHERE inventory_count_id = p_count_id;
END;
$$;


--
-- Name: _cocina_en_calma(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cocina_en_calma(p_location_id uuid, p_quiet_minutes integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pending_jobs  integer := 0;
  v_active_orders integer := 0;
  v_last_sale_min integer;
  v_quiet         integer := greatest(0, coalesce(p_quiet_minutes, 20));
  v_reasons       text[] := '{}';
begin
  select count(*) into v_pending_jobs
    from print_job j
   where j.location_id = p_location_id
     and ((j.status = 'pending' and j.created_at > now() - interval '2 hours')
       or (j.status = 'sent' and j.sent_at > now() - interval '60 minutes'));

  select count(*) into v_active_orders
    from sale s
   where s.location_id = p_location_id
     and s.order_status is not null
     and s.order_status not in ('completed', 'cancelled')
     and s.created_at > now() - interval '12 hours';

  select floor(extract(epoch from (now() - max(s.created_at))) / 60)::int
    into v_last_sale_min
    from sale s
   where s.location_id = p_location_id
     and s.created_at > now() - interval '24 hours';

  if v_pending_jobs > 0 then
    v_reasons := array_append(v_reasons, 'trabajos_de_impresion_vivos');
  end if;
  if v_active_orders > 0 then
    v_reasons := array_append(v_reasons, 'pedidos_en_curso');
  end if;
  if v_last_sale_min is not null and v_last_sale_min < v_quiet then
    v_reasons := array_append(v_reasons, 'venta_reciente');
  end if;

  return jsonb_build_object(
    'safe',               (array_length(v_reasons, 1) is null),
    'reasons',            to_jsonb(v_reasons),
    'pending_jobs',       v_pending_jobs,
    'active_orders',      v_active_orders,
    'minutes_since_sale', v_last_sale_min,
    'quiet_minutes',      v_quiet);
end;
$$;


--
-- Name: FUNCTION _cocina_en_calma(p_location_id uuid, p_quiet_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._cocina_en_calma(p_location_id uuid, p_quiet_minutes integer) IS 'Segunda llave: ¿está la cocina de este local en calma? Es la guarda de siempre, sacada aparte para que la oficina pregunte lo mismo que decide la tablet.';


--
-- Name: _compras_base_recepcion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_base_recepcion(p_recepcion uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select case when jsonb_typeof(a.parsed_result->'document'->'tax_base_total') = 'number' then (a.parsed_result->'document'->>'tax_base_total')::numeric end
       from goods_receipt g join goods_receipt_ai_session a on a.id = g.ai_session_id where g.id = p_recepcion),
    (select sum((l->>'line_amount')::numeric)
       from goods_receipt g join goods_receipt_ai_session a on a.id = g.ai_session_id,
            jsonb_array_elements(coalesce(a.parsed_result->'lines', '[]'::jsonb)) l
      where g.id = p_recepcion and jsonb_typeof(l->'line_amount') = 'number'),
    (select round(sum(gl.qty_received * gl.unit_cost), 2) from goods_receipt_line gl
      where gl.goods_receipt_id = p_recepcion and gl.unit_cost is not null and gl.qty_received is not null))
$$;


--
-- Name: _compras_camino_calcula(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_camino_calcula(p_recepcion uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  g goods_receipt; s supplier; sp supplier; d record; v_doc jsonb; v_tipo text; v_nombre text; v_nif text;
  v_unica uuid; v_es_factura boolean; v_path text; v_company uuid; v_sup uuid; v_how text;
  v_q text; v_qd jsonb; v_reason text; v_modo text; v_sugerida text; v_papel text;
  c_modo constant jsonb := '{"per_delivery": "con cada entrega", "delivery_note_then_invoice": "entrega con albarán y factura después", "monthly_settlement": "liquidación mensual"}';
begin
  select * into g from goods_receipt where id = p_recepcion;
  if g.id is null then raise exception 'Esa recepción no existe.' using errcode = 'P0002'; end if;
  if g.status = 'anulado' then
    return jsonb_build_object('path', 'anulada', 'supplier_id', g.supplier_id, 'reason', 'La recepción está anulada.');
  end if;
  select * into s from supplier where id = g.supplier_id;
  v_modo := s.invoicing_mode;
  v_unica := (select case when count(*) = 1 then min(c.id::text)::uuid end from company c where c.account_id = g.account_id and c.is_active);
  select a.parsed_result->'document' into v_doc from goods_receipt_ai_session a where a.id = g.ai_session_id;
  v_tipo := nullif(v_doc->>'doc_type', '');
  v_nombre := nullif(btrim(v_doc->>'bill_to_name'), '');
  v_nif := nullif(btrim(v_doc->>'bill_to_tax_id'), '');
  v_sup := g.supplier_id;

  if s.id is null then
    v_path := 'sin_decidir'; v_how := 'ficha'; v_q := 'sin_papel';
    v_reason := 'La recepción no tiene proveedor: no se sabe cómo factura.';
  elsif v_tipo is null then
    -- Sin papel leído: manda la ficha.
    v_how := 'ficha'; v_company := v_unica;
    if v_modo = 'monthly_settlement' then
      v_path := 'liquidacion'; v_reason := format('No hay documento leído; %s liquida cada mes.', s.name);
    elsif v_modo = 'delivery_note_then_invoice' then
      v_path := 'pendiente_factura'; v_reason := format('No hay documento leído; %s manda la factura después.', s.name);
    else
      v_path := 'pendiente_factura'; v_q := 'sin_papel';
      v_reason := case when v_modo = 'per_delivery'
        then format('No hay documento leído y %s factura con cada entrega: sube su factura.', s.name)
        else format('No hay documento leído y no se sabe cómo factura %s: queda pendiente de factura.', s.name) end;
    end if;
  else
    v_es_factura := v_tipo in ('factura', 'albaran_factura');
    v_papel := case v_tipo when 'albaran' then 'un albarán' when 'factura' then 'una factura' when 'albaran_factura' then 'un albarán-factura' else 'otro documento' end;
    select * into d from public._compras_destinatario(g.account_id, v_nombre, v_nif);
    v_how := d.how;
    if d.kind = 'empresa' then
      v_company := d.company_id;
      v_sugerida := case when v_es_factura then 'per_delivery' else 'delivery_note_then_invoice' end;
      if v_modo is null then
        -- S01c: sin ficha, decide el papel y se pregunta (el disparador no crea nada con la pregunta abierta).
        v_path := case when v_es_factura then 'factura' else 'pendiente_factura' end;
        v_reason := case when v_es_factura then 'Es una factura a nombre de tu empresa. La ficha no dice cómo factura: dímelo y la apunto.'
                         else 'Es un albarán a nombre de tu empresa: queda pendiente de factura.' end;
        v_q := 'ficha_sin_forma';
      elsif v_modo = 'per_delivery' then
        v_path := case when v_es_factura then 'factura' else 'pendiente_factura' end;
        v_reason := case when v_es_factura then 'Es una factura a nombre de tu empresa.'
                         when s.invoice_arrival = 'inicio_mes_siguiente'
                         then format('%s hace una factura por entrega y las manda todas juntas a primeros del mes siguiente: queda pendiente de su factura.', s.name)
                         else format('%s factura con cada entrega y esto es un albarán: queda pendiente de su factura.', s.name) end;
        -- Con sus facturas a primeros de mes, el albarán de la entrega es lo normal: no se pregunta.
        if not v_es_factura and s.invoice_arrival is distinct from 'inicio_mes_siguiente' then v_q := 'papel_y_ficha'; end if;
      elsif v_modo = 'delivery_note_then_invoice' then
        -- S01c: manda la ficha. Lo que el papel diga no crea ninguna factura.
        v_path := 'pendiente_factura';
        v_reason := case when v_es_factura
          then format('%s factura aparte; este papel es el albarán (se leyó como %s). Queda pendiente de su factura.', s.name, v_papel)
          else 'Es un albarán a nombre de tu empresa: queda pendiente de factura.' end;
        if v_es_factura then v_q := 'papel_y_ficha'; end if;
      else
        v_path := 'liquidacion'; v_company := coalesce(v_company, v_unica);
        v_reason := format('%s liquida cada mes: entra en su liquidación%s.', s.name,
                           case when v_es_factura then format(' (el papel se leyó como %s)', v_papel) else '' end);
        if v_es_factura then v_q := 'papel_y_ficha'; v_sugerida := null; end if;
      end if;
      if v_q = 'papel_y_ficha' then
        v_qd := jsonb_build_object('ficha', v_modo, 'ficha_dice', c_modo->>v_modo, 'papel', v_tipo, 'sugerida', v_sugerida, 'sugerida_dice', c_modo->>v_sugerida, 'manda', 'ficha');
      elsif v_q = 'ficha_sin_forma' then
        v_qd := jsonb_build_object('ficha', null, 'papel', v_tipo, 'sugerida', v_sugerida, 'sugerida_dice', c_modo->>v_sugerida);
      end if;
    elsif d.kind = 'proveedor' then
      select * into sp from supplier where id = d.supplier_id;
      if sp.invoicing_mode = 'monthly_settlement' then
        v_path := 'liquidacion'; v_sup := sp.id; v_company := v_unica;
        v_reason := case when sp.id = s.id then format('Va a nombre de %s, que liquida cada mes: entra en su liquidación.', sp.name)
                         else format('Lo trae %s a nombre de %s, que liquida cada mes: entra en su liquidación.', s.name, sp.name) end;
      elsif sp.invoicing_mode is null then
        v_path := 'sin_decidir'; v_q := 'a_nombre_de';
        v_reason := format('Va a nombre de %s, y su ficha no dice si liquida cada mes.', sp.name);
        v_qd := jsonb_build_object('nombre', v_nombre, 'nombre_norm', public.compras_nombre_norm(v_nombre), 'proveedor', sp.id, 'proveedor_nombre', sp.name);
      else
        v_path := 'a_nombre_de_otro'; v_q := 'a_nombre_de_otro'; v_sup := g.supplier_id;
        v_reason := format('Va a nombre de %s, no de tu empresa: así no se puede deducir el IVA.', sp.name);
      end if;
    elsif d.kind = 'otro' then
      v_path := 'a_nombre_de_otro'; v_q := 'a_nombre_de_otro';
      v_reason := format('Va a nombre de «%s», no de tu empresa: así no se puede deducir el IVA.', v_nombre);
    else
      v_path := 'sin_decidir'; v_q := 'a_nombre_de';
      v_reason := format(case when v_nombre is null then '%s no dice a nombre de quién va.'
                              else '%s va a nombre de «%s», y Folvy no sabe quién es.' end,
                         case v_tipo when 'albaran' then 'El albarán' when 'factura' then 'La factura'
                                     when 'albaran_factura' then 'El albarán-factura' else 'El documento' end,
                         v_nombre);
      v_qd := jsonb_build_object('nombre', v_nombre, 'nombre_norm', public.compras_nombre_norm(v_nombre),
        'candidatos', (select coalesce(jsonb_agg(x order by x->>'orden', x->>'nombre'), '[]'::jsonb) from (
          select jsonb_build_object('tipo', 'empresa', 'id', c.id, 'nombre', coalesce(c.legal_name, c.trade_name),
                   'orden', case when split_part(public.compras_nombre_norm(coalesce(c.legal_name, c.trade_name)), ' ', 1) = split_part(public.compras_nombre_norm(v_nombre), ' ', 1) then '0' else '1' end) x
            from company c where c.account_id = g.account_id and c.is_active
          union all
          select jsonb_build_object('tipo', 'proveedor', 'id', p.id, 'nombre', p.name,
                   'orden', case when split_part(public.compras_nombre_norm(p.name), ' ', 1) = split_part(public.compras_nombre_norm(v_nombre), ' ', 1) then '0' else '1' end)
            from supplier p where p.account_id = g.account_id and p.archived_at is null
             and (p.invoicing_mode = 'monthly_settlement' or p.id = g.supplier_id)) y));
    end if;
  end if;

  return jsonb_build_object('path', v_path, 'supplier_id', v_sup, 'company_id', v_company, 'doc_type', v_tipo,
    'bill_to_name', v_nombre, 'bill_to_tax_id', v_nif, 'bill_to_how', v_how,
    'question', v_q, 'question_detail', v_qd, 'reason', v_reason);
end $$;


--
-- Name: _compras_camino_guarda(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_camino_guarda(p_recepcion uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb; v_cuenta uuid; p goods_receipt_path;
begin
  select account_id into v_cuenta from goods_receipt where id = p_recepcion;
  select * into p from goods_receipt_path where goods_receipt_id = p_recepcion;
  if p.consumed_at is not null then
    -- 0350: ya la usó una factura, un casado o una liquidación, y el camino no
    -- se vuelve a decidir. Pero las preguntas que salen de la ficha sí: si la
    -- ficha cambió, la de antes ya no es verdad.
    if p.question in ('ficha_sin_forma', 'papel_y_ficha') then
      v := public._compras_camino_calcula(p_recepcion);
      if v->>'question' is null or v->>'question' in ('ficha_sin_forma', 'papel_y_ficha') then
        update goods_receipt_path set question = v->>'question', question_detail = nullif(v->'question_detail', 'null'::jsonb)
         where id = p.id
           and (question, question_detail) is distinct from (v->>'question', nullif(v->'question_detail', 'null'::jsonb));
      end if;
    end if;
    return null;
  end if;
  v := public._compras_camino_calcula(p_recepcion);
  insert into goods_receipt_path (account_id, goods_receipt_id, path, supplier_id, company_id, doc_type, bill_to_name, bill_to_tax_id,
                                  bill_to_how, question, question_detail, reason, error, decided_at)
  values (v_cuenta, p_recepcion, v->>'path', (v->>'supplier_id')::uuid, (v->>'company_id')::uuid, v->>'doc_type', v->>'bill_to_name',
          v->>'bill_to_tax_id', v->>'bill_to_how', v->>'question', nullif(v->'question_detail', 'null'::jsonb), v->>'reason', null, now())
  on conflict (goods_receipt_id) do update set
    path = excluded.path, supplier_id = excluded.supplier_id, company_id = excluded.company_id, doc_type = excluded.doc_type,
    bill_to_name = excluded.bill_to_name, bill_to_tax_id = excluded.bill_to_tax_id, bill_to_how = excluded.bill_to_how,
    question = excluded.question, question_detail = excluded.question_detail, reason = excluded.reason, error = null, decided_at = now();
  return v;
end $$;


--
-- Name: FUNCTION _compras_camino_guarda(p_recepcion uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._compras_camino_guarda(p_recepcion uuid) IS 'Compras. Decide y guarda el camino de una recepción. Si ya la usó una factura, un casado o una liquidación (consumed_at), el camino no se toca; solo se vuelven a mirar las preguntas que salen de la ficha (ficha_sin_forma, papel_y_ficha) — 0350, 21/10.';


--
-- Name: _compras_camino_rellena(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_camino_rellena(p_cuenta uuid, p_desde date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v_n int := 0;
begin
  for r in select g.id from goods_receipt g
            where g.account_id = p_cuenta and g.status = 'confirmado' and g.receipt_date >= p_desde
              and not exists (select 1 from goods_receipt_path p where p.goods_receipt_id = g.id)
            order by g.receipt_date, g.created_at loop
    perform public._compras_camino_guarda(r.id); v_n := v_n + 1;
  end loop;
  return jsonb_build_object('recepciones', v_n);
end $$;


--
-- Name: _compras_casar(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_casar(p_factura uuid, p_recepciones uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare f supplier_invoice; v_suma numeric; v_sin_base int; v_dif numeric; v_n int; v_base_factura numeric;
begin
  select * into f from supplier_invoice where id = p_factura for update;
  if f.id is null then raise exception 'Esa factura no existe.' using errcode = 'P0002'; end if;
  if f.status = 'anulada' then raise exception 'La factura está anulada.' using errcode = '22023'; end if;
  if exists (select 1 from unnest(p_recepciones) r(id)
              where not exists (select 1 from goods_receipt g join goods_receipt_path p on p.goods_receipt_id = g.id
                                 where g.id = r.id and g.account_id = f.account_id and g.supplier_id = f.supplier_id
                                   and p.path = 'pendiente_factura' and p.consumed_at is null)) then
    raise exception 'Alguna recepción no es de este proveedor o ya no está esperando factura.' using errcode = '22023';
  end if;
  insert into supplier_invoice_receipt (supplier_invoice_id, goods_receipt_id)
  select p_factura, r.id from unnest(p_recepciones) r(id) on conflict do nothing;
  update goods_receipt_path set supplier_invoice_id = p_factura, consumed_at = now()
   where goods_receipt_id = any(p_recepciones) and consumed_at is null;
  get diagnostics v_n = row_count;
  -- La diferencia: la base de la factura contra lo que suman TODAS sus recepciones.
  select coalesce(sum(public._compras_base_recepcion(x.goods_receipt_id)), 0), count(*) filter (where public._compras_base_recepcion(x.goods_receipt_id) is null)
    into v_suma, v_sin_base from supplier_invoice_receipt x where x.supplier_invoice_id = p_factura;
  v_base_factura := coalesce(f.tax_base_total, (select sum(line_amount) from supplier_invoice_line where supplier_invoice_id = p_factura), 0);
  v_dif := round(v_base_factura - v_suma, 2);
  update supplier_invoice set match_status = case when abs(v_dif) <= 0.02 and v_sin_base = 0 then 'ok' else 'con_diferencias' end, updated_at = now()
   where id = p_factura;
  return jsonb_build_object('factura', p_factura, 'casadas', v_n, 'base_factura', v_base_factura, 'base_recepciones', v_suma,
    'diferencia', v_dif, 'sin_base', v_sin_base,
    'frase', case when abs(v_dif) <= 0.02 and v_sin_base = 0 then format('Casa con %s recepción(es): la base es la misma (%s).', v_n, public.compras_euros(v_base_factura))
                  else format('Casada con %s recepción(es). La factura dice %s de base y las recepciones %s: %s de diferencia%s.',
                              v_n, public.compras_euros(v_base_factura), public.compras_euros(v_suma), public.compras_euros(v_dif),
                              case when v_sin_base > 0 then format(' (y %s sin importe)', v_sin_base) else '' end) end);
end $$;


--
-- Name: _compras_casar_solo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_casar_solo(p_factura uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  f supplier_invoice; s supplier; v_ids uuid[]; v_r jsonb; v_hueco numeric; v_texto text; v_alb text; v_n int;
  e text := 'FM999G999G990D00';
begin
  select * into f from supplier_invoice where id = p_factura;
  if f.id is null or f.supplier_id is null or f.status in ('anulada', 'descartada') or f.grand_total is null then return null; end if;
  if exists (select 1 from supplier_invoice_receipt where supplier_invoice_id = f.id) then return null; end if;
  select * into s from supplier where id = f.supplier_id;
  -- Los que esperan factura de este proveedor, recibidos hasta la fecha de la factura, con su total leído.
  create temp table if not exists _s01c_cand (id uuid, code text, doc text, fecha date, total numeric) on commit drop;
  delete from _s01c_cand where true;
  insert into _s01c_cand
  select g.id, g.code, g.supplier_doc_number, g.receipt_date, nullif(a.parsed_result->'document'->>'grand_total', '')::numeric
    from goods_receipt_path p join goods_receipt g on g.id = p.goods_receipt_id
    left join goods_receipt_ai_session a on a.id = g.ai_session_id
   where p.account_id = f.account_id and p.path = 'pendiente_factura' and p.consumed_at is null and g.status = 'confirmado'
     and g.supplier_id = f.supplier_id and g.receipt_date <= coalesce(f.invoice_date, current_date);
  -- a) Un albarán con el mismo total.
  select array_agg(id) into v_ids from _s01c_cand where abs(total - f.grand_total) < 0.005;
  if coalesce(array_length(v_ids, 1), 0) <> 1 then
    -- b) La factura del mes: los albaranes de su mes, si suman su total.
    select array_agg(id) into v_ids from _s01c_cand
     where date_trunc('month', fecha) = date_trunc('month', coalesce(f.invoice_date, current_date) - (case when extract(day from coalesce(f.invoice_date, current_date)) <= 10 then 15 else 0 end))
     having count(*) > 1 and count(total) = count(*) and abs(sum(total) - f.grand_total) < 0.005;
  end if;
  if coalesce(array_length(v_ids, 1), 0) = 0 then
    v_texto := format('Espera su albarán: no hay ningún albarán de %s esperando factura por %s €.', s.name, translate(to_char(f.grand_total, e), ',.', '.,'));
    insert into document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text, detail)
    values (f.account_id, f.company_id, f.inbox_id, f.id, 'folvy', 'propuesta', v_texto, jsonb_build_object('espera_albaran', true));
    return jsonb_build_object('casada', false, 'texto', v_texto);
  end if;
  v_r := public._compras_casar(f.id, v_ids);
  select string_agg(format('%s del %s', coalesce(c.doc, c.code), to_char(c.fecha, 'DD/MM')), ', ' order by c.fecha), count(*)
    into v_alb, v_n from _s01c_cand c where c.id = any(v_ids);
  -- Lo que el albarán tiene sin leer (su base contra lo que suman sus líneas leídas), si nadie dijo por qué.
  select coalesce(sum(coalesce(g.unread_gap_amount, greatest(coalesce((a.validation->>'base_declared')::numeric, 0) - coalesce((a.validation->>'lines_sum')::numeric, 0), 0))), 0)
    into v_hueco
    from goods_receipt g join goods_receipt_ai_session a on a.id = g.ai_session_id
   where g.id = any(v_ids) and coalesce((a.validation->>'cuadra')::boolean, true) = false and g.unread_gap_reason is null;
  v_texto := format('Casa con %s %s.', case when v_n = 1 then 'el albarán' else format('los %s albaranes', v_n) end, v_alb)
    || case when v_hueco >= 0.005 then format(' Difiere en %s €: el albarán tiene líneas sin leer.', translate(to_char(v_hueco, e), ',.', '.,'))
            when abs(coalesce((v_r->>'diferencia')::numeric, 0)) >= 0.005 then ' ' || (v_r->>'frase')
            else '' end;
  if v_hueco >= 0.005 then update supplier_invoice set match_status = 'con_diferencias' where id = f.id; end if;
  insert into document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text, detail)
  values (f.account_id, f.company_id, f.inbox_id, f.id, 'folvy', 'casada', v_texto,
          jsonb_build_object('recepciones', to_jsonb(v_ids), 'diferencia', v_r->'diferencia', 'lineas_sin_leer', v_hueco));
  return jsonb_build_object('casada', true, 'texto', v_texto, 'recepciones', to_jsonb(v_ids), 'lineas_sin_leer', v_hueco);
end $$;


--
-- Name: _compras_destinatario(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_destinatario(p_cuenta uuid, p_nombre text, p_nif text) RETURNS TABLE(kind text, company_id uuid, supplier_id uuid, how text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nif text := public.compras_nif_norm(p_nif); v_nom text := public.compras_nombre_norm(p_nombre);
        v_ids uuid[]; r purchase_bill_to;
begin
  if v_nif is not null then
    v_ids := array(select c.id from company c where c.account_id = p_cuenta and c.is_active and public.compras_nif_norm(c.tax_id) = v_nif);
    if cardinality(v_ids) = 1 then return query select 'empresa'::text, v_ids[1], null::uuid, 'nif'::text; return; end if;
    v_ids := array(select s.id from supplier s where s.account_id = p_cuenta and s.archived_at is null and public.compras_nif_norm(s.tax_id) = v_nif);
    if cardinality(v_ids) = 1 then return query select 'proveedor'::text, null::uuid, v_ids[1], 'nif'::text; return; end if;
  end if;
  if v_nom is null then
    return query select (case when v_nif is null then 'sin_dato' else 'desconocido' end)::text, null::uuid, null::uuid,
                        (case when v_nif is null then 'sin_dato' else 'desconocido' end)::text;
    return;
  end if;
  select * into r from purchase_bill_to b where b.account_id = p_cuenta and b.name_norm = v_nom;
  if r.id is not null then
    return query select (case when r.company_id is not null then 'empresa' when r.supplier_id is not null then 'proveedor' else 'otro' end)::text,
                        r.company_id, r.supplier_id, 'recordado'::text;
    return;
  end if;
  v_ids := array(select c.id from company c where c.account_id = p_cuenta and c.is_active
                   and v_nom in (public.compras_nombre_norm(c.legal_name), public.compras_nombre_norm(c.trade_name)));
  if cardinality(v_ids) = 1 then return query select 'empresa'::text, v_ids[1], null::uuid, 'nombre'::text; return; end if;
  if cardinality(v_ids) = 0 then
    v_ids := array(select s.id from supplier s where s.account_id = p_cuenta and s.archived_at is null
                     and v_nom in (public.compras_nombre_norm(s.name), public.compras_nombre_norm(s.legal_name)));
    if cardinality(v_ids) = 1 then return query select 'proveedor'::text, null::uuid, v_ids[1], 'nombre'::text; return; end if;
  end if;
  -- Repaso (10/10): «Contado», «Varios»… no es de nadie: no se pregunta, se avisa.
  if public.compras_nombre_generico(p_nombre) then
    return query select 'otro'::text, null::uuid, null::uuid, 'generico'::text; return;
  end if;
  return query select 'desconocido'::text, null::uuid, null::uuid, 'desconocido'::text;
end $$;


--
-- Name: _compras_destinatario_decide(uuid, text, uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_destinatario_decide(p_cuenta uuid, p_nombre text, p_empresa uuid, p_proveedor uuid, p_otro boolean, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nom text := public.compras_nombre_norm(p_nombre); v_n int := 0; r record;
begin
  if v_nom is null then raise exception 'Sin nombre no hay nada que recordar.' using errcode = '22023'; end if;
  if num_nonnulls(p_empresa, p_proveedor) + (case when coalesce(p_otro, false) then 1 else 0 end) <> 1 then
    raise exception 'Elige una: tu empresa, el proveedor o «otro».' using errcode = '22023';
  end if;
  if p_empresa is not null and not exists (select 1 from company where id = p_empresa and account_id = p_cuenta) then
    raise exception 'Esa empresa no es de esta cuenta.' using errcode = '42501';
  end if;
  if p_proveedor is not null and not exists (select 1 from supplier where id = p_proveedor and account_id = p_cuenta) then
    raise exception 'Ese proveedor no es de esta cuenta.' using errcode = '42501';
  end if;
  insert into purchase_bill_to (account_id, name_norm, example, company_id, supplier_id, is_other, decided_by, decided_by_name)
  values (p_cuenta, v_nom, p_nombre, p_empresa, p_proveedor, coalesce(p_otro, false), auth.uid(), coalesce(p_quien_nombre, public.conta_nombre_actor()))
  on conflict (account_id, name_norm) do update set
    example = excluded.example, company_id = excluded.company_id, supplier_id = excluded.supplier_id, is_other = excluded.is_other,
    decided_by = excluded.decided_by, decided_by_name = excluded.decided_by_name, decided_at = now();
  for r in select p.goods_receipt_id from goods_receipt_path p
            where p.account_id = p_cuenta and p.consumed_at is null and public.compras_nombre_norm(p.bill_to_name) = v_nom loop
    perform public._compras_camino_guarda(r.goods_receipt_id); v_n := v_n + 1;
  end loop;
  return jsonb_build_object('nombre', v_nom, 'recepciones', v_n);
end $$;


--
-- Name: _compras_factura_desde_papel(uuid, uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_factura_desde_papel(p_cuenta uuid, p_sesion uuid, p_proveedor uuid, p_local uuid, p_empresa uuid, p_recepcion uuid DEFAULT NULL::uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_doc jsonb; v_lineas jsonb; v_num text; v_fecha date; v_id uuid; v_ok int; v_total int;
  v_base numeric; v_cuota numeric; v_url text;
begin
  select a.parsed_result->'document', coalesce(a.parsed_result->'lines', '[]'::jsonb) into v_doc, v_lineas
    from goods_receipt_ai_session a where a.id = p_sesion and a.account_id = p_cuenta;
  if v_doc is null then raise exception 'Ese documento no está leído en esta cuenta.' using errcode = 'P0002'; end if;
  if not exists (select 1 from supplier where id = p_proveedor and account_id = p_cuenta) then
    raise exception 'Ese proveedor no es de esta cuenta.' using errcode = '42501';
  end if;

  v_num := nullif(btrim(v_doc->>'doc_number'), '');
  if v_num is null and p_recepcion is not null then
    select nullif(btrim(supplier_doc_number), '') into v_num from goods_receipt where id = p_recepcion;
  end if;
  begin v_fecha := (v_doc->>'doc_date')::date; exception when others then v_fecha := null; end;
  if v_fecha is null and p_recepcion is not null then select receipt_date into v_fecha from goods_receipt where id = p_recepcion; end if;
  v_fecha := coalesce(v_fecha, current_date);

  -- El mismo papel dos veces: mismo proveedor y mismo número, o la misma lectura.
  select si.id into v_id from supplier_invoice si
   where si.account_id = p_cuenta and si.status <> 'anulada'
     and (si.ai_session_id = p_sesion
          or (v_num is not null and si.supplier_id = p_proveedor
              and upper(regexp_replace(si.invoice_number, '[^A-Za-z0-9]', '', 'g')) = upper(regexp_replace(v_num, '[^A-Za-z0-9]', '', 'g'))))
   order by si.created_at limit 1;
  if v_id is not null then
    if p_recepcion is not null then
      insert into supplier_invoice_receipt (supplier_invoice_id, goods_receipt_id) values (v_id, p_recepcion) on conflict do nothing;
    end if;
    return jsonb_build_object('factura', v_id, 'creada', false, 'repetida', true,
      'motivo', format('Esta factura ya estaba (%s): se enlaza a ella, no se crea otra.', (select code from supplier_invoice where id = v_id)));
  end if;

  -- Importes: cada línea con su importe neto y su IVA.
  select count(*) filter (where jsonb_typeof(l->'line_amount') = 'number' and jsonb_typeof(l->'vat_pct') = 'number'), count(*)
    into v_ok, v_total from jsonb_array_elements(v_lineas) l;
  if v_total = 0 or v_ok < v_total then
    return jsonb_build_object('factura', null, 'creada', false, 'sin_importes', true,
      'motivo', case when v_total = 0 then 'El documento no trae líneas: sube la factura en Compras.'
                     else format('El documento trae %s línea(s) sin importe o sin IVA: sube la factura en Compras o complétala.', v_total - v_ok) end);
  end if;

  select sum((l->>'line_amount')::numeric), sum(round((l->>'line_amount')::numeric * (l->>'vat_pct')::numeric / 100, 2))
    into v_base, v_cuota from jsonb_array_elements(v_lineas) l;
  if p_recepcion is not null then select raw_document_url into v_url from goods_receipt where id = p_recepcion; end if;
  -- 0770: sin recepción, o con una recepción sin documento, el fichero que se
  -- leyó: el primero de su lectura, de esta misma cuenta (lo que la recepción
  -- guarda en goods_receipt.raw_document_url). «Subir una factura» no lo
  -- guardaba: FAC-00098 y FAC-00101 de Foodint (19 y 21/10) nacieron sin él.
  if v_url is null then
    select nullif(btrim(case when jsonb_typeof(a.input_files -> 0) = 'string' then a.input_files ->> 0
                             else a.input_files -> 0 ->> 'path' end), '')
      into v_url
      from goods_receipt_ai_session a
     where a.id = p_sesion and a.account_id = p_cuenta
       and jsonb_typeof(a.input_files) = 'array'
       and coalesce(a.input_files -> 0 ->> 'bucket', 'receipt-uploads') = 'receipt-uploads';
  end if;

  insert into supplier_invoice (account_id, supplier_id, location_id, company_id, doc_kind, invoice_number, invoice_date, status,
                                source, ai_session_id, raw_document_url, tax_base_total, tax_total, grand_total, needs_review,
                                notes, created_by, created_by_name)
  values (p_cuenta, p_proveedor, p_local, p_empresa, 'invoice', v_num, v_fecha, 'en_revision',
          'ocr', p_sesion, v_url,
          coalesce((v_doc->>'tax_base_total')::numeric, v_base), coalesce((v_doc->>'tax_total')::numeric, v_cuota),
          coalesce((v_doc->>'grand_total')::numeric, v_base + v_cuota),
          -- Lo que dice la cabecera contra lo que suman las líneas: si no cuadra, se revisa.
          abs(coalesce((v_doc->>'tax_base_total')::numeric, v_base) - v_base) > 0.02,
          case when p_recepcion is not null then 'Creada al confirmar la recepción ' || (select code from goods_receipt where id = p_recepcion) || '.' end,
          auth.uid(), coalesce(p_quien_nombre, public.conta_nombre_actor(), 'Folvy'))
  returning id into v_id;

  insert into supplier_invoice_line (supplier_invoice_id, raw_text, supplier_code, qty, unit_price, line_amount, vat_pct, position)
  select v_id, l->>'raw_text', nullif(l->>'supplier_code', ''),
         case when jsonb_typeof(l->'quantity') = 'number' then (l->>'quantity')::numeric end,
         case when jsonb_typeof(l->'unit_price_net') = 'number' then (l->>'unit_price_net')::numeric end,
         (l->>'line_amount')::numeric, (l->>'vat_pct')::numeric, (n - 1)::int
    from jsonb_array_elements(v_lineas) with ordinality as t(l, n);

  if p_recepcion is not null then
    insert into supplier_invoice_receipt (supplier_invoice_id, goods_receipt_id) values (v_id, p_recepcion) on conflict do nothing;
  end if;
  return jsonb_build_object('factura', v_id, 'creada', true, 'repetida', false,
    'motivo', format('Factura %s creada desde el documento: %s de base, %s de IVA.', coalesce(v_num, 'sin número'), public.compras_euros(v_base), public.compras_euros(v_cuota)));
end $$;


--
-- Name: purchase_accrual; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_accrual (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    supplier_id uuid NOT NULL,
    location_id uuid,
    month date NOT NULL,
    base numeric NOT NULL,
    receipts jsonb DEFAULT '[]'::jsonb NOT NULL,
    without_base integer DEFAULT 0 NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT purchase_accrual_mes CHECK ((month = (date_trunc('month'::text, (month)::timestamp with time zone))::date))
);


--
-- Name: TABLE purchase_accrual; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.purchase_accrual IS 'Compras (10/10). Lo recibido y no facturado al cierre de un mes, por proveedor y local: su base y de qué recepciones sale (receipts: id, código, fecha, base). Es el origen de los asientos purchase_accrual (fin de mes) y purchase_accrual_reversal (su contrario el día 1).';


--
-- Name: _compras_fin_de_mes(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_fin_de_mes(p_empresa uuid, p_mes date) RETURNS SETOF public.purchase_accrual
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid; v_ini date := date_trunc('month', p_mes)::date; v_fin date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date;
  v_corte date; v_unica boolean;
begin
  select account_id into v_cuenta from company where id = p_empresa;
  if v_cuenta is null then raise exception 'Esa empresa no existe.' using errcode = 'P0002'; end if;
  select max(imported_until) into v_corte from fiscal_year where company_id = p_empresa;
  v_unica := (select count(*) = 1 from company where account_id = v_cuenta and is_active);

  create temp table if not exists _fin_de_mes (supplier_id uuid, location_id uuid, receipts jsonb, base numeric, sin_base int) on commit drop;
  delete from _fin_de_mes where true;
  insert into _fin_de_mes
  select g.supplier_id, g.location_id,
         jsonb_agg(jsonb_build_object('id', g.id, 'code', g.code, 'fecha', g.receipt_date, 'base', public._compras_base_recepcion(g.id)) order by g.receipt_date, g.code),
         coalesce(sum(public._compras_base_recepcion(g.id)), 0), count(*) filter (where public._compras_base_recepcion(g.id) is null)::int
    from goods_receipt_path p join goods_receipt g on g.id = p.goods_receipt_id
    left join supplier_invoice si on si.id = p.supplier_invoice_id
   where p.account_id = v_cuenta and p.path = 'pendiente_factura' and g.status = 'confirmado'
     and (p.company_id = p_empresa or (p.company_id is null and v_unica))
     and g.receipt_date <= v_fin and (v_corte is null or g.receipt_date > v_corte)
     and (p.supplier_invoice_id is null or si.status = 'anulada' or si.invoice_date > v_fin)
   group by g.supplier_id, g.location_id;

  -- Lo que ya no está (se facturó dentro del mes) y no tiene asiento: fuera.
  delete from purchase_accrual a
   where a.company_id = p_empresa and a.month = v_ini
     and not exists (select 1 from _fin_de_mes x where x.supplier_id = a.supplier_id and x.location_id is not distinct from a.location_id)
     and not exists (select 1 from journal_entry e where e.company_id = p_empresa and e.source_type in ('purchase_accrual', 'purchase_accrual_reversal')
                      and e.source_id = a.id and e.status in ('propuesto', 'borrador', 'validado'));
  insert into purchase_accrual (account_id, company_id, supplier_id, location_id, month, base, receipts, without_base, computed_at)
  select v_cuenta, p_empresa, x.supplier_id, x.location_id, v_ini, x.base, x.receipts, x.sin_base, now() from _fin_de_mes x
  on conflict (company_id, supplier_id, location_id, month) do update set
    base = excluded.base, receipts = excluded.receipts, without_base = excluded.without_base, computed_at = now()
  where not exists (select 1 from journal_entry e where e.company_id = p_empresa and e.source_type = 'purchase_accrual'
                     and e.source_id = purchase_accrual.id and e.status = 'validado');
  return query select * from purchase_accrual where company_id = p_empresa and month = v_ini order by base desc;
end $$;


--
-- Name: _compras_forma_facturar(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_forma_facturar(p_proveedor uuid, p_modo text, p_por_local boolean, p_frecuencia text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n int := 0; r record; v_cuenta uuid;
begin
  select account_id into v_cuenta from supplier where id = p_proveedor;
  if v_cuenta is null then raise exception 'Ese proveedor no existe.' using errcode = 'P0002'; end if;
  update supplier set invoicing_mode = p_modo,
         invoicing_per_location = case when p_modo = 'delivery_note_then_invoice' then p_por_local else null end,
         invoicing_frequency = case when p_modo = 'delivery_note_then_invoice' then coalesce(p_frecuencia, invoicing_frequency)
                                    when p_modo = 'per_delivery' then 'per_delivery'
                                    when p_modo = 'monthly_settlement' then 'monthly' else invoicing_frequency end
   where id = p_proveedor;
  -- 0350: también las consumidas con una pregunta de la ficha.
  for r in select p.goods_receipt_id from goods_receipt_path p join goods_receipt g on g.id = p.goods_receipt_id
            where p.account_id = v_cuenta
              and (p.consumed_at is null or p.question in ('ficha_sin_forma', 'papel_y_ficha'))
              and (g.supplier_id = p_proveedor or p.supplier_id = p_proveedor
                   or (p.question = 'a_nombre_de' and (p.question_detail->>'proveedor')::uuid = p_proveedor)) loop
    perform public._compras_camino_guarda(r.goods_receipt_id); v_n := v_n + 1;
  end loop;
  return jsonb_build_object('proveedor', p_proveedor, 'modo', p_modo, 'recepciones', v_n);
end $$;


--
-- Name: _compras_lineas_comparar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_lineas_comparar(p_factura uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_alb jsonb; v_out jsonb := '[]'; fl record; v_hit int; a jsonb; v_res text;
  n_ok int := 0; n_dif int := 0; n_fac int := 0; n_alb int := 0; n_lin int := 0;
begin
  -- Las líneas de los albaranes casados con la factura, en su orden.
  select coalesce(jsonb_agg(jsonb_build_object(
           'albaran', coalesce(g.supplier_doc_number, g.code), 'art', l.recipe_item_id, 'cod', nullif(lower(btrim(l.supplier_code)), ''),
           'txt', public._compras_texto_norm(coalesce(l.raw_text, l.product_name)), 'texto', coalesce(l.product_name, l.raw_text),
           'cant', coalesce(l.doc_qty, l.qty_received), 'importe', coalesce(l.doc_amount, round(l.qty_received * l.unit_cost, 2)), 'usada', false)
           order by g.receipt_date, g.code, l.position, l.created_at), '[]')
    into v_alb
    from supplier_invoice_receipt r join goods_receipt g on g.id = r.goods_receipt_id
    join goods_receipt_line l on l.goods_receipt_id = g.id
   where r.supplier_invoice_id = p_factura;
  for fl in
    select il.recipe_item_id, nullif(lower(btrim(il.supplier_code)), '') cod, public._compras_texto_norm(il.raw_text) txt,
           il.raw_text, il.qty, il.line_amount
      from supplier_invoice_line il where il.supplier_invoice_id = p_factura order by il.position, il.created_at
  loop
    n_lin := n_lin + 1;
    -- Su línea del albarán: el mismo artículo, si no el mismo código del proveedor, si no el mismo texto.
    select x.i - 1 into v_hit from jsonb_array_elements(v_alb) with ordinality x(e, i)
     where not (x.e->>'usada')::boolean
       and ((fl.recipe_item_id is not null and x.e->>'art' = fl.recipe_item_id::text)
         or (fl.cod is not null and x.e->>'cod' = fl.cod)
         or (fl.txt <> '' and x.e->>'txt' = fl.txt))
     order by case when x.e->>'art' = fl.recipe_item_id::text then 1 when x.e->>'cod' = fl.cod then 2 else 3 end, x.i
     limit 1;
    if v_hit is null then
      n_fac := n_fac + 1;
      v_out := v_out || jsonb_build_array(jsonb_build_object('resultado', 'solo_factura', 'texto_factura', fl.raw_text,
                 'cant_factura', fl.qty, 'importe_factura', fl.line_amount));
      continue;
    end if;
    a := v_alb->v_hit;
    v_alb := jsonb_set(v_alb, array[v_hit::text, 'usada'], 'true');
    v_res := case when fl.qty is not null and (a->>'cant') is not null and abs(fl.qty - (a->>'cant')::numeric) > 0.001 then 'cantidad'
                  when fl.line_amount is not null and (a->>'importe') is not null and abs(fl.line_amount - (a->>'importe')::numeric) > 0.02 then 'importe'
                  else 'cuadra' end;
    if v_res = 'cuadra' then n_ok := n_ok + 1; else n_dif := n_dif + 1; end if;
    v_out := v_out || jsonb_build_array(jsonb_build_object('resultado', v_res, 'texto_factura', fl.raw_text, 'albaran', a->>'albaran',
               'texto_albaran', a->>'texto', 'cant_factura', fl.qty, 'cant_albaran', (a->>'cant')::numeric,
               'importe_factura', fl.line_amount, 'importe_albaran', (a->>'importe')::numeric));
  end loop;
  -- Lo que está en el albarán y la factura no trae.
  for a in select x.e from jsonb_array_elements(v_alb) x(e) where not (x.e->>'usada')::boolean loop
    n_alb := n_alb + 1;
    v_out := v_out || jsonb_build_array(jsonb_build_object('resultado', 'solo_albaran', 'albaran', a->>'albaran', 'texto_albaran', a->>'texto',
               'cant_albaran', (a->>'cant')::numeric, 'importe_albaran', (a->>'importe')::numeric));
  end loop;
  return jsonb_build_object('lineas_factura', n_lin, 'cuadran', n_ok, 'difieren', n_dif, 'solo_factura', n_fac, 'solo_albaran', n_alb, 'lineas', v_out);
end $$;


--
-- Name: _compras_liquidacion_confirmar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_liquidacion_confirmar(p_liq uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l licensed_settlement; v_fv uuid; v_n int; r jsonb;
begin
  select * into l from licensed_settlement where id = p_liq for update;
  if l.id is null then raise exception 'Esa liquidación no existe.' using errcode = 'P0002'; end if;
  if l.formula <> 'documentos' then raise exception 'Esta liquidación no sale de sus documentos.' using errcode = '22023'; end if;
  if l.status <> 'borrador' then raise exception 'La liquidación % ya está confirmada.', l.settlement_ref using errcode = '22023'; end if;
  if jsonb_array_length(coalesce(l.detail->'bloqueos', '[]'::jsonb)) > 0 then
    raise exception 'No se puede confirmar: %', (select string_agg(b, ' ') from jsonb_array_elements_text(l.detail->'bloqueos') b) using errcode = '22023';
  end if;
  r := l.detail->'recibida';
  -- Su factura, como factura recibida. Aprobada por quien confirma (las reglas de aprobación, en la base).
  insert into supplier_invoice (account_id, supplier_id, location_id, company_id, doc_kind, invoice_number, invoice_date, status, source,
                                tax_base_total, tax_total, grand_total, notes, created_by, created_by_name)
  values (l.account_id, l.supplier_id, l.location_id, l.company_id, 'invoice', r->>'numero', (r->>'fecha')::date, 'aprobada', 'manual',
          l.stock_invoice_cost, (r->>'total')::numeric - l.stock_invoice_cost, (r->>'total')::numeric,
          format('Su factura de la liquidación %s (%s a %s).', l.settlement_ref, to_char(l.period_from, 'DD/MM/YYYY'), to_char(l.period_to, 'DD/MM/YYYY')),
          auth.uid(), coalesce(p_quien_nombre, public.conta_nombre_actor()))
  returning id into v_fv;
  insert into supplier_invoice_line (supplier_invoice_id, raw_text, line_amount, vat_pct, position)
  select v_fv, x->>'concepto', (x->>'base')::numeric, (x->>'tipo')::numeric, (n - 1)::int
    from jsonb_array_elements(coalesce(r->'lineas', '[]'::jsonb)) with ordinality t(x, n);
  -- Sus recepciones del mes en ese local quedan cubiertas por la liquidación.
  update goods_receipt_path p set consumed_at = now()
    from goods_receipt g
   where g.id = p.goods_receipt_id and p.account_id = l.account_id and p.path = 'liquidacion' and p.supplier_id = l.supplier_id
     and g.location_id = l.location_id and g.receipt_date between l.period_from and l.period_to and p.consumed_at is null;
  get diagnostics v_n = row_count;
  update licensed_settlement set status = 'confirmada', confirmed_at = now(), confirmed_by = auth.uid(),
         confirmed_by_name = coalesce(p_quien_nombre, public.conta_nombre_actor()), received_invoice_id = v_fv, updated_at = now()
   where id = p_liq;
  return jsonb_build_object('liquidacion', p_liq, 'factura', v_fv, 'recepciones', v_n,
    'frase', format('Confirmada. Su factura %s queda registrada y %s recepción(es) del mes, cubiertas. Los tres asientos los propone el libro.', r->>'numero', v_n));
end $$;


--
-- Name: _compras_liquidacion_contraste(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_liquidacion_contraste(p_liq uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  l licensed_settlement; v_compras jsonb; v_ventas jsonb; v_productos jsonb; v_doc_compras numeric; v_origen_marcas text;
begin
  select * into l from licensed_settlement where id = p_liq;
  if l.id is null then raise exception 'Esa liquidación no existe.' using errcode = 'P0002'; end if;

  -- Compras: sus recepciones del mes en ese local (las suyas, o las de otro
  -- a su nombre que van a su liquidación), por la base de sus papeles.
  with rec as (
    select g.id, public._compras_base_recepcion(g.id) base
      from goods_receipt g left join goods_receipt_path p on p.goods_receipt_id = g.id
     where g.account_id = l.account_id and g.location_id = l.location_id and g.status = 'confirmado'
       and g.receipt_date between l.period_from and l.period_to
       and ((p.id is not null and p.path = 'liquidacion' and p.supplier_id = l.supplier_id)
            or (p.id is null and g.supplier_id = l.supplier_id)))
  select jsonb_build_object('folvy', coalesce(sum(base), 0), 'recepciones', count(*), 'sin_base', count(*) filter (where base is null)) into v_compras from rec;
  select round(sum((x->>'compras')::numeric * (x->>'precio')::numeric), 2) into v_doc_compras
    from jsonb_array_elements(coalesce(l.detail->'inventario'->'productos', '[]'::jsonb)) x;
  v_compras := v_compras || jsonb_build_object('documento', v_doc_compras,
    'diferencia', case when v_doc_compras is null then null else round((v_compras->>'folvy')::numeric - v_doc_compras, 2) end);

  -- Ventas: pedidos cerrados de sus marcas en ese local y mes (fecha de Madrid), por plataforma.
  -- Sus marcas: las de sus acuerdos de cesión; si no tiene ninguno (Foodint,
  -- 10/10: ningún acuerdo en la cuenta), las cedidas que no son de nadie, y se dice.
  v_origen_marcas := case when exists (select 1 from brand_licensing_agreement a where a.party_id = l.party_id) then 'acuerdo'
                          when exists (select 1 from brand b where b.account_id = l.account_id and b.ownership_type = 'licensed'
                                         and not exists (select 1 from brand_licensing_agreement a where a.brand_id = b.id)) then 'cedidas_sin_acuerdo'
                          else 'ninguna' end;
  with marcas as (
    select a.brand_id id from brand_licensing_agreement a where a.party_id = l.party_id and v_origen_marcas = 'acuerdo'
    union
    select b.id from brand b where v_origen_marcas = 'cedidas_sin_acuerdo' and b.account_id = l.account_id and b.ownership_type = 'licensed'
       and not exists (select 1 from brand_licensing_agreement a where a.brand_id = b.id)),
  folvy as (
    select lower(regexp_replace(public.unaccent(c.name), '[^a-zA-Z]', '', 'g')) plat, c.name nombre, sum(s.taxable_base) base, count(*) pedidos
      from sale s join sales_channel c on c.id = s.channel_id
     where s.account_id = l.account_id and s.location_id = l.location_id and s.status = 'closed' and coalesce(s.is_active, true)
       and (s.sold_at at time zone 'Europe/Madrid')::date between l.period_from and l.period_to
       and s.brand_id in (select m.id from marcas m)
     group by 1, 2),
  doc as (
    select lower(regexp_replace(public.unaccent(x->>'plataforma'), '[^a-zA-Z]', '', 'g')) plat, x->>'plataforma' nombre,
           (x->'totales'->>'ventas')::numeric ventas, (x->'totales'->>'total')::numeric total
      from jsonb_array_elements(coalesce(l.detail->'ventas'->'plataformas', '[]'::jsonb)) x)
  select coalesce(jsonb_agg(jsonb_build_object('plataforma', coalesce(d.nombre, f.nombre), 'documento', d.ventas, 'folvy', round(f.base, 2),
           'pedidos', f.pedidos, 'diferencia', round(coalesce(f.base, 0) - coalesce(d.ventas, 0), 2)) order by coalesce(d.nombre, f.nombre)), '[]'::jsonb)
    into v_ventas from doc d full join folvy f on f.plat = d.plat;

  -- Producto a producto, donde está casado: lo que dice que te mandó contra
  -- lo que recibiste (en la unidad base de la dimensión: g, ml o ud).
  with doc as (
    select x->>'nombre' nombre, public.compras_nombre_norm(x->>'nombre') nom, (x->>'compras')::numeric compras, x->>'unidad' unidad,
           case lower(x->>'unidad') when 'kg' then 1000 when 'g' then 1 when 'lt' then 1000 when 'l' then 1000 when 'ml' then 1 else 1 end factor,
           case lower(x->>'unidad') when 'kg' then 'weight' when 'g' then 'weight' when 'lt' then 'volume' when 'l' then 'volume' when 'ml' then 'volume' else 'unit' end dim
      from jsonb_array_elements(coalesce(l.detail->'inventario'->'productos', '[]'::jsonb)) x),
  casado as (
    select d.*, m.recipe_item_id, m.not_ours from doc d
      left join settlement_product_match m on m.account_id = l.account_id and m.supplier_id = l.supplier_id and m.name_norm = d.nom),
  recibido as (
    select gl.recipe_item_id, sum(gl.qty_in_base * u.factor_to_base) qty, max(u.dimension) dim
      from goods_receipt g join goods_receipt_line gl on gl.goods_receipt_id = g.id
      join recipe_item r on r.id = gl.recipe_item_id join kitchen_unit u on u.id = r.base_unit_id
      left join goods_receipt_path p on p.goods_receipt_id = g.id
     where g.account_id = l.account_id and g.location_id = l.location_id and g.status = 'confirmado'
       and g.receipt_date between l.period_from and l.period_to
       and ((p.id is not null and p.path = 'liquidacion' and p.supplier_id = l.supplier_id) or (p.id is null and g.supplier_id = l.supplier_id))
     group by gl.recipe_item_id)
  select jsonb_build_object(
    'casados', count(*) filter (where c.recipe_item_id is not null),
    'no_nuestros', count(*) filter (where c.not_ours),
    'sin_casar', count(*) filter (where c.recipe_item_id is null and not coalesce(c.not_ours, false)),
    'sin_casar_con_compras', count(*) filter (where c.recipe_item_id is null and not coalesce(c.not_ours, false) and c.compras <> 0),
    'no_coinciden', coalesce(jsonb_agg(jsonb_build_object('nombre', c.nombre, 'articulo', c.recipe_item_id, 'documento', c.compras, 'unidad', c.unidad,
                     'folvy', case when r.dim is null then 0 when r.dim = c.dim then round(r.qty / c.factor, 3) end,
                     'comparable', r.dim is null or r.dim = c.dim))
                   filter (where c.recipe_item_id is not null and (r.dim is distinct from c.dim and r.dim is not null
                           or abs(coalesce(r.qty, 0) - c.compras * c.factor) > greatest(0.01 * c.compras * c.factor, 0.001))), '[]'::jsonb))
    into v_productos from casado c left join recibido r on r.recipe_item_id = c.recipe_item_id;

  return jsonb_build_object('liquidacion', l.id, 'compras', v_compras, 'ventas', v_ventas, 'productos', v_productos,
    'marcas', v_origen_marcas,
    'marcas_frase', case v_origen_marcas
      when 'acuerdo' then 'Sus marcas, por sus acuerdos de cesión.'
      when 'cedidas_sin_acuerdo' then 'No tiene acuerdos de cesión: se toman las marcas cedidas que no son de nadie. Ponle sus acuerdos en su ficha.'
      else 'No hay marcas cedidas: no hay ventas suyas que contrastar.' end);
end $$;


--
-- Name: _compras_liquidacion_guardar(uuid, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_liquidacion_guardar(p_empresa uuid, p_proveedor uuid, p_local uuid, p_lectura jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid; s supplier; v_party uuid; v_id uuid; v_num text; v_desde date; v_hasta date; v_clave text;
  v_serv numeric; v_merc numeric; v_stock numeric; v_saldo numeric;
begin
  select account_id into v_cuenta from company where id = p_empresa;
  select * into s from supplier where id = p_proveedor;
  if v_cuenta is null or s.account_id is distinct from v_cuenta then raise exception 'La empresa y el proveedor tienen que ser de la misma cuenta.' using errcode = '42501'; end if;
  if not exists (select 1 from locations where id = p_local and account_id = v_cuenta) then raise exception 'Ese local no es de esta cuenta.' using errcode = '42501'; end if;
  if s.invoicing_mode is distinct from 'monthly_settlement' then
    raise exception 'La ficha de % no dice que liquida cada mes: cámbiala antes («Cómo te factura»).', s.name using errcode = '22023';
  end if;
  select party_id into v_party from party_role where supplier_id = p_proveedor limit 1;
  if v_party is null then raise exception '% no tiene su ficha de tercero.', s.name using errcode = '22023'; end if;
  v_num := nullif(p_lectura->'emitida'->>'numero', '');
  if v_num is null then raise exception 'Sin la factura que le haces no hay liquidación que guardar.' using errcode = '22023'; end if;
  v_desde := (p_lectura->'periodo'->>'desde')::date; v_hasta := (p_lectura->'periodo'->>'hasta')::date;
  if v_desde is null or v_hasta is null then raise exception 'Los documentos no dicen el periodo.' using errcode = '22023'; end if;
  v_clave := format('doc_%s_%s_%s', p_empresa, p_local, v_num);
  if exists (select 1 from licensed_settlement where import_key = v_clave and status <> 'borrador') then
    raise exception 'La liquidación % ya está confirmada: no se vuelve a guardar.', v_num using errcode = '22023';
  end if;
  select coalesce(sum((l->>'base')::numeric) filter (where (l->>'concepto') !~* 'mercader'), 0),
         coalesce(sum((l->>'base')::numeric) filter (where (l->>'concepto') ~* 'mercader'), 0)
    into v_serv, v_merc from jsonb_array_elements(coalesce(p_lectura->'emitida'->'lineas', '[]'::jsonb)) l;
  select coalesce(sum((l->>'base')::numeric), 0) into v_stock from jsonb_array_elements(coalesce(p_lectura->'recibida'->'lineas', '[]'::jsonb)) l;
  v_saldo := coalesce((p_lectura->'transaccion'->'saldo'->>'importe')::numeric,
                      (p_lectura->'emitida'->>'total')::numeric - coalesce((p_lectura->'recibida'->>'total')::numeric, 0));

  insert into licensed_settlement (account_id, company_id, supplier_id, party_id, location_id, settlement_ref, period_from, period_to, period_grain,
                                   service_revenue, materials_supplied, stock_invoice_cost, net_settlement, source, import_key, formula, status,
                                   detail, raw, created_by, created_by_name, updated_at)
  values (v_cuenta, p_empresa, p_proveedor, v_party, p_local, v_num, v_desde, v_hasta, 'month',
          v_serv, v_merc, v_stock, v_saldo, 'documentos', v_clave, 'documentos', 'borrador',
          p_lectura, null, auth.uid(), coalesce(p_quien_nombre, public.conta_nombre_actor()), now())
  on conflict (import_key) do update set
    service_revenue = excluded.service_revenue, materials_supplied = excluded.materials_supplied, stock_invoice_cost = excluded.stock_invoice_cost,
    net_settlement = excluded.net_settlement, period_from = excluded.period_from, period_to = excluded.period_to, detail = excluded.detail, updated_at = now()
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: _compras_texto_norm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compras_texto_norm(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select btrim(regexp_replace(lower(translate(coalesce(p, ''), 'ÁÉÍÓÚÜÑáéíóúüñ', 'aeiouunaeiouun')), '[^a-z0-9]+', ' ', 'g'))
$$;


--
-- Name: _conta_abono_clave(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_abono_clave(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select nullif(upper(regexp_replace(coalesce(p, ''), '[^A-Za-z0-9]', '', 'g')), '')
$$;


--
-- Name: _conta_abono_ligar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_abono_ligar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_clave text; v_ids uuid[];
begin
  if new.doc_kind <> 'credit_note' or new.corrects_invoice_id is not null or new.supplier_id is null then return new; end if;
  v_clave := public._conta_abono_clave(new.reading->'factura'->>'rectificaA');
  if v_clave is null then return new; end if;
  select array_agg(s.id) into v_ids from public.supplier_invoice s
   where s.account_id = new.account_id and s.supplier_id = new.supplier_id and s.id <> new.id
     and s.doc_kind = 'invoice' and s.status <> 'descartada' and s.number_key = v_clave;
  if coalesce(array_length(v_ids, 1), 0) = 1 then new.corrects_invoice_id := v_ids[1]; end if;
  return new;
end $$;


--
-- Name: _conta_abono_validado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_abono_validado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (select 1 from public.supplier_invoice s where s.id = new.source_id and s.account_id = new.account_id and s.doc_kind = 'credit_note') then
    perform public.conta_abono_compensar(new.source_id);
  end if;
  return null;
end $$;


--
-- Name: sales_day_summary; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_day_summary (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    location_id uuid NOT NULL,
    sales_day date NOT NULL,
    entry_id uuid,
    tickets_count integer NOT NULL,
    total numeric(14,2) NOT NULL,
    by_rate jsonb DEFAULT '[]'::jsonb NOT NULL,
    by_channel jsonb DEFAULT '[]'::jsonb NOT NULL,
    by_brand jsonb DEFAULT '[]'::jsonb NOT NULL,
    first_invoice text,
    last_invoice text,
    detail_hash text NOT NULL,
    sale_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    base_calculated boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    unit_key text,
    channel_id uuid,
    brand_id uuid,
    CONSTRAINT sales_day_summary_by_brand_check CHECK ((jsonb_typeof(by_brand) = 'array'::text)),
    CONSTRAINT sales_day_summary_by_channel_check CHECK ((jsonb_typeof(by_channel) = 'array'::text)),
    CONSTRAINT sales_day_summary_by_rate_check CHECK ((jsonb_typeof(by_rate) = 'array'::text)),
    CONSTRAINT sales_day_summary_rango CHECK (((first_invoice IS NULL) = (last_invoice IS NULL))),
    CONSTRAINT sales_day_summary_tickets_count_check CHECK ((tickets_count >= 0))
);


--
-- Name: TABLE sales_day_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_day_summary IS 'C04. Resumen de las ventas de marcas propias de un día en un local (CCom 28.2; RIVA 63.4): recuento, total, base y cuota por tipo, cobro por canal, base por marca, rango de facturas y huella del detalle. base_calculated: la base sale del tipo, no del pedido.';


--
-- Name: COLUMN sales_day_summary.unit_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_day_summary.unit_key IS 'C04b R5: la unidad del asiento dentro del día y el local: el canal, o canal:marca (claveDeUnidad del núcleo). Nulo = el día entero (la regla de antes).';


--
-- Name: _conta_cierre_de(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_cierre_de(p_summary uuid) RETURNS public.sales_day_summary
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from public.sales_day_summary where id = p_summary and unit_key is not null and channel_id is not null
$$;


--
-- Name: _conta_cierre_rehacer(uuid, uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_cierre_rehacer(p_company uuid, p_location uuid, p_dia date, p_unidad text, p_quien text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_e public.journal_entry; v_p jsonb; v_u jsonb; v_r jsonb; v_res text := 'vacio'; v_porque text; v_id uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  perform pg_advisory_xact_lock(hashtextextended('sales_day:' || p_company::text || ':' || p_location || ':' || p_dia, 0));
  select e.* into v_e from public.sales_day_summary s join public.journal_entry e on e.id = s.entry_id
   where s.company_id = p_company and s.location_id = p_location and s.sales_day = p_dia and s.unit_key = p_unidad;
  if v_e.status = 'validado' then
    raise exception 'El cierre del % ya está validado: no se cambia. Se corrige desde su factura, con «Corregir».', to_char(p_dia, 'DD/MM/YYYY') using errcode = '23514';
  end if;
  if v_e.status in ('propuesto', 'borrador') then delete from public.journal_entry where id = v_e.id; end if;
  v_p := public.conta_propuestas_ventas_dia(p_company, p_location, p_dia);
  select x into v_u from jsonb_array_elements(coalesce(v_p, '[]'::jsonb)) x where x->>'unit_key' = p_unidad limit 1;
  if v_u is null then
    v_res := 'vacio'; v_porque := 'No le queda ningún pedido que contar.';
  elsif v_u->'propuesta' ? 'sin_propuesta' then
    v_res := 'sin_propuesta'; v_porque := v_u->'propuesta'->>'sin_propuesta';
  else
    v_r := public._journal_entry_proponer(p_company, v_u->'propuesta'->'entrada', v_u->'propuesta'->'lineas', v_u->'propuesta'->'resumen', p_quien, auth.uid());
    v_id := nullif(v_r->>'id', '')::uuid;
    v_res := case when (v_r->>'descartada')::boolean then 'descartado' else 'propuesto' end;
    if v_res = 'descartado' then v_porque := 'Este cierre estaba descartado: no se vuelve a proponer.'; end if;
  end if;
  if v_res = 'vacio' then
    -- Sin pedidos que contar: su cierre dice cero (y en espera, con el porqué).
    update public.sales_day_summary set tickets_count = 0, total = 0, sale_ids = '{}', by_rate = '[]', by_channel = '[]', by_brand = '[]'
     where company_id = p_company and location_id = p_location and sales_day = p_dia and unit_key = p_unidad and entry_id is null;
  end if;
  if v_res = 'propuesto' then
    delete from public.conta_cierre_espera where company_id = p_company and location_id = p_location and sales_day = p_dia and unit_key = p_unidad and automatica;
  elsif exists (select 1 from public.sales_day_summary where company_id = p_company and location_id = p_location and sales_day = p_dia and unit_key = p_unidad) then
    insert into public.conta_cierre_espera (account_id, company_id, location_id, sales_day, unit_key, motivo, automatica, created_by_name)
    values (v_cuenta, p_company, p_location, p_dia, p_unidad, v_porque, true, p_quien)
    on conflict (company_id, location_id, sales_day, unit_key) do update set motivo = excluded.motivo
      where public.conta_cierre_espera.automatica;
  end if;
  return jsonb_build_object('dia', p_dia, 'resultado', v_res, 'porque', v_porque, 'asiento', v_id,
    'total', (select total from public.sales_day_summary where company_id = p_company and location_id = p_location and sales_day = p_dia and unit_key = p_unidad));
end $$;


--
-- Name: _conta_cierre_serie(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_cierre_serie(p_company uuid, p_canal uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_code text; v_slug text; v_base text; v_i int := 1;
begin
  select code into v_code from public.invoice_series where company_id = p_company and channel_id = p_canal order by created_at limit 1;
  if v_code is not null then return v_code; end if;
  select ch.slug into v_slug from public.sales_channel ch join public.company c on c.id = p_company and c.account_id = ch.account_id where ch.id = p_canal;
  v_base := case when v_slug ~* 'uber' then 'UBR' when v_slug ~* 'glovo' then 'GLV' when v_slug ~* 'just' then 'JUS'
                 when v_slug ~* 'tpv|mostrador|pos' then 'TPV' when v_slug ~* 'shop|tienda|web' then 'WEB'
                 else nullif(left(upper(regexp_replace(coalesce(v_slug, ''), '[^A-Za-z0-9]', '', 'g')), 3), '') end;
  v_base := coalesce(v_base, 'CD');
  v_code := v_base;
  while exists (select 1 from public.invoice_series where company_id = p_company and code = v_code)
     or exists (select 1 from public.customer_invoice where company_id = p_company and series_code = v_code and origin <> 'cierre_dia') loop
    v_i := v_i + 1; v_code := v_base || v_i;
  end loop;
  return v_code;
end $$;


--
-- Name: _conta_comision_buscar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_comision_buscar(p_invoice uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb; v public.supplier_invoice; v_suya uuid;
begin
  select * into v from public.supplier_invoice where id = p_invoice;
  if v.id is null or v.status in ('anulada', 'descartada') then return null; end if;
  -- S01o · Primero, por su número: la liquidación que nombra esta factura es la suya.
  v_suya := public._conta_comision_de_su_numero(v.id);
  if v_suya is not null then
    if not exists (select 1 from public.channel_settlement_invoice k where k.supplier_invoice_id = v.id and k.settlement_id = v_suya) then
      update public.channel_settlement set commission_invoice_id = null, updated_at = now()
       where account_id = v.account_id and commission_invoice_id = v.id and id <> v_suya;
      perform public._conta_comision_ligar(v.id, v_suya, 'sumied', 'Sumied (por su número)');
    end if;
    return 'ligada';
  end if;
  r := public._conta_comision_estado(v.id);
  if r->>'estado' = 'no' then return 'no'; end if;
  update public.supplier_invoice set payment_method = 'compensation', updated_at = now() where id = v.id and payment_method is distinct from 'compensation';
  if r->>'estado' = 'una' then
    perform public._conta_comision_ligar(v.id, (r->>'liquidacion')::uuid, 'sumied', 'Sumied');
  elsif r->>'estado' = 'fuera' then
    perform public._conta_comision_pagar(v.id, true);
  elsif r->>'estado' = 'ligada' then
    perform public._conta_comision_pagar(v.id);
  end if;
  return r->>'estado';
end $$;


--
-- Name: _conta_comision_datos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_comision_datos(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v public.supplier_invoice; v_canal uuid; v_lineas text; m text[]; v_desde date; v_hasta date;
  v_texto text; v_marca uuid; v_local uuid; v_dir text;
begin
  select * into v from public.supplier_invoice where id = p_invoice;
  if v.id is null or v.supplier_id is null then return null; end if;
  select pl.channel_id into v_canal
    from public.party_role ps join public.party_role pl on pl.account_id = ps.account_id and pl.party_id = ps.party_id and pl.role = 'platform'
   where ps.account_id = v.account_id and ps.role = 'supplier' and ps.supplier_id = v.supplier_id and pl.channel_id is not null
   limit 1;
  if v_canal is null then return null; end if;
  select string_agg(l.raw_text, ' | ') into v_lineas from public.supplier_invoice_line l where l.supplier_invoice_id = v.id;
  m := regexp_match(coalesce(v_lineas, ''), '(\d{2})/(\d{2})/(\d{2,4})\s*-\s*(\d{2})/(\d{2})/(\d{2,4})');
  if m is not null then
    v_desde := make_date(case when length(m[3]) = 2 then 2000 + m[3]::int else m[3]::int end, m[2]::int, m[1]::int);
    v_hasta := make_date(case when length(m[6]) = 2 then 2000 + m[6]::int else m[6]::int end, m[5]::int, m[4]::int);
  elsif v.reading->'factura'->'periodo'->>'hasta' ~ '^\d{4}-\d{2}-\d{2}$' then
    v_desde := nullif(v.reading->'factura'->'periodo'->>'desde', '')::date;
    v_hasta := (v.reading->'factura'->'periodo'->>'hasta')::date;
  elsif v.invoice_date is not null and extract(day from v.invoice_date) = 15 then
    v_desde := date_trunc('month', v.invoice_date)::date; v_hasta := v.invoice_date;
  elsif v.invoice_date is not null and v.invoice_date = (date_trunc('month', v.invoice_date) + interval '1 month - 1 day')::date then
    v_desde := date_trunc('month', v.invoice_date)::date + 15; v_hasta := v.invoice_date;
  end if;
  v_dir := nullif(btrim(coalesce(v.reading->'factura'->'tienda'->>'direccion', '')), '');
  v_texto := lower(concat_ws(' | ', v.reading->'factura'->'destinatario'->>'nombre', v.reading->'factura'->'tienda'->>'nombre', v_dir));
  select b.id into v_marca from public.brand b
   where b.account_id = v.account_id and length(btrim(b.name)) >= 3 and position(lower(btrim(b.name)) in v_texto) > 0
   order by length(b.name) desc limit 1;
  v_local := public._conta_local_de_texto(v.account_id, array[v_dir, v.reading->'factura'->'tienda'->>'nombre', v.reading->'factura'->'destinatario'->>'nombre']);
  return jsonb_build_object('canal', v_canal, 'desde', v_desde, 'hasta', v_hasta, 'marca', v_marca, 'local', v_local,
    'total', v.grand_total, 'direccion_leida', v_dir is not null);
end $_$;


--
-- Name: _conta_comision_de_su_numero(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_comision_de_su_numero(p_invoice uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.supplier_invoice; v_num text; v_canal uuid; v_ids uuid[];
begin
  select * into v from public.supplier_invoice where id = p_invoice;
  v_num := upper(regexp_replace(coalesce(v.invoice_number, ''), '[^A-Za-z0-9]', '', 'g'));
  if v.id is null or length(v_num) < 5 then return null; end if;
  v_canal := (public._conta_comision_datos(v.id)->>'canal')::uuid;
  if v_canal is null then return null; end if;
  select array_agg(cs.id) into v_ids
    from public.channel_settlement cs
   where cs.account_id = v.account_id and cs.channel_id = v_canal
     and v_num in (upper(regexp_replace(coalesce(cs.raw->'factura'->>'numero', ''), '[^A-Za-z0-9]', '', 'g')),
                   upper(regexp_replace(coalesce(cs.settlement_ref, ''), '[^A-Za-z0-9]', '', 'g')));
  return case when coalesce(array_length(v_ids, 1), 0) = 1 then v_ids[1] end;
end $$;


--
-- Name: _conta_comision_estado(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_comision_estado(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v public.supplier_invoice; d jsonb; v_canal uuid; v_desde date; v_hasta date; v_marca uuid; v_local uuid;
  v_cands jsonb; v_n int; v_exactas jsonb; v_primera date; v_lig uuid; v_porque text; v_plat text;
begin
  select * into v from public.supplier_invoice where id = p_invoice;
  if v.id is null then return jsonb_build_object('estado', 'no'); end if;
  select settlement_id into v_lig from public.channel_settlement_invoice where supplier_invoice_id = v.id and account_id = v.account_id;
  d := public._conta_comision_datos(v.id);
  if d is null then return jsonb_build_object('estado', 'no'); end if;
  v_canal := (d->>'canal')::uuid; v_desde := (d->>'desde')::date; v_hasta := (d->>'hasta')::date;
  v_marca := (d->>'marca')::uuid; v_local := (d->>'local')::uuid;
  select name into v_plat from public.sales_channel where id = v_canal;
  if v_lig is not null then
    -- Su liquidación, para la ficha: periodo, tienda, lo que factura, lo que suman sus facturas y lo que pagó.
    return jsonb_build_object('estado', 'ligada', 'liquidacion', v_lig, 'plataforma', v_plat, 'datos', d,
      'liq', (select jsonb_build_object('id', cs.id, 'desde', cs.period_from, 'hasta', cs.period_to,
                'tienda', regexp_replace(coalesce(ps.external_text, cs.external_location_text, ''), '\s*\(.*$', ''),
                'marca', (select name from public.brand where id = coalesce(cs.brand_id, ps.brand_id)),
                'local', (select name from public.locations where id = coalesce(cs.location_id, ps.location_id)),
                'a_facturar', public._conta_liquidacion_a_facturar(cs), 'te_pago', cs.net_payout, 'referencia', coalesce(cs.is_reference, false),
                'fecha', coalesce(cs.settlement_date, cs.period_to),
                'facturas', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'codigo', x.code, 'numero', x.invoice_number, 'total', x.grand_total) order by x.invoice_date, x.code), '[]'::jsonb)
                               from public.channel_settlement_invoice k join public.supplier_invoice x on x.id = k.supplier_invoice_id where k.settlement_id = cs.id))
                from public.channel_settlement cs left join public.platform_store ps on ps.id = cs.store_id where cs.id = v_lig));
  end if;
  select min(period_from) into v_primera from public.channel_settlement where account_id = v.account_id and channel_id = v_canal;
  if v_hasta is not null and (v_primera is null or v_hasta < v_primera) then
    return jsonb_build_object('estado', 'fuera', 'plataforma', v_plat, 'datos', d,
      'porque', case when v_primera is null then format('No hay ninguna liquidación de %s en Sumied: se compensó fuera de Sumied.', v_plat)
                     else format('Es de antes de la primera liquidación de %s en Sumied (%s): se compensó fuera de Sumied.', v_plat, to_char(v_primera, 'DD/MM/YYYY')) end);
  end if;
  -- Las que encajan: misma plataforma, el periodo se solapa, y su marca y su local si se saben.
  with c as (
    select cs.*, public._conta_liquidacion_a_facturar(cs) as a_facturar,
           coalesce(cs.brand_id, ps.brand_id) as marca, coalesce(cs.location_id, ps.location_id,
             public._conta_local_de_texto(cs.account_id, array[coalesce(ps.external_text, cs.external_location_text)])) as local,
           coalesce(ps.external_text, cs.external_location_text) as tienda,
           (select coalesce(sum(x.grand_total), 0) from public.channel_settlement_invoice k join public.supplier_invoice x on x.id = k.supplier_invoice_id
             where k.settlement_id = cs.id) as ya_facturado
      from public.channel_settlement cs left join public.platform_store ps on ps.id = cs.store_id
     where cs.account_id = v.account_id and cs.channel_id = v_canal
       and case when v_hasta is null then cs.period_to between v.invoice_date - 45 and v.invoice_date
                else cs.period_from <= v_hasta and cs.period_to >= coalesce(v_desde, v_hasta) end),
  f as (
    select c.* from c
     where (v_marca is null or c.marca = v_marca or (c.marca is null and position(lower((select name from public.brand where id = v_marca)) in lower(coalesce(c.tienda, ''))) > 0))
       and (v_local is null or c.local = v_local))
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', f.id, 'desde', f.period_from, 'hasta', f.period_to, 'tienda', regexp_replace(coalesce(f.tienda, ''), '\s*\(.*$', ''),
           'marca', (select name from public.brand where id = f.marca), 'local', (select name from public.locations where id = f.local),
           'a_facturar', f.a_facturar, 'ya_facturado', f.ya_facturado, 'te_pago', f.net_payout, 'referencia', coalesce(f.is_reference, false),
           'coincide', f.a_facturar is not null and (round(f.a_facturar * 100) = round(v.grand_total * 100)
                                                     or round((f.a_facturar - f.ya_facturado) * 100) = round(v.grand_total * 100)))
           order by f.period_to desc, f.id), '[]'::jsonb)
    into v_cands from f;
  v_n := jsonb_array_length(v_cands);
  if v_hasta is null then
    return jsonb_build_object('estado', 'sin_periodo', 'plataforma', v_plat, 'datos', d, 'candidatas', v_cands,
      'porque', 'La factura no dice de qué semana o quincena es: elige su liquidación.');
  end if;
  -- Ligar sin preguntar solo con una de estas dos (01/11, medido en Foodint: con una sola candidata y
  -- sin marca ni local se ligaban 12 facturas de Glovo de doce tiendas a la única liquidación de la quincena):
  --   · coincide al céntimo una sola (con lo que factura la liquidación, o con lo que le falta por facturar);
  --   · la factura dice su marca, encaja una sola y su periodo es exactamente el de la liquidación (una
  --     liquidación de varias semanas no se queda la factura de una de ellas).
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_exactas from jsonb_array_elements(v_cands) x where (x->>'coincide')::boolean;
  if jsonb_array_length(v_exactas) = 1 then
    return jsonb_build_object('estado', 'una', 'liquidacion', v_exactas->0->>'id', 'plataforma', v_plat, 'datos', d, 'candidatas', v_cands, 'por_importe', true);
  end if;
  if v_n = 1 and v_marca is not null and (v_cands->0->>'desde')::date = v_desde and (v_cands->0->>'hasta')::date = v_hasta then
    return jsonb_build_object('estado', 'una', 'liquidacion', v_cands->0->>'id', 'plataforma', v_plat, 'datos', d, 'candidatas', v_cands);
  end if;
  if v_n >= 1 then
    v_porque := format('%s de %s del %s al %s%s%s, y %s.',
      case when v_n = 1 then 'Hay una liquidación' else 'Hay ' || v_n || ' liquidaciones' end, v_plat, to_char(coalesce(v_desde, v_hasta), 'DD/MM'), to_char(v_hasta, 'DD/MM'),
      case when v_marca is not null then ' de ' || (select name from public.brand where id = v_marca) else '' end,
      case when v_local is not null then ' en ' || (select name from public.locations where id = v_local) else '' end,
      case when v_marca is null and v_local is null then 'la factura no dice de qué marca ni de qué local es'
           when v_marca is null then 'la factura no dice de qué marca es'
           when v_n = 1 then 'su periodo no es el de la factura'
           when v_local is null then 'la factura no dice la dirección de la tienda'
           else 'ninguna coincide sola al céntimo' end);
    return jsonb_build_object('estado', 'varias', 'plataforma', v_plat, 'datos', d, 'candidatas', v_cands, 'porque', v_porque);
  end if;
  return jsonb_build_object('estado', 'falta', 'plataforma', v_plat, 'datos', d, 'candidatas', '[]'::jsonb,
    'porque', format('Falta la liquidación: no hay ninguna de %s%s del %s al %s en Sumied. Se ligará sola cuando llegue.', v_plat,
      case when v_marca is not null then ' de ' || (select name from public.brand where id = v_marca) else '' end,
      to_char(coalesce(v_desde, v_hasta), 'DD/MM'), to_char(v_hasta, 'DD/MM/YYYY')));
end $_$;


--
-- Name: _conta_comision_ligar(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_comision_ligar(p_invoice uuid, p_settlement uuid, p_por text, p_quien text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.supplier_invoice; cs public.channel_settlement;
begin
  select * into v from public.supplier_invoice where id = p_invoice;
  select * into cs from public.channel_settlement where id = p_settlement and account_id = v.account_id;
  if v.id is null or cs.id is null then raise exception 'Esa liquidación no es de la cuenta de la factura.' using errcode = '22023'; end if;
  if cs.channel_id is distinct from (public._conta_comision_datos(v.id)->>'canal')::uuid then
    raise exception 'Esa liquidación no es de la plataforma de la factura.' using errcode = '22023';
  end if;
  insert into public.channel_settlement_invoice (account_id, settlement_id, supplier_invoice_id, matched_by, matched_by_name)
  values (v.account_id, cs.id, v.id, p_por, p_quien)
  on conflict (supplier_invoice_id) do update set settlement_id = excluded.settlement_id, matched_by = excluded.matched_by,
    matched_by_name = excluded.matched_by_name, created_at = now();
  -- Mientras el resto de la base lea la columna de antes (se quita en otra tanda), la primera factura va también ahí.
  update public.channel_settlement set commission_invoice_id = v.id, updated_at = now() where id = cs.id and commission_invoice_id is null;
  update public.supplier_invoice set payment_method = 'compensation', updated_at = now() where id = v.id and payment_method is distinct from 'compensation';
  perform public._conta_comision_pagar(v.id);
end $$;


--
-- Name: _conta_comision_pagar(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_comision_pagar(p_invoice uuid, p_fuera boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.supplier_invoice; cs public.channel_settlement; v_fecha date; v_nota text; v_quien constant text := 'Sumied · compensada con la liquidación';
begin
  select * into v from public.supplier_invoice where id = p_invoice for update;
  if v.id is null or v.status <> 'aprobada' or v.paid_at is not null or coalesce(v.grand_total, 0) = 0 then return false; end if;
  if p_fuera then
    v_fecha := v.invoice_date; v_nota := 'Compensada fuera de Sumied (antes de su primera liquidación en Sumied)';
  else
    select c.* into cs from public.channel_settlement_invoice k join public.channel_settlement c on c.id = k.settlement_id
     where k.supplier_invoice_id = v.id and k.account_id = v.account_id;
    if cs.id is null then return false; end if;
    v_fecha := coalesce(cs.settlement_date, cs.period_to);
    v_nota := format('Compensada con la liquidación del %s al %s', to_char(cs.period_from, 'DD/MM'), to_char(cs.period_to, 'DD/MM/YYYY'));
  end if;
  insert into public.supplier_invoice_payment (account_id, company_id, invoice_id, paid_on, amount, method, note, entry_id, created_by_name)
  values (v.account_id, v.company_id, v.id, v_fecha, v.grand_total, 'compensation', v_nota, cs.journal_entry_id, v_quien);
  update public.supplier_invoice set status = 'pagada', paid_at = v_fecha, paid_method = 'compensation', payment_method = 'compensation',
         paid_by_name = v_quien, updated_at = now() where id = v.id;
  insert into public.supplier_invoice_payment_log (account_id, invoice_id, action, paid_at, paid_method, actor_name)
  values (v.account_id, v.id, 'paid', v_fecha, 'compensation', v_quien);
  return true;
end $$;


--
-- Name: _conta_corte(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_corte(p_company uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select cutover_date from public.bank_settings where company_id = p_company),
                  (select max(imported_until) + 1 from public.fiscal_year where company_id = p_company and imported_until is not null))
$$;


--
-- Name: _conta_cuenta_aprendida(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_cuenta_aprendida(p_company uuid, p_410 text, p_grupo text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select a.code
    from public.journal_entry e
    join public.journal_line l on l.entry_id = e.id
    join public.company_account a on a.id = l.company_account_id and a.company_id = e.company_id and a.code like p_grupo || '%'
   where e.company_id = p_company and e.series = 2 and e.status = 'validado' and p_410 is not null
     and exists (select 1 from public.journal_line l2 join public.company_account a2 on a2.id = l2.company_account_id
                  where l2.entry_id = e.id and a2.code = p_410)
   group by a.code order by count(*) desc, a.code limit 1
$$;


--
-- Name: _conta_dir_coincide(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_dir_coincide(p_texto text, p_dir text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  -- La calle tiene que estar. Si el texto pone un número detrás, tiene que ser el suyo («Inventada 120»
  -- no es «Inventada, 12»); si no lo pone, la calle tiene que ir como calle («C. de Florencio Llorente»,
  -- «(Camichi)»): «Empresa de Prueba» no es «Avenida de Prueba».
  with d as (
    select btrim(regexp_replace(regexp_replace(lower(coalesce(p_dir, '')), '^\s*(calle|c/|c\.|avenida|avda\.?|av\.|paseo|plaza|pza\.?)\s+(de\s+(la\s+|los\s+|las\s+)?)?', ''), '[,\s]*\d.*$', '')) as calle,
           substring(coalesce(p_dir, '') from '(\d+)') as num,
           regexp_replace(lower(coalesce(p_texto, '')), '\s+', ' ', 'g') as t),
  e as (select calle, num, t, position(calle in t) as pos from d)
  select coalesce(length(calle) >= 3 and pos > 0
                  and case when substring(substr(t, pos + length(calle)) from '^[\s,.]{0,3}(\d+)') is not null
                           then substring(substr(t, pos + length(calle)) from '^[\s,.]{0,3}(\d+)') = num
                           -- Sin número, solo si va como calle: «C. de …», «Calle …», «Avenida …» o «(…)».
                           else substr(t, 1, pos - 1) ~ '(\(|(calle|c/|c\.|avenida|avda\.?|av\.|paseo|plaza|pza\.?)\s*(de\s+(la\s+|los\s+|las\s+)?)?)\s*$' end, false)
    from e
$_$;


--
-- Name: _conta_intermediario_de(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_intermediario_de(p_account uuid, p_party uuid, p_canal uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select r.id from public.party_role r where r.account_id = p_account and r.role = 'platform' and r.party_id = p_party order by (r.channel_id is not distinct from p_canal) desc, r.created_at limit 1),
    (select r.id from public.party_role r where r.account_id = p_account and r.role = 'platform' and r.channel_id = p_canal order by r.created_at limit 1))
$$;


--
-- Name: _conta_iva_ajustar_propuesta(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_ajustar_propuesta(p_company uuid, p_entry jsonb, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_fecha date := (p_entry->>'fecha')::date; v_p jsonb; v_desde date; v_nueva date; v_aviso text;
begin
  if public._conta_iva_exento(p_entry->>'source_type', nullif(p_entry->>'source_id', '')::uuid, p_company) then return p_entry; end if;
  if not exists (select 1 from jsonb_array_elements(coalesce(p_lines, '[]')) l
                  where nullif(l->'iva'->>'libro', '') is not null or l->>'cuenta' like '472%' or l->>'cuenta' like '477%') then
    return p_entry;
  end if;
  v_p := public.conta_iva_presentado(p_company, v_fecha);
  if v_p is null then return p_entry; end if;
  -- Solo se mueve una recibida: una expedida (o las ventas de un día) es del
  -- periodo en que se expidió, y ése ya está presentado.
  if exists (select 1 from jsonb_array_elements(p_lines) l where l->'iva'->>'libro' = 'issued')
     or not exists (select 1 from jsonb_array_elements(p_lines) l where l->'iva'->>'libro' in ('received', 'investment')) then
    raise exception '%', public.conta_iva_presentado_mensaje(p_company, v_p, 'corregir') using errcode = '23514', hint = 'iva_presentado';
  end if;
  -- Una factura de proveedor, además, no antes del día en que entró: su libro
  -- la registra ese día o el del asiento si es después (D07, 0850), y así el
  -- asiento y su IVA caen en el mismo periodo.
  v_desde := greatest((v_p->>'hasta')::date + 1,
                      (select si.created_at::date from public.supplier_invoice si
                        where p_entry->>'source_type' = 'supplier_invoice' and si.id = nullif(p_entry->>'source_id', '')::uuid));
  v_nueva := public.conta_primer_dia_iva_abierto(p_company, v_desde);
  if v_nueva is null then
    raise exception '%', public.conta_iva_presentado_mensaje(p_company, v_p, 'factura') using errcode = '23514', hint = 'iva_presentado';
  end if;
  v_aviso := format('%s ya está presentado. Esta factura se deduce %s.',
                    public.conta_iva_periodo_frase('el', v_p->>'periodo', (v_p->>'ejercicio')::int, false),
                    public.conta_iva_periodo_frase('en', public.conta_iva_periodo_de(v_p->>'cadencia', v_nueva), extract(year from v_nueva)::int,
                                                   extract(year from v_nueva)::int <> (v_p->>'ejercicio')::int));
  -- La razón, con la forma de las del núcleo (decision, porque, cita).
  return p_entry || jsonb_build_object('fecha', v_nueva, 'aviso', v_aviso,
    'razones', coalesce(p_entry->'razones', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'decision', v_aviso,
      'porque', format('Una factura contabilizada después de presentar el periodo no entra en él: se asienta el %s, el primer día abierto. Su fecha de factura no cambia.',
                       to_char(v_nueva, 'DD/MM/YYYY')),
      'cita', 'LIVA art. 99.Tres')));
end $$;


--
-- Name: _conta_iva_asiento_con_iva(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_asiento_con_iva(p_entry uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.journal_line l join public.company_account a on a.id = l.company_account_id
                  where l.entry_id = p_entry and (l.vat_book is not null or a.code like '472%' or a.code like '477%'))
$$;


--
-- Name: _conta_iva_candado_apunte(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_candado_apunte() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e record; v_p jsonb;
begin
  select e.company_id, e.entry_date, e.source_type, e.source_id into v_e from public.journal_entry e where e.id = new.entry_id;
  if not found or public._conta_iva_exento(v_e.source_type, v_e.source_id, v_e.company_id) then return new; end if;
  if not (new.vat_book is not null
          or exists (select 1 from public.company_account a where a.id = new.company_account_id and (a.code like '472%' or a.code like '477%'))
          or (tg_op = 'UPDATE' and (old.vat_book is not null
              or exists (select 1 from public.company_account a where a.id = old.company_account_id and (a.code like '472%' or a.code like '477%'))))) then
    return new;
  end if;
  v_p := public.conta_iva_presentado(v_e.company_id, v_e.entry_date);
  if v_p is null then return new; end if;
  raise exception '%', public.conta_iva_presentado_mensaje(v_e.company_id, v_p, 'factura') using errcode = '23514', hint = 'iva_presentado';
end $$;


--
-- Name: _conta_iva_candado_asiento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_candado_asiento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dia date; v_p jsonb;
begin
  -- La huella de un validado y lo que ya está anulado: lo guarda journal_entry_inalterable.
  if old.status in ('validado', 'anulado') and new.status = old.status then return new; end if;
  if public._conta_iva_exento(new.source_type, new.source_id, new.company_id) then return new; end if;
  if not public._conta_iva_asiento_con_iva(new.id) then return new; end if;
  -- Anular uno validado le quita su IVA al periodo en que estaba.
  v_dia := case when new.status = 'anulado' then old.entry_date else new.entry_date end;
  v_p := public.conta_iva_presentado(new.company_id, v_dia);
  if v_p is null then return new; end if;
  raise exception '%', public.conta_iva_presentado_mensaje(new.company_id, v_p,
                         case when new.status = 'anulado' then 'corregir' else 'factura' end)
    using errcode = '23514', hint = 'iva_presentado';
end $$;


--
-- Name: _conta_iva_candado_libro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_candado_libro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_no_es_iva constant text[] := array['number', 'number_to', 'series', 'received_number', 'counterpart_tax_id', 'counterpart_id_type',
                                       'counterpart_name', 'corrects_ref', 'withholding_rate', 'withholding_amount',
                                       'activity_code', 'activity_type', 'activity_iae', 'updated_at', 'updated_by_name'];
  v_p jsonb;
begin
  if tg_op in ('UPDATE', 'DELETE') and not public._conta_iva_exento(old.source_type, old.source_id, old.company_id) then
    if tg_op = 'DELETE' or (to_jsonb(new) - v_no_es_iva) is distinct from (to_jsonb(old) - v_no_es_iva) then
      v_p := public.conta_iva_presentado(old.company_id,
               public._conta_iva_dia_del_libro(old.book, old.deduction_year, old.deduction_period, old.received_date, old.issue_date, old.operation_date));
      if v_p is not null then
        raise exception '%', public.conta_iva_presentado_mensaje(old.company_id, v_p, 'corregir') using errcode = '23514', hint = 'iva_presentado';
      end if;
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  if tg_op = 'UPDATE' and (to_jsonb(new) - v_no_es_iva) is not distinct from (to_jsonb(old) - v_no_es_iva) then return new; end if;
  if public._conta_iva_exento(new.source_type, new.source_id, new.company_id) then return new; end if;
  v_p := public.conta_iva_presentado(new.company_id,
           public._conta_iva_dia_del_libro(new.book, new.deduction_year, new.deduction_period, new.received_date, new.issue_date, new.operation_date));
  if v_p is null then return new; end if;
  raise exception '%', public.conta_iva_presentado_mensaje(new.company_id, v_p, 'factura') using errcode = '23514', hint = 'iva_presentado';
end $$;


--
-- Name: _conta_iva_dia_del_libro(text, smallint, text, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_dia_del_libro(p_book text, p_ded_year smallint, p_ded_period text, p_received date, p_issue date, p_operation date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when p_book in ('received', 'investment') and p_ded_period is not null
              then (public.conta_impuesto_periodo_fechas(p_ded_year, p_ded_period)).desde
              when p_book in ('received', 'investment') then coalesce(p_received, p_issue)
              else coalesce(p_operation, p_issue) end
$$;


--
-- Name: _conta_iva_exento(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_exento(p_tipo text, p_origen uuid, p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p_tipo in ('migrated', 'opening', 'closing')
      or (p_tipo = 'vat_settlement' and exists (select 1 from public.tax_return r where r.id = p_origen and r.company_id = p_company))
$$;


--
-- Name: vat_reopening; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vat_reopening (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    fiscal_year integer NOT NULL,
    period text NOT NULL,
    original_return_id uuid NOT NULL,
    new_return_id uuid NOT NULL,
    kind text NOT NULL,
    reason text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    opened_by uuid,
    opened_by_name text,
    closed_at timestamp with time zone,
    closed_by_name text,
    reminded_at timestamp with time zone,
    CONSTRAINT vat_reopening_kind_check CHECK ((kind = ANY (ARRAY['complementary'::text, 'substitutive'::text]))),
    CONSTRAINT vat_reopening_period_check CHECK ((period ~ '^([1-4]T|0[1-9]|1[0-2])$'::text)),
    CONSTRAINT vat_reopening_reason_check CHECK ((length(btrim(reason)) >= 10))
);


--
-- Name: TABLE vat_reopening; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.vat_reopening IS 'V04 · Reabrir para corregir (1408). Un periodo con el 303 presentado, reabierto con un motivo por el administrador o el gestor. La presentación original no se toca: new_return_id es la nueva (sequence + 1, replaces_return_id → la original). Se cierra sola al presentarse la nueva. Solo la escriben las funciones de la 1408.';


--
-- Name: _conta_iva_marcar(public.vat_reopening, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_marcar(p_reopening public.vat_reopening, p_entry uuid, p_accion text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.vat_reopening_entry (reopening_id, entry_id, account_id, company_id, action, by_user, by_name)
  select (p_reopening).id, p_entry, (p_reopening).account_id, (p_reopening).company_id, p_accion, auth.uid(), public.conta_impuesto_quien()
   where (p_reopening).id is not null
  on conflict (reopening_id, entry_id, action) do update set at = now(), by_user = excluded.by_user, by_name = excluded.by_name
$$;


--
-- Name: _conta_iva_marcar_apunte(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_marcar_apunte() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e record; v public.vat_reopening;
begin
  if not (new.vat_book is not null
          or exists (select 1 from public.company_account a where a.id = new.company_account_id and (a.code like '472%' or a.code like '477%'))) then
    return null;
  end if;
  select e.company_id, e.entry_date, e.source_type, e.source_id into v_e from public.journal_entry e where e.id = new.entry_id;
  if not found or public._conta_iva_exento(v_e.source_type, v_e.source_id, v_e.company_id) then return null; end if;
  v := public.conta_iva_reabierto(v_e.company_id, v_e.entry_date);
  perform public._conta_iva_marcar(v, new.entry_id, case when tg_op = 'INSERT' then 'creado' else 'cambiado' end);
  return null;
end $$;


--
-- Name: _conta_iva_marcar_asiento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_marcar_asiento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.vat_reopening;
begin
  if public._conta_iva_exento(new.source_type, new.source_id, new.company_id) or not public._conta_iva_asiento_con_iva(new.id) then return null; end if;
  if new.status = 'anulado' and old.status is distinct from 'anulado' then
    v := public.conta_iva_reabierto(new.company_id, old.entry_date);
    perform public._conta_iva_marcar(v, new.id, 'anulado');
  elsif new.status = 'validado' and old.status is distinct from 'validado' then
    v := public.conta_iva_reabierto(new.company_id, new.entry_date);
    perform public._conta_iva_marcar(v, new.id, 'validado');
  elsif new.status in ('propuesto', 'borrador') then
    v := public.conta_iva_reabierto(new.company_id, new.entry_date);
    perform public._conta_iva_marcar(v, new.id, 'cambiado');
  end if;
  return null;
end $$;


--
-- Name: _conta_iva_marcar_libro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_marcar_libro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.vat_reopening;
begin
  if new.entry_id is null or public._conta_iva_exento(new.source_type, new.source_id, new.company_id) then return null; end if;
  v := public.conta_iva_reabierto(new.company_id,
         public._conta_iva_dia_del_libro(new.book, new.deduction_year, new.deduction_period, new.received_date, new.issue_date, new.operation_date));
  if v.id is null and tg_op = 'UPDATE' then
    v := public.conta_iva_reabierto(old.company_id,
           public._conta_iva_dia_del_libro(old.book, old.deduction_year, old.deduction_period, old.received_date, old.issue_date, old.operation_date));
  end if;
  perform public._conta_iva_marcar(v, new.entry_id, 'libro');
  return null;
end $$;


--
-- Name: _conta_iva_reabrir_se_puede_deshacer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_reabrir_se_puede_deshacer() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (select 1 from public.vat_reopening) then
    raise exception 'Vuelta atrás de la 1408 PARADA: hay % reaperturas del IVA (con su nueva presentación y sus asientos marcados).',
      (select count(*) from public.vat_reopening) using errcode = 'P0001';
  end if;
end $$;


--
-- Name: _conta_iva_reapertura_cerrar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_iva_reapertura_cerrar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status in ('filed', 'booked', 'paid', 'offset', 'refunded') and old.status not in ('filed', 'booked', 'paid', 'offset', 'refunded') then
    update public.vat_reopening set closed_at = now(), closed_by_name = coalesce(new.filed_by_name, public.conta_impuesto_quien())
     where new_return_id = new.id and closed_at is null;
  end if;
  return null;
end $$;


--
-- Name: channel_settlement; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.channel_settlement (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    channel_id uuid,
    brand_id uuid,
    location_id uuid,
    external_brand_text text,
    external_location_text text,
    settlement_ref text,
    period_from date,
    period_to date,
    settlement_date date,
    period_grain text,
    currency text DEFAULT 'EUR'::text NOT NULL,
    orders_count integer,
    gross_sales numeric,
    base_amount numeric,
    vat_amount numeric,
    commission numeric DEFAULT 0,
    delivery_transport numeric DEFAULT 0,
    promo_product numeric DEFAULT 0,
    promo_flash numeric DEFAULT 0,
    offer_flash_credit numeric DEFAULT 0,
    access_fee numeric DEFAULT 0,
    prime_fee numeric DEFAULT 0,
    recurring_fee numeric DEFAULT 0,
    incidents_cost numeric DEFAULT 0,
    incidents_refund numeric DEFAULT 0,
    min_order_fee numeric DEFAULT 0,
    other_cost numeric DEFAULT 0,
    net_payout numeric,
    accumulated_debt numeric,
    source text DEFAULT 'import_csv'::text NOT NULL,
    import_key text NOT NULL,
    raw jsonb,
    needs_review boolean DEFAULT false NOT NULL,
    review_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    flow_type text DEFAULT 'own'::text NOT NULL,
    is_debt_settlement boolean GENERATED ALWAYS AS (((net_payout IS NOT NULL) AND (net_payout < (0)::numeric))) STORED,
    party_id uuid,
    collected_on date,
    collected_amount numeric,
    collection_note text,
    collected_by uuid,
    collected_by_name text,
    proposed_period_from date,
    proposed_period_to date,
    proposed_period_note text,
    period_confirmed_at timestamp with time zone,
    period_confirmed_by uuid,
    journal_entry_id uuid,
    other_earnings numeric,
    promo_charges numeric,
    ads_spend numeric,
    item_promotions numeric,
    chargebacks numeric,
    adjustments numeric,
    store_id uuid,
    inbound_email_id text,
    commission_invoice_id uuid,
    is_reference boolean,
    invoice_match_status text,
    invoice_match_note text,
    CONSTRAINT channel_settlement_cobro_completo CHECK (((collected_on IS NULL) = (collected_amount IS NULL))),
    CONSTRAINT channel_settlement_flow_type_chk CHECK ((flow_type = ANY (ARRAY['own'::text, 'licensed'::text]))),
    CONSTRAINT channel_settlement_invoice_match_status_check CHECK (((invoice_match_status IS NULL) OR (invoice_match_status = ANY (ARRAY['cobradas'::text, 'a_revisar'::text])))),
    CONSTRAINT channel_settlement_periodo_propuesto CHECK ((((proposed_period_from IS NULL) = (proposed_period_to IS NULL)) AND ((proposed_period_from IS NULL) OR (proposed_period_to >= proposed_period_from))))
);


--
-- Name: COLUMN channel_settlement.party_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.party_id IS 'C03. El tercero de la plataforma (party_role platform del mismo canal).';


--
-- Name: COLUMN channel_settlement.collected_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.collected_amount IS 'C03. Lo que llegó al banco. Si no es el neto, la liquidación está «con diferencia» y la ficha dice la cifra; nunca se cuadra sola.';


--
-- Name: COLUMN channel_settlement.proposed_period_from; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.proposed_period_from IS 'C03. Periodo propuesto desde los pedidos que contiene (primero y último), «por confirmar». period_from/to no se tocan hasta confirmar.';


--
-- Name: COLUMN channel_settlement.journal_entry_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.journal_entry_id IS 'C04. El asiento de la liquidación: comisión y cargos, compensación con su 430 y, si aún no lo están, las ventas.';


--
-- Name: COLUMN channel_settlement.other_earnings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.other_earnings IS 'D01 · «Otras ganancias» del resumen (Uber): a tu favor, signo del origen.';


--
-- Name: COLUMN channel_settlement.promo_charges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.promo_charges IS 'D01 · «Otros cargos de la promoción» (Uber): va en su factura de comisión.';


--
-- Name: COLUMN channel_settlement.ads_spend; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.ads_spend IS 'D01 · «Gastos en anuncios» (Uber): va en su factura de comisión, a la cuenta de publicidad.';


--
-- Name: COLUMN channel_settlement.item_promotions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.item_promotions IS 'D01 · «Promociones en artículos» (Uber): NO va en la factura de comisión ni en los cargos del asiento. Se guarda aparte hasta que Julio decida cómo se apunta.';


--
-- Name: COLUMN channel_settlement.chargebacks; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.chargebacks IS 'D01 · «Importe neto del contracargo» (Uber): lo que la plataforma descuenta por pedidos con error.';


--
-- Name: COLUMN channel_settlement.adjustments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.adjustments IS 'D01 · «Ajustes» (Uber).';


--
-- Name: COLUMN channel_settlement.store_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.store_id IS 'D01 · La tienda de la plataforma (platform_store) de la que es la liquidación.';


--
-- Name: COLUMN channel_settlement.inbound_email_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.inbound_email_id IS 'D01 · El correo (inbound_email_log.email_id) del que se leyó.';


--
-- Name: COLUMN channel_settlement.commission_invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.commission_invoice_id IS 'D01 · Su factura de comisión (supplier_invoice). Si la tiene, el asiento de la liquidación ya no lleva la comisión: va en la factura (serie 2).';


--
-- Name: COLUMN channel_settlement.is_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.is_reference IS 'D01 · De referencia: el periodo acaba antes del corte de la contabilidad (Bancos). Sin factura de comisión ni asiento de liquidación; su cobro sí se casa.';


--
-- Name: COLUMN channel_settlement.invoice_match_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.invoice_match_status IS 'PC01 · Al cobrarla: «cobradas» (sus facturas quedaron cobradas por sus pedidos) o «a_revisar» (no cuadran: no se cobró nada solo). Vacío: sin cobrar.';


--
-- Name: COLUMN channel_settlement.invoice_match_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.channel_settlement.invoice_match_note IS 'PC01 · Lo que pasó al cobrar sus facturas, en una frase (regla 8).';


--
-- Name: _conta_liquidacion_a_facturar(public.channel_settlement); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_liquidacion_a_facturar(p_cs public.channel_settlement) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $_$
  select case when jsonb_typeof(p_cs.raw->'factura') = 'object' and (p_cs.raw->'factura'->>'total') ~ '^-?[0-9.]+$'
              then round((p_cs.raw->'factura'->>'total')::numeric, 2) end
$_$;


--
-- Name: _conta_liquidacion_cobros(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_liquidacion_cobros(p_settlement uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cs public.channel_settlement; v_n int; v_esperados int; v_sin_cierre int; v_sin_factura int; v_mal_total text;
        v_pasa text; v_motivo text; v_facturas int := 0; v_total numeric := 0; f record; v_plat text; v_via text; v_res jsonb; v_porque text;
begin
  select * into v_cs from public.channel_settlement where id = p_settlement for update;
  if v_cs.id is null then return jsonb_build_object('liquidacion', p_settlement, 'estado', 'no_existe'); end if;
  select coalesce(name, slug) into v_plat from public.sales_channel where id = v_cs.channel_id;
  if to_regclass('pg_temp._pc01_pedidos') is null then
    create temp table _pc01_pedidos (sale_id uuid, company_id uuid, location_id uuid, sales_day date, summary_id uuid, invoice_id uuid, importe numeric, via text) on commit drop;
    create temp table _pc01_antes (invoice_id uuid, importe numeric) on commit drop;
    create temp table _pc01_ahora (invoice_id uuid, importe numeric, n int) on commit drop;
  end if;
  delete from _pc01_pedidos where true; delete from _pc01_antes where true; delete from _pc01_ahora where true;
  -- Lo que esta liquidación tenía cobrado: se quita siempre, y al final se dice lo que ha cambiado.
  insert into _pc01_antes select invoice_id, sum(amount) from public.customer_invoice_payment where settlement_id = v_cs.id group by invoice_id;
  delete from public.customer_invoice_payment where settlement_id = v_cs.id;

  if v_cs.collected_on is null then
    v_res := jsonb_build_object('liquidacion', v_cs.id, 'estado', 'sin_cobrar');
    v_porque := 'la liquidación ya no está cobrada';
    update public.channel_settlement set invoice_match_status = null, invoice_match_note = null where id = v_cs.id
       and (invoice_match_status is not null or invoice_match_note is not null);
  elsif coalesce(v_cs.flow_type, '') = 'licensed' then
    -- Una liquidación de una marca cedida no cobra facturas tuyas: su dinero es del socio.
    v_res := jsonb_build_object('liquidacion', v_cs.id, 'estado', 'cedida');
    v_porque := 'es de una marca cedida';
    update public.channel_settlement set invoice_match_status = null, invoice_match_note = 'Es de una marca cedida: su dinero es del socio, no cobra facturas tuyas.' where id = v_cs.id;
  else
    insert into _pc01_pedidos select * from public.conta_liquidacion_pedidos(v_cs.id);
    select count(*), count(*) filter (where summary_id is null), count(*) filter (where summary_id is not null and invoice_id is null), max(via)
      into v_n, v_sin_cierre, v_sin_factura, v_via from _pc01_pedidos;
    -- Cuántos tenía que haber: los que dice la liquidación.
    if v_via = 'pedidos' then
      select count(*) into v_esperados from public.channel_settlement_order where settlement_id = v_cs.id and account_id = v_cs.account_id;
    else
      v_esperados := v_cs.orders_count;
    end if;
    if v_n = 0 and v_cs.brand_id is null and v_cs.store_id is not null
       and not exists (select 1 from public.platform_store where id = v_cs.store_id and brand_id is not null) then
      v_motivo := 'su tienda no tiene marca: dísela en Ventas › Liquidaciones y se cobran sus facturas';
    elsif v_n = 0 then
      v_motivo := 'no encuentro sus pedidos en Folvy';
    elsif v_esperados is null then
      v_motivo := format('no dice cuántos pedidos trae, y en Folvy hay %s: no lo doy por bueno a ciegas', v_n);
    elsif v_esperados <> v_n then
      v_motivo := format('trae %s pedidos y en Folvy hay %s', v_esperados, v_n);
    elsif v_sin_cierre > 0 then
      v_motivo := format('%s de sus %s pedidos no están en ningún cierre del día', v_sin_cierre, v_n);
    elsif v_sin_factura > 0 then
      v_motivo := format('%s de sus %s pedidos están en un cierre que aún no tiene factura (sin validar)', v_sin_factura, v_n);
    end if;
    -- Cada factura: lo que suma su cierre por pedido tiene que ser su total (si
    -- no, el reparto no sería el de su cierre), y no se cobra de más.
    if v_motivo is null then
      select string_agg(x.number_text, ', ') into v_mal_total from (
        select ci.number_text from (select distinct p.invoice_id, p.summary_id from _pc01_pedidos p) u
          join public.customer_invoice ci on ci.id = u.invoice_id
          join public.sales_day_summary sm on sm.id = u.summary_id
         where abs(ci.total - coalesce((select sum(d2.total) from public.conta_pedidos_del_dia(sm.company_id, sm.location_id, sm.sales_day) d2 where d2.id = any(sm.sale_ids)), 0)) >= 0.005
      ) x;
      if v_mal_total is not null then v_motivo := format('el cierre de %s no cuenta sus pedidos por su total', v_mal_total); end if;
    end if;
    if v_motivo is null then
      select string_agg(x.number_text, ', ') into v_pasa from (
        select ci.number_text from (select p.invoice_id, sum(p.importe) imp from _pc01_pedidos p group by p.invoice_id) u
          join public.customer_invoice ci on ci.id = u.invoice_id
         where coalesce((select sum(amount) from public.customer_invoice_payment c where c.invoice_id = ci.id), 0) + u.imp > ci.total + 0.005
      ) x;
      if v_pasa is not null then v_motivo := format('cobraría de más %s (ya tiene otros cobros por esos pedidos)', v_pasa); end if;
    end if;

    if v_motivo is not null then
      v_porque := 'la liquidación está a revisar: ' || v_motivo;
      update public.channel_settlement set invoice_match_status = 'a_revisar',
             invoice_match_note = 'A revisar: ' || v_motivo || '. No he cobrado ninguna factura.' where id = v_cs.id;
      v_res := jsonb_build_object('liquidacion', v_cs.id, 'estado', 'a_revisar', 'motivo', v_motivo, 'pedidos', v_n, 'esperados', v_esperados);
    else
      insert into _pc01_ahora select p.invoice_id, round(sum(p.importe), 2), count(*) from _pc01_pedidos p group by p.invoice_id;
      for f in select * from _pc01_ahora loop
        insert into public.customer_invoice_payment (account_id, company_id, invoice_id, paid_on, amount, method, note, settlement_id, created_by, created_by_name)
        select ci.account_id, ci.company_id, ci.id, v_cs.collected_on, f.importe, 'plataforma',
               format('%s pedido%s de la liquidación de %s del %s al %s', f.n, case when f.n = 1 then '' else 's' end, coalesce(v_plat, 'la plataforma'),
                      to_char(v_cs.period_from, 'DD/MM'), to_char(v_cs.period_to, 'DD/MM/YYYY')),
               v_cs.id, v_cs.collected_by, coalesce(v_cs.collected_by_name, 'Sumied · liquidación')
          from public.customer_invoice ci where ci.id = f.invoice_id;
        -- El historial, solo si cambia (volver a mirar una liquidación no lo repite).
        if not exists (select 1 from _pc01_antes a where a.invoice_id = f.invoice_id and a.importe = f.importe) then
          perform public._conta_venta_evento(f.invoice_id, 'cobro',
            format('Cobrados %s de %s pedido%s por la liquidación de %s del %s al %s.', public.conta_euros_exactos(f.importe), f.n, case when f.n = 1 then '' else 's' end,
                   coalesce(v_plat, 'la plataforma'), to_char(v_cs.period_from, 'DD/MM'), to_char(v_cs.period_to, 'DD/MM/YYYY')),
            jsonb_build_object('liquidacion', v_cs.id), coalesce(v_cs.collected_by_name, 'Sumied · liquidación'));
        end if;
        v_facturas := v_facturas + 1; v_total := v_total + f.importe;
      end loop;
      update public.channel_settlement set invoice_match_status = 'cobradas',
             invoice_match_note = format('Cobradas %s factura%s por %s (%s pedido%s).', v_facturas, case when v_facturas = 1 then '' else 's' end,
                                         public.conta_euros_exactos(v_total), v_n, case when v_n = 1 then '' else 's' end) where id = v_cs.id;
      v_res := jsonb_build_object('liquidacion', v_cs.id, 'estado', 'cobradas', 'facturas', v_facturas, 'importe', v_total, 'pedidos', v_n);
    end if;
  end if;

  -- Lo que tenía cobrado y ya no: se dice en su factura.
  for f in select a.* from _pc01_antes a where not exists (select 1 from _pc01_ahora n where n.invoice_id = a.invoice_id) loop
    perform public._conta_venta_evento(f.invoice_id, 'cobro_deshecho',
      format('Quitado el cobro de %s de la liquidación de %s del %s al %s: %s.', public.conta_euros_exactos(f.importe), coalesce(v_plat, 'la plataforma'),
             to_char(v_cs.period_from, 'DD/MM'), to_char(v_cs.period_to, 'DD/MM/YYYY'), coalesce(v_porque, 'ha cambiado')),
      jsonb_build_object('liquidacion', v_cs.id), coalesce(v_cs.collected_by_name, 'Sumied · liquidación'));
  end loop;
  return v_res;
end $$;


--
-- Name: FUNCTION _conta_liquidacion_cobros(p_settlement uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._conta_liquidacion_cobros(p_settlement uuid) IS 'PC01 · Cobra las facturas de una liquidación cobrada por lo que su cierre cuenta de sus pedidos, o la deja «a revisar». Quita antes lo que hubiera cobrado: se puede repetir.';


--
-- Name: _conta_liquidacion_factura_enganchar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_liquidacion_factura_enganchar(p_settlement uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cs public.channel_settlement; v_num text; v_rol uuid; v_party uuid; v_nif text; v_inv uuid;
begin
  select * into v_cs from public.channel_settlement where id = p_settlement for update;
  if v_cs.id is null or v_cs.commission_invoice_id is not null then return v_cs.commission_invoice_id; end if;
  v_num := nullif(btrim(coalesce(v_cs.raw->'factura'->>'numero', '')), '');
  if v_num is null then return null; end if;
  v_rol := public._conta_intermediario_de(v_cs.account_id, v_cs.party_id, v_cs.channel_id);
  select party_id into v_party from public.party_role where id = v_rol;
  select upper(regexp_replace(coalesce(tax_id, ''), '[^A-Za-z0-9]', '', 'g')) into v_nif from public.party where id = v_party;
  select si.id into v_inv from public.supplier_invoice si
   where si.account_id = v_cs.account_id and upper(regexp_replace(coalesce(si.invoice_number, ''), '\s', '', 'g')) = upper(regexp_replace(v_num, '\s', '', 'g'))
     and si.status not in ('anulada', 'descartada')
     and (si.supplier_id in (select r.supplier_id from public.party_role r where r.account_id = v_cs.account_id and r.party_id = v_party and r.role = 'supplier' and r.supplier_id is not null)
          or (nullif(v_nif, '') is not null and (upper(regexp_replace(coalesce(si.issuer_tax_id, ''), '[^A-Za-z0-9]', '', 'g')) = v_nif
               or exists (select 1 from public.supplier s where s.id = si.supplier_id and upper(regexp_replace(coalesce(s.tax_id, ''), '[^A-Za-z0-9]', '', 'g')) = v_nif))))
     and not exists (select 1 from public.channel_settlement o where o.commission_invoice_id = si.id and o.id <> v_cs.id)
   order by si.created_at limit 1;
  if v_inv is not null then
    update public.channel_settlement set commission_invoice_id = v_inv, updated_at = now() where id = v_cs.id;
  end if;
  return v_inv;
end $$;


--
-- Name: FUNCTION _conta_liquidacion_factura_enganchar(p_settlement uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._conta_liquidacion_factura_enganchar(p_settlement uuid) IS 'V02 · E2. Engancha a la liquidación su factura de comisión (una recibida del mismo intermediario con el número que dice la liquidación). Vacío si aún no ha llegado.';


--
-- Name: _conta_liquidacion_marcar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_liquidacion_marcar(p_settlement uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cs public.channel_settlement; v_sin boolean; v_avisos jsonb; v_n int; v_solape text; v_req jsonb;
begin
  select * into v_cs from public.channel_settlement where id = p_settlement;
  if v_cs.id is null or v_cs.store_id is null then return; end if;
  v_sin := v_cs.brand_id is null or v_cs.location_id is null;
  v_avisos := case when jsonb_typeof(v_cs.raw->'avisos') = 'array' then v_cs.raw->'avisos' else '[]'::jsonb end;
  v_n := jsonb_array_length(v_avisos);
  v_solape := public._conta_liquidacion_solape(v_cs.id);
  update public.channel_settlement set
    needs_review = v_sin or v_n > 0 or v_solape is not null,
    review_note = nullif(concat_ws(' ',
      case when v_cs.is_reference then 'De referencia: es de antes del cierre de la contabilidad; no lleva factura ni asiento, y su cobro sí se casa en Bancos.' end,
      case when v_sin then 'Tienda sin asignar: dale su marca y su local.' end,
      case when v_n > 0 then 'Por aclarar: ' || v_n || case when v_n = 1 then ' cosa no cuadra al leer.' else ' cosas no cuadran al leer.' end end,
      case when v_solape is not null then 'Por aclarar: ' || v_solape || '. Cada día cuenta una sola vez: ninguna de las dos se asienta hasta aclararlo.' end), ''),
    updated_at = now()
   where id = v_cs.id;
  if v_cs.commission_invoice_id is not null then
    v_req := coalesce((select jsonb_agg(x) from public.supplier_invoice i, jsonb_array_elements(coalesce(i.reading->'requisitos', '[]'::jsonb)) x
                        where i.id = v_cs.commission_invoice_id and x->>'id' not in ('solape', 'cuadre')), '[]'::jsonb)
             || case when v_n > 0 then jsonb_build_array(jsonb_build_object('id', 'cuadre', 'ok', false,
                  'texto', 'Por aclarar: la liquidación no cuadra al leer (' || (select string_agg(a #>> '{}', ' ') from jsonb_array_elements(v_avisos) a) || ')')) else '[]'::jsonb end
             || case when v_solape is not null then jsonb_build_array(jsonb_build_object('id', 'solape', 'ok', false,
                  'texto', 'Por aclarar: ' || v_solape || ': esta factura puede repetir cargos ya facturados.')) else '[]'::jsonb end;
    update public.supplier_invoice set reading = jsonb_set(coalesce(reading, '{}'::jsonb), '{requisitos}', v_req), updated_at = now()
     where id = v_cs.commission_invoice_id;
  end if;
end $$;


--
-- Name: _conta_liquidacion_pon_local(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_liquidacion_pon_local() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_texto text; v_tienda_local uuid;
begin
  if new.location_id is not null then return new; end if;
  -- La vuelta atrás de la 1218 quita los locales que puso: con esta marca, no se vuelven a poner.
  if current_setting('s01j2.no_poner_local', true) = '1' then return new; end if;
  select ps.external_text, ps.location_id into v_texto, v_tienda_local
    from public.platform_store ps where ps.id = new.store_id and ps.account_id = new.account_id;
  -- La tienda con su local manda (la ficha lo lee de ella): no se repite aquí.
  if v_tienda_local is not null then return new; end if;
  v_texto := coalesce(v_texto, new.external_location_text);
  if coalesce(btrim(v_texto), '') = '' then return new; end if;
  new.location_id := public._conta_local_de_texto(new.account_id, array[v_texto]);
  return new;
end $$;


--
-- Name: _conta_liquidacion_solape(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_liquidacion_solape(p_settlement uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select 'Se solapa con ' || case when count(*) = 1 then 'la liquidación del ' else count(*) || ' liquidaciones, la primera del ' end ||
         to_char(min(o.period_from), 'DD/MM') || ' al ' || to_char(min(o.period_to), 'DD/MM/YYYY')
    from public.channel_settlement c
    join public.channel_settlement o on o.account_id = c.account_id and o.store_id = c.store_id and o.id <> c.id
     and daterange(o.period_from, o.period_to, '[]') && daterange(c.period_from, c.period_to, '[]')
   where c.id = p_settlement and c.store_id is not null
  having count(*) > 0
$$;


--
-- Name: _conta_local_de_texto(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_local_de_texto(p_account uuid, p_textos text[]) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare t text; p text; v_n int; v_id uuid;
begin
  foreach t in array coalesce(p_textos, '{}'::text[]) loop
    continue when t is null or btrim(t) = '';
    foreach p in array array[regexp_replace(t, '\(.*$', ''), t] loop
      select count(distinct l.id), min(l.id::text)::uuid into v_n, v_id from public.locations l
       where l.account_id = p_account
         and ((l.address is not null and public._conta_dir_coincide(p, l.address))
              or exists (select 1 from public.location_address_alias a
                          where a.location_id = l.id and a.account_id = p_account and public._conta_dir_coincide(p, a.address)));
      if v_n = 1 then return v_id; end if;
      if v_n > 1 then return null; end if;
    end loop;
  end loop;
  return null;
end $_$;


--
-- Name: _conta_no_propuesta(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_no_propuesta(p_company uuid, p_origen text, p_origen_id text, p_que text, p_porque text, p_donde text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.conta_propuesta_pendiente (account_id, company_id, origen, origen_id, que, porque, donde)
  select c.account_id, c.id, p_origen, p_origen_id, p_que, p_porque, p_donde from public.company c where c.id = p_company
  on conflict (company_id, origen, origen_id) do update set que = excluded.que, porque = excluded.porque, donde = excluded.donde, at = now()
$$;


--
-- Name: _conta_pago_aprobado_hoy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_aprobado_hoy(p_company uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(s.amount), 0)::numeric(14,2) from public.conta_pago_salida s
   where s.company_id = p_company and s.estado not in ('cancelada', 'rechazada')
     and (s.created_at at time zone 'Europe/Madrid')::date = (now() at time zone 'Europe/Madrid')::date
$$;


--
-- Name: _conta_pago_de_la_cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_de_la_cuenta(p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.user_profiles u
                  where u.user_id = auth.uid() and u.account_id = p_account and u.active
                    and u.account_id = public._cuenta_activa())
      or public.current_user_is_admin()
$$;


--
-- Name: _conta_pago_empresa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_empresa(p_company uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v uuid;
begin
  select account_id into v from public.company where id = p_company;
  if v is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public._conta_pago_de_la_cuenta(v) then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;
  return v;
end $$;


--
-- Name: _conta_pago_evento(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_evento(p_account uuid, p_lote uuid, p_salida uuid, p_por text, p_texto text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.conta_pago_evento (account_id, lote_id, salida_id, by_name, texto)
  values (p_account, p_lote, p_salida, coalesce(p_por, 'Sumied'), p_texto)
$$;


--
-- Name: _conta_pago_factura(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_factura(p_company uuid, p_invoice uuid, p_importe numeric, p_pagar_igual_porque text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_inv public.supplier_invoice; v_s public.supplier; v_metodo text; v_iban text; v_pend numeric; v_imp numeric;
  v_chk record; v_motivos text[] := '{}'; v_topes record;
begin
  select account_id into v_acc from public.company where id = p_company;
  select * into v_inv from public.supplier_invoice where id = p_invoice and account_id = v_acc;
  if v_inv.id is null or coalesce(v_inv.company_id, p_company) <> p_company then return jsonb_build_object('porque', 'Esa factura no es de la empresa.'); end if;
  if v_inv.status <> 'aprobada' or v_inv.paid_at is not null then
    return jsonb_build_object('porque', format('La factura %s no está por pagar (está %s).', coalesce(v_inv.invoice_number, ''), case when v_inv.paid_at is not null then 'pagada' else v_inv.status end));
  end if;
  select * into v_s from public.supplier where id = v_inv.supplier_id and account_id = v_acc;
  if v_s.id is null then return jsonb_build_object('porque', format('La factura %s no tiene proveedor.', coalesce(v_inv.invoice_number, ''))); end if;
  v_metodo := coalesce(v_inv.payment_method, v_s.payment_method);
  if v_metodo in ('direct_debit', 'card', 'prepaid', 'cash', 'compensation') then
    return jsonb_build_object('porque', format('La factura %s no se paga por transferencia: %s.', coalesce(v_inv.invoice_number, ''),
      case v_metodo when 'direct_debit' then 'la paga el banco solo (domiciliada)' when 'card' then 'se paga con tarjeta'
        when 'prepaid' then 'se paga del saldo prepago' when 'compensation' then 'se compensa con su liquidación' else 'se paga en efectivo' end));
  end if;
  v_iban := public._pc01e2_iban(v_s.iban);
  if v_iban is null or not public._pc01e2b_iban_valido(v_iban) then
    return jsonb_build_object('porque', format('%s no tiene un IBAN válido en su ficha: pónselo antes de pagar.', coalesce(v_s.name, 'Su proveedor')));
  end if;
  if public._pc01e2_iban(v_inv.read_iban) is not null and v_inv.iban_decision is null and public._pc01e2_iban(v_inv.read_iban) <> v_iban then
    return jsonb_build_object('porque', format('La factura %s trae otro IBAN (···· %s) que el de la ficha de %s (···· %s): decide en su ficha si es el nuevo antes de pagarla.',
      coalesce(v_inv.invoice_number, ''), right(public._pc01e2_iban(v_inv.read_iban), 4), v_s.name, right(v_iban, 4)));
  end if;
  if public._pc01e2_cuenta_proveedor(p_company, v_s.id) is null then
    return jsonb_build_object('porque', format('%s no tiene su cuenta de proveedor (400) en el plan: sin ella el pago no tendría asiento.', v_s.name));
  end if;
  v_pend := public._conta_pago_pendiente(v_inv.id);
  v_imp := coalesce(p_importe, v_pend);
  if v_pend <= 0 then return jsonb_build_object('porque', format('A la factura %s no le queda nada por pagar fuera de remesas y pagos en marcha.', coalesce(v_inv.invoice_number, ''))); end if;
  if v_imp <= 0 or v_imp > v_pend + 0.005 then
    return jsonb_build_object('porque', format('A la factura %s le quedan %s por pagar: no se le pueden pagar %s.', coalesce(v_inv.invoice_number, ''),
      public.conta_euros_exactos(v_pend), public.conta_euros_exactos(v_imp)));
  end if;
  select * into v_chk from public._pc01e2_iban_como_esta(v_s.id, v_iban);
  if v_s.iban_unconfirmed_invoice_id is not null then v_motivos := v_motivos || 'iban_de_la_factura'::text;
  elsif v_chk.estado = 'cambiado' then v_motivos := v_motivos || 'iban_cambiado'::text;
  elsif v_chk.estado = 'primer_pago' then v_motivos := v_motivos || 'iban_nuevo'::text; end if;
  select * into v_topes from public._conta_pago_topes(p_company);
  if v_imp > v_topes.tope_pago then v_motivos := v_motivos || 'tope_pago'::text; end if;
  if nullif(trim(coalesce(p_pagar_igual_porque, '')), '') is not null then v_motivos := v_motivos || 'pagar_igual'::text; end if;
  return jsonb_build_object('porque', null, 'factura', v_inv.id, 'numero', v_inv.invoice_number, 'proveedor', v_s.id,
    'beneficiario', coalesce(nullif(trim(v_s.legal_name), ''), v_s.name), 'iban', v_iban, 'iban4', right(v_iban, 4),
    'iban_check', v_chk.estado, 'iban_nota', v_chk.nota, 'importe', v_imp, 'pendiente', v_pend,
    'concepto', left(coalesce(nullif(v_inv.invoice_number, ''), 'Factura ' || to_char(v_inv.invoice_date, 'DD/MM/YYYY')), 140),
    'motivos', to_jsonb(v_motivos));
end $$;


--
-- Name: _conta_pago_huella(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_huella(p_lote uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select encode(sha256(convert_to(
    l.id::text || '|' || l.treasury_account_id::text || '|' || l.proveedor || '|' ||
    coalesce((select string_agg(s.id::text || ':' || to_char(s.amount, 'FM999999999990.00') || ':' || s.iban || ':' || s.beneficiario, ';' order by s.id)
                from public.conta_pago_salida s where s.lote_id = l.id and s.estado <> 'cancelada'), ''), 'UTF8')), 'hex')
    from public.conta_pago_lote l where l.id = p_lote
$$;


--
-- Name: _conta_pago_motivo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_motivo(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p when 'iban_nuevo' then 'IBAN nuevo' when 'iban_cambiado' then 'IBAN cambiado' when 'iban_de_la_factura' then 'IBAN leído de la factura'
    when 'tope_pago' then 'por encima del tope por pago' when 'tope_dia' then 'por encima del tope del día'
    when 'pagar_igual' then 'pagar igual con un titular que no coincide' else p end
$$;


--
-- Name: _conta_pago_nombre(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_nombre(p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select display_name from public.user_profiles where user_id = p_user and active and display_name is not null order by created_at limit 1),
    (select email from auth.users where id = p_user), 'Una persona')
$$;


--
-- Name: _conta_pago_pagadores(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_pagadores(p_company uuid) RETURNS TABLE(user_id uuid, nombre text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.user_id, public._conta_pago_nombre(p.user_id)
    from public.conta_pago_permiso p
   where p.company_id = p_company and p.revoked_at is null and public._conta_pago_puede(p_company, p.user_id)
   order by p.granted_at
$$;


--
-- Name: _conta_pago_pendiente(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_pendiente(p_invoice uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select (coalesce((select r.pendiente from public.conta_recibida_pago r where r.invoice_id = p_invoice), 0)
          - public._pc01e2_en_remesa(p_invoice)
          - coalesce((select sum(s.amount) from public.conta_pago_salida s
                       where s.invoice_id = p_invoice and s.remesa_linea_id is null
                         and s.estado in ('esperando_segunda', 'lista', 'enviando', 'enviada', 'esperando_banco')), 0))::numeric(14,2)
$$;


--
-- Name: _conta_pago_puede(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_puede(p_company uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p_user is not null and exists (
    select 1 from public.conta_pago_permiso p
      join public.company c on c.id = p.company_id
      join public.user_profiles u on u.user_id = p.user_id and u.account_id = c.account_id and u.active
     where p.company_id = p_company and p.user_id = p_user and p.revoked_at is null)
$$;


--
-- Name: _conta_pago_puede_dar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_puede_dar(p_lote uuid, p_user uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.conta_pago_lote; v_n int;
begin
  select * into v_l from public.conta_pago_lote where id = p_lote;
  if v_l.id is null then return 'Ese pago no existe.'; end if;
  if v_l.estado <> 'esperando_segunda' then return 'Ese pago ya no espera la segunda aprobación.'; end if;
  if not public._conta_pago_puede(v_l.company_id, p_user) then return 'No tienes permiso para pagar en esta empresa.'; end if;
  select count(*) into v_n from public._conta_pago_pagadores(v_l.company_id);
  if v_n >= 2 and p_user = v_l.created_by then return 'Lo aprobaste tú: la segunda aprobación la tiene que dar otra persona que pueda pagar.'; end if;
  if v_n < 2 and p_user <> v_l.created_by then return 'La segunda aprobación la da quien lo aprobó.'; end if;
  return null;
end $$;


--
-- Name: _conta_pago_salida_de(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_salida_de(p_company uuid, p_treasury uuid) RETURNS TABLE(proveedor text, banco text, puede boolean, porque text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_t public.treasury_account; v_c public.revolut_conexion;
begin
  select * into v_t from public.treasury_account where id = p_treasury and company_id = p_company and is_active;
  if v_t.id is null then return query select null::text, null::text, false, 'Esa cuenta del banco no es de la empresa.'; return; end if;
  if not exists (select 1 from public.bank_aggregator_link b where b.treasury_account_id = p_treasury and b.company_id = p_company and b.provider = 'revolut' and b.status = 'activo') then
    return query select null::text, null::text, false, format('Desde «%s» no se puede pagar con Sumied: paga con la remesa o desde el banco.', v_t.name); return;
  end if;
  select * into v_c from public.revolut_conexion where company_id = p_company;
  if v_c.id is null or v_c.estado <> 'conectada' then
    return query select 'revolut'::text, 'Revolut'::text, false, 'Revolut no está conectado en esta empresa: conéctalo en Bancos › Cuentas y extractos.'; return;
  end if;
  if not ('PAY' = any (string_to_array(replace(coalesce(v_c.permisos, ''), ' ', ','), ','))) then
    return query select 'revolut'::text, 'Revolut'::text, false, 'Revolut está conectado solo para leer: pulsa «Activar pagos» en Bancos › Cuentas y extractos.'; return;
  end if;
  return query select 'revolut'::text, 'Revolut'::text, true, null::text;
end $$;


--
-- Name: _conta_pago_segunda_dar(uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_segunda_dar(p_lote uuid, p_user uuid, p_huella_vista text, p_via text, p_dispositivo text, p_reto uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.conta_pago_lote; v_no text; v_n int; v_nombre text := public._conta_pago_nombre(p_user);
begin
  select * into v_l from public.conta_pago_lote where id = p_lote for update;
  v_no := public._conta_pago_puede_dar(p_lote, p_user);
  if v_no is not null then return jsonb_build_object('ok', false, 'porque', v_no); end if;
  if public._conta_pago_huella(v_l.id) <> v_l.huella or v_l.huella <> lower(coalesce(p_huella_vista, '')) then
    if p_reto is not null then update public.conta_pago_reto set descartado_at = now() where id = p_reto; end if;
    return jsonb_build_object('ok', false, 'porque', 'La lista de pagos ha cambiado desde que la viste: esta confirmación ya no vale. Vuelve a abrirla.');
  end if;
  if p_reto is not null then update public.conta_pago_reto set used_at = now() where id = p_reto; end if;
  update public.conta_pago_lote set estado = 'listo', segunda_por = p_user, segunda_por_nombre = v_nombre, segunda_at = now(),
    segunda_via = p_via, segunda_dispositivo = nullif(left(trim(coalesce(p_dispositivo, '')), 80), '') where id = v_l.id;
  update public.conta_pago_salida set estado = 'lista', estado_at = now() where lote_id = v_l.id and estado = 'esperando_segunda';
  get diagnostics v_n = row_count;
  perform public._conta_pago_evento(v_l.account_id, v_l.id, null, v_nombre, format('Segunda aprobación: %s, con %s%s · %s.', v_nombre,
    case when p_via = 'llave' then 'su llave' else 'su PIN de pago' end,
    case when nullif(trim(coalesce(p_dispositivo, '')), '') is not null then ' (' || left(trim(p_dispositivo), 80) || ')' else '' end,
    (select string_agg(public._conta_pago_motivo(m), ', ') from unnest(v_l.segunda_motivos) m)));
  return jsonb_build_object('ok', true, 'lote', v_l.id, 'pagos', v_n, 'frase', format('Confirmado con %s a las %s: %s %s para mandar.',
    case when p_via = 'llave' then 'tu llave' else 'tu PIN de pago' end, to_char(now() at time zone 'Europe/Madrid', 'HH24:MI'), v_n, case when v_n = 1 then 'pago listo' else 'pagos listos' end));
end $$;


--
-- Name: _conta_pago_topes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_pago_topes(p_company uuid) RETURNS TABLE(tope_pago numeric, tope_dia numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select a.tope_pago from public.conta_pago_ajustes a where a.company_id = p_company), 3000)::numeric,
         coalesce((select a.tope_dia from public.conta_pago_ajustes a where a.company_id = p_company), 10000)::numeric
$$;


--
-- Name: _conta_periodo_de(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_periodo_de(p_cada text, p_dia date) RETURNS daterange
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case p_cada
    when 'weekly' then daterange(date_trunc('week', p_dia)::date, date_trunc('week', p_dia)::date + 6, '[]')
    when 'fortnightly' then case when extract(day from p_dia) <= 15 then daterange(date_trunc('month', p_dia)::date, date_trunc('month', p_dia)::date + 14, '[]')
                                 else daterange(date_trunc('month', p_dia)::date + 15, (date_trunc('month', p_dia) + interval '1 month')::date - 1, '[]') end
    else daterange(date_trunc('month', p_dia)::date, (date_trunc('month', p_dia) + interval '1 month')::date - 1, '[]')
  end
$$;


--
-- Name: _conta_plataforma_apuntar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_plataforma_apuntar(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v public.supplier_invoice; s jsonb; v_quien constant text := 'Folvy (apunta solo · plataforma)'; v_res jsonb; v_entry uuid;
  v_abono boolean; v_base numeric; v_iva numeric; v_total numeric; v_concepto text; v_lineas jsonb;
begin
  select * into v from public.supplier_invoice where id = p_invoice for update;
  if v.id is null then return jsonb_build_object('apuntada', false, 'motivo', 'No está.'); end if;
  if not coalesce((select ps.post_safe_invoices from public.company_purchase_setting ps where ps.company_id = v.company_id), false) then
    return jsonb_build_object('apuntada', false, 'motivo', 'La empresa tiene apagado «Apuntar solo lo que Sumied tiene seguro».');
  end if;
  s := public._conta_plataforma_seguro(v.id);
  if not coalesce((s->>'seguro')::boolean, false) then
    if s->>'motivo' not in ('No es de una plataforma.', 'Ya tiene su asiento.', 'Ya no está por revisar.') then
      insert into public.supplier_invoice_auto (invoice_id, account_id, company_id, estado, porque)
      values (v.id, v.account_id, v.company_id, 'no', s->>'motivo')
      on conflict (invoice_id) do update set estado = case when supplier_invoice_auto.estado = 'deshecha' then 'deshecha' else 'no' end,
        porque = case when supplier_invoice_auto.estado = 'deshecha' then supplier_invoice_auto.porque else excluded.porque end, at = now();
    end if;
    return jsonb_build_object('apuntada', false, 'motivo', s->>'motivo');
  end if;
  -- Deshecha por una persona: no se vuelve a apuntar sola.
  if exists (select 1 from public.supplier_invoice_auto a where a.invoice_id = v.id and a.estado = 'deshecha') then
    return jsonb_build_object('apuntada', false, 'motivo', 'Una persona la devolvió a «Por revisar»: no se apunta sola otra vez.');
  end if;
  v_abono := v.grand_total < 0;
  v_base := abs(v.tax_base_total); v_iva := abs(v.tax_total); v_total := abs(v.grand_total);
  v_concepto := format('%s %s · %s', case when v_abono then 'Abono' else 'Factura' end,
                       coalesce((select su.name from public.supplier su where su.id = v.supplier_id), s->>'plataforma'), v.invoice_number);
  v_lineas := jsonb_build_array(
    jsonb_build_object('cuenta', s->>'gasto', 'debe', case when v_abono then 0 else v_base end, 'haber', case when v_abono then v_base else 0 end,
                       'concepto', null, 'local_id', s->>'local', 'comun', false, 'tercero_id', null, 'documento', null, 'iva', null, 'retencion', null),
    jsonb_build_object('cuenta', s->>'iva_cuenta', 'debe', case when v_abono then 0 else v_iva end, 'haber', case when v_abono then v_iva else 0 end,
                       'concepto', null, 'local_id', s->>'local', 'comun', false, 'tercero_id', null, 'documento', null,
                       'iva', jsonb_build_object('tipo_id', s->>'iva_tipo', 'base', v_base, 'libro', 'received', 'deducible', 'yes', 'facturas', 1), 'retencion', null),
    jsonb_build_object('cuenta', s->>'proveedor', 'debe', case when v_abono then v_total else 0 end, 'haber', case when v_abono then 0 else v_total end,
                       'concepto', null, 'local_id', s->>'local', 'comun', false, 'tercero_id', s->>'tercero', 'documento', v.invoice_number, 'iva', null, 'retencion', null));
  begin
    if v.status = 'en_revision' then
      update public.supplier_invoice set status = 'aprobada', approved_at = now(), approved_by = null, approved_by_name = v_quien, updated_at = now() where id = v.id;
    end if;
    v_res := public._journal_entry_proponer(v.company_id,
      jsonb_build_object('series', 2, 'fecha', v.invoice_date, 'concepto', v_concepto, 'source_type', 'supplier_invoice', 'source_id', v.id,
                         'confianza', 'seguro', 'porque', s->>'porque', 'razones', jsonb_build_array(jsonb_build_object('decision', 'Apuntada sola', 'porque', s->>'porque')),
                         'party_id', s->>'tercero', 'documento', v.invoice_number),
      v_lineas, null, v_quien, null);
    v_entry := nullif(v_res->>'id', '')::uuid;
    if v_entry is null then raise exception 'no ha salido su asiento (%).', v_res; end if;
    perform public._journal_entry_validar(v_entry, v_quien);
    update public.supplier_invoice set payment_method = 'compensation', updated_at = now() where id = v.id and payment_method is distinct from 'compensation';
    perform public._conta_comision_pagar(v.id);
  exception when others then
    -- Lo que no sale, no se calla: vuelve como estaba (este bloque se deshace entero) y quien la pasa apunta su motivo (regla 8).
    raise exception using message = 'S01O_NO_SALE: ' || sqlerrm;
  end;
  insert into public.supplier_invoice_auto (invoice_id, account_id, company_id, estado, regla, porque, entry_id)
  values (v.id, v.account_id, v.company_id, 'apuntada', s->>'regla', s->>'porque', v_entry)
  on conflict (invoice_id) do update set estado = 'apuntada', regla = excluded.regla, porque = excluded.porque, entry_id = excluded.entry_id, at = now();
  return jsonb_build_object('apuntada', true, 'porque', s->>'porque', 'asiento', v_entry);
end $$;


--
-- Name: _conta_plataforma_seguro(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_plataforma_seguro(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v public.supplier_invoice; d jsonb; v_canal uuid; v_plat text; v_party uuid; v_prov text; v_gasto text; v_iva_tipo uuid; v_iva_cta text;
  cs public.channel_settlement; v_local uuid; v_num text; v_num_liq text; v_ref numeric; v_dif numeric; v_tarifa numeric := 0;
  v_ligadas numeric; v_dt text; v_por text; v_publi text; v_n_lin int := 0; v_n_pub int := 0; v_tipo text := 'comision';
begin
  select * into v from public.supplier_invoice where id = p_invoice;
  if v.id is null then return jsonb_build_object('seguro', false, 'motivo', 'No está.'); end if;
  if v.status not in ('en_revision', 'aprobada') then return jsonb_build_object('seguro', false, 'motivo', 'Ya no está por revisar.'); end if;
  if exists (select 1 from public.journal_entry e where e.account_id = v.account_id and e.source_type = 'supplier_invoice' and e.source_id = v.id and e.status in ('propuesto', 'borrador', 'validado')) then
    return jsonb_build_object('seguro', false, 'motivo', 'Ya tiene su asiento.');
  end if;
  d := public._conta_comision_datos(v.id);
  v_canal := nullif(d->>'canal', '')::uuid;
  if v_canal is null then return jsonb_build_object('seguro', false, 'motivo', 'No es de una plataforma.'); end if;
  select sc.name into v_plat from public.sales_channel sc where sc.id = v_canal and sc.account_id = v.account_id;
  v_plat := case v_plat when 'JustEat' then 'Just Eat' when 'UberEats' then 'Uber' else v_plat end;  -- su nombre para leer
  if v.invoice_number is null or v.invoice_date is null then return jsonb_build_object('seguro', false, 'motivo', 'Le falta el número o la fecha.'); end if;
  v_num := upper(regexp_replace(v.invoice_number, '[^A-Za-z0-9]', '', 'g'));
  if exists (select 1 from public.supplier_invoice o where o.account_id = v.account_id and o.id <> v.id and o.supplier_id = v.supplier_id
              and o.status not in ('anulada', 'descartada') and upper(regexp_replace(coalesce(o.invoice_number, ''), '[^A-Za-z0-9]', '', 'g')) = v_num) then
    return jsonb_build_object('seguro', false, 'motivo', 'Hay otra factura suya con el mismo número.');
  end if;
  -- La ficha: subcuenta, cuenta de gasto y tercero.
  select a.code into v_prov from public.company_account_link k join public.company_account a on a.id = k.company_account_id
   where k.account_id = v.account_id and k.company_id = v.company_id and k.entity = 'supplier' and k.entity_id = v.supplier_id::text and k.role = 'principal' limit 1;
  select a.code into v_gasto from public.company_account_link k join public.company_account a on a.id = k.company_account_id
   where k.account_id = v.account_id and k.company_id = v.company_id and k.entity = 'supplier' and k.entity_id = v.supplier_id::text and k.role = 'gasto' limit 1;
  select pr.party_id into v_party from public.party_role pr where pr.account_id = v.account_id and pr.role = 'supplier' and pr.supplier_id = v.supplier_id limit 1;
  if v_prov is null then return jsonb_build_object('seguro', false, 'motivo', format('Falta la subcuenta en la ficha de %s.', coalesce(v_plat, 'la plataforma')), 'falta_ficha', true); end if;
  -- La cuenta de gasto: SOLO la de su ficha (Julio, 01/11: «probable» no es «seguro»). Si la ficha tiene
  -- también cuenta de publicidad, la factura va a una u otra por sus líneas; si mezcla las dos, no se adivina.
  select a.code into v_publi from public.company_account_link k join public.company_account a on a.id = k.company_account_id
   where k.account_id = v.account_id and k.company_id = v.company_id and k.entity = 'supplier' and k.entity_id = v.supplier_id::text and k.role = 'publicidad' limit 1;
  if v_gasto is null then
    return jsonb_build_object('seguro', false, 'motivo', format('Falta la cuenta de gasto en la ficha de %s.', coalesce(v_plat, 'la plataforma')), 'falta_ficha', true);
  end if;
  if v_publi is not null then
    select count(*), count(*) filter (where l.raw_text ~* 'publicitari|publicidad|\mads\M|marketing') into v_n_lin, v_n_pub
      from public.supplier_invoice_line l where l.supplier_invoice_id = v.id;
    if v_n_lin > 0 and v_n_pub = v_n_lin then v_gasto := v_publi; v_tipo := 'publicidad';
    elsif v_n_pub > 0 or v_n_lin = 0 then
      return jsonb_build_object('seguro', false, 'motivo', 'No sé si es comisión o publicidad.');
    end if;
  end if;
  -- Los importes: base + IVA = total y el IVA es el 21 %.
  if v.grand_total is null or v.tax_base_total is null or v.tax_total is null
     or abs(v.tax_base_total + v.tax_total - v.grand_total) > 0.01 then
    return jsonb_build_object('seguro', false, 'motivo', 'La base más el IVA no da el total.');
  end if;
  if abs(round(v.tax_base_total * 0.21, 2) - v.tax_total) > 0.01 then
    return jsonb_build_object('seguro', false, 'motivo', 'Su IVA no es el 21 % de la base.');
  end if;
  select t.id into v_iva_tipo from public.tax_rate t
   where t.tax_system = 'iva' and t.code like 'iva\_%' and t.rate = 21 and t.valid_to is null and (t.is_system or t.account_id = v.account_id)
   order by (t.account_id = v.account_id) desc nulls last limit 1;
  select a.code into v_iva_cta from public.company_account_link k join public.company_account a on a.id = k.company_account_id
   where k.company_id = v.company_id and k.entity = 'tax_rate' and k.entity_id = v_iva_tipo::text and k.role = 'soportado' limit 1;
  if v_iva_cta is null then return jsonb_build_object('seguro', false, 'motivo', 'La empresa no tiene la cuenta del IVA soportado al 21 %.'); end if;

  select c.* into cs from public.channel_settlement_invoice k join public.channel_settlement c on c.id = k.settlement_id
   where k.supplier_invoice_id = v.id and k.account_id = v.account_id;
  if v.grand_total < 0 then
    -- Un abono: se apunta ligado o no. Con su liquidación, su local.
    if cs.id is not null then
      select coalesce(cs.location_id, ps.location_id) into v_local from public.platform_store ps where ps.id = cs.store_id;
      v_local := coalesce(v_local, cs.location_id);
    end if;
    -- Sin liquidación, el local de la propia factura (la dirección de la tienda que lee). Si la empresa
    -- pide el local en cada apunte (el eje «local»), validar no lo deja pasar sin él: se dice aquí.
    v_local := coalesce(v_local, nullif(d->>'local', '')::uuid);
    if v_local is null and exists (select 1 from public.conta_eje_analitico x where x.company_id = v.company_id and x.account_id = v.account_id and x.eje = 'local' and x.activo) then
      return jsonb_build_object('seguro', false, 'motivo', case when cs.id is null then 'Es un abono sin liquidación ligada y no dice de qué local es.' else 'Su liquidación no dice de qué local es.' end);
    end if;
    v_por := format('Abono de %s: un gasto negativo de la plataforma.%s', v_plat,
                    case when cs.id is null then ' Sin liquidación ligada.' else format(' Ligado a su liquidación del %s.', public._conta_s01o_periodo(cs.period_from, cs.period_to)) end);
    return jsonb_build_object('seguro', true, 'regla', 'abono', 'porque', v_por, 'liquidacion', cs.id, 'local', v_local,
      'proveedor', v_prov, 'gasto', v_gasto, 'tipo', v_tipo, 'iva_tipo', v_iva_tipo, 'iva_cuenta', v_iva_cta, 'tercero', v_party, 'plataforma', v_plat);
  end if;
  if cs.id is null then return jsonb_build_object('seguro', false, 'motivo', 'No está ligada a su liquidación.'); end if;
  select coalesce(cs.location_id, ps.location_id) into v_local from public.platform_store ps where ps.id = cs.store_id;
  v_local := coalesce(v_local, cs.location_id);
  if v_local is null then return jsonb_build_object('seguro', false, 'motivo', 'Su liquidación no dice de qué local es.'); end if;
  v_num_liq := upper(regexp_replace(coalesce(cs.raw->'factura'->>'numero', cs.settlement_ref, ''), '[^A-Za-z0-9]', '', 'g'));
  if v_num_liq <> '' and v_num_liq <> v_num then
    return jsonb_build_object('seguro', false, 'motivo', 'Está ligada a la liquidación de otra factura.');
  end if;
  if v_num_liq = '' then
    -- Sin número en la liquidación (Uber): ligada y cuadrando al céntimo con lo que factura.
    select coalesce(sum(si.grand_total), 0) into v_ligadas from public.channel_settlement_invoice k join public.supplier_invoice si on si.id = k.supplier_invoice_id
     where k.settlement_id = cs.id and k.account_id = v.account_id and si.status not in ('anulada', 'descartada');
    if cs.commission is null or abs(v_ligadas - abs(cs.commission)) >= 0.005 then
      return jsonb_build_object('seguro', false, 'motivo', 'Su liquidación no trae su número y no cuadra al céntimo con lo que factura.');
    end if;
    v_dt := 'cuadra al céntimo';
  else
    v_ref := nullif(cs.raw->'factura'->>'total', '')::numeric;
    if v_ref is null then v_ref := abs(cs.commission); end if;
    v_dif := round(v.grand_total - v_ref, 2);
    select coalesce(round(sum(l.line_amount * (1 + coalesce(l.vat_pct, 21) / 100.0)), 2), 0) into v_tarifa
      from public.supplier_invoice_line l where l.supplier_invoice_id = v.id and l.raw_text ~* 'tarifa recurrente';
    if abs(v_dif) <= 0.02 then
      v_dt := case when v_dif = 0 then 'cuadra al céntimo' else format('difiere en %s céntimo%s de redondeo', abs(v_dif * 100)::int, case when abs(v_dif * 100) = 1 then '' else 's' end) end;
    elsif v_tarifa > 0 and abs(v_dif - v_tarifa) <= 0.02 then
      v_dt := format('la factura incluye la tarifa recurrente (%s), que el Excel no cuenta como comisión', public.conta_euros_exactos(v_tarifa));
    else
      return jsonb_build_object('seguro', false, 'motivo', format('La factura y su liquidación difieren en %s y no es la tarifa recurrente.', public.conta_euros_exactos(v_dif)));
    end if;
  end if;
  v_por := format('Factura %s de su liquidación del %s de %s (mismo número); %s.', case when v_tipo = 'publicidad' then 'de publicidad de ' else 'de ' end || v_plat, public._conta_s01o_periodo(cs.period_from, cs.period_to),
                  coalesce((select l.name from public.locations l where l.id = v_local and l.account_id = v.account_id), 'su local'), v_dt);
  if v_num_liq = '' then
    v_por := format('Factura %s ligada a su liquidación del %s de %s; %s.', case when v_tipo = 'publicidad' then 'de publicidad de ' else 'de ' end || v_plat, public._conta_s01o_periodo(cs.period_from, cs.period_to),
                    coalesce((select l.name from public.locations l where l.id = v_local and l.account_id = v.account_id), 'su local'), v_dt);
  end if;
  return jsonb_build_object('seguro', true, 'regla', 'plataforma', 'porque', v_por, 'liquidacion', cs.id, 'local', v_local,
    'proveedor', v_prov, 'gasto', v_gasto, 'tipo', v_tipo, 'iva_tipo', v_iva_tipo, 'iva_cuenta', v_iva_cta, 'tercero', v_party, 'plataforma', v_plat);
end $$;


--
-- Name: _conta_plataformas_apuntar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_plataformas_apuntar(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; r jsonb; v_si int := 0; v_no int := 0; v_motivos jsonb := '{}'::jsonb; v_m text;
begin
  for v_id in
    select si.id from public.supplier_invoice si
      join public.party_role ps on ps.account_id = si.account_id and ps.role = 'supplier' and ps.supplier_id = si.supplier_id
      join public.party_role pl on pl.account_id = ps.account_id and pl.party_id = ps.party_id and pl.role = 'platform'
     where si.company_id = p_company and si.status in ('en_revision', 'aprobada')
       and not exists (select 1 from public.journal_entry e where e.account_id = si.account_id and e.source_type = 'supplier_invoice' and e.source_id = si.id and e.status in ('propuesto', 'borrador', 'validado'))
     order by si.invoice_date, si.id
  loop
    begin
      perform public._conta_comision_buscar(v_id);
      r := public._conta_plataforma_apuntar(v_id);
    exception when others then
      r := jsonb_build_object('apuntada', false, 'motivo', 'No ha salido su asiento: ' || regexp_replace(sqlerrm, '^S01O_NO_SALE: ', ''));
      insert into public.supplier_invoice_auto (invoice_id, account_id, company_id, estado, porque)
      select v_id, si.account_id, si.company_id, 'no', r->>'motivo' from public.supplier_invoice si where si.id = v_id
      on conflict (invoice_id) do update set porque = excluded.porque, at = now() where supplier_invoice_auto.estado <> 'deshecha';
    end;
    if (r->>'apuntada')::boolean then v_si := v_si + 1;
    else
      v_no := v_no + 1; v_m := coalesce(r->>'motivo', 'sin motivo');
      v_motivos := jsonb_set(v_motivos, array[v_m], to_jsonb(coalesce((v_motivos->>v_m)::int, 0) + 1));
    end if;
  end loop;
  return jsonb_build_object('apuntadas', v_si, 'quedan', v_no, 'motivos', v_motivos);
end $$;


--
-- Name: _conta_plataformas_apuntar_todas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_plataformas_apuntar_todas() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e uuid; v_mal text[] := '{}';
begin
  for v_e in select company_id from public.company_purchase_setting where post_safe_invoices loop
    begin perform public._conta_plataformas_apuntar(v_e);
    exception when others then v_mal := v_mal || format('%s: %s', v_e, sqlerrm); end;
  end loop;
  -- Las demás empresas ya han pasado; esto solo hace que cron la cuente como fallida (un warning lo cuenta como éxito: regla 8).
  if cardinality(v_mal) > 0 then raise exception 'S01o: la pasada ha fallado en %', array_to_string(v_mal, ' · '); end if;
end $$;


--
-- Name: _conta_proponer(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_proponer(p_company uuid, p_propuesta jsonb, p_quien text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_res jsonb;
begin
  v_res := public._journal_entry_proponer(p_company, p_propuesta->'entrada', p_propuesta->'lineas', null, coalesce(p_quien, 'Sumied'), null);
  delete from public.conta_propuesta_pendiente
   where company_id = p_company and origen = p_propuesta->'entrada'->>'source_type' and origen_id = p_propuesta->'entrada'->>'source_id';
  return v_res;
end $$;


--
-- Name: FUNCTION _conta_proponer(p_company uuid, p_propuesta jsonb, p_quien text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._conta_proponer(p_company uuid, p_propuesta jsonb, p_quien text) IS 'S01 · PR 3: una propuesta ya hecha ({entrada, lineas}, la forma de aJson) al libro por _journal_entry_proponer, y fuera su «no he podido».';


--
-- Name: supplier_expected_invoice; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_expected_invoice (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    supplier_id uuid,
    cadence text DEFAULT 'mensual'::text NOT NULL,
    typical_day smallint,
    typical_total numeric(14,2),
    label text,
    source text NOT NULL,
    reason text,
    active boolean DEFAULT true NOT NULL,
    since date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    kind text DEFAULT 'proveedor'::text NOT NULL,
    margin_days smallint,
    weekday smallint,
    gap_days smallint,
    group_label text,
    source_key text,
    match jsonb DEFAULT '{}'::jsonb NOT NULL,
    covered_by_recurring_id uuid,
    location_id uuid,
    updated_at timestamp with time zone,
    updated_by_name text,
    rhythm_set_by text,
    active_set_by text,
    location_set_by text,
    CONSTRAINT supplier_expected_invoice_cadence_check CHECK ((cadence = ANY (ARRAY['mensual'::text, 'quincenal'::text, 'semanal'::text, 'varias'::text]))),
    CONSTRAINT supplier_expected_invoice_gap_check CHECK (((gap_days IS NULL) OR ((gap_days >= 1) AND (gap_days <= 90)))),
    CONSTRAINT supplier_expected_invoice_kind_check CHECK ((kind = ANY (ARRAY['proveedor'::text, 'alquiler'::text, 'riders'::text, 'nominas'::text, 'banco'::text, 'intermediario'::text, 'otro'::text]))),
    CONSTRAINT supplier_expected_invoice_margin_check CHECK (((margin_days IS NULL) OR ((margin_days >= 0) AND (margin_days <= 60)))),
    CONSTRAINT supplier_expected_invoice_set_by_check CHECK ((((rhythm_set_by IS NULL) OR (rhythm_set_by = 'persona'::text)) AND ((active_set_by IS NULL) OR (active_set_by = 'persona'::text)) AND ((location_set_by IS NULL) OR (location_set_by = 'persona'::text)))),
    CONSTRAINT supplier_expected_invoice_source_check CHECK ((source = ANY (ARRAY['aprendido'::text, 'a_mano'::text]))),
    CONSTRAINT supplier_expected_invoice_typical_day_check CHECK (((typical_day >= 1) AND (typical_day <= 31))),
    CONSTRAINT supplier_expected_invoice_weekday_check CHECK (((weekday IS NULL) OR ((weekday >= 1) AND (weekday <= 7))))
);


--
-- Name: TABLE supplier_expected_invoice; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_expected_invoice IS 'D01 · Lo que llega todos los meses del mismo proveedor (alquiler, luz, teléfono, seguros…). Si a mitad del mes siguiente no ha llegado, sale en «Esperadas y no llegadas».';


--
-- Name: COLUMN supplier_expected_invoice.match; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_expected_invoice.match IS 'V02 · Cómo se reconoce lo que llega de una fuente sin proveedor: {"nifs":[…]}, {"numero_prefijo":"ES I"}, {"canal":"<sales_channel.id>"}, {"tesoreria":"<treasury_account.id>"}, {"nominas":true}.';


--
-- Name: COLUMN supplier_expected_invoice.covered_by_recurring_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_expected_invoice.covered_by_recurring_id IS 'V02 · Preparado para Recurrentes: si una recurrente cubre la fuente, «Lo que falta» no avisa; lo que llega de verdad se engancha a lo esperado para sustituirla (document_inbox.expected_id).';


--
-- Name: COLUMN supplier_expected_invoice.rhythm_set_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_expected_invoice.rhythm_set_by IS 'V02d · «persona» si una persona fijó cada cuánto y qué día (Aprender ya no lo recalcula). Vacío: lo aprende Sumied.';


--
-- Name: COLUMN supplier_expected_invoice.active_set_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_expected_invoice.active_set_by IS 'V02d · «persona» si una persona decidió si avisa («No me avises de este» o el interruptor). Vacío: Sumied puede apagar lo que lleva meses sin llegar.';


--
-- Name: COLUMN supplier_expected_invoice.location_set_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_expected_invoice.location_set_by IS 'V02d · «persona» si una persona puso o quitó el local. Sumied nunca cambia el local de lo que ya está apuntado.';


--
-- Name: _conta_puerta_cubre(public.supplier_expected_invoice); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_puerta_cubre(p_x public.supplier_expected_invoice) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_array(desde, hasta) order by hasta), '[]'::jsonb) from (
    select s.period_from desde, s.period_to hasta from public.bank_statement s
     where p_x.kind = 'banco' and s.account_id = p_x.account_id and s.company_id = p_x.company_id
       and (p_x.match->>'tesoreria' is null or s.treasury_account_id::text = p_x.match->>'tesoreria')
       and s.period_from is not null and s.period_to is not null and s.period_to >= current_date - 150
    union
    select coalesce((select b.cutover_date from public.bank_settings b where b.company_id = p_x.company_id), current_date - 150), l.last_sync_at::date
      from public.bank_aggregator_link l
     where p_x.kind = 'banco' and l.account_id = p_x.account_id and l.company_id = p_x.company_id and l.last_sync_at is not null
       and (p_x.match->>'tesoreria' is null or l.treasury_account_id::text = p_x.match->>'tesoreria')
  ) x
$$;


--
-- Name: _conta_puerta_cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_puerta_cuenta(p_company uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not (public.belongs_to_account(v_acc) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Esa empresa no está.' using errcode = 'P0002';
  end if;
  return v_acc;
end $$;


--
-- Name: _conta_puerta_llegadas(public.supplier_expected_invoice); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_puerta_llegadas(p_x public.supplier_expected_invoice) RETURNS date[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(array_agg(distinct d order by d), '{}'::date[]) from (
    -- De un proveedor: sus facturas (las de Sumied y las del libro de recibidas, también las traídas de Diez). Los abonos no.
    select i.invoice_date d from public.supplier_invoice i
     where i.account_id = p_x.account_id and i.status <> 'anulada' and i.invoice_date >= current_date - 150
       and coalesce(i.grand_total, 0) >= 0
       and (i.supplier_id = p_x.supplier_id
            or i.supplier_id in (select s.id from public.supplier s where s.account_id = p_x.account_id
                                    and s.tax_id = any (array(select jsonb_array_elements_text(coalesce(p_x.match->'nifs', '[]'::jsonb)))))
            or (p_x.match ? 'numero_prefijo' and i.invoice_number like (p_x.match->>'numero_prefijo') || '%'))
    union
    select v.issue_date from public.vat_book_entry v
     where v.account_id = p_x.account_id and v.company_id = p_x.company_id and v.book = 'received' and v.voided_at is null and v.issue_date >= current_date - 150
       and coalesce(v.total, 0) >= 0
       and (v.counterpart_tax_id in (select s.tax_id from public.supplier s where s.id = p_x.supplier_id)
            or v.counterpart_tax_id = any (array(select jsonb_array_elements_text(coalesce(p_x.match->'nifs', '[]'::jsonb))))
            or (p_x.match ? 'numero_prefijo' and v.number like (p_x.match->>'numero_prefijo') || '%'))
    -- Riders: la quincena de Catcher subida.
    union
    select b.period_to from public.supplier_batch b
     where p_x.kind = 'riders' and b.account_id = p_x.account_id and b.company_id = p_x.company_id and b.provider = 'catcher' and b.period_to >= current_date - 150
    -- Intermediario: sus liquidaciones (el fin de su periodo).
    union
    select coalesce(c.period_to, c.settlement_date) from public.channel_settlement c
     where p_x.kind = 'intermediario' and c.account_id = p_x.account_id and c.channel_id::text = p_x.match->>'canal'
       and coalesce(c.period_to, c.settlement_date) >= current_date - 150
    -- Banco: el día en que se subió el extracto, o la última sincronización (lo que cubren va en _conta_puerta_cubre).
    union
    select s.imported_at::date from public.bank_statement s
     where p_x.kind = 'banco' and s.account_id = p_x.account_id and s.company_id = p_x.company_id
       and (p_x.match->>'tesoreria' is null or s.treasury_account_id::text = p_x.match->>'tesoreria') and s.imported_at >= current_date - 150
    union
    select l.last_sync_at::date from public.bank_aggregator_link l
     where p_x.kind = 'banco' and l.account_id = p_x.account_id and l.company_id = p_x.company_id and l.last_sync_at is not null
       and (p_x.match->>'tesoreria' is null or l.treasury_account_id::text = p_x.match->>'tesoreria')
    -- Nóminas: el día en que llegaron.
    union
    select n.created_at::date from public.payroll_inbox n
     where p_x.kind = 'nominas' and n.account_id = p_x.account_id and n.created_at >= current_date - 150
    -- Lo que llegó por la puerta y se enganchó a esta fuente.
    union
    select coalesce(d.email_received_at, d.created_at)::date from public.document_inbox d
     where d.expected_id = p_x.id and d.status <> 'descartado'
    -- «Ya lo tengo».
    union
    select r.dia from public.conta_puerta_recibido r where r.expected_id = p_x.id
  ) x where d is not null
$$;


--
-- Name: _conta_recibida_no_antes_de_entrar(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_recibida_no_antes_de_entrar(p_company uuid, p_entry jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_fecha date := (p_entry->>'fecha')::date; v_entro date; v_nueva date; v_aviso text;
begin
  if p_entry->>'source_type' is distinct from 'supplier_invoice' or nullif(p_entry->>'source_id', '') is null then return p_entry; end if;
  select (si.created_at at time zone 'Europe/Madrid')::date into v_entro
    from public.supplier_invoice si join public.company c on c.id = p_company and c.account_id = si.account_id
   where si.id = (p_entry->>'source_id')::uuid;
  if v_entro is null or v_fecha is null or v_fecha >= v_entro then return p_entry; end if;
  v_nueva := coalesce(public.conta_primer_dia_iva_abierto(p_company, v_entro), v_entro);
  v_aviso := format('Esta factura entró el %s: se contabiliza el %s%s.', to_char(v_entro, 'DD/MM'), to_char(v_nueva, 'DD/MM'),
                    case when v_nueva <> v_entro then ', el primer día abierto' else '' end);
  return p_entry || jsonb_build_object('fecha', v_nueva, 'aviso', v_aviso,
    'razones', coalesce(p_entry->'razones', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'decision', v_aviso,
      'porque', format('Una factura recibida no se contabiliza antes del día en que entró (el %s): su IVA se deduce desde ese día, y así el asiento y su IVA caen en el mismo trimestre. Su fecha de factura no cambia.',
                       to_char(v_entro, 'DD/MM/YYYY')))));
end $$;


--
-- Name: FUNCTION _conta_recibida_no_antes_de_entrar(p_company uuid, p_entry jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._conta_recibida_no_antes_de_entrar(p_company uuid, p_entry jsonb) IS 'V04 (1350). La propuesta de una factura recibida, sin fecha anterior al día en que entró (supplier_invoice.created_at, en Madrid): si la lleva, va a ese día o al primer día abierto y sin presentar desde él, con su aviso y su razón. La usa _journal_entry_proponer.';


--
-- Name: _conta_s01o_periodo(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_s01o_periodo(p_desde date, p_hasta date) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_desde is null or p_hasta is null then 'sin periodo'
              when to_char(p_desde, 'MM') = to_char(p_hasta, 'MM') then extract(day from p_desde)::int || '–' || extract(day from p_hasta)::int || '/' || to_char(p_hasta, 'MM')
              else to_char(p_desde, 'DD/MM') || '–' || to_char(p_hasta, 'DD/MM') end
$$;


--
-- Name: _conta_tienda_direccion(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_tienda_direccion(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select nullif(btrim(split_part(coalesce(substring(p_texto from '\(([^()]*)\)\s*$'), ''), ',', 1)), '')
$_$;


--
-- Name: _conta_tienda_local_por_direccion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_tienda_local_por_direccion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.location_id is not null or new.external_text is null then return new; end if;
  new.location_id := public.conta_local_de_tienda(new.account_id, new.external_text);
  if new.location_id is null then
    -- Avisa, pero nunca impide que entre la liquidación.
    begin
      perform public.encolar_alerta(
        p_kind            => 'tienda_sin_local',
        p_subject         => 'Una tienda de plataforma no casa con ningún local',
        p_message         => format('La tienda «%s» (%s) ha llegado con una dirección que no es la de ningún local de la cuenta. Sus liquidaciones salen sin local en Ventas › Liquidaciones hasta que se le ponga.',
                                    new.external_text, coalesce(new.provider, 'plataforma')),
        p_debounce_kind   => 'tienda_sin_local:' || new.account_id::text || ':' || md5(new.external_text),
        p_debounce_window => interval '7 days',
        p_account_id      => new.account_id,
        p_severity        => 'aviso');
    exception when others then
      raise notice 'tienda_sin_local: no se pudo encolar el aviso (%)', sqlerrm;
    end;
  end if;
  return new;
end $$;


--
-- Name: _conta_tienda_nombre(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_tienda_nombre(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select nullif(btrim(regexp_replace(coalesce(p_texto, ''), '\s*\([^()]*\)\s*$', '')), '')
$_$;


--
-- Name: _conta_traspaso_en_diez(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_traspaso_en_diez(p_entry uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.source_type not in ('migrated', 'opening', 'closing', 'template')
     and (exists (select 1 from public.external_send s
                   where s.entry_id = e.id and s.account_id = e.account_id and s.status in ('enviado', 'enlazado'))
          or public._conta_traspaso_va(e.id))
    from public.journal_entry e
   where e.id = p_entry
$$;


--
-- Name: _conta_traspaso_va(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_traspaso_va(p_entry uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.status = 'validado'
     and e.source_type not in ('migrated', 'opening', 'closing', 'template')
     and not exists (select 1 from public.external_send s
                      where s.entry_id = e.id and s.account_id = e.account_id and s.status in ('enviado', 'enlazado'))
     and (e.reverses_entry_id is null or exists (
           select 1 from public.external_send x
            where x.entry_id = e.reverses_entry_id and x.account_id = e.account_id and x.status in ('enviado', 'enlazado')))
    from public.journal_entry e
   where e.id = p_entry
$$;


--
-- Name: _conta_v01_historico_factura(uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_v01_historico_factura(p_entry uuid, p_grupo text, p_serie text, p_numero integer, p_texto text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry; v_id uuid; v_cta uuid; v_local uuid; v_canal text; v_nombre text; v_doc public.journal_entry_document;
  v_base numeric; v_iva numeric; v_pos int := 0; r record;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null or v_e.status <> 'validado' then raise exception 'HISTÓRICO: el asiento % no está validado.', p_entry; end if;
  if exists (select 1 from public.customer_invoice where entry_id = p_entry) then raise exception 'HISTÓRICO: el asiento % ya tiene factura.', p_entry; end if;
  -- La cuenta de ventas: la 70x con más importe del asiento (al haber, o al debe en una devolución).
  select l.company_account_id into v_cta from public.journal_line l join public.company_account a on a.id = l.company_account_id
   where l.entry_id = p_entry and a.code like '70%' order by abs(l.credit - l.debit) desc, l.position limit 1;
  if v_cta is null then raise exception 'HISTÓRICO: el asiento % no tiene cuenta 70x.', p_entry; end if;
  select l.location_id into v_local from public.journal_line l where l.entry_id = p_entry and l.location_id is not null order by l.position limit 1;
  if p_grupo = 'cierre' then
    select ch.name, s.location_id into v_canal, v_local from public.sales_day_summary s left join public.sales_channel ch on ch.id = s.channel_id and ch.account_id = s.account_id where s.entry_id = p_entry;
    v_nombre := 'Ventas del día · ' || coalesce(v_canal, 'canal');
    select * into v_doc from public.journal_entry_document where entry_id = p_entry and kind = 'resumen_ventas';
  else
    select coalesce(nullif(btrim(counterpart_name), ''), 'Ventas a consumidor final') into v_nombre from public.vat_book_entry where entry_id = p_entry and book = 'issued' limit 1;
  end if;

  insert into public.customer_invoice (account_id, company_id, status, doc_type, origin, series_code, fiscal_year, number, number_text, issue_date, due_date,
                                       customer, location_id, notes, created_by_name)
  values (v_e.account_id, v_e.company_id, 'borrador', 'factura', 'cierre_dia', p_serie, extract(year from v_e.entry_date)::int, p_numero, p_texto, v_e.entry_date, v_e.entry_date,
          jsonb_build_object('nombre', v_nombre, 'consumidor_final', true), v_local,
          case p_grupo when 'cierre' then 'Factura resumen del cierre del día, con su número de Diez (histórico, V01).'
                       else 'Traída de Diez: su número es el de Diez (histórico, V01).' end,
          'Histórico (V01)')
  returning id into v_id;

  -- Las líneas, del libro de expedidas del asiento (base y cuota por tipo).
  for r in
    select coalesce(jl.tax_rate_id, (select t.id from public.tax_rate t where t.company_id is null and t.treatment = 'taxed' and t.rate = v.tax_rate order by t.code limit 1)) as tipo,
           v.tax_rate as pct, sum(v.tax_base) as base, sum(v.tax_amount) as cuota
      from public.vat_book_entry v left join public.journal_line jl on jl.id = v.line_id
     where v.entry_id = p_entry and v.book = 'issued'
     group by 1, 2 order by 2 desc
  loop
    if r.tipo is null then raise exception 'HISTÓRICO: el asiento % tiene IVA al % %% sin tipo que lo nombre.', p_entry, r.pct; end if;
    v_pos := v_pos + 1;
    insert into public.customer_invoice_line (account_id, company_id, invoice_id, position, concept, quantity, unit_price, discount_pct, tax_rate_id, tax_pct, revenue_account_id, amount)
    values (v_e.account_id, v_e.company_id, v_id, v_pos,
            case p_grupo when 'cierre' then format('Ventas del día al %s %%', to_char(r.pct, 'FM990D##')) else format('Ventas a consumidor final al %s %%', to_char(r.pct, 'FM990D##')) end,
            1, r.base, 0, r.tipo, r.pct, v_cta, r.base);
  end loop;
  if v_pos = 0 then raise exception 'HISTÓRICO: el asiento % no tiene anotaciones en el libro de expedidas.', p_entry; end if;
  select sum(tax_base), sum(tax_amount) into v_base, v_iva from public.vat_book_entry where entry_id = p_entry and book = 'issued';

  update public.customer_invoice set status = 'emitida', base = v_base, tax = v_iva, total = v_base + v_iva, entry_id = p_entry,
         pdf_path = v_doc.storage_path, pdf_sha256 = v_doc.sha256, pdf_bytes = v_doc.size_bytes,
         issued_at = coalesce(v_e.validated_at, now()), issued_by_name = 'Histórico (V01)'
   where id = v_id;
  insert into public.customer_invoice_event (account_id, company_id, invoice_id, kind, text, detail, by_name)
  values (v_e.account_id, v_e.company_id, v_id, 'emitida',
          case p_grupo when 'cierre' then format('Factura resumen %s del cierre ya validado (asiento nº %s), con su número de Diez y su PDF de siempre. Ya estaba en Diez: no se envía.', p_texto, v_e.number)
                       else format('Factura %s traída de Diez (asiento nº %s). Ya estaba en Diez: no se envía. Su PDF se hace desde el asiento.', p_texto, v_e.number) end,
          jsonb_build_object('asiento', p_entry, 'historico', p_grupo), 'Histórico (V01)');
  insert into public._v01_historico_facturas (invoice_id, entry_id, grupo) values (v_id, p_entry, p_grupo);
  return v_id;
end $$;


--
-- Name: _conta_venta_cifras(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_venta_cifras(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.customer_invoice; v_ret numeric := 0; v_base numeric; v_iva numeric; v_rec numeric; v_retencion numeric;
  v_tipos jsonb; v_cuentas jsonb;
begin
  select * into v_f from public.customer_invoice where id = p_id;
  if v_f.withholding_rate_id is not null then select rate into v_ret from public.withholding_rate where id = v_f.withholding_rate_id; end if;
  with l as (
    select tax_rate_id, tax_pct, coalesce(surcharge_pct, 0) as rec_pct, revenue_account_id, amount, tax_amount from public.customer_invoice_line where invoice_id = p_id
  ), t as (
    select tax_rate_id, tax_pct, rec_pct, sum(amount) as base,
           -- V01b: la cuota guardada (la del libro de su asiento), si todas las líneas del tipo la llevan.
           case when count(tax_amount) = count(*) then sum(tax_amount) else round(sum(amount) * tax_pct / 100, 2) end as iva,
           case when v_f.surcharge then round(sum(amount) * rec_pct / 100, 2) else 0 end as rec
      from l group by tax_rate_id, tax_pct, rec_pct
  )
  select coalesce(jsonb_agg(jsonb_build_object('tipo_id', tax_rate_id, 'pct', tax_pct, 'rec_pct', rec_pct, 'base', base, 'iva', iva, 'rec', rec) order by tax_pct desc), '[]'),
         coalesce(sum(base), 0), coalesce(sum(iva), 0), coalesce(sum(rec), 0)
    into v_tipos, v_base, v_iva, v_rec from t;
  select coalesce(jsonb_agg(jsonb_build_object('cuenta_id', revenue_account_id, 'base', s) order by revenue_account_id), '[]') into v_cuentas
    from (select revenue_account_id, sum(amount) s from public.customer_invoice_line where invoice_id = p_id group by revenue_account_id) x;
  v_retencion := round(v_base * coalesce(v_ret, 0) / 100, 2);
  return jsonb_build_object('base', v_base, 'iva', v_iva, 'recargo', v_rec, 'retencion', v_retencion, 'retencion_pct', coalesce(v_ret, 0),
                            'total', v_base + v_iva + v_rec - v_retencion, 'tipos', v_tipos, 'cuentas', v_cuentas);
end $$;


--
-- Name: _conta_venta_cuotas_al_emitir(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_venta_cuotas_al_emitir() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public._conta_venta_cuotas_guardar(new.id);
  return null;
end $$;


--
-- Name: _conta_venta_cuotas_de(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_venta_cuotas_de(p_id uuid) RETURNS TABLE(line_id uuid, cuota numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_f public.customer_invoice; v_libro boolean := false; r record;
begin
  select * into v_f from public.customer_invoice where id = p_id;
  if v_f.id is null or v_f.status = 'borrador' then return; end if;
  -- Ya guardada (aunque sea en parte): no se recalcula.
  if exists (select 1 from public.customer_invoice_line where invoice_id = p_id and tax_amount is not null) then return; end if;

  -- ¿Manda el libro? Una factura con su asiento, cuyo libro de expedidas
  -- tiene los mismos tipos con las mismas bases que sus líneas, y un solo
  -- tipo de la tabla por porcentaje.
  if v_f.doc_type = 'factura' and v_f.entry_id is not null
     and exists (select 1 from public.vat_book_entry where entry_id = v_f.entry_id and book = 'issued') then
    select not exists (
             select 1
               from (select tax_pct as pct, sum(amount) as base from public.customer_invoice_line where invoice_id = p_id group by tax_pct) l
               full join (select tax_rate as pct, sum(tax_base) as base from public.vat_book_entry where entry_id = v_f.entry_id and book = 'issued' group by tax_rate) b
                 on b.pct = l.pct
              where l.base is distinct from b.base)
       and not exists (
             select 1 from public.customer_invoice_line where invoice_id = p_id
              group by tax_pct having count(distinct (tax_rate_id, coalesce(surcharge_pct, 0))) > 1)
      into v_libro;
  end if;

  for r in
    select l.tax_rate_id, l.tax_pct, coalesce(l.surcharge_pct, 0) as rec_pct,
           case when v_libro
                then (select sum(v.tax_amount) from public.vat_book_entry v where v.entry_id = v_f.entry_id and v.book = 'issued' and v.tax_rate = l.tax_pct)
                else round(sum(l.amount) * l.tax_pct / 100, 2) end as cuota
      from public.customer_invoice_line l
     where l.invoice_id = p_id
     group by l.tax_rate_id, l.tax_pct, coalesce(l.surcharge_pct, 0)
  loop
    -- Cada línea, su base × tipo; lo que sobre o falte, a la de más importe.
    return query
      select z.id, z.propia + case when z.n = 1 then r.cuota - sum(z.propia) over () else 0 end
        from (select x.id, round(x.amount * x.tax_pct / 100, 2) as propia,
                     row_number() over (order by abs(x.amount) desc, x.position, x.id) as n
                from public.customer_invoice_line x
               where x.invoice_id = p_id and x.tax_rate_id = r.tax_rate_id and x.tax_pct = r.tax_pct and coalesce(x.surcharge_pct, 0) = r.rec_pct) z;
  end loop;
end $$;


--
-- Name: _conta_venta_cuotas_guardar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_venta_cuotas_guardar(p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n integer;
begin
  update public.customer_invoice_line l set tax_amount = q.cuota
    from public._conta_venta_cuotas_de(p_id) q where q.line_id = l.id;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


--
-- Name: _conta_venta_diferencia(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_venta_diferencia(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_f public.customer_invoice; v_nueva jsonb; v_vieja jsonb; v_tipos jsonb; v_cuentas jsonb; v_r jsonb;
begin
  select * into v_f from public.customer_invoice where id = p_id;
  v_vieja := public._conta_venta_cifras(v_f.corrects_id);
  if v_f.correction_kind = 'datos' then
    return jsonb_build_object('base', 0, 'iva', 0, 'recargo', 0, 'retencion', 0, 'retencion_pct', v_vieja->'retencion_pct', 'total', 0, 'tipos', '[]'::jsonb, 'cuentas', '[]'::jsonb);
  end if;
  if v_f.correction_kind = 'anular' then
    v_nueva := jsonb_build_object('base', 0, 'iva', 0, 'recargo', 0, 'retencion', 0, 'total', 0, 'tipos', '[]'::jsonb, 'cuentas', '[]'::jsonb);
  else
    v_nueva := public._conta_venta_cifras(p_id);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('tipo_id', k, 'pct', pct, 'rec_pct', rec_pct, 'base', b, 'iva', i, 'rec', r) order by pct desc), '[]')
    into v_tipos
    from (select k, max(pct) pct, max(rec_pct) rec_pct, sum(b) b, sum(i) i, sum(r) r from (
            select x->>'tipo_id' k, (x->>'pct')::numeric pct, (x->>'rec_pct')::numeric rec_pct, (x->>'base')::numeric b, (x->>'iva')::numeric i, (x->>'rec')::numeric r
              from jsonb_array_elements(v_nueva->'tipos') x
            union all
            select x->>'tipo_id', (x->>'pct')::numeric, (x->>'rec_pct')::numeric, -(x->>'base')::numeric, -(x->>'iva')::numeric, -(x->>'rec')::numeric
              from jsonb_array_elements(v_vieja->'tipos') x) u group by k) d
   where b <> 0 or i <> 0 or r <> 0;
  select coalesce(jsonb_agg(jsonb_build_object('cuenta_id', k, 'base', b) order by k), '[]') into v_cuentas
    from (select k, sum(b) b from (
            select x->>'cuenta_id' k, (x->>'base')::numeric b from jsonb_array_elements(v_nueva->'cuentas') x
            union all
            select x->>'cuenta_id', -(x->>'base')::numeric from jsonb_array_elements(v_vieja->'cuentas') x) u group by k) d
   where b <> 0;
  v_r := jsonb_build_object(
    'base', (v_nueva->>'base')::numeric - (v_vieja->>'base')::numeric,
    'iva', (v_nueva->>'iva')::numeric - (v_vieja->>'iva')::numeric,
    'recargo', (v_nueva->>'recargo')::numeric - (v_vieja->>'recargo')::numeric,
    'retencion', (v_nueva->>'retencion')::numeric - (v_vieja->>'retencion')::numeric,
    'retencion_pct', v_vieja->'retencion_pct',
    'tipos', v_tipos, 'cuentas', v_cuentas);
  return v_r || jsonb_build_object('total', (v_r->>'base')::numeric + (v_r->>'iva')::numeric + (v_r->>'recargo')::numeric - (v_r->>'retencion')::numeric);
end $$;


--
-- Name: _conta_venta_evento(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_venta_evento(p_id uuid, p_tipo text, p_texto text, p_detalle jsonb, p_quien text) RETURNS void
