--
-- Name: _cost_average_nightly(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cost_average_nightly(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row      record;
  v_antes    numeric;
  v_despues  numeric;
  v_basis    jsonb;
  v_n        integer := 0;
  v_cambios  jsonb := '[]'::jsonb;
  v_avisos   jsonb := '[]'::jsonb;
  v_fallos   jsonb := '[]'::jsonb;
  v_msg      text;
begin
  for v_row in
    select ri.id, ri.name, ri.computed_cost
      from recipe_item ri
     where ri.account_id = p_account_id
       and ri.cost_strategy = 'average_weighted'
       and ri.type in ('raw', 'tool', 'packaging')
       and ri.is_active and ri.archived_at is null
     order by ri.name
  loop
    begin
      v_antes := v_row.computed_cost;
      perform public._kitchen_recompute_raw_cost_unguarded(v_row.id);
      select computed_cost into v_despues from recipe_item where id = v_row.id;
      v_n := v_n + 1;
      if v_despues is distinct from v_antes then
        v_cambios := v_cambios || jsonb_build_object('nombre', v_row.name,
                       'antes', v_antes, 'despues', v_despues);
      end if;
      v_basis := public._article_weighted_cost(v_row.id);
      if (v_basis->>'pct_descartadas')::numeric > 20 then
        v_avisos := v_avisos || jsonb_build_object(
          'nombre', v_row.name,
          'lineas', v_basis->'lineas_ventana',
          'descartadas', v_basis->'descartadas',
          'albaranes', (select jsonb_agg(distinct l->>'albaran')
                          from jsonb_array_elements(v_basis->'lineas') l
                         where not (l->>'entra')::boolean));
      end if;
    exception when others then
      v_fallos := v_fallos || jsonb_build_object('nombre', v_row.name,
                    'error', sqlerrm, 'sqlstate', sqlstate);
    end;
  end loop;

  if jsonb_array_length(v_avisos) > 0 then
    select string_agg(format('%s: %s de %s líneas fuera de la media (%s)',
             a->>'nombre', a->>'descartadas', a->>'lineas',
             (select string_agg(x, ', ' order by x) from jsonb_array_elements_text(a->'albaranes') x)),
             E'\n' order by a->>'nombre')
      into v_msg from jsonb_array_elements(v_avisos) a;
    perform public.encolar_alerta(
      p_kind            => 'coste_medio_descartes',
      p_subject         => format('Coste medio: %s artículo(s) descartan más del 20 %% de sus compras',
                                  jsonb_array_length(v_avisos)),
      p_message         => 'El guardia deja fuera de la media las líneas que se salen más de 3× '
                           || 'de la mediana del artículo. Cuando son tantas, no es un dato raro: '
                           || 'es que el artículo se recibe con formatos distintos. Revisar el '
                           || 'casado del formato en estos albaranes:' || E'\n\n' || v_msg,
      p_debounce_kind   => 'coste_medio_descartes:' || p_account_id,
      p_debounce_window => interval '20 hours',
      p_account_id      => p_account_id,
      p_severity        => 'aviso');
  end if;

  if jsonb_array_length(v_fallos) > 0 then
    perform public.encolar_alerta(
      p_kind            => 'coste_medio_fallo',
      p_subject         => format('Coste medio: %s artículo(s) no se pudieron recalcular',
                                  jsonb_array_length(v_fallos)),
      p_message         => (select string_agg(f->>'nombre' || ': ' || (f->>'error'), E'\n')
                              from jsonb_array_elements(v_fallos) f),
      p_debounce_kind   => 'coste_medio_fallo:' || p_account_id,
      p_debounce_window => interval '20 hours',
      p_account_id      => p_account_id,
      p_severity        => 'alto');
  end if;

  return jsonb_build_object(
    'recalculados', v_n,
    'cambiados',    jsonb_array_length(v_cambios),
    'cambios',      v_cambios,
    'avisos',       jsonb_array_length(v_avisos),
    'fallos',       v_fallos);
end;
$$;


--
-- Name: _count_cadence_days(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._count_cadence_days(p_account_id uuid, p_item_id uuid, p_abc text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT CASE p_abc WHEN 'A' THEN c.days_a WHEN 'B' THEN c.days_b ELSE c.days_c END
       FROM public.count_cadence c
       JOIN public.recipe_item ri ON ri.id = p_item_id
      WHERE c.account_id = p_account_id AND c.item_type = ri.type),
    -- Sin fila: los mismos 3/7/14 que estaban en el código. Un tipo nuevo no
    -- puede dejar de contarse por no tener ajuste.
    CASE p_abc WHEN 'A' THEN 3 WHEN 'B' THEN 7 ELSE 14 END
  );
$$;


--
-- Name: FUNCTION _count_cadence_days(p_account_id uuid, p_item_id uuid, p_abc text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._count_cadence_days(p_account_id uuid, p_item_id uuid, p_abc text) IS 'Cada cuántos días vuelve a tocar contar este artículo. Sale de count_cadence por cuenta y tipo; sin fila, 3/7/14 como estaba en el código.';


--
-- Name: _count_review_context_core(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._count_review_context_core(p_count_id uuid) RETURNS TABLE(line_id uuid, prev_qty numeric, prev_counted_at timestamp with time zone, prev_by_name text, moved_since numeric, received_since numeric, sold_since numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH cab AS (
    SELECT ic.id, ic.account_id, ic.location_id
      FROM public.inventory_count ic
     WHERE ic.id = p_count_id
  ),
  lineas AS (
    SELECT l.id, l.recipe_item_id, c.account_id, c.location_id
      FROM public.inventory_count_line l
      JOIN cab c ON c.id = l.inventory_count_id
  ),
  anterior AS (
    SELECT ln.id AS line_id, p.counted_qty, p.counted_at, p.counted_by_name,
           ln.recipe_item_id, ln.location_id
      FROM lineas ln
      LEFT JOIN LATERAL (
        SELECT prev.counted_qty, prev.counted_at, prev.counted_by_name
          FROM public.inventory_count_line prev
          JOIN public.inventory_count pic ON pic.id = prev.inventory_count_id
         WHERE prev.recipe_item_id = ln.recipe_item_id
           AND prev.account_id     = ln.account_id
           AND pic.location_id     = ln.location_id
           AND pic.status          = 'aprobado'
           AND prev.counted_qty IS NOT NULL
           AND prev.counted_at  IS NOT NULL
           AND prev.id <> ln.id
         ORDER BY prev.counted_at DESC
         LIMIT 1
      ) p ON true
  )
  SELECT a.line_id, a.counted_qty, a.counted_at, a.counted_by_name,
         COALESCE(m.movido, 0), COALESCE(m.entrado, 0), COALESCE(m.vendido, 0)
    FROM anterior a
    LEFT JOIN LATERAL (
      SELECT SUM(sm.qty_base) AS movido,
             SUM(sm.qty_base) FILTER (
               WHERE sm.source_type = 'goods_receipt_line'
                  OR sm.movement_type IN ('recepcion','traspaso_entrada','apertura')) AS entrado,
             -SUM(sm.qty_base) FILTER (WHERE sm.movement_type = 'consumo') AS vendido
        FROM public.stock_movement sm
       WHERE sm.recipe_item_id = a.recipe_item_id
         AND sm.location_id    = a.location_id
         AND sm.source_type   <> 'inventory_count'
         AND sm.occurred_at    > a.counted_at
    ) m ON a.counted_at IS NOT NULL;
$$;


--
-- Name: courier; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.courier (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    employee_id uuid,
    kind text NOT NULL,
    name text NOT NULL,
    phone text,
    transport_type text,
    access_token text DEFAULT ('cour_'::text || replace((gen_random_uuid())::text, '-'::text, ''::text)),
    assigned_locations uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    active boolean DEFAULT true NOT NULL,
    on_shift boolean DEFAULT false NOT NULL,
    last_lat numeric,
    last_lng numeric,
    last_seen_at timestamp with time zone,
    cost_model text DEFAULT 'per_order'::text NOT NULL,
    cost_value numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    rate_base numeric,
    rate_per_km numeric,
    rate_min_pickup numeric,
    rate_pickup_fee numeric,
    rate_tiers jsonb,
    nif text,
    iban text,
    vehicle_plate text,
    rate_max numeric,
    CONSTRAINT courier_cost_model_check CHECK ((cost_model = ANY (ARRAY['salary'::text, 'hourly'::text, 'per_order'::text, 'per_km'::text, 'tariff'::text]))),
    CONSTRAINT courier_kind_check CHECK ((kind = ANY (ARRAY['employee'::text, 'freelance'::text]))),
    CONSTRAINT courier_kind_employee CHECK (((kind = 'employee'::text) = (employee_id IS NOT NULL))),
    CONSTRAINT courier_transport_type_check CHECK ((transport_type = ANY (ARRAY['moto'::text, 'bici'::text, 'coche'::text, 'a_pie'::text])))
);


--
-- Name: _courier_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._courier_by_token(p_token text) RETURNS public.courier
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier;
BEGIN
  SELECT * INTO c FROM public.courier WHERE access_token = p_token AND active LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'token de repartidor no válido' USING errcode = '28000';
  END IF;
  RETURN c;
END;
$$;


--
-- Name: _create_dish_from_unmapped_core(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._create_dish_from_unmapped_core(p_account_id uuid, p_product_name text, p_confirm_create boolean DEFAULT false) RETURNS TABLE(out_recipe_item_id uuid, out_marcas_creadas integer, out_creado boolean, out_candidato_id uuid, out_candidato_nombre text, out_similitud numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_norm text; v_matricula text; v_brand_id uuid; v_is_combo boolean := false;
  v_cat_name text; v_cat_price numeric; v_unit uuid; v_recipe_id uuid; v_menu_id uuid;
  v_marcas integer := 0;
  v_candidato_id uuid; v_candidato_nombre text; v_similitud numeric;
BEGIN
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'create_dish_from_unmapped: sin acceso a la cuenta %', p_account_id;
  END IF;

  v_norm := public.sales_product_norm(p_product_name);

  IF NOT p_confirm_create THEN
    SELECT ri.id, ri.name,
           round(similarity(public.normalize_ingredient_name(ri.name), v_norm)::numeric, 2)
      INTO v_candidato_id, v_candidato_nombre, v_similitud
      FROM recipe_item ri
     WHERE ri.account_id = p_account_id
       AND ri.type = 'dish'
       AND ri.is_active = true
       AND ri.archived_at IS NULL
       AND public.normalize_ingredient_name(ri.name) % v_norm
       AND similarity(public.normalize_ingredient_name(ri.name), v_norm) >= 0.6
     ORDER BY similarity(public.normalize_ingredient_name(ri.name), v_norm) DESC
     LIMIT 1;

    IF v_candidato_id IS NOT NULL THEN
      out_recipe_item_id := NULL; out_marcas_creadas := 0; out_creado := false;
      out_candidato_id := v_candidato_id; out_candidato_nombre := v_candidato_nombre;
      out_similitud := v_similitud;
      RETURN NEXT; RETURN;
    END IF;
  END IF;

  SELECT sl.external_product_id, s.brand_id INTO v_matricula, v_brand_id
  FROM sale_line sl JOIN sale s ON s.id = sl.sale_id
  WHERE sl.account_id = p_account_id AND s.source = 'lastapp'
    AND coalesce(sl.line_type,'product') = 'product'
    AND public.sales_product_norm(sl.product_name) = v_norm
  ORDER BY (sl.external_product_id IS NOT NULL) DESC, (s.brand_id IS NOT NULL) DESC
  LIMIT 1;

  IF v_matricula IS NULL THEN
    RAISE EXCEPTION 'No se pudo resolver el producto "%" (sus ventas no traen id de producto del TPV; no es casable por matrícula).', p_product_name;
  END IF;

  SELECT max(ecp.product_name) FILTER (WHERE ecp.external_channel = 'default'),
         bool_or(ecp.product_type = 'combo'),
         coalesce(max(ecp.price_cents) FILTER (WHERE ecp.external_channel = 'default'),
           (SELECT mode() WITHIN GROUP (ORDER BY ecp2.price_cents)
              FROM external_catalog_product ecp2
             WHERE ecp2.account_id = p_account_id
               AND ecp2.organization_product_id::text = v_matricula
               AND ecp2.price_cents IS NOT NULL))
    INTO v_cat_name, v_is_combo, v_cat_price
  FROM external_catalog_product ecp
  WHERE ecp.account_id = p_account_id AND ecp.organization_product_id::text = v_matricula;

  IF coalesce(v_is_combo, false) THEN
    RAISE EXCEPTION 'El producto "%" es un combo en el catálogo; su coste es la suma de sus componentes, no una receta plana. (Frente propio: combos.)', p_product_name;
  END IF;

  IF v_brand_id IS NULL THEN
    SELECT b.id INTO v_brand_id
    FROM external_catalog_product ecp
    JOIN brand b ON b.account_id = p_account_id AND b.is_active IS NOT FALSE
      AND upper(coalesce(b.name,'')) <> 'FOODINT'
      AND lower(public.unaccent(b.name)) = lower(public.unaccent(
            CASE WHEN ecp.external_brand_name = 'Dirty Burgers' THEN 'Dirty Burger'
                 ELSE ecp.external_brand_name END))
    WHERE ecp.account_id = p_account_id
      AND ecp.organization_product_id::text = v_matricula
      AND ecp.external_brand_name IS NOT NULL
    LIMIT 1;
  END IF;
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo resolver la marca de "%". Vincula la marca externa (external_brand_map) o revisa el alias de catálogo.', p_product_name;
  END IF;

  SELECT mi.id, mi.recipe_item_id INTO v_menu_id, v_recipe_id
  FROM menu_item mi
  WHERE mi.account_id = p_account_id AND mi.external_source = 'lastapp'
    AND mi.external_id = v_matricula AND mi.brand_id = v_brand_id
    AND mi.archived_at IS NULL
  LIMIT 1;

  IF v_recipe_id IS NULL THEN
    SELECT id INTO v_unit FROM kitchen_unit
    WHERE lower(coalesce(abbreviation,'')) = 'ud' OR lower(coalesce(name,'')) = 'unidad'
    ORDER BY (lower(coalesce(abbreviation,'')) = 'ud') DESC LIMIT 1;
    IF v_unit IS NULL THEN
      RAISE EXCEPTION 'No existe la unidad base "Unidad" en kitchen_unit; no se puede crear el plato.';
    END IF;

    INSERT INTO recipe_item (account_id, type, name, base_unit_id, source, needs_review, is_sellable)
    VALUES (p_account_id, 'dish', coalesce(nullif(btrim(v_cat_name),''), p_product_name),
            v_unit, 'import', true, true)
    RETURNING id INTO v_recipe_id;

    IF v_menu_id IS NULL THEN
      INSERT INTO menu_item (account_id, brand_id, channel_id, recipe_item_id, name, price,
                             product_type, external_source, external_id, source, needs_review)
      VALUES (p_account_id, v_brand_id, NULL, v_recipe_id,
              coalesce(nullif(btrim(v_cat_name),''), p_product_name),
              coalesce(v_cat_price,0)::numeric / 100.0,
              'item', 'lastapp', v_matricula, 'import', true)
      RETURNING id INTO v_menu_id;
      v_marcas := v_marcas + 1;
    ELSE
      UPDATE menu_item SET recipe_item_id = v_recipe_id WHERE id = v_menu_id;
    END IF;
  END IF;

  out_recipe_item_id := v_recipe_id; out_marcas_creadas := v_marcas; out_creado := true;
  out_candidato_id := NULL; out_candidato_nombre := NULL; out_similitud := NULL;
  RETURN NEXT;
END;
$$;


--
-- Name: _ctb_receipt_differences_core(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ctb_receipt_differences_core(p_receipt_id uuid) RETURNS TABLE(linea integer, product_name text, doc_qty numeric, qty_received numeric, diferencia numeric, dimension text, valor_eur numeric, motivo text, clase text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pct numeric;
  v_eur numeric;
begin
  -- SIN guarda de sesión, a propósito: la llaman confirm_goods_receipt (que ya
  -- validó el acceso) y la verificación de esta migración, que corre sin
  -- auth.uid(). La protección son los permisos de abajo.
  if not exists (select 1 from goods_receipt where id = p_receipt_id) then
    raise exception '_ctb_receipt_differences_core: albarán % no existe', p_receipt_id;
  end if;

  -- Si la fila de ajustes no existiera, los defaults viajan aquí: el cálculo
  -- nunca se queda sin umbral ni cae en cero (cero reclamaría cada décima).
  select coalesce(s.ctb_diff_pct, 10), coalesce(s.ctb_diff_eur, 15)
    into v_pct, v_eur
    from app_settings s where s.scope = 'global' limit 1;
  v_pct := coalesce(v_pct, 10);
  v_eur := coalesce(v_eur, 15);

  return query
  with base as (
    select grl.position, grl.product_name, grl.doc_qty, grl.qty_received,
           coalesce(btrim(grl.discrepancy_reason), '') as motivo,
           coalesce(ku.dimension, 'unit') as dim,
           -- Precio por unidad DE PAPEL: lo que el proveedor factura. Si no hay
           -- importe en el documento se cae a lo tecleado; si tampoco, null y
           -- entonces el euro no puede decidir (decide solo el %).
           case
             when grl.doc_amount is not null and grl.doc_qty is not null and grl.doc_qty <> 0
               then grl.doc_amount / grl.doc_qty
             else grl.unit_cost
           end as precio_ud
    from goods_receipt_line grl
    left join recipe_item ri on ri.id = grl.recipe_item_id
    left join kitchen_unit ku on ku.id = ri.base_unit_id
    where grl.goods_receipt_id = p_receipt_id
      and not grl.not_goods
  ),
  calc as (
    select b.*,
           case when b.doc_qty is null or b.qty_received is null
                then null else b.qty_received - b.doc_qty end as dif
    from base b
  )
  select c.position, c.product_name, c.doc_qty, c.qty_received, c.dif, c.dim,
         case when c.dif is null or c.precio_ud is null
              then null else round(abs(c.dif) * c.precio_ud, 2) end,
         nullif(c.motivo, ''),
         case
           when c.dif is null then 'no_comparable'
           when c.dif = 0 and c.motivo <> '' then 'solo_nota'
           when c.dif = 0 then 'sin_diferencia'
           -- Unidades: cualquier diferencia cuenta.
           when c.dim = 'unit' then 'diferencia'
           -- Continuas: salta el que se cumpla ANTES, el % o los euros.
           when c.doc_qty is null or c.doc_qty = 0 then 'diferencia'
           when abs(c.dif) / abs(c.doc_qty) * 100 >= v_pct then 'diferencia'
           when c.precio_ud is not null and abs(c.dif) * c.precio_ud > v_eur then 'diferencia'
           else 'ruido'
         end
  from calc c
  where not (c.dif = 0 and c.motivo = '')   -- las líneas correctas y mudas no aportan
  order by
    case when c.dif is null then 2
         when c.dif = 0 then 3
         else 1 end,
    abs(coalesce(c.dif, 0)) desc,
    c.position;
end;
$$;


--
-- Name: _cuenta_activa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cuenta_activa() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_memo text := current_setting('folvy.cuenta_activa', true);
  v_cuenta uuid;
begin
  if v_uid is null then return null; end if;
  -- Las políticas la llaman fila a fila: se calcula una vez por transacción y
  -- usuario, y se guarda en un ajuste local de la transacción (con el usuario
  -- delante, por si cambia dentro de la misma). Medido el 30/10: sin esto, las
  -- consultas de ventas tardaban entre el doble y el triple.
  if v_memo like v_uid::text || ':%' then
    return nullif(split_part(v_memo, ':', 2), '')::uuid;
  end if;
  select coalesce(
    (select a.account_id
       from public.user_active_account a
       join public.user_profiles up on up.user_id = a.user_id and up.account_id = a.account_id and up.active
      where a.user_id = v_uid),
    (select up.account_id
       from public.user_profiles up
      where up.user_id = v_uid and up.active and up.account_id is not null
      order by up.created_at, up.account_id
      limit 1)) into v_cuenta;
  perform set_config('folvy.cuenta_activa', v_uid::text || ':' || coalesce(v_cuenta::text, ''), true);
  return v_cuenta;
end $$;


--
-- Name: FUNCTION _cuenta_activa(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._cuenta_activa() IS 'DM1 (30/10/2026). La cuenta abierta de quien llama: la guardada si sigue siendo miembro activo; si no, la más antigua. NULL sin usuario. Se calcula una vez por transacción (folvy.cuenta_activa).';


--
-- Name: _delivery_zone_account_of_location(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._delivery_zone_account_of_location(p_location_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select account_id from public.locations where id = p_location_id;
$$;


--
-- Name: _distancia_metros(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._distancia_metros(p_lat1 double precision, p_lng1 double precision, p_lat2 double precision, p_lng2 double precision) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when p_lat1 is null or p_lng1 is null or p_lat2 is null or p_lng2 is null then null
    else round(2 * 6371000 * asin(sqrt(
      power(sin(radians(p_lat2 - p_lat1) / 2), 2)
      + cos(radians(p_lat1)) * cos(radians(p_lat2)) * power(sin(radians(p_lng2 - p_lng1) / 2), 2))))::integer end
$$;


--
-- Name: _documento_trabajador_puede(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._documento_trabajador_puede(p_name text, p_escribir boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_partes text[] := storage.foldername(p_name); v_uno text; v_dos text; v_emp uuid; v_cuenta uuid;
begin
  v_uno := v_partes[1]; v_dos := v_partes[2];
  if v_uno = '_inbox' then
    if v_dos is null or v_dos !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return public.current_user_is_admin(); end if;
    v_cuenta := v_dos::uuid;
    -- L1a: la bandeja de nóminas, solo el administrador (lee y escribe).
    return public.current_user_is_admin_of(v_cuenta);
  end if;
  if v_uno is null or v_uno !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return public.current_user_is_admin(); end if;
  v_emp := v_uno::uuid;
  select e.account_id into v_cuenta from public.employees e where e.id = v_emp;
  if v_cuenta is null then return public.current_user_is_admin(); end if;
  if p_escribir then return public.current_user_is_admin_of(v_cuenta); end if;
  return public.current_user_is_admin_of(v_cuenta) or public.current_user_is_employee(v_emp, v_cuenta);
end $_$;


--
-- Name: _employee_pin_guardar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._employee_pin_guardar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if nullif(btrim(new.pin), '') is not null then
    insert into public.employee_kiosk_pin (employee_id, pin, updated_at)
    values (new.id, btrim(new.pin), now())
    on conflict (employee_id) do update set pin = excluded.pin, updated_at = now();
  end if;
  new.pin := null;
  return new;
end $$;


--
-- Name: _eur_base_from_format(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._eur_base_from_format(p_format_id uuid, p_price_per_format numeric) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_price_per_format IS NULL THEN NULL
    ELSE p_price_per_format / NULLIF(f.qty_in_base, 0)
  END
  FROM recipe_item_purchase_format f
  WHERE f.id = p_format_id AND f.is_active;
$$;


--
-- Name: _extra_nombre_normalizado(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._extra_nombre_normalizado(p_nombre text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  SELECT regexp_replace(
           regexp_replace(
             btrim(lower(public.unaccent(coalesce(p_nombre, '')))),
           '\.$', ''),
         '\s+', ' ', 'g');
$_$;


--
-- Name: _extras_group_options(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._extras_group_options(p_account_id uuid, p_clave text) RETURNS TABLE(option_id uuid, external_id text, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT mo.id, public._modifier_option_ref(mo.id), mo.name
    FROM public.modifier_option mo
   WHERE mo.account_id = p_account_id
     AND mo.is_active
     AND lower(btrim(mo.name)) = p_clave;
$$;


--
-- Name: FUNCTION _extras_group_options(p_account_id uuid, p_clave text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._extras_group_options(p_account_id uuid, p_clave text) IS 'Las copias de un extra en la cuenta, agrupadas por NOMBRE normalizado, con su referencia de canal EFECTIVA (la misma que publica hubrise-catalog-publish). NULL en marca cedida: alli la carta la manda el canal.';


--
-- Name: _f01_alta_marca(uuid, uuid, text, text, boolean, text, boolean, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_alta_marca(p_account uuid, p_org uuid, p_nombre_last text, p_nombre text, p_propia boolean, p_socio text, p_ensayo boolean, p_quien uuid, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_last    text := btrim(coalesce(p_nombre_last, ''));
  v_nombre  text := btrim(coalesce(nullif(btrim(p_nombre), ''), p_nombre_last));
  v_socio   text := nullif(btrim(coalesce(p_socio, '')), '');
  v_brand   uuid;
  v_nueva   boolean := false;
  v_slug    text;
  v_n       integer := 1;
  v_vinc    jsonb;
  v_carta   jsonb;
  v_ventas  jsonb;
begin
  if v_last = '' then raise exception 'Falta la marca de Last.' using errcode = '22023'; end if;
  if v_nombre = '' then raise exception 'Falta el nombre de la marca.' using errcode = '22023'; end if;
  if p_propia is null then raise exception 'Falta decir si la marca es tuya o cedida.' using errcode = '22023'; end if;
  if not p_propia and v_socio is null then raise exception 'Una marca cedida necesita su socio.' using errcode = '22023'; end if;
  if not exists (select 1 from public.external_integration ei where ei.account_id = p_account and ei.source = 'lastapp'
                  and ei.external_org_id = p_org and ei.is_active) then
    raise exception 'Esa cuenta de Last no está conectada.' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public._f01_filas(p_account, p_org, v_last)) then
    raise exception 'La marca «%» ya no está en las cartas de Last.', v_last using errcode = 'P0002';
  end if;

  -- La marca: la del alta, la vinculada o la que se llama igual; si no hay, una nueva.
  v_brand := coalesce(public._f01_marca_vinculada(p_account, p_org, v_last), public._f01_marca_por_nombre(p_account, v_nombre),
                      public._f01_marca_por_nombre(p_account, v_last));
  if v_brand is null then
    v_nueva := true;
    if not p_ensayo then
      v_slug := coalesce(nullif(btrim(regexp_replace(lower(public.unaccent(v_nombre)), '[^a-z0-9]+', '-', 'g'), '-'), ''), 'marca');
      while exists (select 1 from public.brand b where b.account_id = p_account and b.slug = case when v_n = 1 then v_slug else v_slug || '-' || v_n end) loop
        v_n := v_n + 1;
      end loop;
      insert into public.brand (account_id, name, slug, ownership_type, is_active, catalog_source, created_by, created_by_name)
      values (p_account, v_nombre, case when v_n = 1 then v_slug else v_slug || '-' || v_n end,
              case when p_propia then 'own' else 'licensed' end, true, 'pos',
              -- brand.created_by apunta a employees: solo si quien da el alta es un empleado de la cuenta.
              (select e.id from public.employees e where e.id = p_quien and e.account_id = p_account), p_quien_nombre)
      returning id into v_brand;
    end if;
  elsif not p_ensayo then
    update public.brand set ownership_type = case when p_propia then 'own' else 'licensed' end, is_active = true, updated_at = now()
     where id = v_brand and (ownership_type is distinct from case when p_propia then 'own' else 'licensed' end or not is_active);
  end if;

  if not p_ensayo then
    -- De quién es: el socio de una cedida, en su ficha (el porcentaje, cuando se sepa).
    if not p_propia then
      insert into public.brand_licensing_agreement (account_id, brand_id, owner_name, revenue_share_pct, is_active, created_by, created_by_name)
      values (p_account, v_brand, v_socio, null, true, p_quien, p_quien_nombre)
      on conflict (brand_id) do update set owner_name = excluded.owner_name, is_active = true, archived_at = null, updated_at = now();
    end if;
    -- Darla de alta es usarla: si estaba entre las ocultas, deja de estarlo.
    delete from public.external_brand_oculta
     where account_id = p_account and source = 'lastapp' and external_org_id = p_org and external_brand_name = v_last;
    insert into public.external_brand_alta (account_id, source, external_org_id, external_brand_name, brand_id, created_by, created_by_name)
    values (p_account, 'lastapp', p_org, v_last, v_brand, p_quien, p_quien_nombre)
    on conflict (account_id, source, external_org_id, external_brand_name) do update set brand_id = excluded.brand_id;
  end if;

  -- En ensayo con marca nueva, v_brand es null: se lee igual (nada de la marca existe todavía).
  v_vinc  := public._f01_vincular(p_account, v_brand, p_org, v_last, p_ensayo, p_quien_nombre);
  v_carta := public._f01_sembrar_marca(p_account, v_brand, p_org, v_last, p_ensayo, p_quien_nombre);
  v_ventas := case when p_ensayo then null else public._f01_recolocar(p_account, v_brand, p_org, v_last) end;

  return jsonb_build_object(
    'brand_id', v_brand, 'nombre', v_nombre, 'nueva', v_nueva, 'propia', p_propia, 'socio', case when p_propia then null else v_socio end,
    'ensayo', p_ensayo, 'locales', coalesce(v_vinc->'locales', '[]'::jsonb), 'canales', coalesce(v_vinc->'canales', '[]'::jsonb),
    'vinculos_nuevos', coalesce((v_vinc->>'vinculos_nuevos')::integer, 0), 'vinculos_de_otra_marca', coalesce(v_vinc->'vinculos_de_otra_marca', '[]'::jsonb),
    'carta', v_carta, 'ventas', v_ventas);
end $$;


--
-- Name: external_catalog_product; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_catalog_product (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    external_org_id uuid NOT NULL,
    catalog_product_id uuid NOT NULL,
    organization_product_id uuid,
    external_catalog_id uuid,
    external_brand_name text,
    product_name text,
    price_cents integer,
    product_type text,
    is_enabled boolean,
    seen_in_catalog_at timestamp with time zone,
    seen_in_sale_at timestamp with time zone,
    needs_review boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    external_channel text,
    source text DEFAULT 'lastapp'::text NOT NULL,
    external_location_id uuid,
    disabled_since timestamp with time zone,
    missing_since timestamp with time zone,
    last_synced_at timestamp with time zone,
    disabled_since_known boolean DEFAULT true NOT NULL,
    catalog_name text,
    external_channels text[],
    external_brand_id text
);


--
-- Name: COLUMN external_catalog_product.external_location_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_catalog_product.external_location_id IS 'Location (Last) del catálogo; header locationID para los endpoints de catálogo/pedidos. La rellena lastapp-sync-catalog.';


--
-- Name: COLUMN external_catalog_product.catalog_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_catalog_product.catalog_name IS 'Nombre del catalogo en Last (p.ej. "SMASH BROTHERS BURGER 20"). Lo escribe lastapp-sync-catalog.';


--
-- Name: COLUMN external_catalog_product.external_channels; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_catalog_product.external_channels IS 'TODOS los destinos del catalogo, ordenados (local, delivery, glovo, uber...). external_channel es solo el primero, y se conserva por compatibilidad.';


--
-- Name: COLUMN external_catalog_product.external_brand_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_catalog_product.external_brand_id IS 'F01: el id de la marca de Last en este local (brands[].id de /locations/{id}), el mismo que external_brand_map.external_brand_id. Lo escribe last-catalog-sync.';


--
-- Name: _f01_filas(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_filas(p_account uuid, p_org uuid, p_nombre text) RETURNS SETOF public.external_catalog_product
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.* from public.external_catalog_product e
   where e.account_id = p_account and e.source = 'lastapp' and e.external_org_id = p_org
     and btrim(e.external_brand_name) = btrim(p_nombre)
     and e.missing_since is null
     and e.seen_in_catalog_at >= (select max(x.seen_in_catalog_at) - interval '1 day' from public.external_catalog_product x
                                   where x.account_id = p_account and x.external_org_id = p_org)
$$;


--
-- Name: _f01_marca_por_nombre(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_marca_por_nombre(p_account uuid, p_nombre text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select b.id from public.brand b
   where b.account_id = p_account and b.archived_at is null
     and public._f01_normalizar(b.name) = public._f01_normalizar(case when btrim(p_nombre) = 'Dirty Burgers' then 'Dirty Burger' else p_nombre end)
   order by b.is_active desc, b.created_at
   limit 1
$$;


--
-- Name: _f01_marca_vinculada(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_marca_vinculada(p_account uuid, p_org uuid, p_nombre text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select a.brand_id from public.external_brand_alta a
      where a.account_id = p_account and a.source = 'lastapp' and a.external_org_id = p_org and a.external_brand_name = btrim(p_nombre)),
    (select m.brand_id from public.external_brand_map m
      where m.account_id = p_account and m.source = 'lastapp' and not m.is_ignored
        and m.brand_id = public._f01_marca_por_nombre(p_account, p_nombre)
        and m.external_location_id in (select e.external_location_id::text from public.external_catalog_product e
                                        where e.account_id = p_account and e.external_org_id = p_org and btrim(e.external_brand_name) = btrim(p_nombre))
      limit 1))
$$;


--
-- Name: _f01_marcas_last(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_marcas_last(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb;
begin
  with fotos as (
    select x.external_org_id as org, max(x.seen_in_catalog_at) as ultima
      from public.external_catalog_product x where x.account_id = p_account group by x.external_org_id
  ),
  vivas as (
    -- Una fila por (cuenta de Last, marca, local de Folvy ACTIVO), de una cuenta de Last encendida.
    select e.external_org_id as org, btrim(e.external_brand_name) as nombre, l.id as loc_id, l.name as loc_nombre,
           e.external_location_id::text as loc_last, e.external_brand_id as ext,
           e.organization_product_id, e.product_name, coalesce(e.external_channels, array[e.external_channel]) as canales,
           e.is_enabled
      from public.external_catalog_product e
      join public.external_integration ei on ei.account_id = e.account_id and ei.source = 'lastapp'
           and ei.external_org_id = e.external_org_id and ei.is_active
      join public.external_location_map lm on lm.account_id = e.account_id and lm.source = 'lastapp'
           and lm.external_location_id = e.external_location_id::text and lm.is_active
      join public.locations l on l.id = lm.location_id and l.account_id = e.account_id and l.active
      join fotos fo on fo.org = e.external_org_id
     where e.account_id = p_account and e.source = 'lastapp' and e.missing_since is null
       and nullif(btrim(e.external_brand_name), '') is not null and btrim(e.external_brand_name) <> 'FOODINT'
       and e.seen_in_catalog_at >= fo.ultima - interval '1 day'
  ),
  -- Las matrículas que están en más de una marca (bebidas, postres): no dicen de quién es una venta.
  compartidas as (
    select x.organization_product_id from public.external_catalog_product x
     where x.account_id = p_account and x.organization_product_id is not null
     group by x.organization_product_id having count(distinct btrim(x.external_brand_name)) > 1
  ),
  marcas as (
    select v.org, v.nombre,
           jsonb_agg(distinct jsonb_build_object('id', v.loc_id, 'nombre', v.loc_nombre)) as locales,
           (select coalesce(jsonb_agg(distinct c), '[]'::jsonb) from vivas v2 cross join lateral unnest(v2.canales) c
             where v2.org = v.org and v2.nombre = v.nombre and c in ('uber', 'glovo', 'justeat', 'deliveroo', 'shop')) as canales,
           count(distinct public._f01_normalizar(v.product_name)) filter (where v.organization_product_id is not null) as platos,
           -- Un local con su id de marca que Folvy ignora a propósito.
           bool_or(exists (select 1 from public.external_brand_map m where m.account_id = p_account and m.source = 'lastapp'
                             and m.external_location_id = v.loc_last and m.external_brand_id = v.ext and m.is_ignored)) as ignorada,
           -- ¿Algún plato encendido en alguna de sus tiendas con local activo?
           bool_or(coalesce(v.is_enabled, true)) as alguna_activa,
           -- Sus matrículas propias: con ellas se sabe si ha vendido, aunque no esté dada de alta.
           array_agg(distinct v.organization_product_id::text) filter (
             where v.organization_product_id is not null and v.organization_product_id not in (select c.organization_product_id from compartidas c)) as propias
      from vivas v group by v.org, v.nombre
  ),
  con_marca as (
    select m.*, public._f01_marca_vinculada(p_account, m.org, m.nombre) as vinculada,
           public._f01_marca_por_nombre(p_account, m.nombre) as por_nombre,
           ei.organization_name, ei.ownership_type,
           o.created_at as oculta_el, o.created_by_name as oculta_por
      from marcas m
      join public.external_integration ei on ei.account_id = p_account and ei.source = 'lastapp' and ei.external_org_id = m.org
      left join public.external_brand_oculta o on o.account_id = p_account and o.source = 'lastapp'
           and o.external_org_id = m.org and o.external_brand_name = m.nombre
  ),
  -- La última venta: por su marca de Folvy, si la tiene, o por sus matrículas propias.
  con_venta as (
    select cm.*,
           greatest(
             (select max(s.sold_at) from public.sale s where s.account_id = p_account and s.source = 'lastapp'
                and s.brand_id = coalesce(cm.vinculada, cm.por_nombre)),
             (select max(s.sold_at) from public.sale_line sl join public.sale s on s.id = sl.sale_id and s.account_id = sl.account_id
               where sl.account_id = p_account and sl.external_source = 'lastapp' and sl.external_product_id = any (coalesce(cm.propias, '{}')))) as ultima_venta
      from con_marca cm
  ),
  -- El socio que se propone: el de las otras marcas de la misma cuenta de Last
  -- (su ficha; si no la tienen, la factura de sus pedidos de Last).
  socios as (
    select c.org, x.socio, count(distinct x.brand_id) as marcas
      from (select distinct org from con_marca) c
      cross join lateral (
        select coalesce(a.owner_name,
                 (select public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' from public.sale s
                   where s.account_id = p_account and s.brand_id = b.id and s.sold_at > now() - interval '90 days'
                     and public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' is not null
                   order by s.sold_at desc limit 1)) as socio, b.id as brand_id
          from con_marca cm
          join public.brand b on b.id = cm.vinculada and b.ownership_type = 'licensed' and b.is_active
          left join public.brand_licensing_agreement a on a.brand_id = b.id and a.account_id = p_account and a.is_active
         where cm.org = c.org) x
     where x.socio is not null
     group by c.org, x.socio
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'org', cm.org,
           'cuenta_last', cm.organization_name,
           'nombre', cm.nombre,
           'estado', case when cm.ignorada then 'ignorada'
                          when cm.vinculada is not null then 'vinculada'
                          when cm.oculta_el is not null then 'oculta'
                          when cm.por_nombre is not null then 'sin_vincular'
                          else 'nueva' end,
           -- Tiene pinta de cancelada: sin ventas en 90 días y sin un plato encendido en sus tiendas.
           -- No se esconde: sale abajo y lo decide el cliente («No la uso»).
           'apagada', (cm.ultima_venta is null or cm.ultima_venta < now() - interval '90 days') and not cm.alguna_activa,
           'ultima_venta', cm.ultima_venta,
           'oculta_el', cm.oculta_el,
           'oculta_por', cm.oculta_por,
           'brand_id', coalesce(cm.vinculada, cm.por_nombre),
           'marca_folvy', (select b.name from public.brand b where b.id = coalesce(cm.vinculada, cm.por_nombre)),
           'locales', cm.locales,
           'canales', cm.canales,
           'platos', cm.platos,
           'ventas', (select count(*) from public.sale s where s.account_id = p_account and s.brand_id = coalesce(cm.vinculada, cm.por_nombre)),
           'propuesta', jsonb_build_object(
              'propia', cm.ownership_type is distinct from 'licensed',
              -- Si ninguna otra marca de esa cuenta de Last lo dice, el nombre de la cuenta (si es de cedidas).
              'socio', coalesce((select so.socio from socios so where so.org = cm.org order by so.marcas desc, so.socio limit 1),
                                case when cm.ownership_type = 'licensed' then cm.organization_name end),
              'socio_marcas', coalesce((select so.marcas from socios so where so.org = cm.org order by so.marcas desc, so.socio limit 1), 0)))
         order by (cm.vinculada is null and not cm.ignorada and cm.oculta_el is null) desc,
                  ((cm.ultima_venta is null or cm.ultima_venta < now() - interval '90 days') and not cm.alguna_activa),
                  cm.nombre), '[]'::jsonb)
    into v
    from con_venta cm;
  return v;
end $$;


--
-- Name: _f01_normalizar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_normalizar(p text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select nullif(btrim(regexp_replace(regexp_replace(lower(public.unaccent(coalesce(p, ''))), '[^a-z0-9]+', ' ', 'g'), '\s+', ' ', 'g')), '')
$$;


--
-- Name: _f01_recolocar(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_recolocar(p_account uuid, p_brand uuid, p_org uuid, p_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_corte   timestamptz;
  v_id      uuid;
  v_hechas  integer := 0;
  v_fallos  integer := 0;
  v_debajo  integer := 0;
begin
  select max(ic.closed_at) into v_corte from public.inventory_count ic
   where ic.account_id = p_account and ic.status in ('aprobado', 'en_revision');

  for v_id in
    with matriculas as (
      select distinct f.organization_product_id::text as m from public._f01_filas(p_account, p_org, p_nombre) f
       where f.organization_product_id is not null),
    ids as (
      select distinct f.external_brand_id as e from public._f01_filas(p_account, p_org, p_nombre) f where f.external_brand_id is not null),
    ventas as (
      select s.id, s.sold_at from public.sale s
       where s.account_id = p_account and s.source = 'lastapp' and s.raw_products is not null
         and (exists (select 1 from public.sale_line sl
                       where sl.sale_id = s.id and sl.account_id = p_account and sl.menu_item_id is null
                         and coalesce(sl.unmapped_reason, '') in ('no_brand', 'no_menu_item', 'no_recipe')
                         and sl.external_product_id in (select m from matriculas))
              or (s.brand_id is null and s.external_brand_text in (select e from ids))))
    select v.id from ventas v where v_corte is null or v.sold_at > v_corte order by v.sold_at
  loop
    begin
      perform public.reprocess_sale(v_id);
      v_hechas := v_hechas + 1;
    exception when others then
      v_fallos := v_fallos + 1;
      raise warning 'F01: no se ha podido colocar la venta %: %', v_id, sqlerrm;
    end;
  end loop;

  if v_corte is not null then
    select count(distinct s.id) into v_debajo from public.sale s
      join public.sale_line sl on sl.sale_id = s.id and sl.account_id = p_account
     where s.account_id = p_account and s.source = 'lastapp' and s.sold_at <= v_corte and sl.menu_item_id is null
       and coalesce(sl.unmapped_reason, '') in ('no_brand', 'no_menu_item', 'no_recipe')
       and sl.external_product_id in (select f.organization_product_id::text from public._f01_filas(p_account, p_org, p_nombre) f);
  end if;

  return jsonb_build_object('colocadas', v_hechas, 'fallidas', v_fallos, 'antes_del_recuento', v_debajo, 'corte', v_corte);
end $$;


--
-- Name: _f01_sembrar_marca(uuid, uuid, uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_sembrar_marca(p_account uuid, p_brand uuid, p_org uuid, p_nombre text, p_ensayo boolean, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ud        uuid;
  v_p         record;
  v_c         record;
  v_mi        uuid;
  v_ri        uuid;
  v_tipo      text;
  v_origen    text;
  v_vistos    jsonb := '{}'::jsonb;    -- nombre normalizado → artículo (o 'ensayo')
  v_nombres   jsonb := '{}'::jsonb;    -- nombre normalizado → el primer nombre visto
  v_con       text;
  v_platos    jsonb := '{}'::jsonb;    -- nombre normalizado → cómo queda: almacen | receta | sin_receta
  v_norm      text;
  v_matr      integer := 0;
  v_ya        integer := 0;
  v_creados   integer := 0;
  v_enlazados integer := 0;
  v_juntados  jsonb := '[]'::jsonb;
  v_almacen   jsonb := '[]'::jsonb;
  v_archiv    jsonb := '[]'::jsonb;
  v_over      integer := 0;
  v_base      integer;
begin
  -- La unidad «ud»: la global si la hay (producción); si no, la de la cuenta (staging).
  select u.id into v_ud from public.kitchen_unit u
   where (u.account_id is null or u.account_id = p_account) and u.dimension = 'unit' and u.is_base and u.is_active
   order by (u.account_id is null) desc, u.is_seed desc, u.created_at limit 1;

  for v_p in
    select f.organization_product_id::text as matricula,
           btrim(coalesce(max(f.product_name) filter (where f.external_channel = 'default'), max(f.product_name))) as nombre,
           coalesce(max(f.price_cents) filter (where f.external_channel = 'default'),
                    mode() within group (order by f.price_cents)) as base_cents
      from public._f01_filas(p_account, p_org, p_nombre) f
     where f.organization_product_id is not null
     group by f.organization_product_id
     order by 2, 1
  loop
    v_matr := v_matr + 1;
    v_norm := coalesce(public._f01_normalizar(v_p.nombre), v_p.matricula);
    v_mi := null; v_ri := null; v_origen := null; v_con := null;

    select mi.id, mi.recipe_item_id into v_mi, v_ri from public.menu_item mi
     where mi.account_id = p_account and mi.brand_id = p_brand and mi.external_source = 'lastapp'
       and mi.external_id = v_p.matricula and mi.archived_at is null
     limit 1;

    if v_mi is null and exists (select 1 from public.menu_item mi
         where mi.account_id = p_account and mi.brand_id = p_brand and mi.external_source = 'lastapp'
           and mi.external_id = v_p.matricula and mi.archived_at is not null) then
      -- Archivada a propósito: ni se resucita ni se duplica (el índice único también la cuenta).
      v_archiv := v_archiv || jsonb_build_object('plato', v_p.nombre, 'matricula', v_p.matricula);
      continue;
    end if;

    if v_ri is null then
      -- a) lo que ya tiene enlazado esta matrícula en otra marca (las bebidas y los postres).
      select mi.recipe_item_id into v_ri from public.menu_item mi
       where mi.account_id = p_account and mi.external_source = 'lastapp' and mi.external_id = v_p.matricula
         and mi.archived_at is null and mi.recipe_item_id is not null
       group by mi.recipe_item_id order by count(*) desc limit 1;
      if v_ri is not null then v_origen := 'otra_marca'; end if;
      -- b) un plato de la misma marca con el mismo nombre (casi igual): el mismo artículo.
      if v_ri is null and v_vistos ? v_norm then
        v_origen := 'juntado';
        v_con := v_nombres->>v_norm;
        if v_vistos->>v_norm <> 'ensayo' then v_ri := (v_vistos->>v_norm)::uuid; end if;
      end if;
      if v_ri is null and v_origen is null then
        select mi.recipe_item_id, btrim(mi.name) into v_ri, v_con from public.menu_item mi
         where mi.account_id = p_account and mi.brand_id = p_brand and mi.archived_at is null
           and mi.recipe_item_id is not null and public._f01_normalizar(mi.name) = v_norm
           and mi.external_id is distinct from v_p.matricula
         limit 1;
        if v_ri is not null then v_origen := 'juntado'; end if;
      end if;
      -- c) un artículo del almacén que se llama igual, si es uno solo.
      if v_ri is null and v_origen is null then
        select min(ri.id::text)::uuid into v_ri from public.recipe_item ri
         where ri.account_id = p_account and ri.type = 'raw' and ri.is_active and ri.archived_at is null
           and public._f01_normalizar(ri.name) = v_norm
        having count(*) = 1;
        if v_ri is not null then v_origen := 'almacen'; end if;
      end if;
      -- d) un plato nuevo, sin receta todavía.
      if v_ri is null and v_origen is null then
        v_origen := 'nuevo';
        if not p_ensayo then
          insert into public.recipe_item (account_id, type, name, base_unit_id, is_active, source, needs_review, created_by_name)
          values (p_account, 'dish', v_p.nombre, v_ud, true, 'import', true, p_quien_nombre)
          returning id into v_ri;
        end if;
      end if;
      if v_origen = 'juntado' then
        v_juntados := v_juntados || jsonb_build_object('plato', v_p.nombre, 'con', coalesce(v_con, v_norm));
      end if;
    end if;

    if not (v_vistos ? v_norm) then
      v_vistos := v_vistos || jsonb_build_object(v_norm, coalesce(v_ri::text, 'ensayo'));
      v_nombres := v_nombres || jsonb_build_object(v_norm, v_p.nombre);
    end if;

    if v_mi is not null then
      v_ya := v_ya + 1;
      if v_origen is not null then
        v_enlazados := v_enlazados + 1;
        if not p_ensayo and v_ri is not null then
          update public.menu_item set recipe_item_id = v_ri, updated_at = now()
           where id = v_mi and recipe_item_id is null;
        end if;
      end if;
    else
      v_creados := v_creados + 1;
      if not p_ensayo then
        insert into public.menu_item (account_id, brand_id, channel_id, recipe_item_id, name, price,
                                      product_type, external_source, external_id, source, needs_review, created_by_name)
        values (p_account, p_brand, null, v_ri, v_p.nombre, coalesce(v_p.base_cents, 0)::numeric / 100.0,
                'item', 'lastapp', v_p.matricula, 'import', true, p_quien_nombre)
        returning id into v_mi;
      end if;
    end if;

    -- Cómo queda el plato (por nombre: dos nombres casi iguales son un plato).
    select ri.type into v_tipo from public.recipe_item ri where ri.id = v_ri;
    if not (v_platos ? v_norm) then
      v_platos := v_platos || jsonb_build_object(v_norm,
        case when v_tipo = 'raw' then 'almacen'
             when v_ri is not null and exists (select 1 from public.recipe_line rl where rl.parent_item_id = v_ri) then 'receta'
             else 'sin_receta' end);
      if v_tipo = 'raw' then v_almacen := v_almacen || to_jsonb(v_p.nombre); end if;
    end if;

    -- El precio de cada plataforma, cuando no es el de la carta.
    v_base := v_p.base_cents;
    for v_c in
      select sc.id as channel_id,
             (select f.price_cents from public._f01_filas(p_account, p_org, p_nombre) f
               where f.organization_product_id::text = v_p.matricula and f.external_channel = sc.slug and f.price_cents is not null
               order by f.seen_in_catalog_at desc nulls last limit 1) as cents
        from public.sales_channel sc
       where sc.account_id = p_account and sc.slug in ('glovo', 'uber', 'justeat', 'shop')
    loop
      if v_c.cents is not null and v_c.cents is distinct from coalesce(v_base, -1)
         and (v_mi is null or not exists (select 1 from public.menu_item_override o
               where o.account_id = p_account and o.menu_item_id = v_mi and o.channel_id = v_c.channel_id and o.location_id is null)) then
        v_over := v_over + 1;
        if not p_ensayo then
          insert into public.menu_item_override (account_id, menu_item_id, channel_id, location_id, price)
          values (p_account, v_mi, v_c.channel_id, null, v_c.cents::numeric / 100.0);
        end if;
      end if;
    end loop;
  end loop;

  return jsonb_build_object(
    'matriculas', v_matr,
    'platos', (select count(*) from jsonb_object_keys(v_platos)),
    'ya_estaban', v_ya,
    'creados', v_creados,
    'enlazados', v_enlazados,
    'juntados', v_juntados,
    'del_almacen', v_almacen,
    'con_receta', (select count(*) from jsonb_each_text(v_platos) x where x.value = 'receta'),
    'sin_receta', (select count(*) from jsonb_each_text(v_platos) x where x.value = 'sin_receta'),
    'precios_por_plataforma', v_over,
    'archivadas', v_archiv);
end $$;


--
-- Name: _f01_vincular(uuid, uuid, uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01_vincular(p_account uuid, p_brand uuid, p_org uuid, p_nombre text, p_ensayo boolean, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_r          record;
  v_mapas      integer := 0;
  v_otra       jsonb := '[]'::jsonb;
  v_locales    jsonb;
  v_canales    jsonb;
begin
  select coalesce(jsonb_agg(distinct jsonb_build_object('id', l.id, 'nombre', l.name)), '[]'::jsonb) into v_locales
    from public._f01_filas(p_account, p_org, p_nombre) f
    join public.external_location_map lm on lm.account_id = p_account and lm.source = 'lastapp'
         and lm.external_location_id = f.external_location_id::text and lm.is_active
    join public.locations l on l.id = lm.location_id and l.account_id = p_account and l.active;

  select coalesce(jsonb_agg(distinct jsonb_build_object('id', sc.id, 'slug', sc.slug, 'nombre', sc.name)), '[]'::jsonb) into v_canales
    from public._f01_filas(p_account, p_org, p_nombre) f
    cross join lateral unnest(coalesce(f.external_channels, array[f.external_channel])) ch(slug)
    join public.sales_channel sc on sc.account_id = p_account and sc.slug = ch.slug and sc.is_active;

  if not p_ensayo then
    insert into public.brand_location_availability (account_id, brand_id, location_id, is_active, active_since, notes)
    select p_account, p_brand, (x->>'id')::uuid, true, current_date, 'F01 · alta de una marca de Last' from jsonb_array_elements(v_locales) x
    on conflict (account_id, brand_id, location_id) do nothing;

    insert into public.brand_channel (account_id, brand_id, channel_id, is_active, created_by_name)
    select p_account, p_brand, (x->>'id')::uuid, true, p_quien_nombre from jsonb_array_elements(v_canales) x
    on conflict (brand_id, channel_id) do nothing;
  end if;

  -- El vínculo de cada local de Last con su id de marca (cuando el espejo lo trae).
  for v_r in
    select distinct f.external_location_id::text as loc, f.external_brand_id as ext
      from public._f01_filas(p_account, p_org, p_nombre) f
      join public.external_location_map lm on lm.account_id = p_account and lm.source = 'lastapp'
           and lm.external_location_id = f.external_location_id::text and lm.is_active
      join public.locations l on l.id = lm.location_id and l.active
     where f.external_brand_id is not null
  loop
    if exists (select 1 from public.external_brand_map m where m.account_id = p_account and m.source = 'lastapp'
                and m.external_location_id = v_r.loc and m.external_brand_id = v_r.ext) then
      if exists (select 1 from public.external_brand_map m where m.account_id = p_account and m.source = 'lastapp'
                  and m.external_location_id = v_r.loc and m.external_brand_id = v_r.ext
                  and m.brand_id is distinct from p_brand) then
        -- Otra decisión ya tomada (otra marca o ignorada): no se pisa, se dice.
        v_otra := v_otra || jsonb_build_object('local_last', v_r.loc);
      end if;
      continue;
    end if;
    v_mapas := v_mapas + 1;
    if not p_ensayo then
      insert into public.external_brand_map (account_id, source, external_location_id, external_brand_id, brand_id, is_ignored)
      values (p_account, 'lastapp', v_r.loc, v_r.ext, p_brand, false)
      on conflict (account_id, source, external_location_id, external_brand_id) do nothing;
    end if;
  end loop;

  return jsonb_build_object('locales', v_locales, 'canales', v_canales, 'vinculos_nuevos', v_mapas, 'vinculos_de_otra_marca', v_otra);
end $$;


--
-- Name: _f01b_cambios_marca(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01b_cambios_marca(p_account uuid, p_brand uuid, p_org uuid, p_nombre text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_nuevos   jsonb;
  v_retir    jsonb;
  v_precios  jsonb;
  v_extras   jsonb;
  v_hay      boolean;
begin
  select exists (select 1 from public._f01_filas(p_account, p_org, p_nombre)) into v_hay;
  if not v_hay then return null; end if;

  -- Platos nuevos: en Last y no en la carta de la marca (ni archivados).
  select coalesce(jsonb_agg(jsonb_build_object('matricula', x.m, 'nombre', x.n, 'precio', x.c / 100.0) order by x.n), '[]'::jsonb) into v_nuevos
    from (select f.organization_product_id::text as m, btrim(max(f.product_name)) as n,
                 coalesce(max(f.price_cents) filter (where f.external_channel = 'default'), mode() within group (order by f.price_cents)) as c
            from public._f01_filas(p_account, p_org, p_nombre) f
           where f.organization_product_id is not null
             and not exists (select 1 from public.menu_item mi where mi.account_id = p_account and mi.brand_id = p_brand
                               and mi.external_source = 'lastapp' and mi.external_id = f.organization_product_id::text)
           group by 1) x;

  -- Platos que ya no están: en la carta (de Last, vivos) y no en su última foto.
  select coalesce(jsonb_agg(jsonb_build_object('menu_item_id', mi.id, 'nombre', btrim(mi.name),
           'visto', (select max(e.seen_in_catalog_at) from public.external_catalog_product e
                      where e.account_id = p_account and e.organization_product_id::text = mi.external_id))
           order by mi.name), '[]'::jsonb) into v_retir
    from public.menu_item mi
   where mi.account_id = p_account and mi.brand_id = p_brand and mi.external_source = 'lastapp' and mi.archived_at is null
     and coalesce(mi.product_type, 'item') <> 'combo'
     and not exists (select 1 from public._f01_filas(p_account, p_org, p_nombre) f where f.organization_product_id::text = mi.external_id);

  -- Precios distintos: el de la carta y el de cada plataforma, contra Last.
  with base as (
    select mi.id, btrim(mi.name) as nombre, mi.price,
           coalesce(max(f.price_cents) filter (where f.external_channel = 'default'), mode() within group (order by f.price_cents)) as base_c
      from public.menu_item mi
      join public._f01_filas(p_account, p_org, p_nombre) f on f.organization_product_id::text = mi.external_id
     where mi.account_id = p_account and mi.brand_id = p_brand and mi.external_source = 'lastapp' and mi.archived_at is null
       and f.price_cents is not null
     group by mi.id, mi.name, mi.price
  ),
  canal as (
    select b.id, b.nombre, sc.id as channel_id, sc.slug, b.base_c,
           (select f.price_cents from public._f01_filas(p_account, p_org, p_nombre) f
             where f.organization_product_id::text = (select mi.external_id from public.menu_item mi where mi.id = b.id)
               and f.external_channel = sc.slug and f.price_cents is not null
             order by f.seen_in_catalog_at desc limit 1) as last_c,
           (select o.price from public.menu_item_override o where o.account_id = p_account and o.menu_item_id = b.id
             and o.channel_id = sc.id and o.location_id is null) as folvy
      from base b cross join public.sales_channel sc
     where sc.account_id = p_account and sc.slug in ('glovo', 'uber', 'justeat', 'shop')
  )
  select coalesce(jsonb_agg(x order by x->>'nombre', x->>'canal' nulls first), '[]'::jsonb) into v_precios
    from (select jsonb_build_object('menu_item_id', b.id, 'nombre', b.nombre, 'canal', null, 'antes', b.price, 'despues', b.base_c / 100.0) as x
            from base b where b.base_c is not null and round(b.price * 100) <> b.base_c
          union all
          select jsonb_build_object('menu_item_id', c.id, 'nombre', c.nombre, 'canal', c.slug,
                   'antes', coalesce(c.folvy, (select mi.price from public.menu_item mi where mi.id = c.id)), 'despues', c.last_c / 100.0)
            from canal c
           where c.last_c is not null and c.last_c is distinct from c.base_c
             and round(coalesce(c.folvy, -1) * 100) is distinct from c.last_c) y;

  -- Extras nuevos: en Last, en algún plato de la marca, y sin decir qué descuentan.
  with propias as (
    select distinct f.organization_product_id::text as m from public._f01_filas(p_account, p_org, p_nombre) f where f.organization_product_id is not null
  ),
  ex as (
    select distinct on (e.modifier_id) e.modifier_id, btrim(e.name) as nombre, e.price_cents, e.group_name
      from public._f01b_extras(p_account, p_org) e
     where e.product_ids && (select coalesce(array_agg(m), '{}') from propias)
       and not exists (select 1 from public.modifier_option o
                        where o.account_id = p_account and o.pos_modifier_id = e.modifier_id
                          and exists (select 1 from public.modifier_recipe_impact i where i.modifier_option_id = o.id and i.status = 'confirmed'))
     order by e.modifier_id, e.seen_in_catalog_at desc
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'modifier_id', ex.modifier_id, 'nombre', ex.nombre, 'pregunta', ex.group_name, 'precio', coalesce(ex.price_cents, 0) / 100.0,
           'en_folvy', exists (select 1 from public.modifier_option o where o.account_id = p_account and o.pos_modifier_id = ex.modifier_id),
           'propuesta', p.p,
           'estado', case when p.p is not null and p.p->>'cantidad' is not null then 'propuesto' else 'falta' end)
           order by ex.nombre), '[]'::jsonb) into v_extras
    from ex cross join lateral (select public._f01b_propuesta(p_account, ex.nombre) as p) p;

  return jsonb_build_object('brand_id', p_brand, 'nombre', (select b.name from public.brand b where b.id = p_brand),
    'nombre_last', p_nombre, 'org', p_org,
    'platos_nuevos', v_nuevos, 'extras_nuevos', v_extras, 'retirados', v_retir, 'precios', v_precios,
    'precios_puestos_30d', (select count(*) from public.external_catalog_change c where c.account_id = p_account and c.brand_id = p_brand
                              and c.kind = 'precio' and c.created_at > now() - interval '30 days'));
end $$;


--
-- Name: external_catalog_modifier; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_catalog_modifier (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    source text DEFAULT 'lastapp'::text NOT NULL,
    external_org_id uuid NOT NULL,
    group_id text NOT NULL,
    slot_id text NOT NULL,
    modifier_id text NOT NULL,
    group_name text,
    group_min integer,
    group_max integer,
    name text,
    price_cents integer,
    product_ids text[] DEFAULT '{}'::text[] NOT NULL,
    seen_in_catalog_at timestamp with time zone DEFAULT now() NOT NULL,
    missing_since timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE external_catalog_modifier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_catalog_modifier IS 'F01 · PR 2: el espejo de los extras de Last (pregunta, hueco y extra) con los productos que los usan. Lo escribe last-catalog-sync con /organizations/{id}/catalog. Solo se lee de Last.';


--
-- Name: _f01b_extras(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01b_extras(p_account uuid, p_org uuid) RETURNS SETOF public.external_catalog_modifier
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select m.* from public.external_catalog_modifier m
   where m.account_id = p_account and m.source = 'lastapp' and m.external_org_id = p_org and m.missing_since is null
     and m.seen_in_catalog_at >= (select max(x.seen_in_catalog_at) - interval '1 day' from public.external_catalog_modifier x
                                   where x.account_id = p_account and x.external_org_id = p_org)
$$;


--
-- Name: _f01b_last_de(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01b_last_de(p_account uuid, p_brand uuid) RETURNS TABLE(org uuid, nombre text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select (x->>'org')::uuid, x->>'nombre' from jsonb_array_elements(public._f01_marcas_last(p_account)) x
   where x->>'estado' = 'vinculada' and (x->>'brand_id')::uuid = p_brand
   limit 1
$$;


--
-- Name: _f01b_propuesta(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01b_propuesta(p_account uuid, p_nombre text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_n      text := coalesce(public._f01_normalizar(p_nombre), '');
  v_quita  boolean := v_n like 'sin %';
  v_doble  boolean := v_n ~ '(^| )doble( |$)';
  v_resto  text;
  v_ficha  record;
begin
  v_resto := btrim(regexp_replace(regexp_replace(v_n,
    '^(sin|extra|doble de|doble|con|anadir|mas|mas de|racion de|porcion de) ', '', 'g'), ' (extra|doble|adicional)$', '', 'g'));
  if v_resto = '' then return null; end if;
  -- Exacto y uno solo; si no, el único que empieza así.
  select ri.id, ri.name, ri.base_unit_id, ku.dimension, ku.abbreviation into v_ficha
    from public.recipe_item ri left join public.kitchen_unit ku on ku.id = ri.base_unit_id
   where ri.account_id = p_account and ri.type = 'raw' and ri.is_active and ri.archived_at is null
     and public._f01_normalizar(ri.name) = v_resto
   limit 2;
  if v_ficha.id is null or (select count(*) from public.recipe_item ri where ri.account_id = p_account and ri.type = 'raw'
                             and ri.is_active and ri.archived_at is null and public._f01_normalizar(ri.name) = v_resto) <> 1 then
    v_ficha := null;
    select ri.id, ri.name, ri.base_unit_id, ku.dimension, ku.abbreviation into v_ficha
      from public.recipe_item ri left join public.kitchen_unit ku on ku.id = ri.base_unit_id
     where ri.account_id = p_account and ri.type = 'raw' and ri.is_active and ri.archived_at is null
       and public._f01_normalizar(ri.name) like v_resto || ' %'
       and (select count(*) from public.recipe_item r2 where r2.account_id = p_account and r2.type = 'raw' and r2.is_active
              and r2.archived_at is null and public._f01_normalizar(r2.name) like v_resto || ' %') = 1;
  end if;
  -- Y si no, el artículo por cuyo nombre empieza el extra («Huevo frito» → «Huevo»), el más largo y uno solo.
  if v_ficha.id is null then
    select ri.id, ri.name, ri.base_unit_id, ku.dimension, ku.abbreviation into v_ficha
      from public.recipe_item ri left join public.kitchen_unit ku on ku.id = ri.base_unit_id
     where ri.account_id = p_account and ri.type = 'raw' and ri.is_active and ri.archived_at is null
       and v_resto like public._f01_normalizar(ri.name) || ' %'
       and (select count(*) from public.recipe_item r2 where r2.account_id = p_account and r2.type = 'raw' and r2.is_active
              and r2.archived_at is null and public._f01_normalizar(r2.name) = public._f01_normalizar(ri.name)) = 1
     order by length(public._f01_normalizar(ri.name)) desc
     limit 1;
  end if;
  if v_ficha.id is null then return null; end if;
  return jsonb_build_object(
    'ficha', v_ficha.id, 'ficha_nombre', v_ficha.name,
    'tipo', case when v_quita then 'remove_item' else 'add_item' end,
    'cantidad', case when not v_quita and v_ficha.dimension = 'unit' then case when v_doble then 2 else 1 end end,
    'unidad', v_ficha.base_unit_id, 'unidad_nombre', v_ficha.abbreviation);
end $_$;


--
-- Name: _f01b_quien(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01b_quien(p_account uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(nullif(btrim(up.display_name), ''), u.email) from auth.users u
    left join public.user_profiles up on up.user_id = u.id and up.account_id = p_account
   where u.id = auth.uid() limit 1
$$;


--
-- Name: _f01c_candidatas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_candidatas(p_account uuid) RETURNS TABLE(org uuid, nombre text, cuenta_last text, estado text, locales jsonb, canales jsonb, comparacion jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select x.org, x.nombre, x.cuenta_last, x.estado, x.locales, x.canales, public._f01c_comparar(p_account, x.org, x.nombre)
    from (select (m->>'org')::uuid as org, m->>'nombre' as nombre, m->>'cuenta_last' as cuenta_last, m->>'estado' as estado,
                 coalesce(m->'locales', '[]'::jsonb) as locales, coalesce(m->'canales', '[]'::jsonb) as canales
            from jsonb_array_elements(public._f01_marcas_last(p_account)) m) x
   where x.estado in ('nueva', 'sin_vincular')
     and not exists (select 1 from public.f01_marca_reconocida r
                      where r.account_id = p_account and r.source = 'lastapp' and r.external_org_id = x.org
                        and r.external_brand_name = x.nombre and r.como = 'otra')
$$;


--
-- Name: _f01c_colocar_recetas(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_colocar_recetas(p_account uuid, p_max integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_corte    timestamptz;
  v_q        record;
  v_s        record;
  v_n        integer;
  v_resto    integer := greatest(coalesce(p_max, 200), 1);
  v_hechas   integer := 0;
  v_fallos   integer := 0;
  v_debajo   integer := 0;
  v_platos   jsonb := '[]'::jsonb;
  v_ult      timestamptz;
  v_h        integer;
  v_f        integer;
  v_d        integer;
begin
  select max(ic.closed_at) into v_corte from public.inventory_count ic
   where ic.account_id = p_account and ic.status in ('aprobado', 'en_revision');

  for v_q in
    select q.*, btrim(ri.name) as plato from public.f01_receta_puesta q
      join public.recipe_item ri on ri.id = q.recipe_item_id and ri.account_id = p_account
     where q.account_id = p_account and q.colocada_at is null
     order by q.puesta_at
  loop
    exit when v_resto <= 0;
    v_h := 0; v_f := 0; v_n := 0; v_ult := v_q.avance_hasta;
    for v_s in
      select s.id, s.sold_at from public.sale s
       where s.account_id = p_account and s.source = 'lastapp' and s.raw_products is not null
         and s.sold_at <= v_q.puesta_at
         and (v_corte is null or s.sold_at > v_corte)
         and (v_q.avance_hasta is null or s.sold_at >= v_q.avance_hasta)
         and exists (select 1 from public.sale_line sl
                       join public.menu_item mi on mi.id = sl.menu_item_id and mi.account_id = p_account
                      where sl.sale_id = s.id and sl.account_id = p_account and mi.recipe_item_id = v_q.recipe_item_id)
       order by s.sold_at, s.id
       limit v_resto
    loop
      v_n := v_n + 1;
      v_ult := v_s.sold_at;
      begin
        perform public.reprocess_sale(v_s.id);
        v_h := v_h + 1;
      exception when others then
        v_f := v_f + 1;
        raise warning 'F01c: no se ha podido colocar la venta % (receta de %): %', v_s.id, v_q.plato, sqlerrm;
      end;
    end loop;
    v_resto := v_resto - v_n;
    v_hechas := v_hechas + v_h;
    v_fallos := v_fallos + v_f;

    -- Las que se quedan debajo del recuento, una vez por plato.
    v_d := 0;
    if v_corte is not null and v_q.avance_hasta is null then
      select count(distinct s.id) into v_d from public.sale s
        join public.sale_line sl on sl.sale_id = s.id and sl.account_id = p_account
        join public.menu_item mi on mi.id = sl.menu_item_id and mi.account_id = p_account
       where s.account_id = p_account and s.source = 'lastapp' and s.sold_at <= v_corte
         and s.sold_at <= v_q.puesta_at and mi.recipe_item_id = v_q.recipe_item_id;
    end if;
    v_debajo := v_debajo + v_d;

    update public.f01_receta_puesta q
       set avance_hasta = v_ult,
           -- Hecha cuando la tanda no se ha llenado (no queda nada más) o no avanza.
           colocada_at = case when v_resto > 0 or v_ult is not distinct from v_q.avance_hasta then now() end,
           resultado = jsonb_build_object(
             'plato', v_q.plato,
             'colocadas', coalesce((q.resultado->>'colocadas')::int, 0) + v_h,
             'fallidas', coalesce((q.resultado->>'fallidas')::int, 0) + v_f,
             'antes_del_recuento', coalesce((q.resultado->>'antes_del_recuento')::int, 0) + v_d,
             'corte', v_corte)
     where q.id = v_q.id;
    v_platos := v_platos || jsonb_build_object('plato', v_q.plato, 'colocadas', v_h, 'fallidas', v_f, 'antes_del_recuento', v_d);
  end loop;

  return jsonb_build_object(
    'platos', v_platos,
    'colocadas', v_hechas,
    'fallidas', v_fallos,
    'antes_del_recuento', v_debajo,
    'corte', v_corte,
    'quedan', (select count(*) from public.f01_receta_puesta q where q.account_id = p_account and q.colocada_at is null));
end $$;


--
-- Name: _f01c_comparar(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_comparar(p_account uuid, p_org uuid, p_nombre text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_last   jsonb;
  v_nl     integer;
  v_b      record;
  v_platos jsonb;
begin
  with last as (
    select public._f01_normalizar(btrim(f.product_name)) as n, min(btrim(f.product_name)) as nombre,
           array_agg(distinct f.organization_product_id::text) as matr
      from public._f01_filas(p_account, p_org, p_nombre) f
     where f.organization_product_id is not null and nullif(btrim(f.product_name), '') is not null
     group by 1
  )
  select coalesce(jsonb_agg(jsonb_build_object('n', l.n, 'nombre', l.nombre, 'matr', to_jsonb(l.matr)) order by l.n), '[]'::jsonb), count(*)
    into v_last, v_nl from last l;
  if v_nl = 0 then return jsonb_build_object('platos_last', 0, 'identica', false, 'parecida', false); end if;

  with last as (
    select x->>'n' as n, x->>'nombre' as nombre, array(select jsonb_array_elements_text(x->'matr')) as matr from jsonb_array_elements(v_last) x
  ),
  folvy as (
    select mi.brand_id, public._f01_normalizar(btrim(mi.name)) as n, min(btrim(mi.name)) as nombre,
           coalesce(array_agg(distinct mi.external_id) filter (where mi.external_id is not null), '{}') as matr,
           bool_or(ri.type = 'raw' or exists (select 1 from public.recipe_line rl where rl.parent_item_id = ri.id and rl.account_id = p_account)) as con_receta
      from public.menu_item mi
      join public.brand b on b.id = mi.brand_id and b.account_id = p_account and b.is_active and b.archived_at is null
      left join public.recipe_item ri on ri.id = mi.recipe_item_id and ri.account_id = p_account
     where mi.account_id = p_account and mi.archived_at is null and nullif(btrim(mi.name), '') is not null
     group by 1, 2
  ),
  cruce as (
    select f.brand_id,
           count(*) as platos_folvy,
           count(*) filter (where f.con_receta) as con_receta,
           count(*) filter (where exists (select 1 from last l where l.n = f.n or l.matr && f.matr)) as coinciden_folvy,
           (select count(*) from last l where exists (select 1 from folvy f2 where f2.brand_id = f.brand_id and (f2.n = l.n or f2.matr && l.matr))) as coinciden_last
      from folvy f group by f.brand_id
  )
  select c.*, b.name as marca into v_b from cruce c join public.brand b on b.id = c.brand_id
   order by c.coinciden_last desc, c.coinciden_folvy desc, c.platos_folvy, b.name, c.brand_id limit 1;

  if v_b.brand_id is null or v_b.coinciden_last = 0 then
    return jsonb_build_object('platos_last', v_nl, 'identica', false, 'parecida', false);
  end if;

  -- Las dos cartas, una al lado de la otra.
  select jsonb_build_object(
           'last', (select coalesce(jsonb_agg(jsonb_build_object('nombre', l->>'nombre',
                       'coincide', exists (select 1 from public.menu_item mi
                                            where mi.account_id = p_account and mi.brand_id = v_b.brand_id and mi.archived_at is null
                                              and (public._f01_normalizar(btrim(mi.name)) = l->>'n'
                                                   or mi.external_id in (select jsonb_array_elements_text(l->'matr')))))
                       order by l->>'n'), '[]'::jsonb) from jsonb_array_elements(v_last) l),
           'folvy', (select coalesce(jsonb_agg(jsonb_build_object('nombre', x.nombre, 'coincide', x.coincide) order by x.n), '[]'::jsonb)
                       from (select public._f01_normalizar(btrim(mi.name)) as n, min(btrim(mi.name)) as nombre,
                                    bool_or(exists (select 1 from jsonb_array_elements(v_last) l
                                                     where l->>'n' = public._f01_normalizar(btrim(mi.name))
                                                        or mi.external_id in (select jsonb_array_elements_text(l->'matr')))) as coincide
                               from public.menu_item mi
                              where mi.account_id = p_account and mi.brand_id = v_b.brand_id and mi.archived_at is null
                                and nullif(btrim(mi.name), '') is not null
                              group by 1) x))
    into v_platos;

  return jsonb_build_object(
    'brand_id', v_b.brand_id,
    'marca', v_b.marca,
    'platos_last', v_nl,
    'platos_folvy', v_b.platos_folvy,
    'con_receta', v_b.con_receta,
    'coinciden', v_b.coinciden_folvy,
    'coinciden_last', v_b.coinciden_last,
    'identica', v_nl >= 3 and v_b.coinciden_last = v_nl and v_b.coinciden_folvy = v_b.platos_folvy and v_b.platos_folvy = v_nl,
    'parecida', v_b.coinciden_last >= 3 and v_b.coinciden_last * 2 >= v_nl,
    'locales_folvy', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'nombre', l.name) order by l.name), '[]'::jsonb)
                        from public.brand_location_availability x
                        join public.locations l on l.id = x.location_id and l.account_id = p_account
                       where x.account_id = p_account and x.brand_id = v_b.brand_id and x.is_active),
    'cartas', v_platos);
end $$;


--
-- Name: _f01c_preparar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_preparar(p_account uuid, p_menu_item uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_mi    record;
  v_tipo  text;
  v_ri    uuid;
  v_ud    uuid;
begin
  select mi.id, mi.name, mi.recipe_item_id into v_mi from public.menu_item mi
   where mi.id = p_menu_item and mi.account_id = p_account and mi.archived_at is null;
  if v_mi.id is null then raise exception 'Ese plato no está en la carta de esta cuenta.' using errcode = 'P0002'; end if;

  if v_mi.recipe_item_id is not null then
    select ri.type into v_tipo from public.recipe_item ri where ri.id = v_mi.recipe_item_id and ri.account_id = p_account;
    if v_tipo = 'raw' then
      raise exception '«%» sale del almacén tal cual: no lleva receta.', btrim(v_mi.name) using errcode = '22023';
    end if;
    return jsonb_build_object('recipe_item_id', v_mi.recipe_item_id, 'creado', false, 'plato', btrim(v_mi.name));
  end if;

  select u.id into v_ud from public.kitchen_unit u
   where (u.account_id is null or u.account_id = p_account) and u.dimension = 'unit' and u.is_base and u.is_active
   order by (u.account_id is null) desc, u.is_seed desc, u.created_at limit 1;
  insert into public.recipe_item (account_id, type, name, base_unit_id, is_active, source, needs_review, created_by_name)
  values (p_account, 'dish', btrim(v_mi.name), v_ud, true, 'import', true, public._f01b_quien(p_account))
  returning id into v_ri;
  update public.menu_item set recipe_item_id = v_ri, updated_at = now() where id = v_mi.id and recipe_item_id is null;
  return jsonb_build_object('recipe_item_id', v_ri, 'creado', true, 'plato', btrim(v_mi.name));
end $$;


--
-- Name: _f01c_receta_puesta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_receta_puesta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.f01_receta_puesta (account_id, recipe_item_id)
  select ri.account_id, ri.id
    from (select distinct n.parent_item_id from nuevas n) p
    join public.recipe_item ri on ri.id = p.parent_item_id
   where not exists (select 1 from public.recipe_line rl
                      where rl.parent_item_id = p.parent_item_id and rl.account_id = ri.account_id
                        and not exists (select 1 from nuevas n2 where n2.id = rl.id))
     and exists (select 1 from public.menu_item mi
                  where mi.account_id = ri.account_id and mi.recipe_item_id = ri.id and mi.external_source = 'lastapp')
  on conflict do nothing;
  return null;
end $$;


--
-- Name: _f01c_reconocer_solas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_reconocer_solas(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_c       record;
  v_salida  jsonb := '[]'::jsonb;
begin
  for v_c in select * from public._f01c_candidatas(p_account) c where (c.comparacion->>'identica')::boolean loop
    begin
      v_salida := v_salida || public._f01c_unir(p_account, v_c.org, v_c.nombre, (v_c.comparacion->>'brand_id')::uuid, 'sola',
                                                v_c.comparacion, null, null);
    exception when others then
      v_salida := v_salida || jsonb_build_object('nombre_last', v_c.nombre, 'error', sqlerrm);
    end;
  end loop;
  return v_salida;
end $$;


--
-- Name: _f01c_unir(uuid, uuid, text, uuid, text, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_unir(p_account uuid, p_org uuid, p_nombre text, p_brand uuid, p_como text, p_comparacion jsonb, p_quien uuid, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ya      uuid;
  v_vinc    jsonb;
  v_carta   jsonb;
  v_ventas  jsonb;
  v_id      uuid;
begin
  select a.brand_id into v_ya from public.external_brand_alta a
   where a.account_id = p_account and a.source = 'lastapp' and a.external_org_id = p_org and a.external_brand_name = btrim(p_nombre);
  if v_ya is not null and v_ya <> p_brand then
    raise exception '«%» de Last ya está unida a otra marca de Folvy.', btrim(p_nombre) using errcode = '23505';
  end if;
  insert into public.external_brand_alta (account_id, source, external_org_id, external_brand_name, brand_id, created_by, created_by_name)
  values (p_account, 'lastapp', p_org, btrim(p_nombre), p_brand, p_quien, coalesce(p_quien_nombre, 'Folvy (carta idéntica)'))
  on conflict (account_id, source, external_org_id, external_brand_name) do nothing;

  -- Como el alta con una marca que ya existe: el vínculo de cada local, la carta
  -- (las matrículas nuevas se juntan por nombre con el artículo y la receta que
  -- ya tiene la marca) y lo vendido, colocado.
  v_vinc := public._f01_vincular(p_account, p_brand, p_org, p_nombre, false, coalesce(p_quien_nombre, 'Folvy (carta idéntica)'));
  v_carta := public._f01_sembrar_marca(p_account, p_brand, p_org, p_nombre, false, coalesce(p_quien_nombre, 'Folvy (carta idéntica)'));
  v_ventas := public._f01_recolocar(p_account, p_brand, p_org, p_nombre);

  insert into public.f01_marca_reconocida (account_id, source, external_org_id, external_brand_name, brand_id, como,
                                           comparacion, ventas, locales, created_by, created_by_name, visto_at, visto_por)
  values (p_account, 'lastapp', p_org, btrim(p_nombre), p_brand, p_como,
          coalesce(p_comparacion, '{}'::jsonb) - 'cartas', v_ventas, coalesce(v_vinc->'locales', '[]'::jsonb), p_quien, p_quien_nombre,
          -- Lo que decide una persona ya lo ha visto; lo que hace Folvy solo, se avisa.
          case when p_como = 'confirmada' then now() end, case when p_como = 'confirmada' then p_quien_nombre end)
  returning id into v_id;

  return jsonb_build_object('id', v_id, 'como', p_como, 'nombre_last', btrim(p_nombre), 'brand_id', p_brand,
                            'marca', (select b.name from public.brand b where b.id = p_brand),
                            'locales', coalesce(v_vinc->'locales', '[]'::jsonb), 'carta', v_carta, 'ventas', v_ventas,
                            -- Los platos de esa carta que se quedan sin receta: se dicen.
                            'sin_receta', (select coalesce(jsonb_agg(distinct btrim(mi.name)), '[]'::jsonb) from public.menu_item mi
                                            left join public.recipe_item ri on ri.id = mi.recipe_item_id and ri.account_id = p_account
                                           where mi.account_id = p_account and mi.brand_id = p_brand and mi.archived_at is null
                                             and mi.external_source = 'lastapp'
                                             and mi.external_id in (select f.organization_product_id::text from public._f01_filas(p_account, p_org, p_nombre) f)
                                             and coalesce(ri.type, 'dish') <> 'raw'
                                             and not exists (select 1 from public.recipe_line rl where rl.parent_item_id = ri.id and rl.account_id = p_account)));
end $$;


--
-- Name: _f01c_ventas_esperando(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._f01c_ventas_esperando(p_account uuid, p_org uuid, p_nombre text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with corte as (
    select max(ic.closed_at) as c from public.inventory_count ic
     where ic.account_id = p_account and ic.status in ('aprobado', 'en_revision')
  ),
  matriculas as (
    select distinct f.organization_product_id::text as m from public._f01_filas(p_account, p_org, p_nombre) f
     where f.organization_product_id is not null),
  ids as (
    select distinct f.external_brand_id as e from public._f01_filas(p_account, p_org, p_nombre) f where f.external_brand_id is not null),
  ventas as (
    select s.id, s.sold_at from public.sale s
     where s.account_id = p_account and s.source = 'lastapp' and s.raw_products is not null
       and (exists (select 1 from public.sale_line sl
                     where sl.sale_id = s.id and sl.account_id = p_account and sl.menu_item_id is null
                       and coalesce(sl.unmapped_reason, '') in ('no_brand', 'no_menu_item', 'no_recipe')
                       and sl.external_product_id in (select m from matriculas))
            or (s.brand_id is null and s.external_brand_text in (select e from ids))))
  select jsonb_build_object(
    'despues', count(*) filter (where c.c is null or v.sold_at > c.c),
    'antes', count(*) filter (where c.c is not null and v.sold_at <= c.c),
    'corte', max(c.c))
    from ventas v cross join corte c
$$;


--
-- Name: _fill_acc_from_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._fill_acc_from_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.account_id is null then
    select ca.account_id into new.account_id from course_assignment ca where ca.id = new.assignment_id;
  end if;
  return new;
end $$;


