--
-- Name: compras_forma_facturar(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_forma_facturar(p_proveedor uuid, p_modo text, p_por_local boolean DEFAULT NULL::boolean, p_frecuencia text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from supplier where id = p_proveedor;
  if v_cuenta is null then raise exception 'Ese proveedor no existe.' using errcode = 'P0002'; end if;
