end $$;


--
-- Name: compras_hueco_recepcion(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_hueco_recepcion(p_recepcion uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare g goods_receipt; v_hueco numeric; v_quien text := public.conta_nombre_actor();
  e text := 'FM999G999G990D00';
begin
  select * into g from goods_receipt where id = p_recepcion for update;
  if g.id is null then raise exception 'Esa recepción no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(g.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta.' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_motivo, ''))) = 0 then raise exception 'Dime por qué faltan esas líneas.' using errcode = '22023'; end if;
  select greatest(round(coalesce((a.validation->>'base_declared')::numeric, 0) - coalesce((a.validation->>'lines_sum')::numeric, 0), 2), 0)
    into v_hueco from goods_receipt_ai_session a where a.id = g.ai_session_id;
  update goods_receipt set unread_gap_amount = v_hueco, unread_gap_reason = btrim(p_motivo), unread_gap_by_name = v_quien, unread_gap_at = now(),
         needs_review = true, updated_at = now()
   where id = g.id;
  return jsonb_build_object('ok', true, 'mensaje', format('Apuntado: en %s faltan %s € de líneas sin leer, porque «%s». Queda marcado para la oficina.',
    coalesce(g.code, 'el albarán'), translate(to_char(coalesce(v_hueco, 0), e), ',.', '.,'), btrim(p_motivo)));
end $$;


--
-- Name: compras_liquidacion_casar_producto(uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_liquidacion_casar_producto(p_proveedor uuid, p_nombre text, p_articulo uuid, p_no_es_nuestro boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_nom text := public.compras_nombre_norm(p_nombre);
begin
  select account_id into v_cuenta from supplier where id = p_proveedor;
  if v_cuenta is null then raise exception 'Ese proveedor no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_cuenta) then raise exception 'No puedes casar productos en esta cuenta.' using errcode = '42501'; end if;
  if v_nom is null then raise exception 'Sin nombre no hay nada que casar.' using errcode = '22023'; end if;
  if p_articulo is not null and not exists (select 1 from recipe_item where id = p_articulo and account_id = v_cuenta) then
    raise exception 'Ese artículo no es de esta cuenta.' using errcode = '42501';
  end if;
  if p_articulo is null and not coalesce(p_no_es_nuestro, false) then
    delete from settlement_product_match where account_id = v_cuenta and supplier_id = p_proveedor and name_norm = v_nom;
    return jsonb_build_object('nombre', v_nom, 'casado', false);
  end if;
  insert into settlement_product_match (account_id, supplier_id, name_norm, example, recipe_item_id, not_ours, decided_by, decided_by_name)
  values (v_cuenta, p_proveedor, v_nom, p_nombre, p_articulo, coalesce(p_no_es_nuestro, false), auth.uid(), public.conta_nombre_actor())
  on conflict (account_id, supplier_id, name_norm) do update set example = excluded.example, recipe_item_id = excluded.recipe_item_id,
    not_ours = excluded.not_ours, decided_by = excluded.decided_by, decided_by_name = excluded.decided_by_name, decided_at = now();
  return jsonb_build_object('nombre', v_nom, 'casado', true);
end $$;


--
-- Name: compras_liquidacion_confirmar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_liquidacion_confirmar(p_liq uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from licensed_settlement where id = p_liq;
  if v_cuenta is null or not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'No puedes confirmar liquidaciones en esta cuenta.' using errcode = '42501';
  end if;
  return public._compras_liquidacion_confirmar(p_liq, null);
end $$;


--
-- Name: compras_liquidacion_contraste(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_liquidacion_contraste(p_liq uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from licensed_settlement l where l.id = p_liq and (select belongs_to_account(l.account_id))) then
    raise exception 'Esa liquidación no es de tu cuenta.' using errcode = '42501';
  end if;
  return public._compras_liquidacion_contraste(p_liq);
end $$;


--
-- Name: compras_liquidacion_guardar(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_liquidacion_guardar(p_empresa uuid, p_proveedor uuid, p_local uuid, p_lectura jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from company where id = p_empresa;
  if v_cuenta is null or not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'No puedes guardar liquidaciones en esta cuenta.' using errcode = '42501';
  end if;
  return public._compras_liquidacion_guardar(p_empresa, p_proveedor, p_local, p_lectura, null);
end $$;


--
-- Name: compras_liquidacion_productos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_liquidacion_productos(p_liq uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l licensed_settlement; v jsonb;
begin
  select * into l from licensed_settlement where id = p_liq;
  if l.id is null then raise exception 'Esa liquidación no existe.' using errcode = 'P0002'; end if;
  if not (select belongs_to_account(l.account_id)) then raise exception 'Esa liquidación no es de tu cuenta.' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('nombre', x->>'nombre', 'compras', (x->>'compras')::numeric, 'unidad', x->>'unidad',
           'articulo', m.recipe_item_id, 'articulo_nombre', r.name, 'no_es_nuestro', coalesce(m.not_ours, false))
           order by (m.recipe_item_id is not null or coalesce(m.not_ours, false)), x->>'nombre'), '[]'::jsonb) into v
    from jsonb_array_elements(coalesce(l.detail->'inventario'->'productos', '[]'::jsonb)) x
    left join settlement_product_match m on m.account_id = l.account_id and m.supplier_id = l.supplier_id
                                        and m.name_norm = public.compras_nombre_norm(x->>'nombre')
    left join recipe_item r on r.id = m.recipe_item_id and r.account_id = l.account_id;
  return v;
end $$;


--
-- Name: compras_liquidacion_recepciones(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_liquidacion_recepciones(p_liq uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l licensed_settlement; v jsonb;
begin
  select * into l from licensed_settlement where id = p_liq;
  if l.id is null then raise exception 'Esa liquidación no existe.' using errcode = 'P0002'; end if;
  if not (select belongs_to_account(l.account_id)) then raise exception 'Esa liquidación no es de tu cuenta.' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('recepcion', g.id, 'codigo', g.code, 'fecha', g.receipt_date,
           'base', public._compras_base_recepcion(g.id)) order by g.receipt_date, g.code), '[]'::jsonb) into v
    from goods_receipt g left join goods_receipt_path p on p.goods_receipt_id = g.id
   where g.account_id = l.account_id and g.location_id = l.location_id and g.status = 'confirmado'
     and g.receipt_date between l.period_from and l.period_to
     and ((p.id is not null and p.path = 'liquidacion' and p.supplier_id = l.supplier_id)
          or (p.id is null and g.supplier_id = l.supplier_id));
  return v;
end $$;


--
-- Name: compras_liquidaciones(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_liquidaciones(p_cuenta uuid, p_mes date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ini date := date_trunc('month', p_mes)::date; v_fin date := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date; v jsonb;
begin
  if not (select belongs_to_account(p_cuenta)) then raise exception 'Esa cuenta no es tuya.' using errcode = '42501'; end if;
  with rec as (
    select coalesce(p.supplier_id, g.supplier_id) proveedor, g.location_id, count(*) n, sum(public._compras_base_recepcion(g.id)) base
      from goods_receipt g left join goods_receipt_path p on p.goods_receipt_id = g.id
      join supplier s on s.id = coalesce(p.supplier_id, g.supplier_id)
     where g.account_id = p_cuenta and g.status = 'confirmado' and g.receipt_date between v_ini and v_fin
       and s.invoicing_mode = 'monthly_settlement' and (p.id is null or p.path = 'liquidacion')
     group by 1, 2),
  liq as (
    select l.id, l.supplier_id proveedor, l.location_id, l.status, l.settlement_ref, l.net_settlement,
           jsonb_array_length(coalesce(l.detail->'bloqueos', '[]'::jsonb)) bloqueos
      from licensed_settlement l
     where l.account_id = p_cuenta and l.formula = 'documentos' and l.period_from = v_ini),
  pares as (select proveedor, location_id from rec union select proveedor, location_id from liq)
  select coalesce(jsonb_agg(jsonb_build_object(
           'proveedor', x.proveedor, 'proveedor_nombre', s.name, 'local', x.location_id, 'local_nombre', lo.name,
           'recepciones', coalesce(r.n, 0), 'base', coalesce(r.base, 0),
           'liquidacion', q.id, 'estado', q.status, 'referencia', q.settlement_ref, 'saldo', q.net_settlement, 'bloqueos', q.bloqueos)
         order by s.name, lo.name), '[]'::jsonb) into v
    from pares x join supplier s on s.id = x.proveedor left join locations lo on lo.id = x.location_id
    left join rec r on r.proveedor = x.proveedor and r.location_id is not distinct from x.location_id
    left join liq q on q.proveedor = x.proveedor and q.location_id is not distinct from x.location_id;
  return jsonb_build_object('mes', v_ini, 'filas', v);
end $$;


--
-- Name: compras_mirar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_mirar(p_cuenta uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_recepciones jsonb; v_sin_camino jsonb; v_fichas jsonb; v_desde date;
begin
  if not (select belongs_to_account(p_cuenta)) then raise exception 'Esa cuenta no es tuya.' using errcode = '42501'; end if;
  -- Desde el día siguiente al corte más tardío de las empresas de la cuenta.
  select coalesce(max(fy.imported_until) + 1, date '2000-01-01') into v_desde
    from fiscal_year fy join company c on c.id = fy.company_id where c.account_id = p_cuenta;

  select coalesce(jsonb_agg(jsonb_build_object(
           'tipo', 'recepcion', 'recepcion', g.id, 'codigo', g.code, 'fecha', g.receipt_date,
           'proveedor', g.supplier_id, 'proveedor_nombre', s.name, 'local', g.location_id, 'local_nombre', l.name,
           'base', public._compras_base_recepcion(g.id), 'papel', p.doc_type, 'a_nombre_de', p.bill_to_name,
           'camino', p.path, 'pregunta', p.question, 'detalle', p.question_detail, 'frase', p.reason, 'error', p.error,
           'factura', p.supplier_invoice_id, 'sesion', g.ai_session_id)
         order by g.receipt_date, g.code), '[]'::jsonb)
    into v_recepciones
    from goods_receipt_path p join goods_receipt g on g.id = p.goods_receipt_id
    left join supplier s on s.id = g.supplier_id left join locations l on l.id = g.location_id
   where p.account_id = p_cuenta and p.question is not null and p.question is distinct from p.question_closed
     and g.status = 'confirmado'
     -- «¿Cómo factura?» ya está contestada si su ficha lo dice ahora, y no queda nada por hacer si
     -- ese papel ya se usó (su factura está hecha): volver a decidir no las toca (consumed_at).
     and not (p.question = 'ficha_sin_forma' and p.consumed_at is not null and s.invoicing_mode is not null);

  select coalesce(jsonb_agg(jsonb_build_object('tipo', 'sin_camino', 'recepcion', g.id, 'codigo', g.code, 'fecha', g.receipt_date,
           'proveedor_nombre', s.name, 'local_nombre', l.name) order by g.receipt_date), '[]'::jsonb)
    into v_sin_camino
    from goods_receipt g left join supplier s on s.id = g.supplier_id left join locations l on l.id = g.location_id
   where g.account_id = p_cuenta and g.status = 'confirmado' and g.receipt_date >= v_desde
     and not exists (select 1 from goods_receipt_path p where p.goods_receipt_id = g.id);

  -- Las fichas de los proveedores con compras abiertas (factura o pendiente) o que liquidan.
  select coalesce(jsonb_agg(jsonb_build_object('tipo', 'ficha', 'proveedor', x.id, 'proveedor_nombre', x.name, 'falta', x.falta) order by x.name), '[]'::jsonb)
    into v_fichas
    from (select s.id, s.name, public.compras_ficha_le_falta(s.id) falta from supplier s
           where s.account_id = p_cuenta and s.archived_at is null
             and (s.invoicing_mode = 'monthly_settlement'
                  or exists (select 1 from goods_receipt_path p join goods_receipt g on g.id = p.goods_receipt_id
                              where g.supplier_id = s.id and p.path in ('factura', 'pendiente_factura', 'liquidacion')))) x
   where jsonb_array_length(x.falta) > 0;

  return jsonb_build_object('recepciones', v_recepciones, 'sin_camino', v_sin_camino, 'fichas', v_fichas);
end $$;


--
-- Name: compras_nif_norm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_nif_norm(p text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  select nullif(regexp_replace(regexp_replace(upper(coalesce(p, '')), '[^A-Z0-9]', '', 'g'), '^ES(?=[A-Z0-9]{9}$)', ''), '')
$_$;


--
-- Name: compras_nombre_generico(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_nombre_generico(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  select public.compras_nombre_norm(p) in (
    'contado', 'al contado', 'venta al contado', 'cliente contado', 'clientes contado', 'contado cliente',
    'cliente', 'clientes', 'cliente varios', 'clientes varios', 'varios', 'varios clientes',
    'particular', 'particulares', 'consumidor final', 'publico', 'cliente final', 'mostrador', 'cliente mostrador')
$$;


--
-- Name: compras_nombre_norm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_nombre_norm(p text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $_$
  select nullif(btrim(regexp_replace(regexp_replace(regexp_replace(
    ' ' || lower(public.unaccent(coalesce(p, ''))) || ' ',
    '^\s*[0-9]+\s*-\s*', ' '),
    '[^a-z0-9]+', ' ', 'g'),
    '( (s l u|s l l|s l|s a u|s a|sl|slu|sll|sa|sau|s coop|sociedad limitada|sociedad anonima|unipersonal))+ *$', ' ', 'g')), '')
$_$;


--
-- Name: compras_recepcion_linea_anadir(uuid, uuid, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_recepcion_linea_anadir(p_recepcion uuid, p_articulo uuid, p_cantidad numeric, p_importe numeric, p_texto text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  g goods_receipt; v_nombre text; v_pos int; v_linea uuid; v_hueco numeric; v_anadido numeric; v_queda numeric; v_quien text := public.conta_nombre_actor();
  e text := 'FM999G999G990D00';
begin
  select * into g from goods_receipt where id = p_recepcion for update;
  if g.id is null then raise exception 'Esa recepción no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(g.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta.' using errcode = '42501';
  end if;
  if g.status not in ('recibido', 'confirmado') then raise exception 'Solo se añaden líneas a una recepción recibida o confirmada (esta está %).', g.status using errcode = '22023'; end if;
  select name into v_nombre from recipe_item where id = p_articulo and account_id = g.account_id;
  if v_nombre is null then raise exception 'Ese artículo no es de esta cuenta.' using errcode = 'P0002'; end if;
  if p_cantidad is null or p_cantidad <= 0 then raise exception 'La cantidad tiene que ser mayor que cero.' using errcode = '22023'; end if;
  if p_importe is null or p_importe <= 0 then raise exception 'El importe de la línea tiene que ser mayor que cero.' using errcode = '22023'; end if;
  select coalesce(max(position), 0) + 1 into v_pos from goods_receipt_line where goods_receipt_id = g.id;
  insert into goods_receipt_line (account_id, goods_receipt_id, product_name, raw_text, qty_received, recipe_item_id, qty_in_base, unit_cost, doc_amount, position, discrepancy_reason)
  values (g.account_id, g.id, v_nombre, coalesce(nullif(btrim(p_texto), ''), v_nombre), p_cantidad, p_articulo, p_cantidad, round(p_importe / p_cantidad, 6), p_importe, v_pos,
          'Añadida en oficina: no se leyó del albarán')
  returning id into v_linea;
  perform public._post_goods_receipt_lines(g.id, true);
  -- Lo que faltaba (la base del albarán contra lo que sumaban sus líneas leídas) menos lo añadido en oficina.
  select greatest(round(coalesce((a.validation->>'base_declared')::numeric, 0) - coalesce((a.validation->>'lines_sum')::numeric, 0), 2), 0)
    into v_hueco from goods_receipt_ai_session a where a.id = g.ai_session_id;
  select coalesce(sum(round(l.qty_received * l.unit_cost, 2)), 0) into v_anadido
    from goods_receipt_line l where l.goods_receipt_id = g.id and l.discrepancy_reason = 'Añadida en oficina: no se leyó del albarán';
  v_queda := greatest(coalesce(v_hueco, 0) - v_anadido, 0);
  update goods_receipt set unread_gap_amount = v_queda,
         unread_gap_reason = case when v_queda < 0.01 then 'Añadidas en oficina las líneas que no se leyeron.' else unread_gap_reason end,
         unread_gap_by_name = v_quien, unread_gap_at = now(), updated_at = now()
   where id = g.id;
  return jsonb_build_object('ok', true, 'linea', v_linea, 'queda', v_queda,
    'mensaje', format('Añadida a %s: %s de %s por %s €; ha entrado al almacén.%s', coalesce(g.code, 'la recepción'),
                      trim(to_char(p_cantidad, 'FM999G990D###')), v_nombre, translate(to_char(p_importe, e), ',.', '.,'),
                      case when v_queda < 0.01 then ' Ya no falta nada por leer.' else format(' Aún faltan %s €.', translate(to_char(v_queda, e), ',.', '.,')) end));
end $$;


--
-- Name: compras_sin_iva(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_sin_iva(p_recepcion uuid, p_empresa uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p goods_receipt_path; g goods_receipt; v jsonb; v_factura uuid;
begin
  select * into p from goods_receipt_path where goods_receipt_id = p_recepcion for update;
  if p.id is null then raise exception 'Esa recepción no tiene camino.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(p.account_id) then raise exception 'No puedes decidir esto en esta cuenta.' using errcode = '42501'; end if;
  if p.path <> 'a_nombre_de_otro' then raise exception 'Solo se apunta sin IVA un documento que va a nombre de otro.' using errcode = '22023'; end if;
  if not exists (select 1 from company where id = p_empresa and account_id = p.account_id) then
    raise exception 'Esa empresa no es de esta cuenta.' using errcode = '42501';
  end if;
  select * into g from goods_receipt where id = p_recepcion;
  if g.ai_session_id is null then raise exception 'La recepción no tiene documento leído.' using errcode = '22023'; end if;
  -- Sin que el disparador de la 0140 intente crearla otra vez.
  perform set_config('folvy.compras_factura', 'si', true);
  v := public._compras_factura_desde_papel(g.account_id, g.ai_session_id, g.supplier_id, g.location_id, p_empresa, g.id, null);
  perform set_config('folvy.compras_factura', '', true);
  if coalesce((v->>'sin_importes')::boolean, false) or v->>'factura' is null then
    raise exception '%', v->>'motivo' using errcode = '22023';
  end if;
  v_factura := (v->>'factura')::uuid;
  update supplier_invoice set vat_non_deductible = true where id = v_factura;
  update goods_receipt_path set path = 'factura', company_id = p_empresa, supplier_invoice_id = v_factura, consumed_at = now(),
         question_closed = question, question_closed_note = 'Apuntada sin descontar el IVA.',
         question_closed_by_name = public.conta_nombre_actor(), question_closed_at = now(),
         reason = format('Va a nombre de «%s», no de tu empresa: se apunta sin descontar el IVA.', coalesce(bill_to_name, 'otro'))
   where id = p.id;
  return jsonb_build_object('factura', v_factura, 'repetida', coalesce((v->>'repetida')::boolean, false),
    'frase', format('Apuntada sin descontar el IVA: %s. Su IVA va como más gasto; no va a la 472 ni al libro de facturas recibidas como deducible.', v->>'motivo'));
end $$;


--
-- Name: compras_ultimos_papeles(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compras_ultimos_papeles(p_proveedor uuid, p_cuantos integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v jsonb;
begin
  select account_id into v_cuenta from supplier where id = p_proveedor;
  if v_cuenta is null or not (select belongs_to_account(v_cuenta)) then raise exception 'Ese proveedor no es de tu cuenta.' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(x.doc_type order by x.receipt_date desc), '[]'::jsonb) into v
    from (select a.parsed_result->'document'->>'doc_type' doc_type, g.receipt_date
            from goods_receipt g join goods_receipt_ai_session a on a.id = g.ai_session_id
           where g.supplier_id = p_proveedor and g.status <> 'anulado' and a.parsed_result->'document'->>'doc_type' is not null
           order by g.receipt_date desc, g.created_at desc limit greatest(p_cuantos, 1)) x;
  return v;
end $$;


--
-- Name: compute_combo_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_combo_cost(p_combo_item_id uuid) RETURNS TABLE(cost numeric, price numeric, margin numeric, fc_pct numeric, slots_total integer, slots_reliable integer, slots_provisional integer, slots_incomplete integer, is_incomplete boolean, detail jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_price      numeric;
  v_cost       numeric := 0;
  v_total      integer := 0;
  v_reliable   integer := 0;
  v_provisional integer := 0;
  v_incomplete integer := 0;
  v_detail     jsonb := '[]'::jsonb;
  r            record;
BEGIN
  SELECT mi.account_id, mi.price INTO v_account_id, v_price
  FROM menu_item mi WHERE mi.id = p_combo_item_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'compute_combo_cost: combo % no existe', p_combo_item_id;
  END IF;

  FOR r IN
    SELECT cs.id AS slot_id, cs.name AS slot_name, cs.position,
           cs.min_selections AS min_sel
    FROM combo_slot cs
    WHERE cs.combo_item_id = p_combo_item_id
      AND cs.account_id = v_account_id
      AND cs.is_active = true
    ORDER BY cs.position, cs.name
  LOOP
    v_total := v_total + 1;

    DECLARE
      v_opt_name   text;
      v_opt_cost   numeric;
      v_opt_state  text;
      v_required   boolean := (r.min_sel >= 1);
    BEGIN
      SELECT o.name, o.cost, o.state
      INTO v_opt_name, v_opt_cost, v_opt_state
      FROM (
        SELECT
          mi.name AS name,
          COALESCE(ri.computed_cost, 0) AS cost,
          CASE
            WHEN cso.menu_item_id IS NULL OR mi.recipe_item_id IS NULL THEN 'incomplete'
            WHEN ri.computed_cost IS NULL OR ri.computed_cost = 0 OR ri.needs_review THEN 'provisional'
            ELSE 'reliable'
          END AS state,
          cso.is_default AS is_default,
          COALESCE(ri.computed_cost, 0) AS sort_cost
        FROM combo_slot_option cso
        LEFT JOIN menu_item mi ON mi.id = cso.menu_item_id
        LEFT JOIN recipe_item ri ON ri.id = mi.recipe_item_id
        WHERE cso.combo_slot_id = r.slot_id
          AND cso.account_id = v_account_id
          AND cso.is_active = true
      ) o
      ORDER BY o.is_default DESC NULLS LAST, o.sort_cost DESC NULLS LAST
      LIMIT 1;

      IF v_opt_name IS NULL THEN
        v_opt_state := 'empty';
        v_opt_cost := 0;
        IF v_required THEN v_incomplete := v_incomplete + 1; END IF;
      ELSIF v_opt_state = 'incomplete' THEN
        IF v_required THEN v_incomplete := v_incomplete + 1; END IF;
      ELSIF v_opt_state = 'provisional' THEN
        v_provisional := v_provisional + 1;
        v_cost := v_cost + COALESCE(v_opt_cost, 0);
      ELSE
        v_reliable := v_reliable + 1;
        v_cost := v_cost + COALESCE(v_opt_cost, 0);
      END IF;

      v_detail := v_detail || jsonb_build_object(
        'slot_id',   r.slot_id,
        'slot_name', r.slot_name,
        'required',  v_required,
        'option',    v_opt_name,
        'cost',      round(COALESCE(v_opt_cost, 0)::numeric, 4),
        'state',     v_opt_state
      );
    END;
  END LOOP;

  cost              := round(v_cost, 4);
  price             := v_price;
  margin            := NULL;
  fc_pct            := NULL;
  slots_total       := v_total;
  slots_reliable    := v_reliable;
  slots_provisional := v_provisional;
  slots_incomplete  := v_incomplete;
  is_incomplete     := (v_incomplete > 0);
  detail            := v_detail;

  IF NOT is_incomplete THEN
    margin := round(COALESCE(v_price, 0) - v_cost, 4);
    fc_pct := CASE WHEN COALESCE(v_price, 0) > 0
                   THEN round(v_cost / v_price * 100, 2)
                   ELSE NULL END;
  END IF;

  RETURN NEXT;
END;
$$;


--
-- Name: compute_employee_balance(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_employee_balance(p_employee_id uuid, p_from date, p_to date) RETURNS TABLE(contracted_hours numeric, worked_hours numeric, paid_absence_hours numeric, effective_hours numeric, delta_hours numeric, night_hours numeric)
    LANGUAGE sql STABLE
    AS $$
  with e as (
    select id, coalesce(contracted_hours_week, weekly_hours, 40)::numeric as hw,
           start_date, end_date, account_id,
           (select location_id from employees x where x.id = employees.id) as loc
    from employees where id = p_employee_id
  ),
  -- dias efectivos del periodo dentro del contrato del empleado (respeta alta/baja parcial)
  dias as (
    select greatest(p_from, coalesce(e.start_date, p_from)) as ini,
           least(p_to, coalesce(e.end_date, p_to)) as fin, e.hw
    from e
  ),
  contratado as (
    select case when fin >= ini then (hw/7.0) * (fin - ini + 1) else 0 end as h_contrato
    from dias
  ),
  trabajado as (
    select coalesce(sum(w.minutes)/60.0, 0) as h_trab,
           coalesce(sum(public.night_minutes_in_span(w.started_at, w.ended_at))/60.0, 0) as h_noche
    from public.team_worked_shifts((select account_id from e), p_from::timestamptz, (p_to + 1)::timestamptz) w
    where w.employee_id = p_employee_id
  ),
  -- ausencias PAGADAS que caen en el periodo: cuentan como horas cumplidas (prorrateo por dias solapados)
  ausencias as (
    select coalesce(sum(
      (least(v.end_date, p_to) - greatest(v.start_date, p_from) + 1) * ((select hw from dias)/7.0)
    ), 0) as h_ausencia_pagada
    from vacations v
    where v.employee_id = p_employee_id and v.status = 'aprobada' and coalesce(v.paid, false) = true
      and v.start_date <= p_to and v.end_date >= p_from
  )
  select
    round((select h_contrato from contratado), 2),
    round((select h_trab from trabajado), 2),
    round((select h_ausencia_pagada from ausencias), 2),
    round((select h_trab from trabajado) + (select h_ausencia_pagada from ausencias), 2),
    round((select h_trab from trabajado) + (select h_ausencia_pagada from ausencias) - (select h_contrato from contratado), 2),
    round((select h_noche from trabajado), 2);
$$;


--
-- Name: compute_recipe_item_allergens(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_recipe_item_allergens(p_recipe_item_id uuid) RETURNS TABLE(allergen_code text, computed_state text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_type text;
BEGIN
  SELECT type INTO v_type FROM recipe_item WHERE id = p_recipe_item_id;
  IF NOT FOUND OR v_type NOT IN ('dish', 'recipe') THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH raw_ids AS (
    -- Ingredientes reales del árbol completo, excluyendo tool/packaging
    -- explícitamente (no depender de que explode_recipe_to_raws los deje
    -- fuera por casualidad).
    SELECT DISTINCT e.raw_item_id AS id
    FROM public.explode_recipe_to_raws(p_recipe_item_id, 1) e
    JOIN recipe_item ri ON ri.id = e.raw_item_id
    WHERE ri.type NOT IN ('tool', 'packaging')
  ),
  matrix AS (
    -- Cruce alérgeno × ingrediente real: NULL en state = ese ingrediente no
    -- tiene ninguna fila para ese alérgeno ("nadie lo ha mirado").
    SELECT
      a.code AS allergen_code,
      r.id   AS raw_id,
      ria.state AS state
    FROM allergen a
    CROSS JOIN raw_ids r
    LEFT JOIN recipe_item_allergen ria
      ON ria.recipe_item_id = r.id AND ria.allergen_code = a.code
  ),
  agg AS (
    SELECT
      m.allergen_code,
      bool_or(m.state = 'contains')                              AS any_contains,
      bool_or(m.state = 'may_contain')                           AS any_may_contain,
      bool_or(m.state = 'unknown')                                AS any_unknown,
      bool_or(m.state IS NULL)                                    AS any_missing,
      -- count(*) FILTER, no bool_and: bool_and ignora los NULL, lo que
      -- daría "todos libres" por vacuidad si hay ingredientes sin fila.
      -- Aquí, si falta una fila, el conteo filtrado no cuadra con el total.
      count(*) FILTER (WHERE m.state = 'free') = count(*)         AS all_free
    FROM matrix m
    GROUP BY m.allergen_code
  )
  SELECT
    a.code AS allergen_code,
    CASE
      WHEN NOT EXISTS (SELECT 1 FROM raw_ids) THEN 'unknown'
      WHEN g.any_contains THEN 'contains'
      WHEN g.any_may_contain THEN 'may_contain'
      WHEN g.any_unknown OR g.any_missing THEN 'unknown'
      WHEN g.all_free THEN 'free'
      ELSE 'unknown' -- red de seguridad, nunca debería alcanzarse
    END AS computed_state
  FROM allergen a
  LEFT JOIN agg g ON g.allergen_code = a.code
  ORDER BY a.position;
END;
$$;


--
-- Name: compute_sale_line_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_sale_line_cost(p_sale_line_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line        sale_line%ROWTYPE;
  v_account_id  uuid;
  v_mi          menu_item%ROWTYPE;
  v_base_cost   numeric;
  v_mod_total   numeric := 0;
  v_total       numeric;
  v_is_combo    boolean := false;
  v_combo_total numeric := 0;
  v_incomplete  boolean := false;
  v_child       record;
  v_impact      record;
  v_comp_base   numeric;
  v_comp_mod    numeric;
  v_comp_recipe uuid;
BEGIN
  SELECT * INTO v_line FROM sale_line WHERE id = p_sale_line_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  v_account_id := v_line.account_id;

  -- (sin guard de usuario: autorización en la frontera)

  IF COALESCE(v_line.line_type, 'product') <> 'product' THEN
    RETURN v_line.computed_cost;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM sale_line c
    WHERE c.parent_sale_line_id = p_sale_line_id
      AND c.line_type = 'combo_item'
  ) INTO v_is_combo;

  IF v_is_combo THEN
    FOR v_child IN
      SELECT c.id, c.menu_item_id, c.quantity
      FROM sale_line c
      WHERE c.parent_sale_line_id = p_sale_line_id
        AND c.line_type = 'combo_item'
    LOOP
      v_comp_recipe := NULL;
      IF v_child.menu_item_id IS NOT NULL THEN
        SELECT mi.recipe_item_id INTO v_comp_recipe FROM menu_item mi WHERE mi.id = v_child.menu_item_id;
      END IF;
      IF v_comp_recipe IS NULL THEN v_incomplete := true; CONTINUE; END IF;

      SELECT COALESCE(ri.computed_cost, ri.fixed_cost) INTO v_comp_base
      FROM recipe_item ri WHERE ri.id = v_comp_recipe;
      IF v_comp_base IS NULL THEN v_incomplete := true; CONTINUE; END IF;

      v_comp_mod := 0;
      FOR v_impact IN
        SELECT mri.impact_type, mri.target_recipe_item_id, mri.quantity, mri.unit_id,
               COALESCE(gm.quantity, 1) AS mod_qty
        FROM sale_line gm
        JOIN modifier_recipe_impact mri ON mri.modifier_option_id = gm.modifier_option_id
        WHERE gm.parent_sale_line_id = v_child.id
          AND gm.line_type = 'modifier'
          AND mri.status = 'confirmed'
      LOOP
        IF v_impact.impact_type IN ('add_item','bundle','replace_item') THEN
          v_comp_mod := v_comp_mod + public._impact_cost(v_impact.target_recipe_item_id, v_impact.quantity * v_impact.mod_qty, v_impact.unit_id);
        ELSIF v_impact.impact_type = 'remove_item' THEN
          v_comp_mod := v_comp_mod - public._impact_cost(v_impact.target_recipe_item_id, v_impact.quantity * v_impact.mod_qty, v_impact.unit_id);
        ELSIF v_impact.impact_type = 'multiply' THEN
          v_comp_mod := v_comp_mod + v_comp_base * (COALESCE(v_impact.quantity,1) - 1);
        END IF;
      END LOOP;

      v_combo_total := v_combo_total + (v_comp_base + v_comp_mod) * COALESCE(v_child.quantity, 1);
    END LOOP;

    IF v_incomplete THEN
      UPDATE sale_line SET computed_cost = NULL, cost_computed_at = now() WHERE id = p_sale_line_id;
      RETURN NULL;
    END IF;
    v_total := ROUND(v_combo_total * COALESCE(v_line.quantity, 1), 6);
    UPDATE sale_line SET computed_cost = v_total, cost_computed_at = now() WHERE id = p_sale_line_id;
    RETURN v_total;
  END IF;

  IF v_line.menu_item_id IS NULL THEN
    UPDATE sale_line SET computed_cost = NULL, cost_computed_at = now() WHERE id = p_sale_line_id;
    RETURN NULL;
  END IF;
  SELECT * INTO v_mi FROM menu_item WHERE id = v_line.menu_item_id;
  IF v_mi.recipe_item_id IS NULL THEN
    UPDATE sale_line SET computed_cost = NULL, cost_computed_at = now() WHERE id = p_sale_line_id;
    RETURN NULL;
  END IF;

  SELECT COALESCE(ri.computed_cost, ri.fixed_cost) INTO v_base_cost
  FROM recipe_item ri WHERE ri.id = v_mi.recipe_item_id;
  IF v_base_cost IS NULL THEN
    UPDATE sale_line SET computed_cost = NULL, cost_computed_at = now() WHERE id = p_sale_line_id;
    RETURN NULL;
  END IF;

  FOR v_impact IN
    SELECT mri.impact_type, mri.target_recipe_item_id, mri.quantity, mri.unit_id,
           COALESCE(m.quantity, 1) AS mod_qty
    FROM sale_line m
    JOIN modifier_recipe_impact mri ON mri.modifier_option_id = m.modifier_option_id
    WHERE m.parent_sale_line_id = p_sale_line_id
      AND m.line_type = 'modifier'
      AND mri.status = 'confirmed'
  LOOP
    IF v_impact.impact_type IN ('add_item','bundle','replace_item') THEN
      v_mod_total := v_mod_total + public._impact_cost(v_impact.target_recipe_item_id, v_impact.quantity * v_impact.mod_qty, v_impact.unit_id);
    ELSIF v_impact.impact_type = 'remove_item' THEN
      v_mod_total := v_mod_total - public._impact_cost(v_impact.target_recipe_item_id, v_impact.quantity * v_impact.mod_qty, v_impact.unit_id);
    ELSIF v_impact.impact_type = 'multiply' THEN
      v_mod_total := v_mod_total + v_base_cost * (COALESCE(v_impact.quantity,1) - 1);
    END IF;
  END LOOP;

  v_total := ROUND((v_base_cost + v_mod_total) * COALESCE(v_line.quantity, 1), 6);
  UPDATE sale_line SET computed_cost = v_total, cost_computed_at = now() WHERE id = p_sale_line_id;
  RETURN v_total;
END;
$$;


--
-- Name: confirm_goods_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_goods_receipt(p_receipt_id uuid) RETURNS TABLE(posted_lines integer, skipped_lines integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_receipt   goods_receipt%rowtype;
  v_user      uuid;
  v_user_name text;
  v_posted    integer := 0;
  v_skipped   integer := 0;
  v_notify    text;
  v_has_diff  boolean;
  v_undecided integer;
begin
  select * into v_receipt from goods_receipt where id = p_receipt_id;
  if not found then
    raise exception 'confirm_goods_receipt: albarán % no existe', p_receipt_id;
  end if;
  if not belongs_to_account(v_receipt.account_id) then
    raise exception 'confirm_goods_receipt: sin acceso al albarán %', p_receipt_id;
  end if;
  if v_receipt.status not in ('borrador', 'recibido') then
    raise exception 'confirm_goods_receipt: el albarán % no está en borrador ni recibido (está %)',
      p_receipt_id, v_receipt.status;
  end if;

  if v_receipt.status = 'recibido' then
    -- (01/09) Cantidad cero CON motivo escrito es una decisión, no un olvido:
    -- deja de contar como "sin decidir". Sin artículo, y cero sin motivo,
    -- siguen bloqueando igual que antes.
    select count(*) into v_undecided
      from goods_receipt_line
     where goods_receipt_id = p_receipt_id
       and not not_goods
       and (
         recipe_item_id is null
         or (
           (qty_in_base is null or qty_in_base <= 0)
           and coalesce(btrim(discrepancy_reason), '') = ''
         )
       );
    if v_undecided > 0 then
      raise exception 'confirm_goods_receipt: quedan % línea(s) sin decidir en % — cada una tiene '
        'que entrar al almacén o marcarse como que no es mercancía', v_undecided, v_receipt.code;
    end if;

    -- ENCARGO CODE (20/08) §2.3 — sin proveedor ni nº de albarán no se cierra.
    -- Solo en el cierre de OFICINA ('recibido' → 'confirmado'), que es la
    -- pantalla que tiene los campos; un borrador manual sigue como estaba
    -- para no levantar un muro sin puerta donde no se puede arreglar.
    if v_receipt.supplier_id is null then
      raise exception 'confirm_goods_receipt: el albarán % no tiene proveedor — ponlo antes de cerrar',
        coalesce(v_receipt.code, p_receipt_id::text);
    end if;
    if v_receipt.supplier_doc_number is null or btrim(v_receipt.supplier_doc_number) = '' then
      raise exception 'confirm_goods_receipt: el albarán % no tiene nº de albarán — ponlo antes de cerrar',
        coalesce(v_receipt.code, p_receipt_id::text);
    end if;
  end if;

  v_user := auth.uid();
  select display_name into v_user_name from user_profiles where id = v_user;

  if v_receipt.status = 'borrador' then
    select p.posted_lines, p.skipped_lines into v_posted, v_skipped
      from public._post_goods_receipt_lines(p_receipt_id, false) p;
  else
    -- ENCARGO CODE (20/08) §3(C) — 'recibido': entra lo que nunca entró. En un
    -- albarán normal no hay nada que postear (todas sus líneas posteables ya
    -- tienen movimiento); en uno retenido por la IA, entra todo aquí.
    select p.posted_lines, p.skipped_lines into v_posted, v_skipped
      from public._post_goods_receipt_lines(p_receipt_id, true) p;
  end if;

  update goods_receipt
    set status = 'confirmado', received_at = coalesce(received_at, now()),
        -- (01/09) MISMO criterio que el guard, palabra por palabra. Si aquí se
        -- quedara la condición vieja, el albarán cerraría pero nacería marcado
        -- "pendiente de revisar" para siempre: un bloqueo cambiado por una mancha.
        needs_review = exists (
          select 1 from goods_receipt_line
           where goods_receipt_id = p_receipt_id
             and not not_goods
             and (
               recipe_item_id is null
               or (
                 (qty_in_base is null or qty_in_base <= 0)
                 and coalesce(btrim(discrepancy_reason), '') = ''
               )
             )
        ),
        updated_at = now()
    where id = p_receipt_id;

  if v_receipt.purchase_order_id is null then
    v_receipt.purchase_order_id := public.auto_link_goods_receipt_to_order(p_receipt_id);
  end if;

  if v_receipt.purchase_order_id is not null then
    -- ENCARGO CODE (21/08) — casar las líneas ANTES de recalcular: si no,
    -- recompute cuenta 0 recibido y el pedido se queda en 'enviado' para
    -- siempre por mucha mercancía que entre.
    perform public._match_order_lines_for_order(v_receipt.purchase_order_id);
    perform recompute_purchase_order_status(v_receipt.purchase_order_id);
  end if;

  v_notify := null;
  if v_receipt.supplier_id is not null then
    select notify_group into v_notify from supplier where id = v_receipt.supplier_id;
  end if;
  if v_notify = 'ctb' then
    -- (01/09) La diferencia sale de los NUMEROS, no de que alguien se
    -- acordara de escribir un motivo. El criterio viejo se perdia el 89 % de
    -- las diferencias reales (55 de 62 en Foodint) y marcaba como "con
    -- diferencias" 11 lineas que solo tenian una nota. Un solo calculo, el de
    -- ctb_receipt_differences, para el flag y para el texto.
    select exists (
      select 1 from public._ctb_receipt_differences_core(p_receipt_id) d
      where d.clase = 'diferencia'
    ) into v_has_diff;

    insert into ctb_notification_queue (
      account_id, goods_receipt_id, location_id, supplier_id,
      notify_group, has_differences, status
    )
    values (
      v_receipt.account_id, p_receipt_id, v_receipt.location_id, v_receipt.supplier_id,
      v_notify, coalesce(v_has_diff, false), 'pendiente'
    )
    on conflict (goods_receipt_id) do update
      set has_differences = excluded.has_differences,
          location_id     = excluded.location_id,
          supplier_id     = excluded.supplier_id,
          updated_at      = now();
  end if;

  posted_lines := v_posted; skipped_lines := v_skipped;
  return next;
end;
$$;


--
-- Name: confirm_goods_receipt_order_link(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_goods_receipt_order_link(p_account_id uuid, p_receipt_id uuid, p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_receipt goods_receipt%rowtype;
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'confirm_goods_receipt_order_link: cuenta % no pertenece al usuario', p_account_id;
  end if;

  select * into v_receipt from goods_receipt where id = p_receipt_id and account_id = p_account_id;
  if not found then
    raise exception 'confirm_goods_receipt_order_link: albarán % no existe en esta cuenta', p_receipt_id;
  end if;

  if not exists (
    select 1 from public._goods_receipt_order_candidates(p_receipt_id) c where c.order_id = p_order_id
  ) then
    raise exception 'confirm_goods_receipt_order_link: el pedido % no es un candidato real de este albarán', p_order_id;
  end if;

  update goods_receipt set purchase_order_id = p_order_id, updated_at = now() where id = p_receipt_id;
  perform public._match_order_lines_for_order(p_order_id);
  perform recompute_purchase_order_status(p_order_id);
end;
$$;


--
-- Name: confirm_mapping(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_mapping(p_proposal_id uuid, p_action text, p_chosen_target uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text) RETURNS TABLE(propagated_lines integer)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_actor       uuid := auth.uid();
  v_proposal    public.mapping_proposal%ROWTYPE;
  v_brand       uuid;
  v_norm        text;
  v_account     uuid;
  v_target      uuid;
  v_new_status  text;
  v_count       integer := 0;
BEGIN
  SELECT * INTO v_proposal
  FROM public.mapping_proposal
  WHERE id = p_proposal_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Propuesta % no encontrada', p_proposal_id;
  END IF;

  v_account := v_proposal.account_id;
  v_brand   := v_proposal.context_brand_id;
  v_norm    := v_proposal.source_normalized;

  IF NOT public.current_user_is_admin_of(v_account) THEN
    RAISE EXCEPTION 'Sin permiso para confirmar mapeos en esta cuenta';
  END IF;

  IF p_action = 'reject' THEN
    v_new_status := 'rejected';
    v_target := NULL;
  ELSIF p_action IN ('confirm', 'correct') THEN
    v_new_status := 'human_confirmed';
    v_target := COALESCE(p_chosen_target, v_proposal.chosen_target_id);
    IF v_target IS NULL THEN
      RAISE EXCEPTION 'Confirmar/corregir requiere un menu_item destino';
    END IF;
  ELSE
    RAISE EXCEPTION 'Accion invalida: %', p_action;
  END IF;

  INSERT INTO public.mapping_decision
    (proposal_id, account_id, action, chosen_target_id, note, decided_by, decided_by_name)
  VALUES
    (p_proposal_id, v_account, p_action, v_target, p_note, v_actor, p_actor_name);

  UPDATE public.mapping_proposal
  SET status = v_new_status,
      chosen_target_id = v_target,
      method = 'human'
  WHERE id = p_proposal_id;

  IF v_new_status = 'human_confirmed' THEN
    UPDATE public.sale_line sl
    SET menu_item_id     = v_target,
        map_source       = 'human',
        map_confidence   = 1.0,
        map_needs_review = false
    FROM public.sale fact
    WHERE sl.sale_id = fact.id
      AND sl.account_id = v_account
      AND sl.menu_item_id IS NULL
      AND regexp_replace(
            regexp_replace(btrim(lower(unaccent(sl.product_name))), '\.$', ''),
            '\s+', ' ', 'g'
          ) = v_norm
      AND ( v_brand IS NULL OR fact.brand_id = v_brand );
    GET DIAGNOSTICS v_count = ROW_COUNT;
  END IF;

  RETURN QUERY SELECT v_count;
END;
$_$;


--
-- Name: connector_assert_manager(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_assert_manager(p_account_connector_id uuid, p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  v_account_id uuid;
  v_ok boolean;
BEGIN
  -- Cuenta dueña de la conexión.
  SELECT account_id INTO v_account_id
  FROM public.account_connector
  WHERE id = p_account_connector_id;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'Conexión % no encontrada', p_account_connector_id;
  END IF;

  -- ¿El usuario es admin/manager ACTIVO de esa cuenta?
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.user_id = p_user_id
      AND up.account_id = v_account_id
      AND up.active = true
      AND up.role IN ('admin', 'manager')
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Sin permiso: el usuario no es admin/manager de la cuenta';
  END IF;

  RETURN v_account_id;
END;
$$;


--
-- Name: connector_mark_down(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_mark_down(p_account_connector_id uuid, p_error text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_ref text;
begin
  select token_ref into v_ref from public.account_connector where id = p_account_connector_id;
  if not found then raise exception 'Conexión % no encontrada', p_account_connector_id; end if;
  if v_ref is not null then delete from vault.secrets where id = v_ref::uuid; end if;
  update public.account_connector
     set status = 'down', token_ref = null, token_expires_at = null,
         last_error = left(coalesce(p_error, 'La renovación del token falló'), 500), updated_at = now()
   where id = p_account_connector_id;
end $$;


--
-- Name: connector_secret_clear(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_secret_clear(p_account_connector_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  v_ref text;
BEGIN
  PERFORM public.connector_assert_manager(p_account_connector_id, p_user_id);

  SELECT credentials_ref INTO v_ref
  FROM public.account_connector
  WHERE id = p_account_connector_id;

  IF v_ref IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_ref::uuid;
  END IF;

  UPDATE public.account_connector
  SET credentials_ref = NULL,
      status = 'paused',
      updated_at = now()
  WHERE id = p_account_connector_id;
END;
$$;


--
-- Name: connector_secret_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_secret_read(p_account_connector_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_ref text;
  v_config jsonb;
  v_secret text;
begin
  select credentials_ref, config
    into v_ref, v_config
  from public.account_connector
  where id = p_account_connector_id;

  if v_ref is null then
    return null;  -- sin credenciales guardadas
  end if;

  select decrypted_secret
    into v_secret
  from vault.decrypted_secrets
  where id = v_ref::uuid;

  if v_secret is null then
    return null;
  end if;

  -- Devuelve { secrets: {...}, config: {...} }
  return jsonb_build_object(
    'secrets', v_secret::jsonb,
    'config', coalesce(v_config, '{}'::jsonb)
  );
end;
$$;


--
-- Name: connector_secret_save(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_secret_save(p_account_connector_id uuid, p_user_id uuid, p_secret_json text, p_config jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  v_account_id uuid;
  v_existing_ref text;
  v_secret_id uuid;
  v_secret_name text;
BEGIN
  -- Gating de rol (lanza si no autorizado).
  v_account_id := public.connector_assert_manager(p_account_connector_id, p_user_id);

  -- Nombre único del secreto en Vault (legible para auditoría, sin el valor).
  v_secret_name := 'connector:' || p_account_connector_id::text;

  SELECT credentials_ref INTO v_existing_ref
  FROM public.account_connector
  WHERE id = p_account_connector_id;

  IF v_existing_ref IS NOT NULL THEN
    -- Actualiza el secreto existente.
    PERFORM vault.update_secret(v_existing_ref::uuid, p_secret_json, v_secret_name, NULL);
    v_secret_id := v_existing_ref::uuid;
  ELSE
    -- Crea uno nuevo y obtiene su uuid.
    v_secret_id := vault.create_secret(p_secret_json, v_secret_name, 'Credenciales de conector Folvy');
  END IF;

  -- Guarda referencia + config no sensible + estado.
  UPDATE public.account_connector
  SET credentials_ref = v_secret_id::text,
      config = COALESCE(p_config, config),
      status = 'connected',
      connected_at = now(),
      connected_by = p_user_id,
      updated_at = now()
  WHERE id = p_account_connector_id;
END;
$$;


--
-- Name: connector_secret_status(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_secret_status(p_account_connector_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  v_ref text;
BEGIN
  PERFORM public.connector_assert_manager(p_account_connector_id, p_user_id);

  SELECT credentials_ref INTO v_ref
  FROM public.account_connector
  WHERE id = p_account_connector_id;

  RETURN v_ref IS NOT NULL;
END;
$$;


--
-- Name: connector_token_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_token_read(p_account_connector_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_ref text; v_exp timestamptz; v_tok text;
begin
  select token_ref, token_expires_at into v_ref, v_exp from public.account_connector where id = p_account_connector_id;
  if v_ref is null then return null; end if;
  select decrypted_secret into v_tok from vault.decrypted_secrets where id = v_ref::uuid;
  if v_tok is null then return null; end if;
  return jsonb_build_object('token', v_tok, 'expires_at', v_exp);
end $$;


--
-- Name: connector_token_save(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connector_token_save(p_account_connector_id uuid, p_token text, p_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_ref text;
begin
  if p_token is null or length(p_token) = 0 then raise exception 'Token vacío' using errcode = '22023'; end if;
  select token_ref into v_ref from public.account_connector where id = p_account_connector_id;
  if not found then raise exception 'Conexión % no encontrada', p_account_connector_id; end if;
  if v_ref is not null then
    perform vault.update_secret(v_ref::uuid, p_token);
  else
    v_ref := vault.create_secret(p_token, 'connector-token:' || p_account_connector_id::text, 'Token de acceso de una conexión (caduca)')::text;
  end if;
  update public.account_connector
     set token_ref = v_ref, token_expires_at = p_expires_at, last_error = null, updated_at = now(),
         status = case when status = 'down' then 'connected' else status end
   where id = p_account_connector_id;
end $$;


--
-- Name: conservacion_vigia(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conservacion_vigia(p_horas integer DEFAULT 48, p_dry boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cron boolean := false; v_ultima timestamptz; v_motivo text := null;
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    select exists (select 1 from cron.job where jobname = 'registro-jornada-conservacion' and active) into v_cron;
  end if;
  select max(ejecutado_at) into v_ultima from public.registro_conservacion;
  if not v_cron then
    v_motivo := 'El trabajo nocturno que borra las coordenadas de más de 3 meses no está programado (cron registro-jornada-conservacion). Hasta que se programe, las ubicaciones se guardan más tiempo del que dice la empresa.';
  elsif v_ultima is null or v_ultima < now() - make_interval(hours => p_horas) then
    v_motivo := format('El trabajo nocturno que borra las coordenadas de más de 3 meses no ha corrido desde %s. Las ubicaciones se están guardando más tiempo del que dice la empresa.',
                       coalesce(to_char(v_ultima at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), 'nunca'));
  end if;
  if v_motivo is not null and not p_dry then
    perform public._queue_system_alert('registro_jornada', 'Registro de jornada: la limpieza de ubicaciones no corre', v_motivo,
                                       'conservacion_registro_jornada', interval '20 hours');
  end if;
  return jsonb_build_object('cron', v_cron, 'ultima', v_ultima, 'aviso', v_motivo);
end $$;


--
-- Name: FUNCTION conservacion_vigia(p_horas integer, p_dry boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conservacion_vigia(p_horas integer, p_dry boolean) IS 'L1a (27/10): cada mañana (cron registro-jornada-conservacion-vigia). Avisa (system_alert) si la limpieza del registro de jornada no está programada o lleva más de 48 h sin correr.';


--
-- Name: conservar_registro_de_jornada(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conservar_registro_de_jornada(p_dry boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_corte_ubicacion timestamptz := now() - interval '3 months';
  v_corte_registro timestamptz := now() - interval '4 years';
  v_coords integer := 0;
  v_marcas integer := 0;
  v_rastros integer := 0;
  v_peticiones integer := 0;
  v_ids uuid[];
begin
  if p_dry then
    return jsonb_build_object(
      'coordenadas_a_borrar', (select count(*) from public.clock_entries where created_at < v_corte_ubicacion and (lat is not null or lng is not null)),
      'marcas_a_anonimizar', (select count(*) from public.clock_entries where datetime < v_corte_registro and anonimizado_at is null),
      'corte_ubicacion', v_corte_ubicacion, 'corte_registro', v_corte_registro);
  end if;

  -- 1. Las coordenadas de más de 3 meses: antes de borrarlas, la distancia y
  --    «dentro o fuera», si el fichaje no las tenía (los de antes de la L1a).
  perform set_config('app.clock_edit_reason', 'Conservación: coordenadas de más de 3 meses borradas; quedan la distancia y si estaba dentro del radio', true);
  perform set_config('app.clock_edit_actor', 'conservación', true);
  with antes as (
    select c.id, public._distancia_metros(c.lat, c.lng, l.lat, l.lng) dist, coalesce(l.clock_radius_m, 200) radio
      from public.clock_entries c
      left join public.locations l on l.id = c.location_id_at_clock
     where c.created_at < v_corte_ubicacion and (c.lat is not null or c.lng is not null)
  ), hechas as (
    update public.clock_entries c
       set distance_m = coalesce(c.distance_m, a.dist),
           within_radius = coalesce(c.within_radius, case when a.dist is null then null else a.dist <= a.radio end),
           lat = null, lng = null, ubicacion_borrada_at = now()
      from antes a
     where a.id = c.id
    returning c.id
  )
  select count(*) into v_coords from hechas;

  -- 2. El registro de más de 4 años: fuera los textos libres, la foto y la
  --    ubicación de las marcas, de su rastro y de sus peticiones. La ficha de la
  --    persona (nombre, DNI) es de la L1b.
  perform set_config('app.clock_edit_reason', 'Conservación: registro de más de 4 años anonimizado', true);
  with hechas as (
    update public.clock_entries c
       set address = null, photo_data_url = null, break_attest_reason = null, lat = null, lng = null,
           anonimizado_at = now()
     where c.datetime < v_corte_registro and c.anonimizado_at is null
    returning c.id
  )
  select coalesce(array_agg(id), '{}'::uuid[]) into v_ids from hechas;
  v_marcas := coalesce(array_length(v_ids, 1), 0);
  if v_marcas > 0 then
    -- Su rastro, también el que acaba de escribir el disparador al anonimizar.
    with r as (
      update public.clock_entry_audit a
         set reason = 'Anonimizado (registro de más de 4 años)', actor_user_id = null, actor_employee_id = null,
             before = case when a.before is null then null else a.before - 'address' end,
             after = case when a.after is null then null else a.after - 'address' end
       where a.clock_entry_id = any (v_ids)
      returning 1
    )
    select count(*) into v_rastros from r;
  end if;
  with p as (
    update public.clock_correction_request q
       set reason = null, resolution_note = null
     where (q.clock_entry_id = any (v_ids) or q.created_at < v_corte_registro)
       and (q.reason is not null or q.resolution_note is not null)
    returning 1
  )
  select count(*) into v_peticiones from p;

  perform set_config('app.clock_edit_reason', '', true);
  perform set_config('app.clock_edit_actor', '', true);
  insert into public.registro_conservacion (coordenadas_borradas, marcas_anonimizadas, rastros_anonimizados, peticiones_anonimizadas, detalle)
  values (v_coords, v_marcas, v_rastros, v_peticiones,
          jsonb_build_object('corte_ubicacion', v_corte_ubicacion, 'corte_registro', v_corte_registro));
  return jsonb_build_object('coordenadas_borradas', v_coords, 'marcas_anonimizadas', v_marcas,
                            'rastros_anonimizados', v_rastros, 'peticiones_anonimizadas', v_peticiones);
end $$;


--
-- Name: FUNCTION conservar_registro_de_jornada(p_dry boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conservar_registro_de_jornada(p_dry boolean) IS 'L1a (27/10): cada noche (cron registro-jornada-conservacion). Borra las coordenadas de los fichajes de más de 3 meses (quedan la distancia y si estaba dentro del radio) y anonimiza el registro de más de 4 años. p_dry: solo cuenta. Deja una fila en registro_conservacion por pasada.';


--
-- Name: consumo_sin_descontar_watchdog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consumo_sin_descontar_watchdog() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer; v_detalle text; v_b integer; v_b_detalle text;
BEGIN
  SELECT count(*), string_agg(
           format('%s de %s (%s intentos, desde %s)',
                  COALESCE(s.pos_short_code, s.platform_order_code, s.id::text),
                  COALESCE(l.name, 'sin local'), f.attempts,
                  to_char(f.first_failed_at AT TIME ZONE 'Europe/Madrid', 'DD/MM HH24:MI')),
           E'\n' ORDER BY f.first_failed_at)
    INTO v_n, v_detalle
    FROM public.sale_consumption_failure f
    JOIN public.sale s ON s.id = f.sale_id
    LEFT JOIN public.locations l ON l.id = f.location_id
   WHERE f.resolved_at IS NULL AND f.last_failed_at < now() - interval '1 hour';

  IF COALESCE(v_n, 0) > 0 THEN
    PERFORM public.encolar_alerta(
      p_kind => 'consumo_sin_descontar_pendiente',
      p_subject => format('%s pedido(s) siguen sin descontar del almacén', v_n),
      p_message => 'El reintento automático no ha podido con estos. '
                || 'Su consumo NO está en el stock:' || E'\n' || v_detalle,
      p_debounce_kind => 'consumo_sin_descontar_pendiente',
      p_debounce_window => interval '6 hours',
      p_account_id => NULL, p_location_id => NULL, p_brand_id => NULL, p_severity => 'alto');
  END IF;

  -- EL ATAJO DEL MOTOR VIEJO. Tiene que seguir dando 0.
  SELECT count(*), string_agg(DISTINCT COALESCE(s.pos_short_code, s.platform_order_code, s.id::text), ', ')
    INTO v_b, v_b_detalle
    FROM public.stock_movement sm
    JOIN public.sale_line sl ON sl.id = sm.source_id
    JOIN public.sale s       ON s.id = sl.sale_id
   WHERE sm.movement_type = 'consumo'
     AND sm.source_type   = 'sale'
     AND COALESCE(s.created_at, s.sold_at) >= public._corte_motor_viejo();

  IF COALESCE(v_b, 0) > 0 THEN
    PERFORM public.encolar_alerta(
      p_kind => 'motor_viejo_ha_vuelto_a_escribir',
      p_subject => format('%s movimiento(s) de consumo con la llave vieja por encima del corte', v_b),
      p_message => format(
          'El escritor unico se salta la llave vieja en las ventas posteriores al %s porque, medido el '
       || '11/09, no existia ninguna. Ya no es verdad: hay %s en %s venta(s) (%s). '
       || 'Mientras esto no sea 0, esas ventas pueden estar descontando dos veces y el atajo hay que quitarlo.',
          to_char(public._corte_motor_viejo() AT TIME ZONE 'Europe/Madrid', 'DD/MM/YYYY'),
          v_b, (SELECT count(DISTINCT sl2.sale_id) FROM public.stock_movement sm2
                  JOIN public.sale_line sl2 ON sl2.id = sm2.source_id
                  JOIN public.sale s2 ON s2.id = sl2.sale_id
                 WHERE sm2.movement_type='consumo' AND sm2.source_type='sale'
                   AND COALESCE(s2.created_at, s2.sold_at) >= public._corte_motor_viejo()),
          v_b_detalle),
      p_debounce_kind => 'motor_viejo_ha_vuelto_a_escribir',
      p_debounce_window => interval '6 hours',
      p_account_id => NULL, p_location_id => NULL, p_brand_id => NULL, p_severity => 'critico');
  END IF;

  RETURN COALESCE(v_n, 0) + COALESCE(v_b, 0);
END;
$$;


--
-- Name: conta_abono_compensar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_abono_compensar(p_abono uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  a public.supplier_invoice; f public.supplier_invoice;
  v_ea uuid; v_ef uuid; v_pend_f numeric; v_pend_a numeric; v_comp numeric; v_nombre text;
begin
  select * into a from public.supplier_invoice where id = p_abono for update;
  if a.id is null or a.doc_kind <> 'credit_note' then return null; end if;
  select id into v_ea from public.journal_entry
   where account_id = a.account_id and source_type = 'supplier_invoice' and source_id = a.id and status = 'validado'
   order by validated_at desc nulls last limit 1;
  if v_ea is null then return jsonb_build_object('abono', a.id, 'compensado', 0, 'motivo', 'sin asiento validado'); end if;
  -- Lo que le queda al abono (en negativo) y a la factura que anula.
  v_pend_a := coalesce(a.grand_total, 0) - coalesce((select sum(amount) from public.supplier_invoice_payment where invoice_id = a.id), 0);
  if a.corrects_invoice_id is null or v_pend_a > -0.005 then
    return jsonb_build_object('abono', a.id, 'compensado', 0, 'a_favor', abs(least(v_pend_a, 0)), 'motivo', case when a.corrects_invoice_id is null then 'sin factura ligada' else 'ya compensado' end);
  end if;
  select * into f from public.supplier_invoice where id = a.corrects_invoice_id and account_id = a.account_id for update;
  if f.id is null or f.supplier_id is distinct from a.supplier_id or f.status <> 'aprobada' then
    return jsonb_build_object('abono', a.id, 'compensado', 0, 'a_favor', abs(v_pend_a), 'motivo', 'la factura que anula no está pendiente');
  end if;
  select id into v_ef from public.journal_entry
   where account_id = f.account_id and source_type = 'supplier_invoice' and source_id = f.id and status = 'validado'
   order by validated_at desc nulls last limit 1;
  v_pend_f := coalesce(f.grand_total, 0) - coalesce((select sum(amount) from public.supplier_invoice_payment where invoice_id = f.id), 0);
  if v_ef is null or v_pend_f < 0.005 then
    return jsonb_build_object('abono', a.id, 'compensado', 0, 'a_favor', abs(v_pend_a), 'motivo', 'la factura que anula no tiene asiento o no debe nada');
  end if;
  v_comp := least(v_pend_f, abs(v_pend_a));
  v_nombre := 'Sumied · compensación del abono';
  insert into public.supplier_invoice_payment (account_id, company_id, invoice_id, paid_on, amount, method, note, entry_id, created_by_name)
  values (f.account_id, f.company_id, f.id, a.invoice_date, v_comp, 'compensation',
          format('Compensada con el abono %s (%s)', coalesce(a.invoice_number, ''), a.code), v_ea, v_nombre),
         (a.account_id, a.company_id, a.id, a.invoice_date, -v_comp, 'compensation',
          format('Compensa la factura %s (%s)', coalesce(f.invoice_number, ''), f.code), v_ef, v_nombre);
  if v_pend_f - v_comp < 0.005 then
    update public.supplier_invoice set status = 'pagada', paid_at = a.invoice_date, paid_method = 'compensation', paid_by_name = v_nombre, updated_at = now() where id = f.id;
    insert into public.supplier_invoice_payment_log (account_id, invoice_id, action, paid_at, paid_method, actor_name)
    values (f.account_id, f.id, 'paid', a.invoice_date, 'compensation', v_nombre);
  end if;
  if abs(v_pend_a) - v_comp < 0.005 then
    update public.supplier_invoice set status = 'pagada', paid_at = a.invoice_date, paid_method = 'compensation', paid_by_name = v_nombre, updated_at = now() where id = a.id;
    insert into public.supplier_invoice_payment_log (account_id, invoice_id, action, paid_at, paid_method, actor_name)
    values (a.account_id, a.id, 'paid', a.invoice_date, 'compensation', v_nombre);
  end if;
  return jsonb_build_object('abono', a.id, 'factura', f.id, 'compensado', v_comp, 'a_favor', abs(v_pend_a) - v_comp,
    'texto', format('El abono %s compensa %s de la factura %s.', coalesce(a.invoice_number, a.code), public.conta_euros_exactos(v_comp), coalesce(f.invoice_number, f.code)));
end $$;


--
-- Name: conta_abono_pasarela_casar(uuid, uuid[], text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_abono_pasarela_casar(p_movement uuid, p_enlaces uuid[], p_confianza text, p_porque text, p_por text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_m public.bank_movement; v_t public.treasury_account; v_aj public.bank_settings; v_cuenta uuid; v_n int; v_prov text; v_nprov int;
  v_bruto numeric; v_fees numeric; v_fees_n int; v_com numeric; v_desde date; v_hasta date; v_gas text; v_572 text; v_local uuid; v_comun boolean;
  v_lineas jsonb; v_l record; v_res jsonb; v_entry uuid; v_match uuid; v_nombre text; v_periodo text; v_concepto text; v_quien text;
  v_pas text; v_sin text;
begin
  select * into v_m from public.bank_movement where id = p_movement for update;
  if v_m.id is null then raise exception 'Ese movimiento no existe.' using errcode = 'P0002'; end if;
  v_cuenta := public._pc01e3_empresa(v_m.company_id);
  if p_por not in ('folvy', 'persona') then raise exception 'Quién casa: folvy o persona.' using errcode = '23514'; end if;
  if v_m.amount <= 0 then raise exception 'El abono de Stripe o del TPV entra en el banco, y este movimiento sale.' using errcode = '23514'; end if;
  if coalesce(cardinality(p_enlaces), 0) = 0 then raise exception 'Di qué cobros trae este abono.' using errcode = '22023'; end if;
  perform 1 from public.conta_enlace_pago where id = any(p_enlaces) for update;
  select count(*), count(distinct coalesce(e.proveedor, 'stripe')), min(coalesce(e.proveedor, 'stripe')), sum(p.amount), sum(e.comision), count(e.comision),
         min((e.pagado_at at time zone 'Europe/Madrid')::date), max((e.pagado_at at time zone 'Europe/Madrid')::date)
    into v_n, v_nprov, v_prov, v_bruto, v_fees, v_fees_n, v_desde, v_hasta
    from public.conta_enlace_pago e join public.customer_invoice_payment p on p.id = e.payment_id
   where e.id = any(p_enlaces) and e.company_id = v_m.company_id and e.status = 'pagado'
     and not exists (select 1 from public.bank_match b where b.id = e.abono_match_id and b.status = 'vivo');
  if v_n <> cardinality(p_enlaces) then raise exception 'Alguno de esos cobros no es de la empresa, no está cobrado o ya tiene su abono.' using errcode = '23514'; end if;
  if v_nprov <> 1 then raise exception 'Un abono es de un solo proveedor: no se juntan cobros de Stripe y del TPV.' using errcode = '23514'; end if;
  v_nombre := case v_prov when 'redsys' then 'tu TPV (Redsys)' else 'Stripe' end;
  v_com := round(v_bruto - v_m.amount, 2);
  if v_com < 0 then
    raise exception 'El abono (%) es mayor que esos cobros (%): no son estos.', public.conta_euros_exactos(v_m.amount), public.conta_euros_exactos(v_bruto) using errcode = '23514';
  end if;
  if v_com > round(v_bruto * 0.10, 2) then
    raise exception 'Con esos cobros (%) la comisión saldría de %, más del 10 %%: no parecen estos.', public.conta_euros_exactos(v_bruto), public.conta_euros_exactos(v_com) using errcode = '23514';
  end if;
  if v_fees_n = v_n and abs(v_fees - v_com) >= 0.005 then
    raise exception '% dice que la comisión de esos cobros es de %, y este abono deja %: no cuadra.', v_nombre, public.conta_euros_exactos(v_fees), public.conta_euros_exactos(v_com) using errcode = '23514';
  end if;
  select * into v_t from public.treasury_account where id = v_m.treasury_account_id;
  v_572 := public._bank_cuenta_572(v_t.id);
  if v_572 is null then raise exception 'La cuenta «%» no tiene su cuenta contable (572): dila en Cuentas y extractos.', v_t.name using errcode = '23514'; end if;
  if v_com > 0 then
    v_gas := public._pc01e3_cuenta_gastos(v_m.company_id);
    if v_gas is null then raise exception 'La empresa no tiene una cuenta 626 para la comisión: créala en el plan.' using errcode = '23514'; end if;
  end if;
  -- Cada cobro, con su asiento contra la pasarela.
  select string_agg(coalesce(ci.number_text, 'sin número'), ', ') into v_sin
    from public.conta_enlace_pago e join public.customer_invoice_payment p on p.id = e.payment_id join public.customer_invoice ci on ci.id = e.invoice_id
   where e.id = any(p_enlaces) and not exists (select 1 from public.journal_entry j where j.id = p.entry_id and j.status in ('propuesto', 'borrador', 'validado'));
  if v_sin is not null then
    raise exception 'El cobro de % aún no tiene su asiento (la pasarela contra la 430): sin él no hay nada que saldar. Mira su historial.', v_sin using errcode = '23514';
  end if;
  select code into v_pas from public.conta_pasarela_cuenta where company_id = v_m.company_id and proveedor = v_prov;
  if v_pas is null then raise exception 'La empresa no tiene la cuenta de % por abonar.', v_nombre using errcode = '23514'; end if;
  v_local := v_t.location_id; v_comun := v_local is null;
  v_periodo := case when v_desde = v_hasta then 'del ' || to_char(v_desde, 'DD/MM') else format('del %s al %s', to_char(v_desde, 'DD/MM'), to_char(v_hasta, 'DD/MM')) end;
  v_concepto := format('Abono de %s %s', case v_prov when 'redsys' then 'TPV' else 'Stripe' end, v_periodo);
  v_lineas := jsonb_build_array(jsonb_build_object('cuenta', v_572, 'debe', v_m.amount, 'haber', 0, 'concepto', v_concepto, 'local_id', v_local, 'comun', v_comun));
  if v_com > 0 then
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_gas, 'debe', v_com, 'haber', 0,
      'concepto', format('Comisión %s %s', case v_prov when 'redsys' then 'TPV' else 'Stripe' end, v_periodo), 'local_id', v_local, 'comun', v_comun));
  end if;
  v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_pas, 'debe', 0, 'haber', v_bruto,
    'concepto', format('%s · %s %s', v_concepto, v_n, case when v_n = 1 then 'cobro' else 'cobros' end), 'local_id', v_local, 'comun', v_comun));
  v_aj := public._bank_ajustes(v_m.company_id);
  v_quien := case when p_por = 'folvy' then 'Folvy' else public.conta_nombre_actor() end;
  v_res := public._journal_entry_proponer(v_m.company_id,
    jsonb_build_object('fecha', v_m.op_date, 'series', v_aj.treasury_series, 'concepto', v_concepto, 'source_type', 'bank', 'source_id', v_m.id,
                       'confianza', p_confianza, 'porque', p_porque, 'razones', '[]'::jsonb, 'party_id', null, 'documento', coalesce(v_m.document_no, v_m.reference_1)),
    v_lineas, '{}'::jsonb, v_quien, auth.uid());
  if coalesce((v_res->>'descartada')::boolean, false) then raise exception 'Ese movimiento tenía la propuesta descartada.' using errcode = '23514'; end if;
  v_entry := (v_res->>'id')::uuid;
  perform public.bank_casar(p_movement, jsonb_build_object('tipo', 'asiento', 'entry_id', v_entry, 'concepto', v_concepto), p_confianza, p_porque, '[]'::jsonb, p_por, null);
  select id into v_match from public.bank_match where movement_id = p_movement and status = 'vivo';
  -- El asiento lo ha creado este casado: deshacerlo en Bancos lo quita (bank_deshacer).
  update public.bank_match set entry_created = not coalesce((v_res->>'existente')::boolean, false) where id = v_match;
  update public.conta_enlace_pago set abono_match_id = v_match where id = any(p_enlaces);
  for v_l in select e.invoice_id, p.amount from public.conta_enlace_pago e join public.customer_invoice_payment p on p.id = e.payment_id where e.id = any(p_enlaces) loop
    perform public._conta_venta_evento(v_l.invoice_id, 'abono',
      format('Llega al banco el abono de %s con este cobro (%s), el %s.', v_nombre, public.conta_euros_exactos(v_l.amount), to_char(v_m.op_date, 'DD/MM/YYYY')),
      jsonb_build_object('casado', v_match, 'asiento', v_entry), v_quien);
  end loop;
  return jsonb_build_object('casado', v_match, 'asiento', v_entry, 'cobros', v_n, 'comision', v_com,
    'frase', format('Casado el abono de %s %s: %s %s, %s menos %s de comisión. Asiento: %s al banco y %s a comisiones; %s queda saldada por esos cobros.', v_nombre, v_periodo,
      v_n, case when v_n = 1 then 'cobro' else 'cobros' end, public.conta_euros_exactos(v_bruto), public.conta_euros_exactos(v_com),
      public.conta_euros_exactos(v_m.amount), public.conta_euros_exactos(v_com),
      case v_prov when 'redsys' then '«TPV del banco · por abonar»' else '«Stripe · por abonar»' end));
end $$;


--
-- Name: FUNCTION conta_abono_pasarela_casar(p_movement uuid, p_enlaces uuid[], p_confianza text, p_porque text, p_por text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_abono_pasarela_casar(p_movement uuid, p_enlaces uuid[], p_confianza text, p_porque text, p_por text) IS 'S01 · Casa el abono de Stripe o del TPV (Redsys) con sus cobros por el enlace: 572 por el neto y 626 por la comisión contra la cuenta de la pasarela. Deshacer el casado lo quita.';


--
-- Name: conta_abonos_pasarela_pendientes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_abonos_pasarela_pendientes(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', e.id, 'proveedor', coalesce(e.proveedor, 'stripe'), 'fecha', (e.pagado_at at time zone 'Europe/Madrid')::date,
      'bruto', p.amount, 'comision', e.comision, 'neto', e.neto, 'factura', ci.number_text, 'cliente', coalesce(pa.name, ci.customer->>'nombre'),
      'cuenta', pc.code, 'tercero_id', ci.party_id,
      'con_asiento', exists (select 1 from public.journal_entry j where j.id = p.entry_id and j.status in ('propuesto', 'borrador', 'validado'))) order by e.pagado_at)
    from public.conta_enlace_pago e
    join public.customer_invoice_payment p on p.id = e.payment_id
    left join public.conta_pasarela_cuenta pc on pc.company_id = e.company_id and pc.proveedor = coalesce(e.proveedor, 'stripe')
    join public.customer_invoice ci on ci.id = e.invoice_id
    left join public.party pa on pa.id = ci.party_id
   where e.company_id = p_company and e.status = 'pagado'
     and not exists (select 1 from public.bank_match b where b.id = e.abono_match_id and b.status = 'vivo')), '[]'::jsonb);
end $$;


--
-- Name: conta_ajustes_compras_guardar(uuid, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ajustes_compras_guardar(p_company uuid, p_recibe boolean, p_apuntar_seguro boolean, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta cambia los ajustes de compras.' using errcode = '42501';
  end if;
  insert into public.company_purchase_setting (company_id, account_id, receives_goods, receives_goods_reason, post_safe_invoices, updated_at, updated_by, updated_by_name)
  values (p_company, v_acc, p_recibe, 'Lo decidió ' || coalesce(p_quien_nombre, 'una persona') || ' el ' || to_char(now() at time zone 'Europe/Madrid', 'DD/MM/YYYY') || '.',
          p_apuntar_seguro, now(), auth.uid(), p_quien_nombre)
  on conflict (company_id) do update
     set receives_goods = excluded.receives_goods, receives_goods_reason = excluded.receives_goods_reason,
         post_safe_invoices = excluded.post_safe_invoices, updated_at = now(), updated_by = auth.uid(), updated_by_name = p_quien_nombre;
  return (select to_jsonb(s) from public.company_purchase_setting s where s.company_id = p_company);
end $$;


--
-- Name: conta_al_dia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_al_dia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  return new;
end $$;


--
-- Name: conta_apuntada_sola_deshacer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_apuntada_sola_deshacer(p_invoice uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.supplier_invoice; a public.supplier_invoice_auto; v_quien text;
begin
  select * into v from public.supplier_invoice where id = p_invoice for update;
  if v.id is null or not public.belongs_to_account(v.account_id) then raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501'; end if;
  -- Anular un asiento validado es de administrador (journal_entry_anular): deshacer, también.
  if not public.current_user_is_admin_of(v.account_id) then raise exception 'Solo un administrador deshace lo apuntado solo.' using errcode = '42501'; end if;
  select * into a from public.supplier_invoice_auto where invoice_id = v.id and estado = 'apuntada';
  if a.invoice_id is null then raise exception 'Esta factura no la apuntó Sumied sola.' using errcode = '22023'; end if;
  v_quien := coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
  perform public.journal_entry_anular(a.entry_id, 'Deshecho lo apuntado solo por Sumied', current_date, v_quien);
  delete from public.supplier_invoice_payment where invoice_id = v.id and account_id = v.account_id and method = 'compensation' and created_by_name = 'Sumied · compensada con la liquidación';
  if v.paid_at is not null then
    insert into public.supplier_invoice_payment_log (account_id, invoice_id, action, paid_at, paid_method, actor_name)
    values (v.account_id, v.id, 'unpaid', v.paid_at, v.paid_method, v_quien);
  end if;
  update public.supplier_invoice set status = 'en_revision', paid_at = null, paid_method = null, paid_by_name = null, approved_at = null, approved_by_name = null, updated_at = now() where id = v.id;
  update public.supplier_invoice_auto set estado = 'deshecha', porque = format('Devuelta a «Por revisar» por %s.', v_quien), at = now() where invoice_id = v.id;
  return jsonb_build_object('texto', format('Devuelta a «Por revisar»: %s. Su asiento queda anulado con su contraasiento.', coalesce(v.invoice_number, 'la factura')));
end $$;


--
-- Name: conta_apuntadas_solas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_apuntadas_solas(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no es tuya.' using errcode = '42501'; end if;
  return jsonb_build_object(
    'semana', (select count(*) from public.supplier_invoice_auto a where a.account_id = v_acc and a.company_id = p_company and a.estado = 'apuntada' and a.at >= now() - interval '7 days'),
    'filas', coalesce((select jsonb_agg(jsonb_build_object('id', a.invoice_id, 'porque', a.porque, 'regla', a.regla, 'asiento', a.entry_id, 'at', a.at) order by a.at desc)
                         from public.supplier_invoice_auto a where a.account_id = v_acc and a.company_id = p_company and a.estado = 'apuntada'), '[]'::jsonb),
    'motivos', coalesce((select jsonb_object_agg(a.invoice_id, a.porque) from public.supplier_invoice_auto a where a.account_id = v_acc and a.company_id = p_company and a.estado in ('no', 'deshecha')), '{}'::jsonb));
end $$;


--
-- Name: conta_apunte_pago_modelo(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_apunte_pago_modelo(p_entry uuid, p_posicion integer, p_modelo text, p_periodo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare e journal_entry; l journal_line; a company_account; v_txt text;
begin
  select * into e from journal_entry where id = p_entry;
  if e.id is null or not public.current_user_is_admin_or_manager_of(e.account_id) then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  if e.status not in ('borrador', 'propuesto') then
    raise exception 'El asiento ya está %: un asiento validado no se cambia.', e.status using errcode = '22023';
  end if;
  select * into l from journal_line where entry_id = e.id and position = p_posicion;
  select * into a from company_account where id = l.company_account_id;
  if l.id is null or a.template_code not like '4751%' then
    raise exception 'Solo un apunte de la 4751 es el pago de un modelo.' using errcode = '22023';
  end if;
  if p_modelo is null or p_modelo not in ('111', '115', '123') then raise exception 'Di el modelo: 111, 115 o 123.' using errcode = '22023'; end if;
  if p_periodo is null or p_periodo !~ '^[0-9]{4}-([1-4]T|0[1-9]|1[0-2]|0A)$' then
    raise exception 'Di el periodo: el año y el trimestre (3T), el mes o el año entero.' using errcode = '22023';
  end if;
  update journal_line set withholding_model = p_modelo, withholding_period = p_periodo, withholding_rate_id = null, withholding_base = null
   where id = l.id;
  v_txt := public.conta_modelo_periodo_texto(p_modelo, p_periodo);
  return jsonb_build_object('mensaje', format('Apuntado: el apunte %s (%s) es %s de %s.', p_posicion, a.code,
    case when l.debit > 0 then 'el pago' else 'la devolución' end, v_txt), 'pagado', public.conta_modelo_pagado(e.company_id, p_modelo, p_periodo));
end $_$;


--
-- Name: conta_asesoria_aceptar(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_aceptar(p_token_hash text, p_advisor_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.tax_advisor_invitation; c public.company;
begin
  select * into i from public.tax_advisor_invitation where token_hash = p_token_hash for update;
  if i.id is null then raise exception 'Esa invitación no existe: pide a la empresa que te mande otra.' using errcode = 'P0002'; end if;
  select * into c from public.company where id = i.company_id;
  if i.status = 'accepted' then return jsonb_build_object('estado', 'accepted', 'mensaje', 'Ya estaba aceptada: entra con tu usuario.'); end if;
  if i.status = 'waiting_approval' then
    return jsonb_build_object('estado', 'waiting_approval', 'mensaje', 'Ya estaba aceptada: espera el correo para poner tu contraseña.');
  end if;
  if i.status <> 'pending' or i.expires_at <= now() then
    raise exception 'Esta invitación ya no vale (%): pide a % que te mande otra.',
      case when i.status = 'cancelled' then 'la canceló la empresa' else 'caducó' end, c.legal_name using errcode = '22023';
  end if;
  if p_advisor_account is not null then
    perform public.conta_asesoria_vincular(i, p_advisor_account);
    return jsonb_build_object('estado', 'accepted', 'mensaje',
      format('Hecho: ya llevas los impuestos de %s. Entra con tu usuario y la verás en Impuestos.', c.legal_name));
  end if;
  update public.tax_advisor_invitation set status = 'waiting_approval', accepted_at = now() where id = i.id;
  return jsonb_build_object('estado', 'waiting_approval', 'mensaje',
    format('Recibido. Sumied dará de alta tu cuenta y te llegará un correo a %s para poner tu contraseña; entonces verás %s en Impuestos.', i.email, c.legal_name));
end $$;


--
-- Name: conta_asesoria_aprobar(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_aprobar(p_invitation uuid, p_platform_user uuid, p_advisor_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.tax_advisor_invitation;
begin
  if not exists (select 1 from public.platform_admins where user_id = p_platform_user and active) then
    raise exception 'Solo un administrador de la plataforma da el alta de una asesoría.' using errcode = '42501';
  end if;
  select * into i from public.tax_advisor_invitation where id = p_invitation for update;
  if i.id is null then raise exception 'Esa invitación no está.' using errcode = 'P0002'; end if;
  if i.status <> 'waiting_approval' then raise exception 'Esa invitación no espera el alta (está «%»).', i.status using errcode = '22023'; end if;
  perform public.conta_asesoria_vincular(i, p_advisor_account);
  update public.tax_advisor_invitation set approved_by = p_platform_user, approved_at = now() where id = i.id;
  return jsonb_build_object('ok', true, 'mensaje', format('Vinculada: %s lleva los impuestos de la empresa.', i.advisor_name));
end $$;


--
-- Name: conta_asesoria_caducar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_caducar(p_company uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.tax_advisor_invitation set status = 'expired'
   where company_id = p_company and status = 'pending' and expires_at <= now()
$$;


--
-- Name: conta_asesoria_cancelar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_cancelar(p_invitation uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.tax_advisor_invitation;
begin
  select * into i from public.tax_advisor_invitation where id = p_invitation for update;
  if i.id is null then raise exception 'Esa invitación no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(i.account_id) then
    raise exception 'Solo un administrador de la empresa cancela su invitación.' using errcode = '42501';
  end if;
  if i.status not in ('pending', 'waiting_approval') then return 'Esa invitación ya no estaba viva.'; end if;
  update public.tax_advisor_invitation set status = 'cancelled', cancelled_by = auth.uid(), cancelled_at = now() where id = i.id;
  return format('Cancelada la invitación a %s: su enlace ya no sirve.', i.email);
end $$;


--
-- Name: conta_asesoria_cuenta_de(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_cuenta_de(p_email text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when count(distinct u.account_id) = 1 then min(u.account_id::text)::uuid end
    from public.user_profiles u join auth.users a on a.id = u.user_id
   where lower(a.email) = lower(btrim(p_email)) and u.active and u.role = 'admin'
$$;


--
-- Name: conta_asesoria_de_empresa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_de_empresa(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.tax_advisor_invitation;
begin
  if not public.conta_impuesto_puede_ver(p_company) then raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501'; end if;
  perform public.conta_asesoria_caducar(p_company);
  select * into i from public.tax_advisor_invitation where company_id = p_company and status in ('pending', 'waiting_approval');
  if i.id is null then return null; end if;
  return jsonb_build_object('id', i.id, 'estado', i.status, 'correo', i.email, 'asesoria', i.advisor_name, 'base', i.basis,
    'invita', i.invited_by_name, 'creada', i.created_at, 'expira', i.expires_at, 'envios', i.sends, 'ultimo_envio', i.last_sent_at);
end $$;


--
-- Name: conta_asesoria_invitar(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_invitar(p_user uuid, p_company uuid, p_email text, p_nombre text, p_basis text, p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare c public.company; i public.tax_advisor_invitation; v_email text := lower(btrim(coalesce(p_email, ''))); v_nombre text;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_cert_es_admin(p_user, c.account_id) then
    raise exception 'Solo un administrador de la empresa invita a su asesoría.' using errcode = '42501';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Escribe un correo válido.' using errcode = '22023'; end if;
  if btrim(coalesce(p_nombre, '')) = '' then raise exception 'Falta el nombre de la asesoría.' using errcode = '22023'; end if;
  if p_basis not in ('social_collaborator', 'power_of_attorney') then raise exception 'Di cómo presenta la asesoría: como colaboradora social o con un poder.' using errcode = '22023'; end if;
  if p_token_hash !~ '^[0-9a-f]{64}$' then raise exception 'Falta el enlace de la invitación.' using errcode = '22023'; end if;
  if exists (select 1 from public.user_profiles u join auth.users a on a.id = u.user_id
              where u.account_id = c.account_id and u.active and lower(a.email) = v_email) then
    raise exception 'Ese correo es de una persona de tu propia cuenta: invita a la asesoría con el suyo.' using errcode = '22023';
  end if;
  perform public.conta_asesoria_caducar(p_company);
  v_nombre := public.conta_cert_nombre(p_user, c.account_id);
  select * into i from public.tax_advisor_invitation where company_id = p_company and status in ('pending', 'waiting_approval') for update;
  if i.id is not null then
    if i.status = 'waiting_approval' then
      raise exception 'La invitación a % ya está aceptada y espera que Sumied dé de alta su cuenta.', i.email using errcode = '22023';
    end if;
    if i.email <> v_email then
      raise exception 'Ya hay una invitación viva a % hasta el %: cancélala antes de invitar a otra.', i.email,
        to_char(i.expires_at at time zone 'Europe/Madrid', 'DD/MM') using errcode = '22023';
    end if;
    if i.sends >= 3 then raise exception 'Esta invitación ya se ha mandado 3 veces: cancélala y crea otra si hace falta.' using errcode = '22023'; end if;
    if i.last_sent_at > now() - interval '1 hour' then
      raise exception 'Se mandó hace menos de una hora: espera un poco antes de volver a mandarla.' using errcode = '22023';
    end if;
    update public.tax_advisor_invitation set token_hash = p_token_hash, sends = sends + 1, last_sent_at = now(),
           expires_at = now() + interval '7 days', advisor_name = btrim(p_nombre), basis = p_basis
     where id = i.id returning * into i;
    return jsonb_build_object('id', i.id, 'reenvio', true, 'expira', i.expires_at, 'empresa', c.legal_name, 'invita', v_nombre);
  end if;
  if (select count(*) from public.tax_advisor_invitation where company_id = p_company and created_at > now() - interval '30 days') >= 5 then
    raise exception 'Esta empresa ya ha creado 5 invitaciones en 30 días: no se mandan más por ahora.' using errcode = '22023';
  end if;
  insert into public.tax_advisor_invitation (account_id, company_id, email, advisor_name, basis, token_hash, invited_by, invited_by_name, expires_at)
  values (c.account_id, p_company, v_email, btrim(p_nombre), p_basis, p_token_hash, p_user, v_nombre, now() + interval '7 days')
  returning * into i;
  return jsonb_build_object('id', i.id, 'reenvio', false, 'expira', i.expires_at, 'empresa', c.legal_name, 'invita', v_nombre);
end $_$;


--
-- Name: conta_asesoria_pendientes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_pendientes() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from public.platform_admins where user_id = auth.uid() and active) then
    raise exception 'Solo un administrador de la plataforma ve las altas de asesorías.' using errcode = '42501';
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'asesoria', i.advisor_name, 'correo', i.email, 'base', i.basis,
                                                       'empresa', c.legal_name, 'cuenta_empresa', a.name,
                                                       'invita', i.invited_by_name, 'aceptada', i.accepted_at,
                                                       'ya_es_admin_de', (select count(distinct u.account_id) from public.user_profiles u join auth.users au on au.id = u.user_id
                                                                          where lower(au.email) = i.email and u.active and u.role = 'admin'))
                                    order by i.accepted_at), '[]')
            from public.tax_advisor_invitation i join public.company c on c.id = i.company_id join public.accounts a on a.id = i.account_id
           where i.status = 'waiting_approval');
end $$;


--
-- Name: conta_asesoria_ver(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_ver(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.tax_advisor_invitation; c public.company;
begin
  select * into i from public.tax_advisor_invitation where token_hash = p_token_hash;
  if i.id is null then return jsonb_build_object('estado', 'no_esta'); end if;
  perform public.conta_asesoria_caducar(i.company_id);
  select * into i from public.tax_advisor_invitation where id = i.id;
  select * into c from public.company where id = i.company_id;
  return jsonb_build_object('estado', i.status, 'empresa', c.legal_name, 'invita', i.invited_by_name,
    'asesoria', i.advisor_name, 'base', i.basis, 'correo', i.email, 'expira', i.expires_at);
end $$;


--
-- Name: tax_advisor_invitation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_advisor_invitation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    email text NOT NULL,
    advisor_name text NOT NULL,
    basis text NOT NULL,
    token_hash text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    invited_by uuid NOT NULL,
    invited_by_name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    sends smallint DEFAULT 1 NOT NULL,
    last_sent_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
    advisor_account_id uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    cancelled_by uuid,
    cancelled_at timestamp with time zone,
    CONSTRAINT tax_advisor_invitation_advisor_name_check CHECK ((btrim(advisor_name) <> ''::text)),
    CONSTRAINT tax_advisor_invitation_basis_check CHECK ((basis = ANY (ARRAY['social_collaborator'::text, 'power_of_attorney'::text]))),
    CONSTRAINT tax_advisor_invitation_check CHECK (((status = 'accepted'::text) = (advisor_account_id IS NOT NULL))),
    CONSTRAINT tax_advisor_invitation_check1 CHECK (((status <> 'cancelled'::text) OR (cancelled_at IS NOT NULL))),
    CONSTRAINT tax_advisor_invitation_email_check CHECK (((email = lower(email)) AND (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'::text))),
    CONSTRAINT tax_advisor_invitation_sends_check CHECK (((sends >= 1) AND (sends <= 3))),
    CONSTRAINT tax_advisor_invitation_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'waiting_approval'::text, 'accepted'::text, 'cancelled'::text, 'expired'::text]))),
    CONSTRAINT tax_advisor_invitation_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE tax_advisor_invitation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_advisor_invitation IS 'I01b. La invitación de una empresa a su asesoría: vincula al aceptar si la asesoría ya tiene Sumied; si no, espera el alta de la plataforma. Del token solo se guarda su huella.';


--
-- Name: conta_asesoria_vincular(public.tax_advisor_invitation, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asesoria_vincular(i public.tax_advisor_invitation, p_advisor_account uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_advisor_account = i.account_id then
    raise exception 'La asesoría no puede ser la misma cuenta que la empresa.' using errcode = '22023';
  end if;
  insert into public.company_tax_presenter (company_id, account_id, mode, advisor_account_id, advisor_basis, consented_by, consented_by_name, consented_at, since)
  values (i.company_id, i.account_id, 'advisor', p_advisor_account, i.basis, i.invited_by, i.invited_by_name, now(), current_date)
  on conflict (company_id) do update set mode = 'advisor', advisor_account_id = excluded.advisor_account_id, advisor_basis = excluded.advisor_basis,
    consented_by = excluded.consented_by, consented_by_name = excluded.consented_by_name, consented_at = excluded.consented_at,
    revoked_by = null, revoked_at = null, certificate_id = null, since = current_date, updated_at = now();
  update public.tax_advisor_invitation set status = 'accepted', accepted_at = coalesce(accepted_at, now()), advisor_account_id = p_advisor_account
   where id = i.id;
end $$;


--
-- Name: conta_asiento_envio(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_asiento_envio(p_entry uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry;
  v_o text;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null or not (public.belongs_to_account(v_e.account_id) or auth.role() = 'service_role') then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  if v_e.reverses_entry_id is not null then
    select o.source_type into v_o from public.journal_entry o where o.id = v_e.reverses_entry_id and o.account_id = v_e.account_id;
  end if;
  return jsonb_build_object(
    'id', v_e.id, 'account_id', v_e.account_id, 'company_id', v_e.company_id,
    'estado', v_e.status, 'origen', v_e.source_type, 'serie', v_e.series, 'numero', v_e.number,
    'fecha', v_e.entry_date, 'concepto', v_e.concept, 'anula', v_e.reverses_entry_id, 'anulaOrigen', v_o,
    'lineas', coalesce((
      select jsonb_agg(jsonb_build_object('cuenta', a.code, 'debe', l.debit, 'haber', l.credit, 'concepto', l.concept) order by l.position)
        from public.journal_line l
        join public.company_account a on a.id = l.company_account_id and a.company_id = v_e.company_id
       where l.entry_id = v_e.id and l.account_id = v_e.account_id), '[]'::jsonb));
end $$;


--
-- Name: FUNCTION conta_asiento_envio(p_entry uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_asiento_envio(p_entry uuid) IS 'C07 · Lo que el envío a Diez lee de un asiento que va como asiento general (banco, manual, liquidación…) o de su contraasiento: cabecera, origen, lo que anula y sus líneas con la cuenta. Para los de la cuenta, o el servidor.';


--
-- Name: conta_banco_agregador_despertar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_banco_agregador_despertar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_secreto text;
begin
  if extract(hour from (now() at time zone 'Europe/Madrid')) <> 3 then return; end if;
  if not exists (select 1 from public.bank_aggregator_connection where enabled) then return; end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  if v_secreto is null then
    raise exception 'Falta cron_secret en el Vault: no se puede despertar a conta-banco-agregador.' using errcode = '55000';
  end if;
  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/conta-banco-agregador',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := '{}'::jsonb, timeout_milliseconds := 150000);
end $$;


--
-- Name: FUNCTION conta_banco_agregador_despertar(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_banco_agregador_despertar() IS 'B01c · Cada hora (cron conta-banco-agregador-despertar, solo en producción): a las 3 de Madrid, si hay alguna empresa conectada, llama a conta-banco-agregador. Si falta el secreto, falla (cron lo apunta como failed), no calla.';


--
-- Name: conta_canal_de_factura(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_canal_de_factura(p_invoice uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select r.channel_id from public.customer_invoice ci
       join public.sales_day_summary s on s.entry_id = ci.entry_id and s.company_id = ci.company_id and s.channel_id is not null
       join public.party_role r on r.account_id = ci.account_id and r.role = 'platform' and r.channel_id = s.channel_id
      where ci.id = p_invoice limit 1),
    (select r.channel_id from public.customer_invoice ci
       join public.journal_line jl on jl.entry_id = ci.entry_id and jl.company_id = ci.company_id and jl.debit > 0
       join public.company_account ca on ca.id = jl.company_account_id and ca.code like '430%'
       join public.company_account_link k on k.account_id = ci.account_id and k.company_id = ci.company_id and k.company_account_id = ca.id
                                         and k.entity = 'customer' and k.role = 'principal'
       join public.party_role r on r.account_id = ci.account_id and r.role = 'platform' and r.party_id::text = k.entity_id and r.channel_id is not null
      where ci.id = p_invoice and ci.origin = 'cierre_dia' limit 1))
$$;


--
-- Name: conta_cargos_de_pedidos(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cargos_de_pedidos(p_account uuid, p_sales uuid[]) RETURNS TABLE(id uuid, descuento numeric, envio numeric, reparto text, clase text, por_que text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  select s.id,
         greatest(coalesce(s.discount_amount, 0), 0),
         x.envio,
         s.service_type,
         case when x.envio = 0 then 'ninguno'
              when a.decision = 'lo_paga' then 'cobrado'
              when a.decision = 'no_lo_paga' then 'fuera'
              when s.service_type = 'own_delivery' and coalesce(r.source, '') <> 'default' then 'cobrado'
              else 'por_aclarar' end,
         case when x.envio = 0 or a.decision is not null then null
              when s.service_type = 'own_delivery' and coalesce(r.source, '') <> 'default' then null
              when s.service_type = 'own_delivery' then 'quién reparte está por defecto (nadie lo ha dicho)'
              when s.service_type = 'platform_delivery' then 'repartió la plataforma'
              when s.service_type = 'pickup' then 'el pedido es de recogida'
              else 'sin decir quién repartió' end
    from public.sale s
    cross join lateral (
      select coalesce(sum(split_part(c->>'price', ' ', 1)::numeric), 0) as envio
        from jsonb_array_elements(case when jsonb_typeof(public.conta_json_seguro(s.raw_tab)->'charges') = 'array'
                                       then public.conta_json_seguro(s.raw_tab)->'charges' else '[]'::jsonb end) c
       where c->>'type' = 'delivery' and coalesce(c->>'deleted', 'false') <> 'true'
         and split_part(c->>'price', ' ', 1) ~ '^[0-9]+(\.[0-9]+)?$'
    ) x
    left join public.conta_envio_aclarado a on a.sale_id = s.id and a.account_id = s.account_id
    left join lateral (
      select d.source from public.sales_channel ch, public.resolve_delivery_by(s.account_id, s.brand_id, ch.slug, s.location_id) d
       where ch.id = s.channel_id and ch.account_id = s.account_id and x.envio > 0 and s.service_type = 'own_delivery'
    ) r on true
   where s.account_id = p_account and s.id = any (p_sales)
$_$;


--
-- Name: FUNCTION conta_cargos_de_pedidos(p_account uuid, p_sales uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_cargos_de_pedidos(p_account uuid, p_sales uuid[]) IS 'C06b (16/10): de cada pedido, su descuento y su envío (con el IVA dentro), quién repartió (lo guardado al entrar) y qué se hace con el envío: ninguno, cobrado (va a Envíos cobrados), por_aclarar (no se sabe si es del restaurante) o fuera (la plataforma no lo paga).';


--
-- Name: conta_catcher_saldo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_catcher_saldo(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_ca public.company_account; r record; u public.supplier_balance_check;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  select * into v_ca from public.company_account where account_id = v_acc and company_id = p_company and code = '40700001';
  if v_ca.id is null then
    return jsonb_build_object('cuenta', '40700001', 'existe', false, 'texto', 'Falta la 40700001 «Saldo prepago Catcher» en el plan de la empresa.');
  end if;
  select coalesce(sum(l.debit) filter (where e.status = 'validado'), 0) as recargas_v, coalesce(sum(l.credit) filter (where e.status = 'validado'), 0) as pagos_v,
         coalesce(sum(l.debit) filter (where e.status in ('propuesto', 'borrador')), 0) as recargas_p, coalesce(sum(l.credit) filter (where e.status in ('propuesto', 'borrador')), 0) as pagos_p,
         max(e.entry_date) filter (where e.status in ('propuesto', 'borrador', 'validado')) as ultimo
    into r
    from public.journal_line l join public.journal_entry e on e.id = l.entry_id and e.company_id = p_company
   where l.company_account_id = v_ca.id;
  select * into u from public.supplier_balance_check where company_id = p_company and provider = 'catcher' order by checked_at desc limit 1;
  return jsonb_build_object('cuenta', v_ca.code, 'nombre', v_ca.name, 'existe', true,
    'recargas', r.recargas_v + r.recargas_p, 'pagos', r.pagos_v + r.pagos_p, 'saldo', (r.recargas_v + r.recargas_p) - (r.pagos_v + r.pagos_p),
    'saldo_validado', r.recargas_v - r.pagos_v, 'propuesto', (r.recargas_p - r.pagos_p), 'ultimo_movimiento', r.ultimo,
    'ultima_comprobacion', case when u.id is null then null else jsonb_build_object('cuando', u.checked_at, 'portal', u.portal_amount, 'app', u.app_amount, 'coincide', u.matches, 'quien', u.checked_by_name) end);
end $$;


--
-- Name: FUNCTION conta_catcher_saldo(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_catcher_saldo(p_company uuid) IS 'E05 · El saldo de la 40700001 «Saldo prepago Catcher» en la app: recargas (debe) menos pagos (haber), con lo validado y lo propuesto por separado, y la última vez que se comparó con el portal.';


--
-- Name: conta_catcher_saldo_comprobar(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_catcher_saldo_comprobar(p_company uuid, p_saldo_portal numeric, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; s jsonb; v_app numeric; v_val numeric; v_ok boolean; v_dif numeric;
  eur constant text := 'FM999G999G990D00';
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then raise exception 'Solo un administrador o un encargado de la cuenta.' using errcode = '42501'; end if;
  if p_saldo_portal is null then raise exception 'Escribe el saldo que enseña el portal de Catcher.' using errcode = '22023'; end if;
  s := public.conta_catcher_saldo(p_company);
  if not (s->>'existe')::boolean then raise exception '%', s->>'texto' using errcode = 'P0002'; end if;
  v_app := (s->>'saldo')::numeric; v_val := (s->>'saldo_validado')::numeric;
  v_ok := round(v_app * 100) = round(p_saldo_portal * 100);
  v_dif := p_saldo_portal - v_app;
  insert into public.supplier_balance_check (account_id, company_id, provider, portal_amount, app_amount, app_validated_amount, matches, checked_by, checked_by_name)
  values (v_acc, p_company, 'catcher', p_saldo_portal, v_app, v_val, v_ok, auth.uid(), p_quien_nombre);
  return jsonb_build_object('coincide', v_ok, 'portal', p_saldo_portal, 'app', v_app, 'diferencia', v_dif,
    'texto', case when v_ok then 'Coincide: ' || replace(replace(replace(to_char(v_app, eur), ',', '#'), '.', ','), '#', '.') || ' € en el portal y en la 40700001.'
                  else 'No coincide: el portal dice ' || replace(replace(replace(to_char(p_saldo_portal, eur), ',', '#'), '.', ','), '#', '.') || ' € y la 40700001 '
                       || replace(replace(replace(to_char(v_app, eur), ',', '#'), '.', ','), '#', '.') || ' € (el portal tiene '
                       || replace(replace(replace(to_char(abs(v_dif), eur), ',', '#'), '.', ','), '#', '.') || ' € ' || case when v_dif > 0 then 'más' else 'menos' end || ').' end
             || case when round(v_app * 100) <> round(v_val * 100) then ' Hay pagos o recargas propuestos sin validar.' else '' end);
end $$;


--
-- Name: FUNCTION conta_catcher_saldo_comprobar(p_company uuid, p_saldo_portal numeric, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_catcher_saldo_comprobar(p_company uuid, p_saldo_portal numeric, p_quien_nombre text) IS 'E05 · Compara el saldo que alguien ve en el portal de Catcher con el de la 40700001 en la app, lo apunta y dice si coincide (y cuánto no).';


--
-- Name: conta_cerrado_hasta(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cerrado_hasta(p_company uuid, p_ahora timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select ((public.conta_ultimo_dia_cerrado(p_company, p_ahora) + 1)::timestamp at time zone 'Europe/Madrid')
$$;


--
-- Name: FUNCTION conta_cerrado_hasta(p_company uuid, p_ahora timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_cerrado_hasta(p_company uuid, p_ahora timestamp with time zone) IS 'Cierre del día: el instante en que empieza el primer día sin cerrar (medianoche de Madrid). sold_at < esto = venta de un día cerrado.';


--
-- Name: conta_cerrar_dias(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cerrar_dias(p_company uuid, p_ahora timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
  v_hora    time;
  v_hasta   date;
  r         record;
  v_accion  text;
  v_l       uuid;
  v_cerrados int := 0; v_anulados int := 0; v_revisar int := 0; v_consumos int := 0;
  v_importe numeric := 0;
begin
  select c.account_id, coalesce(t.sales_day_close_time, time '02:00')
    into v_account, v_hora
    from public.company c left join public.company_tax_profile t on t.company_id = c.id
   where c.id = p_company;
  if v_account is null then
    raise exception 'Cierre del día: la empresa % no existe.', p_company;
  end if;
  v_hasta := public.conta_ultimo_dia_cerrado(p_company, p_ahora);

  -- C11b: skip locked, como antes: un pedido que en este instante mueve la
  -- plataforma no se pisa; lo coge la pasada de la hora siguiente.
  for r in
    select x.sale_id, x.location_id, x.sales_day, x.order_code, x.total, x.order_status, x.delivery_state, s.account_id, s.source
      from public.conta_por_cerrar(p_company, p_ahora) x
      join public.sale s on s.id = x.sale_id
     where s.status = 'open'
     for update of s skip locked
  loop
    if coalesce(r.source, '') not in ('hubrise', 'lastapp', 'otter') then
      v_accion := 'revisar'; v_revisar := v_revisar + 1;
    elsif coalesce(r.order_status, '') in ('cancelled', 'rejected', 'delivery_failed') then
      update public.sale s
         set status = 'cancelled', unconfirmed_at = now(), cancelled_at = now(),
             cancel_reason = format('Cancelado en la plataforma (%s), anulado al cierre del día (%s)', r.order_status, to_char(v_hora, 'FMHH24:MI')),
             updated_at = now()
       where s.id = r.sale_id;
      v_accion := 'anulado'; v_anulados := v_anulados + 1;
    else
      update public.sale s
         set status = 'closed', closed_at = coalesce(s.closed_at, s.delivered_at, s.handed_to_courier_at, s.ready_at, now()), updated_at = now()
       where s.id = r.sale_id;
      for v_l in select l.id from public.sale_line l
                  where l.sale_id = r.sale_id and coalesce(l.line_type, 'product') = 'product' and l.cost_computed_at is null loop
        perform public.compute_sale_line_cost(v_l);
      end loop;
      if not exists (select 1 from public.stock_movement m where m.source_id = r.sale_id) then
        perform public.generate_sale_consumption(r.sale_id);
        v_consumos := v_consumos + 1;
      end if;
      v_accion := 'cerrado_sin_confirmar'; v_cerrados := v_cerrados + 1; v_importe := v_importe + coalesce(r.total, 0);
    end if;

    insert into public.sales_day_close_log as g
      (account_id, company_id, sale_id, location_id, sales_day, closed_through, close_time, order_code, total, order_status, delivery_state, accion)
    values (r.account_id, p_company, r.sale_id, r.location_id, r.sales_day, v_hasta, v_hora, r.order_code, r.total, r.order_status, r.delivery_state, v_accion)
    on conflict (sale_id) do update
       set accion = excluded.accion, closed_through = excluded.closed_through, close_time = excluded.close_time,
           order_status = excluded.order_status, delivery_state = excluded.delivery_state, closed_at = now()
     where g.accion = 'revisar' and excluded.accion <> 'revisar';
  end loop;

  return jsonb_build_object('company_id', p_company, 'cerrado_hasta', v_hasta, 'hora', to_char(v_hora, 'HH24:MI'),
                            'cerrados', v_cerrados, 'importe', v_importe, 'anulados', v_anulados,
                            'para_revisar', v_revisar, 'consumos_generados', v_consumos);
end
$$;


--
-- Name: FUNCTION conta_cerrar_dias(p_company uuid, p_ahora timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_cerrar_dias(p_company uuid, p_ahora timestamp with time zone) IS 'Cierre del día (C04b; C11b, 23/10): a la hora de cierre de su día, un pedido de plataforma abierto se cierra como vendido (sin volver a consumir si ya consumió) salvo que la plataforma lo tenga cancelled, rejected o delivery_failed (entonces se anula); lo que no es de plataforma se apunta para revisar. Todo queda en sales_day_close_log.';


--
-- Name: conta_cerrar_mes(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cerrar_mes(p_company uuid, p_mes date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_ej public.fiscal_year; v_mes date := date_trunc('month', p_mes)::date; v_primero date; v_id uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.current_user_is_admin_of(v_cuenta) then
    raise exception 'Solo un administrador de la cuenta puede cerrar meses' using errcode = '42501';
  end if;
  select * into v_ej from public.fiscal_year
   where company_id = p_company and v_mes between date_trunc('month', starts_on)::date and ends_on;
  if v_ej.id is null then raise exception 'No hay ejercicio para %', to_char(v_mes, 'MM/YYYY') using errcode = '23514'; end if;
  select min(m)::date into v_primero
    from generate_series(date_trunc('month', v_ej.starts_on), v_ej.ends_on, interval '1 month') m
   where not exists (select 1 from public.fiscal_period_lock l
                      where l.company_id = p_company and l.month = m::date and l.reopened_at is null);
  if v_primero is distinct from v_mes then
    raise exception 'Los meses se cierran en orden: el primero abierto es %', to_char(v_primero, 'MM/YYYY') using errcode = '23514';
  end if;
  insert into public.fiscal_period_lock (account_id, company_id, fiscal_year_id, month, locked_by, locked_by_name)
  values (v_cuenta, p_company, v_ej.id, v_mes, auth.uid(), public.conta_nombre_actor())
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'mes', v_mes);
end $$;


--
-- Name: conta_cert_abrir(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_abrir(p_confirmation uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.tax_certificate_confirmation; c public.tax_certificate; v_motivo text; v_uso uuid; v_material text;
begin
  select * into t from public.tax_certificate_confirmation where id = p_confirmation for update;
  if t.id is null then return jsonb_build_object('ok', false, 'mensaje', 'Esa confirmación no existe. Vuelve a pulsar y confirmar.'); end if;
  select * into c from public.tax_certificate where id = t.certificate_id;
  v_motivo := case
    when t.user_id is distinct from p_user then 'Esa confirmación es de otra persona.'
    when t.used_at is not null then 'Esa confirmación ya se usó. Vuelve a pulsar y confirmar.'
    when t.expires_at <= now() then 'Esa confirmación ha caducado (dura 5 minutos). Vuelve a pulsar y confirmar.'
    when c.status = 'removed' then 'Ese certificado se ha quitado: ya no se puede usar.'
    when c.valid_to <= now() then 'Ese certificado ha caducado: sube uno nuevo.'
    when not public.conta_cert_puede_usar(p_user, c.id) then 'Ya no tienes permiso para presentar con este certificado.'
    when c.storage <> 'vault' then 'Ese certificado está en el almacén con clave externa (KMS), que todavía no está preparado.'
    else null end;
  if v_motivo is not null then
    if c.valid_to <= now() and c.status = 'active' then update public.tax_certificate set status = 'expired' where id = c.id; end if;
    insert into public.tax_certificate_use (certificate_id, owner_account_id, tax_return_id, company_id, user_id, user_name, action, result, message)
    values (c.id, c.owner_account_id, t.tax_return_id, t.company_id, p_user, public.conta_cert_nombre(p_user, c.owner_account_id), t.action, 'denied', v_motivo);
    return jsonb_build_object('ok', false, 'mensaje', v_motivo);
  end if;
  update public.tax_certificate_confirmation set used_at = now() where id = t.id;
  -- Sin terminar hasta que quien lo usa diga cómo fue: si la llamada se cae, queda así.
  insert into public.tax_certificate_use (certificate_id, owner_account_id, tax_return_id, company_id, user_id, user_name, action, confirmation_id, result, message)
  values (c.id, c.owner_account_id, t.tax_return_id, t.company_id, p_user, public.conta_cert_nombre(p_user, c.owner_account_id), t.action, t.id, 'error',
          'Sin terminar: la llamada a Hacienda no ha dicho cómo acabó.')
  returning id into v_uso;
  select decrypted_secret into v_material from vault.decrypted_secrets where id = c.vault_secret_id;
  if v_material is null then
    update public.tax_certificate_use set message = 'El certificado no está en el almacén.' where id = v_uso;
    return jsonb_build_object('ok', false, 'mensaje', 'El certificado no está en el almacén: vuelve a subirlo.');
  end if;
  return jsonb_build_object('ok', true, 'material', v_material, 'uso_id', v_uso, 'certificate_id', c.id);
end $$;


--
-- Name: conta_cert_confirmar(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_confirmar(p_certificate uuid, p_action text, p_tax_return uuid DEFAULT NULL::uuid, p_company uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.tax_certificate; v_id uuid;
begin
  if auth.uid() is null then raise exception 'Tienes que entrar con tu usuario.' using errcode = '42501'; end if;
  select * into c from public.tax_certificate where id = p_certificate;
  if c.id is null then raise exception 'Ese certificado no está.' using errcode = 'P0002'; end if;
  if p_action not in ('test', 'file', 'query', 'receipt_pdf') then raise exception 'Ese uso no existe.' using errcode = '22023'; end if;
  if c.status = 'removed' then raise exception 'Ese certificado se quitó el %: ya no se puede usar.', to_char(c.removed_at at time zone 'Europe/Madrid', 'DD/MM/YYYY') using errcode = '22023'; end if;
  if c.valid_to <= now() then raise exception 'Ese certificado caducó el %: sube uno nuevo.', to_char(c.valid_to at time zone 'Europe/Madrid', 'DD/MM/YYYY') using errcode = '22023'; end if;
  if not public.conta_cert_puede_usar(auth.uid(), c.id) then
    raise exception 'No tienes permiso para presentar con este certificado.' using errcode = '42501';
  end if;
  insert into public.tax_certificate_confirmation (certificate_id, owner_account_id, user_id, action, tax_return_id, company_id, expires_at)
  values (c.id, c.owner_account_id, auth.uid(), p_action, p_tax_return, p_company, now() + interval '5 minutes')
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: conta_cert_cuenta_vault(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_cuenta_vault() RETURNS uuid
    LANGUAGE sql IMMUTABLE
    AS $$ select '51ad1792-6629-4ef7-833a-b57b09a86710'::uuid $$;


--
-- Name: conta_cert_custodia(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_custodia(p_storage text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_storage
    when 'kms' then 'Queda cifrado con una clave que solo puede usar el servidor que presenta. Nadie puede verlo ni descargarlo, tampoco en Sumied. Cada uso queda apuntado.'
    else 'Queda cifrado y solo lo usa el servidor de Sumied para presentar, cuando una persona con permiso lo confirma. Nadie puede descargarlo desde la aplicación, y cada uso queda apuntado.'
  end
$$;


--
-- Name: FUNCTION conta_cert_custodia(p_storage text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_cert_custodia(p_storage text) IS 'I01a. El texto de custodia según el almacén. Con el Vault no dice «nadie puede verlo, tampoco en Sumied»: quien tenga SQL de servicio podría leerlo (informe §2.2).';


--
-- Name: conta_cert_es_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_es_admin(p_user uuid, p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.user_profiles
                  where user_id = p_user and account_id = p_account and role = 'admin' and active)
$$;


--
-- Name: conta_cert_guardar(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_guardar(p_user uuid, p_account uuid, p_ficha jsonb, p_material text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := gen_random_uuid(); v_secreto uuid; v_hasta timestamptz; v_desde timestamptz; v_huella text; v_nombre text;
begin
  if p_user is null or p_account is null then raise exception 'Falta quién lo sube o la cuenta.' using errcode = '22023'; end if;
  if not public.conta_cert_es_admin(p_user, p_account) then
    raise exception 'Solo un administrador de la cuenta puede subir un certificado.' using errcode = '42501';
  end if;
  -- Con el Vault, solo Foodint. El KMS no está: no hay otro almacén donde guardarlo.
  if p_account <> public.conta_cert_cuenta_vault() then
    raise exception 'Todavía no se pueden guardar certificados en esta cuenta: falta el almacén con clave externa (KMS), y hasta que esté solo se admite la cuenta de Foodint. No se ha guardado nada.'
      using errcode = '42501';
  end if;
  if p_material is null or length(p_material) < 100 or p_material !~ 'BEGIN CERTIFICATE' or p_material !~ 'PRIVATE KEY' then
    raise exception 'Falta el certificado o su clave.' using errcode = '22023';
  end if;
  v_desde := (p_ficha->>'valid_from')::timestamptz;
  v_hasta := (p_ficha->>'valid_to')::timestamptz;
  v_huella := lower(p_ficha->>'fingerprint_sha256');
  if v_hasta is null or v_hasta <= now() then
    raise exception 'El certificado caducó el %. No se guarda.', to_char(v_hasta at time zone 'Europe/Madrid', 'DD/MM/YYYY') using errcode = '22023';
  end if;
  if exists (select 1 from public.tax_certificate where fingerprint_sha256 = v_huella and status <> 'removed') then
    raise exception 'Ese certificado ya está guardado.' using errcode = '23505';
  end if;
  v_nombre := public.conta_cert_nombre(p_user, p_account);
  v_secreto := vault.create_secret(p_material, 'tax_certificate:' || v_id::text, 'I01a · certificado de Hacienda (cert y clave en PEM)');
  insert into public.tax_certificate (id, owner_account_id, subject_name, subject_tax_id_hash, subject_tax_id_tail, issuer, serial,
                                      valid_from, valid_to, fingerprint_sha256, kind, storage, vault_secret_id, uploaded_by, uploaded_by_name)
  values (v_id, p_account, p_ficha->>'subject_name', lower(p_ficha->>'subject_tax_id_hash'), upper(p_ficha->>'subject_tax_id_tail'),
          p_ficha->>'issuer', p_ficha->>'serial', v_desde, v_hasta, v_huella, p_ficha->>'kind', 'vault', v_secreto, p_user, v_nombre);
  insert into public.tax_certificate_grant (certificate_id, user_id, permission, granted_by) values (v_id, p_user, 'file', p_user);
  insert into public.tax_certificate_use (certificate_id, owner_account_id, user_id, user_name, action, result, message)
  values (v_id, p_account, p_user, v_nombre, 'upload', 'ok', 'Subido y comprobado: la clave corresponde al certificado y está en vigor.');
  return jsonb_build_object('id', v_id, 'custodia', public.conta_cert_custodia('vault'));
end $$;


--
-- Name: FUNCTION conta_cert_guardar(p_user uuid, p_account uuid, p_ficha jsonb, p_material text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_cert_guardar(p_user uuid, p_account uuid, p_ficha jsonb, p_material text) IS 'I01a. Guarda un certificado ya validado (conta-certificado). Solo un administrador de la cuenta; con el Vault, solo la cuenta de Foodint. Solo service_role.';


--
-- Name: conta_cert_nombre(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_nombre(p_user uuid, p_account uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select nullif(trim(display_name), '') from public.user_profiles
                    where user_id = p_user order by (account_id = p_account) desc, active desc limit 1), 'Sumied')
$$;


--
-- Name: conta_cert_permiso(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_permiso(p_certificate uuid, p_user uuid, p_permission text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.tax_certificate;
begin
  select * into c from public.tax_certificate where id = p_certificate;
  if c.id is null then raise exception 'Ese certificado no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(c.owner_account_id) then
    raise exception 'Solo un administrador de la cuenta puede dar o quitar permisos sobre un certificado.' using errcode = '42501';
  end if;
  if p_permission is not null and p_permission not in ('file', 'view') then raise exception 'Ese permiso no existe.' using errcode = '22023'; end if;
  if p_permission is not null and not exists (select 1 from public.user_profiles where user_id = p_user and account_id = c.owner_account_id and active) then
    raise exception 'Esa persona no es de esta cuenta.' using errcode = '22023';
  end if;
  update public.tax_certificate_grant set revoked_at = now() where certificate_id = c.id and user_id = p_user and revoked_at is null;
  if p_permission is null then return 'Permiso retirado.'; end if;
  insert into public.tax_certificate_grant (certificate_id, user_id, permission, granted_by) values (c.id, p_user, p_permission, auth.uid());
  return case p_permission when 'file' then 'Ahora puede presentar con este certificado.' else 'Ahora puede verlo, pero no presentar.' end;
end $$;


--
-- Name: conta_cert_puede_usar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_puede_usar(p_user uuid, p_certificate uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.tax_certificate c
                  where c.id = p_certificate
                    and (public.conta_cert_es_admin(p_user, c.owner_account_id)
                         or exists (select 1 from public.tax_certificate_grant g
                                     where g.certificate_id = c.id and g.user_id = p_user and g.permission = 'file' and g.revoked_at is null)))
$$;


--
-- Name: conta_cert_quitar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_quitar(p_certificate uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.tax_certificate; v_nombre text;
begin
  select * into c from public.tax_certificate where id = p_certificate for update;
  if c.id is null then raise exception 'Ese certificado no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(c.owner_account_id) then
    raise exception 'Solo un administrador de la cuenta puede quitar un certificado.' using errcode = '42501';
  end if;
  if c.status = 'removed' then return 'Ya estaba quitado.'; end if;
  v_nombre := public.conta_cert_nombre(auth.uid(), c.owner_account_id);
  if c.vault_secret_id is not null then delete from vault.secrets where id = c.vault_secret_id; end if;
  update public.tax_certificate set status = 'removed', vault_secret_id = null, ciphertext = null, wrapped_key = null, kms_key_ref = null,
         removed_at = now(), removed_by = auth.uid(), removed_by_name = v_nombre
   where id = c.id;
  update public.tax_certificate_confirmation set used_at = now() where certificate_id = c.id and used_at is null;
  update public.tax_certificate_grant set revoked_at = now() where certificate_id = c.id and revoked_at is null;
  insert into public.tax_certificate_use (certificate_id, owner_account_id, user_id, user_name, action, result, message)
  values (c.id, c.owner_account_id, auth.uid(), v_nombre, 'remove', 'ok', 'Quitado: borrado del almacén. Nadie puede usarlo desde ahora.');
  return 'Quitado. Se ha borrado del almacén y nadie puede usarlo desde ahora; el registro de usos se queda.';
end $$;


--
-- Name: conta_cert_uso_terminar(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cert_uso_terminar(p_use uuid, p_result text, p_message text, p_aeat_ref_masked text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare u public.tax_certificate_use;
begin
  if p_result not in ('ok', 'error') then raise exception 'Resultado no válido.' using errcode = '22023'; end if;
  if p_message is null or btrim(p_message) = '' then raise exception 'Falta cómo acabó, en palabras.' using errcode = '22023'; end if;
  update public.tax_certificate_use set result = p_result, message = btrim(p_message), aeat_ref_masked = p_aeat_ref_masked
   where id = p_use and message = 'Sin terminar: la llamada a Hacienda no ha dicho cómo acabó.'
  returning * into u;
  if u.id is null then raise exception 'Ese uso no existe o ya está cerrado.' using errcode = 'P0002'; end if;
  if u.action = 'test' then
    update public.tax_certificate set last_test_at = now(), last_test_result = p_result, last_test_message = btrim(p_message) where id = u.certificate_id;
  end if;
end $$;


--
-- Name: conta_cierre_cerrar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_cerrar(p_fiscal_year uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_y public.fiscal_year; v_c public.fiscal_year_closing; v_quien text := public.conta_nombre_actor(); v_falta text;
begin
  select * into v_y from public.fiscal_year where id = p_fiscal_year for update;
  if v_y.id is null then raise exception 'Ese ejercicio no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(v_y.account_id) then raise exception 'Solo un administrador cierra un ejercicio.' using errcode = '42501'; end if;
  select * into v_c from public.fiscal_year_closing where fiscal_year_id = p_fiscal_year for update;
  if v_c.fiscal_year_id is null then raise exception 'Primero hay que preparar el cierre (regularización, cierre y apertura).' using errcode = '23514'; end if;
  select string_agg(q, ', ') into v_falta from (
    select 'regularización' q where not exists (select 1 from public.journal_entry where id = v_c.regularization_entry_id and status = 'validado')
    union all select 'cierre' where not exists (select 1 from public.journal_entry where id = v_c.closing_entry_id and status = 'validado')
    union all select 'apertura' where not exists (select 1 from public.journal_entry where id = v_c.opening_entry_id and status = 'validado')) x;
  if v_falta is not null then raise exception 'Faltan por validar: %.', v_falta using errcode = '23514'; end if;
  if exists (select 1 from public.journal_entry where fiscal_year_id = p_fiscal_year and status in ('propuesto', 'borrador')) then
    raise exception 'Quedan asientos propuestos o en borrador en el ejercicio %: valídalos o descártalos antes de cerrar.', v_y.code using errcode = '23514';
  end if;
  update public.fiscal_year set status = 'closed', closed_at = now(), closed_by = auth.uid() where id = p_fiscal_year;
  update public.fiscal_year_closing set status = 'cerrado', closed_at = now(), closed_by = auth.uid(), closed_by_name = v_quien, updated_at = now() where fiscal_year_id = p_fiscal_year;
  return jsonb_build_object('ejercicio', v_y.code, 'estado', 'cerrado', 'quien', v_quien);
end $$;


--
-- Name: conta_cierre_del_dia_todas(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.conta_cierre_del_dia_todas()
    LANGUAGE plpgsql
    AS $$
declare
  r        record;
  v_p      jsonb;
  v_fallos text[] := '{}';
begin
  for r in select c.id from public.company c order by c.id loop
    begin
      perform public.conta_cerrar_dias(r.id, now());
    exception when others then
      v_fallos := v_fallos || format('%s: %s (%s)', r.id, sqlerrm, sqlstate);
    end;
    commit;
    -- Después de cerrar: lo que ya está cerrado se propone. Un día que falla
    -- se apunta en sales_day_proposal_log y no frena a los demás.
    begin
      v_p := public.conta_proponer_dias(r.id, now());
      if (v_p->>'fallos')::int > 0 then
        v_fallos := v_fallos || format('%s: proponer falló en %s día(s): %s', r.id, v_p->>'fallos', v_p->>'errores');
      end if;
    exception when others then
      v_fallos := v_fallos || format('%s: proponer: %s (%s)', r.id, sqlerrm, sqlstate);
    end;
    commit;
  end loop;
  if cardinality(v_fallos) > 0 then
    raise exception 'Cierre del día: falló en % paso(s): %', cardinality(v_fallos), array_to_string(v_fallos, ' · ');
  end if;
end
$$;


--
-- Name: PROCEDURE conta_cierre_del_dia_todas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON PROCEDURE public.conta_cierre_del_dia_todas() IS 'Cierre del día: conta_cerrar_dias de cada empresa, confirmando una a una. Lo llama el cron cada hora; si alguna falla, termina con error.';


--
-- Name: conta_cierre_enlazar(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_enlazar(p_fiscal_year uuid, p_regularizacion uuid, p_cierre uuid, p_apertura uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_y public.fiscal_year; v_quien text := public.conta_nombre_actor();
begin
  select * into v_y from public.fiscal_year where id = p_fiscal_year;
  if v_y.id is null then raise exception 'Ese ejercicio no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_y.account_id) then raise exception 'Solo un administrador o un encargado prepara el cierre.' using errcode = '42501'; end if;
  if v_y.status <> 'open' then raise exception 'El ejercicio % ya está cerrado.', v_y.code using errcode = '23514'; end if;
  if v_y.origin = 'migrated' then raise exception 'El ejercicio % es traído: se enseña tal cual, no se recalcula su cierre.', v_y.code using errcode = '23514'; end if;
  if exists (select 1 from public.journal_entry e where e.id in (p_regularizacion, p_cierre) and (e.company_id <> v_y.company_id or e.fiscal_year_id <> v_y.id or e.source_type <> 'closing')) then
    raise exception 'La regularización y el cierre son asientos de cierre de ese ejercicio.' using errcode = '23514';
  end if;
  if p_apertura is not null and exists (select 1 from public.journal_entry e where e.id = p_apertura and (e.company_id <> v_y.company_id or e.source_type <> 'opening')) then
    raise exception 'La apertura es un asiento de apertura de la misma empresa.' using errcode = '23514';
  end if;
  insert into public.fiscal_year_closing (fiscal_year_id, account_id, company_id, status, regularization_entry_id, closing_entry_id, opening_entry_id, prepared_at, prepared_by_name)
  values (v_y.id, v_y.account_id, v_y.company_id, 'preparado', p_regularizacion, p_cierre, p_apertura, now(), v_quien)
  on conflict (fiscal_year_id) do update set status = 'preparado', regularization_entry_id = excluded.regularization_entry_id,
    closing_entry_id = excluded.closing_entry_id, opening_entry_id = excluded.opening_entry_id, prepared_at = now(), prepared_by_name = v_quien, updated_at = now();
  return jsonb_build_object('ejercicio', v_y.code, 'estado', 'preparado', 'quien', v_quien);
end $$;


--
-- Name: conta_cierre_espera(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_espera(p_summary uuid, p_motivo text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_d public.sales_day_summary; v_estado text;
begin
  v_d := public._conta_cierre_de(p_summary);
  if v_d.id is null or not public.belongs_to_account(v_d.account_id) then raise exception 'Ese cierre no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_d.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta deja un cierre en espera.' using errcode = '42501';
  end if;
  select status into v_estado from public.journal_entry where id = v_d.entry_id;
  if v_estado = 'validado' then raise exception 'Este cierre ya está validado.' using errcode = '23514'; end if;
  if btrim(coalesce(p_motivo, '')) = '' then
    delete from public.conta_cierre_espera where company_id = v_d.company_id and location_id = v_d.location_id and sales_day = v_d.sales_day and unit_key = v_d.unit_key and not automatica;
    return jsonb_build_object('id', p_summary, 'en_espera', false);
  end if;
  insert into public.conta_cierre_espera (account_id, company_id, location_id, sales_day, unit_key, motivo, automatica, created_by_name)
  values (v_d.account_id, v_d.company_id, v_d.location_id, v_d.sales_day, v_d.unit_key, btrim(p_motivo), false, coalesce(p_quien_nombre, public.conta_nombre_actor()))
  on conflict (company_id, location_id, sales_day, unit_key) do update set motivo = excluded.motivo, automatica = false, created_by_name = excluded.created_by_name;
  return jsonb_build_object('id', p_summary, 'en_espera', true, 'motivo', btrim(p_motivo));
end $$;


--
-- Name: conta_cierre_factura_prevista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_factura_prevista(p_entry uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e public.journal_entry; v_d public.sales_day_summary; v_code text; v_dig int; v_ini int; v_anual boolean; v_anio int; v_ult int; v_num int;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null or not (public.belongs_to_account(v_e.account_id) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  select * into v_d from public.sales_day_summary where entry_id = p_entry and company_id = v_e.company_id and unit_key is not null and channel_id is not null;
  if v_d.id is null then raise exception 'Ese asiento no es el de un cierre del día de un canal: no lleva factura resumen.' using errcode = '22023'; end if;
  v_code := public._conta_cierre_serie(v_e.company_id, v_d.channel_id);
  select digits, starts_at, reset_yearly into v_dig, v_ini, v_anual from public.invoice_series where company_id = v_e.company_id and code = v_code;
  v_dig := coalesce(v_dig, 5); v_ini := coalesce(v_ini, 1); v_anual := coalesce(v_anual, true);
  v_anio := extract(year from v_d.sales_day)::int;
  select last_number into v_ult from public.customer_invoice_counter
   where company_id = v_e.company_id and series_code = v_code and fiscal_year = case when v_anual then v_anio else 0 end;
  v_num := case when v_ult is null then v_ini else v_ult + 1 end;
  return jsonb_build_object('serie', v_code, 'anio', v_anio, 'numero', v_num,
    'texto', v_code || '-' || case when v_anual then v_anio || '/' else '' end || lpad(v_num::text, v_dig, '0'));
end $$;


--
-- Name: conta_cierre_guardar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_guardar(p_summary uuid, p_cambios jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_d public.sales_day_summary; v_c jsonb; v_s public.sale; v_a public.conta_cierre_ajuste; v_accion text; v_dia_pedido date; v_unidad text;
  v_dias date[] := '{}'; v_dia date; v_r jsonb; v_res jsonb := '[]'::jsonb; v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
  v_antes numeric; v_n int := 0; v_importe numeric; v_destino date; v_estado text; v_codigo text;
begin
  v_d := public._conta_cierre_de(p_summary);
  if v_d.id is null or not public.belongs_to_account(v_d.account_id) then raise exception 'Ese cierre no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_d.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta cambia un cierre.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_cambios) <> 'array' or jsonb_array_length(p_cambios) = 0 then raise exception 'No hay cambios que guardar.' using errcode = '22023'; end if;
  select e.status into v_estado from public.journal_entry e where e.id = v_d.entry_id;
  if v_estado = 'validado' then
    raise exception 'Este cierre ya está validado: no se cambia. Se corrige desde su factura, con «Corregir».' using errcode = '23514';
  end if;
  v_antes := v_d.total;
  v_dias := array[v_d.sales_day];

  for v_c in select * from jsonb_array_elements(p_cambios) loop
    v_accion := v_c->>'accion';
    select * into v_s from public.sale where id = nullif(v_c->>'pedido', '')::uuid and account_id = v_d.account_id and location_id = v_d.location_id;
    if v_s.id is null then raise exception 'Ese pedido no es de este local.' using errcode = '22023'; end if;
    v_codigo := coalesce(v_s.platform_order_code, v_s.pos_short_code, v_s.external_ref, left(v_s.id::text, 8));
    v_dia_pedido := (v_s.sold_at at time zone 'Europe/Madrid')::date;
    v_unidad := public.conta_unidad_ventas(v_d.company_id, v_s.channel_id, v_s.brand_id);
    select * into v_a from public.conta_cierre_ajuste where company_id = v_d.company_id and sale_id = v_s.id for update;
    if v_unidad is distinct from v_d.unit_key
       or not (v_dia_pedido = v_d.sales_day or (v_a.id is not null and v_a.dia_destino = v_d.sales_day)) then
      raise exception 'El pedido % no es de este cierre.', v_codigo using errcode = '22023';
    end if;
    if v_a.id is not null and v_a.dia_destino is not null then v_dias := v_dias || v_a.dia_destino; end if;
    v_dias := v_dias || v_dia_pedido;

    if v_accion = 'deshacer' then
      delete from public.conta_cierre_ajuste where id = v_a.id;
    elsif v_accion = 'quitar' then
      if btrim(coalesce(v_c->>'motivo', '')) = '' then raise exception 'Para quitar el pedido % hay que decir por qué.', v_codigo using errcode = '22023'; end if;
      insert into public.conta_cierre_ajuste (account_id, company_id, sale_id, location_id, sales_day, unit_key, quitado, importe_antes, motivo, created_by, created_by_name)
      values (v_d.account_id, v_d.company_id, v_s.id, v_d.location_id, v_dia_pedido, v_unidad, true, v_s.total, btrim(v_c->>'motivo'), auth.uid(), v_quien)
      on conflict (company_id, sale_id) do update set quitado = true, dia_destino = null, importe = null, motivo = excluded.motivo,
        created_by = excluded.created_by, created_by_name = excluded.created_by_name, updated_at = now();
    elsif v_accion = 'mover' then
      v_destino := nullif(v_c->>'dia', '')::date;
      if v_destino is null then raise exception 'Falta el día al que pasar el pedido %.', v_codigo using errcode = '22023'; end if;
      if v_destino > public.conta_ultimo_dia_cerrado(v_d.company_id, now()) then
        raise exception 'El % aún no está cerrado: un pedido solo se pasa a un día ya cerrado.', to_char(v_destino, 'DD/MM/YYYY') using errcode = '22023';
      end if;
      if public.conta_mes_cerrado(v_d.company_id, v_destino) then
        raise exception 'El mes del % está cerrado: no se le pasan pedidos.', to_char(v_destino, 'DD/MM/YYYY') using errcode = '23514';
      end if;
      if v_destino = v_dia_pedido then
        -- Volver a su día es deshacer el paso (lo demás se queda).
        update public.conta_cierre_ajuste set dia_destino = null, updated_at = now() where id = v_a.id;
        delete from public.conta_cierre_ajuste where id = v_a.id and not quitado and dia_destino is null and importe is null;
      else
        insert into public.conta_cierre_ajuste (account_id, company_id, sale_id, location_id, sales_day, unit_key, dia_destino, importe_antes, motivo, created_by, created_by_name)
        values (v_d.account_id, v_d.company_id, v_s.id, v_d.location_id, v_dia_pedido, v_unidad, v_destino, v_s.total, nullif(btrim(v_c->>'motivo'), ''), auth.uid(), v_quien)
        on conflict (company_id, sale_id) do update set quitado = false, dia_destino = excluded.dia_destino,
          motivo = coalesce(excluded.motivo, public.conta_cierre_ajuste.motivo), created_by_name = excluded.created_by_name, updated_at = now();
      end if;
      v_dias := v_dias || v_destino;
    elsif v_accion = 'importe' then
      v_importe := round((v_c->>'importe')::numeric, 2);
      if v_importe is null or v_importe <= 0 then
        raise exception 'El importe del pedido % tiene que ser mayor que cero (para que no cuente, quítalo).', v_codigo using errcode = '22023';
      end if;
      if v_importe = v_s.total then
        update public.conta_cierre_ajuste set importe = null, updated_at = now() where id = v_a.id;
        delete from public.conta_cierre_ajuste where id = v_a.id and not quitado and dia_destino is null and importe is null;
      else
        insert into public.conta_cierre_ajuste (account_id, company_id, sale_id, location_id, sales_day, unit_key, importe, importe_antes, motivo, created_by, created_by_name)
        values (v_d.account_id, v_d.company_id, v_s.id, v_d.location_id, v_dia_pedido, v_unidad, v_importe, v_s.total, nullif(btrim(v_c->>'motivo'), ''), auth.uid(), v_quien)
        on conflict (company_id, sale_id) do update set quitado = false, importe = excluded.importe,
          motivo = coalesce(excluded.motivo, public.conta_cierre_ajuste.motivo), created_by_name = excluded.created_by_name, updated_at = now();
      end if;
    else
      raise exception 'Qué se hace con el pedido %: quitar, mover, importe o deshacer.', v_codigo using errcode = '22023';
    end if;
    v_n := v_n + 1;
  end loop;

  -- Rehacer cada día tocado (este y aquellos de donde o adonde se ha pasado algo).
  for v_dia in select distinct x from unnest(v_dias) x order by 1 loop
    v_r := public._conta_cierre_rehacer(v_d.company_id, v_d.location_id, v_dia, v_d.unit_key, v_quien);
    v_res := v_res || jsonb_build_array(v_r);
  end loop;
  select * into v_d from public.sales_day_summary where id = p_summary;
  return jsonb_build_object('id', p_summary, 'cambios', v_n, 'antes', v_antes, 'total', v_d.total, 'asiento', v_d.entry_id, 'dias', v_res);
end $$;


--
-- Name: conta_cierre_pedidos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_pedidos(p_summary uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_d public.sales_day_summary; v_r jsonb;
begin
  v_d := public._conta_cierre_de(p_summary);
  if v_d.id is null or not public.belongs_to_account(v_d.account_id) then raise exception 'Ese cierre no está.' using errcode = 'P0002'; end if;
  with dentro as (
    -- Lo de este cierre hoy (ya con los cambios). Solo marcas propias: las
    -- cedidas no son ventas de la empresa y no salen.
    select p.id, p.codigo, p.marca_id, p.propia, p.estado, p.total, p.base, p.cuota
      from public.conta_pedidos_del_dia(v_d.company_id, v_d.location_id, v_d.sales_day) p
     where p.propia and public.conta_unidad_ventas(v_d.company_id, p.canal_id, p.marca_id) = v_d.unit_key
  ), fuera as (
    -- Lo que era de este día y se ha quitado o pasado a otro.
    select a.sale_id as id from public.conta_cierre_ajuste a
     where a.company_id = v_d.company_id and a.location_id = v_d.location_id and a.sales_day = v_d.sales_day and a.unit_key = v_d.unit_key
       and (a.quitado or a.dia_destino is not null)
  ), todos as (
    select id from dentro union select id from fuera
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'codigo', coalesce(s.platform_order_code, s.pos_short_code, s.external_ref, left(s.id::text, 8)),
           'hora', to_char(s.sold_at at time zone 'Europe/Madrid', 'HH24:MI'), 'dia', (s.sold_at at time zone 'Europe/Madrid')::date,
           'marca', b.name, 'propia', coalesce(b.ownership_type, 'own') = 'own',
           'estado', coalesce(dn.estado, case when s.status = 'cancelled' and s.unconfirmed_at is not null then 'unconfirmed' else s.status end),
           'total', coalesce(dn.total, s.total), 'total_pedido', s.total,
           'cuenta', dn.id is not null and dn.propia and dn.estado = 'closed',
           'ajuste', case when a.id is null then null else jsonb_build_object('quitado', a.quitado, 'dia', a.dia_destino, 'importe', a.importe,
                     'importe_antes', a.importe_antes, 'motivo', a.motivo, 'quien', a.created_by_name, 'cuando', a.updated_at,
                     'de_otro_dia', a.dia_destino = v_d.sales_day) end)
         order by s.sold_at, s.id), '[]'::jsonb) into v_r
    from todos t
    join public.sale s on s.id = t.id and s.account_id = v_d.account_id
    left join dentro dn on dn.id = s.id
    left join public.brand b on b.id = s.brand_id and b.account_id = s.account_id
    left join public.conta_cierre_ajuste a on a.company_id = v_d.company_id and a.sale_id = s.id;
  return v_r;
end $$;


--
-- Name: conta_cierre_reabrir(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_reabrir(p_fiscal_year uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_y public.fiscal_year; v_c public.fiscal_year_closing; v_quien text := public.conta_nombre_actor(); v_anulados jsonb := '[]';
begin
  if p_motivo is null or length(trim(p_motivo)) = 0 then raise exception 'Para reabrir un ejercicio hay que decir por qué.' using errcode = '23514'; end if;
  select * into v_y from public.fiscal_year where id = p_fiscal_year for update;
  if v_y.id is null then raise exception 'Ese ejercicio no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(v_y.account_id) then raise exception 'Solo un administrador reabre un ejercicio.' using errcode = '42501'; end if;
  if v_y.origin = 'migrated' then raise exception 'El ejercicio % es traído: no se reabre en Folvy.', v_y.code using errcode = '23514'; end if;
  select * into v_c from public.fiscal_year_closing where fiscal_year_id = p_fiscal_year for update;
  if v_c.fiscal_year_id is null or v_c.status <> 'cerrado' then raise exception 'El ejercicio % no está cerrado por Folvy.', v_y.code using errcode = '23514'; end if;
  -- El ejercicio vuelve a abrirse primero: el contraasiento del cierre va en él.
  update public.fiscal_year set status = 'open', closed_at = null, closed_by = null where id = p_fiscal_year;
  if v_c.opening_entry_id is not null and exists (select 1 from public.journal_entry where id = v_c.opening_entry_id and status = 'validado') then
    v_anulados := v_anulados || jsonb_build_array(public.journal_entry_anular(v_c.opening_entry_id, 'Reapertura del ejercicio ' || v_y.code || ': ' || trim(p_motivo), null, v_quien));
  end if;
  if v_c.closing_entry_id is not null and exists (select 1 from public.journal_entry where id = v_c.closing_entry_id and status = 'validado') then
    v_anulados := v_anulados || jsonb_build_array(public.journal_entry_anular(v_c.closing_entry_id, 'Reapertura del ejercicio ' || v_y.code || ': ' || trim(p_motivo), v_y.ends_on, v_quien));
  end if;
  update public.fiscal_year_closing set status = 'abierto', closing_entry_id = null, opening_entry_id = null, closed_at = null, closed_by = null, closed_by_name = null,
         reopenings = reopenings || jsonb_build_array(jsonb_build_object('fecha', now(), 'quien', v_quien, 'motivo', trim(p_motivo), 'anulados', v_anulados)),
         updated_at = now()
   where fiscal_year_id = p_fiscal_year;
  return jsonb_build_object('ejercicio', v_y.code, 'estado', 'abierto', 'anulados', v_anulados, 'quien', v_quien);
end $$;


--
-- Name: conta_cierre_validar(uuid, integer, text, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierre_validar(p_entry uuid, p_numero integer, p_factura text, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry; v_d public.sales_day_summary; v_prev jsonb; v_val jsonb; v_code text; v_id uuid; v_num int; v_anio int; v_anual boolean;
  v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor()); v_espera text; v_canal text; v_local text; v_cta uuid; v_l record; v_pos int := 0;
  v_base numeric := 0; v_iva numeric := 0; v_prev_hash text; v_hash text; v_emisor text;
begin
  select * into v_e from public.journal_entry where id = p_entry for update;
  if v_e.id is null or not public.belongs_to_account(v_e.account_id) then raise exception 'Ese asiento no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_e.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta valida cierres.' using errcode = '42501';
  end if;
  select * into v_d from public.sales_day_summary where entry_id = p_entry and company_id = v_e.company_id and unit_key is not null and channel_id is not null;
  if v_d.id is null then raise exception 'Ese asiento no es el de un cierre del día de un canal.' using errcode = '22023'; end if;
  select motivo into v_espera from public.conta_cierre_espera
   where company_id = v_d.company_id and location_id = v_d.location_id and sales_day = v_d.sales_day and unit_key = v_d.unit_key;
  if v_espera is not null then raise exception 'Está en espera: %. Quítalo de espera para validarlo.', rtrim(v_espera, '.') using errcode = '23514'; end if;
  if exists (select 1 from public.customer_invoice where entry_id = p_entry) then raise exception 'Este cierre ya tiene su factura.' using errcode = '23505'; end if;

  -- La serie del canal: la suya, o se crea ahora con el código que la pantalla ya enseñó.
  v_code := public._conta_cierre_serie(v_e.company_id, v_d.channel_id);
  select ch.name into v_canal from public.sales_channel ch where ch.id = v_d.channel_id and ch.account_id = v_e.account_id;
  select l.name into v_local from public.locations l where l.id = v_d.location_id and l.account_id = v_e.account_id;
  insert into public.invoice_series (account_id, company_id, code, name, doc_type, digits, reset_yearly, starts_at, is_default, is_active, channel_id)
  values (v_e.account_id, v_e.company_id, v_code, 'Cierres del día · ' || coalesce(v_canal, 'canal'), 'simplified', 5, true, 1, false, true, v_d.channel_id)
  on conflict do nothing;
  v_prev := public.conta_cierre_factura_prevista(p_entry);
  if p_factura is null or v_prev->>'texto' <> p_factura then
    raise exception 'El PDF se hizo con la factura % y ahora le toca la % (se ha validado otro asiento de la serie a la vez): no se valida. Vuelve a pulsar.',
      coalesce(p_factura, '(ninguna)'), v_prev->>'texto' using errcode = '40001';
  end if;

  -- El asiento y su PDF (con todas sus reglas).
  v_val := public.journal_entry_validar_con_documento(p_entry, p_numero, p_ruta, p_nombre, p_sha256, p_bytes, v_quien);

  -- El número de la factura: el contador sin huecos de su serie y año.
  select reset_yearly into v_anual from public.invoice_series where company_id = v_e.company_id and code = v_code;
  v_anio := (v_prev->>'anio')::int;
  insert into public.customer_invoice_counter (company_id, account_id, series_code, fiscal_year, last_number)
  values (v_e.company_id, v_e.account_id, v_code, case when coalesce(v_anual, true) then v_anio else 0 end, (v_prev->>'numero')::int)
  on conflict (company_id, series_code, fiscal_year) do update set last_number = public.customer_invoice_counter.last_number + 1
  returning last_number into v_num;
  if v_num <> (v_prev->>'numero')::int then
    raise exception 'La factura del PDF es la % y le toca otro número (se ha validado otro asiento de la serie a la vez): no se valida. Vuelve a pulsar.', p_factura using errcode = '40001';
  end if;

  -- La factura resumen: una línea por tipo de IVA, con la base y la cuota del
  -- asiento (lo que dice el libro), a la cuenta de ventas principal del asiento.
  select l.company_account_id into v_cta from public.journal_line l join public.company_account a on a.id = l.company_account_id
   where l.entry_id = p_entry and a.code like '70%' order by l.credit desc, l.position limit 1;
  insert into public.customer_invoice (account_id, company_id, status, doc_type, origin, series_code, issue_date, due_date, customer, location_id, notes,
                                       created_by, created_by_name)
  values (v_e.account_id, v_e.company_id, 'borrador', 'factura', 'cierre_dia', v_code, v_d.sales_day, v_d.sales_day,
          jsonb_build_object('nombre', 'Ventas del día · ' || coalesce(v_canal, 'canal')), v_d.location_id,
          format('Factura resumen de las ventas del %s en %s (%s): %s tiques.', to_char(v_d.sales_day, 'DD/MM/YYYY'), coalesce(v_canal, 'el canal'), coalesce(v_local, 'el local'), v_d.tickets_count),
          auth.uid(), v_quien)
  returning id into v_id;
  for v_l in
    select l.tax_rate_id, t.rate, sum(case when l.credit > 0 then l.tax_base else -l.tax_base end) as base, sum(l.credit - l.debit) as cuota
      from public.journal_line l join public.tax_rate t on t.id = l.tax_rate_id
     where l.entry_id = p_entry and l.vat_book = 'issued' and l.tax_rate_id is not null
     group by 1, 2 order by 2 desc
  loop
    v_pos := v_pos + 1;
    insert into public.customer_invoice_line (account_id, company_id, invoice_id, position, concept, quantity, unit_price, discount_pct, tax_rate_id, tax_pct, revenue_account_id, amount)
    values (v_e.account_id, v_e.company_id, v_id, v_pos, format('Ventas del día al %s %%', to_char(v_l.rate, 'FM990D##')), 1, v_l.base, 0, v_l.tax_rate_id, v_l.rate, v_cta, v_l.base);
    v_base := v_base + v_l.base; v_iva := v_iva + v_l.cuota;
  end loop;
  if v_pos = 0 or v_cta is null then raise exception 'Este cierre no lleva IVA o cuenta de ventas: no se puede hacer su factura resumen.' using errcode = '23514'; end if;

  select hash into v_prev_hash from public.customer_invoice where company_id = v_e.company_id and status <> 'borrador' and hash is not null order by issued_at desc, id desc limit 1;
  select tax_id into v_emisor from public.company where id = v_e.company_id;
  v_hash := encode(sha256(convert_to(concat_ws('|', v_emisor, p_factura, v_d.sales_day::text, (v_base + v_iva)::text, coalesce(v_prev_hash, '')), 'UTF8')), 'hex');
  update public.customer_invoice set status = 'emitida', fiscal_year = v_anio, number = v_num, number_text = p_factura,
         base = v_base, tax = v_iva, total = v_base + v_iva, entry_id = p_entry, pdf_path = p_ruta, pdf_sha256 = p_sha256, pdf_bytes = p_bytes,
         prev_hash = v_prev_hash, hash = v_hash, issued_at = now(), issued_by_name = v_quien
   where id = v_id;
  -- El libro de expedidas lleva el número de la factura resumen.
  update public.vat_book_entry set number = p_factura, updated_at = now() where entry_id = p_entry and book = 'issued';
  perform public._conta_venta_evento(v_id, 'emitida',
    format('Factura resumen del cierre del %s (%s · %s), con el asiento nº %s y su PDF. Entra en el traspaso del mes.',
           to_char(v_d.sales_day, 'DD/MM/YYYY'), coalesce(v_canal, 'canal'), coalesce(v_local, 'local'), v_val->>'numero'),
    jsonb_build_object('asiento', p_entry, 'numero_asiento', v_val->'numero', 'cierre', v_d.id), v_quien);
  return jsonb_build_object('id', p_entry, 'serie', v_val->'serie', 'numero', v_val->'numero', 'factura', p_factura, 'factura_id', v_id, 'total', v_base + v_iva);
end $$;


--
-- Name: conta_cierres(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cierres(p_company uuid, p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_r jsonb;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  with c as (
    select s.id, s.location_id, l.name as local, s.sales_day, s.unit_key, s.channel_id, ch.name as canal, ch.slug as canal_slug, b.name as marca,
           s.tickets_count, s.total, e.id as entry_id, e.status as estado_asiento, e.number as numero_asiento, e.series as serie_asiento,
           ci.id as factura_id, ci.number_text as factura, d.storage_path as documento, w.motivo as espera, w.automatica as espera_sola,
           (select count(*) from public.conta_cierre_ajuste a where a.company_id = s.company_id and a.location_id = s.location_id and a.unit_key = s.unit_key
             and (a.sales_day = s.sales_day or a.dia_destino = s.sales_day)) as ajustes,
           case when e.status in ('propuesto', 'borrador') then (select m.motivo from public.conta_motivos_para_validar(e.id) m order by m.orden limit 1) end as bloqueo
      from public.sales_day_summary s
      join public.locations l on l.id = s.location_id and l.account_id = v_cuenta
      left join public.sales_channel ch on ch.id = s.channel_id and ch.account_id = v_cuenta
      left join public.brand b on b.id = s.brand_id and b.account_id = v_cuenta
      left join public.journal_entry e on e.id = s.entry_id
      left join public.customer_invoice ci on ci.entry_id = s.entry_id and ci.origin = 'cierre_dia'
      left join public.journal_entry_document d on d.entry_id = s.entry_id and d.kind = 'resumen_ventas'
      left join public.conta_cierre_espera w on w.company_id = s.company_id and w.location_id = s.location_id and w.sales_day = s.sales_day and w.unit_key = s.unit_key
     where s.company_id = p_company and s.unit_key is not null and s.channel_id is not null
       and (p_desde is null or s.sales_day >= p_desde) and (p_hasta is null or s.sales_day <= p_hasta)
  ), sin as (
    -- Días sin ningún cierre que el cierre del día no ha podido proponer.
    select g.location_id, l.name as local, g.sales_day, g.result, g.reason
      from public.sales_day_proposal_log g join public.locations l on l.id = g.location_id and l.account_id = v_cuenta
     where g.company_id = p_company and g.result in ('sin_propuesta', 'fallo')
       and (p_desde is null or g.sales_day >= p_desde) and (p_hasta is null or g.sales_day <= p_hasta)
       and not exists (select 1 from public.sales_day_summary s2 join public.journal_entry e2 on e2.id = s2.entry_id
                        where s2.company_id = p_company and s2.location_id = g.location_id and s2.sales_day = g.sales_day and e2.status in ('propuesto', 'borrador', 'validado'))
  )
  select coalesce(jsonb_agg(x order by x->>'dia' desc, x->>'local', x->>'canal'), '[]'::jsonb) into v_r from (
    select jsonb_build_object('id', c.id, 'local_id', c.location_id, 'local', c.local, 'dia', c.sales_day, 'unidad', c.unit_key, 'canal_id', c.channel_id,
             'canal', coalesce(c.canal, 'Sin canal'), 'canal_slug', c.canal_slug, 'marca', c.marca, 'tiques', c.tickets_count, 'total', c.total,
             'asiento_id', c.entry_id, 'estado_asiento', c.estado_asiento, 'numero_asiento', c.numero_asiento, 'serie_asiento', c.serie_asiento,
             'factura_id', c.factura_id, 'factura', c.factura, 'documento', c.documento, 'ajustes', c.ajustes,
             'estado', case when c.estado_asiento = 'validado' then 'validado'
                            when c.estado_asiento = 'anulado' then 'anulado'
                            when c.entry_id is null or c.espera is not null or c.bloqueo is not null then 'en_espera'
                            else 'por_validar' end,
             'motivo', coalesce(c.espera, c.bloqueo, case when c.entry_id is null then 'Al rehacerlo no ha salido asiento: mira sus pedidos.' end),
             'espera_a_mano', c.espera is not null and not c.espera_sola) as x
      from c
    union all
    select jsonb_build_object('id', null, 'local_id', sin.location_id, 'local', sin.local, 'dia', sin.sales_day, 'unidad', null, 'canal', 'Sin cierre',
             'tiques', 0, 'total', 0, 'estado', 'en_espera', 'ajustes', 0, 'espera_a_mano', false,
             'motivo', coalesce(sin.reason, 'El cierre del día no ha podido proponerlo.'))
      from sin
  ) t;
  return v_r;
end $$;


--
-- Name: conta_clave_direccion(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_clave_direccion(p_texto text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select nullif(regexp_replace(
           regexp_replace(lower(public.unaccent(coalesce(p_texto, ''))),
                          '\m(calle|c|avenida|avda|av|paseo|plaza|pza|camino|carretera|ctra|de|del|la|el|los|las)\M', ' ', 'g'),
           '[^a-z0-9]+', '', 'g'), '')
$$;


--
-- Name: FUNCTION conta_clave_direccion(p_texto text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_clave_direccion(p_texto text) IS 'V01 · La calle y el número de una dirección, para compararlas: sin tildes, sin «calle de» y sin signos.';


--
-- Name: conta_clave_numero(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_clave_numero(p text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  select nullif(case when k ~ '^(SN|SINNUMERO|SINNMERO|SINNUM|0+)$' then '' else k end, '')
    from (select upper(regexp_replace(coalesce(p, ''), '[^A-Za-z0-9]', '', 'g')) as k) x
$_$;


--
-- Name: FUNCTION conta_clave_numero(p text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_clave_numero(p text) IS 'D01 · La clave de número de factura de la regla única de repetidas: mayúsculas, solo letras y cifras; «s/n», «sin número», «0…» no son número (null). La misma que claveNumero() en _shared/lecturaFactura.ts.';


--
-- Name: conta_cobro_ajustes_guardar(uuid, boolean, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobro_ajustes_guardar(p_company uuid, p_recordatorios boolean, p_dias integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid := public._pc01e3_empresa(p_company);
        v_dias integer[] := (select array_agg(distinct d order by d) from unnest(coalesce(p_dias, '{}'::integer[])) d where d is not null);
        v_txt text;
begin
  if p_recordatorios is null then raise exception 'Di si se mandan o no.' using errcode = '22023'; end if;
  if coalesce(cardinality(v_dias), 0) = 0 then raise exception 'Pon al menos un día.' using errcode = '22023'; end if;
  if cardinality(v_dias) > 6 then raise exception 'Como mucho, seis días.' using errcode = '22023'; end if;
  if exists (select 1 from unnest(v_dias) d where d < -30 or d > 90) then
    raise exception 'Cada día, entre 30 antes de vencer y 90 después.' using errcode = '22023';
  end if;
  insert into public.conta_cobro_ajuste (company_id, account_id, recordatorios, recordatorio_dias, updated_at, updated_by_name)
  values (p_company, v_cuenta, p_recordatorios, v_dias, now(), coalesce(public.conta_nombre_actor(), 'Sumied'))
  on conflict (company_id) do update set recordatorios = excluded.recordatorios, recordatorio_dias = excluded.recordatorio_dias,
                                         updated_at = now(), updated_by_name = excluded.updated_by_name;
  v_txt := (select string_agg(case when d < 0 then format('%s días antes', -d) when d = 0 then 'el día que vence' else format('a los %s días', d) end, ', ' order by d)
              from unnest(v_dias) d);
  return jsonb_build_object('frase', case when p_recordatorios
    then format('Guardado: los recordatorios se mandan %s.', v_txt)
    else 'Guardado: los recordatorios están apagados. No se manda ninguno.' end);
end $$;


--
-- Name: conta_cobro_redsys_datos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobro_redsys_datos(p_company uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('empresa', r.company_id, 'comercio', r.comercio, 'terminal', r.terminal, 'bizum', r.bizum, 'modo', r.modo, 'cobra', r.cobra,
                            'clave', (select s.decrypted_secret from vault.decrypted_secrets s where s.id = r.clave_ref))
    from public.conta_cobro_redsys r where r.company_id = p_company
$$;


--
-- Name: conta_cobro_redsys_guardar(uuid, text, text, text, boolean, boolean, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobro_redsys_guardar(p_company uuid, p_comercio text, p_terminal text, p_clave text, p_bizum boolean, p_en_enlace boolean, p_modo text, p_cobra boolean, p_quien text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_cuenta uuid; r public.conta_cobro_redsys; v_comercio text := nullif(regexp_replace(coalesce(p_comercio, ''), '\s', '', 'g'), '');
        v_terminal text := coalesce(nullif(ltrim(trim(coalesce(p_terminal, '')), '0'), ''), '1'); v_clave text := nullif(trim(coalesce(p_clave, '')), '');
        v_ref uuid; v_estado text; v_frase text;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  if v_comercio is not null and v_comercio !~ '^[0-9]{9}$' then raise exception 'El número de comercio son 9 cifras (te lo da tu banco con el TPV virtual).' using errcode = '22023'; end if;
  if v_terminal !~ '^[0-9]{1,3}$' then raise exception 'El terminal es un número de 1 a 3 cifras (casi siempre, 1).' using errcode = '22023'; end if;
  if v_clave is not null and (v_clave !~ '^[A-Za-z0-9+/]{32}$') then
    raise exception 'La clave del comercio son 32 letras y números (la «clave SHA-256» del TPV virtual, en el panel de tu banco).' using errcode = '22023';
  end if;
  if p_modo not in ('prueba', 'real') then raise exception 'Modo: prueba o real.' using errcode = '22023'; end if;
  select * into r from public.conta_cobro_redsys where company_id = p_company for update;
  v_ref := r.clave_ref;
  if v_clave is not null then
    if v_ref is null or not exists (select 1 from vault.secrets where id = v_ref) then
      select id into v_ref from vault.secrets where name = 'conta_redsys:' || p_company::text;
    end if;
    if v_ref is not null then
      perform vault.update_secret(v_ref, v_clave, 'conta_redsys:' || p_company::text, 'Clave del TPV virtual (Redsys) de una empresa de Sumied');
    else
      v_ref := vault.create_secret(v_clave, 'conta_redsys:' || p_company::text, 'Clave del TPV virtual (Redsys) de una empresa de Sumied');
    end if;
  end if;
  insert into public.conta_cobro_redsys (company_id, account_id, comercio, terminal, clave_ref, bizum, en_enlace, modo, cobra, updated_at, updated_by_name)
  values (p_company, v_cuenta, v_comercio, v_terminal, v_ref, coalesce(p_bizum, false), coalesce(p_en_enlace, true), p_modo, coalesce(p_cobra, false), now(), p_quien)
  on conflict (company_id) do update set comercio = excluded.comercio, terminal = excluded.terminal, clave_ref = excluded.clave_ref, bizum = excluded.bizum,
    en_enlace = excluded.en_enlace, modo = excluded.modo, cobra = excluded.cobra, updated_at = now(), updated_by_name = excluded.updated_by_name
  returning * into r;
  v_estado := public._s01_redsys_estado(r);
  v_frase := case v_estado
    when 'falta_comercio' then 'Guardado. A Redsys le falta el número de comercio.'
    when 'falta_clave' then format('Guardado. Redsys, comercio %s: falta la clave del comercio.', r.comercio)
    when 'pruebas' then format('Guardado. Redsys en pruebas, comercio %s%s.', r.comercio,
                               case when r.cobra then '' else ': tus clientes aún no pagan por aquí; lo abre Julio, empresa a empresa' end)
    else format('Guardado. Redsys activo, comercio %s: tus clientes ya pagan con tarjeta%s.', r.comercio, case when r.bizum then ' y Bizum' else '' end) end;
  return jsonb_build_object('frase', v_frase, 'estado', v_estado, 'proveedor_enlace', public._s01_proveedor_enlace(p_company));
end $_$;


--
-- Name: conta_cobro_redsys_leer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobro_redsys_leer(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; r public.conta_cobro_redsys;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  select * into r from public.conta_cobro_redsys where company_id = p_company;
  if r.company_id is null then return null; end if;
  return jsonb_build_object('estado', public._s01_redsys_estado(r), 'comercio', r.comercio, 'terminal', r.terminal, 'con_clave', r.clave_ref is not null,
                            'bizum', r.bizum, 'en_enlace', r.en_enlace, 'modo', r.modo, 'cobra', r.cobra,
                            'proveedor_enlace', public._s01_proveedor_enlace(p_company),
                            'cambiado', jsonb_build_object('at', r.updated_at, 'por', r.updated_by_name));
end $$;


--
-- Name: conta_cobro_stripe_apuntar(uuid, text, text, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobro_stripe_apuntar(p_company uuid, p_stripe text, p_tarjeta text, p_bizum text, p_bizum_encendido boolean, p_pendiente integer, p_quien text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v public.conta_cobro_stripe;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  insert into public.conta_cobro_stripe (company_id, account_id, stripe_account_id, tarjeta, bizum, bizum_encendido, pendiente, leido_at, created_by_name)
  values (p_company, v_cuenta, p_stripe, coalesce(p_tarjeta, 'falta_alta'), coalesce(p_bizum, 'falta_alta'), coalesce(p_bizum_encendido, false),
          coalesce(p_pendiente, 0), now(), p_quien)
  on conflict (company_id) do update set
    tarjeta = coalesce(p_tarjeta, conta_cobro_stripe.tarjeta), bizum = coalesce(p_bizum, conta_cobro_stripe.bizum),
    bizum_encendido = coalesce(p_bizum_encendido, conta_cobro_stripe.bizum_encendido), pendiente = coalesce(p_pendiente, conta_cobro_stripe.pendiente),
    leido_at = now()
  where conta_cobro_stripe.stripe_account_id = excluded.stripe_account_id
  returning * into v;
  if v.company_id is null then raise exception 'Esta empresa ya tiene otra cuenta de Stripe.' using errcode = '23505'; end if;
  return jsonb_build_object('tarjeta', v.tarjeta, 'bizum', v.bizum, 'bizum_encendido', v.bizum_encendido, 'pendiente', v.pendiente, 'modo', v.modo);
end $$;


--
-- Name: conta_cobro_stripe_de(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobro_stripe_de(p_stripe text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('empresa', company_id, 'cuenta', account_id, 'stripe', stripe_account_id, 'modo', modo, 'tarjeta', tarjeta, 'bizum', bizum)
    from public.conta_cobro_stripe where stripe_account_id = p_stripe
$$;


