end $$;


--
-- Name: conta_cobros_abonos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobros_abonos(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', e.invoice_id, 'proveedor', coalesce(e.proveedor, 'stripe'),
                                                       'cobrado', (e.pagado_at at time zone 'Europe/Madrid')::date, 'abonado', m.op_date))
                     from public.conta_enlace_pago e
                     left join public.bank_match b on b.id = e.abono_match_id and b.status = 'vivo'
                     left join public.bank_movement m on m.id = b.movement_id
                    where e.company_id = p_company and e.status = 'pagado' and e.payment_id is not null), '[]'::jsonb);
end $$;


--
-- Name: conta_cobros_lista(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobros_lista(p_company uuid, p_mes date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with f as (
    select ci.id, ci.party_id, coalesce(p.name, 'Sin cliente') as cliente, ci.number_text as numero, ci.issue_date as fecha, c.vence,
           c.total, c.cobrado, c.pendiente, c.estado, c.dias_vencida, ci.location_id, lo.name as local,
           case when c.de_plataforma then 'plataforma'
                else coalesce(case pm.code when 'domiciliacion' then 'direct_debit' when 'transferencia' then 'transfer'
                                           when 'tarjeta' then 'card' when 'efectivo' then 'cash' end, cf.payment_method) end as forma,
           nullif(trim(cf.sepa_mandate_ref), '') as mandato, cf.sepa_mandate_date as mandato_firmado,
           (nullif(trim(cf.sepa_mandate_ref), '') is not null and cf.sepa_mandate_date is not null and cf.iban is not null) as con_mandato,
           right(cf.iban, 4) as iban4,
           exists (select 1 from public.company_account_link l where l.company_id = p_company and l.entity = 'customer' and l.entity_id = ci.party_id::text and l.role = 'principal') as con_cuenta,
           (select jsonb_build_object('id', r.id, 'codigo', r.code, 'importe', sum(l.amount), 'cargo', r.charge_date)
              from public.conta_cobro_remesa_linea_estado l join public.conta_cobro_remesa r on r.id = l.remesa_id
             where l.invoice_id = ci.id and l.estado = 'pendiente' group by r.id, r.code, r.charge_date order by r.code desc limit 1) as remesa,
           (select jsonb_build_object('linea', l.id, 'remesa', r.id, 'codigo', r.code, 'fecha', l.devuelto_el, 'motivo', l.return_reason, 'gastos', l.return_fee)
              from public.conta_cobro_remesa_linea_estado l join public.conta_cobro_remesa r on r.id = l.remesa_id
             where l.invoice_id = ci.id and l.estado = 'devuelto' order by l.returned_at desc limit 1) as devuelto
      from public.customer_invoice ci
      join public.conta_factura_cobro c on c.invoice_id = ci.id
      left join public.party p on p.id = ci.party_id
      left join public.customer_fiscal cf on cf.party_id = ci.party_id
      left join public.payment_method pm on pm.id = ci.payment_method_id
      left join public.locations lo on lo.id = ci.location_id
     where ci.account_id = (select account_id from public.company where id = p_company)
       and ci.company_id = p_company and ci.status = 'emitida' and ci.total > 0
       and public.belongs_to_account(ci.account_id)
  )
  select jsonb_build_object(
    'filas', coalesce((select jsonb_agg(to_jsonb(f) order by f.vence nulls last, f.fecha) from f), '[]'::jsonb),
    'cobrado_mes', (select coalesce(sum(cp.amount), 0) from public.customer_invoice_payment cp join f on f.id = cp.invoice_id
                     where cp.paid_on >= date_trunc('month', p_mes)::date and cp.paid_on < (date_trunc('month', p_mes) + interval '1 month')::date),
    'cobradas_mes', (select count(distinct cp.invoice_id) from public.customer_invoice_payment cp join f on f.id = cp.invoice_id
                      where f.estado = 'cobrada' and cp.paid_on >= date_trunc('month', p_mes)::date and cp.paid_on < (date_trunc('month', p_mes) + interval '1 month')::date),
    'remesas', (select count(*) from public.conta_cobro_remesa r where r.company_id = p_company),
    'sin_mandato', coalesce((select jsonb_agg(x order by x->>'nombre') from (
        select jsonb_build_object('id', f.party_id, 'nombre', f.cliente, 'facturas', count(*), 'pendiente', sum(f.pendiente),
                 'correo', (select ci2.email_to from public.customer_invoice ci2 where ci2.party_id = f.party_id and ci2.email_to is not null order by ci2.issue_date desc limit 1),
                 'enviado', (select jsonb_build_object('at', m.sent_at, 'a', m.sent_to, 'ref', m.ref) from public.conta_mandato m
                              where m.party_id = f.party_id and m.company_id = p_company and m.status = 'por_firmar' and m.expires_at > now() order by m.created_at desc limit 1)) as x
          from f where f.forma = 'direct_debit' and f.pendiente >= 0.005 and not f.con_mandato and f.party_id is not null
         group by f.party_id, f.cliente) s), '[]'::jsonb))
$$;


--
-- Name: FUNCTION conta_cobros_lista(p_company uuid, p_mes date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_cobros_lista(p_company uuid, p_mes date) IS 'PC01 · E3 · Ventas › Cobros: las emitidas de la empresa con su estado de cobro, cómo se cobran, su mandato, su remesa y su devuelto.';


--
-- Name: conta_cobros_para_casar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cobros_para_casar(p_company uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'abonos', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'codigo', r.code, 'cargo', r.charge_date, 'por_abonar', r.por_abonar,
        'recibos', (select jsonb_agg(jsonb_build_object('id', l.id, 'importe', l.amount, 'cliente', p.name, 'factura', ci.number_text) order by p.name)
                      from public.conta_cobro_remesa_linea_estado l join public.customer_invoice ci on ci.id = l.invoice_id left join public.party p on p.id = l.party_id
                     where l.remesa_id = r.id and l.estado = 'pendiente')) order by r.charge_date)
      from public.conta_cobro_remesa_estado r where r.company_id = p_company and r.estado = 'en_banco' and r.por_abonar > 0), '[]'::jsonb),
    'devoluciones', coalesce((select jsonb_agg(jsonb_build_object(
        'id', l.id, 'remesa', r.code, 'importe', l.amount, 'cliente', p.name, 'factura', ci.number_text, 'abonado', l.abonado_el) order by l.abonado_el desc)
      from public.conta_cobro_remesa_linea_estado l join public.conta_cobro_remesa r on r.id = l.remesa_id
      join public.customer_invoice ci on ci.id = l.invoice_id left join public.party p on p.id = l.party_id
     where r.company_id = p_company and l.estado = 'cobrado' and l.abonado_el >= public.conta_hoy() - 56), '[]'::jsonb))
$$;


--
-- Name: conta_comision_de_la_factura(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_comision_de_la_factura(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.supplier_invoice where id = p_invoice;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501'; end if;
  return public._conta_comision_estado(p_invoice);
end $$;


--
-- Name: conta_comision_del_correo(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_comision_del_correo(p_settlement uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_cs public.channel_settlement; v_e uuid; v_rol public.party_role; v_sup uuid; v_num text; v_clave text;
  v_base numeric; v_iva numeric; v_total numeric; v_ya uuid; v_inv uuid; v_410 text; v_c623 text; v_tasa uuid;
  v_cuadra boolean; v_fecha date; v_porque text; v_periodo text;
begin
  select * into v_cs from public.channel_settlement where id = p_settlement;
  if v_cs.id is null then return jsonb_build_object('estado', 'no', 'factura_id', null, 'texto', 'No está la liquidación.'); end if;
  v_num := nullif(btrim(p->'factura'->>'numero'), '');
  v_base := nullif(p->'factura'->>'base', '')::numeric; v_iva := nullif(p->'factura'->>'iva', '')::numeric; v_total := nullif(p->'factura'->>'total', '')::numeric;
  if v_num is null or v_total is null then
    return jsonb_build_object('estado', 'sin_factura', 'factura_id', null, 'texto', 'El correo no trae su factura de comisión.');
  end if;
  select company_id into v_e from public.platform_store where id = v_cs.store_id;
  if v_e is null then return jsonb_build_object('estado', 'sin_empresa', 'factura_id', null, 'texto', 'La liquidación no dice de qué empresa es: la factura no se ha creado.'); end if;

  -- El proveedor: el de la plataforma del canal (su tercero → su ficha de proveedor).
  select * into v_rol from public.party_role where account_id = v_cs.account_id and role = 'platform' and channel_id = v_cs.channel_id order by created_at limit 1;
  select supplier_id into v_sup from public.party_role where account_id = v_cs.account_id and role = 'supplier' and party_id = v_rol.party_id order by created_at limit 1;
  if v_sup is null then
    return jsonb_build_object('estado', 'falta_proveedor', 'factura_id', null,
      'texto', 'La plataforma no tiene ficha de proveedor: su factura de comisión no se ha creado.');
  end if;

  -- La misma factura (el mismo proveedor y el mismo número): no se crea otra.
  v_clave := upper(regexp_replace(v_num, '[^A-Za-z0-9]', '', 'g'));
  select id into v_ya from public.supplier_invoice
   where account_id = v_cs.account_id and supplier_id = v_sup and status <> 'descartada'
     and upper(regexp_replace(coalesce(invoice_number, ''), '[^A-Za-z0-9]', '', 'g')) = v_clave
   order by created_at limit 1;
  if v_ya is not null then
    return jsonb_build_object('estado', 'ya_estaba', 'factura_id', v_ya, 'texto', format('Su factura de comisión %s ya estaba.', v_num));
  end if;

  v_cuadra := v_base is not null and v_iva is not null and round(v_base * 100) + round(v_iva * 100) = round(v_total * 100);
  v_porque := case when v_base is null or v_iva is null then 'La factura del correo no dice su base o su IVA: revísala con el correo.'
                   when not v_cuadra then format('La factura no suma: base %s + IVA %s no es el total %s. Revísala con el correo.',
                     public.conta_euros_exactos(v_base), public.conta_euros_exactos(v_iva), public.conta_euros_exactos(v_total)) end;
  v_fecha := coalesce(case when p->>'fecha_factura' ~ '^\d{4}-\d{2}-\d{2}$' then (p->>'fecha_factura')::date end, v_cs.period_to, v_cs.settlement_date);
  v_periodo := case when v_cs.period_from is not null then format('del %s al %s', to_char(v_cs.period_from, 'DD/MM'), to_char(v_cs.period_to, 'DD/MM/YYYY')) else 'sin periodo' end;

  -- La cuenta: la que diga la plataforma; si no, la 623x aprendida del libro; si no, la de la plantilla.
  select a.code into v_410 from public.company_account_link l join public.company_account a on a.id = l.company_account_id
   where l.company_id = v_e and l.entity = 'supplier' and l.entity_id = v_sup::text and l.role = 'principal' limit 1;
  v_c623 := coalesce(nullif(btrim(v_rol.commission_account_code), ''), public._conta_cuenta_aprendida(v_e, v_410, '623'),
                     (select code from public.company_account where company_id = v_e and kind = 'template' and template_code = '623' order by code limit 1));
  select id into v_tasa from public.tax_rate where code = 'iva_general' and is_system order by valid_to desc nulls first limit 1;

  insert into public.supplier_invoice (account_id, company_id, supplier_id, location_id, brand_id, doc_kind, invoice_number, invoice_date, status, source,
                                       arrival_channel, tax_base_total, tax_total, grand_total, needs_review, notes, reading, reading_confidence, created_by_name)
  values (v_cs.account_id, v_e, v_sup, v_cs.location_id, v_cs.brand_id, 'invoice', v_num, v_fecha, 'en_revision', 'liquidacion', 'correo',
          coalesce(v_base, 0), coalesce(v_iva, 0), v_total, not coalesce(v_cuadra, false),
          coalesce(v_porque, format('Leída del correo de la liquidación %s.', v_periodo)),
          jsonb_build_object('origen', 'correo_liquidacion', 'liquidacion_id', v_cs.id, 'email_id', nullif(p->>'email_id', ''),
            'factura', jsonb_build_object('numero', v_num, 'fecha', v_fecha,
              'periodo', jsonb_build_object('desde', v_cs.period_from, 'hasta', v_cs.period_to),
              'tienda', jsonb_build_object('nombre', nullif(p->>'tienda', ''))),
            'requisitos', case when v_porque is not null then jsonb_build_array(jsonb_build_object('id', 'cuadra', 'ok', false, 'texto', v_porque)) else '[]'::jsonb end,
            'avisos', coalesce(p->'avisos', '[]'::jsonb)),
          case when coalesce(v_cuadra, false) then 'probable' else 'duda' end, 'Sumied · leída del correo')
  returning id into v_inv;
  if v_base is not null then
    insert into public.supplier_invoice_line (supplier_invoice_id, raw_text, qty, unit_price, line_amount, vat_pct, expense_account_code, position)
    values (v_inv, 'Comisión y cargos de la plataforma', 1, v_base, v_base, 21, v_c623, 1);
  end if;
  if v_base is not null and v_iva is not null then
    insert into public.supplier_invoice_tax (account_id, supplier_invoice_id, tax_rate_id, vat_pct, base, vat_amount)
    values (v_cs.account_id, v_inv, v_tasa, 21, v_base, v_iva);
  end if;
  -- Su liquidación es ésta: se liga (S01i). Se paga por compensación al validarla.
  perform public._conta_comision_ligar(v_inv, v_cs.id, 'sumied', null);
  return jsonb_build_object('estado', case when v_porque is null then 'creada' else 'en_revision' end, 'factura_id', v_inv,
    'texto', case when v_porque is null
      then format('Su factura de comisión %s (%s) está en «Por revisar», ligada a su liquidación.', v_num, public.conta_euros_exactos(v_total))
      else format('Su factura de comisión %s está en «Por revisar»: %s', v_num, v_porque) end);
end $_$;


--
-- Name: conta_comision_ligar(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_comision_ligar(p_invoice uuid, p_settlement uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.supplier_invoice; cs public.channel_settlement; v_pagada boolean;
begin
  select * into v from public.supplier_invoice where id = p_invoice;
  if v.id is null or not public.belongs_to_account(v.account_id) then raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501'; end if;
  if auth.uid() is not null and not public.current_user_is_admin_or_manager_of(v.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta liga facturas con liquidaciones.' using errcode = '42501';
  end if;
  perform public._conta_comision_ligar(v.id, p_settlement, 'persona', coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona'));
  select * into cs from public.channel_settlement where id = p_settlement;
  select status = 'pagada' into v_pagada from public.supplier_invoice where id = v.id;
  return jsonb_build_object('liquidacion', cs.id, 'pagada', v_pagada,
    'texto', format('Ligada con la liquidación del %s al %s%s', to_char(cs.period_from, 'DD/MM'), to_char(cs.period_to, 'DD/MM/YYYY'),
      case when v_pagada then ': pagada por compensación, no se paga por banco.' else ': quedará pagada por compensación al validarla.' end));
end $$;


--
-- Name: conta_contrasena_de_marca(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_contrasena_de_marca(p_correo text, p_marca text) RETURNS TABLE(user_id uuid, se_puede boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select u.id,
         (u.recovery_sent_at is null or u.recovery_sent_at < now() - interval '60 seconds')
    from auth.users u
   where lower(u.email) = lower(trim(p_correo))
     and exists (select 1 from public.user_profiles p join public.accounts a on a.id = p.account_id
                  where p.user_id = u.id and p.active and a.product_brand = p_marca and a.deleted_at is null)
   limit 1
$$;


--
-- Name: FUNCTION conta_contrasena_de_marca(p_correo text, p_marca text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_contrasena_de_marca(p_correo text, p_marca text) IS 'C06 · ¿Es este correo de una persona activa de una cuenta de esta marca, y ha pasado un minuto desde la última recuperación? Solo service_role (edge function conta-contrasena).';


--
-- Name: conta_contrasena_pedir(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_contrasena_pedir(p_correo text, p_marca text, p_conexion text) RETURNS TABLE(user_id uuid, se_puede boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_correo text := lower(trim(p_correo));
  v_hc text := encode(extensions.digest(v_correo, 'sha256'), 'hex');
  v_hx text := case when nullif(trim(p_conexion), '') is null then null else encode(extensions.digest(trim(p_conexion), 'sha256'), 'hex') end;
  v_por_correo int; v_por_conexion int;
begin
  delete from public.conta_contrasena_intento where pedido_en < now() - interval '24 hours';
  insert into public.conta_contrasena_intento (correo_huella, conexion_huella, marca) values (v_hc, v_hx, p_marca);
  -- Contando esta: la 6.ª del correo o la 21.ª de la conexión ya no manda nada.
  select count(*) into v_por_correo from public.conta_contrasena_intento where correo_huella = v_hc and pedido_en > now() - interval '1 hour';
  select count(*) into v_por_conexion from public.conta_contrasena_intento where v_hx is not null and conexion_huella = v_hx and pedido_en > now() - interval '1 hour';
  return query
    select u.id,
           (u.recovery_sent_at is null or u.recovery_sent_at < now() - interval '60 seconds') and v_por_correo <= 5 and v_por_conexion <= 20
      from auth.users u
     where lower(u.email) = v_correo
       and exists (select 1 from public.user_profiles p join public.accounts a on a.id = p.account_id
                    where p.user_id = u.id and p.active and a.product_brand = p_marca and a.deleted_at is null)
     limit 1;
end $$;


--
-- Name: FUNCTION conta_contrasena_pedir(p_correo text, p_marca text, p_conexion text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_contrasena_pedir(p_correo text, p_marca text, p_conexion text) IS 'C06b · Apunta la petición (huellas) y dice si se manda: persona activa de una cuenta de esa marca, un minuto desde la última recuperación, ≤ 5 en la hora por correo y ≤ 20 por conexión. Solo service_role (edge function conta-contrasena).';


--
-- Name: conta_correo_facturas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_correo_facturas(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare a company_inbound_address; v_conf inbound_email_log; v_ult timestamptz; v_lleg jsonb;
begin
  if not exists (select 1 from company c where c.id = p_company and public.belongs_to_account(c.account_id)) then
    raise exception 'Esa empresa no está.' using errcode = 'P0002';
  end if;
  select * into a from company_inbound_address where company_id = p_company and kind = 'facturas';
  if a.id is null then return jsonb_build_object('direccion', null); end if;
  select max(received_at) into v_ult from inbound_email_log
   where company_id = p_company and lower(split_part(to_address, '@', 1)) = lower(a.local_part);
  select * into v_conf from inbound_email_log
   where company_id = p_company and outcome = 'confirmacion' and lower(split_part(to_address, '@', 1)) = lower(a.local_part)
   order by received_at desc limit 1;
  select coalesce(jsonb_agg(x order by x->>'fecha' desc), '[]') into v_lleg from (
    select jsonb_build_object('fecha', l.received_at, 'de', l.from_address, 'asunto', l.subject, 'resultado', l.outcome,
             'llegada', d.status, 'motivo', d.reason,
             'factura', case when si.id is not null then jsonb_build_object('id', si.id, 'codigo', si.code, 'numero', si.invoice_number, 'total', si.grand_total,
                                                                         'proveedor', sp.name, 'casada', exists (select 1 from supplier_invoice_receipt r where r.supplier_invoice_id = si.id)) end,
             'dicho', (select da.text from document_activity da where da.supplier_invoice_id = coalesce(d.supplier_invoice_id, d.duplicate_of_invoice_id)
                         and da.action in ('casada', 'propuesta') order by da.created_at desc limit 1),
             -- S01j · Para «Volver a leer», y lo que salió del correo: sus liquidaciones (y la factura de comisión de Just Eat).
             'email_id', l.email_id,
             'liquidaciones', (select coalesce(jsonb_agg(jsonb_build_object('id', cs.id, 'plataforma', sc.name,
                                  'tienda', regexp_replace(coalesce(ps.external_text, cs.external_location_text, ''), '\s*\(.*$', ''),
                                  'local', lo.name, 'desde', cs.period_from, 'hasta', cs.period_to, 'neto', cs.net_payout,
                                  'pago_el', cs.settlement_date,
                                  -- S01j·2 · Una liquidación que ya había entrado con otro correo (el mismo Excel reenviado dos veces).
                                  'otro_correo', cs.inbound_email_id is distinct from l.email_id) order by cs.period_from), '[]'::jsonb)
                                 from channel_settlement cs left join sales_channel sc on sc.id = cs.channel_id
                                 left join platform_store ps on ps.id = cs.store_id left join locations lo on lo.id = coalesce(cs.location_id, ps.location_id)
                                where cs.account_id = l.account_id
                                  and (cs.inbound_email_id = l.email_id
                                       or cs.id::text in (select x->>'id' from jsonb_array_elements(case when jsonb_typeof(l.detail->'liquidaciones') = 'array' then l.detail->'liquidaciones' else '[]'::jsonb end) x))),
             -- S01j·2 · De qué plataforma es (para «Volver a leer todo lo de…») y qué pasó con su Excel:
             -- leído; sin leer (llegó antes de que se leyeran: se dejó como «no es un PDF»); o no venía.
             'plataforma', case when l.from_address ~* 'glovo' or l.subject ~* 'glovo' then 'glovo'
                                when l.from_address ~* 'just-?eat' or l.subject ~* 'just-?eat' then 'justeat' end,
             'excel', case when jsonb_typeof(l.detail->'liquidaciones') = 'array' then 'leido'
                           when exists (select 1 from jsonb_array_elements(case when jsonb_typeof(l.detail->'dejados') = 'array' then l.detail->'dejados' else '[]'::jsonb end) x
                                         where x->>'nombre' ~* '\.xlsx?$') then 'sin_leer'
                           when (l.from_address ~* 'glovo' or l.subject ~* 'glovo') and l.outcome <> 'confirmacion' then 'no_traia' end,
             'factura_comision', case when l.detail ? 'factura_id' then (select jsonb_build_object('id', fi.id, 'codigo', fi.code, 'numero', fi.invoice_number,
                                  'total', fi.grand_total, 'en_revision', fi.needs_review, 'nota', fi.notes)
                                 from supplier_invoice fi where fi.id = nullif(l.detail->>'factura_id', '')::uuid and fi.account_id = l.account_id) end) x
      from inbound_email_log l
      left join document_inbox d on d.email_id = l.email_id and d.company_id = p_company
      left join supplier_invoice si on si.id = coalesce(d.supplier_invoice_id, d.duplicate_of_invoice_id)
      left join supplier sp on sp.id = si.supplier_id
     where l.company_id = p_company and lower(split_part(l.to_address, '@', 1)) = lower(a.local_part)
     order by l.received_at desc limit 30) y;
  return jsonb_build_object('direccion', a.local_part || '@' || a.domain, 'activa', a.active, 'ultimo', v_ult,
    'confirmacion', case when v_conf.id is not null then jsonb_build_object('fecha', v_conf.received_at, 'codigo', v_conf.detail->>'codigo', 'enlace', v_conf.detail->>'enlace') end,
    'llegadas', v_lleg);
end $_$;


--
-- Name: conta_correo_releer_lista(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_correo_releer_lista(p_company uuid, p_email_ids text[] DEFAULT NULL::text[], p_remitente text DEFAULT NULL::text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v text[];
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no es de tu cuenta.' using errcode = '42501'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta vuelve a leer correos.' using errcode = '42501';
  end if;
  if p_email_ids is null and coalesce(btrim(p_remitente), '') = '' then raise exception 'Di qué correos hay que volver a leer.' using errcode = '22023'; end if;
  if p_remitente is not null and p_remitente not in ('glovo', 'justeat') then raise exception 'Solo se vuelve a leer todo lo de Glovo o de Just Eat.' using errcode = '22023'; end if;
  select coalesce(array_agg(x.email_id order by x.received_at), '{}'::text[]) into v from (
    select l.email_id, l.received_at from public.inbound_email_log l
     where l.company_id = p_company and l.outcome <> 'confirmacion'
       and (l.email_id = any(coalesce(p_email_ids, '{}'::text[]))
            or (p_remitente = 'glovo' and (l.from_address ~* 'glovo' or l.subject ~* 'glovo'))
            or (p_remitente = 'justeat' and (l.from_address ~* 'just-?eat' or l.subject ~* 'just-?eat')))
     order by l.received_at desc limit 60) x;
  return v;
end $$;


--
-- Name: conta_crear_cuenta_sola(text, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_crear_cuenta_sola(p_nombre text, p_slug text, p_admin_user_id uuid, p_admin_nombre text, p_marca text, p_motivo text, p_creada_por uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_admin_plataforma uuid;
  v_gerente_total    uuid := null;
  v_cuenta           uuid;
  v_perfil           uuid;
begin
  if coalesce(trim(p_nombre), '') = '' then raise exception 'Falta el nombre de la empresa.'; end if;
  if coalesce(trim(p_marca), '') = '' then raise exception 'Falta la marca con la que se vende.'; end if;
  if coalesce(trim(p_motivo), '') = '' then raise exception 'Falta por qué se da de alta (queda en el registro).'; end if;
  if p_admin_user_id is null then raise exception 'Falta el usuario del administrador del cliente.'; end if;

  select id into v_admin_plataforma from platform_admins where user_id = p_creada_por and active = true limit 1;
  if v_admin_plataforma is null then
    raise exception 'Solo un administrador activo de la plataforma da de alta cuentas (usuario %).', p_creada_por using errcode = '42501';
  end if;

  -- El conjunto de permisos de siempre (gerente_total), como create_account_tx.
  -- staging-conta no tiene permission_sets (su esquema es solo el de
  -- contabilidad): allí la cuenta nace sin él y lo dice; en producción es obligatorio.
  if to_regclass('public.permission_sets') is not null then
    execute $q$select id from public.permission_sets where name = 'gerente_total' and is_system = true and account_id is null limit 1$q$
      into v_gerente_total;
    if v_gerente_total is null then raise exception 'No existe el conjunto de permisos global gerente_total.'; end if;
  else
    raise notice 'Esta base no tiene permission_sets (staging-conta): el administrador queda sin conjunto de permisos.';
  end if;

  -- product_brand va en el INSERT: los disparadores de siembra la ven y no siembran.
  insert into accounts (name, slug, status, country, created_by, business_type, product_brand)
  values (trim(p_nombre), p_slug, 'active', 'ES', p_creada_por, 'otra_actividad', p_marca)
  returning id into v_cuenta;

  insert into user_profiles (user_id, account_id, role, active, display_name)
  values (p_admin_user_id, v_cuenta, 'admin', true, nullif(trim(p_admin_nombre), ''))
  returning id into v_perfil;
  if v_gerente_total is not null then
    execute $q$insert into public.permission_set_assignments (user_profile_id, permission_set_id, assigned_by) values ($1, $2, $3)$q$
      using v_perfil, v_gerente_total, p_creada_por;
  end if;

  insert into feature_flags (account_id, feature_key, enabled, source, granted_by, grant_reason)
  values (v_cuenta, 'conta', true, 'manual_grant', p_creada_por, trim(p_motivo));

  insert into platform_audit_log (platform_admin_id, event_type, target_account_id, target_user_id, details)
  values (v_admin_plataforma, 'account_created', v_cuenta, p_admin_user_id,
    jsonb_build_object('slug', p_slug, 'producto', 'contabilidad', 'marca', p_marca, 'motivo', trim(p_motivo), 'sin_cocina', true));

  return v_cuenta;
end;
$_$;


--
-- Name: FUNCTION conta_crear_cuenta_sola(p_nombre text, p_slug text, p_admin_user_id uuid, p_admin_nombre text, p_marca text, p_motivo text, p_creada_por uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_crear_cuenta_sola(p_nombre text, p_slug text, p_admin_user_id uuid, p_admin_nombre text, p_marca text, p_motivo text, p_creada_por uuid) IS 'C06 · Alta de una cuenta SOLO de contabilidad: sin Cocina, con el interruptor conta (quién y por qué) y su apunte en platform_audit_log. Solo service_role (edge function conta-crear-cuenta).';


--
-- Name: conta_cuadro_con_pendiente(jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_cuadro_con_pendiente(p_cuadro jsonb, p_importe numeric) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(a.fila || jsonb_build_object('pendiente', round(p_importe - a.acumulado, 2)) order by a.n), '[]'::jsonb)
    from (select f.fila, f.n, sum((f.fila->>'capital')::numeric) over (order by f.n) as acumulado
            from jsonb_array_elements(p_cuadro) with ordinality as f(fila, n)) a
$$;


--
-- Name: FUNCTION conta_cuadro_con_pendiente(p_cuadro jsonb, p_importe numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_cuadro_con_pendiente(p_cuadro jsonb, p_importe numeric) IS 'S01d. El cuadro de un contrato con lo que queda por pagar después de cada fila (importe menos el capital acumulado).';


--
-- Name: conta_despacho_clientes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_despacho_clientes(p_account uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.company_id from public.company_tax_presenter t
   where t.advisor_account_id = p_account and t.mode = 'advisor' and t.consented_at is not null and t.revoked_at is null
$$;


--
-- Name: conta_despacho_correo_poner(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_despacho_correo_poner(p_account uuid, p_correo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v text := lower(btrim(coalesce(p_correo, '')));
begin
  if p_account is null or not public.current_user_is_admin_or_manager_of(p_account) then
    raise exception 'Solo la administración o una encargada de la asesoría cambia su correo.' using errcode = '42501';
  end if;
  if v !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Escribe un correo válido.' using errcode = '22023'; end if;
  update public.accounts set billing_email = v where id = p_account;
  return jsonb_build_object('ok', true, 'correo', v,
    'mensaje', format('Guardado: las respuestas de tus clientes llegarán a %s.', v));
end $_$;


--
-- Name: conta_despacho_equipo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_despacho_equipo(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_account is null or not public.belongs_to_account(p_account) then
    raise exception 'No eres de esta cuenta.' using errcode = '42501';
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('usuario', u.user_id, 'nombre', public.conta_impuesto_nombre_de_en(u.user_id, p_account), 'rol', u.role)
                                    order by public.conta_impuesto_nombre_de_en(u.user_id, p_account)), '[]')
            from public.user_profiles u
           where u.account_id = p_account and u.active);
end $$;


--
-- Name: conta_despacho_marcar(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_despacho_marcar(p_account uuid, p_es boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n int; v_desde timestamptz;
begin
  if p_account is null or not public.current_user_is_admin_of(p_account) then
    raise exception 'Solo la administración de la cuenta dice si es una asesoría.' using errcode = '42501';
  end if;
  if p_es is null then raise exception 'Di si la cuenta es una asesoría o no.' using errcode = '22023'; end if;
  select count(*) into v_n from public.conta_despacho_clientes(p_account);
  if not p_es and v_n > 0 then
    -- Quitarla escondería a clientes que siguen dando permiso (regla 7): lo retiran ellos.
    raise exception 'Llevas los impuestos de % cliente%: mientras te den permiso, la cuenta sigue siendo una asesoría.',
      v_n, case when v_n = 1 then '' else 's' end using errcode = '22023';
  end if;
  update public.accounts
     set tax_advisor_since = case when p_es then coalesce(tax_advisor_since, now()) end,
         tax_advisor_by = case when p_es then coalesce(tax_advisor_by, auth.uid()) end
   where id = p_account
  returning tax_advisor_since into v_desde;
  return jsonb_build_object('ok', true, 'asesoria', p_es, 'desde', v_desde,
    'mensaje', case when p_es
      then 'Hecho: la cuenta es una asesoría. En Impuestos verás «Impuestos de tus clientes»' ||
           case when v_n = 0 then ', vacía hasta que un cliente te invite.' else format(', con tus %s cliente%s.', v_n, case when v_n = 1 then '' else 's' end) end
      else 'Hecho: la cuenta ya no es una asesoría.' end);
end $$;


--
-- Name: conta_despacho_responsable_poner(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_despacho_responsable_poner(p_account uuid, p_company uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_empresa text; v_nombre text; v_quien text;
begin
  if p_account is null or not public.current_user_is_admin_or_manager_of(p_account) then
    raise exception 'Solo la administración o una encargada de la asesoría reparte los clientes.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.conta_despacho_clientes(p_account) c where c = p_company) then
    raise exception 'Esa empresa no te ha dado permiso para llevar sus impuestos.' using errcode = '42501';
  end if;
  select coalesce(nullif(btrim(trade_name), ''), legal_name) into v_empresa from public.company where id = p_company;
  v_quien := public.conta_impuesto_nombre_de_en(auth.uid(), p_account);
  if p_user is null then
    delete from public.tax_client_assignee where account_id = p_account and company_id = p_company;
    return jsonb_build_object('ok', true, 'mensaje', format('%s se queda sin responsable.', v_empresa));
  end if;
  if not exists (select 1 from public.user_profiles where user_id = p_user and account_id = p_account and active) then
    raise exception 'Esa persona no es de tu asesoría.' using errcode = '22023';
  end if;
  v_nombre := public.conta_impuesto_nombre_de_en(p_user, p_account);
  insert into public.tax_client_assignee (account_id, company_id, user_id, assigned_by, assigned_by_name)
  values (p_account, p_company, p_user, auth.uid(), v_quien)
  on conflict (account_id, company_id) do update
    set user_id = excluded.user_id, assigned_by = excluded.assigned_by, assigned_by_name = excluded.assigned_by_name, assigned_at = now();
  return jsonb_build_object('ok', true, 'usuario', p_user, 'nombre', v_nombre,
    'mensaje', format('%s lleva ahora %s.', v_nombre, v_empresa));
end $$;


--
-- Name: conta_despacho_soy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_despacho_soy(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.accounts;
begin
  if p_account is null or not public.belongs_to_account(p_account) then
    raise exception 'No eres de esta cuenta.' using errcode = '42501';
  end if;
  select * into a from public.accounts where id = p_account;
  return jsonb_build_object(
    'asesoria', a.tax_advisor_since is not null,
    'desde', a.tax_advisor_since,
    'nombre', coalesce(nullif(btrim(a.legal_name), ''), a.name),
    'correo_respuesta', nullif(btrim(coalesce(a.billing_email, '')), ''),
    'clientes', (select count(*) from public.conta_despacho_clientes(p_account)),
    'puede_gestionar', public.current_user_is_admin_or_manager_of(p_account),
    'puede_marcar', public.current_user_is_admin_of(p_account));
end $$;


--
-- Name: conta_despacho_trimestre(uuid, integer, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_despacho_trimestre(p_account uuid, p_year integer, p_period text, p_hoy date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_hoy date := coalesce(p_hoy, (now() at time zone 'Europe/Madrid')::date);
  v_q int; v_fin date; v_ven date; v_202 text;
  v_clientes jsonb; v_resumen jsonb; v_plazos jsonb; v_yo uuid := auth.uid();
begin
  if p_period is null or p_period !~ '^[1-4]T$' or p_year is null or p_year not between 2000 and 2100 then
    raise exception 'Elige un trimestre: 1T, 2T, 3T o 4T de un año.' using errcode = '22023';
  end if;
  if p_account is null or not public.belongs_to_account(p_account) then
    raise exception 'No eres de esta asesoría.' using errcode = '42501';
  end if;
  v_q := left(p_period, 1)::int;
  v_fin := (make_date(p_year, v_q * 3, 1) + interval '1 month')::date - 1;
  v_ven := (v_fin + interval '3 months')::date;
  v_202 := case v_q when 1 then '1P' when 3 then '2P' when 4 then '3P' end;

  select jsonb_build_object('presentacion', x.presentacion, 'domiciliacion', x.domiciliacion) into v_plazos
    from public.conta_impuesto_plazo_si_hay('303', 'quarterly', p_year, p_period) x;

  with cli as (
    select c.id, c.account_id, coalesce(nullif(btrim(c.trade_name), ''), c.legal_name) as nombre, c.legal_name, c.entity_kind, c.is_hospitality,
           tp.vat_period, tp.sii, tp.vat_prorata, tp.vat_prorata_pct, t.advisor_basis, t.consented_at, t.consented_by_name,
           coalesce(t.certificate_id,
                    (select k.id from public.tax_certificate k
                      where k.owner_account_id = p_account and k.status = 'active' and k.valid_to > now()
                      order by k.valid_to desc limit 1)) as cert
      from public.company_tax_presenter t
      join public.company c on c.id = t.company_id
      left join public.company_tax_profile tp on tp.company_id = c.id
     where t.advisor_account_id = p_account and t.mode = 'advisor' and t.consented_at is not null and t.revoked_at is null
  ),
  per as (
    select o.company_id, o.form_code, o.cadence, o.payment_mode, x.ej, x.per
      from public.tax_obligation o
      join cli on cli.id = o.company_id
     cross join lateral (
       select p_year, p_period where o.cadence = 'quarterly'
       union all select p_year, lpad(m::text, 2, '0') from generate_series(v_q * 3 - 2, v_q * 3) m where o.cadence = 'monthly'
       union all select p_year, v_202 where o.cadence = 'instalments_202' and v_202 is not null
       union all select y, '0A' from generate_series(p_year - 1, p_year) y where o.cadence = 'annual'
     ) x(ej, per)
     where o.valid_to is null and o.active
  ),
  dec as (
    select r.* from public.tax_return r join cli on cli.id = r.company_id
     where r.sequence = 1 and r.fiscal_year between p_year - 1 and p_year
  ),
  base as (
    select coalesce(per.company_id, d.company_id) as company_id, coalesce(per.form_code, d.form_code) as modelo,
           coalesce(per.cadence, d.cadence) as cadencia, coalesce(per.ej, d.fiscal_year) as ej, coalesce(per.per, d.period) as periodo,
           per.payment_mode as pago_obl, d.id as rid, d.status, d.result_kind, d.amount, d.payment_mode, d.due_date,
           d.due_date_direct_debit, d.filed_at, d.filed_via
      from per full join dec d
        on d.company_id = per.company_id and d.form_code = per.form_code and d.fiscal_year = per.ej and d.period = per.per
  ),
  f0 as (
    select b.*, coalesce(b.due_date, pl.presentacion) as plazo, coalesce(b.due_date_direct_debit, pl.domiciliacion) as plazo_dom,
           coalesce(coalesce(b.payment_mode, nullif(b.pago_obl, 'none')) = 'direct_debit', false) as domicilia,
           coalesce(b.status, 'pending') in ('filed', 'booked', 'paid', 'offset', 'refunded') as presentado,
           coalesce(b.status, 'pending') = 'not_required' as no_hace_falta,
           (select count(*) from public.tax_return_check k where k.tax_return_id = b.rid and k.result = 'error') as errores,
           (select count(*) from public.tax_return_check k where k.tax_return_id = b.rid and k.result = 'warning' and k.accepted_at is null) as avisos,
           (select k.title from public.tax_return_check k where k.tax_return_id = b.rid and k.result in ('error', 'warning') and k.accepted_at is null
             order by (k.result = 'error') desc, k.checked_at limit 1) as aviso
      from base b
      left join lateral public.conta_impuesto_plazo_si_hay(b.modelo, b.cadencia, b.ej, b.periodo) pl on true
  ),
  f as (
    select f0.*,
           case when f0.domicilia and f0.plazo_dom is not null then f0.plazo_dom else f0.plazo end as plazo_suyo,
           case
             when f0.no_hace_falta then 'no_hace_falta'
             when f0.presentado then 'presentado'
             when f0.errores > 0 then 'avisos'
             when f0.status = 'reviewed' then 'listo'
             when f0.status = 'draft' and f0.avisos > 0 then 'avisos'
             when f0.status = 'draft' then 'revisar'
             else 'por_calcular' end as estado
      from f0
     where (f0.cadencia = 'quarterly' and f0.ej = p_year and f0.periodo = p_period)
        or (f0.cadencia = 'monthly' and f0.ej = p_year and f0.periodo in (select lpad(m::text, 2, '0') from generate_series(v_q * 3 - 2, v_q * 3) m))
        or (f0.cadencia = 'instalments_202' and f0.ej = p_year and f0.periodo = v_202)
        or (f0.cadencia = 'annual' and f0.plazo > v_fin and f0.plazo <= v_ven)
  ),
  fx as (
    select f.*,
           f.plazo_suyo - v_hoy as dias,
           (not f.presentado and not f.no_hace_falta and f.plazo_suyo is not null and f.plazo_suyo - v_hoy <= 2) as urgente
      from f
  ),
  porcli as (
    select cli.*,
           k.subject_name as cert_titular, k.valid_to as cert_caduca, k.status as cert_status,
           case
             when cli.cert is null then 'sin_certificado'
             when k.status = 'removed' then 'quitado'
             when k.valid_to <= now() then 'caducado'
             when not public.conta_cert_puede_usar(v_yo, k.id) then 'sin_permiso'
             when k.valid_to <= now() + interval '30 days' then 'caduca'
             else 'ok' end as cert_estado,
           a.user_id as resp_id,
           (select coalesce(jsonb_agg(jsonb_build_object(
                     'declaracion', fx.rid, 'modelo', fx.modelo, 'nombre', tf.name, 'cadencia', fx.cadencia,
                     'ejercicio', fx.ej, 'periodo', fx.periodo, 'estado', fx.estado,
                     'estado_texto', public.conta_impuesto_estado_texto(coalesce(fx.status, 'pending')),
                     'resultado', fx.result_kind, 'importe', fx.amount,
                     'plazo', fx.plazo, 'plazo_domiciliacion', fx.plazo_dom, 'plazo_suyo', fx.plazo_suyo,
                     'domicilia', fx.domicilia, 'dias', fx.dias, 'urgente', fx.urgente, 'atrasado', fx.dias < 0 and fx.urgente,
                     'errores', fx.errores, 'avisos', fx.avisos, 'aviso', fx.aviso,
                     'presentada', fx.filed_at, 'por', fx.filed_via,
                     'desde_sumied', fx.modelo = '303')
                   order by (fx.modelo <> '303'), fx.modelo, fx.ej, fx.periodo), '[]')
              from fx left join public.tax_form tf on tf.code = fx.modelo where fx.company_id = cli.id) as modelos,
           (select count(*) from fx where fx.company_id = cli.id and not fx.no_hace_falta) as n_modelos,
           (select count(*) from fx where fx.company_id = cli.id and fx.presentado) as n_presentados,
           (select count(*) from fx where fx.company_id = cli.id and fx.estado = 'listo') as n_listos,
           (select count(*) from fx where fx.company_id = cli.id and fx.estado = 'listo' and fx.modelo = '303') as n_listos_303,
           (select count(*) from fx where fx.company_id = cli.id and fx.estado = 'avisos') as n_avisos,
           (select count(*) from fx where fx.company_id = cli.id and fx.urgente and fx.estado <> 'listo') as n_urgentes,
           -- A ingresar: lo que falta por presentar. A compensar y a devolver: lo del trimestre, presentado o no.
           (select sum(fx.amount) from fx where fx.company_id = cli.id and fx.result_kind = 'to_pay' and not fx.no_hace_falta and not fx.presentado) as a_ingresar,
           (select sum(fx.amount) from fx where fx.company_id = cli.id and fx.result_kind = 'to_offset') as a_compensar,
           (select sum(fx.amount) from fx where fx.company_id = cli.id and fx.result_kind = 'to_refund') as a_devolver,
           (select bool_or(fx.domicilia) from fx where fx.company_id = cli.id) as domicilia,
           -- Lo que vence: su aviso si lo tiene («Faltan 3 facturas por correo · vence el 15/10»), si no, revisarlo.
           (select coalesce(fx.aviso, format('Revisar el %s', fx.modelo))
                   || case when fx.dias < 0 then ': venció el ' else case when fx.aviso is null then ': vence el ' else ' · vence el ' end end
                   || to_char(fx.plazo_suyo, 'DD/MM')
              from fx where fx.company_id = cli.id and fx.urgente and fx.estado <> 'listo' order by fx.plazo_suyo, fx.modelo limit 1) as u_txt,
           (select format('Corregir el %s: %s', fx.modelo, coalesce(fx.aviso, 'tiene errores'))
              from fx where fx.company_id = cli.id and fx.errores > 0 order by fx.plazo_suyo nulls last, fx.modelo limit 1) as e_txt,
           (select coalesce(fx.aviso, format('Mirar los avisos del %s', fx.modelo))
              from fx where fx.company_id = cli.id and fx.estado = 'avisos' order by fx.plazo_suyo nulls last, fx.modelo limit 1) as w_txt,
           (select fx.modelo from fx where fx.company_id = cli.id and fx.estado = 'listo' order by fx.plazo_suyo nulls last, fx.modelo limit 1) as l_modelo,
           (select fx.modelo from fx where fx.company_id = cli.id and fx.estado = 'revisar' order by fx.plazo_suyo nulls last, fx.modelo limit 1) as r_modelo,
           (select fx.modelo from fx where fx.company_id = cli.id and fx.estado = 'por_calcular' order by fx.plazo_suyo nulls last, fx.modelo limit 1) as p_modelo
      from cli
      left join public.tax_certificate k on k.id = cli.cert
      left join public.tax_client_assignee a on a.account_id = p_account and a.company_id = cli.id
  ),
  conpaso as (
    select pc.*,
           (pc.n_modelos > pc.n_presentados) as pendiente,
           case
             when pc.n_modelos > pc.n_presentados and pc.cert_estado = 'sin_certificado' then 'Falta el certificado para presentar'
             when pc.n_modelos > pc.n_presentados and pc.cert_estado in ('caducado', 'quitado') then 'Renovar el certificado: ya no vale'
             when pc.n_modelos > pc.n_presentados and pc.cert_estado = 'sin_permiso' then 'Pedir permiso para usar el certificado'
             when pc.u_txt is not null then pc.u_txt
             when pc.e_txt is not null then pc.e_txt
             when pc.w_txt is not null then pc.w_txt
             when pc.n_listos = 1 then format('Presentar el %s', pc.l_modelo)
             when pc.n_listos > 1 then format('Presentar %s modelos', pc.n_listos)
             when pc.r_modelo is not null then format('Revisar el %s', pc.r_modelo)
             when pc.p_modelo is not null then format('Preparar el %s', pc.p_modelo)
             when pc.cert_estado = 'caduca' then format('Renovar el certificado: caduca el %s', to_char(pc.cert_caduca at time zone 'Europe/Madrid', 'DD/MM'))
             when pc.n_modelos = 0 then 'Sin modelos este trimestre'
             else 'Todo presentado' end as siguiente_paso,
           case
             when pc.u_txt is not null then 0
             when pc.n_modelos > pc.n_presentados and pc.cert_estado in ('sin_certificado', 'caducado', 'quitado', 'sin_permiso') then 1
             when pc.n_avisos > 0 then 2
             when pc.n_listos > 0 then 3
             when pc.n_modelos > pc.n_presentados then 4
             when pc.cert_estado = 'caduca' then 5
             else 6 end as orden
      from porcli pc
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'empresa', c.id, 'nombre', c.nombre, 'razon_social', c.legal_name,
           'tipo', c.entity_kind, 'hosteleria', c.is_hospitality, 'periodo_iva', c.vat_period, 'sii', coalesce(c.sii, false),
           'prorrata', case when c.vat_prorata then c.vat_prorata_pct end, 'base', c.advisor_basis,
           'consentimiento', jsonb_build_object('quien', c.consented_by_name, 'cuando', c.consented_at),
           'domicilia', coalesce(c.domicilia, false),
           'modelos', c.modelos,
           'a_ingresar', c.a_ingresar, 'a_compensar', c.a_compensar, 'a_devolver', c.a_devolver,
           'responsable', case when c.resp_id is null then null else jsonb_build_object(
               'usuario', c.resp_id, 'nombre', public.conta_impuesto_nombre_de_en(c.resp_id, p_account),
               'activa', exists (select 1 from public.user_profiles u where u.user_id = c.resp_id and u.account_id = p_account and u.active)) end,
           'certificado', jsonb_build_object('id', c.cert, 'estado', c.cert_estado, 'titular', c.cert_titular, 'caduca', c.cert_caduca,
               'dias', case when c.cert_caduca is null then null else ((c.cert_caduca at time zone 'Europe/Madrid')::date - (now() at time zone 'Europe/Madrid')::date) end),
           'listos', c.n_listos, 'listos_303', c.n_listos_303, 'con_avisos', c.n_avisos > 0, 'urgentes', c.n_urgentes,
           'pendiente', c.pendiente, 'siguiente_paso', c.siguiente_paso, 'orden', c.orden)
         order by c.orden, c.nombre), '[]')
    into v_clientes
    from conpaso c;

  select jsonb_build_object(
           'clientes', jsonb_array_length(v_clientes),
           'modelos', coalesce(sum((select count(*) from jsonb_array_elements(x->'modelos') m where m->>'estado' <> 'no_hace_falta')), 0),
           'presentados', coalesce(sum((select count(*) from jsonb_array_elements(x->'modelos') m where m->>'estado' = 'presentado')), 0),
           'listos', coalesce(sum((select count(*) from jsonb_array_elements(x->'modelos') m where m->>'estado' = 'listo')), 0),
           'para_revisar', coalesce(sum((select count(*) from jsonb_array_elements(x->'modelos') m where m->>'estado' in ('revisar', 'avisos', 'por_calcular'))), 0),
           'vencen', coalesce(sum((select count(*) from jsonb_array_elements(x->'modelos') m
                                    where m->>'estado' in ('revisar', 'avisos', 'por_calcular') and (m->>'urgente')::boolean and not (m->>'atrasado')::boolean)), 0),
           'atrasados', coalesce(sum((select count(*) from jsonb_array_elements(x->'modelos') m
                                       where m->>'estado' in ('revisar', 'avisos', 'por_calcular', 'listo') and (m->>'atrasado')::boolean)), 0),
           'filtros', jsonb_build_object(
             'con_avisos', count(*) filter (where (x->>'con_avisos')::boolean),
             'listos', count(*) filter (where (x->>'listos')::int > 0),
             'sin_certificado', count(*) filter (where x->'certificado'->>'estado' in ('sin_certificado', 'caducado', 'quitado', 'sin_permiso')),
             'domiciliados', count(*) filter (where (x->>'domicilia')::boolean)))
    into v_resumen
    from jsonb_array_elements(v_clientes) x;

  return jsonb_build_object(
    'hoy', v_hoy, 'ejercicio', p_year, 'periodo', p_period, 'plazos', v_plazos,
    'asesoria', (select coalesce(nullif(btrim(legal_name), ''), name) from public.accounts where id = p_account),
    'es_asesoria', (select tax_advisor_since is not null from public.accounts where id = p_account),
    'puede_gestionar', public.current_user_is_admin_or_manager_of(p_account),
    'resumen', v_resumen, 'clientes', v_clientes);
end $_$;


--
-- Name: FUNCTION conta_despacho_trimestre(p_account uuid, p_year integer, p_period text, p_hoy date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_despacho_trimestre(p_account uuid, p_year integer, p_period text, p_hoy date) IS 'P01. Lo que pinta «Impuestos de tus clientes»: las cifras, los filtros y cada cliente con permiso vivo, con sus modelos del trimestre, importes, certificado, responsable y siguiente paso. No escribe nada.';


--
-- Name: conta_devoluciones_del_dia(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_devoluciones_del_dia(p_company uuid, p_location uuid, p_dia date) RETURNS TABLE(pedido_id uuid, codigo text, canal_id uuid, marca_id uuid, propia boolean, importe numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select o.sale_id, o.platform_order_code, o.channel_id, o.brand_id, coalesce(b.ownership_type, 'own') = 'own', abs(o.incidents_refund)
    from public.channel_settlement_order o
    join public.company c on c.id = p_company and c.account_id = o.account_id
    left join public.channel_settlement cs on cs.id = o.settlement_id
    left join public.brand b on b.id = o.brand_id
   where o.location_id = p_location and coalesce(o.incidents_refund, 0) <> 0
     and coalesce(cs.settlement_date, o.order_date) = p_dia
$$;


--
-- Name: FUNCTION conta_devoluciones_del_dia(p_company uuid, p_location uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_devoluciones_del_dia(p_company uuid, p_location uuid, p_dia date) IS 'C04. Lo que la plataforma devolvió a clientes y comunica en la liquidación de ese día, pedido a pedido (entra en el resumen de ese día, art. 80.Dos LIVA).';


--
-- Name: conta_dia_abierto(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_dia_abierto(p_company uuid, p_dia date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select p_dia is not null and public.conta_primer_dia_abierto(p_company, p_dia) = p_dia
$$;


--
-- Name: FUNCTION conta_dia_abierto(p_company uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_dia_abierto(p_company uuid, p_dia date) IS 'S01 · PR 3: el día está en un ejercicio abierto, fuera de lo traído y con su mes sin cerrar (diaAbierto del navegador).';


--
-- Name: conta_dias_por_asentar(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_dias_por_asentar(p_company uuid, p_desde date, p_hasta date) RETURNS TABLE(location_id uuid, dia date, pedidos bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select s.location_id, (s.sold_at at time zone 'Europe/Madrid')::date, count(*)
    from public.sale s
    join public.company c on c.id = p_company and c.account_id = s.account_id
    left join public.brand b on b.id = s.brand_id
   where s.is_active and s.status = 'closed' and coalesce(b.ownership_type, 'own') = 'own' and s.location_id is not null
     and s.sold_at >= (p_desde::timestamp at time zone 'Europe/Madrid') and s.sold_at < ((p_hasta + 1)::timestamp at time zone 'Europe/Madrid')
     -- Cierre del día: solo días que ya han llegado a su hora de cierre.
     and s.sold_at < (select public.conta_cerrado_hasta(p_company))
     -- V01: lo quitado de su cierre o pasado a otro día no cuenta en el suyo.
     and not exists (select 1 from public.conta_cierre_ajuste a
                      where a.company_id = p_company and a.sale_id = s.id and (a.quitado or a.dia_destino is not null))
     -- El día entero, asentado a la antigua (unit_key nulo)…
     and not exists (select 1 from public.sales_day_summary d join public.journal_entry e on e.id = d.entry_id
                      where d.company_id = p_company and d.location_id = s.location_id and d.sales_day = (s.sold_at at time zone 'Europe/Madrid')::date
                        and d.unit_key is null and e.status in ('propuesto', 'borrador', 'validado'))
     -- …o la unidad de este pedido, con la regla por plataforma (C04b R5).
     and not exists (select 1 from public.sales_day_summary d join public.journal_entry e on e.id = d.entry_id
                      where d.company_id = p_company and d.location_id = s.location_id and d.sales_day = (s.sold_at at time zone 'Europe/Madrid')::date
                        and d.unit_key = public.conta_unidad_ventas(p_company, s.channel_id, s.brand_id)
                        and e.status in ('propuesto', 'borrador', 'validado'))
     and not exists (select 1 from public.journal_dismissal x
                      where x.company_id = p_company and x.source_type = 'sales_day'
                        and x.source_key in (s.location_id || ':' || (s.sold_at at time zone 'Europe/Madrid')::date,
                                             s.location_id || ':' || (s.sold_at at time zone 'Europe/Madrid')::date || ':' || public.conta_unidad_ventas(p_company, s.channel_id, s.brand_id)))
   group by 1, 2
   order by 2, 1
$$;


--
-- Name: conta_diez_adjunto_a_mano(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_adjunto_a_mano(p_entry uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s public.external_send;
begin
  select * into v_s from public.external_send
   where entry_id = p_entry and status in ('enviado', 'enlazado') for update;
  if v_s.id is null or not public.belongs_to_account(v_s.account_id) then
    raise exception 'Ese asiento no está en Diez.' using errcode = 'P0002';
  end if;
  if not public.current_user_is_admin_or_manager_of(v_s.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta marca un documento como adjunto en Diez.' using errcode = '42501';
  end if;
  if v_s.document_status = 'adjunto' then
    return jsonb_build_object('serie', v_s.ext_series, 'numero', v_s.ext_number, 'ya_estaba', true,
      'via', v_s.document_attached_via, 'quien', v_s.document_attached_by_name, 'cuando', v_s.document_attached_at);
  end if;
  if v_s.document_status is distinct from 'pendiente_diez' then
    raise exception 'El documento de este asiento no está pendiente de adjuntar en Diez (está %).', coalesce(v_s.document_status, 'sin estado') using errcode = '23514';
  end if;
  update public.external_send
     set document_status = 'adjunto', document_error = null, document_attached_at = now(),
         document_attached_via = 'a_mano', document_attached_by = auth.uid(),
         document_attached_by_name = nullif(trim(coalesce(p_quien_nombre, '')), ''), updated_at = now()
   where id = v_s.id;
  return jsonb_build_object('serie', v_s.ext_series, 'numero', v_s.ext_number, 'ya_estaba', false, 'via', 'a_mano');
end $$;


--
-- Name: FUNCTION conta_diez_adjunto_a_mano(p_entry uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_adjunto_a_mano(p_entry uuid, p_quien_nombre text) IS 'C06b R7 · «Ya está adjunto»: una persona ha adjuntado en Diez el PDF de una factura que Folvy envió sin él. Solo administrador o encargado; solo desde pendiente_diez; queda quién y cuándo.';


--
-- Name: conta_diez_base_apuntar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_base_apuntar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.conta_diez_base_registro (company_id, account_id, accion, antes, despues, motivo, por)
    values (new.company_id, new.account_id, 'alta', null, new.nombre_bd, new.motivo, new.puesto_por);
  elsif tg_op = 'UPDATE' then
    insert into public.conta_diez_base_registro (company_id, account_id, accion, antes, despues, motivo, por)
    values (new.company_id, new.account_id, 'cambio', old.nombre_bd, new.nombre_bd, new.motivo, new.puesto_por);
  else
    insert into public.conta_diez_base_registro (company_id, account_id, accion, antes, despues, motivo, por)
    values (old.company_id, old.account_id, 'baja', old.nombre_bd, null, null, coalesce(current_setting('request.jwt.claim.sub', true), current_user));
  end if;
  return null;
end;
$$;


--
-- Name: conta_diez_base_guarda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_base_guarda() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from public.company c where c.id = new.company_id and c.account_id = new.account_id) then
    raise exception 'conta_diez_base: la empresa % no es de la cuenta %.', new.company_id, new.account_id;
  end if;
  if new.account_id = '00000000-0000-0000-0000-000000000001' then
    raise exception 'conta_diez_base: Folvy Interno no se toca.';
  end if;
  new.nombre_bd := upper(btrim(new.nombre_bd));
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: conta_diez_base_poner(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_base_poner(p_company uuid, p_nombre_bd text, p_motivo text, p_por text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_cuenta uuid;
  v_bd text := upper(btrim(coalesce(p_nombre_bd, '')));
  v_antes text;
begin
  if v_bd = 'C0001' then raise exception 'La base C0001 no se toca nunca.'; end if;
  if v_bd !~ '^C[0-9]{4}$' then raise exception 'Base de Diez no válida: «%» (es C y cuatro cifras).', p_nombre_bd; end if;
  if btrim(coalesce(p_motivo, '')) = '' or btrim(coalesce(p_por, '')) = '' then raise exception 'Hace falta el motivo y quién lo pone.'; end if;
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'La empresa % no existe.', p_company; end if;
  select nombre_bd into v_antes from public.conta_diez_base where company_id = p_company;
  if v_antes = v_bd then
    return jsonb_build_object('empresa', p_company, 'base', v_bd, 'cambia', false);
  end if;
  if v_antes is null then
    insert into public.conta_diez_base (company_id, account_id, nombre_bd, motivo, puesto_por)
    values (p_company, v_cuenta, v_bd, p_motivo, p_por);
  else
    update public.conta_diez_base set nombre_bd = v_bd, motivo = p_motivo, puesto_por = p_por where company_id = p_company;
  end if;
  return jsonb_build_object('empresa', p_company, 'base', v_bd, 'antes', v_antes, 'cambia', true);
end;
$_$;


--
-- Name: conta_diez_base_recordar(uuid, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_base_recordar(p_company uuid, p_desde text, p_hasta text, p_corte date) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update public.conta_diez_base set ultimo_desde = p_desde, ultimo_hasta = p_hasta, ultimo_corte = p_corte
   where company_id = p_company;
$$;


--
-- Name: conta_diez_cerrar_ejercicio(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_cerrar_ejercicio(p_company uuid, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_y public.fiscal_year; v_n int; v_abiertos int;
begin
  select * into v_y from public.fiscal_year where company_id = p_company and code = p_code for update;
  if v_y.id is null then raise exception 'El ejercicio % no existe.', p_code using errcode = 'P0002'; end if;
  if v_y.origin <> 'migrated' then
    raise exception 'El ejercicio % no es traído entero de Diez: se cierra con el cierre de Folvy.', p_code using errcode = '23514';
  end if;
  if v_y.status = 'closed' then return jsonb_build_object('ejercicio', p_code, 'yaCerrado', true); end if;
  select count(*) filter (where external_program = 'diez' and status = 'validado'),
         count(*) filter (where status in ('propuesto', 'borrador'))
    into v_n, v_abiertos from public.journal_entry where fiscal_year_id = v_y.id;
  if v_n = 0 then raise exception 'El ejercicio % no tiene nada traído: no se cierra vacío.', p_code using errcode = '23514'; end if;
  if v_abiertos > 0 then
    raise exception 'El ejercicio % tiene % asiento(s) sin validar.', p_code, v_abiertos using errcode = '23514';
  end if;
  update public.fiscal_year set status = 'closed', closed_at = now() where id = v_y.id;
  return jsonb_build_object('ejercicio', p_code, 'cerrado', true, 'asientos', v_n);
end $$;


--
-- Name: FUNCTION conta_diez_cerrar_ejercicio(p_company uuid, p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_cerrar_ejercicio(p_company uuid, p_code text) IS 'C04b: cierra un ejercicio traído entero de Diez, con lo traído validado y nada pendiente dentro.';


--
-- Name: conta_diez_despertar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_despertar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secreto text;
begin
  if not exists (select 1 from public.conta_diez_por_enviar(1)) then return; end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  if v_secreto is null then
    raise exception 'Falta cron_secret en el Vault: no se puede despertar a conta-diez-cola.' using errcode = '55000';
  end if;
  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/conta-diez-cola',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := '{}'::jsonb, timeout_milliseconds := 150000);
end $$;


--
-- Name: FUNCTION conta_diez_despertar(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_despertar() IS 'C07 · Cada minuto (cron conta-diez-despertar, solo en producción): si hay algo que mandar a Diez, llama a conta-diez-cola. Si falta el secreto, falla (cron lo apunta como failed), no calla.';


--
-- Name: conta_diez_ejercicio(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_ejercicio(p_company uuid, p_code text, p_starts date, p_ends date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_y public.fiscal_year; v_cuenta uuid; v_prev uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'Esa empresa no existe.' using errcode = 'P0002'; end if;
  select * into v_y from public.fiscal_year where company_id = p_company and code = p_code;
  if v_y.id is not null then
    if v_y.origin = 'folvy' then
      raise exception 'El ejercicio % ya existe y es de Folvy: no se le trae nada de Diez encima.', p_code using errcode = '23514';
    end if;
    if v_y.starts_on <> p_starts or v_y.ends_on <> p_ends then
      raise exception 'El ejercicio % ya existe con otras fechas (% – %).', p_code, v_y.starts_on, v_y.ends_on using errcode = '23514';
    end if;
    return v_y.id;
  end if;
  select id into v_prev from public.fiscal_year where company_id = p_company and ends_on = p_starts - 1;
  insert into public.fiscal_year (account_id, company_id, code, starts_on, ends_on, previous_year_id, status, origin, origin_program, imported_until)
  values (v_cuenta, p_company, p_code, p_starts, p_ends, v_prev, 'open', 'migrated', 'diez', p_ends)
  returning id into v_prev;
  -- El siguiente, si ya existía, cuelga de este.
  update public.fiscal_year set previous_year_id = v_prev
   where company_id = p_company and starts_on = p_ends + 1 and previous_year_id is null;
  return v_prev;
end $$;


--
-- Name: FUNCTION conta_diez_ejercicio(p_company uuid, p_code text, p_starts date, p_ends date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_ejercicio(p_company uuid, p_code text, p_starts date, p_ends date) IS 'C04b: crea (o devuelve) un ejercicio TRAÍDO de Diez, abierto hasta terminar la traída. Uno de Folvy no se toca.';


--
-- Name: conta_diez_envio_poner(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_envio_poner(p_company uuid, p_enviar boolean, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_c public.company;
  v_z public.conta_diez_envio_empresa;
  v_quien text;
  v_salen integer;
  v_desde date;
begin
  select * into v_c from public.company where id = p_company;
  if v_c.id is null or not public.belongs_to_account(v_c.account_id) then
    raise exception 'Esa empresa no está.' using errcode = 'P0002';
  end if;
  if not public.current_user_is_admin_of(v_c.account_id) then
    raise exception 'Solo un administrador de la cuenta enciende o apaga el envío a Diez.' using errcode = '42501';
  end if;
  if p_enviar is null then raise exception 'Hay que decir si se enciende o se apaga.' using errcode = '22023'; end if;
  if p_enviar and not exists (
    select 1 from public.account_connector ac join public.connector k on k.id = ac.connector_id
     where ac.account_id = v_c.account_id and ac.company_id = v_c.id and ac.scope = 'company' and k.code = 'diez' and ac.status = 'connected') then
    raise exception 'Esta empresa no está conectada con Diez: primero, la conexión.' using errcode = '23514';
  end if;
  v_quien := nullif(trim(coalesce(p_quien_nombre, public.conta_nombre_actor(), '')), '');
  select * into v_z from public.conta_diez_envio_empresa where company_id = v_c.id for update;
  if v_z.company_id is null then
    insert into public.conta_diez_envio_empresa (company_id, account_id, enviar, desde, cambiado_por, cambiado_por_nombre)
    values (v_c.id, v_c.account_id, p_enviar, current_date, auth.uid(), v_quien)
    returning * into v_z;
  elsif v_z.enviar is distinct from p_enviar then
    update public.conta_diez_envio_empresa
       set enviar = p_enviar, cambiado_por = auth.uid(), cambiado_por_nombre = v_quien, cambiado_en = now()
     where company_id = v_c.id
    returning * into v_z;
  end if;
  v_desde := v_z.desde;
  -- Lo validado desde «desde» que no está en Diez: lo que sale ahora (o lo que se queda sin salir).
  select count(*) into v_salen
    from public.journal_entry e
   where e.company_id = v_c.id and e.account_id = v_c.account_id and e.status = 'validado' and e.entry_date >= v_desde
     and e.source_type not in ('migrated', 'opening', 'closing', 'template')
     and not exists (select 1 from public.external_send s where s.entry_id = e.id and s.account_id = e.account_id and s.status in ('enviado', 'enlazado'));
  return jsonb_build_object('enviar', v_z.enviar, 'desde', v_desde, 'sin_enviar', v_salen,
    'texto', case when v_z.enviar
      then format('Encendido: todo lo que se valide sale solo a Diez. %s', case v_salen when 0 then 'No hay nada validado pendiente.' when 1 then '1 asiento validado desde el ' || to_char(v_desde, 'DD/MM/YYYY') || ' sale ahora.' else v_salen || ' asientos validados desde el ' || to_char(v_desde, 'DD/MM/YYYY') || ' salen ahora.' end)
      else format('Apagado: no se envía nada a Diez.%s', case when v_salen > 0 then format(' %s %s sin enviar se quedan aquí, validados.', v_salen, case v_salen when 1 then 'asiento' else 'asientos' end) else '' end) end);
end $$;


--
-- Name: FUNCTION conta_diez_envio_poner(p_company uuid, p_enviar boolean, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_envio_poner(p_company uuid, p_enviar boolean, p_quien_nombre text) IS 'C07 · Enciende o apaga «Enviar a Diez» en una empresa. Solo un administrador; para encender, la empresa tiene que estar conectada con Diez. La primera vez, «desde» es hoy. Devuelve qué ha hecho y cuántos asientos validados quedan sin enviar.';


--
-- Name: conta_diez_historico_traido(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_historico_traido(p_company uuid, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_y public.fiscal_year; v_n int; v_max jsonb;
begin
  select * into v_y from public.fiscal_year where company_id = p_company and code = p_code for update;
  if v_y.id is null then raise exception 'El ejercicio % no existe.', p_code using errcode = 'P0002'; end if;
  if v_y.origin not in ('mixed', 'migrated') or v_y.origin_program is distinct from 'diez' then
    raise exception 'El ejercicio % no tiene nada traído de Diez.', p_code using errcode = '23514';
  end if;
  select count(*) into v_n from public.journal_entry where fiscal_year_id = v_y.id and external_program = 'diez' and status = 'validado';
  if v_n = 0 then raise exception 'El ejercicio % no tiene nada traído: no se marca.', p_code using errcode = '23514'; end if;
  if v_y.history_imported_at is null then
    update public.fiscal_year set history_imported_at = now() where id = v_y.id;
  end if;
  select jsonb_object_agg(series::text, n) into v_max
    from (select series, max(number) n from public.journal_entry where fiscal_year_id = v_y.id and number is not null group by series) s;
  return jsonb_build_object('ejercicio', p_code, 'traidos', v_n, 'ultimoPorSerie', v_max);
end $$;


--
-- Name: FUNCTION conta_diez_historico_traido(p_company uuid, p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_historico_traido(p_company uuid, p_code text) IS 'C04b: marca traído el histórico de Diez de un ejercicio. Desde ahí Folvy valida y numera detrás del último número traído de cada serie.';


--
-- Name: conta_diez_importar(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_importar(p_company uuid, p_run uuid, p_asientos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_cuenta uuid; a jsonb; l jsonb; v_y public.fiscal_year; v_e public.journal_entry;
  v_clave text; v_serie int; v_numero int; v_fecha date; v_ej text; v_huella text;
  v_id uuid; v_ca uuid; v_faltan text[]; v_debe numeric; v_haber numeric; v_n int;
  v_seq bigint; v_prev text; v_hash text; v_concepto text;
  n_traidos int := 0; n_estaban int := 0; distintos jsonb := '[]'::jsonb; rechazos jsonb := '[]'::jsonb;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'Esa empresa no existe.' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.import_run r where r.id = p_run and r.company_id = p_company and r.status = 'en_curso'
                 and r.kind in ('historico', 'al_dia')) then
    raise exception 'Esa lectura no es de esta empresa, no trae asientos o ya terminó.' using errcode = '23514';
  end if;
  if jsonb_typeof(p_asientos) <> 'array' then raise exception 'Falta la lista de asientos.' using errcode = '22023'; end if;

  for a in select * from jsonb_array_elements(p_asientos) loop
    v_ej := a ->> 'ejercicio'; v_serie := (a ->> 'serie')::int; v_numero := (a ->> 'numero')::int;
    v_fecha := (a ->> 'fecha')::date; v_huella := a ->> 'huella';
    v_clave := format('%s/%s/%s', v_ej, v_serie, v_numero);
    begin
      -- Ya traído: igual o distinto, nunca dos veces.
      select * into v_e from public.journal_entry
       where company_id = p_company and external_program = 'diez' and external_year = v_ej
         and external_series = v_serie::text and external_number = v_numero::text;
      if v_e.id is not null then
        if v_e.external_hash = v_huella then n_estaban := n_estaban + 1;
        else distintos := distintos || jsonb_build_object('clave', v_clave, 'id', v_e.id); end if;
        continue;
      end if;

      if v_serie not in (1, 2, 3, 4, 9) then raise exception 'la serie % no es de Folvy', v_serie using errcode = '22023'; end if;
      select * into v_y from public.fiscal_year where company_id = p_company and code = v_ej;
      if v_y.id is null then raise exception 'el ejercicio % no existe en Folvy', v_ej using errcode = '22023'; end if;
      if v_y.origin = 'folvy' then raise exception 'el ejercicio % es de Folvy, no traído', v_ej using errcode = '22023'; end if;
      if v_fecha not between v_y.starts_on and v_y.ends_on then
        raise exception 'la fecha % no es del ejercicio %', v_fecha, v_ej using errcode = '22023';
      end if;
      if v_y.imported_until is not null and v_fecha > v_y.imported_until then
        raise exception 'el % es posterior al corte de lo traído (%)', v_fecha, v_y.imported_until using errcode = '22023';
      end if;
      if v_y.status <> 'open' then
        raise exception 'el ejercicio % está cerrado: se trae antes de cerrarlo', v_ej using errcode = '22023';
      end if;
      if exists (select 1 from public.journal_entry where company_id = p_company and fiscal_year_id = v_y.id
                  and series = v_serie and number = v_numero) then
        raise exception 'el número %/% de % ya lo tiene un asiento de Folvy', v_serie, v_numero, v_ej using errcode = '23505';
      end if;
      select array_agg(distinct x ->> 'cuenta') into v_faltan from jsonb_array_elements(a -> 'lineas') x
       where not exists (select 1 from public.company_account c where c.company_id = p_company and c.code = x ->> 'cuenta');
      if v_faltan is not null then
        raise exception 'faltan en el plan las subcuentas %', array_to_string(v_faltan, ', ') using errcode = '22023';
      end if;

      v_concepto := coalesce(nullif(trim(a ->> 'concepto'), ''), format('Asiento %s/%s traído de Diez', v_serie, v_numero));
      insert into public.journal_entry (account_id, company_id, fiscal_year_id, series, entry_date, concept, source_type, status,
                                        reasons, external_program, external_year, external_series, external_number, external_hash,
                                        import_run_id, created_by_name)
      values (v_cuenta, p_company, v_y.id, v_serie, v_fecha, v_concepto, 'migrated', 'borrador',
              jsonb_build_array(jsonb_build_object('decision', 'traido-de-diez',
                'porque', format('Asiento %s de Diez (tipo %s)', v_clave, coalesce(a ->> 'tipoAsiento', '—')),
                'tipo_diez', case when a ->> 'tipoAsiento' ~ '^[0-9]+$' then (a ->> 'tipoAsiento')::int end)),
              'diez', v_ej, v_serie::text, v_numero::text, v_huella, p_run, 'Diez (traído)')
      returning id into v_id;

      for l in select * from jsonb_array_elements(a -> 'lineas') loop
        select id into v_ca from public.company_account where company_id = p_company and code = l ->> 'cuenta';
        insert into public.journal_line (account_id, company_id, entry_id, position, company_account_id, debit, credit, concept,
                                         external_counterpart, external_voucher, external_negative_side)
        values (v_cuenta, p_company, v_id, (l ->> 'posicion')::smallint, v_ca, (l ->> 'debe')::numeric / 100, (l ->> 'haber')::numeric / 100,
                nullif(l ->> 'concepto', ''), nullif(l ->> 'contrapartida', ''), nullif(l ->> 'justificante', ''), l ->> 'negativoEnDiez');
      end loop;

      -- Regla 1, otra vez en la base: dos líneas al menos, y cuadra al céntimo.
      select count(*), coalesce(sum(debit), 0), coalesce(sum(credit), 0) into v_n, v_debe, v_haber from public.journal_line where entry_id = v_id;
      if v_n < 2 then raise exception 'tiene % línea(s)', v_n using errcode = '23514'; end if;
      if v_debe <> v_haber then raise exception 'no cuadra: debe % y haber %', v_debe, v_haber using errcode = '23514'; end if;

      -- Validado con el número de Diez y encadenado, como journal_entry_validar.
      perform pg_advisory_xact_lock(hashtextextended('journal_entry_numero:' || p_company, 0));
      select chain_seq, hash into v_seq, v_prev from public.journal_entry
       where company_id = p_company and chain_seq is not null order by chain_seq desc limit 1;
      v_seq := coalesce(v_seq, 0) + 1;
      update public.journal_entry set number = v_numero, status = 'validado', validated_at = now(), validated_by = null,
             validated_by_name = 'Diez (traído)', chain_seq = v_seq, prev_hash = v_prev, hash = 'pendiente'
       where id = v_id;
      v_hash := public.journal_huella(v_prev, public.journal_entry_canonico(v_id));
      perform set_config('folvy.journal_huella', v_id::text, true);
      update public.journal_entry set hash = v_hash where id = v_id;
      perform set_config('folvy.journal_huella', '', true);

      -- Cómo estaba en Diez al leerlo: lo que compara el día a día.
      insert into public.external_entry_snapshot (account_id, company_id, program, ext_year, ext_series, ext_number, entry_date, lines,
                                                  total_debit, total_credit, hash, import_run_id)
      values (v_cuenta, p_company, 'diez', v_ej, v_serie::text, v_numero, v_fecha, a -> 'lineas', v_debe, v_haber, v_huella, p_run)
      on conflict (company_id, program, ext_year, ext_series, ext_number)
      do update set entry_date = excluded.entry_date, lines = excluded.lines, total_debit = excluded.total_debit,
                    total_credit = excluded.total_credit, hash = excluded.hash, import_run_id = excluded.import_run_id, read_at = now();
      n_traidos := n_traidos + 1;
    exception when others then
      rechazos := rechazos || jsonb_build_object('clave', v_clave, 'motivo', sqlerrm);
    end;
  end loop;
  return jsonb_build_object('traidos', n_traidos, 'yaEstaban', n_estaban, 'distintos', distintos, 'rechazados', rechazos);
end $_$;


--
-- Name: FUNCTION conta_diez_importar(p_company uuid, p_run uuid, p_asientos jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_importar(p_company uuid, p_run uuid, p_asientos jsonb) IS 'C04b: escribe asientos de Diez ya convertidos (convertirAsiento) como migrated y validados, con el número de Diez y la huella encadenada. Idempotente; cada asiento en su subtransacción.';


--
-- Name: conta_diez_listo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_listo(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cuenta uuid;
  v_datos boolean; v_plan boolean; v_banco boolean; v_base text; v_traido boolean; v_fallo text;
  v_sin_nombre int;
begin
  select account_id, setup_completed_at is not null into v_cuenta, v_datos from public.company where id = p_company;
  if v_cuenta is null then raise exception 'Esa empresa no existe.' using errcode = 'P0002'; end if;
  -- El cliente, solo de su cuenta; Folvy (service_role, sin usuario), de todas.
  if auth.uid() is not null and not (v_cuenta = any (public.current_user_account_ids())) then
    raise exception 'Esa empresa no es de tu cuenta.' using errcode = '42501';
  end if;
  v_plan := exists (select 1 from public.company_tax_profile p where p.company_id = p_company)
        and exists (select 1 from public.company_account a where a.company_id = p_company);
  v_banco := exists (select 1 from public.company_account a where a.company_id = p_company and a.code like '572%' and a.status = 'activa');
  select b.nombre_bd into v_base from public.conta_diez_base b where b.company_id = p_company;
  v_traido := exists (select 1 from public.import_run r where r.company_id = p_company and r.program = 'diez' and r.kind = 'historico' and r.status = 'hecho');
  select r.error into v_fallo from public.import_run r
   where r.company_id = p_company and r.program = 'diez' and r.kind = 'historico' and r.status = 'fallido'
     and not v_traido order by r.finished_at desc nulls last limit 1;
  select count(*) into v_sin_nombre from public.company_account a where a.company_id = p_company and a.name_pending;
  return jsonb_build_object(
    'pasos', jsonb_build_array(
      jsonb_build_object('paso', 'datos', 'hecho', v_datos),
      jsonb_build_object('paso', 'plan', 'hecho', v_plan),
      jsonb_build_object('paso', 'banco', 'hecho', v_banco),
      jsonb_build_object('paso', 'diez', 'hecho', v_traido, 'base', v_base, 'fallo', v_fallo)),
    'falta', case when not v_datos then 'datos' when not v_plan then 'plan' when not v_banco then 'banco'
                  when not v_traido then 'diez' end,
    'sinNombre', v_sin_nombre);
end;
$$;


--
-- Name: conta_diez_numero_vez(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_numero_vez(p_entry uuid, p_base text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_empresa uuid; v_cuenta uuid; v_n int;
begin
  if coalesce(p_base, '') !~ '^[A-Za-z0-9][A-Za-z0-9-]*$' then
    raise exception 'conta_diez_numero_vez: «%» no es un número de factura de ventas.', p_base using errcode = '22023';
  end if;
  select e.company_id, e.account_id into v_empresa, v_cuenta from public.journal_entry e where e.id = p_entry;
  if v_empresa is null then
    raise exception 'conta_diez_numero_vez: el asiento % no existe.', p_entry using errcode = 'P0002';
  end if;
  select count(distinct s.entry_id) into v_n
    from public.external_send s
    join public.journal_entry a on a.id = s.entry_id and a.account_id = s.account_id
   where s.account_id = v_cuenta and s.company_id = v_empresa
     and s.entry_id <> p_entry
     and s.status in ('enviado', 'enlazado')
     and a.status = 'anulado'
     and (s.ext_invoice_number = p_base or s.ext_invoice_number ~ ('^' || p_base || '-[0-9]+$'));
  return 1 + v_n;
end
$_$;


--
-- Name: FUNCTION conta_diez_numero_vez(p_entry uuid, p_base text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_numero_vez(p_entry uuid, p_base text) IS 'C11c (24/10). La vez de un número de factura de ventas para un asiento: 1 + los asientos anulados de su empresa que ya lo mandaron a Diez (tal cual o «-N»). El envío numera «base-2», «base-3»…';


--
-- Name: conta_diez_por_enviar(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_por_enviar(p_limite integer DEFAULT 10) RETURNS TABLE(entry_id uuid, account_id uuid, company_id uuid, origen text, kind text, tiene_envio boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.id, e.account_id, e.company_id, e.source_type,
         case when e.source_type in ('sales_day', 'supplier_invoice') or o.source_type in ('sales_day', 'supplier_invoice') then 'factura' else 'asiento' end,
         s.id is not null
    from public.journal_entry e
    join public.conta_diez_envio_empresa z on z.company_id = e.company_id and z.account_id = e.account_id and z.enviar
     and coalesce(z.modo, 'al_validar') = 'al_validar'
    left join public.journal_entry o on o.id = e.reverses_entry_id and o.account_id = e.account_id
    left join public.external_send s on s.entry_id = e.id and s.account_id = e.account_id and s.status <> 'rechazado'
   where e.status = 'validado'
     and e.entry_date >= z.desde
     and e.source_type not in ('migrated', 'opening', 'closing', 'template')
     and (e.reverses_entry_id is null or exists (
           select 1 from public.external_send x
            where x.entry_id = e.reverses_entry_id and x.account_id = e.account_id and x.status in ('enviado', 'enlazado')))
     and (
           (s.id is null and e.validated_at < now() - interval '2 minutes')
        or (s.status = 'pendiente' and s.next_try_at is not null and s.next_try_at <= now() and s.attempts < 3 and s.updated_at < now() - interval '2 minutes')
     )
   order by e.validated_at, e.id
   limit greatest(1, least(coalesce(p_limite, 10), 50))
$$;


--
-- Name: FUNCTION conta_diez_por_enviar(p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_por_enviar(p_limite integer) IS 'C07 · Lo validado de las empresas con «Enviar a Diez» encendido que no está en Diez y le toca salir ahora (ver la migración 0430). Solo el servidor.';


--
-- Name: conta_diez_preparar_corte(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_preparar_corte(p_company uuid, p_corte date, p_por text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cuenta uuid;
  v_y public.fiscal_year;
  v_code text := to_char(p_corte, 'YYYY');
  v_desde date := date_trunc('year', p_corte)::date;
  v_hasta date := (date_trunc('year', p_corte) + interval '1 year - 1 day')::date;
  v_prev uuid;
  v_id uuid;
begin
  if p_corte is null or btrim(coalesce(p_por, '')) = '' then raise exception 'Hace falta la fecha de corte y quién lo prepara.'; end if;
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'La empresa % no existe.', p_company; end if;
  if not exists (select 1 from public.conta_diez_base where company_id = p_company) then
    raise exception 'La empresa no tiene base de Diez registrada (conta_diez_base_poner, primero).';
  end if;
  -- El corte, como lo último usado (si algo de abajo falla, se deshace con todo).
  update public.conta_diez_base set ultimo_corte = p_corte where company_id = p_company;
  select * into v_y from public.fiscal_year where company_id = p_company and code = v_code;
  if v_y.id is not null then
    if v_y.origin = 'mixed' and v_y.origin_program = 'diez' and v_y.imported_until = p_corte then
      return jsonb_build_object('ejercicio', v_code, 'corte', p_corte, 'cambia', false);
    end if;
    if exists (select 1 from public.journal_entry e where e.company_id = p_company and e.fiscal_year_id = v_y.id) then
      raise exception 'El ejercicio % ya tiene asientos: el corte de una empresa que ya trabaja en Folvy se hace a mano (como el de Foodint, C04 R4).', v_code;
    end if;
    if v_y.status <> 'open' then raise exception 'El ejercicio % está cerrado.', v_code; end if;
    if p_corte < v_y.starts_on or p_corte >= v_y.ends_on then
      raise exception 'El corte % tiene que caer dentro del ejercicio % y antes de su último día (% – %).', p_corte, v_code, v_y.starts_on, v_y.ends_on;
    end if;
    update public.fiscal_year set origin = 'mixed', origin_program = 'diez', imported_until = p_corte where id = v_y.id;
    return jsonb_build_object('ejercicio', v_code, 'corte', p_corte, 'cambia', true, 'era', v_y.origin);
  end if;
  if p_corte >= v_hasta then raise exception 'El corte % es el último día del año: entonces el ejercicio entero es de Diez, no mixto.', p_corte; end if;
  select id into v_prev from public.fiscal_year where company_id = p_company and ends_on = v_desde - 1;
  insert into public.fiscal_year (account_id, company_id, code, starts_on, ends_on, previous_year_id, status, origin, origin_program, imported_until)
  values (v_cuenta, p_company, v_code, v_desde, v_hasta, v_prev, 'open', 'mixed', 'diez', p_corte)
  returning id into v_id;
  return jsonb_build_object('ejercicio', v_code, 'corte', p_corte, 'cambia', true, 'era', null);
end;
$$;


--
-- Name: conta_diez_reclamar(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_reclamar(p_limite integer DEFAULT 10) RETURNS TABLE(entry_id uuid, account_id uuid, company_id uuid, origen text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtext('conta_diez_reclamar'));
  create temp table if not exists _c07_reclamo (entry_id uuid, account_id uuid, company_id uuid, origen text, kind text, tiene_envio boolean) on commit drop;
  truncate _c07_reclamo;
  insert into _c07_reclamo select * from public.conta_diez_por_enviar(p_limite);
  insert into public.external_send (entry_id, account_id, company_id, kind, payload_hash, status, attempts, next_try_at, updated_at)
  select r.entry_id, r.account_id, r.company_id, r.kind, 'sin-enviar', 'pendiente', 0, now() + interval '10 minutes', now()
    from _c07_reclamo r where not r.tiene_envio
  on conflict do nothing;
  update public.external_send s set next_try_at = now() + interval '10 minutes', updated_at = now()
    from _c07_reclamo r
   where r.tiene_envio and s.entry_id = r.entry_id and s.account_id = r.account_id and s.status = 'pendiente';
  return query select r.entry_id, r.account_id, r.company_id, r.origen from _c07_reclamo r;
end $$;


--
-- Name: FUNCTION conta_diez_reclamar(p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_reclamar(p_limite integer) IS 'C07 · Coge lo que le toca salir a Diez (conta_diez_por_enviar) y lo aparta 10 minutos para que no lo coja otra pasada. Solo el servidor (conta-diez-cola).';


--
-- Name: conta_diez_subcuentas(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_diez_subcuentas(p_company uuid, p_run uuid, p_cuentas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_cuenta uuid; v_plan text; v_d int; x jsonb; v_code text; v_hoja text; v_nombre text;
  n_nuevas int := 0; n_estaban int := 0; rechazos jsonb := '[]'::jsonb; sin_nombre jsonb := '[]'::jsonb;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'Esa empresa no existe.' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.import_run r where r.id = p_run and r.company_id = p_company and r.status = 'en_curso') then
    raise exception 'Esa lectura no es de esta empresa o ya terminó.' using errcode = '23514';
  end if;
  select case p.chart_kind when 'normal' then 'general' else 'pymes' end, p.account_digits into v_plan, v_d
    from public.company_tax_profile p where p.company_id = p_company;
  if v_plan is null then raise exception 'La empresa no tiene plan contable elegido.' using errcode = '23514'; end if;
  if jsonb_typeof(p_cuentas) <> 'array' then raise exception 'Falta la lista de subcuentas.' using errcode = '22023'; end if;

  for x in select * from jsonb_array_elements(p_cuentas) loop
    v_code := trim(x ->> 'code'); v_nombre := nullif(trim(x ->> 'nombre'), '');
    if exists (select 1 from public.company_account where company_id = p_company and code = v_code) then
      n_estaban := n_estaban + 1; continue;
    end if;
    if v_code !~ ('^[0-9]{' || v_d || '}$') then
      rechazos := rechazos || jsonb_build_object('code', v_code, 'motivo', format('no tiene %s dígitos', v_d)); continue;
    end if;
    -- La hoja: la cuenta sin hijas del plan más larga que empieza el código.
    select a.code into v_hoja from public.pgc_account a
     where a.plan = v_plan and a.is_leaf and a.valid_to is null and v_code like a.code || '%'
     order by length(a.code) desc limit 1;
    if v_hoja is null then
      rechazos := rechazos || jsonb_build_object('code', v_code, 'motivo', 'no cuelga de ninguna cuenta del plan'); continue;
    end if;
    if v_code = rpad(v_hoja, v_d, '0') then
      -- Es la de serie de su hoja y no está activada: se activa como de serie.
      insert into public.company_account (account_id, company_id, plan, code, template_code, name, plain_name, kind, source, created_by_name, name_source, import_id, import_run_id)
      select v_cuenta, p_company, v_plan, v_code, a.code, a.name, a.plain_name, 'template', 'serie', 'Diez (traída)', v_nombre, null, p_run
        from public.pgc_account a where a.plan = v_plan and a.code = v_hoja and a.valid_to is null;
    elsif v_nombre is null then
      -- C06: Diez no le da nombre. No se inventa: lleva el de su cuenta del
      -- plan oficial y queda pendiente de que alguien le ponga el suyo.
      insert into public.company_account (account_id, company_id, plan, code, template_code, name, kind, source, created_by_name, name_source, import_id, name_pending, import_run_id)
      select v_cuenta, p_company, v_plan, v_code, v_hoja, a.name, 'own', 'migrated', 'Diez (traída)', null, null, true, p_run
        from public.pgc_account a where a.plan = v_plan and a.code = v_hoja and a.valid_to is null;
      sin_nombre := sin_nombre || to_jsonb(v_code);
    else
      insert into public.company_account (account_id, company_id, plan, code, template_code, name, kind, source, created_by_name, name_source, import_id, import_run_id)
      values (v_cuenta, p_company, v_plan, v_code, v_hoja, v_nombre, 'own', 'migrated', 'Diez (traída)', v_nombre, null, p_run);
    end if;
    n_nuevas := n_nuevas + 1;
  end loop;
  return jsonb_build_object('nuevas', n_nuevas, 'estaban', n_estaban, 'rechazadas', rechazos, 'sinNombre', sin_nombre);
end $_$;


--
-- Name: FUNCTION conta_diez_subcuentas(p_company uuid, p_run uuid, p_cuentas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_diez_subcuentas(p_company uuid, p_run uuid, p_cuentas jsonb) IS 'C04b: da de alta las subcuentas que usa Diez y el plan no tiene, colgando de su hoja del PGC. Las que ya están no se tocan.';


--
-- Name: conta_direccion_entrada(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_direccion_entrada(p_company uuid, p_tipo text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_c public.company;
  v_base text; v_lp text; v_i int := 1;
  v_x public.company_inbound_address;
begin
  if p_tipo not in ('facturas', 'liquidaciones', 'documentos') then raise exception 'Una dirección es de documentos, de facturas o de liquidaciones.' using errcode = '22023'; end if;
  select * into v_c from public.company where id = p_company;
  if v_c.id is null or not public.belongs_to_account(v_c.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  select * into v_x from public.company_inbound_address where company_id = p_company and kind = p_tipo;
  if v_x.id is not null then return to_jsonb(v_x) || jsonb_build_object('direccion', v_x.local_part || '@' || v_x.domain, 'ya_estaba', true); end if;
  if not public.current_user_is_admin_or_manager_of(v_c.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta crea las direcciones de entrada.' using errcode = '42501';
  end if;
  v_base := regexp_replace(lower(translate(coalesce(nullif(v_c.trade_name, ''), v_c.legal_name, 'empresa'),
                                           'ÁÀÄÂÉÈËÊÍÌÏÎÓÒÖÔÚÙÜÛÑÇáàäâéèëêíìïîóòöôúùüûñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc')), '[^a-z0-9]+', '-', 'g');
  v_base := trim(both '-' from v_base);
  v_base := left(regexp_replace(v_base, '-(s-?l-?u?|s-?a|s-?c-?p|s-?l-?l)$', ''), 30);
  if length(v_base) < 2 then v_base := 'empresa'; end if;
  -- V02: la de documentos va sin prefijo («foodint@»); las de antes, con el suyo.
  v_lp := case when p_tipo = 'documentos' then v_base else p_tipo || '-' || v_base end;
  while exists (select 1 from public.company_inbound_address where lower(local_part) = v_lp and domain = 'entrada.folvy.app') loop
    v_i := v_i + 1; v_lp := case when p_tipo = 'documentos' then v_base else p_tipo || '-' || v_base end || '-' || v_i;
  end loop;
  insert into public.company_inbound_address (account_id, company_id, kind, local_part, created_by, created_by_name)
  values (v_c.account_id, v_c.id, p_tipo, v_lp, auth.uid(), p_quien_nombre) returning * into v_x;
  return to_jsonb(v_x) || jsonb_build_object('direccion', v_x.local_part || '@' || v_x.domain, 'ya_estaba', false);
end $_$;


--
-- Name: conta_direccion_facturas(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_direccion_facturas(p_company uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_c public.company;
  v_base text; v_lp text; v_i int := 1;
  v_x public.company_inbound_address;
begin
  select * into v_c from public.company where id = p_company;
  if v_c.id is null or not public.belongs_to_account(v_c.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  select * into v_x from public.company_inbound_address where company_id = p_company and kind = 'facturas';
  if v_x.id is not null then return to_jsonb(v_x) || jsonb_build_object('direccion', v_x.local_part || '@' || v_x.domain, 'ya_estaba', true); end if;
  if not public.current_user_is_admin_or_manager_of(v_c.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta crea la dirección de facturas.' using errcode = '42501';
  end if;
  v_base := regexp_replace(lower(translate(coalesce(nullif(v_c.trade_name, ''), v_c.legal_name, 'empresa'),
                                           'ÁÀÄÂÉÈËÊÍÌÏÎÓÒÖÔÚÙÜÛÑÇáàäâéèëêíìïîóòöôúùüûñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc')), '[^a-z0-9]+', '-', 'g');
  v_base := trim(both '-' from v_base);
  v_base := left(regexp_replace(v_base, '-(s-?l-?u?|s-?a|s-?c-?p|s-?l-?l)$', ''), 30);
  if length(v_base) < 2 then v_base := 'empresa'; end if;
  v_lp := 'facturas-' || v_base;
  while exists (select 1 from public.company_inbound_address where lower(local_part) = v_lp and domain = 'entrada.folvy.app') loop
    v_i := v_i + 1; v_lp := 'facturas-' || v_base || '-' || v_i;
  end loop;
  insert into public.company_inbound_address (account_id, company_id, local_part, created_by, created_by_name)
  values (v_c.account_id, v_c.id, v_lp, auth.uid(), p_quien_nombre) returning * into v_x;
  return to_jsonb(v_x) || jsonb_build_object('direccion', v_x.local_part || '@' || v_x.domain, 'ya_estaba', false);
end $_$;


--
-- Name: conta_documento_expedida_guardar(uuid, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_documento_expedida_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_e public.journal_entry;
  v_x public.journal_entry_document;
  v_obj record;
  v_prefijo text;
begin
  select * into v_e from public.journal_entry where id = p_entry for update;
  if v_e.id is null or not public.belongs_to_account(v_e.account_id) then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  if not public.current_user_is_admin_or_manager_of(v_e.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta guarda el documento de un asiento.' using errcode = '42501';
  end if;
  if v_e.status <> 'validado' then
    raise exception 'El documento se guarda con el asiento validado; este está %.', v_e.status using errcode = '23514';
  end if;
  if v_e.source_type <> 'manual' or v_e.series <> 1 then
    raise exception 'Ese asiento no es de una factura expedida apuntada a mano.' using errcode = '22023';
  end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'La huella del documento no es un sha256.' using errcode = '22023';
  end if;

  select * into v_x from public.journal_entry_document where entry_id = v_e.id and kind = 'factura_expedida';
  if v_x.id is not null then
    if v_x.sha256 = p_sha256 and v_x.storage_path = p_ruta then
      return jsonb_build_object('id', v_x.id, 'ruta', v_x.storage_path, 'nombre', v_x.file_name, 'ya_estaba', true);
    end if;
    raise exception 'Ese asiento ya tiene su factura (guardada el % por %): no se cambia.',
      to_char(v_x.created_at at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), coalesce(v_x.created_by_name, 'alguien') using errcode = '23505';
  end if;

  v_prefijo := v_e.account_id::text || '/' || v_e.id::text || '/';
  if p_ruta is null or left(p_ruta, length(v_prefijo)) <> v_prefijo or substr(p_ruta, length(v_prefijo) + 1) !~ '^[0-9a-f]{16,64}\.pdf$' then
    raise exception 'La ruta del documento no es la de este asiento (%<huella>.pdf).', v_prefijo using errcode = '22023';
  end if;
  select o.name, (o.metadata->>'size')::bigint as bytes, o.metadata->>'mimetype' as tipo into v_obj
    from storage.objects o where o.bucket_id = 'conta-documentos' and o.name = p_ruta;
  if v_obj.name is null then
    raise exception 'La factura no está subida (%): no se enlaza nada.', p_ruta using errcode = 'P0002';
  end if;
  if v_obj.bytes is not null and v_obj.bytes <> p_bytes then
    raise exception 'La factura subida tiene % bytes y se dijeron %: no se enlaza.', v_obj.bytes, p_bytes using errcode = '22023';
  end if;
  if v_obj.tipo is not null and v_obj.tipo <> 'application/pdf' then
    raise exception 'La factura subida no es un PDF (%): una foto se convierte a PDF antes.', v_obj.tipo using errcode = '22023';
  end if;

  insert into public.journal_entry_document (account_id, company_id, entry_id, kind, storage_path, file_name, sha256, size_bytes, created_by, created_by_name)
  values (v_e.account_id, v_e.company_id, v_e.id, 'factura_expedida', p_ruta, p_nombre, p_sha256, p_bytes, auth.uid(), p_quien_nombre)
  returning * into v_x;
  return jsonb_build_object('id', v_x.id, 'ruta', v_x.storage_path, 'nombre', v_x.file_name, 'ya_estaba', false);
end $_$;


--
-- Name: FUNCTION conta_documento_expedida_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_documento_expedida_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text) IS 'S01d · Enlaza al asiento validado de una factura expedida a mano (serie 1) su PDF ya subido a conta-documentos (kind factura_expedida). Comprueba ruta, fichero, tamaño y tipo; uno por asiento, y no se cambia.';


--
-- Name: conta_documento_factura_guardar(uuid, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_documento_factura_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_e public.journal_entry;
  v_x public.journal_entry_document;
  v_obj record;
  v_prefijo text;
begin
  select * into v_e from public.journal_entry where id = p_entry for update;
  if v_e.id is null or not (public.belongs_to_account(v_e.account_id) or auth.role() = 'service_role') then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  if not (public.current_user_is_admin_or_manager_of(v_e.account_id) or auth.role() = 'service_role') then
    raise exception 'Solo un administrador o un encargado de la cuenta guarda el documento de un asiento.' using errcode = '42501';
  end if;
  if v_e.status <> 'validado' then
    raise exception 'El documento se guarda con el asiento validado; este está %.', v_e.status using errcode = '23514';
  end if;
  if v_e.source_type <> 'supplier_invoice' or not exists (select 1 from public.supplier_invoice i where i.id = v_e.source_id and i.account_id = v_e.account_id) then
    raise exception 'Ese asiento no es de una factura recibida.' using errcode = '22023';
  end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'La huella del documento no es un sha256.' using errcode = '22023';
  end if;

  select * into v_x from public.journal_entry_document where entry_id = v_e.id and kind = 'factura_recibida';
  if v_x.id is not null then
    if v_x.sha256 = p_sha256 and v_x.storage_path = p_ruta then
      return jsonb_build_object('id', v_x.id, 'ruta', v_x.storage_path, 'nombre', v_x.file_name, 'ya_estaba', true);
    end if;
    raise exception 'Ese asiento ya tiene su factura (guardada el % por %): no se cambia.',
      to_char(v_x.created_at at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), coalesce(v_x.created_by_name, 'alguien') using errcode = '23505';
  end if;

  v_prefijo := v_e.account_id::text || '/' || v_e.id::text || '/';
  if p_ruta is null or left(p_ruta, length(v_prefijo)) <> v_prefijo or substr(p_ruta, length(v_prefijo) + 1) !~ '^[0-9a-f]{16,64}\.pdf$' then
    raise exception 'La ruta del documento no es la de este asiento (%<huella>.pdf).', v_prefijo using errcode = '22023';
  end if;
  select o.name, (o.metadata->>'size')::bigint as bytes, o.metadata->>'mimetype' as tipo into v_obj
    from storage.objects o where o.bucket_id = 'conta-documentos' and o.name = p_ruta;
  if v_obj.name is null then
    raise exception 'La factura no está subida (%): no se enlaza nada.', p_ruta using errcode = 'P0002';
  end if;
  if v_obj.bytes is not null and v_obj.bytes <> p_bytes then
    raise exception 'La factura subida tiene % bytes y se dijeron %: no se enlaza.', v_obj.bytes, p_bytes using errcode = '22023';
  end if;
  if v_obj.tipo is not null and v_obj.tipo <> 'application/pdf' then
    raise exception 'La factura subida no es un PDF (%): una foto se convierte a PDF antes.', v_obj.tipo using errcode = '22023';
  end if;

  insert into public.journal_entry_document (account_id, company_id, entry_id, kind, storage_path, file_name, sha256, size_bytes, created_by, created_by_name)
  values (v_e.account_id, v_e.company_id, v_e.id, 'factura_recibida', p_ruta, p_nombre, p_sha256, p_bytes, auth.uid(), p_quien_nombre)
  returning * into v_x;
  return jsonb_build_object('id', v_x.id, 'ruta', v_x.storage_path, 'nombre', v_x.file_name, 'ya_estaba', false);
end $_$;


--
-- Name: FUNCTION conta_documento_factura_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_documento_factura_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text) IS 'D01 · Enlaza al asiento validado de una factura recibida su PDF ya copiado a conta-documentos (kind factura_recibida). Comprueba ruta, fichero, tamaño y tipo; uno por asiento, y no se cambia.';


--
-- Name: conta_documento_guardar(uuid, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_documento_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_e public.journal_entry;
  v_x public.journal_entry_document;
  v_obj record;
  v_prefijo text;
begin
  select * into v_e from public.journal_entry where id = p_entry for update;
  if v_e.id is null or not public.belongs_to_account(v_e.account_id) then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  if not public.current_user_is_admin_or_manager_of(v_e.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta guarda el documento de un asiento.' using errcode = '42501';
  end if;
  if v_e.status <> 'validado' then
    raise exception 'El documento se guarda con el asiento validado (el PDF lleva su número); este está %.', v_e.status using errcode = '23514';
  end if;
  if not exists (select 1 from public.sales_day_summary d
                  where d.entry_id = v_e.id and d.account_id = v_e.account_id and d.channel_id is not null) then
    raise exception 'Ese asiento no es de las ventas de una plataforma: no lleva resumen de ventas.' using errcode = '22023';
  end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'La huella del documento no es un sha256.' using errcode = '22023';
  end if;

  -- Si ya tiene documento: el mismo → se devuelve el que hay; otro → no se cambia.
  select * into v_x from public.journal_entry_document where entry_id = v_e.id and kind = 'resumen_ventas';
  if v_x.id is not null then
    if v_x.sha256 = p_sha256 and v_x.storage_path = p_ruta then
      return jsonb_build_object('id', v_x.id, 'ruta', v_x.storage_path, 'nombre', v_x.file_name, 'ya_estaba', true);
    end if;
    raise exception 'Ese asiento ya tiene su documento (guardado el % por %): no se cambia.',
      to_char(v_x.created_at at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), coalesce(v_x.created_by_name, 'alguien') using errcode = '23505';
  end if;

  -- La ruta es la de SU cuenta y SU asiento, y el fichero está subido con ese tamaño.
  v_prefijo := v_e.account_id::text || '/' || v_e.id::text || '/';
  if p_ruta is null or left(p_ruta, length(v_prefijo)) <> v_prefijo or substr(p_ruta, length(v_prefijo) + 1) !~ '^[0-9a-f]{16,64}\.pdf$' then
    raise exception 'La ruta del documento no es la de este asiento (%<huella>.pdf).', v_prefijo using errcode = '22023';
  end if;
  select o.name, (o.metadata->>'size')::bigint as bytes, o.metadata->>'mimetype' as tipo into v_obj
    from storage.objects o where o.bucket_id = 'conta-documentos' and o.name = p_ruta;
  if v_obj.name is null then
    raise exception 'El documento no está subido (%): no se enlaza nada.', p_ruta using errcode = 'P0002';
  end if;
  if v_obj.bytes is not null and v_obj.bytes <> p_bytes then
    raise exception 'El documento subido tiene % bytes y se dijeron %: no se enlaza.', v_obj.bytes, p_bytes using errcode = '22023';
  end if;
  if v_obj.tipo is not null and v_obj.tipo <> 'application/pdf' then
    raise exception 'El documento subido no es un PDF (%).', v_obj.tipo using errcode = '22023';
  end if;

  insert into public.journal_entry_document (account_id, company_id, entry_id, kind, storage_path, file_name, sha256, size_bytes, created_by, created_by_name)
  values (v_e.account_id, v_e.company_id, v_e.id, 'resumen_ventas', p_ruta, p_nombre, p_sha256, p_bytes, auth.uid(), p_quien_nombre)
  returning * into v_x;
  return jsonb_build_object('id', v_x.id, 'ruta', v_x.storage_path, 'nombre', v_x.file_name, 'ya_estaba', false);
end $_$;


--
-- Name: FUNCTION conta_documento_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_documento_guardar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text) IS 'R15 · Enlaza a su asiento validado el Resumen de ventas ya subido a conta-documentos. Comprueba ruta, fichero y tamaño; uno por asiento, y no se cambia.';


--
-- Name: conta_documentos_recibidos(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_documentos_recibidos(p_company uuid, p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_acc uuid;
  v_hoy date := (now() at time zone 'Europe/Madrid')::date;
  v_filas jsonb;
  v_esperadas jsonb;
  v_correo record;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_hasta < p_desde then
    raise exception 'El periodo no es válido.' using errcode = '22023';
  end if;

  with facturas as materialized (
    select i.*, s.name as proveedor_nombre,
           (select jsonb_build_object('id', e.id, 'estado', e.status, 'solo', coalesce(e.validated_by_name, '') like 'Folvy (apunta solo%')
              from public.journal_entry e
             where e.account_id = v_acc and e.company_id = p_company and e.source_type = 'supplier_invoice' and e.source_id = i.id
               and e.status in ('propuesto', 'borrador', 'validado')
             order by (e.status = 'validado') desc, e.created_at desc limit 1) as asiento,
           (select jsonb_build_object('fecha', gr.receipt_date, 'local', l.name)
              from public.supplier_invoice_receipt r join public.goods_receipt gr on gr.id = r.goods_receipt_id
              left join public.locations l on l.id = gr.location_id
             where r.supplier_invoice_id = i.id order by gr.receipt_date desc limit 1) as recepcion,
           -- R5 · 6: cuántas facturas suyas había antes de esta (para decir «es la primera»).
           (select count(*) from public.supplier_invoice p
             where p.account_id = v_acc and p.supplier_id = i.supplier_id and p.id <> i.id and p.status not in ('anulada', 'descartada')
               and (coalesce(p.invoice_date, (p.created_at at time zone 'Europe/Madrid')::date), p.created_at) < (coalesce(i.invoice_date, (i.created_at at time zone 'Europe/Madrid')::date), i.created_at)) as previas,
           -- R5 · 7: el fichero de la llegada (una foto o un PDF), para decir cómo llegó de verdad.
           (select d.mime_type from public.document_inbox d where d.id = i.inbox_id and d.account_id = v_acc) as llegada_tipo
      from public.supplier_invoice i
      left join public.supplier s on s.id = i.supplier_id and s.account_id = i.account_id
     where i.account_id = v_acc and (i.company_id = p_company or i.company_id is null)
       and i.status <> 'anulada'
       and coalesce(i.invoice_date, (i.created_at at time zone 'Europe/Madrid')::date) between p_desde and p_hasta
  ), gasto0 as materialized (
    -- Lo que Folvy ha entendido: la cuenta del asiento si lo hay; si no, la de la ficha.
    select f.id, f.supplier_id,
           coalesce(
             (select jsonb_build_object('cuenta', a.code, 'nombre', a.name, 'origen', 'del asiento')
                from public.journal_line l join public.company_account a on a.id = l.company_account_id
               where l.entry_id = (f.asiento->>'id')::uuid and a.code like '6%' and l.debit > 0 order by l.position limit 1),
             (select jsonb_build_object('cuenta', a.code, 'nombre', a.name, 'origen', 'de su ficha')
                from public.company_account_link k join public.company_account a on a.id = k.company_account_id
               where k.company_id = p_company and k.entity = 'supplier' and k.entity_id = f.supplier_id::text and k.role = 'gasto' limit 1)) as entendido
      from facturas f
  ), aprendidos as materialized (
    -- R5 · 6: sin cuenta en el asiento ni en la ficha, lo aprendido de sus
    -- facturas anteriores (0250), como en N23, con su porqué. Si no hay nada
    -- que aprender, también se dice (la pantalla explica qué hacer).
    -- S01n · Una vez por PROVEEDOR, no por factura: lo aprendido solo depende
    -- de la empresa y el proveedor. Y «materialized»: sin él, Postgres copiaba
    -- la llamada en cada lectura de «aprendido» (unas 8 por factura).
    select s.supplier_id, public.conta_gasto_aprendido(p_company, s.supplier_id) as aprendido
      from (select distinct g.supplier_id from gasto0 g where g.entendido is null and g.supplier_id is not null) s
  ), gasto as materialized (
    select g.id, g.entendido, a.aprendido
      from gasto0 g left join aprendidos a on a.supplier_id = g.supplier_id and g.entendido is null
  ), filas_f as (
    select jsonb_build_object(
      'id', f.id, 'tipo', 'factura',
      -- S01 (0160): la descartada sale, con su estado y su porqué (regla 7: no se esconde).
      'estado', case when f.status = 'descartada' then 'descartada'
                     when f.asiento->>'estado' = 'validado' then 'apuntada'
                     when f.supplier_id is null or f.reading_confidence = 'duda' or f.status = 'con_discrepancias' then 'por_aclarar'
                     else 'para_mirar' end,
      'proveedor', jsonb_build_object('id', f.supplier_id, 'nombre', coalesce(f.proveedor_nombre, f.reading->'factura'->'proveedor'->>'nombre')),
      'numero', f.invoice_number, 'fecha', f.invoice_date, 'total', f.grand_total,
      -- R5 · 7: por dónde llegó DE VERDAD. Sin canal apuntado: leída del papel
      -- de su recepción (Cocina), leída en Compras, o escrita a mano.
      'canal', coalesce(f.arrival_channel, case when f.source = 'ocr' and f.recepcion is not null then 'cocina' when f.source = 'ocr' then 'compras' else 'a_mano' end),
      'llegada_tipo', f.llegada_tipo,
      'previas', f.previas,
      'confianza', f.reading_confidence,
      'porque', case when f.status = 'descartada'
                  then 'No es una factura: ' || coalesce(f.discard_reason, 'sin motivo') || ' (' || coalesce(f.discarded_by_name, 'una persona') || ', ' || to_char(f.discarded_at at time zone 'Europe/Madrid', 'DD/MM/YYYY') || ').'
                  else coalesce(f.reading->'porque'->>0, case when f.supplier_id is null then 'No reconozco el emisor: dime quién es.' end) end,
      'entendido', coalesce(g.entendido, case when g.aprendido->>'cuenta' is not null then jsonb_build_object(
                     'cuenta', g.aprendido->>'cuenta', 'nombre', g.aprendido->>'nombre', 'origen', g.aprendido->>'origen', 'sin_confirmar', true) end),
      'aprendido', case when g.aprendido is not null then jsonb_build_object('cuenta', g.aprendido->>'cuenta', 'facturas', coalesce((g.aprendido->>'facturas')::int, 0),
                     'confianza', g.aprendido->>'confianza', 'porque', g.aprendido->>'porque') end,
      'recepcion', f.recepcion, 'asiento', f.asiento,
      'llego', f.created_at) as fila
      from facturas f join gasto g on g.id = f.id
  ), recepciones as materialized (
    -- R6 · Una recepción cuyo papel es «factura» o «albarán-factura» ES una
    -- factura recibida. Desde el corte, Compras ya la hace factura con el mismo
    -- papel (0140) y sale arriba, en filas_f. Aquí, las que NO son factura:
    --   · de antes del corte: las llevó el programa anterior. Se enlazan con su
    --     asiento traído de Diez (mismo proveedor, su número en el concepto y
    --     el mismo total), nunca se apuntan otra vez (la base no deja asentar
    --     antes del corte: 0120 de C04);
    --   · desde el corte, sin factura: la recepción no pudo hacerla (su
    --     pregunta lo dice): por aclarar, no se esconde (regla 7).
    -- Lo leído es el de la recepción: no se vuelve a leer con el modelo.
    select g.id, g.receipt_date, g.supplier_id, g.raw_document_url, g.created_at, s.name as proveedor_nombre,
           a.parsed_result->'document' as doc, p.question, p.reason as camino_porque,
           -- S01g · El soporte de una liquidación mensual (la ruta «liquidacion»), con su local y su liquidación, si ya está.
           p.path as ruta, p.supplier_id as ruta_proveedor, p.not_support_at, g.location_id as local_id, g.code as codigo,
           (select s2.name from public.supplier s2 where s2.id = p.supplier_id and s2.account_id = v_acc) as ruta_proveedor_nombre,
           (select lo.name from public.locations lo where lo.id = g.location_id and lo.account_id = v_acc) as local_nombre,
           (select jsonb_build_object('id', l.id, 'desde', l.period_from, 'hasta', l.period_to)
              from public.licensed_settlement l
             where p.path = 'liquidacion' and l.account_id = v_acc and l.location_id = g.location_id and l.supplier_id = p.supplier_id
               and g.receipt_date between l.period_from and l.period_to
             order by l.period_from desc limit 1) as liquidacion,
           upper(regexp_replace(coalesce(nullif(a.parsed_result->'document'->>'doc_number', ''), g.supplier_doc_number, ''), '[^A-Za-z0-9]', '', 'g')) as clave,
           nullif(a.parsed_result->'document'->>'grand_total', '')::numeric as total,
           exists (select 1 from public.fiscal_year y
                    where y.company_id = p_company and y.account_id = v_acc and g.receipt_date between y.starts_on and y.ends_on
                      and y.imported_until is not null and g.receipt_date <= y.imported_until) as antes_del_corte,
           (select k.company_account_id from public.company_account_link k
             where k.company_id = p_company and k.account_id = v_acc and k.entity = 'supplier' and k.entity_id = g.supplier_id::text and k.role = 'principal' limit 1) as subcuenta
      from public.goods_receipt g
      join public.goods_receipt_ai_session a on a.id = g.ai_session_id and a.account_id = g.account_id
      left join public.goods_receipt_path p on p.goods_receipt_id = g.id and p.account_id = g.account_id
      left join public.supplier s on s.id = g.supplier_id and s.account_id = g.account_id
     where g.account_id = v_acc and g.status = 'confirmado'
       and a.parsed_result->'document'->>'doc_type' in ('factura', 'albaran_factura')
       and g.receipt_date between p_desde and p_hasta
       -- De esta empresa: la del camino; sin camino (las de antes de Compras), la
       -- del NIF a cuyo nombre va el papel, o la única de la cuenta si solo hay una.
       and coalesce(p.company_id,
             (select c.id from public.company c
               where c.account_id = v_acc and nullif(regexp_replace(upper(coalesce(c.tax_id, '')), '[^A-Z0-9]', '', 'g'), '')
                     = regexp_replace(regexp_replace(upper(coalesce(a.parsed_result->'document'->>'bill_to_tax_id', '')), '[^A-Z0-9]', '', 'g'), '^ES(?=[A-Z0-9]{9}$)', '')
               limit 1),
             (select c.id from public.company c where c.account_id = v_acc and (select count(*) from public.company c2 where c2.account_id = v_acc) = 1)) = p_company
       and p.supplier_invoice_id is null
       and not exists (select 1 from public.supplier_invoice_receipt x join public.supplier_invoice si on si.id = x.supplier_invoice_id
                        where x.goods_receipt_id = g.id and si.status <> 'anulada')
  ), recepciones_diez as materialized (
    select r.*,
           (select jsonb_build_object('id', e.id, 'serie', e.series, 'numero', e.number, 'fecha', e.entry_date)
              from public.journal_entry e join public.journal_line l on l.entry_id = e.id
             where r.antes_del_corte and e.account_id = v_acc and e.company_id = p_company and e.series = 2 and e.external_program = 'diez' and e.status = 'validado'
               and l.company_account_id = r.subcuenta and l.credit > 0 and round(l.credit * 100) = round(r.total * 100)
               -- El número de Diez va en el concepto (medido: ninguna línea traída trae su justificante), o en el justificante si lo trae.
               and length(r.clave) >= 3
               and (position(r.clave in upper(regexp_replace(coalesce(e.concept, ''), '[^A-Za-z0-9]', '', 'g'))) > 0
                    or upper(regexp_replace(coalesce(l.external_voucher, l.document_ref, ''), '[^A-Za-z0-9]', '', 'g')) = r.clave)
             order by abs(e.entry_date - r.receipt_date) limit 1) as diez
      from recepciones r
  ), filas_r as (
    select jsonb_build_object(
      'id', r.id, 'tipo', 'recepcion',
      'estado', case when r.antes_del_corte then 'en_diez' when r.ruta = 'liquidacion' and r.not_support_at is null then 'soporte' else 'por_aclarar' end,
      'proveedor', jsonb_build_object('id', r.supplier_id, 'nombre', coalesce(r.proveedor_nombre, r.doc->>'supplier_name')),
      'numero', nullif(r.doc->>'doc_number', ''), 'fecha', coalesce(nullif(r.doc->>'doc_date', '')::date, r.receipt_date), 'total', r.total,
      'canal', 'cocina', 'confianza', null,
      'porque', case
        when r.antes_del_corte and r.diez is not null then 'Es de antes del corte y ya está en Diez (asiento ' || (r.diez->>'serie') || '/' || (r.diez->>'numero') || ', mismo proveedor, número y total): no se vuelve a apuntar.'
        when r.antes_del_corte then 'Es de antes del corte: la llevó el programa anterior y no se vuelve a apuntar. No la encuentro en Diez por su número y su total: míralo allí.'
        when r.ruta = 'liquidacion' and r.not_support_at is null then 'No se apunta como compra: entra en la contabilidad con la liquidación mensual de '
          || coalesce(r.ruta_proveedor_nombre, 'su proveedor') || case when r.liquidacion is null then '. Su liquidación de este mes aún no ha llegado.' else '.' end
        when r.question = 'factura_sin_importes' then 'La recepción la leyó, pero no trae importes por línea con su IVA: no he podido hacer la factura. Súbela o díctamela.'
        when r.question is not null then 'La recepción la leyó, pero no he podido hacer la factura: ' || coalesce(r.camino_porque, 'falta algo en la recepción') || '.'
        else 'La recepción la leyó y aún no es factura: ábrela en Compras.' end,
      'entendido', null, 'recepcion', jsonb_build_object('fecha', r.receipt_date, 'local', r.local_nombre),
      'soporte', case when r.ruta = 'liquidacion' and r.not_support_at is null and not r.antes_del_corte then jsonb_build_object(
        'proveedor_id', r.ruta_proveedor, 'proveedor', r.ruta_proveedor_nombre, 'mes', to_char(r.receipt_date, 'YYYY-MM'),
        'local', r.local_nombre, 'local_id', r.local_id, 'codigo', r.codigo, 'liquidacion', r.liquidacion) end,
      'asiento', case when r.diez is not null then jsonb_build_object('id', r.diez->>'id', 'estado', 'validado', 'solo', false, 'diez', true) end,
      'diez', r.diez, 'papel', r.raw_document_url,
      'llego', r.created_at) as fila
      from recepciones_diez r
  ), filas_l as (
    -- Lo que llegó y no es (todavía) una factura: por aclarar, con su motivo.
    select jsonb_build_object(
      'id', d.id, 'tipo', 'llegada',
      'estado', case when d.status = 'repetida' then 'repetida' else 'por_aclarar' end,
      'proveedor', jsonb_build_object('id', null, 'nombre', null),
      'numero', null, 'fecha', (d.created_at at time zone 'Europe/Madrid')::date, 'total', null,
      'canal', d.channel, 'confianza', null,
      'porque', coalesce(d.reason, case d.status when 'falta_pdf' then 'Falta el PDF: el correo trae un enlace.' when 'leyendo' then 'Leyéndola.' when 'recibido' then 'Recibida, sin leer todavía.' else 'Hay algo que aclarar.' end),
      'entendido', null, 'recepcion', null, 'asiento', null, 'llego', d.created_at, 'archivo', d.file_name) as fila
      from public.document_inbox d
     where d.account_id = v_acc and (d.company_id = p_company or d.company_id is null)
       and d.supplier_invoice_id is null and d.status <> 'descartado'
       -- V02 · Lo que la puerta sabe que NO es una factura (un extracto, una
       -- nómina, una liquidación…) tiene su sitio y sale en Inicio › Documentos;
       -- aquí, lo que es factura o ticket y lo que aún no se sabe qué es.
       and coalesce(d.doc_kind, 'factura') in ('factura', 'ticket')
       and (d.created_at at time zone 'Europe/Madrid')::date between p_desde and p_hasta
  )
  select coalesce(jsonb_agg(fila order by (fila->>'llego') desc), '[]'::jsonb) into v_filas
    from (select fila from filas_f union all select fila from filas_l union all select fila from filas_r) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.periodo, x.supplier_name), '[]'::jsonb) into v_esperadas
    from public.conta_esperadas_no_llegadas(p_company, least(v_hoy, p_hasta + 1)) x;

  select a.local_part || '@' || a.domain as direccion, a.active into v_correo
    from public.company_inbound_address a where a.company_id = p_company and a.account_id = v_acc
   -- V02: la dirección única de la empresa, si la tiene; si no, la de facturas.
   order by (a.kind = 'documentos') desc, (a.kind = 'facturas') desc limit 1;

  return jsonb_build_object(
    'desde', p_desde, 'hasta', p_hasta,
    'correo', jsonb_build_object('activo', coalesce(v_correo.active, false), 'direccion', v_correo.direccion),
    'recibe_mercancia', public.conta_recibe_mercancia(p_company),
    'filas', v_filas,
    'esperadas', v_esperadas,
    'cifras', jsonb_build_object(
      -- R5 · 8: las del periodo elegido, no «esta semana».
      'llegadas', jsonb_array_length(v_filas),
      'llegadas_por_canal', (select coalesce(jsonb_object_agg(c, n), '{}'::jsonb) from (select f->>'canal' c, count(*) n from jsonb_array_elements(v_filas) f group by 1) y),
      'apuntadas_solas', (select count(*) from jsonb_array_elements(v_filas) f where f->>'estado' = 'apuntada' and (f->'asiento'->>'solo')::boolean),
      'apuntadas', (select count(*) from jsonb_array_elements(v_filas) f where f->>'estado' = 'apuntada'),
      'para_mirar', (select count(*) from jsonb_array_elements(v_filas) f where f->>'estado' = 'para_mirar'),
      'por_aclarar', (select count(*) from jsonb_array_elements(v_filas) f where f->>'estado' = 'por_aclarar'),
      'soporte', (select count(*) from jsonb_array_elements(v_filas) f where f->>'estado' = 'soporte'),
      'esperadas_no_llegadas', jsonb_array_length(v_esperadas)));
end $_$;


--
-- Name: FUNCTION conta_documentos_recibidos(p_company uuid, p_desde date, p_hasta date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_documentos_recibidos(p_company uuid, p_desde date, p_hasta date) IS 'D01 · N22: las facturas recibidas de una empresa en un periodo (las cifras, del periodo; también las recepciones cuyo papel es una factura y no lo es todavía, o que son de antes del corte, enlazadas con Diez), con sus cinco cifras, el porqué de cada fila y lo que Folvy ha entendido; si el correo está encendido y si recibe la mercancía con Folvy. Solo para los de la cuenta.';


--
-- Name: conta_eje_analitico_al_dia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_eje_analitico_al_dia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end $$;


--
-- Name: conta_ejercicio_sin_solapes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ejercicio_sin_solapes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare otro text; prev_fin date; prev_empresa uuid;
begin
  select code into otro from public.fiscal_year
   where company_id = new.company_id and id <> new.id
     and daterange(starts_on, ends_on, '[]') && daterange(new.starts_on, new.ends_on, '[]')
   limit 1;
  if otro is not null then
    raise exception 'El ejercicio % se solapa con el ejercicio %', new.code, otro using errcode = '23P01';
  end if;
  if new.previous_year_id is not null then
    select ends_on, company_id into prev_fin, prev_empresa from public.fiscal_year where id = new.previous_year_id;
    if prev_empresa is distinct from new.company_id then
      raise exception 'El ejercicio anterior es de otra empresa' using errcode = '23514';
    end if;
    if prev_fin + 1 <> new.starts_on then
      raise exception 'Entre el ejercicio anterior (acaba el %) y el % (empieza el %) no puede haber hueco', prev_fin, new.code, new.starts_on
        using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: conta_enlace_pago_cobrado(text, text, text, numeric, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_cobrado(p_sesion text, p_stripe text, p_pago_ref text, p_importe numeric, p_metodo text, p_fecha date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e public.conta_enlace_pago;
begin
  select * into e from public.conta_enlace_pago where sesion = p_sesion for update;
  if e.id is null then return jsonb_build_object('hecho', false, 'motivo', 'no_existe'); end if;
  if e.status = 'pagado' then return jsonb_build_object('hecho', false, 'motivo', 'ya_cobrado'); end if;
  if not exists (select 1 from public.conta_cobro_stripe where company_id = e.company_id and stripe_account_id = p_stripe) then
    return jsonb_build_object('hecho', false, 'motivo', 'otra_cuenta');
  end if;
  return public._s01_enlace_cobrar(e.id, p_importe, p_metodo, p_pago_ref, 'stripe', p_fecha);
end $$;


--
-- Name: conta_enlace_pago_cobrado_redsys(text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_cobrado_redsys(p_pedido text, p_comercio text, p_importe numeric, p_metodo text, p_autorizacion text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.conta_enlace_pago_intento; e public.conta_enlace_pago; r public.conta_cobro_redsys;
begin
  select * into i from public.conta_enlace_pago_intento where pedido = p_pedido;
  if i.pedido is null then return jsonb_build_object('hecho', false, 'motivo', 'no_existe'); end if;
  select * into e from public.conta_enlace_pago where id = i.enlace_id for update;
  select * into r from public.conta_cobro_redsys where company_id = e.company_id;
  if r.company_id is null or r.comercio is distinct from p_comercio then return jsonb_build_object('hecho', false, 'motivo', 'otro_comercio'); end if;
  if not r.cobra then return jsonb_build_object('hecho', false, 'motivo', 'no_cobra'); end if;
  return public._s01_enlace_cobrar(e.id, p_importe, p_metodo, 'redsys:' || p_pedido || coalesce(':' || nullif(trim(p_autorizacion), ''), ''), 'redsys', null);
end $$;


--
-- Name: conta_enlace_pago_comision(text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_comision(p_sesion text, p_comision numeric, p_neto numeric) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.conta_enlace_pago set comision = round(p_comision, 2), neto = round(p_neto, 2) where sesion = p_sesion and status = 'pagado'
$$;


--
-- Name: conta_enlace_pago_datos(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_datos(p_token text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('enlace', e.id, 'estado', e.status, 'empresa_id', e.company_id, 'factura_id', e.invoice_id, 'factura', v.number_text, 'pendiente', c.pendiente,
                            'empresa', coalesce(nullif(trim(co.trade_name), ''), co.legal_name), 'correo', nullif(lower(trim(v.email_to)), ''),
                            'stripe', s.stripe_account_id, 'modo', s.modo, 'tarjeta', s.tarjeta, 'bizum', s.bizum,
                            'proveedor', public._s01_proveedor_enlace(e.company_id),
                            'redsys', case when r.company_id is not null then jsonb_build_object('comercio', r.comercio, 'terminal', r.terminal, 'bizum', r.bizum,
                                                                                                  'modo', r.modo, 'cobra', r.cobra) end)
    from public.conta_enlace_pago e
    join public.customer_invoice v on v.id = e.invoice_id
    join public.conta_factura_cobro c on c.invoice_id = e.invoice_id
    join public.company co on co.id = e.company_id
    left join public.conta_cobro_stripe s on s.company_id = e.company_id
    left join public.conta_cobro_redsys r on r.company_id = e.company_id
   where e.token = p_token
$$;


--
-- Name: conta_enlace_pago_para(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_para(p_invoice uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.customer_invoice; c record; v_prov text; v_token text;
begin
  select * into v from public.customer_invoice where id = p_invoice;
  if v.id is null or v.status <> 'emitida' then return null; end if;
  select * into c from public.conta_factura_cobro where invoice_id = p_invoice;
  if c.invoice_id is null or c.de_plataforma or c.total <= 0 or c.pendiente < 0.005 then return null; end if;
  v_prov := public._s01_proveedor_enlace(v.company_id);
  if v_prov is null then return null; end if;
  select token into v_token from public.conta_enlace_pago where invoice_id = p_invoice and status = 'abierto';
  if v_token is not null then return v_token; end if;
  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.conta_enlace_pago (account_id, company_id, invoice_id, token) values (v.account_id, v.company_id, v.id, v_token);
  perform public._conta_venta_evento(v.id, 'enlace_pago', 'Enlace de pago preparado (tarjeta'
    || case when public._s01_metodos_enlace(v.company_id) ? 'bizum' then ' y Bizum' else '' end || ').', null, 'Sumied');
  return v_token;
end $$;


--
-- Name: conta_enlace_pago_pedido(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_pedido(p_token text, p_importe numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e public.conta_enlace_pago; v_pedido text; i int := 0;
begin
  select * into e from public.conta_enlace_pago where token = p_token and status = 'abierto';
  if e.id is null then raise exception 'Ese enlace no está abierto.' using errcode = 'P0002'; end if;
  loop
    i := i + 1;
    v_pedido := to_char(now() at time zone 'Europe/Madrid', 'YYMMDDHH24') || lpad(floor(random() * 10000)::int::text, 4, '0');
    begin
      insert into public.conta_enlace_pago_intento (pedido, enlace_id, proveedor, importe) values (v_pedido, e.id, 'redsys', p_importe);
      exit;
    exception when unique_violation then
      if i >= 20 then raise; end if;
    end;
  end loop;
  update public.conta_enlace_pago set sesion = 'redsys:' || v_pedido where id = e.id;
  return v_pedido;
end $$;


--
-- Name: conta_enlace_pago_sesion(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_sesion(p_token text, p_sesion text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.conta_enlace_pago set sesion = p_sesion where token = p_token and status = 'abierto'
$$;


--
-- Name: conta_enlace_pago_ver(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlace_pago_ver(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare e public.conta_enlace_pago; v public.customer_invoice; c record; co public.company; v_prov text;
begin
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then return jsonb_build_object('estado', 'no_existe'); end if;
  select * into e from public.conta_enlace_pago where token = p_token;
  if e.id is null then return jsonb_build_object('estado', 'no_existe'); end if;
  select * into v from public.customer_invoice where id = e.invoice_id;
  select * into c from public.conta_factura_cobro where invoice_id = e.invoice_id;
  select * into co from public.company where id = e.company_id;
  v_prov := public._s01_proveedor_enlace(e.company_id);
  if e.status = 'abierto' then
    update public.conta_enlace_pago set aperturas = aperturas + 1, abierto_at = now() where id = e.id;
  end if;
  return jsonb_build_object(
    'estado', case when e.status = 'pagado' then 'pagado' when e.status = 'anulado' then 'anulado'
                   when c.pendiente < 0.005 then 'cobrada' when v_prov is null then 'sin_cobro' else 'abierto' end,
    'empresa', coalesce(nullif(trim(co.trade_name), ''), co.legal_name), 'color', co.color,
    'factura', v.number_text, 'fecha', v.issue_date, 'vence', v.due_date, 'total', c.total, 'pendiente', c.pendiente,
    'proveedor', coalesce(e.proveedor, v_prov),
    'metodos', public._s01_metodos_enlace(e.company_id),
    'pagado', case when e.status = 'pagado' then jsonb_build_object('el', e.pagado_at, 'con', e.metodo, 'importe', e.importe) end);
end $_$;


--
-- Name: conta_enlaces_pago_resumen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_enlaces_pago_resumen(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', e.invoice_id, 'aperturas', e.aperturas, 'abierto', e.abierto_at))
                     from public.conta_enlace_pago e where e.company_id = p_company and e.status = 'abierto'), '[]'::jsonb);
end $$;


--
-- Name: conta_entrada_correo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_entrada_correo(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.inbound_email_log (email_id, to_address, from_address, subject, company_id, account_id, outcome, detail)
  values (p->>'email_id', p->>'to', p->>'from', left(p->>'subject', 500), nullif(p->>'company_id', '')::uuid,
          (select account_id from public.company where id = nullif(p->>'company_id', '')::uuid), p->>'resultado', coalesce(p->'detalle', '{}'::jsonb))
  on conflict (email_id) do update set outcome = excluded.outcome, detail = excluded.detail;
end $$;


--
-- Name: conta_entrada_destino(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_entrada_destino(p_local_part text, p_domain text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('company_id', a.company_id, 'account_id', a.account_id, 'activa', a.active, 'tipo', a.kind)
    from public.company_inbound_address a
   where lower(a.local_part) = lower(p_local_part) and lower(a.domain) = lower(p_domain)
$$;


--
-- Name: conta_entrada_llegada(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_entrada_llegada(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid := (p->>'account_id')::uuid;
  v_emp uuid := (p->>'company_id')::uuid;
  v_id uuid; v_ya uuid; v_ya_correo text;
begin
  if (select account_id from public.company where id = v_emp) is distinct from v_acc then
    raise exception 'La empresa no es de esa cuenta.' using errcode = '22023';
  end if;
  select id, email_id into v_ya, v_ya_correo from public.document_inbox
   where (p->>'sha256' is not null and account_id = v_acc and sha256 = p->>'sha256' and status <> 'descartado')
      or (email_id = p->>'email_id' and coalesce(file_name, '') = coalesce(p->>'nombre', '') and coalesce(link_url, '') = coalesce(p->>'enlace', ''))
   limit 1;
  if v_ya is not null then
    if coalesce(p->>'canal', 'correo') = 'correo' and p->>'email_id' is not null and v_ya_correo is distinct from p->>'email_id' then
      insert into public.document_activity (account_id, company_id, inbox_id, actor, action, text, detail)
      values (v_acc, v_emp, v_ya, 'folvy', 'repetida',
              'Ha vuelto a llegar por correo el ' || to_char(coalesce(nullif(p->>'recibido', '')::timestamptz, now()) at time zone 'Europe/Madrid', 'DD/MM/YYYY') ||
              ' el mismo fichero (' || coalesce(p->>'nombre', 'sin nombre') || '): ya estaba, no lo apunto dos veces.',
              jsonb_build_object('de', p->>'from', 'asunto', left(p->>'subject', 200), 'email_id', p->>'email_id'));
    end if;
    return jsonb_build_object('id', v_ya, 'ya_estaba', true);
  end if;
  insert into public.document_inbox (account_id, company_id, channel, status, email_id, email_to, email_from, email_subject, email_received_at,
                                     link_url, file_path, file_name, mime_type, size_bytes, sha256, reason)
  values (v_acc, v_emp, coalesce(p->>'canal', 'correo'),
          case when p->>'ruta' is null and p->>'enlace' is not null then 'falta_pdf' else 'recibido' end,
          p->>'email_id', p->>'to', p->>'from', left(p->>'subject', 500), nullif(p->>'recibido', '')::timestamptz,
          p->>'enlace', p->>'ruta', p->>'nombre', p->>'tipo', nullif(p->>'bytes', '')::int, p->>'sha256',
          case when p->>'ruta' is null and p->>'enlace' is not null then 'Falta el PDF: el correo trae un enlace. Bájalo y súbelo.' end)
  returning id into v_id;
  insert into public.document_activity (account_id, company_id, inbox_id, actor, action, text, detail)
  values (v_acc, v_emp, v_id, 'folvy', 'recibida',
          case when p->>'ruta' is null then 'Ha llegado un correo con un enlace y sin el PDF.' else 'Ha llegado ' || coalesce(p->>'nombre', 'un documento') || ' por correo.' end,
          jsonb_build_object('de', p->>'from', 'asunto', left(p->>'subject', 200)));
  return jsonb_build_object('id', v_id, 'ya_estaba', false);
end $$;


--
-- Name: conta_entrada_remitente(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_entrada_remitente(p_company uuid, p_from text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('decision', s.decision, 'motivo', s.reason, 'tipo', s.doc_kind)
    from public.company_inbound_sender s
   where s.company_id = p_company
     and s.sender_sha256 = encode(sha256(convert_to(lower(btrim(coalesce(substring(p_from from '<([^>]+)>'), p_from, ''))), 'UTF8')), 'hex')
$$;


--
-- Name: conta_entrada_tipo(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_entrada_tipo(p_inbox uuid, p_tipo text, p_por text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.document_inbox set doc_kind = p_tipo, doc_kind_by = p_por, updated_at = now()
   where id = p_inbox and (doc_kind_by is distinct from 'persona')
$$;


--
-- Name: conta_envio_aclarar(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_envio_aclarar(p_sale uuid, p_decision text, p_motivo text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s public.sale; v_e record; v_n int := 0; v_codigo text; v_empresa uuid;
begin
  select * into v_s from public.sale where id = p_sale;
  if v_s.id is null or not public.belongs_to_account(v_s.account_id) then raise exception 'Ese pedido no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_s.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta aclara un envío.' using errcode = '42501';
  end if;
  if p_decision is null or p_decision not in ('lo_paga', 'no_lo_paga') then
    raise exception 'Lo que dice la liquidación es «lo_paga» o «no_lo_paga».' using errcode = '22023';
  end if;
  if p_motivo is null or length(trim(p_motivo)) = 0 then raise exception 'Para aclarar un envío hay que decir de dónde sale (la liquidación).' using errcode = '23514'; end if;
  v_codigo := coalesce(v_s.platform_order_code, left(v_s.id::text, 8));
  -- Lo validado no se cambia aquí: se ajusta con su liquidación.
  for v_e in
    select e.id, e.status, e.company_id from public.sales_day_summary d join public.journal_entry e on e.id = d.entry_id and e.account_id = d.account_id
     where d.account_id = v_s.account_id and p_sale = any (d.sale_ids) and e.status not in ('anulado')
  loop
    if v_e.status = 'validado' then
      raise exception 'El pedido % está en un asiento ya validado: no se cambia aquí, se ajusta con su liquidación.', v_codigo using errcode = '23514';
    end if;
    v_empresa := v_e.company_id;
    delete from public.journal_entry where id = v_e.id and status in ('propuesto', 'borrador');
    get diagnostics v_n = row_count;
  end loop;
  if v_empresa is null then
    select c.id into v_empresa from public.company c where c.account_id = v_s.account_id order by c.created_at limit 1;
  end if;
  insert into public.conta_envio_aclarado (sale_id, account_id, company_id, decision, motivo, created_by, created_by_name)
  values (v_s.id, v_s.account_id, v_empresa, p_decision, trim(p_motivo), auth.uid(), coalesce(p_quien_nombre, public.conta_nombre_actor()))
  on conflict (sale_id) do update set decision = excluded.decision, motivo = excluded.motivo, created_at = now(),
    created_by = excluded.created_by, created_by_name = excluded.created_by_name;
  return jsonb_build_object('pedido', v_codigo, 'decision', p_decision, 'quitado', v_n > 0,
    'texto', 'Aclarado: el envío del pedido ' || v_codigo || case when p_decision = 'lo_paga' then ' lo paga la plataforma y va a Envíos cobrados.' else ' no lo paga la plataforma: sale de la venta y del cobro.' end
             || case when v_n > 0 then ' El asiento propuesto de ese día se ha quitado: el cierre del día lo vuelve a proponer (cada hora, a los 7 minutos).' else '' end);
end $$;


--
-- Name: FUNCTION conta_envio_aclarar(p_sale uuid, p_decision text, p_motivo text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_envio_aclarar(p_sale uuid, p_decision text, p_motivo text, p_quien_nombre text) IS 'C06b (16/10): apunta lo que dice la liquidación del envío de un pedido (lo_paga / no_lo_paga) y quita el asiento propuesto de su día para que el cierre lo vuelva a proponer. Lo validado no se toca.';


--
-- Name: conta_esperadas_aprender(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_esperadas_aprender(p_company uuid, p_hoy date DEFAULT ((now() AT TIME ZONE 'Europe/Madrid'::text))::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_n integer;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not (public.current_user_is_admin_or_manager_of(v_acc) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Solo un administrador o un encargado de la cuenta.' using errcode = '42501';
  end if;
  with meses as (select (date_trunc('month', p_hoy) - (n || ' month')::interval)::date m from generate_series(1, 3) n),
  por_mes as (
    select k.entity_id::uuid as supplier_id, date_trunc('month', e.entry_date)::date m, count(distinct e.id) n, max(extract(day from e.entry_date))::smallint dia
      from public.journal_entry e
      join public.journal_line l on l.entry_id = e.id and l.account_id = v_acc
      join public.company_account_link k on k.company_id = p_company and k.entity = 'supplier' and k.role = 'principal' and k.company_account_id = l.company_account_id
     where e.account_id = v_acc and e.company_id = p_company and e.series = 2 and e.status = 'validado'
       and e.entry_date >= (select min(m) from meses) and e.entry_date < date_trunc('month', p_hoy)::date
     group by 1, 2
  ),
  fijas as (select supplier_id, max(dia) dia from por_mes where n = 1 group by 1 having count(*) = 3)
  insert into public.supplier_expected_invoice (account_id, company_id, supplier_id, typical_day, source, reason, since)
  select v_acc, p_company, f.supplier_id, f.dia, 'aprendido',
         'Ha llegado una factura suya cada mes de los tres últimos meses.', (select min(m) from meses)
    from fijas f join public.supplier s on s.id = f.supplier_id and s.account_id = v_acc
  on conflict (company_id, supplier_id) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


--
-- Name: conta_esperadas_no_llegadas(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_esperadas_no_llegadas(p_company uuid, p_hoy date DEFAULT ((now() AT TIME ZONE 'Europe/Madrid'::text))::date) RETURNS TABLE(expected_id uuid, supplier_id uuid, supplier_name text, label text, periodo date, ultima date, pedida text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_mes date;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not (public.belongs_to_account(v_acc) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Esa empresa no está.' using errcode = 'P0002';
  end if;
  -- Antes del día 15 todavía se espera la del mes anterior; desde el 15, falta.
  v_mes := (date_trunc('month', p_hoy) - interval '1 month')::date;
  if extract(day from p_hoy) < 15 then return; end if;
  return query
  select x.id, x.supplier_id, s.name, coalesce(x.label, s.name), v_mes,
         greatest((select max(i.invoice_date) from public.supplier_invoice i where i.account_id = v_acc and i.supplier_id = x.supplier_id and i.status <> 'anulada'),
                  (select max(e.entry_date) from public.journal_entry e
                     join public.journal_line l on l.entry_id = e.id and l.account_id = v_acc
                     join public.company_account_link k on k.company_id = p_company and k.entity = 'supplier' and k.role = 'principal'
                                                        and k.entity_id = x.supplier_id::text and k.company_account_id = l.company_account_id
                    where e.account_id = v_acc and e.company_id = p_company and e.series = 2 and e.status = 'validado')),
         (select r.status from public.supplier_invoice_request r where r.supplier_id = x.supplier_id and r.period = v_mes order by r.created_at desc limit 1)
    from public.supplier_expected_invoice x
    join public.supplier s on s.id = x.supplier_id and s.account_id = v_acc
   where x.company_id = p_company and x.account_id = v_acc and x.active
     and not exists (select 1 from public.supplier_invoice i where i.account_id = v_acc and i.supplier_id = x.supplier_id and i.status <> 'anulada'
                        and i.invoice_date >= v_mes and i.invoice_date < (v_mes + interval '1 month')::date)
     and not exists (select 1 from public.journal_entry e
                       join public.journal_line l on l.entry_id = e.id and l.account_id = v_acc
                       join public.company_account_link k on k.company_id = p_company and k.entity = 'supplier' and k.role = 'principal'
                                                          and k.entity_id = x.supplier_id::text and k.company_account_id = l.company_account_id
                      where e.account_id = v_acc and e.company_id = p_company and e.series = 2 and e.status = 'validado'
                        and e.entry_date >= v_mes and e.entry_date < (v_mes + interval '1 month')::date)
   order by s.name;
end $$;


--
-- Name: conta_esperan(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_esperan(p_company uuid, p_desde date, p_hasta date) RETURNS TABLE(entry_id uuid, orden integer, codigo text, motivo text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select e.id, m.orden, m.codigo, m.motivo
    from public.journal_entry e
    join public.company c on c.id = e.company_id and c.account_id = e.account_id
   cross join lateral public.conta_motivos_para_validar(e.id) m
   where e.company_id = p_company
     and e.status in ('propuesto', 'borrador')
     and e.entry_date between p_desde and p_hasta
   order by e.entry_date, e.id, m.orden
$$;


--
-- Name: FUNCTION conta_esperan(p_company uuid, p_desde date, p_hasta date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_esperan(p_company uuid, p_desde date, p_hasta date) IS 'M01 (16/10): los asientos propuestos o en borrador de esas fechas que la validación pararía, con sus motivos (conta_motivos_para_validar). Lo lee la vista «Esperan» del libro diario. Solo lee.';


--
-- Name: conta_euros_exactos(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_euros_exactos(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select (case when p < 0 then '−' else '' end)
      || regexp_replace((floor(round(abs(p) * 100) / 100))::bigint::text, '(\d)(?=(\d{3})+$)', '\1.', 'g')
      || ',' || lpad((round(abs(p) * 100)::bigint % 100)::text, 2, '0') || ' €'
$_$;


--
-- Name: conta_factura_descartar(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_factura_descartar(p_invoice uuid, p_motivo text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_f public.supplier_invoice; v_act uuid; v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
begin
  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then
    raise exception 'Esa factura no está.' using errcode = 'P0002';
  end if;
  if length(trim(coalesce(p_motivo, ''))) = 0 then raise exception 'Dime por qué no es una factura.' using errcode = '22023'; end if;
  if v_f.status = 'descartada' then raise exception 'Ya estaba descartada.' using errcode = '22023'; end if;
  if v_f.status in ('pagada', 'anulada') then
    raise exception 'Está %: no se descarta.', v_f.status using errcode = '22023';
  end if;
  if exists (select 1 from public.journal_entry e where e.account_id = v_f.account_id and e.source_type = 'supplier_invoice' and e.source_id = v_f.id
              and e.status in ('propuesto', 'borrador', 'validado')) then
    raise exception 'Tiene su asiento: anúlalo o descártalo en el libro antes.' using errcode = '22023';
  end if;
  if exists (select 1 from public.bank_match_item i join public.bank_match b on b.id = i.match_id
              where i.supplier_invoice_id = v_f.id and b.status = 'vivo') then
    raise exception 'Tiene un pago casado en Bancos: deshazlo allí antes.' using errcode = '22023';
  end if;
  update public.supplier_invoice
     set status_before_discard = status, status = 'descartada', discarded_at = now(), discarded_by = auth.uid(),
         discarded_by_name = v_quien, discard_reason = trim(p_motivo), updated_at = now()
   where id = v_f.id;
  insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, actor_name, action, text, detail)
  values (v_f.account_id, v_f.company_id, v_f.inbox_id, v_f.id, 'persona', v_quien, 'descartada',
          'No es una factura: ' || trim(p_motivo) || '.', jsonb_build_object('antes', v_f.status))
  returning id into v_act;
  return jsonb_build_object('id', v_f.id, 'antes', v_f.status, 'actividad', v_act);
end $$;


--
-- Name: FUNCTION conta_factura_descartar(p_invoice uuid, p_motivo text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_factura_descartar(p_invoice uuid, p_motivo text, p_quien_nombre text) IS 'S01 (0160): «No es una factura». La deja descartada con su motivo, quién y cuándo, y lo apunta en document_activity. Se deshace con conta_factura_recuperar.';


--
-- Name: conta_factura_desde_lectura(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_factura_desde_lectura(p_inbox uuid, p_session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_in public.document_inbox;
  v_s record;
  l jsonb; f jsonb;
  v_nif text; v_prov uuid; v_rep record; v_fac uuid; v_conf text; v_texto text;
  v_doc text; v_total numeric; v_estado text; v_validada boolean;
  v_forma text; v_iban text;
  -- S01l · La retención leída.
  v_ret_imp numeric; v_ret_pct numeric; v_ret_base numeric; v_ret_fecha date; v_ret_ids uuid[]; v_ret_id uuid; v_ret_aviso text;
begin
  select * into v_in from public.document_inbox where id = p_inbox for update;
  if v_in.id is null then raise exception 'Esa llegada no está.' using errcode = 'P0002'; end if;
  if not (coalesce(auth.role(), '') = 'service_role' or public.current_user_is_admin_or_manager_of(v_in.account_id)) then
    raise exception 'Solo un administrador o un encargado de la cuenta.' using errcode = '42501';
  end if;
  if v_in.supplier_invoice_id is not null then
    return jsonb_build_object('estado', 'factura', 'factura_id', v_in.supplier_invoice_id, 'texto', 'Ya tenía su factura.');
  end if;
  select s.id, s.validation, s.parsed_result into v_s from public.goods_receipt_ai_session s where s.id = p_session and s.account_id = v_in.account_id;
  if v_s.id is null then raise exception 'Esa lectura no es de esta cuenta.' using errcode = 'P0002'; end if;
  l := v_s.validation->'factura';
  if l is null then raise exception 'La lectura no se hizo con el modo factura.' using errcode = '22023'; end if;
  f := l->'factura';

  -- ¿Es una factura? Sin número, ni total, ni bases, no lo es.
  if f->>'numero' is null and f->>'total' is null and coalesce(jsonb_array_length(f->'tipos'), 0) = 0 then
    update public.document_inbox set status = 'no_es_factura', ai_session_id = p_session, reason = 'No he leído número, total ni bases: no parece una factura.', updated_at = now() where id = p_inbox;
    return jsonb_build_object('estado', 'no_es_factura', 'texto', 'No parece una factura: no trae número, total ni bases.');
  end if;

  -- El proveedor, por su NIF, en la cuenta.
  v_nif := f->'proveedor'->>'nif';
  select s.id into v_prov from public.supplier s
   where s.account_id = v_in.account_id and s.archived_at is null and v_nif is not null
     and regexp_replace(upper(regexp_replace(coalesce(s.tax_id, ''), '[^A-Za-z0-9]', '', 'g')), '^ES(?=[A-Z0-9]{9}$)', '') = v_nif
   order by s.created_at limit 1;

  -- ¿Repetida?
  select * into v_rep from public.supplier_invoice_repetida(v_in.account_id, v_prov, v_nif, f->>'numero', nullif(f->>'fecha', '')::date, nullif(f->>'total', '')::numeric) limit 1;
  if v_rep.nivel = 'repetida' then
    -- D06 · El PDF bueno de una que entró con foto (o sin documento): el mismo proveedor, el mismo
    -- número y el mismo total. Ocupa el sitio de la foto, que queda en su historial como documento
    -- anterior, y no se crea otra factura. No con su asiento validado: su documento va con el asiento.
    select i.raw_document_url, i.grand_total, i.status,
           exists (select 1 from public.journal_entry e where e.account_id = i.account_id and e.source_type = 'supplier_invoice'
                     and e.source_id = i.id and e.status = 'validado')
      into v_doc, v_total, v_estado, v_validada
      from public.supplier_invoice i where i.id = v_rep.invoice_id and i.account_id = v_in.account_id for update;
    if v_in.file_path is not null and (v_in.mime_type = 'application/pdf' or v_in.file_path ~* '\.pdf$')
       and (v_doc is null or v_doc ~* '\.(jpe?g|png|webp|heic|heif)$')
       and v_total is not null and round(v_total, 2) = round(nullif(f->>'total', '')::numeric, 2)
       and v_estado not in ('anulada', 'descartada') and not v_validada then
      update public.supplier_invoice
         set raw_document_url = v_in.file_path, no_document_at = null, no_document_reason = null, no_document_by_name = null, updated_at = now()
       where id = v_rep.invoice_id;
      -- El D02: el PDF hecho de la foto ya no vale; la pasada del minuto mira el nuevo (un PDF no se convierte).
      delete from public.conta_recibida_pdf r where r.invoice_id = v_rep.invoice_id;
      insert into public.supplier_invoice_change (account_id, supplier_invoice_id, by_name, what, cambios)
      values (v_in.account_id, v_rep.invoice_id, 'Folvy', 'papel',
              jsonb_build_array(jsonb_build_object('campo', 'documento', 'antes', v_doc, 'ahora', v_in.file_path,
                                                   'nombre', regexp_replace(v_in.file_path, '^.*/', ''), 'motivo', 'pdf_sustituye_foto')));
      update public.document_inbox set status = 'repetida', ai_session_id = p_session, duplicate_of_invoice_id = v_rep.invoice_id,
             reason = 'Es el PDF de la ' || coalesce(v_rep.invoice_number, 'factura') || ', que había entrado ' ||
                      case when v_doc is null then 'sin documento' else 'con una foto' end || ': lo pongo en su lugar' ||
                      case when v_doc is null then '.' else ' y la foto queda en su historial.' end, updated_at = now()
       where id = p_inbox;
      insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text, detail)
      values (v_in.account_id, v_in.company_id, p_inbox, v_rep.invoice_id, 'folvy', 'corregida',
              'Ha llegado el PDF de la ' || coalesce(v_rep.invoice_number, 'factura') || ': sustituye ' ||
              case when v_doc is null then 'a la falta de documento' else 'a la foto, que queda como documento anterior' end || '. No es otra factura.',
              jsonb_build_object('pdf_sustituye_foto', true, 'antes', v_doc, 'ahora', v_in.file_path));
      return jsonb_build_object('estado', 'pdf_sustituye_foto', 'factura_id', v_rep.invoice_id,
        'texto', 'Es el PDF de la ' || coalesce(v_rep.invoice_number, 'factura') || ': ' ||
                 case when v_doc is null then 'ya tiene su documento' else 'sustituye a la foto, que queda en su historial' end || '. No se crea otra factura.');
    end if;
    update public.document_inbox set status = 'repetida', ai_session_id = p_session, duplicate_of_invoice_id = v_rep.invoice_id,
           reason = 'Ya está: el mismo proveedor y el mismo número (' || coalesce(v_rep.invoice_number, '') || '). No la apunto dos veces.', updated_at = now()
     where id = p_inbox;
    insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text)
    values (v_in.account_id, v_in.company_id, p_inbox, v_rep.invoice_id, 'folvy', 'repetida', 'Repetida: ya estaba la ' || coalesce(v_rep.invoice_number, 'factura') || '. No la he apuntado dos veces.');
    return jsonb_build_object('estado', 'repetida', 'factura_id', v_rep.invoice_id, 'texto', 'Ya estaba la ' || coalesce(v_rep.invoice_number, 'factura') || ': no se apunta dos veces.');
  end if;

  v_conf := case when v_prov is null then 'duda' else l->>'confianza' end;
  -- PC01 · E2b · La forma de pago y el IBAN que trae el papel. El IBAN solo se guarda si es para
  -- pagarle por transferencia (o no lo dice), pasa el control y no es de una cuenta nuestra: en una
  -- domiciliada, o con tarjeta o al contado, el IBAN que sale suele ser el NUESTRO, el del cargo.
  v_forma := case when f->>'forma' in ('transfer', 'direct_debit', 'card', 'cash') then f->>'forma' end;
  v_iban := public._pc01e2_iban(f->>'iban');
  if v_iban is not null and (coalesce(v_forma, 'transfer') <> 'transfer' or not public._pc01e2b_iban_valido(v_iban)
     or exists (select 1 from public.treasury_account t where t.account_id = v_in.account_id and public._pc01e2_iban(t.iban) = v_iban)) then
    v_iban := null;
  end if;

  -- S01l · La retención: con su tipo (el leído, o el que da base × tipo = importe), o ninguna y en revisión.
  v_ret_imp := abs(nullif(f->'retencion'->>'importe', '')::numeric);
  if coalesce(v_ret_imp, 0) = 0 then
    v_ret_imp := null;
  else
    v_ret_pct := abs(nullif(f->'retencion'->>'tipo', '')::numeric);
    v_ret_base := abs(nullif(f->>'base', '')::numeric);
    v_ret_fecha := coalesce(nullif(f->>'fecha', '')::date, current_date);
    select array_agg(r.id order by r.sort_order, r.code) into v_ret_ids
      from public.withholding_rate r
     where (r.is_system or r.account_id = v_in.account_id) and r.code <> 'capital' and r.rate > 0
       and (r.valid_from is null or r.valid_from <= v_ret_fecha) and (r.valid_to is null or r.valid_to >= v_ret_fecha)
       and case when v_ret_pct is not null
                then abs(r.rate - v_ret_pct) < 0.005 and (v_ret_base is null or abs(round(v_ret_base * r.rate / 100, 2) - v_ret_imp) <= 0.01)
                else v_ret_base is not null and abs(round(v_ret_base * r.rate / 100, 2) - v_ret_imp) <= 0.01 end;
    if coalesce(cardinality(v_ret_ids), 0) = 1 then
      v_ret_id := v_ret_ids[1];
    else
      v_ret_aviso := format('La factura trae una retención de %s: elige su tipo.', public.conta_euros_exactos(v_ret_imp));
      v_ret_imp := null;
    end if;
  end if;

  insert into public.supplier_invoice (account_id, company_id, supplier_id, doc_kind, invoice_number, invoice_date, due_date, status, source, ai_session_id,
                                       raw_document_url, tax_base_total, tax_total, surcharge_total, grand_total, withholding_amount, withholding_rate_id,
                                       needs_review, notes, created_by_name, arrival_channel, reading, reading_confidence, inbox_id,
                                       read_iban, payment_method)
  values (v_in.account_id, v_in.company_id, v_prov,
          case when f->>'clase' = 'rectificativa' or nullif(f->>'total', '')::numeric < 0 then 'credit_note' else 'invoice' end,
          f->>'numero', nullif(f->>'fecha', '')::date, nullif(f->>'vencimiento', '')::date, 'en_revision', 'ocr', p_session,
          v_in.file_path, nullif(f->>'base', '')::numeric, nullif(f->>'cuota', '')::numeric, nullif(f->>'recargo', '')::numeric, nullif(f->>'total', '')::numeric,
          v_ret_imp, v_ret_id,
          v_conf <> 'seguro' or v_ret_aviso is not null,
          nullif(concat_ws(' ',
            case when v_rep.nivel = 'posible' then '¿Repetida? El mismo proveedor, la misma fecha y el mismo total que la ' || coalesce(v_rep.invoice_number, 'sin número') || '.' end,
            v_ret_aviso), ''),
          'Folvy', v_in.channel, l, v_conf, p_inbox,
          v_iban, v_forma)
  returning id into v_fac;
  insert into public.supplier_invoice_tax (account_id, supplier_invoice_id, vat_pct, base, vat_amount, surcharge_pct, surcharge_amount)
  select v_in.account_id, v_fac, (t->>'tipo')::numeric, (t->>'base')::numeric, (t->>'cuota')::numeric, nullif(t->>'recargoTipo', '')::numeric, coalesce(nullif(t->>'recargo', '')::numeric, 0)
    from jsonb_array_elements(coalesce(f->'tipos', '[]'::jsonb)) t;
  insert into public.supplier_invoice_line (supplier_invoice_id, raw_text, qty, unit_price, line_amount, vat_pct, position)
  select v_fac, coalesce(x->>'raw_text', '—'), nullif(x->>'quantity', '')::numeric, nullif(x->>'unit_price_net', '')::numeric,
         nullif(x->>'line_amount', '')::numeric, nullif(x->>'vat_pct', '')::numeric, o::int
    from jsonb_array_elements(coalesce(v_s.parsed_result->'lines', '[]'::jsonb)) with ordinality as e(x, o);

  update public.document_inbox set status = 'factura', ai_session_id = p_session, supplier_invoice_id = v_fac,
         reason = case when v_prov is null then 'No tengo a este proveedor: lo doy de alta con lo leído si me dices que sí.' end, updated_at = now()
   where id = p_inbox;
  v_texto := 'He leído la ' || coalesce(f->>'numero', 'factura') || coalesce(' de ' || (f->'proveedor'->>'nombre'), '') ||
             case v_conf when 'seguro' then ': todo cuadra.' when 'probable' then ': cuadra, pero hay algo que mirar.' else ': hay algo que aclarar.' end ||
             coalesce(' ' || v_ret_aviso, '');
  insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text, detail)
  values (v_in.account_id, v_in.company_id, p_inbox, v_fac, 'folvy', 'leida', v_texto, jsonb_build_object('confianza', v_conf, 'porque', l->'porque'));
  if v_prov is null then
    insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text)
    values (v_in.account_id, v_in.company_id, p_inbox, v_fac, 'folvy', 'proveedor_propuesto',
            'No tengo a ' || coalesce(f->'proveedor'->>'nombre', 'este proveedor') || coalesce(' (NIF ' || v_nif || ')', '') || ': lo doy de alta con lo leído si me dices que sí.');
  end if;
  return jsonb_build_object('estado', 'factura', 'factura_id', v_fac, 'confianza', v_conf, 'texto', v_texto, 'proveedor_nuevo', v_prov is null, 'posible_repetida', v_rep.nivel = 'posible',
                            'retencion_sin_tipo', v_ret_aviso is not null);
end $_$;


--
-- Name: conta_factura_es_de_plataforma(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_factura_es_de_plataforma(p_invoice uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select public.conta_canal_de_factura(p_invoice) is not null
$$;


--
-- Name: conta_factura_para_revisar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_factura_para_revisar(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_i public.supplier_invoice;
  v_company uuid;
  v_apr jsonb;
begin
  select * into v_i from public.supplier_invoice where id = p_invoice;
  if v_i.id is null or not public.belongs_to_account(v_i.account_id) then
    raise exception 'Esa factura no está.' using errcode = 'P0002';
  end if;
  v_company := coalesce(v_i.company_id, (select id from public.company where account_id = v_i.account_id order by created_at limit 1));
  -- Lo aprendido de sus facturas anteriores (0250): de ahí sale el origen de
  -- verdad, «aprendido de Diez» o «aprendido de tus facturas» (la más reciente).
  if v_i.supplier_id is not null and v_company is not null then
    v_apr := public.conta_gasto_aprendido(v_company, v_i.supplier_id);
  end if;
  return jsonb_build_object(
    'id', v_i.id, 'account_id', v_i.account_id, 'company_id', v_company, 'estado', v_i.status,
    'numero', v_i.invoice_number, 'fecha', v_i.invoice_date, 'vence', v_i.due_date, 'clase', v_i.doc_kind,
    'base', v_i.tax_base_total, 'cuota', v_i.tax_total, 'recargo', v_i.surcharge_total, 'retencion', v_i.withholding_amount, 'total', v_i.grand_total,
    'canal', v_i.arrival_channel, 'confianza', v_i.reading_confidence, 'lectura', v_i.reading,
    -- R6 · Lo que leyó la recepción con su papel, si la factura salió de ella
    -- (Compras, 0140) y no trae lectura propia: la pantalla comprueba eso, sin
    -- volver a leerla con el modelo.
    'leido_en_recepcion', case when v_i.reading is null then (
        select jsonb_build_object('modelo', a.parsed_result, 'cuando', a.created_at, 'recepcion', gr.receipt_date)
          from public.supplier_invoice_receipt r join public.goods_receipt gr on gr.id = r.goods_receipt_id and gr.account_id = v_i.account_id
          join public.goods_receipt_ai_session a on a.id = gr.ai_session_id and a.account_id = gr.account_id
         where r.supplier_invoice_id = v_i.id and a.parsed_result->'document'->>'doc_type' in ('factura', 'albaran_factura')
         order by gr.receipt_date desc limit 1) end,
    'no_repetida', v_i.not_duplicate_confirmed_at is not null,
    'tipos', coalesce((select jsonb_agg(jsonb_build_object('tipo', t.vat_pct, 'base', t.base, 'cuota', t.vat_amount, 'recargo', t.surcharge_amount) order by t.vat_pct desc)
                         from public.supplier_invoice_tax t where t.supplier_invoice_id = v_i.id), '[]'::jsonb),
    'lineas', coalesce((select jsonb_agg(jsonb_build_object('texto', l.raw_text, 'cantidad', l.qty, 'importe', l.line_amount, 'iva', l.vat_pct) order by l.position nulls last, l.created_at)
                          from public.supplier_invoice_line l where l.supplier_invoice_id = v_i.id), '[]'::jsonb),
    'proveedor', (select jsonb_build_object(
        'id', s.id, 'nombre', s.name, 'razon', s.legal_name, 'nif', s.tax_id,
        'subcuenta', (select a.code from public.company_account_link k join public.company_account a on a.id = k.company_account_id
                       where k.company_id = v_company and k.entity = 'supplier' and k.entity_id = s.id::text and k.role = 'principal' limit 1),
        -- «Sus facturas se apuntan en», con su origen dicho para una persona.
        -- Con cuenta en la ficha: si se puso aceptando lo aprendido y sigue
        -- siendo lo aprendido, el origen es el de la historia (Diez o tus
        -- facturas); si la eligió una persona, «elegida en su ficha». Sin
        -- cuenta en la ficha, lo aprendido tal cual.
        'gasto', coalesce(
          (select jsonb_build_object('cuenta', a.code, 'nombre', a.name,
                    'origen', case when k.source in ('ai_accepted', 'aprendido_diez') and v_apr->>'cuenta' = a.code then v_apr->>'origen'
                                   when k.source = 'manual' then 'elegida en su ficha' else 'de su ficha' end)
             from public.company_account_link k join public.company_account a on a.id = k.company_account_id
            where k.company_id = v_company and k.entity = 'supplier' and k.entity_id = s.id::text and k.role = 'gasto' limit 1),
          case when v_apr->>'cuenta' is not null then jsonb_build_object('cuenta', v_apr->>'cuenta', 'nombre', v_apr->>'nombre', 'origen', v_apr->>'origen') end),
        'facturacion', (select jsonb_build_object('nombre', c.name, 'email', c.email) from public.supplier_contact c
                         where c.supplier_id = s.id and c.account_id = s.account_id and c.role = 'billing' and c.email is not null order by c.created_at limit 1))
      from public.supplier s where s.id = v_i.supplier_id and s.account_id = v_i.account_id),
    'propuesto', case when v_i.supplier_id is null then jsonb_build_object('nombre', v_i.reading->'factura'->'proveedor'->>'nombre', 'nif', v_i.reading->'factura'->'proveedor'->>'nif') end,
    'llegada', (select jsonb_build_object('canal', d.channel, 'archivo', d.file_name, 'ruta', d.file_path, 'tipo', d.mime_type, 'de', d.email_from, 'a', d.email_to, 'cuando', d.created_at)
                  from public.document_inbox d where d.id = v_i.inbox_id and d.account_id = v_i.account_id),
    'papel', v_i.raw_document_url,
    'recepcion', (select jsonb_build_object('fecha', gr.receipt_date, 'local', l.name)
                    from public.supplier_invoice_receipt r join public.goods_receipt gr on gr.id = r.goods_receipt_id
                    left join public.locations l on l.id = gr.location_id
                   where r.supplier_invoice_id = v_i.id order by gr.receipt_date desc limit 1),
    'asiento', (select jsonb_build_object('id', e.id, 'estado', e.status, 'numero', e.number)
                  from public.journal_entry e
                 where e.account_id = v_i.account_id and e.source_type = 'supplier_invoice' and e.source_id = v_i.id and e.status in ('propuesto', 'borrador', 'validado')
                 order by (e.status = 'validado') desc, e.created_at desc limit 1));
end $$;


--
-- Name: FUNCTION conta_factura_para_revisar(p_invoice uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_factura_para_revisar(p_invoice uuid) IS 'D01 · N23: todo lo de una factura recibida para revisarla (lo leído, o lo que leyó su recepción, su proveedor con «Sus facturas se apuntan en» y su contacto de Facturación, su llegada y fichero, su recepción y su asiento). Solo para los de la cuenta.';


--
-- Name: conta_factura_pedir(uuid, uuid, date, text, text, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_factura_pedir(p_company uuid, p_supplier uuid, p_periodo date, p_email text, p_contacto text, p_guardar_contacto boolean, p_asunto text, p_cuerpo text, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_acc uuid;
  v_id uuid;
  v_mes date := date_trunc('month', p_periodo)::date;
  v_email text := lower(trim(coalesce(p_email, '')));
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta pide facturas.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.supplier where id = p_supplier and account_id = v_acc) then
    raise exception 'Ese proveedor no es de esta cuenta.' using errcode = '42501';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Esa dirección de correo no es válida.' using errcode = '22023'; end if;
  if coalesce(trim(p_quien_nombre), '') = '' then raise exception 'Falta quién la pide: sin persona no se confirma.' using errcode = '22023'; end if;

  select id into v_id from public.supplier_invoice_request
   where supplier_id = p_supplier and period = v_mes and status in ('confirmado', 'enviado');
  if v_id is not null then return jsonb_build_object('id', v_id, 'ya_estaba', true); end if;

  if p_guardar_contacto and not exists (select 1 from public.supplier_contact where supplier_id = p_supplier and lower(email) = v_email) then
    insert into public.supplier_contact (account_id, supplier_id, name, role, email, created_by, created_by_name)
    values (v_acc, p_supplier, coalesce(nullif(trim(p_contacto), ''), 'Facturación'), 'billing', v_email, auth.uid(), p_quien_nombre);
  end if;
  insert into public.supplier_invoice_request (account_id, company_id, supplier_id, expected_id, period, to_email, subject, body, status, confirmed_at, confirmed_by, confirmed_by_name)
  values (v_acc, p_company, p_supplier,
          (select id from public.supplier_expected_invoice where company_id = p_company and supplier_id = p_supplier),
          v_mes, v_email, p_asunto, p_cuerpo, 'confirmado', now(), auth.uid(), p_quien_nombre)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'ya_estaba', false);
end $_$;


--
-- Name: FUNCTION conta_factura_pedir(p_company uuid, p_supplier uuid, p_periodo date, p_email text, p_contacto text, p_guardar_contacto boolean, p_asunto text, p_cuerpo text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_factura_pedir(p_company uuid, p_supplier uuid, p_periodo date, p_email text, p_contacto text, p_guardar_contacto boolean, p_asunto text, p_cuerpo text, p_quien_nombre text) IS 'D01 · «Pedírselas»: guarda la petición CONFIRMADA por la persona (una por proveedor y mes) y, si lo pide, la dirección como contacto de Facturación. No envía: el correo lo manda la persona mientras no haya dominio.';


--
-- Name: conta_factura_recuperar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_factura_recuperar(p_invoice uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_f public.supplier_invoice; v_desc uuid; v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
begin
  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then
    raise exception 'Esa factura no está.' using errcode = 'P0002';
  end if;
  if v_f.status <> 'descartada' then raise exception 'No está descartada.' using errcode = '22023'; end if;
  -- Vuelve al estado de antes. Si ya hay otra igual, el disparador de repetidas lo para (23505).
  update public.supplier_invoice
     set status = v_f.status_before_discard, status_before_discard = null, discarded_at = null, discarded_by = null,
         discarded_by_name = null, discard_reason = null, updated_at = now()
   where id = v_f.id;
  select id into v_desc from public.document_activity
   where supplier_invoice_id = v_f.id and action = 'descartada' order by created_at desc limit 1;
  insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, actor_name, action, text, detail, undo_of)
  values (v_f.account_id, v_f.company_id, v_f.inbox_id, v_f.id, 'persona', v_quien, 'deshecha',
          'Era una factura: vuelve a «' || v_f.status_before_discard || '» (la había descartado ' || coalesce(v_f.discarded_by_name, 'una persona')
            || ' el ' || to_char(v_f.discarded_at at time zone 'Europe/Madrid', 'DD/MM/YYYY') || ': ' || v_f.discard_reason || ').',
          jsonb_build_object('vuelve_a', v_f.status_before_discard, 'motivo', v_f.discard_reason), v_desc);
  return jsonb_build_object('id', v_f.id, 'estado', v_f.status_before_discard);
end $$;


--
-- Name: FUNCTION conta_factura_recuperar(p_invoice uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_factura_recuperar(p_invoice uuid, p_quien_nombre text) IS 'S01 (0160): deshace «No es una factura»: vuelve al estado de antes y lo apunta en document_activity (deshecha, con undo_of).';


--
-- Name: conta_factura_tiene_liquidacion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_factura_tiene_liquidacion(p_invoice uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with f as (
    select ci.id, ci.account_id, public.conta_canal_de_factura(ci.id) as canal,
           coalesce(s.sales_day, ci.issue_date) as dia, s.location_id, s.sale_ids
      from public.customer_invoice ci
      left join lateral (select sm.sales_day, sm.location_id, sm.sale_ids from public.sales_day_summary sm
                          where sm.entry_id = ci.entry_id and sm.company_id = ci.company_id and sm.channel_id is not null limit 1) s on true
     where ci.id = p_invoice
  ), liq as (
    select coalesce(cs.location_id, st.location_id) as loc, coalesce(cs.brand_id, st.brand_id) as marca
      from f join public.channel_settlement cs on cs.account_id = f.account_id and cs.channel_id = f.canal
                and f.dia between cs.period_from and cs.period_to
      left join public.platform_store st on st.id = cs.store_id and st.account_id = cs.account_id
     where f.location_id is null or coalesce(cs.location_id, st.location_id) is null or coalesce(cs.location_id, st.location_id) = f.location_id
  )
  select case
           when coalesce(cardinality(f.sale_ids), 0) > 0 then
             not exists (select 1 from public.sale sa
                          where sa.id = any(f.sale_ids) and sa.account_id = f.account_id
                            and not exists (select 1 from liq where liq.marca is null or liq.marca = sa.brand_id))
           else exists (select 1 from public.customer_invoice_payment p where p.invoice_id = f.id and p.settlement_id is not null)
                or exists (select 1 from liq)
         end
    from f
$$;


--
-- Name: FUNCTION conta_factura_tiene_liquidacion(p_invoice uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_factura_tiene_liquidacion(p_invoice uuid) IS 'PC01 · Si a una factura de plataforma le ha llegado su liquidación: cada marca con pedidos en su cierre tiene una de su canal, periodo y local. Si no, pasado su plazo, sale «Falta su liquidación» y no «Vencida» (Julio, 25/10).';


--
-- Name: conta_fijar_corte(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_fijar_corte(p_company uuid, p_hasta date, p_programa text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_n int := 0; r record; m date;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.current_user_is_admin_of(v_cuenta) then
    raise exception 'Solo un administrador de la cuenta fija la fecha de corte.' using errcode = '42501';
  end if;
  if p_programa is null or length(trim(p_programa)) = 0 then raise exception 'Hay que decir de qué programa se trae.' using errcode = '23514'; end if;
  if exists (select 1 from public.journal_entry where company_id = p_company and source_type = 'migrated') then
    raise exception 'Ya hay asientos traídos: la fecha de corte no se cambia.' using errcode = '23514';
  end if;
  -- Lo que dejó un corte anterior se quita (solo los cierres de mes «traídos»).
  delete from public.fiscal_period_lock where company_id = p_company and kind = 'migrated';
  for r in select * from public.fiscal_year where company_id = p_company order by starts_on loop
    update public.fiscal_year set
      origin = case when p_hasta is null or p_hasta < r.starts_on then 'folvy' when p_hasta >= r.ends_on then 'migrated' else 'mixed' end,
      origin_program = case when p_hasta is null or p_hasta < r.starts_on then null else trim(p_programa) end,
      imported_until = case when p_hasta is null or p_hasta < r.starts_on or p_hasta >= r.ends_on then null else p_hasta end
     where id = r.id;
    if p_hasta is not null and p_hasta >= r.starts_on then
      for m in select generate_series(date_trunc('month', r.starts_on), date_trunc('month', least(p_hasta, r.ends_on)), interval '1 month')::date loop
        -- Solo los meses enteros traídos se cierran (el del corte, si no acaba ese día, sigue abierto desde el día siguiente).
        if (m + interval '1 month' - interval '1 day')::date <= p_hasta
           and not exists (select 1 from public.fiscal_period_lock l where l.company_id = p_company and l.month = m and l.reopened_at is null) then
          insert into public.fiscal_period_lock (account_id, company_id, fiscal_year_id, month, kind, locked_by, locked_by_name)
          values (v_cuenta, p_company, r.id, m, 'migrated', auth.uid(), public.conta_nombre_actor());
          v_n := v_n + 1;
        end if;
      end loop;
    end if;
  end loop;
  return jsonb_build_object('hasta', p_hasta, 'programa', p_programa, 'meses_cerrados', v_n);
end $$;


--
-- Name: conta_fila_serie_ok(boolean, uuid, uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_fila_serie_ok(p_is_system boolean, p_account uuid, p_company uuid, p_legal_ref text, p_verified date, p_source text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_is_system
    then p_account is null and p_company is null and p_legal_ref is not null and p_verified is not null and p_source is not null
    else p_account is not null and p_company is not null end
$$;


--
-- Name: conta_gasto_aprendido(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_gasto_aprendido(p_company uuid, p_supplier uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid;
  v_prov uuid;
  v_total int;
  v_top record;
  v_n_cuentas int;
  v_reparto jsonb;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not (public.belongs_to_account(v_acc) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;
  -- La subcuenta del proveedor (400/410), la de su ficha.
  select k.company_account_id into v_prov from public.company_account_link k
   where k.company_id = p_company and k.account_id = v_acc and k.entity = 'supplier' and k.entity_id = p_supplier::text and k.role = 'principal';
  if v_prov is null then
    return jsonb_build_object('cuenta', null, 'porque', 'El proveedor no tiene su subcuenta en el plan: no hay historia que mirar.');
  end if;

  with facturas as (
    select e.id, e.entry_date, e.created_at, e.external_program from public.journal_entry e
     where e.account_id = v_acc and e.company_id = p_company and e.series = 2 and e.status = 'validado'
       and exists (select 1 from public.journal_line l where l.entry_id = e.id and l.company_account_id = v_prov and l.credit > 0)
  ), gasto as (
    select f.id, f.entry_date, f.created_at, f.external_program, a.id as cuenta_id, a.code, a.name
      from facturas f join public.journal_line l on l.entry_id = f.id and l.debit > 0
      join public.company_account a on a.id = l.company_account_id and a.company_id = p_company and a.code like '6%'
     group by f.id, f.entry_date, f.created_at, f.external_program, a.id, a.code, a.name
  ), por_cuenta as (
    -- De dónde vino de verdad: la factura MÁS RECIENTE de esa cuenta manda
    -- (traída de Diez, o apuntada en Folvy).
    select g.cuenta_id, g.code, g.name, count(distinct g.id) as n, max(g.entry_date) as ultima,
           (array_agg(case when g.external_program = 'diez' then 'aprendido de Diez' else 'aprendido de tus facturas' end
                      order by g.entry_date desc, g.created_at desc))[1] as origen
      from gasto g group by 1, 2, 3
  )
  select (select count(distinct id) from gasto),
         (select count(*) from por_cuenta),
         (select jsonb_agg(jsonb_build_object('cuenta', code, 'nombre', name, 'facturas', n, 'ultima', ultima, 'origen', origen) order by ultima desc, n desc) from por_cuenta)
    into v_total, v_n_cuentas, v_reparto;

  if coalesce(v_total, 0) = 0 then
    return jsonb_build_object('cuenta', null, 'facturas', 0, 'porque', 'No hay facturas anteriores de este proveedor en el libro: no hay nada que aprender.');
  end if;
  -- La más reciente manda (si fueron a varias, es la que vale hoy).
  select x->>'cuenta' as code, x->>'nombre' as name, (x->>'facturas')::int as n, x->>'origen' as origen into v_top from jsonb_array_elements(v_reparto) x limit 1;
  return jsonb_build_object(
    'cuenta', v_top.code,
    'cuenta_id', (select id from public.company_account where company_id = p_company and code = v_top.code),
    'nombre', v_top.name,
    'facturas', v_total,
    'confianza', case when v_n_cuentas = 1 then 'seguro' else 'probable' end,
    'origen', v_top.origen,
    'reparto', v_reparto,
    'porque', case
      when v_n_cuentas = 1 and v_total = 1 then format('La factura anterior de este proveedor fue a %s · %s.', v_top.name, v_top.code)
      when v_n_cuentas = 1 then format('Las %s facturas anteriores de este proveedor fueron a %s · %s.', v_total, v_top.name, v_top.code)
      else format('Las %s facturas anteriores de este proveedor fueron a %s cuentas; la más reciente, a %s · %s (%s de %s). Probable, no segura: confírmalo.',
                  v_total, v_n_cuentas, v_top.name, v_top.code, v_top.n, v_total) end);
end $$;


--
-- Name: FUNCTION conta_gasto_aprendido(p_company uuid, p_supplier uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_gasto_aprendido(p_company uuid, p_supplier uuid) IS 'D01 · La cuenta de gasto aprendida de las facturas anteriores del proveedor (serie 2, validadas), con su porqué y su origen de verdad: «aprendido de Diez» o «aprendido de tus facturas», el de la más reciente. Seguro si fueron todas a una; si a varias, la más reciente y probable.';


--
-- Name: conta_hacer_principal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_hacer_principal(p_actividad uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_empresa uuid; v_fin date; v_desc text;
begin
  select company_id, ended_on, description into v_empresa, v_fin, v_desc
    from public.company_activity where id = p_actividad;
  if v_empresa is null then
    raise exception 'No encuentro esa actividad' using errcode = '42501';
  end if;
  if v_fin is not null then
    raise exception 'Esa actividad ya terminó: no puede ser la principal' using errcode = '23514';
  end if;
  update public.company_activity set is_main = false
   where company_id = v_empresa and is_main and id <> p_actividad;
  update public.company_activity set is_main = true where id = p_actividad;
  if not found then
    raise exception 'No puedes cambiar las actividades de esta empresa' using errcode = '42501';
  end if;
  return jsonb_build_object('id', p_actividad, 'principal', v_desc);
end $$;


--
-- Name: FUNCTION conta_hacer_principal(p_actividad uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_hacer_principal(p_actividad uuid) IS 'C00. Marca una actividad vigente como la principal de su empresa y desmarca la anterior, en la misma transacción.';


--
-- Name: conta_hoy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_hoy() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$ select (now() at time zone 'Europe/Madrid')::date $$;


--
-- Name: conta_ia_anadir_actividad(uuid, text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ia_anadir_actividad(p_company uuid, p_descripcion text, p_clase text, p_iae text, p_cnae text, p_principal boolean, p_motivo text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid := public.conta_ia_cuenta(p_company); v_act uuid; v_id uuid;
begin
  if p_motivo is null or length(trim(p_motivo)) = 0 then
    raise exception 'Lo que hace la IA lleva siempre su porqué' using errcode = '23514';
  end if;
  -- Nunca inventa: el epígrafe y la CNAE tienen que estar en las tablas oficiales.
  if p_iae is not null and not exists (select 1 from public.iae_heading where code = p_iae) then
    raise exception 'El epígrafe % no está en el IAE', p_iae using errcode = '23503';
  end if;
  if p_cnae is not null and not exists (select 1 from public.cnae_code where version = '2025' and code = p_cnae) then
    raise exception 'El código % no está en la CNAE-2025', p_cnae using errcode = '23503';
  end if;
  if p_principal then
    update public.company_activity set is_main = false where company_id = p_company and is_main;
  end if;
  insert into public.company_activity (account_id, company_id, kind, description, iae_code, cnae_version, cnae_code, is_main, created_by)
  values (v_cuenta, p_company, p_clase, trim(p_descripcion), p_iae, '2025', p_cnae,
          p_principal or not exists (select 1 from public.company_activity where company_id = p_company and ended_on is null),
          auth.uid())
  returning id into v_act;
  insert into public.ai_data_origin (account_id, company_id, table_key, row_id, field, source, value_set, reason, set_by)
  values (v_cuenta, p_company, 'company_activity', v_act, 'description', 'ai', to_jsonb(trim(p_descripcion)), trim(p_motivo), auth.uid());
  insert into public.ai_action_log (account_id, company_id, action, table_key, row_id, after_value, reason, done_for, done_for_name)
  values (v_cuenta, p_company, 'anadir_actividad', 'company_activity', v_act,
          (select to_jsonb(a) from public.company_activity a where a.id = v_act), trim(p_motivo), auth.uid(), public.conta_nombre_actor())
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: conta_ia_campo_permitido(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ia_campo_permitido(p_tabla text, p_campo text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select (p_tabla = 'company' and p_campo in ('legal_name', 'trade_name', 'legal_form_code', 'fiscal_street_type',
            'fiscal_street', 'fiscal_number', 'fiscal_postal_code', 'fiscal_city', 'fiscal_province',
            'incorporated_on', 'dehu_email', 'dehu_phone', 'registry_name', 'registry_volume', 'registry_folio',
            'registry_sheet', 'registry_entry'))
      or (p_tabla = 'company_tax_profile' and p_campo in ('tax_territory', 'vat_scheme_code', 'vat_period', 'vat_cash_basis',
            'vat_surcharge', 'chart_kind', 'account_digits', 'tax_forms', 'sales_tax_rate_code'))
$$;


--
-- Name: conta_ia_cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ia_cuenta(p_company uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'No puedes cambiar esta empresa' using errcode = '42501';
  end if;
  return v_cuenta;
end $$;


--
-- Name: conta_ia_deshacer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ia_deshacer(p_registro uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare r public.ai_action_log; v_ahora jsonb; v_clave text; v_otras int;
begin
  select * into r from public.ai_action_log where id = p_registro for update;
  if r.id is null then raise exception 'No encuentro esa acción' using errcode = '42501'; end if;
  perform public.conta_ia_cuenta(r.company_id);
  if r.undone_at is not null then raise exception 'Eso ya se deshizo' using errcode = '23514'; end if;

  if r.action = 'poner' then
    v_clave := case r.table_key when 'company' then 'id' else 'company_id' end;
    execute format('select to_jsonb(t.%I) from public.%I t where t.%I = $1', r.field, r.table_key, v_clave) into v_ahora using r.company_id;
    if v_ahora is distinct from r.after_value then
      raise exception 'Ese dato ya lo cambió alguien después: no lo deshago para no pisarlo' using errcode = '23514';
    end if;
    execute format('update public.%I set %I = (jsonb_populate_record(null::public.%I, jsonb_build_object(%L, $1))).%I where %I = $2',
                   r.table_key, r.field, r.table_key, r.field, r.field, v_clave) using r.before_value, r.company_id;
    delete from public.ai_data_origin where table_key = r.table_key and row_id = r.row_id and field = r.field and value_set = r.after_value;
  elsif r.action = 'anadir_actividad' then
    if exists (select 1 from public.company_activity where id = r.row_id and is_main) then
      select count(*) into v_otras from public.company_activity where company_id = r.company_id and ended_on is null and id <> r.row_id;
      if v_otras > 0 then
        raise exception 'Es tu actividad principal: haz principal otra antes de quitarla' using errcode = '23514';
      end if;
    end if;
    delete from public.company_activity where id = r.row_id;
    delete from public.ai_data_origin where table_key = 'company_activity' and row_id = r.row_id;
  end if;

  update public.ai_action_log set undone_at = now(), undone_by = auth.uid(), undone_by_name = public.conta_nombre_actor() where id = r.id;
  return jsonb_build_object('id', r.id, 'deshecho', r.reason);
end $_$;


--
-- Name: conta_ia_poner(uuid, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ia_poner(p_company uuid, p_tabla text, p_campo text, p_valor jsonb, p_motivo text, p_origen text DEFAULT 'ai'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_cuenta uuid := public.conta_ia_cuenta(p_company);
  v_clave text; v_antes jsonb; v_despues jsonb; v_id uuid;
begin
  if not public.conta_ia_campo_permitido(p_tabla, p_campo) then
    raise exception 'La IA no puede poner «%» de «%»', p_campo, p_tabla using errcode = '42501';
  end if;
  if p_origen not in ('ai', 'import') then raise exception 'Origen no válido: %', p_origen using errcode = '22023'; end if;
  if p_motivo is null or length(trim(p_motivo)) = 0 then
    raise exception 'Lo que hace la IA lleva siempre su porqué' using errcode = '23514';
  end if;
  v_clave := case p_tabla when 'company' then 'id' else 'company_id' end;
  if p_tabla = 'company_tax_profile' then
    insert into public.company_tax_profile (company_id, account_id) values (p_company, v_cuenta) on conflict (company_id) do nothing;
  end if;
  execute format('select to_jsonb(t.%I) from public.%I t where t.%I = $1', p_campo, p_tabla, v_clave) into v_antes using p_company;
  execute format('update public.%I set %I = (jsonb_populate_record(null::public.%I, jsonb_build_object(%L, $1))).%I where %I = $2',
                 p_tabla, p_campo, p_tabla, p_campo, p_campo, v_clave) using p_valor, p_company;
  execute format('select to_jsonb(t.%I) from public.%I t where t.%I = $1', p_campo, p_tabla, v_clave) into v_despues using p_company;

  insert into public.ai_data_origin (account_id, company_id, table_key, row_id, field, source, value_set, reason, set_by)
  values (v_cuenta, p_company, p_tabla, p_company, p_campo, p_origen, v_despues, trim(p_motivo), auth.uid())
  on conflict (table_key, row_id, field) do update
    set source = excluded.source, value_set = excluded.value_set, reason = excluded.reason, set_at = now(), set_by = excluded.set_by;

  insert into public.ai_action_log (account_id, company_id, action, source, table_key, row_id, field, before_value, after_value, reason, done_for, done_for_name)
  values (v_cuenta, p_company, 'poner', p_origen, p_tabla, p_company, p_campo, v_antes, v_despues, trim(p_motivo), auth.uid(), public.conta_nombre_actor())
  returning id into v_id;
  return v_id;
end $_$;


--
-- Name: conta_impuesto_180_calcular(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_180_calcular(p_company uuid, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; o public.tax_obligation; r public.tax_return; v_plazo record; v_quien text := public.conta_impuesto_quien();
  v_cad text; v_pers text[]; v_per text; v_d jsonb; v_asientos jsonb := '[]'; v_sin_modelo jsonb := '[]';
  v_lineas jsonb; v_trim jsonb := '[]'; v_n int; v_base numeric; v_ret numeric; v_det jsonb;
  v_dif text; v_falta text; v_ret115 numeric; v_box jsonb;
  e text := 'FM999G999G990D00';
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, calcula sus impuestos.' using errcode = '42501';
  end if;
  if p_year is null or p_year < 2023 or p_year > extract(year from now())::int then
    raise exception 'El 180 de «%» no se puede calcular: el diseño del fichero es del 2023 en adelante, y el año tiene que haber empezado.', p_year using errcode = '22023';
  end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = '180' and valid_to is null and active;
  if o.id is null then raise exception 'Esta empresa no presenta el 180 (no está en sus modelos).' using errcode = 'P0002'; end if;

  select * into r from public.tax_return where company_id = p_company and form_code = '180' and fiscal_year = p_year and period = '0A' and sequence = 1 for update;
  if r.id is not null and r.status not in ('pending', 'draft', 'reviewed') then
    raise exception 'El 180 de % ya está «%»: no se recalcula.', p_year, public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if r.id is null then
    select * into v_plazo from public.conta_impuesto_plazo_si_hay('180', o.cadence, p_year, '0A');
    insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, due_date,
                                   due_date_direct_debit, due_provisional, alert_on, status)
    values (c.account_id, p_company, o.id, '180', p_year, o.cadence, '0A', v_plazo.presentacion, null, v_plazo.provisional,
            v_plazo.presentacion, 'draft')
    returning * into r;
  elsif r.status <> 'draft' then
    update public.tax_return set status = 'draft' where id = r.id returning * into r;
  end if;

  -- Los periodos del 115 del año: los de su obligación (trimestres o meses).
  select coalesce(public.conta_impuesto_cadencia_de(p_company, '115'), 'quarterly') into v_cad;
  v_pers := case when v_cad = 'monthly' then array['01','02','03','04','05','06','07','08','09','10','11','12'] else array['1T','2T','3T','4T'] end;
  foreach v_per in array v_pers loop
    v_d := public.conta_impuesto_retenciones_diario(p_company, p_year, v_per);
    v_asientos := v_asientos || coalesce((select jsonb_agg(a || jsonb_build_object('periodo', v_per)) from jsonb_array_elements(v_d->'asientos') a
                                           where a->>'tipo' = '115'), '[]');
    v_sin_modelo := v_sin_modelo || coalesce((select jsonb_agg(a) from jsonb_array_elements(v_d->'asientos') a where a->>'tipo' = 'sin_modelo'), '[]');
    v_trim := v_trim || jsonb_build_array(jsonb_build_object('periodo', v_per,
      'base', (v_d#>>'{sumas,115,base}')::numeric, 'retenido', (v_d#>>'{sumas,115,retenido}')::numeric));
  end loop;

  -- ── Los arrendadores: por perceptor (el tercero de la 4751 o la subcuenta del proveedor), con su ficha y su inmueble ──
  with a as (
    select x->>'perceptor' as perceptor, max(x->>'perceptor_nombre') as cuenta_nombre,
           sum((x->>'base')::numeric) as base, sum((x->>'retenido')::numeric) as retenido,
           -- El porcentaje: el del último asiento del año con base.
           (array_agg(round(100 * (x->>'retenido')::numeric / (x->>'base')::numeric, 2) order by x->>'fecha' desc, x->>'numero' desc)
              filter (where coalesce((x->>'base')::numeric, 0) <> 0))[1] as porcentaje,
           jsonb_agg(jsonb_build_object('asiento', x->>'asiento', 'fecha', x->>'fecha', 'serie', x->>'serie', 'numero', x->>'numero',
                                        'base', (x->>'base')::numeric, 'retenido', (x->>'retenido')::numeric, 'periodo', x->>'periodo') order by x->>'fecha') as asientos
      from jsonb_array_elements(v_asientos) x
     group by 1
  ), f as (
    select a.*, s.id as proveedor, coalesce(nullif(s.tax_id, ''), nullif(p.tax_id, '')) as nif,
           coalesce(nullif(s.legal_name, ''), nullif(s.name, ''), nullif(p.name, ''), a.cuenta_nombre) as nombre,
           case when coalesce(nullif(upper(s.country_code), ''), 'ES') = 'ES' and regexp_replace(coalesce(s.fiscal_postal_code, ''), '\D', '', 'g') ~ '^(0[1-9]|[1-4][0-9]|5[0-2])\d{3}$'
                then left(regexp_replace(s.fiscal_postal_code, '\D', '', 'g'), 2) end as provincia,
           ls.id as inmueble_id,
           case when ls.id is not null then jsonb_build_object(
             'situacion', ls.situation, 'catastral', ls.cadastral_ref, 'tipo_via', ls.street_type, 'nombre_via', ls.street_name,
             'tipo_numeracion', ls.number_type, 'numero', ls.street_number, 'calificador', ls.number_qualifier, 'bloque', ls.block,
             'portal', ls.portal, 'escalera', ls.stair, 'planta', ls.floor, 'puerta', ls.door, 'complemento', ls.complement,
             'localidad', ls.locality, 'municipio', ls.municipality, 'codigo_municipio', ls.municipality_code,
             'provincia', ls.province, 'cp', ls.postal_code) end as inmueble
      from a
      left join public.party p on p.account_id = c.account_id and p.id::text = a.perceptor
      -- Un enlace por subcuenta (el más antiguo, si hubiera dos): una línea por arrendador.
      left join lateral (select l.entity_id from public.company_account_link l
                          where l.account_id = c.account_id and l.company_id = p_company and l.company_account_id::text = a.perceptor
                            and l.entity = 'supplier' and l.role = 'principal' order by l.created_at, l.id limit 1) l on true
      left join lateral (select pr.supplier_id from public.party_role pr where pr.account_id = c.account_id and pr.party_id = p.id and pr.supplier_id is not null limit 1) pr on true
      left join public.supplier s on s.account_id = c.account_id and s.id::text = coalesce(l.entity_id, pr.supplier_id::text)
      left join public.company_lease ls on ls.account_id = c.account_id and ls.company_id = p_company and ls.supplier_id = s.id
     where abs(a.retenido) >= 0.005 or abs(a.base) >= 0.005
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'origen', 'diario', 'modalidad', '1',
           'perceptor', f.perceptor, 'proveedor', f.proveedor, 'nif', f.nif, 'nombre', f.nombre, 'provincia', f.provincia,
           'nif_valido', f.nif is not null and public._verifactu_nif_es_valido(f.nif),
           'porcentaje', coalesce(f.porcentaje, 0), 'inmueble', f.inmueble,
           'base', round(f.base, 2), 'retenciones', round(f.retenido, 2), 'asientos', f.asientos) order by f.nombre), '[]')
    into v_lineas
    from f;

  -- Las líneas: cada arrendador, con su foto.
  delete from public.tax_return_line where tax_return_id = r.id;
  insert into public.tax_return_line (tax_return_id, account_id, company_id, boxes, frozen)
  select r.id, c.account_id, p_company, array['01', '02', '03'], l from jsonb_array_elements(v_lineas) l;

  -- Las casillas: los totales del registro de declarante («si un mismo perceptor figura en varios registros, se computará una sola vez»).
  select count(distinct coalesce(l->>'nif', l->>'perceptor')), coalesce(sum((l->>'base')::numeric), 0), coalesce(sum((l->>'retenciones')::numeric), 0)
    into v_n, v_base, v_ret from jsonb_array_elements(v_lineas) l;
  delete from public.tax_return_box where tax_return_id = r.id and origin = 'calculated';
  insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
  values (r.id, c.account_id, p_company, '01', v_n, jsonb_build_object('de', 'los arrendadores (un perceptor cada uno)')),
         (r.id, c.account_id, p_company, '02', round(v_base, 2), jsonb_build_object('de', 'la suma de lo pagado en alquileres con retención en el año, sin IVA')),
         (r.id, c.account_id, p_company, '03', round(v_ret, 2), jsonb_build_object('de', 'la suma de lo retenido en la 4751, de los 115 del año'))
  on conflict (tax_return_id, box) do nothing;

  update public.tax_return set result_kind = case when jsonb_array_length(v_lineas) = 0 then 'no_activity' else 'zero' end, amount = 0,
         calculated_at = now(), updated_at = now() where id = r.id;

  -- ── Lo comprobado (se rehace entero) ──
  delete from public.tax_return_check where tax_return_id = r.id;

  -- a) Que sume los 115 del año, periodo a periodo: lo que el 115 declaró ([02] y [03]) contra el diario.
  with t as (
    select x->>'periodo' as periodo, (x->>'base')::numeric as base, (x->>'retenido')::numeric as retenido, d.id as decl, d.status,
           (select coalesce(sum(b.value), 0) from public.tax_return_box b where b.tax_return_id = d.id and b.box = '02') as base115,
           (select coalesce(sum(b.value), 0) from public.tax_return_box b where b.tax_return_id = d.id and b.box = '03') as ret115
      from jsonb_array_elements(v_trim) x
      left join public.tax_return d on d.company_id = p_company and d.form_code = '115' and d.fiscal_year = p_year and d.period = x->>'periodo' and d.sequence = 1
  )
  select string_agg(t.periodo || ': ' || concat_ws(' y ',
                      case when abs(t.ret115 - t.retenido) >= 0.005 then 'lo retenido, ' || translate(to_char(t.ret115, e), ',.', '.,') || ' € en el 115 y ' ||
                                                                          translate(to_char(t.retenido, e), ',.', '.,') || ' € en el diario' end,
                      case when abs(t.base115 - t.base) >= 0.005 then 'la base, ' || translate(to_char(t.base115, e), ',.', '.,') || ' € en el 115 y ' ||
                                                                       translate(to_char(t.base, e), ',.', '.,') || ' € en el diario' end), '; ' order by t.periodo)
           filter (where t.decl is not null and (abs(t.ret115 - t.retenido) >= 0.005 or abs(t.base115 - t.base) >= 0.005)),
         string_agg(t.periodo, ', ' order by t.periodo) filter (where t.decl is null and (t.retenido <> 0 or t.base <> 0)),
         jsonb_agg(jsonb_build_object('periodo', t.periodo, 'declaracion', t.decl, 'estado', t.status, 'base_115', t.base115, 'retenido_115', t.ret115,
                                      'base_diario', t.base, 'retenido_diario', t.retenido) order by t.periodo),
         coalesce(sum(t.ret115), 0)
    into v_dif, v_falta, v_det, v_ret115
    from t;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'sum_115_vs_180', case when v_dif is null and v_falta is null then 'ok' else 'warning' end,
          case when v_dif is null and v_falta is null
               then 'El 180 suma lo mismo que los 115 del año: ' || translate(to_char(v_ret, e), ',.', '.,') || ' € retenidos.'
               else concat_ws(' ',
                      case when v_dif is not null then 'No casa con los 115 del año: ' || v_dif || '.' end,
                      case when v_falta is not null then 'Hay retenciones de alquiler en el diario y no hay 115 en Sumied de: ' || v_falta || '.' end) end,
          jsonb_build_object('periodos', v_det, 'retenido_180', round(v_ret, 2), 'retenido_115', round(v_ret115, 2)));

  -- b) NIF que falta o no vale.
  select coalesce(jsonb_agg(l), '[]'), count(*) into v_det, v_n from jsonb_array_elements(v_lineas) l where not coalesce((l->>'nif_valido')::boolean, false);
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'payees_180_nif', case when v_n > 0 then 'error' else 'ok' end,
          case when v_n = 0 then 'Cada arrendador tiene un NIF que vale.'
               when v_n = 1 then '1 arrendador sin NIF o con un NIF que no vale: ' || coalesce((select l->>'nombre' from jsonb_array_elements(v_det) l limit 1), 'uno sin ficha de proveedor') || '. Corrígelo en su ficha.'
               else v_n || ' arrendadores sin NIF o con un NIF que no vale. Corrígelo en su ficha.' end,
          jsonb_build_object('perceptores', v_det));

  -- c) Arrendador sin provincia (la de su domicilio: el anexo la pide).
  select coalesce(jsonb_agg(l), '[]'), count(*) into v_det, v_n from jsonb_array_elements(v_lineas) l where coalesce(l->>'provincia', '') = '';
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'payees_180_province', case when v_n > 0 then 'error' else 'ok' end,
          case when v_n = 0 then 'Cada arrendador tiene su provincia.'
               when v_n = 1 then '1 arrendador sin provincia (sin código postal español en su ficha): ' || coalesce((select l->>'nombre' from jsonb_array_elements(v_det) l limit 1), 'uno sin ficha de proveedor') || '.'
               else v_n || ' arrendadores sin provincia (sin código postal español en su ficha).' end,
          jsonb_build_object('perceptores', v_det));

  -- d) Arrendador sin inmueble: el 180 lleva la situación, la referencia catastral y la dirección del local.
  select coalesce(jsonb_agg(l), '[]'), count(*) into v_det, v_n from jsonb_array_elements(v_lineas) l where l->'inmueble' is null or jsonb_typeof(l->'inmueble') = 'null';
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'lease_180', case when v_n > 0 then 'error' else 'ok' end,
          case when v_n = 0 then 'Cada arrendador tiene su inmueble: situación, referencia catastral y dirección.'
               when v_n = 1 then '1 arrendador sin el inmueble arrendado: ' || coalesce((select l->>'nombre' from jsonb_array_elements(v_det) l limit 1), 'uno sin ficha de proveedor') ||
                                 '. Ponlo en su fila: el 180 lleva la referencia catastral y la dirección del local.'
               else v_n || ' arrendadores sin el inmueble arrendado. Ponlo en su fila: el 180 lleva la referencia catastral y la dirección del local.' end,
          jsonb_build_object('perceptores', v_det));

  -- e) Asientos con retención sin modelo en el año.
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'withholding_unclassified', case when jsonb_array_length(v_sin_modelo) > 0 then 'error' else 'ok' end,
          case when jsonb_array_length(v_sin_modelo) = 0 then 'Cada asiento con retención del año tiene su modelo.'
               when jsonb_array_length(v_sin_modelo) = 1 then '1 asiento del año mueve la 4751 sin gasto ni nómina: Sumied no sabe si va en el 180. Ábrelo en el diario.'
               else jsonb_array_length(v_sin_modelo) || ' asientos del año mueven la 4751 sin gasto ni nómina: Sumied no sabe si van en el 180. Ábrelos en el diario.' end,
          jsonb_build_object('asientos', v_sin_modelo));

  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, c.account_id, p_company, auth.uid(), v_quien, 'calculation',
          v_quien || ' calculó el 180 de ' || p_year || ' desde los 115 del año: ' || translate(to_char(v_ret, e), ',.', '.,') || ' € retenidos.',
          jsonb_build_object('periodos', v_trim));

  select jsonb_object_agg(box, value) into v_box from public.tax_return_box where tax_return_id = r.id and value is not null;
  return jsonb_build_object('declaracion', r.id, 'modelo', '180', 'ejercicio', p_year,
                            'perceptores', (select count(*) from public.tax_return_line where tax_return_id = r.id),
                            'casillas', coalesce(v_box, '{}'),
                            'errores', (select count(*) from public.tax_return_check where tax_return_id = r.id and result = 'error'),
                            'avisos', (select count(*) from public.tax_return_check where tax_return_id = r.id and result = 'warning'),
                            'quien', v_quien);
end $_$;


--
-- Name: FUNCTION conta_impuesto_180_calcular(p_company uuid, p_year integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_180_calcular(p_company uuid, p_year integer) IS 'S02. Crea o recalcula el borrador del 180 del año desde los periodos del 115 (conta_impuesto_retenciones_diario): un perceptor por arrendador, con su ficha y su inmueble (company_lease), las casillas [01]-[03] del registro de declarante y lo comprobado (suma de los 115, NIF, provincia, inmueble). Informativo: resultado cero. Uno presentado no se recalcula.';


--
-- Name: conta_impuesto_180_fichero(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_180_fichero(p_return uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; c public.company; v_n int; v_quien text;
begin
  select * into r from public.tax_return where id = p_return and form_code = '180';
  if r.id is null then raise exception 'Ese 180 no está.' using errcode = 'P0002'; end if;
  select count(*) into v_n from public.tax_return_check where tax_return_id = r.id and result = 'error' and check_key <> 'file_layout';
  if v_n > 0 then
    raise exception 'Este 180 tiene % que resolver en «Lo comprobado»: sin eso no se prepara el fichero.',
      case when v_n = 1 then 'una cosa' else v_n || ' cosas' end using errcode = '22023';
  end if;
  select count(*) into v_n from public.tax_return_check where tax_return_id = r.id and result = 'warning' and accepted_at is null;
  if v_n > 0 then
    raise exception 'Antes, mira % de «Lo comprobado» y dalo por bueno si lo está: con un aviso sin mirar no se prepara el fichero.',
      case when v_n = 1 then 'el aviso' else 'los ' || v_n || ' avisos' end using errcode = '22023';
  end if;
  if r.result_kind is null then raise exception 'Este 180 no está calculado todavía: no se prepara el fichero.' using errcode = '22023'; end if;
  select * into c from public.company where id = r.company_id;
  v_quien := coalesce(public.conta_impuesto_nombre_de(p_user), c.legal_name);
  return jsonb_build_object(
    'ejercicio', r.fiscal_year, 'nif', c.tax_id, 'nombre', c.legal_name,
    'contacto', jsonb_build_object('telefono', coalesce(c.phone, ''), 'nombre', v_quien),
    -- El número identificativo: 180, el año y la secuencia de la declaración (13 cifras).
    'numero', '180' || r.fiscal_year || lpad(r.sequence::text, 6, '0'),
    'perceptores', (select coalesce(jsonb_agg(jsonb_build_object(
                       'nif', l.frozen->>'nif', 'nombre', l.frozen->>'nombre', 'provincia', l.frozen->>'provincia',
                       'modalidad', coalesce(l.frozen->>'modalidad', '1'), 'base', (l.frozen->>'base')::numeric,
                       'porcentaje', (l.frozen->>'porcentaje')::numeric, 'retenciones', (l.frozen->>'retenciones')::numeric,
                       'inmueble', l.frozen->'inmueble') order by l.frozen->>'nombre'), '[]')
                      from public.tax_return_line l where l.tax_return_id = r.id));
end $$;


--
-- Name: FUNCTION conta_impuesto_180_fichero(p_return uuid, p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_180_fichero(p_return uuid, p_user uuid) IS 'S02. Los datos del fichero del 180 (conta-hacienda, «fichero_180»): declarante, persona de contacto y un arrendador con su inmueble por línea. Con un error sin resolver o un aviso sin mirar en lo comprobado, no da datos. Solo el servicio.';


--
-- Name: conta_impuesto_180_inmueble_poner(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_180_inmueble_poner(p_company uuid, p_supplier uuid, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; s public.supplier; v_quien text := public.conta_impuesto_quien();
  v_sit text := btrim(coalesce(p_datos->>'situacion', ''));
  v_cat text := nullif(upper(regexp_replace(coalesce(p_datos->>'catastral', ''), '\s', '', 'g')), '');
  v_via text := nullif(btrim(coalesce(p_datos->>'nombre_via', '')), '');
  v_mun text := nullif(btrim(coalesce(p_datos->>'municipio', '')), '');
  v_cmun text := nullif(regexp_replace(coalesce(p_datos->>'codigo_municipio', ''), '\s', '', 'g'), '');
  v_prov text := nullif(btrim(coalesce(p_datos->>'provincia', '')), '');
  v_cp text := nullif(regexp_replace(coalesce(p_datos->>'cp', ''), '\s', '', 'g'), '');
  v_tn text := nullif(upper(btrim(coalesce(p_datos->>'tipo_numeracion', ''))), '');
  v_num text := nullif(btrim(coalesce(p_datos->>'numero', '')), '');
  v_falta text[] := '{}';
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, pone los datos de sus impuestos.' using errcode = '42501';
  end if;
  -- Regla 9: el proveedor, de la cuenta de la empresa.
  select * into s from public.supplier where id = p_supplier and account_id = c.account_id;
  if s.id is null then raise exception 'Ese arrendador no es un proveedor de esta cuenta.' using errcode = 'P0002'; end if;

  if v_sit not in ('1', '2', '3', '4') then v_falta := v_falta || 'la situación (1, 2, 3 o 4)'::text; end if;
  if v_sit in ('1', '2', '3') and coalesce(v_cat, '') !~ '^[0-9A-Z]{20}$' then v_falta := v_falta || 'la referencia catastral (20 letras y cifras; sin ella, la situación es la 4)'::text; end if;
  if v_via is null then v_falta := v_falta || 'la calle'::text; end if;
  if v_mun is null then v_falta := v_falta || 'el municipio'::text; end if;
  if v_cmun is not null and v_cmun !~ '^[0-9]{5}$' then v_falta := v_falta || 'el código de municipio del INE (5 cifras, o en blanco)'::text; end if;
  if coalesce(v_prov, '') !~ '^(0[1-9]|[1-4][0-9]|5[0-3])$' then v_falta := v_falta || 'la provincia (dos cifras, de 01 a 53)'::text; end if;
  if coalesce(v_cp, '') !~ '^[0-9]{5}$' then v_falta := v_falta || 'el código postal (5 cifras)'::text; end if;
  if v_tn is not null and v_tn not in ('NUM', 'KM.', 'S/N') then v_falta := v_falta || 'el tipo de numeración (NUM, KM. o S/N)'::text; end if;
  if array_length(v_falta, 1) > 0 then
    raise exception 'Falta o no vale: %.', array_to_string(v_falta, '; ') using errcode = '22023';
  end if;

  insert into public.company_lease as l (account_id, company_id, supplier_id, situation, cadastral_ref, street_type, street_name, number_type, street_number,
                                         number_qualifier, block, portal, stair, floor, door, complement, locality, municipality, municipality_code,
                                         province, postal_code, updated_by, updated_by_name)
  values (c.account_id, p_company, s.id, v_sit, case when v_sit = '4' then null else v_cat end,
          nullif(upper(btrim(coalesce(p_datos->>'tipo_via', ''))), ''), v_via, coalesce(v_tn, case when v_num is null then 'S/N' else 'NUM' end), v_num,
          nullif(btrim(coalesce(p_datos->>'calificador', '')), ''), nullif(btrim(coalesce(p_datos->>'bloque', '')), ''),
          nullif(btrim(coalesce(p_datos->>'portal', '')), ''), nullif(btrim(coalesce(p_datos->>'escalera', '')), ''),
          nullif(btrim(coalesce(p_datos->>'planta', '')), ''), nullif(btrim(coalesce(p_datos->>'puerta', '')), ''),
          nullif(btrim(coalesce(p_datos->>'complemento', '')), ''), nullif(btrim(coalesce(p_datos->>'localidad', '')), ''),
          v_mun, v_cmun, v_prov, v_cp, auth.uid(), v_quien)
  on conflict (company_id, supplier_id) do update
     set situation = excluded.situation, cadastral_ref = excluded.cadastral_ref, street_type = excluded.street_type, street_name = excluded.street_name,
         number_type = excluded.number_type, street_number = excluded.street_number, number_qualifier = excluded.number_qualifier, block = excluded.block,
         portal = excluded.portal, stair = excluded.stair, floor = excluded.floor, door = excluded.door, complement = excluded.complement,
         locality = excluded.locality, municipality = excluded.municipality, municipality_code = excluded.municipality_code, province = excluded.province,
         postal_code = excluded.postal_code, updated_by = excluded.updated_by, updated_by_name = excluded.updated_by_name, updated_at = now();

  return jsonb_build_object('ok', true,
    'mensaje', 'Guardado el local de ' || coalesce(nullif(s.legal_name, ''), s.name) || ': ' || v_via || coalesce(' ' || v_num, '') || ', ' || v_cp || ' ' || v_mun ||
               case when v_sit = '4' then ', sin referencia catastral (situación 4)' else ', referencia catastral …' || right(v_cat, 4) end ||
               '. Vuelve a calcular el 180 para que lo lleve.');
end $_$;


--
-- Name: FUNCTION conta_impuesto_180_inmueble_poner(p_company uuid, p_supplier uuid, p_datos jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_180_inmueble_poner(p_company uuid, p_supplier uuid, p_datos jsonb) IS 'S02. Guarda el inmueble arrendado de un arrendador (company_lease) con lo que pide el anexo VI del 180: situación, referencia catastral si la tiene y dirección. Dice qué ha guardado.';


--
-- Name: conta_impuesto_190_calcular(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_190_calcular(p_company uuid, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; o public.tax_obligation; r public.tax_return; v_plazo record; v_quien text := public.conta_impuesto_quien();
  v_cad111 text; v_pers text[]; v_per text; v_d jsonb; v_asientos jsonb := '[]'; v_sin_modelo jsonb := '[]';
  v_lineas jsonb; v_trim jsonb := '[]'; v_n int; v_base numeric; v_ret numeric; v_det jsonb;
  v_nom_base numeric := 0; v_nom_ret numeric := 0; v_sin_ret_base numeric := 0; v_sin_ret_asientos jsonb := '[]'; v_l05 numeric := 0; v_l05_asientos jsonb := '[]'; v_det_a jsonb; v_det_l jsonb; v_pay_base numeric := 0; v_pay_ret numeric := 0; v_una_empresa boolean;
  v_dif text; v_falta_111 text; v_box jsonb;
  e text := 'FM999G999G990D00';
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, calcula sus impuestos.' using errcode = '42501';
  end if;
  if p_year is null or p_year < 2025 or p_year > extract(year from now())::int then
    raise exception 'El 190 de «%» no se puede calcular: el diseño del fichero es del 2025 en adelante, y el año tiene que haber empezado.', p_year using errcode = '22023';
  end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = '190' and valid_to is null and active;
  if o.id is null then raise exception 'Esta empresa no presenta el 190 (no está en sus modelos).' using errcode = 'P0002'; end if;

  select * into r from public.tax_return where company_id = p_company and form_code = '190' and fiscal_year = p_year and period = '0A' and sequence = 1 for update;
  if r.id is not null and r.status not in ('pending', 'draft', 'reviewed') then
    raise exception 'El 190 de % ya está «%»: no se recalcula.', p_year, public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if r.id is null then
    select * into v_plazo from public.conta_impuesto_plazo_si_hay('190', o.cadence, p_year, '0A');
    insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, due_date,
                                   due_date_direct_debit, due_provisional, alert_on, status)
    values (c.account_id, p_company, o.id, '190', p_year, o.cadence, '0A', v_plazo.presentacion, null, v_plazo.provisional,
            v_plazo.presentacion, 'draft')
    returning * into r;
  elsif r.status <> 'draft' then
    update public.tax_return set status = 'draft' where id = r.id returning * into r;
  end if;

  -- Los periodos del 111 del año: los de su obligación (trimestres o meses).
  select coalesce(public.conta_impuesto_cadencia_de(p_company, '111'), 'quarterly') into v_cad111;
  v_pers := case when v_cad111 = 'monthly' then array['01','02','03','04','05','06','07','08','09','10','11','12'] else array['1T','2T','3T','4T'] end;
  foreach v_per in array v_pers loop
    v_d := public.conta_impuesto_retenciones_diario(p_company, p_year, v_per);
    v_asientos := v_asientos || coalesce((select jsonb_agg(a || jsonb_build_object('periodo', v_per)) from jsonb_array_elements(v_d->'asientos') a
                                           where a->>'tipo' in ('111_nomina', '111_profesional')), '[]');
    v_sin_modelo := v_sin_modelo || coalesce((select jsonb_agg(a) from jsonb_array_elements(v_d->'asientos') a where a->>'tipo' = 'sin_modelo'), '[]');
    v_trim := v_trim || jsonb_build_array(jsonb_build_object('periodo', v_per,
      'base', (v_d#>>'{sumas,111_nomina,base}')::numeric + (v_d#>>'{sumas,111_profesional,base}')::numeric,
      'retenido', (v_d#>>'{sumas,111_nomina,retenido}')::numeric + (v_d#>>'{sumas,111_profesional,retenido}')::numeric));
  end loop;

  -- ── Los perceptores ──
  -- Profesionales: por perceptor (el tercero de la 4751 o la subcuenta del proveedor), con su ficha.
  with a as (
    select x->>'perceptor' as perceptor, max(x->>'perceptor_nombre') as cuenta_nombre,
           sum((x->>'base')::numeric) as base, sum((x->>'retenido')::numeric) as retenido,
           jsonb_agg(jsonb_build_object('asiento', x->>'asiento', 'fecha', x->>'fecha', 'serie', x->>'serie', 'numero', x->>'numero',
                                        'retenido', (x->>'retenido')::numeric, 'periodo', x->>'periodo') order by x->>'fecha') as asientos
      from jsonb_array_elements(v_asientos) x where x->>'tipo' = '111_profesional'
     group by 1
  ), f as (
    select a.*, s.id as proveedor, coalesce(nullif(s.tax_id, ''), nullif(p.tax_id, '')) as nif,
           coalesce(nullif(s.legal_name, ''), nullif(s.name, ''), nullif(p.name, ''), a.cuenta_nombre) as nombre,
           case when coalesce(nullif(upper(s.country_code), ''), 'ES') = 'ES' and regexp_replace(coalesce(s.fiscal_postal_code, ''), '\D', '', 'g') ~ '^\d{5}$'
                then left(regexp_replace(s.fiscal_postal_code, '\D', '', 'g'), 2) end as provincia
      from a
      left join public.party p on p.account_id = c.account_id and p.id::text = a.perceptor
      -- Un enlace por subcuenta (el más antiguo, si hubiera dos): una línea por perceptor.
      left join lateral (select l.entity_id from public.company_account_link l
                          where l.account_id = c.account_id and l.company_id = p_company and l.company_account_id::text = a.perceptor
                            and l.entity = 'supplier' and l.role = 'principal' order by l.created_at, l.id limit 1) l on true
      left join lateral (select pr.supplier_id from public.party_role pr where pr.account_id = c.account_id and pr.party_id = p.id and pr.supplier_id is not null limit 1) pr on true
      left join public.supplier s on s.account_id = c.account_id and s.id::text = coalesce(l.entity_id, pr.supplier_id::text)
     where abs(a.retenido) >= 0.005 or abs(a.base) >= 0.005
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'origen', 'diario', 'clave', 'G',
           'subclave', case when f.base > 0 and abs(f.retenido / f.base - 0.07) < 0.0005 then '03' else '01' end,
           'perceptor', f.perceptor, 'proveedor', f.proveedor, 'nif', f.nif, 'nombre', f.nombre, 'provincia', f.provincia,
           'nif_valido', f.nif is not null and public._verifactu_nif_es_valido(f.nif),
           'integra', round(f.base, 2), 'retenciones', round(f.retenido, 2), 'asientos', f.asientos) order by f.nombre), '[]')
    into v_lineas
    from f;

  -- Nóminas: lo del diario, y lo de las nóminas por trabajador del año (si la cuenta tiene una sola empresa).
  select coalesce(sum((x->>'base')::numeric), 0), coalesce(sum((x->>'retenido')::numeric), 0) into v_nom_base, v_nom_ret
    from jsonb_array_elements(v_asientos) x where x->>'tipo' = '111_nomina';
  -- Y las nóminas SIN retención (mueven la 640 y no la 4751): también van en el 190, con
  -- retenciones cero. Sin la regularización (la que salda la 640 contra el grupo 1), sin
  -- apertura ni cierre. Un asiento anulado y su contraasiento se compensan.
  -- (S02, 29/10: lo enseñó el 190 de 2023 de Foodint, una nómina de 546,00 € sin retención.)
  select coalesce(sum(q.n640), 0),
         coalesce(jsonb_agg(jsonb_build_object('asiento', q.id, 'fecha', q.entry_date, 'serie', q.series, 'numero', q.number,
                                               'retenido', 0, 'base', round(q.n640, 2), 'sin_retencion', true) order by q.entry_date), '[]')
    into v_sin_ret_base, v_sin_ret_asientos
    from (select je.id, je.entry_date, je.series, je.number, sum(l.debit - l.credit) filter (where ca.code like '640%') as n640
            from public.journal_entry je
            join public.journal_line l on l.entry_id = je.id
            join public.company_account ca on ca.id = l.company_account_id
           where je.account_id = c.account_id and je.company_id = p_company and je.status in ('validado', 'anulado')
             and je.entry_date between make_date(p_year, 1, 1) and make_date(p_year, 12, 31)
             and coalesce(je.source_type, '') not in ('opening', 'closing')
           group by je.id, je.entry_date, je.series, je.number
          having bool_or(ca.code like '640%') and not bool_or(ca.code like '4751%') and not bool_or(ca.code ~ '^(10|11|12)')) q
   where abs(q.n640) >= 0.005;
  v_nom_base := v_nom_base + v_sin_ret_base;
  select count(*) = 1 into v_una_empresa from public.company where account_id = c.account_id;
  if v_una_empresa then
    with n as (
      select pc.employee_id, sum(pc.gross) as bruto, sum(pc.irpf) as irpf, sum(coalesce(pc.employee_ss, 0)) as cotizaciones, count(*) as nominas
        from public.payroll_cost pc
       where pc.account_id = c.account_id and pc.period_year = p_year and pc.irpf is not null and pc.gross is not null
       group by 1
    )
    select coalesce(v_lineas || coalesce(jsonb_agg(jsonb_build_object(
             'origen', 'nominas', 'clave', 'A', 'subclave', null, 'perceptor', em.id, 'nif', nullif(em.dni, ''), 'nombre', em.name,
             'provincia', null, 'nif_valido', nullif(em.dni, '') is not null and public._verifactu_nif_es_valido(em.dni),
             'anio_nacimiento', extract(year from em.birth_date)::int, 'nominas', n.nominas,
             -- Los «gastos deducibles» del 190 (art. 19.2 LIRPF): las cotizaciones a cargo del trabajador.
             'gastos', round(n.cotizaciones, 2),
             'integra', round(n.bruto, 2), 'retenciones', round(n.irpf, 2)) order by em.name), '[]'), v_lineas),
           coalesce(sum(n.bruto), 0), coalesce(sum(n.irpf), 0)
      into v_lineas, v_pay_base, v_pay_ret
      from n join public.employees em on em.id = n.employee_id and em.account_id = c.account_id;
  end if;
  if abs(v_nom_ret - v_pay_ret) >= 0.005 or abs(v_nom_base - v_pay_base) >= 0.005 then
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object(
      'origen', 'diario', 'clave', 'A', 'subclave', null, 'perceptor', null, 'nif', null, 'nombre', null, 'provincia', null, 'nif_valido', false,
      'sin_trabajador', true, 'integra', round(v_nom_base - v_pay_base, 2), 'retenciones', round(v_nom_ret - v_pay_ret, 2),
      'asientos', coalesce((select jsonb_agg(jsonb_build_object('asiento', x->>'asiento', 'fecha', x->>'fecha', 'serie', x->>'serie', 'numero', x->>'numero',
                                                                 'retenido', (x->>'retenido')::numeric, 'periodo', x->>'periodo') order by x->>'fecha')
                              from jsonb_array_elements(v_asientos) x where x->>'tipo' = '111_nomina'), '[]') || v_sin_ret_asientos));
  end if;

  -- Las indemnizaciones exentas (la 641): clave L, subclave 05 del anexo («indemnizaciones por
  -- despido o cese del trabajador que estén exentas», art. 7.e LIRPF). Sin retención. Del diario
  -- no se sabe de quién son: van «sin trabajador» hasta que entren las nóminas de cada persona.
  -- (S02, 29/10: la L.05 de los 190 presentados de Foodint es la 641 al céntimo: 717,68 en
  -- 2024; 897,78 + 870,43 en 2025.)
  select coalesce(sum(q.n641), 0),
         coalesce(jsonb_agg(jsonb_build_object('asiento', q.id, 'fecha', q.entry_date, 'serie', q.series, 'numero', q.number,
                                               'retenido', 0, 'base', round(q.n641, 2)) order by q.entry_date), '[]')
    into v_l05, v_l05_asientos
    from (select je.id, je.entry_date, je.series, je.number, sum(l.debit - l.credit) filter (where ca.code like '641%') as n641
            from public.journal_entry je
            join public.journal_line l on l.entry_id = je.id
            join public.company_account ca on ca.id = l.company_account_id
           where je.account_id = c.account_id and je.company_id = p_company and je.status in ('validado', 'anulado')
             and je.entry_date between make_date(p_year, 1, 1) and make_date(p_year, 12, 31)
             and coalesce(je.source_type, '') not in ('opening', 'closing')
           group by je.id, je.entry_date, je.series, je.number
          having bool_or(ca.code like '641%') and not bool_or(ca.code ~ '^(10|11|12)')) q
   where abs(q.n641) >= 0.005;
  if abs(v_l05) >= 0.005 then
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object(
      'origen', 'diario', 'clave', 'L', 'subclave', '05', 'perceptor', null, 'nif', null, 'nombre', null, 'provincia', null, 'nif_valido', false,
      'sin_trabajador', true, 'integra', round(v_l05, 2), 'retenciones', 0, 'asientos', v_l05_asientos));
  end if;

  -- Las líneas: cada perceptor y clave, con su foto.
  delete from public.tax_return_line where tax_return_id = r.id;
  insert into public.tax_return_line (tax_return_id, account_id, company_id, boxes, frozen)
  select r.id, c.account_id, p_company, array['01', '02', '03'], l from jsonb_array_elements(v_lineas) l;

  -- Las casillas: los totales del registro de declarante.
  select count(*) filter (where not coalesce((l->>'sin_trabajador')::boolean, false)),
         coalesce(sum((l->>'integra')::numeric), 0), coalesce(sum((l->>'retenciones')::numeric), 0)
    into v_n, v_base, v_ret from jsonb_array_elements(v_lineas) l;
  delete from public.tax_return_box where tax_return_id = r.id and origin = 'calculated';
  insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
  values (r.id, c.account_id, p_company, '01', v_n, jsonb_build_object('de', 'los perceptores con su clave (un registro de perceptor cada uno)')),
         (r.id, c.account_id, p_company, '02', round(v_base, 2), jsonb_build_object('de', 'la suma de lo pagado a esos perceptores en el año')),
         (r.id, c.account_id, p_company, '03', round(v_ret, 2), jsonb_build_object('de', 'la suma de lo retenido en la 4751, de los 111 del año'))
  on conflict (tax_return_id, box) do nothing;

  -- Informativo: no se paga.
  update public.tax_return set result_kind = case when jsonb_array_length(v_lineas) = 0 then 'no_activity' else 'zero' end, amount = 0,
         calculated_at = now(), updated_at = now() where id = r.id;

  -- ── Lo comprobado (se rehace entero) ──
  delete from public.tax_return_check where tax_return_id = r.id;

  -- a) Que sume los 111 del año, periodo a periodo: lo que el 111 declaró ([02]+[08] y [03]+[09]) contra el diario.
  with t as (
    select x->>'periodo' as periodo, (x->>'base')::numeric as base, (x->>'retenido')::numeric as retenido,
           d.id as decl, d.status,
           (select coalesce(sum(b.value), 0) from public.tax_return_box b where b.tax_return_id = d.id and b.box in ('02', '08')) as base111,
           (select coalesce(sum(b.value), 0) from public.tax_return_box b where b.tax_return_id = d.id and b.box in ('03', '09')) as ret111
      from jsonb_array_elements(v_trim) x
      left join public.tax_return d on d.company_id = p_company and d.form_code = '111' and d.fiscal_year = p_year and d.period = x->>'periodo' and d.sequence = 1
  )
  select string_agg(t.periodo || ': ' || concat_ws(' y ',
                      case when abs(t.ret111 - t.retenido) >= 0.005 then 'lo retenido, ' || translate(to_char(t.ret111, e), ',.', '.,') || ' € en el 111 y ' ||
                                                                          translate(to_char(t.retenido, e), ',.', '.,') || ' € en el diario' end,
                      case when abs(t.base111 - t.base) >= 0.005 then 'la base, ' || translate(to_char(t.base111, e), ',.', '.,') || ' € en el 111 y ' ||
                                                                       translate(to_char(t.base, e), ',.', '.,') || ' € en el diario' end), '; ' order by t.periodo)
           filter (where t.decl is not null and (abs(t.ret111 - t.retenido) >= 0.005 or abs(t.base111 - t.base) >= 0.005)),
         string_agg(t.periodo, ', ' order by t.periodo) filter (where t.decl is null and (t.retenido <> 0 or t.base <> 0)),
         jsonb_agg(jsonb_build_object('periodo', t.periodo, 'declaracion', t.decl, 'estado', t.status, 'base_111', t.base111, 'retenido_111', t.ret111,
                                      'base_diario', t.base, 'retenido_diario', t.retenido) order by t.periodo),
         coalesce(sum(t.ret111), 0)
    into v_dif, v_falta_111, v_det, v_base
    from t;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'sum_111_vs_190', case when v_dif is null and v_falta_111 is null then 'ok' else 'warning' end,
          case when v_dif is null and v_falta_111 is null
               then 'El 190 suma lo mismo que los 111 del año: ' || translate(to_char(v_ret, e), ',.', '.,') || ' € retenidos.'
               else concat_ws(' ',
                      case when v_dif is not null then 'No casa con los 111 del año: ' || v_dif || '.' end,
                      case when v_falta_111 is not null then 'Hay retenciones en el diario y no hay 111 en Sumied de: ' || v_falta_111 || '.' end) end,
          jsonb_build_object('periodos', v_det, 'retenido_190', round(v_ret, 2), 'retenido_111', round(v_base, 2)));
  -- (El 190 lleva lo que dice el diario; lo que el 111 presentó distinto se explica aquí y se da por bueno con su motivo.)

  -- b) NIF que falta o no vale.
  select coalesce(jsonb_agg(l), '[]'), count(*) into v_det, v_n from jsonb_array_elements(v_lineas) l
   where not coalesce((l->>'sin_trabajador')::boolean, false) and not coalesce((l->>'nif_valido')::boolean, false);
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'payees_190_nif', case when v_n > 0 then 'error' else 'ok' end,
          case when v_n = 0 then 'Cada perceptor tiene un NIF que vale.'
               when v_n = 1 then '1 perceptor sin NIF o con un NIF que no vale: ' || coalesce((select l->>'nombre' from jsonb_array_elements(v_det) l limit 1), 'uno sin ficha de proveedor') || '. Corrígelo en su ficha.'
               else v_n || ' perceptores sin NIF o con un NIF que no vale. Corrígelo en su ficha.' end,
          jsonb_build_object('perceptores', v_det));

  -- c) Perceptor sin provincia (el anexo la pide: la de su domicilio).
  select coalesce(jsonb_agg(l), '[]'), count(*) into v_det, v_n from jsonb_array_elements(v_lineas) l
   where not coalesce((l->>'sin_trabajador')::boolean, false) and coalesce(l->>'provincia', '') = '';
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'payees_190_province', case when v_n > 0 then 'error' else 'ok' end,
          case when v_n = 0 then 'Cada perceptor tiene su provincia.'
               else concat_ws(' ',
                 case (select count(*) from jsonb_array_elements(v_det) l where l->>'clave' = 'G')
                   when 0 then null
                   when 1 then '1 proveedor sin provincia (sin código postal español en su ficha): ' || coalesce((select l->>'nombre' from jsonb_array_elements(v_det) l where l->>'clave' = 'G' limit 1), 'uno sin ficha de proveedor') || '.'
                   else (select count(*) from jsonb_array_elements(v_det) l where l->>'clave' = 'G') || ' proveedores sin provincia (sin código postal español en su ficha).' end,
                 case (select count(*) from jsonb_array_elements(v_det) l where l->>'clave' = 'A')
                   when 0 then null
                   when 1 then '1 trabajador sin provincia: Sumied no guarda el domicilio de los trabajadores, y el 190 lo pide.'
                   else (select count(*) from jsonb_array_elements(v_det) l where l->>'clave' = 'A') || ' trabajadores sin provincia: Sumied no guarda el domicilio de los trabajadores, y el 190 lo pide.' end) end,
          jsonb_build_object('perceptores', v_det));

  -- d) Nóminas sin trabajador.
  select coalesce(jsonb_agg(l), '[]') into v_det from jsonb_array_elements(v_lineas) l where coalesce((l->>'sin_trabajador')::boolean, false);
  select l into v_det_a from jsonb_array_elements(v_det) l where l->>'clave' = 'A' limit 1;
  select l into v_det_l from jsonb_array_elements(v_det) l where l->>'clave' = 'L' limit 1;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'payroll_190', case when jsonb_array_length(v_det) > 0 then 'error' else 'ok' end,
          case when jsonb_array_length(v_det) = 0 then 'Las nóminas del año van por trabajador.'
               else concat_ws(' ',
                 case when v_det_a is not null then
                    'Las nóminas del diario pagan ' || translate(to_char(v_nom_base, e), ',.', '.,') || ' € (' ||
                    translate(to_char(v_nom_ret, e), ',.', '.,') || ' € retenidos) y las nóminas por trabajador de Sumied, ' ||
                    translate(to_char(v_pay_base, e), ',.', '.,') || ' € (' || translate(to_char(v_pay_ret, e), ',.', '.,') ||
                    ' €): el 190 lleva una línea por persona, y quedan ' ||
                    translate(to_char(v_nom_base - v_pay_base, e), ',.', '.,') || ' € pagados y ' ||
                    translate(to_char(v_nom_ret - v_pay_ret, e), ',.', '.,') || ' € retenidos sin trabajador (' ||
                    jsonb_array_length(v_det_a->'asientos') || case when jsonb_array_length(v_det_a->'asientos') = 1 then ' asiento' else ' asientos' end || ' de nómina).' end,
                 case when v_det_l is not null then
                    'Las indemnizaciones exentas (la 641, clave L.05) suman ' || translate(to_char(v_l05, e), ',.', '.,') ||
                    ' € y tampoco se sabe de quién son (' || jsonb_array_length(v_det_l->'asientos') ||
                    case when jsonb_array_length(v_det_l->'asientos') = 1 then ' asiento).' else ' asientos).' end end,
                 case when not v_una_empresa then 'La cuenta tiene más de una empresa: sus nóminas no se pueden repartir.' end) end,
          jsonb_build_object('diario', jsonb_build_object('base', v_nom_base, 'retenido', v_nom_ret, 'sin_retencion', v_sin_ret_base, 'indemnizaciones_l05', v_l05),
                             'nominas', jsonb_build_object('base', v_pay_base, 'retenido', v_pay_ret), 'lineas', v_det));

  -- e) Asientos con retención sin modelo en el año.
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'withholding_unclassified', case when jsonb_array_length(v_sin_modelo) > 0 then 'error' else 'ok' end,
          case when jsonb_array_length(v_sin_modelo) = 0 then 'Cada asiento con retención del año tiene su modelo.'
               when jsonb_array_length(v_sin_modelo) = 1 then '1 asiento del año mueve la 4751 sin gasto ni nómina: Sumied no sabe si va en el 190. Ábrelo en el diario.'
               else jsonb_array_length(v_sin_modelo) || ' asientos del año mueven la 4751 sin gasto ni nómina: Sumied no sabe si van en el 190. Ábrelos en el diario.' end,
          jsonb_build_object('asientos', v_sin_modelo));

  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, c.account_id, p_company, auth.uid(), v_quien, 'calculation',
          v_quien || ' calculó el 190 de ' || p_year || ' desde los 111 del año: ' || translate(to_char(v_ret, e), ',.', '.,') || ' € retenidos.',
          jsonb_build_object('periodos', v_trim));

  select jsonb_object_agg(box, value) into v_box from public.tax_return_box where tax_return_id = r.id and value is not null;
  return jsonb_build_object('declaracion', r.id, 'modelo', '190', 'ejercicio', p_year,
                            'perceptores', (select count(*) from public.tax_return_line where tax_return_id = r.id),
                            'casillas', coalesce(v_box, '{}'),
                            'errores', (select count(*) from public.tax_return_check where tax_return_id = r.id and result = 'error'),
                            'avisos', (select count(*) from public.tax_return_check where tax_return_id = r.id and result = 'warning'),
                            'quien', v_quien);
end $_$;


--
-- Name: FUNCTION conta_impuesto_190_calcular(p_company uuid, p_year integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_190_calcular(p_company uuid, p_year integer) IS 'S02. Crea o recalcula el borrador del 190 del año desde los periodos del 111 (conta_impuesto_retenciones_diario): un perceptor por proveedor (clave G) y por trabajador (clave A, de sus nóminas), las casillas [01]-[03] del registro de declarante y lo comprobado (suma de los 111, NIF, provincia, nóminas sin trabajador). Informativo: resultado cero. Uno presentado no se recalcula.';


--
-- Name: conta_impuesto_190_fichero(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_190_fichero(p_return uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; c public.company; v_n int; v_quien text;
begin
  select * into r from public.tax_return where id = p_return and form_code = '190';
  if r.id is null then raise exception 'Ese 190 no está.' using errcode = 'P0002'; end if;
  select count(*) into v_n from public.tax_return_check where tax_return_id = r.id and result = 'error' and check_key <> 'file_layout';
  if v_n > 0 then
    raise exception 'Este 190 tiene % que resolver en «Lo comprobado»: sin eso no se prepara el fichero.',
      case when v_n = 1 then 'una cosa' else v_n || ' cosas' end using errcode = '22023';
  end if;
  select count(*) into v_n from public.tax_return_check where tax_return_id = r.id and result = 'warning' and accepted_at is null;
  if v_n > 0 then
    raise exception 'Antes, mira % de «Lo comprobado» y dalo por bueno si lo está: con un aviso sin mirar no se prepara el fichero.',
      case when v_n = 1 then 'el aviso' else 'los ' || v_n || ' avisos' end using errcode = '22023';
  end if;
  if r.result_kind is null then raise exception 'Este 190 no está calculado todavía: no se prepara el fichero.' using errcode = '22023'; end if;
  select * into c from public.company where id = r.company_id;
  v_quien := coalesce(public.conta_impuesto_nombre_de(p_user), c.legal_name);
  return jsonb_build_object(
    'ejercicio', r.fiscal_year, 'nif', c.tax_id, 'nombre', c.legal_name,
    'contacto', jsonb_build_object('telefono', coalesce(c.phone, ''), 'nombre', v_quien, 'correo', coalesce(c.email, '')),
    -- El número identificativo: 190, el año y la secuencia de la declaración (13 cifras).
    'numero', '190' || r.fiscal_year || lpad(r.sequence::text, 6, '0'),
    'perceptores', (select coalesce(jsonb_agg(jsonb_build_object(
                       'nif', l.frozen->>'nif', 'nombre', l.frozen->>'nombre', 'provincia', l.frozen->>'provincia',
                       'clave', l.frozen->>'clave', 'subclave', l.frozen->>'subclave',
                       'integra', (l.frozen->>'integra')::numeric, 'retenciones', (l.frozen->>'retenciones')::numeric,
                       'anio_nacimiento', (l.frozen->>'anio_nacimiento')::int, 'gastos', (l.frozen->>'gastos')::numeric) order by l.frozen->>'clave', l.frozen->>'nombre'), '[]')
                      from public.tax_return_line l where l.tax_return_id = r.id and not coalesce((l.frozen->>'sin_trabajador')::boolean, false)));
end $$;


--
-- Name: FUNCTION conta_impuesto_190_fichero(p_return uuid, p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_190_fichero(p_return uuid, p_user uuid) IS 'S02. Los datos del fichero del 190 (conta-hacienda, «fichero_190»): declarante, persona de contacto y un perceptor por línea. Con un error sin resolver en lo comprobado, no da datos. Solo el servicio.';


--
-- Name: conta_impuesto_200_poner(uuid, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_200_poner(p_company uuid, p_year integer, p_datos jsonb, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c public.company; f public.corporate_tax_filing; v_quien text := public.conta_impuesto_quien();
  v_presentado date; v_base numeric; v_cuota numeric; v_kind text; v_importe numeric;
  v_hechos jsonb := '[]'; v_calc jsonb; v_p record; v_ya public.tax_return; v_frase text; e text := 'FM999G999G990D00';
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, escribe sus impuestos.' using errcode = '42501';
  end if;
  if p_year is null or p_year < 2000 or p_year > 2100 then raise exception 'Escribe el ejercicio del 200.' using errcode = '22023'; end if;
  if p_motivo is null or btrim(p_motivo) = '' then raise exception 'Para escribir un 200 a mano hace falta decir de dónde salen los datos.' using errcode = '22023'; end if;
  begin
    v_presentado := (p_datos->>'presentado')::date;
    v_base := (p_datos->>'base_imponible')::numeric;
    v_cuota := (p_datos->>'cuota')::numeric;
    v_importe := coalesce((p_datos->>'importe')::numeric, 0);
  exception when others then
    raise exception 'Los datos del 200 no se entienden: la fecha va como AAAA-MM-DD y las cifras, con punto decimal.' using errcode = '22023';
  end;
  v_kind := p_datos->>'resultado';
  if v_presentado is null or v_base is null or v_cuota is null or v_kind is null then
    raise exception 'Del 200 hacen falta la fecha en que se presentó, la base imponible, la cuota y el resultado.' using errcode = '22023';
  end if;
  if v_presentado <= make_date(p_year, 12, 31) then raise exception 'El 200 de % se presenta en %: la fecha % no puede ser.', p_year, p_year + 1, to_char(v_presentado, 'DD/MM/YYYY') using errcode = '22023'; end if;
  if v_presentado > (now() at time zone 'Europe/Madrid')::date then raise exception 'La fecha en que se presentó no puede ser de después de hoy.' using errcode = '22023'; end if;
  if v_cuota < 0 then raise exception 'La cuota (la base del 202) no puede ser negativa: si salió negativa, es 0.' using errcode = '22023'; end if;
  if v_kind not in ('to_pay', 'to_refund', 'zero') then raise exception 'El resultado es «a ingresar», «a devolver» o «cero».' using errcode = '22023'; end if;
  if v_importe < 0 then raise exception 'El importe del resultado va sin signo: «a devolver» ya dice que es a tu favor.' using errcode = '22023'; end if;
  if (v_kind = 'zero') <> (v_importe = 0) then
    raise exception '%', case when v_kind = 'zero' then 'Si el resultado es cero, el importe es 0.' else 'A ingresar o a devolver lleva su importe.' end using errcode = '22023';
  end if;

  insert into public.corporate_tax_filing (account_id, company_id, fiscal_year, filed_on, taxable_base, quota, result_kind, result_amount,
                                           origin, manual_reason, written_by, written_by_name)
  values (c.account_id, p_company, p_year, v_presentado, round(v_base, 2), round(v_cuota, 2), v_kind, round(v_importe, 2), 'manual',
          btrim(p_motivo) || ' (' || v_quien || ', ' || to_char(now() at time zone 'Europe/Madrid', 'DD/MM/YYYY') || ')', auth.uid(), v_quien)
  on conflict (company_id, fiscal_year) do update
    set filed_on = excluded.filed_on, taxable_base = excluded.taxable_base, quota = excluded.quota, result_kind = excluded.result_kind,
        result_amount = excluded.result_amount, origin = 'manual', manual_reason = excluded.manual_reason,
        written_by = excluded.written_by, written_by_name = excluded.written_by_name, updated_at = now()
  returning * into f;

  -- Los 202 que salen de este 200 (2P y 3P del año siguiente, 1P del otro), si no están
  -- presentados. Los que ya están en Sumied se vuelven a calcular; uno nuevo, solo de este
  -- año en adelante y con su plazo sabido: un 200 viejo no inventa pagos que ya se hicieron fuera.
  if exists (select 1 from public.tax_obligation where company_id = p_company and form_code = '202' and valid_to is null and active) then
    for v_p in select * from (values (p_year + 1, '2P'), (p_year + 1, '3P'), (p_year + 2, '1P')) t(y, p) loop
      select * into v_ya from public.tax_return where company_id = p_company and form_code = '202' and fiscal_year = v_p.y and period = v_p.p and sequence = 1;
      if v_ya.id is null and (v_p.y < extract(year from now() at time zone 'Europe/Madrid')::int
                              or not exists (select 1 from public.conta_impuesto_plazo_si_hay('202', 'instalments_202', v_p.y, v_p.p))) then
        continue;
      elsif v_ya.id is null or v_ya.status in ('pending', 'draft', 'reviewed', 'not_required') then
        v_calc := public.conta_impuesto_202_calcular(p_company, v_p.y, v_p.p);
        v_hechos := v_hechos || jsonb_build_array(jsonb_build_object('periodo', v_p.p, 'ejercicio', v_p.y, 'importe', v_calc->'importe', 'no_hace_falta', v_calc->'no_hace_falta'));
      else
        v_hechos := v_hechos || jsonb_build_array(jsonb_build_object('periodo', v_p.p, 'ejercicio', v_p.y, 'presentado', true));
      end if;
    end loop;
  end if;

  select string_agg(case when (h->>'presentado')::boolean then 'el ' || (h->>'periodo') || '/' || (h->>'ejercicio') || ' ya estaba presentado'
                         when (h->>'no_hace_falta')::boolean then 'el ' || (h->>'periodo') || '/' || (h->>'ejercicio') || ', no hay que presentarlo'
                         else 'el ' || (h->>'periodo') || '/' || (h->>'ejercicio') || ', ' || translate(to_char((h->>'importe')::numeric, e), ',.', '.,') || ' € a ingresar' end, '; ' order by n)
    into v_frase from jsonb_array_elements(v_hechos) with ordinality t(h, n);
  return jsonb_build_object('ok', true, 'declaracion_200', f.id, 'pagos_202', v_hechos,
    'mensaje', 'Guardado el Impuesto de sociedades de ' || p_year || ': cuota ' || translate(to_char(f.quota, e), ',.', '.,') || ' €, ' ||
               case f.result_kind when 'to_pay' then translate(to_char(f.result_amount, e), ',.', '.,') || ' € a ingresar'
                                  when 'to_refund' then translate(to_char(f.result_amount, e), ',.', '.,') || ' € a devolver'
                                  else 'resultado cero' end || '.' ||
               case when v_frase is not null then ' Vueltos a calcular los 202 que salen de él: ' || v_frase || '.' else '' end);
end $$;


--
-- Name: FUNCTION conta_impuesto_200_poner(p_company uuid, p_year integer, p_datos jsonb, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_200_poner(p_company uuid, p_year integer, p_datos jsonb, p_motivo text) IS 'I01h. Escribe a mano (con su motivo y quién) los datos del 200 de un ejercicio: {presentado, base_imponible, cuota, resultado (to_pay/to_refund/zero), importe}. Vuelve a calcular el 2P y el 3P del año siguiente y el 1P del otro, si no están presentados.';


--
-- Name: conta_impuesto_202_calcular(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_202_calcular(p_company uuid, p_year integer, p_period text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; o public.tax_obligation; r public.tax_return; f public.corporate_tax_filing; v_plazo record;
  v_quien text := public.conta_impuesto_quien(); v_base_y int; v01 numeric; v03 numeric; v_kind text; v_motivo text;
  v_box jsonb; e text := 'FM999G999G990D00';
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, calcula sus impuestos.' using errcode = '42501';
  end if;
  if p_period !~ '^[1-3]P$' then raise exception 'El 202 va en tres pagos: 1P, 2P o 3P, y «%» no es uno.', p_period using errcode = '22023'; end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = '202' and valid_to is null and active;
  if o.id is null then raise exception 'Esta empresa no presenta el 202 (no está en sus modelos).' using errcode = 'P0002'; end if;

  select * into r from public.tax_return where company_id = p_company and form_code = '202' and fiscal_year = p_year and period = p_period and sequence = 1 for update;
  if r.id is not null and r.status not in ('pending', 'draft', 'reviewed', 'not_required') then
    raise exception 'El 202 del % de % ya está «%»: no se recalcula.', p_period, p_year, public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;

  -- El 200 del que sale: el último con el plazo vencido al empezar el del pago.
  v_base_y := case when p_period = '1P' then p_year - 2 else p_year - 1 end;
  select * into f from public.corporate_tax_filing where company_id = p_company and fiscal_year = v_base_y;
  if f.id is not null then
    v01 := f.quota;
    v03 := round(v01 * 0.18, 2);
    v_kind := case when v03 > 0 then 'to_pay' else 'zero' end;
    v_motivo := case when v_kind = 'zero' then 'el impuesto de ' || v_base_y || ' salió a cero' end;
  end if;

  if r.id is null then
    select * into v_plazo from public.conta_impuesto_plazo('202', o.cadence, p_year, p_period, 'ES-MD');
    insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, due_date,
                                   due_date_direct_debit, due_provisional, alert_on, status, not_required_reason, payment_mode, payment_treasury_account_id)
    values (c.account_id, p_company, o.id, '202', p_year, o.cadence, p_period, v_plazo.presentacion, v_plazo.domiciliacion, v_plazo.provisional,
            case when o.payment_mode = 'direct_debit' then v_plazo.domiciliacion else v_plazo.presentacion end,
            case when v_kind = 'zero' then 'not_required' else 'draft' end, v_motivo,
            nullif(o.payment_mode, 'none'), case when o.payment_mode = 'direct_debit' then o.payment_treasury_account_id end)
    returning * into r;
  elsif v_kind = 'zero' and r.status <> 'not_required' then
    update public.tax_return set status = 'not_required', not_required_reason = v_motivo where id = r.id returning * into r;
  elsif v_kind = 'zero' then
    update public.tax_return set not_required_reason = v_motivo where id = r.id returning * into r;
  else
    -- Hay que presentarlo (o aún no se sabe): de «No hace falta» se vuelve por «Pendiente».
    if r.status = 'not_required' then update public.tax_return set status = 'pending' where id = r.id returning * into r; end if;
    if r.status <> 'draft' then update public.tax_return set status = 'draft' where id = r.id returning * into r; end if;
  end if;

  delete from public.tax_return_box where tax_return_id = r.id and origin = 'calculated';
  if f.id is not null then
    insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
    values (r.id, c.account_id, p_company, '01', v01, jsonb_build_object('de', 'la cuota del 200 de ' || v_base_y, 'ejercicio', v_base_y)),
           (r.id, c.account_id, p_company, '03', v03, jsonb_build_object('de', '18 % de la [01] (art. 40.2)'))
    on conflict (tax_return_id, box) do nothing;
  end if;
  update public.tax_return set result_kind = v_kind, amount = case when v_kind is not null then v03 end,
         calculated_at = now(), updated_at = now() where id = r.id;

  delete from public.tax_return_check where tax_return_id = r.id;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'base_200', case when f.id is null then 'error' else 'ok' end,
          case when f.id is null
               then 'Falta el Impuesto de sociedades de ' || v_base_y || ': escribe en «Impuesto de sociedades» su cuota, que es la base de este pago.'
               else 'La base es la cuota del Impuesto de sociedades de ' || v_base_y || ' (presentado el ' || to_char(f.filed_on, 'DD/MM/YYYY') || '): ' ||
                    translate(to_char(v01, e), ',.', '.,') || ' € × 18 % = ' || translate(to_char(v03, e), ',.', '.,') || ' €.' ||
                    case when v_kind = 'zero' then ' No hay que presentarlo.' else '' end end,
          jsonb_build_object('ejercicio_base', v_base_y, 'declaracion_200', f.id, 'cuota', v01, 'pago', v03));

  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, c.account_id, p_company, auth.uid(), v_quien, 'calculation',
          v_quien || ' calculó el 202 del ' || p_period || '/' || p_year ||
          case when f.id is null then ': falta el 200 de ' || v_base_y || '.'
               else ' desde el 200 de ' || v_base_y || ': ' || translate(to_char(v03, e), ',.', '.,') || ' €.' end,
          jsonb_build_object('ejercicio_base', v_base_y, 'cuota', v01, 'pago', v03));

  select jsonb_object_agg(box, value) into v_box from public.tax_return_box where tax_return_id = r.id and value is not null;
  return jsonb_build_object('declaracion', r.id, 'modelo', '202', 'ejercicio', p_year, 'periodo', p_period,
                            'ejercicio_base', v_base_y, 'falta_200', f.id is null, 'cuota', v01,
                            'resultado', v_kind, 'importe', v03, 'no_hace_falta', v_kind = 'zero',
                            'casillas', coalesce(v_box, '{}'), 'quien', v_quien);
end $_$;


--
-- Name: FUNCTION conta_impuesto_202_calcular(p_company uuid, p_year integer, p_period text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_202_calcular(p_company uuid, p_year integer, p_period text) IS 'I01h. El 202 de un periodo (1P, 2P o 3P), modalidad del art. 40.2: la [01] es la cuota del 200 de dos años antes (1P) o del anterior (2P y 3P) y la [03], su 18 %. Con 0, queda «No hace falta» con el porqué. Sin ese 200, un error en lo comprobado y sin resultado. Uno presentado no se recalcula.';


--
-- Name: vat_book_entry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vat_book_entry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    entry_id uuid NOT NULL,
    line_id uuid,
    book text NOT NULL,
    invoice_type text NOT NULL,
    series text,
    number text,
    number_to text,
    documents_count integer DEFAULT 1 NOT NULL,
    issue_date date NOT NULL,
    operation_date date,
    received_date date,
    received_number text,
    party_id uuid,
    counterpart_tax_id text,
    counterpart_id_type text,
    counterpart_country text,
    counterpart_name text,
    operation_key text DEFAULT '01'::text NOT NULL,
    qualification text,
    exempt_cause text,
    tax_base numeric(14,2) NOT NULL,
    tax_rate numeric(5,2),
    tax_amount numeric(14,2) DEFAULT 0 NOT NULL,
    surcharge_rate numeric(5,2),
    surcharge_amount numeric(14,2),
    total numeric(14,2),
    deductible_amount numeric(14,2),
    deductible_later boolean DEFAULT false NOT NULL,
    reverse_charge boolean DEFAULT false NOT NULL,
    investment_good boolean DEFAULT false NOT NULL,
    withholding_rate numeric(5,2),
    withholding_amount numeric(14,2),
    activity_code text,
    activity_type text,
    activity_iae text,
    corrects_ref text,
    source_type text NOT NULL,
    source_id uuid,
    voided_at timestamp with time zone,
    voided_by_entry_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_name text,
    deduction_year smallint,
    deduction_period text,
    deduction_reason text,
    CONSTRAINT vat_book_entry_book_check CHECK ((book = ANY (ARRAY['issued'::text, 'received'::text, 'investment'::text, 'not_subject'::text]))),
    CONSTRAINT vat_book_entry_counterpart_id_type_check CHECK (((counterpart_id_type IS NULL) OR (counterpart_id_type = ANY (ARRAY['02'::text, '03'::text, '04'::text, '05'::text, '06'::text])))),
    CONSTRAINT vat_book_entry_deducida_en CHECK ((((deduction_year IS NULL) AND (deduction_period IS NULL) AND (deduction_reason IS NULL)) OR (((deduction_year >= 2000) AND (deduction_year <= 2100)) AND (deduction_period ~ '^([1-4]T|0[1-9]|1[0-2])$'::text) AND (book = ANY (ARRAY['received'::text, 'investment'::text])) AND (deduction_reason IS NOT NULL) AND (btrim(deduction_reason) <> ''::text)))),
    CONSTRAINT vat_book_entry_documents_count_check CHECK ((documents_count > 0)),
    CONSTRAINT vat_book_entry_exempt_cause_check CHECK (((exempt_cause IS NULL) OR (exempt_cause = ANY (ARRAY['E1'::text, 'E2'::text, 'E3'::text, 'E4'::text, 'E5'::text, 'E6'::text])))),
    CONSTRAINT vat_book_entry_invoice_type_check CHECK ((invoice_type = ANY (ARRAY['F1'::text, 'F2'::text, 'F3'::text, 'F4'::text, 'R1'::text, 'R2'::text, 'R3'::text, 'R4'::text, 'R5'::text]))),
    CONSTRAINT vat_book_entry_qualification_check CHECK (((qualification IS NULL) OR (qualification = ANY (ARRAY['S1'::text, 'S2'::text, 'N1'::text, 'N2'::text])))),
    CONSTRAINT vat_book_entry_resumen CHECK (((invoice_type <> 'F4'::text) OR (documents_count >= 1)))
);


--
-- Name: TABLE vat_book_entry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.vat_book_entry IS 'C05. Libro registro del IVA (RIVA arts. 62–70) en el formato de requerimiento de la AEAT: una fila por factura (o asiento resumen F4, RIVA 63.4) y tipo. Se crea al validar el asiento con su apunte de IVA y se anula con él. Lo que el documento no dice (NIF, fecha de operación) se completa en pantalla.';


--
-- Name: COLUMN vat_book_entry.deduction_period; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.vat_book_entry.deduction_period IS 'I01c (0290) · «Deducida en»: el periodo (1T…4T o 01…12) del 303 en que se dedujo esta recibida, si no es el de su fecha de recepción. Vacío: el de su fecha.';


--
-- Name: conta_impuesto_303_cajas(public.vat_book_entry); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_303_cajas(v public.vat_book_entry) RETURNS TABLE(no_sabe text, cajas text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select n.no_sabe, x.cajas
    from (select 1) uno
    cross join lateral (select
      case
        when coalesce(v.surcharge_amount, 0) <> 0 then 'recargo'
        when v.book = 'issued' and v.invoice_type like 'R%' then 'rectificativa_expedida'
        when v.book in ('received', 'investment') and v.invoice_type like 'R%' and (v.reverse_charge or v.operation_key = '09') then 'rectificativa_isp'
        when v.book in ('received', 'investment') and not v.reverse_charge and v.operation_key <> '09'
             and coalesce(v.counterpart_country, 'ES') <> 'ES' then 'extranjera_sin_isp'
        when v.book = 'issued' and v.qualification = 'S1' and not v.reverse_charge and v.tax_rate not in (4, 10, 21) then 'tipo'
        else null end as no_sabe) n
    cross join lateral (select n.no_sabe,
      case
        when n.no_sabe is not null then '{}'::text[]
        -- D07 (0850): una recibida con IVA NO deducible (la factura no va a
        -- nombre de la empresa, un ticket sin NIF…) sale en el libro, con su
        -- cuota y deducible 0, pero no entra en el 303: ni su base en la [28]
        -- ni nada en la [29]. Medido el 23/10: 0 líneas así en producción.
        when v.book in ('received', 'investment') and not v.reverse_charge and v.operation_key <> '09'
             and coalesce(v.deductible_amount, 0) = 0 and coalesce(v.tax_amount, 0) <> 0 then '{}'::text[]
        when v.book = 'issued' and v.qualification = 'S1' and not v.reverse_charge then
          case v.tax_rate when 4 then array['01', '03'] when 10 then array['04', '06'] when 21 then array['07', '09'] end
        when v.book = 'issued' and v.qualification = 'S2' then array['122']
        when v.book = 'issued' and v.exempt_cause = 'E5' then array['59']
        when v.book = 'issued' and v.exempt_cause = 'E2' then array['60']
        when v.book = 'not_subject' or (v.book = 'issued' and v.qualification = 'N2') then case when v.qualification = 'N2' then array['120'] else '{}'::text[] end
        when v.book in ('received', 'investment') and v.invoice_type like 'R%' then array['40', '41']
        -- 0300: la autoliquidación. Intracomunitaria (clave 09): devengada en la
        -- [10]/[11] y deducible en la [36]/[37] (bien de inversión: [38]/[39]).
        -- Otra inversión del sujeto pasivo (de fuera de la UE o nacional):
        -- devengada en la [12]/[13] y deducible en la [28]/[29] ([30]/[31]).
        when v.book in ('received', 'investment') and v.operation_key = '09' then
          case when v.book = 'investment' or v.investment_good then array['10', '11', '38', '39'] else array['10', '11', '36', '37'] end
        when v.book in ('received', 'investment') and v.reverse_charge then
          case when v.book = 'investment' or v.investment_good then array['12', '13', '30', '31'] else array['12', '13', '28', '29'] end
        when v.deductible_later then '{}'::text[]
        when v.book = 'investment' or v.investment_good then array['30', '31']
        when v.book = 'received' then array['28', '29']
        else '{}'::text[] end as cajas) x
$$;


--
-- Name: FUNCTION conta_impuesto_303_cajas(v public.vat_book_entry); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_303_cajas(v public.vat_book_entry) IS 'I01d (0300). Las casillas del 303 de un apunte del libro de IVA (o por qué Sumied aún no lo sabe declarar). La usan el cálculo y conta_impuesto_303_desde_libro.';


--
-- Name: conta_impuesto_303_calcular(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_303_calcular(p_company uuid, p_year integer, p_period text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; p public.company_tax_profile; o public.tax_obligation; r public.tax_return;
  v_desde date; v_hasta date; v_plazo record; v_quien text := public.conta_impuesto_quien();
  v_no jsonb := '[]'; v_lineas int; v_box jsonb; b record;
  v27 numeric; v45 numeric; v46 numeric; v66 numeric; v110 numeric; v78 numeric; v69 numeric; v71 numeric;
  v_anterior public.tax_return; v_477 numeric; v_472 numeric; v_n int; v_det jsonb; v_kind text;
  v_man jsonb; v_emitidas int; v_recibidas int; v_vacio_exp boolean; v_vacio_rec boolean; v_vacio boolean;
  v_sabe110 boolean; v_sabido boolean; v_ant_y int; v_ant_p text; v_txt_vacio text; v_vienen int; v_van int;
  e text := 'FM999G999G990D00';
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, calcula sus impuestos.' using errcode = '42501';
  end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = '303' and valid_to is null and active;
  if o.id is null then raise exception 'Esta empresa no presenta el 303 (no está en sus modelos).' using errcode = 'P0002'; end if;
  if (o.cadence = 'quarterly' and p_period !~ '^[1-4]T$') or (o.cadence = 'monthly' and p_period !~ '^(0[1-9]|1[0-2])$') then
    raise exception 'Esta empresa presenta el 303 %, y «%» no es un periodo suyo.', case o.cadence when 'monthly' then 'cada mes' else 'cada trimestre' end, p_period using errcode = '22023';
  end if;
  select * into v_desde, v_hasta from public.conta_impuesto_periodo_fechas(p_year, p_period);
  select * into p from public.company_tax_profile where company_id = p_company;

  -- La declaración: la de este periodo, o una nueva en borrador.
  select * into r from public.tax_return where company_id = p_company and form_code = '303' and fiscal_year = p_year and period = p_period and sequence = 1 for update;
  if r.id is not null and r.status not in ('pending', 'draft', 'reviewed') then
    raise exception 'El 303 del % de % ya está «%»: no se recalcula.', p_period, p_year, public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if r.id is null then
    select * into v_plazo from public.conta_impuesto_plazo('303', o.cadence, p_year, p_period, 'ES-MD');
    -- La forma de pago, la de su obligación (sin ella, null: se dice al presentar).
    insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, due_date,
                                   due_date_direct_debit, due_provisional, alert_on, status, payment_mode, payment_treasury_account_id)
    values (c.account_id, p_company, o.id, '303', p_year, o.cadence, p_period, v_plazo.presentacion, v_plazo.domiciliacion, v_plazo.provisional,
            case when o.payment_mode = 'direct_debit' then v_plazo.domiciliacion else v_plazo.presentacion end, 'draft',
            nullif(o.payment_mode, 'none'), case when o.payment_mode = 'direct_debit' then o.payment_treasury_account_id end)
    returning * into r;
  elsif r.status <> 'draft' then
    update public.tax_return set status = 'draft' where id = r.id returning * into r;
  end if;

  -- Lo que la empresa es y Sumied no sabe declarar.
  if coalesce(p.tax_territory, 'peninsula_baleares') <> 'peninsula_baleares' then v_no := v_no || jsonb_build_object('motivo', 'territorio', 'texto', 'La empresa no está en la Península ni en Baleares: allí no hay 303.'); end if;
  if coalesce(p.vat_scheme_code, 'general') not in ('general') then v_no := v_no || jsonb_build_object('motivo', 'regimen', 'texto', 'La empresa no está en el régimen general («' || p.vat_scheme_code || '»): Sumied todavía no lo declara.'); end if;
  if coalesce(p.vat_prorata, false) then v_no := v_no || jsonb_build_object('motivo', 'prorrata', 'texto', 'La empresa aplica prorrata: Sumied todavía no la declara.'); end if;
  if coalesce(p.vat_cash_basis, false) then v_no := v_no || jsonb_build_object('motivo', 'criterio_caja', 'texto', 'La empresa está en el criterio de caja: Sumied todavía no lo declara.'); end if;

  -- Las líneas: cada apunte vivo del libro del periodo, con sus casillas y su foto.
  delete from public.tax_return_line where tax_return_id = r.id;
  insert into public.tax_return_line (tax_return_id, account_id, company_id, vat_book_entry_id, journal_line_id, boxes, frozen)
  select r.id, v.account_id, v.company_id, v.id, v.line_id, x.cajas,
         jsonb_build_object('libro', v.book, 'tipo_factura', v.invoice_type, 'serie', v.series, 'numero', v.number, 'expedida', v.issue_date,
                            'operacion', v.operation_date, 'recibida', v.received_date, 'contraparte', v.counterpart_name, 'base', v.tax_base,
                            'tipo', v.tax_rate, 'cuota', v.tax_amount, 'deducible', v.deductible_amount, 'calificacion', v.qualification,
                            'exencion', v.exempt_cause, 'recargo', v.surcharge_amount, 'isp', v.reverse_charge, 'pais', v.counterpart_country,
                            'no_sabe', x.no_sabe,
                            -- 0290: dónde se dedujo, si no es el periodo de su fecha (con su porqué).
                            'deducida_en', case when v.deduction_period is not null then v.deduction_period || '/' || v.deduction_year end,
                            'deducida_porque', v.deduction_reason)
    from public.vat_book_entry v
    cross join lateral public.conta_impuesto_303_cajas(v) x
   where v.account_id = c.account_id and v.company_id = p_company and v.voided_at is null
     -- 0290: una recibida con «deducida en» va en ESE periodo, no en el de su fecha.
     and case when v.book in ('received', 'investment') and v.deduction_period is not null
              then v.deduction_year = p_year and v.deduction_period = p_period
              else case when v.book in ('received', 'investment') then coalesce(v.received_date, v.issue_date) else coalesce(v.operation_date, v.issue_date) end
                   between v_desde and v_hasta end;
  get diagnostics v_lineas = row_count;
  select count(*) filter (where frozen->>'libro' in ('issued', 'not_subject')), count(*) filter (where frozen->>'libro' in ('received', 'investment'))
    into v_emitidas, v_recibidas from public.tax_return_line where tax_return_id = r.id;
  select coalesce(jsonb_agg(jsonb_build_object('motivo', k, 'apuntes', n, 'texto', case k
           when 'recargo' then n || ' con recargo de equivalencia: Sumied todavía no lo declara.'
           when 'rectificativa_expedida' then n || ' facturas rectificativas emitidas: Sumied todavía no las declara.'
           when 'rectificativa_isp' then n || ' rectificativas recibidas con inversión del sujeto pasivo o intracomunitarias: Sumied todavía no las declara.'
           when 'extranjera_sin_isp' then n || ' compras a proveedores de fuera de España sin autoliquidar: mira si son importaciones (con DUA) o si les falta el tipo «Compra en otro país de la UE» o «Inversión del sujeto pasivo».'
           when 'tipo' then n || ' ventas a un tipo que no es 4, 10 ni 21 %: falta cotejar sus casillas con la orden de 2026.' end)), '[]')
    into v_det
    from (select l.frozen->>'no_sabe' as k, count(*) as n from public.tax_return_line l where l.tax_return_id = r.id and l.frozen->>'no_sabe' is not null group by 1) q;
  v_no := v_no || v_det;

  -- 477 y 472 del diario del periodo (los anulados y sus contraasientos se compensan entre sí).
  select coalesce(sum(jl.credit - jl.debit) filter (where ca.code like '477%'), 0), coalesce(sum(jl.debit - jl.credit) filter (where ca.code like '472%'), 0)
    into v_477, v_472
    from public.journal_line jl
    join public.journal_entry je on je.id = jl.entry_id
    join public.company_account ca on ca.id = jl.company_account_id
   where je.account_id = c.account_id and je.company_id = p_company and je.status in ('validado', 'anulado')
     and je.source_type not in ('vat_settlement', 'opening', 'closing') and je.entry_date between v_desde and v_hasta;

  -- El libro vacío con el diario lleno: no hay nada que calcular, falta el libro.
  v_vacio_exp := v_emitidas = 0 and abs(v_477) >= 0.005;
  v_vacio_rec := v_recibidas = 0 and abs(v_472) >= 0.005;
  v_vacio := v_vacio_exp or v_vacio_rec;
  if v_vacio then
    v_txt_vacio := 'El libro de IVA de este periodo ' ||
      case when v_vacio_exp and v_vacio_rec then 'está vacío' when v_vacio_exp then 'no tiene ninguna factura emitida' else 'no tiene ninguna factura recibida' end ||
      ', pero el diario tiene IVA: la 477 suma ' || translate(to_char(v_477, e), ',.', '.,') || ' € y la 472, ' || translate(to_char(v_472, e), ',.', '.,') ||
      ' €. Sin el libro, Sumied no calcula el 303: tráelo a Libros y vuelve a calcular. Si ya lo presentó tu asesoría, apúntalo con «Ya lo presenté fuera» y las casillas del justificante.';
    v_no := jsonb_build_array(jsonb_build_object('motivo', 'libro_vacio', 'texto', v_txt_vacio, 'emitidas', v_emitidas, 'recibidas', v_recibidas,
                                                 'cuenta_477', v_477, 'cuenta_472', v_472)) || v_no;
  end if;

  -- Las casillas calculadas (las puestas a mano se quedan, y mandan).
  delete from public.tax_return_box where tax_return_id = r.id and origin = 'calculated';
  select coalesce(jsonb_object_agg(box, value), '{}') into v_man from public.tax_return_box
   where tax_return_id = r.id and origin = 'manual' and value is not null;
  for b in
    with l as (select l.boxes, (l.frozen->>'base')::numeric as base, (l.frozen->>'cuota')::numeric as cuota,
                      (l.frozen->>'deducible')::numeric as ded, l.frozen->>'libro' as libro, l.vat_book_entry_id
                 from public.tax_return_line l where l.tax_return_id = r.id)
    select caja, sum(valor) as valor, count(*) as n
      from (select boxes[1] as caja, base as valor from l where cardinality(boxes) >= 1
            union all
            select boxes[2], case when libro = 'issued' then cuota else ded end from l where cardinality(boxes) = 2
            -- 0300: la autoliquidación lleva cuatro casillas: base y cuota
            -- devengadas ([10]/[11] o [12]/[13]) y base y cuota deducibles.
            union all select boxes[2], cuota from l where cardinality(boxes) = 4
            union all select boxes[3], base from l where cardinality(boxes) = 4
            union all select boxes[4], ded from l where cardinality(boxes) = 4) s
     group by caja
  loop
    insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
    values (r.id, c.account_id, p_company, b.caja, round(b.valor, 2), jsonb_build_object('apuntes', b.n, 'de', 'libro de IVA'))
    on conflict (tax_return_id, box) do nothing;
  end loop;
  -- Las sumas, como el diseño (una [27] o [45] escrita a mano manda).
  select coalesce(sum(value) filter (where box in ('152','167','03','155','06','09','11','13','15','158','170','18','21','24','26')), 0),
         coalesce(sum(value) filter (where box in ('29','31','33','35','37','39','41','42','43','44')), 0)
    into v27, v45 from public.tax_return_box where tax_return_id = r.id;
  v27 := coalesce((v_man->>'27')::numeric, v27);
  v45 := coalesce((v_man->>'45')::numeric, v45);
  v46 := v27 - v45;
  v66 := round(v46 * 100 / 100, 2);
  -- [110]: la escrita a mano, o lo que quedó por compensar del 303 del periodo
  -- INMEDIATAMENTE anterior ya presentado (su [87] y, si salió a compensar, su
  -- resultado). Si no hay ninguna de las dos, no se sabe: no es 0.
  if p_period ~ '^[1-4]T$' then
    v_ant_y := case when p_period = '1T' then p_year - 1 else p_year end;
    v_ant_p := case when p_period = '1T' then '4T' else (left(p_period, 1)::int - 1) || 'T' end;
  else
    v_ant_y := case when p_period = '01' then p_year - 1 else p_year end;
    v_ant_p := case when p_period = '01' then '12' else lpad((p_period::int - 1)::text, 2, '0') end;
  end if;
  select * into v_anterior from public.tax_return
   where company_id = p_company and form_code = '303' and fiscal_year = v_ant_y and period = v_ant_p and sequence = 1;
  if v_man ? '110' then
    v110 := (v_man->>'110')::numeric; v_sabe110 := true;
  elsif v_anterior.status in ('filed', 'booked', 'paid', 'offset', 'refunded') then
    v110 := coalesce((select value from public.tax_return_box where tax_return_id = v_anterior.id and box = '87'), 0)
          + case when v_anterior.result_kind = 'to_offset' then v_anterior.amount else 0 end;
    v_sabe110 := true;
  else
    v110 := 0; v_sabe110 := false;
  end if;
  v78 := coalesce((v_man->>'78')::numeric, least(v110, greatest(v66, 0)));
  v69 := v66 - v78;
  v71 := coalesce((v_man->>'71')::numeric, v69);
  -- ¿Se sabe el resultado? Con la [71] a mano, sí (es la del justificante). Si
  -- no, hace falta el libro (o la [27] y la [45] a mano) y, si sale a pagar,
  -- lo que quedaba de antes.
  v_sabido := v_man ? '71'
           or ((not v_vacio_exp or v_man ? '27') and (not v_vacio_rec or v_man ? '45') and (v_sabe110 or v66 <= 0));
  if v_sabido then
    insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
    select r.id, c.account_id, p_company, k, round(val, 2), jsonb_build_object('de', como)
      from (values ('27', v27, '[152]+[167]+[03]+[155]+[06]+[09]+[11]+[13]+[15]+[158]+[170]+[18]+[21]+[24]+[26]'),
                   ('45', v45, '[29]+[31]+[33]+[35]+[37]+[39]+[41]+[42]+[43]+[44]'), ('46', v46, '[27]−[45]'), ('64', v46, '[46]+[58]+[76]'),
                   ('65', 100, 'no foral: todo a la Administración del Estado'), ('66', v66, '[64]×[65] %'),
                   ('110', v110, case when v_anterior.id is null or not v_sabe110 then 'nadie ha dicho lo que quedó por compensar de antes'
                                      else 'lo que quedó por compensar del ' || v_anterior.period || '/' || v_anterior.fiscal_year || ': su [87] y, si salió a compensar, su resultado' end),
                   ('78', v78, 'lo que se compensa ahora, hasta el resultado'), ('87', v110 - v78, '[110]−[78]'),
                   ('69', v69, '[66]+[77]−[78]+[68]+[108]'), ('71', v71, '[69]−[70]+[109]−[112]')) t(k, val, como)
     where k <> '110' or v_sabe110
    on conflict (tax_return_id, box) do nothing;
  else
    -- Sin resultado, ninguna casilla calculada: un cero aquí parecería un dato.
    delete from public.tax_return_box where tax_return_id = r.id and origin = 'calculated';
    -- Salvo la [110] (0280): no sale del libro de este periodo sino del 303
    -- anterior presentado, así que se sabe aunque falte el libro. Sin ella, un
    -- borrador calculado antes de tener el anterior se quedaba sin [110] para
    -- siempre (Foodint, 19/10: el 3T con la 477 y la 472 llenas y el libro vacío).
    if v_sabe110 then
      insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
      values (r.id, c.account_id, p_company, '110', round(v110, 2),
              jsonb_build_object('de', 'lo que quedó por compensar del ' || v_anterior.period || '/' || v_anterior.fiscal_year || ': su [87] y, si salió a compensar, su resultado'))
      on conflict (tax_return_id, box) do nothing;
    end if;
  end if;

  -- El resultado, en la declaración (sin saberlo, ninguno).
  v_kind := case when not v_sabido then null
                 when v_lineas = 0 and v71 = 0 then 'no_activity' when v71 > 0 then 'to_pay' when v71 = 0 then 'zero'
                 when p_period in ('4T', '12') and r.payment_mode = 'refund' then 'to_refund' else 'to_offset' end;
  update public.tax_return set result_kind = v_kind, amount = case when v_sabido then abs(v71) end, calculated_at = now(), updated_at = now() where id = r.id;

  -- Lo comprobado (se rehace entero: si cambian los números, se vuelve a mirar).
  delete from public.tax_return_check where tax_return_id = r.id;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'book_vs_303', case when jsonb_array_length(v_no) > 0 then 'error' else 'ok' end,
          case when v_vacio
               then v_txt_vacio || coalesce(' Y además: ' || (select string_agg(x->>'texto', ' ') from jsonb_array_elements(v_no) x where x->>'motivo' <> 'libro_vacio'), '')
               when jsonb_array_length(v_no) > 0
               then 'Hay cosas que Sumied todavía no sabe declarar en este 303. Preséntalo con tu asesor o espera a que lo sepa: ' ||
                    (select string_agg(x->>'texto', ' ') from jsonb_array_elements(v_no) x)
               when v_lineas = 0 then 'No hay facturas en el libro de IVA de este periodo, y el diario tampoco tiene IVA.'
               else 'Las ' || v_lineas || ' facturas del libro de IVA de este periodo están en el 303, cada una en su casilla.' end,
          jsonb_build_object('apuntes', v_lineas, 'emitidas', v_emitidas, 'recibidas', v_recibidas, 'no_sabe', v_no));

  -- El diario contra el 303 (con el libro vacío no hay 303 con que comparar: lo dice la de arriba).
  if not v_vacio then
    insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
    values (r.id, c.account_id, p_company, 'ledger_477_472',
            case when abs(v_477 - v27) < 0.005 and abs(v_472 - v45) < 0.005 then 'ok' else 'warning' end,
            case when abs(v_477 - v27) < 0.005 and abs(v_472 - v45) < 0.005
                 then 'El diario dice lo mismo que el 303: la 477 (' || translate(to_char(v_477, e), ',.', '.,') || ' €) y la 472 (' || translate(to_char(v_472, e), ',.', '.,') || ' €).'
                 else 'El diario no dice lo mismo que el 303: la 477 suma ' || translate(to_char(v_477, e), ',.', '.,') || ' € frente a ' || translate(to_char(v27, e), ',.', '.,') ||
                      ' €, y la 472, ' || translate(to_char(v_472, e), ',.', '.,') || ' € frente a ' || translate(to_char(v45, e), ',.', '.,') || ' €. Puede ser una factura recibida apuntada en un trimestre y llegada en otro.' end,
            jsonb_build_object('cuenta_477', v_477, 'casilla_27', v27, 'cuenta_472', v_472, 'casilla_45', v45));
  end if;

  -- Recibidas que llegaron en el periodo con fecha de antes: van en este.
  select count(*), coalesce(jsonb_agg(jsonb_build_object('numero', frozen->>'numero', 'expedida', frozen->>'expedida', 'recibida', frozen->>'recibida', 'contraparte', frozen->>'contraparte')), '[]')
    into v_n, v_det
    from public.tax_return_line where tax_return_id = r.id and frozen->>'libro' in ('received', 'investment') and (frozen->>'expedida')::date < v_desde;
  -- 0290: y las que se dedujeron en otro periodo que el de su fecha, a los dos
  -- lados: las que vienen a este y las de este que se fueron a otro (regla 7).
  select count(*) into v_vienen from public.tax_return_line
   where tax_return_id = r.id and frozen->>'deducida_en' is not null
     and coalesce((frozen->>'recibida')::date, (frozen->>'expedida')::date) not between v_desde and v_hasta;
  select count(*) into v_van from public.vat_book_entry v
   where v.account_id = c.account_id and v.company_id = p_company and v.voided_at is null and v.book in ('received', 'investment')
     and v.deduction_period is not null and not (v.deduction_year = p_year and v.deduction_period = p_period)
     and coalesce(v.received_date, v.issue_date) between v_desde and v_hasta;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'out_of_period', case when v_n + v_vienen + v_van > 0 then 'warning' else 'ok' end,
          case when v_n + v_vienen + v_van = 0 then 'Ninguna factura de otro periodo.'
               else concat_ws(' ',
                 case when v_n = 1 then '1 factura recibida tiene fecha de antes del periodo, pero llegó en él: va en este 303.'
                      when v_n > 1 then v_n || ' facturas recibidas tienen fecha de antes del periodo, pero llegaron en él: van en este 303.' end,
                 case when v_vienen = 1 then '1 recibida de otro periodo se dedujo en este (deducida en): va en este 303.'
                      when v_vienen > 1 then v_vienen || ' recibidas de otro periodo se dedujeron en este (deducida en): van en este 303.' end,
                 case when v_van = 1 then '1 recibida de este periodo se dedujo en otro (deducida en): no va en este 303.'
                      when v_van > 1 then v_van || ' recibidas de este periodo se dedujeron en otro (deducida en): no van en este 303.' end) end,
          jsonb_build_object('facturas', v_det, 'deducidas_aqui_de_otro_periodo', v_vienen, 'de_aqui_deducidas_en_otro', v_van));

  -- Recibidas por correo (D01) sin apuntar: no entran hasta que se validen.
  select count(*), coalesce(jsonb_agg(jsonb_build_object('id', si.id, 'numero', si.invoice_number, 'fecha', si.invoice_date, 'emisor', si.issuer_name)), '[]')
    into v_n, v_det
    from public.supplier_invoice si
   where si.account_id = c.account_id and si.company_id = p_company and si.arrival_channel = 'correo'
     and si.status not in ('anulada', 'descartada') and si.journal_entry_id is null and si.invoice_date <= v_hasta;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'mail_invoices_missing', case when v_n > 0 then 'warning' else 'ok' end,
          case when v_n = 0 then 'No falta ninguna factura recibida por correo.'
               when v_n = 1 then '1 factura que llegó por correo está sin apuntar: no entra en este 303 hasta que se valide.'
               else v_n || ' facturas que llegaron por correo están sin apuntar: no entran en este 303 hasta que se validen.' end,
          jsonb_build_object('facturas', v_det));

  -- Lo que quedó por compensar antes: si no se sabe, se pide (no se da por 0).
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'previous_offset',
          case when v_sabe110 then 'ok' else 'error' end,
          case when v_man ? '110'
               then 'Lo que quedaba por compensar de antes lo escribió una persona: ' || translate(to_char(v110, e), ',.', '.,') || ' €.'
               when v_sabe110
               then 'Del 303 del ' || v_anterior.period || '/' || v_anterior.fiscal_year || ' quedaron ' || translate(to_char(v110, e), ',.', '.,') || ' € por compensar.'
               else 'No sé lo que te quedó por compensar de antes: el 303 del ' || v_ant_p || '/' || v_ant_y ||
                    case when v_anterior.id is null then ' no está en Sumied' else ' no está presentado en Sumied' end ||
                    '. Escríbelo en la casilla [110], aunque sea 0 (está en el justificante del ' || v_ant_p || '/' || v_ant_y || ', casilla [87], más el resultado si salió a compensar).' end,
          jsonb_build_object('casilla_110', case when v_sabe110 then v110 end, 'anterior', v_anterior.id, 'periodo_anterior', v_ant_p || '/' || v_ant_y,
                             'a_mano', v_man ? '110'));

  select jsonb_object_agg(box, value) into v_box from public.tax_return_box where tax_return_id = r.id and value is not null;
  return jsonb_build_object('declaracion', r.id, 'desde', v_desde, 'hasta', v_hasta, 'apuntes', v_lineas, 'resultado', v_kind,
                            'importe', case when v_sabido then abs(v71) end, 'sabido', v_sabido,
                            'casillas', coalesce(v_box, '{}'), 'no_sabe', v_no, 'quien', v_quien);
end $_$;


--
-- Name: FUNCTION conta_impuesto_303_calcular(p_company uuid, p_year integer, p_period text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_303_calcular(p_company uuid, p_year integer, p_period text) IS 'I01a/I01b (0240), I01c (0280, 0290), I01d (0300: la autoliquidación, [10]–[13] y [36]–[39], desde el libro). El borrador del 303 del periodo desde el libro de IVA. Una recibida con «deducida en» va en ese periodo (0290). Con el libro vacío y el diario con IVA, o sin saber la [110] cuando sale a pagar, no hay resultado: se dice por qué. Las casillas manuales mandan. La [110] del 303 anterior presentado se escribe también sin resultado (0280). Una presentada no se recalcula.';


--
-- Name: conta_impuesto_303_contabilizar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_303_contabilizar(p_return uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r public.tax_return; v_desde date; v_hasta date; v_fecha date; v_aviso_fecha text;
  v27 numeric; v45 numeric; v71 numeric; v78 numeric; v_raras text;
  v_lineas jsonb := '[]'::jsonb; v_res jsonb; v_entry uuid; v_val jsonb; v_cta text; v_cta_mayor text; v_suma numeric; v_mov numeric;
  v_4700 text; v_4750 text; v_estado text; v_concepto text; v_nombre text := public.conta_impuesto_quien(); x record;
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(r.account_id) then
    raise exception 'El asiento de liquidación lo hace un administrador o un encargado de la empresa.' using errcode = '42501';
  end if;
  if r.form_code <> '303' then raise exception 'Solo se contabiliza solo el 303 de momento.' using errcode = '22023'; end if;

  -- Ya contabilizada: se dice cuál.
  if r.liquidation_entry_id is not null then
    select format('Ya estaba contabilizado: asiento %s/%s del %s.', e.series, coalesce(e.number::text, '—'), to_char(e.entry_date, 'DD/MM/YYYY'))
      into v_concepto from public.journal_entry e where e.id = r.liquidation_entry_id and e.status in ('propuesto', 'borrador', 'validado');
    if v_concepto is not null then
      return jsonb_build_object('ok', true, 'asiento', r.liquidation_entry_id, 'existente', true, 'mensaje', v_concepto);
    end if;
  end if;
  if r.status not in ('filed', 'paid', 'refunded') then
    raise exception 'Esta declaración está «%»: se contabiliza cuando está presentada.', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;

  select desde, hasta into v_desde, v_hasta from public.conta_impuesto_periodo_fechas(r.fiscal_year, r.period);
  select coalesce(max(value) filter (where box = '27'), 0), coalesce(max(value) filter (where box = '45'), 0),
         coalesce(max(value) filter (where box = '71'), 0), coalesce(max(value) filter (where box = '78'), 0),
         string_agg('[' || box || ']', ', ' order by box) filter (where box in ('68', '70', '77', '108', '109', '112') and coalesce(value, 0) <> 0)
    into v27, v45, v71, v78, v_raras
    from public.tax_return_box where tax_return_id = r.id;
  if v_raras is not null then
    raise exception 'Este 303 lleva % y el asiento de liquidación todavía no sabe llevarlas: hazlo a mano en el diario, con origen esta declaración.', v_raras
      using errcode = '22023';
  end if;
  if abs((v27 - v45 - v78) - v71) >= 0.005 then
    raise exception 'Las casillas no cuadran: [27] % − [45] % − [78] % no da el resultado [71] %.',
      public.conta_impuesto_euros(v27), public.conta_impuesto_euros(v45), public.conta_impuesto_euros(v78), public.conta_impuesto_euros(v71)
      using errcode = '22023';
  end if;

  -- Sin nada que saldar: «Contabilizado» sin asiento, y se dice.
  if v27 = 0 and v45 = 0 and v78 = 0 then
    if r.status = 'filed' then
      update public.tax_return set status = 'booked', updated_at = now() where id = r.id;
    end if;
    insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message)
    values (r.id, r.account_id, r.company_id, auth.uid(), v_nombre, 'note', 'Sin IVA que saldar: no hace falta asiento de liquidación.');
    return jsonb_build_object('ok', true, 'asiento', null, 'mensaje', 'Contabilizado. Este 303 no tiene IVA que saldar: no hace falta asiento.');
  end if;

  -- La fecha: el último día del periodo, o el primer día abierto después.
  v_fecha := v_hasta;
  if exists (select 1 from public.fiscal_year y where y.company_id = r.company_id and v_hasta between y.starts_on and y.ends_on
               and (y.status <> 'open' or (y.imported_until is not null and v_hasta <= y.imported_until)))
     or public.conta_mes_cerrado(r.company_id, v_hasta) then
    v_fecha := public.conta_primer_dia_abierto(r.company_id, v_hasta + 1);
    if v_fecha is null then
      raise exception 'No hay ningún día abierto después del % para apuntar la liquidación.', to_char(v_hasta, 'DD/MM/YYYY') using errcode = '23514';
    end if;
    v_aviso_fecha := format(' Con fecha %s: el %s no se puede apuntar (traído o cerrado).', to_char(v_fecha, 'DD/MM/YYYY'), to_char(v_hasta, 'DD/MM/YYYY'));
  end if;

  -- 477 (al debe) y 472 (al haber), por subcuenta. Lo que movió cada una en el
  -- periodo (como la comprobación ledger_477_472 del cálculo), y la diferencia
  -- con la casilla, a la que más movió (o a la primera, si no movió ninguna).
  for x in select k.raiz, k.casilla, k.lado from (values ('477', v27, 'debe'), ('472', v45, 'haber')) k(raiz, casilla, lado) loop
    v_suma := 0; v_cta_mayor := null;
    for v_cta, v_mov in
      select ca.code, sum(case when x.raiz = '477' then jl.credit - jl.debit else jl.debit - jl.credit end)
        from public.journal_line jl
        join public.journal_entry je on je.id = jl.entry_id
        join public.company_account ca on ca.id = jl.company_account_id
       where je.account_id = r.account_id and je.company_id = r.company_id and je.status in ('validado', 'anulado')
         and je.source_type not in ('vat_settlement', 'opening', 'closing') and je.entry_date between v_desde and v_hasta
         and ca.template_code like x.raiz || '%'
       group by ca.code
      having sum(jl.credit - jl.debit) <> 0
       order by abs(sum(jl.credit - jl.debit)) desc, ca.code
    loop
      v_cta_mayor := coalesce(v_cta_mayor, v_cta);
      v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_cta, 'importe', v_mov, 'raiz', x.raiz));
      v_suma := v_suma + v_mov;
    end loop;
    if v_cta_mayor is null then
      select min(code) into v_cta_mayor from public.company_account where company_id = r.company_id and template_code = x.raiz;
      if v_cta_mayor is null then
        raise exception 'La cuenta % no está en el plan de la empresa.', x.raiz using errcode = '23514';
      end if;
    end if;
    if abs(x.casilla - v_suma) >= 0.005 then
      v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_cta_mayor, 'importe', x.casilla - v_suma, 'raiz', x.raiz));
    end if;
  end loop;

  select min(code) into v_4700 from public.company_account where company_id = r.company_id and template_code = '4700';
  select min(code) into v_4750 from public.company_account where company_id = r.company_id and template_code = '4750';
  if (v78 <> 0 or v71 < 0) and v_4700 is null then raise exception 'La cuenta 4700 no está en el plan de la empresa.' using errcode = '23514'; end if;
  if v71 > 0 and v_4750 is null then raise exception 'La cuenta 4750 no está en el plan de la empresa.' using errcode = '23514'; end if;

  v_concepto := 'Liquidación del IVA ' || case r.period when '1T' then 'del 1.er trimestre' when '2T' then 'del 2.º trimestre'
                  when '3T' then 'del 3.er trimestre' when '4T' then 'del 4.º trimestre' else 'de ' || r.period end
                || ' de ' || r.fiscal_year || ' (modelo 303)';

  -- Las líneas: juntas las de la misma cuenta, y del lado que toca.
  v_res := (
    select coalesce(jsonb_agg(jsonb_build_object(
             'cuenta', c.cuenta,
             'debe', case when c.raiz = '477' then greatest(c.importe, 0) else greatest(-c.importe, 0) end,
             'haber', case when c.raiz = '477' then greatest(-c.importe, 0) else greatest(c.importe, 0) end,
             'concepto', v_concepto, 'comun', true) order by c.raiz desc, c.cuenta), '[]'::jsonb)
      from (select l->>'cuenta' cuenta, l->>'raiz' raiz, sum((l->>'importe')::numeric) importe
              from jsonb_array_elements(v_lineas) l group by 1, 2 having sum((l->>'importe')::numeric) <> 0) c);
  if v78 <> 0 then
    v_res := v_res || jsonb_build_array(jsonb_build_object('cuenta', v_4700, 'debe', 0, 'haber', v78, 'concepto', 'Compensado de periodos anteriores', 'comun', true));
  end if;
  if v71 > 0 then
    v_res := v_res || jsonb_build_array(jsonb_build_object('cuenta', v_4750, 'debe', 0, 'haber', v71, 'concepto', v_concepto, 'comun', true));
  elsif v71 < 0 then
    v_res := v_res || jsonb_build_array(jsonb_build_object('cuenta', v_4700, 'debe', -v71, 'haber', 0, 'concepto', v_concepto, 'comun', true));
  end if;

  v_res := public._journal_entry_proponer(r.company_id,
    jsonb_build_object('fecha', v_fecha, 'series', 4, 'concepto', v_concepto, 'source_type', 'vat_settlement', 'source_id', r.id,
                       'confianza', 'seguro', 'porque', 'Sale de las casillas del 303 presentado.',
                       'razones', jsonb_build_array(jsonb_build_object('decision', 'liquidacion-303', 'declaracion', r.id,
                                   'casillas', jsonb_build_object('27', v27, '45', v45, '78', v78, '71', v71))),
                       'documento', r.aeat_receipt_number),
    v_res, null, v_nombre, auth.uid());
  if coalesce((v_res->>'descartada')::boolean, false) then
    raise exception 'El asiento de liquidación de esta declaración se descartó en el diario.' using errcode = '23514';
  end if;
  v_entry := (v_res->>'id')::uuid;
  if exists (select 1 from public.journal_entry where id = v_entry and status in ('propuesto', 'borrador')) then
    v_val := public.journal_entry_validar(v_entry, v_nombre);
  else
    select jsonb_build_object('serie', series, 'numero', number) into v_val from public.journal_entry where id = v_entry;
  end if;

  v_estado := case when r.status = 'filed' and r.result_kind = 'to_offset' then 'offset'
                   when r.status = 'filed' then 'booked' else r.status end;
  if v_estado = 'offset' then
    update public.tax_return set status = 'booked', liquidation_entry_id = v_entry, updated_at = now() where id = r.id;
  end if;
  update public.tax_return set status = v_estado, liquidation_entry_id = v_entry, updated_at = now() where id = r.id;

  v_concepto := format('Contabilizado: asiento %s/%s del %s, 477 contra 472%s.', v_val->>'serie', v_val->>'numero', to_char(v_fecha, 'DD/MM/YYYY'),
                  case when v71 > 0 then ' y ' || public.conta_impuesto_euros(v71) || ' a la 4750'
                       when v71 < 0 then ' y ' || public.conta_impuesto_euros(-v71) || ' a la 4700'
                       else '' end) || coalesce(v_aviso_fecha, '');
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, r.account_id, r.company_id, auth.uid(), v_nombre, 'note', v_concepto, jsonb_build_object('asiento', v_entry, 'fecha', v_fecha));
  return jsonb_build_object('ok', true, 'asiento', v_entry, 'serie', v_val->'serie', 'numero', v_val->'numero', 'fecha', v_fecha, 'mensaje', v_concepto);
end $$;


--
-- Name: FUNCTION conta_impuesto_303_contabilizar(p_return uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_303_contabilizar(p_return uuid) IS 'I01b. El asiento de liquidación del 303 presentado (477 contra 472, el resultado a 4750 o 4700, lo compensado de antes a 4700), validado, y la declaración a «Contabilizado». Un 303 con casillas raras o sin día abierto no se contabiliza y se dice por qué.';


--
-- Name: conta_impuesto_303_desde_libro(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_303_desde_libro(p_company uuid, p_year integer, p_period text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c public.company; v_desde date; v_hasta date; v_box jsonb; v_no jsonb; v_n int; v27 numeric; v45 numeric;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, mira sus impuestos.' using errcode = '42501';
  end if;
  select * into v_desde, v_hasta from public.conta_impuesto_periodo_fechas(p_year, p_period);
  -- Los mismos apuntes que el cálculo (con «deducida en»), con sus casillas.
  with l as (
    select v.tax_base as base, v.tax_amount as cuota, v.deductible_amount as ded, v.book as libro, x.cajas, x.no_sabe
      from public.vat_book_entry v
      cross join lateral public.conta_impuesto_303_cajas(v) x
     where v.account_id = c.account_id and v.company_id = p_company and v.voided_at is null
       and case when v.book in ('received', 'investment') and v.deduction_period is not null
                then v.deduction_year = p_year and v.deduction_period = p_period
                else case when v.book in ('received', 'investment') then coalesce(v.received_date, v.issue_date) else coalesce(v.operation_date, v.issue_date) end
                     between v_desde and v_hasta end
  ), s as (
    select cajas[1] as caja, base as valor from l where cardinality(cajas) >= 1
    union all select cajas[2], case when libro = 'issued' then cuota else ded end from l where cardinality(cajas) = 2
    union all select cajas[2], cuota from l where cardinality(cajas) = 4
    union all select cajas[3], base from l where cardinality(cajas) = 4
    union all select cajas[4], ded from l where cardinality(cajas) = 4
  ), b as (select caja, round(sum(valor), 2) as valor from s where caja is not null group by caja)
  select coalesce((select jsonb_object_agg(caja, valor) from b), '{}'),
         coalesce((select jsonb_object_agg(no_sabe, n) from (select no_sabe, count(*) n from l where no_sabe is not null group by no_sabe) q), '{}'),
         (select count(*) from l)
    into v_box, v_no, v_n;
  select coalesce(sum((v_box->>k)::numeric), 0) into v27
    from unnest(array['152','167','03','155','06','09','11','13','15','158','170','18','21','24','26']) k;
  select coalesce(sum((v_box->>k)::numeric), 0) into v45
    from unnest(array['29','31','33','35','37','39','41','42','43','44']) k;
  return jsonb_build_object('desde', v_desde, 'hasta', v_hasta, 'apuntes', v_n, 'casillas', v_box,
                            '27', v27, '45', v45, '46', v27 - v45, 'no_sabe', v_no);
end $$;


--
-- Name: FUNCTION conta_impuesto_303_desde_libro(p_company uuid, p_year integer, p_period text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_303_desde_libro(p_company uuid, p_year integer, p_period text) IS 'I01d (0300). Las casillas del 303 del periodo que salen del libro de IVA, sin escribir nada: [27], [45] y [46] y lo que Sumied aún no sabe. El testigo de un 303 ya presentado.';


--
-- Name: conta_impuesto_303_fichero(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_303_fichero(p_return uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; c public.company; p public.company_tax_profile; v_tipo text; v_71 numeric; v_iban text; v_redeme boolean; v_n int;
begin
  select * into r from public.tax_return where id = p_return and form_code = '303';
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if exists (select 1 from public.tax_return_check where tax_return_id = r.id and result = 'error' and check_key <> 'file_layout') then
    raise exception 'Este 303 tiene cosas que Sumied no sabe declarar: no se prepara el fichero.' using errcode = '22023';
  end if;
  select count(*) into v_n from public.tax_return_check where tax_return_id = r.id and result = 'warning' and accepted_at is null;
  if v_n > 0 then
    raise exception 'Antes, mira % de «Lo que ha comprobado Sumied» y dalo por bueno si lo está: con un aviso sin mirar no se prepara el fichero.',
      case when v_n = 1 then 'el aviso' else 'los ' || v_n || ' avisos' end using errcode = '22023';
  end if;
  if r.result_kind is null then
    raise exception 'Este 303 no tiene resultado todavía: no se prepara el fichero.' using errcode = '22023';
  end if;
  select * into c from public.company where id = r.company_id;
  select * into p from public.company_tax_profile where company_id = r.company_id;
  select value into v_71 from public.tax_return_box where tax_return_id = r.id and box = '71';
  select coalesce((value = 'true'::jsonb), false) into v_redeme from public.company_tax_facts where company_id = r.company_id and fact = 'redeme';
  v_tipo := case when coalesce(v_71, 0) = 0 then 'N'
                 when v_71 > 0 then case when r.payment_mode = 'direct_debit' then 'U' else 'I' end
                 when r.result_kind = 'to_refund' then 'D' else 'C' end;
  if v_tipo in ('U', 'D') then
    select iban into v_iban from public.treasury_account where id = r.payment_treasury_account_id and company_id = r.company_id;
  end if;
  return jsonb_build_object('ejercicio', r.fiscal_year, 'periodo', r.period, 'nif', c.tax_id, 'nombre', c.legal_name, 'tipo', v_tipo,
                            'redeme', coalesce(v_redeme, false), 'sii', coalesce(p.sii, false), 'iban', v_iban,
                            'sin_actividad', r.result_kind = 'no_activity',
                            'casillas', (select jsonb_object_agg(box, value) from public.tax_return_box where tax_return_id = r.id and value is not null));
end $$;


--
-- Name: conta_impuesto_303_fichero_comprobado(uuid, boolean, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_303_fichero_comprobado(p_return uuid, p_ok boolean, p_fallos jsonb, p_huella text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return;
begin
  select * into r from public.tax_return where id = p_return;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, r.account_id, r.company_id, 'file_layout', case when p_ok then 'ok' else 'error' end,
          case when p_ok then 'El fichero cumple el diseño de registro de la AEAT (DR303e26v101): medidas, tipos, constantes y sumas.'
               else 'El fichero no cumple el diseño de registro: ' || coalesce((select string_agg(x, ' ') from jsonb_array_elements_text(p_fallos) x), 'sin detalle') end,
          jsonb_build_object('fallos', coalesce(p_fallos, '[]'), 'huella', p_huella))
  on conflict (tax_return_id, check_key) do update set result = excluded.result, title = excluded.title, detail = excluded.detail, checked_at = now();
end $$;


--
-- Name: conta_impuesto_303_preparar(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_303_preparar(p_return uuid, p_user uuid, p_confirmation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; t public.tax_certificate_confirmation;
begin
  select * into r from public.tax_return where id = p_return and form_code = '303';
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_gestiona(p_user, r.company_id) then
    raise exception 'No puedes presentar los impuestos de esta empresa.' using errcode = '42501';
  end if;
  select * into t from public.tax_certificate_confirmation where id = p_confirmation;
  if t.id is null or t.user_id is distinct from p_user or t.action <> 'file' or t.tax_return_id is distinct from r.id then
    raise exception 'Esa confirmación no es para presentar esta declaración. Vuelve a pulsar y confirmar.' using errcode = '42501';
  end if;
  if t.used_at is not null or t.expires_at <= now() then
    raise exception 'Esa confirmación ya se usó o ha caducado (dura 5 minutos). Vuelve a pulsar y confirmar.' using errcode = '22023';
  end if;
  if r.status <> 'reviewed' then
    raise exception 'Antes de presentar, alguien tiene que revisarla: está «%».', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  return public.conta_impuesto_303_fichero(r.id) || jsonb_build_object('declaracion', r.id, 'empresa', r.company_id, 'cuenta', r.account_id);
end $$;


--
-- Name: conta_impuesto_anual(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_anual(p_company uuid, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_modelos jsonb; v_desde date;
begin
  if not exists (select 1 from public.company where id = p_company) then
    raise exception 'Esa empresa no está.' using errcode = 'P0002';
  end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;
  if p_year is null or p_year < 2000 or p_year > extract(year from now())::int + 1 then
    raise exception 'El ejercicio «%» no es un año que se pueda mirar.', p_year using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'modelo', o.form_code, 'nombre', f.name, 'cadencia', o.cadence, 'periodo', '0A', 'no_toca', false,
           'presentacion', pl.presentacion, 'domiciliacion', null,
           'declaracion', case when r.id is null then null else jsonb_build_object(
             'id', r.id, 'cuenta', r.account_id, 'estado', r.status, 'estado_texto', public.conta_impuesto_estado_texto(r.status),
             'resultado', r.result_kind, 'importe', r.amount,
             'presentada', r.filed_at, 'presentada_por', r.filed_by_name, 'por', r.filed_via,
             'csv', r.aeat_csv, 'justificante', r.aeat_receipt_number, 'justificante_pdf', r.receipt_document_path,
             'traido', r.receipt_source = 'aeat_csv', 'expediente', r.aeat_expediente,
             'presentador', case when r.presenter_tax_id is not null or r.presenter_name is not null
                                 then jsonb_build_object('nif', r.presenter_tax_id, 'nombre', r.presenter_name) end,
             'casillas', (select coalesce(jsonb_agg(jsonb_build_object('casilla', b.box, 'valor', b.value, 'texto', b.value_text,
                                                                       'origen', b.origin, 'motivo', b.manual_reason)
                                                    order by length(b.box), b.box), '[]')
                            from public.tax_return_box b where b.tax_return_id = r.id)) end
         ) order by case o.form_code when '390' then 1 when '190' then 2 when '180' then 3 when '347' then 4 when '349' then 5 else 6 end, o.form_code), '[]')
    into v_modelos
    from public.tax_obligation o
    join public.tax_form f on f.code = o.form_code
    left join lateral public.conta_impuesto_plazo_si_hay(o.form_code, o.cadence, p_year, '0A') pl on true
    left join public.tax_return r on r.company_id = p_company and r.form_code = o.form_code and r.fiscal_year = p_year and r.period = '0A' and r.sequence = 1
   where o.company_id = p_company and o.valid_to is null and o.active and o.cadence = 'annual';

  select min(valid_from) into v_desde from public.tax_obligation where company_id = p_company and valid_to is null and active;

  return jsonb_build_object(
    'empresa', (select jsonb_build_object('id', c.id, 'nombre', coalesce(nullif(c.trade_name, ''), c.legal_name), 'razon_social', c.legal_name, 'nif', c.tax_id)
                  from public.company c where c.id = p_company),
    'ejercicio', p_year, 'trimestre', '0A', 'desde', v_desde,
    'puede_gestionar', public.conta_impuesto_puede_gestionar(p_company),
    'modelos', v_modelos,
    'cartera', jsonb_build_object('filas', '[]'::jsonb, 'pendiente_al_empezar', null, 'esperada_110', null, 'borrador', null, 'desfasada', false));
end $$;


--
-- Name: FUNCTION conta_impuesto_anual(p_company uuid, p_year integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_anual(p_company uuid, p_year integer) IS 'S02. La tira del año: los modelos anuales que presenta la empresa (390, 190, 180, 347, 349) con su plazo y su declaración, con la forma de conta_impuesto_trimestre. Solo lee.';


--
-- Name: conta_impuesto_aviso_aceptar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_aviso_aceptar(p_check uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare k public.tax_return_check; r public.tax_return;
begin
  select * into k from public.tax_return_check where id = p_check for update;
  if k.id is null then raise exception 'Esa comprobación no está.' using errcode = 'P0002'; end if;
  select * into r from public.tax_return where id = k.tax_return_id;
  if not public.conta_impuesto_puede_gestionar(r.company_id) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, da por bueno un aviso.' using errcode = '42501';
  end if;
  if k.result <> 'warning' then raise exception 'Solo se da por bueno un aviso; un error no.' using errcode = '22023'; end if;
  if p_motivo is null or btrim(p_motivo) = '' then raise exception 'Para dar por bueno un aviso hace falta decir por qué.' using errcode = '22023'; end if;
  if r.status not in ('draft', 'reviewed') then raise exception 'Esta declaración ya está «%».', public.conta_impuesto_estado_texto(r.status) using errcode = '22023'; end if;
  update public.tax_return_check set accepted_by = auth.uid(), accepted_by_name = public.conta_impuesto_quien(), accepted_at = now(), accepted_reason = btrim(p_motivo)
   where id = k.id;
  return jsonb_build_object('ok', true, 'mensaje', public.conta_impuesto_quien() || ' lo dio por bueno el ' || to_char(now() at time zone 'Europe/Madrid', 'DD/MM') || ': ' || btrim(p_motivo));
end $$;


--
-- Name: conta_impuesto_cadencia_de(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_cadencia_de(p_company uuid, p_form text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when p_form in ('303', '349', '111', '115') then
      case when (select vat_period from public.company_tax_profile where company_id = p_company) = 'monthly' then 'monthly' else 'quarterly' end
    when p_form = '202' then 'instalments_202'
    else 'annual' end
$$;


--
-- Name: conta_impuesto_calendario(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_calendario(p_company uuid, p_hoy date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_hoy date := coalesce(p_hoy, (now() at time zone 'Europe/Madrid')::date);
  v_y int := extract(year from coalesce(p_hoy, (now() at time zone 'Europe/Madrid')::date))::int;
  v_desde date; v_ventana date; v_filas jsonb; v_siguiente jsonb; v_reglas jsonb; v_no jsonb; v_pres jsonb;
begin
  if not exists (select 1 from public.company where id = p_company) then
    raise exception 'Esa empresa no está.' using errcode = 'P0002';
  end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;

  select min(valid_from) into v_desde from public.tax_obligation where company_id = p_company and valid_to is null and active;

  -- La ventana: el mes del próximo plazo de presentación que hay que presentar.
  -- S02 · PR 3 (0490): lo que está «No hace falta» (not_required) no la abre;
  -- antes, el 202 3P de diciembre a cero la llevaba a diciembre el 22/10.
  select date_trunc('month', min(c.presentacion))::date into v_ventana
    from public.conta_impuesto_periodos(p_company, v_y) c
    left join public.tax_return r on r.company_id = p_company and r.form_code = c.modelo and r.fiscal_year = c.ejercicio
                                  and r.period = c.periodo and r.sequence = 1
   where c.presentacion >= v_hoy and coalesce(r.status, 'pending') <> 'not_required';

  with d as (
    select c.*, r.id as rid, r.status, r.result_kind, r.amount, r.previous_period_amount, r.not_required_reason,
           coalesce(r.payment_mode, case when c.pago = 'direct_debit' then 'direct_debit' end) as pago_real,
           coalesce(r.payment_treasury_account_id, c.cuenta) as cuenta_real,
           r.filed_at, r.filed_via, r.due_date
      from public.conta_impuesto_periodos(p_company, v_y) c
      left join public.tax_return r on r.company_id = p_company and r.form_code = c.modelo and r.fiscal_year = c.ejercicio
                                    and r.period = c.periodo and r.sequence = 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'obligacion', d.obligacion, 'modelo', d.modelo, 'nombre', f.name, 'cadencia', d.cadencia,
           'ejercicio', d.ejercicio, 'periodo', d.periodo,
           'presentacion', d.presentacion, 'domiciliacion', d.domiciliacion, 'provisional', d.provisional,
           'atrasado', d.presentacion < v_hoy,
           'domicilia', coalesce(d.pago_real = 'direct_debit', false),
           'cuenta_final', (select right(t.iban, 4) from public.treasury_account t where t.id = d.cuenta_real and t.company_id = p_company),
           'se_calcula', d.modelo = '303',
           'declaracion', case when d.rid is null then null else jsonb_build_object(
             'id', d.rid, 'estado', d.status, 'estado_texto', public.conta_impuesto_estado_texto(d.status),
             'resultado', d.result_kind, 'importe', d.amount, 'anterior', d.previous_period_amount,
             'no_hace_falta', d.not_required_reason,
             'presentada', d.filed_at, 'por', d.filed_via,
             'errores', (select count(*) from public.tax_return_check k where k.tax_return_id = d.rid and k.result = 'error'),
             'avisos', (select count(*) from public.tax_return_check k where k.tax_return_id = d.rid and k.result = 'warning' and k.accepted_at is null),
             'aviso', (select k.title from public.tax_return_check k where k.tax_return_id = d.rid and k.result in ('error', 'warning') and k.accepted_at is null
                        order by (k.result = 'error') desc, k.checked_at limit 1),
             'cuadra', exists (select 1 from public.tax_return_check k where k.tax_return_id = d.rid and k.check_key = 'book_vs_303' and k.result = 'ok')
                   and exists (select 1 from public.tax_return_check k where k.tax_return_id = d.rid and k.check_key = 'ledger_477_472' and (k.result = 'ok' or k.accepted_at is not null))) end
         ) order by d.presentacion, d.modelo, d.ejercicio, d.periodo), '[]')
    into v_filas
    from d join public.tax_form f on f.code = d.modelo
   where (v_ventana is not null and date_trunc('month', d.presentacion)::date = v_ventana)
      -- Lo de antes que no se ha presentado: desde que lleva aquí sus impuestos, o si tiene declaración.
      or (d.presentacion < v_hoy
          and coalesce(d.status, 'pending') in ('pending', 'draft', 'reviewed')
          and (d.rid is not null or (v_desde is not null and d.presentacion >= v_desde)))
      -- I01h · Lo que no hacía falta presentar y venció hace poco (el último mes): se
      -- enseña con su porqué, para que no desaparezca sin decir nada (Julio, 21/10).
      or (d.presentacion < v_hoy and d.status = 'not_required' and d.presentacion >= v_hoy - 31)
      -- S02 · PR 3 (0490) · Lo que no hace falta presentar y vence ANTES de la
      -- ventana (que ya no se abre por ello): sale igual, con su porqué, para
      -- que no desaparezca (regla 7). El 202 3P de diciembre, el 22/10.
      or (d.presentacion >= v_hoy and d.status = 'not_required' and (v_ventana is null or d.presentacion < v_ventana));

  -- Lo siguiente: los plazos de después de la ventana, hasta un año.
  select coalesce(jsonb_agg(jsonb_build_object('modelo', c.modelo, 'nombre', f.name, 'cadencia', c.cadencia, 'ejercicio', c.ejercicio,
                                               'periodo', c.periodo, 'presentacion', c.presentacion, 'domiciliacion', c.domiciliacion)
                            order by c.presentacion, c.modelo), '[]')
    into v_siguiente
    from public.conta_impuesto_periodos(p_company, v_y) c join public.tax_form f on f.code = c.modelo
   where v_ventana is not null and c.presentacion >= (v_ventana + interval '1 month')::date
     and c.presentacion < (v_ventana + interval '1 year')::date;

  -- Los presentados del año: los periodos con plazo en el año que ya han vencido
  -- (desde que lleva aquí sus impuestos, o con declaración), y cuántos están presentados.
  with v as (
    select c.*, r.id as rid, r.status, r.filed_at, r.due_date
      from public.conta_impuesto_periodos(p_company, v_y) c
      left join public.tax_return r on r.company_id = p_company and r.form_code = c.modelo and r.fiscal_year = c.ejercicio
                                    and r.period = c.periodo and r.sequence = 1
     where extract(year from c.presentacion) = v_y
       and (c.presentacion < v_hoy or r.filed_at is not null)
       and coalesce(r.status, 'pending') <> 'not_required'
       and (r.id is not null or (v_desde is not null and c.presentacion >= v_desde))
  )
  select jsonb_build_object('ano', v_y, 'desde', v_desde,
           'vencidos', count(*),
           'presentados', count(*) filter (where status in ('filed', 'booked', 'paid', 'offset', 'refunded')),
           'en_plazo', count(*) filter (where filed_at is not null and (filed_at at time zone 'Europe/Madrid')::date <= presentacion),
           'contabilizados', count(*) filter (where status in ('booked', 'paid', 'offset', 'refunded')))
    into v_pres from v;

  -- Por qué le sale cada modelo, y los que no.
  select coalesce(jsonb_agg(jsonb_build_object('modelo', o2.form_code, 'nombre', f.name, 'por_que', o2.why, 'origen', o2.origin,
                                               'cadencia', o2.cadence, 'quien', o2.decided_by_name, 'cuando', o2.decided_at)
                            order by o2.form_code) filter (where o2.active), '[]'),
         coalesce(jsonb_agg(jsonb_build_object('modelo', o2.form_code, 'nombre', f.name, 'por_que', o2.why, 'origen', o2.origin)
                            order by o2.form_code) filter (where not o2.active), '[]')
    into v_reglas, v_no
    from public.tax_obligation o2 join public.tax_form f on f.code = o2.form_code
   where o2.company_id = p_company and o2.valid_to is null;
  -- 0250: y las reglas que dicen que no y nunca se escribieron (calcular no
  -- escribe una regla inactiva sin fila previa): «No te sale el 349: …».
  v_no := v_no || coalesce((select jsonb_agg(jsonb_build_object('modelo', r.form_code, 'nombre', f.name, 'por_que', r.why, 'origen', 'rule')
                                              order by r.form_code)
                              from public.conta_impuesto_reglas(p_company) r join public.tax_form f on f.code = r.form_code
                             where not r.active
                               and not exists (select 1 from public.tax_obligation o3 where o3.company_id = p_company
                                                                                       and o3.valid_to is null and o3.form_code = r.form_code)), '[]');

  return jsonb_build_object(
    'hoy', v_hoy, 'ventana', v_ventana, 'desde', v_desde,
    -- Para los avisos de Inicio: el certificado con que presenta la empresa (su caducidad)…
    'certificado', (select jsonb_build_object('titular', t.subject_name, 'caduca', t.valid_to)
                      from public.company_tax_presenter pr join public.tax_certificate t on t.id = pr.certificate_id
                     where pr.company_id = p_company and pr.mode = 'company' and t.status <> 'removed'),
    -- …y lo presentado a pagar cuyo cargo no ha llegado al banco dos días después del plazo (respuesta 5 de Julio).
    'pagos_sin_llegar', (select coalesce(jsonb_agg(jsonb_build_object('declaracion', r.id, 'modelo', r.form_code, 'ejercicio', r.fiscal_year,
                                                                      'periodo', r.period, 'importe', r.amount, 'plazo', r.due_date,
                                                                      'domicilia', r.payment_mode = 'direct_debit') order by r.due_date), '[]')
                           from public.tax_return r
                          where r.company_id = p_company and r.status in ('filed', 'booked') and r.result_kind = 'to_pay'
                            and r.bank_match_id is null and r.due_date < v_hoy - 2 and r.due_date > v_hoy - 400),
    'puede_gestionar', public.conta_impuesto_puede_gestionar(p_company),
    'filas', v_filas, 'siguiente', v_siguiente, 'presentados', v_pres,
    'modelos', v_reglas, 'no_presenta', v_no,
    -- Para «+ Añadir otro impuesto»: los modelos que conoce Sumied y no están en la lista.
    'se_pueden_anadir', (select coalesce(jsonb_agg(jsonb_build_object('modelo', f.code, 'nombre', f.name) order by f.code), '[]')
                           from public.tax_form f
                          where f.code in (select distinct form_code from public.tax_form_deadline)
                            and not exists (select 1 from public.tax_obligation o3 where o3.company_id = p_company and o3.valid_to is null
                                                                                    and o3.active and o3.form_code = f.code)));
end $$;


--
-- Name: FUNCTION conta_impuesto_calendario(p_company uuid, p_hoy date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_calendario(p_company uuid, p_hoy date) IS 'I01b (0250). Lo que pinta Impuestos › Calendario: los periodos que tocan con su plazo y su declaración, lo siguiente, los presentados del año y el porqué de cada modelo. No escribe nada.';


--
-- Name: conta_impuesto_cargos_posibles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_cargos_posibles(p_return uuid) RETURNS TABLE(movimiento uuid, fecha date, importe numeric, concepto text, cuenta text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; v_hasta date;
begin
  select * into r from public.tax_return where id = p_return;
  if r.id is null or not public.current_user_is_admin_or_manager_of(r.account_id) then
    raise exception 'Esa declaración no es de tu cuenta.' using errcode = '42501';
  end if;
  if coalesce(r.result_kind, '') not in ('to_pay', 'to_refund') or coalesce(r.amount, 0) = 0 then return; end if;
  select hasta into v_hasta from public.conta_impuesto_periodo_fechas(r.fiscal_year, r.period);
  return query
    select m.id, m.op_date, m.amount, nullif(m.clean_concept, ''), t.name
      from public.bank_movement m join public.treasury_account t on t.id = m.treasury_account_id
     where m.account_id = r.account_id and m.company_id = r.company_id and m.status = 'pendiente' and not m.before_cutover
       and m.amount = case when r.result_kind = 'to_pay' then -r.amount else r.amount end
       and m.op_date > v_hasta
       and not exists (select 1 from public.bank_match b where b.movement_id = m.id and b.status = 'vivo')
     order by abs(m.op_date - coalesce(r.due_date_direct_debit, r.due_date)), m.op_date;
end $$;


--
-- Name: conta_impuesto_casar_cargo(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_casar_cargo(p_return uuid, p_movement uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r public.tax_return; m public.bank_movement; v_cta text; v_casado jsonb; v_match uuid; v_entry uuid; v_aviso text; v_estado text;
  v_esperado numeric; v_nombre text := public.conta_impuesto_quien();
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(r.account_id) then
    raise exception 'El pago lo casa un administrador o un encargado de la empresa.' using errcode = '42501';
  end if;
  if r.status not in ('filed', 'booked') then
    raise exception 'Esta declaración está «%»: el pago se casa cuando está presentada.', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if coalesce(r.result_kind, '') not in ('to_pay', 'to_refund') or coalesce(r.amount, 0) = 0 then
    raise exception 'Este 303 no sale a pagar ni a devolver: no hay cargo que casar.' using errcode = '22023';
  end if;
  select * into m from public.bank_movement where id = p_movement;
  if m.id is null or m.company_id <> r.company_id or m.account_id <> r.account_id then
    raise exception 'Ese movimiento no es de la empresa de la declaración.' using errcode = '42501';
  end if;
  -- (El IF de PL/pgSQL corta en el primer THEN: el CASE, fuera.)
  v_esperado := case when r.result_kind = 'to_pay' then -r.amount else r.amount end;
  if m.amount <> v_esperado then
    raise exception 'El movimiento es de % y la declaración, de % %.', public.conta_impuesto_euros(m.amount), public.conta_impuesto_euros(r.amount),
      case when r.result_kind = 'to_pay' then 'a pagar' else 'a devolver' end using errcode = '22023';
  end if;
  if r.form_code in ('111', '115', '123') then
    -- S01d: una retención se paga en la subcuenta de la 4751 de su modelo (la que lo dice en su
    -- configuración; si ninguna lo dice y solo hay una, ésa), con su modelo y su periodo en la línea.
    select min(code) into v_cta from public.company_account where company_id = r.company_id and template_code like '4751%' and withholding_model = r.form_code
     having count(*) = 1;
    if v_cta is null then
      select min(code) into v_cta from public.company_account where company_id = r.company_id and template_code like '4751%' and kind <> 'template'
       having count(*) = 1;
    end if;
    if v_cta is null then
      raise exception 'No sé en qué subcuenta de la 4751 va el %: dilo en la cuenta (su modelo).', r.form_code using errcode = '23514';
    end if;
  else
    select min(code) into v_cta from public.company_account where company_id = r.company_id
       and template_code = case when r.result_kind = 'to_pay' then '4750' else '4700' end;
    if v_cta is null then raise exception 'La cuenta % no está en el plan de la empresa.', case when r.result_kind = 'to_pay' then '4750' else '4700' end using errcode = '23514'; end if;
  end if;

  v_casado := public.bank_casar(m.id,
    jsonb_build_object('tipo', 'cuenta', 'concepto', 'Pago del ' || r.form_code || ' ' || r.period || '/' || r.fiscal_year,
                       'lineas', jsonb_build_array(jsonb_build_object('cuenta', v_cta, 'importe', r.amount,
                                                   'concepto', 'Pago del ' || r.form_code || ' ' || r.period || '/' || r.fiscal_year)
                                                   || case when r.form_code in ('111', '115', '123')
                                                           then jsonb_build_object('modelo', r.form_code, 'periodo', r.fiscal_year || '-' || r.period) else '{}'::jsonb end)),
    'seguro', 'Es el ' || case when r.result_kind = 'to_pay' then 'cargo' else 'abono' end || ' del ' || r.form_code || ' ' || r.period || '/' || r.fiscal_year || ' por su importe.',
    jsonb_build_array(jsonb_build_object('decision', 'pago-impuesto', 'declaracion', r.id)), 'persona', null);
  v_match := (v_casado->>'match')::uuid; v_entry := (v_casado->>'asiento')::uuid;
  insert into public.bank_match_item (account_id, match_id, tax_return_id, amount, marked_by_bank)
  values (r.account_id, v_match, r.id, m.amount, true);

  -- El asiento del pago, validado: lo ha confirmado la persona. Si no se puede, queda propuesto y se dice.
  if exists (select 1 from public.journal_entry where id = v_entry and status in ('propuesto', 'borrador')) then
    begin
      perform public.journal_entry_validar(v_entry, v_nombre);
    exception when others then
      v_aviso := ' Su asiento queda propuesto: ' || sqlerrm;
    end;
  end if;

  v_estado := case when r.result_kind = 'to_pay' then 'paid' else 'refunded' end;
  update public.tax_return set status = v_estado, bank_match_id = v_match, payment_entry_id = v_entry, updated_at = now() where id = r.id;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, r.account_id, r.company_id, auth.uid(), v_nombre, 'note',
          format('%s con el movimiento del %s por %s.%s', case when v_estado = 'paid' then 'Pagado' else 'Devuelto' end,
                 to_char(m.op_date, 'DD/MM/YYYY'), public.conta_impuesto_euros(abs(m.amount)), coalesce(v_aviso, '')),
          jsonb_build_object('casado', v_match, 'asiento', v_entry, 'movimiento', m.id));
  return jsonb_build_object('ok', true, 'casado', v_match, 'asiento', v_entry,
    'mensaje', format('%s: casado con el movimiento del %s por %s.%s', case when v_estado = 'paid' then 'Pagado' else 'Devuelto' end,
                      to_char(m.op_date, 'DD/MM/YYYY'), public.conta_impuesto_euros(abs(m.amount)), coalesce(v_aviso, '')));
end $$;


--
-- Name: conta_impuesto_casillas_poner(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_casillas_poner(p_return uuid, p_casillas jsonb, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r public.tax_return; k text; v jsonb; n numeric; v_quien text := public.conta_impuesto_quien(); v_motivo text; v_c jsonb;
  v_vale constant text[] := array['01','03','04','06','07','09','27','28','29','30','31','40','41','45','46','59','60','64','66','69','71','78','87','110','120','122'];
  v_calc jsonb; v_n int := 0;
begin
  select * into r from public.tax_return where id = p_return and form_code = '303' for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(r.company_id) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, escribe casillas de sus impuestos.' using errcode = '42501';
  end if;
  if r.status not in ('pending', 'draft', 'reviewed') then
    raise exception 'Esta declaración ya está «%»: sus casillas no se cambian.', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if p_casillas is null or jsonb_typeof(p_casillas) <> 'object' or p_casillas = '{}'::jsonb then
    raise exception 'Faltan las casillas que hay que escribir.' using errcode = '22023';
  end if;
  if p_motivo is null or btrim(p_motivo) = '' then raise exception 'Para escribir una casilla a mano hace falta decir de dónde sale.' using errcode = '22023'; end if;
  v_motivo := btrim(p_motivo) || ' (' || v_quien || ', ' || to_char(now() at time zone 'Europe/Madrid', 'DD/MM/YYYY') || ')';
  for k, v in select * from jsonb_each(p_casillas) loop
    if not (k = any (v_vale)) then
      raise exception 'La casilla [%] no se escribe aquí: solo las que el 303 de Sumied calcula.', k using errcode = '22023';
    end if;
    if jsonb_typeof(v) not in ('number', 'null') then
      raise exception 'La casilla [%] tiene que ser un importe.', k using errcode = '22023';
    end if;
    if k in ('110', '78', '87') and jsonb_typeof(v) = 'number' and (v #>> '{}')::numeric < 0 then
      raise exception 'La casilla [%] no puede ser negativa: son cuotas a compensar.', k using errcode = '22023';
    end if;
  end loop;
  -- Lo que quedará: las de ahora a mano, con las nuevas encima.
  select coalesce(jsonb_object_agg(box, value), '{}') into v_c from public.tax_return_box where tax_return_id = r.id and origin = 'manual' and value is not null;
  v_c := jsonb_strip_nulls(v_c || p_casillas);
  if v_c ?& array['27', '45', '71'] and abs(((v_c->>'27')::numeric - (v_c->>'45')::numeric - coalesce((v_c->>'78')::numeric, 0)) - (v_c->>'71')::numeric) >= 0.005 then
    raise exception 'Las casillas no cuadran: [27] − [45] − [78] tiene que dar la [71] (% − % − % no es %). Mira el justificante otra vez.',
      v_c->>'27', v_c->>'45', coalesce(v_c->>'78', '0'), v_c->>'71' using errcode = '22023';
  end if;
  if v_c ?& array['110', '87'] and abs(((v_c->>'110')::numeric - coalesce((v_c->>'78')::numeric, 0)) - (v_c->>'87')::numeric) >= 0.005 then
    raise exception 'Las casillas no cuadran: [110] − [78] tiene que dar la [87] (% − % no es %). Mira el justificante otra vez.',
      v_c->>'110', coalesce(v_c->>'78', '0'), v_c->>'87' using errcode = '22023';
  end if;
  for k, v in select * from jsonb_each(p_casillas) loop
    if jsonb_typeof(v) = 'null' then
      delete from public.tax_return_box where tax_return_id = r.id and box = k and origin = 'manual';
    else
      insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, origin, manual_reason, source)
      values (r.id, r.account_id, r.company_id, k, round((v #>> '{}')::numeric, 2), 'manual', v_motivo, jsonb_build_object('de', 'a mano', 'quien', v_quien))
      on conflict (tax_return_id, box) do update
        set value = excluded.value, value_text = null, origin = 'manual', manual_reason = excluded.manual_reason, source = excluded.source;
    end if;
    v_n := v_n + 1;
  end loop;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, r.account_id, r.company_id, auth.uid(), v_quien, 'note',
          v_quien || ' escribió a mano ' || (select string_agg('[' || x || ']', ', ' order by x) from jsonb_object_keys(p_casillas) x) || ': ' || btrim(p_motivo) || '.',
          jsonb_build_object('casillas', p_casillas));
  v_calc := public.conta_impuesto_303_calcular(r.company_id, r.fiscal_year, r.period);
  return jsonb_build_object('ok', true, 'calculo', v_calc,
    'mensaje', 'Escritas ' || (select string_agg('[' || x || ']', ', ' order by x) from jsonb_object_keys(p_casillas) x) || ' y vuelto a calcular: ' ||
               case when (v_calc->>'sabido')::boolean
                    then translate(to_char((v_calc->>'importe')::numeric, 'FM999G999G990D00'), ',.', '.,') || ' € ' ||
                         case v_calc->>'resultado' when 'to_pay' then 'a pagar' when 'to_offset' then 'a compensar' when 'to_refund' then 'a devolver' else 'sin nada que pagar' end || '.'
                    else 'todavía no se puede calcular (mira «Lo que ha comprobado Sumied»).' end);
end $$;


--
-- Name: FUNCTION conta_impuesto_casillas_poner(p_return uuid, p_casillas jsonb, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_casillas_poner(p_return uuid, p_casillas jsonb, p_motivo text) IS 'I01b (0240). Escribe a mano casillas del 303 (la [110], o las del justificante de lo presentado fuera), con motivo y quién; null quita la manual. Comprueba que cuadran y vuelve a calcular.';


--
-- Name: conta_impuesto_certificado_presenta(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_certificado_presenta(p_company uuid, p_certificate uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.company; t public.tax_certificate;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(c.account_id) then
    raise exception 'Solo un administrador de la empresa decide quién presenta sus impuestos.' using errcode = '42501';
  end if;
  select * into t from public.tax_certificate where id = p_certificate and owner_account_id = c.account_id;
  if t.id is null then raise exception 'Ese certificado no es de esta cuenta.' using errcode = '42501'; end if;
  if t.status <> 'active' or t.valid_to <= now() then
    raise exception 'Ese certificado no se puede usar: está %.', case when t.status = 'removed' then 'quitado' else 'caducado' end using errcode = '22023';
  end if;
  insert into public.company_tax_presenter (company_id, account_id, mode, certificate_id, since)
  values (p_company, c.account_id, 'company', t.id, current_date)
  on conflict (company_id) do update set mode = 'company', certificate_id = t.id, advisor_account_id = null, advisor_basis = null,
    consented_by = null, consented_by_name = null, consented_at = null, revoked_by = null, revoked_at = null, since = current_date, updated_at = now();
  return jsonb_build_object('ok', true, 'mensaje', format('Presenta la propia empresa, con el certificado de %s (válido hasta el %s).',
                            t.subject_name, to_char(t.valid_to at time zone 'Europe/Madrid', 'DD/MM/YYYY')));
end $$;


--
-- Name: conta_impuesto_certificados_ver(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_certificados_ver(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.company; pr public.company_tax_presenter; v_admin boolean; v_no text;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;
  select * into pr from public.company_tax_presenter where company_id = p_company;
  v_admin := public.current_user_is_admin_of(c.account_id);
  -- Por qué no puede subir uno: lo mismo, y en el mismo orden, que conta_cert_guardar.
  v_no := case
    when not v_admin then 'Solo un administrador de la cuenta puede subir un certificado.'
    when c.account_id <> public.conta_cert_cuenta_vault() then
      'Todavía no se pueden guardar certificados en esta cuenta: falta el almacén con clave externa (KMS), y hasta que esté solo se admite la cuenta de Foodint. No se ha guardado nada.'
  end;
  return jsonb_build_object(
    'cuenta', c.account_id,
    'es_admin', v_admin,
    'puede_subir', v_no is null,
    'por_que_no_subir', v_no,
    'presentador', jsonb_build_object(
      'modo', coalesce(pr.mode, 'company'),
      'certificado', pr.certificate_id,
      'asesoria', (select a.name from public.accounts a where a.id = pr.advisor_account_id),
      'base', pr.advisor_basis,
      'consentida_por', pr.consented_by_name, 'consentida_el', pr.consented_at,
      'retirada_el', pr.revoked_at, 'desde', pr.since),
    'certificados', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', t.id, 'titular', t.subject_name, 'nif_cola', t.subject_tax_id_tail, 'tipo', t.kind, 'emisor', t.issuer,
               'desde', t.valid_from, 'caduca', t.valid_to, 'estado', t.status, 'almacen', t.storage,
               'custodia', public.conta_cert_custodia(t.storage),
               'subido', t.uploaded_at, 'subido_por', t.uploaded_by_name,
               'quitado', t.removed_at, 'quitado_por', t.removed_by_name,
               'probado', t.last_test_at, 'prueba', t.last_test_result, 'prueba_mensaje', t.last_test_message,
               'presenta', t.id = pr.certificate_id and coalesce(pr.mode, 'company') = 'company',
               'permisos', (select coalesce(jsonb_agg(jsonb_build_object('persona', g.user_id, 'nombre', public.conta_cert_nombre(g.user_id, t.owner_account_id),
                                                                        'permiso', g.permission) order by g.permission, g.granted_at), '[]')
                              from public.tax_certificate_grant g where g.certificate_id = t.id and g.revoked_at is null))
             order by (t.status = 'active') desc, t.uploaded_at desc), '[]')
        from public.tax_certificate t
       where t.owner_account_id = c.account_id and (t.status <> 'removed' or t.removed_at > now() - interval '90 days')),
    'usos', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'cuando', u.at, 'quien', u.user_name, 'accion', u.action, 'resultado', u.result, 'mensaje', u.message,
               'declaracion', case when r.id is null then null else jsonb_build_object(
                 'id', r.id, 'modelo', r.form_code, 'ejercicio', r.fiscal_year, 'periodo', r.period, 'justificante_pdf', r.receipt_document_path) end)
             order by u.at desc), '[]')
        from (select * from public.tax_certificate_use u0
               where u0.owner_account_id = c.account_id
                 and exists (select 1 from public.tax_certificate t0 where t0.id = u0.certificate_id and t0.owner_account_id = c.account_id)
               order by u0.at desc limit 50) u
        left join public.tax_return r on r.id = u.tax_return_id and r.company_id = p_company),
    'personas', case when not v_admin then '[]'::jsonb else (
      select coalesce(jsonb_agg(jsonb_build_object('id', p.user_id, 'nombre', coalesce(nullif(trim(p.display_name), ''), 'Sin nombre'), 'papel', p.role)
                                order by p.display_name), '[]')
        from public.user_profiles p where p.account_id = c.account_id and p.active) end);
end $$;


--
-- Name: FUNCTION conta_impuesto_certificados_ver(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_certificados_ver(p_company uuid) IS 'I01b. Lo que pinta Certificados y accesos: quién presenta, los certificados (solo la ficha), permisos, usos, custodia y si se puede subir uno. Nada del material.';


--
-- Name: conta_impuesto_dato_poner(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_dato_poner(p_company uuid, p_fact text, p_value jsonb, p_origin text DEFAULT 'ajustes'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_nombre text;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, cambia estos datos.' using errcode = '42501';
  end if;
  v_nombre := public.conta_impuesto_quien();
  insert into public.company_tax_facts (company_id, account_id, fact, value, origin, said_by, said_by_name, said_at)
  values (p_company, v_acc, p_fact, case when p_value = 'null'::jsonb then null else p_value end, p_origin, auth.uid(), v_nombre, now())
  on conflict (company_id, fact) do update set value = excluded.value, origin = excluded.origin, said_by = excluded.said_by,
    said_by_name = excluded.said_by_name, said_at = excluded.said_at;
end $$;


--
-- Name: conta_impuesto_datos_del_alta(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_datos_del_alta(p_company uuid, p_respuestas jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare k text; v text; v_fact text; n int := 0;
begin
  for k, v in select key, value #>> '{}' from jsonb_each(coalesce(p_respuestas, '{}')) loop
    v_fact := case k when 'retiene' then 'pays_with_withholding' when 'alquiler' then 'rents_premises_with_withholding'
                     when 'retenido70' then 'withheld_income_70' end;
    continue when v_fact is null;
    if v not in ('__nolose', 'si', 'no') then
      raise exception 'La respuesta «%» a «%» no es sí, no ni «No lo sé».', v, k using errcode = '22023';
    end if;
    perform public.conta_impuesto_dato_poner(p_company, v_fact,
      case v when '__nolose' then 'null'::jsonb when 'si' then 'true'::jsonb else 'false'::jsonb end, 'alta');
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: conta_impuesto_declaracion_ver(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_declaracion_ver(p_company uuid, p_year integer, p_period text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  o public.tax_obligation; r public.tax_return; a public.tax_return; pr public.company_tax_presenter; ce public.tax_certificate;
  v_desde date; v_hasta date; v_pres date; v_dom date; v_prov text; v_ant_y int; v_ant_p text; v_hoy date := (now() at time zone 'Europe/Madrid')::date;
begin
  if not exists (select 1 from public.company where id = p_company) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = '303' and valid_to is null and active;
  select desde, hasta into v_desde, v_hasta from public.conta_impuesto_periodo_fechas(p_year, p_period);
  if o.id is not null then
    select x.presentacion, x.domiciliacion, x.provisional into v_pres, v_dom, v_prov from public.conta_impuesto_plazo_si_hay('303', o.cadence, p_year, p_period) x;
  end if;
  select * into r from public.tax_return where company_id = p_company and form_code = '303' and fiscal_year = p_year and period = p_period and sequence = 1;

  -- El periodo anterior: el trimestre (o el mes) de antes.
  if p_period ~ '^[1-4]T$' then
    v_ant_y := case when p_period = '1T' then p_year - 1 else p_year end;
    v_ant_p := case when p_period = '1T' then '4T' else (left(p_period, 1)::int - 1)::text || 'T' end;
  else
    v_ant_y := case when p_period = '01' then p_year - 1 else p_year end;
    v_ant_p := case when p_period = '01' then '12' else lpad((p_period::int - 1)::text, 2, '0') end;
  end if;
  select * into a from public.tax_return where company_id = p_company and form_code = '303' and fiscal_year = v_ant_y and period = v_ant_p and sequence = 1;

  select * into pr from public.company_tax_presenter where company_id = p_company;
  if pr.certificate_id is not null then select * into ce from public.tax_certificate where id = pr.certificate_id; end if;

  return jsonb_build_object(
    'hoy', v_hoy, 'ejercicio', p_year, 'periodo', p_period, 'desde', v_desde, 'hasta', v_hasta,
    'presenta_303', o.id is not null, 'cadencia', o.cadence,
    'presentacion', v_pres, 'domiciliacion', v_dom, 'provisional', v_prov,
    'puede_gestionar', public.conta_impuesto_puede_gestionar(p_company),
    'declaracion', case when r.id is null then null else jsonb_build_object(
      'id', r.id, 'estado', r.status, 'estado_texto', public.conta_impuesto_estado_texto(r.status),
      'resultado', r.result_kind, 'importe', r.amount,
      'pago', r.payment_mode,
      'pago_cuenta', r.payment_treasury_account_id,
      'pago_cuenta_final', (select right(t.iban, 4) from public.treasury_account t where t.id = r.payment_treasury_account_id and t.company_id = p_company),
      'calculada', r.calculated_at, 'revisada', r.reviewed_at, 'revisada_por', r.reviewed_by_name,
      'presentada', r.filed_at, 'presentada_por', r.filed_by_name, 'por', r.filed_via, 'quien_presenta', r.presenter_kind,
      'csv', r.aeat_csv, 'justificante', r.aeat_receipt_number, 'justificante_pdf', r.receipt_document_path,
      'liquidacion', r.liquidation_entry_id, 'pago_asiento', r.payment_entry_id, 'casado', r.bank_match_id) end,
    'casillas', case when r.id is null then '[]'::jsonb else (
      select coalesce(jsonb_agg(jsonb_build_object('casilla', b.box, 'valor', b.value, 'texto', b.value_text, 'origen', b.origin, 'motivo', b.manual_reason)
                                order by lpad(regexp_replace(b.box, '[^0-9]', '', 'g'), 3, '0'), b.box), '[]')
        from public.tax_return_box b where b.tax_return_id = r.id) end,
    'comprobaciones', case when r.id is null then '[]'::jsonb else (
      select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'clave', k.check_key, 'resultado', k.result, 'titulo', k.title, 'detalle', k.detail,
                                                   'aceptada_por', k.accepted_by_name, 'aceptada_el', k.accepted_at, 'motivo', k.accepted_reason)
                                order by case k.result when 'error' then 0 when 'warning' then 1 else 2 end, k.check_key), '[]')
        from public.tax_return_check k where k.tax_return_id = r.id) end,
    'libros', case when r.id is null then '{}'::jsonb else (
      select coalesce(jsonb_object_agg(libro, n), '{}') from (
        select l.frozen->>'libro' as libro, count(*) as n from public.tax_return_line l where l.tax_return_id = r.id group by 1) x) end,
    'anterior', case when a.id is null then null else jsonb_build_object(
      'ejercicio', a.fiscal_year, 'periodo', a.period, 'estado', a.status, 'resultado', a.result_kind, 'importe', a.amount,
      'c27', (select value from public.tax_return_box where tax_return_id = a.id and box = '27'),
      'c45', (select value from public.tax_return_box where tax_return_id = a.id and box = '45')) end,
    'presentador', jsonb_build_object(
      'modo', coalesce(pr.mode, 'company'),
      'consentida', pr.consented_at is not null and pr.revoked_at is null,
      'certificado', case when ce.id is null then null else jsonb_build_object(
        'id', ce.id, 'nombre', ce.subject_name, 'caduca', ce.valid_to, 'estado', ce.status,
        'probado', ce.last_test_at, 'prueba', ce.last_test_result) end,
      'puedo_presentar', ce.id is not null and ce.status = 'active' and ce.valid_to > now() and public.conta_cert_puede_usar(auth.uid(), ce.id)),
    'bancos', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'nombre', t.name, 'final', right(t.iban, 4)) order by t.name), '[]')
                 from public.treasury_account t where t.company_id = p_company and t.kind = 'bank' and t.iban is not null),
    'registro', case when r.id is null then '[]'::jsonb else (
      select coalesce(jsonb_agg(jsonb_build_object('cuando', e.at, 'quien', e.by_name, 'que', e.kind, 'a', e.to_status, 'mensaje', e.message,
                                                   'servicio', e.aeat_service, 'resultado', e.result) order by e.at desc), '[]')
        from (select * from public.tax_return_event where tax_return_id = r.id order by at desc limit 30) e) end);
end $_$;


--
-- Name: FUNCTION conta_impuesto_declaracion_ver(p_company uuid, p_year integer, p_period text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_declaracion_ver(p_company uuid, p_year integer, p_period text) IS 'I01b. Lo que pinta el IVA de un periodo (tablero 9): plazos, declaración, casillas, comprobaciones, el periodo anterior, quién presenta y el registro. No escribe nada.';


--
-- Name: conta_impuesto_desde_tax_forms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_desde_tax_forms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_quien uuid := auth.uid(); v_nombre text; v_primera boolean; c text;
  v_motivo constant text := 'Cambiado en los datos de la empresa, sin motivo: esa pantalla todavía no lo pide.';
begin
  if coalesce(current_setting('conta.i01_espejo', true), '') = 'si' then return new; end if;
  if tg_op = 'UPDATE' and new.tax_forms is not distinct from old.tax_forms then return new; end if;
  -- Un «insert … on conflict do nothing» sobre un perfil que ya existe (lo hace
  -- conta_ia_poner antes de cada escritura) dispara este «before insert» antes
  -- de ver el conflicto, con la lista vacía: no es una escritura de la lista.
  if tg_op = 'INSERT' and exists (select 1 from public.company_tax_profile where company_id = new.company_id) then return new; end if;
  v_nombre := public.conta_impuesto_quien();
  v_primera := not exists (select 1 from public.tax_obligation where company_id = new.company_id);
  perform set_config('conta.i01_desde_columna', 'si', true);
  -- Lo que sale (solo al cambiar la lista: crear el perfil no quita nada).
  for c in select o.form_code from public.tax_obligation o
            where tg_op = 'UPDATE' and o.company_id = new.company_id and o.valid_to is null and o.active
              and not (o.form_code = any (coalesce(new.tax_forms, '{}'))) loop
    update public.tax_obligation set valid_to = current_date where company_id = new.company_id and form_code = c and valid_to is null;
    insert into public.tax_obligation (account_id, company_id, form_code, cadence, active, origin, why, reason, decided_by, decided_by_name)
    values (new.account_id, new.company_id, c, public.conta_impuesto_cadencia_de(new.company_id, c), false, 'removed',
            'Quitado de la lista de modelos.', v_motivo, v_quien, v_nombre);
  end loop;
  -- Lo que entra (solo modelos que existen en tax_form; los demás no son una obligación).
  for c in select distinct x from unnest(coalesce(new.tax_forms, '{}')) x
            where exists (select 1 from public.tax_form t where t.code = x)
              and not exists (select 1 from public.tax_obligation o where o.company_id = new.company_id and o.form_code = x and o.valid_to is null and o.active) loop
    update public.tax_obligation set valid_to = current_date where company_id = new.company_id and form_code = c and valid_to is null;
    if v_primera then
      insert into public.tax_obligation (account_id, company_id, form_code, cadence, active, origin, rule_key, why, decided_by, decided_by_name)
      values (new.account_id, new.company_id, c, public.conta_impuesto_cadencia_de(new.company_id, c), true, 'rule', 'alta_c00',
              'Lo propuso el alta con tus respuestas.', v_quien, v_nombre);
    else
      insert into public.tax_obligation (account_id, company_id, form_code, cadence, active, origin, why, reason, decided_by, decided_by_name)
      values (new.account_id, new.company_id, c, public.conta_impuesto_cadencia_de(new.company_id, c), true, 'added',
              'Añadido a la lista de modelos.', v_motivo, v_quien, v_nombre);
    end if;
  end loop;
  perform set_config('conta.i01_desde_columna', '', true);
  -- La columna queda como se escribió si dice lo mismo que las obligaciones (el
  -- mismo orden de quien la escribe); si no, como dicen las obligaciones.
  if array(select distinct x from unnest(coalesce(new.tax_forms, '{}')) x where exists (select 1 from public.tax_form t where t.code = x) order by 1)
     is distinct from coalesce((select f.tax_forms from public.company_tax_forms f where f.company_id = new.company_id), '{}') then
    select coalesce(f.tax_forms, '{}') into new.tax_forms from public.company_tax_forms f where f.company_id = new.company_id;
  end if;
  return new;
end $$;


--
-- Name: conta_impuesto_espejo_tax_forms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_espejo_tax_forms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_company uuid := coalesce(new.company_id, old.company_id);
begin
  -- Dentro del disparador de la columna (o de la migración): la columna la pone él.
  if coalesce(current_setting('conta.i01_desde_columna', true), '') = 'si' then return null; end if;
  perform set_config('conta.i01_espejo', 'si', true);
  update public.company_tax_profile p set tax_forms = f.tax_forms
    from public.company_tax_forms f
   where p.company_id = v_company and f.company_id = v_company and p.tax_forms is distinct from f.tax_forms;
  perform set_config('conta.i01_espejo', '', true);
  return null;
end $$;


--
-- Name: conta_impuesto_estado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_estado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nombre text;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then return new; end if;
  v_nombre := public.conta_impuesto_quien();
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, from_status, to_status, message)
  values (new.id, new.account_id, new.company_id, auth.uid(), v_nombre, 'status',
          case when tg_op = 'UPDATE' then old.status end, new.status,
          case when new.status = 'not_required' then 'No hay que presentarlo: ' || new.not_required_reason
               else public.conta_impuesto_estado_texto(new.status) end);
  return new;
end $$;


--
-- Name: conta_impuesto_estado_antes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_estado_antes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status and not public.conta_impuesto_estado_vale(old.status, new.status) then
    raise exception 'Una declaración no pasa de «%» a «%».', public.conta_impuesto_estado_texto(old.status), public.conta_impuesto_estado_texto(new.status)
      using errcode = '22023';
  end if;
  return new;
end $$;


--
-- Name: conta_impuesto_estado_texto(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_estado_texto(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case p_status
    when 'pending' then 'Por calcular' when 'draft' then 'Borrador' when 'reviewed' then 'Revisado'
    when 'filed' then 'Presentado' when 'booked' then 'Contabilizado' when 'paid' then 'Pagado'
    when 'offset' then 'Compensado' when 'refunded' then 'Devuelto' when 'not_required' then 'No hay que presentarlo'
    else p_status end
$$;


--
-- Name: conta_impuesto_estado_vale(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_estado_vale(p_de text, p_a text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select (p_de, p_a) in (
    ('pending', 'draft'), ('pending', 'not_required'),
    ('draft', 'reviewed'), ('draft', 'pending'), ('draft', 'not_required'), ('draft', 'filed'),
    ('reviewed', 'draft'), ('reviewed', 'filed'), ('reviewed', 'not_required'),
    ('filed', 'booked'), ('filed', 'paid'), ('filed', 'offset'), ('filed', 'refunded'),
    ('booked', 'paid'), ('booked', 'offset'), ('booked', 'refunded'),
    ('not_required', 'pending'),
    -- I01b (0180): deshacer el pago en Bancos, o anular el asiento de liquidación.
    ('paid', 'booked'), ('paid', 'filed'), ('refunded', 'booked'), ('refunded', 'filed'),
    ('booked', 'filed'), ('offset', 'filed'))
$$;


--
-- Name: conta_impuesto_euros(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_euros(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select translate(to_char(p, 'FM999G999G990D00'), ',.', '.,') || ' €'
$$;


--
-- Name: conta_impuesto_fin_periodo(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_fin_periodo(p_cadencia text, p_periodo text) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select case
    when p_cadencia = 'quarterly' and p_periodo ~ '^[1-4]T$' then (substr(p_periodo, 1, 1)::int * 3)::smallint
    when p_cadencia = 'monthly' and p_periodo ~ '^(0[1-9]|1[0-2])$' then p_periodo::smallint
    when p_cadencia = 'annual' and p_periodo = '0A' then 12::smallint
    when p_cadencia = 'instalments_202' and p_periodo = '1P' then 3::smallint
    when p_cadencia = 'instalments_202' and p_periodo = '2P' then 9::smallint
    when p_cadencia = 'instalments_202' and p_periodo = '3P' then 11::smallint
  end
$_$;


--
-- Name: conta_impuesto_fuera(uuid, uuid, text, boolean, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_fuera(p_return uuid, p_user uuid, p_csv text, p_comprobada boolean, p_justificante text, p_fecha timestamp with time zone, p_use uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare r public.tax_return; v_csv text := upper(regexp_replace(coalesce(p_csv, ''), '\s', '', 'g')); v_nombre text := public.conta_impuesto_nombre_de(p_user);
        v_71_mano boolean; v_que text;
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_gestiona(p_user, r.company_id) then
    raise exception 'No puedes apuntar los impuestos de esta empresa.' using errcode = '42501';
  end if;
  if v_csv !~ '^[A-Z0-9]{16}$' then
    raise exception 'Ese CSV no tiene la forma de los de Hacienda: son 16 letras y números, como aparecen en el justificante.' using errcode = '22023';
  end if;
  if r.status not in ('draft', 'reviewed') then
    raise exception 'Esta declaración está «%»: solo se apunta como presentada fuera un borrador o una revisada.', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if p_comprobada and not exists (select 1 from public.tax_certificate_use u where u.id = p_use and u.user_id = p_user and u.action = 'query' and u.tax_return_id = r.id) then
    raise exception 'Para darla por comprobada con Hacienda hace falta el uso del certificado con el que se consultó.' using errcode = '42501';
  end if;
  -- Con algo que Sumied no supo calcular, lo presentado lo dicen las casillas
  -- del justificante, escritas a mano: al menos la [71]. Y lo de antes ([110]),
  -- que sin ella el siguiente trimestre no sabe qué arrastra.
  v_71_mano := exists (select 1 from public.tax_return_box where tax_return_id = r.id and box = '71' and origin = 'manual' and value is not null);
  select string_agg(check_key, ', ') into v_que from public.tax_return_check
   where tax_return_id = r.id and result = 'error' and check_key <> 'file_layout' and not (v_71_mano and check_key = 'book_vs_303');
  if v_que is not null then
    raise exception 'Sumied no ha podido calcular este 303 (%): antes de apuntarlo como presentado, escribe las casillas del justificante ([27], [45], [110], [78], [87] y [71]).', v_que using errcode = '22023';
  end if;
  -- Sin calcular, Sumied no sabe qué se presentó (la consulta de Hacienda no da el importe): no se inventa un resultado.
  if r.result_kind is null then
    raise exception 'Antes de apuntarla como presentada, calcúlala en Sumied o escribe las casillas del justificante: así queda qué se presentó.' using errcode = '22023';
  end if;
  update public.tax_return
     set status = 'filed', filed_at = coalesce(p_fecha, now()), filed_by = p_user, filed_by_name = v_nombre, filed_via = 'outside',
         aeat_csv = v_csv, aeat_receipt_number = p_justificante, outside_csv_pasted_at = now(), updated_at = now()
   where id = r.id;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, aeat_service, result, message, detail)
  values (r.id, r.account_id, r.company_id, p_user, v_nombre,
          case when p_comprobada then 'aeat_call' else 'note' end, case when p_comprobada then 'outside_check' end, case when p_comprobada then 'ok' end,
          case when p_comprobada then 'Presentado fuera de Sumied: Hacienda lo confirma (justificante ' || coalesce(p_justificante, '—') || ').'
               else 'Presentado fuera de Sumied, según ' || v_nombre || '. No se ha comprobado con Hacienda.' end,
          jsonb_build_object('csv_cola', right(v_csv, 4), 'comprobada', p_comprobada, 'casillas_a_mano', v_71_mano));
  return jsonb_build_object('ok', true, 'comprobada', p_comprobada,
    'mensaje', case when p_comprobada then 'Apuntado como presentado fuera: Hacienda lo confirma, justificante ' || coalesce(p_justificante, '—') || '.'
                    else 'Apuntado como presentado fuera, con el CSV que has pegado. No se ha podido comprobar con Hacienda.' end);
end $_$;


--
-- Name: conta_impuesto_gestiona(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_gestiona(p_user uuid, p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p_user is not null and (
    exists (select 1 from public.company c join public.user_profiles me on me.account_id = c.account_id
             where c.id = p_company and me.user_id = p_user and me.active and me.role in ('admin', 'manager'))
    or exists (select 1 from public.company_tax_presenter t join public.user_profiles me on me.account_id = t.advisor_account_id
                where t.company_id = p_company and t.mode = 'advisor' and t.consented_at is not null and t.revoked_at is null
                  and me.user_id = p_user and me.active and me.role in ('admin', 'manager')))
$$;


--
-- Name: conta_impuesto_habil(date, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_habil(p_dia date, p_scopes text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare v_falta text;
begin
  select string_agg(s, ', ') into v_falta from unnest(p_scopes) s
   where not exists (select 1 from public.tax_holiday_year y where y.year = extract(year from p_dia)::int and y.scope = s);
  if v_falta is not null then
    raise exception 'No están cargados los festivos de % (%): sin ellos no se puede calcular el plazo.', extract(year from p_dia)::int, v_falta
      using errcode = 'P0002';
  end if;
  return extract(isodow from p_dia) < 6
     and not exists (select 1 from public.tax_holiday h where h.day = p_dia and h.scope = any (p_scopes));
end $$;


--
-- Name: conta_impuesto_hacienda_apunte(uuid, uuid, text, text, text[], text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_hacienda_apunte(p_return uuid, p_user uuid, p_service text, p_result text, p_codes text[], p_message text, p_detail jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return;
begin
  select * into r from public.tax_return where id = p_return;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if p_message is null or btrim(p_message) = '' then raise exception 'Falta cómo acabó, en palabras.' using errcode = '22023'; end if;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, aeat_service, result, aeat_codes, message, detail)
  values (r.id, r.account_id, r.company_id, p_user, public.conta_impuesto_nombre_de(p_user), 'aeat_call', p_service, p_result, p_codes,
          btrim(p_message), coalesce(p_detail, '{}'));
end $$;


--
-- Name: conta_impuesto_informativa_fuera(uuid, text, integer, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_informativa_fuera(p_company uuid, p_form text, p_year integer, p_csv text, p_fecha date, p_justificante text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; o public.tax_obligation; r public.tax_return; v_plazo record; v_quien text := public.conta_impuesto_quien();
  v_csv text := upper(regexp_replace(coalesce(p_csv, ''), '\s', '', 'g'));
begin
  if p_form not in ('190', '180', '347', '349', '390') then
    raise exception 'Aquí se apuntan los modelos anuales (390, 190, 180, 347 y 349), no el %.', p_form using errcode = '22023';
  end if;
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, apunta lo presentado.' using errcode = '42501';
  end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = p_form and valid_to is null and active;
  if o.id is null or o.cadence <> 'annual' then raise exception 'Esta empresa no presenta el % (no está en sus modelos anuales).', p_form using errcode = 'P0002'; end if;
  if v_csv !~ '^[A-Z0-9]{16}$' then raise exception 'El CSV no tiene la forma de los de Hacienda (16 letras y números).' using errcode = '22023'; end if;
  if p_fecha is null then raise exception 'Falta la fecha de presentación.' using errcode = '22023'; end if;
  if p_fecha > (now() at time zone 'Europe/Madrid')::date then raise exception 'La fecha de presentación es futura: no puede estar presentado.' using errcode = '22023'; end if;
  if p_fecha <= make_date(p_year, 12, 31) then raise exception 'El % de % se presenta después de acabar el año: el % no casa.', p_form, p_year, to_char(p_fecha, 'DD/MM/YYYY') using errcode = '22023'; end if;

  select * into r from public.tax_return where company_id = p_company and form_code = p_form and fiscal_year = p_year and period = '0A' and sequence = 1 for update;
  if r.id is not null and r.status not in ('pending', 'draft', 'reviewed') then
    return jsonb_build_object('ok', true, 'declaracion', r.id, 'mensaje', 'El ' || p_form || ' de ' || p_year || ' ya estaba apuntado como presentado (' || public.conta_impuesto_estado_texto(r.status) || ').');
  end if;
  if r.id is null then
    select * into v_plazo from public.conta_impuesto_plazo_si_hay(p_form, 'annual', p_year, '0A');
    insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, due_date, due_provisional, alert_on, status)
    values (c.account_id, p_company, o.id, p_form, p_year, 'annual', '0A', v_plazo.presentacion, v_plazo.provisional, v_plazo.presentacion, 'draft')
    returning * into r;
  end if;
  update public.tax_return
     set status = 'filed', result_kind = coalesce(result_kind, 'zero'), amount = coalesce(amount, 0),
         filed_at = (p_fecha::timestamp at time zone 'Europe/Madrid') + interval '12 hours', filed_by = auth.uid(), filed_by_name = v_quien, filed_via = 'outside',
         aeat_csv = v_csv, aeat_receipt_number = nullif(btrim(coalesce(p_justificante, '')), ''), outside_csv_pasted_at = now(), receipt_source = 'upload',
         updated_at = now()
   where id = r.id returning * into r;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, c.account_id, p_company, auth.uid(), v_quien, 'note',
          v_quien || ' apuntó el ' || p_form || ' de ' || p_year || ' como presentado fuera el ' || to_char(p_fecha, 'DD/MM/YYYY') || ' (CSV …' || right(v_csv, 4) || ').',
          jsonb_build_object('fecha', p_fecha, 'justificante', r.aeat_receipt_number));
  return jsonb_build_object('ok', true, 'declaracion', r.id,
    'mensaje', 'Apuntado: el ' || p_form || ' de ' || p_year || ' presentado fuera el ' || to_char(p_fecha, 'DD/MM/YYYY') ||
               ', CSV terminado en ' || right(v_csv, 4) || '. Ya no se recalcula. El PDF del justificante de los anuales aún no se lee en Sumied: queda apuntado con su CSV.');
end $_$;


--
-- Name: FUNCTION conta_impuesto_informativa_fuera(p_company uuid, p_form text, p_year integer, p_csv text, p_fecha date, p_justificante text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_informativa_fuera(p_company uuid, p_form text, p_year integer, p_csv text, p_fecha date, p_justificante text) IS 'S02. «Ya lo presenté fuera» de un modelo anual informativo (390, 190, 180, 347, 349): con su CSV y su fecha queda presentado fuera, con candado (ya no se recalcula). Dice qué ha apuntado.';


--
-- Name: conta_impuesto_justificante_apuntar(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_justificante_apuntar(p_company uuid, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  m jsonb; c public.company; r public.tax_return; v_id uuid; v_nombre text := public.conta_impuesto_quien();
  v_mod text := p_datos->>'modelo'; v_per text := upper(p_datos->>'periodo'); v_ej int := (p_datos->>'ejercicio')::int;
  v_cad text; v_pl record; v_due date; v_dd date; v_prov text; v_regla record; v_mes date;
  v_mano boolean := coalesce((p_datos->>'a_mano')::boolean, false); v_motivo text := btrim(coalesce(p_datos->>'motivo', ''));
  v_caja_res text := case p_datos->>'modelo' when '303' then '71' when '111' then '30' when '115' then '05' end;
  v_casillas jsonb := p_datos->'casillas'; v_antes text;
  -- 0270: de dónde sale el PDF y lo que dice su primera página.
  v_traido boolean := p_datos->>'origen_pdf' = 'aeat_csv';
  v_exp text := nullif(btrim(coalesce(p_datos->>'expediente', '')), '');
  v_pnif text := nullif(upper(regexp_replace(coalesce(p_datos->'presentador'->>'nif', ''), '[^A-Za-z0-9]', '', 'g')), '');
  v_pnom text := nullif(btrim(coalesce(p_datos->'presentador'->>'nombre', '')), '');
begin
  if not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, sube justificantes.' using errcode = '42501';
  end if;
  m := public.conta_impuesto_justificante_mirar(p_company, p_datos);
  if m->>'estado' = 'error' then raise exception '%', m->>'motivo' using errcode = '22023'; end if;
  if m->>'estado' = 'ya_estaba' then
    return m || jsonb_build_object('ok', true, 'mensaje', m->>'motivo');
  end if;
  select * into c from public.company where id = p_company;
  v_cad := m->>'cadencia';
  -- La [71] (o la del resultado) escrita a mano si el PDF no la traía.
  if v_caja_res is not null and not (v_casillas ? v_caja_res) then
    v_casillas := v_casillas || jsonb_build_object(v_caja_res, (p_datos->>'resultado')::numeric);
  end if;

  if m->>'estado' = 'nuevo' then
    select * into v_pl from public.conta_impuesto_plazo_si_hay(v_mod, v_cad, v_ej, v_per);
    v_due := v_pl.presentacion; v_dd := v_pl.domiciliacion; v_prov := v_pl.provisional;
    if v_due is null then
      -- Sin los festivos de ese año: el día de la regla, sin trasladar, y dicho.
      select * into v_regla from public.tax_form_deadline d
       where d.form_code = v_mod and d.cadence = v_cad and d.period in (v_per, '*') order by (d.period = v_per) desc limit 1;
      if v_regla.form_code is null then
        raise exception 'No tengo la regla del plazo del % (%): no se inventa.', v_mod, v_per using errcode = 'P0002';
      end if;
      v_mes := (make_date(v_ej, public.conta_impuesto_fin_periodo(v_cad, v_per), 1) + make_interval(months => v_regla.months_after))::date;
      v_due := case when v_regla.day is null then (v_mes + interval '1 month - 1 day')::date
                    else make_date(extract(year from v_mes)::int, extract(month from v_mes)::int, v_regla.day) end;
      v_prov := 'Sin los festivos de ' || extract(year from v_due)::int || ': el día de la regla, sin trasladar si caía en festivo.';
    end if;
    -- Nace presentada (de «pendiente» no se pasa a «presentada»: el registro lo dice como alta).
    insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, due_date, due_date_direct_debit, due_provisional,
                                   status, result_kind, amount, filed_at, filed_by, filed_by_name, filed_via, aeat_csv, aeat_receipt_number, outside_csv_pasted_at,
                                   aeat_expediente, presenter_tax_id, presenter_name, receipt_source)
    values (c.account_id, p_company,
            (select o.id from public.tax_obligation o where o.company_id = p_company and o.form_code = v_mod and o.valid_to is null),
            v_mod, v_ej, v_cad, v_per, v_due, v_dd, v_prov,
            'filed', m->>'resultado', (m->>'importe')::numeric, (m->>'presentada')::timestamptz, auth.uid(), v_nombre, 'outside',
            upper(regexp_replace(p_datos->>'csv', '\s', '', 'g')), nullif(btrim(coalesce(p_datos->>'justificante', '')), ''), now(),
            v_exp, v_pnif, v_pnom, case when v_traido then 'aeat_csv' else 'upload' end)
    returning * into r;
    v_antes := null;
  else
    select * into r from public.tax_return where id = (m->>'declaracion')::uuid for update;
    v_antes := r.status;
    -- Una pendiente pasa por borrador: los cambios de estado que valen (conta_impuesto_estado_vale).
    if r.status = 'pending' then update public.tax_return set status = 'draft' where id = r.id; end if;
  end if;

  -- Las casillas: las del justificante, y ninguna más (lo calculado que no está en él, fuera; queda en el evento).
  delete from public.tax_return_box where tax_return_id = r.id;
  insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, origin, manual_reason, source)
  select r.id, r.account_id, p_company, k, round(v::numeric, 2),
         case when v_mano or (k = v_caja_res and not (p_datos->'casillas' ? k)) then 'manual' else 'justificante' end,
         case when v_mano then 'Escrita a mano del justificante: ' || v_motivo
              when k = v_caja_res and not (p_datos->'casillas' ? k) then 'El resultado, escrito a mano: el PDF no lo traía. ' || nullif(v_motivo, '') end,
         jsonb_build_object('justificante', p_datos->>'justificante')
    from jsonb_each_text(v_casillas) e(k, v);

  update public.tax_return
     set status = 'filed', result_kind = m->>'resultado', amount = (m->>'importe')::numeric,
         filed_at = (m->>'presentada')::timestamptz, filed_by = auth.uid(), filed_by_name = v_nombre, filed_via = 'outside',
         aeat_csv = upper(regexp_replace(p_datos->>'csv', '\s', '', 'g')), aeat_receipt_number = nullif(btrim(coalesce(p_datos->>'justificante', '')), ''),
         outside_csv_pasted_at = now(), updated_at = now(),
         aeat_expediente = v_exp, presenter_tax_id = v_pnif, presenter_name = v_pnom,
         receipt_source = case when v_traido then 'aeat_csv' else 'upload' end
   where id = r.id and v_antes is not null;
  -- El cambio de estado lo apunta su disparador; aquí, de dónde sale y las diferencias.
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, r.account_id, p_company, auth.uid(), v_nombre, 'note',
          'Presentado fuera de Sumied: ' || case when v_mano then 'casillas escritas a mano del justificante'
                                                 when v_traido then 'justificante traído de Hacienda por su CSV' else 'subido el justificante' end
            || coalesce(' nº ' || nullif(btrim(coalesce(p_datos->>'justificante', '')), ''), '') || '.',
          jsonb_build_object('origen', case when v_mano then 'justificante_a_mano' when v_traido then 'justificante_aeat_csv' else 'justificante' end, 'antes', v_antes,
                             'csv_cola', right(upper(p_datos->>'csv'), 4), 'diferencias', coalesce(m->'diferencias', '[]'),
                             'casillas', (select count(*) from jsonb_object_keys(v_casillas))));
  return m || jsonb_build_object('ok', true, 'declaracion', r.id, 'cuenta', r.account_id,
    'mensaje', 'Apuntado el ' || v_mod || ' del ' || v_per || '/' || v_ej || ' como presentado fuera, ' ||
               case when v_casillas = '{}'::jsonb then 'con su importe y sin casillas (el impreso era imagen)'
                    else 'con ' || (select count(*) from jsonb_object_keys(v_casillas)) || ' casillas' end ||
               case when jsonb_array_length(coalesce(m->'diferencias', '[]')) > 0
                    then ' (' || jsonb_array_length(m->'diferencias') || ' distintas de lo calculado)' else '' end || '.');
end $$;


--
-- Name: FUNCTION conta_impuesto_justificante_apuntar(p_company uuid, p_datos jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_justificante_apuntar(p_company uuid, p_datos jsonb) IS 'I01c (0270). Apunta un justificante de Hacienda como declaración presentada fuera: la crea o completa la que había (nunca duplica), con sus casillas de origen justificante, su expediente, su presentador y de dónde salió el PDF (traído de Hacienda por CSV o subido).';


--
-- Name: conta_impuesto_justificante_guardar(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_justificante_guardar(p_return uuid, p_ruta text, p_huella text, p_tamano bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare r public.tax_return; v_tam bigint; v_tipo text;
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(r.company_id) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, guarda el justificante.' using errcode = '42501';
  end if;
  if r.status not in ('filed', 'booked', 'paid', 'offset', 'refunded') then
    raise exception 'El justificante va con una declaración presentada, y esta está «%».', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if p_ruta is null or p_ruta <> r.account_id::text || '/impuestos/' || r.id::text || '/' || p_huella || '.pdf' or p_huella !~ '^[0-9a-f]{64}$' then
    raise exception 'El justificante tiene que estar en la carpeta de esta declaración, con su huella de nombre.' using errcode = '22023';
  end if;
  if r.receipt_document_path is not null then
    if r.receipt_document_path = p_ruta then return jsonb_build_object('ok', true, 'ruta', p_ruta, 'mensaje', 'El justificante ya estaba guardado.'); end if;
    raise exception 'Esta declaración ya tiene su justificante: no se cambia.' using errcode = '22023';
  end if;
  select (o.metadata->>'size')::bigint, o.metadata->>'mimetype' into v_tam, v_tipo
    from storage.objects o where o.bucket_id = 'conta-documentos' and o.name = p_ruta;
  if v_tam is null then raise exception 'El justificante no ha llegado: vuelve a subirlo.' using errcode = 'P0002'; end if;
  if v_tam <> p_tamano or coalesce(v_tipo, 'application/pdf') <> 'application/pdf' then
    raise exception 'El fichero subido no es el justificante que se esperaba (tamaño o tipo distintos).' using errcode = '22023';
  end if;
  update public.tax_return set receipt_document_path = p_ruta, updated_at = now() where id = r.id;
  return jsonb_build_object('ok', true, 'ruta', p_ruta, 'mensaje', 'Guardado el justificante del ' || r.form_code || ' del ' || r.period || '/' || r.fiscal_year || '.');
end $_$;


--
-- Name: conta_impuesto_justificante_mirar(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_justificante_mirar(p_company uuid, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; r public.tax_return;
  v_mod text := p_datos->>'modelo'; v_per text := upper(coalesce(p_datos->>'periodo', ''));
  v_ej int; v_cad text; v_fin smallint; v_fecha timestamptz; v_csv text := upper(regexp_replace(coalesce(p_datos->>'csv', ''), '\s', '', 'g'));
  v_nif text := upper(regexp_replace(coalesce(p_datos->>'nif', ''), '[^A-Za-z0-9]', '', 'g'));
  v_nif_emp text; v_res numeric; v_kind text; v_dif jsonb := '[]'; v_k text; v_v jsonb;
  v_base jsonb := jsonb_build_object('modelo', p_datos->>'modelo', 'ejercicio', p_datos->'ejercicio', 'periodo', p_datos->>'periodo');
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  -- El NIF, lo primero: si no es de esta empresa, no se mira nada más.
  v_nif_emp := upper(regexp_replace(coalesce(c.tax_id, ''), '[^A-Za-z0-9]', '', 'g'));
  v_nif_emp := case when v_nif_emp ~ '^ES[A-Z0-9]{9}$' then substr(v_nif_emp, 3) else v_nif_emp end;
  v_nif := case when v_nif ~ '^ES[A-Z0-9]{9}$' then substr(v_nif, 3) else v_nif end;
  if v_nif_emp = '' then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'La empresa no tiene su NIF en Ajustes: sin él no se puede comprobar de quién es el justificante.');
  end if;
  -- Escrito a mano sin NIF (el PDF no se pudo leer): lo afirma quien lo escribe, con su motivo.
  if v_nif <> v_nif_emp and not (coalesce((p_datos->>'a_mano')::boolean, false) and v_nif = '') then
    return v_base || jsonb_build_object('estado', 'error', 'motivo',
      'Es de otro NIF (' || coalesce(nullif(v_nif, ''), 'sin NIF') || '), no del de ' || coalesce(c.legal_name, 'esta empresa') || ' (' || v_nif_emp || '): no se guarda.');
  end if;
  if v_mod is null or v_mod not in ('303', '111', '115', '202') then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'Sumied lee el 303, el 111, el 115 y el 202, y este es el ' || coalesce(v_mod, '(sin modelo)') || '.');
  end if;
  begin v_ej := (p_datos->>'ejercicio')::int; exception when others then v_ej := null; end;
  if v_ej is null or v_ej < 2000 or v_ej > extract(year from now())::int then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'El ejercicio «' || coalesce(p_datos->>'ejercicio', '') || '» no es un año que pueda estar presentado.');
  end if;
  v_cad := case when v_per ~ '^[1-4]T$' and v_mod <> '202' then 'quarterly'
                when v_per ~ '^(0[1-9]|1[0-2])$' and v_mod <> '202' then 'monthly'
                when v_per ~ '^[1-3]P$' and v_mod = '202' then 'instalments_202' end;
  if v_cad is null then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'El periodo «' || v_per || '» no es de un ' || v_mod || '.');
  end if;
  v_fin := public.conta_impuesto_fin_periodo(v_cad, v_per);
  begin v_fecha := ((p_datos->>'presentada')::timestamp) at time zone 'Europe/Madrid'; exception when others then v_fecha := null; end;
  if v_fecha is null then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'Falta la fecha de presentación.');
  end if;
  if v_fecha > now() + interval '1 day' then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'La fecha de presentación es futura: no puede estar presentado.');
  end if;
  if (v_fecha at time zone 'Europe/Madrid')::date < (make_date(v_ej, v_fin, 1) + interval '1 month')::date then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'Está presentado antes de acabar el periodo: no casa.');
  end if;
  if v_csv !~ '^[A-Z0-9]{16}$' then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'El CSV no tiene la forma de los de Hacienda (16 letras y números).');
  end if;
  begin v_res := (p_datos->>'resultado')::numeric; exception when others then v_res := null; end;
  if v_res is null then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'Falta el resultado: escríbelo.');
  end if;
  v_kind := case when v_res > 0 then 'to_pay' when v_res = 0 then 'zero'
                 when v_mod = '303' and coalesce((p_datos->>'devolucion')::boolean, false) then 'to_refund'
                 when v_mod = '303' then 'to_offset' end;
  if v_kind is null then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'Un ' || v_mod || ' no sale negativo: el resultado leído no casa.');
  end if;
  if v_kind = 'to_refund' and v_per not in ('4T', '12') then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'La devolución se pide en el último periodo del año; antes, sale a compensar.');
  end if;
  -- Sin casillas, solo el 202: sus páginas del impreso pueden ser imagen, y su resultado es lo ingresado (la línea del NRC).
  if coalesce(jsonb_typeof(p_datos->'casillas'), '') <> 'object' or (p_datos->'casillas' = '{}'::jsonb and v_mod <> '202') then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'Faltan las casillas.');
  end if;
  for v_k, v_v in select * from jsonb_each(p_datos->'casillas') loop
    if v_k !~ '^[0-9]{2,3}$' or jsonb_typeof(v_v) <> 'number' then
      return v_base || jsonb_build_object('estado', 'error', 'motivo', 'La casilla «' || v_k || '» no se ha leído bien.');
    end if;
  end loop;
  if coalesce((p_datos->>'a_mano')::boolean, false) and btrim(coalesce(p_datos->>'motivo', '')) = '' then
    return v_base || jsonb_build_object('estado', 'error', 'motivo', 'Escritas a mano, las casillas llevan el motivo.');
  end if;

  select * into r from public.tax_return
   where company_id = p_company and form_code = v_mod and fiscal_year = v_ej and period = v_per and sequence = 1;
  -- Ya presentada: con el mismo CSV, ya estaba; con otro, no se pisa.
  if r.id is not null and r.status in ('filed', 'booked', 'paid', 'offset', 'refunded') then
    if r.aeat_csv = v_csv then
      return v_base || jsonb_build_object('estado', 'ya_estaba', 'declaracion', r.id, 'cuenta', r.account_id, 'resultado', r.result_kind, 'importe', r.amount,
        'presentada', r.filed_at, 'falta_pdf', r.receipt_document_path is null,
        'motivo', case when r.receipt_document_path is null then 'Ya estaba apuntado; se guarda el PDF.' else 'Ya estaba apuntado, con su PDF.' end);
    end if;
    return v_base || jsonb_build_object('estado', 'error', 'declaracion', r.id, 'motivo',
      'Ya hay un ' || v_mod || ' del ' || v_per || '/' || v_ej || ' presentado con otro CSV. Si este es una complementaria o una sustitutiva, todavía no se apunta aquí.');
  end if;
  -- Lo que Sumied tenía (calculado o escrito a mano) contra lo que dice el justificante.
  if r.id is not null then
    select coalesce(jsonb_agg(jsonb_build_object('casilla', x.box, 'sumied', x.antes, 'presentado', x.ahora) order by length(x.box), x.box), '[]') into v_dif
      from (select coalesce(b.box, j.k) box, b.value antes, (j.v)::numeric ahora
              from (select box, value from public.tax_return_box where tax_return_id = r.id and value is not null) b
              full join (select k, v from jsonb_each_text(p_datos->'casillas') e(k, v)) j on j.k = b.box) x
     where x.antes is not null and x.antes is distinct from x.ahora and not (x.ahora is null and x.antes = 0);
  end if;
  return v_base || jsonb_build_object(
    'estado', case when r.id is null then 'nuevo' else 'completa' end,
    'declaracion', r.id, 'cuenta', c.account_id, 'cadencia', v_cad,
    'resultado', v_kind, 'importe', abs(v_res), 'presentada', v_fecha,
    'calculada', r.id is not null and exists (select 1 from public.tax_return_box where tax_return_id = r.id),
    'diferencias', v_dif,
    'motivo', case when r.id is null then null
                   when jsonb_array_length(v_dif) = 0 and exists (select 1 from public.tax_return_box where tax_return_id = r.id)
                     then 'Sumied lo había calculado igual, casilla a casilla.'
                   when jsonb_array_length(v_dif) > 0 then 'Sumied lo había calculado y ' || jsonb_array_length(v_dif) ||
                     case when jsonb_array_length(v_dif) = 1 then ' casilla no coincide.' else ' casillas no coinciden.' end
              end);
end $_$;


--
-- Name: FUNCTION conta_impuesto_justificante_mirar(p_company uuid, p_datos jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_justificante_mirar(p_company uuid, p_datos jsonb) IS 'I01c (0260). Interna: comprueba un justificante de Hacienda leído contra la empresa (NIF, modelo, periodo, fecha, CSV, resultado) y lo que ya hay. No escribe nada.';


--
-- Name: conta_impuesto_justificantes_repasar(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_justificantes_repasar(p_company uuid, p_lista jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_out jsonb := '[]'; v_vistos text[] := '{}'; v_clave text; e jsonb; m jsonb; i int := 0;
begin
  if not exists (select 1 from public.company where id = p_company) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, sube justificantes.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_lista) <> 'array' then raise exception 'La lista de justificantes no ha llegado.' using errcode = '22023'; end if;
  for e in select * from jsonb_array_elements(p_lista) loop
    m := public.conta_impuesto_justificante_mirar(p_company, e);
    v_clave := coalesce(e->>'modelo', '') || '·' || coalesce(e->>'ejercicio', '') || '·' || upper(coalesce(e->>'periodo', ''));
    if m->>'estado' <> 'error' and v_clave = any (v_vistos) then
      m := m || jsonb_build_object('estado', 'error', 'motivo', 'Va dos veces en esta subida: se apunta el primero.');
    end if;
    v_vistos := v_vistos || v_clave;
    v_out := v_out || jsonb_build_array(m || jsonb_build_object('i', i));
    i := i + 1;
  end loop;
  return v_out;
end $$;


--
-- Name: FUNCTION conta_impuesto_justificantes_repasar(p_company uuid, p_lista jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_justificantes_repasar(p_company uuid, p_lista jsonb) IS 'I01c (0260). La pantalla de repaso de «Subir justificantes»: cada justificante leído, mirado (nuevo, completa lo calculado con sus diferencias, ya estaba o por qué no). No escribe nada.';


--
-- Name: conta_impuesto_nombre_de(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_nombre_de(p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select nullif(btrim(display_name), '') from public.user_profiles where user_id = p_user and active order by display_name limit 1), 'Sumied')
$$;


--
-- Name: conta_impuesto_nombre_de_en(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_nombre_de_en(p_user uuid, p_account uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select nullif(btrim(display_name), '') from public.user_profiles
                    where user_id = p_user order by (account_id = p_account) desc, active desc, display_name limit 1), 'Sin nombre')
$$;


--
-- Name: conta_impuesto_obligacion_decidir(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_obligacion_decidir(p_company uuid, p_form text, p_presenta boolean, p_motivo text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_id uuid; o public.tax_obligation;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, cambia sus modelos.' using errcode = '42501';
  end if;
  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'Para % el % hace falta el motivo.', case when p_presenta then 'añadir' else 'quitar' end, p_form using errcode = '22023';
  end if;
  if not exists (select 1 from public.tax_form where code = p_form) then raise exception 'No hay un modelo %.', p_form using errcode = 'P0002'; end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = p_form and valid_to is null;
  if o.id is not null and o.active = p_presenta then
    raise exception 'El % ya está %.', p_form, case when p_presenta then 'en la lista' else 'fuera de la lista' end using errcode = '22023';
  end if;
  if o.id is not null then update public.tax_obligation set valid_to = current_date where id = o.id; end if;
  insert into public.tax_obligation (account_id, company_id, form_code, cadence, active, origin, why, reason, payment_mode,
                                     payment_treasury_account_id, decided_by, decided_by_name)
  values (v_acc, p_company, p_form, coalesce(o.cadence, public.conta_impuesto_cadencia_de(p_company, p_form)), p_presenta,
          case when p_presenta then 'added' else 'removed' end,
          case when p_presenta then 'Lo añadiste tú: ' else 'Lo quitaste tú: ' end || btrim(p_motivo), btrim(p_motivo),
          coalesce(o.payment_mode, 'none'), o.payment_treasury_account_id, auth.uid(), public.conta_impuesto_quien())
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: conta_impuesto_obligaciones_calcular(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_obligaciones_calcular(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_nombre text; r record; o public.tax_obligation; v_out jsonb := '[]'; v_hecho text;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, recalcula sus modelos.' using errcode = '42501';
  end if;
  v_nombre := public.conta_impuesto_quien();
  for r in select * from public.conta_impuesto_reglas(p_company) loop
    select * into o from public.tax_obligation where company_id = p_company and form_code = r.form_code and valid_to is null;
    if o.id is not null and o.origin in ('added', 'removed') then
      v_hecho := 'lo_decidio_una_persona';
    elsif o.id is not null and o.active = r.active and o.rule_key is not distinct from r.rule_key
          and o.rule_facts = r.rule_facts and o.why = r.why and o.cadence = r.cadence then
      v_hecho := 'igual';
    elsif o.id is null and not r.active then
      v_hecho := 'no_toca';
    else
      if o.id is not null then update public.tax_obligation set valid_to = current_date where id = o.id; end if;
      insert into public.tax_obligation (account_id, company_id, form_code, cadence, active, origin, rule_key, rule_facts, why,
                                         payment_mode, payment_treasury_account_id, decided_by, decided_by_name)
      values (v_acc, p_company, r.form_code, r.cadence, r.active, 'rule', r.rule_key, r.rule_facts, r.why,
              coalesce(o.payment_mode, 'none'), o.payment_treasury_account_id, auth.uid(), v_nombre);
      v_hecho := case when o.id is null then 'nuevo' else 'cambiado' end;
    end if;
    v_out := v_out || jsonb_build_object('modelo', r.form_code, 'presenta', r.active, 'regla', r.rule_key, 'por_que', r.why, 'datos', r.rule_facts,
                                         'hecho', v_hecho, 'motivo_de_la_persona', case when v_hecho = 'lo_decidio_una_persona' then o.reason end);
  end loop;
  return v_out;
end $$;


--
-- Name: FUNCTION conta_impuesto_obligaciones_calcular(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_obligaciones_calcular(p_company uuid) IS 'I01a. Escribe en tax_obligation lo que dicen las reglas (conta_impuesto_reglas). No pisa lo que decidió una persona. Devuelve, por modelo, qué dice la regla, por qué y qué se ha hecho.';


--
-- Name: conta_impuesto_pago_poner(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_pago_poner(p_return uuid, p_modo text, p_cuenta uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; t public.treasury_account; v_hoy date := (now() at time zone 'Europe/Madrid')::date; v_msg text;
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(r.company_id) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, decide cómo se paga.' using errcode = '42501';
  end if;
  if r.status not in ('draft', 'reviewed') then
    raise exception 'Esta declaración ya está «%»: el pago se decide antes de presentar.', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if p_modo not in ('direct_debit', 'self', 'refund') then raise exception 'Esa forma de pago no existe.' using errcode = '22023'; end if;
  if p_modo in ('direct_debit', 'refund') then
    select * into t from public.treasury_account where id = p_cuenta and company_id = r.company_id and kind = 'bank' and iban is not null;
    if t.id is null then raise exception 'Elige un banco de la empresa, con su IBAN.' using errcode = '22023'; end if;
  end if;
  if p_modo = 'direct_debit' then
    if r.result_kind is distinct from 'to_pay' then raise exception 'Solo se domicilia lo que sale a pagar.' using errcode = '22023'; end if;
    if r.due_date_direct_debit is null or v_hoy > r.due_date_direct_debit then
      raise exception 'Domiciliar ya no se puede: era hasta el %. Págalo tú hasta el %.',
        to_char(r.due_date_direct_debit, 'DD/MM'), to_char(r.due_date, 'DD/MM') using errcode = '22023';
    end if;
  end if;
  if p_modo = 'refund' and r.result_kind is distinct from 'to_refund' then
    raise exception 'Solo se pide la devolución de lo que sale a devolver.' using errcode = '22023';
  end if;
  update public.tax_return
     set payment_mode = case p_modo when 'self' then null else p_modo end,
         payment_treasury_account_id = case when p_modo = 'self' then null else t.id end,
         updated_at = now()
   where id = r.id;
  v_msg := case p_modo
    when 'direct_debit' then format('Domiciliado en la cuenta ···· %s: Hacienda lo carga el %s.', right(t.iban, 4), to_char(r.due_date, 'DD/MM'))
    when 'refund' then format('A devolver en la cuenta ···· %s.', right(t.iban, 4))
    else format('Sin domiciliar: lo pagas tú hasta el %s.', to_char(r.due_date, 'DD/MM')) end;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message)
  values (r.id, r.account_id, r.company_id, auth.uid(), public.conta_impuesto_quien(), 'note', v_msg);
  return jsonb_build_object('ok', true, 'mensaje', v_msg);
end $$;


--
-- Name: conta_impuesto_perceptores_poner(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_perceptores_poner(p_return uuid, p_perceptores integer, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; v_quien text := public.conta_impuesto_quien(); v_calc jsonb;
begin
  select * into r from public.tax_return where id = p_return and form_code = '111' for update;
  if r.id is null then raise exception 'Ese 111 no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(r.company_id) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, escribe casillas de sus impuestos.' using errcode = '42501';
  end if;
  if r.status not in ('pending', 'draft', 'reviewed') then
    raise exception 'Este 111 ya está «%»: sus casillas no se cambian.', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if p_perceptores is null or p_perceptores < 1 then
    raise exception 'Escribe cuántas personas cobraron nómina en el periodo (1 o más).' using errcode = '22023';
  end if;
  if p_motivo is null or btrim(p_motivo) = '' then raise exception 'Para escribir los perceptores hace falta decir de dónde sale el número.' using errcode = '22023'; end if;
  insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, origin, manual_reason, source)
  values (r.id, r.account_id, r.company_id, '01', p_perceptores, 'manual',
          btrim(p_motivo) || ' (' || v_quien || ', ' || to_char(now() at time zone 'Europe/Madrid', 'DD/MM/YYYY') || ')',
          jsonb_build_object('de', 'a mano', 'quien', v_quien))
  on conflict (tax_return_id, box) do update
    set value = excluded.value, value_text = null, origin = 'manual', manual_reason = excluded.manual_reason, source = excluded.source;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, r.account_id, r.company_id, auth.uid(), v_quien, 'note',
          v_quien || ' escribió a mano la [01] (' || p_perceptores || ' perceptores): ' || btrim(p_motivo) || '.', jsonb_build_object('casillas', jsonb_build_object('01', p_perceptores)));
  v_calc := public.conta_impuesto_retenciones_calcular(r.company_id, r.fiscal_year, r.period, '111');
  return jsonb_build_object('ok', true, 'calculo', v_calc,
    'mensaje', 'Escrita la [01]: ' || p_perceptores || case when p_perceptores = 1 then ' persona' else ' personas' end || ' con nómina. Vuelto a calcular el 111: ' ||
               translate(to_char((v_calc->>'importe')::numeric, 'FM999G999G990D00'), ',.', '.,') || ' € a ingresar.');
end $$;


--
-- Name: FUNCTION conta_impuesto_perceptores_poner(p_return uuid, p_perceptores integer, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_perceptores_poner(p_return uuid, p_perceptores integer, p_motivo text) IS 'I01g. Escribe a mano la [01] del 111 (cuántas personas cobraron nómina), con su motivo y quién, y vuelve a calcular el 111.';


--
-- Name: conta_impuesto_periodo_fechas(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_periodo_fechas(p_year integer, p_period text, OUT desde date, OUT hasta date) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
begin
  if p_period ~ '^[1-4]T$' then
    desde := make_date(p_year, (left(p_period, 1)::int - 1) * 3 + 1, 1);
    hasta := (desde + interval '3 months' - interval '1 day')::date;
  elsif p_period ~ '^(0[1-9]|1[0-2])$' then
    desde := make_date(p_year, p_period::int, 1);
    hasta := (desde + interval '1 month' - interval '1 day')::date;
  else
    raise exception 'El periodo «%» no es un trimestre ni un mes.', p_period using errcode = '22023';
  end if;
end $_$;


--
-- Name: conta_impuesto_periodos(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_periodos(p_company uuid, p_y integer) RETURNS TABLE(obligacion uuid, modelo text, cadencia text, ejercicio integer, periodo text, presentacion date, domiciliacion date, provisional text, pago text, cuenta uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.id, o.form_code, o.cadence, e.ej, p.per, pl.presentacion, pl.domiciliacion, pl.provisional,
         o.payment_mode, o.payment_treasury_account_id
    from public.tax_obligation o
   cross join generate_series(p_y - 1, p_y + 1) e(ej)
   cross join lateral unnest(case o.cadence
       when 'quarterly' then array['1T', '2T', '3T', '4T']
       when 'monthly' then array['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12']
       when 'annual' then array['0A']
       when 'instalments_202' then array['1P', '2P', '3P'] end) p(per)
   cross join lateral public.conta_impuesto_plazo_si_hay(o.form_code, o.cadence, e.ej, p.per) pl
   where o.company_id = p_company and o.valid_to is null and o.active
$$;


--
-- Name: conta_impuesto_plazo(text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_plazo(p_modelo text, p_cadencia text, p_ejercicio integer, p_periodo text, p_ambito text DEFAULT 'ES-MD'::text) RETURNS TABLE(presentacion date, presentacion_regla date, domiciliacion date, regla text, provisional text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  r public.tax_form_deadline; v_fin smallint; v_mes date; v_dia date; v_p_aeat date; v_n int := 0;
  v_empresa constant text[] := array[p_ambito];
  v_aeat constant text[] := array['ES', 'ES-MD'];
begin
  v_fin := public.conta_impuesto_fin_periodo(p_cadencia, p_periodo);
  if v_fin is null then
    raise exception 'El periodo «%» no es de un modelo %.', p_periodo,
      case p_cadencia when 'quarterly' then 'trimestral' when 'monthly' then 'mensual' when 'annual' then 'anual' when 'instalments_202' then 'de pagos fraccionados' else p_cadencia end
      using errcode = '22023';
  end if;
  select * into r from public.tax_form_deadline d
   where d.form_code = p_modelo and d.cadence = p_cadencia and d.period in (p_periodo, '*')
   order by (d.period = p_periodo) desc limit 1;
  if r.form_code is null then
    raise exception 'No tengo la regla del plazo del % (%, periodo %): no se inventa.', p_modelo, p_cadencia, p_periodo using errcode = 'P0002';
  end if;

  -- El día de la regla: meses después del último mes del periodo, ese día o el último del mes.
  v_mes := (make_date(p_ejercicio, v_fin, 1) + make_interval(months => r.months_after))::date;
  v_dia := case when r.day is null then (v_mes + interval '1 month - 1 day')::date
                else make_date(extract(year from v_mes)::int, extract(month from v_mes)::int, r.day) end;
  presentacion_regla := v_dia;
  regla := r.legal_ref;

  -- Presentación para la empresa: el primer hábil desde el día de la regla, con su calendario.
  presentacion := v_dia;
  while not public.conta_impuesto_habil(presentacion, v_empresa) loop presentacion := presentacion + 1; end loop;

  -- Domiciliación: desde el último día del plazo genérico (calendario de la AEAT),
  -- el último hábil que deja 3 hábiles hasta él, incluido.
  if r.direct_debit then
    v_p_aeat := v_dia;
    while not public.conta_impuesto_habil(v_p_aeat, v_aeat) loop v_p_aeat := v_p_aeat + 1; end loop;
    domiciliacion := v_p_aeat;
    while v_n < 3 loop
      if public.conta_impuesto_habil(domiciliacion, v_aeat) then v_n := v_n + 1; end if;
      domiciliacion := domiciliacion - 1;
    end loop;
    while not public.conta_impuesto_habil(domiciliacion, v_aeat) loop domiciliacion := domiciliacion - 1; end loop;
  end if;

  -- Si algún festivo usado es provisional, se dice.
  select string_agg(distinct y.year || ' (' || y.scope || '): ' || y.provisional_reason, ' · ') into provisional
    from public.tax_holiday_year y
   where y.provisional_reason is not null
     and y.scope = any (v_empresa || case when r.direct_debit then v_aeat else '{}'::text[] end)
     and y.year between extract(year from least(coalesce(domiciliacion, v_dia), v_dia))::int
                    and extract(year from greatest(presentacion, coalesce(v_p_aeat, presentacion)))::int;
  return next;
end $$;


--
-- Name: FUNCTION conta_impuesto_plazo(p_modelo text, p_cadencia text, p_ejercicio integer, p_periodo text, p_ambito text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_plazo(p_modelo text, p_cadencia text, p_ejercicio integer, p_periodo text, p_ambito text) IS 'I01a. Último día de presentación (trasladado si cae en inhábil para la empresa) y último día domiciliado (3 días hábiles, Orden HAC/241/2025) de un modelo y periodo. Para si falta la regla o los festivos del año.';


--
-- Name: conta_impuesto_plazo_si_hay(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_plazo_si_hay(p_modelo text, p_cadencia text, p_ejercicio integer, p_periodo text) RETURNS TABLE(presentacion date, domiciliacion date, provisional text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
begin
  return query select x.presentacion, x.domiciliacion, x.provisional from public.conta_impuesto_plazo(p_modelo, p_cadencia, p_ejercicio, p_periodo) x;
exception when others then
  return;
end $$;


--
-- Name: conta_impuesto_presentada(uuid, uuid, uuid, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_presentada(p_return uuid, p_user uuid, p_use uuid, p_csv text, p_justificante text, p_expediente text, p_fecha timestamp with time zone, p_respuesta jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare r public.tax_return; u public.tax_certificate_use; c public.tax_certificate; v_nombre text := public.conta_impuesto_nombre_de(p_user);
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  select * into u from public.tax_certificate_use where id = p_use;
  if u.id is null or u.user_id is distinct from p_user or u.action <> 'file' or u.tax_return_id is distinct from r.id then
    raise exception 'Ese uso del certificado no es de esta persona para presentar esta declaración.' using errcode = '42501';
  end if;
  if p_csv is null or p_csv !~ '^[A-Z0-9]{16}$' then raise exception 'Hacienda no ha dado un CSV válido: no se apunta como presentada.' using errcode = '22023'; end if;
  if r.status <> 'reviewed' then raise exception 'Esta declaración está «%».', public.conta_impuesto_estado_texto(r.status) using errcode = '22023'; end if;
  select * into c from public.tax_certificate where id = u.certificate_id;
  update public.tax_return
     set status = 'filed', filed_at = coalesce(p_fecha, now()), filed_by = p_user, filed_by_name = v_nombre, filed_via = 'sumied',
         presenter_kind = case when c.owner_account_id = r.account_id then 'company' else 'advisor' end, certificate_id = c.id,
         aeat_csv = p_csv, aeat_receipt_number = p_justificante, updated_at = now()
   where id = r.id;
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, aeat_service, result, message, detail)
  values (r.id, r.account_id, r.company_id, p_user, v_nombre, 'aeat_call', 'present', 'ok',
          'Presentado. Justificante ' || coalesce(p_justificante, '—') || '.',
          jsonb_build_object('expediente', p_expediente, 'csv_cola', right(p_csv, 4), 'respuesta', coalesce(p_respuesta, '{}')));
  return jsonb_build_object('ok', true, 'mensaje', 'Presentado el ' || r.form_code || ' del ' || r.period || '/' || r.fiscal_year ||
                            '. Justificante ' || coalesce(p_justificante, '—') || ', CSV ' || p_csv || '.');
end $_$;


--
-- Name: conta_impuesto_presentador_poner(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_presentador_poner(p_company uuid, p_mode text, p_advisor_account uuid DEFAULT NULL::uuid, p_basis text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_nombre text;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(v_acc) then
    raise exception 'Solo un administrador de la empresa decide quién presenta sus impuestos.' using errcode = '42501';
  end if;
  v_nombre := public.conta_impuesto_quien();
  insert into public.company_tax_presenter (company_id, account_id, mode, advisor_account_id, advisor_basis, consented_by, consented_by_name, consented_at, since)
  values (p_company, v_acc, p_mode, p_advisor_account, p_basis,
          case when p_mode = 'advisor' then auth.uid() end, case when p_mode = 'advisor' then v_nombre end,
          case when p_mode = 'advisor' then now() end, current_date)
  on conflict (company_id) do update set mode = excluded.mode, advisor_account_id = excluded.advisor_account_id,
    advisor_basis = excluded.advisor_basis, consented_by = excluded.consented_by, consented_by_name = excluded.consented_by_name,
    consented_at = excluded.consented_at, revoked_by = null, revoked_at = null, since = excluded.since, certificate_id = null;
end $$;


--
-- Name: conta_impuesto_presentador_retirar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_presentador_retirar(p_company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.current_user_is_admin_of(v_acc) then
    raise exception 'Solo un administrador de la empresa retira el permiso de su asesoría.' using errcode = '42501';
  end if;
  update public.company_tax_presenter set revoked_by = auth.uid(), revoked_at = now()
   where company_id = p_company and mode = 'advisor' and revoked_at is null;
  if not found then raise exception 'Esta empresa no tiene una asesoría con permiso.' using errcode = 'P0002'; end if;
end $$;


--
-- Name: conta_impuesto_presentados(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_presentados(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_hoy date := (now() at time zone 'Europe/Madrid')::date; v_y int := extract(year from (now() at time zone 'Europe/Madrid'))::int;
begin
  if not exists (select 1 from public.company where id = p_company) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'puede_gestionar', public.conta_impuesto_puede_gestionar(p_company),
    'presentados', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', r.id, 'cuenta', r.account_id, 'modelo', r.form_code, 'nombre', f.name, 'cadencia', r.cadence, 'ejercicio', r.fiscal_year, 'periodo', r.period,
               'estado', r.status, 'estado_texto', public.conta_impuesto_estado_texto(r.status),
               'resultado', r.result_kind, 'importe', r.amount,
               'presentada', r.filed_at, 'presentada_por', r.filed_by_name, 'por', r.filed_via, 'plazo', r.due_date,
               'csv', r.aeat_csv, 'justificante', r.aeat_receipt_number, 'justificante_pdf', r.receipt_document_path,
               'contabilizada', r.liquidation_entry_id is not null, 'casada', r.bank_match_id is not null,
               'comprobada', r.filed_via = 'sumied' or r.receipt_source = 'aeat_csv'
                             or exists (select 1 from public.tax_return_event e where e.tax_return_id = r.id
                                         and e.aeat_service = 'outside_check' and e.result = 'ok'),
               -- 0270: el PDF traído de Hacienda, el expediente, el presentador y, en el 303,
               -- lo compensado con trimestres anteriores ([78]): un 0,00 € que salió a ingresar.
               'traido', r.receipt_source = 'aeat_csv', 'expediente', r.aeat_expediente,
               'presentador', case when r.presenter_tax_id is not null or r.presenter_name is not null
                                   then jsonb_build_object('nif', r.presenter_tax_id, 'nombre', r.presenter_name) end,
               'compensado', case when r.form_code = '303' then
                               (select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '78' and b.value > 0) end)
             order by r.filed_at desc nulls last, r.fiscal_year desc, r.period desc), '[]')
        from public.tax_return r join public.tax_form f on f.code = r.form_code
       where r.company_id = p_company and r.status in ('filed', 'booked', 'paid', 'offset', 'refunded')),
    'para_apuntar', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'ejercicio', c.ejercicio, 'periodo', c.periodo, 'presentacion', c.presentacion,
               'declaracion', r.id, 'estado', r.status, 'resultado', r.result_kind, 'importe', r.amount)
             order by c.ejercicio desc, c.periodo desc), '[]')
        from public.conta_impuesto_periodos(p_company, v_y) c
        left join public.tax_return r on r.company_id = p_company and r.form_code = '303' and r.fiscal_year = c.ejercicio
                                      and r.period = c.periodo and r.sequence = 1
       where c.modelo = '303' and c.ejercicio between v_y - 1 and v_y
         and c.presentacion - interval '25 days' <= v_hoy
         and coalesce(r.status, 'pending') in ('pending', 'draft', 'reviewed')));
end $$;


--
-- Name: FUNCTION conta_impuesto_presentados(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_presentados(p_company uuid) IS 'I01c (0270). Las declaraciones presentadas de la empresa (con su PDF traído de Hacienda o subido, expediente, presentador y lo compensado del 303) y los periodos del 303 que se pueden apuntar como presentados fuera. No escribe nada.';


--
-- Name: conta_impuesto_puede_gestionar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_puede_gestionar(p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.company c where c.id = p_company and public.current_user_is_admin_or_manager_of(c.account_id))
      or exists (select 1 from public.company_tax_presenter t
                  where t.company_id = p_company and t.mode = 'advisor' and t.consented_at is not null and t.revoked_at is null
                    and public.current_user_is_admin_or_manager_of(t.advisor_account_id))
$$;


--
-- Name: conta_impuesto_puede_ver(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_puede_ver(p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.company c where c.id = p_company and public.belongs_to_account(c.account_id))
      or exists (select 1 from public.company_tax_presenter t
                  where t.company_id = p_company and t.mode = 'advisor' and t.consented_at is not null and t.revoked_at is null
                    and t.advisor_account_id = any (public.current_user_account_ids()))
$$;


--
-- Name: conta_impuesto_quien(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_quien() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select nullif(btrim(display_name), '') from public.user_profiles where user_id = auth.uid() and active order by display_name limit 1), 'Sumied')
$$;


--
-- Name: conta_impuesto_reglas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_reglas(p_company uuid) RETURNS TABLE(form_code text, active boolean, cadence text, rule_key text, rule_facts jsonb, why text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  p public.company_tax_profile; c public.company;
  v_nomina int; v_f111 int; v_f115 int;
  v_retiene jsonb; v_alquila jsonb; v_roi jsonb; v_hay_retiene boolean; v_hay_alquila boolean;
  v_r70 jsonb; v_hay_r70 boolean; v_actividades int; v_profesionales int;
  v_mensual boolean; v_303 boolean; v_111 boolean; v_115 boolean; v_202 boolean;
  v_ue_compras int; v_ue_ventas int; v_349 boolean;
  t record;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  select * into p from public.company_tax_profile where company_id = p_company;
  v_mensual := coalesce(p.vat_period = 'monthly', false) or coalesce(p.sii, false);

  -- Los datos, siempre de esta empresa y su cuenta (regla 9).
  select coalesce(max(s.employees_count), 0) into v_nomina from public.payroll_summary s
   where s.account_id = c.account_id and s.company_id = p_company and s.period_month >= (date_trunc('month', current_date) - interval '12 months')::date;
  select count(*) filter (where w.filed_in = '111'), count(*) filter (where w.filed_in = '115') into v_f111, v_f115
    from public.supplier_invoice i join public.withholding_rate w on w.id = i.withholding_rate_id
   where i.account_id = c.account_id and i.company_id = p_company and coalesce(i.withholding_amount, 0) <> 0
     and i.invoice_date >= current_date - interval '12 months';
  -- «Lo dijo» (hay fila) y «qué dijo» (null = «No lo sé»), por separado: sin fila, no se dijo nada.
  select value into v_retiene from public.company_tax_facts where company_id = p_company and fact = 'pays_with_withholding';
  v_hay_retiene := found;
  select value into v_alquila from public.company_tax_facts where company_id = p_company and fact = 'rents_premises_with_withholding';
  v_hay_alquila := found;
  select value into v_roi from public.company_tax_facts where company_id = p_company and fact = 'roi_registered';
  select value into v_r70 from public.company_tax_facts where company_id = p_company and fact = 'withheld_income_70';
  v_hay_r70 := found;
  -- Operaciones con la UE en los últimos 12 meses, del libro de IVA (0250):
  -- compras intracomunitarias (clave 09, la que pone el libro a una
  -- adquisición intracomunitaria, o autoliquidada con país de la UE) y ventas
  -- intracomunitarias (exenta E5, o con país de la UE).
  select count(*) filter (where v.book in ('received', 'investment')
                            and (v.operation_key = '09' or (v.reverse_charge and v.counterpart_country = any (public.conta_paises_ue())))),
         count(*) filter (where v.book = 'issued' and (v.exempt_cause = 'E5' or v.counterpart_country = any (public.conta_paises_ue())))
    into v_ue_compras, v_ue_ventas
    from public.vat_book_entry v
   where v.account_id = c.account_id and v.company_id = p_company and v.voided_at is null
     and coalesce(v.received_date, v.operation_date, v.issue_date) >= (current_date - interval '12 months')::date;
  select count(*), count(*) filter (where a.kind = 'professional') into v_actividades, v_profesionales
    from public.company_activity a where a.account_id = c.account_id and a.company_id = p_company and a.ended_on is null;

  -- 303
  v_303 := coalesce(p.tax_territory, 'peninsula_baleares') = 'peninsula_baleares' and coalesce(p.vat_scheme_code, 'general') <> 'recargo_equivalencia';
  form_code := '303'; active := v_303; cadence := case when v_mensual then 'monthly' else 'quarterly' end; rule_key := 'iva_303';
  rule_facts := jsonb_build_object('territorio', coalesce(p.tax_territory, 'peninsula_baleares'), 'regimen', coalesce(p.vat_scheme_code, 'general'),
                                   'mensual', v_mensual, 'sii', coalesce(p.sii, false));
  why := case
    when not v_303 and coalesce(p.tax_territory, '') = 'canarias' then 'En Canarias no hay IVA sino IGIC: sus modelos los confirma tu asesor.'
    when not v_303 and coalesce(p.tax_territory, '') = 'ceuta_melilla' then 'En Ceuta y Melilla no hay IVA sino IPSI: sus modelos los confirma tu asesor.'
    when not v_303 then 'Estás en recargo de equivalencia: el IVA lo paga tu proveedor y no presentas el 303.'
    when coalesce(p.sii, false) then 'Llevas el SII: declaras el IVA cada mes, lo que cobras menos lo que pagas.'
    when v_mensual then 'Declaras el IVA cada mes, lo que cobras menos lo que pagas.'
    else 'Vendes con IVA: cada trimestre declaras lo que cobras menos lo que pagas.' end;
  return next;

  -- 111
  v_111 := v_nomina > 0 or v_f111 > 0 or (v_hay_retiene and coalesce(v_retiene = 'true'::jsonb, true));
  form_code := '111'; active := v_111; cadence := case when coalesce(p.vat_period = 'monthly', false) then 'monthly' else 'quarterly' end; rule_key := 'ret_111';
  rule_facts := jsonb_build_object('personas_en_nomina', v_nomina, 'facturas_con_retencion_111', v_f111, 'dijo_en_el_alta', v_retiene);
  why := case
    when v_nomina > 0 then 'Tienes ' || v_nomina || case when v_nomina = 1 then ' persona' else ' personas' end || ' en nómina: declaras cada trimestre lo que les retienes.'
    when v_f111 > 0 then 'Tienes ' || v_f111 || case when v_f111 = 1 then ' factura' else ' facturas' end || ' de profesionales con retención en los últimos 12 meses: declaras cada trimestre lo retenido.'
    when v_hay_retiene and v_retiene is null then 'Dijiste «No lo sé» a si pagas nóminas o profesionales con retención: lo dejamos hasta que lo confirme tu asesor.'
    when v_hay_retiene and v_retiene = 'true'::jsonb then 'Dijiste en el alta que pagas nóminas o facturas de profesionales con retención.'
    else 'No tienes a nadie en nómina ni facturas de profesionales con retención.' end;
  if v_111 or v_hay_retiene then return next; end if;

  -- 115
  v_115 := v_f115 > 0 or (v_hay_alquila and coalesce(v_alquila = 'true'::jsonb, true));
  form_code := '115'; active := v_115; cadence := case when coalesce(p.vat_period = 'monthly', false) then 'monthly' else 'quarterly' end; rule_key := 'alq_115';
  rule_facts := jsonb_build_object('facturas_con_retencion_115', v_f115, 'dijo_en_el_alta', v_alquila);
  why := case
    when v_f115 > 0 then 'Tienes ' || v_f115 || case when v_f115 = 1 then ' factura' else ' facturas' end || ' de alquiler con retención en los últimos 12 meses: declaras cada trimestre lo retenido.'
    when v_hay_alquila and v_alquila is null then 'Dijiste «No lo sé» a si pagas el alquiler del local con retención: lo dejamos hasta que lo confirme tu asesor.'
    when v_hay_alquila and v_alquila = 'true'::jsonb then 'Dijiste en el alta que pagas el alquiler del local con retención.'
    else 'No pagas el alquiler de un local con retención.' end;
  if v_115 or v_hay_alquila then return next; end if;

  -- 202 y 200
  v_202 := c.entity_kind = 'company';
  if v_202 then
    form_code := '202'; active := true; cadence := 'instalments_202'; rule_key := 'is_202';
    rule_facts := jsonb_build_object('tipo', c.entity_kind);
    why := 'Eres una sociedad: adelantas el Impuesto sobre Sociedades en abril, octubre y diciembre.';
    return next;
    form_code := '200'; active := true; cadence := 'annual'; rule_key := 'is_200';
    why := 'Eres una sociedad: en julio presentas el Impuesto sobre Sociedades del año.';
    return next;
  end if;

  -- 130 (autónomos)
  if c.entity_kind = 'self_employed' and (v_actividades = 0 or v_profesionales < v_actividades or v_hay_r70) then
    form_code := '130'; cadence := 'quarterly'; rule_key := 'irpf_130';
    rule_facts := jsonb_build_object('actividades', v_actividades, 'profesionales', v_profesionales, 'retenido_70', v_r70);
    if v_actividades = 0 or v_profesionales < v_actividades then
      active := true;
      why := 'Como autónomo con actividad empresarial, adelantas el IRPF cada trimestre.';
    elsif v_r70 is null then
      active := true;
      why := 'Dijiste «No lo sé» a si el 70 % de tus ingresos llevó retención: lo dejamos, que es lo normal, hasta que lo confirme tu asesor.';
    elsif v_r70 = 'true'::jsonb then
      active := false;
      why := 'El año pasado al menos el 70 % de tus ingresos llevó retención: no adelantas el IRPF.';
    else
      active := true;
      why := 'Menos del 70 % de tus ingresos llevó retención: adelantas el IRPF cada trimestre.';
    end if;
    return next;
  end if;

  -- Los resúmenes anuales de cada periódico, de la tabla de modelos: van con
  -- su periódico, en el mismo sentido, cuando una regla ha decidido sobre él.
  for t in select f.code, f.annual_form_code, f.annual_legal_ref from public.tax_form f
            where f.code in ('303', '111', '115') and f.annual_form_code is not null loop
    continue when (t.code = '111' and not (v_111 or v_hay_retiene)) or (t.code = '115' and not (v_115 or v_hay_alquila));
    form_code := t.annual_form_code; cadence := 'annual'; rule_key := 'anual_de_' || t.code;
    active := case t.code when '303' then v_303 when '111' then v_111 else v_115 end;
    rule_facts := jsonb_build_object('periodico', t.code, 'presenta_el_periodico', active, 'norma', t.annual_legal_ref);
    why := case when active then 'Presentas el ' || t.code || ': en enero resumes el año en el ' || t.annual_form_code || '.'
                else 'No presentas el ' || t.code || ', así que tampoco su resumen anual.' end;
    return next;
  end loop;

  -- 347, por defecto (tax_form.default_for).
  if exists (select 1 from public.tax_form where code = '347' and default_for = 'company_not_sii') and c.entity_kind = 'company' and not coalesce(p.sii, false) then
    form_code := '347'; active := true; cadence := 'annual'; rule_key := 'defecto_347';
    rule_facts := jsonb_build_object('sii', false, 'tipo', c.entity_kind);
    why := 'No llevas el SII: en febrero declaras a quien te compró o vendió más de 3.005,06 € en el año.';
    return next;
  end if;

  -- 349: lo propone tener operaciones con la UE (compras o ventas
  -- intracomunitarias en el libro de IVA, últimos 12 meses) o estar en el ROI.
  -- Julio, 18/10: Foodint compra servicios en la UE y la gestoría no presenta
  -- el 349; que se proponga, con su porqué, y que se pueda quitar con motivo
  -- (lo quitado a mano no lo pisa ninguna regla).
  -- Sale siempre, también cuando no toca: «No te sale el 349» con su porqué.
  v_349 := v_ue_compras > 0 or v_ue_ventas > 0 or coalesce(v_roi = 'true'::jsonb, false);
  form_code := '349'; active := v_349; cadence := 'quarterly'; rule_key := 'roi_349';
  rule_facts := jsonb_build_object('roi', v_roi, 'compras_ue_12_meses', v_ue_compras, 'ventas_ue_12_meses', v_ue_ventas);
  why := case
    when v_ue_compras > 0 or v_ue_ventas > 0 then
      'En los últimos 12 meses tienes ' ||
      concat_ws(' y ',
        case when v_ue_compras > 0 then v_ue_compras || case when v_ue_compras = 1 then ' compra' else ' compras' end || ' a empresas de la UE' end,
        case when v_ue_ventas > 0 then v_ue_ventas || case when v_ue_ventas = 1 then ' venta' else ' ventas' end || ' a empresas de la UE' end) ||
      ': las operaciones intracomunitarias se declaran en el 349 el trimestre en que se hacen.' ||
      case when v_roi = 'false'::jsonb then ' Dijiste que no estás en el Registro de Operadores Intracomunitarios: confírmalo con tu asesor.' else '' end
    when v_roi = 'true'::jsonb then 'Estás dado de alta en el Registro de Operadores Intracomunitarios: declaras tus operaciones con la UE.'
    when v_roi = 'false'::jsonb then 'No estás en el Registro de Operadores Intracomunitarios ni tienes operaciones con la UE en los últimos 12 meses.'
    else 'No tienes compras ni ventas con empresas de la UE en los últimos 12 meses.' end;
  return next;
end $$;


--
-- Name: FUNCTION conta_impuesto_reglas(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_reglas(p_company uuid) IS 'I01a/I01b (0250). Lo que dice cada regla con nombre sobre los modelos de una empresa, con los datos y el porqué en palabras de oficina. El 349, por operaciones con la UE o el ROI. No escribe nada.';


--
-- Name: conta_impuesto_retenciones_calcular(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_retenciones_calcular(p_company uuid, p_year integer, p_period text, p_form text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; o public.tax_obligation; r public.tax_return; v_plazo record; v_quien text := public.conta_impuesto_quien();
  v_d jsonb; s jsonb; v_man jsonb; v_box jsonb; v_kind text; v_total numeric; v_n int; v_det jsonb;
  v_ant public.tax_return; v_ant_y int; v_ant_p text; v_prop numeric; v_sin int; v_sin_ret numeric;
  v_nomina numeric; v_prof numeric; v_115 numeric; v_4751 numeric; v_otro numeric; v_falta_01 boolean;
  e text := 'FM999G999G990D00';
begin
  if p_form not in ('111', '115') then raise exception 'Solo se calculan aquí el 111 y el 115.' using errcode = '22023'; end if;
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, calcula sus impuestos.' using errcode = '42501';
  end if;
  select * into o from public.tax_obligation where company_id = p_company and form_code = p_form and valid_to is null and active;
  if o.id is null then raise exception 'Esta empresa no presenta el % (no está en sus modelos).', p_form using errcode = 'P0002'; end if;
  if (o.cadence = 'quarterly' and p_period !~ '^[1-4]T$') or (o.cadence = 'monthly' and p_period !~ '^(0[1-9]|1[0-2])$') then
    raise exception 'Esta empresa presenta el % %, y «%» no es un periodo suyo.', p_form, case o.cadence when 'monthly' then 'cada mes' else 'cada trimestre' end, p_period using errcode = '22023';
  end if;

  select * into r from public.tax_return where company_id = p_company and form_code = p_form and fiscal_year = p_year and period = p_period and sequence = 1 for update;
  if r.id is not null and r.status not in ('pending', 'draft', 'reviewed') then
    raise exception 'El % del % de % ya está «%»: no se recalcula.', p_form, p_period, p_year, public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  if r.id is null then
    select * into v_plazo from public.conta_impuesto_plazo(p_form, o.cadence, p_year, p_period, 'ES-MD');
    insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, due_date,
                                   due_date_direct_debit, due_provisional, alert_on, status, payment_mode, payment_treasury_account_id)
    values (c.account_id, p_company, o.id, p_form, p_year, o.cadence, p_period, v_plazo.presentacion, v_plazo.domiciliacion, v_plazo.provisional,
            case when o.payment_mode = 'direct_debit' then v_plazo.domiciliacion else v_plazo.presentacion end, 'draft',
            nullif(o.payment_mode, 'none'), case when o.payment_mode = 'direct_debit' then o.payment_treasury_account_id end)
    returning * into r;
  elsif r.status <> 'draft' then
    update public.tax_return set status = 'draft' where id = r.id returning * into r;
  end if;

  v_d := public.conta_impuesto_retenciones_diario(p_company, p_year, p_period);
  s := v_d->'sumas';
  v_nomina := (s#>>'{111_nomina,retenido}')::numeric;
  v_prof := (s#>>'{111_profesional,retenido}')::numeric;
  v_115 := (s#>>'{115,retenido}')::numeric;
  v_sin := (s#>>'{sin_modelo,asientos}')::int;
  v_sin_ret := (s#>>'{sin_modelo,retenido}')::numeric;

  -- Las líneas: cada asiento del modelo, con su foto.
  delete from public.tax_return_line where tax_return_id = r.id;
  insert into public.tax_return_line (tax_return_id, account_id, company_id, boxes, frozen)
  select r.id, c.account_id, p_company,
         case when p_form = '115' then array['02', '03'] when a->>'tipo' = '111_nomina' then array['02', '03'] else array['08', '09'] end,
         a || jsonb_build_object('origen', 'diario')
    from jsonb_array_elements(v_d->'asientos') a
   where (p_form = '115' and a->>'tipo' = '115') or (p_form = '111' and a->>'tipo' in ('111_nomina', '111_profesional'));

  -- Las casillas calculadas (la [01] del 111 a mano se queda, y manda).
  delete from public.tax_return_box where tax_return_id = r.id and origin = 'calculated';
  select coalesce(jsonb_object_agg(box, value), '{}') into v_man from public.tax_return_box where tax_return_id = r.id and origin = 'manual' and value is not null;
  if p_form = '111' then
    v_total := v_nomina + v_prof;
    insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
    select r.id, c.account_id, p_company, k, round(val, 2), jsonb_build_object('de', como)
      from (values ('02', (s#>>'{111_nomina,base}')::numeric, 'la 640 de las nóminas del periodo, sin la 641', v_nomina <> 0 or (s#>>'{111_nomina,base}')::numeric <> 0),
                   ('03', v_nomina, 'lo retenido en la 4751 en las nóminas', v_nomina <> 0 or (s#>>'{111_nomina,base}')::numeric <> 0),
                   ('07', (s#>>'{111_profesional,perceptores}')::numeric, 'los proveedores distintos con retención', v_prof <> 0),
                   ('08', (s#>>'{111_profesional,base}')::numeric, 'el gasto de las facturas con retención', v_prof <> 0),
                   ('09', v_prof, 'lo retenido en la 4751 en esas facturas', v_prof <> 0),
                   ('28', v_total, '[03]+[09]', true),
                   ('30', v_total, '[28]−[29]', true)) t(k, val, como, va)
     where va and not v_man ? k
    on conflict (tax_return_id, box) do nothing;
  else
    v_total := v_115;
    insert into public.tax_return_box (tax_return_id, account_id, company_id, box, value, source)
    select r.id, c.account_id, p_company, k, round(val, 2), jsonb_build_object('de', como)
      from (values ('01', (s#>>'{115,perceptores}')::numeric, 'los arrendadores distintos con retención'),
                   ('02', (s#>>'{115,base}')::numeric, 'la 621 de las facturas con retención'),
                   ('03', v_115, 'lo retenido en la 4751 en esas facturas'),
                   ('05', v_115, '[03]−[04]')) t(k, val, como)
     where not v_man ? k
    on conflict (tax_return_id, box) do nothing;
  end if;

  -- La [01] del 111: a mano (Julio, 20/10). Sin ella, con nóminas, no se da por revisado.
  v_falta_01 := p_form = '111' and (v_nomina <> 0 or (s#>>'{111_nomina,base}')::numeric <> 0) and not v_man ? '01';

  -- El resultado.
  v_kind := case when v_total > 0 then 'to_pay' when v_total = 0 and jsonb_array_length(v_d->'asientos') = 0 then 'no_activity'
                 when v_total = 0 then 'zero' else null end;
  update public.tax_return set result_kind = v_kind, amount = case when v_kind is not null then abs(v_total) end,
         calculated_at = now(), updated_at = now() where id = r.id;

  -- Lo comprobado (se rehace entero).
  delete from public.tax_return_check where tax_return_id = r.id;

  -- a) Lo retenido de este modelo y de los demás suma lo que la 4751 tiene del periodo.
  v_4751 := v_nomina + v_prof + v_115 + v_sin_ret;
  v_otro := case when p_form = '111' then v_115 else v_nomina + v_prof end;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'ledger_4751', case when v_total < 0 then 'error' else 'ok' end,
          case when v_total < 0
               then 'Lo retenido en el periodo sale negativo (' || translate(to_char(v_total, e), ',.', '.,') || ' €): mira los contraasientos de la 4751 en el mayor.'
               else 'Lo retenido sale del diario: ' || translate(to_char(v_total, e), ',.', '.,') || ' € en la 4751' ||
                    case when v_otro <> 0 then ' (otros ' || translate(to_char(v_otro, e), ',.', '.,') || ' € van en el ' || case when p_form = '111' then '115' else '111' end || ')' else '' end ||
                    ', sin la apertura ni los pagos a Hacienda (' || (s->>'pagos') || ').' end,
          jsonb_build_object('retenido', v_total, 'cuenta_4751', v_4751, 'otro_modelo', v_otro, 'pagos', (s->>'pagos')::int, 'aperturas', (s->>'aperturas')::int));

  -- b) Asientos con retención que Sumied no sabe a qué modelo van.
  select coalesce(jsonb_agg(a), '[]') into v_det from jsonb_array_elements(v_d->'asientos') a where a->>'tipo' = 'sin_modelo';
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'withholding_unclassified', case when v_sin > 0 then 'error' else 'ok' end,
          case when v_sin = 0 then 'Cada asiento con retención del periodo tiene su modelo.'
               when v_sin = 1 then '1 asiento mueve la 4751 sin gasto ni nómina (' || translate(to_char(v_sin_ret, e), ',.', '.,') || ' € retenidos): Sumied no sabe si va en el 111 o en el 115. Ábrelo en el diario.'
               else v_sin || ' asientos mueven la 4751 sin gasto ni nómina (' || translate(to_char(v_sin_ret, e), ',.', '.,') || ' € retenidos): Sumied no sabe si van en el 111 o en el 115. Ábrelos en el diario.' end,
          jsonb_build_object('asientos', v_det));

  -- c) Los perceptores de las nóminas (solo el 111).
  if p_form = '111' then
    v_ant_y := case when p_period in ('1T', '01') then p_year - 1 else p_year end;
    v_ant_p := case when p_period ~ '^[1-4]T$' then case when p_period = '1T' then '4T' else (left(p_period, 1)::int - 1) || 'T' end
                    else case when p_period = '01' then '12' else lpad((p_period::int - 1)::text, 2, '0') end end;
    select * into v_ant from public.tax_return where company_id = p_company and form_code = '111' and fiscal_year = v_ant_y and period = v_ant_p and sequence = 1;
    select value into v_prop from public.tax_return_box where tax_return_id = v_ant.id and box = '01';
    insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
    values (r.id, c.account_id, p_company, 'payees_111', case when v_falta_01 then 'error' else 'ok' end,
            case when v_falta_01
                 then 'Falta cuántas personas cobraron nómina en el periodo ([01]): el diario lleva las nóminas sin trabajadores. Escríbelo con su motivo' ||
                      case when v_prop is not null then ' (en el ' || v_ant_p || '/' || v_ant_y || ' fueron ' || v_prop::int || ').' else '.' end
                 when v_man ? '01' then 'Las personas que cobraron nómina las escribió una persona: ' || (v_man->>'01')::numeric::int || '.'
                 else 'En el periodo no hay nóminas con retención.' end,
            jsonb_build_object('a_mano', v_man ? '01', 'perceptores', v_man->'01', 'propuesta', v_prop, 'periodo_anterior', v_ant_p || '/' || v_ant_y));
  end if;

  -- d) Recibidas por correo sin apuntar: pueden llevar retención.
  select count(*) into v_n from public.supplier_invoice si
   where si.account_id = c.account_id and si.company_id = p_company and si.arrival_channel = 'correo'
     and si.status not in ('anulada', 'descartada') and si.journal_entry_id is null and si.invoice_date <= (v_d->>'hasta')::date;
  insert into public.tax_return_check (tax_return_id, account_id, company_id, check_key, result, title, detail)
  values (r.id, c.account_id, p_company, 'mail_invoices_missing', case when v_n > 0 then 'warning' else 'ok' end,
          case when v_n = 0 then 'No falta ninguna factura recibida por correo.'
               when v_n = 1 then '1 factura que llegó por correo está sin apuntar: si lleva retención, no entra hasta que se valide.'
               else v_n || ' facturas que llegaron por correo están sin apuntar: si llevan retención, no entran hasta que se validen.' end,
          jsonb_build_object('facturas', v_n));

  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  values (r.id, c.account_id, p_company, auth.uid(), v_quien, 'calculation',
          v_quien || ' calculó el ' || p_form || ' del ' || p_period || '/' || p_year || ' desde el diario: ' || translate(to_char(v_total, e), ',.', '.,') || ' €.',
          jsonb_build_object('sumas', s));

  select jsonb_object_agg(box, value) into v_box from public.tax_return_box where tax_return_id = r.id and value is not null;
  return jsonb_build_object('declaracion', r.id, 'modelo', p_form, 'desde', v_d->'desde', 'hasta', v_d->'hasta',
                            'asientos', (select count(*) from public.tax_return_line where tax_return_id = r.id),
                            'resultado', v_kind, 'importe', case when v_kind is not null then abs(v_total) end,
                            'casillas', coalesce(v_box, '{}'), 'falta_perceptores', v_falta_01, 'propuesta_perceptores', v_prop, 'quien', v_quien);
end $_$;


--
-- Name: FUNCTION conta_impuesto_retenciones_calcular(p_company uuid, p_year integer, p_period text, p_form text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_retenciones_calcular(p_company uuid, p_year integer, p_period text, p_form text) IS 'I01g. Crea o recalcula el borrador del 111 o del 115 del periodo desde el diario (conta_impuesto_retenciones_diario): casillas, líneas y lo comprobado. La [01] del 111 va a mano (conta_impuesto_perceptores_poner): sin ella, con nóminas, queda un error y no se da por revisado. Uno presentado no se recalcula; uno revisado vuelve a borrador.';


--
-- Name: conta_impuesto_retenciones_diario(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_retenciones_diario(p_company uuid, p_year integer, p_period text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c public.company; v_desde date; v_hasta date; v_asientos jsonb; v_sumas jsonb; v_640 jsonb; v_621 numeric; v_4751 jsonb;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;
  select * into v_desde, v_hasta from public.conta_impuesto_periodo_fechas(p_year, p_period);

  with e as (
    select je.id, je.entry_date, je.series, je.number, je.concept, je.status, je.source_type, je.reverses_entry_id
      from public.journal_entry je
     where je.account_id = c.account_id and je.company_id = p_company and je.status in ('validado', 'anulado')
       and je.entry_date between v_desde and v_hasta
       and exists (select 1 from public.journal_line l join public.company_account ca on ca.id = l.company_account_id
                    where l.entry_id = je.id and ca.code like '4751%')
  ), x as (
    select e.id, e.entry_date, e.series, e.number, e.concept, e.status, e.source_type, e.reverses_entry_id,
           coalesce(sum(l.credit - l.debit) filter (where ca.code like '4751%'), 0) as retenido,
           bool_or(ca.code ~ '^(10|11|12)') as mueve_grupo_1,
           bool_or(ca.code like '57%') as tesoreria,
           -- S01d: todas sus líneas de la 4751 dicen modelo y periodo y no llevan tipo: es un pago, una compensación o una devolución.
           coalesce(bool_and(l.withholding_rate_id is null and l.withholding_model is not null and l.withholding_period is not null)
                    filter (where ca.code like '4751%'), false) as pago_marcado,
           coalesce(sum(l.debit - l.credit) filter (where ca.code like '621%'), 0) as b621,
           coalesce(sum(l.debit - l.credit) filter (where ca.code like '640%'), 0) as b640,
           coalesce(sum(l.debit - l.credit) filter (where ca.code ~ '^(6|2)' and ca.code !~ '^(621|64)'), 0) as bgasto,
           max(l.withholding_model) filter (where ca.code like '4751%') as modelo_linea,
           max(wr.code) filter (where ca.code like '4751%') as tipo_linea,
           -- La base de la línea de la 4751 (Sumied la exige al validar): manda si la llevan todas.
           case when bool_and(l.withholding_base is not null) filter (where ca.code like '4751%')
                then sum(l.withholding_base) filter (where ca.code like '4751%') end as base_linea,
           string_agg(distinct ca.code, ' ') filter (where ca.code like '4751%') as cuentas_4751,
           -- El perceptor: el tercero de la línea de la 4751 o, si no, la subcuenta del proveedor (40 o 41).
           coalesce(max(l.party_id::text) filter (where ca.code like '4751%'),
                    max(ca.id::text) filter (where ca.code ~ '^(40|41)')) as perceptor,
           max(ca.code || ' · ' || coalesce(nullif(ca.plain_name, ''), ca.name)) filter (where ca.code ~ '^(40|41)') as perceptor_nombre
      from e
      join public.journal_line l on l.entry_id = e.id
      join public.company_account ca on ca.id = l.company_account_id
      left join public.withholding_rate wr on wr.id = l.withholding_rate_id
     group by e.id, e.entry_date, e.series, e.number, e.concept, e.status, e.source_type, e.reverses_entry_id
  ), m0 as (
    select x.*,
           case when x.source_type in ('opening', 'closing') or x.mueve_grupo_1 then 'apertura'
                when x.pago_marcado then 'pago'
                when x.retenido < 0 and x.reverses_entry_id is null and x.tesoreria then 'pago'
                when x.modelo_linea is not null and x.modelo_linea not in ('111', '115') then 'otro_modelo'
                when x.modelo_linea = '115' or (x.modelo_linea is null and x.b621 <> 0) then '115'
                when x.modelo_linea = '111' and x.tipo_linea = 'administradores' then '111_nomina'
                when x.modelo_linea = '111' then '111_profesional'
                when x.b640 <> 0 then '111_nomina'
                when x.bgasto <> 0 then '111_profesional'
                else 'sin_modelo' end as tipo
      from x
  ), m as (
    -- La base: la de la línea de la 4751 si la lleva (con el signo de lo retenido: un
    -- contraasiento resta); si no (lo traído de Diez), la de la regla de arriba.
    select m0.*,
           case when m0.base_linea is not null then sign(m0.retenido) * abs(m0.base_linea)
                else case m0.tipo when '115' then m0.b621 when '111_nomina' then m0.b640 when '111_profesional' then m0.bgasto end end as base
      from m0
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'asiento', m.id, 'fecha', m.entry_date, 'serie', m.series, 'numero', m.number, 'concepto', m.concept, 'estado', m.status,
           'tipo', m.tipo, 'retenido', round(m.retenido, 2),
           'base', round(m.base, 2), 'tipo_retencion', m.tipo_linea,
           'perceptor', case when m.tipo in ('115', '111_profesional') then m.perceptor end,
           'perceptor_nombre', case when m.tipo in ('115', '111_profesional') then m.perceptor_nombre end,
           'cuentas_4751', m.cuentas_4751) order by m.entry_date, m.series, m.number), '[]'),
         jsonb_build_object(
           '115', jsonb_build_object('asientos', count(*) filter (where m.tipo = '115'),
                                     'base', round(coalesce(sum(m.base) filter (where m.tipo = '115'), 0), 2),
                                     'retenido', round(coalesce(sum(m.retenido) filter (where m.tipo = '115'), 0), 2)),
           '111_nomina', jsonb_build_object('asientos', count(*) filter (where m.tipo = '111_nomina'),
                                     'base', round(coalesce(sum(m.base) filter (where m.tipo = '111_nomina'), 0), 2),
                                     'retenido', round(coalesce(sum(m.retenido) filter (where m.tipo = '111_nomina'), 0), 2)),
           '111_profesional', jsonb_build_object('asientos', count(*) filter (where m.tipo = '111_profesional'),
                                     'base', round(coalesce(sum(m.base) filter (where m.tipo = '111_profesional'), 0), 2),
                                     'retenido', round(coalesce(sum(m.retenido) filter (where m.tipo = '111_profesional'), 0), 2)),
           'sin_modelo', jsonb_build_object('asientos', count(*) filter (where m.tipo = 'sin_modelo'),
                                     'retenido', round(coalesce(sum(m.retenido) filter (where m.tipo = 'sin_modelo'), 0), 2)),
           'otro_modelo', jsonb_build_object('asientos', count(*) filter (where m.tipo = 'otro_modelo'),
                                     'retenido', round(coalesce(sum(m.retenido) filter (where m.tipo = 'otro_modelo'), 0), 2)),
           'pagos', count(*) filter (where m.tipo = 'pago'),
           'aperturas', count(*) filter (where m.tipo = 'apertura'))
    into v_asientos, v_sumas
    from m;

  -- Los perceptores distintos con algo retenido (un contraasiento lo deja a cero).
  v_sumas := jsonb_set(jsonb_set(v_sumas, '{115,perceptores}', to_jsonb((
      select count(*) from (select a->>'perceptor' from jsonb_array_elements(v_asientos) a where a->>'tipo' = '115' and a->>'perceptor' is not null
                             group by 1 having abs(sum((a->>'retenido')::numeric)) >= 0.005) s))),
    '{111_profesional,perceptores}', to_jsonb((
      select count(*) from (select a->>'perceptor' from jsonb_array_elements(v_asientos) a where a->>'tipo' = '111_profesional' and a->>'perceptor' is not null
                             group by 1 having abs(sum((a->>'retenido')::numeric)) >= 0.005) s)));

  -- Cada línea de la 640 de las nóminas, para explicar una diferencia con lo presentado.
  select coalesce(jsonb_agg(jsonb_build_object('asiento', je.id, 'fecha', je.entry_date, 'importe', round(l.debit - l.credit, 2),
                                               'concepto', coalesce(l.concept, je.concept)) order by je.entry_date, l.position), '[]')
    into v_640
    from public.journal_line l join public.journal_entry je on je.id = l.entry_id
    join public.company_account ca on ca.id = l.company_account_id
   where je.id in (select (a->>'asiento')::uuid from jsonb_array_elements(v_asientos) a where a->>'tipo' = '111_nomina')
     and ca.code like '640%';

  -- La 621 entera del periodo (también los alquileres sin retención) y el haber de cada subcuenta de la 4751.
  select coalesce(sum(l.debit - l.credit), 0) into v_621
    from public.journal_line l join public.journal_entry je on je.id = l.entry_id
    join public.company_account ca on ca.id = l.company_account_id
   where je.account_id = c.account_id and je.company_id = p_company and je.status in ('validado', 'anulado')
     and je.entry_date between v_desde and v_hasta and ca.code like '621%';
  select coalesce(jsonb_agg(jsonb_build_object('cuenta', q.code, 'nombre', q.nombre, 'haber', q.haber, 'debe', q.debe) order by q.code), '[]')
    into v_4751
    from (select ca.code, coalesce(nullif(ca.plain_name, ''), ca.name) as nombre, round(sum(l.credit), 2) as haber, round(sum(l.debit), 2) as debe
            from public.journal_line l join public.journal_entry je on je.id = l.entry_id
            join public.company_account ca on ca.id = l.company_account_id
           where je.account_id = c.account_id and je.company_id = p_company and je.status in ('validado', 'anulado')
             and je.entry_date between v_desde and v_hasta and ca.code like '4751%'
             and je.source_type not in ('opening', 'closing')
             and not exists (select 1 from public.journal_line g join public.company_account gc on gc.id = g.company_account_id
                              where g.entry_id = je.id and gc.code ~ '^(10|11|12)')
           group by 1, 2) q;

  return jsonb_build_object('desde', v_desde, 'hasta', v_hasta, 'asientos', v_asientos, 'sumas', v_sumas,
                            'lineas_640', v_640, 'cuenta_621', round(v_621, 2), 'cuentas_4751', v_4751);
end $$;


--
-- Name: FUNCTION conta_impuesto_retenciones_diario(p_company uuid, p_year integer, p_period text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_retenciones_diario(p_company uuid, p_year integer, p_period text) IS 'I01g. Lo que dice el diario de las retenciones de un periodo: cada asiento con la 4751 (sin la apertura ni el pago a Hacienda) con su modelo (115, nómina, profesional o sin modelo), base, retenido y perceptor; las sumas; las líneas de la 640 de las nóminas; la 621 entera y el haber de cada subcuenta de la 4751. Solo lee.';


--
-- Name: conta_impuesto_revisar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_revisar(p_return uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; v_n int; v_avisos int;
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null then raise exception 'Esa declaración no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_gestionar(r.company_id) then
    raise exception 'Solo un administrador o un encargado de la empresa, o su asesoría con su consentimiento, revisa sus impuestos.' using errcode = '42501';
  end if;
  if r.status <> 'draft' then
    raise exception 'Solo se revisa un borrador, y esta declaración está «%».', public.conta_impuesto_estado_texto(r.status) using errcode = '22023';
  end if;
  select count(*) into v_n from public.tax_return_check where tax_return_id = r.id and result = 'error';
  if v_n > 0 then
    raise exception 'Tiene % % que Sumied no sabe resolver: no se puede dar por revisada.', v_n, case when v_n = 1 then 'cosa' else 'cosas' end using errcode = '22023';
  end if;
  select count(*) into v_avisos from public.tax_return_check where tax_return_id = r.id and result = 'warning' and accepted_at is null;
  update public.tax_return set status = 'reviewed', reviewed_at = now(), reviewed_by = auth.uid(), reviewed_by_name = public.conta_impuesto_quien(), updated_at = now()
   where id = r.id;
  return jsonb_build_object('ok', true, 'avisos_sin_aceptar', v_avisos,
    'mensaje', 'Revisado por ' || public.conta_impuesto_quien() || case when v_avisos > 0 then '. Quedan ' || v_avisos || ' avisos sin dar por buenos.' else '.' end);
end $$;


--
-- Name: conta_impuesto_sociedades(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_sociedades(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.company; v_200 jsonb; v_202 jsonb; v_hoy date := (now() at time zone 'Europe/Madrid')::date;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;

  -- Los 200, y lo que salió a devolver: cobrado cuando un asiento posterior abona la 4709 contra tesorería.
  select coalesce(jsonb_agg(jsonb_build_object(
           'ejercicio', f.fiscal_year, 'presentado', f.filed_on, 'base_imponible', f.taxable_base, 'cuota', f.quota,
           'resultado', f.result_kind, 'importe', f.result_amount, 'origen', f.origin, 'motivo', f.manual_reason, 'quien', f.written_by_name,
           'devolucion', case when f.result_kind = 'to_refund' then jsonb_build_object(
               'importe', f.result_amount, 'cobrado', coalesce(k.cobrado, 0), 'cobrado_el', k.ultimo, 'asiento', k.asiento,
               'pendiente', greatest(f.result_amount - coalesce(k.cobrado, 0), 0)) end)
           order by f.fiscal_year desc), '[]')
    into v_200
    from public.corporate_tax_filing f
    left join lateral (
      select sum(l.credit - l.debit) as cobrado, max(je.entry_date) as ultimo, (array_agg(je.id order by je.entry_date desc))[1] as asiento
        from public.journal_entry je
        join public.journal_line l on l.entry_id = je.id
        join public.company_account ca on ca.id = l.company_account_id
       where f.result_kind = 'to_refund' and je.account_id = c.account_id and je.company_id = p_company and je.status = 'validado'
         and je.entry_date >= f.filed_on and ca.code like '4709%' and l.credit > 0
         and exists (select 1 from public.journal_line l2 join public.company_account c2 on c2.id = l2.company_account_id
                      where l2.entry_id = je.id and c2.code like '57%' and l2.debit > 0)
    ) k on true
   where f.company_id = p_company;

  -- Los 202: los de los años con alguno en Sumied y el de este año, con el 200 del que salen.
  with anos as (
    select distinct fiscal_year y from public.tax_return where company_id = p_company and form_code = '202'
    union select extract(year from v_hoy)::int
  ), p as (
    select a.y, x.p, case when x.p = '1P' then a.y - 2 else a.y - 1 end as base_y
      from anos a cross join (values ('1P'), ('2P'), ('3P')) x(p)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'ejercicio', p.y, 'periodo', p.p, 'ejercicio_base', p.base_y,
           'plazo', coalesce(r.due_date, (select presentacion from public.conta_impuesto_plazo_si_hay('202', 'instalments_202', p.y, p.p))),
           'cuota_200', f.quota, 'esperado', case when f.id is not null then round(f.quota * 0.18, 2) end,
           'declaracion', case when r.id is not null then jsonb_build_object(
               'id', r.id, 'estado', r.status, 'estado_texto', public.conta_impuesto_estado_texto(r.status), 'resultado', r.result_kind,
               'importe', r.amount, 'no_hace_falta', r.not_required_reason,
               'c01', (select value from public.tax_return_box where tax_return_id = r.id and box = '01'),
               'c03', (select value from public.tax_return_box where tax_return_id = r.id and box = '03'),
               'origen', (select origin from public.tax_return_box where tax_return_id = r.id and box = '03')) end)
           order by p.y desc, p.p), '[]')
    into v_202
    from p
    left join public.tax_return r on r.company_id = p_company and r.form_code = '202' and r.fiscal_year = p.y and r.period = p.p and r.sequence = 1
    left join public.corporate_tax_filing f on f.company_id = p_company and f.fiscal_year = p.base_y;

  return jsonb_build_object('empresa', p_company, 'hoy', v_hoy, 'puede_gestionar', public.conta_impuesto_puede_gestionar(p_company),
                            'declaraciones_200', v_200, 'pagos_202', v_202);
end $$;


--
-- Name: FUNCTION conta_impuesto_sociedades(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_sociedades(p_company uuid) IS 'I01h. Solo lee. La pestaña «Impuesto de sociedades»: los 200 guardados (con lo que queda por cobrar de los que salieron a devolver: cobrado cuando un asiento validado posterior abona la 4709 contra tesorería) y los 202 de los años que tienen alguno, con el 200 del que salen y lo que daría.';


--
-- Name: conta_impuesto_trimestre(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_impuesto_trimestre(p_company uuid, p_year integer, p_quarter integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_hechos constant text[] := array['filed', 'booked', 'paid', 'offset', 'refunded'];
  v_q text; v_meses text[]; v_202 text;
  v_modelos jsonb; v_filas jsonb;
  v_ant public.tax_return; v_ant_y int; v_ant_p text;
  v_esperada numeric; v_esperada_de text;
  v_inicio numeric; v_inicio_de text; v_110_1t numeric; v_desde date;
  v_borr public.tax_return; v_b110 numeric; v_b110_origen text; v_desfasada boolean := false;
begin
  if not exists (select 1 from public.company where id = p_company) then
    raise exception 'Esa empresa no está.' using errcode = 'P0002';
  end if;
  if not public.conta_impuesto_puede_ver(p_company) then
    raise exception 'No puedes ver los impuestos de esta empresa.' using errcode = '42501';
  end if;
  if p_quarter is null or p_quarter not between 1 and 4 then
    raise exception 'El trimestre es del 1 al 4.' using errcode = '22023';
  end if;
  if p_year is null or p_year < 2000 or p_year > extract(year from now())::int + 1 then
    raise exception 'El ejercicio «%» no es un año que se pueda mirar.', p_year using errcode = '22023';
  end if;

  v_q := p_quarter || 'T';
  v_meses := array[lpad(((p_quarter - 1) * 3 + 1)::text, 2, '0'), lpad(((p_quarter - 1) * 3 + 2)::text, 2, '0'), lpad(((p_quarter - 1) * 3 + 3)::text, 2, '0')];
  -- El 202 que se paga con el trimestre: el 1P en abril (tras el 1T), el 2P en
  -- octubre (tras el 3T) y el 3P en diciembre (en el 4T). En el 2T no toca.
  v_202 := case p_quarter when 1 then '1P' when 3 then '2P' when 4 then '3P' end;

  -- ── La tira: cada modelo que la empresa presenta, con lo que le toca este trimestre ──
  with o as (
    select o.form_code, o.cadence from public.tax_obligation o
     where o.company_id = p_company and o.valid_to is null and o.active and o.cadence <> 'annual'
  ), p as (
    select o.form_code, o.cadence, x.per
      from o cross join lateral unnest(case o.cadence
             when 'quarterly' then array[v_q]
             when 'monthly' then v_meses
             when 'instalments_202' then case when v_202 is null then array[null::text] else array[v_202] end end) x(per)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'modelo', p.form_code, 'nombre', f.name, 'cadencia', p.cadence, 'periodo', p.per,
           -- Un modelo que presenta y no toca este trimestre se dice (regla 7): el 202 en el 2T.
           'no_toca', p.per is null,
           'presentacion', pl.presentacion, 'domiciliacion', pl.domiciliacion,
           'declaracion', case when r.id is null then null else jsonb_build_object(
             'id', r.id, 'cuenta', r.account_id, 'estado', r.status, 'estado_texto', public.conta_impuesto_estado_texto(r.status),
             'resultado', r.result_kind, 'importe', r.amount,
             'presentada', r.filed_at, 'presentada_por', r.filed_by_name, 'por', r.filed_via,
             'csv', r.aeat_csv, 'justificante', r.aeat_receipt_number, 'justificante_pdf', r.receipt_document_path,
             'traido', r.receipt_source = 'aeat_csv', 'expediente', r.aeat_expediente,
             'presentador', case when r.presenter_tax_id is not null or r.presenter_name is not null
                                 then jsonb_build_object('nif', r.presenter_tax_id, 'nombre', r.presenter_name) end,
             'casillas', (select coalesce(jsonb_agg(jsonb_build_object('casilla', b.box, 'valor', b.value, 'texto', b.value_text,
                                                                       'origen', b.origin, 'motivo', b.manual_reason)
                                                    order by length(b.box), b.box), '[]')
                            from public.tax_return_box b where b.tax_return_id = r.id)) end
         ) order by case p.form_code when '303' then 1 when '111' then 2 when '115' then 3 when '202' then 4 else 5 end, p.form_code, p.per), '[]')
    into v_modelos
    from p join public.tax_form f on f.code = p.form_code
    left join lateral public.conta_impuesto_plazo_si_hay(p.form_code, p.cadence, p_year, p.per) pl on p.per is not null
    left join public.tax_return r on p.per is not null and r.company_id = p_company and r.form_code = p.form_code
                                  and r.fiscal_year = p_year and r.period = p.per and r.sequence = 1;

  -- ── La cartera del 303: los cuatro trimestres del año, con [110], [78] y [87] ──
  select coalesce(jsonb_agg(jsonb_build_object(
           'periodo', q.per, 'declaracion', r.id, 'estado', r.status,
           'presentada', r.status = any (v_hechos),
           'resultado', r.result_kind, 'importe', r.amount,
           'c110', (select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '110'),
           'c78', (select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '78'),
           'c87', (select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '87'),
           'origen110', (select b.origin from public.tax_return_box b where b.tax_return_id = r.id and b.box = '110'))
         order by q.per), '[]')
    into v_filas
    from unnest(array['1T', '2T', '3T', '4T']) q(per)
    left join public.tax_return r on r.company_id = p_company and r.form_code = '303' and r.fiscal_year = p_year
                                  and r.period = q.per and r.sequence = 1;

  -- Lo que quedaba al empezar el año (I01d, 0420): lo que dejó el 4T del año
  -- anterior presentado ([87] más lo que salió a compensar), que es de donde
  -- sale; si ese 4T no está, la [110] del 1T presentado, y se dice de cuál. Si
  -- están los dos, la [110] del 1T va al lado, para ver si casan. Si no hay
  -- ninguno, no se sabe.
  select * into v_ant from public.tax_return
   where company_id = p_company and form_code = '303' and fiscal_year = p_year - 1 and period = '4T' and sequence = 1 and status = any (v_hechos);
  if v_ant.id is not null then
    v_inicio := coalesce((select b.value from public.tax_return_box b where b.tax_return_id = v_ant.id and b.box = '87'), 0)
              + case when v_ant.result_kind = 'to_offset' then v_ant.amount else 0 end;
    v_inicio_de := '4T/' || (p_year - 1);
  end if;
  select * into v_ant from public.tax_return
   where company_id = p_company and form_code = '303' and fiscal_year = p_year and period = '1T' and sequence = 1 and status = any (v_hechos);
  if v_ant.id is not null then
    v_110_1t := (select b.value from public.tax_return_box b where b.tax_return_id = v_ant.id and b.box = '110');
    if v_inicio is null and v_110_1t is not null then
      v_inicio := v_110_1t;
      v_inicio_de := '1T/' || p_year;
    end if;
  end if;

  -- Desde cuándo lleva aquí sus impuestos (como el calendario): lo presentado
  -- antes se presentó fuera y, si no está, está «sin cargar».
  select min(valid_from) into v_desde from public.tax_obligation where company_id = p_company and valid_to is null and active;

  -- La [110] que le toca al trimestre: lo que dejó el 303 inmediatamente
  -- anterior presentado (como lo calcula conta_impuesto_303_calcular, 0240).
  v_ant_y := case when p_quarter = 1 then p_year - 1 else p_year end;
  v_ant_p := case when p_quarter = 1 then '4T' else (p_quarter - 1) || 'T' end;
  select * into v_ant from public.tax_return
   where company_id = p_company and form_code = '303' and fiscal_year = v_ant_y and period = v_ant_p and sequence = 1 and status = any (v_hechos);
  if v_ant.id is not null then
    v_esperada := coalesce((select b.value from public.tax_return_box b where b.tax_return_id = v_ant.id and b.box = '87'), 0)
                + case when v_ant.result_kind = 'to_offset' then v_ant.amount else 0 end;
    v_esperada_de := v_ant_p || '/' || v_ant_y;
  end if;

  -- ¿El borrador del trimestre está desfasado? Solo si se calculó solo (una
  -- [110] escrita a mano la decidió una persona) y no es la que le toca.
  select * into v_borr from public.tax_return
   where company_id = p_company and form_code = '303' and fiscal_year = p_year and period = v_q and sequence = 1
     and status in ('draft', 'reviewed');
  if v_borr.id is not null then
    select b.value, b.origin into v_b110, v_b110_origen from public.tax_return_box b where b.tax_return_id = v_borr.id and b.box = '110';
    v_desfasada := v_esperada is not null and coalesce(v_b110_origen, 'calculated') <> 'manual'
                   and (v_b110 is null or abs(v_b110 - v_esperada) >= 0.005);
  end if;

  return jsonb_build_object(
    'empresa', (select jsonb_build_object('id', c.id, 'nombre', coalesce(nullif(c.trade_name, ''), c.legal_name), 'razon_social', c.legal_name, 'nif', c.tax_id)
                  from public.company c where c.id = p_company),
    'ejercicio', p_year, 'trimestre', v_q, 'desde', v_desde,
    'puede_gestionar', public.conta_impuesto_puede_gestionar(p_company),
    'modelos', v_modelos,
    'cartera', jsonb_build_object(
      'filas', v_filas,
      'pendiente_al_empezar', case when v_inicio is null then null else jsonb_build_object('importe', v_inicio, 'de', v_inicio_de,
                                'c110_1t', case when v_inicio_de like '4T/%' then v_110_1t end) end,
      'esperada_110', case when v_esperada is null then null else jsonb_build_object('importe', v_esperada, 'de', v_esperada_de) end,
      'borrador', case when v_borr.id is null then null else jsonb_build_object('id', v_borr.id, 'estado', v_borr.status, 'c110', v_b110, 'origen110', v_b110_origen) end,
      'desfasada', v_desfasada));
end $$;


--
-- Name: FUNCTION conta_impuesto_trimestre(p_company uuid, p_year integer, p_quarter integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_impuesto_trimestre(p_company uuid, p_year integer, p_quarter integer) IS 'I01c (0280). Lo que pinta Impuestos › Trimestre (maqueta_303_v2): los modelos del trimestre con su declaración, casillas y justificante, y la cartera de cuotas a compensar del 303 ([110], [78], [87]) de los cuatro trimestres del año; y si el borrador del trimestre tiene la [110] desfasada respecto al 303 anterior presentado. No escribe nada.';


--
-- Name: conta_intermediario_asegurar(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_intermediario_asegurar(p_company uuid, p_provider text, p_canal uuid DEFAULT NULL::uuid, p_nombre text DEFAULT NULL::text, p_nif text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_prov text := lower(btrim(coalesce(p_provider, ''))); v_r public.party_role; v_party uuid; v_nombre text; v_cada text; v_dias int;
  v_nif text := nullif(upper(regexp_replace(coalesce(p_nif, ''), '[^A-Za-z0-9]', '', 'g')), '');
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta da de alta a quien le paga.' using errcode = '42501';
  end if;
  if p_canal is not null then
    select * into v_r from public.party_role where account_id = v_acc and role = 'platform' and channel_id = p_canal order by created_at limit 1;
    if v_r.id is not null then return v_r.id; end if;
  end if;
  if v_nif is not null then
    select pr.* into v_r from public.party_role pr join public.party p on p.id = pr.party_id
     where pr.account_id = v_acc and pr.role = 'platform' and upper(regexp_replace(coalesce(p.tax_id, ''), '[^A-Za-z0-9]', '', 'g')) = v_nif
     order by pr.created_at limit 1;
    if v_r.id is not null then
      if v_r.channel_id is null and p_canal is not null then update public.party_role set channel_id = p_canal where id = v_r.id; end if;
      return v_r.id;
    end if;
  end if;
  v_nombre := coalesce(nullif(btrim(p_nombre), ''), case v_prov when 'uber' then 'Uber Eats' when 'glovo' then 'Glovo' when 'justeat' then 'Just Eat' else initcap(v_prov) end);
  if p_canal is null and v_nif is null then
    select pr.* into v_r from public.party_role pr join public.party p on p.id = pr.party_id
     where pr.account_id = v_acc and pr.role = 'platform' and lower(btrim(p.name)) = lower(v_nombre) order by pr.created_at limit 1;
    if v_r.id is not null then return v_r.id; end if;
  end if;
  if v_nif is not null then
    select id into v_party from public.party where account_id = v_acc and archived_at is null
       and upper(regexp_replace(coalesce(tax_id, ''), '[^A-Za-z0-9]', '', 'g')) = v_nif order by created_at limit 1;
  end if;
  if v_party is null then
    insert into public.party (account_id, name, tax_id, source, created_by, created_by_name)
    -- source: los valores de party_source_check (manual, supplier, migrated, ticket); quién lo dio de alta va en created_by_name.
    values (v_acc, v_nombre, v_nif, 'manual', auth.uid(), 'Sumied · su primera liquidación' || coalesce(' (' || nullif(btrim(p_quien_nombre), '') || ')', ''))
    returning id into v_party;
  end if;
  select cada, dias into v_cada, v_dias from (values ('uber', 'weekly', 1), ('glovo', 'fortnightly', 20), ('justeat', 'fortnightly', 4)) k(prov, cada, dias) where k.prov = v_prov;
  insert into public.party_role (account_id, party_id, role, channel_id, settlement_every, payout_days_after, created_by)
  values (v_acc, v_party, 'platform', p_canal, v_cada, v_dias, auth.uid())
  returning * into v_r;
  return v_r.id;
end $$;


--
-- Name: FUNCTION conta_intermediario_asegurar(p_company uuid, p_provider text, p_canal uuid, p_nombre text, p_nif text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_intermediario_asegurar(p_company uuid, p_provider text, p_canal uuid, p_nombre text, p_nif text, p_quien_nombre text) IS 'V02 · E2. El papel de intermediario (party_role platform) de quien te paga; si no lo hay, lo da de alta con su primera liquidación, con el calendario de su plataforma si se conoce.';


--
-- Name: conta_interruptor_cambiar(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_interruptor_cambiar(p_account uuid, p_clave text, p_encender boolean, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_motivo  text := trim(coalesce(p_motivo, ''));
  v_cuenta  text;
  v_claves  text[];
  v_clave   text;
  v_antes   boolean;
  v_hechos  jsonb := '[]'::jsonb;
begin
  if not public.current_user_is_admin() then
    raise exception 'Solo un administrador de la plataforma enciende o apaga Sumied en una cuenta.' using errcode = '42501';
  end if;
  if p_clave is null or p_clave not in ('conta', 'conta_impuestos', 'conta_laboral') then
    raise exception 'Ese interruptor no es de Sumied: %.', coalesce(p_clave, '(ninguno)') using errcode = '22023';
  end if;
  if p_encender is null then
    raise exception 'Falta si se enciende o se apaga.' using errcode = '22023';
  end if;
  if v_motivo = '' then
    raise exception 'Falta el motivo: una línea, que queda en la auditoría.' using errcode = '22023';
  end if;
  select name into v_cuenta from accounts where id = p_account;
  if v_cuenta is null then
    raise exception 'No existe esa cuenta.' using errcode = '22023';
  end if;

  if p_encender and p_clave <> 'conta'
     and not exists (select 1 from feature_flags where account_id = p_account and feature_key = 'conta' and enabled) then
    raise exception 'Enciende antes la contabilidad.' using errcode = '22023';
  end if;

  -- Apagar la contabilidad apaga las tres; lo demás, solo la suya.
  v_claves := case when not p_encender and p_clave = 'conta'
                   then array['conta', 'conta_impuestos', 'conta_laboral'] else array[p_clave] end;

  foreach v_clave in array v_claves loop
    select enabled into v_antes from feature_flags where account_id = p_account and feature_key = v_clave;
    v_antes := coalesce(v_antes, false);
    continue when v_antes = p_encender;

    insert into feature_flags (account_id, feature_key, enabled, source, granted_by, grant_reason)
    values (p_account, v_clave, p_encender, 'manual_grant', auth.uid(), v_motivo)
    on conflict (account_id, feature_key) do update
       set enabled = excluded.enabled, source = 'manual_grant', granted_by = excluded.granted_by,
           grant_reason = excluded.grant_reason, expires_at = null;

    perform public.log_platform_event('account_feature_changed', p_account, null,
      jsonb_build_object('interruptor', v_clave, 'de', v_antes, 'a', p_encender, 'motivo', v_motivo,
                         'por', case when v_clave = p_clave then 'pedido' else 'al apagar la contabilidad' end));

    v_hechos := v_hechos || jsonb_build_object('clave', v_clave, 'de', v_antes, 'a', p_encender);
  end loop;

  return jsonb_build_object('cuenta', v_cuenta, 'cambiados', v_hechos);
end;
$$;


--
-- Name: FUNCTION conta_interruptor_cambiar(p_account uuid, p_clave text, p_encender boolean, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_interruptor_cambiar(p_account uuid, p_clave text, p_encender boolean, p_motivo text) IS 'S01f · Enciende o apaga un interruptor de Sumied (conta, conta_impuestos, conta_laboral) con su motivo y su apunte en platform_audit_log. Apagar conta apaga los tres. Solo administrador de la plataforma.';


--
-- Name: conta_interruptores_de_cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_interruptores_de_cuenta(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lista jsonb;
  v_datos jsonb;
begin
  if not public.current_user_is_admin() then
    raise exception 'Solo un administrador de la plataforma ve los interruptores de una cuenta.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'clave', c.clave,
           'encendida', coalesce(f.enabled, false),
           'existe', f.account_id is not null,
           'cambiada', f.updated_at,
           'quien', pa.full_name,
           'motivo', nullif(trim(f.grant_reason), '')
         ) order by c.orden), '[]'::jsonb)
    into v_lista
    from (values ('conta', 1), ('conta_impuestos', 2), ('conta_laboral', 3)) as c(clave, orden)
    left join feature_flags f on f.account_id = p_account and f.feature_key = c.clave
    left join lateral (select full_name from platform_admins where user_id = f.granted_by order by active desc limit 1) pa on true;

  -- Lo que se deja de ver al apagar la contabilidad (regla 9: todo por account_id).
  select jsonb_build_object(
           'asientos', (select count(*) from journal_entry where account_id = p_account),
           'facturas_recibidas', (select count(*) from supplier_invoice where account_id = p_account),
           'impuestos', (select count(*) from tax_return where account_id = p_account))
    into v_datos;

  return jsonb_build_object('interruptores', v_lista, 'datos', v_datos);
end;
$$;


--
-- Name: FUNCTION conta_interruptores_de_cuenta(p_account uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_interruptores_de_cuenta(p_account uuid) IS 'S01f · Los interruptores de Sumied de una cuenta (encendido, desde cuándo, quién y por qué) y lo que tiene dentro. Solo administrador de la plataforma.';


--
-- Name: conta_iva_periodo_de(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_periodo_de(p_cadencia text, p_fecha date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when p_cadencia = 'monthly' then to_char(p_fecha, 'MM')
              else ((extract(month from p_fecha)::int - 1) / 3 + 1)::text || 'T' end
$$;


--
-- Name: conta_iva_periodo_frase(text, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_periodo_frase(p_prep text, p_periodo text, p_ejercicio integer, p_con_anio boolean DEFAULT true) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select case when p_periodo ~ '^[1-4]T$'
              then case p_prep when 'de' then 'del ' when 'a' then 'al ' when 'en' then 'en el ' else 'El ' end
                   || public.conta_iva_periodo_nombre(p_periodo, p_ejercicio, p_con_anio)
              when p_prep = 'el' then initcap(public.conta_iva_periodo_nombre(p_periodo, p_ejercicio, p_con_anio))
              else p_prep || ' ' || public.conta_iva_periodo_nombre(p_periodo, p_ejercicio, p_con_anio) end
$_$;


--
-- Name: conta_iva_periodo_nombre(text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_periodo_nombre(p_periodo text, p_ejercicio integer, p_con_anio boolean DEFAULT true) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select case when p_periodo ~ '^[1-4]T$' then p_periodo
              else (array['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'])[p_periodo::int] end
         || case when p_con_anio then ' de ' || p_ejercicio else '' end
$_$;


--
-- Name: conta_iva_presentado(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_presentado(p_company uuid, p_fecha date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  select jsonb_build_object('id', r.id, 'ejercicio', r.fiscal_year, 'periodo', r.period, 'cadencia', r.cadence,
                            'desde', f.desde, 'hasta', f.hasta,
                            'presentado', coalesce(r.filed_at, r.updated_at), 'secuencia', r.sequence)
    from public.tax_return r
   cross join lateral public.conta_impuesto_periodo_fechas(r.fiscal_year, r.period) f
   where p_fecha is not null and r.company_id = p_company and r.form_code = '303'
     and r.fiscal_year = extract(year from p_fecha)::int
     and r.period ~ '^([1-4]T|0[1-9]|1[0-2])$'
     and r.status in ('filed', 'booked', 'paid', 'offset', 'refunded')
     and p_fecha between f.desde and f.hasta
     -- V04 (1408): reabierto para corregir, el periodo no está cerrado hasta su nueva presentación.
     and not exists (select 1 from public.vat_reopening o where o.company_id = p_company and o.fiscal_year = r.fiscal_year
                       and o.period = r.period and o.closed_at is null)
   -- La última presentada: su fecha es la que dice el mensaje.
   order by r.sequence desc, r.filed_at desc nulls last
   limit 1
$_$;


--
-- Name: FUNCTION conta_iva_presentado(p_company uuid, p_fecha date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_iva_presentado(p_company uuid, p_fecha date) IS 'V04 · candado del IVA (1233; 1408: lo reabierto no está cerrado). El último 303 presentado (filed, booked, paid, offset o refunded) que cubre esa fecha, o null. El único sitio que decide si el IVA de un día está cerrado.';


--
-- Name: conta_iva_presentado_mensaje(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_presentado_mensaje(p_company uuid, p_presentado jsonb, p_que text DEFAULT 'factura'::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_sig date; v_texto text;
begin
  v_texto := format('El IVA %s ya está presentado (%s). No se puede cambiar.',
                    public.conta_iva_periodo_frase('de', p_presentado->>'periodo', (p_presentado->>'ejercicio')::int),
                    to_char(((p_presentado->>'presentado')::timestamptz at time zone 'Europe/Madrid')::date, 'DD/MM'));
  v_sig := public.conta_primer_dia_iva_abierto(p_company, (p_presentado->>'hasta')::date + 1);
  if v_sig is null then
    return v_texto || ' No hay un periodo abierto donde llevarlo.';
  end if;
  return v_texto || case when p_que = 'corregir' then ' Lo que haya que corregir va ' else ' Esta factura va ' end
         || public.conta_iva_periodo_frase('a', public.conta_iva_periodo_de(p_presentado->>'cadencia', v_sig), extract(year from v_sig)::int,
                                           extract(year from v_sig)::int <> (p_presentado->>'ejercicio')::int) || '.';
end $$;


--
-- Name: conta_iva_presentados(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_presentados(p_company uuid, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  -- Quien es de la cuenta, o quien ve sus impuestos (su asesoría, con su consentimiento).
  if v_cuenta is null or not (v_cuenta = any ((select public.current_user_account_ids())::uuid[]) or public.conta_impuesto_puede_ver(p_company)) then
    raise exception 'No puedes ver esta empresa.' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('periodo', r.period, 'ejercicio', r.fiscal_year, 'desde', f.desde, 'hasta', f.hasta,
                                        'presentado', coalesce(u.filed_at, u.updated_at), 'declaracion', u.id,
                                        'nombre', public.conta_iva_periodo_nombre(r.period, r.fiscal_year),
                                        'siguiente', public.conta_iva_periodo_nombre(
                                            public.conta_iva_periodo_de(r.cadence, coalesce(public.conta_primer_dia_iva_abierto(p_company, f.hasta + 1), f.hasta + 1)),
                                            extract(year from coalesce(public.conta_primer_dia_iva_abierto(p_company, f.hasta + 1), f.hasta + 1))::int,
                                            extract(year from coalesce(public.conta_primer_dia_iva_abierto(p_company, f.hasta + 1), f.hasta + 1))::int <> r.fiscal_year),
                                        -- V04 (1408): reabierto para corregir (sin candado hasta su nueva presentación).
                                        'reabierto', (select jsonb_build_object('id', o.id, 'motivo', o.reason, 'desde', o.opened_at, 'por', o.opened_by_name,
                                                                                'tipo', o.kind, 'secuencia', (select n.sequence from public.tax_return n where n.id = o.new_return_id))
                                                        from public.vat_reopening o where o.company_id = p_company and o.fiscal_year = r.fiscal_year
                                                         and o.period = r.period and o.closed_at is null))
                     order by f.desde)
      from public.tax_return r
     cross join lateral public.conta_impuesto_periodo_fechas(r.fiscal_year, r.period) f
     cross join lateral (select x.* from public.tax_return x where x.company_id = r.company_id and x.form_code = '303' and x.fiscal_year = r.fiscal_year
                           and x.period = r.period and x.status in ('filed', 'booked', 'paid', 'offset', 'refunded')
                         order by x.sequence desc limit 1) u
     where r.company_id = p_company and r.form_code = '303' and r.fiscal_year = p_year and r.sequence = 1
       and r.period ~ '^([1-4]T|0[1-9]|1[0-2])$'
       and r.status in ('filed', 'booked', 'paid', 'offset', 'refunded')), '[]'::jsonb);
end $_$;


--
-- Name: FUNCTION conta_iva_presentados(p_company uuid, p_year integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_iva_presentados(p_company uuid, p_year integer) IS 'V04 · candado del IVA (1233; 1408: con «reabierto» y la fecha de la última presentada). Los periodos con el 303 presentado de un ejercicio. Para el candado de las pantallas; quien manda es la base (conta_iva_presentado).';


--
-- Name: conta_iva_puede_reabrir(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_puede_reabrir(p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.company c where c.id = p_company and public.current_user_is_admin_of(c.account_id))
      or exists (select 1 from public.company_tax_presenter t
                  where t.company_id = p_company and t.mode = 'advisor' and t.consented_at is not null and t.revoked_at is null
                    and public.current_user_is_admin_or_manager_of(t.advisor_account_id))
$$;


--
-- Name: conta_iva_reabierto(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_reabierto(p_company uuid, p_fecha date) RETURNS public.vat_reopening
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.* from public.vat_reopening o
   cross join lateral public.conta_impuesto_periodo_fechas(o.fiscal_year, o.period) f
   where p_fecha is not null and o.company_id = p_company and o.closed_at is null and p_fecha between f.desde and f.hasta
   limit 1
$$;


--
-- Name: conta_iva_reabrir(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_reabrir(p_return uuid, p_motivo text, p_tipo text DEFAULT 'complementary'::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.tax_return; v_ultima public.tax_return; v_nueva uuid; v_seq smallint; v_id uuid; v_nombre text;
begin
  select * into r from public.tax_return where id = p_return for update;
  if r.id is null or r.form_code <> '303' then raise exception 'Esa declaración no es un 303.' using errcode = 'P0002'; end if;
  if not public.conta_iva_puede_reabrir(r.company_id) then
    raise exception 'Solo el administrador de la empresa o su gestor reabren un periodo presentado.' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_motivo, ''))) < 10 then
    raise exception 'Escribe por qué se reabre (al menos diez letras): queda en cada asiento que se cambie.' using errcode = '23514';
  end if;
  if coalesce(p_tipo, 'complementary') not in ('complementary', 'substitutive') then
    raise exception 'La nueva presentación es complementaria o sustitutiva.' using errcode = '22023';
  end if;
  -- Nada reabierto ya, y la última del periodo, presentada.
  if exists (select 1 from public.vat_reopening o where o.company_id = r.company_id and o.fiscal_year = r.fiscal_year and o.period = r.period and o.closed_at is null) then
    raise exception 'El % de % ya está reabierto para corregir.', public.conta_iva_periodo_nombre(r.period, r.fiscal_year, false), r.fiscal_year using errcode = '23505';
  end if;
  select * into v_ultima from public.tax_return
   where company_id = r.company_id and form_code = '303' and fiscal_year = r.fiscal_year and period = r.period
   order by sequence desc limit 1;
  if v_ultima.status not in ('filed', 'booked', 'paid', 'offset', 'refunded') then
    raise exception 'El 303 % de % no está presentado: no hay nada que reabrir.', r.period, r.fiscal_year using errcode = '22023';
  end if;
  v_seq := v_ultima.sequence + 1;
  v_nombre := coalesce(p_quien_nombre, public.conta_impuesto_quien());
  insert into public.tax_return (account_id, company_id, obligation_id, form_code, fiscal_year, cadence, period, sequence, kind, replaces_return_id, due_date, status)
  values (r.account_id, r.company_id, r.obligation_id, r.form_code, r.fiscal_year, r.cadence, r.period, v_seq, coalesce(p_tipo, 'complementary'), v_ultima.id, r.due_date, 'draft')
  returning id into v_nueva;
  insert into public.vat_reopening (account_id, company_id, fiscal_year, period, original_return_id, new_return_id, kind, reason, opened_by, opened_by_name)
  values (r.account_id, r.company_id, r.fiscal_year, r.period, v_ultima.id, v_nueva, coalesce(p_tipo, 'complementary'), btrim(p_motivo), auth.uid(), v_nombre)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'nueva', v_nueva, 'secuencia', v_seq,
    'texto', format('Reabierto el %s de %s para corregir. La presentación del %s se queda como estaba: lo que cambies irá en la %s nº %s.',
                    public.conta_iva_periodo_nombre(r.period, r.fiscal_year, false), r.fiscal_year,
                    to_char((coalesce(v_ultima.filed_at, v_ultima.updated_at) at time zone 'Europe/Madrid')::date, 'DD/MM'),
                    case when coalesce(p_tipo, 'complementary') = 'complementary' then 'complementaria' else 'sustitutiva' end, v_seq));
end $$;


--
-- Name: FUNCTION conta_iva_reabrir(p_return uuid, p_motivo text, p_tipo text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_iva_reabrir(p_return uuid, p_motivo text, p_tipo text, p_quien_nombre text) IS 'V04 · Reabrir para corregir (1408). Reabre un periodo con el 303 presentado (el administrador o el gestor, con motivo): crea la nueva declaración (sequence + 1, complementaria o sustitutiva, replaces_return_id → la última presentada) y deja la original como estaba.';


--
-- Name: conta_iva_reapertura_presentada(uuid, text, timestamp with time zone, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_reapertura_presentada(p_reopening uuid, p_csv text, p_fecha timestamp with time zone, p_resultado text, p_importe numeric, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare o public.vat_reopening; v_csv text := upper(btrim(coalesce(p_csv, ''))); v_nombre text;
begin
  select * into o from public.vat_reopening where id = p_reopening for update;
  if o.id is null then raise exception 'Esa reapertura no está.' using errcode = 'P0002'; end if;
  if not public.conta_iva_puede_reabrir(o.company_id) then
    raise exception 'Solo el administrador de la empresa o su gestor apuntan la nueva presentación.' using errcode = '42501';
  end if;
  if o.closed_at is not null then raise exception 'Esta reapertura ya está cerrada.' using errcode = '22023'; end if;
  if v_csv !~ '^[A-Z0-9]{16}$' then raise exception 'El CSV de Hacienda son 16 letras y números.' using errcode = '22023'; end if;
  if p_resultado not in ('to_pay', 'to_refund', 'to_offset', 'zero', 'no_activity') then raise exception 'Di el resultado de la nueva presentación.' using errcode = '22023'; end if;
  if p_resultado in ('zero', 'no_activity') and coalesce(p_importe, 0) <> 0 or p_resultado not in ('zero', 'no_activity') and coalesce(p_importe, 0) <= 0 then
    raise exception 'El importe no casa con el resultado.' using errcode = '22023';
  end if;
  v_nombre := coalesce(p_quien_nombre, public.conta_impuesto_quien());
  update public.tax_return set status = 'filed', result_kind = p_resultado, amount = coalesce(p_importe, 0), filed_at = coalesce(p_fecha, now()),
         filed_by = auth.uid(), filed_by_name = v_nombre, filed_via = 'outside', aeat_csv = v_csv, updated_at = now()
   where id = o.new_return_id;
  return jsonb_build_object('ok', true, 'texto', format('Apuntada la %s nº %s del %s de %s (CSV %s). El periodo vuelve a estar cerrado.',
    case when o.kind = 'complementary' then 'complementaria' else 'sustitutiva' end,
    (select sequence from public.tax_return where id = o.new_return_id),
    public.conta_iva_periodo_nombre(o.period, o.fiscal_year, false), o.fiscal_year, v_csv));
end $_$;


--
-- Name: conta_iva_reaperturas(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_reaperturas(p_company uuid, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not (v_cuenta = any ((select public.current_user_account_ids())::uuid[]) or public.conta_impuesto_puede_ver(p_company)) then
    raise exception 'No puedes ver esta empresa.' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', o.id, 'periodo', o.period, 'ejercicio', o.fiscal_year, 'tipo', o.kind, 'motivo', o.reason,
             'abierta', o.opened_at, 'por', o.opened_by_name, 'cerrada', o.closed_at, 'cerrada_por', o.closed_by_name,
             'dias', extract(day from coalesce(o.closed_at, now()) - o.opened_at)::int,
             'original', jsonb_build_object('id', a.id, 'secuencia', a.sequence, 'estado', a.status, 'presentada', a.filed_at, 'csv', a.aeat_csv, 'importe', a.amount, 'resultado', a.result_kind),
             'nueva', jsonb_build_object('id', n.id, 'secuencia', n.sequence, 'estado', n.status, 'presentada', n.filed_at, 'csv', n.aeat_csv, 'importe', n.amount, 'resultado', n.result_kind),
             'asientos', (select count(distinct m.entry_id) from public.vat_reopening_entry m where m.reopening_id = o.id))
           order by o.opened_at)
      from public.vat_reopening o
      join public.tax_return a on a.id = o.original_return_id
      join public.tax_return n on n.id = o.new_return_id
     where o.company_id = p_company and o.fiscal_year = p_year), '[]'::jsonb);
end $$;


--
-- Name: conta_iva_reaperturas_recordar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_iva_reaperturas_recordar() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare o record; n int := 0;
begin
  for o in select v.*, coalesce(nullif(c.trade_name, ''), c.legal_name) as empresa from public.vat_reopening v join public.company c on c.id = v.company_id
            where v.closed_at is null and v.opened_at < now() - interval '30 days'
              and (v.reminded_at is null or v.reminded_at < now() - interval '7 days') loop
    begin
      perform public.encolar_alerta(
        p_kind            => 'iva_reabierto_sin_presentar',
        p_subject         => 'Un trimestre reabierto sin presentar',
        p_message         => format('El %s de %s de %s lleva %s días reabierto para corregir y sin presentar. Presenta la %s y apúntala en Impuestos.',
                               public.conta_iva_periodo_nombre(o.period, o.fiscal_year, false), o.fiscal_year, o.empresa,
                               extract(day from now() - o.opened_at)::int, case when o.kind = 'complementary' then 'complementaria' else 'sustitutiva' end),
        p_debounce_kind   => 'iva_reabierto:' || o.id::text,
        p_debounce_window => interval '7 days',
        p_account_id      => o.account_id,
        p_location_id     => null,
        p_brand_id        => null,
        p_severity        => 'aviso');
      update public.vat_reopening set reminded_at = now() where id = o.id;
      n := n + 1;
    exception when others then
      raise notice 'iva_reabierto_sin_presentar: no se pudo encolar el aviso (%)', sqlerrm;
    end;
  end loop;
  return n;
end $$;


--
-- Name: conta_json_seguro(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_json_seguro(p text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
begin
  return p::jsonb;
exception when others then
  return null;
end $$;


--
-- Name: conta_lectura_proveedor_releida(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lectura_proveedor_releida(p_invoice uuid, p_session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_f public.supplier_invoice;
  v_s record;
  v_quien text := coalesce(public.conta_nombre_actor(), 'Sumied');
  v_antes jsonb; v_leido jsonb; v_nuevo jsonb; v_puesto text[] := '{}';
  k text;
begin
  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Esa factura no está, o no puedes revisarla.' using errcode = 'P0002';
  end if;
  if v_f.raw_document_url is null then raise exception 'Esta factura no tiene PDF guardado: no hay nada que volver a leer.' using errcode = '22023'; end if;
  select s.id, s.input_files, s.validation into v_s from public.goods_receipt_ai_session s where s.id = p_session and s.account_id = v_f.account_id;
  if v_s.id is null then raise exception 'Esa lectura no está.' using errcode = 'P0002'; end if;
  if not exists (select 1 from jsonb_array_elements(coalesce(v_s.input_files, '[]'::jsonb)) x where x->>'path' = v_f.raw_document_url) then
    raise exception 'Esa lectura no es del PDF de esta factura.' using errcode = '23514';
  end if;
  v_leido := v_s.validation->'factura'->'factura'->'proveedor';
  if v_leido is null or jsonb_typeof(v_leido) <> 'object' then raise exception 'La lectura no ha sacado nada del proveedor.' using errcode = '22023'; end if;

  v_antes := coalesce(v_f.reading->'factura'->'proveedor', '{}'::jsonb);
  v_nuevo := v_antes;
  -- Solo lo que faltaba (o venía vacío): nombre y NIF no se tocan nunca.
  foreach k in array array['telefono', 'web', 'email', 'direccion'] loop
    if nullif(btrim(coalesce(v_antes->>k, '')), '') is null and nullif(btrim(coalesce(v_leido->>k, '')), '') is not null then
      v_nuevo := v_nuevo || jsonb_build_object(k, v_leido->>k);
      v_puesto := v_puesto || k;
    end if;
  end loop;
  -- Las claves nuevas, siempre: vacías si la factura no las trae (ya está leída con el lector de hoy).
  if not (v_nuevo ? 'telefono') then v_nuevo := v_nuevo || jsonb_build_object('telefono', null); end if;
  if not (v_nuevo ? 'web') then v_nuevo := v_nuevo || jsonb_build_object('web', null); end if;

  update public.supplier_invoice
     set reading = jsonb_set(
           jsonb_set(coalesce(reading, '{}'::jsonb), '{factura}', coalesce(reading->'factura', '{}'::jsonb) || jsonb_build_object('proveedor', v_nuevo)),
           '{releida}', jsonb_build_object('sesion', v_s.id, 'cuando', now(), 'quien', v_quien, 'puesto', to_jsonb(v_puesto))),
         updated_at = now()
   where id = v_f.id;

  insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, actor_name, action, text, detail)
  values (v_f.account_id, v_f.company_id, v_f.inbox_id, v_f.id, 'persona', v_quien, 'leida',
          case when cardinality(v_puesto) = 0
               then format('%s vuelve a leer su PDF para los datos del proveedor: no trae nada más de lo que ya tenía.', v_quien)
               else format('%s vuelve a leer su PDF para los datos del proveedor: añade %s.', v_quien,
                           regexp_replace(array_to_string(array(select case x when 'telefono' then 'el teléfono' when 'web' then 'la web' when 'email' then 'el correo' else 'la dirección' end from unnest(v_puesto) x), ', '), ', ([^,]*)$', ' y \1')) end,
          jsonb_build_object('releida', true, 'sesion', v_s.id, 'puesto', to_jsonb(v_puesto)));

  return jsonb_build_object('proveedor', v_nuevo, 'puesto', to_jsonb(v_puesto));
end $_$;


--
-- Name: FUNCTION conta_lectura_proveedor_releida(p_invoice uuid, p_session uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lectura_proveedor_releida(p_invoice uuid, p_session uuid) IS 'S01b2 · Completa la lectura guardada de una factura con lo que le faltaba del proveedor (teléfono, web, correo, dirección), tomado de una relectura de SU PDF (goods_receipt_ai_session). Nunca cambia nombre ni NIF.';


--
-- Name: conta_libro_iva_deducir_en(uuid, jsonb, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_libro_iva_deducir_en(p_company uuid, p_claves jsonb, p_year integer, p_period text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  c public.company; v_pedidas int; v_halladas int; v_marcadas int; v_faltan jsonb; v_testigo jsonb;
begin
  select * into c from public.company where id = p_company;
  if c.id is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_gestionar(p_company) then
    raise exception 'Solo quien gestiona los impuestos de la empresa cambia dónde se dedujo una factura.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_claves) <> 'array' or jsonb_array_length(p_claves) = 0 then
    raise exception 'Faltan las facturas: una lista de claves de Diez (ejercicio, serie y documento).' using errcode = '22023';
  end if;
  if p_period is not null and (p_year is null or p_period !~ '^([1-4]T|0[1-9]|1[0-2])$') then
    raise exception '«%» no es un periodo del 303.', p_period using errcode = '22023';
  end if;
  if p_period is not null and (p_motivo is null or btrim(p_motivo) = '') then
    raise exception 'Di por qué: de dónde sale que se dedujo en el % de %.', p_period, p_year using errcode = '22023';
  end if;

  -- Cada clave, su asiento de Diez en ESTA empresa (regla 9: cuenta y empresa).
  drop table if exists pg_temp._claves;
  create temporary table _claves on commit drop as
  select x->>'e' e, x->>'s' s, x->>'n' n, je.id entry_id
    from jsonb_array_elements(p_claves) x
    left join public.journal_entry je on je.account_id = c.account_id and je.company_id = p_company
     and je.external_program = 'diez' and je.external_year = x->>'e' and je.external_series = x->>'s' and je.external_number = x->>'n';
  select count(*), count(entry_id) into v_pedidas, v_halladas from _claves;
  select coalesce(jsonb_agg(jsonb_build_object('e', e, 's', s, 'n', n)), '[]') into v_faltan from _claves where entry_id is null
     or not exists (select 1 from public.vat_book_entry v where v.entry_id = _claves.entry_id and v.book in ('received', 'investment') and v.voided_at is null);
  -- Si falta alguna, ninguna: o la lista entera, o nada.
  if jsonb_array_length(v_faltan) > 0 then
    return jsonb_build_object('marcadas', 0, 'pedidas', v_pedidas, 'faltan', v_faltan,
                              'texto', jsonb_array_length(v_faltan) || ' de ' || v_pedidas || ' no son recibidas de esta empresa en el libro de IVA: no se ha marcado ninguna.');
  end if;
  update public.vat_book_entry v
     set deduction_year = case when p_period is null then null else p_year end,
         deduction_period = p_period,
         deduction_reason = case when p_period is null then null else btrim(p_motivo) end,
         updated_at = now()
    from _claves k
   where v.entry_id = k.entry_id and v.account_id = c.account_id and v.company_id = p_company
     and v.book in ('received', 'investment') and v.voided_at is null;
  get diagnostics v_marcadas = row_count;
  -- El testigo: en cada trimestre del año que toca la carga, la [28] y la [29]
  -- del libro (recibidas corrientes que no son intracomunitarias, ya con «deducida en») contra
  -- las del 303 PRESENTADO (con su justificante). Al céntimo; sin 303
  -- presentado, se dice y no se compara.
  with ef as (
    select v.tax_base, coalesce(v.deductible_amount, v.tax_amount) ded,
           case when v.deduction_period is not null then v.deduction_year else extract(year from coalesce(v.received_date, v.issue_date))::int end y,
           coalesce(v.deduction_period, extract(quarter from coalesce(v.received_date, v.issue_date))::int || 'T') per
      from public.vat_book_entry v
     where v.account_id = c.account_id and v.company_id = p_company and v.voided_at is null and v.book = 'received'
       -- 0300: la [28]/[29] lleva también la inversión del sujeto pasivo que no es
       -- intracomunitaria (esa va en la [36]/[37]), como el 303 presentado.
       and v.operation_key <> '09' and not v.investment_good and not v.deductible_later and v.invoice_type not like 'R%'
  ), periodos as (
    select distinct y, per from ef
     where per ~ '^[1-4]T$' and y = coalesce(p_year, (select min(je.external_year)::int from _claves k join public.journal_entry je on je.id = k.entry_id))
  ), libro as (
    select y, per, round(sum(tax_base), 2) c28, round(sum(ded), 2) c29 from ef group by y, per
  )
  select coalesce(jsonb_agg(jsonb_build_object('periodo', p.per || '/' || p.y,
           'libro_28', l.c28, 'libro_29', l.c29,
           'presentado_28', (select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '28'),
           'presentado_29', (select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '29'),
           'presentado', r.id is not null,
           'casa', r.id is not null
                   and coalesce(l.c28, 0) = coalesce((select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '28'), 0)
                   and coalesce(l.c29, 0) = coalesce((select b.value from public.tax_return_box b where b.tax_return_id = r.id and b.box = '29'), 0))
           order by p.per), '[]')
    into v_testigo
    from periodos p left join libro l on l.y = p.y and l.per = p.per
    left join lateral (select r.id from public.tax_return r
                        where r.account_id = c.account_id and r.company_id = p_company and r.form_code = '303'
                          and r.fiscal_year = p.y and r.period = p.per and r.sequence = 1
                          and r.status in ('filed', 'booked', 'paid', 'offset', 'refunded')
                          and exists (select 1 from public.tax_return_box b where b.tax_return_id = r.id and b.origin = 'justificante')) r on true;
  return jsonb_build_object('marcadas', v_marcadas, 'pedidas', v_pedidas, 'faltan', '[]'::jsonb, 'testigo', v_testigo,
    'casa', not exists (select 1 from jsonb_array_elements(v_testigo) x where not (x->>'casa')::boolean),
    'texto', case when p_period is null
                  then v_marcadas || ' líneas del libro de ' || v_pedidas || ' facturas vuelven al periodo de su fecha.'
                  else v_marcadas || ' líneas del libro de ' || v_pedidas || ' facturas, deducidas en el ' || p_period || ' de ' || p_year || '.' end);
end $_$;


--
-- Name: FUNCTION conta_libro_iva_deducir_en(p_company uuid, p_claves jsonb, p_year integer, p_period text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_libro_iva_deducir_en(p_company uuid, p_claves jsonb, p_year integer, p_period text, p_motivo text) IS 'I01c (0290) · Marca (o quita, con periodo null) «deducida en» en las recibidas de la empresa por sus claves de Diez. Todas o ninguna.';


--
-- Name: conta_liquidacion_apuntar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_apuntar(p_company uuid, p jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_r public.party_role; v_nombre text; v_local uuid := nullif(p->>'local', '')::uuid;
  v_desde date := nullif(p->>'desde', '')::date; v_hasta date := nullif(p->>'hasta', '')::date;
  v_vendido numeric := nullif(p->>'vendido', '')::numeric; v_com numeric := coalesce(nullif(p->>'comision', '')::numeric, 0);
  v_cobrado numeric := nullif(p->>'cobrado', '')::numeric; v_id uuid; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor());
  v_clave text; v_inv uuid; v_corte date;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta apunta liquidaciones.' using errcode = '42501';
  end if;
  select * into v_r from public.party_role where id = nullif(p->>'intermediario', '')::uuid and account_id = v_acc and role = 'platform';
  if v_r.id is null then raise exception 'Di quién te paga (un intermediario de Contactos).' using errcode = '22023'; end if;
  select name into v_nombre from public.party where id = v_r.party_id;
  if v_desde is null or v_hasta is null or v_hasta < v_desde then raise exception 'Di el periodo: desde y hasta.' using errcode = '22023'; end if;
  if v_vendido is null then raise exception 'Di lo vendido en el periodo.' using errcode = '22023'; end if;
  if v_com < 0 then raise exception 'La comisión va en positivo: lo que se queda.' using errcode = '22023'; end if;
  if v_cobrado is null then raise exception 'Di lo cobrado: lo que te paga.' using errcode = '22023'; end if;
  if v_local is not null and not exists (select 1 from public.locations where id = v_local and account_id = v_acc) then raise exception 'Ese local no es de esta cuenta.' using errcode = '22023'; end if;
  v_clave := 'a_mano:' || v_r.id::text || ':' || coalesce(v_local::text, 'sin') || ':' || v_desde::text || ':' || v_hasta::text;
  if exists (select 1 from public.channel_settlement where account_id = v_acc and import_key = v_clave) then
    raise exception 'Ya hay una liquidación de % apuntada del % al %: ábrela y corrígela.', coalesce(v_nombre, 'ese intermediario'),
      to_char(v_desde, 'DD/MM'), to_char(v_hasta, 'DD/MM/YYYY') using errcode = '23505';
  end if;
  v_corte := public._conta_corte(p_company);
  insert into public.channel_settlement (account_id, channel_id, party_id, location_id, settlement_ref, period_from, period_to, settlement_date, period_grain,
    orders_count, gross_sales, commission, other_cost, net_payout, source, import_key, raw, needs_review, is_reference, created_by, created_by_name)
  values (v_acc, v_r.channel_id, v_r.party_id, v_local, nullif(btrim(coalesce(p->>'referencia', '')), ''), v_desde, v_hasta, v_hasta,
    case when v_hasta - v_desde = 6 then 'week' when v_hasta - v_desde between 13 and 15 then 'quincena' when v_hasta - v_desde between 27 and 30 then 'mes' else 'periodo' end,
    nullif(p->>'pedidos', '')::int, round(v_vendido, 2), -round(v_com, 2), round(v_vendido - v_com - v_cobrado, 2), round(v_cobrado, 2), 'a_mano', v_clave,
    jsonb_build_object('a_mano', true, 'nota', nullif(btrim(coalesce(p->>'nota', '')), ''),
      'factura', case when v_com > 0 then jsonb_build_object('total', round(v_com, 2), 'numero', nullif(btrim(coalesce(p->>'factura', '')), '')) end),
    false, v_corte is not null and v_hasta < v_corte, auth.uid(), v_quien)
  returning id into v_id;
  v_inv := public._conta_liquidacion_factura_enganchar(v_id);
  return jsonb_build_object('liquidacion_id', v_id, 'factura_id', v_inv,
    'texto', 'Apuntada la liquidación de ' || coalesce(v_nombre, 'tu intermediario') || ' del ' || to_char(v_desde, 'DD/MM') || ' al ' || to_char(v_hasta, 'DD/MM/YYYY') ||
             ': vendido ' || public.conta_euros_exactos(v_vendido) || ', comisión ' || public.conta_euros_exactos(v_com) || ', te paga ' || public.conta_euros_exactos(v_cobrado) || '. ' ||
             case when v_corte is not null and v_hasta < v_corte then 'Es de antes del cierre: de referencia, sin factura ni asiento.'
                  when v_com > 0 and v_inv is null then 'Falta su factura de comisión: súbela en Compras y se engancha.'
                  when v_inv is not null then 'Su factura de comisión ya estaba: enganchada.'
                  else 'Sin comisión, no lleva factura.' end);
end $$;


--
-- Name: FUNCTION conta_liquidacion_apuntar(p_company uuid, p jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_liquidacion_apuntar(p_company uuid, p jsonb, p_quien_nombre text) IS 'V02 · E2. «Apuntar a mano» una liquidación de cualquier intermediario: periodo, lo vendido, la comisión y lo cobrado. Se cuadra igual que lo que llega solo.';


--
-- Name: conta_liquidacion_enlazar_factura(uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_enlazar_factura(p_invoice uuid, p_liquidaciones uuid[], p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.supplier_invoice; v_mal int; v_n int; v_suma numeric; v_desde date; v_hasta date;
  v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
begin
  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then
    raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501';
  end if;
  if auth.uid() is not null and not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta enlaza facturas con liquidaciones.' using errcode = '42501';
  end if;
  if v_f.status in ('anulada', 'descartada') then
    raise exception 'La factura está %: no se enlaza.', v_f.status using errcode = '22023';
  end if;
  if p_liquidaciones is null or cardinality(p_liquidaciones) = 0 then
    raise exception 'Di con qué liquidaciones se enlaza.' using errcode = '22023';
  end if;
  -- De la cuenta, del canal cuya plataforma es el proveedor de la factura, y sin otra factura.
  select count(*) into v_mal
    from unnest(p_liquidaciones) x(id)
    left join public.channel_settlement cs on cs.id = x.id and cs.account_id = v_f.account_id
   where cs.id is null
      or (cs.commission_invoice_id is not null and cs.commission_invoice_id <> v_f.id)
      or not exists (select 1 from public.party_role pl
                       join public.party_role ps on ps.account_id = pl.account_id and ps.party_id = pl.party_id and ps.role = 'supplier'
                      where pl.account_id = v_f.account_id and pl.role = 'platform' and pl.channel_id = cs.channel_id
                        and ps.supplier_id = v_f.supplier_id);
  if v_mal > 0 then
    raise exception '% de las % liquidaciones no son de este proveedor, no son de tu cuenta o ya tienen otra factura: no se enlaza ninguna.',
      v_mal, cardinality(p_liquidaciones) using errcode = '22023';
  end if;
  update public.channel_settlement set commission_invoice_id = v_f.id, updated_at = now()
   where account_id = v_f.account_id and id = any (p_liquidaciones) and commission_invoice_id is distinct from v_f.id;
  get diagnostics v_n = row_count;
  perform public._conta_liquidacion_marcar(cs.id) from public.channel_settlement cs where cs.account_id = v_f.account_id and cs.id = any (p_liquidaciones);
  select round(sum(coalesce((cs.raw->'factura'->>'total')::numeric, 0)), 2), min(cs.period_from), max(cs.period_to)
    into v_suma, v_desde, v_hasta
    from public.channel_settlement cs where cs.account_id = v_f.account_id and cs.id = any (p_liquidaciones);
  insert into public.supplier_invoice_change (account_id, supplier_invoice_id, by_name, what, cambios)
  values (v_f.account_id, v_f.id, v_quien, 'guardar', jsonb_build_array(jsonb_build_object('campo', 'liquidaciones',
          'antes', null, 'ahora', to_jsonb(p_liquidaciones))));
  return jsonb_build_object('enlazadas', cardinality(p_liquidaciones), 'nuevas', v_n, 'suma', v_suma, 'total', v_f.grand_total,
    'cuadra', v_suma = v_f.grand_total,
    'texto', format('Enlazada con %s liquidaciones (del %s al %s): suman %s, %s.', cardinality(p_liquidaciones),
                    to_char(v_desde, 'DD/MM'), to_char(v_hasta, 'DD/MM/YYYY'), public.conta_euros_exactos(v_suma),
                    case when v_suma = v_f.grand_total then 'como la factura'
                         else 'y la factura dice ' || public.conta_euros_exactos(v_f.grand_total) || ': revisa cuáles van' end));
end $$;


--
-- Name: conta_liquidacion_factura_proponer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_factura_proponer(p_settlement uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cs public.channel_settlement; v_e uuid; v_f jsonb; v_sup uuid; v_rol public.party_role; v_inv uuid; v_410 text;
  v_c623 text; v_c627 text; v_tasa uuid; v_fecha date; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), 'Liquidación por correo');
  v_base numeric; v_iva numeric; v_total numeric; v_bc numeric; v_ba numeric; v_sem int; v_corte date;
begin
  select * into v_cs from public.channel_settlement where id = p_settlement for update;
  if v_cs.id is null then raise exception 'Esa liquidación no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.current_user_is_admin_or_manager_of(v_cs.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta propone facturas.' using errcode = '42501';
  end if;
  if v_cs.commission_invoice_id is not null then
    return jsonb_build_object('estado', 'ya_estaba', 'factura_id', v_cs.commission_invoice_id, 'texto', 'La factura de comisión ya estaba.');
  end if;
  -- El corte (Julio, 16/10): la contabilidad está cerrada hasta la fecha de corte
  -- de Bancos. Una liquidación que ACABA antes es solo de referencia: sin
  -- factura ni asiento (sirve para contrastar y para casar su cobro). La que
  -- cruza el corte es real: su factura va entera con su fecha (después del fin
  -- del periodo, así que ya del periodo abierto).
  v_corte := public._conta_corte((select company_id from public.platform_store where id = v_cs.store_id));
  if v_corte is not null and v_cs.period_to < v_corte then
    update public.channel_settlement set is_reference = true, updated_at = now() where id = v_cs.id and is_reference is distinct from true;
    perform public._conta_liquidacion_marcar(v_cs.id);
    return jsonb_build_object('estado', 'referencia', 'corte', v_corte,
      'texto', 'De referencia: es de antes del cierre (' || to_char(v_corte - 1, 'DD/MM/YYYY') || '), así que no lleva factura de comisión ni asiento.');
  end if;
  v_f := v_cs.raw->'factura';
  if v_f is null or jsonb_typeof(v_f) <> 'object' or coalesce((v_f->>'total')::numeric, 0) = 0 then
    return jsonb_build_object('estado', 'sin_factura', 'texto', 'Esta liquidación no tiene comisión ni cargos que facturar.');
  end if;
  v_base := (v_f->>'base')::numeric; v_iva := (v_f->>'iva')::numeric; v_total := (v_f->>'total')::numeric;
  v_bc := (v_f->'comision'->>'base')::numeric; v_ba := (v_f->'publicidad'->>'base')::numeric;
  if round(v_base * 100) + round(v_iva * 100) <> round(v_total * 100) or round(v_bc * 100) + round(v_ba * 100) <> round(v_base * 100) then
    raise exception 'La factura de comisión no cuadra: base + IVA no es el total.' using errcode = '22023';
  end if;
  -- D07 (Julio, 23/10, camino B): la factura de comisión de Uber llega CADA
  -- SEMANA, como su propia factura recibida, con su PDF y su número, y se
  -- enlaza con las liquidaciones de su semana (conta_liquidacion_enlazar_factura).
  -- Aquí ya no se crea una provisional sin número ni PDF: salía en «Facturas
  -- recibidas» y en «Por revisar» como si fuera una factura. Si una semana no
  -- llega, lo dice Inicio.
  perform public._conta_liquidacion_marcar(v_cs.id);
  return jsonb_build_object('estado', 'espera_factura', 'total', (v_f->>'total')::numeric,
    'texto', 'Su factura de comisión (' || public.conta_euros_exactos((v_f->>'total')::numeric) ||
             ') llega aparte, cada semana, con su PDF: cuando entre en Facturas recibidas se enlaza con las liquidaciones de su semana.');
end $$;


--
-- Name: conta_liquidacion_ficha(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_ficha(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare cs public.channel_settlement; v_fac jsonb; v_correo jsonb; v_tienda text; v_local uuid; v_local_nombre text; v_marca text; v_canal text;
begin
  select * into cs from public.channel_settlement where id = p_id;
  if cs.id is null or not public.belongs_to_account(cs.account_id) then
    raise exception 'Esa liquidación no está en tu cuenta.' using errcode = '42501';
  end if;
  select sc.name into v_canal from public.sales_channel sc where sc.id = cs.channel_id and sc.account_id = cs.account_id;
  select regexp_replace(coalesce(ps.external_text, cs.external_location_text, ''), '\s*\(.*$', ''), coalesce(cs.location_id, ps.location_id)
    into v_tienda, v_local
    from (select 1) x left join public.platform_store ps on ps.id = cs.store_id and ps.account_id = cs.account_id;
  select lo.name into v_local_nombre from public.locations lo where lo.id = v_local and lo.account_id = cs.account_id;
  select b.name into v_marca from public.brand b where b.id = cs.brand_id and b.account_id = cs.account_id;

  -- Su factura de comisión: la ligada (S01i), o la que apunta la propia liquidación.
  select jsonb_build_object('id', si.id, 'codigo', si.code, 'numero', si.invoice_number, 'fecha', si.invoice_date,
           'base', si.tax_base_total, 'iva', si.tax_total, 'total', si.grand_total, 'estado', si.status, 'en_revision', si.needs_review)
    into v_fac
    from public.supplier_invoice si
   where si.account_id = cs.account_id
     and si.id = coalesce((select k.supplier_invoice_id from public.channel_settlement_invoice k
                            where k.settlement_id = cs.id and k.account_id = cs.account_id order by k.created_at limit 1), cs.commission_invoice_id);

  -- El correo del que salió: el suyo, o el primero que lo nombra.
  select jsonb_build_object('email_id', l.email_id, 'fecha', l.received_at, 'de', l.from_address, 'asunto', l.subject, 'a', l.to_address,
           'adjuntos', coalesce(l.detail->'dejados', '[]'::jsonb), 'company_id', l.company_id)
    into v_correo
    from public.inbound_email_log l
   where l.account_id = cs.account_id
     and (l.email_id = cs.inbound_email_id
          or (cs.inbound_email_id is null and jsonb_typeof(l.detail->'liquidaciones') = 'array'
              and exists (select 1 from jsonb_array_elements(l.detail->'liquidaciones') x where x->>'id' = cs.id::text)))
   order by (l.email_id = cs.inbound_email_id) desc, l.received_at limit 1;

  return jsonb_build_object(
    'id', cs.id, 'plataforma', v_canal, 'canal_id', cs.channel_id, 'marca', coalesce(v_marca, nullif(cs.external_brand_text, '')), 'local', v_local_nombre, 'local_id', v_local,
    'tienda', nullif(v_tienda, ''), 'referencia', cs.settlement_ref,
    'desde', cs.period_from, 'hasta', cs.period_to, 'sin_periodo', cs.period_from is null,
    'origen', cs.source,
    'pedidos', cs.orders_count, 'ventas', cs.gross_sales, 'comision', cs.commission,
    'otros', coalesce(cs.delivery_transport, 0) + coalesce(cs.min_order_fee, 0) + coalesce(cs.other_cost, 0) + coalesce(cs.promo_product, 0)
             + coalesce(cs.promo_flash, 0) + coalesce(cs.incidents_cost, 0) + coalesce(cs.incidents_refund, 0) + coalesce(cs.access_fee, 0)
             + coalesce(cs.prime_fee, 0) + coalesce(cs.recurring_fee, 0) + coalesce(cs.other_earnings, 0) + coalesce(cs.adjustments, 0),
    'neto', cs.net_payout, 'pago_el', cs.settlement_date,
    'cobrado_el', cs.collected_on, 'cobrado', cs.collected_amount,
    'factura', v_fac, 'correo', v_correo,
    'revisar', case when cs.needs_review then coalesce(cs.review_note, 'Hay algo que mirar.') end);
end $_$;


--
-- Name: conta_liquidacion_pedidos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_pedidos(p_settlement uuid) RETURNS TABLE(sale_id uuid, company_id uuid, location_id uuid, sales_day date, summary_id uuid, invoice_id uuid, importe numeric, via text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare v_cs public.channel_settlement; v_st public.platform_store; v_marca uuid; v_local uuid; v_empresa uuid; d date;
begin
  select * into v_cs from public.channel_settlement where id = p_settlement;
  if v_cs.id is null then return; end if;
  if exists (select 1 from public.channel_settlement_order o where o.settlement_id = v_cs.id and o.account_id = v_cs.account_id) then
    return query
      with v as (
        select distinct o.sale_id from public.channel_settlement_order o
         where o.settlement_id = v_cs.id and o.account_id = v_cs.account_id and o.sale_id is not null
      ), s as (
        select v.sale_id, sm.* from v
          left join public.sales_day_summary sm on sm.account_id = v_cs.account_id and v.sale_id = any(sm.sale_ids) and sm.entry_id is not null
      )
      select s.sale_id, s.company_id, s.location_id, s.sales_day, s.id,
             (select ci.id from public.customer_invoice ci where ci.entry_id = s.entry_id and ci.company_id = s.company_id and ci.status = 'emitida' limit 1),
             (select d2.total from public.conta_pedidos_del_dia(s.company_id, s.location_id, s.sales_day) d2 where d2.id = s.sale_id limit 1),
             'pedidos'::text
        from s;
    return;
  end if;
  select * into v_st from public.platform_store where id = v_cs.store_id and account_id = v_cs.account_id;
  v_marca := coalesce(v_cs.brand_id, v_st.brand_id);
  v_local := coalesce(v_cs.location_id, v_st.location_id);
  v_empresa := v_st.company_id;
  if v_marca is null or v_local is null or v_empresa is null or v_cs.period_from is null or v_cs.period_to is null or v_cs.channel_id is null then return; end if;
  for d in select g::date from generate_series(v_cs.period_from, v_cs.period_to, interval '1 day') g loop
    return query
      select p.id, v_empresa, v_local, d, sm.id,
             (select ci.id from public.customer_invoice ci where ci.entry_id = sm.entry_id and ci.company_id = v_empresa and ci.status = 'emitida' limit 1),
             p.total, 'periodo'::text
        from public.conta_pedidos_del_dia(v_empresa, v_local, d) p
        left join public.sales_day_summary sm on sm.company_id = v_empresa and sm.location_id = v_local and sm.sales_day = d
             and sm.channel_id = v_cs.channel_id and sm.entry_id is not null and p.id = any(sm.sale_ids)
       where p.canal_id = v_cs.channel_id and p.marca_id = v_marca and p.estado = 'closed' and coalesce(p.total, 0) <> 0;
  end loop;
end $$;


--
-- Name: FUNCTION conta_liquidacion_pedidos(p_settlement uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_liquidacion_pedidos(p_settlement uuid) IS 'PC01 · Los pedidos de una liquidación con su cierre, su factura y lo que el cierre cuenta de cada uno. Solo lee.';


--
-- Name: conta_liquidacion_registrar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_registrar(p_company uuid, p jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_prov text := lower(btrim(coalesce(p->>'proveedor', ''))); v_origen text := lower(btrim(coalesce(p->>'origen', 'correo')));
  v_tienda text := nullif(btrim(coalesce(p->>'tienda', '')), ''); v_tid text := nullif(btrim(coalesce(p->>'tienda_id', '')), '');
  v_desde date := nullif(p->>'desde', '')::date; v_hasta date := nullif(p->>'hasta', '')::date;
  v_s public.platform_store; v_canal uuid; v_clave text; v_ya public.channel_settlement; v_id uuid; v_fac jsonb; v_nueva boolean := false;
  v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), 'Liquidación por correo');
  v_neto numeric := nullif(p->>'neto', '')::numeric; v_texto text; v_solape text; v_rec jsonb; v_rol uuid; v_party uuid;
  v_marca uuid; v_local uuid; v_local_abierto boolean; v_local_nombre text; v_uber boolean; v_inv uuid; v_aviso text; v_nombre_plat text;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  -- La llama la función de entrada (sin persona) o, a mano, un administrador o encargado.
  if auth.uid() is not null and not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta registra liquidaciones.' using errcode = '42501';
  end if;
  if v_prov = '' then raise exception 'La liquidación no dice de qué plataforma es.' using errcode = '22023'; end if;
  if v_tienda is null and v_tid is null then raise exception 'El resumen no dice de qué tienda es.' using errcode = '22023'; end if;
  if v_desde is null or v_hasta is null or v_hasta < v_desde then raise exception 'El resumen no dice de qué periodo es.' using errcode = '22023'; end if;
  if v_neto is null then raise exception 'El resumen no trae el pago neto.' using errcode = '22023'; end if;
  v_uber := v_prov = 'uber' and v_origen = 'correo';
  v_nombre_plat := case v_prov when 'uber' then 'Uber' when 'glovo' then 'Glovo' when 'justeat' then 'Just Eat' else initcap(v_prov) end;

  -- El canal de venta de la plataforma (el de sus tiendas, o por su nombre).
  select channel_id into v_canal from public.platform_store where account_id = v_acc and company_id = p_company and provider = v_prov and channel_id is not null limit 1;
  if v_canal is null then
    select id into v_canal from public.sales_channel
     where account_id = v_acc and (slug = v_prov or slug like v_prov || '%' or replace(lower(name), ' ', '') like replace(v_prov, ' ', '') || '%')
     order by (slug = v_prov) desc, created_at limit 1;
  end if;
  -- La tienda: por su ID, o por un nombre ya visto; nueva si no.
  v_rec := public.conta_tienda_reconocer(p_company, v_prov, v_tid, v_tienda, v_canal, v_quien);
  select * into v_s from public.platform_store where id = (v_rec->>'tienda_id')::uuid;
  v_nueva := (v_rec->>'nueva')::boolean;
  -- Quien te paga, de alta sola con su primera liquidación.
  v_rol := public.conta_intermediario_asegurar(p_company, v_prov, coalesce(v_s.channel_id, v_canal), p->'intermediario'->>'nombre', p->'intermediario'->>'nif', v_quien);
  select party_id into v_party from public.party_role where id = v_rol;
  -- Su marca y su local: los de su tramo el primer día del periodo.
  select t.brand_id, t.location_id into v_marca, v_local from public.conta_tienda_en(v_s.id, v_desde) t;
  select active, name into v_local_abierto, v_local_nombre from public.locations where id = v_local;

  -- La misma tienda y el mismo periodo, por este camino o por otro: nada nuevo, y se dice.
  v_clave := case when v_uber then 'uber-correo:' else v_prov || '-' || v_origen || ':' end || v_s.id::text || ':' || v_desde::text || ':' || v_hasta::text;
  select * into v_ya from public.channel_settlement where account_id = v_acc and import_key = v_clave;
  if v_ya.id is null then
    select * into v_ya from public.channel_settlement where account_id = v_acc and store_id = v_s.id and period_from = v_desde and period_to = v_hasta
     order by created_at limit 1;
  end if;
  if v_ya.id is not null then
    return jsonb_build_object('liquidacion_id', v_ya.id, 'ya_estaba', true, 'tienda_id', v_s.id, 'tienda_nueva', false,
      'aprendido_id', (v_rec->>'aprendido_id')::boolean, 'cambio', v_rec->'cambio',
      'texto', 'Esta liquidación ya estaba (del ' || to_char(v_desde, 'DD/MM') || ' al ' || to_char(v_hasta, 'DD/MM/YYYY') || '): no se ha creado nada' ||
               case when v_ya.net_payout is null or abs(v_ya.net_payout - v_neto) < 0.005 then '.'
                    else ', pero esta dice que paga ' || public.conta_euros_exactos(v_neto) || ' y la que estaba ' || public.conta_euros_exactos(v_ya.net_payout) || ': revísala.' end ||
               case when (v_rec->>'aprendido_id')::boolean then ' Aprendido el ID de su tienda.' else '' end);
  end if;

  insert into public.channel_settlement (
    account_id, channel_id, party_id, brand_id, location_id, external_brand_text, external_location_text, settlement_ref, period_from, period_to,
    settlement_date, period_grain, orders_count, gross_sales, base_amount, vat_amount,
    commission, other_cost, other_earnings, promo_charges, ads_spend, item_promotions, chargebacks, adjustments,
    net_payout, source, import_key, raw, needs_review, review_note, store_id, inbound_email_id, created_by_name)
  values (
    v_acc, coalesce(v_s.channel_id, v_canal), v_party, v_marca, v_local, nullif(p->>'marca', ''), coalesce(v_tienda, v_s.external_text), nullif(p->>'referencia', ''), v_desde, v_hasta,
    coalesce(nullif(p->>'deposito_iniciado', '')::date, nullif(p->>'pago_el', '')::date, v_hasta + 1),
    case when v_hasta - v_desde = 6 then 'week' when v_hasta - v_desde between 13 and 15 then 'quincena' when v_hasta - v_desde between 27 and 30 then 'mes'
         when v_uber then 'weeks' else 'periodo' end,
    nullif(p->>'pedidos', '')::int, (p->'ventas'->>'total')::numeric, (p->'ventas'->>'base')::numeric, (p->'ventas'->>'iva')::numeric,
    coalesce((p->'uber'->>'tasas')::numeric, case when v_prov = 'justeat' then -nullif(p->>'comision', '')::numeric else -abs(nullif(p->>'comision', '')::numeric) end, 0), coalesce((p->'uber'->>'otros')::numeric, nullif(p->>'otros', '')::numeric, 0),
    (p->'ganancias'->>'otras')::numeric,
    (p->'marketing'->>'otrosPromo')::numeric, (p->'marketing'->>'anuncios')::numeric, (p->'marketing'->>'promociones')::numeric,
    (p->'modificaciones'->>'contracargo')::numeric, (p->'modificaciones'->>'ajustes')::numeric,
    v_neto, case when v_uber then 'correo_uber' else v_origen || '_' || v_prov end, v_clave, p, true, null, v_s.id, nullif(p->>'email_id', ''), v_quien)
  returning id into v_id;
  -- Por aclarar (tienda, cuadre, solape): esta, y cada una con la que se solapa, que ahora lo dice también.
  v_solape := public._conta_liquidacion_solape(v_id);
  perform public._conta_liquidacion_marcar(v_id);
  perform public._conta_liquidacion_marcar(o.id) from public.channel_settlement o, public.channel_settlement c
    where c.id = v_id and o.account_id = c.account_id and o.store_id = c.store_id and o.id <> c.id
      and daterange(o.period_from, o.period_to, '[]') && daterange(c.period_from, c.period_to, '[]');

  v_fac := public.conta_liquidacion_factura_proponer(v_id, v_quien);
  v_inv := public._conta_liquidacion_factura_enganchar(v_id);
  -- Un local cerrado no recibe ventas: si llega una liquidación suya, se avisa (nunca impide que entre).
  if v_local is not null and v_local_abierto is false then
    v_aviso := 'Llegan ventas de ' || v_local_nombre || ', que está cerrado: revisa de qué local es la tienda.';
    begin
      perform public.encolar_alerta(
        p_kind            => 'liquidacion_local_cerrado',
        p_subject         => 'Llega una liquidación de un local cerrado',
        p_message         => format('%s Tienda «%s», del %s al %s.', v_aviso, coalesce(v_tienda, v_s.external_text), to_char(v_desde, 'DD/MM'), to_char(v_hasta, 'DD/MM/YYYY')),
        p_debounce_kind   => 'liquidacion_local_cerrado:' || v_s.id::text,
        p_debounce_window => interval '7 days',
        p_account_id      => v_acc,
        p_location_id     => v_local,
        p_brand_id        => v_marca,
        p_severity        => 'aviso');
    exception when others then
      raise notice 'liquidacion_local_cerrado: no se pudo encolar el aviso (%)', sqlerrm;
    end;
  end if;
  v_texto := 'Liquidación de ' || v_nombre_plat || ' del ' || to_char(v_desde, 'DD/MM') || ' al ' || to_char(v_hasta, 'DD/MM/YYYY') || ' leída: neto ' ||
             public.conta_euros_exactos(v_neto) || case when v_neto <= 0 then ' (sin cobro: pasa al siguiente)' else '' end || '. ' ||
             case when v_inv is not null then 'Su factura de comisión ya estaba: enganchada.'
                  when v_uber or v_fac->>'estado' in ('referencia', 'sin_factura', 'ya_estaba') then coalesce(v_fac->>'texto', '')
                  when nullif(p->'factura'->>'numero', '') is not null then 'Su factura de comisión (' || (p->'factura'->>'numero') || ') se engancha sola cuando entre en Compras.'
                  else coalesce(v_fac->>'texto', '') end ||
             case when v_nueva then ' Tienda nueva: dale su marca y su local.' else '' end ||
             case when (v_rec->>'aprendido_id')::boolean then ' Aprendido el ID de su tienda.' else '' end ||
             case when v_rec->>'cambio' is not null then ' La tienda llega con otro nombre o en otra dirección: confírmalo.' else '' end ||
             case when v_aviso is not null then ' ' || v_aviso else '' end ||
             case when v_solape is not null then ' Por aclarar: ' || v_solape || ' (cada día cuenta una sola vez).' else '' end;
  return jsonb_build_object('liquidacion_id', v_id, 'ya_estaba', false, 'tienda_id', v_s.id, 'tienda_nueva', v_nueva,
                            'aprendido_id', (v_rec->>'aprendido_id')::boolean, 'cambio', v_rec->'cambio', 'intermediario_id', v_rol,
                            'factura', v_fac, 'factura_id', v_inv, 'texto', v_texto);
end $$;


--
-- Name: conta_liquidacion_resolver(uuid, uuid, uuid, date, date, text, numeric, text, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_resolver(p_company uuid, p_intermediario uuid, p_local uuid, p_desde date, p_hasta date, p_tipo text, p_importe numeric, p_frase text, p_fecha date DEFAULT NULL::date, p_lineas jsonb DEFAULT NULL::jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_r public.party_role; v_res jsonb; v_id uuid; v_nombre text;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  select * into v_r from public.party_role where id = p_intermediario and account_id = v_acc and role = 'platform';
  if v_r.id is null then raise exception 'Ese intermediario no es de la cuenta.' using errcode = '23514'; end if;
  select name into v_nombre from public.party where id = v_r.party_id;
  if v_r.channel_id is not null then
    -- Con canal: el camino del V01, que valida, hace el asiento y lo guarda.
    v_res := public.conta_plataforma_resolver(p_company, v_r.channel_id, p_local, p_desde, p_hasta, null, p_tipo, p_importe, p_frase, p_fecha, p_lineas, p_quien_nombre);
    update public.conta_liquidacion_resolucion set party_id = v_r.party_id where id = (v_res->>'id')::uuid;
  else
    -- Sin canal (Stripe, Amazon…): lo mismo, por su contacto. channel_id admite
    -- vacío desde la 2254.
    if p_tipo not in ('gasto', 'reclamacion') then raise exception 'Una diferencia se resuelve como gasto o como reclamación.' using errcode = '22023'; end if;
    if btrim(coalesce(p_frase, '')) = '' then raise exception 'Escribe en una frase por qué.' using errcode = '22023'; end if;
    if p_importe is null or p_importe = 0 then raise exception 'La diferencia tiene que tener importe.' using errcode = '22023'; end if;
    if not public.current_user_is_admin_or_manager_of(v_acc) then
      raise exception 'Solo un administrador o un encargado de la cuenta resuelve diferencias.' using errcode = '42501';
    end if;
    if exists (select 1 from public.conta_liquidacion_resolucion x where x.company_id = p_company and x.channel_id is null and x.party_id = v_r.party_id
                  and x.location_id is not distinct from p_local and x.period_from = p_desde and x.period_to = p_hasta and x.sale_id is null) then
      raise exception 'Esa diferencia ya está resuelta.' using errcode = '23505';
    end if;
    if p_tipo = 'gasto' then
      if p_lineas is null or jsonb_typeof(p_lineas) <> 'array' or jsonb_array_length(p_lineas) < 2 then raise exception 'Un gasto lleva su asiento.' using errcode = '22023'; end if;
      v_res := public._journal_entry_proponer(p_company,
        jsonb_build_object('series', 1, 'fecha', coalesce(p_fecha, p_hasta), 'source_type', 'manual',
          'concepto', 'Diferencia de la liquidación de ' || coalesce(v_nombre, 'tu intermediario') || ' (' || to_char(p_desde, 'DD/MM') || '–' || to_char(p_hasta, 'DD/MM/YYYY') || '): ' || btrim(p_frase),
          'confianza', 'seguro', 'porque', 'Diferencia resuelta como gasto en Ventas › Liquidaciones.'),
        p_lineas, null, coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor()), auth.uid());
      v_res := jsonb_build_object('asiento', (v_res->>'id')::uuid, 'numero_asiento',
        public.journal_entry_validar((v_res->>'id')::uuid, coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor()))->'numero');
    else
      v_res := '{}'::jsonb;
    end if;
    insert into public.conta_liquidacion_resolucion (account_id, company_id, channel_id, party_id, location_id, period_from, period_to, kind, importe, frase,
                                                     entry_id, created_by, created_by_name)
    values (v_acc, p_company, null, v_r.party_id, p_local, p_desde, p_hasta, p_tipo, round(p_importe, 2), btrim(p_frase),
            (v_res->>'asiento')::uuid, auth.uid(), coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor()))
    returning id into v_id;
    v_res := v_res || jsonb_build_object('id', v_id);
  end if;
  return v_res || jsonb_build_object('texto',
    case when p_tipo = 'reclamacion' then 'Apuntado: reclamas ' || public.conta_euros_exactos(abs(p_importe)) || ' a ' || coalesce(v_nombre, 'tu intermediario') || '. Te lo recuerdo hasta que llegue.'
         else 'Apuntado como gasto: ' || public.conta_euros_exactos(abs(p_importe)) || coalesce(', asiento ' || (v_res->>'numero_asiento'), '') || '.' end);
end $$;


--
-- Name: FUNCTION conta_liquidacion_resolver(p_company uuid, p_intermediario uuid, p_local uuid, p_desde date, p_hasta date, p_tipo text, p_importe numeric, p_frase text, p_fecha date, p_lineas jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_liquidacion_resolver(p_company uuid, p_intermediario uuid, p_local uuid, p_desde date, p_hasta date, p_tipo text, p_importe numeric, p_frase text, p_fecha date, p_lineas jsonb, p_quien_nombre text) IS 'V02 · E2. Resolver una diferencia de una liquidación en una frase: «Es un gasto» o «Lo reclamo» (se recuerda hasta que llegue).';


--
-- Name: conta_liquidacion_resolver_tienda(uuid, uuid, uuid, uuid, date, date, text, numeric, text, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidacion_resolver_tienda(p_company uuid, p_intermediario uuid, p_local uuid, p_marca uuid, p_desde date, p_hasta date, p_tipo text, p_importe numeric, p_frase text, p_fecha date DEFAULT NULL::date, p_lineas jsonb DEFAULT NULL::jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_r public.party_role; v_res jsonb := '{}'::jsonb; v_id uuid; v_nombre text; v_canal text; v_entry uuid; v_num jsonb;
        v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor());
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta resuelve diferencias.' using errcode = '42501';
  end if;
  select * into v_r from public.party_role where id = p_intermediario and account_id = v_acc and role = 'platform';
  if v_r.id is null then raise exception 'Ese intermediario no es de la cuenta.' using errcode = '23514'; end if;
  if p_tipo not in ('gasto', 'reclamacion') then raise exception 'Una diferencia se resuelve como gasto o como reclamación.' using errcode = '22023'; end if;
  if btrim(coalesce(p_frase, '')) = '' then raise exception 'Escribe en una frase por qué.' using errcode = '22023'; end if;
  if p_importe is null or p_importe = 0 then raise exception 'La diferencia tiene que tener importe.' using errcode = '22023'; end if;
  if p_local is not null and not exists (select 1 from public.locations where id = p_local and account_id = v_acc) then raise exception 'Ese local no es de la cuenta.' using errcode = '23514'; end if;
  if p_marca is not null and not exists (select 1 from public.brand where id = p_marca and account_id = v_acc) then raise exception 'Esa marca no es de la cuenta.' using errcode = '23514'; end if;
  select name into v_nombre from public.party where id = v_r.party_id;
  select name into v_canal from public.sales_channel where id = v_r.channel_id;
  if exists (select 1 from public.conta_liquidacion_resolucion x
              where x.company_id = p_company and x.sale_id is null and x.period_from = p_desde and x.period_to = p_hasta
                and x.location_id is not distinct from p_local and x.brand_id is not distinct from p_marca
                and (x.channel_id = v_r.channel_id or (v_r.channel_id is null and x.channel_id is null and x.party_id = v_r.party_id))) then
    raise exception 'Esa diferencia ya está resuelta.' using errcode = '23505';
  end if;
  if p_tipo = 'gasto' then
    if p_lineas is null or jsonb_typeof(p_lineas) <> 'array' or jsonb_array_length(p_lineas) < 2 then raise exception 'Un gasto lleva su asiento.' using errcode = '22023'; end if;
    v_res := public._journal_entry_proponer(p_company,
      jsonb_build_object('series', 1, 'fecha', coalesce(p_fecha, p_hasta), 'source_type', 'manual',
        'concepto', 'Diferencia de la liquidación de ' || coalesce(v_canal, v_nombre, 'tu intermediario') || coalesce(' · ' || (select name from public.brand where id = p_marca), '') ||
                    ' (' || to_char(p_desde, 'DD/MM') || '–' || to_char(p_hasta, 'DD/MM/YYYY') || '): ' || btrim(p_frase),
        'confianza', 'seguro', 'porque', 'Diferencia resuelta como gasto en Ventas › Liquidaciones.'),
      p_lineas, null, v_quien, auth.uid());
    v_entry := (v_res->>'id')::uuid;
    v_num := public.journal_entry_validar(v_entry, v_quien)->'numero';
  end if;
  insert into public.conta_liquidacion_resolucion (account_id, company_id, channel_id, party_id, location_id, brand_id, period_from, period_to, kind, importe, frase,
                                                   entry_id, created_by, created_by_name)
  values (v_acc, p_company, v_r.channel_id, v_r.party_id, p_local, p_marca, p_desde, p_hasta, p_tipo, round(p_importe, 2), btrim(p_frase), v_entry, auth.uid(), v_quien)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'asiento', v_entry, 'numero_asiento', v_num, 'texto',
    case when p_tipo = 'reclamacion' then 'Apuntado: reclamas ' || public.conta_euros_exactos(abs(p_importe)) || ' a ' || coalesce(v_nombre, 'tu intermediario') || '. Te lo recuerdo hasta que llegue.'
         else 'Apuntado como gasto: ' || public.conta_euros_exactos(abs(p_importe)) || coalesce(', asiento ' || v_num::text, '') || '.' end);
end $$;


--
-- Name: FUNCTION conta_liquidacion_resolver_tienda(p_company uuid, p_intermediario uuid, p_local uuid, p_marca uuid, p_desde date, p_hasta date, p_tipo text, p_importe numeric, p_frase text, p_fecha date, p_lineas jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_liquidacion_resolver_tienda(p_company uuid, p_intermediario uuid, p_local uuid, p_marca uuid, p_desde date, p_hasta date, p_tipo text, p_importe numeric, p_frase text, p_fecha date, p_lineas jsonb, p_quien_nombre text) IS 'V02 · E2. Resolver la diferencia de la liquidación de una tienda (intermediario, local, marca y periodo) en una frase: «Es un gasto» (con su asiento) o «Lo reclamo» (se recuerda hasta que llegue).';


--
-- Name: conta_liquidaciones(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_liquidaciones(p_company uuid, p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_desde date; v_hasta date; v_hoy date := public.conta_hoy(); v_corte date; v_r jsonb;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  v_corte := public._conta_corte(p_company);
  v_hasta := coalesce(p_hasta, v_hoy);
  v_desde := coalesce(p_desde, v_hasta - 92);

  with roles as (
    select r.id as rol, r.party_id, r.channel_id, r.settlement_every as cada, coalesce(r.payout_days_after, 0) as dias,
           coalesce(r.payout_margin_days, 5) as margen, p.name as nombre
      from public.party_role r join public.party p on p.id = r.party_id
     where r.account_id = v_acc and r.role = 'platform'
  ),
  -- Los locales de la empresa (si la cuenta no los reparte por empresa, todos los suyos).
  locs as (
    select lc.location_id from public.location_company lc where lc.company_id = p_company
    union
    select l.id from public.locations l
     where l.account_id = v_acc and not exists (select 1 from public.location_company lc where lc.company_id = p_company)
  ),
  -- Las liquidaciones de la empresa (las de sus tiendas y las que no dicen tienda).
  liq as (
    select cs.*, ps.external_text as tienda,
           coalesce(cs.location_id, (select t.location_id from public.conta_tienda_en(cs.store_id, coalesce(cs.period_from, cs.settlement_date)) t)) as local_id,
           coalesce(cs.brand_id, (select t.brand_id from public.conta_tienda_en(cs.store_id, coalesce(cs.period_from, cs.settlement_date)) t)) as marca_id,
           coalesce(cs.period_from, cs.proposed_period_from, cs.settlement_date) as d1,
           coalesce(cs.period_to, cs.proposed_period_to, cs.settlement_date) as d2,
           public._conta_intermediario_de(v_acc, cs.party_id, cs.channel_id) as rol
      from public.channel_settlement cs
      left join public.platform_store ps on ps.id = cs.store_id and ps.account_id = v_acc
     where cs.account_id = v_acc and coalesce(cs.flow_type, 'own') <> 'licensed'
       and (ps.id is null or ps.company_id = p_company)
  ), liq_sel as (
    select * from liq where d1 is not null and d1 <= v_hasta and d2 >= v_desde
  ),
  -- Los periodos con ventas y sin liquidación: de los intermediarios con canal y
  -- calendario, por sus pedidos de cada tienda; de los que cobran facturas, por sus facturas.
  dias_venta as (
    -- Las plataformas liquidan por tienda (marca y local): lo vendido, por sus
    -- pedidos cerrados de esa marca, ese canal y ese local (Madrid). Las marcas
    -- cedidas no: su dinero lo cobra el socio.
    select r.rol, s.location_id as local_id, s.brand_id as marca_id,
           public._conta_periodo_de(r.cada, (s.sold_at at time zone 'Europe/Madrid')::date) as per, s.total
      from roles r join public.sale s on s.account_id = v_acc and s.channel_id = r.channel_id
      join public.brand b on b.id = s.brand_id and b.account_id = v_acc and coalesce(b.ownership_type, 'own') <> 'licensed'
     where r.channel_id is not null and r.cada is not null and s.status = 'closed' and coalesce(s.is_active, true)
       and (s.sold_at at time zone 'Europe/Madrid')::date between v_desde and v_hasta
       and s.location_id in (select location_id from locs)
    union all
    select r.rol, ci.location_id, null::uuid, public._conta_periodo_de(coalesce(r.cada, 'monthly'), ci.issue_date), ci.total
      from roles r join public.payment_method pm on pm.party_id = r.party_id and pm.account_id = v_acc
      join public.customer_invoice ci on ci.payment_method_id = pm.id and ci.company_id = p_company and ci.status = 'emitida'
     where ci.issue_date between v_desde and v_hasta
  ), esperados as (
    select rol, local_id, marca_id, lower(per) as d1, upper(per) - 1 as d2 from dias_venta
     group by rol, local_id, marca_id, per having sum(total) <> 0
  ),
  grupos as (
    select rol, local_id, marca_id, d1, d2 from liq_sel group by 1, 2, 3, 4, 5
    union
    select e.rol, e.local_id, e.marca_id, e.d1, e.d2 from esperados e
     where (v_corte is null or e.d2 >= v_corte)
       and not exists (select 1 from liq_sel l where l.rol is not distinct from e.rol and l.local_id is not distinct from e.local_id
                         and l.marca_id is not distinct from e.marca_id and l.d1 <= e.d2 and l.d2 >= e.d1)
  ),
  filas as (
    select g.*, r.party_id, r.channel_id, r.nombre, r.dias, r.margen, r.cada,
           coalesce(ch.name, r.nombre, 'Intermediario') as canal, l.name as local, l.active as local_abierto, br.name as marca,
           -- Lo vendido: los pedidos cerrados de su canal, su local y su marca (la
           -- tienda); sin marca, los de todo el local (Madrid).
           (select jsonb_build_object('total', coalesce(sum(s.total), 0), 'pedidos', count(*), 'dias', count(distinct (s.sold_at at time zone 'Europe/Madrid')::date))
              from public.sale s
             where r.channel_id is not null and g.local_id is not null and s.account_id = v_acc and s.channel_id = r.channel_id
               and s.location_id = g.local_id and (g.marca_id is null or s.brand_id = g.marca_id)
               and s.status = 'closed' and coalesce(s.is_active, true)
               and (s.sold_at at time zone 'Europe/Madrid')::date between g.d1 and g.d2) as pedidos,
           (select jsonb_build_object('total', coalesce(sum(ci.total), 0), 'n', count(*))
              from public.payment_method pm join public.customer_invoice ci on ci.payment_method_id = pm.id
             where r.channel_id is null and pm.party_id = r.party_id and pm.account_id = v_acc and ci.company_id = p_company
               and ci.status = 'emitida' and ci.location_id is not distinct from g.local_id and ci.issue_date between g.d1 and g.d2) as facturas_vendidas,
           (select jsonb_agg(jsonb_build_object(
                     'id', s.id, 'tienda', s.tienda, 'ref', s.settlement_ref, 'fecha', s.settlement_date, 'origen', s.source, 'pedidos', s.orders_count,
                     'ventas', coalesce(s.gross_sales, 0), 'comision', abs(coalesce(s.commission, 0)), 'neto', s.net_payout,
                     -- Lo que suman sus pedidos, lo que se compara con la caja: el
                     -- «Total del pedido» del informe de Uber; del correo, las ventas
                     -- con sus promociones y las otras ganancias; si no, las ventas.
                     'pedidos_total', coalesce(nullif(s.raw->>'pedidos_total', '')::numeric,
                                               case when s.item_promotions is not null or s.other_earnings is not null
                                                    then coalesce(s.gross_sales, 0) + coalesce(s.item_promotions, 0) + coalesce(s.other_earnings, 0) end,
                                               coalesce(s.gross_sales, 0)),
                     'cobrado', s.collected_amount, 'cobrado_el', s.collected_on, 'referencia', coalesce(s.is_reference, false),
                     'por_aclarar', case when s.needs_review and not coalesce(s.is_reference, false) then s.review_note end,
                     'a_facturar', nullif((s.raw->'factura'->>'total')::numeric, 0),
                     'factura', case when si.id is not null then jsonb_build_object('id', si.id, 'numero', si.invoice_number, 'total', si.grand_total, 'estado', si.status) end,
                     'casada_en_banco', exists (select 1 from public.bank_match_item i join public.bank_match b on b.id = i.match_id
                                                  where i.channel_settlement_id = s.id and b.status = 'vivo'),
                     'facturas_cobradas', s.invoice_match_status, 'facturas_nota', s.invoice_match_note)
                   order by s.d1, s.tienda)
              from liq_sel s left join public.supplier_invoice si on si.id = s.commission_invoice_id and si.account_id = v_acc
             where s.rol is not distinct from g.rol and s.local_id is not distinct from g.local_id and s.marca_id is not distinct from g.marca_id
               and s.d1 = g.d1 and s.d2 = g.d2) as liquidaciones,
           coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'tipo', x.kind, 'importe', x.importe, 'frase', x.frase, 'pedido', x.sale_id,
                                                         'quien', x.created_by_name, 'cuando', x.created_at, 'llego_el', x.arrived_on, 'llego', x.arrived_amount)
                                      order by x.created_at)
                       from public.conta_liquidacion_resolucion x
                      where x.company_id = p_company and x.location_id is not distinct from g.local_id and x.brand_id is not distinct from g.marca_id
                        and x.period_from = g.d1 and x.period_to = g.d2
                        and (x.channel_id = r.channel_id or (r.channel_id is null and x.party_id = r.party_id))), '[]'::jsonb) as resoluciones,
           (select jsonb_agg(jsonb_build_object('id', c.id, 'tienda', ps.external_text, 'tipo', c.kind, 'antes', c.antes, 'ahora', c.ahora) order by c.detected_at)
              from public.platform_store_cambio c join public.platform_store ps on ps.id = c.store_id
             where c.company_id = p_company and c.decided_at is null
               and c.store_id in (select s.store_id from liq_sel s where s.rol is not distinct from g.rol and s.local_id is not distinct from g.local_id
                                    and s.marca_id is not distinct from g.marca_id and s.d1 = g.d1 and s.d2 = g.d2)) as cambios
      from grupos g
      left join roles r on r.rol = g.rol
      left join public.sales_channel ch on ch.id = r.channel_id and ch.account_id = v_acc
      left join public.locations l on l.id = g.local_id and l.account_id = v_acc
      left join public.brand br on br.id = g.marca_id and br.account_id = v_acc
  ),
  cifras as (
    select f.*,
      coalesce(jsonb_array_length(f.liquidaciones), 0) as n_liq,
      (select coalesce(sum((x->>'ventas')::numeric), 0) from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x) as l_ventas,
      (select coalesce(sum((x->>'pedidos_total')::numeric), 0) from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x) as l_pedidos,
      (select coalesce(sum((x->>'comision')::numeric), 0) from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x) as l_comision,
      (select case when bool_and(x->>'neto' is not null) then sum((x->>'neto')::numeric) end from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x) as l_pagan,
      (select case when count(*) filter (where x->>'cobrado' is not null) > 0 then sum((x->>'cobrado')::numeric) end from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x) as l_banco,
      (select count(*) from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x
        where not (x->>'referencia')::boolean and x->>'cobrado' is null and coalesce((x->>'neto')::numeric, 0) > 0) as por_cobrar,
      (select count(*) from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x
        where not (x->>'referencia')::boolean and coalesce((x->>'a_facturar')::numeric, 0) > 0 and x->>'factura' is null) as faltan_facturas,
      (select coalesce(bool_and((x->>'referencia')::boolean), false) from jsonb_array_elements(coalesce(f.liquidaciones, '[]')) x) as todo_referencia,
      case when f.channel_id is not null then coalesce((f.pedidos->>'total')::numeric, 0)
           else coalesce((f.facturas_vendidas->>'total')::numeric, 0) end as vendido,
      (f.channel_id is null and coalesce((f.facturas_vendidas->>'n')::int, 0) = 0) as sin_vendido,
      greatest(1, coalesce(jsonb_array_length(f.liquidaciones), 0)) as tol,
      f.d2 + f.dias + f.margen as plazo,
      (select x from jsonb_array_elements(f.resoluciones) x where x->>'pedido' is null limit 1) as resuelta,
      (select coalesce(sum(abs((x->>'importe')::numeric)), 0) from jsonb_array_elements(f.resoluciones) x
        where x->>'tipo' = 'reclamacion' and x->>'llego_el' is null) as reclamado_sin_llegar
      from filas f
  ),
  dif as (
    select c.*,
      case when c.n_liq > 0 and (c.local_id is not null or c.channel_id is null) and not c.sin_vendido and abs(round((c.vendido - c.l_pedidos) * 100)) > c.tol
           then round(c.vendido - c.l_pedidos, 2) end as dif_ventas,
      case when c.n_liq > 0 and c.l_banco is not null and c.l_pagan is not null and c.por_cobrar = 0 and abs(round((c.l_pagan - c.l_banco) * 100)) > c.tol
           then round(c.l_pagan - c.l_banco, 2) end as dif_cobro
      from cifras c
  ),
  estado as (
    select d.*,
      case
        when d.n_liq = 0 then case when v_hoy > d.plazo then 'falta_liquidacion' else 'esperando_liquidacion' end
        -- De antes del corte: la lleva Diez; sirve para contrastar, no pide nada.
        when d.todo_referencia then 'cuadra'
        when d.local_id is null and d.channel_id is not null and not d.todo_referencia then 'diferencia'
        when (d.dif_ventas is not null or d.dif_cobro is not null) and d.resuelta is null then 'diferencia'
        when d.faltan_facturas > 0 then 'falta_factura'
        when d.por_cobrar > 0 then 'esperando_cobro'
        else 'cuadra'
      end as estado
      from dif d
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'clave', coalesce(e.rol::text, 'sin') || ':' || coalesce(e.local_id::text, 'sin') || ':' || coalesce(e.marca_id::text, 'sin') || ':' || e.d1 || ':' || e.d2,
      'marca_id', e.marca_id, 'marca', e.marca,
      'intermediario_id', e.rol, 'intermediario', coalesce(e.nombre, e.canal), 'canal_id', e.channel_id, 'canal', e.canal,
      'local_id', e.local_id, 'local', e.local, 'desde', e.d1, 'hasta', e.d2,
      'estado', e.estado, 'cerrada', e.estado = 'cuadra' and e.reclamado_sin_llegar = 0,
      'diferencia', case when e.estado = 'diferencia' then coalesce(e.dif_ventas, e.dif_cobro, 0) end,
      'frase', case e.estado
        when 'esperando_liquidacion' then 'Aún a tiempo: ' || coalesce(e.nombre, e.canal) || ' suele pagar hacia el ' || to_char(e.d2 + e.dias, 'DD/MM') || '.'
        when 'falta_liquidacion' then 'Falta su liquidación: tenía que haber llegado hacia el ' || to_char(e.d2 + e.dias, 'DD/MM') ||
                                      ' y vendiste ' || public.conta_euros_exactos(e.vendido) || ' por ' || e.canal || coalesce(' con ' || e.marca, '') || '.'
        when 'diferencia' then case
          when e.local_id is null and e.channel_id is not null then 'No sé de qué local es: dale su local a la tienda y se compara con lo que vendiste.'
          when e.dif_ventas is not null then case when e.dif_ventas > 0
              then 'Vendiste ' || public.conta_euros_exactos(e.vendido) || ' y la liquidación dice ' || public.conta_euros_exactos(e.l_pedidos) || ': liquida ' || public.conta_euros_exactos(e.dif_ventas) || ' de menos.'
              else 'La liquidación dice ' || public.conta_euros_exactos(e.l_pedidos) || ' y vendiste ' || public.conta_euros_exactos(e.vendido) || ': liquida ' || public.conta_euros_exactos(-e.dif_ventas) || ' de más.' end
          else case when e.dif_cobro > 0
              then 'Dice que paga ' || public.conta_euros_exactos(e.l_pagan) || ' y al banco llegaron ' || public.conta_euros_exactos(e.l_banco) || ': faltan ' || public.conta_euros_exactos(e.dif_cobro) || '.'
              else 'Dice que paga ' || public.conta_euros_exactos(e.l_pagan) || ' y al banco llegaron ' || public.conta_euros_exactos(e.l_banco) || ': ' || public.conta_euros_exactos(-e.dif_cobro) || ' de más.' end end
        when 'falta_factura' then case when e.faltan_facturas = 1 then 'Falta su factura de comisión: cuando llegue a Compras, se engancha.'
                                       else 'Faltan ' || e.faltan_facturas || ' facturas de comisión: cuando lleguen a Compras, se enganchan.' end
        when 'esperando_cobro' then 'Esperando el cobro: ' || public.conta_euros_exactos(coalesce(e.l_pagan, 0)) ||
                                    case when v_hoy > e.plazo then ', y ya debería haber llegado al banco.' else '.' end
        else case when e.todo_referencia then 'De antes del cierre: de referencia (la lleva Diez).'
                  when e.reclamado_sin_llegar > 0 then 'Cuadra, con ' || public.conta_euros_exactos(e.reclamado_sin_llegar) || ' reclamados que aún no han llegado.'
                  when jsonb_array_length(e.resoluciones) > 0 then 'Cuadra, con ' || case when jsonb_array_length(e.resoluciones) = 1 then 'una diferencia resuelta' else jsonb_array_length(e.resoluciones) || ' diferencias resueltas' end || '.'
                  else 'Cuadra: lo vendido, la liquidación, su factura y el cobro.' end
      end,
      'piezas', jsonb_build_object(
        'vendido', jsonb_build_object('via', case when e.channel_id is not null then 'pedidos' when e.sin_vendido then 'liquidacion' else 'facturas' end,
                                      'total', case when e.sin_vendido then null else e.vendido end, 'pedidos', e.pedidos, 'facturas', e.facturas_vendidas),
        'liquidacion', jsonb_build_object('n', e.n_liq, 'ventas', e.l_ventas, 'pedidos_total', e.l_pedidos, 'comision', e.l_comision, 'pagan', e.l_pagan,
                                          'otros', case when e.l_pagan is not null then round(e.l_ventas - e.l_comision - e.l_pagan, 2) end,
                                          'referencia', e.todo_referencia and e.n_liq > 0),
        'factura', jsonb_build_object('faltan', e.faltan_facturas),
        'cobro', jsonb_build_object('esperado', e.l_pagan, 'llegado', e.l_banco, 'por_cobrar', e.por_cobrar)),
      'liquidaciones', coalesce(e.liquidaciones, '[]'::jsonb),
      'resoluciones', e.resoluciones,
      'reclamado_sin_llegar', e.reclamado_sin_llegar,
      'avisos', (select coalesce(jsonb_agg(a), '[]'::jsonb) from (
                  select jsonb_build_object('tipo', 'local_cerrado', 'texto', 'Llegan ventas de ' || e.local || ', que está cerrado: revisa de qué local son.') a
                   where e.local_id is not null and e.local_abierto is false and e.n_liq > 0 and not e.todo_referencia
                  union all
                  select jsonb_build_object('tipo', 'tienda_cambiada', 'cambio_id', c->>'id',
                                            'texto', 'La tienda «' || (c->>'antes') || '» llega como «' || (c->>'ahora') || '»: confírmalo con un clic.')
                    from jsonb_array_elements(coalesce(e.cambios, '[]'::jsonb)) c) z),
      'plazo', e.plazo)
    order by e.d2 desc, e.canal, e.local nulls last), '[]'::jsonb)
    into v_r
    from estado e;
  return v_r;
end $$;


--
-- Name: FUNCTION conta_liquidaciones(p_company uuid, p_desde date, p_hasta date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_liquidaciones(p_company uuid, p_desde date, p_hasta date) IS 'V02 · E2. EL MOTOR: una fila por intermediario, local y periodo con sus cuatro piezas (lo vendido, la liquidación, su factura de comisión y el cobro), su estado y la frase. También los periodos con ventas y sin liquidación. Solo lee.';


--
-- Name: conta_llave_de(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_llave_de(p_user uuid, p_credential_id text, p_rp_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('id', id, 'public_key', public_key, 'algoritmo', algoritmo, 'sign_count', sign_count, 'dispositivo', dispositivo)
    from public.conta_llave where user_id = p_user and credential_id = p_credential_id and rp_id = lower(p_rp_id) and revoked_at is null
$$;


--
-- Name: conta_llave_guardar(uuid, uuid, text, text, text, integer, bigint, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_llave_guardar(p_user uuid, p_reto uuid, p_reto_huella text, p_credential_id text, p_public_key text, p_algoritmo integer, p_sign_count bigint, p_rp_id text, p_dispositivo text, p_transports text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_r public.conta_pago_reto; v_id uuid; v_codigo uuid;
begin
  select * into v_r from public.conta_pago_reto where id = p_reto and user_id = p_user and proposito = 'registrar' for update;
  if v_r.id is null or v_r.used_at is not null or v_r.descartado_at is not null or v_r.expires_at < now() or lower(p_reto_huella) <> v_r.reto_huella then
    raise exception 'Este intento de activar la llave ya no vale. Vuelve a empezar.' using errcode = '42501';
  end if;
  select id into v_codigo from public.conta_pago_reto where user_id = p_user and proposito = 'activar_llave' and used_at > now() - interval '10 minutes' and llave_id is null
   order by used_at desc limit 1 for update;
  if v_codigo is null then raise exception 'Para activar una llave nueva, confirma antes que eres tú con el código del correo.' using errcode = '42501'; end if;
  insert into public.conta_llave (user_id, credential_id, public_key, algoritmo, sign_count, rp_id, dispositivo, transports)
  values (p_user, p_credential_id, p_public_key, p_algoritmo, coalesce(p_sign_count, 0), lower(p_rp_id), nullif(left(trim(coalesce(p_dispositivo, '')), 80), ''), coalesce(p_transports, '{}'))
  returning id into v_id;
  update public.conta_pago_reto set used_at = now(), llave_id = v_id where id = p_reto;
  update public.conta_pago_reto set llave_id = v_id where id = v_codigo;
  return jsonb_build_object('llave', v_id, 'frase', format('Llave activada%s. Desde ahora confirmas los pagos con ella.',
    case when nullif(trim(coalesce(p_dispositivo, '')), '') is not null then ' en ' || left(trim(p_dispositivo), 80) else '' end));
end $$;


--
-- Name: conta_llave_quitar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_llave_quitar(p_llave uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_k public.conta_llave;
begin
  select * into v_k from public.conta_llave where id = p_llave and user_id = auth.uid() and revoked_at is null for update;
  if v_k.id is null then raise exception 'Esa llave no es tuya o ya está quitada.' using errcode = 'P0002'; end if;
  update public.conta_llave set revoked_at = now(), revoked_by_name = coalesce(public.conta_nombre_actor(), 'Sumied') where id = p_llave;
  return jsonb_build_object('frase', format('Llave quitada%s. Desde ese dispositivo, Sumied te pedirá tu PIN de pago.',
    case when v_k.dispositivo is not null then ' (' || v_k.dispositivo || ')' else '' end));
end $$;


--
-- Name: conta_llave_usada(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_llave_usada(p_llave uuid, p_sign_count bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_k public.conta_llave;
begin
  select * into v_k from public.conta_llave where id = p_llave and revoked_at is null for update;
  if v_k.id is null then return jsonb_build_object('ok', false, 'porque', 'Esa llave ya no está activa.'); end if;
  if coalesce(p_sign_count, 0) > 0 and coalesce(p_sign_count, 0) <= v_k.sign_count then
    update public.conta_llave set revoked_at = now(), revoked_by_name = 'Sumied (el contador de la llave no subió: puede estar copiada)' where id = p_llave;
    return jsonb_build_object('ok', false, 'porque', 'Esta llave parece copiada (su contador no ha subido) y la hemos quitado. Confirma con tu PIN de pago y vuelve a activar tu llave con el código del correo.');
  end if;
  update public.conta_llave set sign_count = greatest(sign_count, coalesce(p_sign_count, 0)), last_used_at = now() where id = p_llave;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: conta_llaves_de(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_llaves_de(p_user uuid, p_rp_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('credential_id', credential_id, 'transports', transports)), '[]'::jsonb)
    from public.conta_llave where user_id = p_user and rp_id = lower(p_rp_id) and revoked_at is null
$$;


--
-- Name: conta_llaves_mias(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_llaves_mias() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'direccion', rp_id, 'dispositivo', dispositivo, 'creada', created_at, 'usada', last_used_at) order by created_at), '[]'::jsonb)
    from public.conta_llave where user_id = auth.uid() and revoked_at is null
$$;


--
-- Name: conta_llegada_pdf_subido(uuid, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_llegada_pdf_subido(p_inbox uuid, p_ruta text, p_nombre text, p_tipo text, p_bytes integer, p_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_d public.document_inbox;
begin
  select * into v_d from public.document_inbox where id = p_inbox;
  if v_d.id is null or not public.belongs_to_account(v_d.account_id) then raise exception 'Ese documento no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_d.account_id) then
    raise exception 'Solo un administrador o un encargado sube el PDF de un documento.' using errcode = '42501';
  end if;
  if v_d.status <> 'falta_pdf' then raise exception 'A ese documento no le falta el PDF.' using errcode = '22023'; end if;
  if coalesce(p_ruta, '') not like v_d.account_id::text || '/%' then raise exception 'El fichero no es de esta cuenta.' using errcode = '22023'; end if;
  update public.document_inbox set file_bucket = 'receipt-uploads', file_path = p_ruta, file_name = p_nombre, mime_type = p_tipo,
         size_bytes = p_bytes, sha256 = p_sha256, status = 'recibido', reason = null, updated_at = now()
   where id = p_inbox;
  return jsonb_build_object('id', p_inbox, 'ruta', p_ruta, 'mensaje', format('Subido «%s»: lo leo ahora.', p_nombre));
end $$;


--
-- Name: FUNCTION conta_llegada_pdf_subido(p_inbox uuid, p_ruta text, p_nombre text, p_tipo text, p_bytes integer, p_sha256 text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_llegada_pdf_subido(p_inbox uuid, p_ruta text, p_nombre text, p_tipo text, p_bytes integer, p_sha256 text) IS 'S01g. «Subir el PDF» de una llegada a la que le faltaba: el fichero va a la misma llegada y queda recibido, para leerlo.';


--
-- Name: conta_local_de_tienda(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_local_de_tienda(p_account uuid, p_texto text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_dir text;
  v_clave text;
  v_ids uuid[];
begin
  if p_account is null or p_texto is null then return null; end if;
  -- La dirección va entre los últimos paréntesis: «Marca (Calle …, Madrid, ES, 28027)».
  -- Sin paréntesis, el texto entero. De la dirección, lo de antes de la primera coma.
  v_dir := coalesce(substring(p_texto from '\(([^()]*)\)\s*$'), p_texto);
  v_clave := public.conta_clave_direccion(split_part(v_dir, ',', 1));
  if v_clave is null then return null; end if;
  select array_agg(l.id) into v_ids
    from public.locations l
   where l.account_id = p_account
     and public.conta_clave_direccion(l.address) = v_clave;
  if coalesce(array_length(v_ids, 1), 0) <> 1 then return null; end if;
  return v_ids[1];
end $_$;


--
-- Name: FUNCTION conta_local_de_tienda(p_account uuid, p_texto text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_local_de_tienda(p_account uuid, p_texto text) IS 'V01 · El local de la cuenta cuya dirección es la de la tienda (entre los últimos paréntesis). Null si no casa con ninguno o casa con más de uno.';


--
-- Name: conta_local_direcciones_guardar(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_local_direcciones_guardar(p_location uuid, p_direcciones text[], p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_nombre text; v_n int; v_inv uuid; v_buscadas int := 0; v_ligadas int := 0; v_r text; v_locales int := 0;
begin
  select account_id, name into v_acc, v_nombre from public.locations where id = p_location;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Ese local no es de tu cuenta.' using errcode = '42501'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta cambia las direcciones de un local.' using errcode = '42501';
  end if;
  delete from public.location_address_alias where location_id = p_location;
  insert into public.location_address_alias (account_id, location_id, address, created_by_name)
  select distinct on (lower(btrim(d))) v_acc, p_location, btrim(d), coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor())
    from unnest(coalesce(p_direcciones, '{}'::text[])) d where btrim(coalesce(d, '')) <> '';
  get diagnostics v_n = row_count;
  -- S01j·2 · Con la dirección nueva, las liquidaciones sin local que ahora lo tienen sin adivinar (por el texto de su tienda), antes de buscar facturas.
  update public.channel_settlement cs set location_id = p_location, updated_at = now()
    from public.platform_store ps
   where cs.account_id = v_acc and cs.location_id is null and ps.id = cs.store_id and ps.account_id = v_acc and ps.location_id is null
     and public._conta_local_de_texto(v_acc, array[coalesce(ps.external_text, cs.external_location_text)]) = p_location;
  get diagnostics v_locales = row_count;
  -- Con la dirección nueva, las facturas de plataformas sin ligar pueden encontrar ya su liquidación (S01i).
  if to_regprocedure('public._conta_comision_buscar(uuid)') is not null then
    for v_inv in
      select si.id from public.supplier_invoice si
        join public.party_role ps on ps.account_id = si.account_id and ps.role = 'supplier' and ps.supplier_id = si.supplier_id
        join public.party_role pl on pl.account_id = ps.account_id and pl.party_id = ps.party_id and pl.role = 'platform'
       where si.account_id = v_acc and si.status not in ('anulada', 'descartada', 'pagada')
         and not exists (select 1 from public.channel_settlement_invoice k where k.supplier_invoice_id = si.id)
    loop
      v_buscadas := v_buscadas + 1;
      v_r := public._conta_comision_buscar(v_inv);
      if exists (select 1 from public.channel_settlement_invoice k where k.supplier_invoice_id = v_inv) then v_ligadas := v_ligadas + 1; end if;
    end loop;
  end if;
  return jsonb_build_object('guardadas', v_n, 'buscadas', v_buscadas, 'ligadas', v_ligadas, 'liquidaciones', v_locales,
    'texto', format('%s: %s.%s%s', v_nombre,
      case when v_n = 0 then 'sin otras direcciones' when v_n = 1 then 'guardada 1 otra dirección' else format('guardadas %s otras direcciones', v_n) end,
      case when v_buscadas = 0 then ''
           else format(' Vuelta a buscar la liquidación de %s %s sin ligar: %s.', v_buscadas,
             case when v_buscadas = 1 then 'factura de plataformas' else 'facturas de plataformas' end,
             case when v_ligadas = 0 then 'ninguna se ha ligado aún' when v_ligadas = 1 then '1 ligada ahora' else format('%s ligadas ahora', v_ligadas) end) end,
      case when v_locales = 0 then ''
           when v_locales = 1 then format(' Puesto %s en 1 liquidación que no tenía local.', v_nombre)
           else format(' Puesto %s en %s liquidaciones que no tenían local.', v_nombre, v_locales) end));
end $$;


--
-- Name: conta_lote_aclarar(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_aclarar(p_issue uuid, p_decision text, p_nota text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_i public.supplier_batch_issue; v_quedan int; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), 'Alguien de la cuenta');
begin
  select * into v_i from public.supplier_batch_issue where id = p_issue for update;
  if v_i.id is null or not public.belongs_to_account(v_i.account_id) then raise exception 'Eso no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_i.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta decide lo que hay que aclarar.' using errcode = '42501';
  end if;
  if p_decision not in ('aceptada', 'reclamada', 'abierta') then raise exception 'Se da por buena, se reclama o se vuelve a abrir.' using errcode = '22023'; end if;
  if p_decision = 'reclamada' and coalesce(btrim(p_nota), '') = '' then raise exception 'Di qué se reclama.' using errcode = '22023'; end if;
  update public.supplier_batch_issue
     set status = p_decision, note = nullif(btrim(p_nota), ''),
         resolved_at = case when p_decision = 'abierta' then null else now() end,
         resolved_by = case when p_decision = 'abierta' then null else auth.uid() end,
         resolved_by_name = case when p_decision = 'abierta' then null else v_quien end
   where id = p_issue;
  if v_i.supplier_invoice_id is not null then
    select count(*) into v_quedan from public.supplier_batch_issue where supplier_invoice_id = v_i.supplier_invoice_id and status <> 'aceptada';
    update public.supplier_invoice f
       set reading = jsonb_set(coalesce(f.reading, '{}'::jsonb), '{cruce,aclarar}', to_jsonb(v_quedan)),
           reading_confidence = case when v_quedan = 0 and f.reading->>'confianza' = 'seguro' and f.reading->'cruce'->>'estado' is not null then 'seguro' else 'duda' end,
           needs_review = not (v_quedan = 0 and f.reading->>'confianza' = 'seguro' and f.reading->'cruce'->>'estado' is not null),
           updated_at = now()
     where f.id = v_i.supplier_invoice_id and f.status = 'en_revision';
  end if;
  return jsonb_build_object('estado', p_decision, 'quedan', coalesce(v_quedan, 0),
    'texto', case p_decision when 'aceptada' then 'Dado por bueno' when 'reclamada' then 'Apuntado para reclamar a Catcher' else 'Vuelto a abrir' end
             || coalesce(' (' || v_i.order_code || ')', '') || '. '
             || case when v_i.supplier_invoice_id is null then '' when coalesce(v_quedan, 0) = 0 then 'A su factura no le queda nada por aclarar.'
                     else 'A su factura le ' || case v_quedan when 1 then 'queda 1 cosa' else 'quedan ' || v_quedan || ' cosas' end || '.' end);
end $$;


--
-- Name: FUNCTION conta_lote_aclarar(p_issue uuid, p_decision text, p_nota text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_aclarar(p_issue uuid, p_decision text, p_nota text, p_quien_nombre text) IS 'E05 · La persona decide sobre una cosa por aclarar de un lote: aceptada (se da por buena), reclamada (con lo que se reclama) o abierta otra vez. Rehace si su factura queda segura.';


--
-- Name: conta_lote_cruce_guardar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_cruce_guardar(p_lote uuid, p_cruce jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_l public.supplier_batch; a jsonb; k text; v jsonb;
  v_bien int := 0; v_mal int := 0; v_n int; v_abiertas int;
begin
  select * into v_l from public.supplier_batch where id = p_lote for update;
  if v_l.id is null or not (public.belongs_to_account(v_l.account_id) or auth.role() = 'service_role') then raise exception 'Ese lote no está.' using errcode = 'P0002'; end if;
  if not (public.current_user_is_admin_or_manager_of(v_l.account_id) or auth.role() = 'service_role') then
    raise exception 'Solo un administrador o un encargado de la cuenta cruza las facturas.' using errcode = '42501';
  end if;
  if coalesce(jsonb_typeof(p_cruce->'facturas'), '') <> 'object' or coalesce(jsonb_typeof(p_cruce->'porAclarar'), '') <> 'array' then
    raise exception 'El cruce no trae sus facturas y lo que hay que aclarar.' using errcode = '22023';
  end if;

  -- Lo abierto se rehace; lo que ya decidió una persona se queda.
  delete from public.supplier_batch_issue where batch_id = p_lote and status = 'abierta';
  for a in select * from jsonb_array_elements(p_cruce->'porAclarar') loop
    -- Si la persona ya decidió sobre ese mismo pedido y motivo, no se vuelve a abrir.
    if exists (select 1 from public.supplier_batch_issue i where i.batch_id = p_lote and i.status <> 'abierta' and i.reason = a->>'motivo'
                and i.order_code is not distinct from a->'pedido'->>'codigo' and i.ordered_at is not distinct from nullif(a->'pedido'->>'momento', '')::timestamptz
                and i.supplier_invoice_id is not distinct from (select f.id from public.supplier_invoice f where f.batch_id = p_lote and f.invoice_number = a->>'factura' limit 1)) then
      continue;
    end if;
    insert into public.supplier_batch_issue (account_id, batch_id, supplier_invoice_id, reason, order_code, ordered_at, text, difference_cents)
    values (v_l.account_id, p_lote, (select f.id from public.supplier_invoice f where f.batch_id = p_lote and f.invoice_number = a->>'factura' limit 1),
            a->>'motivo', a->'pedido'->>'codigo', nullif(a->'pedido'->>'momento', '')::timestamptz, a->>'texto', nullif(a->>'diferencia', '')::int);
  end loop;

  -- Con qué venta casó cada pedido.
  update public.supplier_batch_order o set sale_id = null where o.batch_id = p_lote;
  for k, v in select * from jsonb_each(coalesce(p_cruce->'casados', '{}'::jsonb)) loop
    update public.supplier_batch_order o set sale_id = (v #>> '{}')::uuid
     where o.batch_id = p_lote and o.invoice_number || '|' || o.order_code || '|' || coalesce(to_char(o.ordered_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), '') = k;
  end loop;

  -- Cada factura en revisión: segura solo si el cruce la da por buena, no le queda nada
  -- abierto ni reclamado y ya era segura al leerla.
  for k, v in select * from jsonb_each(p_cruce->'facturas') loop
    select count(*) into v_abiertas from public.supplier_batch_issue i join public.supplier_invoice f on f.id = i.supplier_invoice_id
     where f.batch_id = p_lote and f.invoice_number = k and i.status <> 'aceptada';
    update public.supplier_invoice f
       set reading = jsonb_set(coalesce(f.reading, '{}'::jsonb), '{cruce}', jsonb_build_object('estado', v->>'estado', 'aclarar', v_abiertas, 'cruzada', now())),
           reading_confidence = case when v->>'estado' = 'seguro' and v_abiertas = 0 and f.reading->>'confianza' = 'seguro' then 'seguro' else 'duda' end,
           needs_review = not (v->>'estado' = 'seguro' and v_abiertas = 0 and f.reading->>'confianza' = 'seguro'),
           updated_at = now()
     where f.batch_id = p_lote and f.invoice_number = k and f.status = 'en_revision';
    if v->>'estado' = 'seguro' and v_abiertas = 0 then v_bien := v_bien + 1; else v_mal := v_mal + 1; end if;
  end loop;
  select count(*) into v_n from public.supplier_batch_issue where batch_id = p_lote and status = 'abierta';

  update public.supplier_batch set crossed_at = now(),
         cross_summary = jsonb_build_object('cuadran', v_bien, 'aclarar', v_mal, 'abiertas', v_n, 'totales', p_cruce->'totales', 'coste', coalesce(p_cruce->'coste', '[]'::jsonb), 'por', p_quien_nombre)
   where id = p_lote;
  return jsonb_build_object('cuadran', v_bien, 'aclarar', v_mal, 'abiertas', v_n,
    'texto', 'Cruzada la ' || v_l.label || ': ' || (v_bien + v_mal) || case when v_bien + v_mal = 1 then ' factura' else ' facturas' end || ', '
             || v_bien || case v_bien when 1 then ' cuadra' else ' cuadran' end
             || case when v_mal > 0 then ' y ' || v_mal || ' por aclarar' else '' end
             || case when v_n > 0 then ' (' || v_n || case v_n when 1 then ' cosa que mirar' else ' cosas que mirar' end || ')' else '' end || '.');
end $$;


--
-- Name: FUNCTION conta_lote_cruce_guardar(p_lote uuid, p_cruce jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_cruce_guardar(p_lote uuid, p_cruce jsonb, p_quien_nombre text) IS 'E05 · Guarda el cruce de un lote (catcherCruces.ts): lo que hay que aclarar (rehace lo abierto, respeta lo decidido), con qué venta casó cada pedido y si cada factura en revisión queda segura.';


--
-- Name: conta_lote_pago_proponer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_pago_proponer(p_lote uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_l public.supplier_batch; v_prepago public.company_account; v_serie int; v_fecha date; v_total numeric := 0; v_n int := 0;
  v_sin_cuenta text[]; v_lineas jsonb := '[]'::jsonb; f record; r jsonb; v_entry uuid; v_eur text;
begin
  select * into v_l from public.supplier_batch where id = p_lote for update;
  if v_l.id is null or not public.belongs_to_account(v_l.account_id) then raise exception 'Ese lote no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_l.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta propone pagos.' using errcode = '42501';
  end if;
  if v_l.payment_entry_id is not null and exists (select 1 from public.journal_entry e where e.id = v_l.payment_entry_id and e.status in ('propuesto', 'borrador', 'validado')) then
    return jsonb_build_object('id', v_l.payment_entry_id, 'ya_estaba', true, 'texto', 'El pago de la ' || v_l.label || ' ya estaba propuesto: no se ha creado otro.');
  end if;

  select * into v_prepago from public.company_account where account_id = v_l.account_id and company_id = v_l.company_id and code = '40700001';
  if v_prepago.id is null then
    raise exception 'Falta la 40700001 «Saldo prepago Catcher» en el plan de la empresa: dala de alta antes de proponer el pago.' using errcode = 'P0002';
  end if;

  -- Cada factura del lote, a la cuenta de su proveedor (su enlace «principal»).
  select array_agg(i.invoice_number order by i.invoice_number) into v_sin_cuenta
    from public.supplier_invoice i
   where i.batch_id = p_lote and i.status <> 'anulada'
     and not exists (select 1 from public.company_account_link k join public.company_account ca on ca.id = k.company_account_id and ca.account_id = k.account_id
                      where k.account_id = i.account_id and k.company_id = v_l.company_id and k.entity = 'supplier' and k.role = 'principal' and k.entity_id = i.supplier_id::text);
  if v_sin_cuenta is not null then
    raise exception 'No se puede proponer el pago: % sin proveedor o sin su cuenta (%). Si es Catcher, dalo de alta y dale su cuenta.',
      case array_length(v_sin_cuenta, 1) when 1 then '1 factura' else array_length(v_sin_cuenta, 1) || ' facturas' end, array_to_string(v_sin_cuenta[1:5], ', ')
      using errcode = '23514';
  end if;

  for f in
    select i.invoice_number, i.grand_total, i.location_id, i.invoice_date, ca.code
      from public.supplier_invoice i
      join public.company_account_link k on k.account_id = i.account_id and k.company_id = v_l.company_id and k.entity = 'supplier' and k.role = 'principal' and k.entity_id = i.supplier_id::text
      join public.company_account ca on ca.id = k.company_account_id and ca.account_id = k.account_id
     where i.batch_id = p_lote and i.status <> 'anulada'
     order by i.invoice_number
  loop
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', f.code, 'debe', f.grand_total, 'haber', 0,
                  'local_id', f.location_id, 'comun', f.location_id is null, 'documento', f.invoice_number));
    v_total := v_total + f.grand_total; v_n := v_n + 1;
    v_fecha := greatest(v_fecha, coalesce(f.invoice_date, v_l.period_to));
  end loop;
  if v_n = 0 then raise exception 'El lote no tiene facturas que pagar.' using errcode = '23514'; end if;
  -- Lo que baja la 40700001 = lo que suman las facturas = lo que sumaba el Excel.
  if v_l.grand_total is not null and round(v_l.grand_total * 100) <> round(v_total * 100) then
    raise exception 'Las facturas del lote suman % y el lote (el Excel) %: no se paga hasta aclararlo.', v_total, v_l.grand_total using errcode = '23514';
  end if;
  v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', '40700001', 'debe', 0, 'haber', v_total, 'local_id', null, 'comun', true, 'documento', v_l.label));

  select coalesce((select b.treasury_series from public.bank_settings b where b.account_id = v_l.account_id and b.company_id = v_l.company_id limit 1), 3) into v_serie;
  r := public.journal_entry_proponer(v_l.company_id,
    jsonb_build_object('series', v_serie, 'fecha', coalesce(v_fecha, v_l.period_to), 'concepto', left('Pago desde el ' || v_prepago.name || ' · ' || v_l.label, 200),
                       'source_type', 'supplier_payment', 'source_id', p_lote, 'confianza', 'seguro',
                       'porque', 'Catcher paga a los riders y se cobra su comisión del saldo prepago: las facturas de la quincena se pagan contra la 40700001.',
                       'documento', v_l.label),
    v_lineas, null, p_quien_nombre);
  v_entry := (r->>'id')::uuid;
  update public.supplier_batch set payment_entry_id = v_entry where id = p_lote;
  update public.supplier_invoice set payment_entry_id = v_entry, updated_at = now() where batch_id = p_lote and status <> 'anulada';

  v_eur := replace(replace(replace(to_char(v_total, 'FM999G999G990D00'), ',', '#'), '.', ','), '#', '.') || ' €';
  return jsonb_build_object('id', v_entry, 'ya_estaba', false, 'facturas', v_n, 'total', v_total, 'serie', v_serie,
    'texto', 'Propuesto el pago de la ' || v_l.label || ': ' || v_n || case v_n when 1 then ' factura, ' else ' facturas, ' end || v_eur
             || ' desde la 40700001 «' || v_prepago.name || '» (serie ' || v_serie || ').');
end $$;


--
-- Name: FUNCTION conta_lote_pago_proponer(p_lote uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_pago_proponer(p_lote uuid, p_quien_nombre text) IS 'E05 · Propone el pago de un lote de Catcher contra el saldo prepago (40700001), en la serie de tesorería: una línea por factura a la cuenta de su proveedor y el total al haber de la 40700001. Una vez por lote.';


--
-- Name: conta_lote_pedidos_app(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_pedidos_app(p_lote uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.supplier_batch;
begin
  select * into v_l from public.supplier_batch where id = p_lote;
  if v_l.id is null or not (public.belongs_to_account(v_l.account_id) or auth.role() = 'service_role') then raise exception 'Ese lote no está.' using errcode = 'P0002'; end if;
  -- Un día antes y uno después: un pedido de las 23:50 puede ir en la factura del día siguiente.
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', s.id, 'codigo', coalesce(s.pos_short_code, s.platform_order_code, ''), 'momento', s.sold_at,
                                        'localId', s.location_id, 'marcaId', s.brand_id, 'canalId', s.channel_id,
                                        'estado', coalesce(s.delivery_state, ''), 'precio', s.transport_price) order by s.sold_at)
      from public.sale s
     where s.account_id = v_l.account_id and s.carrier_code = v_l.provider
       and s.sold_at >= ((v_l.period_from - 1)::timestamp at time zone 'Europe/Madrid')
       and s.sold_at <  ((v_l.period_to + 2)::timestamp at time zone 'Europe/Madrid')), '[]'::jsonb);
end $$;


--
-- Name: FUNCTION conta_lote_pedidos_app(p_lote uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_pedidos_app(p_lote uuid) IS 'E05 · Los pedidos que la app mandó al proveedor del lote (sale.carrier_code) en su periodo, un día antes y uno después (hora de Madrid), para cruzarlos con su Excel de pedidos. Solo lee.';


--
-- Name: conta_lote_registrar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_registrar(p_company uuid, p_lote jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_acc uuid; v_ya public.supplier_batch; v_lote uuid;
  v_desde date := nullif(p_lote->>'desde', '')::date;
  v_hasta date := nullif(p_lote->>'hasta', '')::date;
  v_prov text := coalesce(p_lote->>'proveedor', '');
  v_riders uuid; v_catcher uuid; v_catcher_nuevo boolean := false;
  f jsonb; v_pdf jsonb; v_in uuid; v_fac uuid; v_sup uuid; v_nif text; v_rep uuid; v_conf text; v_loc uuid;
  v_n int := 0; v_rep_n int := 0; v_sin_pdf int := 0; v_ya_pdf int := 0;
  v_base numeric := 0; v_cuota numeric := 0; v_total numeric := 0;
  v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), 'Alguien de la cuenta');
  v_eur text;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta sube facturas.' using errcode = '42501';
  end if;
  if v_prov <> 'catcher' then raise exception 'Solo se suben lotes de Catcher.' using errcode = '22023'; end if;
  if v_desde is null or v_hasta is null or v_hasta < v_desde then raise exception 'El lote no dice de qué periodo es.' using errcode = '22023'; end if;
  -- Sin la clave, jsonb_typeof da NULL y «NULL <> …» no frena: con coalesce.
  if coalesce(jsonb_typeof(p_lote->'facturas'), '') <> 'array' or jsonb_array_length(p_lote->'facturas') = 0 then
    raise exception 'El lote no trae ninguna factura.' using errcode = '22023';
  end if;

  -- La misma quincena dos veces: no se crea nada, y se dice.
  select * into v_ya from public.supplier_batch
   where account_id = v_acc and company_id = p_company and provider = v_prov and period_from = v_desde and period_to = v_hasta;
  if v_ya.id is not null then
    return jsonb_build_object('lote_id', v_ya.id, 'ya_estaba', true, 'facturas', v_ya.invoice_count, 'total', v_ya.grand_total,
      'texto', 'La ' || v_ya.label || ' ya estaba subida (' || v_ya.invoice_count || ' facturas, ' ||
               coalesce(v_ya.created_by_name, 'alguien') || ', ' || to_char(v_ya.created_at at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI') || '). No se ha creado nada.');
  end if;

  -- El proveedor genérico «Riders»: el que lleva la 41000100 como su cuenta.
  select l.entity_id::uuid into v_riders
    from public.company_account_link l
    join public.company_account ca on ca.id = l.company_account_id and ca.account_id = l.account_id and ca.company_id = l.company_id
   where l.account_id = v_acc and l.company_id = p_company and l.entity = 'supplier' and l.role = 'principal' and ca.code = '41000100'
   order by l.created_at limit 1;
  if v_riders is null and exists (select 1 from jsonb_array_elements(p_lote->'facturas') x where x->>'tipo' in ('rider', 'flota')) then
    raise exception 'No hay ningún proveedor con la 41000100 «Riders» como cuenta: dale esa cuenta al proveedor de los riders antes de subir la quincena.' using errcode = 'P0002';
  end if;

  insert into public.supplier_batch (account_id, company_id, provider, period_from, period_to, label, files, warnings, created_by, created_by_name)
  values (v_acc, p_company, v_prov, v_desde, v_hasta, coalesce(nullif(p_lote->>'etiqueta', ''), 'quincena del ' || to_char(v_desde, 'DD/MM/YYYY')),
          coalesce(p_lote->'ficheros', '[]'::jsonb), coalesce(p_lote->'avisos', '[]'::jsonb), auth.uid(), v_quien)
  returning id into v_lote;

  for f in select * from jsonb_array_elements(p_lote->'facturas') loop
    if f->>'tipo' not in ('rider', 'flota', 'catcher') then raise exception 'La factura % no dice de qué tipo es.', f->>'numero' using errcode = '22023'; end if;
    if coalesce(f->>'numero', '') = '' then raise exception 'Una factura del lote no tiene número.' using errcode = '22023'; end if;
    if round((f->>'base')::numeric * 100) + round((f->>'cuota')::numeric * 100) <> round((f->>'total')::numeric * 100) then
      raise exception 'La factura %: base + IVA no es el total.', f->>'numero' using errcode = '22023';
    end if;
    v_nif := nullif(regexp_replace(upper(regexp_replace(coalesce(f->'emisor'->>'nif', ''), '[^A-Za-z0-9]', '', 'g')), '^ES(?=[A-Z0-9]{9}$)', ''), '');
    v_loc := nullif(f->>'localId', '')::uuid;
    if v_loc is not null and not exists (select 1 from public.locations where id = v_loc and account_id = v_acc) then
      raise exception 'La factura %: ese local no es de esta cuenta.', f->>'numero' using errcode = '22023';
    end if;

    -- Su proveedor: «Riders» para riders y flotas; Catcher, por su NIF (si no está, se propone darlo de alta).
    if f->>'tipo' = 'catcher' then
      if v_catcher is null then
        select s.id into v_catcher from public.supplier s
         where s.account_id = v_acc and s.archived_at is null and v_nif is not null
           and regexp_replace(upper(regexp_replace(coalesce(s.tax_id, ''), '[^A-Za-z0-9]', '', 'g')), '^ES(?=[A-Z0-9]{9}$)', '') = v_nif
         order by s.created_at limit 1;
        v_catcher_nuevo := v_catcher is null;
      end if;
      v_sup := v_catcher;
    else
      v_sup := v_riders;
    end if;

    -- ¿Ya estaba? El mismo emisor, el mismo número (su clave) y el mismo total.
    select i.id into v_rep from public.supplier_invoice i
     where i.account_id = v_acc and i.status <> 'anulada' and i.not_duplicate_confirmed_at is null
       and public.conta_clave_numero(i.invoice_number) = public.conta_clave_numero(f->>'numero')
       and round(i.grand_total * 100) = round((f->>'total')::numeric * 100)
       and (i.issuer_tax_id = v_nif or (i.issuer_tax_id is null and v_sup is not null and i.supplier_id = v_sup))
     order by i.created_at limit 1;
    if v_rep is not null then v_rep_n := v_rep_n + 1; continue; end if;

    -- Su PDF, subido ya a receipt-uploads por el navegador.
    v_pdf := f->'pdf';
    v_in := null;
    if v_pdf is null or jsonb_typeof(v_pdf) <> 'object' then
      v_sin_pdf := v_sin_pdf + 1;
    else
      if left(v_pdf->>'ruta', 37) <> v_acc::text || '/' then raise exception 'La factura %: la ruta de su PDF no es de esta cuenta.', f->>'numero' using errcode = '22023'; end if;
      if coalesce(v_pdf->>'sha256', '') !~ '^[0-9a-f]{64}$' then raise exception 'La factura %: la huella de su PDF no es un sha256.', f->>'numero' using errcode = '22023'; end if;
      if not exists (select 1 from storage.objects o where o.bucket_id = 'receipt-uploads' and o.name = v_pdf->>'ruta') then
        raise exception 'El PDF de la factura % no está subido.', f->>'numero' using errcode = 'P0002';
      end if;
      select id into v_in from public.document_inbox where account_id = v_acc and sha256 = v_pdf->>'sha256' and status <> 'descartado' limit 1;
      if v_in is not null then v_ya_pdf := v_ya_pdf + 1; v_rep_n := v_rep_n + 1; continue; end if;
      insert into public.document_inbox (account_id, company_id, channel, status, file_path, file_name, mime_type, size_bytes, sha256, reason, created_by, created_by_name)
      values (v_acc, p_company, 'portal', 'leido', v_pdf->>'ruta', v_pdf->>'nombre', 'application/pdf', nullif(v_pdf->>'bytes', '')::int, v_pdf->>'sha256',
              'De la ' || coalesce(p_lote->>'etiqueta', 'quincena') || ' de Catcher.', auth.uid(), v_quien)
      returning id into v_in;
    end if;

    -- Segura solo si cumple la norma, su PDF dice lo mismo, tiene proveedor y cada
    -- tienda su local (un local, o varios en su reparto: un rider reparte para las
    -- dos tiendas y eso no es un problema).
    v_conf := case when f->>'confianza' = 'seguro' and v_pdf is not null and v_sup is not null
                    and (v_loc is not null or (jsonb_array_length(coalesce(f->'reparto', '[]'::jsonb)) > 0
                         and not exists (select 1 from jsonb_array_elements(f->'reparto') x where coalesce(x->>'localId', '') = '')))
               then 'seguro' else 'duda' end;
    insert into public.supplier_invoice (account_id, company_id, supplier_id, location_id, doc_kind, invoice_number, invoice_date, status, source,
                                         raw_document_url, tax_base_total, tax_total, grand_total, needs_review, notes, created_by_name,
                                         arrival_channel, reading, reading_confidence, inbox_id, batch_id, issuer_name, issuer_tax_id, issuer_address)
    values (v_acc, p_company, v_sup, v_loc, 'invoice', f->>'numero', nullif(f->>'fecha', '')::date, 'en_revision', 'lote',
            v_pdf->>'ruta', (f->>'base')::numeric, (f->>'cuota')::numeric, (f->>'total')::numeric, v_conf <> 'seguro',
            case when v_sup is null then 'Catcher no tiene ficha: dalo de alta con los datos de la factura.'
                 when v_loc is null and (jsonb_array_length(coalesce(f->'reparto', '[]'::jsonb)) = 0
                                         or exists (select 1 from jsonb_array_elements(f->'reparto') x where coalesce(x->>'localId', '') = ''))
                   then 'Una de sus tiendas de Catcher no tiene local: dile cuál es.' end,
            v_quien, 'portal',
            jsonb_build_object(
              'factura', jsonb_build_object('proveedor', jsonb_build_object('nombre', f->'emisor'->>'nombre', 'nif', v_nif),
                                            'numero', f->>'numero', 'fecha', f->>'fecha', 'clase', 'completa',
                                            'tipos', jsonb_build_array(jsonb_build_object('tipo', (f->>'tipoIva')::numeric, 'base', (f->>'base')::numeric, 'cuota', (f->>'cuota')::numeric)),
                                            'base', (f->>'base')::numeric, 'cuota', (f->>'cuota')::numeric, 'total', (f->>'total')::numeric, 'desgloseDe', 'lote'),
              'comprobaciones', coalesce(f->'requisitos', '[]'::jsonb) || coalesce(f->'contraPdf', '[]'::jsonb),
              'confianza', v_conf,
              'lote', jsonb_build_object('proveedor', v_prov, 'tipo', f->>'tipo', 'pedidos', f->'pedidos', 'periodo', f->'periodo', 'reparto', coalesce(f->'reparto', '[]'::jsonb))),
            v_conf, v_in, v_lote, nullif(btrim(f->'emisor'->>'nombre'), ''), v_nif, nullif(btrim(f->'emisor'->>'domicilio'), ''))
    returning id into v_fac;
    insert into public.supplier_invoice_tax (account_id, supplier_invoice_id, vat_pct, base, vat_amount, surcharge_pct, surcharge_amount)
    values (v_acc, v_fac, (f->>'tipoIva')::numeric, (f->>'base')::numeric, (f->>'cuota')::numeric, null, 0);
    if v_in is not null then
      update public.document_inbox set status = 'factura', supplier_invoice_id = v_fac, updated_at = now() where id = v_in;
      insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text, detail)
      values (v_acc, p_company, v_in, v_fac, 'folvy', 'leida',
              'La ' || (f->>'numero') || ' de la quincena de Catcher, del Excel' || case v_conf when 'seguro' then ': cuadra con su PDF.' else ': hay algo que aclarar.' end,
              jsonb_build_object('confianza', v_conf, 'lote', v_lote));
    end if;
    v_n := v_n + 1;
    v_base := v_base + (f->>'base')::numeric; v_cuota := v_cuota + (f->>'cuota')::numeric; v_total := v_total + (f->>'total')::numeric;
  end loop;

  insert into public.supplier_batch_order (account_id, batch_id, invoice_number, supplier_invoice_id, kind, order_code, order_status, ordered_at, tax_base, tax_amount, total)
  select v_acc, v_lote, p->>'factura',
         (select i.id from public.supplier_invoice i where i.batch_id = v_lote and i.invoice_number = p->>'factura' limit 1),
         coalesce(p->>'tipo', ''), coalesce(p->>'codigo', ''), coalesce(p->>'estado', ''), nullif(p->>'momento', '')::timestamptz,
         coalesce((p->>'base')::numeric, 0), coalesce((p->>'cuota')::numeric, 0), coalesce((p->>'total')::numeric, 0)
    from jsonb_array_elements(coalesce(p_lote->'pedidos', '[]'::jsonb)) p;

  update public.supplier_batch set invoice_count = v_n, tax_base_total = v_base, tax_total = v_cuota, grand_total = v_total where id = v_lote;
  if v_catcher_nuevo then
    insert into public.document_activity (account_id, company_id, actor, action, text, detail)
    values (v_acc, p_company, 'folvy', 'proveedor_propuesto', 'Catcher Marketplace no tiene ficha: la doy de alta con los datos de su factura si me dices que sí.', jsonb_build_object('lote', v_lote));
  end if;

  v_eur := replace(replace(replace(to_char(v_total, 'FM999G999G990D00'), ',', '#'), '.', ','), '#', '.') || ' €';
  return jsonb_build_object('lote_id', v_lote, 'ya_estaba', false, 'facturas', v_n, 'ya_estaban', v_rep_n, 'sin_pdf', v_sin_pdf,
    'total', v_total, 'catcher_sin_ficha', v_catcher_nuevo,
    'texto', 'Subida la ' || coalesce(p_lote->>'etiqueta', 'quincena') || ': ' || v_n || case v_n when 1 then ' factura' else ' facturas' end || ' (' || v_eur || ')'
             || case when v_rep_n = 1 then '. 1 ya estaba y no se ha vuelto a apuntar' when v_rep_n > 1 then '. ' || v_rep_n || ' ya estaban y no se han vuelto a apuntar' else '' end
             || case when v_sin_pdf > 0 then '. ' || v_sin_pdf || ' sin su PDF' else '' end || '.');
end $_$;


--
-- Name: FUNCTION conta_lote_registrar(p_company uuid, p_lote jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_registrar(p_company uuid, p_lote jsonb, p_quien_nombre text) IS 'E05 · Registra un lote del proveedor (la quincena de Catcher, leída en el navegador): el lote, sus pedidos, y una entrada en la bandeja y una factura en revisión por PDF. La misma quincena dos veces no crea nada.';


--
-- Name: conta_lote_relectura_empezar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_relectura_empezar(p_relectura uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_r public.conta_lote_relectura;
begin
  update public.conta_lote_relectura set empezada_en = now()
   where id = p_relectura and empezada_en is null and hecha_en is null
  returning * into v_r;
  if v_r.id is null then raise exception 'Esa relectura no está, o ya empezó.' using errcode = 'P0002'; end if;
  return jsonb_build_object('lote', v_r.batch_id, 'cuenta', v_r.account_id, 'quien', v_r.pedida_por_nombre);
end $$;


--
-- Name: FUNCTION conta_lote_relectura_empezar(p_relectura uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_relectura_empezar(p_relectura uuid) IS 'E05 · Marca que una relectura empieza (una sola vez) y dice de qué lote es. Solo el servidor (conta-lote-releer).';


--
-- Name: conta_lote_relectura_guardar(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_relectura_guardar(p_relectura uuid, p_lecturas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_r public.conta_lote_relectura; v_f public.supplier_invoice; x jsonb; v_comp jsonb; v_conf text;
  v_rel int := 0; v_seg int := 0; v_sin int := 0;
begin
  select * into v_r from public.conta_lote_relectura where id = p_relectura for update;
  if v_r.id is null then raise exception 'Esa relectura no está.' using errcode = 'P0002'; end if;
  if v_r.hecha_en is not null then raise exception 'Esa relectura ya está hecha.' using errcode = '23505'; end if;
  if coalesce(jsonb_typeof(p_lecturas), '') <> 'array' then raise exception 'Las lecturas tienen que ser una lista.' using errcode = '22023'; end if;
  for x in select * from jsonb_array_elements(p_lecturas) loop
    select * into v_f from public.supplier_invoice f where f.id = (x->>'factura')::uuid and f.batch_id = v_r.batch_id and f.account_id = v_r.account_id for update;
    if v_f.id is null then raise exception 'Una de las facturas no es de este lote.' using errcode = '22023'; end if;
    if coalesce(jsonb_typeof(x->'contraPdf'), '') <> 'array' or jsonb_array_length(x->'contraPdf') = 0
       or exists (select 1 from jsonb_array_elements(x->'contraPdf') c where coalesce(c->>'id', '') !~ '^pdf_' or jsonb_typeof(c->'ok') <> 'boolean') then
      raise exception 'La lectura de la % no es una lista de comprobaciones del PDF.', v_f.invoice_number using errcode = '22023';
    end if;
    -- Lo que ya decidió una persona no se toca.
    if v_f.status <> 'en_revision' then v_sin := v_sin + 1; continue; end if;
    v_comp := coalesce((select jsonb_agg(c) from jsonb_array_elements(coalesce(v_f.reading->'comprobaciones', '[]'::jsonb)) c where coalesce(c->>'id', '') !~ '^pdf_'), '[]'::jsonb)
              || (x->'contraPdf');
    -- Segura al leer con la misma regla que conta_lote_registrar: todo bien, con su
    -- PDF, con proveedor y cada tienda con su local.
    v_conf := case when not exists (select 1 from jsonb_array_elements(v_comp) c where (c->>'ok')::boolean is not true)
                     and v_f.raw_document_url is not null and v_f.supplier_id is not null
                     and (v_f.location_id is not null or (jsonb_array_length(coalesce(v_f.reading->'lote'->'reparto', '[]'::jsonb)) > 0
                          and not exists (select 1 from jsonb_array_elements(v_f.reading->'lote'->'reparto') r where coalesce(r->>'localId', '') = '')))
                   then 'seguro' else 'duda' end;
    update public.supplier_invoice f
       set reading = jsonb_set(jsonb_set(jsonb_set(coalesce(f.reading, '{}'::jsonb), '{comprobaciones}', v_comp), '{confianza}', to_jsonb(v_conf)),
                               '{relectura}', jsonb_build_object('id', v_r.id, 'cuando', now(), 'sha256', x->>'sha256')),
           updated_at = now()
     where f.id = v_f.id;
    v_rel := v_rel + 1;
    if v_conf = 'seguro' then v_seg := v_seg + 1; end if;
  end loop;
  update public.conta_lote_relectura set releidas = v_rel, seguras = v_seg, sin_tocar = v_sin where id = v_r.id;
  return jsonb_build_object('releidas', v_rel, 'seguras', v_seg, 'sin_tocar', v_sin);
end $$;


--
-- Name: FUNCTION conta_lote_relectura_guardar(p_relectura uuid, p_lecturas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_relectura_guardar(p_relectura uuid, p_lecturas jsonb) IS 'E05 · Guarda la lectura nueva de los PDF de un lote (las comprobaciones pdf_* y la confianza al leer), solo de las facturas que siguen en revisión. Solo el servidor (conta-lote-releer).';


--
-- Name: conta_lote_relectura_hecha(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_relectura_hecha(p_relectura uuid, p_cruce jsonb, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.conta_lote_relectura
     set hecha_en = now(), cruce = p_cruce, error = left(nullif(trim(coalesce(p_error, '')), ''), 500)
   where id = p_relectura and hecha_en is null;
  if not found then raise exception 'Esa relectura no está o ya está hecha.' using errcode = 'P0002'; end if;
end $$;


--
-- Name: FUNCTION conta_lote_relectura_hecha(p_relectura uuid, p_cruce jsonb, p_error text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_relectura_hecha(p_relectura uuid, p_cruce jsonb, p_error text) IS 'E05 · Apunta lo que salió de una relectura (el cruce) o su error. Solo el servidor (conta-lote-releer).';


--
-- Name: conta_lote_releer_lanzar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_releer_lanzar(p_lote uuid, p_quien_nombre text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.supplier_batch; v_id uuid; v_secreto text;
begin
  select * into v_l from public.supplier_batch where id = p_lote;
  if v_l.id is null then raise exception 'Ese lote no está.' using errcode = 'P0002'; end if;
  if nullif(trim(coalesce(p_quien_nombre, '')), '') is null then raise exception 'Hay que decir quién la pide.' using errcode = '22023'; end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  if v_secreto is null then
    raise exception 'Falta cron_secret en el Vault: no se puede llamar a conta-lote-releer.' using errcode = '55000';
  end if;
  insert into public.conta_lote_relectura (account_id, batch_id, pedida_por_nombre)
  values (v_l.account_id, v_l.id, trim(p_quien_nombre))
  returning id into v_id;
  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/conta-lote-releer',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := jsonb_build_object('lote', v_l.id, 'relectura', v_id), timeout_milliseconds := 150000);
  return v_id;
end $$;


--
-- Name: FUNCTION conta_lote_releer_lanzar(p_lote uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_releer_lanzar(p_lote uuid, p_quien_nombre text) IS 'E05 · Pide volver a leer los PDF de un lote desde la base, sin sesión: apunta la relectura y llama a conta-lote-releer con el cron_secret. Solo postgres (lo que se lanza a mano por encargo).';


--
-- Name: conta_lote_releer_pedir(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_lote_releer_pedir(p_lote uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.supplier_batch; v_id uuid;
begin
  select * into v_l from public.supplier_batch where id = p_lote;
  if v_l.id is null or not public.belongs_to_account(v_l.account_id) then raise exception 'Ese lote no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_l.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta vuelve a comprobar las facturas.' using errcode = '42501';
  end if;
  insert into public.conta_lote_relectura (account_id, batch_id, pedida_por, pedida_por_nombre)
  values (v_l.account_id, v_l.id, auth.uid(), nullif(trim(coalesce(p_quien_nombre, public.conta_nombre_actor(), '')), ''))
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: FUNCTION conta_lote_releer_pedir(p_lote uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_lote_releer_pedir(p_lote uuid, p_quien_nombre text) IS 'E05 · Un administrador o un encargado pide volver a leer los PDF de un lote (lo llama conta-lote-releer con su sesión). Devuelve la relectura.';


--
-- Name: conta_mandato_enviado(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_mandato_enviado(p_mandato uuid, p_correo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.conta_mandato set sent_to = coalesce(nullif(lower(trim(p_correo)), ''), sent_to), sent_at = now()
   where id = p_mandato and public.current_user_is_admin_or_manager_of(account_id);
end $$;


--
-- Name: conta_mandato_firmar(text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_mandato_firmar(p_token text, p_nombre text, p_nif text, p_iban text, p_acepto boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v public.conta_mandato; v_iban text := public._pc01e2_iban(regexp_replace(coalesce(p_iban, ''), '[-.]', '', 'g'));
        v_nombre text := nullif(trim(coalesce(p_nombre, '')), ''); v_h json; v_p public.party; v_hoy date := public.conta_hoy();
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{64}$' then raise exception 'Ese enlace no vale.' using errcode = 'P0002'; end if;
  select * into v from public.conta_mandato where token = p_token for update;
  if v.id is null then raise exception 'Ese enlace no vale.' using errcode = 'P0002'; end if;
  if v.status = 'firmado' then raise exception 'Este mandato ya está firmado.' using errcode = '23514'; end if;
  if v.status = 'anulado' then raise exception 'Este enlace ya no vale: te han mandado otro más nuevo.' using errcode = '23514'; end if;
  if v.expires_at < now() then raise exception 'Este enlace ha caducado: pide otro a quien te lo mandó.' using errcode = '23514'; end if;
  if v_nombre is null or length(v_nombre) < 3 then raise exception 'Escribe el nombre de quien firma.' using errcode = '22023'; end if;
  if v_iban is null or not public._pc01e2b_iban_valido(v_iban) then raise exception 'Ese IBAN no es correcto: revisa los dígitos.' using errcode = '22023'; end if;
  if p_acepto is not true then raise exception 'Para firmar, marca que aceptas el mandato.' using errcode = '22023'; end if;
  begin v_h := nullif(current_setting('request.headers', true), '')::json; exception when others then v_h := null; end;
  update public.conta_mandato set status = 'firmado', iban = v_iban, signed_at = now(), signed_name = left(v_nombre, 140),
         signed_tax_id = nullif(upper(regexp_replace(coalesce(p_nif, ''), '[^A-Za-z0-9]', '', 'g')), ''),
         signed_ip = left(split_part(coalesce(v_h->>'x-forwarded-for', v_h->>'x-real-ip', ''), ',', 1), 64),
         signed_agent = left(v_h->>'user-agent', 300), text_version = 'core-recurrente-es-1'
   where id = v.id;
  select * into v_p from public.party where id = v.party_id;
  insert into public.customer_fiscal (party_id, account_id, legal_name, iban, sepa_mandate_ref, sepa_mandate_date, payment_method)
  values (v.party_id, v.account_id, v_p.name, v_iban, v.ref, v_hoy, 'direct_debit')
  on conflict (party_id) do update set iban = excluded.iban, sepa_mandate_ref = excluded.sepa_mandate_ref, sepa_mandate_date = excluded.sepa_mandate_date,
                                       payment_method = 'direct_debit', updated_at = now();
  return jsonb_build_object('frase', format('Mandato %s firmado. Gracias: los próximos recibos se cargarán en la cuenta que termina en %s.', v.ref, right(v_iban, 4)));
end $_$;


--
-- Name: conta_mandato_para_firmar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_mandato_para_firmar(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v public.conta_mandato; v_c public.company; v_p public.party; v_t public.treasury_account; v_cf public.customer_fiscal;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{64}$' then return jsonb_build_object('estado', 'no_existe'); end if;
  select * into v from public.conta_mandato where token = p_token;
  if v.id is null then return jsonb_build_object('estado', 'no_existe'); end if;
  select * into v_c from public.company where id = v.company_id;
  select * into v_p from public.party where id = v.party_id;
  select * into v_cf from public.customer_fiscal where party_id = v.party_id;
  select * into v_t from public.treasury_account where company_id = v.company_id and is_active and kind = 'bank' order by created_at limit 1;
  return jsonb_build_object(
    'estado', case when v.status = 'firmado' then 'firmado' when v.status = 'anulado' then 'anulado' when v.expires_at < now() then 'caducado' else 'por_firmar' end,
    'ref', v.ref,
    'acreedor', jsonb_build_object('nombre', coalesce(nullif(v_c.legal_name, ''), v_c.trade_name),
      'identificador', public._pc01e3_identificador_acreedor(v_c.tax_id, v_t.sepa_suffix),
      'direccion', concat_ws(', ', nullif(v_c.fiscal_street, ''), nullif(concat_ws(' ', v_c.fiscal_postal_code, v_c.fiscal_city), ''))),
    'deudor', jsonb_build_object('nombre', coalesce(nullif(v_cf.legal_name, ''), v_p.name), 'nif', v_p.tax_id),
    'firmado', case when v.status = 'firmado' then jsonb_build_object('at', v.signed_at, 'nombre', v.signed_name, 'nif', v.signed_tax_id,
                    'iban', left(v.iban, 4) || ' •••• •••• ' || right(v.iban, 4)) end);
end $_$;


--
-- Name: conta_mandato_preparar(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_mandato_preparar(p_company uuid, p_party uuid, p_correo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_cuenta uuid := public._pc01e3_empresa(p_company); v_p public.party; v_ref text; v_token text; v_id uuid;
        v_correo text := nullif(lower(trim(coalesce(p_correo, ''))), '');
begin
  select * into v_p from public.party where id = p_party and account_id = v_cuenta;
  if v_p.id is null then raise exception 'Ese cliente no es de la cuenta.' using errcode = 'P0002'; end if;
  if v_correo is not null and v_correo !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Ese correo no vale.' using errcode = '22023'; end if;
  update public.conta_mandato set status = 'anulado', cancelled_at = now() where party_id = p_party and company_id = p_company and status = 'por_firmar';
  v_ref := public._pc01e3_ref_mandato(p_company);
  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.conta_mandato (account_id, company_id, party_id, ref, token, expires_at, sent_to, created_by, created_by_name)
  values (v_cuenta, p_company, p_party, v_ref, v_token, now() + interval '30 days', v_correo, auth.uid(), coalesce(public.conta_nombre_actor(), 'Sumied'))
  returning id into v_id;
  return jsonb_build_object('mandato', v_id, 'ref', v_ref, 'token', v_token, 'enlace', '/mandato.html?t=' || v_token, 'correo', v_correo,
    'caduca', (now() + interval '30 days')::date,
    'frase', format('Mandato %s de %s preparado: el enlace para firmarlo vale 30 días.', v_ref, v_p.name));
end $_$;


--
-- Name: conta_mapeo_cambiar(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_mapeo_cambiar(p_company uuid, p_model text, p_statement text, p_prefix text, p_line text, p_by_balance text DEFAULT NULL::text, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_acc uuid; v_de text; v_quien text := public.conta_nombre_actor();
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta cambia qué cuentas alimentan cada línea.' using errcode = '42501';
  end if;
  if p_prefix !~ '^[0-9]{1,8}$' then raise exception 'La cuenta tiene que ser un número de cuenta (prefijo).' using errcode = '22023'; end if;
  if p_line is not null and not exists (select 1 from public.annual_accounts_line where model = p_model and statement = p_statement and code = p_line and not is_total) then
    raise exception 'Esa línea no existe en el modelo % (%).', p_model, p_statement using errcode = '22023';
  end if;
  -- De dónde venía: lo propio si lo había; si no, la serie más específica.
  select line_code into v_de from public.annual_accounts_mapping
   where company_id = p_company and model = p_model and statement = p_statement and account_prefix = p_prefix and coalesce(by_balance, '') = coalesce(p_by_balance, '') limit 1;
  if v_de is null then
    select line_code into v_de from public.annual_accounts_mapping
     where company_id is null and model = p_model and statement = p_statement and p_prefix like account_prefix || '%'
       and coalesce(by_balance, '') = coalesce(p_by_balance, '')
     order by length(account_prefix) desc limit 1;
  end if;
  delete from public.annual_accounts_mapping
   where company_id = p_company and model = p_model and statement = p_statement and account_prefix = p_prefix and coalesce(by_balance, '') = coalesce(p_by_balance, '');
  insert into public.annual_accounts_mapping (account_id, company_id, model, statement, line_code, account_prefix, by_balance, origin, excluded, note, created_by, created_by_name)
  values (v_acc, p_company, p_model, p_statement,
          coalesce(p_line, (select code from public.annual_accounts_line where model = p_model and statement = p_statement order by sort_order limit 1)),
          p_prefix, p_by_balance, 'empresa', p_line is null, p_motivo, auth.uid(), v_quien);
  insert into public.annual_accounts_mapping_change (account_id, company_id, model, statement, account_prefix, action, from_line, to_line, reason, changed_by, changed_by_name)
  values (v_acc, p_company, p_model, p_statement, p_prefix, case when p_line is null then 'deja_fuera' else 'cambia' end, v_de, p_line, p_motivo, auth.uid(), v_quien);
  return jsonb_build_object('cuenta', p_prefix, 'de', v_de, 'a', p_line, 'quien', v_quien);
end $_$;


--
-- Name: conta_mapeo_volver_al_estandar(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_mapeo_volver_al_estandar(p_company uuid, p_model text, p_statement text, p_prefix text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_n int; v_quien text := public.conta_nombre_actor();
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta cambia qué cuentas alimentan cada línea.' using errcode = '42501';
  end if;
  with b as (
    delete from public.annual_accounts_mapping
     where company_id = p_company and model = p_model and statement = p_statement and (p_prefix is null or account_prefix = p_prefix)
    returning account_prefix, line_code)
  insert into public.annual_accounts_mapping_change (account_id, company_id, model, statement, account_prefix, action, from_line, to_line, changed_by, changed_by_name)
  select v_acc, p_company, p_model, p_statement, account_prefix, 'estandar', line_code, null, auth.uid(), v_quien from b;
  get diagnostics v_n = row_count;
  return jsonb_build_object('vueltas', v_n, 'quien', v_quien);
end $$;


--
-- Name: conta_mes_cerrado(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_mes_cerrado(p_company uuid, p_fecha date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.fiscal_period_lock
     where company_id = p_company and month = date_trunc('month', p_fecha)::date and reopened_at is null)
$$;


--
-- Name: conta_misma_cuenta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_misma_cuenta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v uuid;
begin
  -- SECURITY DEFINER para ver la empresa aunque la RLS la esconda; el mensaje
  -- no dice de quién es (no da a una cuenta datos de otra).
  select account_id into v from public.company where id = new.company_id;
  if v is distinct from new.account_id then
    raise exception 'Esa empresa no es de esta cuenta' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: conta_misma_cuenta_si_propia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_misma_cuenta_si_propia() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v uuid;
begin
  if new.company_id is null then return new; end if;
  select account_id into v from public.company where id = new.company_id;
  if v is distinct from new.account_id then
    raise exception 'Esa empresa no es de esta cuenta' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: conta_modelo_pagado(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_modelo_pagado(p_company uuid, p_modelo text, p_periodo text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c company; t tax_return; v_pagado numeric; v_pendiente numeric;
begin
  select * into c from company where id = p_company;
  if c.id is null or not public.belongs_to_account(c.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  select coalesce(sum(l.debit - l.credit), 0) into v_pagado
    from journal_line l join journal_entry e on e.id = l.entry_id join company_account a on a.id = l.company_account_id
   where l.company_id = p_company and e.status = 'validado' and a.template_code like '4751%'
     and l.withholding_model = p_modelo and l.withholding_period = p_periodo and l.withholding_rate_id is null;
  select * into t from tax_return
   where company_id = p_company and form_code = p_modelo and fiscal_year = split_part(p_periodo, '-', 1)::int
     and period = case when split_part(p_periodo, '-', 2) = '0A' then '0A' else split_part(p_periodo, '-', 2) end
     and status = 'filed' order by sequence desc limit 1;
  v_pendiente := case when t.id is not null and t.result_kind = 'to_pay' then round(t.amount - v_pagado, 2) end;
  return jsonb_build_object('modelo', p_modelo, 'periodo', p_periodo, 'texto', public.conta_modelo_periodo_texto(p_modelo, p_periodo),
    'declaracion', t.id, 'importe', t.amount, 'pagado', round(v_pagado, 2), 'pendiente', v_pendiente, 'asiento_pago', t.payment_entry_id);
end $$;


--
-- Name: conta_modelo_periodo_texto(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_modelo_periodo_texto(p_modelo text, p_periodo text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select p_modelo || ' · ' || case when split_part(p_periodo, '-', 2) = '0A' then 'año ' || split_part(p_periodo, '-', 1)
                                   else split_part(p_periodo, '-', 2) || ' ' || split_part(p_periodo, '-', 1) end
$$;


--
-- Name: conta_motivos_para_validar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_motivos_para_validar(p_entry uuid) RETURNS TABLE(orden integer, codigo text, motivo text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry; v_y public.fiscal_year;
  v_n int; v_debe numeric; v_haber numeric; v_cierre boolean; v_mal text; v_aclarar int; v_lista text;
  v_local boolean; v_liquidacion boolean;
  v_hay_isp boolean; v_isp_472 numeric; v_auto_477 numeric; v_p record; v_contra text;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null then return; end if;

  -- Regla 1: cuadra, al céntimo.
  select count(*), coalesce(sum(debit), 0), coalesce(sum(credit), 0) into v_n, v_debe, v_haber
    from public.journal_line where entry_id = p_entry;
  if v_n < 2 then
    orden := 1; codigo := 'pocos_apuntes'; motivo := 'Un asiento lleva al menos dos apuntes.'; return next;
  end if;
  if v_debe <> v_haber then
    orden := 2; codigo := 'no_cuadra';
    motivo := format('No cuadra: Debe %s y Haber %s, diferencia %s.', v_debe, v_haber, v_debe - v_haber); return next;
  end if;

  -- Regla 4: fecha en su ejercicio, abierto, fuera de lo traído, mes abierto.
  select * into v_y from public.fiscal_year where id = v_e.fiscal_year_id;
  if v_e.entry_date not between v_y.starts_on and v_y.ends_on then
    orden := 3; codigo := 'fuera_del_ejercicio';
    motivo := format('La fecha %s no es del ejercicio %s.', to_char(v_e.entry_date, 'DD/MM/YYYY'), v_y.code); return next;
  end if;
  if v_e.source_type <> 'migrated' then
    if v_y.status <> 'open' then
      orden := 4; codigo := 'ejercicio_cerrado'; motivo := format('El ejercicio %s está cerrado.', v_y.code); return next;
    end if;
    if v_y.origin in ('mixed', 'migrated') and v_y.origin_program is not null and v_y.history_imported_at is null then
      orden := 5; codigo := 'falta_historico';
      motivo := format('Primero hay que traer el histórico de %s de %s.',
        case lower(v_y.origin_program) when 'diez' then 'Diez' else v_y.origin_program end, v_y.code); return next;
    end if;
    if v_y.imported_until is not null and v_e.entry_date <= v_y.imported_until then
      orden := 6; codigo := 'traido';
      motivo := format('Hasta el %s el ejercicio %s es traído de %s: la fecha abierta más cercana es el %s.',
        to_char(v_y.imported_until, 'DD/MM/YYYY'), v_y.code, v_y.origin_program,
        to_char(public.conta_primer_dia_abierto(v_e.company_id, v_y.imported_until + 1), 'DD/MM/YYYY')); return next;
    end if;
    if public.conta_mes_cerrado(v_e.company_id, v_e.entry_date) then
      orden := 7; codigo := 'mes_cerrado';
      motivo := format('El mes de %s está cerrado: la fecha abierta más cercana es el %s.',
        to_char(v_e.entry_date, 'MM/YYYY'),
        coalesce(to_char(public.conta_primer_dia_abierto(v_e.company_id, v_e.entry_date), 'DD/MM/YYYY'), 'ninguna')); return next;
    end if;

    -- C05 (respuesta 3), copiado de la vigente: un asiento de cierre o de
    -- apertura del generador de cierre (o su contraasiento) se libra de las
    -- reglas de IVA y retención.
    v_cierre := exists (
      select 1 from public.journal_entry o
        join public.fiscal_year oy on oy.id = o.fiscal_year_id
       where o.id = case when v_e.source_type = 'reversal' then v_e.reverses_entry_id else v_e.id end
         and o.source_type in ('closing', 'opening')
         and coalesce(o.reasons, '[]'::jsonb) @> '[{"decision": "cierre-del-ejercicio"}]'::jsonb
         and exists (
           select 1 from public.fiscal_year_closing c
            where c.company_id = o.company_id
              and ((o.source_type = 'closing' and c.fiscal_year_id = o.fiscal_year_id
                    and o.id in (c.regularization_entry_id, c.closing_entry_id))
                or (o.source_type = 'opening' and c.opening_entry_id = o.id
                    and exists (select 1 from public.fiscal_year a
                                 where a.id = c.fiscal_year_id and a.ends_on + 1 = oy.starts_on)))));

    -- I01b (0180): el asiento de liquidación de un 303 (o su contraasiento)
    -- salda la 477 y la 472 del periodo: sus apuntes no llevan tipo ni libro
    -- registro. Solo si su origen es una declaración 303 de su misma empresa.
    v_liquidacion := exists (
      select 1 from public.journal_entry o
        join public.tax_return t on t.id = o.source_id and t.company_id = o.company_id and t.account_id = o.account_id
       where o.id = case when v_e.source_type = 'reversal' then v_e.reverses_entry_id else v_e.id end
         and o.company_id = v_e.company_id
         and o.source_type = 'vat_settlement'
         and t.form_code = '303');

    -- S01 (0140): el local solo se pide si el eje «local» de la empresa está encendido
    -- (conta_eje_analitico; sin fila = apagado). Lo demás, como estaba.
    v_local := exists (select 1 from public.conta_eje_analitico x
                        where x.company_id = v_e.company_id and x.account_id = v_e.account_id and x.eje = 'local' and x.activo);

    -- I01d (0300): ¿lleva el asiento IVA autoliquidado? (una 472 con el tipo
    -- «Compra en otro país de la UE» o «Inversión del sujeto pasivo»). Su 477
    -- de autorrepercusión va SIN tipo ni libro registro, como la trae Diez:
    -- la regla 10 de abajo la casa con la 472 al céntimo.
    v_hay_isp := exists (select 1 from public.journal_line l join public.company_account a on a.id = l.company_account_id
                           join public.tax_rate t on t.id = l.tax_rate_id
                          where l.entry_id = p_entry and a.template_code like '472%' and t.treatment in ('intra_eu', 'reverse_charge'));

    -- Regla 5, copiada de la vigente (20261113T0100: el céntimo de redondeo).
    select string_agg(format('apunte %s (%s): %s', l.position, a.code, m.motivo), '; ' order by l.position) into v_mal
      from public.journal_line l
      join public.company_account a on a.id = l.company_account_id
      left join public.tax_rate t on t.id = l.tax_rate_id
      cross join lateral (select case
        when (a.template_code like '472%' or a.template_code like '477%') and l.tax_rate_id is null and not v_cierre and not v_liquidacion
             and not (a.template_code like '477%' and v_hay_isp)
          then 'un apunte de IVA lleva base, tipo y libro registro'
        -- V03 E2 (0146): un apunte con un tipo exento ES la base (la 70x de una
        -- venta sin IVA): su importe es su base, al céntimo.
        when l.tax_rate_id is not null and t.treatment = 'exempt'
             and abs(l.tax_base) <> l.debit + l.credit
          then format('un apunte sin IVA es su base: el importe %s no es la base %s', l.debit + l.credit, l.tax_base)
        when l.tax_rate_id is not null and t.treatment is distinct from 'exempt'
             and abs(round(l.tax_base * t.rate / 100, 2) - (l.debit + l.credit)) > greatest(1, floor(l.tax_documents / 2.0)) / 100
          then format('la cuota %s no es la base %s × %s %% = %s', l.debit + l.credit, l.tax_base, t.rate, round(l.tax_base * t.rate / 100, 2))
        when a.template_code like '4751%' and l.withholding_rate_id is null and not v_cierre
             and not (l.withholding_model is not null and l.withholding_period is not null)
          then 'una retención lleva su tipo, su base y su modelo; el pago o la compensación de un modelo, su modelo y su periodo'
        when a.template_code like '4751%' and l.withholding_rate_id is not null and l.withholding_period is not null
          then 'o es una retención que nace (tipo, base y modelo) o el pago de un modelo (modelo y periodo), no las dos'
        when v_local and not l.is_common and l.location_id is null
          then 'falta el local (o marcarlo como común)'
        end as motivo) m
     where l.entry_id = p_entry and m.motivo is not null;
    if v_mal is not null then
      orden := 8; codigo := 'apuntes'; motivo := format('No se valida: %s.', v_mal); return next;
    end if;

    -- I01d (0300), regla 10 · LA AUTOLIQUIDACIÓN. (a) La 477 de la
    -- autorrepercusión (sin tipo) suma lo mismo que la 472 autoliquidada, al
    -- céntimo. (b) En una factura de proveedor, el tipo de cada línea de IVA
    -- es el que dice su ficha (país, NIF-IVA y régimen de IVA): si lo
    -- contradice, no se valida y se dice por qué.
    select coalesce(sum(l.debit - l.credit) filter (where a.template_code like '472%' and t.treatment in ('intra_eu', 'reverse_charge')), 0),
           coalesce(sum(l.credit - l.debit) filter (where a.template_code like '477%' and l.tax_rate_id is null), 0)
      into v_isp_472, v_auto_477
      from public.journal_line l join public.company_account a on a.id = l.company_account_id
      left join public.tax_rate t on t.id = l.tax_rate_id
     where l.entry_id = p_entry;
    if v_hay_isp and v_isp_472 <> v_auto_477 then
      orden := 10; codigo := 'autorrepercusion';
      motivo := format('No se valida: falta la autorrepercusión. El IVA autoliquidado de la 472 suma %s y la 477 sin tipo, %s: tienen que ser lo mismo (el IVA lo declaras y lo deduces tú).',
                       public.conta_impuesto_euros(v_isp_472), public.conta_impuesto_euros(v_auto_477)); return next;
    elsif not v_hay_isp and v_auto_477 <> 0 and not v_cierre and not v_liquidacion then
      orden := 10; codigo := 'autorrepercusion';
      motivo := 'No se valida: hay una 477 sin tipo y ninguna compra autoliquidada en el asiento. Un apunte de IVA lleva base, tipo y libro registro.'; return next;
    end if;
    if v_e.source_type = 'supplier_invoice' then
      select s.name, s.country_code, public.conta_proveedor_iva_clase(s.country_code, s.tax_id_type, s.tax_id, s.tax_id_check_status, s.vat_regime) as clase
        into v_p
        from public.supplier_invoice si join public.supplier s on s.id = si.supplier_id and s.account_id = si.account_id
       where si.id = v_e.source_id and si.account_id = v_e.account_id;
      if found then
        select string_agg(format('el apunte %s lleva «%s»', l.position, t.name), ', ' order by l.position) into v_contra
          from public.journal_line l join public.tax_rate t on t.id = l.tax_rate_id
         where l.entry_id = p_entry and l.vat_book in ('received', 'investment')
           and not case v_p.clase
                 when 'intracomunitaria' then t.treatment = 'intra_eu'
                 when 'isp_extranjero' then t.treatment = 'reverse_charge'
                 when 'isp_nacional' then t.treatment = 'reverse_charge'
                 when 'nacional' then t.treatment in ('taxed', 'exempt', 'not_subject')
                 else false end;
        if v_contra is not null then
          orden := 11; codigo := 'tipo_contra_pais';
          motivo := 'No se valida: ' || v_contra || '. ' || v_p.name || ' ' || case v_p.clase
            when 'intracomunitaria' then 'es de ' || public.conta_pais_nombre(v_p.country_code) || ' y tiene NIF-IVA europeo: su compra es intracomunitaria y va con «Compra en otro país de la UE» (el IVA lo declaras tú).'
            when 'isp_extranjero' then 'es de fuera de la UE (' || public.conta_pais_nombre(v_p.country_code) || '): su compra va con «Inversión del sujeto pasivo» (el IVA lo declaras tú).'
            when 'isp_nacional' then 'está marcado con inversión del sujeto pasivo en su ficha: su compra va con «Inversión del sujeto pasivo».'
            when 'nacional' then 'es de España: su compra lleva el IVA de su factura. Si es una inversión del sujeto pasivo (obras, chatarra…), márcalo en su ficha, en «Régimen de IVA».'
            else 'es de ' || public.conta_pais_nombre(v_p.country_code) || ' y no tiene un NIF-IVA europeo válido: sin él su compra no es intracomunitaria. Pon su NIF-IVA en su ficha (se comprueba en VIES).' end;
          return next;
        end if;
      end if;
    end if;
  end if;

  -- C06b (#210): un asiento de ventas del día con un envío por aclarar. Copiado
  -- de tg_journal_entry_envio_por_aclarar, que desde aquí lo lee de esta función.
  if v_e.source_type = 'sales_day' then
    select count(*), string_agg(coalesce(s.platform_order_code, left(s.id::text, 8)) || ' (envío ' || public.conta_euros_exactos(c.envio) || ', ' || c.por_que || ')', '; ' order by s.sold_at)
      into v_aclarar, v_lista
      from public.sales_day_summary d
      cross join lateral public.conta_cargos_de_pedidos(d.account_id, d.sale_ids) c
      join public.sale s on s.id = c.id and s.account_id = d.account_id
     where d.entry_id = v_e.id and d.account_id = v_e.account_id and c.clase = 'por_aclarar';
    if v_aclarar > 0 then
      orden := 9; codigo := 'envio_por_aclarar';
      motivo := format('No se valida: %s con envío por aclarar: %s. Se resuelve con la liquidación de esa semana.',
        v_aclarar || case when v_aclarar = 1 then ' pedido' else ' pedidos' end, v_lista); return next;
    end if;
  end if;
end $$;


--
-- Name: FUNCTION conta_motivos_para_validar(p_entry uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_motivos_para_validar(p_entry uuid) IS 'M01 (16/10): lo que haría que journal_entry_validar no valide este asiento, por orden y con el texto con el que lo para. La regla vive aquí: journal_entry_validar y tg_journal_entry_envio_por_aclarar la leen. Solo lee.';


--
-- Name: conta_no_confirmados(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_no_confirmados(p_company uuid, p_desde date, p_hasta date, p_location uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, location_id uuid, dia date, sold_at timestamp with time zone, marca text, canal text, codigo text, total numeric, order_status text, delivery_state text, unconfirmed_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select s.id, s.location_id, (s.sold_at at time zone 'Europe/Madrid')::date, s.sold_at, b.name, ch.name,
         coalesce(s.platform_order_code, s.pos_short_code, s.external_ref), s.total, s.order_status, s.delivery_state, s.unconfirmed_at
    from public.sale s
    join public.company c on c.id = p_company and c.account_id = s.account_id
    left join public.brand b on b.id = s.brand_id
    left join public.sales_channel ch on ch.id = s.channel_id
   where s.unconfirmed_at is not null and s.status = 'cancelled'
     and (p_location is null or s.location_id = p_location)
     and s.sold_at >= (p_desde::timestamp at time zone 'Europe/Madrid') and s.sold_at < ((p_hasta + 1)::timestamp at time zone 'Europe/Madrid')
   order by s.sold_at
$$;


--
-- Name: FUNCTION conta_no_confirmados(p_company uuid, p_desde date, p_hasta date, p_location uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_no_confirmados(p_company uuid, p_desde date, p_hasta date, p_location uuid) IS 'Cierre del día: los pedidos cerrados como no confirmados entre dos días (Madrid), con marca, canal, código e importe. Lee con los permisos de quien llama.';


--
-- Name: conta_no_confirmados_pagados(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_no_confirmados_pagados(p_company uuid) RETURNS TABLE(sale_id uuid, location_id uuid, dia date, codigo text, canal_id uuid, marca_id uuid, total numeric, settlement_order_id uuid, settlement_ref text, settlement_date date, pagado numeric, dia_validado boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select distinct on (s.id)
         s.id, s.location_id, (s.sold_at at time zone 'Europe/Madrid')::date,
         coalesce(s.platform_order_code, s.pos_short_code, s.external_ref), s.channel_id, s.brand_id, s.total,
         co.id, coalesce(cs.settlement_ref, co.settlement_ref), cs.settlement_date, co.products,
         exists (select 1 from public.sales_day_summary d join public.journal_entry e on e.id = d.entry_id
                  where d.company_id = p_company and d.location_id = s.location_id
                    and d.sales_day = (s.sold_at at time zone 'Europe/Madrid')::date and e.status = 'validado')
    from public.sale s
    join public.company c on c.id = p_company and c.account_id = s.account_id
    join public.channel_settlement_order co on co.sale_id = s.id and co.account_id = s.account_id
    left join public.channel_settlement cs on cs.id = co.settlement_id
   where s.unconfirmed_at is not null and s.status = 'cancelled'
     and coalesce(co.matched, false) and coalesce(co.products, 0) > 0
     and not exists (select 1 from public.journal_entry e
                      where e.company_id = p_company and e.source_type = 'sales_adjustment' and e.source_id = s.id
                        and e.status in ('propuesto', 'borrador', 'validado'))
     and not exists (select 1 from public.journal_dismissal x
                      where x.company_id = p_company and x.source_type = 'sales_adjustment' and x.source_key = s.id::text)
   order by s.id, cs.settlement_date nulls last
$$;


--
-- Name: FUNCTION conta_no_confirmados_pagados(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_no_confirmados_pagados(p_company uuid) IS 'Cierre del día: los pedidos cerrados como no confirmados que una liquidación de la plataforma ha pagado, sin propuesta viva ni descarte. Lo que «Proponer lo pendiente» propone aparte como venta de su día.';


--
-- Name: conta_nombre_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_nombre_actor() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select display_name from public.user_profiles where user_id = auth.uid() and active order by created_at limit 1),
    (select email from auth.users where id = auth.uid()))
$$;


--
-- Name: conta_nombre_fichero(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_nombre_fichero(p_nombre text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $_$
  select case when c = '' then 'documento' else c end || '.pdf'
    from (select regexp_replace(
                   left(regexp_replace(regexp_replace(
                     regexp_replace(translate(coalesce(p_nombre, ''),
                       'áàäâãåÁÀÄÂÃÅéèëêÉÈËÊíìïîÍÌÏÎóòöôõÓÒÖÔÕúùüûÚÙÜÛñÑçÇ',
                       'aaaaaaAAAAAAeeeeEEEEiiiiIIIIoooooOOOOOuuuuUUUUnNcC'),
                       '\.pdf\s*$', '', 'i'),
                     '[^A-Za-z0-9._-]+', '-', 'g'),
                   '-{2,}', '-', 'g'), 150),
                 '^[-.]+|[-.]+$', '', 'g') as c) x
$_$;


--
-- Name: FUNCTION conta_nombre_fichero(p_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_nombre_fichero(p_nombre text) IS 'C06b · El nombre de un PDF que cumple el CHECK de journal_entry_document.file_name: sin tildes ni ñ, lo demás a «-», .pdf al final.';


--
-- Name: conta_numero_previsto(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_numero_previsto(p_entry uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e public.journal_entry;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null or not public.belongs_to_account(v_e.account_id) then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  if not public.current_user_is_admin_or_manager_of(v_e.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta valida asientos.' using errcode = '42501';
  end if;
  if v_e.status not in ('propuesto', 'borrador') then
    raise exception 'El asiento ya está %.', v_e.status using errcode = '23514';
  end if;
  -- El mismo cálculo que journal_entry_validar (regla 2): el siguiente de su serie en el ejercicio.
  return (select coalesce(max(number), 0) + 1 from public.journal_entry
           where company_id = v_e.company_id and fiscal_year_id = v_e.fiscal_year_id and series = v_e.series and number is not null);
end $$;


--
-- Name: conta_numero_texto(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_numero_texto(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when p::text like '%.%' then rtrim(rtrim(p::text, '0'), '.') else p::text end
$$;


--
-- Name: conta_pago_a_mano(uuid, uuid, uuid, date, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_a_mano(p_company uuid, p_invoice uuid, p_treasury uuid, p_fecha date, p_importe numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid := public._pc01e2_empresa(p_company); v_t public.treasury_account; v_inv public.supplier_invoice; v_s public.supplier;
  v_pend numeric; v_r uuid; v_code text; v_l uuid;
begin
  select * into v_t from public.treasury_account where id = p_treasury and company_id = p_company and is_active;
  if v_t.id is null then raise exception 'Esa cuenta del banco no es de la empresa.' using errcode = '23514'; end if;
  if p_fecha is null then raise exception 'Falta el día que la pagaste.' using errcode = '22023'; end if;
  if p_fecha > public.conta_hoy() then raise exception '«Ya la he pagado» es para un pago hecho: el día no puede ser posterior a hoy.' using errcode = '22023'; end if;
  select * into v_inv from public.supplier_invoice where id = p_invoice and account_id = v_cuenta for update;
  if v_inv.id is null or coalesce(v_inv.company_id, p_company) <> p_company then raise exception 'Esa factura no es de la empresa.' using errcode = '23514'; end if;
  if v_inv.status <> 'aprobada' then raise exception 'La factura % no está por pagar (está %).', coalesce(v_inv.invoice_number, ''), v_inv.status using errcode = '23514'; end if;
  select * into v_s from public.supplier where id = v_inv.supplier_id;
  if public._pc01e2_cuenta_proveedor(p_company, v_s.id) is null then
    raise exception '% no tiene su cuenta de proveedor (400) en el plan: sin ella el pago no tendría asiento.', coalesce(v_s.name, 'Su proveedor') using errcode = '23514';
  end if;
  select pendiente into v_pend from public.conta_recibida_pago where invoice_id = v_inv.id;
  v_pend := coalesce(v_pend, 0) - public._pc01e2_en_remesa(v_inv.id);
  if p_importe is null or p_importe <= 0 or p_importe > v_pend + 0.005 then
    raise exception 'A la factura % le quedan % por pagar: no se le pueden apuntar %.', coalesce(v_inv.invoice_number, ''),
      public.conta_euros_exactos(greatest(v_pend, 0)), public.conta_euros_exactos(coalesce(p_importe, 0)) using errcode = '23514';
  end if;
  v_code := public._pc01e2_codigo(p_company, p_fecha);
  insert into public.conta_pago_remesa (account_id, company_id, code, kind, treasury_account_id, pay_date, created_by, created_by_name)
  values (v_cuenta, p_company, v_code, 'a_mano', p_treasury, p_fecha, auth.uid(), coalesce(public.conta_nombre_actor(), 'Sumied'))
  returning id into v_r;
  insert into public.conta_pago_remesa_linea (account_id, company_id, remesa_id, invoice_id, supplier_id, amount, iban, iban_check, iban_note)
  values (v_cuenta, p_company, v_r, v_inv.id, v_s.id, p_importe, public._pc01e2_iban(v_s.iban), 'sin_fichero', 'Pagada a mano en el banco.')
  returning id into v_l;
  perform public._pc01e2_evento(v_cuenta, v_r, v_l, format('Apunta que pagó %s de la factura %s de %s el %s desde %s. Espera el cargo en el banco.',
    public.conta_euros_exactos(p_importe), coalesce(v_inv.invoice_number, 'sin número'), coalesce(v_s.name, '—'), to_char(p_fecha, 'DD/MM/YYYY'), v_t.name));
  return jsonb_build_object('remesa', v_r, 'codigo', v_code,
    'frase', format('Apuntado: %s a %s el %s desde %s. Queda esperando el cargo; cuando lo cases en Bancos, %s.',
      public.conta_euros_exactos(p_importe), coalesce(v_s.name, 'su proveedor'), to_char(p_fecha, 'DD/MM'), v_t.name,
      case when p_importe >= v_pend - 0.005 then 'la factura queda pagada con su asiento' else 'el pago queda con su asiento y la factura, pagada en parte' end));
end $$;


--
-- Name: FUNCTION conta_pago_a_mano(p_company uuid, p_invoice uuid, p_treasury uuid, p_fecha date, p_importe numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_pago_a_mano(p_company uuid, p_invoice uuid, p_treasury uuid, p_fecha date, p_importe numeric) IS 'PC01 · E2 · «Ya la he pagado»: apunta el pago de una factura suelta (admite parcial). Espera el cargo para casarse en Bancos y tener su asiento.';


--
-- Name: conta_pago_activar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_activar(p_company uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_n int; v_nombre text := public._conta_pago_nombre(p_user);
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.user_profiles where user_id = p_user and account_id = v_acc and role = 'admin' and active) then
    raise exception 'Solo un administrador activa los pagos.' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('conta_pago_permiso:' || p_company::text, 0));
  if not public._conta_pago_puede(p_company, p_user) then
    insert into public.conta_pago_permiso (account_id, company_id, user_id, user_name, granted_by, granted_by_name)
    values (v_acc, p_company, p_user, v_nombre, p_user, v_nombre || ' (al activar los pagos)');
  end if;
  select count(*) into v_n from public._conta_pago_pagadores(p_company);
  return jsonb_build_object('n', v_n, 'personas', (select coalesce(jsonb_agg(nombre), '[]'::jsonb) from public._conta_pago_pagadores(p_company)));
end $$;


--
-- Name: conta_pago_aprobar(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_aprobar(p_company uuid, p_treasury uuid, p_facturas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid := public._conta_pago_empresa(p_company); v_sal record; v_t record; v_lote uuid; v_f jsonb; v_p jsonb; v_s uuid;
  v_vistas uuid[] := '{}'; v_total numeric := 0; v_n int := 0; v_motivos text[] := '{}'; v_m text; v_quien jsonb; v_huella text; v_yo text;
begin
  if not public._conta_pago_puede(p_company, auth.uid()) then
    raise exception 'No tienes permiso para pagar en esta empresa.' using errcode = '42501';
  end if;
  select * into v_sal from public._conta_pago_salida_de(p_company, p_treasury);
  if not v_sal.puede then raise exception '%', v_sal.porque using errcode = '23514'; end if;
  if jsonb_typeof(p_facturas) <> 'array' or jsonb_array_length(p_facturas) = 0 then raise exception 'Elige al menos una factura.' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('conta_pago_aprobar:' || p_company::text, 0));
  v_yo := coalesce(public.conta_nombre_actor(), 'Sumied');
  insert into public.conta_pago_lote (account_id, company_id, treasury_account_id, proveedor, estado, huella, created_by, created_by_name)
  values (v_acc, p_company, p_treasury, v_sal.proveedor, 'esperando_segunda', repeat('0', 64), auth.uid(), v_yo)
  returning id into v_lote;
  for v_f in select * from jsonb_array_elements(p_facturas) loop
    if (v_f->>'id')::uuid = any(v_vistas) then raise exception 'Una factura está dos veces.' using errcode = '23514'; end if;
    v_vistas := v_vistas || (v_f->>'id')::uuid;
    perform 1 from public.supplier_invoice where id = (v_f->>'id')::uuid and account_id = v_acc for update;
    v_p := public._conta_pago_factura(p_company, (v_f->>'id')::uuid, nullif(v_f->>'importe', '')::numeric, v_f->>'pagar_igual_porque');
    if v_p->>'porque' is not null then raise exception '%', v_p->>'porque' using errcode = '23514'; end if;
    insert into public.conta_pago_salida (account_id, company_id, lote_id, invoice_id, supplier_id, amount, beneficiario, iban, iban_check, iban_nota,
                                          concepto, motivos, pagar_igual_porque, estado)
    values (v_acc, p_company, v_lote, (v_p->>'factura')::uuid, (v_p->>'proveedor')::uuid, (v_p->>'importe')::numeric, v_p->>'beneficiario', v_p->>'iban',
            v_p->>'iban_check', v_p->>'iban_nota', v_p->>'concepto', array(select jsonb_array_elements_text(v_p->'motivos')),
            nullif(trim(coalesce(v_f->>'pagar_igual_porque', '')), ''), 'esperando_segunda')
    returning id into v_s;
    v_motivos := v_motivos || array(select jsonb_array_elements_text(v_p->'motivos'));
    v_total := v_total + (v_p->>'importe')::numeric; v_n := v_n + 1;
    perform public._conta_pago_evento(v_acc, v_lote, v_s, v_yo, format('Aprueba pagar %s a %s (factura %s, IBAN ···· %s) desde %s.',
      public.conta_euros_exactos((v_p->>'importe')::numeric), v_p->>'beneficiario', coalesce(v_p->>'numero', 'sin número'), v_p->>'iban4', v_sal.banco));
  end loop;
  select * into v_t from public._conta_pago_topes(p_company);
  -- Lo aprobado hoy ya incluye este lote.
  if public._conta_pago_aprobado_hoy(p_company) > v_t.tope_dia then v_motivos := v_motivos || 'tope_dia'::text; end if;
  v_motivos := array(select distinct m from unnest(v_motivos) m order by m);
  v_huella := public._conta_pago_huella(v_lote);
  update public.conta_pago_lote set huella = v_huella, segunda_motivos = v_motivos,
    estado = case when cardinality(v_motivos) = 0 then 'listo' else 'esperando_segunda' end where id = v_lote;
  update public.conta_pago_salida set estado = case when cardinality(v_motivos) = 0 then 'lista' else 'esperando_segunda' end where lote_id = v_lote;
  v_quien := public.conta_pago_quien(p_company);
  if cardinality(v_motivos) > 0 then
    perform public._conta_pago_evento(v_acc, v_lote, null, v_yo, format('Pide la segunda aprobación (%s): %s.',
      (select string_agg(public._conta_pago_motivo(m), ', ') from unnest(v_motivos) m),
      case when v_quien->>'segunda' = 'otra' then 'la tiene que dar otra persona que pueda pagar, con su llave'
           else 'la da quien lo aprobó, con su llave o con su PIN de pago' end));
  end if;
  return jsonb_build_object('lote', v_lote, 'huella', v_huella, 'pagos', v_n, 'total', v_total,
    'estado', case when cardinality(v_motivos) = 0 then 'listo' else 'esperando_segunda' end,
    'segunda', case when cardinality(v_motivos) = 0 then null else jsonb_build_object('quien', v_quien->>'segunda', 'motivos', to_jsonb(v_motivos),
      'motivos_texto', (select jsonb_agg(public._conta_pago_motivo(m)) from unnest(v_motivos) m),
      'personas', (select coalesce(jsonb_agg(x->>'nombre'), '[]'::jsonb) from jsonb_array_elements(v_quien->'personas') x where not (x->>'yo')::boolean)) end,
    'frase', case when cardinality(v_motivos) = 0 then format('Aprobado: %s %s, %s, desde %s. Listo para mandarlo.', v_n, case when v_n = 1 then 'pago' else 'pagos' end,
                    public.conta_euros_exactos(v_total), v_sal.banco)
                  when v_quien->>'segunda' = 'otra' then format('Aprobado por ti. Falta la segunda aprobación de otra persona que pueda pagar (%s). Hasta entonces no sale nada.',
                    (select string_agg(public._conta_pago_motivo(m), ', ') from unnest(v_motivos) m))
                  else format('Aprobado por ti. Confírmalo con tu llave (%s). Hasta entonces no sale nada.',
                    (select string_agg(public._conta_pago_motivo(m), ', ') from unnest(v_motivos) m)) end);
end $$;


--
-- Name: conta_pago_banco_dice(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_banco_dice(p_salida uuid, p_estado text, p_banco_id text, p_porque text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s public.conta_pago_salida; v_l public.conta_pago_lote; v_banco text; v_texto text; v_quedan int;
begin
  if p_estado not in ('enviada', 'esperando_banco', 'pagada', 'rechazada', 'devuelta') then
    raise exception 'Estado del banco desconocido: %.', p_estado using errcode = '22023';
  end if;
  select * into v_s from public.conta_pago_salida where id = p_salida for update;
  if v_s.id is null then raise exception 'Ese pago no existe.' using errcode = 'P0002'; end if;
  select * into v_l from public.conta_pago_lote where id = v_s.lote_id for update;
  v_banco := initcap(v_l.proveedor);
  -- Lo que ya acabó no vuelve atrás, salvo una devolución de lo pagado.
  if v_s.estado in ('rechazada', 'devuelta', 'cancelada') or (v_s.estado = 'pagada' and p_estado <> 'devuelta') then
    return jsonb_build_object('estado', v_s.estado, 'sin_cambio', true);
  end if;
  if v_s.estado = p_estado and v_s.banco_id is not distinct from coalesce(p_banco_id, v_s.banco_id) then
    return jsonb_build_object('estado', v_s.estado, 'sin_cambio', true);
  end if;
  update public.conta_pago_salida set estado = p_estado, banco_id = coalesce(nullif(p_banco_id, ''), banco_id),
    estado_porque = case when p_estado in ('rechazada', 'devuelta') then left(coalesce(nullif(trim(p_porque), ''), 'El banco no ha dicho por qué.'), 300) end,
    estado_at = now() where id = p_salida;
  if p_estado = 'rechazada' and v_s.remesa_linea_id is not null then
    update public.conta_pago_remesa_linea set rejected_at = now(), rejected_by_name = v_banco,
      reject_reason = left(coalesce(nullif(trim(p_porque), ''), 'El banco no ha dicho por qué.'), 300)
     where id = v_s.remesa_linea_id and rejected_at is null;
  end if;
  v_texto := case p_estado
    when 'enviada' then format('%s lo ha recibido.', v_banco)
    when 'esperando_banco' then format('%s lo está procesando (o espera la aprobación en %s).', v_banco, v_banco)
    when 'pagada' then format('%s lo ha confirmado: pagado.', v_banco)
    when 'rechazada' then format('%s no ha hecho el pago: %s La factura sigue por pagar.', v_banco, coalesce(nullif(trim(p_porque), ''), 'no ha dicho por qué.'))
    else format('%s ha devuelto el pago: %s', v_banco, coalesce(nullif(trim(p_porque), ''), 'no ha dicho por qué.')) end;
  perform public._conta_pago_evento(v_s.account_id, v_s.lote_id, p_salida, v_banco, v_texto);
  if v_s.remesa_id is not null then perform public._pc01e2_evento(v_s.account_id, v_s.remesa_id, v_s.remesa_linea_id, v_texto); end if;
  select count(*) into v_quedan from public.conta_pago_salida where lote_id = v_s.lote_id and estado = 'enviando';
  if v_quedan = 0 and v_l.estado = 'enviando' then update public.conta_pago_lote set estado = 'enviado' where id = v_s.lote_id; end if;
  return jsonb_build_object('estado', p_estado, 'frase', v_texto);
end $$;


--
-- Name: conta_pago_cancelar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_cancelar(p_lote uuid, p_porque text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.conta_pago_lote; v_yo text := coalesce(public.conta_nombre_actor(), 'Sumied'); v_n int;
begin
  select * into v_l from public.conta_pago_lote where id = p_lote for update;
  if v_l.id is null then raise exception 'Ese pago no existe.' using errcode = 'P0002'; end if;
  perform public._conta_pago_empresa(v_l.company_id);
  if not (auth.uid() = v_l.created_by or public._conta_pago_puede(v_l.company_id, auth.uid())) then
    raise exception 'No tienes permiso para pagar en esta empresa.' using errcode = '42501';
  end if;
  if v_l.estado not in ('esperando_segunda', 'listo') then raise exception 'Este pago ya se ha mandado al banco: no se puede cancelar desde aquí.' using errcode = '23514'; end if;
  update public.conta_pago_lote set estado = 'cancelado', cancelado_at = now(), cancelado_por_nombre = v_yo,
    cancelado_porque = coalesce(nullif(trim(coalesce(p_porque, '')), ''), 'No pagar') where id = p_lote;
  update public.conta_pago_salida set estado = 'cancelada', estado_porque = coalesce(nullif(trim(coalesce(p_porque, '')), ''), 'No pagar'), estado_at = now()
   where lote_id = p_lote and estado in ('esperando_segunda', 'lista');
  get diagnostics v_n = row_count;
  update public.conta_pago_reto set descartado_at = now() where lote_id = p_lote and used_at is null and descartado_at is null;
  perform public._conta_pago_evento(v_l.account_id, p_lote, null, v_yo, format('No pagar: %s.', coalesce(nullif(trim(coalesce(p_porque, '')), ''), 'cancelado')));
  return jsonb_build_object('frase', format('No ha salido nada: %s %s cancelado%s. Las facturas siguen por pagar.', v_n, case when v_n = 1 then 'pago' else 'pagos' end, case when v_n = 1 then '' else 's' end));
end $$;


--
-- Name: conta_pago_dejar(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_dejar(p_company uuid, p_quien uuid, p_quien_nombre text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), 'Sumied'); v_motivo text := coalesce(nullif(trim(p_motivo), ''), 'Se han dejado de usar los pagos con Revolut');
        v_permisos int; v_lotes int := 0; v_l record;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended('conta_pago_permiso:' || p_company::text, 0));
  update public.conta_pago_permiso set revoked_at = now(), revoked_by_name = v_quien || ' (' || v_motivo || ')'
   where company_id = p_company and revoked_at is null;
  get diagnostics v_permisos = row_count;
  for v_l in select id, account_id from public.conta_pago_lote where company_id = p_company and estado in ('esperando_segunda', 'listo') for update loop
    update public.conta_pago_lote set estado = 'cancelado', cancelado_at = now(), cancelado_por_nombre = v_quien, cancelado_porque = v_motivo where id = v_l.id;
    update public.conta_pago_salida set estado = 'cancelada', estado_porque = v_motivo, estado_at = now() where lote_id = v_l.id and estado in ('esperando_segunda', 'lista');
    update public.conta_pago_reto set descartado_at = now() where lote_id = v_l.id and used_at is null and descartado_at is null;
    perform public._conta_pago_evento(v_l.account_id, v_l.id, null, v_quien, format('No sale: %s.', v_motivo));
    v_lotes := v_lotes + 1;
  end loop;
  update public.revolut_conexion set permisos = 'READ,WRITE'
   where company_id = p_company and 'PAY' = any (string_to_array(replace(coalesce(permisos, ''), ' ', ','), ','));
  return jsonb_build_object('permisos', v_permisos, 'lotes', v_lotes,
    'frase', format('Ya no se puede pagar con Revolut desde Sumied.%s%s',
      case when v_permisos = 0 then '' when v_permisos = 1 then ' Quitado el permiso de pagar a 1 persona.' else format(' Quitado el permiso de pagar a %s personas.', v_permisos) end,
      case when v_lotes = 0 then '' when v_lotes = 1 then ' 1 pago que esperaba no saldrá.' else format(' %s pagos que esperaban no saldrán.', v_lotes) end));
end $$;


--
-- Name: FUNCTION conta_pago_dejar(p_company uuid, p_quien uuid, p_quien_nombre text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_pago_dejar(p_company uuid, p_quien uuid, p_quien_nombre text, p_motivo text) IS 'B01 Revolut · 2c-1 · Dejar de pagar, en Sumied y al instante: sin permisos de pago, sin lo que esperaba (cancelado) y la conexión sin PAY. Lo que ya salió al banco sigue su camino.';


--
-- Name: conta_pago_lote_ver(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_lote_ver(p_lote uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.conta_pago_lote; v_t public.treasury_account;
begin
  select * into v_l from public.conta_pago_lote where id = p_lote;
  if v_l.id is null then raise exception 'Ese pago no existe.' using errcode = 'P0002'; end if;
  perform public._conta_pago_empresa(v_l.company_id);
  select * into v_t from public.treasury_account where id = v_l.treasury_account_id;
  return jsonb_build_object('lote', v_l.id, 'estado', v_l.estado, 'huella', v_l.huella, 'creado', v_l.created_at, 'aprobado_por', v_l.created_by_name,
    'desde', jsonb_build_object('nombre', v_t.name, 'iban4', right(public._pc01e2_iban(v_t.iban), 4), 'banco', 'Revolut'),
    'motivos', to_jsonb(v_l.segunda_motivos), 'motivos_texto', (select coalesce(jsonb_agg(public._conta_pago_motivo(m)), '[]'::jsonb) from unnest(v_l.segunda_motivos) m),
    'puedo_dar', public._conta_pago_puede_dar(p_lote, auth.uid()) is null, 'no_puedo_porque', public._conta_pago_puede_dar(p_lote, auth.uid()),
    'segunda', case when v_l.segunda_at is not null then jsonb_build_object('por', v_l.segunda_por_nombre, 'at', v_l.segunda_at, 'via', v_l.segunda_via, 'dispositivo', v_l.segunda_dispositivo) end,
    'total', (select coalesce(sum(amount), 0) from public.conta_pago_salida where lote_id = p_lote and estado <> 'cancelada'),
    'pagos', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'factura', s.invoice_id, 'concepto', s.concepto, 'beneficiario', s.beneficiario,
                'iban4', right(s.iban, 4), 'iban_check', s.iban_check, 'importe', s.amount, 'estado', s.estado,
                'motivos_texto', (select coalesce(jsonb_agg(public._conta_pago_motivo(m)), '[]'::jsonb) from unnest(s.motivos) m)) order by s.created_at), '[]'::jsonb)
                from public.conta_pago_salida s where s.lote_id = p_lote),
    'historial', (select coalesce(jsonb_agg(jsonb_build_object('at', e.at, 'por', e.by_name, 'texto', e.texto) order by e.at), '[]'::jsonb)
                    from public.conta_pago_evento e where e.lote_id = p_lote));
end $$;


--
-- Name: conta_pago_mandar_empezar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_mandar_empezar(p_lote uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_l public.conta_pago_lote; v_sal record; v_cuenta text; v_r uuid; v_code text; v_s public.conta_pago_salida;
  v_inv public.supplier_invoice; v_sup public.supplier; v_lin uuid; v_pagos jsonb := '[]'::jsonb; v_total numeric := 0; v_n int := 0;
begin
  select * into v_l from public.conta_pago_lote where id = p_lote for update;
  if v_l.id is null then raise exception 'Ese pago no existe.' using errcode = 'P0002'; end if;
  if v_l.estado <> 'listo' then
    raise exception 'Este pago no está listo para mandar (está %).', replace(v_l.estado, '_', ' ') using errcode = '23514';
  end if;
  if public._conta_pago_huella(p_lote) <> v_l.huella then
    raise exception 'La lista de pagos ha cambiado desde que se aprobó: no se manda. Vuelve a aprobarla.' using errcode = '23514';
  end if;
  select * into v_sal from public._conta_pago_salida_de(v_l.company_id, v_l.treasury_account_id);
  if not v_sal.puede then raise exception '%', v_sal.porque using errcode = '23514'; end if;
  select b.external_account_id into v_cuenta from public.bank_aggregator_link b
   where b.treasury_account_id = v_l.treasury_account_id and b.company_id = v_l.company_id and b.provider = v_l.proveedor and b.status = 'activo';
  v_code := public._pc01e2_codigo(v_l.company_id, public.conta_hoy());
  insert into public.conta_pago_remesa (account_id, company_id, code, kind, treasury_account_id, pay_date, created_by, created_by_name)
  values (v_l.account_id, v_l.company_id, v_code, 'banco', v_l.treasury_account_id, public.conta_hoy(), v_l.created_by, v_l.created_by_name)
  returning id into v_r;
  for v_s in select * from public.conta_pago_salida where lote_id = p_lote and estado = 'lista' order by created_at, id for update loop
    select * into v_inv from public.supplier_invoice where id = v_s.invoice_id for update;
    if v_inv.status <> 'aprobada' or v_inv.paid_at is not null then
      raise exception 'La factura % ya no está por pagar: no se manda ningún pago del lote.', coalesce(v_inv.invoice_number, '') using errcode = '23514';
    end if;
    -- Su propio importe ya está descontado de lo pendiente (es un pago vivo): basta con que no quede negativo.
    if public._conta_pago_pendiente(v_inv.id) < -0.005 then
      raise exception 'A la factura % ya no le queda %: se ha pagado por otro lado. No se manda ningún pago del lote.',
        coalesce(v_inv.invoice_number, ''), public.conta_euros_exactos(v_s.amount) using errcode = '23514';
    end if;
    select * into v_sup from public.supplier where id = v_s.supplier_id;
    if public._pc01e2_iban(v_sup.iban) is distinct from v_s.iban then
      raise exception 'El IBAN de % ha cambiado en su ficha desde que se aprobó el pago: no se manda. Vuelve a aprobarlo.', coalesce(v_sup.name, 'su proveedor') using errcode = '23514';
    end if;
    insert into public.conta_pago_remesa_linea (account_id, company_id, remesa_id, invoice_id, supplier_id, amount, iban, iban_check, iban_note,
                                                iban_confirmed_at, iban_confirmed_by, iban_confirmed_by_name)
    values (v_l.account_id, v_l.company_id, v_r, v_s.invoice_id, v_s.supplier_id, v_s.amount, v_s.iban, v_s.iban_check, v_s.iban_nota,
            case when v_s.iban_check <> 'comprobado' then v_l.segunda_at end,
            case when v_s.iban_check <> 'comprobado' then v_l.segunda_por end,
            case when v_s.iban_check <> 'comprobado' then v_l.segunda_por_nombre end)
    returning id into v_lin;
    -- La segunda aprobación de un IBAN nuevo, cambiado o leído de la factura lo confirma también en la ficha.
    if v_s.iban_check <> 'comprobado' then
      if v_l.segunda_at is null then
        raise exception 'El IBAN ···· % pedía segunda aprobación y no la tiene: no se manda.', right(v_s.iban, 4) using errcode = '23514';
      end if;
      update public.supplier set iban_verified_at = now(), iban_unconfirmed_invoice_id = null, updated_at = now()
       where id = v_s.supplier_id and public._pc01e2_iban(iban) = v_s.iban;
      perform public._pc01e2_evento(v_l.account_id, v_r, v_lin, format('IBAN ···· %s de %s confirmado con la segunda aprobación de %s (%s).',
        right(v_s.iban, 4), v_s.beneficiario, coalesce(v_l.segunda_por_nombre, 'una persona'), case v_l.segunda_via when 'llave' then 'su llave' else 'su PIN de pago' end));
    end if;
    update public.conta_pago_salida set remesa_id = v_r, remesa_linea_id = v_lin, estado = 'enviando', estado_at = now() where id = v_s.id;
    v_pagos := v_pagos || jsonb_build_array(jsonb_build_object('salida', v_s.id, 'request_id', v_s.request_id, 'importe', v_s.amount,
      'beneficiario', v_s.beneficiario, 'iban', v_s.iban, 'concepto', v_s.concepto));
    v_total := v_total + v_s.amount; v_n := v_n + 1;
  end loop;
  if v_n = 0 then raise exception 'Este lote no tiene ningún pago para mandar.' using errcode = '23514'; end if;
  update public.conta_pago_lote set estado = 'enviando' where id = p_lote;
  perform public._pc01e2_evento(v_l.account_id, v_r, null, format('Se manda a %s: %s %s, %s, desde %s (aprobado por %s).',
    v_sal.banco, v_n, case when v_n = 1 then 'pago' else 'pagos' end, public.conta_euros_exactos(v_total),
    (select name from public.treasury_account where id = v_l.treasury_account_id), coalesce(v_l.created_by_name, 'una persona')));
  perform public._conta_pago_evento(v_l.account_id, p_lote, null, 'Sumied', format('Se manda a %s (remesa %s).', v_sal.banco, v_code));
  return jsonb_build_object('lote', p_lote, 'remesa', v_r, 'codigo', v_code, 'proveedor', v_l.proveedor, 'banco', v_sal.banco,
    'company', v_l.company_id, 'cuenta', v_cuenta, 'pagos', v_pagos, 'total', v_total);
end $$;


--
-- Name: conta_pago_para_mi(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_para_mi(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public._conta_pago_empresa(p_company);
  return (select coalesce(jsonb_agg(jsonb_build_object('lote', l.id, 'aprobado_por', l.created_by_name, 'creado', l.created_at,
            'total', (select sum(amount) from public.conta_pago_salida s where s.lote_id = l.id and s.estado <> 'cancelada'),
            'pagos', (select count(*) from public.conta_pago_salida s where s.lote_id = l.id and s.estado <> 'cancelada')) order by l.created_at), '[]'::jsonb)
            from public.conta_pago_lote l
           where l.company_id = p_company and l.estado = 'esperando_segunda' and public._conta_pago_puede_dar(l.id, auth.uid()) is null
             and l.created_by <> auth.uid());
end $$;


--
-- Name: conta_pago_permiso_dar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_permiso_dar(p_company uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_pago_empresa(p_company); v_n int; v_nombre text;
begin
  if not public.current_user_is_admin_of(v_acc) then raise exception 'Solo un administrador da el permiso de pagar.' using errcode = '42501'; end if;
  if not exists (select 1 from public.user_profiles where user_id = p_user and account_id = v_acc and active) then
    raise exception 'Esa persona no está activa en la cuenta.' using errcode = '23514';
  end if;
  v_nombre := public._conta_pago_nombre(p_user);
  if public._conta_pago_puede(p_company, p_user) then
    select count(*) into v_n from public._conta_pago_pagadores(p_company);
    return jsonb_build_object('n', v_n, 'frase', format('%s ya podía pagar.', v_nombre));
  end if;
  perform pg_advisory_xact_lock(hashtextextended('conta_pago_permiso:' || p_company::text, 0));
  update public.conta_pago_permiso set revoked_at = now(), revoked_by_name = 'Sumied (ya no estaba activa)'
   where company_id = p_company and user_id = p_user and revoked_at is null;
  insert into public.conta_pago_permiso (account_id, company_id, user_id, user_name, granted_by, granted_by_name)
  values (v_acc, p_company, p_user, v_nombre, auth.uid(), coalesce(public.conta_nombre_actor(), 'Sumied'));
  select count(*) into v_n from public._conta_pago_pagadores(p_company);
  return jsonb_build_object('n', v_n, 'frase', format('%s ya puede pagar. %s', v_nombre,
    case when v_n = 1 then 'Es la única persona que paga: confirma la segunda aprobación con su llave (o con su PIN de pago).'
         else format('Pueden pagar %s personas: la segunda aprobación la da otra de ellas, con su llave o su PIN.', v_n) end));
end $$;


--
-- Name: conta_pago_permiso_quitar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_permiso_quitar(p_company uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_pago_empresa(p_company); v_n int; v_k int;
begin
  if not public.current_user_is_admin_of(v_acc) then raise exception 'Solo un administrador quita el permiso de pagar.' using errcode = '42501'; end if;
  update public.conta_pago_permiso set revoked_at = now(), revoked_by_name = coalesce(public.conta_nombre_actor(), 'Sumied')
   where company_id = p_company and user_id = p_user and revoked_at is null;
  get diagnostics v_k = row_count;
  select count(*) into v_n from public._conta_pago_pagadores(p_company);
  return jsonb_build_object('n', v_n, 'frase', case when v_k = 0 then format('%s no podía pagar.', public._conta_pago_nombre(p_user))
    else format('%s ya no puede pagar. %s', public._conta_pago_nombre(p_user),
      case when v_n = 0 then 'Ahora no puede pagar nadie desde Sumied.' when v_n = 1 then 'Queda 1 persona que puede pagar.' else format('Quedan %s personas que pueden pagar.', v_n) end) end);
end $$;


--
-- Name: conta_pago_pin_confirmar(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_pin_confirmar(p_user uuid, p_lote uuid, p_pin_cifrado text, p_huella_vista text, p_dispositivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_p public.conta_pago_pin; v_no text; v_n int;
begin
  v_no := public._conta_pago_puede_dar(p_lote, p_user);
  if v_no is not null then return jsonb_build_object('ok', false, 'porque', v_no); end if;
  select * into v_p from public.conta_pago_pin where user_id = p_user for update;
  if v_p.user_id is null then return jsonb_build_object('ok', false, 'sin_pin', true, 'porque', 'Todavía no tienes PIN de pago: créalo con el código del correo, o confirma con tu llave.'); end if;
  if v_p.bloqueado_at is not null then
    return jsonb_build_object('ok', false, 'bloqueado', true, 'porque', 'Tu PIN de pago está bloqueado. No ha salido ningún pago: siguen aprobados y esperando. Confírmalos con tu llave, o crea un PIN nuevo con el código del correo.');
  end if;
  if lower(coalesce(p_pin_cifrado, '')) <> v_p.pin_cifrado then
    update public.conta_pago_pin set intentos = intentos + 1, bloqueado_at = case when intentos + 1 >= 5 then now() end where user_id = p_user returning intentos into v_n;
    if v_n >= 5 then
      perform public._conta_pago_evento((select account_id from public.conta_pago_lote where id = p_lote), p_lote, null, 'Sumied',
        format('PIN de pago de %s bloqueado tras 5 fallos. No ha salido nada.', public._conta_pago_nombre(p_user)));
      return jsonb_build_object('ok', false, 'bloqueado', true, 'aviso_correo', true, 'porque', 'Tu PIN de pago está bloqueado: 5 fallos. No ha salido ningún pago: siguen aprobados y esperando. Confírmalos con tu llave, o crea un PIN nuevo con el código del correo.');
    end if;
    return jsonb_build_object('ok', false, 'quedan', 5 - v_n, 'porque', format('Ese no es tu PIN de pago. Te %s %s %s. Con 5 fallos se bloquea y tendrás que recuperarlo con el código del correo. Los pagos siguen aprobados y esperando.',
      case when 5 - v_n = 1 then 'queda' else 'quedan' end, 5 - v_n, case when 5 - v_n = 1 then 'intento' else 'intentos' end));
  end if;
  update public.conta_pago_pin set intentos = 0 where user_id = p_user;
  return public._conta_pago_segunda_dar(p_lote, p_user, p_huella_vista, 'pin', p_dispositivo, null);
end $$;


--
-- Name: conta_pago_pin_guardar(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_pin_guardar(p_user uuid, p_pin_cifrado text, p_sal text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_codigo uuid; v_habia boolean;
begin
  select id into v_codigo from public.conta_pago_reto
   where user_id = p_user and proposito = 'crear_pin' and used_at > now() - interval '10 minutes' and llave_id is null and descartado_at is null
   order by used_at desc limit 1 for update;
  if v_codigo is null then raise exception 'Para crear tu PIN de pago, confirma antes que eres tú con el código del correo.' using errcode = '42501'; end if;
  update public.conta_pago_reto set descartado_at = now() where id = v_codigo;
  select exists (select 1 from public.conta_pago_pin where user_id = p_user) into v_habia;
  insert into public.conta_pago_pin (user_id, pin_cifrado, sal) values (p_user, lower(p_pin_cifrado), lower(p_sal))
  on conflict (user_id) do update set pin_cifrado = excluded.pin_cifrado, sal = excluded.sal, intentos = 0, bloqueado_at = null, cambiado_at = now();
  return jsonb_build_object('nuevo', not v_habia, 'frase', case when v_habia then 'PIN de pago cambiado. Te hemos avisado al correo.'
    else 'PIN de pago guardado. Lo usarás cuando no tengas tu llave a mano.' end);
end $$;


--
-- Name: conta_pago_pin_mio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_pin_mio() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('tiene', exists (select 1 from public.conta_pago_pin where user_id = auth.uid()),
    'bloqueado', exists (select 1 from public.conta_pago_pin where user_id = auth.uid() and bloqueado_at is not null),
    'quedan', (select 5 - intentos from public.conta_pago_pin where user_id = auth.uid()))
$$;


--
-- Name: conta_pago_pin_sal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_pin_sal(p_user uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('sal', sal, 'bloqueado', bloqueado_at is not null, 'quedan', 5 - intentos)
    from public.conta_pago_pin where user_id = p_user
$$;


--
-- Name: conta_pago_por_saber(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_por_saber(p_company uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('salida', s.id, 'request_id', s.request_id, 'banco_id', s.banco_id, 'estado', s.estado) order by s.created_at), '[]'::jsonb)
    from public.conta_pago_salida s
   where s.company_id = p_company and s.estado in ('enviando', 'enviada', 'esperando_banco')
$$;


--
-- Name: conta_pago_preparar(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_preparar(p_company uuid, p_invoice uuid, p_treasury uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_pago_empresa(p_company); v_f jsonb; v_sal record; v_t record; v_hoy numeric; v_motivos jsonb; v_quien jsonb;
begin
  v_f := public._conta_pago_factura(p_company, p_invoice, null, null);
  select * into v_sal from public._conta_pago_salida_de(p_company, p_treasury);
  v_quien := public.conta_pago_quien(p_company);
  if v_f->>'porque' is null then
    select * into v_t from public._conta_pago_topes(p_company);
    v_hoy := public._conta_pago_aprobado_hoy(p_company);
    v_motivos := v_f->'motivos';
    if v_hoy + (v_f->>'importe')::numeric > v_t.tope_dia then v_motivos := v_motivos || '"tope_dia"'::jsonb; end if;
    v_f := v_f || jsonb_build_object('motivos', v_motivos,
      'motivos_texto', (select coalesce(jsonb_agg(public._conta_pago_motivo(m)), '[]'::jsonb) from jsonb_array_elements_text(v_motivos) m),
      'tope_pago', v_t.tope_pago, 'tope_dia', v_t.tope_dia, 'aprobado_hoy', v_hoy);
  end if;
  return v_f || jsonb_build_object('se_puede', v_f->>'porque' is null and v_sal.puede and (v_quien->>'yo_puedo')::boolean,
    'salida', jsonb_build_object('proveedor', v_sal.proveedor, 'banco', v_sal.banco, 'puede', v_sal.puede, 'porque', v_sal.porque),
    'quien', v_quien,
    'porque', coalesce(v_f->>'porque', v_sal.porque,
      case when not (v_quien->>'yo_puedo')::boolean then
        case when (v_quien->>'n')::int = 0 then 'Nadie tiene todavía el permiso de pagar en esta empresa: lo da un administrador al «Activar pagos».'
             else format('No tienes permiso para pagar. Pídeselo a %s, que puede pagar.', (select string_agg(x->>'nombre', ' o ') from jsonb_array_elements(v_quien->'personas') x)) end end));
end $$;


--
-- Name: conta_pago_quien(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_quien(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_pago_empresa(p_company); v_p jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('nombre', p.nombre, 'yo', p.user_id = auth.uid())), '[]'::jsonb) into v_p from public._conta_pago_pagadores(p_company) p;
  return jsonb_build_object('yo_puedo', public._conta_pago_puede(p_company, auth.uid()), 'soy_admin', public.current_user_is_admin_of(v_acc),
    'personas', v_p, 'n', jsonb_array_length(v_p),
    'segunda', case when jsonb_array_length(v_p) >= 2 then 'otra' else 'la_misma' end);
end $$;


--
-- Name: conta_pago_reto_crear(uuid, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_reto_crear(p_user uuid, p_proposito text, p_via text, p_reto_huella text, p_lote uuid, p_correo_mascara text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l public.conta_pago_lote; v_no text; v_id uuid; v_acc uuid;
begin
  if p_proposito = 'confirmar' then
    select * into v_l from public.conta_pago_lote where id = p_lote for update;
    v_no := public._conta_pago_puede_dar(p_lote, p_user);
    if v_no is not null then raise exception '%', v_no using errcode = '42501'; end if;
    v_acc := v_l.account_id;
  elsif p_proposito = 'registrar' then
    -- Registrar una llave nueva pide antes el código del correo, usado hace menos de 10 minutos y sin llave todavía.
    if not exists (select 1 from public.conta_pago_reto r where r.user_id = p_user and r.proposito = 'activar_llave' and r.used_at > now() - interval '10 minutes' and r.llave_id is null) then
      raise exception 'Para activar una llave nueva, confirma antes que eres tú con el código del correo.' using errcode = '42501';
    end if;
  elsif p_proposito not in ('activar_llave', 'crear_pin') then
    raise exception 'Propósito de reto desconocido.' using errcode = '22023';
  end if;
  update public.conta_pago_reto set descartado_at = now()
   where user_id = p_user and proposito = p_proposito and lote_id is not distinct from p_lote and used_at is null and descartado_at is null;
  insert into public.conta_pago_reto (user_id, account_id, lote_id, proposito, via, reto_huella, huella_lote, correo_mascara, expires_at)
  values (p_user, v_acc, case when p_proposito = 'confirmar' then p_lote end, p_proposito, p_via, lower(p_reto_huella), v_l.huella, p_correo_mascara, now() + interval '10 minutes')
  returning id into v_id;
  return jsonb_build_object('reto', v_id, 'caduca', now() + interval '10 minutes');
end $$;


--
-- Name: conta_pago_reto_usar(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_reto_usar(p_reto uuid, p_user uuid, p_reto_huella text, p_dispositivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_r public.conta_pago_reto; v_n int;
begin
  select * into v_r from public.conta_pago_reto where id = p_reto for update;
  if v_r.id is null or v_r.user_id <> p_user then return jsonb_build_object('ok', false, 'porque', 'Ese código no es tuyo. Pide otro.'); end if;
  if v_r.used_at is not null then return jsonb_build_object('ok', false, 'porque', 'Ese código ya se usó: vale una sola vez. Pide otro.'); end if;
  if v_r.descartado_at is not null then return jsonb_build_object('ok', false, 'porque', 'Ese código ya no vale: se pidió otro después, o el pago se canceló.'); end if;
  if v_r.expires_at < now() then
    return jsonb_build_object('ok', false, 'caducado', true, 'porque', format('Ha caducado. Valía 10 minutos y se pidió a las %s. Pide otro%s.',
      to_char(v_r.created_at at time zone 'Europe/Madrid', 'HH24:MI'), case when v_r.proposito = 'confirmar' then ': los pagos siguen aprobados y esperando' else '' end));
  end if;
  if lower(p_reto_huella) <> v_r.reto_huella then
    if v_r.via = 'llave' then
      update public.conta_pago_reto set descartado_at = now() where id = p_reto;
      return jsonb_build_object('ok', false, 'porque', 'La llave no ha firmado esto. Vuelve a pulsar el botón.');
    end if;
    update public.conta_pago_reto set intentos = intentos + 1 where id = p_reto returning intentos into v_n;
    if v_n >= 3 then
      update public.conta_pago_reto set descartado_at = now() where id = p_reto;
      return jsonb_build_object('ok', false, 'porque', 'Tres códigos equivocados: este ya no vale. Pide otro.');
    end if;
    return jsonb_build_object('ok', false, 'quedan', 3 - v_n, 'porque', format('Ese código no es el que te hemos mandado. Te %s %s %s.',
      case when 3 - v_n = 1 then 'queda' else 'quedan' end, 3 - v_n, case when 3 - v_n = 1 then 'intento' else 'intentos' end));
  end if;
  if v_r.proposito = 'confirmar' then
    return public._conta_pago_segunda_dar(v_r.lote_id, p_user, v_r.huella_lote, 'llave', p_dispositivo, p_reto);
  end if;
  update public.conta_pago_reto set used_at = now() where id = p_reto;
  return jsonb_build_object('ok', true, 'proposito', v_r.proposito);
end $$;


--
-- Name: conta_pago_topes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_topes(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_t record;
begin
  perform public._conta_pago_empresa(p_company);
  select * into v_t from public._conta_pago_topes(p_company);
  return jsonb_build_object('tope_pago', v_t.tope_pago, 'tope_dia', v_t.tope_dia, 'aprobado_hoy', public._conta_pago_aprobado_hoy(p_company));
end $$;


--
-- Name: conta_pago_topes_poner(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pago_topes_poner(p_company uuid, p_tope_pago numeric, p_tope_dia numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_pago_empresa(p_company);
begin
  if not public.current_user_is_admin_of(v_acc) then raise exception 'Solo un administrador cambia los topes de pago.' using errcode = '42501'; end if;
  if p_tope_pago is null or p_tope_dia is null or p_tope_pago <= 0 or p_tope_dia <= 0 then raise exception 'Los dos topes tienen que ser mayores que cero.' using errcode = '22023'; end if;
  if p_tope_pago > p_tope_dia then raise exception 'El tope por pago no puede ser mayor que el del día.' using errcode = '22023'; end if;
  insert into public.conta_pago_ajustes (company_id, account_id, tope_pago, tope_dia, updated_by, updated_by_name)
  values (p_company, v_acc, round(p_tope_pago, 2), round(p_tope_dia, 2), auth.uid(), coalesce(public.conta_nombre_actor(), 'Sumied'))
  on conflict (company_id) do update set tope_pago = excluded.tope_pago, tope_dia = excluded.tope_dia,
    updated_at = now(), updated_by = excluded.updated_by, updated_by_name = excluded.updated_by_name;
  return jsonb_build_object('frase', format('Topes guardados: %s por pago y %s al día. Por encima, hace falta una segunda aprobación.',
    public.conta_euros_exactos(round(p_tope_pago, 2)), public.conta_euros_exactos(round(p_tope_dia, 2))));
end $$;


--
-- Name: conta_pagos_lista(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pagos_lista(p_company uuid, p_mes date) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with f as (
    select si.id, si.supplier_id, s.name as proveedor, si.invoice_number as numero, si.invoice_date as fecha, rp.vence, rp.total, rp.pagado, rp.pendiente,
           rp.estado, rp.dias_vencida, coalesce(si.payment_method, s.payment_method) as forma, si.location_id, lo.name as local,
           right(public._pc01e2_iban(s.iban), 4) as iban4, (public._pc01e2_iban(s.iban) is not null) as con_iban,
           (s.iban_unconfirmed_invoice_id is not null) as iban_sin_confirmar, right(public._pc01e2_iban(si.read_iban), 4) as iban_leido4,
           (public._pc01e2_iban(si.read_iban) is not null and si.iban_decision is null and public._pc01e2_iban(s.iban) is not null
              and public._pc01e2_iban(si.read_iban) <> public._pc01e2_iban(s.iban)) as iban_distinto,
           exists (select 1 from public.company_account_link l where l.company_id = p_company and l.entity = 'supplier' and l.entity_id = s.id::text and l.role = 'principal') as con_cuenta,
           s.payment_terms_days as plazo,
           (select jsonb_build_object('id', r.id, 'codigo', r.code, 'importe', sum(l.amount))
              from public.conta_pago_remesa_linea_estado l join public.conta_pago_remesa r on r.id = l.remesa_id
             where l.invoice_id = si.id and l.estado in ('pendiente', 'por_confirmar') group by r.id, r.code order by r.code desc limit 1) as remesa
      from public.supplier_invoice si
      join public.conta_recibida_pago rp on rp.invoice_id = si.id
      left join public.supplier s on s.id = si.supplier_id
      left join public.locations lo on lo.id = si.location_id
     where si.account_id = (select account_id from public.company where id = p_company)
       and coalesce(si.company_id, p_company) = p_company
       and si.status in ('aprobada', 'pagada')
       -- S01i · Lo que se compensa (comisiones de plataformas, abonos) no se paga por banco: no sale en Pagos.
       and si.payment_method is distinct from 'compensation' and si.paid_method is distinct from 'compensation'
  )
  select jsonb_build_object(
    'filas', coalesce((select jsonb_agg(to_jsonb(f) order by f.vence nulls last, f.fecha) from f), '[]'::jsonb),
    'pagado_mes', (select coalesce(sum(p.amount), 0) from public.supplier_invoice_payment p join f on f.id = p.invoice_id
                    where p.entry_id is not null and p.paid_on >= date_trunc('month', p_mes)::date and p.paid_on < (date_trunc('month', p_mes) + interval '1 month')::date),
    'pagadas_mes', (select count(distinct p.invoice_id) from public.supplier_invoice_payment p join f on f.id = p.invoice_id
                     where p.entry_id is not null and p.paid_on >= date_trunc('month', p_mes)::date and p.paid_on < (date_trunc('month', p_mes) + interval '1 month')::date),
    'sin_plazo', coalesce((select jsonb_agg(distinct jsonb_build_object('id', f.supplier_id, 'nombre', f.proveedor))
                            from f where f.estado = 'sin_vencimiento' and f.plazo is null and f.supplier_id is not null), '[]'::jsonb))
$$;


--
-- Name: FUNCTION conta_pagos_lista(p_company uuid, p_mes date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_pagos_lista(p_company uuid, p_mes date) IS 'PC01 · E2 · Compras › Pagos: las recibidas por pagar y pagadas de la empresa, con su estado, su remesa y lo pagado en el mes.';


