CREATE FUNCTION public.conta_pais_nombre(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select coalesce((select n from (values
    ('ES', 'España'), ('AT', 'Austria'), ('BE', 'Bélgica'), ('BG', 'Bulgaria'), ('CY', 'Chipre'), ('CZ', 'Chequia'),
    ('DE', 'Alemania'), ('DK', 'Dinamarca'), ('EE', 'Estonia'), ('EL', 'Grecia'), ('GR', 'Grecia'), ('FI', 'Finlandia'),
    ('FR', 'Francia'), ('HR', 'Croacia'), ('HU', 'Hungría'), ('IE', 'Irlanda'), ('IT', 'Italia'), ('LT', 'Lituania'),
    ('LU', 'Luxemburgo'), ('LV', 'Letonia'), ('MT', 'Malta'), ('NL', 'Países Bajos'), ('PL', 'Polonia'), ('PT', 'Portugal'),
    ('RO', 'Rumanía'), ('SE', 'Suecia'), ('SI', 'Eslovenia'), ('SK', 'Eslovaquia'),
    ('US', 'Estados Unidos'), ('GB', 'Reino Unido'), ('CH', 'Suiza'), ('NO', 'Noruega'), ('SG', 'Singapur'),
    ('CN', 'China'), ('JP', 'Japón'), ('CA', 'Canadá'), ('AU', 'Australia'), ('MX', 'México'), ('AD', 'Andorra'),
    ('MA', 'Marruecos'), ('TR', 'Turquía'), ('IN', 'India'), ('IL', 'Israel'), ('KR', 'Corea del Sur'),
    ('BR', 'Brasil'), ('AR', 'Argentina')) t(c, n) where t.c = upper(p)), upper(p))
$$;


