--
-- Name: conta_pedidos_del_dia(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pedidos_del_dia(p_company uuid, p_location uuid, p_dia date) RETURNS TABLE(id uuid, codigo text, canal_id uuid, marca_id uuid, propia boolean, estado text, total numeric, base numeric, cuota numeric, tipos numeric[])
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  with p as (
    -- Los del día (Madrid) que no se han quitado ni pasado a otro…
    select s.*, a.importe as ajuste
      from public.sale s
      join public.company c on c.id = p_company and c.account_id = s.account_id
      left join public.conta_cierre_ajuste a on a.company_id = p_company and a.sale_id = s.id
     where s.location_id = p_location and s.is_active
       and s.sold_at >= (p_dia::timestamp at time zone 'Europe/Madrid') and s.sold_at < ((p_dia + 1)::timestamp at time zone 'Europe/Madrid')
       and s.status in ('closed', 'cancelled', 'open')
       and not coalesce(a.quitado or a.dia_destino is not null, false)
    union all
    -- …y los de otro día que se han pasado a este (V01, conta_cierre_ajuste).
    select s.*, a.importe
      from public.conta_cierre_ajuste a
      join public.sale s on s.id = a.sale_id and s.account_id = a.account_id
     where a.company_id = p_company and a.location_id = p_location and a.dia_destino = p_dia and not a.quitado
       and s.location_id = p_location and s.is_active and s.status in ('closed', 'cancelled', 'open')
  )
  select s.id, coalesce(s.platform_order_code, s.pos_short_code, s.external_ref), s.channel_id, s.brand_id,
         coalesce(b.ownership_type, 'own') = 'own',
         -- Cierre del día: el no confirmado no es una anulación; se dice aparte.
         case when s.status = 'cancelled' and s.unconfirmed_at is not null then 'unconfirmed' else s.status end,
         -- V01: con otro importe, ese; la base y la cuota, en proporción.
         coalesce(s.ajuste, s.total),
         case when s.ajuste is null then s.taxable_base
              when s.taxable_base is null or coalesce(s.total, 0) = 0 then null
              else round(s.taxable_base * s.ajuste / s.total, 2) end,
         case when s.ajuste is null then s.tax
              when s.taxable_base is null or coalesce(s.total, 0) = 0 then null
              else s.ajuste - round(s.taxable_base * s.ajuste / s.total, 2) end,
         coalesce((select array_agg(distinct (it->>'tax_rate')::numeric)
                     from jsonb_array_elements(case when jsonb_typeof(public.conta_json_seguro(s.raw_tab)->'items') = 'array'
                                                    then public.conta_json_seguro(s.raw_tab)->'items' else '[]'::jsonb end) it
                    where it->>'tax_rate' ~ '^[0-9]+(\.[0-9]+)?$'), '{}')
    from p s
    left join public.brand b on b.id = s.brand_id
$_$;


--
-- Name: FUNCTION conta_pedidos_del_dia(p_company uuid, p_location uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_pedidos_del_dia(p_company uuid, p_location uuid, p_dia date) IS 'C04. Los pedidos de un día (hora de Madrid) y un local, con si la marca es propia, la base y la cuota que traigan, y los tipos de sus líneas (HubRise). Solo lectura.';


--
-- Name: conta_pendientes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_pendientes(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid;
  v_hoy date := (now() at time zone 'Europe/Madrid')::date;
  v_mirar jsonb;
  v_docs jsonb;
  v_para int; v_por int; v_asientos int; v_confirmar int; v_aclarar int; v_validar int;
begin
  select c.account_id into v_acc from public.company c where c.id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;

  -- Compras: las filas crudas de «Qué tienes que mirar» (las agrupa el cliente).
  begin
    v_mirar := public.compras_mirar(v_acc);
  exception when others then v_mirar := null;
  end;

  -- Facturas recibidas: la misma llamada que su pantalla, los 12 meses de ventanaParaRevisar.
  begin
    v_docs := public.conta_documentos_recibidos(p_company,
                (date_trunc('month', v_hoy) - interval '11 months')::date,
                (date_trunc('month', v_hoy) + interval '1 month' - interval '1 day')::date);
    select count(*) filter (where f->>'estado' = 'para_mirar'), count(*) filter (where f->>'estado' = 'por_aclarar')
      into v_para, v_por
      from jsonb_array_elements(v_docs->'filas') f
     where f->>'tipo' = 'factura';
  exception when others then v_para := null; v_por := null;
  end;

  -- Asientos: lo de «Para revisar», menos lo que se decide en su sitio y lo que espera.
  begin
    with esperan as materialized (
      select distinct w.entry_id from public.conta_esperan(p_company, date '1900-01-01', date '2999-12-31') w
    )
    select count(*) into v_asientos
      from public.journal_entry e
     where e.account_id = v_acc and e.company_id = p_company
       and e.status in ('propuesto', 'borrador')
       and not (e.status = 'propuesto' and e.source_type in ('supplier_invoice', 'bank'))
       and not exists (select 1 from esperan w where w.entry_id = e.id);
  exception when others then v_asientos := null;
  end;

  -- Bancos: las bandejas de Movimientos.
  begin
    select count(*) filter (where m.status = 'propuesto'),
           count(*) filter (where m.status in ('por_aclarar', 'pendiente', 'posible_repetido'))
      into v_confirmar, v_aclarar
      from public.bank_movement m
     where m.account_id = v_acc and m.company_id = p_company;
    select count(*) into v_validar
      from public.bank_movement m
     where m.account_id = v_acc and m.company_id = p_company and m.status = 'casado'
       and exists (select 1 from public.bank_match b join public.journal_entry e on e.id = b.journal_entry_id
                    where b.movement_id = m.id and b.account_id = v_acc and b.company_id = p_company
                      and b.status = 'vivo' and e.status = 'propuesto');
  exception when others then v_confirmar := null; v_aclarar := null; v_validar := null;
  end;

  return jsonb_build_object(
    'compras_decidir', null,
    'compras_filas', v_mirar,
    'facturas_para_mirar', v_para,
    'facturas_por_aclarar', v_por,
    'asientos_por_validar', v_asientos,
    'bancos_confirmar', v_confirmar,
    'bancos_aclarar', v_aclarar,
    'bancos_validar', v_validar);
end $$;


--
-- Name: FUNCTION conta_pendientes(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_pendientes(p_company uuid) IS 'S02 · PR 3 (0490). Solo lee. Lo que espera una acción de una persona en una empresa, contado una vez con la vara de su pantalla: compras_filas (compras_mirar crudo; compras_decidir lo agrupa el cliente con agruparAMirar, por eso va null), facturas_para_mirar y facturas_por_aclarar (conta_documentos_recibidos, 12 meses), asientos_por_validar (propuesto|borrador menos lo que se decide en su sitio y lo que espera), bancos_confirmar, bancos_aclarar y bancos_validar. Null = no se ha podido contar.';


--
-- Name: conta_plataforma_plazo_guardar(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_plataforma_plazo_guardar(p_party uuid, p_cada text, p_dias integer, p_margen integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_r public.party_role; v_n int := 0; v_canal text;
begin
  select * into v_r from public.party_role where party_id = p_party and role = 'platform' for update;
  if v_r.id is null or not public.belongs_to_account(v_r.account_id) then raise exception 'Este contacto no está como plataforma.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_r.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta cambia cuándo paga una plataforma.' using errcode = '42501';
  end if;
  if p_cada is not null and p_cada not in ('weekly', 'fortnightly', 'monthly') then raise exception 'El periodo es cada semana, cada quincena o cada mes.' using errcode = '22023'; end if;
  if p_dias is not null and (p_dias < 0 or p_dias > 90) then raise exception 'Los días hasta el pago van de 0 a 90.' using errcode = '22023'; end if;
  if p_margen is not null and (p_margen < 0 or p_margen > 60) then raise exception 'El margen va de 0 a 60 días.' using errcode = '22023'; end if;
  update public.party_role set settlement_every = p_cada, payout_days_after = p_dias, payout_margin_days = p_margen where id = v_r.id;
  if v_r.channel_id is not null then
    with f as (
      select ci.id, public.conta_vence_de_factura(ci.id) v from public.customer_invoice ci
       where ci.account_id = v_r.account_id and ci.status = 'emitida' and ci.origin = 'cierre_dia' and ci.total > 0
         and public.conta_canal_de_factura(ci.id) = v_r.channel_id
         and ci.total - coalesce((select sum(p.amount) from public.customer_invoice_payment p where p.invoice_id = ci.id), 0) >= 0.005)
    update public.customer_invoice ci set due_date = f.v from f where f.id = ci.id and f.v is not null and ci.due_date is distinct from f.v;
    get diagnostics v_n = row_count;
    select name into v_canal from public.sales_channel where id = v_r.channel_id;
  end if;
  return jsonb_build_object('party_id', p_party, 'canal', v_canal, 'facturas', v_n);
end $$;


--
-- Name: FUNCTION conta_plataforma_plazo_guardar(p_party uuid, p_cada text, p_dias integer, p_margen integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_plataforma_plazo_guardar(p_party uuid, p_cada text, p_dias integer, p_margen integer) IS 'PC01 · Guarda cuándo paga una plataforma (periodo, días hasta el pago, margen) y recoloca el vencimiento de sus facturas por cobrar. Dice cuántas.';


--
-- Name: conta_plataforma_resolver(uuid, uuid, uuid, date, date, uuid, text, numeric, text, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_plataforma_resolver(p_company uuid, p_canal uuid, p_local uuid, p_desde date, p_hasta date, p_pedido uuid, p_tipo text, p_importe numeric, p_frase text, p_fecha date DEFAULT NULL::date, p_lineas jsonb DEFAULT NULL::jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor()); v_r jsonb; v_entry uuid; v_val jsonb;
  v_id uuid; v_canal text; v_frase text := btrim(coalesce(p_frase, ''));
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'Solo un administrador o un encargado de la cuenta resuelve diferencias.' using errcode = '42501';
  end if;
  if p_tipo not in ('gasto', 'reclamacion') then raise exception 'Una diferencia se resuelve como gasto o como reclamación.' using errcode = '22023'; end if;
  if v_frase = '' then raise exception 'Escribe en una frase por qué.' using errcode = '22023'; end if;
  if p_importe is null or p_importe = 0 then raise exception 'La diferencia tiene que tener importe.' using errcode = '22023'; end if;
  select name into v_canal from public.sales_channel where id = p_canal and account_id = v_cuenta;
  if v_canal is null then raise exception 'Esa plataforma no es de la cuenta.' using errcode = '23514'; end if;
  if p_local is not null and not exists (select 1 from public.locations where id = p_local and account_id = v_cuenta) then
    raise exception 'Ese local no es de la cuenta.' using errcode = '23514';
  end if;
  if p_pedido is not null and not exists (select 1 from public.sale where id = p_pedido and account_id = v_cuenta and channel_id = p_canal) then
    raise exception 'Ese pedido no es de esa plataforma.' using errcode = '23514';
  end if;
  if exists (select 1 from public.conta_liquidacion_resolucion r
              where r.company_id = p_company and r.channel_id = p_canal and r.location_id is not distinct from p_local
                and r.period_from = p_desde and r.period_to = p_hasta and r.sale_id is not distinct from p_pedido) then
    raise exception 'Esa diferencia ya está resuelta.' using errcode = '23505';
  end if;
  -- Un gasto de la liquidación entera: su asiento, validado.
  if p_tipo = 'gasto' and p_pedido is null then
    if p_lineas is null or jsonb_typeof(p_lineas) <> 'array' or jsonb_array_length(p_lineas) < 2 then
      raise exception 'Un gasto lleva su asiento.' using errcode = '22023';
    end if;
    v_r := public._journal_entry_proponer(p_company,
      jsonb_build_object('series', 1, 'fecha', coalesce(p_fecha, p_hasta), 'source_type', 'manual',
        'concepto', 'Diferencia de la liquidación de ' || v_canal || ' (' || to_char(p_desde, 'DD/MM') || '–' || to_char(p_hasta, 'DD/MM/YYYY') || '): ' || v_frase,
        'confianza', 'seguro', 'porque', 'Diferencia resuelta como gasto en Ventas › Liquidaciones.'),
      p_lineas, null, v_quien, auth.uid());
    v_entry := (v_r->>'id')::uuid;
    v_val := public.journal_entry_validar(v_entry, v_quien);
  end if;
  -- Un pedido reclamado (o dado por gasto: su devolución la propone el
  -- navegador al libro, como en Lo que deja el cierre del día) sale del aviso del C11b.
  if p_pedido is not null then
    insert into public.journal_dismissal (account_id, company_id, source_type, source_key, reason, created_by, created_by_name)
    select v_cuenta, p_company, 'sales_adjustment', p_pedido::text,
           case p_tipo when 'reclamacion' then 'Reclamado a ' || v_canal || ': ' else 'Gasto (su devolución, al libro): ' end || v_frase, auth.uid(), v_quien
     where not exists (select 1 from public.journal_dismissal d where d.company_id = p_company and d.source_type = 'sales_adjustment' and d.source_key = p_pedido::text);
  end if;
  insert into public.conta_liquidacion_resolucion (account_id, company_id, channel_id, location_id, period_from, period_to, sale_id, kind, importe, frase,
                                                   entry_id, created_by, created_by_name)
  values (v_cuenta, p_company, p_canal, p_local, p_desde, p_hasta, p_pedido, p_tipo, round(p_importe, 2), v_frase, v_entry, auth.uid(), v_quien)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'asiento', v_entry, 'numero_asiento', v_val->'numero');
end $$;


--
-- Name: conta_plataformas(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_plataformas(p_company uuid, p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_r jsonb;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  with liq as (
    select cs.*, ps.external_text as tienda, coalesce(cs.location_id, ps.location_id) as local_id,
           coalesce(cs.period_from, cs.proposed_period_from, cs.settlement_date) as desde,
           coalesce(cs.period_to, cs.proposed_period_to, cs.settlement_date) as hasta
      from public.channel_settlement cs
      left join public.platform_store ps on ps.id = cs.store_id and ps.account_id = v_cuenta
     where cs.account_id = v_cuenta and cs.channel_id is not null
       and (ps.id is null or ps.company_id = p_company)
  ), sel as (
    select * from liq
     where desde is not null and (p_hasta is null or desde <= p_hasta) and (p_desde is null or hasta >= p_desde)
  ), grupos as (
    select channel_id, local_id, desde, hasta from sel group by 1, 2, 3, 4
  ), sinconf as (
    select x.sale_id, x.location_id, x.dia, x.codigo, x.canal_id, x.total from public.conta_sin_confirmar_no_cobrados(p_company) x
  )
  select coalesce(jsonb_agg(g.j order by g.hasta desc, g.canal, g.local nulls last), '[]'::jsonb) into v_r from (
    select gr.hasta, ch.name as canal, l.name as local, jsonb_build_object(
      'canal_id', gr.channel_id, 'canal', coalesce(ch.name, 'Plataforma'), 'local_id', gr.local_id, 'local', l.name,
      'desde', gr.desde, 'hasta', gr.hasta,
      'liquidaciones', (
        select jsonb_agg(jsonb_build_object(
                 'id', s.id, 'tienda', s.tienda, 'ref', s.settlement_ref, 'fecha', s.settlement_date, 'pedidos', s.orders_count,
                 'ventas', s.gross_sales, 'comision', abs(coalesce(s.commission, 0)), 'neto', s.net_payout,
                 'deuda', s.accumulated_debt, 'cobrado', s.collected_amount, 'cobrado_el', s.collected_on,
                 'referencia', coalesce(s.is_reference, false), 'por_aclarar', case when s.needs_review and not coalesce(s.is_reference, false) then s.review_note end,
                 'a_facturar', nullif((s.raw->'factura'->>'total')::numeric, 0),
                 'factura', case when si.id is not null then jsonb_build_object('id', si.id, 'numero', si.invoice_number, 'base', si.tax_base_total, 'total', si.grand_total, 'estado', si.status) end,
                 'casada_en_banco', exists (select 1 from public.bank_match_item i join public.bank_match b on b.id = i.match_id
                                              where i.channel_settlement_id = s.id and b.status = 'vivo'),
                 'asiento', (select jsonb_build_object('id', e.id, 'estado', e.status, 'numero', e.number)
                               from public.journal_entry e where e.company_id = p_company and e.source_type = 'channel_settlement'
                                and e.source_id = s.id and e.status <> 'anulado' order by e.created_at desc limit 1))
               order by s.settlement_date, s.tienda)
          from sel s left join public.supplier_invoice si on si.id = s.commission_invoice_id and si.account_id = v_cuenta
         where s.channel_id = gr.channel_id and s.local_id is not distinct from gr.local_id and s.desde = gr.desde and s.hasta = gr.hasta),
      -- Las ventas de sus cierres (marcas propias), de ese canal, ese local y esos días.
      'cierres', (
        select jsonb_build_object('total', coalesce(sum(d.total), 0), 'dias', count(distinct d.sales_day),
                                  'validados', count(*) filter (where e.status = 'validado'), 'por_validar', count(*) filter (where e.status in ('propuesto', 'borrador')))
          from public.sales_day_summary d left join public.journal_entry e on e.id = d.entry_id
         where gr.local_id is not null and d.company_id = p_company and d.channel_id = gr.channel_id and d.location_id = gr.local_id
           and d.sales_day between gr.desde and gr.hasta and coalesce(e.status, 'propuesto') <> 'anulado'),
      -- Las de las marcas cedidas: la plataforma las paga, pero no son ventas de la empresa.
      'cedidas', (
        select jsonb_build_object('total', coalesce(sum(s.total), 0), 'pedidos', count(*))
          from public.sale s join public.brand b on b.id = s.brand_id and b.account_id = v_cuenta and b.ownership_type = 'licensed'
         where gr.local_id is not null and s.account_id = v_cuenta and s.channel_id = gr.channel_id and s.location_id = gr.local_id
           and s.status = 'closed' and coalesce(s.is_active, true)
           and (s.sold_at at time zone 'Europe/Madrid')::date between gr.desde and gr.hasta),
      -- Los cerrados sin confirmar que la liquidación no cobra (C11b): los que
      -- siguen en el aviso, y los ya resueltos aquí (regla 7: no desaparecen).
      'sin_confirmar', coalesce((
        select jsonb_agg(jsonb_build_object('sale_id', x.sale_id, 'codigo', x.codigo, 'dia', x.dia, 'total', x.total) order by x.dia, x.codigo)
          from sinconf x
         where x.canal_id = gr.channel_id and x.location_id is not distinct from gr.local_id and x.dia between gr.desde and gr.hasta), '[]'::jsonb),
      'resoluciones', coalesce((
        select jsonb_agg(jsonb_build_object('id', r.id, 'sale_id', r.sale_id, 'tipo', r.kind, 'importe', r.importe, 'frase', r.frase,
                                            'asiento_id', r.entry_id, 'quien', r.created_by_name, 'cuando', r.created_at,
                                            'codigo', (select coalesce(s.platform_order_code, s.pos_short_code, s.external_ref) from public.sale s where s.id = r.sale_id and s.account_id = v_cuenta),
                                            'dia', (select (s.sold_at at time zone 'Europe/Madrid')::date from public.sale s where s.id = r.sale_id and s.account_id = v_cuenta),
                                            'total', (select s.total from public.sale s where s.id = r.sale_id and s.account_id = v_cuenta))
               order by r.created_at)
          from public.conta_liquidacion_resolucion r
         where r.company_id = p_company and r.channel_id = gr.channel_id and r.location_id is not distinct from gr.local_id
           and r.period_from = gr.desde and r.period_to = gr.hasta), '[]'::jsonb)
    ) as j
      from grupos gr
      left join public.sales_channel ch on ch.id = gr.channel_id and ch.account_id = v_cuenta
      left join public.locations l on l.id = gr.local_id and l.account_id = v_cuenta
  ) g;
  return v_r;
end $$;


--
-- Name: conta_por_cerrar(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_por_cerrar(p_company uuid, p_ahora timestamp with time zone DEFAULT now()) RETURNS TABLE(sale_id uuid, location_id uuid, sales_day date, sold_at timestamp with time zone, order_code text, total numeric, order_status text, delivery_state text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select s.id, s.location_id, (s.sold_at at time zone 'Europe/Madrid')::date, s.sold_at,
         coalesce(s.platform_order_code, s.pos_short_code, s.external_ref), s.total, s.order_status, s.delivery_state
    from public.sale s
    join public.company c on c.id = p_company and c.account_id = s.account_id
    left join public.brand b on b.id = s.brand_id
   where s.status = 'open' and s.is_active and coalesce(b.ownership_type, 'own') = 'own'
     and s.sold_at < public.conta_cerrado_hasta(p_company, p_ahora)
   order by s.sold_at
$$;


--
-- Name: FUNCTION conta_por_cerrar(p_company uuid, p_ahora timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_por_cerrar(p_company uuid, p_ahora timestamp with time zone) IS 'Cierre del día: los pedidos de marca propia que siguen abiertos en días ya cerrados. Lo que cerraría conta_cerrar_dias, sin tocar nada.';


--
-- Name: conta_primer_dia_abierto(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_primer_dia_abierto(p_company uuid, p_fecha date) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select min(d)::date
    from generate_series(p_fecha, p_fecha + 400, interval '1 day') d
   where not public.conta_mes_cerrado(p_company, d::date)
     and exists (select 1 from public.fiscal_year y
                  where y.company_id = p_company and y.status = 'open' and d::date between y.starts_on and y.ends_on
                    and (y.imported_until is null or d::date > y.imported_until))
$$;


--
-- Name: FUNCTION conta_primer_dia_abierto(p_company uuid, p_fecha date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_primer_dia_abierto(p_company uuid, p_fecha date) IS 'C04. El primer día, desde esa fecha, de un ejercicio abierto, fuera de lo traído y de un mes sin cerrar. NULL si no hay en 400 días.';


--
-- Name: conta_primer_dia_iva_abierto(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_primer_dia_iva_abierto(p_company uuid, p_fecha date) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_d date := p_fecha; v_p jsonb; i int := 0;
begin
  loop
    v_d := public.conta_primer_dia_abierto(p_company, v_d);
    if v_d is null then return null; end if;
    v_p := public.conta_iva_presentado(p_company, v_d);
    if v_p is null then return v_d; end if;
    v_d := (v_p->>'hasta')::date + 1;
    i := i + 1;
    if i > 24 then return null; end if;
  end loop;
end $$;


--
-- Name: conta_programa_anterior_apuntar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_programa_anterior_apuntar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.conta_programa_anterior_registro (company_id, account_id, accion, antes, despues, por)
    values (new.company_id, new.account_id, 'alta', null, new.programa || coalesce(': ' || new.otro_nombre, ''), new.puesto_por);
  elsif tg_op = 'UPDATE' then
    if new.programa is distinct from old.programa or new.otro_nombre is distinct from old.otro_nombre then
      insert into public.conta_programa_anterior_registro (company_id, account_id, accion, antes, despues, por)
      values (new.company_id, new.account_id, 'cambio', old.programa || coalesce(': ' || old.otro_nombre, ''),
              new.programa || coalesce(': ' || new.otro_nombre, ''), new.puesto_por);
    end if;
  else
    insert into public.conta_programa_anterior_registro (company_id, account_id, accion, antes, despues, por)
    values (old.company_id, old.account_id, 'baja', old.programa || coalesce(': ' || old.otro_nombre, ''), null, auth.uid());
  end if;
  return null;
end;
$$;


--
-- Name: conta_programa_anterior_guarda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_programa_anterior_guarda() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from public.company c where c.id = new.company_id and c.account_id = new.account_id) then
    raise exception 'conta_programa_anterior: la empresa % no es de la cuenta %.', new.company_id, new.account_id;
  end if;
  new.otro_nombre := nullif(btrim(coalesce(new.otro_nombre, '')), '');
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: conta_programa_anterior_poner(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_programa_anterior_poner(p_company uuid, p_programa text, p_otro text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cuenta uuid;
  v_prog text := lower(btrim(coalesce(p_programa, '')));
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'Esa empresa no existe.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not (v_cuenta = any (public.current_user_account_ids())) then
    raise exception 'Esa empresa no es de tu cuenta.' using errcode = '42501';
  end if;
  insert into public.conta_programa_anterior (company_id, account_id, programa, otro_nombre, puesto_por)
  values (p_company, v_cuenta, v_prog, case when v_prog = 'otro' then p_otro end, auth.uid())
  on conflict (company_id) do update
    set programa = excluded.programa, otro_nombre = excluded.otro_nombre, puesto_por = excluded.puesto_por;
  return jsonb_build_object('empresa', p_company, 'programa', v_prog, 'otro', case when v_prog = 'otro' then nullif(btrim(p_otro), '') end);
end;
$$;


--
-- Name: conta_proponer_dias(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_proponer_dias(p_company uuid, p_ahora timestamp with time zone DEFAULT now(), p_quien text DEFAULT 'Folvy (cierre del día)'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid; v_hasta date; y record; d record; v_p jsonb; v_r jsonb; v_res text; v_porque text; v_entry uuid;
  v_u jsonb; v_ures text; v_nuevo boolean; v_porques text[]; v_canal text; v_asientos int := 0; v_dia_asientos int;
  v_n jsonb := jsonb_build_object('propuestos', 0, 'ya_estaban', 0, 'descartados', 0, 'sin_propuesta', 0, 'fallos', 0);
  v_fallos text[] := '{}'; v_preguntar text[] := '{}';
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'Proponer: la empresa % no existe.', p_company; end if;
  v_hasta := public.conta_ultimo_dia_cerrado(p_company, p_ahora);

  for y in select f.* from public.fiscal_year f where f.company_id = p_company and f.status = 'open' and f.starts_on <= v_hasta order by f.starts_on loop
    if y.imported_until is null
       and exists (select 1 from public.sale s where s.account_id = v_cuenta and s.sold_at < (y.starts_on::timestamp at time zone 'Europe/Madrid'))
       and not exists (select 1 from public.journal_entry e where e.company_id = p_company and e.fiscal_year_id = y.id) then
      v_preguntar := v_preguntar || y.code::text;
      continue;
    end if;
    for d in
      select x.location_id, x.dia from public.conta_dias_por_asentar(p_company, greatest(y.starts_on, coalesce(y.imported_until + 1, y.starts_on)), least(v_hasta, y.ends_on)) x
       where not exists (select 1 from public.fiscal_period_lock k where k.company_id = p_company and k.month = date_trunc('month', x.dia)::date and k.reopened_at is null)
       order by x.dia, x.location_id
    loop
      v_entry := null; v_porque := null; v_dia_asientos := 0;
      begin
        v_nuevo := exists (select 1 from public.conta_ventas_canal v where v.company_id = p_company);
        if not v_nuevo then
          -- La regla de antes: el día entero en un asiento.
          v_p := public.conta_propuesta_ventas_dia(p_company, d.location_id, d.dia);
          if v_p is null then
            raise exception 'la propuesta del día ha salido vacía (ni asiento ni porqué)';
          elsif v_p ? 'sin_propuesta' then
            v_res := 'sin_propuesta'; v_porque := v_p->>'sin_propuesta';
          else
            v_r := public._journal_entry_proponer(p_company, v_p->'entrada', v_p->'lineas', v_p->'resumen', p_quien, null);
            v_res := case when (v_r->>'descartada')::boolean then 'descartado' when (v_r->>'existente')::boolean then 'ya_estaba' else 'propuesto' end;
            v_entry := nullif(v_r->>'id', '')::uuid;
          end if;
        else
          -- C04b R5: una propuesta por unidad. En el registro del día queda lo
          -- peor que pasó (sin propuesta > propuesto > ya estaba > descartado;
          -- un fallo salta al «exception» de abajo) y el porqué de cada unidad
          -- que no se propuso.
          v_res := null; v_porques := '{}';
          v_p := public.conta_propuestas_ventas_dia(p_company, d.location_id, d.dia);
          if v_p is null or jsonb_array_length(v_p) = 0 then
            raise exception 'el día no tiene ninguna unidad que proponer (ni asiento ni porqué)';
          end if;
          for v_u in select * from jsonb_array_elements(v_p) loop
            v_canal := coalesce((select ch.name from public.sales_channel ch where ch.id = nullif(v_u->>'channel_id', '')::uuid and ch.account_id = v_cuenta), 'sin canal')
                       || coalesce(' · ' || (select b.name from public.brand b where b.id = nullif(v_u->>'brand_id', '')::uuid and b.account_id = v_cuenta), '');
            if v_u->'propuesta' is null or jsonb_typeof(v_u->'propuesta') <> 'object' then
              raise exception '%: la propuesta ha salido vacía (ni asiento ni porqué)', v_canal;
            elsif v_u->'propuesta' ? 'sin_propuesta' then
              v_ures := 'sin_propuesta'; v_porques := v_porques || (v_canal || ': ' || (v_u->'propuesta'->>'sin_propuesta'));
            else
              v_r := public._journal_entry_proponer(p_company, v_u->'propuesta'->'entrada', v_u->'propuesta'->'lineas', v_u->'propuesta'->'resumen', p_quien, null);
              v_ures := case when (v_r->>'descartada')::boolean then 'descartado' when (v_r->>'existente')::boolean then 'ya_estaba' else 'propuesto' end;
              if v_ures = 'propuesto' then
                v_dia_asientos := v_dia_asientos + 1;
                if v_entry is null then v_entry := nullif(v_r->>'id', '')::uuid; end if;
              end if;
            end if;
            v_res := case when v_res is null then v_ures
                          when 'sin_propuesta' in (v_res, v_ures) then 'sin_propuesta'
                          when 'propuesto' in (v_res, v_ures) then 'propuesto'
                          when 'ya_estaba' in (v_res, v_ures) then 'ya_estaba'
                          else 'descartado' end;
          end loop;
          v_porque := nullif(array_to_string(v_porques, ' · '), '');
        end if;
      exception when others then
        v_res := 'fallo'; v_porque := format('%s (%s)', sqlerrm, sqlstate);
        v_fallos := v_fallos || format('%s %s: %s', d.dia, d.location_id, sqlerrm);
      end;
      -- Lo de un día que falla se deshace entero: sus asientos no cuentan.
      if v_res <> 'fallo' then v_asientos := v_asientos + v_dia_asientos; end if;
      insert into public.sales_day_proposal_log as g (account_id, company_id, location_id, sales_day, result, reason, entry_id)
      values (v_cuenta, p_company, d.location_id, d.dia, v_res, v_porque, v_entry)
      on conflict (company_id, location_id, sales_day) do update
        set result = excluded.result, reason = excluded.reason, entry_id = excluded.entry_id, attempts = g.attempts + 1, last_at = now();
      v_n := jsonb_set(v_n, array[case v_res when 'propuesto' then 'propuestos' when 'ya_estaba' then 'ya_estaban' when 'descartado' then 'descartados'
                                              when 'sin_propuesta' then 'sin_propuesta' else 'fallos' end],
                       to_jsonb((v_n->>case v_res when 'propuesto' then 'propuestos' when 'ya_estaba' then 'ya_estaban' when 'descartado' then 'descartados'
                                                  when 'sin_propuesta' then 'sin_propuesta' else 'fallos' end)::int + 1));
    end loop;
  end loop;
  -- C04b R5: los contadores son de días; asientos_por_unidad, de asientos (un día da varios).
  return v_n || jsonb_build_object('company_id', p_company, 'hasta', v_hasta, 'errores', to_jsonb(v_fallos), 'preguntar_ejercicio', to_jsonb(v_preguntar),
                                   'asientos_por_unidad', v_asientos);
end $$;


--
-- Name: FUNCTION conta_proponer_dias(p_company uuid, p_ahora timestamp with time zone, p_quien text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_proponer_dias(p_company uuid, p_ahora timestamp with time zone, p_quien text) IS 'Cierre del día 2 + C04b R5: propone las ventas de los días cerrados y abiertos que no tienen asiento vivo (por unidad: plataforma, o plataforma y marca, si la empresa usa la regla por plataforma), y apunta en sales_day_proposal_log lo que pasó con cada día y local.';


--
-- Name: conta_proponer_nominas(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_proponer_nominas(p_company uuid, p_desde date, p_hasta date, p_quien text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; r record; x jsonb; v_res jsonb;
        v_prop int := 0; v_ya int := 0; v_desc int := 0; v_sin jsonb := '[]'::jsonb;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  -- Una persona, solo si administra o encarga la cuenta; desde un disparador propone Sumied.
  if auth.uid() is not null and pg_trigger_depth() = 0 and not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'Solo un administrador o un encargado de la cuenta propone asientos.' using errcode = '42501';
  end if;
  for r in select ps.id from public.payroll_summary ps
            where ps.company_id = p_company and ps.account_id = v_cuenta and ps.entry_id is null
              and ps.period_month >= date_trunc('month', p_desde)::date and ps.period_month <= p_hasta
            order by ps.period_month desc loop
    x := public.conta_propuesta_nomina(r.id);
    if x ? 'sin_propuesta' then
      perform public._conta_no_propuesta(p_company, 'payroll', r.id::text, x->>'que', x->>'sin_propuesta', 'Contabilidad › Asientos');
      v_sin := v_sin || jsonb_build_array(jsonb_build_object('que', x->>'que', 'porque', x->>'sin_propuesta'));
      continue;
    end if;
    if not public.conta_dia_abierto(p_company, (x->'propuesta'->'entrada'->>'fecha')::date) then continue; end if;
    v_res := public._conta_proponer(p_company, x->'propuesta', p_quien);
    if (v_res->>'descartada')::boolean then v_desc := v_desc + 1;
    elsif (v_res->>'existente')::boolean then v_ya := v_ya + 1;
    else v_prop := v_prop + 1; end if;
  end loop;
  return jsonb_build_object('propuestas', v_prop, 'yaEstaban', v_ya, 'descartadas', v_desc, 'sinPropuesta', v_sin);
end $$;


--
-- Name: FUNCTION conta_proponer_nominas(p_company uuid, p_desde date, p_hasta date, p_quien text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_proponer_nominas(p_company uuid, p_desde date, p_hasta date, p_quien text) IS 'S01 · PR 3: propone las nóminas de un rango (navegador, pasada de noche, disparador); lo que no puede, a conta_propuesta_pendiente. No valida.';


--
-- Name: conta_propuesta_nomina(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_propuesta_nomina(p_payroll uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with n as (
    select ps.*, (date_trunc('month', ps.period_month) + interval '1 month - 1 day')::date as fin,
           to_char(ps.period_month, 'MM/YYYY') as mes
      from public.payroll_summary ps where ps.id = p_payroll
  ), c as (
    select n.*,
      coalesce((select ca.code from public.company_account ca where ca.company_id = n.company_id and ca.kind = 'template' and ca.status is distinct from 'cerrada' and ca.template_code = '640' order by ca.code limit 1), '64000000') as c_sueldos,
      coalesce((select ca.code from public.company_account ca where ca.company_id = n.company_id and ca.kind = 'template' and ca.status is distinct from 'cerrada' and ca.template_code = '642' order by ca.code limit 1), '64200000') as c_ss_empresa,
      coalesce((select ca.code from public.company_account ca where ca.company_id = n.company_id and ca.kind = 'template' and ca.status is distinct from 'cerrada' and ca.template_code = '476' order by ca.code limit 1), '47600000') as c_ss_acreedora,
      coalesce((select ca.code from public.company_account ca where ca.company_id = n.company_id and ca.kind = 'template' and ca.status is distinct from 'cerrada' and ca.template_code = '4751' order by ca.code limit 1), '47510000') as c_irpf,
      coalesce((select ca.code from public.company_account ca where ca.company_id = n.company_id and ca.kind = 'template' and ca.status is distinct from 'cerrada' and ca.template_code = '465' order by ca.code limit 1), '46500000') as c_remuneraciones,
      -- Por su clave (code = 'trabajo', modelo 111), vigente el último día del mes,
      -- nunca «el primero»: la de la empresa antes que la de serie (1103), y la
      -- más reciente si hay dos versiones.
      (select w.id from public.withholding_rate w where w.filed_in = '111' and w.code = 'trabajo'
          and (w.account_id is null or w.account_id = n.account_id) and (w.company_id is null or w.company_id = n.company_id)
          and w.valid_from <= n.fin and (w.valid_to is null or w.valid_to >= n.fin)
        order by w.company_id nulls last, w.account_id nulls last, w.valid_from desc, w.id limit 1) as ret
      from n
  ), l as (
    select c.*, jsonb_build_array(
        jsonb_build_object('cuenta', c_sueldos, 'debe', gross, 'haber', 0),
        jsonb_build_object('cuenta', c_ss_empresa, 'debe', employer_ss, 'haber', 0),
        jsonb_build_object('cuenta', c_ss_acreedora, 'debe', 0, 'haber', round(employer_ss + employee_ss, 2)),
        jsonb_build_object('cuenta', c_irpf, 'debe', 0, 'haber', irpf, 'retencion', jsonb_build_object('tipo_id', ret, 'base', gross, 'modelo', '111')),
        jsonb_build_object('cuenta', c_remuneraciones, 'debe', 0, 'haber', net)) as crudas
      from c
  )
  select case
    when not exists (select 1 from n) then jsonb_build_object('sin_propuesta', 'La nómina no existe.', 'que', 'Nóminas')
    when round(l.gross * 100) <> round(l.employee_ss * 100) + round(l.irpf * 100) + round(l.other_deductions * 100) + round(l.net * 100) then
      jsonb_build_object('que', 'Nóminas de ' || l.mes,
        'sin_propuesta', format('Bruto %s ≠ SS del trabajador + IRPF + otras + líquido: revisa el resumen de la gestoría.', public.conta_euros_exactos(l.gross)))
    when round(l.other_deductions * 100) <> 0 then
      jsonb_build_object('que', 'Nóminas de ' || l.mes, 'sin_propuesta', 'El resumen trae otras deducciones (embargos, anticipos): dime a qué cuenta van antes de proponerla.')
    when round(l.irpf * 100) <> 0 and l.ret is null then
      jsonb_build_object('que', 'Nóminas de ' || l.mes, 'sin_propuesta', 'Falta el tipo de retención de trabajo en Tablas › Retenciones.')
    else jsonb_build_object('que', 'Nóminas de ' || l.mes, 'propuesta', jsonb_build_object(
      'entrada', jsonb_build_object(
        'series', 9, 'fecha', l.fin, 'concepto', 'Nóminas de ' || l.mes, 'source_type', 'payroll', 'source_id', l.id,
        'confianza', case when l.location_id is not null then 'seguro' else 'probable' end,
        'porque', 'El resumen de la gestoría: sueldos y SS de la empresa como gasto; SS, IRPF y líquido como lo que se debe.',
        'razones', jsonb_build_array(jsonb_build_object('decision', format('IRPF %s a la 4751', public.conta_euros_exactos(l.irpf)),
                                                        'porque', 'retenciones de trabajo: van al 111 del trimestre')),
        'party_id', null, 'documento', null),
      'lineas', (select coalesce(jsonb_agg(x.v || jsonb_build_object('concepto', null, 'local_id', l.location_id, 'comun', l.location_id is null,
                                                                    'marca_id', null, 'tercero_id', null, 'documento', null, 'iva', null)
                                           || case when x.v ? 'retencion' then '{}'::jsonb else jsonb_build_object('retencion', null) end
                                           order by x.o), '[]'::jsonb)
                   from jsonb_array_elements(l.crudas) with ordinality x(v, o)
                  where round(((x.v->>'debe')::numeric + (x.v->>'haber')::numeric) * 100) > 0
                    and not (x.v ? 'retencion' and round(l.irpf * 100) = 0))))
    end
  from (select 1) uno left join l on true
$$;


--
-- Name: FUNCTION conta_propuesta_nomina(p_payroll uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_propuesta_nomina(p_payroll uuid) IS 'S01 · PR 3: la regla de una nómina (nomina() del navegador), en SQL puro: {entrada, lineas} como aJson, o {sin_propuesta}. Solo lee.';


--
-- Name: conta_propuesta_ventas_dia(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_propuesta_ventas_dia(p_company uuid, p_location uuid, p_dia date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with
emp as (
  select c.id, c.account_id, t.sales_tax_rate_code from public.company c
    left join public.company_tax_profile t on t.company_id = c.id
   where c.id = p_company
),
tipo as (
  select r.id, r.rate, public.conta_numero_texto(r.rate) as txt from public.tax_rate r, emp
   where r.code = emp.sales_tax_rate_code and r.tax_system = 'iva' and r.valid_to is null
     and (r.is_system or r.account_id = emp.account_id)
   order by r.is_system, r.id limit 1
),
hoja as (
  select a.template_code, min(a.code) as code from public.company_account a
   where a.company_id = p_company and a.kind = 'template' and a.status is distinct from 'cerrada' and a.template_code in ('700', '708')
   group by 1
),
cta as (
  select (select code from hoja where template_code = '700') as ventas,
         coalesce((select code from hoja where template_code = '708'), (select code from hoja where template_code = '700')) as devoluciones,
         (select a.code from public.company_account_link k join public.company_account a on a.id = k.company_account_id, tipo
           where k.company_id = p_company and k.entity = 'tax_rate' and k.entity_id = tipo.id::text and k.role = 'repercutido'
           order by a.code limit 1) as iva477
),
canal as (
  select ch.id, ch.name,
         (select a.code from public.party_role pr
            join public.company_account_link k on k.company_id = p_company and k.entity = 'customer' and k.entity_id = pr.party_id::text and k.role = 'principal'
            join public.company_account a on a.id = k.company_account_id
           where pr.account_id = ch.account_id and pr.role = 'platform' and pr.channel_id = ch.id
           order by pr.party_id, a.code limit 1) as cuenta
    from public.sales_channel ch, emp where ch.account_id = emp.account_id
),
loc as (select coalesce((select l.name from public.locations l, emp where l.id = p_location and l.account_id = emp.account_id), 'local') as nombre),
ped as (
  select x.* from public.conta_pedidos_del_dia(p_company, p_location, p_dia) with ordinality as x(id, codigo, canal_id, marca_id, propia, estado, total, base, cuota, tipos, ord)
),
fila as (  -- los tickets de tus marcas: base y cuota del pedido si cuadran; si no, del total al tipo
  select p.*,
         (p.base is not null and p.cuota is not null and round(p.base * 100) + round(p.cuota * 100) = round(p.total * 100)) as trae,
         exists (select 1 from unnest(p.tipos) t where t <> tipo.rate) as otro,
         round(p.total * 100) as c_total,
         case when p.base is not null and p.cuota is not null and round(p.base * 100) + round(p.cuota * 100) = round(p.total * 100)
              then round(p.base * 100)
              else sign(p.total) * round(abs(round(p.total * 100)) * 100 / (100 + tipo.rate)) end as c_base
    from ped p, tipo where p.propia and p.estado = 'closed'
),
fila2 as (
  select f.*, case when f.trae then round(f.cuota * 100) else f.c_total - f.c_base end as c_cuota from fila f
),
dev as (
  select o.*, round(o.importe * 100) as c_imp,
         sign(o.importe) * round(abs(round(o.importe * 100)) * 100 / (100 + tipo.rate)) as c_base
    from public.conta_devoluciones_del_dia(p_company, p_location, p_dia) with ordinality as o(pedido_id, codigo, canal_id, marca_id, propia, importe, ord), tipo
   where o.propia
),
dev2 as (select d.*, d.c_imp - d.c_base as c_cuota, coalesce(d.codigo, d.pedido_id::text) as ref from dev d),
tot as (
  select count(*) as n, coalesce(sum(c_total), 0) as c_total, coalesce(sum(c_base), 0) as c_base, coalesce(sum(c_cuota), 0) as c_cuota,
         bool_or(not trae) as calculada, count(*) filter (where otro) as otro
    from fila2
),
por_canal as (select canal_id, sum(c_total) as c, min(ord) as o from fila2 group by canal_id),
por_marca as (select marca_id, sum(c_base) as c, min(ord) as o from fila2 group by marca_id),
cuentas_cobro as (
  select pc.canal_id, pc.o, (select cuenta from canal where canal.id = pc.canal_id) as cuenta,
         case when pc.canal_id is null then 'sin canal' else coalesce((select name from canal where canal.id = pc.canal_id), 'un canal') end as nombre
    from por_canal pc
),
sin_cuenta as (  -- canales de lo cobrado y de lo devuelto sin su 430, en orden de aparición y sin repetir
  select nombre, min(o) as o from (
    select nombre, o from cuentas_cobro where cuenta is null
    union all
    select case when d.canal_id is null then 'sin canal' else coalesce((select name from canal where canal.id = d.canal_id), 'un canal') end,
           100000000 + d.ord
      from dev2 d where d.canal_id is null or (select cuenta from canal where canal.id = d.canal_id) is null
  ) z group by nombre
),
cnt as (
  select (select count(*) from ped where not propia and estado = 'closed') as cedidas,
         (select coalesce(sum(round(total * 100)), 0) from ped where not propia and estado = 'closed') as c_cedidas,
         (select count(*) from ped where estado = 'cancelled') as cancelados,
         (select count(*) from ped where estado = 'open' and propia) as abiertos,
         (select count(*) from dev2) as devs,
         (select coalesce(sum(c_imp), 0) from dev2) as c_devs
),
lineas as (
  select jsonb_agg(l.j order by l.k1, l.k2, l.k3) as j from (
    select 1 as k1, cc.o as k2, 0 as k3, jsonb_build_object('cuenta', cc.cuenta, 'debe', round(pc.c / 100, 2), 'haber', 0, 'concepto', 'Cobra ' || cc.nombre,
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', null, 'iva', null, 'retencion', null) as j
      from cuentas_cobro cc join por_canal pc on pc.canal_id is not distinct from cc.canal_id
    union all
    select 2, pm.o, 0, jsonb_build_object('cuenta', cta.ventas, 'debe', 0, 'haber', round(pm.c / 100, 2), 'concepto', 'Ventas de tus marcas',
             'local_id', p_location, 'comun', false, 'marca_id', pm.marca_id, 'tercero_id', null, 'documento', null, 'iva', null, 'retencion', null)
      from por_marca pm, cta
    union all
    select 3, 0, 0, jsonb_build_object('cuenta', cta.iva477, 'debe', 0, 'haber', round(tot.c_cuota / 100, 2), 'concepto', 'IVA repercutido ' || tipo.txt || ' %',
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', null,
             'iva', jsonb_build_object('tipo_id', tipo.id, 'base', round(tot.c_base / 100, 2), 'libro', 'issued', 'deducible', null, 'facturas', tot.n), 'retencion', null)
      from tot, cta, tipo where tot.n > 0
    union all
    select 4, d.ord, 1, jsonb_build_object('cuenta', cta.devoluciones, 'debe', round(d.c_base / 100, 2), 'haber', 0, 'concepto', 'Devolución del pedido ' || coalesce(d.ref, 'sin código'),
             'local_id', p_location, 'comun', false, 'marca_id', d.marca_id, 'tercero_id', null, 'documento', d.ref, 'iva', null, 'retencion', null)
      from dev2 d, cta
    union all
    select 4, d.ord, 2, jsonb_build_object('cuenta', cta.iva477, 'debe', round(d.c_cuota / 100, 2), 'haber', 0, 'concepto', trim('IVA de la devolución ' || coalesce(d.ref, '')),
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', d.ref,
             'iva', jsonb_build_object('tipo_id', tipo.id, 'base', round(d.c_base / 100, 2), 'libro', 'issued', 'deducible', null, 'facturas', 1), 'retencion', null)
      from dev2 d, cta, tipo
    union all
    select 4, d.ord, 3, jsonb_build_object('cuenta', (select cuenta from canal where canal.id = d.canal_id), 'debe', 0, 'haber', round(d.c_imp / 100, 2),
             'concepto', 'Devuelve ' || case when d.canal_id is null then 'sin canal' else coalesce((select name from canal where canal.id = d.canal_id), 'un canal') end,
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', d.ref, 'iva', null, 'retencion', null)
      from dev2 d
  ) l
),
razones as (
  select jsonb_agg(r.j order by r.k) as j from (
    select 1 as k, jsonb_build_object('decision', tot.n || ' ticket' || case when tot.n = 1 then '' else 's' end || ' de tus marcas, ' || public.conta_euros_exactos(round(tot.c_total / 100, 2)),
             'porque', 'una factura simplificada por pedido, anotadas juntas en un asiento resumen del día con base y cuota por tipo',
             'cita', 'Código de Comercio, art. 28.2; RD 1624/1992 (Reglamento del IVA), art. 63.4') as j from tot
    union all
    select 2, jsonb_build_object('decision', 'IVA al ' || tipo.txt || ' %', 'porque', 'reparto de comida = servicio de restauración: criterio de tu empresa',
             'cita', 'Ley 37/1992, art. 91.Uno.2.2.º') from tipo
    union all
    select 3, jsonb_build_object('decision', cnt.devs || ' devolución' || case when cnt.devs = 1 then '' else 'es' end || ' de ' || public.conta_euros_exactos(round(cnt.c_devs / 100, 2)),
             'porque', 'la plataforma devolvió al cliente después de la venta: menos venta y menos IVA, contra lo que cobra la plataforma, el día en que se produce',
             'cita', 'Ley 37/1992, art. 80.Dos') from cnt where cnt.devs > 0
    union all
    select 4, jsonb_build_object('decision', 'Base calculada',
             'porque', 'algún pedido no trae la base imponible: la calculo del total al ' || tipo.txt || ' % (el tipo de tus ventas); no la invento, la deduzco y lo digo')
      from tot, tipo where tot.calculada
    union all
    select 5, jsonb_build_object('decision', 'Fuera: ' || cnt.cedidas || ' pedidos de marcas cedidas (' || public.conta_euros_exactos(round(cnt.c_cedidas / 100, 2)) || ')',
             'porque', 'son ventas del socio y su IVA es del socio: entran solo en su liquidación mensual, que comparas con estos tickets',
             'cita', 'Ley 37/1992, art. 11.Dos.15.º') from cnt where cnt.cedidas > 0
    union all
    select 6, jsonb_build_object('decision', 'Fuera: ' || cnt.cancelados || ' cancelado' || case when cnt.cancelados = 1 then '' else 's' end,
             'porque', 'cancelado antes de entregar no es venta') from cnt where cnt.cancelados > 0
    union all  -- los avisos van detrás, como «Mira esto» (propuestasLibroService.ts, aJson)
    select 7, jsonb_build_object('decision', 'Mira esto',
             'porque', tot.otro || ' pedido' || case when tot.otro = 1 then ' trae' else 's traen' end || ' en sus líneas un tipo distinto del ' || tipo.txt || ' %: mira cuáles antes de validar.')
      from tot, tipo where tot.otro > 0
  ) r
),
resumen as (
  select jsonb_build_object(
    'location_id', p_location, 'sales_day', p_dia, 'tickets_count', tot.n, 'total', round(tot.c_total / 100, 2),
    'by_rate', jsonb_build_array(jsonb_build_object('tax_rate_id', tipo.id, 'rate', public.conta_numero_texto(tipo.rate)::numeric, 'base', round(tot.c_base / 100, 2), 'cuota', round(tot.c_cuota / 100, 2), 'calculated', coalesce(tot.calculada, false))),
    'by_channel', coalesce((select jsonb_agg(jsonb_build_object('channel_id', canal_id, 'total', round(c / 100, 2)) order by o) from por_canal), '[]'),
    'by_brand', coalesce((select jsonb_agg(jsonb_build_object('brand_id', marca_id, 'base', round(c / 100, 2)) order by o) from por_marca), '[]'),
    'detail_hash', encode(sha256(convert_to(
        coalesce((select string_agg(id::text, '|' order by id::text collate "C") from fila2), '') || '#' || tot.c_total::bigint::text, 'UTF8')), 'hex'),
    'sale_ids', coalesce((select jsonb_agg(id order by id::text collate "C") from fila2), '[]'),
    'base_calculated', coalesce(tot.calculada, false)) as j
  from tot left join tipo on true   -- sin tipo de ventas no hay propuesta, pero sí respuesta (abajo)
)
select case
  when (select id from tipo) is null or cta.iva477 is null or cta.ventas is null then
    jsonb_build_object('sin_propuesta', 'Falta el IVA de tus ventas (Tu empresa) o su 477, o la 700 en el plan.')
  when tot.n = 0 and cnt.devs = 0 then
    jsonb_build_object('sin_propuesta', case when cnt.cedidas > 0 then 'Ese día solo hubo ventas de marcas cedidas: van en la liquidación del socio.' else 'Ese día no hubo ventas de tus marcas.' end)
  when cnt.abiertos > 0 then
    jsonb_build_object('sin_propuesta', 'El cierre del día aún no ha pasado por este día: ' || cnt.abiertos || ' pedido' || case when cnt.abiertos = 1 then '' else 's' end
      || ' de tus marcas ' || case when cnt.abiertos = 1 then 'sigue abierto' else 'siguen abiertos' end || '. Pasa cada hora a los 7 minutos; vuelve a proponer después.')
  when exists (select 1 from sin_cuenta) then
    jsonb_build_object('sin_propuesta', 'No sé a qué cuenta va lo que cobra ' || (select string_agg(nombre, ', ' order by o) from sin_cuenta)
      || ': enlaza su 430 en su ficha (Clientes y proveedores › Plataformas).')
  when tot.n > 0 and abs(tot.c_cuota - sign(tot.c_base) * round(abs(tot.c_base * (select rate from tipo)) / 100)) > floor(0.55 * tot.n + 0.5) then
    jsonb_build_object('sin_propuesta', 'La cuota de los tickets (' || public.conta_euros_exactos(round(tot.c_cuota / 100, 2)) || ') se aleja de la base × '
      || (select txt from tipo) || ' % más de medio céntimo por ticket: hay pedidos con otro tipo.')
  else jsonb_build_object(
    'entrada', jsonb_build_object(
      'series', 1, 'fecha', p_dia, 'concepto', 'Ventas del día · ' || loc.nombre, 'source_type', 'sales_day', 'source_id', null,
      'confianza', case when tot.otro > 0 then 'duda' when tot.calculada then 'probable' else 'seguro' end,
      'porque', tot.n || ' tickets de tus marcas cuadran con lo que cobran las plataformas, al céntimo'
                || case when tot.calculada then '; base calculada al ' || (select txt from tipo) || ' %' else '' end || '.',
      'razones', razones.j, 'party_id', null, 'documento', null),
    'lineas', lineas.j,
    'resumen', resumen.j)
  end
from tot, cnt, cta, loc, lineas, razones, resumen
$$;


--
-- Name: FUNCTION conta_propuesta_ventas_dia(p_company uuid, p_location uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_propuesta_ventas_dia(p_company uuid, p_location uuid, p_dia date) IS 'Cierre del día 2: la propuesta del asiento de ventas de un día y un local (espejo de ventasDelDia del núcleo), o {sin_propuesta: por qué}. Solo lee.';


--
-- Name: conta_propuesta_ventas_unidad(uuid, uuid, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_propuesta_ventas_unidad(p_company uuid, p_location uuid, p_dia date, p_canal uuid, p_marca uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with
emp as (
  select c.id, c.account_id, t.sales_tax_rate_code from public.company c
    left join public.company_tax_profile t on t.company_id = c.id
   where c.id = p_company
),
tipo as (
  select r.id, r.rate, public.conta_numero_texto(r.rate) as txt from public.tax_rate r, emp
   where r.code = emp.sales_tax_rate_code and r.tax_system = 'iva' and r.valid_to is null
     and (r.is_system or r.account_id = emp.account_id)
   order by r.is_system, r.id limit 1
),
hoja as (
  select a.template_code, min(a.code) as code from public.company_account a
   where a.company_id = p_company and a.kind = 'template' and a.status is distinct from 'cerrada' and a.template_code in ('700', '708')
   group by 1
),
cta as (
  select (select code from hoja where template_code = '700') as ventas,
         coalesce((select code from hoja where template_code = '708'), (select code from hoja where template_code = '700')) as devoluciones,
         (select a.code from public.company_account_link k join public.company_account a on a.id = k.company_account_id, tipo
           where k.company_id = p_company and k.entity = 'tax_rate' and k.entity_id = tipo.id::text and k.role = 'repercutido'
           order by a.code limit 1) as iva477
),
marca_cta as (
  select m.brand_id, m.papel, a.code from public.conta_ventas_marca m join public.company_account a on a.id = m.company_account_id
   where m.company_id = p_company and a.status is distinct from 'cerrada'
),
canal as (
  select ch.id, ch.name,
         (select a.code from public.party_role pr
            join public.company_account_link k on k.company_id = p_company and k.entity = 'customer' and k.entity_id = pr.party_id::text and k.role = 'principal'
            join public.company_account a on a.id = k.company_account_id
           where pr.account_id = ch.account_id and pr.role = 'platform' and pr.channel_id = ch.id
           order by pr.party_id, a.code limit 1) as cuenta,
         (select a.code from public.conta_ventas_canal_cuenta v join public.company_account a on a.id = v.company_account_id and a.company_id = v.company_id
           where v.company_id = p_company and v.channel_id = ch.id and v.papel = 'promociones' and a.status is distinct from 'cerrada') as promo,
         (select a.code from public.conta_ventas_canal_cuenta v join public.company_account a on a.id = v.company_account_id and a.company_id = v.company_id
           where v.company_id = p_company and v.channel_id = ch.id and v.papel = 'envios' and a.status is distinct from 'cerrada') as envios
    from public.sales_channel ch, emp where ch.account_id = emp.account_id
),
cta_canal as (select (select promo from canal where id = p_canal) as promo, (select envios from canal where id = p_canal) as envios),
nombre_canal as (select case when p_canal is null then 'sin canal' else coalesce((select name from canal where id = p_canal), 'un canal') end as n),
marca_nombre as (select b.id, b.name from public.brand b, emp where b.account_id = emp.account_id),
loc as (select coalesce((select l.name from public.locations l, emp where l.id = p_location and l.account_id = emp.account_id), 'local') as nombre),
ped as (
  select x.* from public.conta_pedidos_del_dia(p_company, p_location, p_dia) with ordinality as x(id, codigo, canal_id, marca_id, propia, estado, total, base, cuota, tipos, ord)
   where x.canal_id is not distinct from p_canal and (p_marca is null or x.marca_id = p_marca)
),
-- C06b (16/10): el descuento, el envío y quién repartió cada pedido (conta_cargos_de_pedidos).
carg as (
  select c.* from emp, public.conta_cargos_de_pedidos(emp.account_id, (select coalesce(array_agg(id), '{}') from ped where propia and estado = 'closed')) c
),
fila0 as (
  select p.*, round(coalesce(c.descuento, 0) * 100) as c_desc, round(coalesce(c.envio, 0) * 100) as c_env,
         coalesce(c.clase, 'ninguno') as clase, c.por_que,
         -- Un envío que la plataforma no paga (aclarado así) sale de la venta y del cobro.
         round(p.total * 100) - case when c.clase = 'fuera' then round(c.envio * 100) else 0 end as c_total
    from ped p left join carg c on c.id = p.id
   where p.propia and p.estado = 'closed'
),
fila as (
  select p.*,
         (p.clase <> 'fuera' and p.base is not null and p.cuota is not null and round(p.base * 100) + round(p.cuota * 100) = round(p.total * 100)) as trae,
         exists (select 1 from unnest(p.tipos) t where t <> tipo.rate) as otro,
         case when p.clase <> 'fuera' and p.base is not null and p.cuota is not null and round(p.base * 100) + round(p.cuota * 100) = round(p.total * 100)
              then round(p.base * 100)
              else sign(p.c_total) * round(abs(p.c_total) * 100 / (100 + tipo.rate)) end as c_base
    from fila0 p, tipo
),
fila2 as (
  select f.*, case when f.trae then round(f.cuota * 100) else f.c_total - f.c_base end as c_cuota,
         -- La promoción en base, al tipo de la venta; el envío cobrado, igual. Sin su subcuenta, se quedan en la venta (y se avisa).
         case when cc.promo is not null and f.c_desc > 0 then round(f.c_desc * 100 / (100 + tipo.rate)) else 0 end as c_promo,
         case when cc.envios is not null and f.clase = 'cobrado' and f.c_env > 0 then round(f.c_env * 100 / (100 + tipo.rate)) else 0 end as c_envio
    from fila f, tipo, cta_canal cc
),
dev as (
  select o.*, round(o.importe * 100) as c_imp,
         sign(o.importe) * round(abs(round(o.importe * 100)) * 100 / (100 + tipo.rate)) as c_base
    from public.conta_devoluciones_del_dia(p_company, p_location, p_dia) with ordinality as o(pedido_id, codigo, canal_id, marca_id, propia, importe, ord), tipo
   where o.propia and o.canal_id is not distinct from p_canal and (p_marca is null or o.marca_id = p_marca)
),
dev2 as (select d.*, d.c_imp - d.c_base as c_cuota, coalesce(d.codigo, d.pedido_id::text) as ref from dev d),
tot as (
  select count(*) as n, coalesce(sum(c_total), 0) as c_total, coalesce(sum(c_base), 0) as c_base, coalesce(sum(c_cuota), 0) as c_cuota,
         bool_or(not trae) as calculada, count(*) filter (where otro) as otro,
         coalesce(sum(c_promo), 0) as c_promo, count(*) filter (where c_promo > 0) as n_promo, coalesce(sum(c_desc) filter (where c_promo > 0), 0) as c_desc,
         count(*) filter (where c_desc > 0 and c_promo = 0) as n_promo_sin_cuenta,
         coalesce(sum(c_envio), 0) as c_envio, count(*) filter (where c_envio > 0) as n_envio, coalesce(sum(c_env) filter (where c_envio > 0), 0) as c_env,
         count(*) filter (where clase = 'cobrado' and c_env > 0 and c_envio = 0) as n_envio_sin_cuenta,
         count(*) filter (where clase = 'por_aclarar') as n_aclarar,
         count(*) filter (where clase = 'fuera') as n_fuera, coalesce(sum(c_env) filter (where clase = 'fuera'), 0) as c_fuera
    from fila2
),
-- La venta de cada marca, a precio de carta: lo pagado + su promoción − el envío cobrado.
por_marca as (select marca_id, sum(c_base + c_promo - c_envio) as c, min(ord) as o from fila2 group by marca_id),
sin_cuenta as (
  select nombre_canal.n as nombre from nombre_canal
   where ((select count(*) from fila2) > 0 or (select count(*) from dev2) > 0)
     and (p_canal is null or (select cuenta from canal where canal.id = p_canal) is null)
),
sin_subcuenta as (  -- marcas sin su 7000000x o su 7080000x, en orden de aparición y sin repetir
  select coalesce((select name from marca_nombre where id = z.marca_id), case when z.marca_id is null then 'sin marca' else 'una marca' end) as nombre, min(z.o) as o
    from (select pm.marca_id, pm.o from por_marca pm
           where pm.marca_id is null or not exists (select 1 from marca_cta mc where mc.brand_id = pm.marca_id and mc.papel = 'ventas')
          union all
          select d.marca_id, 100000000 + d.ord from dev2 d
           where d.marca_id is null or not exists (select 1 from marca_cta mc where mc.brand_id = d.marca_id and mc.papel = 'devoluciones')) z
   group by 1
),
cnt as (
  select (select count(*) from ped where not propia and estado = 'closed') as cedidas,
         (select coalesce(sum(round(total * 100)), 0) from ped where not propia and estado = 'closed') as c_cedidas,
         (select count(*) from ped where estado = 'cancelled') as cancelados,
         (select count(*) from ped where estado = 'open' and propia) as abiertos,
         (select count(*) from dev2) as devs,
         (select coalesce(sum(c_imp), 0) from dev2) as c_devs
),
lineas as (
  select jsonb_agg(l.j order by l.k1, l.k2, l.k3) as j from (
    select 1 as k1, 0 as k2, 0 as k3, jsonb_build_object('cuenta', (select cuenta from canal where canal.id = p_canal), 'debe', round(tot.c_total / 100, 2), 'haber', 0,
             'concepto', 'Cobra ' || nombre_canal.n,
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', null, 'iva', null, 'retencion', null) as j
      from tot, nombre_canal where tot.n > 0
    union all
    select 2, pm.o, 0, jsonb_build_object('cuenta', coalesce((select code from marca_cta mc where mc.brand_id = pm.marca_id and mc.papel = 'ventas'), cta.ventas),
             'debe', 0, 'haber', round(pm.c / 100, 2),
             'concepto', 'Ventas ' || coalesce((select name from marca_nombre where id = pm.marca_id), case when pm.marca_id is null then 'sin marca' else 'una marca' end),
             'local_id', p_location, 'comun', false, 'marca_id', pm.marca_id, 'tercero_id', null, 'documento', null, 'iva', null, 'retencion', null)
      from por_marca pm, cta
    union all
    select 2, -1, 0, jsonb_build_object('cuenta', cc.promo, 'debe', round(tot.c_promo / 100, 2), 'haber', 0,
             'concepto', 'Promociones ' || nombre_canal.n || ' · ' || tot.n_promo || ' pedido' || case when tot.n_promo = 1 then '' else 's' end,
             'local_id', p_location, 'comun', false, 'marca_id', p_marca, 'tercero_id', null, 'documento', null, 'iva', null, 'retencion', null)
      from tot, cta_canal cc, nombre_canal where tot.c_promo > 0
    union all
    select 2, 1000000000, 0, jsonb_build_object('cuenta', cc.envios, 'debe', 0, 'haber', round(tot.c_envio / 100, 2),
             'concepto', 'Envíos cobrados · ' || tot.n_envio || ' pedido' || case when tot.n_envio = 1 then '' else 's' end,
             'local_id', p_location, 'comun', false, 'marca_id', p_marca, 'tercero_id', null, 'documento', null, 'iva', null, 'retencion', null)
      from tot, cta_canal cc where tot.c_envio > 0
    union all
    select 3, 0, 0, jsonb_build_object('cuenta', cta.iva477, 'debe', 0, 'haber', round(tot.c_cuota / 100, 2), 'concepto', 'IVA repercutido ' || tipo.txt || ' %',
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', null,
             'iva', jsonb_build_object('tipo_id', tipo.id, 'base', round(tot.c_base / 100, 2), 'libro', 'issued', 'deducible', null, 'facturas', tot.n), 'retencion', null)
      from tot, cta, tipo where tot.n > 0
    union all
    select 4, d.ord, 1, jsonb_build_object('cuenta', coalesce((select code from marca_cta mc where mc.brand_id = d.marca_id and mc.papel = 'devoluciones'), cta.devoluciones),
             'debe', round(d.c_base / 100, 2), 'haber', 0,
             'concepto', 'Reembolso al cliente · ' || coalesce((select name from marca_nombre where id = d.marca_id), case when d.marca_id is null then 'sin marca' else 'una marca' end)
                         || ' · pedido ' || coalesce(d.ref, 'sin código'),
             'local_id', p_location, 'comun', false, 'marca_id', d.marca_id, 'tercero_id', null, 'documento', d.ref, 'iva', null, 'retencion', null)
      from dev2 d, cta
    union all
    select 4, d.ord, 2, jsonb_build_object('cuenta', cta.iva477, 'debe', round(d.c_cuota / 100, 2), 'haber', 0, 'concepto', trim('IVA del reembolso ' || coalesce(d.ref, '')),
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', d.ref,
             'iva', jsonb_build_object('tipo_id', tipo.id, 'base', round(d.c_base / 100, 2), 'libro', 'issued', 'deducible', null, 'facturas', 1), 'retencion', null)
      from dev2 d, cta, tipo
    union all
    select 4, d.ord, 3, jsonb_build_object('cuenta', (select cuenta from canal where canal.id = p_canal), 'debe', 0, 'haber', round(d.c_imp / 100, 2),
             'concepto', 'Devuelve ' || nombre_canal.n,
             'local_id', p_location, 'comun', false, 'marca_id', null, 'tercero_id', null, 'documento', d.ref, 'iva', null, 'retencion', null)
      from dev2 d, nombre_canal
  ) l
),
razones as (
  select jsonb_agg(r.j order by r.k) as j from (
    select 1 as k, jsonb_build_object('decision', tot.n || ' ticket' || case when tot.n = 1 then '' else 's' end || ' de tus marcas, ' || public.conta_euros_exactos(round(tot.c_total / 100, 2)),
             'porque', 'una factura simplificada por pedido, anotadas juntas en un asiento resumen del día con base y cuota por tipo',
             'cita', 'Código de Comercio, art. 28.2; RD 1624/1992 (Reglamento del IVA), art. 63.4') as j from tot
    union all
    select 2, jsonb_build_object('decision', 'IVA al ' || tipo.txt || ' %', 'porque', 'reparto de comida = servicio de restauración: criterio de tu empresa',
             'cita', 'Ley 37/1992, art. 91.Uno.2.2.º') from tipo
    union all
    select 2.1, jsonb_build_object('decision', 'Promociones: ' || tot.n_promo || ' pedido' || case when tot.n_promo = 1 then '' else 's' end
               || ', ' || public.conta_euros_exactos(round(tot.c_desc / 100, 2)) || ' con el IVA dentro',
             'porque', 'la venta va a precio de carta en su marca y la promoción, en su subcuenta (' || cc.promo || '), resta; el IVA va sobre lo que paga el cliente',
             'cita', 'Ley 37/1992, art. 78.Tres.2.º') from tot, cta_canal cc where tot.c_promo > 0
    union all
    select 2.2, jsonb_build_object('decision', 'Envíos cobrados: ' || tot.n_envio || ' pedido' || case when tot.n_envio = 1 then '' else 's' end
               || ', ' || public.conta_euros_exactos(round(tot.c_env / 100, 2)) || ' con el IVA dentro',
             'porque', 'lo repartimos nosotros: el envío es del restaurante y va a su subcuenta (' || cc.envios || '), con su local; forma parte de la base, al tipo de la venta',
             'cita', 'Ley 37/1992, art. 78.Dos.1.º') from tot, cta_canal cc where tot.c_envio > 0
    union all
    select 2.3, jsonb_build_object('decision', 'Fuera: el envío de ' || tot.n_fuera || ' pedido' || case when tot.n_fuera = 1 then '' else 's' end
               || ' (' || public.conta_euros_exactos(round(tot.c_fuera / 100, 2)) || ')',
             'porque', 'lo repartió la plataforma y su liquidación no lo paga: no es venta del restaurante ni lo cobra la plataforma para él') from tot where tot.n_fuera > 0
    union all
    select 3, jsonb_build_object('decision', cnt.devs || ' devolución' || case when cnt.devs = 1 then '' else 'es' end || ' de ' || public.conta_euros_exactos(round(cnt.c_devs / 100, 2)),
             'porque', 'la plataforma devolvió al cliente después de la venta: menos venta y menos IVA, contra lo que cobra la plataforma, el día en que se produce',
             'cita', 'Ley 37/1992, art. 80.Dos') from cnt where cnt.devs > 0
    union all
    select 4, jsonb_build_object('decision', 'Base calculada',
             'porque', 'algún pedido no trae la base imponible: la calculo del total al ' || tipo.txt || ' % (el tipo de tus ventas); no la invento, la deduzco y lo digo')
      from tot, tipo where tot.calculada
    union all
    select 5, jsonb_build_object('decision', 'Fuera: ' || cnt.cedidas || ' pedido' || case when cnt.cedidas = 1 then '' else 's' end || ' de marcas cedidas (' || public.conta_euros_exactos(round(cnt.c_cedidas / 100, 2)) || ')',
             'porque', 'son ventas del socio y su IVA es del socio: entran solo en su liquidación mensual, que comparas con estos tickets',
             'cita', 'Ley 37/1992, art. 11.Dos.15.º') from cnt where cnt.cedidas > 0
    union all
    select 6, jsonb_build_object('decision', 'Fuera: ' || cnt.cancelados || ' cancelado' || case when cnt.cancelados = 1 then '' else 's' end,
             'porque', 'cancelado antes de entregar no es venta') from cnt where cnt.cancelados > 0
    union all  -- los avisos van detrás, como «Mira esto», en el orden del núcleo: otro tipo y después la subcuenta
    select 7, jsonb_build_object('decision', 'Mira esto',
             'porque', tot.otro || ' pedido' || case when tot.otro = 1 then ' trae' else 's traen' end || ' en sus líneas un tipo distinto del ' || tipo.txt || ' %: mira cuáles antes de validar.')
      from tot, tipo where tot.otro > 0
    union all
    select 8, jsonb_build_object('decision', 'Mira esto',
             'porque', (select string_agg(nombre, ', ' order by o) from sin_subcuenta)
                       || case when (select count(*) from sin_subcuenta) = 1 then ' no tiene' else ' no tienen' end
                       || ' su subcuenta de ventas o de reembolsos: va a la general (' || cta.ventas || ' / ' || cta.devoluciones || '). Enlázala antes de validar.')
      from cta where exists (select 1 from sin_subcuenta)
    union all
    select 9, jsonb_build_object('decision', 'Mira esto',
             'porque', 'Por aclarar: ' || tot.n_aclarar || ' pedido' || case when tot.n_aclarar = 1 then '' else 's' end || ' con envío y sin saber si es del restaurante ('
                       || (select string_agg(coalesce(f.codigo, left(f.id::text, 8)) || ' · ' || coalesce((select name from marca_nombre where id = f.marca_id), 'sin marca')
                                             || ' · envío ' || public.conta_euros_exactos(round(f.c_env / 100.0, 2)) || ' · ' || coalesce(f.por_que, 'sin decir quién repartió'), '; ' order by f.ord)
                             from fila2 f where f.clase = 'por_aclarar')
                       || '). Se resuelve con la liquidación de esa semana: si la plataforma lo paga, va a Envíos cobrados; si no, sale de la venta y del cobro. Hasta entonces no se valida.')
      from tot where tot.n_aclarar > 0
    union all
    select 10, jsonb_build_object('decision', 'Mira esto',
             'porque', tot.n_promo_sin_cuenta || ' pedido' || case when tot.n_promo_sin_cuenta = 1 then ' lleva' else 's llevan' end || ' promoción y ' || nombre_canal.n
                       || ' no tiene su subcuenta de promociones: queda restada de la venta. Enlázala antes de validar.')
      from tot, nombre_canal where tot.n_promo_sin_cuenta > 0
    union all
    select 11, jsonb_build_object('decision', 'Mira esto',
             'porque', tot.n_envio_sin_cuenta || ' pedido' || case when tot.n_envio_sin_cuenta = 1 then ' lleva' else 's llevan' end || ' envío cobrado y ' || nombre_canal.n
                       || ' no tiene su subcuenta de envíos: queda dentro de la venta. Enlázala antes de validar.')
      from tot, nombre_canal where tot.n_envio_sin_cuenta > 0
  ) r
),
resumen as (
  select jsonb_build_object(
    'location_id', p_location, 'sales_day', p_dia,
    'unit_key', coalesce(p_canal::text, 'sin-canal') || coalesce(':' || p_marca::text, ''), 'channel_id', p_canal, 'brand_id', p_marca,
    'tickets_count', tot.n, 'total', round(tot.c_total / 100, 2),
    'by_rate', jsonb_build_array(jsonb_build_object('tax_rate_id', tipo.id, 'rate', public.conta_numero_texto(tipo.rate)::numeric, 'base', round(tot.c_base / 100, 2), 'cuota', round(tot.c_cuota / 100, 2), 'calculated', coalesce(tot.calculada, false))),
    'by_channel', case when tot.n > 0 then jsonb_build_array(jsonb_build_object('channel_id', p_canal, 'total', round(tot.c_total / 100, 2))) else '[]'::jsonb end,
    'by_brand', coalesce((select jsonb_agg(jsonb_build_object('brand_id', marca_id, 'base', round(c / 100, 2)) order by o) from por_marca), '[]'),
    'detail_hash', encode(sha256(convert_to(
        coalesce((select string_agg(id::text, '|' order by id::text collate "C") from fila2), '') || '#' || tot.c_total::bigint::text, 'UTF8')), 'hex'),
    'sale_ids', coalesce((select jsonb_agg(id order by id::text collate "C") from fila2), '[]'),
    'base_calculated', coalesce(tot.calculada, false)) as j
  from tot left join tipo on true
)
select case
  when (select id from tipo) is null or cta.iva477 is null or cta.ventas is null then
    jsonb_build_object('sin_propuesta', 'Falta el IVA de tus ventas (Tu empresa) o su 477, o la 700 en el plan.')
  when tot.n = 0 and cnt.devs = 0 then
    jsonb_build_object('sin_propuesta', case when cnt.cedidas > 0 then 'Ese día solo hubo ventas de marcas cedidas: van en la liquidación del socio.' else 'Ese día no hubo ventas de tus marcas.' end)
  when cnt.abiertos > 0 then
    jsonb_build_object('sin_propuesta', 'El cierre del día aún no ha pasado por este día: ' || cnt.abiertos || ' pedido' || case when cnt.abiertos = 1 then '' else 's' end
      || ' de tus marcas ' || case when cnt.abiertos = 1 then 'sigue abierto' else 'siguen abiertos' end || '. Pasa cada hora a los 7 minutos; vuelve a proponer después.')
  when exists (select 1 from sin_cuenta) then
    jsonb_build_object('sin_propuesta', 'No sé a qué cuenta va lo que cobra ' || (select nombre from sin_cuenta)
      || ': enlaza su 430 en su ficha (Clientes y proveedores › Plataformas).')
  when tot.n > 0 and abs(tot.c_cuota - sign(tot.c_base) * round(abs(tot.c_base * (select rate from tipo)) / 100)) > floor(0.55 * tot.n + 0.5) then
    jsonb_build_object('sin_propuesta', 'La cuota de los tickets (' || public.conta_euros_exactos(round(tot.c_cuota / 100, 2)) || ') se aleja de la base × '
      || (select txt from tipo) || ' % más de medio céntimo por ticket: hay pedidos con otro tipo.')
  else jsonb_build_object(
    'entrada', jsonb_build_object(
      'series', 1, 'fecha', p_dia,
      'concepto', 'Ventas ' || nombre_canal.n || coalesce(' · ' || (select name from marca_nombre where id = p_marca), '') || ' · ' || loc.nombre,
      'source_type', 'sales_day', 'source_id', null,
      'confianza', case when tot.otro > 0 or exists (select 1 from sin_subcuenta) or tot.n_aclarar > 0 or tot.n_promo_sin_cuenta > 0 or tot.n_envio_sin_cuenta > 0 then 'duda'
                        when tot.calculada then 'probable' else 'seguro' end,
      'porque', tot.n || case when tot.n = 1 then ' ticket de tus marcas en ' || nombre_canal.n || ' cuadra' else ' tickets de tus marcas en ' || nombre_canal.n || ' cuadran' end
                || ' con lo que cobra, al céntimo'
                || case when tot.calculada then '; base calculada al ' || (select txt from tipo) || ' %' else '' end || '.',
      'razones', razones.j, 'party_id', null, 'documento', null),
    'lineas', lineas.j,
    'resumen', resumen.j)
  end
from tot, cnt, cta, loc, lineas, razones, resumen, nombre_canal
$$;


--
-- Name: FUNCTION conta_propuesta_ventas_unidad(p_company uuid, p_location uuid, p_dia date, p_canal uuid, p_marca uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_propuesta_ventas_unidad(p_company uuid, p_location uuid, p_dia date, p_canal uuid, p_marca uuid) IS 'C04b R5: la propuesta del asiento de ventas de una unidad (canal, o canal y marca) de un día y un local (espejo de ventasDelDia con unidad), o {sin_propuesta: por qué}. Solo lee.';


--
-- Name: conta_propuestas_ventas_dia(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_propuestas_ventas_dia(p_company uuid, p_location uuid, p_dia date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with u as (
    select x.canal_id, case when exists (select 1 from public.conta_ventas_canal v where v.company_id = p_company and v.channel_id = x.canal_id and v.por_marca)
                            then x.marca_id end as marca_id, x.o
      from (select p.canal_id, p.marca_id, p.ord as o
              from public.conta_pedidos_del_dia(p_company, p_location, p_dia) with ordinality as p(id, codigo, canal_id, marca_id, propia, estado, total, base, cuota, tipos, ord)
             where p.propia and p.estado = 'closed'
            union all
            select d.canal_id, d.marca_id, 100000000 + d.ord
              from public.conta_devoluciones_del_dia(p_company, p_location, p_dia) with ordinality as d(pedido_id, codigo, canal_id, marca_id, propia, importe, ord)
             where d.propia) x
  ), u2 as (select canal_id, marca_id, min(o) as o from u group by 1, 2)
  select coalesce(jsonb_agg(jsonb_build_object(
           'unit_key', coalesce(u2.canal_id::text, 'sin-canal') || coalesce(':' || u2.marca_id::text, ''),
           'channel_id', u2.canal_id, 'brand_id', u2.marca_id,
           'propuesta', public.conta_propuesta_ventas_unidad(p_company, p_location, p_dia, u2.canal_id, u2.marca_id)) order by u2.o), '[]'::jsonb)
    from u2
$$;


--
-- Name: FUNCTION conta_propuestas_ventas_dia(p_company uuid, p_location uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_propuestas_ventas_dia(p_company uuid, p_location uuid, p_dia date) IS 'C04b R5: las propuestas de ventas de un día y un local, una por unidad (canal, o canal y marca). Solo lee.';


--
-- Name: conta_propuestos_antes_del_cierre(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_propuestos_antes_del_cierre(p_company uuid DEFAULT NULL::uuid) RETURNS TABLE(entry_id uuid, company_id uuid, location_id uuid, sales_day date, created_at timestamp with time zone, status text, number integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select e.id, e.company_id, d.location_id, d.sales_day, e.created_at, e.status, e.number
    from public.journal_entry e
    join public.sales_day_summary d on d.entry_id = e.id
   where e.source_type = 'sales_day'
     and e.status = 'propuesto'
     and (p_company is null or e.company_id = p_company)
     -- Propuesto cuando su día aún no estaba cerrado: la MISMA pregunta que
     -- hace el cierre (también la noche en que las 2:00 pasan dos veces).
     and public.conta_ultimo_dia_cerrado(e.company_id, e.created_at) < d.sales_day
$$;


--
-- Name: FUNCTION conta_propuestos_antes_del_cierre(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_propuestos_antes_del_cierre(p_company uuid) IS 'Cierre del día: los asientos de ventas del día propuestos antes de que su día llegara a la hora de cierre. Solo lee.';


--
-- Name: conta_propuestos_dia_entero(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_propuestos_dia_entero(p_company uuid DEFAULT NULL::uuid) RETURNS TABLE(entry_id uuid, summary_id uuid, company_id uuid, location_id uuid, sales_day date, created_at timestamp with time zone, status text, number integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select e.id, d.id, e.company_id, d.location_id, d.sales_day, e.created_at, e.status, e.number
    from public.journal_entry e
    join public.sales_day_summary d on d.entry_id = e.id
   where e.source_type = 'sales_day'
     and e.status = 'propuesto'
     and d.unit_key is null
     and cardinality(d.sale_ids) > 0
     and (p_company is null or e.company_id = p_company)
     and exists (select 1 from public.conta_ventas_canal v where v.company_id = e.company_id)
$$;


--
-- Name: FUNCTION conta_propuestos_dia_entero(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_propuestos_dia_entero(p_company uuid) IS 'C04b R5: los asientos de ventas propuestos a la antigua (día entero) en empresas que ya usan la regla por plataforma. Solo lee.';


--
-- Name: conta_proveedor_desde_factura(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_proveedor_desde_factura(p_invoice uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_i public.supplier_invoice; p jsonb; v_s uuid; v_nif text;
begin
  select * into v_i from public.supplier_invoice where id = p_invoice for update;
  if v_i.id is null or not public.current_user_is_admin_or_manager_of(v_i.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if v_i.supplier_id is not null then return jsonb_build_object('supplier_id', v_i.supplier_id, 'ya_estaba', true); end if;
  p := v_i.reading->'factura'->'proveedor';
  v_nif := p->>'nif';
  if coalesce(p->>'nombre', '') = '' then raise exception 'No leí el nombre del proveedor: dalo de alta a mano.' using errcode = '22023'; end if;
  -- Si entretanto alguien lo dio de alta con ese NIF, se usa ese.
  select id into v_s from public.supplier s where s.account_id = v_i.account_id and s.archived_at is null and v_nif is not null
     and regexp_replace(upper(regexp_replace(coalesce(s.tax_id, ''), '[^A-Za-z0-9]', '', 'g')), '^ES(?=[A-Z0-9]{9}$)', '') = v_nif limit 1;
  if v_s is null then
    insert into public.supplier (account_id, name, legal_name, tax_id, is_active, created_from, created_by, created_by_name)
    values (v_i.account_id, p->>'nombre', p->>'nombre', v_nif, true, 'factura', auth.uid(), p_quien_nombre)
    returning id into v_s;
  end if;
  update public.supplier_invoice set supplier_id = v_s where id = p_invoice;
  insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, actor_name, action, text)
  values (v_i.account_id, v_i.company_id, v_i.inbox_id, p_invoice, 'persona', coalesce(p_quien_nombre, 'Alguien de la cuenta'), 'corregida',
          coalesce(p_quien_nombre, 'Alguien') || ' ha dado de alta a ' || (p->>'nombre') || ' con lo leído en la factura (por completar).');
  return jsonb_build_object('supplier_id', v_s, 'ya_estaba', false);
end $_$;


--
-- Name: conta_proveedor_iban_de_factura(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_proveedor_iban_de_factura(p_supplier uuid, p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s public.supplier; v_f public.supplier_invoice;
  v_quien text := coalesce(public.conta_nombre_actor(), 'Sumied');
  v_iban text;
begin
  select * into v_s from public.supplier where id = p_supplier for update;
  if v_s.id is null or not public.current_user_is_admin_or_manager_of(v_s.account_id) then
    raise exception 'Ese proveedor no está, o no puedes cambiar su ficha.' using errcode = 'P0002';
  end if;
  select * into v_f from public.supplier_invoice where id = p_invoice and account_id = v_s.account_id;
  if v_f.id is null then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if v_f.supplier_id is distinct from v_s.id then
    raise exception 'Esa factura no es de %: elige primero su proveedor y guarda.', v_s.name using errcode = '23514';
  end if;
  -- El IBAN que trae la factura: el que guardó el lector (read_iban) o, si no, el de su lectura.
  v_iban := public._pc01e2_iban(regexp_replace(coalesce(v_f.read_iban, v_f.reading->'factura'->>'iban', ''), '[-.]', '', 'g'));
  if v_iban is null then raise exception 'Esta factura no trae IBAN.' using errcode = '22023'; end if;
  if public._pc01e2_iban(v_s.iban) is not null then
    if public._pc01e2_iban(v_s.iban) = v_iban then
      return jsonb_build_object('iban4', right(v_iban, 4), 'frase', format('%s ya tiene este IBAN (···· %s) en su ficha.', v_s.name, right(v_iban, 4)));
    end if;
    raise exception '% ya tiene otro IBAN (···· %): si esta factura trae el nuevo, decídelo en ella.', v_s.name, right(public._pc01e2_iban(v_s.iban), 4) using errcode = '23514';
  end if;
  if not public._pc01e2b_iban_valido(v_iban) then raise exception 'El IBAN de esta factura no es correcto: puede estar mal leído. Compruébalo en su PDF.' using errcode = '22023'; end if;
  if exists (select 1 from public.treasury_account t where t.account_id = v_s.account_id and public._pc01e2_iban(t.iban) = v_iban) then
    raise exception 'Ese IBAN es de una cuenta vuestra, no de %.', v_s.name using errcode = '23514';
  end if;
  update public.supplier
     set iban = v_iban, iban_set_at = now(), iban_set_by = auth.uid(), iban_set_by_name = v_quien, iban_unconfirmed_invoice_id = null,
         data_from_invoice = coalesce(data_from_invoice, '{}'::jsonb) || jsonb_build_object('iban', jsonb_build_object(
           'factura', v_f.invoice_number, 'facturaId', v_f.id, 'fecha', to_char(now() at time zone 'Europe/Madrid', 'YYYY-MM-DD'), 'quien', v_quien)),
         updated_at = now()
   where id = v_s.id;
  insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, actor_name, action, text, detail)
  values (v_f.account_id, v_f.company_id, v_f.inbox_id, v_f.id, 'persona', v_quien, 'corregida',
          format('%s guarda en la ficha de %s el IBAN de esta factura (···· %s).', v_quien, v_s.name, right(v_iban, 4)),
          jsonb_build_object('iban_puesto', true, 'iban4', right(v_iban, 4), 'supplier_id', v_s.id));
  return jsonb_build_object('iban4', right(v_iban, 4),
    'frase', format('IBAN de %s guardado en su ficha (···· %s), de la factura %s. Queda apuntado: %s, el %s a las %s.', v_s.name, right(v_iban, 4),
                    coalesce(v_f.invoice_number, 'sin número'), v_quien,
                    to_char(now() at time zone 'Europe/Madrid', 'DD/MM'), to_char(now() at time zone 'Europe/Madrid', 'HH24:MI')));
end $$;


--
-- Name: FUNCTION conta_proveedor_iban_de_factura(p_supplier uuid, p_invoice uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_proveedor_iban_de_factura(p_supplier uuid, p_invoice uuid) IS 'S01b · «Guardar este IBAN» en Revisar factura: a un proveedor sin IBAN, el de su factura, comprobado y con quién, cuándo y de qué factura. Nunca pisa otro.';


--
-- Name: conta_proveedor_iban_poner(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_proveedor_iban_poner(p_supplier uuid, p_iban text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s public.supplier; v_quien text := coalesce(public.conta_nombre_actor(), 'Sumied');
  v_iban text := public._pc01e2_iban(regexp_replace(coalesce(p_iban, ''), '[-.]', '', 'g'));
begin
  select * into v_s from public.supplier where id = p_supplier for update;
  if v_s.id is null or not public.current_user_is_admin_or_manager_of(v_s.account_id) then
    raise exception 'Ese proveedor no está, o no puedes cambiar su ficha.' using errcode = 'P0002';
  end if;
  if public._pc01e2_iban(v_s.iban) is not null then
    raise exception '% ya tiene IBAN (···· %): para cambiarlo, ve a su ficha.', v_s.name, right(public._pc01e2_iban(v_s.iban), 4) using errcode = '23514';
  end if;
  if v_iban is null then raise exception 'Escribe el IBAN.' using errcode = '22023'; end if;
  if not public._pc01e2b_iban_valido(v_iban) then raise exception 'Ese IBAN no es correcto: revisa los dígitos.' using errcode = '22023'; end if;
  if exists (select 1 from public.treasury_account t where t.account_id = v_s.account_id and public._pc01e2_iban(t.iban) = v_iban) then
    raise exception 'Ese IBAN es de una cuenta vuestra, no de %.', v_s.name using errcode = '23514';
  end if;
  update public.supplier set iban = v_iban, iban_set_at = now(), iban_set_by = auth.uid(), iban_set_by_name = v_quien,
         iban_unconfirmed_invoice_id = null, updated_at = now()
   where id = p_supplier;
  return jsonb_build_object('iban4', right(v_iban, 4),
    'frase', format('IBAN de %s puesto (···· %s). Queda apuntado: %s, el %s a las %s.', v_s.name, right(v_iban, 4), v_quien,
                    to_char(now() at time zone 'Europe/Madrid', 'DD/MM'), to_char(now() at time zone 'Europe/Madrid', 'HH24:MI')));
end $$;


--
-- Name: FUNCTION conta_proveedor_iban_poner(p_supplier uuid, p_iban text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_proveedor_iban_poner(p_supplier uuid, p_iban text) IS 'PC01 · E2b · «Poner IBAN» en la barra de Pagar: a un proveedor sin IBAN, comprobado (módulo 97) y con quién y cuándo.';


--
-- Name: conta_proveedor_iva_clase(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_proveedor_iva_clase(p_pais text, p_tipo_nif text, p_nif text, p_vies text, p_regimen text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when coalesce(nullif(upper(p_pais), ''), 'ES') = 'ES' then case when p_regimen = 'inversion_sujeto_pasivo' then 'isp_nacional' else 'nacional' end
    when upper(p_pais) = any (public.conta_paises_ue()) then
      case when p_tipo_nif = 'vat_eu' and nullif(btrim(p_nif), '') is not null and coalesce(p_vies, 'pending') <> 'invalid'
           then 'intracomunitaria' else 'ue_sin_nif_iva' end
    else 'isp_extranjero' end
$$;


--
-- Name: FUNCTION conta_proveedor_iva_clase(p_pais text, p_tipo_nif text, p_nif text, p_vies text, p_regimen text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_proveedor_iva_clase(p_pais text, p_tipo_nif text, p_nif text, p_vies text, p_regimen text) IS 'I01d (0300). Cómo se apunta el IVA de un proveedor, de su ficha: nacional, isp_nacional (régimen de IVA «inversión del sujeto pasivo»), intracomunitaria (UE con NIF-IVA que VIES no rechaza), ue_sin_nif_iva o isp_extranjero (fuera de la UE).';


--
-- Name: conta_puerta(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta(p_company uuid, p_dias integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_puerta_cuenta(p_company); v_desde timestamptz := now() - make_interval(days => greatest(1, least(p_dias, 120)));
begin
  return jsonb_build_object(
    'direcciones', coalesce((select jsonb_agg(jsonb_build_object('tipo', a.kind, 'direccion', a.local_part || '@' || a.domain, 'activa', a.active) order by a.kind)
                              from public.company_inbound_address a where a.company_id = p_company), '[]'::jsonb),
    'conectados', jsonb_build_object(
       'bancos', coalesce((select jsonb_agg(jsonb_build_object('proveedor', l.provider, 'estado', l.status, 'ultima', l.last_sync_at))
                            from public.bank_aggregator_link l where l.company_id = p_company), '[]'::jsonb),
       'uber_por_correo', exists (select 1 from public.company_inbound_address a where a.company_id = p_company and a.kind = 'liquidaciones' and a.active)),
    'ultimos', coalesce((select jsonb_agg(u order by u->>'cuando' desc) from (
      -- La bandeja: lo que llegó por correo o se subió (salvo lo que ya cuenta su lote de Catcher).
      select jsonb_build_object('id', d.id, 'fuente', 'bandeja', 'cuando', coalesce(d.email_received_at, d.created_at),
               'por', case d.channel when 'correo' then 'correo' when 'subida' then 'subido' when 'cocina' then 'cocina' else 'subido' end,
               'que', coalesce(d.doc_kind, case when d.status in ('factura', 'repetida') then 'factura' end),
               'que_por', d.doc_kind_by,
               'de', coalesce(s.name, case when d.channel = 'correo' then d.email_from end, d.file_name),
               'importe', i.grand_total, 'estado', d.status, 'motivo', d.reason,
               'donde', case when d.supplier_invoice_id is not null then 'factura'
                             when d.doc_kind = 'extracto' then 'bancos' when d.doc_kind = 'liquidacion' then 'liquidaciones'
                             when d.doc_kind = 'nomina' then 'laboral' when d.doc_kind = 'riders' then 'riders' end,
               'factura_id', d.supplier_invoice_id, 'nombre', d.file_name) u
        from public.document_inbox d
        left join public.supplier_invoice i on i.id = d.supplier_invoice_id
        left join public.supplier s on s.id = i.supplier_id
       where d.company_id = p_company and d.account_id = v_acc and d.created_at >= v_desde and d.status <> 'descartado'
         and not (d.channel = 'portal' and d.supplier_invoice_id is not null
                  and exists (select 1 from public.supplier_invoice x where x.id = d.supplier_invoice_id and x.batch_id is not null))
      union all
      -- La quincena de Catcher, como un solo documento.
      select jsonb_build_object('id', b.id, 'fuente', 'catcher', 'cuando', b.created_at, 'por', 'subido', 'que', 'riders',
               'de', 'Catcher · ' || to_char(b.period_from, 'DD/MM') || '–' || to_char(b.period_to, 'DD/MM'),
               'importe', b.grand_total,
               'estado', 'colocado', 'donde', 'riders', 'facturas', b.invoice_count)
        from public.supplier_batch b where b.company_id = p_company and b.account_id = v_acc and b.provider = 'catcher' and b.created_at >= v_desde
      union all
      -- Los extractos del banco.
      select jsonb_build_object('id', s.id, 'fuente', 'extracto', 'cuando', s.imported_at, 'por', case when s.source = 'fichero' then 'subido' else 'conexion' end,
               'que', 'extracto', 'de', coalesce((select coalesce(t.short_name, t.name) from public.treasury_account t where t.id = s.treasury_account_id), 'Banco')
                                   || ' · ' || coalesce(s.movements_count, 0) || ' mov.', 'importe', null, 'estado', 'colocado', 'donde', 'bancos')
        from public.bank_statement s where s.company_id = p_company and s.account_id = v_acc and s.imported_at >= v_desde
      union all
      -- Las liquidaciones.
      select jsonb_build_object('id', c.id, 'fuente', 'liquidacion', 'cuando', c.created_at,
               'por', case when c.source like 'correo%' then 'correo' else 'subido' end, 'que', 'liquidacion',
               'de', coalesce(ch.name, 'Plataforma') || coalesce(' · ' || nullif(c.external_brand_text, ''), ''), 'importe', c.net_payout,
               'estado', 'colocado', 'donde', 'liquidaciones')
        from public.channel_settlement c left join public.sales_channel ch on ch.id = c.channel_id and ch.account_id = c.account_id
       where c.account_id = v_acc and c.created_at >= v_desde and coalesce(c.is_reference, false) = false
      union all
      -- Las nóminas.
      select jsonb_build_object('id', n.id, 'fuente', 'nomina', 'cuando', n.created_at, 'por', 'correo', 'que', 'nomina',
               'de', 'Nómina ' || lpad(n.period_month::text, 2, '0') || '/' || n.period_year, 'importe', n.total_cost,
               'estado', case when n.status = 'matched' then 'colocado' else n.status end, 'donde', 'laboral')
        from public.payroll_inbox n where n.account_id = v_acc and n.created_at >= v_desde
    ) z), '[]'::jsonb));
end $$;


--
-- Name: conta_puerta_ajustes_poner(uuid, boolean, smallint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_ajustes_poner(p_company uuid, p_lo_que_falta boolean, p_margen smallint, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_puerta_cuenta(p_company);
begin
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado cambia los ajustes de la puerta.' using errcode = '42501';
  end if;
  insert into public.conta_puerta_ajustes (company_id, account_id, lo_que_falta, margen_dias, updated_by_name)
  values (p_company, v_acc, coalesce(p_lo_que_falta, true), coalesce(p_margen, 5), p_quien_nombre)
  on conflict (company_id) do update set lo_que_falta = excluded.lo_que_falta, margen_dias = excluded.margen_dias, updated_at = now(), updated_by_name = excluded.updated_by_name;
  return jsonb_build_object('lo_que_falta', coalesce(p_lo_que_falta, true), 'margen', coalesce(p_margen, 5),
    'texto', case when coalesce(p_lo_que_falta, true) then 'Encendido: «Lo que falta» avisa con ' || coalesce(p_margen, 5) || ' días de margen.'
                  else 'Apagado: «Lo que falta» ya no avisa en esta empresa.' end);
end $$;


--
-- Name: conta_puerta_al_dia(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_al_dia(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid := public._conta_puerta_cuenta(p_company);
  v_p jsonb;
  v_x public.supplier_expected_invoice;
  v_nuevas int := 0; v_reaprendidas int := 0; v_dormidas int := 0; v_despiertas int := 0;
  v_ultima date; v_periodo int; v_dormida boolean;
begin
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    return jsonb_build_object('nuevas', 0, 'reaprendidas', 0, 'dormidas', 0, 'despiertas', 0, 'solo_lectura', true);
  end if;
  for v_p in select jsonb_array_elements(public.conta_puerta_fuentes_proponer(p_company)) loop
    select * into v_x from public.supplier_expected_invoice where company_id = p_company and account_id = v_acc and source_key = v_p->>'clave';
    if v_x.id is null then
      perform public.conta_puerta_fuente_guardar(p_company, v_p, null);
      v_nuevas := v_nuevas + 1;
    elsif v_x.source = 'aprendido' and v_x.rhythm_set_by is null
          and (v_x.cadence is distinct from coalesce(v_p->>'cadencia', 'mensual')
               or v_x.typical_day is distinct from nullif(v_p->>'dia', '')::smallint
               or v_x.weekday is distinct from nullif(v_p->>'dia_semana', '')::smallint
               or v_x.gap_days is distinct from nullif(v_p->>'cada', '')::smallint) then
      update public.supplier_expected_invoice set
        cadence = coalesce(v_p->>'cadencia', 'mensual'), typical_day = nullif(v_p->>'dia', '')::smallint,
        weekday = nullif(v_p->>'dia_semana', '')::smallint, gap_days = nullif(v_p->>'cada', '')::smallint,
        margin_days = case when v_p ? 'margen' then nullif(v_p->>'margen', '')::smallint else margin_days end,
        updated_at = now()
       where id = v_x.id;
      v_reaprendidas := v_reaprendidas + 1;
    end if;
  end loop;
  -- Proveedores y alquileres cuyo «avisar» no decidió nadie: tres periodos sin llegar, apagado; si llega algo, encendido.
  for v_x in select * from public.supplier_expected_invoice
              where company_id = p_company and account_id = v_acc and source = 'aprendido' and active_set_by is null
                and not (updated_by_name is not null and rhythm_set_by is null and location_set_by is null)
                and kind in ('proveedor', 'alquiler') loop
    select max(d) into v_ultima from unnest(public._conta_puerta_llegadas(v_x)) d;
    v_periodo := case v_x.cadence when 'mensual' then 31 when 'quincenal' then 16 when 'semanal' then 7 else coalesce(v_x.gap_days, 10) end;
    v_dormida := v_ultima is null or v_ultima < current_date - (3 * v_periodo + coalesce(v_x.margin_days, 5));
    if v_dormida and v_x.active then
      update public.supplier_expected_invoice set active = false, updated_at = now() where id = v_x.id;
      v_dormidas := v_dormidas + 1;
    elsif not v_dormida and not v_x.active then
      update public.supplier_expected_invoice set active = true, updated_at = now() where id = v_x.id;
      v_despiertas := v_despiertas + 1;
    end if;
  end loop;
  return jsonb_build_object('nuevas', v_nuevas, 'reaprendidas', v_reaprendidas, 'dormidas', v_dormidas, 'despiertas', v_despiertas);
end $$;


--
-- Name: conta_puerta_dime_que_es(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_dime_que_es(p_inbox uuid, p_tipo text, p_recordar boolean, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_d public.document_inbox; v_from text; v_recordado boolean := false; v_que text;
begin
  select * into v_d from public.document_inbox where id = p_inbox;
  if v_d.id is null or not public.belongs_to_account(v_d.account_id) then raise exception 'Ese documento no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_d.account_id) then
    raise exception 'Solo un administrador o un encargado dice qué es un documento.' using errcode = '42501';
  end if;
  if p_tipo not in ('factura', 'ticket', 'liquidacion', 'extracto', 'nomina', 'riders', 'otro') then
    raise exception 'Un documento es una factura, un ticket, una liquidación, un extracto, una nómina, facturas de riders u otra cosa.' using errcode = '22023';
  end if;
  v_que := case p_tipo when 'factura' then 'una factura' when 'ticket' then 'un ticket' when 'liquidacion' then 'una liquidación'
                       when 'extracto' then 'un extracto del banco' when 'nomina' then 'una nómina' when 'riders' then 'una quincena de riders'
                       else 'otra cosa' end;
  update public.document_inbox set doc_kind = p_tipo, doc_kind_by = 'persona', updated_at = now() where id = p_inbox;
  v_from := lower(btrim(coalesce(substring(v_d.email_from from '<([^>]+)>'), v_d.email_from, '')));
  if p_recordar and v_d.company_id is not null and v_from <> '' then
    insert into public.company_inbound_sender (account_id, company_id, sender_sha256, decision, reason, doc_kind)
    values (v_d.account_id, v_d.company_id, encode(sha256(convert_to(v_from, 'UTF8')), 'hex'), 'tipo',
            'Lo dijo ' || coalesce(p_quien_nombre, 'una persona') || ' en la puerta: lo que manda es ' || v_que || '.', p_tipo)
    on conflict (company_id, sender_sha256) do update set decision = 'tipo', doc_kind = excluded.doc_kind, reason = excluded.reason;
    v_recordado := true;
  end if;
  insert into public.document_activity (account_id, company_id, inbox_id, actor, actor_name, action, text, detail)
  values (v_d.account_id, v_d.company_id, p_inbox, 'persona', p_quien_nombre, 'corregida',
          'Es ' || v_que || case when v_recordado then '; lo que llegue de ese remitente irá igual' else '' end || '.',
          jsonb_build_object('campo', 'tipo', 'tipo', p_tipo, 'recordado', v_recordado));
  return jsonb_build_object('id', p_inbox, 'tipo', p_tipo, 'recordado', v_recordado,
    'texto', 'Apuntado: es ' || v_que
             || case when v_recordado then '. Lo que llegue de ese remitente irá igual.' else '.' end);
end $$;


--
-- Name: conta_puerta_fuente_guardar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_fuente_guardar(p_company uuid, p jsonb, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid := public._conta_puerta_cuenta(p_company);
  v_x public.supplier_expected_invoice;
  v_match jsonb;
  v_nuevo boolean := false;
begin
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado cambia lo que se espera.' using errcode = '42501';
  end if;
  if coalesce(p->>'cadencia', 'mensual') not in ('mensual', 'quincenal', 'semanal', 'varias') then
    raise exception 'Cada cuánto llega: mensual, quincenal, semanal o varias al mes.' using errcode = '22023';
  end if;
  if p->>'proveedor_id' is not null and not exists (select 1 from public.supplier where id = (p->>'proveedor_id')::uuid and account_id = v_acc) then
    raise exception 'Ese proveedor no es de esta cuenta.' using errcode = '42501';
  end if;
  if nullif(p->>'local_id', '') is not null and not exists (select 1 from public.location_company lc
       where lc.location_id = (p->>'local_id')::uuid and lc.company_id = p_company and lc.account_id = v_acc) then
    raise exception 'Ese local no es de esta empresa.' using errcode = '42501';
  end if;
  v_match := jsonb_strip_nulls(jsonb_build_object('nifs', p->'nifs', 'numero_prefijo', p->>'numero_prefijo', 'canal', p->>'canal',
                                                  'tesoreria', p->>'tesoreria', 'nominas', case when p->>'tipo' = 'nominas' then true end));
  if p->>'id' is not null then
    select * into v_x from public.supplier_expected_invoice where id = (p->>'id')::uuid and company_id = p_company;
    if v_x.id is null then raise exception 'Esa fuente no está.' using errcode = 'P0002'; end if;
  elsif p->>'clave' is not null then
    select * into v_x from public.supplier_expected_invoice where company_id = p_company and source_key = p->>'clave';
  end if;
  if v_x.id is null then
    insert into public.supplier_expected_invoice (account_id, company_id, supplier_id, cadence, typical_day, label, source, reason, active, since,
                                                  kind, margin_days, weekday, gap_days, group_label, source_key, match, location_id, created_by, created_by_name,
                                                  rhythm_set_by, location_set_by)
    values (v_acc, p_company, (p->>'proveedor_id')::uuid, coalesce(p->>'cadencia', 'mensual'), nullif(p->>'dia', '')::smallint, p->>'nombre',
            case when p->>'clave' is not null then 'aprendido' else 'a_mano' end, p->>'motivo', coalesce((p->>'activa')::boolean, true), current_date,
            coalesce(p->>'tipo', 'proveedor'), nullif(p->>'margen', '')::smallint, nullif(p->>'dia_semana', '')::smallint, nullif(p->>'cada', '')::smallint,
            nullif(btrim(p->>'grupo'), ''), p->>'clave', v_match, nullif(p->>'local_id', '')::uuid, auth.uid(), p_quien_nombre,
            -- Lo apuntado a mano lo fijó una persona; lo aprendido, no.
            case when p->>'clave' is null and p_quien_nombre is not null then 'persona' end,
            case when p->>'clave' is null and p_quien_nombre is not null and nullif(p->>'local_id', '') is not null then 'persona' end)
    returning * into v_x;
    v_nuevo := true;
  else
    update public.supplier_expected_invoice set
      label = coalesce(p->>'nombre', label),
      group_label = case when p ? 'grupo' then nullif(btrim(p->>'grupo'), '') else group_label end,
      cadence = coalesce(p->>'cadencia', cadence),
      typical_day = case when p ? 'dia' then nullif(p->>'dia', '')::smallint else typical_day end,
      weekday = case when p ? 'dia_semana' then nullif(p->>'dia_semana', '')::smallint else weekday end,
      gap_days = case when p ? 'cada' then nullif(p->>'cada', '')::smallint else gap_days end,
      margin_days = case when p ? 'margen' then nullif(p->>'margen', '')::smallint else margin_days end,
      active = coalesce((p->>'activa')::boolean, active),
      location_id = case when p ? 'local_id' then nullif(p->>'local_id', '')::uuid else location_id end,
      match = case when v_match = '{}'::jsonb then match else v_match end,
      -- V02d · Quién decidió qué, campo a campo: una persona (con nombre) que cambia el
      -- ritmo, si avisa o el local lo deja marcado; Aprender respeta cada cosa por separado.
      rhythm_set_by = case when p_quien_nombre is not null and (p ? 'cadencia' or p ? 'dia' or p ? 'dia_semana' or p ? 'cada') then 'persona' else rhythm_set_by end,
      active_set_by = case when p_quien_nombre is not null and p ? 'activa' then 'persona' else active_set_by end,
      location_set_by = case when p_quien_nombre is not null and p ? 'local_id' then 'persona' else location_set_by end,
      updated_at = now(), updated_by_name = p_quien_nombre
     where id = v_x.id returning * into v_x;
  end if;
  return jsonb_build_object('id', v_x.id, 'nueva', v_nuevo, 'activa', v_x.active,
    'texto', case when v_nuevo then 'Apuntado: ' || coalesce(v_x.label, 'la fuente') || ' se espera ' || v_x.cadence || '.'
                  when not v_x.active then 'Apagado: ' || coalesce(v_x.label, 'la fuente') || ' ya no avisa si falta.'
                  else 'Guardado: ' || coalesce(v_x.label, 'la fuente') || '.' end);
end $$;


--
-- Name: conta_puerta_fuentes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_fuentes(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_puerta_cuenta(p_company);
begin
  return jsonb_build_object(
    'ajustes', coalesce((select jsonb_build_object('lo_que_falta', a.lo_que_falta, 'margen', a.margen_dias) from public.conta_puerta_ajustes a where a.company_id = p_company),
                        jsonb_build_object('lo_que_falta', true, 'margen', 5)),
    -- La fecha de corte: lo de antes lo lleva el programa de antes, y no se pide.
    'corte', (select b.cutover_date from public.bank_settings b where b.company_id = p_company),
    -- Los locales de la empresa, para elegir el de cada fuente (con uno solo, no se pide nada).
    'locales', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'nombre', l.name, 'direccion', l.address, 'activo', l.active) order by l.name)
                           from public.location_company lc join public.locations l on l.id = lc.location_id
                          where lc.company_id = p_company and lc.account_id = v_acc), '[]'::jsonb),
    'fuentes', coalesce((select jsonb_agg(jsonb_build_object(
        'id', x.id, 'clave', x.source_key, 'tipo', x.kind, 'nombre', coalesce(x.label, s.name, 'Sin nombre'), 'grupo', x.group_label,
        'proveedor_id', x.supplier_id, 'cadencia', x.cadence, 'dia', x.typical_day, 'dia_semana', x.weekday, 'cada', x.gap_days,
        'margen', x.margin_days, 'activa', x.active, 'origen', x.source, 'cubierta', x.covered_by_recurring_id is not null,
        -- Si una persona fijó su ritmo (entonces no se vuelve a aprender solo).
        'tocada', x.source <> 'aprendido' or x.rhythm_set_by is not null,
        'local', (select jsonb_build_object('id', l.id, 'nombre', l.name, 'direccion', l.address) from public.locations l where l.id = x.location_id),
        'llegadas', to_jsonb(public._conta_puerta_llegadas(x)),
        'cubre', public._conta_puerta_cubre(x),
        'familia', case
            when x.kind = 'alquiler' then 'alquiler'
            when x.kind in ('intermediario', 'riders') or cn.canal_id is not null then 'plataforma'
            when x.kind = 'nominas' then 'gestoria'
            when x.kind = 'banco' then 'banco'
            when exists (select 1 from public.vat_book_entry v join public.journal_line jl on jl.entry_id = v.entry_id
                           join public.company_account a on a.id = jl.company_account_id
                          where v.account_id = v_acc and v.company_id = p_company and v.book = 'received' and v.voided_at is null
                            and v.counterpart_tax_id = coalesce(s.tax_id, x.match->'nifs'->>0) and a.code like '628%') then 'suministro'
            else 'proveedor' end,
        -- El canal de venta (la plataforma) de unas liquidaciones o de su factura de comisiones.
        'canal', case when cn.canal_id is not null then jsonb_build_object('id', cn.canal_id, 'nombre', cn.canal_nombre) end,
        -- A quién se le puede pedir: su contacto de Facturación (o el primero con correo); la gestoría, las nóminas.
        'correo', case when x.kind = 'nominas' then (select nullif(btrim(p.source_email), '') from public.payroll_settings p where p.account_id = v_acc)
                       else (select c.email from public.supplier_contact c
                              where c.supplier_id = x.supplier_id and c.account_id = v_acc and nullif(btrim(c.email), '') is not null
                              order by (c.role = 'billing') desc, (c.role = 'admin') desc, c.is_primary desc nulls last, c.created_at limit 1) end,
        'pedida', (select jsonb_build_object('periodo', r.period, 'estado', r.status, 'a', r.to_email) from public.supplier_invoice_request r
                    where r.expected_id = x.id or (x.supplier_id is not null and r.supplier_id = x.supplier_id)
                    order by r.created_at desc limit 1))
      order by x.group_label nulls last, coalesce(x.label, s.name))
      from public.supplier_expected_invoice x
      left join public.supplier s on s.id = x.supplier_id
      left join lateral (
        select ch.id canal_id, ch.name canal_nombre from public.sales_channel ch
         where ch.account_id = v_acc
           and (ch.id::text = x.match->>'canal'
                or exists (select 1 from public.channel_settlement c join public.party pa on pa.id = c.party_id
                            where c.account_id = v_acc and c.channel_id = ch.id
                              and pa.tax_id = coalesce(s.tax_id, x.match->'nifs'->>0)))
         limit 1) cn on true
     where x.company_id = p_company and x.account_id = v_acc), '[]'::jsonb));
end $$;


--
-- Name: conta_puerta_fuentes_proponer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_fuentes_proponer(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid := public._conta_puerta_cuenta(p_company); v_desde date := (date_trunc('month', current_date) - interval '9 months')::date;
begin
  return coalesce((select jsonb_agg(x order by x->>'tipo', x->>'nombre') from (
    -- Proveedores con un ritmo (sin los riders, que van juntos).
    select jsonb_build_object(
      'clave', 'nif:' || r.nif, 'tipo', case when r.alquiler then 'alquiler' else 'proveedor' end,
      'nombre', r.nombre, 'proveedor_id', r.supplier_id, 'nifs', jsonb_build_array(r.nif),
      -- El local que llevaban sus facturas (el más repetido), si la empresa tiene
      -- más de uno: la persona lo confirma o lo cambia en «Qué esperas cada mes».
      'local_id', case when (select count(*) from public.location_company lc where lc.company_id = p_company and lc.account_id = v_acc) > 1 then
                    (select mode() within group (order by i.location_id) from public.supplier_invoice i
                      where i.account_id = v_acc and i.supplier_id = r.supplier_id and i.status <> 'anulada'
                        and i.location_id in (select lc.location_id from public.location_company lc where lc.company_id = p_company and lc.account_id = v_acc)) end,
      'cadencia', r.cadencia,
      'dia', case r.cadencia when 'mensual' then case when r.dia_mediano >= 28 then 31 else r.dia_mediano end when 'quincenal' then 0 end,
      'cada', case when r.cadencia = 'varias' then r.cada end,
      'meses', r.meses, 'dias_por_mes', r.dias_por_mes) as x
      from (
        select d.*,
               case
                 -- El 15 y a fin de mes (el día 15 o el último del mes, en 7 de cada 10 días con factura).
                 when d.dias_por_mes >= 1.5 and d.quincena >= 0.7 then 'quincenal'
                 -- Una vez al mes, o todos los días de cada mes juntos en una semana.
                 when d.dias_por_mes <= 1.3 or d.juntos >= 0.8 then 'mensual'
                 -- Lo demás, la siguiente desde la última (un proveedor de género factura por entrega).
                 else 'varias' end cadencia
          from (
            select f.nif, f.nombre, f.supplier_id, f.alquiler, f.meses,
                   round(f.dias::numeric / nullif(f.meses, 0), 1) dias_por_mes,
                   f.dia_mediano, f.quincena, f.juntos,
                   greatest(7, least(45, f.hueco)) cada
              from (
                select dd.nif, max(dd.nombre) nombre, max(dd.supplier_id::text)::uuid supplier_id, bool_or(dd.alquiler) alquiler,
                       count(distinct date_trunc('month', dd.d)) meses, count(*) dias, max(dd.d) ultima,
                       percentile_disc(0.5) within group (order by extract(day from dd.d)::int) dia_mediano,
                       avg(case when extract(day from dd.d) = 15 or dd.d = (date_trunc('month', dd.d) + interval '1 month - 1 day')::date then 1 else 0 end) quincena,
                       -- Qué parte de los meses tiene todos sus días con factura en 7 días o menos.
                       (select avg(case when m.dmax - m.dmin <= 7 then 1 else 0 end) from (
                          select max(extract(day from z.d)) dmax, min(extract(day from z.d)) dmin from unnest(array_agg(dd.d)) z(d) group by date_trunc('month', z.d)) m) juntos,
                       -- Días entre dos llegadas seguidas, el mediano.
                       (select percentile_disc(0.5) within group (order by g.h) from (
                          select z.d - lag(z.d) over (order by z.d) h from unnest(array_agg(dd.d)) z(d)) g where g.h is not null) hueco
                  from (
                    -- Un día con factura (sin abonos) por proveedor: diez facturas el mismo día son una llegada.
                    select v.counterpart_tax_id nif, max(v.counterpart_name) nombre, v.issue_date d,
                           (select s.id from public.supplier s where s.account_id = v_acc and s.tax_id = v.counterpart_tax_id order by s.created_at limit 1) supplier_id,
                           -- Un alquiler: su gasto va a la 621 (arrendamientos), según su asiento.
                           bool_or(exists (select 1 from public.journal_line l join public.company_account a on a.id = l.company_account_id
                                            where l.entry_id = v.entry_id and a.code like '621%')) alquiler
                      from public.vat_book_entry v
                     where v.account_id = v_acc and v.company_id = p_company and v.book = 'received' and v.voided_at is null
                       and v.issue_date >= v_desde and coalesce(v.counterpart_tax_id, '') <> '' and coalesce(v.number, '') not like 'ES I%'
                       and coalesce(v.total, 0) > 0
                     group by v.counterpart_tax_id, v.issue_date
                  ) dd
                 group by dd.nif
              ) f
             where f.meses >= 6 and f.ultima >= (date_trunc('month', current_date) - interval '2 months')::date
          ) d
      ) r
    union all
    -- Los riders: una sola fuente, quincenal.
    select jsonb_build_object('clave', 'riders', 'tipo', 'riders', 'nombre', 'Riders de Catcher', 'cadencia', 'quincenal',
                              'numero_prefijo', 'ES I', 'facturas', count(*), 'personas', count(distinct v.counterpart_tax_id))
      from public.vat_book_entry v
     where v.account_id = v_acc and v.company_id = p_company and v.book = 'received' and v.voided_at is null
       and v.issue_date >= v_desde and v.number like 'ES I%'
    having count(*) > 0
    union all
    -- Intermediarios con liquidaciones en los últimos 4 meses.
    select jsonb_build_object('clave', 'canal:' || c.channel_id, 'tipo', 'intermediario', 'nombre', coalesce(ch.name, 'Intermediario') || ' · liquidaciones',
                              'canal', c.channel_id,
                              -- El ritmo de su ÚLTIMO periodo, no el más repetido: el histórico importado
                              -- (mensual, una fila por tienda) pesaba más que los resúmenes semanales de
                              -- Uber que entran desde el 11/10 (medido el 25/10). Empate el mismo día: el más fino.
                              'cadencia', (array_agg(case when c.period_grain in ('week', 'weeks', 'semana') then 'semanal' when c.period_grain = 'quincena' then 'quincenal' else 'mensual' end
                                                     order by coalesce(c.period_to, c.settlement_date) desc,
                                                              case when c.period_grain in ('week', 'weeks', 'semana') then 0 when c.period_grain = 'quincena' then 1 else 2 end))[1],
                              -- El día de la semana en que acaba su último periodo (Uber: el domingo) y, si es semanal, 1 día de margen (Julio, 25/10).
                              'dia_semana', (array_agg(case when c.period_grain in ('week', 'weeks', 'semana') then extract(isodow from coalesce(c.period_to, c.settlement_date))::int end
                                                       order by coalesce(c.period_to, c.settlement_date) desc,
                                                                case when c.period_grain in ('week', 'weeks', 'semana') then 0 when c.period_grain = 'quincena' then 1 else 2 end))[1],
                              'margen', (array_agg(case when c.period_grain in ('week', 'weeks', 'semana') then 1 end
                                                   order by coalesce(c.period_to, c.settlement_date) desc,
                                                            case when c.period_grain in ('week', 'weeks', 'semana') then 0 when c.period_grain = 'quincena' then 1 else 2 end))[1],
                              'liquidaciones', count(*))
      from public.channel_settlement c left join public.sales_channel ch on ch.id = c.channel_id and ch.account_id = c.account_id
     where c.account_id = v_acc and coalesce(c.is_reference, false) = false and coalesce(c.period_to, c.settlement_date) >= current_date - 120
     group by c.channel_id, ch.name
    union all
    -- El banco: cada cuenta con extractos o conexión.
    select jsonb_build_object('clave', 'banco:' || t.id, 'tipo', 'banco', 'nombre', 'Extracto · ' || coalesce(t.short_name, t.name, 'banco'),
                              'tesoreria', t.id, 'cadencia', 'semanal')
      from public.treasury_account t
     where t.company_id = p_company and t.account_id = v_acc and t.is_active
       and (exists (select 1 from public.bank_statement s where s.treasury_account_id = t.id)
            or exists (select 1 from public.bank_aggregator_link l where l.treasury_account_id = t.id))
    union all
    -- Las nóminas, si la cuenta las recibe (Laboral).
    select jsonb_build_object('clave', 'nominas', 'tipo', 'nominas', 'nombre', 'Nóminas' || coalesce(' · ' || p.gestoria_name, ''),
                              'cadencia', 'mensual', 'dia', 5)
      from public.payroll_settings p where p.account_id = v_acc
  ) z), '[]'::jsonb);
end $$;


--
-- Name: conta_puerta_pedir(uuid, date, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_pedir(p_expected uuid, p_periodo date, p_email text, p_asunto text, p_cuerpo text, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_x public.supplier_expected_invoice; v_id uuid; v_mes date := date_trunc('month', p_periodo)::date; v_email text := lower(trim(coalesce(p_email, '')));
begin
  select * into v_x from public.supplier_expected_invoice where id = p_expected;
  if v_x.id is null or not public.current_user_is_admin_or_manager_of(v_x.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta pide documentos.' using errcode = '42501';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Esa dirección de correo no es válida.' using errcode = '22023'; end if;
  if coalesce(trim(p_quien_nombre), '') = '' then raise exception 'Falta quién lo pide: sin persona no se confirma.' using errcode = '22023'; end if;
  select id into v_id from public.supplier_invoice_request
   where (expected_id = p_expected or (v_x.supplier_id is not null and supplier_id = v_x.supplier_id)) and period = v_mes and status in ('confirmado', 'enviado');
  if v_id is not null then return jsonb_build_object('id', v_id, 'ya_estaba', true, 'texto', 'Ya estaba pedida este mes.'); end if;
  insert into public.supplier_invoice_request (account_id, company_id, supplier_id, expected_id, period, to_email, subject, body, status, confirmed_at, confirmed_by, confirmed_by_name)
  values (v_x.account_id, v_x.company_id, v_x.supplier_id, v_x.id, v_mes, v_email, coalesce(nullif(trim(p_asunto), ''), 'Documento pendiente'), coalesce(p_cuerpo, ''),
          'confirmado', now(), auth.uid(), p_quien_nombre)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'ya_estaba', false, 'texto', 'Pedida a ' || v_email || ': se abre tu correo con el texto para que lo mandes tú.');
end $_$;


--
-- Name: conta_puerta_subida(uuid, text, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_subida(p_company uuid, p_ruta text, p_nombre text, p_tipo text, p_bytes integer, p_sha256 text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare v_acc uuid := public._conta_puerta_cuenta(p_company); v_id uuid; v_ya uuid;
begin
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta sube documentos.' using errcode = '42501';
  end if;
  if p_ruta is null or left(p_ruta, 37) <> v_acc::text || '/' then raise exception 'La ruta no es de la carpeta de esta cuenta.' using errcode = '22023'; end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'La huella del fichero no es un sha256.' using errcode = '22023'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id = 'conta-entrada' and o.name = p_ruta) then
    raise exception 'El fichero no está subido (%).', p_ruta using errcode = 'P0002';
  end if;
  select id into v_ya from public.document_inbox where account_id = v_acc and sha256 = p_sha256 and status <> 'descartado' limit 1;
  if v_ya is not null then return jsonb_build_object('id', v_ya, 'ya_estaba', true, 'texto', coalesce(p_nombre, 'Ese documento') || ' ya estaba: no lo apunto dos veces.'); end if;
  insert into public.document_inbox (account_id, company_id, channel, file_bucket, file_path, file_name, mime_type, size_bytes, sha256, created_by, created_by_name)
  values (v_acc, p_company, 'subida', 'conta-entrada', p_ruta, p_nombre, p_tipo, p_bytes, p_sha256, auth.uid(), p_quien_nombre)
  returning id into v_id;
  insert into public.document_activity (account_id, company_id, inbox_id, actor, actor_name, action, text)
  values (v_acc, p_company, v_id, 'persona', coalesce(p_quien_nombre, 'Alguien de la cuenta'), 'recibida', coalesce(p_quien_nombre, 'Alguien') || ' ha subido ' || coalesce(p_nombre, 'un documento') || ' a la puerta.');
  return jsonb_build_object('id', v_id, 'ya_estaba', false, 'texto', coalesce(p_nombre, 'El documento') || ': guardado. Dime qué es y lo llevo a su sitio.');
end $_$;


--
-- Name: conta_puerta_ya_lo_tengo(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_puerta_ya_lo_tengo(p_expected uuid, p_dia date, p_quien_nombre text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_x public.supplier_expected_invoice; v_id uuid;
begin
  select * into v_x from public.supplier_expected_invoice where id = p_expected;
  if v_x.id is null or not public.current_user_is_admin_or_manager_of(v_x.account_id) then
    raise exception 'Solo un administrador o un encargado dice que algo ya lo tiene.' using errcode = '42501';
  end if;
  if p_dia is null then raise exception 'Falta de qué día es.' using errcode = '22023'; end if;
  insert into public.conta_puerta_recibido (account_id, company_id, expected_id, dia, created_by_name)
  values (v_x.account_id, v_x.company_id, v_x.id, p_dia, p_quien_nombre)
  on conflict (expected_id, dia) do nothing
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'ya_estaba', v_id is null);
end $$;


--
-- Name: conta_reabrir_mes(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_reabrir_mes(p_company uuid, p_mes date, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_mes date := date_trunc('month', p_mes)::date; v_ultimo date; v_id uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.current_user_is_admin_of(v_cuenta) then
    raise exception 'Solo un administrador de la cuenta puede reabrir meses' using errcode = '42501';
  end if;
  if p_motivo is null or length(trim(p_motivo)) = 0 then
    raise exception 'Para reabrir un mes hay que decir por qué' using errcode = '23514';
  end if;
  select max(month) into v_ultimo from public.fiscal_period_lock where company_id = p_company and reopened_at is null;
  if v_ultimo is distinct from v_mes then
    raise exception 'Solo se puede reabrir el último mes cerrado: %', coalesce(to_char(v_ultimo, 'MM/YYYY'), 'no hay ninguno')
      using errcode = '23514';
  end if;
  -- C04: lo traído de otro programa no se reabre aquí; se corrige allí y se vuelve a traer.
  if exists (select 1 from public.fiscal_period_lock where company_id = p_company and month = v_mes and reopened_at is null and kind = 'migrated') then
    raise exception 'El mes % es traído de otro programa: no se reabre.', to_char(v_mes, 'MM/YYYY') using errcode = '23514';
  end if;
  update public.fiscal_period_lock
     set reopened_at = now(), reopened_by = auth.uid(), reopened_by_name = public.conta_nombre_actor(), reopen_reason = trim(p_motivo)
   where company_id = p_company and month = v_mes and reopened_at is null
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'mes', v_mes);
end $$;


--
-- Name: conta_recepcion_no_es_soporte(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recepcion_no_es_soporte(p_recepcion uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_g public.goods_receipt; v_n int;
begin
  select * into v_g from public.goods_receipt where id = p_recepcion;
  if v_g.id is null or not public.belongs_to_account(v_g.account_id) then raise exception 'Esa recepción no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_g.account_id) then
    raise exception 'Solo un administrador o un encargado dice que una recepción no es soporte.' using errcode = '42501';
  end if;
  update public.goods_receipt_path set not_support_at = now(), not_support_by_name = public.conta_nombre_actor()
   where goods_receipt_id = p_recepcion and account_id = v_g.account_id and path = 'liquidacion' and not_support_at is null;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'Esa recepción no es soporte de una liquidación.' using errcode = '22023'; end if;
  return jsonb_build_object('mensaje', format('La recepción %s ya no es soporte: vuelve a «Por aclarar».', coalesce(v_g.code, 'sin código')));
end $$;


--
-- Name: FUNCTION conta_recepcion_no_es_soporte(p_recepcion uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recepcion_no_es_soporte(p_recepcion uuid) IS 'S01g. «No es soporte de la liquidación»: la recepción vuelve a «Por aclarar» en Facturas recibidas.';


--
-- Name: conta_recibe_mercancia(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibe_mercancia(p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select s.receives_goods from public.company_purchase_setting s where s.company_id = p_company), false)
$$;


--
-- Name: FUNCTION conta_recibe_mercancia(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibe_mercancia(p_company uuid) IS 'D01 · ¿Recibe la mercancía con Folvy? Sin fila (empresa nueva, o cuenta solo de contabilidad): no.';


--
-- Name: conta_recibida_envio(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_envio(p_entry uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry;
  v_i public.supplier_invoice;
  v_s public.supplier;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null or not public.belongs_to_account(v_e.account_id) then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  if v_e.source_type <> 'supplier_invoice' then
    raise exception 'Ese asiento no es de una factura recibida.' using errcode = '22023';
  end if;
  select * into v_i from public.supplier_invoice where id = v_e.source_id and account_id = v_e.account_id;
  if v_i.id is null then raise exception 'La factura de ese asiento no está.' using errcode = 'P0002'; end if;
  if v_i.source = 'liquidacion' and nullif(btrim(v_i.invoice_number), '') is null then
    raise exception 'La factura de comisión no tiene número: no va a Diez hasta tenerlo.' using errcode = '22023';
  end if;
  select * into v_s from public.supplier where id = v_i.supplier_id and account_id = v_e.account_id;

  return jsonb_build_object(
    'id', v_e.id, 'account_id', v_e.account_id, 'company_id', v_e.company_id, 'estado', v_e.status, 'fecha', v_e.entry_date,
    'factura', jsonb_build_object('numero', v_i.invoice_number, 'fecha', coalesce(v_i.invoice_date, v_e.document_date, v_e.entry_date)),
    -- E05: si la factura lleva su emisor (los riders y flotas de Catcher, en el
    -- proveedor genérico «Riders»), es el emisor el que va a Diez.
    'proveedor', jsonb_build_object('nombre', coalesce(nullif(trim(v_i.issuer_name), ''), nullif(trim(v_s.legal_name), ''), v_s.name),
                                    'nif', coalesce(nullif(trim(v_i.issuer_tax_id), ''), nullif(trim(v_s.tax_id), ''))),
    'lineas', coalesce((
      select jsonb_agg(jsonb_build_object('cuenta', a.code, 'debe', l.debit, 'haber', l.credit,
                                          'tipoIva', t.rate, 'baseIva', l.tax_base) order by l.position)
        from public.journal_line l
        join public.company_account a on a.id = l.company_account_id and a.company_id = v_e.company_id
        left join public.tax_rate t on t.id = l.tax_rate_id
       where l.entry_id = v_e.id), '[]'::jsonb),
    'documento', (select jsonb_build_object('id', d.id, 'ruta', d.storage_path, 'nombre', d.file_name, 'sha256', d.sha256)
                    from public.journal_entry_document d where d.entry_id = v_e.id and d.kind = 'factura_recibida'));
end $$;


--
-- Name: FUNCTION conta_recibida_envio(p_entry uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_envio(p_entry uuid) IS 'D01 · Lo que el envío a Diez (serie 2) lee de una factura recibida: asiento, líneas con tipo y base del IVA, factura, proveedor y su documento. Solo para los de la cuenta. La de comisión de una liquidación, solo con número.';


--
-- Name: conta_recibida_guardar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_guardar(p_invoice uuid, p_cambios jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.supplier_invoice;
  v_n public.supplier_invoice;
  v_c jsonb := coalesce(p_cambios, '{}'::jsonb);
  v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
  v_claves constant text[] := array['proveedor', 'numero', 'fecha', 'local', 'vence', 'forma_pago', 'iva', 'retencion', 'gasto', 'asiento_a_mano'];
  v_raras text[];
  v_cambios jsonb := '[]'::jsonb;
  v_textos text[] := '{}';
  v_guardado text[] := '{}';
  v_al_asiento boolean := false;
  v_quitados int := 0;
  v_vence_antes date; v_vence date;
  v_iva_antes jsonb; v_iva jsonb;
  v_gasto_antes jsonb; v_gasto jsonb;
  v_ret_antes jsonb; v_ret jsonb;
  v_tasa uuid; v_tasas uuid[]; v_tipo numeric; v_importe numeric;
  v_x jsonb; v_uuid uuid; v_txt text; v_fecha date; v_mal int;
  v_debe numeric; v_haber numeric;
  v_formas constant jsonb := '{"transfer": "Transferencia", "direct_debit": "Domiciliación", "card": "Tarjeta", "cash": "Efectivo", "prepaid": "Saldo prepago Catcher (40700001)"}'::jsonb;
begin
  if jsonb_typeof(v_c) <> 'object' then
    raise exception 'Los cambios no se entienden: tiene que ser un objeto con lo que cambia.' using errcode = '22023';
  end if;
  select array_agg(k order by k) into v_raras from jsonb_object_keys(v_c) k where not (k = any (v_claves));
  if v_raras is not null then
    raise exception 'No sé guardar: %. Lo que sé guardar: %.', array_to_string(v_raras, ', '), array_to_string(v_claves, ', ') using errcode = '22023';
  end if;

  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then
    raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501';
  end if;
  if v_f.status in ('anulada', 'descartada') then
    raise exception 'Está %: no se cambia.', v_f.status using errcode = '22023';
  end if;
  if exists (select 1 from public.journal_entry e where e.account_id = v_f.account_id and e.source_type = 'supplier_invoice'
                and e.source_id = v_f.id and e.status = 'validado') then
    raise exception 'Ya está contabilizada: para cambiarla, anula su asiento.' using errcode = '22023';
  end if;
  v_n := v_f;

  -- Proveedor
  if v_c ? 'proveedor' then
    v_uuid := nullif(v_c ->> 'proveedor', '')::uuid;
    if v_uuid is null then raise exception 'Una factura tiene proveedor.' using errcode = '22023'; end if;
    if not exists (select 1 from public.supplier s where s.id = v_uuid and s.account_id = v_f.account_id) then
      raise exception 'Ese proveedor no es de esta cuenta.' using errcode = '42501';
    end if;
    if v_uuid is distinct from v_f.supplier_id then
      v_n.supplier_id := v_uuid; v_al_asiento := true; v_guardado := array_append(v_guardado, 'proveedor');
      v_cambios := v_cambios || jsonb_build_object('campo', 'proveedor', 'antes', v_f.supplier_id, 'ahora', v_uuid);
      v_textos := array_append(v_textos, format('Proveedor %s → %s',
        coalesce((select s.name from public.supplier s where s.id = v_f.supplier_id), '—'), (select s.name from public.supplier s where s.id = v_uuid)));
    end if;
  end if;

  -- Número
  if v_c ? 'numero' then
    v_txt := nullif(trim(v_c ->> 'numero'), '');
    if v_txt is distinct from v_f.invoice_number then
      v_n.invoice_number := v_txt; v_al_asiento := true; v_guardado := array_append(v_guardado, 'numero');
      v_cambios := v_cambios || jsonb_build_object('campo', 'numero', 'antes', v_f.invoice_number, 'ahora', v_txt);
      v_textos := array_append(v_textos, format('Número %s → %s', coalesce(v_f.invoice_number, '—'), coalesce(v_txt, '—')));
    end if;
  end if;

  -- Fecha
  if v_c ? 'fecha' then
    v_fecha := nullif(v_c ->> 'fecha', '')::date;
    if v_fecha is null then raise exception 'Una factura tiene fecha.' using errcode = '22023'; end if;
    if v_fecha is distinct from v_f.invoice_date then
      v_n.invoice_date := v_fecha; v_al_asiento := true; v_guardado := array_append(v_guardado, 'fecha');
      v_cambios := v_cambios || jsonb_build_object('campo', 'fecha', 'antes', v_f.invoice_date, 'ahora', v_fecha);
      v_textos := array_append(v_textos, format('Fecha %s → %s', coalesce(to_char(v_f.invoice_date, 'DD/MM/YYYY'), '—'), to_char(v_fecha, 'DD/MM/YYYY')));
    end if;
  end if;

  -- Local
  if v_c ? 'local' then
    v_uuid := nullif(v_c ->> 'local', '')::uuid;
    if v_uuid is not null and not exists (select 1 from public.locations l where l.id = v_uuid and l.account_id = v_f.account_id) then
      raise exception 'Ese local no es de esta cuenta.' using errcode = '42501';
    end if;
    if v_uuid is distinct from v_f.location_id then
      v_n.location_id := v_uuid; v_al_asiento := true; v_guardado := array_append(v_guardado, 'local');
      v_cambios := v_cambios || jsonb_build_object('campo', 'local', 'antes', v_f.location_id, 'ahora', v_uuid);
      v_textos := array_append(v_textos, format('Local %s → %s',
        coalesce((select l.name from public.locations l where l.id = v_f.location_id), 'común'), coalesce((select l.name from public.locations l where l.id = v_uuid), 'común')));
    end if;
  end if;

  -- Forma de pago (prevista)
  if v_c ? 'forma_pago' then
    v_txt := nullif(v_c ->> 'forma_pago', '');
    if v_txt is not null and not (v_formas ? v_txt) then
      raise exception 'No conozco la forma de pago «%». Puede ser: %.', v_txt,
        (select string_agg(x.value, ', ' order by x.key) from jsonb_each_text(v_formas) x) using errcode = '22023';
    end if;
    if v_txt is distinct from v_f.payment_method then
      v_n.payment_method := v_txt; v_guardado := array_append(v_guardado, 'forma_pago');
      v_cambios := v_cambios || jsonb_build_object('campo', 'forma_pago', 'antes', v_f.payment_method, 'ahora', v_txt);
      v_textos := array_append(v_textos, format('Forma de pago %s → %s', coalesce(v_formas ->> v_f.payment_method, 'sin decir'), coalesce(v_formas ->> v_txt, 'sin decir')));
    end if;
  end if;

  -- IVA por tipos: se rehace entero y, con él, los totales.
  if v_c ? 'iva' then
    if jsonb_typeof(v_c -> 'iva') <> 'array' then raise exception 'El IVA va por tipos: una lista.' using errcode = '22023'; end if;
    select count(*) into v_mal from jsonb_array_elements(v_c -> 'iva') t
     where jsonb_typeof(t -> 'tipo') <> 'number' or jsonb_typeof(t -> 'base') <> 'number' or jsonb_typeof(t -> 'cuota') <> 'number';
    if v_mal > 0 then raise exception 'Cada línea de IVA lleva su tipo, su base y su cuota (% sin ellos).', v_mal using errcode = '22023'; end if;
    select count(*) - count(distinct (t ->> 'tipo')::numeric) into v_mal from jsonb_array_elements(v_c -> 'iva') t;
    if v_mal > 0 then raise exception 'Un mismo tipo de IVA va en una sola línea.' using errcode = '22023'; end if;
    if exists (select 1 from jsonb_array_elements(v_c -> 'iva') t
                where nullif(t ->> 'tipo_id', '') is not null
                  and not exists (select 1 from public.tax_rate r where r.id = (t ->> 'tipo_id')::uuid and (r.is_system or r.account_id = v_f.account_id))) then
      raise exception 'Ese tipo de IVA no es de esta cuenta.' using errcode = '42501';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('tipo', x.vat_pct, 'base', x.base, 'cuota', x.vat_amount, 'recargo_tipo', x.surcharge_pct,
                                                 'recargo', nullif(x.surcharge_amount, 0), 'tipo_id', x.tax_rate_id) order by x.vat_pct), '[]'::jsonb)
      into v_iva_antes from public.supplier_invoice_tax x where x.supplier_invoice_id = v_f.id;
    select coalesce(jsonb_agg(jsonb_build_object('tipo', (t ->> 'tipo')::numeric, 'base', round((t ->> 'base')::numeric, 2), 'cuota', round((t ->> 'cuota')::numeric, 2),
                                                 'recargo_tipo', nullif(t ->> 'recargo_tipo', '')::numeric, 'recargo', nullif(round(coalesce(nullif(t ->> 'recargo', '')::numeric, 0), 2), 0),
                                                 'tipo_id', nullif(t ->> 'tipo_id', '')::uuid) order by (t ->> 'tipo')::numeric), '[]'::jsonb)
      into v_iva from jsonb_array_elements(v_c -> 'iva') t;
    if v_iva is distinct from v_iva_antes
       or (select sum((t ->> 'base')::numeric) from jsonb_array_elements(v_iva) t) is distinct from v_f.tax_base_total then
      delete from public.supplier_invoice_tax x where x.supplier_invoice_id = v_f.id;
      insert into public.supplier_invoice_tax (account_id, supplier_invoice_id, tax_rate_id, vat_pct, base, vat_amount, surcharge_pct, surcharge_amount)
      select v_f.account_id, v_f.id, nullif(t ->> 'tipo_id', '')::uuid, (t ->> 'tipo')::numeric, (t ->> 'base')::numeric, (t ->> 'cuota')::numeric,
             nullif(t ->> 'recargo_tipo', '')::numeric, coalesce(nullif(t ->> 'recargo', '')::numeric, 0)
        from jsonb_array_elements(v_iva) t;
      select sum((t ->> 'base')::numeric), sum((t ->> 'cuota')::numeric), sum(nullif(t ->> 'recargo', '')::numeric)
        into v_n.tax_base_total, v_n.tax_total, v_n.surcharge_total from jsonb_array_elements(v_iva) t;
      v_n.tax_base_total := coalesce(v_n.tax_base_total, 0); v_n.tax_total := coalesce(v_n.tax_total, 0);
      v_al_asiento := true; v_guardado := array_append(v_guardado, 'iva');
      v_cambios := v_cambios || jsonb_build_object('campo', 'iva', 'antes', v_iva_antes, 'ahora', v_iva);
      v_textos := array_append(v_textos, format('IVA %s de base y %s de cuota → %s y %s',
        public.compras_euros(v_f.tax_base_total), public.compras_euros(v_f.tax_total), public.compras_euros(v_n.tax_base_total), public.compras_euros(v_n.tax_total)));
    end if;
  end if;

  -- Retención: su tipo (withholding_rate), su base y su importe; o ninguna.
  if v_c ? 'retencion' then
    v_x := v_c -> 'retencion';
    v_ret_antes := case when v_f.withholding_rate_id is null and v_f.withholding_amount is null then null
                        else jsonb_build_object('tipo_id', v_f.withholding_rate_id, 'base', v_f.withholding_base, 'importe', v_f.withholding_amount) end;
    v_importe := case when jsonb_typeof(v_x) = 'object' then round(nullif(v_x ->> 'importe', '')::numeric, 2) end;
    if v_importe is null or v_importe = 0 then
      v_tasa := null; v_ret := null;
    else
      if v_importe < 0 then raise exception 'La retención se escribe en positivo: se resta del total.' using errcode = '22023'; end if;
      v_tasa := nullif(v_x ->> 'tipo_id', '')::uuid;
      v_tipo := nullif(v_x ->> 'tipo', '')::numeric;
      if v_tasa is not null then
        if not exists (select 1 from public.withholding_rate w where w.id = v_tasa and (w.is_system or w.account_id = v_f.account_id)) then
          raise exception 'Esa retención no es de esta cuenta.' using errcode = '42501';
        end if;
      else
        if v_tipo is null then raise exception 'Dime el tipo de la retención (el %%).' using errcode = '22023'; end if;
        select array_agg(w.id order by w.sort_order, w.code) into v_tasas from public.withholding_rate w
         where w.rate = v_tipo and (w.is_system or w.account_id = v_f.account_id)
           and (w.valid_from is null or w.valid_from <= coalesce(v_n.invoice_date, current_date))
           and (w.valid_to is null or w.valid_to >= coalesce(v_n.invoice_date, current_date));
        if v_tasas is null then raise exception 'No hay ninguna retención del % %%.', v_tipo using errcode = '22023'; end if;
        if cardinality(v_tasas) = 1 then
          v_tasa := v_tasas[1];
        else
          -- Varias del mismo tanto (19 %: alquiler o capital): la que usó este proveedor la última vez.
          select i.withholding_rate_id into v_tasa from public.supplier_invoice i
           where i.account_id = v_f.account_id and i.supplier_id = v_n.supplier_id and i.withholding_rate_id = any (v_tasas)
           order by i.invoice_date desc nulls last, i.created_at desc limit 1;
          if v_tasa is null then
            raise exception 'Hay % retenciones del % %% (%): dime cuál con tipo_id.', cardinality(v_tasas), v_tipo,
              (select string_agg(w.name, ', ' order by w.sort_order, w.code) from public.withholding_rate w where w.id = any (v_tasas)) using errcode = '22023';
          end if;
        end if;
      end if;
      v_ret := jsonb_build_object('tipo_id', v_tasa, 'base', round(nullif(v_x ->> 'base', '')::numeric, 2), 'importe', v_importe);
    end if;
    if v_ret is distinct from v_ret_antes then
      v_n.withholding_rate_id := v_tasa; v_n.withholding_amount := case when v_ret is null then null else v_importe end;
      v_n.withholding_base := case when v_ret is null then null else (v_ret ->> 'base')::numeric end;
      v_al_asiento := true; v_guardado := array_append(v_guardado, 'retencion');
      v_cambios := v_cambios || jsonb_build_object('campo', 'retencion', 'antes', v_ret_antes, 'ahora', v_ret);
      v_textos := array_append(v_textos, format('Retención %s → %s', case when v_f.withholding_amount is null then 'ninguna' else public.compras_euros(v_f.withholding_amount) end,
        case when v_ret is null then 'ninguna' else public.compras_euros(v_importe) end));
    end if;
  end if;

  -- Con el IVA o la retención cambiados, el total: base + cuota + recargo − retención.
  if ('iva' = any (v_guardado) or 'retencion' = any (v_guardado)) and v_n.tax_base_total is not null and v_n.tax_total is not null then
    v_n.grand_total := v_n.tax_base_total + v_n.tax_total + coalesce(v_n.surcharge_total, 0) - coalesce(v_n.withholding_amount, 0);
  end if;

  -- El gasto repartido: cuentas del plan de su empresa, local de la cuenta o común.
  if v_c ? 'gasto' then
    if jsonb_typeof(v_c -> 'gasto') <> 'array' then raise exception 'El gasto va en una lista: cuenta, local y importe.' using errcode = '22023'; end if;
    if jsonb_array_length(v_c -> 'gasto') > 0 and v_n.company_id is null then
      raise exception 'La factura no tiene empresa: no se puede repartir su gasto en un plan.' using errcode = '22023';
    end if;
    select count(*) into v_mal from jsonb_array_elements(v_c -> 'gasto') g
     where nullif(g ->> 'cuenta', '') is null or jsonb_typeof(g -> 'importe') <> 'number';
    if v_mal > 0 then raise exception 'Cada línea del gasto lleva su cuenta y su importe (% sin ellos).', v_mal using errcode = '22023'; end if;
    select string_agg(distinct g ->> 'cuenta', ', ') into v_txt from jsonb_array_elements(v_c -> 'gasto') g
     where not exists (select 1 from public.company_account a where a.company_id = v_n.company_id and a.code = g ->> 'cuenta' and a.status <> 'cerrada');
    if v_txt is not null then raise exception 'Estas cuentas no están (o están cerradas) en el plan de la empresa: %.', v_txt using errcode = '22023'; end if;
    if exists (select 1 from jsonb_array_elements(v_c -> 'gasto') g
                where nullif(g ->> 'local', '') is not null
                  and not exists (select 1 from public.locations l where l.id = (g ->> 'local')::uuid and l.account_id = v_f.account_id)) then
      raise exception 'Un local del gasto no es de esta cuenta.' using errcode = '42501';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('cuenta', x.account_code, 'local', x.location_id, 'comun', x.is_common, 'importe', x.amount) order by x.position), '[]'::jsonb)
      into v_gasto_antes from public.supplier_invoice_expense x where x.supplier_invoice_id = v_f.id;
    select coalesce(jsonb_agg(jsonb_build_object('cuenta', g ->> 'cuenta', 'local', nullif(g ->> 'local', '')::uuid,
                                                 'comun', coalesce((g ->> 'comun')::boolean, nullif(g ->> 'local', '') is null),
                                                 'importe', round((g ->> 'importe')::numeric, 2)) order by o), '[]'::jsonb)
      into v_gasto from jsonb_array_elements(v_c -> 'gasto') with ordinality as e(g, o);
    if v_gasto is distinct from v_gasto_antes then
      delete from public.supplier_invoice_expense x where x.supplier_invoice_id = v_f.id;
      insert into public.supplier_invoice_expense (account_id, supplier_invoice_id, position, account_code, location_id, is_common, amount)
      select v_f.account_id, v_f.id, (o - 1)::int, g ->> 'cuenta', nullif(g ->> 'local', '')::uuid, (g ->> 'comun')::boolean, (g ->> 'importe')::numeric
        from jsonb_array_elements(v_gasto) with ordinality as e(g, o);
      v_al_asiento := true; v_guardado := array_append(v_guardado, 'gasto');
      v_cambios := v_cambios || jsonb_build_object('campo', 'gasto', 'antes', v_gasto_antes, 'ahora', v_gasto);
      v_textos := array_append(v_textos, case when jsonb_array_length(v_gasto) = 0 then 'Gasto: sin reparto, el de la cuenta propuesta'
                                   else format('Gasto: %s', (select string_agg(format('%s %s', g ->> 'cuenta', public.compras_euros((g ->> 'importe')::numeric)), ' + ' order by o)
                                                            from jsonb_array_elements(v_gasto) with ordinality as e(g, o))) end);
    end if;
  end if;

  -- El asiento a mano: tiene que cuadrar, con cuentas del plan de su empresa.
  if v_c ? 'asiento_a_mano' then
    v_x := v_c -> 'asiento_a_mano';
    if jsonb_typeof(v_x) = 'null' then v_x := null; end if;
    if v_x is not null then
      if jsonb_typeof(v_x) <> 'array' or jsonb_array_length(v_x) < 2 then
        raise exception 'El asiento a mano lleva al menos dos líneas.' using errcode = '22023';
      end if;
      if v_n.company_id is null then raise exception 'La factura no tiene empresa: no hay plan contra el que hacer el asiento.' using errcode = '22023'; end if;
      select string_agg(distinct coalesce(nullif(l ->> 'cuenta', ''), '(sin cuenta)'), ', ') into v_txt from jsonb_array_elements(v_x) l
       where not exists (select 1 from public.company_account a where a.company_id = v_n.company_id and a.code = l ->> 'cuenta' and a.status <> 'cerrada');
      if v_txt is not null then raise exception 'El asiento a mano usa cuentas que no están en el plan de la empresa: %.', v_txt using errcode = '22023'; end if;
      select round(sum(coalesce(nullif(l ->> 'debe', '')::numeric, 0)), 2), round(sum(coalesce(nullif(l ->> 'haber', '')::numeric, 0)), 2),
             count(*) filter (where coalesce(nullif(l ->> 'debe', '')::numeric, 0) < 0 or coalesce(nullif(l ->> 'haber', '')::numeric, 0) < 0)
        into v_debe, v_haber, v_mal from jsonb_array_elements(v_x) l;
      if v_mal > 0 then raise exception 'En el asiento, el debe y el haber van en positivo.' using errcode = '22023'; end if;
      if v_debe <> v_haber or v_debe = 0 then
        raise exception 'El asiento no cuadra: debe %, haber %.', public.compras_euros(v_debe), public.compras_euros(v_haber) using errcode = '22023';
      end if;
    end if;
    if v_x is distinct from v_f.entry_overrides then
      v_n.entry_overrides := v_x; v_al_asiento := true; v_guardado := array_append(v_guardado, 'asiento_a_mano');
      v_cambios := v_cambios || jsonb_build_object('campo', 'asiento_a_mano', 'antes', v_f.entry_overrides, 'ahora', v_x);
      v_textos := array_append(v_textos, case when v_x is null then 'Asiento: el propuesto' else 'Asiento: a mano' end);
    end if;
  end if;

  -- Vence: con set_supplier_invoice_due_date (su escritura y su registro de siempre).
  if v_c ? 'vence' then
    v_vence := nullif(v_c ->> 'vence', '')::date;
    v_vence_antes := v_f.due_date;
  end if;

  if cardinality(v_guardado) > 0 then
    update public.supplier_invoice
       set supplier_id = v_n.supplier_id, invoice_number = v_n.invoice_number, invoice_date = v_n.invoice_date, location_id = v_n.location_id,
           payment_method = v_n.payment_method, tax_base_total = v_n.tax_base_total, tax_total = v_n.tax_total, surcharge_total = v_n.surcharge_total,
           grand_total = v_n.grand_total, withholding_rate_id = v_n.withholding_rate_id, withholding_amount = v_n.withholding_amount,
           withholding_base = v_n.withholding_base, entry_overrides = v_n.entry_overrides, updated_at = now()
     where id = v_f.id;
  end if;
  if v_c ? 'vence' and v_vence is distinct from v_vence_antes then
    perform public.set_supplier_invoice_due_date(v_f.id, v_vence);
    v_guardado := array_append(v_guardado, 'vence');
    v_cambios := v_cambios || jsonb_build_object('campo', 'vence', 'antes', v_vence_antes, 'ahora', v_vence);
    v_textos := array_append(v_textos, format('Vence %s → %s', coalesce(to_char(v_vence_antes, 'DD/MM/YYYY'), 'sin vencimiento'), coalesce(to_char(v_vence, 'DD/MM/YYYY'), 'sin vencimiento')));
  end if;

  if cardinality(v_guardado) = 0 then
    return jsonb_build_object('guardado', '[]'::jsonb, 'texto', 'No había nada que guardar: todo estaba como está.', 'asiento_quitado', false);
  end if;

  -- Su asiento propuesto, si lo cambiado le afecta: fuera, para volver a proponerlo con lo nuevo.
  if v_al_asiento then
    delete from public.journal_entry e
     where e.account_id = v_f.account_id and e.source_type = 'supplier_invoice' and e.source_id = v_f.id and e.status in ('propuesto', 'borrador');
    get diagnostics v_quitados = row_count;
  end if;

  insert into public.supplier_invoice_change (account_id, supplier_invoice_id, by_name, what, cambios)
  values (v_f.account_id, v_f.id, v_quien, 'guardar', v_cambios);

  return jsonb_build_object(
    'guardado', to_jsonb(v_guardado),
    'texto', 'Guardado: ' || array_to_string(v_textos, ', ') || '.'
             || case when v_quitados > 0 then ' Su asiento propuesto se ha quitado para proponerlo otra vez con lo nuevo.' else '' end,
    'asiento_quitado', v_quitados > 0);
end $$;


--
-- Name: FUNCTION conta_recibida_guardar(p_invoice uuid, p_cambios jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_guardar(p_invoice uuid, p_cambios jsonb, p_quien_nombre text) IS 'D03 · «Guardar cambios» de la ficha de una recibida: proveedor, numero, fecha, local, vence, forma_pago, iva, retencion, gasto y asiento_a_mano (todas opcionales). Con historial; quita su asiento propuesto si le afecta. No con su asiento validado.';


--
-- Name: conta_recibida_iva_no_deducible(uuid, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_iva_no_deducible(p_invoice uuid, p_no_deducible boolean, p_motivo text DEFAULT NULL::text, p_texto text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.supplier_invoice;
  v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
  v_texto text := nullif(trim(p_texto), '');
  v_motivo text := case when coalesce(p_no_deducible, false) then nullif(trim(p_motivo), '') end;
  v_quitados int := 0;
  v_dicho text;
begin
  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then
    raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501';
  end if;
  if v_f.status in ('anulada', 'descartada') then
    raise exception 'Está %: no se cambia.', v_f.status using errcode = '22023';
  end if;
  if exists (select 1 from public.journal_entry e where e.account_id = v_f.account_id and e.source_type = 'supplier_invoice'
                and e.source_id = v_f.id and e.status = 'validado') then
    raise exception 'Ya está contabilizada: para cambiar si su IVA se deduce, anula su asiento.' using errcode = '22023';
  end if;
  if coalesce(p_no_deducible, false) and (v_motivo is null or v_motivo not in ('no_a_nombre', 'ticket_sin_nif', 'otro')) then
    raise exception 'Di por qué no se deduce: no va a nombre de la empresa, es un ticket sin NIF u otro motivo (con su texto).' using errcode = '22023';
  end if;
  if v_motivo = 'otro' and v_texto is null then
    raise exception 'Con «Otro motivo», escribe cuál.' using errcode = '22023';
  end if;
  v_dicho := case v_motivo when 'no_a_nombre' then 'no va a nombre de la empresa' when 'ticket_sin_nif' then 'es un ticket sin NIF'
                           when 'otro' then v_texto end;
  update public.supplier_invoice
     set vat_non_deductible = coalesce(p_no_deducible, false),
         vat_non_deductible_reason = v_motivo,
         vat_non_deductible_note = case when v_motivo = 'otro' then v_texto end,
         updated_at = now()
   where id = v_f.id;
  delete from public.journal_entry e
   where e.account_id = v_f.account_id and e.source_type = 'supplier_invoice' and e.source_id = v_f.id and e.status in ('propuesto', 'borrador');
  get diagnostics v_quitados = row_count;
  insert into public.supplier_invoice_change (account_id, supplier_invoice_id, by_name, what, cambios)
  values (v_f.account_id, v_f.id, v_quien, 'guardar', jsonb_build_array(jsonb_build_object('campo', 'iva_no_deducible',
          'antes', jsonb_build_object('no_deducible', v_f.vat_non_deductible, 'motivo', v_f.vat_non_deductible_reason, 'texto', v_f.vat_non_deductible_note),
          'ahora', jsonb_build_object('no_deducible', coalesce(p_no_deducible, false), 'motivo', v_motivo, 'texto', case when v_motivo = 'otro' then v_texto end))));
  return jsonb_build_object('no_deducible', coalesce(p_no_deducible, false), 'motivo', v_motivo, 'asiento_quitado', v_quitados > 0,
    'texto', case when coalesce(p_no_deducible, false)
                  then 'Guardado: su IVA no se deduce (' || v_dicho || '). Va a su gasto, sale en el libro de recibidas como no deducible y no entra en el 303.'
                  else 'Guardado: su IVA se deduce.' end
             || case when v_quitados > 0 then ' Su asiento propuesto se ha quitado para proponerlo otra vez.' else '' end);
end $$;


--
-- Name: conta_recibida_papel_poner(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_papel_poner(p_invoice uuid, p_ruta text, p_nombre text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_f public.supplier_invoice;
  v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
  v_ruta text := nullif(trim(p_ruta), '');
  v_nombre text := coalesce(nullif(trim(p_nombre), ''), regexp_replace(coalesce(nullif(trim(p_ruta), ''), ''), '^.*/', ''));
  v_d02 int := 0;
begin
  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then
    raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501';
  end if;
  if v_f.status in ('anulada', 'descartada') then
    raise exception 'Está %: no se cambia.', v_f.status using errcode = '22023';
  end if;
  if exists (select 1 from public.journal_entry e where e.account_id = v_f.account_id and e.source_type = 'supplier_invoice'
                and e.source_id = v_f.id and e.status = 'validado') then
    raise exception 'Ya está contabilizada: su documento va con el asiento. Para cambiarlo, anula su asiento.' using errcode = '22023';
  end if;
  if v_ruta is null or left(v_ruta, 37) <> v_f.account_id::text || '/' or v_ruta like '%..%' then
    raise exception 'El documento tiene que estar subido en la carpeta de esta cuenta.' using errcode = '22023';
  end if;
  if not exists (select 1 from storage.objects o where o.bucket_id = 'receipt-uploads' and o.name = v_ruta) then
    raise exception 'El documento no está subido (%): no se pone nada.', v_nombre using errcode = 'P0002';
  end if;
  if v_ruta = v_f.raw_document_url and v_f.no_document_at is null then
    return jsonb_build_object('documento', v_ruta, 'ya_estaba', true, 'pdf_reiniciado', false, 'texto', 'Ese documento ya era el suyo.');
  end if;

  update public.supplier_invoice
     set raw_document_url = v_ruta, no_document_at = null, no_document_reason = null, no_document_by_name = null, updated_at = now()
   where id = v_f.id;
  -- El D02: lo hecho (o fallado) con el documento de antes ya no vale; la pasada del minuto vuelve a mirar.
  delete from public.conta_recibida_pdf r where r.invoice_id = v_f.id;
  get diagnostics v_d02 = row_count;

  insert into public.supplier_invoice_change (account_id, supplier_invoice_id, by_name, what, cambios)
  values (v_f.account_id, v_f.id, v_quien, 'papel',
          jsonb_build_array(jsonb_build_object('campo', 'documento', 'antes', v_f.raw_document_url, 'ahora', v_ruta, 'nombre', v_nombre))
          || case when v_f.no_document_at is not null
                  then jsonb_build_array(jsonb_build_object('campo', 'sin_pdf', 'antes', v_f.no_document_reason, 'ahora', null)) else '[]'::jsonb end);

  return jsonb_build_object('documento', v_ruta, 'ya_estaba', false, 'pdf_reiniciado', v_d02 > 0,
    'texto', format('Documento puesto: «%s».', v_nombre)
             || case when v_ruta ~* '\.(jpe?g|png)$' then ' Es una foto: Folvy hace su PDF en un minuto.' else '' end
             || case when v_f.no_document_at is not null then ' Ya no está marcada «Sin PDF».' else '' end);
end $_$;


--
-- Name: FUNCTION conta_recibida_papel_poner(p_invoice uuid, p_ruta text, p_nombre text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_papel_poner(p_invoice uuid, p_ruta text, p_nombre text, p_quien_nombre text) IS 'D03 · Pone el documento de una recibida (subido en receipt-uploads, en la carpeta de su cuenta), quita «Sin PDF» y reinicia su fila del D02. Con historial. No con su asiento validado.';


--
-- Name: conta_recibida_pdf_despertar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_pdf_despertar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secreto text;
begin
  if not exists (select 1 from public.conta_recibida_pdf_por_hacer(1))
     and not exists (select 1 from public.conta_recibida_pdf_por_enlazar(1)) then
    return;
  end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  if v_secreto is null then
    raise exception 'Falta cron_secret en el Vault: no se puede despertar a conta-recibida-pdf.' using errcode = '55000';
  end if;
  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/conta-recibida-pdf',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := '{}'::jsonb, timeout_milliseconds := 150000);
end $$;


--
-- Name: FUNCTION conta_recibida_pdf_despertar(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_pdf_despertar() IS 'D02 · Cada minuto (cron conta-recibida-pdf-despertar, solo en producción): si hay alguna foto de recibida sin PDF o algún PDF sin enlazar a su asiento, llama a conta-recibida-pdf. Si falta el secreto, falla (cron lo apunta como failed), no calla.';


--
-- Name: conta_recibida_pdf_enlazar(uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_pdf_enlazar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb;
  v_e public.journal_entry;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Solo el servidor enlaza el PDF de una recibida por aquí.' using errcode = '42501';
  end if;
  v := public.conta_documento_factura_guardar(p_entry, p_ruta, p_nombre, p_sha256, p_bytes, 'automático');
  select * into v_e from public.journal_entry where id = p_entry;
  update public.conta_recibida_pdf set link_error = null, link_next_try_at = null, updated_at = now()
   where invoice_id = v_e.source_id and account_id = v_e.account_id;
  -- Si su envío a Diez esperaba por el documento, que salga ya (EUROPASTRY).
  update public.external_send set next_try_at = now()
   where entry_id = p_entry and account_id = v_e.account_id and status = 'pendiente' and last_error = 'falta el documento';
  return v;
end $$;


--
-- Name: FUNCTION conta_recibida_pdf_enlazar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_pdf_enlazar(p_entry uuid, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer) IS 'D02 · Enlaza el PDF de una recibida a su asiento validado (con conta_documento_factura_guardar, como el servidor) y, si su envío a Diez esperaba por el documento, lo despierta. Solo el servidor.';


--
-- Name: conta_recibida_pdf_fallo(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_pdf_fallo(p_invoice uuid, p_motivo text, p_enlace boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_i public.supplier_invoice;
  v_m text := left(coalesce(nullif(trim(p_motivo), ''), 'sin motivo'), 300);
begin
  select * into v_i from public.supplier_invoice where id = p_invoice;
  if v_i.id is null then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if coalesce(p_enlace, false) then
    insert into public.conta_recibida_pdf as r (invoice_id, account_id, link_attempts, link_error, link_next_try_at)
    values (v_i.id, v_i.account_id, 1, v_m, now() + interval '15 minutes')
    on conflict (invoice_id) do update
      set link_attempts = r.link_attempts + 1, link_error = v_m, link_next_try_at = now() + interval '15 minutes', updated_at = now();
  else
    insert into public.conta_recibida_pdf as r (invoice_id, account_id, attempts, last_error, next_try_at)
    values (v_i.id, v_i.account_id, 1, v_m, now() + interval '15 minutes')
    on conflict (invoice_id) do update
      set attempts = r.attempts + 1, last_error = v_m, next_try_at = now() + interval '15 minutes', updated_at = now();
  end if;
end $$;


--
-- Name: FUNCTION conta_recibida_pdf_fallo(p_invoice uuid, p_motivo text, p_enlace boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_pdf_fallo(p_invoice uuid, p_motivo text, p_enlace boolean) IS 'D02 · Apunta por qué no se ha podido hacer (o enlazar, con p_enlace) el PDF de una recibida, y su reintento a los 15 minutos. Al tercer intento no se reintenta más: queda el motivo. Solo el servidor.';


--
-- Name: conta_recibida_pdf_hecho(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_pdf_hecho(p_invoice uuid, p_ruta text, p_sha256 text, p_bytes integer, p_paginas integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_i public.supplier_invoice;
  v_r public.conta_recibida_pdf;
  v_prefijo text;
  v_obj record;
begin
  select * into v_i from public.supplier_invoice where id = p_invoice;
  if v_i.id is null then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'La huella del PDF no es un sha256.' using errcode = '22023';
  end if;
  v_prefijo := v_i.account_id::text || '/recibidas/' || v_i.id::text || '/';
  if p_ruta is distinct from v_prefijo || left(p_sha256, 16) || '.pdf' then
    raise exception 'La ruta del PDF no es la de esta factura (%<huella>.pdf).', v_prefijo using errcode = '22023';
  end if;
  if p_paginas is null or p_paginas < 1 then raise exception 'Un PDF tiene al menos una página.' using errcode = '22023'; end if;
  select o.name, (o.metadata ->> 'size')::bigint as bytes, o.metadata ->> 'mimetype' as tipo into v_obj
    from storage.objects o where o.bucket_id = 'conta-documentos' and o.name = p_ruta;
  if v_obj.name is null then raise exception 'El PDF no está subido (%): no se apunta nada.', p_ruta using errcode = 'P0002'; end if;
  if v_obj.bytes is not null and v_obj.bytes <> p_bytes then
    raise exception 'El PDF subido tiene % bytes y se dijeron %: no se apunta.', v_obj.bytes, p_bytes using errcode = '22023';
  end if;
  if v_obj.tipo is not null and v_obj.tipo <> 'application/pdf' then
    raise exception 'Lo subido no es un PDF (%).', v_obj.tipo using errcode = '22023';
  end if;
  select * into v_r from public.conta_recibida_pdf where invoice_id = v_i.id for update;
  if v_r.storage_path is not null then
    if v_r.storage_path = p_ruta then return jsonb_build_object('ruta', v_r.storage_path, 'ya_estaba', true); end if;
    raise exception 'Esa factura ya tiene su PDF: no se cambia.' using errcode = '23505';
  end if;
  insert into public.conta_recibida_pdf as r (invoice_id, account_id, storage_path, sha256, size_bytes, pages, made_at, last_error, next_try_at)
  values (v_i.id, v_i.account_id, p_ruta, p_sha256, p_bytes, p_paginas, now(), null, null)
  on conflict (invoice_id) do update
    set storage_path = excluded.storage_path, sha256 = excluded.sha256, size_bytes = excluded.size_bytes, pages = excluded.pages,
        made_at = excluded.made_at, last_error = null, next_try_at = null, updated_at = now();
  return jsonb_build_object('ruta', p_ruta, 'ya_estaba', false);
end $_$;


--
-- Name: FUNCTION conta_recibida_pdf_hecho(p_invoice uuid, p_ruta text, p_sha256 text, p_bytes integer, p_paginas integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_pdf_hecho(p_invoice uuid, p_ruta text, p_sha256 text, p_bytes integer, p_paginas integer) IS 'D02 · Apunta el PDF hecho de una recibida, si está subido en conta-documentos en <cuenta>/recibidas/<factura>/<huella>.pdf con ese tamaño. No cambia uno que ya tenga. Solo el servidor.';


--
-- Name: conta_recibida_pdf_por_enlazar(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_pdf_por_enlazar(p_limite integer DEFAULT 20) RETURNS TABLE(entry_id uuid, account_id uuid, invoice_id uuid, bucket text, ruta text, nombre text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
  select e.id, e.account_id, i.id,
         case when r.storage_path is not null then 'conta-documentos' else src.bucket end,
         coalesce(r.storage_path, src.original),
         left(coalesce(nullif(trim(coalesce(s.name, i.issuer_name, '')), ''), 'factura') || coalesce(' ' || nullif(trim(i.invoice_number), ''), ''), 120) || '.pdf'
    from public.journal_entry e
    join public.supplier_invoice i on i.id = e.source_id and i.account_id = e.account_id
    left join public.supplier s on s.id = i.supplier_id and s.account_id = i.account_id
    left join public.document_inbox d on d.id = i.inbox_id and d.account_id = i.account_id
    left join public.conta_recibida_pdf r on r.invoice_id = i.id
    cross join lateral (
      select coalesce(i.raw_document_url, d.file_path) as original,
             case when i.raw_document_url is not null then 'receipt-uploads' else d.file_bucket end as bucket
    ) src
   where e.source_type = 'supplier_invoice' and e.status = 'validado'
     and e.validated_at < now() - interval '2 minutes'
     and not exists (select 1 from public.journal_entry_document x where x.entry_id = e.id and x.kind = 'factura_recibida')
     and (r.storage_path is not null
          or (src.original is not null and src.bucket is not null
              and (src.original ~* '\.pdf$'
                   or exists (select 1 from storage.objects o where o.bucket_id = src.bucket and o.name = src.original and o.metadata ->> 'mimetype' = 'application/pdf'))))
     and (r.invoice_id is null or (r.link_attempts < 3 and (r.link_next_try_at is null or r.link_next_try_at <= now())))
   order by e.validated_at, e.id
   limit greatest(1, least(coalesce(p_limite, 20), 50))
$_$;


--
-- Name: FUNCTION conta_recibida_pdf_por_enlazar(p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_pdf_por_enlazar(p_limite integer) IS 'D02 · Los asientos validados de una recibida que no tienen su PDF enlazado, con el PDF de donde sale (el hecho por el servidor, o el original si ya era un PDF). Solo el servidor.';


--
-- Name: conta_recibida_pdf_por_hacer(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_pdf_por_hacer(p_limite integer DEFAULT 20) RETURNS TABLE(invoice_id uuid, account_id uuid, ficheros jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
  with base as (
    select i.id, i.account_id, i.created_at,
           coalesce(i.raw_document_url, d.file_path) as original,
           case when i.raw_document_url is not null then 'receipt-uploads' else d.file_bucket end as bucket,
           a.input_files
      from public.supplier_invoice i
      left join public.document_inbox d on d.id = i.inbox_id and d.account_id = i.account_id
      left join public.goods_receipt_ai_session a on a.id = i.ai_session_id
     where i.discarded_at is null
  ), fotos as (
    select b.id, b.account_id, b.created_at,
           case when jsonb_typeof(b.input_files) = 'array' and jsonb_array_length(b.input_files) > 1
                 and not exists (select 1 from jsonb_array_elements(b.input_files) f where coalesce(f ->> 'path', f #>> '{}') !~* '\.(jpe?g|png)$')
                 and exists (select 1 from jsonb_array_elements(b.input_files) f where coalesce(f ->> 'path', f #>> '{}') = b.original)
                then (select jsonb_agg(jsonb_build_object('bucket', b.bucket, 'ruta', coalesce(t.f ->> 'path', t.f #>> '{}')) order by t.n)
                        from jsonb_array_elements(b.input_files) with ordinality as t(f, n))
                else jsonb_build_array(jsonb_build_object('bucket', b.bucket, 'ruta', b.original))
           end as ficheros
      from base b
     where b.original is not null and b.bucket is not null
       and (b.original ~* '\.(jpe?g|png)$'
            or exists (select 1 from storage.objects o where o.bucket_id = b.bucket and o.name = b.original and o.metadata ->> 'mimetype' in ('image/jpeg', 'image/png')))
  )
  select f.id, f.account_id, f.ficheros
    from fotos f
    left join public.conta_recibida_pdf r on r.invoice_id = f.id
   where r.storage_path is null
     and (r.invoice_id is null or (r.attempts < 3 and (r.next_try_at is null or r.next_try_at <= now())))
   order by f.created_at, f.id
   limit greatest(1, least(coalesce(p_limite, 20), 50))
$_$;


--
-- Name: FUNCTION conta_recibida_pdf_por_hacer(p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_pdf_por_hacer(p_limite integer) IS 'D02 · Las recibidas no descartadas cuyo original es una foto (JPG o PNG) y aún no tienen PDF, con sus fotos en orden; sin las que ya fallaron 3 veces ni las que esperan su reintento. Solo el servidor.';


--
-- Name: conta_recibida_pdf_reclamar(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_pdf_reclamar(p_limite integer DEFAULT 20) RETURNS TABLE(invoice_id uuid, account_id uuid, ficheros jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
begin
  perform pg_advisory_xact_lock(hashtext('conta_recibida_pdf_reclamar'));
  create temp table if not exists _d02_reclamo (invoice_id uuid, account_id uuid, ficheros jsonb) on commit drop;
  truncate _d02_reclamo;
  insert into _d02_reclamo select * from public.conta_recibida_pdf_por_hacer(p_limite);
  insert into public.conta_recibida_pdf as r (invoice_id, account_id, next_try_at)
  select c.invoice_id, c.account_id, now() + interval '10 minutes' from _d02_reclamo c
  on conflict (invoice_id) do update set next_try_at = now() + interval '10 minutes', updated_at = now();
  return query select c.invoice_id, c.account_id, c.ficheros from _d02_reclamo c;
end $$;


--
-- Name: FUNCTION conta_recibida_pdf_reclamar(p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_pdf_reclamar(p_limite integer) IS 'D02 · Coge las fotos que faltan por convertir (conta_recibida_pdf_por_hacer) y las aparta 10 minutos para que no las coja otra pasada. Solo el servidor (conta-recibida-pdf).';


--
-- Name: conta_recibida_sin_papel(uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibida_sin_papel(p_invoice uuid, p_sin boolean, p_motivo text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.supplier_invoice;
  v_quien text := coalesce(nullif(trim(p_quien_nombre), ''), public.conta_nombre_actor(), 'una persona');
  v_motivo text := nullif(trim(p_motivo), '');
begin
  select * into v_f from public.supplier_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then
    raise exception 'Esa factura no es de tu cuenta.' using errcode = '42501';
  end if;
  if v_f.status in ('anulada', 'descartada') then
    raise exception 'Está %: no se cambia.', v_f.status using errcode = '22023';
  end if;
  if p_sin is null then raise exception 'Dime si es sin PDF o no.' using errcode = '22023'; end if;
  if p_sin then
    if v_motivo is null then raise exception 'Para decir que no tiene PDF, di por qué.' using errcode = '22023'; end if;
    if v_f.raw_document_url is not null then
      raise exception 'Ya tiene su documento: no se puede marcar «Sin PDF».' using errcode = '22023';
    end if;
    if v_f.no_document_at is not null and v_f.no_document_reason = v_motivo then
      return jsonb_build_object('sin_pdf', true, 'ya_estaba', true, 'texto', 'Ya estaba marcada «Sin PDF» con ese motivo.');
    end if;
    update public.supplier_invoice
       set no_document_at = now(), no_document_reason = v_motivo, no_document_by_name = v_quien, updated_at = now()
     where id = v_f.id;
  else
    if v_f.no_document_at is null then
      return jsonb_build_object('sin_pdf', false, 'ya_estaba', true, 'texto', 'No estaba marcada «Sin PDF».');
    end if;
    update public.supplier_invoice
       set no_document_at = null, no_document_reason = null, no_document_by_name = null, updated_at = now()
     where id = v_f.id;
  end if;
  insert into public.supplier_invoice_change (account_id, supplier_invoice_id, by_name, what, cambios)
  values (v_f.account_id, v_f.id, v_quien, 'sin_papel',
          jsonb_build_array(jsonb_build_object('campo', 'sin_pdf', 'antes', v_f.no_document_reason, 'ahora', case when p_sin then v_motivo end)));
  return jsonb_build_object('sin_pdf', p_sin, 'ya_estaba', false,
    'texto', case when p_sin then format('Marcada «Sin PDF»: %s.', v_motivo) else 'Ya no está marcada «Sin PDF».' end);
end $$;


--
-- Name: FUNCTION conta_recibida_sin_papel(p_invoice uuid, p_sin boolean, p_motivo text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibida_sin_papel(p_invoice uuid, p_sin boolean, p_motivo text, p_quien_nombre text) IS 'D03 · «Sin PDF» de una recibida, con su motivo (p_sin = true), o quitarlo (false). Con historial.';


--
-- Name: conta_recibidas_poner_vencimiento(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibidas_poner_vencimiento(p_company uuid, p_plazos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid := public._pc01e2_empresa(p_company); v_p jsonb; v_prov int := 0; v_n int := 0; v_quedan int;
begin
  for v_p in select * from jsonb_array_elements(coalesce(p_plazos, '[]'::jsonb)) loop
    if (v_p->>'dias')::int is null or (v_p->>'dias')::int < 0 or (v_p->>'dias')::int > 365 then raise exception 'El plazo va de 0 a 365 días.' using errcode = '22023'; end if;
    update public.supplier set payment_terms_days = (v_p->>'dias')::int, updated_at = now()
     where id = (v_p->>'proveedor')::uuid and account_id = v_cuenta and payment_terms_days is null;
    v_prov := v_prov + 1;
  end loop;
  update public.supplier_invoice si set due_date = si.invoice_date + s.payment_terms_days,
         due_date_set_name = format('%s · plazo del proveedor (%s días)', coalesce(public.conta_nombre_actor(), 'Sumied'), s.payment_terms_days), due_date_set_at = now()
    from public.supplier s
   where s.id = si.supplier_id and si.account_id = v_cuenta and coalesce(si.company_id, p_company) = p_company
     and si.status = 'aprobada' and si.due_date is null and si.invoice_date is not null and s.payment_terms_days is not null;
  get diagnostics v_n = row_count;
  select count(*) into v_quedan from public.supplier_invoice si
   where si.account_id = v_cuenta and coalesce(si.company_id, p_company) = p_company and si.status = 'aprobada' and si.due_date is null;
  return jsonb_build_object('facturas', v_n, 'proveedores', v_prov, 'quedan', v_quedan,
    'frase', format('Puesto el vencimiento a %s %s%s.%s', v_n, case when v_n = 1 then 'factura' else 'facturas' end,
      case when v_prov > 0 then format(' (y el plazo en la ficha de %s %s)', v_prov, case when v_prov = 1 then 'proveedor' else 'proveedores' end) else '' end,
      case when v_quedan > 0 then format(' Quedan %s sin vencimiento: no tienen fecha de factura o su proveedor sigue sin plazo.', v_quedan) else '' end));
end $$;


--
-- Name: conta_recibo_devuelto(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recibo_devuelto(p_linea uuid, p_movement uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v public.conta_cobro_remesa_linea_estado; v_r public.conta_cobro_remesa; v_m public.bank_movement; v_cuenta uuid;
  v_cli text; v_gas text; v_fee numeric; v_lineas jsonb; v_match uuid; v_entry uuid; v_ci public.customer_invoice; v_nombre text;
  v_motivo text := nullif(trim(coalesce(p_motivo, '')), '');
begin
  select * into v from public.conta_cobro_remesa_linea_estado where id = p_linea;
  if v.id is null then raise exception 'Ese recibo no existe.' using errcode = 'P0002'; end if;
  v_cuenta := public._pc01e3_empresa(v.company_id);
  perform 1 from public.conta_cobro_remesa_linea where id = p_linea for update;
  select * into v_r from public.conta_cobro_remesa where id = v.remesa_id;
  if v.estado <> 'cobrado' then raise exception 'Solo se devuelve un recibo cobrado (este está %).', v.estado using errcode = '23514'; end if;
  if v_motivo is null then raise exception 'Di el motivo de la devolución (el que da el banco).' using errcode = '22023'; end if;
  select * into v_m from public.bank_movement where id = p_movement;
  if v_m.id is null or v_m.company_id <> v.company_id then raise exception 'Ese movimiento no es de la empresa del recibo.' using errcode = '23514'; end if;
  if v_m.amount >= 0 then raise exception 'Una devolución sale del banco, y este movimiento entra.' using errcode = '23514'; end if;
  v_fee := round(abs(v_m.amount) - v.amount, 2);
  if v_fee < 0 then raise exception 'El cargo (%) es menor que el recibo (%): no es su devolución.', public.conta_euros_exactos(abs(v_m.amount)), public.conta_euros_exactos(v.amount) using errcode = '23514'; end if;
  if v_fee > 30 then raise exception 'El cargo (%) pasa del recibo (%) en más de 30 €: no parecen gastos de devolución.', public.conta_euros_exactos(abs(v_m.amount)), public.conta_euros_exactos(v.amount) using errcode = '23514'; end if;
  select * into v_ci from public.customer_invoice where id = v.invoice_id for update;
  select name into v_nombre from public.party where id = v.party_id;
  v_cli := public._pc01e3_cuenta_cliente(v.company_id, v.party_id);
  if v_cli is null then raise exception '% no tiene su cuenta de cliente (430) en el plan.', coalesce(v_nombre, 'El cliente') using errcode = '23514'; end if;
  v_lineas := jsonb_build_array(jsonb_build_object('cuenta', v_cli, 'importe', v.amount, 'tercero_id', v.party_id,
    'concepto', format('Devolución recibo %s · %s · %s', coalesce(v_ci.number_text, ''), coalesce(v_nombre, ''), v_motivo)));
  if v_fee > 0 then
    v_gas := public._pc01e3_cuenta_gastos(v.company_id);
    if v_gas is null then raise exception 'La empresa no tiene una cuenta 626 para los gastos de devolución: créala en el plan.' using errcode = '23514'; end if;
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_gas, 'importe', v_fee, 'concepto', format('Gastos devolución recibo %s', coalesce(v_ci.number_text, ''))));
  end if;
  perform public.bank_casar(p_movement, jsonb_build_object('tipo', 'cuenta', 'concepto', format('Devolución recibo %s', coalesce(v_ci.number_text, '')), 'lineas', v_lineas),
    'seguro', format('Es la devolución del recibo de la %s (remesa %s): %s más %s de gastos.', coalesce(v_ci.number_text, 'factura'), v_r.code,
      public.conta_euros_exactos(v.amount), public.conta_euros_exactos(v_fee)), '[]'::jsonb, 'persona', null);
  select id, journal_entry_id into v_match, v_entry from public.bank_match where movement_id = p_movement and status = 'vivo';
  insert into public.customer_invoice_payment (account_id, company_id, invoice_id, paid_on, amount, method, note, entry_id, bank_match_id, created_by, created_by_name)
  values (v_cuenta, v.company_id, v.invoice_id, v_m.op_date, -v.amount, 'direct_debit', format('Recibo devuelto (%s): %s.', v_r.code, v_motivo),
          v_entry, v_match, auth.uid(), coalesce(public.conta_nombre_actor(), 'Sumied'));
  update public.conta_cobro_remesa_linea set returned_at = now(), return_reason = v_motivo, return_fee = v_fee, return_match_id = v_match,
         returned_by_name = coalesce(public.conta_nombre_actor(), 'Sumied') where id = p_linea;
  perform public._conta_venta_evento(v.invoice_id, 'cobro_devuelto',
    format('%s devolvió el recibo de %s el %s (%s). La factura vuelve a «Por cobrar».', coalesce(v_nombre, 'El cliente'), public.conta_euros_exactos(v.amount),
      to_char(v_m.op_date, 'DD/MM/YYYY'), v_motivo), jsonb_build_object('remesa', v_r.id, 'casado', v_match, 'gastos', v_fee), null);
  perform public._pc01e3_evento(v_cuenta, v.remesa_id, p_linea, format('%s devuelve el recibo de la %s el %s (%s), con %s de gastos.',
    coalesce(v_nombre, 'El cliente'), coalesce(v_ci.number_text, 'factura'), to_char(v_m.op_date, 'DD/MM/YYYY'), v_motivo, public.conta_euros_exactos(v_fee)));
  return jsonb_build_object('casado', v_match, 'gastos', v_fee,
    'frase', format('%s devolvió el recibo de la %s (%s): su factura vuelve a «Por cobrar», y los %s de gastos van a la %s.',
      coalesce(v_nombre, 'El cliente'), coalesce(v_ci.number_text, 'factura'), v_motivo, public.conta_euros_exactos(v_fee), coalesce(v_gas, '626')));
end $$;


--
-- Name: FUNCTION conta_recibo_devuelto(p_linea uuid, p_movement uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recibo_devuelto(p_linea uuid, p_movement uuid, p_motivo text) IS 'PC01 · E3 · Casa la devolución de un recibo (430 del cliente y 626 de los gastos contra 572); la factura vuelve a «Por cobrar». Deshacer el casado lo devuelve todo.';


--
-- Name: conta_reclamacion_llegada(uuid, date, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_reclamacion_llegada(p_resolucion uuid, p_fecha date, p_importe numeric DEFAULT NULL::numeric, p_nota text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_x public.conta_liquidacion_resolucion; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor());
begin
  select * into v_x from public.conta_liquidacion_resolucion where id = p_resolucion for update;
  if v_x.id is null or not public.belongs_to_account(v_x.account_id) then raise exception 'Esa reclamación no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_x.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta cierra una reclamación.' using errcode = '42501';
  end if;
  if v_x.kind <> 'reclamacion' then raise exception 'Eso no es una reclamación.' using errcode = '22023'; end if;
  if v_x.arrived_on is not null then raise exception 'Esa reclamación ya estaba cerrada (el %).', to_char(v_x.arrived_on, 'DD/MM/YYYY') using errcode = '23505'; end if;
  if p_fecha is null then raise exception 'Di el día en que llegó.' using errcode = '22023'; end if;
  update public.conta_liquidacion_resolucion set arrived_on = p_fecha, arrived_amount = coalesce(p_importe, abs(importe)),
         arrived_note = nullif(btrim(coalesce(p_nota, '')), ''), arrived_by_name = v_quien
   where id = v_x.id;
  return jsonb_build_object('id', v_x.id, 'texto', 'Llegó el ' || to_char(p_fecha, 'DD/MM/YYYY') || ': ' ||
    public.conta_euros_exactos(coalesce(p_importe, abs(v_x.importe))) || ' de los ' || public.conta_euros_exactos(abs(v_x.importe)) || ' reclamados. Ya no te lo recuerdo.');
end $$;


--
-- Name: conta_recordatorio_apuntar(uuid, integer, date, boolean, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recordatorio_apuntar(p_invoice uuid, p_dia integer, p_toca date, p_enviado boolean, p_para text, p_motivo text, p_texto text, p_correo_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.customer_invoice; v_id uuid;
begin
  select * into v from public.customer_invoice where id = p_invoice;
  if v.id is null then return false; end if;
  insert into public.conta_recordatorio (account_id, company_id, invoice_id, party_id, dia, toca, enviado, motivo, para, texto, correo_id)
  values (v.account_id, v.company_id, v.id, v.party_id, p_dia, p_toca, p_enviado, case when p_enviado then null else p_motivo end,
          nullif(lower(trim(coalesce(p_para, ''))), ''), p_texto, p_correo_id)
  on conflict (invoice_id, dia) do nothing
  returning id into v_id;
  if v_id is null then return false; end if;
  perform public._conta_venta_evento(v.id, case when p_enviado then 'recordatorio' else 'recordatorio_no_enviado' end, p_texto,
    jsonb_build_object('dia', p_dia, 'para', p_para, 'motivo', p_motivo), 'Sumied');
  return true;
end $$;


--
-- Name: conta_recordatorio_prueba_datos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recordatorio_prueba_datos(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.customer_invoice where id = p_invoice;
  if v_cuenta is null then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'Solo un administrador o un encargado de la cuenta manda recordatorios.' using errcode = '42501';
  end if;
  return public._pc01e4_datos(p_invoice) || jsonb_build_object('sin', public._pc01e4_sin_recordatorio(p_invoice));
end $$;


--
-- Name: conta_recordatorios_cliente(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recordatorios_cliente(p_company uuid, p_party uuid, p_apagar boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid := public._pc01e3_empresa(p_company); v_nombre text;
begin
  select name into v_nombre from public.party where id = p_party and account_id = v_cuenta;
  if v_nombre is null then raise exception 'Ese cliente no es de la cuenta.' using errcode = 'P0002'; end if;
  insert into public.conta_cobro_cliente (company_id, party_id, account_id, sin_recordatorios, updated_at, updated_by_name)
  values (p_company, p_party, v_cuenta, coalesce(p_apagar, false), now(), coalesce(public.conta_nombre_actor(), 'Sumied'))
  on conflict (company_id, party_id) do update set sin_recordatorios = excluded.sin_recordatorios, updated_at = now(), updated_by_name = excluded.updated_by_name;
  return jsonb_build_object('frase', case when coalesce(p_apagar, false)
    then format('A %s ya no se le mandan recordatorios.', v_nombre)
    else format('A %s se le vuelven a mandar recordatorios.', v_nombre) end);
end $$;


--
-- Name: conta_recordatorios_despertar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recordatorios_despertar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_secreto text;
begin
  if extract(hour from (now() at time zone 'Europe/Madrid')) <> 9 then return; end if;
  if not exists (select 1 from public.conta_recordatorios_por_mandar(null, 1)) then return; end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  if v_secreto is null then
    raise exception 'Falta cron_secret en el Vault: no se puede despertar a conta-recordatorios.' using errcode = '55000';
  end if;
  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/conta-recordatorios',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := '{}'::jsonb, timeout_milliseconds := 150000);
end $$;


--
-- Name: FUNCTION conta_recordatorios_despertar(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recordatorios_despertar() IS 'PC01 · E4 · Cada hora (cron conta-recordatorios-despertar, solo en producción): a las 9 de Madrid, si hay recordatorios que mandar, llama a conta-recordatorios. Si falta el secreto, falla (cron lo apunta como failed), no calla.';


--
-- Name: conta_recordatorios_por_mandar(date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recordatorios_por_mandar(p_hoy date DEFAULT NULL::date, p_limite integer DEFAULT 200) RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with hoy as (select coalesce(p_hoy, public.conta_hoy()) as d),
  pasos as (
    select c.invoice_id, d.dia, c.vence + d.dia as toca
      from public.conta_factura_cobro c
      join public.customer_invoice ci on ci.id = c.invoice_id
      cross join hoy
      cross join lateral unnest(public._pc01e4_dias(c.company_id)) as d(dia)
     where ci.status = 'emitida' and not c.de_plataforma and c.total > 0 and c.pendiente >= 0.005 and c.vence is not null
       and c.vence + d.dia between hoy.d - 2 and hoy.d
       and not exists (select 1 from public.conta_recordatorio r where r.invoice_id = c.invoice_id and r.dia = d.dia)
  ),
  uno as (
    select distinct on (invoice_id) invoice_id, dia, toca from pasos order by invoice_id, dia desc
  )
  select public._pc01e4_datos(u.invoice_id) || jsonb_build_object('dia', u.dia, 'toca', u.toca, 'sin', public._pc01e4_sin_recordatorio(u.invoice_id))
    from uno u
   where public._pc01e4_sin_recordatorio(u.invoice_id) is null or public._pc01e4_sin_recordatorio(u.invoice_id) = 'sin_correo'
   order by u.toca, u.invoice_id
   limit greatest(1, least(coalesce(p_limite, 200), 1000))
$$;


--
-- Name: FUNCTION conta_recordatorios_por_mandar(p_hoy date, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recordatorios_por_mandar(p_hoy date, p_limite integer) IS 'PC01 · E4 · Los recordatorios que toca mandar hoy (solo el servidor, conta-recordatorios). Uno por factura; los «sin_correo» van también, para apuntar que no salieron.';


--
-- Name: conta_recordatorios_resumen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_recordatorios_resumen(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_hoy date := public.conta_hoy(); v_dias integer[] := public._pc01e4_dias(p_company);
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;
  return jsonb_build_object(
    'activos', coalesce((select recordatorios from public.conta_cobro_ajuste where company_id = p_company), true),
    'dias', to_jsonb(v_dias),
    'cambiado', (select jsonb_build_object('at', updated_at, 'por', updated_by_name) from public.conta_cobro_ajuste where company_id = p_company),
    'clientes_apagados', coalesce((
      select jsonb_agg(jsonb_build_object('id', k.party_id, 'nombre', p.name, 'por', k.updated_by_name, 'at', k.updated_at) order by p.name)
        from public.conta_cobro_cliente k join public.party p on p.id = k.party_id
       where k.company_id = p_company and k.sin_recordatorios), '[]'::jsonb),
    'facturas', coalesce((
      select jsonb_agg(x) from (
        select jsonb_build_object(
                 'id', c.invoice_id,
                 'enviados', (select count(*) from public.conta_recordatorio r where r.invoice_id = c.invoice_id and r.enviado),
                 'ultimo', (select max(r.toca) from public.conta_recordatorio r where r.invoice_id = c.invoice_id and r.enviado),
                 'no_salio', (select jsonb_build_object('toca', r.toca, 'motivo', r.motivo) from public.conta_recordatorio r
                               where r.invoice_id = c.invoice_id and not r.enviado order by r.toca desc limit 1),
                 'proximo', case when s.sin is null then (
                    select min(c.vence + d.dia) from unnest(v_dias) d(dia)
                     where c.vence + d.dia >= v_hoy
                       and not exists (select 1 from public.conta_recordatorio r where r.invoice_id = c.invoice_id and r.dia = d.dia)) end,
                 'sin', s.sin) as x
          from public.conta_factura_cobro c
          join public.customer_invoice ci on ci.id = c.invoice_id
          cross join lateral (select public._pc01e4_sin_recordatorio(c.invoice_id) as sin) s
         where c.company_id = p_company and ci.status = 'emitida' and c.total > 0 and c.pendiente >= 0.005) f), '[]'::jsonb),
    'ultimos', coalesce((
      select jsonb_agg(jsonb_build_object('at', r.at, 'factura', ci.number_text, 'factura_id', r.invoice_id, 'cliente', coalesce(p.name, ci.customer->>'nombre'),
                                          'para', r.para, 'enviado', r.enviado, 'motivo', r.motivo, 'dia', r.dia) order by r.at desc)
        from (select * from public.conta_recordatorio where company_id = p_company order by at desc limit 20) r
        join public.customer_invoice ci on ci.id = r.invoice_id
        left join public.party p on p.id = r.party_id), '[]'::jsonb),
    'hoy', v_hoy);
end $$;


--
-- Name: FUNCTION conta_recordatorios_resumen(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_recordatorios_resumen(p_company uuid) IS 'PC01 · E4 · Ventas › Cobros (columna «Recordatorios» y su diálogo) y Ajustes › Cobros: los ajustes, los clientes apagados, los últimos recordatorios y, por factura pendiente, cuántos han salido, el próximo y por qué no lleva.';


--
-- Name: conta_redsys_aviso_apuntar(text, uuid, boolean, text, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_redsys_aviso_apuntar(p_pedido text, p_empresa uuid, p_firma_ok boolean, p_respuesta text, p_importe numeric, p_resultado text, p_detalle jsonb) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.conta_redsys_aviso (pedido, company_id, firma_ok, respuesta, importe, resultado, detalle)
  values (left(p_pedido, 40), p_empresa, coalesce(p_firma_ok, false), left(p_respuesta, 10), p_importe, left(coalesce(p_resultado, '?'), 400), p_detalle)
  returning id
$$;


--
-- Name: conta_redsys_aviso_datos(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_redsys_aviso_datos(p_pedido text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('empresa', e.company_id, 'enlace', e.id, 'comercio', r.comercio, 'terminal', r.terminal, 'modo', r.modo, 'cobra', r.cobra,
                            'clave', (select s.decrypted_secret from vault.decrypted_secrets s where s.id = r.clave_ref))
    from public.conta_enlace_pago_intento i
    join public.conta_enlace_pago e on e.id = i.enlace_id
    left join public.conta_cobro_redsys r on r.company_id = e.company_id
   where i.pedido = p_pedido
$$;


--
-- Name: conta_remesa_casar(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_casar(p_movement uuid, p_remesa uuid, p_lineas uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_r public.conta_pago_remesa; v_m public.bank_movement; v_cuenta uuid; v_suma numeric := 0; v_lineas jsonb := '[]'::jsonb;
  v_res jsonb; v_match uuid; v_l record; v_inv public.supplier_invoice; v_n int := 0; v_pagadas int := 0; v_ids uuid[];
  v_entry uuid; v_total numeric; v_vivas int; v_sin_confirmar int; v_solo boolean := false; v_porque text;
begin
  select * into v_r from public.conta_pago_remesa where id = p_remesa for update;
  if v_r.id is null then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  v_cuenta := public._pc01e2_empresa(v_r.company_id);
  select * into v_m from public.bank_movement where id = p_movement;
  if v_m.id is null or v_m.company_id <> v_r.company_id then raise exception 'Ese movimiento no es de la empresa de la remesa.' using errcode = '23514'; end if;
  if v_m.amount >= 0 then raise exception 'El cargo de una remesa sale del banco, y este movimiento entra.' using errcode = '23514'; end if;
  if v_r.kind = 'fichero' and v_r.file_at is null then raise exception 'El fichero de la remesa % no se ha descargado: el banco aún no la tiene.', v_r.code using errcode = '23514'; end if;
  select array_agg(id order by id) into v_ids from public.conta_pago_remesa_linea_estado
   where remesa_id = p_remesa and estado = 'pendiente' and (p_lineas is null or id = any(p_lineas));
  if v_ids is null then raise exception 'La remesa % no tiene pagos esperando el cargo.', v_r.code using errcode = '23514'; end if;
  if p_lineas is not null and cardinality(v_ids) <> cardinality(p_lineas) then raise exception 'Alguno de esos pagos no está esperando el cargo.' using errcode = '23514'; end if;
  -- Una línea del asiento por proveedor.
  for v_l in select l.supplier_id, s.name, public._pc01e2_cuenta_proveedor(v_r.company_id, l.supplier_id) as cuenta,
                    (select pr.party_id from public.party_role pr where pr.supplier_id = l.supplier_id and pr.role = 'supplier' limit 1) as tercero,
                    sum(l.amount) as importe, string_agg(coalesce(si.invoice_number, 'sin número'), ', ' order by si.invoice_date) as facturas
               from public.conta_pago_remesa_linea l join public.supplier_invoice si on si.id = l.invoice_id left join public.supplier s on s.id = l.supplier_id
              where l.id = any(v_ids) group by l.supplier_id, s.name loop
    if v_l.cuenta is null then raise exception '% no tiene su cuenta de proveedor (400) en el plan.', coalesce(v_l.name, 'Un proveedor') using errcode = '23514'; end if;
    v_suma := v_suma + v_l.importe;
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_l.cuenta, 'importe', v_l.importe, 'tercero_id', v_l.tercero,
      'concepto', format('Pago remesa %s · %s · %s', v_r.code, coalesce(v_l.name, ''), v_l.facturas)));
  end loop;
  if abs(v_suma - abs(v_m.amount)) >= 0.005 then
    raise exception 'El cargo es de % y lo que espera la remesa % es %.', public.conta_euros_exactos(abs(v_m.amount)), v_r.code, public.conta_euros_exactos(v_suma) using errcode = '23514';
  end if;
  v_res := public.bank_casar(p_movement, jsonb_build_object('tipo', 'cuenta', 'concepto', format('Pago remesa %s', v_r.code), 'lineas', v_lineas),
    'seguro', format('Es el cargo de la remesa %s: %s.', v_r.code, public.conta_euros_exactos(v_suma)), '[]'::jsonb, 'persona', null);
  select id into v_match from public.bank_match where movement_id = p_movement and status = 'vivo';
  -- Cada factura con lo que paga: el disparador del casado apunta su pago con este asiento.
  for v_l in select l.id, l.invoice_id, l.amount from public.conta_pago_remesa_linea l where l.id = any(v_ids) loop
    select * into v_inv from public.supplier_invoice where id = v_l.invoice_id for update;
    insert into public.bank_match_item (account_id, match_id, supplier_invoice_id, amount, marked_by_bank)
    values (v_cuenta, v_match, v_inv.id, v_l.amount, false);
    update public.conta_pago_remesa_linea set bank_match_id = v_match where id = v_l.id;
    update public.supplier_invoice set payment_entry_id = coalesce(payment_entry_id, (select journal_entry_id from public.bank_match where id = v_match)) where id = v_inv.id;
    if v_inv.status = 'aprobada' and coalesce((select sum(amount) from public.supplier_invoice_payment where invoice_id = v_inv.id and entry_id is not null), 0) >= coalesce(v_inv.grand_total, 0) - 0.005 then
      perform public.mark_supplier_invoice_paid(v_inv.id, v_m.op_date, 'transfer');
      update public.bank_match_item set marked_by_bank = true where match_id = v_match and supplier_invoice_id = v_inv.id;
      v_pagadas := v_pagadas + 1;
    end if;
    v_n := v_n + 1;
  end loop;
  perform public._pc01e2_evento(v_cuenta, p_remesa, null, format('Llega el cargo del %s en el banco: %s %s casados, %s %s.',
    to_char(v_m.op_date, 'DD/MM/YYYY'), v_n, case when v_n = 1 then 'pago' else 'pagos' end, v_pagadas, case when v_pagadas = 1 then 'factura pagada' else 'facturas pagadas' end));

  -- Respuesta 7 · El asiento se valida solo, y solo si: es una remesa de
  -- transferencias, el cargo es su total entero al céntimo (todos sus pagos
  -- en este cargo, ninguno casado antes), cada IBAN está comprobado (el mismo
  -- de pagos anteriores) o confirmado por alguien, y el asiento pasa las reglas
  -- de validar (cuadra, mes abierto, local…). Si no, queda en «Por validar».
  select journal_entry_id into v_entry from public.bank_match where id = v_match;
  select total, vivas into v_total, v_vivas from public.conta_pago_remesa_estado where id = p_remesa;
  select count(*) into v_sin_confirmar from public.conta_pago_remesa_linea
   where id = any(v_ids) and not (iban_check = 'comprobado' or iban_confirmed_at is not null);
  v_porque := case
    when v_r.kind <> 'fichero' then 'es un pago a mano'
    when p_lineas is not null or cardinality(v_ids) <> v_vivas then 'el banco ha cargado solo una parte de la remesa'
    when abs(v_m.amount) <> v_total then 'el cargo no es el total de la remesa'
    when v_sin_confirmar > 0 then format('%s IBAN sin confirmar', v_sin_confirmar)
    when v_entry is null then 'no hay asiento'
    when exists (select 1 from public.journal_entry where id = v_entry and status not in ('propuesto', 'borrador')) then null
    else (select m.motivo from public.conta_motivos_para_validar(v_entry) m order by m.orden limit 1)
  end;
  if v_porque is null and v_entry is not null and exists (select 1 from public.journal_entry where id = v_entry and status in ('propuesto', 'borrador')) then
    perform public.journal_entry_validar(v_entry, format('%s · el cargo cuadra con la remesa %s', coalesce(public.conta_nombre_actor(), 'Sumied'), v_r.code));
    update public.conta_pago_remesa set validated_solo_at = now(), validated_solo_entry = v_entry where id = p_remesa;
    perform public._pc01e2_evento(v_cuenta, p_remesa, null, 'Asiento validado solo: el cargo cuadra con la remesa.');
    v_solo := true;
  end if;

  return jsonb_build_object('casado', v_match, 'pagos', v_n, 'pagadas', v_pagadas, 'validado_solo', v_solo,
    'frase', format('Casado con la remesa %s: %s %s, %s. %s %s %s.', v_r.code, v_n, case when v_n = 1 then 'pago' else 'pagos' end,
      public.conta_euros_exactos(v_suma), v_pagadas, case when v_pagadas = 1 then 'factura queda pagada' else 'facturas quedan pagadas' end,
      case when v_solo then 'y su asiento validado solo: el cargo cuadra con la remesa'
           else format('con su asiento propuesto, en «Por validar» (no se valida solo: %s)', coalesce(v_porque, 'ya estaba validado')) end));
end $$;


--
-- Name: FUNCTION conta_remesa_casar(p_movement uuid, p_remesa uuid, p_lineas uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_remesa_casar(p_movement uuid, p_remesa uuid, p_lineas uuid[]) IS 'PC01 · E2 · Casa el cargo del banco con una remesa de pagos (entera o los pagos que carga): un asiento (400/410 contra 572) por bank_casar y las facturas pagadas. Deshacer el casado lo devuelve todo.';


--
-- Name: conta_remesa_cobros_casar(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_cobros_casar(p_movement uuid, p_remesa uuid, p_lineas uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_r public.conta_cobro_remesa; v_m public.bank_movement; v_cuenta uuid; v_suma numeric := 0; v_lineas jsonb := '[]'::jsonb;
  v_match uuid; v_l record; v_n int := 0; v_cobradas int := 0; v_ids uuid[];
begin
  select * into v_r from public.conta_cobro_remesa where id = p_remesa for update;
  if v_r.id is null then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  v_cuenta := public._pc01e3_empresa(v_r.company_id);
  select * into v_m from public.bank_movement where id = p_movement;
  if v_m.id is null or v_m.company_id <> v_r.company_id then raise exception 'Ese movimiento no es de la empresa de la remesa.' using errcode = '23514'; end if;
  if v_m.amount <= 0 then raise exception 'El abono de una remesa de recibos entra en el banco, y este movimiento sale.' using errcode = '23514'; end if;
  if v_r.file_at is null then raise exception 'El fichero de la remesa % no se ha descargado: el banco aún no la tiene.', v_r.code using errcode = '23514'; end if;
  select array_agg(id order by id) into v_ids from public.conta_cobro_remesa_linea_estado
   where remesa_id = p_remesa and estado = 'pendiente' and (p_lineas is null or id = any(p_lineas));
  if v_ids is null then raise exception 'La remesa % no tiene recibos esperando el abono.', v_r.code using errcode = '23514'; end if;
  if p_lineas is not null and cardinality(v_ids) <> cardinality(p_lineas) then raise exception 'Alguno de esos recibos no está esperando el abono.' using errcode = '23514'; end if;
  for v_l in select l.party_id, p.name, public._pc01e3_cuenta_cliente(v_r.company_id, l.party_id) as cuenta,
                    sum(l.amount) as importe, string_agg(coalesce(ci.number_text, 'sin número'), ', ' order by ci.issue_date) as facturas
               from public.conta_cobro_remesa_linea l join public.customer_invoice ci on ci.id = l.invoice_id left join public.party p on p.id = l.party_id
              where l.id = any(v_ids) group by l.party_id, p.name loop
    if v_l.cuenta is null then raise exception '% no tiene su cuenta de cliente (430) en el plan.', coalesce(v_l.name, 'Un cliente') using errcode = '23514'; end if;
    v_suma := v_suma + v_l.importe;
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_l.cuenta, 'importe', v_l.importe, 'tercero_id', v_l.party_id,
      'concepto', format('Cobro remesa %s · %s · %s', v_r.code, coalesce(v_l.name, ''), v_l.facturas)));
  end loop;
  if abs(v_suma - v_m.amount) >= 0.005 then
    raise exception 'El abono es de % y lo que espera la remesa % es %.', public.conta_euros_exactos(v_m.amount), v_r.code, public.conta_euros_exactos(v_suma) using errcode = '23514';
  end if;
  perform public.bank_casar(p_movement, jsonb_build_object('tipo', 'cuenta', 'concepto', format('Cobro remesa %s', v_r.code), 'lineas', v_lineas),
    'seguro', format('Es el abono de la remesa de recibos %s: %s.', v_r.code, public.conta_euros_exactos(v_suma)), '[]'::jsonb, 'persona', null);
  select id into v_match from public.bank_match where movement_id = p_movement and status = 'vivo';
  for v_l in select l.id, l.invoice_id, l.amount from public.conta_cobro_remesa_linea l where l.id = any(v_ids) loop
    insert into public.bank_match_item (account_id, match_id, customer_invoice_id, amount, marked_by_bank)
    values (v_cuenta, v_match, v_l.invoice_id, v_l.amount, true);
    update public.conta_cobro_remesa_linea set bank_match_id = v_match where id = v_l.id;
    if (select pendiente from public.conta_factura_cobro where invoice_id = v_l.invoice_id) < 0.005 then v_cobradas := v_cobradas + 1; end if;
    v_n := v_n + 1;
  end loop;
  -- El disparador del casado los apunta como transferencia salvo que el concepto diga «recibo»: son recibos.
  update public.customer_invoice_payment set method = 'direct_debit' where bank_match_id = v_match;
  perform public._pc01e3_evento(v_cuenta, p_remesa, null, format('Llega el abono del %s en el banco: %s %s, %s %s.',
    to_char(v_m.op_date, 'DD/MM/YYYY'), v_n, case when v_n = 1 then 'recibo cobrado' else 'recibos cobrados' end,
    v_cobradas, case when v_cobradas = 1 then 'factura cobrada' else 'facturas cobradas' end));
  return jsonb_build_object('casado', v_match, 'recibos', v_n, 'cobradas', v_cobradas,
    'frase', format('Casado con la remesa %s: %s %s, %s. %s %s. Un recibo se puede devolver durante 8 semanas: si llega alguno, se casa con su recibo.',
      v_r.code, v_n, case when v_n = 1 then 'recibo' else 'recibos' end, public.conta_euros_exactos(v_suma),
      v_cobradas, case when v_cobradas = 1 then 'factura queda cobrada' else 'facturas quedan cobradas' end));
end $$;


--
-- Name: FUNCTION conta_remesa_cobros_casar(p_movement uuid, p_remesa uuid, p_lineas uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_remesa_cobros_casar(p_movement uuid, p_remesa uuid, p_lineas uuid[]) IS 'PC01 · E3 · Casa el abono del banco con una remesa de recibos (entera o los recibos que abona): un asiento (572 contra las 430) y las facturas cobradas. Deshacer el casado lo devuelve todo.';


--
-- Name: conta_remesa_cobros_crear(uuid, uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_cobros_crear(p_company uuid, p_treasury uuid, p_fecha date, p_facturas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid := public._pc01e3_empresa(p_company); v_t public.treasury_account; v_r uuid; v_code text;
  v_f jsonb; v_ci public.customer_invoice; v_nombre text; v_pend numeric; v_imp numeric; v_forma text; v_m record; v_seq text;
  v_n int := 0; v_total numeric := 0; v_vistas uuid[] := '{}'; v_primeros int := 0;
begin
  select * into v_t from public.treasury_account where id = p_treasury and company_id = p_company and is_active;
  if v_t.id is null then raise exception 'Esa cuenta del banco no es de la empresa.' using errcode = '23514'; end if;
  if public._pc01e2_iban(v_t.iban) is null then raise exception 'La cuenta «%» no tiene IBAN: el banco no sabría dónde abonar los recibos.', v_t.name using errcode = '23514'; end if;
  if public._pc01e3_identificador_acreedor((select tax_id from public.company where id = p_company), v_t.sepa_suffix) is null then
    raise exception 'La empresa no tiene un NIF que valga: sin él no hay identificador de acreedor para los recibos.' using errcode = '23514';
  end if;
  if p_fecha is null then raise exception 'Falta el día del cargo.' using errcode = '22023'; end if;
  if p_fecha <= public.conta_hoy() then raise exception 'El cargo tiene que ser como pronto mañana: el banco necesita el fichero el día antes.' using errcode = '22023'; end if;
  if jsonb_typeof(p_facturas) <> 'array' or jsonb_array_length(p_facturas) = 0 then raise exception 'Elige al menos una factura.' using errcode = '22023'; end if;
  v_code := public._pc01e3_codigo(p_company, p_fecha);
  insert into public.conta_cobro_remesa (account_id, company_id, code, treasury_account_id, charge_date, created_by, created_by_name)
  values (v_cuenta, p_company, v_code, p_treasury, p_fecha, auth.uid(), coalesce(public.conta_nombre_actor(), 'Sumied'))
  returning id into v_r;
  for v_f in select * from jsonb_array_elements(p_facturas) loop
    select * into v_ci from public.customer_invoice where id = (v_f->>'id')::uuid and account_id = v_cuenta and company_id = p_company for update;
    if v_ci.id is null then raise exception 'Esa factura no es de la empresa.' using errcode = '23514'; end if;
    if v_ci.id = any(v_vistas) then raise exception 'La factura % está dos veces.', coalesce(v_ci.number_text, '') using errcode = '23514'; end if;
    v_vistas := v_vistas || v_ci.id;
    select name into v_nombre from public.party where id = v_ci.party_id;
    if v_ci.status <> 'emitida' then raise exception 'La factura % no está emitida (está %).', coalesce(v_ci.number_text, ''), v_ci.status using errcode = '23514'; end if;
    if public.conta_factura_es_de_plataforma(v_ci.id) then raise exception 'La factura % la paga una plataforma: se cobra en Liquidaciones.', coalesce(v_ci.number_text, '') using errcode = '23514'; end if;
    v_forma := public._pc01e3_forma(v_ci.id);
    if v_forma is distinct from 'direct_debit' then
      raise exception 'La factura % de % no se cobra por domiciliación (%): no va en una remesa de recibos.', coalesce(v_ci.number_text, ''), coalesce(v_nombre, 'su cliente'),
        case v_forma when 'transfer' then 'paga por transferencia' when 'card' then 'paga con tarjeta' when 'cash' then 'paga en efectivo' when 'prepaid' then 'paga del saldo prepago' else 'no dice cómo paga' end
        using errcode = '23514';
    end if;
    select * into v_m from public._pc01e3_mandato(v_ci.party_id);
    if v_m.ok is not true then
      raise exception '% paga por domiciliación y no tiene mandato firmado: envíaselo para firmar antes de pasarle el recibo.', coalesce(v_nombre, 'Su cliente') using errcode = '23514';
    end if;
    if public._pc01e3_cuenta_cliente(p_company, v_ci.party_id) is null then
      raise exception '% no tiene su cuenta de cliente (430) en el plan: sin ella el cobro no tendría asiento.', coalesce(v_nombre, 'Su cliente') using errcode = '23514';
    end if;
    select pendiente into v_pend from public.conta_factura_cobro where invoice_id = v_ci.id;
    v_pend := coalesce(v_pend, 0) - public._pc01e3_en_remesa(v_ci.id);
    v_imp := coalesce(nullif(v_f->>'importe', '')::numeric, v_pend);
    if v_imp <= 0 or v_imp > v_pend + 0.005 then
      raise exception 'La factura % tiene pendientes % sin remesa: no se le pueden cobrar %.', coalesce(v_ci.number_text, ''),
        public.conta_euros_exactos(greatest(v_pend, 0)), public.conta_euros_exactos(v_imp) using errcode = '23514';
    end if;
    -- Primer cobro con este mandato (FRST) si ningún recibo suyo ha ido ya al banco; si no, RCUR.
    v_seq := case when exists (select 1 from public.conta_cobro_remesa_linea_estado l join public.conta_cobro_remesa r on r.id = l.remesa_id
                                where l.party_id = v_ci.party_id and l.mandate_ref = v_m.ref and l.estado <> 'sacada' and r.file_at is not null)
                  then 'RCUR' else 'FRST' end;
    if v_seq = 'FRST' then v_primeros := v_primeros + 1; end if;
    insert into public.conta_cobro_remesa_linea (account_id, company_id, remesa_id, invoice_id, party_id, amount, iban, mandate_ref, mandate_date, seq)
    values (v_cuenta, p_company, v_r, v_ci.id, v_ci.party_id, v_imp, v_m.iban, v_m.ref, v_m.firmado, v_seq);
    v_n := v_n + 1; v_total := v_total + v_imp;
  end loop;
  perform public._pc01e3_evento(v_cuenta, v_r, null, format('Prepara la remesa con %s %s por %s, a %s, con cargo el %s.',
    v_n, case when v_n = 1 then 'recibo' else 'recibos' end, public.conta_euros_exactos(v_total), v_t.name, to_char(p_fecha, 'DD/MM/YYYY')));
  return jsonb_build_object('remesa', v_r, 'codigo', v_code, 'recibos', v_n, 'total', v_total, 'primeros', v_primeros,
    'frase', format('Remesa %s preparada: %s %s, %s, con cargo el %s. Descarga el fichero y súbelo a la banca de %s.', v_code, v_n,
      case when v_n = 1 then 'recibo' else 'recibos' end, public.conta_euros_exactos(v_total), to_char(p_fecha, 'DD/MM'), v_t.name));
end $$;


--
-- Name: FUNCTION conta_remesa_cobros_crear(p_company uuid, p_treasury uuid, p_fecha date, p_facturas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_remesa_cobros_crear(p_company uuid, p_treasury uuid, p_fecha date, p_facturas jsonb) IS 'PC01 · E3 · «Cobrar por remesa»: prepara la remesa de recibos domiciliados. Para sin crear nada si una factura no se puede cobrar por remesa, y dice por qué.';


--
-- Name: conta_remesa_cobros_descargada(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_cobros_descargada(p_remesa uuid, p_sha256 text, p_recibos integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_r public.conta_cobro_remesa_estado; v_t text;
begin
  select * into v_r from public.conta_cobro_remesa_estado where id = p_remesa;
  if v_r.id is null then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  perform public._pc01e3_empresa(v_r.company_id);
  if coalesce(p_sha256, '') !~ '^[0-9a-f]{64}$' then raise exception 'Falta la huella del fichero.' using errcode = '22023'; end if;
  update public.conta_cobro_remesa set file_sha256 = p_sha256, file_at = coalesce(file_at, now()), file_by = coalesce(file_by, auth.uid()),
         file_by_name = coalesce(file_by_name, public.conta_nombre_actor(), 'Sumied') where id = p_remesa;
  select name into v_t from public.treasury_account where id = v_r.treasury_account_id;
  perform public._pc01e3_evento(v_r.account_id, p_remesa, null, format('Descarga el fichero para el banco: %s %s, %s (huella %s).',
    p_recibos, case when p_recibos = 1 then 'recibo' else 'recibos' end, public.conta_euros_exactos(v_r.por_abonar), left(p_sha256, 8)));
  return jsonb_build_object('frase', format('Fichero de la remesa %s descargado: %s %s. Súbelo a la banca de %s antes del %s; cuando llegue el abono, lo casas en Bancos y las facturas quedan cobradas.',
    v_r.code, p_recibos, case when p_recibos = 1 then 'recibo' else 'recibos' end, coalesce(v_t, 'tu banco'), to_char(v_r.charge_date, 'DD/MM')));
end $_$;


--
-- Name: conta_remesa_cobros_ficha(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_cobros_ficha(p_remesa uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_r public.conta_cobro_remesa_estado; v_t public.treasury_account; v_c public.company;
begin
  select * into v_r from public.conta_cobro_remesa_estado where id = p_remesa;
  if v_r.id is null then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  if not public.belongs_to_account(v_r.account_id) then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  select * into v_t from public.treasury_account where id = v_r.treasury_account_id;
  select * into v_c from public.company where id = v_r.company_id;
  return jsonb_build_object(
    'id', v_r.id, 'codigo', v_r.code, 'cargo', v_r.charge_date, 'estado', v_r.estado, 'total', v_r.total, 'cobrado', v_r.cobrado,
    'por_abonar', v_r.por_abonar, 'recibos_vivos', v_r.vivas, 'cobrados', v_r.cobrados, 'devueltos', v_r.devueltos,
    'abonada_el', v_r.abonada_el, 'plazo_hasta', v_r.plazo_hasta,
    'fichero_at', v_r.file_at, 'fichero_por', v_r.file_by_name, 'creada', v_r.created_at, 'creada_por', v_r.created_by_name,
    'empresa', coalesce(nullif(v_c.trade_name, ''), v_c.legal_name),
    'acreedor', public._pc01e3_identificador_acreedor(v_c.tax_id, v_t.sepa_suffix),
    'banco', jsonb_build_object('id', v_t.id, 'nombre', v_t.name, 'iban4', right(public._pc01e2_iban(v_t.iban), 4), 'cuenta', public._bank_cuenta_572(v_t.id)),
    'cuenta_gastos', public._pc01e3_cuenta_gastos(v_r.company_id),
    'recibos', coalesce((select jsonb_agg(jsonb_build_object(
        'id', l.id, 'factura_id', l.invoice_id, 'numero', ci.number_text, 'fecha', ci.issue_date, 'importe', l.amount, 'estado', l.estado,
        'cliente', p.name, 'cliente_id', l.party_id, 'cuenta', public._pc01e3_cuenta_cliente(v_r.company_id, l.party_id),
        'iban4', right(l.iban, 4), 'iban_pais', left(l.iban, 2), 'mandato', l.mandate_ref, 'firmado', l.mandate_date, 'primero', l.seq = 'FRST',
        'abonado', l.abonado_el, 'devuelto', l.devuelto_el, 'motivo', l.return_reason, 'gastos', l.return_fee,
        -- La factura aún por cobrar (para «Pasar el devuelto en la próxima remesa»).
        'pendiente', (select pendiente from public.conta_factura_cobro where invoice_id = l.invoice_id),
        'mandato_ficha', (select jsonb_build_object('ref', m.ref, 'firmado', m.signed_at, 'como', 'enlace', 'firmante', m.signed_name, 'token', m.token)
                            from public.conta_mandato m where m.party_id = l.party_id and m.company_id = v_r.company_id and m.ref = l.mandate_ref and m.status = 'firmado' limit 1),
        'ultimo_cobro', (select jsonb_build_object('fecha', x.abonado_el, 'estado', x.estado) from public.conta_cobro_remesa_linea_estado x
                          where x.party_id = l.party_id and x.mandate_ref = l.mandate_ref and x.estado in ('cobrado', 'devuelto') and x.id <> l.id
                          order by x.abonado_el desc nulls last limit 1))
        order by p.name, ci.issue_date)
      from public.conta_cobro_remesa_linea_estado l
      join public.customer_invoice ci on ci.id = l.invoice_id
      left join public.party p on p.id = l.party_id
     where l.remesa_id = p_remesa and l.estado <> 'sacada'), '[]'::jsonb),
    'historial', coalesce((select jsonb_agg(jsonb_build_object('at', e.at, 'por', e.by_name, 'texto', e.texto) order by e.at)
                            from public.conta_cobro_remesa_evento e where e.remesa_id = p_remesa), '[]'::jsonb));
end $$;


--
-- Name: conta_remesa_cobros_fichero_datos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_cobros_fichero_datos(p_remesa uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_r public.conta_cobro_remesa_estado; v_c public.company; v_t public.treasury_account;
begin
  select * into v_r from public.conta_cobro_remesa_estado where id = p_remesa;
  if v_r.id is null then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  perform public._pc01e3_empresa(v_r.company_id);
  if v_r.pendientes = 0 then raise exception 'Esta remesa no tiene recibos esperando el abono.' using errcode = '23514'; end if;
  select * into v_c from public.company where id = v_r.company_id;
  select * into v_t from public.treasury_account where id = v_r.treasury_account_id;
  return jsonb_build_object(
    'codigo', v_r.code, 'fecha_cargo', v_r.charge_date, 'creada', v_r.created_at,
    'acreedor', jsonb_build_object('nombre', coalesce(nullif(v_c.legal_name, ''), v_c.trade_name), 'nif', v_c.tax_id,
                                   'iban', public._pc01e2_iban(v_t.iban), 'bic', nullif(upper(trim(coalesce(v_t.bic, ''))), ''),
                                   'sufijo', coalesce(v_t.sepa_suffix, '000')),
    'recibos', coalesce((select jsonb_agg(jsonb_build_object(
        'id', l.id, 'importe', l.amount, 'iban', l.iban, 'bic', null, 'nombre', coalesce(nullif(cf.legal_name, ''), p.name),
        'mandato', l.mandate_ref, 'firmado', l.mandate_date, 'primero', l.seq = 'FRST',
        'factura', ci.number_text, 'fecha_factura', ci.issue_date) order by p.name, ci.issue_date)
      from public.conta_cobro_remesa_linea_estado l
      join public.customer_invoice ci on ci.id = l.invoice_id
      left join public.party p on p.id = l.party_id
      left join public.customer_fiscal cf on cf.party_id = l.party_id
     where l.remesa_id = p_remesa and l.estado = 'pendiente'), '[]'::jsonb));
end $$;


--
-- Name: conta_remesa_cobros_linea_sacar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_cobros_linea_sacar(p_linea uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.conta_cobro_remesa_linea_estado; v_r public.conta_cobro_remesa; v_cuenta uuid; v_num text;
begin
  select * into v from public.conta_cobro_remesa_linea_estado where id = p_linea;
  if v.id is null then raise exception 'Ese recibo no existe.' using errcode = 'P0002'; end if;
  v_cuenta := public._pc01e3_empresa(v.company_id);
  select * into v_r from public.conta_cobro_remesa where id = v.remesa_id for update;
  if v.estado <> 'pendiente' then raise exception 'Ese recibo ya no está esperando (está %).', v.estado using errcode = '23514'; end if;
  if v_r.file_at is not null then raise exception 'El fichero de la remesa % ya se descargó: el banco lo tiene. Si no se cobra, llegará devuelto.', v_r.code using errcode = '23514'; end if;
  update public.conta_cobro_remesa_linea set removed_at = now(), removed_by_name = coalesce(public.conta_nombre_actor(), 'Sumied') where id = p_linea;
  select number_text into v_num from public.customer_invoice where id = v.invoice_id;
  perform public._pc01e3_evento(v_cuenta, v.remesa_id, p_linea, format('Saca de la remesa el recibo de la %s.', coalesce(v_num, 'factura')));
  return jsonb_build_object('frase', format('Recibo de la %s sacado de la remesa %s: vuelve a «Por cobrar».', coalesce(v_num, 'factura'), v_r.code));
end $$;


--
-- Name: conta_remesa_descargada(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_descargada(p_remesa uuid, p_sha256 text, p_pagos integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_r public.conta_pago_remesa_estado; v_t text;
begin
  select * into v_r from public.conta_pago_remesa_estado where id = p_remesa;
  if v_r.id is null then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  perform public._pc01e2_empresa(v_r.company_id);
  if v_r.por_confirmar > 0 then raise exception 'Queda un IBAN por confirmar.' using errcode = '23514'; end if;
  if coalesce(p_sha256, '') !~ '^[0-9a-f]{64}$' then raise exception 'Falta la huella del fichero.' using errcode = '22023'; end if;
  update public.conta_pago_remesa set file_sha256 = p_sha256, file_at = coalesce(file_at, now()), file_by = coalesce(file_by, auth.uid()),
         file_by_name = coalesce(file_by_name, public.conta_nombre_actor(), 'Sumied') where id = p_remesa;
  select name into v_t from public.treasury_account where id = v_r.treasury_account_id;
  perform public._pc01e2_evento(v_r.account_id, p_remesa, null, format('Descarga el fichero para el banco: %s %s, %s (huella %s).',
    p_pagos, case when p_pagos = 1 then 'pago' else 'pagos' end, public.conta_euros_exactos(v_r.por_cargar), left(p_sha256, 8)));
  return jsonb_build_object('frase', format('Fichero de la remesa %s descargado: %s %s. Súbelo a la banca de %s; cuando llegue el cargo, la casas en Bancos y las facturas quedan pagadas.',
    v_r.code, p_pagos, case when p_pagos = 1 then 'pago' else 'pagos' end, coalesce(v_t, 'tu banco')));
end $_$;


--
-- Name: conta_remesa_ficha(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_ficha(p_remesa uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb;
begin
  if not exists (select 1 from public.conta_pago_remesa where id = p_remesa and public.belongs_to_account(account_id)) then
    raise exception 'Esa remesa no existe o no es de tu cuenta.' using errcode = 'P0002';
  end if;
  select jsonb_build_object(
    'id', r.id, 'codigo', r.code, 'a_mano', r.kind = 'a_mano', 'fecha_pago', r.pay_date, 'estado', r.estado, 'total', r.total, 'por_cargar', r.por_cargar,
    'vivas', r.vivas, 'pagadas', r.pagadas, 'por_confirmar', r.por_confirmar, 'rechazadas', r.rechazadas,
    'fichero_at', r.file_at, 'fichero_por', r.file_by_name, 'creada', r.created_at, 'creada_por', r.created_by_name,
    -- Solo mientras el casado que lo validó siga vivo (deshacerlo anula ese asiento).
    'validado_solo', exists (select 1 from public.conta_pago_remesa_linea_estado x join public.bank_match b on b.id = x.bank_match_id
                              where x.remesa_id = r.id and x.estado = 'pagada' and b.journal_entry_id = r.validated_solo_entry),
    'banco', jsonb_build_object('id', t.id, 'nombre', t.name, 'iban4', right(public._pc01e2_iban(t.iban), 4), 'cuenta', public._bank_cuenta_572(t.id)),
    'pagos', coalesce((select jsonb_agg(jsonb_build_object(
        'id', l.id, 'factura_id', l.invoice_id, 'numero', si.invoice_number, 'vence', si.due_date, 'importe', l.amount,
        'proveedor', s.name, 'iban4', right(l.iban, 4), 'iban_pais', left(l.iban, 4), 'iban_estado', l.iban_check, 'iban_nota', l.iban_note,
        'confirmado_por', l.iban_confirmed_by_name, 'confirmado_at', l.iban_confirmed_at, 'estado', l.estado, 'motivo', l.reject_reason,
        'cuenta', public._pc01e2_cuenta_proveedor(r.company_id, l.supplier_id)) order by s.name, si.invoice_date)
      from public.conta_pago_remesa_linea_estado l join public.supplier_invoice si on si.id = l.invoice_id left join public.supplier s on s.id = l.supplier_id
     where l.remesa_id = r.id), '[]'::jsonb),
    'historial', coalesce((select jsonb_agg(jsonb_build_object('at', e.at, 'por', e.by_name, 'texto', e.texto) order by e.at, e.id)
      from public.conta_pago_remesa_evento e where e.remesa_id = r.id), '[]'::jsonb))
  into v
  from public.conta_pago_remesa_estado r
  join public.treasury_account t on t.id = r.treasury_account_id
  where r.id = p_remesa;
  return v;
end $$;


--
-- Name: conta_remesa_fichero_datos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_fichero_datos(p_remesa uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_r public.conta_pago_remesa_estado; v_c public.company; v_t public.treasury_account;
begin
  select * into v_r from public.conta_pago_remesa_estado where id = p_remesa;
  if v_r.id is null then raise exception 'Esa remesa no existe.' using errcode = 'P0002'; end if;
  perform public._pc01e2_empresa(v_r.company_id);
  if v_r.kind <> 'fichero' then raise exception 'Un pago a mano no lleva fichero.' using errcode = '23514'; end if;
  if v_r.por_confirmar > 0 then raise exception 'Antes de descargar el fichero, confirma el IBAN que ha cambiado (o saca esa factura de la remesa).' using errcode = '23514'; end if;
  if v_r.vivas = 0 then raise exception 'Esta remesa ya no tiene ningún pago.' using errcode = '23514'; end if;
  select * into v_c from public.company where id = v_r.company_id;
  select * into v_t from public.treasury_account where id = v_r.treasury_account_id;
  return jsonb_build_object(
    'codigo', v_r.code, 'fecha_pago', v_r.pay_date, 'creada', v_r.created_at,
    'ordenante', jsonb_build_object('nombre', coalesce(nullif(v_c.legal_name, ''), v_c.trade_name), 'nif', v_c.tax_id,
                                    'iban', public._pc01e2_iban(v_t.iban), 'bic', nullif(upper(trim(coalesce(v_t.bic, ''))), ''),
                                    'sufijo', coalesce(v_t.sepa_suffix, '000')),
    'pagos', coalesce((select jsonb_agg(jsonb_build_object(
        'id', l.id, 'importe', l.amount, 'iban', l.iban, 'bic', nullif(upper(trim(coalesce(s.bic, ''))), ''),
        'nombre', coalesce(nullif(s.legal_name, ''), s.name), 'factura', si.invoice_number, 'fecha_factura', si.invoice_date) order by s.name, si.invoice_date)
      from public.conta_pago_remesa_linea_estado l
      join public.supplier_invoice si on si.id = l.invoice_id
      left join public.supplier s on s.id = l.supplier_id
     where l.remesa_id = p_remesa and l.estado = 'pendiente'), '[]'::jsonb));
end $$;


--
-- Name: conta_remesa_iban_confirmar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_iban_confirmar(p_linea uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.conta_pago_remesa_linea_estado := public._pc01e2_linea(p_linea); v_s text;
begin
  -- Respuesta 7: también el de un primer pago (no para la remesa, pero sin confirmar su asiento no se valida solo).
  if not (v.estado = 'por_confirmar' or (v.estado = 'pendiente' and v.iban_check = 'primer_pago' and v.iban_confirmed_at is null)) then
    raise exception 'Ese IBAN no está esperando confirmación.' using errcode = '23514';
  end if;
  update public.conta_pago_remesa_linea set iban_confirmed_at = now(), iban_confirmed_by = auth.uid(),
         iban_confirmed_by_name = coalesce(public.conta_nombre_actor(), 'Sumied') where id = p_linea;
  -- PC01 · E2b · Si era el leído de una factura, queda confirmado en la ficha.
  update public.supplier set iban_unconfirmed_invoice_id = null
   where id = v.supplier_id and iban_unconfirmed_invoice_id is not null and public._pc01e2_iban(iban) = v.iban;
  select name into v_s from public.supplier where id = v.supplier_id;
  perform public._pc01e2_evento(v.account_id, v.remesa_id, p_linea, format('Confirma el IBAN ···· %s de %s.', right(v.iban, 4), coalesce(v_s, '—')));
  return jsonb_build_object('frase', format('IBAN de %s confirmado (···· %s). Queda apuntado quién y cuándo.', coalesce(v_s, 'su proveedor'), right(v.iban, 4)));
end $$;


--
-- Name: conta_remesa_linea_rechazada(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_linea_rechazada(p_linea uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.conta_pago_remesa_linea_estado := public._pc01e2_linea(p_linea); v_s text; v_num text;
begin
  if v.estado not in ('pendiente', 'por_confirmar') then raise exception 'Ese pago no está esperando el cargo.' using errcode = '23514'; end if;
  if coalesce(trim(p_motivo), '') = '' then raise exception 'Di el motivo que da el banco.' using errcode = '22023'; end if;
  update public.conta_pago_remesa_linea set rejected_at = now(), reject_reason = trim(p_motivo), rejected_by_name = coalesce(public.conta_nombre_actor(), 'Sumied') where id = p_linea;
  select s.name, si.invoice_number into v_s, v_num from public.supplier_invoice si left join public.supplier s on s.id = si.supplier_id where si.id = v.invoice_id;
  perform public._pc01e2_evento(v.account_id, v.remesa_id, p_linea, format('El banco rechaza el pago de %s a %s: %s. La factura %s vuelve a «Por pagar».',
    public.conta_euros_exactos(v.amount), coalesce(v_s, '—'), trim(p_motivo), coalesce(v_num, 'sin número')));
  return jsonb_build_object('frase', format('Rechazado: la factura %s de %s vuelve a «Por pagar» con el motivo «%s». Las demás siguen su curso.',
    coalesce(v_num, 'sin número'), coalesce(v_s, 'su proveedor'), trim(p_motivo)));
end $$;


--
-- Name: conta_remesa_linea_sacar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_linea_sacar(p_linea uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.conta_pago_remesa_linea_estado := public._pc01e2_linea(p_linea); v_r public.conta_pago_remesa; v_s text; v_num text;
begin
  select * into v_r from public.conta_pago_remesa where id = v.remesa_id;
  if v.estado not in ('pendiente', 'por_confirmar') then raise exception 'Ese pago ya no está esperando: no se puede sacar.' using errcode = '23514'; end if;
  if v_r.file_at is not null then raise exception 'El fichero de esta remesa ya se descargó: si el banco no lo paga, di que lo ha rechazado.' using errcode = '23514'; end if;
  update public.conta_pago_remesa_linea set removed_at = now(), removed_by_name = coalesce(public.conta_nombre_actor(), 'Sumied') where id = p_linea;
  select s.name, si.invoice_number into v_s, v_num from public.supplier_invoice si left join public.supplier s on s.id = si.supplier_id where si.id = v.invoice_id;
  perform public._pc01e2_evento(v.account_id, v.remesa_id, p_linea, format('Saca de la remesa la factura %s de %s.', coalesce(v_num, 'sin número'), coalesce(v_s, '—')));
  return jsonb_build_object('frase', format('Factura %s de %s fuera de la remesa: vuelve a «Por pagar».', coalesce(v_num, 'sin número'), coalesce(v_s, 'su proveedor')));
end $$;


--
-- Name: conta_remesa_pagos_crear(uuid, uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesa_pagos_crear(p_company uuid, p_treasury uuid, p_fecha date, p_facturas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid := public._pc01e2_empresa(p_company); v_t public.treasury_account; v_r uuid; v_code text;
  v_f jsonb; v_inv public.supplier_invoice; v_s public.supplier; v_pend numeric; v_imp numeric; v_iban text; v_metodo text;
  v_chk record; v_l uuid; v_n int := 0; v_total numeric := 0; v_conf int := 0; v_vistas uuid[] := '{}';
begin
  select * into v_t from public.treasury_account where id = p_treasury and company_id = p_company and is_active;
  if v_t.id is null then raise exception 'Esa cuenta del banco no es de la empresa.' using errcode = '23514'; end if;
  if public._pc01e2_iban(v_t.iban) is null then raise exception 'La cuenta «%» no tiene IBAN: el banco no sabría de dónde sacar el dinero.', v_t.name using errcode = '23514'; end if;
  if p_fecha is null then raise exception 'Falta la fecha de pago.' using errcode = '22023'; end if;
  if p_fecha < public.conta_hoy() then raise exception 'La fecha de pago no puede ser anterior a hoy.' using errcode = '22023'; end if;
  if jsonb_typeof(p_facturas) <> 'array' or jsonb_array_length(p_facturas) = 0 then raise exception 'Elige al menos una factura.' using errcode = '22023'; end if;
  v_code := public._pc01e2_codigo(p_company, p_fecha);
  insert into public.conta_pago_remesa (account_id, company_id, code, kind, treasury_account_id, pay_date, created_by, created_by_name)
  values (v_cuenta, p_company, v_code, 'fichero', p_treasury, p_fecha, auth.uid(), coalesce(public.conta_nombre_actor(), 'Sumied'))
  returning id into v_r;
  for v_f in select * from jsonb_array_elements(p_facturas) loop
    select * into v_inv from public.supplier_invoice where id = (v_f->>'id')::uuid and account_id = v_cuenta for update;
    if v_inv.id is null or coalesce(v_inv.company_id, p_company) <> p_company then raise exception 'Esa factura no es de la empresa.' using errcode = '23514'; end if;
    if v_inv.id = any(v_vistas) then raise exception 'La factura % está dos veces.', coalesce(v_inv.invoice_number, '') using errcode = '23514'; end if;
    v_vistas := v_vistas || v_inv.id;
    if v_inv.status <> 'aprobada' then raise exception 'La factura % no está por pagar (está %).', coalesce(v_inv.invoice_number, ''), v_inv.status using errcode = '23514'; end if;
    select * into v_s from public.supplier where id = v_inv.supplier_id;
    v_metodo := coalesce(v_inv.payment_method, v_s.payment_method);
    if v_metodo in ('direct_debit', 'card', 'prepaid', 'cash') then
      raise exception 'La factura % de % no se paga por remesa: %.', coalesce(v_inv.invoice_number, ''), coalesce(v_s.name, 'su proveedor'),
        case v_metodo when 'direct_debit' then 'la paga el banco solo (domiciliada)' when 'card' then 'se paga con tarjeta' when 'prepaid' then 'se paga del saldo prepago' else 'se paga en efectivo' end
        using errcode = '23514';
    end if;
    v_iban := public._pc01e2_iban(v_s.iban);
    if v_iban is null then raise exception '% no tiene IBAN en su ficha: pónselo con «Poner IBAN» en la barra de Pagar.', coalesce(v_s.name, 'Su proveedor') using errcode = '23514'; end if;
    -- PC01 · E2b · La factura trae otro IBAN y nadie ha decidido: antes paraba al casar el cargo (freno de la C01b); ahora, aquí.
    if public._pc01e2_iban(v_inv.read_iban) is not null and v_inv.iban_decision is null and public._pc01e2_iban(v_inv.read_iban) <> v_iban then
      raise exception 'La factura % trae otro IBAN (···· %) que el de la ficha de % (···· %): decide en su ficha si es el nuevo antes de pagarla.',
        coalesce(v_inv.invoice_number, ''), right(public._pc01e2_iban(v_inv.read_iban), 4), v_s.name, right(v_iban, 4) using errcode = '23514';
    end if;
    if public._pc01e2_cuenta_proveedor(p_company, v_s.id) is null then
      raise exception '% no tiene su cuenta de proveedor (400) en el plan: sin ella el pago no tendría asiento.', v_s.name using errcode = '23514';
    end if;
    select pendiente into v_pend from public.conta_recibida_pago where invoice_id = v_inv.id;
    v_pend := coalesce(v_pend, 0) - public._pc01e2_en_remesa(v_inv.id);
    v_imp := coalesce(nullif(v_f->>'importe', '')::numeric, v_pend);
    if v_imp <= 0 or v_imp > v_pend + 0.005 then
      raise exception 'La factura % tiene pendientes % sin remesa: no se le pueden pagar %.', coalesce(v_inv.invoice_number, ''),
        public.conta_euros_exactos(greatest(v_pend, 0)), public.conta_euros_exactos(v_imp) using errcode = '23514';
    end if;
    select * into v_chk from public._pc01e2_iban_como_esta(v_s.id, v_iban);
    insert into public.conta_pago_remesa_linea (account_id, company_id, remesa_id, invoice_id, supplier_id, amount, iban, iban_check, iban_note)
    values (v_cuenta, p_company, v_r, v_inv.id, v_s.id, v_imp, v_iban, v_chk.estado, v_chk.nota) returning id into v_l;
    if v_chk.estado = 'cambiado' then
      v_conf := v_conf + 1;
      perform public._pc01e2_evento(v_cuenta, v_r, v_l, format('El IBAN de %s no se ha confirmado: %s Se para hasta confirmarlo.', v_s.name, v_chk.nota));
    end if;
    v_n := v_n + 1; v_total := v_total + v_imp;
  end loop;
  perform public._pc01e2_evento(v_cuenta, v_r, null, format('Prepara la remesa con %s %s por %s, desde %s, para pagar el %s.',
    v_n, case when v_n = 1 then 'factura' else 'facturas' end, public.conta_euros_exactos(v_total), v_t.name, to_char(p_fecha, 'DD/MM/YYYY')));
  return jsonb_build_object('remesa', v_r, 'codigo', v_code, 'pagos', v_n, 'total', v_total, 'por_confirmar', v_conf,
    'frase', format('Remesa %s preparada: %s %s, %s.%s', v_code, v_n, case when v_n = 1 then 'pago' else 'pagos' end, public.conta_euros_exactos(v_total),
      case when v_conf = 0 then ' Ya puedes descargar el fichero para el banco.'
           when v_conf = 1 then ' Antes de descargar el fichero, confirma 1 IBAN que ha cambiado.'
           else format(' Antes de descargar el fichero, confirma %s IBAN que han cambiado.', v_conf) end));
end $$;


--
-- Name: FUNCTION conta_remesa_pagos_crear(p_company uuid, p_treasury uuid, p_fecha date, p_facturas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_remesa_pagos_crear(p_company uuid, p_treasury uuid, p_fecha date, p_facturas jsonb) IS 'PC01 · E2 · «Pagar N facturas»: prepara la remesa de transferencias. Para sin crear nada si una factura no se puede pagar por remesa, y dice por qué.';


--
-- Name: conta_remesas_cobros_lista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesas_cobros_lista(p_company uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', r.id, 'codigo', r.code, 'cargo', r.charge_date, 'estado', r.estado, 'total', r.total, 'cobrado', r.cobrado,
           'recibos', r.vivas, 'cobrados', r.cobrados, 'devueltos', r.devueltos, 'plazo_hasta', r.plazo_hasta,
           'banco', (select t.name from public.treasury_account t where t.id = r.treasury_account_id)) order by r.charge_date desc, r.code desc), '[]'::jsonb)
    from public.conta_cobro_remesa_estado r where r.company_id = p_company
$$;


--
-- Name: conta_remesas_lista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesas_lista(p_company uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'codigo', r.code, 'a_mano', r.kind = 'a_mano', 'fecha_pago', r.pay_date, 'estado', r.estado,
           'total', r.total, 'vivas', r.vivas, 'pagadas', r.pagadas, 'por_confirmar', r.por_confirmar, 'banco', t.name) order by r.created_at desc), '[]'::jsonb)
    from public.conta_pago_remesa_estado r join public.treasury_account t on t.id = r.treasury_account_id
   where r.company_id = p_company
$$;


