-- Name: conta_remesas_para_casar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_remesas_para_casar(p_company uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', r.id, 'codigo', r.code, 'fecha', r.pay_date, 'a_mano', r.kind = 'a_mano', 'por_cargar', r.por_cargar,
           'pagos', (select jsonb_agg(jsonb_build_object('id', l.id, 'importe', l.amount, 'proveedor', s.name, 'factura', si.invoice_number) order by s.name)
                       from public.conta_pago_remesa_linea_estado l join public.supplier_invoice si on si.id = l.invoice_id left join public.supplier s on s.id = l.supplier_id
                      where l.remesa_id = r.id and l.estado = 'pendiente')) order by r.pay_date), '[]'::jsonb)
    from public.conta_pago_remesa_estado r
   where r.company_id = p_company and r.estado = 'en_banco' and r.por_cargar > 0
$$;


--
-- Name: conta_resultado_por_local(uuid, date, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_resultado_por_local(p_company uuid, p_desde date, p_hasta date, p_repartir boolean DEFAULT false) RETURNS TABLE(location_id uuid, brand_id uuid, ingresos numeric, gastos numeric, resultado numeric, nota text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
-- Las columnas de salida (location_id, ingresos, gastos…) se llaman igual que
-- las de _c04_res: dentro de las consultas manda la columna. Sin esto, la rama
-- del reparto fallaba con 42702 «ingresos is ambiguous» (e2e 123, 07/10).
#variable_conflict use_column
declare v_suma numeric;
begin
  create temp table if not exists _c04_res (location_id uuid, brand_id uuid, ingresos numeric, gastos numeric) on commit drop;
  truncate _c04_res;
  insert into _c04_res
  select l.location_id, l.brand_id,
         sum(case when l.template_code like '7%' then l.credit - l.debit else 0 end),
         sum(case when l.template_code like '6%' then l.debit - l.credit else 0 end)
    from public.journal_ledger l
   where l.company_id = p_company and l.entry_date between p_desde and p_hasta
     and (l.template_code like '6%' or l.template_code like '7%')
     -- C05: la regularización (6 y 7 → 129) y el cierre no son resultado del
     -- periodo; con ellos dentro, el resultado del año saldría 0.
     and l.source_type <> 'closing'
   group by l.location_id, l.brand_id;

  if p_repartir then
    select sum(r.pct) into v_suma from public.allocation_rule r
     where r.company_id = p_company and p_hasta between r.valid_from and coalesce(r.valid_to, p_hasta);
    if v_suma = 100 then
      -- Lo común (sin local) se reparte por la regla; el último local se lleva el
      -- redondeo para que la suma sea exacta.
      insert into _c04_res
      select x.location_id, null, x.ing, x.gas from (
        select r.location_id,
               case when row_number() over (order by r.pct, r.location_id desc) = count(*) over ()
                    then c.ingresos - coalesce(sum(round(c.ingresos * r.pct / 100, 2)) over (order by r.pct, r.location_id desc rows between unbounded preceding and 1 preceding), 0)
                    else round(c.ingresos * r.pct / 100, 2) end as ing,
               case when row_number() over (order by r.pct, r.location_id desc) = count(*) over ()
                    then c.gastos - coalesce(sum(round(c.gastos * r.pct / 100, 2)) over (order by r.pct, r.location_id desc rows between unbounded preceding and 1 preceding), 0)
                    else round(c.gastos * r.pct / 100, 2) end as gas
          from public.allocation_rule r
          cross join (select coalesce(sum(ingresos), 0) ingresos, coalesce(sum(gastos), 0) gastos from _c04_res where location_id is null) c
         where r.company_id = p_company and p_hasta between r.valid_from and coalesce(r.valid_to, p_hasta)) x;
      delete from _c04_res where location_id is null;
    end if;
  end if;

  return query
  select r.location_id, r.brand_id, sum(r.ingresos), sum(r.gastos), sum(r.ingresos) - sum(r.gastos),
         case when r.location_id is null and p_repartir then 'Común sin repartir: la regla de reparto no suma 100 % en esas fechas.'
              when r.location_id is null then 'Común: el informe puede repartirlo con tu regla de reparto.' end
    from _c04_res r
   group by r.location_id, r.brand_id
   order by r.location_id nulls last, r.brand_id nulls last;
end $$;


--
-- Name: FUNCTION conta_resultado_por_local(p_company uuid, p_desde date, p_hasta date, p_repartir boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_resultado_por_local(p_company uuid, p_desde date, p_hasta date, p_repartir boolean) IS 'C04. Ingresos (grupo 7) menos gastos (grupo 6) por local y marca en un periodo. Lo común sale aparte o, con p_repartir, por allocation_rule. La suma de las filas es el resultado total.';


--
-- Name: conta_resumen_ventas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_resumen_ventas(p_entry uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry;
  v_d public.sales_day_summary;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null or not (public.belongs_to_account(v_e.account_id) or auth.role() = 'service_role') then
    raise exception 'Ese asiento no está.' using errcode = 'P0002';
  end if;
  select * into v_d from public.sales_day_summary
   where entry_id = v_e.id and account_id = v_e.account_id and company_id = v_e.company_id;
  if v_d.id is null or v_d.channel_id is null then
    raise exception 'Ese asiento no es de las ventas de una plataforma: no lleva resumen de ventas.' using errcode = '22023';
  end if;
  return jsonb_build_object(
    'id', v_e.id, 'account_id', v_e.account_id, 'company_id', v_e.company_id,
    'estado', v_e.status, 'serie', v_e.series, 'numero', v_e.number,
    'fecha', v_d.sales_day, 'validado_en', v_e.validated_at,
    'empresa', (select jsonb_build_object('nombre', c.legal_name, 'nif', c.tax_id)
                  from public.company c where c.id = v_e.company_id and c.account_id = v_e.account_id),
    'local', (select jsonb_build_object('id', l.id, 'nombre', l.name)
                from public.locations l where l.id = v_d.location_id and l.account_id = v_e.account_id),
    'canal', (select jsonb_build_object('id', ch.id, 'slug', ch.slug, 'nombre', ch.name)
                from public.sales_channel ch where ch.id = v_d.channel_id and ch.account_id = v_e.account_id),
    'pedidos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'hora', to_char(s.sold_at at time zone 'Europe/Madrid', 'HH24:MI'),
               'codigo', coalesce(s.platform_order_code, left(s.id::text, 8)),
               'marca', b.name,
               -- V01: con otro importe en su cierre (conta_cierre_ajuste), ese; la base y la cuota en proporción.
               'total', coalesce(a.importe, s.total),
               'base', case when a.importe is null then s.taxable_base when s.taxable_base is null or coalesce(s.total, 0) = 0 then null
                            else round(s.taxable_base * a.importe / s.total, 2) end,
               'cuota', case when a.importe is null then s.tax when s.taxable_base is null or coalesce(s.total, 0) = 0 then null
                             else a.importe - round(s.taxable_base * a.importe / s.total, 2) end,
               -- C06b (16/10): el descuento y el envío, y qué se hizo con el envío (conta_cargos_de_pedidos).
               'descuento', coalesce(c.descuento, 0), 'envio', coalesce(c.envio, 0), 'clase', coalesce(c.clase, 'ninguno')) order by s.sold_at, s.id)
        from public.sale s left join public.brand b on b.id = s.brand_id and b.account_id = s.account_id
        left join public.conta_cargos_de_pedidos(v_e.account_id, v_d.sale_ids) c on c.id = s.id
        left join public.conta_cierre_ajuste a on a.company_id = v_e.company_id and a.sale_id = s.id and not a.quitado
       where s.id = any (v_d.sale_ids) and s.account_id = v_e.account_id), '[]'::jsonb),
    'lineas', coalesce((
      select jsonb_agg(jsonb_build_object(
               'cuenta', a.code, 'debe', l.debit, 'haber', l.credit, 'marca', b.name,
               'tipoIva', t.rate, 'documento', l.document_ref,
               -- C06b (16/10): si la línea es la de promociones o la de envíos de su plataforma.
               'papel', (select v.papel from public.conta_ventas_canal_cuenta v
                          where v.company_id = v_e.company_id and v.channel_id = v_d.channel_id and v.company_account_id = a.id)) order by l.position)
        from public.journal_line l
        join public.company_account a on a.id = l.company_account_id and a.company_id = v_e.company_id
        left join public.brand b on b.id = l.brand_id and b.account_id = v_e.account_id
        left join public.tax_rate t on t.id = l.tax_rate_id
       where l.entry_id = v_e.id and l.account_id = v_e.account_id), '[]'::jsonb),
    'documento', (
      select jsonb_build_object('id', x.id, 'ruta', x.storage_path, 'nombre', x.file_name, 'sha256', x.sha256,
                                'bytes', x.size_bytes, 'creado_en', x.created_at, 'creado_por', x.created_by_name)
        from public.journal_entry_document x
       where x.entry_id = v_e.id and x.account_id = v_e.account_id and x.kind = 'resumen_ventas'));
end $$;


--
-- Name: FUNCTION conta_resumen_ventas(p_entry uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_resumen_ventas(p_entry uuid) IS 'R15 · Lo que lleva el Resumen de ventas de un asiento de ventas de una plataforma: asiento, líneas, empresa, local, plataforma, pedidos y su documento si lo tiene. Solo para los de la cuenta.';


--
-- Name: conta_revolut_desconectar(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_revolut_desconectar(p_company uuid, p_quien uuid, p_quien_nombre text, p_desde_revolut boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v public.revolut_conexion; v_secretos integer; v_cuentas integer;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'Solo la función de Revolut desconecta.' using errcode = '42501'; end if;
  select * into v from public.revolut_conexion where company_id = p_company for update;
  if v.id is null then raise exception 'Esta empresa no tiene Revolut conectado.' using errcode = 'P0002'; end if;
  v_secretos := public._revolut_secretos_quitar(p_company);
  delete from public.bank_aggregator_link where company_id = p_company and provider = 'revolut';
  get diagnostics v_cuentas = row_count;
  update public.revolut_conexion
     set estado = case when p_desde_revolut then 'retirada' else 'desconectada' end,
         desconectada_at = now(), desconectada_por_nombre = nullif(trim(p_quien_nombre), ''),
         estado_oauth_huella = null, estado_oauth_at = null, permisos = null,
         last_error = case when p_desde_revolut then 'Revolut ya no acepta el permiso: se ha quitado el certificado en Revolut o ha caducado.' else last_error end
   where id = v.id;
  return jsonb_build_object('estado', case when p_desde_revolut then 'retirada' else 'desconectada' end, 'cuentas', v_cuentas, 'secretos', v_secretos, 'quien', p_quien);
end $$;


--
-- Name: FUNCTION conta_revolut_desconectar(p_company uuid, p_quien uuid, p_quien_nombre text, p_desde_revolut boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_revolut_desconectar(p_company uuid, p_quien uuid, p_quien_nombre text, p_desde_revolut boolean) IS 'B01 Revolut. Deja la empresa sin Revolut: borra sus secretos del Vault y sus cuentas conectadas (bank_aggregator_link). Lo que ya entró se queda. Desde Sumied: desconectada; desde Revolut (el permiso ya no vale): retirada.';


--
-- Name: conta_revolut_despertar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_revolut_despertar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_secreto text; v_url text;
begin
  if not exists (select 1 from public.revolut_conexion where estado = 'conectada') then return; end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  select rtrim(decrypted_secret, '/') into v_url from vault.decrypted_secrets
   where name = 'project_url' and decrypted_secret ~ '^https://[a-z0-9]+\.supabase\.co/?$';
  if v_secreto is null or v_url is null then
    raise exception 'Falta cron_secret o project_url en el Vault: no se puede despertar a conta-revolut-leer.' using errcode = '55000';
  end if;
  perform net.http_post(
    url := v_url || '/functions/v1/conta-revolut-leer',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := '{"por":"cron"}'::jsonb, timeout_milliseconds := 150000);
end $_$;


--
-- Name: FUNCTION conta_revolut_despertar(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_revolut_despertar() IS 'B01 Revolut · Cada hora (cron conta-revolut-despertar): si hay alguna empresa con Revolut conectado, llama a conta-revolut-leer. La dirección, de project_url en el Vault (W10). Si falta algo, falla (cron lo apunta como failed), no calla.';


--
-- Name: conta_revolut_secreto(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_revolut_secreto(p_company uuid, p_que text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare v text;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'Solo las funciones de Revolut leen sus secretos.' using errcode = '42501'; end if;
  select decrypted_secret into v from vault.decrypted_secrets where name = public._revolut_nombre_secreto(p_company, p_que);
  return v;
end $$;


--
-- Name: conta_revolut_secreto_poner(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_revolut_secreto_poner(p_company uuid, p_que text, p_valor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare v_nombre text := public._revolut_nombre_secreto(p_company, p_que); v_id uuid;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'Solo las funciones de Revolut guardan sus secretos.' using errcode = '42501'; end if;
  if coalesce(p_valor, '') = '' then raise exception 'Un secreto vacío no se guarda.' using errcode = '22023'; end if;
  select id into v_id from vault.secrets where name = v_nombre;
  if v_id is null then
    perform vault.create_secret(p_valor, v_nombre, 'B01 Revolut · ' || p_que);
  else
    perform vault.update_secret(v_id, p_valor, v_nombre, 'B01 Revolut · ' || p_que);
  end if;
end $$;


--
-- Name: conta_saldo_bancos(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_saldo_bancos(p_company uuid, p_hasta date) RETURNS TABLE(treasury_account_id uuid, nombre text, cuenta text, libro_validado numeric, libro_propuesto numeric, extracto_saldo numeric, extracto_hasta date, sin_casar numeric, sin_casar_n integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare v_acc uuid;
begin
  select c.account_id into v_acc from public.company c where c.id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;
  if p_hasta is null then
    raise exception 'Falta la fecha.' using errcode = '22023';
  end if;

  return query
  with s as (
    -- La misma vara que Inicio: conta_saldos_cuentas desde el día 1 del mes.
    select x.company_account_id,
           sum(x.inicial_debe - x.inicial_haber + x.apertura_debe - x.apertura_haber
               + x.periodo_debe - x.periodo_haber + x.regularizacion_debe - x.regularizacion_haber) as saldo
      from public.conta_saldos_cuentas(p_company, date_trunc('month', p_hasta)::date, p_hasta) x
     where x.code like '572%'
     group by x.company_account_id
  ), b as (
    select t.id, t.name, ca.id as ca_id, ca.code
      from public.treasury_account t
      left join lateral (select l.company_account_id from public.company_account_link l
                          where l.account_id = v_acc and l.company_id = p_company and l.entity = 'bank_account'
                            and l.role = 'principal' and l.entity_id = t.id::text
                          order by l.created_at limit 1) l on true
      left join public.company_account ca on ca.id = l.company_account_id and ca.account_id = v_acc and ca.company_id = p_company
     where t.account_id = v_acc and t.company_id = p_company and t.kind = 'bank' and t.is_active
  )
  select b.id, b.name, b.code,
         case when b.ca_id is null then null else round(coalesce(s.saldo, 0), 2) end,
         case when b.ca_id is null then null else round(coalesce((
           select sum(jl.debit - jl.credit) from public.journal_line jl join public.journal_entry e on e.id = jl.entry_id
            where jl.account_id = v_acc and jl.company_id = p_company and jl.company_account_id = b.ca_id
              and e.status = 'propuesto' and e.entry_date <= p_hasta and e.source_type <> 'closing'), 0), 2) end,
         st.closing_balance, st.period_to,
         round(coalesce(m.importe, 0), 2), coalesce(m.n, 0)::int
    from b
    left join s on s.company_account_id = b.ca_id
    left join lateral (select bs.closing_balance, bs.period_to from public.bank_statement bs
                        where bs.account_id = v_acc and bs.company_id = p_company and bs.treasury_account_id = b.id
                          and bs.period_to <= p_hasta and bs.closing_balance is not null
                        order by bs.period_to desc, bs.imported_at desc limit 1) st on true
    left join lateral (select sum(bm.amount) as importe, count(*) as n from public.bank_movement bm
                        where bm.account_id = v_acc and bm.company_id = p_company and bm.treasury_account_id = b.id
                          and bm.status not in ('casado', 'ignorado', 'antes_corte_sin_pareja') and not bm.before_cutover
                          and bm.op_date <= coalesce(st.period_to, p_hasta)) m on true
   order by b.code nulls last, b.name;
end $$;


--
-- Name: FUNCTION conta_saldo_bancos(p_company uuid, p_hasta date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_saldo_bancos(p_company uuid, p_hasta date) IS 'S02 · PR 3 (0490). Solo lee. Una fila por banco activo de la empresa: su 572, lo validado en ella (la vara de Inicio: conta_saldos_cuentas desde el día 1 del mes), lo propuesto aparte, el último extracto con saldo hasta la fecha y lo sin casar hasta la fecha del extracto. Inicio y Bancos leen la misma fila.';


--
-- Name: conta_saldos_cuentas(uuid, date, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_saldos_cuentas(p_company uuid, p_desde date, p_hasta date, p_por_local boolean DEFAULT false) RETURNS TABLE(company_account_id uuid, code text, name text, template_code text, location_id uuid, brand_id uuid, inicial_debe numeric, inicial_haber numeric, apertura_debe numeric, apertura_haber numeric, periodo_debe numeric, periodo_haber numeric, regularizacion_debe numeric, regularizacion_haber numeric, cierre_debe numeric, cierre_haber numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with ej as (
    select starts_on from public.fiscal_year where company_id = p_company and p_hasta between starts_on and ends_on limit 1
  ), cierre as (
    select c.regularization_entry_id r, c.closing_entry_id c, c.opening_entry_id o
      from public.fiscal_year_closing c where c.company_id = p_company
  ), l as (
    select l.*, case
             when l.source_type = 'opening' or l.entry_id in (select o from cierre) then 'apertura'
             when l.entry_id in (select r from cierre where r is not null) then 'regularizacion'
             when l.entry_id in (select c from cierre where c is not null) then 'cierre'
             when l.source_type = 'closing' then 'cierre'
             else 'normal' end as clase
      from public.journal_ledger l
     where l.company_id = p_company
       and l.entry_date between coalesce((select starts_on from ej), p_desde) and p_hasta
  )
  select l.company_account_id, l.account_code, l.account_name, l.template_code,
         case when p_por_local then l.location_id end, case when p_por_local then l.brand_id end,
         coalesce(sum(l.debit)  filter (where l.entry_date < p_desde and l.clase = 'normal'), 0),
         coalesce(sum(l.credit) filter (where l.entry_date < p_desde and l.clase = 'normal'), 0),
         coalesce(sum(l.debit)  filter (where l.clase = 'apertura'), 0),
         coalesce(sum(l.credit) filter (where l.clase = 'apertura'), 0),
         coalesce(sum(l.debit)  filter (where l.entry_date >= p_desde and l.clase = 'normal'), 0),
         coalesce(sum(l.credit) filter (where l.entry_date >= p_desde and l.clase = 'normal'), 0),
         coalesce(sum(l.debit)  filter (where l.clase = 'regularizacion'), 0),
         coalesce(sum(l.credit) filter (where l.clase = 'regularizacion'), 0),
         coalesce(sum(l.debit)  filter (where l.clase = 'cierre'), 0),
         coalesce(sum(l.credit) filter (where l.clase = 'cierre'), 0)
    from l
   group by 1, 2, 3, 4, 5, 6
   order by 2
$$;


--
-- Name: FUNCTION conta_saldos_cuentas(p_company uuid, p_desde date, p_hasta date, p_por_local boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_saldos_cuentas(p_company uuid, p_desde date, p_hasta date, p_por_local boolean) IS 'C05. Saldos de cada cuenta del ejercicio que contiene p_hasta, separados en inicial (antes de p_desde), apertura, periodo, regularización y cierre. Con la RLS de quien lee (journal_ledger es security_invoker).';


--
-- Name: conta_saldos_terceros(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_saldos_terceros(p_company uuid, p_hasta date) RETURNS TABLE(cuenta text, nombre text, party_id uuid, grupo text, saldo_deudor numeric, saldo_acreedor numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare v_acc uuid;
begin
  select c.account_id into v_acc from public.company c where c.id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;
  if p_hasta is null then
    raise exception 'Falta la fecha.' using errcode = '22023';
  end if;

  return query
  with s as (
    -- La misma vara que Inicio: conta_saldos_cuentas desde el día 1 del mes.
    select x.company_account_id,
           round(sum(x.inicial_debe - x.inicial_haber + x.apertura_debe - x.apertura_haber
                     + x.periodo_debe - x.periodo_haber + x.regularizacion_debe - x.regularizacion_haber), 2) as saldo
      from public.conta_saldos_cuentas(p_company, date_trunc('month', p_hasta)::date, p_hasta) x
     where x.code ~ '^4[0134]'
     group by x.company_account_id
  )
  select ca.code, coalesce(ca.plain_name, ca.name),
         coalesce(
           (select p.id from public.company_account_link l join public.party p on p.account_id = v_acc and p.id::text = l.entity_id
             where l.account_id = v_acc and l.company_id = p_company and l.company_account_id = ca.id
               and l.entity = 'customer' and l.role in ('principal', 'liquidacion')
             order by (l.role = 'principal') desc, l.created_at limit 1),
           (select pr.party_id from public.company_account_link l join public.party_role pr
                on pr.account_id = v_acc and pr.role = 'supplier' and pr.supplier_id::text = l.entity_id
             where l.account_id = v_acc and l.company_id = p_company and l.company_account_id = ca.id
               and l.entity = 'supplier' and l.role in ('principal', 'pago')
             order by (l.role = 'principal') desc, l.created_at, pr.created_at limit 1)),
         case when left(ca.code, 2) in ('43', '44') then 'cliente'
              when left(ca.code, 3) = '407' then 'anticipo'
              when coalesce(ca.plain_name, ca.name) ilike '%por localizar%' then 'por_localizar'
              when left(ca.code, 2) = '40' then 'proveedor'
              else 'acreedor' end,
         greatest(s.saldo, 0), greatest(-s.saldo, 0)
    from s
    join public.company_account ca on ca.id = s.company_account_id and ca.account_id = v_acc and ca.company_id = p_company
   where s.saldo <> 0
   order by ca.code;
end $$;


--
-- Name: FUNCTION conta_saldos_terceros(p_company uuid, p_hasta date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_saldos_terceros(p_company uuid, p_hasta date) IS 'S02 · PR 3 (0490). Solo lee. El saldo del libro (la vara de Inicio) de cada subcuenta 40/41/43/44 con saldo, en deudor y acreedor, con su grupo (cliente 43/44, anticipo 407, por_localizar, proveedor 40, acreedor 41) y su contacto por company_account_link. «Te deben» = deudor de cliente; «Debes» = acreedor de proveedor y acreedor.';


--
-- Name: conta_sin_confirmar_no_cobrados(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_sin_confirmar_no_cobrados(p_company uuid) RETURNS TABLE(sale_id uuid, location_id uuid, dia date, codigo text, canal_id uuid, total numeric, settlement_ref text, settlement_date date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select l.sale_id, s.location_id, l.sales_day, l.order_code, s.channel_id, s.total, cs.settlement_ref, cs.settlement_date
    from public.sales_day_close_log l
    join public.company c on c.id = p_company and c.account_id = l.account_id
    join public.sale s on s.id = l.sale_id and s.account_id = l.account_id
    join lateral (
      select x.settlement_ref, x.settlement_date
        from public.channel_settlement x
       where x.account_id = s.account_id and x.channel_id = s.channel_id
         and (x.location_id is null or x.location_id = s.location_id)
         and not coalesce(x.is_reference, false)
         and l.sales_day between coalesce(x.period_from, x.proposed_period_from) and coalesce(x.period_to, x.proposed_period_to)
       order by x.settlement_date desc nulls last
       limit 1) cs on true
   where l.company_id = p_company and l.accion = 'cerrado_sin_confirmar' and s.status = 'closed'
     and not exists (select 1 from public.channel_settlement_order co
                      where co.sale_id = s.id and co.account_id = s.account_id and coalesce(co.matched, false))
     and not exists (select 1 from public.journal_dismissal d
                      where d.company_id = p_company and d.source_type = 'sales_adjustment' and d.source_key = s.id::text)
   order by l.sales_day, l.order_code
$$;


--
-- Name: FUNCTION conta_sin_confirmar_no_cobrados(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_sin_confirmar_no_cobrados(p_company uuid) IS 'C11b (23/10). Pedidos cerrados sin confirmar al cierre del día que una liquidación de su canal ya cubre (su día dentro del periodo) y no trae cobrados: aviso para hacer el ajuste.';


--
-- Name: conta_socios_hasta_cien(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_socios_hasta_cien() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare total numeric;
begin
  select coalesce(sum(ownership_pct), 0) into total from public.company_person
   where company_id = new.company_id and ended_on is null;
  if total > 100 then
    raise exception 'Los porcentajes de los socios suman % %%: no pueden pasar de 100', total using errcode = '23514';
  end if;
  return null;
end $$;


--
-- Name: conta_subida_registrar(uuid, text, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_subida_registrar(p_company uuid, p_ruta text, p_nombre text, p_tipo text, p_bytes integer, p_sha256 text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare v_acc uuid; v_id uuid; v_ya uuid;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta sube facturas.' using errcode = '42501';
  end if;
  if p_tipo not in ('application/pdf', 'image/jpeg', 'image/png', 'image/webp') then raise exception 'Solo PDF o fotos (jpg, png, webp).' using errcode = '22023'; end if;
  if p_ruta is null or left(p_ruta, 37) <> v_acc::text || '/' then raise exception 'La ruta no es de la carpeta de esta cuenta.' using errcode = '22023'; end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'La huella del fichero no es un sha256.' using errcode = '22023'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id = 'receipt-uploads' and o.name = p_ruta) then
    raise exception 'El fichero no está subido (%).', p_ruta using errcode = 'P0002';
  end if;
  select id into v_ya from public.document_inbox where account_id = v_acc and sha256 = p_sha256 and status <> 'descartado' limit 1;
  if v_ya is not null then return jsonb_build_object('id', v_ya, 'ya_estaba', true); end if;
  insert into public.document_inbox (account_id, company_id, channel, file_path, file_name, mime_type, size_bytes, sha256, created_by, created_by_name)
  values (v_acc, p_company, 'subida', p_ruta, p_nombre, p_tipo, p_bytes, p_sha256, auth.uid(), p_quien_nombre)
  returning id into v_id;
  insert into public.document_activity (account_id, company_id, inbox_id, actor, actor_name, action, text)
  values (v_acc, p_company, v_id, 'persona', coalesce(p_quien_nombre, 'Alguien de la cuenta'), 'recibida', coalesce(p_quien_nombre, 'Alguien') || ' ha subido ' || coalesce(p_nombre, 'un documento') || '.');
  return jsonb_build_object('id', v_id, 'ya_estaba', false);
end $_$;


--
-- Name: conta_sugerencia_responder(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_sugerencia_responder(p_sugerencia uuid, p_acepta boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.ai_suggestion; v_modelos text[]; v_nuevos text[]; v_anual text; v_log uuid;
begin
  select * into s from public.ai_suggestion where id = p_sugerencia for update;
  if s.id is null then raise exception 'No encuentro esa sugerencia' using errcode = '42501'; end if;
  perform public.conta_ia_cuenta(s.company_id);
  if s.status <> 'open' then raise exception 'Esa sugerencia ya está contestada' using errcode = '23514'; end if;
  v_nuevos := '{}';
  if p_acepta then
    if s.kind = 'modelo' then
      select coalesce(tax_forms, '{}') into v_modelos from public.company_tax_profile where company_id = s.company_id;
      v_modelos := coalesce(v_modelos, '{}');
      if not ((s.payload ->> 'modelo') = any(v_modelos)) then v_nuevos := v_nuevos || (s.payload ->> 'modelo'); end if;
      -- Respuesta 3: todo periódico lleva su anual, según la tabla de modelos.
      select annual_form_code into v_anual from public.tax_form where code = (s.payload ->> 'modelo');
      if v_anual is not null and not (v_anual = any(v_modelos)) then v_nuevos := v_nuevos || v_anual; end if;
      if cardinality(v_nuevos) > 0 then
        v_log := public.conta_ia_poner(s.company_id, 'company_tax_profile', 'tax_forms',
                   to_jsonb((select array_agg(m order by m) from unnest(v_modelos || v_nuevos) m)),
                   s.why || case when v_anual = any(v_nuevos) then ' Con su resumen anual, el ' || v_anual || '.' else '' end, 'ai');
        update public.ai_action_log set suggestion_id = s.id where id = v_log;
      end if;
    end if;
  end if;
  update public.ai_suggestion
     set status = case when p_acepta then 'accepted' else 'rejected' end,
         decided_at = now(), decided_by = auth.uid(), decided_by_name = public.conta_nombre_actor()
   where id = s.id;
  return jsonb_build_object('id', s.id, 'aceptada', p_acepta, 'registro', v_log, 'anadidos', to_jsonb(v_nuevos));
end $$;


--
-- Name: conta_sugerencias_calcular(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_sugerencias_calcular(p_company uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid; v_modelos text[]; v_prov text; n integer := 0;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.belongs_to_account(v_cuenta) then
    raise exception 'Esa empresa no es de esta cuenta' using errcode = '42501';
  end if;
  select coalesce(tax_forms, '{}') into v_modelos from public.company_tax_profile where company_id = p_company;
  v_modelos := coalesce(v_modelos, '{}');

  -- 115
  select s.name into v_prov from public.supplier s join public.expense_category e on e.id = s.expense_category_id
   where s.account_id = v_cuenta and coalesce(s.is_active, true) and s.archived_at is null
     and e.pgc_account_hint = '621' and s.irpf_withholding_pct = 19
   order by s.name limit 1;
  if v_prov is not null and not ('115' = any(v_modelos)) then
    insert into public.ai_suggestion (account_id, company_id, kind, reason_key, title, why, payload)
    values (v_cuenta, p_company, 'modelo', 'modelo_115',
            'Pagas un alquiler con retención y no tienes el modelo 115. ¿Lo añado?',
            format('Lo veo en %s: alquiler (cuenta 621) con un 19 %% de retención. Esa retención se declara cada trimestre en el 115 (RD 439/2007, art. 100).', v_prov),
            jsonb_build_object('modelo', '115'))
    on conflict (company_id, kind, reason_key) do nothing;
    if found then n := n + 1; end if;
  else
    delete from public.ai_suggestion where company_id = p_company and reason_key = 'modelo_115' and status = 'open';
  end if;

  -- 111
  v_prov := null;
  select s.name into v_prov from public.supplier s
   where s.account_id = v_cuenta and coalesce(s.is_active, true) and s.archived_at is null and s.irpf_withholding_pct in (7, 15)
   order by s.name limit 1;
  if v_prov is not null and not ('111' = any(v_modelos)) then
    insert into public.ai_suggestion (account_id, company_id, kind, reason_key, title, why, payload)
    values (v_cuenta, p_company, 'modelo', 'modelo_111',
            'Pagas a profesionales con retención y no tienes el modelo 111. ¿Lo añado?',
            format('Lo veo en %s: le retienes el IRPF. Esas retenciones se declaran cada trimestre en el 111 (RD 439/2007, art. 108).', v_prov),
            jsonb_build_object('modelo', '111'))
    on conflict (company_id, kind, reason_key) do nothing;
    if found then n := n + 1; end if;
  else
    delete from public.ai_suggestion where company_id = p_company and reason_key = 'modelo_111' and status = 'open';
  end if;
  return n;
end $$;


--
-- Name: conta_sumas_saldos(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_sumas_saldos(p_company uuid, p_desde date, p_hasta date) RETURNS TABLE(company_account_id uuid, code text, name text, template_code text, debe numeric, haber numeric, saldo numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select l.company_account_id, l.account_code, l.account_name, l.template_code,
         sum(l.debit), sum(l.credit), sum(l.debit) - sum(l.credit)
    from public.journal_ledger l
   where l.company_id = p_company and l.entry_date between p_desde and p_hasta
   group by l.company_account_id, l.account_code, l.account_name, l.template_code
   order by l.account_code
$$;


--
-- Name: FUNCTION conta_sumas_saldos(p_company uuid, p_desde date, p_hasta date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_sumas_saldos(p_company uuid, p_desde date, p_hasta date) IS 'C04. Sumas y saldos por cuenta de apunte en un periodo (lo validado; con la RLS de quien lee).';


--
-- Name: conta_tarifa_guardar(uuid, text, date, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_tarifa_guardar(p_company uuid, p_provider text, p_desde date, p_params jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_id uuid; v_ya boolean; t jsonb;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_acc) then raise exception 'Solo un administrador o un encargado de la cuenta cambia la tarifa.' using errcode = '42501'; end if;
  if p_provider <> 'catcher' then raise exception 'Solo hay tarifa de Catcher.' using errcode = '22023'; end if;
  if p_desde is null then raise exception 'Di desde cuándo vale.' using errcode = '22023'; end if;
  -- Un valor que falta da NULL, y «NULL <> …» no frena: todo con coalesce (lo cazó la prueba de staging).
  if coalesce(jsonb_typeof(p_params->'tramos'), '') <> 'array' or jsonb_array_length(p_params->'tramos') = 0 then raise exception 'La tarifa necesita al menos un tramo por km.' using errcode = '22023'; end if;
  for t in select * from jsonb_array_elements(p_params->'tramos') loop
    if coalesce((t->>'hastaKm')::numeric, 0) <= 0 or coalesce((t->>'precio')::numeric, -1) < 0 then raise exception 'Cada tramo lleva hasta cuántos km y su precio.' using errcode = '22023'; end if;
  end loop;
  if exists (select 1 from unnest(array['porKmExtra', 'maximo', 'bonoLluviaPct', 'bonoDemandaPct', 'bonoMaxPct', 'pedidoExtra', 'comisionPedido']) k
              where coalesce(jsonb_typeof(p_params->k), '') <> 'number' or coalesce((p_params->>k)::numeric, -1) < 0) then
    raise exception 'Faltan valores de la tarifa (por km de más, máximo, bonos, pedido extra o comisión), o alguno es negativo.' using errcode = '22023';
  end if;
  select exists (select 1 from public.supplier_rate where account_id = v_acc and company_id = p_company and provider = p_provider and valid_from = p_desde) into v_ya;
  insert into public.supplier_rate (account_id, company_id, provider, valid_from, params, source, created_by_name)
  values (v_acc, p_company, p_provider, p_desde, p_params, 'manual', p_quien_nombre)
  on conflict (account_id, company_id, provider, valid_from) do update set params = excluded.params, source = 'manual', created_by_name = excluded.created_by_name, updated_at = now()
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'texto', case when v_ya then 'Corregida la tarifa de Catcher que vale desde el ' else 'Guardada la tarifa de Catcher: vale desde el ' end || to_char(p_desde, 'DD/MM/YYYY') || '.');
end $$;


--
-- Name: FUNCTION conta_tarifa_guardar(p_company uuid, p_provider text, p_desde date, p_params jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_tarifa_guardar(p_company uuid, p_provider text, p_desde date, p_params jsonb, p_quien_nombre text) IS 'E05 · Guarda una versión de la tarifa del proveedor (Catcher) que vale desde p_desde; si ya hay una de ese día, la corrige.';


--
-- Name: conta_tienda_cambio_decidir(uuid, boolean, uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_tienda_cambio_decidir(p_cambio uuid, p_confirmar boolean, p_marca uuid DEFAULT NULL::uuid, p_local uuid DEFAULT NULL::uuid, p_desde date DEFAULT NULL::date, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_c public.platform_store_cambio; v_s public.platform_store; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor());
  v_desde date; v_marca uuid; v_local uuid; v_n int := 0; v_t record; v_texto text;
begin
  select * into v_c from public.platform_store_cambio where id = p_cambio for update;
  if v_c.id is null or not public.belongs_to_account(v_c.account_id) then raise exception 'Ese cambio no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_c.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta confirma los cambios de las tiendas.' using errcode = '42501';
  end if;
  if v_c.decided_at is not null then raise exception 'Ese cambio ya está decidido.' using errcode = '23505'; end if;
  select * into v_s from public.platform_store where id = v_c.store_id for update;
  if not coalesce(p_confirmar, false) then
    update public.platform_store_cambio set decided_at = now(), decision = 'descartado', decided_by = auth.uid(), decided_by_name = v_quien where id = v_c.id;
    return jsonb_build_object('cambio', v_c.id, 'decision', 'descartado',
      'texto', 'Descartado: «' || coalesce(v_s.external_text, '') || '» sigue con su marca y su local.');
  end if;
  v_desde := coalesce(p_desde, (v_c.propuesta->>'desde')::date, public.conta_hoy());
  v_marca := coalesce(p_marca, nullif(v_c.propuesta->>'marca', '')::uuid);
  v_local := coalesce(p_local, nullif(v_c.propuesta->>'local', '')::uuid);
  if v_marca is not null and not exists (select 1 from public.brand where id = v_marca and account_id = v_c.account_id) then raise exception 'Esa marca no es de esta cuenta.' using errcode = '22023'; end if;
  if v_local is not null and not exists (select 1 from public.locations where id = v_local and account_id = v_c.account_id) then raise exception 'Ese local no es de esta cuenta.' using errcode = '22023'; end if;
  -- Lo de antes no se mueve: las liquidaciones de la tienda que empiezan antes y aún
  -- no dicen marca o local se quedan con las de su tramo.
  for v_t in select cs.id, (public.conta_tienda_en(v_s.id, cs.period_from)).* from public.channel_settlement cs
              where cs.store_id = v_s.id and cs.account_id = v_s.account_id and coalesce(cs.period_from, cs.settlement_date) < v_desde
                and (cs.brand_id is null or cs.location_id is null) loop
    update public.channel_settlement set brand_id = coalesce(brand_id, v_t.brand_id), location_id = coalesce(location_id, v_t.location_id), updated_at = now()
     where id = v_t.id;
    v_n := v_n + 1;
  end loop;
  -- El tramo vigente se cierra la víspera y se abre el nuevo.
  update public.platform_store_tramo set valid_to = v_desde - 1
   where store_id = v_s.id and valid_to is null and (valid_from is null or valid_from < v_desde);
  delete from public.platform_store_tramo where store_id = v_s.id and valid_from >= v_desde;
  insert into public.platform_store_tramo (account_id, store_id, brand_id, location_id, valid_from, motivo, created_by_name)
  values (v_s.account_id, v_s.id, v_marca, v_local, v_desde,
          case v_c.kind when 'direccion' then 'Cambió de dirección: ' else 'Cambió de nombre: ' end || coalesce(v_c.antes, '') || ' → ' || v_c.ahora, v_quien);
  v_texto := v_c.ahora;
  if exists (select 1 from public.platform_store where account_id = v_s.account_id and company_id = v_s.company_id and provider = v_s.provider
                and id <> v_s.id and lower(btrim(external_text)) = lower(btrim(v_texto))) then
    v_texto := v_texto || ' · ' || coalesce(v_s.external_id, left(v_s.id::text, 8));
  end if;
  update public.platform_store set external_text = v_texto, brand_id = v_marca, location_id = v_local,
         updated_at = now(), updated_by = auth.uid(), updated_by_name = v_quien
   where id = v_s.id;
  update public.platform_store_cambio set decided_at = now(), decision = 'confirmado', decided_by = auth.uid(), decided_by_name = v_quien,
         propuesta = propuesta || jsonb_build_object('marca', v_marca, 'local', v_local, 'desde', v_desde)
   where id = v_c.id;
  return jsonb_build_object('cambio', v_c.id, 'decision', 'confirmado', 'desde', v_desde, 'liquidaciones_de_antes', v_n,
    'texto', 'Confirmado desde el ' || to_char(v_desde, 'DD/MM/YYYY') || ': «' || v_c.ahora || '»' ||
             coalesce(' es de ' || (select name from public.brand where id = v_marca), '') ||
             coalesce(' en ' || (select name from public.locations where id = v_local), '') || '. ' ||
             case when v_n = 0 then 'Lo de antes no se mueve.'
                  else 'Lo de antes no se mueve: ' || v_n || ' liquidaci' || case when v_n = 1 then 'ón se queda' else 'ones se quedan' end || ' con su marca y su local de entonces.' end);
end $$;


--
-- Name: FUNCTION conta_tienda_cambio_decidir(p_cambio uuid, p_confirmar boolean, p_marca uuid, p_local uuid, p_desde date, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_tienda_cambio_decidir(p_cambio uuid, p_confirmar boolean, p_marca uuid, p_local uuid, p_desde date, p_quien_nombre text) IS 'V02 · E2. Confirmar con un clic (o descartar) un cambio de nombre o de dirección de una tienda: tramo nuevo desde ese día; lo de antes no se mueve.';


--
-- Name: conta_tienda_en(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_tienda_en(p_store uuid, p_dia date) RETURNS TABLE(brand_id uuid, location_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(t.brand_id, case when t.id is null then s.brand_id end), coalesce(t.location_id, case when t.id is null then s.location_id end)
    from public.platform_store s
    left join lateral (
      select x.* from public.platform_store_tramo x
       where x.store_id = s.id
         and (p_dia is null and x.valid_to is null
              or p_dia is not null and (x.valid_from is null or x.valid_from <= p_dia) and (x.valid_to is null or x.valid_to >= p_dia))
       order by x.valid_from desc nulls last limit 1) t on true
   where s.id = p_store
$$;


--
-- Name: FUNCTION conta_tienda_en(p_store uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_tienda_en(p_store uuid, p_dia date) IS 'V02 · E2. La marca y el local de una tienda de plataforma un día, por sus tramos con fecha.';


--
-- Name: conta_tienda_plataforma_asignar(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_tienda_plataforma_asignar(p_store uuid, p_marca uuid, p_local uuid, p_banco uuid DEFAULT NULL::uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s public.platform_store; v_antes public.platform_store; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), public.conta_nombre_actor()); v_t record;
begin
  select * into v_s from public.platform_store where id = p_store for update;
  if v_s.id is null or not public.belongs_to_account(v_s.account_id) then raise exception 'Esa tienda no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_s.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta asigna las tiendas.' using errcode = '42501';
  end if;
  if p_marca is not null and not exists (select 1 from public.brand where id = p_marca and account_id = v_s.account_id) then raise exception 'Esa marca no es de esta cuenta.' using errcode = '22023'; end if;
  if p_local is not null and not exists (select 1 from public.locations where id = p_local and account_id = v_s.account_id) then raise exception 'Ese local no es de esta cuenta.' using errcode = '22023'; end if;
  if p_banco is not null and not exists (select 1 from public.treasury_account where id = p_banco and account_id = v_s.account_id and company_id = v_s.company_id) then
    raise exception 'Esa cuenta del banco no es de esta empresa.' using errcode = '22023';
  end if;
  v_antes := v_s;
  -- V02 · E2: cambiar la marca o el local que YA tenía es un cambio con fecha: lo
  -- de antes se queda con los de antes (sus liquidaciones sin marca o local los
  -- toman de su tramo) y el tramo nuevo empieza hoy. Darlos a una tienda que no
  -- los tenía vale desde siempre, como hasta ahora.
  if (v_antes.brand_id is not null and p_marca is distinct from v_antes.brand_id)
     or (v_antes.location_id is not null and p_local is distinct from v_antes.location_id) then
    for v_t in select cs.id, (public.conta_tienda_en(v_s.id, coalesce(cs.period_from, cs.settlement_date))).* from public.channel_settlement cs
                where cs.store_id = v_s.id and cs.account_id = v_s.account_id and coalesce(cs.period_from, cs.settlement_date) < public.conta_hoy()
                  and (cs.brand_id is null or cs.location_id is null) loop
      update public.channel_settlement set brand_id = coalesce(brand_id, v_t.brand_id), location_id = coalesce(location_id, v_t.location_id), updated_at = now() where id = v_t.id;
    end loop;
    update public.platform_store_tramo set valid_to = public.conta_hoy() - 1
     where store_id = v_s.id and valid_to is null and (valid_from is null or valid_from < public.conta_hoy());
    delete from public.platform_store_tramo where store_id = v_s.id and valid_from >= public.conta_hoy();
    insert into public.platform_store_tramo (account_id, store_id, brand_id, location_id, valid_from, motivo, created_by_name)
    values (v_s.account_id, v_s.id, p_marca, p_local, public.conta_hoy(), 'Cambiada a mano en Sus tiendas.', v_quien);
  else
    update public.platform_store_tramo set brand_id = coalesce(p_marca, brand_id), location_id = coalesce(p_local, location_id)
     where store_id = v_s.id and valid_to is null;
    if not found then
      insert into public.platform_store_tramo (account_id, store_id, brand_id, location_id, valid_from, motivo, created_by_name)
      values (v_s.account_id, v_s.id, p_marca, p_local, null, 'Asignada en Sus tiendas: desde siempre.', v_quien);
    end if;
  end if;
  update public.platform_store set brand_id = p_marca, location_id = p_local, treasury_account_id = p_banco,
         updated_at = now(), updated_by = auth.uid(), updated_by_name = v_quien
   where id = p_store returning * into v_s;
  -- Sus liquidaciones aún sin marca ni local las toman ahora (las que ya tenían, no se tocan),
  -- y cada una vuelve a decir si queda por aclarar: asignar la tienda no arregla un solape
  -- ni lo que no cuadró al leer.
  update public.channel_settlement set brand_id = coalesce(brand_id, p_marca), location_id = coalesce(location_id, p_local), updated_at = now()
   where store_id = p_store and (brand_id is null or location_id is null);
  perform public._conta_liquidacion_marcar(x.id) from public.channel_settlement x where x.store_id = p_store;
  return to_jsonb(v_s);
end $$;


--
-- Name: conta_tienda_reconocer(uuid, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_tienda_reconocer(p_company uuid, p_provider text, p_id text, p_texto text, p_canal uuid DEFAULT NULL::uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_prov text := lower(btrim(coalesce(p_provider, ''))); v_id text := nullif(btrim(coalesce(p_id, '')), '');
  v_texto text := nullif(btrim(coalesce(p_texto, '')), ''); v_s public.platform_store; v_por_nombre public.platform_store;
  v_nueva boolean := false; v_aprendido boolean := false; v_cambio uuid; v_quien text := coalesce(nullif(btrim(p_quien_nombre), ''), 'Sumied · liquidaciones');
  v_kind text; v_antes text; v_loc uuid; v_t record;
begin
  select account_id into v_acc from public.company where id = p_company;
  if v_acc is null then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.current_user_is_admin_or_manager_of(v_acc) then
    raise exception 'Solo un administrador o un encargado de la cuenta registra liquidaciones.' using errcode = '42501';
  end if;
  if v_prov = '' then raise exception 'Falta de qué plataforma es la tienda.' using errcode = '22023'; end if;
  if v_id is null and v_texto is null then raise exception 'El documento no dice de qué tienda es.' using errcode = '22023'; end if;

  if v_id is not null then
    select * into v_s from public.platform_store where account_id = v_acc and company_id = p_company and provider = v_prov and external_id = v_id;
  end if;
  if v_texto is not null then
    select s.* into v_por_nombre from public.platform_store_alias a join public.platform_store s on s.id = a.store_id
     where a.account_id = v_acc and a.company_id = p_company and a.provider = v_prov and lower(btrim(a.texto)) = lower(v_texto) limit 1;
    if v_por_nombre.id is null then
      select * into v_por_nombre from public.platform_store
       where account_id = v_acc and company_id = p_company and provider = v_prov and lower(btrim(external_text)) = lower(v_texto);
    end if;
  end if;

  if v_s.id is null and v_por_nombre.id is not null and (v_id is null or v_por_nombre.external_id is null) then
    -- La del nombre: si llega con un ID que no tenía, se aprende.
    v_s := v_por_nombre;
    if v_id is not null then
      update public.platform_store set external_id = v_id, last_seen_at = now() where id = v_s.id returning * into v_s;
      v_aprendido := true;
    else
      update public.platform_store set last_seen_at = now() where id = v_s.id returning * into v_s;
    end if;
  elsif v_s.id is null then
    -- Nueva: sin marca; el local, por su dirección (el disparador de la 2031).
    -- Si su nombre ya es el de otra tienda con otro ID, el nombre se guarda con el ID detrás.
    insert into public.platform_store (account_id, company_id, provider, external_text, external_id, channel_id, created_by_name)
    values (v_acc, p_company, v_prov,
            case when v_texto is null then v_prov || ' · ' || v_id
                 when exists (select 1 from public.platform_store where account_id = v_acc and company_id = p_company and provider = v_prov and lower(btrim(external_text)) = lower(v_texto))
                   then v_texto || ' · ' || v_id
                 else v_texto end,
            v_id, p_canal, v_quien)
    returning * into v_s;
    insert into public.platform_store_tramo (account_id, store_id, brand_id, location_id, valid_from, motivo, created_by_name)
    values (v_acc, v_s.id, v_s.brand_id, v_s.location_id, null, 'Tienda nueva: desde siempre.', v_quien);
    v_nueva := true;
  else
    update public.platform_store set last_seen_at = now() where id = v_s.id returning * into v_s;
    -- La misma tienda (por su ID) con otro nombre o en otra dirección: se apunta, no se reasigna.
    if v_texto is not null and not exists (select 1 from public.platform_store_alias a where a.store_id = v_s.id and lower(btrim(a.texto)) = lower(v_texto))
       and lower(btrim(v_s.external_text)) <> lower(v_texto) then
      v_antes := v_s.external_text;
      v_kind := case when public.conta_clave_direccion(public._conta_tienda_direccion(v_texto)) is distinct from public.conta_clave_direccion(public._conta_tienda_direccion(v_antes))
                     then 'direccion' else 'nombre' end;
      v_loc := case when v_kind = 'direccion' then public.conta_local_de_tienda(v_acc, v_texto) else v_s.location_id end;
      insert into public.platform_store_cambio (account_id, company_id, store_id, kind, antes, ahora, propuesta)
      values (v_acc, p_company, v_s.id, v_kind, v_antes, v_texto,
              jsonb_build_object('marca', case when v_kind = 'nombre' then null else v_s.brand_id end, 'local', v_loc, 'desde', public.conta_hoy()))
      on conflict do nothing
      returning id into v_cambio;
      if v_cambio is null then
        select id into v_cambio from public.platform_store_cambio where store_id = v_s.id and kind = v_kind and lower(btrim(ahora)) = lower(v_texto) and decided_at is null;
      end if;
    end if;
  end if;

  if v_texto is not null then
    insert into public.platform_store_alias (account_id, company_id, store_id, provider, texto)
    values (v_acc, p_company, v_s.id, v_prov, v_texto)
    on conflict (account_id, company_id, provider, lower(btrim(texto))) do nothing;
    update public.platform_store_alias set last_seen_at = now() where store_id = v_s.id and lower(btrim(texto)) = lower(v_texto);
  end if;
  if v_s.channel_id is null and p_canal is not null then
    update public.platform_store set channel_id = p_canal where id = v_s.id returning * into v_s;
  end if;
  return jsonb_build_object('tienda_id', v_s.id, 'nueva', v_nueva, 'aprendido_id', v_aprendido, 'cambio', v_cambio);
end $$;


--
-- Name: FUNCTION conta_tienda_reconocer(p_company uuid, p_provider text, p_id text, p_texto text, p_canal uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_tienda_reconocer(p_company uuid, p_provider text, p_id text, p_texto text, p_canal uuid, p_quien_nombre text) IS 'V02 · E2. La tienda de un documento: por su ID de la plataforma (o, si no lo trae, por un nombre ya visto). Aprende el ID; si la tienda llega con otro nombre o en otra dirección, apunta el cambio para confirmarlo.';


--
-- Name: conta_traspaso_apuntar(uuid, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_traspaso_apuntar(p_traspaso uuid, p_llegaron integer, p_no_llegaron integer, p_detalle jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.conta_diez_traspaso
     set estado = 'traspasando', llegaron = llegaron + greatest(p_llegaron, 0), no_llegaron = greatest(p_no_llegaron, 0),
         detalle = coalesce(p_detalle, '[]'::jsonb)
   where id = p_traspaso
$$;


--
-- Name: conta_traspaso_confirmar(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_traspaso_confirmar(p_company uuid, p_mes date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_mes date := date_trunc('month', p_mes)::date; v_rev jsonb; v_t public.conta_diez_traspaso; v_id uuid;
begin
  select c.account_id into v_acc from public.company c where c.id = p_company;
  if v_acc is null or not public.current_user_is_admin_of(v_acc) then
    raise exception 'Solo un administrador de la cuenta puede traspasar el mes a Diez.' using errcode = '42501';
  end if;
  if v_mes >= date_trunc('month', (now() at time zone 'Europe/Madrid'))::date then
    raise exception 'El mes aún no ha terminado: se traspasa cuando acaba.' using errcode = '23514';
  end if;
  select * into v_t from public.conta_diez_traspaso where company_id = p_company and mes = v_mes for update;
  if v_t.id is not null and v_t.estado in ('terminado', 'traspasando') then
    raise exception 'Ese mes ya está %.', case v_t.estado when 'terminado' then 'traspasado' else 'traspasándose' end using errcode = '23505';
  end if;
  v_rev := public.conta_traspaso_revisar(p_company, v_mes);
  insert into public.conta_diez_traspaso (account_id, company_id, mes, estado, confirmado_por, confirmado_por_nombre, confirmado_en, faltaba, resumen, van)
  values (v_acc, p_company, v_mes, 'confirmado', auth.uid(), public.conta_nombre_actor(), now(), v_rev->'faltan',
          jsonb_build_object('por_tipo', v_rev->'por_tipo', 'por_cuenta', v_rev->'por_cuenta', 'ya_en_diez', v_rev->'ya_en_diez', 'no_viajan', v_rev->'no_viajan'),
          (v_rev->>'van')::int)
  on conflict (company_id, mes) do update
     set estado = 'confirmado', confirmado_por = excluded.confirmado_por, confirmado_por_nombre = excluded.confirmado_por_nombre,
         confirmado_en = excluded.confirmado_en, faltaba = excluded.faltaba, resumen = excluded.resumen, van = excluded.van,
         llegaron = 0, no_llegaron = 0, detalle = '[]'::jsonb, cuadre = null, cuadra = null, terminado_en = null
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'mes', v_mes, 'van', (v_rev->>'van')::int, 'faltaban', jsonb_array_length(v_rev->'faltan'));
end
$$;


--
-- Name: conta_traspaso_lista(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_traspaso_lista(p_company uuid, p_mes date) RETURNS TABLE(entry_id uuid, orden integer, tipo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.id, (row_number() over (order by e.entry_date, (e.reverses_entry_id is not null), e.number nulls last, e.id))::int,
         case when e.source_type = 'reversal' then 'anulacion'
              when e.source_type = 'sales_day' then 'ventas'
              when e.source_type = 'supplier_invoice' then 'recibidas'
              when e.source_type = 'bank' then 'banco'
              when e.source_type in ('channel_settlement', 'licensed_settlement') then 'liquidaciones'
              else 'manuales' end
    from public.journal_entry e
   where e.company_id = p_company
     and e.entry_date >= date_trunc('month', p_mes)::date
     and e.entry_date < (date_trunc('month', p_mes) + interval '1 month')::date
     and public._conta_traspaso_va(e.id)
   order by 2
$$;


--
-- Name: conta_traspaso_revisar(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_traspaso_revisar(p_company uuid, p_mes date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_mes date := date_trunc('month', p_mes)::date; v_fin date;
  v_asientos int; v_sin_pdf int; v_cierres int; v_liq int;
  v_por_tipo jsonb; v_por_cuenta jsonb; v_van int; v_ya int; v_no_viajan int;
  v_traspaso jsonb; v_cerrado boolean; v_modo text; v_conectado boolean;
begin
  select c.account_id into v_acc from public.company c where c.id = p_company;
  if v_acc is null or not public.belongs_to_account(v_acc) then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;
  v_fin := (v_mes + interval '1 month - 1 day')::date;

  -- 1 · Asientos sin validar del mes.
  select count(*) into v_asientos from public.journal_entry e
   where e.company_id = p_company and e.account_id = v_acc and e.status in ('propuesto', 'borrador')
     and e.entry_date between v_mes and v_fin;
  -- 2 · Recibidas del mes sin PDF (salvo las marcadas «Sin PDF»).
  select count(*) into v_sin_pdf from public.journal_entry e
    join public.supplier_invoice f on f.id = e.source_id and f.account_id = e.account_id
   where e.company_id = p_company and e.account_id = v_acc and e.source_type = 'supplier_invoice'
     and e.status in ('propuesto', 'validado') and e.entry_date between v_mes and v_fin
     and f.raw_document_url is null and f.no_document_at is null;
  -- 3 · Cierres del día en espera: pedidos cerrados sin confirmar que esperan decisión.
  begin
    select count(*) into v_cierres from public.conta_sin_confirmar_no_cobrados(p_company) w
     where w.dia between v_mes and v_fin;
  exception when others then v_cierres := null;
  end;
  -- 4 · Liquidaciones del mes cobradas con diferencia.
  select count(*) into v_liq from public.channel_settlement x
   where x.account_id = v_acc and not coalesce(x.is_reference, false)
     and x.collected_on is not null and x.net_payout is not null
     and abs(coalesce(x.collected_amount, 0) - x.net_payout) >= 0.01
     and coalesce(x.settlement_date, x.period_to, x.proposed_period_to) between v_mes and v_fin;

  -- Lo que va, por tipo, y lo que ya estaba.
  select coalesce(jsonb_agg(jsonb_build_object('tipo', t.tipo, 'n', t.n) order by t.tipo), '[]'::jsonb), coalesce(sum(t.n), 0)
    into v_por_tipo, v_van
    from (select l.tipo, count(*)::int n from public.conta_traspaso_lista(p_company, v_mes) l group by l.tipo) t;
  select count(*) into v_ya from public.journal_entry e
   where e.company_id = p_company and e.account_id = v_acc and e.entry_date between v_mes and v_fin
     and exists (select 1 from public.external_send s where s.entry_id = e.id and s.account_id = e.account_id and s.status in ('enviado', 'enlazado'));
  -- Anulados y sus anulaciones que no viajan (el original nunca llegó a Diez).
  select count(*) into v_no_viajan from public.journal_entry e
   where e.company_id = p_company and e.account_id = v_acc and e.entry_date between v_mes and v_fin
     and ((e.status = 'anulado' and not exists (select 1 from public.external_send s where s.entry_id = e.id and s.account_id = e.account_id and s.status in ('enviado', 'enlazado')))
       or (e.status = 'validado' and e.reverses_entry_id is not null and not public._conta_traspaso_va(e.id)
           and not exists (select 1 from public.external_send s where s.entry_id = e.id and s.account_id = e.account_id and s.status in ('enviado', 'enlazado'))));

  -- Totales por cuenta de lo que va.
  select coalesce(jsonb_agg(jsonb_build_object('cuenta', x.code, 'nombre', x.name, 'debe', x.d, 'haber', x.h) order by x.code), '[]'::jsonb)
    into v_por_cuenta
    from (select a.code, a.name, sum(l.debit)::numeric(14,2) d, sum(l.credit)::numeric(14,2) h
            from public.conta_traspaso_lista(p_company, v_mes) z
            join public.journal_line l on l.entry_id = z.entry_id and l.account_id = v_acc
            join public.company_account a on a.id = l.company_account_id and a.company_id = p_company
           group by a.code, a.name) x;

  select to_jsonb(t) - 'detalle' into v_traspaso from public.conta_diez_traspaso t where t.company_id = p_company and t.mes = v_mes;
  select exists (select 1 from public.fiscal_period_lock k where k.company_id = p_company and k.month = v_mes and k.reopened_at is null) into v_cerrado;
  select z.modo, coalesce(z.enviar, false) into v_modo, v_conectado from public.conta_diez_envio_empresa z where z.company_id = p_company and z.account_id = v_acc;

  return jsonb_build_object(
    'mes', v_mes,
    'faltan', (select coalesce(jsonb_agg(f) filter (where (f->>'n')::int > 0), '[]'::jsonb) from jsonb_array_elements(jsonb_build_array(
        jsonb_build_object('codigo', 'asientos', 'n', coalesce(v_asientos, 0)),
        jsonb_build_object('codigo', 'recibidas_sin_pdf', 'n', coalesce(v_sin_pdf, 0)),
        jsonb_build_object('codigo', 'cierres_en_espera', 'n', coalesce(v_cierres, 0)),
        jsonb_build_object('codigo', 'liquidaciones_con_diferencia', 'n', coalesce(v_liq, 0)))) f),
    'van', v_van, 'por_tipo', v_por_tipo, 'por_cuenta', v_por_cuenta,
    'ya_en_diez', v_ya, 'no_viajan', v_no_viajan,
    'traspaso', v_traspaso, 'mes_cerrado', v_cerrado,
    'modo', coalesce(v_modo, 'al_validar'), 'conectado', coalesce(v_conectado, false));
end
$$;


--
-- Name: conta_traspaso_saldos(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_traspaso_saldos(p_company uuid, p_mes date) RETURNS TABLE(cuenta text, nombre text, debe numeric, haber numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid;
begin
  select c.account_id into v_acc from public.company c where c.id = p_company;
  if v_acc is null then raise exception 'Esa empresa no existe.' using errcode = 'P0002'; end if;
  if auth.uid() is not null and not public.belongs_to_account(v_acc) then
    raise exception 'Esa empresa no es tuya.' using errcode = '42501';
  end if;
  return query
    select a.code, a.name, sum(l.debit)::numeric(14,2), sum(l.credit)::numeric(14,2)
      from public.journal_entry e
      join public.journal_line l on l.entry_id = e.id and l.account_id = e.account_id
      join public.company_account a on a.id = l.company_account_id and a.company_id = e.company_id
     where e.company_id = p_company and e.account_id = v_acc
       and e.entry_date >= date_trunc('month', p_mes)::date
       and e.entry_date < (date_trunc('month', p_mes) + interval '1 month')::date
       and e.status in ('validado', 'anulado')
       and public._conta_traspaso_en_diez(e.id)
     group by a.code, a.name
     order by a.code;
end
$$;


--
-- Name: conta_traspaso_terminar(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_traspaso_terminar(p_traspaso uuid, p_cuadre jsonb, p_cuadra boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_t public.conta_diez_traspaso; v_ej public.fiscal_year; v_primero date; v_cerrado boolean := false; v_motivo text;
begin
  select * into v_t from public.conta_diez_traspaso where id = p_traspaso for update;
  if v_t.id is null then raise exception 'Ese traspaso no existe.' using errcode = 'P0002'; end if;
  if v_t.no_llegaron > 0 then
    v_motivo := 'No se cierra el mes: ' || v_t.no_llegaron || ' no han llegado a Diez.';
  elsif p_cuadra is not true then
    v_motivo := case when p_cuadra is null then 'No se cierra el mes: no se ha podido comprobar con Diez.'
                     else 'No se cierra el mes: Diez no cuadra con Sumied.' end;
  elsif exists (select 1 from public.fiscal_period_lock k where k.company_id = v_t.company_id and k.month = v_t.mes and k.reopened_at is null) then
    v_cerrado := true; v_motivo := 'El mes ya estaba cerrado.';
  else
    select * into v_ej from public.fiscal_year where company_id = v_t.company_id and v_t.mes between date_trunc('month', starts_on)::date and ends_on;
    if v_ej.id is null then
      v_motivo := 'No se cierra el mes: no hay ejercicio para ' || to_char(v_t.mes, 'MM/YYYY') || '.';
    else
      select min(m)::date into v_primero from generate_series(date_trunc('month', v_ej.starts_on), v_ej.ends_on, interval '1 month') m
       where not exists (select 1 from public.fiscal_period_lock l where l.company_id = v_t.company_id and l.month = m::date and l.reopened_at is null);
      if v_primero is distinct from v_t.mes then
        v_motivo := 'No se cierra el mes: los meses se cierran en orden y el primero abierto es ' || to_char(v_primero, 'MM/YYYY') || '.';
      else
        insert into public.fiscal_period_lock (account_id, company_id, fiscal_year_id, month, locked_by, locked_by_name)
        values (v_t.account_id, v_t.company_id, v_ej.id, v_t.mes, v_t.confirmado_por, coalesce(v_t.confirmado_por_nombre, 'Traspaso a Diez'));
        v_cerrado := true;
      end if;
    end if;
  end if;
  update public.conta_diez_traspaso
     set estado = case when v_t.no_llegaron > 0 then 'con_fallos' else 'terminado' end,
         cuadre = p_cuadre, cuadra = p_cuadra, mes_cerrado = v_cerrado, cierre_motivo = v_motivo, terminado_en = now()
   where id = p_traspaso;
  return jsonb_build_object('mes_cerrado', v_cerrado, 'motivo', v_motivo);
end
$$;


--
-- Name: conta_ultimo_dia_cerrado(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_ultimo_dia_cerrado(p_company uuid, p_ahora timestamp with time zone DEFAULT now()) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case when (p_ahora at time zone 'Europe/Madrid')::time >= coalesce(t.sales_day_close_time, time '02:00')
              then (p_ahora at time zone 'Europe/Madrid')::date - 1
              else (p_ahora at time zone 'Europe/Madrid')::date - 2 end
    from public.company c
    left join public.company_tax_profile t on t.company_id = c.id
   where c.id = p_company
$$;


--
-- Name: FUNCTION conta_ultimo_dia_cerrado(p_company uuid, p_ahora timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_ultimo_dia_cerrado(p_company uuid, p_ahora timestamp with time zone) IS 'Cierre del día: el último día ya cerrado de la empresa a esta hora (Madrid). A las 17:16 del 09/10 con cierre a las 2:00 → 08/10; a las 1:30 del 09/10 → 07/10.';


--
-- Name: conta_una_principal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_una_principal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare c uuid := coalesce(new.company_id, old.company_id); vigentes int; principales int;
begin
  select count(*), count(*) filter (where is_main) into vigentes, principales
    from public.company_activity where company_id = c and ended_on is null;
  if vigentes > 0 and principales <> 1 then
    raise exception 'La empresa tiene % actividades y % principales: tiene que haber una y solo una principal', vigentes, principales
      using errcode = '23514';
  end if;
  return null;
end $$;


--
-- Name: conta_unidad_ventas(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_unidad_ventas(p_company uuid, p_canal uuid, p_marca uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(p_canal::text, 'sin-canal')
      || case when p_marca is not null and exists (select 1 from public.conta_ventas_canal v
                                                    where v.company_id = p_company and v.channel_id = p_canal and v.por_marca)
              then ':' || p_marca::text else '' end
$$;


--
-- Name: conta_user_pref_al_dia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_user_pref_al_dia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  return new;
end $$;


--
-- Name: conta_v01_historico_cierres(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_v01_historico_cierres() RETURNS TABLE(entry_id uuid, company_id uuid, account_id uuid, numero text, serie text, fecha date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  select e.id, e.company_id, e.account_id, x.ext_invoice_number,
         regexp_replace(x.ext_invoice_number, '-[0-9]{8}(-[0-9]+)?$', ''), s.sales_day
    from public.journal_entry e
    join public.sales_day_summary s on s.entry_id = e.id and s.company_id = e.company_id and s.unit_key is not null and s.channel_id is not null
    join lateral (select x.ext_invoice_number from public.external_send x
                   where x.entry_id = e.id and x.account_id = e.account_id and x.status in ('enviado', 'enlazado') and x.ext_invoice_number is not null
                   order by x.created_at desc limit 1) x on true
   where e.source_type = 'sales_day' and e.status = 'validado'
     and not exists (select 1 from public.customer_invoice ci where ci.entry_id = e.id)
     and exists (select 1 from public.vat_book_entry v where v.entry_id = e.id and v.book = 'issued' and v.number is null)
$_$;


--
-- Name: conta_v01_historico_traidos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_v01_historico_traidos() RETURNS TABLE(entry_id uuid, company_id uuid, account_id uuid, numero text, serie text, fecha date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select e.id, e.company_id, e.account_id, v.number, 'DIEZ'::text, e.entry_date
    from public.journal_entry e
    join public.vat_book_entry v on v.entry_id = e.id and v.book = 'issued'
   where e.source_type = 'migrated' and e.status = 'validado'
     and v.counterpart_tax_id is null and v.number is not null
     and not exists (select 1 from public.customer_invoice ci where ci.entry_id = e.id)
     -- Una factura por asiento: solo los de UNA anotación en el libro (los 1.196, el 24/10).
     and (select count(*) from public.vat_book_entry v2 where v2.entry_id = e.id and v2.book = 'issued') = 1
$$;


--
-- Name: conta_vat_book_desde_asiento(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_vat_book_desde_asiento(p_entry uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry; v_n integer := 0; l record;
  v_tipo text; v_num text; v_hasta text; v_docs int; v_fecha_op date; v_recep date; v_nif text; v_tipo_id text; v_pais text; v_nombre text;
  v_clave text; v_calif text; v_exenta text; v_corrige text; v_ret_tipo numeric; v_ret numeric; v_inv boolean; v_isp boolean;
  v_act_code text := 'A'; v_act_tipo text := '03'; v_iae text;
  v_sp record; v_em record; v_fac date;
  v_op public.verifactu_operacion; v_importe numeric; v_cuota numeric; v_base numeric;
begin
  select * into v_e from public.journal_entry where id = p_entry;
  if v_e.id is null or v_e.status not in ('validado', 'anulado') or v_e.source_type = 'reversal' then return 0; end if;
  if exists (select 1 from public.vat_book_entry where entry_id = p_entry) then return 0; end if;
  -- V03 E2 (0146): el porqué de una factura de venta sin IVA.
  if v_e.source_type = 'customer_invoice' then
    select * into v_op from public.verifactu_operacion where invoice_id = v_e.source_id and account_id = v_e.account_id;
  end if;
  select iae_code into v_iae from public.company_activity
   where company_id = v_e.company_id and is_main and (ended_on is null or ended_on >= v_e.entry_date) order by started_on desc nulls last limit 1;

  for l in
    select jl.*, t.rate, t.surcharge_rate, t.treatment
      from public.journal_line jl left join public.tax_rate t on t.id = jl.tax_rate_id
     where jl.entry_id = p_entry and jl.vat_book is not null
     order by jl.position
  loop
    v_tipo := 'F1'; v_num := coalesce(l.document_ref, v_e.document_ref); v_hasta := null; v_docs := l.tax_documents;
    v_fecha_op := null; v_recep := null; v_fac := null; v_corrige := null; v_ret_tipo := null; v_ret := null;
    v_nif := null; v_tipo_id := null; v_pais := null; v_nombre := null;
    v_inv := l.vat_book = 'investment';
    -- I01d (0300): la compra intracomunitaria también es inversión del sujeto
    -- pasivo (la declaras tú), como la trae Diez: clave 09 y «ISP» a la vez.
    v_isp := l.treatment = 'reverse_charge' or (l.treatment = 'intra_eu' and l.vat_book in ('received', 'investment'));
    v_clave := case when l.treatment = 'intra_eu' and l.vat_book <> 'issued' then '09' else '01' end;
    v_calif := case when l.vat_book = 'not_subject' then 'N1' when l.treatment = 'exempt' or (l.treatment = 'intra_eu' and l.vat_book = 'issued') then null
                    when v_isp then 'S2' else 'S1' end;
    v_exenta := case when l.treatment = 'exempt' then 'E1' when l.treatment = 'intra_eu' and l.vat_book = 'issued' then 'E5' end;
    -- V03 E2 (0146): la venta sin IVA de una factura dice su porqué
    -- (verifactu_operacion): E2 exportación (clave 02), E5, N1, N2…
    if l.treatment = 'exempt' and v_op.invoice_id is not null then
      v_calif := v_op.calificacion; v_exenta := v_op.exenta;
      v_clave := case when v_op.exenta = 'E2' then '02' else coalesce(v_op.clave_regimen, v_clave) end;
    end if;
    v_importe := case when l.vat_book = 'issued' then l.credit - l.debit else l.debit - l.credit end;
    v_cuota := case when l.treatment = 'exempt' then 0 else v_importe end;
    v_base := case when v_importe < 0 then -abs(l.tax_base) else abs(l.tax_base) end;

    if v_e.source_type = 'sales_day' then
      -- Asiento resumen de tiques (RIVA 63.4): F4 con el rango; un tique suelto, F2.
      select first_invoice, last_invoice, tickets_count into v_num, v_hasta, v_docs
        from public.sales_day_summary where entry_id = p_entry or id = v_e.source_id order by (entry_id = p_entry) desc limit 1;
      v_docs := coalesce(nullif(l.tax_documents, 1), v_docs, 1);
      v_tipo := case when coalesce(v_docs, 1) > 1 then 'F4' else 'F2' end;
      v_nombre := 'VENTAS A CONSUMIDOR FINAL';
    elsif v_e.source_type = 'supplier_invoice' then
      -- D07 (0850): la recibida conserva SU fecha de factura (la de expedición),
      -- aunque se asiente otro día (un periodo cerrado: el primer día abierto);
      -- y se registra el día que entró o, si es después, el del asiento: su IVA
      -- va al periodo en que se asienta (el 303 reparte por esta fecha).
      select si.invoice_number, greatest(si.created_at::date, v_e.entry_date), case when si.doc_kind = 'credit_note' then 'R1' else 'F1' end,
             (select c.invoice_number from public.supplier_invoice c where c.id = si.corrects_invoice_id),
             wr.rate, si.withholding_amount, si.invoice_date
        into v_num, v_recep, v_tipo, v_corrige, v_ret_tipo, v_ret, v_fac
        from public.supplier_invoice si left join public.withholding_rate wr on wr.id = si.withholding_rate_id
       where si.id = v_e.source_id;
    elsif v_e.source_type in ('channel_settlement', 'licensed_settlement') then
      v_num := coalesce(v_num, (select settlement_ref from public.channel_settlement where id = v_e.source_id),
                               (select settlement_ref from public.licensed_settlement where id = v_e.source_id));
    end if;

    select p.tax_id, nullif(f.tax_id_type, 'nif'), f.country_code, coalesce(f.legal_name, p.name)
      into v_nif, v_tipo_id, v_pais, v_nombre
      from public.party p left join public.customer_fiscal f on f.party_id = p.id
     where p.id = coalesce(l.party_id, v_e.party_id)
       and v_e.source_type <> 'sales_day';
    if v_e.source_type = 'sales_day' then v_nombre := 'VENTAS A CONSUMIDOR FINAL'; end if;
    -- I01d (0300): una recibida toma de la FICHA DEL PROVEEDOR lo que su
    -- tercero no tiene (no tiene ficha de cliente): el país si no es España,
    -- el tipo de identificación (02 NIF-IVA, 04 extranjero), el NIF y el nombre.
    if v_e.source_type = 'supplier_invoice' then
      select s.country_code, s.tax_id_type, s.tax_id, coalesce(s.legal_name, s.name) as nombre into v_sp
        from public.supplier_invoice si join public.supplier s on s.id = si.supplier_id and s.account_id = si.account_id
       where si.id = v_e.source_id and si.account_id = v_e.account_id;
      if found then
        v_pais := coalesce(v_pais, nullif(v_sp.country_code, 'ES'));
        v_tipo_id := coalesce(v_tipo_id, case v_sp.tax_id_type when 'vat_eu' then '02' when 'foreign' then '04' end);
        v_nif := coalesce(v_nif, v_sp.tax_id);
        v_nombre := coalesce(v_nombre, v_sp.nombre);
      end if;
    end if;
    -- 0410 · Una factura de lote (los riders y las flotas de Catcher): su
    -- contraparte es su EMISOR, que va en la factura (issuer_*), no la ficha
    -- genérica «RIDERS» ni su tercero, que no tienen NIF.
    if v_e.source_type = 'supplier_invoice' then
      select si.issuer_tax_id, si.issuer_name into v_em
        from public.supplier_invoice si
       where si.id = v_e.source_id and si.account_id = v_e.account_id and si.source = 'lote' and si.issuer_tax_id is not null;
      if found then
        v_nif := v_em.issuer_tax_id; v_nombre := coalesce(v_em.issuer_name, v_nombre); v_tipo_id := null; v_pais := null;
      end if;
    end if;
    if v_tipo_id is not null and v_tipo_id not in ('02', '03', '04', '05', '06') then v_tipo_id := null; end if;

    insert into public.vat_book_entry (account_id, company_id, entry_id, line_id, book, invoice_type, number, number_to, documents_count,
      issue_date, operation_date, received_date, party_id, counterpart_tax_id, counterpart_id_type, counterpart_country, counterpart_name,
      operation_key, qualification, exempt_cause, tax_base, tax_rate, tax_amount, surcharge_rate, total,
      deductible_amount, reverse_charge, investment_good, withholding_rate, withholding_amount,
      activity_code, activity_type, activity_iae, corrects_ref, source_type, source_id, voided_at, voided_by_entry_id)
    values (v_e.account_id, v_e.company_id, p_entry, l.id, l.vat_book, v_tipo, v_num, v_hasta, greatest(coalesce(v_docs, 1), 1),
      coalesce(l.document_date, v_e.document_date, v_fac, v_e.entry_date), v_fecha_op, v_recep, coalesce(l.party_id, v_e.party_id),
      v_nif, v_tipo_id, v_pais, v_nombre,
      -- La base lleva el signo de la cuota: en una rectificativa las dos van en
      -- negativo (el validador del C04 compara en valor absoluto y deja la base
      -- en positivo en el apunte).
      v_clave, v_calif, v_exenta,
      -- V03 E2 (0146): un apunte exento es la base, no la cuota: cuota 0, y la
      -- base con el signo de su importe.
      v_base, l.rate, v_cuota, nullif(l.surcharge_rate, 0), v_base + v_cuota,
      case when l.vat_book in ('received', 'investment') and l.vat_deductible = 'yes' then v_cuota when l.vat_book in ('received', 'investment') then 0 end,
      v_isp, v_inv, v_ret_tipo, v_ret,
      case when v_iae is null then null else v_act_code end, case when v_iae is null then null else v_act_tipo end, v_iae,
      v_corrige, v_e.source_type, v_e.source_id,
      case when v_e.status = 'anulado' then coalesce(v_e.voided_at, now()) end, v_e.voided_by_entry_id);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


--
-- Name: FUNCTION conta_vat_book_desde_asiento(p_entry uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_vat_book_desde_asiento(p_entry uuid) IS 'C05. Crea las filas del libro registro de un asiento validado (o anulado: nacen anuladas). Idempotente. La llama el disparador de la 0120.';


--
-- Name: conta_vence_de_cierre(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_vence_de_cierre(p_entry uuid) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select public.conta_vence_por_plataforma(s.account_id, s.channel_id, s.sales_day)
    from public.sales_day_summary s
   where s.entry_id = p_entry and s.channel_id is not null and s.unit_key is not null
   limit 1
$$;


--
-- Name: conta_vence_de_factura(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_vence_de_factura(p_invoice uuid) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select public.conta_vence_por_plataforma(ci.account_id, public.conta_canal_de_factura(ci.id),
           coalesce((select s.sales_day from public.sales_day_summary s where s.entry_id = ci.entry_id and s.company_id = ci.company_id and s.channel_id is not null limit 1), ci.issue_date))
    from public.customer_invoice ci where ci.id = p_invoice
$$;


--
-- Name: conta_vence_por_plataforma(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_vence_por_plataforma(p_account uuid, p_channel uuid, p_dia date) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with r as (
    select settlement_every, payout_days_after, coalesce(payout_margin_days, 5) as margen
      from public.party_role
     where account_id = p_account and role = 'platform' and channel_id = p_channel
       and settlement_every is not null and payout_days_after is not null
     order by created_at limit 1
  )
  select (case r.settlement_every
            -- Semana de lunes a domingo: cierra el domingo.
            when 'weekly' then date_trunc('week', p_dia)::date + 6
            -- Quincenas del 1 al 15 y del 16 a fin de mes.
            when 'fortnightly' then case when extract(day from p_dia) <= 15 then date_trunc('month', p_dia)::date + 14
                                         else (date_trunc('month', p_dia) + interval '1 month')::date - 1 end
            when 'monthly' then (date_trunc('month', p_dia) + interval '1 month')::date - 1
          end) + r.payout_days_after + r.margen
    from r
$$;


--
-- Name: FUNCTION conta_vence_por_plataforma(p_account uuid, p_channel uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conta_vence_por_plataforma(p_account uuid, p_channel uuid, p_dia date) IS 'PC01 · Vencimiento de lo vendido un día por el canal de una plataforma: fin de su periodo + días hasta el pago + margen (5 si no se dice). Null sin plazo.';


--
-- Name: conta_venta_borrar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_venta_borrar(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_f public.customer_invoice;
begin
  select * into v_f from public.customer_invoice where id = p_id for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta borra borradores.' using errcode = '42501';
  end if;
  if v_f.status <> 'borrador' then
    raise exception 'La factura % ya está emitida: no se borra nunca. Se corrige con «Corregir».', v_f.number_text using errcode = '23514';
  end if;
  delete from public.customer_invoice where id = p_id;
  return jsonb_build_object('id', p_id, 'borrado', true, 'total', v_f.total);
end $$;


--
-- Name: conta_venta_cobrar(uuid, date, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_venta_cobrar(p_id uuid, p_fecha date, p_importe numeric, p_forma text, p_nota text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_f public.customer_invoice; v_cobrado numeric; v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor()); v_queda numeric;
  v_pago uuid; v_cta430 text; v_cta570 text; v_r jsonb; v_entry uuid; v_val jsonb; v_lado jsonb; v_fecha date;
begin
  select * into v_f from public.customer_invoice where id = p_id for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta apunta cobros.' using errcode = '42501';
  end if;
  if v_f.status <> 'emitida' or v_f.total <= 0 then raise exception 'Solo se cobra una factura emitida con importe a cobrar.' using errcode = '23514'; end if;
  if p_importe is null or p_importe <= 0 then raise exception 'El cobro tiene que ser mayor que cero.' using errcode = '22023'; end if;
  select coalesce(sum(amount), 0) into v_cobrado from public.customer_invoice_payment where invoice_id = p_id;
  v_queda := v_f.total - v_cobrado;
  if p_importe > v_queda then
    raise exception 'Quedan % € por cobrar de la %: no se puede apuntar %.', to_char(v_queda, 'FM999G999G990D00'), v_f.number_text, to_char(p_importe, 'FM999G999G990D00') using errcode = '22023';
  end if;
  v_fecha := coalesce(p_fecha, (now() at time zone 'Europe/Madrid')::date);
  insert into public.customer_invoice_payment (account_id, company_id, invoice_id, paid_on, amount, method, note, created_by, created_by_name)
  values (v_f.account_id, v_f.company_id, p_id, v_fecha, p_importe, nullif(btrim(p_forma), ''), nullif(btrim(p_nota), ''), auth.uid(), v_quien)
  returning id into v_pago;
  -- V01 entrega 2 (Julio, 24/10): el cobro en efectivo no pasa por el banco,
  -- así que nadie más haría su asiento. Lo hace aquí, validado: 570 a 430 (la
  -- 430 que cobra en el asiento de la factura). Por banco, sigue sin asiento.
  if lower(btrim(coalesce(p_forma, ''))) = 'efectivo' then
    select a.code into v_cta430 from public.journal_line l join public.company_account a on a.id = l.company_account_id
     where l.entry_id = v_f.entry_id and a.code like '43%' and l.debit > 0 order by l.debit desc, l.position limit 1;
    if v_cta430 is null then raise exception 'No encuentro la 430 en el asiento de la %: el cobro en efectivo no se puede asentar.', v_f.number_text using errcode = '23514'; end if;
    select code into v_cta570 from public.company_account where company_id = v_f.company_id and coalesce(template_code, code) like '570%' order by code limit 1;
    if v_cta570 is null then
      v_r := public.company_account_add(v_f.company_id, '5700', 'Caja', null, null, null, v_quien, 'manual');
      v_cta570 := v_r->>'code';
    end if;
    v_lado := case when v_f.location_id is not null then jsonb_build_object('local_id', v_f.location_id) else jsonb_build_object('comun', true) end;
    v_r := public._journal_entry_proponer(v_f.company_id,
      jsonb_build_object('series', 4, 'fecha', v_fecha, 'source_type', 'customer_invoice', 'source_id', v_pago,
        'concepto', 'Cobro en efectivo de la factura ' || v_f.number_text, 'party_id', v_f.party_id, 'documento', v_f.number_text, 'fecha_documento', v_f.issue_date,
        'confianza', 'seguro', 'porque', 'Cobro en efectivo apuntado en la factura.'),
      jsonb_build_array(
        jsonb_build_object('cuenta', v_cta570, 'documento', v_f.number_text, 'concepto', 'Cobro en efectivo ' || v_f.number_text, 'debe', p_importe, 'haber', 0) || v_lado,
        jsonb_build_object('cuenta', v_cta430, 'tercero_id', v_f.party_id, 'documento', v_f.number_text, 'concepto', 'Cobro en efectivo ' || v_f.number_text, 'debe', 0, 'haber', p_importe) || v_lado),
      null, v_quien, auth.uid());
    v_entry := (v_r->>'id')::uuid;
    v_val := public.journal_entry_validar(v_entry, v_quien);
    update public.customer_invoice_payment set entry_id = v_entry where id = v_pago;
  end if;
  v_queda := v_queda - p_importe;
  perform public._conta_venta_evento(p_id, 'cobro',
    'Cobro de ' || to_char(p_importe, 'FM999G999G990D00') || ' €' || coalesce(' en efectivo, con su asiento nº ' || (v_val->>'numero'), '')
      || case when v_queda = 0 then ': cobrada entera.' else '; quedan ' || to_char(v_queda, 'FM999G999G990D00') || ' €.' end,
    jsonb_build_object('importe', p_importe, 'fecha', p_fecha, 'asiento', v_entry), v_quien);
  return jsonb_build_object('id', p_id, 'cobrado', v_cobrado + p_importe, 'queda', v_queda, 'asiento', v_entry, 'numero_asiento', v_val->'numero');
end $$;


--
-- Name: conta_venta_corregir(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_venta_corregir(p_id uuid, p_tipo text, p_motivo text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_f public.customer_invoice; v_id uuid; v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor()); v_c jsonb;
begin
  select * into v_f from public.customer_invoice where id = p_id for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta corrige facturas.' using errcode = '42501';
  end if;
  if v_f.status <> 'emitida' then raise exception 'Solo se corrige una factura emitida y viva (esta está %).', v_f.status using errcode = '23514'; end if;
  if v_f.doc_type = 'rectificativa' then raise exception 'Una rectificativa no se corrige con otra: corrige la factura de origen.' using errcode = '23514'; end if;
  if p_tipo not in ('importes', 'anular', 'datos') then raise exception 'Qué se corrige: importes, anular o datos.' using errcode = '22023'; end if;
  if v_f.origin = 'cierre_dia' and p_tipo = 'datos' then
    raise exception 'Una factura resumen de un cierre no lleva cliente: se corrigen sus importes o se anula.' using errcode = '22023';
  end if;
  if exists (select 1 from public.customer_invoice where corrects_id = p_id and status = 'borrador') then
    select id into v_id from public.customer_invoice where corrects_id = p_id and status = 'borrador' limit 1;
    return jsonb_build_object('id', v_id, 'ya_estaba', true);
  end if;
  insert into public.customer_invoice (account_id, company_id, doc_type, origin, series_code, issue_date, due_date, party_id, customer, location_id,
                                    payment_method_id, notes, email_to, withholding_rate_id, surcharge, corrects_id, correction_kind, correction_reason,
                                    created_by, created_by_name)
  values (v_f.account_id, v_f.company_id, 'rectificativa', v_f.origin, 'R', (now() at time zone 'Europe/Madrid')::date, null, v_f.party_id, v_f.customer, v_f.location_id,
          v_f.payment_method_id, null, v_f.email_to, v_f.withholding_rate_id, v_f.surcharge, p_id, p_tipo, nullif(btrim(p_motivo), ''), auth.uid(), v_quien)
  returning id into v_id;
  -- Las líneas de la original: lo que se cambia en «importes»; en «anular» y
  -- «datos», solo se enseñan (la diferencia no las usa).
  insert into public.customer_invoice_line (account_id, company_id, invoice_id, position, concept, quantity, unit_price, discount_pct, tax_rate_id, tax_pct, surcharge_pct, revenue_account_id, amount)
  select account_id, company_id, v_id, position, concept, quantity, unit_price, discount_pct, tax_rate_id, tax_pct, surcharge_pct, revenue_account_id, amount
    from public.customer_invoice_line where invoice_id = p_id;
  v_c := public._conta_venta_diferencia(v_id);
  update public.customer_invoice set base = (v_c->>'base')::numeric, tax = (v_c->>'iva')::numeric, surcharge_amount = (v_c->>'recargo')::numeric,
         withholding_amount = (v_c->>'retencion')::numeric, total = (v_c->>'total')::numeric where id = v_id;
  perform public._conta_venta_evento(v_id, 'creada', 'Rectificativa de la ' || v_f.number_text || ' preparada (' ||
    case p_tipo when 'anular' then 'anularla entera' when 'datos' then 'datos del cliente' else 'importes o líneas' end || ').', jsonb_build_object('corrige', p_id), v_quien);
  return jsonb_build_object('id', v_id, 'ya_estaba', false, 'total', (v_c->>'total')::numeric);
end $$;


--
-- Name: conta_venta_emitir(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_venta_emitir(p_id uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.customer_invoice; v_orig public.customer_invoice; v_c jsonb; v_anio int; v_num int; v_texto text; v_serie text; v_digitos int := 4;
  v_empieza int; v_por_anio boolean; v_cta430 text; v_r jsonb; v_lineas jsonb := '[]'::jsonb; v_x jsonb; v_cta text; v_cta477 text; v_cta473 text; v_entry uuid; v_val jsonb;
  v_nombre text; v_signo numeric; v_prev text; v_hash text; v_emisor text; v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
  v_tipo_libro text; v_nif text; v_esta jsonb; v_cierre boolean;
  v_falta text; v_trato text;
begin
  select * into v_f from public.customer_invoice where id = p_id for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta emite facturas.' using errcode = '42501';
  end if;
  if v_f.status <> 'borrador' then raise exception 'La factura % ya está emitida.', v_f.number_text using errcode = '23514'; end if;
  -- V01 entrega 2: una factura resumen de un cierre no lleva cliente; se emite
  -- al validar su cierre, y aquí solo llega su rectificativa.
  v_cierre := v_f.origin = 'cierre_dia';
  if v_cierre and v_f.doc_type <> 'rectificativa' then
    raise exception 'Una factura resumen se emite al validar su cierre, en Ventas › Cierres del día.' using errcode = '23514';
  end if;
  v_nombre := v_f.customer->>'nombre';
  v_nif := v_f.customer->>'nif';
  if not v_cierre then
    if v_f.party_id is null then raise exception 'Falta el cliente: elige uno de Contactos o dalo de alta.' using errcode = '23514'; end if;
    if coalesce(btrim(v_nif), '') = '' then
      raise exception 'Falta el NIF de %: una factura lo lleva. Ponlo en su ficha de Contactos.', coalesce(v_nombre, 'el cliente') using errcode = '23514';
    end if;
  end if;

  if v_f.doc_type = 'rectificativa' then
    select * into v_orig from public.customer_invoice where id = v_f.corrects_id;
    if v_orig.status <> 'emitida' then raise exception 'La factura que se corrige (%) no está emitida o ya está anulada.', v_orig.number_text using errcode = '23514'; end if;
    if coalesce(btrim(v_f.correction_reason), '') = '' then raise exception 'Falta el motivo de la corrección: va en la factura.' using errcode = '23514'; end if;
    v_c := public._conta_venta_diferencia(p_id);
    if v_f.correction_kind = 'importes' and (v_c->>'total')::numeric = 0 and (v_c->>'base')::numeric = 0 then
      raise exception 'Las líneas son iguales que las de %: no hay nada que corregir.', v_orig.number_text using errcode = '23514';
    end if;
  else
    if not exists (select 1 from public.customer_invoice_line where invoice_id = p_id) then raise exception 'La factura no tiene líneas.' using errcode = '23514'; end if;
    v_c := public._conta_venta_cifras(p_id);
    if (v_c->>'total')::numeric <= 0 then raise exception 'El total de la factura es %: una factura va en positivo (para restar, «Corregir» la que toca).', v_c->>'total' using errcode = '23514'; end if;
  end if;

  -- V03 E2 · Una línea sin IVA necesita su porqué, con Verifactu encendido o
  -- no: la ley pide en la factura la causa de la exención o de la no sujeción
  -- (RD 1619/2012, art. 6.1.j), y el libro y el 303 la necesitan. La regla y
  -- sus frases son las de la comprobación de Verifactu (tablero 27). Antes del
  -- número: si falta, la factura sigue en borrador y no gasta ninguno. La
  -- rectificativa hereda el porqué de la que corrige.
  if v_f.doc_type = 'rectificativa' and not exists (select 1 from public.verifactu_operacion where invoice_id = p_id) then
    insert into public.verifactu_operacion (invoice_id, account_id, company_id, calificacion, exenta, clave_regimen, updated_by_name)
    select p_id, o.account_id, o.company_id, o.calificacion, o.exenta, o.clave_regimen, v_quien
      from public.verifactu_operacion o where o.invoice_id = v_f.corrects_id and o.account_id = v_f.account_id;
  end if;
  select x->>'frase' into v_falta from jsonb_array_elements(public._verifactu_desglose(p_id)->'faltas') x
   where x->>'campo' = 'tipo_venta' limit 1;
  if v_falta is not null then
    raise exception '%', v_falta using errcode = '23514', hint = 'tipo_venta';
  end if;

  -- El número: su serie (la de la empresa en Numeración, si la tiene: sus
  -- cifras, por dónde empieza y si vuelve a 1 cada año; si no, 4 cifras, desde
  -- el 1 y por año) y el año de la fecha.
  v_serie := v_f.series_code;
  select digits, starts_at, reset_yearly into v_digitos, v_empieza, v_por_anio
    from public.invoice_series where company_id = v_f.company_id and code = v_serie and is_active;
  v_digitos := coalesce(v_digitos, 4); v_empieza := coalesce(v_empieza, 1); v_por_anio := coalesce(v_por_anio, true);
  v_anio := extract(year from v_f.issue_date)::int;
  insert into public.customer_invoice_counter (company_id, account_id, series_code, fiscal_year, last_number)
  values (v_f.company_id, v_f.account_id, v_serie, case when v_por_anio then v_anio else 0 end, v_empieza)
  on conflict (company_id, series_code, fiscal_year) do update set last_number = public.customer_invoice_counter.last_number + 1
  returning last_number into v_num;
  v_texto := v_serie || '-' || case when v_por_anio then v_anio || '/' else '' end || lpad(v_num::text, v_digitos, '0');

  -- La 430 del cliente: la suya, o una nueva de la 4300 con su nombre. La de
  -- una factura resumen, la del canal: la que cobra en el asiento de su cierre.
  if v_cierre then
    select a.code into v_cta430 from public.journal_line l join public.company_account a on a.id = l.company_account_id
     where l.entry_id = v_orig.entry_id and a.code like '43%' and l.debit > 0 order by l.debit desc, l.position limit 1;
    if v_cta430 is null then raise exception 'No encuentro la 430 del canal en el asiento de la %.', v_orig.number_text using errcode = '23514'; end if;
  end if;
  if v_cta430 is null then
  select a.code into v_cta430 from public.company_account_link k join public.company_account a on a.id = k.company_account_id
   where k.company_id = v_f.company_id and k.entity = 'customer' and k.entity_id = v_f.party_id::text and k.role = 'principal' limit 1;
  if v_cta430 is null then
    v_r := public.company_account_add(v_f.company_id, '4300', 'Clientes · ' || coalesce(v_nombre, 'cliente'), null, 'customer', v_f.party_id::text, v_quien, 'manual');
    v_cta430 := v_r->>'code';
  end if;
  end if;

  -- El asiento: 430 por el total; 70x por cuenta; 477 por tipo (con su libro);
  -- el recargo a la misma 477, sin libro; la retención a la 473. Una
  -- rectificativa en negativo pone cada importe en el otro lado.
  v_signo := case when (v_c->>'total')::numeric < 0 then -1 else 1 end;
  if (v_c->>'total')::numeric <> 0 then
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_cta430, 'tercero_id', v_f.party_id, 'documento', v_texto, 'concepto', 'Factura ' || v_texto,
      'debe', case when v_signo > 0 then (v_c->>'total')::numeric else 0 end, 'haber', case when v_signo < 0 then -(v_c->>'total')::numeric else 0 end));
  end if;
  -- V03 E2: la 70x por cuenta Y, dentro de ella, la parte sin IVA aparte: esa
  -- parte es la base de su tipo exento y lleva en su apunte el tipo, la base y
  -- el libro (no hay 477 a cero). Por cuenta suma lo mismo que v_c->'cuentas'
  -- (las mismas líneas: las suyas y, en una rectificativa, menos las de la que
  -- corrige; «datos» no cambia importes y «anular» deja las nuevas a cero).
  for v_x in
    with d as (
      select l.revenue_account_id as c, case when t.treatment = 'exempt' then l.tax_rate_id end as k, l.amount as b
        from public.customer_invoice_line l join public.tax_rate t on t.id = l.tax_rate_id
       where l.invoice_id = p_id and coalesce(v_f.correction_kind, '') not in ('anular', 'datos')
      union all
      select l.revenue_account_id, case when t.treatment = 'exempt' then l.tax_rate_id end, -l.amount
        from public.customer_invoice_line l join public.tax_rate t on t.id = l.tax_rate_id
       where v_f.doc_type = 'rectificativa' and coalesce(v_f.correction_kind, '') <> 'datos' and l.invoice_id = v_f.corrects_id)
    select jsonb_build_object('cuenta_id', c, 'tipo_id', k, 'base', sum(b)) from d group by c, k having sum(b) <> 0 order by c, k nulls first
  loop
    select code into v_cta from public.company_account where id = (v_x->>'cuenta_id')::uuid;
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_cta, 'tercero_id', v_f.party_id, 'documento', v_texto, 'concepto', 'Factura ' || v_texto,
      'haber', greatest((v_x->>'base')::numeric, 0), 'debe', greatest(-(v_x->>'base')::numeric, 0))
      || case when v_x->>'tipo_id' is not null
              then jsonb_build_object('iva', jsonb_build_object('tipo_id', v_x->>'tipo_id', 'base', abs((v_x->>'base')::numeric), 'libro', 'issued', 'facturas', 1))
              else '{}'::jsonb end);
  end loop;
  for v_x in select * from jsonb_array_elements(v_c->'tipos') loop
    -- V03 E2: el tipo exento no lleva 477 (va en su 70x, arriba).
    select treatment into v_trato from public.tax_rate where id = (v_x->>'tipo_id')::uuid;
    continue when v_trato = 'exempt';
    select a.code into v_cta477 from public.company_account_link k join public.company_account a on a.id = k.company_account_id
     where k.company_id = v_f.company_id and k.entity = 'tax_rate' and k.entity_id = v_x->>'tipo_id' and k.role = 'repercutido' limit 1;
    if v_cta477 is null then
      select code into v_cta477 from public.company_account where company_id = v_f.company_id and code like '477%' and code <> '47700000'
         and (name ilike '%' || to_char((v_x->>'pct')::numeric, 'FM990') || ' %%' or name ilike '%' || to_char((v_x->>'pct')::numeric, 'FM990') || '%') order by code limit 1;
    end if;
    if v_cta477 is null then raise exception 'Falta en tu plan la 477 del IVA repercutido al % %%.', to_char((v_x->>'pct')::numeric, 'FM990D##') using errcode = '23514'; end if;
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_cta477, 'tercero_id', v_f.party_id, 'documento', v_texto, 'concepto', 'IVA factura ' || v_texto,
      'haber', greatest((v_x->>'iva')::numeric, 0), 'debe', greatest(-(v_x->>'iva')::numeric, 0),
      'iva', jsonb_build_object('tipo_id', v_x->>'tipo_id', 'base', abs((v_x->>'base')::numeric), 'libro', 'issued', 'facturas', 1)));
    if (v_x->>'rec')::numeric <> 0 then
      v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_cta477, 'tercero_id', v_f.party_id, 'documento', v_texto, 'concepto', 'Recargo de equivalencia factura ' || v_texto,
        'haber', greatest((v_x->>'rec')::numeric, 0), 'debe', greatest(-(v_x->>'rec')::numeric, 0)));
    end if;
  end loop;
  if (v_c->>'retencion')::numeric <> 0 then
    -- La retención que te hace el cliente es un pago a cuenta TUYO: 473. El
    -- enlace «retención → cuenta» de la empresa es el de las compras (4751, la
    -- que tú ingresas por otros), y aquí no vale.
    select code into v_cta473 from public.company_account where company_id = v_f.company_id and coalesce(template_code, code) like '473%' order by code limit 1;
    if v_cta473 is null then
      v_r := public.company_account_add(v_f.company_id, '4730', 'Retenciones que te hacen tus clientes', null, null, null, v_quien, 'manual');
      v_cta473 := v_r->>'code';
    end if;
    v_lineas := v_lineas || jsonb_build_array(jsonb_build_object('cuenta', v_cta473, 'tercero_id', v_f.party_id, 'documento', v_texto, 'concepto', 'Retención factura ' || v_texto,
      'debe', greatest((v_c->>'retencion')::numeric, 0), 'haber', greatest(-(v_c->>'retencion')::numeric, 0)));
  end if;

  -- Cada apunte, con el local de la factura o «común» (la analítica por local lo pide al validar).
  select coalesce(jsonb_agg(x || case when v_f.location_id is not null then jsonb_build_object('local_id', v_f.location_id) else jsonb_build_object('comun', true) end order by i), '[]'::jsonb)
    into v_lineas from jsonb_array_elements(v_lineas) with ordinality as t(x, i);
  if jsonb_array_length(v_lineas) > 0 then
    v_r := public._journal_entry_proponer(v_f.company_id,
      jsonb_build_object('series', 1, 'fecha', v_f.issue_date, 'source_type', 'customer_invoice', 'source_id', p_id,
        'concepto', 'Factura ' || v_texto || ' · ' || coalesce(v_nombre, ''), 'party_id', v_f.party_id, 'documento', v_texto, 'fecha_documento', v_f.issue_date,
        'confianza', 'seguro', 'porque', 'Factura de venta emitida en Sumied.'),
      v_lineas, null, v_quien, auth.uid());
    v_entry := (v_r->>'id')::uuid;
    v_val := public.journal_entry_validar(v_entry, v_quien);
    -- Lo que el libro no sabe de una factura de venta: el tipo, la que corrige,
    -- el recargo y la retención (la primera anotación lleva la retención entera).
    -- La rectificativa de una resumen (simplificadas) es R5.
    v_tipo_libro := case when v_f.doc_type = 'rectificativa' then case when v_cierre then 'R5' else 'R4' end else 'F1' end;
    update public.vat_book_entry v set invoice_type = v_tipo_libro,
           corrects_ref = case when v_f.doc_type = 'rectificativa' then v_orig.number_text end,
           counterpart_name = coalesce(v_nombre, v.counterpart_name),
           surcharge_amount = (select nullif((t->>'rec')::numeric, 0) from jsonb_array_elements(v_c->'tipos') t
                                where t->>'tipo_id' = (select jl.tax_rate_id::text from public.journal_line jl where jl.id = v.line_id)),
           updated_at = now()
     where v.entry_id = v_entry;
    if (v_c->>'retencion')::numeric <> 0 then
      update public.vat_book_entry set withholding_rate = (v_c->>'retencion_pct')::numeric, withholding_amount = (v_c->>'retencion')::numeric
       where id = (select id from public.vat_book_entry where entry_id = v_entry order by created_at, id limit 1);
    end if;
  end if;

  -- La huella encadenada con la emitida anterior de la empresa (para Verifactu).
  select hash into v_prev from public.customer_invoice where company_id = v_f.company_id and status <> 'borrador' and hash is not null order by issued_at desc, id desc limit 1;
  select tax_id into v_emisor from public.company where id = v_f.company_id;
  v_hash := encode(sha256(convert_to(concat_ws('|', v_emisor, v_texto, v_f.issue_date::text, (v_c->>'total')::numeric::text, coalesce(v_prev, '')), 'UTF8')), 'hex');

  update public.customer_invoice set status = 'emitida', fiscal_year = v_anio, number = v_num, number_text = v_texto,
         base = (v_c->>'base')::numeric, tax = (v_c->>'iva')::numeric, surcharge_amount = (v_c->>'recargo')::numeric,
         withholding_amount = (v_c->>'retencion')::numeric, total = (v_c->>'total')::numeric,
         due_date = coalesce(v_f.due_date, v_f.issue_date), entry_id = v_entry, prev_hash = v_prev, hash = v_hash,
         issued_at = now(), issued_by_name = v_quien
   where id = p_id;

  perform public._conta_venta_evento(p_id, 'emitida',
    'Emitida con el nº ' || v_texto || coalesce(' y su asiento nº ' || (v_val->>'numero'), ' (sin asiento: no cambia importes)') || '.',
    jsonb_build_object('asiento', v_entry, 'numero_asiento', v_val->'numero'), v_quien);
  if v_f.doc_type = 'rectificativa' then
    perform public._conta_venta_evento(v_f.corrects_id, 'corregida',
      'Corregida con la ' || v_texto || ' (' || case v_f.correction_kind when 'anular' then 'anulada entera' when 'datos' then 'datos del cliente' else 'importes o líneas' end || '): ' || v_f.correction_reason || '.',
      jsonb_build_object('rectificativa', p_id), v_quien);
    if v_f.correction_kind = 'anular' then
      update public.customer_invoice set status = 'anulada' where id = v_f.corrects_id;
    end if;
  end if;

  select jsonb_build_object('id', p_id, 'numero', v_texto, 'total', (v_c->>'total')::numeric, 'asiento', v_entry, 'numero_asiento', v_val->'numero') into v_esta;
  return v_esta;
end $$;


--
-- Name: conta_venta_enviada(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_venta_enviada(p_id uuid, p_para text, p_texto text, p_detalle jsonb, p_quien_nombre text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_para is not null then update public.customer_invoice set sent_at = now() where id = p_id and status <> 'borrador'; end if;
  perform public._conta_venta_evento(p_id, case when p_para is null then 'correo_no' else 'enviada' end, p_texto, p_detalle, p_quien_nombre);
end $$;


--
-- Name: conta_venta_guardar(uuid, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_venta_guardar(p_company uuid, p_id uuid, p_datos jsonb, p_lineas jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuenta uuid; v_f public.customer_invoice; v_id uuid := p_id; v_l jsonb; v_pos int := 0; v_t public.tax_rate; v_cta uuid;
  v_cli jsonb := '{}'::jsonb; v_party uuid := nullif(p_datos->>'cliente_id', '')::uuid; v_cifras jsonb; v_nuevo boolean := p_id is null;
  v_cant numeric; v_precio numeric; v_dto numeric;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'Solo un administrador o un encargado de la cuenta hace facturas.' using errcode = '42501';
  end if;
  if v_party is not null then
    select jsonb_strip_nulls(jsonb_build_object('nombre', coalesce(f.legal_name, p.name), 'nif', p.tax_id, 'tipo_nif', f.tax_id_type, 'pais', coalesce(f.country_code, 'ES'),
             'calle', f.fiscal_street, 'cp', f.fiscal_postal_code, 'ciudad', f.fiscal_city, 'provincia', f.fiscal_province,
             'nif_comprobado', f.tax_id_check_status = 'valid'))
      into v_cli from public.party p left join public.customer_fiscal f on f.party_id = p.id
     where p.id = v_party and p.account_id = v_cuenta;
    if v_cli is null then raise exception 'Ese cliente no es de esta cuenta.' using errcode = '22023'; end if;
  end if;

  if v_id is null then
    insert into public.customer_invoice (account_id, company_id, created_by, created_by_name)
    values (v_cuenta, p_company, auth.uid(), coalesce(p_quien_nombre, public.conta_nombre_actor()))
    returning id into v_id;
  end if;
  select * into v_f from public.customer_invoice where id = v_id for update;
  if v_f.company_id is distinct from p_company then raise exception 'Esa factura no es de esta empresa.' using errcode = '22023'; end if;
  if v_f.status <> 'borrador' then raise exception 'La factura % ya está emitida: no se cambia. Se corrige con «Corregir».', v_f.number_text using errcode = '23514'; end if;

  -- El recargo de equivalencia aún no: hoy ninguna 477 se valida sin su tipo
  -- y su cuota, y el 303 no sabe dónde va el recargo («recargo» en
  -- conta_impuesto_303_cajas). La columna queda preparada; se abre con su
  -- propio encargo.
  if coalesce((p_datos->>'recargo')::boolean, false) then
    raise exception 'El recargo de equivalencia todavía no se puede facturar desde Sumied: el libro y el 303 aún no saben llevarlo.' using errcode = '0A000';
  end if;

  -- V01 entrega 2: la de un cierre (la rectificativa de una resumen) no lleva
  -- cliente de Contactos: se queda con el suyo («Ventas del día · canal»).
  update public.customer_invoice set
    party_id = case when v_f.origin = 'cierre_dia' then v_f.party_id else v_party end,
    customer = case when v_f.origin = 'cierre_dia' then v_f.customer
                    else coalesce(v_cli, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object('correo', nullif(btrim(p_datos->>'correo'), ''))) end,
    issue_date = coalesce(nullif(p_datos->>'fecha', '')::date, issue_date),
    due_date = nullif(p_datos->>'vence', '')::date,
    series_code = case when v_f.doc_type = 'rectificativa' then 'R' else coalesce(nullif(upper(btrim(p_datos->>'serie')), ''), 'F') end,
    payment_method_id = nullif(p_datos->>'forma_cobro_id', '')::uuid,
    location_id = nullif(p_datos->>'local_id', '')::uuid,
    notes = nullif(btrim(p_datos->>'notas'), ''),
    email_to = nullif(btrim(p_datos->>'correo'), ''),
    withholding_rate_id = nullif(p_datos->>'retencion_id', '')::uuid,
    surcharge = coalesce((p_datos->>'recargo')::boolean, false),
    correction_reason = case when v_f.doc_type = 'rectificativa' then coalesce(nullif(btrim(p_datos->>'motivo'), ''), correction_reason) else null end
  where id = v_id;

  -- Las líneas, de nuevo enteras (una rectificativa para anular no tiene líneas que cambiar).
  if v_f.correction_kind is distinct from 'anular' then
    delete from public.customer_invoice_line where invoice_id = v_id;
    for v_l in select * from jsonb_array_elements(coalesce(p_lineas, '[]'::jsonb)) loop
      v_pos := v_pos + 1;
      select * into v_t from public.tax_rate where id = (v_l->>'tipo_id')::uuid;
      if v_t.id is null or (v_t.company_id is not null and v_t.company_id <> p_company) then
        raise exception 'La línea %: ese tipo de IVA no existe.', v_pos using errcode = '22023';
      end if;
      -- V03 E2: también sin IVA («Exento o 0 %»); su porqué va en tipo_venta.
      if v_t.treatment not in ('taxed', 'exempt') then
        raise exception 'La línea %: «%» aún no se puede facturar aquí (solo IVA general, reducido, superreducido o sin IVA).', v_pos, v_t.name using errcode = '22023';
      end if;
      select id into v_cta from public.company_account where id = (v_l->>'cuenta_id')::uuid and company_id = p_company and code like '7%';
      if v_cta is null then raise exception 'La línea %: la cuenta de ventas no es de esta empresa.', v_pos using errcode = '22023'; end if;
      v_cant := coalesce((v_l->>'cantidad')::numeric, 1);
      v_precio := coalesce((v_l->>'precio')::numeric, 0);
      v_dto := coalesce((v_l->>'descuento')::numeric, 0);
      insert into public.customer_invoice_line (account_id, company_id, invoice_id, position, concept, quantity, unit_price, discount_pct,
                                             tax_rate_id, tax_pct, surcharge_pct, revenue_account_id, amount)
      values (v_cuenta, p_company, v_id, v_pos, btrim(v_l->>'concepto'), v_cant, v_precio, v_dto,
              v_t.id, v_t.rate, v_t.surcharge_rate, v_cta, round(v_cant * v_precio * (1 - v_dto / 100), 2));
    end loop;
  end if;

  -- V03 E2: el porqué de las líneas sin IVA (tablero 27), si viene. null lo quita.
  if p_datos ? 'tipo_venta' then
    if jsonb_typeof(p_datos->'tipo_venta') = 'object' then
      if coalesce(p_datos->'tipo_venta'->>'calificacion', '') not in ('', 'N1', 'N2')
         or coalesce(p_datos->'tipo_venta'->>'exenta', '') not in ('', 'E1', 'E2', 'E3', 'E4', 'E5', 'E6')
         or (nullif(p_datos->'tipo_venta'->>'calificacion', '') is null) = (nullif(p_datos->'tipo_venta'->>'exenta', '') is null) then
        raise exception 'El tipo de venta sin IVA es una de dos: no sujeta (N1, N2) o exenta (E1 a E6).' using errcode = '22023';
      end if;
      perform public.verifactu_operacion_poner(v_id, nullif(p_datos->'tipo_venta'->>'calificacion', ''), nullif(p_datos->'tipo_venta'->>'exenta', ''), null, p_quien_nombre);
    else
      perform public.verifactu_operacion_poner(v_id, null, null, null, p_quien_nombre);
    end if;
  end if;

  v_cifras := case when v_f.doc_type = 'rectificativa' then public._conta_venta_diferencia(v_id) else public._conta_venta_cifras(v_id) end;
  update public.customer_invoice set base = (v_cifras->>'base')::numeric, tax = (v_cifras->>'iva')::numeric, surcharge_amount = (v_cifras->>'recargo')::numeric,
         withholding_amount = (v_cifras->>'retencion')::numeric, total = (v_cifras->>'total')::numeric
   where id = v_id;
  if v_nuevo then
    perform public._conta_venta_evento(v_id, 'creada', 'Borrador creado a mano.', null, p_quien_nombre);
  end if;
  return jsonb_build_object('id', v_id, 'nuevo', v_nuevo, 'total', (v_cifras->>'total')::numeric, 'lineas', v_pos);
end $$;


--
-- Name: conta_venta_pdf_guardar(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_venta_pdf_guardar(p_id uuid, p_ruta text, p_sha256 text, p_bytes integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare v_f public.customer_invoice; v_obj record;
begin
  select * into v_f from public.customer_invoice where id = p_id for update;
  -- Lo llama el navegador de quien emite (el PDF se hace allí, como el resumen
  -- de ventas): sus permisos, y la ruta tiene que ser la de ESTA factura.
  if v_f.id is null or not (public.belongs_to_account(v_f.account_id) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Esa factura no está.' using errcode = 'P0002';
  end if;
  if not (public.current_user_is_admin_or_manager_of(v_f.account_id) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Solo un administrador o un encargado de la cuenta guarda el PDF de una factura.' using errcode = '42501';
  end if;
  if v_f.status = 'borrador' then raise exception 'Un borrador no lleva PDF: se hace al emitir.' using errcode = '23514'; end if;
  if v_f.pdf_sha256 is not null then
    if v_f.pdf_sha256 = p_sha256 then return jsonb_build_object('id', p_id, 'ruta', v_f.pdf_path, 'ya_estaba', true); end if;
    raise exception 'La % ya tiene su PDF: no se cambia.', v_f.number_text using errcode = '23505';
  end if;
  if p_ruta is null or left(p_ruta, length(v_f.account_id::text || '/ventas/' || p_id::text || '/')) <> v_f.account_id::text || '/ventas/' || p_id::text || '/' then
    raise exception 'La ruta del PDF no es la de esta factura.' using errcode = '22023';
  end if;
  select o.name into v_obj from storage.objects o where o.bucket_id = 'conta-documentos' and o.name = p_ruta;
  if v_obj.name is null then raise exception 'El PDF no está subido (%).', p_ruta using errcode = 'P0002'; end if;
  update public.customer_invoice set pdf_path = p_ruta, pdf_sha256 = p_sha256, pdf_bytes = p_bytes where id = p_id;
  -- V01 entrega 2: y junto a su asiento, como el de un cierre, para que el
  -- traspaso del mes lo lleve (una rectificativa de «datos» no tiene asiento).
  if v_f.entry_id is not null and not exists (select 1 from public.journal_entry_document where entry_id = v_f.entry_id and kind = 'factura_expedida') then
    insert into public.journal_entry_document (account_id, company_id, entry_id, kind, storage_path, file_name, sha256, size_bytes, created_by, created_by_name)
    values (v_f.account_id, v_f.company_id, v_f.entry_id, 'factura_expedida', p_ruta,
            'Factura_' || regexp_replace(regexp_replace(v_f.number_text, '[^A-Za-z0-9.-]+', '-', 'g'), '^-+|-+$', '', 'g') || '.pdf',
            p_sha256, coalesce(p_bytes, 0), auth.uid(), public.conta_nombre_actor());
  end if;
  return jsonb_build_object('id', p_id, 'ruta', p_ruta, 'ya_estaba', false);
end $_$;


--
-- Name: conta_vigencia_ok(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conta_vigencia_ok() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare otro uuid;
begin
  if tg_op = 'UPDATE' then
    if new.rate is distinct from old.rate or new.valid_from is distinct from old.valid_from
       or new.code is distinct from old.code then
      raise exception 'Un cambio de porcentaje o de fecha es una fila nueva con su fecha, nunca una edición' using errcode = '23514';
    end if;
  end if;
  if new.valid_to is not null and new.valid_to < new.valid_from then
    raise exception 'La vigencia acaba antes de empezar' using errcode = '23514';
  end if;
  execute format(
    'select id from public.%I where code = $1 and id <> $2 and company_id is not distinct from $3
       and daterange(valid_from, valid_to, ''[]'') && daterange($4, $5, ''[]'') limit 1', tg_table_name)
    into otro using new.code, new.id, new.company_id, new.valid_from, new.valid_to;
  if otro is not null then
    raise exception 'Ya hay otra fila de «%» vigente en esas fechas: cierra la anterior antes de abrir esta', new.code
      using errcode = '23P01';
  end if;
  return new;
end $_$;


--
-- Name: cortes_aprobados(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cortes_aprobados(p_location_id uuid, p_items uuid[]) RETURNS TABLE(recipe_item_id uuid, corte timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT icl.recipe_item_id,
         max(COALESCE(icl.counted_at, ic.started_at, ic.closed_at, ic.created_at))
    FROM public.inventory_count_line icl
    JOIN public.inventory_count ic ON ic.id = icl.inventory_count_id
   WHERE icl.recipe_item_id = ANY(p_items)
     AND icl.excluded_at IS NULL
     AND ic.status = 'aprobado'
     AND ic.location_id = p_location_id
   GROUP BY icl.recipe_item_id;
$$;


--
-- Name: FUNCTION cortes_aprobados(p_location_id uuid, p_items uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cortes_aprobados(p_location_id uuid, p_items uuid[]) IS 'El corte de cada ingrediente en un local: la ultima linea de recuento APROBADO, con la misma vara que usa el motor de recuentos. Es LA definicion; nadie escribe otra.';


--
-- Name: count_lines_requiring_reason(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_lines_requiring_reason(p_count_id uuid) RETURNS TABLE(line_id uuid, item_name text, reasons text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH cab AS (
    SELECT ic.id, ic.account_id FROM public.inventory_count ic WHERE ic.id = p_count_id
  ),
  umbral AS (
    SELECT COALESCE(ss.count_review_pct, 25)::numeric        AS u_pct,
           COALESCE(ss.count_review_eur, 5)::numeric         AS u_eur,
           COALESCE(ss.count_contradiction_pct, 40)::numeric AS u_contra
      FROM cab LEFT JOIN public.supply_settings ss ON ss.account_id = cab.account_id
  ),
  ctx AS (SELECT * FROM public._count_review_context_core(p_count_id)),
  ojo AS (
    SELECT e.line_id
      FROM public.inventory_count_entry e
      JOIN public.inventory_count_line l ON l.id = e.line_id
      JOIN (SELECT e2.line_id AS lid, max(e2.attempt) AS ult
              FROM public.inventory_count_entry e2
              JOIN public.inventory_count_line l2 ON l2.id = e2.line_id
             WHERE l2.inventory_count_id = p_count_id
             GROUP BY e2.line_id) m
        ON m.lid = e.line_id AND m.ult = e.attempt
     WHERE l.inventory_count_id = p_count_id AND e.method = 'fraccion'
     GROUP BY e.line_id
  ),
  base AS (
    SELECT l.id, ri.name,
           abs(COALESCE(l.variance_pct, 0)) AS pct,
           CASE WHEN l.variance_value IS NULL THEN NULL ELSE abs(l.variance_value) END AS eur,
           COALESCE(l.needs_review, false) AS needs_review,
           COALESCE(l.no_reference, false) AS no_reference,
           l.counted_qty,
           c.prev_qty, c.prev_counted_at,
           COALESCE(c.moved_since, 0) AS moved_since,
           COALESCE(c.received_since, 0) AS received_since,
           (o.line_id IS NOT NULL) AS a_ojo
      FROM public.inventory_count_line l
      JOIN public.recipe_item ri ON ri.id = l.recipe_item_id
      LEFT JOIN ctx c ON c.line_id = l.id
      LEFT JOIN ojo o ON o.line_id = l.id
     WHERE l.inventory_count_id = p_count_id AND l.counted_qty IS NOT NULL
       -- Una linea apartada no se aplica, asi que tampoco pide motivo: su
       -- motivo es el de haberla apartado (11/09/2026).
       AND l.excluded_at IS NULL
  ),
  marcadas AS (
    SELECT b.id, b.name,
      array_remove(ARRAY[
        CASE WHEN b.pct >= u.u_pct AND b.eur IS NOT NULL AND b.eur >= u.u_eur
             THEN 'desviacion' END,
        CASE WHEN b.needs_review THEN 'needs_review' END,
        CASE WHEN b.no_reference AND b.counted_qty <> 0 THEN 'sin_referencia' END,
        CASE WHEN b.prev_qty IS NOT NULL AND b.prev_counted_at IS NOT NULL
              AND b.received_since = 0
              AND (b.prev_qty + b.moved_since) > 0
              AND abs(b.counted_qty - (b.prev_qty + b.moved_since))
                  / (b.prev_qty + b.moved_since) * 100 >= u.u_contra
             THEN 'contradiccion' END,
        CASE WHEN b.a_ojo AND b.pct >= u.u_pct THEN 'a_ojo' END
      ], NULL) AS reasons
    FROM base b CROSS JOIN umbral u
  )
  SELECT m.id, m.name, m.reasons FROM marcadas m WHERE cardinality(m.reasons) > 0;
$$;


--
-- Name: FUNCTION count_lines_requiring_reason(p_count_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.count_lines_requiring_reason(p_count_id uuid) IS 'UNA sola regla para «que hay que mirar antes de aprobar»: la usa apply_inventory_count para rechazar y la pantalla para pintar. 11/09/2026: antes la pantalla decia 25 % y 5 euros y la base pedia motivo por la tolerancia ABC de 2/3/5 %, y ofrecia un boton que la base rechazaba.';


--
-- Name: count_review_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_review_context(p_count_id uuid) RETURNS TABLE(line_id uuid, prev_qty numeric, prev_counted_at timestamp with time zone, prev_by_name text, moved_since numeric, received_since numeric, sold_since numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.* FROM public._count_review_context_core(p_count_id) c
   WHERE EXISTS (SELECT 1 FROM public.inventory_count ic
                  WHERE ic.id = p_count_id AND public.belongs_to_account(ic.account_id));
$$;


--
-- Name: FUNCTION count_review_context(p_count_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.count_review_context(p_count_id uuid) IS 'Los hechos que necesita la pantalla de aprobación para explicar una contradicción con nombres, fecha y cantidad: el recuento anterior aprobado y lo que se ha movido desde entonces (§2.4, 10/09/2026). Sólo lectura.';


--
-- Name: courier_advance_by_token(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_advance_by_token(p_token text, p_assignment_id uuid, p_state text, p_note text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier; a public.delivery_assignment;
BEGIN
  c := public._courier_by_token(p_token);
  SELECT * INTO a FROM public.delivery_assignment WHERE id = p_assignment_id;
  IF NOT FOUND OR a.courier_id IS DISTINCT FROM c.id THEN
    RAISE EXCEPTION 'este pedido no es tuyo';
  END IF;
  IF p_state NOT IN ('picked_up','in_delivery','delivered','failed','canceled') THEN
    RAISE EXCEPTION 'estado no válido: %', p_state;
  END IF;

  UPDATE public.delivery_assignment SET
    state          = p_state,
    picked_up_at   = CASE WHEN p_state = 'picked_up'   THEN now() ELSE picked_up_at END,
    in_delivery_at = CASE WHEN p_state = 'in_delivery' THEN now() ELSE in_delivery_at END,
    delivered_at   = CASE WHEN p_state = 'delivered'   THEN now() ELSE delivered_at END,
    failed_at      = CASE WHEN p_state IN ('failed','canceled') THEN now() ELSE failed_at END,
    failed_reason  = CASE WHEN p_state IN ('failed','canceled') THEN coalesce(p_note, failed_reason) ELSE failed_reason END,
    proof_note     = coalesce(p_note, proof_note),
    proof_url      = coalesce(p_proof_url, proof_url),
    proof_type     = CASE WHEN p_proof_url IS NOT NULL THEN 'photo' ELSE proof_type END
  WHERE id = p_assignment_id;

  IF p_state = 'delivered' THEN
    UPDATE public.sale SET order_status = 'completed'
     WHERE id = a.sale_id AND order_status NOT IN ('completed','cancelled','rejected');
  END IF;

  RETURN jsonb_build_object('assignment_id', p_assignment_id, 'state', p_state);
END;
$$;


--
-- Name: courier_claim_by_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_claim_by_token(p_token text, p_assignment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier; v_base numeric; v_surge numeric; v_cost numeric; v_upd uuid; v_sale uuid; v_loc uuid;
BEGIN
  c := public._courier_by_token(p_token);
  IF NOT c.on_shift THEN RAISE EXCEPTION 'ponte en turno para aceptar pedidos'; END IF;

  SELECT da.sale_id, da.location_id INTO v_sale, v_loc FROM public.delivery_assignment da WHERE da.id = p_assignment_id;
  v_base  := coalesce(public.courier_payout(c.id, public.sale_delivery_distance_km(v_sale)), 0);
  v_surge := coalesce(public.location_surge_pct(v_loc), 0);
  v_cost  := round((v_base * (1 + v_surge/100.0))::numeric, 2);

  UPDATE public.delivery_assignment da
     SET courier_id = c.id, state = 'accepted', accepted_at = now(), transport_price = v_cost,
         offered_to = NULL, offer_expires_at = NULL
   WHERE da.id = p_assignment_id
     AND da.state = 'offered'
     AND da.courier_id IS NULL
     AND da.account_id = c.account_id
     AND (c.assigned_locations = '{}'::uuid[] OR da.location_id = ANY(c.assigned_locations))
     AND (da.offered_to IS NULL OR da.offered_to = c.id)
   RETURNING da.id INTO v_upd;

  IF v_upd IS NULL THEN RAISE EXCEPTION 'esa oferta ya fue tomada o no está disponible'; END IF;
  RETURN jsonb_build_object('assignment_id', v_upd, 'state', 'accepted', 'payout', v_cost, 'surge_pct', v_surge);
END;
$$;


--
-- Name: courier_decline_by_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_decline_by_token(p_token text, p_assignment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier;
BEGIN
  c := public._courier_by_token(p_token);
  UPDATE public.delivery_assignment
     SET declined_by = array_append(coalesce(declined_by, '{}'::uuid[]), c.id)
   WHERE id = p_assignment_id
     AND state = 'offered'
     AND courier_id IS NULL
     AND account_id = c.account_id
     AND NOT (c.id = ANY(coalesce(declined_by, '{}'::uuid[])));
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: courier_earnings_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_earnings_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c public.courier;
  v_day_start  timestamptz;
  v_week_start timestamptz;
  v_today  record;
  v_week   record;
  v_quests jsonb;
  v_quest_reward numeric;
  v_history jsonb;
BEGIN
  c := public._courier_by_token(p_token);
  v_day_start  := (date_trunc('day',  now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid';
  v_week_start := (date_trunc('week', now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid';

  SELECT count(*)::int AS deliveries,
         coalesce(sum(da.transport_price),0)::numeric AS earnings,
         coalesce(sum(public.sale_delivery_distance_km(da.sale_id)),0)::numeric AS km
    INTO v_today
    FROM public.delivery_assignment da
   WHERE da.courier_id = c.id AND da.state = 'delivered' AND da.delivered_at >= v_day_start;

  SELECT count(*)::int AS deliveries,
         coalesce(sum(da.transport_price),0)::numeric AS earnings,
         coalesce(sum(public.sale_delivery_distance_km(da.sale_id)),0)::numeric AS km
    INTO v_week
    FROM public.delivery_assignment da
   WHERE da.courier_id = c.id AND da.state = 'delivered' AND da.delivered_at >= v_week_start;

  -- Retos completados (progreso vigente) → suma de sus bonos.
  v_quests := public.courier_quest_progress(c.id);
  SELECT coalesce(sum((q->>'reward')::numeric),0) INTO v_quest_reward
    FROM jsonb_array_elements(v_quests) q
   WHERE (q->>'completed')::boolean;

  -- Histórico últimos 7 días (por fecha local).
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'date', t.day, 'deliveries', t.deliveries, 'earnings', t.earnings) ORDER BY t.day DESC), '[]'::jsonb)
    INTO v_history
    FROM (
      SELECT (da.delivered_at at time zone 'Europe/Madrid')::date AS day,
             count(*)::int AS deliveries,
             coalesce(sum(da.transport_price),0)::numeric AS earnings
        FROM public.delivery_assignment da
       WHERE da.courier_id = c.id AND da.state = 'delivered'
         AND da.delivered_at >= (now() - interval '7 days')
       GROUP BY 1
    ) t;

  RETURN jsonb_build_object(
    'today', jsonb_build_object('deliveries', v_today.deliveries, 'earnings', round(v_today.earnings,2), 'km', round(v_today.km,1)),
    'week',  jsonb_build_object('deliveries', v_week.deliveries,  'earnings', round(v_week.earnings,2),  'km', round(v_week.km,1)),
    'quests', v_quests,
    'quest_reward', round(v_quest_reward,2),
    'week_total', round(v_week.earnings + v_quest_reward, 2),
    'history', v_history
  );
END;
$$;


--
-- Name: courier_feed_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_feed_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier; v jsonb;
BEGIN
  c := public._courier_by_token(p_token);
  SELECT coalesce(jsonb_agg(item ORDER BY sort_key, offered_at), '[]'::jsonb) INTO v
  FROM (
    SELECT
      CASE WHEN da.courier_id = c.id THEN 0 ELSE 1 END AS sort_key,
      da.offered_at,
      jsonb_build_object(
        'assignment_id',    da.id,
        'state',            da.state,
        'mine',             (da.courier_id = c.id),
        'sale_id',          s.id,
        'order_code',       coalesce(s.platform_order_code, s.external_tab_ref, s.external_ref, left(s.id::text,8)),
        'brand',            b.name,
        'brand_logo',       b.logo_url,
        'customer_name',    s.customer_name,
        'customer_phone',   s.customer_phone,
        'total',            s.total,
        'items_count',      (SELECT count(*) FROM public.sale_line sl WHERE sl.sale_id = s.id AND sl.line_type = 'product'),
        'delivery_address', coalesce(NULLIF(j.rt->'delivery'->>'geocodedAddress',''),
                                     NULLIF(j.rt->'delivery'->>'address',''), s.delivery_address),
        'delivery_details', j.rt->'delivery'->>'details',
        'delivery_lat',     g.dlat,
        'delivery_lng',     g.dlng,
        'pickup_name',      l.name,
        'pickup_address',   l.address,
        'pickup_lat',       l.lat,
        'pickup_lng',       l.lng,
        'distance_km',      dk.dist_km,
        'base_payout',      public.courier_payout(c.id, dk.dist_km),
        'surge_pct',        public.location_surge_pct(da.location_id),
        'surge_reason',     public.location_surge_reason(da.location_id),
        'payout',           round((coalesce(public.courier_payout(c.id, dk.dist_km),0)
                                    * (1 + public.location_surge_pct(da.location_id)/100.0))::numeric, 2),
        'offered_at',       da.offered_at
      ) AS item
    FROM public.delivery_assignment da
    JOIN public.sale s      ON s.id = da.sale_id
    LEFT JOIN public.brand b ON b.id = s.brand_id
    LEFT JOIN public.locations l ON l.id = da.location_id
    CROSS JOIN LATERAL (
      SELECT CASE WHEN left(btrim(coalesce(s.raw_tab,'')),1) = '{' THEN s.raw_tab::jsonb ELSE '{}'::jsonb END AS rt
    ) j
    CROSS JOIN LATERAL (
      SELECT NULLIF(j.rt->'delivery'->>'latitude','')::numeric  AS dlat,
             NULLIF(j.rt->'delivery'->>'longitude','')::numeric AS dlng
    ) g
    CROSS JOIN LATERAL (
      SELECT CASE
        WHEN l.lat IS NOT NULL AND l.lng IS NOT NULL AND g.dlat IS NOT NULL AND g.dlng IS NOT NULL
        THEN round((2 * 6371 * asin(sqrt(
               power(sin(radians(g.dlat - l.lat) / 2), 2) +
               cos(radians(l.lat)) * cos(radians(g.dlat)) *
               power(sin(radians(g.dlng - l.lng) / 2), 2)
             )))::numeric, 1)
        ELSE NULL END AS dist_km
    ) dk
    WHERE da.account_id = c.account_id
      AND (
        (da.courier_id = c.id AND da.state IN ('accepted','picked_up','in_delivery'))
        OR
        (da.courier_id IS NULL AND da.state = 'offered'
          AND NOT (c.id = ANY(coalesce(da.declined_by, '{}'::uuid[])))
          AND (c.assigned_locations = '{}'::uuid[] OR da.location_id = ANY(c.assigned_locations))
          AND (da.offered_to IS NULL OR da.offered_to = c.id))
      )
  ) t;
  RETURN v;
END;
$$;


--
-- Name: courier_payout(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_payout(p_courier_id uuid, p_distance_km numeric) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier; v_raw numeric; v_price numeric; v_dist numeric := coalesce(p_distance_km,0); v_val numeric;
BEGIN
  SELECT * INTO c FROM public.courier WHERE id = p_courier_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF c.cost_model = 'per_order' THEN
    RETURN c.cost_value;

  ELSIF c.cost_model = 'per_km' THEN
    v_val := CASE WHEN p_distance_km IS NOT NULL
                  THEN round((coalesce(c.cost_value,0) * p_distance_km)::numeric, 2)
                  ELSE c.cost_value END;
    RETURN CASE WHEN c.rate_max IS NOT NULL AND v_val IS NOT NULL THEN least(v_val, c.rate_max) ELSE v_val END;

  ELSIF c.cost_model = 'tariff' THEN
    IF c.rate_tiers IS NOT NULL AND jsonb_typeof(c.rate_tiers)='array' AND jsonb_array_length(c.rate_tiers) > 0 THEN
      SELECT (t->>'price')::numeric INTO v_price
      FROM jsonb_array_elements(c.rate_tiers) t
      WHERE v_dist <= (t->>'to_km')::numeric
      ORDER BY (t->>'to_km')::numeric ASC LIMIT 1;
      IF v_price IS NULL THEN
        SELECT (t->>'price')::numeric INTO v_price
        FROM jsonb_array_elements(c.rate_tiers) t
        ORDER BY (t->>'to_km')::numeric DESC LIMIT 1;
      END IF;
      v_raw := coalesce(c.rate_pickup_fee,0) + coalesce(v_price,0);
    ELSE
      v_raw := coalesce(c.rate_base,0) + coalesce(c.rate_pickup_fee,0) + coalesce(c.rate_per_km,0) * v_dist;
    END IF;
    v_val := greatest(coalesce(c.rate_min_pickup,0), v_raw);              -- respeta el mínimo de recogida
    RETURN round((CASE WHEN c.rate_max IS NOT NULL THEN least(v_val, c.rate_max) ELSE v_val END)::numeric, 2);

  ELSE
    RETURN NULL;  -- salary / hourly
  END IF;
END;
$$;


--
-- Name: courier_ping_by_token(text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_ping_by_token(p_token text, p_lat numeric, p_lng numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier;
BEGIN
  c := public._courier_by_token(p_token);
  UPDATE public.courier SET last_lat = p_lat, last_lng = p_lng, last_seen_at = now() WHERE id = c.id;
  UPDATE public.sale s SET rider_lat = p_lat, rider_lng = p_lng, rider_seen_at = now()
   WHERE s.id IN (
     SELECT da.sale_id FROM public.delivery_assignment da
     WHERE da.courier_id = c.id AND da.state IN ('accepted','picked_up','in_delivery'));
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: courier_quest_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_quest_progress(p_courier_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with c as (select * from public.courier where id = p_courier_id)
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', qb.id, 'name', qb.name, 'period', qb.period,
    'target', qb.target_count, 'reward', qb.reward,
    'location_id', qb.location_id,
    'done', d.done,
    'completed', (d.done >= qb.target_count)
  ) order by qb.reward desc), '[]'::jsonb)
  from public.courier_bonus qb
  cross join lateral (
    select case when qb.period='day'
      then (date_trunc('day',  now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid'
      else (date_trunc('week', now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid'
    end as start_ts
  ) w
  cross join lateral (
    select count(*)::int as done
    from public.delivery_assignment da
    where da.courier_id = p_courier_id
      and da.state = 'delivered'
      and da.delivered_at >= w.start_ts
      and (qb.location_id is null or da.location_id = qb.location_id)
  ) d
  where qb.account_id = (select account_id from c)
    and qb.is_active
    and (qb.valid_from is null or (now() at time zone 'Europe/Madrid')::date >= qb.valid_from)
    and (qb.valid_to   is null or (now() at time zone 'Europe/Madrid')::date <= qb.valid_to)
    and (qb.location_id is null
         or (select assigned_locations = '{}'::uuid[] or qb.location_id = any(assigned_locations) from c));
$$;


--
-- Name: courier_quests_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_quests_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier;
BEGIN
  c := public._courier_by_token(p_token);
  RETURN public.courier_quest_progress(c.id);
END; $$;


--
-- Name: courier_reset_token(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_reset_token(p_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_tok text; v_acc uuid;
begin
  select account_id into v_acc from courier where id = p_id;
  if v_acc is null or not current_user_is_admin_or_manager_of(v_acc) then raise exception 'forbidden'; end if;
  update courier set access_token = 'cour_'||replace(gen_random_uuid()::text,'-',''), updated_at=now()
   where id = p_id and account_id = any(current_user_account_ids())
   returning access_token into v_tok;
  return v_tok;
end; $$;


--
-- Name: courier_session_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.courier_session_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c public.courier;
BEGIN
  c := public._courier_by_token(p_token);
  RETURN jsonb_build_object(
    'courier_id', c.id, 'name', c.name, 'phone', c.phone,
    'kind', c.kind, 'transport_type', c.transport_type,
    'on_shift', c.on_shift, 'account_id', c.account_id,
    'assigned_locations', to_jsonb(c.assigned_locations)
  );
END;
$$;


