--
-- Name: course_state_for_employee(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_state_for_employee(p_employee_id uuid, p_course_id uuid, p_account_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_position text;
  v_location_id uuid;
  v_requires_practical boolean;
  v_reeval_months int;
  v_applies boolean;
  v_attempt_id uuid;
  v_passed boolean;
  v_signed_at timestamptz;
  v_practical_ok boolean;
  v_caller_employee_id uuid;
begin
  if auth.uid() is not null then
    select employee_id into v_caller_employee_id from public.current_employee_and_account();
    if not (
      coalesce(v_caller_employee_id = p_employee_id, false)
      or public.current_user_is_admin_or_manager_of(p_account_id)
      or public.current_user_is_admin()
    ) then
      raise exception 'course_state_for_employee: sin acceso';
    end if;
  end if;

  select e.position, e.location_id into v_position, v_location_id
  from public.employees e where e.id = p_employee_id;

  select c.requires_practical, c.reeval_months into v_requires_practical, v_reeval_months
  from public.course c where c.id = p_course_id;

  select exists (
    select 1 from public.course_assignment ca
    where ca.course_id = p_course_id and ca.account_id = p_account_id
      and (
        ca.employee_id = p_employee_id
        or (ca.role is not null and ca.role = v_position)
        or (ca.location_id is not null and ca.location_id = v_location_id)
      )
  ) into v_applies;

  if not v_applies then
    return 'no_aplica';
  end if;

  select best.id, best.passed, best.signed_at, best.practical_ok
    into v_attempt_id, v_passed, v_signed_at, v_practical_ok
  from (
    select at.id, at.passed,
      (select max(s.signed_at) from public.course_signature s where s.attempt_id = at.id) as signed_at,
      (
        not exists (
          select 1 from public.course_practical_item pi
          where pi.course_id = p_course_id
            and not exists (
              select 1 from public.course_practical_check pc
              where pc.item_id = pi.id and pc.attempt_id = at.id and pc.checked = true
                and pc.verified_at = (
                  select max(pc2.verified_at) from public.course_practical_check pc2
                  where pc2.item_id = pi.id and pc2.attempt_id = at.id
                )
            )
        )
      ) as practical_ok
    from public.course_attempt at
    join public.course_assignment ca2 on ca2.id = at.assignment_id
    where at.employee_id = p_employee_id and ca2.course_id = p_course_id and ca2.account_id = p_account_id
    order by
      ((select max(s2.signed_at) from public.course_signature s2 where s2.attempt_id = at.id) is not null
       and coalesce(at.passed, false)) desc,
      at.started_at desc
    limit 1
  ) best;

  if v_attempt_id is null then
    return 'pendiente';
  end if;
  if not (v_signed_at is not null and coalesce(v_passed, false)) then
    return 'en_curso';
  end if;
  if v_requires_practical and not coalesce(v_practical_ok, false) then
    return 'pendiente_practica';
  end if;
  if v_reeval_months is null then
    return 'vigente';
  end if;
  if v_signed_at + (v_reeval_months || ' months')::interval > now() then
    return 'vigente';
  end if;
  return 'caducado';
end;
$$;


--
-- Name: crear_enlace_inspeccion(uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crear_enlace_inspeccion(p_employee_id uuid, p_desde date, p_hasta date, p_dias integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acct uuid; v_token text; v_caduca timestamptz;
begin
  v_acct := public._account_of_employee(p_employee_id);
  if v_acct is null or not public.current_user_is_admin_of(v_acct) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El enlace para la Inspección lo crea el administrador.';
  end if;
  if p_hasta < p_desde or p_hasta - p_desde > 366 then
    raise exception 'PERIODO_INVALIDO' using errcode = '22023', hint = 'El periodo va de un día a un año.';
  end if;
  if coalesce(p_dias, 0) not between 1 and 90 then
    raise exception 'CADUCIDAD_INVALIDA' using errcode = '22023', hint = 'El enlace caduca entre 1 y 90 días después.';
  end if;
  v_token := encode(extensions.gen_random_bytes(24), 'hex');
  v_caduca := now() + make_interval(days => p_dias);
  insert into public.registro_jornada_enlace(token, account_id, employee_id, desde, hasta, caduca_at, creado_por)
  values (v_token, v_acct, p_employee_id, p_desde, p_hasta, v_caduca, auth.uid());
  return jsonb_build_object('token', v_token, 'caduca_at', v_caduca);
end $$;


--
-- Name: create_account_gestoria_config_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_account_gestoria_config_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.product_brand IS NOT NULL THEN RETURN NEW; END IF;  -- C06: cuenta solo de contabilidad
  INSERT INTO public.account_gestoria_config (account_id)
  VALUES (NEW.id)
  ON CONFLICT (account_id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: create_account_tx(text, text, uuid, text, text, text, text, uuid[], uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_account_tx(p_account_name text, p_account_slug text, p_admin_user_id uuid, p_admin_display_name text, p_location_name text, p_brand_name text, p_brand_slug text, p_submodule_ids uuid[], p_plan_id uuid, p_status text, p_created_by uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id        uuid;
  v_user_profile_id   uuid;
  v_gerente_total_id  uuid;
  v_platform_admin_id uuid;
  v_plan_code         text;
  v_sub_id            uuid;
  v_sm                uuid;
BEGIN
  SELECT id INTO v_platform_admin_id
  FROM platform_admins WHERE user_id = p_created_by AND active = true LIMIT 1;
  IF v_platform_admin_id IS NULL THEN
    RAISE EXCEPTION 'No existe platform_admin activo para user_id %', p_created_by;
  END IF;

  SELECT id INTO v_gerente_total_id
  FROM permission_sets WHERE name = 'gerente_total' AND is_system = true AND account_id IS NULL LIMIT 1;
  IF v_gerente_total_id IS NULL THEN
    RAISE EXCEPTION 'No existe el permission_set global gerente_total';
  END IF;

  -- Cuenta (dispara triggers AFTER INSERT: appcc, familias ingrediente, gestoría, vacaciones).
  INSERT INTO accounts (name, slug, status, country, created_by)
  VALUES (p_account_name, p_account_slug, p_status, 'ES', p_created_by)
  RETURNING id INTO v_account_id;

  -- Perfil admin + permisos.
  INSERT INTO user_profiles (user_id, account_id, role, active, display_name)
  VALUES (p_admin_user_id, v_account_id, 'admin', true, p_admin_display_name)
  RETURNING id INTO v_user_profile_id;
  INSERT INTO permission_set_assignments (user_profile_id, permission_set_id, assigned_by)
  VALUES (v_user_profile_id, v_gerente_total_id, p_created_by);

  -- Local inicial (nombre del formulario).
  INSERT INTO locations (name, account_id, active)
  VALUES (p_location_name, v_account_id, true);

  -- Marca inicial.
  INSERT INTO brand (account_id, name, slug, ownership_type, is_active)
  VALUES (v_account_id, p_brand_name, p_brand_slug, 'own', true);

  -- Resolver plan_id -> code (default professional si no llega o no existe).
  SELECT code INTO v_plan_code FROM billing_plans WHERE id = p_plan_id;
  IF v_plan_code IS NULL THEN v_plan_code := 'professional'; END IF;

  -- ONBOARDING COMPLETO (suscripción+items del plan, kitchen_settings, canales,
  -- familias de plato, siembra del master con alérgenos). Idempotente: no duplica
  -- la location/suscripción ya creadas aquí.
  PERFORM public.onboard_account(v_account_id, v_plan_code, p_admin_user_id, p_status);

  -- Override opcional: add-ons sueltos extra no incluidos en el plan.
  IF p_submodule_ids IS NOT NULL AND array_length(p_submodule_ids, 1) > 0 THEN
    SELECT id INTO v_sub_id FROM subscriptions WHERE account_id = v_account_id LIMIT 1;
    IF v_sub_id IS NOT NULL THEN
      FOREACH v_sm IN ARRAY p_submodule_ids LOOP
        INSERT INTO subscription_items (subscription_id, submodule_id, quantity, unit_price_eur, status)
        SELECT v_sub_id, v_sm, 1, 0, 'active'
        WHERE NOT EXISTS (
          SELECT 1 FROM subscription_items si
          WHERE si.subscription_id = v_sub_id AND si.submodule_id = v_sm
        );
      END LOOP;
    END IF;
  END IF;

  -- Auditoría.
  INSERT INTO platform_audit_log (platform_admin_id, event_type, target_account_id, target_user_id, details)
  VALUES (
    v_platform_admin_id, 'account_created', v_account_id, p_admin_user_id,
    jsonb_build_object('slug', p_account_slug, 'status', p_status, 'plan', v_plan_code, 'onboarded', true)
  );

  RETURN v_account_id;
END;
$$;


--
-- Name: create_dish_from_unmapped(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_dish_from_unmapped(p_account_id uuid, p_product_name text, p_confirm_create boolean DEFAULT false) RETURNS TABLE(out_recipe_item_id uuid, out_marcas_creadas integer, out_lineas_casadas integer, out_creado boolean, out_candidato_id uuid, out_candidato_nombre text, out_similitud numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_core record; v_norm text; v_sale_id uuid; v_casadas integer := 0;
BEGIN
  SELECT * INTO v_core
    FROM public._create_dish_from_unmapped_core(p_account_id, p_product_name, p_confirm_create);

  IF NOT v_core.out_creado THEN
    out_recipe_item_id := NULL; out_marcas_creadas := 0; out_lineas_casadas := 0;
    out_creado := false; out_candidato_id := v_core.out_candidato_id;
    out_candidato_nombre := v_core.out_candidato_nombre; out_similitud := v_core.out_similitud;
    RETURN NEXT; RETURN;
  END IF;

  v_norm := public.sales_product_norm(p_product_name);

  FOR v_sale_id IN
    SELECT DISTINCT s.id
      FROM sale s JOIN sale_line sl ON sl.sale_id = s.id
     WHERE s.account_id = p_account_id AND s.source = 'lastapp'
       AND s.raw_products IS NOT NULL
       AND coalesce(sl.line_type,'product') = 'product'
       AND public.sales_product_norm(sl.product_name) = v_norm
  LOOP
    PERFORM public.reprocess_sale(v_sale_id);
  END LOOP;

  SELECT count(*) INTO v_casadas
  FROM sale_line sl JOIN sale s ON s.id = sl.sale_id
  WHERE sl.account_id = p_account_id AND s.source = 'lastapp'
    AND sl.menu_item_id IS NOT NULL
    AND public.sales_product_norm(sl.product_name) = v_norm;

  out_recipe_item_id := v_core.out_recipe_item_id;
  out_marcas_creadas := v_core.out_marcas_creadas;
  out_lineas_casadas := v_casadas;
  out_creado := true; out_candidato_id := NULL;
  out_candidato_nombre := NULL; out_similitud := NULL;
  RETURN NEXT;
END;
$$;


--
-- Name: FUNCTION create_dish_from_unmapped(p_account_id uuid, p_product_name text, p_confirm_create boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_dish_from_unmapped(p_account_id uuid, p_product_name text, p_confirm_create boolean) IS 'Crea un plato del TPV que no existe en Folvy (modelo external_catalog_product). Antes de crear comprueba si ya hay un plato MUY parecido (similarity >= 0.6): si lo hay y p_confirm_create=false, devuelve el candidato sin duplicar (out_creado=false). p_confirm_create=true salta el check. Recast acotado al producto (no a toda la cuenta).';


--
-- Name: create_dish_from_unmapped_scoped(uuid, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_dish_from_unmapped_scoped(p_account_id uuid, p_product_name text, p_confirm_create boolean DEFAULT false, p_include_before_last_count boolean DEFAULT false) RETURNS TABLE(out_recipe_item_id uuid, out_marcas_creadas integer, out_lineas_casadas integer, out_creado boolean, out_candidato_id uuid, out_candidato_nombre text, out_similitud numeric, out_ventas_reprocesadas integer, out_ventas_protegidas integer, out_euros_protegidos numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_core record; v_rep record; v_norm text; v_casadas integer := 0;
BEGIN
  SELECT * INTO v_core
    FROM public._create_dish_from_unmapped_core(p_account_id, p_product_name, p_confirm_create);

  IF NOT v_core.out_creado THEN
    out_recipe_item_id := NULL; out_marcas_creadas := 0; out_lineas_casadas := 0;
    out_creado := false; out_candidato_id := v_core.out_candidato_id;
    out_candidato_nombre := v_core.out_candidato_nombre; out_similitud := v_core.out_similitud;
    out_ventas_reprocesadas := 0; out_ventas_protegidas := 0; out_euros_protegidos := 0::numeric;
    RETURN NEXT; RETURN;
  END IF;

  SELECT * INTO v_rep
    FROM public._reprocess_product_sales_scoped(p_account_id, p_product_name, p_include_before_last_count);

  v_norm := public.sales_product_norm(p_product_name);
  SELECT count(*) INTO v_casadas
  FROM sale_line sl JOIN sale s ON s.id = sl.sale_id
  WHERE sl.account_id = p_account_id AND s.source = 'lastapp'
    AND sl.menu_item_id IS NOT NULL
    AND public.sales_product_norm(sl.product_name) = v_norm;

  out_recipe_item_id := v_core.out_recipe_item_id;
  out_marcas_creadas := v_core.out_marcas_creadas;
  out_lineas_casadas := v_casadas;
  out_creado := true; out_candidato_id := NULL;
  out_candidato_nombre := NULL; out_similitud := NULL;
  out_ventas_reprocesadas := v_rep.ventas_reprocesadas;
  out_ventas_protegidas   := v_rep.ventas_protegidas;
  out_euros_protegidos    := v_rep.euros_protegidos;
  RETURN NEXT;
END;
$$;


--
-- Name: create_mirror_item(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_mirror_item(p_account uuid, p_item uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_src menu_item%rowtype;
  v_id  uuid;
begin
  if not (p_account = any(current_user_account_ids())) then raise exception 'forbidden'; end if;

  select * into v_src from menu_item where id = p_item and account_id = p_account;
  if v_src.id is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_src.mirror_of_item_id is not null then return jsonb_build_object('ok', false, 'reason', 'is_mirror'); end if;
  if exists (select 1 from menu_item where mirror_of_item_id = p_item and account_id = p_account) then
    return jsonb_build_object('ok', false, 'reason', 'already_mirrored');
  end if;

  insert into menu_item (
    account_id, brand_id, channel_id, recipe_item_id, name, description, category,
    photo_url, position, price, vat_rate, is_active, is_available, product_type,
    menu_category_id, packaging_cost, packaging_description, source, mirror_of_item_id, created_by)
  values (
    v_src.account_id, v_src.brand_id, v_src.channel_id, v_src.recipe_item_id, v_src.name,
    v_src.description, v_src.category, v_src.photo_url, v_src.position, v_src.price,
    v_src.vat_rate, v_src.is_active, false, v_src.product_type, v_src.menu_category_id,
    v_src.packaging_cost, v_src.packaging_description, v_src.source, v_src.id, auth.uid())
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


--
-- Name: create_platform_admin_tx(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_platform_admin_tx(p_user_id uuid, p_full_name text, p_role text, p_created_by uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_creator_admin_id uuid;
  v_new_admin_id     uuid;
  v_perms            jsonb;
BEGIN
  -- Autorización: el creador debe tener manage_admins.
  IF NOT _user_can_manage_admins(p_created_by) THEN
    RAISE EXCEPTION 'Acceso denegado: requiere el permiso "Gestionar admins".';
  END IF;
  SELECT id INTO v_creator_admin_id
  FROM platform_admins WHERE user_id = p_created_by AND active = true LIMIT 1;

  -- Validaciones.
  IF p_role NOT IN ('ceo','senior_admin','admin','support') THEN
    RAISE EXCEPTION 'Rol inválido: %', p_role;
  END IF;
  IF length(btrim(COALESCE(p_full_name,''))) < 2 THEN
    RAISE EXCEPTION 'El nombre del admin es obligatorio.';
  END IF;
  IF EXISTS (SELECT 1 FROM platform_admins WHERE user_id = p_user_id) THEN
    RAISE EXCEPTION 'Ese usuario ya es administrador de plataforma.';
  END IF;

  -- 1) Fila de platform_admins.
  INSERT INTO platform_admins (user_id, full_name, role, active, created_by)
  VALUES (p_user_id, btrim(p_full_name), p_role, true, p_created_by)
  RETURNING id INTO v_new_admin_id;

  -- 2) Permisos por defecto del rol (matriz de Staff-A).
  v_perms := default_permissions_for_role(p_role);
  INSERT INTO platform_admin_permissions (
    platform_admin_id,
    platform_can_create_accounts, platform_can_suspend_accounts, platform_can_archive_accounts,
    platform_can_delete_accounts, platform_can_edit_seed_data, platform_can_impersonate,
    platform_can_manage_admins, platform_can_reset_2fa_of_others, platform_can_send_global_notifications,
    platform_can_view_audit_log, platform_can_view_system_health, updated_by)
  VALUES (
    v_new_admin_id,
    (v_perms->>'platform_can_create_accounts')::boolean,
    (v_perms->>'platform_can_suspend_accounts')::boolean,
    (v_perms->>'platform_can_archive_accounts')::boolean,
    (v_perms->>'platform_can_delete_accounts')::boolean,
    (v_perms->>'platform_can_edit_seed_data')::boolean,
    (v_perms->>'platform_can_impersonate')::boolean,
    (v_perms->>'platform_can_manage_admins')::boolean,
    (v_perms->>'platform_can_reset_2fa_of_others')::boolean,
    (v_perms->>'platform_can_send_global_notifications')::boolean,
    (v_perms->>'platform_can_view_audit_log')::boolean,
    (v_perms->>'platform_can_view_system_health')::boolean,
    p_created_by);

  -- 3) Auditoría (actor = el creador; insert directo porque aquí no hay sesión).
  INSERT INTO platform_audit_log (platform_admin_id, event_type, target_user_id, details)
  VALUES (
    v_creator_admin_id, 'admin_created', p_user_id,
    jsonb_build_object('admin', btrim(p_full_name), 'role', p_role));

  RETURN v_new_admin_id;
END;
$$;


--
-- Name: create_recipe_version(uuid, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_recipe_version(p_item_id uuid, p_label text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_is_milestone boolean DEFAULT false, p_created_by_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ri recipe_item%ROWTYPE; v_next integer; v_new_id uuid;
BEGIN
  IF p_item_id IS NULL THEN RAISE EXCEPTION 'create_recipe_version: falta el id del plato'; END IF;
  SELECT * INTO v_ri FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'create_recipe_version: receta % no encontrada', p_item_id; END IF;
  IF NOT public.current_user_is_admin_or_manager_of(v_ri.account_id) THEN
    RAISE EXCEPTION 'Sin permiso para versionar esta receta';
  END IF;
  SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next
    FROM recipe_item_version WHERE recipe_item_id = p_item_id;
  UPDATE recipe_item_version SET status = 'superseded', valid_to = now()
   WHERE recipe_item_id = p_item_id AND valid_to IS NULL;
  INSERT INTO recipe_item_version (
    recipe_item_id, version_number, valid_from, valid_to, snapshot,
    computed_cost, status, is_milestone, is_auto, milestone_label, change_note, created_by_name
  ) VALUES (
    p_item_id, v_next, now(), NULL, public._recipe_snapshot(p_item_id),
    v_ri.computed_cost, 'active', COALESCE(p_is_milestone, false), false,
    NULLIF(btrim(p_label), ''), NULLIF(btrim(p_note), ''), NULLIF(btrim(p_created_by_name), '')
  ) RETURNING id INTO v_new_id;
  RETURN v_new_id;
END;
$$;


--
