--
-- Name: cron_generate_daily_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_generate_daily_counts() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_counters uuid[];
  v_per_person integer;
BEGIN
  FOR r IN
    SELECT s.account_id, l.id AS location_id,
           COALESCE(s.autoinventory_per_person, 8) AS per_person
    FROM public.supply_settings s
    JOIN public.locations l ON l.account_id = s.account_id
    WHERE COALESCE(s.autoinventory_enabled, true) = true
      -- 29/08/2026: SOLO LOCALES ACTIVOS. Sin esto se generaba conteo diario
      -- para Foodint Plaza Castilla (629f9154, locations.active = false), un
      -- local dado de baja: 24 lineas y personas asignadas cada dia, y un
      -- rezagado nuevo cada dia que ademas alimentaria la alerta de rezagados
      -- recien creada. La primera alerta del cron arreglado habria nacido
      -- siendo ruido.
      AND COALESCE(l.active, true) = true
  LOOP
    v_counters := public._resolve_day_counters(r.location_id, current_date);
    -- genera y reparte (idempotente: si ya hay cola de hoy, no duplica)
    PERFORM public._generate_daily_count_core(
      r.account_id, r.location_id, v_counters, r.per_person, 80, false);
  END LOOP;
END;
$$;


--
-- Name: cron_kitchen_recompute_all(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_kitchen_recompute_all() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc      record;
  v_res      jsonb;
  v_media    jsonb;
  v_out      jsonb := '[]'::jsonb;
  v_started  timestamptz := clock_timestamp();
begin
  for v_acc in
    select a.id, a.name from accounts a
     where a.status = 'active'
       and a.suspended_at is null
       and a.archived_at  is null
       and a.deleted_at   is null
     order by a.name
  loop
    -- (27/09) Primero las materias primas a media (la ventana caduca sola),
    -- después recetas y platos, que leen ese coste.
    begin
      v_media := public._cost_average_nightly(v_acc.id);
    exception when others then
      v_media := jsonb_build_object('fatal', sqlerrm);
      perform public.encolar_alerta(
        p_kind => 'coste_medio_fallo',
        p_subject => format('Coste medio: la pasada nocturna abortó en %s', v_acc.name),
        p_message => sqlerrm,
        p_debounce_kind => 'coste_medio_fatal:' || v_acc.id,
        p_debounce_window => interval '20 hours',
        p_account_id => v_acc.id,
        p_severity => 'alto');
    end;
    begin
      v_res := public.kitchen_recompute_all(v_acc.id);
    exception when others then
      v_res := jsonb_build_object('account_id', v_acc.id, 'fatal', sqlerrm);
      raise warning 'cron_kitchen_recompute_all: cuenta % (%) abortada: %', v_acc.name, v_acc.id, sqlerrm;
    end;
    v_out := v_out || (jsonb_build_object('account', v_acc.name, 'coste_medio', v_media) || v_res);
  end loop;

  return jsonb_build_object(
    'ran_at',      v_started,
    'duration_ms', round(extract(epoch from clock_timestamp() - v_started) * 1000),
    'accounts',    v_out);
end;
$$;


--
-- Name: cron_parte_plataformas(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_parte_plataformas(p_days integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cuentas integer := 0; v_dias integer := 0;
  v_ced integer := 0; v_pro integer := 0;
  r record; d date; j jsonb;
begin
  for r in
    select a.id from public.accounts a
    where a.status = 'active' and coalesce(a.is_internal, false) = false
  loop
    v_cuentas := v_cuentas + 1;
    for i in 1..greatest(coalesce(p_days,2),1) loop
      d := ((now() at time zone 'Europe/Madrid')::date - i);
      j := public.parte_plataformas_refresh(r.id, d);
      v_ced := v_ced + coalesce((j->>'cedidas')::int, 0);
      v_pro := v_pro + coalesce((j->>'propias')::int, 0);
      v_dias := v_dias + 1;
    end loop;
  end loop;

  raise notice 'cron_parte_plataformas: % cuentas, % días, % cedidas, % propias',
    v_cuentas, v_dias, v_ced, v_pro;

  return jsonb_build_object('cuentas', v_cuentas, 'dias', v_dias,
                            'cedidas', v_ced, 'propias', v_pro);
end;
$$;


--
-- Name: FUNCTION cron_parte_plataformas(p_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cron_parte_plataformas(p_days integer) IS 'La pasada de cada mañana del cruce con las plataformas: ayer y anteayer, solo cuentas activas y no internas. §3.3.';


--
-- Name: cron_recompute_missing_sale_consumption(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_recompute_missing_sale_consumption(p_days integer DEFAULT 7) RETURNS TABLE(sales_reprocessed integer, movements_written integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_n integer := 0; v_mov integer := 0; v_esc integer;
BEGIN
  FOR r IN
    WITH candidatas AS (
      -- a) la de siempre: no ha descontado NADA y es de los ultimos p_days.
      SELECT s.id FROM sale s
       WHERE s.sold_at >= now() - make_interval(days => GREATEST(COALESCE(p_days,7), 1))
         AND NOT EXISTS (SELECT 1 FROM stock_movement sm
                WHERE sm.source_type = 'sale' AND sm.movement_type = 'consumo'
                  AND sm.source_id = s.id)
         AND EXISTS (SELECT 1 FROM sale_line sl
                WHERE sl.sale_id = s.id
                  AND COALESCE(sl.line_type, 'product') = 'product'
                  AND sl.ignored_at IS NULL
                  AND ( EXISTS (SELECT 1 FROM menu_item mi
                                 WHERE mi.id = sl.menu_item_id AND mi.recipe_item_id IS NOT NULL)
                        OR EXISTS (SELECT 1 FROM sale_line c
                                    WHERE c.parent_sale_line_id = sl.id AND c.line_type = 'combo_item') ))
      UNION
      -- b) la nueva: tiene un fallo apuntado sin resolver, TENGA O NO
      --    movimientos. Un consumo a medias no lo veia nadie: la red vieja
      --    preguntaba «¿hay algo?», no «¿esta entero?».
      SELECT f.sale_id FROM sale_consumption_failure f WHERE f.resolved_at IS NULL
    )
    SELECT s.id FROM candidatas c JOIN sale s ON s.id = c.id
     WHERE COALESCE(s.is_active, true)
       AND COALESCE(s.status, '') <> 'cancelled'
       AND COALESCE(s.order_status, '') NOT IN ('cancelled', 'rejected')
       -- REGLA 6: nunca por debajo del ultimo conteo aprobado del local.
       AND s.sold_at > COALESCE(
             (SELECT max(ic.closed_at) FROM inventory_count ic
               WHERE ic.account_id = s.account_id AND ic.location_id = s.location_id
                 AND ic.status = 'aprobado'), '-infinity'::timestamptz)
    ORDER BY s.sold_at
  LOOP
    v_esc := COALESCE(public.generate_sale_consumption(r.id), 0);
    PERFORM public._resolver_fallo_de_consumo(r.id, v_esc);
    v_mov := v_mov + v_esc; v_n := v_n + 1;
  END LOOP;
  IF v_n > 0 THEN
    RAISE NOTICE 'cron_recompute_missing_sale_consumption: % ventas, % movimientos', v_n, v_mov;
  END IF;
  sales_reprocessed := v_n; movements_written := v_mov; RETURN NEXT;
END;
$$;


--
-- Name: ctb_receipt_differences(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ctb_receipt_differences(p_receipt_id uuid) RETURNS TABLE(linea integer, product_name text, doc_qty numeric, qty_received numeric, diferencia numeric, dimension text, valor_eur numeric, motivo text, clase text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acct uuid;
begin
  select account_id into v_acct from goods_receipt where id = p_receipt_id;
  if v_acct is null then
    raise exception 'ctb_receipt_differences: albarán % no existe', p_receipt_id;
  end if;
  if not belongs_to_account(v_acct) then
    raise exception 'ctb_receipt_differences: sin acceso al albarán %', p_receipt_id;
  end if;
  return query select * from public._ctb_receipt_differences_core(p_receipt_id);
end;
$$;


--
-- Name: cuenta_opera(uuid); Type: FUNCTION; Schema: public; Owner: -
