--
-- Name: current_employee_and_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_employee_and_account(OUT employee_id uuid, OUT account_id uuid) RETURNS record
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- DM1 (30/10): la ficha de la cuenta abierta, sin «limit 1» al azar.
  select up.employee_id, up.account_id
  from public.user_profiles up
  where up.user_id = auth.uid()
    and up.active = true
    and up.employee_id is not null
    and up.account_id = public._cuenta_activa();
$$;


--
-- Name: current_user_account_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_account_ids() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when public.current_user_is_admin() then
      -- Superadmin de plataforma: ve todas las cuentas.
      (select coalesce(array_agg(id), '{}') from public.accounts)
    else
      -- DM1 (30/10): la cuenta abierta (con una sola cuenta, esa).
      coalesce(array_remove(array[public._cuenta_activa()], null), '{}')
  end;
$$;


--
-- Name: current_user_can_approve_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_can_approve_invoice(p_invoice_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_account_id uuid;
  v_required text;
BEGIN
  SELECT account_id INTO v_account_id FROM public.supplier_invoice WHERE id = p_invoice_id;
  IF v_account_id IS NULL THEN RETURN false; END IF;
  v_required := public.invoice_required_role(p_invoice_id);
  IF v_required = 'admin' THEN
    RETURN public.current_user_is_admin_of(v_account_id);
  ELSE
    RETURN public.current_user_is_admin_or_manager_of(v_account_id);
  END IF;
END;
$$;


--
-- Name: current_user_has_platform_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_has_platform_permission(p_permission_flag text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_platform_admin_id uuid;
  v_has_permission boolean;
BEGIN
  SELECT pa.id INTO v_platform_admin_id
  FROM platform_admins pa
  WHERE pa.user_id = auth.uid()
    AND pa.active = true
  LIMIT 1;
  
  IF v_platform_admin_id IS NULL THEN
    RETURN false;
  END IF;
  
  BEGIN
    EXECUTE format(
      'SELECT %I FROM platform_admin_permissions WHERE platform_admin_id = $1',
      p_permission_flag
    )
    INTO v_has_permission
    USING v_platform_admin_id;
    
    RETURN COALESCE(v_has_permission, false);
  EXCEPTION
    WHEN undefined_column THEN
      RAISE WARNING 'current_user_has_platform_permission: flag % no existe', p_permission_flag;
      RETURN false;
    WHEN OTHERS THEN
      RAISE WARNING 'current_user_has_platform_permission: error %', SQLERRM;
      RETURN false;
  END;
END;
$_$;


--
-- Name: FUNCTION current_user_has_platform_permission(p_permission_flag text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.current_user_has_platform_permission(p_permission_flag text) IS 'Verifica si el platform_admin actual tiene un flag específico activo.';


--
-- Name: current_user_is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Decisión 3 (C2): platform admin se identifica por presencia en
  -- la tabla platform_admins (separada del concepto user_profile).
  SELECT EXISTS (
    SELECT 1
    FROM public.platform_admins
    WHERE user_id = auth.uid()
      AND active = true
  );
$$;


--
-- Name: FUNCTION current_user_is_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.current_user_is_admin() IS 'Verifica si el usuario actual es platform_admin activo. Decisión 3 (C2) refactor 19/05/2026: ahora consulta tabla platform_admins en lugar de accounts.is_internal.';


--
-- Name: current_user_is_admin_of(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_is_admin_of(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.user_profiles
    where user_id = auth.uid()
      and account_id = p_account_id
      and account_id = public._cuenta_activa()   -- DM1: solo en la abierta
      and role = 'admin'
      and active = true
  ) or public.current_user_is_admin();
$$;


--
-- Name: current_user_is_admin_or_manager_of(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_is_admin_or_manager_of(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.user_profiles me
    where me.user_id = auth.uid()
      and me.account_id = p_account_id
      and me.account_id = public._cuenta_activa()   -- DM1: solo en la abierta
      and me.role = any (array['admin', 'manager'])
      and me.active = true
  ) or public.current_user_is_admin();
$$;


--
-- Name: current_user_is_employee(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_is_employee(p_employee_id uuid, p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.user_profiles up
    where up.user_id = auth.uid()
      and up.account_id = p_account_id
      and up.account_id = public._cuenta_activa()   -- DM1: solo en la abierta
      and up.employee_id = p_employee_id
      and up.active = true
  );
$$;


--
-- Name: current_user_is_office(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_is_office() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.user_profiles up
    where up.user_id = auth.uid()
      and up.active = true
      and up.account_id = public._cuenta_activa()   -- DM1: su rol en la abierta
      and up.role = any (array['admin', 'manager'])
  ) or public.current_user_is_admin();
$$;


--
-- Name: current_user_location_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_location_ids() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when public.current_user_is_admin() then
      (select coalesce(array_agg(id), '{}'::uuid[]) from public.locations)
    when exists (
      select 1 from public.manager_locations ml
      join public.user_profiles up on up.id = ml.user_profile_id
      where up.user_id = auth.uid() and up.active = true
        and up.account_id = public._cuenta_activa()   -- DM1: los de la abierta
    ) then
      (select coalesce(array_agg(distinct ml.location_id), '{}'::uuid[])
         from public.manager_locations ml
         join public.user_profiles up on up.id = ml.user_profile_id
        where up.user_id = auth.uid() and up.active = true
          and up.account_id = public._cuenta_activa())
    when exists (
      select 1 from public.user_profiles up
      where up.user_id = auth.uid() and up.active = true and up.role = 'admin'
        and up.account_id = public._cuenta_activa()
    ) then
      (select coalesce(array_agg(l.id), '{}'::uuid[]) from public.locations l
        where l.account_id = any(public.current_user_account_ids()))
    else '{}'::uuid[]
  end;
$$;


--
-- Name: current_user_manages_location(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_manages_location(p_location_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p_location_id = any(public.current_user_location_ids());
$$;


--
-- Name: current_user_ve_laboral(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_ve_laboral(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.current_user_is_admin_of(p_account_id)
      or exists (
        select 1
          from public.lab_permiso p
          join public.user_profiles up on up.user_id = p.user_id and up.account_id = p.account_id and up.active
         where p.account_id = p_account_id
           and p.user_id = auth.uid()
           and p.account_id = public._cuenta_activa());
$$;


--
-- Name: current_user_ve_persona(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_ve_persona(p_employee_id uuid, p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.current_user_is_admin_of(p_account_id)
      or public.current_user_is_employee(p_employee_id, p_account_id)
      or (exists (select 1 from public.user_profiles up
                   where up.user_id = auth.uid() and up.account_id = p_account_id
                     and up.account_id = public._cuenta_activa()   -- DM1: solo en la abierta
                     and up.role = 'manager' and up.active)
          and exists (select 1 from public.employees e
                       where e.id = p_employee_id and e.account_id = p_account_id
                         and (e.location_id = any (public.current_user_location_ids())
                              or coalesce(e.assigned_locations, '{}'::uuid[]) && public.current_user_location_ids())))
$$;


--
-- Name: FUNCTION current_user_ve_persona(p_employee_id uuid, p_account_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.current_user_ve_persona(p_employee_id uuid, p_account_id uuid) IS 'L1a (27/10): quién ve a una persona. El administrador de la cuenta, a todos; la propia persona; el encargado (manager), a las de sus locales (manager_locations). Un encargado sin locales asignados no ve a nadie: se le asignan en Usuarios.';


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_user_id uuid;
  v_claims jsonb;
  v_folvy_existing jsonb;

  -- Platform admin lookup
  v_is_platform_admin boolean := false;
  v_platform_admin_role text := null;

  -- Active accounts lookup
  v_active_accounts jsonb := '[]'::jsonb;
  v_accounts_count integer := 0;

  -- Current account resolution
  v_current_account_id uuid := null;
  v_current_account_slug text := null;
  v_current_account_role text := null;

  -- Final folvy claim
  v_folvy_claim jsonb;
  v_session_max_age integer;
BEGIN
  -- ==========================================================
  -- 1. Extraer user_id y claims base del payload
  -- ==========================================================
  v_user_id := (event->>'user_id')::uuid;
  v_claims := event->'claims';

  IF v_user_id IS NULL THEN
    -- Edge case: payload sin user_id (no debería pasar nunca, pero defensivo)
    RAISE WARNING '[custom_access_token_hook] user_id is NULL in event payload';
    RETURN event;
  END IF;

  -- ==========================================================
  -- 2. Respetar claim 'folvy' pre-existente (caso impersonation)
  --    Si el JWT secundario de impersonation ya trae folvy.*,
  --    no lo sobrescribimos.
  -- ==========================================================
  v_folvy_existing := v_claims->'folvy';
  IF v_folvy_existing IS NOT NULL
     AND (v_folvy_existing->>'impersonating')::boolean = true THEN
    -- Es un JWT de impersonation, no tocar
    RETURN event;
  END IF;

  -- ==========================================================
  -- 3. Buscar si el user es platform admin activo
  -- ==========================================================
  BEGIN
    SELECT pa.role, true
    INTO v_platform_admin_role, v_is_platform_admin
    FROM public.platform_admins pa
    WHERE pa.user_id = v_user_id
      AND pa.active = true
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[custom_access_token_hook] platform_admin lookup failed: %', SQLERRM;
    v_is_platform_admin := false;
    v_platform_admin_role := null;
  END;

  -- Si no se encontró fila, los DEFAULT se mantienen (false, null)
  IF v_platform_admin_role IS NULL THEN
    v_is_platform_admin := false;
  END IF;

  -- ==========================================================
  -- 4. Buscar user_profiles activos en cuentas no eliminadas
  -- ==========================================================
  BEGIN
    SELECT
      jsonb_agg(
        jsonb_build_object(
          'id', up.account_id,
          'slug', a.slug,
          'role', up.role,
          'profile_id', up.id
        )
        ORDER BY up.created_at DESC
      ),
      COUNT(*)
    INTO v_active_accounts, v_accounts_count
    FROM public.user_profiles up
    INNER JOIN public.accounts a ON a.id = up.account_id
    WHERE up.user_id = v_user_id
      AND up.active = true
      AND a.deleted_at IS NULL
      AND a.suspended_at IS NULL;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[custom_access_token_hook] user_profiles lookup failed: %', SQLERRM;
    v_active_accounts := '[]'::jsonb;
    v_accounts_count := 0;
  END;

  -- Si jsonb_agg no encontró nada, devuelve NULL en lugar de '[]'
  IF v_active_accounts IS NULL THEN
    v_active_accounts := '[]'::jsonb;
    v_accounts_count := 0;
  END IF;

  -- ==========================================================
  -- 5. Resolver current_account_id (D-S2.7: created_at DESC)
  --    El primer elemento del array (ordenado DESC) gana.
  -- ==========================================================
  IF v_accounts_count > 0 THEN
    v_current_account_id := (v_active_accounts->0->>'id')::uuid;
    v_current_account_slug := v_active_accounts->0->>'slug';
    v_current_account_role := v_active_accounts->0->>'role';
  END IF;

  -- ==========================================================
  -- 6. Calcular session_max_age (platform admin: 4h; normal: 7 días)
  -- ==========================================================
  IF v_is_platform_admin THEN
    v_session_max_age := 14400;   -- 4 horas en segundos
  ELSE
    v_session_max_age := 604800;  -- 7 días en segundos
  END IF;

  -- ==========================================================
  -- 7. Construir el claim folvy.*
  -- ==========================================================
  v_folvy_claim := jsonb_build_object(
    'is_platform_admin', v_is_platform_admin,
    'platform_admin_role', v_platform_admin_role,
    'current_account_id', v_current_account_id,
    'current_account_slug', v_current_account_slug,
    'current_account_role', v_current_account_role,
    'active_accounts', v_active_accounts,
    'impersonating', false,
    'real_user_id', null,
    'session_max_age', v_session_max_age
  );

  -- ==========================================================
  -- 8. Inyectar folvy.* en los claims y devolver el event modificado
  -- ==========================================================
  v_claims := jsonb_set(v_claims, '{folvy}', v_folvy_claim);
  event := jsonb_set(event, '{claims}', v_claims);

  RETURN event;

EXCEPTION WHEN OTHERS THEN
  -- Last resort: si algo no capturado falla, devuelve event sin tocar.
  -- Mejor login con JWT sin folvy.* que login bloqueado.
  RAISE WARNING '[custom_access_token_hook] unexpected error: %', SQLERRM;
  RETURN event;
END;
$$;


--
-- Name: customer_addresses(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_addresses(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer uuid;
  v_acc      uuid;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  return jsonb_build_object(
    'ok', true,
    'addresses', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', a.id, 'label', a.label, 'address', a.address, 'detail', a.detail,
               'lat', a.lat, 'lng', a.lng, 'isDefault', a.is_default)
             order by a.is_default desc, a.created_at)
      from customer_address a
      where a.customer_id = v_customer
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: customer_coupons(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_coupons(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer    uuid;
  v_acc         uuid;
  v_has_consent boolean;
  v_freq        coupon%rowtype;
  v_progress    integer := 0;
  v_available   jsonb;
  v_progress_json jsonb;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  select marketing_email into v_has_consent from customer_consent where customer_id = v_customer;
  v_has_consent := coalesce(v_has_consent, false);

  select * into v_freq
  from coupon
  where account_id = v_acc and active and kind = 'frequency'
    and (starts_at is null or starts_at <= now())
    and (ends_at   is null or ends_at   >  now())
  limit 1;

  if v_freq.id is not null and v_freq.frequency_threshold is not null then
    select count(*) into v_progress
    from sale s
    where s.customer_id = v_customer and s.source = 'folvy_shop'
      and coalesce(s.status,'') <> 'cancelled'
      and s.created_at > coalesce((
        select max(cr.ts) from coupon_redemption cr
        join sale cs on cs.id = cr.sale_id
        where cr.coupon_id = v_freq.id and cr.customer_id = v_customer
          and coalesce(cs.status,'') <> 'cancelled'
      ), '-infinity'::timestamptz);
  end if;

  -- Disponibles: cascada estándar. Frecuencia (tarjeta propia) e item_percent
  -- (oferta de carta) EXCLUIDOS. free_delivery entra como bono normal; la lógica
  -- de bienvenida (needs_consent/not_first) es SOLO para kind='standard'.
  v_available := coalesce((
    select jsonb_agg(jsonb_build_object(
             'couponId',      c.id,
             'name',          c.name,
             'code',          c.code,
             'kind',          c.kind,
             'discountType',  c.discount_type,
             'discountValue', c.value,
             'minSubtotal',   c.min_subtotal,
             'endsAt',        c.ends_at,
             'autoApply',     c.auto_apply,
             'isWelcome',     (c.kind = 'standard' and (c.first_order_only or c.auto_apply)),
             'isFrequency',   false,
             'eligible',      (r.reason is null),
             'reason',        r.reason)
           order by (r.reason is null) desc, c.created_at)
    from coupon c
    cross join lateral (
      select case
        when c.kind = 'standard' and (c.first_order_only or c.auto_apply) and not v_has_consent
          then 'needs_consent'
        when c.kind = 'standard' and c.first_order_only and exists (
               select 1 from sale s
               where s.customer_id = v_customer and coalesce(s.status,'') <> 'cancelled'
             )
          then 'not_first'
        when c.budget_max is not null and (
               select coalesce(sum(cr.discount_amount), 0) from coupon_redemption cr
               join sale s on s.id = cr.sale_id
               where cr.coupon_id = c.id and coalesce(s.status,'') <> 'cancelled'
             ) >= c.budget_max
          then 'exhausted'
        when c.max_redemptions is not null and (
               select count(*) from coupon_redemption cr
               join sale s on s.id = cr.sale_id
               where cr.coupon_id = c.id and coalesce(s.status,'') <> 'cancelled'
             ) >= c.max_redemptions
          then 'exhausted'
        when (
               select count(*) from coupon_redemption cr
               join sale s on s.id = cr.sale_id
               where cr.coupon_id = c.id and cr.customer_id = v_customer
                 and coalesce(s.status,'') <> 'cancelled'
             ) >= c.max_per_customer
          then 'per_customer'
        else null
      end as reason
    ) r
    where c.account_id = v_acc and c.active and c.kind not in ('frequency','item_percent')
      and (c.starts_at is null or c.starts_at <= now())
      and (c.ends_at   is null or c.ends_at   >  now())
      and r.reason is distinct from 'per_customer'
  ), '[]'::jsonb);

  if v_freq.id is not null and v_freq.frequency_threshold is not null
     and v_progress >= v_freq.frequency_threshold then
    v_available := jsonb_build_array(jsonb_build_object(
      'couponId',      v_freq.id,
      'name',          v_freq.name,
      'code',          v_freq.code,
      'kind',          v_freq.kind,
      'discountType',  v_freq.discount_type,
      'discountValue', v_freq.value,
      'minSubtotal',   v_freq.min_subtotal,
      'endsAt',        v_freq.ends_at,
      'autoApply',     false,
      'isWelcome',     false,
      'isFrequency',   true,
      'eligible',      true,
      'reason',        null
    )) || v_available;
  end if;

  v_progress_json := case
    when v_freq.id is null or v_freq.frequency_threshold is null then jsonb_build_object('active', false)
    else jsonb_build_object(
      'active',    true,
      'threshold', v_freq.frequency_threshold,
      'current',   least(v_progress, v_freq.frequency_threshold),
      'reward',    jsonb_build_object('discountType', v_freq.discount_type, 'discountValue', v_freq.value, 'name', v_freq.name),
      'earned',    v_progress >= v_freq.frequency_threshold)
  end;

  return jsonb_build_object(
    'ok', true,
    'used', coalesce((
      select jsonb_agg(jsonb_build_object(
               'couponId',       c.id,
               'name',           c.name,
               'code',           c.code,
               'kind',           c.kind,
               'discountType',   c.discount_type,
               'discountValue',  c.value,
               'discountAmount', cr.discount_amount,
               'ts',             cr.ts)
             order by cr.ts desc)
      from coupon_redemption cr
      join coupon c on c.id = cr.coupon_id
      join sale s on s.id = cr.sale_id
      where cr.customer_id = v_customer and coalesce(s.status,'') <> 'cancelled'
        and c.kind not in ('item_percent')
    ), '[]'::jsonb),
    'available', v_available,
    'progress', v_progress_json
  );
end;
$$;


--
-- Name: customer_delete_address(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_delete_address(p_token text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer     uuid;
  v_acc          uuid;
  v_was_default  boolean;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  delete from customer_address
  where id = p_id and customer_id = v_customer
  returning is_default into v_was_default;

  -- Si borramos la predeterminada y quedan otras, promover la más reciente.
  if coalesce(v_was_default, false) then
    update customer_address set is_default = true, updated_at = now()
    where id = (
      select id from customer_address
      where customer_id = v_customer
      order by created_at desc
      limit 1
    );
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: customer_invoice_inalterable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_invoice_inalterable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'borrador' then
      raise exception 'Una factura emitida no se borra nunca: se corrige con su rectificativa.' using errcode = '23514';
    end if;
    return old;
  end if;
  if old.status <> 'borrador' and (
       new.number is distinct from old.number or new.number_text is distinct from old.number_text or new.series_code is distinct from old.series_code
       or new.fiscal_year is distinct from old.fiscal_year or new.issue_date is distinct from old.issue_date or new.customer is distinct from old.customer
       or new.base is distinct from old.base or new.tax is distinct from old.tax or new.total is distinct from old.total
       or new.surcharge_amount is distinct from old.surcharge_amount or new.withholding_amount is distinct from old.withholding_amount
       or new.hash is distinct from old.hash or new.doc_type is distinct from old.doc_type or new.corrects_id is distinct from old.corrects_id
       or (old.pdf_sha256 is not null and new.pdf_sha256 is distinct from old.pdf_sha256)) then
    raise exception 'La factura % ya está emitida: no se cambia. Se corrige con «Corregir».', old.number_text using errcode = '23514';
  end if;
  if old.status = 'anulada' and new.status <> 'anulada' then
    raise exception 'Una factura anulada no vuelve atrás.' using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end $$;


--
-- Name: customer_invoice_line_inalterable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_invoice_line_inalterable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_estado text;
begin
  select status into v_estado from public.customer_invoice where id = coalesce(new.invoice_id, old.invoice_id);
  -- Al borrar un borrador entero (cascada) la factura ya no está: se deja.
  if v_estado is not null and v_estado <> 'borrador' then
    -- V01b: poner la cuota donde no la había, sin tocar nada más, sí.
    if tg_op = 'UPDATE' and old.tax_amount is null and new.tax_amount is not null
       and (to_jsonb(new) - 'tax_amount') = (to_jsonb(old) - 'tax_amount') then
      return new;
    end if;
    raise exception 'Las líneas de una factura emitida no se cambian.' using errcode = '23514';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: customer_logout(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_logout(p_token text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update customer_session set revoked_at = now()
  where token = nullif(btrim(p_token),'') and revoked_at is null
  returning jsonb_build_object('ok', true);
$$;


--
-- Name: customer_orders(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_orders(p_token text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer uuid;
  v_acc      uuid;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  return jsonb_build_object(
    'ok', true,
    'orders', coalesce((
      select jsonb_agg(o.j order by o.created_at desc)
      from (
        select
          jsonb_build_object(
            'saleId',       s.id,
            'code',         s.platform_order_code,
            'date',         s.created_at,
            'total',        s.total,
            'discount',     s.discount_amount,
            'orderStatus',  s.order_status,
            'mode',         nullif(s.raw_tab,'')::jsonb ->> 'mode',
            'brands', coalesce((
              select jsonb_agg(distinct jsonb_build_object(
                       'name', b.name, 'logoUrl', b.logo_url, 'color', b.color))
              from sale_line sl
              join menu_item mi on mi.id = sl.menu_item_id
              join brand b on b.id = mi.brand_id
              where sl.sale_id = s.id and sl.line_type = 'product'
            ), '[]'::jsonb),
            'lines', coalesce((
              select jsonb_agg(jsonb_build_object(
                       'name', sl.product_name, 'qty', sl.quantity, 'photoUrl', mi.photo_url)
                     order by sl.created_at)
              from sale_line sl
              left join menu_item mi on mi.id = sl.menu_item_id
              where sl.sale_id = s.id and sl.line_type = 'product'
            ), '[]'::jsonb),
            'thumbnailUrl', (
              select mi.photo_url
              from sale_line sl
              join menu_item mi on mi.id = sl.menu_item_id
              where sl.sale_id = s.id and sl.line_type = 'product' and mi.photo_url is not null
              order by sl.created_at
              limit 1
            )
          ) as j,
          s.created_at as created_at
        from sale s
        where s.customer_id = v_customer and s.source = 'folvy_shop'
        order by s.created_at desc
        limit greatest(1, coalesce(p_limit, 20))
      ) o
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: customer_reorder_payload(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_reorder_payload(p_token text, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer uuid;
  v_acc      uuid;
  v_sale     sale%rowtype;
  v_raw      jsonb;
  v_brands   jsonb;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  select * into v_sale from sale where id = p_sale_id;
  if v_sale.id is null or v_sale.customer_id is distinct from v_customer or v_sale.source <> 'folvy_shop' then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  v_raw := nullif(v_sale.raw_tab,'')::jsonb;

  -- Marca por menuItemId de las líneas del payload (para poblar el carrito).
  select coalesce(jsonb_object_agg(mi.id::text,
           jsonb_build_object('brandId', mi.brand_id, 'brandName', b.name)), '{}'::jsonb)
  into v_brands
  from (
    select distinct nullif(l->>'menuItemId','')::uuid as mid
    from jsonb_array_elements(coalesce(v_raw->'lines','[]'::jsonb)) l
    where nullif(l->>'menuItemId','') is not null
  ) ids
  join menu_item mi on mi.id = ids.mid and mi.account_id = v_acc
  join brand b on b.id = mi.brand_id;

  return jsonb_build_object(
    'ok', true,
    'payload', jsonb_build_object(
      'locationId', v_raw ->> 'locationId',
      'mode',       coalesce(v_raw ->> 'mode', 'delivery'),
      'lines',      coalesce(v_raw -> 'lines', '[]'::jsonb),
      'brandById',  coalesce(v_brands, '{}'::jsonb)
    )
  );
end;
$$;


--
-- Name: customer_request_login(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_request_login(p_slug text, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_acc    uuid;
  v_email  text;
  v_code   text;
  v_recent int;
begin
  select id into v_acc from accounts where slug = p_slug;
  if v_acc is null then
    return jsonb_build_object('ok', false, 'reason', 'account');
  end if;

  v_email := lower(nullif(btrim(p_email), ''));
  if v_email is null or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    return jsonb_build_object('ok', false, 'reason', 'email');
  end if;

  select count(*) into v_recent
  from customer_otp
  where account_id = v_acc and lower(email) = v_email
    and created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'rate_limited');
  end if;

  v_code := lpad((floor(random() * 1000000))::int::text, 6, '0');

  insert into customer_otp (account_id, email, code_hash, expires_at)
  values (v_acc, v_email, encode(digest(v_code || v_email, 'sha256'), 'hex'),
          now() + interval '10 minutes');

  return jsonb_build_object(
    'ok', true,
    'code', v_code,
    'name', (select name from customer where account_id = v_acc and lower(email) = v_email limit 1)
  );
end;
$_$;


--
-- Name: customer_save_address(text, uuid, text, text, text, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_save_address(p_token text, p_id uuid, p_label text, p_address text, p_detail text, p_lat numeric, p_lng numeric, p_is_default boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer     uuid;
  v_acc          uuid;
  v_addr         text;
  v_id           uuid;
  v_n            integer;
  v_make_default boolean;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  v_addr := nullif(btrim(p_address), '');
  if v_addr is null then
    return jsonb_build_object('ok', false, 'reason', 'address_required');
  end if;

  -- La primera dirección del cliente nace como predeterminada aunque no se pida.
  if p_id is null then
    select count(*) into v_n from customer_address where customer_id = v_customer;
    v_make_default := coalesce(p_is_default, false) or v_n = 0;
  else
    v_make_default := coalesce(p_is_default, false);
  end if;

  -- Si va a ser la predeterminada, desmarcar las demás ANTES (índice único parcial).
  if v_make_default then
    update customer_address set is_default = false, updated_at = now()
    where customer_id = v_customer and is_default;
  end if;

  if p_id is null then
    insert into customer_address (customer_id, account_id, label, address, detail, lat, lng, is_default)
    values (v_customer, v_acc, nullif(btrim(p_label),''), v_addr, nullif(btrim(p_detail),''),
            p_lat, p_lng, v_make_default)
    returning id into v_id;
  else
    update customer_address set
      label      = nullif(btrim(p_label),''),
      address    = v_addr,
      detail     = nullif(btrim(p_detail),''),
      lat        = p_lat,
      lng        = p_lng,
      is_default = v_make_default,
      updated_at = now()
    where id = p_id and customer_id = v_customer
    returning id into v_id;
    if v_id is null then
      return jsonb_build_object('ok', false, 'reason', 'not_found');
    end if;
  end if;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


--
-- Name: customer_session_me(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_session_me(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cust      customer%rowtype;
  v_sess      customer_session%rowtype;
  v_consented boolean;
begin
  select * into v_sess from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_sess.id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_session');
  end if;
  update customer_session set last_seen_at = now() where id = v_sess.id
    and (last_seen_at is null or last_seen_at < now() - interval '30 seconds');
  select * into v_cust from customer where id = v_sess.customer_id;
  select marketing_email into v_consented from customer_consent where customer_id = v_cust.id;
  return jsonb_build_object(
    'ok', true,
    'customerId', v_cust.id,
    'name', v_cust.name,
    'email', v_cust.email,
    'phone', v_cust.phone,
    'consented', coalesce(v_consented, false)
  );
end;
$$;


--
-- Name: customer_set_consent(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_consent(p_token text, p_consent boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer uuid;
  v_acc      uuid;
  v_prev     boolean;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  select marketing_email into v_prev from customer_consent where customer_id = v_customer;

  -- Solo si hay cambio real: upsert + log (append-only prueba legal).
  if coalesce(v_prev, false) is distinct from coalesce(p_consent, false) then
    insert into customer_consent (customer_id, account_id, marketing_email, updated_at)
    values (v_customer, v_acc, coalesce(p_consent, false), now())
    on conflict (customer_id) do update set marketing_email = excluded.marketing_email, updated_at = now();

    insert into customer_consent_log (customer_id, account_id, action, channel, source, terms_version)
    values (v_customer, v_acc,
            case when coalesce(p_consent, false) then 'granted' else 'revoked' end,
            'email', 'account_page', 'shop-privacy-v1');
  end if;

  return jsonb_build_object('ok', true, 'consented', coalesce(p_consent, false));
end;
$$;


--
-- Name: customer_update_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_update_profile(p_token text, p_name text, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer uuid;
  v_acc      uuid;
  v_name     text;
  v_phone    text;
begin
  select customer_id, account_id into v_customer, v_acc
  from customer_session
  where token = nullif(btrim(p_token),'') and revoked_at is null and expires_at > now()
  limit 1;
  if v_customer is null then
    return jsonb_build_object('ok', false, 'reason', 'session');
  end if;

  v_name  := nullif(btrim(p_name),  '');
  v_phone := nullif(btrim(p_phone), '');

  -- Teléfono único por cuenta (índice único parcial (account_id, phone)).
  if v_phone is not null and exists (
        select 1 from customer
        where account_id = v_acc and phone = v_phone and id <> v_customer
     ) then
    return jsonb_build_object('ok', false, 'reason', 'phone_taken');
  end if;

  begin
    update customer set name = v_name, phone = v_phone, updated_at = now()
    where id = v_customer;
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'reason', 'phone_taken');
  end;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: customer_verify_login(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_verify_login(p_slug text, p_email text, p_code text, p_ttl_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_acc      uuid;
  v_email    text;
  v_otp      customer_otp%rowtype;
  v_customer uuid;
  v_token    text;
  v_ttl      int;
begin
  select id into v_acc from accounts where slug = p_slug;
  if v_acc is null then
    return jsonb_build_object('ok', false, 'reason', 'account');
  end if;

  v_email := lower(nullif(btrim(p_email), ''));
  if v_email is null then
    return jsonb_build_object('ok', false, 'reason', 'email');
  end if;

  v_ttl := greatest(1, least(coalesce(p_ttl_days, 90), 365));

  select * into v_otp
  from customer_otp
  where account_id = v_acc and lower(email) = v_email
    and consumed_at is null and expires_at > now()
  order by created_at desc
  limit 1;

  if v_otp.id is null then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  if v_otp.attempts >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'too_many_attempts');
  end if;

  if v_otp.code_hash <> encode(digest(coalesce(p_code,'') || v_email, 'sha256'), 'hex') then
    update customer_otp set attempts = attempts + 1 where id = v_otp.id;
    return jsonb_build_object('ok', false, 'reason', 'bad_code');
  end if;

  update customer_otp set consumed_at = now() where id = v_otp.id;

  select id into v_customer from customer
  where account_id = v_acc and lower(email) = v_email limit 1;

  if v_customer is null then
    insert into customer (account_id, email, email_verified, last_login_at)
    values (v_acc, v_email, true, now())
    returning id into v_customer;
  else
    update customer set email_verified = true, last_login_at = now(), updated_at = now()
    where id = v_customer;
  end if;

  v_token := replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-','');
  insert into customer_session (customer_id, account_id, token, expires_at)
  values (v_customer, v_acc, v_token, now() + (v_ttl || ' days')::interval);

  return jsonb_build_object(
    'ok', true,
    'sessionToken', v_token,
    'customerId', v_customer,
    'name', (select name from customer where id = v_customer),
    'email', v_email
  );
end;
$$;


--
-- Name: db_health_connection_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.db_health_connection_guard() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_max        int;
  v_total      int;
  v_idle       int;
  v_quien      text;
  v_hace10     int;
  v_secret     text;
  v_killed     int := 0;
  v_lista      text;
begin
  -- Lectura BARATA (no pg_settings: esa vista fue la que tardó 10 s el 13/08).
  v_max := current_setting('max_connections')::int;

  select count(*) filter (where backend_type = 'client backend'),
         count(*) filter (where backend_type = 'client backend' and state = 'idle')
    into v_total, v_idle
  from pg_stat_activity;

  -- ── CAPA 3 · AUTODEFENSA (>90%) ────────────────────────────────────────────
  -- Mata SOLO conexiones ociosas de más de 5 min. NUNCA 'active' (trabajo en curso)
  -- ni 'idle in transaction' (transacción abierta: matarla perdería trabajo).
  -- El pool del cliente reabre solo — es comportamiento estándar de cualquier pool.
  if v_total > 0.90 * v_max then
    with muertas as (
      select pid, coalesce(nullif(application_name,''), '(sin nombre)') as app
      from pg_stat_activity
      where backend_type = 'client backend'
        and state = 'idle'
        and state_change < now() - interval '5 minutes'
        and pid <> pg_backend_pid()
        and coalesce(application_name,'') not in ('pg_cron scheduler','mgmt-api','postgres_exporter')
    ), ejecutado as (
      select app, pg_terminate_backend(pid) as ok from muertas
    )
    select count(*) filter (where ok),
           string_agg(distinct app, ', ')
      into v_killed, v_lista
    from ejecutado;

    if coalesce(v_killed,0) > 0 then
      perform public._queue_system_alert(
        'db-health',
        'AUTODEFENSA: liberadas ' || v_killed || ' conexiones ociosas (' || v_total || '/' || v_max || ')',
        'db_health_connection_guard cerró ' || v_killed || ' conexión(es) en estado idle de más de 5 min '
          || 'al superar el 90% del límite. Origen: ' || coalesce(v_lista,'?') || '.' || chr(10)
          || 'Ninguna conexión activa ni con transacción abierta fue tocada; los pools reabren solos.' || chr(10)
          || 'ESTO ES UN SÍNTOMA: revisar quién está abriendo tantas conexiones.',
        'db-health-autodefensa'
      );
    end if;
  end if;

  -- ── CAPA 1 · AVISO TEMPRANO (65%) o POR TENDENCIA (+10 en 10 min) ──────────
  select total_connections into v_hace10
  from public.db_health_snapshot_log
  where checked_at <= now() - interval '10 minutes'
  order by checked_at desc
  limit 1;

  if v_total > 0.65 * v_max
     or (v_hace10 is not null and v_total - v_hace10 >= 10) then

    -- Antiruido: 15 min, igual que el resto de avisos de db-health.
    if not exists (
      select 1 from public.db_health_alert_log
      where kind = 'db-health-conn-guard' and sent_at >= now() - interval '15 minutes'
    ) then

      -- QUIÉN las consume: sin esto el aviso dice "53/60" y hay que entrar a mirar…
      -- y el 13/08 NO SE PODÍA ENTRAR A MIRAR.
      select string_agg(linea, ' · ' order by n desc)
        into v_quien
      from (
        select coalesce(nullif(application_name,''),'(sin nombre)') || ': ' || count(*)
                 || ' (' || count(*) filter (where state='idle') || ' idle)' as linea,
               count(*) as n
        from pg_stat_activity
        where backend_type = 'client backend'
        group by 1
        order by n desc
        limit 3
      ) t;

      -- ENVÍO DIRECTO, sin pasar por system_alert_queue: el 13/08 el drain también
      -- estaba ahogado (250 fallos) — el aviso de "me quedo sin conexiones" NO puede
      -- depender de otro cron que se ahoga en el mismo momento.
      select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cron_secret';

      if v_secret is not null then
        perform net.http_post(
          url     := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/system-alert',
          headers := jsonb_build_object('Content-Type','application/json','x-cron-secret', v_secret),
          body    := jsonb_build_object(
                       'kind',    'db-health',
                       'subject', 'Conexiones subiendo — ' || v_total || '/' || v_max
                                    || case when v_hace10 is not null then ' (hace 10 min: ' || v_hace10 || ')' else '' end,
                       'message', 'Conexiones de cliente: ' || v_total || ' de ' || v_max
                                    || ' (' || v_idle || ' ociosas).' || chr(10)
                                    || 'Quién: ' || coalesce(v_quien,'?') || chr(10)
                                    || 'Autodefensa a partir de ' || ceil(0.90*v_max) || '. Aviso enviado DIRECTO.'
                     ),
          timeout_milliseconds := 5000
        );
        insert into public.db_health_alert_log (kind, detail)
          values ('db-health-conn-guard', v_total || '/' || v_max || ' — ' || coalesce(v_quien,'?'));
      else
        raise warning 'db_health_connection_guard: sin cron_secret, aviso no enviado (%/%)', v_total, v_max;
      end if;
    end if;
  end if;

exception when others then
  -- Nunca tumbar el cron por un fallo del vigía; dejar rastro (regla: nada de catch mudo).
  raise warning 'db_health_connection_guard: excepcion: %', sqlerrm;
end;
$$;


--
-- Name: FUNCTION db_health_connection_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.db_health_connection_guard() IS 'Vigía de conexiones (13/08): avisa al 65% o si suben +10 en 10 min, con QUIÉN las consume y
   envío DIRECTO (no por system_alert_queue, que se ahoga a la vez). A partir del 90% libera
   conexiones idle de más de 5 min (nunca activas ni en transacción). Función pequeña a propósito:
   debe poder arrancar cuando la base ya va mal.';


--
-- Name: db_health_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.db_health_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total_conn   int;
  v_waiting_lock int;
  v_oldest_tx_s  numeric;
  v_max_conn     int;
begin
  -- Corregido 11/08: solo client backend cuenta plaza de max_connections.
  select count(*) into v_total_conn
  from pg_stat_activity
  where backend_type = 'client backend';
  select count(*) into v_waiting_lock
  from pg_stat_activity
  where wait_event_type = 'Lock';
  select extract(epoch from max(now() - xact_start)) into v_oldest_tx_s
  from pg_stat_activity
  where xact_start is not null;
  select setting::int into v_max_conn from pg_settings where name = 'max_connections';
  return jsonb_build_object(
    'total_connections', v_total_conn,
    'waiting_locks',     v_waiting_lock,
    'oldest_tx_seconds', coalesce(round(v_oldest_tx_s), 0),
    'max_connections',   v_max_conn
  );
end;
$$;


--
-- Name: FUNCTION db_health_snapshot(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.db_health_snapshot() IS 'Chequeo puro e instantaneo (conexiones de CLIENTE real, procesos esperando lock, tx mas vieja, max_connections). Sin writer_count desde la 0906.';


--
-- Name: db_health_stale_devices_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.db_health_stale_devices_report() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_list  text;
  v_count int;
begin
  select string_agg(
           format('%s (%s) — ultimo latido: %s',
             d.label, coalesce(l.name, 'sin local'), coalesce(d.last_seen_at::text, 'nunca')),
           chr(10) order by d.last_seen_at nulls first
         ), count(*)
    into v_list, v_count
  from kds_device d
  left join locations l on l.id = d.location_id
  where d.is_active
    and (d.last_seen_at is null or d.last_seen_at < now() - interval '30 days');

  if v_count is null or v_count = 0 then
    return;
  end if;

  perform public._queue_system_alert(
    'db-health-stale-devices',
    v_count || ' dispositivo(s) KDS activo(s) sin latido hace mas de 30 dias',
    'Solo REPORTE — ninguna baja automatica. Revisar si siguen en uso o dar de baja a mano (is_active=false):'
      || chr(10) || chr(10) || v_list
  );
exception when others then
  raise warning 'db_health_stale_devices_report: excepcion: %', sqlerrm;
  perform public._queue_system_alert(
    'db-health-stale-devices-error',
    'db_health_stale_devices_report FALLO',
    'El reporte diario de dispositivos fantasma lanzo una excepcion: ' || sqlerrm
  );
  raise;
end;
$$;


--
-- Name: FUNCTION db_health_stale_devices_report(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.db_health_stale_devices_report() IS 'Reporte DIARIO (cron db-health-stale-devices-daily, 06:00 UTC ~ 08:00 Madrid en verano) de kds_device con is_active=true y last_seen_at NULL o >30 dias. Solo aviso — CERO efecto operativo automatico.';


--
-- Name: db_health_watchdog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.db_health_watchdog() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_snap            jsonb;
  v_waiting         int;
  v_total_conn      int;
  v_max_conn        int;
  v_n_snapshots     int;
  v_n_breaching     int;
  v_stuck_print     int;
  v_inactive_print  int;
  v_route_failures  int;
begin
  begin
    v_snap       := public.db_health_snapshot();
    v_waiting    := (v_snap->>'waiting_locks')::int;
    v_total_conn := (v_snap->>'total_connections')::int;
    v_max_conn   := (v_snap->>'max_connections')::int;

    insert into public.db_health_snapshot_log
      (total_connections, waiting_locks, oldest_tx_seconds)
    values
      (v_total_conn, v_waiting, (v_snap->>'oldest_tx_seconds')::numeric);

    delete from public.db_health_snapshot_log where checked_at < now() - interval '48 hours';
    delete from public.db_health_alert_log where sent_at < now() - interval '30 days';

    -- Aviso 1 — bloqueos sostenidos. CRITICO, y dicho, no caido por defecto.
    -- Sin cuenta ni local a proposito: esto es la BASE ENTERA, y rellenar un
    -- campo de local aqui seria mentir en un campo.
    --
    -- La ventana pasa a los 15 minutos que el codigo decia. Antes decia 15 y
    -- hacia 20 HORAS: el `not exists` miraba `sent_at` (cuando se envio) y el
    -- envoltorio viejo traia `p_debounce_window default '20:00:00'`, que gana
    -- por ser mas ancha. Un segundo episodio dentro de esas 20 h no avisaba.
    select count(*), count(*) filter (where waiting_locks > 3)
      into v_n_snapshots, v_n_breaching
      from public.db_health_snapshot_log
      where checked_at >= now() - interval '2 minutes';
    if v_n_snapshots >= 2 and v_n_breaching = v_n_snapshots then
      perform public.encolar_alerta(
        p_kind    => 'db-health',
        p_subject => 'La base de datos esta bloqueada: ' || v_waiting
                     || ' proceso(s) esperando, y van mas de 2 min',
        p_message =>
          'Mas de 3 procesos llevan esperando un lock en ' || v_n_snapshots
          || ' medidas seguidas de los ultimos 2 minutos; ahora mismo hay ' || v_waiting || '.'
          || chr(10)
          || 'Conexiones de cliente: ' || v_total_conn
          || '. Transaccion mas antigua: ' || (v_snap->>'oldest_tx_seconds') || ' s.'
          || chr(10) || chr(10)
          || 'Asi empezo el incidente del 11/08. Mirar pg_stat_activity YA.',
        p_debounce_kind   => 'db-health-lock',
        p_debounce_window => interval '15 minutes',
        p_account_id      => NULL,
        p_location_id     => NULL,
        p_brand_id        => NULL,
        p_severity        => 'critico'
      );
    end if;

    -- Aviso 2 — conexiones de CLIENTE cerca del maximo. ALTO, y dicho.
    -- Se queda en el MISMO valor al que caia por defecto. Ese es todo el
    -- cambio, y es el que importa: ahora esta escrito, asi que se puede
    -- discutir. Antes no era una decision, era un hueco.
    if v_max_conn > 0 and v_total_conn > 0.8 * v_max_conn then
      perform public.encolar_alerta(
        p_kind    => 'db-health',
        p_subject => 'La base de datos se acerca a su limite de conexiones: '
                     || v_total_conn || ' de ' || v_max_conn,
        p_message =>
          'Hay ' || v_total_conn || ' conexiones de CLIENTE abiertas de un maximo de '
          || v_max_conn || ', mas del 80 %.' || chr(10) || chr(10)
          || 'Mirar pg_stat_activity: puede ser el mismo patron del 11/08.',
        p_debounce_kind   => 'db-health-connections',
        p_debounce_window => interval '15 minutes',
        p_account_id      => NULL,
        p_location_id     => NULL,
        p_brand_id        => NULL,
        p_severity        => 'alto'
      );
    end if;

    -- Aviso 4 — tickets atascados en cola mas de 2h, POR LOCAL, y SOLO de
    -- cuentas que operan.
    --
    -- `print_job` trae `account_id` y `location_id`, los dos NOT NULL: como en
    -- el aviso 6, no habia que buscarlos, habia que dejar de tirarlos. El
    -- viejo sumaba la tabla ENTERA y decia un numero que no es de nadie
    -- (regla 9). Y el antirruido era global: un local tapaba al otro una hora.
    --
    -- El filtro de cuenta va en los DOS sitios —la puerta y el agrupado— a
    -- proposito: si la puerta contara mas ancho que el agrupado, tendriamos un
    -- `if` que se abre para no encolar nada. La misma vara a los dos lados.
    select count(*) into v_stuck_print
    from public.print_job
    where status = 'pending' and created_at < now() - interval '2 hours'
      and public.cuenta_opera(account_id);
    if v_stuck_print > 0 then
      perform public.encolar_alerta(
        p_kind    => 'db-health',
        p_subject => 'Tickets sin imprimir desde hace horas: ' || t.n || ' en cola',
        p_message =>
          t.n || ' ticket(s) llevan en cola sin imprimirse mas de 2 horas. El mas viejo espera '
          || 'desde las ' || to_char(t.mas_viejo at time zone 'Europe/Madrid', 'HH24:MI')
          || ' del ' || to_char(t.mas_viejo at time zone 'Europe/Madrid', 'DD/MM') || '.'
          || chr(10) || chr(10)
          || 'Mira la impresora del local: encendida, con papel y con la tablet conectada.'
          || chr(10)
          || 'Asi se acumularon los 76 de Carabanchel del 08/08, tres dias sin que nadie se enterara.',
        p_debounce_kind   => 'db-health-print-stuck_'
                             || coalesce(t.location_id::text, 'sin-local'),
        p_debounce_window => interval '60 minutes',
        p_account_id      => t.account_id,
        p_location_id     => t.location_id,
        p_brand_id        => NULL,
        -- La severidad la decide el HORARIO, no una constante (Julio, 09/09).
        -- `critico` quiere decir «actua ahora», y eso solo es verdad si el
        -- local esta sirviendo: tickets atascados a las 21:00 con la cocina
        -- abierta son pedidos perdiendose; el mismo dato a las 4 de la manana
        -- no justifica despertar a nadie.
        --
        -- Se evalua POR FILA: dos locales del mismo grupo pueden estar uno
        -- abierto y otro cerrado, y cada aviso se lleva la suya.
        p_severity        => case
                               when public.is_brand_open(t.location_id, NULL::uuid, now())
                               then 'critico' else 'alto'
                             end
      )
      from (select j.account_id, j.location_id, count(*) as n, min(j.created_at) as mas_viejo
              from public.print_job j
             where j.status = 'pending' and j.created_at < now() - interval '2 hours'
               and public.cuenta_opera(j.account_id)
             group by j.account_id, j.location_id) t;
    end if;

    -- Aviso 5 — tickets encolados a una impresora marcada como inactiva, POR
    -- LOCAL, y SOLO de cuentas que operan.
    --
    -- Mismo arreglo que el 4, y aqui ademas se puede decir QUE impresora: sin
    -- el nombre, el aviso obliga a ir a buscarla a mano.
    --
    -- Se agrupa por el local del TRABAJO, no por el de la impresora. No es lo
    -- mismo por definicion, asi que se comprobo sobre la tabla entera: de los
    -- 9.488 print_job, CERO apuntan a una impresora de otro local. Agrupar por
    -- el del trabajo no parte hoy ningun aviso en dos.
    select count(*) into v_inactive_print
    from public.print_job pj
    join public.printer p on p.id = pj.printer_id
    where pj.status in ('pending', 'sent') and p.is_active = false
      and public.cuenta_opera(pj.account_id);
    if v_inactive_print > 0 then
      perform public.encolar_alerta(
        p_kind    => 'db-health',
        p_subject => 'Tickets encolados a una impresora apagada en Folvy: ' || t.n,
        p_message =>
          t.n || ' ticket(s) estan esperando en una impresora que en Folvy figura como INACTIVA: '
          || t.impresoras || '.' || chr(10) || chr(10)
          || 'No se van a imprimir nunca: la tablet solo recoge trabajos de impresoras activas.'
          || chr(10)
          || 'O se vuelve a marcar activa esa impresora, o esos tickets hay que mandarlos a otra.',
        p_debounce_kind   => 'db-health-print-inactive-printer_'
                             || coalesce(t.location_id::text, 'sin-local'),
        p_debounce_window => interval '60 minutes',
        p_account_id      => t.account_id,
        p_location_id     => t.location_id,
        p_brand_id        => NULL,
        p_severity        => 'alto'
      )
      from (select j.account_id, j.location_id, count(*) as n,
                   string_agg(distinct pr.name, ', ') as impresoras
              from public.print_job j
              join public.printer pr on pr.id = j.printer_id
             where j.status in ('pending', 'sent') and pr.is_active = false
               and public.cuenta_opera(j.account_id)
             group by j.account_id, j.location_id) t;
    end if;

    -- Aviso 6 — pedidos aceptados sin ninguna impresora activa, POR LOCAL, y
    -- SOLO de cuentas que operan.
    --
    -- `print_route_failure_log` ya trae account_id y location_id: no habia que
    -- buscarlos, habia que dejar de tirarlos. El antirruido va por local, que
    -- antes era global y un local tapaba al otro durante una hora.
    --
    -- `perform ... from (...)` llama a encolar_alerta una vez por fila sin
    -- declarar variables nuevas: el resto de este cuerpo no se toca.
    --
    -- Este es el aviso que hizo ver el problema: las 100 filas de la tabla son
    -- 98 de una cuenta SUSPENDIDA y 2 de la plantilla. Cero de un cliente vivo.
    select count(*) into v_route_failures
    from public.print_route_failure_log
    where created_at >= now() - interval '10 minutes'
      and public.cuenta_opera(account_id);
    if v_route_failures > 0 then
      perform public.encolar_alerta(
        p_kind    => 'db-health',
        p_subject => 'Pedidos aceptados y sin imprimir: no hay ninguna impresora activa',
        p_message =>
          t.n || ' pedido(s) se han aceptado en los ultimos 10 minutos y no se han podido '
          || 'enviar a imprimir: el local no tiene ninguna impresora activa dada de alta.'
          || chr(10) || chr(10)
          || 'El pedido esta cocinandose sin ticket. Da de alta una impresora en ese local, '
          || 'o marcala como activa si ya existe.',
        p_debounce_kind   => 'db-health-print-no-active-printer_'
                             || coalesce(t.location_id::text, 'sin-local'),
        p_debounce_window => interval '60 minutes',
        p_account_id      => t.account_id,
        p_location_id     => t.location_id,
        p_brand_id        => NULL,
        p_severity        => 'alto'
      )
      from (select f.account_id, f.location_id, count(*) as n
              from public.print_route_failure_log f
             where f.created_at >= now() - interval '10 minutes'
               and public.cuenta_opera(f.account_id)
             group by f.account_id, f.location_id) t;
    end if;

  exception when others then
    -- raise warning PRIMERO: va a los logs del servidor y NO se revierte con
    -- el raise de abajo. El encolado si se revierte — se mantiene porque si la
    -- condicion persiste, el siguiente tick lo vuelve a intentar.
    raise warning 'db_health_watchdog: excepcion: %', sqlerrm;
    if not exists (
      select 1 from public.db_health_alert_log
      where kind = 'db-health-watchdog-error' and sent_at >= now() - interval '30 minutes'
    ) then
      perform public._queue_system_alert(
        'db-health-watchdog-error',
        'db_health_watchdog FALLO',
        'El vigia de salud de BBDD lanzo una excepcion: ' || sqlerrm,
        'db-health-watchdog-error'
      );
    end if;
    raise;
  end;
end;
$$;


--
-- Name: FUNCTION db_health_watchdog(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.db_health_watchdog() IS 'Snapshot cada minuto y ENCOLA en system_alert_queue (ya no net.http_post directo — 11/08) ante 5 condiciones, cada una con su antiruido en db_health_alert_log (consumido solo al confirmarse la entrega). Nunca falla en silencio.';


--
-- Name: db_health_writer_regression_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.db_health_writer_regression_check() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_snap    jsonb;
  v_writers int;
begin
  begin
    v_snap := public.db_health_snapshot();
    select count(*) into v_writers
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prosrc ~* 'update\s+(public\.)?kds_device';

    insert into public.db_health_snapshot_log
      (total_connections, waiting_locks, oldest_tx_seconds, writer_count)
    values (
      (v_snap->>'total_connections')::int,
      (v_snap->>'waiting_locks')::int,
      (v_snap->>'oldest_tx_seconds')::numeric,
      v_writers
    );

    if v_writers <> 3
       and exists (select 1 from public.db_health_snapshot_log where writer_count = 3)
       and not exists (
         select 1 from public.db_health_alert_log
         where kind = 'db-health-writer-regression' and sent_at >= now() - interval '24 hours'
       ) then
      perform public._queue_system_alert(
        'db-health',
        'REGRESION: ' || v_writers || ' funciones escriben kds_device (se esperaban 3)',
        'Alguien ha vuelto a meter una escritura de last_seen_at en una funcion de LECTURA de kds_device '
          || '(el incidente completo del 11/08, de nuevo).' || chr(10)
          || 'Esperado: kds_heartbeat, report_device_app_version, set_device_mode_by_token — y nada mas.',
        'db-health-writer-regression'
      );
    end if;
  exception when others then
    raise warning 'db_health_writer_regression_check: excepcion: %', sqlerrm;
    if not exists (
      select 1 from public.db_health_alert_log
      where kind = 'db-health-writer-regression-check-error' and sent_at >= now() - interval '30 minutes'
    ) then
      perform public._queue_system_alert(
        'db-health-writer-regression-check-error',
        'db_health_writer_regression_check FALLO',
        'El chequeo de regresion de escritores (cada 15 min) lanzo una excepcion: ' || sqlerrm,
        'db-health-writer-regression-check-error'
      );
    end if;
    raise;
  end;
end;
$$;


--
-- Name: FUNCTION db_health_writer_regression_check(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.db_health_writer_regression_check() IS 'Chequeo cada 15 MIN (cron db-health-writer-regression-15m) del guard anti-regresion de escritores de kds_device (esperado SIEMPRE 3). Trasladado desde db_health_watchdog() el 11/08 por coste (283ms medido). Inserta 1 fila cada 15 min con writer_count real; el resto de filas lo dejan NULL.';


--
-- Name: decidir_quien_reparte(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decidir_quien_reparte(p_sale_id uuid, p_quien text, p_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s record; v_carrier text; v_reason text; v_mode text;
begin
  select s.id, s.location_id, s.delivery_by_reason, s.status, s.carrier_order_id, s.delivery_address, s.delivery_address_fixed,
         s.rider_name, s.rider_phone
    into v_s from public.sale s where s.id = p_sale_id;
  if v_s.id is null then raise exception 'decidir_quien_reparte: el pedido no existe'; end if;
  perform public.kds_authorize(v_s.location_id, p_token);
  if v_s.status is distinct from 'open' then raise exception 'Este pedido ya está cerrado.'; end if;
  if p_quien not in ('nosotros', 'uber') then raise exception 'decidir_quien_reparte: «nosotros» o «uber»'; end if;
  if v_s.carrier_order_id is not null then raise exception 'Este pedido ya está en Catcher.'; end if;

  -- «Tal cual»: que el disparador de «Quién reparte» no lo devuelva a lo de antes.
  perform set_config('folvy.reparto_tal_cual', 'on', true);
  update public.sale
     set service_type = case when p_quien = 'nosotros' then 'own_delivery' else 'platform_delivery' end,
         delivery_by_reason = case when p_quien = 'nosotros' then 'decidido_propio' else 'decidido_uber' end,
         updated_at = now()
   where id = p_sale_id;
  perform set_config('folvy.reparto_tal_cual', '', true);

  if p_quien = 'nosotros' then
    select r.carrier, r.reason into v_carrier, v_reason from public.resolve_dispatch(p_sale_id) r;
  end if;
  select coalesce(l.dispatch_mode, 'auto') into v_mode from public.locations l where l.id = v_s.location_id;
  return jsonb_build_object(
    'ok', true, 'sale_id', p_sale_id, 'quien', p_quien,
    'direccion', nullif(coalesce(nullif(btrim(v_s.delivery_address_fixed), ''), btrim(v_s.delivery_address)), ''),
    'carrier', v_carrier, 'reason', v_reason, 'dispatch_mode', v_mode,
    'ya_en_catcher', false, 'rider_name', v_s.rider_name, 'rider_phone', v_s.rider_phone);
end;
$$;


--
-- Name: FUNCTION decidir_quien_reparte(p_sale_id uuid, p_quien text, p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.decidir_quien_reparte(p_sale_id uuid, p_quien text, p_token text) IS 'R03: una persona decide quién reparte un pedido de Uber con señales mezcladas (calle, punto o cargo de envío). «nosotros» → propio (decidido_propio); «uber» → la reparte Uber (decidido_uber). Con token, solo pedidos del local del dispositivo.';


--
-- Name: declare_closure_deliberate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.declare_closure_deliberate(p_closure_id uuid, p_note text DEFAULT NULL::text) RETURNS TABLE(closure_id uuid, deliberate_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
begin
  select bc.account_id into v_account
    from public.brand_closure bc where bc.id = p_closure_id;
  if v_account is null then
    raise exception 'declare_closure_deliberate: el cierre % no existe', p_closure_id;
  end if;
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_account)) then
    raise exception 'declare_closure_deliberate: sin acceso a la cuenta %', v_account;
  end if;

  -- Declarar dos veces no es un error: se queda la primera declaracion, que es
  -- la que tiene la fecha y el autor de verdad.
  update public.brand_closure bc
     set deliberate_at   = coalesce(bc.deliberate_at, now()),
         deliberate_by   = coalesce(bc.deliberate_by, auth.uid()),
         deliberate_note = coalesce(bc.deliberate_note, nullif(btrim(p_note), '')),
         updated_at      = now()
   where bc.id = p_closure_id;

  return query
    select bc.id, bc.deliberate_at from public.brand_closure bc where bc.id = p_closure_id;
end;
$$;


--
-- Name: FUNCTION declare_closure_deliberate(p_closure_id uuid, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.declare_closure_deliberate(p_closure_id uuid, p_note text) IS 'Declara que un cierre sin fecha es a proposito. Deja de alarmar, con autor y momento. Idempotente: la segunda llamada conserva la primera declaracion.';


--
-- Name: default_permissions_for_role(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.default_permissions_for_role(p_role text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_role
    WHEN 'ceo' THEN jsonb_build_object(
      'platform_can_create_accounts', true,  'platform_can_suspend_accounts', true,
      'platform_can_archive_accounts', true, 'platform_can_delete_accounts', true,
      'platform_can_edit_seed_data', true,   'platform_can_impersonate', true,
      'platform_can_manage_admins', true,    'platform_can_reset_2fa_of_others', true,
      'platform_can_send_global_notifications', true,
      'platform_can_view_audit_log', true,   'platform_can_view_system_health', true)
    WHEN 'senior_admin' THEN jsonb_build_object(
      'platform_can_create_accounts', true,  'platform_can_suspend_accounts', true,
      'platform_can_archive_accounts', true, 'platform_can_delete_accounts', false,
      'platform_can_edit_seed_data', true,   'platform_can_impersonate', true,
      'platform_can_manage_admins', false,   'platform_can_reset_2fa_of_others', true,
      'platform_can_send_global_notifications', true,
      'platform_can_view_audit_log', true,   'platform_can_view_system_health', true)
    WHEN 'admin' THEN jsonb_build_object(
      'platform_can_create_accounts', true,  'platform_can_suspend_accounts', true,
      'platform_can_archive_accounts', false,'platform_can_delete_accounts', false,
      'platform_can_edit_seed_data', false,  'platform_can_impersonate', true,
      'platform_can_manage_admins', false,   'platform_can_reset_2fa_of_others', false,
      'platform_can_send_global_notifications', false,
      'platform_can_view_audit_log', true,   'platform_can_view_system_health', true)
    WHEN 'support' THEN jsonb_build_object(
      'platform_can_create_accounts', false, 'platform_can_suspend_accounts', false,
      'platform_can_archive_accounts', false,'platform_can_delete_accounts', false,
      'platform_can_edit_seed_data', false,  'platform_can_impersonate', true,
      'platform_can_manage_admins', false,   'platform_can_reset_2fa_of_others', false,
      'platform_can_send_global_notifications', false,
      'platform_can_view_audit_log', false,  'platform_can_view_system_health', true)
    ELSE jsonb_build_object(
      'platform_can_create_accounts', false, 'platform_can_suspend_accounts', false,
      'platform_can_archive_accounts', false,'platform_can_delete_accounts', false,
      'platform_can_edit_seed_data', false,  'platform_can_impersonate', false,
      'platform_can_manage_admins', false,   'platform_can_reset_2fa_of_others', false,
      'platform_can_send_global_notifications', false,
      'platform_can_view_audit_log', false,  'platform_can_view_system_health', false)
  END;
$$;


--
-- Name: delete_account_tx(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_account_tx(p_account_id uuid, p_admin_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM platform_audit_log
  WHERE target_account_id = p_account_id
     OR (p_admin_user_id IS NOT NULL AND target_user_id = p_admin_user_id);

  DELETE FROM subscription_items
  WHERE subscription_id IN (SELECT id FROM subscriptions WHERE account_id = p_account_id);

  DELETE FROM subscriptions WHERE account_id = p_account_id;

  DELETE FROM permission_set_assignments
  WHERE user_profile_id IN (SELECT id FROM user_profiles WHERE account_id = p_account_id);

  DELETE FROM user_profiles
  WHERE account_id = p_account_id
     OR (p_admin_user_id IS NOT NULL AND user_id = p_admin_user_id);

  DELETE FROM brand WHERE account_id = p_account_id;
  DELETE FROM locations WHERE account_id = p_account_id;
  DELETE FROM accounts WHERE id = p_account_id;

  IF p_admin_user_id IS NOT NULL THEN
    DELETE FROM auth.users WHERE id = p_admin_user_id;
  END IF;
END;
$$;


--
-- Name: delete_campaign(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_campaign(p_account uuid, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_c coupon%rowtype;
begin
  if not (p_account = any(current_user_account_ids())) then raise exception 'forbidden'; end if;

  select * into v_c from coupon where id = p_id and account_id = p_account;
  if v_c.id is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;

  -- Sistema = bienvenida (standard auto/first) o frecuencia: NUNCA se eliminan aquí.
  if v_c.kind = 'frequency' or (v_c.kind = 'standard' and (v_c.auto_apply or v_c.first_order_only)) then
    return jsonb_build_object('ok', false, 'reason', 'system');
  end if;

  -- Con canjes: el histórico manda. No se borra físico; la UI ofrece pausar.
  if exists (select 1 from coupon_redemption where coupon_id = p_id) then
    return jsonb_build_object('ok', false, 'reason', 'has_redemptions');
  end if;

  -- Sin canjes: borrado físico. campaign_scope cae por FK on delete cascade.
  delete from coupon where id = p_id and account_id = p_account;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: delete_courier_bonus(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_courier_bonus(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from courier_bonus where id=p_id and account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(account_id);
end; $$;


--
-- Name: delete_delivery_zone(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_delivery_zone(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_account uuid;
begin
  select account_id into v_account from public.delivery_zone where id = p_id;
  if v_account is null then return; end if;
  if not public.current_user_is_admin_of(v_account) then raise exception 'Sin permiso'; end if;
  delete from public.delivery_zone where id = p_id;
end; $$;


--
-- Name: delete_dispatch_rule(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_dispatch_rule(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from dispatch_rule where id=p_id and account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(account_id);
end; $$;


--
-- Name: delete_printer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_printer(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid;
begin
  select account_id into v_acc from printer where id = p_id;
  if v_acc is null then return; end if;
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_acc)) then
    raise exception 'delete_printer: sin acceso';
  end if;
  if exists (select 1 from print_job where printer_id = p_id and status = 'pending') then
    raise exception 'delete_printer: la impresora tiene trabajos pendientes; cancélalos primero';
  end if;
  delete from printer where id = p_id;
end;
$$;


--
-- Name: delete_printer_by_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_printer_by_token(p_device_token text, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'delete_printer_by_token: token no válido';
  end if;

  if not exists (
    select 1 from printer
    where id = p_id
      and account_id  = v_device.account_id
      and location_id = v_device.location_id
  ) then
    return;
  end if;

  if exists (select 1 from print_job where printer_id = p_id and status = 'pending') then
    raise exception 'delete_printer_by_token: la impresora tiene trabajos pendientes; cancélalos primero';
  end if;

  delete from printer where id = p_id;
end;
$$;


--
-- Name: delivery_watchdog_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delivery_watchdog_scan() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer;
begin
  with cfg as (
    select l.id as location_id,
           coalesce(w.enabled, true)                        as enabled,
           coalesce(w.in_delivery_threshold_minutes, 45)    as in_del,
           coalesce(w.unsealed_threshold_minutes, 90)       as unsealed
    from public.locations l
    left join public.delivery_watchdog_config w on w.location_id = l.id
  ),
  stalled as (
    select s.id,
           case
             when s.delivery_state = 'in_delivery'
                  and s.handed_to_courier_at is not null
                  and now() - s.handed_to_courier_at > make_interval(mins => c.in_del)
               then 'stalled_in_delivery'
             when s.order_status not in ('completed','rejected','cancelled','delivery_failed')
                  and now() - coalesce(s.opened_at, s.sold_at, s.created_at) > make_interval(mins => c.unsealed)
               then 'stalled_unclosed'
             else null
           end as kind
    from public.sale s
    join cfg c on c.location_id = s.location_id and c.enabled
    where s.delivery_alarm_at is null
      and s.order_status not in ('rejected','cancelled')
      and (s.carrier_code is not null or s.delivery_state is not null)
      and coalesce(s.opened_at, s.sold_at, s.created_at) > now() - interval '24 hours'
  )
  update public.sale s
     set delivery_alarm_at     = now(),
         delivery_alarm_kind    = st.kind,
         delivery_alarm_ack_at  = null,
         updated_at             = now()
    from stalled st
   where s.id = st.id
     and st.kind is not null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: device_location_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_location_by_token(p_device_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
  v_name   text;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'device_location_by_token: token no válido';
  end if;

  select name into v_name from locations where id = v_device.location_id;

  return jsonb_build_object(
    'location_id',   v_device.location_id,
    'location_name', coalesce(v_name, 'Local'),
    'device_label',  v_device.label
  );
end;
$$;


--
-- Name: dismiss_pending(uuid, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_pending(p_account_id uuid, p_pending_kind text, p_location_id uuid, p_action text, p_preset text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_profile_id uuid;
  v_user_id uuid;
  v_user_name text;
  v_until timestamptz;
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'dismiss_pending: cuenta % no pertenece al usuario', p_account_id;
  end if;

  if p_action not in ('posponer', 'descartar') then
    raise exception 'dismiss_pending: action invalida %', p_action;
  end if;

  select up.id, up.user_id, up.display_name into v_user_profile_id, v_user_id, v_user_name
  from public.user_profiles up
  where up.user_id = auth.uid() and up.account_id = p_account_id and up.active = true
  limit 1;

  if v_user_profile_id is null then
    raise exception 'dismiss_pending: sin perfil activo en esta cuenta';
  end if;

  if p_action = 'posponer' then
    if p_preset not in ('manana', 'semana', 'mes') then
      raise exception 'dismiss_pending: preset invalido para posponer';
    end if;
    v_until := case p_preset
      when 'manana' then (current_date + 1)::timestamptz
      when 'semana' then (current_date + 7)::timestamptz
      else (current_date + interval '1 month')::timestamptz
    end;

    insert into public.pending_dismissal (account_id, location_id, pending_kind, entity_id, action, until, created_by, created_by_name)
    select p_account_id, p_location_id, p_pending_kind, r.entity_id, 'posponer', v_until, v_user_id, v_user_name
    from public.pending_raw_entities(p_account_id) r
    where r.pending_kind = p_pending_kind and r.location_id = p_location_id;

  else
    if p_reason is null or length(trim(p_reason)) = 0 then
      raise exception 'dismiss_pending: descartar exige motivo';
    end if;
    insert into public.pending_dismissal (account_id, location_id, pending_kind, entity_id, action, reason, created_by, created_by_name)
    values (p_account_id, p_location_id, p_pending_kind, p_entity_id, 'descartar', p_reason, v_user_id, v_user_name);
  end if;
end;
$$;


--
-- Name: dispatch_watchdog_scan(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_watchdog_scan(p_grace_minutes integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer := 0;
  v_row   record;
  v_carrier text;
  v_reason  text;
begin
  for v_row in
    select s.id, s.dispatch_error
      from public.sale s
      join public.locations l on l.id = s.location_id
     where s.service_type = 'own_delivery'
       and coalesce(l.dispatch_mode,'auto') = 'auto'
       and s.order_status in ('accepted','in_preparation','awaiting_collection')
       and s.carrier_order_id is null
       and s.delivery_alarm_at is null
       and s.created_at > now() - interval '24 hours'
       and now() - coalesce(s.accepted_at, s.created_at) > make_interval(mins => greatest(p_grace_minutes,1))
       -- R02 (05/10): un «propio» SIN dirección no es una alarma. La cocina
       -- lo ve en ámbar («Nosotros · falta la dirección») con sus dos
       -- acciones; el reparto nunca pinta el pedido en rojo.
       and coalesce(btrim(s.delivery_address), '') <> ''
       and not exists (
         select 1 from public.delivery_assignment da
          where da.sale_id = s.id and da.state not in ('failed','canceled'))
  loop
    select carrier, reason into v_carrier, v_reason
      from public.resolve_dispatch(v_row.id);

    if v_carrier is null then
      -- NO SE ENVIO. El guard hizo su trabajo. Se marca para que se vea, pero
      -- con el motivo REAL y sin decir «enviado».
      update public.sale s
         set delivery_alarm_at    = now(),
             delivery_alarm_kind   = 'no_despachado',
             delivery_alarm_ack_at = null,
             dispatch_error        = 'No se despachó: ' || coalesce(v_reason, 'sin motivo del resolutor'),
             updated_at            = now()
       where s.id = v_row.id;
    else
      update public.sale s
         set delivery_alarm_at    = now(),
             delivery_alarm_kind   = 'no_rider',
             delivery_alarm_ack_at = null,
             dispatch_error        = case
               when s.dispatch_error is not null and btrim(s.dispatch_error) <> ''
                 then 'No se pudo enviar a Catcher: ' || s.dispatch_error
               else 'Enviado a Catcher, sin rider tras ' || p_grace_minutes || ' min. Revisar/despachar a mano.'
             end,
             updated_at            = now()
       where s.id = v_row.id;
    end if;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


--
-- Name: duplicate_recipe_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duplicate_recipe_item(p_source_id uuid, p_new_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_src        recipe_item%ROWTYPE;
  v_new_id     uuid;
  v_new_name   text;
  v_line       record;
  v_step       record;
  v_new_line   uuid;
  v_new_step   uuid;
  -- mapas id_viejo → id_nuevo para reconstruir el enlace paso↔línea
  v_line_map   jsonb := '{}'::jsonb;
  v_step_map   jsonb := '{}'::jsonb;
BEGIN
  IF p_source_id IS NULL THEN
    RAISE EXCEPTION 'duplicate_recipe_item: falta el id de origen';
  END IF;

  SELECT * INTO v_src FROM recipe_item WHERE id = p_source_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'duplicate_recipe_item: receta % no encontrada', p_source_id;
  END IF;

  -- Guard de cuenta: el llamante debe pertenecer a la cuenta del plato origen.
  -- Usa el helper canónico del proyecto (belongs_to_account), igual que el resto
  -- del sistema. (En SQL Editor auth.uid() es null → fallará a propósito; se
  -- prueba desde la app, que sí tiene sesión.)
  IF NOT public.belongs_to_account(v_src.account_id) THEN
    RAISE EXCEPTION 'Sin permiso sobre la cuenta de esta receta';
  END IF;

  v_new_name := COALESCE(NULLIF(btrim(p_new_name), ''), v_src.name || ' (copia)');

  -- ── 1) El PLATO copia (sin folvy_code: lo pone el trigger; needs_review=true) ──
  INSERT INTO recipe_item (
    account_id, type, name, base_unit_id, cost_strategy, fixed_cost,
    created_by_name, yield_portions, source, ai_confidence, needs_review, is_stockable
  )
  VALUES (
    v_src.account_id, v_src.type, v_new_name, v_src.base_unit_id, v_src.cost_strategy,
    v_src.fixed_cost, COALESCE(v_src.created_by_name, 'Duplicado'),
    v_src.yield_portions, 'manual', NULL, true, v_src.is_stockable
  )
  RETURNING id INTO v_new_id;

  -- ── 2) Las LÍNEAS (mapeando id viejo→nuevo para los pasos) ──
  FOR v_line IN
    SELECT * FROM recipe_line WHERE parent_item_id = p_source_id
    ORDER BY position ASC, created_at ASC
  LOOP
    INSERT INTO recipe_line (
      account_id, parent_item_id, child_item_id,
      quantity_net, quantity_gross, unit_id, cut_type_id, comment, position
    )
    VALUES (
      v_src.account_id, v_new_id, v_line.child_item_id,
      v_line.quantity_net, v_line.quantity_gross, v_line.unit_id,
      v_line.cut_type_id, v_line.comment, v_line.position
    )
    RETURNING id INTO v_new_line;
    v_line_map := v_line_map || jsonb_build_object(v_line.id::text, v_new_line::text);
  END LOOP;

  -- ── 3) Los PASOS (contenido), mapeando id viejo→nuevo ──
  FOR v_step IN
    SELECT * FROM recipe_item_step WHERE recipe_item_id = p_source_id
    ORDER BY position ASC, created_at ASC
  LOOP
    INSERT INTO recipe_item_step (
      recipe_item_id, position, text, kind, duration_min, temperature_c, photo_url
    )
    VALUES (
      v_new_id, v_step.position, v_step.text, v_step.kind,
      v_step.duration_min, v_step.temperature_c, v_step.photo_url
    )
    RETURNING id INTO v_new_step;
    v_step_map := v_step_map || jsonb_build_object(v_step.id::text, v_new_step::text);
  END LOOP;

  -- ── 4) El ENLACE paso↔línea, reconstruido contra los ids NUEVOS ──
  --     Solo se copia el enlace si AMBOS (paso y línea) existen en los mapas.
  INSERT INTO recipe_item_step_line (account_id, step_id, line_id)
  SELECT
    v_src.account_id,
    (v_step_map->>sl.step_id::text)::uuid,
    (v_line_map->>sl.line_id::text)::uuid
  FROM recipe_item_step_line sl
  WHERE sl.step_id IN (SELECT id FROM recipe_item_step WHERE recipe_item_id = p_source_id)
    AND v_step_map ? sl.step_id::text
    AND v_line_map ? sl.line_id::text;

  RETURN v_new_id;
END;
$$;


--
-- Name: e2e_autoconteo_preparar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.e2e_autoconteo_preparar(p_caso text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- Los ids de la plantilla con el segundo grupo a 0000: el del carril lo lleva
  -- con su número (scripts/e2e/carril/comun.sql, en_carril), así que se compara así.
  v_acc uuid;
  v_loc uuid;
  v_emp uuid;
  v_count uuid;
  v_linea uuid;
  r record;
  i int := 0;
  plantilla constant text := '0000';
begin
  if auth.uid() is null
     or overlay(auth.uid()::text placing plantilla from 10 for 4) <> 'c01a0000-0000-4000-8000-0000000000a1' then
    raise exception 'Solo el administrador de la cuenta A de prueba.' using errcode = '42501';
  end if;
  select up.account_id into v_acc from public.user_profiles up where up.user_id = auth.uid() and up.active limit 1;
  if v_acc is null or overlay(v_acc::text placing plantilla from 10 for 4) <> 'c01a0000-0000-4000-8000-00000000000a' then
    raise exception 'El administrador de prueba no está en la cuenta A.' using errcode = '42501';
  end if;
  select id into v_loc from public.locations
   where account_id = v_acc and overlay(id::text placing plantilla from 10 for 4) = 'c01a0000-0000-4000-8000-0000000000a2';
  select id into v_emp from public.employees
   where account_id = v_acc and overlay(id::text placing plantilla from 10 for 4) = 'c01a0000-0000-4000-8000-0000000000e7';
  if v_loc is null or v_emp is null then
    raise exception 'Falta el local o el trabajador de prueba en esta cuenta (seed_autoconteo_e2e_staging.sql).';
  end if;

  if p_caso = 'hoy' then
    -- Que la tablet coja ESTE: los autoconteos abiertos del local, anulados.
    update public.inventory_count set status = 'anulado', updated_at = now(),
           notes = concat_ws(E'\n', notes, 'Anulado por la e2e del autoconteo (otro de hoy).')
     where account_id = v_acc and location_id = v_loc and kind = 'cycle' and status in ('abierto', 'contando', 'en_revision');
    -- El stock de partida otra vez (10, 20 y 30 ud): la pasada de móvil corre
    -- después de la de ordenador en el mismo carril, con su ajuste ya hecho.
    -- Como «apertura», que es una ENTRADA para el freno del recuento (b): si
    -- fuera un «ajuste», el freno compararía con el recuento aprobado de la
    -- pasada de ordenador más este movimiento, y cuántos minutos hay entre las
    -- dos pasadas decidiría si las latas piden recontar (lo cazó la entera 766:
    -- sola pasa siempre, con minutos de otras pruebas en medio, no).
    for r in
      select ri.id, (array[10, 20, 30])[right(overlay(ri.id::text placing plantilla from 10 for 4), 1)::int] as objetivo,
             (select coalesce(sum(qty_base), 0) from public.stock_movement m where m.recipe_item_id = ri.id and m.location_id = v_loc) as hay
        from public.recipe_item ri
       where ri.account_id = v_acc and overlay(ri.id::text placing plantilla from 10 for 4) like 'a7c10000-0000-4000-8000-00000000000_'
    loop
      if r.objetivo <> r.hay then
        insert into public.stock_movement (account_id, location_id, recipe_item_id, movement_type, qty_base, cost_provisional, source_type, occurred_at, created_by_name, notes)
        values (v_acc, v_loc, r.id, 'apertura', r.objetivo - r.hay, false, 'adjustment', now() - interval '1 minute', 'e2e autoconteo', 'vuelve al stock de partida de la e2e');
        perform public.recompute_location_stock(r.id, v_loc);
      end if;
    end loop;
    insert into public.inventory_count (account_id, location_id, kind, status, started_at, created_by_name)
    values (v_acc, v_loc, 'cycle', 'contando', now(), 'e2e autoconteo')
    returning id into v_count;
    for r in
      select ri.id from public.recipe_item ri
       where ri.account_id = v_acc and overlay(ri.id::text placing plantilla from 10 for 4) like 'a7c10000-0000-4000-8000-00000000000_'
       order by ri.id
    loop
      i := i + 1;
      insert into public.inventory_count_line (account_id, inventory_count_id, recipe_item_id, system_qty, position, assigned_to)
      values (v_acc, v_count, r.id,
              (select coalesce(sum(qty_base), 0) from public.stock_movement m where m.recipe_item_id = r.id and m.location_id = v_loc),
              i, v_emp);
    end loop;
  elsif p_caso = 'fallido' then
    insert into public.inventory_count (account_id, location_id, kind, status, started_at, created_at, created_by_name)
    values (v_acc, v_loc, 'cycle', 'contando', now() - interval '30 hours', now() - interval '30 hours', 'e2e autoconteo')
    returning id into v_count;
    select ri.id into r from public.recipe_item ri
     where ri.account_id = v_acc and overlay(ri.id::text placing plantilla from 10 for 4) = 'a7c10000-0000-4000-8000-000000000002';
    insert into public.inventory_count_line (account_id, inventory_count_id, recipe_item_id, system_qty, position, assigned_to)
    values (v_acc, v_count, r.id,
            (select coalesce(sum(qty_base), 0) from public.stock_movement m where m.recipe_item_id = r.id and m.location_id = v_loc), 1, v_emp)
    returning id into v_linea;
    -- Contado por la puerta, como lo cuenta la tablet (el disparador no deja otra).
    perform public.save_count_line(v_linea, jsonb_build_array(jsonb_build_object('method', 'peso', 'qty', 18)), null, null, null);
    update public.inventory_count
       set auto_apply_error = 'canceling statement due to lock timeout (fallo de prueba de la e2e)',
           auto_apply_failed_at = now() - interval '1 hour'
     where id = v_count;
  else
    raise exception 'Caso desconocido: % (hoy | fallido)', p_caso;
  end if;

  return jsonb_build_object('count_id', v_count, 'code', (select code from public.inventory_count where id = v_count));
end;
$$;


--
-- Name: e2e_c06_recorrido_base(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.e2e_c06_recorrido_base(p_company uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- Quién tiene el turno: el administrador de plataforma de prueba de este carril.
  v_por constant text := 'e2e C06 · ' || coalesce(auth.uid()::text, '');
begin
  -- W02 (carriles): cada e2e entra con su copia del administrador de plataforma
  -- de prueba, con el segundo grupo del id cambiado por el número de su carril
  -- (scripts/e2e/carril/comun.sql, en_carril). Vale el de la plantilla y el de
  -- cualquier carril, siempre que sea administrador de plataforma activo.
  if auth.uid() is null
     or overlay(auth.uid()::text placing '0000' from 10 for 4) <> 'c0600000-0000-4000-8000-0000000000f0'
     or not exists (select 1 from public.platform_admins where user_id = auth.uid() and active) then
    raise exception 'Solo el administrador de plataforma de prueba del C06.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.company c join public.accounts a on a.id = c.account_id
                  where c.id = p_company and a.name like 'Recorrido de Prueba C06 %' and a.product_brand = 'contabilidad') then
    raise exception 'Esa empresa no es de una cuenta del recorrido del C06.' using errcode = '42501';
  end if;
  -- El turno se mira y se coge en un solo paso: dos carriles a la vez esperan aquí.
  perform pg_advisory_xact_lock(hashtext('e2e_c06_recorrido_base'));
  if exists (select 1 from public.conta_diez_base
              where nombre_bd = 'C0009' and company_id <> p_company
                and puesto_por <> v_por and created_at > now() - interval '10 minutes') then
    return 'ocupada';
  end if;
  delete from public.conta_diez_base where nombre_bd = 'C0009' and company_id <> p_company;
  if not exists (select 1 from public.conta_diez_base where company_id = p_company) then
    perform public.conta_diez_base_poner(p_company, 'C0009',
      'Recorrido e2e del C06 (staging): traer de Diez leyendo la C0009.', v_por);
  end if;
  return 'C0009';
end;
$$;


--
-- Name: FUNCTION e2e_c06_recorrido_base(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.e2e_c06_recorrido_base(p_company uuid) IS 'SOLO STAGING (seed_c06_recorrido_staging.sql). El recorrido e2e del C06 registra la C0009 para su empresa, por turnos entre carriles («ocupada» mientras otro la tenga, hasta 10 min). Solo el administrador de plataforma de prueba (el de la plantilla o el de su carril).';


--
-- Name: e2e_f01_preparar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.e2e_f01_preparar(p_que text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  org constant uuid := 'f01e2e00-0000-4000-8000-0000000000a0';
  v_cuenta uuid;
  v_marcas integer := 0;
begin
  if exists (select 1 from public.accounts where id in ('51ad1792-6629-4ef7-833a-b57b09a86710', '00000000-0000-0000-0000-000000000001')) then
    raise exception 'e2e_f01_preparar: esta base tiene cuentas de producción.';
  end if;
  if p_que not in ('empezar', 'limpiar') then raise exception 'e2e_f01_preparar: «empezar» o «limpiar».'; end if;
  -- La cuenta del que llama: la A de la plantilla o la de su carril, la que tiene la carta de prueba.
  select up.account_id into v_cuenta from public.user_profiles up
   where up.user_id = auth.uid() and up.role = 'admin'
     and exists (select 1 from public.external_integration ei where ei.account_id = up.account_id and ei.external_org_id = org)
   limit 1;
  if v_cuenta is null then raise exception 'e2e_f01_preparar: solo el administrador de la cuenta con la carta de prueba.' using errcode = '42501'; end if;

  -- Lo que dejó un alta anterior, archivado (no se borra: lo que apunte a ello sigue en pie).
  update public.menu_item mi set archived_at = now(), updated_at = now()
   where mi.account_id = v_cuenta and mi.archived_at is null
     and mi.brand_id in (select b.id from public.brand b where b.account_id = v_cuenta and b.name = 'Latina de Prueba' and b.archived_at is null);
  delete from public.brand_licensing_agreement a
   where a.account_id = v_cuenta and a.brand_id in (select b.id from public.brand b where b.account_id = v_cuenta and b.name = 'Latina de Prueba');
  delete from public.external_brand_map where account_id = v_cuenta and source = 'lastapp' and external_brand_id like 'f01e2e-lp-%';
  delete from public.external_brand_alta where account_id = v_cuenta and external_org_id = org;
  delete from public.external_brand_oculta where account_id = v_cuenta and external_org_id = org;
  update public.brand b set archived_at = now(), is_active = false, updated_at = now()
   where b.account_id = v_cuenta and b.name = 'Latina de Prueba' and b.archived_at is null;
  get diagnostics v_marcas = row_count;

  if p_que = 'empezar' then
    update public.external_catalog_product set seen_in_catalog_at = now(), missing_since = null, last_synced_at = now()
     where account_id = v_cuenta and external_org_id = org;
  end if;
  return jsonb_build_object('cuenta', v_cuenta, 'marcas_archivadas', v_marcas);
end $$;


--
-- Name: e2e_f01b_preparar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.e2e_f01b_preparar() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  org constant uuid := 'f01e2e00-0000-4000-8000-0000000000a0';
  v_cuenta uuid;
  r jsonb;
begin
  if exists (select 1 from public.accounts where id in ('51ad1792-6629-4ef7-833a-b57b09a86710', '00000000-0000-0000-0000-000000000001')) then
    raise exception 'e2e_f01b_preparar: esta base tiene cuentas de producción.';
  end if;
  select up.account_id into v_cuenta from public.user_profiles up
   where up.user_id = auth.uid() and up.role = 'admin'
     and exists (select 1 from public.external_integration ei where ei.account_id = up.account_id and ei.external_org_id = org)
   limit 1;
  if v_cuenta is null then raise exception 'e2e_f01b_preparar: solo el administrador de la cuenta con la carta de prueba.' using errcode = '42501'; end if;

  -- Lo que dejó una pasada anterior al guardar.
  delete from public.modifier_recipe_impact i using public.modifier_option o
   where i.modifier_option_id = o.id and o.account_id = v_cuenta and o.pos_modifier_id like 'f01e2e-extra-%';
  delete from public.modifier_option where account_id = v_cuenta and pos_modifier_id like 'f01e2e-extra-%';
  delete from public.modifier_group where account_id = v_cuenta and external_source = 'lastapp' and external_id = 'f01e2e-grupo-extras';
  -- La carta y sus extras, vistos ahora; la marca, dada de alta si no lo está.
  perform public.e2e_f01_preparar('empezar');
  update public.external_catalog_modifier set seen_in_catalog_at = now(), missing_since = null where account_id = v_cuenta and external_org_id = org;
  -- Quién: nadie (null). brand.created_by apunta a employees y el administrador
  -- de la prueba no es empleado; hasta la 0650, _f01_alta_marca lo ponía tal
  -- cual y fallaba (23503). Lo que mide esta preparación es la carta, no quién.
  r := public._f01_alta_marca(v_cuenta, org, 'Latina de Prueba', 'Latina de Prueba', true, null, false, null, 'e2e F01b');
  return jsonb_build_object('cuenta', v_cuenta, 'brand_id', r->>'brand_id');
end $$;


--
-- Name: e2e_f01c_preparar(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.e2e_f01c_preparar(p_que text, p_juego text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_g      text;
  v_suf    text;
  v_cod    text;
  v_org    uuid;
  v_cuenta uuid;
  v_marca  uuid;
  v_alitas uuid;
  v_t1     text;
  v_t2     text;
  v_centro uuid;
  v_merc   uuid;
  v_sesion uuid;
  v_solas  jsonb;
  v_borradas integer := 0;
  v_n      integer := 0;
begin
  if exists (select 1 from public.accounts where id in ('51ad1792-6629-4ef7-833a-b57b09a86710', '00000000-0000-0000-0000-000000000001')) then
    raise exception 'e2e_f01c_preparar: esta base tiene cuentas de producción.';
  end if;
  if p_que not in ('empezar', 'pasada', 'limpiar') then raise exception 'e2e_f01c_preparar: «empezar», «pasada» o «limpiar».'; end if;
  if p_juego not in ('ordenador', 'movil') then raise exception 'e2e_f01c_preparar: el juego es «ordenador» o «movil».'; end if;
  v_g := case p_juego when 'ordenador' then '8000' else '8001' end;
  v_suf := case p_juego when 'ordenador' then '' else ' M' end;
  v_cod := case p_juego when 'ordenador' then 'f01c' else 'f01c-m' end;
  v_org := ('f01c2e00-0000-4000-' || v_g || '-0000000000a0')::uuid;

  -- La cuenta del que llama: la A de la plantilla o la de su carril, la que tiene la carta de prueba.
  select up.account_id into v_cuenta from public.user_profiles up
   where up.user_id = auth.uid() and up.role = 'admin'
     and exists (select 1 from public.external_integration ei where ei.account_id = up.account_id and ei.external_org_id = v_org)
   limit 1;
  if v_cuenta is null then raise exception 'e2e_f01c_preparar: solo el administrador de la cuenta con la carta de prueba.' using errcode = '42501'; end if;

  if p_que = 'pasada' then
    -- Solo las de este juego: lo que la pasada une en el otro no es de esta prueba.
    select coalesce(jsonb_agg(public._f01c_unir(v_cuenta, c.org, c.nombre, (c.comparacion->>'brand_id')::uuid, 'sola', c.comparacion, null, null)), '[]'::jsonb)
      into v_solas
      from public._f01c_candidatas(v_cuenta) c
     where c.org = v_org and (c.comparacion->>'identica')::boolean;
    return jsonb_build_object('cuenta', v_cuenta, 'juego', p_juego, 'reconocidas_solas', v_solas);
  end if;

  select b.id into v_marca from public.brand b where b.account_id = v_cuenta and b.name = 'Pollería de Prueba' || v_suf and b.archived_at is null limit 1;
  -- Las tiendas de Last de la prueba en esta cuenta (en un carril tienen otro id).
  select max(e.external_location_id::text) filter (where e.external_brand_name = 'Pollería de Prueba' || v_suf),
         max(e.external_location_id::text) filter (where e.external_brand_name = 'Pollos Nuevos' || v_suf)
    into v_t1, v_t2
    from public.external_catalog_product e where e.account_id = v_cuenta and e.external_org_id = v_org;
  select lm.location_id into v_centro from public.external_location_map lm where lm.account_id = v_cuenta and lm.source = 'lastapp' and lm.external_location_id = v_t1;
  select lm.location_id into v_merc from public.external_location_map lm where lm.account_id = v_cuenta and lm.source = 'lastapp' and lm.external_location_id = v_t2;

  -- Express y Nuevos, sin unir: sin alta, sin vínculos, sin avisos ni decisiones.
  delete from public.external_brand_alta where account_id = v_cuenta and external_org_id = v_org and external_brand_name <> 'Pollería de Prueba' || v_suf;
  delete from public.external_brand_map where account_id = v_cuenta and source = 'lastapp' and external_brand_id in (v_cod || '-px-2', v_cod || '-pn-3');
  delete from public.f01_marca_reconocida where account_id = v_cuenta and external_org_id = v_org;
  delete from public.brand_location_availability where account_id = v_cuenta and brand_id = v_marca and location_id is distinct from v_centro;
  -- Lo que la unión sembró en la carta (las matrículas de Pollos Nuevos),
  -- archivado y con la matrícula apartada: el sembrado no resucita una archivada,
  -- y la pasada siguiente tiene que poder volver a sembrarla.
  update public.menu_item set archived_at = coalesce(archived_at, now()), external_id = external_id || '-e2e-' || id::text, updated_at = now()
   where account_id = v_cuenta and brand_id = v_marca and external_id not like '%-e2e-%'
     and external_id not in (select distinct e.organization_product_id::text from public.external_catalog_product e
                              where e.account_id = v_cuenta and e.external_org_id = v_org and e.external_brand_name = 'Pollería de Prueba' || v_suf);
  -- Alitas, otra vez sin receta; Croquetas, otra vez sin artículo.
  select mi.recipe_item_id into v_alitas from public.menu_item mi
   where mi.account_id = v_cuenta and mi.brand_id = v_marca and mi.name = 'Alitas de Prueba' || v_suf and mi.archived_at is null limit 1;
  delete from public.recipe_line where account_id = v_cuenta and parent_item_id = v_alitas;
  update public.menu_item set recipe_item_id = null, updated_at = now()
   where account_id = v_cuenta and brand_id = v_marca and name = 'Croquetas de Prueba' || v_suf and recipe_item_id is not null;
  delete from public.f01_receta_puesta where account_id = v_cuenta
     and recipe_item_id in (select mi.recipe_item_id from public.menu_item mi where mi.account_id = v_cuenta and mi.brand_id = v_marca);
  -- Las ventas de pasadas anteriores de este juego, BORRADAS (con lo que
  -- descontaron): una anulada se seguía contando y las cifras crecían.
  delete from public.stock_movement sm
   where sm.account_id = v_cuenta and sm.source_type = 'sale'
     and sm.source_id in (select s.id from public.sale s where s.account_id = v_cuenta and s.source = 'lastapp' and s.external_ref like 'f01c-e2e-' || p_juego || '-%');
  delete from public.sale s where s.account_id = v_cuenta and s.source = 'lastapp' and s.external_ref like 'f01c-e2e-' || p_juego || '-%';
  get diagnostics v_borradas = row_count;
  update public.external_catalog_product set seen_in_catalog_at = now(), missing_since = null, last_synced_at = now()
   where account_id = v_cuenta and external_org_id = v_org;

  if p_que = 'empezar' then
    insert into public.sale (account_id, location_id, brand_id, source, sold_at, status, order_status, total, is_active,
                             external_ref, external_brand_text, external_location_text, raw_products, raw_tab)
    select v_cuenta, x.loc, x.marca, 'lastapp', now(), 'open', 'accepted', x.cents / 100.0, true,
           'f01c-e2e-' || p_juego || '-' || x.n, x.codigo, x.tienda,
           jsonb_build_array(jsonb_build_object('name', x.plato || v_suf, 'quantity', 1, 'price', x.cents,
                                                'organizationProductId', 'f01c2e00-0000-4000-' || v_g || '-0000000001' || x.mat))::text, '{}'
      from (values (1, v_centro, v_marca, v_cod || '-pp-1', v_t1, 'Alitas de Prueba', 750, 'd5'),
                   (2, v_merc, null::uuid, v_cod || '-px-2', v_t2, 'Pollo asado de Prueba', 1250, 'd1'),
                   (3, v_merc, null::uuid, v_cod || '-pn-3', v_t2, 'Pollo asado de Prueba', 1250, 'e1'),
                   (4, v_merc, null::uuid, v_cod || '-pn-3', v_t2, 'Wrap de Pollo', 850, 'e4')) x(n, loc, marca, codigo, tienda, plato, cents, mat);
    get diagnostics v_n = row_count;
    -- Cada venta, casada como la casaría el pedido.
    perform public.reprocess_sale(s.id) from public.sale s
     where s.account_id = v_cuenta and s.source = 'lastapp' and s.external_ref like 'f01c-e2e-' || p_juego || '-_';

    -- La lectura de «Alitas de Prueba» (como la deja extract-recipe), por confirmar.
    insert into public.recipe_item_ai_session (account_id, kind, status, input_text, parsed_result, ai_model)
    values (v_cuenta, 'conversational', 'pending_review', 'Alitas de Prueba' || v_suf || ': 6 ud de alitas de pollo',
            jsonb_build_object('dish', jsonb_build_object('name', 'Alitas de Prueba' || v_suf, 'brand', 'Pollería de Prueba' || v_suf),
                               'lines', jsonb_build_array(jsonb_build_object('raw_text', 'Alitas de pollo', 'quantity', 6, 'unit', 'ud'))),
            'e2e (sin IA)')
    returning id into v_sesion;
  end if;
  return jsonb_build_object('cuenta', v_cuenta, 'juego', p_juego, 'marca', v_marca, 'ventas', v_n, 'borradas', v_borradas, 'sesion', v_sesion);
end $$;


--
-- Name: edge_drift_registrar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edge_drift_registrar(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_res jsonb;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'edge_drift_registrar: p_rows debe ser un array jsonb';
  end if;
  if jsonb_array_length(p_rows) = 0 then
    raise exception 'edge_drift_registrar: p_rows vacio; no se toca el estado';
  end if;

  with entrada as (
    select r.slug, r.repo_path, r.repo_blob_sha, r.repo_commit_at,
           coalesce(r.desplegada, false) as desplegada,
           r.deploy_version, r.deploy_bundle_sha, r.deploy_at,
           coalesce(nullif(r.contenido,''), 'no_comprobable') as contenido,
           r.contenido_detalle
      from jsonb_to_recordset(p_rows) as r(
             slug text, repo_path text, repo_blob_sha text,
             repo_commit_at timestamptz, desplegada boolean,
             deploy_version integer, deploy_bundle_sha text,
             deploy_at timestamptz, contenido text, contenido_detalle text)
     where nullif(btrim(r.slug), '') is not null
  ),
  con_historia as (
    select e.*,
           t.deploy_bundle_sha as sha_anterior,
           t.repo_blob_sha     as blob_anterior,
           t.comprobado_at     as visto_anterior_at,
           t.estado            as estado_anterior,
           (t.slug is not null) as hay_historia
      from entrada e
      left join public.edge_function_deploy_state t on t.slug = e.slug
  ),
  juzgada as (
    select h.*,
           case
             when not h.desplegada and h.repo_path is not null then 'ok_sin_desplegar'
             when h.desplegada and h.repo_path is null         then 'sin_fuente_en_repo'
             when h.contenido = 'igual'                        then 'ok'
             when h.contenido = 'distinto'
                  and h.deploy_at > coalesce(h.repo_commit_at, '-infinity'::timestamptz)
                                                               then 'deploy_sin_commit'
             when h.contenido = 'distinto'                     then 'commit_sin_desplegar'
             when not h.hay_historia                           then 'ok'
             when h.deploy_bundle_sha is not null
                  and h.sha_anterior is distinct from h.deploy_bundle_sha
                  and (h.repo_commit_at is null
                       or h.repo_commit_at < h.visto_anterior_at)
                                                               then 'deploy_sin_commit'
             when h.blob_anterior is not null
                  and h.repo_blob_sha is distinct from h.blob_anterior
                  and h.sha_anterior is not distinct from h.deploy_bundle_sha
                                                               then 'commit_sin_desplegar'
             when h.estado_anterior = 'commit_sin_desplegar'
                  and h.sha_anterior is not distinct from h.deploy_bundle_sha
                                                               then 'commit_sin_desplegar'
             else 'ok'
           end as estado
      from con_historia h
  )
  insert into public.edge_function_deploy_state as t (
    slug, repo_path, repo_blob_sha, repo_commit_at, desplegada, deploy_version,
    deploy_bundle_sha, deploy_at, contenido, contenido_detalle, estado,
    drift_desde, comprobado_at, bundle_sha_anterior, comprobado_anterior_at)
  select j.slug, j.repo_path, j.repo_blob_sha, j.repo_commit_at, j.desplegada,
         j.deploy_version, j.deploy_bundle_sha, j.deploy_at, j.contenido,
         j.contenido_detalle, j.estado,
         case when j.estado in ('ok','ok_sin_desplegar') then null else now() end,
         now(), j.sha_anterior, j.visto_anterior_at
    from juzgada j
  on conflict (slug) do update
    set repo_path         = excluded.repo_path,
        repo_blob_sha     = excluded.repo_blob_sha,
        repo_commit_at    = excluded.repo_commit_at,
        desplegada        = excluded.desplegada,
        deploy_version    = excluded.deploy_version,
        bundle_sha_anterior    = t.deploy_bundle_sha,
        comprobado_anterior_at = t.comprobado_at,
        deploy_bundle_sha = excluded.deploy_bundle_sha,
        deploy_at         = excluded.deploy_at,
        contenido         = excluded.contenido,
        contenido_detalle = excluded.contenido_detalle,
        estado            = excluded.estado,
        drift_desde       = case
                              when excluded.estado in ('ok','ok_sin_desplegar') then null
                              when t.estado in ('ok','ok_sin_desplegar')        then now()
                              else coalesce(t.drift_desde, now())
                            end,
        comprobado_at     = now();

  delete from public.edge_function_deploy_state
   where slug not in (select slug from jsonb_to_recordset(p_rows) as r(slug text)
                       where nullif(btrim(r.slug),'') is not null);

  select jsonb_object_agg(estado, n) into v_res
    from (select estado, count(*) as n
            from public.edge_function_deploy_state group by estado) q;

  return coalesce(v_res, '{}'::jsonb);
end;
$$;


--
-- Name: edge_drift_salud_watchdog(integer, integer, interval, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edge_drift_salud_watchdog(p_horas_alto integer DEFAULT 48, p_horas_critico integer DEFAULT 120, p_debounce_window interval DEFAULT '20:00:00'::interval, p_dry boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cron_ok  boolean;
  v_filas    integer;
  v_ultima   timestamptz;
  v_horas    numeric;
  v_sev      text := null;
  v_motivo   text := null;
  v_detalle  text := '';
  s          record;
  v_dias     integer;
  v_sev_s    text;
  v_cad      jsonb := '[]'::jsonb;
BEGIN
  SELECT EXISTS (SELECT 1 FROM cron.job
                  WHERE jobname = 'edge-drift-watchdog' AND active)
    INTO v_cron_ok;

  SELECT count(*), max(comprobado_at)
    INTO v_filas, v_ultima
    FROM public.edge_function_deploy_state;

  v_horas := CASE WHEN v_ultima IS NULL THEN NULL
                  ELSE round((extract(epoch FROM (now() - v_ultima)) / 3600)::numeric, 1) END;

  IF NOT v_cron_ok THEN
    v_sev := 'CRITICO'; v_motivo := 'cron_ausente';
    v_detalle := 'El cron `edge-drift-watchdog` no existe o esta desactivado. '
      || 'Sin el, nadie compara lo desplegado con main.';
  ELSIF v_ultima IS NULL THEN
    v_sev := 'ALTO'; v_motivo := 'nunca_ha_corrido';
    v_detalle := 'El vigia de drift no ha registrado NADA todavia. Lo normal es que '
      || 'falten los secrets: prueba la funcion y mira si responde '
      || '"faltan secrets: MGMT_API_TOKEN, GITHUB_TOKEN".';
  ELSIF v_horas >= greatest(coalesce(p_horas_critico, 120), 1) THEN
    v_sev := 'CRITICO'; v_motivo := 'parado';
    v_detalle := 'El vigia de drift lleva ' || v_horas::text || ' horas sin refrescar su estado.';
  ELSIF v_horas >= greatest(coalesce(p_horas_alto, 48), 1) THEN
    v_sev := 'ALTO'; v_motivo := 'retrasado';
    v_detalle := 'El vigia de drift lleva ' || v_horas::text || ' horas sin refrescar su estado '
      || '(deberia hacerlo cada 24 h).';
  END IF;

  IF v_sev IS NOT NULL AND NOT p_dry THEN
    PERFORM public._queue_system_alert(
      'edge_drift_salud',
      v_sev || ': el vigia de divergencia con main no esta vigilando',
      v_detalle || chr(10) || chr(10)
        || 'Ultima comprobacion: '
        || coalesce(to_char(v_ultima at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), 'nunca')
        || chr(10)
        || 'Funciones en la tabla de estado: ' || v_filas::text || chr(10)
        || 'Cron activo: ' || CASE WHEN v_cron_ok THEN 'si' ELSE 'NO' END || chr(10) || chr(10)
        || 'Por que importa: mientras esto siga asi, cualquier despliegue puede pisar '
        || 'trabajo no commiteado y no nos enteraremos. Es lo que paso el 13/08 con '
        || 'hubrise-webhook: 14 dias y 148 pedidos sin el codigo que ve el cliente.' || chr(10) || chr(10)
        || 'Que mirar, por orden: que MGMT_API_TOKEN y GITHUB_TOKEN sigan validos en los '
        || 'secrets de Edge Functions, los logs de `edge-drift-watchdog`, y que el cron '
        || 'siga programado.',
      'edge_drift_salud_' || v_sev || '_' || v_motivo || '_'
        || to_char(now() at time zone 'Europe/Madrid', 'YYYYMMDD'),
      p_debounce_window
    );
  END IF;

  -- Caducidad de secrets: INDEPENDIENTE de lo anterior. Un token que caduca
  -- dentro de 20 dias hay que avisarlo aunque hoy el vigia funcione bien.
  FOR s IN
    SELECT * FROM public.secret_expiry
     WHERE caduca_el <= (current_date + dias_aviso)
     ORDER BY caduca_el
  LOOP
    v_dias := s.caduca_el - current_date;
    v_sev_s := CASE
                 WHEN v_dias < 0                THEN 'CRITICO'
                 WHEN v_dias <= s.dias_critico  THEN 'CRITICO'
                 ELSE 'ALTO'
               END;
    v_cad := v_cad || jsonb_build_object('nombre', s.nombre, 'dias', v_dias,
                                         'severidad', v_sev_s);

    IF NOT p_dry THEN
      PERFORM public._queue_system_alert(
        'secret_caduca',
        v_sev_s || ': el secret ' || s.nombre
          || CASE WHEN v_dias < 0
                  THEN ' CADUCO hace ' || abs(v_dias)::text || ' dias'
                  ELSE ' caduca en ' || v_dias::text || ' dias' END,
        CASE WHEN v_dias < 0
             THEN 'El secret ' || s.nombre || ' caduco el '
                  || to_char(s.caduca_el, 'DD/MM/YYYY') || '. Lo que dependa de el ya '
                  || 'esta fallando.'
             ELSE 'El secret ' || s.nombre || ' caduca el '
                  || to_char(s.caduca_el, 'DD/MM/YYYY') || ', dentro de ' || v_dias::text
                  || ' dias.' END
          || chr(10) || chr(10)
          || coalesce(s.descripcion, '') || chr(10) || chr(10)
          || 'Como se renueva: ' || coalesce(s.donde_renovar, '(sin instrucciones guardadas)')
          || chr(10) || chr(10)
          || 'Se avisa con antelacion a proposito: cuando caduque, el vigia de '
          || 'divergencia deja de comparar produccion con el repositorio y volvemos '
          || 'a estar ciegos ante un deploy que pise trabajo no commiteado.',
        'secret_caduca_' || s.nombre || '_' || v_sev_s || '_'
          || to_char(now() at time zone 'Europe/Madrid', 'YYYYMMDD'),
        p_debounce_window
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'avisa_salud',   v_sev IS NOT NULL,
    'severidad',     v_sev,
    'motivo',        v_motivo,
    'cron_ok',       v_cron_ok,
    'filas',         v_filas,
    'horas_desde_ultima', v_horas,
    'caducidades',   v_cad,
    'seco',          p_dry);
END;
$$;


--
-- Name: edge_drift_watchdog(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edge_drift_watchdog(p_debounce_window interval DEFAULT '20:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record; v_sev text; v_lineas text := ''; v_n integer := 0; v_firma text := '';
begin
  for r in
    select s.*,
           case s.estado
             when 'sin_fuente_en_repo'        then 1
             when 'deploy_sin_commit'         then 2
             when 'commit_sin_desplegar'      then 3
             when 'posible_deploy_sin_commit' then 4
           end as orden
      from public.edge_function_deploy_state s
     where s.estado not in ('ok','ok_sin_desplegar')
     order by orden, s.slug
  loop
    v_n := v_n + 1;
    v_firma := v_firma || r.slug || ':' || r.estado || ';';
    v_lineas := v_lineas || '- ' || r.slug || ' [' || r.estado || ']' || chr(10)
      || '    desplegada: '
      || coalesce(to_char(r.deploy_at at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), 'nunca')
      || case when r.deploy_version is not null then ' (v' || r.deploy_version || ')' else '' end
      || chr(10)
      || '    ultimo commit en main: '
      || coalesce(to_char(r.repo_commit_at at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), 'sin fichero')
      || chr(10)
      || '    divergente desde: '
      || coalesce(to_char(r.drift_desde at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'), '-')
      || case when r.contenido_detalle is not null
              then chr(10) || '    difiere: ' || r.contenido_detalle else '' end
      || chr(10);
  end loop;

  if v_n = 0 then
    return 0;
  end if;

  select case
           when count(*) filter (where estado in ('sin_fuente_en_repo','deploy_sin_commit')) > 0
             then 'CRITICO'
           when count(*) filter (where estado = 'commit_sin_desplegar') > 0 then 'ALTO'
           else 'AVISO'
         end
    into v_sev
    from public.edge_function_deploy_state
   where estado not in ('ok','ok_sin_desplegar');

  perform public._queue_system_alert(
    'edge_drift',
    v_sev || ': ' || v_n::text || ' Edge Function(s) no coinciden con main',
    'Lo que corre en produccion y lo que hay en el repositorio no son lo mismo:'
      || chr(10) || chr(10) || v_lineas || chr(10)
      || 'Que significa cada estado:' || chr(10)
      || '  sin_fuente_en_repo   corre codigo que no esta en main. Nadie puede leerlo '
      || 'ni revisarlo, y el proximo deploy lo borra.' || chr(10)
      || '  deploy_sin_commit    se desplego algo que no se commiteo. Es exactamente '
      || 'lo que paso el 13/08: 14 dias y 148 pedidos sin codigo de plataforma.' || chr(10)
      || '  commit_sin_desplegar hay un arreglo en main que no esta corriendo. '
      || 'Falta desplegarlo.' || chr(10)
      || '  posible_deploy_sin_commit  las fechas cuadran mal pero no se pudo leer el '
      || 'contenido desplegado para probarlo.' || chr(10) || chr(10)
      || 'Regla del proyecto: ninguna correccion vive solo en el desplegado. Si se toca '
      || 'una edge function, se commitea antes o inmediatamente despues.',
    'edge_drift_' || v_sev || '_' || md5(v_firma),
    p_debounce_window
  );

  return v_n;
end;
$$;


--
-- Name: edit_clock_entry(uuid, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_clock_entry(p_entry_id uuid, p_datetime timestamp with time zone, p_reason text, p_type text DEFAULT NULL::text, p_actor_label text DEFAULT NULL::text) RETURNS public.clock_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acct uuid; v_emp uuid; v_row public.clock_entries;
begin
  if coalesce(trim(p_reason),'') = '' then raise exception 'MOTIVO_OBLIGATORIO'; end if;
  select employee_id into v_emp from public.clock_entries where id = p_entry_id;
  if v_emp is null then raise exception 'FICHAJE_NO_EXISTE'; end if;
  v_acct := public._account_of_employee(v_emp);
  -- L1a (28/10): el administrador, o el encargado de esa persona (nunca a sí mismo).
  if not public._puede_corregir(v_emp, v_acct) then raise exception 'NO_AUTORIZADO'; end if;
  if p_type is not null and p_type not in ('entrada','salida') then raise exception 'TIPO_INVALIDO'; end if;

  perform set_config('app.clock_edit_reason', p_reason, true);
  perform set_config('app.clock_edit_actor', coalesce(p_actor_label,''), true);

  update public.clock_entries
     set datetime = p_datetime,
         real_datetime = p_datetime,
         type = coalesce(p_type, type)
   where id = p_entry_id
   returning * into v_row;
  return v_row;
end $$;


--
-- Name: effective_price(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.effective_price(p_menu_item_id uuid, p_channel_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (select mio.price from public.menu_item_override mio
      where mio.menu_item_id = p_menu_item_id
        and p_channel_id is not null and mio.channel_id = p_channel_id
        and p_location_id is not null and mio.location_id = p_location_id
        and mio.price is not null
      limit 1),
    (select mio.price from public.menu_item_override mio
      where mio.menu_item_id = p_menu_item_id
        and mio.channel_id is null
        and p_location_id is not null and mio.location_id = p_location_id
        and mio.price is not null
      limit 1),
    (select mio.price from public.menu_item_override mio
      where mio.menu_item_id = p_menu_item_id
        and p_channel_id is not null and mio.channel_id = p_channel_id
        and mio.location_id is null
        and mio.price is not null
      limit 1),
    (select mi.price from public.menu_item mi where mi.id = p_menu_item_id)
  );
$$;


