--
-- Name: encender_coste_medio_quietos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.encender_coste_medio_quietos(p_account_id uuid) RETURNS TABLE(nombre text, encendido boolean, antes numeric, despues numeric, lineas integer, descartadas integer, motivo text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_r   record;
  v_res jsonb;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'encender_coste_medio_quietos: sin permiso sobre la cuenta %', p_account_id;
  end if;
  for v_r in
    select r.recipe_item_id from recipe_item_cost_rollout r
      join recipe_item ri on ri.id = r.recipe_item_id
     where r.account_id = p_account_id and r.grupo = 'quieto' and r.estado = 'pendiente'
     order by ri.name
  loop
    v_res := public.approve_average_cost(v_r.recipe_item_id, true);
    nombre      := v_res->>'nombre';
    encendido   := (v_res->>'encendido')::boolean;
    antes       := (v_res->>'antes')::numeric;
    despues     := coalesce((v_res->>'despues')::numeric, (v_res->>'con_media')::numeric);
    lineas      := (v_res->>'lineas')::integer;
    descartadas := (v_res->>'descartadas')::integer;
    motivo      := v_res->>'motivo';
    return next;
  end loop;
end;
$$;


--
-- Name: encolar_alerta(text, text, text, text, interval, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.encolar_alerta(p_kind text, p_subject text, p_message text, p_debounce_kind text DEFAULT NULL::text, p_debounce_window interval DEFAULT NULL::interval, p_account_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_severity text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
  v_cuenta uuid;
BEGIN
  -- DM1 · PR 2a (31/10): una cuenta de demo no cuenta en los avisos. La del
  -- aviso, o la de su local, o la de su marca; sin ninguna, sigue como antes.
  v_cuenta := coalesce(
    p_account_id,
    (SELECT l.account_id FROM public.locations l WHERE l.id = p_location_id),
    (SELECT b.account_id FROM public.brand b WHERE b.id = p_brand_id));
  IF v_cuenta IS NOT NULL AND NOT public.cuenta_puede_salir(v_cuenta) THEN
    RETURN NULL;
  END IF;

  -- El antirruido, igual que antes. Devuelve NULL cuando NO encola, para que
  -- el llamador pueda distinguir «encolado» de «callado a propósito». La vieja
  -- devolvía void y las dos cosas se veían igual desde fuera.
  IF p_debounce_kind IS NOT NULL THEN
    -- 1) Ya hay uno pendiente con esta clave: no apilar.
    IF EXISTS (
      SELECT 1 FROM public.system_alert_queue
       WHERE debounce_kind = p_debounce_kind AND status = 'pending'
    ) THEN
      RETURN NULL;
    END IF;

    -- 2) Ya se encoló uno con esta clave dentro de la ventana: no repetir.
    IF p_debounce_window IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.system_alert_queue
       WHERE debounce_kind = p_debounce_kind
         AND created_at > now() - p_debounce_window
    ) THEN
      RETURN NULL;
    END IF;
  END IF;

  INSERT INTO public.system_alert_queue
    (kind, subject, message, debounce_kind, account_id, location_id, brand_id, severity)
  VALUES
    (p_kind, p_subject, p_message, p_debounce_kind,
     p_account_id, p_location_id, p_brand_id, p_severity)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: enqueue_clockout_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_clockout_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_forgot_min int;
  v_count int := 0;
  r record;
BEGIN
  SELECT forgot_clockout_min INTO v_forgot_min FROM app_settings WHERE scope='global' LIMIT 1;
  v_forgot_min := COALESCE(v_forgot_min, 30);

  FOR r IN
    WITH abiertos AS (
      SELECT DISTINCT ON (ce.employee_id)
             ce.id AS clock_entry_id, ce.employee_id, ce.datetime AS entrada_at,
             e.name, e.location_id, e.phone, e.forgot_clockout_reminder,
             l.account_id
      FROM clock_entries ce
      JOIN employees e ON e.id = ce.employee_id
      JOIN locations l ON l.id = e.location_id
      WHERE NOT ce.voided AND ce.datetime::date = now()::date
      ORDER BY ce.employee_id, ce.datetime DESC
    ),
    candidatos AS (
      SELECT a.*, st.start_time, st.end_time,
             abs(EXTRACT(epoch FROM (a.entrada_at::time - st.start_time))) AS dist_seg
      FROM abiertos a
      JOIN schedules s ON s.location_id = a.location_id
        AND s.week_start = date_trunc('week', now())::date
        AND s.status = 'published'
      JOIN shift_templates st ON st.location_id = a.location_id AND st.active
      WHERE a.forgot_clockout_reminder = true
        AND s.cells ? st.id::text
        AND s.cells->(st.id::text) ? (((EXTRACT(dow FROM now())::int + 6) % 7)::text)
        AND s.cells->(st.id::text)->(((EXTRACT(dow FROM now())::int + 6) % 7)::text)
            @> to_jsonb(a.employee_id::text)
    ),
    mejor_turno AS (
      SELECT DISTINCT ON (employee_id) *
      FROM candidatos
      ORDER BY employee_id, dist_seg ASC
    )
    SELECT clock_entry_id, employee_id, account_id, name, phone, entrada_at,
           start_time, end_time
    FROM mejor_turno mt
    WHERE
      (
        CASE
          WHEN mt.end_time > mt.start_time THEN
            now()::time > (mt.end_time + make_interval(mins => v_forgot_min))
            AND now()::time > mt.start_time
          ELSE
            now() > (mt.entrada_at::date + interval '1 day' + mt.end_time + make_interval(mins => v_forgot_min))
        END
      )
      AND NOT EXISTS (
        SELECT 1 FROM clockout_reminder_log crl WHERE crl.clock_entry_id = mt.clock_entry_id
      )
  LOOP
    INSERT INTO clockout_reminder_log (account_id, employee_id, clock_entry_id, to_phone, scheduled_end, status)
    VALUES (r.account_id, r.employee_id, r.clock_entry_id, r.phone,
            to_char(r.end_time, 'HH24:MI'),
            CASE WHEN r.phone IS NULL OR btrim(r.phone)='' THEN 'skipped' ELSE 'queued' END)
    ON CONFLICT (clock_entry_id) DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: enqueue_customer_notification(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_customer_notification(p_sale_id uuid, p_event text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s         record;
  v_base    text;
  v_phone   text;
  v_track   text;
  v_brand   text;
  v_enabled boolean;
BEGIN
  SELECT sl.id, sl.account_id, sl.brand_id, sl.location_id, sl.service_type, sl.source,
         sl.customer_name, sl.customer_phone, sl.public_token, sl.eta_delivery, sl.rider_name
    INTO s FROM public.sale sl WHERE sl.id = p_sale_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF s.service_type <> 'own_delivery' THEN RETURN; END IF;

  -- Interruptor por local
  SELECT coalesce(l.customer_notify_enabled, false) INTO v_enabled
    FROM public.locations l WHERE l.id = s.location_id;
  IF NOT coalesce(v_enabled, false) THEN RETURN; END IF;

  SELECT coalesce(a.track_base_url, 'https://app.folvy.app') INTO v_base
    FROM public.accounts a WHERE a.id = s.account_id;
  v_base := coalesce(v_base, 'https://app.folvy.app');

  v_phone := public.fv_e164_or_null(s.customer_phone);
  SELECT b.name INTO v_brand FROM public.brand b WHERE b.id = s.brand_id;

  IF s.public_token IS NOT NULL AND s.public_token <> '' THEN
     v_track := v_base || '/seguir/' || s.public_token;
  END IF;

  IF v_phone IS NULL OR v_track IS NULL THEN
     INSERT INTO public.customer_notification
       (sale_id, account_id, event, channel, to_phone, template, lang, payload, status, skip_reason)
     VALUES (s.id, s.account_id, p_event, 'whatsapp', v_phone, 'pedido_en_camino', 'es',
             jsonb_build_object('customer_name', s.customer_name, 'brand', v_brand,
                                'rider_name', s.rider_name, 'eta', s.eta_delivery, 'track_url', v_track),
             'skipped',
             CASE WHEN v_phone IS NULL THEN 'sin_telefono_valido' ELSE 'sin_public_token' END)
     ON CONFLICT (sale_id, event, channel) DO NOTHING;
     RETURN;
  END IF;

  INSERT INTO public.customer_notification
    (sale_id, account_id, event, channel, to_phone, template, lang, payload, status)
  VALUES (s.id, s.account_id, p_event, 'whatsapp', v_phone, 'pedido_en_camino', 'es',
          jsonb_build_object('customer_name', s.customer_name, 'brand', v_brand,
                             'rider_name', s.rider_name, 'eta', s.eta_delivery, 'track_url', v_track),
          'pending')
  ON CONFLICT (sale_id, event, channel) DO NOTHING;
END;
$$;


--
-- Name: enqueue_print_job(uuid, uuid, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_print_job(p_account_id uuid, p_location_id uuid, p_sale_id uuid, p_doc_type text, p_payload jsonb, p_source text DEFAULT 'manual'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count int := 0; v_printer record; v_i int;
begin
  if not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'enqueue_print_job: sin acceso a la cuenta %', p_account_id;
  end if;
  for v_printer in
    select id, copies from printer
    where account_id = p_account_id and location_id = p_location_id and is_active and p_doc_type = any(doc_types)
  loop
    for v_i in 1..greatest(1, coalesce(v_printer.copies, 1)) loop
      insert into print_job (account_id, location_id, printer_id, sale_id, doc_type, payload, source)
      values (p_account_id, p_location_id, v_printer.id, p_sale_id, p_doc_type, p_payload, p_source);
      v_count := v_count + 1;
    end loop;
  end loop;
  return v_count;
end;
$$;


--
-- Name: enqueue_test_print(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_test_print(p_printer_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_p printer; v_doc text; v_job uuid;
begin
  select * into v_p from printer where id = p_printer_id;
  if v_p.id is null then raise exception 'enqueue_test_print: impresora no encontrada'; end if;
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_p.account_id)) then
    raise exception 'enqueue_test_print: sin acceso a la cuenta';
  end if;
  v_doc := coalesce(v_p.doc_types[1], 'kitchen');
  insert into print_job (account_id, location_id, printer_id, sale_id, doc_type, payload, source, status)
  values (v_p.account_id, v_p.location_id, v_p.id, null, v_doc,
          public._build_test_ticket(v_p.name, v_p.config->>'ip', coalesce((v_p.config->>'port')::int, 9100)),
          'manual', 'pending')
  returning id into v_job;
  return v_job;
end;
$$;


--
-- Name: enqueue_test_print_by_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_test_print_by_token(p_device_token text, p_printer_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_device kds_device; v_p printer; v_doc text; v_job uuid;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'enqueue_test_print_by_token: token no válido'; end if;
  select * into v_p from printer
  where id = p_printer_id and account_id = v_device.account_id and location_id = v_device.location_id;
  if v_p.id is null then raise exception 'enqueue_test_print_by_token: impresora no encontrada en el local del dispositivo'; end if;
  v_doc := coalesce(v_p.doc_types[1], 'kitchen');
  insert into print_job (account_id, location_id, printer_id, sale_id, doc_type, payload, source, status)
  values (v_device.account_id, v_device.location_id, v_p.id, null, v_doc,
          public._build_test_ticket(v_p.name, v_p.config->>'ip', coalesce((v_p.config->>'port')::int, 9100)),
          'manual', 'pending')
  returning id into v_job;
  return v_job;
end;
$$;


--
-- Name: enqueue_training_notice(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_training_notice(p_assignment_id uuid, p_origin text DEFAULT 'auto'::text, p_requested_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc   uuid;
  v_emp   uuid;
  v_course uuid;
  v_phone text;
  v_name  text;
  v_hook  text;
  v_min   int;
  v_status text;
  v_min_txt text;
  v_notice_id uuid;
BEGIN
  SELECT ca.account_id, ca.employee_id, ca.course_id
    INTO v_acc, v_emp, v_course
  FROM course_assignment ca
  WHERE ca.id = p_assignment_id;

  IF v_emp IS NULL THEN
    RETURN NULL;  -- asignación por rol/puesto sin empleado concreto: no se avisa aquí
  END IF;

  -- Solo cursos publicados con gancho.
  SELECT c.whatsapp_hook, c.estimated_minutes
    INTO v_hook, v_min
  FROM course c
  WHERE c.id = v_course AND c.status = 'published';

  IF NOT FOUND THEN
    RETURN NULL;  -- borrador o inexistente: no se avisa
  END IF;

  SELECT e.name, e.phone INTO v_name, v_phone
  FROM employees e WHERE e.id = v_emp;

  -- Guardarraíl anti-repetición: ya avisado (o en cola) en las últimas 48h.
  IF EXISTS (
    SELECT 1 FROM training_notice tn
    WHERE tn.employee_id = v_emp AND tn.course_id = v_course
      AND tn.created_at > now() - interval '48 hours'
      AND tn.status IN ('queued','sent','delivered','read')
  ) THEN
    RETURN NULL;  -- ya hay un aviso vigente, no duplicar
  END IF;

  -- Determinar estado inicial y motivo de skip.
  v_min_txt := COALESCE(v_min::text, '10');
  IF v_hook IS NULL OR btrim(v_hook) = '' THEN
    v_status := 'skipped';
  ELSIF v_phone IS NULL OR btrim(v_phone) = '' THEN
    v_status := 'skipped';
  ELSE
    v_status := 'queued';
  END IF;

  INSERT INTO training_notice (
    account_id, employee_id, course_id, assignment_id,
    to_phone, payload, origin, status, skip_reason, requested_by
  ) VALUES (
    v_acc, v_emp, v_course, p_assignment_id,
    v_phone,
    jsonb_build_object('nombre', COALESCE(v_name,'Hola'), 'gancho', COALESCE(v_hook,''), 'minutos', v_min_txt),
    p_origin,
    v_status,
    CASE
      WHEN v_hook IS NULL OR btrim(v_hook) = '' THEN 'sin_gancho'
      WHEN v_phone IS NULL OR btrim(v_phone) = '' THEN 'sin_telefono'
      ELSE NULL
    END,
    p_requested_by
  )
  RETURNING id INTO v_notice_id;

  RETURN v_notice_id;
END;
$$;


--
-- Name: ensure_label_tokens(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_label_tokens(p_sale_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_loc uuid; v_n int := 0;
begin
  select account_id, location_id into v_acc, v_loc from sale where id = p_sale_id;
  if v_acc is null then return 0; end if;

  -- Barrido de huerfanos de ESTA venta: tokens que apuntan a una linea que ya
  -- no existe porque el adaptador reescribio el pedido. Los ESCANEADOS se
  -- quedan: son historia de una bolsa que alguien leyo.
  delete from public.label_token lt
   where lt.sale_id = p_sale_id
     and lt.line_id is not null
     and lt.scanned_at is null
     and not exists (select 1 from sale_line sl where sl.id = lt.line_id);

  with objetivo as (
    select p.id as line_id, greatest(1, round(p.quantity)::int) as uds
      from sale_line p
     where p.sale_id = p_sale_id and p.parent_sale_line_id is null
       and not exists (select 1 from sale_line h
                        where h.parent_sale_line_id = p.id and h.line_type = 'combo_item')
    union all
    -- Componente de combo: SU cantidad POR LA DEL PACK (G587, 21/09).
    select h.id,
           greatest(1, round(h.quantity)::int)
             * greatest(1, round(coalesce(pp.quantity, 1))::int)
      from sale_line h
      left join sale_line pp on pp.id = h.parent_sale_line_id
     where h.sale_id = p_sale_id and h.line_type = 'combo_item'
  ),
  unidades as (
    select o.line_id, g.n as unit_no from objetivo o, generate_series(1, o.uds) as g(n)
    union all
    select null::uuid, null::int
  ),
  puestos as (
    insert into public.label_token (token, account_id, location_id, sale_id, line_id, unit_no)
    select public._label_token_nuevo(), v_acc, v_loc, p_sale_id, u.line_id, u.unit_no
      from unidades u
    on conflict on constraint label_token_unidad_unica do nothing
    returning 1
  )
  select count(*)::int into v_n from puestos;
  return v_n;
exception when others then
  raise warning 'ensure_label_tokens: venta % sin tokens (%): %', p_sale_id, sqlstate, sqlerrm;
  return 0;
end;
$$;


--
-- Name: ensure_training_path_progress(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_training_path_progress(p_employee_id uuid, p_path_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row record;
  v_account_id uuid;
begin
  select l.account_id into v_account_id
  from public.employees e join public.locations l on l.id = e.location_id
  where e.id = p_employee_id;

  if auth.uid() is not null and v_account_id is not null and not (
    public.current_user_is_admin_or_manager_of(v_account_id) or public.current_user_is_admin()
  ) then
    raise exception 'ensure_training_path_progress: sin acceso';
  end if;

  for v_row in
    select * from (values ('dia_1', true), ('dias_30', false), ('dias_90', false)) as t(phase, is_first)
  loop
    insert into public.training_path_progress (employee_id, path_id, phase, state, released_at, due_at)
    values (
      p_employee_id, p_path_id, v_row.phase,
      case when v_row.is_first then 'liberada' else 'pendiente' end,
      case when v_row.is_first then now() else null end,
      null
    )
    on conflict (employee_id, path_id, phase) do nothing;
  end loop;
end;
$$;


--
-- Name: evaluate_campaign_rules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_campaign_rules() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r            campaign_rule%rowtype;
  v_now        timestamptz := now();
  v_fh         numeric; v_weeks int; v_drop numeric; v_days int;
  v_stock      numeric; v_stock_min numeric; v_sales_max numeric; v_sold numeric;
  v_cur        numeric; v_mean numeric;
  v_fires      boolean; v_reason jsonb;
  v_active_acct int; v_active_rule int;
  v_coupon_id  uuid; v_lit int := 0;
  v_sc         jsonb; v_kind text; v_val numeric;
begin
  for r in select * from campaign_rule where active loop
    -- ── Límites (freno de mano) ─────────────────────────────────────────────
    select count(*) into v_active_acct from coupon
      where account_id = r.account_id and origin = 'rule' and active and (ends_at is null or ends_at > v_now);
    if v_active_acct >= 3 then continue; end if;

    select count(*) into v_active_rule from coupon c
      join campaign_rule_firing f on f.coupon_id = c.id
      where f.rule_id = r.id and c.active and (c.ends_at is null or c.ends_at > v_now);
    if v_active_rule >= r.max_active then continue; end if;

    if r.last_fired_at is not null and v_now - r.last_fired_at < make_interval(mins => r.cooldown_minutes) then continue; end if;

    -- ── Disparadores ────────────────────────────────────────────────────────
    v_fires := false; v_reason := null;

    if r.trigger_type = 'hourly_valley' then
      v_fh := coalesce((r.condition->>'franjaHoras')::numeric, 2);
      v_weeks := coalesce((r.condition->>'weeks')::int, 4);
      v_drop := coalesce((r.condition->>'dropPct')::numeric, 30);
      select coalesce(sum(s.total), 0) into v_cur from sale s
      where s.account_id = r.account_id and s.source = 'folvy_shop' and coalesce(s.status,'') <> 'cancelled'
        and s.sold_at >= v_now - make_interval(hours => v_fh::int) and s.sold_at < v_now
        and (r.location_id is null or s.location_id = r.location_id)
        and (r.brand_id is null or exists (select 1 from sale_line sl join menu_item mi on mi.id = sl.menu_item_id where sl.sale_id = s.id and mi.brand_id = r.brand_id));
      select avg(wk.s) into v_mean from (
        select (select coalesce(sum(s.total), 0) from sale s
          where s.account_id = r.account_id and s.source = 'folvy_shop' and coalesce(s.status,'') <> 'cancelled'
            and s.sold_at >= v_now - make_interval(weeks => w) - make_interval(hours => v_fh::int) and s.sold_at < v_now - make_interval(weeks => w)
            and (r.location_id is null or s.location_id = r.location_id)
            and (r.brand_id is null or exists (select 1 from sale_line sl join menu_item mi on mi.id = sl.menu_item_id where sl.sale_id = s.id and mi.brand_id = r.brand_id))) as s
        from generate_series(1, v_weeks) w) wk;
      if v_mean is not null and v_mean > 0 and v_cur < v_mean * (1 - v_drop / 100.0) then
        v_fires := true;
        v_reason := jsonb_build_object('trigger','hourly_valley','franjaHoras',v_fh,'weeks',v_weeks,'dropPct',v_drop,'mean',round(v_mean,2),'current',round(v_cur,2));
      end if;

    elsif r.trigger_type = 'weak_brand' and r.brand_id is not null then
      v_days := coalesce((r.condition->>'days')::int, 7);
      v_weeks := coalesce((r.condition->>'weeks')::int, 4);
      v_drop := coalesce((r.condition->>'dropPct')::numeric, 25);
      select coalesce(sum(sl.line_total), 0) into v_cur
      from sale s join sale_line sl on sl.sale_id = s.id and coalesce(sl.line_type,'product') = 'product'
      join menu_item mi on mi.id = sl.menu_item_id
      where s.account_id = r.account_id and s.source = 'folvy_shop' and coalesce(s.status,'') <> 'cancelled'
        and mi.brand_id = r.brand_id and s.sold_at >= v_now - make_interval(days => v_days) and s.sold_at < v_now
        and (r.location_id is null or s.location_id = r.location_id);
      select avg(wk.s) into v_mean from (
        select (select coalesce(sum(sl.line_total), 0)
          from sale s join sale_line sl on sl.sale_id = s.id and coalesce(sl.line_type,'product') = 'product'
          join menu_item mi on mi.id = sl.menu_item_id
          where s.account_id = r.account_id and s.source = 'folvy_shop' and coalesce(s.status,'') <> 'cancelled'
            and mi.brand_id = r.brand_id
            and s.sold_at >= v_now - make_interval(days => (w + 1) * v_days) and s.sold_at < v_now - make_interval(days => w * v_days)
            and (r.location_id is null or s.location_id = r.location_id)) as s
        from generate_series(1, v_weeks) w) wk;
      if v_mean is not null and v_mean > 0 and v_cur < v_mean * (1 - v_drop / 100.0) then
        v_fires := true;
        v_reason := jsonb_build_object('trigger','weak_brand','days',v_days,'dropPct',v_drop,'mean',round(v_mean,2),'current',round(v_cur,2),'brandId',r.brand_id);
      end if;

    elsif r.trigger_type = 'stalled_dish' and r.menu_item_id is not null then
      v_days := coalesce((r.condition->>'days')::int, 7);
      v_stock_min := coalesce((r.condition->>'stockMin')::numeric, 0);
      v_sales_max := coalesce((r.condition->>'salesMax')::numeric, 0);
      select ri.current_stock into v_stock
      from menu_item mi join recipe_item ri on ri.id = mi.recipe_item_id
      where mi.id = r.menu_item_id and ri.is_stockable;
      select coalesce(sum(sl.quantity), 0) into v_sold
      from sale s join sale_line sl on sl.sale_id = s.id and coalesce(sl.line_type,'product') = 'product'
      where s.account_id = r.account_id and s.source = 'folvy_shop' and coalesce(s.status,'') <> 'cancelled'
        and sl.menu_item_id = r.menu_item_id and s.sold_at >= v_now - make_interval(days => v_days) and s.sold_at < v_now
        and (r.location_id is null or s.location_id = r.location_id);
      if v_stock is not null and v_stock >= v_stock_min and v_sold <= v_sales_max then
        v_fires := true;
        v_reason := jsonb_build_object('trigger','stalled_dish','days',v_days,'stockMin',v_stock_min,'salesMax',v_sales_max,'stock',round(v_stock,2),'soldUnits',round(v_sold,2),'menuItemId',r.menu_item_id);
      end if;
    end if;

    -- ── Encender la campaña (nace origin='rule') ────────────────────────────
    if v_fires then
      v_kind := coalesce(r.action_template->>'kind', 'item_percent');
      if v_kind not in ('item_percent', 'bogo') then v_kind := 'item_percent'; end if;
      v_val := coalesce((r.action_template->>'value')::numeric, 10);

      insert into coupon (account_id, name, code, discount_type, value, applies_to,
        first_order_only, auto_apply, max_per_customer, min_subtotal,
        starts_at, ends_at, active, kind, origin, weekdays, time_from, time_to, budget_max, channels, created_by)
      values (r.account_id, coalesce(nullif(btrim(r.action_template->>'name'),''), r.name), null, 'percent', v_val, 'subtotal',
        false, false, 1, null, v_now, v_now + make_interval(mins => r.duration_minutes), true, v_kind, 'rule',
        null, null, null, r.budget_max, '{shop}', r.created_by)
      returning id into v_coupon_id;

      -- Scope: de la plantilla; si no trae, se deriva del objetivo del disparador.
      if jsonb_typeof(r.action_template->'scope') = 'array' and jsonb_array_length(r.action_template->'scope') > 0 then
        for v_sc in select * from jsonb_array_elements(r.action_template->'scope') loop
          insert into campaign_scope (coupon_id, brand_id, menu_category_id, menu_item_id)
          values (v_coupon_id,
            case when v_sc->>'type' = 'brand'    then (v_sc->>'id')::uuid else null end,
            case when v_sc->>'type' = 'category' then (v_sc->>'id')::uuid else null end,
            case when v_sc->>'type' = 'item'     then (v_sc->>'id')::uuid else null end);
        end loop;
      elsif r.menu_item_id is not null then
        insert into campaign_scope (coupon_id, brand_id, menu_category_id, menu_item_id) values (v_coupon_id, null, null, r.menu_item_id);
      elsif r.brand_id is not null then
        insert into campaign_scope (coupon_id, brand_id, menu_category_id, menu_item_id) values (v_coupon_id, r.brand_id, null, null);
      end if;

      insert into campaign_rule_firing (rule_id, account_id, coupon_id, fired_at, reason)
      values (r.id, r.account_id, v_coupon_id, v_now, v_reason);

      update campaign_rule set last_fired_at = v_now, updated_at = v_now where id = r.id;
      v_lit := v_lit + 1;
    end if;
  end loop;

  return v_lit;
end;
$$;


--
-- Name: expire_unpaid_shop_orders(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_unpaid_shop_orders(p_minutes integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count int;
begin
  with caducados as (
    update sale
    set order_status = 'cancelled',
        status       = 'cancelled',
        cancelled_at = now()
    where source = 'folvy_shop'
      and order_status = 'new'
      and coalesce(payment_status, '') <> 'paid'
      and created_at < now() - make_interval(mins => p_minutes)
    returning id
  )
  select count(*) into v_count from caducados;
  return v_count;
end;
$$;


--
-- Name: explode_recipe_to_raws(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explode_recipe_to_raws(p_item_id uuid, p_multiplier numeric) RETURNS TABLE(raw_item_id uuid, qty_base numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item  recipe_item%ROWTYPE;
  v_line  recipe_line%ROWTYPE;
  v_qb    numeric;
  v_yield numeric := NULL;
BEGIN
  IF p_item_id IS NULL OR p_multiplier IS NULL THEN RETURN; END IF;
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN RETURN; END IF;

  -- Condicion de parada: hoja del arbol de consumo.
  --
  -- 22/09/2026: entra 'packaging'. NO estaba excluido por un filtro: un
  -- packaging no es raw ni tool ni receta stockable, asi que caia a la rama
  -- compuesta, no tenia lineas hijas y devolvia cero filas. Era invisible por
  -- construccion, y por eso 55 articulos de envase llevaban 30 dias con CERO
  -- movimientos de venta mientras los raw acumulaban 35.921.
  -- El coste ya lo cobraba (`computed_cost` suma todas las lineas); lo que no
  -- se movia era el STOCK. Decidido por Julio el 22/09.
  IF v_item.type IN ('raw', 'tool', 'packaging')
     OR (v_item.type = 'recipe' AND COALESCE(v_item.is_stockable, false)) THEN
    raw_item_id := p_item_id;
    qty_base    := p_multiplier;
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_item.type = 'recipe' OR v_item.batch_yield IS NOT NULL THEN
    v_yield := public._batch_yield_in_base(p_item_id);
  END IF;
  IF v_yield IS NULL OR v_yield <= 0 THEN v_yield := 1; END IF;

  FOR v_line IN
    SELECT * FROM recipe_line WHERE parent_item_id = p_item_id
    ORDER BY position ASC, created_at ASC
  LOOP
    v_qb := public._qty_in_base(v_line.child_item_id,
              COALESCE(v_line.quantity_gross, v_line.quantity_net), v_line.unit_id);
    IF v_qb IS NULL THEN CONTINUE; END IF;
    RETURN QUERY
      SELECT * FROM public.explode_recipe_to_raws(v_line.child_item_id,
                      (p_multiplier / v_yield) * v_qb);
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: export_gestoria_mensual(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_gestoria_mensual(p_account uuid, p_from date, p_to date) RETURNS TABLE(empleado text, dni text, local text, dias_trabajados integer, horas_trabajadas numeric, horas_nocturnas numeric, dias_vacaciones integer, dias_baja integer, dias_festivo_trabajado integer, horas_contratadas numeric, delta_horas numeric, incidencias text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Lleva el DNI y lo manda a la gestoría: solo el administrador de la cuenta.
  if not public.current_user_is_admin_of(p_account) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El resumen para la gestoría solo lo saca el administrador.';
  end if;
  return query
  select e.name, e.dni, l.name,
    t.dias_trabajados, t.horas_trabajadas, t.horas_nocturnas,
    t.dias_vacaciones, t.dias_baja, t.dias_festivo_trabajado,
    t.horas_contratadas, t.delta_horas,
    nullif(concat_ws(' · ',
      case when e.dni is null or e.dni = '' then 'SIN DNI' end,
      case when t.horas_pausa = 0 and t.horas_trabajadas > 0 then 'sin descansos registrados' end,
      case when abs(t.delta_horas) > 20 then 'desvío de '||round(t.delta_horas,1)||' h sobre contrato' end,
      case when exists (
        select 1 from public.registro_jornada_mensual(e.id, p_from, p_to) r
        where r.salida is not null
          and extract(hour from (r.salida at time zone 'Europe/Madrid')) between 4 and 10
      ) then 'posible fichaje de salida olvidado' end
    ), '')
  from public.employees e
  join public.locations l on l.id = e.location_id
  cross join lateral public.registro_jornada_totales(e.id, p_from, p_to) t
  where e.account_id = p_account and e.active
  order by e.name;
end $$;


--
-- Name: extras_availability_panel_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extras_availability_panel_by_token(p_device_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_device kds_device;
BEGIN
  v_device := public.kds_resolve_device(p_device_token);
  IF v_device.id IS NULL THEN
    RAISE EXCEPTION 'extras_availability_panel_by_token: token no válido';
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(x ORDER BY x->>'name')
    FROM (
      SELECT jsonb_build_object(
               'clave',           g.clave,
               'name',            min(g.name),
               'option_id',       min(g.option_id::text) FILTER (WHERE g.ref IS NOT NULL),
               'opciones',        count(*),
               'agotadas',        count(*) FILTER (WHERE g.agotada),
               'marcas',          count(DISTINCT g.brand_id),
               'sin_ref',         count(*) FILTER (WHERE g.ref IS NULL),
               'reason',          min(g.reason),
               'available_until', max(g.available_until),
               'set_at',          max(g.set_at)) AS x
        FROM (
          SELECT lower(btrim(mo.name)) AS clave, mo.name, mo.id AS option_id,
                 public._modifier_option_ref(mo.id) AS ref,
                 mg.brand_id,
                 (pa.id IS NOT NULL) AS agotada,
                 pa.reason, pa.available_until, pa.set_at
            FROM public.modifier_option mo
            JOIN public.modifier_group mg ON mg.id = mo.modifier_group_id
            LEFT JOIN public.product_availability pa
              ON pa.account_id = mo.account_id
             AND pa.target_kind = 'modifier_option'
             AND pa.external_id = public._modifier_option_ref(mo.id)
             AND pa.is_available = false
             AND (pa.location_id IS NULL OR pa.location_id = v_device.location_id)
           WHERE mo.account_id = v_device.account_id AND mo.is_active
        ) g
       GROUP BY g.clave
      HAVING count(*) FILTER (WHERE g.agotada) > 0
    ) s
  ), '[]'::jsonb);
END;
$$;


--
-- Name: f01_alta_marca(uuid, uuid, text, text, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_alta_marca(p_account uuid, p_org uuid, p_nombre_last text, p_nombre text, p_propia boolean, p_socio text, p_ensayo boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nombre text;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Dar de alta una marca es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  select coalesce(nullif(btrim(up.display_name), ''), u.email) into v_nombre
    from auth.users u left join public.user_profiles up on up.user_id = u.id and up.account_id = p_account
   where u.id = auth.uid() limit 1;
  return public._f01_alta_marca(p_account, p_org, p_nombre_last, p_nombre, p_propia, p_socio, coalesce(p_ensayo, false), auth.uid(), v_nombre);
end $$;


--
-- Name: f01_anadir_platos_nuevos(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_anadir_platos_nuevos(p_account uuid, p_brand uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l record; r jsonb; v_marca text;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Cambiar la carta de una marca es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  select * into v_l from public._f01b_last_de(p_account, p_brand);
  if v_l.org is null then raise exception 'Esa marca no está vinculada a Last.' using errcode = 'P0002'; end if;
  select name into v_marca from public.brand where id = p_brand and account_id = p_account;
  r := public._f01_sembrar_marca(p_account, p_brand, v_l.org, v_l.nombre, false, public._f01b_quien(p_account));
  return r || jsonb_build_object('frase',
    case when (r->>'creados')::int = 0 then 'No había platos nuevos que añadir a ' || v_marca || '.'
         else case when (r->>'creados')::int = 1 then 'Añadido 1 plato' else 'Añadidos ' || (r->>'creados') || ' platos' end
              || ' a la carta de ' || v_marca || '.'
              || case when (r->>'sin_receta')::int > 0 then ' Faltan ' || (r->>'sin_receta') || ' recetas.' else '' end end);
end $$;


--
-- Name: f01_aviso_visto(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_aviso_visto(p_account uuid, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n integer;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Este aviso es de quien administra la cuenta.' using errcode = '42501';
  end if;
  update public.f01_marca_reconocida set visto_at = now(), visto_por = public._f01b_quien(p_account)
   where id = p_id and account_id = p_account and visto_at is null;
  get diagnostics v_n = row_count;
  return jsonb_build_object('vistos', v_n);
end $$;


--
-- Name: f01_cambios_carta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_cambios_carta(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; m jsonb; c jsonb;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(p_account)) then
    return '[]'::jsonb;
  end if;
  for m in select x from jsonb_array_elements(public._f01_marcas_last(p_account)) x
            where x->>'estado' = 'vinculada' and x->>'brand_id' is not null loop
    c := public._f01b_cambios_marca(p_account, (m->>'brand_id')::uuid, (m->>'org')::uuid, m->>'nombre');
    if c is not null then v := v || c; end if;
  end loop;
  return v;
end $$;


--
-- Name: f01_carta_marca(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_carta_marca(p_account uuid, p_brand uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_corte  timestamptz;
  v        jsonb;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'La carta de una marca la ve quien administra la cuenta.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.brand b where b.id = p_brand and b.account_id = p_account) then
    raise exception 'Esa marca no es de esta cuenta.' using errcode = 'P0002';
  end if;
  select max(ic.closed_at) into v_corte from public.inventory_count ic
   where ic.account_id = p_account and ic.status in ('aprobado', 'en_revision');

  with canales as (
    select sc.id, sc.slug, sc.name from public.brand_channel bc
      join public.sales_channel sc on sc.id = bc.channel_id and sc.account_id = p_account and sc.is_active
     where bc.account_id = p_account and bc.brand_id = p_brand and bc.is_active and bc.archived_at is null
       and sc.slug in ('uber', 'glovo', 'justeat', 'deliveroo', 'shop')
  ),
  articulos as (
    select mi.id, btrim(mi.name) as nombre, mi.price, mi.recipe_item_id, mi.external_source, mi.created_at as creado,
           case when ri.type = 'raw' then 'almacen'
                when ri.id is not null and exists (select 1 from public.recipe_line rl
                                                    where rl.parent_item_id = ri.id and rl.account_id = p_account) then 'receta'
                else 'sin_receta' end as estado
      from public.menu_item mi
      left join public.recipe_item ri on ri.id = mi.recipe_item_id and ri.account_id = p_account
     where mi.account_id = p_account and mi.brand_id = p_brand and mi.archived_at is null
       and coalesce(mi.product_type, 'item') <> 'combo'
  ),
  -- Un plato por artículo: dos matrículas con el mismo artículo (un nombre por
  -- plataforma, o el mismo plato con otro código de marca) son un plato.
  platos as (
    select (array_agg(a.id order by (a.external_source = 'lastapp') desc, a.creado, a.nombre, a.id))[1] as id,
           (array_agg(a.nombre order by (a.external_source = 'lastapp') desc, a.creado, a.nombre, a.id))[1] as nombre,
           (array_agg(a.price order by (a.external_source = 'lastapp') desc, a.creado, a.nombre, a.id))[1] as price,
           (array_agg(a.external_source order by (a.external_source = 'lastapp') desc, a.creado, a.nombre, a.id))[1] as external_source,
           a.recipe_item_id, min(a.estado) as estado, array_agg(a.id) as ids
      from articulos a
     group by a.recipe_item_id, case when a.recipe_item_id is null then a.id end
  ),
  -- Lo vendido de cada plato sin receta: lo que se colocará al ponerla y lo
  -- que se queda debajo del último recuento (regla 6). Solo Last.
  ventas as (
    select p.id,
           count(distinct s.id) filter (where v_corte is null or s.sold_at > v_corte) as despues,
           count(distinct s.id) filter (where v_corte is not null and s.sold_at <= v_corte) as antes
      from platos p
      join public.sale_line sl on sl.menu_item_id = any (p.ids) and sl.account_id = p_account
      join public.sale s on s.id = sl.sale_id and s.account_id = p_account and s.source = 'lastapp'
     where p.estado = 'sin_receta'
     group by p.id
  )
  select jsonb_build_object(
    'marca', (select jsonb_build_object(
                'id', b.id, 'nombre', b.name, 'propia', b.ownership_type is distinct from 'licensed',
                'socio', (select a.owner_name from public.brand_licensing_agreement a
                           where a.brand_id = b.id and a.account_id = p_account and a.is_active limit 1),
                'locales', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'nombre', l.name) order by l.name), '[]'::jsonb)
                              from public.brand_location_availability x
                              join public.locations l on l.id = x.location_id and l.account_id = p_account
                             where x.account_id = p_account and x.brand_id = b.id and x.is_active),
                'canales', (select coalesce(jsonb_agg(jsonb_build_object('slug', c.slug, 'nombre', c.name) order by c.slug), '[]'::jsonb) from canales c))
              from public.brand b where b.id = p_brand),
    'platos', (select coalesce(jsonb_agg(jsonb_build_object(
                 'id', p.id, 'nombre', p.nombre, 'estado', p.estado, 'recipe_item_id', p.recipe_item_id,
                 'de_last', p.external_source = 'lastapp',
                 'precio', p.price,
                 'precios', (select coalesce(jsonb_object_agg(c.slug, coalesce(
                                (select o.price from public.menu_item_override o
                                  where o.account_id = p_account and o.menu_item_id = p.id and o.channel_id = c.id and o.location_id is null
                                  order by o.updated_at desc nulls last limit 1), p.price)), '{}'::jsonb) from canales c),
                 'ventas_esperando', coalesce(v.despues, 0),
                 'ventas_antes_del_recuento', coalesce(v.antes, 0))
               order by (p.estado = 'sin_receta') desc, (p.estado = 'almacen'), public._f01_normalizar(p.nombre), p.id), '[]'::jsonb)
               from platos p left join ventas v on v.id = p.id),
    'resumen', (select jsonb_build_object(
                  'platos', count(*) filter (where p.estado <> 'almacen'),
                  'con_receta', count(*) filter (where p.estado = 'receta'),
                  'sin_receta', count(*) filter (where p.estado = 'sin_receta'),
                  'almacen', count(*) filter (where p.estado = 'almacen'))
                from platos p),
    'ventas_esperando', (select count(distinct s.id) from public.sale s
                          join public.sale_line sl on sl.sale_id = s.id and sl.account_id = p_account
                          join platos p on sl.menu_item_id = any (p.ids) and p.estado = 'sin_receta'
                         where s.account_id = p_account and s.source = 'lastapp' and (v_corte is null or s.sold_at > v_corte)),
    'ventas_antes_del_recuento', (select count(distinct s.id) from public.sale s
                          join public.sale_line sl on sl.sale_id = s.id and sl.account_id = p_account
                          join platos p on sl.menu_item_id = any (p.ids) and p.estado = 'sin_receta'
                         where s.account_id = p_account and s.source = 'lastapp' and v_corte is not null and s.sold_at <= v_corte),
    'corte', v_corte,
    'por_colocar', (select count(*) from public.f01_receta_puesta q
                     where q.account_id = p_account and q.colocada_at is null
                       and q.recipe_item_id in (select p.recipe_item_id from platos p where p.recipe_item_id is not null)),
    -- Lo colocado en los últimos 7 días al poner una receta de esta marca: se dice.
    'colocadas', (select coalesce(jsonb_agg(q.resultado || jsonb_build_object('colocada_at', q.colocada_at) order by q.colocada_at desc), '[]'::jsonb)
                    from public.f01_receta_puesta q
                   where q.account_id = p_account and q.colocada_at > now() - interval '7 days'
                     and q.recipe_item_id in (select p.recipe_item_id from platos p where p.recipe_item_id is not null)))
  into v;
  return v;
end $$;


--
-- Name: f01_colocar_recetas(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_colocar_recetas(p_account uuid, p_receta uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Colocar lo vendido es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  -- La receta recién guardada desde «Subir mis recetas»: entra en la cola aquí
  -- mismo, sin esperar al disparador (si ya está, no se repite).
  if p_receta is not null then
    insert into public.f01_receta_puesta (account_id, recipe_item_id)
    select ri.account_id, ri.id from public.recipe_item ri
     where ri.id = p_receta and ri.account_id = p_account
       and exists (select 1 from public.recipe_line rl where rl.parent_item_id = ri.id and rl.account_id = p_account)
       and exists (select 1 from public.menu_item mi where mi.account_id = p_account and mi.recipe_item_id = ri.id and mi.external_source = 'lastapp')
    on conflict do nothing;
  end if;
  -- Pocas por llamada: la pantalla repite mientras «quedan».
  return public._f01c_colocar_recetas(p_account, 150);
end $$;


--
-- Name: f01_decidir_marca(uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_decidir_marca(p_account uuid, p_org uuid, p_nombre text, p_brand uuid, p_es boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_c     record;
  v_quien text;
  r       jsonb;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Decidir de quién es una marca de Last es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.brand b where b.id = p_brand and b.account_id = p_account and b.archived_at is null) then
    raise exception 'Esa marca no es de esta cuenta.' using errcode = 'P0002';
  end if;
  select * into v_c from public._f01c_candidatas(p_account) c where c.org = p_org and c.nombre = btrim(p_nombre);
  if v_c.org is null then
    raise exception '«%» ya no está pendiente en Last.', btrim(p_nombre) using errcode = 'P0002';
  end if;
  v_quien := public._f01b_quien(p_account);
  if p_es then
    r := public._f01c_unir(p_account, p_org, p_nombre, p_brand, 'confirmada', v_c.comparacion, auth.uid(), v_quien);
  else
    insert into public.f01_marca_reconocida (account_id, source, external_org_id, external_brand_name, brand_id, como,
                                             comparacion, locales, created_by, created_by_name, visto_at, visto_por)
    values (p_account, 'lastapp', p_org, btrim(p_nombre), p_brand, 'otra', coalesce(v_c.comparacion, '{}'::jsonb) - 'cartas',
            v_c.locales, auth.uid(), v_quien, now(), v_quien);
    r := jsonb_build_object('como', 'otra', 'nombre_last', btrim(p_nombre), 'brand_id', p_brand,
                            'marca', (select b.name from public.brand b where b.id = p_brand), 'locales', v_c.locales,
                            'org', p_org);
  end if;
  return r;
end $$;


--
-- Name: f01_destino_lectura(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_destino_lectura(p_account uuid, p_session uuid, p_menu_item uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_estado text;
  r        jsonb;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Subir las recetas de la carta es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  select s.status into v_estado from public.recipe_item_ai_session s where s.id = p_session and s.account_id = p_account;
  if v_estado is null then raise exception 'Esa lectura no es de esta cuenta.' using errcode = 'P0002'; end if;
  if v_estado = 'accepted' then raise exception 'Esa lectura ya está guardada.' using errcode = '22023'; end if;
  r := public._f01c_preparar(p_account, p_menu_item);
  update public.recipe_item_ai_session set recipe_item_id = (r->>'recipe_item_id')::uuid, updated_at = now()
   where id = p_session and account_id = p_account;
  return r;
end $$;


--
-- Name: f01_espejo_extras(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_espejo_extras(p_account uuid, p_org uuid, p_extras jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ahora timestamptz := now(); v_vistos integer; v_idos integer;
begin
  insert into public.external_catalog_modifier (account_id, source, external_org_id, group_id, slot_id, modifier_id, group_name,
                                                group_min, group_max, name, price_cents, product_ids, seen_in_catalog_at, missing_since)
  select p_account, 'lastapp', p_org, x->>'group_id', x->>'slot_id', x->>'modifier_id', x->>'group_name',
         nullif(x->>'group_min', '')::integer, nullif(x->>'group_max', '')::integer, x->>'name', nullif(x->>'price_cents', '')::integer,
         coalesce((select array_agg(v) from jsonb_array_elements_text(x->'product_ids') v), '{}'), v_ahora, null
    from jsonb_array_elements(coalesce(p_extras, '[]'::jsonb)) x
   where nullif(x->>'group_id', '') is not null and nullif(x->>'slot_id', '') is not null and nullif(x->>'modifier_id', '') is not null
  on conflict (account_id, source, external_org_id, group_id, slot_id) do update set
    modifier_id = excluded.modifier_id, group_name = excluded.group_name, group_min = excluded.group_min, group_max = excluded.group_max,
    name = excluded.name, price_cents = excluded.price_cents, product_ids = excluded.product_ids,
    seen_in_catalog_at = excluded.seen_in_catalog_at, missing_since = null;
  get diagnostics v_vistos = row_count;
  -- Solo si la foto trae algo: una lista vacía (Last no contesta bien) no da por idos a todos.
  if v_vistos > 0 then
    update public.external_catalog_modifier set missing_since = v_ahora
     where account_id = p_account and source = 'lastapp' and external_org_id = p_org
       and seen_in_catalog_at < v_ahora and missing_since is null;
    get diagnostics v_idos = row_count;
  end if;
  return jsonb_build_object('vistos', v_vistos, 'idos', coalesce(v_idos, 0));
end $$;


--
-- Name: f01_guardar_extras(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_guardar_extras(p_account uuid, p_brand uuid, p_extras jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_x       jsonb;
  v_e       record;
  v_grupo   uuid;
  v_opc     uuid;
  v_quien   text := public._f01b_quien(p_account);
  v_extras  integer := 0;
  v_copias  integer := 0;
  v_nuevas  integer := 0;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para decir qué descuentan los extras de esta cuenta.' using errcode = '42501';
  end if;
  if p_extras is null or jsonb_array_length(p_extras) = 0 then raise exception 'No hay extras que guardar.' using errcode = '22023'; end if;
  if not exists (select 1 from public.brand where id = p_brand and account_id = p_account) then
    raise exception 'Esa marca no es de esta cuenta.' using errcode = '42501';
  end if;

  for v_x in select * from jsonb_array_elements(p_extras) loop
    if nullif(v_x->>'cantidad', '') is null or (v_x->>'tipo') not in ('add_item', 'remove_item')
       or not exists (select 1 from public.recipe_item ri where ri.id = (v_x->>'ficha')::uuid and ri.account_id = p_account) then
      raise exception 'Al extra % le falta qué descuenta o cuánto. No se ha guardado nada.', v_x->>'modifier_id' using errcode = '22023';
    end if;
    -- La opción de Folvy; si no existe aún, se crea como la crearía la importación.
    if not exists (select 1 from public.modifier_option o where o.account_id = p_account and o.pos_modifier_id = v_x->>'modifier_id') then
      select e.* into v_e from public.external_catalog_modifier e
       where e.account_id = p_account and e.modifier_id = v_x->>'modifier_id' and e.missing_since is null
       order by e.seen_in_catalog_at desc limit 1;
      if v_e.id is null then raise exception 'El extra % no está en Last.', v_x->>'modifier_id' using errcode = 'P0002'; end if;
      select g.id into v_grupo from public.modifier_group g
       where g.account_id = p_account and g.external_source = 'lastapp' and g.external_id = v_e.group_id;
      if v_grupo is null then
        insert into public.modifier_group (account_id, brand_id, name, min_selections, max_selections, group_type, is_active, external_source, external_id)
        values (p_account, p_brand, coalesce(v_e.group_name, 'Extras'), coalesce(v_e.group_min, 0), coalesce(v_e.group_max, 1), 'extras', true, 'lastapp', v_e.group_id)
        returning id into v_grupo;
      end if;
      insert into public.modifier_option (account_id, modifier_group_id, name, price_impact, is_active, external_source, external_id, pos_modifier_id)
      values (p_account, v_grupo, coalesce(v_e.name, '(extra)'), coalesce(v_e.price_cents, 0) / 100.0, true, 'lastapp', v_e.slot_id, v_e.modifier_id)
      on conflict (account_id, external_source, external_id) where external_id is not null do nothing;
      v_nuevas := v_nuevas + 1;
    end if;
    v_extras := v_extras + 1;
    for v_opc in select o.id from public.modifier_option o where o.account_id = p_account and o.pos_modifier_id = v_x->>'modifier_id' loop
      insert into public.modifier_recipe_impact (account_id, modifier_option_id, impact_type, target_recipe_item_id, quantity, unit_id,
                                                 status, source, rationale, confirmed_by, confirmed_by_name, confirmed_at)
      values (p_account, v_opc, v_x->>'tipo', (v_x->>'ficha')::uuid, (v_x->>'cantidad')::numeric, nullif(v_x->>'unidad', '')::uuid,
              'confirmed', 'human', 'F01 · Cambios de Last', auth.uid(), v_quien, now())
      on conflict (modifier_option_id, target_recipe_item_id) where status = 'confirmed'
      do update set impact_type = excluded.impact_type, quantity = excluded.quantity, unit_id = excluded.unit_id,
                    rationale = excluded.rationale, confirmed_by = excluded.confirmed_by,
                    confirmed_by_name = excluded.confirmed_by_name, confirmed_at = excluded.confirmed_at, updated_at = now();
      v_copias := v_copias + 1;
    end loop;
  end loop;

  return jsonb_build_object('extras', v_extras, 'copias', v_copias, 'opciones_nuevas', v_nuevas,
    'frase', case when v_extras = 1 then 'Guardado 1 extra: ya dice qué descuenta del almacén.'
                  else 'Guardados ' || v_extras || ' extras: ya dicen qué descuentan del almacén.' end);
end $$;


--
-- Name: f01_marcas_last(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_marcas_last(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Dar de alta es cosa de quien administra la cuenta; los demás no ven el aviso.
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    return '[]'::jsonb;
  end if;
  return public._f01_marcas_last(p_account);
end $$;


--
-- Name: f01_marcas_por_revisar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_marcas_por_revisar(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    return jsonb_build_object('preguntas', '[]'::jsonb, 'reconocidas', '[]'::jsonb, 'sin_marca', '[]'::jsonb);
  end if;
  select jsonb_build_object(
    'preguntas', (select coalesce(jsonb_agg(jsonb_build_object(
                    'org', c.org, 'nombre', c.nombre, 'cuenta_last', c.cuenta_last, 'estado', c.estado,
                    'locales', c.locales, 'canales', c.canales, 'comparacion', c.comparacion,
                    'ventas', public._f01c_ventas_esperando(p_account, c.org, c.nombre))
                  order by c.nombre), '[]'::jsonb)
                    from public._f01c_candidatas(p_account) c
                   where (c.comparacion->>'parecida')::boolean or (c.comparacion->>'identica')::boolean),
    'reconocidas', (select coalesce(jsonb_agg(jsonb_build_object(
                      'id', r.id, 'como', r.como, 'nombre_last', r.external_brand_name, 'brand_id', r.brand_id,
                      'marca', b.name, 'locales', r.locales, 'ventas', r.ventas, 'comparacion', r.comparacion,
                      'created_at', r.created_at) order by r.created_at desc), '[]'::jsonb)
                      from public.f01_marca_reconocida r join public.brand b on b.id = r.brand_id
                     where r.account_id = p_account and r.visto_at is null and r.como in ('sola', 'codigo_nuevo')),
    -- Ninguna venta sin marca en silencio: todas las de Last sin marca, por su
    -- código, salvo los códigos que alguien ha decidido ignorar.
    'sin_marca', (select coalesce(jsonb_agg(jsonb_build_object(
                    'codigo', g.codigo, 'local', g.local, 'marca_last', g.marca_last, 'ventas', g.n,
                    'primera', g.primera, 'ultima', g.ultima) order by g.ultima desc), '[]'::jsonb)
                    from (select s.external_brand_text as codigo,
                                 (select l.name from public.external_location_map lm join public.locations l on l.id = lm.location_id
                                   where lm.account_id = p_account and lm.source = 'lastapp' and lm.external_location_id = s.external_location_text
                                   limit 1) as local,
                                 (select btrim(e.external_brand_name) from public.external_catalog_product e
                                   where e.account_id = p_account and e.source = 'lastapp' and e.external_brand_id = s.external_brand_text
                                   order by e.seen_in_catalog_at desc limit 1) as marca_last,
                                 count(*) as n, min(s.sold_at) as primera, max(s.sold_at) as ultima
                            from public.sale s
                           where s.account_id = p_account and s.source = 'lastapp' and s.brand_id is null
                             and not exists (select 1 from public.external_brand_map m
                                              where m.account_id = p_account and m.source = 'lastapp' and m.is_ignored
                                                and m.external_brand_id = s.external_brand_text
                                                and m.external_location_id = s.external_location_text)
                           group by s.external_brand_text, s.external_location_text) g),
    'corte', (select max(ic.closed_at) from public.inventory_count ic
               where ic.account_id = p_account and ic.status in ('aprobado', 'en_revision')))
  into v;
  return v;
end $$;


--
-- Name: f01_ocultar_marca(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_ocultar_marca(p_account uuid, p_org uuid, p_nombre_last text, p_ocultar boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_nombre text := btrim(coalesce(p_nombre_last, ''));
  v_quien  text;
  v_n      integer;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Ocultar una marca de Last es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  if v_nombre = '' or p_ocultar is null then raise exception 'Falta la marca de Last.' using errcode = '22023'; end if;
  if p_ocultar then
    if not exists (select 1 from public.external_catalog_product e where e.account_id = p_account and e.source = 'lastapp'
                    and e.external_org_id = p_org and btrim(e.external_brand_name) = v_nombre) then
      raise exception 'La marca «%» no está en las cartas de Last.', v_nombre using errcode = 'P0002';
    end if;
    select coalesce(nullif(btrim(up.display_name), ''), u.email) into v_quien
      from auth.users u left join public.user_profiles up on up.user_id = u.id and up.account_id = p_account
     where u.id = auth.uid() limit 1;
    insert into public.external_brand_oculta (account_id, source, external_org_id, external_brand_name, created_by, created_by_name)
    values (p_account, 'lastapp', p_org, v_nombre, auth.uid(), v_quien)
    on conflict (account_id, source, external_org_id, external_brand_name) do nothing;
    get diagnostics v_n = row_count;
    return jsonb_build_object('nombre', v_nombre, 'oculta', true, 'cambiada', v_n > 0,
      'frase', v_nombre || ' no volverá a avisar. Puedes recuperarla en Marcas › Ocultas.');
  end if;
  delete from public.external_brand_oculta
   where account_id = p_account and source = 'lastapp' and external_org_id = p_org and external_brand_name = v_nombre;
  get diagnostics v_n = row_count;
  return jsonb_build_object('nombre', v_nombre, 'oculta', false, 'cambiada', v_n > 0,
    'frase', v_nombre || ' vuelve a salir entre las marcas nuevas de Last.');
end $$;


--
-- Name: f01_pasada_last(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_pasada_last(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_a       record;
  v_vinc    jsonb;
  v_ventas  jsonb;
  v_salida  jsonb := '[]'::jsonb;
  v_solas   jsonb;
  v_recetas jsonb;
begin
  for v_a in select a.* from public.external_brand_alta a
               join public.brand b on b.id = a.brand_id and b.archived_at is null
              where a.account_id = p_account and a.source = 'lastapp'
  loop
    v_vinc := public._f01_vincular(p_account, v_a.brand_id, v_a.external_org_id, v_a.external_brand_name, false, 'F01 · pasada de Last');
    if (v_vinc->>'vinculos_nuevos')::integer > 0 then
      v_ventas := public._f01_recolocar(p_account, v_a.brand_id, v_a.external_org_id, v_a.external_brand_name);
      v_salida := v_salida || jsonb_build_object('marca', v_a.external_brand_name, 'vinculos_nuevos', v_vinc->'vinculos_nuevos', 'ventas', v_ventas);
      -- F01 · PR 3: la marca llega con otro código en algún local. Se ha
      -- vinculado sola; ahora, además, se avisa.
      insert into public.f01_marca_reconocida (account_id, source, external_org_id, external_brand_name, brand_id, como,
                                               ventas, locales, created_by_name)
      values (p_account, 'lastapp', v_a.external_org_id, v_a.external_brand_name, v_a.brand_id, 'codigo_nuevo',
              v_ventas || jsonb_build_object('vinculos_nuevos', v_vinc->'vinculos_nuevos'),
              coalesce(v_vinc->'locales', '[]'::jsonb), 'F01 · pasada de Last');
    end if;
  end loop;

  -- F01 · PR 3: las de carta idéntica, unidas solas; y lo vendido de las
  -- recetas recién puestas, colocado (regla 6).
  v_solas := public._f01c_reconocer_solas(p_account);
  v_recetas := public._f01c_colocar_recetas(p_account, 2000);

  return jsonb_build_object('marcas_con_vinculos_nuevos', v_salida, 'reconocidas_solas', v_solas, 'recetas', v_recetas);
end $$;


--
-- Name: f01_poner_precios_de_last(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_poner_precios_de_last(p_account uuid, p_brand uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_l     record;
  v_c     jsonb;
  v_p     jsonb;
  v_quien text := public._f01b_quien(p_account);
  v_n     integer := 0;
  v_marca text;
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Cambiar la carta de una marca es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  select * into v_l from public._f01b_last_de(p_account, p_brand);
  if v_l.org is null then raise exception 'Esa marca no está vinculada a Last.' using errcode = 'P0002'; end if;
  select name into v_marca from public.brand where id = p_brand and account_id = p_account;
  v_c := public._f01b_cambios_marca(p_account, p_brand, v_l.org, v_l.nombre);
  for v_p in select * from jsonb_array_elements(coalesce(v_c->'precios', '[]'::jsonb)) loop
    if v_p->>'canal' is null then
      update public.menu_item set price = (v_p->>'despues')::numeric, updated_at = now()
       where id = (v_p->>'menu_item_id')::uuid and account_id = p_account;
    else
      update public.menu_item_override o set price = (v_p->>'despues')::numeric, updated_at = now()
        from public.sales_channel sc
       where o.account_id = p_account and o.menu_item_id = (v_p->>'menu_item_id')::uuid and o.location_id is null
         and o.channel_id = sc.id and sc.account_id = p_account and sc.slug = v_p->>'canal';
      if not found then
        insert into public.menu_item_override (account_id, menu_item_id, channel_id, location_id, price)
        select p_account, (v_p->>'menu_item_id')::uuid, sc.id, null, (v_p->>'despues')::numeric
          from public.sales_channel sc where sc.account_id = p_account and sc.slug = v_p->>'canal';
      end if;
    end if;
    insert into public.external_catalog_change (account_id, brand_id, kind, menu_item_id, nombre, canal, antes, despues, created_by, created_by_name)
    values (p_account, p_brand, 'precio', (v_p->>'menu_item_id')::uuid, v_p->>'nombre', v_p->>'canal',
            (v_p->>'antes')::numeric, (v_p->>'despues')::numeric, auth.uid(), v_quien);
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('puestos', v_n,
    'frase', case when v_n = 0 then 'Los precios de ' || v_marca || ' ya eran los de Last.'
                  when v_n = 1 then 'Puesto 1 precio de Last en ' || v_marca || ', apuntado.'
                  else 'Puestos ' || v_n || ' precios de Last en ' || v_marca || ', apuntados.' end);
end $$;


--
-- Name: f01_preparar_receta(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f01_preparar_receta(p_account uuid, p_menu_item uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_account is null or not (public.current_user_is_admin() or public.current_user_is_admin_of(p_account)) then
    raise exception 'Hacer la receta de un plato de la carta es cosa de quien administra la cuenta.' using errcode = '42501';
  end if;
  return public._f01c_preparar(p_account, p_menu_item);
end $$;


--
-- Name: fail_image_job(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_image_job(p_post_id uuid, p_err text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update social_post
     set payload = jsonb_set(
                     jsonb_set(payload, '{image_level}', to_jsonb('N1-error'::text)),
                     '{image_error}', to_jsonb(left(coalesce(p_err,''), 400))),
         updated_at = now()
   where id = p_post_id;
end $$;


--
-- Name: fichar(uuid, text, text, uuid, double precision, double precision, timestamp with time zone, timestamp with time zone, text, boolean, integer, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fichar(p_employee_id uuid, p_type text, p_origen text, p_location_id uuid, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_hora_efectiva timestamp with time zone DEFAULT NULL::timestamp with time zone, p_hora_declarada timestamp with time zone DEFAULT NULL::timestamp with time zone, p_scheduled text DEFAULT NULL::text, p_rounding_applied boolean DEFAULT false, p_diff_minutes integer DEFAULT NULL::integer, p_address text DEFAULT NULL::text, p_pin text DEFAULT NULL::text, p_break_attested boolean DEFAULT NULL::boolean, p_break_attest_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_emp public.employees;
  v_loc public.locations;
  v_up public.user_profiles;
  v_pin text;
  v_dist integer;
  v_radio integer;
  v_dentro boolean;
  v_real timestamptz;
  v_efectiva timestamptz;
  v_row public.clock_entries;
  v_motivo text;
  v_rastro jsonb;
begin
  if p_type not in ('entrada', 'salida', 'pausa_inicio', 'pausa_fin') then
    raise exception 'TIPO_INVALIDO: %', p_type using errcode = '22023';
  end if;
  select * into v_emp from public.employees where id = p_employee_id;
  if v_emp.id is null then
    raise exception 'PERSONA_NO_EXISTE' using errcode = '22023', hint = 'Esa persona no existe.';
  end if;
  if not coalesce(v_emp.active, true) then
    raise exception 'PERSONA_DE_BAJA' using errcode = '42501', hint = 'Esa persona está de baja en la empresa: no puede fichar.';
  end if;

  -- Quién, según desde dónde.
  if p_origen = 'movil' then
    if not public.current_user_is_employee(p_employee_id, v_emp.account_id) then
      raise exception 'NO_AUTORIZADO: solo puedes fichar por ti'
        using errcode = '42501', hint = 'Solo puedes fichar por ti. Si hay que corregir el fichaje de otra persona, lo hace el encargado.';
    end if;
  elsif p_origen = 'tablet' then
    -- La sesión de la tablet es la del administrador o la del encargado del local.
    if not (public.current_user_is_admin_of(v_emp.account_id)
            or (public.current_user_is_admin_or_manager_of(v_emp.account_id)
                and p_location_id = any (public.current_user_location_ids()))) then
      raise exception 'NO_AUTORIZADO: esta tablet no puede fichar en este local'
        using errcode = '42501', hint = 'La tablet tiene que estar abierta con el administrador o con el encargado de este local.';
    end if;
    select k.pin into v_pin from public.employee_kiosk_pin k where k.employee_id = p_employee_id;
    if v_pin is null or v_pin = '' then
      raise exception 'SIN_PIN' using errcode = '42501', hint = 'Esta persona no tiene PIN de kiosko. Se lo pone el administrador en su ficha.';
    end if;
    if p_pin is distinct from v_pin then
      raise exception 'PIN_INCORRECTO' using errcode = '42501', hint = 'El PIN no es correcto.';
    end if;
  elsif p_origen = 'manual' then
    raise exception 'USA_UNA_CORRECCION'
      using errcode = '22023', hint = 'Una marca puesta a mano es una corrección con motivo: «Añadir marca» en Control horario o en la ficha de la persona.';
  else
    raise exception 'ORIGEN_INVALIDO: %', p_origen using errcode = '22023';
  end if;

  -- El local, de la misma cuenta.
  select * into v_loc from public.locations where id = p_location_id and account_id = v_emp.account_id;
  if v_loc.id is null then
    raise exception 'LOCAL_INVALIDO' using errcode = '22023', hint = 'Ese local no es de tu empresa.';
  end if;

  -- Lo que se guarda de la ubicación: la distancia y si cae dentro del radio.
  v_radio := coalesce(v_loc.clock_radius_m, 200);
  v_dist := public._distancia_metros(p_lat, p_lng, v_loc.lat, v_loc.lng);
  v_dentro := case when v_dist is null then null else v_dist <= v_radio end;
  if v_dentro = false and coalesce(v_loc.clock_geofence_mode, 'warn') = 'block' then
    raise exception 'FUERA_DE_ZONA'
      using errcode = '42501', hint = format('Estás a %s m de %s. Acércate para fichar.', v_dist, v_loc.name);
  end if;

  -- La hora. Con cobertura, la del servidor (la efectiva redondeada al turno,
  -- solo si cae a menos de 30 min). Sin cobertura, la que declara el móvil,
  -- que no puede ser futura ni de hace más de 72 h; la de llegada es created_at.
  if p_hora_declarada is not null then
    if p_hora_declarada > now() + interval '2 minutes' then
      raise exception 'HORA_DECLARADA_FUTURA' using errcode = '22023', hint = 'La hora del móvil va por delante de la del servidor. Revisa la hora del teléfono.';
    end if;
    if p_hora_declarada < now() - interval '72 hours' then
      raise exception 'HORA_DECLARADA_ANTIGUA'
        using errcode = '22023', hint = 'Ese fichaje se hizo hace más de 72 h sin conexión. Pide la corrección desde «Mis fichajes».';
    end if;
    v_real := p_hora_declarada;
    v_efectiva := case when p_hora_efectiva is not null and abs(extract(epoch from (p_hora_efectiva - p_hora_declarada))) <= 1800
                       then p_hora_efectiva else p_hora_declarada end;
  else
    v_real := now();
    v_efectiva := case when p_hora_efectiva is not null and abs(extract(epoch from (p_hora_efectiva - now()))) <= 1800
                       then p_hora_efectiva else now() end;
  end if;

  perform set_config('app.fichar', 'on', true);
  insert into public.clock_entries (
    employee_id, account_id, type, datetime, real_datetime, declared_at, lat, lng, distance_m, within_radius,
    address, scheduled, rounding_applied, diff_minutes, source, location_id_at_clock,
    break_attested, break_attest_reason)
  values (
    p_employee_id, v_emp.account_id, p_type, v_efectiva, v_real, p_hora_declarada, p_lat, p_lng, v_dist, v_dentro,
    nullif(p_address, ''), p_scheduled, coalesce(p_rounding_applied, false), p_diff_minutes, p_origen, v_loc.id,
    p_break_attested, p_break_attest_reason)
  returning * into v_row;
  perform set_config('app.fichar', '', true);

  -- Su rastro, completo. Lo normal es que el disparador del alta sea diferido y
  -- corra al cerrar la transacción: entonces ve este «create» y no escribe. Si
  -- alguien lo ha puesto inmediato (set constraints … immediate), ya ha escrito
  -- el suyo: se completa ese, nunca dos rastros para la misma alta.
  select * into v_up from public.user_profiles up
   where up.user_id = auth.uid() and up.account_id = v_emp.account_id and up.active
   order by (up.employee_id = p_employee_id) desc nulls last limit 1;
  v_motivo := case p_origen
    when 'movil' then 'Fichaje propio desde el móvil'
    else 'Fichaje en la tablet del local, con PIN' end
    || case when p_hora_declarada is not null
         then format(' · sin cobertura: hora del móvil %s, llegó %s',
                     to_char(p_hora_declarada at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'),
                     to_char(now() at time zone 'Europe/Madrid', 'DD/MM/YYYY HH24:MI'))
         else '' end;
  v_rastro := public._clock_snapshot(v_row) || jsonb_build_object(
    'via', p_origen,
    'para_otra_persona', not coalesce(v_up.employee_id = p_employee_id, false),
    'hora_servidor', now(),
    'hora_declarada', p_hora_declarada,
    'distancia_m', v_dist,
    'dentro_del_radio', v_dentro);
  update public.clock_entry_audit a
     set actor_user_id = auth.uid(), actor_employee_id = v_up.employee_id,
         actor_label = coalesce(v_up.role, case when auth.uid() is null then 'servidor' else 'sin perfil' end),
         reason = v_motivo, after = v_rastro
   where a.clock_entry_id = v_row.id and a.action = 'create';
  if not found then
    insert into public.clock_entry_audit (clock_entry_id, employee_id, account_id, action, actor_user_id, actor_employee_id, actor_label, reason, before, after)
    values (v_row.id, p_employee_id, v_emp.account_id, 'create', auth.uid(), v_up.employee_id,
            coalesce(v_up.role, case when auth.uid() is null then 'servidor' else 'sin perfil' end),
            v_motivo, null, v_rastro);
  end if;

  return jsonb_build_object(
    'id', v_row.id, 'type', v_row.type, 'datetime', v_row.datetime, 'real_datetime', v_row.real_datetime,
    'declarada', v_row.declared_at, 'llegada', v_row.created_at, 'origen', v_row.source,
    'distancia_m', v_dist, 'dentro_del_radio', v_dentro, 'radio_m', v_radio,
    'local', v_loc.name, 'local_con_coordenadas', v_loc.lat is not null and v_loc.lng is not null);
end $$;


--
-- Name: FUNCTION fichar(p_employee_id uuid, p_type text, p_origen text, p_location_id uuid, p_lat double precision, p_lng double precision, p_hora_efectiva timestamp with time zone, p_hora_declarada timestamp with time zone, p_scheduled text, p_rounding_applied boolean, p_diff_minutes integer, p_address text, p_pin text, p_break_attested boolean, p_break_attest_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fichar(p_employee_id uuid, p_type text, p_origen text, p_location_id uuid, p_lat double precision, p_lng double precision, p_hora_efectiva timestamp with time zone, p_hora_declarada timestamp with time zone, p_scheduled text, p_rounding_applied boolean, p_diff_minutes integer, p_address text, p_pin text, p_break_attested boolean, p_break_attest_reason text) IS 'L1a (27/10): fichar en el servidor. La hora la pone el servidor (o la declara el móvil sin cobertura, hasta 72 h); el móvil, solo por ti; la tablet, con PIN; guarda la distancia y si cae dentro del radio; deja su rastro «create».';


--
-- Name: fijar_direccion_entrega(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fijar_direccion_entrega(p_sale_id uuid, p_direccion text, p_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s       record;
  v_device  kds_device;
  v_texto   text := btrim(regexp_replace(coalesce(p_direccion, ''), '\s+', ' ', 'g'));
  v_por     text;
  v_carrier text;
  v_reason  text;
  v_mode    text;
begin
  select s.id, s.location_id, s.service_type, s.status, s.carrier_order_id, s.rider_name, s.rider_phone
    into v_s from public.sale s where s.id = p_sale_id;
  if v_s.id is null then raise exception 'fijar_direccion_entrega: el pedido no existe'; end if;

  perform public.kds_authorize(v_s.location_id, p_token);

  if v_s.service_type is distinct from 'own_delivery' then
    raise exception 'Este pedido no lo repartimos nosotros: no hace falta dirección.';
  end if;
  if v_s.status is distinct from 'open' then
    raise exception 'Este pedido ya está cerrado.';
  end if;
  if length(v_texto) < 6 then
    raise exception 'Falta la dirección: pega la calle, el número, el piso y el portal.';
  end if;
  if length(v_texto) > 300 then
    raise exception 'La dirección es demasiado larga (más de 300 letras).';
  end if;

  if p_token is not null then
    v_device := public.kds_resolve_device(p_token);
    v_por := 'tablet · ' || coalesce(v_device.label, 'sin nombre');
  else
    -- Quién: el nombre, para que la oficina lo lea («Completada por Ana»).
    v_por := coalesce(nullif(btrim(public.conta_nombre_actor()), ''), auth.uid()::text, 'sesión');
  end if;

  update public.sale
     set delivery_address_fixed    = v_texto,
         delivery_address_fixed_at = now(),
         delivery_address_fixed_by = v_por,
         updated_at                = now()
   where id = p_sale_id;

  select r.carrier, r.reason into v_carrier, v_reason from public.resolve_dispatch(p_sale_id) r;
  select coalesce(l.dispatch_mode, 'auto') into v_mode from public.locations l where l.id = v_s.location_id;

  return jsonb_build_object(
    'ok',            true,
    'sale_id',       p_sale_id,
    'direccion',     v_texto,
    'carrier',       v_carrier,
    'reason',        v_reason,
    'dispatch_mode', v_mode,
    -- Quién la ha escrito: la pantalla lo dice («Dirección completada por …»).
    'por',           v_por,
    -- Catcher ya tiene el pedido (salió por el punto del mapa): no se puede
    -- reenviar sin crear otro (no hay cambio ni anulación en su API). La
    -- pantalla lo dice y da el contacto del repartidor.
    'ya_en_catcher', v_s.carrier_order_id is not null,
    'rider_name',    v_s.rider_name,
    'rider_phone',   v_s.rider_phone);
end;
$$;


--
-- Name: FUNCTION fijar_direccion_entrega(p_sale_id uuid, p_direccion text, p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fijar_direccion_entrega(p_sale_id uuid, p_direccion text, p_token text) IS 'R03: la cocina pega la dirección que no llegó. Guarda en delivery_address_fixed (lo de la plataforma no se toca) y devuelve lo que dice resolve_dispatch y si el pedido ya estaba en Catcher. Con token, solo pedidos del local del dispositivo (kds_authorize).';


--
-- Name: fill_line_discounts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_line_discounts(p_sale_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale  sale%ROWTYPE;
  v_count integer := 0;
  v_prod  jsonb;
  v_full  numeric;
  v_final numeric;
  v_disc  numeric;
  v_ext   text;
BEGIN
  SELECT * INTO v_sale FROM sale WHERE id = p_sale_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- ── LAST: raw_products[]; price en céntimos; fullPrice vs finalPrice ──
  IF v_sale.source = 'lastapp' AND v_sale.raw_products IS NOT NULL THEN
    FOR v_prod IN SELECT * FROM jsonb_array_elements(v_sale.raw_products::jsonb)
    LOOP
      v_ext   := nullif(v_prod->>'organizationProductId','');
      v_full  := nullif(v_prod->>'fullPrice','')::numeric;
      v_final := nullif(v_prod->>'finalPrice','')::numeric;
      v_disc  := nullif(v_prod->>'discountAmount','')::numeric;
      IF v_ext IS NULL OR v_full IS NULL OR v_final IS NULL THEN CONTINUE; END IF;
      IF v_full <= v_final THEN CONTINUE; END IF;     -- sin descuento real
      UPDATE sale_line sl
         SET original_unit_price = v_full / 100.0,
             unit_price = v_final / 100.0,
             line_total = (v_final / 100.0) * sl.quantity,
             discount_label = 'Descuento ' || replace(trim(to_char(
                COALESCE(v_disc, v_full - v_final) / 100.0, 'FM999990.00')), '.', ',') || ' EUR'
       WHERE sl.sale_id = p_sale_id
         AND sl.external_product_id = v_ext
         AND sl.line_type = 'product'
         AND sl.parent_sale_line_id IS NULL;
      v_count := v_count + 1;
    END LOOP;
  END IF;

  -- ── HUBRISE: raw_tab.items[]; price_offset/subtotal indica descuento ──
  -- HubRise pone el precio ya con su valor; el descuento de línea viene como
  -- 'discounts' o diferencia con 'subtotal'. Si existe item->>'discount', se usa.
  IF v_sale.source = 'hubrise' AND v_sale.raw_tab IS NOT NULL THEN
    FOR v_prod IN SELECT * FROM jsonb_array_elements(COALESCE(v_sale.raw_tab::jsonb->'items','[]'::jsonb))
    LOOP
      v_ext   := nullif(v_prod->>'sku_ref','');
      -- HubRise: price = unitario; si trae 'price_without_discount' o 'full_price', tachar.
      v_full  := public.hubrise_money(coalesce(v_prod->>'full_price', v_prod->>'price_without_discount'));
      v_final := public.hubrise_money(v_prod->>'price');
      IF v_ext IS NULL OR v_full IS NULL OR v_final IS NULL THEN CONTINUE; END IF;
      IF v_full <= v_final THEN CONTINUE; END IF;
      UPDATE sale_line sl
         SET original_unit_price = v_full,
             discount_label = 'Descuento ' || replace(trim(to_char(v_full - v_final, 'FM999990.00')), '.', ',') || ' EUR'
       WHERE sl.sale_id = p_sale_id
         AND sl.external_product_id = v_ext
         AND sl.line_type = 'product'
         AND sl.parent_sale_line_id IS NULL;
      v_count := v_count + 1;
    END LOOP;
  END IF;

  RETURN v_count;
END;
$$;


--
-- Name: finish_image_job(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_image_job(p_post_id uuid, p_public_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update social_post
     set payload = jsonb_set(
                     jsonb_set(payload, '{image_url}',   to_jsonb(p_public_url)),
                     '{image_level}', to_jsonb('N1'::text)),
         updated_at = now()
   where id = p_post_id;
end $$;


--
-- Name: firma_registro_mes_pedir(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.firma_registro_mes_pedir(p_account_id uuid, p_pedir boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_personas integer;
begin
  if p_account_id is null or p_pedir is null then
    raise exception 'DATOS_INCOMPLETOS' using errcode = '22023', hint = 'Falta la empresa o si se enciende o se apaga.';
  end if;
  if not public.current_user_is_admin_of(p_account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'Solo el administrador de la empresa puede encender o apagar la firma del registro.';
  end if;
  update public.accounts set firma_registro_mes = p_pedir where id = p_account_id;
  if not found then
    raise exception 'CUENTA_NO_EXISTE' using errcode = '22023', hint = 'Esa empresa no existe.';
  end if;
  select count(*) into v_personas from public.employees where account_id = p_account_id and active;
  return jsonb_build_object('pedir', p_pedir, 'personas', v_personas);
end $$;


--
-- Name: FUNCTION firma_registro_mes_pedir(p_account_id uuid, p_pedir boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.firma_registro_mes_pedir(p_account_id uuid, p_pedir boolean) IS 'L1a-H (29/10/2026). Enciende o apaga «Pedir a cada persona que firme su registro del mes» de una cuenta. Solo su administrador. Devuelve {pedir, personas}: las personas activas de la cuenta.';


--
-- Name: firmar_registro_mes(uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.firmar_registro_mes(p_employee_id uuid, p_mes date, p_resumen jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acct uuid; v_mes date := date_trunc('month', p_mes)::date; f public.registro_jornada_firma;
begin
  v_acct := public._account_of_employee(p_employee_id);
  if v_acct is null or not public.current_user_is_employee(p_employee_id, v_acct) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El registro de cada mes lo firma la propia persona, desde su portal.';
  end if;
  if v_mes >= public._mes_madrid(now()) then
    raise exception 'MES_SIN_ACABAR' using errcode = '22023', hint = 'Un mes se firma cuando ha acabado.';
  end if;
  if exists (select 1 from public.registro_jornada_firma where employee_id = p_employee_id and mes = v_mes and invalidada_at is null) then
    raise exception 'YA_FIRMADO' using errcode = '22023', hint = 'Ese mes ya está firmado.';
  end if;
  insert into public.registro_jornada_firma(account_id, employee_id, mes, firmado_por, huella, resumen)
  values (v_acct, p_employee_id, v_mes, auth.uid(), public._huella_registro_mes(p_employee_id, v_mes), coalesce(p_resumen, '{}'::jsonb))
  returning * into f;
  return jsonb_build_object('id', f.id, 'mes', f.mes, 'firmado_at', f.firmado_at, 'huella', f.huella);
end $$;


--
-- Name: fiscal_for_preview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_for_preview(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_q jsonb; v_t public.ticket_invoice; v_code text; v_loc uuid; v_raw jsonb; v_qr text;
begin
  select account_id, location_id, public.safe_jsonb(raw_tab) into v_acc, v_loc, v_raw from public.sale where id = p_sale_id;
  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Ese pedido no está.' using errcode = 'P0002'; end if;
  v_q := public._ticket_quien_factura(v_acc, p_sale_id);
  if v_q->>'tipo' = 'cedida' then
    return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', v_q->>'address',
      'ticketNumber', v_q->>'number', 'issuerKind', 'cedida', 'sinFactura', (v_q->>'sinFactura')::boolean, 'serie', false, 'pendiente', false,
      'verifactu', null, 'verifactuQr', null);
  end if;
  select * into v_t from public.ticket_invoice where account_id = v_acc and sale_id = p_sale_id and kind = 'F';
  select code into v_code from public.location_invoice_code where location_id = v_loc and account_id = v_acc;
  if v_t.verifactu_entorno = 'real' and v_t.importe_total is not null then
    v_qr := public.verifactu_url_qr('real', (select regexp_replace(upper(coalesce(c.tax_id, '')), '^ES', '') from public.company c where c.id = v_t.company_id),
                                    v_t.number_text, (v_t.issued_at at time zone 'Europe/Madrid')::date, v_t.importe_total);
  end if;
  return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', null,
    'ticketNumber', coalesce(v_t.number_text, case when v_code is null then coalesce(v_raw->'bills'->0->>'number', v_raw->>'number') end),
    'issuerKind', 'propia', 'sinFactura', false, 'serie', v_t.id is not null,
    -- El local numera, pero este pedido aún no se ha impreso: el número llega al imprimir.
    'pendiente', v_t.id is null and v_code is not null,
    'verifactu', v_t.verifactu_entorno, 'verifactuEstado', v_t.verifactu_estado, 'verifactuQr', v_qr);
end $$;


--
-- Name: fiscal_for_print(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_for_print(p_device_token text, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device; v_acc uuid; v_q jsonb; v_loc uuid; v_brand uuid; v_raw jsonb; v_code text; v_t public.ticket_invoice; v_num text;
  v_modo text; v_qr text; v_nif text;
begin
  -- Igual que antes: sin un token bueno no hay tique (y la tablet lo sabe).
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'fiscal_for_print: token no válido'; end if;
  v_acc := v_device.account_id;

  begin
    select location_id, brand_id, public.safe_jsonb(raw_tab) into v_loc, v_brand, v_raw from public.sale where id = p_sale_id and account_id = v_acc;
    v_q := public._ticket_quien_factura(v_acc, p_sale_id);
  exception when others then
    v_q := null;
    perform public._ticket_aviso('tique_sin_quien_factura', 'Un tique ha salido sin saber quién factura',
      'No se ha podido leer quién factura el pedido al imprimir su tique (' || sqlerrm || '). Ha salido como antes. Míralo en Ajustes › Facturas de los pedidos.',
      'tique_sin_quien_factura:' || v_acc::text, interval '1 hour', v_acc, v_loc, v_brand, 'alto');
  end;
  if v_q is null then
    begin return public._ticket_fiscal_de_antes(v_acc, p_sale_id);
    exception when others then return jsonb_build_object('legalName', null, 'taxId', null, 'address', null, 'ticketNumber', null);
    end;
  end if;

  -- Las cedidas no entran en nada de lo nuestro (ni serie, ni Verifactu): la factura es del socio.
  if v_q->>'tipo' = 'cedida' then
    if (v_q->>'sinFactura')::boolean then
      -- Nunca se inventa un número: el tique va sin la línea, y se avisa.
      perform public._ticket_aviso('tique_cedida_sin_factura',
        'Un pedido de una marca cedida llegó sin la factura de Last',
        'El tique de la bolsa ha salido sin «Factura Simplificada»: el pedido de una marca cedida no trae la factura del socio (raw_tab.bills). Míralo en Last.',
        'tique_cedida_sin_factura:' || p_sale_id::text, interval '7 days', v_acc, v_loc, v_brand, 'aviso');
    end if;
    return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', v_q->>'address',
      'ticketNumber', v_q->>'number', 'issuerKind', 'cedida', 'sinFactura', (v_q->>'sinFactura')::boolean, 'serie', false,
      'verifactu', null, 'verifactuQr', null);
  end if;

  -- Propia: el número de la serie del local, si el local tiene código.
  begin
    select code into v_code from public.location_invoice_code where location_id = v_loc and account_id = v_acc;
    if v_code is not null then
      v_t := public._ticket_invoice_number(v_acc, v_loc, p_sale_id, v_code, v_q->>'legalName', v_q->>'taxId');
      v_num := v_t.number_text;
    end if;
  exception when others then
    -- La impresión no se cae por esto: el tique sale como antes y se avisa.
    v_num := null; v_t := null;
    perform public._ticket_aviso('tique_sin_numero',
      'Un tique ha salido sin el número de su serie',
      'No se ha podido dar el número de la serie del local al imprimir el tique (' || sqlerrm || '). El tique ha salido con el número del pedido. Míralo en Ajustes › Facturas de los pedidos.',
      'tique_sin_numero:' || coalesce(v_loc::text, v_acc::text), interval '1 hour', v_acc, v_loc, v_brand, 'alto');
  end;

  -- Verifactu (V04 · PR 2). Nada de esto para la impresión: ni espera a
  -- Hacienda (el envío lo hace la cola después) ni falla si el motor falla.
  if v_t.id is not null then
    begin
      -- Recién numerado en esta impresión (el número se da con now(), la hora
      -- de esta transacción): se apuntan su importe y el entorno de su empresa.
      if v_t.issued_at = now() and v_t.importe_total is null then
        select e.modo into v_modo from public.verifactu_empresa e where e.company_id = v_t.company_id;
        update public.ticket_invoice
           set importe_total = (select round(total, 2) from public.sale where id = p_sale_id and account_id = v_acc),
               verifactu_entorno = case when v_modo in ('pruebas', 'real') then v_modo end
         where id = v_t.id returning * into v_t;
        if v_t.verifactu_entorno is not null then
          begin
            perform public._ticket_verifactu_alta(v_t.id);
          exception when others then
            update public.ticket_invoice set verifactu_estado = 'pendiente', verifactu_error = left(sqlerrm, 500), verifactu_intentos = 1 where id = v_t.id;
            perform public._ticket_aviso('tique_verifactu_pendiente', 'Un tique ha salido sin su registro de Verifactu',
              'El tique ' || v_t.number_text || ' se ha impreso, pero su registro de Verifactu ha quedado pendiente (' || left(sqlerrm, 300) || '). Se reintenta cada 5 minutos.',
              'tique_verifactu_pendiente:' || v_acc::text, interval '1 hour', v_acc, v_loc, v_brand, 'alto');
          end;
        end if;
        select * into v_t from public.ticket_invoice where id = v_t.id;
      end if;
      -- El QR, solo en real, con los datos del propio tique.
      if v_t.verifactu_entorno = 'real' and v_t.importe_total is not null then
        select regexp_replace(upper(coalesce(c.tax_id, '')), '^ES', '') into v_nif from public.company c where c.id = v_t.company_id;
        v_qr := public.verifactu_url_qr('real', v_nif, v_t.number_text, (v_t.issued_at at time zone 'Europe/Madrid')::date, v_t.importe_total);
      end if;
    exception when others then
      v_qr := null;
      perform public._ticket_aviso('tique_verifactu_pendiente', 'Un tique ha salido sin su registro de Verifactu',
        'Al imprimir el tique ' || coalesce(v_t.number_text, '') || ' ha fallado lo de Verifactu (' || left(sqlerrm, 300) || '). El tique ha salido.',
        'tique_verifactu_pendiente:' || v_acc::text, interval '1 hour', v_acc, v_loc, v_brand, 'alto');
    end;
  end if;

  if v_num is null then
    -- Como antes: el número de la plataforma o del TPV, si lo trae (si no, la tablet pone el del pedido).
    v_num := coalesce(v_raw->'bills'->0->>'number', v_raw->>'number');
  end if;
  return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', null,
    'ticketNumber', v_num, 'issuerKind', 'propia', 'sinFactura', false, 'serie', v_t.id is not null,
    'verifactu', v_t.verifactu_entorno, 'verifactuQr', v_qr);
end;
$$;


--
-- Name: fiscal_year_corte_cambiable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_year_corte_cambiable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (new.origin, new.origin_program, new.imported_until) is distinct from (old.origin, old.origin_program, old.imported_until)
     and exists (select 1 from public.journal_entry e where e.fiscal_year_id = old.id and e.source_type = 'migrated') then
    raise exception 'El ejercicio % ya tiene asientos traídos: la fecha de corte no se cambia (se deshace lo traído y se vuelve a traer).', old.code
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: folvy_code_prefix(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.folvy_code_prefix(p_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_type
    WHEN 'raw'    THEN 'RAW'
    WHEN 'recipe' THEN 'REC'
    WHEN 'dish'   THEN 'DSH'
    WHEN 'tool'   THEN 'TOO'
    ELSE 'ART' END;
$$;


--
-- Name: folvy_map_measure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.folvy_map_measure() RETURNS TABLE(measure_table text, filas bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT n.measure_table, COALESCE(s.n_live_tup, 0)::bigint
  FROM (SELECT DISTINCT measure_table FROM folvy_map_node
        WHERE measure_table IS NOT NULL) n
  LEFT JOIN pg_stat_user_tables s
    ON s.schemaname='public' AND s.relname = n.measure_table;
$$;


