  RETURN NEW;
END;
$$;


--
-- Name: food_cost_dashboard(uuid, timestamp with time zone, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.food_cost_dashboard(p_account uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location uuid DEFAULT NULL::uuid, p_brand uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  with l as (
    select s.brand_id                                  as brand_id,
           b.name                                      as brand,
           b.ownership_type                            as own_type,
           mi.name                                     as dish,
           coalesce(sl.line_type, 'product')           as lt,
           coalesce(sl.parent_sale_line_id, sl.id)     as unidad,
           sl.quantity, sl.unit_price,
           ri.computed_cost, coalesce(ri.packaging_cost,0) as packaging,
           -- B44 (03/09/2026): el coste CONGELADO EN LA VENTA. Ya lleva la
           -- cantidad multiplicada y los modificadores aplicados; en el combo
           -- vive en la linea PADRE. No se vuelve a multiplicar por quantity.
           sl.computed_cost as line_cost,
           (sl.computed_cost is not null)              as costed
    from public.sale_line sl
    join public.sale s on s.id = sl.sale_id
    left join public.menu_item mi on mi.id = sl.menu_item_id
    left join public.recipe_item ri on ri.id = mi.recipe_item_id
    left join public.brand b on b.id = s.brand_id
    where sl.account_id = p_account
      and coalesce(s.status,'') <> 'cancelled'
      and (p_from is null or s.sold_at >= p_from)
      and (p_to  is null or s.sold_at <  p_to)
      and (p_location is null or s.location_id = p_location)
      and (p_brand is null or s.brand_id = p_brand)
  ),
  u as (
    select unidad,
           max(brand) as brand,
           -- Todas las lineas de una unidad son de la MISMA venta, y por tanto de
           -- la misma marca: cualquier agregado da el mismo valor. Va por texto
           -- porque en Postgres no existe max(uuid).
           max(brand_id::text)::uuid as brand_id,
           max(own_type)                                       as own_type,
           sum(quantity * unit_price)                          as eur,
           sum(line_cost) filter (where costed)                as coste,
           -- Envase de las fichas de HOY sobre lo vendido. Ver el punto 3 de la
           -- cabecera: es una estimacion del orden de magnitud, NO un trozo del
           -- coste congelado. No se resta del food_cost_pct.
           sum(packaging * quantity)                           as envase,
           bool_or(costed)                                     as costeada
    from l
    group by unidad
  )
  select jsonb_build_object(
    'salud', jsonb_build_object(
      'unidades',           (select count(*) from u),
      'unidades_costeadas', (select count(*) filter (where costeada) from u),
      'cobertura_pct',      (select round(100.0*count(*) filter (where costeada)
                                          /nullif(count(*),0),1) from u),
      'cobertura_dinero_pct', (select round(100.0*sum(eur) filter (where costeada)
                                            /nullif(sum(eur),0),1) from u),
      'ingreso_total',      (select round(sum(eur)) from u)
    ),
    'total', (select jsonb_build_object(
        'ingreso',       round(sum(eur) filter (where costeada)),
        'food_cost',     round(sum(coste)),
        'food_cost_pct', round(100.0*sum(coste)/nullif(sum(eur) filter (where costeada),0),1),
        'envase_eur',    round(sum(envase) filter (where costeada), 2),
        'envase_pts',    round(100.0*sum(envase) filter (where costeada)
                                    /nullif(sum(eur) filter (where costeada),0),1)
      ) from u),
    'by_ownership', (
      -- «Tuyas» (own) frente a «de terceros» (licensed), y el cubo que existe y
      -- que nadie espera: las ventas sin marca. Se devuelven los tres.
      select coalesce(jsonb_agg(o order by o.vendido desc),'[]'::jsonb) from (
        select coalesce(own_type,'sin_marca') as tipo,
          count(*)::int                             as unidades,
          round(sum(eur))                           as vendido,
          round(sum(eur) filter (where costeada))   as vendido_con_coste,
          round(sum(coste))                         as food_cost,
          round(100.0*sum(coste)/nullif(sum(eur) filter (where costeada),0),1) as food_cost_pct,
          round(100.0*count(*) filter (where costeada)/nullif(count(*),0),1)   as cobertura_pct
        from u
        group by coalesce(own_type,'sin_marca')
      ) o
    ),
    'by_brand', (
      select coalesce(jsonb_agg(x order by x.ingreso desc),'[]'::jsonb) from (
        select max(brand) as brand,
          brand_id,
          max(own_type)                             as ownership_type,
          round(sum(eur) filter (where costeada))   as ingreso,
          round(sum(coste))                         as food_cost,
          round(100.0*sum(coste)/nullif(sum(eur) filter (where costeada),0),1) as food_cost_pct,
          round(100.0*count(*) filter (where costeada)/nullif(count(*),0),1)   as cobertura_pct,
          -- ── LA BANDERA «sospechosa». UMBRAL ALTO PROVISIONAL: 40 %. ────────
          -- Estaba en 60 y NO PODIA ENCENDERSE. Se midieron 68 observaciones
          -- (17 marcas x 4 ventanas) con la metrica por unidad de venta: minimo
          -- 5,4 · mediana 21,6 · p95 31,1 · MAXIMO 33,1. Cero por encima de 60,
          -- cero por encima de 40, una por debajo de 8.
          --
          -- El 60 se fijo cuando los combos inflaban el numero al doble (Deep
          -- Pizza marcaba 78,6 % y es 32,9 %). Corregido el denominador, ninguna
          -- marca de esta casa puede acercarse: era una alarma muda.
          --
          -- 40 son SIETE PUNTOS por encima de la peor marca real: no salta por
          -- variacion normal y sigue por debajo de donde un food cost deja de
          -- ser un margen. Es un numero con padre, no uno redondo.
          --
          -- ES INTERINO, Y ESTA ES SU FECHA DE CADUCIDAD: el umbral bueno no es
          -- absoluto, es «X puntos sobre el objetivo de la cuenta». Hoy no se
          -- puede. CORREGIDO EL 06/09/2026: este comentario decia que Foodint no
          -- tenia fila en `kitchen_settings`. Medido hoy, la fila SI EXISTE y es
          -- `target_food_cost_pct` quien esta a NULL — la conclusion no cambia
          -- (no hay objetivo con el que hacer el umbral relativo) pero la causa
          -- se cuenta como es. Frente A7. El dia que ese objetivo tenga valor,
          -- este 40 se sustituye por el relativo y deja de envejecer solo.
          --
          -- La rama baja se queda en 8: esa SI funciona — salto en julio con una
          -- marca al 5,4 %, que es su trabajo (avisar de que falta coste).
          (round(100.0*sum(coste)/nullif(sum(eur) filter (where costeada),0),1) > 40
           or round(100.0*sum(coste)/nullif(sum(eur) filter (where costeada),0),1) < 8) as sospechoso
        from u where brand_id is not null group by brand_id
      ) x
    ),
    'by_dish', (
      select coalesce(jsonb_agg(d order by d.ingreso desc),'[]'::jsonb) from (
        select dish, brand,
          round(sum(quantity)) as uds,
          round(avg(unit_price),2) as precio,
          round(avg(line_cost / nullif(quantity,0)),2) as food,
          round(100.0*sum(line_cost)/nullif(sum(quantity*unit_price),0),1) as food_cost_pct,
          round(sum(quantity*unit_price)) as ingreso
        from l where costed and dish is not null and lt = 'product'
        group by dish, brand
        order by sum(quantity*unit_price) desc limit 30
      ) d
    )
  );
$$;


--
-- Name: FUNCTION food_cost_dashboard(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid, p_brand uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.food_cost_dashboard(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid, p_brand uuid) IS 'Food cost por UNIDAD DE VENTA (linea de producto + sus combo_item y modifier), no por linea suelta. Antes contaba el coste de los hijos del combo y descartaba el ingreso del padre por no tener receta: inflaba el food cost. Ver 20260902T2200_food_cost_denominador_por_unidad.sql.';


--
-- Name: force_close_long_impersonations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.force_close_long_impersonations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_closed integer;
BEGIN
  UPDATE impersonation_sessions
  SET ended_at = now(), 
      force_closed = true
  WHERE ended_at IS NULL
    AND started_at < now() - interval '4 hours';
  
  GET DIAGNOSTICS v_closed = ROW_COUNT;
  
  IF v_closed > 0 THEN
    RAISE NOTICE 'force_close_long_impersonations: closed % sessions exceeding 4h', v_closed;
  END IF;
  
  RETURN v_closed;
END;
$$;


--
-- Name: FUNCTION force_close_long_impersonations(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.force_close_long_impersonations() IS 'Cierra automáticamente sesiones impersonation >4h. Ejecutar cada 5-10 min via cron.';


--
-- Name: format_price_per_base(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.format_price_per_base(p_format_id uuid, p_supplier_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  WITH self AS (
    SELECT id, qty_in_base
    FROM recipe_item_purchase_format
    WHERE id = p_format_id
  ),
  -- (1) precio propio del formato con ese proveedor
  own AS (
    SELECT as2.last_price, s.qty_in_base
    FROM article_supplier as2
    JOIN self s ON true
    WHERE as2.purchase_format_id = p_format_id
      AND as2.supplier_id        = p_supplier_id
      AND as2.is_active
      AND as2.last_price IS NOT NULL
      AND s.qty_in_base > 0
    LIMIT 1
  ),
  -- (2) derivado desde la caja que tiene este formato como sub-envase
  --     (parent_format_id apunta al sub-envase; qty_per_parent = cuántos contiene)
  derived AS (
    SELECT as2.last_price, caja.qty_per_parent, s.qty_in_base
    FROM recipe_item_purchase_format caja
    JOIN self s ON true
    JOIN article_supplier as2
      ON as2.purchase_format_id = caja.id
     AND as2.supplier_id        = p_supplier_id
     AND as2.is_active
     AND as2.last_price IS NOT NULL
    WHERE caja.parent_format_id = p_format_id
      AND caja.qty_per_parent > 0
      AND s.qty_in_base > 0
    ORDER BY as2.last_price
    LIMIT 1
  )
  SELECT COALESCE(
    (SELECT last_price / qty_in_base FROM own),
    (SELECT last_price / qty_per_parent / qty_in_base FROM derived)
  );
$$;


--
-- Name: fuente__cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente__cuenta(p_empresa uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v uuid;
begin
  select c.account_id into v from public.company c where c.id = p_empresa;
  if v is null then
    raise exception 'La empresa % no existe.', p_empresa using errcode = 'P0002';
  end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_ver(p_empresa) then
    raise exception 'No puedes leer los datos de esa empresa.' using errcode = '42501';
  end if;
  return v;
end
$$;


--
-- Name: fuente__locales(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente__locales(p_empresa uuid) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_cuenta uuid := public.fuente__cuenta(p_empresa); v_una boolean;
begin
  select count(*) = 1 into v_una from public.company c where c.account_id = v_cuenta;
  if to_regclass('public.location_company') is null then
    return query select l.id from public.locations l where l.account_id = v_cuenta;
    return;
  end if;
  -- Con el maestro del N3: los suyos, y los sin fila solo si la cuenta tiene una sola empresa.
  return query execute
    'select l.id from public.locations l
       left join public.location_company lc on lc.location_id = l.id
      where l.account_id = $1 and (lc.company_id = $2 or (lc.location_id is null and $3))'
    using v_cuenta, p_empresa, v_una;
end
$_$;


--
-- Name: fuente_nominas_mes_v1(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente_nominas_mes_v1(p_empresa uuid, p_mes date) RETURNS TABLE(local_id uuid, mes date, trabajadores integer, borradores integer, bruto numeric, ss_empresa numeric, ss_trabajador numeric, irpf numeric, deducciones numeric, liquido numeric, coste_total numeric, desglose_completo boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_cuenta uuid; v_una boolean; v_mes date := date_trunc('month', p_mes)::date; v_locales uuid[];
begin
  if p_mes is null then
    raise exception 'fuente_nominas_mes_v1: falta el mes.' using errcode = '22023';
  end if;
  select c.account_id into v_cuenta from public.company c where c.id = p_empresa;
  if v_cuenta is null then
    raise exception 'La empresa % no existe.', p_empresa using errcode = 'P0002';
  end if;
  if auth.uid() is not null and not public.conta_impuesto_puede_ver(p_empresa) then
    raise exception 'No puedes leer los datos de esa empresa.' using errcode = '42501';
  end if;
  select count(*) = 1 into v_una from public.company c where c.account_id = v_cuenta;

  -- Los locales de la empresa, como fuente__locales (N6).
  if to_regclass('public.location_company') is null then
    select array_agg(l.id) into v_locales from public.locations l where l.account_id = v_cuenta;
  else
    execute
      'select array_agg(l.id) from public.locations l
         left join public.location_company lc on lc.location_id = l.id
        where l.account_id = $1 and (lc.company_id = $2 or (lc.location_id is null and $3))'
      into v_locales using v_cuenta, p_empresa, v_una;
  end if;

  return query
    with n as (
      -- Una por trabajador y mes: la definitiva si la hay.
      select distinct on (p.employee_id) p.*, e.location_id as local
        from public.payroll_cost p
        join public.employees e on e.id = p.employee_id and e.account_id = p.account_id
       where p.account_id = v_cuenta
         and p.period_year = extract(year from v_mes)::int
         and p.period_month = extract(month from v_mes)::int
         and (e.location_id = any(coalesce(v_locales, '{}'::uuid[])) or (e.location_id is null and v_una))
       order by p.employee_id, (p.status = 'definitiva') desc, p.updated_at desc
    )
    select n.local, v_mes,
           count(*)::int,
           (count(*) filter (where n.status = 'borrador'))::int,
           coalesce(sum(n.gross), 0)::numeric(14,2),
           coalesce(sum(n.employer_ss), 0)::numeric(14,2),
           (case when bool_and(n.employee_ss is not null) then sum(n.employee_ss) end)::numeric(14,2),
           (case when bool_and(n.irpf is not null) then sum(n.irpf) end)::numeric(14,2),
           coalesce(sum(n.gross - n.net), 0)::numeric(14,2),
           coalesce(sum(n.net), 0)::numeric(14,2),
           coalesce(sum(coalesce(n.total_cost, n.gross + n.employer_ss)), 0)::numeric(14,2),
           bool_and(n.employee_ss is not null and n.irpf is not null)
      from n
     group by n.local
     order by n.local nulls last;
end
$_$;


--
-- Name: FUNCTION fuente_nominas_mes_v1(p_empresa uuid, p_mes date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fuente_nominas_mes_v1(p_empresa uuid, p_mes date) IS 'N7 (24/10). Puerta v1 de Sumied hacia Folvy: el coste de personal del mes por local. Solo lectura, comprueba la empresa, importes numeric(14,2).';


--
-- Name: fuente_pedidos_v1(uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente_pedidos_v1(p_empresa uuid, p_desde timestamp with time zone, p_hasta timestamp with time zone, p_canal text DEFAULT NULL::text) RETURNS TABLE(pedido_id uuid, local_id uuid, marca_id uuid, canal_id uuid, canal text, referencia text, sold_at timestamp with time zone, dia_madrid date, estado text, estado_plataforma text, total numeric, quien_reparte text, con_rider boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select s.id, s.location_id, s.brand_id, s.channel_id, ch.slug,
         coalesce(s.platform_order_code, s.external_ref), s.sold_at, (s.sold_at at time zone 'Europe/Madrid')::date,
         s.status, s.order_status, coalesce(s.total, 0)::numeric(14,2), s.dispatch_mode, s.has_courier
    from public.sale s
    left join public.sales_channel ch on ch.id = s.channel_id
   where s.account_id = public.fuente__cuenta(p_empresa)
     and s.location_id in (select public.fuente__locales(p_empresa))
     and s.sold_at >= p_desde and s.sold_at < p_hasta
     and (p_canal is null or ch.slug = p_canal)
   order by s.sold_at, s.id
$$;


--
-- Name: FUNCTION fuente_pedidos_v1(p_empresa uuid, p_desde timestamp with time zone, p_hasta timestamp with time zone, p_canal text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fuente_pedidos_v1(p_empresa uuid, p_desde timestamp with time zone, p_hasta timestamp with time zone, p_canal text) IS 'N6 (24/10). Puerta v1 de Sumied hacia Folvy: solo lectura, comprueba la empresa (fuente__cuenta), importes numeric(14,2), horas UTC y día en Madrid.';


--
-- Name: fuente_productos_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente_productos_v1(p_empresa uuid, p_tipo text DEFAULT NULL::text) RETURNS TABLE(producto_id uuid, nombre text, tipo text, unidad text, activo boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select ri.id, ri.name, ri.type, coalesce(ku.abbreviation, ku.name), coalesce(ri.is_active, true) and ri.archived_at is null
    from public.recipe_item ri
    left join public.kitchen_unit ku on ku.id = ri.base_unit_id
   where ri.account_id = public.fuente__cuenta(p_empresa)
     and (p_tipo is null or ri.type = p_tipo)
   order by ri.name, ri.id
$$;


--
-- Name: FUNCTION fuente_productos_v1(p_empresa uuid, p_tipo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fuente_productos_v1(p_empresa uuid, p_tipo text) IS 'N6 (24/10). Puerta v1 de Sumied hacia Folvy: solo lectura, comprueba la empresa (fuente__cuenta), importes numeric(14,2), horas UTC y día en Madrid.';


--
-- Name: fuente_recepcion_lineas_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente_recepcion_lineas_v1(p_recepcion uuid) RETURNS TABLE(linea_id uuid, articulo_id uuid, articulo text, cantidad numeric, unidad text, precio numeric, base numeric, tipo_iva numeric, no_es_mercancia boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_empresa uuid;
begin
  select g.account_id into v_cuenta from public.goods_receipt g where g.id = p_recepcion;
  if v_cuenta is null then raise exception 'La recepción % no existe.', p_recepcion using errcode = 'P0002'; end if;
  -- Se comprueba contra una empresa de su cuenta (la de su local, si el N3 lo dice).
  select c.id into v_empresa from public.company c where c.account_id = v_cuenta order by c.created_at limit 1;
  perform public.fuente__cuenta(v_empresa);
  return query
    select gl.id, gl.recipe_item_id, coalesce(ri.name, gl.product_name), gl.qty_received,
           coalesce(ku.abbreviation, ku.name), gl.unit_cost,
           coalesce(gl.doc_amount, gl.qty_received * gl.unit_cost)::numeric(14,2),
           (select r.rate from public.vat_rate_for(ri.vat_category_id, g.receipt_date) r),
           coalesce(gl.not_goods, false)
      from public.goods_receipt_line gl
      join public.goods_receipt g on g.id = gl.goods_receipt_id
      left join public.recipe_item ri on ri.id = gl.recipe_item_id
      left join public.kitchen_unit ku on ku.id = gl.purchase_unit_id
     where gl.goods_receipt_id = p_recepcion
     order by gl.position nulls last, gl.id;
end
$$;


--
-- Name: FUNCTION fuente_recepcion_lineas_v1(p_recepcion uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fuente_recepcion_lineas_v1(p_recepcion uuid) IS 'N6 (24/10). Puerta v1 de Sumied hacia Folvy: solo lectura, comprueba la empresa (fuente__cuenta), importes numeric(14,2), horas UTC y día en Madrid.';


--
-- Name: fuente_recepciones_v1(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente_recepciones_v1(p_empresa uuid, p_desde date, p_hasta date) RETURNS TABLE(recepcion_id uuid, local_id uuid, proveedor_id uuid, proveedor text, fecha date, albaran text, estado text, base numeric, iva numeric, total numeric, iva_completo boolean, papel text, recibida_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with l as (
    select gl.goods_receipt_id,
           coalesce(gl.doc_amount, gl.qty_received * gl.unit_cost) as base,
           (select r.rate from public.vat_rate_for(ri.vat_category_id, g.receipt_date) r) as tipo
      from public.goods_receipt g
      join public.goods_receipt_line gl on gl.goods_receipt_id = g.id
      left join public.recipe_item ri on ri.id = gl.recipe_item_id
     where g.account_id = public.fuente__cuenta(p_empresa)
       and g.location_id in (select public.fuente__locales(p_empresa))
       and g.receipt_date between p_desde and p_hasta
       and not coalesce(gl.not_goods, false)
  ), s as (
    select goods_receipt_id, sum(base) base, sum(base * tipo / 100) iva, bool_and(tipo is not null) completo
      from l group by goods_receipt_id
  )
  select g.id, g.location_id, g.supplier_id, sp.name, g.receipt_date, g.supplier_doc_number, g.status,
         coalesce(s.base, 0)::numeric(14,2), coalesce(s.iva, 0)::numeric(14,2),
         (coalesce(s.base, 0) + coalesce(s.iva, 0))::numeric(14,2), coalesce(s.completo, true),
         g.raw_document_url, g.received_at
    from public.goods_receipt g
    left join s on s.goods_receipt_id = g.id
    left join public.supplier sp on sp.id = g.supplier_id
   where g.account_id = public.fuente__cuenta(p_empresa)
     and g.location_id in (select public.fuente__locales(p_empresa))
     and g.receipt_date between p_desde and p_hasta
     and coalesce(g.is_active, true)
   order by g.receipt_date, g.id
$$;


--
-- Name: FUNCTION fuente_recepciones_v1(p_empresa uuid, p_desde date, p_hasta date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fuente_recepciones_v1(p_empresa uuid, p_desde date, p_hasta date) IS 'N6 (24/10). Puerta v1 de Sumied hacia Folvy: solo lectura, comprueba la empresa (fuente__cuenta), importes numeric(14,2), horas UTC y día en Madrid.';


--
-- Name: fuente_ventas_dia_v1(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fuente_ventas_dia_v1(p_empresa uuid, p_dia date) RETURNS TABLE(local_id uuid, marca_id uuid, canal_id uuid, pedidos integer, base numeric, iva numeric, total numeric, devoluciones numeric, no_confirmados integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with h as (
    select coalesce((select t.sales_day_close_time from public.company_tax_profile t where t.company_id = p_empresa), time '02:00') as hora
  )
  select s.location_id, s.brand_id, s.channel_id, count(*)::integer,
         sum(coalesce(s.taxable_base, 0))::numeric(14,2), sum(coalesce(s.tax, 0))::numeric(14,2),
         sum(coalesce(s.total, 0))::numeric(14,2), sum(coalesce(s.refund_amount, 0))::numeric(14,2),
         count(*) filter (where exists (select 1 from public.sales_day_close_log g
                                         where g.sale_id = s.id and g.accion = 'cerrado_sin_confirmar'))::integer
    from public.sale s, h
   where s.account_id = public.fuente__cuenta(p_empresa)
     and s.location_id in (select public.fuente__locales(p_empresa))
     and s.status = 'closed'
     and ((s.sold_at at time zone 'Europe/Madrid') - h.hora)::date = p_dia
   group by s.location_id, s.brand_id, s.channel_id
   order by s.location_id, s.brand_id, s.channel_id
$$;


--
-- Name: FUNCTION fuente_ventas_dia_v1(p_empresa uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fuente_ventas_dia_v1(p_empresa uuid, p_dia date) IS 'N6 (24/10). Puerta v1 de Sumied hacia Folvy: solo lectura, comprueba la empresa (fuente__cuenta), importes numeric(14,2), horas UTC y día en Madrid.';


--
-- Name: fv_e164_or_null(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fv_e164_or_null(p text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE v text;
BEGIN
  v := regexp_replace(coalesce(p,''), '\D', '', 'g');
  IF v = '' THEN RETURN NULL; END IF;
  IF left(v,2) = '00' THEN v := substr(v,3); END IF;               -- 0034... -> 34...
  IF length(v) = 9 AND substr(v,1,1) IN ('6','7') THEN            -- móvil ES sin prefijo
     v := '34' || v;
  END IF;
  IF length(v) BETWEEN 11 AND 15 THEN RETURN v; END IF;           -- ya con prefijo país
  RETURN NULL;                                                    -- fijo/incompleto -> no enviable
END;
$$;


--
-- Name: generate_course_from_recipe(uuid, text, text, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_course_from_recipe(p_recipe_item_id uuid, p_title text, p_summary text, p_estimated_minutes integer, p_sections jsonb, p_questions jsonb, p_practical_item_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_existing_course_id uuid;
  v_existing_version int;
  v_version int;
  v_course_id uuid;
  v_sec jsonb;
  v_new_section_id uuid;
  v_q jsonb;
  v_new_question_id uuid;
  v_opt jsonb;
  v_sections_out jsonb := '[]'::jsonb;
  v_regenerated boolean;
begin
  select account_id into v_account_id from public.recipe_item where id = p_recipe_item_id;
  if v_account_id is null then
    raise exception 'generate_course_from_recipe: receta % no encontrada', p_recipe_item_id;
  end if;

  if not (public.current_user_is_admin_or_manager_of(v_account_id) or public.current_user_is_admin()) then
    raise exception 'generate_course_from_recipe: sin acceso a la cuenta %', v_account_id;
  end if;

  select id, version into v_existing_course_id, v_existing_version
  from public.course
  where source_recipe_item_id = p_recipe_item_id and account_id = v_account_id;

  v_regenerated := v_existing_course_id is not null;

  if v_regenerated then
    v_version := coalesce(v_existing_version, 1) + 1;

    -- 🔴 Rescate: cualquier firma de este curso sin snapshot todavía se
    -- congela AHORA, con el contenido que está a punto de borrarse. Tras
    -- este UPDATE, todas las firmas ya existentes de este curso tienen su
    -- propio content_snapshot, independiente de lo que le pase al DELETE
    -- de más abajo.
    update public.course_signature cs
    set content_snapshot = public.build_course_content_snapshot(v_existing_course_id)
    where cs.content_snapshot is null
      and cs.attempt_id in (
        select ca4.id
        from public.course_attempt ca4
        join public.course_assignment ca5 on ca5.id = ca4.assignment_id
        where ca5.course_id = v_existing_course_id
      );

    -- Secciones y preguntas SÍ se reemplazan por completo -- la evidencia
    -- legal de qué firmó cada uno ya no depende de estas filas (vive en
    -- content_snapshot desde el paso anterior), así que regenerar puede
    -- seguir reemplazando el contenido vivo sin perder el histórico.
    -- course_option cae en cascada al borrar su course_question (C1).
    delete from public.course_section where course_id = v_existing_course_id;
    delete from public.course_question where course_id = v_existing_course_id;

    update public.course
    set title = p_title,
        summary = p_summary,
        estimated_minutes = p_estimated_minutes,
        version = v_version,
        status = 'draft' -- contenido nuevo, vuelve a exigir revisión (regla dura del encargo: "siempre borrador")
    where id = v_existing_course_id;

    v_course_id := v_existing_course_id;
  else
    v_version := 1;
    insert into public.course (
      account_id, code, title, summary, delivery_mode, reeval_months, is_mandatory,
      appcc_prerequisite, estimated_minutes, version, status,
      category, business_types, level, recommended_order, requires_practical,
      source_recipe_item_id
    ) values (
      v_account_id,
      'producto_' || p_recipe_item_id::text,
      p_title, p_summary, 'folvy_imparte', null, false,
      false, p_estimated_minutes, v_version, 'draft',
      'producto', '{todos}', 'especialista', null, true,
      p_recipe_item_id
    )
    returning id into v_course_id;
  end if;

  for v_sec in select * from jsonb_array_elements(p_sections)
  loop
    insert into public.course_section (course_id, ord, title, body, media_url)
    values (v_course_id, (v_sec->>'ord')::int, v_sec->>'title', v_sec->>'body', null)
    returning id into v_new_section_id;

    v_sections_out := v_sections_out || jsonb_build_object(
      'id', v_new_section_id,
      'ord', (v_sec->>'ord')::int,
      'sourcePhotoPath', v_sec->'sourcePhotoPath'
    );
  end loop;

  for v_q in select * from jsonb_array_elements(p_questions)
  loop
    insert into public.course_question (course_id, ord, text)
    values (v_course_id, (v_q->>'ord')::int, v_q->>'text')
    returning id into v_new_question_id;

    for v_opt in select * from jsonb_array_elements(v_q->'options')
    loop
      insert into public.course_option (question_id, text, is_correct, explanation)
      values (v_new_question_id, v_opt->>'text', (v_opt->>'isCorrect')::boolean, v_opt->>'explanation');
    end loop;
  end loop;

  if p_practical_item_text is not null and not exists (
    select 1 from public.course_practical_item where course_id = v_course_id
  ) then
    insert into public.course_practical_item (course_id, ord, text)
    values (v_course_id, 1, p_practical_item_text);
  end if;

  return jsonb_build_object(
    'courseId', v_course_id,
    'version', v_version,
    'regenerated', v_regenerated,
    'sections', v_sections_out
  );
end;
$$;


--
-- Name: generate_daily_count(uuid, uuid, uuid[], integer, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_daily_count(p_account_id uuid, p_location_id uuid, p_employee_ids uuid[] DEFAULT NULL::uuid[], p_per_person integer DEFAULT 8, p_coverage_target numeric DEFAULT 80, p_ignore_freshness boolean DEFAULT false) RETURNS TABLE(count_id uuid, lines_created integer, already_existed boolean, coverage_before numeric, coverage_after numeric, per_person_today integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'generate_daily_count: sin acceso a la cuenta %', p_account_id;
  END IF;
  RETURN QUERY
  SELECT * FROM public._generate_daily_count_core(
    p_account_id, p_location_id, p_employee_ids, p_per_person, p_coverage_target, p_ignore_freshness);
END;
$$;


--
-- Name: generate_sale_consumption(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_sale_consumption(p_sale_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale       sale%ROWTYPE;
  v_void       boolean;
  v_legacy     boolean;
  v_fecha      timestamptz;
  v_written    integer := 0;
  v_previos    uuid[] := '{}';
  v_libres     uuid[] := '{}';
  v_protegidos uuid[] := '{}';
  v_cortes     timestamptz[] := '{}';
  v_nuevos     uuid[] := '{}';
  v_todos      uuid[] := '{}';
  v_item       uuid;
  v_huella_antes   text;
  v_huella_despues text;
BEGIN
  SELECT * INTO v_sale FROM sale WHERE id = p_sale_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- ══ LA HUELLA DE ANTES · FV001 · 16/09/2026 ══
  v_huella_antes := public._huella_consumo(p_sale_id);

  BEGIN

  -- La fecha del libro: la misma con la que se sella el asiento y con la que
  -- se decide el corte. Una sola vara para las dos cosas.
  v_fecha := COALESCE(v_sale.created_at, now());

  -- D2: una venta anulada/rechazada/inactiva NO consume.
  -- Cierre del dia (16/10): un pedido cerrado como no confirmado
  -- (unconfirmed_at) NO es una anulacion: su consumo se queda y, si se
  -- regenera, se recalcula como el de cualquier venta.
  v_void := (COALESCE(v_sale.status, '') = 'cancelled' AND v_sale.unconfirmed_at IS NULL)
         OR COALESCE(v_sale.order_status, '') IN ('cancelled', 'rejected')
         OR NOT COALESCE(v_sale.is_active, true);

  -- El motor viejo escribia con la llave de la LINEA. Por encima del corte no
  -- existe ninguna (ver `_corte_motor_viejo`, que es donde vive la fecha y su
  -- medicion), asi que ni se buscan: ese `OR source_id IN (...)` cuesta 28 ms
  -- por venta porque no puede usar `idx_sm_source`, y un pedido de hoy no tiene
  -- por que pagarlo. El vigia de consumo avisa si deja de ser verdad.
  v_legacy := v_fecha < public._corte_motor_viejo();

  -- ── LO QUE ESTA VENTA YA TIENE APUNTADO ───────────────────────────────
  SELECT COALESCE(array_agg(DISTINCT sm.recipe_item_id), '{}') INTO v_previos
    FROM public.stock_movement sm
   WHERE sm.account_id    = v_sale.account_id
     AND sm.movement_type = 'consumo'
     AND sm.source_type   = 'sale'
     AND sm.source_id     = p_sale_id
     AND sm.recipe_item_id IS NOT NULL;

  IF v_legacy THEN
    SELECT COALESCE(array_agg(DISTINCT sm.recipe_item_id), '{}') || v_previos
      INTO v_previos
      FROM public.stock_movement sm
     WHERE sm.account_id    = v_sale.account_id
       AND sm.movement_type = 'consumo'
       AND sm.source_type   = 'sale'
       AND sm.source_id IN (SELECT id FROM public.sale_line WHERE sale_id = p_sale_id)
       AND sm.recipe_item_id IS NOT NULL;
    -- Las dos llaves pueden traer el MISMO ingrediente, y concatenar dos
    -- arrays no lo quita. Si se cuela repetido, la nota de proteccion intenta
    -- escribir dos veces la misma fila y Postgres para la venta entera con
    -- 21000 («ON CONFLICT DO UPDATE command cannot affect row a second time»).
    -- Lo cazo el ensayo C8; en una venta de hoy no pasa nunca, porque solo se
    -- mira una llave.
    SELECT COALESCE(array_agg(DISTINCT x), '{}') INTO v_previos FROM unnest(v_previos) x;
  END IF;

  -- ── LO VIEJO: se borra lo libre, se apunta lo protegido ───────────────

  IF array_length(v_previos, 1) IS NOT NULL THEN
    SELECT COALESCE(array_agg(i.item)  FILTER (WHERE c.corte IS NULL OR v_fecha >= c.corte), '{}'),
           COALESCE(array_agg(i.item)  FILTER (WHERE c.corte IS NOT NULL AND v_fecha < c.corte), '{}'),
           COALESCE(array_agg(c.corte) FILTER (WHERE c.corte IS NOT NULL AND v_fecha < c.corte), '{}')
      INTO v_libres, v_protegidos, v_cortes
      FROM unnest(v_previos) AS i(item)
      LEFT JOIN public.cortes_aprobados(v_sale.location_id, v_previos) c
             ON c.recipe_item_id = i.item;

    IF array_length(v_protegidos, 1) IS NOT NULL THEN
      INSERT INTO public.sale_consumption_skip
        (account_id, sale_id, recipe_item_id, location_id, fecha_venta, corte, motivo)
      SELECT v_sale.account_id, p_sale_id, x.item, v_sale.location_id, v_fecha, x.corte,
             CASE WHEN v_void
                  THEN 'anulacion por debajo del corte: no se devuelve stock, el recuento posterior ya conto lo que habia'
                  ELSE 'regeneracion por debajo del corte: el recuento posterior ya cuadro este ingrediente'
             END
        FROM unnest(v_protegidos, v_cortes) AS x(item, corte)
      ON CONFLICT (sale_id, recipe_item_id) DO UPDATE
        SET corte = EXCLUDED.corte, fecha_venta = EXCLUDED.fecha_venta,
            motivo = EXCLUDED.motivo, created_at = now();
    END IF;

    IF array_length(v_libres, 1) IS NOT NULL THEN
      -- Una nota que ya no es verdad miente igual que un silencio.
      DELETE FROM public.sale_consumption_skip s
       WHERE s.sale_id = p_sale_id AND s.recipe_item_id = ANY(v_libres);

      DELETE FROM public.stock_movement sm
       WHERE sm.account_id    = v_sale.account_id
         AND sm.movement_type = 'consumo'
         AND sm.source_type   = 'sale'
         AND sm.source_id     = p_sale_id
         AND sm.recipe_item_id = ANY(v_libres);

      -- Aqui se cierra el mecanismo que re-creaba duplicados: el motor viejo
      -- de ESTA venta se va con el resto, pero solo por encima del corte.
      IF v_legacy THEN
        DELETE FROM public.stock_movement sm
         WHERE sm.account_id    = v_sale.account_id
           AND sm.movement_type = 'consumo'
           AND sm.source_type   = 'sale'
           AND sm.source_id IN (SELECT id FROM public.sale_line WHERE sale_id = p_sale_id)
           AND sm.recipe_item_id = ANY(v_libres);
      END IF;
    END IF;
  END IF;

  -- ── LO NUEVO: UNA sola pasada del escandallo ──────────────────────────
  -- `base` se recorre una vez y de ella cuelgan las dos escrituras. Llamar
  -- dos veces a `_sale_line_raw_consumption` costaba 50 ms por venta.
  --
  -- UNA FILA POR (LINEA, INGREDIENTE): al rellenar `sale_line_id` se despierta
  -- el indice unico `stock_movement_sale_line_dedup`, dormido desde siempre
  -- porque la columna estaba a NULL en las 68.582 filas. Tiene razon: el mismo
  -- ingrediente puede venir dos veces en una linea, una por la receta y otra
  -- por un extra. Medido sobre 129 ventas reales: 1.474 renglones pasan a
  -- 1.367 filas y la suma no se mueve (74.950,7183 a los dos lados).
  IF NOT v_void THEN
    WITH base AS (
      SELECT sl.id AS line, r.raw_item_id AS item, sum(r.qty_base) AS qty
        FROM public.sale_line sl
        CROSS JOIN LATERAL public._sale_line_raw_consumption(sl.id) r
       WHERE sl.sale_id = p_sale_id
         AND COALESCE(sl.line_type, 'product') = 'product'
         AND sl.ignored_at IS NULL
         -- D1: o la linea esta mapeada, o es la cabecera de un COMBO.
         AND (
           sl.menu_item_id IS NOT NULL
           OR EXISTS (SELECT 1 FROM public.sale_line c
                       WHERE c.parent_sale_line_id = sl.id AND c.line_type = 'combo_item')
         )
         AND r.raw_item_id IS NOT NULL
         AND r.qty_base IS NOT NULL
       GROUP BY sl.id, r.raw_item_id
      -- qty_base viene CON SIGNO: +N consumo, -N remove. Si se anulan entre
      -- ellos no hay asiento: un cero no es un movimiento.
      HAVING sum(r.qty_base) <> 0
    ),
    items AS (SELECT DISTINCT item FROM base),
    -- ── LO ESPERADO, ESCRITO EN EL MOMENTO (punto 1 del encargo del vigia) ──
    -- `base` es lo que el motor va a consumir, ya deduplicado y ya sin los ceros
    -- que se anulan. Guardarlo aqui es lo unico que evita que manana alguien
    -- vuelva a preguntarle al motor de manana por una venta de hoy — que es lo
    -- que movio 2.061 lineas de casilla el 23/09 al empezar a explotar envase.
    -- Las dos escrituras son DISJUNTAS: se borra lo que NO esta en `base`, se
    -- mete lo que SI esta. Nunca tocan la misma fila en la misma sentencia.
    esperado_stale AS (
      DELETE FROM public.sale_line_consumo_esperado e
       USING public.sale_line sl
       WHERE sl.sale_id = p_sale_id
         AND e.sale_line_id = sl.id
         AND NOT EXISTS (SELECT 1 FROM base b
                          WHERE b.line = e.sale_line_id AND b.item = e.recipe_item_id)
      RETURNING 1
    ),
    esperado AS (
      INSERT INTO public.sale_line_consumo_esperado
        (account_id, sale_id, sale_line_id, recipe_item_id, location_id, qty_base, fecha_venta)
      SELECT v_sale.account_id, p_sale_id, b.line, b.item, v_sale.location_id, b.qty, v_fecha
        FROM base b
      ON CONFLICT (sale_line_id, recipe_item_id) DO UPDATE
        SET qty_base = EXCLUDED.qty_base,
            fecha_venta = EXCLUDED.fecha_venta,
            location_id = EXCLUDED.location_id,
            created_at = now()
      RETURNING 1
    ),
    cortes AS (
      SELECT * FROM public.cortes_aprobados(v_sale.location_id,
                      (SELECT array_agg(item) FROM items))
    ),
    -- EL PRECIO SE RESUELVE AQUI, Y CON EL SE DECIDE SI SE PUEDE ESCRIBIR.
    -- Antes se calculaba dentro del propio INSERT y nadie lo miraba: por eso
    -- entraban precios imposibles sin que nada chistara.
    precios AS (
      SELECT i.item,
             (SELECT ric.avg_unit_cost
                FROM public.recipe_item_location_stock ric
               WHERE ric.recipe_item_id = i.item
                 AND ric.account_id  = v_sale.account_id
                 AND ric.location_id = v_sale.location_id)            AS medio,
             (SELECT COALESCE(ri.computed_cost, ri.fixed_cost)
                FROM public.recipe_item ri WHERE ri.id = i.item)      AS escandallo
        FROM items i
    ),
    plan AS (
      SELECT i.item, c.corte,
             (c.corte IS NULL OR v_fecha >= c.corte) AS libre,
             pr.medio, pr.escandallo,
             -- PRECIO INDEFENDIBLE: negativo, o mas de 20 veces el escandallo.
             -- Medido el 12/09: 24 articulo-local con el coste medio NEGATIVO
             -- (los 24 con su computed_cost positivo) y 2 absurdos. El peor no
             -- es ninguno de los negativos: es la Albahaca de Plaza Castilla a
             -- 7,1536 EUR/gramo contra 0,0278 del escandallo — 258 veces mas—,
             -- que ella sola le daba la vuelta al signo del coste de un local
             -- entero. Una guarda de "negativo" no la habria atrapado.
             --
             -- EL COALESCE NO ES DECORACION, Y COSTO UN AGUJERO MUDO. Sin el,
             -- un ingrediente con `avg_unit_cost` NULO daba `indefendible =
             -- NULL`, y un NULO se cuela por LAS DOS PUERTAS A LA VEZ:
             --   `puesto` pide `NOT p.indefendible` ....... NULL -> no escribe
             --   `notas`  pide `NOT libre OR indefendible`  NULL -> no apunta
             -- Ni movimiento ni nota: consumo que desaparece sin rastro, que
             -- es justo lo que prohiben las reglas 8 y 30. En Foodint son 186
             -- articulos sin fila de stock y 134 filas con el medio a NULO.
             -- Lo cazo el ensayo del paso 2: los Nachos de Carabanchel tenian
             -- -100 por cada motor, al regenerar quedaban 0 movimientos y 0
             -- notas, y el escandallo de hoy SI daba su renglon.
             -- No habia mordido a nadie: 0 ventas entre las 08:56 y las 09:30,
             -- porque los locales no habian abierto. Habria empezado sobre la
             -- 13:00, dentro de la banda prohibida.
             -- Sin precio medio NO hay nada que juzgar: el escritor ya sabe
             -- que hacer (`WHEN p.medio IS NULL THEN p.escandallo`), asi que
             -- defendible por defecto y el almacen se mueve.
             COALESCE(
               pr.medio < 0
               OR (pr.medio > 0 AND pr.escandallo > 0 AND pr.medio > 20 * pr.escandallo)
             , false) AS indefendible
        FROM items i
        LEFT JOIN cortes  c  ON c.recipe_item_id = i.item
        LEFT JOIN precios pr ON pr.item = i.item
    ),
    -- UNA NOTA QUE YA NO ES VERDAD MIENTE IGUAL QUE UN SILENCIO (regla 30).
    -- El DELETE de notas de mas arriba solo mira los ingredientes que YA tenian
    -- movimiento. Uno que se quedo fuera por precio no tiene ninguno, asi que
    -- cuando su precio se arregla y vuelve a escribirse, su nota de "no se
    -- escribio por precio" se queda ahi, mintiendo sobre trabajo que SI esta
    -- hecho. Lo cazo el ensayo P4 subiendo y bajando el precio del mismo
    -- articulo. Los dos conjuntos son disjuntos por construccion —este borra lo
    -- libre y defendible, el de abajo apunta lo protegido o indefendible— asi
    -- que no se pisan dentro de la misma sentencia.
    limpia AS (
      DELETE FROM public.sale_consumption_skip s
       USING plan p
       WHERE s.sale_id = p_sale_id AND s.recipe_item_id = p.item
         AND p.libre AND NOT p.indefendible
      RETURNING s.recipe_item_id
    ),
    notas AS (
      INSERT INTO public.sale_consumption_skip
        (account_id, sale_id, recipe_item_id, location_id, fecha_venta, corte, motivo)
      -- UNA fila por ingrediente, no dos: un ingrediente puede estar protegido
      -- por el corte Y tener el precio roto a la vez, y dos filas con la misma
      -- clave rompen la venta entera con 21000. Manda el corte, porque si esta
      -- protegido no se escribe pase lo que pase con el precio.
      SELECT v_sale.account_id, p_sale_id, p.item, v_sale.location_id, v_fecha, p.corte,
             CASE WHEN NOT p.libre
                  THEN 'regeneracion por debajo del corte: el recuento posterior ya cuadro este ingrediente'
                  ELSE format('precio indefendible: %s EUR frente a %s del escandallo. No se escribe el '
                           || 'movimiento para no meter ese precio en la historia de coste.',
                           round(p.medio, 6), round(p.escandallo, 6))
             END
        FROM plan p WHERE NOT p.libre OR p.indefendible
      ON CONFLICT (sale_id, recipe_item_id) DO UPDATE
        SET corte = EXCLUDED.corte, fecha_venta = EXCLUDED.fecha_venta,
            motivo = EXCLUDED.motivo, created_at = now()
      RETURNING recipe_item_id
    ),
    -- ── LO QUE SE RETIRA, DICHO ──────────────────────────────────────────
    -- Un ingrediente que ESTA venta tenia apuntado, que el corte deja libre,
    -- y que el escandallo de HOY ya no pide: sus movimientos se han borrado
    -- ahi arriba y aqui no hay nada que escribir. Sin esta nota se iba en
    -- silencio, que es la regla 8 y la 30 otra vez.
    --
    -- MEDIDO EL 12/09, ensayando el paso 4: seis ventas del 15 al 27/08
    -- perdian su unico renglon de Albahaca —11,765 g cada una, 70,6 en
    -- total— y no quedaba una sola nota. Ese ingrediente solo vive en
    -- `v_previos`; nunca llega a `base`, asi que no entra en `plan` y
    -- ninguna de las dos ramas de arriba lo mira.
    --
    -- POR QUE PASA, y la nota no lo finge: no hay una sola causa. Puede ser
    -- que la receta cambiara, que la linea dejara de estar mapeada (D1), o
    -- que un `remove_item` anule la cantidad (el HAVING de `base`). Las tres
    -- dicen lo mismo de cara al almacen, y distinguirlas pide comparar
    -- versiones de escandallo que no existen: `recipe_item_version` tiene
    -- UNA fila, de UNA ficha. Asi que la nota dice lo que se sabe y no
    -- inventa el motivo.
    --
    -- `corte` va a NULO a proposito: aqui no hay corte que citar, y por eso
    -- la columna dejo de ser NOT NULL.
    --
    -- DISJUNTO POR CONSTRUCCION con las otras dos escrituras de la misma
    -- sentencia: `limpia` y `notas` solo tocan lo que esta en `items`, y
    -- esto solo toca lo que NO esta. Sin eso, dos filas con la misma clave
    -- rompen la venta entera con 21000.
    retirados AS (
      INSERT INTO public.sale_consumption_skip
        (account_id, sale_id, recipe_item_id, location_id, fecha_venta, corte, motivo)
      SELECT v_sale.account_id, p_sale_id, x.item, v_sale.location_id, v_fecha, NULL::timestamptz,
             'el escandallo de hoy ya no pide este ingrediente en esta venta: se retira lo que habia '
          || 'apuntado. Puede ser que la receta cambiara, que la linea dejara de estar mapeada o que '
          || 'un extra lo anule; no se guarda la version del escandallo con la que se consumio, asi '
          || 'que no se puede decir cual.'
        FROM unnest(v_libres) AS x(item)
       WHERE NOT EXISTS (SELECT 1 FROM items i WHERE i.item = x.item)
      ON CONFLICT (sale_id, recipe_item_id) DO UPDATE
        SET corte = EXCLUDED.corte, fecha_venta = EXCLUDED.fecha_venta,
            motivo = EXCLUDED.motivo, created_at = now()
      RETURNING recipe_item_id
    ),
    puesto AS (
      INSERT INTO public.stock_movement(
        account_id, location_id, recipe_item_id, movement_type, qty_base,
        unit_cost, source_type, source_id, sale_line_id, occurred_at, notes)
      SELECT v_sale.account_id, v_sale.location_id, b.item, 'consumo', -b.qty,
        -- EL COSTE, con sus tres casos dichos:
        --   sin coste medio      -> vale el del escandallo, como antes;
        --   coste medio CERO     -> NULO, no cero. Cero dice "es gratis"; nulo
        --                           dice "no lo se", que es la verdad. El front
        --                           ya lo cuenta asi (`unit_cost == null` ->
        --                           sinCoste en countApprovalService). Entre no
        --                           mover el almacen y no valorarlo, gana mover
        --                           el almacen: el movimiento SI se escribe.
        --   coste medio bueno    -> ese.
        CASE WHEN p.medio IS NULL THEN p.escandallo
             WHEN p.medio = 0     THEN NULL
             ELSE p.medio END,
        'sale', p_sale_id, b.line, v_fecha, 'Consumo por venta'
        FROM base b JOIN plan p ON p.item = b.item AND p.libre AND NOT p.indefendible
      RETURNING recipe_item_id
    )
    SELECT count(*)::int, COALESCE(array_agg(DISTINCT recipe_item_id), '{}')
      INTO v_written, v_nuevos
      FROM puesto;
  END IF;

  -- ── REFRESCAR LA CACHE de lo que ha podido cambiar ────────────────────
  v_todos := v_previos || v_nuevos;
  IF v_sale.location_id IS NOT NULL AND array_length(v_todos, 1) IS NOT NULL THEN
    FOR v_item IN SELECT DISTINCT x FROM unnest(v_todos) x WHERE x IS NOT NULL
    LOOP
      PERFORM public.recompute_location_stock_core(v_item, v_sale.location_id);
    END LOOP;
  END IF;


  -- ══ SI NADA HA CAMBIADO, SE DESHACE EL BLOQUE ENTERO · FV001 ══
  -- El cuerpo de arriba es el de siempre, literal y una sola vez. Si lo que ha
  -- quedado escrito es identico a lo que habia, este error propio deshace la
  -- subtransaccion entera: mismos identificadores, 0 filas nuevas, cache
  -- incluida.
  -- NOT v_legacy: la huella solo mira lo que cuelga de la VENTA, y en una venta
  -- vieja esta funcion tambien borra lo que cuelga de la LINEA, que la huella
  -- no ve. Donde no puede ver, no decide. (La misma exclusion que tenia la
  -- guarda de las 19:14.)
  v_huella_despues := public._huella_consumo(p_sale_id);
  IF NOT v_legacy AND v_huella_despues = v_huella_antes THEN
    RAISE EXCEPTION USING ERRCODE = 'FV001', MESSAGE = 'consumo sin cambios';
  END IF;
  EXCEPTION
    WHEN SQLSTATE 'FV001' THEN
      NULL;
  END;

  -- El numero que ven los siete llamadores: lo que la venta TIENE. Es el mismo
  -- que devolvia la guarda de las 19:14 cuando no habia nada que cambiar, y
  -- ahora se devuelve siempre, que es lo que pedia el bloque.
  RETURN (SELECT count(*)::int FROM public.stock_movement sm
           WHERE sm.account_id = v_sale.account_id AND sm.movement_type = 'consumo'
             AND sm.source_type = 'sale' AND sm.source_id = p_sale_id);
END;
$$;


--
-- Name: generate_week_schedule(uuid, uuid, date, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_week_schedule(p_account uuid, p_location uuid, p_week_start date, p_role text DEFAULT 'cocina'::text, p_min_pct_dias numeric DEFAULT 15.0) RETURNS TABLE(o_fecha date, o_dow integer, o_shift_template_id uuid, o_ini text, o_fin text, o_horas numeric, o_capa integer, o_employee_id uuid, o_employee text, o_hueco boolean, o_motivo text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_max_h numeric; v_min_h numeric; v_rest_min int; v_rest_12h int; v_split_gap int; v_tol_pct numeric;
  v_peak_wd int; v_peak_we int; v_pre_open int; v_post_close int;
  v_dem jsonb := '{}'::jsonb;
  v_templates jsonb := '[]'::jsonb;
  v_uso jsonb := '{}'::jsonb;
  v_day_total numeric[] := array_fill(0::numeric, array[7]);
  v_tmp numeric;
  v_n_emp int := 1;
  v_long_tpl_id uuid; v_long_dur numeric;
  v_long_days int[] := array[]::int[];
  v_day_order int[];
  v_week_idx int;
  v_horas jsonb := '{}'::jsonb;
  v_turnos jsonb := '{}'::jsonb;
  v_plan jsonb := '[]'::jsonb;
  v_gaps jsonb := '[]'::jsonb;
  v_long_assigned jsonb := '{}'::jsonb;
  v_assign_all jsonb := '{}'::jsonb;
  d int; i int;
  v_fecha date;
  v_day_orig jsonb;
  v_remaining jsonb;
  v_assign_day jsonb;
  v_min_ini int; v_max_fin int;
  v_peak_hour int; v_peak_count int;
  v_floor int;
  v_best_id text; v_best_gain numeric; v_best_ini int; v_best_fin int;
  v_iter int;
  v_run_start int; v_run_end int; v_run_len int; v_cur_start int; v_cur_len int; h int;
  r_a record; r_c record;
  v_ini_ts timestamp; v_fin_ts timestamp; v_dur numeric; v_found boolean;
  v_seat_is_long boolean; v_seat_motivo text; v_seat_capa int;
  v_attempt int; v_allow_long_repeat boolean; v_relaxed_long boolean;
  v_n_solapa int; v_n_12h int; v_n_contrato int; v_n_jornada int; v_n_gap int; v_n_descanso int;
begin
  if not exists (select 1 from public.locations l where l.id = p_location and l.active) then
    return;
  end if;

  select coalesce(bp.max_daily_minutes_plan, bp.max_daily_minutes, 540)/60.0,
         coalesce(bp.min_shift_minutes,180)/60.0,
         coalesce(bp.weekly_rest_minutes,2160),
         coalesce(bp.min_rest_between_shifts_minutes,720),
         coalesce(bp.split_min_gap_minutes,90),
         coalesce(bp.contract_tolerance_pct,0)
    into v_max_h, v_min_h, v_rest_min, v_rest_12h, v_split_gap, v_tol_pct
  from public.break_policy bp
  where bp.account_id=p_account and (bp.location_id=p_location or bp.location_id is null)
  order by bp.location_id nulls last limit 1;
  v_max_h:=coalesce(v_max_h,9); v_min_h:=coalesce(v_min_h,3);
  v_rest_min:=coalesce(v_rest_min,2160); v_rest_12h:=coalesce(v_rest_12h,720);
  v_split_gap:=coalesce(v_split_gap,90); v_tol_pct:=coalesce(v_tol_pct,0);

  select coalesce(tlm.peak_weekday,0), coalesce(tlm.peak_weekend,0),
         coalesce(tlm.pre_open_minutes,0), coalesce(tlm.post_close_minutes,0)
    into v_peak_wd, v_peak_we, v_pre_open, v_post_close
  from public.team_labor_model tlm
  where tlm.account_id=p_account and tlm.role_kind=p_role and tlm.active
    and (tlm.location_id=p_location or tlm.location_id is null)
  order by tlm.location_id nulls last limit 1;
  v_peak_wd:=coalesce(v_peak_wd,0); v_peak_we:=coalesce(v_peak_we,0);
  v_pre_open:=coalesce(v_pre_open,0); v_post_close:=coalesce(v_post_close,0);

  select coalesce(jsonb_object_agg(r.fecha::text||'|'||r.hora::text, r.required_exact),'{}'::jsonb)
    into v_dem
  from public.team_labor_requirement(p_account,p_location,p_week_start) r
  where r.role_kind=p_role and r.required_exact > 0
    and r.hora in (
      select s.hour from public.sales_hourly_agg s
      where s.location_id=p_location and s.day > now() - interval '90 days'
      group by s.hour
      having 100.0*count(distinct s.day)
             / nullif((select count(distinct s2.day) from public.sales_hourly_agg s2
                        where s2.location_id=p_location
                          and s2.day > now() - interval '90 days'),0) >= p_min_pct_dias);

  select coalesce(jsonb_object_agg(k.tid, k.uso), '{}'::jsonb) into v_uso
  from (
    select k.tid, count(distinct s.week_start) as uso
    from public.schedules s
    cross join lateral jsonb_object_keys(s.cells) as k(tid)
    where s.location_id = p_location
      and s.week_start >= (p_week_start - interval '90 days')::date
      and s.week_start < p_week_start
    group by k.tid
  ) k;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', st.id::text,
      'kind', st.kind,
      'ini_min', (extract(hour from st.start_time)::int*60 + extract(minute from st.start_time)::int),
      'fin_min', case when st.end_time <= st.start_time
                      then (extract(hour from st.end_time)::int*60 + extract(minute from st.end_time)::int) + 1440
                      else (extract(hour from st.end_time)::int*60 + extract(minute from st.end_time)::int) end,
      'cov_mon', st.coverage_mon, 'cov_tue', st.coverage_tue, 'cov_wed', st.coverage_wed,
      'cov_thu', st.coverage_thu, 'cov_fri', st.coverage_fri, 'cov_sat', st.coverage_sat, 'cov_sun', st.coverage_sun,
      'uso', coalesce((v_uso->>st.id::text)::int, 0)
    ) order by st.start_time), '[]'::jsonb)
  into v_templates
  from public.shift_templates st
  where st.location_id = p_location and st.active;

  select count(*) into v_n_emp
  from public.employees e
  where e.account_id=p_account and e.active
    and (e.location_id=p_location
         or (e.assigned_locations is not null
             and to_jsonb(e.assigned_locations) @> to_jsonb(p_location::text)));
  v_n_emp := greatest(coalesce(v_n_emp,0), 1);

  for d in 0..6 loop
    select coalesce(sum(t.v::numeric),0) into v_tmp
    from jsonb_each_text(v_dem) t(k,v)
    where split_part(t.k,'|',1) = (p_week_start + d)::text;
    v_day_total[d+1] := coalesce(v_tmp,0);
  end loop;

  select (t->>'id')::uuid, ((t->>'fin_min')::int-(t->>'ini_min')::int)/60.0
    into v_long_tpl_id, v_long_dur
  from jsonb_array_elements(v_templates) t
  where t->>'kind'='demanda'
  order by ((t->>'fin_min')::int-(t->>'ini_min')::int) desc
  limit 1;

  if v_long_tpl_id is not null then
    select array_agg(x.d order by x.tot desc, x.d asc) into v_long_days
    from (
      select gs.d, v_day_total[gs.d+1] as tot
      from generate_series(0,6) gs(d)
      where v_day_total[gs.d+1] > 0
      order by v_day_total[gs.d+1] desc, gs.d asc
      limit v_n_emp
    ) x(d,tot);
  end if;
  v_long_days := coalesce(v_long_days, array[]::int[]);

  select array_agg(x.d order by x.tot desc, x.d asc) into v_day_order
  from (select gs.d, v_day_total[gs.d+1] as tot from generate_series(0,6) gs(d)) x(d,tot);

  v_week_idx := (p_week_start - date '2024-01-01')::int / 7;

  for d in 0..6 loop
    v_fecha := p_week_start + d;

    select coalesce(jsonb_object_agg(t.k2, t.v), '{}'::jsonb) into v_day_orig
    from (
      select split_part(t.k,'|',2) as k2, t.v
      from jsonb_each_text(v_dem) t(k,v)
      where split_part(t.k,'|',1) = v_fecha::text
    ) t;
    v_remaining := v_day_orig;
    v_assign_day := '[]'::jsonb;

    -- kind='forzado': se abre siempre que coverage_<dia> > 0 (parámetro 3).
    for r_a in
      select t->>'id' as id, (t->>'ini_min')::int as ini_min, (t->>'fin_min')::int as fin_min,
             (case d
                when 0 then (t->>'cov_mon')::int when 1 then (t->>'cov_tue')::int
                when 2 then (t->>'cov_wed')::int when 3 then (t->>'cov_thu')::int
                when 4 then (t->>'cov_fri')::int when 5 then (t->>'cov_sat')::int
                else (t->>'cov_sun')::int end) as necesita
      from jsonb_array_elements(v_templates) t
      where t->>'kind' = 'forzado'
    loop
      if r_a.necesita > 0 then
        for v_iter in 1..r_a.necesita loop
          v_assign_day := v_assign_day || jsonb_build_object(
            'tpl_id', r_a.id, 'kind', 'forzado', 'ini_min', r_a.ini_min, 'fin_min', r_a.fin_min);
          select coalesce(jsonb_object_agg(k.k, greatest(0, k.v::numeric -
                   case when r_a.ini_min < (k.k::int+1)*60 and least(r_a.fin_min,1440) > k.k::int*60
                        then 1 else 0 end)), '{}'::jsonb)
            into v_remaining
          from jsonb_each_text(v_remaining) k(k,v);
        end loop;
      end if;
    end loop;

    -- kind='no_productivo': se coloca, suma horas, NO descuenta demanda (parámetro 4).
    for r_a in
      select t->>'id' as id, (t->>'ini_min')::int as ini_min, (t->>'fin_min')::int as fin_min,
             (case d
                when 0 then (t->>'cov_mon')::int when 1 then (t->>'cov_tue')::int
                when 2 then (t->>'cov_wed')::int when 3 then (t->>'cov_thu')::int
                when 4 then (t->>'cov_fri')::int when 5 then (t->>'cov_sat')::int
                else (t->>'cov_sun')::int end) as necesita
      from jsonb_array_elements(v_templates) t
      where t->>'kind' = 'no_productivo'
    loop
      if r_a.necesita > 0 then
        for v_iter in 1..r_a.necesita loop
          v_assign_day := v_assign_day || jsonb_build_object(
            'tpl_id', r_a.id, 'kind', 'no_productivo', 'ini_min', r_a.ini_min, 'fin_min', r_a.fin_min);
        end loop;
      end if;
    end loop;

    -- MOVIDO (3ª parte, §8.3 vuelta 2): el turno largo del día pico se
    -- garantiza ANTES del greedy de demanda, no después. Con el greedy ya
    -- puntuando por neto (ver más abajo) puede dejar de necesitar nunca la
    -- plantilla larga para cubrir su hueco de demanda — si el garantizado
    -- corriera después, chocaría contra un día ya lleno de turnos cortos y
    -- se convertiría en hueco. Reservando primero, el greedy cubre lo que
    -- quede alrededor y la persona asignada al largo tiene prioridad real
    -- de horario ese día (los asientos se procesan en orden de aparición
    -- en fase 2).
    if v_long_tpl_id is not null and d = any(v_long_days) then
      if not exists (
        select 1 from jsonb_array_elements(v_assign_day) a
        where a->>'tpl_id' = v_long_tpl_id::text
      ) then
        select (t->>'ini_min')::int, (t->>'fin_min')::int into v_best_ini, v_best_fin
        from jsonb_array_elements(v_templates) t
        where t->>'id' = v_long_tpl_id::text limit 1;
        v_assign_day := v_assign_day || jsonb_build_object(
          'tpl_id', v_long_tpl_id::text, 'kind', 'demanda_largo', 'ini_min', v_best_ini, 'fin_min', v_best_fin);
        select coalesce(jsonb_object_agg(k.k, greatest(0, k.v::numeric -
                 case when v_best_ini < (k.k::int+1)*60 and least(v_best_fin,1440) > k.k::int*60
                      then 1 else 0 end)), '{}'::jsonb)
          into v_remaining
        from jsonb_each_text(v_remaining) k(k,v);
      end if;
    end if;

    -- kind='demanda': greedy set-cover. CAMBIO 8.3: `neto = 2*gain - dur_h`
    -- en vez de `gain` bruto (evita que el turno más largo gane siempre por
    -- construcción). `having gain>0` + `uso desc` PRIMERO evita que ese
    -- mismo cambio resucite plantillas duplicadas sin uso real: entre dos
    -- que cubren lo mismo, la más corta siempre da mejor neto — sin mirar
    -- el uso histórico antes, "Mañana1" (duplicada, uso=0) le ganaba a la
    -- "Mañana" real. Encontrado y corregido en la validación por MCP de
    -- esta misma migración, no en producción.
    for v_iter in 1..20 loop
      select x.id, x.gain, x.ini_min, x.fin_min
        into v_best_id, v_best_gain, v_best_ini, v_best_fin
      from (
        select t->>'id' as id,
               sum(case when (t->>'ini_min')::int < (h.hour+1)*60
                         and least((t->>'fin_min')::int,1440) > h.hour*60
                         and coalesce((v_remaining->>h.hour::text)::numeric,0) > 0
                        then 1 else 0 end) as gain,
               coalesce((t->>'uso')::int,0) as uso,
               ((t->>'fin_min')::int-(t->>'ini_min')::int)/60.0 as dur_h,
               (t->>'ini_min')::int as ini_min,
               (t->>'fin_min')::int as fin_min
        from jsonb_array_elements(v_templates) t
        cross join generate_series(0,23) h(hour)
        where t->>'kind' = 'demanda'
        group by t->>'id', t->>'uso', t->>'ini_min', t->>'fin_min'
        having sum(case when (t->>'ini_min')::int < (h.hour+1)*60
                          and least((t->>'fin_min')::int,1440) > h.hour*60
                          and coalesce((v_remaining->>h.hour::text)::numeric,0) > 0
                         then 1 else 0 end) > 0
      ) x
      order by x.uso desc, (2*x.gain - x.dur_h) desc, x.dur_h asc, x.ini_min asc
      limit 1;

      exit when v_best_id is null or coalesce(v_best_gain,0) <= 0;

      v_assign_day := v_assign_day || jsonb_build_object(
        'tpl_id', v_best_id, 'kind', 'demanda', 'ini_min', v_best_ini, 'fin_min', v_best_fin);
      select coalesce(jsonb_object_agg(k.k, greatest(0, k.v::numeric -
               case when v_best_ini < (k.k::int+1)*60 and least(v_best_fin,1440) > k.k::int*60
                    then 1 else 0 end)), '{}'::jsonb)
        into v_remaining
      from jsonb_each_text(v_remaining) k(k,v);
    end loop;

    -- Dotación mínima en el pico (parámetro 1). 0/NULL = sin efecto.
    v_floor := case when d in (5,6) then v_peak_we else v_peak_wd end;
    if coalesce(v_floor,0) > 0 then
      select k.k::int into v_peak_hour
      from jsonb_each_text(v_day_orig) k(k,v)
      order by k.v::numeric desc, k.k::int asc
      limit 1;
      if v_peak_hour is not null then
        select count(*) into v_peak_count
        from jsonb_array_elements(v_assign_day) a
        where (a->>'ini_min')::int < (v_peak_hour+1)*60
          and least((a->>'fin_min')::int,1440) > v_peak_hour*60;
        v_iter := 0;
        while coalesce(v_peak_count,0) < v_floor and v_iter < 6 loop
          v_iter := v_iter + 1;
          select t->>'id', (t->>'ini_min')::int, (t->>'fin_min')::int
            into v_best_id, v_best_ini, v_best_fin
          from jsonb_array_elements(v_templates) t
          where t->>'kind' = 'demanda'
            and (t->>'ini_min')::int < (v_peak_hour+1)*60
            and least((t->>'fin_min')::int,1440) > v_peak_hour*60
          order by coalesce((t->>'uso')::int,0) desc,
                   ((t->>'fin_min')::int-(t->>'ini_min')::int) asc
          limit 1;
          exit when v_best_id is null;
          v_assign_day := v_assign_day || jsonb_build_object(
            'tpl_id', v_best_id, 'kind', 'demanda_pico', 'ini_min', v_best_ini, 'fin_min', v_best_fin);
          select coalesce(jsonb_object_agg(k.k, greatest(0, k.v::numeric -
                   case when v_best_ini < (k.k::int+1)*60 and least(v_best_fin,1440) > k.k::int*60
                        then 1 else 0 end)), '{}'::jsonb)
            into v_remaining
          from jsonb_each_text(v_remaining) k(k,v);
          v_peak_count := v_peak_count + 1;
        end loop;
      end if;
    end if;

    -- Refuerzo excepcional: como mucho UN bloque dinámico, cuadrado a horas
    -- completas (la demanda ya viene por hora). Se descarta si no llega a
    -- min_shift_minutes — nunca un turno suelto por debajo del mínimo.
    v_run_start := null; v_run_end := null; v_cur_start := null; v_cur_len := 0; v_run_len := 0;
    for h in 0..23 loop
      if coalesce((v_remaining->>h::text)::numeric,0) > 0 then
        if v_cur_start is null then v_cur_start := h; v_cur_len := 1;
        else v_cur_len := v_cur_len + 1; end if;
        if v_cur_len > v_run_len then
          v_run_len := v_cur_len; v_run_start := v_cur_start; v_run_end := h+1;
        end if;
      else
        v_cur_start := null; v_cur_len := 0;
      end if;
    end loop;

    if v_run_start is not null and (v_run_end - v_run_start) >= v_min_h then
      v_assign_day := v_assign_day || jsonb_build_object(
        'tpl_id', null, 'kind', 'refuerzo', 'ini_min', v_run_start*60, 'fin_min', v_run_end*60);
      select coalesce(jsonb_object_agg(k.k, greatest(0, k.v::numeric -
               case when v_run_start*60 < (k.k::int+1)*60 and v_run_end*60 > k.k::int*60
                    then 1 else 0 end)), '{}'::jsonb)
        into v_remaining
      from jsonb_each_text(v_remaining) k(k,v);
    end if;

    -- Lo que siga con remaining > 0 (incluida la racha descartada por corta)
    -- se declara hueco directo: nunca se intenta cubrir con nadie.
    for r_a in
      select k.k::int as hora
      from jsonb_each_text(v_remaining) k(k,v)
      where k.v::numeric > 0
      order by k.k::int
    loop
      v_gaps := v_gaps || jsonb_build_object(
        'f', v_fecha, 'ini', r_a.hora*60, 'fin', (r_a.hora+1)*60, 'tpl', null,
        'motivo', 'Demanda residual (menos de ' || round(v_min_h,1) || ' h) sin cubrir — no se abre un turno suelto por debajo del mínimo');
    end loop;

    -- Márgenes de apertura/cierre (parámetro 4). 0/NULL = sin efecto.
    if jsonb_array_length(v_assign_day) > 0 then
      select min((a->>'ini_min')::int), max((a->>'fin_min')::int)
        into v_min_ini, v_max_fin
      from jsonb_array_elements(v_assign_day) a;
      if coalesce(v_pre_open,0) > 0 then
        select coalesce(jsonb_agg(
                 case when (a->>'ini_min')::int = v_min_ini
                      then jsonb_set(a, '{ini_min}', to_jsonb(greatest(0,(a->>'ini_min')::int - v_pre_open)))
                      else a end),
               '[]'::jsonb)
          into v_assign_day
        from jsonb_array_elements(v_assign_day) a;
      end if;
      if coalesce(v_post_close,0) > 0 then
        select coalesce(jsonb_agg(
                 case when (a->>'fin_min')::int = v_max_fin
                      then jsonb_set(a, '{fin_min}', to_jsonb((a->>'fin_min')::int + v_post_close))
                      else a end),
               '[]'::jsonb)
          into v_assign_day
        from jsonb_array_elements(v_assign_day) a;
      end if;
    end if;

    v_assign_all := jsonb_set(v_assign_all, array[d::text], v_assign_day);
  end loop;

  for i in 1..7 loop
    d := v_day_order[i];
    v_fecha := p_week_start + d;
    v_assign_day := coalesce(v_assign_all -> d::text, '[]'::jsonb);

    for r_a in
      select a->>'tpl_id' as tpl_id, a->>'kind' as kind,
             (a->>'ini_min')::int as ini_min, (a->>'fin_min')::int as fin_min
      from jsonb_array_elements(v_assign_day) a
    loop
      v_ini_ts := v_fecha::timestamp + make_interval(mins => r_a.ini_min);
      v_fin_ts := v_fecha::timestamp + make_interval(mins => r_a.fin_min);
      v_dur := (r_a.fin_min - r_a.ini_min) / 60.0;
      v_seat_is_long := (v_long_tpl_id is not null and r_a.tpl_id = v_long_tpl_id::text);
      v_found := false;
      v_relaxed_long := false;
      v_allow_long_repeat := false;

      for v_attempt in 0..1 loop
        if v_attempt = 1 then
          exit when not v_seat_is_long or v_found;
          v_allow_long_repeat := true;
        end if;

        for r_c in
          with cand as (
            select e.id, e.name, coalesce(e.contracted_hours_week,40) ctr,
                   coalesce((v_horas->>e.id::text)::numeric,0) ya,
                   (select coalesce(sum(extract(epoch from ((t->>1)::timestamp-(t->>0)::timestamp))/3600),0)
                      from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                     where (t->>0)::timestamp::date = v_fecha) h_dia,
                   (select count(*) from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                     where (t->>0)::timestamp::date = v_fecha) n_dia,
                   (select count(distinct (t->>0)::timestamp::date)
                      from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t) as dias_trabajados,
                   (select min(greatest(extract(epoch from (v_ini_ts-(t->>1)::timestamp))/60,
                                        extract(epoch from ((t->>0)::timestamp-v_fin_ts))/60))
                      from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                     where (t->>0)::timestamp::date = v_fecha) gap_min,
                   exists (select 1 from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                            where (t->>0)::timestamp < v_fin_ts and (t->>1)::timestamp > v_ini_ts) solapa,
                   exists (select 1 from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                            where (t->>0)::timestamp::date <> v_fecha
                              and ( ((t->>1)::timestamp <= v_ini_ts
                                     and v_ini_ts < (t->>1)::timestamp + make_interval(mins=>v_rest_12h))
                                 or (v_fin_ts <= (t->>0)::timestamp
                                     and (t->>0)::timestamp < v_fin_ts + make_interval(mins=>v_rest_12h)) )
                   ) viola_12h,
                   row_number() over (order by e.name) as rnk,
                   coalesce((v_long_assigned->>e.id::text)::boolean,false) as had_long
            from public.employees e
            where e.account_id=p_account and e.active
              and (e.location_id=p_location
                   or (e.assigned_locations is not null
                       and to_jsonb(e.assigned_locations) @> to_jsonb(p_location::text)))
              and not exists (select 1 from public.vacations v
                              where v.employee_id=e.id and v.status='aprobada'
                                and v_fecha between v.start_date and v.end_date)
          ),
          cand2 as (
            select c.*,
                   (d = ((c.rnk - 1 + v_week_idx) % 7)) as is_target_off,
                   (array_length(v_long_days,1) > 0
                    and d = v_long_days[1 + ((c.rnk - 1 + v_week_idx) % array_length(v_long_days,1))]) as is_target_long
            from cand c
          )
          select c.id, c.name, c.ctr, c.ya, c.n_dia from cand2 c
          where not c.solapa and not c.viola_12h
            and c.ya + v_dur <= c.ctr * (1 + v_tol_pct/100.0)
            and c.h_dia + v_dur <= v_max_h
            and (c.n_dia = 0 or c.gap_min = 0 or c.gap_min >= v_split_gap)
            and (not v_seat_is_long or not c.had_long or v_allow_long_repeat)
            and public.has_weekly_rest(coalesce(v_turnos->c.id::text,'[]'::jsonb),
                  v_ini_ts, v_fin_ts, p_week_start, v_rest_min)
          order by
            (v_seat_is_long and c.is_target_long) desc,
            (v_seat_is_long and c.had_long) asc,
            c.dias_trabajados asc,
            c.is_target_off asc,
            (c.n_dia > 0) desc,
            (c.ctr - c.ya) desc,
            c.name
          limit 1
        loop
          v_relaxed_long := (v_attempt = 1);
          v_seat_motivo := case
            when v_relaxed_long then 'Segundo turno largo — no había alternativa'
            else case r_a.kind
              when 'forzado' then 'Franja forzada'
              when 'no_productivo' then 'Bloque fijo no productivo'
              when 'demanda_largo' then 'Turno largo · día de mayor demanda'
              when 'demanda_pico' then 'Dotación mínima en el pico'
              when 'refuerzo' then 'Refuerzo excepcional · demanda residual'
              else 'Demanda prevista'
            end
          end;
          v_seat_capa := case r_a.kind
            when 'demanda_largo' then 2 when 'demanda_pico' then 3
            when 'refuerzo' then 4 else 1 end;
          v_plan := v_plan || jsonb_build_object(
            'f', v_fecha, 'ini', r_a.ini_min, 'fin', r_a.fin_min, 'tpl', r_a.tpl_id,
            'capa', v_seat_capa, 'emp', r_c.id, 'nom', r_c.name, 'motivo', v_seat_motivo);
          v_horas := jsonb_set(v_horas, array[r_c.id::text], to_jsonb(r_c.ya + v_dur));
          v_turnos := jsonb_set(v_turnos, array[r_c.id::text],
                       coalesce(v_turnos->r_c.id::text,'[]'::jsonb)
                       || jsonb_build_array(jsonb_build_array(
                            to_char(v_ini_ts,'YYYY-MM-DD"T"HH24:MI:SS'),
                            to_char(v_fin_ts,'YYYY-MM-DD"T"HH24:MI:SS'))));
          if v_seat_is_long then
            v_long_assigned := jsonb_set(v_long_assigned, array[r_c.id::text], to_jsonb(true));
          end if;
          v_found := true;
        end loop;

        exit when v_found;
      end loop;

      if not v_found then
        select
          count(*) filter (where solapa),
          count(*) filter (where viola_12h),
          count(*) filter (where ya + v_dur > ctr * (1 + v_tol_pct/100.0)),
          count(*) filter (where h_dia + v_dur > v_max_h),
          count(*) filter (where not (n_dia = 0 or gap_min = 0 or gap_min >= v_split_gap)),
          count(*) filter (where not public.has_weekly_rest(coalesce(v_turnos->id::text,'[]'::jsonb),
                                    v_ini_ts, v_fin_ts, p_week_start, v_rest_min))
          into v_n_solapa, v_n_12h, v_n_contrato, v_n_jornada, v_n_gap, v_n_descanso
        from (
          select e.id,
                 coalesce(e.contracted_hours_week,40) ctr,
                 coalesce((v_horas->>e.id::text)::numeric,0) ya,
                 (select coalesce(sum(extract(epoch from ((t->>1)::timestamp-(t->>0)::timestamp))/3600),0)
                    from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                   where (t->>0)::timestamp::date = v_fecha) h_dia,
                 (select count(*) from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                   where (t->>0)::timestamp::date = v_fecha) n_dia,
                 (select min(greatest(extract(epoch from (v_ini_ts-(t->>1)::timestamp))/60,
                                      extract(epoch from ((t->>0)::timestamp-v_fin_ts))/60))
                    from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                   where (t->>0)::timestamp::date = v_fecha) gap_min,
                 exists (select 1 from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                          where (t->>0)::timestamp < v_fin_ts and (t->>1)::timestamp > v_ini_ts) solapa,
                 exists (select 1 from jsonb_array_elements(coalesce(v_turnos->e.id::text,'[]'::jsonb)) t
                          where (t->>0)::timestamp::date <> v_fecha
                            and ( ((t->>1)::timestamp <= v_ini_ts
                                   and v_ini_ts < (t->>1)::timestamp + make_interval(mins=>v_rest_12h))
                               or (v_fin_ts <= (t->>0)::timestamp
                                   and (t->>0)::timestamp < v_fin_ts + make_interval(mins=>v_rest_12h)) )
                 ) viola_12h
          from public.employees e
          where e.account_id=p_account and e.active
            and (e.location_id=p_location
                 or (e.assigned_locations is not null
                     and to_jsonb(e.assigned_locations) @> to_jsonb(p_location::text)))
            and not exists (select 1 from public.vacations v
                            where v.employee_id=e.id and v.status='aprobada'
                              and v_fecha between v.start_date and v.end_date)
        ) c;

        v_seat_motivo := (
          select coalesce(nullif(string_agg(part, ' · '), ''), 'no hay empleados activos en este local')
          from (
            select 'tope de horas contratadas (' || v_n_contrato || ')' as part where coalesce(v_n_contrato,0) > 0
            union all select 'descanso de 12h (' || v_n_12h || ')' where coalesce(v_n_12h,0) > 0
            union all select 'descanso semanal (' || v_n_descanso || ')' where coalesce(v_n_descanso,0) > 0
            union all select 'jornada máxima diaria (' || v_n_jornada || ')' where coalesce(v_n_jornada,0) > 0
            union all select 'ya tienen turno solapado (' || v_n_solapa || ')' where coalesce(v_n_solapa,0) > 0
            union all select 'hueco de turno partido insuficiente (' || v_n_gap || ')' where coalesce(v_n_gap,0) > 0
          ) parts
        );
        v_gaps := v_gaps || jsonb_build_object(
          'f', v_fecha, 'ini', r_a.ini_min, 'fin', r_a.fin_min, 'tpl', r_a.tpl_id,
          'motivo', 'SIN CUBRIR — ' || v_seat_motivo);
      end if;
    end loop;

  end loop;

  return query
  select (x->>'f')::date,
         extract(isodow from (x->>'f')::date)::int - 1,
         (x->>'tpl')::uuid,
         to_char((x->>'f')::date::timestamp + make_interval(mins => (x->>'ini')::int), 'HH24:MI'),
         to_char((x->>'f')::date::timestamp + make_interval(mins => (x->>'fin')::int), 'HH24:MI'),
         (((x->>'fin')::int - (x->>'ini')::int)/60.0)::numeric,
         (x->>'capa')::int,
         (x->>'emp')::uuid, x->>'nom', false, x->>'motivo'
  from jsonb_array_elements(v_plan) x
  union all
  select (x->>'f')::date,
         extract(isodow from (x->>'f')::date)::int - 1,
         (x->>'tpl')::uuid,
         to_char((x->>'f')::date::timestamp + make_interval(mins => (x->>'ini')::int), 'HH24:MI'),
         to_char((x->>'f')::date::timestamp + make_interval(mins => (x->>'fin')::int), 'HH24:MI'),
         (((x->>'fin')::int - (x->>'ini')::int)/60.0)::numeric,
         null::int,
         null::uuid, null::text, true, x->>'motivo'
  from jsonb_array_elements(v_gaps) x
  order by 1, 4;
end
$$;


--
-- Name: FUNCTION generate_week_schedule(p_account uuid, p_location uuid, p_week_start date, p_role text, p_min_pct_dias numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_week_schedule(p_account uuid, p_location uuid, p_week_start date, p_role text, p_min_pct_dias numeric) IS 'ENCARGO F10 mix de turnos, 09/08/2026 (3ª parte). Greedy de demanda ordena por neto (2*gain-dur_h) dentro de cada nivel de uso histórico (uso desc primero, evita resucitar duplicadas). Turno largo garantizado del día pico se reserva ANTES del greedy, no después. Validado por MCP: 3 corridos/semana (1 por persona, real=3), 0 avisos de segundo turno largo, huecos y días trabajados sin empeorar. Horas totales bajan a ~97,5 (por debajo del suelo de 115 que pedía el encargo) — declarado sin resolver, pendiente de criterio de negocio de Julio.';


--
-- Name: get_account_discount(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_account_discount(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF NOT current_user_is_admin() THEN
    RAISE EXCEPTION 'Acceso denegado: solo platform admins.';
  END IF;

  SELECT to_jsonb(t) INTO v
  FROM (
    SELECT id, discount_type, value, note, valid_until, active, created_at
    FROM account_discount
    WHERE account_id = p_account_id AND active
    ORDER BY created_at DESC
    LIMIT 1
  ) t;

  RETURN v;  -- null si no hay descuento activo
END;
$$;


--
-- Name: get_auth_user_id_by_email(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_auth_user_id_by_email(p_email text, p_created_by uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NOT _user_can_manage_admins(p_created_by) THEN
    RAISE EXCEPTION 'Acceso denegado: requiere el permiso "Gestionar admins".';
  END IF;
  SELECT id INTO v_id FROM auth.users WHERE lower(email) = lower(p_email) LIMIT 1;
  RETURN v_id;  -- NULL si no existe
END;
$$;


--
-- Name: get_effective_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_permissions(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_profile_id uuid;
  v_user_role text;
  v_permissions jsonb;
BEGIN
  -- Step 1: Resolver el user_profile del caller en la cuenta dada.
  SELECT up.id, up.role
    INTO v_user_profile_id, v_user_role
  FROM user_profiles up
  WHERE up.user_id = auth.uid()
    AND up.account_id = p_account_id
    AND up.active = true
    AND up.suspended_at IS NULL
  LIMIT 1;

  IF v_user_profile_id IS NULL THEN
    RETURN '{}'::jsonb;
  END IF;

  -- Admin de cuenta: marcador de acceso total.
  IF v_user_role = 'admin' THEN
    RETURN jsonb_build_object('__full_access', true);
  END IF;

  -- Step 2: Devolver la fila de manager_permissions (los checkboxes que el
  --   admin configura por persona) como jsonb. Se excluyen las columnas meta
  --   (user_profile_id, created_at, updated_at) para dejar solo los booleanos.
  SELECT to_jsonb(mp) - 'user_profile_id' - 'created_at' - 'updated_at'
    INTO v_permissions
  FROM manager_permissions mp
  WHERE mp.user_profile_id = v_user_profile_id;

  -- Sin fila → {} (deny total, fail-closed). El admin aún no le ha
  --   configurado permisos a este manager.
  RETURN COALESCE(v_permissions, '{}'::jsonb);
END;
$$;


--
-- Name: get_launch_phase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_launch_phase(p_account_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v text;
begin
  if not belongs_to_account(p_account_id) then raise exception 'no autorizado'; end if;
  select launch_phase into v from social_config where account_id = p_account_id;
  return coalesce(v, 'apetito');
end $$;


--
-- Name: get_n2_config(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_n2_config(p_account_id uuid) RETURNS TABLE(n2_enabled boolean, n2_daily_cap integer, n2_mood_ratio integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not belongs_to_account(p_account_id) then raise exception 'no autorizado'; end if;
  return query select c.n2_enabled, c.n2_daily_cap, c.n2_mood_ratio
    from social_config c where c.account_id = p_account_id;
end $$;


--
-- Name: get_promo_push_job_status(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_promo_push_job_status(p_secret text, p_job_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_status text;
begin
  select account_id into v_acc from offers_agent_config
   where push_agent_secret = p_secret and push_agent_secret is not null;
  if v_acc is null then raise exception 'secreto inválido'; end if;
  select status into v_status from promo_push_job
   where id = p_job_id and account_id = v_acc;
  return v_status;
end $$;


--
-- Name: get_sale_ticket(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sale_ticket(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc uuid;
  v_res jsonb;
BEGIN
  SELECT account_id INTO v_acc FROM sale WHERE id = p_sale_id;
  IF v_acc IS NULL THEN RETURN NULL; END IF;
  IF NOT (current_user_is_admin() OR current_user_is_admin_or_manager_of(v_acc)) THEN
    RAISE EXCEPTION 'get_sale_ticket: sin acceso a la venta';
  END IF;

  WITH s AS (SELECT * FROM sale WHERE id = p_sale_id),
  lineas AS (
    SELECT sl.id, sl.product_name, sl.quantity, sl.unit_price, sl.line_total,
           sl.computed_cost, sl.line_type, sl.parent_sale_line_id,
           sl.discount_label, sl.original_unit_price, sl.map_needs_review,
           sl.unmapped_reason, sl.menu_item_id, sl.ignored_at,
           mi.name AS menu_item_name
    FROM sale_line sl
    LEFT JOIN menu_item mi ON mi.id = sl.menu_item_id
    WHERE sl.sale_id = p_sale_id
  ),
  tot AS (
    SELECT coalesce(sum(computed_cost) FILTER (WHERE coalesce(line_type,'product')='product'),0) AS coste,
           count(*) FILTER (WHERE coalesce(line_type,'product')='product' AND computed_cost IS NULL) AS lineas_sin_coste
    FROM lineas
  )
  SELECT jsonb_build_object(
    'sale', (
      SELECT jsonb_build_object(
        'id', s.id, 'sold_at', s.sold_at,
        'brand', coalesce(b.name, s.external_brand_text),
        'channel', coalesce(sc.name, initcap(s.external_channel_text)),
        'location', l.name,
        'order_status', s.order_status, 'status', s.status, 'source', s.source,
        'ticket_code', coalesce(nullif(s.platform_order_code,''), nullif(s.pos_short_code,''), s.external_ref),
        'total', s.total, 'taxable_base', s.taxable_base, 'tax', s.tax,
        'discount_amount', s.discount_amount, 'service_type', s.service_type,
        'cost', (SELECT round(coste,2) FROM tot),
        'lines_without_cost', (SELECT lineas_sin_coste FROM tot),
        'cost_complete', (SELECT lineas_sin_coste = 0 FROM tot),
        'margin_eur', round(coalesce(s.taxable_base, s.total, 0) - (SELECT coste FROM tot), 2),
        'margin_pct', CASE WHEN coalesce(s.taxable_base, s.total, 0) > 0
          THEN round(((coalesce(s.taxable_base, s.total,0) - (SELECT coste FROM tot))
                      / coalesce(s.taxable_base, s.total)) * 100, 1) ELSE null END)
      FROM s
      LEFT JOIN brand b ON b.id = s.brand_id
      LEFT JOIN sales_channel sc ON sc.id = s.channel_id
      LEFT JOIN locations l ON l.id = s.location_id),
    'lines', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', ln.id,
        'product_name', coalesce(ln.menu_item_name, ln.product_name),
        'raw_name', ln.product_name,
        'quantity', ln.quantity,
        'unit_price', ln.unit_price,
        'line_total', ln.line_total,
        'unit_cost', CASE WHEN ln.quantity > 0 THEN round(ln.computed_cost / ln.quantity, 4) ELSE null END,
        'computed_cost', ln.computed_cost,
        'contribution', CASE WHEN ln.computed_cost IS NOT NULL
                             THEN round(coalesce(ln.line_total,0) - ln.computed_cost, 2) ELSE null END,
        'margin_pct', CASE WHEN ln.computed_cost IS NOT NULL AND coalesce(ln.line_total,0) > 0
                           THEN round(((ln.line_total - ln.computed_cost) / ln.line_total) * 100, 1) ELSE null END,
        'line_type', coalesce(ln.line_type,'product'),
        'parent_id', ln.parent_sale_line_id,
        'discount_label', ln.discount_label,
        'original_unit_price', ln.original_unit_price,
        'needs_review', coalesce(ln.map_needs_review,false),
        'unmapped_reason', ln.unmapped_reason,
        'ignored', ln.ignored_at IS NOT NULL,
        'warehouse', null, 'lots', null
      ) ORDER BY ln.parent_sale_line_id NULLS FIRST, ln.product_name)
      FROM lineas ln), '[]'::jsonb)
  ) INTO v_res;

  RETURN v_res;
END;
$$;


--
-- Name: goods_receipt_cost_warnings(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_receipt_cost_warnings(p_account_id uuid, p_receipt_id uuid) RETURNS TABLE(line_id uuid, recipe_item_id uuid, product_name text, unit_cost_per_base numeric, median_cost_per_base numeric, ratio numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c_threshold constant numeric := 1.8;
  c_min_recepciones constant int := 3;
begin
  if not belongs_to_account(p_account_id) then
    raise exception 'No autorizado para esta cuenta.';
  end if;

  return query
  with linea as (
    select grl.id as line_id, grl.recipe_item_id, ri.name as product_name,
           (grl.unit_cost::numeric * grl.qty_received::numeric / grl.qty_in_base::numeric) as unit_cost_per_base
    from goods_receipt_line grl
    join goods_receipt gr on gr.id = grl.goods_receipt_id
    join recipe_item ri on ri.id = grl.recipe_item_id
    where gr.id = p_receipt_id and gr.account_id = p_account_id
      and grl.unit_cost is not null and grl.unit_cost > 0
      and grl.qty_in_base is not null and grl.qty_in_base > 0
  ),
  historico as (
    select sm.recipe_item_id,
           percentile_cont(0.5) within group (order by sm.unit_cost::numeric) as mediana,
           count(*) as n
    from stock_movement sm
    where sm.account_id = p_account_id and sm.source_type = 'goods_receipt_line'
      and sm.movement_type = 'recepcion' and sm.unit_cost > 0
      and sm.source_id not in (select l.line_id from linea l)
    group by sm.recipe_item_id
  )
  select l.line_id, l.recipe_item_id, l.product_name, round(l.unit_cost_per_base, 6),
         round(h.mediana::numeric, 6), round((l.unit_cost_per_base / h.mediana)::numeric, 3)
  from linea l
  join historico h on h.recipe_item_id = l.recipe_item_id
  where h.n >= c_min_recepciones
    and (l.unit_cost_per_base > h.mediana * c_threshold or l.unit_cost_per_base < h.mediana / c_threshold);
end;
$$;


--
-- Name: goods_receipt_fractional_warnings(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_receipt_fractional_warnings(p_account_id uuid, p_receipt_id uuid) RETURNS TABLE(line_id uuid, recipe_item_id uuid, product_name text, qty_received numeric, format_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not belongs_to_account(p_account_id) then
    raise exception 'No autorizado para esta cuenta.';
  end if;

  return query
  select grl.id, grl.recipe_item_id, ri.name,
         grl.qty_received::numeric, f.name
  from goods_receipt_line grl
  join goods_receipt gr on gr.id = grl.goods_receipt_id
  join recipe_item ri on ri.id = grl.recipe_item_id
  join kitchen_unit ku on ku.id = ri.base_unit_id
  left join recipe_item_purchase_format f on f.id = grl.purchase_format_id
  where gr.id = p_receipt_id and gr.account_id = p_account_id
    and ku.dimension = 'unit'
    and grl.qty_received is not null
    and grl.qty_received <> round(grl.qty_received::numeric);
end;
$$;


--
-- Name: has_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_account_id uuid, p_permission_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_user_profile_id uuid;
  v_user_role text;
  v_value boolean;
BEGIN
  -- Step 1: Resolver el user_profile del caller en la cuenta dada.
  SELECT up.id, up.role
    INTO v_user_profile_id, v_user_role
  FROM user_profiles up
  WHERE up.user_id = auth.uid()
    AND up.account_id = p_account_id
    AND up.active = true
    AND up.suspended_at IS NULL
  LIMIT 1;

  IF v_user_profile_id IS NULL THEN
    RETURN public.current_user_is_admin();
  END IF;

  -- Admin de cuenta: todos los permisos.
  IF v_user_role = 'admin' THEN
    RETURN true;
  END IF;

  -- Step 2: Leer la columna concreta de manager_permissions (los checkboxes
  --   que el admin configura por persona). Única fuente de permisos del manager.
  BEGIN
    EXECUTE format(
      'SELECT %I FROM manager_permissions WHERE user_profile_id = $1',
      p_permission_key
    )
    INTO v_value
    USING v_user_profile_id;
  EXCEPTION
    WHEN undefined_column THEN
      v_value := NULL;  -- clave que no es columna → deny
    WHEN OTHERS THEN
      RAISE WARNING 'has_permission: error en columna %: %', p_permission_key, SQLERRM;
      v_value := NULL;
  END;

  -- Step 3: Si la columna tiene valor → ese valor. Si NULL (sin fila o sin
  --   valor) → DENY (fail-closed).
  RETURN COALESCE(v_value, false);
END;
$_$;


--
-- Name: FUNCTION has_permission(p_account_id uuid, p_permission_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_permission(p_account_id uuid, p_permission_key text) IS 'Resolución cascada de permisos (Decisión 1 B aprobada Julio CEO 18/05/2026): admin > legacy column > set jsonb > deny.';


--
-- Name: has_weekly_rest(jsonb, timestamp without time zone, timestamp without time zone, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_weekly_rest(p_turnos jsonb, p_new_ini timestamp without time zone, p_new_fin timestamp without time zone, p_week_start date, p_min_minutes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with ivs as (
    select (x->>0)::timestamp as s, (x->>1)::timestamp as e
    from jsonb_array_elements(coalesce(p_turnos,'[]'::jsonb)) x
    union all select p_new_ini, p_new_fin
  ),
  ord as (select s, e, lead(s) over (order by s) as next_s from ivs),
  gaps as (
    select extract(epoch from (next_s - e))/60.0 as m from ord where next_s is not null
    union all
    select extract(epoch from ((select min(s) from ivs) - p_week_start::timestamp))/60.0
    union all
    select extract(epoch from ((p_week_start + 7)::timestamp - (select max(e) from ivs)))/60.0
  )
  select coalesce(max(m), 999999) >= p_min_minutes from gaps;
$$;


--
-- Name: has_weekly_rest_36h(jsonb, timestamp without time zone, timestamp without time zone, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_weekly_rest_36h(p_turnos jsonb, p_new_ini timestamp without time zone, p_new_fin timestamp without time zone, p_week_start date) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with ivs as (
    select (x->>0)::timestamp as s, (x->>1)::timestamp as e
    from jsonb_array_elements(coalesce(p_turnos,'[]'::jsonb)) x
    union all
    select p_new_ini, p_new_fin
  ),
  ord as (
    select s, e, lead(s) over (order by s) as next_s from ivs
  ),
  gaps as (
    select extract(epoch from (next_s - e))/3600.0 as h
      from ord where next_s is not null
    union all
    select extract(epoch from ((select min(s) from ivs) - p_week_start::timestamp))/3600.0
    union all
    select extract(epoch from ((p_week_start + 7)::timestamp - (select max(e) from ivs)))/3600.0
  )
  select coalesce(max(h), 999) >= 36 from gaps;
$$;


--
-- Name: home_agentes_estado(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.home_agentes_estado(p_account_id uuid) RETURNS TABLE(agent_key text, nombre text, cadencia text, que_hace text, ultima_vez timestamp with time zone, estado text, corridas_24h integer, fallos_24h integer, pausado boolean, paused_at timestamp with time zone, paused_by text, se_puede_pausar boolean, jobs_totales integer, jobs_apagados integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (p_account_id = any (public.current_user_account_ids())) then
    raise exception 'home_agentes_estado: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with def(clave, nom, cad, hace, patron, pausable) as (
    values
      ('ofertas',  'Ofertas',            'cada hora',
       'Enciende y apaga promociones segun la demanda',
       array['offers-agent-hourly'], true),          -- v54, 02/09 18:51
      ('campanas', 'Reglas de campana',  'cada 15 min',
       'Vigila valles de venta y dispara campanas con tope de gasto',
       array['evaluate-campaign-rules'], false),
      ('clima',    'Clima y reparto',    'cada 10 min',
       'Ajusta el reparto cuando va a llover',
       array['reparto-weather-poll','reparto-weather-apply'], false),
      ('social',   'Social',             'diario',
       'Prepara y publica el contenido del dia',
       array['social-agent-daily','social-publish-worker'], true),
      ('guardias', 'Guardias',           '15 vigias',
       'Pedidos atascados, tablets mudas, ventas sin mapear, salud de la base',
       array['%watchdog%','%-check','%-guard','%health%'], false)
  ),
  jobs as (
    select d.clave, j.jobid, j.jobname, j.active
    from def d
    join cron.job j
      on (d.clave <> 'guardias' and j.jobname = any(d.patron))
      or (d.clave =  'guardias' and exists (
            select 1 from unnest(d.patron) p where j.jobname like p))
  ),
  corridas as (
    select jb.clave, max(r.end_time) as ult, count(*) as veces,
           count(*) filter (where r.status <> 'succeeded') as malas
    from jobs jb join cron.job_run_details r on r.jobid = jb.jobid
    where r.start_time > now() - interval '24 hours'
    group by 1
  ),
  resumen as (
    select jb.clave, count(*)::int as total,
           count(*) filter (where not jb.active)::int as apagados
    from jobs jb group by 1
  )
  select d.clave, d.nom, d.cad, d.hace, c.ult,
         case when ap.account_id is not null then 'pausado'
              when c.ult is null             then 'sin_datos'
              when coalesce(c.malas, 0) > 0  then 'con_fallos'
              else 'ok' end,
         coalesce(c.veces, 0)::int, coalesce(c.malas, 0)::int,
         (ap.account_id is not null), ap.paused_at, ap.paused_by_label,
         d.pausable, coalesce(rs.total, 0), coalesce(rs.apagados, 0)
  from def d
  left join corridas c  on c.clave  = d.clave
  left join resumen  rs on rs.clave = d.clave
  left join agent_pause ap on ap.account_id = p_account_id and ap.agent_key = d.clave
  order by array_position(array['ofertas','campanas','clima','social','guardias'], d.clave);
end;
$$;


--
-- Name: home_en_cocina_ahora(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.home_en_cocina_ahora(p_account_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(employee_id uuid, nombre text, location_id uuid, location_name text, estado text, abierta_desde timestamp with time zone, minutos_hoy numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
begin
  -- GUARDA DE CUENTA DENTRO, no solo confiada a la RLS. `employee_clock_status`
  -- hace ademas la suya por empleado: dos puertas, ninguna abierta de mas.
  if not (p_account_id = any(public.current_user_account_ids())) then
    raise exception 'home_en_cocina_ahora: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  select e.id, e.name, l.id, l.name,
         s.j->>'estado',
         nullif(s.j->>'abierta_desde','')::timestamptz,
         nullif(s.j->>'minutos_hoy','')::numeric
  from employees e
  join locations l on l.id = e.location_id and l.active
  cross join lateral (select public.employee_clock_status(e.id) as j) s
  where e.account_id = p_account_id
    and e.active
    and (p_location_id is null or e.location_id = p_location_id)
  order by l.name, e.name;
end;
$$;


--
-- Name: home_vendido_sin_coste(uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.home_vendido_sin_coste(p_account uuid, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now(), p_location uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'home_vendido_sin_coste: sin acceso a la cuenta %', p_account;
  end if;

  with l as (
    select sl.quantity * sl.unit_price                        as venta,
           (sl.computed_cost is not null)                     as costeada,
           coalesce(mi.name, sl.product_name, '(sin nombre)')  as nombre,
           b.name                                             as marca,
           (sl.menu_item_id is not null and exists (
              select 1 from public.combo_slot cs
               where cs.combo_item_id = sl.menu_item_id
                 and cs.is_active))                           as es_combo
      from public.sale_line sl
      join public.sale s        on s.id  = sl.sale_id
      left join public.menu_item mi on mi.id = sl.menu_item_id
      left join public.brand b      on b.id  = mi.brand_id
     where sl.account_id = p_account
       and coalesce(s.status,'') <> 'cancelled'
       and s.sold_at >= p_from
       and s.sold_at <  p_to
       and (p_location is null or s.location_id = p_location)
       and coalesce(sl.line_type, 'product') = 'product'
  ),
  sin_coste as (select * from l where not costeada),
  por_producto as (
    select nombre, marca, es_combo,
           count(*)::int             as lineas,
           round(sum(venta))::numeric as venta
      from sin_coste
     group by nombre, marca, es_combo
  )
  select jsonb_build_object(
    'lineas',           (select count(*) from l),
    'lineas_costeadas', (select count(*) filter (where costeada) from l),
    'cobertura_pct',    (select round(100.0 * count(*) filter (where costeada)
                                     / nullif(count(*),0), 1) from l),
    'venta',            (select coalesce(round(sum(venta)), 0) from l),
    'venta_sin_coste',  (select coalesce(round(sum(venta)), 0) from sin_coste),
    'platos', (select jsonb_build_object(
                 'productos', count(*),
                 'lineas',    coalesce(sum(lineas), 0),
                 'venta',     coalesce(sum(venta), 0))
                 from por_producto where not es_combo),
    'combos', (select jsonb_build_object(
                 'productos', count(*),
                 'lineas',    coalesce(sum(lineas), 0),
                 'venta',     coalesce(sum(venta), 0))
                 from por_producto where es_combo),
    'top', (select coalesce(jsonb_agg(x order by x.venta desc, x.nombre), '[]'::jsonb)
              from (select nombre, marca, lineas, venta
                      from por_producto
                     where not es_combo
                     order by venta desc, nombre
                     limit 8) x)
  ) into v;

  return v;
end;
$$;


--
-- Name: FUNCTION home_vendido_sin_coste(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.home_vendido_sin_coste(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid) IS 'Inicio, tarjeta Platos sin escandallo. Lineas de PRODUCTO vendidas sin sale_line.computed_cost, separando los combos declarados (su coste son sus componentes) del resto. Ver 20260902T2100_home_vendido_sin_coste.sql.';


--
-- Name: hours_staffing_gaps(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hours_staffing_gaps(p_location_id uuid) RETURNS TABLE(weekday smallint, gap_start time without time zone, gap_end time without time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cells jsonb;
  v_day smallint;        -- convención business_hours (Postgres dow): 0=domingo..6=sábado
  v_sched_key text;      -- convención cuadrante: 0=lunes..6=domingo
  v_today date := (now() at time zone 'Europe/Madrid')::date;
begin
  select cells into v_cells
  from schedules
  where location_id = p_location_id
    and week_start <= v_today
    and v_today < week_start + 7
  order by week_start desc
  limit 1;

  if v_cells is null then
    return;
  end if;

  for v_day in 0..6 loop
    -- Mapeo dow (dom=0) -> clave cuadrante (lun=0): (dow + 6) % 7
    v_sched_key := ((v_day + 6) % 7)::text;

    return query
    with comercial as (
      select h.open_time as o,
             case when h.close_time <= h.open_time then time '23:59:59' else h.close_time end as c
      from business_hours h
      where h.location_id = p_location_id and h.brand_id is null and h.weekday = v_day
    ),
    cobertura as (
      select st.start_time as o,
             case when st.end_time <= st.start_time then time '23:59:59' else st.end_time end as c
      from shift_templates st
      where st.location_id = p_location_id and st.active = true
        and v_cells ? st.id::text
        and jsonb_array_length(coalesce(v_cells -> st.id::text -> v_sched_key, '[]'::jsonb)) > 0
    ),
    puntos as (
      select o as t from comercial union select c from comercial
      union select o from cobertura union select c from cobertura
    ),
    ordenados as (
      select t, lead(t) over (order by t) as t2 from puntos
    ),
    huecos as (
      select o2.t as s, o2.t2 as e
      from ordenados o2
      where o2.t2 is not null and o2.t2 > o2.t
        and exists (select 1 from comercial c where o2.t >= c.o and o2.t2 <= c.c)
        and not exists (select 1 from cobertura k where o2.t >= k.o and o2.t2 <= k.c)
    ),
    marcados as (
      select s, e, case when s = lag(e) over (order by s) then 0 else 1 end as nuevo
      from huecos
    ),
    grupos as (
      select s, e, sum(nuevo) over (order by s) as g from marcados
    )
    select v_day::smallint, min(s)::time, max(e)::time
    from grupos group by g order by min(s);
  end loop;
end;
$$;


--
-- Name: hubrise_location_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_location_status(p_account_id uuid) RETURNS TABLE(location_id uuid, location_name text, status text, external_location_id text, external_account_name text, external_location_name text, token_status text, token_checked_at timestamp with time zone, brands jsonb, last_order_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
  select
    l.id as location_id,
    l.name as location_name,
    case
      when not l.active then 'local_inactivo'
      when public._hubrise_location_pending_connect(l.account_id, l.id) then 'conectando'
      when ei.id is null then 'sin_conectar'
      when ei.token_status = 'invalid' then 'token_invalido'
      else 'conectado'
    end as status,
    elm.external_location_id,
    ei.external_account_name,
    ei.external_location_name,
    ei.token_status,
    ei.token_checked_at,
    coalesce(br.brands, '[]'::jsonb) as brands,
    lo.last_order_at
  from public.locations l
  left join public.external_location_map elm
    on elm.account_id = l.account_id and elm.source = 'hubrise'
   and elm.location_id = l.id and elm.is_active = true
  left join public.external_integration ei
    on ei.account_id = l.account_id and ei.source = 'hubrise'
   and ei.external_location_id = elm.external_location_id
   and ei.connection_name = 'Folvy'
  left join lateral (
    select jsonb_agg(jsonb_build_object(
      'brand_id', bhc.brand_id,
      'brand_name', b.name,
      'external_catalog_id', bhc.external_catalog_id,
      'hubrise_catalog_name', bhc.hubrise_catalog_name
    ) order by b.name) as brands
    from public.brand_hubrise_catalog bhc
    join public.brand b on b.id = bhc.brand_id
    where bhc.account_id = l.account_id and bhc.location_id = l.id
  ) br on true
  left join lateral (
    select max(created_at) as last_order_at
    from public.sale
    where account_id = l.account_id and location_id = l.id and source = 'hubrise'
  ) lo on true
  where l.account_id = p_account_id
  order by l.name;
$$;


--
-- Name: FUNCTION hubrise_location_status(p_account_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hubrise_location_status(p_account_id uuid) IS 'Contrato de la pantalla de estado HubRise (Fase 3, ADMIN-ONLY).
5 estados por prioridad: local_inactivo > conectando > sin_conectar > token_invalido > conectado.
brands (via brand_hubrise_catalog) sale vacio para roles no admin/manager -- RLS de esa tabla,
intencional: la pantalla que consume esto es de ajustes de cuenta, no para "worker".';


--
-- Name: hubrise_money(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_money(p text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
           WHEN p IS NULL OR btrim(p) = '' THEN 0
           ELSE COALESCE(NULLIF(split_part(btrim(p), ' ', 1), '')::numeric, 0)
         END;
$$;


--
-- Name: hubrise_ops_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_ops_dashboard() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_locations jsonb;
  v_writers jsonb;
  v_alerts_48h integer;
begin
  if not current_user_is_admin() then
    raise exception 'Acceso denegado: solo platform admins pueden ver el tablero de operación HubRise.';
  end if;

  with loc_ids as (
    select distinct location_id, account_id
    from external_integration
    where source = 'hubrise' and location_id is not null
    union
    select distinct location_id, account_id
    from external_location_map
    where source = 'hubrise' and location_id is not null
    union
    select distinct location_id, account_id
    from hubrise_oauth_state
    where kind = 'location' and location_id is not null
      and created_at > now() - interval '15 minutes'
  )
  select coalesce(jsonb_agg(row_json order by
      row_json->>'account_name', row_json->>'location_name',
      (row_json->>'is_standard_connection')::boolean desc nulls last,
      row_json->>'connection_name'
    ), '[]'::jsonb)
  into v_locations
  from (
    select jsonb_build_object(
      'account_id', a.id,
      'account_name', a.name,
      'location_id', l.id,
      'location_name', l.name,
      'integration_id', ei.id,
      'connection_name', ei.connection_name,
      'is_standard_connection', (ei.id is null or ei.connection_name = 'Folvy'),
      'status', case
          when not l.active then 'local_inactivo'
          when exists (
            select 1 from hubrise_oauth_state hos
            where hos.account_id = l.account_id and hos.kind = 'location' and hos.location_id = l.id
              and hos.created_at > now() - interval '15 minutes'
          ) then 'conectando'
          when ei.id is null or not ei.is_active then 'sin_conectar'
          when ei.token_status = 'invalid' then 'token_invalido'
          else 'conectado'
        end,
      'external_location_id', coalesce(ei.external_location_id, elm.external_location_id),
      'external_account_name', ei.external_account_name,
      'external_location_name', ei.external_location_name,
      'token_status', ei.token_status,
      'token_checked_at', ei.token_checked_at,
      'callback_status', ei.callback_status,
      'callback_checked_at', ei.callback_checked_at,
      'revoke_pending', coalesce(ei.revoke_pending, false),
      'last_order_at', lo.last_order_at,
      'brand_diff', (coalesce(jsonb_array_length(bd.catalog_only), 0) > 0 or coalesce(jsonb_array_length(bd.mapped_only), 0) > 0),
      'brands_catalog_only', coalesce(bd.catalog_only, '[]'::jsonb),
      'brands_mapped_only', coalesce(bd.mapped_only, '[]'::jsonb)
    ) as row_json
    from loc_ids li
    join locations l on l.id = li.location_id
    join accounts a on a.id = li.account_id
    left join external_integration ei
      on ei.account_id = l.account_id and ei.source = 'hubrise' and ei.location_id = l.id
     and (ei.connection_name = 'Folvy' or ei.is_active = true)
    left join external_location_map elm
      on elm.account_id = l.account_id and elm.source = 'hubrise' and elm.location_id = l.id
     and elm.is_active = true
    left join lateral (
      select max(created_at) as last_order_at
      from sale
      where account_id = l.account_id and location_id = l.id and source = 'hubrise'
    ) lo on true
    left join lateral (
      select
        (select coalesce(jsonb_agg(distinct b.name order by b.name), '[]'::jsonb)
           from brand_hubrise_catalog bhc
           join brand b on b.id = bhc.brand_id
           where bhc.account_id = l.account_id and bhc.location_id = l.id
             and not exists (
               select 1 from external_brand_map ebm
               where ebm.account_id = l.account_id and ebm.source = 'hubrise'
                 and ebm.external_location_id = coalesce(ei.external_location_id, elm.external_location_id)
                 and ebm.brand_id = bhc.brand_id
                 and not coalesce(ebm.is_ignored, false)
             )
        ) as catalog_only,
        (select coalesce(jsonb_agg(distinct b.name order by b.name), '[]'::jsonb)
           from external_brand_map ebm
           join brand b on b.id = ebm.brand_id
           where ebm.account_id = l.account_id and ebm.source = 'hubrise'
             and ebm.external_location_id = coalesce(ei.external_location_id, elm.external_location_id)
             and not coalesce(ebm.is_ignored, false)
             and not exists (
               select 1 from brand_hubrise_catalog bhc
               where bhc.account_id = l.account_id and bhc.location_id = l.id
                 and bhc.brand_id = ebm.brand_id
             )
        ) as mapped_only
    ) bd on true
  ) t;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'account_id', a.id,
      'account_name', a.name,
      'hubrise_account_id', hwc.hubrise_account_id,
      'token_status', hwc.token_status,
      'token_checked_at', hwc.token_checked_at,
      'connected_at', hwc.connected_at
    ) order by a.name
  ), '[]'::jsonb)
  into v_writers
  from hubrise_writer_connection hwc
  join accounts a on a.id = hwc.account_id;

  select count(*)
  into v_alerts_48h
  from system_alert_queue
  where kind in ('hubrise-connection-health', 'hubrise-callback', 'hubrise-revoke-pending')
    and created_at > now() - interval '48 hours';

  return jsonb_build_object(
    'locations', v_locations,
    'writers', v_writers,
    'alerts_48h', v_alerts_48h,
    'generated_at', now()
  );
end;
$$;


--
-- Name: FUNCTION hubrise_ops_dashboard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hubrise_ops_dashboard() IS 'Tablero de vigilancia HubRise (Fase 3, A.1) -- SUPERADMIN-ONLY (platform admin,
gateado por current_user_is_admin(), RAISE EXCEPTION si no lo es). Cruza TODAS las
cuentas -- distinto de hubrise_location_status (SECURITY INVOKER, admin de UNA
cuenta, pantalla de ajustes del cliente). Devuelve jsonb: locations[] (una fila
POR CONEXIÓN hubrise de cada cuenta x local -- la conexión estándar "Folvy"
siempre, más cualquier otra conexión que esté ACTIVA ahora mismo, etiquetada
como no estándar; corregido 15/08 tras certificación de Julio: filtrar solo por
connection_name=''Folvy'' escondía conexiones vivas reales, ej. "Folvy Test" en
el laboratorio), writers[] (una fila por escritora de cuenta), y alerts_48h
(contador global de system_alert_queue, sin atribuir a fila -- esa tabla no
tiene account_id/location_id estructurado; parsear el mensaje de texto sería
fabricar fragilidad, decisión de Julio 15/08). Deuda declarada: el día que se
toque system-alert por otro motivo, añadirle account_id/location_id
estructurados y entonces el tablero podrá atribuir alertas por fila.';


--
-- Name: hubrise_order_stuck_watchdog(integer, integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_order_stuck_watchdog(p_min_minutos integer DEFAULT 3, p_max_horas integer DEFAULT 3, p_debounce_window interval DEFAULT '00:30:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_n integer := 0; v_min integer;
BEGIN
  FOR r IN
    SELECT s.external_ref, s.platform_order_code, s.external_brand_text,
           s.total, s.created_at
      FROM public.sale s
     WHERE s.source = 'hubrise'
       AND s.status = 'open'
       AND coalesce(s.order_status, 'new') IN ('new','received')
       AND s.cancelled_at IS NULL
       AND s.created_at < now() - make_interval(mins => greatest(coalesce(p_min_minutos,3),1))
       AND s.created_at > now() - make_interval(hours => greatest(coalesce(p_max_horas,3),1))
     ORDER BY s.created_at
     LIMIT 20
  LOOP
    v_min := round(extract(epoch from (now() - r.created_at))/60);

    PERFORM public._queue_system_alert(
      'hubrise-order-stuck',
      'URGENTE: pedido HubRise SIN ACEPTAR hace ' || v_min::text || ' min ('
        || coalesce(r.external_brand_text,'sin marca') || ')',
      'Uber marca el pedido PERDIDO a los ~10 min y el pago queda en 0 EUR.' || chr(10)
        || 'Aceptar YA en Folvy o en el panel de la plataforma.' || chr(10) || chr(10)
        || '  codigo : ' || coalesce(r.platform_order_code,'(sin codigo)') || chr(10)
        || '  ref    : ' || coalesce(r.external_ref,'(sin ref)') || chr(10)
        || '  marca  : ' || coalesce(r.external_brand_text,'(sin marca)') || chr(10)
        || '  importe: ' || coalesce(r.total::text,'?') || ' EUR' || chr(10)
        || '  entro hace ' || v_min::text || ' min',
      -- Una clave POR PEDIDO: un pedido nuevo nunca queda tapado por el
      -- silencio de otro.
      'hubrise_stuck_' || coalesce(r.external_ref, r.created_at::text),
      p_debounce_window
    );
    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END;
$$;


--
-- Name: hubrise_street_line(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_street_line(p_address_1 text, p_city text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT CASE
    -- `city` NO es un número de portal (Just Eat: "Madrid") -> address_1 intacto.
    WHEN btrim(coalesce(p_city, '')) !~ '^[0-9]{1,4}( *- *[0-9]{1,4})? *[A-Za-zºª]?$'
      THEN nullif(btrim(coalesce(p_address_1, '')), '')
    -- Sin calle no hay nada que componer.
    WHEN nullif(btrim(coalesce(p_address_1, '')), '') IS NULL
      THEN NULL
    -- La calle ya lleva ese número al final -> no duplicar.
    WHEN btrim(p_address_1) ~ ('(^|[ ,])' || regexp_replace(btrim(p_city), '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '$')
      THEN btrim(p_address_1)
    -- Glovo: pegar el portal a la calle.
    ELSE btrim(p_address_1) || ', ' || btrim(p_city)
  END;
$_$;


--
-- Name: FUNCTION hubrise_street_line(p_address_1 text, p_city text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hubrise_street_line(p_address_1 text, p_city text) IS 'Compone "calle, número" desde customer.address_1 + customer.city de HubRise. Glovo manda el número de portal en `city` (incluidos rangos "40-46"); Just Eat manda ahí la ciudad. Se decide por la forma del dato. Idempotente.';


--
-- Name: hubrise_strip_ns(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_strip_ns(p_ref text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_ref is null then null
    when p_ref ~ '^shr_'   then regexp_replace(p_ref, '^shr_', '')
    when p_ref ~ '^[^:]+:' then regexp_replace(p_ref, '^[^:]+:', '')
    else p_ref
  end;
$$;


--
-- Name: hubrise_writer_token_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_writer_token_read(p_account_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  v_ref text;
  v_token text;
BEGIN
  SELECT credentials_ref INTO v_ref
  FROM public.hubrise_writer_connection
  WHERE account_id = p_account_id;

  IF v_ref IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO v_token
  FROM vault.decrypted_secrets
  WHERE id = v_ref::uuid;

  RETURN v_token;
END;
$$;


--
-- Name: hubrise_writer_token_save(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hubrise_writer_token_save(p_account_id uuid, p_access_token text, p_hubrise_account_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  v_existing_ref text;
  v_secret_id uuid;
  v_secret_name text;
BEGIN
  IF p_account_id IS NULL OR p_access_token IS NULL OR length(p_access_token) = 0 THEN
    RAISE EXCEPTION 'hubrise_writer_token_save: p_account_id y p_access_token son obligatorios';
  END IF;

  v_secret_name := 'hubrise-writer:' || p_account_id::text;

  SELECT credentials_ref INTO v_existing_ref
  FROM public.hubrise_writer_connection
  WHERE account_id = p_account_id;

  IF v_existing_ref IS NOT NULL THEN
    PERFORM vault.update_secret(v_existing_ref::uuid, p_access_token, v_secret_name, NULL);
    v_secret_id := v_existing_ref::uuid;
  ELSE
    v_secret_id := vault.create_secret(p_access_token, v_secret_name, 'Token escritor HubRise (Folvy) por cuenta');
  END IF;

  INSERT INTO public.hubrise_writer_connection (account_id, hubrise_account_id, credentials_ref, connected_at, updated_at)
  VALUES (p_account_id, p_hubrise_account_id, v_secret_id::text, now(), now())
  ON CONFLICT (account_id) DO UPDATE
    SET hubrise_account_id = EXCLUDED.hubrise_account_id,
        credentials_ref = EXCLUDED.credentials_ref,
        connected_at = now(),
        updated_at = now();
END;
$$;


--
-- Name: infer_employee_availability(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.infer_employee_availability(p_account uuid, p_location uuid DEFAULT NULL::uuid) RETURNS TABLE(employee_id uuid, employee_name text, day_of_week integer, shift_period text, veces_asignado integer, semanas_observadas integer, ratio numeric, sugerencia boolean, confianza text, motivo text)
    LANGUAGE sql STABLE
    AS $$
  with asign as (
    select s.location_id, s.week_start,
           (dia.key)::int as dow,
           (emp.value #>> '{}')::uuid as employee_id,
           case when st.start_time < time '17:00' then 'morning' else 'evening' end as periodo
    from public.schedules s
    cross join lateral jsonb_each(s.cells) shift
    cross join lateral jsonb_each(shift.value) dia
    cross join lateral jsonb_array_elements(dia.value) emp
    join public.shift_templates st on st.id = (shift.key)::uuid
    where s.location_id in (
      select id from public.locations
      where account_id = p_account and (p_location is null or id = p_location))
  ),
  -- semanas en las que ese empleado aparece en algún cuadrante (denominador honesto:
  -- no penaliza a quien entró tarde ni cuenta semanas en las que no estaba)
  semanas as (
    select employee_id, count(distinct week_start) as n_semanas
    from asign group by employee_id
  ),
  -- rejilla completa: cada empleado x 7 días x 2 periodos
  rejilla as (
    select sm.employee_id, d.dow, p.periodo, sm.n_semanas
    from semanas sm
    cross join generate_series(0,6) d(dow)
    cross join (values ('morning'),('evening')) p(periodo)
  ),
  conteo as (
    select r.employee_id, r.dow, r.periodo, r.n_semanas,
           (select count(*) from asign a
             where a.employee_id = r.employee_id and a.dow = r.dow and a.periodo = r.periodo) as veces
    from rejilla r
  )
  select c.employee_id, e.name, c.dow, c.periodo,
         c.veces::int, c.n_semanas::int,
         round(c.veces::numeric / nullif(c.n_semanas,0), 2) as ratio,
         (c.veces > 0) as sugerencia,
         case
           when c.n_semanas < 4 then 'baja'                      -- poca muestra: no afirmar nada
           when c.veces = 0 then 'alta'                           -- nunca en N semanas = restricción real
           when c.veces::numeric / c.n_semanas >= 0.6 then 'alta' -- patrón fijo
           else 'media'
         end as confianza,
         case
           when c.n_semanas < 4 then 'Solo '||c.n_semanas||' semanas observadas: hace falta más historial'
           when c.veces = 0 then 'Nunca asignado en '||c.n_semanas||' semanas'
           when c.veces::numeric / c.n_semanas >= 0.6 then 'Asignado '||c.veces||' de '||c.n_semanas||' semanas'
           else 'Asignado solo '||c.veces||' de '||c.n_semanas||' semanas'
         end as motivo
  from conteo c
  join public.employees e on e.id = c.employee_id
  order by e.name, c.dow, c.periodo;
$$;


--
-- Name: informe_por_enlace(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.informe_por_enlace(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare x public.registro_jornada_enlace;
begin
  select * into x from public.registro_jornada_enlace where token = p_token for update;
  if x.token is null or x.revocado_at is not null or x.caduca_at <= now() then
    raise exception 'ENLACE_NO_VALIDO' using errcode = '42501', hint = 'Este enlace ya no es válido: ha caducado o lo han retirado. Pide uno nuevo a la empresa.';
  end if;
  update public.registro_jornada_enlace
     set abierto_veces = abierto_veces + 1, ultimo_abierto_at = now()
   where token = p_token;
  -- Con el DNI (la identificación que pide el art. 34.9); una baja médica, como
  -- «ausente» (decisión 1 de Julio: para los demás, nunca el motivo).
  return public._informe_registro_jornada(x.employee_id, x.desde, x.hasta, true, false)
         || jsonb_build_object('enlace', jsonb_build_object('caduca_at', x.caduca_at, 'creado_at', x.creado_at));
end $$;


--
-- Name: informe_registro_jornada(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.informe_registro_jornada(p_employee_id uuid, p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acct uuid;
begin
  v_acct := public._account_of_employee(p_employee_id);
  if v_acct is null or not public.current_user_ve_persona(p_employee_id, v_acct) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'Solo ves el registro de las personas que llevas.';
  end if;
  if p_hasta < p_desde or p_hasta - p_desde > 366 then
    raise exception 'PERIODO_INVALIDO' using errcode = '22023', hint = 'El periodo va de un día a un año.';
  end if;
  return public._informe_registro_jornada(p_employee_id, p_desde, p_hasta,
           public.current_user_is_admin_of(v_acct),
           public.current_user_is_admin_of(v_acct) or public.current_user_is_employee(p_employee_id, v_acct));
end $$;


--
-- Name: ingesta_silencio_watchdog(integer, integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingesta_silencio_watchdog(p_min_punta integer DEFAULT 30, p_min_valle integer DEFAULT 60, p_debounce_window interval DEFAULT '02:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_loc        record;
  v_n          integer := 0;
  v_hoy        date;
  v_hora       integer;
  v_apertura   timestamptz;
  v_cierre     timestamptz;
  v_exc_ap     timestamptz;
  v_exc_ci     timestamptz;
  v_ultima     timestamptz;
  v_ancla      timestamptz;
  v_mudo       integer;
  v_umbral     integer;
  v_sev        text;
  v_corto      text;
  v_otras      integer;
  v_sin_hora   text[] := '{}';
  v_vende_apagado text[] := '{}';
  v_dominante  text;
  v_pct        numeric;
  v_ultima_dom timestamptz;
  v_mudo_dom   integer;
BEGIN
  v_hoy  := (now() at time zone 'Europe/Madrid')::date;
  v_hora := extract(hour from (now() at time zone 'Europe/Madrid'));

  FOR v_loc IN
    SELECT l.id, l.name, l.account_id, a.name AS cuenta,
           EXISTS (SELECT 1 FROM public.business_hours bh WHERE bh.location_id = l.id) AS tiene_horario
      FROM public.locations l
      JOIN public.accounts a ON a.id = l.account_id
     -- ── EL CRITERIO YA NO ES LA BANDERA, ES LA ACTIVIDAD (09/09) ────────
     -- Escribí «sólo locales con `l.active`» y estaba mal, y se vio con un
     -- caso: un local con la bandera apagada desde el 18/06 facturando 3.254 €
     -- en 30 días. Con aquella vara no se habría vigilado NUNCA mientras
     -- facturaba. La bandera la mantiene una persona; las ventas no mienten.
     -- Y que la bandera diga lo contrario es un aviso en sí mismo — está
     -- abajo, en su propio bloque.
     --
     -- El estado de la CUENTA sí se respeta: eso no es una bandera olvidada,
     -- es una decisión de negocio con fecha y motivo escritos.
     WHERE public.cuenta_opera(l.account_id)
       AND EXISTS (SELECT 1 FROM public.sale s
                    WHERE s.location_id = l.id AND s.sold_at >= now() - interval '7 days')
     ORDER BY a.name, l.name
  LOOP
    -- Sin horario no hay veto posible, y vigilar sin veto es la franja fija
    -- otra vez. No se vigila — pero se dice, abajo.
    IF NOT v_loc.tiene_horario THEN
      v_sin_hora := v_sin_hora || (v_loc.cuenta || ' · ' || v_loc.name);
      CONTINUE;
    END IF;

    -- ── EL VETO ───────────────────────────────────────────────────────────
    CONTINUE WHEN NOT public.is_brand_open(v_loc.id, NULL, now());

    -- ── La apertura del tramo EN CURSO, que es el ancla del silencio ──────
    SELECT o.opened_from, o.opened_until INTO v_apertura, v_cierre
      FROM public.availability_location_open_minutes(
             v_loc.id, now() - interval '18 hours', now() + interval '12 hours') o
     WHERE o.opened_from <= now() AND o.opened_until > now()
     ORDER BY o.opened_from DESC
     LIMIT 1;

    -- Si hoy hay una excepción que ABRE en otro horario, manda ella (misma
    -- precedencia que `is_brand_open`). Hoy no existe ninguna en toda la tabla
    -- —las 92 que hay son cierres, y todas de un local inactivo— pero sin esto
    -- el ancla saldría del horario normal el día que aparezca la primera.
    -- Se lee aparte y sólo pisa si hay fila: un SELECT INTO sin resultados
    -- pone NULL, y eso se llevaría por delante lo que acabamos de calcular.
    SELECT (v_hoy + e.open_time) AT TIME ZONE 'Europe/Madrid',
           CASE WHEN e.close_time <= e.open_time
                THEN (v_hoy + 1 + e.close_time) AT TIME ZONE 'Europe/Madrid'
                ELSE (v_hoy + e.close_time) AT TIME ZONE 'Europe/Madrid' END
      INTO v_exc_ap, v_exc_ci
      FROM public.business_hours_exception e
     WHERE e.location_id = v_loc.id
       AND e.exception_date = v_hoy
       AND e.is_closed = false
       AND e.open_time IS NOT NULL AND e.close_time IS NOT NULL
     ORDER BY (e.brand_id IS NOT NULL) DESC
     LIMIT 1;
    IF v_exc_ap IS NOT NULL THEN
      v_apertura := v_exc_ap;
      v_cierre   := v_exc_ci;
    END IF;

    -- No se inventa un ancla: si el horario dice abierto pero no sabemos desde
    -- cuándo, no se avisa. Es preferible callar UNA pasada a contar minutos
    -- desde una hora que no es.
    CONTINUE WHEN v_apertura IS NULL;

    -- ── Cuánto lleva mudo ────────────────────────────────────────────────
    SELECT max(s.sold_at) INTO v_ultima
      FROM public.sale s
     WHERE s.location_id = v_loc.id AND s.sold_at >= v_apertura;

    -- Sin ventas desde que abrió, el ancla es la apertura. Aquí se cierra el
    -- punto ciego: antes eso era NULL y el vigía callaba.
    v_ancla := greatest(coalesce(v_ultima, v_apertura), v_apertura);
    v_mudo  := round(extract(epoch from (now() - v_ancla)) / 60);

    IF v_hora >= 20 THEN
      v_umbral := greatest(coalesce(p_min_punta, 30), 5);
      v_sev    := 'critico';
    ELSE
      v_umbral := greatest(coalesce(p_min_valle, 60), 5);
      v_sev    := 'alto';
    END IF;

    v_corto := CASE WHEN v_loc.name LIKE v_loc.cuenta || ' %'
                    THEN substr(v_loc.name, length(v_loc.cuenta) + 2)
                    ELSE v_loc.name END;

    -- ── 1) EL LOCAL, MUDO ────────────────────────────────────────────────
    IF v_mudo >= v_umbral THEN
      SELECT count(*) INTO v_otras
        FROM public.locations l2
       WHERE l2.account_id = v_loc.account_id AND l2.id <> v_loc.id AND l2.active
         AND EXISTS (SELECT 1 FROM public.sale s
                      WHERE s.location_id = l2.id
                        AND s.sold_at > now() - make_interval(mins => v_umbral));

      PERFORM public.encolar_alerta(
        p_kind    => 'ingesta_silencio',
        p_subject => 'Sin pedidos desde hace ' || v_mudo::text || ' min — está abierto',
        p_message =>
          v_corto || ' lleva ' || v_mudo::text || ' min sin ningún pedido y ahora mismo está abierto'
          || coalesce(' (cierra a las ' || to_char(v_cierre at time zone 'Europe/Madrid', 'HH24:MI') || ')', '')
          || '.' || chr(10)
          || CASE WHEN v_ultima IS NULL
                  THEN 'No ha entrado ninguno desde que abrió, a las '
                       || to_char(v_apertura at time zone 'Europe/Madrid', 'HH24:MI') || '.'
                  ELSE 'Último pedido: '
                       || to_char(v_ultima at time zone 'Europe/Madrid', 'HH24:MI') || '.' END
          || CASE WHEN v_otras > 0
                  THEN ' Las otras tiendas sí están recibiendo, así que no parece la cocina.'
                  ELSE '' END
          || chr(10) || chr(10)
          || 'Revisa la conexión de la caja en ' || v_corto || ' (paneles de Glovo y Uber).',
        p_debounce_kind   => 'ingesta_silencio_' || v_loc.id::text || '_' || v_sev || '_'
                             || to_char(v_hoy, 'YYYYMMDD'),
        p_debounce_window => p_debounce_window,
        p_account_id      => v_loc.account_id,
        p_location_id     => v_loc.id,
        p_brand_id        => NULL,
        p_severity        => v_sev
      );
      v_n := v_n + 1;
      CONTINUE;  -- si no entra NADA, no tiene sentido avisar además por vía
    END IF;

    -- ── 2) LA VÍA QUE MÁS PEDIDOS TRAE, MUDA ─────────────────────────────
    SELECT s.source, round(100.0 * count(*) / nullif(sum(count(*)) over (), 0), 1)
      INTO v_dominante, v_pct
      FROM public.sale s
     WHERE s.location_id = v_loc.id AND s.sold_at >= now() - interval '7 days'
     GROUP BY s.source
     ORDER BY count(*) DESC
     LIMIT 1;

    CONTINUE WHEN v_dominante IS NULL OR coalesce(v_pct, 0) < 60;

    SELECT max(s.sold_at) INTO v_ultima_dom
      FROM public.sale s
     WHERE s.location_id = v_loc.id AND s.source = v_dominante AND s.sold_at >= v_apertura;

    v_mudo_dom := round(extract(epoch from (now() - greatest(coalesce(v_ultima_dom, v_apertura), v_apertura))) / 60);

    IF v_mudo_dom >= greatest(coalesce(p_min_valle, 60), 5) THEN
      PERFORM public.encolar_alerta(
        p_kind    => 'ingesta_silencio',
        p_subject => v_dominante || ' lleva ' || v_mudo_dom::text || ' min sin traer pedidos',
        p_message =>
          'En ' || v_corto || ', ' || v_dominante || ' trae el ' || v_pct::text
          || ' % de los pedidos y lleva ' || v_mudo_dom::text
          || ' min sin traer ninguno, mientras otras vías sí están entrando.' || chr(10)
          || CASE WHEN v_ultima_dom IS NULL
                  THEN 'No ha traído ninguno desde que abrió.'
                  ELSE 'Último suyo: ' || to_char(v_ultima_dom at time zone 'Europe/Madrid','HH24:MI') || '.' END
          || chr(10) || chr(10)
          || 'Suele ser la conexión de esa vía, no la cocina.',
        p_debounce_kind   => 'ingesta_via_' || v_loc.id::text || '_' || v_dominante || '_'
                             || to_char(v_hoy, 'YYYYMMDD'),
        p_debounce_window => p_debounce_window,
        p_account_id      => v_loc.account_id,
        p_location_id     => v_loc.id,
        p_brand_id        => NULL,
        p_severity        => 'aviso'
      );
      v_n := v_n + 1;
    END IF;
  END LOOP;

  -- ── VENDE CON LA BANDERA APAGADA ───────────────────────────────────────
  -- Se mira APARTE y SIN el filtro de estado de cuenta, a propósito: una cuenta
  -- suspendida que sigue vendiendo es justo la noticia, no algo que callar. Si
  -- se filtrara aquí por `status='active'`, el único caso que existe hoy —el que
  -- destapó todo esto— sería invisible.
  --
  -- Es un ESTADO, no un suceso, así que la clave del antirruido va por la LISTA
  -- de locales y no por la fecha: sólo vuelve a sonar si la lista cambia.
  SELECT coalesce(array_agg(t.linea ORDER BY t.linea), '{}')
    INTO v_vende_apagado
    FROM (
      SELECT a2.name || ' · ' || l2.name || ' — ' || cnt.n || ' venta(s) en 7 días' AS linea
        FROM public.locations l2
        JOIN public.accounts a2 ON a2.id = l2.account_id
        JOIN LATERAL (SELECT count(*) AS n FROM public.sale s2
                       WHERE s2.location_id = l2.id
                         AND s2.sold_at >= now() - interval '7 days') cnt ON cnt.n > 0
       WHERE l2.active = false
         AND a2.is_internal IS NOT TRUE
         AND a2.archived_at IS NULL AND a2.deleted_at IS NULL
    ) t;

  IF array_length(v_vende_apagado, 1) > 0 THEN
    PERFORM public.encolar_alerta(
      p_kind    => 'ingesta_silencio',
      p_subject => 'Vende con el local apagado en Folvy: '
                   || array_length(v_vende_apagado, 1)::text || ' local(es)',
      p_message =>
        'Estos locales están marcados como INACTIVOS en Folvy y aun así han entrado ventas suyas '
        || 'en los últimos 7 días:' || chr(10)
        || '· ' || array_to_string(v_vende_apagado, chr(10) || '· ') || chr(10) || chr(10)
        || 'Mientras la bandera diga inactivo, ese local queda fuera de las pantallas y de los '
        || 'vigías que la miran. O el local se reactiva, o hay que dejar de aceptarle ventas: '
        || 'las dos cosas a la vez no se sostienen.',
      p_debounce_kind   => 'ingesta_vende_apagado_' || md5(array_to_string(v_vende_apagado, '|')),
      p_debounce_window => interval '7 days',
      p_account_id      => NULL,
      p_location_id     => NULL,
      p_brand_id        => NULL,
      p_severity        => 'alto'
    );
  END IF;

  -- ── AVISO DE COBERTURA ─────────────────────────────────────────────────
  -- Un vigía que no dice lo que NO mira da la sensación de que mira todo.
  --
  -- ⚠️ CAMBIO SOBRE EL FICHERO DE CODE, decidido por Julio (09/09): Code lo
  -- puso una vez AL DÍA. Diario está mal: esto no cambia de un día para otro y
  -- sería un correo cada mañana sobre lo mismo, que es justo el ruido que se
  -- viene a quitar. La clave de antirruido pasa a ir por la LISTA de locales
  -- afectados, no por la fecha: sólo vuelve a avisar cuando la lista CAMBIA.
  -- Techo real de 7 días, y no es un número elegido: el drenaje borra las filas
  -- enviadas a los 7 días, así que a partir de ahí la clave deja de existir y
  -- vuelve a sonar una vez. Ni calla sobre su punto ciego ni da la lata.
  IF array_length(v_sin_hora, 1) > 0 THEN
    PERFORM public.encolar_alerta(
      p_kind    => 'ingesta_silencio',
      p_subject => 'Sin vigilar por falta de horario: ' || array_length(v_sin_hora, 1)::text || ' local(es)',
      p_message =>
        'Estos locales tienen ventas y están activos, pero no tienen horario cargado, así que '
        || 'no se puede saber si deberían estar recibiendo pedidos. NO se vigilan:' || chr(10)
        || '· ' || array_to_string(v_sin_hora, chr(10) || '· ') || chr(10) || chr(10)
        || 'Cárgales el horario y empiezan a vigilarse solos.',
      p_debounce_kind   => 'ingesta_sin_horario_' || md5(array_to_string(v_sin_hora, '|')),
      p_debounce_window => interval '7 days',
      p_account_id      => NULL,
      p_location_id     => NULL,
      p_brand_id        => NULL,
      p_severity        => 'info'
    );
  END IF;

  RETURN v_n;
END;
$$;


--
-- Name: FUNCTION ingesta_silencio_watchdog(p_min_punta integer, p_min_valle integer, p_debounce_window interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ingesta_silencio_watchdog(p_min_punta integer, p_min_valle integer, p_debounce_window interval) IS 'Vigia de silencio de ingesta. 08/09/2026: el silencio se cuenta desde la apertura de la franja (12:00 Madrid), no desde la ultima venta de la madrugada — antes fabricaba un aviso falso cada dia a las 12:00 en punto (665-670 min, cinco dias seguidos). Pendiente del estandar de alertas: repartir por local, disparar por la historia del local en vez de por la franja fija, filtrar cuentas activas y reescribir el texto.';


--
-- Name: ingredients_without_spec(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingredients_without_spec(p_account_id uuid) RETURNS TABLE(ingredient_id uuid, ingredient_name text, supplier_id uuid, supplier_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'ingredients_without_spec: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  select ri.id, ri.name, asup.supplier_id, s.name
  from recipe_item ri
  left join lateral (
    select a.supplier_id
    from article_supplier a
    where a.recipe_item_id = ri.id and coalesce(a.is_active, true)
    order by a.is_preferred desc nulls last, a.updated_at desc nulls last
    limit 1
  ) asup on true
  left join supplier s on s.id = asup.supplier_id
  where ri.account_id = p_account_id
    and ri.type = 'raw'
    and coalesce(ri.is_active, true)
    and not exists (
      select 1
      from compliance_document_link cdl
      join compliance_document cd on cd.id = cdl.document_id
      where cdl.entity_type = 'recipe_item'
        and cdl.entity_id = ri.id
        and cd.doc_family = 'food_spec'
        and cd.status <> 'superseded'
    )
  order by s.name nulls last, ri.name;
end;
$$;


--
-- Name: internal_secret(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_secret(p_name text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
  select decrypted_secret from vault.decrypted_secrets where name = p_name limit 1;
$$;


--
-- Name: invoice_required_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_required_role(p_invoice_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_account_id uuid;
  v_amount numeric;
  v_supplier uuid;
  v_location uuid;
  v_role text;
BEGIN
  SELECT account_id, grand_total, supplier_id, location_id
    INTO v_account_id, v_amount, v_supplier, v_location
    FROM public.supplier_invoice WHERE id = p_invoice_id;
  IF v_account_id IS NULL THEN RETURN 'manager'; END IF;

  SELECT required_role INTO v_role
  FROM public.invoice_approval_rule r
  WHERE r.account_id = v_account_id
    AND r.active
    AND (r.min_amount IS NULL OR COALESCE(v_amount,0) >= r.min_amount)
    AND (r.max_amount IS NULL OR COALESCE(v_amount,0) <= r.max_amount)
    AND (r.supplier_id IS NULL OR r.supplier_id = v_supplier)
    AND (r.location_id IS NULL OR r.location_id = v_location)
  ORDER BY r.priority ASC
  LIMIT 1;

  RETURN COALESCE(v_role, 'manager');
END;
$$;


--
-- Name: is_brand_open(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_brand_open(p_location_id uuid, p_brand_id uuid, p_ts timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_local_date date := (p_ts at time zone 'Europe/Madrid')::date;
  v_local_time time := (p_ts at time zone 'Europe/Madrid')::time;
  v_prev_date date := v_local_date - 1;
  v_dow smallint := extract(dow from v_local_date)::smallint;       -- 0=domingo
  v_dow_prev smallint := extract(dow from v_prev_date)::smallint;
  v_has_exc boolean;
  v_open boolean := false;
begin
  -- 1) Excepcion para HOY (marca, o general del local si la marca no tiene)
  select exists (
    select 1 from business_hours_exception e
    where e.location_id = p_location_id
      and e.exception_date = v_local_date
      and (e.brand_id = p_brand_id or e.brand_id is null)
  ) into v_has_exc;

  if v_has_exc then
    -- Prioriza la excepcion de la marca sobre la general
    return exists (
      select 1 from business_hours_exception e
      where e.location_id = p_location_id
        and e.exception_date = v_local_date
        and (e.brand_id = p_brand_id or e.brand_id is null)
        and e.is_closed = false
        and e.open_time is not null and e.close_time is not null
        and (
          (e.close_time > e.open_time and v_local_time >= e.open_time and v_local_time < e.close_time)
          or
          (e.close_time <= e.open_time and (v_local_time >= e.open_time or v_local_time < e.close_time))
        )
      order by (e.brand_id is not null) desc
      limit 1
    );
  end if;

  -- 2) Horario habitual del dia de HOY (tramos que abren hoy)
  select exists (
    select 1 from business_hours h
    where h.location_id = p_location_id
      and h.weekday = v_dow
      and (h.brand_id = p_brand_id or h.brand_id is null)
      and (
        (h.close_time > h.open_time and v_local_time >= h.open_time and v_local_time < h.close_time)
        or
        (h.close_time <= h.open_time and v_local_time >= h.open_time)  -- abre hoy, cierra manana
      )
      -- si la marca tiene horario propio para este dia, ignora el general
      and (
        h.brand_id = p_brand_id
        or not exists (
          select 1 from business_hours h2
          where h2.location_id = p_location_id and h2.brand_id = p_brand_id and h2.weekday = v_dow
        )
      )
  ) into v_open;
  if v_open then return true; end if;

  -- 3) Tramo del dia ANTERIOR que cruza medianoche y sigue abierto ahora
  return exists (
    select 1 from business_hours h
    where h.location_id = p_location_id
      and h.weekday = v_dow_prev
      and (h.brand_id = p_brand_id or h.brand_id is null)
      and h.close_time <= h.open_time          -- cruza medianoche
      and v_local_time < h.close_time          -- aun dentro del tramo de madrugada
      and (
        h.brand_id = p_brand_id
        or not exists (
          select 1 from business_hours h2
          where h2.location_id = p_location_id and h2.brand_id = p_brand_id and h2.weekday = v_dow_prev
        )
      )
  );
end;
$$;


--
-- Name: item_movements(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_movements(p_account uuid, p_recipe_item uuid, p_location uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
with base as (
  select sm.id, sm.movement_type, sm.source_type, sm.source_id, sm.location_id,
         sm.qty_base, sm.unit_cost, sm.occurred_at, sm.created_by_name, sm.notes,
         l.name as location_name
  from stock_movement sm
  left join locations l on l.id = sm.location_id
  where sm.account_id = p_account
    and sm.recipe_item_id = p_recipe_item
    and (p_location is null or sm.location_id = p_location)
    and (p_from is null or sm.occurred_at >= p_from)
    and (p_to is null or sm.occurred_at < p_to)
  order by sm.occurred_at desc
  limit greatest(p_limit, 0)
),
resolved as (
  select b.*,
    case b.source_type
      when 'sale' then (
        select trim(both ' ·' from
          coalesce(sc.name, initcap(s.external_channel_text), 'Venta')
          || coalesce(' · ' || nullif((case when left(btrim(s.raw_tab),1) = '{' then s.raw_tab::jsonb->>'code' else null end), ''), ''))
        from sale_line sl
        join sale s on s.id = sl.sale_id
        left join sales_channel sc on sc.id = s.channel_id
        where sl.id = b.source_id
      )
      when 'goods_receipt_line' then (
        select coalesce(gr.code, 'Recepción') || coalesce(' · ' || nullif(gr.supplier_doc_number, ''), '')
        from goods_receipt_line grl join goods_receipt gr on gr.id = grl.goods_receipt_id
        where grl.id = b.source_id
      )
      when 'adjustment' then (select 'Ajuste · ' || sa.reason_code from stock_adjustment sa where sa.id = b.source_id)
      when 'waste' then (select 'Merma · ' || sw.reason_code from stock_waste sw where sw.id = b.source_id)
      when 'transfer' then (
        select case when st.from_location_id = b.location_id then '→ ' || coalesce(lt.name, 'otro local')
                    else '← ' || coalesce(lf.name, 'otro local') end
        from stock_transfer st
        left join locations lf on lf.id = st.from_location_id
        left join locations lt on lt.id = st.to_location_id
        where st.id = b.source_id
      )
      else null
    end as reference
  from base b
)
select coalesce((
  select jsonb_agg(jsonb_build_object(
           'id', r.id, 'movement_type', r.movement_type, 'source_type', r.source_type,
           'location_name', r.location_name, 'qty_base', r.qty_base, 'unit_cost', r.unit_cost,
           'cost_eur', round(abs(r.qty_base) * coalesce(r.unit_cost, 0), 2),
           'occurred_at', r.occurred_at, 'created_by_name', r.created_by_name,
           'reference', r.reference, 'notes', r.notes
         ) order by r.occurred_at desc)
  from resolved r
), '[]'::jsonb);
$$;


--
-- Name: item_stock_by_location(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_stock_by_location(p_account uuid, p_recipe_item uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
with bf as (
  select pf.name, pf.qty_in_base, pf.is_piece
  from recipe_item_purchase_format pf
  where pf.item_id = p_recipe_item
    and pf.account_id = p_account
    and pf.parent_format_id is null
    and pf.is_active = true
    and pf.archived_at is null
  order by pf.qty_in_base desc
  limit 1
),
rows as (
  select l.id as location_id, l.name as location_name,
         coalesce(ril.qty_on_hand, 0) as qty,
         coalesce(ril.stock_value, 0) as value_eur,
         ril.recipe_item_id is not null as has_stock_row
  from locations l
  left join recipe_item_location_stock ril
    on ril.location_id = l.id
   and ril.recipe_item_id = p_recipe_item
   and ril.account_id = p_account
  where l.account_id = p_account
)
select jsonb_build_object(
  'unit_abbr', (select ku.abbreviation from recipe_item ri left join kitchen_unit ku on ku.id = ri.base_unit_id where ri.id = p_recipe_item),
  'buy_format_name', (select name from bf),
  'buy_format_qty_in_base', (select qty_in_base from bf),
  'total_qty', (select coalesce(sum(qty), 0) from rows),
  'total_value', (select coalesce(sum(value_eur), 0) from rows),
  'locations', coalesce((
    select jsonb_agg(jsonb_build_object(
             'location_id', r.location_id, 'location_name', r.location_name,
             'qty', r.qty, 'value_eur', r.value_eur, 'has_stock_row', r.has_stock_row
           ) order by r.value_eur desc nulls last, r.location_name asc)
    from rows r
  ), '[]'::jsonb)
);
$$;


--
-- Name: jornadas_para_revisar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jornadas_para_revisar(p_account_id uuid) RETURNS TABLE(clock_entry_id uuid, employee_id uuid, nombre text, tipo text, entrada timestamp with time zone, salida timestamp with time zone, horas numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.current_user_is_admin_or_manager_of(p_account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501';
  end if;
  return query
  with m as (
    select ce.id, ce.employee_id, ce.type, coalesce(ce.real_datetime, ce.datetime) as t
      from public.clock_entries ce
     where ce.account_id = p_account_id and not coalesce(ce.voided, false)
       and ce.type in ('entrada', 'salida')
  ), s as (
    select m.*, lead(m.type) over w as sig_tipo, lead(m.t) over w as sig_t
      from m window w as (partition by m.employee_id order by m.t, m.id)
  )
  select s.id, s.employee_id, e.name,
         case when s.sig_tipo = 'salida' then 'larga' else 'sin_salida' end,
         s.t,
         case when s.sig_tipo = 'salida' then s.sig_t end,
         case when s.sig_tipo = 'salida' then round(extract(epoch from (s.sig_t - s.t)) / 3600.0, 1) end
    from s
    join public.employees e on e.id = s.employee_id
   where s.type = 'entrada'
     and (   (s.sig_tipo = 'salida' and s.sig_t - s.t > interval '12 hours')
          or  s.sig_tipo = 'entrada'
          or (s.sig_tipo is null and s.t < now() - interval '24 hours'))
     and public.current_user_ve_persona(s.employee_id, p_account_id)
   order by s.t desc;
end $$;


--
-- Name: journal_cadena_comprobar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_cadena_comprobar(p_company uuid) RETURNS TABLE(chain_seq bigint, entry_id uuid, series smallint, number integer, ok boolean, motivo text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v_prev text := null; v_esperada text;
begin
  if not exists (select 1 from public.company c where c.id = p_company and public.belongs_to_account(c.account_id)) then
    raise exception 'Esa empresa no es de tu cuenta.' using errcode = '42501';
  end if;
  for r in select e.* from public.journal_entry e where e.company_id = p_company and e.chain_seq is not null order by e.chain_seq loop
    v_esperada := public.journal_huella(v_prev, public.journal_entry_canonico(r.id));
    chain_seq := r.chain_seq; entry_id := r.id; series := r.series; number := r.number;
    ok := r.prev_hash is not distinct from v_prev and r.hash = v_esperada;
    motivo := case when r.prev_hash is distinct from v_prev then 'no encadena con el anterior'
                   when r.hash <> v_esperada then 'su contenido no es el que se validó' end;
    return next;
    v_prev := r.hash;
  end loop;
end $$;


--
-- Name: journal_entry_anular(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_anular(p_entry uuid, p_motivo text, p_fecha date DEFAULT NULL::date, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e public.journal_entry; v_fecha date; v_y uuid; v_nuevo uuid; v_r jsonb; v_quien text; v_factura text; v_pago public.customer_invoice_payment; v_pp record;
begin
  select * into v_e from public.journal_entry where id = p_entry for update;
  if v_e.id is null then raise exception 'Ese asiento no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(v_e.account_id) then
    raise exception 'Solo un administrador de la cuenta anula asientos.' using errcode = '42501';
  end if;
  if v_e.status <> 'validado' then
    raise exception 'Solo se anula un asiento validado (este está %).', v_e.status using errcode = '23514';
  end if;
  if v_e.source_type = 'reversal' then
    raise exception 'Un contraasiento no se anula: si hace falta, se hace el asiento bueno.' using errcode = '23514';
  end if;
  -- V01 entrega 2 (Julio, 24/10): el asiento de una factura emitida, o el de
  -- un cierre con su factura resumen, no se anula desde aquí: la factura
  -- quedaría viva sin su asiento. Se corrige desde la factura («Corregir»).
  select number_text into v_factura from public.customer_invoice where entry_id = v_e.id and status <> 'borrador' limit 1;
  if v_factura is not null then
    raise exception 'Este asiento es el de la factura %: no se anula desde Contabilidad. Se corrige desde la factura, con «Corregir».', v_factura using errcode = '23514';
  end if;
  if p_motivo is null or length(trim(p_motivo)) = 0 then
    raise exception 'Para anular hay que decir por qué.' using errcode = '23514';
  end if;
  v_quien := coalesce(p_quien_nombre, public.conta_nombre_actor());
  v_fecha := coalesce(p_fecha, greatest(v_e.entry_date, current_date));
  if public.conta_mes_cerrado(v_e.company_id, v_fecha) then
    v_fecha := public.conta_primer_dia_abierto(v_e.company_id, v_fecha);
  end if;
  select id into v_y from public.fiscal_year
   where company_id = v_e.company_id and v_fecha between starts_on and ends_on;
  if v_y is null then raise exception 'No hay ejercicio abierto para el %.', to_char(v_fecha, 'DD/MM/YYYY') using errcode = '23514'; end if;

  insert into public.journal_entry (account_id, company_id, fiscal_year_id, series, entry_date, concept, source_type, source_id,
                                    status, party_id, document_ref, document_date, reverses_entry_id, created_by, created_by_name)
  values (v_e.account_id, v_e.company_id, v_y, v_e.series, v_fecha,
          format('Anula %s nº %s: %s', case v_e.series when 1 then 'Ventas' when 2 then 'Compras' when 3 then 'Banco' when 9 then 'Nóminas' else 'General' end, v_e.number, trim(p_motivo)), 'reversal', v_e.id,
          'borrador', v_e.party_id, v_e.document_ref, v_e.document_date, v_e.id, auth.uid(), v_quien)
  returning id into v_nuevo;
  insert into public.journal_line (account_id, company_id, entry_id, position, company_account_id, debit, credit, concept,
                                   location_id, is_common, brand_id, party_id, document_ref, document_date,
                                   tax_rate_id, tax_base, vat_book, vat_deductible, tax_documents, withholding_rate_id, withholding_base, withholding_model)
  select account_id, company_id, v_nuevo, position, company_account_id, credit, debit, concept,
         location_id, is_common, brand_id, party_id, document_ref, document_date,
         tax_rate_id, tax_base, vat_book, vat_deductible, tax_documents, withholding_rate_id, withholding_base, withholding_model
    from public.journal_line where entry_id = v_e.id;
  v_r := public.journal_entry_validar(v_nuevo, v_quien);

  update public.journal_entry set status = 'anulado', voided_by_entry_id = v_nuevo, voided_at = now(), voided_by = auth.uid(),
         voided_by_name = v_quien, void_reason = trim(p_motivo)
   where id = v_e.id;
  -- V01: anular el asiento de un cobro en efectivo deshace ese cobro en su factura.
  -- PC01: y el de cualquier cobro o pago con ese asiento (el del banco, el del
  -- lote de prepago), todos, no solo el primero.
  for v_pago in select * from public.customer_invoice_payment where entry_id = v_e.id loop
    delete from public.customer_invoice_payment where id = v_pago.id;
    perform public._conta_venta_evento(v_pago.invoice_id, 'cobro_anulado',
      'Cobro ' || case when v_pago.method = 'cash' then 'en efectivo ' else '' end || 'de ' || to_char(v_pago.amount, 'FM999G999G990D00') || ' € anulado desde Contabilidad (asiento nº ' || v_e.number || '): ' || trim(p_motivo) || '.',
      jsonb_build_object('asiento', v_e.id, 'contraasiento', v_nuevo), v_quien);
  end loop;
  for v_pp in delete from public.supplier_invoice_payment where entry_id = v_e.id returning invoice_id loop
    if exists (select 1 from public.supplier_invoice si where si.id = v_pp.invoice_id and si.status = 'pagada'
                  and coalesce((select sum(x.amount) from public.supplier_invoice_payment x where x.invoice_id = si.id and x.entry_id is not null), 0) < coalesce(si.grand_total, 0) - 0.005) then
      perform public.unmark_supplier_invoice_paid(v_pp.invoice_id);
    end if;
  end loop;
  return jsonb_build_object('anulado', v_e.id, 'contraasiento', v_nuevo, 'serie', v_r->'serie', 'numero', v_r->'numero', 'fecha', v_fecha);
end $$;


--
-- Name: journal_entry_canonico(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_canonico(p_entry uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select concat_ws('|',
           e.id, e.company_id, e.fiscal_year_id, e.series, e.number, e.entry_date, e.concept, e.source_type,
           coalesce(e.source_id::text, ''), coalesce(e.party_id::text, ''), coalesce(e.document_ref, ''),
           coalesce(e.document_date::text, ''), coalesce(e.external_program, ''), coalesce(e.external_series, ''),
           coalesce(e.external_number, ''), coalesce(e.reverses_entry_id::text, ''))
         || '#' ||
         coalesce((select string_agg(concat_ws(':',
                    l.position, a.code, l.debit, l.credit, coalesce(l.location_id::text, ''), l.is_common,
                    coalesce(l.brand_id::text, ''), coalesce(l.party_id::text, ''), coalesce(l.document_ref, ''),
                    coalesce(l.tax_rate_id::text, ''), coalesce(l.tax_base::text, ''), coalesce(l.vat_book, ''),
                    coalesce(l.vat_deductible, ''), l.tax_documents, coalesce(l.withholding_rate_id::text, ''),
                    coalesce(l.withholding_base::text, ''), coalesce(l.withholding_model, '')), ';' order by l.position)
                   from public.journal_line l join public.company_account a on a.id = l.company_account_id
                  where l.entry_id = e.id), '')
    from public.journal_entry e where e.id = p_entry
$$;


--
-- Name: journal_entry_descartar(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_descartar(p_entry uuid, p_motivo text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e public.journal_entry; v_clave text;
begin
  select * into v_e from public.journal_entry where id = p_entry for update;
  if v_e.id is null then raise exception 'Ese asiento no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_e.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta descarta propuestas.' using errcode = '42501';
  end if;
  if v_e.status not in ('propuesto', 'borrador') then raise exception 'Solo se descarta una propuesta o un borrador; lo validado se anula.' using errcode = '23514'; end if;
  if p_motivo is null or length(trim(p_motivo)) = 0 then raise exception 'Para descartar hay que decir por qué.' using errcode = '23514'; end if;
  if v_e.source_type = 'sales_day' then
    -- C04b R5: el de una unidad descarta esa unidad, no el día entero.
    select s.location_id || ':' || s.sales_day || coalesce(':' || s.unit_key, '') into v_clave from public.sales_day_summary s where s.id = v_e.source_id;
  else
    v_clave := v_e.source_id::text;
  end if;
  if v_clave is not null then
    insert into public.journal_dismissal (account_id, company_id, source_type, source_key, reason, created_by, created_by_name)
    values (v_e.account_id, v_e.company_id, v_e.source_type, v_clave, trim(p_motivo), auth.uid(), coalesce(p_quien_nombre, public.conta_nombre_actor()))
    on conflict (company_id, source_type, source_key) do update set reason = excluded.reason;
  end if;
  delete from public.journal_entry where id = p_entry;
  return jsonb_build_object('descartado', p_entry, 'clave', v_clave);
end $$;


--
-- Name: journal_entry_document_nombre_limpio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_document_nombre_limpio() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if tg_op = 'INSERT' then
    new.original_name := coalesce(new.original_name, new.file_name);
  elsif new.file_name is distinct from old.file_name then
    new.original_name := new.file_name;
  end if;
  if new.file_name is null or new.file_name !~ '^[A-Za-z0-9._-]+\.pdf$' then
    new.file_name := public.conta_nombre_fichero(new.file_name);
  end if;
  return new;
end $_$;


--
-- Name: journal_entry_inalterable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_inalterable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_anulacion constant text[] := array['status', 'voided_by_entry_id', 'voided_at', 'voided_by', 'voided_by_name', 'void_reason', 'updated_at'];
begin
  if tg_op = 'DELETE' then
    if old.number is not null or old.status in ('validado', 'anulado') then
      raise exception 'El asiento %/% está validado: no se borra, se anula.', old.series, old.number using errcode = '42501';
    end if;
    return old;
  end if;
  new.updated_at := now();
  if old.status = 'validado' and old.hash = 'pendiente' and current_setting('folvy.journal_huella', true) = old.id::text
     and (to_jsonb(new) - array['hash', 'updated_at']) = (to_jsonb(old) - array['hash', 'updated_at']) then
    return new;
  end if;
  if old.status = 'anulado' then
    raise exception 'El asiento %/% está anulado: ya no cambia.', old.series, old.number using errcode = '42501';
  end if;
  if old.status = 'validado' then
    if new.status <> 'anulado'
       or (to_jsonb(new) - v_anulacion) is distinct from (to_jsonb(old) - v_anulacion) then
      raise exception 'El asiento %/% está validado: no se modifica, se anula con un contraasiento.', old.series, old.number using errcode = '42501';
    end if;
  end if;
  return new;
end $$;


--
-- Name: journal_entry_libro_registro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_libro_registro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'validado' and old.status is distinct from 'validado' and new.source_type <> 'reversal' then
    perform public.conta_vat_book_desde_asiento(new.id);
  elsif new.status = 'anulado' and old.status is distinct from 'anulado' then
    update public.vat_book_entry set voided_at = coalesce(new.voided_at, now()), voided_by_entry_id = new.voided_by_entry_id, updated_at = now()
     where entry_id = new.id and voided_at is null;
  end if;
  return null;
end $$;


--
-- Name: journal_entry_proponer(uuid, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_proponer(p_company uuid, p_entry jsonb, p_lines jsonb, p_summary jsonb DEFAULT NULL::jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from public.company where id = p_company;
  if v_cuenta is null or not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'Solo un administrador o un encargado de la cuenta propone asientos.' using errcode = '42501';
  end if;
  return public._journal_entry_proponer(p_company, p_entry, p_lines, p_summary, p_quien_nombre, auth.uid());
end $$;


--
-- Name: journal_entry_valida_con_pdf(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_valida_con_pdf() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'validado'
     and exists (select 1 from public.sales_day_summary d
                  where d.entry_id = new.id and d.account_id = new.account_id and d.channel_id is not null)
     and not exists (select 1 from public.journal_entry_document x
                      where x.entry_id = new.id and x.account_id = new.account_id and x.kind = 'resumen_ventas') then
    raise exception 'Un asiento de ventas de una plataforma se valida con su PDF («Resumen de ventas»), y este no lo lleva: no se valida.'
      using errcode = '23514', hint = 'Validar y guardar el PDF van juntos (journal_entry_validar_con_documento).';
  end if;
  return null;
end $$;


--
-- Name: journal_entry_validar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_validar(p_entry uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_e public.journal_entry;
begin
  select * into v_e from public.journal_entry where id = p_entry for update;
  if v_e.id is null then raise exception 'Ese asiento no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_e.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta valida asientos.' using errcode = '42501';
  end if;
  -- S01 · PR 3: las reglas de validar viven en _journal_entry_validar (una sola copia).
  return public._journal_entry_validar(p_entry, p_quien_nombre);
end $$;


--
-- Name: journal_entry_validar_con_documento(uuid, integer, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_validar_con_documento(p_entry uuid, p_numero integer, p_ruta text, p_nombre text, p_sha256 text, p_bytes integer, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_v jsonb; v_d jsonb;
begin
  if p_numero is null then
    raise exception 'Falta el número con el que se hizo el PDF.' using errcode = '22023';
  end if;
  -- Valida con todas sus reglas (cuadre, fecha, mes, IVA, número y huella).
  v_v := public.journal_entry_validar(p_entry, p_quien_nombre);
  if (v_v->>'numero')::int <> p_numero then
    raise exception 'El PDF se hizo con el nº % y al validar le toca el nº % (se ha validado otro asiento de la serie a la vez): no se valida. Vuelve a pulsar.',
      p_numero, (v_v->>'numero')::int using errcode = '40001';
  end if;
  -- Y guarda su PDF en la misma transacción: si no se puede, no se valida.
  v_d := public.conta_documento_guardar(p_entry, p_ruta, p_nombre, p_sha256, p_bytes, p_quien_nombre);
  return jsonb_build_object('id', p_entry, 'serie', v_v->'serie', 'numero', v_v->'numero', 'huella', v_v->'huella', 'documento', v_d);
end $$;


--
-- Name: journal_huella(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_huella(p_prev text, p_canonico text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select encode(extensions.digest(coalesce(p_prev, '') || '>' || p_canonico, 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION journal_huella(p_prev text, p_canonico text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.journal_huella(p_prev text, p_canonico text) IS 'C04. sha256(huella anterior > texto canónico). La primera de la empresa encadena con «» (vacío).';


--
-- Name: journal_line_coherente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_line_coherente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e public.journal_entry; v_a public.company_account;
begin
  select * into v_e from public.journal_entry where id = new.entry_id;
  if v_e.company_id is distinct from new.company_id then
    raise exception 'El apunte y su asiento tienen que ser de la misma empresa.' using errcode = '23514';
  end if;
  select * into v_a from public.company_account where id = new.company_account_id;
  if v_a.company_id is distinct from new.company_id then
    raise exception 'Esa cuenta no es de esta empresa.' using errcode = '23514';
  end if;
  if v_a.status = 'cerrada' and v_e.source_type <> 'migrated' then
    raise exception 'La cuenta % está cerrada: no admite apuntes nuevos.', v_a.code using errcode = '23514';
  end if;
  if new.location_id is not null and not exists (select 1 from public.locations l where l.id = new.location_id and l.account_id = new.account_id) then
    raise exception 'Ese local no es de esta cuenta.' using errcode = '23514';
  end if;
  if new.brand_id is not null and not exists (select 1 from public.brand b where b.id = new.brand_id and b.account_id = new.account_id) then
    raise exception 'Esa marca no es de esta cuenta.' using errcode = '23514';
  end if;
  if new.party_id is not null and not exists (select 1 from public.party p where p.id = new.party_id and p.account_id = new.account_id) then
    raise exception 'Ese tercero no es de esta cuenta.' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: journal_line_inalterable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_line_inalterable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_status text; v_entry uuid := coalesce(new.entry_id, old.entry_id);
begin
  select status into v_status from public.journal_entry where id = v_entry;
  -- Al borrar un borrador, sus apuntes se van con él (el asiento ya no existe).
  if v_status in ('validado', 'anulado') then
    raise exception 'Los apuntes de un asiento validado no se tocan: se anula con un contraasiento.' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.entry_id <> old.entry_id then
    raise exception 'Un apunte no cambia de asiento.' using errcode = '42501';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: kds_ack_alarm(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_ack_alarm(p_sale_id uuid, p_token text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_loc uuid;
begin
  select location_id into v_loc from sale where id = p_sale_id;
  if v_loc is null then raise exception 'kds_ack_alarm: venta inexistente'; end if;
  perform public.kds_authorize(v_loc, p_token);
  update sale
  set delivery_alarm_ack_at = now(),
      updated_at            = now()
  where id = p_sale_id
    and delivery_alarm_ack_at is null;
end;
$$;


--
-- Name: kds_alarms(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_alarms(p_location_id uuid, p_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device  kds_device;
  v_loc     uuid;
  v_result  jsonb;
begin
  if p_token is not null then
    v_device := public.kds_resolve_device(p_token);
    if v_device.id is null then raise exception 'kds_alarms: token de dispositivo no válido'; end if;
    v_loc := v_device.location_id;
    
  else
    if p_location_id is null then raise exception 'kds_alarms: falta location_id'; end if;
    v_loc := p_location_id;
    perform public.kds_authorize(v_loc, null);
  end if;

  select coalesce(jsonb_agg(row_to_json(a) order by a.raised_at desc), '[]'::jsonb)
  into v_result
  from (
    select s.id                                                             as sale_id,
           s.delivery_alarm_kind                                            as kind,
           s.delivery_alarm_at                                              as raised_at,
           s.delivery_state,
           s.order_status,
           coalesce(s.platform_order_code, s.external_tab_ref, s.external_ref) as code,
           s.customer_name,
           s.delivery_address,
           s.rider_name,
           s.rider_phone
    from sale s
    where s.location_id = v_loc
      and s.delivery_alarm_at is not null
      and s.delivery_alarm_ack_at is null
  ) a;

  return jsonb_build_object('location_id', v_loc, 'now', now(), 'alarms', v_result);
end;
$$;


--
-- Name: kds_authorize(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_authorize(p_location_id uuid, p_token text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device  kds_device;
  v_account uuid;
begin
  if p_token is not null then
    v_device := public.kds_resolve_device(p_token);
    if v_device.id is null then
      raise exception 'kds: token de dispositivo no válido';
    end if;
    if v_device.location_id <> p_location_id then
      raise exception 'kds: el token no corresponde a esta ubicación';
    end if;
    
    return v_device.account_id;
  end if;
  select account_id into v_account from locations where id = p_location_id;
  if v_account is null then raise exception 'kds: ubicación inexistente'; end if;
  if not belongs_to_account(v_account) then
    raise exception 'kds: sin acceso a esta ubicación';
  end if;
  return v_account;
end;
$$;


--
-- Name: kds_board(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_board(p_location_id uuid DEFAULT NULL::uuid, p_device_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_account_id uuid;
  v_location_id uuid := p_location_id;
  v_device     kds_device;
  v_station_filter uuid[] := null;
  v_default_station uuid;
  v_result     jsonb;
begin
  if p_device_token is not null then
    v_device := public.kds_resolve_device(p_device_token);
    if v_device.id is null then
      raise exception 'kds_board: token de dispositivo no válido';
    end if;
    if v_location_id is null then
      v_location_id := v_device.location_id;
    elsif v_device.location_id <> v_location_id then
      raise exception 'kds_board: el token no corresponde a esta ubicación';
    end if;
    v_account_id := v_device.account_id;
    v_station_filter := v_device.station_ids;
    
  else
    if v_location_id is null then
      raise exception 'kds_board: falta location o token';
    end if;
    select account_id into v_account_id from locations where id = v_location_id;
    if v_account_id is null then
      raise exception 'kds_board: ubicación inexistente';
    end if;
    if not belongs_to_account(v_account_id) then
      raise exception 'kds_board: sin acceso a esta ubicación';
    end if;
  end if;

  select id into v_default_station from kitchen_station
   where location_id = v_location_id and is_default and is_active limit 1;

  with vivos as (
    select s.id, s.external_ref, s.external_tab_ref, s.status,
           s.brand_id, s.channel_id, s.external_channel_text,
           s.opened_at, s.closed_at, s.sold_at, s.raw_tab,
           coalesce(s.opened_at, s.sold_at, s.created_at) as entro_at
    from sale s
    where s.location_id = v_location_id
      and s.account_id = v_account_id
      and s.status <> 'cancelled'
      -- Pedido del Shop sin confirmar (pago online pendiente): NO entra en cocina.
      and not (s.source = 'folvy_shop' and s.order_status = 'new')
      and not exists (
        select 1 from kds_ticket_station_state st
        join kitchen_station k on k.id = st.station_id
        where st.sale_id = s.id and k.kind = 'expo' and st.status = 'done'
      )
      and (s.status <> 'closed' or coalesce(s.closed_at, s.sold_at) >= now() - interval '2 hours')
      -- EL PASE (15/09/2026): con el Pase encendido en este local, un pedido
      -- que ya tiene sello de cocina sale del tablero de cocina. Antes sólo
      -- salía cuando la expo lo bajaba, y donde hay Pase ya no hay expo que lo
      -- baje. Se pregunta por `ready_at` --un solo escritor en toda la base--
      -- y no por una lista de estados, que sería la quinta definición de
      -- «listo». Con el interruptor apagado el `or` es cierto siempre: no-op.
      and (
        s.ready_at is null
        or not coalesce((select bool_or(k2.pase_activo) from kitchen_station k2
                          where k2.location_id = v_location_id
                            and k2.kind = 'expo'), false)
      )
      -- B47 (03/09/2026): un pedido cancelado o rechazado por la plataforma deja
      -- order_status en cancelled/rejected/delivery_failed y sale.status en 'open'.
      -- Sin esta linea el ticket no cae nunca (42 asi el dia que se midio, el mas
      -- antiguo del 24/06). Misma gracia de 2 h que los cerrados.
      and (coalesce(s.order_status, '') not in ('cancelled', 'rejected', 'delivery_failed')
           or coalesce(s.cancelled_at, s.updated_at, s.sold_at) >= now() - interval '2 hours')
  ),
  notas as (
    select v.id as sale_id,
           (prod->>'organizationProductId') as ext_pid,
           nullif(btrim(prod->>'comments'), '') as note
    from vivos v
    cross join lateral (
      select safe_jsonb(v.raw_tab) as tab
    ) rt
    cross join lateral (
      select coalesce(rt.tab -> 'products', rt.tab -> 'bills' -> 0 -> 'products') as products
    ) p
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(p.products) = 'array' then p.products else '[]'::jsonb end
    ) as prod
    where nullif(btrim(prod->>'comments'), '') is not null
      and (prod->>'organizationProductId') is not null
  ),
  padres as (
    select sl.sale_id, sl.id as line_id, sl.product_name, sl.quantity,
           sl.line_type, sl.menu_item_id, sl.external_product_id, sl.kitchen_note,
           coalesce(
             ri.kds_station_id,
             (select fr.station_id from kitchen_family_route fr
               where fr.account_id = v_account_id and fr.family_id = ri.family_id limit 1),
             v_default_station
           ) as station_id,
           coalesce(ls.marked, false) as marked,
           array(select allergen_code from recipe_item_allergen a
                  where a.recipe_item_id = ri.id and a.state = 'contains') as allergens
    from sale_line sl
    left join menu_item mi on mi.id = sl.menu_item_id
    left join recipe_item ri on ri.id = mi.recipe_item_id
    left join kds_line_state ls on ls.sale_line_id = sl.id
    where sl.sale_id in (select id from vivos)
      and sl.parent_sale_line_id is null
  ),
  hijas as (
    select sl.parent_sale_line_id, sl.sale_id, sl.id as line_id,
           sl.product_name, sl.quantity, sl.line_type, sl.external_product_id
    from sale_line sl
    where sl.sale_id in (select id from vivos)
      and sl.parent_sale_line_id is not null
  ),
  tickets as (
    select v.id as sale_id, v.external_ref, v.external_tab_ref, v.status,
           b.name as brand,
           b.logo_url as brand_logo_url, b.color as brand_color,
           coalesce(ch.name, v.external_channel_text) as channel, v.entro_at,
           round(extract(epoch from (now() - v.entro_at)) / 60.0)::int as minutos,
           coalesce((select jsonb_agg(jsonb_build_object(
                'line_id', l.line_id, 'name', l.product_name, 'qty', l.quantity,
                'menu_item_id', l.menu_item_id,
                'station_id', l.station_id, 'marked', l.marked, 'allergens', l.allergens,
                'has_recipe', (l.menu_item_id is not null),
                'customer_note', coalesce((select n.note from notas n where n.sale_id = l.sale_id and n.ext_pid = l.external_product_id limit 1), l.kitchen_note),
                'children', coalesce((
                  select jsonb_agg(jsonb_build_object(
                           'line_id', h.line_id, 'name', h.product_name, 'qty', h.quantity,
                           'line_type', h.line_type,
                           'customer_note', (
                             select n2.note from notas n2
                              where n2.sale_id = h.sale_id and n2.ext_pid = h.external_product_id limit 1
                           )
                         ) order by h.line_id)
                  from hijas h where h.parent_sale_line_id = l.line_id
                ), '[]'::jsonb)
            ) order by l.product_name)
            from padres l where l.sale_id = v.id), '[]'::jsonb) as lineas,
           (select jsonb_object_agg(st.station_id, st.status)
            from kds_ticket_station_state st where st.sale_id = v.id) as estaciones
    from vivos v
    left join brand b on b.id = v.brand_id
    left join sales_channel ch on ch.id = v.channel_id
  )
  select jsonb_build_object(
    'location_id', v_location_id,
    'station_filter', to_jsonb(v_station_filter),
    'default_station_id', v_default_station,
    'expo_station_id', (select id from kitchen_station
                         where location_id = v_location_id and kind='expo' and is_active
                         order by display_order limit 1),
    'stations', (
      select coalesce(jsonb_agg(jsonb_build_object(
                'id', k.id, 'name', k.name, 'kind', k.kind,
                'display_order', k.display_order, 'is_default', k.is_default
              ) order by k.display_order), '[]'::jsonb)
      from kitchen_station k
      where k.account_id = v_account_id and k.location_id = v_location_id and k.is_active
    ),
    'now', now(),
    'tickets', coalesce(jsonb_agg(to_jsonb(t) order by t.entro_at) filter (where t.sale_id is not null), '[]'::jsonb)
  ) into v_result
  from tickets t;

  return v_result;
end;
$$;


--
-- Name: kds_bump(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_bump(p_sale_id uuid, p_station_id uuid, p_token text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account   uuid;
  v_loc       uuid;
  v_is_expo   boolean;
  v_service   text;
  v_cur       text;
  v_next      text;
begin
  select location_id into v_loc from sale where id = p_sale_id;
  if v_loc is null then raise exception 'kds_bump: venta inexistente'; end if;

  v_account := public.kds_authorize(v_loc, p_token);

  if not exists (select 1 from kitchen_station k
                 where k.id = p_station_id and k.account_id = v_account and k.location_id = v_loc) then
    raise exception 'kds_bump: estación no válida para esta ubicación';
  end if;

  insert into kds_ticket_station_state (account_id, sale_id, station_id, status, updated_at)
  values (v_account, p_sale_id, p_station_id, 'done', now())
  on conflict (sale_id, station_id)
  do update set status = 'done', updated_at = now();

  select (k.kind = 'expo') into v_is_expo
  from kitchen_station k where k.id = p_station_id;

  if coalesce(v_is_expo, false) then
    select service_type, order_status into v_service, v_cur from sale where id = p_sale_id;

    if v_cur in ('new','received','accepted','in_preparation') then
      v_next := case
                  -- pickup y plataforma: listo esperando recogida (cliente o rider)
                  when v_service = 'pickup'            then 'awaiting_collection'
                  when v_service = 'platform_delivery' then 'awaiting_collection'
                  -- reparto propio (y NULL): sale a reparto, Folvy sigue el pedido
                  else 'in_delivery'
                end;

      update sale
      set order_status = v_next,
          updated_at   = now()
      where id = p_sale_id;
    end if;
  end if;
end;
$$;


--
-- Name: kds_device_bundle_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_device_bundle_status(p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(device_id uuid, label text, local text, is_active boolean, app_version text, bundle_actual integer, ultimo_bundle integer, atraso_bundles integer, horas_desfase integer, last_seen_at timestamp with time zone, estado text, aplicado_en timestamp with time zone, en_ventana boolean, cocina_en_calma boolean, motivo_espera text, instalado_a_mano_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_ultimo int;
begin
  select b.bundle_id into v_ultimo from public._ultimo_bundle_publicado() b;

  return query
  with d as (
    select dev.id, dev.label, coalesce(l.name, 'sin local') as loc, dev.is_active,
           dev.app_version, dev.last_seen_at, dev.account_id, dev.location_id,
           dev.bundle_applied, dev.bundle_applied_at, dev.instalado_a_mano_at,
           -- La columna manda; el texto libre es el respaldo mientras quede
           -- alguna tablet sin el paquete que sabe reportarla.
           coalesce(dev.bundle_applied,
                    (regexp_match(dev.app_version, '· bundle (\d+)'))[1]::int) as b_actual,
           (dev.bundle_applied is null
            and dev.app_version is not null
            and dev.app_version !~ '· bundle \d+')                             as es_builtin
    from kds_device dev
    left join locations l on l.id = dev.location_id
    where dev.account_id = any(public.current_user_account_ids())
      and (p_location_id is null or dev.location_id = p_location_id)
  ),
  -- Las dos llaves se preguntan UNA VEZ POR LOCAL, no por dispositivo: son del
  -- local, no del aparato, y asi dos tablets del mismo sitio no pueden dar
  -- respuestas distintas a la misma pregunta.
  llaves as (
    select dl.location_id,
           (public._ventana_de_mantenimiento(dl.location_id)->>'en_ventana')::boolean as en_ventana,
           (public._ventana_de_mantenimiento(dl.location_id)->>'motivo')              as motivo_ventana,
           (public._cocina_en_calma(dl.location_id)->>'safe')::boolean                as en_calma
    from (select distinct d.location_id from d where d.location_id is not null) dl
  ),
  horas as (
    select d.id,
           case when d.b_actual is not null and v_ultimo > d.b_actual then (
             select round(extract(epoch from (now() - min(o.created_at)))/3600)::int
             from storage.objects o
             where o.bucket_id = 'apps' and o.name ~ '^bundle-\d+\.zip$'
               and (regexp_replace(o.name, '\D', '', 'g'))::int > d.b_actual
           ) end as h
    from d
  )
  select
    d.id, d.label, d.loc, d.is_active, d.app_version,
    d.b_actual, v_ultimo,
    case when d.b_actual is not null then v_ultimo - d.b_actual end,
    h.h,
    d.last_seen_at,
    case
      when d.es_builtin                       then 'builtin'
      when d.b_actual is null                 then 'desconocido'
      when d.b_actual >= v_ultimo             then 'al_dia'
      when coalesce(h.h, 0) >= 24             then 'muy_atrasado'
      else 'atrasado'
    end,
    d.bundle_applied_at,
    k.en_ventana,
    k.en_calma,
    -- POR QUE esta esperando. Solo tiene sentido si va por detras: al dia no
    -- espera a nada, y poner un motivo ahi seria ruido con cara de dato.
    case
      when d.b_actual is not null and d.b_actual >= v_ultimo then null
      when not d.is_active                                   then 'aparato_apagado'
      when d.last_seen_at is null
        or d.last_seen_at < now() - interval '30 minutes'     then 'no_da_senales'
      when k.en_ventana is not true                          then coalesce(k.motivo_ventana, 'fuera_de_ventana')
      when k.en_calma is not true                            then 'cocina_ocupada'
      else 'a_punto_de_instalarse'
    end,
    d.instalado_a_mano_at
  from d
  left join llaves k on k.location_id = d.location_id
  left join horas  h on h.id = d.id
  order by
    case when d.b_actual is null then 0 else 1 end,
    d.b_actual asc nulls first, d.label;
end;
$_$;


--
-- Name: FUNCTION kds_device_bundle_status(p_location_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kds_device_bundle_status(p_location_id uuid) IS 'Estado de cada tablet para la pantalla de oficina: que paquete corre, desde cuando, POR QUE espera si va por detras, y si alguien se salto la ventana a mano.';


--
-- Name: kds_device_silence_check(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_device_silence_check(p_minutos integer DEFAULT 10, p_ahora timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ahora     timestamptz := coalesce(p_ahora, now());
  v_umbral    int         := greatest(p_minutos, 3);
  v_d         record;
  v_serv      jsonb;
  v_estado    text;
  v_desde     timestamptz;
  v_ref       timestamptz;
  v_min       int;
  v_n         int := 0;   -- avisadas
  v_calla     int := 0;   -- calladas con el local cerrado (no se avisan, pero se cuentan)
  v_coletilla text;
begin
  for v_d in
    select d.id, d.label, d.account_id, d.location_id, d.app_version, d.last_seen_at,
           coalesce(l.name, 'sin local') as local
      from kds_device d
      left join locations l on l.id = d.location_id
     where d.is_active
       and d.last_seen_at is not null
  loop
    v_serv   := public._servicio_del_local(v_d.location_id, v_ahora);
    v_estado := v_serv->>'estado';
    v_desde  := nullif(v_serv->>'desde', '')::timestamptz;

    -- CERRADO DECLARADO es el único estado que calla. La ausencia de horario
    -- nunca calla: no saber si están trabajando no es saber que no lo están.
    if v_estado = 'cerrado_declarado' then
      if v_d.last_seen_at < v_ahora - make_interval(mins => v_umbral) then
        v_calla := v_calla + 1;
      end if;
      continue;
    end if;

    -- El silencio se cuenta desde que abre, no desde el último latido: lo que
    -- pasa con la tablet apagada fuera de servicio no es noticia de nadie.
    v_ref := greatest(v_d.last_seen_at, coalesce(v_desde, v_d.last_seen_at));
    v_min := round(extract(epoch from (v_ahora - v_ref)) / 60)::int;

    continue when v_min < v_umbral;

    v_coletilla := case v_estado
      when 'en_servicio' then
        'Lleva ' || v_min || ' minutos sin dar senal de vida en horario de servicio'
        || case when v_desde is not null and v_d.last_seen_at < v_desde
                then ' (se cuenta desde que abrio el local, no desde su ultimo latido)' else '' end
        || '. '
      when 'sin_horario_declarado_hoy' then
        'Lleva ' || v_min || ' minutos sin dar senal de vida. Este local NO tiene horario '
        || 'declarado para hoy, asi que no se puede saber si estabais trabajando: se avisa por '
        || 'si acaso. Declarar el horario de hoy hace que este aviso deje de salir en balde. '
      else
        'Lleva ' || v_min || ' minutos sin dar senal de vida. Este local no tiene ningun horario '
        || 'declarado, asi que no se puede saber si estabais trabajando: se avisa por si acaso. '
      end;

    v_n := v_n + 1;
    raise warning 'kds_device_silence_check: % (%) lleva % min sin latir [%]',
                  v_d.label, v_d.local, v_min, v_estado;

    perform public.encolar_alerta(
      'kds_device_silencio',
      'Tablet sin senal: ' || v_d.label || ' (' || v_d.local || ')',
      'La tablet "' || v_d.label || '" del local ' || v_d.local || '. ' || v_coletilla
      || 'Version: ' || coalesce(v_d.app_version, 'desconocida') || '. '
      || 'Si la pantalla pide vincular, apagar y encender la tablet suele bastar. '
      || 'Mientras tanto los pedidos SIGUEN entrando en Folvy y se pueden ver desde cualquier '
      || 'movil u ordenador en Pedidos.',
      'kds_silencio_' || v_d.id::text,
      interval '4 hours',
      v_d.account_id,
      v_d.location_id,
      null::uuid,
      'alto'
    );
  end loop;

  -- Regla 7: el umbral decide a quién se INTERRUMPE, nunca qué existe. Las
  -- calladas con el local cerrado no avisan, pero se dicen en el log del cron.
  if v_calla > 0 then
    raise notice 'kds_device_silence_check: % tablet(s) calladas con el local cerrado, no se avisan', v_calla;
  end if;

  return v_n;
end;
$$;


--
-- Name: kds_device_stale_bundle_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_device_stale_bundle_check() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $_$
declare
  v_ultimo int;
  v_d      record;
  v_n      int := 0;
  v_txt    text;
begin
  select b.bundle_id into v_ultimo from public._ultimo_bundle_publicado() b;
  if v_ultimo is null then
    raise warning 'kds_device_stale_bundle_check: no hay ningun bundle en el bucket apps';
    return 0;
  end if;

  for v_d in
    select dev.id, dev.label, coalesce(l.name,'sin local') as loc, dev.account_id,
           dev.app_version,
           (regexp_match(dev.app_version, '· bundle (\d+)'))[1]::int as b_actual,
           (dev.app_version is not null and dev.app_version !~ '· bundle \d+') as es_builtin
    from kds_device dev
    left join locations l on l.id = dev.location_id
    where dev.is_active
      and dev.app_version is not null
  loop
    -- DM1 · PR 2a (31/10): una cuenta de demo no cuenta en los vigías.
    continue when not public.cuenta_puede_salir(v_d.account_id);
    v_txt := null;

    if v_d.es_builtin then
      v_txt := 'Nunca ha aplicado ninguna actualizacion: sigue con el codigo empotrado en el APK. '
            || 'Es la version mas antigua que puede correr un aparato.';
    elsif v_d.b_actual is null then
      v_txt := 'No se ha podido leer que version corre (reporta "' || v_d.app_version || '"). '
            || 'Mientras no se pueda leer, este aparato NO esta vigilado.';
    elsif v_d.b_actual < v_ultimo then
      declare v_h int;
      begin
        select round(extract(epoch from (now() - min(o.created_at)))/3600)::int into v_h
        from storage.objects o
        where o.bucket_id = 'apps' and o.name ~ '^bundle-\d+\.zip$'
          and (regexp_replace(o.name,'\D','','g'))::int > v_d.b_actual;
        if v_h >= 24 then
          v_txt := 'Corre el bundle ' || v_d.b_actual || ' y el ultimo publicado es el ' || v_ultimo
                || ' (' || (v_ultimo - v_d.b_actual) || ' por detras). '
                || 'Hay version mas nueva desde hace ' || v_h || ' horas y no la ha cogido.';
        end if;
      end;
    end if;

    continue when v_txt is null;

    v_n := v_n + 1;
    raise warning 'kds_device_stale_bundle_check: % (%) desfasado', v_d.label, v_d.loc;

    perform public._queue_system_alert(
      'kds_device_desfasado',
      'Tablet con codigo viejo: ' || v_d.label || ' (' || v_d.loc || ')',
      'La tablet "' || v_d.label || '" del local ' || v_d.loc || ' esta sirviendo comandas con '
      || 'codigo antiguo. ' || v_txt || ' '
      || 'Late y contesta con normalidad, que es lo que hace esto dificil de notar. '
      || 'Suele bastar con dejarla encendida y con red un rato fuera de servicio: la '
      || 'actualizacion se aplica sola en ventana segura, nunca en mitad de un pedido.',
      'kds_desfasado_' || v_d.id::text,
      interval '20 hours'
    );
  end loop;

  return v_n;
end;
$_$;


--
-- Name: kds_heartbeat(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_heartbeat(p_token text, p_app_version text DEFAULT NULL::text, p_platform text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
begin
  v_device := public.kds_resolve_device(p_token);
  if v_device.id is null then
    return false;
  end if;
  update kds_device
  set last_seen_at   = now(),
      app_version    = coalesce(nullif(btrim(coalesce(p_app_version, '')), ''), app_version),
      platform       = coalesce(nullif(btrim(coalesce(p_platform, '')), ''), platform),
      app_version_at = case when nullif(btrim(coalesce(p_app_version, '')), '') is not null then now() else app_version_at end,
      updated_at     = now()
  where id = v_device.id
    and (last_seen_at is null or last_seen_at < now() - interval '10 seconds');
  return true;
end;
$$;


--
-- Name: FUNCTION kds_heartbeat(p_token text, p_app_version text, p_platform text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kds_heartbeat(p_token text, p_app_version text, p_platform text) IS 'Unico RPC pensado para escribir kds_device.last_seen_at (fix/kds-latido-raiz, 11/08). Llamado por un solo setInterval de cliente. Hasta aplicar 20260816T0901 conviven con el las 13 funciones de lectura que aun escriben por su cuenta (mitigacion de emergencia del 11/08, freno de 30s).';


--
-- Name: kds_mark_line(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_mark_line(p_sale_line_id uuid, p_token text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
  v_loc     uuid;
  v_new     boolean;
begin
  select s.location_id, s.account_id into v_loc, v_account
  from sale_line sl join sale s on s.id = sl.sale_id
  where sl.id = p_sale_line_id;
  if v_loc is null then raise exception 'kds_mark_line: línea inexistente'; end if;
  perform public.kds_authorize(v_loc, p_token);

  insert into kds_line_state (account_id, sale_line_id, marked, marked_at, updated_at)
  values (v_account, p_sale_line_id, true, now(), now())
  on conflict (sale_line_id)
  do update set marked = not kds_line_state.marked,
                marked_at = case when not kds_line_state.marked then now() else null end,
                updated_at = now()
  returning marked into v_new;
  return v_new;
end;
$$;


--
-- Name: kds_recipe(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_recipe(p_menu_item_id uuid, p_qty numeric DEFAULT 1, p_token text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ri      uuid;
  v_account uuid;
  v_qty     numeric := greatest(coalesce(p_qty, 1), 1);
  v_loc     uuid := p_location_id;
  v_device  kds_device;
  v_result  jsonb;
begin
  select mi.recipe_item_id, mi.account_id into v_ri, v_account
  from menu_item mi where mi.id = p_menu_item_id;
  if v_ri is null then
    return jsonb_build_object('found', false);
  end if;

  if p_token is not null then
    v_device := public.kds_resolve_device(p_token);
    if v_device.id is null then raise exception 'kds_recipe: token no válido'; end if;
    if v_loc is null then v_loc := v_device.location_id; end if;
    if v_device.account_id <> v_account then
      raise exception 'kds_recipe: el plato no pertenece a la cuenta del dispositivo';
    end if;
    
  else
    if not belongs_to_account(v_account) then
      raise exception 'kds_recipe: sin acceso';
    end if;
  end if;

  select jsonb_build_object(
    'found', true,
    'qty', v_qty,
    'photo_url', coalesce(
      (select kitchen_photo_url from recipe_item where id = v_ri),
      (select photo_url from menu_item where id = p_menu_item_id)
    ),
    'allergens', (
      select coalesce(jsonb_agg(jsonb_build_object('code', allergen_code, 'state', state)
                                order by allergen_code), '[]'::jsonb)
      from recipe_item_allergen where recipe_item_id = v_ri and state in ('contains','may_contain')
    ),
    'ingredients', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'name', child.name,
        'unit', u.abbreviation,
        'qty_base', coalesce(rl.quantity_gross, rl.quantity_net),   -- 28/08/2026: sin bruto declarado, el bruto ES el neto
        'qty_total', round(coalesce(rl.quantity_gross, rl.quantity_net) * v_qty, 3),
        'cut', ct.name
      ) order by rl.position), '[]'::jsonb)
      from recipe_line rl
      join recipe_item child on child.id = rl.child_item_id
      left join kitchen_unit u on u.id = rl.unit_id
      left join kitchen_cut_type ct on ct.id = rl.cut_type_id
      where rl.parent_item_id = v_ri
    ),
    'steps', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'position', st.position, 'text', st.text, 'kind', st.kind,
        'duration_min', st.duration_min, 'temperature_c', st.temperature_c,
        'photo_url', st.photo_url,
        'ingredients', (
          select coalesce(jsonb_agg(ci.name order by ci.name), '[]'::jsonb)
          from recipe_item_step_line sln
          join recipe_line rl2 on rl2.id = sln.line_id
          join recipe_item ci on ci.id = rl2.child_item_id
          where sln.step_id = st.id
        )
      ) order by st.position), '[]'::jsonb)
      from recipe_item_step st where st.recipe_item_id = v_ri
    )
  ) into v_result;

  return v_result;
end;
$$;


--
-- Name: kds_device; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.kds_device (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    label text NOT NULL,
    token text NOT NULL,
    station_ids uuid[],
    is_active boolean DEFAULT true NOT NULL,
    last_seen_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    device_mode text DEFAULT 'estacion'::text NOT NULL,
    app_version text,
    platform text,
    app_version_at timestamp with time zone,
    model text,
    bundle_applied integer,
    bundle_applied_at timestamp with time zone,
    instalado_a_mano_at timestamp with time zone,
    CONSTRAINT kds_device_device_mode_chk CHECK ((device_mode = ANY (ARRAY['estacion'::text, 'equipo'::text, 'gestion'::text])))
);


--
-- Name: COLUMN kds_device.device_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.device_mode IS 'Modo del dispositivo: estacion (imprime/cocina) | equipo | gestion. Sólo estacion reclama la cola de impresión.';


--
-- Name: COLUMN kds_device.app_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.app_version IS 'versionName/versionCode de la APK instalada, reportado por la propia app al arrancar.';


--
-- Name: COLUMN kds_device.platform; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.platform IS 'Plataforma del dispositivo: android | ios | web.';


--
-- Name: COLUMN kds_device.app_version_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.app_version_at IS 'Cuándo reportó por última vez su versión (para detectar tablets rezagadas).';


--
-- Name: COLUMN kds_device.model; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.model IS 'C9 L2 §4: modelo del dispositivo, tal y como lo reporta el. Sirve para poder separar «lee mal porque la tablet es vieja» de «lee mal porque la etiqueta esta mal pegada» cuando L3 empiece a dar numeros por local.';


--
-- Name: COLUMN kds_device.bundle_applied; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.bundle_applied IS 'Numero del paquete OTA que corre AHORA en este dispositivo. Lo escribe report_device_bundle_applied AL ARRANCAR el paquete, no al aplicarlo.';


--
-- Name: COLUMN kds_device.bundle_applied_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.bundle_applied_at IS 'Cuando EMPEZO A CORRER ese paquete aqui. OJO AL MATIZ, que ya nos costo caro con app_version_at: se sella AL ARRANCAR el paquete nuevo (que es la unica prueba de que se aplico: si no arrancara, Capgo vuelve al anterior), NO al aplicarlo. Entre aplicar y arrancar hay un hueco de segundos en el que esta columna dice todavia lo viejo, y eso es correcto. Solo se mueve cuando bundle_applied cambia: un reinicio con el mismo paquete no la toca.';


--
-- Name: COLUMN kds_device.instalado_a_mano_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kds_device.instalado_a_mano_at IS 'La ultima vez que alguien pulso «Instalar ahora» en ESTA tablet. Ese boton es el unico camino que se salta la ventana de mantenimiento, asi que deja rastro. Se sella AL PULSAR, no al arrancar: que una persona lo pidiera es verdad aunque el paquete luego no arranque.';


--
-- Name: kds_resolve_device(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_resolve_device(p_token text) RETURNS public.kds_device
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from kds_device
  where token = p_token and is_active = true
  limit 1;
$$;


--
-- Name: kds_set_default_station(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_set_default_station(p_location_id uuid, p_station_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
begin
  -- la estación debe existir, estar activa y pertenecer al local
  select account_id into v_account from kitchen_station
   where id = p_station_id and location_id = p_location_id and is_active;
  if v_account is null then
    raise exception 'kds_set_default_station: estación no válida para el local';
  end if;

  -- guard de sesión: el usuario debe poder gestionar esta cuenta
  if not current_user_is_admin_or_manager_of(v_account) then
    raise exception 'kds_set_default_station: sin permiso';
  end if;

  -- Cambio atómico en un único UPDATE: la elegida pasa a true, el resto del
  -- local a false. Un solo statement → el índice parcial nunca ve dos true.
  update kitchen_station
     set is_default = (id = p_station_id),
         updated_at = now()
   where location_id = p_location_id
     and is_default is distinct from (id = p_station_id);
end;
$$;


--
-- Name: kds_unbump(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_unbump(p_sale_id uuid, p_station_id uuid, p_token text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_loc uuid;
begin
  select location_id into v_loc from sale where id = p_sale_id;
  if v_loc is null then raise exception 'kds_unbump: venta inexistente'; end if;
  perform public.kds_authorize(v_loc, p_token);
  update kds_ticket_station_state
  set status = 'pending', updated_at = now()
  where sale_id = p_sale_id and station_id = p_station_id;
end;
$$;


--
-- Name: kiosko_comprobar_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kiosko_comprobar_pin(p_employee_id uuid, p_pin text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid; v_pin text;
begin
  select e.account_id into v_cuenta from public.employees e where e.id = p_employee_id;
  if v_cuenta is null or not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501';
  end if;
  select k.pin into v_pin from public.employee_kiosk_pin k where k.employee_id = p_employee_id;
  return v_pin is not null and v_pin = btrim(coalesce(p_pin, ''));
end $$;


--
-- Name: kiosko_con_pin(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kiosko_con_pin(p_employee_ids uuid[]) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select k.employee_id from public.employee_kiosk_pin k join public.employees e on e.id = k.employee_id
   where k.employee_id = any (p_employee_ids) and public.current_user_is_admin_or_manager_of(e.account_id)
$$;


--
-- Name: kitchen_ancestors_of(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_ancestors_of(p_item_id uuid) RETURNS TABLE(ancestor_id uuid, depth integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
begin
  select account_id into v_account_id from recipe_item where id = p_item_id;
  if not found then
    raise exception 'kitchen_ancestors_of: item % no existe', p_item_id;
  end if;

  -- La misma guarda que kitchen_recompute_item, que es el paso siguiente de la
  -- cascada: ser de la cuenta del artículo (L00, 27/10). Antes pedía ser
  -- administrador o encargado, y la cascada de un trabajador que recibe un
  -- albarán se paraba aquí.
  if not public.belongs_to_account(v_account_id) then
    raise exception 'kitchen_ancestors_of: sin acceso al item %', p_item_id;
  end if;

  return query
  with recursive ancestros as (
    -- Nivel 1: quién usa p_item_id directamente.
    select rl.parent_item_id as ancestor_id, 1 as depth
    from recipe_line rl
    where rl.child_item_id = p_item_id
    union
    -- Niveles superiores: quién usa a esos ancestros.
    select rl.parent_item_id, a.depth + 1
    from recipe_line rl
    join ancestros a on rl.child_item_id = a.ancestor_id
  )
  -- Si un ítem aparece a varias profundidades (lo usa por dos caminos), nos
  -- quedamos con la MÁS profunda: se recalcula después de todos sus hijos. La
  -- app ordena por depth DESC.
  select anc.ancestor_id, max(anc.depth) as depth
  from ancestros anc
  group by anc.ancestor_id
  order by max(anc.depth) desc;
end;
$$;


--
-- Name: kitchen_aplicar_a_las_iguales(uuid, uuid[], jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_aplicar_a_las_iguales(p_account uuid, p_opciones uuid[], p_efecto jsonb, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tipo   text := nullif(p_efecto->>'tipo','');
  v_ficha  uuid := nullif(p_efecto->>'ficha','')::uuid;
  v_mala   text;
  v_op     uuid;
  v_n      int := 0;
  v_ced    int := 0;
  v_nombres text[] := '{}';
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para decidir qué llevan los extras de la cuenta %', p_account
      using errcode = '42501';
  end if;

  if p_opciones is null or array_length(p_opciones,1) is null then
    raise exception 'No se ha elegido ninguna respuesta.' using errcode = '22023';
  end if;
  if v_tipo is null then
    raise exception 'No se ha dicho qué lleva.' using errcode = '22023';
  end if;
  if v_tipo not in ('add_item','remove_item','replace_item','multiply','bundle','none') then
    raise exception 'El efecto «%» no existe. No se ha escrito nada.', v_tipo using errcode = '22023';
  end if;

  -- 🔴 SIN CANTIDAD NO DESCUENTA NADA (13/09). Aqui pesa el doble: un efecto
  -- a medias repartido en lote son N respuestas que dicen «decidida» y
  -- descuentan cero, no una.
  if not public._impacto_completo(v_tipo, v_ficha,
                                  nullif(p_efecto->>'cantidad','')::numeric) then
    raise exception
      'Al efecto le falta el articulo o la cantidad: asi no descontaria nada del almacen, aunque las respuestas quedaran como decididas. No se ha escrito nada.'
      using errcode = '22023';
  end if;

  -- CONDICION 2 · SOLO DE ESTA CUENTA, y se ABORTA entero si alguna no lo es.
  -- Un lote que se salta filas en silencio es peor que uno que falla: quien lo
  -- lanza cree que ha resuelto 7 y ha resuelto 4.
  --
  -- 🔴 AQUI ESTABA TAMBIEN LA MARCA CEDIDA, Y SE QUITA (14/09). Abortaba con
  -- «La carta de X la manda Last: sus respuestas no se tocan aqui». Lo que se
  -- escribe aqui no es la carta: es la FICHA, que es nuestra y que el
  -- importador no pisa (18 de 37 medidas, tocadas despues y con ficha intacta).
  -- Y la puerta de una en una --`kitchen_extras_poner_lo_que_lleva`-- nunca
  -- miro `ownership_type`: por ahi se escribieron esas 37. Este aborto no
  -- protegia nada; hacia que dos puertas dijeran lo contrario que la tercera.
  --
  -- Lo que SIGUE cerrado en cedidas es el catalogo: nombre, precio, alta en
  -- platos y retirada. Ver la cabecera del fichero.
  if exists (select 1 from unnest(p_opciones) x(id)
              where not exists (select 1 from modifier_option o
                                 where o.id = x.id and o.account_id = p_account)) then
    raise exception 'Alguna respuesta no es de esta cuenta. No se ha escrito nada.'
      using errcode = '42501';
  end if;

  -- La ficha, viva y de la cuenta. Mismo criterio que el resto: una archivada
  -- tiene el precio del dia en que se archivo.
  if v_ficha is not null then
    select ri.name into v_mala from recipe_item ri
     where ri.id = v_ficha
       and (ri.account_id <> p_account or not ri.is_active or ri.archived_at is not null);
    if v_mala is not null then
      raise exception 'La ficha «%» está archivada o no es de esta cuenta. No se ha escrito nada.', v_mala
        using errcode = '42501';
    end if;
    if not exists (select 1 from recipe_item ri where ri.id = v_ficha) then
      raise exception 'Esa ficha no existe. No se ha escrito nada.' using errcode = '42501';
    end if;
  end if;

  -- CONDICION 3 · RASTRO POR FILA. Se escribe una a una, con su quien y su
  -- cuando, igual que si se hubieran hecho a mano de una en una.
  foreach v_op in array p_opciones loop
    delete from modifier_recipe_impact
     where modifier_option_id = v_op and account_id = p_account and status = 'confirmed';

    insert into modifier_recipe_impact (
      account_id, modifier_option_id, impact_type, target_recipe_item_id,
      quantity, unit_id, status, source, rationale,
      confirmed_by, confirmed_by_name, confirmed_at)
    values (
      p_account, v_op, v_tipo, v_ficha,
      nullif(p_efecto->>'cantidad','')::numeric,
      nullif(p_efecto->>'unidad','')::uuid,
      'confirmed', 'human',
      'Decidido a la vez para las respuestas que se llaman igual',
      auth.uid(), p_actor, now());

    v_n := v_n + 1;
    -- Se cuentan las cedidas para poder DECIRLO en la confirmacion (regla 8):
    -- «resuelta en 4 sitios, 1 de ellos una marca que manda Last» dice algo.
    select array_append(v_nombres, b.name || ' · ' || g.name),
           v_ced + (case when coalesce(b.ownership_type,'own') <> 'own' then 1 else 0 end)
      into v_nombres, v_ced
      from modifier_option o
      join modifier_group g on g.id = o.modifier_group_id
      left join brand b on b.id = g.brand_id
     where o.id = v_op;
  end loop;

  return jsonb_build_object(
    'resueltas', v_n,
    'cedidas',   v_ced,
    'donde',     to_jsonb(v_nombres),
    'efecto',    v_tipo,
    'actor',     p_actor);
end;
$$;


--
-- Name: FUNCTION kitchen_aplicar_a_las_iguales(p_account uuid, p_opciones uuid[], p_efecto jsonb, p_actor text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_aplicar_a_las_iguales(p_account uuid, p_opciones uuid[], p_efecto jsonb, p_actor text) IS 'Aplica el mismo «que lleva» a las respuestas ELEGIDAS que se llaman igual. Solo marcas propias, aborta entero si alguna no lo es o si el efecto no descontaria nada, y deja rastro por fila.';


--
-- Name: kitchen_archive_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_archive_item(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item recipe_item%rowtype;
begin
  select * into v_item from recipe_item where id = p_item_id;
  if not found then
    raise exception 'kitchen_archive_item: item % no existe', p_item_id;
  end if;
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_item.account_id)) then
    raise exception 'kitchen_archive_item: sin acceso al item %', p_item_id;
  end if;

  update recipe_item
     set is_active = false, archived_at = coalesce(archived_at, now())
   where id = p_item_id;

  return jsonb_build_object('action', 'archived', 'name', v_item.name);
end;
$$;


--
-- Name: kitchen_batch_yield(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_batch_yield(p_item_id uuid) RETURNS TABLE(yield_in_base numeric, base_unit_id uuid, is_declared boolean, unmeasured_lines integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item recipe_item%ROWTYPE;
  v_base kitchen_unit%ROWTYPE;
BEGIN
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kitchen_batch_yield: item % no existe', p_item_id;
  END IF;
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(v_item.account_id)) THEN
    RAISE EXCEPTION 'kitchen_batch_yield: sin acceso al item %', p_item_id;
  END IF;

  SELECT * INTO v_base FROM kitchen_unit WHERE id = v_item.base_unit_id;

  yield_in_base := public._batch_yield_in_base(p_item_id);
  base_unit_id  := v_item.base_unit_id;
  is_declared   := (v_item.batch_yield IS NOT NULL AND v_item.batch_yield > 0);

  SELECT COUNT(*) INTO unmeasured_lines
  FROM recipe_line rl
  JOIN kitchen_unit lu ON lu.id = rl.unit_id
  WHERE rl.parent_item_id = p_item_id
    AND (v_base.id IS NULL OR lu.dimension <> v_base.dimension);

  RETURN NEXT;
END;
$$;


--
-- Name: kitchen_buscar(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_buscar(p_account uuid, p_texto text, p_tope integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_q    text;
  v_like text;
  v_tope int := greatest(least(coalesce(p_tope, 12), 100), 1);
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para buscar en la cuenta %', p_account
      using errcode = '42501';
  end if;

  v_q := btrim(coalesce(p_texto, ''));
  -- Con una letra sale media carta y no sirve de nada. Se dice por que, en
  -- vez de devolver una lista vacia que parece una averia.
  if length(v_q) < 2 then
    return jsonb_build_object(
      'texto', v_q, 'tope', v_tope,
      'preguntas', '[]'::jsonb, 'respuestas', '[]'::jsonb, 'platos', '[]'::jsonb,
      'fichas', '[]'::jsonb,
      'cuantas', jsonb_build_object('preguntas', 0, 'respuestas', 0,
                                    'respuestas_distintas', 0, 'platos', 0, 'fichas', 0),
      'corto', true);
  end if;

  v_like := '%' || replace(replace(v_q, '\', '\\'), '%', '\%') || '%';

  return (
    with fichas as (
      select ri.id, btrim(ri.name) as nombre
        from recipe_item ri
       where ri.account_id = p_account and ri.name ilike v_like
    ),
    -- Una respuesta sale por su NOMBRE o por LO QUE LLEVA. El motivo se guarda
    -- porque es lo que la fila tiene que decir.
    respuestas as (
      select o.id, btrim(o.name) as nombre, g.id as pregunta_id, btrim(g.name) as pregunta,
             coalesce(b.name, 'Sin marca') as marca,
             (coalesce(b.ownership_type,'own') <> 'own') as cedida,
             coalesce(o.is_active, true) as activa,
             (o.name ilike v_like) as por_nombre,
             (select f.nombre from modifier_recipe_impact i
                join fichas f on f.id = i.target_recipe_item_id
               where i.modifier_option_id = o.id and i.account_id = p_account
                 and i.status = 'confirmed'
               order by f.nombre limit 1) as ficha
        from modifier_option o
        join modifier_group g on g.id = o.modifier_group_id
        left join brand b on b.id = g.brand_id
       where o.account_id = p_account
         and (o.name ilike v_like
              or exists (select 1 from modifier_recipe_impact i
                           join fichas f on f.id = i.target_recipe_item_id
                          where i.modifier_option_id = o.id and i.account_id = p_account
                            and i.status = 'confirmed'))
    ),
    preguntas as (
      select g.id, btrim(g.name) as nombre,
             coalesce(b.name, 'Sin marca') as marca,
             (coalesce(b.ownership_type,'own') <> 'own') as cedida,
             coalesce(g.is_active, true) as activa,
             (g.name ilike v_like) as por_nombre,
             (select count(*) from respuestas r where r.pregunta_id = g.id) as respuestas_que_salen,
             (select count(*) from modifier_option o
               where o.modifier_group_id = g.id and coalesce(o.is_active,true)) as respuestas
        from modifier_group g
        left join brand b on b.id = g.brand_id
       where g.account_id = p_account
         and (g.name ilike v_like
              or exists (select 1 from respuestas r where r.pregunta_id = g.id))
    ),
    platos as (
      select mi.id, btrim(mi.name) as nombre,
             coalesce(b.name, 'Sin marca') as marca,
             (coalesce(b.ownership_type,'own') <> 'own') as cedida,
             (mi.name ilike v_like) as por_nombre,
             (select count(*) from modifier_group_assignment a
                join preguntas p2 on p2.id = a.modifier_group_id
               where a.menu_item_id = mi.id and a.account_id = p_account) as preguntas_que_salen
        from menu_item mi
        left join brand b on b.id = mi.brand_id
       where mi.account_id = p_account
         and mi.archived_at is null
         and (mi.name ilike v_like
              or exists (select 1 from modifier_group_assignment a
                           join preguntas p2 on p2.id = a.modifier_group_id
                          where a.menu_item_id = mi.id and a.account_id = p_account))
    ),
    -- LAS RESPUESTAS, AGRUPADAS POR NOMBRE. Sin esto la lista es inutil: con
    -- «harissa» las cinco primeras son la MISMA «Salsa Harissa (Picante)»
    -- copiada en cinco preguntas, y «Sin Salsa Harisa» --la que solo aparece
    -- por su ficha, que es el caso que justifica la pantalla-- se cae del
    -- corte. Agrupar por nombre es ademas como ya piensa el resto del gestor:
    -- «decidir una vez para todas las iguales».
    agrupadas as (
      select (array_agg(r.id order by r.marca, r.pregunta))[1] as id,
             min(r.nombre) as nombre,
             count(*) as copias,
             count(distinct r.pregunta_id) as preguntas,
             count(distinct r.marca) as marcas,
             bool_or(r.activa) as alguna_activa,
             bool_and(r.activa) as todas_activas,
             bool_or(r.por_nombre) as por_nombre,
             (array_agg(r.ficha) filter (where r.ficha is not null))[1] as ficha,
             (array_agg(r.marca order by r.marca))[1] as marca
        from respuestas r
       group by lower(btrim(r.nombre))
    )
    select jsonb_build_object(
      'texto', v_q, 'tope', v_tope, 'corto', false,
      -- LOS TOTALES SON LOS DE VERDAD. La lista de abajo va cortada; esto no.
      'cuantas', jsonb_build_object(
        'fichas',     (select count(*) from fichas),
        'preguntas',  (select count(*) from preguntas),
        -- Las dos cifras: las filas que hay y los nombres distintos. La
        -- pantalla ensena nombres; el total de filas va al lado para que
        -- nadie crea que hay 6 respuestas cuando hay 18 copias de 6.
        'respuestas', (select count(*) from respuestas),
        'respuestas_distintas', (select count(*) from agrupadas),
        'platos',     (select count(*) from platos)),
      'fichas', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nombre', f.nombre)
                                  order by f.nombre), '[]'::jsonb)
                   from (select * from fichas order by nombre limit v_tope) f),
      'preguntas', (select coalesce(jsonb_agg(jsonb_build_object(
                              'id', p.id, 'nombre', p.nombre, 'marca', p.marca,
                              'cedida', p.cedida, 'activa', p.activa,
                              'respuestas', p.respuestas,
                              'porque', case when p.por_nombre then 'se_llama_asi'
                                             else 'lleva_eso' end,
                              'cuantas_respuestas_salen', p.respuestas_que_salen)
                            order by (not p.por_nombre), p.marca, p.nombre), '[]'::jsonb)
                     from (select * from preguntas
                            order by (not por_nombre), marca, nombre limit v_tope) p),
      'respuestas', (select coalesce(jsonb_agg(jsonb_build_object(
                              'id', r.id, 'nombre', r.nombre,
                              'copias', r.copias, 'preguntas', r.preguntas,
                              'marcas', r.marcas, 'marca', r.marca,
                              'alguna_activa', r.alguna_activa,
                              'todas_activas', r.todas_activas,
                              'ficha', r.ficha,
                              'porque', case when r.por_nombre and r.ficha is not null then 'las_dos'
                                             when r.por_nombre then 'se_llama_asi'
                                             else 'lleva_eso' end)
                            order by (not r.por_nombre), r.nombre), '[]'::jsonb)
                      from (select * from agrupadas
                             order by (not por_nombre), nombre limit v_tope) r),
      'platos', (select coalesce(jsonb_agg(jsonb_build_object(
                              'id', pl.id, 'nombre', pl.nombre, 'marca', pl.marca,
                              'cedida', pl.cedida,
                              'porque', case when pl.por_nombre then 'se_llama_asi'
                                             else 'su_pregunta_lleva_eso' end,
                              'cuantas_preguntas_salen', pl.preguntas_que_salen)
                            order by (not pl.por_nombre), pl.marca, pl.nombre), '[]'::jsonb)
                  from (select * from platos
                         order by (not por_nombre), marca, nombre limit v_tope) pl))
  );
end;
$$;


--
-- Name: kitchen_buscar_ficha(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_buscar_ficha(p_account uuid, p_texto text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;

  -- SOLO FICHAS VIVAS. Una archivada tiene el precio del dia en que se
  -- archivo, y la funcion de guardar la rechaza: ofrecerla en el buscador
  -- seria enseñar algo que va a fallar al guardar.
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', ri.id, 'nombre', ri.name, 'unidad', ri.base_unit_id)
           order by ri.name), '[]'::jsonb)
      from recipe_item ri
     where ri.account_id = p_account
       and ri.is_active and ri.archived_at is null
       and (coalesce(btrim(p_texto),'') = ''
            or ri.name ilike '%' || btrim(p_texto) || '%')
     limit 40);
end;
$$;


--
-- Name: FUNCTION kitchen_buscar_ficha(p_account uuid, p_texto text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_buscar_ficha(p_account uuid, p_texto text) IS 'El buscador de articulos del escandallo para «que lleva». Solo fichas vivas: una archivada la rechaza el guardado.';


--
-- Name: kitchen_catalog_gaps(uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_catalog_gaps(p_account uuid, p_ventana interval DEFAULT '30 days'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  -- ── DOS JUEGOS DE DEFINICIONES, Y SOLO UNO SE PINTA (B83) ────────────────
  -- `d_*` es lo que VE EL CLIENTE: castellano de persona, sin una sola columna,
  -- sin SQL y sin inglés. `t_*` es la regla técnica: viaja en la salida para
  -- soporte y para poder auditar el número, pero NO SE PINTA.
  d_en_carta   constant text := 'Un plato está «en carta» si está activo y no se ha retirado del catálogo.';
  d_extras     constant text := 'Un extra que el cliente paga aparte y que, sumado lo que lleva, no añade ni un céntimo de coste. Cuenta también el que no tiene nada puesto.';
  d_sin_coste  constant text := 'Un plato de la carta del que Folvy no sabe lo que cuesta: o no tiene ficha de escandallo enlazada, o la tiene sin terminar.';
  d_sin_envase constant text := 'Un plato cuya ficha tiene el envase a cero, así que su coste no incluye lo que cuesta servirlo.';
  d_ingred     constant text := 'Un ingrediente en uso al que no se le ha puesto ningún precio, ni a mano ni por compras.';
  d_objetivo   constant text := 'La cuenta no tiene un objetivo de comida sobre ventas al que apuntar, así que ninguna cifra puede llamarse buena ni mala.';

  -- La regla técnica. Viaja, no se pinta.
  t_en_carta   constant text := 'menu_item de la cuenta con is_active IS NOT FALSE y archived_at IS NULL.';
  t_extras     constant text := 'modifier_option activa con price_impact > 0 cuyos modifier_recipe_impact en estado confirmed suman 0, incluidas las que no tienen ninguno. Misma consulta que el vigía modifier_zero_cost_watchdog.';
  t_sin_coste  constant text := 'menu_item en carta con recipe_item_id IS NULL, o con ficha cuyo recipe_item.computed_cost IS NULL. Con coste = computed_cost IS NOT NULL.';
  t_sin_envase constant text := 'menu_item en carta cuya recipe_item.packaging_cost es NULL o 0.';
  t_ingred     constant text := 'recipe_item de tipo raw, activo y sin archivar, con fixed_cost y computed_cost ambos nulos o cero.';
  t_objetivo   constant text := 'kitchen_settings.target_food_cost_pct inexistente o NULL para la cuenta.';

  v_dias     integer := greatest(1, (extract(epoch from coalesce(p_ventana, interval '30 days')) / 86400)::int);
  v_resultado jsonb;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para ver lo que le falta al catálogo de la cuenta %', p_account
      using errcode = '42501';
  end if;

  with carta as (
    select mi.id, mi.brand_id, mi.recipe_item_id,
           ri.computed_cost, ri.packaging_cost
      from menu_item mi
      left join recipe_item ri on ri.id = mi.recipe_item_id
     where mi.account_id = p_account
       and mi.is_active is not false
       and mi.archived_at is null
  ),
  cobran as (
    select mo.id, mg.brand_id
      from modifier_option mo
      join modifier_group mg on mg.id = mo.modifier_group_id
                            and mg.account_id = p_account      -- regla 9
     where mo.account_id = p_account
       and mo.is_active
       and coalesce(mo.price_impact, 0) > 0
  ),
  extras_cero as (
    select c.id, c.brand_id
      from cobran c
     where coalesce((select sum(case when i.impact_type in ('add_item','bundle','replace_item')
                                     then public._impact_cost(i.target_recipe_item_id, i.quantity, i.unit_id)
                                     else 0 end)
                       from modifier_recipe_impact i
                      where i.modifier_option_id = c.id
                        and i.status = 'confirmed'), 0) = 0
  ),
  extras_vivos as (
    select distinct e.id
      from extras_cero e
      join sale_line m on m.modifier_option_id = e.id and m.line_type = 'modifier'
      join sale s on s.id = m.sale_id
                 and s.account_id = p_account                  -- regla 9
                 and s.sold_at >= now() - coalesce(p_ventana, interval '30 days')
                 and coalesce(s.status, '') <> 'cancelled'
  ),
  ingredientes as (
    select ri.id, (coalesce(ri.fixed_cost,0) = 0 and coalesce(ri.computed_cost,0) = 0) as mudo
      from recipe_item ri
     where ri.account_id = p_account
       and ri.type = 'raw'
       and ri.is_active is not false
       and ri.archived_at is null
  ),
  objetivo as (
    select ks.target_food_cost_pct
      from kitchen_settings ks
     where ks.account_id = p_account
     limit 1
  )
  select jsonb_build_object(
    'cuenta',        p_account,
    'medido_en',     now(),
    'ventana_dias',  v_dias,
    'en_carta', jsonb_build_object(
      'definicion', d_en_carta,
      'regla_tecnica', t_en_carta,
      'n',          (select count(*) from carta)
    ),
    'cosas', jsonb_build_array(

      jsonb_build_object(
        'clave',      'extras_que_cobran_sin_coste',
        'orden',      1,
        'por_que_aqui','Entran en la caja y no descuentan comida: empujan la cifra de comida sobre ventas HACIA ABAJO. Es el único de los cinco que hace que el número sea mejor de lo que es.',
        'definicion', d_extras,
        'regla_tecnica', t_extras,
        'n',          (select count(*) from extras_cero),
        'de',         (select count(*) from cobran),
        'venden',     (select count(*) from extras_vivos),
        'accion',     'Ponerles coste',
        'peores', (
          select coalesce(jsonb_agg(p order by p.n desc, p.marca), '[]'::jsonb) from (
            select c.brand_id, coalesce(b.name, '(sin marca)') as marca,
                   count(*) filter (where z.id is not null)::int as n,
                   count(*)::int                                as de
              from cobran c
              left join extras_cero z on z.id = c.id
              left join brand b on b.id = c.brand_id and b.account_id = p_account
             group by c.brand_id, b.name
            having count(*) filter (where z.id is not null) > 0
          ) p
        )
      ),

      jsonb_build_object(
        'clave',      'platos_en_carta_sin_coste',
        'orden',      2,
        'por_que_aqui','Se venden sin que Folvy sepa lo que cuestan, así que se quedan FUERA de la cifra: no la empeoran, la dejan incompleta.',
        'definicion', d_sin_coste,
        'regla_tecnica', t_sin_coste,
        'n',          (select count(*) from carta where computed_cost is null),
        'de',         (select count(*) from carta),
        'sin_ficha',           (select count(*) from carta where recipe_item_id is null),
        'con_ficha_sin_coste', (select count(*) from carta where recipe_item_id is not null and computed_cost is null),
        'accion',     'Casar o crear la ficha',
        'peores', (
          select coalesce(jsonb_agg(p order by p.n desc, p.marca), '[]'::jsonb) from (
            select k.brand_id, coalesce(b.name, '(sin marca)') as marca,
                   count(*) filter (where k.computed_cost is null)::int as n,
                   count(*)::int                                        as de
              from carta k
              left join brand b on b.id = k.brand_id and b.account_id = p_account
             group by k.brand_id, b.name
            having count(*) filter (where k.computed_cost is null) > 0
          ) p
        )
      ),

      jsonb_build_object(
        'clave',      'platos_en_carta_sin_envase',
        'orden',      3,
        'por_que_aqui','Su envase cuenta como cero, así que la comida sale más barata de lo que es.',
        'definicion', d_sin_envase,
        'regla_tecnica', t_sin_envase,
        'n',          (select count(*) from carta where coalesce(packaging_cost, 0) = 0),
        'de',         (select count(*) from carta),
        'accion',     'Poner envase',
        'peores', (
          select coalesce(jsonb_agg(p order by p.n desc, p.marca), '[]'::jsonb) from (
            select k.brand_id, coalesce(b.name, '(sin marca)') as marca,
                   count(*) filter (where coalesce(k.packaging_cost,0) = 0)::int as n,
                   count(*)::int                                                 as de
              from carta k
              left join brand b on b.id = k.brand_id and b.account_id = p_account
             group by k.brand_id, b.name
            having count(*) filter (where coalesce(k.packaging_cost,0) = 0) > 0
          ) p
        )
      ),

      jsonb_build_object(
        'clave',      'sin_objetivo_de_comida',
        'orden',      4,
        'por_que_aqui','Va el cuarto porque no ensucia ningún número: los deja sin juez. Es un minuto de trabajo y le da sentido a los tres de arriba.',
        'definicion', d_objetivo,
        'regla_tecnica', t_objetivo,
        'n',          (select case when (select target_food_cost_pct from objetivo) is null then 1 else 0 end),
        'de',         1,
        'hay_fila_de_ajustes', (select exists (select 1 from objetivo)),
        'target_food_cost_pct', (select target_food_cost_pct from objetivo),
        'platos_con_objetivo_propio', (
          select count(*)::int from menu_item mi2
           where mi2.account_id = p_account                    -- regla 9
             and mi2.is_active is not false
             and mi2.archived_at is null
             and mi2.target_food_cost_pct is not null
        ),
        'accion',     'Poner objetivo',
        'peores',     '[]'::jsonb
      ),

      jsonb_build_object(
        'clave',      'ingredientes_sin_precio',
        'orden',      5,
        'por_que_aqui','El último porque HOY no bloquea nada: se cuenta en cuántas líneas de receta aparecen de verdad, y hoy son cero. Si ese número sube, este contador sube de puesto solo.',
        'definicion', d_ingred,
        'regla_tecnica', t_ingred,
        'n',          (select count(*) from ingredientes where mudo),
        'de',         (select count(*) from ingredientes),
        'usados_en_lineas_de_receta', (
          select count(*)::int
            from recipe_line rl
            join ingredientes g on g.id = rl.child_item_id and g.mudo
           where rl.account_id = p_account                     -- regla 9
        ),
        'recetas_que_bloquean', (
          select count(distinct rl.parent_item_id)::int
            from recipe_line rl
            join ingredientes g on g.id = rl.child_item_id and g.mudo
            join recipe_item rr on rr.id = rl.parent_item_id
                               and rr.account_id = p_account   -- regla 9
                               and rr.is_active is not false
                               and rr.archived_at is null
           where rl.account_id = p_account
        ),
        'accion',     'Poner precios',
        'peores',     '[]'::jsonb
      )
    )
  ) into v_resultado;

  return v_resultado;
end;
$$;


--
-- Name: FUNCTION kitchen_catalog_gaps(p_account uuid, p_ventana interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_catalog_gaps(p_account uuid, p_ventana interval) IS 'B79 lote 4 · B83. Las cinco cosas que arreglar del Resumen de Kitchen. Cada contador devuelve DOS reglas: `definicion` en castellano de persona (la unica que se pinta) y `regla_tecnica` con las columnas (viaja, no se pinta).';


--
-- Name: kitchen_day_banner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_day_banner(p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_account_id uuid;
begin
  select account_id into v_account_id from locations where id = p_location_id;
  if v_account_id is null then raise exception 'kitchen_day_banner: ubicación inexistente'; end if;
  if not belongs_to_account(v_account_id) then raise exception 'kitchen_day_banner: sin acceso'; end if;
  return public._kitchen_day_banner_for(p_location_id);
end;
$$;


--
-- Name: kitchen_day_banner_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_day_banner_by_token(p_device_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_device kds_device;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'kitchen_day_banner_by_token: token no válido'; end if;
  if v_device.location_id is null then raise exception 'kitchen_day_banner_by_token: dispositivo sin local'; end if;
  return public._kitchen_day_banner_for(v_device.location_id);
end;
$$;


--
-- Name: kitchen_delete_or_archive_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_delete_or_archive_item(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item  recipe_item%ROWTYPE;
  v_check jsonb;
BEGIN
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kitchen_delete_or_archive_item: item % no existe', p_item_id;
  END IF;
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(v_item.account_id)) THEN
    RAISE EXCEPTION 'kitchen_delete_or_archive_item: sin acceso al item %', p_item_id;
  END IF;

  v_check := public.kitchen_item_delete_check(p_item_id);

  IF (v_check->>'deletable')::boolean THEN
    -- Sin referencias bloqueantes: borrado físico. Los CASCADE se encargan del resto.
    DELETE FROM recipe_item WHERE id = p_item_id;
    RETURN jsonb_build_object('action', 'deleted', 'name', v_item.name);
  ELSE
    -- En uso: archivar (reversible, conserva histórico).
    UPDATE recipe_item
       SET is_active = false, archived_at = now()
     WHERE id = p_item_id;
    RETURN jsonb_build_object('action', 'archived', 'name', v_item.name,
                              'reasons', v_check->'reasons');
  END IF;
END;
$$;


--
-- Name: kitchen_dish_state_for_ai(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_dish_state_for_ai(p_recipe_item_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'id', ri.id,
    'name', ri.name,
    'type', ri.type,
    'code', ri.code,
    'family_id', ri.family_id,
    'yield_portions', ri.yield_portions,
    'computed_cost', ri.computed_cost,
    'fixed_cost', ri.fixed_cost,
    'cost_strategy', ri.cost_strategy,
    'needs_review', ri.needs_review,
    'procedure_text', ri.procedure_text,
    'lines', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'child_item_id', rl.child_item_id,
        'child_name', child.name,
        'child_type', child.type,
        'quantity_net', rl.quantity_net,
        'quantity_gross', rl.quantity_gross,
        'unit_id', rl.unit_id,
        'cut_type_id', rl.cut_type_id,
        'comment', rl.comment,
        'position', rl.position
      ) ORDER BY rl.position)
      FROM recipe_line rl
      JOIN recipe_item child ON child.id = rl.child_item_id
      WHERE rl.parent_item_id = ri.id
    ), '[]'::jsonb)
  )
  FROM recipe_item ri
  WHERE ri.id = p_recipe_item_id;
$$;


--
-- Name: kitchen_dishes_incomplete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_dishes_incomplete(p_account_id uuid) RETURNS TABLE(dish_id uuid, has_incomplete boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT parent.id AS dish_id,
         true AS has_incomplete
  FROM recipe_item  parent
  JOIN recipe_line  rl              ON rl.parent_item_id = parent.id
  JOIN recipe_item  child           ON child.id = rl.child_item_id
  JOIN kitchen_unit line_unit       ON line_unit.id = rl.unit_id
  JOIN kitchen_unit child_base_unit ON child_base_unit.id = child.base_unit_id
  WHERE parent.account_id = p_account_id
    AND parent.type = 'dish'
    AND public.current_user_is_admin_or_manager_of(p_account_id)
  GROUP BY parent.id
  HAVING bool_or(
    COALESCE(child.needs_review, false)
    OR (
      line_unit.dimension <> child_base_unit.dimension
      AND NOT EXISTS (
        SELECT 1 FROM recipe_item_unit_conversion c
        WHERE c.item_id = child.id AND c.from_unit_id = rl.unit_id
      )
    )
  );
$$;


--
-- Name: kitchen_extras_poner_lo_que_lleva(uuid, uuid[], jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_extras_poner_lo_que_lleva(p_account uuid, p_opciones uuid[], p_lleva jsonb, p_actor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cosa      jsonb;
  v_opcion    uuid;
  v_escritos  int := 0;
  v_ficha     uuid;
  v_tipo      text;
  v_rationale text;
  v_mala      text;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para poner el coste de los extras de la cuenta %', p_account
      using errcode = '42501';
  end if;

  if p_opciones is null or array_length(p_opciones, 1) is null then
    raise exception 'No se ha elegido ninguna copia a la que ponerle lo que lleva.'
      using errcode = '22023';
  end if;
  if p_lleva is null or jsonb_array_length(p_lleva) = 0 then
    raise exception 'No se ha dicho qué lleva el extra.'
      using errcode = '22023';
  end if;

  -- REGLA 9, Y AQUÍ ES UNA ESCRITURA. Si una opción no es de esta cuenta se
  -- aborta entera: escribir en el catálogo de otro cliente no se arregla luego.
  if exists (
    select 1 from unnest(p_opciones) o(id)
     where not exists (
       select 1 from modifier_option mo
        where mo.id = o.id and mo.account_id = p_account)
  ) then
    raise exception 'Alguna de las copias no es de esta cuenta. No se ha escrito nada.'
      using errcode = '42501';
  end if;

  -- Las fichas de destino, igual: por cuenta.
  if exists (
    select 1 from jsonb_array_elements(p_lleva) c
     where not exists (
       select 1 from recipe_item ri
        where ri.id = (c->>'ficha')::uuid and ri.account_id = p_account)
  ) then
    raise exception 'Alguna de las fichas no es de esta cuenta. No se ha escrito nada.'
      using errcode = '42501';
  end if;

  -- Y VIVAS (B84.3). Una ficha archivada tiene el precio del día en que se
  -- archivó y ya no sale en el selector: si llega aquí es por una llamada
  -- directa, y costear siete copias contra un precio congelado es escribir un
  -- número que nadie va a volver a mirar. Se dice CUÁL falla, no «alguna»: con
  -- siete copias y tres cosas, «alguna» no se puede ir a buscar.
  select ri.name into v_mala
    from jsonb_array_elements(p_lleva) c
    join recipe_item ri on ri.id = (c->>'ficha')::uuid
   where ri.account_id = p_account
     and (not ri.is_active or ri.archived_at is not null)
   limit 1;
  if v_mala is not null then
    raise exception 'La ficha «%» está archivada: su precio es el del día que se archivó. No se ha escrito nada.', v_mala
      using errcode = '42501';
  end if;

  v_rationale := 'Sección Extras · aplicado a ' || array_length(p_opciones, 1) || ' copias';

  foreach v_opcion in array p_opciones loop
    for v_cosa in select * from jsonb_array_elements(p_lleva) loop
      v_ficha := (v_cosa->>'ficha')::uuid;
      -- Un plato entero es UN impacto `bundle`; un ingrediente se añade.
      v_tipo := case when v_cosa->>'tipo' = 'plato' then 'bundle' else 'add_item' end;

      -- 🔴 SIN CANTIDAD NO DESCUENTA NADA (13/09). Esta puerta nunca lo ha
      -- dejado pasar porque su pantalla siempre manda la cantidad — o sea que
      -- los 73 `add_item` buenos lo son por buena conducta, no porque nada lo
      -- impidiera. Lo impide ahora.
      if not public._impacto_completo(
               v_tipo, v_ficha, nullif(v_cosa->>'cantidad','')::numeric) then
        raise exception
          'A «%» le falta la cantidad: asi no descontaria nada del almacen, aunque el extra quedara como decidido. No se ha escrito nada.',
          coalesce((select ri.name from recipe_item ri where ri.id = v_ficha), 'ese articulo')
          using errcode = '22023';
      end if;

      insert into modifier_recipe_impact (
        account_id, modifier_option_id, impact_type, target_recipe_item_id,
        quantity, unit_id, status, source, rationale,
        confirmed_by, confirmed_by_name, confirmed_at)
      values (
        p_account, v_opcion, v_tipo, v_ficha,
        nullif(v_cosa->>'cantidad','')::numeric,
        nullif(v_cosa->>'unidad','')::uuid,
        'confirmed', 'human', v_rationale,
        auth.uid(), p_actor, now())
      -- Si esa copia ya tenía justo esa ficha confirmada, se ACTUALIZA en vez
      -- de duplicar: el índice único parcial lo impediría, y reventar aquí
      -- dejaría el trabajo a medias por algo que es corregir, no duplicar.
      on conflict (modifier_option_id, target_recipe_item_id)
        where status = 'confirmed'
      do update set
        impact_type       = excluded.impact_type,
        quantity          = excluded.quantity,
        unit_id           = excluded.unit_id,
        rationale         = excluded.rationale,
        confirmed_by      = excluded.confirmed_by,
        confirmed_by_name = excluded.confirmed_by_name,
        confirmed_at      = excluded.confirmed_at,
        updated_at        = now();

      v_escritos := v_escritos + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'copias',   array_length(p_opciones, 1),
    'escritos', v_escritos,
    'cosas',    jsonb_array_length(p_lleva)
  );
end;
$$;


--
-- Name: FUNCTION kitchen_extras_poner_lo_que_lleva(p_account uuid, p_opciones uuid[], p_lleva jsonb, p_actor text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_extras_poner_lo_que_lleva(p_account uuid, p_opciones uuid[], p_lleva jsonb, p_actor text) IS 'Extras: aplica lo que lleva a N copias de un extra. Rechaza fichas de otra cuenta, archivadas, y efectos que no descontarian nada del almacen.';


--
-- Name: kitchen_extras_por_nombre(uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_extras_por_nombre(p_account uuid, p_ventana interval DEFAULT '30 days'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_dias      integer := greatest(1, (extract(epoch from coalesce(p_ventana, interval '30 days')) / 86400)::int);
  -- ── DÍAS ENTEROS, Y EN HORA DE MADRID ───────────────────────────────────
  -- La ventana era `now() - 30 days`, que empieza a media tarde del primer
  -- día. La pantalla dice «del 9 de agosto al 7 de septiembre» y eso promete
  -- días completos: o la frase miente o la cuenta miente. Aquí se arregla en
  -- la cuenta, y la frase se pinta con las fechas que devuelve ESTA función:
  -- un solo reloj, no dos que se parecen.
  --
  -- El truncado va en `Europe/Madrid`, no en UTC (regla 4): la medianoche de
  -- Madrid del 9 son las 22:00 UTC del 8. Truncando en UTC la ventana
  -- empezaría a las 02:00 de Madrid y se comería el servicio de madrugada,
  -- que en Alcalá llega pasada la una.
  v_hasta_dia date      := (now() at time zone 'Europe/Madrid')::date;
  v_desde_dia date      := v_hasta_dia - (v_dias - 1);
  v_desde     timestamptz := (v_desde_dia::timestamp) at time zone 'Europe/Madrid';
  v_resultado jsonb;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para ver los extras de la cuenta %', p_account
      using errcode = '42501';
  end if;

  with copias as (
    -- Una copia = una opción de modificador que COBRA. La marca sale del grupo,
    -- y el grupo lleva su propio account_id (regla 9): sin eso, el catálogo
    -- plantilla del sistema entraría en la cuenta del cliente.
    select mo.id,
           btrim(mo.name)                          as nombre,
           mo.price_impact::numeric                as precio,
           mg.brand_id,
           coalesce(b.name, '(sin marca)')         as marca,
           mg.name                                 as grupo,
           lower(btrim(regexp_replace(regexp_replace(mo.name, '[.]', '', 'g'), '\s+', ' ', 'g'))) as clave,
           coalesce((
             select sum(case when i.impact_type in ('add_item','bundle','replace_item')
                             then public._impact_cost(i.target_recipe_item_id, i.quantity, i.unit_id)
                             else 0 end)
               from modifier_recipe_impact i
              where i.modifier_option_id = mo.id and i.status = 'confirmed'), 0)::numeric as coste,
           (select count(*) from modifier_recipe_impact i
             where i.modifier_option_id = mo.id and i.status = 'confirmed')::int as impactos,
           -- B84.5: DÓNDE lo ve el cliente. El grupo no lo dice —cuatro copias
           -- de «Algun extra en tu pita?» son cuatro platos distintos—, así que
           -- viajan los platos vivos a los que ese grupo está asignado, con su
           -- id para poder enlazar a la ficha. Por cuenta, como todo (regla 9).
           (select coalesce(jsonb_agg(jsonb_build_object('id', mi.id, 'nombre', mi.name)
                                      order by mi.name), '[]'::jsonb)
              from modifier_group_assignment ga
              join menu_item mi on mi.id = ga.menu_item_id
                               and mi.account_id = p_account
                               and mi.is_active
                               and mi.archived_at is null
             where ga.modifier_group_id = mg.id
               and ga.account_id = p_account) as platos
      from modifier_option mo
      join modifier_group mg on mg.id = mo.modifier_group_id
                            and mg.account_id = p_account            -- regla 9
      left join brand b on b.id = mg.brand_id and b.account_id = p_account
     where mo.account_id = p_account
       and mo.is_active
       and coalesce(mo.price_impact, 0) > 0
  ),
  ventas as (
    select m.modifier_option_id as id, count(*)::int as vendidas
      from sale_line m
      join sale s on s.id = m.sale_id
                 and s.account_id = p_account                        -- regla 9
                 and s.sold_at >= v_desde                            -- días enteros, Madrid
                 and coalesce(s.status, '') <> 'cancelled'
     where m.account_id = p_account
       and m.line_type = 'modifier'
     group by 1
  ),
  c as (
    select copias.*, coalesce(ventas.vendidas, 0) as vendidas
      from copias left join ventas using (id)
  ),
  grupos as (
    select c.clave,
           -- El nombre que se pinta: el de la copia que más se vende. Si nadie
           -- vende, el primero por orden. Determinista a propósito: una fila que
           -- cambia de nombre al recargar no se puede señalar por teléfono.
           (array_agg(c.nombre order by c.vendidas desc, c.nombre))[1] as nombre,
           count(*)::int                                as copias,
           count(distinct c.brand_id)::int              as marcas,
           sum(c.vendidas)::int                         as vendidas,
           round(sum(c.vendidas * c.precio), 2)         as cobrado,
           min(c.precio)                                as precio_min,
           max(c.precio)                                as precio_max,
           (min(c.precio) <> max(c.precio))             as precios_distintos,
           case when min(c.coste) > 0      then 'con_coste'
                when max(c.coste) > 0      then 'mixto'
                when max(c.impactos) > 0   then 'puesto_pero_cero'
                else                            'nada_puesto' end as estado,
           -- Para «usar el mismo que en Meraki»: lo que ya cuesta una copia del
           -- grupo, si alguna lo tiene. No se pisa lo que ya está hecho.
           max(c.coste) filter (where c.coste > 0)      as coste_ya_puesto,
           (array_agg(c.marca order by c.coste desc, c.marca)
             filter (where c.coste > 0))[1]             as marca_que_ya_lo_tiene,
           jsonb_agg(jsonb_build_object(
             'opcion',    c.id,
             'marca',     c.marca,
             'marca_id',  c.brand_id,
             'grupo',     c.grupo,
             'precio',    c.precio,
             'vendidas',  c.vendidas,
             'coste',     c.coste,
             'tiene_coste', (c.coste > 0),
             'platos',    c.platos
           ) order by c.vendidas desc, c.marca, c.nombre)  as donde
      from c
     group by c.clave
  )
  select jsonb_build_object(
    'cuenta',        p_account,
    'medido_en',     now(),
    'ventana_dias',  v_dias,
    -- QUÉ DÍAS SE HAN CONTADO. La pantalla los pinta tal cual; no los vuelve a
    -- calcular. Dos sitios calculando la misma ventana es cómo nacen los dos
    -- relojes.
    'ventana_desde', v_desde_dia,
    'ventana_hasta', v_hasta_dia,
    'cifras', jsonb_build_object(
      'cobran',             (select count(*) from c),
      'marcas_que_cobran',  (select count(distinct brand_id) from c),
      'con_coste',          (select count(*) from c where coste > 0),
      'sin_coste',          (select count(*) from c where coste = 0),
      'nombres',            (select count(*) from grupos),
      'nombres_sin_coste',  (select count(*) from grupos where estado <> 'con_coste'),
      'vendidos_sin_coste', (select count(*) from c where coste = 0 and vendidas > 0),
      'veces_vendidos',     (select coalesce(sum(vendidas),0) from c where coste = 0),
      'cobrado_eur',        (select coalesce(round(sum(vendidas * precio), 2), 0) from c where coste = 0)
    ),
    'filas', (
      select coalesce(jsonb_agg(to_jsonb(g) order by g.vendidas desc, g.copias desc, g.clave), '[]'::jsonb)
        from grupos g
    )
  ) into v_resultado;

  return v_resultado;
end;
$$;


--
-- Name: FUNCTION kitchen_extras_por_nombre(p_account uuid, p_ventana interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_extras_por_nombre(p_account uuid, p_ventana interval) IS 'Sección Extras. Una fila por nombre normalizado dentro de la cuenta, no por copia: copias, marcas, lo vendido, lo cobrado, si los precios difieren y si alguna copia ya tiene coste. Cada copia dice en qué platos aparece (B84.5). Devuelve TODOS los grupos; el filtro «sólo los que hay que arreglar» es de la pantalla. Sólo claves, ningún texto de pantalla.';


--
-- Name: kitchen_ficha_de_respuesta(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_ficha_de_respuesta(p_account uuid, p_option_id uuid, p_dias integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_dias  int := greatest(1, coalesce(p_dias, 30));
  v_clave text;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;

  select lower(btrim(o.name)) into v_clave
    from modifier_option o where o.id = p_option_id and o.account_id = p_account;
  if v_clave is null then return null; end if;

  return (
  select jsonb_build_object(
    'id', o.id, 'nombre', btrim(o.name), 'precio', coalesce(o.price_impact,0),
    'activa', coalesce(o.is_active, true),
    'retirada_at', o.deactivated_at, 'retirada_por', o.deactivated_by,
    -- 🔴 EL CASO CONTRARIO (14/09). Arriba esta «quien la apago»; esto es
    -- «a quien se la volvieron a encender». Una respuesta ENCENDIDA con esta
    -- marca es una que apago una persona y el importador de Last ha vuelto a
    -- poner a la venta. Sin esta linea, esa persona no se entera nunca: el
    -- sello de apagado se borra al encenderla, y antes no quedaba nada.
    'reencendida_at', o.reencendida_at, 'reencendida_sobre', o.reencendida_sobre,
    'cedida', (coalesce(b.ownership_type,'own') <> 'own'),
    'marca', coalesce(b.name,'Sin marca'),
    'pregunta', g.name, 'pregunta_id', g.id,
    -- QUE LLEVA
    'efecto', (
      select jsonb_build_object('tipo', i.impact_type, 'ficha', i.target_recipe_item_id,
                                'ficha_nombre', ri.name, 'cantidad', i.quantity,
                                'unidad', i.unit_id,
                                'quien', i.confirmed_by_name, 'cuando', i.confirmed_at,
                                'descuenta_algo', public._impacto_completo(
                                   i.impact_type, i.target_recipe_item_id, i.quantity))
        from modifier_recipe_impact i
        left join recipe_item ri on ri.id = i.target_recipe_item_id
       where i.modifier_option_id = o.id and i.account_id = p_account
         and i.status = 'confirmed' limit 1),
    -- DONDE ESTA: todas las que se llaman igual, cada una abrible.
    'donde_esta', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', o2.id, 'pregunta', g2.name, 'pregunta_id', g2.id,
               'marca', coalesce(b2.name,'Sin marca'),
               'cedida', (coalesce(b2.ownership_type,'own') <> 'own'),
               'activa', coalesce(o2.is_active, true),
               'es_esta', (o2.id = o.id),
               'platos', (select count(*) from modifier_group_assignment a
                           where a.modifier_group_id = g2.id),
               'decidida', exists (select 1 from modifier_recipe_impact i2
                                    where i2.modifier_option_id = o2.id
                                      and i2.status = 'confirmed'
                                      and public._impacto_completo(i2.impact_type,
                                            i2.target_recipe_item_id, i2.quantity)))
             order by (o2.id = o.id) desc, b2.name, g2.name)
        from modifier_option o2
        join modifier_group g2 on g2.id = o2.modifier_group_id
        left join brand b2 on b2.id = g2.brand_id
       where o2.account_id = p_account and lower(btrim(o2.name)) = v_clave
         and coalesce(o2.is_active, true)), '[]'::jsonb),
    -- CUANTO SE PIDE. El 0 nunca va solo: al lado va lo anulado.
    'ventas', (
      select jsonb_build_object(
               'dias', v_dias,
               'ventas', count(*) filter (where s.cancelled_at is null),
               'anuladas', count(*) filter (where s.cancelled_at is not null),
               'ultimas', coalesce(jsonb_agg(jsonb_build_object(
                   'cuando', s.sold_at, 'total', s.total,
                   'anulada', (s.cancelled_at is not null),
                   'canal', s.source)
                 order by s.sold_at desc), '[]'::jsonb))
        from sale_line m
        join sale s on s.id = m.sale_id and s.account_id = p_account
                   and s.sold_at >= now() - make_interval(days => v_dias)
       where m.modifier_option_id = o.id and m.line_type = 'modifier'),
    'ultima_venta', (
      select max(s.sold_at) from sale_line m
        join sale s on s.id = m.sale_id and s.account_id = p_account
                   and s.cancelled_at is null
       where m.modifier_option_id = o.id and m.line_type = 'modifier'))
    from modifier_option o
    join modifier_group g on g.id = o.modifier_group_id
    left join brand b on b.id = g.brand_id
   where o.id = p_option_id and o.account_id = p_account);
end;
$$;


--
-- Name: FUNCTION kitchen_ficha_de_respuesta(p_account uuid, p_option_id uuid, p_dias integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_ficha_de_respuesta(p_account uuid, p_option_id uuid, p_dias integer) IS 'La ficha de una respuesta: nombre, que lleva, donde esta (todas las que se llaman igual, abribles) y cuanto se pide. Las ventas anuladas se cuentan aparte y nunca se esconden detras de un 0.';


--
-- Name: kitchen_guardar_pregunta(uuid, uuid, uuid, text, text, boolean, integer, boolean, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_guardar_pregunta(p_account uuid, p_group_id uuid, p_brand_id uuid, p_nombre text, p_tipo text, p_obligatoria boolean, p_max integer, p_repetible boolean, p_respuestas jsonb, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_group      uuid := p_group_id;
  v_nueva      boolean := (p_group_id is null);
  v_nombre     text := btrim(coalesce(p_nombre, ''));
  v_r          jsonb;
  v_efecto     jsonb;
  v_opcion     uuid;
  v_pos        int := 0;
  v_vistas     uuid[] := '{}';
  v_creadas    int := 0;
  v_actual     int := 0;
  v_retiradas  int := 0;
  v_efectos    int := 0;
  v_mala       text;
  v_etiqueta   boolean := false;
  v_tipo_imp   text;
begin
  -- ── PERMISO ─────────────────────────────────────────────────────────────
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para editar las preguntas de la cuenta %', p_account
      using errcode = '42501';
  end if;

  -- ── LA MARCA: de esta cuenta Y PROPIA ───────────────────────────────────
  if not exists (select 1 from brand b
                  where b.id = p_brand_id and b.account_id = p_account) then
    raise exception 'Esa marca no es de esta cuenta. No se ha escrito nada.'
      using errcode = '42501';
  end if;
  select b.name into v_mala from brand b
   where b.id = p_brand_id and coalesce(b.ownership_type, 'own') <> 'own';
  if v_mala is not null then
    raise exception 'La carta de «%» la manda Last: aquí no se crean ni se editan preguntas. No se ha escrito nada.', v_mala
      using errcode = '42501';
  end if;

  -- ── LO QUE SE EDITA, si se edita ────────────────────────────────────────
  if not v_nueva then
    if not exists (select 1 from modifier_group g
                    where g.id = v_group and g.account_id = p_account
                      and g.brand_id = p_brand_id) then
      raise exception 'Esa pregunta no es de esta cuenta o no es de esa marca. No se ha escrito nada.'
        using errcode = '42501';
    end if;
  end if;

  if v_nombre = '' then
    raise exception 'La pregunta necesita el texto que lee el cliente.'
      using errcode = '22023';
  end if;
  if p_respuestas is null or jsonb_array_length(p_respuestas) = 0 then
    raise exception 'La pregunta necesita al menos una respuesta.'
      using errcode = '22023';
  end if;

  -- Dos respuestas con el mismo nombre son indistinguibles para el cliente.
  select lower(btrim(r->>'nombre')) into v_mala
    from jsonb_array_elements(p_respuestas) r
   group by lower(btrim(r->>'nombre')) having count(*) > 1 limit 1;
  if v_mala is not null then
    raise exception 'Hay dos respuestas llamadas «%». No se ha escrito nada.', v_mala
      using errcode = '22023';
  end if;

  -- ── LAS FICHAS DE DESTINO: de esta cuenta, VIVAS y sin archivar ─────────
  -- Igual que en la sección Extras: una ficha archivada tiene el precio del día
  -- en que se archivó, y costear contra ese número es escribir algo que nadie
  -- va a volver a mirar. Se dice CUÁL falla, no «alguna».
  select ri.name into v_mala
    from jsonb_array_elements(p_respuestas) r
    join recipe_item ri on ri.id = nullif(r->'efecto'->>'ficha','')::uuid
   where ri.account_id <> p_account
      or not ri.is_active or ri.archived_at is not null
   limit 1;
  if v_mala is not null then
    raise exception 'La ficha «%» está archivada o no es de esta cuenta. No se ha escrito nada.', v_mala
      using errcode = '42501';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_respuestas) r
     where nullif(r->'efecto'->>'ficha','') is not null
       and not exists (select 1 from recipe_item ri
                        where ri.id = (r->'efecto'->>'ficha')::uuid)
  ) then
    raise exception 'Alguna ficha no existe. No se ha escrito nada.' using errcode = '42501';
  end if;

  -- ── LA PREGUNTA ─────────────────────────────────────────────────────────
  if v_nueva then
    insert into modifier_group (account_id, brand_id, name, min_selections,
                                max_selections, allow_repetition, group_type, is_active)
    values (p_account, p_brand_id, v_nombre,
            case when p_obligatoria then 1 else 0 end,
            greatest(1, coalesce(p_max, 1)),
            coalesce(p_repetible, false),
            coalesce(p_tipo, 'choice'), true)
    returning id into v_group;
  else
    -- LA ETIQUETA VIEJA SE LIMPIA AL GUARDAR: «esta pregunta venía de una
    -- importación antigua; al guardarla pasa a ser tuya». Solo en propias —
    -- aquí ya no puede ser otra cosa, la marca se comprobó arriba.
    select (g.external_source is not null) into v_etiqueta
      from modifier_group g where g.id = v_group;

    update modifier_group
       set name             = v_nombre,
           min_selections   = case when p_obligatoria then 1 else 0 end,
           max_selections   = greatest(1, coalesce(p_max, 1)),
           allow_repetition = coalesce(p_repetible, false),
           group_type       = coalesce(p_tipo, group_type),
           is_active        = true,
           external_source  = null,
           external_id      = null,
           updated_at       = now()
     where id = v_group;
  end if;

  -- ── LAS RESPUESTAS ──────────────────────────────────────────────────────
  for v_r in select * from jsonb_array_elements(p_respuestas) loop
    v_pos    := v_pos + 1;
    v_opcion := nullif(v_r->>'id', '')::uuid;
    v_efecto := case when v_r->'efecto' = 'null'::jsonb then null else v_r->'efecto' end;

    if v_opcion is not null then
      -- Existente: tiene que ser de ESTA pregunta. Mover una opción de una
      -- pregunta a otra por id no es editar, es otra cosa.
      if not exists (select 1 from modifier_option o
                      where o.id = v_opcion and o.account_id = p_account
                        and o.modifier_group_id = v_group) then
        raise exception 'Una de las respuestas no es de esta pregunta. No se ha escrito nada.'
          using errcode = '42501';
      end if;
      update modifier_option
         set name           = btrim(v_r->>'nombre'),
             price_impact   = coalesce(nullif(v_r->>'precio','')::numeric, 0),
             position       = v_pos,
             is_active      = true,
             deactivated_at = null,
             deactivated_by = null,
             updated_at     = now()
       where id = v_opcion;
      v_actual := v_actual + 1;
    else
      -- NUEVA. Sin efecto declarado no entra: seria la fila 111.
      if v_efecto is null or nullif(v_efecto->>'tipo','') is null then
        raise exception 'La respuesta «%» es nueva y no dice qué lleva. No se ha escrito nada.',
          btrim(v_r->>'nombre') using errcode = '22023';
      end if;
      insert into modifier_option (account_id, modifier_group_id, name,
                                   price_impact, position, is_active)
      values (p_account, v_group, btrim(v_r->>'nombre'),
              coalesce(nullif(v_r->>'precio','')::numeric, 0), v_pos, true)
      returning id into v_opcion;
      v_creadas := v_creadas + 1;
    end if;

    v_vistas := array_append(v_vistas, v_opcion);

    -- ── QUÉ LLEVA ─────────────────────────────────────────────────────────
    -- Una respuesta tiene UN efecto. Se borra el confirmado que hubiera y se
    -- escribe el declarado: asi «cambiar de opinion» no deja dos verdades.
    -- Si no viene efecto y la respuesta ya existia, se deja como estaba.
    if v_efecto is not null and nullif(v_efecto->>'tipo','') is not null then
      v_tipo_imp := v_efecto->>'tipo';
      if v_tipo_imp not in ('add_item','remove_item','replace_item','multiply','bundle','none') then
        raise exception 'El efecto «%» no existe. No se ha escrito nada.', v_tipo_imp
          using errcode = '22023';
      end if;

      -- 🔴 SIN CANTIDAD NO DESCUENTA NADA (13/09). La puerta, no solo la
      -- pantalla: el 13/09 se guardaron dos «anade» con ficha y sin cantidad
      -- y el contador las dio por decididas mientras el consumo era CERO.
      -- Que exige cada tipo lo dice `_impacto_completo`, en un solo sitio.
      if not public._impacto_completo(
               v_tipo_imp,
               nullif(v_efecto->>'ficha','')::uuid,
               nullif(v_efecto->>'cantidad','')::numeric) then
        raise exception
          'A «%» le falta el articulo o la cantidad: asi no descontaria nada del almacen, aunque la pregunta quedara como decidida. No se ha escrito nada.',
          btrim(v_r->>'nombre') using errcode = '22023';
      end if;

      delete from modifier_recipe_impact
       where modifier_option_id = v_opcion and account_id = p_account
         and status = 'confirmed';

      insert into modifier_recipe_impact (
        account_id, modifier_option_id, impact_type, target_recipe_item_id,
        quantity, unit_id, status, source, rationale,
        confirmed_by, confirmed_by_name, confirmed_at)
      values (
        p_account, v_opcion, v_tipo_imp,
        nullif(v_efecto->>'ficha','')::uuid,
        nullif(v_efecto->>'cantidad','')::numeric,
        nullif(v_efecto->>'unidad','')::uuid,
        'confirmed', 'human',
        'Tablero 5 · ' || v_nombre,
        auth.uid(), p_actor, now());

      v_efectos := v_efectos + 1;
    end if;
  end loop;

  -- ── LAS QUE YA NO ESTÁN ─────────────────────────────────────────────────
  -- No se borran: se retiran, con sello de persona. Una opción borrada se
  -- lleva por delante el historial de lo que se vendió con ella.
  update modifier_option
     set is_active = false, deactivated_at = now(),
         deactivated_by = 'persona', updated_at = now()
   where modifier_group_id = v_group and account_id = p_account
     and is_active and not (id = any(v_vistas));
  get diagnostics v_retiradas = row_count;

  return jsonb_build_object(
    'pregunta_id',            v_group,
    'nombre',                 v_nombre,
    'creada',                 v_nueva,
    'respuestas_creadas',     v_creadas,
    'respuestas_actualizadas',v_actual,
    'respuestas_retiradas',   v_retiradas,
    'efectos_escritos',       v_efectos,
    'etiqueta_vieja_limpiada',v_etiqueta);
end;
$$;


--
-- Name: FUNCTION kitchen_guardar_pregunta(p_account uuid, p_group_id uuid, p_brand_id uuid, p_nombre text, p_tipo text, p_obligatoria boolean, p_max integer, p_repetible boolean, p_respuestas jsonb, p_actor text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_guardar_pregunta(p_account uuid, p_group_id uuid, p_brand_id uuid, p_nombre text, p_tipo text, p_obligatoria boolean, p_max integer, p_repetible boolean, p_respuestas jsonb, p_actor text) IS 'Tablero 5: crea o edita una pregunta con sus respuestas y lo que lleva cada una. Candados: marca cedida, respuesta nueva sin efecto, ficha archivada o de otra cuenta, efecto que no descuenta nada, y nombres repetidos.';


--
-- Name: kitchen_item_delete_check(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_item_delete_check(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item    recipe_item%rowtype;
  v_reasons text[] := array[]::text[];
  v_n       integer;
begin
  select * into v_item from recipe_item where id = p_item_id;
  if not found then
    raise exception 'kitchen_item_delete_check: item % no existe', p_item_id;
  end if;
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_item.account_id)) then
    raise exception 'kitchen_item_delete_check: sin acceso al item %', p_item_id;
  end if;

  select count(*) into v_n from menu_item where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || format('está en %s carta(s)', v_n); end if;

  select count(distinct parent_item_id) into v_n from recipe_line where child_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || format('se usa como ingrediente en %s plato(s)', v_n); end if;

  select count(*) into v_n from stock_movement where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || 'tiene movimientos de stock'; end if;

  select count(*) into v_n from stock_waste where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || 'tiene mermas registradas'; end if;

  select count(*) into v_n from inventory_count_line where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || 'aparece en inventarios'; end if;

  select count(*) into v_n from modifier_option where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || 'se usa en modificadores'; end if;

  select count(*) into v_n from modifier_recipe_impact where target_recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || 'se usa en modificadores'; end if;

  select count(*) into v_n from supplier_invoice_line where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || 'está en facturas de proveedor'; end if;

  -- (02/09) LAS CINCO QUE FALTABAN.
  -- `course` aborta el DELETE por clave ajena; las otras cuatro lo dejan pasar
  -- y se llevan la historia por delante en silencio.
  select count(*) into v_n from course where source_recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || format('es el origen de %s curso(s) de formación', v_n); end if;

  select count(*) into v_n from goods_receipt_line where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || format('está en %s línea(s) de albarán recibido', v_n); end if;

  select count(*) into v_n from purchase_order_line where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || format('está en %s línea(s) de pedido a proveedor', v_n); end if;

  select count(*) into v_n from purchase_line where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || format('está en %s línea(s) de compra', v_n); end if;

  select count(*) into v_n from sales_mapping_fix where recipe_item_id = p_item_id;
  if v_n > 0 then v_reasons := v_reasons || format('lo usan %s corrección(es) de casado de ventas', v_n); end if;

  return jsonb_build_object(
    'deletable',  (array_length(v_reasons, 1) is null),
    'reasons',    to_jsonb(v_reasons),
    'name',       v_item.name,
    'type',       v_item.type,
    'archived',   (v_item.archived_at is not null or v_item.is_active = false)
  );
end;
$$;


--
-- Name: kitchen_las_iguales(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_las_iguales(p_account uuid, p_option_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_clave text;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;

  select lower(btrim(o.name)) into v_clave
    from modifier_option o
   where o.id = p_option_id and o.account_id = p_account;
  if v_clave is null then
    return jsonb_build_object('iguales', '[]'::jsonb, 'fuera', '[]'::jsonb);
  end if;

  return jsonb_build_object(
    -- LAS QUE SE PUEDEN RESOLVER: mismo nombre, activas y SIN decidir todavia.
    -- Las que ya tienen efecto no salen: pisar una decision que alguien tomo a
    -- mano, sin pedirlo, seria lo contrario de esto.
    --
    -- «SIN DECIDIR» = sin ficha QUE DESCUENTE ALGO (13/09). Antes bastaba una
    -- fila confirmada, y una respuesta con ficha sin cantidad se quedaba fuera
    -- como «ya decidida»: la unica pantalla que podia arreglarla de un golpe
    -- era justo la que la escondia.
    --
    -- CEDIDAS DENTRO (14/09). Antes esta lista exigia marca propia. Lo que
    -- escribimos aqui es la FICHA, y la ficha es nuestra: el importador no la
    -- pisa --18 de 37 lo demuestran, tocadas despues y con su ficha intacta--.
    -- Cada fila dice si es cedida para que la pantalla pueda decirlo: se abre
    -- la puerta, no se disimula por donde se entra.
    'iguales', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', o.id, 'nombre', o.name,
               'pregunta', g.name, 'marca', b.name,
               'cedida', (coalesce(b.ownership_type,'own') <> 'own'),
               'precio', coalesce(o.price_impact,0))
             -- Propias primero, cedidas al final: agrupadas, no mezcladas.
             order by (coalesce(b.ownership_type,'own') <> 'own'), b.name, g.name), '[]'::jsonb)
        from modifier_option o
        join modifier_group g on g.id = o.modifier_group_id
        left join brand b on b.id = g.brand_id
       where o.account_id = p_account
         and o.id <> p_option_id
         and lower(btrim(o.name)) = v_clave
         and coalesce(o.is_active, true) and coalesce(g.is_active, true)
         and not exists (select 1 from modifier_recipe_impact i
                          where i.modifier_option_id = o.id and i.status = 'confirmed'
                            and public._impacto_completo(i.impact_type,
                                                        i.target_recipe_item_id,
                                                        i.quantity))),
    -- LAS QUE SE QUEDAN FUERA, Y POR QUE. No se esconden (regla 7): quien mira
    -- tiene que poder ver que hay 3 mas que no se tocan, y el motivo.
    --
    -- 🔴 «CEDIDA» YA NO ES UN MOTIVO (14/09). Lo era, y ademas se evaluaba el
    -- PRIMERO en este CASE, asi que tapaba a `ya_decidida`: 16 de las 17
    -- cedidas que salian aqui YA TENIAN FICHA y la pantalla las anunciaba como
    -- intocables. Eso es esconder trabajo hecho (regla 30). Ahora una cedida
    -- sale fuera por lo mismo que cualquier otra --ya decidida, o apagada-- y
    -- lleva su etiqueta al lado en vez de en lugar del motivo.
    'fuera', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', o.id, 'nombre', o.name,
               'pregunta', g.name, 'marca', b.name,
               'cedida', (coalesce(b.ownership_type,'own') <> 'own'),
               'motivo', case
                 when exists (select 1 from modifier_recipe_impact i
                               where i.modifier_option_id = o.id and i.status='confirmed'
                                 and public._impacto_completo(i.impact_type,
                                                             i.target_recipe_item_id,
                                                             i.quantity))
                   then 'ya_decidida'
                 else 'apagada' end)
             order by b.name, g.name), '[]'::jsonb)
        from modifier_option o
        join modifier_group g on g.id = o.modifier_group_id
        left join brand b on b.id = g.brand_id
       where o.account_id = p_account
         and o.id <> p_option_id
         and lower(btrim(o.name)) = v_clave
         and (not coalesce(o.is_active, true) or not coalesce(g.is_active, true)
              or exists (select 1 from modifier_recipe_impact i
                          where i.modifier_option_id = o.id and i.status='confirmed'
                            and public._impacto_completo(i.impact_type,
                                                        i.target_recipe_item_id,
                                                        i.quantity)))));
end;
$$;


--
-- Name: FUNCTION kitchen_las_iguales(p_account uuid, p_option_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_las_iguales(p_account uuid, p_option_id uuid) IS 'Las otras respuestas que se llaman IGUAL y siguen sin decidir, en marcas propias, para poder resolverlas de una vez. Y las que se quedan fuera, con su motivo.';


--
-- Name: kitchen_para_trabajar(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_para_trabajar(p_account uuid, p_dias integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_dias int := greatest(1, coalesce(p_dias, 30));
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;

  return (
  with viva as (
    select o.id, btrim(o.name) as nombre, lower(btrim(o.name)) as clave,
           coalesce(o.price_impact,0) as precio,
           g.id as pregunta_id, g.name as pregunta,
           coalesce(b.name,'Sin marca') as marca,
           (coalesce(b.ownership_type,'own') <> 'own') as cedida,
           exists (select 1 from modifier_recipe_impact i
                    where i.modifier_option_id = o.id and i.account_id = p_account
                      and i.status = 'confirmed'
                      and public._impacto_completo(i.impact_type,
                            i.target_recipe_item_id, i.quantity))          as decidida,
           (select max(i.confirmed_at) from modifier_recipe_impact i
             where i.modifier_option_id = o.id and i.account_id = p_account
               and i.status = 'confirmed')                                 as decidida_at
      from modifier_option o
      join modifier_group g on g.id = o.modifier_group_id
      left join brand b on b.id = g.brand_id
     where o.account_id = p_account
       and coalesce(o.is_active, true) and coalesce(g.is_active, true)
  ),
  -- Las ventas se cuentan SIN las anuladas, y las anuladas APARTE.
  ventas as (
    select v.id,
           count(*) filter (where s.cancelled_at is null)     as ventas,
           count(*) filter (where s.cancelled_at is not null) as anuladas
      from viva v
      join sale_line m on m.modifier_option_id = v.id and m.line_type = 'modifier'
      join sale s on s.id = m.sale_id and s.account_id = p_account
                 and s.sold_at >= now() - make_interval(days => v_dias)
     group by v.id
  ),
  ultima as (
    select v.id, max(s.sold_at) as cuando
      from viva v
      join sale_line m on m.modifier_option_id = v.id and m.line_type = 'modifier'
      join sale s on s.id = m.sale_id and s.account_id = p_account
                 and s.cancelled_at is null
     group by v.id
  ),
  -- MONTON 1 · por NOMBRE: resolver «Salsa Yogur» resuelve las 6.
  faltan as (
    select v.clave,
           max(v.nombre) as nombre,
           count(*) as cuantas,
           count(*) filter (where not v.cedida) as alcanzables,
           jsonb_agg(distinct v.marca) as marcas,
           (array_agg(v.id order by v.cedida, v.pregunta))[1] as por_donde_entrar
      from viva v
     where not v.decidida
     group by v.clave
  ),
  -- MONTON 2 · por FILA: retirar es de una fila en una pregunta concreta.
  sobran as (
    select v.id, v.nombre, v.pregunta_id, v.pregunta, v.marca, v.cedida,
           v.precio, v.decidida, v.decidida_at,
           (v.decidida_at is not null
            and v.decidida_at >= now() - make_interval(days => v_dias)) as decidida_reciente,
           coalesce(ve.anuladas, 0) as pedidos_anulados,
           u.cuando as ultima_venta,
           case when u.cuando is null then null
                else (extract(epoch from (now() - u.cuando)) / 86400)::int end as dias_sin_venderse
      from viva v
      left join ventas ve on ve.id = v.id
      left join ultima u  on u.id = v.id
     where coalesce(ve.ventas, 0) = 0
  )
  select jsonb_build_object(
    'dias', v_dias,
    'le_falta_decir_que_lleva', jsonb_build_object(
      'respuestas', (select count(*) from viva where not decidida),
      'alcanzables',(select count(*) from viva where not decidida and not cedida),
      'nombres',    (select count(*) from faltan),
      'filas', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'nombre', f.nombre, 'cuantas', f.cuantas,
                 'alcanzables', f.alcanzables, 'marcas', f.marcas,
                 'entrar_por', f.por_donde_entrar)
               order by f.alcanzables desc, f.cuantas desc, f.nombre)
          from faltan f), '[]'::jsonb)),
    'no_lo_pide_nadie', jsonb_build_object(
      'respuestas',  (select count(*) from sobran),
      -- CANDIDATAS = propias que nadie ha tocado en un mes. Es el numero que
      -- de verdad dice cuanto hay que limpiar; el total dice cuanto hay.
      'candidatas',  (select count(*) from sobran where not cedida and not decidida_reciente),
      'alcanzables', (select count(*) from sobran where not cedida),
      'decididas_hace_poco', (select count(*) from sobran where not cedida and decidida_reciente),
      'cedidas',     (select count(*) from sobran where cedida),
      'preguntas',   (select count(distinct pregunta_id) from sobran),
      'con_pedido_anulado', (select count(*) from sobran where pedidos_anulados > 0),
      'filas', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'id', s.id, 'nombre', s.nombre, 'pregunta', s.pregunta,
                 'pregunta_id', s.pregunta_id, 'marca', s.marca,
                 'cedida', s.cedida, 'precio', s.precio,
                 'pedidos_anulados', s.pedidos_anulados,
                 'ultima_venta', s.ultima_venta,
                 'dias_sin_venderse', s.dias_sin_venderse,
                 'decidida', s.decidida, 'decidida_at', s.decidida_at,
                 'decidida_reciente', s.decidida_reciente)
               -- LOS TRES ESCALONES. Ninguno esconde: los tres se pintan.
               order by s.cedida,
                        s.decidida_reciente,
                        (s.dias_sin_venderse is not null),
                        s.dias_sin_venderse desc nulls first,
                        s.marca, s.pregunta, s.nombre)
          from sobran s), '[]'::jsonb))));
end;
$$;


--
-- Name: FUNCTION kitchen_para_trabajar(p_account uuid, p_dias integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_para_trabajar(p_account uuid, p_dias integer) IS 'La entrada del gestor: los DOS montones. El que falta va por NOMBRE (resolver uno resuelve todos los que se llaman igual); el que sobra va por FILA y en TRES escalones — candidatas, decididas hace poco, y cedidas — porque avisar del solape no basta: si lo primero que ves es la trampa, el cartel llega tarde.';


--
-- Name: kitchen_platos_de_la_marca(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_platos_de_la_marca(p_account uuid, p_brand_id uuid, p_group_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'platos', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', mi.id, 'nombre', mi.name,
               'categoria_id', mi.menu_category_id,
               'categoria', coalesce(mc.name, 'Sin categoría'),
               -- Si YA la tiene, para que la pantalla arranque con la verdad
               -- puesta y «lo que cambia» se pueda calcular contra ella.
               'ya_la_tiene', (p_group_id is not null and exists (
                 select 1 from modifier_group_assignment a
                  where a.modifier_group_id = p_group_id
                    and a.menu_item_id = mi.id)),
               -- Cuantas preguntas tiene ya ese plato: 9 preguntas en un plato
               -- es una carta que el cliente no termina de leer.
               'cuantas_preguntas', (
                 select count(*) from modifier_group_assignment a2
                  where a2.menu_item_id = mi.id))
             order by coalesce(mc.name,'zzz'), mi.name), '[]'::jsonb)
        from menu_item mi
        left join menu_category mc on mc.id = mi.menu_category_id
       where mi.account_id = p_account and mi.brand_id = p_brand_id
         and mi.archived_at is null),
    'categorias', (
      select coalesce(jsonb_agg(x order by x->>'nombre'), '[]'::jsonb) from (
        select jsonb_build_object(
                 'id', coalesce(mi.menu_category_id::text, 'sin'),
                 'nombre', coalesce(mc.name, 'Sin categoría'),
                 'cuantos_platos', count(*)) as x
          from menu_item mi
          left join menu_category mc on mc.id = mi.menu_category_id
         where mi.account_id = p_account and mi.brand_id = p_brand_id
           and mi.archived_at is null
         group by mi.menu_category_id, mc.name) s));
end;
$$;


--
-- Name: FUNCTION kitchen_platos_de_la_marca(p_account uuid, p_brand_id uuid, p_group_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_platos_de_la_marca(p_account uuid, p_brand_id uuid, p_group_id uuid) IS 'Tablero 3: los platos vivos de una marca con su categoria, si ya tienen la pregunta, y cuantas preguntas lleva ya cada uno.';


--
-- Name: kitchen_poner_pregunta_en_platos(uuid, uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_poner_pregunta_en_platos(p_account uuid, p_group_id uuid, p_platos uuid[], p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_brand    uuid;
  v_nombre   text;
  v_marca    text;
  v_puestos  int := 0;
  v_quitados int := 0;
  v_mala     text;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para poner preguntas en los platos de la cuenta %', p_account
      using errcode = '42501';
  end if;

  select g.brand_id, g.name into v_brand, v_nombre
    from modifier_group g where g.id = p_group_id and g.account_id = p_account;
  if v_brand is null then
    raise exception 'Esa pregunta no es de esta cuenta. No se ha escrito nada.'
      using errcode = '42501';
  end if;

  select b.name into v_marca from brand b where b.id = v_brand;
  if exists (select 1 from brand b
              where b.id = v_brand and coalesce(b.ownership_type,'own') <> 'own') then
    raise exception 'La carta de «%» la manda Last: aquí no se ponen preguntas en platos. No se ha escrito nada.', v_marca
      using errcode = '42501';
  end if;

  -- LOS PLATOS, DE LA MISMA MARCA. Poner una pregunta de Dos Coyotes en un
  -- plato de Milanesa Haus no es un error de dedo: es una carta rota.
  select mi.name into v_mala
    from unnest(coalesce(p_platos, '{}'::uuid[])) x(id)
    left join menu_item mi on mi.id = x.id
   where mi.id is null or mi.account_id <> p_account or mi.brand_id <> v_brand
      or mi.archived_at is not null
   limit 1;
  if v_mala is not null or exists (
       select 1 from unnest(coalesce(p_platos,'{}'::uuid[])) x(id)
        where not exists (select 1 from menu_item mi where mi.id = x.id)) then
    raise exception 'El plato «%» no es de esta marca, no es de esta cuenta o está archivado. No se ha escrito nada.',
      coalesce(v_mala, '?') using errcode = '42501';
  end if;

  delete from modifier_group_assignment a
   where a.modifier_group_id = p_group_id and a.account_id = p_account
     and not (a.menu_item_id = any(coalesce(p_platos, '{}'::uuid[])));
  get diagnostics v_quitados = row_count;

  insert into modifier_group_assignment (account_id, modifier_group_id, menu_item_id, position)
  select p_account, p_group_id, x.id, 0
    from unnest(coalesce(p_platos, '{}'::uuid[])) x(id)
  on conflict (modifier_group_id, menu_item_id) do nothing;
  get diagnostics v_puestos = row_count;

  -- Devuelve CONTENIDO, no un visto (regla 8): «Publicado. Avisadas 4 personas»
  -- dice algo; «Hecho» no.
  return jsonb_build_object(
    'pregunta',  v_nombre,
    'marca',     v_marca,
    'puestos',   v_puestos,
    'quitados',  v_quitados,
    'total',     coalesce(array_length(p_platos, 1), 0),
    'actor',     p_actor);
end;
$$;


--
-- Name: FUNCTION kitchen_poner_pregunta_en_platos(p_account uuid, p_group_id uuid, p_platos uuid[], p_actor text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_poner_pregunta_en_platos(p_account uuid, p_group_id uuid, p_platos uuid[], p_actor text) IS 'Tablero 3: pone una pregunta en un conjunto de platos de SU MISMA marca propia. La lista es la verdad: lo que no viene, se quita.';


--
-- Name: kitchen_pregunta_para_editar(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_pregunta_para_editar(p_account uuid, p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_marcas jsonb;
  v_p      jsonb;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;

  -- Las marcas SALEN TODAS, propias y cedidas, con su bandera. Esconder las
  -- cedidas del selector dejaria a quien las busca pensando que se han
  -- perdido; se ven y se dice por que no se tocan (regla 7).
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', b.id, 'nombre', b.name,
           'cedida', (coalesce(b.ownership_type,'own') <> 'own'),
           'platos', (select count(*) from menu_item mi
                       where mi.brand_id = b.id and mi.archived_at is null))
         order by (coalesce(b.ownership_type,'own') <> 'own'), b.name), '[]'::jsonb)
    into v_marcas
    from brand b
   where b.account_id = p_account and coalesce(b.is_active, true)
     and upper(btrim(coalesce(b.name,''))) <> 'FOODINT';

  if p_group_id is null then
    return jsonb_build_object('marcas', v_marcas, 'pregunta', null);
  end if;

  select jsonb_build_object(
           'id', g.id, 'nombre', g.name, 'marca_id', g.brand_id,
           'marca_nombre', b.name,
           'cedida', (coalesce(b.ownership_type,'own') <> 'own'),
           'tipo', g.group_type,
           'obligatoria', (coalesce(g.min_selections,0) > 0),
           'max', coalesce(g.max_selections,1),
           'repetible', coalesce(g.allow_repetition,false),
           'etiqueta_vieja', (g.external_source is not null),
           'platos', (select coalesce(jsonb_agg(a.menu_item_id), '[]'::jsonb)
                        from modifier_group_assignment a
                       where a.modifier_group_id = g.id),
           'respuestas', (
             select coalesce(jsonb_agg(jsonb_build_object(
                      'id', o.id, 'nombre', o.name,
                      'precio', coalesce(o.price_impact,0),
                      -- El efecto CONFIRMADO, si lo hay. Una respuesta puede
                      -- tener propuestas sin confirmar: esas no cuentan como
                      -- decididas ni aqui ni en el tablero 1.
                      'efecto', (
                        select jsonb_build_object(
                                 'tipo', i.impact_type,
                                 'ficha', i.target_recipe_item_id,
                                 'ficha_nombre', ri.name,
                                 'cantidad', i.quantity,
                                 'unidad', i.unit_id)
                          from modifier_recipe_impact i
                          left join recipe_item ri on ri.id = i.target_recipe_item_id
                         where i.modifier_option_id = o.id and i.status = 'confirmed'
                         limit 1),
                      -- En cuantas preguntas MAS vive un extra con este nombre.
                      -- Es lo que avisa de que tocarlo aqui no lo arregla alli.
                      'en_cuantas_preguntas', (
                        select count(distinct o2.modifier_group_id)
                          from modifier_option o2
                         where o2.account_id = p_account
                           and lower(btrim(o2.name)) = lower(btrim(o.name))
                           and coalesce(o2.is_active,true)))
                    order by o.position, o.name), '[]'::jsonb)
               from modifier_option o
              where o.modifier_group_id = g.id and coalesce(o.is_active,true)))
    into v_p
    from modifier_group g
    left join brand b on b.id = g.brand_id
   where g.id = p_group_id and g.account_id = p_account;

  return jsonb_build_object('marcas', v_marcas, 'pregunta', v_p);
end;
$$;


--
-- Name: FUNCTION kitchen_pregunta_para_editar(p_account uuid, p_group_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_pregunta_para_editar(p_account uuid, p_group_id uuid) IS 'Tablero 5: las marcas y, si se edita, la pregunta entera con sus respuestas y el efecto confirmado de cada una.';


--
-- Name: kitchen_preguntas_de_un_plato(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_preguntas_de_un_plato(p_account uuid, p_menu_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plato jsonb;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para mirar los platos de la cuenta %', p_account
      using errcode = '42501';
  end if;

  -- EL PLATO. Regla 9: por cuenta, siempre. El catalogo plantilla comparte
  -- tablas Y NOMBRES con produccion.
  select jsonb_build_object(
           'id', mi.id,
           'nombre', btrim(mi.name),
           'precio', coalesce(mi.price, 0),
           'marca', coalesce(b.name, 'Sin marca'),
           'marca_id', b.id,
           'cedida', (coalesce(b.ownership_type, 'own') <> 'own'),
           'activo', coalesce(mi.is_active, true),
           'archivado', (mi.archived_at is not null))
    into v_plato
    from menu_item mi
    left join brand b on b.id = mi.brand_id
   where mi.id = p_menu_item_id and mi.account_id = p_account;

  if v_plato is null then
    raise exception 'Ese plato no es de esta cuenta.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'plato', v_plato,
    'preguntas', (
      select coalesce(jsonb_agg(x order by (x->>'posicion')::int, x->>'nombre'), '[]'::jsonb)
        from (
          select jsonb_build_object(
                   'id', g.id,
                   'nombre', btrim(g.name),
                   'tipo', case g.group_type when 'choice' then 'elige'
                                             when 'extras' then 'anade'
                                             when 'removal' then 'quita'
                                             else coalesce(g.group_type, 'elige') end,
                   'min', coalesce(g.min_selections, 0),
                   'max', coalesce(g.max_selections, 1),
                   'obligatoria', (coalesce(g.min_selections, 0) > 0),
                   'repetible', coalesce(g.allow_repetition, false),
                   'activa', coalesce(g.is_active, true),
                   'posicion', coalesce(a.position, 0),
                   -- SOLO ACTIVAS: una respuesta retirada no se vende, asi que
                   -- no cuenta ni para el total ni para lo que falta.
                   'de_pago', exists (select 1 from modifier_option o
                                       where o.modifier_group_id = g.id
                                         and coalesce(o.is_active, true)
                                         and coalesce(o.price_impact, 0) > 0),
                   'respuestas', (select count(*) from modifier_option o
                                   where o.modifier_group_id = g.id
                                     and coalesce(o.is_active, true)),
                   -- SIN DECIDIR = sin ficha QUE DESCUENTE ALGO. La misma
                   -- frase que el resto del gestor, en su unico sitio.
                   'sin_decidir', (select count(*) from modifier_option o
                                    where o.modifier_group_id = g.id
                                      and coalesce(o.is_active, true)
                                      and not exists (
                                        select 1 from modifier_recipe_impact i
                                         where i.modifier_option_id = o.id
                                           and i.status = 'confirmed'
                                           and public._impacto_completo(
                                                 i.impact_type,
                                                 i.target_recipe_item_id,
                                                 i.quantity))),
                   -- Y en cuantos platos MAS esta, que es lo que decide si
                   -- quitarla de aqui es un gesto pequeno o se lleva la unica.
                   'otros_platos', (select count(*) from modifier_group_assignment a2
                                     where a2.modifier_group_id = g.id
                                       and a2.account_id = p_account
                                       and a2.menu_item_id <> p_menu_item_id),
                   'se_puede_quitar', (coalesce(b.ownership_type, 'own') = 'own'),
                   'por_que_no', case
                     when coalesce(b.ownership_type, 'own') <> 'own'
                       then 'La carta de «' || coalesce(b.name, 'esta marca')
                            || '» la manda Last: sus preguntas se ponen y se quitan allí. '
                            || 'Si la quitaras aquí, volvería de madrugada.'
                     else null end) as x
            from modifier_group_assignment a
            join modifier_group g on g.id = a.modifier_group_id
            left join brand b on b.id = g.brand_id
           where a.menu_item_id = p_menu_item_id
             and a.account_id = p_account
             and g.account_id = p_account
        ) q),
    'cuantas', (select count(*) from modifier_group_assignment a
                 where a.menu_item_id = p_menu_item_id and a.account_id = p_account));
end;
$$;


--
-- Name: kitchen_quitar_pregunta_de_plato(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_quitar_pregunta_de_plato(p_account uuid, p_group_id uuid, p_menu_item_id uuid, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pregunta text; v_plato text; v_marca text; v_cedida boolean;
  v_quitadas int := 0; v_quedan int;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para quitar preguntas de los platos de la cuenta %', p_account
      using errcode = '42501';
  end if;

  select btrim(g.name), coalesce(b.name, 'Sin marca'),
         (coalesce(b.ownership_type, 'own') <> 'own')
    into v_pregunta, v_marca, v_cedida
    from modifier_group g
    left join brand b on b.id = g.brand_id
   where g.id = p_group_id and g.account_id = p_account;
  if v_pregunta is null then
    raise exception 'Esa pregunta no es de esta cuenta. No se ha escrito nada.'
      using errcode = '42501';
  end if;

  select btrim(mi.name) into v_plato
    from menu_item mi
   where mi.id = p_menu_item_id and mi.account_id = p_account;
  if v_plato is null then
    raise exception 'Ese plato no es de esta cuenta. No se ha escrito nada.'
      using errcode = '42501';
  end if;

  if v_cedida then
    raise exception 'La carta de «%» la manda Last: aquí no se quitan preguntas de los platos. Lo que quitases volvería de madrugada. No se ha escrito nada.', v_marca
      using errcode = '42501';
  end if;

  delete from modifier_group_assignment a
   where a.modifier_group_id = p_group_id
     and a.menu_item_id = p_menu_item_id
     and a.account_id = p_account;
  get diagnostics v_quitadas = row_count;

  if v_quitadas = 0 then
    raise exception 'La pregunta «%» no estaba en «%». No se ha escrito nada.', v_pregunta, v_plato
      using errcode = '22023';
  end if;

  select count(*) into v_quedan
    from modifier_group_assignment a
   where a.menu_item_id = p_menu_item_id and a.account_id = p_account;

  -- Devuelve CONTENIDO, no un visto (regla 8). Con el numero que la pantalla
  -- necesita para actualizarse sin recargar y sin inventarselo restando.
  return jsonb_build_object(
    'pregunta', v_pregunta,
    'plato', v_plato,
    'marca', v_marca,
    'quitadas', v_quitadas,
    'le_quedan', v_quedan,
    -- Y donde sigue viva, que es lo que evita el susto de «la he borrado».
    'sigue_en_platos', (select count(*) from modifier_group_assignment a2
                         where a2.modifier_group_id = p_group_id
                           and a2.account_id = p_account),
    'actor', p_actor);
end;
$$;


--
-- Name: kitchen_raw_usage_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_raw_usage_counts(p_account_id uuid) RETURNS TABLE(child_item_id uuid, usage_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Guard de tenancy: admin de plataforma (CEO) O admin/manager de la cuenta.
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'kitchen_raw_usage_counts: sin acceso a la cuenta %', p_account_id;
  END IF;

  RETURN QUERY
    SELECT rl.child_item_id,
           COUNT(DISTINCT rl.parent_item_id) AS usage_count
    FROM recipe_line rl
    JOIN recipe_item parent ON parent.id = rl.parent_item_id
    WHERE rl.account_id = p_account_id
      AND parent.type = 'dish'
    GROUP BY rl.child_item_id;
END;
$$;


--
-- Name: kitchen_recipe_breakdown(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_recipe_breakdown(p_item_id uuid) RETURNS TABLE(line_id uuid, child_item_id uuid, child_name text, child_type text, quantity numeric, quantity_net numeric, unit_abbr text, line_cost numeric, needs_review boolean, child_needs_review boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item            recipe_item%ROWTYPE;
  v_line            recipe_line%ROWTYPE;
  v_child           recipe_item%ROWTYPE;
  v_line_unit       kitchen_unit%ROWTYPE;
  v_child_base_unit kitchen_unit%ROWTYPE;
  v_qty             numeric;
  v_qty_in_base     numeric;
  v_child_cost      numeric;
  v_conv            numeric;
  v_line_total      numeric;
  v_line_incomplete boolean;
BEGIN
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kitchen_recipe_breakdown: item % no existe', p_item_id;
  END IF;
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(v_item.account_id)) THEN
    RAISE EXCEPTION 'kitchen_recipe_breakdown: sin acceso al item %', p_item_id;
  END IF;
  IF v_item.type NOT IN ('recipe', 'dish') THEN
    RETURN;
  END IF;
  FOR v_line IN
    SELECT * FROM recipe_line WHERE parent_item_id = p_item_id
    ORDER BY position ASC, created_at ASC
  LOOP
    SELECT * INTO v_child           FROM recipe_item  WHERE id = v_line.child_item_id;
    SELECT * INTO v_line_unit       FROM kitchen_unit WHERE id = v_line.unit_id;
    SELECT * INTO v_child_base_unit FROM kitchen_unit WHERE id = v_child.base_unit_id;
    v_child_cost := COALESCE(v_child.computed_cost, v_child.fixed_cost, 0);
    v_qty := COALESCE(v_line.quantity_gross, v_line.quantity_net);
    v_line_incomplete := false;
    IF v_line_unit.dimension = v_child_base_unit.dimension THEN
      v_qty_in_base := v_qty * v_line_unit.factor_to_base / v_child_base_unit.factor_to_base;
    ELSE
      SELECT qty_in_base INTO v_conv
        FROM recipe_item_unit_conversion
        WHERE item_id = v_child.id AND from_unit_id = v_line.unit_id
        LIMIT 1;
      IF v_conv IS NOT NULL THEN
        v_qty_in_base := v_qty * v_conv;
      ELSE
        v_line_incomplete := true;
        v_qty_in_base := 0;
      END IF;
    END IF;
    v_line_total := v_child_cost * v_qty_in_base;
    line_id            := v_line.id;
    child_item_id      := v_line.child_item_id;
    child_name         := v_child.name;
    child_type         := v_child.type;          -- NUEVO: tipo del hijo
    quantity           := v_qty;
    quantity_net       := v_line.quantity_net;
    unit_abbr          := v_line_unit.abbreviation;
    line_cost          := v_line_total;
    needs_review       := v_line_incomplete;
    child_needs_review := COALESCE(v_child.needs_review, false);
    RETURN NEXT;
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: kitchen_recipe_cost_by_location(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_recipe_cost_by_location(p_item_id uuid, p_location_id uuid) RETURNS TABLE(line_id uuid, child_item_id uuid, child_name text, quantity numeric, unit_abbr text, line_cost numeric, cost_source text, needs_review boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item            recipe_item%ROWTYPE;
  v_line            recipe_line%ROWTYPE;
  v_child           recipe_item%ROWTYPE;
  v_line_unit       kitchen_unit%ROWTYPE;
  v_child_base_unit kitchen_unit%ROWTYPE;
  v_qty             numeric;
  v_qty_in_base     numeric;
  v_child_cost      numeric;
  v_cost_source     text;
  v_loc_cost        numeric;
  v_conv            numeric;
  v_line_total      numeric;
  v_line_incomplete boolean;
BEGIN
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kitchen_recipe_cost_by_location: item % no existe', p_item_id;
  END IF;
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(v_item.account_id)) THEN
    RAISE EXCEPTION 'kitchen_recipe_cost_by_location: sin acceso al item %', p_item_id;
  END IF;
  IF v_item.type NOT IN ('recipe', 'dish') THEN
    RETURN;
  END IF;

  FOR v_line IN
    SELECT * FROM recipe_line WHERE parent_item_id = p_item_id
    ORDER BY position ASC, created_at ASC
  LOOP
    SELECT * INTO v_child           FROM recipe_item  WHERE id = v_line.child_item_id;
    SELECT * INTO v_line_unit       FROM kitchen_unit WHERE id = v_line.unit_id;
    SELECT * INTO v_child_base_unit FROM kitchen_unit WHERE id = v_child.base_unit_id;

    -- ── ÚNICO CAMBIO: coste del ingrediente POR LOCAL, con fallback ──
    v_loc_cost := NULL;
    SELECT unit_cost INTO v_loc_cost
      FROM recipe_item_location_cost
      WHERE recipe_item_id = v_child.id AND location_id = p_location_id
      LIMIT 1;

    IF v_loc_cost IS NOT NULL THEN
      v_child_cost  := v_loc_cost;
      v_cost_source := 'location';
    ELSIF v_child.computed_cost IS NOT NULL THEN
      v_child_cost  := v_child.computed_cost;
      v_cost_source := 'global';
    ELSIF v_child.fixed_cost IS NOT NULL THEN
      v_child_cost  := v_child.fixed_cost;
      v_cost_source := 'fixed';
    ELSE
      v_child_cost  := 0;
      v_cost_source := 'none';
    END IF;
    -- ────────────────────────────────────────────────────────────────

    v_qty := COALESCE(v_line.quantity_gross, v_line.quantity_net);
    v_line_incomplete := (v_cost_source = 'none');

    IF v_line_unit.dimension = v_child_base_unit.dimension THEN
      v_qty_in_base := v_qty * v_line_unit.factor_to_base / v_child_base_unit.factor_to_base;
    ELSE
      SELECT qty_in_base INTO v_conv
        FROM recipe_item_unit_conversion
        WHERE item_id = v_child.id AND from_unit_id = v_line.unit_id
        LIMIT 1;
      IF v_conv IS NOT NULL THEN
        v_qty_in_base := v_qty * v_conv;
      ELSE
        v_line_incomplete := true;
        v_qty_in_base := 0;
      END IF;
    END IF;

    v_line_total := v_child_cost * v_qty_in_base;

    line_id       := v_line.id;
    child_item_id := v_line.child_item_id;
    child_name    := v_child.name;
    quantity      := v_line.quantity_net;
    unit_abbr     := v_line_unit.abbreviation;
    line_cost     := v_line_total;
    cost_source   := v_cost_source;
    needs_review  := v_line_incomplete;
    RETURN NEXT;
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: kitchen_recompute_all(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_recompute_all(p_account_id uuid, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row       record;
  v_total     int := 0;
  v_processed int := 0;
  v_failed    int := 0;
  v_errors    jsonb := '[]'::jsonb;
  v_is_server boolean;
begin
  v_is_server := session_user in ('postgres', 'supabase_admin');

  if not v_is_server then
    if auth.uid() is null
       or not public.current_user_is_admin_or_manager_of(p_account_id) then
      raise exception 'kitchen_recompute_all: sin acceso a la cuenta %', p_account_id;
    end if;
  end if;

  select count(*) into v_total
    from recipe_item ri
   where ri.account_id = p_account_id
     and ri.type in ('recipe', 'dish')
     and ri.archived_at is null;

  for v_row in
    select ri.id, ri.name, ri.type
      from recipe_item ri
     where ri.account_id = p_account_id
       and ri.type in ('recipe', 'dish')
       and ri.archived_at is null
     order by (ri.type = 'dish'), ri.name, ri.id
     limit p_limit offset coalesce(p_offset, 0)
  loop
    begin
      perform public._kitchen_recompute_item_unguarded(v_row.id);
      v_processed := v_processed + 1;
    exception when others then
      v_failed := v_failed + 1;
      v_errors := v_errors || jsonb_build_object(
        'item_id', v_row.id, 'name', v_row.name, 'type', v_row.type,
        'error', sqlerrm, 'sqlstate', sqlstate);
      raise warning 'kitchen_recompute_all: fallo en % (%): %', v_row.name, v_row.id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object(
    'account_id', p_account_id,
    'total',      v_total,
    'processed',  v_processed,
    'failed',     v_failed,
    'errors',     v_errors);
end;
$$;


--
-- Name: kitchen_recompute_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_recompute_item(p_item_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_account uuid;
begin
  select account_id into v_account from recipe_item where id = p_item_id;
  if v_account is null then
    raise exception 'kitchen_recompute_item: item % no existe', p_item_id;
  end if;
  if not public.belongs_to_account(v_account) then
    raise exception 'kitchen_recompute_item: sin acceso al item %', p_item_id;
  end if;
  return public._kitchen_recompute_item_unguarded(p_item_id);
end;
$$;


--
-- Name: kitchen_recompute_raw_cost(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_recompute_raw_cost(p_item_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
begin
  select account_id into v_account from recipe_item where id = p_item_id;
  if not found then
    raise exception 'kitchen_recompute_raw_cost: item % no existe', p_item_id;
  end if;
  if not public.belongs_to_account(v_account) then
    raise exception 'kitchen_recompute_raw_cost: sin acceso al item %', p_item_id;
  end if;
  return public._kitchen_recompute_raw_cost_unguarded(p_item_id);
end;
$$;


--
-- Name: kitchen_recompute_users_of(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_recompute_users_of(p_item_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item   recipe_item%ROWTYPE;
  v_parent uuid;
  v_count  integer := 0;
BEGIN
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kitchen_recompute_users_of: item % no existe', p_item_id;
  END IF;
  IF NOT public.belongs_to_account(v_item.account_id) THEN
    RAISE EXCEPTION 'kitchen_recompute_users_of: sin acceso al item %', p_item_id;
  END IF;

  FOR v_parent IN
    SELECT DISTINCT parent_item_id
    FROM recipe_line
    WHERE child_item_id = p_item_id
  LOOP
    PERFORM public.kitchen_recompute_item(v_parent);
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: kitchen_retirar(uuid, uuid[], uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_retirar(p_account uuid, p_opciones uuid[] DEFAULT NULL::uuid[], p_pregunta uuid DEFAULT NULL::uuid, p_actor text DEFAULT NULL::text, p_encender boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_mala      text;
  v_opciones  int := 0;
  v_preguntas int := 0;
  v_n         int := 0;
  v_nombre    text;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso para retirar de la cuenta %', p_account
      using errcode = '42501';
  end if;

  if (p_opciones is null or array_length(p_opciones,1) is null) and p_pregunta is null then
    raise exception 'No se ha dicho qué retirar.' using errcode = '22023';
  end if;

  -- EN CEDIDAS NO SE RETIRA NADA. Last las reescribe cada noche a las 03:20:
  -- lo retirado volveria, y nadie se enteraria de que ha vuelto.
  select b.name into v_mala
    from modifier_option o
    join modifier_group g on g.id = o.modifier_group_id
    left join brand b on b.id = g.brand_id
   where o.id = any(coalesce(p_opciones,'{}'::uuid[]))
     and (o.account_id <> p_account or coalesce(b.ownership_type,'own') <> 'own')
   limit 1;
  if v_mala is null and p_pregunta is not null then
    select b.name into v_mala from modifier_group g
      left join brand b on b.id = g.brand_id
     where g.id = p_pregunta
       and (g.account_id <> p_account or coalesce(b.ownership_type,'own') <> 'own');
  end if;
  if v_mala is not null then
    raise exception 'La carta de «%» la manda Last y la reescribe cada noche: lo que retirases aquí volvería a las 03:20. No se ha escrito nada.', v_mala
      using errcode = '42501';
  end if;

  -- ── LAS RESPUESTAS SUELTAS ──────────────────────────────────────────────
  if p_opciones is not null and array_length(p_opciones,1) is not null then
    if p_encender then
      update modifier_option
         set is_active = true, deactivated_at = null, deactivated_by = null,
             updated_at = now()
       where id = any(p_opciones) and account_id = p_account;
    else
      update modifier_option
         set is_active = false, deactivated_at = now(),
             deactivated_by = 'persona', updated_at = now()
       where id = any(p_opciones) and account_id = p_account;
    end if;
    get diagnostics v_n = row_count;
    v_opciones := v_opciones + v_n;
  end if;

  -- ── LA PREGUNTA ENTERA ──────────────────────────────────────────────────
  if p_pregunta is not null then
    select g.name into v_nombre from modifier_group g
     where g.id = p_pregunta and g.account_id = p_account;
    if v_nombre is null then
      raise exception 'Esa pregunta no es de esta cuenta. No se ha escrito nada.'
        using errcode = '42501';
    end if;

    if p_encender then
      update modifier_group set is_active = true, updated_at = now()
       where id = p_pregunta and account_id = p_account;
      get diagnostics v_preguntas = row_count;
      update modifier_option
         set is_active = true, deactivated_at = null, deactivated_by = null,
             updated_at = now()
       where modifier_group_id = p_pregunta and account_id = p_account
         and deactivated_by = 'persona';
      get diagnostics v_n = row_count;
    else
      update modifier_group set is_active = false, updated_at = now()
       where id = p_pregunta and account_id = p_account;
      get diagnostics v_preguntas = row_count;
      update modifier_option
         set is_active = false, deactivated_at = now(),
             deactivated_by = 'persona', updated_at = now()
       where modifier_group_id = p_pregunta and account_id = p_account
         and coalesce(is_active, true);
      get diagnostics v_n = row_count;
    end if;
    v_opciones := v_opciones + v_n;
  end if;

  return jsonb_build_object(
    'encendido',  p_encender,
    'respuestas', v_opciones,
    'preguntas',  v_preguntas,
    'pregunta',   v_nombre,
    'actor',      p_actor);
end;
$$;


--
-- Name: FUNCTION kitchen_retirar(p_account uuid, p_opciones uuid[], p_pregunta uuid, p_actor text, p_encender boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.kitchen_retirar(p_account uuid, p_opciones uuid[], p_pregunta uuid, p_actor text, p_encender boolean) IS 'Retira (o vuelve a encender) respuestas sueltas o una pregunta entera. Se RETIRA, no se borra: sello de persona en cada respuesta. Al reencender una pregunta solo revive lo que apago una persona, no lo que apago Last. En marcas cedidas aborta.';


--
-- Name: kitchen_similar_dishes_for_ai(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_similar_dishes_for_ai(p_recipe_item_id uuid, p_n integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  WITH base AS (
    SELECT account_id, family_id, computed_cost
    FROM recipe_item
    WHERE id = p_recipe_item_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', ri.id,
    'name', ri.name,
    'family_id', ri.family_id,
    'computed_cost', ri.computed_cost
  ) ORDER BY
      (ri.family_id IS NOT DISTINCT FROM base.family_id) DESC,
      abs(COALESCE(ri.computed_cost, 0) - COALESCE(base.computed_cost, 0)) ASC
  ), '[]'::jsonb)
  FROM recipe_item ri, base
  WHERE ri.account_id = base.account_id
    AND ri.id <> p_recipe_item_id
    AND ri.type = 'dish'
    AND ri.is_active = true
  LIMIT p_n;
$$;


--
-- Name: kitchen_time_stats(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_time_stats(p_location_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c_prog_gap constant interval := interval '45 minutes';
  v_account_id uuid;
  v_tz         text;
  v_cfg        kitchen_time_config;
  v_result     jsonb;
begin
  if p_location_id is null or p_from is null or p_to is null then
    raise exception 'kitchen_time_stats: faltan parámetros (location, from, to)';
  end if;
  select account_id into v_account_id from locations where id = p_location_id;
  if v_account_id is null then raise exception 'kitchen_time_stats: ubicación inexistente'; end if;
  if not belongs_to_account(v_account_id) then raise exception 'kitchen_time_stats: sin acceso'; end if;

  select coalesce(a.timezone, 'Europe/Madrid') into v_tz from accounts a where a.id = v_account_id;
  select * into v_cfg from kitchen_time_config where location_id = p_location_id;

  with base as (
    select
      s.id, s.brand_id, s.accepted_at, s.ready_at,
      (s.accepted_at at time zone v_tz) as accepted_local,
      case
        when s.order_status in ('cancelled','rejected','delivery_failed') then false
        when s.accepted_at is null then false
        when s.expected_time is not null and s.expected_time > s.accepted_at + c_prog_gap then false
        else true
      end as elegible,
      case when s.ready_at is not null and s.accepted_at is not null
           then extract(epoch from (s.ready_at - s.accepted_at)) / 60.0 end as cook_min
    from sale s
    where s.location_id = p_location_id
      and s.account_id  = v_account_id
      and coalesce(s.accepted_at, s.sold_at, s.created_at) >= p_from
      and coalesce(s.accepted_at, s.sold_at, s.created_at) <  p_to
  ),
  medibles as (
    select b.*, b.cook_min as t
    from base b
    where b.elegible and b.cook_min is not null
      and b.cook_min >= coalesce(v_cfg.floor_minutes, 0)
  )
  select jsonb_build_object(
    'location_id', p_location_id,
    'from', p_from, 'to', p_to,
    'config', case when v_cfg.location_id is null then null else jsonb_build_object(
      'green_max_minutes', v_cfg.green_max_minutes,
      'amber_max_minutes', v_cfg.amber_max_minutes,
      'ceiling_minutes',   v_cfg.ceiling_minutes,
      'floor_minutes',     v_cfg.floor_minutes,
      'enabled',           v_cfg.enabled
    ) end,
    'summary', (
      select jsonb_build_object(
        'n_medidos',       count(*),
        'mediana_min',     round(percentile_cont(0.5) within group (order by t)::numeric, 1),
        'peor_min',        round(max(t)::numeric, 1),
        'pct_en_objetivo', case when count(*) = 0 then null
                                else round(100.0 * count(*) filter (where t <= v_cfg.amber_max_minutes) / count(*), 0) end,
        'pct_en_verde',    case when count(*) = 0 then null
                                else round(100.0 * count(*) filter (where t <= v_cfg.green_max_minutes) / count(*), 0) end,
        'pct_sobre_techo', case when count(*) = 0 then null
                                else round(100.0 * count(*) filter (where t > v_cfg.ceiling_minutes) / count(*), 0) end
      ) from medibles
    ),
    'adopcion', (
      select jsonb_build_object(
        'elegibles',      count(*) filter (where elegible),
        'con_listo',      count(*) filter (where elegible and ready_at is not null),
        'pct',            case when count(*) filter (where elegible) = 0 then null
                               else round(100.0 * count(*) filter (where elegible and ready_at is not null)
                                                / count(*) filter (where elegible), 0) end,
        'representativo', (count(*) filter (where elegible) > 0
                           and count(*) filter (where elegible and ready_at is not null)::numeric
                               / nullif(count(*) filter (where elegible), 0) >= 0.80)
      ) from base
    ),
    'por_hora', coalesce((
      select jsonb_agg(jsonb_build_object('hora', hh, 'n', n, 'mediana_min', med) order by hh)
      from (
        select extract(hour from accepted_local)::int as hh, count(*) as n,
               round(percentile_cont(0.5) within group (order by t)::numeric, 1) as med
        from medibles group by 1
      ) q
    ), '[]'::jsonb),
    'por_marca', coalesce((
      select jsonb_agg(jsonb_build_object('brand_id', brand_id, 'brand', brand_name, 'n', n, 'mediana_min', med) order by med desc)
      from (
        select m.brand_id, b.name as brand_name, count(*) as n,
               round(percentile_cont(0.5) within group (order by m.t)::numeric, 1) as med
        from medibles m left join brand b on b.id = m.brand_id
        group by m.brand_id, b.name
      ) q
    ), '[]'::jsonb),
    'tendencia_semanal', coalesce((
      select jsonb_agg(jsonb_build_object('semana', wk, 'n', n, 'mediana_min', med, 'pct_en_objetivo', pct_obj) order by wk)
      from (
        select date_trunc('week', accepted_local)::date as wk, count(*) as n,
               round(percentile_cont(0.5) within group (order by t)::numeric, 1) as med,
               round(100.0 * count(*) filter (where t <= v_cfg.amber_max_minutes) / count(*), 0) as pct_obj
        from medibles group by 1
      ) q
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


--
-- Name: kitchen_unarchive_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_unarchive_item(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item recipe_item%rowtype;
begin
  select * into v_item from recipe_item where id = p_item_id;
  if not found then
    raise exception 'kitchen_unarchive_item: item % no existe', p_item_id;
  end if;
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_item.account_id)) then
    raise exception 'kitchen_unarchive_item: sin acceso al item %', p_item_id;
  end if;

  update recipe_item
     set is_active = true, archived_at = null
   where id = p_item_id;

  return jsonb_build_object('action', 'unarchived', 'name', v_item.name);
end;
$$;


--
-- Name: lab_centros_del_lote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_centros_del_lote(p_lote uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lote public.lab_import_lote;
begin
  select * into v_lote from public.lab_import_lote where id = p_lote;
  if v_lote.id is null or not public.current_user_is_admin_of(v_lote.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El volcado lo hace el administrador de la cuenta.';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'centro', c.centro,
             'personas', c.personas,
             'propuesto', (select jsonb_build_object('id', l.id, 'nombre', l.name)
                             from public.locations l
                            where l.account_id = v_lote.account_id
                              and (public._lab_norm(l.name) like '%' || public._lab_norm(c.centro) || '%'
                                   or public._lab_norm(c.centro) like '%' || public._lab_norm(l.name) || '%')
                            order by abs(length(l.name) - length(c.centro)), l.name limit 1),
             'confirmado', (select jsonb_build_object('id', l.id, 'nombre', l.name)
                              from public.lab_centro_local cl join public.locations l on l.id = cl.location_id
                             where cl.account_id = v_lote.account_id and cl.centro = c.centro))
           order by c.centro)
      from (select public._lab_txt(f.datos, 'centro') centro,
                   count(distinct coalesce(public._lab_txt(f.datos, 'trabajador'), f.fila_n::text)) filter (where f.hoja = 'trabajadores') personas
              from public.lab_import_fila f
             where f.lote_id = p_lote and f.hoja in ('trabajadores', 'contratos') and public._lab_txt(f.datos, 'centro') is not null
             group by 1) c), '[]'::jsonb);
end $$;


--
-- Name: lab_confirmar_centro(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_confirmar_centro(p_lote uuid, p_centro text, p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lote public.lab_import_lote;
begin
  select * into v_lote from public.lab_import_lote where id = p_lote;
  if v_lote.id is null or not public.current_user_is_admin_of(v_lote.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El local de cada centro lo confirma el administrador de la cuenta.';
  end if;
  if not exists (select 1 from public.locations where id = p_location_id and account_id = v_lote.account_id) then
    raise exception 'LOCAL_DE_OTRA_CUENTA' using errcode = '22023', hint = 'El local tiene que ser de esta cuenta.';
  end if;
  if nullif(btrim(p_centro), '') is null then
    raise exception 'SIN_CENTRO' using errcode = '22023';
  end if;
  insert into public.lab_centro_local (account_id, centro, location_id, confirmado_por)
  values (v_lote.account_id, btrim(p_centro), p_location_id, auth.uid())
  on conflict (account_id, centro) do update
     set location_id = excluded.location_id, confirmado_por = excluded.confirmado_por, confirmado_at = now();
  return public.lab_centros_del_lote(p_lote);
end $$;


--
-- Name: lab_dar_permiso(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_dar_permiso(p_account_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.current_user_is_admin_of(p_account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El permiso de Laboral lo da el administrador de la cuenta.';
  end if;
  if not exists (select 1 from public.user_profiles where user_id = p_user_id and account_id = p_account_id and active) then
    raise exception 'NO_ES_DE_LA_CUENTA' using errcode = '22023', hint = 'Solo se da a alguien que entra en esta cuenta.';
  end if;
  insert into public.lab_permiso (account_id, user_id, dado_por) values (p_account_id, p_user_id, auth.uid())
  on conflict (account_id, user_id) do nothing;
  return jsonb_build_object('con_permiso', (select count(*) from public.lab_permiso where account_id = p_account_id));
end $$;


--
-- Name: lab_import_cargar_filas(uuid, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_import_cargar_filas(p_lote uuid, p_hoja text, p_desde integer, p_filas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lote public.lab_import_lote;
  v_n int;
  v_nuevas int;
begin
  select * into v_lote from public.lab_import_lote where id = p_lote;
  if v_lote.id is null or not public.current_user_is_admin_of(v_lote.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El historial de personal lo importa el administrador de la cuenta.';
  end if;
  if v_lote.estado <> 'leido' then
    raise exception 'LOTE_NO_LEIDO' using errcode = '22023', hint = 'Las filas se cargan en un lote recién leído.';
  end if;
  if p_hoja not in ('empresa', 'convenio', 'tablas_salariales', 'conceptos', 'trabajadores',
                    'contratos', 'nominas', 'nominas_conceptos', 'cuadre_contable') then
    raise exception 'HOJA_DESCONOCIDA' using errcode = '22023';
  end if;
  if p_desde is null or p_desde < 1 then
    raise exception 'FILA_INICIAL_MAL' using errcode = '22023';
  end if;
  if jsonb_typeof(p_filas) is distinct from 'array' or jsonb_array_length(p_filas) = 0 then
    raise exception 'SIN_FILAS' using errcode = '22023';
  end if;
  if jsonb_array_length(p_filas) > 1000 or pg_column_size(p_filas) > 2097152 then
    raise exception 'TROZO_DEMASIADO_GRANDE' using errcode = '22023', hint = 'Como mucho 1.000 filas o 2 MB por trozo.';
  end if;
  if exists (select 1 from jsonb_array_elements(p_filas) f where jsonb_typeof(f) <> 'object') then
    raise exception 'FILA_MAL_FORMADA' using errcode = '22023', hint = 'Cada fila va como sus columnas y sus valores.';
  end if;

  select count(*) into v_nuevas
    from jsonb_array_elements(p_filas) with ordinality f(datos, i)
   where not exists (select 1 from public.lab_import_fila x
                      where x.lote_id = p_lote and x.hoja = p_hoja and x.fila_n = p_desde + f.i::int - 1);

  insert into public.lab_import_fila (lote_id, account_id, hoja, fila_n, datos, huella)
  select p_lote, v_lote.account_id, p_hoja, p_desde + f.i::int - 1, f.datos, md5(f.datos::text)
    from jsonb_array_elements(p_filas) with ordinality f(datos, i)
  on conflict (lote_id, hoja, fila_n) do update
     set datos = excluded.datos, huella = excluded.huella,
         estado = 'ok', mensajes = '{}', destino_tabla = null, destino_id = null
   where public.lab_import_fila.huella is distinct from excluded.huella;
  get diagnostics v_n = row_count;

  return jsonb_build_object('hoja', p_hoja, 'recibidas', jsonb_array_length(p_filas),
                            'nuevas', v_nuevas, 'cambiadas', v_n - v_nuevas);
end $$;


--
-- Name: lab_import_leer_cabeceras(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_import_leer_cabeceras(p_account_id uuid, p_fichero_nombre text, p_fichero_huella text, p_hojas jsonb, p_comparacion jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_lote public.lab_import_lote;
  v_repetido boolean := false;
  v_h jsonb;
begin
  if p_account_id is null or not public.current_user_is_admin_of(p_account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El historial de personal lo importa el administrador de la cuenta.';
  end if;
  if coalesce(btrim(p_fichero_nombre), '') = '' or coalesce(p_fichero_huella, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'FICHERO_SIN_NOMBRE_O_HUELLA' using errcode = '22023';
  end if;
  if jsonb_typeof(p_hojas) is distinct from 'array' or jsonb_array_length(p_hojas) = 0 then
    raise exception 'SIN_HOJAS' using errcode = '22023', hint = 'El fichero no trae ninguna hoja.';
  end if;
  -- Solo cabeceras: nombre, columnas (textos) y filas (un número). Nada más.
  for v_h in select * from jsonb_array_elements(p_hojas) loop
    if jsonb_typeof(v_h) <> 'object'
       or (select count(*) from jsonb_object_keys(v_h) k where k not in ('nombre', 'columnas', 'filas')) > 0
       or jsonb_typeof(v_h -> 'nombre') <> 'string'
       or jsonb_typeof(v_h -> 'columnas') <> 'array'
       or jsonb_typeof(v_h -> 'filas') <> 'number'
       or exists (select 1 from jsonb_array_elements(v_h -> 'columnas') c where jsonb_typeof(c) <> 'string') then
      raise exception 'HOJA_MAL_FORMADA' using errcode = '22023', hint = 'Cada hoja lleva solo su nombre, sus cabeceras y cuántas filas tiene.';
    end if;
  end loop;
  if pg_column_size(p_hojas) + pg_column_size(coalesce(p_comparacion, '{}'::jsonb)) > 262144 then
    raise exception 'CABECERAS_DEMASIADO_GRANDES' using errcode = '22023';
  end if;

  select * into v_lote from public.lab_import_lote
   where account_id = p_account_id and fichero_huella = p_fichero_huella and estado not in ('deshecho', 'descartado');
  if v_lote.id is not null then
    v_repetido := true;
    update public.lab_import_lote
       set resumen = jsonb_build_object('hojas', p_hojas, 'comparacion', coalesce(p_comparacion, '{}'::jsonb)),
           fichero_nombre = btrim(p_fichero_nombre)
     where id = v_lote.id
    returning * into v_lote;
  else
    insert into public.lab_import_lote (account_id, origen, fichero_nombre, fichero_huella, resumen, subido_por)
    values (p_account_id, 'cegid', btrim(p_fichero_nombre), p_fichero_huella,
            jsonb_build_object('hojas', p_hojas, 'comparacion', coalesce(p_comparacion, '{}'::jsonb)), auth.uid())
    returning * into v_lote;
  end if;
  return jsonb_build_object('id', v_lote.id, 'repetido', v_repetido, 'subido_at', v_lote.subido_at, 'estado', v_lote.estado);
end $_$;


--
-- Name: lab_import_terminar_filas(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_import_terminar_filas(p_lote uuid, p_esperadas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lote public.lab_import_lote;
  v_quitadas int;
  v_hojas jsonb;
begin
  select * into v_lote from public.lab_import_lote where id = p_lote;
  if v_lote.id is null or not public.current_user_is_admin_of(v_lote.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El historial de personal lo importa el administrador de la cuenta.';
  end if;
  if v_lote.estado <> 'leido' then
    raise exception 'LOTE_NO_LEIDO' using errcode = '22023';
  end if;
  if jsonb_typeof(p_esperadas) is distinct from 'object'
     or exists (select 1 from jsonb_each(p_esperadas) e where jsonb_typeof(e.value) <> 'number') then
    raise exception 'ESPERADAS_MAL_FORMADAS' using errcode = '22023';
  end if;

  delete from public.lab_import_fila f
   where f.lote_id = p_lote
     and (not (p_esperadas ? f.hoja) or f.fila_n > (p_esperadas ->> f.hoja)::int);
  get diagnostics v_quitadas = row_count;

  select coalesce(jsonb_object_agg(h.hoja, jsonb_build_object('esperadas', h.esperadas, 'cargadas', h.cargadas)), '{}'::jsonb)
    into v_hojas
    from (select e.key hoja, (e.value)::text::int esperadas,
                 (select count(*) from public.lab_import_fila f where f.lote_id = p_lote and f.hoja = e.key)::int cargadas
            from jsonb_each(p_esperadas) e) h;

  return jsonb_build_object(
    'hojas', v_hojas,
    'quitadas', v_quitadas,
    'cargadas', (select count(*) from public.lab_import_fila where lote_id = p_lote),
    'completo', not exists (select 1 from jsonb_each(v_hojas) x where (x.value ->> 'esperadas') <> (x.value ->> 'cargadas')));
end $$;


--
-- Name: lab_quitar_permiso(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_quitar_permiso(p_account_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.current_user_is_admin_of(p_account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El permiso de Laboral lo quita el administrador de la cuenta.';
  end if;
  delete from public.lab_permiso where account_id = p_account_id and user_id = p_user_id;
  return jsonb_build_object('con_permiso', (select count(*) from public.lab_permiso where account_id = p_account_id));
end $$;


--
-- Name: lab_volcar_lote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lab_volcar_lote(p_lote uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lote      public.lab_import_lote;
  v_acc       uuid;
  v_ccc       text;
  v_conv_cod  text;
  v_hoy       date := (now() at time zone 'Europe/Madrid')::date;
  f           record;
  v_emp       uuid;
  v_loc       uuid;
  v_alta      boolean;
  v_nif       text;
  v_nombre    text;
  v_msg       text[];
  v_estado    text;
  v_contrato  uuid;
  v_desde     date;
  v_fin       date;
  v_coef      numeric;
  v_periodo   int;
  v_bruto     numeric;
  v_conv      numeric;
  v_pact      numeric;
  v_irpf      numeric;
  v_base      numeric;
  n_nuevas    int := 0;
  n_ya        int := 0;
  n_contratos int := 0;
  n_aviso     int := 0;
  n_error     int := 0;
  v_sin_centro text[] := '{}';
  v_no_cuadra jsonb := '[]';
begin
  select * into v_lote from public.lab_import_lote where id = p_lote;
  if v_lote.id is null or not public.current_user_is_admin_of(v_lote.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'El volcado lo hace el administrador de la cuenta.';
  end if;
  if v_lote.estado <> 'leido' then
    raise exception 'LOTE_NO_LEIDO' using errcode = '22023', hint = 'Se vuelca un lote leído y con sus filas cargadas.';
  end if;
  if not exists (select 1 from public.lab_import_fila where lote_id = p_lote and hoja = 'trabajadores') then
    raise exception 'SIN_FILAS' using errcode = '22023', hint = 'Primero «Cargar las filas en Sumied».';
  end if;
  v_acc := v_lote.account_id;
  v_ccc := public._lab_campo(p_lote, 'empresa', 'CCC');

  -- 1 · Convenio, tablas salariales y conceptos.
  if exists (select 1 from public.lab_import_fila where lote_id = p_lote and hoja = 'convenio') then
    insert into public.lab_convenio (account_id, codigo, nombre, codigo_oficial, horas_anuales, horas_dia, vacaciones, paga_13, paga_14, datos, lote_id, updated_at)
    select v_acc, coalesce(public._lab_campo(p_lote, 'convenio', 'código ERP10'), public._lab_campo(p_lote, 'empresa', 'convenio'), 'convenio'),
           public._lab_campo(p_lote, 'convenio', 'nombre'), public._lab_campo(p_lote, 'convenio', 'código oficial'),
           public._lab_num(public._lab_campo(p_lote, 'convenio', 'horas anuales')), public._lab_num(public._lab_campo(p_lote, 'convenio', 'horas día')),
           public._lab_campo(p_lote, 'convenio', 'vacaciones'), public._lab_campo(p_lote, 'convenio', 'paga 13'), public._lab_campo(p_lote, 'convenio', 'paga 14'),
           (select coalesce(jsonb_object_agg(datos ->> 'campo', datos -> 'valor'), '{}') from public.lab_import_fila where lote_id = p_lote and hoja = 'convenio' and datos ? 'valor'),
           p_lote, now()
    on conflict (account_id, codigo) do update
       set nombre = excluded.nombre, codigo_oficial = excluded.codigo_oficial, horas_anuales = excluded.horas_anuales,
           horas_dia = excluded.horas_dia, vacaciones = excluded.vacaciones, paga_13 = excluded.paga_13, paga_14 = excluded.paga_14,
           datos = excluded.datos, lote_id = excluded.lote_id, updated_at = now();
  end if;

  insert into public.lab_convenio_tabla (account_id, convenio_codigo, categoria, categoria_nombre, concepto_codigo, concepto_nombre, importe, modo_pago, lote_id)
  select distinct on (c, cat, con) v_acc, c, cat, public._lab_txt(datos, 'categoria_nombre'), con, public._lab_txt(datos, 'concepto_nombre'),
         public._lab_num(datos ->> 'importe'), public._lab_txt(datos, 'modo_pago'), p_lote
    from (select datos, public._lab_txt(datos, 'convenio') c, public._lab_txt(datos, 'categoria') cat, public._lab_txt(datos, 'concepto') con, fila_n
            from public.lab_import_fila where lote_id = p_lote and hoja = 'tablas_salariales') t
   where c is not null and cat is not null and con is not null
   order by c, cat, con, fila_n desc
  on conflict (account_id, convenio_codigo, categoria, concepto_codigo) do update
     set categoria_nombre = excluded.categoria_nombre, concepto_nombre = excluded.concepto_nombre, importe = excluded.importe,
         modo_pago = excluded.modo_pago, lote_id = excluded.lote_id;
  update public.lab_import_fila set estado = 'ok', mensajes = '{}', destino_tabla = 'lab_convenio_tabla'
   where lote_id = p_lote and hoja = 'tablas_salariales';

  insert into public.lab_concepto (account_id, codigo, nombre, tipo, codigo_red, lote_id)
  select distinct on (cod) v_acc, cod, public._lab_txt(datos, 'concepto'), public._lab_txt(datos, 'tipo'), public._lab_txt(datos, 'codigo_red'), p_lote
    from (select datos, public._lab_txt(datos, 'codigo') cod, fila_n from public.lab_import_fila where lote_id = p_lote and hoja = 'conceptos') t
   where cod is not null order by cod, fila_n desc
  on conflict (account_id, codigo) do update
     set nombre = excluded.nombre, tipo = excluded.tipo, codigo_red = excluded.codigo_red, lote_id = excluded.lote_id;
  update public.lab_import_fila set estado = 'ok', mensajes = '{}', destino_tabla = 'lab_concepto'
   where lote_id = p_lote and hoja = 'conceptos';

  -- 2 · Las personas (hoja Trabajadores).
  for f in select * from public.lab_import_fila where lote_id = p_lote and hoja = 'trabajadores' order by fila_n loop
    v_msg := '{}'; v_estado := 'ok'; v_emp := null;
    v_nif := public._lab_nif(f.datos ->> 'nif');
    v_nombre := coalesce(public._lab_txt(f.datos, 'nombre'), 'fila ' || f.fila_n);
    v_alta := public._lab_si(f.datos ->> 'en_alta_hoy');
    select cl.location_id into v_loc from public.lab_centro_local cl
     where cl.account_id = v_acc and cl.centro = public._lab_txt(f.datos, 'centro');

    if v_nif is null then
      v_estado := 'error'; v_msg := array[v_nombre || ': no trae NIF, y por el NIF se sabe quién es.'];
    elsif v_loc is null then
      v_estado := 'aviso';
      v_msg := array[v_nombre || ': su centro «' || coalesce(public._lab_txt(f.datos, 'centro'), 'sin centro') || '» no tiene local confirmado. Confírmalo arriba y vuelve a volcar.'];
      v_sin_centro := array_append(v_sin_centro, coalesce(public._lab_txt(f.datos, 'centro'), 'sin centro'));
    else
      select e.id into v_emp from public.employees e
       where e.account_id = v_acc and public._lab_nif(e.dni) = v_nif
       order by e.active desc, e.created_at limit 1;

      if v_emp is null and v_alta then
        v_estado := 'aviso';
        v_msg := array[v_nombre || ': en Cegid está de alta y no está en Folvy. No se crea sola: dala de alta desde Equipo y vuelve a volcar.'];
      elsif v_emp is null then
        -- Una baja que falta (respuesta 6): sin local primero (la formación de bienvenida no la encuentra), después su local.
        insert into public.employees (account_id, location_id, name, dni, birth_date, phone, email, position, active,
                                      start_date, contract_type, weekly_hours)
        values (v_acc, null, v_nombre, f.datos ->> 'nif', public._lab_fecha(f.datos ->> 'nacimiento'),
                coalesce(public._lab_txt(f.datos, 'movil'), public._lab_txt(f.datos, 'telefono')), public._lab_txt(f.datos, 'email'),
                public._lab_txt(f.datos, 'puesto'), false,
                coalesce(public._lab_fecha(f.datos ->> 'antiguedad'), public._lab_fecha(f.datos ->> 'primera_alta')), null, 40)
        returning id into v_emp;
        update public.employees set location_id = v_loc where id = v_emp;
        n_nuevas := n_nuevas + 1;
        v_msg := array[v_nombre || ': de baja en Cegid y no estaba en Folvy: entra como baja.'];
      else
        n_ya := n_ya + 1;
        -- De la que ya está, solo lo vacío; lo que no cuadra, como aviso.
        update public.employees e
           set dni = coalesce(nullif(e.dni, ''), f.datos ->> 'nif'),
               birth_date = coalesce(e.birth_date, public._lab_fecha(f.datos ->> 'nacimiento')),
               phone = coalesce(nullif(e.phone, ''), public._lab_txt(f.datos, 'movil'), public._lab_txt(f.datos, 'telefono')),
               email = coalesce(nullif(e.email, ''), public._lab_txt(f.datos, 'email')),
               position = coalesce(nullif(e.position, ''), public._lab_txt(f.datos, 'puesto'))
         where e.id = v_emp;
        if exists (select 1 from public.employees e where e.id = v_emp and e.active and not v_alta) then
          v_estado := 'aviso'; v_msg := v_msg || (v_nombre || ': en Cegid está de baja y en Folvy sigue de alta. No se cambia sola: revísalo en su ficha.');
        end if;
        if exists (select 1 from public.employees e where e.id = v_emp and e.location_id is distinct from v_loc
                     and not (v_loc = any (coalesce(e.assigned_locations, '{}')))) then
          v_estado := 'aviso'; v_msg := v_msg || (v_nombre || ': en Cegid su centro es otro local que el de Folvy.');
        end if;
      end if;

      if v_emp is not null then
        insert into public.lab_persona (employee_id, account_id, codigo_cegid, naf, iban, nacionalidad, sexo, nivel_formativo,
                                        domicilio, cp, poblacion, provincia, discapacidad, lote_id, fila_n, updated_at)
        values (v_emp, v_acc, public._lab_txt(f.datos, 'trabajador'), public._lab_txt(f.datos, 'naf'), public._lab_txt(f.datos, 'iban'),
                public._lab_txt(f.datos, 'nacionalidad'), public._lab_txt(f.datos, 'sexo'), public._lab_txt(f.datos, 'nivel_formativo'),
                public._lab_txt(f.datos, 'domicilio'), public._lab_txt(f.datos, 'cp'), public._lab_txt(f.datos, 'poblacion'),
                public._lab_txt(f.datos, 'provincia'), public._lab_txt(f.datos, 'minusvalia'), p_lote, f.fila_n, now())
        on conflict (employee_id) do update
           set codigo_cegid = excluded.codigo_cegid, naf = excluded.naf, iban = excluded.iban, nacionalidad = excluded.nacionalidad,
               sexo = excluded.sexo, nivel_formativo = excluded.nivel_formativo, domicilio = excluded.domicilio, cp = excluded.cp,
               poblacion = excluded.poblacion, provincia = excluded.provincia, discapacidad = excluded.discapacidad,
               lote_id = excluded.lote_id, fila_n = excluded.fila_n, updated_at = now();
      end if;
    end if;

    if v_estado = 'aviso' then n_aviso := n_aviso + 1; elsif v_estado = 'error' then n_error := n_error + 1; end if;
    update public.lab_import_fila
       set estado = v_estado, mensajes = v_msg, destino_tabla = case when v_emp is null then null else 'employees' end, destino_id = v_emp
     where id = f.id;
  end loop;

  -- 3 · Los contratos (hoja Contratos), de las personas que entraron.
  for f in select c.*, t.destino_id emp, public._lab_txt(t.datos, 'centro') centro_t
             from public.lab_import_fila c
             left join lateral (select x.destino_id, x.datos from public.lab_import_fila x
                                 where x.lote_id = p_lote and x.hoja = 'trabajadores' and x.destino_id is not null
                                   and public._lab_txt(x.datos, 'trabajador') = public._lab_txt(c.datos, 'trabajador') limit 1) t on true
            where c.lote_id = p_lote and c.hoja = 'contratos' order by c.fila_n loop
    v_msg := '{}'; v_estado := 'ok'; v_contrato := null;
    v_nombre := coalesce(public._lab_txt(f.datos, 'nombre'), 'trabajador ' || coalesce(public._lab_txt(f.datos, 'trabajador'), '?'));
    v_desde := public._lab_fecha(f.datos ->> 'fecha_alta');
    v_fin := public._lab_fecha(f.datos ->> 'fecha_fin');
    select cl.location_id into v_loc from public.lab_centro_local cl
     where cl.account_id = v_acc and cl.centro = coalesce(public._lab_txt(f.datos, 'centro'), f.centro_t);
    if f.emp is null then
      v_estado := 'aviso'; v_msg := array['Contrato ' || coalesce(public._lab_txt(f.datos, 'contrato_n'), '?') || ' de ' || v_nombre || ': su persona no ha entrado (mira su fila en Trabajadores).'];
    elsif v_desde is null then
      v_estado := 'error'; v_msg := array['Contrato ' || coalesce(public._lab_txt(f.datos, 'contrato_n'), '?') || ' de ' || v_nombre || ': no trae fecha de alta.'];
    else
      insert into public.lab_contrato (account_id, employee_id, numero, clave, descripcion, fecha_alta, fecha_fin_prevista, fecha_baja,
                                       origen, lote_id, fila_n, updated_at)
      values (v_acc, f.emp, coalesce(public._lab_txt(f.datos, 'contrato_n'), '1'), public._lab_txt(f.datos, 'tipo_contrato'),
              public._lab_txt(f.datos, 'tipo_contrato'), v_desde, v_fin, case when v_fin is not null and v_fin < v_hoy then v_fin end,
              'cegid', p_lote, f.fila_n, now())
      on conflict (account_id, employee_id, numero) do update
         set clave = excluded.clave, descripcion = excluded.descripcion, fecha_alta = excluded.fecha_alta,
             fecha_fin_prevista = excluded.fecha_fin_prevista, fecha_baja = coalesce(public.lab_contrato.fecha_baja, excluded.fecha_baja),
             lote_id = excluded.lote_id, fila_n = excluded.fila_n, updated_at = now()
      returning id into v_contrato;
      n_contratos := n_contratos + 1;

      v_coef := public._lab_num(f.datos ->> 'coef_parcial');
      insert into public.lab_contrato_condicion (account_id, contrato_id, vigente_desde, grupo_cotizacion, grupo_desc, puesto,
                                                 convenio_codigo, location_id, centro_cegid, cuenta_cotizacion, jornada, coef_parcial, lote_id, fila_n)
      values (v_acc, v_contrato, v_desde, public._lab_txt(f.datos, 'grupo_cotizacion'), public._lab_txt(f.datos, 'grupo_desc'),
              public._lab_txt(f.datos, 'puesto'), public._lab_txt(f.datos, 'convenio'), v_loc, coalesce(public._lab_txt(f.datos, 'centro'), f.centro_t),
              v_ccc, case when v_coef is null or v_coef in (0, 1, 100, 1000) then 'completa' else 'parcial' end, v_coef, p_lote, f.fila_n)
      on conflict (contrato_id, vigente_desde) do update
         set grupo_cotizacion = excluded.grupo_cotizacion, grupo_desc = excluded.grupo_desc, puesto = excluded.puesto,
             convenio_codigo = excluded.convenio_codigo, location_id = excluded.location_id, centro_cegid = excluded.centro_cegid,
             cuenta_cotizacion = coalesce(public.lab_contrato_condicion.cuenta_cotizacion, excluded.cuenta_cotizacion),
             jornada = excluded.jornada, coef_parcial = excluded.coef_parcial, lote_id = excluded.lote_id, fila_n = excluded.fila_n;
    end if;
    if v_estado = 'aviso' then n_aviso := n_aviso + 1; elsif v_estado = 'error' then n_error := n_error + 1; end if;
    update public.lab_import_fila
       set estado = v_estado, mensajes = v_msg, destino_tabla = case when v_contrato is null then null else 'lab_contrato' end, destino_id = v_contrato
     where id = f.id;
  end loop;

  -- La baja de una baja: su último contrato, cerrado. Si no trae fecha de fin, se dice.
  update public.lab_import_fila x set estado = 'aviso',
         mensajes = x.mensajes || (coalesce(public._lab_txt(x.datos, 'nombre'), 'Una baja') || ': de baja, pero su último contrato no trae fecha de fin. Ponla en su ficha.')
   where x.lote_id = p_lote and x.hoja = 'trabajadores' and x.destino_id is not null and not public._lab_si(x.datos ->> 'en_alta_hoy')
     and not exists (select 1 from public.lab_contrato c where c.employee_id = x.destino_id and c.fecha_baja is not null)
     and x.estado <> 'aviso';

  -- 4 · Lo que cobra cada una: convenio + pactado, y la última nómina de Cegid al lado.
  for f in select x.destino_id emp, x.datos from public.lab_import_fila x
            where x.lote_id = p_lote and x.hoja = 'trabajadores' and x.destino_id is not null loop
    select max(public._lab_num(n.datos ->> 'anio')::int * 100 + public._lab_num(n.datos ->> 'mes')::int) into v_periodo
      from public.lab_import_fila n
     where n.lote_id = p_lote and n.hoja = 'nominas' and public._lab_txt(n.datos, 'trabajador') = public._lab_txt(f.datos, 'trabajador');
    select c.id, coalesce(cc.convenio_codigo, public._lab_txt(f.datos, 'convenio')) into v_contrato, v_conv_cod
      from public.lab_contrato c left join public.lab_contrato_condicion cc on cc.contrato_id = c.id
     where c.employee_id = f.emp order by c.fecha_alta desc nulls last, cc.vigente_desde desc nulls last limit 1;
    v_desde := coalesce(make_date(v_periodo / 100, v_periodo % 100, 1),
                        (select max(c.fecha_alta) from public.lab_contrato c where c.employee_id = f.emp), v_hoy);

    delete from public.lab_persona_concepto where employee_id = f.emp and lote_id = p_lote;
    update public.lab_persona_concepto set vigente_hasta = v_desde - 1
     where employee_id = f.emp and vigente_hasta is null and vigente_desde < v_desde;

    -- Lo del convenio, por su convenio y su categoría.
    insert into public.lab_persona_concepto (account_id, employee_id, contrato_id, concepto_codigo, concepto_nombre, importe, periodicidad, origen, vigente_desde, lote_id)
    select v_acc, f.emp, v_contrato, t.concepto_codigo, t.concepto_nombre, t.importe,
           case when public._lab_norm(t.modo_pago) like '%paga%' then 'paga' else 'mes' end, 'convenio', v_desde, p_lote
      from public.lab_convenio_tabla t
     where t.account_id = v_acc and t.convenio_codigo = v_conv_cod and t.categoria = public._lab_txt(f.datos, 'categoria') and t.importe is not null;

    -- Lo pactado: los devengos de su última nómina que no son del convenio.
    if v_periodo is not null then
      insert into public.lab_persona_concepto (account_id, employee_id, contrato_id, concepto_codigo, concepto_nombre, importe, periodicidad, origen, vigente_desde, lote_id)
      select v_acc, f.emp, v_contrato, cod, max(nom), sum(imp), 'mes', 'pactado', v_desde, p_lote
        from (select coalesce(public._lab_txt(n.datos, 'concepto_codigo'), public._lab_txt(n.datos, 'concepto')) cod,
                     public._lab_txt(n.datos, 'concepto') nom, public._lab_num(n.datos ->> 'importe') imp,
                     coalesce(public._lab_txt(n.datos, 'tipo'), k.tipo) tipo
                from public.lab_import_fila n
                left join public.lab_concepto k on k.account_id = v_acc and k.codigo = public._lab_txt(n.datos, 'concepto_codigo')
               where n.lote_id = p_lote and n.hoja = 'nominas_conceptos'
                 and public._lab_txt(n.datos, 'trabajador') = public._lab_txt(f.datos, 'trabajador')
                 and public._lab_num(n.datos ->> 'anio')::int * 100 + public._lab_num(n.datos ->> 'mes')::int = v_periodo) n
       where cod is not null and imp is not null
         and public._lab_norm(tipo) !~ '(deduc|descuent|retenc|cotiz|aportac|irpf|seg soc)'
         and not exists (select 1 from public.lab_persona_concepto p
                          where p.employee_id = f.emp and p.lote_id = p_lote and p.origen = 'convenio' and p.concepto_codigo = n.cod)
       group by cod;
    end if;

    select sum(importe) filter (where origen = 'convenio' and periodicidad = 'mes'), sum(importe) filter (where origen = 'pactado')
      into v_conv, v_pact
      from public.lab_persona_concepto where employee_id = f.emp and lote_id = p_lote;
    select public._lab_num(n.datos ->> 'Devengado'), public._lab_num(n.datos ->> 'Retención'), public._lab_num(n.datos ->> 'Base I.R.P.F.')
      into v_bruto, v_irpf, v_base
      from public.lab_import_fila n
     where n.lote_id = p_lote and n.hoja = 'nominas' and v_periodo is not null
       and public._lab_txt(n.datos, 'trabajador') = public._lab_txt(f.datos, 'trabajador')
       and public._lab_num(n.datos ->> 'anio')::int * 100 + public._lab_num(n.datos ->> 'mes')::int = v_periodo
     order by n.fila_n limit 1;
    update public.lab_persona
       set bruto_cegid_mes = v_bruto,
           bruto_cegid_periodo = case when v_periodo is null then null else lpad((v_periodo % 100)::text, 2, '0') || '/' || (v_periodo / 100) end,
           bruto_conceptos_mes = coalesce(v_conv, 0) + coalesce(v_pact, 0),
           irpf_cegid_pct = case when v_base > 0 then round(v_irpf / v_base * 100, 2) end
     where employee_id = f.emp;
    if v_bruto is not null and abs(v_bruto - (coalesce(v_conv, 0) + coalesce(v_pact, 0))) >= 0.01 then
      v_no_cuadra := v_no_cuadra || jsonb_build_object('persona', public._lab_txt(f.datos, 'nombre'), 'cegid', v_bruto,
                                                       'conceptos', coalesce(v_conv, 0) + coalesce(v_pact, 0));
    end if;
  end loop;
  update public.lab_import_fila set estado = 'ok', mensajes = '{}', destino_tabla = 'lab_persona_concepto'
   where lote_id = p_lote and hoja in ('nominas', 'nominas_conceptos');

  update public.lab_import_lote
     set resumen = coalesce(resumen, '{}') || jsonb_build_object('volcado', jsonb_build_object('at', now(), 'por', auth.uid()))
   where id = p_lote;

  return jsonb_build_object(
    'personas', (select count(distinct destino_id) from public.lab_import_fila where lote_id = p_lote and hoja = 'trabajadores' and destino_id is not null),
    'nuevas_de_baja', n_nuevas,
    'ya_estaban', n_ya,
    'contratos', (select count(*) from public.lab_contrato where lote_id = p_lote),
    'trabajadores_en_cegid', (select count(*) from public.lab_import_fila where lote_id = p_lote and hoja = 'trabajadores'),
    'contratos_en_cegid', (select count(*) from public.lab_import_fila where lote_id = p_lote and hoja = 'contratos'),
    'avisos', n_aviso,
    'errores', n_error,
    'centros_sin_confirmar', (select coalesce(jsonb_agg(distinct c), '[]') from unnest(v_sin_centro) c),
    'no_cuadra', v_no_cuadra,
    'mensajes', (select coalesce(jsonb_agg(m order by hoja, fila_n), '[]')
                   from (select hoja, fila_n, unnest(mensajes) m from public.lab_import_fila
                          where lote_id = p_lote and estado in ('aviso', 'error')) x));
end $$;


--
-- Name: label_scan_register(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.label_scan_register(p_token text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_url text;
begin
  if p_token is null or length(p_token) not between 8 and 32 then
    return null;
  end if;

  update public.label_token t
     set scanned_at = coalesce(t.scanned_at, now()),
         scan_count = t.scan_count + 1
   where t.token = upper(p_token)
  returning (select b.shop_url from sale s join brand b on b.id = s.brand_id where s.id = t.sale_id)
    into v_url;

  return v_url;
exception when others then
  raise warning 'label_scan_register: token % (%): %', left(coalesce(p_token,''), 4), sqlstate, sqlerrm;
  return null;
end;
$$;


--
-- Name: label_token_bolsa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.label_token_bolsa(p_sale_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.token from public.label_token t
   where t.sale_id = p_sale_id and t.line_id is null and t.unit_no is null
   limit 1;
$$;


--
-- Name: label_tokens_for(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.label_tokens_for(p_line_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select array_agg(t.token order by t.unit_no)
    from public.label_token t
   where t.line_id = p_line_id;
$$;


--
-- Name: last_catalog_import_dispatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.last_catalog_import_dispatch() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secret text;
  v_row    record;
begin
  select decrypted_secret into v_secret
    from vault.decrypted_secrets where name = 'lastapp_internal_key';
  if v_secret is null then
    raise warning 'last_catalog_import_dispatch: secreto lastapp_internal_key ausente en Vault, no se dispara nada';
    return;
  end if;

  for v_row in
    select distinct ei.account_id, ei.external_org_id
      from public.external_integration ei
      join public.accounts a on a.id = ei.account_id
     where ei.source = 'lastapp'
       and ei.is_active = true
       and ei.ownership_type = 'licensed'
       and ei.external_org_id is not null
       and a.is_internal is not true
       and a.status = 'active'
       and a.suspended_at is null and a.archived_at is null and a.deleted_at is null
  loop
    perform net.http_post(
      url     := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/lastapp-catalog-import',
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-internal-key', v_secret),
      body    := jsonb_build_object(
                   'account_id', v_row.account_id,
                   'lastapp_organization_id', v_row.external_org_id),
      timeout_milliseconds := 120000
    );
  end loop;
end;
$$;


--
-- Name: last_catalog_sync_dispatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.last_catalog_sync_dispatch() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secret text;
  v_row    record;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'lastapp_internal_key';
  if v_secret is null then
    raise warning 'last_catalog_sync_dispatch: secreto lastapp_internal_key ausente en Vault, no se dispara nada';
    return;
  end if;

  for v_row in
    select distinct account_id, external_org_id
    from public.external_integration
    where source = 'lastapp' and is_active = true
  loop
    perform net.http_post(
      url     := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/last-catalog-sync',
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-internal-key', v_secret),
      body    := jsonb_build_object('account_id', v_row.account_id, 'external_org_id', v_row.external_org_id),
      timeout_milliseconds := 60000
    );
  end loop;
end;
$$;


--
-- Name: FUNCTION last_catalog_sync_dispatch(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.last_catalog_sync_dispatch() IS 'Dispara la Edge Function last-catalog-sync (net.http_post, fire-and-forget) para cada (account_id, external_org_id) activo en external_integration source=lastapp. Cron last-catalog-sync-hourly, horario de servicio 12-23 UTC.';


--
-- Name: last_catalog_watchdog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.last_catalog_watchdog() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  -- La cuenta plantilla del sistema. Comparte tablas Y nombres con producción
  -- (regla 9) y no la sirve nadie: no entra en los avisos.
  k_plantilla constant uuid := '00000000-0000-0000-0000-000000000001';
  -- «Reciente» es lo que hace que esto sea una señal y no una lista. Ver la
  -- cabecera: con 3 h, los 121 que llevan más de una semana tapan a los de hoy.
  k_reciente  constant interval := interval '24 hours';

  v_acc      record;
  v_list     text;
  v_n        int;
  v_recientes int;
  v_viejos   int;
  v_id       bigint;
  v_avisados int := 0;
  v_callados int := 0;
  v_cuentas  int := 0;
  v_parte    jsonb := '[]'::jsonb;
  v_de_esta  jsonb;
begin
  for v_acc in
    select ei.account_id, coalesce(max(a.name), ei.account_id::text) as cuenta
      from public.external_integration ei
      left join public.accounts a on a.id = ei.account_id
     where ei.source = 'lastapp' and ei.is_active = true
       and ei.account_id is not null
       and ei.account_id <> k_plantilla
     group by ei.account_id
     order by 2
  loop
    v_cuentas := v_cuentas + 1;
    v_de_esta := jsonb_build_object('cuenta', v_acc.cuenta, 'account_id', v_acc.account_id);

    -- ── 1 · EL ESPEJO RANCIO. Ésta ya iba por cuenta; ahora además sólo mira
    -- la suya. Es la que se pasó 52 días sin que nadie la viera (21/06→12/08).
    select string_agg(format('org %s - ultimo sync: %s', x.external_org_id,
                             coalesce(x.max_synced::text, 'nunca')),
                      chr(10) order by x.max_synced nulls first), count(*)
      into v_list, v_n
    from (
      select ei.external_org_id,
             (select max(ecp.last_synced_at) from public.external_catalog_product ecp
               where ecp.account_id = v_acc.account_id and ecp.source = 'lastapp'
                 and ecp.external_org_id = ei.external_org_id) as max_synced
        from public.external_integration ei
       where ei.source = 'lastapp' and ei.is_active = true
         and ei.account_id = v_acc.account_id
    ) x
    where x.max_synced is null or x.max_synced < now() - interval '3 hours';

    v_de_esta := v_de_esta || jsonb_build_object('espejo_rancio', coalesce(v_n, 0));
    if coalesce(v_n, 0) > 0 then
      v_id := public.encolar_alerta(
        p_kind    => 'last-catalog-sync',
        p_subject => format('%s: el espejo de Last lleva mas de 3 h sin refrescarse (%s org)',
                            v_acc.cuenta, v_n),
        p_message => format(
            'El espejo de disponibilidad de Last de %s no se refresca desde hace mas de 3 horas:%s%s%s%s'
         || 'Asi paso desapercibido 52 dias (21/06 a 12/08) la ultima vez. '
         || 'Revisar el cron last-catalog-sync-hourly y los registros de la funcion last-catalog-sync.',
            v_acc.cuenta, chr(10), chr(10), v_list, chr(10) || chr(10)),
        p_debounce_kind   => 'last-catalog-stale:' || v_acc.account_id,
        p_debounce_window => interval '3 hours',
        p_account_id      => v_acc.account_id,
        p_severity        => 'alto');
      if v_id is null then v_callados := v_callados + 1; else v_avisados := v_avisados + 1; end if;
    end if;

    -- ── 2 · PRODUCTOS AGOTADOS. Aqui estaba la fuga: sin `account_id`, sumaba
    -- las tres cuentas. Y aqui va el umbral que ORDENA: se avisa por los
    -- RECIENTES, y se dice cuantos viejos hay y cuantos son en total.
    select count(*) filter (where ecp.disabled_since > now() - k_reciente),
           count(*) filter (where ecp.disabled_since <= now() - k_reciente),
           count(*)
      into v_recientes, v_viejos, v_n
      from public.external_catalog_product ecp
     where ecp.account_id = v_acc.account_id
       and ecp.source = 'lastapp' and ecp.is_enabled = false and ecp.missing_since is null
       and ecp.disabled_since is not null and ecp.disabled_since < now() - interval '3 hours';

    v_de_esta := v_de_esta || jsonb_build_object(
      'agotados_total', coalesce(v_n, 0),
      'agotados_recientes', coalesce(v_recientes, 0),
      'agotados_de_mas_de_un_dia', coalesce(v_viejos, 0));

    if coalesce(v_recientes, 0) > 0 then
      select string_agg(format('%s (%s / %s) - agotado desde %s',
                               ecp.product_name,
                               coalesce(ecp.external_brand_name, '?'),
                               coalesce(ecp.external_channel, '?'),
                               ecp.disabled_since::text),
                        chr(10) order by ecp.disabled_since desc)
        into v_list
        from public.external_catalog_product ecp
       where ecp.account_id = v_acc.account_id
         and ecp.source = 'lastapp' and ecp.is_enabled = false and ecp.missing_since is null
         and ecp.disabled_since is not null
         and ecp.disabled_since < now() - interval '3 hours'
         and ecp.disabled_since > now() - k_reciente;

      v_id := public.encolar_alerta(
        p_kind    => 'last-catalog-sync',
        p_subject => format('%s: %s producto(s) agotados hoy en Last', v_acc.cuenta, v_recientes),
        p_message => format(
            'Agotados en las ultimas 24 horas en %s:%s%s%s%s'
         -- La cola del mensaje es la regla 7: lo que no se lista, SE CUENTA.
         -- Un aviso puede ordenar por lo urgente; lo que no puede es decir
         -- que son N cuando son mas.
         || 'Ademas hay %s que llevan agotados mas de un dia (en total, %s). '
         || 'Esos no se listan aqui para que no tapen a los de hoy: salen enteros en el parte del vigia.',
            v_acc.cuenta, chr(10), chr(10), left(v_list, 3000), chr(10) || chr(10),
            v_viejos, v_n),
        p_debounce_kind   => 'last-catalog-product-down:' || v_acc.account_id,
        p_debounce_window => interval '3 hours',
        p_account_id      => v_acc.account_id,
        p_severity        => 'aviso');
      if v_id is null then v_callados := v_callados + 1; else v_avisados := v_avisados + 1; end if;
    end if;

    -- ── 3 · MARCA ENTERA CAIDA. Sin `account_id` podia dar por caida una
    -- marca de otra cuenta. Se queda como estaba en criterio --3 o mas
    -- productos y TODOS apagados-- y cambia de alcance.
    select string_agg(format('%s (%s) org %s local %s - %s productos caidos',
                             y.external_brand_name, coalesce(y.external_channel, '?'),
                             y.external_org_id, y.external_location_id, y.n_down),
                      chr(10) order by y.n_down desc), count(*)
      into v_list, v_n
    from (
      select external_brand_name, external_channel, external_org_id, external_location_id,
             count(*) filter (where is_enabled = false) as n_down
        from public.external_catalog_product
       where account_id = v_acc.account_id
         and source = 'lastapp' and missing_since is null and external_brand_name is not null
       group by 1, 2, 3, 4
      having count(*) >= 3 and count(*) filter (where is_enabled = false) = count(*)
    ) y;

    v_de_esta := v_de_esta || jsonb_build_object('marcas_caidas', coalesce(v_n, 0));
    if coalesce(v_n, 0) > 0 then
      v_id := public.encolar_alerta(
        p_kind    => 'last-catalog-sync',
        p_subject => format('%s: %s marca(s) entera(s) caida(s) en Last', v_acc.cuenta, v_n),
        p_message => format(
            'Todos los productos de estas marcas/canal/local de %s estan apagados a la vez. '
         || 'Eso no es un agotado puntual: parece una caida de plataforma.%s%s%s',
            v_acc.cuenta, chr(10), chr(10), left(v_list, 3000)),
        p_debounce_kind   => 'last-catalog-brand-down:' || v_acc.account_id,
        p_debounce_window => interval '3 hours',
        p_account_id      => v_acc.account_id,
        p_severity        => 'critico');
      if v_id is null then v_callados := v_callados + 1; else v_avisados := v_avisados + 1; end if;
    end if;

    -- ── 4 · REFERENCIAS DESAPARECIDAS del catalogo, en las ultimas 3 h.
    select string_agg(format('%s (%s) - desaparecido %s', ecp.product_name,
                             coalesce(ecp.external_brand_name, '?'), ecp.missing_since::text),
                      chr(10) order by ecp.missing_since), count(*)
      into v_list, v_n
      from public.external_catalog_product ecp
     where ecp.account_id = v_acc.account_id
       and ecp.source = 'lastapp' and ecp.missing_since is not null
       and ecp.missing_since >= now() - interval '3 hours';

    v_de_esta := v_de_esta || jsonb_build_object('desaparecidos_3h', coalesce(v_n, 0));
    if coalesce(v_n, 0) > 0 then
      v_id := public.encolar_alerta(
        p_kind    => 'last-catalog-sync',
        p_subject => format('%s: %s referencia(s) han desaparecido del catalogo de Last',
                            v_acc.cuenta, v_n),
        p_message => format('Han dejado de venir en el catalogo de Last de %s:%s%s%s',
                            v_acc.cuenta, chr(10), chr(10), left(v_list, 3000)),
        p_debounce_kind   => 'last-catalog-missing:' || v_acc.account_id,
        p_debounce_window => interval '3 hours',
        p_account_id      => v_acc.account_id,
        p_severity        => 'aviso');
      if v_id is null then v_callados := v_callados + 1; else v_avisados := v_avisados + 1; end if;
    end if;

    v_parte := v_parte || jsonb_build_array(v_de_esta);
  end loop;

  -- EL PARTE. Antes esto devolvia `void`: una pasada que no encontraba nada y
  -- una que no llego a correr se leian igual (la familia de la regla 8).
  return jsonb_build_object(
    'ok', true,
    'cuentas_miradas', v_cuentas,
    'avisos_encolados', v_avisados,
    'avisos_callados_por_antirruido', v_callados,
    'plantilla_excluida', k_plantilla,
    'por_cuenta', v_parte);
end;
$$;


--
-- Name: FUNCTION last_catalog_watchdog(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.last_catalog_watchdog() IS 'Vigia del espejo de Last, CUENTA POR CUENTA (regla 9). Antes leia external_catalog_product sin account_id y mezclaba Foodint, la plantilla del sistema y el cliente 2 en un solo aviso: 789 productos medidos el 14/09. Avisa por la cola (encolar_alerta) con su account_id, y el aviso de agotados ordena por los de las ultimas 24 h diciendo cuantos viejos hay.';


--
-- Name: learn_from_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learn_from_receipt(p_receipt_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_receipt goods_receipt%ROWTYPE;
  v_line    goods_receipt_line%ROWTYPE;
  v_count   integer := 0;
  v_eur_base numeric;
  v_code    text;
BEGIN
  SELECT * INTO v_receipt FROM goods_receipt WHERE id = p_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'learn_from_receipt: albarán % no existe', p_receipt_id;
  END IF;
  IF NOT public.belongs_to_account(v_receipt.account_id) THEN
    RAISE EXCEPTION 'learn_from_receipt: sin acceso al albarán %', p_receipt_id;
  END IF;
  IF v_receipt.supplier_id IS NULL THEN RETURN 0; END IF;

  FOR v_line IN
    SELECT * FROM goods_receipt_line
    WHERE goods_receipt_id = p_receipt_id AND recipe_item_id IS NOT NULL
  LOOP
    v_eur_base := public._eur_base_from_format(v_line.purchase_format_id, v_line.unit_cost);
    v_code := NULLIF(btrim(coalesce(v_line.supplier_code, '')), '');

    IF v_code IS NOT NULL THEN
      INSERT INTO article_supplier (
        account_id, recipe_item_id, supplier_id,
        supplier_code, supplier_item_name, last_price, purchase_format_id,
        is_preferred, is_active, source
      )
      VALUES (
        v_receipt.account_id, v_line.recipe_item_id, v_receipt.supplier_id,
        v_code,
        NULLIF(btrim(coalesce(v_line.raw_text, v_line.product_name, '')), ''),
        v_eur_base, v_line.purchase_format_id,
        false, true, 'albaran'
      )
      ON CONFLICT (supplier_id, supplier_code, recipe_item_id) WHERE supplier_code IS NOT NULL
      DO UPDATE SET
        supplier_item_name = COALESCE(EXCLUDED.supplier_item_name, article_supplier.supplier_item_name),
        last_price         = COALESCE(EXCLUDED.last_price, article_supplier.last_price),
        purchase_format_id = COALESCE(EXCLUDED.purchase_format_id, article_supplier.purchase_format_id),
        is_active          = true,
        updated_at         = now();
    ELSE
      INSERT INTO article_supplier (
        account_id, recipe_item_id, supplier_id,
        supplier_code, supplier_item_name, last_price, purchase_format_id,
        is_preferred, is_active, source
      )
      VALUES (
        v_receipt.account_id, v_line.recipe_item_id, v_receipt.supplier_id,
        NULL,
        NULLIF(btrim(coalesce(v_line.raw_text, v_line.product_name, '')), ''),
        v_eur_base, v_line.purchase_format_id,
        false, true, 'albaran'
      )
      ON CONFLICT (recipe_item_id, supplier_id) WHERE supplier_code IS NULL
      DO UPDATE SET
        supplier_item_name = COALESCE(EXCLUDED.supplier_item_name, article_supplier.supplier_item_name),
        last_price         = COALESCE(EXCLUDED.last_price, article_supplier.last_price),
        purchase_format_id = COALESCE(EXCLUDED.purchase_format_id, article_supplier.purchase_format_id),
        is_active          = true,
        updated_at         = now();
    END IF;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: learn_supplier_alias(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learn_supplier_alias(p_receipt_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_receipt   goods_receipt%ROWTYPE;
  v_emitter   text;
  v_emit_nif  text;
  v_sup_name  text;
  v_emit_norm text;
BEGIN
  SELECT * INTO v_receipt FROM goods_receipt WHERE id = p_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'learn_supplier_alias: albarán % no existe', p_receipt_id;
  END IF;
  IF NOT public.belongs_to_account(v_receipt.account_id) THEN
    RAISE EXCEPTION 'learn_supplier_alias: sin acceso al albarán %', p_receipt_id;
  END IF;

  -- Sin proveedor elegido o sin sesión OCR → nada que aprender.
  IF v_receipt.supplier_id IS NULL OR v_receipt.ai_session_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT
    btrim(s.parsed_result->'document'->>'supplier_name'),
    btrim(s.parsed_result->'document'->>'supplier_tax_id')
  INTO v_emitter, v_emit_nif
  FROM goods_receipt_ai_session s
  WHERE s.id = v_receipt.ai_session_id;

  IF v_emitter IS NULL OR v_emitter = '' THEN
    RETURN false;
  END IF;

  -- Nombre del proveedor comercial elegido.
  SELECT name INTO v_sup_name FROM supplier WHERE id = v_receipt.supplier_id;

  -- Normalizadores coherentes con resolveReceiptHeader (lower, sin acentos, sin
  -- signos, espacios colapsados).
  v_emit_norm := regexp_replace(
                   regexp_replace(lower(unaccent(v_emitter)), '[^a-z0-9 ]', ' ', 'g'),
                   '\s+', ' ', 'g');
  v_emit_norm := btrim(v_emit_norm);

  -- Solo es "intermediario" si el emisor difiere del proveedor comercial elegido.
  IF v_sup_name IS NOT NULL
     AND btrim(regexp_replace(regexp_replace(lower(unaccent(v_sup_name)), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')) = v_emit_norm THEN
    RETURN false;   -- emisor == comercial → no hay intermediario que recordar
  END IF;

  INSERT INTO supplier_alias (account_id, emitter_norm, emitter_nif, supplier_id, delivered_by, created_by)
  VALUES (
    v_receipt.account_id,
    v_emit_norm,
    NULLIF(regexp_replace(upper(coalesce(v_emit_nif, '')), '[^A-Z0-9]', '', 'g'), ''),
    v_receipt.supplier_id,
    v_emitter,
    auth.uid()
  )
  ON CONFLICT (account_id, emitter_norm) DO UPDATE SET
    supplier_id = EXCLUDED.supplier_id,
    emitter_nif = COALESCE(EXCLUDED.emitter_nif, supplier_alias.emitter_nif),
    delivered_by = EXCLUDED.delivered_by,
    updated_at = now();

  RETURN true;
END;
$$;


--
-- Name: licensed_economics_dashboard(uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.licensed_economics_dashboard(p_account uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  with rows as (
    select cs.brand_id, b.name as brand, cs.channel_id, ch.name as channel, ch.slug as channel_slug,
           cs.location_id, l.name as location,
           coalesce(cs.gross_sales,0) as gross,
           coalesce(cs.net_payout,0)  as ingreso,
           coalesce(cs.commission,0)  as corte
    from public.channel_settlement cs
    left join public.brand b on b.id = cs.brand_id
    left join public.sales_channel ch on ch.id = cs.channel_id
    left join public.locations l on l.id = cs.location_id
    where cs.account_id = p_account
      and cs.flow_type = 'licensed'
      and cs.source = 'ctb_sales_detail'
      and (p_from is null or cs.period_to   >= p_from::date)
      and (p_to   is null or cs.period_from <  p_to::date)
      and (p_location is null or cs.location_id = p_location)
  ),
  by_brand as (
    select brand, brand_id,
      round(sum(gross),2) as gross, round(sum(ingreso),2) as ingreso,
      round(100.0*sum(ingreso)/nullif(sum(gross),0),1) as share_pct
    from rows where brand is not null group by brand, brand_id having sum(gross) > 0
  ),
  by_channel as (
    select channel, channel_slug, round(sum(gross),2) as gross, round(sum(ingreso),2) as ingreso
    from rows where channel is not null group by channel, channel_slug having sum(gross) > 0
  ),
  costs as (
    select s.location_id, l.name as location,
      round(sum(s.service_revenue),2) as rev,
      round(sum(s.food_cost),2) as food,
      round(sum(s.packaging_cost),2) as packaging,
      round(sum(s.food_cost+s.packaging_cost),2) as coste,
      round(sum(s.service_revenue-(s.food_cost+s.packaging_cost)),2) as contrib,
      round(sum(s.materials_supplied-s.stock_invoice_cost),2) as material_net,
      round(sum(s.net_settlement),2) as saldo
    from public.licensed_settlement s
    left join public.locations l on l.id = s.location_id
    where s.account_id = p_account
      and (p_from is null or s.period_to   >= p_from::date)
      and (p_to   is null or s.period_from <  p_to::date)
      and (p_location is null or s.location_id = p_location)
    group by s.location_id, l.name having sum(s.service_revenue) <> 0 or sum(s.food_cost) <> 0
  )
  select jsonb_build_object(
    'total', jsonb_build_object(
      'gross', (select round(sum(gross),2) from rows),
      'ingreso', (select round(sum(ingreso),2) from rows),
      'corte', (select round(sum(corte),2) from rows),
      'share_pct', (select round(100.0*sum(ingreso)/nullif(sum(gross),0),1) from rows),
      'marcas', (select count(*) from by_brand),
      'coste', (select round(sum(coste),2) from costs),
      'contrib', (select round(sum(contrib),2) from costs),
      'material_net', (select round(sum(material_net),2) from costs)
    ),
    'by_brand', coalesce((select jsonb_agg(jsonb_build_object(
        'brand', brand, 'gross', gross, 'ingreso', ingreso, 'share_pct', share_pct
      ) order by ingreso desc) from by_brand), '[]'::jsonb),
    'by_channel', coalesce((select jsonb_agg(jsonb_build_object(
        'channel', channel, 'slug', channel_slug, 'gross', gross, 'ingreso', ingreso
      ) order by ingreso desc) from by_channel), '[]'::jsonb),
    'by_location', coalesce((select jsonb_agg(jsonb_build_object(
        'location', location, 'ingreso', rev, 'coste', coste, 'food', food, 'packaging', packaging,
        'contrib', contrib, 'material_net', material_net, 'saldo', saldo
      ) order by rev desc) from costs), '[]'::jsonb)
  );
$$;


--
-- Name: list_campaigns(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_campaigns(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (p_account = any(current_user_account_ids())) then
    raise exception 'forbidden';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id',                 c.id,
             'name',               c.name,
             'code',               c.code,
             'kind',               c.kind,
             'discountType',       c.discount_type,
             'value',              c.value,
             'minSubtotal',        c.min_subtotal,
             'firstOrderOnly',     c.first_order_only,
             'autoApply',          c.auto_apply,
             'frequencyThreshold', c.frequency_threshold,
             'startsAt',           c.starts_at,
             'endsAt',             c.ends_at,
             'maxRedemptions',     c.max_redemptions,
             'maxPerCustomer',     c.max_per_customer,
             'active',             c.active,
             'pausedAt',           c.paused_at,
             'origin',             c.origin,
             'budgetMax',          c.budget_max,
             'weekdays',           c.weekdays,
             'timeFrom',           c.time_from,
             'timeTo',             c.time_to,
             'channels',           c.channels,
             'status', case
               when c.paused_at is not null then 'paused'
               when not c.active then 'paused'
               when c.ends_at is not null and c.ends_at <= now() then 'expired'
               when c.budget_max is not null and coalesce(p.sum_disc, 0) >= c.budget_max then 'exhausted'
               when c.starts_at is not null and c.starts_at > now() then 'scheduled'
               else 'active' end,
             -- Sistema = bienvenida (standard auto/first) o frecuencia. item_percent y
             -- free_delivery son campañas EDITABLES aquí (aunque free_delivery sea auto).
             'isSystem', (c.kind = 'frequency' or (c.kind = 'standard' and (c.auto_apply or c.first_order_only))),
             'redemptions',  coalesce(p.n, 0),
             'discounted',   coalesce(p.sum_disc, 0),
             'avgMarginPct', p.avg_margin_pct,
             'roi', case when p.margin_total is not null and coalesce(p.sum_disc, 0) > 0
                         then round(p.margin_total / p.sum_disc, 2) else null end
           )
           order by (c.kind = 'frequency' or (c.kind = 'standard' and (c.auto_apply or c.first_order_only))) desc, c.created_at desc)
    from coupon c
    cross join lateral (
      select count(*) as n,
             sum(cr.discount_amount) as sum_disc,
             sum(cr.margin_after) filter (where cr.margin_after is not null) as margin_total,
             round(avg(cr.margin_after / nullif(cr.reference_subtotal - cr.discount_amount, 0))
                     filter (where cr.margin_after is not null) * 100, 1) as avg_margin_pct
      from coupon_redemption cr
      join sale s on s.id = cr.sale_id
      where cr.coupon_id = c.id and coalesce(s.status,'') <> 'cancelled'
    ) p
    where c.account_id = p_account
  ), '[]'::jsonb);
end;
$$;


--
-- Name: list_delivery_zones(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_delivery_zones(p_location_id uuid) RETURNS TABLE(id uuid, name text, method text, delivery_fee numeric, min_order numeric, eta_min integer, radius_m integer, priority integer, is_active boolean, center_lat double precision, center_lng double precision, area_geojson jsonb, postal_codes text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select z.id, z.name, z.method, z.delivery_fee, z.min_order, z.eta_min,
         z.radius_m, z.priority, z.is_active,
         ST_Y(z.center::geometry), ST_X(z.center::geometry),
         case when z.area is not null then ST_AsGeoJSON(z.area)::jsonb else null end,
         z.postal_codes
  from public.delivery_zone z
  join public.locations l on l.id = z.location_id
  where z.location_id = p_location_id
    and l.account_id = any (public.current_user_account_ids())
  order by z.delivery_fee asc, z.priority desc;
$$;


--
-- Name: list_item_stock_movements(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_item_stock_movements(p_account uuid, p_item uuid, p_location uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_res jsonb;
BEGIN
  IF NOT (current_user_is_admin() OR current_user_is_admin_or_manager_of(p_account)) THEN
    RAISE EXCEPTION 'list_item_stock_movements: sin acceso a la cuenta %', p_account;
  END IF;

  WITH todos AS (
    SELECT sm.id, sm.movement_type, sm.source_type, sm.source_id,
           sm.qty_base, sm.unit_cost, sm.occurred_at, sm.created_by_name, sm.notes,
           sum(sm.qty_base) OVER (ORDER BY sm.occurred_at, sm.id
                                  ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_qty,
           sum(sm.qty_base * coalesce(sm.unit_cost, 0)) OVER (ORDER BY sm.occurred_at, sm.id
                                  ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cost
    FROM stock_movement sm
    WHERE sm.account_id = p_account
      AND sm.recipe_item_id = p_item
      AND sm.location_id = p_location
  ),
  ventana AS (
    SELECT * FROM todos
    WHERE (p_from IS NULL OR occurred_at >= p_from)
      AND (p_to IS NULL OR occurred_at < p_to)
  ),
  fam AS (
    SELECT v.*,
      CASE v.movement_type
        WHEN 'recepcion' THEN 'compras'
        WHEN 'consumo' THEN 'ventas'
        WHEN 'merma' THEN 'otros'
        WHEN 'traspaso_entrada' THEN 'otros'
        WHEN 'traspaso_salida' THEN 'otros'
        WHEN 'ajuste' THEN 'inventarios'
        WHEN 'recuento' THEN 'inventarios'
        WHEN 'apertura' THEN 'inventarios'
        ELSE 'otros'
      END AS familia
    FROM ventana v
  ),
  pagina AS (
    SELECT * FROM fam
    ORDER BY occurred_at DESC
    LIMIT greatest(p_limit, 0) OFFSET greatest(p_offset, 0)
  ),
  resolved AS (
    SELECT f.*,
      CASE f.source_type
        WHEN 'sale' THEN coalesce(
          (SELECT s.id FROM sale s WHERE s.id = f.source_id),
          (SELECT sl.sale_id FROM sale_line sl WHERE sl.id = f.source_id))
        ELSE null
      END AS sale_id,
      CASE f.source_type
        WHEN 'sale' THEN (
          SELECT trim(both ' ·' FROM
            coalesce(b.name, sc.name, initcap(s.external_channel_text), 'Venta')
            || coalesce(' · ' || nullif(s.platform_order_code, ''), ''))
          FROM sale s
          LEFT JOIN sales_channel sc ON sc.id = s.channel_id
          LEFT JOIN brand b ON b.id = s.brand_id
          WHERE s.id = coalesce(
            (SELECT s2.id FROM sale s2 WHERE s2.id = f.source_id),
            (SELECT sl.sale_id FROM sale_line sl WHERE sl.id = f.source_id)))
        WHEN 'goods_receipt_line' THEN (
          SELECT coalesce(gr.code, 'Recepción')
            || coalesce(' · ' || nullif(gr.supplier_doc_number, ''), '')
          FROM goods_receipt_line grl
          JOIN goods_receipt gr ON gr.id = grl.goods_receipt_id
          WHERE grl.id = f.source_id)
        WHEN 'adjustment' THEN (
          SELECT 'Ajuste · ' || sa.reason_code FROM stock_adjustment sa WHERE sa.id = f.source_id)
        WHEN 'waste' THEN (
          SELECT 'Merma · ' || sw.reason_code FROM stock_waste sw WHERE sw.id = f.source_id)
        WHEN 'transfer' THEN (
          SELECT CASE WHEN st.from_location_id = p_location
                      THEN '→ ' || coalesce(lt.name, 'otro local')
                      ELSE '← ' || coalesce(lf.name, 'otro local') END
          FROM stock_transfer st
          LEFT JOIN locations lf ON lf.id = st.from_location_id
          LEFT JOIN locations lt ON lt.id = st.to_location_id
          WHERE st.id = f.source_id)
        ELSE null
      END AS reference
    FROM pagina f
  )
  SELECT jsonb_build_object(
    'item', (
      SELECT jsonb_build_object(
        'id', ri.id, 'name', ri.name,
        'unit_abbr', ku.abbreviation,
        'qty_on_hand', coalesce(st.qty_on_hand, 0),
        'avg_unit_cost', st.avg_unit_cost,
        'stock_value', coalesce(st.stock_value, 0))
      FROM recipe_item ri
      LEFT JOIN kitchen_unit ku ON ku.id = ri.base_unit_id
      LEFT JOIN recipe_item_location_stock st
        ON st.recipe_item_id = ri.id AND st.location_id = p_location
      WHERE ri.id = p_item),
    'total', (SELECT count(*) FROM ventana),
    'series', coalesce((
      SELECT jsonb_agg(x ORDER BY x->>'dia')
      FROM (
        SELECT jsonb_build_object('dia', occurred_at::date, 'familia', familia,
                                  'qty', round(sum(qty_base), 3)) AS x
        FROM fam GROUP BY occurred_at::date, familia) t
    ), '[]'::jsonb),
    'items', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', r.id,
               'movement_type', r.movement_type,
               'source_type', r.source_type,
               'sale_id', r.sale_id,
               'qty_base', r.qty_base,
               'unit_cost', r.unit_cost,
               'cost_eur', round(abs(r.qty_base) * coalesce(r.unit_cost, 0), 2),
               'running_qty', round(r.running_qty, 3),
               'running_cost', round(r.running_cost, 2),
               'occurred_at', r.occurred_at,
               'created_by_name', r.created_by_name,
               'reference', r.reference,
               'notes', r.notes
             ) ORDER BY r.occurred_at DESC)
      FROM resolved r
    ), '[]'::jsonb)
  ) INTO v_res;

  RETURN v_res;
END;
$$;


--
-- Name: list_pending_external_brands(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pending_external_brands(p_account_id uuid) RETURNS TABLE(source text, external_location_id text, external_brand_id text, folvy_location_id uuid, folvy_location_name text, ventas bigint, pista_catalogo text, pista_productos text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH lineas AS (
    SELECT
      'lastapp'::text                              AS source,
      l.payload->'data'->>'locationId'             AS ext_loc,
      l.payload->'data'->>'locationBrandId'        AS ext_brand,
      l.id                                         AS log_id,
      p->>'name'                                   AS producto,
      nullif(p->>'catalogProductId','')::uuid      AS cat_prod
    FROM lastapp_webhook_log l
    CROSS JOIN LATERAL jsonb_array_elements(l.payload->'data'->'products') p
    WHERE l.payload->'data'->>'locationBrandId' IS NOT NULL
  ),
  marca_nombre AS (
    -- nombre real de marca: el primer catalogProductId de ese id que resuelve a un nombre
    SELECT DISTINCT ON (ln.source, ln.ext_loc, ln.ext_brand)
      ln.source, ln.ext_loc, ln.ext_brand,
      cp.external_brand_name AS nombre_catalogo
    FROM lineas ln
    JOIN external_catalog_product cp
      ON cp.account_id = p_account_id
     AND cp.catalog_product_id = ln.cat_prod
     AND cp.external_brand_name IS NOT NULL
    ORDER BY ln.source, ln.ext_loc, ln.ext_brand
  ),
  marca_productos AS (
    SELECT source, ext_loc, ext_brand,
           string_agg(producto, ' · ' ORDER BY n DESC) AS pista_productos
    FROM (
      SELECT source, ext_loc, ext_brand, producto, count(*) AS n,
             row_number() OVER (PARTITION BY source, ext_loc, ext_brand ORDER BY count(*) DESC) AS rn
      FROM lineas
      WHERE producto IS NOT NULL
      GROUP BY source, ext_loc, ext_brand, producto
    ) t
    WHERE rn <= 4
    GROUP BY source, ext_loc, ext_brand
  ),
  agg AS (
    SELECT source, ext_loc, ext_brand, count(DISTINCT log_id) AS ventas
    FROM lineas
    GROUP BY source, ext_loc, ext_brand
  )
  SELECT
    a.source,
    a.ext_loc                                AS external_location_id,
    a.ext_brand                              AS external_brand_id,
    lm.location_id                           AS folvy_location_id,
    loc.name                                 AS folvy_location_name,
    a.ventas,
    mn.nombre_catalogo                       AS pista_catalogo,
    mp.pista_productos
  FROM agg a
  LEFT JOIN marca_nombre   mn USING (source, ext_loc, ext_brand)
  LEFT JOIN marca_productos mp USING (source, ext_loc, ext_brand)
  -- Local: CONVERGIDO a external_location_map (antes lastapp_location_map). Ambos
  -- external_location_id son text -> comparación directa, sin ::text.
  LEFT JOIN external_location_map lm
    ON lm.account_id = p_account_id
   AND lm.source = 'lastapp'
   AND lm.external_location_id = a.ext_loc
  LEFT JOIN locations loc
    ON loc.id = lm.location_id
  WHERE NOT EXISTS (
    SELECT 1 FROM external_brand_map m
    WHERE m.account_id = p_account_id
      AND m.source = a.source
      AND m.external_location_id = a.ext_loc
      AND m.external_brand_id = a.ext_brand
  )
  ORDER BY loc.name NULLS LAST, a.ventas DESC;
$$;


--
-- Name: list_platform_admins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_platform_admins() RETURNS TABLE(id uuid, user_id uuid, full_name text, email text, role text, active boolean, last_login_at timestamp with time zone, created_at timestamp with time zone, can_create_accounts boolean, can_suspend_accounts boolean, can_archive_accounts boolean, can_delete_accounts boolean, can_edit_seed_data boolean, can_impersonate boolean, can_manage_admins boolean, can_reset_2fa_of_others boolean, can_send_global_notifications boolean, can_view_audit_log boolean, can_view_system_health boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM _require_manage_admins();
  RETURN QUERY
  SELECT
    pa.id, pa.user_id, pa.full_name::text, au.email::text, pa.role::text,
    pa.active, pa.last_login_at, pa.created_at,
    COALESCE(p.platform_can_create_accounts, false),
    COALESCE(p.platform_can_suspend_accounts, false),
    COALESCE(p.platform_can_archive_accounts, false),
    COALESCE(p.platform_can_delete_accounts, false),
    COALESCE(p.platform_can_edit_seed_data, false),
    COALESCE(p.platform_can_impersonate, false),
    COALESCE(p.platform_can_manage_admins, false),
    COALESCE(p.platform_can_reset_2fa_of_others, false),
    COALESCE(p.platform_can_send_global_notifications, false),
    COALESCE(p.platform_can_view_audit_log, false),
    COALESCE(p.platform_can_view_system_health, false)
  FROM platform_admins pa
  LEFT JOIN auth.users au ON au.id = pa.user_id
  LEFT JOIN platform_admin_permissions p ON p.platform_admin_id = pa.id
  ORDER BY pa.active DESC, pa.created_at ASC;
END;
$$;


--
-- Name: list_platform_events(uuid, uuid, text, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_platform_events(p_account_id uuid DEFAULT NULL::uuid, p_admin_id uuid DEFAULT NULL::uuid, p_event_type text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, created_at timestamp with time zone, event_type text, admin_id uuid, admin_name text, admin_email text, target_account_id uuid, account_name text, target_user_id uuid, details jsonb, ip_address text, user_agent text, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Solo platform admins activos pueden leer la auditoría.
  IF NOT EXISTS (
    SELECT 1 FROM platform_admins pa
    WHERE pa.user_id = auth.uid() AND pa.active = true
  ) THEN
    RAISE EXCEPTION 'Acceso denegado: solo platform admins pueden leer la auditoría';
  END IF;

  RETURN QUERY
  SELECT
    l.id,
    l.created_at,
    l.event_type::text,
    l.platform_admin_id                              AS admin_id,
    pa.full_name::text                               AS admin_name,
    au.email::text                                   AS admin_email,
    l.target_account_id,
    acc.name::text                                   AS account_name,
    l.target_user_id,
    l.details,
    host(l.ip_address)::text                          AS ip_address,
    l.user_agent::text,
    count(*) OVER ()                                 AS total_count
  FROM platform_audit_log l
  LEFT JOIN platform_admins pa ON pa.id = l.platform_admin_id
  LEFT JOIN auth.users      au ON au.id = pa.user_id
  LEFT JOIN accounts        acc ON acc.id = l.target_account_id
  WHERE (p_account_id IS NULL OR l.target_account_id = p_account_id)
    AND (p_admin_id   IS NULL OR l.platform_admin_id = p_admin_id)
    AND (p_event_type IS NULL OR l.event_type = p_event_type)
    AND (p_from       IS NULL OR l.created_at >= p_from)
    AND (p_to         IS NULL OR l.created_at <= p_to)
  ORDER BY l.created_at DESC
  LIMIT  greatest(1, least(coalesce(p_limit, 100), 500))
  OFFSET greatest(0, coalesce(p_offset, 0));
END;
$$;


--
-- Name: list_pricing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pricing() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF NOT current_user_is_admin() THEN
    RAISE EXCEPTION 'Acceso denegado: solo platform admins.';
  END IF;

  v := jsonb_build_object(
    'plans', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id, 'code', code, 'name', name,
        'base_price_eur', base_price_eur,
        'per_location_price', per_location_price,
        'max_locations', max_locations,
        'billing_cycle', billing_cycle
      ) ORDER BY sort_order), '[]'::jsonb)
      FROM billing_plans),
    'addons', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', sm.id, 'code', sm.code, 'name', sm.name,
        'module', m.name, 'price_eur', sm.price_eur
      ) ORDER BY m.sort_order, sm.sort_order), '[]'::jsonb)
      FROM submodules sm
      JOIN modules m ON m.id = sm.module_id
      WHERE sm.type = 'addon' AND sm.status = 'active')
  );
  RETURN v;
END;
$$;


--
-- Name: list_printers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_printers(p_location_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', id, 'name', name, 'transport', transport,
           'ip', config->>'ip', 'port', coalesce((config->>'port')::int, 9100),
           'doc_types', to_jsonb(doc_types), 'copies', copies, 'is_active', is_active
         ) order by name), '[]'::jsonb)
  from printer where location_id = p_location_id and public.belongs_to_account(account_id);
$$;


--
-- Name: list_printers_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_printers_by_token(p_device_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_device kds_device;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'list_printers_by_token: token no válido'; end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', id, 'name', name, 'transport', transport,
             'ip', config->>'ip', 'port', coalesce((config->>'port')::int, 9100),
             'doc_types', to_jsonb(doc_types), 'copies', copies, 'is_active', is_active
           ) order by name), '[]'::jsonb)
    from printer where location_id = v_device.location_id and account_id = v_device.account_id
  );
end;
$$;


--
-- Name: list_stock_movements(uuid, uuid, text[], timestamp with time zone, timestamp with time zone, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_stock_movements(p_account uuid, p_location uuid, p_types text[] DEFAULT NULL::text[], p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
with q as (
  select nullif(
           replace(replace(replace(unaccent(lower(btrim(coalesce(p_search, '')))),
             '\', '\\'), '%', '\%'), '_', '\_'),
           '') as term
),
-- MATERIALIZED: se calcula UNA vez. Sin esto Postgres lo recalcula en cada uso.
filtrado as materialized (
  select sm.id, sm.movement_type, sm.source_type, sm.source_id,
         sm.qty_base, sm.unit_cost, sm.occurred_at, sm.created_by_name, sm.notes,
         ri.name as item_name,
         ku.abbreviation as unit_abbr
  from stock_movement sm
  join recipe_item ri on ri.id = sm.recipe_item_id
  left join kitchen_unit ku on ku.id = ri.base_unit_id
  cross join q
  where sm.account_id = p_account
    and sm.location_id = p_location
    and (p_types is null or sm.movement_type = any(p_types))
    and (p_from is null or sm.occurred_at >= p_from)
    and (p_to is null or sm.occurred_at < p_to)
    and (q.term is null
         or unaccent(lower(ri.name)) like '%' || q.term || '%' escape '\')
),
agregados as (
  select count(*)                                                          as total,
         coalesce(round(sum(qty_base) filter (where qty_base > 0), 3), 0)  as sum_in,
         coalesce(round(sum(-qty_base) filter (where qty_base < 0), 3), 0) as sum_out,
         coalesce(jsonb_agg(distinct coalesce(unit_abbr, '')), '[]'::jsonb) as units
  from filtrado
),
pagina as (
  select * from filtrado
  order by occurred_at desc
  limit greatest(p_limit, 0) offset greatest(p_offset, 0)
),
resolved as (
  select f.*,
    case f.source_type
      when 'sale' then coalesce(
        (select s.id from sale s where s.id = f.source_id),
        (select sl.sale_id from sale_line sl where sl.id = f.source_id)
      )
      else null
    end as sale_id,
    case f.source_type
      when 'sale' then (
        select trim(both ' ·' from
          coalesce(sc.name, initcap(s.external_channel_text), 'Venta')
          || coalesce(' · ' || nullif((case when left(btrim(s.raw_tab),1) = '{' then s.raw_tab::jsonb->>'code' else null end), ''), ''))
        from sale s
        left join sales_channel sc on sc.id = s.channel_id
        where s.id = coalesce(
          (select s2.id from sale s2 where s2.id = f.source_id),
          (select sl.sale_id from sale_line sl where sl.id = f.source_id)
        )
      )
      when 'goods_receipt_line' then (
        select coalesce(gr.code, 'Recepción')
          || coalesce(' · ' || nullif(gr.supplier_doc_number, ''), '')
        from goods_receipt_line grl
        join goods_receipt gr on gr.id = grl.goods_receipt_id
        where grl.id = f.source_id
      )
      when 'adjustment' then (
        select 'Ajuste · ' || sa.reason_code from stock_adjustment sa where sa.id = f.source_id
      )
      when 'waste' then (
        select 'Merma · ' || sw.reason_code from stock_waste sw where sw.id = f.source_id
      )
      when 'transfer' then (
        select case
          when st.from_location_id = p_location then '→ ' || coalesce(lt.name, 'otro local')
          else '← ' || coalesce(lf.name, 'otro local')
        end
        from stock_transfer st
        left join locations lf on lf.id = st.from_location_id
        left join locations lt on lt.id = st.to_location_id
        where st.id = f.source_id
      )
      else null
    end as reference
  from pagina f
)
select jsonb_build_object(
  'total',       (select total from agregados),
  'total_all',   (select total from agregados),
  'sum_in',      (select sum_in from agregados),
  'sum_out',     (select sum_out from agregados),
  'units',       (select units from agregados),
  'items', coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', r.id,
             'movement_type', r.movement_type,
             'source_type', r.source_type,
             'sale_id', r.sale_id,
             'item_name', r.item_name,
             'unit_abbr', r.unit_abbr,
             'qty_base', r.qty_base,
             'unit_cost', r.unit_cost,
             'cost_eur', round(abs(r.qty_base) * coalesce(r.unit_cost, 0), 2),
             'occurred_at', r.occurred_at,
             'created_by_name', r.created_by_name,
             'reference', r.reference,
             'notes', r.notes
           ) order by r.occurred_at desc)
    from resolved r
  ), '[]'::jsonb)
);
$$;


--
-- Name: FUNCTION list_stock_movements(p_account uuid, p_location uuid, p_types text[], p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer, p_search text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_stock_movements(p_account uuid, p_location uuid, p_types text[], p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer, p_search text) IS 'Libro mayor del almacén. p_search filtra por nombre de artículo EN SERVIDOR (sin acentos), antes de contar y de paginar. total = resultados de la búsqueda; total_all = del filtro sin búsqueda.';


--
-- Name: load_sales_history_batch(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_sales_history_batch(p_batch text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n integer;
begin
  with parsed as (
    select string_to_array(rec, '|') a
    from unnest(string_to_array(p_batch, ';')) rec
    where length(trim(rec)) > 0
  ),
  mapped as (
    select case a[1]
             when 'A' then '38158159-cd71-4056-950b-53425afac1ce'::uuid
             when 'C' then '92d7656e-082e-452a-8ebc-236b2d6ebf5f'::uuid
             when 'P' then '629f9154-b888-48ed-9b8c-ffae77620615'::uuid
           end loc,
           a[2]::date d, a[3]::int o, a[4]::numeric pl, a[5]::numeric be, a[6]::numeric po
    from parsed
  )
  insert into public.sales_history_daily
    (account_id, location_id, day, scope, orders, dishes, drinks, desserts, source)
  select '51ad1792-6629-4ef7-833a-b57b09a86710'::uuid, loc, d, 'licensed', o, pl, be, po,
         'lastapp_tabs_export'
  from mapped where loc is not null
  on conflict (account_id, location_id, day, scope, source) do update
    set orders = excluded.orders, dishes = excluded.dishes,
        drinks = excluded.drinks, desserts = excluded.desserts;

  get diagnostics v_n = row_count;
  return v_n;
end $$;


--
-- Name: location_company_misma_cuenta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_company_misma_cuenta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_loc uuid; v_emp uuid;
begin
  select l.account_id into v_loc from public.locations l where l.id = new.location_id;
  select c.account_id into v_emp from public.company c where c.id = new.company_id;
  if v_loc is distinct from new.account_id or v_emp is distinct from new.account_id then
    raise exception 'El local y la empresa tienen que ser de la misma cuenta (local %, empresa %, fila %).', v_loc, v_emp, new.account_id
      using errcode = 'check_violation';
  end if;
  new.updated_at := now();
  return new;
end
$$;


--
-- Name: location_demand_pct(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_demand_pct(p_location_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_max numeric; v_acc uuid; v_pending int; v_avail int; v_ratio numeric;
BEGIN
  SELECT bonus_demand_max_pct, account_id INTO v_max, v_acc FROM public.locations WHERE id = p_location_id;
  IF v_max IS NULL OR v_max = 0 THEN RETURN 0; END IF;

  SELECT count(*) INTO v_pending FROM public.delivery_assignment da
   WHERE da.location_id = p_location_id AND da.state = 'offered';
  SELECT count(*) INTO v_avail FROM public.courier c
   WHERE c.account_id = v_acc AND c.active AND c.on_shift
     AND (c.assigned_locations = '{}'::uuid[] OR p_location_id = ANY(c.assigned_locations));

  IF v_pending = 0 THEN RETURN 0; END IF;
  IF v_avail = 0 THEN RETURN v_max; END IF;

  v_ratio := v_pending::numeric / v_avail;
  RETURN round(greatest(0, least(v_max, (v_ratio - 1.0) / 2.0 * v_max))::numeric, 1);
END;
$$;


--
-- Name: location_economics(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_economics(p_location_id uuid, p_from timestamp with time zone DEFAULT (now() - '90 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS TABLE(revenue numeric, food_cost numeric, labor_cost numeric, food_cost_pct numeric, labor_cost_pct numeric, prime_cost numeric, prime_cost_pct numeric, food_cost_coverage_pct numeric, employee_count integer, is_estimate boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_revenue        numeric := 0;
  v_revenue_costed numeric := 0;
  v_food_cost      numeric := 0;
  v_labor          numeric := 0;
  v_emp            integer := 0;
  v_coverage       numeric := 0;
  v_food_pct       numeric;
  v_labor_pct      numeric;
  v_prime          numeric;
  v_prime_pct      numeric;
  v_estimate       boolean;
BEGIN
  SELECT
    -- revenue TOTAL = SUM(line_total) de TODAS las líneas de producto (casadas o no).
    -- (Antes: solo casadas → base falsa.)
    COALESCE(SUM(COALESCE(sl.line_total, sl.unit_price * sl.quantity)), 0),
    -- revenue CON COSTE = solo líneas casadas cuyo plato tiene coste.
    COALESCE(SUM(COALESCE(sl.line_total, sl.unit_price * sl.quantity))
             FILTER (WHERE sl.menu_item_id IS NOT NULL AND ri_cost.dish_cost IS NOT NULL), 0),
    -- food cost = quantity × coste del plato, solo donde hay coste.
    COALESCE(SUM(sl.quantity * ri_cost.dish_cost)
             FILTER (WHERE sl.menu_item_id IS NOT NULL AND ri_cost.dish_cost IS NOT NULL), 0)
  INTO v_revenue, v_revenue_costed, v_food_cost
  FROM sale_line sl
  JOIN sale s ON s.id = sl.sale_id
  -- LEFT JOIN: las líneas sin casar (menu_item_id null) SÍ cuentan al revenue total.
  LEFT JOIN menu_item mi ON mi.id = sl.menu_item_id
  LEFT JOIN LATERAL (
    SELECT COALESCE(ri.computed_cost, ri.fixed_cost) AS dish_cost
    FROM recipe_item ri WHERE ri.id = mi.recipe_item_id
  ) ri_cost ON true
  WHERE s.location_id = p_location_id
    AND s.is_active = true
    AND COALESCE(sl.line_type, 'product') = 'product'
    AND s.sold_at >= p_from
    AND s.sold_at <  p_to;

  SELECT lc.labor_cost, lc.employee_count
  INTO v_labor, v_emp
  FROM location_labor_cost(p_location_id, p_from, p_to) lc;

  v_labor := COALESCE(v_labor, 0);
  v_emp   := COALESCE(v_emp, 0);

  -- cobertura = lo costeado sobre el revenue TOTAL (honesto: baja si hay ventas ciegas).
  v_coverage := CASE WHEN v_revenue > 0
                     THEN ROUND(v_revenue_costed / v_revenue * 100, 1)
                     ELSE 0 END;

  v_food_pct  := CASE WHEN v_revenue > 0 THEN ROUND(v_food_cost / v_revenue * 100, 2) END;
  v_labor_pct := CASE WHEN v_revenue > 0 THEN ROUND(v_labor / v_revenue * 100, 2) END;
  v_prime     := ROUND(v_food_cost + v_labor, 2);
  v_prime_pct := CASE WHEN v_revenue > 0 THEN ROUND((v_food_cost + v_labor) / v_revenue * 100, 2) END;
  v_estimate  := (v_coverage < 90);

  RETURN QUERY SELECT
    ROUND(v_revenue, 2), ROUND(v_food_cost, 2), ROUND(v_labor, 2),
    v_food_pct, v_labor_pct, v_prime, v_prime_pct,
    v_coverage, v_emp, v_estimate;
END;
$$;


--
-- Name: location_labor_cost(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_labor_cost(p_location_id uuid, p_from timestamp with time zone DEFAULT (now() - '90 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS TABLE(labor_cost numeric, employee_count integer, days_in_period integer, is_estimate boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days integer;
BEGIN
  -- Días del periodo (mínimo 1 para no dividir por cero)
  v_days := GREATEST(1, CEIL(EXTRACT(EPOCH FROM (p_to - p_from)) / 86400.0)::integer);

  RETURN QUERY
  SELECT
    -- salary = coste total anual; prorrateo lineal por días del periodo
    COALESCE(ROUND(SUM(e.salary / 365.0 * v_days), 2), 0)::numeric AS labor_cost,
    COUNT(e.id)::integer                                           AS employee_count,
    v_days                                                         AS days_in_period,
    true                                                           AS is_estimate
  FROM employees e
  WHERE e.active = true
    AND e.location_id = p_location_id
    AND e.salary IS NOT NULL;
END;
$$;


--
-- Name: location_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_status(p_location_id uuid DEFAULT NULL::uuid, p_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device      kds_device;
  v_loc         uuid;
  v_account     uuid;
  v_name        text;
  v_mode        text;
  v_resume_at   timestamptz;
  v_reason      text;
  v_set_at      timestamptz;
  v_ext_loc     text;
begin
  if p_token is not null then
    v_device := public.kds_resolve_device(p_token);
    if v_device.id is null then raise exception 'location_status: token de dispositivo no válido'; end if;
    v_loc := v_device.location_id;
    v_account := v_device.account_id;
  else
    if p_location_id is null then raise exception 'location_status: falta location_id'; end if;
    v_loc := p_location_id;
    v_account := public.kds_authorize(v_loc, null);
  end if;

  select l.name, l.hubrise_status_mode, l.hubrise_status_resume_at, l.hubrise_status_reason, l.hubrise_status_set_at
    into v_name, v_mode, v_resume_at, v_reason, v_set_at
  from locations l where l.id = v_loc;

  select elm.external_location_id into v_ext_loc
  from external_location_map elm
  where elm.account_id = v_account and elm.source = 'hubrise' and elm.is_active
    and elm.location_id = v_loc
  limit 1;

  return jsonb_build_object(
    'location_id',   v_loc,
    'location_name', v_name,
    'mode',          coalesce(v_mode, 'normal'),
    'resume_at',     v_resume_at,
    'reason',        v_reason,
    'set_at',        v_set_at,
    'connected',     v_ext_loc is not null
  );
end;
$$;


--
-- Name: location_surge_pct(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_surge_pct(p_location_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE l public.locations; v_rain numeric; v_dem numeric; v_sum numeric;
BEGIN
  SELECT * INTO l FROM public.locations WHERE id = p_location_id;
  IF NOT FOUND THEN RETURN 0; END IF;
  v_rain := CASE WHEN l.weather_is_raining THEN coalesce(l.bonus_rain_pct,0) ELSE 0 END;
  v_dem  := public.location_demand_pct(p_location_id);
  v_sum  := coalesce(v_rain,0) + coalesce(v_dem,0);
  IF l.bonus_combined_cap_pct IS NOT NULL THEN v_sum := least(v_sum, l.bonus_combined_cap_pct); END IF;
  RETURN round(v_sum::numeric, 1);
END;
$$;


--
-- Name: location_surge_reason(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_surge_reason(p_location_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE l public.locations; v_dem numeric; parts text[] := '{}';
BEGIN
  SELECT * INTO l FROM public.locations WHERE id = p_location_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF l.weather_is_raining AND coalesce(l.bonus_rain_pct,0) > 0 THEN parts := parts || 'lluvia'; END IF;
  v_dem := public.location_demand_pct(p_location_id);
  IF v_dem > 0 THEN parts := parts || 'alta demanda'; END IF;
  RETURN CASE WHEN array_length(parts,1) IS NULL THEN NULL ELSE array_to_string(parts, ' + ') END;
END;
$$;


--
-- Name: log_platform_event(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_platform_event(p_event_type text, p_target_account_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_headers  json;
  v_ip       text;
  v_ip_inet  inet;
  v_ua       text;
  v_id       uuid;
BEGIN
  -- Actor = platform_admin de la sesión actual (la app tiene sesión).
  SELECT id INTO v_admin_id FROM platform_admins
  WHERE user_id = auth.uid() AND active = true LIMIT 1;

  -- IP/UA reales desde las cabeceras de la request (best-effort).
  BEGIN
    v_headers := nullif(current_setting('request.headers', true), '')::json;
    v_ua := v_headers->>'user-agent';
    v_ip := nullif(btrim(split_part(coalesce(v_headers->>'x-forwarded-for',''), ',', 1)), '');
    IF v_ip IS NOT NULL THEN v_ip_inet := v_ip::inet; END IF;
  EXCEPTION WHEN others THEN
    v_ip_inet := NULL;
  END;

  INSERT INTO platform_audit_log
    (event_type, platform_admin_id, target_account_id, target_user_id, details, ip_address, user_agent)
  VALUES
    (p_event_type, v_admin_id, p_target_account_id, p_target_user_id, p_details, v_ip_inet, v_ua)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: lp_evento(text, text, text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lp_evento(quien text, evento text, dispositivo text, tipo text, navegador text, ciudad text, pais text, detalle jsonb DEFAULT NULL::jsonb, propuesta text DEFAULT 'LP-2026-01'::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into propuestas.eventos (propuesta, quien, evento, dispositivo, tipo, navegador, ciudad, pais, detalle)
  values (propuesta, quien, left(evento, 40), left(dispositivo, 64), left(tipo, 20), left(navegador, 80),
          left(ciudad, 80), left(pais, 8), detalle);
$$;


--
-- Name: lp_registro(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lp_registro(k text, propuesta text DEFAULT 'LP-2026-01'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r jsonb;
begin
  if k is null or k <> (select v from propuestas.config where propuestas.config.k = 'admin_key') then
    raise exception 'no autorizado' using errcode = '28000';
  end if;
  select jsonb_build_object(
    'claves', (select coalesce(jsonb_agg(jsonb_build_object('nombre', c.nombre, 'clave', c.clave, 'activa', c.activa) order by c.creada), '[]'::jsonb)
               from propuestas.claves c where c.propuesta = lp_registro.propuesta),
    'eventos', (select coalesce(jsonb_agg(to_jsonb(e) order by e.ts desc), '[]'::jsonb)
                from (select * from propuestas.eventos where propuestas.eventos.propuesta = lp_registro.propuesta order by ts desc limit 2000) e)
  ) into r;
  return r;
end $$;


--
-- Name: lp_set_clave(text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lp_set_clave(k text, nombre text, clave text, activa boolean DEFAULT true, propuesta text DEFAULT 'LP-2026-01'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if k is null or k <> (select v from propuestas.config where propuestas.config.k = 'admin_key') then
    raise exception 'no autorizado' using errcode = '28000';
  end if;
  if length(trim(clave)) < 6 then raise exception 'clave demasiado corta'; end if;
  insert into propuestas.claves (nombre, clave, activa, propuesta)
  values (lower(trim(nombre)), trim(clave), activa, propuesta)
  on conflict (nombre) do update set clave = excluded.clave, activa = excluded.activa;
end $$;


--
-- Name: lp_validar_clave(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lp_validar_clave(p text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select nombre from propuestas.claves
  where activa
    and length(regexp_replace(coalesce(p,''), '[^A-Za-z0-9]', '', 'g')) >= 6
    and lower(regexp_replace(clave, '[^A-Za-z0-9]', '', 'g'))
      = lower(regexp_replace(coalesce(p,''), '[^A-Za-z0-9]', '', 'g'))
  limit 1;
$$;


--
-- Name: map_sales_product_to_dish(uuid, text, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.map_sales_product_to_dish(p_account_id uuid, p_product_name text, p_recipe_item_id uuid, p_brand_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_method text DEFAULT 'manual'::text) RETURNS TABLE(resultado text, menu_item_id uuid, recipe_item_id uuid, brand_id uuid, lineas_futuras integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'map_sales_product_to_dish: sin acceso a la cuenta %', p_account_id;
  end if;
  return query
    select * from public._map_sales_product_to_dish_internal(
      p_account_id, p_product_name, p_recipe_item_id, p_brand_id, p_actor_name, p_method);
end;
$$;


--
-- Name: FUNCTION map_sales_product_to_dish(p_account_id uuid, p_product_name text, p_recipe_item_id uuid, p_brand_id uuid, p_actor_name text, p_method text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.map_sales_product_to_dish(p_account_id uuid, p_product_name text, p_recipe_item_id uuid, p_brand_id uuid, p_actor_name text, p_method text) IS 'Casa un producto vendido del TPV a un plato QUE YA EXISTE (apunta el menu_item sellado por matrícula). No crea platos y no reprocesa histórico.';


--
-- Name: marcar_capturas_purgadas(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_capturas_purgadas(p_ids uuid[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with hechas as (
    update public.sale_capture
       set purged_at = now()
     where id = any(p_ids) and purged_at is null
    returning 1
  )
  select count(*)::int from hechas;
$$;


--
-- Name: FUNCTION marcar_capturas_purgadas(p_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.marcar_capturas_purgadas(p_ids uuid[]) IS 'C9 L2 §5: sella purged_at DESPUES de que el objeto se haya borrado del bucket. La fila no se borra: queda de recibo de que la foto existio y de que se purgo.';


--
-- Name: marcar_recogido_by_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_recogido_by_token(p_device_token text, p_sale_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
  v_acc    uuid;
  v_loc    uuid;
  v_hora   timestamptz;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'marcar_recogido_by_token: token no válido';
  end if;

  select account_id, location_id, handed_to_courier_at
    into v_acc, v_loc, v_hora
    from sale where id = p_sale_id;
  if v_acc is null then
    raise exception 'marcar_recogido_by_token: venta inexistente';
  end if;
  if v_acc <> v_device.account_id then
    raise exception 'marcar_recogido_by_token: la venta no pertenece a la cuenta del dispositivo';
  end if;
  if v_device.location_id is not null and v_loc is distinct from v_device.location_id then
    raise exception 'marcar_recogido_by_token: la venta no pertenece al local del dispositivo';
  end if;

  if v_hora is not null then
    return v_hora;                      -- ya lo sabíamos: no se pisa
  end if;

  update sale
     set handed_to_courier_at = now(),
         updated_at           = now()
   where id = p_sale_id
     and handed_to_courier_at is null
  returning handed_to_courier_at into v_hora;

  -- Si entre el select y el update llegó el aviso, `v_hora` vuelve null: se lee
  -- otra vez y se devuelve la que haya. El botón nunca se queda sin respuesta.
  if v_hora is null then
    select handed_to_courier_at into v_hora from sale where id = p_sale_id;
  end if;

  return v_hora;
end $$;


--
-- Name: margin_by_brand(uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.margin_by_brand(p_account uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  with base as (
    select s.brand_id, b.name as brand, s.channel_id, s.location_id,
      sum(sl.quantity*sl.unit_price) filter (where ri.computed_cost is not null) as venta,
      sum(sl.quantity*ri.computed_cost) filter (where ri.computed_cost is not null) as food,
      count(*) as lineas,
      count(*) filter (where ri.computed_cost is not null) as lineas_costeadas
    from public.sale_line sl
    join public.sale s on s.id = sl.sale_id
    left join public.menu_item mi on mi.id = sl.menu_item_id
    left join public.recipe_item ri on ri.id = mi.recipe_item_id
    left join public.brand b on b.id = s.brand_id
    where sl.account_id = p_account
      and s.channel_id is not null
      and coalesce(s.status,'') <> 'cancelled'
      and (p_from is null or s.sold_at >= p_from)
      and (p_to  is null or s.sold_at <  p_to)
      and (p_location is null or s.location_id = p_location)
    group by s.brand_id, b.name, s.channel_id, s.location_id
  ),
  withrate as (
    select *, public.resolve_channel_commission(p_account, channel_id, brand_id, location_id, 'platform_delivery') as rate
    from base
  ),
  -- promo REAL por marca desde Capa C (channel_settlement_order): promo / venta bruta
  promo_cte as (
    select brand_id,
      sum(coalesce(promo_product,0)+coalesce(promo_flash,0)) as promo,
      sum(coalesce(net_payout,0)+coalesce(commission,0)+coalesce(promo_product,0)+coalesce(promo_flash,0)) as gross
    from public.channel_settlement_order
    where account_id = p_account
      and (p_from is null or order_date >= p_from::date)
      and (p_to  is null or order_date <  p_to::date)
      and (p_location is null or location_id = p_location)
    group by brand_id
  ),
  bybrand as (
    select w.brand, w.brand_id,
      round(sum(coalesce(w.venta,0))) as venta,
      round(sum(coalesce(w.food,0))) as food,
      round(sum(coalesce(w.venta,0) * coalesce(w.rate,0)/100.0)) as comision,
      round(100.0*sum(coalesce(w.venta,0) * coalesce(w.rate,0)/100.0)/nullif(sum(w.venta),0),1) as comision_pct,
      round(100.0*sum(w.food)/nullif(sum(w.venta),0),1) as food_pct,
      round(100.0*sum(w.lineas_costeadas)/nullif(sum(w.lineas),0),1) as cobertura_pct,
      coalesce(max(case when p.gross > 0 then round(100.0*p.promo/p.gross,1) end),0) as promo_pct
    from withrate w
    left join promo_cte p on p.brand_id = w.brand_id
    where w.brand is not null group by w.brand, w.brand_id
    having sum(coalesce(w.venta,0)) > 0
  )
  select jsonb_build_object(
    'total', jsonb_build_object(
      'venta', round(sum(venta)), 'comision', round(sum(comision)), 'food', round(sum(food)),
      'promo', round(sum(venta*promo_pct/100.0))
    ),
    'by_brand', coalesce(jsonb_agg(jsonb_build_object(
      'brand', brand, 'venta', venta, 'comision', comision, 'comision_pct', comision_pct,
      'food', food, 'food_pct', food_pct, 'promo_pct', promo_pct, 'cobertura_pct', cobertura_pct
    ) order by venta desc), '[]'::jsonb)
  )
  from bybrand;
$$;


--
-- Name: FUNCTION margin_by_brand(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.margin_by_brand(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid) IS 'Margen por marca con comision REAL (resolve_channel_commission, asume reparto plataforma) + food cost REAL (escandallo). Promo/personal se anaden en cliente como supuestos.';


--
-- Name: mark_ctb_notification_sent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_ctb_notification_sent(p_queue_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc  uuid;
  v_user uuid;
  v_name text;
BEGIN
  SELECT account_id INTO v_acc FROM ctb_notification_queue WHERE id = p_queue_id;
  IF v_acc IS NULL THEN
    RAISE EXCEPTION 'mark_ctb_notification_sent: entrada % no existe', p_queue_id;
  END IF;
  IF NOT (current_user_is_admin() OR current_user_is_admin_or_manager_of(v_acc)) THEN
    RAISE EXCEPTION 'mark_ctb_notification_sent: sin acceso';
  END IF;
  v_user := auth.uid();
  SELECT display_name INTO v_name FROM user_profiles WHERE id = v_user;
  UPDATE ctb_notification_queue
    SET status = 'enviado', sent_by = v_user, sent_by_name = v_name,
        sent_at = now(), updated_at = now()
    WHERE id = p_queue_id;
END;
$$;


--
-- Name: mark_shop_order_failed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_shop_order_failed(p_payment_intent_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale sale%rowtype;
begin
  select * into v_sale from sale
  where stripe_payment_intent_id = p_payment_intent_id
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'sale_not_found');
  end if;

  -- no tocar un pedido que ya se pagó
  if coalesce(v_sale.payment_status,'') = 'paid' then
    return jsonb_build_object('ok', true, 'already_paid', true, 'saleId', v_sale.id);
  end if;

  update sale set payment_status = 'failed' where id = v_sale.id;
  return jsonb_build_object('ok', true, 'saleId', v_sale.id);
end;
$$;


--
-- Name: mark_shop_order_paid(text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_shop_order_paid(p_payment_intent_id text, p_amount_cents bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale sale%rowtype;
begin
  select * into v_sale from sale
  where stripe_payment_intent_id = p_payment_intent_id
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'sale_not_found');
  end if;

  -- idempotente: ya estaba pagada
  if coalesce(v_sale.payment_status,'') = 'paid' then
    return jsonb_build_object('ok', true, 'already', true, 'saleId', v_sale.id);
  end if;

  update sale
  set payment_status = 'paid',
      paid_at = now(),
      -- mover a 'accepted' SOLO si seguía 'new' (no pisar estados posteriores)
      order_status = case when order_status = 'new' then 'accepted' else order_status end
  where id = v_sale.id;

  return jsonb_build_object('ok', true, 'already', false, 'saleId', v_sale.id);
end;
$$;


--
-- Name: mark_social_post_published(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_social_post_published(p_post_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_cur text;
begin
  select account_id, status into v_acc, v_cur from social_post where id = p_post_id;
  if v_acc is null then raise exception 'post no encontrado'; end if;
  if not current_user_is_admin_or_manager_of(v_acc) then raise exception 'no autorizado'; end if;
  if v_cur = 'published' then return; end if;   -- idempotente
  update social_post
     set status = 'published',
         published_at = coalesce(published_at, now()),
         updated_at = now()
   where id = p_post_id;
end $$;


--
-- Name: mark_supplier_invoice_paid(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_supplier_invoice_paid(p_invoice_id uuid, p_paid_at date, p_method text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_inv supplier_invoice%rowtype; v_name text; v_pagos numeric;
begin
  select * into v_inv from supplier_invoice where id = p_invoice_id for update;
  if not found or not belongs_to_account(v_inv.account_id) then raise exception 'No encuentro esa factura.'; end if;
  if v_inv.status not in ('aprobada','pagada') then
    raise exception 'Solo se puede marcar como pagada una factura aprobada.';
  end if;
  if p_paid_at is null then raise exception 'Falta la fecha de pago.'; end if;
  if p_method is not null and p_method not in ('transfer','direct_debit','card','cash','prepaid') then
    raise exception 'No conozco la forma de pago «%». Puede ser: Transferencia, Domiciliación, Tarjeta, Efectivo o Saldo prepago Catcher (40700001).', p_method;
  end if;
  -- PC01 (Julio, 25/10): o hay un pago con asiento, o no está pagada. Solo la
  -- marcan pagada los pagos con asiento que la cubren (Bancos al casar, el pago
  -- del lote de prepago); a mano, no.
  select coalesce(sum(amount), 0) into v_pagos from supplier_invoice_payment where invoice_id = p_invoice_id and entry_id is not null;
  if v_pagos < coalesce(v_inv.grand_total, 0) - 0.005 then
    raise exception 'La factura % no se marca pagada a mano: queda pagada sola cuando su pago tiene asiento (al casarlo en Bancos). Lleva pagado con asiento % de %.',
      coalesce(v_inv.invoice_number, ''), public.conta_euros_exactos(v_pagos), public.conta_euros_exactos(coalesce(v_inv.grand_total, 0)) using errcode = '23514';
  end if;
  v_name := _actor_name(v_inv.account_id);
  update supplier_invoice set status = 'pagada', paid_at = p_paid_at, paid_method = p_method,
         paid_by = auth.uid(), paid_by_name = v_name, updated_at = now()
   where id = p_invoice_id;
  insert into supplier_invoice_payment_log (account_id, invoice_id, action, paid_at, paid_method, actor_id, actor_name)
  values (v_inv.account_id, p_invoice_id, 'paid', p_paid_at, p_method, auth.uid(), v_name);
end $$;


--
-- Name: materialize_recipe_session(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.materialize_recipe_session(p_session_id uuid, p_decisions jsonb DEFAULT NULL::jsonb) RETURNS TABLE(result_recipe_id uuid, dish_name text, was_created boolean, lines_created integer, new_articles_created integer, lines_skipped integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_parsed     jsonb;
  v_dish       jsonb;
  v_dish_name  text;
  v_recipe_id  uuid;
  v_created    boolean := false;
  v_line       jsonb;
  v_raw_text   text;
  v_norm       text;
  v_qty        numeric;
  v_unit_txt   text;
  v_unit_id    uuid;
  v_cost       numeric;
  v_note       text;
  v_child_id   uuid;
  v_chosen     uuid;
  v_decided    boolean;
  v_pos        int := 0;
  v_lines      int := 0;
  v_newart     int := 0;
  v_skipped    int := 0;
  v_default_unit uuid;   -- unidad 'ud' para base_unit_id del plato
BEGIN
  -- ── Cargar la sesión ──
  SELECT s.account_id, s.parsed_result, s.recipe_item_id
  INTO v_account_id, v_parsed, v_recipe_id
  FROM recipe_item_ai_session s WHERE s.id = p_session_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'Sesión % no encontrada', p_session_id;
  END IF;

  -- Persistir las decisiones recibidas en la sesión (trazabilidad + futuras lecturas).
  IF p_decisions IS NOT NULL THEN
    UPDATE recipe_item_ai_session
    SET decisions = p_decisions, updated_at = now()
    WHERE id = p_session_id;
  END IF;

  v_dish := v_parsed->'dish';
  v_dish_name := COALESCE(v_dish->>'name', 'Escandallo sin nombre');

  -- unidad por defecto del plato (una ración = 1 ud)
  SELECT id INTO v_default_unit FROM kitchen_unit
  WHERE (account_id = v_account_id OR account_id IS NULL)
    AND lower(abbreviation) = 'ud'
  LIMIT 1;

  -- ── El PLATO: actualizar existente o crear nuevo ──
  IF v_recipe_id IS NOT NULL THEN
    -- actualizar: limpiar las líneas anteriores (se reemplazan por las nuevas)
    DELETE FROM recipe_line WHERE parent_item_id = v_recipe_id;
    v_created := false;
  ELSE
    -- crear plato nuevo (folvy_code lo pone el trigger)
    INSERT INTO recipe_item (account_id, type, name, source, base_unit_id, ai_confidence, created_by_name)
    VALUES (v_account_id, 'dish', v_dish_name, 'ai_recipe', v_default_unit, NULL, 'IA (foto)')
    RETURNING id INTO v_recipe_id;
    v_created := true;
    -- vincular la sesión al plato creado
    UPDATE recipe_item_ai_session SET recipe_item_id = v_recipe_id WHERE id = p_session_id;
  END IF;

  -- ── Las LÍNEAS ──
  FOR v_line IN SELECT * FROM jsonb_array_elements(v_parsed->'lines')
  LOOP
    v_raw_text := v_line->>'raw_text';
    CONTINUE WHEN v_raw_text IS NULL OR trim(v_raw_text) = '';
    v_norm  := normalize_ingredient_name(v_raw_text);
    v_qty   := NULLIF(v_line->>'quantity','')::numeric;
    v_unit_txt := lower(trim(COALESCE(v_line->>'unit','')));
    v_cost  := NULLIF(v_line->>'cost','')::numeric;
    v_note  := v_line->>'note';

    -- resolver unidad por abreviatura normalizada (g, gr→g; ud, uds, unidad→ud)
    SELECT id INTO v_unit_id FROM kitchen_unit
    WHERE (account_id = v_account_id OR account_id IS NULL)
      AND lower(abbreviation) = CASE
            WHEN v_unit_txt IN ('g','gr','gramo','gramos') THEN 'g'
            WHEN v_unit_txt IN ('kg','kilo','kilogramo')   THEN 'kg'
            WHEN v_unit_txt IN ('l','litro','litros')      THEN 'l'
            WHEN v_unit_txt IN ('ml','mililitro')          THEN 'ml'
            WHEN v_unit_txt IN ('ud','uds','unidad','u')   THEN 'ud'
            ELSE v_unit_txt END
    LIMIT 1;

    -- si la unidad no se reconoce, no inventamos: omitir y contar
    IF v_unit_id IS NULL OR v_qty IS NULL THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- ── Resolver el ingrediente de esta línea ──
    v_chosen  := NULL;
    v_decided := false;

    -- (1) PRIORIDAD ABSOLUTA: decisión humana pasada en p_decisions.
    --     Presencia de la clave = el humano YA decidió esta línea.
    IF p_decisions IS NOT NULL AND (p_decisions ? v_norm) THEN
      v_decided := true;
      IF jsonb_typeof(p_decisions->v_norm) = 'string' THEN
        v_chosen := NULLIF(p_decisions->>v_norm, '')::uuid;   -- uuid = usar existente
      ELSE
        v_chosen := NULL;                                     -- null = crear nuevo a propósito
      END IF;
    END IF;

    -- (2) FALLBACK: mapping_proposal (flujo viejo end-to-end, o líneas sin decisión).
    IF NOT v_decided THEN
      SELECT chosen_target_id INTO v_chosen
      FROM mapping_proposal
      WHERE source_ref = p_session_id
        AND source_normalized = v_norm
        AND status IN ('auto_confirmed','needs_review','human_confirmed')
      LIMIT 1;
    END IF;

    IF v_chosen IS NOT NULL THEN
      -- artículo existente elegido por el humano (o por la propuesta): NO duplica.
      v_child_id := v_chosen;
    ELSE
      -- artículo NUEVO: crear provisional, needs_review + motivo.
      -- cost_strategy SIEMPRE 'fixed' (NOT NULL): si no hay coste, fixed_cost
      -- queda NULL = "sin coste, a completar". Igual que el defecto del front.
      INSERT INTO recipe_item (
        account_id, type, name, source, fixed_cost, cost_strategy,
        base_unit_id, needs_review, review_notes, created_by_name
      )
      VALUES (
        v_account_id, 'raw', v_raw_text, 'ai_recipe', v_cost,
        'fixed',
        v_unit_id, true,
        jsonb_build_object('reason', 'Creado automáticamente desde ficha (foto). Completar coste real, proveedor y formato.',
                           'origin_session', p_session_id),
        'IA (foto)'
      )
      RETURNING id INTO v_child_id;
      v_newart := v_newart + 1;
    END IF;

    -- crear la línea del escandallo
    v_pos := v_pos + 1;
    INSERT INTO recipe_line (
      account_id, parent_item_id, child_item_id,
      quantity_net, unit_id, comment, position
    )
    VALUES (
      v_account_id, v_recipe_id, v_child_id,
      v_qty, v_unit_id, v_note, v_pos
    );
    v_lines := v_lines + 1;
  END LOOP;

  -- ── Cerrar la sesión ──
  UPDATE recipe_item_ai_session SET status = 'accepted', updated_at = now()
  WHERE id = p_session_id;

  RETURN QUERY SELECT v_recipe_id, v_dish_name, v_created, v_lines, v_newart, v_skipped;
END;
$$;


--
-- Name: menu_item_channel_economics(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_item_channel_economics(p_menu_item_id uuid, p_overrides jsonb DEFAULT NULL::jsonb, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(channel_id uuid, channel_name text, channel_type text, service_type text, price numeric, price_source text, is_location_override boolean, is_available boolean, vat_rate numeric, price_with_vat numeric, cost numeric, packaging_cost numeric, food_cost numeric, cost_available boolean, commission_pct numeric, commission_base text, commission_amount numeric, commission_fixed numeric, own_courier_cost numeric, own_customer_fee numeric, order_costs_per_item numeric, contribution_margin numeric, contribution_margin_pct numeric, net_margin numeric, net_margin_pct numeric, food_cost_pct numeric, target_food_cost_pct numeric, food_cost_status text, plate_cost_pct numeric, target_plate_cost_pct numeric, plate_cost_status text, orders_30d integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id      uuid;
  v_brand_id        uuid;
  v_recipe_item_id  uuid;
  v_base_price      numeric;
  v_vat             numeric;
  v_cost            numeric;
  v_packaging       numeric := 0;
  v_food            numeric;
  v_cost_avail      boolean;
  v_target          numeric;
  v_target_plate    numeric;
  -- B79 3.11 (06/09/2026): el objetivo PROPIO del plato, si lo tiene.
  v_target_own      numeric;
  v_items_per_order numeric := 2;
BEGIN
  SELECT mi.account_id, mi.brand_id, mi.recipe_item_id, mi.price, COALESCE(mi.vat_rate, 0),
         mi.target_food_cost_pct
    INTO v_account_id, v_brand_id, v_recipe_item_id, v_base_price, v_vat,
         v_target_own
  FROM menu_item mi
  WHERE mi.id = p_menu_item_id
    AND mi.archived_at IS NULL;

  IF v_account_id IS NULL THEN
    RETURN;
  END IF;

  SELECT ri.computed_cost, COALESCE(ri.packaging_cost, 0)
    INTO v_cost, v_packaging
  FROM recipe_item ri WHERE ri.id = v_recipe_item_id;
  v_cost_avail := (v_cost IS NOT NULL);
  v_food := COALESCE(v_cost, 0) - COALESCE(v_packaging, 0);

  SELECT ks.target_food_cost_pct, ks.target_plate_cost_pct
    INTO v_target, v_target_plate
  FROM kitchen_settings ks WHERE ks.account_id = v_account_id;

  -- EL OBJETIVO DEL PLATO MANDA SOBRE EL DE LA CUENTA (B79 3.11).
  -- Va DESPUES del SELECT y no dentro de el a proposito: si la cuenta no
  -- tiene fila en kitchen_settings, un `SELECT ... INTO` sin filas NO asigna
  -- nada, y meter el COALESCE dentro dejaria sin objetivo a un plato que si
  -- lo tiene. Asi el del plato sobrevive a que la cuenta no tenga fila.
  v_target := COALESCE(v_target_own, v_target);

  -- El objetivo de COSTE DE PLATO no se toca: `menu_item` no tiene columna
  -- para el (comprobado en information_schema, 06/09/2026), asi que sigue
  -- siendo solo de la cuenta. Si algun dia la tiene, este es su sitio.

  RETURN QUERY
  WITH ch AS (
    SELECT sc.id AS channel_id, sc.name AS channel_name, sc.channel_type
    FROM sales_channel sc
    WHERE sc.account_id = v_account_id
      AND sc.is_active = true
  ),
  rate AS (
    SELECT
      ch.channel_id, ch.channel_name, ch.channel_type,
      COALESCE(bcr.service_type,            cr.service_type)            AS service_type,
      COALESCE(bcr.commission_pct,          cr.commission_pct)          AS commission_pct,
      COALESCE(bcr.commission_fixed,        cr.commission_fixed)        AS commission_fixed,
      COALESCE(bcr.commission_base,         cr.commission_base)         AS commission_base,
      COALESCE(bcr.own_courier_cost,        cr.own_courier_cost)        AS own_courier_cost,
      COALESCE(bcr.own_customer_fee,        cr.own_customer_fee)        AS own_customer_fee,
      COALESCE(bcr.own_customer_fee_vat_pct, cr.own_customer_fee_vat_pct, 10) AS own_customer_fee_vat_pct
    FROM ch
    LEFT JOIN brand_channel bc
           ON bc.brand_id = v_brand_id
          AND bc.channel_id = ch.channel_id
          AND bc.is_active = true
    LEFT JOIN brand_channel_rate bcr
           ON bcr.brand_channel_id = bc.id
          AND bcr.is_active = true
          AND bcr.archived_at IS NULL
    LEFT JOIN channel_rate cr
           ON cr.sales_channel_id = ch.channel_id
          AND cr.is_active = true
          AND cr.archived_at IS NULL
  ),
  usage_30d AS (
    SELECT s.channel_id, s.service_type, count(*)::integer AS n
    FROM sale s
    WHERE s.account_id = v_account_id
      AND s.created_at >= now() - interval '30 days'
    GROUP BY s.channel_id, s.service_type
  ),
  ov AS (
    SELECT o.channel_id, o.is_available AS ov_avail
    FROM menu_item_override o
    WHERE o.menu_item_id = p_menu_item_id
      AND o.location_id IS NULL
  ),
  eff AS (
    SELECT
      rate.*,
      COALESCE(usage_30d.n, 0) AS orders_30d,
      CASE
        WHEN p_overrides IS NOT NULL AND p_overrides ? rate.channel_id::text
             THEN (p_overrides ->> rate.channel_id::text)::numeric
        ELSE public.effective_price(p_menu_item_id, rate.channel_id, p_location_id)
      END AS eff_price,
      CASE
        WHEN p_overrides IS NOT NULL AND p_overrides ? rate.channel_id::text THEN 'preview'
        WHEN loc_ov.has_location_override OR loc_ov.has_brand_override THEN 'override'
        ELSE 'base'
      END AS price_source,
      (NOT (p_overrides IS NOT NULL AND p_overrides ? rate.channel_id::text))
        AND loc_ov.has_location_override AS is_location_override,
      COALESCE(ov.ov_avail, true) AS is_available
    FROM rate
    LEFT JOIN usage_30d ON usage_30d.channel_id = rate.channel_id AND usage_30d.service_type IS NOT DISTINCT FROM rate.service_type
    LEFT JOIN ov ON ov.channel_id = rate.channel_id
    LEFT JOIN LATERAL (
      SELECT
        EXISTS (
          SELECT 1 FROM menu_item_override mio
          WHERE mio.menu_item_id = p_menu_item_id
            AND p_location_id IS NOT NULL AND mio.location_id = p_location_id
            AND (mio.channel_id = rate.channel_id OR mio.channel_id IS NULL)
            AND mio.price IS NOT NULL
        ) AS has_location_override,
        EXISTS (
          SELECT 1 FROM menu_item_override mio2
          WHERE mio2.menu_item_id = p_menu_item_id
            AND mio2.channel_id = rate.channel_id
            AND mio2.location_id IS NULL
            AND mio2.price IS NOT NULL
        ) AS has_brand_override
    ) loc_ov ON true
  ),
  calc AS (
    SELECT
      eff.*,
      -- ANTES: ROUND(eff.eff_price * (1 + v_vat/100.0), 2) AS pvp_con_iva
      -- eff_price YA es el precio que paga el cliente.
      eff.eff_price                              AS pvp_bruto,
      -- Sin ROUND intermedio: se redondea solo en la salida.
      eff.eff_price / (1 + v_vat/100.0)          AS ingreso_neto,
      CASE WHEN eff.service_type = 'own_delivery' THEN
        ROUND(
          ( COALESCE(ROUND(eff.commission_fixed / 1.21, 2), 0)
          + COALESCE(ROUND(eff.own_courier_cost  / 1.21, 2), 0)
          - COALESCE(ROUND(eff.own_customer_fee / (1 + eff.own_customer_fee_vat_pct/100.0), 2), 0)
          ) / v_items_per_order, 2)
      ELSE 0 END AS order_costs_per_item
    FROM eff
  ),
  m AS (
    SELECT
      calc.*,
      -- 'pvp_sin_iva' comisiona sobre el NETO, cualquier otro sobre el BRUTO.
      CASE calc.commission_base WHEN 'pvp_sin_iva' THEN calc.ingreso_neto ELSE calc.pvp_bruto END AS comm_basis
    FROM calc
  ),
  f AS (
    SELECT
      m.*,
      CASE WHEN m.commission_pct IS NOT NULL
           THEN ROUND(m.comm_basis * m.commission_pct / 100.0, 2) END AS commission_amount
    FROM m
  )
  SELECT
    f.channel_id,
    f.channel_name,
    f.channel_type,
    f.service_type,
    f.eff_price                                   AS price,
    f.price_source,
    f.is_location_override,
    f.is_available,
    v_vat                                         AS vat_rate,
    f.pvp_bruto                                   AS price_with_vat,
    v_cost                                        AS cost,
    v_packaging                                   AS packaging_cost,
    v_food                                        AS food_cost,
    v_cost_avail                                  AS cost_available,
    f.commission_pct,
    f.commission_base,
    f.commission_amount,
    f.commission_fixed,
    f.own_courier_cost,
    f.own_customer_fee,
    f.order_costs_per_item,
    ROUND(f.ingreso_neto - (CASE WHEN v_cost_avail THEN v_cost ELSE 0 END) - COALESCE(f.commission_amount, 0), 2) AS contribution_margin,
    CASE WHEN f.ingreso_neto > 0
         THEN ROUND((f.ingreso_neto - (CASE WHEN v_cost_avail THEN v_cost ELSE 0 END) - COALESCE(f.commission_amount, 0)) / f.ingreso_neto * 100, 2) END AS contribution_margin_pct,
    ROUND(f.ingreso_neto - (CASE WHEN v_cost_avail THEN v_cost ELSE 0 END) - COALESCE(f.commission_amount, 0) - COALESCE(f.order_costs_per_item, 0), 2) AS net_margin,
    CASE WHEN f.ingreso_neto > 0
         THEN ROUND((f.ingreso_neto - (CASE WHEN v_cost_avail THEN v_cost ELSE 0 END) - COALESCE(f.commission_amount, 0) - COALESCE(f.order_costs_per_item, 0)) / f.ingreso_neto * 100, 2) END AS net_margin_pct,
    CASE WHEN v_cost_avail AND f.ingreso_neto > 0
         THEN ROUND(v_food / f.ingreso_neto * 100, 2) END AS food_cost_pct,
    v_target                                      AS target_food_cost_pct,
    CASE
      WHEN NOT v_cost_avail          THEN 'no_cost'
      WHEN f.ingreso_neto <= 0       THEN 'no_cost'
      WHEN v_target IS NULL          THEN 'no_target'
      WHEN (v_food / f.ingreso_neto * 100) <= v_target THEN 'under'
      ELSE 'over'
    END AS food_cost_status,
    CASE WHEN v_cost_avail AND f.ingreso_neto > 0
         THEN ROUND(v_cost / f.ingreso_neto * 100, 2) END AS plate_cost_pct,
    v_target_plate                                AS target_plate_cost_pct,
    CASE
      WHEN NOT v_cost_avail              THEN 'no_cost'
      WHEN f.ingreso_neto <= 0           THEN 'no_cost'
      WHEN v_target_plate IS NULL        THEN 'no_target'
      WHEN (v_cost / f.ingreso_neto * 100) <= v_target_plate THEN 'under'
      ELSE 'over'
    END AS plate_cost_status,
    f.orders_30d
  FROM f
  ORDER BY f.channel_name;
END;
$$;


--
-- Name: FUNCTION menu_item_channel_economics(p_menu_item_id uuid, p_overrides jsonb, p_location_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.menu_item_channel_economics(p_menu_item_id uuid, p_overrides jsonb, p_location_id uuid) IS 'Economia por canal de un producto. menu_item.price es PRECIO CON IVA INCLUIDO (verificado 17/08 contra ventas reales: sale_line.unit_price = price exacto en 2.925 lineas, cero a price*1,10). ingreso_neto = price/(1+iva); la comision sigue sobre BRUTO porque las plataformas comisionan sobre el total que paga el cliente. price_with_vat = price. No toca target_food_cost_pct a proposito.';


--
-- Name: menu_item_economics(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_item_economics(p_brand_id uuid, p_service_type text DEFAULT 'platform_delivery'::text) RETURNS TABLE(menu_item_id uuid, menu_item_name text, recipe_item_id uuid, channel_id uuid, channel_name text, flow_type text, cost numeric, packaging_cost numeric, food_cost numeric, cost_available boolean, price numeric, vat_rate numeric, price_with_vat numeric, food_cost_pct numeric, contribution_margin numeric, commission_pct numeric, commission_amount numeric, commission_fixed numeric, delivery_fee numeric, revenue_share_pct numeric, revenue_share_amount numeric, consumption_reimb numeric, net_margin numeric, net_margin_pct numeric, target_food_cost_pct numeric, food_cost_status text, plate_cost_pct numeric, target_plate_cost_pct numeric, plate_cost_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
BEGIN
  SELECT b.account_id INTO v_account_id FROM brand b WHERE b.id = p_brand_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'Marca % no encontrada', p_brand_id;
  END IF;

  IF NOT (current_user_is_admin()
          OR current_user_is_admin_or_manager_of(v_account_id)) THEN
    RAISE EXCEPTION 'Sin permiso para la economía de la marca %', p_brand_id;
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT
      mi.id                AS menu_item_id,
      mi.name              AS menu_item_name,
      mi.recipe_item_id    AS recipe_item_id,
      mi.channel_id        AS channel_id,
      sc.name              AS channel_name,
      b.ownership_type     AS flow_type,
      ri.computed_cost     AS cost,
      COALESCE(ri.packaging_cost, 0)          AS packaging_cost,
      (ri.computed_cost IS NOT NULL) AS cost_available,
      mi.price             AS price,
      mi.vat_rate          AS vat_rate,
      -- ANTES: ROUND(mi.price * (1 + mi.vat_rate / 100), 4)
      mi.price                                AS price_with_vat,
      mi.consumption_price AS consumption_price,
      COALESCE(bcr.commission_pct,   cr.commission_pct)   AS commission_pct,
      COALESCE(bcr.commission_fixed, cr.commission_fixed) AS commission_fixed,
      COALESCE(bcr.commission_base,  cr.commission_base)  AS commission_base,
      COALESCE(bcr.own_courier_cost, cr.own_courier_cost) AS own_courier_cost,
      bla.revenue_share_pct      AS revenue_share_pct,
      bla.reimburses_consumption AS reimburses_consumption,
      -- EL OBJETIVO DEL PLATO MANDA SOBRE EL DE LA CUENTA (B79 3.11,
      -- 06/09/2026). 8 platos de Foodint tenian el suyo puesto a mano desde la
      -- pestana Ficha y esta funcion no lo miraba: leia solo el de la cuenta,
      -- que esta a NULL en las tres cuentas. Ocho decisiones sin efecto.
      COALESCE(mi.target_food_cost_pct, ks.target_food_cost_pct) AS target_food_cost_pct,
      -- El de COSTE DE PLATO no lleva COALESCE: `menu_item` no tiene esa
      -- columna (comprobado en information_schema, 06/09/2026). Sigue siendo
      -- de la cuenta.
      ks.target_plate_cost_pct   AS target_plate_cost_pct
    FROM menu_item mi
    JOIN brand b          ON b.id = mi.brand_id
    LEFT JOIN sales_channel sc ON sc.id = mi.channel_id
    LEFT JOIN recipe_item ri   ON ri.id = mi.recipe_item_id
    LEFT JOIN brand_channel bc
           ON bc.brand_id = mi.brand_id
          AND bc.channel_id = mi.channel_id
          AND bc.is_active = true
    LEFT JOIN brand_channel_rate bcr
           ON bcr.brand_channel_id = bc.id
          AND bcr.service_type = p_service_type
          AND bcr.is_active = true
          AND bcr.archived_at IS NULL
    LEFT JOIN channel_rate cr
           ON cr.sales_channel_id = mi.channel_id
          AND cr.service_type = p_service_type
          AND cr.is_active = true
          AND cr.archived_at IS NULL
    LEFT JOIN brand_licensing_agreement bla
           ON bla.brand_id = mi.brand_id AND bla.is_active = true
    LEFT JOIN kitchen_settings ks ON ks.account_id = mi.account_id
    WHERE mi.brand_id = p_brand_id
      AND mi.archived_at IS NULL
  ),
  calc AS (
    SELECT
      base.*,
      (base.cost - COALESCE(base.packaging_cost, 0)) AS food_cost,
      base.price / (1 + COALESCE(base.vat_rate, 0)/100.0) AS ingreso_neto,
      CASE base.commission_base
        WHEN 'pvp_sin_iva' THEN base.price / (1 + COALESCE(base.vat_rate, 0)/100.0)
        ELSE base.price
      END AS commission_basis
    FROM base
  )
  SELECT
    calc.menu_item_id,
    calc.menu_item_name,
    calc.recipe_item_id,
    calc.channel_id,
    calc.channel_name,
    calc.flow_type,
    calc.cost,
    calc.packaging_cost,
    calc.food_cost,
    calc.cost_available,
    calc.price,
    calc.vat_rate,
    calc.price_with_vat,
    CASE WHEN calc.flow_type = 'own' AND calc.cost_available AND calc.ingreso_neto > 0
         THEN ROUND(calc.food_cost / calc.ingreso_neto * 100, 2) END AS food_cost_pct,
    CASE WHEN calc.flow_type = 'own' AND calc.cost_available
         THEN ROUND(calc.ingreso_neto - calc.cost, 4) END AS contribution_margin,
    CASE WHEN calc.flow_type = 'own' THEN calc.commission_pct END AS commission_pct,
    CASE WHEN calc.flow_type = 'own' AND calc.commission_pct IS NOT NULL
         THEN ROUND(calc.commission_basis * calc.commission_pct / 100, 4) END AS commission_amount,
    CASE WHEN calc.flow_type = 'own' THEN calc.commission_fixed END AS commission_fixed,
    CASE WHEN calc.flow_type = 'own' THEN calc.own_courier_cost END AS delivery_fee,
    CASE WHEN calc.flow_type = 'licensed' THEN calc.revenue_share_pct END AS revenue_share_pct,
    -- CEDIDAS: intacto, sobre calc.price. Ver cabecera.
    CASE WHEN calc.flow_type = 'licensed' AND calc.revenue_share_pct IS NOT NULL
         THEN ROUND(calc.price * calc.revenue_share_pct / 100, 4) END AS revenue_share_amount,
    CASE WHEN calc.flow_type = 'licensed' AND COALESCE(calc.reimburses_consumption, false)
         THEN calc.consumption_price END AS consumption_reimb,
    CASE
      WHEN calc.flow_type = 'own' AND calc.cost_available AND calc.commission_pct IS NOT NULL
        THEN ROUND(calc.ingreso_neto - calc.cost - (calc.commission_basis * calc.commission_pct / 100), 4)
      WHEN calc.flow_type = 'licensed' AND calc.cost_available AND calc.revenue_share_pct IS NOT NULL
        THEN ROUND(
               (calc.price * calc.revenue_share_pct / 100)
               + (CASE WHEN COALESCE(calc.reimburses_consumption, false)
                       THEN COALESCE(calc.consumption_price, 0) ELSE 0 END)
               - calc.cost, 4)
    END AS net_margin,
    CASE
      WHEN calc.flow_type = 'own' AND calc.cost_available AND calc.commission_pct IS NOT NULL AND calc.ingreso_neto > 0
        THEN ROUND((calc.ingreso_neto - calc.cost - (calc.commission_basis * calc.commission_pct / 100)) / calc.ingreso_neto * 100, 2)
    END AS net_margin_pct,
    calc.target_food_cost_pct,
    CASE
      WHEN calc.flow_type = 'licensed'       THEN 'n_a'
      WHEN NOT calc.cost_available           THEN 'no_cost'
      WHEN calc.target_food_cost_pct IS NULL THEN 'no_target'
      WHEN calc.ingreso_neto <= 0            THEN 'no_cost'
      WHEN (calc.food_cost / calc.ingreso_neto * 100) <= calc.target_food_cost_pct
           THEN 'under'
      ELSE 'over'
    END AS food_cost_status,
    CASE WHEN calc.flow_type = 'own' AND calc.cost_available AND calc.ingreso_neto > 0
         THEN ROUND(calc.cost / calc.ingreso_neto * 100, 2) END AS plate_cost_pct,
    calc.target_plate_cost_pct,
    CASE
      WHEN calc.flow_type = 'licensed'        THEN 'n_a'
      WHEN NOT calc.cost_available            THEN 'no_cost'
      WHEN calc.target_plate_cost_pct IS NULL THEN 'no_target'
      WHEN calc.ingreso_neto <= 0             THEN 'no_cost'
      WHEN (calc.cost / calc.ingreso_neto * 100) <= calc.target_plate_cost_pct
           THEN 'under'
      ELSE 'over'
    END AS plate_cost_status
  FROM calc
  ORDER BY calc.channel_name, calc.menu_item_name;
END;
$$;


--
-- Name: FUNCTION menu_item_economics(p_brand_id uuid, p_service_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.menu_item_economics(p_brand_id uuid, p_service_type text) IS 'INTERINO B79 (06/09/2026). El canal es LEFT JOIN porque `menu_item.channel_id` esta vacio en toda la base: el eje de canal vive en la capa de precios (`menu_item_channel_economics`), no en el producto. Mientras tanto `commission_pct` / `net_margin` / `net_margin_pct` salen NULL en marcas propias. La definitiva (fase C) es delegar en `menu_item_channel_economics`.';


--
-- Name: menu_item_link_health(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_item_link_health(p_account_id uuid, p_brand_id uuid DEFAULT NULL::uuid) RETURNS TABLE(menu_item_id uuid, item_name text, brand_id uuid, brand_name text, recipe_item_id uuid, recipe_name text, recipe_type text, cost numeric, price numeric, needs_review boolean, link_approved_at timestamp with time zone, status text, shared_with integer, recipe_line_count integer, sold_lines_90d integer, sold_eur_90d numeric, live_in_catalog boolean, sells_as_combo boolean, consumes_via_modifiers boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'menu_item_link_health: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with share_counts as (
    select m2.recipe_item_id, count(*)::int as n
    from menu_item m2
    where m2.account_id = p_account_id
      and m2.archived_at is null
      and m2.recipe_item_id is not null
    group by m2.recipe_item_id
  ),
  line_counts as (
    select rl.parent_item_id, count(*)::int as n
    from recipe_line rl
    where rl.account_id = p_account_id
    group by rl.parent_item_id
  ),
  ventas_90d as (
    select sl.menu_item_id as mi_id, count(*)::int as n,
           round(sum(sl.quantity * coalesce(sl.unit_price,0)), 2) as eur
    from sale_line sl
    join sale s on s.id = sl.sale_id
    where sl.account_id = p_account_id
      and sl.menu_item_id is not null
      and s.sold_at >= now() - interval '90 days'
    group by sl.menu_item_id
  ),
  vivos as (
    select distinct ecp.organization_product_id::text as matricula
    from external_catalog_product ecp
    where ecp.account_id = p_account_id and ecp.is_enabled
  ),
  combos as (
    -- SOLO 'combo_item'. Las hijas 'modifier' no llevan producto y no
    -- descuentan: excluir por "tiene hijas" a secas escondia fuga real.
    select distinct p.menu_item_id as mi_id
    from sale_line c
    join sale_line p on p.id = c.parent_sale_line_id
    where c.account_id = p_account_id
      and c.line_type = 'combo_item'
      and p.menu_item_id is not null
  ),
  via_modifiers as (
    -- El producto no tiene escandallo propio pero SI descuenta: sus
    -- modificadores son productos enteros con impacto 'bundle' confirmado.
    -- Es el caso de los combos Smash, cuyos componentes llegan de Last como
    -- 'modifier' en vez de 'combo_item'. Ponerles escandallo propio duplicaria
    -- el consumo, igual que en un combo. ~9 ms medidos.
    select distinct p.menu_item_id as mi_id
    from sale_line m
    join sale_line p on p.id = m.parent_sale_line_id
    join modifier_recipe_impact mri
         on mri.modifier_option_id = m.modifier_option_id
        and mri.status = 'confirmed'
        and mri.impact_type in ('add_item', 'bundle', 'replace_item')
    where m.account_id = p_account_id
      and m.line_type = 'modifier'
      and p.menu_item_id is not null
  )
  select
    mi.id, mi.name, mi.brand_id, b.name,
    ri.id, ri.name, ri.type,
    round(coalesce(ri.computed_cost, ri.fixed_cost), 4),
    mi.price,
    coalesce(ri.needs_review, false),
    mi.link_approved_at,
    case
      when mi.recipe_item_id is null                                   then 'roto_sin_escandallo'
      when ri.id is null                                               then 'roto_enlace'
      when coalesce(ri.computed_cost, ri.fixed_cost) is null           then 'roto_coste_null'
      when coalesce(ri.needs_review, false)                            then 'roto_needs_review'
      when coalesce(ri.computed_cost, ri.fixed_cost) < 0.50            then 'roto_coste_imposible'
      when mi.link_approved_at is null                                 then 'sin_aprobar'
      else 'aprobado'
    end as status,
    coalesce(sc.n, 0) as shared_with,
    coalesce(lc.n, 0) as recipe_line_count,
    coalesce(v.n, 0) as sold_lines_90d,
    coalesce(v.eur, 0)::numeric as sold_eur_90d,
    (vi.matricula is not null) as live_in_catalog,
    (cb.mi_id is not null) as sells_as_combo,
    (vm.mi_id is not null) as consumes_via_modifiers
  from menu_item mi
  left join recipe_item ri on ri.id = mi.recipe_item_id
  left join brand b on b.id = mi.brand_id
  left join share_counts sc on sc.recipe_item_id = mi.recipe_item_id
  left join line_counts lc on lc.parent_item_id = mi.recipe_item_id
  left join ventas_90d v on v.mi_id = mi.id
  left join vivos vi on vi.matricula = mi.external_id
  left join combos cb on cb.mi_id = mi.id
  left join via_modifiers vm on vm.mi_id = mi.id
  where mi.account_id = p_account_id
    and mi.archived_at is null
    and coalesce(mi.product_type, 'item') <> 'combo'
    and (ri.id is null or ri.type in ('dish', 'raw'))
    and (p_brand_id is null or mi.brand_id = p_brand_id)
  order by
    case
      when mi.recipe_item_id is null then 0
      when coalesce(ri.computed_cost, ri.fixed_cost) is null then 1
      when coalesce(ri.needs_review, false) then 2
      when coalesce(ri.computed_cost, ri.fixed_cost) < 0.50 then 3
      when mi.link_approved_at is null then 4
      else 5
    end,
    b.name, mi.name;
end;
$$;


--
-- Name: menu_item_shared_recipe_review(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_item_shared_recipe_review(p_account_id uuid) RETURNS TABLE(recipe_item_id uuid, recipe_name text, n_items integer, item_names text[], raw_ingredients text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'menu_item_shared_recipe_review: sin acceso';
  end if;

  return query
  with shared as (
    select mi.recipe_item_id, ri.name as recipe_name,
           count(distinct mi.id) as n_items,
           array_agg(distinct mi.name) as item_names
    from menu_item mi
    join recipe_item ri on ri.id = mi.recipe_item_id
    where mi.account_id = p_account_id and mi.archived_at is null
    group by mi.recipe_item_id, ri.name
    having count(distinct mi.id) > 1
  )
  select s.recipe_item_id, s.recipe_name, s.n_items::int, s.item_names,
         (select array_agg(distinct ri2.name)
            from public.explode_recipe_to_raws(s.recipe_item_id, 1) e
            join recipe_item ri2 on ri2.id = e.raw_item_id)
  from shared s
  order by s.n_items desc;
end;
$$;


--
-- Name: menu_item_units_sold(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_item_units_sold(p_brand_id uuid, p_from timestamp with time zone DEFAULT (now() - '90 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS TABLE(menu_item_id uuid, units_sold numeric, revenue numeric, lines_count bigint, first_sold_at timestamp with time zone, last_sold_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
BEGIN
  SELECT b.account_id INTO v_account_id FROM brand b WHERE b.id = p_brand_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'Marca % no encontrada', p_brand_id;
  END IF;
  IF NOT (current_user_is_admin()
          OR current_user_is_admin_or_manager_of(v_account_id)) THEN
    RAISE EXCEPTION 'Sin permiso para las ventas de la marca %', p_brand_id;
  END IF;

  RETURN QUERY
  SELECT
    sl.menu_item_id                          AS menu_item_id,
    SUM(sl.quantity)                         AS units_sold,
    -- revenue = total real de las líneas (line_total), NO quantity×unit_price
    ROUND(SUM(COALESCE(sl.line_total, sl.unit_price * sl.quantity)), 2) AS revenue,
    count(*)                                 AS lines_count,
    MIN(s.sold_at)                           AS first_sold_at,
    MAX(s.sold_at)                           AS last_sold_at
  FROM sale_line sl
  JOIN sale s ON s.id = sl.sale_id
  JOIN menu_item mi ON mi.id = sl.menu_item_id
  WHERE s.account_id = v_account_id
    AND mi.brand_id  = p_brand_id
    AND mi.archived_at IS NULL
    AND sl.menu_item_id IS NOT NULL
    AND s.is_active = true
    AND s.sold_at >= p_from
    AND s.sold_at <  p_to
  GROUP BY sl.menu_item_id;
END;
$$;


--
-- Name: menu_item_vendible_en_alguna_parte(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.menu_item_vendible_en_alguna_parte(p_menu_item_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select not exists (
    select 1
      from menu_item mi
      join product_availability pa
        on pa.account_id = mi.account_id
       and pa.is_available = false
       and (pa.available_until is null or pa.available_until > now())
       and ( (mi.external_id    is not null and pa.external_id    = mi.external_id)
          or (mi.recipe_item_id is not null and pa.recipe_item_id = mi.recipe_item_id) )
     where mi.id = p_menu_item_id
       and ( pa.location_id is null
          or not exists (
               select 1
                 from brand_location_availability bla
                where bla.brand_id = mi.brand_id
                  and bla.is_active = true
                  and not exists (
                        select 1
                          from product_availability pa2
                         where pa2.account_id = mi.account_id
                           and pa2.is_available = false
                           and (pa2.available_until is null or pa2.available_until > now())
                           and (pa2.location_id = bla.location_id or pa2.location_id is null)
                           and ( (mi.external_id    is not null and pa2.external_id    = mi.external_id)
                              or (mi.recipe_item_id is not null and pa2.recipe_item_id = mi.recipe_item_id) )
                      )
             ) )
  );
$$;


--
-- Name: FUNCTION menu_item_vendible_en_alguna_parte(p_menu_item_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.menu_item_vendible_en_alguna_parte(p_menu_item_id uuid) IS 'Regla de NAVEGACION de la tienda propia (el cliente aun no ha elegido local): un producto es vendible si lo esta en ALGUN local activo de su marca. NO vale para el pedido, que si conoce el local y necesita la regla POR LOCAL (paso 2). Unico hogar de esta regla; copiada de shop_brand_menu_by_slug el 29/08/2026.';


--
-- Name: metrica_direcciones_de_reparto(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.metrica_direcciones_de_reparto(p_account_id uuid, p_dias integer DEFAULT 30) RETURNS TABLE(reparto text, marca text, pasarela text, canal text, pedidos bigint, sin_direccion bigint, sin_direccion_pct numeric, con_coordenadas bigint, coords_en_delivery bigint, coords_en_customer bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- service_role (informes, cron) pasa; un usuario tiene que ser de la cuenta.
  if current_setting('request.jwt.claims', true) is not null
     and not public.belongs_to_account(p_account_id) then
    raise exception 'metrica_direcciones_de_reparto: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with base as (
    select
      -- EJE 1, quien reparte: lo que dice «Quién reparte» HOY para esa marca
      -- en ese canal y local (R02). Antes, el interruptor por marca.
      case when (select r.delivery_by
                   from public.resolve_delivery_by(s.account_id, s.brand_id, sc.slug, s.location_id) r) = 'own'
           then 'nosotros' else 'plataforma' end as reparto,
      -- EJE 2, de quien es la marca. Nada que ver con el anterior.
      case b.ownership_type
           when 'own'      then 'propia'
           when 'licensed' then 'licenciada'
           else coalesce(b.ownership_type, 'sin marca')
      end as marca,
      coalesce(s.source, '(sin source)') as pasarela,
      coalesce(nullif(btrim(s.external_channel_text), ''), '(sin canal)') as canal,
      coalesce(btrim(s.delivery_address), '') = '' as sin_dir,
      case when left(btrim(coalesce(s.raw_tab, '')), 1) = '{'
           then nullif(s.raw_tab::jsonb->'delivery'->>'latitude', '') end as lat_delivery,
      case when left(btrim(coalesce(s.raw_tab, '')), 1) = '{'
           then nullif(s.raw_tab::jsonb->'customer'->>'latitude', '') end as lat_customer
    from public.sale s
    left join public.brand b on b.id = s.brand_id and b.account_id = s.account_id
    left join public.sales_channel sc on sc.id = s.channel_id and sc.account_id = s.account_id
    where s.account_id = p_account_id
      and s.service_type = 'own_delivery'
      and s.created_at > now() - make_interval(days => greatest(1, p_dias))
  )
  select
    b.reparto,
    b.marca,
    b.pasarela,
    b.canal,
    count(*),
    count(*) filter (where b.sin_dir),
    round(100.0 * count(*) filter (where b.sin_dir) / nullif(count(*), 0), 1),
    count(*) filter (where b.sin_dir and coalesce(b.lat_delivery, b.lat_customer) is not null),
    count(*) filter (where b.lat_delivery is not null),
    count(*) filter (where b.lat_customer is not null)
  from base b
  group by b.reparto, b.marca, b.pasarela, b.canal
  -- Lo que repartimos primero; dentro, lo que mas falla. El criterio ORDENA.
  order by case when b.reparto = 'nosotros' then 0 else 1 end,
           count(*) filter (where b.sin_dir) desc,
           count(*) desc;
end;
$$;


--
-- Name: FUNCTION metrica_direcciones_de_reparto(p_account_id uuid, p_dias integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.metrica_direcciones_de_reparto(p_account_id uuid, p_dias integer) IS 'Direcciones que faltan en pedidos marcados own_delivery, por pasarela y canal. DOS EJES INDEPENDIENTES: `reparto` (nosotros / plataforma, de brand.own_delivery_enabled) y `marca` (propia / licenciada, de brand.ownership_type). Smash Brothers y Lovers son marcas PROPIAS que reparte la plataforma: no confundir los ejes. Ojo: own_delivery_enabled es NULL en 16 de 18 marcas y NULL se lee como "nosotros", asi que las filas reparto=nosotros + marca=licenciada son una contradiccion conocida (Dos Coyotes); la fuente buena es channel_delivery_policy.';


--
-- Name: migrate_brands_and_map(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_brands_and_map(p_source uuid, p_dest uuid, p_run boolean DEFAULT false) RETURNS TABLE(paso text, n bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_brandmap_existing int;
begin
  -- Mapa marca_vieja -> marca_destino (nueva o reutilizada por slug)
  create temp table _map_brand (old_id uuid primary key, new_id uuid, reused boolean) on commit drop;
  insert into _map_brand(old_id, new_id, reused)
  select b.id,
         coalesce(d.id, gen_random_uuid()),
         (d.id is not null)
  from brand b
  left join brand d on d.account_id = p_dest and d.slug = b.slug
  where b.account_id = p_source;
  -- external_brand_map del origen que apunta a tiendas YA mapeadas en el destino
  -- CONVERGIDO: lee external_location_map (antes lastapp_location_map). Ambos
  -- external_location_id son text -> comparacion directa, sin ::text.
  create temp table _src_map on commit drop as
  select m.*
  from external_brand_map m
  where m.account_id = p_source
    and exists (
      select 1 from external_location_map lm
      where lm.account_id = p_dest
        and lm.external_location_id = m.external_location_id
    );
  if not p_run then
    return query
      select 'marcas_total',      count(*)::bigint from _map_brand union all
      select 'marcas_nuevas',     count(*)::bigint from _map_brand where not reused union all
      select 'marcas_reutilizadas',count(*)::bigint from _map_brand where reused union all
      select 'brand_map_a_migrar',count(*)::bigint from _src_map;
    return;
  end if;
  -- 1) Crear las marcas NUEVAS (las reutilizadas ya existen, no se tocan)
  insert into brand (id, account_id, name, slug, ownership_type, color, logo_url,
                     notes, is_active, created_at, updated_at)
  select mb.new_id, p_dest, b.name, b.slug, b.ownership_type, b.color, b.logo_url,
         b.notes, b.is_active, now(), now()
  from brand b
  join _map_brand mb on mb.old_id = b.id
  where mb.reused = false;
  -- 2) Copiar external_brand_map (brand_id re-apuntado; guarda anti-duplicado)
  select count(*) into v_brandmap_existing from external_brand_map where account_id = p_dest;
  insert into external_brand_map (account_id, source, external_location_id, external_brand_id,
                                  brand_id, is_ignored, created_at, updated_at)
  select p_dest, s.source, s.external_location_id, s.external_brand_id,
         (select mb.new_id from _map_brand mb where mb.old_id = s.brand_id),
         s.is_ignored, now(), now()
  from _src_map s
  where not exists (
    select 1 from external_brand_map e
    where e.account_id = p_dest
      and e.source = s.source
      and e.external_location_id = s.external_location_id
      and e.external_brand_id = s.external_brand_id
  );
  return query
    select 'marcas_en_destino',   count(*)::bigint from brand where account_id = p_dest union all
    select 'brand_map_en_destino',count(*)::bigint from external_brand_map where account_id = p_dest;
end;
$$;


--
-- Name: migrate_kitchen_core(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_kitchen_core(p_source uuid, p_dest uuid, p_run boolean DEFAULT false) RETURNS TABLE(paso text, n bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing int;
begin
  select count(*) into v_existing from recipe_item where account_id = p_dest;
  if v_existing > 0 and p_run then
    raise exception 'DESTINO NO VACÍO: % ya tiene % recipe_item. Aborto.', p_dest, v_existing;
  end if;

  -- NÚCLEO: platos con escandallo + ingredientes/subrecetas usados
  create temp table _nucleo on commit drop as
  select distinct id from (
    select ri.id from recipe_item ri
      join recipe_line rl on rl.parent_item_id = ri.id
     where ri.account_id = p_source and ri.type = 'dish'
    union
    select rl.child_item_id from recipe_line rl where rl.account_id = p_source
  ) x;

  create temp table _map_family   (old_id uuid primary key, new_id uuid default gen_random_uuid()) on commit drop;
  create temp table _map_supplier (old_id uuid primary key, new_id uuid default gen_random_uuid()) on commit drop;
  create temp table _map_item     (old_id uuid primary key, new_id uuid default gen_random_uuid()) on commit drop;

  insert into _map_family(old_id)
    select distinct family_id from recipe_item
     where id in (select id from _nucleo) and family_id is not null;
  insert into _map_supplier(old_id)
    select distinct supplier_id from article_supplier
     where recipe_item_id in (select id from _nucleo);
  insert into _map_item(old_id) select id from _nucleo;

  if not p_run then
    return query
      select 'familias',     count(*)::bigint from _map_family   union all
      select 'proveedores',  count(*)::bigint from _map_supplier union all
      select 'items',        count(*)::bigint from _map_item     union all
      select 'lineas',       count(*)::bigint from recipe_line where parent_item_id in (select old_id from _map_item) union all
      select 'article_supp', count(*)::bigint from article_supplier where recipe_item_id in (select old_id from _map_item) union all
      select 'conversiones', count(*)::bigint from recipe_item_unit_conversion where item_id in (select old_id from _map_item);
    return;
  end if;

  -- ════════ EJECUCIÓN: triggers OFF durante toda la copia ════════
  set local session_replication_role = replica;

  -- 1) FAMILIAS
  insert into recipe_family (id, account_id, template_id, name, color, icon, position,
                             is_active, created_at, scope, parent_family_id, accounting_category, code)
  select m.new_id, p_dest, f.template_id, f.name, f.color, f.icon, f.position,
         f.is_active, now(), f.scope,
         (select mp.new_id from _map_family mp where mp.old_id = f.parent_family_id),
         f.accounting_category, f.code
    from recipe_family f join _map_family m on m.old_id = f.id;

  -- 2) PROVEEDORES. C01b: ni email, ni teléfono, ni dirección en supplier;
  -- se clonan los datos fiscales estructurados, los contactos y la dirección
  -- por confirmar (propuesta pendiente), que es donde viven ahora.
  insert into supplier (id, account_id, name, tax_id, notes,
                        is_active, created_at, health_registry_no,
                        legal_name, tax_id_type, country_code, entity_kind,
                        fiscal_street, fiscal_postal_code, fiscal_city, fiscal_province)
  select m.new_id, p_dest, s.name, s.tax_id, s.notes,
         s.is_active, now(), s.health_registry_no,
         s.legal_name, s.tax_id_type, s.country_code, s.entity_kind,
         s.fiscal_street, s.fiscal_postal_code, s.fiscal_city, s.fiscal_province
    from supplier s join _map_supplier m on m.old_id = s.id;

  insert into supplier_contact (account_id, supplier_id, name, role, phone, email, is_primary, notes, created_at, created_by_name)
  select p_dest, m.new_id, c.name, c.role, c.phone, c.email, c.is_primary, c.notes, now(), 'Clonado de la plantilla'
    from supplier_contact c join _map_supplier m on m.old_id = c.supplier_id;

  insert into supplier_proposal (account_id, supplier_id, field, value, source, source_label)
  select p_dest, m.new_id, p.field, p.value, p.source, p.source_label
    from supplier_proposal p join _map_supplier m on m.old_id = p.supplier_id
   where p.status = 'pending' and p.field = 'fiscal_address';

  -- 3) RECIPE_ITEM — computed_cost/cost_updated_at SÍ se copian (nace con coste correcto)
  insert into recipe_item (
    id, account_id, type, name, alt_name, code, base_unit_id, cost_strategy, fixed_cost,
    computed_cost, cost_updated_at, notes, is_active, archived_at, created_at, updated_at,
    created_by, created_by_name, cost_window_days, indirect_cost_pct, prep_time_minutes,
    cook_time_minutes, procedure_text, plating_notes, kitchen_photo_url, yield_portions,
    conservation_type, service_temp_c, source, ai_confidence, needs_review, family_id,
    is_stockable, completeness, chef_notes, prep_notes, finishing_notes, steps_auto_split,
    season_start, season_end, recyclable_packaging, supplier_codes, shelf_life_days,
    label_override, label_simplified, category, supplier_name, supplier_url,
    last_purchase_date, current_stock, current_stock_unit_id, review_notes, folvy_code,
    external_codes, alt_names, purchase_unit_id, stock_unit_id, is_purchasable, is_sellable,
    nutrition, media, vat_category_id, vat_category_source, default_waste_pct, origin,
    template_code, template_version, menu_tags, is_operational_critical, operational_min_qty
  )
  select
    mi.new_id, p_dest, ri.type, ri.name, ri.alt_name, ri.code, ri.base_unit_id, ri.cost_strategy, ri.fixed_cost,
    ri.computed_cost, ri.cost_updated_at, ri.notes, ri.is_active, ri.archived_at, now(), now(),
    ri.created_by, ri.created_by_name, ri.cost_window_days, ri.indirect_cost_pct, ri.prep_time_minutes,
    ri.cook_time_minutes, ri.procedure_text, ri.plating_notes, ri.kitchen_photo_url, ri.yield_portions,
    ri.conservation_type, ri.service_temp_c, ri.source, ri.ai_confidence, ri.needs_review,
    (select mf.new_id from _map_family mf where mf.old_id = ri.family_id),
    ri.is_stockable, ri.completeness, ri.chef_notes, ri.prep_notes, ri.finishing_notes, ri.steps_auto_split,
    ri.season_start, ri.season_end, ri.recyclable_packaging, ri.supplier_codes, ri.shelf_life_days,
    ri.label_override, ri.label_simplified, ri.category, ri.supplier_name, ri.supplier_url,
    ri.last_purchase_date, ri.current_stock, ri.current_stock_unit_id, ri.review_notes, ri.folvy_code,
    ri.external_codes, ri.alt_names, ri.purchase_unit_id, ri.stock_unit_id, ri.is_purchasable, ri.is_sellable,
    ri.nutrition, ri.media, ri.vat_category_id, ri.vat_category_source, ri.default_waste_pct, ri.origin,
    ri.template_code, ri.template_version, ri.menu_tags, ri.is_operational_critical, ri.operational_min_qty
  from recipe_item ri join _map_item mi on mi.old_id = ri.id;

  -- 4) RECIPE_LINE
  insert into recipe_line (id, account_id, parent_item_id, child_item_id, quantity_net,
                           quantity_gross, unit_id, cut_type_id, comment, position, created_at, updated_at)
  select gen_random_uuid(), p_dest, mp.new_id, mc.new_id, rl.quantity_net, rl.quantity_gross,
         rl.unit_id, rl.cut_type_id, rl.comment, rl.position, now(), now()
    from recipe_line rl
    join _map_item mp on mp.old_id = rl.parent_item_id
    join _map_item mc on mc.old_id = rl.child_item_id
   where rl.account_id = p_source;

  -- 5) ARTICLE_SUPPLIER (purchase_format_id NO migra -> null; formatos son Fase posterior)
  insert into article_supplier (id, account_id, recipe_item_id, supplier_id, supplier_code,
                                last_price, is_preferred, is_active, created_at, updated_at,
                                purchase_format_id, supplier_item_name)
  select gen_random_uuid(), p_dest, mi.new_id, ms.new_id, as_.supplier_code,
         as_.last_price, as_.is_preferred, as_.is_active, now(), now(),
         null, as_.supplier_item_name
    from article_supplier as_
    join _map_item     mi on mi.old_id = as_.recipe_item_id
    join _map_supplier ms on ms.old_id = as_.supplier_id;

  -- 6) CONVERSIONES (0 filas hoy, inofensivo)
  insert into recipe_item_unit_conversion (id, account_id, item_id, from_unit_id, qty_in_base,
                                           source, ai_confidence, needs_review, is_active,
                                           archived_at, created_at, updated_at, created_by, created_by_name)
  select gen_random_uuid(), p_dest, mi.new_id, c.from_unit_id, c.qty_in_base,
         c.source, c.ai_confidence, c.needs_review, c.is_active,
         c.archived_at, now(), now(), c.created_by, c.created_by_name
    from recipe_item_unit_conversion c
    join _map_item mi on mi.old_id = c.item_id;

  set local session_replication_role = default;

  return query
    select 'familias',     count(*)::bigint from recipe_family where account_id = p_dest union all
    select 'proveedores',  count(*)::bigint from supplier where account_id = p_dest union all
    select 'items',        count(*)::bigint from recipe_item where account_id = p_dest union all
    select 'lineas',       count(*)::bigint from recipe_line where account_id = p_dest union all
    select 'article_supp', count(*)::bigint from article_supplier where account_id = p_dest union all
    select 'conversiones', count(*)::bigint from recipe_item_unit_conversion where account_id = p_dest;
end;
$$;


--
-- Name: migrate_locations_and_staff(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_locations_and_staff(p_source uuid, p_dest uuid, p_run boolean DEFAULT false) RETURNS TABLE(paso text, n bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing int;
begin
  select count(*) into v_existing from locations where account_id = p_dest;
  if v_existing > 0 and p_run then
    raise exception 'DESTINO YA TIENE % locales. Aborto para no duplicar.', v_existing;
  end if;

  create temp table _map_loc (old_id uuid primary key, new_id uuid default gen_random_uuid()) on commit drop;
  insert into _map_loc(old_id) select id from locations where account_id = p_source;

  create temp table _emp on commit drop as
  select e.* from employees e
  where e.location_id in (select old_id from _map_loc);

  if not p_run then
    return query
      select 'locales',  count(*)::bigint from _map_loc union all
      select 'personal', count(*)::bigint from _emp;
    return;
  end if;

  set local session_replication_role = replica;

  -- 1) LOCALES
  insert into locations (id, account_id, name, address, phone, active, lat, lng,
                         created_at, updated_at, hours_balance_close_day,
                         hours_balance_sync_with_gestoria, is_billable)
  select m.new_id, p_dest, l.name, l.address, l.phone, l.active, l.lat, l.lng,
         now(), now(), l.hours_balance_close_day,
         l.hours_balance_sync_with_gestoria, l.is_billable
    from locations l join _map_loc m on m.old_id = l.id;

  -- 2) PERSONAL — pin y username a NULL (van en el frente de accesos)
  insert into employees (
    id, name, dni, phone, email, photo, position, department, contract_type,
    start_date, end_date, salary, weekly_hours, schedule, active, notes, pin,
    location_id, assigned_locations, weekly_schedule, availability,
    created_at, updated_at, contracted_hours_week, shift_code, shift_period,
    rest_pattern, initial_hours_balance, show_hours_balance, termination_type,
    termination_reason, termination_communicated_to_gestoria, trial_period_days,
    birth_date, username
  )
  select
    gen_random_uuid(), e.name, e.dni, e.phone, e.email, e.photo, e.position, e.department, e.contract_type,
    e.start_date, e.end_date, e.salary, e.weekly_hours, e.schedule, e.active, e.notes, null,
    (select new_id from _map_loc where old_id = e.location_id),
    coalesce(
      (select array_agg(coalesce(m.new_id, a.old_a))
         from unnest(e.assigned_locations) as a(old_a)
         left join _map_loc m on m.old_id = a.old_a),
      array[]::uuid[]
    ),
    e.weekly_schedule, e.availability,
    now(), now(), e.contracted_hours_week, e.shift_code, e.shift_period,
    e.rest_pattern, e.initial_hours_balance, e.show_hours_balance, e.termination_type,
    e.termination_reason, e.termination_communicated_to_gestoria, e.trial_period_days,
    e.birth_date, null
  from _emp e;

  set local session_replication_role = default;

  return query
    select 'locales',  count(*)::bigint from locations where account_id = p_dest union all
    select 'personal', count(*)::bigint from employees
      where location_id in (select new_id from _map_loc);
end;
$$;


--
-- Name: migrate_supplier_articles(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_supplier_articles(p_source uuid, p_target uuid, p_mode text DEFAULT 'fill'::text) RETURNS TABLE(moved integer, merged integer, affected_item_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_acc uuid; v_moved int := 0; v_merged int := 0; v_affected uuid[]; r record;
BEGIN
  SELECT s1.account_id INTO v_acc
  FROM supplier s1 JOIN supplier s2 ON s2.id = p_target
  WHERE s1.id = p_source AND s1.account_id = s2.account_id;
  IF v_acc IS NULL THEN RAISE EXCEPTION 'Proveedores inválidos o de cuentas distintas'; END IF;
  IF NOT (v_acc = ANY (current_user_account_ids())) THEN RAISE EXCEPTION 'Sin permiso sobre esta cuenta'; END IF;
  IF p_source = p_target THEN RAISE EXCEPTION 'Origen y destino no pueden ser el mismo proveedor'; END IF;
  IF p_mode NOT IN ('fill','source_wins','keep_target') THEN RAISE EXCEPTION 'Modo no válido: %', p_mode; END IF;

  SELECT COALESCE(array_agg(DISTINCT recipe_item_id), '{}') INTO v_affected
  FROM article_supplier WHERE supplier_id = p_source;

  FOR r IN
    SELECT src.id AS src_id, dst.id AS dst_id,
           src.last_price AS s_price, src.supplier_code AS s_code, src.purchase_format_id AS s_fmt, src.supplier_item_name AS s_name,
           dst.last_price AS d_price, dst.supplier_code AS d_code, dst.purchase_format_id AS d_fmt, dst.supplier_item_name AS d_name
    FROM article_supplier src
    JOIN article_supplier dst ON dst.supplier_id = p_target AND dst.recipe_item_id = src.recipe_item_id
      AND dst.supplier_code IS NOT DISTINCT FROM src.supplier_code
    WHERE src.supplier_id = p_source
  LOOP
    IF p_mode = 'fill' THEN
      UPDATE article_supplier SET
        last_price         = COALESCE(r.d_price, r.s_price),
        supplier_code      = COALESCE(NULLIF(r.d_code, ''), r.s_code),
        purchase_format_id = COALESCE(r.d_fmt, r.s_fmt),
        supplier_item_name = COALESCE(NULLIF(r.d_name, ''), r.s_name),
        updated_at = now()
      WHERE id = r.dst_id;
    ELSIF p_mode = 'source_wins' THEN
      UPDATE article_supplier SET
        last_price = r.s_price, supplier_code = r.s_code, purchase_format_id = r.s_fmt,
        supplier_item_name = r.s_name, updated_at = now()
      WHERE id = r.dst_id;
    END IF;
    DELETE FROM article_supplier WHERE id = r.src_id;
    v_merged := v_merged + 1;
  END LOOP;

  UPDATE article_supplier SET supplier_id = p_target, updated_at = now()
  WHERE supplier_id = p_source;
  GET DIAGNOSTICS v_moved = ROW_COUNT;

  RETURN QUERY SELECT v_moved, v_merged, v_affected;
END; $$;


--
-- Name: mirror_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_state(p_account uuid, p_item uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item menu_item%rowtype;
  v_orig menu_item%rowtype;
  v_mir  menu_item%rowtype;
begin
  if not (p_account = any(current_user_account_ids())) then raise exception 'forbidden'; end if;

  select * into v_item from menu_item where id = p_item and account_id = p_account;
  if v_item.id is null then return jsonb_build_object('role', 'none'); end if;

  if v_item.mirror_of_item_id is not null then
    -- p_item ES el espejo: su original es mirror_of_item_id.
    select * into v_orig from menu_item where id = v_item.mirror_of_item_id and account_id = p_account;
    if v_orig.id is null then return jsonb_build_object('role', 'none'); end if;
    return jsonb_build_object(
      'role', 'mirror',
      'originalId', v_orig.id, 'originalName', v_orig.name, 'originalAvailable', coalesce(v_orig.is_available, false),
      'mirrorId', v_item.id, 'mirrorName', v_item.name, 'mirrorAvailable', coalesce(v_item.is_available, false),
      'usingMirror', coalesce(v_item.is_available, false)
    );
  end if;

  -- p_item es (posible) original: buscar su espejo.
  select * into v_mir from menu_item where mirror_of_item_id = p_item and account_id = p_account limit 1;
  if v_mir.id is null then return jsonb_build_object('role', 'none'); end if;

  return jsonb_build_object(
    'role', 'original',
    'originalId', v_item.id, 'originalName', v_item.name, 'originalAvailable', coalesce(v_item.is_available, false),
    'mirrorId', v_mir.id, 'mirrorName', v_mir.name, 'mirrorAvailable', coalesce(v_mir.is_available, false),
    'usingMirror', coalesce(v_mir.is_available, false)
  );
end;
$$;


--
-- Name: mis_avisos_olvido(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mis_avisos_olvido() RETURNS TABLE(id uuid, entrada_at timestamp with time zone, fin_turno timestamp with time zone, local_nombre text, respuesta text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select l.id, l.entrada_at, l.fin_turno, coalesce(loc.name, ''), l.respuesta
    from public.clockout_reminder_log l
    left join public.locations loc on loc.id = l.location_id
    join public.current_employee_and_account() yo on yo.employee_id = l.employee_id and yo.account_id = l.account_id
   where l.entrada_at is not null and l.entrada_at > now() - interval '14 days'
     and exists (select 1 from public.clock_entries ce where ce.id = l.clock_entry_id and not ce.voided)
     and l.correction_request_id is null
     and (l.respuesta is null or l.respuesta = 'otra_hora' or (l.respuesta = 'sigo' and l.entrada_at < now() - interval '12 hours'))
     and not exists (select 1 from public.clock_entries n
                      where n.employee_id = l.employee_id and not n.voided
                        and n.id <> l.clock_entry_id and n.datetime > l.entrada_at)
     and not exists (select 1 from public.clock_correction_request r
                      where r.employee_id = l.employee_id and r.kind = 'add' and r.proposed_type = 'salida'
                        and r.status in ('pending', 'approved') and r.proposed_datetime > l.entrada_at)
   order by l.entrada_at desc;
$$;


--
-- Name: mis_empresas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mis_empresas() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'account_id', a.id,
      'nombre', a.name,
      'slug', a.slug,
      'logo', a.logo_url,
      'rol', up.role,
      'solo_sumied', a.product_brand is not null,
      'activa', a.id = public._cuenta_activa(),
      'sociedades', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'id', c.id,
                 'nombre', coalesce(nullif(c.trade_name, ''), c.legal_name),
                 'razon_social', c.legal_name,
                 'color', c.color,
                 'logo', c.logo_path)
               order by coalesce(nullif(c.trade_name, ''), c.legal_name))
          from public.company c
         where c.account_id = a.id and coalesce(c.is_active, true)), '[]'::jsonb))
    order by a.name), '[]'::jsonb)
  from public.user_profiles up
  join public.accounts a on a.id = up.account_id
  where up.user_id = auth.uid() and up.active and up.account_id is not null
$$;


--
-- Name: FUNCTION mis_empresas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mis_empresas() IS 'DM1 (30/10/2026). Las cuentas de quien llama, con su rol, si es solo Sumied, si está abierta y sus sociedades. Para el selector de empresa.';


--
-- Name: modificadores_cobertura_de_codigos(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.modificadores_cobertura_de_codigos(p_account_id uuid, p_catalog_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH refs AS (
    SELECT DISTINCT sl.external_product_id ref
      FROM public.sale_line sl
      JOIN public.sale s          ON s.id = sl.sale_id
      LEFT JOIN public.sale_line padre ON padre.id = sl.parent_sale_line_id
      LEFT JOIN public.menu_item mi    ON mi.id = padre.menu_item_id
      JOIN public.brand b         ON b.id = COALESCE(mi.brand_id, s.brand_id)
     WHERE sl.account_id = p_account_id
       AND sl.line_type  = 'modifier'
       AND sl.external_source = 'lastapp'
       AND sl.external_product_id IS NOT NULL
       AND b.ownership_type = 'licensed'
       AND COALESCE(s.status,'') <> 'cancelled'
       AND COALESCE(s.order_status,'') NOT IN ('cancelled','rejected')
       AND COALESCE(s.is_active, true)
  ),
  cat AS (SELECT DISTINCT unnest(COALESCE(p_catalog_ids, '{}'::text[])) id)
  SELECT jsonb_build_object(
    'refs_en_pedidos_cedidos', (SELECT count(*) FROM refs),
    'en_el_catalogo',          (SELECT count(*) FROM refs WHERE ref IN (SELECT id FROM cat)),
    'fuera_del_catalogo',      (SELECT count(*) FROM refs WHERE ref NOT IN (SELECT id FROM cat)),
    'ids_en_el_catalogo',      (SELECT count(*) FROM cat),
    'ejemplos_fuera', (
      SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) FROM (
        SELECT jsonb_build_object(
                 'ref', r.ref,
                 'visto_como', (SELECT string_agg(DISTINCT sl2.product_name, ' | ')
                                  FROM public.sale_line sl2
                                 WHERE sl2.account_id = p_account_id
                                   AND sl2.external_product_id = r.ref
                                   AND sl2.line_type = 'modifier'),
                 'ventas', (SELECT count(*) FROM public.sale_line sl3
                             WHERE sl3.account_id = p_account_id
                               AND sl3.external_product_id = r.ref
                               AND sl3.line_type = 'modifier')
               ) x
          FROM refs r
         WHERE r.ref NOT IN (SELECT id FROM cat)
         LIMIT 20
      ) q
    )
  );
$$;


--
-- Name: modificadores_lista_preguntas(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.modificadores_lista_preguntas(p_account_id uuid, p_dias integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hoy date; v_dias integer; v_desde date; v_out jsonb;
BEGIN
  IF NOT public.belongs_to_account(p_account_id) THEN
    RAISE EXCEPTION 'modificadores_lista_preguntas: sin acceso a la cuenta %', p_account_id;
  END IF;
  v_dias  := GREATEST(LEAST(COALESCE(p_dias, 30), 365), 1);
  v_hoy   := (now() AT TIME ZONE 'Europe/Madrid')::date;
  v_desde := v_hoy - v_dias;

  WITH pregunta AS (
    SELECT g.id, g.brand_id, g.name, g.group_type, g.min_selections, g.max_selections,
           COALESCE(g.allow_repetition,false) AS repetible,
           COALESCE(g.is_active,true) AS activa,
           COALESCE(g.external_source,'propia') AS origen,
           -- CEDIDA SE MIDE POR LA MARCA, no por el origen de la fila.
           (COALESCE(b.ownership_type,'own') <> 'own') AS cedida,
           lower(btrim(COALESCE(g.name,''))) AS nombre_norm
      FROM public.modifier_group g
      LEFT JOIN public.brand b ON b.id = g.brand_id
     WHERE g.account_id = p_account_id
  ),
  opcion AS (
    SELECT o.id, o.modifier_group_id, COALESCE(o.price_impact,0) AS precio,
           -- UNA OPCION RETIRADA NO SE VENDE, asi que no hay nada que decidir
           -- en ella. Todo lo que empuja a trabajar cuenta solo las activas;
           -- el total viaja al lado, de contexto. (Julio, 12/09 12:10.)
           COALESCE(o.is_active,true) AS activa,
           -- DECIDIDA = TIENE FICHA QUE DESCUENTA ALGO. Incluido `none` («no
           -- lleva nada»), que es una respuesta y no un hueco. Hasta hoy aqui
           -- ponia solo «tiene impacto confirmado», y por eso el contador dio
           -- por decididas dos respuestas con ficha y SIN CANTIDAD, que
           -- descuentan cero. Que cuenta como completo lo dice la funcion del
           -- candado, en un solo sitio, el mismo que usan las tres puertas de
           -- escritura y la propia tabla.
           EXISTS (SELECT 1 FROM public.modifier_recipe_impact i
                    WHERE i.modifier_option_id = o.id AND i.account_id = p_account_id
                      AND i.status = 'confirmed'
                      AND public._impacto_completo(i.impact_type,
                                                   i.target_recipe_item_id,
                                                   i.quantity)) AS decidida
      FROM public.modifier_option o WHERE o.account_id = p_account_id
  ),
  plato_activo AS (
    -- `archived_at` TAMBIEN. Hay 2 platos con `is_active = true` y fecha de
    -- archivo: contarlos daba 595 donde Julio cuenta 593. Ninguno de los dos
    -- lleva preguntas, asi que esto solo mueve el denominador.
    SELECT mi.id FROM public.menu_item mi
     WHERE mi.account_id = p_account_id AND COALESCE(mi.is_active,true)
       AND mi.archived_at IS NULL
  ),
  puesta AS (
    SELECT DISTINCT ga.modifier_group_id, ga.menu_item_id
      FROM public.modifier_group_assignment ga
      JOIN plato_activo pa ON pa.id = ga.menu_item_id
     WHERE ga.account_id = p_account_id
  ),
  copias AS (
    -- `IS NOT DISTINCT FROM` mas abajo, no `=`: una pregunta sin marca tiene
    -- `brand_id` nulo y con `=` se quedaria sin su grupo de copias.
    SELECT brand_id, nombre_norm, count(*) AS n,
           (count(DISTINCT COALESCE(min_selections,0)) > 1
         OR count(DISTINCT COALESCE(max_selections,0)) > 1) AS reglas_distintas
      FROM pregunta GROUP BY 1,2
  ),
  fila AS (
    SELECT q.*,
           (SELECT count(*) FROM opcion o WHERE o.modifier_group_id=q.id AND o.activa)      AS opciones,
           (SELECT count(*) FROM opcion o WHERE o.modifier_group_id=q.id AND NOT o.activa)  AS retiradas,
           (SELECT count(*) FROM opcion o WHERE o.modifier_group_id=q.id AND o.activa
                                            AND o.precio > 0)                               AS cobran,
           (SELECT count(*) FROM opcion o WHERE o.modifier_group_id=q.id AND o.activa
                                            AND NOT o.decidida)                             AS sin_decidir,
           (SELECT count(*) FROM puesta a WHERE a.modifier_group_id=q.id)                    AS platos,
           c.n AS copias, c.reglas_distintas
      FROM pregunta q
      JOIN copias c ON c.brand_id IS NOT DISTINCT FROM q.brand_id AND c.nombre_norm = q.nombre_norm
  ),
  fila_json AS (
    SELECT f.*, jsonb_build_object(
             'id', f.id, 'nombre', f.name,
             'tipo', CASE f.group_type WHEN 'choice' THEN 'elige' WHEN 'extras' THEN 'anade'
                                       WHEN 'removal' THEN 'quita' ELSE COALESCE(f.group_type,'elige') END,
             'de_pago', (f.cobran > 0),
             'min', COALESCE(f.min_selections,0), 'max', COALESCE(f.max_selections,1),
             'obligatoria', (COALESCE(f.min_selections,0) > 0),
             'repetible', f.repetible, 'activa', f.activa,
             'origen', f.origen,
             'cedida', f.cedida,
             'editable', (NOT f.cedida),
             -- Para la linea de la pantalla: «esta pregunta venia de una
             -- importacion antigua; al guardarla pasa a ser tuya». Hoy, 40.
             'etiqueta_vieja', (f.origen = 'lastapp' AND NOT f.cedida),
             'opciones', f.opciones, 'opciones_cobran', f.cobran,
             'opciones_retiradas', f.retiradas,
             'sin_decidir', f.sin_decidir, 'platos', f.platos,
             'copias', f.copias, 'reglas_distintas', f.reglas_distintas,
             -- Copias con las MISMAS reglas se pueden juntar; con reglas
             -- distintas no se junta a ciegas, se revisa.
             'accion', CASE WHEN f.copias > 1 AND f.reglas_distintas THEN 'revisar'
                            WHEN f.copias > 1                        THEN 'juntar'
                            ELSE 'abrir' END) AS j
      FROM fila f
  ),
  marca AS (
    SELECT b.id, b.name, (COALESCE(b.ownership_type,'own') <> 'own') AS cedida
      FROM public.brand b WHERE b.account_id = p_account_id
  ),
  vendidas AS (
    SELECT sl.id, o.id AS opcion, COALESCE(mg.external_source,'propia') AS origen,
           -- MISMA DEFINICION QUE ARRIBA. `extra IS NULL` es lo que cuenta
           -- las vendidas «sin decidir»: una ficha sin cantidad nombraba un
           -- articulo y no descontaba nada, o sea que contaba como decidida
           -- mintiendo igual que el otro predicado.
           (SELECT i.target_recipe_item_id FROM public.modifier_recipe_impact i
             WHERE i.modifier_option_id = o.id AND i.account_id = p_account_id
               AND i.status='confirmed' AND i.target_recipe_item_id IS NOT NULL
               AND public._impacto_completo(i.impact_type,
                                            i.target_recipe_item_id,
                                            i.quantity) LIMIT 1) AS extra,
           -- UN PEDIDO ANULADO NO ES DEMANDA (Julio, 13/09). No se filtra
           -- aqui: se MARCA, y cada cifra de la franja decide. Filtrarlo en el
           -- WHERE haria desaparecer las 21 lineas sin que nadie supiera que
           -- existen, y el 0 nunca va solo (regla 7).
           (s.cancelled_at IS NULL) AS viva
      FROM public.sale_line sl
      JOIN public.sale s ON s.id = sl.sale_id
      LEFT JOIN public.modifier_option o ON o.id = sl.modifier_option_id AND o.account_id = p_account_id
      LEFT JOIN public.modifier_group mg ON mg.id = o.modifier_group_id
     WHERE sl.account_id = p_account_id AND sl.modifier_option_id IS NOT NULL
       AND sl.ignored_at IS NULL AND s.created_at >= v_desde
  )
  SELECT jsonb_build_object(
    'ventana', jsonb_build_object('dias', v_dias, 'desde', v_desde, 'hasta', v_hoy),
    'franja', jsonb_build_object(
      'vendidas',      (SELECT count(*) FROM vendidas WHERE viva),
      'con_que_lleva', (SELECT count(*) FROM vendidas WHERE viva AND extra IS NOT NULL),
      'sin_decidir',   (SELECT count(*) FROM vendidas WHERE viva AND opcion IS NOT NULL AND extra IS NULL),
      'desconocidas',  (SELECT count(*) FROM vendidas WHERE viva AND opcion IS NULL),
      'cedidas',       (SELECT count(*) FROM vendidas WHERE viva AND origen <> 'propia'),
      'propias',       (SELECT count(*) FROM vendidas WHERE viva AND origen = 'propia'),
      -- Y las anuladas AL LADO, no escondidas: misma pareja y misma vara que
      -- usa la mitad que limpia (`cancelled_at IS NULL`).
      'anuladas',      (SELECT count(*) FROM vendidas WHERE NOT viva)),
    'cifras', jsonb_build_object(
      'preguntas',           (SELECT count(*) FROM pregunta),
      'opciones',            (SELECT count(*) FROM opcion),
      'opciones_activas',    (SELECT count(*) FROM opcion WHERE activa),
      'platos_con_pregunta', (SELECT count(DISTINCT menu_item_id) FROM puesta),
      'platos_activos',      (SELECT count(*) FROM plato_activo),
      'repetidas_nombres',   (SELECT count(*) FROM copias WHERE n > 1),
      'repetidas_preguntas', (SELECT COALESCE(sum(n),0) FROM copias WHERE n > 1),
      -- Extras que hay DETRAS DE LO QUE SE VENDE HOY: el impacto de una
      -- opcion retirada no descuenta nada de nadie.
      'extras_distintos',    (SELECT count(DISTINCT i.target_recipe_item_id)
                                FROM public.modifier_recipe_impact i
                                JOIN opcion o ON o.id = i.modifier_option_id AND o.activa
                               WHERE i.account_id = p_account_id AND i.status='confirmed'
                                 AND i.target_recipe_item_id IS NOT NULL),
      'opciones_decididas_activas',  (SELECT count(*) FROM opcion WHERE activa AND decidida),
      'opciones_sin_decidir',        (SELECT count(*) FROM opcion WHERE NOT decidida),
      'opciones_sin_decidir_activas',(SELECT count(*) FROM opcion WHERE NOT decidida AND activa),
      'opciones_sin_decidir_cobran', (SELECT count(*) FROM opcion WHERE NOT decidida AND precio > 0),
      'opciones_sin_decidir_cobran_activas',
                                     (SELECT count(*) FROM opcion
                                       WHERE NOT decidida AND precio > 0 AND activa)),
    -- Propias primero y cedidas despues: 'false' < 'true' como texto.
    'marcas', COALESCE((
      SELECT jsonb_agg(x.m ORDER BY (x.m->>'cedida'), (x.m->>'nombre'))
        FROM (SELECT jsonb_build_object(
                'id', mb.id, 'nombre', mb.name, 'cedida', mb.cedida,
                'preguntas', (SELECT jsonb_agg(fj.j ORDER BY
                                (fj.sin_decidir > 0 OR fj.copias > 1) DESC,
                                fj.sin_decidir DESC, fj.copias DESC, fj.name)
                                FROM fila_json fj WHERE fj.brand_id = mb.id AND fj.platos > 0)) AS m
                FROM marca mb
               WHERE EXISTS (SELECT 1 FROM fila_json fj WHERE fj.brand_id = mb.id AND fj.platos > 0)) x
      ), '[]'::jsonb),
    -- Las que no estan en ningun plato ACTIVO van aparte, no desaparecen.
    'sin_plato', jsonb_build_object(
      'preguntas', (SELECT count(*) FROM fila_json WHERE platos = 0),
      'opciones',  (SELECT COALESCE(sum(opciones),0) FROM fila_json WHERE platos = 0),
      'opciones_retiradas', (SELECT COALESCE(sum(retiradas),0) FROM fila_json WHERE platos = 0),
      'filas', COALESCE((SELECT jsonb_agg(fj.j || jsonb_build_object(
                            'marca', (SELECT mb.name FROM marca mb WHERE mb.id = fj.brand_id)) ORDER BY fj.name)
                           FROM fila_json fj WHERE fj.platos = 0), '[]'::jsonb))
  ) INTO v_out;
  RETURN v_out;
END;
$$;


--
-- Name: modificadores_plan_de_retiro(uuid, uuid[], text[], boolean, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.modificadores_plan_de_retiro(p_account_id uuid, p_brand_ids uuid[], p_option_ext_ids text[], p_aplicar boolean DEFAULT false, p_max_por_marca integer DEFAULT 3, p_max_pct numeric DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_marcas    jsonb   := '[]'::jsonb;
  v_retiradas integer := 0;
  v_frenadas  integer := 0;
  v_visitadas integer := 0;
  v_sin_ref   integer := 0;
  v_avisados  integer := 0;
  v_callados  integer := 0;
  v_marca     jsonb;
  v_id        bigint;
  v_a_retirar uuid[] := '{}';
  v_rescatados integer := 0;
  v_rescatables integer := 0;
  v_sin_codigo integer := 0;
  v_reactivar  uuid[] := '{}';
  v_reactivadas integer := 0;
  -- 🔴 LO NUEVO (14/09): la vuelta atras se parte en dos montones.
  v_volver_rutina  uuid[] := '{}';   -- las apago el propio importador, o no se sabe
  v_volver_persona uuid[] := '{}';   -- las apago UNA PERSONA: esto deshace lo suyo
  v_deshechas      integer := 0;
  v_deshechas_json jsonb   := '[]'::jsonb;
BEGIN
  -- FRENO 2 · la lista vacía no retira.
  IF p_account_id IS NULL
     OR COALESCE(array_length(p_brand_ids, 1), 0) = 0
     OR COALESCE(array_length(p_option_ext_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok',     false,
      'motivo', 'la pasada no trae marcas visitadas o no trae ni una opcion de Last: no se retira nada',
      'aplicado',           false,
      'marcas_visitadas',   COALESCE(array_length(p_brand_ids, 1), 0),
      'opciones_en_last',   COALESCE(array_length(p_option_ext_ids, 1), 0),
      'opciones_retiradas', 0,
      'marcas_frenadas',    0,
      'marcas',             '[]'::jsonb
    );
  END IF;

  -- ── EL PLAN. Sólo lee. Lo que decide aquí es lo que se ejecuta abajo, y
  -- es lo MISMO que devuelve el `dry_run`: una sola vara para los dos lados
  -- (regla 31).
  WITH vivas AS (
    -- FRENO 1 · el raíl: sólo marcas visitadas, sólo cedidas, sólo de esta
    -- cuenta (regla 9: el catálogo plantilla comparte tablas Y nombres).
    SELECT mo.id, mo.name AS opcion, mo.external_id, mo.pos_modifier_id,
           mg.brand_id, b.name AS marca, mg.name AS pregunta
      FROM public.modifier_option mo
      JOIN public.modifier_group  mg ON mg.id = mo.modifier_group_id
      JOIN public.brand           b  ON b.id  = mg.brand_id
     WHERE mo.account_id      = p_account_id
       AND b.account_id       = p_account_id
       AND mo.external_source = 'lastapp'
       AND mo.is_active
       AND mg.brand_id        = ANY(p_brand_ids)
       AND b.ownership_type   = 'licensed'
  ),
  cat AS (
    SELECT DISTINCT e AS ext FROM unnest(p_option_ext_ids) e WHERE e IS NOT NULL
  ),
  -- Una opción con origen `lastapp` y SIN referencia no se puede comparar con
  -- nada: no se retira, se cuenta aparte y se dice.
  con_ref AS (SELECT * FROM vivas WHERE external_id IS NOT NULL),
  sobra AS (
    SELECT v.* FROM con_ref v
     WHERE NOT EXISTS (SELECT 1 FROM cat c WHERE c.ext = v.external_id)
  ),
  por_marca AS (
    SELECT v.brand_id, max(v.marca) AS marca, count(*) AS activas,
           count(*) FILTER (
             WHERE NOT EXISTS (SELECT 1 FROM cat c WHERE c.ext = v.external_id)
           ) AS sobran
      FROM con_ref v
     GROUP BY v.brand_id
  ),
  decision AS (
    -- FRENO 3 · el de Julio. Se evalúa marca por marca, con SUS cifras: el
    -- freno de una no arrastra a las demás.
    SELECT pm.*,
           (pm.sobran > p_max_por_marca
            OR pm.sobran::numeric > (p_max_pct / 100.0) * pm.activas) AS frenada,
           round(100.0 * pm.sobran / NULLIF(pm.activas, 0), 1) AS pct
      FROM por_marca pm
     WHERE pm.sobran > 0
  )
  SELECT
    (SELECT COALESCE(array_agg(s.id), '{}')
       FROM sobra s JOIN decision d ON d.brand_id = s.brand_id WHERE NOT d.frenada),
    (SELECT count(*) FROM decision WHERE frenada),
    (SELECT count(DISTINCT brand_id) FROM vivas),
    (SELECT count(*) FROM vivas WHERE external_id IS NULL),
    (SELECT COALESCE(jsonb_agg(x ORDER BY x->>'marca'), '[]'::jsonb) FROM (
       SELECT jsonb_build_object(
                'brand_id', d.brand_id,
                'marca',    d.marca,
                'activas',  d.activas,
                'sobran',   d.sobran,
                'pct',      d.pct,
                'frenada',  d.frenada,
                'motivo_del_freno', CASE
                  WHEN NOT d.frenada THEN NULL
                  WHEN d.sobran > p_max_por_marca
                    THEN format('%s opciones es mas de %s', d.sobran, p_max_por_marca)
                  ELSE format('%s %% es mas del %s %% de las suyas', d.pct, p_max_pct)
                END,
                'opciones', (
                  SELECT COALESCE(jsonb_agg(jsonb_build_object(
                           'opcion', s.opcion, 'pregunta', s.pregunta, 'ref', s.external_id,
                           'codigo', s.pos_modifier_id)
                         ORDER BY s.opcion), '[]'::jsonb)
                    FROM sobra s WHERE s.brand_id = d.brand_id
                )
              ) AS x
         FROM decision d
     ) q)
  INTO v_a_retirar, v_frenadas, v_visitadas, v_sin_ref, v_marcas;

  -- ── LA VUELTA. Lo que Last VUELVE a servir se vuelve a encender solo.
  --
  -- 🔴 EN DOS MONTONES (14/09). El de arriba es rutina: la apagó el propio
  -- importador y ahora Last la recupera. El de abajo DESHACE LO DE UNA
  -- PERSONA, y ése es el que habla.
  SELECT COALESCE(array_agg(mo.id) FILTER (WHERE mo.deactivated_by IS DISTINCT FROM 'persona'), '{}'::uuid[]),
         COALESCE(array_agg(mo.id) FILTER (WHERE mo.deactivated_by = 'persona'), '{}'::uuid[])
    INTO v_volver_rutina, v_volver_persona
    FROM public.modifier_option mo
    JOIN public.modifier_group  mg ON mg.id = mo.modifier_group_id
    JOIN public.brand           b  ON b.id  = mg.brand_id
   WHERE mo.account_id      = p_account_id
     AND b.account_id       = p_account_id
     AND mo.external_source = 'lastapp'
     AND NOT mo.is_active
     AND mg.brand_id        = ANY(p_brand_ids)
     AND b.ownership_type   = 'licensed'
     AND mo.external_id IS NOT NULL
     AND mo.external_id = ANY(p_option_ext_ids);

  v_reactivar := v_volver_rutina || v_volver_persona;

  -- El detalle de las que deshacen, ANTES de tocarlas: después de encenderlas
  -- el sello ya no dice quién las había apagado ni cuándo, y eso es justo lo
  -- que hay que contar.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'brand_id',  mg.brand_id,
           'marca',     b.name,
           'pregunta',  mg.name,
           'opcion',    mo.name,
           'la_apago',  mo.deactivated_by,
           'apagada_el', mo.deactivated_at)
         ORDER BY b.name, mo.name), '[]'::jsonb)
    INTO v_deshechas_json
    FROM public.modifier_option mo
    JOIN public.modifier_group mg ON mg.id = mo.modifier_group_id
    JOIN public.brand b ON b.id = mg.brand_id
   WHERE mo.id = ANY(v_volver_persona);

  -- ── LO QUE EL RESCATE PUEDE SALVAR.
  WITH evidencia AS (
    SELECT sl.modifier_option_id AS opt, min(sl.external_product_id) AS ref
      FROM public.sale_line sl
     WHERE sl.account_id = p_account_id
       AND sl.line_type = 'modifier'
       AND sl.external_source = 'lastapp'
       AND sl.external_product_id IS NOT NULL
       AND sl.modifier_option_id = ANY(v_a_retirar)
     GROUP BY sl.modifier_option_id
    HAVING count(DISTINCT sl.external_product_id) = 1
       AND NOT EXISTS (SELECT 1 FROM public.modifier_option o2
                        WHERE o2.account_id = p_account_id
                          AND o2.pos_modifier_id = min(sl.external_product_id))
  )
  SELECT count(*) FILTER (WHERE e.ref IS NOT NULL),
         count(*) FILTER (WHERE e.ref IS NULL)
    INTO v_rescatables, v_sin_codigo
    FROM public.modifier_option mo
    LEFT JOIN evidencia e ON e.opt = mo.id
   WHERE mo.id = ANY(v_a_retirar) AND mo.pos_modifier_id IS NULL;

  -- Las de rutina: se encienden y quedan limpias, como siempre.
  IF p_aplicar AND COALESCE(array_length(v_volver_rutina, 1), 0) > 0 THEN
    UPDATE public.modifier_option mo
       SET is_active = true, deactivated_at = NULL, deactivated_by = NULL,
           updated_at = now()
     WHERE mo.id = ANY(v_volver_rutina);
    GET DIAGNOSTICS v_reactivadas = ROW_COUNT;
  END IF;

  -- Las que deshacen lo de una persona: se encienden IGUAL --Julio, 13/09
  -- 19:45: «no se arregla quitándolo, se arregla haciéndolo hablar»-- pero
  -- dejan la marca puesta. El disparador pone la fecha.
  IF p_aplicar AND COALESCE(array_length(v_volver_persona, 1), 0) > 0 THEN
    UPDATE public.modifier_option mo
       SET is_active = true, reencendida_sobre = 'persona', updated_at = now()
     WHERE mo.id = ANY(v_volver_persona);
    GET DIAGNOSTICS v_deshechas = ROW_COUNT;
    v_reactivadas := v_reactivadas + v_deshechas;
  END IF;

  IF p_aplicar AND v_reactivadas <> COALESCE(array_length(v_reactivar, 1), 0) THEN
    RAISE EXCEPTION 'A2c: el plan decia reencender % y se reencendieron %',
      COALESCE(array_length(v_reactivar, 1), 0), v_reactivadas;
  END IF;

  IF p_aplicar AND COALESCE(array_length(v_a_retirar, 1), 0) > 0 THEN
    -- EL RESCATE DEL CÓDIGO, antes de apagar. Sólo donde la evidencia de los
    -- propios pedidos es UNA y no la usa nadie más. Si no, no se inventa nada.
    WITH evidencia AS (
      SELECT sl.modifier_option_id AS opt, min(sl.external_product_id) AS ref
        FROM public.sale_line sl
       WHERE sl.account_id = p_account_id
         AND sl.line_type = 'modifier'
         AND sl.external_source = 'lastapp'
         AND sl.external_product_id IS NOT NULL
         AND sl.modifier_option_id = ANY(v_a_retirar)
       GROUP BY sl.modifier_option_id
      HAVING count(DISTINCT sl.external_product_id) = 1
         AND NOT EXISTS (SELECT 1 FROM public.modifier_option o2
                          WHERE o2.account_id = p_account_id
                            AND o2.pos_modifier_id = min(sl.external_product_id))
    )
    UPDATE public.modifier_option mo
       SET pos_modifier_id = e.ref, updated_at = now()
      FROM evidencia e
     WHERE mo.id = e.opt AND mo.pos_modifier_id IS NULL;
    GET DIAGNOSTICS v_rescatados = ROW_COUNT;

    UPDATE public.modifier_option mo
       SET is_active = false, deactivated_at = now(), deactivated_by = 'last',
           updated_at = now()
     WHERE mo.id = ANY(v_a_retirar);
    GET DIAGNOSTICS v_retiradas = ROW_COUNT;

    -- Si lo hecho no es lo planeado, algo se movió por debajo: se para.
    IF v_rescatados <> v_rescatables
       OR v_retiradas <> COALESCE(array_length(v_a_retirar, 1), 0) THEN
      RAISE EXCEPTION 'A2c: el plan decia % rescates y % retiros; se hicieron % y %',
        v_rescatables, COALESCE(array_length(v_a_retirar, 1), 0), v_rescatados, v_retiradas;
    END IF;
  END IF;

  IF p_aplicar AND v_frenadas > 0 THEN
    FOR v_marca IN
      SELECT m FROM jsonb_array_elements(v_marcas) m WHERE (m->>'frenada')::boolean
    LOOP
      v_id := public.encolar_alerta(
        p_kind    => 'catalogo_last_retiro_frenado',
        p_subject => format('Last: no se han retirado los extras de %s', v_marca->>'marca'),
        p_message => format(
            'El importador de Last iba a apagar %s de las %s opciones de extra de %s (%s %%) y no ha apagado ninguna: %s. '
         || 'O Last ha cambiado la carta de verdad, o la pasada vino incompleta. Hasta que se mire, esas opciones siguen encendidas. '
         || 'Son: %s.',
            v_marca->>'sobran', v_marca->>'activas', v_marca->>'marca', v_marca->>'pct',
            v_marca->>'motivo_del_freno',
            (SELECT string_agg(o->>'opcion', ', ') FROM jsonb_array_elements(v_marca->'opciones') o)),
        p_debounce_kind   => 'catalogo_last_retiro_frenado:' || (v_marca->>'marca'),
        p_debounce_window => interval '6 hours',
        p_account_id      => p_account_id,
        p_brand_id        => (v_marca->>'brand_id')::uuid,
        p_severity        => 'aviso'
      );
      IF v_id IS NULL THEN v_callados := v_callados + 1;
      ELSE                 v_avisados := v_avisados + 1;
      END IF;
    END LOOP;
  END IF;

  -- ── 🔴 EL AVISO NUEVO: se ha deshecho lo que decidió una persona.
  --
  -- Un aviso interrumpe, así que aquí SÍ se filtra (regla 7): sólo sale cuando
  -- hay al menos una, y una por marca, no una por opción. Pero el parte de
  -- abajo las lleva TODAS con nombre, que es la pantalla que se abre a
  -- propósito.
  --
  -- Y no se dice una hora: se dice «de madrugada». La hora de la pasada es
  -- cosa nuestra y cambia; lo que le importa a quien lo lee es que pasó
  -- mientras no estaba.
  IF p_aplicar AND v_deshechas > 0 THEN
    FOR v_marca IN
      SELECT jsonb_build_object(
               'brand_id', d->>'brand_id',
               'marca',    d->>'marca',
               'cuantas',  count(*),
               'opciones', string_agg(d->>'opcion', ', ' ORDER BY d->>'opcion'))
        FROM jsonb_array_elements(v_deshechas_json) d
       GROUP BY d->>'brand_id', d->>'marca'
    LOOP
      v_id := public.encolar_alerta(
        p_kind    => 'catalogo_last_reenciende_lo_que_apago_una_persona',
        p_subject => format('Last ha vuelto a encender %s extra%s de %s que alguien había quitado',
                            v_marca->>'cuantas',
                            CASE WHEN (v_marca->>'cuantas')::int = 1 THEN '' ELSE 's' END,
                            v_marca->>'marca'),
        p_message => format(
            'Alguien había quitado %s en %s desde Folvy, y Last las sigue sirviendo. '
         || 'La importación de madrugada las ha vuelto a encender, que es lo que hace cuando Last recupera una opción. '
         || 'Ahora están a la venta otra vez. Si tienen que estar quitadas, hay que quitarlas TAMBIÉN en Last: '
         || 'mientras Last las sirva, volverán a encenderse cada noche.',
            v_marca->>'opciones', v_marca->>'marca'),
        p_debounce_kind   => 'catalogo_last_reenciende_persona:' || (v_marca->>'marca'),
        p_debounce_window => interval '6 hours',
        p_account_id      => p_account_id,
        p_brand_id        => (v_marca->>'brand_id')::uuid,
        p_severity        => 'aviso'
      );
      IF v_id IS NULL THEN v_callados := v_callados + 1;
      ELSE                 v_avisados := v_avisados + 1;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'ok',                 true,
    'aplicado',           p_aplicar,
    'marcas_visitadas',   v_visitadas,
    'opciones_en_last',   COALESCE(array_length(p_option_ext_ids, 1), 0),
    'opciones_retiradas', v_retiradas,
    'opciones_a_retirar', COALESCE(array_length(v_a_retirar, 1), 0),
    'opciones_a_reencender', COALESCE(array_length(v_reactivar, 1), 0),
    'opciones_reencendidas', v_reactivadas,
    'reencendidas_cuales', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('opcion', mo.name, 'marca', b.name)
                      ORDER BY mo.name), '[]'::jsonb)
        FROM public.modifier_option mo
        JOIN public.modifier_group mg ON mg.id = mo.modifier_group_id
        JOIN public.brand b ON b.id = mg.brand_id
       WHERE mo.id = ANY(v_reactivar)
    ),
    -- 🔴 EL PARTE DE LA PASADA LAS LLEVA CON NOMBRE. Sin esto, una pasada que
    -- deshace tres decisiones se lee igual que una que no deshace ninguna.
    'reencendidas_sobre_una_persona',        v_deshechas,
    'reencendidas_sobre_una_persona_a_hacer', COALESCE(array_length(v_volver_persona, 1), 0),
    'reencendidas_sobre_una_persona_cuales', v_deshechas_json,
    'codigos_rescatables',  v_rescatables,
    'codigos_rescatados',   v_rescatados,
    'retiradas_sin_codigo', v_sin_codigo,
    'marcas_frenadas',    v_frenadas,
    'avisos_encolados',   v_avisados,
    'avisos_callados_por_antirruido', v_callados,
    'sin_referencia_no_tocadas',      v_sin_ref,
    'freno',  jsonb_build_object('max_por_marca', p_max_por_marca, 'max_pct', p_max_pct),
    'marcas', v_marcas
  );
END;
$$;


--
-- Name: modifier_incomplete_impact_watchdog(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.modifier_incomplete_impact_watchdog(p_debounce_window interval DEFAULT '20:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r         record;
  v_avisos  integer := 0;
  v_candado boolean;
begin
  -- ¿Sigue puesto el candado? Es la explicacion de como puede haber filas, y
  -- por eso se mira ANTES: sin el, la cifra de abajo solo dice que ya ha
  -- pasado.
  select c.convalidated into v_candado
    from pg_constraint c
   where c.conrelid = 'public.modifier_recipe_impact'::regclass
     and c.conname  = 'impacto_confirmado_completo';

  if v_candado is null or not v_candado then
    perform public._queue_system_alert(
      'ficha_a_medias_candado_caido',
      'El candado que impide fichas a medias ya no esta puesto',
      'La tabla `modifier_recipe_impact` tenia un candado --`impacto_confirmado_completo`-- '
      || 'que impedia guardar una decision confirmada que no descuenta nada: un «anade» sin '
      || 'articulo, una cantidad a cero, una ficha sin cantidad.' || chr(10) || chr(10)
      || case when v_candado is null
              then 'Ahora **no existe**.'
              else 'Ahora existe pero **no esta validado**, o sea que no dice nada de las filas que ya hay.' end
      || chr(10) || chr(10)
      || 'Mientras no este, las tres puertas de pantalla siguen preguntando, pero una escritura '
      || 'directa a la tabla puede volver a dejar respuestas que la pantalla da por decididas y '
      || 'que descuentan cero del almacen.',
      'ficha_a_medias_candado_caido_'
        || to_char(now() at time zone 'Europe/Madrid', 'YYYYMMDD'),
      p_debounce_window);
    v_avisos := v_avisos + 1;
    raise warning 'modifier_incomplete_impact_watchdog: EL CANDADO NO ESTA PUESTO.';
  end if;

  -- Y las filas, por cuenta (regla 9: una cifra sin cuenta no es de nadie).
  for r in
    select i.account_id,
           coalesce(a.name, '(cuenta sin nombre)') as cuenta,
           count(*)::int as filas,
           count(distinct i.modifier_option_id)::int as respuestas,
           count(*) filter (where coalesce(o.is_active, true))::int as vivas,
           string_agg(distinct coalesce(o.name, '(sin nombre)'), ', '
                      order by coalesce(o.name, '(sin nombre)')) as cuales
      from public.modifier_recipe_impact i
      left join public.modifier_option o on o.id = i.modifier_option_id
      left join public.accounts a on a.id = i.account_id
     where i.status = 'confirmed'
       and not public._impacto_completo(i.impact_type, i.target_recipe_item_id, i.quantity)
     group by i.account_id, a.name
  loop
    -- DM1 · PR 2a (31/10): una cuenta de demo no cuenta en los vigías.
    continue when not public.cuenta_puede_salir(r.account_id);
    perform public._queue_system_alert(
      'modificador_ficha_a_medias',
      'Hay ' || r.respuestas::text || ' respuestas con ficha a medias en ' || r.cuenta,
      'En ' || r.cuenta || ' hay **' || r.respuestas::text || ' respuestas de modificador cuya '
      || 'ficha esta confirmada y NO DESCUENTA NADA** (' || r.vivas::text || ' de ellas siguen '
      || 'encendidas). La pantalla las da por decididas; el almacen no ve salir nada.'
      || chr(10) || chr(10)
      || 'Son: ' || r.cuales || '.' || chr(10) || chr(10)
      || 'Esto no deberia poder pasar: desde el 13/09 la propia tabla lo prohibe. Si hay filas, '
      || 'o se han escrito rodeando la tabla, o el candado se ha caido.' || chr(10) || chr(10)
      || 'Se arregla en Folvy Kitchen -> Modificadores -> la pregunta -> la respuesta, poniendo '
      || 'el articulo y la cantidad.',
      'modificador_ficha_a_medias_' || r.account_id::text || '_'
        || to_char(now() at time zone 'Europe/Madrid', 'YYYYMMDD'),
      p_debounce_window);
    v_avisos := v_avisos + 1;
    raise warning 'modifier_incomplete_impact_watchdog: % — % filas a medias en % respuestas (% vivas).',
      r.cuenta, r.filas, r.respuestas, r.vivas;
  end loop;

  if v_avisos = 0 then
    -- Un vigia que calla no se distingue de uno roto (regla 8).
    raise warning 'modifier_incomplete_impact_watchdog: candado puesto y validado, cero fichas a medias.';
  end if;

  return v_avisos;
end;
$$;


--
-- Name: modifier_zero_cost_watchdog(interval, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.modifier_zero_cost_watchdog(p_ventana interval DEFAULT '30 days'::interval, p_debounce_window interval DEFAULT '20:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r        record;
  v_base   record;
  v_avisos integer := 0;
begin
  for r in
    with cero as (
      -- Una opcion ACTIVA que cobra dinero y cuyos impactos confirmados suman
      -- exactamente 0 EUR. Devolver 0 no es «no inventar»: es afirmar que no
      -- cuesta nada. Incluye tanto las que tienen impacto roto (sin unidad, sin
      -- destino, no convertible) como las que no tienen NINGUN impacto — que es
      -- el caso de «Si, con patatas» de Lovers Burgers, 27 lineas en agosto.
      select mo.account_id, mo.id
        from modifier_option mo
       where mo.is_active
         and coalesce(mo.price_impact, 0) > 0
         and coalesce((select sum(case when i.impact_type in ('add_item','bundle','replace_item')
                                       then public._impact_cost(i.target_recipe_item_id, i.quantity, i.unit_id)
                                       else 0 end)
                         from modifier_recipe_impact i
                        where i.modifier_option_id = mo.id
                          and i.status = 'confirmed'), 0) = 0
    ),
    vivas as (
      -- Las que ademas SE ESTAN VENDIENDO. Una opcion muerta que vale cero es
      -- deuda; una que vende es dinero saliendo hoy.
      select distinct c.account_id, c.id
        from cero c
        join sale_line m on m.modifier_option_id = c.id and m.line_type = 'modifier'
        join sale s on s.id = m.sale_id
                   and s.account_id = c.account_id          -- regla 9, tambien aqui
                   and s.sold_at >= now() - coalesce(p_ventana, interval '30 days')
                   and coalesce(s.status, '') <> 'cancelled'
    )
    select c.account_id,
           coalesce(a.name, '(cuenta sin nombre)') as cuenta,
           count(distinct c.id)::int as total,
           count(distinct v.id)::int as vivas
      from cero c
      left join vivas v on v.id = c.id
      left join accounts a on a.id = c.account_id
     group by c.account_id, a.name
  loop
    -- DM1 · PR 2a (31/10): una cuenta de demo no cuenta en los vigías.
    -- Tampoco se siembra ni se mueve su marca: al quitarle la demo, empieza de cero.
    continue when not public.cuenta_puede_salir(r.account_id);
    select * into v_base from public.modifier_zero_cost_baseline where account_id = r.account_id;

    if not found then
      -- Primera vez: se siembra la marca con lo que hay y NO se avisa. Avisar de
      -- un pasivo que ya existia no le dice a nadie que ha pasado algo hoy.
      insert into public.modifier_zero_cost_baseline (account_id, vivas, total)
      values (r.account_id, r.vivas, r.total);
      raise warning 'modifier_zero_cost_watchdog: % — marca sembrada en % vivas de % que cobran y valen 0 EUR.',
        r.cuenta, r.vivas, r.total;

    elsif r.vivas > v_base.vivas then
      -- HA SUBIDO. Un aviso por cuenta, con los dos numeros absolutos delante.
      perform public._queue_system_alert(
        'modificador_sin_coste',
        'Hay ' || r.vivas::text || ' modificadores que cobran y cuestan 0 EUR en ' || r.cuenta
          || ' (eran ' || v_base.vivas::text || ')',
        'En ' || r.cuenta || ' hay ahora **' || r.vivas::text || ' opciones de modificador que '
          || 'COBRAN dinero, se han vendido en los ultimos '
          || extract(day from coalesce(p_ventana, interval '30 days'))::int::text
          || ' dias y aportan 0,00 EUR al coste**. Antes eran ' || v_base.vivas::text || '.'
          || chr(10) || chr(10)
          || 'En total, contando tambien las que no se venden, son ' || r.total::text
          || ' opciones en esa situacion.' || chr(10) || chr(10)
          || 'Aportar cero no es «no inventar un coste»: es afirmar que no cuesta nada, y eso '
          || 'baja el food cost de todo lo que las lleve. Las causas de siempre son tres: al '
          || 'impacto le falta la unidad, le falta el destino, o la opcion NO TIENE impacto '
          || 'ninguno (pasa cuando una marca se sustituye por otra y la nueva se queda sin '
          || 'configurar).' || chr(10) || chr(10)
          || 'Se revisa en Folvy Kitchen -> Cartas -> el producto -> pestaña «Modificadores» '
          || '-> bloque «Impacto en coste».',
        'modificador_sin_coste_' || r.account_id::text || '_'
          || to_char(now() at time zone 'Europe/Madrid', 'YYYYMMDD'),
        p_debounce_window
      );
      v_avisos := v_avisos + 1;
      raise warning 'modifier_zero_cost_watchdog: % — SUBE de % a % vivas (total %). Aviso encolado.',
        r.cuenta, v_base.vivas, r.vivas, r.total;

    elsif r.vivas < v_base.vivas then
      -- Ha bajado: se consolida. El trinquete solo gira en un sentido.
      update public.modifier_zero_cost_baseline
         set vivas = r.vivas, total = r.total, updated_at = now()
       where account_id = r.account_id;
      raise warning 'modifier_zero_cost_watchdog: % — BAJA de % a % vivas (total %). Marca consolidada.',
        r.cuenta, v_base.vivas, r.vivas, r.total;

    else
      -- Igual. Se dice igualmente: un vigia que calla no se distingue de uno roto.
      update public.modifier_zero_cost_baseline
         set total = r.total, updated_at = now()
       where account_id = r.account_id;
      raise warning 'modifier_zero_cost_watchdog: % — sin cambio: % vivas de % que cobran y valen 0 EUR.',
        r.cuenta, r.vivas, r.total;
    end if;
  end loop;

  return v_avisos;
end;
$$;


--
-- Name: module_inventory(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.module_inventory(p_pattern text) RETURNS TABLE(tipo text, nombre text, filas bigint, ultimo_dato text, senal text, detalle text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r   record;
  n   bigint;
  ts  timestamptz;
  col text;
begin
  if coalesce(btrim(p_pattern), '') = '' then
    raise exception 'module_inventory: hace falta un patrón (ej. ''clock|employee|vacation'')';
  end if;

  ---------------------------------------------------------------- TABLAS
  for r in
    select c.relname::text as relname,
           c.relrowsecurity,
           (select count(*) from pg_policies p
             where p.schemaname = 'public' and p.tablename = c.relname) as pols,
           exists (select 1 from information_schema.columns ic
                    where ic.table_schema = 'public' and ic.table_name = c.relname
                      and ic.column_name = 'account_id') as has_acc
      from pg_class c
      join pg_namespace ns on ns.oid = c.relnamespace
     where ns.nspname = 'public' and c.relkind = 'r' and c.relname ~* p_pattern
     order by c.relname
  loop
    execute format('select count(*) from public.%I', r.relname) into n;

    select ic.column_name into col
      from information_schema.columns ic
     where ic.table_schema = 'public' and ic.table_name = r.relname
       and ic.data_type in ('timestamp with time zone', 'timestamp without time zone')
     order by case ic.column_name
                when 'created_at' then 1 when 'updated_at' then 2
                when 'datetime'   then 3 when 'sold_at'    then 4 else 9 end
     limit 1;

    ts := null;
    if col is not null and n > 0 then
      execute format('select max(%I)::timestamptz from public.%I', col, r.relname) into ts;
    end if;

    tipo        := 'tabla';
    nombre      := r.relname;
    filas       := n;
    ultimo_dato := coalesce(to_char(ts, 'YYYY-MM-DD'), '—');
    senal       := case
                     when n = 0 then '🔴 VACÍA — estructura sin combustible'
                     when ts is not null and ts < now() - interval '60 days'
                       then '🟠 SIN DATO RECIENTE'
                     else '✅ con dato'
                   end;
    detalle     := (case when r.has_acc then 'account_id ✓' else 'account_id ✗ (tenencia por salto)' end)
                   || ' · RLS ' || (case when r.relrowsecurity then 'on' else 'OFF 🔴' end)
                   || ' · ' || r.pols || ' pol.'
                   || (case when r.relrowsecurity and r.pols = 0 then ' 🔴 SIN POLÍTICAS' else '' end);
    return next;
  end loop;

  -------------------------------------------------------------- FUNCIONES
  for r in
    select p.proname::text as proname,
           pg_get_function_identity_arguments(p.oid) as args,
           p.prosecdef,
           has_function_privilege('anon', p.oid, 'execute') as anon_exec
      from pg_proc p
      join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public' and p.prokind = 'f' and p.proname ~* p_pattern
       and p.proname !~ '^(st_|_st_|geom|box|postgis)'
     order by p.proname
  loop
    tipo        := 'funcion';
    nombre      := r.proname || '(' || left(coalesce(r.args, ''), 70) || ')';
    filas       := null;
    ultimo_dato := '—';
    senal       := case
                     when r.prosecdef and r.anon_exec then '🔴 DEFINER ejecutable por anon'
                     when r.prosecdef                 then '🟠 DEFINER'
                     else '✅ INVOKER'
                   end;
    detalle     := '';
    return next;
  end loop;
end
$$;


--
-- Name: move_items_to_zone(uuid, uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_items_to_zone(p_account uuid, p_item_ids uuid[], p_from_zone_id uuid, p_to_zone_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_loc uuid;
  v_item uuid;
  v_from_pos int;
  v_moved int := 0;
begin
  if p_to_zone_id is null then
    raise exception 'Falta la zona de destino';
  end if;
  if p_item_ids is null or array_length(p_item_ids, 1) is null then
    return jsonb_build_object('moved', 0);
  end if;

  select location_id into v_loc
  from storage_area
  where id = p_to_zone_id and account_id = p_account;
  if v_loc is null then
    raise exception 'Zona de destino no válida';
  end if;

  foreach v_item in array p_item_ids loop
    v_from_pos := null;

    if p_from_zone_id is not null then
      select position into v_from_pos
      from recipe_item_storage_area
      where recipe_item_id = v_item
        and storage_area_id = p_from_zone_id
        and account_id = p_account;

      delete from recipe_item_storage_area
      where recipe_item_id = v_item
        and storage_area_id = p_from_zone_id
        and account_id = p_account;
    end if;

    -- añade (o reposiciona) en la zona destino heredando la position del origen
    insert into recipe_item_storage_area (account_id, recipe_item_id, storage_area_id, position)
    values (p_account, v_item, p_to_zone_id, coalesce(v_from_pos, 0))
    on conflict (recipe_item_id, storage_area_id)
    do update set position = excluded.position;

    -- re-normaliza el orden/principal del artículo en el local destino
    with ranked as (
      select rsa.recipe_item_id,
             rsa.storage_area_id,
             (row_number() over (
                order by rsa.position asc, sa.position asc
             ) - 1) * 10 as new_pos
      from recipe_item_storage_area rsa
      join storage_area sa on sa.id = rsa.storage_area_id
      where rsa.account_id = p_account
        and sa.location_id = v_loc
        and rsa.recipe_item_id = v_item
    )
    update recipe_item_storage_area t
    set position = ranked.new_pos
    from ranked
    where t.recipe_item_id = ranked.recipe_item_id
      and t.storage_area_id = ranked.storage_area_id
      and t.position <> ranked.new_pos;

    v_moved := v_moved + 1;
  end loop;

  return jsonb_build_object('moved', v_moved);
end;
$$;


--
-- Name: my_pending_courses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_pending_courses() RETURNS TABLE(assignment_id uuid, course_id uuid, course_code text, course_title text, delivery_mode text, estimated_minutes integer, reeval_months integer, due_at timestamp with time zone, status text, attempt_id uuid, score_pct numeric, passed boolean, signed_at timestamp with time zone, phase text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_account_id uuid;
begin
  select * into v_employee_id, v_account_id from public.current_employee_and_account();
  if v_employee_id is null then
    raise exception 'Sin sesión de empleado válida';
  end if;

  return query
  with per_assignment as (
    select
      ca.id as assignment_id,
      c.id as course_id,
      c.code as course_code,
      c.title as course_title,
      c.delivery_mode,
      c.estimated_minutes,
      c.reeval_months,
      ca.due_at,
      case
        when cs.value = 'vigente' then 'firmado'
        when cs.value = 'caducado' then 'caducado'
        when cs.value = 'pendiente_practica' then 'pendiente_practica'
        when att.finished_at is not null and coalesce(att.passed, false) = false then 'suspendido'
        when att.started_at is not null and att.finished_at is null then 'en_curso'
        else 'pendiente'
      end as status,
      att.id as attempt_id,
      att.score_pct,
      att.passed,
      sig.signed_at,
      pit.phase
    from public.course_assignment ca
    join public.course c on c.id = ca.course_id
    join public.employees e on e.id = v_employee_id
    left join public.training_path_item pit on pit.id = ca.path_item_id
    left join lateral (
      select public.course_state_for_employee(v_employee_id, c.id, v_account_id) as value
    ) cs on true
    left join lateral (
      select a.* from public.course_attempt a
      where a.assignment_id = ca.id and a.employee_id = v_employee_id
      order by a.started_at desc
      limit 1
    ) att on true
    left join lateral (
      select s.* from public.course_signature s
      where s.attempt_id = att.id
      order by s.signed_at desc
      limit 1
    ) sig on true
    where ca.account_id = v_account_id
      and c.status = 'published'
      and c.delivery_mode <> 'solo_archivo'
      and (
        ca.employee_id = v_employee_id
        or (ca.role is not null and ca.role = e.position)
        or (ca.location_id is not null and ca.location_id = e.location_id)
      )
  ),
  best_per_course as (
    select distinct on (per_assignment.course_id)
      per_assignment.assignment_id,
      per_assignment.course_id,
      per_assignment.course_code,
      per_assignment.course_title,
      per_assignment.delivery_mode,
      per_assignment.estimated_minutes,
      per_assignment.reeval_months,
      per_assignment.due_at,
      per_assignment.status,
      per_assignment.attempt_id,
      per_assignment.score_pct,
      per_assignment.passed,
      per_assignment.signed_at,
      per_assignment.phase
    from per_assignment
    order by
      per_assignment.course_id,
      case per_assignment.status
        when 'pendiente_practica' then 0
        when 'caducado' then 1
        when 'en_curso' then 2
        when 'suspendido' then 3
        when 'firmado' then 5
        else 4
      end,
      per_assignment.due_at nulls last
  )
  select
    best_per_course.assignment_id,
    best_per_course.course_id,
    best_per_course.course_code,
    best_per_course.course_title,
    best_per_course.delivery_mode,
    best_per_course.estimated_minutes,
    best_per_course.reeval_months,
    best_per_course.due_at,
    best_per_course.status,
    best_per_course.attempt_id,
    best_per_course.score_pct,
    best_per_course.passed,
    best_per_course.signed_at,
    best_per_course.phase
  from best_per_course
  order by
    case best_per_course.phase when 'dia_1' then 0 when 'dias_30' then 1 when 'dias_90' then 2 else 3 end,
    best_per_course.due_at nulls last,
    best_per_course.course_title;
end;
$$;


--
-- Name: negative_stock_report(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.negative_stock_report(p_account uuid, p_location uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rel_pct numeric;
  v_abs_qty numeric;
  v_window  integer;
  v_res     jsonb;
begin
  if not (current_user_is_admin() or current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'negative_stock_report: sin acceso a la cuenta %', p_account;
  end if;
  select coalesce(s.neg_stock_rel_pct, 5),
         coalesce(s.neg_stock_abs_qty, 5),
         coalesce(s.neg_stock_window_days, 60)
    into v_rel_pct, v_abs_qty, v_window
  from public.supply_settings s
  where s.account_id = p_account;
  v_rel_pct := coalesce(v_rel_pct, 5);
  v_abs_qty := coalesce(v_abs_qty, 5);
  v_window  := coalesce(v_window, 60);
  with universe as (
    select ri.id, ri.name, ku.abbreviation as unit_abbr,
           coalesce(rls.qty_on_hand, 0) as qty_on_hand,
           coalesce(rls.stock_value, 0) as value_eur
    from public.recipe_item ri
    left join public.kitchen_unit ku on ku.id = ri.base_unit_id
    left join public.recipe_item_location_stock rls
           on rls.recipe_item_id = ri.id
          and rls.location_id    = p_location
          and rls.account_id     = p_account
    where ri.account_id = p_account
      and ri.type IN ('raw', 'packaging')
      and ri.is_active = true
  ),
  negativos as (
    select * from universe where qty_on_hand < 0
  ),
  mov_all as (
    select sm.recipe_item_id,
           coalesce(sum(sm.qty_base) filter (where sm.movement_type = 'recepcion'), 0)      as recepcion_total,
           count(*)                  filter (where sm.movement_type = 'recepcion')          as recepcion_count,
           coalesce(sum(abs(sm.qty_base)) filter (where sm.movement_type = 'consumo'), 0)    as consumo_total_abs
    from public.stock_movement sm
    where sm.account_id  = p_account
      and sm.location_id = p_location
      and sm.recipe_item_id in (select id from negativos)
    group by sm.recipe_item_id
  ),
  mov_window as (
    select sm.recipe_item_id,
           coalesce(sum(abs(sm.qty_base)), 0) as consumo_window_abs
    from public.stock_movement sm
    where sm.account_id     = p_account
      and sm.location_id    = p_location
      and sm.movement_type  = 'consumo'
      and sm.occurred_at   >= now() - make_interval(days => v_window)
      and sm.recipe_item_id in (select id from negativos)
    group by sm.recipe_item_id
  ),
  scored as (
    select n.id, n.name, n.unit_abbr, n.qty_on_hand, n.value_eur,
           coalesce(ma.recepcion_total, 0)   as recepcion_total,
           coalesce(ma.recepcion_count, 0)   as recepcion_count,
           coalesce(ma.consumo_total_abs, 0) as consumo_total_abs,
           case when coalesce(mw.consumo_window_abs, 0) > 0
                then mw.consumo_window_abs
                else coalesce(ma.consumo_total_abs, 0)
           end as consumo_ref_abs
    from negativos n
    left join mov_all    ma on ma.recipe_item_id = n.id
    left join mov_window mw on mw.recipe_item_id = n.id
  )
  select jsonb_build_object(
    'window_days',       v_window,
    'threshold_rel_pct', v_rel_pct,
    'threshold_abs_qty', v_abs_qty,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'recipe_item_id', s.id,
               'name',           s.name,
               'unit_abbr',      s.unit_abbr,
               'qty_on_hand',    s.qty_on_hand,
               'value_eur',      s.value_eur,
               'ratio_pct',      case when s.consumo_ref_abs > 0
                                       then round(abs(s.qty_on_hand) / s.consumo_ref_abs * 100, 1)
                                       else null end,
               'cause',          case
                                    when s.recepcion_count = 0 then 'sin_entradas'
                                    when s.consumo_total_abs > s.recepcion_total then 'compras_por_detras'
                                    else 'otras_salidas'
                                  end,
               'is_alert',       (abs(s.qty_on_hand) >= greatest(v_rel_pct / 100.0 * s.consumo_ref_abs, v_abs_qty))
             ) order by
               (case when s.consumo_ref_abs > 0
                     then abs(s.qty_on_hand) / s.consumo_ref_abs
                     else null end) desc nulls first,
               s.qty_on_hand asc)
      from scored s
    ), '[]'::jsonb)
  ) into v_res;
  return v_res;
end;
$$;


--
-- Name: next_folvy_code(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_folvy_code(p_account_id uuid, p_type text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_prefix text := public.folvy_code_prefix(p_type);
  v_next   int;
BEGIN
  SELECT COALESCE(MAX(SUBSTRING(folvy_code FROM '[0-9]+$')::int), 0) + 1
    INTO v_next
    FROM public.recipe_item
    WHERE account_id = p_account_id
      AND folvy_code LIKE v_prefix || '-%';
  RETURN v_prefix || '-' || LPAD(v_next::text, 5, '0');
END;
$_$;


--
-- Name: next_goods_receipt_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_goods_receipt_code(p_account_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_n integer;
BEGIN
  -- Serializa por cuenta: dos recepciones simultáneas no comparten correlativo.
  PERFORM pg_advisory_xact_lock(hashtext('goods_receipt_code:' || p_account_id::text));

  SELECT COALESCE(MAX((regexp_replace(code, '\D', '', 'g'))::integer), 0) + 1
    INTO v_n
    FROM public.goods_receipt
    WHERE account_id = p_account_id
      AND code ~ '^ALB-\d+$';

  RETURN 'ALB-' || lpad(v_n::text, 5, '0');
END;
$_$;


--
-- Name: next_inventory_count_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_inventory_count_code(p_account_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_n integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('inventory_count_code:' || p_account_id::text));
  SELECT COALESCE(MAX((regexp_replace(code, '\D', '', 'g'))::integer), 0) + 1
    INTO v_n
    FROM public.inventory_count
    WHERE account_id = p_account_id
      AND code ~ '^INV-\d+$';
  RETURN 'INV-' || lpad(v_n::text, 5, '0');
END;
$_$;


--
-- Name: next_purchase_order_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_purchase_order_code(p_account_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_prefix text := 'PED';
  v_next   int;
BEGIN
  SELECT COALESCE(MAX(SUBSTRING(code FROM '[0-9]+$')::int), 0) + 1
    INTO v_next
    FROM public.purchase_order
    WHERE account_id = p_account_id
      AND code LIKE v_prefix || '-%';
  RETURN v_prefix || '-' || LPAD(v_next::text, 5, '0');
END;
$_$;


