--
-- Name: night_minutes_in_span(timestamp with time zone, timestamp with time zone, time without time zone, time without time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.night_minutes_in_span(p_from timestamp with time zone, p_to timestamp with time zone, p_night_start time without time zone DEFAULT '22:00:00'::time without time zone, p_night_end time without time zone DEFAULT '06:00:00'::time without time zone, p_tz text DEFAULT 'Europe/Madrid'::text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  with cfg as (
    select case when p_night_end > p_night_start
                then (p_night_end - p_night_start)
                else (interval '24 hours' - (p_night_start - p_night_end))
           end as dur
  ),
  win as (
    select ((d::date + p_night_start) at time zone p_tz) as ini,
           ((d::date + p_night_start) at time zone p_tz) + (select dur from cfg) as fin
    from generate_series(
           ((p_from at time zone p_tz)::date - 1),
           ((p_to   at time zone p_tz)::date + 1),
           interval '1 day') d
  )
  select coalesce(sum(greatest(0, extract(epoch from (
           least(p_to, w.fin) - greatest(p_from, w.ini)
         )) / 60.0)), 0)::numeric
  from win w;
$$;


--
-- Name: FUNCTION night_minutes_in_span(p_from timestamp with time zone, p_to timestamp with time zone, p_night_start time without time zone, p_night_end time without time zone, p_tz text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.night_minutes_in_span(p_from timestamp with time zone, p_to timestamp with time zone, p_night_start time without time zone, p_night_end time without time zone, p_tz text) IS 'F1.5 Minutos de la jornada que caen en franja nocturna (solapamiento real). Soporta franja que cruza medianoche.';


--
-- Name: normalize_ingredient_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_ingredient_name(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT trim(regexp_replace(
           regexp_replace(
             lower(public.unaccent(COALESCE(p_text, ''))),
             '\s*\([^)]*\)', '', 'g'          -- quita "(...)" aclaratorios
           ),
           '\s+', ' ', 'g'                    -- colapsa espacios
         ));
$$;


--
-- Name: notify_employee_courses(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_employee_courses(p_employee_id uuid, p_course_id uuid DEFAULT NULL::uuid) RETURNS TABLE(course_id uuid, notice_id uuid, result text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc uuid;
  r record;
  v_nid uuid;
BEGIN
  -- Resolver la cuenta del empleado (vía su local) y validar permiso.
  SELECT l.account_id INTO v_acc
  FROM employees e JOIN locations l ON l.id = e.location_id
  WHERE e.id = p_employee_id;

  IF v_acc IS NULL THEN
    RAISE EXCEPTION 'empleado no encontrado o sin local';
  END IF;

  IF NOT current_user_is_admin_or_manager_of(v_acc) THEN
    RAISE EXCEPTION 'sin acceso a la cuenta del empleado';
  END IF;

  -- Recorrer sus asignaciones de cursos publicados NO completados.
  FOR r IN
    SELECT ca.id AS assignment_id, ca.course_id
    FROM course_assignment ca
    JOIN course c ON c.id = ca.course_id
    WHERE ca.employee_id = p_employee_id
      AND ca.account_id = v_acc
      AND c.status = 'published'
      AND (p_course_id IS NULL OR ca.course_id = p_course_id)
      AND NOT EXISTS (
        SELECT 1 FROM course_attempt at
        WHERE at.assignment_id = ca.id AND at.passed
      )
  LOOP
    v_nid := enqueue_training_notice(r.assignment_id, 'manual', auth.uid());
    RETURN QUERY SELECT r.course_id, v_nid,
      CASE WHEN v_nid IS NULL THEN 'omitido (ya avisado/sin gancho/sin teléfono)'
           ELSE 'encolado' END;
  END LOOP;
END;
$$;


--
-- Name: offers_goal_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offers_goal_report(p_account_id uuid) RETURNS TABLE(brand_id uuid, brand_name text, channel_name text, location_id uuid, location_name text, target_daily numeric, ped_dia_7d numeric, ped_dia_prev7 numeric, pct_objetivo numeric, tendencia_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with base as (
    select t.brand_id, b.name as brand_name, sc.name as channel_name,
           t.location_id, l.name as location_name, t.target_daily
    from brand_channel_target t
    join sales_channel sc on sc.id = t.channel_id
    join locations l on l.id = t.location_id
    join brand b on b.id = t.brand_id and b.is_active
    where t.account_id = p_account_id and t.target_daily > 0
  ),
  rec as (
    select s.brand_id, sc.name as channel_name, s.location_id,
      count(*) filter (where s.created_at >= now() - interval '7 days') / 7.0 as s7,
      count(*) filter (where s.created_at >= now() - interval '14 days'
                         and s.created_at <  now() - interval '7 days') / 7.0 as s7p
    from sale s
    join sales_channel sc on sc.id = s.channel_id
    where s.account_id = p_account_id
      and s.created_at >= now() - interval '14 days'
      and s.order_status not in ('cancelled','rejected')
    group by s.brand_id, sc.name, s.location_id
  )
  select b.brand_id, b.brand_name, b.channel_name, b.location_id, b.location_name,
         b.target_daily,
         round(coalesce(r.s7, 0), 2)  as ped_dia_7d,
         round(coalesce(r.s7p, 0), 2) as ped_dia_prev7,
         round(100 * coalesce(r.s7, 0) / nullif(b.target_daily, 0), 1) as pct_objetivo,
         case when coalesce(r.s7p, 0) = 0 then null
              else round(100 * (coalesce(r.s7,0) - r.s7p) / r.s7p, 1) end as tendencia_pct
  from base b
  left join rec r on r.brand_id = b.brand_id
                 and r.channel_name = b.channel_name
                 and r.location_id = b.location_id
  order by (coalesce(r.s7,0) / nullif(b.target_daily,0)) nulls first, b.brand_name;
$$;


--
-- Name: omnibus_ref_price(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnibus_ref_price(p_menu_item_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select min(price)
  from menu_item_price_history
  where menu_item_id = p_menu_item_id
    and captured_at >= now() - interval '30 days';
$$;


--
-- Name: onboard_account(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboard_account(p_account_id uuid, p_plan_code text DEFAULT 'professional'::text, p_admin_user_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'trial'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan         billing_plans%ROWTYPE;
  v_status       text;
  v_sub_id       uuid;
  v_loc_id       uuid;
  v_unit_weight  uuid;
  v_unit_volume  uuid;
  v_unit_unit    uuid;
  v_sm           uuid;
  v_tpl          record;
  v_item_id      uuid;
  v_base_unit    uuid;
  v_fam_id       uuid;
  v_n_items      integer := 0;
  v_n_alg        integer := 0;
  v_alg_rows     integer := 0;
  v_n_dish_fam   integer := 0;
  v_n_chan       integer := 0;
  v_result       jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM accounts WHERE id = p_account_id) THEN
    RAISE EXCEPTION 'Cuenta % no existe', p_account_id;
  END IF;
  v_status := CASE WHEN p_status IN ('active','trial') THEN p_status ELSE 'trial' END;

  -- Unidades base GLOBALES por dimensión (account_id IS NULL).
  SELECT id INTO v_unit_weight FROM kitchen_unit WHERE account_id IS NULL AND is_base AND dimension='weight' LIMIT 1;
  SELECT id INTO v_unit_volume FROM kitchen_unit WHERE account_id IS NULL AND is_base AND dimension='volume' LIMIT 1;
  SELECT id INTO v_unit_unit   FROM kitchen_unit WHERE account_id IS NULL AND is_base AND dimension='unit'   LIMIT 1;
  IF v_unit_weight IS NULL OR v_unit_volume IS NULL OR v_unit_unit IS NULL THEN
    RAISE EXCEPTION 'Faltan unidades base globales (weight/volume/unit)';
  END IF;

  -- ── 1) SUSCRIPCIÓN (con estado comercial; idempotente) ──────────────────────
  SELECT * INTO v_plan FROM billing_plans WHERE code = p_plan_code;
  IF v_plan.id IS NULL THEN RAISE EXCEPTION 'Plan % no existe', p_plan_code; END IF;

  SELECT id INTO v_sub_id FROM subscriptions WHERE account_id = p_account_id LIMIT 1;
  IF v_sub_id IS NULL THEN
    INSERT INTO subscriptions (account_id, plan_id, status, billing_cycle,
                               trial_ends_at, current_period_start, current_period_end)
    VALUES (p_account_id, v_plan.id, v_status, COALESCE(v_plan.billing_cycle,'monthly'),
            CASE WHEN v_status='trial'
                 THEN now() + (COALESCE(v_plan.trial_days,14)||' days')::interval
                 ELSE NULL END,
            now(), now() + interval '1 month')
    RETURNING id INTO v_sub_id;

    FOREACH v_sm IN ARRAY COALESCE(v_plan.included_submodules, '{}'::uuid[])
    LOOP
      INSERT INTO subscription_items (subscription_id, submodule_id, status, starts_at)
      VALUES (v_sub_id, v_sm, 'active', now())
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  -- ── 2) LOCATION POR DEFECTO (su trigger siembra estaciones de cocina) ───────
  SELECT id INTO v_loc_id FROM locations WHERE account_id = p_account_id LIMIT 1;
  IF v_loc_id IS NULL THEN
    INSERT INTO locations (account_id, name, active, is_billable, clock_geofence_mode, clock_radius_m)
    VALUES (p_account_id, 'Principal', true, true, 'warn', 200)
    RETURNING id INTO v_loc_id;
  END IF;

  -- ── 3) KITCHEN_SETTINGS ─────────────────────────────────────────────────────
  -- (27/09) 'last_purchase' y 90 días: 'avg_window' ya no existe.
  IF NOT EXISTS (SELECT 1 FROM kitchen_settings WHERE account_id = p_account_id) THEN
    INSERT INTO kitchen_settings (
      account_id, currency, cost_strategy_default, cost_window_days_default,
      indirect_cost_pct_default, allow_negative_yield, price_rounding,
      ai_default_model, ai_escalation_enabled, transcription_language,
      audit_mode_default, audit_threshold_default, audit_shadow_min_samples,
      reliability_min_pct, max_recipe_depth_warning, version_alert_pct, photo_retention_days
    ) VALUES (
      p_account_id, 'EUR', 'last_purchase', 90,
      0, false, 'none',
      'claude-sonnet-4-6', true, 'es',
      'shadow', 0.15, 5,
      70, 6, 20, 365
    );
  END IF;

  -- ── 4) STORAGE_AREA por defecto ─────────────────────────────────────────────
  IF NOT EXISTS (SELECT 1 FROM storage_area WHERE account_id = p_account_id) THEN
    INSERT INTO storage_area (account_id, location_id, name, position, active)
    VALUES (p_account_id, v_loc_id, 'Almacén principal', 0, true);
  END IF;

  -- ── 5) SALES_CHANNEL (Salón + plataformas + tienda) ─────────────────────────
  INSERT INTO sales_channel (account_id, name, slug, channel_type, is_active)
  SELECT p_account_id, x.name, x.slug, x.channel_type, true
  FROM (VALUES
    ('Salón',   'salon',   'dine_in'),
    ('Glovo',   'glovo',   'delivery'),
    ('JustEat', 'justeat', 'delivery'),
    ('Uber',    'uber',    'delivery'),
    ('Shop',    'shop',    'takeaway')
  ) AS x(name, slug, channel_type)
  WHERE NOT EXISTS (
    SELECT 1 FROM sales_channel sc WHERE sc.account_id = p_account_id AND sc.slug = x.slug
  );
  GET DIAGNOSTICS v_n_chan = ROW_COUNT;

  -- ── 6) FAMILIAS DE PLATO desde dish_family_template ─────────────────────────
  INSERT INTO recipe_family (account_id, scope, code, name, icon, position, template_id, is_active)
  SELECT p_account_id, 'dish', dft.code, dft.name_es, dft.icon, dft.position, dft.id, true
  FROM dish_family_template dft
  WHERE NOT EXISTS (
    SELECT 1 FROM recipe_family rf
    WHERE rf.account_id = p_account_id AND rf.scope = 'dish' AND rf.code = dft.code
  );
  GET DIAGNOSTICS v_n_dish_fam = ROW_COUNT;

  -- ── 7) SIEMBRA DEL MASTER (ingredient_template -> recipe_item type='raw') ────
  FOR v_tpl IN SELECT * FROM ingredient_template WHERE is_active LOOP
    IF EXISTS (
      SELECT 1 FROM recipe_item ri
      WHERE ri.account_id = p_account_id AND ri.template_code = v_tpl.code
    ) THEN CONTINUE; END IF;

    v_base_unit := CASE lower(COALESCE(v_tpl.default_base_dimension,'weight'))
                     WHEN 'volume' THEN v_unit_volume
                     WHEN 'unit'   THEN v_unit_unit
                     ELSE v_unit_weight
                   END;

    v_fam_id := NULL;
    IF nullif(v_tpl.family_code,'') IS NOT NULL THEN
      SELECT rf.id INTO v_fam_id FROM recipe_family rf
      WHERE rf.account_id = p_account_id AND rf.scope = 'ingredient' AND rf.code = v_tpl.family_code
      LIMIT 1;
    END IF;

    INSERT INTO recipe_item (
      account_id, name, type, source, base_unit_id, family_id,
      template_code, template_version,
      kitchen_photo_url, conservation_type, default_waste_pct,
      shelf_life_days, nutrition, cost_strategy, is_active,
      is_purchasable, is_stockable, is_sellable, needs_review
    ) VALUES (
      p_account_id, COALESCE(v_tpl.name_es, v_tpl.name_en, 'Ingrediente'), 'raw', 'template_global',
      v_base_unit, v_fam_id,
      v_tpl.code, v_tpl.version,
      v_tpl.photo_url, v_tpl.conservation_type, v_tpl.default_waste_pct,
      v_tpl.shelf_life_days, v_tpl.nutrition,
      -- (27/09) kitchen_settings y recipe_item hablan ya el mismo idioma.
      CASE (SELECT cost_strategy_default FROM kitchen_settings WHERE account_id = p_account_id)
        WHEN 'average_weighted' THEN 'average_weighted'
        WHEN 'fixed'            THEN 'fixed'
        ELSE 'last_purchase'
      END,
      true, true, true, false, false
    ) RETURNING id INTO v_item_id;
    v_n_items := v_n_items + 1;

    -- ── 8) ALÉRGENOS heredados del master ─────────────────────────────────────
    INSERT INTO recipe_item_allergen (recipe_item_id, allergen_code, state, source)
    SELECT v_item_id, ita.allergen_code, ita.state, 'inherited'
    FROM ingredient_template_allergen ita
    WHERE ita.template_id = v_tpl.id
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_alg_rows = ROW_COUNT;
    v_n_alg := v_n_alg + v_alg_rows;
  END LOOP;

  -- ── 9) USUARIO ADMIN (idempotente; create_account_tx ya pudo crearlo) ───────
  IF p_admin_user_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM user_profiles WHERE account_id = p_account_id AND user_id = p_admin_user_id
    ) THEN
      INSERT INTO user_profiles (account_id, user_id, role, active)
      VALUES (p_account_id, p_admin_user_id, 'admin', true);
    END IF;
  END IF;

  v_result := jsonb_build_object(
    'account_id', p_account_id, 'plan', p_plan_code, 'status', v_status,
    'subscription_id', v_sub_id, 'location_id', v_loc_id,
    'channels_seeded', v_n_chan, 'dish_families_seeded', v_n_dish_fam,
    'ingredients_seeded', v_n_items, 'allergens_seeded', v_n_alg,
    'admin_linked', (p_admin_user_id IS NOT NULL)
  );
  RETURN v_result;
END;
$$;


--
-- Name: order_for_print(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_for_print(p_device_token text, p_sale_id uuid, p_fire_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device      kds_device;
  v_account_id  uuid;
  v_result      jsonb;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'order_for_print: token no válido';
  end if;
  v_account_id := v_device.account_id;

  -- Pobla descuento por línea (Last + HubRise) just-in-time. No falla si no hay.
  begin
    perform public.fill_line_discounts(p_sale_id);
    -- C9 L1: acuña los tokens de etiqueta si no existen. Idempotente: la
    -- reimpresion pasa por aqui otra vez y devuelve LOS MISMOS.
    perform public.ensure_label_tokens(p_sale_id);
  exception when others then
    null;  -- el ticket no se cae por un descuento mal formado
  end;

  with v as (
    select s.id, s.external_ref, s.external_tab_ref,
           s.platform_order_code, s.pos_short_code, s.platform_order_ref,
           s.order_status, s.status, s.service_type, s.source,
           s.brand_id, s.channel_id, s.external_channel_text,
           s.customer_name, s.customer_phone, s.delivery_address,
           s.expected_time, s.customer_note, s.delivery_address_fixed, s.delivery_address_fixed_by, s.customer_phone_code, s.delivery_instructions, s.order_customer_note, s.delivery_by_reason,
           s.total, s.paid, s.payment_method, s.discount_amount, s.delivery_cost,
           coalesce(s.opened_at, s.sold_at, s.created_at) as entro_at, s.raw_tab
    from sale s
    where s.id = p_sale_id and s.account_id = v_account_id
  ),
  notas as (
    select v.id as sale_id, (prod->>'organizationProductId') as ext_pid,
           nullif(btrim(prod->>'comments'), '') as note
    from v
    cross join lateral (select safe_jsonb(v.raw_tab) as tab) rt
    cross join lateral (select coalesce(rt.tab -> 'products', rt.tab -> 'bills' -> 0 -> 'products') as products) p
    cross join lateral jsonb_array_elements(case when jsonb_typeof(p.products)='array' then p.products else '[]'::jsonb end) as prod
    where nullif(btrim(prod->>'comments'),'') is not null and (prod->>'organizationProductId') is not null
  ),
  padres as (
    select sl.sale_id, sl.id as line_id, btrim(regexp_replace(regexp_replace(sl.product_name, '[‍️←-⇿⌀-⏿①-⓿─-➿⬀-⯿\U0001F000-\U0001FAFF]', '', 'g'), '\s{2,}', ' ', 'g')) as product_name, sl.quantity, sl.line_type,
           sl.menu_item_id, sl.external_product_id, sl.unit_price, sl.line_total, sl.kitchen_note,
           sl.original_unit_price, sl.discount_label,
           mi.category as menu_category, df.name as family, df.color as family_color, df.icon as family_icon,
           array(select case a.allergen_code when 'gluten' then 'Gluten' when 'milk' then 'Lácteos' when 'eggs' then 'Huevos' when 'sulphites' then 'Sulfitos' when 'mustard' then 'Mostaza' when 'soy' then 'Soja' when 'sesame' then 'Sésamo' when 'celery' then 'Apio' when 'nuts' then 'Frutos de cáscara' when 'fish' then 'Pescado' when 'molluscs' then 'Moluscos' when 'crustaceans' then 'Crustáceos' when 'peanuts' then 'Cacahuetes' when 'lupin' then 'Altramuces' else initcap(a.allergen_code) end from recipe_item_allergen a where a.recipe_item_id = ri.id and a.state='contains') as allergens
    from sale_line sl
    left join menu_item mi on mi.id = sl.menu_item_id
    left join recipe_item ri on ri.id = mi.recipe_item_id
    left join recipe_family df on df.id = ri.family_id
    where sl.sale_id = p_sale_id and sl.parent_sale_line_id is null
      -- TPV sala (S1): con envío, solo sus líneas; nunca las anuladas.
      and (p_fire_id is null or sl.fire_id = p_fire_id)
      and sl.voided_at is null
  ),
  hijas as (
    select sl.parent_sale_line_id, sl.sale_id, sl.id as line_id, btrim(regexp_replace(regexp_replace(sl.product_name, '[‍️←-⇿⌀-⏿①-⓿─-➿⬀-⯿\U0001F000-\U0001FAFF]', '', 'g'), '\s{2,}', ' ', 'g')) as product_name, sl.quantity,
           sl.line_type, sl.external_product_id, sl.menu_item_id, mg.group_type,
           dfh.name as family, dfh.color as family_color, mih.category as menu_category,
           case when sl.line_type='combo_item' then 1 when mg.group_type='removal' then 2
                when mg.group_type='extras' then 3 when mg.group_type in ('choice','side') then 4
                when mg.group_type in ('cross_sell','info') then 6 else 5 end as sort_rank
    from sale_line sl
    left join modifier_option mo on mo.id = sl.modifier_option_id
    left join modifier_group mg on mg.id = mo.modifier_group_id
    left join menu_item mih on mih.id = sl.menu_item_id
    left join recipe_item rih on rih.id = mih.recipe_item_id
    left join recipe_family dfh on dfh.id = rih.family_id
    where sl.sale_id = p_sale_id and sl.parent_sale_line_id is not null
  )
  select to_jsonb(t) into v_result from (
    select v.id as sale_id, v.external_ref, v.external_tab_ref,
           v.platform_order_code, v.pos_short_code, v.platform_order_ref, v.order_status, v.status, v.service_type, v.source,
           b.name as brand, b.logo_url as brand_logo_url, b.color as brand_color,
           b.shop_url as brand_shop_url, b.qr_caption as brand_qr_caption, b.ownership_type as brand_ownership_type,
           public.label_token_bolsa(v.id) as bag_token,
           coalesce(ch.name, v.external_channel_text) as channel, v.channel_id,
           v.customer_name, v.customer_phone, v.delivery_address, v.expected_time, v.customer_note, v.delivery_address_fixed, v.delivery_address_fixed_by, v.customer_phone_code, v.delivery_instructions, v.order_customer_note, v.delivery_by_reason,
           v.total, v.paid, v.payment_method, v.discount_amount, v.delivery_cost, v.entro_at,
           safe_jsonb(v.raw_tab)->'delivery' as delivery_detail,
           (select jsonb_agg(jsonb_build_object(
              'line_id', l.line_id, 'name', l.product_name, 'qty', l.quantity, 'menu_item_id', l.menu_item_id,
              'unit_tokens', public.label_tokens_for(l.line_id),
              'unit_price', l.unit_price, 'line_total', l.line_total,
              'original_unit_price', l.original_unit_price, 'discount_label', l.discount_label,
              'allergens', l.allergens,
              'family', l.family, 'family_color', l.family_color, 'family_icon', l.family_icon,
              'menu_category', l.menu_category, 'has_recipe', (l.menu_item_id is not null),
              'customer_note', coalesce((select n.note from notas n where n.sale_id = l.sale_id and n.ext_pid = l.external_product_id limit 1), l.kitchen_note),
              'children', coalesce((select jsonb_agg(jsonb_build_object(
                  'line_id', h.line_id, 'name', h.product_name, 'qty', h.quantity, 'line_type', h.line_type,
                  'unit_tokens', public.label_tokens_for(h.line_id),
                  'group_type', h.group_type, 'menu_item_id', h.menu_item_id, 'family', h.family,
                  'family_color', h.family_color, 'menu_category', h.menu_category
                ) order by h.sort_rank, h.product_name) from hijas h where h.parent_sale_line_id = l.line_id), '[]'::jsonb)
            ) order by l.product_name) from padres l) as lineas
    from v
    left join brand b on b.id = v.brand_id
    left join sales_channel ch on ch.id = v.channel_id
  ) t;

  -- TPV sala (S1): mesa, zona, comensales y envío para la cabecera del ticket.
  if v_result is not null then
    v_result := v_result || coalesce((
      select jsonb_build_object(
        'table_name', dt.name, 'zone_name', z.name, 'covers', s.covers,
        'served_by_name', s.served_by_name,
        'fire_number', f.fire_number, 'fired_at', f.fired_at,
        'fire_count', (select count(*) from sale_fire ff where ff.sale_id = s.id))
      from sale s
      join dining_table dt on dt.id = s.table_id
      join dining_zone z on z.id = dt.zone_id
      left join sale_fire f on f.id = p_fire_id and f.sale_id = s.id
      where s.id = p_sale_id and s.account_id = v_account_id), '{}'::jsonb);
  end if;

  return v_result;
end;
$$;


--
-- Name: orders_feed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orders_feed(p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id  uuid;
  v_location_id uuid := p_location_id;
  v_tz          text;
  c_business_day_cutoff_hours constant int := 4;
  v_cutoff      interval := make_interval(hours => c_business_day_cutoff_hours);
  v_day_start   timestamptz;
  v_result      jsonb;
begin
  if v_location_id is null then
    raise exception 'orders_feed: falta location';
  end if;
  select account_id into v_account_id from locations where id = v_location_id;
  if v_account_id is null then
    raise exception 'orders_feed: ubicación inexistente';
  end if;
  if not belongs_to_account(v_account_id) then
    raise exception 'orders_feed: sin acceso a esta ubicación';
  end if;

  select coalesce(a.timezone, 'Europe/Madrid') into v_tz
  from accounts a where a.id = v_account_id;

  v_day_start := (
    date_trunc('day', (now() at time zone v_tz) - v_cutoff) + v_cutoff
  ) at time zone v_tz;

  with vivos as (
    select s.id, s.external_ref, s.external_tab_ref,
           s.platform_order_code, s.pos_short_code, s.platform_order_ref,
           s.order_status, s.status, s.service_type, s.source,
           s.brand_id, s.channel_id, s.external_channel_text,
           s.customer_name, s.customer_phone, s.delivery_address,
           s.expected_time, s.customer_note, s.delivery_address_fixed, s.delivery_address_fixed_by, s.customer_phone_code, s.delivery_instructions, s.order_customer_note, s.delivery_by_reason,
           s.total, s.paid, s.payment_method, s.discount_amount, s.delivery_cost,
           -- Campos de reparto (para la fila plegable de la tarjeta).
           s.dispatch_mode, s.carrier_code, s.delivery_state,
           s.rider_name, s.rider_phone, s.eta_pickup, s.eta_delivery, s.transport_price, s.dispatch_error,
           -- (+ rider Catcher) tipo de vehículo, última posición vista y flag de asignación.
           s.rider_transport_type, s.rider_lat, s.rider_lng, s.rider_seen_at, s.has_courier,
           -- Hitos de tiempo: KPI de cocina (accepted_at/ready_at) y reparto.
           s.accepted_at, s.ready_at, s.handed_to_courier_at, s.delivered_at,
           s.opened_at, s.closed_at, s.cancelled_at, s.sold_at, s.raw_tab,
           coalesce(s.opened_at, s.sold_at, s.created_at) as entro_at
    from sale s
    where s.location_id = v_location_id
      and s.account_id  = v_account_id
      and s.order_status is not null
      -- GUARDARRAÍL DE PAGO: no mostrar un pedido del Shop pagado online cuyo
      -- pago no esté confirmado (cubre new, accepted, in_preparation, etc.).
      and not (
        s.source = 'folvy_shop'
        and s.payment_method = 'stripe'
        and coalesce(s.payment_status,'pending') <> 'paid'
      )
      and (
        s.order_status not in ('completed','rejected','cancelled','delivery_failed')
        or (
             coalesce(s.closed_at, s.cancelled_at, s.sold_at, s.opened_at) >= v_day_start
         and coalesce(s.closed_at, s.cancelled_at, s.sold_at, s.opened_at) <  v_day_start + interval '1 day'
        )
      )
  ),
  notas as (
    select v.id as sale_id,
           (prod->>'organizationProductId') as ext_pid,
           nullif(btrim(prod->>'comments'), '') as note
    from vivos v
    cross join lateral (select safe_jsonb(v.raw_tab) as tab) rt
    cross join lateral (
      select coalesce(rt.tab -> 'products', rt.tab -> 'bills' -> 0 -> 'products') as products
    ) p
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(p.products) = 'array' then p.products else '[]'::jsonb end
    ) as prod
    where nullif(btrim(prod->>'comments'), '') is not null
      and (prod->>'organizationProductId') is not null
  ),
  padres as (
    select sl.sale_id, sl.id as line_id, sl.product_name, sl.quantity,
           sl.line_type, sl.menu_item_id, sl.external_product_id,
           sl.unit_price, sl.line_total, sl.kitchen_note,
           coalesce(ls.marked, false) as marked,
           mi.category               as menu_category,
           df.name                   as family,
           df.color                  as family_color,
           df.icon                   as family_icon,
           array(select allergen_code from recipe_item_allergen a
                  where a.recipe_item_id = ri.id and a.state = 'contains') as allergens
    from sale_line sl
    left join menu_item mi on mi.id = sl.menu_item_id
    left join recipe_item ri on ri.id = mi.recipe_item_id
    left join recipe_family df on df.id = ri.family_id
    left join kds_line_state ls on ls.sale_line_id = sl.id
    where sl.sale_id in (select id from vivos)
      and sl.parent_sale_line_id is null
  ),
  hijas as (
    select sl.parent_sale_line_id, sl.sale_id, sl.id as line_id,
           sl.product_name, sl.quantity, sl.line_type, sl.external_product_id,
           sl.menu_item_id,
           mg.group_type,
           dfh.name  as family,
           dfh.color as family_color,
           mih.category as menu_category,
           case
             when sl.line_type = 'combo_item'                      then 1
             when mg.group_type = 'removal'                        then 2
             when mg.group_type = 'extras'                         then 3
             when mg.group_type in ('choice','side')               then 4
             when mg.group_type in ('cross_sell','info')           then 6
             else 5
           end as sort_rank
    from sale_line sl
    left join modifier_option mo on mo.id = sl.modifier_option_id
    left join modifier_group  mg on mg.id = mo.modifier_group_id
    left join menu_item   mih on mih.id = sl.menu_item_id
    left join recipe_item rih on rih.id = mih.recipe_item_id
    left join recipe_family dfh on dfh.id = rih.family_id
    where sl.sale_id in (select id from vivos)
      and sl.parent_sale_line_id is not null
  ),
  tickets as (
    select v.id as sale_id, v.external_ref, v.external_tab_ref,
           v.platform_order_code, v.pos_short_code, v.platform_order_ref,
           v.order_status, v.status, v.service_type, v.source,
           b.name as brand,
           b.logo_url as brand_logo_url, b.color as brand_color,
           b.shop_url as brand_shop_url, b.qr_caption as brand_qr_caption,
           b.ownership_type as brand_ownership_type,
           (v.service_type = 'own_delivery') as brand_own_delivery,
           coalesce(ch.name, v.external_channel_text) as channel,
           v.channel_id,
           v.customer_name, v.customer_phone, v.delivery_address,
           v.expected_time, v.customer_note, v.delivery_address_fixed, v.delivery_address_fixed_by, v.customer_phone_code, v.delivery_instructions, v.order_customer_note, v.delivery_by_reason,
           v.total, v.paid, v.payment_method, v.discount_amount, v.delivery_cost,
           -- Reparto (espejo directo de sale).
           v.dispatch_mode, v.carrier_code, v.delivery_state,
           v.rider_name, v.rider_phone, v.eta_pickup, v.eta_delivery, v.transport_price, v.dispatch_error,
           -- (+ rider Catcher)
           v.rider_transport_type, v.rider_lat, v.rider_lng, v.rider_seen_at, v.has_courier,
           v.accepted_at, v.ready_at, v.handed_to_courier_at, v.delivered_at,
           v.entro_at,
           round(extract(epoch from (now() - v.entro_at)) / 60.0)::int as minutos,
           coalesce((select jsonb_agg(jsonb_build_object(
                'line_id', l.line_id, 'name', l.product_name, 'qty', l.quantity,
                'menu_item_id', l.menu_item_id,
                'unit_price', l.unit_price, 'line_total', l.line_total,
                'marked', l.marked, 'allergens', l.allergens,
                'family', l.family, 'family_color', l.family_color,
                'family_icon', l.family_icon, 'menu_category', l.menu_category,
                'has_recipe', (l.menu_item_id is not null),
                'customer_note', coalesce((select n.note from notas n where n.sale_id = l.sale_id and n.ext_pid = l.external_product_id limit 1), l.kitchen_note),
                'children', coalesce((
                  select jsonb_agg(jsonb_build_object(
                           'line_id', h.line_id, 'name', h.product_name, 'qty', h.quantity,
                           'line_type', h.line_type,
                           'group_type', h.group_type,
                           'menu_item_id', h.menu_item_id,
                           'family', h.family, 'family_color', h.family_color,
                           'menu_category', h.menu_category,
                           'customer_note', (
                             select n2.note from notas n2
                              where n2.sale_id = h.sale_id and n2.ext_pid = h.external_product_id limit 1
                           )
                         ) order by h.sort_rank, h.product_name)
                  from hijas h where h.parent_sale_line_id = l.line_id
                ), '[]'::jsonb)
            ) order by l.product_name)
            from padres l where l.sale_id = v.id), '[]'::jsonb) as lineas
    from vivos v
    left join brand b on b.id = v.brand_id
    left join sales_channel ch on ch.id = v.channel_id
  )
  select jsonb_build_object(
    'location_id', v_location_id,
    'now', now(),
    'orders', coalesce(
      jsonb_agg(to_jsonb(t) order by t.entro_at) filter (where t.sale_id is not null),
      '[]'::jsonb)
  ) into v_result
  from tickets t;

  return v_result;
end;
$$;


--
-- Name: orders_feed_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orders_feed_by_token(p_device_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device      kds_device;
  v_account_id  uuid;
  v_location_id uuid;
  v_result      jsonb;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'orders_feed_by_token: token no válido';
  end if;
  
  v_account_id  := v_device.account_id;
  v_location_id := v_device.location_id;
  if v_location_id is null then
    raise exception 'orders_feed_by_token: el dispositivo no tiene local asignado';
  end if;

  with vivos as (
    select s.id, s.external_ref, s.external_tab_ref,
           s.platform_order_code, s.pos_short_code, s.platform_order_ref,
           s.order_status, s.status, s.service_type, s.source,
           s.brand_id, s.channel_id, s.external_channel_text,
           s.customer_name, s.customer_phone, s.delivery_address,
           s.expected_time, s.customer_note, s.delivery_address_fixed, s.delivery_address_fixed_by, s.customer_phone_code, s.delivery_instructions, s.order_customer_note, s.delivery_by_reason,
           s.total, s.paid, s.payment_method, s.discount_amount, s.delivery_cost,
           -- Reparto (paridad con orders_feed) + campos de rider de Catcher.
           s.dispatch_mode, s.carrier_code, s.delivery_state,
           s.rider_name, s.rider_phone, s.eta_pickup, s.eta_delivery, s.transport_price, s.dispatch_error,
           s.rider_transport_type, s.rider_lat, s.rider_lng, s.rider_seen_at, s.has_courier,
           -- Hitos de tiempo: KPI de cocina (accepted_at/ready_at) y reparto.
           s.accepted_at, s.ready_at, s.handed_to_courier_at, s.delivered_at,
           s.opened_at, s.closed_at, s.cancelled_at, s.sold_at, s.raw_tab,
           coalesce(s.opened_at, s.sold_at, s.created_at) as entro_at
    from sale s
    where s.location_id = v_location_id
      and s.account_id  = v_account_id
      and s.order_status is not null
      -- GUARDARRAÍL DE PAGO (idéntico a orders_feed): no mostrar en la tablet un
      -- pedido del Shop pagado online cuyo pago no esté confirmado.
      and not (
        s.source = 'folvy_shop'
        and s.payment_method = 'stripe'
        and coalesce(s.payment_status,'pending') <> 'paid'
      )
      and (
        s.order_status not in ('completed','rejected','cancelled','delivery_failed')
        or coalesce(s.closed_at, s.cancelled_at, s.sold_at, s.opened_at) >= now() - interval '2 hours'
      )
  ),
  notas as (
    select v.id as sale_id,
           (prod->>'organizationProductId') as ext_pid,
           nullif(btrim(prod->>'comments'), '') as note
    from vivos v
    cross join lateral (select safe_jsonb(v.raw_tab) as tab) rt
    cross join lateral (
      select coalesce(rt.tab -> 'products', rt.tab -> 'bills' -> 0 -> 'products') as products
    ) p
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(p.products) = 'array' then p.products else '[]'::jsonb end
    ) as prod
    where nullif(btrim(prod->>'comments'), '') is not null
      and (prod->>'organizationProductId') is not null
  ),
  padres as (
    select sl.sale_id, sl.id as line_id, sl.product_name, sl.quantity,
           sl.line_type, sl.menu_item_id, sl.external_product_id,
           sl.unit_price, sl.line_total, sl.kitchen_note,
           coalesce(ls.marked, false) as marked,
           mi.category               as menu_category,
           df.name                   as family,
           df.color                  as family_color,
           df.icon                   as family_icon,
           array(select allergen_code from recipe_item_allergen a
                  where a.recipe_item_id = ri.id and a.state = 'contains') as allergens
    from sale_line sl
    left join menu_item mi on mi.id = sl.menu_item_id
    left join recipe_item ri on ri.id = mi.recipe_item_id
    left join recipe_family df on df.id = ri.family_id
    left join kds_line_state ls on ls.sale_line_id = sl.id
    where sl.sale_id in (select id from vivos)
      and sl.parent_sale_line_id is null
  ),
  hijas as (
    select sl.parent_sale_line_id, sl.sale_id, sl.id as line_id,
           sl.product_name, sl.quantity, sl.line_type, sl.external_product_id,
           sl.menu_item_id,
           mg.group_type,
           dfh.name  as family,
           dfh.color as family_color,
           mih.category as menu_category,
           case
             when sl.line_type = 'combo_item'                      then 1
             when mg.group_type = 'removal'                        then 2
             when mg.group_type = 'extras'                         then 3
             when mg.group_type in ('choice','side')               then 4
             when mg.group_type in ('cross_sell','info')           then 6
             else 5
           end as sort_rank
    from sale_line sl
    left join modifier_option mo on mo.id = sl.modifier_option_id
    left join modifier_group  mg on mg.id = mo.modifier_group_id
    left join menu_item   mih on mih.id = sl.menu_item_id
    left join recipe_item rih on rih.id = mih.recipe_item_id
    left join recipe_family dfh on dfh.id = rih.family_id
    where sl.sale_id in (select id from vivos)
      and sl.parent_sale_line_id is not null
  ),
  tickets as (
    select v.id as sale_id, v.external_ref, v.external_tab_ref,
           v.platform_order_code, v.pos_short_code, v.platform_order_ref,
           v.order_status, v.status, v.service_type, v.source,
           b.name as brand,
           b.logo_url as brand_logo_url, b.color as brand_color,
           b.shop_url as brand_shop_url, b.qr_caption as brand_qr_caption,
           b.ownership_type as brand_ownership_type,
           (v.service_type = 'own_delivery') as brand_own_delivery,
           coalesce(ch.name, v.external_channel_text) as channel,
           v.channel_id,
           v.customer_name, v.customer_phone, v.delivery_address,
           v.expected_time, v.customer_note, v.delivery_address_fixed, v.delivery_address_fixed_by, v.customer_phone_code, v.delivery_instructions, v.order_customer_note, v.delivery_by_reason,
           v.total, v.paid, v.payment_method, v.discount_amount, v.delivery_cost,
           -- Reparto (paridad con orders_feed) + campos de rider de Catcher.
           v.dispatch_mode, v.carrier_code, v.delivery_state,
           v.rider_name, v.rider_phone, v.eta_pickup, v.eta_delivery, v.transport_price, v.dispatch_error,
           v.rider_transport_type, v.rider_lat, v.rider_lng, v.rider_seen_at, v.has_courier,
           v.accepted_at, v.ready_at, v.handed_to_courier_at, v.delivered_at,
           v.entro_at,
           round(extract(epoch from (now() - v.entro_at)) / 60.0)::int as minutos,
           coalesce((select jsonb_agg(jsonb_build_object(
                'line_id', l.line_id, 'name', l.product_name, 'qty', l.quantity,
                'menu_item_id', l.menu_item_id,
                'unit_price', l.unit_price, 'line_total', l.line_total,
                'marked', l.marked, 'allergens', l.allergens,
                'family', l.family, 'family_color', l.family_color,
                'family_icon', l.family_icon, 'menu_category', l.menu_category,
                'has_recipe', (l.menu_item_id is not null),
                'customer_note', coalesce((select n.note from notas n where n.sale_id = l.sale_id and n.ext_pid = l.external_product_id limit 1), l.kitchen_note),
                'children', coalesce((
                  select jsonb_agg(jsonb_build_object(
                           'line_id', h.line_id, 'name', h.product_name, 'qty', h.quantity,
                           'line_type', h.line_type,
                           'group_type', h.group_type,
                           'menu_item_id', h.menu_item_id,
                           'family', h.family, 'family_color', h.family_color,
                           'menu_category', h.menu_category,
                           'customer_note', (
                             select n2.note from notas n2
                              where n2.sale_id = h.sale_id and n2.ext_pid = h.external_product_id limit 1
                           )
                         ) order by h.sort_rank, h.product_name)
                  from hijas h where h.parent_sale_line_id = l.line_id
                ), '[]'::jsonb)
            ) order by l.product_name)
            from padres l where l.sale_id = v.id), '[]'::jsonb) as lineas
    from vivos v
    left join brand b on b.id = v.brand_id
    left join sales_channel ch on ch.id = v.channel_id
  )
  select jsonb_build_object(
    'location_id', v_location_id,
    'now', now(),
    'orders', coalesce(
      jsonb_agg(to_jsonb(t) order by t.entro_at) filter (where t.sale_id is not null),
      '[]'::jsonb)
  ) into v_result
  from tickets t;

  return v_result;
end;
$$;


--
-- Name: parte_del_dia(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parte_del_dia(p_account_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_dia date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'parte_del_dia: sin acceso a la cuenta %', p_account_id;
  end if;
  return public._parte_del_dia_raw(p_account_id, p_location_id, p_dia);
end;
$$;


--
-- Name: FUNCTION parte_del_dia(p_account_id uuid, p_location_id uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.parte_del_dia(p_account_id uuid, p_location_id uuid, p_dia date) IS 'El parte del día: lo vendido, si cuadra con el almacén, qué no descontó y por qué, y el cruce con las plataformas. Día natural de Madrid por sold_at. Encargo del 16/09 §3.1.';


--
-- Name: parte_plataformas_refresh(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parte_plataformas_refresh(p_account_id uuid, p_dia date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ced integer; v_pro integer;
begin
  v_ced := public._parte_plataformas_cedidas(p_account_id, p_dia);
  v_pro := public._parte_plataformas_propias(p_account_id, p_dia);
  return jsonb_build_object('dia', p_dia, 'cedidas', v_ced, 'propias', v_pro);
end;
$$;


--
-- Name: FUNCTION parte_plataformas_refresh(p_account_id uuid, p_dia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.parte_plataformas_refresh(p_account_id uuid, p_dia date) IS 'Rehace el cruce de un día para una cuenta. Idempotente. §3.3.';


--
-- Name: party_add_role(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_add_role(p_party uuid, p_role text, p_config jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid := public.party_cuenta(p_party); v_canal uuid; n int := 0;
begin
  if p_role not in ('customer', 'platform', 'brand_partner') then
    raise exception 'Desde aquí solo se añade como cliente, plataforma o socio (como proveedor llega con su ficha de Cocina).' using errcode = '22023';
  end if;
  if p_role = 'platform' then
    v_canal := nullif(p_config->>'channelId', '')::uuid;
    insert into party_role (account_id, party_id, role, channel_id, settlement_every, commission_pct, created_by)
    values (v_cuenta, p_party, 'platform', v_canal, nullif(p_config->>'settlementEvery', ''), nullif(p_config->>'commissionPct', '')::numeric, auth.uid())
    on conflict (party_id, role) do update set channel_id = excluded.channel_id, settlement_every = excluded.settlement_every,
                                                commission_pct = excluded.commission_pct;
    if v_canal is not null then
      update channel_settlement set party_id = p_party
       where account_id = v_cuenta and channel_id = v_canal and party_id is distinct from p_party;
      get diagnostics n = row_count;
    end if;
  elsif p_role = 'brand_partner' then
    insert into party_role (account_id, party_id, role, contribution_kinds, created_by)
    values (v_cuenta, p_party, 'brand_partner',
            coalesce((select array_agg(x) from jsonb_array_elements_text(p_config->'contributionKinds') x), array['marketing', 'packaging']), auth.uid())
    on conflict (party_id, role) do update set contribution_kinds = excluded.contribution_kinds;
  else
    insert into party_role (account_id, party_id, role, created_by) values (v_cuenta, p_party, 'customer', auth.uid())
    on conflict (party_id, role) do nothing;
    insert into customer_fiscal (party_id, account_id) values (p_party, v_cuenta) on conflict (party_id) do nothing;
  end if;
  return jsonb_build_object('party_id', p_party, 'role', p_role, 'liquidaciones_enlazadas', n);
end $$;


--
-- Name: party_al_borrar_proveedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_al_borrar_proveedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_party uuid;
begin
  delete from public.party_role where supplier_id = old.id returning party_id into v_party;
  if v_party is not null and not exists (select 1 from public.party_role r where r.party_id = v_party) then
    delete from public.party where id = v_party;
  end if;
  return old;
end $$;


--
-- Name: party_cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_cuenta(p_party uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v uuid;
begin
  select account_id into v from party where id = p_party;
  if v is null then raise exception 'Ese tercero no existe.' using errcode = 'P0002'; end if;
  if not current_user_is_admin_or_manager_of(v) then
    raise exception 'No puedes cambiar este tercero.' using errcode = '42501';
  end if;
  return v;
end $$;


--
-- Name: party_desde_proveedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_desde_proveedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_party uuid; v_nif text := public.party_nif(new.tax_id); v_solo boolean;
begin
  if tg_op = 'INSERT' then
    if v_nif is not null then
      select id into v_party from party where account_id = new.account_id and tax_id = v_nif;
      -- Dos proveedores con el mismo NIF (lo permite Cocina): el segundo no
      -- puede ser el mismo papel del mismo tercero. Tercero aparte, sin NIF,
      -- y el agente lo enseña como NIF repetido.
      if v_party is not null and exists (select 1 from party_role where party_id = v_party and role = 'supplier') then
        v_party := null; v_nif := null;
      end if;
    end if;
    if v_party is null then
      insert into party (account_id, name, tax_id, archived_at, source, created_by, created_by_name)
      values (new.account_id, new.name, v_nif, new.archived_at, 'supplier', new.created_by, new.created_by_name)
      returning id into v_party;
    end if;
    insert into party_role (account_id, party_id, role, supplier_id, created_by)
    values (new.account_id, v_party, 'supplier', new.id, new.created_by)
    on conflict (party_id, role) do nothing;
    return new;
  end if;
  select r.party_id, (select count(*) from party_role x where x.party_id = r.party_id) = 1
    into v_party, v_solo
    from party_role r where r.supplier_id = new.id;
  if v_party is null then return new; end if;
  if v_solo then
    update party set name = new.name, archived_at = new.archived_at where id = v_party
       and (name, archived_at) is distinct from (new.name, new.archived_at);
  end if;
  -- El NIF: solo si no choca con otro tercero (si choca, lo ve el agente).
  if v_nif is distinct from public.party_nif(old.tax_id)
     and not exists (select 1 from party where account_id = new.account_id and tax_id = v_nif and id <> v_party) then
    update party set tax_id = v_nif where id = v_party;
  end if;
  return new;
exception when others then
  -- El albarán no se para por el tercero: queda sin enlazar y el agente lo dice.
  raise warning 'C03 · el proveedor % no se ha podido enlazar con su tercero: %', new.id, sqlerrm;
  return new;
end $$;


--
-- Name: party_merge_do(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_merge_do(p_queda uuid, p_se_va uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.party_cuenta(p_queda);  -- existe y quien llama es administrador o encargado de su cuenta
  return public._party_merge(p_queda, p_se_va, p_quien_nombre);
end $$;


--
-- Name: party_merge_undo(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_merge_undo(p_merge uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_queda uuid;
begin
  select kept_party_id into v_queda from party_merge where id = p_merge;
  if v_queda is null then raise exception 'Esa fusión no existe.' using errcode = 'P0002'; end if;
  perform public.party_cuenta(v_queda);
  return public._party_merge_undo(p_merge, p_quien_nombre);
end $$;


--
-- Name: party_misma_cuenta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_misma_cuenta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from party p where p.id = new.party_id and p.account_id = new.account_id) then
    raise exception 'Ese tercero no es de esta cuenta.' using errcode = '23514';
  end if;
  if tg_table_name = 'party_role' then
    if new.supplier_id is not null and not exists (select 1 from supplier s where s.id = new.supplier_id and s.account_id = new.account_id) then
      raise exception 'Ese proveedor no es de esta cuenta.' using errcode = '23514';
    end if;
    if new.channel_id is not null and not exists (select 1 from sales_channel c where c.id = new.channel_id and c.account_id = new.account_id) then
      raise exception 'Ese canal de venta no es de esta cuenta.' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: party_nif(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_nif(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select nullif(upper(regexp_replace(coalesce(p, ''), '[^A-Za-z0-9]', '', 'g')), '')
$$;


--
-- Name: FUNCTION party_nif(p text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.party_nif(p text) IS 'C03. El NIF como se compara: mayúsculas y solo letras y números. «B-12.345.678» y «b12345678» son el mismo.';


--
-- Name: party_save_customer(uuid, uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_save_customer(p_account uuid, p_party uuid, p_nombre text, p_nif text, p_datos jsonb DEFAULT '{}'::jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_party uuid := p_party; v_nif text := public.party_nif(p_nif); v_otro record; v_nuevo boolean := p_party is null;
begin
  if not current_user_is_admin_or_manager_of(p_account) then
    raise exception 'No puedes dar de alta clientes en esta cuenta.' using errcode = '42501';
  end if;
  if coalesce(trim(p_nombre), '') = '' then raise exception 'Ponle un nombre.' using errcode = '22023'; end if;
  if v_party is not null and (select account_id from party where id = v_party) is distinct from p_account then
    raise exception 'Ese tercero no es de esta cuenta.' using errcode = '42501';
  end if;
  if v_nif is not null then
    select p.id, p.name into v_otro from party p where p.account_id = p_account and p.tax_id = v_nif and p.id is distinct from v_party;
    if found then
      raise exception 'MISMO_NIF %: % ya tiene el NIF %.', v_otro.id, v_otro.name, v_nif using errcode = '23505';
    end if;
  end if;
  if v_nuevo then
    insert into party (account_id, name, tax_id, source, created_by, created_by_name)
    values (p_account, trim(p_nombre), v_nif, 'manual', auth.uid(), p_quien_nombre) returning id into v_party;
  else
    -- El nombre de un tercero con proveedor lo manda su ficha de Cocina.
    update party set name = case when exists (select 1 from party_role where party_id = v_party and role = 'supplier') then name else trim(p_nombre) end,
                     tax_id = v_nif
     where id = v_party;
  end if;
  insert into party_role (account_id, party_id, role, created_by) values (p_account, v_party, 'customer', auth.uid())
  on conflict (party_id, role) do nothing;
  insert into customer_fiscal (party_id, account_id) values (v_party, p_account) on conflict (party_id) do nothing;
  update customer_fiscal set
    legal_name             = case when p_datos ? 'legalName'          then nullif(trim(p_datos->>'legalName'), '') else legal_name end,
    tax_id_type            = case when p_datos ? 'taxIdType'          then p_datos->>'taxIdType' else tax_id_type end,
    country_code           = case when p_datos ? 'countryCode'        then coalesce(nullif(p_datos->>'countryCode', ''), 'ES') else country_code end,
    entity_kind            = case when p_datos ? 'entityKind'         then p_datos->>'entityKind' else entity_kind end,
    tax_id_check_status    = case when p_datos ? 'taxIdCheckStatus'   then p_datos->>'taxIdCheckStatus' else tax_id_check_status end,
    tax_id_checked_at      = case when p_datos ? 'taxIdCheckStatus'   then now() else tax_id_checked_at end,
    tax_id_verified_at     = case when p_datos->>'taxIdCheckStatus' = 'valid' then now()
                                  when p_datos ? 'taxIdCheckStatus'   then null else tax_id_verified_at end,
    fiscal_street          = case when p_datos ? 'fiscalStreet'       then nullif(trim(p_datos->>'fiscalStreet'), '') else fiscal_street end,
    fiscal_postal_code     = case when p_datos ? 'fiscalPostalCode'   then nullif(trim(p_datos->>'fiscalPostalCode'), '') else fiscal_postal_code end,
    fiscal_city            = case when p_datos ? 'fiscalCity'         then nullif(trim(p_datos->>'fiscalCity'), '') else fiscal_city end,
    fiscal_province        = case when p_datos ? 'fiscalProvince'     then nullif(trim(p_datos->>'fiscalProvince'), '') else fiscal_province end,
    equivalence_surcharge  = case when p_datos ? 'equivalenceSurcharge' then (p_datos->>'equivalenceSurcharge')::boolean else equivalence_surcharge end,
    withholding_rate_id    = case when p_datos ? 'withholdingRateId'  then nullif(p_datos->>'withholdingRateId', '')::uuid else withholding_rate_id end,
    operation_scope        = case when p_datos ? 'operationScope'     then p_datos->>'operationScope' else operation_scope end,
    exclude_347            = case when p_datos ? 'exclude347'         then (p_datos->>'exclude347')::boolean else exclude_347 end,
    exclude_347_reason     = case when p_datos ? 'exclude347Reason'   then nullif(trim(p_datos->>'exclude347Reason'), '') else exclude_347_reason end,
    payment_method         = case when p_datos ? 'paymentMethod'      then nullif(p_datos->>'paymentMethod', '') else payment_method end,
    payment_terms_days     = case when p_datos ? 'paymentTermsDays'   then nullif(p_datos->>'paymentTermsDays', '')::int else payment_terms_days end,
    payment_fixed_days     = case when p_datos ? 'paymentFixedDays'   then (select array_agg(x::int) from jsonb_array_elements_text(p_datos->'paymentFixedDays') x) else payment_fixed_days end,
    collection_treasury_id = case when p_datos ? 'collectionTreasuryId' then nullif(p_datos->>'collectionTreasuryId', '')::uuid else collection_treasury_id end,
    iban                   = case when p_datos ? 'iban'               then nullif(upper(regexp_replace(p_datos->>'iban', '\s', '', 'g')), '') else iban end,
    sepa_mandate_ref       = case when p_datos ? 'sepaMandateRef'     then nullif(trim(p_datos->>'sepaMandateRef'), '') else sepa_mandate_ref end,
    sepa_mandate_date      = case when p_datos ? 'sepaMandateDate'    then nullif(p_datos->>'sepaMandateDate', '')::date else sepa_mandate_date end
  where party_id = v_party;
  -- La cuenta donde cobra, de esta empresa y de esta cuenta.
  if exists (select 1 from customer_fiscal cf join treasury_account t on t.id = cf.collection_treasury_id
              where cf.party_id = v_party and t.account_id <> p_account) then
    raise exception 'Esa cuenta de cobro no es de esta cuenta.' using errcode = '23514';
  end if;
  return jsonb_build_object('party_id', v_party, 'nuevo', v_nuevo);
end $$;


--
-- Name: party_set_archived(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_set_archived(p_party uuid, p_archivar boolean, p_nota text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid := public.party_cuenta(p_party); v_cuando timestamptz := case when p_archivar then now() end;
begin
  update party set archived_at = v_cuando, archived_note = case when p_archivar then nullif(trim(p_nota), '') end where id = p_party;
  update supplier s set archived_at = v_cuando
    from party_role r where r.party_id = p_party and r.supplier_id = s.id and s.archived_at is distinct from v_cuando;
  return jsonb_build_object('party_id', p_party, 'archivado', p_archivar);
end $$;


--
-- Name: pase_apagar(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pase_apagar(p_device_token text, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_device  kds_device;
  v_nombre  text;
  v_estaba  boolean;
  v_cuantas int;
  v_objetivo uuid[];
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'pase_apagar: token de dispositivo no válido';
  end if;

  select l.name into v_nombre from locations l
   where l.id = v_device.location_id and l.account_id = v_device.account_id;
  if v_nombre is null then
    raise exception 'pase_apagar: el aparato no corresponde a un local de su cuenta';
  end if;

  -- 🔴 AQUÍ SÍ MANDA EL APARATO, y es la diferencia con `pase_board`: apagar es
  -- un GESTO de quien está delante de una tablet, y apaga la salida que esa
  -- tablet mira. Si no mira ninguna --hoy `camichi4`-- cae a las de su local,
  -- que es lo que hacía el modelo viejo: una tablet sin estación asignada no
  -- puede quedarse sin poder apagar.
  --
  -- Se resuelve a un array y NO a una tabla temporal: esta función la llama la
  -- tablet en cada apagado, y crear una temporal por llamada es un coste y un
  -- riesgo (colisión entre llamadas de la misma sesión) a cambio de nada.
  select coalesce(array_agg(k.id), '{}'::uuid[]) into v_objetivo
    from kitchen_station k
   where k.account_id = v_device.account_id
     and k.kind = 'expo'
     and ( k.id = any(coalesce(v_device.station_ids, '{}'::uuid[]))
           or ( coalesce(array_length(v_device.station_ids, 1), 0) = 0
                and k.location_id = v_device.location_id ) );

  select bool_or(k.pase_activo), count(*) into v_estaba, v_cuantas
    from kitchen_station k where k.id = any(v_objetivo);

  update kitchen_station k
     set pase_activo         = false,
         pase_activo_at      = now(),
         pase_activo_por     = v_device.id,
         pase_activo_desde   = 'tablet',
         pase_apagado_motivo = nullif(btrim(p_motivo), ''),
         updated_at          = now()
   where k.id = any(v_objetivo);

  return jsonb_build_object(
    'local',      v_nombre,
    'estaciones', coalesce(v_cuantas, 0),
    'estaba',     coalesce(v_estaba, false),
    'activo',     false,
    'cuando',     now(),
    'desde',      'tablet');
end;
$$;


--
-- Name: pase_board(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pase_board(p_device_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device  kds_device;
  v_cuenta  uuid;
  v_local   uuid;
  v_nombre  text;
  v_papel   text;
  v_activo  boolean;
  v_res     jsonb;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'pase_board: token de dispositivo no válido';
  end if;
  v_cuenta := v_device.account_id;
  v_local  := v_device.location_id;

  select l.name into v_nombre from locations l where l.id = v_local;

  -- EL PAPEL, del `kind` de las estaciones del aparato. Cero campos nuevos.
  --   expo → pase · prep → cocina · sin estación → ambas
  select case
           when v_device.station_ids is null
             or coalesce(array_length(v_device.station_ids, 1), 0) = 0 then 'ambas'
           when bool_and(k.kind = 'expo') then 'pase'
           when bool_and(k.kind = 'prep') then 'cocina'
           else 'ambas'
         end
    into v_papel
    from kitchen_station k
   where k.id = any(coalesce(v_device.station_ids, '{}'::uuid[]))
     and k.account_id = v_cuenta;
  v_papel := coalesce(v_papel, 'ambas');

  select coalesce(bool_or(k.pase_activo), false) into v_activo
    from kitchen_station k
   where k.location_id = v_local
     and k.kind = 'expo';
  v_activo := coalesce(v_activo, false);

  with vivos as (
    select s.*
      from sale s
     where s.location_id = v_local
       and s.account_id  = v_cuenta          -- 🔴 por CUENTA, no sólo por local
       and s.sold_at >= now() - interval '12 hours'
       and coalesce(s.status, '') <> 'cancelled'
       -- Lo que se torció no se pinta en ninguna zona, así que no viaja.
       and coalesce(s.order_status, '') not in ('rejected', 'cancelled', 'delivery_failed')
       -- Y lo cerrado sólo si la flota dice que llegó hace poco, que es lo
       -- único que entra en «Entregados». El front recorta a 20 min.
       --
       -- 🔴 OJO CON LO QUE ESTA RAYA DEJA FUERA, y es a propósito: una venta
       -- `completed` con `delivery_state = 'delivered'` pero SIN `delivered_at`
       -- no viaja, porque `null >= now() - interval` es null y null no pasa.
       -- Medido: hay 43 así --41 con `delivered` y 2 con `finish`-- y LAS 43
       -- no tienen ni entrega, ni sello, ni handoff.
       --
       -- 🔴 Y NO SON UN GOTEO: son la semana en que se encendió el sello.
       -- Todas están entre el 06/07 y el 24/07, todas en Alcalá y todas de
       -- reparto nuestro con repartidor puesto. El sello no existía --0 de 101,
       -- 0 de 80, 0 de 95, 0 de 121--, aparece la semana del 20/07 con 32 de
       -- 111, y esa misma semana concentra 39 de los 43. Desde el 27/07, CERO,
       -- siete semanas seguidas. Está extinto. Mandarlas hoy sería pintar
       -- «Entregado» sin ninguna hora de un pedido de julio.
       and (coalesce(s.order_status, '') <> 'completed'
            or s.delivered_at >= now() - interval '40 minutes'
            or s.delivery_state in ('in_delivery', 'picked_up'))
  ),
  bolsa as (
    select pj.sale_id,
           (array_agg(pj.status order by pj.created_at desc))[1]     as estado,
           max(pj.created_at)                                        as cuando,
           count(*) filter (where pj.status = 'error')::int           as fallidos
      from print_job pj
     where pj.sale_id in (select id from vivos) and pj.doc_type = 'bag'
     group by pj.sale_id
  )
  select jsonb_agg(jsonb_build_object(
           'sale_id',   v.id,
           'codigo',    coalesce(v.pos_short_code, v.platform_order_code),
           'marca',     b.name,
           'marca_logo_url', b.logo_url,
           'cliente',   v.customer_name,   -- se lee en «Entregado a X». Ni tel ni dirección.
           'channel',   coalesce(c.name, v.external_channel_text),
           'order_status',  v.order_status,
           'service_type',  v.service_type,
           'has_courier',   v.has_courier,
           'carrier_code',  v.carrier_code,
           'source',        v.source,
           'delivery_state', v.delivery_state,
           -- EL REPARTIDOR · los tres campos del §4 de la enmienda del 14/09.
           --
           -- 🔴 De los tres, sólo UNO era un dato que faltaba: el teléfono.
           -- `repartidor_nombre` ya viajaba y `quien_lo_lleva` NO es un dato,
           -- es una FRASE derivada de canal + `service_type` + `carrier_code`
           -- --los tres ya van aquí en crudo-- así que se arma en
           -- `quienLoLleva()` y no se escribe también aquí: la misma regla en
           -- dos sitios es una regla que un día dice dos cosas.
           --
           -- 🔴 Y es el teléfono del REPARTIDOR, que es de casa. Medido en 14
           -- días: 231 repartos propios con flota, los 231 con nombre Y
           -- teléfono; 0 con flota y sin nombre; 0 con nombre y sin flota. De
           -- 1.424 pedidos de plataforma, CERO traen repartidor.
           'repartidor_nombre',     v.rider_name,
           'repartidor_telefono',   v.rider_phone,
           'repartidor_transporte', v.rider_transport_type,
           -- Los instantes en crudo: el reloj lo elige el front.
           'entro_at',   coalesce(v.opened_at, v.sold_at, v.created_at),
           'ready_at',   v.ready_at,
           'handed_to_courier_at', v.handed_to_courier_at,
           'delivered_at',         v.delivered_at,
           'lineas', coalesce((
             select jsonb_agg(jsonb_build_object('nombre', sl.product_name,
                                                 'cantidad', sl.quantity)
                              order by sl.created_at)
               from sale_line sl
              where sl.sale_id = v.id and sl.parent_sale_line_id is null
                and coalesce(sl.line_type, '') <> 'modifier'), '[]'::jsonb),
           'bolsa', jsonb_build_object(
             'estado', case
                         when bo.sale_id is null then 'sin_pedir'
                         when bo.estado = 'done'  then 'hecha'
                         when bo.estado = 'error' then 'rota'
                         else 'esperando' end,
             'cuando',  to_char(bo.cuando at time zone 'Europe/Madrid', 'HH24:MI'),
             'intentos', coalesce(bo.fallidos, 0)),
           -- CÓMO AVANZÓ. Hoy sólo se puede distinguir «lo movió la flota» de
           -- «lo marcó una persona»: ver la nota de abajo.
           'avanzo_por', case
                           when v.delivery_state is not null then 'flota'
                           when v.ready_at is not null       then 'persona'
                           else null end,
           'avanzo_quien', null
         ) order by coalesce(v.opened_at, v.sold_at, v.created_at))
    into v_res
    from vivos v
    left join brand b on b.id = v.brand_id
    left join sales_channel c on c.id = v.channel_id
    left join bolsa bo on bo.sale_id = v.id;

  return jsonb_build_object(
    'local',       v_nombre,
    'papel',       v_papel,
    'pase_activo', v_activo,
    'ahora',       now(),
    'tarjetas',    coalesce(v_res, '[]'::jsonb));
end;
$$;


--
-- Name: pase_encender(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pase_encender(p_station_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_filas  int;
  v_nombre text;
  v_local  text;
begin
  if p_station_id is null then
    raise exception 'pase_encender: falta la estación';
  end if;

  -- El diagnóstico va ANTES del intento: si no, el fallo de permiso lo tapa.
  if exists (select 1 from locations l where l.id = p_station_id) then
    raise exception 'pase_encender: eso es un LOCAL, no una estación. Desde el 16/09 el Pase '
                    'se enciende por estación de salida, no por local.';
  end if;

  update kitchen_station
     set pase_activo         = true,
         pase_activo_at      = now(),
         pase_activo_por     = auth.uid(),
         pase_activo_desde   = 'pantalla',
         pase_apagado_motivo = null,
         updated_at          = now()
   where id = p_station_id;
  get diagnostics v_filas = row_count;

  if v_filas = 0 then
    raise exception 'pase_encender: esta estación no existe o no tienes permiso para cambiar '
                    'los ajustes de su local';
  end if;

  select k.name, l.name into v_nombre, v_local
    from kitchen_station k join locations l on l.id = k.location_id
   where k.id = p_station_id;

  return jsonb_build_object(
    'estacion', v_nombre,
    'local',    v_local,
    'activo',   true,
    'cuando',   now(),
    'por',      auth.uid(),
    'desde',    'pantalla');
end;
$$;


--
-- Name: pase_ficha(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pase_ficha(p_device_token text, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
  v_sale   sale;
  v_raw    jsonb;
  v_codigo text;
  v_tel    text;
  v_marca  text;
  v_bolsa  jsonb;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'pase_ficha: token de dispositivo no válido';
  end if;

  select s.* into v_sale
    from sale s
   where s.id          = p_sale_id
     and s.account_id  = v_device.account_id
     and s.location_id = v_device.location_id;

  if v_sale.id is null then
    raise exception 'pase_ficha: ese pedido no es de este local';
  end if;

  begin
    v_raw := v_sale.raw_tab::jsonb;
  exception when others then
    v_raw := null;
  end;

  v_codigo := nullif(btrim(coalesce(
                v_raw #>> '{customer,phone_access_code}',      -- HubRise
                v_raw #>> '{customerInfo,phoneNumberCode}'     -- Last
              )), '');

  v_tel := nullif(btrim(v_sale.customer_phone), '');

  v_marca := case
               when v_tel is null then null
               when v_codigo is null then 'tel:' || replace(v_tel, ' ', '')
               else 'tel:' || replace(v_tel, ' ', '') || ',,,' || replace(v_codigo, ' ', '')
             end;

  -- LA BOLSA · la misma consulta que `pase_board`, para una sola venta.
  select jsonb_build_object(
           'estado', case
                       when b.sale_id is null then 'sin_pedir'
                       when b.estado = 'done'  then 'hecha'
                       when b.estado = 'error' then 'rota'
                       else 'esperando' end,
           'cuando',   to_char(b.cuando at time zone 'Europe/Madrid', 'HH24:MI'),
           'intentos', coalesce(b.fallidos, 0))
    into v_bolsa
    from (select pj.sale_id,
                 (array_agg(pj.status order by pj.created_at desc))[1] as estado,
                 max(pj.created_at)                                    as cuando,
                 count(*) filter (where pj.status = 'error')::int       as fallidos
            from print_job pj
           where pj.sale_id = v_sale.id and pj.doc_type = 'bag'
           group by pj.sale_id) b;

  return jsonb_build_object(
    'sale_id',       v_sale.id,
    'codigo',        coalesce(v_sale.pos_short_code, v_sale.platform_order_code),
    'marca',         (select b.name     from brand b where b.id = v_sale.brand_id),
    'marca_logo_url',(select b.logo_url from brand b where b.id = v_sale.brand_id),
    'channel',       coalesce((select c.name from sales_channel c where c.id = v_sale.channel_id),
                              v_sale.external_channel_text),
    'order_status',  v_sale.order_status,
    'service_type',  v_sale.service_type,
    'has_courier',   v_sale.has_courier,
    'carrier_code',  v_sale.carrier_code,
    'source',        v_sale.source,
    'delivery_state',v_sale.delivery_state,
    'repartidor_nombre',   nullif(btrim(v_sale.rider_name), ''),
    'repartidor_telefono', nullif(btrim(v_sale.rider_phone), ''),
    'cliente',       nullif(btrim(v_sale.customer_name), ''),
    'cliente_nombre',    nullif(btrim(v_sale.customer_name), ''),
    'cliente_telefono',  v_tel,
    'cliente_codigo',    v_codigo,
    'cliente_marcacion', v_marca,
    'entro_at',    coalesce(v_sale.opened_at, v_sale.sold_at, v_sale.created_at),
    'accepted_at', v_sale.accepted_at,
    'ready_at',    v_sale.ready_at,
    'handed_to_courier_at', v_sale.handed_to_courier_at,
    'delivered_at',         v_sale.delivered_at,
    'direccion',   nullif(btrim(v_sale.delivery_address), ''),
    'notas',       nullif(btrim(v_sale.customer_note), ''),
    -- LO QUE BAJÓ DE LA TARJETA (17/09)
    'bolsa',       coalesce(v_bolsa, jsonb_build_object('estado','sin_pedir','cuando',null,'intentos',0)),
    'avanzo_por',  case
                     when v_sale.delivery_state is not null then 'flota'
                     when v_sale.ready_at is not null       then 'persona'
                     else null end,
    'avanzo_quien', null
  );
end;
$$;


--
-- Name: FUNCTION pase_ficha(p_device_token text, p_sale_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pase_ficha(p_device_token text, p_sale_id uuid) IS 'La hoja de detalle del Pase: teléfonos, centralita, tiempos y dirección de UN pedido. Frontera de token igual que pase_board, y además comprueba el LOCAL. Devuelve datos, no frases: las frases las arma el front en laFicha.ts.';


--
-- Name: pedidos_sin_direccion(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pedidos_sin_direccion(p_location_id uuid, p_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
  v_loc    uuid;
  v_acc    uuid;
  v_mode   text;
  v_tz     text;
  v_hoy    date;
  v_result jsonb;
begin
  if p_token is not null then
    v_device := public.kds_resolve_device(p_token);
    if v_device.id is null then raise exception 'pedidos_sin_direccion: token de dispositivo no válido'; end if;
    v_loc := v_device.location_id;
  else
    if p_location_id is null then raise exception 'pedidos_sin_direccion: falta location_id'; end if;
    v_loc := p_location_id;
    perform public.kds_authorize(v_loc, null);
  end if;

  select coalesce(l.dispatch_mode, 'auto'), l.account_id into v_mode, v_acc
    from public.locations l where l.id = v_loc;
  select coalesce(a.timezone, 'Europe/Madrid') into v_tz from public.accounts a where a.id = v_acc;
  v_tz  := coalesce(v_tz, 'Europe/Madrid');
  v_hoy := ((now() at time zone v_tz) - interval '4 hours')::date;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.sold_at desc), '[]'::jsonb)
    into v_result
    from (
      select s.id                                   as sale_id,
             s.sold_at,
             coalesce(s.pos_short_code, s.platform_order_code, s.external_ref) as code,
             s.platform_order_ref,
             s.external_channel_text                as channel,
             b.name                                 as brand,
             s.status,
             s.order_status,
             s.delivery_state,
             (case when left(btrim(coalesce(s.raw_tab,'')),1)='{'
                   then coalesce(nullif(s.raw_tab::jsonb->'customer'->>'latitude',''),
                                 nullif(s.raw_tab::jsonb->'delivery'->>'latitude','')) end)::numeric  as lat,
             (case when left(btrim(coalesce(s.raw_tab,'')),1)='{'
                   then coalesce(nullif(s.raw_tab::jsonb->'customer'->>'longitude',''),
                                 nullif(s.raw_tab::jsonb->'delivery'->>'longitude','')) end)::numeric as lng,
             s.carrier_code,
             (s.carrier_order_id is not null)       as en_catcher,
             s.rider_name,
             s.rider_phone,
             -- Para llamar al cliente desde el aviso rojo y la lista (Uber: con su código).
             s.customer_phone,
             s.customer_phone_code,
             s.dispatch_error,
             v_mode                                 as dispatch_mode,
             nullif(btrim(s.delivery_address_fixed), '') as direccion_completada,
             s.delivery_address_fixed_at            as completada_at,
             s.delivery_address_fixed_by            as completada_por,
             -- R03 · Uber: señales mezcladas, lo decide una persona.
             (s.delivery_by_reason = 'uber_decidir') as decidir,
             -- El aviso rojo: abierto, sin salir a Catcher y con el motivo.
             (s.status = 'open' and s.carrier_order_id is null and s.dispatch_error is not null
              and coalesce(btrim(s.delivery_address_fixed), '') = '') as no_ha_salido
        from public.sale s
        left join public.brand b on b.id = s.brand_id
       where s.location_id = v_loc
         and s.service_type = 'own_delivery'
         and s.sold_at > now() - interval '30 hours'
         and ((s.sold_at at time zone v_tz) - interval '4 hours')::date = v_hoy
         and (coalesce(btrim(s.delivery_address), '') = '' or s.delivery_by_reason = 'uber_decidir')
    ) x;

  return jsonb_build_object('location_id', v_loc, 'now', now(), 'pedidos', v_result);
end;
$$;


--
-- Name: FUNCTION pedidos_sin_direccion(p_location_id uuid, p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pedidos_sin_direccion(p_location_id uuid, p_token text) IS 'R03: pedidos de reparto propio vivos sin dirección (ni de la plataforma ni pegada), para el aviso rojo de la cocina. Con token, solo el local del dispositivo.';


--
-- Name: pending_albaran_sin_pedido_detail(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_albaran_sin_pedido_detail(p_account_id uuid, p_location_id uuid) RETURNS TABLE(receipt_id uuid, receipt_code text, supplier_name text, received_at timestamp with time zone, candidate_order_id uuid, candidate_order_code text, candidate_expected_date date, candidate_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'pending_albaran_sin_pedido_detail: cuenta % no pertenece al usuario', p_account_id;
  end if;

  return query
  select gr.id, gr.code, s.name, gr.received_at,
         c.order_id, c.order_code, c.expected_date, c.score
  from goods_receipt gr
  join supplier s on s.id = gr.supplier_id
  join lateral (
    select * from public._goods_receipt_order_candidates(gr.id) order by score desc limit 1
  ) c on true
  where gr.account_id = p_account_id
    and gr.location_id = p_location_id
    and gr.purchase_order_id is null
    and gr.status in ('recibido', 'confirmado')
  order by gr.received_at desc;
end;
$$;


--
-- Name: pending_board(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_board(p_account_id uuid) RETURNS TABLE(pending_kind text, layer text, area text, location_id uuid, location_name text, items integer, detail jsonb, sort_weight integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_profile_id uuid;
  v_user_role text;
  c_pct_minimo_sano constant numeric := 90;
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'pending_board: cuenta % no pertenece al usuario', p_account_id;
  end if;

  set local statement_timeout = '3s';

  select up.id, up.role into v_user_profile_id, v_user_role
  from public.user_profiles up
  where up.user_id = auth.uid() and up.account_id = p_account_id and up.active = true
  limit 1;

  if v_user_profile_id is null then
    return;
  end if;

  return query
  with scoped_locations as (
    select l.id, l.name
    from public.locations l
    where l.account_id = p_account_id and l.active = true
      and (
        v_user_role = 'admin'
        or exists (
          select 1 from public.manager_locations ml
          where ml.user_profile_id = v_user_profile_id and ml.location_id = l.id
        )
      )
  ),
  dismissed as (
    select d.pending_kind, d.location_id, d.entity_id
    from public.pending_dismissal d
    where d.account_id = p_account_id
      and (
        (d.action = 'posponer' and d.until > now())
        or d.action = 'descartar'
      )
  ),
  raw as (
    select r.pending_kind, r.entity_id, r.location_id, r.entity_at
    from public.pending_raw_entities(p_account_id) r
    join scoped_locations sl on sl.id = r.location_id
    where not exists (
      select 1 from dismissed d
      where d.pending_kind = r.pending_kind
        and d.location_id = r.location_id
        and (d.entity_id = r.entity_id or d.entity_id is null)
    )
  ),
  counted as (
    select r.pending_kind, r.location_id, count(*)::integer as items, min(r.entity_at) as oldest_at, max(r.entity_at) as newest_at, count(*) filter (where r.entity_at > now() - interval '7 days')::integer as items_recientes
    from raw r
    group by r.pending_kind, r.location_id
  ),
  kinds as (
    select * from (values
      ('recepcion_esperando_oficina', 'ahora',  'almacen', 'show_recepcion',   10),
      ('albaran_genero_sin_casar',    'ahora',  'almacen', 'show_recepcion',   20),
      ('pedido_vencido',              'ahora',  'almacen', 'show_pedidos',     30),
      ('albaran_borrador_atascado',   'semana', 'almacen', 'show_recepcion',   40),
      ('albaran_sin_pedido',          'semana', 'almacen', 'show_recepcion',   45),
      ('pedido_borrador_atascado',    'semana', 'almacen', 'show_pedidos',     50),
      ('recuento_abierto',            'semana', 'almacen', 'show_inventarios', 60),
      ('recuento_sin_aprobar',        'semana', 'almacen', 'show_inventarios', 70),
      ('linea_sin_coste',             'semana', 'almacen', 'show_costes',      80)
    ) as k(pending_kind, layer, area, perm_key, sort_weight)
  )
  select
    c.pending_kind, k.layer, k.area, c.location_id, sl.name,
    c.items, jsonb_build_object('oldest_at', c.oldest_at, 'newest_at', c.newest_at, 'items_recientes', c.items_recientes), k.sort_weight
  from counted c
  join kinds k on k.pending_kind = c.pending_kind
  join scoped_locations sl on sl.id = c.location_id
  where public.has_permission(p_account_id, k.perm_key)

  union all

  select
    'stock_negativo', 'salud', 'almacen', sl.id, sl.name,
    count(*)::integer, jsonb_build_object(), 90
  from public.recipe_item_location_stock rils
  join scoped_locations sl on sl.id = rils.location_id
  where rils.account_id = p_account_id and rils.qty_on_hand < 0
    and public.has_permission(p_account_id, 'show_inventory')
  group by sl.id, sl.name

  union all

  select
    'formatos_extraccion_degradada', 'salud', 'almacen', sl.id, sl.name,
    v.faltan::integer,
    jsonb_build_object('pct_ok', v.pct_ok, 'total_semana', v.total),
    95
  from scoped_locations sl
  cross join lateral (
    select
      count(*) as total,
      count(*) filter (where (ln->>'pack_size') is null or nullif(ln->>'supplier_code','') is null) as faltan,
      round(100.0 * count(*) filter (where (ln->>'pack_size') is not null and nullif(ln->>'supplier_code','') is not null) / nullif(count(*),0), 1) as pct_ok
    from public.goods_receipt gr
    join public.goods_receipt_ai_session s on s.id = gr.ai_session_id
    cross join lateral jsonb_array_elements(s.parsed_result->'lines') as ln
    where gr.account_id = p_account_id and gr.location_id = sl.id
      and gr.created_at > now() - interval '7 days'
  ) v
  where public.has_permission(p_account_id, 'show_recepcion')
    and v.total > 0 and v.pct_ok < c_pct_minimo_sano

  union all

  select 'ficha_contradice_historico', 'salud', 'almacen', sl.id, sl.name,
    v.n::integer, jsonb_build_object(), 96
  from scoped_locations sl
  cross join lateral (
    select count(*) as n
    from (
      select a.id
      from public.article_supplier a
      join public.recipe_item_purchase_format f on f.id = a.purchase_format_id and f.is_active
      join (
        select gr.supplier_id, grl.supplier_code,
          percentile_cont(0.5) within group (order by grl.qty_in_base / grl.qty_received) as mediana,
          count(*) as n
        from public.goods_receipt_line grl
        join public.goods_receipt gr on gr.id = grl.goods_receipt_id
        where gr.account_id = p_account_id and grl.supplier_code is not null
          and grl.qty_received is not null and grl.qty_received > 0 and grl.qty_in_base is not null
        group by gr.supplier_id, grl.supplier_code
        having count(*) >= 3
      ) h on h.supplier_id = a.supplier_id and h.supplier_code = a.supplier_code
      where a.account_id = p_account_id and a.is_active
        and abs(f.qty_in_base - h.mediana) >= 0.01
    ) x
  ) v
  where public.has_permission(p_account_id, 'show_costes') and v.n > 0

  union all

  select 'codigo_ambiguo', 'salud', 'almacen', sl.id, sl.name,
    v.n::integer, jsonb_build_object(), 97
  from scoped_locations sl
  cross join lateral (
    select count(*) as n
    from (
      select supplier_id, supplier_code
      from public.article_supplier
      where account_id = p_account_id and supplier_code is not null and is_active
      group by supplier_id, supplier_code
      having count(distinct recipe_item_id) > 1
    ) x
  ) v
  where public.has_permission(p_account_id, 'show_recepcion') and v.n > 0

  union all

  select 'fichas_sin_verificar', 'salud', 'almacen', sl.id, sl.name,
    v.n::integer, jsonb_build_object(), 98
  from scoped_locations sl
  cross join lateral (
    select count(*) as n
    from public.article_supplier a
    where a.account_id = p_account_id and a.source = 'albaran' and a.verified_at is null and a.is_active
  ) v
  where public.has_permission(p_account_id, 'show_recepcion') and v.n > 0;
end;
$$;


--
-- Name: pending_count_line_for_item(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_count_line_for_item(p_account_id uuid, p_location_id uuid, p_recipe_item_id uuid) RETURNS TABLE(line_id uuid, count_id uuid, count_code text, count_status text, counted_qty numeric, counted_at timestamp with time zone, counted_by_name text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT l.id, ic.id, ic.code, ic.status,
         l.counted_qty, l.counted_at, l.counted_by_name
    FROM public.inventory_count_line l
    JOIN public.inventory_count ic ON ic.id = l.inventory_count_id
   WHERE l.account_id     = p_account_id
     AND ic.location_id   = p_location_id
     AND l.recipe_item_id = p_recipe_item_id
     AND ic.status IN ('contando', 'en_revision')
     AND l.excluded_at IS NULL
   ORDER BY ic.created_at DESC
   LIMIT 1;
$$;


--
-- Name: FUNCTION pending_count_line_for_item(p_account_id uuid, p_location_id uuid, p_recipe_item_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pending_count_line_for_item(p_account_id uuid, p_location_id uuid, p_recipe_item_id uuid) IS 'La linea de recuento sin aprobar que tiene este articulo en este local, si la hay. La pantalla de corregir stock a mano la usa para avisar ANTES de escribir, no despues.';


--
-- Name: pending_raw_entities(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_raw_entities(p_account_id uuid) RETURNS TABLE(pending_kind text, entity_id uuid, location_id uuid, entity_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select 'recepcion_esperando_oficina', gr.id, gr.location_id, gr.received_at
  from goods_receipt gr
  where gr.account_id = p_account_id and gr.status = 'recibido'

  union all
  select 'albaran_genero_sin_casar', v.goods_receipt_id, v.location_id, v.received_at
  from public.goods_receipt_posting_status v
  where v.account_id = p_account_id
    and v.status = 'confirmado'
    and (coalesce(v.needs_review, false) or v.lines_pending > 0)

  union all
  select 'pedido_vencido', po.id, po.location_id, po.expected_date::timestamptz
  from purchase_order po
  where po.account_id = p_account_id and po.status = 'enviado' and po.expected_date < current_date

  union all
  select 'albaran_borrador_atascado', gr.id, gr.location_id, gr.created_at
  from goods_receipt gr
  where gr.account_id = p_account_id and gr.status = 'borrador' and gr.created_at < now() - interval '2 days'

  union all
  select 'pedido_borrador_atascado', po.id, po.location_id, po.created_at
  from purchase_order po
  where po.account_id = p_account_id and po.status = 'borrador' and po.created_at < now() - interval '7 days'

  union all
  select 'recuento_abierto', ic.id, ic.location_id, ic.created_at
  from inventory_count ic
  where ic.account_id = p_account_id and ic.closed_at is null and ic.status <> 'anulado'

  union all
  select 'recuento_sin_aprobar', ic.id, ic.location_id, ic.closed_at
  from inventory_count ic
  where ic.account_id = p_account_id and ic.closed_at is not null and ic.approved_at is null and ic.status <> 'anulado'

  union all
  select 'linea_sin_coste', sm.id, sm.location_id, sm.created_at
  from stock_movement sm
  where sm.account_id = p_account_id and sm.source_type = 'goods_receipt_line' and sm.unit_cost is null

  union all
  select 'albaran_sin_pedido', gr.id, gr.location_id, gr.received_at
  from goods_receipt gr
  where gr.account_id = p_account_id
    and gr.purchase_order_id is null
    and gr.status in ('recibido', 'confirmado')
    and exists (select 1 from public._goods_receipt_order_candidates(gr.id));
end;
$$;


--
-- Name: pending_receptions_report(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_receptions_report(p_account uuid, p_location uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_res jsonb;
begin
  if not (current_user_is_admin() or current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'pending_receptions_report: sin acceso a la cuenta %', p_account;
  end if;

  with pedidos as (
    select po.id, po.code, po.supplier_id, s.name as supplier_name,
           po.location_id, l.name as location_name,
           po.order_date, po.expected_date, po.status
    from public.purchase_order po
    left join public.supplier  s on s.id = po.supplier_id
    left join public.locations l on l.id = po.location_id
    where po.account_id = p_account
      and po.location_id = p_location
      and po.status in ('enviado', 'recibido_parcial')
  ),
  lineas as (
    select pol.id as line_id, pol.purchase_order_id, pol.recipe_item_id, pol.product_name,
           pol.qty_ordered,
           coalesce(f.qty_in_base, 1) as format_qty_in_base,
           ku.abbreviation as unit_abbr
    from public.purchase_order_line pol
    join pedidos p on p.id = pol.purchase_order_id
    left join public.recipe_item_purchase_format f on f.id = pol.purchase_format_id
    left join public.recipe_item ri on ri.id = pol.recipe_item_id
    left join public.kitchen_unit ku on ku.id = ri.base_unit_id
  ),
  recibido as (
    select grl.purchase_order_line_id as line_id,
           sum(grl.qty_in_base) as qty_received_base
    from public.goods_receipt_line grl
    join public.goods_receipt gr on gr.id = grl.goods_receipt_id
    where gr.status = 'confirmado'
      and grl.purchase_order_line_id is not null
    group by grl.purchase_order_line_id
  )
  select jsonb_build_object(
    'orders', coalesce((
      select jsonb_agg(jsonb_build_object(
               'order_id',       p.id,
               'code',           p.code,
               'supplier_id',    p.supplier_id,
               'supplier_name',  p.supplier_name,
               'location_id',    p.location_id,
               'location_name',  p.location_name,
               'order_date',     p.order_date,
               'expected_date',  p.expected_date,
               'status',         p.status,
               'days_overdue',   case when p.expected_date is not null and p.expected_date < current_date
                                       then (current_date - p.expected_date)
                                       else 0 end,
               'lines', coalesce((
                 select jsonb_agg(jsonb_build_object(
                          'recipe_item_id',    ln.recipe_item_id,
                          'product_name',      ln.product_name,
                          'unit_abbr',         ln.unit_abbr,
                          'qty_ordered_base',  round(ln.qty_ordered * ln.format_qty_in_base, 3),
                          'qty_received_base', round(coalesce(r.qty_received_base, 0), 3),
                          'complete',          coalesce(r.qty_received_base, 0) >= (ln.qty_ordered * ln.format_qty_in_base)
                        ) order by ln.product_name)
                 from lineas ln
                 left join recibido r on r.line_id = ln.line_id
                 where ln.purchase_order_id = p.id
               ), '[]'::jsonb)
             ) order by p.expected_date asc nulls last, p.order_date asc)
      from pedidos p
    ), '[]'::jsonb)
  ) into v_res;

  return v_res;
end;
$$;


--
-- Name: pick_social_copy(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pick_social_copy(p_pillar text, p_account_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id   uuid;
  v_text text;
  v_has_own boolean;
begin
  -- ¿la cuenta tiene voz propia para este pilar? -> override total sobre la global
  select exists(
    select 1 from social_copy
     where pillar = p_pillar and is_active and account_id = p_account_id
  ) into v_has_own;

  select id, text into v_id, v_text
    from social_copy
   where pillar = p_pillar and is_active
     and ( (v_has_own and account_id = p_account_id)
        or (not v_has_own and account_id is null) )
   order by (times_used::numeric / greatest(weight,1)) asc, random()
   limit 1;

  if v_id is null then
    return null;                         -- sin frase para ese pilar (el agente tiene fallback)
  end if;

  update social_copy set times_used = times_used + 1 where id = v_id;
  return v_text;
end $$;


--
-- Name: pick_social_scene(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pick_social_scene(p_mode text, p_account_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_prompt text; v_has_own boolean;
begin
  select exists(select 1 from social_scene where mode = p_mode and is_active and account_id = p_account_id)
    into v_has_own;
  select id, prompt into v_id, v_prompt from social_scene
   where mode = p_mode and is_active
     and ((v_has_own and account_id = p_account_id) or (not v_has_own and account_id is null))
   order by (times_used::numeric / greatest(weight,1)) asc, random()
   limit 1;
  if v_id is null then return null; end if;
  update social_scene set times_used = times_used + 1 where id = v_id;
  return v_prompt;
end $$;


--
-- Name: place_shop_order(text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_shop_order(p_slug text, p_payload jsonb, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc        uuid;
  v_channel    uuid;
  v_location   uuid;
  v_mode       text;
  v_service    text;
  v_pay_mode   text;
  v_line       jsonb;
  v_repr       jsonb;
  v_subtotal   numeric := 0;
  v_delivery   numeric := 0;
  v_total      numeric := 0;
  v_preview    jsonb := '[]'::jsonb;
  v_sale_id    uuid;
  v_code       text;
  v_token      text;
  v_brand_arr  uuid[];
  v_cart_brand uuid;                      -- ⟵ 3b: marca del carrito (Shop es per-marca)
  v_expected   timestamptz;
  v_addr       text;
  v_is_cash    boolean;
  v_email      text;
  v_phone      text;
  v_name       text;
  v_consent    boolean;
  v_terms      text;
  v_customer   uuid;
  v_seed_addr  text;
  v_line_cost    numeric;
  v_line_qty     numeric;
  v_cost_known   numeric := 0;
  v_cost_has_null boolean := false;
  v_coupon_code  text;
  v_coupon       coupon%rowtype;
  v_cust_existing uuid;
  v_discount     numeric := 0;
  v_reason       text := null;
  v_neto         numeric;
  v_margin_eur   numeric;
  v_margin_pct   numeric;
  v_margin_warn  boolean := false;
  v_floor        numeric;
  v_is_welcome   boolean;
  v_coupon_json  jsonb := jsonb_build_object('applied', false);
  v_freq          coupon%rowtype;
  v_freq_discount numeric := 0;
  v_progress      integer := 0;
  v_is_frequency  boolean := false;
  v_fd           coupon%rowtype;
  v_fd_discount  numeric := 0;
  v_gi           coupon%rowtype;
  v_gift_id      uuid;
  v_gift_price   numeric := 0;
  v_gift_name    text;
  v_gift_reason  text;
  v_gift_applied boolean := false;
  v_fd_applied   boolean := false;
  v_fd_reason    text := null;
  v_item_promo   jsonb := '{}'::jsonb;
  v_promo_cid    text;
  v_promo_du     numeric;
begin
  select id into v_acc from accounts where slug = p_slug;
  if v_acc is null then
    return jsonb_build_object('ok', false, 'reason', 'account');
  end if;

  if jsonb_typeof(p_payload->'lines') <> 'array'
     or jsonb_array_length(p_payload->'lines') = 0 then
    return jsonb_build_object('ok', false, 'reason', 'empty');
  end if;

  v_location := nullif(p_payload->>'locationId','')::uuid;
  v_mode     := coalesce(p_payload->>'mode', 'delivery');
  v_service  := case when v_mode = 'pickup' then 'pickup' else 'own_delivery' end;
  v_delivery := case when v_mode = 'pickup' then 0
                     else coalesce((p_payload#>>'{delivery,deliveryFee}')::numeric, 0) end;
  v_expected := nullif(p_payload->>'expectedTime','')::timestamptz;
  v_pay_mode := coalesce(p_payload#>>'{payment,mode}','simulated');
  v_is_cash  := (v_pay_mode = 'cash');

  select id into v_channel
  from sales_channel
  where account_id = v_acc and slug = 'shop' and is_active and archived_at is null
  limit 1;

  for v_line in select * from jsonb_array_elements(p_payload->'lines')
  loop
    v_repr := public._shop_reprice_line(v_acc, v_line);
    v_subtotal := v_subtotal + coalesce((v_repr->>'lineTotal')::numeric, 0);
    v_preview := v_preview || jsonb_build_array(jsonb_build_object(
      'name', v_repr->>'name',
      'quantity', (v_repr->>'quantity')::numeric,
      'unitPrice', (v_repr->>'unitPrice')::numeric,
      'lineTotal', (v_repr->>'lineTotal')::numeric,
      'valid', (v_repr->>'valid')::boolean,
      'offer', v_repr->'offer'
    ));

    if jsonb_typeof(v_repr->'offer') = 'object' then
      v_promo_cid := v_repr#>>'{offer,campaignId}';
      if v_promo_cid is not null then
        v_promo_du := coalesce((v_repr#>>'{offer,discountUnit}')::numeric, 0)
                    * coalesce((v_repr->>'quantity')::numeric, 0);
        if v_promo_du > 0 then
          v_item_promo := jsonb_set(v_item_promo, array[v_promo_cid],
            to_jsonb(coalesce((v_item_promo->>v_promo_cid)::numeric, 0) + v_promo_du));
        end if;
      end if;
    end if;

    v_line_qty := coalesce((v_repr->>'quantity')::numeric, 0);
    select ri.computed_cost into v_line_cost
    from menu_item mi
    left join recipe_item ri on ri.id = mi.recipe_item_id
    where mi.id = nullif(v_line->>'menuItemId','')::uuid
      and mi.account_id = v_acc
    limit 1;

    if v_line_cost is null then
      v_cost_has_null := true;
    else
      v_cost_known := v_cost_known + (v_line_cost * v_line_qty);
    end if;
  end loop;
  v_total := v_subtotal + v_delivery;

  -- ⟵ 3b: marca del carrito (el Shop es per-marca; el carrito es de una sola marca).
  select mi.brand_id into v_cart_brand
  from jsonb_array_elements(p_payload->'lines') ln
  join menu_item mi on mi.id = nullif(ln->>'menuItemId','')::uuid and mi.account_id = v_acc
  where mi.brand_id is not null
  limit 1;

  v_coupon_code := nullif(p_payload#>>'{coupon,code}','');
  v_email := lower(nullif(btrim(p_payload#>>'{customer,email}'), ''));
  v_phone := nullif(btrim(p_payload#>>'{customer,phone}'), '');
  v_consent := coalesce((p_payload#>>'{consent,marketing}')::boolean, false);

  select * into v_coupon
  from coupon
  where account_id = v_acc and active and kind <> 'free_delivery'
    and (
      (v_coupon_code is not null and lower(code) = lower(v_coupon_code))
      or (v_coupon_code is null and auto_apply)
    )
    and (starts_at is null or starts_at <= now())
    and (ends_at   is null or ends_at   >  now())
  order by (v_coupon_code is not null) desc
  limit 1;

  if v_coupon.id is not null then
    v_is_welcome := v_coupon.first_order_only or v_coupon.auto_apply;

    if v_email is not null then
      select id into v_cust_existing from customer
      where account_id = v_acc and lower(email) = v_email limit 1;
    end if;
    if v_cust_existing is null and v_phone is not null then
      select id into v_cust_existing from customer
      where account_id = v_acc and phone = v_phone limit 1;
    end if;

    if v_coupon.min_subtotal is not null and v_subtotal < v_coupon.min_subtotal then
      v_reason := 'min';
    elsif v_is_welcome and (v_email is null or not v_consent) then
      v_reason := 'needs_contact';
    elsif v_coupon.first_order_only and v_cust_existing is not null and exists (
            select 1 from sale
            where customer_id = v_cust_existing
              and coalesce(status,'') <> 'cancelled'
          ) then
      v_reason := 'not_first';
    elsif v_coupon.max_redemptions is not null and (
            select count(*) from coupon_redemption cr
            join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_coupon.id and coalesce(s.status,'') <> 'cancelled'
          ) >= v_coupon.max_redemptions then
      v_reason := 'exhausted';
    elsif v_cust_existing is not null and (
            select count(*) from coupon_redemption cr
            join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_coupon.id and cr.customer_id = v_cust_existing
              and coalesce(s.status,'') <> 'cancelled'
          ) >= v_coupon.max_per_customer then
      v_reason := 'per_customer';
    end if;

    if v_reason is null then
      v_discount := case v_coupon.discount_type
        when 'percent' then round(v_subtotal * v_coupon.value / 100, 2)
        else least(v_coupon.value, v_subtotal) end;
      if v_discount < 0 then v_discount := 0; end if;

      if v_cost_has_null then
        v_margin_warn := true;
      else
        v_neto       := v_subtotal - v_discount;
        v_margin_eur := v_neto - v_cost_known;
        v_margin_pct := case when v_neto > 0 then v_margin_eur / v_neto * 100 else null end;
        v_floor      := (select shop_coupon_margin_floor_pct from accounts where id = v_acc);

        if v_floor is not null and v_margin_pct is not null and v_margin_pct < v_floor then
          if v_is_welcome then
            v_margin_warn := true;
          else
            v_reason := 'margin';
            v_discount := 0;
          end if;
        end if;
      end if;
    end if;

    v_coupon_json := jsonb_build_object(
      'applied', (v_discount > 0),
      'code', v_coupon.code,
      'label', v_coupon.name,
      'discount', round(v_discount,2),
      'discountType', v_coupon.discount_type,
      'discountValue', v_coupon.value,
      'reason', v_reason,
      'marginWarning', v_margin_warn,
      'isWelcome', v_is_welcome,
      'isFrequency', false
    );
  end if;

  if v_coupon_code is null then
    if v_cust_existing is null and v_email is not null then
      select id into v_cust_existing from customer
      where account_id = v_acc and lower(email) = v_email limit 1;
    end if;
    if v_cust_existing is null and v_phone is not null then
      select id into v_cust_existing from customer
      where account_id = v_acc and phone = v_phone limit 1;
    end if;

    if v_cust_existing is not null then
      select * into v_freq
      from coupon
      where account_id = v_acc and active and kind = 'frequency'
        and (starts_at is null or starts_at <= now())
        and (ends_at   is null or ends_at   >  now())
      limit 1;

      if v_freq.id is not null and v_freq.frequency_threshold is not null then
        select count(*) into v_progress
        from sale s
        where s.customer_id = v_cust_existing and s.source = 'folvy_shop'
          and coalesce(s.status,'') <> 'cancelled'
          and s.created_at > coalesce((
            select max(cr.ts) from coupon_redemption cr
            join sale cs on cs.id = cr.sale_id
            where cr.coupon_id = v_freq.id and cr.customer_id = v_cust_existing
              and coalesce(cs.status,'') <> 'cancelled'
          ), '-infinity'::timestamptz);

        if v_progress >= v_freq.frequency_threshold then
          v_freq_discount := case v_freq.discount_type
            when 'percent' then round(v_subtotal * v_freq.value / 100, 2)
            else least(v_freq.value, v_subtotal) end;
          if v_freq_discount < 0 then v_freq_discount := 0; end if;

          if v_freq_discount > 0 and not v_cost_has_null then
            v_floor := (select shop_coupon_margin_floor_pct from accounts where id = v_acc);
            if v_floor is not null then
              v_neto := v_subtotal - v_freq_discount;
              v_margin_pct := case when v_neto > 0 then (v_neto - v_cost_known) / v_neto * 100 else null end;
              if v_margin_pct is not null and v_margin_pct < v_floor then
                v_freq_discount := 0;
              end if;
            end if;
          end if;

          if v_freq_discount > v_discount then
            v_coupon       := v_freq;
            v_is_frequency := true;
            v_discount     := v_freq_discount;
            v_reason       := null;
            v_margin_warn  := v_cost_has_null;
            v_coupon_json  := jsonb_build_object(
              'applied', (v_freq_discount > 0),
              'code', v_freq.code,
              'label', v_freq.name,
              'discount', round(v_freq_discount,2),
              'discountType', v_freq.discount_type,
              'discountValue', v_freq.value,
              'reason', null,
              'marginWarning', v_cost_has_null,
              'isWelcome', false,
              'isFrequency', true
            );
          end if;
        end if;
      end if;
    end if;
  end if;

  select * into v_fd
  from coupon
  where account_id = v_acc and active and kind = 'free_delivery'
    and ((v_coupon_code is not null and lower(code) = lower(v_coupon_code)) or auto_apply)
    and (starts_at is null or starts_at <= now())
    and (ends_at   is null or ends_at   >  now())
  order by (v_coupon_code is not null and code is not null and lower(code) = lower(v_coupon_code)) desc, created_at desc
  limit 1;

  if v_fd.id is not null then
    if v_cust_existing is null and v_email is not null then
      select id into v_cust_existing from customer where account_id = v_acc and lower(email) = v_email limit 1;
    end if;
    if v_cust_existing is null and v_phone is not null then
      select id into v_cust_existing from customer where account_id = v_acc and phone = v_phone limit 1;
    end if;

    if v_mode = 'pickup' then
      v_fd_reason := 'pickup_only';
    elsif v_fd.min_subtotal is not null and v_subtotal < v_fd.min_subtotal then
      v_fd_reason := 'min';
    elsif v_delivery <= 0 then
      v_fd_reason := 'no_delivery';
    elsif v_fd.max_redemptions is not null and (
            select count(*) from coupon_redemption cr
            join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_fd.id and coalesce(s.status,'') <> 'cancelled'
          ) >= v_fd.max_redemptions then
      v_fd_reason := 'exhausted';
    elsif v_fd.budget_max is not null and (
            select coalesce(sum(cr.discount_amount), 0) from coupon_redemption cr
            join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_fd.id and coalesce(s.status,'') <> 'cancelled'
          ) >= v_fd.budget_max then
      v_fd_reason := 'exhausted';
    elsif v_cust_existing is not null and (
            select count(*) from coupon_redemption cr
            join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_fd.id and cr.customer_id = v_cust_existing
              and coalesce(s.status,'') <> 'cancelled'
          ) >= v_fd.max_per_customer then
      v_fd_reason := 'per_customer';
    end if;

    if v_fd_reason is null then
      v_fd_discount := round(v_delivery, 2);
      v_fd_applied  := true;
    end if;
  end if;

  -- ── PLATO DE REGALO (free_item) en lane propio (línea a 0€) ──
  select * into v_gi
  from coupon
  where account_id = v_acc and active and kind = 'free_item' and paused_at is null and auto_apply
    and (starts_at is null or starts_at <= now())
    and (ends_at   is null or ends_at   >  now())
    and 'shop' = any(channels)
    and (weekdays  is null or extract(isodow from (now() at time zone 'Europe/Madrid'))::smallint = any(weekdays))
    and (time_from is null or (now() at time zone 'Europe/Madrid')::time >= time_from)
    and (time_to   is null or (now() at time zone 'Europe/Madrid')::time <= time_to)
    and exists (                               -- ⟵ 3b: solo el regalo de la MARCA del carrito
      select 1 from campaign_scope csc
      join menu_item cmi on cmi.id = csc.menu_item_id
      where csc.coupon_id = coupon.id and cmi.brand_id = v_cart_brand
    )
  order by created_at desc
  limit 1;

  if v_gi.id is not null then
    if v_cust_existing is null and v_email is not null then
      select id into v_cust_existing from customer where account_id = v_acc and lower(email) = v_email limit 1;
    end if;
    if v_cust_existing is null and v_phone is not null then
      select id into v_cust_existing from customer where account_id = v_acc and phone = v_phone limit 1;
    end if;

    select sc.menu_item_id into v_gift_id
    from campaign_scope sc where sc.coupon_id = v_gi.id and sc.menu_item_id is not null limit 1;

    if v_gift_id is not null then
      select mi.name, coalesce(mi.price, 0) into v_gift_name, v_gift_price
      from menu_item mi
      where mi.id = v_gift_id and mi.account_id = v_acc
        and mi.archived_at is null and mi.is_active is not false and public.menu_item_vendible_en_alguna_parte(mi.id);
    end if;

    if v_gift_id is null or v_gift_name is null then
      v_gift_reason := 'gift_unavailable';
    elsif v_gi.min_subtotal is not null and v_subtotal < v_gi.min_subtotal then
      v_gift_reason := 'min';
    elsif v_gi.max_redemptions is not null and (
            select count(*) from coupon_redemption cr join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_gi.id and coalesce(s.status,'') <> 'cancelled'
          ) >= v_gi.max_redemptions then
      v_gift_reason := 'exhausted';
    elsif v_gi.budget_max is not null and (
            select coalesce(sum(cr.discount_amount), 0) from coupon_redemption cr join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_gi.id and coalesce(s.status,'') <> 'cancelled'
          ) >= v_gi.budget_max then
      v_gift_reason := 'exhausted';
    elsif v_cust_existing is not null and (
            select count(*) from coupon_redemption cr join sale s on s.id = cr.sale_id
            where cr.coupon_id = v_gi.id and cr.customer_id = v_cust_existing and coalesce(s.status,'') <> 'cancelled'
          ) >= v_gi.max_per_customer then
      v_gift_reason := 'per_customer';
    end if;

    if v_gift_reason is null then
      v_gift_applied := true;
      v_preview := v_preview || jsonb_build_array(jsonb_build_object(
        'name', v_gift_name, 'quantity', 1, 'unitPrice', 0, 'lineTotal', 0, 'valid', true,
        'offer', jsonb_build_object('kind', 'free_item', 'giftValue', round(v_gift_price, 2))));
    end if;
  end if;

  if v_coupon.id is null and v_fd_applied then
    v_coupon_json := jsonb_build_object(
      'applied', true, 'code', v_fd.code, 'label', v_fd.name, 'discount', 0,
      'reason', null, 'isWelcome', false, 'isFrequency', false, 'freeDelivery', true);
  elsif v_coupon.id is null and v_coupon_code is not null and v_fd.id is not null
        and v_fd.code is not null and lower(v_fd.code) = lower(v_coupon_code) then
    v_coupon_json := jsonb_build_object(
      'applied', false, 'code', v_fd.code, 'label', v_fd.name,
      'reason', v_fd_reason, 'isWelcome', false, 'isFrequency', false, 'freeDelivery', false);
  else
    v_coupon_json := v_coupon_json || jsonb_build_object('freeDelivery', v_fd_applied);
  end if;

  if v_gi.id is not null and v_gift_name is not null then
    v_coupon_json := v_coupon_json || jsonb_build_object('giftItem', jsonb_build_object(
      'name', v_gift_name, 'value', round(v_gift_price, 2),
      'min', v_gi.min_subtotal, 'applied', v_gift_applied, 'reason', v_gift_reason));
  end if;

  v_total := v_subtotal - v_discount - v_fd_discount + v_delivery;

  if p_dry_run then
    return jsonb_build_object(
      'ok', true, 'dryRun', true,
      'subtotal', round(v_subtotal,2),
      'deliveryFee', round(v_delivery,2),
      'discount', round(v_discount + v_fd_discount,2),
      'total', round(v_total,2),
      'lines', v_preview,
      'coupon', v_coupon_json
    );
  end if;

  v_addr := nullif(btrim(
              coalesce(p_payload#>>'{delivery,address}','') || ' · ' ||
              coalesce(p_payload#>>'{delivery,detail}',''),
              ' ·'), '');

  v_sale_id := gen_random_uuid();
  v_code    := 'FS' || upper(left(replace(v_sale_id::text,'-',''), 5));
  v_token   := replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-','');

  insert into sale (id, account_id, channel_id, location_id, source,
                    sold_at, total, delivery_cost, discount_amount, service_type,
                    status, order_status, platform_order_code, public_token,
                    customer_name, customer_phone, delivery_address, customer_note,
                    expected_time, payment_method, payment_status, dispatch_mode, raw_tab, created_by_name)
  values (v_sale_id, v_acc, v_channel, v_location, 'folvy_shop',
          now(), round(v_total,2), round(v_delivery,2), round(v_discount + v_fd_discount,2), v_service,
          'open', 'new', v_code, v_token,
          nullif(p_payload#>>'{customer,name}',''),
          nullif(p_payload#>>'{customer,phone}',''),
          v_addr,
          nullif(p_payload#>>'{delivery,note}',''),
          v_expected,
          v_pay_mode,
          case when v_is_cash then 'pending' else 'pending' end,
          'auto',
          p_payload::text,
          'Folvy Shop');

  perform public.adapt_folvy_shop_order(v_sale_id);

  if v_gift_applied then
    insert into sale_line (account_id, sale_id, product_name, raw_text, line_type,
                           quantity, unit_price, line_total, menu_item_id,
                           map_source, map_needs_review, unmapped_reason,
                           external_source, external_product_id, external_brand_id)
    values (v_acc, v_sale_id, v_gift_name || ' · Regalo', v_gift_name || ' · Regalo', 'product',
            1, 0, 0, v_gift_id, 'pos', false, null,
            'folvy_shop', v_gift_id::text, (select brand_id::text from menu_item where id = v_gift_id));
  end if;

  perform public.compute_sale_line_cost(sl.id)
  from sale_line sl
  where sl.sale_id = v_sale_id and coalesce(sl.line_type,'product') = 'product';

  select array_agg(distinct mi.brand_id)
  into v_brand_arr
  from sale_line sl
  join menu_item mi on mi.id = sl.menu_item_id
  where sl.sale_id = v_sale_id and sl.line_type = 'product' and mi.brand_id is not null;

  update sale
  set brand_id = case when coalesce(array_length(v_brand_arr,1),0) = 1 then v_brand_arr[1] else null end
  where id = v_sale_id;

  v_name    := nullif(btrim(p_payload#>>'{customer,name}'), '');
  v_terms   := nullif(p_payload#>>'{consent,termsVersion}', '');

  if v_email is not null or v_phone is not null then
    if v_email is not null then
      select id into v_customer from customer
      where account_id = v_acc and lower(email) = v_email limit 1;
    end if;
    if v_customer is null and v_phone is not null then
      select id into v_customer from customer
      where account_id = v_acc and phone = v_phone limit 1;
    end if;

    if v_customer is null then
      insert into customer (account_id, phone, email, name, first_brand_id, first_location_id)
      values (v_acc, v_phone, v_email, v_name,
              case when coalesce(array_length(v_brand_arr,1),0) = 1 then v_brand_arr[1] else null end,
              v_location)
      returning id into v_customer;
    else
      update customer set
        email      = coalesce(email, v_email),
        phone      = coalesce(phone, v_phone),
        name       = coalesce(name, v_name),
        last_seen_at = now(),
        updated_at   = now()
      where id = v_customer;
    end if;

    update sale set customer_id = v_customer where id = v_sale_id;

    if v_consent and v_email is not null then
      insert into customer_consent (customer_id, account_id, marketing_email, updated_at)
      values (v_customer, v_acc, true, now())
      on conflict (customer_id) do update set marketing_email = true, updated_at = now();

      insert into customer_consent_log (customer_id, account_id, action, channel, source, terms_version)
      values (v_customer, v_acc, 'granted', 'email', 'shop', v_terms);
    end if;
  end if;

  if v_customer is not null and v_mode = 'delivery' then
    v_seed_addr := nullif(btrim(p_payload#>>'{delivery,address}'), '');
    if v_seed_addr is not null then
      begin
        update customer_address set
          detail     = coalesce(nullif(btrim(p_payload#>>'{delivery,detail}'),''), detail),
          lat        = coalesce(nullif(p_payload#>>'{delivery,lat}','')::numeric, lat),
          lng        = coalesce(nullif(p_payload#>>'{delivery,lng}','')::numeric, lng),
          updated_at = now()
        where customer_id = v_customer and lower(address) = lower(v_seed_addr);

        if not found then
          insert into customer_address (customer_id, account_id, address, detail, lat, lng, is_default)
          values (v_customer, v_acc, v_seed_addr,
                  nullif(btrim(p_payload#>>'{delivery,detail}'),''),
                  nullif(p_payload#>>'{delivery,lat}','')::numeric,
                  nullif(p_payload#>>'{delivery,lng}','')::numeric,
                  not exists (select 1 from customer_address where customer_id = v_customer));
        end if;
      exception when others then null;
      end;
    end if;
  end if;

  if v_coupon.id is not null and v_discount > 0 then
    if v_is_frequency then
      insert into coupon_redemption (
        coupon_id, account_id, sale_id, customer_id, customer_email, customer_phone,
        discount_amount, reference_subtotal, margin_after, is_cycle)
      values (
        v_coupon.id, v_acc, v_sale_id, v_customer, v_email, v_phone,
        round(v_discount,2), round(v_subtotal,2),
        case when v_cost_has_null then null else round(v_subtotal - v_discount - v_cost_known, 2) end,
        true);
    else
      if v_customer is not null then
        delete from coupon_redemption cr using sale s
        where cr.coupon_id = v_coupon.id and cr.customer_id = v_customer
          and s.id = cr.sale_id and coalesce(s.status,'') = 'cancelled';
      end if;

      begin
        insert into coupon_redemption (
          coupon_id, account_id, sale_id, customer_id, customer_email, customer_phone,
          discount_amount, reference_subtotal, margin_after)
        values (
          v_coupon.id, v_acc, v_sale_id, v_customer, v_email, v_phone,
          round(v_discount,2), round(v_subtotal,2),
          case when v_cost_has_null then null else round(v_subtotal - v_discount - v_cost_known, 2) end);
      exception when unique_violation then
        update sale set discount_amount = round(v_fd_discount,2), total = round(v_subtotal - v_fd_discount + v_delivery, 2)
        where id = v_sale_id;
        v_discount := 0;
        v_total := v_subtotal - v_fd_discount + v_delivery;
        v_coupon_json := jsonb_build_object('applied', false, 'reason', 'per_customer', 'freeDelivery', v_fd_applied);
      end;
    end if;
  end if;

  if v_fd.id is not null and v_fd_discount > 0 then
    begin
      insert into coupon_redemption (
        coupon_id, account_id, sale_id, customer_id, customer_email, customer_phone,
        discount_amount, reference_subtotal, margin_after, is_cycle)
      values (
        v_fd.id, v_acc, v_sale_id, v_customer, v_email, v_phone,
        round(v_fd_discount,2), round(v_subtotal,2), case when v_cost_has_null then null else round(v_subtotal - v_cost_known - v_fd_discount, 2) end, true);
    exception when others then null;
    end;
  end if;

  for v_promo_cid, v_promo_du in
    select key, value::numeric from jsonb_each_text(v_item_promo)
  loop
    if v_promo_du > 0 then
      begin
        insert into coupon_redemption (
          coupon_id, account_id, sale_id, customer_id, customer_email, customer_phone,
          discount_amount, reference_subtotal, margin_after, is_cycle)
        values (
          v_promo_cid::uuid, v_acc, v_sale_id, v_customer, v_email, v_phone,
          round(v_promo_du,2), round(v_subtotal,2), case when v_cost_has_null then null else round(v_subtotal - v_cost_known, 2) end, true);
      exception when others then null;
      end;
    end if;
  end loop;

  if v_gift_applied then
    begin
      insert into coupon_redemption (coupon_id, account_id, sale_id, customer_id, customer_email, customer_phone,
        discount_amount, reference_subtotal, margin_after, is_cycle)
      values (v_gi.id, v_acc, v_sale_id, v_customer, v_email, v_phone,
        round(v_gift_price, 2), round(v_subtotal, 2), case when v_cost_has_null then null else round(v_subtotal - v_cost_known - (select ri.computed_cost + coalesce(mi.packaging_cost, 0) from menu_item mi join recipe_item ri on ri.id = mi.recipe_item_id where mi.id = v_gift_id and ri.computed_cost is not null), 2) end, true);
    exception when others then null;
    end;
  end if;

  if v_is_cash then
    update sale set order_status = 'accepted' where id = v_sale_id and order_status = 'new';
  end if;

  return jsonb_build_object(
    'ok', true, 'dryRun', false,
    'saleId', v_sale_id,
    'code', v_code,
    'publicToken', v_token,
    'accepted', v_is_cash,
    'subtotal', round(v_subtotal,2),
    'deliveryFee', round(v_delivery,2),
    'discount', round(v_discount + v_fd_discount,2),
    'total', round(v_total,2),
    'coupon', v_coupon_json
  );
end;
$$;


--
-- Name: platform_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_metrics() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mrr    numeric := 0;
  v_result jsonb;
BEGIN
  IF NOT current_user_is_admin() THEN
    RAISE EXCEPTION 'Acceso denegado: solo platform admins pueden ver las métricas.';
  END IF;

  -- MRR estimado: por suscripción activa de cliente (no interna):
  --   plan base + per_location × exceso(locales, max_locations; 0=ilimitado)
  --   + add-ons activos (unit_price × cantidad)
  --   − descuento activo del cliente (percent o fixed), con suelo en 0.
  SELECT COALESCE(SUM(net), 0) INTO v_mrr
  FROM (
    SELECT GREATEST(0,
      (
        bp.base_price_eur
        + bp.per_location_price * (CASE
            WHEN COALESCE(bp.max_locations, 0) = 0 THEN 0   -- 0 = ilimitado
            ELSE GREATEST(0,
              (SELECT count(*) FROM locations l WHERE l.account_id = s.account_id AND l.active)
              - bp.max_locations)
          END)
        + COALESCE((
            SELECT SUM(si.unit_price_eur * si.quantity)
            FROM subscription_items si
            JOIN submodules sm ON sm.id = si.submodule_id
            WHERE si.subscription_id = s.id AND si.status = 'active' AND sm.type = 'addon'
          ), 0)
      ) * (CASE WHEN d.discount_type = 'percent' THEN (1 - d.value / 100.0) ELSE 1 END)
        - (CASE WHEN d.discount_type = 'fixed' THEN d.value ELSE 0 END)
    ) AS net
    FROM subscriptions s
    JOIN billing_plans bp ON bp.id = s.plan_id
    JOIN accounts a       ON a.id = s.account_id
    LEFT JOIN LATERAL (
      SELECT discount_type, value
      FROM account_discount ad
      WHERE ad.account_id = s.account_id AND ad.active
        AND (ad.valid_until IS NULL OR ad.valid_until > now())
      ORDER BY ad.created_at DESC
      LIMIT 1
    ) d ON true
    WHERE s.status = 'active' AND NOT COALESCE(a.is_internal, false)
  ) t;

  v_result := jsonb_build_object(
    'clients_active', (SELECT count(*) FROM accounts WHERE status='active' AND NOT COALESCE(is_internal,false)),
    'clients_total',  (SELECT count(*) FROM accounts WHERE NOT COALESCE(is_internal,false)),
    'accounts_by_status', (
      SELECT COALESCE(jsonb_object_agg(status, c), '{}'::jsonb)
      FROM (SELECT status, count(*) c FROM accounts WHERE NOT COALESCE(is_internal,false) GROUP BY status) t),
    'mrr_eur', round(v_mrr, 2),
    'arr_eur', round(v_mrr * 12, 2),
    'subs_active',       (SELECT count(*) FROM subscriptions s JOIN accounts a ON a.id=s.account_id WHERE s.status='active' AND NOT COALESCE(a.is_internal,false)),
    'subs_trial',        (SELECT count(*) FROM subscriptions s JOIN accounts a ON a.id=s.account_id WHERE s.status='trial'  AND NOT COALESCE(a.is_internal,false)),
    'subs_without_plan', (SELECT count(*) FROM subscriptions s JOIN accounts a ON a.id=s.account_id WHERE s.plan_id IS NULL AND NOT COALESCE(a.is_internal,false)),
    'subs_by_plan', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('plan', plan, 'status', st, 'count', c) ORDER BY plan, st), '[]'::jsonb)
      FROM (
        SELECT COALESCE(bp.code, '(sin plan)') plan, s.status st, count(*) c
        FROM subscriptions s
        LEFT JOIN billing_plans bp ON bp.id = s.plan_id
        JOIN accounts a ON a.id = s.account_id
        WHERE NOT COALESCE(a.is_internal, false)
        GROUP BY bp.code, s.status) t),
    'signups_by_month', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('month', m, 'count', c) ORDER BY m), '[]'::jsonb)
      FROM (
        SELECT to_char(date_trunc('month', created_at), 'YYYY-MM') m, count(*) c
        FROM accounts
        WHERE NOT COALESCE(is_internal, false)
          AND created_at >= date_trunc('month', now()) - interval '11 months'
        GROUP BY date_trunc('month', created_at)) t),
    'usage_active_30d', (SELECT count(DISTINCT s.account_id) FROM sale s JOIN accounts a ON a.id=s.account_id WHERE NOT COALESCE(a.is_internal,false) AND s.created_at >= now()-interval '30 days'),
    'usage_active_7d',  (SELECT count(DISTINCT s.account_id) FROM sale s JOIN accounts a ON a.id=s.account_id WHERE NOT COALESCE(a.is_internal,false) AND s.created_at >= now()-interval '7 days'),
    'client_sales_total', (SELECT count(*) FROM sale s JOIN accounts a ON a.id=s.account_id WHERE NOT COALESCE(a.is_internal,false)),
    'client_sales_30d',   (SELECT count(*) FROM sale s JOIN accounts a ON a.id=s.account_id WHERE NOT COALESCE(a.is_internal,false) AND s.created_at >= now()-interval '30 days'),
    'platform_admins_active', (SELECT count(*) FROM platform_admins WHERE active),
    'generated_at', now()
  );

  RETURN v_result;
END;
$$;


--
-- Name: pos_floor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_floor(p_account_id uuid, p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb;
begin
  if not public._pos_can_operate(p_account_id, p_location_id) then
    raise exception 'pos_floor: sin acceso a esta cuenta/local';
  end if;
  with live as (
    select s.* from sale s
    where s.account_id = p_account_id and s.location_id = p_location_id
      and s.table_id is not null and s.table_cleared_at is null and s.status <> 'cancelled'
  ),
  t as (
    select dt.*, l.id as sale_id,
      case when l.id is null then null else jsonb_build_object(
        'id', l.id,
        'covers', l.covers,
        'openedAt', coalesce(l.opened_at, l.created_at),
        'total', l.total,
        'servedByName', l.served_by_name,
        'state', public._pos_table_state(l),
        'fireCount', (select count(*) from sale_fire f where f.sale_id = l.id),
        'lastFireAt', (select max(f.fired_at) from sale_fire f where f.sale_id = l.id),
        'pendingCount', (select count(*) from sale_line sl where sl.sale_id = l.id
                           and sl.parent_sale_line_id is null and sl.fire_id is null),
        'billRequestedAt', l.bill_requested_at,
        'paidAt', l.paid_at
      ) end as sale_json
    from dining_table dt
    left join live l on l.table_id = dt.id
    where dt.account_id = p_account_id and dt.location_id = p_location_id and dt.is_active
  )
  select jsonb_build_object(
    'warnMinutes', coalesce((select table_warn_minutes from dining_config where location_id = p_location_id), 90),
    'zones', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', z.id, 'name', z.name, 'kind', z.kind, 'sortOrder', z.sort_order,
        'tables', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', t.id, 'name', t.name, 'seats', t.seats, 'gridWidth', t.grid_width,
            'sortOrder', t.sort_order, 'sale', t.sale_json
          ) order by t.sort_order, t.name) from t where t.zone_id = z.id), '[]'::jsonb)
      ) order by z.sort_order, z.name)
      from dining_zone z
      where z.account_id = p_account_id and z.location_id = p_location_id and z.is_active
    ), '[]'::jsonb)
  ) into v;
  return v;
end $$;


--
-- Name: pos_item_config(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_item_config(p_account_id uuid, p_location_id uuid, p_menu_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item  record;
  v_slots jsonb;
begin
  if not public._pos_can_operate(p_account_id, p_location_id) then
    raise exception 'pos_item_config: sin acceso a esta cuenta/local';
  end if;

  select mi.id, mi.name, mi.description, mi.photo_url, mi.price, mi.product_type, mi.recipe_item_id, mi.brand_id
    into v_item
  from menu_item mi
  join brand_location_availability bla
    on bla.brand_id = mi.brand_id and bla.location_id = p_location_id and bla.is_active
  where mi.id = p_menu_item_id and mi.account_id = p_account_id
    and mi.is_active is not false and not exists (
       select 1 from product_availability pa
        where pa.account_id = mi.account_id
          and pa.is_available = false
          and (pa.available_until is null or pa.available_until > now())
          and (pa.location_id = p_location_id or pa.location_id is null)
          and ((mi.external_id is not null and pa.external_id = mi.external_id)
            or (mi.recipe_item_id is not null and pa.recipe_item_id = mi.recipe_item_id))
     ) and mi.archived_at is null;

  if v_item.id is null then return null; end if;

  if v_item.product_type = 'combo' then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', cs.id,
             'name', cs.name,
             'min', cs.min_selections,
             'max', cs.max_selections,
             'options', (
               select coalesce(jsonb_agg(jsonb_build_object(
                        'menu_item_id', omi.id,
                        'name', omi.name,
                        'photo_url', omi.photo_url,
                        'price_impact', cso.price_impact,
                        'is_default', cso.is_default,
                        'allergens', _allergens_of_recipe(omi.recipe_item_id),
                        'modifier_groups', _modgroups_of_item(omi.id)
                      ) order by cso.position nulls last, omi.name), '[]'::jsonb)
               from combo_slot_option cso
               join menu_item omi on omi.id = cso.menu_item_id
               where cso.combo_slot_id = cs.id and cso.is_active and omi.is_active is not false
             )
           ) order by cs.position nulls last), '[]'::jsonb)
    into v_slots
    from combo_slot cs
    where cs.combo_item_id = v_item.id and cs.is_active;
  else
    v_slots := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'id', v_item.id,
    'name', v_item.name,
    'description', v_item.description,
    'photo_url', v_item.photo_url,
    'price', v_item.price,
    'product_type', v_item.product_type,
    'allergens', _allergens_of_recipe(v_item.recipe_item_id),
    'modifier_groups', _modgroups_of_item(v_item.id),
    'slots', v_slots
  );
end;
$$;


--
-- Name: pos_open_sales(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_open_sales(p_account_id uuid, p_location_id uuid, p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  if not public._pos_can_operate(p_account_id, p_location_id) then
    raise exception 'pos_open_sales: sin acceso a esta cuenta/local';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id,
           'posShortCode', s.pos_short_code,
           'status', s.status,
           'orderStatus', s.order_status,
           'paymentStatus', s.payment_status,
           'brandId', s.brand_id,
           'total', s.total,
           'openedAt', coalesce(s.opened_at, s.created_at),
           'rawTab', s.raw_tab,
           'lineCount', (select count(*) from sale_line sl where sl.sale_id = s.id and sl.parent_sale_line_id is null),
           'createdByName', s.created_by_name,
           'deviceId', s.device_id
         ) order by coalesce(s.opened_at, s.created_at) asc), '[]'::jsonb)
    into v_result
  from sale s
  where s.account_id = p_account_id
    and s.location_id = p_location_id
    and s.source = 'folvy_pos'
    and s.status = 'open'
    and s.table_id is null
    and coalesce(s.opened_at, s.created_at) >= now() - (greatest(p_hours, 1) || ' hours')::interval;

  return v_result;
end;
$$;


--
-- Name: FUNCTION pos_open_sales(p_account_id uuid, p_location_id uuid, p_hours integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pos_open_sales(p_account_id uuid, p_location_id uuid, p_hours integer) IS 'Cuentas abiertas (status=open) del TPV para el panel "Cuentas" (11/08,
   TPV T1.d Tarea A.1) — sustituye la consulta directa a sale que hacía el
   cliente, que rompía el patrón _pos_can_operate. Orden created_at asc: la
   más vieja primero. Límite de 24h por defecto (parametrizable).';


--
-- Name: pos_pending_delivery_sales(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_pending_delivery_sales(p_account_id uuid, p_location_id uuid, p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  if not public._pos_can_operate(p_account_id, p_location_id) then
    raise exception 'pos_pending_delivery_sales: sin acceso a esta cuenta/local';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id,
           'posShortCode', s.pos_short_code,
           'status', s.status,
           'orderStatus', s.order_status,
           'paymentStatus', s.payment_status,
           'brandId', s.brand_id,
           'total', s.total,
           'openedAt', coalesce(s.opened_at, s.created_at),
           'rawTab', s.raw_tab,
           'lineCount', (select count(*) from sale_line sl where sl.sale_id = s.id and sl.parent_sale_line_id is null),
           'createdByName', s.created_by_name,
           'deviceId', s.device_id
         ) order by coalesce(s.opened_at, s.created_at) asc), '[]'::jsonb)
    into v_result
  from sale s
  where s.account_id = p_account_id
    and s.location_id = p_location_id
    and s.source = 'folvy_pos'
    and s.status = 'closed'
    -- order_status='accepted' a propósito, no "<> 'completed'" (probado y
    -- descartado: cuela cancelled/rejected — ver fichero de Code).
    and s.order_status = 'accepted'
    and coalesce(s.opened_at, s.created_at) >= now() - (greatest(p_hours, 1) || ' hours')::interval;

  return v_result;
end;
$$;


--
-- Name: FUNCTION pos_pending_delivery_sales(p_account_id uuid, p_location_id uuid, p_hours integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pos_pending_delivery_sales(p_account_id uuid, p_location_id uuid, p_hours integer) IS 'Ventas cobradas (status=closed) pendientes de marcar Entregado (11/08,
   TPV T1.d) — hermana de pos_open_sales, mismo hueco de arquitectura
   cerrado (antes: consulta directa a sale desde el cliente). order_status
   filtrado a ''accepted'' explícitamente, no ''<> completed'': evita colar
   ventas cancelled/rejected como si estuvieran pendientes de entregar.';


--
-- Name: pos_table_add_lines(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_add_lines(p_sale_id uuid, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s sale; v_line jsonb; v_n int := 0;
begin
  v_s := public._pos_table_sale(p_sale_id);
  perform public._pos_table_assert_open(v_s);
  if jsonb_typeof(p_lines) <> 'array' then raise exception 'pos_table_add_lines: p_lines no es una lista'; end if;
  for v_line in select * from jsonb_array_elements(p_lines) loop
    perform public._pos_insert_order_line(p_sale_id, v_line);
    v_n := v_n + 1;
  end loop;
  perform public._pos_table_recalc_totals(p_sale_id);
  return jsonb_build_object('added', v_n);
end $$;


--
-- Name: pos_table_charge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_charge(p_sale_id uuid, p_payment_method text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s sale; v_pending int;
begin
  v_s := public._pos_table_sale(p_sale_id);
  perform public._pos_table_assert_open(v_s);
  if p_payment_method not in ('cash', 'card') then raise exception 'Cobrar exige efectivo o tarjeta.'; end if;
  select count(*) into v_pending from sale_line
  where sale_id = p_sale_id and parent_sale_line_id is null and fire_id is null;
  if v_pending > 0 then
    raise exception 'Hay % línea(s) sin enviar a cocina. Envíalas o quítalas antes de cobrar.', v_pending;
  end if;
  if not exists (select 1 from sale_line where sale_id = p_sale_id and parent_sale_line_id is null) then
    raise exception 'La mesa no tiene nada pedido: no hay nada que cobrar.';
  end if;
  update sale set status = 'closed', payment_method = p_payment_method, payment_status = 'paid',
                  paid_at = now(), closed_at = coalesce(closed_at, now()), updated_at = now()
  where id = p_sale_id;
  select * into v_s from sale where id = p_sale_id;
  return jsonb_build_object('ok', true, 'total', v_s.total, 'paymentMethod', v_s.payment_method);
end $$;


--
-- Name: pos_table_clear(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_clear(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s sale;
begin
  v_s := public._pos_table_sale(p_sale_id);
  if v_s.table_cleared_at is not null then return jsonb_build_object('ok', true); end if;
  if v_s.paid_at is null then
    if exists (select 1 from sale_line where sale_id = p_sale_id) then
      raise exception 'La mesa tiene cosas pedidas y no está cobrada.';
    end if;
    update sale set status = 'cancelled', cancelled_at = now(), cancel_reason = 'Mesa abierta por error (sin nada pedido)',
                    table_cleared_at = now(), updated_at = now()
    where id = p_sale_id;
    return jsonb_build_object('ok', true, 'cancelled', true);
  end if;
  update sale set table_cleared_at = now(), order_status = 'completed', updated_at = now() where id = p_sale_id;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: pos_table_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_detail(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s sale; v jsonb;
begin
  v_s := public._pos_table_sale(p_sale_id);
  select jsonb_build_object(
    'saleId', v_s.id, 'posShortCode', v_s.pos_short_code, 'brandId', v_s.brand_id,
    'tableId', dt.id, 'tableName', dt.name, 'seats', dt.seats,
    'zoneId', z.id, 'zoneName', z.name, 'zoneKind', z.kind,
    'covers', v_s.covers, 'openedAt', coalesce(v_s.opened_at, v_s.created_at),
    'servedByName', v_s.served_by_name, 'total', v_s.total,
    'state', public._pos_table_state(v_s),
    'billRequestedAt', v_s.bill_requested_at, 'paidAt', v_s.paid_at,
    'paymentMethod', v_s.payment_method,
    'fires', coalesce((select jsonb_agg(jsonb_build_object(
        'id', f.id, 'number', f.fire_number, 'firedAt', f.fired_at, 'firedByName', f.fired_by_name,
        'originTableName', f.origin_table_name
      ) order by f.fire_number) from sale_fire f where f.sale_id = v_s.id), '[]'::jsonb),
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
        'id', sl.id, 'name', sl.product_name, 'menuItemId', sl.menu_item_id,
        'quantity', sl.quantity, 'unitPrice', sl.unit_price, 'lineTotal', sl.line_total,
        'kitchenNote', sl.kitchen_note, 'fireId', sl.fire_id, 'voidedAt', sl.voided_at,
        'voidReason', (select v.reason_label from sale_line_void v where v.sale_line_id = sl.id),
        'createdAt', sl.created_at,
        'summary', coalesce((select jsonb_agg(h.product_name order by h.created_at)
                             from sale_line h where h.parent_sale_line_id = sl.id), '[]'::jsonb)
      ) order by sl.created_at, sl.id)
      from sale_line sl where sl.sale_id = v_s.id and sl.parent_sale_line_id is null), '[]'::jsonb)
  ) into v
  from dining_table dt join dining_zone z on z.id = dt.zone_id
  where dt.id = v_s.table_id;
  return v;
end $$;


--
-- Name: pos_table_fire(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_fire(p_sale_id uuid, p_lines jsonb DEFAULT '[]'::jsonb, p_device_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s sale; v_line jsonb; v_fire uuid; v_num int; v_n int; v_jobs int;
begin
  v_s := public._pos_table_sale(p_sale_id);
  perform public._pos_table_assert_open(v_s);
  perform 1 from sale where id = p_sale_id for update;
  if jsonb_typeof(p_lines) = 'array' then
    for v_line in select * from jsonb_array_elements(p_lines) loop
      perform public._pos_insert_order_line(p_sale_id, v_line);
    end loop;
  end if;
  select count(*) into v_n from sale_line
  where sale_id = p_sale_id and parent_sale_line_id is null and fire_id is null and voided_at is null;
  if v_n = 0 then raise exception 'No hay nada nuevo que enviar.'; end if;
  select coalesce(max(fire_number), 0) + 1 into v_num from sale_fire where sale_id = p_sale_id;
  insert into sale_fire (account_id, location_id, sale_id, fire_number, fired_by, fired_by_name, device_id)
  values (v_s.account_id, v_s.location_id, p_sale_id, v_num, auth.uid(), public._pos_actor_name(v_s.account_id),
          public._pos_device_for(p_device_token, v_s.account_id, v_s.location_id))
  returning id into v_fire;
  with recursive arbol as (
    select id from sale_line
    where sale_id = p_sale_id and parent_sale_line_id is null and fire_id is null and voided_at is null
    union all
    select h.id from sale_line h join arbol a on h.parent_sale_line_id = a.id
  )
  update sale_line set fire_id = v_fire where id in (select id from arbol);
  perform public._pos_table_recalc_totals(p_sale_id);
  update sale set order_status = coalesce(order_status, 'accepted') where id = p_sale_id;
  v_jobs := public._pos_enqueue_print(v_s, 'kitchen',
              jsonb_build_object('mode', 'by_order', 'sale_id', p_sale_id, 'fire_id', v_fire, 'fire_number', v_num));
  return jsonb_build_object('fireId', v_fire, 'fireNumber', v_num, 'lineCount', v_n, 'printJobs', v_jobs);
end $$;


--
-- Name: pos_table_move(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_move(p_sale_id uuid, p_to_table_id uuid, p_device_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s sale; v_d sale; v_to dining_table; v_from_name text; v_base int; v_amount numeric;
  v_dev uuid; v_has_fires boolean; v_jobs int := 0;
begin
  v_s := public._pos_table_sale(p_sale_id);
  perform public._pos_table_assert_open(v_s);
  v_to := public._pos_dest_table(p_to_table_id, v_s);
  if v_to.id = v_s.table_id then raise exception 'Es la misma mesa.'; end if;
  select name into v_from_name from dining_table where id = v_s.table_id;
  v_dev := public._pos_device_for(p_device_token, v_s.account_id, v_s.location_id);
  v_has_fires := exists (select 1 from sale_fire where sale_id = v_s.id);
  perform 1 from sale where id = v_s.id for update;
  select * into v_d from sale
  where table_id = v_to.id and table_cleared_at is null and status <> 'cancelled'
  for update;
  if v_d.id is null then
    update sale set table_id = v_to.id, updated_at = now() where id = v_s.id;
    insert into sale_table_move (account_id, location_id, kind, from_sale_id, to_sale_id, from_table_id, to_table_id,
                                 amount_moved, moved_by, moved_by_name, device_id)
    values (v_s.account_id, v_s.location_id, 'move', v_s.id, v_s.id, v_s.table_id, v_to.id,
            v_s.total, auth.uid(), public._pos_actor_name(v_s.account_id), v_dev);
    if v_has_fires then
      v_jobs := public._pos_print_table_notice(v_s, 'CAMBIO DE MESA', 'MESA ' || upper(v_from_name) || ' → ' || upper(v_to.name), null);
    end if;
    return jsonb_build_object('kind', 'move', 'saleId', v_s.id, 'tableName', v_to.name, 'covers', v_s.covers,
                              'total', v_s.total, 'printJobs', v_jobs);
  end if;
  if v_d.paid_at is not null then
    raise exception 'La mesa % está cobrada y sin recoger: primero «Mesa lista».', v_to.name;
  end if;
  select coalesce(max(fire_number), 0) into v_base from sale_fire where sale_id = v_d.id;
  update sale_fire
     set sale_id = v_d.id,
         fire_number = fire_number + v_base,
         origin_table_name = coalesce(origin_table_name, v_from_name)
   where sale_id = v_s.id;
  update sale_line set sale_id = v_d.id, updated_at = now() where sale_id = v_s.id;
  update sale_line_void set sale_id = v_d.id where sale_id = v_s.id;
  v_amount := v_s.total;
  update sale set
    status = 'cancelled', cancelled_at = now(),
    cancel_reason = 'Juntada con la mesa ' || v_to.name,
    merged_into_sale_id = v_d.id,
    table_cleared_at = now(),
    total = 0, taxable_base = 0, tax = 0,
    updated_at = now()
  where id = v_s.id;
  perform public.generate_sale_consumption(v_s.id);
  update sale set
    covers = covers + v_s.covers,
    opened_at = least(coalesce(opened_at, created_at), coalesce(v_s.opened_at, v_s.created_at)),
    order_status = coalesce(order_status, v_s.order_status),
    bill_requested_at = null,
    updated_at = now()
  where id = v_d.id;
  perform public._pos_table_recalc_totals(v_d.id);
  perform public.generate_sale_consumption(v_d.id);
  insert into sale_table_move (account_id, location_id, kind, from_sale_id, to_sale_id, from_table_id, to_table_id,
                               covers_moved, amount_moved, moved_by, moved_by_name, device_id)
  values (v_s.account_id, v_s.location_id, 'merge', v_s.id, v_d.id, v_s.table_id, v_to.id,
          v_s.covers, v_amount, auth.uid(), public._pos_actor_name(v_s.account_id), v_dev);
  if v_has_fires then
    v_jobs := public._pos_print_table_notice(v_d, 'MESAS JUNTAS', 'MESA ' || upper(v_from_name) || ' → ' || upper(v_to.name), null);
  end if;
  select * into v_d from sale where id = v_d.id;
  return jsonb_build_object('kind', 'merge', 'saleId', v_d.id, 'tableName', v_to.name, 'covers', v_d.covers,
                            'total', v_d.total, 'printJobs', v_jobs);
end $$;


--
-- Name: pos_table_move_lines(uuid[], uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_move_lines(p_line_ids uuid[], p_to_table_id uuid, p_covers integer DEFAULT NULL::integer, p_device_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s sale; v_d sale; v_to dining_table; v_from_name text; v_sale_ids uuid[]; v_dev uuid;
  v_f record; v_new_fire uuid; v_new_sale uuid; v_num int; v_amount numeric; v_notice text[]; v_jobs int := 0; v_n int;
begin
  if p_line_ids is null or array_length(p_line_ids, 1) is null then raise exception 'No hay líneas que mover.'; end if;
  select array_agg(distinct sale_id) into v_sale_ids
  from sale_line where id = any (p_line_ids) and parent_sale_line_id is null;
  if v_sale_ids is null or array_length(v_sale_ids, 1) <> 1 then
    raise exception 'Las líneas tienen que ser de una sola mesa.';
  end if;
  select count(*) into v_n from sale_line where id = any (p_line_ids) and parent_sale_line_id is null;
  if v_n <> array_length(p_line_ids, 1) then raise exception 'Alguna de esas líneas no existe.'; end if;
  v_s := public._pos_table_sale(v_sale_ids[1]);
  perform public._pos_table_assert_open(v_s);
  v_to := public._pos_dest_table(p_to_table_id, v_s);
  if v_to.id = v_s.table_id then raise exception 'Es la misma mesa.'; end if;
  select name into v_from_name from dining_table where id = v_s.table_id;
  v_dev := public._pos_device_for(p_device_token, v_s.account_id, v_s.location_id);
  perform 1 from sale where id = v_s.id for update;
  select * into v_d from sale
  where table_id = v_to.id and table_cleared_at is null and status <> 'cancelled'
  for update;
  if v_d.id is null then
    if p_covers is null or p_covers < 1 then
      raise exception 'La mesa % está libre: hay que decir cuántos son.', v_to.name;
    end if;
    v_new_sale := (public.pos_table_open(v_to.id, p_covers, v_s.brand_id, p_device_token)->>'saleId')::uuid;
    select * into v_d from sale where id = v_new_sale;
  elsif v_d.paid_at is not null then
    raise exception 'La mesa % está cobrada y sin recoger: primero «Mesa lista».', v_to.name;
  end if;
  select coalesce(sum(line_total), 0) into v_amount
  from sale_line where id = any (p_line_ids) or parent_sale_line_id = any (p_line_ids);
  for v_f in
    select distinct f.id, f.fired_at, f.fired_by, f.fired_by_name, f.device_id, f.origin_table_name
    from sale_line sl join sale_fire f on f.id = sl.fire_id
    where sl.id = any (p_line_ids)
  loop
    select coalesce(max(fire_number), 0) + 1 into v_num from sale_fire where sale_id = v_d.id;
    insert into sale_fire (account_id, location_id, sale_id, fire_number, fired_at, fired_by, fired_by_name, device_id,
                           origin_fire_id, origin_table_name)
    values (v_s.account_id, v_s.location_id, v_d.id, v_num, v_f.fired_at, v_f.fired_by, v_f.fired_by_name, v_f.device_id,
            v_f.id, coalesce(v_f.origin_table_name, v_from_name))
    returning id into v_new_fire;
    with recursive arbol as (
      select id from sale_line where id = any (p_line_ids) and fire_id = v_f.id
      union all
      select h.id from sale_line h join arbol a on h.parent_sale_line_id = a.id
    )
    update sale_line set sale_id = v_d.id, fire_id = v_new_fire, updated_at = now() where id in (select id from arbol);
  end loop;
  with recursive arbol as (
    select id from sale_line where id = any (p_line_ids) and fire_id is null
    union all
    select h.id from sale_line h join arbol a on h.parent_sale_line_id = a.id
  )
  update sale_line set sale_id = v_d.id, updated_at = now() where id in (select id from arbol);
  update sale_line_void set sale_id = v_d.id where sale_line_id = any (p_line_ids);
  perform public.generate_sale_consumption(v_s.id);
  update sale set bill_requested_at = null, updated_at = now() where id in (v_s.id, v_d.id);
  update sale set order_status = coalesce(order_status, 'accepted')
  where id = v_d.id and exists (select 1 from sale_fire where sale_id = v_d.id);
  perform public._pos_table_recalc_totals(v_s.id);
  perform public._pos_table_recalc_totals(v_d.id);
  perform public.generate_sale_consumption(v_d.id);
  insert into sale_table_move (account_id, location_id, kind, from_sale_id, to_sale_id, from_table_id, to_table_id,
                               line_ids, amount_moved, moved_by, moved_by_name, device_id)
  values (v_s.account_id, v_s.location_id, 'lines', v_s.id, v_d.id, v_s.table_id, v_to.id,
          p_line_ids, v_amount, auth.uid(), public._pos_actor_name(v_s.account_id), v_dev);
  select array_agg(rtrim(to_char(quantity, 'FM999990.##'), '.') || 'x ' || product_name order by created_at)
    into v_notice
  from sale_line where id = any (p_line_ids) and fire_id is not null and voided_at is null;
  if v_notice is not null then
    v_jobs := public._pos_print_table_notice(v_d, 'CAMBIO DE MESA',
      'DE LA ' || upper(v_from_name) || ' A LA ' || upper(v_to.name), v_notice);
  end if;
  return jsonb_build_object('saleId', v_d.id, 'tableName', v_to.name, 'moved', array_length(p_line_ids, 1),
                            'amount', v_amount, 'printJobs', v_jobs);
end $$;


--
-- Name: pos_table_open(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_open(p_table_id uuid, p_covers integer, p_brand_id uuid, p_device_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_t dining_table; v_id uuid; v_actor text;
begin
  select * into v_t from dining_table where id = p_table_id and is_active;
  if v_t.id is null then raise exception 'Esa mesa no existe.'; end if;
  if not public._pos_can_operate(v_t.account_id, v_t.location_id) then
    raise exception 'Sin acceso a esta cuenta/local.';
  end if;
  if p_covers is null or p_covers < 1 then raise exception 'Hay que decir cuántos son.'; end if;
  if exists (select 1 from sale where table_id = p_table_id and table_cleared_at is null and status <> 'cancelled') then
    raise exception 'La mesa % ya está abierta.', v_t.name;
  end if;
  v_actor := public._pos_actor_name(v_t.account_id);
  insert into sale (
    account_id, location_id, brand_id, channel_id, source, service_type,
    status, order_status, sold_at, opened_at, total, taxable_base, tax,
    pos_short_code, created_by, created_by_name, device_id,
    table_id, covers, served_by, served_by_name
  ) values (
    v_t.account_id, v_t.location_id, p_brand_id, public._pos_sala_channel_id(v_t.account_id),
    'folvy_pos', 'dine_in', 'open', null, now(), now(), 0, 0, 0,
    public._pos_next_ticket_code(v_t.account_id, v_t.location_id), auth.uid(), v_actor,
    public._pos_device_for(p_device_token, v_t.account_id, v_t.location_id),
    v_t.id, p_covers, auth.uid(), v_actor
  ) returning id into v_id;
  return jsonb_build_object('saleId', v_id);
end $$;


--
-- Name: pos_table_remove_pending_line(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_remove_pending_line(p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l sale_line; v_s sale;
begin
  select * into v_l from sale_line where id = p_line_id and parent_sale_line_id is null;
  if v_l.id is null then raise exception 'Esa línea no existe.'; end if;
  v_s := public._pos_table_sale(v_l.sale_id);
  perform public._pos_table_assert_open(v_s);
  if v_l.fire_id is not null then raise exception 'Esa línea ya está en cocina: se anula, no se borra.'; end if;
  delete from sale_line where id = p_line_id;   -- las hijas caen por la FK en cascada
  perform public._pos_table_recalc_totals(v_s.id);
  perform public.generate_sale_consumption(v_s.id);   -- el borrado no dispara el consumo
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: pos_table_request_bill(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_request_bill(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_s sale; v_pending int; v_jobs int;
begin
  v_s := public._pos_table_sale(p_sale_id);
  perform public._pos_table_assert_open(v_s);
  select count(*) into v_pending from sale_line
  where sale_id = p_sale_id and parent_sale_line_id is null and fire_id is null;
  if v_pending > 0 then
    raise exception 'Hay % línea(s) sin enviar a cocina. Envíalas o quítalas antes de sacar la cuenta.', v_pending;
  end if;
  update sale set bill_requested_at = coalesce(bill_requested_at, now()), updated_at = now() where id = p_sale_id;
  v_jobs := public._pos_enqueue_print(v_s, 'bag', jsonb_build_object('mode', 'by_order', 'sale_id', p_sale_id, 'bill', true));
  return jsonb_build_object('ok', true, 'printJobs', v_jobs, 'total', v_s.total);
end $$;


--
-- Name: pos_table_set_pending_qty(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_set_pending_qty(p_line_id uuid, p_quantity numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l sale_line; v_s sale;
begin
  select * into v_l from sale_line where id = p_line_id and parent_sale_line_id is null;
  if v_l.id is null then raise exception 'Esa línea no existe.'; end if;
  v_s := public._pos_table_sale(v_l.sale_id);
  perform public._pos_table_assert_open(v_s);
  if v_l.fire_id is not null then raise exception 'Esa línea ya está en cocina: se anula, no se cambia.'; end if;
  if p_quantity is null or p_quantity < 1 then raise exception 'La cantidad mínima es 1.'; end if;
  update sale_line set quantity = p_quantity, line_total = round(unit_price * p_quantity, 2), updated_at = now()
  where id = p_line_id;
  perform public._pos_table_recalc_totals(v_s.id);
  perform public.generate_sale_consumption(v_s.id);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: pos_table_void_line(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_table_void_line(p_line_id uuid, p_reason_id uuid, p_note text DEFAULT NULL::text, p_device_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_l sale_line; v_s sale; v_r void_reason; v_orig numeric; v_tab text; v_zone text; v_jobs int; v_who text;
begin
  select * into v_l from sale_line where id = p_line_id and parent_sale_line_id is null;
  if v_l.id is null then raise exception 'Esa línea no existe.'; end if;
  v_s := public._pos_table_sale(v_l.sale_id);
  perform public._pos_table_assert_open(v_s);
  if v_l.fire_id is null then raise exception 'Esa línea no se ha enviado: se quita, no se anula.'; end if;
  if v_l.voided_at is not null then raise exception 'Esa línea ya está anulada.'; end if;
  select * into v_r from void_reason where id = p_reason_id and account_id = v_s.account_id and is_active;
  if v_r.id is null then raise exception 'Hay que elegir un motivo.'; end if;
  select coalesce(sum(line_total), 0) into v_orig from sale_line where id = p_line_id or parent_sale_line_id = p_line_id;
  v_who := public._pos_actor_name(v_s.account_id);
  insert into sale_line_void (account_id, sale_id, sale_line_id, reason_id, reason_label, note,
                              original_quantity, original_line_total, voided_by, voided_by_name, device_id)
  values (v_s.account_id, v_s.id, p_line_id, v_r.id, v_r.label, nullif(btrim(p_note), ''),
          v_l.quantity, v_orig, auth.uid(), v_who,
          public._pos_device_for(p_device_token, v_s.account_id, v_s.location_id));
  with recursive arbol as (
    select id from sale_line where id = p_line_id
    union all
    select h.id from sale_line h join arbol a on h.parent_sale_line_id = a.id
  )
  update sale_line set voided_at = now(), line_total = 0, updated_at = now() where id in (select id from arbol);
  perform public._pos_table_recalc_totals(v_s.id);
  select dt.name, z.name into v_tab, v_zone from dining_table dt join dining_zone z on z.id = dt.zone_id where dt.id = v_s.table_id;
  v_jobs := public._pos_enqueue_print(v_s, 'kitchen', jsonb_build_object(
    'title', 'Anulado', 'widthMm', 80, 'blocks', jsonb_build_array(
      jsonb_build_object('kind', 'invertBanner', 'text', 'ANULADO', 'size', 4),
      jsonb_build_object('kind', 'text', 'text', 'MESA ' || upper(v_tab), 'align', 'center', 'bold', true, 'size', 3),
      jsonb_build_object('kind', 'text', 'text', upper(v_zone), 'align', 'center', 'bold', true, 'size', 2),
      jsonb_build_object('kind', 'rule'),
      jsonb_build_object('kind', 'text', 'text', rtrim(to_char(v_l.quantity, 'FM999990.##'), '.') || 'x ' || v_l.product_name, 'bold', true, 'size', 3),
      jsonb_build_object('kind', 'text', 'text', 'Motivo: ' || v_r.label, 'size', 2),
      jsonb_build_object('kind', 'text', 'text', coalesce(v_who, '') || ' · ' || to_char(now() at time zone 'Europe/Madrid', 'HH24:MI'), 'muted', true),
      jsonb_build_object('kind', 'cut')
    )));
  return jsonb_build_object('ok', true, 'printJobs', v_jobs);
end $$;


--
-- Name: pos_void_reasons(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_void_reasons(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin() or public.belongs_to_account(p_account_id)) then
    raise exception 'Sin acceso a esta cuenta.';
  end if;
  if not exists (select 1 from void_reason where account_id = p_account_id) then
    insert into void_reason (account_id, label, sort_order) values
      (p_account_id, 'Error al pedir', 10),
      (p_account_id, 'El cliente lo cambia', 20),
      (p_account_id, 'Tarda demasiado', 30),
      (p_account_id, 'Se ha agotado', 40);
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', id, 'label', label) order by sort_order, label)
                   from void_reason where account_id = p_account_id and is_active), '[]'::jsonb);
end $$;


--
-- Name: post_pending_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pending_receipt(p_receipt_id uuid) RETURNS TABLE(posted integer, still_pending integer, pending_items jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_receipt goods_receipt%ROWTYPE;
  v_line    goods_receipt_line%ROWTYPE;
  v_ok      boolean;
  v_posted  integer := 0;
  v_pending integer := 0;
  v_items   jsonb := '[]'::jsonb;
  v_reason  text;
BEGIN
  SELECT * INTO v_receipt FROM goods_receipt WHERE id = p_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'post_pending_receipt: recepción % no existe', p_receipt_id;
  END IF;
  IF NOT belongs_to_account(v_receipt.account_id) THEN
    RAISE EXCEPTION 'post_pending_receipt: sin acceso';
  END IF;

  -- Recorre TODAS las líneas sin movimiento (con o sin artículo).
  FOR v_line IN
    SELECT * FROM goods_receipt_line grl
    WHERE grl.goods_receipt_id = p_receipt_id
      AND NOT EXISTS (SELECT 1 FROM stock_movement sm
        WHERE sm.source_type='goods_receipt_line' AND sm.source_id = grl.id)
    ORDER BY grl.position ASC
  LOOP
    -- Sin artículo casado: no se puede postear, razón clara.
    IF v_line.recipe_item_id IS NULL THEN
      v_pending := v_pending + 1;
      v_items := v_items || jsonb_build_object(
        'line_id', v_line.id, 'item_id', NULL,
        'name', COALESCE(v_line.product_name, 'Artículo sin nombre'),
        'reason', 'sin_articulo'
      );
      CONTINUE;
    END IF;

    -- Tiene artículo: intentar postear.
    v_ok := public.post_pending_receipt_line(v_line.id);
    IF v_ok THEN
      v_posted := v_posted + 1;
    ELSE
      v_pending := v_pending + 1;
      v_items := v_items || jsonb_build_object(
        'line_id', v_line.id, 'item_id', v_line.recipe_item_id,
        'name', COALESCE(
          (SELECT ri.name FROM recipe_item ri WHERE ri.id = v_line.recipe_item_id),
          v_line.product_name, 'Artículo sin nombre'),
        'reason', 'sin_formato'
      );
    END IF;
  END LOOP;

  posted := v_posted; still_pending := v_pending; pending_items := v_items;
  RETURN NEXT;
END;
$$;


--
-- Name: post_pending_receipt_line(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pending_receipt_line(p_line_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line     goods_receipt_line%ROWTYPE;
  v_receipt  goods_receipt%ROWTYPE;
  v_fmt_id   uuid;
  v_fmt_qib  numeric;
  v_qib      numeric;
  v_eur_base numeric;
  v_area_id  uuid;
  v_user     uuid;
  v_user_name text;
BEGIN
  SELECT * INTO v_line FROM goods_receipt_line WHERE id = p_line_id;
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT * INTO v_receipt FROM goods_receipt WHERE id = v_line.goods_receipt_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF NOT belongs_to_account(v_receipt.account_id) THEN
    RAISE EXCEPTION 'post_pending_receipt_line: sin acceso';
  END IF;

  -- Solo recepciones confirmadas (no borradores: ésos los postea confirm_goods_receipt).
  IF v_receipt.status <> 'confirmado' THEN RETURN false; END IF;

  -- Idempotencia: si ya hay movimiento de esta línea, nada que hacer.
  IF EXISTS (SELECT 1 FROM stock_movement
             WHERE source_type='goods_receipt_line' AND source_id = p_line_id) THEN
    RETURN false;
  END IF;

  IF v_line.recipe_item_id IS NULL THEN RETURN false; END IF;

  -- Resolver formato: el de la línea, o el del proveedor PREFERIDO del artículo.
  v_fmt_id := v_line.purchase_format_id;
  IF v_fmt_id IS NULL THEN
    SELECT a.purchase_format_id INTO v_fmt_id
    FROM article_supplier a
    WHERE a.recipe_item_id = v_line.recipe_item_id
      AND a.account_id = v_receipt.account_id
      AND a.is_active
      AND a.purchase_format_id IS NOT NULL
    ORDER BY a.is_preferred DESC, a.updated_at DESC
    LIMIT 1;
  END IF;

  -- Calcular qty_in_base
  v_qib := NULL;
  IF v_fmt_id IS NOT NULL THEN
    SELECT f.qty_in_base INTO v_fmt_qib
      FROM recipe_item_purchase_format f
      WHERE f.id = v_fmt_id AND f.is_active;
    IF v_fmt_qib IS NOT NULL AND v_fmt_qib > 0
       AND v_line.qty_received IS NOT NULL AND v_line.qty_received > 0 THEN
      v_qib := v_line.qty_received * v_fmt_qib;
    END IF;
  END IF;
  IF v_qib IS NULL THEN v_qib := v_line.qty_in_base; END IF;

  -- Si seguimos sin poder calcular cuánto entra, no posteamos (sigue pendiente).
  IF v_qib IS NULL OR v_qib <= 0 THEN RETURN false; END IF;

  -- Persistir el formato resuelto y la conversión en la línea (deja rastro).
  UPDATE goods_receipt_line
    SET purchase_format_id = COALESCE(purchase_format_id, v_fmt_id),
        qty_in_base = v_qib, updated_at = now()
    WHERE id = p_line_id;

  v_eur_base := public._eur_base_from_format(v_fmt_id, v_line.unit_cost);

  -- Zona principal del artículo en el local
  v_area_id := NULL;
  SELECT sa.id INTO v_area_id
    FROM recipe_item_storage_area risa
    JOIN storage_area sa ON sa.id = risa.storage_area_id
    WHERE risa.recipe_item_id = v_line.recipe_item_id
      AND risa.account_id     = v_receipt.account_id
      AND sa.location_id      = v_receipt.location_id
      AND sa.active
    ORDER BY risa.position ASC, sa.position ASC
    LIMIT 1;

  v_user := auth.uid();
  SELECT display_name INTO v_user_name FROM user_profiles WHERE id = v_user;

  INSERT INTO stock_movement (
    account_id, location_id, recipe_item_id, storage_area_id,
    movement_type, qty_base, unit_cost, cost_provisional,
    source_type, source_id, lot_code, expiry_date,
    occurred_at, created_by, created_by_name, notes
  )
  VALUES (
    v_receipt.account_id, v_receipt.location_id, v_line.recipe_item_id, v_area_id,
    'recepcion', v_qib,
    COALESCE(
      v_eur_base,
      CASE WHEN v_line.unit_cost IS NOT NULL AND v_line.qty_received > 0
           THEN (v_line.unit_cost * v_line.qty_received) / v_qib END
    ),
    true,
    'goods_receipt_line', p_line_id,
    v_line.lot_code, v_line.expiry_date,
    COALESCE(v_receipt.received_at, now()), v_user, v_user_name,
    'Posteo de línea pendiente (formato resuelto tras confirmar)'
  );

  PERFORM recompute_location_stock(v_line.recipe_item_id, v_receipt.location_id);

  IF v_eur_base IS NOT NULL AND v_fmt_id IS NOT NULL THEN
    UPDATE article_supplier
      SET last_price = v_eur_base, updated_at = now()
      WHERE account_id = v_receipt.account_id
        AND recipe_item_id = v_line.recipe_item_id
        AND purchase_format_id = v_fmt_id
        AND is_active;
  END IF;

  -- ¿Quedan líneas pendientes en esta recepción? Pendiente = CUALQUIER línea sin
  -- movimiento de stock (tenga o no artículo: una línea sin casar también está
  -- pendiente). Solo si NO queda ninguna se baja needs_review. Esto evita el
  -- desajuste "indicador dice OK pero falta meter género".
  IF NOT EXISTS (
    SELECT 1 FROM goods_receipt_line grl
    WHERE grl.goods_receipt_id = v_receipt.id
      AND NOT EXISTS (SELECT 1 FROM stock_movement sm
        WHERE sm.source_type='goods_receipt_line' AND sm.source_id = grl.id)
  ) THEN
    UPDATE goods_receipt SET needs_review = false, updated_at = now()
    WHERE id = v_receipt.id;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: prevent_platform_audit_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_platform_audit_modification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'platform_audit_log es inmutable (append-only): operación % no permitida', TG_OP;
END;
$$;


--
-- Name: preview_add_ingredient(uuid, numeric, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_add_ingredient(p_target uuid, p_qty numeric, p_unit uuid, p_cut uuid DEFAULT NULL::uuid) RETURNS TABLE(parent_item_id uuid, parent_name text, already_has boolean, is_cycle boolean, coste_actual numeric, coste_nuevo numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_acc uuid; v_tcost numeric; v_added_base numeric; v_added_cost numeric;
BEGIN
  SELECT account_id, COALESCE(computed_cost, fixed_cost, 0)
    INTO v_acc, v_tcost FROM recipe_item WHERE id = p_target;
  IF v_acc IS NULL OR NOT (v_acc = ANY (current_user_account_ids())) THEN
    RAISE EXCEPTION 'preview_add_ingredient: ingrediente no accesible';
  END IF;
  v_added_base := public._qty_in_base(p_target, p_qty, p_unit);
  v_added_cost := CASE WHEN v_added_base IS NULL THEN NULL ELSE v_added_base * v_tcost END;

  RETURN QUERY
  WITH RECURSIVE desc_target AS (
    SELECT p_target AS item_id
    UNION
    SELECT rl.child_item_id FROM recipe_line rl
    JOIN desc_target d ON rl.parent_item_id = d.item_id
  )
  SELECT ri.id, ri.name,
    EXISTS (SELECT 1 FROM recipe_line t WHERE t.parent_item_id = ri.id AND t.child_item_id = p_target),
    (ri.id IN (SELECT item_id FROM desc_target)),
    ri.computed_cost,
    CASE WHEN ri.id IN (SELECT item_id FROM desc_target) OR v_added_cost IS NULL OR ri.computed_cost IS NULL
         THEN NULL ELSE ri.computed_cost + v_added_cost END
  FROM recipe_item ri
  WHERE ri.account_id = v_acc AND ri.type IN ('dish','recipe') AND ri.id <> p_target
  ORDER BY ri.name;
END;
$$;


--
-- Name: preview_bogo_mirror_price(uuid, uuid, uuid, numeric, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_bogo_mirror_price(p_account_id uuid, p_channel_id uuid, p_brand_id uuid, p_margin_floor_pct numeric DEFAULT 45, p_menu_item_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(menu_item_id uuid, item_name text, brand_name text, pvp_cliente numeric, food_cost numeric, precio_paridad numeric, precio_min_suelo numeric, precio_sugerido numeric, margen_2x1 numeric, margen_pct_2x1 numeric, ahorro_cliente_pct numeric, units_30d numeric, status text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with rate as (
    select cr.commission_pct, cr.commission_base
    from channel_rate cr
    where cr.account_id = p_account_id
      and cr.sales_channel_id = p_channel_id
      and cr.is_active
    order by cr.commission_pct asc
    limit 1
  ),
  items as (
    select m.id, m.name, b.name as brand_name,
           coalesce(o.price, m.price) as pvp_gross,
           coalesce(m.vat_rate, 10) as vat,
           ri.computed_cost as food_cost
    from menu_item m
    join brand b on b.id = m.brand_id
    left join menu_item_override o
      on o.menu_item_id = m.id and o.channel_id = p_channel_id and o.price is not null
    left join recipe_item ri on ri.id = m.recipe_item_id
    where m.account_id = p_account_id
      and m.archived_at is null
      and m.brand_id = p_brand_id
      and (p_menu_item_ids is null or m.id = any(p_menu_item_ids))
  ),
  sold as (
    select sl.menu_item_id, sum(sl.quantity) as units
    from sale_line sl
    join sale s on s.id = sl.sale_id
    where s.account_id = p_account_id
      and s.brand_id = p_brand_id
      and s.created_at >= now() - interval '30 days'
    group by sl.menu_item_id
  ),
  calc as (
    select i.*,
      i.pvp_gross as pvp_cli,
      case when r.commission_base = 'pvp_sin_iva'
        then r.commission_pct/100.0
        else r.commission_pct/100.0 * (1 + i.vat/100) end as k
    from items i cross join rate r
  ),
  calc2 as (
    select c.*,
      c.pvp_gross / (1 + c.vat/100) as n1,
      case when (1 - c.k) > 0
        then (c.pvp_gross / (1 + c.vat/100)) + c.food_cost / (1 - c.k)
        else null end as n_paridad,
      case when (1 - c.k - p_margin_floor_pct/100.0) > 0
        then (2 * c.food_cost) / (1 - c.k - p_margin_floor_pct/100.0)
        else null end as n_suelo
    from calc c
  ),
  calc3 as (
    select c.*,
      round(c.n_paridad * (1 + c.vat/100), 2) as p_paridad,
      round(c.n_suelo   * (1 + c.vat/100), 2) as p_suelo,
      ceil(greatest(c.n_suelo, c.n1) * (1 + c.vat/100) * 10) / 10.0 as p_sug
    from calc2 c
  ),
  calc4 as (
    select c.*,
      c.p_sug / (1 + c.vat/100) as n_sug,
      round((c.p_sug / (1 + c.vat/100)) * (1 - c.k) - 2 * c.food_cost, 2) as margen_2x1_eur
    from calc3 c
  )
  select
    c.id, c.name, c.brand_name,
    c.pvp_cli,
    round(c.food_cost, 2),
    c.p_paridad, c.p_suelo, c.p_sug,
    c.margen_2x1_eur,
    round(100 * c.margen_2x1_eur / nullif(c.n_sug, 0), 1) as margen_pct_2x1,
    round(100 * (1 - c.p_sug / nullif(2 * c.pvp_cli, 0)), 1) as ahorro_cliente_pct,
    coalesce(so.units, 0),
    case
      when c.food_cost is null then 'sin_escandallo'
      when c.p_sug is null or c.p_sug >= 2 * c.pvp_cli then 'inviable'
      else 'ok'
    end as status
  from calc4 c
  left join sold so on so.menu_item_id = c.id
  order by coalesce(so.units, 0) desc;
$$;


--
-- Name: preview_coupon_impact(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_coupon_impact(p_account uuid, p_discount_type text, p_value numeric) RETURNS TABLE(sellable_items integer, costed_items integer, uncosted_items integer, floor_pct numeric, avg_order numeric, effective_pct numeric, avg_margin_now_pct numeric, avg_margin_after_pct numeric, min_margin_after_pct numeric, items_below_floor_after integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_floor     numeric;
  v_avg_order numeric;
  v_f         numeric;  -- fracción efectiva de descuento (0..1)
begin
  if not (p_account = any(current_user_account_ids())) then
    raise exception 'forbidden';
  end if;

  select shop_coupon_margin_floor_pct into v_floor from accounts where id = p_account;

  -- Pedido medio real del Shop; si no hay pedidos aún, aprox = precio medio de
  -- platos costeados × 3 (un ticket típico de tres artículos).
  select avg(total) into v_avg_order
  from sale
  where account_id = p_account and source = 'folvy_shop'
    and coalesce(status,'') <> 'cancelled' and total is not null;

  if v_avg_order is null or v_avg_order <= 0 then
    select avg(mi.price) * 3 into v_avg_order
    from menu_item mi join recipe_item ri on ri.id = mi.recipe_item_id
    where mi.account_id = p_account and coalesce(mi.is_active,true) and mi.archived_at is null
      and mi.price > 0 and ri.computed_cost is not null;
  end if;

  if p_discount_type = 'percent' then
    v_f := greatest(0, least(1, coalesce(p_value,0) / 100.0));
  elsif p_discount_type = 'fixed' and v_avg_order is not null and v_avg_order > 0 then
    v_f := greatest(0, least(1, coalesce(p_value,0) / v_avg_order));
  else
    v_f := null;  -- fijo sin pedido medio: no estimable
  end if;

  return query
  with items as (
    select mi.price::numeric as price,
           (coalesce(ri.computed_cost,0) + coalesce(mi.packaging_cost,0))::numeric as cost,
           (mi.recipe_item_id is not null and ri.computed_cost is not null) as costed
    from menu_item mi
    left join recipe_item ri on ri.id = mi.recipe_item_id
    where mi.account_id = p_account
      and coalesce(mi.is_active,true) and mi.archived_at is null
  ),
  costed as (
    select price, cost,
           (price - cost)/nullif(price,0) as m_now,
           case when v_f is null then null
                else (price*(1-v_f) - cost)/nullif(price*(1-v_f),0) end as m_after
    from items where costed and price > 0
  )
  select
    (select count(*)::int from items),
    (select count(*)::int from items where costed),
    (select count(*)::int from items where not costed),
    v_floor,
    round(v_avg_order,2),
    case when v_f is null then null else round(v_f*100,1) end,
    round((select avg(m_now)   from costed)*100, 1),
    case when v_f is null then null else round((select avg(m_after) from costed)*100, 1) end,
    case when v_f is null then null else round((select min(m_after) from costed)*100, 1) end,
    case when v_f is null or v_floor is null then null
         else (select count(*) from costed where m_after*100 < v_floor)::int end;
end;
$$;


--
-- Name: preview_modifier_impact_cost(uuid, text, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_modifier_impact_cost(p_recipe_item_id uuid, p_impact_type text, p_target_recipe_item_id uuid, p_quantity numeric, p_unit_id uuid) RETURNS TABLE(base_cost numeric, delta numeric, total_cost numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_base       numeric;
  v_delta      numeric := 0;
BEGIN
  SELECT account_id, COALESCE(computed_cost, fixed_cost)
    INTO v_account_id, v_base
  FROM recipe_item
  WHERE id = p_recipe_item_id;

  IF v_account_id IS NULL THEN
    RETURN QUERY SELECT NULL::numeric, NULL::numeric, NULL::numeric;
    RETURN;
  END IF;

  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(v_account_id)) THEN
    RAISE EXCEPTION 'preview_modifier_impact_cost: sin acceso a la cuenta %', v_account_id;
  END IF;

  -- Si el plato no tiene coste base, el preview tampoco lo tiene (honesto).
  IF v_base IS NULL THEN
    RETURN QUERY SELECT NULL::numeric, NULL::numeric, NULL::numeric;
    RETURN;
  END IF;

  -- Delta según el tipo de impacto, con la MISMA lógica que compute_sale_line_cost.
  IF p_impact_type IN ('add_item', 'bundle', 'replace_item') THEN
    v_delta := public._impact_cost(p_target_recipe_item_id, p_quantity, p_unit_id);
  ELSIF p_impact_type = 'remove_item' THEN
    v_delta := -public._impact_cost(p_target_recipe_item_id, p_quantity, p_unit_id);
  ELSIF p_impact_type = 'multiply' THEN
    v_delta := v_base * (COALESCE(p_quantity, 1) - 1);
  ELSE
    v_delta := 0;  -- none
  END IF;

  RETURN QUERY SELECT v_base, v_delta, ROUND(v_base + v_delta, 6);
END;
$$;


--
-- Name: preview_platform_promo_impact(uuid, uuid, uuid[], text, numeric, uuid[], numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_platform_promo_impact(p_account_id uuid, p_channel_id uuid, p_brand_ids uuid[], p_discount_type text, p_discount_value numeric, p_menu_item_ids uuid[] DEFAULT NULL::uuid[], p_margin_floor_pct numeric DEFAULT NULL::numeric) RETURNS TABLE(menu_item_id uuid, item_name text, brand_name text, pvp_cliente numeric, pvp_promo_cliente numeric, descuento numeric, comision_antes numeric, comision_despues numeric, food_cost numeric, margen_antes numeric, margen_despues numeric, margen_pct_antes numeric, margen_pct_despues numeric, units_30d numeric, status text)
    LANGUAGE sql STABLE
    AS $$
  with rate as (
    select cr.commission_pct, cr.commission_base
    from channel_rate cr
    where cr.account_id = p_account_id
      and cr.sales_channel_id = p_channel_id
      and cr.is_active
    order by cr.updated_at desc
    limit 1
  ),
  items as (
    select m.id, m.name, b.name as brand_name,
           -- ANTES se llamaba price_sin_iva. menu_item.price lleva el IVA incluido.
           coalesce(o.price, m.price) as pvp_bruto,
           coalesce(m.vat_rate, 10) as vat,
           ri.computed_cost as food_cost
    from menu_item m
    join brand b on b.id = m.brand_id
    left join menu_item_override o
      on o.menu_item_id = m.id and o.channel_id = p_channel_id and o.price is not null
    left join recipe_item ri on ri.id = m.recipe_item_id
    where m.account_id = p_account_id
      and m.archived_at is null
      and m.brand_id = any(p_brand_ids)
      and (p_menu_item_ids is null or m.id = any(p_menu_item_ids))
  ),
  sold as (
    select sl.menu_item_id, sum(sl.quantity) as units
    from sale_line sl
    join sale s on s.id = sl.sale_id
    where s.account_id = p_account_id
      and s.brand_id = any(p_brand_ids)
      and s.created_at >= now() - interval '30 days'
    group by sl.menu_item_id
  ),
  calc as (
    select i.*,
      -- ANTES: round(i.price_sin_iva * (1 + i.vat/100), 2)
      i.pvp_bruto as pvp_cli,
      r.commission_pct, r.commission_base
    from items i cross join rate r
  ),
  calc2 as (
    select c.*,
      least(c.pvp_cli, case when p_discount_type = 'percent'
        then round(c.pvp_cli * p_discount_value / 100, 2)
        else p_discount_value end) as desc_cli
    from calc c
  ),
  calc3 as (
    select c.*,
      (c.pvp_cli - c.desc_cli) as pvp_promo,
      case when c.commission_base = 'pvp_sin_iva'
        then c.pvp_cli / (1 + c.vat/100) else c.pvp_cli end as base_com_antes,
      case when c.commission_base = 'pvp_sin_iva'
        then (c.pvp_cli - c.desc_cli) / (1 + c.vat/100)
        else (c.pvp_cli - c.desc_cli) end as base_com_despues
    from calc2 c
  ),
  calc4 as (
    select c.*,
      round(c.base_com_antes  * c.commission_pct/100, 4) as com_antes,
      round(c.base_com_despues * c.commission_pct/100, 4) as com_despues,
      round(c.pvp_cli   / (1 + c.vat/100), 4) as ingreso_neto_antes,
      round(c.pvp_promo / (1 + c.vat/100), 4) as ingreso_neto_despues
    from calc3 c
  )
  select
    c.id, c.name, c.brand_name,
    c.pvp_cli, c.pvp_promo, c.desc_cli,
    round(c.com_antes, 2), round(c.com_despues, 2),
    round(c.food_cost, 2),
    round(c.ingreso_neto_antes  - c.com_antes  - coalesce(c.food_cost,0), 2) as margen_antes,
    round(c.ingreso_neto_despues - c.com_despues - coalesce(c.food_cost,0), 2) as margen_despues,
    round(100 * (c.ingreso_neto_antes  - c.com_antes  - coalesce(c.food_cost,0))
      / nullif(c.ingreso_neto_antes, 0), 1),
    round(100 * (c.ingreso_neto_despues - c.com_despues - coalesce(c.food_cost,0))
      / nullif(c.ingreso_neto_despues, 0), 1),
    coalesce(so.units, 0),
    case
      when c.food_cost is null then 'sin_escandallo'
      when p_margin_floor_pct is not null
        and 100 * (c.ingreso_neto_despues - c.com_despues - c.food_cost)
            / nullif(c.ingreso_neto_despues, 0) < p_margin_floor_pct then 'bajo_suelo'
      else 'ok'
    end
  from calc4 c
  left join sold so on so.menu_item_id = c.id
  order by coalesce(so.units, 0) desc;
$$;


--
-- Name: FUNCTION preview_platform_promo_impact(p_account_id uuid, p_channel_id uuid, p_brand_ids uuid[], p_discount_type text, p_discount_value numeric, p_menu_item_ids uuid[], p_margin_floor_pct numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.preview_platform_promo_impact(p_account_id uuid, p_channel_id uuid, p_brand_ids uuid[], p_discount_type text, p_discount_value numeric, p_menu_item_ids uuid[], p_margin_floor_pct numeric) IS 'Prevision de impacto de promo de plataforma. menu_item.price es PRECIO CON IVA INCLUIDO (17/08): pvp_cli = coalesce(override, price) sin multiplicar. Toda la cadena de abajo ya dividia correctamente. price_sin_iva renombrada a pvp_bruto porque el nombre afirmaba la interpretacion equivocada.';


--
-- Name: preview_remove_ingredient(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_remove_ingredient(p_source uuid) RETURNS TABLE(parent_item_id uuid, parent_name text, n_lines integer, first_qty numeric, first_unit_id uuid, coste_actual numeric, coste_nuevo numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_acc uuid; v_scost numeric;
BEGIN
  SELECT account_id, COALESCE(computed_cost, fixed_cost, 0)
    INTO v_acc, v_scost FROM recipe_item WHERE id = p_source;
  IF v_acc IS NULL OR NOT (v_acc = ANY (current_user_account_ids())) THEN
    RAISE EXCEPTION 'preview_remove_ingredient: origen no accesible';
  END IF;

  RETURN QUERY
  WITH src_lines AS (
    SELECT rl.parent_item_id, rl.position,
           COALESCE(rl.quantity_gross, rl.quantity_net) AS qty, rl.unit_id,
           public._qty_in_base(p_source, COALESCE(rl.quantity_gross, rl.quantity_net), rl.unit_id) AS src_base
    FROM recipe_line rl
    WHERE rl.child_item_id = p_source AND rl.account_id = v_acc
  ),
  per_dish AS (
    SELECT s.parent_item_id,
      count(*)::int AS n_lines,
      (array_agg(s.qty ORDER BY s.position NULLS LAST))[1] AS first_qty,
      (array_agg(s.unit_id ORDER BY s.position NULLS LAST))[1] AS first_unit_id,
      sum(COALESCE(s.src_base,0)) * v_scost AS quitado
    FROM src_lines s GROUP BY s.parent_item_id
  )
  SELECT d.parent_item_id, ri.name, d.n_lines, d.first_qty, d.first_unit_id,
         ri.computed_cost,
         CASE WHEN ri.computed_cost IS NULL THEN NULL
              ELSE GREATEST(ri.computed_cost - d.quitado, 0) END
  FROM per_dish d JOIN recipe_item ri ON ri.id = d.parent_item_id
  ORDER BY ri.name;
END;
$$;


--
-- Name: preview_scope_bulk_by_token(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_scope_bulk_by_token(p_device_token text, p_menu_item_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device; v_matriculas text[]; v_brand_ids uuid[]; v_brands int; v_core jsonb;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'preview_scope_bulk_by_token: token no valido'; end if;
  if p_menu_item_ids is null or array_length(p_menu_item_ids, 1) is null then
    raise exception 'preview_scope_bulk_by_token: la seleccion esta vacia';
  end if;

  with sib as (
    select mi.id, mi.brand_id, mi.external_id from menu_item mi
    where mi.account_id = v_device.account_id
      and ( mi.id = any(p_menu_item_ids)
        or mi.recipe_item_id in (select recipe_item_id from menu_item
             where id = any(p_menu_item_ids) and account_id = v_device.account_id and recipe_item_id is not null)
        or mi.stock_group_id in (select stock_group_id from menu_item
             where id = any(p_menu_item_ids) and account_id = v_device.account_id and stock_group_id is not null) )
  )
  select array_agg(distinct external_id) filter (where external_id is not null),
         array_agg(distinct brand_id) filter (where brand_id is not null),
         count(distinct brand_id)
    into v_matriculas, v_brand_ids, v_brands from sib;

  v_core := public._scope_preview_core(v_device.account_id, v_matriculas, v_brand_ids, v_device.location_id);

  return jsonb_build_object('brands', coalesce(v_brands, 0),
    'channels', coalesce((v_core->>'channelsLast')::int, 0),
    'channelsLast', (v_core->>'channelsLast')::int,
    'brandsHubrise', (v_core->>'brandsHubrise')::int);
end;
$$;


--
-- Name: preview_scope_by_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_scope_by_token(p_device_token text, p_menu_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device; v_recipe_item uuid; v_external_id text; v_stock_group uuid;
  v_matriculas text[]; v_brand_ids uuid[]; v_brands int; v_core jsonb;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'preview_scope_by_token: token no valido'; end if;

  select mi.recipe_item_id, mi.external_id, mi.stock_group_id
    into v_recipe_item, v_external_id, v_stock_group
  from menu_item mi where mi.id = p_menu_item_id and mi.account_id = v_device.account_id;

  with sib as (
    select mi.id, mi.brand_id, mi.external_id from menu_item mi
    where mi.account_id = v_device.account_id
      and ( mi.id = p_menu_item_id
        or (v_recipe_item is not null and mi.recipe_item_id = v_recipe_item)
        or (v_stock_group is not null and mi.stock_group_id = v_stock_group) )
  )
  select array_agg(distinct external_id) filter (where external_id is not null),
         array_agg(distinct brand_id) filter (where brand_id is not null),
         count(distinct brand_id)
    into v_matriculas, v_brand_ids, v_brands from sib;

  v_core := public._scope_preview_core(v_device.account_id, v_matriculas, v_brand_ids, v_device.location_id);

  return jsonb_build_object('brands', coalesce(v_brands, 0),
    'channels', coalesce((v_core->>'channelsLast')::int, 0),
    'channelsLast', (v_core->>'channelsLast')::int,
    'brandsHubrise', (v_core->>'brandsHubrise')::int);
end;
$$;


--
-- Name: preview_substitute_ingredient(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_substitute_ingredient(p_source uuid, p_target uuid) RETURNS TABLE(parent_item_id uuid, parent_name text, estado text, n_lines integer, first_qty numeric, first_unit_id uuid, coste_actual numeric, coste_nuevo numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_acc uuid; v_scost numeric; v_tcost numeric;
BEGIN
  SELECT account_id, COALESCE(computed_cost, fixed_cost, 0)
    INTO v_acc, v_scost FROM recipe_item WHERE id = p_source;
  IF v_acc IS NULL OR NOT (v_acc = ANY (current_user_account_ids())) THEN
    RAISE EXCEPTION 'preview_substitute_ingredient: origen no accesible';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM recipe_item WHERE id = p_target AND account_id = v_acc) THEN
    RAISE EXCEPTION 'preview_substitute_ingredient: destino no existe en la misma cuenta';
  END IF;
  SELECT COALESCE(computed_cost, fixed_cost, 0) INTO v_tcost
    FROM recipe_item WHERE id = p_target;

  RETURN QUERY
  WITH RECURSIVE desc_target AS (
    SELECT p_target AS item_id
    UNION
    SELECT rl.child_item_id FROM recipe_line rl
    JOIN desc_target d ON rl.parent_item_id = d.item_id
  ),
  src_lines AS (
    SELECT rl.parent_item_id, rl.position,
           COALESCE(rl.quantity_gross, rl.quantity_net) AS qty,
           rl.unit_id,
           public._qty_in_base(p_source, COALESCE(rl.quantity_gross, rl.quantity_net), rl.unit_id) AS src_base,
           public._qty_in_base(p_target, COALESCE(rl.quantity_gross, rl.quantity_net), rl.unit_id) AS tgt_base,
           EXISTS (SELECT 1 FROM recipe_line t WHERE t.parent_item_id = rl.parent_item_id
                     AND t.child_item_id = p_target AND t.unit_id = rl.unit_id
                     AND t.cut_type_id IS NOT DISTINCT FROM rl.cut_type_id) AS fusable,
           EXISTS (SELECT 1 FROM recipe_line t WHERE t.parent_item_id = rl.parent_item_id
                     AND t.child_item_id = p_target) AS has_target
    FROM recipe_line rl
    WHERE rl.child_item_id = p_source AND rl.account_id = v_acc
  ),
  per_dish AS (
    SELECT s.parent_item_id,
      bool_or(s.parent_item_id IN (SELECT item_id FROM desc_target)) AS is_cycle,
      bool_or(s.fusable) AS any_fusion,
      bool_or(s.has_target AND NOT s.fusable) AS any_dup,
      bool_or(s.tgt_base IS NULL) AS any_unconv,
      count(*)::int AS n_lines,
      (array_agg(s.qty ORDER BY s.position NULLS LAST))[1] AS first_qty,
      (array_agg(s.unit_id ORDER BY s.position NULLS LAST))[1] AS first_unit_id,
      sum(COALESCE(s.src_base,0)) * v_scost AS old_cost,
      CASE WHEN bool_or(s.tgt_base IS NULL) THEN NULL
           ELSE sum(COALESCE(s.tgt_base,0)) * v_tcost END AS new_cost
    FROM src_lines s
    GROUP BY s.parent_item_id
  )
  SELECT
    d.parent_item_id, ri.name,
    CASE WHEN d.is_cycle THEN 'ciclo'
         WHEN d.any_dup THEN 'revisar'
         WHEN d.any_fusion THEN 'fusion'
         ELSE 'limpio' END,
    d.n_lines, d.first_qty, d.first_unit_id,
    ri.computed_cost,
    CASE WHEN d.is_cycle OR d.new_cost IS NULL OR ri.computed_cost IS NULL THEN NULL
         ELSE ri.computed_cost - d.old_cost + d.new_cost END
  FROM per_dish d
  JOIN recipe_item ri ON ri.id = d.parent_item_id
  ORDER BY ri.name;
END;
$$;


--
-- Name: preview_supplier_migration(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_supplier_migration(p_source uuid, p_target uuid) RETURNS TABLE(origen_total integer, colisiones integer, migran_limpio integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_acc uuid;
BEGIN
  SELECT s1.account_id INTO v_acc
  FROM supplier s1 JOIN supplier s2 ON s2.id = p_target
  WHERE s1.id = p_source AND s1.account_id = s2.account_id;
  IF v_acc IS NULL THEN RAISE EXCEPTION 'Proveedores inválidos o de cuentas distintas'; END IF;
  IF NOT (v_acc = ANY (current_user_account_ids())) THEN RAISE EXCEPTION 'Sin permiso sobre esta cuenta'; END IF;
  RETURN QUERY
  WITH origen AS (SELECT recipe_item_id, supplier_code FROM article_supplier WHERE supplier_id = p_source),
       destino AS (SELECT recipe_item_id, supplier_code FROM article_supplier WHERE supplier_id = p_target)
  SELECT (SELECT count(*) FROM origen)::int,
         (SELECT count(*) FROM origen o WHERE EXISTS (
            SELECT 1 FROM destino d WHERE d.recipe_item_id = o.recipe_item_id
              AND d.supplier_code IS NOT DISTINCT FROM o.supplier_code))::int,
         (SELECT count(*) FROM origen o WHERE NOT EXISTS (
            SELECT 1 FROM destino d WHERE d.recipe_item_id = o.recipe_item_id
              AND d.supplier_code IS NOT DISTINCT FROM o.supplier_code))::int;
END; $$;


--
-- Name: price_drift_for(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_drift_for(p_account_id uuid, p_item_id uuid, p_window_months integer DEFAULT 6) RETURNS TABLE(actual_eur_base numeric, median_eur_base numeric, n_recepciones integer, pct_vs_median numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH recs AS (
    SELECT sm.unit_cost, sm.occurred_at
    FROM stock_movement sm
    -- Solo recepciones de albaranes que NO están anulados. El movimiento de
    -- recepción siempre tiene source goods_receipt_line → su goods_receipt.
    JOIN goods_receipt_line grl ON grl.id = sm.source_id AND sm.source_type = 'goods_receipt_line'
    JOIN goods_receipt gr       ON gr.id = grl.goods_receipt_id
    WHERE sm.account_id = p_account_id
      AND sm.recipe_item_id = p_item_id
      AND sm.movement_type = 'recepcion'
      AND sm.unit_cost IS NOT NULL
      AND sm.unit_cost > 0
      AND gr.status = 'confirmado'            -- ignora anulados
      AND sm.occurred_at >= now() - make_interval(months => p_window_months)
  ),
  agg AS (
    SELECT
      (SELECT unit_cost FROM recs ORDER BY occurred_at DESC LIMIT 1)                       AS actual,
      percentile_cont(0.5) WITHIN GROUP (ORDER BY unit_cost)::numeric                       AS mediana,
      count(*)                                                                              AS n
    FROM recs
  )
  SELECT
    agg.actual,
    agg.mediana,
    agg.n::integer,
    CASE WHEN agg.mediana > 0
         THEN round(((agg.actual - agg.mediana) / agg.mediana) * 100, 1)
         ELSE NULL END
  FROM agg
  WHERE agg.n > 0;
$$;


--
-- Name: propose_ai_action(uuid, text, text, text, jsonb, text, jsonb, jsonb, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_ai_action(p_account_id uuid, p_agent text, p_tool_name text, p_summary text, p_args jsonb, p_risk text DEFAULT 'L1'::text, p_effect_preview jsonb DEFAULT NULL::jsonb, p_rollback_hint jsonb DEFAULT NULL::jsonb, p_target_table text DEFAULT NULL::text, p_target_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not current_user_is_admin_of(p_account_id) then
    raise exception 'No autorizado para proponer acciones en esta cuenta';
  end if;

  -- Guardarraíl de fiabilidad: L1/L2 exigen plan de reversión.
  if p_risk in ('L1','L2') and p_rollback_hint is null then
    raise exception 'Las acciones L1/L2 requieren rollback_hint (plan de reversión)';
  end if;

  insert into ai_action(
    account_id, agent, tool_name, risk, status, summary,
    target_table, target_id, args, effect_preview, rollback_hint,
    proposed_by, session_id
  ) values (
    p_account_id, p_agent, p_tool_name, p_risk, 'proposed', p_summary,
    p_target_table, p_target_id, coalesce(p_args, '{}'::jsonb), p_effect_preview, p_rollback_hint,
    auth.uid(), p_session_id
  )
  returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: propose_schedule(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_schedule(p_account uuid, p_location uuid, p_week_start date) RETURNS TABLE(dia date, day_of_week integer, shift_template_id uuid, shift_label text, employee_id uuid, employee_name text, motivo text, rompe_preferencia boolean, es_hueco boolean, motivo_hueco text)
    LANGUAGE plpgsql STABLE
    AS $$
declare
  r_turno record; r_cand record;
  v_asignadas jsonb := '{}'::jsonb;
  v_horas     jsonb := '{}'::jsonb;
  v_turnos    jsonb := '{}'::jsonb;
  v_fin       jsonb := '{}'::jsonb;
  v_dur numeric; v_ini timestamp; v_fin_t timestamp;
  v_i integer; v_encontrado boolean;
  v_bloq_desc int; v_bloq_12h int; v_bloq_horas int;
  v_bloq_vac int; v_ocupados int; v_plantilla int;
  v_rest_min int; v_rest_12h int; v_margen int;
  v_refuerzo text;
begin
  v_rest_min := public.weekly_rest_minutes_for(p_account, p_location);
  v_margen   := public.rest_safety_margin_for(p_account, p_location);
  v_rest_12h := coalesce((select bp.min_rest_between_shifts_minutes from public.break_policy bp
                          where bp.account_id = p_account
                            and (bp.location_id = p_location or bp.location_id is null)
                          order by bp.location_id nulls last limit 1), 720);

  -- Quien ha cubierto en este local sin pertenecer a el (solo INFORMATIVO)
  select string_agg(x.name || ' (' || x.n || ' fichajes)', ', ' order by x.n desc)
    into v_refuerzo
  from (
    select e.name, count(*) as n
    from public.employees e
    join public.clock_entries ce on ce.employee_id = e.id
    where e.account_id = p_account and e.active
      and e.location_id is distinct from p_location
      and not (e.assigned_locations is not null
               and to_jsonb(e.assigned_locations) @> to_jsonb(p_location::text))
      and ce.location_id_at_clock = p_location
      and not coalesce(ce.voided,false)
      and ce.real_datetime > now() - interval '90 days'
    group by e.name having count(*) >= 5
  ) x;

  for r_turno in
    select st.id as tpl, st.label, st.start_time, st.end_time,
           d.dow, (p_week_start + d.dow)::date as fecha,
           case when st.start_time < time '17:00' then 'morning' else 'evening' end as periodo,
           coalesce(case d.dow
             when 0 then st.coverage_mon when 1 then st.coverage_tue when 2 then st.coverage_wed
             when 3 then st.coverage_thu when 4 then st.coverage_fri when 5 then st.coverage_sat
             else st.coverage_sun end, 0) as necesita
    from public.shift_templates st
    cross join generate_series(0,6) d(dow)
    where st.location_id = p_location and st.account_id = p_account and st.active
      and coalesce(case d.dow
             when 0 then st.coverage_mon when 1 then st.coverage_tue when 2 then st.coverage_wed
             when 3 then st.coverage_thu when 4 then st.coverage_fri when 5 then st.coverage_sat
             else st.coverage_sun end, 0) > 0
    order by d.dow, st.start_time
  loop
    v_dur := extract(epoch from (
               (r_turno.end_time - r_turno.start_time)
               + case when r_turno.end_time <= r_turno.start_time
                      then interval '24 hours' else interval '0' end)) / 3600.0;
    v_ini   := (r_turno.fecha + r_turno.start_time)::timestamp;
    v_fin_t := v_ini + make_interval(secs => v_dur * 3600);

    for v_i in 1 .. r_turno.necesita loop
      v_encontrado := false;

      select count(*),
             count(*) filter (where en_vac),
             count(*) filter (where ya_hoy),
             count(*) filter (where not en_vac and not ya_hoy
                and not public.has_weekly_rest(turnos, v_ini, v_fin_t, p_week_start, v_rest_min)),
             count(*) filter (where not en_vac and not ya_hoy and fin_ant is not null
                and v_ini < (fin_ant + make_interval(mins => v_rest_12h))),
             count(*) filter (where not en_vac and not ya_hoy
                and horas_ya + v_dur > horas_contrato)
        into v_plantilla, v_bloq_vac, v_ocupados, v_bloq_desc, v_bloq_12h, v_bloq_horas
      from (
        select
          exists (select 1 from public.vacations v
                  where v.employee_id = e.id and v.status='aprobada'
                    and r_turno.fecha between v.start_date and v.end_date) as en_vac,
          (coalesce(v_asignadas -> (r_turno.fecha::text), '[]'::jsonb)
             @> to_jsonb(e.id::text)) as ya_hoy,
          coalesce(v_turnos -> e.id::text, '[]'::jsonb)  as turnos,
          coalesce((v_horas ->> e.id::text)::numeric, 0) as horas_ya,
          coalesce(e.contracted_hours_week, 40)          as horas_contrato,
          (v_fin ->> e.id::text)::timestamp              as fin_ant
        from public.employees e
        where e.account_id = p_account and e.active
          and (e.location_id = p_location
            or (e.assigned_locations is not null
                and to_jsonb(e.assigned_locations) @> to_jsonb(p_location::text)))
      ) q;

      for r_cand in
        select e.id, e.name,
               coalesce((v_horas ->> e.id::text)::numeric, 0) as horas_ya,
               coalesce(av.available, true) as disponible,
               av.note as motivo_disp,
               public.has_weekly_rest(
                 coalesce(v_turnos -> e.id::text, '[]'::jsonb),
                 v_ini, v_fin_t, p_week_start, v_rest_min + v_margen) as queda_holgado
        from public.employees e
        left join public.employee_availability av
          on av.employee_id = e.id and av.day_of_week = r_turno.dow
         and av.shift_period = r_turno.periodo
        where e.account_id = p_account and e.active
          -- SOLO plantilla del local (propia o autorizada explicitamente)
          and (e.location_id = p_location
            or (e.assigned_locations is not null
                and to_jsonb(e.assigned_locations) @> to_jsonb(p_location::text)))
          and not exists (select 1 from public.vacations v
                          where v.employee_id = e.id and v.status='aprobada'
                            and r_turno.fecha between v.start_date and v.end_date)
          and not (coalesce(v_asignadas -> (r_turno.fecha::text), '[]'::jsonb)
                   @> to_jsonb(e.id::text))
          and public.has_weekly_rest(
                coalesce(v_turnos -> e.id::text, '[]'::jsonb),
                v_ini, v_fin_t, p_week_start, v_rest_min)
          and ((v_fin ->> e.id::text) is null
               or v_ini >= ((v_fin ->> e.id::text)::timestamp
                            + make_interval(mins => v_rest_12h)))
          and coalesce((v_horas ->> e.id::text)::numeric, 0) + v_dur
              <= coalesce(e.contracted_hours_week, 40)
        order by coalesce(av.available, true) desc,
                 public.has_weekly_rest(
                   coalesce(v_turnos -> e.id::text, '[]'::jsonb),
                   v_ini, v_fin_t, p_week_start, v_rest_min + v_margen) desc,
                 coalesce((v_horas ->> e.id::text)::numeric, 0) asc,
                 e.name
        limit 1
      loop
        dia := r_turno.fecha; day_of_week := r_turno.dow;
        shift_template_id := r_turno.tpl; shift_label := r_turno.label;
        employee_id := r_cand.id; employee_name := r_cand.name;
        rompe_preferencia := not r_cand.disponible;
        es_hueco := false; motivo_hueco := null;
        motivo := case
          when not r_cand.disponible
            then 'AVISO: normalmente no trabaja esta franja ('
                 ||coalesce(r_cand.motivo_disp,'sin dato')||') pero hace falta para cubrir'
          when not r_cand.queda_holgado
            then 'Queda al limite de descanso semanal · '
                 ||round(r_cand.horas_ya + v_dur,1)||' h esta semana'
          else 'Disponible · '||round(r_cand.horas_ya + v_dur,1)||' h esta semana' end;

        v_asignadas := jsonb_set(v_asignadas, array[r_turno.fecha::text],
          coalesce(v_asignadas -> (r_turno.fecha::text), '[]'::jsonb) || to_jsonb(r_cand.id::text));
        v_horas  := jsonb_set(v_horas, array[r_cand.id::text], to_jsonb(r_cand.horas_ya + v_dur));
        v_turnos := jsonb_set(v_turnos, array[r_cand.id::text],
                      coalesce(v_turnos -> r_cand.id::text, '[]'::jsonb)
                      || jsonb_build_array(jsonb_build_array(
                           to_char(v_ini,'YYYY-MM-DD"T"HH24:MI:SS'),
                           to_char(v_fin_t,'YYYY-MM-DD"T"HH24:MI:SS'))));
        v_fin    := jsonb_set(v_fin, array[r_cand.id::text],
                      to_jsonb(to_char(v_fin_t,'YYYY-MM-DD"T"HH24:MI:SS')));
        v_encontrado := true;
        return next;
      end loop;

      if not v_encontrado then
        dia := r_turno.fecha; day_of_week := r_turno.dow;
        shift_template_id := r_turno.tpl; shift_label := r_turno.label;
        employee_id := null; employee_name := null;
        rompe_preferencia := false; es_hueco := true;
        motivo := 'SIN CUBRIR — nadie de la plantilla puede sin incumplir';
        motivo_hueco := nullif(concat_ws(' · ',
          case when v_ocupados   > 0 then 'ya tienen turno ese dia: '||v_ocupados end,
          case when v_bloq_desc  > 0 then 'perderian el descanso semanal de '
                                          ||round(v_rest_min/60.0)||' h: '||v_bloq_desc end,
          case when v_bloq_12h   > 0 then 'descanso de '||round(v_rest_12h/60.0)
                                          ||' h entre jornadas: '||v_bloq_12h end,
          case when v_bloq_horas > 0 then 'superarian su jornada contratada: '||v_bloq_horas end,
          case when v_bloq_vac   > 0 then 'vacaciones aprobadas: '||v_bloq_vac end,
          case when v_plantilla  = 0 then 'no hay personal asignado a este local' end
        ), '');
        motivo_hueco := coalesce(motivo_hueco,
          'plantilla insuficiente ('||v_plantilla||' personas para la cobertura pedida)');
        if v_refuerzo is not null then
          motivo_hueco := motivo_hueco
            || ' · Ha cubierto aqui antes: ' || v_refuerzo || ' (requiere autorizacion)';
        end if;
        return next;
      end if;
    end loop;
  end loop;
end $$;


--
-- Name: propose_schedule_rest(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_schedule_rest(p_account uuid, p_location uuid, p_week_start date) RETURNS TABLE(employee_id uuid, employee_name text, dias_trabajados integer, horas_semana numeric, descanso_desde timestamp without time zone, descanso_hasta timestamp without time zone, descanso_horas numeric, minimo_exigido_horas numeric, margen_horas numeric, estado text, cumple boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with cfg as (
    select public.weekly_rest_minutes_for(p_account,p_location) as m,
           public.rest_safety_margin_for(p_account,p_location)  as s
  ),
  t as (
    select ps.employee_id, ps.employee_name,
           (ps.dia + st.start_time)::timestamp as ini,
           (ps.dia + st.start_time)::timestamp
             + case when st.end_time <= st.start_time then interval '24h' else interval '0' end
             + (st.end_time - st.start_time) as fin
    from public.propose_schedule(p_account,p_location,p_week_start) ps
    join public.shift_templates st on st.id = ps.shift_template_id
    where not ps.es_hueco
  ),
  g as (
    select employee_id, employee_name, fin as desde,
           lead(ini) over (partition by employee_id order by ini) as hasta
    from t
    union all
    select employee_id, employee_name, p_week_start::timestamp, min(ini)
    from t group by employee_id, employee_name
    union all
    select employee_id, employee_name, max(fin), (p_week_start + 7)::timestamp
    from t group by employee_id, employee_name
  ),
  best as (
    select distinct on (employee_id) employee_id, employee_name, desde, hasta,
           extract(epoch from (hasta - desde))/3600.0 as h
    from g where hasta is not null
    order by employee_id, extract(epoch from (hasta - desde)) desc
  )
  select b.employee_id, b.employee_name,
         (select count(distinct ini::date) from t where t.employee_id=b.employee_id)::int,
         round((select sum(extract(epoch from (fin-ini))/3600.0)
                from t where t.employee_id=b.employee_id)::numeric,1),
         b.desde, b.hasta, round(b.h::numeric,1),
         round((select m from cfg)/60.0,1),
         round((b.h - (select m from cfg)/60.0)::numeric,1),
         case
           when b.h < (select m from cfg)/60.0 then 'incumple'
           when b.h < (select m + s from cfg)/60.0 then 'al_limite'
           else 'ok' end,
         b.h >= (select m from cfg)/60.0
  from best b order by b.h;
$$;


--
-- Name: propose_shift_blocks(uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_shift_blocks(p_account uuid, p_location uuid, p_week_start date, p_role text DEFAULT 'cocina'::text) RETURNS TABLE(o_fecha date, o_dow integer, o_role text, o_capa integer, o_ini integer, o_fin integer, o_horas numeric, o_demanda_media numeric, o_nota text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_max_h numeric; v_min_h numeric;
begin
  select coalesce(bp.max_daily_minutes,540)/60.0, coalesce(bp.min_shift_minutes,180)/60.0
    into v_max_h, v_min_h
  from public.break_policy bp
  where bp.account_id = p_account and (bp.location_id = p_location or bp.location_id is null)
  order by bp.location_id nulls last limit 1;
  v_max_h := coalesce(v_max_h, 9); v_min_h := coalesce(v_min_h, 3);

  return query
  with req as (
    select r.fecha as f, r.dow as d, r.hora as h, r.required as q
    from public.team_labor_requirement(p_account, p_location, p_week_start) r
    where r.role_kind = p_role and r.required > 0
  ),
  niveles as (
    select req.f, req.d, req.h, n.nivel
    from req cross join generate_series(1, 6) n(nivel)
    where req.q >= n.nivel
  ),
  grupos as (
    select f, d, nivel, h,
           h - row_number() over (partition by f, d, nivel order by h) as g
    from niveles
  ),
  bloques as (
    select f, d, nivel, min(h) as h_ini, max(h) + 1 as h_fin
    from grupos group by f, d, nivel, g
  ),
  ajustados as (
    select f, d, nivel, h_ini,
           case when (h_fin - h_ini) < v_min_h
                then least(24, h_ini + ceil(v_min_h)::int)
                else h_fin end as h_fin,
           case when (h_fin - h_ini) < v_min_h then 'ampliado al minimo de turno'
                when (h_fin - h_ini) > v_max_h then 'supera la jornada maxima'
                else null end as nota
    from bloques
  )
  select a.f, a.d, p_role, a.nivel,
         a.h_ini, a.h_fin, (a.h_fin - a.h_ini)::numeric,
         round((select avg(r.q) from req r
                 where r.f = a.f and r.h >= a.h_ini and r.h < a.h_fin)::numeric, 2),
         a.nota
  from ajustados a
  order by a.f, a.nivel, a.h_ini;
end $$;


--
-- Name: propose_vat_category(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_vat_category(p_recipe_item_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_current_cat    uuid;
  v_current_source text;
  v_family_name    text;
  v_proposed_cat   uuid;
BEGIN
  SELECT ri.vat_category_id, ri.vat_category_source, rf.name
    INTO v_current_cat, v_current_source, v_family_name
  FROM public.recipe_item ri
  LEFT JOIN public.recipe_family rf ON rf.id = ri.family_id
  WHERE ri.id = p_recipe_item_id;

  -- No tocar lo confirmado por un humano.
  IF v_current_source = 'confirmed' THEN
    RETURN v_current_cat;
  END IF;

  -- Sin familia no se puede proponer (honesto: queda sin IVA, no inventa).
  IF v_family_name IS NULL THEN
    RETURN v_current_cat;
  END IF;

  SELECT fvd.vat_category_id INTO v_proposed_cat
  FROM public.family_vat_default fvd
  WHERE fvd.family_name = v_family_name;

  IF v_proposed_cat IS NULL THEN
    RETURN v_current_cat;
  END IF;

  UPDATE public.recipe_item
     SET vat_category_id = v_proposed_cat,
         vat_category_source = 'proposed'
   WHERE id = p_recipe_item_id;

  RETURN v_proposed_cat;
END;
$$;


--
-- Name: protect_last_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_last_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_active_ceos integer;
BEGIN
  IF (TG_OP = 'DELETE') THEN
    SELECT COUNT(*) INTO v_active_ceos
    FROM platform_admins
    WHERE role = 'ceo' 
      AND active = true
      AND id != OLD.id;
    
    IF OLD.role = 'ceo' AND v_active_ceos = 0 THEN
      RAISE EXCEPTION 'No se puede borrar el último CEO platform_admin. Promociona otro admin primero.';
    END IF;
    
    RETURN OLD;
  END IF;
  
  IF (TG_OP = 'UPDATE') THEN
    IF OLD.role = 'ceo' AND OLD.active = true THEN
      SELECT COUNT(*) INTO v_active_ceos
      FROM platform_admins
      WHERE role = 'ceo' 
        AND active = true
        AND id != OLD.id;
      
      IF v_active_ceos = 0 AND (NEW.role != 'ceo' OR NEW.active = false) THEN
        RAISE EXCEPTION 'No se puede desactivar o cambiar role del último CEO platform_admin.';
      END IF;
    END IF;
    
    RETURN NEW;
  END IF;
  
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION protect_last_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.protect_last_admin() IS 'Protege contra borrar/desactivar/degradar al último CEO platform_admin activo. Previene self-lockout.';


--
-- Name: purchase_format_has_stock_movements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_format_has_stock_movements(p_format_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from goods_receipt_line grl
    join stock_movement sm on sm.source_type = 'goods_receipt_line' and sm.source_id = grl.id
    where grl.purchase_format_id = p_format_id
    limit 1
  );
$$;


--
-- Name: purchase_order_progress(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_progress(p_order_ids uuid[]) RETURNS TABLE(order_id uuid, lineas integer, completas integer, faltan integer, dias_de_retraso integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with recv as (
    select gr.purchase_order_id as po_id, grl.purchase_order_line_id as pol_id,
           sum(grl.qty_received) as qty_recv
      from goods_receipt_line grl
      join goods_receipt gr on gr.id = grl.goods_receipt_id
     where gr.purchase_order_id = any(p_order_ids)
       and gr.status = 'confirmado'
       and grl.purchase_order_line_id is not null
     group by 1,2
  )
  select po.id,
         count(pol.id)::integer,
         count(pol.id) filter (where coalesce(r.qty_recv,0) >= pol.qty_ordered)::integer,
         count(pol.id) filter (where coalesce(r.qty_recv,0) < pol.qty_ordered)::integer,
         case when po.expected_date is null then null
              else greatest((current_date - po.expected_date)::integer, 0) end
    from purchase_order po
    left join purchase_order_line pol on pol.purchase_order_id = po.id
    left join recv r on r.pol_id = pol.id
   where po.id = any(p_order_ids)
     and public.belongs_to_account(po.account_id)
   group by po.id, po.expected_date;
$$;


--
-- Name: purchase_order_shortfall(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_shortfall(p_order_id uuid) RETURNS TABLE(line_id uuid, product_name text, recipe_item_id uuid, format_name text, qty_ordered numeric, qty_received numeric, qty_missing numeric, line_position integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with recv as (
    select grl.purchase_order_line_id as pol_id, sum(grl.qty_received) as qty_recv
      from goods_receipt_line grl
      join goods_receipt gr on gr.id = grl.goods_receipt_id
     where gr.purchase_order_id = p_order_id
       and gr.status = 'confirmado'
       and grl.purchase_order_line_id is not null
     group by 1
  )
  select pol.id,
         coalesce(ri.name, pol.product_name),
         pol.recipe_item_id,
         f.name,
         pol.qty_ordered,
         coalesce(r.qty_recv, 0),
         greatest(pol.qty_ordered - coalesce(r.qty_recv, 0), 0),
         pol.position
    from purchase_order_line pol
    join purchase_order po on po.id = pol.purchase_order_id
    left join recv r on r.pol_id = pol.id
    left join recipe_item ri on ri.id = pol.recipe_item_id
    left join recipe_item_purchase_format f on f.id = pol.purchase_format_id
   where pol.purchase_order_id = p_order_id
     and public.belongs_to_account(po.account_id)
   -- LO QUE FALTA, PRIMERO. Hoy el orden alfabético entierra las cuatro que
   -- importan entre las veintisiete que no.
   order by (coalesce(r.qty_recv,0) >= pol.qty_ordered), pol.position;
$$;


--
-- Name: purchase_orders_stuck(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_orders_stuck(p_days integer DEFAULT 3) RETURNS TABLE(order_id uuid, order_code text, estado text, supplier_name text, location_name text, expected_date date, dias_de_retraso integer, lineas_pedido integer, lineas_completas integer, lineas_sin_recibir integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with recv as (
    select grl.purchase_order_line_id as pol_id, sum(grl.qty_received) as qty_recv
      from goods_receipt_line grl
      join goods_receipt gr on gr.id = grl.goods_receipt_id
     where gr.status = 'confirmado' and grl.purchase_order_line_id is not null
     group by 1
  ),
  por_pedido as (
    select pol.purchase_order_id as po_id,
           count(*)::integer as n_lineas,
           count(*) filter (where coalesce(r.qty_recv,0) >= pol.qty_ordered)::integer as n_completas,
           count(*) filter (where coalesce(r.qty_recv,0) = 0)::integer as n_sin_recibir
      from purchase_order_line pol
      left join recv r on r.pol_id = pol.id
     group by 1
  )
  select po.id, po.code, po.status, s.name, l.name, po.expected_date,
         (current_date - po.expected_date)::integer,
         coalesce(pp.n_lineas,0), coalesce(pp.n_completas,0), coalesce(pp.n_sin_recibir,0)
    from purchase_order po
    left join supplier s on s.id = po.supplier_id
    left join locations l on l.id = po.location_id
    left join por_pedido pp on pp.po_id = po.id
   where po.status in ('enviado', 'recibido_parcial')
     and po.expected_date < current_date - greatest(p_days, 0)
     and public.belongs_to_account(po.account_id)
   order by po.expected_date;
$$;


--
-- Name: push_location_opening_hours(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_location_opening_hours(p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_ext_loc    text;
  v_secret     text;
  v_log_id     uuid;
  v_hours      jsonb;
  v_patch      jsonb;
begin
  select account_id into v_account_id from locations where id = p_location_id;
  if v_account_id is null then
    raise exception 'push_location_opening_hours: local % no encontrado', p_location_id;
  end if;

  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_account_id)) then
    raise exception 'push_location_opening_hours: sin acceso a la cuenta %', v_account_id;
  end if;

  -- 7 días completos (nombre HubRise), SIEMPRE presentes aunque estén vacíos.
  -- weekday Folvy: 0=domingo..6=sabado (business_hours.weekday).
  with days(weekday, day_name) as (
    values (1, 'monday'), (2, 'tuesday'), (3, 'wednesday'), (4, 'thursday'),
           (5, 'friday'), (6, 'saturday'), (0, 'sunday')
  ),
  slots as (
    select bh.weekday,
           jsonb_agg(
             jsonb_build_object('from', to_char(bh.open_time, 'HH24:MI'), 'to', to_char(bh.close_time, 'HH24:MI'))
             order by bh.open_time
           ) as tramos
    from business_hours bh
    where bh.location_id = p_location_id and bh.brand_id is null
    group by bh.weekday
  )
  select jsonb_object_agg(d.day_name, coalesce(s.tramos, '[]'::jsonb))
    into v_hours
  from days d
  left join slots s on s.weekday = d.weekday;

  select elm.external_location_id into v_ext_loc
  from external_location_map elm
  where elm.account_id = v_account_id and elm.source = 'hubrise' and elm.is_active
    and elm.location_id = p_location_id
  limit 1;

  v_patch := jsonb_build_object('opening_hours', v_hours);

  insert into location_status_log
    (account_id, location_id, external_location_id, kind, patch_body, surface, set_by)
  values
    (v_account_id, p_location_id, v_ext_loc, 'opening_hours', v_patch, 'web', auth.uid())
  returning id into v_log_id;

  if v_ext_loc is null then
    update location_status_log
    set ok = true, error = 'Local sin conexión HubRise: horario guardado solo en Folvy', resolved_at = now()
    where id = v_log_id;
    return jsonb_build_object('location_id', p_location_id, 'connected', false, 'log_id', v_log_id);
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets where name = 'location_status_dispatch_secret';

  if v_secret is null then
    update location_status_log
    set ok = false, error = 'secret location_status_dispatch_secret ausente en Vault', resolved_at = now()
    where id = v_log_id;
    raise warning 'push_location_opening_hours: secret location_status_dispatch_secret ausente en Vault, no se empuja a HubRise';
    return jsonb_build_object('location_id', p_location_id, 'connected', true, 'log_id', v_log_id, 'dispatched', false);
  end if;

  perform net.http_post(
    url     := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/hubrise-location-dispatch',
    headers := jsonb_build_object(
      'Content-Type',                       'application/json',
      'x-location-status-dispatch-secret',  v_secret
    ),
    body    := jsonb_build_object(
      'log_id',               v_log_id,
      'account_id',           v_account_id,
      'external_location_id', v_ext_loc,
      'patch_body',           v_patch
    )
  );

  return jsonb_build_object('location_id', p_location_id, 'connected', true, 'log_id', v_log_id, 'dispatched', true);
end;
$$;


--
-- Name: quality_dashboard(uuid, timestamp with time zone, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quality_dashboard(p_account uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location uuid DEFAULT NULL::uuid, p_brand uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  with rev as (
    select r.*, b.name as brand from public.channel_review r
    left join public.brand b on b.id=r.brand_id
    where r.account_id=p_account
      and (p_from is null or r.review_date >= p_from::date)
      and (p_to is null or r.review_date < p_to::date)
      and (p_location is null or r.location_id=p_location)
      and (p_brand is null or r.brand_id=p_brand)
  ),
  inc as (
    select i.*, b.name as brand from public.channel_incident i
    left join public.brand b on b.id=i.brand_id
    where i.account_id=p_account
      and (p_from is null or i.incident_date >= p_from::date)
      and (p_to is null or i.incident_date < p_to::date)
      and (p_location is null or i.location_id=p_location)
      and (p_brand is null or i.brand_id=p_brand)
  ),
  ops as (
    select o.*, b.name as brand from public.channel_ops_time o
    left join public.brand b on b.id=o.brand_id
    where o.account_id=p_account
      and (p_location is null or o.location_id=p_location)
      and (p_brand is null or o.brand_id=p_brand)
  ),
  tag_rows as (
    select trim(t) as tag from rev, unnest(string_to_array(coalesce(rev.tags,''), ',')) t
    where trim(t) <> ''
  )
  select jsonb_build_object(
    'ratings', jsonb_build_object(
      'n', (select count(*) from rev where stars is not null),
      'avg', (select round(avg(stars),2) from rev where stars is not null),
      'dist', (select coalesce(jsonb_object_agg(s::text, c),'{}'::jsonb) from (
        select stars::int s, count(*) c from rev where stars is not null group by 1) d)
    ),
    'by_brand', (select coalesce(jsonb_agg(x order by x.n desc),'[]'::jsonb) from (
      select brand, round(avg(stars),2) as avg, count(*) as n, count(*) filter (where stars<=2) as neg
      from rev where stars is not null and brand is not null group by brand) x),
    'comments', (select coalesce(jsonb_agg(jsonb_build_object('stars',stars,'brand',brand,'txt',comment,'tags',tags) order by review_date),'[]'::jsonb)
      from rev where comment is not null and comment<>''),
    'tags', (select coalesce(jsonb_agg(jsonb_build_object('tag',tag,'n',n) order by n desc),'[]'::jsonb) from (
      select tag, count(*) n from tag_rows group by tag) tg),
    'err_types', (select coalesce(jsonb_agg(jsonb_build_object('type',incident_type,'n',n) order by n desc),'[]'::jsonb) from (
      select incident_type, count(*) n from inc group by incident_type) e),
    'top_fail', (select coalesce(jsonb_agg(jsonb_build_object('item',item,'n',n) order by n desc),'[]'::jsonb) from (
      select split_part(item_name,' | ',1) as item, count(*) n from inc where item_name is not null group by 1 order by n desc limit 10) f),
    'refund', jsonb_build_object(
      'total', (select round(coalesce(sum(refund_total),0)) from inc),
      'own', (select round(coalesce(sum(refund_own),0)) from inc)),
    'incidencias', (select count(*) from inc),
    'tiempos', (select case when coalesce(sum(n_orders),0) > 0 then jsonb_build_object(
        'n', sum(n_orders),
        'prep_avg', round(sum(prep_avg*n_orders)/nullif(sum(n_orders),0),1),
        'delivery_avg', round(sum(delivery_avg*n_orders)/nullif(sum(n_orders),0),1),
        'total_avg', round(sum(total_avg*n_orders)/nullif(sum(n_orders),0),1),
        'wait_avoidable_total_h', round(sum(wait_avoidable_total_min)/60.0,1),
        'completion_pct', round(sum(completion_pct*n_orders)/nullif(sum(n_orders),0),1),
        'by_brand', (select coalesce(jsonb_agg(jsonb_build_object('brand',brand,'total',total,'n',nn) order by total desc),'[]'::jsonb) from (
          select brand, round(sum(total_avg*n_orders)/nullif(sum(n_orders),0),1) as total, sum(n_orders) nn
          from ops where brand is not null group by brand having sum(n_orders)>=20) bt)
      ) else null end from ops)
  );
$$;


--
-- Name: FUNCTION quality_dashboard(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid, p_brand uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.quality_dashboard(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location uuid, p_brand uuid) IS 'Area de Calidad: valoraciones (dist/avg/por marca), comentarios, etiquetas, tipos de error, platos que fallan, reembolsos. Lee channel_review + channel_incident.';


--
-- Name: queue_ctb_order_claim(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_ctb_order_claim(p_order_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order  purchase_order%rowtype;
  v_notify text;
  v_faltan integer;
  v_id     uuid;
begin
  select * into v_order from purchase_order where id = p_order_id;
  if not found then
    raise exception 'queue_ctb_order_claim: el pedido % no existe', p_order_id;
  end if;
  if not public.belongs_to_account(v_order.account_id) then
    raise exception 'queue_ctb_order_claim: sin acceso al pedido %', p_order_id;
  end if;

  if v_order.supplier_id is null then
    raise exception 'queue_ctb_order_claim: el pedido % no tiene proveedor', coalesce(v_order.code, p_order_id::text);
  end if;
  select notify_group into v_notify from supplier where id = v_order.supplier_id;
  if coalesce(v_notify, '') <> 'ctb' then
    -- Sin fallo mudo: se dice POR QUÉ no se puede, no se devuelve null.
    raise exception 'queue_ctb_order_claim: el proveedor de % no comunica por el grupo de CTB, no hay a dónde reclamar desde aquí',
      coalesce(v_order.code, p_order_id::text);
  end if;

  -- No se reclama un pedido que no le falta nada: sería mandar ruido al grupo.
  select count(*) into v_faltan
    from public.purchase_order_shortfall(p_order_id) s where s.qty_missing > 0;
  if v_faltan = 0 then
    raise exception 'queue_ctb_order_claim: a % no le falta nada que reclamar', coalesce(v_order.code, p_order_id::text);
  end if;

  insert into ctb_notification_queue (
    account_id, goods_receipt_id, purchase_order_id, location_id, supplier_id,
    notify_group, has_differences, status
  )
  values (
    v_order.account_id, null, p_order_id, v_order.location_id, v_order.supplier_id,
    'ctb', true, 'pendiente'
  )
  returning id into v_id;

  return v_id;
end;
$$;


