--
-- Name: reanchor_counted_adjustments(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reanchor_counted_adjustments(p_batch text) RETURNS TABLE(lines_processed integer, movements_written integer, movements_removed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r            record;
  v_seq        integer := 0;
  v_written    integer := 0;
  v_removed    integer := 0;
  v_old_rows   jsonb;
  v_old_qty    numeric;
  v_before     numeric;
  v_delta      numeric;
  v_touched    uuid[] := '{}'::uuid[];
  v_locs       uuid[] := '{}'::uuid[];
  i            integer;
BEGIN
  IF p_batch IS NULL OR length(trim(p_batch)) = 0 THEN
    RAISE EXCEPTION 'reanchor_counted_adjustments: hace falta un nombre de lote';
  END IF;
  IF EXISTS (SELECT 1 FROM public.stock_movement_reanchor_log WHERE batch = p_batch) THEN
    RAISE EXCEPTION 'reanchor_counted_adjustments: el lote % ya existe', p_batch;
  END IF;

  FOR r IN
    SELECT ic.id  AS count_id, ic.code AS count_code, ic.status AS count_status,
           ic.account_id, ic.location_id, ic.is_opening,
           l.id AS line_id, l.recipe_item_id, l.counted_qty,
           COALESCE(l.counted_at, ic.started_at, ic.closed_at, ic.created_at) AS cut_at
      FROM public.inventory_count ic
      JOIN public.inventory_count_line l ON l.inventory_count_id = ic.id
     WHERE ic.status IN ('aprobado', 'en_revision')
       AND l.counted_qty IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.stock_movement sm
                    WHERE sm.source_type = 'inventory_count'
                      AND sm.source_id   = ic.id
                      AND sm.recipe_item_id = l.recipe_item_id)
     ORDER BY COALESCE(l.counted_at, ic.started_at, ic.closed_at, ic.created_at),
              ic.id, l.recipe_item_id
  LOOP
    v_seq := v_seq + 1;

    SELECT COALESCE(jsonb_agg(to_jsonb(sm)), '[]'::jsonb), COALESCE(SUM(sm.qty_base), 0)
      INTO v_old_rows, v_old_qty
      FROM public.stock_movement sm
     WHERE sm.source_type = 'inventory_count'
       AND sm.source_id   = r.count_id
       AND sm.recipe_item_id = r.recipe_item_id;

    DELETE FROM public.stock_movement sm
     WHERE sm.source_type = 'inventory_count'
       AND sm.source_id   = r.count_id
       AND sm.recipe_item_id = r.recipe_item_id;
    v_removed := v_removed + 1;

    v_before := public.theoretical_qty_at(r.recipe_item_id, r.location_id, r.cut_at);
    v_delta  := r.counted_qty - v_before;

    IF abs(v_delta) > 0.0000001 THEN
      INSERT INTO public.stock_movement (
        account_id, location_id, recipe_item_id, movement_type, qty_base,
        unit_cost, cost_provisional, source_type, source_id, occurred_at,
        created_by, created_by_name, notes)
      SELECT r.account_id, r.location_id, r.recipe_item_id,
             COALESCE(o->>'movement_type', CASE WHEN r.is_opening THEN 'apertura' ELSE 'ajuste' END),
             v_delta,
             NULLIF(o->>'unit_cost','')::numeric,
             false, 'inventory_count', r.count_id, r.cut_at,
             NULLIF(o->>'created_by','')::uuid,
             o->>'created_by_name',
             COALESCE(o->>'notes', 'Ajuste por conteo de inventario')
        FROM jsonb_array_elements(v_old_rows) o
       LIMIT 1;
      v_written := v_written + 1;
      v_removed := v_removed - 1;
    END IF;

    INSERT INTO public.stock_movement_reanchor_log (
      batch, seq, inventory_count_id, count_code, count_status,
      inventory_count_line_id, recipe_item_id, location_id, cut_at,
      counted_qty, ledger_before_new, old_qty_base, new_qty_base, old_rows)
    VALUES (
      p_batch, v_seq, r.count_id, r.count_code, r.count_status,
      r.line_id, r.recipe_item_id, r.location_id, r.cut_at,
      r.counted_qty, v_before, v_old_qty,
      CASE WHEN abs(v_delta) > 0.0000001 THEN v_delta ELSE 0 END, v_old_rows);

    v_touched := v_touched || r.recipe_item_id;
    v_locs    := v_locs    || r.location_id;
  END LOOP;

  IF array_length(v_touched, 1) IS NOT NULL THEN
    FOR i IN 1 .. array_length(v_touched, 1) LOOP
      PERFORM public.recompute_location_stock_core(v_touched[i], v_locs[i]);
    END LOOP;
  END IF;

  lines_processed   := v_seq;
  movements_written := v_written;
  movements_removed := v_removed;
  RETURN NEXT;
END;
$$;


--
-- Name: reassign_inventory_count(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign_inventory_count(p_count_id uuid, p_employee_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_kind text;
  v_status text;
  v_reset boolean := false;
begin
  select account_id, kind, status
    into v_account_id, v_kind, v_status
    from public.inventory_count where id = p_count_id
    for update;

  if v_account_id is null then
    raise exception 'reassign_inventory_count: conteo % no existe', p_count_id;
  end if;

  -- Solo conteos MANUALES (los cycle del autoinventario no se reasignan a mano).
  if v_kind not in ('full','audit') then
    raise exception 'reassign_inventory_count: solo se reasignan inventarios manuales';
  end if;

  -- Solo gestor/admin (oficina).
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_account_id)) then
    raise exception 'reassign_inventory_count: solo un gestor puede reasignar un inventario';
  end if;

  -- El empleado nuevo debe existir en la cuenta y estar activo.
  if not exists (
    select 1 from public.employees e
    where e.id = p_employee_id and e.account_id = v_account_id and e.active = true
  ) then
    raise exception 'reassign_inventory_count: el empleado no es válido para esta cuenta';
  end if;

  -- No tiene sentido reasignar algo ya contado.
  if v_status in ('en_revision','aprobado','anulado') then
    raise exception 'reassign_inventory_count: el inventario está en % y ya no se puede reasignar', v_status;
  end if;

  -- Si ya se había EMPEZADO (contando) → REINICIA: borra la hoja y vuelve a
  -- programado. El nuevo asignado pulsará "Empezar" y hará su propio snapshot.
  if v_status = 'contando' then
    delete from public.inventory_count_line where inventory_count_id = p_count_id;
    v_reset := true;
  end if;

  update public.inventory_count
    set assigned_employee_id = p_employee_id,
        assigned_at = now(),
        assigned_by = auth.uid(),
        status = 'abierto',
        started_at = null,
        updated_at = now()
    where id = p_count_id;

  return case when v_reset then 'reasignado_reiniciado' else 'reasignado' end;
end;
$$;


--
-- Name: rebase_count_system_qty(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebase_count_system_qty(p_count_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_location_id uuid;
  v_instant timestamptz;
  v_n integer := 0;
BEGIN
  SELECT location_id, COALESCE(started_at, closed_at, created_at, now())
    INTO v_location_id, v_instant
    FROM public.inventory_count WHERE id = p_count_id;
  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'rebase_count_system_qty: conteo % no existe', p_count_id;
  END IF;

  UPDATE public.inventory_count_line l
     SET system_qty = public.theoretical_qty_at(
                        l.recipe_item_id,
                        v_location_id,
                        COALESCE(l.counted_at, v_instant))
   WHERE l.inventory_count_id = p_count_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: recasar_lastapp_en_frio(uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recasar_lastapp_en_frio(p_account_id uuid, p_dry_run boolean DEFAULT true, p_dias integer DEFAULT 30) RETURNS TABLE(lineas_miradas integer, casadas_por_id integer, casadas_por_nom integer, ambiguas integer, sin_casar integer, euros_recuperados numeric, bajo_corte integer, corte_vigente timestamp with time zone, aplicado boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_arm "char"; v_corte timestamptz; v_r record; v_mi uuid; v_n integer; v_via text;
  v_look integer := 0; v_id integer := 0; v_nom integer := 0;
  v_amb integer := 0; v_no integer := 0; v_bajo integer := 0; v_eur numeric := 0;
begin
  -- Guarda de tenencia, como `recast_lastapp_sales`, MAS el dueno de la base.
  -- `session_user` y no `current_user`: la funcion es SECURITY DEFINER, asi que
  -- para un usuario de la aplicacion `current_user` YA es postgres y esto seria
  -- una puerta abierta a cualquiera.
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)
          or session_user = 'postgres') then
    raise exception 'recasar_lastapp_en_frio: sin acceso a la cuenta %', p_account_id;
  end if;

  -- ENCLAVAMIENTO: si el disparador de consumo esta armado, esto NO escribe.
  select t.tgenabled into v_arm
    from pg_trigger t join pg_class c on c.oid = t.tgrelid
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relname = 'sale_line'
     and t.tgname = 'trg_sale_line_consumption';
  if v_arm is null then
    raise exception 'recasar_lastapp_en_frio: no encuentro trg_sale_line_consumption. '
                    'Si lo han renombrado, este enclavamiento ya no protege nada: para.';
  end if;
  if v_arm <> 'D' and not p_dry_run then
    raise exception 'recasar_lastapp_en_frio: trg_sale_line_consumption esta ARMADO (%). '
                    'Escribir menu_item_id ahora generaria consumo, que es justo lo que '
                    'esta pasada NO debe hacer. Desarmalo en el script de la pasada.', v_arm;
  end if;

  select max(ic.closed_at) into v_corte from public.inventory_count ic
   where ic.account_id = p_account_id and ic.status in ('aprobado','en_revision');

  for v_r in
    select sl.id, sl.external_product_id, sl.line_total, sl.unmapped_reason,
           coalesce(sl.product_name, sl.raw_text) as nombre,
           s.id as sale_id, s.sold_at, s.brand_id
      from public.sale_line sl join public.sale s on s.id = sl.sale_id
     where sl.account_id = p_account_id and s.account_id = p_account_id
       and s.source = 'lastapp' and sl.map_source = 'unmapped' and sl.menu_item_id is null
       and coalesce(sl.unmapped_reason,'') not in ('ignored','delisted')
       and coalesce(s.status,'') <> 'cancelled'
       and coalesce(s.order_status,'') not in ('cancelled','rejected')
       and coalesce(s.is_active, true)
       and s.sold_at >= now() - make_interval(days => p_dias)
     order by s.sold_at
  loop
    v_look := v_look + 1; v_mi := null; v_via := null;

    if v_r.external_product_id is not null then
      select count(*) into v_n from public.menu_item mi
       where mi.account_id = p_account_id and mi.external_source = 'lastapp'
         and mi.archived_at is null and mi.external_id = v_r.external_product_id;
      if v_n = 1 then
        select mi.id into v_mi from public.menu_item mi
         where mi.account_id = p_account_id and mi.external_source = 'lastapp'
           and mi.archived_at is null and mi.external_id = v_r.external_product_id;
        v_via := 'id';
      elsif v_n > 1 and v_r.brand_id is not null then
        select count(*) into v_n from public.menu_item mi
         where mi.account_id = p_account_id and mi.external_source = 'lastapp'
           and mi.archived_at is null and mi.external_id = v_r.external_product_id
           and mi.brand_id = v_r.brand_id;
        if v_n = 1 then
          select mi.id into v_mi from public.menu_item mi
           where mi.account_id = p_account_id and mi.external_source = 'lastapp'
             and mi.archived_at is null and mi.external_id = v_r.external_product_id
             and mi.brand_id = v_r.brand_id;
          v_via := 'id';
        end if;
      end if;
    end if;

    -- Red: el nombre EXACTO, dentro de la marca. Exacto a proposito: hay 43
    -- grupos de carta con el mismo nombre suave y 3 apuntan a FICHAS DISTINTAS.
    if v_mi is null and v_r.brand_id is not null and v_r.nombre is not null then
      select count(*) into v_n from public.menu_item mi
       where mi.account_id = p_account_id and mi.archived_at is null
         and mi.brand_id = v_r.brand_id
         and lower(public.unaccent(mi.name)) = lower(public.unaccent(v_r.nombre));
      if v_n = 1 then
        select mi.id into v_mi from public.menu_item mi
         where mi.account_id = p_account_id and mi.archived_at is null
           and mi.brand_id = v_r.brand_id
           and lower(public.unaccent(mi.name)) = lower(public.unaccent(v_r.nombre));
        v_via := 'nombre';
      elsif v_n > 1 then
        -- Dos candidatos y ningun criterio: NO se elige.
        v_amb := v_amb + 1; continue;
      end if;
    end if;

    if v_mi is null then v_no := v_no + 1; continue; end if;
    if v_via = 'id' then v_id := v_id + 1; else v_nom := v_nom + 1; end if;
    v_eur := v_eur + coalesce(v_r.line_total, 0);
    if v_corte is not null and v_r.sold_at <= v_corte then v_bajo := v_bajo + 1; end if;

    if not p_dry_run then
      update public.sale_line
         set menu_item_id = v_mi,
             map_source = case when v_via = 'id' then 'pos' else 'fuzzy' end,
             map_needs_review = false, unmapped_reason = null
       where id = v_r.id;
      insert into public.sale_line_recast_frio (
        account_id, sale_line_id, sale_id, sold_at, menu_item_id, via,
        nombre_en_venta, external_id, line_total, motivo_anterior,
        corte_vigente, bajo_corte, recasado_por)
      values (p_account_id, v_r.id, v_r.sale_id, v_r.sold_at, v_mi, v_via,
        v_r.nombre, v_r.external_product_id, v_r.line_total, v_r.unmapped_reason,
        v_corte, (v_corte is not null and v_r.sold_at <= v_corte),
        coalesce(current_setting('request.jwt.claim.email', true), current_user))
      on conflict (sale_line_id) do nothing;
    end if;
  end loop;

  lineas_miradas := v_look; casadas_por_id := v_id; casadas_por_nom := v_nom;
  ambiguas := v_amb; sin_casar := v_no; euros_recuperados := round(v_eur, 2);
  bajo_corte := v_bajo; corte_vigente := v_corte; aplicado := not p_dry_run;
  return next;
end; $$;


--
-- Name: recast_lastapp_sales(uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recast_lastapp_sales(p_account_id uuid, p_incluir_bajo_conteo boolean DEFAULT false, p_ventas_esperadas integer DEFAULT NULL::integer) RETURNS TABLE(ventas_procesadas integer, ventas_protegidas integer, corte_en timestamp with time zone, lineas_total integer, lineas_casadas integer, lineas_no_brand integer, lineas_no_recipe integer, lineas_no_menu_item integer, lineas_ambiguous integer, lineas_respetadas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale_id  uuid;
  v_corte    timestamptz;
  v_bajo     integer := 0;
  v_ventas   integer := 0;
  v_prot     integer := 0;
  v_total    integer := 0;
  v_ok       integer := 0;
  v_nb       integer := 0;
  v_nr       integer := 0;
  v_nm       integer := 0;
  v_amb      integer := 0;
  v_resp     integer := 0;
BEGIN
  -- Guard de tenancy (sin cambios).
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'recast_lastapp_sales: sin acceso a la cuenta %', p_account_id;
  END IF;

  -- El corte: el ultimo conteo que ya fijo la verdad del stock.
  SELECT max(ic.closed_at) INTO v_corte
    FROM public.inventory_count ic
   WHERE ic.account_id = p_account_id
     AND ic.status IN ('aprobado','en_revision');

  IF v_corte IS NOT NULL THEN
    SELECT count(*) INTO v_bajo
      FROM public.sale s
     WHERE s.account_id = p_account_id AND s.source = 'lastapp'
       AND s.raw_products IS NOT NULL AND s.sold_at <= v_corte;
  END IF;

  -- Bajar del corte exige la cifra exacta, no un booleano.
  IF p_incluir_bajo_conteo AND v_corte IS NOT NULL THEN
    IF p_ventas_esperadas IS NULL THEN
      RAISE EXCEPTION
        'recast_lastapp_sales: para reprocesar por debajo del ultimo conteo (%) hay que pasar '
        'p_ventas_esperadas con el numero exacto de ventas afectadas. Ahora mismo son %.',
        v_corte, v_bajo;
    END IF;
    IF p_ventas_esperadas <> v_bajo THEN
      RAISE EXCEPTION
        'recast_lastapp_sales: p_ventas_esperadas=% no coincide con las % ventas que hay por '
        'debajo del corte (%). Vuelve a mirarlo: o el numero esta mal, o han entrado ventas '
        'desde que lo miraste.',
        p_ventas_esperadas, v_bajo, v_corte;
    END IF;
  END IF;

  FOR v_sale_id IN
    SELECT id FROM public.sale
     WHERE account_id = p_account_id AND source = 'lastapp' AND raw_products IS NOT NULL
       AND (v_corte IS NULL OR p_incluir_bajo_conteo OR sold_at > v_corte)
     ORDER BY sold_at
  LOOP
    PERFORM public.reprocess_sale(v_sale_id);
  END LOOP;

  v_prot := CASE WHEN v_corte IS NULL OR p_incluir_bajo_conteo THEN 0 ELSE v_bajo END;

  -- Metricas leidas del canonico ya reescrito (no del JSON). Se miden sobre
  -- TODA la cuenta a proposito: son el estado del casado, no el de esta pasada.
  SELECT
    count(DISTINCT sl.sale_id),
    count(*),
    count(*) FILTER (WHERE sl.menu_item_id IS NOT NULL),
    count(*) FILTER (WHERE sl.unmapped_reason = 'no_brand'),
    count(*) FILTER (WHERE sl.unmapped_reason = 'no_recipe'),
    count(*) FILTER (WHERE sl.unmapped_reason = 'no_menu_item'),
    count(*) FILTER (WHERE sl.unmapped_reason = 'ambiguous'),
    count(*) FILTER (WHERE sl.map_source = 'manual'
                        OR COALESCE(sl.unmapped_reason, '') IN ('ignored', 'delisted'))
  INTO v_ventas, v_total, v_ok, v_nb, v_nr, v_nm, v_amb, v_resp
  FROM public.sale_line sl
  JOIN public.sale s ON s.id = sl.sale_id
  WHERE sl.account_id = p_account_id AND s.source = 'lastapp'
    AND COALESCE(sl.line_type, 'product') = 'product';

  ventas_procesadas   := v_ventas;
  ventas_protegidas   := v_prot;
  corte_en            := v_corte;
  lineas_total        := v_total;
  lineas_casadas      := v_ok;
  lineas_no_brand     := v_nb;
  lineas_no_recipe    := v_nr;
  lineas_no_menu_item := v_nm;
  lineas_ambiguous    := v_amb;
  lineas_respetadas   := v_resp;
  RETURN NEXT;
END;
$$;


--
-- Name: receive_goods_receipt(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_goods_receipt(p_receipt_id uuid, p_hold boolean DEFAULT false) RETURNS TABLE(posted_lines integer, skipped_lines integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_receipt goods_receipt%rowtype;
  v_posted  integer := 0;
  v_skipped integer := 0;
  v_needs   boolean;
  v_direct  boolean := false;
begin
  select * into v_receipt from goods_receipt where id = p_receipt_id;
  if not found then
    raise exception 'receive_goods_receipt: albarán % no existe', p_receipt_id;
  end if;
  if not belongs_to_account(v_receipt.account_id) then
    raise exception 'receive_goods_receipt: sin acceso al albarán %', p_receipt_id;
  end if;
  if v_receipt.status <> 'borrador' then
    raise exception 'receive_goods_receipt: el albarán % no está en borrador (está %)',
      p_receipt_id, v_receipt.status;
  end if;

  -- El stock entra SIEMPRE, dude o no la IA. Lo que no se puede postear (linea
  -- sin articulo o sin cantidad base) sale como skipped y deja needs_review.
  select p.posted_lines, p.skipped_lines into v_posted, v_skipped
    from public._post_goods_receipt_lines(p_receipt_id) p;

  v_needs := p_hold or v_skipped > 0 or coalesce(v_receipt.needs_review, false);

  update goods_receipt
    set status = 'recibido', received_at = coalesce(received_at, now()),
        needs_review = v_needs, via_assistant = true, updated_at = now()
    where id = p_receipt_id;

  if v_receipt.purchase_order_id is null then
    v_receipt.purchase_order_id := public.auto_link_goods_receipt_to_order(p_receipt_id);
  end if;
  if v_receipt.purchase_order_id is not null then
    perform public._match_order_lines_for_order(v_receipt.purchase_order_id);
    perform recompute_purchase_order_status(v_receipt.purchase_order_id);
  end if;

  -- Confianza ganada: el albaran se cierra solo, sin pasar por oficina. Solo si
  -- no hay nada dudoso. Si confirm_goods_receipt no puede cerrarlo (falta nº de
  -- albaran, proveedor o alguna linea sin decidir) se queda en 'recibido': la
  -- recepcion NUNCA falla por esto.
  select coalesce(t.direct_confirm_enabled, false) into v_direct
    from public.location_receipt_trust t where t.location_id = v_receipt.location_id;

  if coalesce(v_direct, false) and not v_needs then
    begin
      perform public.confirm_goods_receipt(p_receipt_id);
    exception when others then
      raise warning 'receive_goods_receipt: confirmación directa no pudo cerrar %: %',
        coalesce(v_receipt.code, p_receipt_id::text), sqlerrm;
    end;
  end if;

  perform public.refresh_location_receipt_trust(v_receipt.location_id);

  posted_lines := v_posted; skipped_lines := v_skipped;
  return next;
end;
$$;


--
-- Name: recipe_item_allergen_set_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipe_item_allergen_set_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  if new.source = 'manual' and auth.uid() is not null then
    new.updated_by := auth.uid();
  end if;
  return new;
end;
$$;


--
-- Name: recipe_item_has_unmeasurable_line(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipe_item_has_unmeasurable_line(p_item_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item recipe_item%ROWTYPE;
  v_line recipe_line%ROWTYPE;
  v_qb   numeric;
BEGIN
  IF p_item_id IS NULL THEN RETURN false; END IF;
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN RETURN false; END IF;

  -- Hoja del árbol de consumo: no tiene líneas que explotar.
  IF v_item.type IN ('raw', 'tool')
     OR (v_item.type = 'recipe' AND COALESCE(v_item.is_stockable, false)) THEN
    RETURN false;
  END IF;

  FOR v_line IN
    SELECT * FROM recipe_line WHERE parent_item_id = p_item_id
  LOOP
    v_qb := public._qty_in_base(
              v_line.child_item_id,
              COALESCE(v_line.quantity_gross, v_line.quantity_net),
              v_line.unit_id);
    IF v_qb IS NULL THEN
      RETURN true;  -- esta línea no convierte -> no medible
    END IF;
    IF public.recipe_item_has_unmeasurable_line(v_line.child_item_id) THEN
      RETURN true;  -- el subárbol del hijo tiene una línea no medible
    END IF;
  END LOOP;

  RETURN false;
END;
$$;


--
-- Name: recipe_item_unmeasurable_raws(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipe_item_unmeasurable_raws(p_item_id uuid) RETURNS TABLE(raw_item_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item recipe_item%ROWTYPE;
  v_line recipe_line%ROWTYPE;
  v_qb   numeric;
BEGIN
  IF p_item_id IS NULL THEN RETURN; END IF;
  SELECT * INTO v_item FROM recipe_item WHERE id = p_item_id;
  IF NOT FOUND THEN RETURN; END IF;

  -- Hoja: no tiene líneas.
  IF v_item.type IN ('raw', 'tool')
     OR (v_item.type = 'recipe' AND COALESCE(v_item.is_stockable, false)) THEN
    RETURN;
  END IF;

  FOR v_line IN
    SELECT * FROM recipe_line WHERE parent_item_id = p_item_id
  LOOP
    v_qb := public._qty_in_base(
              v_line.child_item_id,
              COALESCE(v_line.quantity_gross, v_line.quantity_net),
              v_line.unit_id);
    IF v_qb IS NULL THEN
      -- Línea no medible: TODO el subárbol del hijo queda sin contar.
      -- (medibles que cuelgan del hijo + no-medibles más profundos)
      RETURN QUERY SELECT e.raw_item_id
        FROM public.explode_recipe_to_raws(v_line.child_item_id, 1) e;
      RETURN QUERY SELECT u.raw_item_id
        FROM public.recipe_item_unmeasurable_raws(v_line.child_item_id) u;
    ELSE
      -- Línea medible: el subárbol del hijo puede tener SUS propias no-medibles.
      RETURN QUERY SELECT u.raw_item_id
        FROM public.recipe_item_unmeasurable_raws(v_line.child_item_id) u;
    END IF;
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: recipe_line_prevent_cycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recipe_line_prevent_cycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cycle_found boolean;
BEGIN
  -- Una línea no puede referenciarse a sí misma
  IF NEW.parent_item_id = NEW.child_item_id THEN
    RAISE EXCEPTION 'Ciclo en escandallo: un plato no puede contenerse a sí mismo (item %)', NEW.parent_item_id;
  END IF;

  -- ¿El child (o algún descendiente suyo) vuelve al parent? → ciclo
  WITH RECURSIVE descendientes AS (
    SELECT child_item_id
    FROM recipe_line
    WHERE parent_item_id = NEW.child_item_id
    UNION
    SELECT rl.child_item_id
    FROM recipe_line rl
    JOIN descendientes d ON rl.parent_item_id = d.child_item_id
  )
  SELECT EXISTS (
    SELECT 1 FROM descendientes WHERE child_item_id = NEW.parent_item_id
  ) INTO v_cycle_found;

  IF v_cycle_found THEN
    RAISE EXCEPTION 'Ciclo en escandallo detectado: % usaría % que (directa o indirectamente) ya usa %',
      NEW.parent_item_id, NEW.child_item_id, NEW.parent_item_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: recompute_location_stock(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_location_stock(p_item_id uuid, p_location_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
BEGIN
  SELECT account_id INTO v_account_id FROM recipe_item WHERE id = p_item_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'recompute_location_stock: item % no existe', p_item_id;
  END IF;
  IF NOT public.belongs_to_account(v_account_id) THEN
    RAISE EXCEPTION 'recompute_location_stock: sin acceso al item %', p_item_id;
  END IF;
  PERFORM public.recompute_location_stock_core(p_item_id, p_location_id);
END;
$$;


--
-- Name: recompute_location_stock_core(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_location_stock_core(p_item_id uuid, p_location_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_qty        numeric := 0;
  v_avg        numeric := NULL;
  v_base       numeric;
  v_value      numeric;
  v_ficha      numeric;
  v_banda      numeric;
  r            RECORD;
BEGIN
  SELECT account_id,
         COALESCE(NULLIF(computed_cost, 0), NULLIF(fixed_cost, 0))
    INTO v_account_id, v_ficha
    FROM recipe_item WHERE id = p_item_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'recompute_location_stock_core: item % no existe', p_item_id;
  END IF;

  SELECT COALESCE(cost_band_factor, 5) INTO v_banda
    FROM supply_settings WHERE account_id = v_account_id;
  v_banda := COALESCE(v_banda, 5);
  IF v_banda <= 1 THEN v_banda := 5; END IF;

  -- El libro en orden. `id` desempata para que dos movimientos con el mismo
  -- instante se recorran siempre igual: sin ese desempate, el mismo libro daría
  -- dos costes distintos en dos ejecuciones y nadie sabría cuál creerse.
  FOR r IN
    SELECT qty_base, unit_cost,
           (source_type = 'goods_receipt_line'
            OR movement_type IN ('recepcion', 'traspaso_entrada')) AS es_recepcion
      FROM stock_movement
     WHERE recipe_item_id = p_item_id
       AND location_id    = p_location_id
     ORDER BY occurred_at, id
  LOOP
    -- SÓLO LAS RECEPCIONES, y sólo si su coste es creíble.
    --
    -- `unit_cost > 0` y no `IS NOT NULL`: un coste negativo o cero no es un
    -- coste, es un hueco (regla 3, la misma lección que `computed_cost = 0`).
    --
    -- Y la banda: `v_ficha IS NULL` deja pasar a propósito —sin coste de ficha
    -- no hay con qué juzgar, y rechazar dejaría sin coste para siempre a un
    -- artículo nuevo.
    IF r.qty_base > 0
       AND r.es_recepcion
       AND r.unit_cost > 0
       AND (v_ficha IS NULL
            OR (r.unit_cost <= v_ficha * v_banda AND r.unit_cost >= v_ficha / v_banda))
    THEN
      v_base := GREATEST(v_qty, 0);
      IF v_avg IS NULL OR v_base = 0 THEN
        v_avg := r.unit_cost;
      ELSE
        v_avg := (v_base * v_avg + r.qty_base * r.unit_cost) / (v_base + r.qty_base);
      END IF;
    END IF;
    -- Todo lo demás mueve la CANTIDAD y no el coste: las salidas, los ajustes
    -- de recuento, las mermas y las aperturas.
    v_qty := v_qty + r.qty_base;
  END LOOP;

  IF abs(v_qty) < 0.0000001 THEN
    v_qty := 0;
  END IF;

  -- Sin ninguna recepción válida: el coste de ficha. Y si tampoco, NULL.
  IF v_avg IS NULL THEN
    SELECT computed_cost INTO v_avg FROM recipe_item WHERE id = p_item_id;
    IF v_avg IS NOT NULL AND v_avg <= 0 THEN
      -- Regla 3: `computed_cost = 0` tapa el `fixed_cost` real. Aquí un cero no
      -- es un coste, es un hueco: se trata como lo que es.
      SELECT fixed_cost INTO v_avg FROM recipe_item WHERE id = p_item_id;
      IF v_avg IS NOT NULL AND v_avg <= 0 THEN v_avg := NULL; END IF;
    END IF;
  END IF;

  v_value := CASE WHEN v_avg IS NULL THEN NULL ELSE v_qty * v_avg END;

  INSERT INTO recipe_item_location_stock
    (account_id, recipe_item_id, location_id, qty_on_hand, avg_unit_cost, stock_value, updated_at)
  VALUES
    (v_account_id, p_item_id, p_location_id, v_qty, v_avg, v_value, now())
  ON CONFLICT (recipe_item_id, location_id) DO UPDATE
    SET qty_on_hand   = EXCLUDED.qty_on_hand,
        avg_unit_cost = EXCLUDED.avg_unit_cost,
        stock_value   = EXCLUDED.stock_value,
        updated_at    = now();
END;
$$;


--
-- Name: FUNCTION recompute_location_stock_core(p_item_id uuid, p_location_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recompute_location_stock_core(p_item_id uuid, p_location_id uuid) IS 'Media ponderada PERPETUA: recorre el libro en orden y SÓLO las recepciones con coste dentro de banda (cost_band_factor × coste de ficha) mueven la media. Los ajustes de recuento, las mermas y las salidas no la tocan. Un stock negativo no la envenena (max(qty,0)). Sin recepciones válidas, coste de ficha; sin eso, NULL — nunca 0 callado (§2.5 + correcciones de Julio del 10/09/2026).';


--
-- Name: recompute_purchase_order_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_purchase_order_status(p_order_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order          purchase_order%ROWTYPE;
  v_total_lines    integer;
  v_complete_lines integer;
  v_any_received   boolean;
  v_new_status     text;
BEGIN
  SELECT * INTO v_order FROM purchase_order WHERE id = p_order_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF NOT public.belongs_to_account(v_order.account_id) THEN
    RAISE EXCEPTION 'recompute_purchase_order_status: sin acceso al pedido %', p_order_id;
  END IF;

  -- Estados terminales/manuales: la automatización no los toca.
  IF v_order.status IN ('borrador', 'cancelado', 'cerrado') THEN
    RETURN v_order.status;
  END IF;

  -- Recibido acumulado por línea (solo recepciones CONFIRMADAS de este pedido)
  -- vs lo pedido. Líneas extra (sin purchase_order_line_id) no cuentan aquí.
  WITH recv AS (
    SELECT grl.purchase_order_line_id AS pol_id,
           SUM(grl.qty_received)       AS qty_recv
    FROM goods_receipt_line grl
    JOIN goods_receipt gr ON gr.id = grl.goods_receipt_id
    WHERE gr.purchase_order_id = p_order_id
      AND gr.status = 'confirmado'
      AND grl.purchase_order_line_id IS NOT NULL
    GROUP BY grl.purchase_order_line_id
  ),
  per_line AS (
    SELECT pol.id,
           pol.qty_ordered,
           COALESCE(r.qty_recv, 0) AS qty_recv
    FROM purchase_order_line pol
    LEFT JOIN recv r ON r.pol_id = pol.id
    WHERE pol.purchase_order_id = p_order_id
  )
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE qty_recv >= qty_ordered),
         COALESCE(bool_or(qty_recv > 0), false)
  INTO v_total_lines, v_complete_lines, v_any_received
  FROM per_line;

  IF v_total_lines = 0 THEN
    RETURN v_order.status;                 -- pedido sin líneas: no tocar
  ELSIF v_complete_lines = v_total_lines THEN
    v_new_status := 'recibido';
  ELSIF v_any_received THEN
    v_new_status := 'recibido_parcial';
  ELSE
    v_new_status := 'enviado';             -- nada recibido (p. ej. tras anular)
  END IF;

  IF v_new_status <> v_order.status THEN
    UPDATE purchase_order
      SET status = v_new_status, updated_at = now()
      WHERE id = p_order_id;
  END IF;

  RETURN v_new_status;
END;
$$;


--
-- Name: recompute_recipe_item_allergens(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_recipe_item_allergens(p_recipe_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account uuid;
BEGIN
  SELECT account_id INTO v_account FROM recipe_item WHERE id = p_recipe_item_id;
  IF v_account IS NULL THEN
    RAISE EXCEPTION 'recompute_recipe_item_allergens: escandallo % no existe', p_recipe_item_id;
  END IF;
  IF NOT public.belongs_to_account(v_account) THEN
    RAISE EXCEPTION 'recompute_recipe_item_allergens: sin acceso a la cuenta %', v_account;
  END IF;

  PERFORM public._recompute_recipe_item_allergens(p_recipe_item_id);
END;
$$;


--
-- Name: recompute_sales_consumption(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_sales_consumption(p_account_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(lines_processed integer, movements_written integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale_id uuid;
  v_sales   integer := 0;
  v_moves   integer := 0;
BEGIN
  IF NOT (current_user_is_admin()
          OR current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'recompute_sales_consumption: sin acceso a la cuenta %', p_account_id;
  END IF;

  FOR v_sale_id IN
    SELECT s.id
    FROM sale s
    WHERE s.account_id = p_account_id
      AND (p_from IS NULL OR s.sold_at >= p_from)
      AND (p_to   IS NULL OR s.sold_at <  p_to)
  LOOP
    v_moves := v_moves + COALESCE(public.generate_sale_consumption(v_sale_id), 0);
    v_sales := v_sales + 1;
  END LOOP;

  lines_processed   := v_sales;
  movements_written := v_moves;
  RETURN NEXT;
END;
$$;


--
-- Name: recost_sales_for_product(uuid, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recost_sales_for_product(p_account_id uuid, p_product_name text, p_days integer DEFAULT 30, p_dry_run boolean DEFAULT true) RETURNS TABLE(ventas_afectadas integer, lineas_afectadas integer, movimientos integer, aplicado boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_norm    text;
  v_sale    record;
  v_ventas  integer := 0;
  v_lineas  integer := 0;
  v_movs    integer := 0;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'recost_sales_for_product: sin acceso a la cuenta %', p_account_id;
  end if;

  v_norm := public.sales_product_norm(p_product_name);

  create temp table if not exists _recost_sales (sale_id uuid primary key) on commit drop;
  delete from _recost_sales where true;

  insert into _recost_sales (sale_id)
  select distinct s.id
    from sale_line sl
    join sale s on s.id = sl.sale_id
   where sl.account_id = p_account_id
     and s.is_active
     and s.sold_at >= now() - make_interval(days => greatest(p_days, 1))
     and coalesce(sl.line_type,'product') = 'product'
     and sl.ignored_at is null
     and public.sales_product_norm(sl.product_name) = v_norm;

  select count(*) into v_ventas from _recost_sales;

  select count(*) into v_lineas
    from sale_line sl
   where sl.account_id = p_account_id
     and sl.sale_id in (select sale_id from _recost_sales)
     and public.sales_product_norm(sl.product_name) = v_norm;

  if p_dry_run then
    return query select v_ventas, v_lineas, 0, false;
    return;
  end if;

  -- Casar las líneas viejas con el menu_item sellado de su matrícula, igual que
  -- haría el recast, pero acotado a este producto (no a la cuenta entera).
  update sale_line sl
     set menu_item_id = mi.id, map_source = 'manual', map_needs_review = false,
         unmapped_reason = null, updated_at = now()
    from sale s, menu_item mi
   where sl.sale_id = s.id
     and sl.account_id = p_account_id
     and sl.sale_id in (select sale_id from _recost_sales)
     and sl.menu_item_id is null
     and public.sales_product_norm(sl.product_name) = v_norm
     and mi.account_id = p_account_id
     and mi.external_source = 'lastapp'
     and mi.external_id = sl.external_product_id
     and mi.brand_id is not distinct from s.brand_id
     and mi.archived_at is null;

  for v_sale in select sale_id from _recost_sales loop
    v_movs := v_movs + coalesce(public.generate_sale_consumption(v_sale.sale_id), 0);
  end loop;

  return query select v_ventas, v_lineas, v_movs, true;
end;
$$;


--
-- Name: FUNCTION recost_sales_for_product(p_account_id uuid, p_product_name text, p_days integer, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recost_sales_for_product(p_account_id uuid, p_product_name text, p_days integer, p_dry_run boolean) IS 'Re-costeo retroactivo de UN producto (casa líneas viejas + regenera consumo). Descuadra el stock contado: siempre explícito, con dry-run por defecto.';


--
-- Name: recuperar_sello_listo(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recuperar_sello_listo(p_account_id uuid, p_pares jsonb, p_origen text DEFAULT 'analitica de Last (readyToPickupStatus), precision de segundo'::text) RETURNS TABLE(pos_short_code text, external_tab_ref text, resultado text, ready_at_escrito timestamp with time zone, nota text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r        record;
  v_sale   sale%rowtype;
  v_listo  timestamptz;
  v_res    text;
  v_nota   text;
begin
  if p_account_id is null then raise exception 'sin cuenta no se ancla nada'; end if;

  for r in select x->>'tab_id' as tab_id, (x->>'listo')::timestamptz as listo
             from jsonb_array_elements(p_pares) x
  loop
    v_listo := r.listo;
    select * into v_sale from sale s
     where s.account_id = p_account_id
       and s.external_tab_ref = r.tab_id;

    if not found then
      v_res  := 'no hay venta con esa comanda';
      v_nota := format('tabId %s: ninguna venta de esta cuenta lo lleva en external_tab_ref', r.tab_id);
    elsif v_sale.ready_at is not null then
      v_res  := 'ya tenia hora, no se toca';
      v_nota := format('ya tenia ready_at %s; no se pisa', v_sale.ready_at);
    elsif v_sale.accepted_at is not null and v_listo < v_sale.accepted_at then
      v_res  := 'hora imposible: antes de aceptarse';
      v_nota := format('el «Listo» %s es anterior al aceptado %s', v_listo, v_sale.accepted_at);
    elsif v_sale.closed_at is not null and v_listo > v_sale.closed_at then
      v_res  := 'hora imposible: posterior al cierre';
      v_nota := format('el «Listo» %s es posterior al cierre %s', v_listo, v_sale.closed_at);
    else
      -- Solo `ready_at`, y solo si sigue vacio entre la lectura y la escritura.
      update sale set ready_at = v_listo
       where id = v_sale.id and ready_at is null;
      if found then
        v_res  := 'escrito';
        v_nota := format('«Listo» recuperado de %s: %s', p_origen, v_listo);
      else
        v_res  := 'ya tenia hora, no se toca';
        v_nota := 'alguien la escribio entre la lectura y la escritura';
      end if;
    end if;

    insert into public.sello_listo_recuperado_log(
      account_id, sale_id, external_tab_ref, pos_short_code, ready_at_escrito, resultado, nota)
    values (p_account_id, v_sale.id, r.tab_id, v_sale.pos_short_code,
            case when v_res = 'escrito' then v_listo end, v_res, v_nota);

    pos_short_code   := v_sale.pos_short_code;
    external_tab_ref := r.tab_id;
    resultado        := v_res;
    ready_at_escrito := case when v_res = 'escrito' then v_listo end;
    nota             := v_nota;
    return next;
  end loop;
end $$;


--
-- Name: refresh_location_receipt_trust(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_location_receipt_trust(p_location_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_goal       integer;
  v_streak     integer := 0;
  v_total      integer := 0;
  v_corr       integer := 0;
  v_last_corr  timestamptz;
  v_enabled    boolean;
  v_was        boolean;
  r            record;
BEGIN
  IF p_location_id IS NULL THEN RETURN; END IF;
  SELECT account_id INTO v_account_id FROM public.locations WHERE id = p_location_id;
  IF v_account_id IS NULL THEN RETURN; END IF;

  SELECT COALESCE(goal, 30), COALESCE(direct_confirm_enabled, false)
    INTO v_goal, v_was
    FROM public.location_receipt_trust WHERE location_id = p_location_id;
  v_goal := COALESCE(v_goal, 30);
  v_was  := COALESCE(v_was, false);

  FOR r IN
    SELECT gr.id, gr.received_at, gr.receipt_date, gr.created_at,
           EXISTS (SELECT 1 FROM public.goods_receipt_line l
                    WHERE l.goods_receipt_id = gr.id
                      AND l.discrepancy_reason LIKE 'cambio oficina: %'
                      AND NOT COALESCE(l.flagged_for_office, false)) AS corregida
      FROM public.goods_receipt gr
     WHERE gr.location_id = p_location_id
       AND gr.via_assistant
       AND gr.status IN ('recibido', 'confirmado')
     ORDER BY gr.receipt_date DESC, gr.created_at DESC
     LIMIT 200
  LOOP
    v_total := v_total + 1;
    IF r.corregida THEN
      v_corr := v_corr + 1;
      IF v_last_corr IS NULL THEN
        v_last_corr := COALESCE(r.received_at, r.created_at);
      END IF;
    END IF;
    -- la racha solo cuenta hasta la primera corregida empezando por la mas reciente
    IF v_corr = 0 THEN
      v_streak := v_streak + 1;
    END IF;
  END LOOP;

  IF v_streak > v_goal THEN v_streak := v_goal; END IF;
  v_enabled := v_streak >= v_goal;

  INSERT INTO public.location_receipt_trust AS t (
    location_id, account_id, streak, goal, assistant_receipts, corrected_receipts,
    direct_confirm_enabled, enabled_at, last_correction_at, updated_at)
  VALUES (
    p_location_id, v_account_id, v_streak, v_goal, v_total, v_corr,
    v_enabled, CASE WHEN v_enabled THEN now() END, v_last_corr, now())
  ON CONFLICT (location_id) DO UPDATE
    SET streak = EXCLUDED.streak,
        assistant_receipts = EXCLUDED.assistant_receipts,
        corrected_receipts = EXCLUDED.corrected_receipts,
        direct_confirm_enabled = EXCLUDED.direct_confirm_enabled,
        -- se sella cuando se GANA; se borra cuando se pierde
        enabled_at = CASE WHEN EXCLUDED.direct_confirm_enabled
                          THEN COALESCE(t.enabled_at, now()) END,
        last_correction_at = EXCLUDED.last_correction_at,
        account_id = EXCLUDED.account_id,
        updated_at = now();
END;
$$;


--
-- Name: refresh_sales_hourly_agg(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_sales_hourly_agg(p_account uuid, p_from date, p_to date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_rows int;
begin
  delete from public.sales_hourly_agg
  where account_id = p_account and day >= p_from and day <= p_to;

  insert into public.sales_hourly_agg (account_id, location_id, day, hour, demand_kind, units, tickets)
  select s.account_id,
         s.location_id,
         (s.sold_at at time zone 'Europe/Madrid')::date as day,
         extract(hour from (s.sold_at at time zone 'Europe/Madrid'))::smallint as hour,
         coalesce(mc.demand_kind, 'otro') as demand_kind,
         coalesce(sum(sl.quantity), 0) as units,
         count(distinct s.id) as tickets
  from public.sale s
  join public.sale_line sl on sl.sale_id = s.id
  join public.menu_item mi on mi.id = sl.menu_item_id
  join public.menu_category mc on mc.id = mi.menu_category_id
  where s.account_id = p_account
    and coalesce(s.is_active, true)
    and (s.sold_at at time zone 'Europe/Madrid')::date >= p_from
    and (s.sold_at at time zone 'Europe/Madrid')::date <= p_to
  group by 1,2,3,4,5;

  get diagnostics v_rows = row_count;
  return v_rows;
end $$;


--
-- Name: refresh_supplier_proposals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_supplier_proposals(p_supplier_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  s   supplier%rowtype;
  doc jsonb;
  src text; src_id uuid; src_label text;
  n   integer := 0;
begin
  select * into s from supplier where id = p_supplier_id;
  if not found then return 0; end if;

  -- La primera lectura: factura antes que albarán, la más antigua.
  select g.parsed_result -> 'document', x.src, x.src_id, x.lbl
    into doc, src, src_id, src_label
  from (
    select 'supplier_invoice'::text src, i.id src_id, i.ai_session_id ses,
           'Leído de su factura ' || coalesce(i.invoice_number, i.code, '') lbl, i.created_at t, 1 prio
    from supplier_invoice i where i.supplier_id = s.id and i.account_id = s.account_id and i.ai_session_id is not null
    union all
    select 'goods_receipt', r.id, r.ai_session_id,
           'Leído de su albarán ' || coalesce(r.supplier_doc_number, r.code, ''), r.created_at, 2
    from goods_receipt r where r.supplier_id = s.id and r.account_id = s.account_id and r.ai_session_id is not null
  ) x
  join goods_receipt_ai_session g on g.id = x.ses and g.account_id = s.account_id
  order by x.prio, x.t
  limit 1;

  if doc is null then return 0; end if;

  if coalesce(trim(s.tax_id), '') = '' and coalesce(trim(doc ->> 'supplier_tax_id'), '') <> '' then
    insert into supplier_proposal (account_id, supplier_id, field, value, source, source_id, source_label)
    values (s.account_id, s.id, 'tax_id', to_jsonb(trim(doc ->> 'supplier_tax_id')), src, src_id, trim(src_label))
    on conflict do nothing;
    get diagnostics n = row_count;
  end if;
  if coalesce(trim(s.legal_name), '') = '' and coalesce(trim(doc ->> 'supplier_name'), '') <> '' then
    insert into supplier_proposal (account_id, supplier_id, field, value, source, source_id, source_label)
    values (s.account_id, s.id, 'legal_name', to_jsonb(trim(doc ->> 'supplier_name')), src, src_id, trim(src_label))
    on conflict do nothing;
  end if;
  if coalesce(trim(s.fiscal_street), '') = '' and coalesce(trim(doc ->> 'supplier_address'), '') <> '' then
    -- La dirección va en una línea; el reparto lo propone el núcleo
    -- (proponerDireccion) al enseñarla, y la persona confirma.
    insert into supplier_proposal (account_id, supplier_id, field, value, source, source_id, source_label)
    values (s.account_id, s.id, 'fiscal_address', jsonb_build_object('line', trim(doc ->> 'supplier_address')), src, src_id, trim(src_label))
    on conflict do nothing;
  end if;
  select count(*) into n from supplier_proposal where supplier_id = s.id and status = 'pending';
  return n;
end $$;


--
-- Name: regenerate_social_copy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regenerate_social_copy(p_post_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_cur text; p jsonb; v_pillar text; v_plato text; v_marca text;
        v_anon boolean; v_tpl text; v_new text; v_pct numeric;
begin
  select account_id, status, payload into v_acc, v_cur, p from social_post where id = p_post_id;
  if v_acc is null then raise exception 'post no encontrado'; end if;
  if not current_user_is_admin_or_manager_of(v_acc) then raise exception 'no autorizado'; end if;
  if v_cur in ('publishing','published') then raise exception 'no en este estado'; end if;

  v_anon  := coalesce((p->>'brand_anonymous')::boolean, false);
  v_tpl   := coalesce(p->>'template', 'apetito');
  v_plato := coalesce(p->>'star_item', '');
  v_marca := coalesce(p->>'brand_name', '');
  v_pillar := case when v_anon then 'cedida'
                   when v_tpl = 'oferta' then 'oferta'
                   when v_tpl = 'curiosidad' then 'curiosidad'
                   else 'apetito' end;

  v_new := public.pick_social_copy(v_pillar, v_acc);
  if v_new is null then v_new := '{plato} — pídelo en foodint.es 🔥'; end if;

  select c.value into v_pct from coupon c where c.id = nullif(p->>'coupon_id','')::uuid;
  v_new := replace(replace(replace(v_new, '{plato}', v_plato), '{marca}', v_marca),
                   '{pct}', coalesce(v_pct::text, ''));

  update social_post set payload = jsonb_set(payload, '{copy}', to_jsonb(v_new)), updated_at = now()
   where id = p_post_id;
  return v_new;
end $$;


--
-- Name: register_adjustment(uuid, uuid, uuid, text, numeric, text, numeric, numeric, text, text, date, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_adjustment(p_account_id uuid, p_location_id uuid, p_recipe_item_id uuid, p_reason_code text, p_counted_base numeric, p_use_unit_label text DEFAULT NULL::text, p_use_unit_factor numeric DEFAULT NULL::numeric, p_use_qty numeric DEFAULT NULL::numeric, p_photo_url text DEFAULT NULL::text, p_lot_code text DEFAULT NULL::text, p_expiry_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_user_name text DEFAULT NULL::text) RETURNS TABLE(adjustment_id uuid, delta_base numeric, cost_eur numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_account uuid;
  v_previous     numeric;
  v_unit_cost    numeric;
  v_delta        numeric;
  v_cost_eur     numeric;
  v_adj_id       uuid;
begin
  -- Guard: el usuario debe pertenecer a la cuenta.
  if not belongs_to_account(p_account_id) then
    raise exception 'register_adjustment: sin acceso a la cuenta %', p_account_id;
  end if;
  -- El conteo real no puede ser negativo (si puede ser 0 = "no queda nada").
  if p_counted_base is null or p_counted_base < 0 then
    raise exception 'register_adjustment: el conteo debe ser >= 0';
  end if;
  if p_reason_code is null or length(trim(p_reason_code)) = 0 then
    raise exception 'register_adjustment: el motivo es obligatorio';
  end if;
  -- El articulo debe existir y pertenecer a la cuenta.
  select account_id into v_item_account
    from public.recipe_item where id = p_recipe_item_id;
  if v_item_account is null then
    raise exception 'register_adjustment: el articulo % no existe', p_recipe_item_id;
  end if;
  if v_item_account <> p_account_id then
    raise exception 'register_adjustment: el articulo no pertenece a la cuenta';
  end if;

  -- Saldo actual y WAC del instante (0/NULL si el articulo aun no tiene fila/coste).
  select coalesce(qty_on_hand, 0), coalesce(avg_unit_cost, 0)
    into v_previous, v_unit_cost
    from public.recipe_item_location_stock
    where recipe_item_id = p_recipe_item_id
      and location_id = p_location_id
      and account_id = p_account_id;
  v_previous  := coalesce(v_previous, 0);
  v_unit_cost := coalesce(v_unit_cost, 0);

  v_delta    := p_counted_base - v_previous;     -- movimiento con signo
  v_cost_eur := v_delta * v_unit_cost;

  -- ── 23/09/2026 · BAJAR STOCK EXIGE DECIR POR QUE ────────────────────────
  -- Solo a la BAJA. Al alza no se toca nada: no es la fuga, y la friccion
  -- solo conseguiria que se dejaran de hacer.
  --
  -- Medido antes de escribir esto, Alcala, 30 dias: de los 8 ajustes a la
  -- baja de esta pantalla, SEIS eran correcciones de UNIDAD sin una linea de
  -- explicacion (55.000 bolsas -> 200; 1.440 latas -> 60, que es 60 x 24) por
  -- 29.622,09 EUR. No eran perdidas: era stock fantasma. Pero desde la base
  -- un -8.891 sin nota es la MISMA FILA que una perdida real. Esto no tapa
  -- una fuga: hace que el residuo deje de poder explicarse en falso.
  if v_delta < 0 then
    if p_reason_code in ('waste', 'expired') then
      raise exception
        'register_adjustment: «%» es una merma y va por register_waste, no por aqui. '
        'Si sale por merma tiene que contar como merma, o el almacen dice que la '
        'merma es cero mientras se tira comida.', p_reason_code
        using errcode = 'check_violation';
    end if;

    if p_reason_code = 'other' then
      raise exception
        'register_adjustment: para bajar stock hace falta un motivo de verdad. '
        '«Otro» no dice nada y el mes que viene nadie sabra que paso.'
        using errcode = 'check_violation';
    end if;

    -- La que muerde: habria cazado las seis.
    if p_reason_code = 'count_correction'
       and length(btrim(coalesce(p_notes, ''))) < 10 then
      raise exception
        'register_adjustment: una correccion de conteo a la baja necesita nota '
        '(minimo 10 caracteres). Sin ella no se distingue de una perdida.'
        using errcode = 'check_violation';
    end if;
  end if;

  -- Sin cambio real: no escribimos ruido en el ledger.
  if v_delta = 0 then
    insert into public.stock_adjustment (
      account_id, location_id, recipe_item_id, reason_code,
      counted_base, previous_base, delta_base,
      use_unit_label, use_unit_factor, use_qty,
      unit_cost, cost_eur, photo_url, lot_code, expiry_date, notes,
      occurred_at, created_by, created_by_name
    ) values (
      p_account_id, p_location_id, p_recipe_item_id, p_reason_code,
      p_counted_base, v_previous, 0,
      p_use_unit_label, p_use_unit_factor, p_use_qty,
      v_unit_cost, 0, p_photo_url, p_lot_code, p_expiry_date, p_notes,
      now(), p_user_id, p_user_name
    ) returning id into v_adj_id;
    return query select v_adj_id, 0::numeric, 0::numeric;
    return;
  end if;

  -- 1) Evento de ajuste.
  insert into public.stock_adjustment (
    account_id, location_id, recipe_item_id, reason_code,
    counted_base, previous_base, delta_base,
    use_unit_label, use_unit_factor, use_qty,
    unit_cost, cost_eur, photo_url, lot_code, expiry_date, notes,
    occurred_at, created_by, created_by_name
  ) values (
    p_account_id, p_location_id, p_recipe_item_id, p_reason_code,
    p_counted_base, v_previous, v_delta,
    p_use_unit_label, p_use_unit_factor, p_use_qty,
    v_unit_cost, v_cost_eur, p_photo_url, p_lot_code, p_expiry_date, p_notes,
    now(), p_user_id, p_user_name
  ) returning id into v_adj_id;

  -- 2) Movimiento al ledger.
  insert into public.stock_movement (
    account_id, location_id, recipe_item_id, movement_type, qty_base,
    unit_cost, cost_provisional, source_type, source_id, occurred_at,
    lot_code, expiry_date, created_by, created_by_name, notes
  ) values (
    p_account_id, p_location_id, p_recipe_item_id, 'ajuste', v_delta,
    v_unit_cost, false, 'adjustment', v_adj_id, now(),
    p_lot_code, p_expiry_date, p_user_id, p_user_name,
    coalesce('Ajuste: ' || p_reason_code, 'Ajuste')
  );

  -- 3) Recalcular el saldo del articulo en el local.
  perform public.recompute_location_stock_core(p_recipe_item_id, p_location_id);

  return query select v_adj_id, v_delta, v_cost_eur;
end;
$$;


--
-- Name: register_shop_consent(text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_shop_consent(p_slug text, p_email text, p_name text, p_phone text, p_consent boolean, p_terms_version text DEFAULT 'shop-privacy-v1'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc      uuid;
  v_email    text;
  v_phone    text;
  v_name     text;
  v_customer uuid;
  v_prev     boolean;
begin
  select id into v_acc from accounts where slug = p_slug;
  if v_acc is null then
    return jsonb_build_object('ok', false, 'reason', 'account');
  end if;

  v_email := lower(nullif(btrim(p_email), ''));
  v_phone := nullif(btrim(p_phone), '');
  v_name  := nullif(btrim(p_name),  '');

  -- Regla de hierro: sin email válido no se guarda nada.
  if v_email is null or position('@' in v_email) = 0 or position('.' in v_email) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'needs_email');
  end if;

  -- Dedup igual que place_shop_order: email -> phone.
  select id into v_customer from customer
  where account_id = v_acc and lower(email) = v_email limit 1;
  if v_customer is null and v_phone is not null then
    select id into v_customer from customer
    where account_id = v_acc and phone = v_phone limit 1;
  end if;

  if not coalesce(p_consent, false) then
    -- Desmarcar: si el cliente no existe, NO se crea nada (sin registro sin acción
    -- afirmativa). Si existe y estaba consentido, se revoca + log.
    if v_customer is null then
      return jsonb_build_object('ok', true, 'consented', false);
    end if;
    select marketing_email into v_prev from customer_consent where customer_id = v_customer;
    if coalesce(v_prev, false) then
      update customer_consent set marketing_email = false, updated_at = now()
      where customer_id = v_customer;
      insert into customer_consent_log (customer_id, account_id, action, channel, source, terms_version)
      values (v_customer, v_acc, 'revoked', 'email', 'shop_checkbox', p_terms_version);
    end if;
    return jsonb_build_object('ok', true, 'consented', false);
  end if;

  -- consent = true (acción afirmativa): crear/actualizar el cliente.
  if v_customer is null then
    insert into customer (account_id, email, phone, name)
    values (v_acc, v_email, v_phone, v_name)
    returning id into v_customer;
  else
    update customer set
      email        = coalesce(email, v_email),
      phone        = coalesce(phone, v_phone),
      name         = coalesce(name,  v_name),
      last_seen_at = now(),
      updated_at   = now()
    where id = v_customer;
  end if;

  -- Upsert consent + log SOLO si antes no estaba consentido (idempotente).
  select marketing_email into v_prev from customer_consent where customer_id = v_customer;
  if not coalesce(v_prev, false) then
    insert into customer_consent (customer_id, account_id, marketing_email, updated_at)
    values (v_customer, v_acc, true, now())
    on conflict (customer_id) do update set marketing_email = true, updated_at = now();
    insert into customer_consent_log (customer_id, account_id, action, channel, source, terms_version)
    values (v_customer, v_acc, 'granted', 'email', 'shop_checkbox', p_terms_version);
  end if;

  return jsonb_build_object('ok', true, 'consented', true, 'customerId', v_customer);
end;
$$;


--
-- Name: register_transfer(uuid, uuid, uuid, uuid, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_transfer(p_account_id uuid, p_from_location uuid, p_to_location uuid, p_recipe_item_id uuid, p_qty_base numeric, p_notes text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_user_name text DEFAULT NULL::text) RETURNS TABLE(transfer_id uuid, cost_eur numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_account uuid;
  v_unit_cost    numeric;
  v_cost_eur     numeric;
  v_avail        numeric;
  v_transfer_id  uuid;
begin
  if not belongs_to_account(p_account_id) then
    raise exception 'register_transfer: sin acceso a la cuenta %', p_account_id;
  end if;
  if p_qty_base is null or p_qty_base <= 0 then
    raise exception 'register_transfer: la cantidad debe ser mayor que 0';
  end if;
  if p_from_location = p_to_location then
    raise exception 'register_transfer: origen y destino no pueden ser el mismo local';
  end if;

  select account_id into v_item_account from public.recipe_item where id = p_recipe_item_id;
  if v_item_account is null then
    raise exception 'register_transfer: el artículo % no existe', p_recipe_item_id;
  end if;
  if v_item_account <> p_account_id then
    raise exception 'register_transfer: el artículo no pertenece a la cuenta';
  end if;

  -- WAC y saldo del origen.
  select coalesce(avg_unit_cost, 0), coalesce(qty_on_hand, 0)
    into v_unit_cost, v_avail
    from public.recipe_item_location_stock
    where recipe_item_id = p_recipe_item_id
      and location_id = p_from_location
      and account_id = p_account_id;
  v_unit_cost := coalesce(v_unit_cost, 0);
  v_avail := coalesce(v_avail, 0);
  if p_qty_base > v_avail then
    raise exception 'register_transfer: no hay stock suficiente en origen (disponible %, pedido %)', v_avail, p_qty_base;
  end if;

  v_cost_eur := p_qty_base * v_unit_cost;

  insert into public.stock_transfer(
    account_id, from_location_id, to_location_id, recipe_item_id,
    qty_base, unit_cost, cost_eur, notes, occurred_at, created_by, created_by_name
  ) values (
    p_account_id, p_from_location, p_to_location, p_recipe_item_id,
    p_qty_base, v_unit_cost, v_cost_eur, p_notes, now(), p_user_id, p_user_name
  ) returning id into v_transfer_id;

  -- Salida del origen.
  insert into public.stock_movement(
    account_id, location_id, recipe_item_id, movement_type, qty_base,
    unit_cost, cost_provisional, source_type, source_id, occurred_at,
    created_by, created_by_name, notes
  ) values (
    p_account_id, p_from_location, p_recipe_item_id, 'traspaso_salida', -p_qty_base,
    v_unit_cost, false, 'transfer', v_transfer_id, now(),
    p_user_id, p_user_name, coalesce('Traspaso: ' || p_notes, 'Traspaso')
  );

  -- Entrada en el destino (con el coste del origen).
  insert into public.stock_movement(
    account_id, location_id, recipe_item_id, movement_type, qty_base,
    unit_cost, cost_provisional, source_type, source_id, occurred_at,
    created_by, created_by_name, notes
  ) values (
    p_account_id, p_to_location, p_recipe_item_id, 'traspaso_entrada', p_qty_base,
    v_unit_cost, false, 'transfer', v_transfer_id, now(),
    p_user_id, p_user_name, coalesce('Traspaso: ' || p_notes, 'Traspaso')
  );

  -- Recalcular ambos saldos.
  perform public.recompute_location_stock_core(p_recipe_item_id, p_from_location);
  perform public.recompute_location_stock_core(p_recipe_item_id, p_to_location);

  return query select v_transfer_id, v_cost_eur;
end;
$$;


--
-- Name: register_waste(uuid, uuid, uuid, text, numeric, text, numeric, numeric, text, text, date, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_waste(p_account_id uuid, p_location_id uuid, p_recipe_item_id uuid, p_reason_code text, p_qty_base numeric, p_use_unit_label text DEFAULT NULL::text, p_use_unit_factor numeric DEFAULT NULL::numeric, p_use_qty numeric DEFAULT NULL::numeric, p_photo_url text DEFAULT NULL::text, p_lot_code text DEFAULT NULL::text, p_expiry_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_user_name text DEFAULT NULL::text) RETURNS TABLE(waste_id uuid, cost_eur numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item_account uuid;
  v_unit_cost numeric;
  v_cost_eur numeric;
  v_waste_id uuid;
BEGIN
  -- Guard: el usuario debe pertenecer a la cuenta.
  IF NOT belongs_to_account(p_account_id) THEN
    RAISE EXCEPTION 'register_waste: sin acceso a la cuenta %', p_account_id;
  END IF;

  -- Validaciones básicas.
  IF p_qty_base IS NULL OR p_qty_base <= 0 THEN
    RAISE EXCEPTION 'register_waste: la cantidad debe ser mayor que 0';
  END IF;

  -- El artículo debe existir y pertenecer a la cuenta (coherencia multi-tenant).
  SELECT account_id INTO v_item_account
    FROM public.recipe_item WHERE id = p_recipe_item_id;
  IF v_item_account IS NULL THEN
    RAISE EXCEPTION 'register_waste: el artículo % no existe', p_recipe_item_id;
  END IF;
  IF v_item_account <> p_account_id THEN
    RAISE EXCEPTION 'register_waste: el artículo no pertenece a la cuenta';
  END IF;

  -- WAC del instante (mismo origen que el ajuste de conteo). Puede ser 0/NULL si
  -- el artículo aún no tiene coste: la merma se registra igual (coste 0), no se inventa.
  SELECT COALESCE(avg_unit_cost, 0) INTO v_unit_cost
    FROM public.recipe_item_location_stock
    WHERE recipe_item_id = p_recipe_item_id
      AND location_id = p_location_id
      AND account_id = p_account_id;
  v_unit_cost := COALESCE(v_unit_cost, 0);
  v_cost_eur := p_qty_base * v_unit_cost;

  -- 1) Evento de merma (cabecera con causa, unidad amigable, foto, lote).
  INSERT INTO public.stock_waste (
    account_id, location_id, recipe_item_id, reason_code,
    qty_base, use_unit_label, use_unit_factor, use_qty,
    unit_cost, cost_eur, photo_url, lot_code, expiry_date, notes,
    occurred_at, created_by, created_by_name
  ) VALUES (
    p_account_id, p_location_id, p_recipe_item_id, p_reason_code,
    p_qty_base, p_use_unit_label, p_use_unit_factor, p_use_qty,
    v_unit_cost, v_cost_eur, p_photo_url, p_lot_code, p_expiry_date, p_notes,
    now(), p_user_id, p_user_name
  )
  RETURNING id INTO v_waste_id;

  -- 2) Movimiento al ledger: SALIDA (qty negativa), tipo 'merma', apunta al evento.
  INSERT INTO public.stock_movement (
    account_id, location_id, recipe_item_id, movement_type, qty_base,
    unit_cost, cost_provisional, source_type, source_id, occurred_at,
    lot_code, expiry_date, created_by, created_by_name, notes
  ) VALUES (
    p_account_id, p_location_id, p_recipe_item_id, 'merma', -p_qty_base,
    v_unit_cost, false, 'waste', v_waste_id, now(),
    p_lot_code, p_expiry_date, p_user_id, p_user_name,
    COALESCE('Merma: ' || p_reason_code, 'Merma')
  );

  -- 3) Recalcular el saldo del artículo en el local.
  PERFORM public.recompute_location_stock(p_recipe_item_id, p_location_id);

  RETURN QUERY SELECT v_waste_id, v_cost_eur;
END;
$$;


--
-- Name: registro_jornada_mensual(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registro_jornada_mensual(p_employee_id uuid, p_from date, p_to date) RETURNS TABLE(dia date, entrada timestamp with time zone, salida timestamp with time zone, minutos_trabajados numeric, minutos_pausa numeric, minutos_nocturnos numeric, es_festivo boolean, festivo_nombre text, ausencia_tipo text)
    LANGUAGE sql STABLE
    AS $$
  with dias as (
    select generate_series(p_from, p_to, interval '1 day')::date as d
  ),
  acc as (select account_id, location_id from public.employees where id = p_employee_id),
  jor as (
    select (w.started_at at time zone 'Europe/Madrid')::date as d,
           w.started_at, w.ended_at, w.minutes, w.break_minutes,
           public.night_minutes_in_span(w.started_at, w.ended_at) as night
    from public.team_worked_shifts((select account_id from acc),
           p_from::timestamptz, (p_to + 1)::timestamptz) w
    where w.employee_id = p_employee_id
  ),
  fest as (
    select h.holiday_date, h.name from public.holiday_calendar h
    where (h.account_id is null or h.account_id = (select account_id from acc))
      and h.holiday_date between p_from and p_to
  ),
  aus as (
    select v.start_date, v.end_date, v.type from public.vacations v
    where v.employee_id = p_employee_id and v.status = 'aprobada'
      and v.start_date <= p_to and v.end_date >= p_from
  )
  select dias.d,
         j.started_at, j.ended_at,
         coalesce(j.minutes, 0), coalesce(j.break_minutes, 0), coalesce(j.night, 0),
         (f.holiday_date is not null), f.name,
         (select a.type from aus a where dias.d between a.start_date and a.end_date limit 1)
  from dias
  left join jor j on j.d = dias.d
  left join fest f on f.holiday_date = dias.d
  order by dias.d;
$$;


--
-- Name: registro_jornada_totales(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registro_jornada_totales(p_employee_id uuid, p_from date, p_to date) RETURNS TABLE(dias_trabajados integer, tramos integer, horas_trabajadas numeric, horas_pausa numeric, horas_nocturnas numeric, dias_vacaciones integer, dias_baja integer, dias_festivo_trabajado integer, horas_contratadas numeric, delta_horas numeric)
    LANGUAGE sql STABLE
    AS $$
  with r as (select * from public.registro_jornada_mensual(p_employee_id, p_from, p_to)),
       b as (select * from public.compute_employee_balance(p_employee_id, p_from, p_to))
  select
    (select count(distinct dia)::int from r where entrada is not null),
    (select count(*)::int from r where entrada is not null),
    (select round(coalesce(sum(minutos_trabajados),0)/60.0, 2) from r),
    (select round(coalesce(sum(minutos_pausa),0)/60.0, 2) from r),
    (select round(coalesce(sum(minutos_nocturnos),0)/60.0, 2) from r),
    (select count(distinct dia)::int from r where ausencia_tipo = 'vacaciones'),
    (select count(distinct dia)::int from r where ausencia_tipo = 'baja_medica'),
    (select count(distinct dia)::int from r where es_festivo and entrada is not null),
    (select contracted_hours from b),
    (select delta_hours from b);
$$;


--
-- Name: release_next_phase(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_next_phase(p_employee_id uuid, p_path_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_uid uuid := auth.uid();
  v_next_phase text;
begin
  select l.account_id into v_account_id
  from public.employees e
  join public.locations l on l.id = e.location_id
  where e.id = p_employee_id;
  if v_account_id is null then
    raise exception 'release_next_phase: no se pudo resolver la cuenta del empleado';
  end if;
  if not (public.current_user_is_admin_or_manager_of(v_account_id) or public.current_user_is_admin()) then
    raise exception 'release_next_phase: sin acceso a la cuenta %', v_account_id;
  end if;

  select pp.phase into v_next_phase
  from public.training_path_progress pp
  where pp.employee_id = p_employee_id and pp.path_id = p_path_id and pp.state = 'pendiente'
  order by case pp.phase when 'dia_1' then 0 when 'dias_30' then 1 when 'dias_90' then 2 else 3 end
  limit 1;

  if v_next_phase is null then
    raise exception 'release_next_phase: no hay ninguna fase pendiente que liberar para este itinerario';
  end if;

  return public.release_specific_phase(p_employee_id, p_path_id, v_next_phase, v_uid);
end;
$$;


--
-- Name: release_overdue_phases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_overdue_phases() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
  v_next_phase text;
  v_count integer := 0;
begin
  for r in
    select pp.employee_id, pp.path_id
    from public.training_path_progress pp
    join public.training_path tp on tp.id = pp.path_id
    where pp.state = 'liberada'
      and tp.auto_release = true
      and pp.released_at is not null
      and greatest(pp.due_at, pp.released_at + interval '7 days') < now()
      and exists (
        select 1 from public.training_path_progress pp2
        where pp2.employee_id = pp.employee_id and pp2.path_id = pp.path_id and pp2.state = 'pendiente'
      )
  loop
    begin
      select pp3.phase into v_next_phase
      from public.training_path_progress pp3
      where pp3.employee_id = r.employee_id and pp3.path_id = r.path_id and pp3.state = 'pendiente'
      order by case pp3.phase when 'dia_1' then 0 when 'dias_30' then 1 when 'dias_90' then 2 else 3 end
      limit 1;

      if v_next_phase is not null then
        perform public.release_specific_phase(r.employee_id, r.path_id, v_next_phase, null);
        v_count := v_count + 1;
      end if;
    exception when others then
      raise warning 'release_overdue_phases: fallo con empleado % itinerario %: %', r.employee_id, r.path_id, sqlerrm;
    end;
  end loop;

  return v_count;
end;
$$;


--
-- Name: release_phase_for_group(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_phase_for_group(p_account_id uuid, p_path_id uuid, p_phase text, p_location_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_emp record;
  v_result jsonb;
  v_released integer := 0;
  v_already integer := 0;
begin
  if not (public.current_user_is_admin_or_manager_of(p_account_id) or public.current_user_is_admin()) then
    raise exception 'release_phase_for_group: sin acceso a la cuenta %', p_account_id;
  end if;
  if p_location_id is null and p_role is null then
    raise exception 'release_phase_for_group: indica al menos local o puesto';
  end if;

  for v_emp in
    select e.id
    from public.employees e
    join public.locations l on l.id = e.location_id
    where e.active = true
      and l.account_id = p_account_id
      and (p_location_id is null or e.location_id = p_location_id)
      and (p_role is null or e.position = p_role)
      and exists (
        select 1 from public.training_path_progress pp
        where pp.employee_id = e.id and pp.path_id = p_path_id and pp.phase = p_phase
      )
  loop
    begin
      v_result := public.release_specific_phase(v_emp.id, p_path_id, p_phase, v_uid);
      if coalesce((v_result ->> 'alreadyReleased')::boolean, false) then
        v_already := v_already + 1;
      else
        v_released := v_released + 1;
      end if;
    exception when others then
      raise warning 'release_phase_for_group: fallo con empleado %: %', v_emp.id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object('released', v_released, 'alreadyReleased', v_already, 'totalMatching', v_released + v_already);
end;
$$;


--
-- Name: release_specific_phase(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_specific_phase(p_employee_id uuid, p_path_id uuid, p_phase text, p_released_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_progress record;
  v_count integer := 0;
  v_account_id uuid;
  v_caller_employee_id uuid;
begin
  select l.account_id into v_account_id
  from public.employees e join public.locations l on l.id = e.location_id
  where e.id = p_employee_id;

  if auth.uid() is not null then
    select employee_id into v_caller_employee_id from public.current_employee_and_account();
    if not (
      coalesce(v_caller_employee_id = p_employee_id, false)
      or public.current_user_is_admin_or_manager_of(v_account_id)
      or public.current_user_is_admin()
    ) then
      raise exception 'release_specific_phase: sin acceso';
    end if;
  end if;

  select * into v_progress
  from public.training_path_progress pp
  where pp.employee_id = p_employee_id and pp.path_id = p_path_id and pp.phase = p_phase;

  if v_progress.id is null then
    raise exception 'release_specific_phase: no existe progreso para empleado %, itinerario %, fase %', p_employee_id, p_path_id, p_phase;
  end if;

  if v_progress.state <> 'pendiente' then
    return jsonb_build_object('phase', p_phase, 'state', v_progress.state, 'alreadyReleased', true, 'assignmentsCreated', 0);
  end if;

  update public.training_path_progress
  set state = 'liberada', released_at = now(), released_by = p_released_by, updated_at = now()
  where id = v_progress.id;

  v_count := public.sync_phase_assignments(p_employee_id, p_path_id, p_phase);

  return jsonb_build_object('phase', p_phase, 'state', 'liberada', 'alreadyReleased', false, 'assignmentsCreated', v_count);
end;
$$;


--
-- Name: remove_ingredient_from_recipes(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_ingredient_from_recipes(p_source uuid, p_parents uuid[]) RETURNS TABLE(removed integer, affected_item_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_acc uuid; v_removed int; v_affected uuid[];
BEGIN
  SELECT account_id INTO v_acc FROM recipe_item WHERE id = p_source;
  IF v_acc IS NULL OR NOT (v_acc = ANY (current_user_account_ids())) THEN
    RAISE EXCEPTION 'remove_ingredient_from_recipes: origen no accesible';
  END IF;
  IF p_parents IS NULL OR array_length(p_parents,1) IS NULL THEN
    RETURN QUERY SELECT 0, '{}'::uuid[]; RETURN;
  END IF;

  SELECT array_agg(DISTINCT parent_item_id) INTO v_affected
  FROM recipe_line
  WHERE child_item_id = p_source AND account_id = v_acc AND parent_item_id = ANY(p_parents);

  WITH del AS (
    DELETE FROM recipe_line
    WHERE child_item_id = p_source AND account_id = v_acc AND parent_item_id = ANY(p_parents)
    RETURNING 1
  )
  SELECT count(*)::int INTO v_removed FROM del;

  RETURN QUERY SELECT v_removed, COALESCE(v_affected, '{}'::uuid[]);
END;
$$;


--
-- Name: reparto_award_quests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_award_quests() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into courier_bonus_award(account_id, courier_id, bonus_id, period_key, reward)
  select qb.account_id, c.id, qb.id,
    case qb.period
      when 'day' then 'd:'||to_char((now() at time zone 'Europe/Madrid')::date, 'YYYY-MM-DD')
      else 'w:'||to_char((now() at time zone 'Europe/Madrid'), 'IYYY-"W"IW')
    end,
    qb.reward
  from courier c
  join courier_bonus qb on qb.account_id = c.account_id and qb.is_active
    and (qb.valid_from is null or (now() at time zone 'Europe/Madrid')::date >= qb.valid_from)
    and (qb.valid_to   is null or (now() at time zone 'Europe/Madrid')::date <= qb.valid_to)
    and (qb.location_id is null or c.assigned_locations = '{}'::uuid[] or qb.location_id = any(c.assigned_locations))
  where c.active
    and (
      select count(*) from delivery_assignment da
      where da.courier_id = c.id and da.state = 'delivered'
        and da.delivered_at >= (case qb.period
              when 'day' then (date_trunc('day',  now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid'
              else            (date_trunc('week', now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid' end)
        and (qb.location_id is null or da.location_id = qb.location_id)
    ) >= qb.target_count
  on conflict (courier_id, bonus_id, period_key) do nothing;
$$;


--
-- Name: reparto_cambiar_desde_pedido(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_cambiar_desde_pedido(p_sale_id uuid, p_delivery_by text) RETURNS TABLE(delivery_by text, source text, service_type text, channel_slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale record;
  v_slug text;
begin
  select s.id, s.account_id, s.brand_id, s.channel_id, s.status
    into v_sale from public.sale s where s.id = p_sale_id;
  if v_sale.id is null then
    raise exception 'Pedido no encontrado' using errcode = 'P0002';
  end if;
  if not public.current_user_is_admin_or_manager_of(v_sale.account_id) then
    raise exception 'Solo un administrador o encargado de la cuenta puede decidir quién reparte'
      using errcode = '42501';
  end if;
  if v_sale.brand_id is null then
    raise exception 'Este pedido no tiene marca: no se puede decidir quién lo reparte' using errcode = '23514';
  end if;
  select sc.slug into v_slug from public.sales_channel sc
   where sc.id = v_sale.channel_id and sc.account_id = v_sale.account_id;
  if coalesce(btrim(v_slug), '') = '' then
    raise exception 'Este pedido no tiene plataforma: no se puede decidir quién lo reparte' using errcode = '23514';
  end if;

  perform public.reparto_guardar_celda(v_sale.account_id, v_sale.brand_id, v_slug, null, p_delivery_by, 'manual');

  -- Recolocar ESTE pedido con la resolución nueva (el disparador de entrada
  -- solo recalcula un pedido abierto si se le pide a propósito).
  perform set_config('folvy.reparto_recalcular', 'on', true);
  update public.sale s
     set updated_at = now(),
         -- Si ya no lo repartimos nosotros, el motivo viejo deja de valer.
         dispatch_error = case when p_delivery_by = 'platform' then null else s.dispatch_error end,
         delivery_alarm_at = case when p_delivery_by = 'platform' and s.delivery_alarm_kind = 'no_despachado'
                                  then null else s.delivery_alarm_at end,
         delivery_alarm_kind = case when p_delivery_by = 'platform' and s.delivery_alarm_kind = 'no_despachado'
                                    then null else s.delivery_alarm_kind end
   where s.id = p_sale_id;
  perform set_config('folvy.reparto_recalcular', '', true);

  return query
    select r.delivery_by, r.source, s.service_type, v_slug
      from public.sale s
      cross join lateral public.resolve_delivery_by(s.account_id, s.brand_id, v_slug, s.location_id) r
     where s.id = p_sale_id;
end;
$$;


--
-- Name: reparto_fleet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_fleet() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id, 'name', c.name, 'transport_type', c.transport_type,
    'lat', c.last_lat, 'lng', c.last_lng, 'seen_at', c.last_seen_at,
    'status', case when da.id is not null then da.state else 'free' end,
    'order_code', coalesce(s.platform_order_code, s.external_ref, left(s.id::text,8)),
    'pickup_lat', l.lat, 'pickup_lng', l.lng
  ) order by c.name), '[]'::jsonb)
  from courier c
  left join lateral (
    select da2.* from delivery_assignment da2
    where da2.courier_id = c.id and da2.state in ('accepted','picked_up','in_delivery')
    order by da2.accepted_at desc limit 1
  ) da on true
  left join sale s on s.id = da.sale_id
  left join locations l on l.id = da.location_id
  where c.account_id = any(current_user_account_ids())
    and belongs_to_account(c.account_id)
    and c.active and c.on_shift;
$$;


--
-- Name: reparto_guardar_celda(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_guardar_celda(p_account_id uuid, p_brand_id uuid, p_channel_slug text, p_location_id uuid, p_delivery_by text, p_source text DEFAULT 'manual'::text) RETURNS TABLE(delivery_by text, source text, decided_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_local uuid := coalesce(p_location_id, '00000000-0000-0000-0000-000000000000'::uuid);
begin
  if not public.current_user_is_admin_or_manager_of(p_account_id) then
    raise exception 'Solo un administrador o encargado de la cuenta puede decidir quién reparte'
      using errcode = '42501';
  end if;
  if p_delivery_by is not null and p_delivery_by not in ('platform', 'own') then
    raise exception 'Quién reparte: «%» no es ni platform ni own', p_delivery_by using errcode = '22023';
  end if;
  if p_source not in ('manual', 'ai_accepted') then
    raise exception 'Quién reparte: origen «%» no válido desde la pantalla', p_source using errcode = '22023';
  end if;

  if p_delivery_by is null then
    delete from public.brand_delivery_policy p
     where p.account_id = p_account_id and p.brand_id = p_brand_id
       and p.channel_slug = p_channel_slug and p.location_id = v_local;
  else
    insert into public.brand_delivery_policy as p
      (account_id, brand_id, channel_slug, location_id, delivery_by, source, decided_by, decided_by_name, decided_at)
    values
      (p_account_id, p_brand_id, p_channel_slug, v_local, p_delivery_by, p_source,
       auth.uid(), public.conta_nombre_actor(), now())
    on conflict (account_id, brand_id, channel_slug, location_id) do update
      set delivery_by     = excluded.delivery_by,
          source          = excluded.source,
          decided_by      = excluded.decided_by,
          decided_by_name = excluded.decided_by_name,
          decided_at      = excluded.decided_at;
  end if;

  return query
    select r.delivery_by, r.source, r.decided_at
      from public.resolve_delivery_by(p_account_id, p_brand_id, p_channel_slug,
             case when v_local = '00000000-0000-0000-0000-000000000000'::uuid then null else v_local end) r;
end;
$$;


--
-- Name: reparto_guardar_herencia(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_guardar_herencia(p_account_id uuid, p_channel_slug text, p_ownership_type text, p_location_id uuid, p_delivery_by text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_st text;
  v_id uuid;
begin
  if not public.current_user_is_admin_or_manager_of(p_account_id) then
    raise exception 'Solo un administrador o encargado de la cuenta puede cambiar «Si no dices nada»'
      using errcode = '42501';
  end if;
  if p_delivery_by not in ('platform', 'own') then
    raise exception 'Quién reparte: «%» no es ni platform ni own', p_delivery_by using errcode = '22023';
  end if;
  if p_location_id is not null
     and not exists (select 1 from public.locations l where l.id = p_location_id and l.account_id = p_account_id) then
    raise exception 'El local % no es de la cuenta', p_location_id using errcode = '23514';
  end if;
  v_st := case p_delivery_by when 'own' then 'own_delivery' else 'platform_delivery' end;

  if p_location_id is null then
    insert into public.channel_delivery_policy as c
      (account_id, channel_slug, ownership_type, service_type, location_id, created_by, created_by_name)
    values (p_account_id, p_channel_slug, p_ownership_type, v_st, null, auth.uid(), public.conta_nombre_actor())
    on conflict (account_id, channel_slug, ownership_type) where location_id is null
    do update set service_type = excluded.service_type, updated_at = now()
    returning c.id into v_id;
  else
    insert into public.channel_delivery_policy as c
      (account_id, channel_slug, ownership_type, service_type, location_id, created_by, created_by_name)
    values (p_account_id, p_channel_slug, p_ownership_type, v_st, p_location_id, auth.uid(), public.conta_nombre_actor())
    on conflict (account_id, channel_slug, ownership_type, location_id) where location_id is not null
    do update set service_type = excluded.service_type, updated_at = now()
    returning c.id into v_id;
  end if;
  return v_id;
end;
$$;


--
-- Name: reparto_liquidacion(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_liquidacion(p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'courier_id', c.id, 'name', c.name, 'kind', c.kind, 'nif', c.nif, 'iban', c.iban,
    'deliveries', dl.deliveries, 'km', round(dl.km,1),
    'delivery_earnings', round(dl.earnings,2),
    'quest_bonus', round(qa.bonus,2),
    'total', round(dl.earnings + qa.bonus, 2)
  ) order by c.name), '[]'::jsonb)
  from courier c
  cross join lateral (
    select count(*)::int as deliveries,
           coalesce(sum(da.transport_price),0)::numeric as earnings,
           coalesce(sum(public.sale_delivery_distance_km(da.sale_id)),0)::numeric as km
    from delivery_assignment da
    where da.courier_id = c.id and da.state = 'delivered'
      and (da.delivered_at at time zone 'Europe/Madrid')::date between p_from and p_to
      and (p_location_id is null or da.location_id = p_location_id)
  ) dl
  cross join lateral (
    select coalesce(sum(a.reward),0)::numeric as bonus
    from courier_bonus_award a
    where a.courier_id = c.id
      and (a.awarded_at at time zone 'Europe/Madrid')::date between p_from and p_to
  ) qa
  where c.account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(c.account_id)
    and (dl.deliveries > 0 or qa.bonus > 0);
$$;


--
-- Name: reparto_reoffer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_reoffer() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_next uuid; v_timeout int;
BEGIN
  FOR r IN SELECT * FROM public.delivery_assignment da
           WHERE da.state = 'offered' AND da.courier_id IS NULL
             AND da.offered_to IS NOT NULL AND da.offer_expires_at IS NOT NULL
             AND da.offer_expires_at < now() LOOP
    SELECT coalesce(l.offer_timeout_s,60) INTO v_timeout FROM public.locations l WHERE l.id = r.location_id;
    SELECT c.id INTO v_next
      FROM public.courier c, public.locations l
     WHERE l.id = r.location_id AND c.account_id = r.account_id AND c.active AND c.on_shift
       AND (c.assigned_locations = '{}'::uuid[] OR r.location_id = ANY(c.assigned_locations))
       AND c.id <> r.offered_to
       AND NOT (c.id = ANY(coalesce(r.declined_by, '{}'::uuid[])))
     ORDER BY (CASE WHEN c.last_lat IS NOT NULL AND c.last_lng IS NOT NULL AND l.lat IS NOT NULL AND l.lng IS NOT NULL
                    THEN 2*6371*asin(sqrt(power(sin(radians(c.last_lat - l.lat)/2),2)
                         + cos(radians(l.lat))*cos(radians(c.last_lat))*power(sin(radians(c.last_lng - l.lng)/2),2)))
                    ELSE NULL END) ASC NULLS LAST
     LIMIT 1;

    UPDATE public.delivery_assignment SET
      declined_by      = array_append(coalesce(declined_by, '{}'::uuid[]), r.offered_to),
      offered_to       = v_next,
      offer_expires_at = CASE WHEN v_next IS NOT NULL THEN now() + make_interval(secs => v_timeout) ELSE NULL END
    WHERE id = r.id;
  END LOOP;
END;
$$;


--
-- Name: reparto_responder_sugerencia(uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_responder_sugerencia(p_account_id uuid, p_brand_id uuid, p_channel_slug text, p_last_sale_id uuid, p_aceptar boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_r record;
  v_plataforma text;
begin
  if not public.current_user_is_admin_or_manager_of(p_account_id) then
    raise exception 'Solo un administrador o encargado de la cuenta puede responder a Folvy'
      using errcode = '42501';
  end if;
  select * into v_r from public.reparto_sugerencias(p_account_id) s
   where s.brand_id = p_brand_id and s.channel_slug = p_channel_slug and s.last_sale_id = p_last_sale_id;
  if v_r.brand_id is null then
    raise exception 'Esa sugerencia ya no está viva (llegó un pedido con dirección o ya se respondió)'
      using errcode = 'P0002';
  end if;
  v_plataforma := case p_channel_slug when 'uber' then 'Uber Eats' when 'justeat' then 'Just Eat'
                                      when 'glovo' then 'Glovo' else initcap(p_channel_slug) end;

  insert into public.delivery_policy_suggestion
    (account_id, brand_id, channel_slug, proposed, reason, evidence, last_sale_id, status,
     answered_by, answered_by_name)
  values
    (p_account_id, p_brand_id, p_channel_slug, 'platform',
     'En ' || v_plataforma || ', ' || v_r.brand_name || ' llevaba ' || v_r.pedidos
       || ' pedidos seguidos sin dirección. Parece que en ' || v_plataforma
       || ' la tienda está como «reparto de la plataforma».',
     (select jsonb_agg(jsonb_build_object('sale_id', v, 'codigo', c))
        from unnest(v_r.ventas, v_r.codigos) as x(v, c)),
     p_last_sale_id,
     case when p_aceptar then 'accepted' else 'rejected' end,
     auth.uid(), public.conta_nombre_actor());

  if p_aceptar then
    perform public.reparto_guardar_celda(p_account_id, p_brand_id, p_channel_slug, null, 'platform', 'ai_accepted');
    return 'Hecho: ' || v_r.brand_name || ' en ' || v_plataforma
      || ' la reparte la plataforma. Se aplica a los pedidos siguientes.';
  end if;
  return 'Anotado: ' || v_r.brand_name || ' en ' || v_plataforma
    || ' sigue en «Nosotros». No se vuelve a proponer por estos pedidos.';
end;
$$;


--
-- Name: reparto_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with acc as (select unnest(current_user_account_ids()) as id)
  select jsonb_build_object(
    'track_base_url', (select a.track_base_url from accounts a join acc on acc.id=a.id order by a.id limit 1),
    'carriers', coalesce((
        select jsonb_agg(jsonb_build_object('code', t.code, 'name', t.name) order by t.ord, t.name)
        from (
          select 'own_fleet'::text as code, 'Flota propia'::text as name, 0 as ord
          union
          select co.code, co.name, 1 as ord
          from account_connector ac
          join connector co on co.id = ac.connector_id
          where ac.account_id in (select id from acc)
            and coalesce(ac.is_active, false)
            and co.category = 'logistics'
        ) t
      ), '[]'::jsonb),
    'employees', coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'name',e.name) order by e.name)
      from employees e
      where coalesce(e.active,true)
        and exists (select 1 from locations l
                    where l.account_id in (select id from acc)
                      and (e.location_id = l.id or l.id = any(e.assigned_locations)))
      ),'[]'::jsonb),
    'locations', coalesce((select jsonb_agg(jsonb_build_object(
        'id',l.id,'name',l.name,'mode',coalesce(l.dispatch_mode,'auto'),
        'broker',l.dispatch_broker,'notify',coalesce(l.customer_notify_enabled,false),
        'bonus_rain_pct',l.bonus_rain_pct,'bonus_demand_max_pct',l.bonus_demand_max_pct,
        'bonus_combined_cap_pct',l.bonus_combined_cap_pct,'weather_is_raining',l.weather_is_raining,
        'weather_auto',l.weather_auto,'surge_pct',public.location_surge_pct(l.id),
        'assignment_strategy',coalesce(l.assignment_strategy,'broadcast'),'offer_timeout_s',coalesce(l.offer_timeout_s,60)) order by l.name)
      from locations l where l.account_id in (select id from acc)),'[]'::jsonb),
    'rules', coalesce((select jsonb_agg(jsonb_build_object(
        'id',r.id,'priority',r.priority,'location_id',r.location_id,'weekdays',r.weekdays,
        'time_from',r.time_from,'time_to',r.time_to,'min_total',r.min_total,'max_total',r.max_total,
        'margin_floor_pct',r.margin_floor_pct,'then_carrier',r.then_carrier,'fallback_carrier',r.fallback_carrier,
        'carrier_chain',r.carrier_chain,'max_distance_km',r.max_distance_km,
        'strategy',r.strategy,'is_active',r.is_active) order by r.priority)
      from dispatch_rule r where r.account_id in (select id from acc)),'[]'::jsonb),
    'bonuses', coalesce((select jsonb_agg(jsonb_build_object(
        'id',qb.id,'name',qb.name,'period',qb.period,'target_count',qb.target_count,'reward',qb.reward,
        'location_id',qb.location_id,'valid_from',qb.valid_from,'valid_to',qb.valid_to,'is_active',qb.is_active)
        order by qb.reward desc)
      from courier_bonus qb where qb.account_id in (select id from acc)),'[]'::jsonb),
    'couriers', coalesce((select jsonb_agg(jsonb_build_object(
        'id',c.id,'name',c.name,'phone',c.phone,'kind',c.kind,'employee_id',c.employee_id,
        'transport_type',c.transport_type,'vehicle_plate',c.vehicle_plate,'nif',c.nif,'iban',c.iban,
        'access_token',c.access_token,
        'assigned_locations',c.assigned_locations,'cost_model',c.cost_model,'cost_value',c.cost_value,
        'rate_base',c.rate_base,'rate_per_km',c.rate_per_km,'rate_min_pickup',c.rate_min_pickup,
        'rate_pickup_fee',c.rate_pickup_fee,'rate_max',c.rate_max,'rate_tiers',c.rate_tiers,
        'active',c.active,'on_shift',c.on_shift) order by c.name)
      from courier c where c.account_id in (select id from acc)),'[]'::jsonb)
  );
$$;


--
-- Name: reparto_sugerencias(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_sugerencias(p_account_id uuid, p_seguidos integer DEFAULT 3) RETURNS TABLE(brand_id uuid, brand_name text, channel_slug text, pedidos integer, codigos text[], ventas uuid[], last_sale_id uuid, ultimo_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'reparto_sugerencias: sin acceso a la cuenta' using errcode = '42501';
  end if;

  return query
  with ultimos as (
    select s.id, s.brand_id, sc.slug, s.platform_order_code, s.sold_at,
           coalesce(btrim(s.delivery_address), '') = '' as sin_dir,
           row_number() over (partition by s.brand_id, sc.slug order by s.sold_at desc, s.id desc) as n
      from public.sale s
      join public.sales_channel sc on sc.id = s.channel_id and sc.account_id = s.account_id
     where s.account_id = p_account_id
       and s.service_type = 'own_delivery'
       and s.source in ('hubrise', 'lastapp')
       and s.brand_id is not null
       and s.sold_at > now() - interval '30 days'
  ),
  rachas as (
    select u.brand_id, u.slug,
           count(*)::integer as pedidos,
           array_agg(coalesce(u.platform_order_code, left(u.id::text, 8)) order by u.sold_at) as codigos,
           array_agg(u.id order by u.sold_at) as ventas,
           (array_agg(u.id order by u.sold_at desc))[1] as last_sale_id,
           max(u.sold_at) as ultimo_at
      from ultimos u
     where u.n <= greatest(p_seguidos, 1)
     group by u.brand_id, u.slug
    having count(*) = greatest(p_seguidos, 1) and bool_and(u.sin_dir)
  )
  select r.brand_id, b.name, r.slug, r.pedidos, r.codigos, r.ventas, r.last_sale_id, r.ultimo_at
    from rachas r
    join public.brand b on b.id = r.brand_id and b.account_id = p_account_id
   cross join lateral public.resolve_delivery_by(p_account_id, r.brand_id, r.slug, null) q
   where q.delivery_by = 'own'
     and not exists (
       select 1 from public.delivery_policy_suggestion d
        where d.account_id = p_account_id and d.brand_id = r.brand_id
          and d.channel_slug = r.slug and d.last_sale_id = r.last_sale_id)
   order by r.ultimo_at desc;
end;
$$;


--
-- Name: reparto_weather_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_weather_apply() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'net', 'extensions'
    AS $$
DECLARE wp record; v_status int; v_content text; j jsonb; v_precip numeric; v_code int; v_rain boolean;
BEGIN
  FOR wp IN SELECT * FROM public.weather_poll WHERE request_id IS NOT NULL LOOP
    SELECT status_code, content::text INTO v_status, v_content
      FROM net._http_response WHERE id = wp.request_id;
    IF NOT FOUND OR v_status IS DISTINCT FROM 200 THEN CONTINUE; END IF;
    BEGIN
      j := (v_content::jsonb) -> 'current';
      v_precip := nullif(j->>'precipitation','')::numeric;
      v_code   := nullif(j->>'weather_code','')::int;
      v_rain   := coalesce(v_precip,0) > 0.1 OR coalesce(v_code,0) >= 51;
      UPDATE public.locations SET weather_is_raining = v_rain, weather_updated_at = now()
       WHERE id = wp.location_id AND weather_auto;
    EXCEPTION WHEN others THEN CONTINUE; END;
    UPDATE public.weather_poll SET request_id = NULL WHERE location_id = wp.location_id;
  END LOOP;
END;
$$;


--
-- Name: reparto_weather_poll(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparto_weather_poll() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'net', 'extensions'
    AS $$
DECLARE r record; v_req bigint;
BEGIN
  FOR r IN SELECT id, lat, lng FROM public.locations
           WHERE weather_auto AND lat IS NOT NULL AND lng IS NOT NULL LOOP
    v_req := net.http_get(
      'https://api.open-meteo.com/v1/forecast?latitude='||r.lat||'&longitude='||r.lng||'&current=precipitation,weather_code'
    );
    INSERT INTO public.weather_poll(location_id, request_id, requested_at)
    VALUES (r.id, v_req, now())
    ON CONFLICT (location_id) DO UPDATE SET request_id = excluded.request_id, requested_at = excluded.requested_at;
  END LOOP;
END;
$$;


--
-- Name: replicate_system_permission_sets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replicate_system_permission_sets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_replicated integer;
BEGIN
  INSERT INTO permission_sets (
    account_id, 
    name, 
    description, 
    is_system, 
    permissions, 
    active, 
    created_by
  )
  SELECT 
    NEW.id,
    ps.name, 
    ps.description, 
    true,
    ps.permissions, 
    true, 
    NEW.created_by
  FROM permission_sets ps
  WHERE ps.account_id IS NULL
    AND ps.is_system = true
    AND ps.active = true;
  
  GET DIAGNOSTICS v_replicated = ROW_COUNT;
  
  RAISE NOTICE 'replicate_system_permission_sets: replicated % sets to new account %', 
    v_replicated, NEW.id;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION replicate_system_permission_sets(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replicate_system_permission_sets() IS 'Replica los permission_sets system globales (account_id NULL) a cada nueva cuenta cliente.';


--
-- Name: report_device_app_version(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_device_app_version(p_device_token text, p_app_version text, p_platform text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_device kds_device;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    return false;
  end if;

  update kds_device
     set app_version    = nullif(btrim(coalesce(p_app_version, '')), ''),
         platform       = nullif(btrim(coalesce(p_platform, '')), ''),
         app_version_at = now(),
         updated_at     = now()
   where id = v_device.id;

  return true;
end;
$$;


--
-- Name: FUNCTION report_device_app_version(p_device_token text, p_app_version text, p_platform text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_device_app_version(p_device_token text, p_app_version text, p_platform text) IS 'La app reporta su versión instalada. Devuelve false (no excepción) si el token no es válido.';


--
-- Name: report_device_bundle_applied(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_device_bundle_applied(p_device_token text, p_bundle_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device  kds_device;
  v_antes   integer;
  v_cambio  boolean;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    return jsonb_build_object('ok', false, 'motivo', 'token_no_valido');
  end if;
  if p_bundle_id is null or p_bundle_id < 0 then
    return jsonb_build_object('ok', false, 'motivo', 'paquete_no_valido');
  end if;

  select bundle_applied into v_antes from kds_device where id = v_device.id;
  v_cambio := (v_antes is distinct from p_bundle_id);

  if v_cambio then
    update kds_device
       set bundle_applied    = p_bundle_id,
           bundle_applied_at = now(),
           updated_at        = now()
     where id = v_device.id;
  end if;

  -- Devuelve QUÉ ha pasado, no un booleano (regla 8): quien llama —y quien lea
  -- el ensayo— distingue «ha cambiado de paquete» de «sigue en el mismo», que
  -- son cosas distintas y hasta hoy se veían igual desde fuera.
  return jsonb_build_object(
    'ok',               true,
    'cambio',           v_cambio,
    'bundle_anterior',  v_antes,
    'bundle_aplicado',  p_bundle_id,
    'aplicado_en',      (select bundle_applied_at from kds_device where id = v_device.id)
  );
end;
$$;


--
-- Name: FUNCTION report_device_bundle_applied(p_device_token text, p_bundle_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_device_bundle_applied(p_device_token text, p_bundle_id integer) IS 'La tablet declara qué paquete OTA está corriendo. Sella bundle_applied_at solo cuando el número cambia.';


