--
-- Name: report_platform_floor(text, text, uuid, numeric, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_platform_floor(p_secret text, p_channel text, p_menu_item_id uuid, p_floor_pct numeric DEFAULT NULL::numeric, p_floor_price numeric DEFAULT NULL::numeric, p_ref_price numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
  v_channel uuid;
  v_pct     numeric;
begin
  -- 1) Autenticar por secreto → cuenta
  select account_id into v_account
  from public.offers_agent_config
  where push_agent_secret = p_secret
  limit 1;
  if v_account is null then
    return jsonb_build_object('ok', false, 'error', 'secreto inválido');
  end if;

  -- 2) El artículo debe ser de esa cuenta (defensa: el secreto no puede escribir en otra)
  if not exists (
    select 1 from public.menu_item mi
    where mi.id = p_menu_item_id and mi.account_id = v_account
  ) then
    return jsonb_build_object('ok', false, 'error', 'menu_item fuera de la cuenta');
  end if;

  -- 3) Resolver canal por nombre dentro de la cuenta
  select id into v_channel
  from public.sales_channel
  where account_id = v_account and lower(name) = lower(p_channel)
  limit 1;
  if v_channel is null then
    return jsonb_build_object('ok', false, 'error', 'canal no encontrado: ' || coalesce(p_channel,'∅'));
  end if;

  -- 4) Resolver el % hundido: el que venga, o calcularlo desde los € si están ambos.
  v_pct := coalesce(
    p_floor_pct,
    case when p_floor_price is not null and p_ref_price is not null and p_ref_price > 0
         then (1 - p_floor_price / p_ref_price) * 100 end
  );
  if v_pct is not null then
    v_pct := greatest(0, least(95, round(v_pct::numeric, 2)));
  end if;

  -- 5) Upsert de la observación (la más reciente manda)
  insert into public.platform_promo_floor
    (account_id, channel_id, menu_item_id, floor_pct, floor_price, ref_price, source, observed_at, note)
  values
    (v_account, v_channel, p_menu_item_id, v_pct,
     p_floor_price, p_ref_price, 'glovo_portal', now(), p_note)
  on conflict (account_id, channel_id, menu_item_id) do update
    set floor_pct   = excluded.floor_pct,
        floor_price = excluded.floor_price,
        ref_price   = excluded.ref_price,
        source      = excluded.source,
        observed_at = now(),
        note        = excluded.note;

  return jsonb_build_object('ok', true, 'account_id', v_account, 'channel_id', v_channel);
end;
$$;


--
-- Name: report_print_job(text, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_print_job(p_device_token text, p_job_id uuid, p_ok boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'report_print_job: token no válido';
  end if;

  update print_job j
  set status = case
        when p_ok then 'done'
        -- Tarea E.1/E.3: reintenta si aún le quedan intentos Y no es viejo;
        -- si no, 'error' de verdad — terminal, no se vuelve a ofrecer.
        when j.attempts < 3 and j.created_at >= now() - interval '2 hours' then 'pending'
        else 'error'
      end,
      done_at    = case when p_ok then now() else done_at end,
      last_error = case when p_ok then null else p_error end
  where j.id = p_job_id
    and j.account_id = v_device.account_id;
end;
$$;


--
-- Name: FUNCTION report_print_job(p_device_token text, p_job_id uuid, p_ok boolean, p_error text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_print_job(p_device_token text, p_job_id uuid, p_ok boolean, p_error text) IS 'Informa el resultado de un trabajo de impresión. Tarea E (fix/tablet-
   robustez, 12/08): un fallo con menos de 3 intentos y menos de 2h de
   antigüedad vuelve a pending (claim_print_jobs lo reintentará con espera);
   agotados los intentos o superadas las 2h, error de verdad — terminal.';


--
-- Name: report_promo_push_job(text, uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_promo_push_job(p_secret text, p_job_id uuid, p_ok boolean, p_external_ref text DEFAULT NULL::text, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid;
begin
  select account_id into v_acc from offers_agent_config
   where push_agent_secret = p_secret and push_agent_secret is not null;
  if v_acc is null then raise exception 'secreto inválido'; end if;
  update promo_push_job
     set status = case when p_ok then 'done' else 'error' end,
         external_ref = coalesce(p_external_ref, external_ref),
         last_error = p_error, updated_at = now()
   where id = p_job_id and account_id = v_acc
     and status = 'sent';  -- v3.18: solo vuelos vivos; un job matado queda matado
end $$;


--
-- Name: report_sales(uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text[], uuid[], uuid[], text, uuid[], text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_sales(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_prev_from timestamp with time zone, p_prev_to timestamp with time zone, p_ejes text[] DEFAULT ARRAY['local'::text], p_location_ids uuid[] DEFAULT NULL::uuid[], p_brand_ids uuid[] DEFAULT NULL::uuid[], p_ownership text DEFAULT NULL::text, p_channel_ids uuid[] DEFAULT NULL::uuid[], p_service_types text[] DEFAULT NULL::text[], p_calendario boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tz     text;
  v_dur    interval;
  v_dur_p  interval;
  v_filas  jsonb;
  v_esp    jsonb;
  v_dias   jsonb;
  v_tot    record;
begin
  if not (p_account = any(current_user_account_ids())) then
    raise exception 'report_sales: sin acceso a la cuenta %', p_account;
  end if;

  -- Una regla, un sitio. Lanza excepcion si las ventanas no son comparables.
  perform _report_ventanas_validas(p_from, p_to, p_prev_from, p_prev_to, p_calendario);

  select coalesce(a.timezone, 'Europe/Madrid') into v_tz from accounts a where a.id = p_account;
  v_dur   := p_to - p_from;
  v_dur_p := p_prev_to - p_prev_from;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.neto desc), '[]'::jsonb) into v_filas
  from _report_sales_rows(p_account, p_from, p_to, p_ejes,
                          p_location_ids, p_brand_ids, p_ownership, p_channel_ids, p_service_types) r;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.neto desc), '[]'::jsonb) into v_esp
  from _report_sales_rows(p_account, p_prev_from, p_prev_to, p_ejes,
                          p_location_ids, p_brand_ids, p_ownership, p_channel_ids, p_service_types) r;

  select jsonb_build_object(
    'actual', coalesce((select jsonb_agg(to_jsonb(r) order by r.dims->>'dia')
                        from _report_sales_rows(p_account, p_from, p_to, p_ejes || array['dia'],
                              p_location_ids, p_brand_ids, p_ownership, p_channel_ids, p_service_types) r),
                       '[]'::jsonb),
    'espejo', coalesce((select jsonb_agg(to_jsonb(r) order by r.dims->>'dia')
                        from _report_sales_rows(p_account, p_prev_from, p_prev_to, p_ejes || array['dia'],
                              p_location_ids, p_brand_ids, p_ownership, p_channel_ids, p_service_types) r),
                       '[]'::jsonb)
  ) into v_dias;

  select * into v_tot from _report_sales_rows(p_account, p_from, p_to, array[]::text[],
                        p_location_ids, p_brand_ids, p_ownership, p_channel_ids, p_service_types);

  return jsonb_build_object(
    'meta', jsonb_build_object(
      'zona', v_tz,
      'ventana_actual', jsonb_build_object(
        'desde', to_char(p_from      at time zone v_tz, 'YYYY-MM-DD HH24:MI'),
        'hasta', to_char(p_to        at time zone v_tz, 'YYYY-MM-DD HH24:MI'),
        'horas', round(extract(epoch from v_dur)/3600.0, 2)),
      'ventana_espejo', jsonb_build_object(
        'desde', to_char(p_prev_from at time zone v_tz, 'YYYY-MM-DD HH24:MI'),
        'hasta', to_char(p_prev_to   at time zone v_tz, 'YYYY-MM-DD HH24:MI'),
        'horas', round(extract(epoch from v_dur_p)/3600.0, 2)),
      'ejes', to_jsonb(p_ejes),
      'filtros', jsonb_strip_nulls(jsonb_build_object(
        'locales', to_jsonb(p_location_ids), 'marcas', to_jsonb(p_brand_ids),
        'propiedad', p_ownership, 'canales', to_jsonb(p_channel_ids),
        'servicios', to_jsonb(p_service_types))),
      'regla',
        'account_id = la cuenta · is_active · status <> cancelled · cortes en ' || v_tz ||
        ' · Neto = sale.total · Bruto = neto + descuentos · Devoluciones no se pintan: refund_amount es 0,00 en el 100 % de las ventas',
      'cobertura_coste', jsonb_build_object(
        'pedidos', v_tot.pedidos,
        'neto',    v_tot.neto,
        'con_coste', jsonb_build_object(
          'pedidos', v_tot.pedidos_costeados,
          'neto',    v_tot.neto_costeado,
          'pct_pedidos', case when coalesce(v_tot.pedidos,0) <> 0
                              then round(100.0 * v_tot.pedidos_costeados / v_tot.pedidos, 1) end,
          'pct_importe', case when coalesce(v_tot.neto,0) <> 0
                              then round(100 * v_tot.neto_costeado / v_tot.neto, 1) end,
          'regla', 'Un pedido cuenta como costeado si TODAS sus lineas product no ignoradas tienen coste. Las combo_item y modifier no entran: su computed_cost es NULL siempre y por diseno, el motor cuelga el coste de la linea padre.'),
        'sin_hueco_de_modificador', jsonb_build_object(
          'pedidos', v_tot.pedidos_sin_hueco,
          'neto',    v_tot.neto_sin_hueco,
          'pct_pedidos', case when coalesce(v_tot.pedidos,0) <> 0
                              then round(100.0 * v_tot.pedidos_sin_hueco / v_tot.pedidos, 1) end,
          'pct_importe', case when coalesce(v_tot.neto,0) <> 0
                              then round(100 * v_tot.neto_sin_hueco / v_tot.neto, 1) end,
          'pedidos_con_modificador_cobrado_sin_impacto', v_tot.pedidos_mod_sin_impacto,
          'regla', 'Ademas de lo anterior, el pedido no lleva ningun modificador COBRADO sin impacto confirmado. Ese modificador mete su comida en el precio y no en el coste: el pedido cuenta como costeado y el margen sale mejor de lo que es. OJO al restar: de esos pedidos, solo los que estaban dentro del nivel anterior lo reducen.'),
        'sesgo_no_medido', 'El envase (packaging_cost) NO entra en el coste congelado (B73): el margen sale sistematicamente mejor de lo que es en una cantidad que todavia nadie ha medido. Un hueco declarado se puede ensenar; un sesgo sin medir, no.')
    ),
    'filas',  v_filas,
    'espejo', v_esp,
    'dias',   v_dias
  );
end;
$$;


--
-- Name: FUNCTION report_sales(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_prev_from timestamp with time zone, p_prev_to timestamp with time zone, p_ejes text[], p_location_ids uuid[], p_brand_ids uuid[], p_ownership text, p_channel_ids uuid[], p_service_types text[], p_calendario boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_sales(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_prev_from timestamp with time zone, p_prev_to timestamp with time zone, p_ejes text[], p_location_ids uuid[], p_brand_ids uuid[], p_ownership text, p_channel_ids uuid[], p_service_types text[], p_calendario boolean) IS 'Generador de informes: frontera que autoriza por cuenta, mide las dos ventanas con la misma regla y devuelve meta con el intervalo local, los filtros y la regla de medida.';


--
-- Name: reprint_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reprint_order(p_sale_id uuid, p_doc_type text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_loc uuid; v_count int := 0; v_printer record; v_doc text; v_i int;
begin
  select account_id, location_id into v_acc, v_loc from sale where id = p_sale_id;
  if v_acc is null then raise exception 'reprint_order: pedido no encontrado'; end if;
  if not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(v_acc)) then
    raise exception 'reprint_order: sin acceso a la cuenta';
  end if;
  for v_printer in
    select id, doc_types, copies from printer where account_id = v_acc and location_id = v_loc and is_active
  loop
    foreach v_doc in array v_printer.doc_types loop
      if p_doc_type is not null and v_doc <> p_doc_type then continue; end if;
      for v_i in 1..greatest(1, coalesce(v_printer.copies, 1)) loop
        insert into print_job (account_id, location_id, printer_id, sale_id, doc_type, payload, source, status)
        values (v_acc, v_loc, v_printer.id, p_sale_id, v_doc,
                jsonb_build_object('sale_id', p_sale_id, 'mode', 'by_order'), 'reprint', 'pending');
        v_count := v_count + 1;
      end loop;
    end loop;
  end loop;
  return v_count;
end;
$$;


--
-- Name: reprint_order_by_token(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reprint_order_by_token(p_device_token text, p_sale_id uuid, p_doc_type text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_device kds_device; v_count int := 0; v_printer record; v_doc text; v_i int;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'reprint_order_by_token: token no válido'; end if;
  if not exists (select 1 from sale where id = p_sale_id and account_id = v_device.account_id and location_id = v_device.location_id) then
    raise exception 'reprint_order_by_token: pedido no encontrado en el local del dispositivo';
  end if;
  for v_printer in
    select id, doc_types, copies from printer where account_id = v_device.account_id and location_id = v_device.location_id and is_active
  loop
    foreach v_doc in array v_printer.doc_types loop
      if p_doc_type is not null and v_doc <> p_doc_type then continue; end if;
      for v_i in 1..greatest(1, coalesce(v_printer.copies, 1)) loop
        insert into print_job (account_id, location_id, printer_id, sale_id, doc_type, payload, source, status)
        values (v_device.account_id, v_device.location_id, v_printer.id, p_sale_id, v_doc,
                jsonb_build_object('sale_id', p_sale_id, 'mode', 'by_order'), 'reprint', 'pending');
        v_count := v_count + 1;
      end loop;
    end loop;
  end loop;
  return v_count;
end;
$$;


--
-- Name: reprocess_sale(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reprocess_sale(p_sale_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_loc        uuid;
  v_source     text;
  v_line_id    uuid;
  v_item       uuid;
  v_old_items  uuid[];
  v_n          integer := 0;
BEGIN
  SELECT account_id, location_id, source INTO v_account_id, v_loc, v_source
  FROM sale WHERE id = p_sale_id;
  IF v_account_id IS NULL THEN RETURN 0; END IF;

  v_old_items := ARRAY(
    SELECT DISTINCT sm.recipe_item_id
    FROM stock_movement sm
    WHERE sm.account_id = v_account_id
      AND sm.movement_type = 'consumo'
      AND sm.source_type = 'sale'
      AND (
        sm.source_id = p_sale_id
        OR sm.source_id IN (SELECT id FROM sale_line WHERE sale_id = p_sale_id)
      )
  );

  -- (Aqui habia un DELETE sin corte. Lo hace `generate_sale_consumption`, que
  --  es el unico que sabe que puede borrar y que no.)

  IF v_source = 'lastapp' THEN
    PERFORM public.resolve_sale_brand_from_map(p_sale_id);
  END IF;

  IF v_source = 'hubrise' THEN
    PERFORM public.adapt_hubrise_order(p_sale_id);
  ELSE
    PERFORM public.adapt_lastapp_order(p_sale_id);
  END IF;

  FOR v_line_id IN
    SELECT id FROM sale_line
    WHERE sale_id = p_sale_id AND line_type = 'product'
  LOOP
    PERFORM public.compute_sale_line_cost(v_line_id);
    v_n := v_n + 1;
  END LOOP;

  PERFORM public.generate_sale_consumption(p_sale_id);

  IF v_loc IS NOT NULL THEN
    FOREACH v_item IN ARRAY COALESCE(v_old_items, '{}'::uuid[])
    LOOP
      PERFORM public.recompute_location_stock_core(v_item, v_loc);
    END LOOP;
  END IF;

  RETURN v_n;
END;
$$;


--
-- Name: clock_correction_request; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clock_correction_request (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    requested_by_employee_id uuid NOT NULL,
    clock_entry_id uuid,
    kind text NOT NULL,
    proposed_type text,
    proposed_datetime timestamp with time zone,
    reason text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    resolved_by_user_id uuid,
    resolved_at timestamp with time zone,
    resolution_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT clock_correction_request_kind_check CHECK ((kind = ANY (ARRAY['add'::text, 'edit'::text, 'void'::text]))),
    CONSTRAINT clock_correction_request_proposed_type_check CHECK ((proposed_type = ANY (ARRAY['entrada'::text, 'salida'::text]))),
    CONSTRAINT clock_correction_request_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: request_clock_correction(uuid, uuid, text, text, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_clock_correction(p_employee_id uuid, p_requested_by_employee_id uuid, p_kind text, p_reason text, p_clock_entry_id uuid DEFAULT NULL::uuid, p_proposed_type text DEFAULT NULL::text, p_proposed_datetime timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.clock_correction_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acct uuid; v_row public.clock_correction_request;
begin
  if coalesce(trim(p_reason),'') = '' then raise exception 'MOTIVO_OBLIGATORIO'; end if;
  if p_kind not in ('add','edit','void') then raise exception 'TIPO_INVALIDO'; end if;
  v_acct := public._account_of_employee(p_employee_id);
  if v_acct is null or not (v_acct = any (public.current_user_account_ids())) then raise exception 'NO_AUTORIZADO'; end if;
  -- L1a (28/10): la pide la propia persona, en su nombre; o quien puede
  -- corregirla. Hasta hoy quien llamaba decía quién pedía, y para quién.
  if not (
       (p_requested_by_employee_id = p_employee_id and public.current_user_is_employee(p_employee_id, v_acct))
    or public._puede_corregir(p_employee_id, v_acct)
  ) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'Solo puedes pedir correcciones de tus propios fichajes.';
  end if;
  if p_clock_entry_id is not null and not exists (
    select 1 from public.clock_entries where id = p_clock_entry_id and employee_id = p_employee_id) then
    raise exception 'FICHAJE_NO_EXISTE' using errcode = '22023', hint = 'Ese fichaje no es de esa persona.';
  end if;

  insert into public.clock_correction_request(
    account_id, employee_id, requested_by_employee_id, clock_entry_id, kind, proposed_type, proposed_datetime, reason)
  values (v_acct, p_employee_id, p_requested_by_employee_id, p_clock_entry_id, p_kind, p_proposed_type, p_proposed_datetime, p_reason)
  returning * into v_row;

  insert into public.clock_entry_audit(
    clock_entry_id, employee_id, account_id, action, actor_employee_id, reason, after, peticion_id)
  values (p_clock_entry_id, p_employee_id, v_acct, 'request', p_requested_by_employee_id, p_reason, to_jsonb(v_row), v_row.id);
  return v_row;
end $$;


--
-- Name: request_recount(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_recount(p_line_id uuid, p_assign_to uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id  uuid;
  v_location_id uuid;
  v_item_id     uuid;
  v_conto       uuid;
  v_asignado    uuid;
  v_abierto     uuid;
  v_nueva       uuid;
  v_pos         integer;
  v_nombre      text;
BEGIN
  SELECT l.account_id, l.recipe_item_id, l.counted_by, ic.location_id
    INTO v_account_id, v_item_id, v_conto, v_location_id
    FROM public.inventory_count_line l
    JOIN public.inventory_count ic ON ic.id = l.inventory_count_id
   WHERE l.id = p_line_id;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'request_recount: la línea % no existe', p_line_id;
  END IF;
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(v_account_id)) THEN
    RAISE EXCEPTION 'request_recount: sólo quien aprueba puede pedir un recuento';
  END IF;

  -- OTRA PERSONA, y esto no es una preferencia: preguntarle otra vez a quien ya
  -- contestó da la misma respuesta.
  v_asignado := p_assign_to;
  IF v_asignado IS NOT NULL AND v_conto IS NOT NULL AND v_asignado = v_conto THEN
    v_asignado := NULL;
  END IF;
  IF v_asignado IS NULL AND v_conto IS NOT NULL THEN
    SELECT l2.counted_by INTO v_asignado
      FROM public.inventory_count_line l2
      JOIN public.inventory_count ic2 ON ic2.id = l2.inventory_count_id
     WHERE ic2.location_id = v_location_id
       AND l2.account_id = v_account_id
       AND l2.counted_by IS NOT NULL
       AND l2.counted_by <> v_conto
       AND l2.counted_at > now() - interval '30 days'
     GROUP BY l2.counted_by
     ORDER BY max(l2.counted_at) DESC
     LIMIT 1;
  END IF;

  UPDATE public.inventory_count_line
     SET recount_requested_at = now(),
         recount_requested_by = auth.uid(),
         recount_assign_to    = v_asignado
   WHERE id = p_line_id;

  -- Si el autoinventario de HOY sigue abierto y el artículo no está ya dentro,
  -- la línea entra ahora mismo. Si no, espera al siguiente (paso 7).
  SELECT id INTO v_abierto
    FROM public.inventory_count
   WHERE account_id = v_account_id AND location_id = v_location_id
     AND kind = 'cycle' AND status IN ('abierto','contando')
     AND created_at::date = current_date
   ORDER BY created_at DESC LIMIT 1;

  IF v_abierto IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.inventory_count_line x
                      WHERE x.inventory_count_id = v_abierto AND x.recipe_item_id = v_item_id) THEN
    SELECT COALESCE(max(position), 0) + 1 INTO v_pos
      FROM public.inventory_count_line WHERE inventory_count_id = v_abierto;

    INSERT INTO public.inventory_count_line
      (account_id, inventory_count_id, recipe_item_id, position, system_qty,
       abc_class, assigned_to, recount_of)
    SELECT v_account_id, v_abierto, v_item_id, v_pos,
           public.theoretical_qty_at(v_item_id, v_location_id, now()),
           l.abc_class, v_asignado, p_line_id
      FROM public.inventory_count_line l WHERE l.id = p_line_id
    RETURNING id INTO v_nueva;
  END IF;

  SELECT e.name INTO v_nombre FROM public.employees e WHERE e.id = v_asignado;

  -- Regla 8: la confirmación lleva CONTENIDO.
  RETURN jsonb_build_object(
    'requested',    true,
    'new_line_id',  v_nueva,
    'when',         CASE WHEN v_nueva IS NOT NULL THEN 'hoy' ELSE 'proximo' END,
    'assigned_to',  v_asignado,
    'assigned_name', v_nombre
  );
END;
$$;


--
-- Name: FUNCTION request_recount(p_line_id uuid, p_assign_to uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_recount(p_line_id uuid, p_assign_to uuid) IS 'Pide que otra persona vuelva a contar este artículo: crea la línea con recount_of en el autoinventario de hoy si sigue abierto, o la deja en cola para el siguiente (§2.4, 10/09/2026).';


--
-- Name: request_social_generation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_social_generation(p_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_secret text;
begin
  if not current_user_is_admin_or_manager_of(p_account_id) then
    raise exception 'no autorizado';
  end if;
  select decrypted_secret into v_secret
    from vault.decrypted_secrets where name = 'offers_agent_secret';
  if v_secret is null then raise exception 'secreto del agente no configurado'; end if;

  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/social-agent',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-agent-secret', v_secret
    ),
    body := jsonb_build_object('account_id', p_account_id, 'force', true),
    timeout_milliseconds := 20000
  );
end $$;


--
-- Name: requeue_social_image(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requeue_social_image(p_post_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_cur text;
begin
  select account_id, status into v_acc, v_cur from social_post where id = p_post_id;
  if v_acc is null then raise exception 'post no encontrado'; end if;
  if not current_user_is_admin_or_manager_of(v_acc) then raise exception 'no autorizado'; end if;
  if v_cur in ('publishing','published') then raise exception 'no en este estado'; end if;
  update social_post set payload = jsonb_set(payload, '{image_level}', to_jsonb('N1-pendiente'::text)),
         updated_at = now() where id = p_post_id;
end $$;


--
-- Name: resolve_channel_commission(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_channel_commission(p_account uuid, p_channel uuid, p_brand uuid, p_location uuid, p_service_type text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (
      select r.commission_pct
      from public.brand_channel_rate r
      join public.brand_channel bc on bc.id = r.brand_channel_id
      where r.account_id = p_account
        and bc.brand_id = p_brand
        and bc.channel_id = p_channel
        and r.service_type = p_service_type
        and coalesce(r.is_active, true)
        and (r.location_id = p_location or r.location_id is null)
      order by (r.location_id is not null) desc   -- local concreto primero
      limit 1
    ),
    (
      select cr.commission_pct
      from public.channel_rate cr
      where cr.account_id = p_account
        and cr.sales_channel_id = p_channel
        and cr.service_type = p_service_type
        and coalesce(cr.is_active, true)
      limit 1
    )
  );
$$;


--
-- Name: FUNCTION resolve_channel_commission(p_account uuid, p_channel uuid, p_brand uuid, p_location uuid, p_service_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_channel_commission(p_account uuid, p_channel uuid, p_brand uuid, p_location uuid, p_service_type text) IS 'Devuelve la comision (%) de un pedido segun cuenta/canal/marca/local/modo, en cascada: brand_channel_rate por local > por marca > channel_rate defecto.';


--
-- Name: resolve_clock_correction(uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_clock_correction(p_request_id uuid, p_approve boolean, p_note text DEFAULT NULL::text, p_actor_label text DEFAULT NULL::text) RETURNS public.clock_correction_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.clock_correction_request; v_new public.clock_entries; v_loc uuid;
begin
  select * into r from public.clock_correction_request where id = p_request_id for update;
  if r.id is null then raise exception 'SOLICITUD_NO_EXISTE'; end if;
  if not public._puede_corregir(r.employee_id, r.account_id) then raise exception 'NO_AUTORIZADO'; end if;
  if r.status <> 'pending' then raise exception 'YA_RESUELTA'; end if;

  if p_approve then
    perform set_config('app.clock_edit_reason', 'Solicitud del trabajador: '||r.reason, true);
    perform set_config('app.clock_edit_actor', coalesce(p_actor_label,''), true);
    -- L1a (28/10): el rastro sabe de qué petición viene (y no pide conformidad:
    -- la pidió la propia persona).
    perform set_config('app.clock_peticion_id', r.id::text, true);

    if r.kind = 'add' then
      select location_id into v_loc from public.employees where id = r.employee_id;
      insert into public.clock_entries(employee_id, type, datetime, real_datetime, source, address, location_id_at_clock)
      values (r.employee_id, r.proposed_type, r.proposed_datetime, r.proposed_datetime, 'manual', 'Aprobado · '||r.reason, v_loc)
      returning * into v_new;
      insert into public.clock_entry_audit(
        clock_entry_id, employee_id, account_id, action, actor_user_id, actor_label, reason, after)
      values (v_new.id, r.employee_id, r.account_id, 'create_manual', auth.uid(), p_actor_label, r.reason,
              public._clock_snapshot(v_new));
    elsif r.kind = 'edit' and r.clock_entry_id is not null then
      update public.clock_entries set datetime = r.proposed_datetime, real_datetime = r.proposed_datetime, type = coalesce(r.proposed_type, type)
       where id = r.clock_entry_id;
    elsif r.kind = 'void' and r.clock_entry_id is not null then
      update public.clock_entries set voided = true where id = r.clock_entry_id;
    end if;
    perform set_config('app.clock_peticion_id', '', true);
  end if;

  update public.clock_correction_request
     set status = case when p_approve then 'approved' else 'rejected' end,
         resolved_by_user_id = auth.uid(), resolved_at = now(), resolution_note = p_note
   where id = p_request_id
   returning * into r;

  insert into public.clock_entry_audit(
    clock_entry_id, employee_id, account_id, action, actor_user_id, actor_label, reason, peticion_id)
  values (coalesce(v_new.id, r.clock_entry_id), r.employee_id, r.account_id,
          case when p_approve then 'approve' else 'reject' end, auth.uid(), p_actor_label,
          coalesce(p_note, r.reason), r.id);

  insert into public.employee_notifications(employee_id, type, title, body, data)
  values (r.requested_by_employee_id, 'clock_correction_resolved',
          case when p_approve then 'Corrección aprobada' else 'Corrección rechazada' end,
          coalesce(p_note, r.reason),
          jsonb_build_object('request_id', r.id, 'status', r.status));
  return r;
end $$;


--
-- Name: resolve_delivery_by(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_delivery_by(p_account_id uuid, p_brand_id uuid, p_channel_slug text, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(delivery_by text, source text, decided_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with marca as (
    select b.ownership_type
      from public.brand b
     where b.id = p_brand_id and b.account_id = p_account_id
  ),
  candidatas as (
    -- 1 y 2: la celda de la marca, primero la del local.
    select p.delivery_by, p.source, p.decided_at,
           case when p.location_id = p_location_id then 1 else 2 end as orden
      from public.brand_delivery_policy p
     where p.account_id = p_account_id
       and p.brand_id = p_brand_id
       and p.channel_slug = p_channel_slug
       and (p.location_id = '00000000-0000-0000-0000-000000000000'::uuid
            or p.location_id = p_location_id)
    union all
    -- 3 y 4: la herencia por tipo de marca, primero la del local.
    select case pol.service_type when 'own_delivery' then 'own' else 'platform' end,
           'inherited', pol.updated_at,
           case when pol.location_id is not null then 3 else 4 end
      from public.channel_delivery_policy pol
      join marca m on m.ownership_type = pol.ownership_type
     where pol.account_id = p_account_id
       and pol.channel_slug = p_channel_slug
       and (pol.location_id is null or pol.location_id = p_location_id)
    union all
    -- 5: nadie ha dicho nada.
    select 'platform', 'default', null::timestamptz, 5
  )
  select c.delivery_by, c.source, c.decided_at
    from candidatas c
   order by c.orden
   limit 1
$$;


--
-- Name: FUNCTION resolve_delivery_by(p_account_id uuid, p_brand_id uuid, p_channel_slug text, p_location_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_delivery_by(p_account_id uuid, p_brand_id uuid, p_channel_slug text, p_location_id uuid) IS 'R02 · Quién reparte esta marca en esta plataforma (y local): own | platform, y de dónde sale (manual | migrated | ai_accepted | inherited | default). Orden: celda del local, celda de la marca, herencia del local, herencia de la cuenta, platform. Es el ÚNICO sitio que decide.';


--
-- Name: resolve_delivery_zone(uuid, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_delivery_zone(p_account_id uuid, p_lat double precision, p_lng double precision, p_postal text DEFAULT NULL::text) RETURNS TABLE(zone_id uuid, location_id uuid, zone_name text, method text, delivery_fee numeric, min_order numeric, eta_min integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with pt as (
    select ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography as g
  )
  select z.id, z.location_id, z.name, z.method, z.delivery_fee, z.min_order, z.eta_min
  from public.delivery_zone z, pt
  where z.account_id = p_account_id
    and z.is_active
    and (
      (z.method = 'radius'  and ST_DWithin(z.center, pt.g, z.radius_m))
      or
      (z.method = 'polygon' and ST_Covers(z.area, pt.g))
      or
      (z.method = 'postal'  and p_postal is not null and p_postal = any (z.postal_codes))
    )
  -- Regla Uber: gana la tarifa más baja; desempate por priority y zona.
  order by z.delivery_fee asc, z.priority desc, z.id asc
  limit 1;
$$;


--
-- Name: FUNCTION resolve_delivery_zone(p_account_id uuid, p_lat double precision, p_lng double precision, p_postal text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_delivery_zone(p_account_id uuid, p_lat double precision, p_lng double precision, p_postal text) IS 'Resuelve la zona de entrega más barata que cubre un punto (regla Uber). Devuelve local+coste+mínimo+ETA, o 0 filas si no hay cobertura. SECURITY DEFINER: verificar desde la app.';


--
-- Name: resolve_dispatch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_dispatch(p_sale_id uuid) RETURNS TABLE(carrier text, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale   record;
  v_mode   text;
  v_broker text;
  v_rule   record;
  v_now    timestamptz := now();
  v_dow    int;
  v_time   time;
  v_avail  int;
  v_rt     jsonb;
  v_dlat   numeric;
  v_dlng   numeric;
  v_llat   numeric;
  v_llng   numeric;
  v_dist   numeric;
  v_chain  text[];
  v_c      text;
BEGIN
  SELECT s.account_id, s.location_id, s.brand_id, s.total, s.service_type, s.raw_tab,
         s.delivery_address, s.delivery_address_fixed, s.delivery_by_reason
    INTO v_sale FROM public.sale s WHERE s.id = p_sale_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::text, 'venta no encontrada'::text; RETURN;
  END IF;

  -- GUARD (R02, 05/10): QUIÉN REPARTE YA ESTÁ DECIDIDO.
  -- Antes aquí se miraba el interruptor por marca, que valía para todas las
  -- plataformas a la vez y no cabía en la realidad
  -- (Smash: Glovo reparte Glovo, Uber repartimos nosotros). Ahora lo decide
  -- resolve_delivery_by al ENTRAR el pedido y queda escrito en su
  -- service_type. Aquí solo se respeta: si no es own_delivery, no se despacha.
  -- Así cambiar una celda en «Quién reparte» no toca pedidos ya abiertos.
  IF v_sale.service_type IS DISTINCT FROM 'own_delivery' THEN
    RETURN QUERY SELECT NULL::text, 'la reparte la plataforma: no se despacha'::text;
    RETURN;
  END IF;

  -- GUARD (R03 · Uber, 16/10): Uber mandó solo parte de la entrega (calle,
  -- punto o cargo de envío) y no se sabe quién reparte: lo decide una persona
  -- en el aviso. Hasta entonces, no sale.
  IF v_sale.delivery_by_reason = 'uber_decidir' THEN
    RETURN QUERY SELECT NULL::text, 'falta decidir quién reparte este pedido de Uber'::text;
    RETURN;
  END IF;

  v_rt := CASE WHEN left(btrim(coalesce(v_sale.raw_tab,'')),1)='{' THEN v_sale.raw_tab::jsonb ELSE '{}'::jsonb END;

  -- GUARD (31/08 · R03 16/10): SIN DÓNDE IR NO SE DESPACHA. Desde el R03, «dónde
  -- ir» es la dirección que mandó la plataforma, la que pegó la cocina o, si no
  -- hay ninguna, el PUNTO DEL MAPA: catcher-dispatch lo manda con la calle más
  -- cercana y la nota «Dirección incompleta: llamar al cliente». Solo lo que no
  -- trae ni dirección ni coordenadas se queda sin despachar.
  IF coalesce(btrim(v_sale.delivery_address_fixed), '') = ''
     AND coalesce(btrim(v_sale.delivery_address), '') = ''
     AND (coalesce(nullif(v_rt->'customer'->>'latitude',''), nullif(v_rt->'delivery'->>'latitude','')) IS NULL
          OR coalesce(nullif(v_rt->'customer'->>'longitude',''), nullif(v_rt->'delivery'->>'longitude','')) IS NULL)
  THEN
    RETURN QUERY SELECT NULL::text,
      'la dirección no ha llegado y tampoco el punto del mapa: no se puede despachar'::text;
    RETURN;
  END IF;

  SELECT coalesce(l.dispatch_mode,'auto'), coalesce(l.dispatch_broker,'catcher'), l.lat, l.lng
    INTO v_mode, v_broker, v_llat, v_llng
    FROM public.locations l WHERE l.id = v_sale.location_id;
  v_broker := coalesce(v_broker,'catcher');

  v_dlat := nullif(v_rt->'delivery'->>'latitude','')::numeric;
  v_dlng := nullif(v_rt->'delivery'->>'longitude','')::numeric;
  IF v_llat IS NOT NULL AND v_llng IS NOT NULL AND v_dlat IS NOT NULL AND v_dlng IS NOT NULL THEN
    v_dist := round((2*6371*asin(sqrt(
      power(sin(radians(v_dlat - v_llat)/2),2) +
      cos(radians(v_llat))*cos(radians(v_dlat))*
      power(sin(radians(v_dlng - v_llng)/2),2)
    )))::numeric, 1);
  END IF;

  v_dow  := ((extract(dow FROM (v_now AT TIME ZONE 'Europe/Madrid'))::int) + 6) % 7;
  v_time := (v_now AT TIME ZONE 'Europe/Madrid')::time;

  SELECT * INTO v_rule
  FROM public.dispatch_rule r
  WHERE r.is_active
    AND r.account_id = v_sale.account_id
    AND (r.location_id IS NULL OR r.location_id = v_sale.location_id)
    AND (r.weekdays IS NULL OR v_dow = ANY(r.weekdays))
    AND (r.time_from IS NULL OR r.time_to IS NULL OR
         (CASE WHEN r.time_from <= r.time_to
               THEN v_time >= r.time_from AND v_time < r.time_to
               ELSE v_time >= r.time_from OR  v_time < r.time_to END))
    AND (r.min_total IS NULL OR v_sale.total >= r.min_total)
    AND (r.max_total IS NULL OR v_sale.total <  r.max_total)
  ORDER BY r.priority ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT v_broker, ('sin regla -> broker por defecto ('||v_broker||')')::text; RETURN;
  END IF;

  v_chain := v_rule.carrier_chain;
  IF v_chain IS NULL OR array_length(v_chain,1) IS NULL THEN
    v_chain := array_remove(ARRAY[v_rule.then_carrier, v_rule.fallback_carrier], NULL);
  END IF;
  IF array_length(v_chain,1) IS NULL THEN
    RETURN QUERY SELECT v_broker, ('regla '||v_rule.priority||' sin cadena -> broker por defecto')::text; RETURN;
  END IF;

  FOREACH v_c IN ARRAY v_chain LOOP
    IF v_c = 'own_fleet' THEN
      IF v_rule.max_distance_km IS NOT NULL AND v_dist IS NOT NULL AND v_dist > v_rule.max_distance_km THEN
        CONTINUE;
      END IF;
      SELECT count(*) INTO v_avail
      FROM public.courier c
      WHERE c.account_id = v_sale.account_id AND c.active AND c.on_shift
        AND (c.assigned_locations = '{}'::uuid[] OR v_sale.location_id = ANY(c.assigned_locations));
      IF v_avail > 0 THEN
        RETURN QUERY SELECT 'own_fleet'::text,
          ('regla '||v_rule.priority||' -> propio ('||v_avail||' en turno'||coalesce(', '||v_dist||' km','')||')')::text;
        RETURN;
      END IF;
    ELSE
      RETURN QUERY SELECT v_c, ('regla '||v_rule.priority||' -> '||v_c||' (cadena)')::text;
      RETURN;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_broker,
    ('regla '||v_rule.priority||' -> cadena agotada; broker por defecto ('||v_broker||')')::text;
END;
$$;


--
-- Name: resolve_goods_receipt_line_format(uuid, uuid, uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_goods_receipt_line_format(p_account_id uuid, p_ai_session_id uuid, p_recipe_item_id uuid, p_raw_text text, p_supplier_id uuid, p_created_by uuid DEFAULT NULL::uuid, p_created_by_name text DEFAULT NULL::text) RETURNS TABLE(purchase_format_id uuid, qty_in_base_per_pack numeric, supplier_code text, doc_qty numeric, doc_amount numeric, map_source text, map_needs_review boolean, discrepancy_reason text, ocr_qty_in_base numeric, ficha_qty_in_base numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pack_size numeric;
  v_pack_unit text;
  v_format_name text;
  v_supplier_code text;
  v_doc_qty numeric;
  v_doc_amount numeric;
  v_base_abbr text;
  v_base_dim text;
  v_ocr_qty numeric;
  v_ocr_rule text;
  v_ficha_format_id uuid;
  v_ficha_qty numeric;
  v_ficha_count int;
  v_result_format_id uuid;
  v_result_qty numeric;
  v_map_source text;
  v_needs_review boolean := false;
  v_reason text := null;
begin
  if not belongs_to_account(p_account_id) then
    raise exception 'No autorizado para esta cuenta.';
  end if;

  if p_ai_session_id is not null and p_raw_text is not null and p_raw_text <> '' then
    select (ln->>'pack_size')::numeric, ln->>'pack_unit', ln->>'format_name',
           nullif(ln->>'supplier_code',''),
           coalesce((ln->>'packages')::numeric, (ln->>'quantity')::numeric),
           (ln->>'line_amount')::numeric
      into v_pack_size, v_pack_unit, v_format_name, v_supplier_code, v_doc_qty, v_doc_amount
    from goods_receipt_ai_session s
    cross join lateral jsonb_array_elements(s.parsed_result->'lines') as ln
    where s.id = p_ai_session_id and ln->>'raw_text' = p_raw_text
    limit 1;
  end if;

  if p_recipe_item_id is not null then
    select ku.abbreviation, ku.dimension into v_base_abbr, v_base_dim
    from recipe_item ri join kitchen_unit ku on ku.id = ri.base_unit_id
    where ri.id = p_recipe_item_id;
  end if;

  if v_pack_size is not null and v_base_dim is not null then
    select i.qty_in_base, i.rule_id into v_ocr_qty, v_ocr_rule
    from _interpret_pack_size(v_pack_size, v_pack_unit, coalesce(p_raw_text,''), v_base_abbr, v_base_dim) i;
    if v_ocr_rule = 'NO_RESUELTO' then v_ocr_qty := null; end if;
  end if;

  if p_supplier_id is not null and p_recipe_item_id is not null then
    if v_supplier_code is not null then
      select a.purchase_format_id into v_ficha_format_id
      from article_supplier a
      where a.recipe_item_id = p_recipe_item_id and a.supplier_id = p_supplier_id
        and a.supplier_code = v_supplier_code and a.is_active
      limit 1;
    else
      select count(*) into v_ficha_count
      from article_supplier a
      where a.recipe_item_id = p_recipe_item_id and a.supplier_id = p_supplier_id and a.is_active;
      if v_ficha_count = 1 then
        select a.purchase_format_id into v_ficha_format_id
        from article_supplier a
        where a.recipe_item_id = p_recipe_item_id and a.supplier_id = p_supplier_id and a.is_active
        limit 1;
      end if;
    end if;
    if v_ficha_format_id is not null then
      select f.qty_in_base into v_ficha_qty
      from recipe_item_purchase_format f
      where f.id = v_ficha_format_id and f.is_active;
    end if;
  end if;

  if v_ocr_qty is not null and v_ficha_qty is not null then
    if abs(v_ocr_qty - v_ficha_qty) < 0.01 then
      v_result_format_id := v_ficha_format_id; v_result_qty := v_ficha_qty; v_map_source := 'ocr_ficha_coinciden';
    else
      v_result_format_id := null; v_result_qty := null; v_map_source := 'discrepancia'; v_needs_review := true;
      v_reason := format('El documento dice %s y la ficha dice %s (unidad base).', v_ocr_qty, v_ficha_qty);
    end if;
  elsif v_ocr_qty is not null then
    select f.id into v_result_format_id
    from recipe_item_purchase_format f
    where f.account_id = p_account_id and f.item_id = p_recipe_item_id and f.is_active
      and abs(f.qty_in_base - v_ocr_qty) < 0.01
    limit 1;
    if v_result_format_id is null then
      insert into recipe_item_purchase_format (account_id, item_id, name, qty_in_base, source, needs_review, is_active, created_by, created_by_name)
      values (p_account_id, p_recipe_item_id, coalesce(nullif(v_format_name,''), 'Formato del albarán'), v_ocr_qty, 'albaran', true, true, p_created_by, p_created_by_name)
      returning id into v_result_format_id;
      v_needs_review := true;
    end if;
    v_result_qty := v_ocr_qty; v_map_source := 'ocr';
    if p_supplier_id is not null then
      if v_supplier_code is not null then
        update article_supplier a set
            account_id = p_account_id,
            purchase_format_id = v_result_format_id,
            updated_at = now()
          where a.recipe_item_id = p_recipe_item_id and a.supplier_id = p_supplier_id
            and a.supplier_code = v_supplier_code;
        if not found then
          insert into article_supplier (account_id, recipe_item_id, supplier_id, supplier_code, purchase_format_id, is_active, source)
          values (p_account_id, p_recipe_item_id, p_supplier_id, v_supplier_code, v_result_format_id, true, 'albaran');
        end if;
      else
        update article_supplier a set
            account_id = p_account_id,
            purchase_format_id = v_result_format_id,
            updated_at = now()
          where a.recipe_item_id = p_recipe_item_id and a.supplier_id = p_supplier_id
            and a.supplier_code is null;
        if not found then
          insert into article_supplier (account_id, recipe_item_id, supplier_id, supplier_code, purchase_format_id, is_active, source)
          values (p_account_id, p_recipe_item_id, p_supplier_id, null, v_result_format_id, true, 'albaran');
        end if;
      end if;
    end if;
  elsif v_ficha_qty is not null then
    v_result_format_id := v_ficha_format_id; v_result_qty := v_ficha_qty; v_map_source := 'ficha';
  else
    v_result_format_id := null; v_result_qty := null; v_map_source := 'sin_formato'; v_needs_review := true;
    v_reason := 'Ni el documento ni la ficha del proveedor dicen el formato.';
  end if;

  return query select v_result_format_id, v_result_qty, v_supplier_code, v_doc_qty, v_doc_amount,
                      v_map_source, v_needs_review, v_reason, v_ocr_qty, v_ficha_qty;
end;
$$;


--
-- Name: resolve_mapping_proposals(uuid, text[], numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_mapping_proposals(p_session_id uuid, p_target_types text[] DEFAULT ARRAY['raw'::text, 'recipe'::text], p_fuzzy_min numeric DEFAULT 0.45) RETURNS TABLE(resolved integer, auto_confirmed integer, needs_review integer, no_candidate integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_prop       record;
  v_norm       text;
  v_best_id    uuid;
  v_best_name  text;
  v_best_conf  numeric;
  v_best_method text;
  v_status     text;
  v_resolved   int := 0;
  v_auto       int := 0;
  v_review     int := 0;
  v_none       int := 0;
  v_rank       int;
  v_cand       record;
BEGIN
  -- cuenta de la sesión
  SELECT account_id INTO v_account_id
  FROM recipe_item_ai_session WHERE id = p_session_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'Sesión % no encontrada', p_session_id;
  END IF;

  -- recorrer las propuestas pendientes de esta sesión
  FOR v_prop IN
    SELECT id, source_text, source_normalized
    FROM mapping_proposal
    WHERE source_ref = p_session_id AND status = 'pending'
  LOOP
    v_norm := COALESCE(v_prop.source_normalized,
                       normalize_ingredient_name(v_prop.source_text));
    v_best_id := NULL; v_best_name := NULL; v_best_conf := NULL; v_best_method := NULL;

    -- limpiar candidatos previos de esta propuesta (idempotente)
    DELETE FROM mapping_candidate WHERE proposal_id = v_prop.id;

    -- escribir candidatos (hasta 5) y quedarnos con el mejor
    v_rank := 0;
    FOR v_cand IN
      SELECT ri.id, ri.name,
             CASE
               WHEN normalize_ingredient_name(ri.name) = v_norm THEN 0.99::numeric
               ELSE ROUND(similarity(normalize_ingredient_name(ri.name), v_norm)::numeric, 2)
             END AS conf,
             CASE
               WHEN normalize_ingredient_name(ri.name) = v_norm THEN 'exact'
               ELSE 'fuzzy'
             END AS mt
      FROM recipe_item ri
      WHERE ri.account_id = v_account_id
        AND ri.is_active = true
        AND ri.type = ANY(p_target_types)
        AND (
          normalize_ingredient_name(ri.name) = v_norm
          OR (normalize_ingredient_name(ri.name) % v_norm
              AND similarity(normalize_ingredient_name(ri.name), v_norm) >= p_fuzzy_min)
        )
      ORDER BY conf DESC, ri.name
      LIMIT 5
    LOOP
      v_rank := v_rank + 1;
      INSERT INTO mapping_candidate (proposal_id, target_id, target_label, score, rank, reason)
      VALUES (v_prop.id, v_cand.id, v_cand.name, v_cand.conf, v_rank,
              CASE v_cand.mt WHEN 'exact' THEN 'Nombre coincide'
                             ELSE 'Similitud ' || v_cand.conf END);
      IF v_rank = 1 THEN
        v_best_id := v_cand.id; v_best_name := v_cand.name;
        v_best_conf := v_cand.conf; v_best_method := v_cand.mt;
      END IF;
    END LOOP;

    -- decidir estado según confianza
    IF v_best_id IS NOT NULL AND v_best_conf >= 0.95 THEN
      v_status := 'auto_confirmed'; v_auto := v_auto + 1;
    ELSIF v_best_id IS NOT NULL AND v_best_conf >= 0.55 THEN
      v_status := 'needs_review'; v_review := v_review + 1;
    ELSE
      v_status := 'no_candidate'; v_none := v_none + 1;
      v_best_id := NULL; v_best_method := NULL;
    END IF;

    UPDATE mapping_proposal
    SET chosen_target_id = v_best_id,
        confidence       = v_best_conf,
        method           = COALESCE(v_best_method, 'fuzzy'),
        status           = v_status,
        updated_at       = now()
    WHERE id = v_prop.id;

    v_resolved := v_resolved + 1;
  END LOOP;

  RETURN QUERY SELECT v_resolved, v_auto, v_review, v_none;
END;
$$;


--
-- Name: resolve_payroll_inbox(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_payroll_inbox(p_inbox_id uuid, p_employee_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r        public.payroll_inbox;
  v_status text;
  v_base   numeric;
  v_net    numeric;
  v_cost   uuid;
begin
  select * into r from public.payroll_inbox where id = p_inbox_id;
  if not found then raise exception 'Nómina no encontrada'; end if;
  if not current_user_is_admin_of(r.account_id) then
    raise exception 'Sin permiso para esta cuenta';
  end if;
  if r.period_year is null or r.period_month is null then
    raise exception 'La nómina no tiene periodo legible; no se puede asignar';
  end if;

  v_status := case when coalesce((r.raw->'parsed'->'payslip'->>'is_draft')::boolean, false)
                   then 'borrador' else 'definitiva' end;
  v_base := (r.raw->'parsed'->'payslip'->>'contribution_base')::numeric;
  v_net  := coalesce((r.raw->'validation'->>'net')::numeric,
                     (r.raw->'parsed'->'payslip'->>'net')::numeric);

  insert into public.payroll_cost (
    account_id, employee_id, period_year, period_month, status,
    gross, employer_ss, total_cost, contribution_base, net,
    source, document_id, needs_review, raw
  ) values (
    r.account_id, p_employee_id, r.period_year, r.period_month, v_status,
    r.gross, r.employer_ss, r.total_cost, v_base, v_net,
    r.source, r.document_id, false, r.raw
  )
  on conflict (employee_id, period_year, period_month, status) do update set
    gross = excluded.gross, employer_ss = excluded.employer_ss, total_cost = excluded.total_cost,
    contribution_base = excluded.contribution_base, net = excluded.net,
    needs_review = false, document_id = excluded.document_id, raw = excluded.raw,
    updated_at = now()
  returning id into v_cost;

  -- Si la ficha no tenía DNI y la IA leyó uno, se lo ponemos (futuras casan solas).
  if r.read_dni is not null and length(btrim(r.read_dni)) > 0 then
    update public.employees set dni = r.read_dni
    where id = p_employee_id and (dni is null or btrim(dni) = '');
  end if;

  update public.payroll_inbox set
    status = 'resolved', matched_employee_id = p_employee_id, payroll_cost_id = v_cost,
    resolved_at = now(), resolved_by = auth.uid(), updated_at = now()
  where id = p_inbox_id;

  return v_cost;
end;
$$;


--
-- Name: resolve_sale_brand_from_map(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_sale_brand_from_map(p_sale_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc        uuid;
  v_ext_brand  text;
  v_ext_loc    text;
  v_brand      uuid;
  v_ignored    boolean;
BEGIN
  SELECT account_id, external_brand_text, external_location_text
    INTO v_acc, v_ext_brand, v_ext_loc
  FROM sale WHERE id = p_sale_id;
  IF v_acc IS NULL THEN RETURN; END IF;

  -- Histórico: si la venta no tiene el id de marca crudo en la columna (solo se
  -- puebla desde el eslabón 1), lo recuperamos del log por external_ref.
  IF v_ext_brand IS NULL OR v_ext_loc IS NULL THEN
    SELECT
      COALESCE(v_ext_brand, l.payload->'data'->>'locationBrandId'),
      COALESCE(v_ext_loc,   l.payload->'data'->>'locationId')
      INTO v_ext_brand, v_ext_loc
    FROM lastapp_webhook_log l
    WHERE l.payload->'data'->>'id' = (SELECT external_ref FROM sale WHERE id = p_sale_id)
    LIMIT 1;
  END IF;

  IF v_ext_brand IS NULL THEN RETURN; END IF;

  -- Buscar la decisión en el mapa: vinculada (brand_id) o ignorada.
  SELECT brand_id, is_ignored INTO v_brand, v_ignored
  FROM external_brand_map
  WHERE account_id = v_acc
    AND source = 'lastapp'
    AND external_location_id = v_ext_loc
    AND external_brand_id = v_ext_brand
  LIMIT 1;

  -- Si hay vínculo real (no ignorada), esa marca manda.
  IF v_brand IS NOT NULL AND COALESCE(v_ignored, false) = false THEN
    UPDATE sale SET brand_id = v_brand WHERE id = p_sale_id AND brand_id IS DISTINCT FROM v_brand;
  END IF;
END;
$$;


--
-- Name: resolve_unmapped_sales(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_unmapped_sales(p_account_id uuid, p_product_name text, p_action text, p_reason text DEFAULT NULL::text, p_brand_id uuid DEFAULT NULL::uuid) RETURNS TABLE(resultado text, menu_item_id uuid, recipe_item_id uuid, brand_id uuid, lineas_afectadas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_norm text; v_afect integer := 0; v_core record;
BEGIN
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'resolve_unmapped_sales: sin acceso a la cuenta %', p_account_id;
  END IF;
  IF p_action NOT IN ('link','ignore','delist') THEN
    RAISE EXCEPTION 'resolve_unmapped_sales: acción inválida %', p_action;
  END IF;

  v_norm := public.sales_product_norm(p_product_name);

  IF p_action IN ('ignore','delist') THEN
    UPDATE sale_line sl
    SET unmapped_reason = CASE WHEN p_action = 'ignore' THEN 'ignored' ELSE 'delisted' END,
        ignore_reason = nullif(btrim(coalesce(p_reason,'')), ''),
        ignored_at = now(), map_needs_review = false, updated_at = now()
    FROM sale s
    WHERE sl.sale_id = s.id AND sl.account_id = p_account_id AND s.source = 'lastapp'
      AND sl.menu_item_id IS NULL AND coalesce(sl.line_type,'product') = 'product'
      AND sl.map_source <> 'manual'
      AND (p_brand_id IS NULL OR s.brand_id = p_brand_id)
      AND public.sales_product_norm(sl.product_name) = v_norm;
    GET DIAGNOSTICS v_afect = ROW_COUNT;
    RETURN QUERY SELECT CASE WHEN p_action='ignore' THEN 'ignored' ELSE 'delisted' END,
                        NULL::uuid, NULL::uuid, p_brand_id, v_afect;
    RETURN;
  END IF;

  SELECT * INTO v_core
    FROM public._resolve_unmapped_link_core(p_account_id, p_product_name, p_brand_id);

  -- Recast GLOBAL, como siempre. Ojo: reprocesa todas las ventas de Last de la
  -- cuenta. Para la bandeja usa resolve_unmapped_sales_scoped.
  PERFORM public.recast_lastapp_sales(p_account_id);

  SELECT count(*) INTO v_afect
  FROM sale_line sl JOIN sale s ON s.id = sl.sale_id
  WHERE sl.account_id = p_account_id AND s.source = 'lastapp'
    AND sl.menu_item_id = v_core.menu_item_id
    AND public.sales_product_norm(sl.product_name) = v_norm;

  RETURN QUERY SELECT 'linked'::text, v_core.menu_item_id, v_core.recipe_item_id,
                      v_core.brand_id, v_afect;
END;
$$;


--
-- Name: FUNCTION resolve_unmapped_sales(p_account_id uuid, p_product_name text, p_action text, p_reason text, p_brand_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_unmapped_sales(p_account_id uuid, p_product_name text, p_action text, p_reason text, p_brand_id uuid) IS 'Resuelve un producto ciego (link|ignore|delist) en el modelo canónico. ignore/delist marcan estado (acotable a marca). link resuelve/crea menu_item SELLADO por matrícula (sin product_map) y recasa. Anti-invención: EXCEPTION sin matrícula/marca o si es combo.';


--
-- Name: resolve_unmapped_sales_scoped(uuid, text, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_unmapped_sales_scoped(p_account_id uuid, p_product_name text, p_action text, p_reason text DEFAULT NULL::text, p_brand_id uuid DEFAULT NULL::uuid, p_include_before_last_count boolean DEFAULT false) RETURNS TABLE(resultado text, menu_item_id uuid, recipe_item_id uuid, brand_id uuid, ventas_reprocesadas integer, ventas_protegidas integer, euros_protegidos numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_core record; v_rep record;
BEGIN
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'resolve_unmapped_sales_scoped: sin acceso a la cuenta %', p_account_id;
  END IF;
  IF p_action NOT IN ('link','ignore','delist') THEN
    RAISE EXCEPTION 'resolve_unmapped_sales_scoped: acción inválida %', p_action;
  END IF;

  IF p_action IN ('ignore','delist') THEN
    RETURN QUERY
      SELECT r2.resultado, r2.menu_item_id, r2.recipe_item_id, r2.brand_id,
             0, 0, 0::numeric
        FROM public.resolve_unmapped_sales(p_account_id, p_product_name, p_action, p_reason, p_brand_id) r2;
    RETURN;
  END IF;

  SELECT * INTO v_core
    FROM public._resolve_unmapped_link_core(p_account_id, p_product_name, p_brand_id);

  SELECT * INTO v_rep
    FROM public._reprocess_product_sales_scoped(p_account_id, p_product_name, p_include_before_last_count);

  resultado := 'linked';
  menu_item_id := v_core.menu_item_id;
  recipe_item_id := v_core.recipe_item_id;
  brand_id := v_core.brand_id;
  ventas_reprocesadas := v_rep.ventas_reprocesadas;
  ventas_protegidas   := v_rep.ventas_protegidas;
  euros_protegidos    := v_rep.euros_protegidos;
  RETURN NEXT;
END;
$$;


--
-- Name: resolver_opcion_de_extra(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolver_opcion_de_extra(p_account_id uuid, p_menu_item_id uuid, p_brand_id uuid, p_ref text, p_name text, p_source text) RETURNS TABLE(option_id uuid, como text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id   uuid;
  v_norm text := public._extra_nombre_normalizado(p_name);
  v_ref  text := nullif(btrim(coalesce(p_ref, '')), '');
BEGIN
  -- ── 1 · por codigo, dentro de las preguntas de ese plato ────────────────
  IF v_ref IS NOT NULL AND p_menu_item_id IS NOT NULL THEN
    SELECT mo.id INTO v_id
      FROM public.modifier_group_assignment mga
      JOIN public.modifier_group mg ON mg.id = mga.modifier_group_id
      JOIN public.modifier_option mo ON mo.modifier_group_id = mg.id
     WHERE mga.menu_item_id = p_menu_item_id
       AND mo.account_id = p_account_id
       AND CASE p_source
             WHEN 'lastapp' THEN mo.pos_modifier_id = v_ref
             WHEN 'hubrise' THEN public._modifier_option_ref(mo.id) = v_ref
             WHEN 'folvy'   THEN mo.id::text = v_ref
             ELSE false
           END
     ORDER BY (mo.is_active AND mg.is_active) DESC,  -- la viva, si la hay
              mo.id                                   -- desempate FIJO
     LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN QUERY SELECT v_id, 'pos'::text; RETURN;
    END IF;
  END IF;

  -- ── 2 · por codigo, en cualquier opcion de la cuenta ────────────────────
  --
  -- Aqui es donde entran los extras de un plato que Folvy todavia no tiene
  -- enlazado: son las 18 lineas cedidas del 11/09 (9 del burrito de birria de
  -- Dos Coyotes, 8 de los tequeños de Ay Mamita, 1 del Cochinita Bowl y 1 de
  -- las Classic French Fries). Enlazar ESOS PLATOS es otro encargo (D12); sus
  -- extras se enlazan igual por aqui.
  IF v_ref IS NOT NULL THEN
    SELECT mo.id INTO v_id
      FROM public.modifier_option mo
      JOIN public.modifier_group mg ON mg.id = mo.modifier_group_id
     WHERE mo.account_id = p_account_id
       AND CASE p_source
             WHEN 'lastapp' THEN mo.pos_modifier_id = v_ref
             WHEN 'hubrise' THEN public._modifier_option_ref(mo.id) = v_ref
             WHEN 'folvy'   THEN mo.id::text = v_ref
             ELSE false
           END
     ORDER BY
       (mo.is_active AND mg.is_active) DESC,          -- la viva, si la hay
       (mg.brand_id IS NOT DISTINCT FROM p_brand_id) DESC,
       (EXISTS (SELECT 1 FROM public.modifier_recipe_impact mri
                 WHERE mri.modifier_option_id = mo.id AND mri.status = 'confirmed')) DESC,
       mo.id
     LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN QUERY SELECT v_id, 'pos'::text; RETURN;
    END IF;
  END IF;

  -- ── 3 · por nombre, SOLO en la marca del pedido y SOLO activas ──────────
  --
  -- Aqui NO se cae a las retiradas: por nombre no hay identidad, hay parecido,
  -- y resucitar una opcion que alguien retiro porque se parece de nombre es
  -- exactamente lo contrario de lo que se busca.
  --
  -- Lo que desaparece respecto a hoy: «en toda la cuenta» y «activas o no».
  -- Sin marca del pedido no se busca por nombre: preferimos una linea sin
  -- enlazar y con motivo a una linea enlazada a la copia de otra marca, que
  -- es lo que descuenta del almacen equivocado.
  IF v_norm <> '' AND p_brand_id IS NOT NULL THEN
    SELECT mo.id INTO v_id
      FROM public.modifier_option mo
      JOIN public.modifier_group mg ON mg.id = mo.modifier_group_id
     WHERE mo.account_id = p_account_id
       AND mo.is_active AND mg.is_active
       AND mg.brand_id = p_brand_id
       AND public._extra_nombre_normalizado(mo.name) = v_norm
     ORDER BY
       (EXISTS (SELECT 1 FROM public.modifier_group_assignment mga
                 WHERE mga.modifier_group_id = mg.id
                   AND mga.menu_item_id IS NOT DISTINCT FROM p_menu_item_id)) DESC,
       (EXISTS (SELECT 1 FROM public.modifier_recipe_impact mri
                 WHERE mri.modifier_option_id = mo.id AND mri.status = 'confirmed')) DESC,
       mo.id
     LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN QUERY SELECT v_id, 'fuzzy'::text; RETURN;
    END IF;
  END IF;

  -- ── 4 · nada ────────────────────────────────────────────────────────────
  RETURN QUERY SELECT NULL::uuid, NULL::text;
END;
$$;


--
-- Name: responder_aviso_olvido(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.responder_aviso_olvido(p_log_id uuid, p_respuesta text, p_hora timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l public.clockout_reminder_log;
begin
  select * into l from public.clockout_reminder_log where id = p_log_id;
  if not found or not public.current_user_is_employee(l.employee_id, l.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'Solo puedes contestar tus propios avisos.';
  end if;
  if p_respuesta = 'otra_hora' and p_hora is null then
    raise exception 'FALTA_LA_HORA' using errcode = '22023', hint = 'Di a qué hora saliste.';
  end if;
  return public._aviso_olvido_responder(p_log_id, p_respuesta, p_hora, 'portal');
end $$;


--
-- Name: responder_aviso_olvido_whatsapp(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.responder_aviso_olvido_whatsapp(p_log_id uuid, p_respuesta text, p_telefono text, p_contexto_wamid text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l public.clockout_reminder_log;
  v_a text := right(regexp_replace(coalesce(p_telefono, ''), '\D', '', 'g'), 9);
  v_b text;
begin
  select * into l from public.clockout_reminder_log where id = p_log_id;
  if not found then
    return jsonb_build_object('resultado', 'no_existe', 'texto', 'No encontramos ese aviso. Si te falta la salida, pídela desde tu portal.');
  end if;
  v_b := right(regexp_replace(coalesce(l.to_phone, ''), '\D', '', 'g'), 9);
  if length(v_a) < 9 or v_a <> v_b then
    return jsonb_build_object('resultado', 'otro_telefono', 'texto', 'Este aviso no era para este número.');
  end if;
  if p_contexto_wamid is not null and l.provider_message_id is not null and p_contexto_wamid <> l.provider_message_id then
    return jsonb_build_object('resultado', 'otro_mensaje', 'texto', 'Este aviso no era para este número.');
  end if;
  return public._aviso_olvido_responder(p_log_id, p_respuesta, null, 'whatsapp');
end $$;


--
-- Name: FUNCTION responder_aviso_olvido_whatsapp(p_log_id uuid, p_respuesta text, p_telefono text, p_contexto_wamid text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.responder_aviso_olvido_whatsapp(p_log_id uuid, p_respuesta text, p_telefono text, p_contexto_wamid text) IS 'L1a PR 3: la respuesta de un toque al WhatsApp del olvido (la llama whatsapp-webhook, después de comprobar la firma de Meta). Crea la petición de corrección; nunca el fichaje.';


--
-- Name: responder_correccion(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.responder_correccion(p_audit_id uuid, p_conforme boolean, p_nota text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.clock_entry_audit;
begin
  select * into a from public.clock_entry_audit where id = p_audit_id for update;
  if a.id is null then
    raise exception 'CORRECCION_NO_EXISTE' using errcode = '22023', hint = 'Esa corrección ya no existe.';
  end if;
  if not public.current_user_is_employee(a.employee_id, a.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501', hint = 'Solo la persona del fichaje puede decir si está de acuerdo.';
  end if;
  if a.conformidad is distinct from 'pendiente' then
    raise exception 'YA_RESPONDIDA' using errcode = '22023', hint = 'Ya dijiste si estabas de acuerdo con esta corrección.';
  end if;
  update public.clock_entry_audit
     set conformidad = case when p_conforme then 'conforme' else 'desacuerdo' end,
         conformidad_at = now(),
         conformidad_nota = nullif(trim(coalesce(p_nota, '')), '')
   where id = p_audit_id
   returning * into a;
  return jsonb_build_object('id', a.id, 'conformidad', a.conformidad, 'conformidad_at', a.conformidad_at);
end $$;


--
-- Name: rest_safety_margin_for(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rest_safety_margin_for(p_account uuid, p_location uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT bp.rest_safety_margin_minutes FROM public.break_policy bp
      WHERE bp.account_id = p_account AND bp.location_id = p_location LIMIT 1),
    (SELECT bp.rest_safety_margin_minutes FROM public.break_policy bp
      WHERE bp.account_id = p_account AND bp.location_id IS NULL LIMIT 1),
    (SELECT bp.rest_safety_margin_minutes FROM public.break_policy bp
      WHERE bp.account_id = p_account LIMIT 1),
    30);
$$;


--
-- Name: restore_recipe_version(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_recipe_version(p_version_id uuid, p_created_by_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ver       recipe_item_version%ROWTYPE;
  v_item_id   uuid;
  v_account   uuid;
  v_snap      jsonb;
  v_line      jsonb;
  v_step      jsonb;
  v_sl        jsonb;
  v_new_line  uuid;
  v_new_step  uuid;
  v_line_map  jsonb := '{}'::jsonb;
  v_step_map  jsonb := '{}'::jsonb;
  v_new_active uuid;
BEGIN
  IF p_version_id IS NULL THEN
    RAISE EXCEPTION 'restore_recipe_version: falta el id de la versión';
  END IF;

  SELECT * INTO v_ver FROM recipe_item_version WHERE id = p_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'restore_recipe_version: versión % no encontrada', p_version_id;
  END IF;

  v_item_id := v_ver.recipe_item_id;
  SELECT account_id INTO v_account FROM recipe_item WHERE id = v_item_id;

  IF NOT public.current_user_is_admin_or_manager_of(v_account) THEN
    RAISE EXCEPTION 'Sin permiso para restaurar esta receta';
  END IF;

  v_snap := v_ver.snapshot;

  -- 1) RED: versiona el estado ACTUAL antes de sobrescribir (no se pierde nada).
  PERFORM public.create_recipe_version(
    v_item_id,
    'Antes de restaurar a v' || v_ver.version_number::text,
    NULL, false, p_created_by_name
  );

  -- 2) Sobrescribe líneas + pasos + enlaces desde el snapshot objetivo.
  --    Orden de borrado: enlaces → pasos → líneas (por las FK).
  DELETE FROM recipe_item_step_line
   WHERE step_id IN (SELECT id FROM recipe_item_step WHERE recipe_item_id = v_item_id);
  DELETE FROM recipe_item_step WHERE recipe_item_id = v_item_id;
  DELETE FROM recipe_line WHERE parent_item_id = v_item_id;

  -- Líneas (mapa id_snapshot → id_nuevo para reconstruir enlaces).
  FOR v_line IN SELECT * FROM jsonb_array_elements(COALESCE(v_snap->'lines', '[]'::jsonb))
  LOOP
    INSERT INTO recipe_line (
      account_id, parent_item_id, child_item_id,
      quantity_net, quantity_gross, unit_id, cut_type_id, comment, position
    )
    VALUES (
      v_account, v_item_id,
      (v_line->>'child_item_id')::uuid,
      NULLIF(v_line->>'quantity_net','')::numeric,
      NULLIF(v_line->>'quantity_gross','')::numeric,
      NULLIF(v_line->>'unit_id','')::uuid,
      NULLIF(v_line->>'cut_type_id','')::uuid,
      v_line->>'comment',
      COALESCE(NULLIF(v_line->>'position','')::int, 0)
    )
    RETURNING id INTO v_new_line;
    v_line_map := v_line_map || jsonb_build_object(v_line->>'id', v_new_line::text);
  END LOOP;

  -- Pasos (mapa id_snapshot → id_nuevo).
  FOR v_step IN SELECT * FROM jsonb_array_elements(COALESCE(v_snap->'steps', '[]'::jsonb))
  LOOP
    INSERT INTO recipe_item_step (
      recipe_item_id, position, text, kind, duration_min, temperature_c, photo_url
    )
    VALUES (
      v_item_id,
      COALESCE(NULLIF(v_step->>'position','')::int, 0),
      v_step->>'text',
      v_step->>'kind',
      NULLIF(v_step->>'duration_min','')::int,
      NULLIF(v_step->>'temperature_c','')::numeric,
      v_step->>'photo_url'
    )
    RETURNING id INTO v_new_step;
    v_step_map := v_step_map || jsonb_build_object(v_step->>'id', v_new_step::text);
  END LOOP;

  -- Enlaces paso↔línea (solo si ambos extremos existen en los mapas).
  FOR v_sl IN SELECT * FROM jsonb_array_elements(COALESCE(v_snap->'step_lines', '[]'::jsonb))
  LOOP
    IF (v_step_map ? (v_sl->>'step_id')) AND (v_line_map ? (v_sl->>'line_id')) THEN
      INSERT INTO recipe_item_step_line (account_id, step_id, line_id)
      VALUES (
        v_account,
        (v_step_map->>(v_sl->>'step_id'))::uuid,
        (v_line_map->>(v_sl->>'line_id'))::uuid
      );
    END IF;
  END LOOP;

  -- Meta del plato que afecta al coste por ración (no se toca el nombre).
  UPDATE recipe_item
     SET yield_portions = NULLIF(v_snap->>'yield_portions','')::numeric
   WHERE id = v_item_id;

  -- 3) Recostea el plato (cascada).
  PERFORM public.kitchen_recompute_item(v_item_id);

  -- 4) Versiona el estado RESTAURADO → queda como versión activa coherente.
  v_new_active := public.create_recipe_version(
    v_item_id,
    'Restaurada de v' || v_ver.version_number::text,
    v_ver.milestone_label,
    false, p_created_by_name
  );

  RETURN v_new_active;
END;
$$;


--
-- Name: retire_stale_agent_shop_offers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retire_stale_agent_shop_offers(p_account_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ids uuid[];
  v_n   integer;
begin
  select array_agg(id) into v_ids
  from coupon
  where account_id = p_account_id
    and origin = 'agent'
    and active = false
    and kind in ('item_percent', 'free_item')
    and 'shop' = any(channels)
    and (created_at at time zone 'Europe/Madrid')::date
        < (now() at time zone 'Europe/Madrid')::date;

  if v_ids is null then return 0; end if;

  delete from campaign_scope where coupon_id = any(v_ids);
  delete from coupon         where id = any(v_ids);

  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


--
-- Name: revert_price_operation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_price_operation(p_operation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_op      price_operation%rowtype;
  v_new_id  uuid := gen_random_uuid();
  v_bad     text;
  v_n       int;
  v_writes  int;
  r         record;
begin
  select * into v_op from price_operation where id = p_operation_id;
  if not found then
    raise exception 'Operacion % no encontrada', p_operation_id;
  end if;

  if not (current_user_is_admin() or current_user_is_admin_or_manager_of(v_op.account_id)) then
    raise exception 'Sin permiso para deshacer operaciones de esta cuenta';
  end if;

  if v_op.kind = 'revert' then
    raise exception 'No se puede deshacer un deshacer (operacion % es kind=revert)', p_operation_id;
  end if;

  if exists (select 1 from price_operation where reverted_operation_id = p_operation_id) then
    raise exception 'La operacion % ya fue deshecha', p_operation_id;
  end if;

  select count(*) into v_n
    from menu_item_override_history where operation_id = p_operation_id;
  if v_n = 0 then
    raise exception 'La operacion % no tiene cambios que deshacer', p_operation_id;
  end if;

  -- ── conflicto: el estado actual tiene que ser EXACTAMENTE el que dejo la
  -- operacion. Si alguien toco una celda despues, se aborta entera: deshacer a
  -- medias es peor que no deshacer.
  select string_agg(txt, E'\n') into v_bad from (
    select format('  %s / canal %s%s: la operacion dejo %s, ahora hay %s',
             h.menu_item_id, h.channel_id,
             case when h.location_id is null then '' else ' / local '||h.location_id end,
             case when h.op = 'delete' then 'sin override' else coalesce(h.price_after::text,'null') end,
             coalesce((select mio.price::text from menu_item_override mio
                        where mio.menu_item_id = h.menu_item_id
                          and coalesce(mio.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
                              = coalesce(h.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
                          and coalesce(mio.location_id, '00000000-0000-0000-0000-000000000000'::uuid)
                              = coalesce(h.location_id, '00000000-0000-0000-0000-000000000000'::uuid)),
                      'sin override')) as txt
    from menu_item_override_history h
    where h.operation_id = p_operation_id
      and case
            when h.op = 'delete' then
              exists (select 1 from menu_item_override mio
                       where mio.menu_item_id = h.menu_item_id
                         and coalesce(mio.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
                             = coalesce(h.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
                         and coalesce(mio.location_id, '00000000-0000-0000-0000-000000000000'::uuid)
                             = coalesce(h.location_id, '00000000-0000-0000-0000-000000000000'::uuid))
            else
              not exists (select 1 from menu_item_override mio
                           where mio.menu_item_id = h.menu_item_id
                             and coalesce(mio.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
                                 = coalesce(h.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
                             and coalesce(mio.location_id, '00000000-0000-0000-0000-000000000000'::uuid)
                                 = coalesce(h.location_id, '00000000-0000-0000-0000-000000000000'::uuid)
                             and mio.price IS NOT DISTINCT FROM h.price_after
                             and mio.is_available IS NOT DISTINCT FROM h.is_available_after)
          end
  ) c;
  if v_bad is not null then
    raise exception E'Alguien toco estas celdas despues de la operacion. No se ha deshecho NADA.\n%', v_bad;
  end if;

  -- ── restaurar bajo un operation_id NUEVO ───
  perform set_config('folvy.operation_id', v_new_id::text, true);

  insert into price_operation (id, account_id, kind, actor, scope, entries_count, writes_count,
                               reverted_operation_id, note)
  values (v_new_id, v_op.account_id, 'revert', auth.uid(),
          jsonb_build_object('deshace', p_operation_id, 'scope_original', v_op.scope),
          v_n, 0, p_operation_id,
          format('Deshace la operacion %s', p_operation_id));

  for r in
    select * from menu_item_override_history
     where operation_id = p_operation_id
     order by changed_at desc, id desc
  loop
    if r.op = 'insert' then
      -- antes no existia: se borra
      delete from menu_item_override
       where menu_item_id = r.menu_item_id
         and coalesce(channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
             = coalesce(r.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
         and coalesce(location_id, '00000000-0000-0000-0000-000000000000'::uuid)
             = coalesce(r.location_id, '00000000-0000-0000-0000-000000000000'::uuid);

    elsif r.op = 'update' then
      update menu_item_override
         set price = r.price_before, is_available = r.is_available_before
       where menu_item_id = r.menu_item_id
         and coalesce(channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
             = coalesce(r.channel_id,  '00000000-0000-0000-0000-000000000000'::uuid)
         and coalesce(location_id, '00000000-0000-0000-0000-000000000000'::uuid)
             = coalesce(r.location_id, '00000000-0000-0000-0000-000000000000'::uuid);

    else -- 'delete': se vuelve a crear tal como estaba
      insert into menu_item_override (account_id, menu_item_id, channel_id, location_id, price, is_available)
      values (r.account_id, r.menu_item_id, r.channel_id, r.location_id, r.price_before, r.is_available_before);
    end if;
  end loop;

  select count(*) into v_writes
    from menu_item_override_history where operation_id = v_new_id;
  update price_operation set writes_count = v_writes where id = v_new_id;

  return v_new_id;
end;
$$;


--
-- Name: revert_sale_consumption(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_sale_consumption(p_sale_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sale     sale%ROWTYPE;
  v_fecha    timestamptz;
  v_legacy   boolean;
  v_previos  uuid[] := '{}';
  v_libres   uuid[] := '{}';
  v_protegidos uuid[] := '{}';
  v_cortes   timestamptz[] := '{}';
  v_deleted  integer := 0;
  v_n        integer := 0;
  v_item     uuid;
BEGIN
  SELECT * INTO v_sale FROM sale WHERE id = p_sale_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- GUARDA DE CUENTA, y con una excepcion que hay que decir en voz alta.
  -- `belongs_to_account` se apoya en `auth.uid()`: MEDIDO, sin JWT devuelve
  -- FALSE (rol postgres, uid NULL -> false). Y a esta funcion la llama
  -- `cancel_sale`, que es lo que ejecutan los webhooks de Last y de HubRise
  -- con service_role y sin JWT. Una guarda a secas aqui tumbaria TODAS las
  -- anulaciones que llegan de las plataformas — el camino que ya se rompio en
  -- silencio el 13/08.
  -- Asi que la guarda muerde cuando hay una persona detras, y la puerta se
  -- cierra por el otro lado: a `authenticated` se le quita el EXECUTE, porque
  -- el front no la llama (barrido del 11/09: solo aparece en los tipos
  -- generados). Sin persona y sin front, quien queda es el motor.
  IF auth.uid() IS NOT NULL AND NOT public.belongs_to_account(v_sale.account_id) THEN
    RAISE EXCEPTION 'revert_sale_consumption: sin acceso a la cuenta de la venta %', p_sale_id;
  END IF;

  v_fecha  := COALESCE(v_sale.created_at, now());
  v_legacy := v_fecha < public._corte_motor_viejo();

  SELECT COALESCE(array_agg(DISTINCT sm.recipe_item_id), '{}') INTO v_previos
    FROM public.stock_movement sm
   WHERE sm.movement_type = 'consumo' AND sm.source_type = 'sale'
     AND sm.source_id = p_sale_id AND sm.recipe_item_id IS NOT NULL;
  IF v_legacy THEN
    SELECT COALESCE(array_agg(DISTINCT sm.recipe_item_id), '{}') || v_previos
      INTO v_previos
      FROM public.stock_movement sm
     WHERE sm.movement_type = 'consumo' AND sm.source_type = 'sale'
       AND sm.source_id IN (SELECT id FROM public.sale_line WHERE sale_id = p_sale_id)
       AND sm.recipe_item_id IS NOT NULL;
    -- Mismo motivo que en el escritor: sin esto, un ingrediente que este bajo
    -- las dos llaves rompe la nota con 21000.
    SELECT COALESCE(array_agg(DISTINCT x), '{}') INTO v_previos FROM unnest(v_previos) x;
  END IF;
  IF array_length(v_previos, 1) IS NULL THEN RETURN 0; END IF;

  SELECT COALESCE(array_agg(i.item)  FILTER (WHERE c.corte IS NULL OR v_fecha >= c.corte), '{}'),
         COALESCE(array_agg(i.item)  FILTER (WHERE c.corte IS NOT NULL AND v_fecha < c.corte), '{}'),
         COALESCE(array_agg(c.corte) FILTER (WHERE c.corte IS NOT NULL AND v_fecha < c.corte), '{}')
    INTO v_libres, v_protegidos, v_cortes
    FROM unnest(v_previos) AS i(item)
    LEFT JOIN public.cortes_aprobados(v_sale.location_id, v_previos) c
           ON c.recipe_item_id = i.item;

  IF array_length(v_protegidos, 1) IS NOT NULL THEN
    INSERT INTO public.sale_consumption_skip
      (account_id, sale_id, recipe_item_id, location_id, fecha_venta, corte, motivo)
    SELECT v_sale.account_id, p_sale_id, x.item, v_sale.location_id, v_fecha, x.corte,
           'anulacion por debajo del corte: no se devuelve stock, el recuento posterior ya conto lo que habia'
      FROM unnest(v_protegidos, v_cortes) AS x(item, corte)
    ON CONFLICT (sale_id, recipe_item_id) DO UPDATE
      SET corte = EXCLUDED.corte, fecha_venta = EXCLUDED.fecha_venta,
          motivo = EXCLUDED.motivo, created_at = now();
  END IF;

  IF array_length(v_libres, 1) IS NOT NULL THEN
    DELETE FROM public.stock_movement sm
     WHERE sm.movement_type = 'consumo' AND sm.source_type = 'sale'
       AND sm.source_id = p_sale_id AND sm.recipe_item_id = ANY(v_libres);
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    IF v_legacy THEN
      DELETE FROM public.stock_movement sm
       WHERE sm.movement_type = 'consumo' AND sm.source_type = 'sale'
         AND sm.source_id IN (SELECT id FROM public.sale_line WHERE sale_id = p_sale_id)
         AND sm.recipe_item_id = ANY(v_libres);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_deleted := v_deleted + v_n;
    END IF;
  END IF;

  IF v_sale.location_id IS NOT NULL THEN
    FOREACH v_item IN ARRAY v_previos
    LOOP
      PERFORM public.recompute_location_stock_core(v_item, v_sale.location_id);
    END LOOP;
  END IF;

  RETURN v_deleted;
END;
$$;


--
-- Name: revocar_enlace_inspeccion(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revocar_enlace_inspeccion(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare x public.registro_jornada_enlace;
begin
  select * into x from public.registro_jornada_enlace where token = p_token for update;
  if x.token is null or not public.current_user_is_admin_of(x.account_id) then
    raise exception 'NO_AUTORIZADO' using errcode = '42501';
  end if;
  update public.registro_jornada_enlace set revocado_at = coalesce(revocado_at, now()) where token = p_token returning * into x;
  return jsonb_build_object('token', x.token, 'revocado_at', x.revocado_at);
end $$;


--
-- Name: run_invoice_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_invoice_match(p_invoice_id uuid) RETURNS TABLE(match_status text, lines_total integer, lines_ok integer, lines_diff_price integer, lines_diff_qty integer, lines_not_received integer, lines_vat_bad integer, lines_unmatched integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
  v_invoice_date date;
  v_threshold numeric;
  v_line record;
  v_alb_qty numeric;
  v_alb_cost numeric;
  v_alb_line uuid;
  v_alb_count integer;
  v_expected_vat numeric;
  v_result text;
  v_detail jsonb;
  c_total integer := 0; c_ok integer := 0; c_dp integer := 0; c_dq integer := 0;
  c_nr integer := 0; c_vat integer := 0; c_un integer := 0;
  v_status text;
BEGIN
  SELECT account_id, invoice_date INTO v_account_id, v_invoice_date
    FROM public.supplier_invoice WHERE id = p_invoice_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'Factura % no encontrada', p_invoice_id;
  END IF;
  IF v_invoice_date IS NULL THEN v_invoice_date := current_date; END IF;

  SELECT COALESCE(price_alert_pct, 15) INTO v_threshold
    FROM public.supply_settings WHERE account_id = v_account_id;
  IF v_threshold IS NULL THEN v_threshold := 15; END IF;

  FOR v_line IN
    SELECT id, recipe_item_id, qty, unit_price, vat_pct
      FROM public.supplier_invoice_line
      WHERE supplier_invoice_id = p_invoice_id
  LOOP
    c_total := c_total + 1;
    v_result := NULL; v_detail := '{}'::jsonb; v_alb_line := NULL;

    IF v_line.recipe_item_id IS NULL THEN
      v_result := 'sin_casar';
      c_un := c_un + 1;
    ELSE
      SELECT
        COALESCE(SUM(grl.qty_received), 0),
        CASE WHEN COALESCE(SUM(grl.qty_received),0) > 0
             THEN SUM(grl.unit_cost * grl.qty_received) / NULLIF(SUM(grl.qty_received),0)
             ELSE AVG(grl.unit_cost) END,
        COUNT(*),
        MIN(grl.id)
      INTO v_alb_qty, v_alb_cost, v_alb_count, v_alb_line
      FROM public.goods_receipt_line grl
      WHERE grl.recipe_item_id = v_line.recipe_item_id
        AND grl.goods_receipt_id IN (
          SELECT goods_receipt_id FROM public.supplier_invoice_receipt
          WHERE supplier_invoice_id = p_invoice_id
        );

      v_expected_vat := NULL;
      SELECT rate INTO v_expected_vat
      FROM public.vat_rate_for(
        (SELECT vat_category_id FROM public.recipe_item WHERE id = v_line.recipe_item_id),
        v_invoice_date
      );

      IF v_alb_count IS NULL OR v_alb_count = 0 THEN
        v_result := 'no_recibido';
        v_detail := jsonb_build_object('invoiced_qty', v_line.qty, 'received_qty', 0);
        c_nr := c_nr + 1;
      ELSE
        IF v_line.unit_price IS NOT NULL AND v_alb_cost IS NOT NULL AND v_alb_cost > 0
           AND abs((v_line.unit_price - v_alb_cost) / v_alb_cost) * 100 > v_threshold THEN
          v_result := 'diferencia_precio';
          v_detail := jsonb_build_object(
            'invoiced_price', v_line.unit_price, 'receipt_cost', round(v_alb_cost, 4),
            'pct', round(((v_line.unit_price - v_alb_cost) / v_alb_cost) * 100, 1));
          c_dp := c_dp + 1;
        ELSIF v_line.qty IS NOT NULL AND v_alb_qty IS NOT NULL
              AND abs(v_line.qty - v_alb_qty) > 0.001 THEN
          v_result := 'diferencia_cantidad';
          v_detail := jsonb_build_object('invoiced_qty', v_line.qty, 'received_qty', v_alb_qty);
          c_dq := c_dq + 1;
        ELSIF v_expected_vat IS NOT NULL AND v_line.vat_pct IS NOT NULL
              AND abs(v_line.vat_pct - v_expected_vat) > 0.1 THEN
          v_result := 'iva_no_cuadra';
          v_detail := jsonb_build_object('invoiced_vat', v_line.vat_pct, 'expected_vat', v_expected_vat);
          c_vat := c_vat + 1;
        ELSE
          v_result := 'ok';
          v_detail := jsonb_build_object(
            'receipt_cost', round(COALESCE(v_alb_cost,0), 4), 'received_qty', v_alb_qty);
          c_ok := c_ok + 1;
        END IF;
      END IF;
    END IF;

    UPDATE public.supplier_invoice_line
      SET match_result = v_result,
          match_detail = v_detail,
          goods_receipt_line_id = COALESCE(v_alb_line, goods_receipt_line_id)
      WHERE id = v_line.id;
  END LOOP;

  IF (c_dp + c_dq + c_nr + c_vat + c_un) = 0 AND c_total > 0 THEN
    v_status := 'ok';
  ELSIF c_total = 0 THEN
    v_status := 'sin_match';
  ELSE
    v_status := 'con_diferencias';
  END IF;

  UPDATE public.supplier_invoice
    SET match_status = v_status, updated_at = now()
    WHERE id = p_invoice_id;

  RETURN QUERY SELECT v_status, c_total, c_ok, c_dp, c_dq, c_nr, c_vat, c_un;
END;
$$;


--
-- Name: run_mapping(uuid, text, text, integer, numeric, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_mapping(p_account_id uuid, p_text text, p_code text DEFAULT NULL::text, p_limit integer DEFAULT 5, p_fuzzy_min numeric DEFAULT 0.45, p_target_types text[] DEFAULT ARRAY['raw'::text, 'recipe'::text]) RETURNS TABLE(recipe_item_id uuid, name text, folvy_code text, confidence numeric, match_type text, semaphore text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_norm text := public.normalize_ingredient_name(p_text);
BEGIN
  IF NOT public.belongs_to_account(p_account_id) THEN
    RAISE EXCEPTION 'run_mapping: sin permiso sobre la cuenta %', p_account_id;
  END IF;

  RETURN QUERY
  WITH candidates AS (
    -- Cada capa lleva 'prio' (1=mejor) para priorizar capa sobre similitud bruta
    -- 1) CÓDIGO
    SELECT ri.id, ri.name, ri.folvy_code, 1.00::numeric AS conf, 'code'::text AS mt, 1 AS prio
    FROM recipe_item ri
    WHERE ri.account_id = p_account_id AND ri.is_active = true
      AND ri.type = ANY(p_target_types)
      AND p_code IS NOT NULL AND p_code <> ''
      AND (
        ri.folvy_code = p_code
        OR EXISTS (SELECT 1 FROM jsonb_each_text(ri.external_codes) j WHERE j.value = p_code)
        OR EXISTS (SELECT 1 FROM article_supplier a
                   WHERE a.recipe_item_id = ri.id AND a.supplier_code = p_code)
      )

    UNION ALL
    -- 2) NOMBRE EXACTO LITERAL (name + alt_names), normalizado
    SELECT ri.id, ri.name, ri.folvy_code, 0.99::numeric, 'name_exact', 2
    FROM recipe_item ri
    WHERE ri.account_id = p_account_id AND ri.is_active = true
      AND ri.type = ANY(p_target_types)
      AND (
        lower(public.unaccent(ri.name)) = lower(public.unaccent(p_text))
        OR EXISTS (SELECT 1 FROM unnest(ri.alt_names) an
                   WHERE lower(public.unaccent(an)) = lower(public.unaccent(p_text)))
      )

    UNION ALL
    -- 3) NOMBRE NORMALIZADO (sin paréntesis/acentos/espacios), name + alt_names
    SELECT ri.id, ri.name, ri.folvy_code, 0.92::numeric, 'name_normalized', 3
    FROM recipe_item ri
    WHERE ri.account_id = p_account_id AND ri.is_active = true
      AND ri.type = ANY(p_target_types)
      AND (
        public.normalize_ingredient_name(ri.name) = v_norm
        OR EXISTS (SELECT 1 FROM unnest(ri.alt_names) an
                   WHERE public.normalize_ingredient_name(an) = v_norm)
      )

    UNION ALL
    -- 4) DIFUSO (similarity trgm), confianza real = similitud
    SELECT ri.id, ri.name, ri.folvy_code,
           ROUND(similarity(public.normalize_ingredient_name(ri.name), v_norm)::numeric, 2),
           'fuzzy', 4
    FROM recipe_item ri
    WHERE ri.account_id = p_account_id AND ri.is_active = true
      AND ri.type = ANY(p_target_types)
      AND public.normalize_ingredient_name(ri.name) % v_norm
      AND similarity(public.normalize_ingredient_name(ri.name), v_norm) >= p_fuzzy_min
  ),
  -- Mejor capa por artículo: prioridad de capa primero, luego confianza
  best AS (
    SELECT DISTINCT ON (c.id)
      c.id, c.name, c.folvy_code, c.conf, c.mt, c.prio
    FROM candidates c
    ORDER BY c.id, c.prio ASC, c.conf DESC
  )
  SELECT
    b.id, b.name, b.folvy_code, b.conf, b.mt,
    -- verde si es match determinista (code/exact/normalized) o fuzzy muy alto
    CASE WHEN b.prio <= 3 OR b.conf >= 0.90 THEN 'green' ELSE 'yellow' END
  FROM best b
  ORDER BY b.prio ASC, b.conf DESC, b.name
  LIMIT p_limit;
END;
$$;


--
-- Name: safe_jsonb(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safe_jsonb(p_text text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
begin
  if p_text is null or btrim(p_text) = '' then
    return null;
  end if;
  return p_text::jsonb;
exception
  when others then
    return null;   -- texto no es JSON válido → null, no rompe la consulta
end;
$$;


--
-- Name: sale_coordenadas_de_entrega(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sale_coordenadas_de_entrega(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_s   record;
  v_rt  jsonb;
  v_lat numeric;
  v_lng numeric;
  v_org text;
begin
  select s.account_id, s.raw_tab, s.delivery_address
    into v_s
    from public.sale s
   where s.id = p_sale_id;

  if v_s.account_id is null then
    return jsonb_build_object('hay', false, 'motivo', 'pedido no encontrado');
  end if;

  if current_setting('request.jwt.claims', true) is not null
     and not public.belongs_to_account(v_s.account_id) then
    raise exception 'sale_coordenadas_de_entrega: sin acceso a ese pedido';
  end if;

  v_rt := case when left(btrim(coalesce(v_s.raw_tab, '')), 1) = '{'
               then v_s.raw_tab::jsonb else '{}'::jsonb end;

  v_lat := nullif(v_rt->'delivery'->>'latitude', '')::numeric;
  v_lng := nullif(v_rt->'delivery'->>'longitude', '')::numeric;
  v_org := 'delivery';

  if v_lat is null or v_lng is null then
    v_lat := nullif(v_rt->'customer'->>'latitude', '')::numeric;
    v_lng := nullif(v_rt->'customer'->>'longitude', '')::numeric;
    v_org := 'customer';
  end if;

  if v_lat is null or v_lng is null then
    return jsonb_build_object(
      'hay', false,
      'motivo', 'la plataforma tampoco ha enviado coordenadas');
  end if;

  return jsonb_build_object(
    'hay', true,
    'lat', v_lat,
    'lng', v_lng,
    'origen', v_org,
    -- Que quede dicho EN EL DATO, no solo en la pantalla: esto es un punto, no
    -- un portal. Si algun dia alguien consume esto desde otro sitio, se lo
    -- lleva puesto.
    'aproximada', true,
    'tiene_direccion_postal', coalesce(btrim(v_s.delivery_address), '') <> '');
end;
$$;


--
-- Name: FUNCTION sale_coordenadas_de_entrega(p_sale_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sale_coordenadas_de_entrega(p_sale_id uuid) IS 'B68 §2: coordenadas de entrega de un pedido cuando la plataforma no mando direccion postal. Mira `delivery` (Last.app) y `customer` (HubRise) y DICE de cual salieron. Marca `aproximada: true` en el dato, no solo en la pantalla. No hace geocodificacion inversa: no inventa la calle. Funcion aparte a proposito, para no tocar orders_feed, que alimenta las tablets.';


--
-- Name: sale_coordenadas_de_entrega_by_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sale_coordenadas_de_entrega_by_token(p_device_token text, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device;
  v_s      record;
  v_rt     jsonb;
  v_lat    numeric;
  v_lng    numeric;
  v_org    text;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'sale_coordenadas_de_entrega_by_token: token de dispositivo no válido';
  end if;

  select s.location_id, s.raw_tab, s.delivery_address, s.delivery_address_fixed
    into v_s from public.sale s where s.id = p_sale_id;
  -- Un pedido de otro local se trata igual que uno que no existe: la tablet no
  -- sabe ni que está ahí.
  if v_s.location_id is null or v_s.location_id <> v_device.location_id then
    raise exception 'sale_coordenadas_de_entrega_by_token: ese pedido no es de este local';
  end if;

  v_rt := case when left(btrim(coalesce(v_s.raw_tab, '')), 1) = '{'
               then v_s.raw_tab::jsonb else '{}'::jsonb end;
  v_lat := nullif(v_rt->'delivery'->>'latitude', '')::numeric;
  v_lng := nullif(v_rt->'delivery'->>'longitude', '')::numeric;
  v_org := 'delivery';
  if v_lat is null or v_lng is null then
    v_lat := nullif(v_rt->'customer'->>'latitude', '')::numeric;
    v_lng := nullif(v_rt->'customer'->>'longitude', '')::numeric;
    v_org := 'customer';
  end if;

  if v_lat is null or v_lng is null then
    return jsonb_build_object('hay', false, 'motivo', 'la plataforma tampoco ha enviado coordenadas',
      'direccion', nullif(coalesce(nullif(btrim(v_s.delivery_address_fixed), ''), btrim(v_s.delivery_address)), ''));
  end if;

  return jsonb_build_object(
    'hay', true, 'lat', v_lat, 'lng', v_lng, 'origen', v_org, 'aproximada', true,
    'tiene_direccion_postal', coalesce(btrim(v_s.delivery_address), '') <> ''
                              or coalesce(btrim(v_s.delivery_address_fixed), '') <> '',
    'direccion', nullif(coalesce(nullif(btrim(v_s.delivery_address_fixed), ''), btrim(v_s.delivery_address)), ''));
end;
$$;


--
-- Name: FUNCTION sale_coordenadas_de_entrega_by_token(p_device_token text, p_sale_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sale_coordenadas_de_entrega_by_token(p_device_token text, p_sale_id uuid) IS 'R03: el punto del mapa y la dirección de un pedido, para la tablet. SOLO pedidos del local del dispositivo; uno de otro local da error como si no existiera. sale_coordenadas_de_entrega (sesión) sigue cerrada a anon.';


--
-- Name: sale_delivery_distance_km(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sale_delivery_distance_km(p_sale_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when l.lat is not null and l.lng is not null and g.dlat is not null and g.dlng is not null
    then round((2*6371*asin(sqrt(
      power(sin(radians(g.dlat - l.lat)/2),2) +
      cos(radians(l.lat))*cos(radians(g.dlat))*
      power(sin(radians(g.dlng - l.lng)/2),2)
    )))::numeric,1)
    else null end
  from public.sale s
  left join public.locations l on l.id = s.location_id
  cross join lateral (
    select case when left(btrim(coalesce(s.raw_tab,'')),1)='{' then s.raw_tab::jsonb else '{}'::jsonb end as rt
  ) j
  cross join lateral (
    select nullif(j.rt->'delivery'->>'latitude','')::numeric  as dlat,
           nullif(j.rt->'delivery'->>'longitude','')::numeric as dlng
  ) g
  where s.id = p_sale_id;
$$;


--
-- Name: sale_entrega_desde_raw(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sale_entrega_desde_raw(p_source text, p_raw_tab text) RETURNS TABLE(customer_phone_code text, delivery_instructions text, order_customer_note text)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_t jsonb;
  v_w constant text := E' \t\r\n';
begin
  if left(btrim(coalesce(p_raw_tab, '')), 1) <> '{' then
    return query select null::text, null::text, null::text; return;
  end if;
  -- Un raw_tab roto no es un error de nadie que esté pidiendo: no se lee y ya
  -- (la 0320 llama aquí fila a fila; un solo roto tumbaba la tanda entera).
  begin
    v_t := p_raw_tab::jsonb;
  exception when others then
    return query select null::text, null::text, null::text; return;
  end;
  if p_source = 'hubrise' then
    return query select
      nullif(btrim(coalesce(v_t->'customer'->>'phone_access_code', ''), v_w), ''),
      nullif(btrim(coalesce(v_t->'customer'->>'delivery_notes', ''), v_w), ''),
      nullif(btrim(coalesce(v_t->>'customer_notes', ''), v_w), '');
  elsif p_source = 'lastapp' then
    return query select
      null::text,
      nullif(btrim(coalesce(v_t->'delivery'->>'details', ''), v_w), ''),
      nullif(btrim(coalesce(v_t->>'customerNote', ''), v_w), '');
  else
    return query select null::text, null::text, null::text;
  end if;
end;
$$;


--
-- Name: FUNCTION sale_entrega_desde_raw(p_source text, p_raw_tab text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sale_entrega_desde_raw(p_source text, p_raw_tab text) IS 'R03: código del teléfono, indicaciones de entrega y nota del cliente, leídos de raw_tab. Espacios o saltos de línea solos = null.';


--
-- Name: sale_line_cost_sweep(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sale_line_cost_sweep(p_limit integer DEFAULT 2000) RETURNS TABLE(examinadas integer, reparadas integer, rechazadas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_line record;
  v_exam int := 0;
  v_ok   int := 0;
  v_no   int := 0;
begin
  -- ── RAMA 1: linea de producto con receta propia. Comportamiento de siempre.
  for v_line in
    select sl.id
    from sale_line sl
    join menu_item mi on mi.id = sl.menu_item_id
    join recipe_item ri on ri.id = mi.recipe_item_id
    where coalesce(sl.line_type,'product') = 'product'
      and sl.computed_cost is null
      and coalesce(ri.computed_cost, ri.fixed_cost) is not null
      and (sl.cost_computed_at is null or sl.cost_computed_at < ri.updated_at)
    limit greatest(p_limit, 1)
  loop
    v_exam := v_exam + 1;
    begin
      if public.compute_sale_line_cost(v_line.id) is not null then
        v_ok := v_ok + 1;
      end if;
    exception when others then
      raise warning 'sale_line_cost_sweep: fallo en linea % — %', v_line.id, sqlerrm;
    end;
  end loop;

  -- ── RAMA 2 (02/09): EL PADRE DE COMBO. Era el punto ciego.
  --
  -- La rama 1 hace `join recipe_item on ri.id = mi.recipe_item_id`, y un combo
  -- NO TIENE RECETA PROPIA — es lo que lo hace un combo. El INNER JOIN lo tira.
  -- Resultado: el reparador nocturno nunca podia recoger un combo, justo el
  -- caso para el que existe («venta de hoy costeada mañana al escandallar»).
  --
  -- VENTANA DE 30 DIAS, Y ES DELIBERADA. Decision de Julio del 02/09: reparar
  -- lo reciente y arreglar hacia delante, NO rellenar la historia. Motivo
  -- medido: de las 606 lineas reparables de toda la vida, 598 (98,7 %) se
  -- costearian con una receta tocada DESPUES de la venta, y `recipe_item_version`
  -- —la tabla con la que se costearia al precio de entonces— tiene 0 filas.
  -- Escribir el coste de hoy sobre una venta del 7 de junio es inventar una
  -- cifra con cara de medida. Con la ventana, un combo tiene 30 dias para que
  -- alguien coste sus componentes; pasado eso, se queda sin coste y se ve.
  --
  -- La rama 1 NO lleva ventana, y se deja como estaba: cambiar su alcance seria
  -- un cambio de comportamiento que nadie ha pedido. La asimetria esta anotada.
  for v_line in
    select p.id
    from sale_line p
    join sale s on s.id = p.sale_id
    where coalesce(p.line_type,'product') = 'product'
      and p.computed_cost is null                    -- nunca recalcular
      and s.sold_at >= now() - interval '30 days'
      and exists (select 1 from sale_line h
                   where h.parent_sale_line_id = p.id and h.line_type = 'combo_item')
      and not exists (
        select 1 from sale_line h
          left join menu_item hmi on hmi.id = h.menu_item_id
          left join recipe_item hri on hri.id = hmi.recipe_item_id
         where h.parent_sale_line_id = p.id and h.line_type = 'combo_item'
           and (h.menu_item_id is null or hmi.recipe_item_id is null
                or coalesce(hri.computed_cost, hri.fixed_cost) is null))
    limit greatest(p_limit, 1)
  loop
    v_exam := v_exam + 1;
    begin
      if public.compute_sale_line_cost(v_line.id) is not null then
        v_ok := v_ok + 1;
      end if;
    exception when others then
      raise warning 'sale_line_cost_sweep: fallo en combo % — %', v_line.id, sqlerrm;
    end;
  end loop;

  -- ── LO QUE NO SE PUDO REPARAR, QUE ES LA COLA DE TRABAJO DE CASADO ────────
  -- Combos de la ventana, sin coste, con AL MENOS UN COMPONENTE SIN CASAR. El
  -- motor se niega con razon: un combo con un componente sin receta no tiene
  -- coste, tiene un trozo de coste. Este numero no existia en ninguna parte —
  -- y es exactamente lo que hay que casar.
  select count(*) into v_no
  from sale_line p
  join sale s on s.id = p.sale_id
  where coalesce(p.line_type,'product') = 'product'
    and p.computed_cost is null
    and s.sold_at >= now() - interval '30 days'
    and exists (select 1 from sale_line h
                 where h.parent_sale_line_id = p.id and h.line_type = 'combo_item')
    and exists (
      select 1 from sale_line h
        left join menu_item hmi on hmi.id = h.menu_item_id
        left join recipe_item hri on hri.id = hmi.recipe_item_id
       where h.parent_sale_line_id = p.id and h.line_type = 'combo_item'
         and (h.menu_item_id is null or hmi.recipe_item_id is null
              or coalesce(hri.computed_cost, hri.fixed_cost) is null));

  -- EL BARRIDO DICE QUE HIZO, SIEMPRE. Corre a las 04:50 y hasta hoy no se lo
  -- contaba a nadie. `raise warning` aterriza en cron.job_run_details.return_message,
  -- que es lo que ya lee el panel «Mis agentes»: sin tabla nueva y en una
  -- pantalla que alguien mira.
  raise warning 'sale_line_cost_sweep: % examinadas, % reparadas, % rechazadas por componente sin casar',
    v_exam, v_ok, v_no;

  -- Un goteo es normal (venta de hoy costeada mañana al escandallar). Un
  -- aluvion significa que el flujo de entrada esta costeando antes de tiempo de
  -- forma sistematica: eso se avisa, no se tapa.
  if v_ok > 300 then
    perform public._queue_system_alert(
      'cost_sweep',
      'Barrido de costes: ' || v_ok || ' lineas reparadas en una noche',
      'El barrido nocturno ha tenido que reparar ' || v_ok || ' lineas de venta que se costearon antes de que su receta tuviera coste. Un goteo es normal; este volumen indica que el flujo de entrada esta calculando costes demasiado pronto o que una campana de escandallos acaba de completarse. Revisar folvy_estado.',
      'cost_sweep_aluvion'
    );
  end if;

  examinadas := v_exam;
  reparadas  := v_ok;
  rechazadas := v_no;
  return next;
end;
$$;


--
-- Name: FUNCTION sale_line_cost_sweep(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sale_line_cost_sweep(p_limit integer) IS 'Barrido nocturno de costes de linea. Rama 1: producto con receta propia (sin ventana, como siempre). Rama 2 (02/09): PADRE DE COMBO, que la rama 1 no podia ver porque un combo no tiene receta propia y el INNER JOIN lo tiraba; acotada a 30 dias por decision de Julio para no costear historia con recetas de hoy. Devuelve tambien `rechazadas`: combos sin coste por tener algun componente sin casar, que es la cola de trabajo de Casado.';


--
-- Name: sales_brand_initials(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_brand_initials(p_brand_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select string_agg(left(w, 1), '' order by ord)
  from (
    select w, ord from unnest(
             string_to_array(
               regexp_replace(lower(public.unaccent(coalesce(p_brand_name, ''))), '[^a-z0-9 ]', ' ', 'g'),
               ' ')
           ) with ordinality as t(w, ord)
    where w <> '' and w not in ('de','del','la','el','los','las','y','do','it','the','of','and','a')
  ) q;
$$;


--
-- Name: sales_dashboard(uuid, timestamp with time zone, timestamp with time zone, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_dashboard(p_account_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_ownership text DEFAULT NULL::text, p_channel text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tz text;
  v_result jsonb;
  v_prev_from timestamptz;
  v_prev_to timestamptz;
  v_prev jsonb;
begin
  if not (p_account_id = any(current_user_account_ids())) then
    raise exception 'Sin acceso a la cuenta %', p_account_id;
  end if;

  select coalesce(timezone, 'Europe/Madrid') into v_tz
  from accounts where id = p_account_id;

  -- Periodo anterior de igual duración (para el "vs ayer / vs periodo").
  if p_from is not null and p_to is not null then
    v_prev_from := p_from - (p_to - p_from);
    v_prev_to   := p_from;
  end if;

  with base as (
    select
      s.id,
      (s.sold_at at time zone v_tz) as sold_local,
      -- B74: `total` YA lleva el descuento restado. Restarlo otra vez enseñaba
      -- un 18,6 % de menos.
      coalesce(s.total,0) - coalesce(s.refund_amount,0) as net,
      s.brand_id, s.location_id,
      lower(coalesce(s.external_channel_text,'desconocido')) as canal,
      b.name as brand_name, b.ownership_type, l.name as local_name
    from sale s
    left join brand b on b.id = s.brand_id
    left join locations l on l.id = s.location_id
    where s.account_id = p_account_id
      and s.is_active = true
      -- B74: un pedido cancelado no es una venta.
      and coalesce(s.status,'') <> 'cancelled'
      and (p_from is null or s.sold_at >= p_from)
      and (p_to   is null or s.sold_at <  p_to)
      and (p_location_id is null or s.location_id = p_location_id)
      and (p_brand_id    is null or s.brand_id = p_brand_id)
      and (p_ownership is null or b.ownership_type = p_ownership)
      and (p_channel   is null or lower(s.external_channel_text) = p_channel)
  )
  select jsonb_build_object(
    'kpis', (
      select jsonb_build_object(
        'net', coalesce(round(sum(net),2),0),
        'orders', count(*),
        'aov', case when count(*)>0 then round(sum(net)/count(*),2) else 0 end
      ) from base
    ),
    'by_channel', (
      select coalesce(jsonb_agg(x order by x.net desc),'[]'::jsonb) from (
        select canal as name, round(sum(net),2) as net, count(*) as orders
        from base group by canal) x
    ),
    'by_brand', (
      select coalesce(jsonb_agg(x order by x.net desc),'[]'::jsonb) from (
        select brand_name as name, ownership_type, round(sum(net),2) as net, count(*) as orders
        from base where brand_id is not null group by brand_name, ownership_type) x
    ),
    'by_ownership', (
      select coalesce(jsonb_agg(x order by x.net desc),'[]'::jsonb) from (
        select coalesce(ownership_type,'desconocido') as ownership,
               round(sum(net),2) as net, count(*) as orders
        from base group by ownership_type) x
    ),
    'by_location', (
      select coalesce(jsonb_agg(x order by x.net desc),'[]'::jsonb) from (
        select local_name as name, round(sum(net),2) as net, count(*) as orders
        from base where location_id is not null group by local_name) x
    ),
    'by_hour', (
      select coalesce(jsonb_agg(x order by x.hour),'[]'::jsonb) from (
        select extract(hour from sold_local)::int as hour,
               round(sum(net),2) as net, count(*) as orders
        from base group by extract(hour from sold_local)) x
    )
  ) into v_result;

  -- Bloque del periodo anterior. MISMA regla que arriba, a los dos lados.
  if v_prev_from is not null then
    select jsonb_build_object(
      'net', coalesce(round(sum(
        coalesce(s.total,0)-coalesce(s.refund_amount,0)
      ),2),0),
      'orders', count(*)
    ) into v_prev
    from sale s
    left join brand b on b.id = s.brand_id
    where s.account_id = p_account_id
      and s.is_active = true
      and coalesce(s.status,'') <> 'cancelled'
      and s.sold_at >= v_prev_from and s.sold_at < v_prev_to
      and (p_location_id is null or s.location_id = p_location_id)
      and (p_brand_id    is null or s.brand_id = p_brand_id)
      and (p_ownership is null or b.ownership_type = p_ownership)
      and (p_channel   is null or lower(s.external_channel_text) = p_channel);
  else
    v_prev := jsonb_build_object('net', 0, 'orders', 0);
  end if;

  v_result := v_result || jsonb_build_object('prev', v_prev);
  return v_result;
end;
$$;


--
-- Name: sales_mapping_reliability(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_mapping_reliability(p_account_id uuid, p_from timestamp with time zone DEFAULT (now() - '90 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS TABLE(revenue_total numeric, revenue_casado numeric, revenue_sin_casar numeric, reliability_pct numeric, threshold_pct numeric, status text, lineas_total integer, lineas_casadas integer, ciego_desconocido_eur numeric, ciego_desconocido_lineas integer, ciego_calculable_eur numeric, ciego_calculable_lineas integer, ciego_otros_eur numeric, ciego_otros_lineas integer, casado_sin_coste_eur numeric, casado_sin_coste_lineas integer, cost_coverage_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '15s'
    AS $$
DECLARE
  v_total      numeric := 0;
  v_casado     numeric := 0;
  v_sincasar   numeric := 0;
  v_rel        numeric := 0;
  v_thr        numeric;
  v_status     text;
  v_lin_tot    integer := 0;
  v_lin_cas    integer := 0;
  v_desc_eur   numeric := 0;
  v_desc_lin   integer := 0;
  v_calc_eur   numeric := 0;
  v_calc_lin   integer := 0;
  v_otros_eur  numeric := 0;
  v_otros_lin  integer := 0;
  v_scost_eur  numeric := 0;
  v_scost_lin  integer := 0;
  v_cov        numeric := NULL;
BEGIN
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'sales_mapping_reliability: sin acceso a la cuenta %', p_account_id;
  END IF;

  SELECT COALESCE(ks.reliability_min_pct, 90)
  INTO v_thr
  FROM kitchen_settings ks
  WHERE ks.account_id = p_account_id;
  v_thr := COALESCE(v_thr, 90);

  WITH vr AS MATERIALIZED (
    -- Arrancar por las ventas del rango (índice por cuenta/fecha) en vez de por
    -- todas las líneas históricas; evita los ~9k sondeos uno-a-uno a `sale`.
    SELECT s.id
      FROM sale s
     WHERE s.account_id = p_account_id
       AND s.is_active = true
       AND s.sold_at >= p_from
       AND s.sold_at <  p_to
  )
  SELECT
    COALESCE(SUM(amt), 0),
    COALESCE(SUM(amt) FILTER (WHERE casado), 0),
    COUNT(*),
    COUNT(*) FILTER (WHERE casado),
    COALESCE(SUM(amt) FILTER (WHERE NOT casado AND reason = 'no_recipe'), 0),
    COUNT(*)          FILTER (WHERE NOT casado AND reason = 'no_recipe'),
    COALESCE(SUM(amt) FILTER (WHERE NOT casado AND reason = 'no_menu_item'), 0),
    COUNT(*)          FILTER (WHERE NOT casado AND reason = 'no_menu_item'),
    COALESCE(SUM(amt) FILTER (WHERE NOT casado
                                AND COALESCE(reason,'') NOT IN ('no_recipe','no_menu_item')), 0),
    COUNT(*)          FILTER (WHERE NOT casado
                                AND COALESCE(reason,'') NOT IN ('no_recipe','no_menu_item')),
    COALESCE(SUM(amt) FILTER (WHERE casado AND sin_coste), 0),
    COUNT(*)          FILTER (WHERE casado AND sin_coste)
  INTO v_total, v_casado, v_lin_tot, v_lin_cas,
       v_desc_eur, v_desc_lin, v_calc_eur, v_calc_lin, v_otros_eur, v_otros_lin,
       v_scost_eur, v_scost_lin
  FROM (
    SELECT
      COALESCE(sl.line_total, sl.unit_price * sl.quantity) AS amt,
      (sl.menu_item_id IS NOT NULL)                        AS casado,
      sl.unmapped_reason                                   AS reason,
      (mi.recipe_item_id IS NOT NULL
        AND ri.computed_cost IS NULL
        AND ri.fixed_cost IS NULL)                         AS sin_coste
    FROM vr
    JOIN sale_line sl ON sl.sale_id = vr.id
    LEFT JOIN menu_item mi ON mi.id = sl.menu_item_id
    LEFT JOIN recipe_item ri ON ri.id = mi.recipe_item_id
    WHERE COALESCE(sl.line_type, 'product') = 'product'
  ) q;

  v_sincasar := ROUND(v_total - v_casado, 2);
  v_rel := CASE WHEN v_total > 0 THEN ROUND(v_casado / v_total * 100, 2) ELSE NULL END;
  v_cov := CASE WHEN v_casado > 0
                THEN ROUND((v_casado - v_scost_eur) / v_casado * 100, 2)
                ELSE NULL END;

  v_status := CASE
    WHEN v_rel IS NULL              THEN 'verde'
    WHEN v_rel >= v_thr             THEN 'verde'
    WHEN v_rel >= (v_thr - 10)      THEN 'ambar'
    ELSE 'rojo'
  END;

  RETURN QUERY SELECT
    ROUND(v_total, 2), ROUND(v_casado, 2), v_sincasar, v_rel, v_thr, v_status,
    v_lin_tot, v_lin_cas,
    ROUND(v_desc_eur, 2), v_desc_lin,
    ROUND(v_calc_eur, 2), v_calc_lin,
    ROUND(v_otros_eur, 2), v_otros_lin,
    ROUND(v_scost_eur, 2), v_scost_lin, v_cov;
END;
$$;


--
-- Name: sales_product_norm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_product_norm(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select regexp_replace(
           regexp_replace(btrim(lower(public.unaccent(coalesce(p_name, '')))), '\.$', ''),
           '\s+', ' ', 'g'
         );
$_$;


--
-- Name: sales_product_norm_nobrand(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_product_norm_nobrand(p_name text, p_brand_name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_norm  text := public.sales_product_norm(p_name);
  v_sigla text := public.sales_brand_initials(p_brand_name);
  v_marca text := public.sales_product_norm(p_brand_name);
  v_tok   text;
begin
  foreach v_tok in array array[v_sigla, v_marca] loop
    if v_tok is null or length(v_tok) < 2 then continue; end if;
    -- "... (mh)" o "... mh" al final
    if v_norm like '%(' || v_tok || ')' then
      v_norm := btrim(left(v_norm, length(v_norm) - length(v_tok) - 2));
    elsif v_norm like '% ' || v_tok then
      v_norm := btrim(left(v_norm, length(v_norm) - length(v_tok) - 1));
    end if;
  end loop;
  return btrim(v_norm);
end;
$$;


--
-- Name: sales_unmapped_products(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_unmapped_products(p_account_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(product_name text, brand_id uuid, brand_name text, sources text, lineas integer, uds numeric, euros numeric, ventas integer, ultima_venta date, tiene_matricula boolean, ya_mapeado boolean, candidatos_marca integer, candidatos_otras_marcas integer, sugerencia_menu_item_id uuid, sugerencia_nombre text, diagnostico text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.belongs_to_account(p_account_id) THEN
    RAISE EXCEPTION 'sales_unmapped_products: sin acceso a la cuenta %', p_account_id;
  END IF;

  RETURN QUERY
  WITH sc AS (
    SELECT sl.product_name AS pname,
           s.brand_id      AS bid,
           b.name          AS bname,
           string_agg(DISTINCT coalesce(s.source,'?'), ', ') AS srcs,
           public.sales_product_norm_nobrand(sl.product_name, b.name) AS norm,
           count(*)::integer                                  AS n_lineas,
           sum(sl.quantity)                                   AS n_uds,
           round(sum(sl.quantity * coalesce(sl.unit_price,0)),2) AS n_eur,
           count(DISTINCT s.id)::integer                      AS n_ventas,
           max(s.sold_at)::date                               AS ult,
           bool_or(sl.external_product_id IS NOT NULL)        AS matricula
      FROM public.sale_line sl
      JOIN public.sale s ON s.id = sl.sale_id
      LEFT JOIN public.brand b ON b.id = s.brand_id
     WHERE s.account_id = p_account_id
       AND s.sold_at >= now() - make_interval(days => greatest(coalesce(p_days,30), 1))
       AND sl.menu_item_id IS NULL
       AND sl.ignored_at IS NULL
       AND coalesce(sl.line_type,'product') = 'product'
       AND coalesce(s.is_active, true)
       AND coalesce(s.status,'') <> 'cancelled'
       AND coalesce(s.order_status,'') NOT IN ('cancelled','rejected')
     GROUP BY 1,2,3,5
  ), cand AS (
    SELECT sc.*,
      (SELECT count(*)::integer FROM public.menu_item mi
        WHERE mi.account_id = p_account_id AND mi.archived_at IS NULL
          AND mi.brand_id = sc.bid AND sc.norm <> ''
          AND public.sales_product_norm_nobrand(mi.name, sc.bname) = sc.norm) AS c_marca,
      (SELECT count(*)::integer FROM public.menu_item mi
        WHERE mi.account_id = p_account_id AND mi.archived_at IS NULL
          AND coalesce(mi.brand_id, '00000000-0000-0000-0000-000000000000'::uuid)
              IS DISTINCT FROM coalesce(sc.bid, '00000000-0000-0000-0000-000000000000'::uuid)
          AND sc.norm <> ''
          AND public.sales_product_norm_nobrand(mi.name, sc.bname) = sc.norm) AS c_otras,
      EXISTS (SELECT 1 FROM public.sales_mapping_fix smf
               WHERE smf.account_id = p_account_id
                 AND smf.product_norm = public.sales_product_norm(sc.pname)
                 AND smf.reverted_at IS NULL) AS mapeado
    FROM sc
  )
  SELECT c.pname, c.bid, c.bname, c.srcs,
         c.n_lineas, c.n_uds, c.n_eur, c.n_ventas, c.ult,
         c.matricula, c.mapeado, c.c_marca, c.c_otras,
         -- sugerencia SOLO si es unica dentro de su marca
         CASE WHEN c.c_marca = 1 THEN
           (SELECT mi.id FROM public.menu_item mi
             WHERE mi.account_id = p_account_id AND mi.archived_at IS NULL
               AND mi.brand_id = c.bid
               AND public.sales_product_norm_nobrand(mi.name, c.bname) = c.norm
             LIMIT 1) END,
         CASE WHEN c.c_marca = 1 THEN
           (SELECT mi.name FROM public.menu_item mi
             WHERE mi.account_id = p_account_id AND mi.archived_at IS NULL
               AND mi.brand_id = c.bid
               AND public.sales_product_norm_nobrand(mi.name, c.bname) = c.norm
             LIMIT 1) END,
         CASE
           WHEN c.mapeado          THEN 'ya_mapeado'
           WHEN c.c_marca = 1      THEN 'casa_solo'
           WHEN c.c_marca > 1      THEN 'ambiguo'
           WHEN c.c_otras > 0      THEN 'otra_marca'
           ELSE                         'sin_candidato'
         END
    FROM cand c
   ORDER BY c.n_eur DESC;
END;
$$;


--
-- Name: sales_unmapped_watchdog(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_unmapped_watchdog(p_days integer DEFAULT 30, p_min_catalogo integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  a record; v_n integer := 0; v_prod integer; v_eur numeric; v_lin integer;
  v_casan integer; v_top text; v_top_eur numeric; v_sev text; fmt text; v_cat integer;
BEGIN
  FOR a IN SELECT DISTINCT s.account_id FROM public.sale s
            WHERE s.sold_at >= now() - make_interval(days => greatest(coalesce(p_days,30),1))
  LOOP
    -- DM1 · PR 2a (31/10): una cuenta de demo no cuenta en los vigías.
    CONTINUE WHEN NOT public.cuenta_puede_salir(a.account_id);
    -- Sin carta montada no hay nada que avisar: todo estaria sin casar.
    SELECT count(*)::integer INTO v_cat
      FROM public.menu_item mi
     WHERE mi.account_id = a.account_id AND mi.archived_at IS NULL;
    CONTINUE WHEN coalesce(v_cat,0) < greatest(coalesce(p_min_catalogo,10), 1);

    SELECT count(*)::integer, coalesce(sum(u.euros),0), coalesce(sum(u.lineas),0)::integer,
           count(*) FILTER (WHERE u.diagnostico = 'casa_solo')::integer
      INTO v_prod, v_eur, v_lin, v_casan
      FROM public._sales_unmapped_products_raw(a.account_id, p_days) u;

    CONTINUE WHEN coalesce(v_prod,0) = 0;

    SELECT u.product_name, u.euros INTO v_top, v_top_eur
      FROM public._sales_unmapped_products_raw(a.account_id, p_days) u
     ORDER BY u.euros DESC LIMIT 1;

    v_sev := CASE WHEN v_eur >= 5000 THEN 'CRITICO'
                  WHEN v_eur >= 1000 THEN 'ALTO' ELSE 'AVISO' END;
    fmt := translate(to_char(v_eur, 'FM999G999G990D00'), ',.', '.,');

    PERFORM public._queue_system_alert(
      'venta_producto_sin_casar',
      v_sev || ': ' || v_prod::text || ' productos vendidos sin catalogo (' || fmt || ' EUR)',
      v_prod::text || ' productos distintos se han vendido en los ultimos ' || p_days::text
        || ' dias sin estar casados con la carta: ' || v_lin::text || ' lineas y ' || fmt || ' EUR. '
        || 'Su stock NO se ha descontado. El mayor es "' || coalesce(v_top,'?') || '" con '
        || translate(to_char(coalesce(v_top_eur,0), 'FM999G999G990D00'), ',.', '.,') || ' EUR. '
        || v_casan::text || ' de ellos tienen un unico candidato en su marca y se pueden casar de un clic. '
        || 'Bandeja: Productos sin catalogar.',
      -- La severidad va en la clave: un empeoramiento rompe el silencio, un
      -- estado estable no vuelve a sonar en 20 h.
      'venta_sin_casar_' || a.account_id::text || '_' || v_sev || '_'
        || to_char(now() at time zone 'Europe/Madrid', 'YYYYMMDD')
    );
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END;
$$;


--
-- Name: sales_without_consumption(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_without_consumption(p_account_id uuid, p_hours integer DEFAULT 4) RETURNS TABLE(causa text, ventas integer, importe numeric, mas_antigua timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with candidatas as (
    select s.id, s.total, s.sold_at,
           exists (
             select 1 from sale_line sl
              where sl.sale_id = s.id
                and coalesce(sl.line_type,'product') = 'product'
                and sl.menu_item_id is not null
                and sl.ignored_at is null
           ) as tiene_lineas
      from sale s
     where s.account_id = p_account_id
       and s.is_active
       and coalesce(s.status,'') <> 'cancelled'
       and coalesce(s.order_status,'') not in ('cancelled','rejected')
       and s.sold_at < now() - make_interval(hours => p_hours)
       and s.sold_at > now() - interval '30 days'
       and not exists (
         select 1 from stock_movement sm
          where sm.source_type = 'sale'
            and sm.source_id = s.id
            and sm.movement_type = 'consumo'
       )
  )
  select case when tiene_lineas then 'motor_fallo' else 'sin_lineas' end,
         count(*)::integer,
         round(coalesce(sum(total),0), 2),
         min(sold_at)
    from candidatas
   group by 1;
$$;


--
-- Name: save_campaign(uuid, uuid, text, text, text, text, numeric, numeric, timestamp with time zone, timestamp with time zone, integer, integer, smallint[], time without time zone, time without time zone, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_campaign(p_account uuid, p_id uuid, p_kind text, p_name text, p_code text, p_discount_type text, p_value numeric, p_min_subtotal numeric, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_max_redemptions integer, p_max_per_customer integer, p_weekdays smallint[], p_time_from time without time zone, p_time_to time without time zone, p_budget_max numeric, p_scope jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_name  text;
  v_code  text;
  v_mpc   integer;
  v_dtype text;
  v_value numeric;
  v_auto  boolean;
  v_existing coupon%rowtype;
  v_id    uuid;
  v_sc    jsonb;
begin
  if not (p_account = any(current_user_account_ids())) then raise exception 'forbidden'; end if;

  if p_kind not in ('standard','item_percent','free_delivery','bogo','free_item') then
    return jsonb_build_object('ok', false, 'reason', 'bad_kind');
  end if;

  v_name := nullif(btrim(p_name), '');
  v_mpc  := coalesce(p_max_per_customer, 1);
  if v_name is null then return jsonb_build_object('ok', false, 'reason', 'name_required'); end if;
  if v_mpc < 1 then return jsonb_build_object('ok', false, 'reason', 'bad_max_per'); end if;
  if p_min_subtotal is not null and p_min_subtotal < 0 then return jsonb_build_object('ok', false, 'reason', 'bad_min'); end if;
  if p_max_redemptions is not null and p_max_redemptions <= 0 then return jsonb_build_object('ok', false, 'reason', 'bad_max'); end if;
  if p_budget_max is not null and p_budget_max <= 0 then return jsonb_build_object('ok', false, 'reason', 'bad_budget'); end if;
  if p_starts_at is not null and p_ends_at is not null and p_ends_at <= p_starts_at then
    return jsonb_build_object('ok', false, 'reason', 'bad_window');
  end if;

  if p_kind = 'standard' then
    v_code := upper(nullif(btrim(p_code), ''));
    if v_code is null then return jsonb_build_object('ok', false, 'reason', 'code_required'); end if;
    if p_discount_type not in ('percent','fixed') then return jsonb_build_object('ok', false, 'reason', 'bad_type'); end if;
    if p_value is null or p_value <= 0 then return jsonb_build_object('ok', false, 'reason', 'bad_value'); end if;
    if p_discount_type = 'percent' and p_value > 100 then return jsonb_build_object('ok', false, 'reason', 'bad_percent'); end if;
    v_dtype := p_discount_type; v_value := p_value; v_auto := false;
  elsif p_kind in ('item_percent','bogo') then
    -- item_percent: % de cada unidad en scope. bogo: % de la 2ª unidad de cada par
    -- (100 = 2x1). Ambos: value 1..100, scope obligatorio, auto_apply=false.
    v_code := null; v_auto := false; v_dtype := 'percent';
    if p_value is null or p_value <= 0 or p_value > 100 then return jsonb_build_object('ok', false, 'reason', 'bad_value'); end if;
    v_value := p_value;
    if jsonb_typeof(p_scope) <> 'array' or jsonb_array_length(coalesce(p_scope,'[]'::jsonb)) = 0 then
      return jsonb_build_object('ok', false, 'reason', 'scope_required');
    end if;
  elsif p_kind = 'free_item' then
    -- Regalo: 1 plato en scope + mínimo obligatorio ("desde X€"); auto, value dummy.
    v_code := null; v_dtype := 'fixed'; v_value := 1; v_auto := true;
    if p_min_subtotal is null or p_min_subtotal <= 0 then
      return jsonb_build_object('ok', false, 'reason', 'min_required');
    end if;
    if jsonb_typeof(p_scope) <> 'array'
       or jsonb_array_length(coalesce(p_scope,'[]'::jsonb)) <> 1
       or (p_scope->0->>'type') <> 'item' then
      return jsonb_build_object('ok', false, 'reason', 'gift_item_required');
    end if;
  else  -- free_delivery: value/discount_type dummy (el descuento es el envío); auto.
    v_code := null; v_dtype := 'fixed'; v_value := 1; v_auto := true;
  end if;

  if p_id is null then
    begin
      insert into coupon (account_id, name, code, discount_type, value, applies_to,
                          first_order_only, auto_apply, max_per_customer, max_redemptions, min_subtotal,
                          starts_at, ends_at, active, kind, origin,
                          weekdays, time_from, time_to, budget_max, channels, created_by)
      values (p_account, v_name, v_code, v_dtype, v_value, 'subtotal',
              false, v_auto, v_mpc, p_max_redemptions, p_min_subtotal,
              p_starts_at, p_ends_at, true, p_kind, 'manual',
              p_weekdays, p_time_from, p_time_to, p_budget_max, '{shop}', auth.uid())
      returning id into v_id;
    exception when unique_violation then
      return jsonb_build_object('ok', false, 'reason',
        case when p_kind = 'free_delivery' then 'free_delivery_exists'
             when p_kind = 'free_item'     then 'free_item_exists'
             else 'code_taken' end);
    end;
  else
    select * into v_existing from coupon where id = p_id and account_id = p_account;
    if v_existing.id is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
    -- Sistema = bienvenida (standard auto/first) o frecuencia. item_percent/free_delivery/bogo/free_item editables.
    if v_existing.kind = 'frequency'
       or (v_existing.kind = 'standard' and (v_existing.auto_apply or v_existing.first_order_only)) then
      return jsonb_build_object('ok', false, 'reason', 'system');
    end if;
    begin
      update coupon set
        name             = v_name,
        code             = v_code,
        discount_type    = v_dtype,
        value            = v_value,
        min_subtotal     = p_min_subtotal,
        starts_at        = p_starts_at,
        ends_at          = p_ends_at,
        max_redemptions  = p_max_redemptions,
        max_per_customer = v_mpc,
        weekdays         = p_weekdays,
        time_from        = p_time_from,
        time_to          = p_time_to,
        budget_max       = p_budget_max,
        updated_at       = now()
      where id = p_id;
    exception when unique_violation then
      return jsonb_build_object('ok', false, 'reason',
        case when v_existing.kind = 'free_delivery' then 'free_delivery_exists'
             when v_existing.kind = 'free_item'     then 'free_item_exists'
             else 'code_taken' end);
    end;
    v_id := p_id;
  end if;

  -- Alcance (item_percent, bogo y free_item): reemplazar en bloque (atómico).
  if p_kind in ('item_percent','bogo','free_item') then
    delete from campaign_scope where coupon_id = v_id;
    for v_sc in select * from jsonb_array_elements(p_scope)
    loop
      insert into campaign_scope (coupon_id, brand_id, menu_category_id, menu_item_id)
      values (v_id,
        case when v_sc->>'type' = 'brand'    then (v_sc->>'id')::uuid else null end,
        case when v_sc->>'type' = 'category' then (v_sc->>'id')::uuid else null end,
        case when v_sc->>'type' = 'item'     then (v_sc->>'id')::uuid else null end);
    end loop;
  end if;

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


--
-- Name: save_count_line(uuid, jsonb, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_count_line(p_line_id uuid, p_entries jsonb, p_confirm numeric DEFAULT NULL::numeric, p_counted_by uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id   uuid;
  v_count_id     uuid;
  v_location_id  uuid;
  v_item_id      uuid;
  v_status       text;
  v_ya_pedido    timestamptz;
  v_anterior     numeric;

  v_actor        uuid := auth.uid();
  v_actor_emp    uuid;
  v_actor_name   text;

  -- Quien contó, cuando no es quien teclea.
  v_source       text := COALESCE(NULLIF(p_source, ''), 'tablet');
  v_por_telefono boolean;
  v_quien_emp    uuid;
  v_quien_name   text;

  v_total        numeric := 0;
  v_e            jsonb;
  v_method       text;
  v_format_id    uuid;
  v_qty          numeric;
  v_fraction     numeric;
  v_fmt_base     numeric;
  v_base         numeric;
  v_n            integer := 0;
  v_a_ojo        boolean := false;
  v_intento      smallint;

  v_factor       numeric;
  v_contra_pct   numeric;
  v_repeat_pct   numeric;

  v_teorico      numeric;
  v_ref_qty      numeric;
  v_hubo_entrada boolean := false;
  v_sin_ref      boolean := false;
  v_apertura     boolean := false;

  v_veredicto    text := 'ok';
  v_confirmado   boolean := false;
  v_forzado      boolean := false;
  v_revisar      boolean := false;
  v_segundo      boolean;

  -- Lo que va a la tabla de entradas, ya convertido, antes de decidir nada.
  v_conv         jsonb := '[]'::jsonb;
BEGIN
  IF v_source NOT IN ('tablet', 'telefono') THEN
    RAISE EXCEPTION 'save_count_line: origen «%» desconocido', v_source;
  END IF;
  v_por_telefono := v_source = 'telefono';

  -- ── Quién y qué ─────────────────────────────────────────────────────────
  SELECT l.account_id, l.inventory_count_id, l.recipe_item_id, l.counted_qty,
         l.recount_asked_at, ic.location_id, ic.status, COALESCE(ic.is_opening, false)
    INTO v_account_id, v_count_id, v_item_id, v_anterior,
         v_ya_pedido, v_location_id, v_status, v_apertura
    FROM public.inventory_count_line l
    JOIN public.inventory_count ic ON ic.id = l.inventory_count_id
   WHERE l.id = p_line_id
   FOR UPDATE OF l;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'save_count_line: la línea % no existe', p_line_id;
  END IF;
  IF NOT public.belongs_to_account(v_account_id) THEN
    RAISE EXCEPTION 'save_count_line: sin acceso a la cuenta';
  END IF;
  IF v_status IN ('aprobado', 'anulado') THEN
    RAISE EXCEPTION 'save_count_line: el recuento está % y ya no se puede tocar', v_status;
  END IF;

  -- «Corregir ahora» es una acción de la pantalla de revisión y de ninguna
  -- otra. Mientras el recuento sigue abierto, quien cuenta cuenta: no hace
  -- falta que nadie apunte por él.
  IF v_por_telefono AND v_status <> 'en_revision' THEN
    RAISE EXCEPTION 'save_count_line: una corrección por teléfono sólo se apunta con el recuento en revisión, y éste está %', v_status;
  END IF;

  IF jsonb_typeof(p_entries) <> 'array' OR jsonb_array_length(p_entries) = 0 THEN
    RAISE EXCEPTION 'save_count_line: hay que mandar al menos una entrada. Un campo vacío no es un cero: para decir que no queda nada, manda una entrada con method = cero.';
  END IF;

  -- Nombre real de quien cuenta, para que la pantalla de aprobación pueda
  -- decir «Natacha · 20:39» y no «alguien».
  --
  -- `display_name` entra como reserva (11/09): el usuario de oficina no tiene
  -- ficha de empleado, y sin esto «apuntado por …» se quedaría en blanco justo
  -- en el caso para el que se escribe esta migración.
  SELECT up.employee_id, COALESCE(e.name, up.display_name)
    INTO v_actor_emp, v_actor_name
    FROM public.user_profiles up
    LEFT JOIN public.employees e ON e.id = up.employee_id
   WHERE up.user_id = v_actor AND up.account_id = v_account_id
   LIMIT 1;

  -- ── Quién contó, si no es quien teclea ──────────────────────────────────
  --
  -- REGLA 9, UN PISO MÁS ABAJO. El empleado se ancla por id Y por cuenta Y por
  -- LOCAL: la plantilla es multi-cuenta y multi-local, y apuntar el recuento
  -- de Carabanchel a nombre de alguien de Alcalá no da un nombre equivocado,
  -- da un nombre que no es de nadie.
  IF p_counted_by IS NOT NULL THEN
    SELECT emp.id, emp.name
      INTO v_quien_emp, v_quien_name
      FROM public.employees emp
     WHERE emp.id         = p_counted_by
       AND emp.account_id = v_account_id
       AND emp.active
       AND (emp.location_id = v_location_id
            OR v_location_id = ANY(COALESCE(emp.assigned_locations, '{}'::uuid[])));
    IF v_quien_emp IS NULL THEN
      RAISE EXCEPTION 'save_count_line: % no está en la plantilla activa de este local, así que no puede figurar como quien contó', p_counted_by;
    END IF;
  END IF;

  -- ── El número de intento: max + 1, nunca «1 o 2» ────────────────────────
  --
  -- Ver la cabecera de la migración: con la regla vieja el tercer guardado
  -- escribía otra vez sobre el intento 1, y un re-guardado de una línea buena
  -- volvía a pasar por los frenos ciegos y podía dejarla sin cifra.
  SELECT COALESCE(max(attempt), 0) + 1 INTO v_intento
    FROM public.inventory_count_entry WHERE line_id = p_line_id;
  v_segundo := v_intento > 1;

  -- ── Las entradas: el servidor convierte, el móvil no ────────────────────
  FOR v_e IN SELECT * FROM jsonb_array_elements(p_entries)
  LOOP
    v_method    := v_e->>'method';
    v_format_id := NULLIF(v_e->>'format_id','')::uuid;
    v_qty       := NULLIF(v_e->>'qty','')::numeric;
    v_fraction  := NULLIF(v_e->>'fraction','')::numeric;
    v_fmt_base  := NULL;

    IF v_method IS NULL OR v_method NOT IN ('formato','peso','fraccion','cero') THEN
      RAISE EXCEPTION 'save_count_line: método «%» desconocido', coalesce(v_method,'(vacío)');
    END IF;

    IF v_method IN ('formato','fraccion') THEN
      -- Regla 9: el formato se ancla por id Y por cuenta Y por artículo. Un
      -- formato de otro artículo (o de la cuenta plantilla, que comparte
      -- NOMBRES con producción) multiplicaría por el peso de otra ficha.
      SELECT f.qty_in_base INTO v_fmt_base
        FROM public.recipe_item_purchase_format f
       WHERE f.id = v_format_id
         AND f.account_id = v_account_id
         AND f.item_id    = v_item_id;
      IF v_fmt_base IS NULL THEN
        RAISE EXCEPTION 'save_count_line: el formato % no es de este artículo', v_format_id;
      END IF;
      IF v_fmt_base <= 0 THEN
        RAISE EXCEPTION 'save_count_line: el formato % no tiene contenido. No se puede contar con él', v_format_id;
      END IF;
    END IF;

    IF v_method = 'fraccion' THEN
      -- Puede pasar de 1: «Otra · + bolsa» de la pantalla 2 sirve para decir
      -- que hay dos bolsas abiertas y media. Sigue siendo A OJO, y eso es lo
      -- que hace que salga marcada en la aprobación.
      IF v_fraction IS NULL OR v_fraction <= 0 THEN
        RAISE EXCEPTION 'save_count_line: una cantidad a ojo tiene que ser mayor que cero, no %', v_fraction;
      END IF;
      v_a_ojo := true;
    END IF;

    v_base := CASE v_method
      WHEN 'formato'  THEN v_qty * v_fmt_base
      WHEN 'fraccion' THEN v_fraction * v_fmt_base
      WHEN 'peso'     THEN v_qty
      WHEN 'cero'     THEN 0
    END;

    IF v_base IS NULL OR v_base < 0 THEN
      RAISE EXCEPTION 'save_count_line: cantidad no válida en una entrada de tipo %', v_method;
    END IF;

    v_conv := v_conv || jsonb_build_object(
      'method', v_method, 'format_id', v_format_id,
      'qty', v_qty, 'fraction', v_fraction, 'base', v_base);

    v_total := v_total + v_base;
    v_n := v_n + 1;
  END LOOP;

  -- ── El freno, contra dos referencias, sin devolver ninguna ──────────────
  SELECT COALESCE(count_recount_factor, 3),
         COALESCE(count_contradiction_pct, 40),
         COALESCE(count_repeat_tolerance_pct, 5)
    INTO v_factor, v_contra_pct, v_repeat_pct
    FROM public.supply_settings WHERE account_id = v_account_id;
  v_factor     := COALESCE(v_factor, 3);
  v_contra_pct := COALESCE(v_contra_pct, 40);
  v_repeat_pct := COALESCE(v_repeat_pct, 5);

  -- (a) teórico vivo del ledger
  v_teorico := public.theoretical_qty_at(v_item_id, v_location_id, now());

  -- (b) último recuento APROBADO + lo movido desde entonces
  --
  -- LAS DOS SE MIRAN SIEMPRE, aunque el freno no llegue a usarlas. Antes la (b)
  -- sólo se calculaba si la (a) no había frenado ya; ahora se calcula igual y
  -- se APLICA en las mismas condiciones que antes, para poder responder a una
  -- pregunta que el freno no contestaba: ¿tenía Folvy con qué comparar?
  SELECT ref.qty, ref.entradas
    INTO v_ref_qty, v_hubo_entrada
    FROM (
      SELECT prev.counted_qty + COALESCE((
               SELECT SUM(sm.qty_base) FROM public.stock_movement sm
                WHERE sm.recipe_item_id = v_item_id
                  AND sm.location_id    = v_location_id
                  AND sm.source_type   <> 'inventory_count'
                  AND sm.occurred_at    > prev.counted_at
             ), 0) AS qty,
             COALESCE((
               -- «Recepciones» en el sentido del encargo: mercancía que
               -- ENTRA por una razón registrada. Un ajuste manual no cuenta:
               -- si el stock subió porque alguien lo corrigió a mano, la
               -- pregunta «¿seguro?» sigue mereciendo hacerse.
               SELECT bool_or(true) FROM public.stock_movement sm
                WHERE sm.recipe_item_id = v_item_id
                  AND sm.location_id    = v_location_id
                  AND sm.occurred_at    > prev.counted_at
                  AND (sm.source_type = 'goods_receipt_line'
                       OR sm.movement_type IN ('recepcion','traspaso_entrada','apertura'))
             ), false) AS entradas
        FROM public.inventory_count_line prev
        JOIN public.inventory_count pic ON pic.id = prev.inventory_count_id
       WHERE prev.recipe_item_id = v_item_id
         AND prev.account_id     = v_account_id
         AND pic.location_id     = v_location_id
         AND pic.status          = 'aprobado'
         AND prev.counted_qty IS NOT NULL
         AND prev.counted_at  IS NOT NULL
         AND prev.id <> p_line_id
       ORDER BY prev.counted_at DESC
       LIMIT 1
    ) ref;

  -- ¿TENÍA FOLVY CON QUÉ COMPARAR? Ninguno de los dos frenos puede correr si su
  -- referencia no es un número positivo: el (a) exige `v_teorico > 0` y el (b)
  -- `v_ref_qty > 0`. Cuando las dos fallan —una ficha con el teórico en
  -- negativo, como Humus a −355 g— la línea se guarda SIN QUE NADIE LA MIRE.
  -- No se frena a quien cuenta, que no tiene culpa de la ficha: se marca para
  -- que la aprobación lo sepa.
  --
  -- EN UNA APERTURA NO SE MARCA. «Folvy no tenía referencia» sería cierto en
  -- TODAS las líneas —es la definición de una apertura— y una etiqueta que
  -- sale siempre no informa de nada: sería ruido en la única pantalla donde
  -- hace falta que se lea la que importa.
  v_sin_ref := NOT v_apertura
           AND (v_teorico IS NULL OR v_teorico <= 0)
           AND (v_ref_qty  IS NULL OR v_ref_qty  <= 0);

  IF NOT v_segundo THEN
    -- LOS DOS FRENOS, APAGADOS EN UNA APERTURA (10/09, noche). Comparan con
    -- el teórico vivo y con el último recuento aprobado, y en una apertura
    -- los dos son cifras que YA SABEMOS FALSAS: el teórico de Bolsas
    -- Personalizadas en Alcalá son 149.250 ud. Frenar contra eso mandaría a
    -- recontar media apertura por no parecerse a una mentira.
    --
    -- La red de cordura (FV001, el disparador simétrico) NO se apaga: esa no
    -- compara con nada, caza el cero de más. Y su confirmación expresa sigue
    -- siendo la puerta para pasarla.
    IF NOT v_apertura AND v_teorico IS NOT NULL AND v_teorico > 0 THEN
      IF v_total >= v_teorico * v_factor OR v_total <= v_teorico / v_factor THEN
        v_veredicto := 'recount';
      END IF;
    END IF;

    -- Sin entradas de por medio, apartarse del recuento anterior es una
    -- contradicción, no deriva. Con entradas, este freno se calla: el stock
    -- ha cambiado por una razón conocida.
    IF NOT v_apertura AND v_veredicto = 'ok'
       AND v_ref_qty IS NOT NULL AND NOT v_hubo_entrada AND v_ref_qty > 0 THEN
      IF abs(v_total - v_ref_qty) / v_ref_qty * 100 >= v_contra_pct THEN
        v_veredicto := 'recount';
      END IF;
    END IF;

  ELSE
    -- SEGUNDA MIRADA (o tercera, o cuarta): se acepta siempre. Sólo decide
    -- cómo queda sellado.
    --
    -- Se compara con el TOTAL DEL INTENTO ANTERIOR, que está en las entradas,
    -- no con `counted_qty` — que en un `recount` se quedó sin escribir a
    -- propósito. Comparar contra un NULL haría que «lo he mirado bien: es lo
    -- que hay» acabara SIEMPRE en `needs_review`, y entonces «confirmado dos
    -- veces» no existiría nunca: la etiqueta estaría en la pantalla y no
    -- podría salir.
    SELECT SUM(qty_in_base) INTO v_anterior
      FROM public.inventory_count_entry
     WHERE line_id = p_line_id AND attempt = v_intento - 1;

    IF v_anterior IS NOT NULL AND (
         (v_anterior = 0 AND v_total = 0)
      OR (v_anterior <> 0 AND abs(v_total - v_anterior) / abs(v_anterior) * 100 <= v_repeat_pct)
    ) THEN
      v_confirmado := true;    -- ha mirado dos veces y le sale lo mismo
    ELSE
      v_revisar := true;       -- sigue sin cuadrar: no se aplica solo
    END IF;

    -- UNA CORRECCIÓN POR TELÉFONO NO ES «NO CUADRÓ DOS VECES».
    --
    -- Las dos etiquetas de arriba describen a alguien que miró dos veces A
    -- CIEGAS. En una corrección desde revisión no ha pasado eso: la oficina
    -- está delante, VIENDO lo esperado, ha llamado precisamente porque la
    -- cifra estaba mal, y la nueva sustituye a la vieja a sabiendas. Que
    -- cambie mucho es el propósito, no un síntoma.
    --
    -- Y `needs_review` no es sólo una pastilla: medido en
    -- `count_lines_requiring_reason`, es uno de los cinco motivos que obligan
    -- a poner un motivo para aprobar. Dejarlo puesto haría que la línea
    -- corregida siguiera pidiendo motivo para siempre — lo contrario de lo
    -- que pide el encargo.
    IF v_por_telefono THEN
      v_confirmado := false;
      v_revisar    := false;
    END IF;
  END IF;

  -- Confirmar a mano una cantidad que la red de cordura había rechazado vale
  -- para los dos intentos: quien la confirma ya ha dicho que la ha mirado. Va
  -- FUERA del if de arriba a propósito — dentro de la primera rama no serviría
  -- de nada en el segundo intento, que es justo donde la red sigue puesta.
  IF p_confirm IS NOT NULL AND p_confirm = v_total THEN
    v_forzado   := true;
    v_veredicto := 'ok';
    v_revisar   := false;
  END IF;

  -- ── Guardar SIEMPRE lo tecleado ─────────────────────────────────────────
  -- El intento se guarda aunque el veredicto sea `recount`: lo que la persona
  -- tecleó es un hecho y no se tira. Lo que no se sella todavía es la línea.
  --
  -- `recorded_by` se queda en NULL cuando quien apunta ES quien cuenta: un
  -- «apuntado por Pamela» debajo de «contó Pamela» sería ruido, y además
  -- distinguir el NULL permite saber después cuáles se dictaron.
  INSERT INTO public.inventory_count_entry
    (account_id, line_id, format_id, qty, fraction, qty_in_base, method, attempt,
     counted_by, counted_by_name, recorded_by, recorded_by_name, source)
  SELECT v_account_id, p_line_id,
         NULLIF(e->>'format_id','')::uuid,
         NULLIF(e->>'qty','')::numeric,
         NULLIF(e->>'fraction','')::numeric,
         (e->>'base')::numeric,
         e->>'method',
         v_intento,
         COALESCE(v_quien_emp, v_actor_emp, v_actor),
         COALESCE(v_quien_name, v_actor_name),
         CASE WHEN v_quien_emp IS NOT NULL THEN COALESCE(v_actor_emp, v_actor) END,
         CASE WHEN v_quien_emp IS NOT NULL THEN v_actor_name END,
         v_source
    FROM jsonb_array_elements(v_conv) e;

  IF v_veredicto = 'recount' THEN
    -- No se sella: la línea sigue sin contar y el móvil enseña la pantalla 3
    -- con las casillas vacías. `recount_asked_at` es lo que hace que el
    -- siguiente guardado se acepte sin discusión.
    UPDATE public.inventory_count_line
       SET recount_asked_at = now()
     WHERE id = p_line_id;
  ELSE
    -- EL SELLO DE LA PUERTA (p11, incidente del 10/09). Se pone justo antes
    -- del UPDATE y se quita justo después: la ventana en la que vale es UNA
    -- sentencia. Y lleva el id de la línea, así que no autoriza otra.
    PERFORM set_config('folvy.count_gate', p_line_id::text, true);
    UPDATE public.inventory_count_line
       SET counted_qty              = v_total,
           counted_at               = now(),
           counted_by               = COALESCE(v_quien_emp, v_actor_emp, counted_by),
           counted_by_name          = COALESCE(v_quien_name, v_actor_name, counted_by_name),
           counted_qty_confirmed    = CASE WHEN v_confirmado OR v_forzado THEN v_total ELSE NULL END,
           counted_qty_confirmed_at = CASE WHEN v_confirmado OR v_forzado THEN now() ELSE NULL END,
           needs_review             = v_revisar,
           no_reference             = v_sin_ref
     WHERE id = p_line_id;
    PERFORM set_config('folvy.count_gate', '', true);

    -- LAS DIFERENCIAS, AL DÍA. Si el recuento ya está cerrado —y una corrección
    -- desde revisión lo está siempre— las cifras de diferencia son las que se
    -- calcularon al cerrar, contra la cantidad VIEJA. Sin esto, la línea
    -- corregida seguiría pidiendo motivo por una desviación que ya no existe y
    -- la pantalla enseñaría un porcentaje que no es el de la cifra de al lado.
    --
    -- Mientras el recuento sigue abierto no se toca: ahí las diferencias no
    -- están calculadas todavía, y las calculará el cierre para todas a la vez.
    IF v_status = 'en_revision' THEN
      PERFORM public._recompute_count_line_variance(p_line_id);
    END IF;
  END IF;

  -- LO QUE VUELVE AL MÓVIL. `counted` es lo que ha tecleado la propia persona,
  -- así que devolverlo no le dice nada que no supiera. Lo esperado NO viaja:
  -- ni la cantidad, ni el porcentaje, ni el signo de la diferencia.
  RETURN jsonb_build_object(
    'verdict',      v_veredicto,
    'counted',      v_total,
    'entries',      v_n,
    'attempt',      v_intento,
    'estimated',    v_a_ojo,
    'confirmed',    v_confirmado,
    'needs_review', v_revisar,
    'no_reference', v_sin_ref
  );
END;
$$;


--
-- Name: save_frequency_reward(uuid, boolean, integer, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_frequency_reward(p_account uuid, p_active boolean, p_threshold integer, p_discount_type text, p_value numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not (p_account = any(current_user_account_ids())) then
    raise exception 'forbidden';
  end if;
  if p_discount_type not in ('percent','fixed') then raise exception 'bad_type'; end if;
  if p_value is null or p_value <= 0 then raise exception 'bad_value'; end if;
  if p_discount_type = 'percent' and p_value > 100 then raise exception 'bad_percent'; end if;
  if p_threshold is null or p_threshold < 2 then raise exception 'bad_threshold'; end if;

  -- Cupón de frecuencia canónico de la cuenta (uno por cuenta; se reutiliza).
  select id into v_id from coupon
  where account_id = p_account and kind = 'frequency'
  limit 1;

  if v_id is null then
    insert into coupon (account_id, name, code, discount_type, value, applies_to,
                        auto_apply, first_order_only, max_per_customer, min_subtotal,
                        active, kind, frequency_threshold, created_by)
    values (p_account, 'Bono por fidelidad', null, p_discount_type, p_value, 'subtotal',
            false, false, 1, null, coalesce(p_active,true), 'frequency', p_threshold, auth.uid())
    returning id into v_id;
  else
    update coupon set discount_type = p_discount_type, value = p_value,
                      frequency_threshold = p_threshold, active = coalesce(p_active,true),
                      updated_at = now()
    where id = v_id;
  end if;

  return jsonb_build_object('ok', true, 'couponId', v_id);
end;
$$;


--
-- Name: save_welcome_offer(uuid, boolean, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_welcome_offer(p_account uuid, p_active boolean, p_discount_type text, p_value numeric, p_floor_pct numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not (p_account = any(current_user_account_ids())) then
    raise exception 'forbidden';
  end if;
  if p_discount_type not in ('percent','fixed') then raise exception 'bad_type'; end if;
  if p_value is null or p_value <= 0 then raise exception 'bad_value'; end if;
  if p_discount_type = 'percent' and p_value > 100 then raise exception 'bad_percent'; end if;
  if p_floor_pct is not null and (p_floor_pct < 0 or p_floor_pct > 100) then raise exception 'bad_floor'; end if;

  -- Cupón de bienvenida canónico de la cuenta: auto_apply + first_order_only.
  select id into v_id from coupon
  where account_id = p_account and auto_apply and first_order_only
  limit 1;

  if v_id is null then
    insert into coupon (account_id, name, code, discount_type, value, applies_to,
                        auto_apply, first_order_only, max_per_customer, min_subtotal, active, created_by)
    values (p_account, 'Bienvenida', null, p_discount_type, p_value, 'subtotal',
            true, true, 1, null, coalesce(p_active,true), auth.uid())
    returning id into v_id;
  else
    update coupon set discount_type = p_discount_type, value = p_value,
                      active = coalesce(p_active,true), updated_at = now()
    where id = v_id;
  end if;

  update accounts set shop_coupon_margin_floor_pct = p_floor_pct where id = p_account;

  return jsonb_build_object('ok', true, 'couponId', v_id);
end;
$$;


--
-- Name: schedule_coverage_gap(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_coverage_gap(p_account uuid, p_location uuid, p_week_start date) RETURNS TABLE(fecha date, hora integer, required_total integer, assigned_total integer, gap integer, assigned_cost_hour numeric, cost_is_partial boolean)
    LANGUAGE sql STABLE
    AS $$
  with req as (
    select r.fecha, r.hora, sum(r.required)::int as required_total
    from public.team_labor_requirement(p_account, p_location, p_week_start) r
    where r.is_estimate = false
    group by r.fecha, r.hora
  ),
  asign as (
    select (p_week_start + ((dia.key)::int))::date as fecha,
           (emp.value #>> '{}')::uuid as employee_id, st.start_time, st.end_time
    from public.schedules s
    cross join lateral jsonb_each(s.cells) shift
    cross join lateral jsonb_each(shift.value) dia
    cross join lateral jsonb_array_elements(dia.value) emp
    join public.shift_templates st on st.id = (shift.key)::uuid
    where s.location_id = p_location and s.week_start = p_week_start
  ),
  horas as (
    select a.employee_id,
           (a.fecha + (h || ' hours')::interval)::date as fecha,
           (extract(hour from (a.fecha + (h || ' hours')::interval)))::int as hora
    from asign a
    cross join lateral generate_series(
      extract(hour from a.start_time)::int,
      case when a.end_time <= a.start_time
           then extract(hour from a.end_time)::int + 24
           else extract(hour from a.end_time)::int end - 1
    ) h
  ),
  -- ÚLTIMA nómina de cada empleado (no la del mes planificado, que no existe al planificar el futuro)
  ult_nomina as (
    select distinct on (pc.employee_id)
           pc.employee_id, pc.total_cost, pc.period_year, pc.period_month
    from public.payroll_cost pc
    where pc.account_id = p_account
    order by pc.employee_id, pc.period_year desc, pc.period_month desc
  ),
  coste as (
    select u.employee_id,
           u.total_cost / nullif((
             select sum(w.minutes)/60.0 from public.team_worked_shifts(p_account,
                    make_date(u.period_year, u.period_month, 1)::timestamptz,
                    (make_date(u.period_year, u.period_month, 1) + interval '1 month')::timestamptz) w
             where w.employee_id = u.employee_id), 0) as coste_hora
    from ult_nomina u
  ),
  media as (select avg(coste_hora) as m from coste where coste_hora is not null),
  agg as (
    select h.fecha, h.hora, count(*)::int as assigned_total,
           sum(coalesce(c.coste_hora, (select m from media))) as coste,
           bool_or(c.coste_hora is null) as falta_nomina
    from horas h left join coste c on c.employee_id = h.employee_id
    group by h.fecha, h.hora
  )
  select coalesce(r.fecha, a.fecha), coalesce(r.hora, a.hora),
         coalesce(r.required_total, 0), coalesce(a.assigned_total, 0),
         coalesce(a.assigned_total,0) - coalesce(r.required_total,0),
         round(coalesce(a.coste,0), 2), coalesce(a.falta_nomina, false)
  from req r
  full outer join agg a on a.fecha = r.fecha and a.hora = r.hora
  order by 1, 2;
$$;


--
-- Name: search_extras_by_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_extras_by_token(p_device_token text, p_query text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_device kds_device; v_q text;
BEGIN
  v_device := public.kds_resolve_device(p_device_token);
  IF v_device.id IS NULL THEN
    RAISE EXCEPTION 'search_extras_by_token: token no válido';
  END IF;
  v_q := '%' || lower(btrim(COALESCE(p_query, ''))) || '%';
  RETURN COALESCE((
    SELECT jsonb_agg(x ORDER BY x->>'name')
    FROM (
      SELECT jsonb_build_object(
               'clave',     lower(btrim(mo.name)),
               'name',      min(mo.name),
               'option_id', min(mo.id::text),
               'opciones',  count(*),
               'marcas',    count(DISTINCT mg.brand_id),
               'con_ref',   count(*) FILTER (WHERE mo.external_id IS NOT NULL),
               'sin_ref',   count(*) FILTER (WHERE mo.external_id IS NULL)) AS x
        FROM public.modifier_option mo
        JOIN public.modifier_group mg ON mg.id = mo.modifier_group_id
       WHERE mo.account_id = v_device.account_id AND mo.is_active
         AND lower(mo.name) LIKE v_q
       GROUP BY lower(btrim(mo.name))
      HAVING count(*) FILTER (WHERE mo.external_id IS NOT NULL) > 0
       LIMIT 40
    ) s
  ), '[]'::jsonb);
END;
$$;


--
-- Name: search_products_86(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_products_86(p_account_id uuid, p_query text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_term text := btrim(coalesce(p_query, ''));
begin
  if not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'search_products_86: sin acceso a la cuenta %', p_account_id;
  end if;
  if length(v_term) < 2 then return '[]'::jsonb; end if;

  return coalesce((
    with rows as (
      select mi.id, mi.external_id, mi.recipe_item_id, mi.brand_id, mi.name, mi.product_type,
             coalesce(mi.recipe_item_id::text, mi.external_id, mi.id::text) as pkey
      from menu_item mi join brand b on b.id = mi.brand_id
      where mi.account_id = p_account_id and b.is_active
        and mi.name ilike '%' || v_term || '%'
        and not exists ( select 1 from product_availability pa
          where pa.account_id = p_account_id
            and ( (mi.external_id is not null and pa.external_id = mi.external_id)
               or (mi.recipe_item_id is not null and pa.recipe_item_id = mi.recipe_item_id) )
            and (pa.location_id = p_location_id or pa.location_id is null) )
      limit 200
    ), grouped as (
      select pkey, (array_agg(id order by id))[1] as menu_item_id,
             (array_agg(name order by id))[1] as name,
             (array_agg(external_id order by id))[1] as external_id,
             (array_agg(recipe_item_id order by id))[1] as recipe_item_id,
             bool_or(product_type = 'combo') as is_combo,
             count(distinct brand_id) as brands
      from rows group by pkey
    )
    select jsonb_agg(jsonb_build_object('menuItemId', menu_item_id, 'name', name,
             'externalId', external_id, 'recipeItemId', recipe_item_id,
             'brands', brands, 'isCombo', is_combo) order by name)
    from grouped), '[]'::jsonb);
end;
$$;


--
-- Name: search_products_by_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_products_by_token(p_device_token text, p_query text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device; v_term text := btrim(coalesce(p_query, ''));
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'search_products_by_token: token no valido'; end if;
  if length(v_term) < 2 then return '[]'::jsonb; end if;

  return coalesce((
    with rows as (
      select mi.id, mi.external_id, mi.recipe_item_id, mi.brand_id, mi.name, mi.product_type,
             coalesce(mi.recipe_item_id::text, mi.external_id, mi.id::text) as pkey
      from menu_item mi join brand b on b.id = mi.brand_id
      where mi.account_id = v_device.account_id and b.is_active
        and mi.name ilike '%' || v_term || '%'
        and not exists ( select 1 from product_availability pa
          where pa.account_id = v_device.account_id
            and ( (mi.external_id is not null and pa.external_id = mi.external_id)
               or (mi.recipe_item_id is not null and pa.recipe_item_id = mi.recipe_item_id) )
            and (pa.location_id = v_device.location_id or pa.location_id is null) )
      limit 200
    ), grouped as (
      select pkey, (array_agg(id order by id))[1] as menu_item_id,
             (array_agg(name order by id))[1] as name,
             (array_agg(external_id order by id))[1] as external_id,
             (array_agg(recipe_item_id order by id))[1] as recipe_item_id,
             bool_or(product_type = 'combo') as is_combo,
             count(distinct brand_id) as brands
      from rows group by pkey
    )
    select jsonb_agg(jsonb_build_object('menuItemId', menu_item_id, 'name', name,
             'externalId', external_id, 'recipeItemId', recipe_item_id,
             'brands', brands, 'isCombo', is_combo) order by name)
    from grouped), '[]'::jsonb);
end;
$$;


--
-- Name: seed_account_scenes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_account_scenes(p_account_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  if not current_user_is_admin_or_manager_of(p_account_id) then raise exception 'no autorizado'; end if;
  if exists(select 1 from social_scene where account_id = p_account_id) then return 0; end if;
  insert into social_scene(account_id, mode, label, prompt, is_active, weight, lang)
  select p_account_id, mode, label, prompt, is_active, weight, lang
    from social_scene where account_id is null;
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: seed_appcc_for_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_appcc_for_account(p_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  -- IDs de planes (referencias estables a la tabla global appcc_plans)
  v_plan_aguas uuid;
  v_plan_limpieza uuid;
  v_plan_plagas uuid;
  v_plan_formacion uuid;
  v_plan_trazabilidad uuid;
  v_plan_mantenimiento uuid;
  v_plan_cadena_frio uuid;
  -- IDs de plantillas creadas (para insertar sus items después)
  v_tpl_id uuid;
  -- IDs de auditorías y secciones
  v_audit_id uuid;
  v_section_id uuid;
BEGIN
  -- Guard: si la cuenta ya tiene plantillas seed (detectado por la presencia
  -- del code 'agua_cloro_grifo' que es la primera que sembramos), no hacer nada.
  -- Detectamos por code en lugar de is_seed porque el patrón B2 (D1) usa
  -- is_seed=false en plantillas replicadas → no podríamos distinguir seed
  -- de las custom del cliente con solo is_seed.
  IF EXISTS (
    SELECT 1 FROM appcc_templates
    WHERE account_id = p_account_id AND code = 'agua_cloro_grifo'
  ) THEN
    RAISE NOTICE 'Cuenta % ya tiene plantillas seed (code agua_cloro_grifo existe), omitiendo seed_appcc_for_account', p_account_id;
    RETURN;
  END IF;

  -- Resolver IDs de planes globales
  SELECT id INTO v_plan_aguas FROM appcc_plans WHERE code = 'plan_aguas';
  SELECT id INTO v_plan_limpieza FROM appcc_plans WHERE code = 'plan_limpieza';
  SELECT id INTO v_plan_plagas FROM appcc_plans WHERE code = 'plan_plagas';
  SELECT id INTO v_plan_formacion FROM appcc_plans WHERE code = 'plan_formacion';
  SELECT id INTO v_plan_trazabilidad FROM appcc_plans WHERE code = 'plan_trazabilidad';
  SELECT id INTO v_plan_mantenimiento FROM appcc_plans WHERE code = 'plan_mantenimiento';
  SELECT id INTO v_plan_cadena_frio FROM appcc_plans WHERE code = 'plan_cadena_frio';

  IF v_plan_aguas IS NULL OR v_plan_limpieza IS NULL OR v_plan_plagas IS NULL
     OR v_plan_formacion IS NULL OR v_plan_trazabilidad IS NULL
     OR v_plan_mantenimiento IS NULL OR v_plan_cadena_frio IS NULL THEN
    RAISE EXCEPTION 'Planes globales no sembrados. Ejecuta Bloque 1.A primero.';
  END IF;

  -- ============================================================
  -- PLAN 1: CONTROL DE AGUAS
  -- ============================================================

  -- 1.1 Cloro residual en grifo de cocina (semanal)
  INSERT INTO appcc_templates (account_id, plan_id, code, name, description, is_seed, is_active, estimated_minutes)
  VALUES (p_account_id, v_plan_aguas, 'agua_cloro_grifo',
    'Control de cloro residual en grifo',
    'Medición semanal del cloro residual libre en grifo de cocina. Frecuencia: agua de red sin instalación intermedia = semanal.',
    false, true, 5)
  RETURNING id INTO v_tpl_id;

  INSERT INTO appcc_template_items
    (template_id, code, label, help_text, field_type, is_required, display_order, numeric_min, numeric_max, numeric_unit, creates_incident_on_fail, incident_severity)
  VALUES
    (v_tpl_id, 'cloro_ppm', 'Cloro residual libre',
     'Rango legal: 0.2-1.0 ppm (mg/L). Fuera de rango = incidencia.',
     'numeric', true, 1, 0.2, 1.0, 'ppm', true, 'high'),
    (v_tpl_id, 'grifo_estado', '¿Grifo en buen estado (sin fugas ni sarro)?',
     null,
     'boolean', true, 2, null, null, null, false, null),
    (v_tpl_id, 'observaciones', 'Observaciones',
     null,
     'text', false, 3, null, null, null, false, null);

  -- 1.2 Limpieza y desinfección de depósitos (anual)
  INSERT INTO appcc_templates (account_id, plan_id, code, name, description, is_seed, is_active, estimated_minutes)
  VALUES (p_account_id, v_plan_aguas, 'agua_limpieza_depositos',
    'Limpieza y desinfección de depósitos de agua',
    'Limpieza anual obligatoria de depósitos de agua potable. Aplica solo si hay instalación intermedia.',
    false, true, 60)
  RETURNING id INTO v_tpl_id;

  INSERT INTO appcc_template_items
    (template_id, code, label, help_text, field_type, is_required, display_order, creates_incident_on_fail, incident_severity)
  VALUES
    (v_tpl_id, 'deposito_vaciado', '¿Depósito vaciado completamente?',
     null, 'boolean', true, 1, true, 'medium'),
    (v_tpl_id, 'deposito_cepillado', '¿Paredes cepilladas y enjuagadas?',
     null, 'boolean', true, 2, true, 'medium'),
    (v_tpl_id, 'deposito_desinfectado', '¿Aplicado desinfectante alimentario?',
     'Hipoclorito sódico a 50 ppm durante 30 minutos, según protocolo.',
