--
-- Name: seed_vacation_settings_for_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_vacation_settings_for_account(p_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Guard: si la cuenta ya tiene fila global, no hacer nada (idempotente).
  IF EXISTS (
    SELECT 1 FROM public.vacation_settings
    WHERE account_id = p_account_id AND scope = 'global'
  ) THEN
    RAISE NOTICE 'Cuenta % ya tiene vacation_settings global, omitiendo seed', p_account_id;
    RETURN;
  END IF;

  -- Inserta la fila global tomando los defaults de la tabla para los valores
  -- de politica (vacation_days_per_year=30, asuntos=3, min_staff=2,
  -- min_lead=30, scope='global', request_types_disabled='{}').
  INSERT INTO public.vacation_settings (account_id)
  VALUES (p_account_id);

  RAISE NOTICE 'vacation_settings global creada para cuenta %', p_account_id;
END;
$$;


--
-- Name: set_account_discount(uuid, text, numeric, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_account_discount(p_account_id uuid, p_discount_type text, p_value numeric, p_note text DEFAULT NULL::text, p_valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT current_user_is_admin() THEN
    RAISE EXCEPTION 'Acceso denegado: solo platform admins.';
  END IF;
  IF p_discount_type NOT IN ('percent','fixed') THEN
    RAISE EXCEPTION 'Tipo de descuento inválido (percent|fixed).';
  END IF;
  IF p_value IS NULL OR p_value <= 0 THEN
    RAISE EXCEPTION 'El valor del descuento debe ser mayor que 0.';
  END IF;
  IF p_discount_type = 'percent' AND p_value > 100 THEN
    RAISE EXCEPTION 'Un porcentaje no puede pasar de 100.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM accounts WHERE id = p_account_id) THEN
    RAISE EXCEPTION 'Cuenta no encontrada.';
  END IF;

  -- MODELO A: desactivar el activo anterior (si lo hay) antes de insertar el nuevo.
  UPDATE account_discount SET active = false
  WHERE account_id = p_account_id AND active;

  INSERT INTO account_discount (account_id, discount_type, value, note, valid_until, active, created_by)
  VALUES (p_account_id, p_discount_type, p_value, NULLIF(btrim(coalesce(p_note,'')), ''), p_valid_until, true, auth.uid());

  PERFORM log_platform_event(
    'system_config_changed', p_account_id, NULL,
    jsonb_build_object(
      'config', 'account_discount', 'action', 'set',
      'discount_type', p_discount_type, 'value', p_value,
      'note', NULLIF(btrim(coalesce(p_note,'')), ''),
      'valid_until', p_valid_until));
END;
$$;


