-- Name: set_brand_status(uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_brand_status(p_brand_id uuid, p_mode text, p_resume_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  raise exception 'set_brand_status: esta version cierra la marca en TODOS los locales y '
                  'esta retirada desde el 01/09/2026. Actualiza la aplicacion: ahora hay que '
                  'indicar el local. Desde la tablet de cocina no hace falta hacer nada.';
end;
$$;


--
-- Name: FUNCTION set_brand_status(p_brand_id uuid, p_mode text, p_resume_at timestamp with time zone, p_reason text, p_reason_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_brand_status(p_brand_id uuid, p_mode text, p_resume_at timestamp with time zone, p_reason text, p_reason_code text) IS 'RETIRADA 01/09/2026. Solo lanza excepcion. Existe para que un cliente viejo reciba un mensaje que se entiende. BORRAR cuando no queden llamadas de 5 argumentos: select count(*) from availability_event where scope=''brand'' and location_id is null and occurred_at > now() - interval ''30 days'';';


--
-- Name: set_brand_status(uuid, text, uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_brand_status(p_brand_id uuid, p_mode text, p_location_id uuid, p_resume_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_loc_acc    uuid;
begin
  select account_id into v_account_id from brand where id = p_brand_id;
  if v_account_id is null then
    raise exception 'set_brand_status: marca % no encontrada', p_brand_id;
  end if;

  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_account_id)) then
    raise exception 'set_brand_status: sin acceso a la cuenta %', v_account_id;
  end if;

  -- (02/09) ALCANCE POR LOCAL. Hasta hoy el local era un filtro, no una
  -- autorizacion: un admin acotado podia operar sobre cualquier local de
  -- su cuenta. El criterio sale de current_user_location_ids().
  perform public._assert_location_in_scope(p_location_id, 'set_brand_status');

  if p_location_id is null then
    raise exception 'set_brand_status: falta el local. Cerrar una marca es POR LOCAL: '
                    'en la vista consolidada no se puede decidir en cual.';
  end if;

  select account_id into v_loc_acc from locations where id = p_location_id;
  if v_loc_acc is null then
    raise exception 'set_brand_status: local % no encontrado', p_location_id;
  end if;
  if v_loc_acc <> v_account_id then
    raise exception 'set_brand_status: el local no pertenece a la cuenta de la marca';
  end if;

  return public._set_brand_closure_core(
    p_brand_id, array[p_location_id], p_mode, p_resume_at, p_reason,
    p_reason_code, v_account_id, auth.uid(), 'oficina', 'web');
end;
$$;


--
-- Name: set_brand_status_by_token(text, uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_brand_status_by_token(p_device_token text, p_brand_id uuid, p_mode text, p_resume_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device    kds_device;
  v_brand_acc uuid;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'set_brand_status_by_token: token de dispositivo no valido';
  end if;
  if v_device.location_id is null then
    raise exception 'set_brand_status_by_token: el dispositivo % no tiene local asignado; '
                    'cerrar una marca es por local y sin local no se puede decidir', v_device.id;
  end if;

  select account_id into v_brand_acc from brand where id = p_brand_id;
  if v_brand_acc is null then
    raise exception 'set_brand_status_by_token: marca % no encontrada', p_brand_id;
  end if;
  if v_brand_acc <> v_device.account_id then
    raise exception 'set_brand_status_by_token: la marca no pertenece a la cuenta del dispositivo';
  end if;

  return public._set_brand_closure_core(
    p_brand_id, array[v_device.location_id], p_mode, p_resume_at, p_reason,
    p_reason_code, v_device.account_id, null, 'cocina', 'tablet');
end;
$$;


--
-- Name: set_count_line_excluded(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_count_line_excluded(p_line_id uuid, p_reason text, p_excluded boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_account uuid; v_status text; v_actor uuid := auth.uid(); v_nom text;
BEGIN
  SELECT l.account_id, ic.status INTO v_account, v_status
    FROM public.inventory_count_line l
    JOIN public.inventory_count ic ON ic.id = l.inventory_count_id
   WHERE l.id = p_line_id;
  IF v_account IS NULL THEN
    RAISE EXCEPTION 'set_count_line_excluded: la línea % no existe', p_line_id;
  END IF;
  IF NOT public.belongs_to_account(v_account) THEN
    RAISE EXCEPTION 'set_count_line_excluded: sin acceso a la cuenta';
  END IF;
  IF v_status IN ('aprobado', 'anulado') THEN
    RAISE EXCEPTION 'set_count_line_excluded: el recuento está % y ya no se puede tocar', v_status;
  END IF;
  IF NOT p_excluded THEN
    UPDATE public.inventory_count_line
       SET excluded_at = NULL, excluded_by = NULL,
           excluded_by_name = NULL, excluded_reason = NULL
     WHERE id = p_line_id;
    RETURN;
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'set_count_line_excluded: apartar una línea necesita un motivo. Sin él, mañana nadie sabrá por qué no se aplicó.';
  END IF;
  SELECT up.display_name INTO v_nom FROM public.user_profiles up
   WHERE up.user_id = v_actor AND up.account_id = v_account LIMIT 1;
  UPDATE public.inventory_count_line
     SET excluded_at = now(), excluded_by = v_actor,
         excluded_by_name = v_nom, excluded_reason = trim(p_reason)
   WHERE id = p_line_id;
END;
$$;


