--
-- Name: set_launch_phase(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_launch_phase(p_account_id uuid, p_phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not current_user_is_admin_or_manager_of(p_account_id) then
    raise exception 'no autorizado';
  end if;
  if p_phase not in ('apetito','comunidad','conversion') then
    raise exception 'fase invalida: %', p_phase;
  end if;
  update social_config set launch_phase = p_phase, updated_by = auth.uid(), updated_at = now()
   where account_id = p_account_id;
  if not found then
    insert into social_config(account_id, launch_phase, updated_by) values (p_account_id, p_phase, auth.uid());
  end if;
end $$;


--
-- Name: set_location_assignment(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_location_assignment(p_location_id uuid, p_strategy text, p_timeout_s integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update locations set
    assignment_strategy = case when p_strategy in ('broadcast','nearest') then p_strategy else assignment_strategy end,
    offer_timeout_s = case when p_timeout_s is not null and p_timeout_s between 15 and 600 then p_timeout_s else offer_timeout_s end
  where id = p_location_id and account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(account_id);
end; $$;


