-- Name: set_location_bonus(uuid, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_location_bonus(p_location_id uuid, p_rain_pct numeric, p_demand_max_pct numeric, p_combined_cap_pct numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update locations set
    bonus_rain_pct = greatest(0, coalesce(p_rain_pct,0)),
    bonus_demand_max_pct = greatest(0, coalesce(p_demand_max_pct,0)),
    bonus_combined_cap_pct = case when p_combined_cap_pct is null then null else greatest(0,p_combined_cap_pct) end
  where id = p_location_id and account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(account_id);
end; $$;


--
-- Name: set_location_dispatch(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_location_dispatch(p_location_id uuid, p_mode text, p_broker text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update locations l set
    dispatch_mode  = case when p_mode  in ('auto','manual','off')  then p_mode  else l.dispatch_mode  end,
    dispatch_broker= case when p_broker in ('catcher','own_fleet') then p_broker else l.dispatch_broker end
  where l.id=p_location_id and l.account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(l.account_id);
end; $$;


--
-- Name: set_location_status(uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_location_status(p_location_id uuid, p_mode text, p_resume_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_loc_name   text;
  v_user       uuid := auth.uid();
  v_ext_loc    text;
  v_secret     text;
  v_log_id     uuid;
  v_patch      jsonb;
  v_action     text;
begin
  select account_id, name into v_account_id, v_loc_name from locations where id = p_location_id;
  if v_account_id is null then
    raise exception 'set_location_status: local % no encontrado', p_location_id;
  end if;

  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(v_account_id)) then
    raise exception 'set_location_status: sin acceso a la cuenta %', v_account_id;
  end if;

  if p_mode not in ('normal', 'busy', 'paused') then
    raise exception 'set_location_status: mode no válido %', p_mode;
  end if;

  if p_reason_code is not null and p_reason_code not in
     ('sin_stock','incidencia','fin_servicio','promocion','mantenimiento','otro') then
    raise exception 'set_location_status: reason_code no válido %', p_reason_code;
  end if;

  update locations
  set hubrise_status_mode      = p_mode,
      hubrise_status_resume_at = case when p_mode = 'normal' then null else p_resume_at end,
      hubrise_status_reason    = case when p_mode = 'normal' then null else p_reason end,
      hubrise_status_set_at    = now(),
      hubrise_status_set_by    = v_user
  where id = p_location_id;

  select elm.external_location_id into v_ext_loc
  from external_location_map elm
  where elm.account_id = v_account_id and elm.source = 'hubrise' and elm.is_active
    and elm.location_id = p_location_id
  limit 1;

  v_patch := jsonb_build_object('order_acceptance', jsonb_strip_nulls(jsonb_build_object(
    'mode', p_mode, 'resume_at', p_resume_at, 'reason', p_reason
  )));

  insert into location_status_log
    (account_id, location_id, external_location_id, kind, patch_body, mode, resume_at, reason, surface, set_by)
  values
    (v_account_id, p_location_id, v_ext_loc, 'order_acceptance', v_patch, p_mode, p_resume_at, p_reason, 'web', v_user)
  returning id into v_log_id;

  -- ANALÍTICA (C1) — fire-and-forget: nunca bloquea el cierre/apertura.
  v_action := case when p_mode = 'normal' then 'open' else 'close' end;
  begin
    insert into availability_event
      (account_id, scope, target_id, target_label, location_id, action, origin,
       reason_code, reason_note, actor_id, surface, resume_at)
    values
      (v_account_id, 'location', p_location_id, v_loc_name, p_location_id, v_action, 'oficina',
       case when v_action = 'close' then p_reason_code else null end,
       case when v_action = 'close' then p_reason else null end,
       v_user, 'web',
       case when v_action = 'close' then p_resume_at else null end);
  exception when others then
    raise warning 'set_location_status: fallo insertando availability_event: %', sqlerrm;
  end;

  if v_ext_loc is null then
    update location_status_log
    set ok = true, error = 'Local sin conexión HubRise: estado guardado solo en Folvy', resolved_at = now()
    where id = v_log_id;
    return jsonb_build_object('location_id', p_location_id, 'mode', p_mode, 'connected', false, 'log_id', v_log_id);
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets where name = 'location_status_dispatch_secret';

  if v_secret is null then
    update location_status_log
    set ok = false, error = 'secret location_status_dispatch_secret ausente en Vault', resolved_at = now()
    where id = v_log_id;
    raise warning 'set_location_status: secret location_status_dispatch_secret ausente en Vault, no se empuja a HubRise';
    return jsonb_build_object('location_id', p_location_id, 'mode', p_mode, 'connected', true, 'log_id', v_log_id, 'dispatched', false);
  end if;

  perform net.http_post(
    url     := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/hubrise-location-dispatch',
    headers := jsonb_build_object(
      'Content-Type',                       'application/json',
      'x-location-status-dispatch-secret',  v_secret
    ),
    body    := jsonb_build_object(
      'log_id',               v_log_id,
      'account_id',           v_account_id,
      'external_location_id', v_ext_loc,
      'patch_body',           v_patch
    )
  );

  return jsonb_build_object('location_id', p_location_id, 'mode', p_mode, 'connected', true, 'log_id', v_log_id, 'dispatched', true);
end;
$$;


--
-- Name: set_location_status_by_token(text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_location_status_by_token(p_device_token text, p_mode text, p_resume_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device     kds_device;
  v_account_id uuid;
  v_location   uuid;
  v_loc_name   text;
  v_ext_loc    text;
  v_secret     text;
  v_log_id     uuid;
  v_patch      jsonb;
  v_action     text;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'set_location_status_by_token: token de dispositivo no válido';
  end if;
  v_account_id := v_device.account_id;
  v_location   := v_device.location_id;
  

  if p_mode not in ('normal', 'busy', 'paused') then
    raise exception 'set_location_status_by_token: mode no válido %', p_mode;
  end if;

  if p_reason_code is not null and p_reason_code not in
     ('sin_stock','incidencia','fin_servicio','promocion','mantenimiento','otro') then
    raise exception 'set_location_status_by_token: reason_code no válido %', p_reason_code;
  end if;

  select name into v_loc_name from locations where id = v_location;

  update locations
  set hubrise_status_mode      = p_mode,
      hubrise_status_resume_at = case when p_mode = 'normal' then null else p_resume_at end,
      hubrise_status_reason    = case when p_mode = 'normal' then null else p_reason end,
      hubrise_status_set_at    = now(),
      hubrise_status_set_by    = null
  where id = v_location;

  select elm.external_location_id into v_ext_loc
  from external_location_map elm
  where elm.account_id = v_account_id and elm.source = 'hubrise' and elm.is_active
    and elm.location_id = v_location
  limit 1;

  v_patch := jsonb_build_object('order_acceptance', jsonb_strip_nulls(jsonb_build_object(
    'mode', p_mode, 'resume_at', p_resume_at, 'reason', p_reason
  )));

  insert into location_status_log
    (account_id, location_id, external_location_id, kind, patch_body, mode, resume_at, reason, surface, set_by)
  values
    (v_account_id, v_location, v_ext_loc, 'order_acceptance', v_patch, p_mode, p_resume_at, p_reason, 'tablet', null)
  returning id into v_log_id;

  -- ANALÍTICA (C1) — fire-and-forget: nunca bloquea el cierre/apertura.
  v_action := case when p_mode = 'normal' then 'open' else 'close' end;
  begin
    insert into availability_event
      (account_id, scope, target_id, target_label, location_id, action, origin,
       reason_code, reason_note, actor_id, surface, resume_at)
    values
      (v_account_id, 'location', v_location, v_loc_name, v_location, v_action, 'cocina',
       case when v_action = 'close' then p_reason_code else null end,
       case when v_action = 'close' then p_reason else null end,
       null, 'tablet',
       case when v_action = 'close' then p_resume_at else null end);
  exception when others then
    raise warning 'set_location_status_by_token: fallo insertando availability_event: %', sqlerrm;
  end;

  if v_ext_loc is null then
    update location_status_log
    set ok = true, error = 'Local sin conexión HubRise: estado guardado solo en Folvy', resolved_at = now()
    where id = v_log_id;
    return jsonb_build_object('location_id', v_location, 'mode', p_mode, 'connected', false, 'log_id', v_log_id);
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets where name = 'location_status_dispatch_secret';

  if v_secret is null then
    update location_status_log
    set ok = false, error = 'secret location_status_dispatch_secret ausente en Vault', resolved_at = now()
    where id = v_log_id;
    raise warning 'set_location_status_by_token: secret location_status_dispatch_secret ausente en Vault, no se empuja a HubRise';
    return jsonb_build_object('location_id', v_location, 'mode', p_mode, 'connected', true, 'log_id', v_log_id, 'dispatched', false);
  end if;

  perform net.http_post(
    url     := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/hubrise-location-dispatch',
    headers := jsonb_build_object(
      'Content-Type',                       'application/json',
      'x-location-status-dispatch-secret',  v_secret
    ),
    body    := jsonb_build_object(
      'log_id',               v_log_id,
      'account_id',           v_account_id,
      'external_location_id', v_ext_loc,
      'patch_body',           v_patch
    )
  );

  return jsonb_build_object('location_id', v_location, 'mode', p_mode, 'connected', true, 'log_id', v_log_id, 'dispatched', true);
end;
$$;


--
-- Name: set_location_weather(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_location_weather(p_location_id uuid, p_is_raining boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update locations set weather_is_raining = coalesce(p_is_raining,false), weather_updated_at = now()
  where id = p_location_id and account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(account_id);
end; $$;


--
-- Name: set_location_weather(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_location_weather(p_location_id uuid, p_is_raining boolean, p_auto boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update locations set
    weather_auto = coalesce(p_auto, false),
    weather_is_raining = case when p_auto is true then weather_is_raining else coalesce(p_is_raining, false) end,
    weather_updated_at = now()
  where id = p_location_id and account_id = any(current_user_account_ids())
    and current_user_is_admin_or_manager_of(account_id);
end; $$;


--
-- Name: set_menu_item_override(uuid, uuid, numeric, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_menu_item_override(p_menu_item_id uuid, p_channel_id uuid, p_price numeric DEFAULT NULL::numeric, p_is_available boolean DEFAULT true, p_location_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
BEGIN
  SELECT mi.account_id INTO v_account_id FROM menu_item mi WHERE mi.id = p_menu_item_id;
  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'Producto % no encontrado', p_menu_item_id;
  END IF;
  IF NOT (current_user_is_admin() OR current_user_is_admin_or_manager_of(v_account_id)) THEN
    RAISE EXCEPTION 'Sin permiso para editar precios de este producto';
  END IF;

  -- A.5 (deuda B7): dos validaciones defensivas, ni una mas.
  IF p_price IS NOT NULL AND p_price < 0 THEN
    RAISE EXCEPTION 'El precio no puede ser negativo (recibido %)', p_price;
  END IF;
  IF p_location_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM locations l
        WHERE l.id = p_location_id AND l.account_id = v_account_id) THEN
    RAISE EXCEPTION 'El local % no pertenece a la cuenta de este producto', p_location_id;
  END IF;

  INSERT INTO menu_item_override (account_id, menu_item_id, channel_id, location_id, price, is_available)
  VALUES (v_account_id, p_menu_item_id, p_channel_id, p_location_id, p_price, p_is_available)
  ON CONFLICT (menu_item_id,
               COALESCE(location_id, '00000000-0000-0000-0000-000000000000'::uuid),
               COALESCE(channel_id,  '00000000-0000-0000-0000-000000000000'::uuid))
  DO UPDATE SET price = EXCLUDED.price, is_available = EXCLUDED.is_available, updated_at = now();
END;
$$;


--
-- Name: set_menu_item_recipe(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_menu_item_recipe(p_menu_item_id uuid, p_recipe_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
  v_ri      recipe_item%rowtype;
begin
  select account_id into v_account from menu_item where id = p_menu_item_id;
  if v_account is null then
    raise exception 'set_menu_item_recipe: ítem % no existe', p_menu_item_id;
  end if;

  if not public.current_user_is_admin_of(v_account) then
    raise exception 'set_menu_item_recipe: sin acceso a la cuenta %', v_account;
  end if;

  -- El escandallo destino DEBE ser de la MISMA cuenta y estar vivo (candado anti-fuga).
  select * into v_ri from recipe_item
   where id = p_recipe_item_id and account_id = v_account;
  if not found then
    raise exception 'set_menu_item_recipe: el escandallo no existe o no es de esta cuenta';
  end if;
  if v_ri.archived_at is not null then
    raise exception 'set_menu_item_recipe: el escandallo "%" está archivado', v_ri.name;
  end if;

  begin
    update menu_item
       set recipe_item_id = p_recipe_item_id,
           link_approved_at = null,      -- cambiar enlace exige re-aprobar
           link_approved_by = null,
           updated_at = now()
     where id = p_menu_item_id;
  exception when unique_violation then
    -- Índice único (brand_id, channel_id, recipe_item_id): con channel_id no
    -- nulo, otro ítem de la misma marca+canal ya puede usar este escandallo.
    raise exception 'set_menu_item_recipe: ya existe otro ítem de esta marca/canal enlazado al escandallo "%"', v_ri.name;
  end;

  return jsonb_build_object('ok', true, 'menu_item_id', p_menu_item_id,
                            'recipe_item_id', p_recipe_item_id, 'recipe_name', v_ri.name);
end;
$$;


--
-- Name: set_modifier_option_availability(uuid, boolean, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_modifier_option_availability(p_option_id uuid, p_is_available boolean, p_location_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'stock_out'::text, p_available_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acct   uuid;
  v_clave  text;
  v_res    jsonb;
  v_refs   text[] := '{}';
  v_n      int := 0;
  v_sin    int := 0;
  v_label  text;
  v_r      record;
  v_secret text;
begin
  select account_id, lower(btrim(name)), name
    into v_acct, v_clave, v_label
    from modifier_option where id = p_option_id;
  if v_acct is null then
    raise exception 'set_modifier_option_availability: opcion % no encontrada', p_option_id;
  end if;
  if not (v_acct = any(public.current_user_account_ids())) then
    raise exception 'set_modifier_option_availability: sin acceso a la cuenta %', v_acct;
  end if;
  if p_location_id is not null and not exists (
      select 1 from locations l where l.id = p_location_id and l.account_id = v_acct) then
    raise exception 'set_modifier_option_availability: el local % no es de esta cuenta', p_location_id;
  end if;

  -- (02/09) ALCANCE POR LOCAL, ver current_user_location_ids().
  perform public._assert_location_in_scope(p_location_id, 'set_modifier_option_availability');

  -- TODAS LAS COPIAS DEL MISMO EXTRA, POR NOMBRE (11/09/2026). Las que no
  -- tienen `external_id` no se pueden empujar al canal: se saltan y se cuentan
  -- en `sin_ref` en vez de callarse (regla 7).
  for v_r in select * from public._extras_group_options(v_acct, v_clave)
  loop
    if v_r.external_id is null then
      v_sin := v_sin + 1;
      continue;
    end if;
    v_res := public._set_modifier_option_availability_core(
      v_r.option_id, p_is_available, p_location_id, p_reason, p_available_until,
      p_reason_code, v_acct, auth.uid(), 'oficina', 'web');
    v_refs := v_refs || array(select jsonb_array_elements_text(v_res->'option_refs'));
    v_n := v_n + 1;
  end loop;

  if array_length(v_refs, 1) > 0 then
    select decrypted_secret into v_secret from vault.decrypted_secrets
     where name = 'availability_dispatch_secret';
    if v_secret is not null then
      -- Se manda SOLO option_refs: sin `matriculas`, para que el despachador no
      -- confunda un ref de opcion con un sku de producto. expires_at lo pone el
      -- despachador desde available_until, igual que en los productos.
      perform net.http_post(
        url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/availability-dispatch',
        headers := jsonb_build_object('Content-Type','application/json','x-availability-dispatch-secret', v_secret),
        body := jsonb_build_object(
          'account_id', v_acct,
          'option_refs', to_jsonb(v_refs),
          'location_id', p_location_id,
          'available_until', p_available_until,
          'enable', p_is_available,
          'reason', p_reason));
    else
      raise warning 'set_modifier_option_availability: secret availability_dispatch_secret ausente en Vault, no se empuja al despachador';
    end if;
  end if;

  return jsonb_build_object(
    'label', coalesce(v_label, '(opcion)'),
    'opciones', v_n,
    'option_refs', coalesce(to_jsonb(v_refs), '[]'::jsonb),
    'sin_ref', v_sin,
    'available_until', p_available_until,
    'dispatched', v_secret is not null and coalesce(array_length(v_refs,1),0) > 0);
end;
$$;


--
-- Name: set_modifier_option_availability_by_token(text, uuid, boolean, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_modifier_option_availability_by_token(p_device_token text, p_option_id uuid, p_is_available boolean, p_reason text DEFAULT 'manual'::text, p_available_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_device kds_device; v_acct uuid; v_clave text; v_mo_acct uuid;
  v_refs text[] := '{}'; v_n int := 0; v_sin_ref int := 0;
  v_sec text; v_r record; v_core jsonb;
BEGIN
  v_device := public.kds_resolve_device(p_device_token);
  IF v_device.id IS NULL THEN
    RAISE EXCEPTION 'set_modifier_option_availability_by_token: token de dispositivo no valido';
  END IF;
  v_acct := v_device.account_id;

  SELECT mo.account_id, lower(btrim(mo.name)) INTO v_mo_acct, v_clave
    FROM public.modifier_option mo WHERE mo.id = p_option_id;
  IF v_mo_acct IS NULL THEN
    RAISE EXCEPTION 'set_modifier_option_availability_by_token: extra % no encontrado', p_option_id;
  END IF;
  IF v_mo_acct <> v_acct THEN
    RAISE EXCEPTION 'set_modifier_option_availability_by_token: el extra no pertenece a la cuenta del dispositivo';
  END IF;

  -- TODAS LAS COPIAS DEL MISMO EXTRA, POR NOMBRE. Quien agota «Salsa Yogur»
  -- desde la cocina no sabe —ni tiene por que saber— que hay 13 copias
  -- repartidas por marcas y grupos: agotar una sola dejaria las otras doce
  -- vendiendose. Las que no tienen `external_id` no se pueden empujar al
  -- canal, y eso se DEVUELVE en `sin_ref` en vez de callarse (regla 7).
  FOR v_r IN SELECT * FROM public._extras_group_options(v_acct, v_clave)
  LOOP
    IF v_r.external_id IS NULL THEN
      v_sin_ref := v_sin_ref + 1;
      CONTINUE;
    END IF;
    v_core := public._set_modifier_option_availability_core(
      v_r.option_id, p_is_available, v_device.location_id, p_reason,
      p_available_until, p_reason_code, v_acct, NULL, 'cocina', 'tablet');
    v_refs := v_refs || array(SELECT jsonb_array_elements_text(v_core->'option_refs'));
    v_n := v_n + 1;
  END LOOP;

  IF array_length(v_refs, 1) > 0 THEN
    SELECT decrypted_secret INTO v_sec FROM vault.decrypted_secrets
     WHERE name = 'availability_dispatch_secret';
    IF v_sec IS NOT NULL THEN
      -- UN solo empujon con todos los refs, no uno por copia.
      PERFORM net.http_post(
        url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/availability-dispatch',
        headers := jsonb_build_object('Content-Type','application/json','x-availability-dispatch-secret', v_sec),
        body := jsonb_build_object(
          'account_id', v_acct,
          'option_refs', to_jsonb(v_refs),
          'location_id', v_device.location_id,
          'available_until', p_available_until,
          'enable', p_is_available,
          'reason', p_reason));
    ELSE
      RAISE WARNING 'set_modifier_option_availability_by_token: secret availability_dispatch_secret ausente en Vault, no se empuja al despachador';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'opciones', v_n, 'refs', COALESCE(array_length(v_refs,1), 0),
    'sin_ref', v_sin_ref, 'location_id', v_device.location_id,
    'dispatched', v_sec IS NOT NULL AND COALESCE(array_length(v_refs,1),0) > 0);
END;
$$;


--
-- Name: set_my_clockout_reminder(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_clockout_reminder(p_enabled boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp uuid;
BEGIN
  SELECT employee_id INTO v_emp FROM current_employee_and_account();
  IF v_emp IS NULL THEN
    RAISE EXCEPTION 'no hay empleado vinculado a la sesión';
  END IF;
  UPDATE employees SET forgot_clockout_reminder = p_enabled WHERE id = v_emp;
  RETURN p_enabled;
END;
$$;


--
-- Name: set_n2_config(uuid, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_n2_config(p_account_id uuid, p_enabled boolean, p_cap integer, p_ratio integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not current_user_is_admin_or_manager_of(p_account_id) then raise exception 'no autorizado'; end if;
  update social_config
     set n2_enabled = p_enabled,
         n2_daily_cap = greatest(coalesce(p_cap, 30), 0),
         n2_mood_ratio = greatest(coalesce(p_ratio, 5), 0),
         updated_at = now()
   where account_id = p_account_id;
  if not found then
    insert into social_config(account_id, launch_phase, n2_enabled, n2_daily_cap, n2_mood_ratio)
    values (p_account_id, 'apetito', p_enabled, greatest(coalesce(p_cap,30),0), greatest(coalesce(p_ratio,5),0));
  end if;
end $$;


--
-- Name: set_order_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_order_status(p_sale_id uuid, p_new_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc uuid;
  v_cur text;
BEGIN
  SELECT account_id, order_status INTO v_acc, v_cur FROM sale WHERE id = p_sale_id;
  IF v_acc IS NULL THEN
    RAISE EXCEPTION 'set_order_status: venta inexistente';
  END IF;

  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(v_acc)) THEN
    RAISE EXCEPTION 'set_order_status: sin acceso a la cuenta %', v_acc;
  END IF;

  IF p_new_status IS NULL OR p_new_status NOT IN (
    'new','received','accepted','in_preparation','awaiting_collection',
    'awaiting_shipment','in_delivery','completed','rejected','cancelled','delivery_failed'
  ) THEN
    RAISE EXCEPTION 'set_order_status: estado no válido %', p_new_status;
  END IF;

  UPDATE sale
  SET order_status = p_new_status,
      updated_at   = now()
  WHERE id = p_sale_id;

  RETURN p_new_status;
END;
$$;


--
-- Name: set_order_status_by_token(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_order_status_by_token(p_device_token text, p_sale_id uuid, p_new_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device   kds_device;
  v_acc      uuid;
  v_loc      uuid;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'set_order_status_by_token: token no válido';
  end if;
  

  select account_id, location_id into v_acc, v_loc from sale where id = p_sale_id;
  if v_acc is null then
    raise exception 'set_order_status_by_token: venta inexistente';
  end if;
  if v_acc <> v_device.account_id then
    raise exception 'set_order_status_by_token: la venta no pertenece a la cuenta del dispositivo';
  end if;
  if v_device.location_id is not null and v_loc is distinct from v_device.location_id then
    raise exception 'set_order_status_by_token: la venta no pertenece al local del dispositivo';
  end if;

  if p_new_status is null or p_new_status not in (
    'new','received','accepted','in_preparation','awaiting_collection',
    'awaiting_shipment','in_delivery','completed','rejected','cancelled','delivery_failed'
  ) then
    raise exception 'set_order_status_by_token: estado no válido %', p_new_status;
  end if;

  update sale
  set order_status = p_new_status,
      updated_at   = now()
  where id = p_sale_id;

  return p_new_status;
end;
$$;


--
-- Name: set_plan_pricing(uuid, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_plan_pricing(p_plan_id uuid, p_base_price_eur numeric, p_per_location_price numeric, p_max_locations integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old billing_plans%ROWTYPE;
BEGIN
  IF NOT current_user_is_admin() THEN
    RAISE EXCEPTION 'Acceso denegado: solo platform admins.';
  END IF;
  IF p_base_price_eur < 0 OR p_per_location_price < 0 OR p_max_locations < 0 THEN
    RAISE EXCEPTION 'Los precios y el máximo de locales no pueden ser negativos.';
  END IF;

  SELECT * INTO v_old FROM billing_plans WHERE id = p_plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Plan no encontrado.'; END IF;

  UPDATE billing_plans
  SET base_price_eur     = p_base_price_eur,
      per_location_price = p_per_location_price,
      max_locations      = p_max_locations,
      updated_at         = now()
  WHERE id = p_plan_id;

  PERFORM log_platform_event(
    'system_config_changed', NULL, NULL,
    jsonb_build_object(
      'config', 'plan_pricing', 'plan', v_old.code,
      'from', jsonb_build_object('base', v_old.base_price_eur, 'per_location', v_old.per_location_price, 'max_locations', v_old.max_locations),
      'to',   jsonb_build_object('base', p_base_price_eur, 'per_location', p_per_location_price, 'max_locations', p_max_locations)));
END;
$$;


--
-- Name: set_platform_admin_active(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_platform_admin_active(p_admin_id uuid, p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_active boolean;
  v_name       text;
  v_user_id    uuid;
BEGIN
  PERFORM _require_manage_admins();

  SELECT active, full_name, user_id INTO v_old_active, v_name, v_user_id
  FROM platform_admins WHERE id = p_admin_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Admin no encontrado.';
  END IF;

  IF v_old_active = p_active THEN
    RETURN;
  END IF;

  -- protect_last_admin (BEFORE UPDATE) aborta si desactivas al último CEO.
  UPDATE platform_admins SET active = p_active WHERE id = p_admin_id;

  PERFORM log_platform_event(
    CASE WHEN p_active THEN 'admin_reactivated' ELSE 'admin_suspended' END,
    NULL, v_user_id,
    jsonb_build_object('admin', v_name));
END;
$$;


--
-- Name: set_platform_admin_permissions(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_platform_admin_permissions(p_admin_id uuid, p_permissions jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name       text;
  v_user_id    uuid;
  v_old        platform_admin_permissions%ROWTYPE;
  v_activated  text[] := ARRAY[]::text[];
  v_deactivated text[] := ARRAY[]::text[];
  -- nuevos valores
  n_create  boolean := COALESCE((p_permissions->>'platform_can_create_accounts')::boolean, false);
  n_suspend boolean := COALESCE((p_permissions->>'platform_can_suspend_accounts')::boolean, false);
  n_archive boolean := COALESCE((p_permissions->>'platform_can_archive_accounts')::boolean, false);
  n_delete  boolean := COALESCE((p_permissions->>'platform_can_delete_accounts')::boolean, false);
  n_seed    boolean := COALESCE((p_permissions->>'platform_can_edit_seed_data')::boolean, false);
  n_imp     boolean := COALESCE((p_permissions->>'platform_can_impersonate')::boolean, false);
  n_manage  boolean := COALESCE((p_permissions->>'platform_can_manage_admins')::boolean, false);
  n_2fa     boolean := COALESCE((p_permissions->>'platform_can_reset_2fa_of_others')::boolean, false);
  n_notif   boolean := COALESCE((p_permissions->>'platform_can_send_global_notifications')::boolean, false);
  n_audit   boolean := COALESCE((p_permissions->>'platform_can_view_audit_log')::boolean, false);
  n_health  boolean := COALESCE((p_permissions->>'platform_can_view_system_health')::boolean, false);
BEGIN
  PERFORM _require_manage_admins();

  SELECT full_name, user_id INTO v_name, v_user_id
  FROM platform_admins WHERE id = p_admin_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Admin no encontrado.';
  END IF;

  -- Estado anterior (si no hay fila, se tratan como defaults: false / true salud+audit).
  SELECT * INTO v_old FROM platform_admin_permissions WHERE platform_admin_id = p_admin_id;

  -- Diff legible para la auditoría.
  IF n_create  IS DISTINCT FROM COALESCE(v_old.platform_can_create_accounts,false)            THEN IF n_create  THEN v_activated:=v_activated||'create_accounts';      ELSE v_deactivated:=v_deactivated||'create_accounts';      END IF; END IF;
  IF n_suspend IS DISTINCT FROM COALESCE(v_old.platform_can_suspend_accounts,false)           THEN IF n_suspend THEN v_activated:=v_activated||'suspend_accounts';     ELSE v_deactivated:=v_deactivated||'suspend_accounts';     END IF; END IF;
  IF n_archive IS DISTINCT FROM COALESCE(v_old.platform_can_archive_accounts,false)           THEN IF n_archive THEN v_activated:=v_activated||'archive_accounts';     ELSE v_deactivated:=v_deactivated||'archive_accounts';     END IF; END IF;
  IF n_delete  IS DISTINCT FROM COALESCE(v_old.platform_can_delete_accounts,false)            THEN IF n_delete  THEN v_activated:=v_activated||'delete_accounts';      ELSE v_deactivated:=v_deactivated||'delete_accounts';      END IF; END IF;
  IF n_seed    IS DISTINCT FROM COALESCE(v_old.platform_can_edit_seed_data,false)             THEN IF n_seed    THEN v_activated:=v_activated||'edit_seed_data';       ELSE v_deactivated:=v_deactivated||'edit_seed_data';       END IF; END IF;
  IF n_imp     IS DISTINCT FROM COALESCE(v_old.platform_can_impersonate,false)                THEN IF n_imp     THEN v_activated:=v_activated||'impersonate';          ELSE v_deactivated:=v_deactivated||'impersonate';          END IF; END IF;
  IF n_manage  IS DISTINCT FROM COALESCE(v_old.platform_can_manage_admins,false)              THEN IF n_manage  THEN v_activated:=v_activated||'manage_admins';        ELSE v_deactivated:=v_deactivated||'manage_admins';        END IF; END IF;
  IF n_2fa     IS DISTINCT FROM COALESCE(v_old.platform_can_reset_2fa_of_others,false)        THEN IF n_2fa     THEN v_activated:=v_activated||'reset_2fa_of_others'; ELSE v_deactivated:=v_deactivated||'reset_2fa_of_others'; END IF; END IF;
  IF n_notif   IS DISTINCT FROM COALESCE(v_old.platform_can_send_global_notifications,false)  THEN IF n_notif   THEN v_activated:=v_activated||'send_notifications';   ELSE v_deactivated:=v_deactivated||'send_notifications';   END IF; END IF;
  IF n_audit   IS DISTINCT FROM COALESCE(v_old.platform_can_view_audit_log,true)              THEN IF n_audit   THEN v_activated:=v_activated||'view_audit_log';       ELSE v_deactivated:=v_deactivated||'view_audit_log';       END IF; END IF;
  IF n_health  IS DISTINCT FROM COALESCE(v_old.platform_can_view_system_health,true)          THEN IF n_health  THEN v_activated:=v_activated||'view_system_health';   ELSE v_deactivated:=v_deactivated||'view_system_health';   END IF; END IF;

  -- Upsert de los 11 flags (UNIQUE platform_admin_id).
  INSERT INTO platform_admin_permissions (
    platform_admin_id,
    platform_can_create_accounts, platform_can_suspend_accounts, platform_can_archive_accounts,
    platform_can_delete_accounts, platform_can_edit_seed_data, platform_can_impersonate,
    platform_can_manage_admins, platform_can_reset_2fa_of_others, platform_can_send_global_notifications,
    platform_can_view_audit_log, platform_can_view_system_health, updated_by)
  VALUES (
    p_admin_id,
    n_create, n_suspend, n_archive, n_delete, n_seed, n_imp,
    n_manage, n_2fa, n_notif, n_audit, n_health, auth.uid())
  ON CONFLICT (platform_admin_id) DO UPDATE SET
    platform_can_create_accounts            = EXCLUDED.platform_can_create_accounts,
    platform_can_suspend_accounts           = EXCLUDED.platform_can_suspend_accounts,
    platform_can_archive_accounts           = EXCLUDED.platform_can_archive_accounts,
    platform_can_delete_accounts            = EXCLUDED.platform_can_delete_accounts,
    platform_can_edit_seed_data             = EXCLUDED.platform_can_edit_seed_data,
    platform_can_impersonate                = EXCLUDED.platform_can_impersonate,
    platform_can_manage_admins              = EXCLUDED.platform_can_manage_admins,
    platform_can_reset_2fa_of_others        = EXCLUDED.platform_can_reset_2fa_of_others,
    platform_can_send_global_notifications  = EXCLUDED.platform_can_send_global_notifications,
    platform_can_view_audit_log             = EXCLUDED.platform_can_view_audit_log,
    platform_can_view_system_health         = EXCLUDED.platform_can_view_system_health,
    updated_by                              = EXCLUDED.updated_by,
    updated_at                              = now();

  IF array_length(v_activated,1) IS NOT NULL OR array_length(v_deactivated,1) IS NOT NULL THEN
    PERFORM log_platform_event(
      'admin_permissions_changed', NULL, v_user_id,
      jsonb_build_object('admin', v_name,
        'activated', to_jsonb(v_activated),
        'deactivated', to_jsonb(v_deactivated)));
  END IF;
END;
$$;


--
-- Name: set_platform_admin_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_platform_admin_role(p_admin_id uuid, p_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_role text;
  v_name     text;
  v_user_id  uuid;
BEGIN
  PERFORM _require_manage_admins();

  SELECT role, full_name, user_id INTO v_old_role, v_name, v_user_id
  FROM platform_admins WHERE id = p_admin_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Admin no encontrado.';
  END IF;

  IF v_old_role = p_role THEN
    RETURN;  -- sin cambio
  END IF;

  -- protect_last_admin (BEFORE UPDATE) puede abortar si es el último CEO.
  UPDATE platform_admins SET role = p_role WHERE id = p_admin_id;

  PERFORM log_platform_event(
    'admin_role_changed', NULL, v_user_id,
    jsonb_build_object('admin', v_name, 'from', v_old_role, 'to', p_role));
END;
$$;


--
-- Name: set_product_availability(uuid, boolean, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_product_availability(p_menu_item_id uuid, p_is_available boolean, p_location_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'manual'::text, p_available_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid; v_user uuid := auth.uid(); v_core jsonb; v_matriculas text[];
  v_affected_ids uuid[]; v_brands int; v_ext_locs text[]; v_channels int; v_secret text;
begin
  select mi.account_id into v_account_id from menu_item mi where mi.id = p_menu_item_id;
  if v_account_id is null then
    raise exception 'set_product_availability: producto % no encontrado', p_menu_item_id;
  end if;
  if not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(v_account_id)) then
    raise exception 'set_product_availability: sin acceso a la cuenta %', v_account_id;
  end if;

  -- (02/09) ALCANCE POR LOCAL. Hasta hoy el local era un filtro, no una
  -- autorizacion: un admin acotado podia operar sobre cualquier local de
  -- su cuenta. El criterio sale de current_user_location_ids().
  perform public._assert_location_in_scope(p_location_id, 'set_product_availability');

  v_core := public._set_product_availability_core(
    p_menu_item_id, p_is_available, p_location_id, p_reason, p_available_until, p_reason_code,
    v_account_id, v_user, 'oficina', 'web');
  v_matriculas := array(select jsonb_array_elements_text(v_core->'matriculas'));
  v_affected_ids := array(select (jsonb_array_elements_text(v_core->'affected_ids'))::uuid);
  v_brands := coalesce((v_core->>'brands')::int, 0);

  if p_location_id is null then
    select array_agg(distinct elm.external_location_id) into v_ext_locs from external_location_map elm
    where elm.account_id = v_account_id and elm.source = 'lastapp' and elm.is_active;
  else
    select array_agg(distinct elm.external_location_id) into v_ext_locs from external_location_map elm
    where elm.account_id = v_account_id and elm.source = 'lastapp' and elm.is_active
      and elm.location_id = p_location_id;
  end if;

  if v_matriculas is not null and array_length(v_matriculas, 1) > 0 then
    select count(distinct ecp.external_channel) into v_channels from external_catalog_product ecp
    where ecp.account_id = v_account_id and ecp.organization_product_id::text = any(v_matriculas)
      and (v_ext_locs is null or ecp.external_location_id::text = any(v_ext_locs));
    select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'availability_dispatch_secret';
    if v_secret is not null then
      perform net.http_post(
        url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/availability-dispatch',
        headers := jsonb_build_object('Content-Type','application/json','x-availability-dispatch-secret', v_secret),
        body := jsonb_build_object(
          'account_id', v_account_id, 'matriculas', to_jsonb(v_matriculas),
          'affected_menu_item_ids', to_jsonb(coalesce(v_affected_ids, array[]::uuid[])),
          'external_location_ids', to_jsonb(coalesce(v_ext_locs, array[]::text[])),
          'location_id', p_location_id, 'available_until', p_available_until,
          'enable', p_is_available, 'reason', p_reason));
    else
      raise warning 'set_product_availability: secret availability_dispatch_secret ausente en Vault, no se empuja al despachador';
    end if;
  end if;

  return jsonb_build_object('brands', v_brands, 'channels', coalesce(v_channels, 0),
    'matriculas', coalesce(array_length(v_matriculas, 1), 0), 'location_id', p_location_id,
    'external_locations', coalesce(array_length(v_ext_locs, 1), 0));
end;
$$;


--
-- Name: set_product_availability_by_token(text, uuid, boolean, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_product_availability_by_token(p_device_token text, p_menu_item_id uuid, p_is_available boolean, p_reason text DEFAULT 'manual'::text, p_available_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device; v_account_id uuid; v_location_id uuid; v_mi_account uuid;
  v_core jsonb; v_matriculas text[]; v_affected_ids uuid[]; v_brands int;
  v_ext_locs text[]; v_channels int; v_secret text;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'set_product_availability_by_token: token de dispositivo no valido';
  end if;
  v_account_id := v_device.account_id; v_location_id := v_device.location_id;
  

  select mi.account_id into v_mi_account from menu_item mi where mi.id = p_menu_item_id;
  if v_mi_account is null then
    raise exception 'set_product_availability_by_token: producto % no encontrado', p_menu_item_id;
  end if;
  if v_mi_account <> v_account_id then
    raise exception 'set_product_availability_by_token: el producto no pertenece a la cuenta del dispositivo';
  end if;

  v_core := public._set_product_availability_core(
    p_menu_item_id, p_is_available, v_location_id, p_reason, p_available_until, p_reason_code,
    v_account_id, null, 'cocina', 'tablet');
  v_matriculas := array(select jsonb_array_elements_text(v_core->'matriculas'));
  v_affected_ids := array(select (jsonb_array_elements_text(v_core->'affected_ids'))::uuid);
  v_brands := coalesce((v_core->>'brands')::int, 0);

  select array_agg(distinct elm.external_location_id) into v_ext_locs from external_location_map elm
  where elm.account_id = v_account_id and elm.source = 'lastapp' and elm.is_active
    and elm.location_id = v_location_id;

  if v_matriculas is not null and array_length(v_matriculas, 1) > 0 then
    select count(distinct ecp.external_channel) into v_channels from external_catalog_product ecp
    where ecp.account_id = v_account_id and ecp.organization_product_id::text = any(v_matriculas)
      and (v_ext_locs is null or ecp.external_location_id::text = any(v_ext_locs));
    select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'availability_dispatch_secret';
    if v_secret is not null then
      perform net.http_post(
        url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/availability-dispatch',
        headers := jsonb_build_object('Content-Type','application/json','x-availability-dispatch-secret', v_secret),
        body := jsonb_build_object(
          'account_id', v_account_id, 'matriculas', to_jsonb(v_matriculas),
          'affected_menu_item_ids', to_jsonb(coalesce(v_affected_ids, array[]::uuid[])),
          'external_location_ids', to_jsonb(coalesce(v_ext_locs, array[]::text[])),
          'location_id', v_location_id, 'available_until', p_available_until,
          'enable', p_is_available, 'reason', p_reason));
    else
      raise warning 'set_product_availability_by_token: secret availability_dispatch_secret ausente en Vault, no se empuja al despachador';
    end if;
  end if;

  return jsonb_build_object('brands', v_brands, 'channels', coalesce(v_channels, 0),
    'matriculas', coalesce(array_length(v_matriculas, 1), 0), 'location_id', v_location_id,
    'external_locations', coalesce(array_length(v_ext_locs, 1), 0));
end;
$$;


--
-- Name: set_products_availability_bulk(uuid[], boolean, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_products_availability_bulk(p_menu_item_ids uuid[], p_is_available boolean, p_location_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'manual'::text, p_available_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid(); v_account_id uuid; v_n_found int; v_n_mismatch int;
  v_mi uuid; v_core jsonb; v_all_matr text[] := array[]::text[]; v_all_ids uuid[] := array[]::uuid[];
  v_failed jsonb := '[]'::jsonb; v_products_ok int := 0; v_ext_locs text[]; v_channels int; v_secret text;
begin
  if p_menu_item_ids is null or array_length(p_menu_item_ids, 1) is null then
    raise exception 'set_products_availability_bulk: la seleccion esta vacia';
  end if;
  if array_length(p_menu_item_ids, 1) > 50 then
    raise exception 'set_products_availability_bulk: maximo 50 productos por operacion (recibidos %)', array_length(p_menu_item_ids, 1);
  end if;
  if p_reason is null or p_reason not in ('manual','stock_out','schedule') then
    raise exception 'set_products_availability_bulk: reason no valido %', p_reason;
  end if;
  if p_reason_code is not null and p_reason_code not in
     ('sin_stock','incidencia','fin_servicio','promocion','mantenimiento','otro') then
    raise exception 'set_products_availability_bulk: reason_code no valido %', p_reason_code;
  end if;

  select mi.account_id into v_account_id from menu_item mi where mi.id = p_menu_item_ids[1];
  if v_account_id is null then
    raise exception 'set_products_availability_bulk: producto % no encontrado', p_menu_item_ids[1];
  end if;

  select count(*), count(*) filter (where account_id <> v_account_id) into v_n_found, v_n_mismatch
  from menu_item where id = any(p_menu_item_ids);
  if v_n_found <> array_length(p_menu_item_ids, 1) then
    raise exception 'set_products_availability_bulk: algun producto de la seleccion no existe';
  end if;
  if v_n_mismatch > 0 then
    raise exception 'set_products_availability_bulk: todos los productos deben pertenecer a la misma cuenta';
  end if;

  if not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(v_account_id)) then
    raise exception 'set_products_availability_bulk: sin acceso a la cuenta %', v_account_id;
  end if;

  foreach v_mi in array p_menu_item_ids loop
    begin
      v_core := public._set_product_availability_core(
        v_mi, p_is_available, p_location_id, p_reason, p_available_until, p_reason_code,
        v_account_id, v_user, 'oficina', 'web');
      v_all_matr := v_all_matr || array(select jsonb_array_elements_text(v_core->'matriculas'));
      v_all_ids := v_all_ids || array(select (jsonb_array_elements_text(v_core->'affected_ids'))::uuid);
      v_products_ok := v_products_ok + 1;
    exception when others then
      v_failed := v_failed || jsonb_build_object('menu_item_id', v_mi, 'error', sqlerrm);
    end;
  end loop;

  select array_agg(distinct x) into v_all_matr from unnest(v_all_matr) x;
  select array_agg(distinct x) into v_all_ids from unnest(v_all_ids) x;

  if p_location_id is null then
    select array_agg(distinct elm.external_location_id) into v_ext_locs from external_location_map elm
    where elm.account_id = v_account_id and elm.source = 'lastapp' and elm.is_active;
  else
    select array_agg(distinct elm.external_location_id) into v_ext_locs from external_location_map elm
    where elm.account_id = v_account_id and elm.source = 'lastapp' and elm.is_active
      and elm.location_id = p_location_id;
  end if;

  if v_all_matr is not null and array_length(v_all_matr, 1) > 0 then
    select count(distinct ecp.external_channel) into v_channels from external_catalog_product ecp
    where ecp.account_id = v_account_id and ecp.organization_product_id::text = any(v_all_matr)
      and (v_ext_locs is null or ecp.external_location_id::text = any(v_ext_locs));
    select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'availability_dispatch_secret';
    if v_secret is not null then
      perform net.http_post(
        url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/availability-dispatch',
        headers := jsonb_build_object('Content-Type','application/json','x-availability-dispatch-secret', v_secret),
        body := jsonb_build_object(
          'account_id', v_account_id, 'matriculas', to_jsonb(v_all_matr),
          'affected_menu_item_ids', to_jsonb(coalesce(v_all_ids, array[]::uuid[])),
          'external_location_ids', to_jsonb(coalesce(v_ext_locs, array[]::text[])),
          'location_id', p_location_id, 'available_until', p_available_until,
          'enable', p_is_available, 'reason', p_reason));
    else
      raise warning 'set_products_availability_bulk: secret availability_dispatch_secret ausente en Vault, no se empuja al despachador';
    end if;
  end if;

  return jsonb_build_object('products', v_products_ok,
    'brands', coalesce((select count(distinct brand_id) from menu_item
                        where id = any(v_all_ids) and account_id = v_account_id), 0),
    'channels', coalesce(v_channels, 0),
    'matriculas', coalesce(v_all_matr, array[]::text[]), 'failed', v_failed);
end;
$$;


--
-- Name: set_products_availability_bulk_by_token(text, uuid[], boolean, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_products_availability_bulk_by_token(p_device_token text, p_menu_item_ids uuid[], p_is_available boolean, p_reason text DEFAULT 'manual'::text, p_available_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device kds_device; v_account_id uuid; v_location_id uuid; v_n_found int;
  v_mi uuid; v_core jsonb; v_all_matr text[] := array[]::text[]; v_all_ids uuid[] := array[]::uuid[];
  v_failed jsonb := '[]'::jsonb; v_products_ok int := 0; v_ext_locs text[]; v_channels int; v_secret text;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    raise exception 'set_products_availability_bulk_by_token: token de dispositivo no valido';
  end if;
  v_account_id := v_device.account_id; v_location_id := v_device.location_id;

  if p_menu_item_ids is null or array_length(p_menu_item_ids, 1) is null then
    raise exception 'set_products_availability_bulk_by_token: la seleccion esta vacia';
  end if;
  if array_length(p_menu_item_ids, 1) > 50 then
    raise exception 'set_products_availability_bulk_by_token: maximo 50 productos por operacion (recibidos %)', array_length(p_menu_item_ids, 1);
  end if;
  if p_reason is null or p_reason not in ('manual','stock_out','schedule') then
    raise exception 'set_products_availability_bulk_by_token: reason no valido %', p_reason;
  end if;
  if p_reason_code is not null and p_reason_code not in
     ('sin_stock','incidencia','fin_servicio','promocion','mantenimiento','otro') then
    raise exception 'set_products_availability_bulk_by_token: reason_code no valido %', p_reason_code;
  end if;

  select count(*) into v_n_found from menu_item
  where id = any(p_menu_item_ids) and account_id = v_account_id;
  if v_n_found <> array_length(p_menu_item_ids, 1) then
    raise exception 'set_products_availability_bulk_by_token: algun producto de la seleccion no existe en esta cuenta';
  end if;

  

  foreach v_mi in array p_menu_item_ids loop
    begin
      v_core := public._set_product_availability_core(
        v_mi, p_is_available, v_location_id, p_reason, p_available_until, p_reason_code,
        v_account_id, null, 'cocina', 'tablet');
      v_all_matr := v_all_matr || array(select jsonb_array_elements_text(v_core->'matriculas'));
      v_all_ids := v_all_ids || array(select (jsonb_array_elements_text(v_core->'affected_ids'))::uuid);
      v_products_ok := v_products_ok + 1;
    exception when others then
      v_failed := v_failed || jsonb_build_object('menu_item_id', v_mi, 'error', sqlerrm);
    end;
  end loop;

  select array_agg(distinct x) into v_all_matr from unnest(v_all_matr) x;
  select array_agg(distinct x) into v_all_ids from unnest(v_all_ids) x;

  select array_agg(distinct elm.external_location_id) into v_ext_locs from external_location_map elm
  where elm.account_id = v_account_id and elm.source = 'lastapp' and elm.is_active
    and elm.location_id = v_location_id;

  if v_all_matr is not null and array_length(v_all_matr, 1) > 0 then
    select count(distinct ecp.external_channel) into v_channels from external_catalog_product ecp
    where ecp.account_id = v_account_id and ecp.organization_product_id::text = any(v_all_matr)
      and (v_ext_locs is null or ecp.external_location_id::text = any(v_ext_locs));
    select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'availability_dispatch_secret';
    if v_secret is not null then
      perform net.http_post(
        url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/availability-dispatch',
        headers := jsonb_build_object('Content-Type','application/json','x-availability-dispatch-secret', v_secret),
        body := jsonb_build_object(
          'account_id', v_account_id, 'matriculas', to_jsonb(v_all_matr),
          'affected_menu_item_ids', to_jsonb(coalesce(v_all_ids, array[]::uuid[])),
          'external_location_ids', to_jsonb(coalesce(v_ext_locs, array[]::text[])),
          'location_id', v_location_id, 'available_until', p_available_until,
          'enable', p_is_available, 'reason', p_reason));
    else
      raise warning 'set_products_availability_bulk_by_token: secret availability_dispatch_secret ausente en Vault, no se empuja al despachador';
    end if;
  end if;

  return jsonb_build_object('products', v_products_ok,
    'brands', coalesce((select count(distinct brand_id) from menu_item
                        where id = any(v_all_ids) and account_id = v_account_id), 0),
    'channels', coalesce(v_channels, 0),
    'matriculas', coalesce(v_all_matr, array[]::text[]), 'failed', v_failed);
end;
$$;


--
-- Name: set_purchase_order_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_purchase_order_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.code IS NULL THEN
    NEW.code := public.next_purchase_order_code(NEW.account_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_social_post_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_social_post_status(p_post_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_cur text;
begin
  select account_id, status into v_acc, v_cur from social_post where id = p_post_id;
  if v_acc is null then raise exception 'post no encontrado'; end if;
  if not current_user_is_admin_or_manager_of(v_acc) then raise exception 'no autorizado'; end if;
  if p_status not in ('draft','approved','discarded') then raise exception 'estado no permitido: %', p_status; end if;
  if v_cur in ('publishing','published') then raise exception 'no se puede cambiar un post en publicacion'; end if;
  update social_post set status = p_status, updated_at = now() where id = p_post_id;
end $$;


--
-- Name: set_stock_level(uuid, uuid, uuid, numeric, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_stock_level(p_account uuid, p_location uuid, p_recipe_item uuid, p_min numeric DEFAULT NULL::numeric, p_par numeric DEFAULT NULL::numeric, p_user_id uuid DEFAULT NULL::uuid, p_user_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  IF NOT public.belongs_to_account(p_account) THEN
    raise exception 'set_stock_level: sin permiso sobre la cuenta %', p_account;
  end if;
  insert into public.stock_level(
    account_id, location_id, recipe_item_id,
    min_qty, par_qty, updated_at, updated_by, updated_by_name
  ) values (
    p_account, p_location, p_recipe_item,
    p_min, p_par, now(), p_user_id, p_user_name
  )
  on conflict (account_id, location_id, recipe_item_id) do update set
    min_qty = p_min,            -- solo min y par; NO se tocan reorder/lead/safety
    par_qty = p_par,
    updated_at = now(),
    updated_by = p_user_id,
    updated_by_name = p_user_name;
end;
$$;


--
-- Name: set_submodule_price(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_submodule_price(p_submodule_id uuid, p_price_eur numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_code  text;
  v_type  text;
  v_old   numeric;
BEGIN
  IF NOT current_user_is_admin() THEN
    RAISE EXCEPTION 'Acceso denegado: solo platform admins.';
  END IF;
  IF p_price_eur < 0 THEN
    RAISE EXCEPTION 'El precio no puede ser negativo.';
  END IF;

  SELECT code, type, price_eur INTO v_code, v_type, v_old FROM submodules WHERE id = p_submodule_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Submódulo no encontrado.'; END IF;
  IF v_type <> 'addon' THEN
    RAISE EXCEPTION 'Solo los add-ons tienen precio propio (este es un tier del plan).';
  END IF;

  UPDATE submodules SET price_eur = p_price_eur, updated_at = now() WHERE id = p_submodule_id;

  PERFORM log_platform_event(
    'system_config_changed', NULL, NULL,
    jsonb_build_object('config', 'addon_price', 'addon', v_code, 'from', v_old, 'to', p_price_eur));
END;
$$;


--
-- Name: set_supplier_invoice_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_supplier_invoice_code() RETURNS trigger
