  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: shop_brand_menu_by_slug(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_brand_menu_by_slug(p_slug text, p_brand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_brand record;
  v_cats jsonb;
  v_is_open boolean;
  v_location_ids jsonb;
begin
  select id into v_account_id from accounts where slug = p_slug;
  if v_account_id is null then
    return null;
  end if;
  select b.id, b.name, b.logo_url, b.cuisine_code,
         st.accent_color, st.hero_url, st.seed_rating, st.seed_rating_count
    into v_brand
  from brand b
  join shop_theme st on st.brand_id = b.id
  where b.id = p_brand_id
    and b.account_id = v_account_id
    and st.hub_visible = true
    and st.is_published = true;
  if v_brand.id is null then
    return null;
  end if;
  select coalesce(jsonb_agg(distinct bla.location_id), '[]'::jsonb)
    into v_location_ids
  from brand_location_availability bla
  where bla.brand_id = p_brand_id and bla.is_active = true;
  select exists (
    select 1 from brand_location_availability bla
    where bla.brand_id = p_brand_id
      and bla.is_active = true
      and is_brand_open(bla.location_id, p_brand_id)
  ) into v_is_open;
  select coalesce(jsonb_agg(cat order by cat.position nulls last, cat.name), '[]'::jsonb)
  into v_cats
  from (
    select c.id, c.name, c.emoji, c.position,
           coalesce(jsonb_agg(
             jsonb_build_object(
               'id', mi.id,
               'name', mi.name,
               'description', mi.description,
               'photo_url', mi.photo_url,
               'price', mi.price,
               'product_type', mi.product_type,
               'offer', public._shop_item_promo(v_account_id, mi.id, mi.price)
             ) order by mi.position nulls last, mi.name
           ) filter (where mi.id is not null), '[]'::jsonb) as products
    from menu_category c
    join menu_item mi
      on mi.menu_category_id = c.id
     and mi.account_id = v_account_id
     and mi.brand_id = p_brand_id
     and mi.is_active is not false
     and not exists (
       select 1 from product_availability pa
        where pa.account_id = mi.account_id
          and pa.is_available = false
          and (pa.available_until is null or pa.available_until > now())
          and ((mi.external_id is not null and pa.external_id = mi.external_id)
            or (mi.recipe_item_id is not null and pa.recipe_item_id = mi.recipe_item_id))
          and (
            pa.location_id is null
            or not exists (
              select 1
                from brand_location_availability bla2
               where bla2.brand_id = p_brand_id
                 and bla2.is_active = true
                 and not exists (
                   select 1 from product_availability pa2
                    where pa2.account_id = mi.account_id
                      and pa2.is_available = false
                      and (pa2.available_until is null or pa2.available_until > now())
                      and (pa2.location_id = bla2.location_id or pa2.location_id is null)
                      and ((mi.external_id is not null and pa2.external_id = mi.external_id)
                        or (mi.recipe_item_id is not null and pa2.recipe_item_id = mi.recipe_item_id))
                 )
            )
          )
     )
     and mi.archived_at is null
    where c.account_id = v_account_id
      and c.brand_id = p_brand_id
    group by c.id, c.name, c.emoji, c.position
    having count(mi.id) > 0
  ) cat;
  return jsonb_build_object(
    'brand_id', v_brand.id,
    'name', v_brand.name,
    'logo_url', v_brand.logo_url,
    'accent_color', v_brand.accent_color,
    'hero_url', v_brand.hero_url,
    'cuisine_code', v_brand.cuisine_code,
    'rating', v_brand.seed_rating,
    'rating_count', v_brand.seed_rating_count,
    'is_open', v_is_open,
    'location_ids', v_location_ids,
    'free_delivery', public._shop_account_free_delivery(v_account_id),
    -- (+ storefront paso3) Plato de regalo de esta marca, para el banner del menú.
    'gift', public._shop_brand_free_gift(v_account_id, p_brand_id),
    'categories', v_cats
  );
end;
$$;


--
-- Name: shop_check_delivery(text, uuid, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_check_delivery(p_slug text, p_location_id uuid, p_lat double precision, p_lng double precision) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_pt geography;
  v_zone record;
begin
  select id into v_account_id from accounts where slug = p_slug;
  if v_account_id is null then
    return jsonb_build_object('ok', false, 'reason', 'account');
  end if;

  v_pt := st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography;

  -- Zona activa del local que cubre el punto (radio por ahora; menor prioridad gana)
  select dz.id, dz.name, dz.delivery_fee, dz.min_order, dz.eta_min,
         st_distance(v_pt, dz.center) as dist_m, dz.radius_m
    into v_zone
  from delivery_zone dz
  where dz.account_id = v_account_id
    and dz.location_id = p_location_id
    and dz.is_active = true
    and dz.method = 'radius'
    and dz.center is not null
    and st_dwithin(v_pt, dz.center, dz.radius_m)
  order by dz.priority nulls last, st_distance(v_pt, dz.center)
  limit 1;

  if v_zone.id is null then
    return jsonb_build_object('ok', false, 'reason', 'out_of_zone');
  end if;

  return jsonb_build_object(
    'ok', true,
    'zone_id', v_zone.id,
    'zone_name', v_zone.name,
    'delivery_fee', v_zone.delivery_fee,
    'min_order', v_zone.min_order,
    'eta_min', v_zone.eta_min,
    'distance_m', round(v_zone.dist_m)
  );
end;
$$;


--
-- Name: shop_delivery_slots(text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_delivery_slots(p_slug text, p_location_id uuid, p_eta_min integer DEFAULT 40, p_step_min integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_now timestamptz := now();
  v_tz text := 'Europe/Madrid';
  v_start timestamptz;
  v_end_of_day timestamptz;
  v_slot timestamptz;
  v_slots jsonb := '[]'::jsonb;
  v_epoch_step int;
begin
  select id into v_account_id from accounts where slug = p_slug;
  if v_account_id is null then
    return jsonb_build_object('ok', false, 'slots', '[]'::jsonb);
  end if;

  -- Inicio: ahora + eta, redondeado hacia arriba al siguiente múltiplo de step.
  v_start := v_now + (p_eta_min || ' minutes')::interval;
  v_epoch_step := p_step_min * 60;
  v_start := to_timestamp(ceil(extract(epoch from v_start) / v_epoch_step) * v_epoch_step);

  -- Fin del día de hoy en zona local.
  v_end_of_day := (date_trunc('day', v_now at time zone v_tz) + interval '1 day') at time zone v_tz;

  v_slot := v_start;
  while v_slot < v_end_of_day loop
    -- Solo franjas en las que el LOCAL está abierto (horario general, brand_id NULL).
    if is_brand_open(p_location_id, null, v_slot) then
      v_slots := v_slots || jsonb_build_object(
        'ts', v_slot,
        'label', to_char(v_slot at time zone v_tz, 'HH24:MI')
      );
    end if;
    v_slot := v_slot + (p_step_min || ' minutes')::interval;
  end loop;

  return jsonb_build_object('ok', true, 'slots', v_slots);
end;
$$;


--
-- Name: shop_home_overview(uuid, timestamp with time zone, timestamp with time zone, uuid[], uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_home_overview(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_location_ids uuid[], p_brand_ids uuid[], p_kinds text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_to         timestamptz := coalesce(p_to, now());
  v_from       timestamptz := coalesce(p_from, '-infinity'::timestamptz);
  v_has_prev   boolean     := (p_from is not null);
  v_prev_from  timestamptz := case when p_from is not null then p_from - (v_to - p_from) else null end;
  v_span_start timestamptz := coalesce(v_prev_from, v_from);
  v_result     jsonb;
begin
  if not (p_account = any(current_user_account_ids())) then raise exception 'forbidden'; end if;

  with sales as (
    select s.id, s.total,
      case when s.sold_at >= v_from then 'cur' when v_has_prev and s.sold_at >= v_prev_from then 'prev' end as period,
      to_char((s.sold_at at time zone 'Europe/Madrid')::date, 'YYYY-MM-DD') as day
    from sale s
    where s.account_id = p_account and s.source = 'folvy_shop' and coalesce(s.status,'') <> 'cancelled'
      and s.sold_at >= v_span_start and s.sold_at < v_to
      and (p_location_ids is null or s.location_id = any(p_location_ids))
      and (p_brand_ids is null or exists (
        select 1 from sale_line sl join menu_item mi on mi.id = sl.menu_item_id
        where sl.sale_id = s.id and mi.brand_id = any(p_brand_ids)))
  ),
  red as (
    select cr.margin_after, cr.customer_id, sa.period, sa.id as sale_id, sa.total as sale_total, sa.day,
      c.kind, c.id as coupon_id, c.name,
      (c.kind = 'standard' and (c.auto_apply or c.first_order_only)) as is_welcome,
      case when c.kind = 'free_item' then coalesce((
        select round(ri.computed_cost + coalesce(mi.packaging_cost, 0), 2)
        from campaign_scope sc join menu_item mi on mi.id = sc.menu_item_id join recipe_item ri on ri.id = mi.recipe_item_id
        where sc.coupon_id = c.id and sc.menu_item_id is not null and ri.computed_cost is not null limit 1
      ), cr.discount_amount) else cr.discount_amount end as invested
    from coupon_redemption cr
    join sales sa on sa.id = cr.sale_id and sa.period is not null
    join coupon c on c.id = cr.coupon_id and c.account_id = p_account
    where cr.account_id = p_account and (p_kinds is null or c.kind = any(p_kinds))
  ),
  offer_ids as (select distinct sale_id, period from red),
  lines as (
    select sl.line_total, sl.computed_cost, sl.quantity, sl.menu_item_id, mi.brand_id, mi.name as item_name, b.name as brand_name
    from sale_line sl
    join sales sa on sa.id = sl.sale_id and sa.period = 'cur'
    join menu_item mi on mi.id = sl.menu_item_id
    left join brand b on b.id = mi.brand_id
    where coalesce(sl.line_type, 'product') = 'product'
  ),
  series as (
    select sa.day, count(*) as orders,
      round(sum(case when sa.id in (select sale_id from offer_ids where period = 'cur') then sa.total else 0 end), 2) as with_offer,
      round(sum(case when sa.id in (select sale_id from offer_ids where period = 'cur') then 0 else sa.total end), 2) as without_offer
    from sales sa where sa.period = 'cur' group by sa.day order by sa.day
  ),
  bk as (
    select kind, count(*) as redemptions, round(sum(invested), 2) as invested,
      sum(margin_after) filter (where margin_after is not null) as margin_real
    from red where period = 'cur' group by kind
  ),
  bc as (
    select coupon_id, name, kind, count(*) as redemptions, round(sum(invested), 2) as invested,
      sum(margin_after) filter (where margin_after is not null) as margin_real, count(margin_after) as margin_known
    from red where period = 'cur' group by coupon_id, name, kind
  ),
  br as (
    select coalesce(brand_name, '(sin marca)') as name, round(sum(line_total), 2) as ventas,
      round(sum((line_total - computed_cost)) filter (where computed_cost is not null), 2) as margin
    from lines group by brand_name
  ),
  td as (
    select item_name as name, round(sum(quantity), 0) as units
    from lines group by item_name order by sum(quantity) desc limit 8
  )
  select jsonb_build_object(
    'ok', true, 'hasPrev', v_has_prev,
    'ventasCur',  (select coalesce(round(sum(total) filter (where period='cur'),2),0) from sales),
    'ventasPrev', (select coalesce(round(sum(total) filter (where period='prev'),2),0) from sales),
    'pedidosCur',  (select count(*) filter (where period='cur') from sales),
    'pedidosPrev', (select count(*) filter (where period='prev') from sales),
    'ticketCur',  (select round(avg(total) filter (where period='cur'),2) from sales),
    'ticketPrev', (select round(avg(total) filter (where period='prev'),2) from sales),
    'marginCur',  (select round(sum(margin_after) filter (where period='cur' and margin_after is not null),2) from red),
    'marginPrev', (select round(sum(margin_after) filter (where period='prev' and margin_after is not null),2) from red),
    'marginKnownCur', (select count(*) filter (where period='cur' and margin_after is not null) from red),
    'marginRedCur',   (select count(*) filter (where period='cur') from red),
    'newCur',  (select count(distinct customer_id) filter (where period='cur' and is_welcome and customer_id is not null) from red),
    'newPrev', (select count(distinct customer_id) filter (where period='prev' and is_welcome and customer_id is not null) from red),
    'offerOrdersCur',  (select count(*) filter (where period='cur') from offer_ids),
    'offerOrdersPrev', (select count(*) filter (where period='prev') from offer_ids),
    'series', coalesce((select jsonb_agg(jsonb_build_object('day', day, 'withOffer', with_offer, 'withoutOffer', without_offer, 'orders', orders)) from series), '[]'::jsonb),
    'byKind', coalesce((select jsonb_agg(jsonb_build_object('kind', kind, 'redemptions', redemptions, 'invested', invested, 'marginReal', round(margin_real,2)) order by invested desc nulls last) from bk), '[]'::jsonb),
    'topCampaigns', coalesce((select jsonb_agg(t) from (
        select jsonb_build_object('id', coupon_id, 'name', name, 'kind', kind, 'redemptions', redemptions, 'invested', invested,
          'roi', case when margin_known > 0 and invested > 0 then round(margin_real/invested, 2) else null end) as t
        from bc order by (case when margin_known > 0 and invested > 0 then margin_real/invested else null end) desc nulls last, redemptions desc limit 5) x), '[]'::jsonb),
    'brands', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'ventas', ventas, 'margin', margin) order by ventas desc) from br), '[]'::jsonb),
    'topDishes', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'units', units)) from td), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


--
-- Name: shop_hub_by_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_hub_by_slug(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_name text;
  v_hero text;
  v_tagline text;
  v_subtitle text;
  v_logo text;
  v_brands jsonb;
  v_top jsonb;
begin
  select id, name, shop_hero_url, shop_tagline, shop_subtitle, shop_logo_url
    into v_account_id, v_name, v_hero, v_tagline, v_subtitle, v_logo
  from accounts where slug = p_slug;
  if v_account_id is null then
    return null;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'brand_id', b.id,
           'name', b.name,
           'logo_url', b.logo_url,
           'hero_url', st.hero_url,
           'accent_color', st.accent_color,
           'template', st.template,
           'position', st.hub_position,
           'rating', st.seed_rating,
           'rating_count', st.seed_rating_count,
           'cuisine_code', sc.code,
           'cuisine_label', sc.label,
           'cuisine_emoji', sc.emoji,
           'offer', public._shop_brand_best_offer(v_account_id, b.id),
           -- (+ storefront paso3) Plato de regalo por marca, para el badge del hub.
           'gift', public._shop_brand_free_gift(v_account_id, b.id),
           'is_open', exists (
             select 1
             from brand_location_availability bla
             where bla.brand_id = b.id
               and bla.is_active = true
               and is_brand_open(bla.location_id, b.id)
           )
         ) order by st.hub_position nulls last, b.name), '[]'::jsonb)
  into v_brands
  from brand b
  join shop_theme st on st.brand_id = b.id
  left join shop_cuisine sc on sc.code = b.cuisine_code
  where b.account_id = v_account_id
    and st.hub_visible = true
    and st.is_published = true;
  select coalesce(jsonb_agg(t order by t.units desc), '[]'::jsonb)
  into v_top
  from (
    select mi.id          as menu_item_id,
           mi.name        as name,
           mi.photo_url   as photo_url,
           mi.price       as price,
           b.id           as brand_id,
           b.name         as brand_name,
           sum(coalesce(sl.quantity, 1)) as units
    from sale_line sl
    join sale s        on s.id = sl.sale_id
    join menu_item mi  on mi.id = sl.menu_item_id
    join brand b       on b.id = mi.brand_id
    join shop_theme st on st.brand_id = b.id
                      and st.is_published = true
                      and st.hub_visible = true
    where mi.account_id = v_account_id
      and sl.menu_item_id is not null
      and public.menu_item_vendible_en_alguna_parte(mi.id)
      and mi.product_type <> 'combo'
      and s.sold_at >= now() - interval '30 days'
    group by mi.id, mi.name, mi.photo_url, mi.price, b.id, b.name
    order by units desc
    limit 8
  ) t;
  return jsonb_build_object(
    'account_name', v_name,
    'account_logo_url', v_logo,
    'slug', p_slug,
    'hero_url', v_hero,
    'tagline', v_tagline,
    'subtitle', v_subtitle,
    'free_delivery', public._shop_account_free_delivery(v_account_id),
    'free_gift', public._shop_account_free_gift(v_account_id),
    'brands', v_brands,
    'top_dishes', v_top
  );
end;
$$;


--
-- Name: shop_item_config(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_item_config(p_slug text, p_menu_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_item record;
  v_slots jsonb;
begin
  select id into v_account_id from accounts where slug = p_slug;
  if v_account_id is null then return null; end if;

  select mi.id, mi.name, mi.description, mi.photo_url, mi.price, mi.product_type, mi.recipe_item_id, mi.brand_id
    into v_item
  from menu_item mi
  join shop_theme st on st.brand_id = mi.brand_id and st.is_published and st.hub_visible
  where mi.id = p_menu_item_id and mi.account_id = v_account_id
    and mi.is_active is not false and public.menu_item_vendible_en_alguna_parte(mi.id) and mi.archived_at is null;
  if v_item.id is null then return null; end if;

  -- Slots del combo (cada opción = un menu_item con price_impact, sus alérgenos y SUS modgroups anidados)
  if v_item.product_type = 'combo' then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', cs.id,
             'name', cs.name,
             'min', cs.min_selections,
             'max', cs.max_selections,
             'options', (
               select coalesce(jsonb_agg(jsonb_build_object(
                        'menu_item_id', omi.id,
                        'name', omi.name,
                        'photo_url', omi.photo_url,
                        'price_impact', cso.price_impact,
                        'is_default', cso.is_default,
                        'allergens', _allergens_of_recipe(omi.recipe_item_id),
                        'modifier_groups', _modgroups_of_item(omi.id)
                      ) order by cso.position nulls last, omi.name), '[]'::jsonb)
               from combo_slot_option cso
               join menu_item omi on omi.id = cso.menu_item_id
               where cso.combo_slot_id = cs.id and cso.is_active and omi.is_active is not false
             )
           ) order by cs.position nulls last), '[]'::jsonb)
    into v_slots
    from combo_slot cs
    where cs.combo_item_id = v_item.id and cs.is_active;
  else
    v_slots := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'id', v_item.id,
    'name', v_item.name,
    'description', v_item.description,
    'photo_url', v_item.photo_url,
    'price', v_item.price,
    'product_type', v_item.product_type,
    'allergens', _allergens_of_recipe(v_item.recipe_item_id),
    'modifier_groups', _modgroups_of_item(v_item.id),
    'slots', v_slots
  );
end;
$$;


--
-- Name: shop_locations_by_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_locations_by_slug(p_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object('id', l.id, 'name', l.name, 'address', l.address)
      order by l.name
    ),
    '[]'::jsonb
  )
  from locations l
  join accounts a on a.id = l.account_id
  where a.slug = p_slug
    and l.active = true;
$$;


--
-- Name: shop_order_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_order_status(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s          sale%rowtype;
  v_bname    text;
  v_logo     text;
  v_accent   text;
  v_addr     text;
  v_locname  text;
  v_lines    jsonb;
begin
  select * into s
  from sale
  where public_token = nullif(btrim(coalesce(p_token,'')), '')
    and source = 'folvy_shop'
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  -- Marca: nombre + logo (si el pedido es de una sola marca).
  if s.brand_id is not null then
    select b.name, b.logo_url into v_bname, v_logo from brand b where b.id = s.brand_id;
    select st.accent_color into v_accent from shop_theme st where st.brand_id = s.brand_id limit 1;
  end if;
  -- Color: si no hay tema de marca, cae al tema del hub (account, brand_id NULL).
  if v_accent is null then
    select st.accent_color into v_accent
    from shop_theme st
    where st.account_id = s.account_id and st.brand_id is null
    limit 1;
  end if;

  -- Dirección a mostrar según el modo.
  if s.service_type = 'pickup' then
    select l.name, l.address into v_locname, v_addr from locations l where l.id = s.location_id;
  else
    v_addr := s.delivery_address;
  end if;

  -- Líneas de producto (sin modificadores ni componentes de combo).
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'name', sl.product_name,
             'quantity', sl.quantity,
             'lineTotal', coalesce(sl.line_total, sl.unit_price * sl.quantity)
           ) order by sl.id
         ), '[]'::jsonb)
  into v_lines
  from sale_line sl
  where sl.sale_id = s.id
    and coalesce(sl.line_type, 'product') = 'product'
    and sl.parent_sale_line_id is null;

  return jsonb_build_object(
    'ok',            true,
    'code',          s.platform_order_code,
    'orderStatus',   s.order_status,
    'paymentStatus', s.payment_status,
    'payMethod',     s.payment_method,
    'mode',          case when s.service_type = 'pickup' then 'pickup' else 'delivery' end,
    'total',         s.total,
    'deliveryFee',   s.delivery_cost,
    'paidAt',        s.paid_at,
    'deliveryState', s.delivery_state,
    'etaAt',         coalesce(s.eta_delivery, s.eta_pickup),
    'riderName',     s.rider_name,
    'brand',         jsonb_build_object('name', v_bname, 'logoUrl', v_logo, 'accentColor', v_accent),
    'address',       v_addr,
    'locationName',  v_locname,
    'lines',         v_lines
  );
end;
$$;


--
-- Name: shop_payment_config(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shop_payment_config(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb;
begin
  select jsonb_build_object(
           'ok', true,
           'online',        coalesce(a.shop_pay_online, true),
           'cashPickup',    coalesce(a.shop_pay_cash_pickup, false),
           'cashDelivery',  coalesce(a.shop_pay_cash_delivery, false)
         )
  into v
  from accounts a
  where a.slug = p_slug;

  if v is null then
    return jsonb_build_object('ok', false, 'reason', 'account');
  end if;
  return v;
end;
$$;


--
-- Name: sign_course_attempt(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_course_attempt(p_attempt_id uuid, p_signature_path text, p_signer_name text, p_signer_doc_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_employee_id uuid;
  v_account_id uuid;
  v_attempt public.course_attempt%rowtype;
  v_course_id uuid;
  v_course_version int;
  v_signature_id uuid;
  v_signed_at timestamptz;
  v_headers json;
  v_ip text;
  v_ua text;
begin
  if v_uid is null then
    raise exception 'Sin sesión de empleado válida: no se puede firmar sin auth.uid()';
  end if;

  select * into v_employee_id, v_account_id from public.current_employee_and_account();
  if v_employee_id is null then
    raise exception 'Sin sesión de empleado válida';
  end if;

  select * into v_attempt from public.course_attempt where id = p_attempt_id;
  if not found then
    raise exception 'Intento no encontrado';
  end if;
  if v_attempt.employee_id <> v_employee_id then
    raise exception 'Este intento no pertenece al empleado autenticado';
  end if;
  if coalesce(v_attempt.passed, false) is not true then
    raise exception 'Solo se puede firmar un intento superado';
  end if;

  select ca.course_id into v_course_id from public.course_assignment ca where ca.id = v_attempt.assignment_id;
  select version into v_course_version from public.course where id = v_course_id;

  -- IP/UA reales desde las cabeceras de la request (best-effort -- si el
  -- contexto de la llamada no las trae, se queda NULL, no rompe la firma).
  begin
    v_headers := nullif(current_setting('request.headers', true), '')::json;
    v_ua := v_headers ->> 'user-agent';
    v_ip := nullif(btrim(split_part(coalesce(v_headers ->> 'x-forwarded-for', ''), ',', 1)), '');
  exception when others then
    v_ip := null;
    v_ua := null;
  end;

  insert into public.course_signature (
    attempt_id, employee_id, signature_png, signer_name, signer_doc_id,
    auth_method, auth_uid, course_version, content_snapshot, ip, user_agent
  ) values (
    p_attempt_id, v_employee_id, p_signature_path, p_signer_name, p_signer_doc_id,
    'employee_session', v_uid, v_course_version, public.build_course_content_snapshot(v_course_id), v_ip, v_ua
  )
  returning id, signed_at into v_signature_id, v_signed_at;

  begin
    perform public.check_phase_completion_for_assignment(v_attempt.assignment_id);
  exception when others then
    raise warning 'sign_course_attempt: check_phase_completion_for_assignment falló para asignación %: %', v_attempt.assignment_id, sqlerrm;
  end;

  return jsonb_build_object('signatureId', v_signature_id, 'signedAt', v_signed_at);
end;
$$;


--
-- Name: social_estado_de_la_cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_estado_de_la_cuenta(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v jsonb;
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account)) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'red',            sa.network,
           'enlazada',       (sa.link_status = 'linked'),
           'enlazada_el',    sa.config->>'linked_at',
           -- Nunca la llave. Solo su NOMBRE en el Vault, que no es un secreto
           -- y es lo que hace falta para ir a renovarla.
           --
           -- Y tampoco el `ig_user_id` (14/09): no lo pinta nadie, y mandarlo
           -- al navegador para tirarlo desmentía el comentario del fichero de
           -- la ficha, que decia que los identificadores no salen.
           'llave_nombre',   sa.config->>'token_vault_name',
           'llave_ok_at',    sa.llave_ok_at,
           'llave_fallo_at', sa.llave_fallo_at,
           'llave_fallo_clase', sa.llave_fallo_clase,
           'llave_caduca_el',   sa.llave_caduca_el,
           -- Se cuentan aqui para que la pantalla no tenga que restar fechas:
           -- una cuenta hecha en dos sitios se despega en uno de los dos.
           'dias_para_caducar', case when sa.llave_caduca_el is null then null
                                     else (sa.llave_caduca_el::date - current_date) end,
           -- Lo ultimo que se publico de verdad. Es la otra mitad de la prueba:
           -- una llave «sin fallos» que no ha publicado nunca no dice nada.
           'ultima_publicacion', (
             select max(sp.published_at) from social_post sp
              where sp.account_id = p_account and sp.social_account_id = sa.id
                and sp.status = 'published')
         ) order by sa.network), '[]'::jsonb)
    into v
    from social_account sa
   where sa.account_id = p_account;

  return jsonb_build_object('cuentas', v);
end;
$$;


--
-- Name: social_llave_renovada(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_llave_renovada(p_nombre text, p_llave text, p_segundos integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_temp'
    AS $$
declare
  v_id       uuid;
  v_leida    text;
  v_caduca   timestamptz;
  v_filas_se int := 0;
  v_filas_sa int := 0;
begin
  if p_llave is null or length(p_llave) = 0 then
    raise exception 'no se guarda una llave vacia' using errcode = '22023';
  end if;

  select s.id into v_id from vault.secrets s where s.name = p_nombre;
  if v_id is null then
    raise exception 'no hay ningun secreto llamado % en el Vault', p_nombre using errcode = '42704';
  end if;

  -- 1 · se escribe
  perform vault.update_secret(v_id, new_secret := p_llave);

  -- 2 · y se COMPRUEBA leyendola de vuelta. Sin esto, «guardada» es una
  --     suposicion, que es justo lo que no puede ser aqui.
  select d.decrypted_secret into v_leida from vault.decrypted_secrets d where d.id = v_id;
  if v_leida is distinct from p_llave then
    raise exception 'la llave se escribio pero no se lee igual: el Vault no la ha guardado'
      using errcode = '25000';
  end if;

  -- 3 y 4 · las fechas, solo si Meta dijo cuanto dura. Si no vino un numero,
  --         no se inventa: se deja la fecha vieja y se dice que no se movio.
  if p_segundos is not null and p_segundos > 0 then
    v_caduca := now() + make_interval(secs => p_segundos);

    update public.secret_expiry se
       set caduca_el = (v_caduca at time zone 'Europe/Madrid')::date,
           actualizado_at = now()
     where se.nombre = p_nombre;
    get diagnostics v_filas_se = row_count;

    update public.social_account sa
       set llave_caduca_el = v_caduca,
           llave_ok_at     = now(),
           updated_at      = now()
     where sa.config->>'token_vault_name' = p_nombre;
    get diagnostics v_filas_sa = row_count;
  end if;

  return jsonb_build_object(
    'guardada',           true,
    'comprobada',         true,
    'caduca_actualizada', (p_segundos is not null and p_segundos > 0),
    'caduca_el',          v_caduca,
    'segundos',           p_segundos,
    'filas_secret_expiry',  v_filas_se,
    'filas_social_account', v_filas_sa);
end;
$$;


--
-- Name: social_secret_read(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_secret_read(p_name text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v text;
begin
  select decrypted_secret into v
    from vault.decrypted_secrets
   where name = p_name;
  return v;
end $$;


--
-- Name: start_course_attempt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_course_attempt(p_assignment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_account_id uuid;
  v_assignment public.course_assignment%rowtype;
  v_emp_position text;
  v_emp_location_id uuid;
  v_course public.course%rowtype;
  v_attempt_id uuid;
  v_sections jsonb;
  v_questions jsonb;
begin
  select * into v_employee_id, v_account_id from public.current_employee_and_account();
  if v_employee_id is null then
    raise exception 'Sin sesión de empleado válida';
  end if;

  select e.position, e.location_id into v_emp_position, v_emp_location_id
  from public.employees e where e.id = v_employee_id;

  select ca.* into v_assignment
  from public.course_assignment ca
  where ca.id = p_assignment_id
    and ca.account_id = v_account_id
    and (
      ca.employee_id = v_employee_id
      or (ca.role is not null and ca.role = v_emp_position)
      or (ca.location_id is not null and ca.location_id = v_emp_location_id)
    );
  if not found then
    raise exception 'Asignación no encontrada o no pertenece a este empleado';
  end if;

  select c.* into v_course from public.course c where c.id = v_assignment.course_id;
  if not found then
    raise exception 'Curso no encontrado';
  end if;

  -- Reutiliza un intento en curso (no finalizado) en vez de duplicar por cada
  -- refresco de pantalla.
  select a.id into v_attempt_id
  from public.course_attempt a
  where a.assignment_id = p_assignment_id and a.employee_id = v_employee_id and a.finished_at is null
  order by a.started_at desc
  limit 1;

  if v_attempt_id is null then
    insert into public.course_attempt (assignment_id, employee_id, answers)
    values (p_assignment_id, v_employee_id, '{}'::jsonb)
    returning id into v_attempt_id;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', s.id, 'ord', s.ord, 'title', s.title, 'body', s.body, 'mediaUrl', s.media_url
  ) order by s.ord), '[]'::jsonb) into v_sections
  from public.course_section s where s.course_id = v_course.id;

  -- ⚠️ Deliberadamente SIN is_correct ni explanation: la solución no sale del
  -- servidor hasta submit_course_attempt.
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', q.id, 'ord', q.ord, 'text', q.text,
    'options', (
      select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'text', o.text) order by o.id), '[]'::jsonb)
      from public.course_option o where o.question_id = q.id
    )
  ) order by q.ord), '[]'::jsonb) into v_questions
  from public.course_question q where q.course_id = v_course.id;

  return jsonb_build_object(
    'attemptId', v_attempt_id,
    'course', jsonb_build_object(
      'id', v_course.id, 'code', v_course.code, 'title', v_course.title,
      'summary', v_course.summary, 'legalBasis', v_course.legal_basis,
      'deliveryMode', v_course.delivery_mode, 'estimatedMinutes', v_course.estimated_minutes,
      'passThresholdPct', v_course.pass_threshold_pct, 'version', v_course.version,
      'requiresPractical', v_course.requires_practical
    ),
    'sections', v_sections,
    'questions', v_questions
  );
end;
$$;


--
-- Name: station_update_window(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.station_update_window(p_device_token text, p_quiet_minutes integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device  kds_device;
  v_calma   jsonb;
  v_ventana jsonb;
  v_reasons jsonb;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then
    return jsonb_build_object('ok', false, 'safe', false, 'en_ventana', false,
                              'reasons', to_jsonb(array['token_no_valido']));
  end if;

  v_calma   := public._cocina_en_calma(v_device.location_id, p_quiet_minutes);
  v_ventana := public._ventana_de_mantenimiento(v_device.location_id);

  -- `reasons` junta los motivos de las dos llaves, pero `safe` sigue saliendo
  -- SOLO de la actividad. Si `safe` se calculara de «no hay motivos», meter el
  -- horario aquí le cambiaría el significado por la puerta de atrás y dejaría
  -- de ser la segunda llave: serían las dos mezcladas en una.
  v_reasons := v_calma->'reasons';
  if (v_ventana->>'en_ventana')::boolean is not true then
    v_reasons := v_reasons || to_jsonb(array[coalesce(v_ventana->>'motivo', 'fuera_de_ventana')]);
  end if;

  return jsonb_build_object(
    'ok',                 true,
    'safe',               (v_calma->>'safe')::boolean,
    'reasons',            v_reasons,
    'pending_jobs',       (v_calma->>'pending_jobs')::int,
    'active_orders',      (v_calma->>'active_orders')::int,
    'minutes_since_sale', (v_calma->>'minutes_since_sale')::int,
    'quiet_minutes',      (v_calma->>'quiet_minutes')::int,
    'en_ventana',         (v_ventana->>'en_ventana')::boolean,
    'motivo_ventana',     v_ventana->>'motivo',
    'ventana_hasta',      v_ventana->>'hasta',
    'margen_minutos',     (v_ventana->>'margen_minutos')::int
  );
end;
$$;


--
-- Name: FUNCTION station_update_window(p_device_token text, p_quiet_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.station_update_window(p_device_token text, p_quiet_minutes integer) IS 'Las dos llaves de la actualización de una estación: en_ventana (fuera del horario del local, 45 min de margen) y safe (la cocina en calma). Las dos tienen que abrir.';


--
-- Name: stock_levels_overview(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_levels_overview(p_account uuid, p_location uuid, p_only_with_level boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
with base as (
  select ri.id as recipe_item_id, ri.name as item_name, ri.family_id,
         rf.name as family_name, ku.abbreviation as unit_abbr,
         coalesce(rls.qty_on_hand, 0) as qty_on_hand,
         coalesce(rls.avg_unit_cost, ri.computed_cost, 0) as unit_cost,
         sl.min_qty, sl.par_qty, sl.reorder_point, sl.lead_time_days, sl.safety_qty,
         (sl.id is not null) as has_level
  from recipe_item ri
  left join recipe_family rf on rf.id = ri.family_id
  left join kitchen_unit ku on ku.id = ri.base_unit_id
  left join recipe_item_location_stock rls
         on rls.recipe_item_id = ri.id and rls.location_id = p_location and rls.account_id = p_account
  left join stock_level sl
         on sl.recipe_item_id = ri.id and sl.location_id = p_location and sl.account_id = p_account
  where ri.account_id = p_account
    and ri.type IN ('raw', 'packaging')
    and coalesce(ri.is_active, true) = true
)
select jsonb_build_object(
  'items', coalesce((
    select jsonb_agg(jsonb_build_object(
      'recipe_item_id', b.recipe_item_id,
      'item_name', b.item_name,
      'family_id', b.family_id,
      'family_name', b.family_name,
      'unit_abbr', b.unit_abbr,
      'qty_on_hand', b.qty_on_hand,
      'unit_cost', b.unit_cost,
      'min_qty', b.min_qty,
      'par_qty', b.par_qty,
      'reorder_point', b.reorder_point,
      'lead_time_days', b.lead_time_days,
      'safety_qty', b.safety_qty,
      'has_level', b.has_level,
      'below_min', (b.min_qty is not null and b.qty_on_hand < b.min_qty),
      'to_par_qty', (case when b.par_qty is not null and b.par_qty > b.qty_on_hand then b.par_qty - b.qty_on_hand else 0 end)
    ) order by
      (case when b.min_qty is not null and b.qty_on_hand < b.min_qty then 0 else 1 end),
      b.item_name)
    from base b
    where (not p_only_with_level or b.has_level)
  ), '[]'::jsonb)
);
$$;


--
-- Name: storage_coverage(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_coverage(p_account uuid, p_location uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
with universe as (
  select ri.id,
         ri.name,
         coalesce(ril.stock_value, 0) as value_eur,
         coalesce(ril.qty_on_hand, 0) as qty,
         ku.abbreviation as unit_abbr,
         bf.name as bf_name,
         bf.qty_in_base as bf_qib,
         bf.is_piece as bf_piece
  from recipe_item ri
  left join recipe_item_location_stock ril
    on ril.recipe_item_id = ri.id
   and ril.location_id = p_location
   and ril.account_id = p_account
  left join kitchen_unit ku on ku.id = ri.base_unit_id
  left join lateral (
    select pf.name, pf.qty_in_base, pf.is_piece
    from recipe_item_purchase_format pf
    where pf.item_id = ri.id
      and pf.account_id = p_account
      and pf.parent_format_id is null
      and pf.is_active = true
      and pf.archived_at is null
    order by pf.qty_in_base desc
    limit 1
  ) bf on true
  where ri.account_id = p_account
    and ri.type IN ('raw', 'packaging')
    and ri.is_active = true
),
primary_area as (
  select distinct on (rsa.recipe_item_id)
         rsa.recipe_item_id,
         sa.id as area_id
  from recipe_item_storage_area rsa
  join storage_area sa on sa.id = rsa.storage_area_id
  where rsa.account_id = p_account
    and sa.location_id = p_location
    and sa.active = true
  order by rsa.recipe_item_id, rsa.position asc, sa.position asc
),
item_area as (
  select u.id, u.name, u.value_eur, u.qty, u.unit_abbr,
         u.bf_name, u.bf_qib, u.bf_piece, pa.area_id
  from universe u
  left join primary_area pa on pa.recipe_item_id = u.id
),
zone_rows as (
  select sa.id, sa.name, sa.parent_id, sa.position,
         count(ia.id) as item_count,
         coalesce(sum(ia.value_eur), 0) as value_eur,
         coalesce((
           select jsonb_agg(jsonb_build_object(
                    'recipe_item_id', t.id, 'name', t.name,
                    'value_eur', t.value_eur, 'qty', t.qty, 'unit_abbr', t.unit_abbr,
                    'buy_format_name', t.bf_name,
                    'buy_format_qty_in_base', t.bf_qib,
                    'buy_format_is_piece', t.bf_piece))
           from (
             select ia2.id, ia2.name, ia2.value_eur, ia2.qty, ia2.unit_abbr,
                    ia2.bf_name, ia2.bf_qib, ia2.bf_piece
             from item_area ia2
             where ia2.area_id = sa.id
             order by ia2.value_eur desc nulls last, ia2.name asc
             limit 5
           ) t
         ), '[]'::jsonb) as top_items
  from storage_area sa
  left join item_area ia on ia.area_id = sa.id
  where sa.account_id = p_account
    and sa.location_id = p_location
    and sa.active = true
  group by sa.id, sa.name, sa.parent_id, sa.position
)
select jsonb_build_object(
  'kpis', jsonb_build_object(
    'raw_active',   (select count(*) from universe),
    'placed',       (select count(*) from item_area where area_id is not null),
    'orphans',      (select count(*) from item_area where area_id is null),
    'total_value',  (select coalesce(sum(value_eur), 0) from universe),
    'orphan_value', (select coalesce(sum(value_eur), 0) from item_area where area_id is null)
  ),
  'zones', coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', id, 'name', name, 'parent_id', parent_id, 'position', position,
             'item_count', item_count, 'value_eur', value_eur, 'top_items', top_items
           ) order by position asc, name asc)
    from zone_rows
  ), '[]'::jsonb)
);
$$;


--
-- Name: storage_orphans(uuid, uuid, text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_orphans(p_account uuid, p_location uuid, p_search text DEFAULT NULL::text, p_family uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
with placed as (
  select distinct rsa.recipe_item_id
  from recipe_item_storage_area rsa
  join storage_area sa on sa.id = rsa.storage_area_id
  where rsa.account_id = p_account
    and sa.location_id = p_location
    and sa.active = true
),
orphans as (
  select ri.id, ri.name, ri.family_id, rf.name as family_name,
         coalesce(ril.stock_value, 0) as value_eur,
         coalesce(ril.qty_on_hand, 0) as qty,
         ku.abbreviation as unit_abbr,
         bf.name as bf_name, bf.qty_in_base as bf_qib, bf.is_piece as bf_piece
  from recipe_item ri
  left join recipe_item_location_stock ril
    on ril.recipe_item_id = ri.id
   and ril.location_id = p_location
   and ril.account_id = p_account
  left join recipe_family rf on rf.id = ri.family_id
  left join kitchen_unit ku on ku.id = ri.base_unit_id
  left join lateral (
    select pf.name, pf.qty_in_base, pf.is_piece
    from recipe_item_purchase_format pf
    where pf.item_id = ri.id
      and pf.account_id = p_account
      and pf.parent_format_id is null
      and pf.is_active = true
      and pf.archived_at is null
    order by pf.qty_in_base desc
    limit 1
  ) bf on true
  where ri.account_id = p_account
    and ri.type IN ('raw', 'packaging')
    and ri.is_active = true
    and ri.id not in (select recipe_item_id from placed)
    and (p_search is null or ri.name ilike '%' || p_search || '%')
    and (p_family is null or ri.family_id = p_family)
)
select jsonb_build_object(
  'total', (select count(*) from orphans),
  'items', coalesce((
    select jsonb_agg(jsonb_build_object(
             'recipe_item_id', o.id, 'name', o.name,
             'family_id', o.family_id, 'family_name', o.family_name,
             'value_eur', o.value_eur, 'qty', o.qty, 'unit_abbr', o.unit_abbr,
             'buy_format_name', o.bf_name,
             'buy_format_qty_in_base', o.bf_qib,
             'buy_format_is_piece', o.bf_piece))
    from (
      select * from orphans
      order by value_eur desc nulls last, name asc
      limit greatest(p_limit, 0) offset greatest(p_offset, 0)
    ) o
  ), '[]'::jsonb)
);
$$;


--
-- Name: storage_zone_items(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_zone_items(p_account uuid, p_area uuid, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
with items as (
  select ri.id, ri.name,
         coalesce(ril.stock_value, 0) as value_eur,
         coalesce(ril.qty_on_hand, 0) as qty,
         ku.abbreviation as unit_abbr,
         rsa.position,
         bf.name as bf_name, bf.qty_in_base as bf_qib, bf.is_piece as bf_piece
  from recipe_item_storage_area rsa
  join storage_area sa on sa.id = rsa.storage_area_id
  join recipe_item ri on ri.id = rsa.recipe_item_id and ri.is_active = true
  left join recipe_item_location_stock ril
    on ril.recipe_item_id = ri.id
   and ril.location_id = sa.location_id
   and ril.account_id = p_account
  left join kitchen_unit ku on ku.id = ri.base_unit_id
  left join lateral (
    select pf.name, pf.qty_in_base, pf.is_piece
    from recipe_item_purchase_format pf
    where pf.item_id = ri.id
      and pf.account_id = p_account
      and pf.parent_format_id is null
      and pf.is_active = true
      and pf.archived_at is null
    order by pf.qty_in_base desc
    limit 1
  ) bf on true
  where rsa.account_id = p_account
    and rsa.storage_area_id = p_area
    and (p_search is null or ri.name ilike '%' || p_search || '%')
)
select jsonb_build_object(
  'total', (select count(*) from items),
  'items', coalesce((
    select jsonb_agg(jsonb_build_object(
             'recipe_item_id', x.id, 'name', x.name,
             'value_eur', x.value_eur, 'qty', x.qty, 'unit_abbr', x.unit_abbr,
             'is_primary', (x.position = 0),
             'buy_format_name', x.bf_name,
             'buy_format_qty_in_base', x.bf_qib,
             'buy_format_is_piece', x.bf_piece))
    from (
      select * from items
      order by value_eur desc nulls last, name asc
      limit greatest(p_limit, 0) offset greatest(p_offset, 0)
    ) x
  ), '[]'::jsonb)
);
$$;


--
-- Name: submit_course_attempt(uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_course_attempt(p_attempt_id uuid, p_answers jsonb, p_time_spent_seconds integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_id uuid;
  v_account_id uuid;
  v_attempt public.course_attempt%rowtype;
  v_course_id uuid;
  v_threshold int;
  v_total int;
  v_correct int;
  v_score numeric;
  v_passed boolean;
  v_results jsonb;
begin
  select * into v_employee_id, v_account_id from public.current_employee_and_account();
  if v_employee_id is null then
    raise exception 'Sin sesión de empleado válida';
  end if;

  select * into v_attempt from public.course_attempt where id = p_attempt_id;
  if not found then
    raise exception 'Intento no encontrado';
  end if;
  if v_attempt.employee_id <> v_employee_id then
    raise exception 'Este intento no pertenece al empleado autenticado';
  end if;
  if v_attempt.finished_at is not null then
    raise exception 'Este intento ya se corrigió';
  end if;

  select ca.course_id into v_course_id from public.course_assignment ca where ca.id = v_attempt.assignment_id;
  select pass_threshold_pct into v_threshold from public.course where id = v_course_id;

  -- Nota: el join de la opción DADA exige go.question_id = q.id (no solo
  -- go.id = <valor>) — si no, un cliente podría enviar el id de una opción
  -- correcta de OTRA pregunta y colarla como respuesta válida de esta. La
  -- opción correcta (co) se resuelve con LATERAL + LIMIT 1: defensa ante
  -- datos mal cargados con más de un is_correct=true por pregunta (el editor
  -- de oficina debería impedirlo, pero la nota no puede depender de eso).
  select
    count(*),
    count(*) filter (where coalesce(go.is_correct, false)),
    jsonb_agg(jsonb_build_object(
      'questionId', q.id,
      'givenOptionId', go.id,
      'isCorrect', coalesce(go.is_correct, false),
      'explanation', go.explanation,
      'correctOptionId', co.id,
      'correctText', co.text
    ) order by q.ord)
  into v_total, v_correct, v_results
  from public.course_question q
  left join public.course_option go
    on go.question_id = q.id and go.id = nullif(p_answers ->> q.id::text, '')::uuid
  left join lateral (
    select o.id, o.text from public.course_option o
    where o.question_id = q.id and o.is_correct = true
    order by o.id limit 1
  ) co on true
  where q.course_id = v_course_id;

  v_score := round((coalesce(v_correct, 0)::numeric / greatest(coalesce(v_total, 0), 1)) * 100, 2);
  v_passed := v_score >= v_threshold;

  update public.course_attempt
  set finished_at = now(),
      score_pct = v_score,
      passed = v_passed,
      answers = p_answers,
      time_spent_seconds = coalesce(p_time_spent_seconds, time_spent_seconds)
  where id = p_attempt_id;

  return jsonb_build_object(
    'scorePct', v_score, 'passed', v_passed,
    'total', v_total, 'correct', v_correct,
    'passThresholdPct', v_threshold,
    'results', v_results
  );
end;
$$;


--
-- Name: substitute_ingredient_in_recipes(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.substitute_ingredient_in_recipes(p_source uuid, p_target uuid, p_parents uuid[]) RETURNS TABLE(replaced integer, merged integer, flagged integer, skipped_cycle integer, affected_item_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acc uuid; v_replaced int:=0; v_merged int:=0; v_flagged int:=0; v_skipped int:=0;
  v_affected uuid[]:='{}'; r RECORD; v_tline uuid;
BEGIN
  SELECT account_id INTO v_acc FROM recipe_item WHERE id = p_source;
  IF v_acc IS NULL OR NOT (v_acc = ANY (current_user_account_ids())) THEN
    RAISE EXCEPTION 'substitute_ingredient_in_recipes: origen no accesible';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM recipe_item WHERE id = p_target AND account_id = v_acc) THEN
    RAISE EXCEPTION 'substitute_ingredient_in_recipes: destino no existe en la misma cuenta';
  END IF;
  IF p_parents IS NULL OR array_length(p_parents, 1) IS NULL THEN
    RETURN QUERY SELECT 0,0,0,0,'{}'::uuid[]; RETURN;
  END IF;

  FOR r IN
    WITH RECURSIVE desc_target AS (
      SELECT p_target AS item_id
      UNION
      SELECT rl.child_item_id FROM recipe_line rl
      JOIN desc_target d ON rl.parent_item_id = d.item_id
    )
    SELECT rl.id, rl.parent_item_id, rl.unit_id, rl.cut_type_id,
           rl.quantity_gross, rl.quantity_net,
           (rl.parent_item_id IN (SELECT item_id FROM desc_target)) AS is_cycle
    FROM recipe_line rl
    WHERE rl.child_item_id = p_source AND rl.account_id = v_acc
      AND rl.parent_item_id = ANY (p_parents)
  LOOP
    IF r.is_cycle THEN v_skipped := v_skipped + 1; CONTINUE; END IF;

    SELECT t.id INTO v_tline FROM recipe_line t
    WHERE t.parent_item_id = r.parent_item_id AND t.child_item_id = p_target
      AND t.unit_id = r.unit_id AND t.cut_type_id IS NOT DISTINCT FROM r.cut_type_id
    ORDER BY t.id LIMIT 1;

    IF v_tline IS NOT NULL THEN
      UPDATE recipe_line tgt
        SET quantity_net = tgt.quantity_net + r.quantity_net,
            quantity_gross = CASE WHEN tgt.quantity_gross IS NULL OR r.quantity_gross IS NULL
                                  THEN NULL ELSE tgt.quantity_gross + r.quantity_gross END,
            updated_at = now()
        WHERE tgt.id = v_tline;
      DELETE FROM recipe_line WHERE id = r.id;
      v_merged := v_merged + 1;
    ELSIF EXISTS (SELECT 1 FROM recipe_line t
            WHERE t.parent_item_id = r.parent_item_id AND t.child_item_id = p_target) THEN
      UPDATE recipe_line SET child_item_id = p_target, updated_at = now() WHERE id = r.id;
      v_flagged := v_flagged + 1;
    ELSE
      UPDATE recipe_line SET child_item_id = p_target, updated_at = now() WHERE id = r.id;
      v_replaced := v_replaced + 1;
    END IF;

    IF NOT (r.parent_item_id = ANY (v_affected)) THEN
      v_affected := array_append(v_affected, r.parent_item_id);
    END IF;
    v_tline := NULL;
  END LOOP;

  RETURN QUERY SELECT v_replaced, v_merged, v_flagged, v_skipped, v_affected;
END;
$$;


--
-- Name: suggest_modifier_product_bundles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggest_modifier_product_bundles(p_account_id uuid) RETURNS TABLE(modifier_option_id uuid, option_name text, brand_name text, target_recipe_item_id uuid, target_menu_item_id uuid, target_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'suggest_modifier_product_bundles: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with opcion_marca as (
    -- Una opcion puede colgar de varias marcas; se propone por cada una y luego
    -- se exige unicidad global de la opcion.
    select distinct mo.id as opt_id, mo.name as opt_name,
           public.sales_product_norm(mo.name) as norm,
           mi.brand_id
    from modifier_option mo
    join modifier_group mg on mg.id = mo.modifier_group_id
    join modifier_group_assignment mga on mga.modifier_group_id = mg.id
    join menu_item mi on mi.id = mga.menu_item_id and mi.archived_at is null
    where mo.account_id = p_account_id
      and mo.is_active is not false
      and coalesce(btrim(mo.name),'') <> ''
      -- solo las que aun no tienen impacto definido
      and not exists (select 1 from modifier_recipe_impact mri
                       where mri.modifier_option_id = mo.id)
  ),
  candidatos as (
    select om.opt_id, om.opt_name, b.name as marca,
           mi.recipe_item_id, mi.id as menu_item_id, mi.name as destino,
           count(*) over (partition by om.opt_id) as n_global
    from opcion_marca om
    join menu_item mi on mi.account_id = p_account_id
      and mi.archived_at is null
      and mi.brand_id = om.brand_id
      and mi.recipe_item_id is not null
      and public.sales_product_norm(mi.name) = om.norm
    left join brand b on b.id = om.brand_id
  )
  select c.opt_id, c.opt_name, c.marca, c.recipe_item_id, c.menu_item_id, c.destino
    from candidatos c
   where c.n_global = 1
   order by c.opt_name;
end;
$$;


--
-- Name: suggest_purchase_qty(uuid, uuid, uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggest_purchase_qty(p_account uuid, p_supplier uuid, p_location uuid, p_horizon_days integer DEFAULT 7, p_hist_days integer DEFAULT 60, p_consumo_days integer DEFAULT 30) RETURNS TABLE(recipe_item_id uuid, suggested_qty numeric, source text, confidence text, format_qty_base numeric, needed_base numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with cat as (
    select distinct a.recipe_item_id
    from article_supplier a
    where a.account_id = p_account
      and a.supplier_id = p_supplier
      and a.is_active = true
  ),
  fmt as (
    select distinct on (a.recipe_item_id)
      a.recipe_item_id as item_id,
      coalesce(nullif(f.qty_in_base, 0), 1)::numeric as qty_base
    from article_supplier a
    left join recipe_item_purchase_format f
      on f.id = a.purchase_format_id and f.account_id = p_account
    where a.account_id = p_account
      and a.supplier_id = p_supplier
      and a.is_active = true
    order by a.recipe_item_id, a.is_preferred desc, a.updated_at desc
  ),
  stock as (
    select s.recipe_item_id, coalesce(s.qty_on_hand, 0)::numeric as on_hand
    from recipe_item_location_stock s
    where s.account_id = p_account and s.location_id = p_location
  ),
  par as (
    select l.recipe_item_id, l.par_qty::numeric as par_qty
    from stock_level l
    where l.account_id = p_account and l.location_id = p_location
      and l.par_qty is not null and l.par_qty > 0
  ),
  consumo as (
    select m.recipe_item_id,
           sum(abs(m.qty_base)) / nullif(p_consumo_days, 0)::numeric as diario_base
    from stock_movement m
    where m.account_id = p_account
      and m.location_id = p_location
      and m.movement_type = 'consumo'
      and m.occurred_at >= now() - make_interval(days => p_consumo_days)
    group by m.recipe_item_id
    having sum(abs(m.qty_base)) > 0
  ),
  hist as (
    select pol.recipe_item_id,
           sum(pol.qty_ordered)::numeric
             / nullif(p_hist_days, 0)::numeric * 7 as semanal_fmt
    from purchase_order_line pol
    join purchase_order po on po.id = pol.purchase_order_id
    where pol.account_id = p_account
      and po.location_id = p_location
      and po.status not in ('cancelado', 'borrador')
      and po.order_date >= (now() - make_interval(days => p_hist_days))::date
      and pol.recipe_item_id is not null
    group by pol.recipe_item_id
    having sum(pol.qty_ordered) > 0
  )
  select
    c.recipe_item_id,
    case
      when p.par_qty is not null then
        greatest(0, ceil( greatest(p.par_qty - coalesce(st.on_hand,0), 0) / f.qty_base ))
      when co.diario_base is not null then
        greatest(0, ceil( greatest(co.diario_base * p_horizon_days - coalesce(st.on_hand,0), 0) / f.qty_base ))
      when h.semanal_fmt is not null then
        greatest(0, ceil( greatest(
          h.semanal_fmt * (p_horizon_days::numeric / 7) - coalesce(st.on_hand,0) / f.qty_base
        , 0) ))
      else null
    end as suggested_qty,
    case
      when p.par_qty  is not null then 'par'
      when co.diario_base is not null then 'consumo'
      when h.semanal_fmt is not null then 'historico'
      else 'none'
    end as source,
    case
      when p.par_qty is not null then 'alta'
      when co.diario_base is not null then 'alta'
      when h.semanal_fmt is not null then 'media'
      else null
    end as confidence,
    f.qty_base as format_qty_base,
    case
      when p.par_qty is not null then greatest(p.par_qty - coalesce(st.on_hand,0), 0)
      when co.diario_base is not null then greatest(co.diario_base * p_horizon_days - coalesce(st.on_hand,0), 0)
      else null
    end as needed_base
  from cat c
  left join fmt f  on f.item_id = c.recipe_item_id
  left join stock st on st.recipe_item_id = c.recipe_item_id
  left join par p  on p.recipe_item_id = c.recipe_item_id
  left join consumo co on co.recipe_item_id = c.recipe_item_id
  left join hist h on h.recipe_item_id = c.recipe_item_id;
$$;


--
-- Name: supplier_contact_misma_cuenta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_contact_misma_cuenta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from supplier s where s.id = new.supplier_id and s.account_id = new.account_id) then
    raise exception 'El contacto y su proveedor tienen que ser de la misma cuenta.';
  end if;
  return new;
end $$;


--
-- Name: supplier_format_prices(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_format_prices(p_account_id uuid, p_supplier_id uuid) RETURNS TABLE(format_id uuid, eur_per_base numeric)
    LANGUAGE sql STABLE
    AS $$
  -- (1) formatos con precio propio de este proveedor: €/base = last_price directo.
  SELECT pf.id AS format_id,
         as2.last_price AS eur_per_base
  FROM article_supplier as2
  JOIN recipe_item_purchase_format pf ON pf.id = as2.purchase_format_id
  WHERE as2.account_id = p_account_id
    AND as2.supplier_id = p_supplier_id
    AND as2.is_active
    AND as2.last_price IS NOT NULL
  UNION ALL
  -- (2) sub-envases SIN precio propio que heredan el del padre con precio de este
  -- proveedor. Mismo ingrediente → mismo €/base → last_price directo (sin escalar).
  SELECT sub.id AS format_id,
         as2.last_price AS eur_per_base
  FROM recipe_item_purchase_format caja
  JOIN article_supplier as2
    ON as2.purchase_format_id = caja.id
   AND as2.account_id  = p_account_id
   AND as2.supplier_id = p_supplier_id
   AND as2.is_active
   AND as2.last_price IS NOT NULL
  JOIN recipe_item_purchase_format sub
    ON sub.id = caja.parent_format_id
  WHERE caja.account_id = p_account_id
    AND sub.id NOT IN (
      -- no pisar sub-envases que YA tienen precio propio (los da la rama 1)
      SELECT a3.purchase_format_id FROM article_supplier a3
      WHERE a3.account_id = p_account_id AND a3.supplier_id = p_supplier_id
        AND a3.is_active AND a3.purchase_format_id IS NOT NULL
    );
$$;


--
-- Name: supplier_invoice_aprobacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_aprobacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_rol text;
begin
  if new.status <> 'aprobada' or (tg_op = 'UPDATE' and old.status = 'aprobada') then
    return new;
  end if;
  if auth.uid() is null then return new; end if;   -- sin usuario: migración o proceso del servidor
  select r.required_role into v_rol from invoice_approval_rule r
   where r.account_id = new.account_id and r.active
     and (r.min_amount is null or coalesce(new.grand_total, 0) >= r.min_amount)
     and (r.max_amount is null or coalesce(new.grand_total, 0) <= r.max_amount)
     and (r.supplier_id is null or r.supplier_id = new.supplier_id)
     and (r.location_id is null or r.location_id = new.location_id)
   order by r.priority asc limit 1;
  v_rol := coalesce(v_rol, 'manager');
  if v_rol = 'admin' and not public.current_user_is_admin_of(new.account_id) then
    raise exception 'Esta factura la tiene que aprobar un administrador.' using errcode = '42501';
  elsif v_rol <> 'admin' and not public.current_user_is_admin_or_manager_of(new.account_id) then
    raise exception 'No puedes aprobar facturas: hace falta un encargado o un administrador.' using errcode = '42501';
  end if;
  new.approved_at := coalesce(new.approved_at, now());
  new.approved_by := coalesce(new.approved_by, auth.uid());
  new.approved_by_name := coalesce(new.approved_by_name, public.conta_nombre_actor());
  return new;
end $$;


--
-- Name: supplier_invoice_iban_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_iban_decide(p_invoice_id uuid, p_decision text, p_quien_nombre text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_inv public.supplier_invoice%rowtype;
begin
  if p_decision is null or p_decision not in ('es_el_nuevo', 'no_es_suyo') then
    raise exception 'Esa decisión no existe.' using errcode = '22023';
  end if;
  select * into v_inv from public.supplier_invoice where id = p_invoice_id for update;
  if not found then raise exception 'Esa factura no existe o no es de tu cuenta.' using errcode = 'P0002'; end if;
  if v_inv.read_iban is null then raise exception 'Esa factura no trae IBAN.' using errcode = '22023'; end if;
  if v_inv.supplier_id is null then raise exception 'Esa factura no tiene proveedor.' using errcode = '22023'; end if;

  if p_decision = 'es_el_nuevo' then
    update public.supplier
       set iban_previous = iban,
           iban = v_inv.read_iban,
           iban_verified_at = now(),
           iban_changed_at = now(),
           iban_changed_by = auth.uid(),
           iban_changed_by_name = p_quien_nombre,
           updated_at = now()
     where id = v_inv.supplier_id;
    if not found then
      raise exception 'Solo un administrador o encargado puede cambiar el IBAN de la ficha.' using errcode = '42501';
    end if;
  end if;

  update public.supplier_invoice
     set iban_decision = p_decision, iban_decision_at = now(),
         iban_decision_by = auth.uid(), iban_decision_by_name = p_quien_nombre
   where id = p_invoice_id;
end $$;


--
-- Name: FUNCTION supplier_invoice_iban_decide(p_invoice_id uuid, p_decision text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.supplier_invoice_iban_decide(p_invoice_id uuid, p_decision text, p_quien_nombre text) IS 'C01b · Una persona decide sobre el IBAN distinto de una factura: es_el_nuevo (a la ficha, con quién y cuándo) o no_es_suyo.';


--
-- Name: supplier_invoice_iban_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_iban_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_ficha text;
begin
  if new.status = 'pagada' and old.status is distinct from 'pagada'
     and new.read_iban is not null and new.iban_decision is null then
    select upper(regexp_replace(s.iban, '\s', '', 'g')) into v_ficha
      from public.supplier s where s.id = new.supplier_id;
    if v_ficha is not null and v_ficha <> upper(regexp_replace(new.read_iban, '\s', '', 'g')) then
      raise exception 'IBAN distinto al de la ficha: decide si es el nuevo IBAN o no es suyo antes de marcarla como pagada.'
        using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION supplier_invoice_iban_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.supplier_invoice_iban_guard() IS 'C01b · Rechaza pagar una factura con IBAN distinto al de la ficha y sin decidir. Misma regla que src/modules/conta/lib/ibanFactura.ts.';


--
-- Name: supplier_invoice_not_duplicate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_not_duplicate(p_invoice_id uuid, p_quien_nombre text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update public.supplier_invoice
     set not_duplicate_confirmed_at = now(), not_duplicate_confirmed_by = auth.uid(), not_duplicate_confirmed_by_name = p_quien_nombre
   where id = p_invoice_id;
  if not found then raise exception 'Esa factura no existe o no es de tu cuenta.' using errcode = 'P0002'; end if;
end $$;


--
-- Name: FUNCTION supplier_invoice_not_duplicate(p_invoice_id uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.supplier_invoice_not_duplicate(p_invoice_id uuid, p_quien_nombre text) IS 'C01b · Una persona dice que esta factura NO es repetida: queda apuntado quién y cuándo, y no se vuelve a marcar.';


--
-- Name: supplier_invoice_repetida(uuid, uuid, text, text, date, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_repetida(p_account uuid, p_supplier uuid, p_nif text, p_numero text, p_fecha date, p_total numeric, p_excluir uuid DEFAULT NULL::uuid) RETURNS TABLE(nivel text, invoice_id uuid, invoice_number text, invoice_date date, grand_total numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_clave text := public.conta_clave_numero(p_numero);
  v_nif text := nullif(regexp_replace(upper(regexp_replace(coalesce(p_nif, ''), '[^A-Za-z0-9]', '', 'g')), '^ES(?=[A-Z0-9]{9}$)', ''), '');
begin
  if not (public.belongs_to_account(p_account) or coalesce(auth.role(), '') = 'service_role') then
    raise exception 'Esa cuenta no es tuya.' using errcode = '42501';
  end if;
  return query
  with vivas as (
    select i.* from public.supplier_invoice i
      left join public.supplier s on s.id = i.supplier_id and s.account_id = i.account_id
     where i.account_id = p_account and i.status <> 'anulada' and i.not_duplicate_confirmed_at is null
       and (p_excluir is null or i.id <> p_excluir)
       and ((p_supplier is not null and i.supplier_id = p_supplier)
            or (v_nif is not null and regexp_replace(upper(regexp_replace(coalesce(s.tax_id, ''), '[^A-Za-z0-9]', '', 'g')), '^ES(?=[A-Z0-9]{9}$)', '') = v_nif))
  ), repetida as (
    select v.* from vivas v
     where v_clave is not null and public.conta_clave_numero(v.invoice_number) = v_clave
       and p_total is not null and round(v.grand_total * 100) = round(p_total * 100)
     order by v.created_at limit 1
  )
  (select 'repetida'::text, r.id, r.invoice_number, r.invoice_date, r.grand_total from repetida r)
  union all
  -- Con el mismo número y total habría salido arriba: aquí el número es otro,
  -- o no lo trae ninguna. Un total 0 no dice nada de la factura.
  (select 'posible'::text, v.id, v.invoice_number, v.invoice_date, v.grand_total from vivas v
    where p_fecha is not null and p_total is not null and round(p_total * 100) <> 0
      and v.invoice_date = p_fecha and round(v.grand_total * 100) = round(p_total * 100)
      and not exists (select 1 from repetida)
    order by v.created_at limit 1);
end $_$;


--
-- Name: FUNCTION supplier_invoice_repetida(p_account uuid, p_supplier uuid, p_nif text, p_numero text, p_fecha date, p_total numeric, p_excluir uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.supplier_invoice_repetida(p_account uuid, p_supplier uuid, p_nif text, p_numero text, p_fecha date, p_total numeric, p_excluir uuid) IS 'D01 · La regla única de repetidas, la del C01b: repetida = mismo proveedor (o su NIF), misma clave de número y mismo total (bloquea); posible = misma fecha y mismo total (no 0) con otro número o sin número ninguna (pregunta). El mismo número con otro total no es nada. Para Compras, Supply, la ficha y la bandeja.';


--
-- Name: supplier_invoice_repetidas_que_hay(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_repetidas_que_hay(p_account uuid) RETURNS TABLE(supplier_id uuid, number_key text, facturas integer, ids uuid[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select i.supplier_id, public.conta_clave_numero(i.invoice_number), count(*)::int, array_agg(i.id order by i.created_at)
    from public.supplier_invoice i
   where i.account_id = p_account and (public.belongs_to_account(p_account) or coalesce(auth.role(), '') = 'service_role')
     and public.conta_clave_numero(i.invoice_number) is not null and i.supplier_id is not null and i.grand_total is not null
     and i.status <> 'anulada' and i.not_duplicate_confirmed_at is null
   group by i.supplier_id, public.conta_clave_numero(i.invoice_number), round(i.grand_total * 100) having count(*) > 1
$$;


--
-- Name: supplier_learning_fix(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_learning_fix(p_supplier_id uuid, p_campo text, p_valor text, p_etiqueta text, p_quien_nombre text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
begin
  select account_id into v_account from public.supplier where id = p_supplier_id;
  if v_account is null then raise exception 'Ese proveedor no existe o no es de tu cuenta.' using errcode = 'P0002'; end if;
  if p_valor is null then
    delete from public.supplier_learning where supplier_id = p_supplier_id and campo = p_campo and a_mano;
    insert into public.supplier_learning_log (account_id, supplier_id, campo, que, porque, hecho_por, hecho_por_nombre)
    values (v_account, p_supplier_id, p_campo, 'devuelto_a_folvy', 'Vuelve a aprenderlo de sus facturas.', auth.uid(), p_quien_nombre);
    return;
  end if;
  insert into public.supplier_learning (account_id, supplier_id, campo, valor, etiqueta, porque, a_mano, fijado_por, fijado_por_nombre)
  values (v_account, p_supplier_id, p_campo, p_valor, p_etiqueta,
          coalesce('Lo fijó ' || nullif(btrim(p_quien_nombre), '') || ' a mano', 'Lo fijaste tú a mano'), true, auth.uid(), p_quien_nombre)
  on conflict (supplier_id, campo) do update
    set valor = excluded.valor, etiqueta = excluded.etiqueta, porque = excluded.porque, a_mano = true,
        fijado_por = excluded.fijado_por, fijado_por_nombre = excluded.fijado_por_nombre, updated_at = now();
  insert into public.supplier_learning_log (account_id, supplier_id, campo, que, valor, etiqueta, porque, hecho_por, hecho_por_nombre)
  values (v_account, p_supplier_id, p_campo, 'fijado_a_mano', p_valor, p_etiqueta, 'Cambiado a mano con «Cambiar».', auth.uid(), p_quien_nombre);
end $$;


--
-- Name: FUNCTION supplier_learning_fix(p_supplier_id uuid, p_campo text, p_valor text, p_etiqueta text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.supplier_learning_fix(p_supplier_id uuid, p_campo text, p_valor text, p_etiqueta text, p_quien_nombre text) IS 'C01b · «Cambiar» de lo aprendido: fija un valor a mano (gana a lo aprendido) o, con p_valor nulo, lo devuelve a Folvy. Deja rastro en supplier_learning_log.';


--
-- Name: supplier_learning_sync(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_learning_sync(p_supplier_id uuid, p_items jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_account uuid;
  v_item jsonb;
  v_prev public.supplier_learning;
  v_n integer := 0;
  v_olvidados integer := 0;
  v_campos text[] := '{}';
begin
  select account_id into v_account from public.supplier where id = p_supplier_id;
  if v_account is null then raise exception 'Ese proveedor no existe o no es de tu cuenta.' using errcode = 'P0002'; end if;
  if jsonb_typeof(p_items) is distinct from 'array' then raise exception 'p_items tiene que ser una lista.'; end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_campos := v_campos || (v_item->>'campo');
    select * into v_prev from public.supplier_learning where supplier_id = p_supplier_id and campo = v_item->>'campo';
    if found and v_prev.a_mano then
      continue;
    end if;
    if not found or v_prev.valor is distinct from v_item->>'valor' then
      insert into public.supplier_learning_log (account_id, supplier_id, campo, que, valor, etiqueta, porque)
      values (v_account, p_supplier_id, v_item->>'campo', 'aprendido', v_item->>'valor', v_item->>'etiqueta', v_item->>'porque');
      v_n := v_n + 1;
    end if;
    insert into public.supplier_learning (account_id, supplier_id, campo, valor, etiqueta, porque, veces, desde, hasta)
    values (v_account, p_supplier_id, v_item->>'campo', v_item->>'valor', v_item->>'etiqueta', v_item->>'porque',
            coalesce((v_item->>'veces')::int, 0), (v_item->>'desde')::timestamptz, (v_item->>'hasta')::timestamptz)
    on conflict (supplier_id, campo) do update
      set valor = excluded.valor, etiqueta = excluded.etiqueta, porque = excluded.porque, veces = excluded.veces,
          desde = excluded.desde, hasta = excluded.hasta, updated_at = now(),
          aprendido_at = case when supplier_learning.valor is distinct from excluded.valor then now() else supplier_learning.aprendido_at end;
  end loop;

  -- Lo aprendido que ya no sale (la persona cambió la última vez): se olvida.
  with fuera as (
    delete from public.supplier_learning
     where supplier_id = p_supplier_id and not a_mano and not (campo = any (v_campos))
    returning campo, valor, etiqueta
  )
  insert into public.supplier_learning_log (account_id, supplier_id, campo, que, valor, etiqueta, porque)
  select v_account, p_supplier_id, campo, 'olvidado', valor, etiqueta,
         'Las últimas facturas ya no dicen lo mismo: dejo de proponerlo hasta que se repita tres veces.'
    from fuera;
  get diagnostics v_olvidados = row_count;
  return v_n + v_olvidados;
end $$;


--
-- Name: FUNCTION supplier_learning_sync(p_supplier_id uuid, p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.supplier_learning_sync(p_supplier_id uuid, p_items jsonb) IS 'C01b · Guarda lo aprendido de un proveedor (lo decide el núcleo) y apunta en supplier_learning_log lo nuevo y lo olvidado. No toca lo fijado a mano.';


--
-- Name: supplier_merge_do(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_merge_do(p_queda uuid, p_se_va uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from supplier where id = p_queda;
  if v_cuenta is null then raise exception 'Ese proveedor no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'No puedes unir fichas de proveedor de esta cuenta.' using errcode = '42501';
  end if;
  return public._supplier_merge(p_queda, p_se_va, p_quien_nombre);
end $$;


--
-- Name: supplier_merge_undo(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_merge_undo(p_merge uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cuenta uuid;
begin
  select account_id into v_cuenta from supplier_merge where id = p_merge;
  if v_cuenta is null then raise exception 'Esa fusión no existe.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_cuenta) then
    raise exception 'No puedes deshacer fusiones de esta cuenta.' using errcode = '42501';
  end if;
  return public._supplier_merge_undo(p_merge, p_quien_nombre);
end $$;


--
-- Name: supplier_tax_rates_ok(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_tax_rates_ok() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_malos int;
begin
  if new.usual_tax_rate_ids is null or cardinality(new.usual_tax_rate_ids) = 0 then
    return new;
  end if;
  select count(*) into v_malos
    from unnest(new.usual_tax_rate_ids) as x(id)
   where not exists (
     select 1 from public.tax_rate t
      where t.id = x.id and (t.is_system or t.account_id = new.account_id));
  if v_malos > 0 then
    raise exception 'Este IVA no existe en tus tablas: elige uno de la lista.' using errcode = '23503';
  end if;
  return new;
end;
$$;


--
-- Name: swap_mirror(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.swap_mirror(p_account uuid, p_item uuid, p_use_mirror boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_src    menu_item%rowtype;
  v_mirror uuid;
begin
  if not (p_account = any(current_user_account_ids())) then raise exception 'forbidden'; end if;

  select * into v_src from menu_item where id = p_item and account_id = p_account;
  if v_src.id is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;

  select id into v_mirror from menu_item
  where mirror_of_item_id = p_item and account_id = p_account limit 1;
  if v_mirror is null then return jsonb_build_object('ok', false, 'reason', 'no_mirror'); end if;

  if coalesce(p_use_mirror, false) then
    update menu_item set is_available = false, updated_at = now() where id = p_item;
    update menu_item set is_available = true,  updated_at = now() where id = v_mirror;
  else
    update menu_item set is_available = true,  updated_at = now() where id = p_item;
    update menu_item set is_available = false, updated_at = now() where id = v_mirror;
  end if;

  return jsonb_build_object('ok', true, 'usingMirror', coalesce(p_use_mirror, false));
end;
$$;


--
-- Name: sync_phase_assignments(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_phase_assignments(p_employee_id uuid, p_path_id uuid, p_phase text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_progress record;
  v_item record;
  v_count integer := 0;
  v_max_due timestamptz;
  v_caller_employee_id uuid;
begin
  select l.account_id into v_account_id
  from public.employees e
  join public.locations l on l.id = e.location_id
  where e.id = p_employee_id;
  if v_account_id is null then
    return 0;
  end if;

  if auth.uid() is not null then
    select employee_id into v_caller_employee_id from public.current_employee_and_account();
    if not (
      coalesce(v_caller_employee_id = p_employee_id, false)
      or public.current_user_is_admin_or_manager_of(v_account_id)
      or public.current_user_is_admin()
    ) then
      raise exception 'sync_phase_assignments: sin acceso';
    end if;
  end if;

  select * into v_progress
  from public.training_path_progress pp
  where pp.employee_id = p_employee_id and pp.path_id = p_path_id and pp.phase = p_phase;
  if v_progress.id is null or v_progress.state = 'pendiente' then
    return 0;
  end if;

  for v_item in
    select pi.id as item_id, pi.course_id, pi.days_from_hire as days_from_release
    from public.training_path_item pi
    where pi.path_id = p_path_id and pi.phase = p_phase
      and not exists (
        select 1 from public.course_assignment ca2
        where ca2.employee_id = p_employee_id and ca2.course_id = pi.course_id
      )
  loop
    insert into public.course_assignment (account_id, course_id, employee_id, origin, due_at, path_item_id)
    values (
      v_account_id, v_item.course_id, p_employee_id, 'onboarding',
      case when v_progress.released_at is null then null else v_progress.released_at + (v_item.days_from_release || ' days')::interval end,
      v_item.item_id
    );
    v_count := v_count + 1;
  end loop;

  update public.course_assignment ca
  set due_at = v_progress.released_at + (pi2.days_from_hire || ' days')::interval
  from public.training_path_item pi2
  where ca.employee_id = p_employee_id
    and ca.path_item_id = pi2.id
    and pi2.path_id = p_path_id
    and pi2.phase = p_phase
    and ca.due_at is null
    and v_progress.released_at is not null;

  select max(ca3.due_at) into v_max_due
  from public.course_assignment ca3
  where ca3.employee_id = p_employee_id
    and ca3.path_item_id in (select pi4.id from public.training_path_item pi4 where pi4.path_id = p_path_id and pi4.phase = p_phase);

  update public.training_path_progress
  set due_at = v_max_due, updated_at = now()
  where id = v_progress.id;

  return v_count;
end;
$$;


--
-- Name: system_alert_queue_drain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_alert_queue_drain() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row         record;
  v_status_code int;
  v_error_msg   text;
  v_secret      text;
  v_new_request bigint;
  v_to_fire     int;
  v_degraded_n  int;
begin
  -- 3.1) Resolver peticiones en vuelo. FOR UPDATE SKIP LOCKED: si dos
  -- ejecuciones se solapan, la segunda salta las filas en curso.
  for v_row in
    select * from public.system_alert_queue
    where status = 'pending' and request_id is not null
    order by id
    for update skip locked
  loop
    select status_code, error_msg into v_status_code, v_error_msg
    from net._http_response where id = v_row.request_id;

    if found then
      if v_status_code = 200 then
        update public.system_alert_queue
          set status = 'sent', sent_at = now(), request_id = null
          where id = v_row.id;
        -- El antiruido se consume AQUI, con la entrega confirmada.
        if v_row.debounce_kind is not null then
          insert into public.db_health_alert_log (kind, detail)
            values (v_row.debounce_kind, 'entregado por la cola, intento ' || v_row.attempts);
        end if;
      else
        update public.system_alert_queue set
          status     = case when v_row.attempts >= 3 then 'failed' else 'pending' end,
          request_id = null,
          last_error = coalesce('http ' || v_status_code, v_error_msg, 'fallo desconocido')
        where id = v_row.id;
      end if;
    elsif v_row.last_attempt_at < now() - interval '2 minutes' then
      -- pg_net no ha respondido tras 2min. Mismo case: si era el 3er intento,
      -- 'failed' — sin esto se quedaria en limbo permanente.
      update public.system_alert_queue set
        status     = case when v_row.attempts >= 3 then 'failed' else 'pending' end,
        request_id = null,
        last_error = 'sin respuesta de pg_net tras 2min'
      where id = v_row.id;
    end if;
  end loop;

  -- 3.2) Disparar
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cron_secret';
  select count(*) into v_to_fire
  from public.system_alert_queue
  where status = 'pending' and request_id is null and attempts < 3;

  if v_secret is null then
    if v_to_fire > 0 then
      raise warning 'system_alert_queue_drain: secret cron_secret ausente en Vault, % aviso(s) sin poder dispararse', v_to_fire;
    end if;
  else
    for v_row in
      select * from public.system_alert_queue
      where status = 'pending' and request_id is null and attempts < 3
      order by id
      for update skip locked
    loop
      select net.http_post(
        url     := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/system-alert',
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secret),
        body    := jsonb_build_object(
        'subject', v_row.subject, 'message', v_row.message, 'kind', v_row.kind,
        'severity', v_row.severity, 'alerta_id', v_row.id, 'creado_at', v_row.created_at,
        'negocio', (select a.name from public.accounts a where a.id = v_row.account_id),
        -- «Foodint Alcalá» dentro de la cuenta «Foodint» se manda como «Alcalá»,
        -- para que el asunto no diga «[Foodint · Foodint Alcalá]».
        'local', (select case when l.name like a2.name || ' %'
                              then substr(l.name, length(a2.name) + 2)
                              else l.name end
                    from public.locations l
                    left join public.accounts a2 on a2.id = l.account_id
                   where l.id = v_row.location_id),
        'marca', (select b.name from public.brand b where b.id = v_row.brand_id)),
        timeout_milliseconds := 10000
      ) into v_new_request;
      update public.system_alert_queue
        set request_id = v_new_request, attempts = attempts + 1, last_attempt_at = now()
        where id = v_row.id;
    end loop;
  end if;

  delete from public.system_alert_queue
    where status in ('sent', 'failed') and created_at < now() - interval '7 days';

  -- 3.3) Meta-aviso. "Degradado" = al menos un FALLO CONFIRMADO en la ultima
  -- hora (last_error solo se rellena al confirmar un fallo, nunca al disparar).
  select count(*) into v_degraded_n
  from public.system_alert_queue
  where last_error is not null and created_at >= now() - interval '60 minutes';

  if v_degraded_n > 0 then
    raise warning 'system_alert_queue_drain: % aviso(s) sin poder entregarse en la ultima hora — el canal de alertas puede estar caido', v_degraded_n;
    if not exists (
      select 1 from public.system_alert_queue
      where debounce_kind = 'db-health-alert-queue-degraded' and created_at >= now() - interval '60 minutes'
    ) then
      perform public._queue_system_alert(
        'db-health',
        'Canal de alertas degradado — ' || v_degraded_n || ' aviso(s) sin entregar en 1h',
        v_degraded_n || ' aviso(s) llevan en cola sin poder entregarse en la ultima hora (fallo de red/DNS o Resend). '
          || 'Revisa system_alert_queue y los logs de Postgres.',
        'db-health-alert-queue-degraded'
      );
    end if;
  end if;
exception when others then
  raise warning 'system_alert_queue_drain: excepcion no controlada: %', sqlerrm;
  raise;
end;
$$;


--
-- Name: FUNCTION system_alert_queue_drain(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.system_alert_queue_drain() IS 'Drena system_alert_queue cada minuto (cron system-alert-queue-drain): resuelve peticiones en vuelo contra net._http_response (200->sent, otro resultado->reintenta o failed a la 3a) y dispara las listas. El antiruido se escribe SOLO al confirmar un 200 — nunca al encolar. Meta-aviso por dos vias si hay fallos confirmados en la ultima hora.';


--
-- Name: team_compliance_scan(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_compliance_scan(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(employee_id uuid, employee_name text, location_id uuid, started_at timestamp with time zone, ended_at timestamp with time zone, worked_minutes numeric, night_minutes numeric, issue_code text, issue_severity text, issue_detail text, legal_ref text)
    LANGUAGE sql STABLE
    AS $$
  with pol as (
    select distinct on (loc.id) loc.id as location_id,
           coalesce(bl.max_continuous_minutes, bc.max_continuous_minutes) as max_cont,
           coalesce(bl.min_rest_between_shifts_minutes, bc.min_rest_between_shifts_minutes, 720) as min_rest,
           coalesce(bl.max_daily_minutes, bc.max_daily_minutes, 540) as max_daily,
           coalesce(bl.rules, bc.rules, '[]'::jsonb) as rules,
           coalesce(bl.night_start, bc.night_start, '22:00'::time) as ns,
           coalesce(bl.night_end,   bc.night_end,   '06:00'::time) as ne
    from public.locations loc
    left join public.break_policy bc on bc.account_id = loc.account_id and bc.location_id is null
    left join public.break_policy bl on bl.location_id = loc.id
    where loc.account_id = p_account
  ),
  j as (
    select w.*, e.name as emp_name,
           public.night_minutes_in_span(w.started_at, w.ended_at, p.ns, p.ne) as night_min,
           p.max_cont, p.min_rest, p.max_daily, p.rules,
           lag(w.ended_at) over (partition by w.employee_id order by w.started_at) as prev_end
    from public.team_worked_shifts(p_account, p_from, p_to) w
    join public.employees e on e.id = w.employee_id
    left join pol p on p.location_id = w.location_id
  )
  select j.employee_id, j.emp_name, j.location_id, j.started_at, j.ended_at, j.minutes, j.night_min,
         'SIN_DESCANSO', 'serious',
         'Jornada de '||round(j.presence_minutes/60.0,1)||' h sin descanso registrado',
         'ET art. 34.4 / convenio'
  from j
  where j.rules <> '[]'::jsonb
    and j.presence_minutes >= coalesce((j.rules->0->>'min_shift_minutes')::numeric, 360)
    and j.break_minutes = 0
  union all
  select j.employee_id, j.emp_name, j.location_id, j.started_at, j.ended_at, j.minutes, j.night_min,
         'EXCESO_CONTINUO', 'warning',
         'Mas de '||round(j.max_cont/60.0,1)||' h seguidas sin pausa',
         'Convenio (jornada continuada)'
  from j
  where j.max_cont is not null and j.break_minutes = 0 and j.presence_minutes > j.max_cont
  union all
  -- DESCANSO_ENTRE_JORNADAS: solo si cambia el dia natural (Madrid) -> excluye turno partido del mismo dia
  select j.employee_id, j.emp_name, j.location_id, j.started_at, j.ended_at, j.minutes, j.night_min,
         'DESCANSO_ENTRE_JORNADAS', 'serious',
         'Solo '||round(extract(epoch from (j.started_at - j.prev_end))/3600.0,1)||' h desde la jornada del dia anterior',
         'ET art. 34.3 (12 h)'
  from j
  where j.prev_end is not null
    and j.started_at > j.prev_end
    and j.started_at - j.prev_end < make_interval(mins => j.min_rest::int)
    and (j.started_at at time zone 'Europe/Madrid')::date
        > (j.prev_end at time zone 'Europe/Madrid')::date   -- distinto dia natural = no es partida
  union all
  select j.employee_id, j.emp_name, j.location_id, j.started_at, j.ended_at, j.minutes, j.night_min,
         'EXCESO_JORNADA_DIARIA', 'warning',
         'Jornada trabajada de '||round(j.minutes/60.0,1)||' h (max '||round(j.max_daily/60.0,1)||' h)',
         'ET art. 34.3 (9 h ordinarias)'
  from j
  where j.minutes > j.max_daily;
$$;


--
-- Name: team_demand_by_hour(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_demand_by_hour(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(location_id uuid, hour_of_day integer, units numeric)
    LANGUAGE sql STABLE
    AS $$
  with kinds as (
    select coalesce(
      (select counted_kinds from public.team_demand_config where account_id = p_account),
      array['cocina']
    ) as k
  )
  select s.location_id,
         extract(hour from (s.sold_at at time zone 'Europe/Madrid'))::int as h,
         coalesce(sum(sl.quantity), 0) as units
  from public.sale s
  join public.sale_line sl on sl.sale_id = s.id
  join public.menu_item mi on mi.id = sl.menu_item_id
  join public.menu_category mc on mc.id = mi.menu_category_id
  cross join kinds
  where s.account_id = p_account
    and coalesce(s.is_active, true)
    and s.sold_at >= p_from and s.sold_at < p_to
    and mc.demand_kind = any (kinds.k)
  group by s.location_id, 2;
$$;


--
-- Name: team_demand_coefficients(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_demand_coefficients(p_account uuid) RETURNS TABLE(dim text, key integer, idx_final numeric, idx_own numeric, idx_prior numeric, weight_own numeric, own_days integer)
    LANGUAGE sql STABLE
    AS $$
  with biz as (
    select coalesce((select business_type from public.accounts where id = p_account), 'dark_kitchen') as bt
  ),
  -- Días con ventas de la cuenta (para calcular medias propias por día/mes).
  days as (
    select (s.sold_at at time zone 'Europe/Madrid')::date as d,
           extract(isodow from (s.sold_at at time zone 'Europe/Madrid'))::int - 1 as dow,
           extract(month  from (s.sold_at at time zone 'Europe/Madrid'))::int as mon,
           count(*)::numeric as tickets
    from public.sale s
    where s.account_id = p_account and coalesce(s.is_active, true)
    group by 1, 2, 3
  ),
  base as (  -- media global de tickets/día de la cuenta (denominador del índice)
    select nullif(avg(tickets), 0) as m from days
  ),
  -- Índice propio por día de la semana + nº de días observados de ese dow.
  own_dow as (
    select 'dow'::text dim, dow key, (avg(tickets) / (select m from base)) idx, count(*)::int n
    from days group by dow
  ),
  own_mon as (
    select 'month'::text dim, mon key, (avg(tickets) / (select m from base)) idx, count(*)::int n
    from days group by mon
  ),
  own as (select * from own_dow union all select * from own_mon),
  prior as (
    select dp.dim, dp.key, dp.idx from public.demand_prior dp, biz where dp.business_type = biz.bt
  ),
  -- Rejilla completa de claves (dow 0..6, month 1..12) para no perder ninguna.
  grid as (
    select 'dow'::text dim, g key from generate_series(0,6) g
    union all
    select 'month'::text, g from generate_series(1,12) g
  )
  select
    grid.dim, grid.key,
    -- w = n / (n + K): con K=6, hacen falta ~6 observaciones para pesar 50 % lo propio.
    round(
      coalesce(o.n,0)::numeric / (coalesce(o.n,0) + 6) * coalesce(o.idx, coalesce(p.idx,1))
      + (1 - coalesce(o.n,0)::numeric / (coalesce(o.n,0) + 6)) * coalesce(p.idx, coalesce(o.idx,1))
    , 3) as idx_final,
    round(coalesce(o.idx, 0), 3) as idx_own,
    round(coalesce(p.idx, 0), 3) as idx_prior,
    round(coalesce(o.n,0)::numeric / (coalesce(o.n,0) + 6), 2) as weight_own,
    coalesce(o.n, 0) as own_days
  from grid
  left join own   o on o.dim = grid.dim and o.key = grid.key
  left join prior p on p.dim = grid.dim and p.key = grid.key
  order by grid.dim, grid.key;
$$;


--
-- Name: team_demand_forecast(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_demand_forecast(p_account uuid, p_location uuid, p_week_start date) RETURNS TABLE(fecha date, dow integer, mes integer, base_reciente numeric, base_anual numeric, idx_dow numeric, idx_mes numeric, factor_base numeric, tendencia numeric, prevision numeric, dias_datos integer)
    LANGUAGE sql STABLE
    AS $$
  with cfg as (
    select coalesce(
      (select counted_kinds from public.team_demand_config where account_id = p_account),
      array['cocina']
    ) as kinds
  ),
  loc_days as (
    select (s.sold_at at time zone 'Europe/Madrid')::date as d,
           sum(sl.quantity)::numeric as platos
    from public.sale s
    join public.sale_line sl on sl.sale_id = s.id
    join public.menu_item mi on mi.id = sl.menu_item_id
    join public.menu_category mc on mc.id = mi.menu_category_id
    cross join cfg
    where s.account_id = p_account
      and s.location_id = p_location
      and coalesce(s.is_active, true)
      and mc.demand_kind = any (cfg.kinds)
    group by 1
  ),
  anchor as (select max(d) as ad from loc_days),
  base_win as (
    select d, platos, extract(month from d)::int as mon
    from loc_days, anchor
    where anchor.ad is not null and d > anchor.ad - 56 and d <= anchor.ad
  ),
  base_stats as (select avg(platos) as base_reciente, count(*)::int as dias from base_win),
  coef as (select dim, key, idx_final from public.team_demand_coefficients(p_account)),
  season_base as (
    select coalesce(avg(c.idx_final), 1) as f
    from base_win b left join coef c on c.dim='month' and c.key = b.mon
  ),
  tc as (
    select (select sum(platos) from loc_days, anchor where d > anchor.ad - 14 and d <= anchor.ad) as t_recent,
           (select sum(platos) from loc_days, anchor where d > anchor.ad - 28 and d <= anchor.ad - 14) as t_prev
  ),
  trend as (
    select case
      when (select dias from base_stats) < 21 then 1.0
      when coalesce(t_prev,0) <= 0 or coalesce(t_recent,0) <= 0 then 1.0
      else least(1.15, greatest(0.85, t_recent / t_prev))
    end as tv
    from tc
  ),
  days as (
    select (p_week_start + g)::date as fecha,
           (extract(isodow from (p_week_start + g))::int - 1) as dow,
           extract(month from (p_week_start + g))::int as mes
    from generate_series(0,6) g
  )
  select
    d.fecha, d.dow, d.mes,
    round(bs.base_reciente, 1) as base_reciente,
    round(bs.base_reciente / nullif(sb.f,0), 1) as base_anual,
    cd.idx_final as idx_dow,
    cm.idx_final as idx_mes,
    round(sb.f, 3) as factor_base,
    round(tr.tv, 3) as tendencia,
    round((bs.base_reciente / nullif(sb.f,0)) * coalesce(cd.idx_final,1) * coalesce(cm.idx_final,1) * tr.tv, 0) as prevision,
    bs.dias as dias_datos
  from days d
  cross join base_stats bs
  cross join season_base sb
  cross join trend tr
  left join coef cd on cd.dim='dow'   and cd.key = d.dow
  left join coef cm on cm.dim='month' and cm.key = d.mes
  order by d.fecha;
$$;


--
-- Name: team_demand_profile(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_demand_profile(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(location_id uuid, dow integer, hour_of_day integer, units numeric)
    LANGUAGE sql STABLE
    AS $$
  with kinds as (
    select coalesce(
      (select counted_kinds from public.team_demand_config where account_id = p_account),
      array['cocina']
    ) as k
  )
  select a.location_id,
         (extract(isodow from a.day)::int - 1) as dow,
         a.hour::int as hour_of_day,
         coalesce(sum(a.units), 0) as units
  from public.sales_hourly_agg a
  cross join kinds
  where a.account_id = p_account
    and a.day >= (p_from at time zone 'Europe/Madrid')::date
    and a.day <= (p_to   at time zone 'Europe/Madrid')::date
    and a.demand_kind = any (kinds.k)
  group by a.location_id, 2, 3;
$$;


--
-- Name: team_hours_summary(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_hours_summary(p_account_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(employee_id uuid, employee_name text, location_id uuid, contracted_hours numeric, worked_hours numeric, vacation_hours numeric, night_hours numeric, delta_hours numeric, labor_cost numeric, cost_is_partial boolean)
    LANGUAGE sql STABLE
    AS $$
  with emp as (
    select e.id, e.name, e.location_id
    from public.employees e
    where e.account_id = p_account_id and e.active = true
      and (p_location_id is null or e.location_id = p_location_id)
  ),
  bal as (
    select emp.id as employee_id, emp.name, emp.location_id, b.*
    from emp
    cross join lateral public.compute_employee_balance(emp.id, p_from, p_to) b
  ),
  months as (
    select distinct extract(year from d)::int as y, extract(month from d)::int as m
    from generate_series(p_from, p_to, interval '1 month') d
  ),
  cost as (
    select pc.employee_id, sum(pc.total_cost) as labor_cost
    from public.payroll_cost pc
    join months mo on mo.y = pc.period_year and mo.m = pc.period_month
    where pc.account_id = p_account_id
    group by pc.employee_id
  )
  select bal.employee_id, bal.name, bal.location_id,
    bal.contracted_hours, bal.worked_hours, bal.paid_absence_hours,
    bal.night_hours, bal.delta_hours,
    c.labor_cost, (c.labor_cost is null) as cost_is_partial
  from bal
  left join cost c on c.employee_id = bal.employee_id
  order by bal.name;
$$;


--
-- Name: team_labor_requirement(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_labor_requirement(p_account uuid, p_location uuid, p_week_start date) RETURNS TABLE(fecha date, dow integer, hora integer, role_kind text, driver text, volumen numeric, per_person_hour numeric, required integer, required_exact numeric, is_estimate boolean)
    LANGUAGE sql STABLE
    AS $$
  with biz as (
    select coalesce((select business_type from public.accounts where id = p_account), 'dark_kitchen') as bt
  ),
  intensity as (
    select case coalesce((select labor_intensity from public.team_demand_config where account_id = p_account), 'normal')
             when 'holgado' then 1.15 when 'ajustado' then 0.90 else 1.0 end as m
  ),
  kinds as (
    select k.role_kind,
      coalesce(mp.driver, m.driver, pr.driver, 'platos')                as driver,
      coalesce(mp.per_person_hour, m.per_person_hour, pr.per_person_hour, 30) as pph,
      coalesce(mp.min_on_open, m.min_on_open, pr.min_on_open, 0)         as min_open,
      coalesce(mp.open_close_extra, m.open_close_extra, pr.open_close_extra, 0) as oc_extra,
      (mp.role_kind is null and m.role_kind is null)                    as is_estimate
    from (select distinct kind as role_kind from public.staff_role where account_id = p_account and active) k
    left join public.team_labor_model mp on mp.account_id = p_account and mp.location_id = p_location and mp.role_kind = k.role_kind and mp.active
    left join public.team_labor_model m  on m.account_id = p_account and m.location_id is null and m.role_kind = k.role_kind and m.active
    left join public.labor_model_prior pr on pr.business_type = (select bt from biz) and pr.role_kind = k.role_kind
  ),
  ppt as (
    select coalesce(sum(sl.quantity) / nullif(count(distinct s.id), 0), 2.1) as r
    from public.sale s
    join public.sale_line sl on sl.sale_id = s.id
    join public.menu_item mi on mi.id = sl.menu_item_id
    join public.menu_category mc on mc.id = mi.menu_category_id
    where s.account_id = p_account and s.location_id = p_location and coalesce(s.is_active, true)
      and mc.demand_kind = any (coalesce((select counted_kinds from public.team_demand_config where account_id = p_account), array['cocina']))
      and s.sold_at >= now() - interval '63 days'
  ),
  prof as (
    select dow, hour_of_day as h, sum(units) as u
    from public.team_demand_profile(p_account, now() - interval '63 days', now())
    where location_id = p_location
    group by 1, 2
  ),
  shape as (select dow, h, u, sum(u) over (partition by dow) as tot from prof where u > 0),
  openh as (select dow, min(h) as h0, max(h) as h1 from shape group by dow),
  fc as (select fecha, dow, prevision from public.team_demand_forecast(p_account, p_location, p_week_start)),
  hourly as (
    select fc.fecha, fc.dow, s.h, fc.prevision * s.u / nullif(s.tot, 0) as platos_hora
    from fc join shape s on s.dow = fc.dow
  ),
  calc as (
    select h.fecha, h.dow, h.h, k.role_kind, k.driver, k.pph, k.min_open, k.oc_extra, k.is_estimate,
           case k.driver when 'tickets' then h.platos_hora / (select r from ppt)
                         when 'fixed'   then 0
                         else h.platos_hora end as vol,
           o.h0, o.h1
    from hourly h cross join kinds k join openh o on o.dow = h.dow
  )
  select c.fecha, c.dow, c.h as hora, c.role_kind, c.driver,
         round(c.vol, 1) as volumen,
         c.pph,
         -- required (int): se conserva por compatibilidad, ahora al ENTERO MAS PROXIMO
         ( greatest(c.min_open,
             case when c.driver = 'fixed' then c.min_open
                  else round(c.vol / nullif(c.pph,0) * (select m from intensity)) end)
           + case when c.h = c.h0 or c.h = c.h1 then c.oc_extra else 0 end )::int as required,
         -- required_exact: SIN redondear. Es el que debe usar el generador.
         round( greatest(c.min_open::numeric,
                  case when c.driver = 'fixed' then c.min_open::numeric
                       else c.vol / nullif(c.pph,0) * (select m from intensity) end)
                + case when c.h = c.h0 or c.h = c.h1 then c.oc_extra else 0 end , 3) as required_exact,
         c.is_estimate
  from calc c
  order by c.fecha, c.h, c.role_kind;
$$;


--
-- Name: team_sales_by_hour(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_sales_by_hour(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(location_id uuid, hour_of_day integer, tickets bigint, ventas numeric)
    LANGUAGE sql STABLE
    AS $$
  select location_id,
         extract(hour from (sold_at at time zone 'Europe/Madrid'))::int,
         count(*)::bigint, coalesce(sum(total), 0)
  from public.sale
  where account_id = p_account and coalesce(is_active, true)
    and sold_at >= p_from and sold_at < p_to
  group by location_id, 2;
$$;


--
-- Name: team_sales_by_location(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_sales_by_location(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(location_id uuid, tickets bigint, ventas numeric, base numeric, coste_lineas numeric, lineas_total bigint, lineas_con_coste bigint)
    LANGUAGE sql STABLE
    AS $$
  with sc as (
    select location_id, count(*)::bigint tickets,
           coalesce(sum(total), 0) ventas, coalesce(sum(taxable_base), 0) base
    from public.sale
    where account_id = p_account and coalesce(is_active, true)
      and sold_at >= p_from and sold_at < p_to
    group by location_id
  ),
  lc as (
    select s.location_id,
           coalesce(sum(sl.computed_cost), 0) coste,
           count(sl.id)::bigint lineas,
           count(sl.computed_cost)::bigint con_coste
    from public.sale s
    join public.sale_line sl on sl.sale_id = s.id
    where s.account_id = p_account and coalesce(s.is_active, true)
      and s.sold_at >= p_from and s.sold_at < p_to
    group by s.location_id
  )
  select sc.location_id, sc.tickets, sc.ventas, sc.base,
         coalesce(lc.coste, 0), coalesce(lc.lineas, 0), coalesce(lc.con_coste, 0)
  from sc left join lc on lc.location_id = sc.location_id;
$$;


--
-- Name: team_worked_shifts(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_worked_shifts(p_account uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(employee_id uuid, location_id uuid, started_at timestamp with time zone, ended_at timestamp with time zone, minutes numeric, presence_minutes numeric, break_minutes numeric)
    LANGUAGE sql STABLE
    AS $$
  with base as (
    select ce.employee_id,
           ce.location_id_at_clock as location_id,
           ce.type, ce.real_datetime as rt
    from public.clock_entries ce
    join public.employees e on e.id = ce.employee_id
    where coalesce(ce.voided, false) = false
      and e.location_id in (select id from public.locations where account_id = p_account)
      and ce.real_datetime >= p_from
      and ce.real_datetime <  p_to + interval '16 hours'
  ),
  spans as (
    select b.employee_id, b.location_id, b.rt as started_at,
           (select min(s.rt) from base s
             where s.employee_id = b.employee_id and s.type='salida' and s.rt > b.rt) as ended_at
    from base b
    where b.type = 'entrada'
      and b.rt >= p_from and b.rt < p_to
  ),
  valid as (
    select s.* from spans s
    where s.ended_at is not null
      and s.ended_at - s.started_at < interval '16 hours'
      -- entrada huerfana: hay otra 'entrada' antes de la salida -> se olvido fichar la salida. Se descarta.
      and not exists (
        select 1 from base x
        where x.employee_id = s.employee_id and x.type = 'entrada'
          and x.rt > s.started_at and x.rt < s.ended_at
      )
  ),
  pauses as (
    select v.employee_id, v.started_at,
           coalesce(sum(extract(epoch from (
             (select min(f.rt) from base f
               where f.employee_id = v.employee_id and f.type='pausa_fin' and f.rt > p.rt
                 and f.rt <= v.ended_at)
             - p.rt)) / 60.0), 0) as break_min
    from valid v
    left join base p
      on p.employee_id = v.employee_id and p.type = 'pausa_inicio'
     and p.rt > v.started_at and p.rt < v.ended_at
    group by v.employee_id, v.started_at
  )
  select v.employee_id, v.location_id, v.started_at, v.ended_at,
         round(extract(epoch from (v.ended_at - v.started_at))/60.0 - coalesce(pz.break_min,0), 1) as minutes,
         round(extract(epoch from (v.ended_at - v.started_at))/60.0, 1) as presence_minutes,
         round(coalesce(pz.break_min,0), 1) as break_minutes
  from valid v
  left join pauses pz
    on pz.employee_id = v.employee_id and pz.started_at = v.started_at;
$$;


--
-- Name: tg_ajuste_aparta_la_linea_pendiente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_ajuste_aparta_la_linea_pendiente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_line uuid;
BEGIN
  -- LA ULTIMA PALABRA ES LA DE LA PERSONA (11/09/2026). Si alguien corrige a
  -- mano el stock de un articulo que esta en un recuento sin aprobar, las dos
  -- cosas se sumarian al aprobar: el ajuste del recuento lleva la hora de
  -- cuando se conto, asi que ni siquiera «gana el ultimo». Paso el 11/09 con
  -- cinco productos de Alcala (Lima 1.000 -> 1.360,7 g, y cuatro mas).
  --
  -- No se toca el recuento entero: se aparta ESA linea, con su motivo y su
  -- nombre, y se ve apartada en la pantalla de revision.
  SELECT l.id INTO v_line
    FROM public.inventory_count_line l
    JOIN public.inventory_count ic ON ic.id = l.inventory_count_id
   WHERE l.account_id     = NEW.account_id
     AND ic.location_id   = NEW.location_id
     AND l.recipe_item_id = NEW.recipe_item_id
     AND ic.status IN ('contando', 'en_revision')
     AND l.excluded_at IS NULL
   ORDER BY ic.created_at DESC
   LIMIT 1;
  IF v_line IS NULL THEN RETURN NEW; END IF;
  UPDATE public.inventory_count_line
     SET excluded_at      = now(),
         excluded_by      = NEW.created_by,
         excluded_by_name = NEW.created_by_name,
         excluded_reason  = 'Se corrigió a mano el stock de este producto'
   WHERE id = v_line;
  RETURN NEW;
END;
$$;


--
-- Name: tg_auto_dispatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_auto_dispatch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_mode     text;
  v_carrier  text;
  v_reason   text;
  v_strategy text;
  v_timeout  int;
  v_courier  uuid;
  v_secret   text;
  v_url      text := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/catcher-dispatch';
  v_anon     text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Inh6bXBuY2hsZ3VpYmNsdnh5eW50Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxNzE1NTksImV4cCI6MjA5Mzc0NzU1OX0.v5GsOW5hxwzJZA0z5Le26E9vAWflG1XFZ7ec2hvMphY';
BEGIN
  IF new.service_type = 'own_delivery'
     AND new.order_status = 'accepted'
     AND new.carrier_order_id IS NULL
     AND (tg_op = 'INSERT' OR old.order_status IS DISTINCT FROM new.order_status)
  THEN
    IF EXISTS (SELECT 1 FROM public.delivery_assignment da
               WHERE da.sale_id = new.id AND da.state NOT IN ('failed','canceled')) THEN
      RETURN new;
    END IF;

    SELECT coalesce(l.dispatch_mode,'auto') INTO v_mode
      FROM public.locations l WHERE l.id = new.location_id;
    IF v_mode <> 'auto' THEN RETURN new; END IF;

    SELECT carrier, reason INTO v_carrier, v_reason FROM public.resolve_dispatch(new.id);

    IF v_carrier = 'own_fleet' THEN
      SELECT coalesce(l.assignment_strategy,'broadcast'), coalesce(l.offer_timeout_s,60)
        INTO v_strategy, v_timeout FROM public.locations l WHERE l.id = new.location_id;

      IF v_strategy = 'nearest' THEN
        SELECT c.id INTO v_courier
          FROM public.courier c, public.locations l
         WHERE l.id = new.location_id AND c.account_id = new.account_id AND c.active AND c.on_shift
           AND (c.assigned_locations = '{}'::uuid[] OR new.location_id = ANY(c.assigned_locations))
         ORDER BY (CASE WHEN c.last_lat IS NOT NULL AND c.last_lng IS NOT NULL AND l.lat IS NOT NULL AND l.lng IS NOT NULL
                        THEN 2*6371*asin(sqrt(power(sin(radians(c.last_lat - l.lat)/2),2)
                             + cos(radians(l.lat))*cos(radians(c.last_lat))*power(sin(radians(c.last_lng - l.lng)/2),2)))
                        ELSE NULL END) ASC NULLS LAST
         LIMIT 1;
        INSERT INTO public.delivery_assignment (sale_id, account_id, location_id, state, assigned_by, offered_to, offer_expires_at)
        VALUES (new.id, new.account_id, new.location_id, 'offered', 'auto', v_courier,
                CASE WHEN v_courier IS NOT NULL THEN now() + make_interval(secs => v_timeout) ELSE NULL END);
      ELSE
        INSERT INTO public.delivery_assignment (sale_id, account_id, location_id, state, assigned_by)
        VALUES (new.id, new.account_id, new.location_id, 'offered', 'auto');
      END IF;

    ELSIF v_carrier = 'catcher' THEN
      SELECT decrypted_secret INTO v_secret
        FROM vault.decrypted_secrets WHERE name = 'catcher_dispatch_secret';
      PERFORM net.http_post(
        url     := v_url,
        headers := jsonb_build_object('Content-Type','application/json',
                                      'Authorization', 'Bearer ' || v_anon,
                                      'x-catcher-dispatch-secret', v_secret),
        body    := jsonb_build_object('sale_id', new.id, 'internal', true)
      );
    END IF;
  END IF;
  RETURN new;
END;
$$;


--
-- Name: tg_auto_print_bag_on_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_auto_print_bag_on_ready() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_printer record; v_doc text; v_i int; v_on boolean := false;
begin
  if new.order_status = 'awaiting_collection'
     and old.order_status is distinct from new.order_status then
    begin
      select coalesce(k.bag_on_ready, false) into v_on
      from kitchen_time_config k where k.location_id = new.location_id;
      if not coalesce(v_on, false) then return new; end if;

      -- El rastro de la BOLSA, igual que estaba.
      if not exists (
        select 1 from printer
        where account_id = new.account_id and location_id = new.location_id
          and is_active and 'bag' = any(doc_types)
      ) then
        insert into print_route_failure_log (account_id, location_id, sale_id, doc_type, detail)
        select new.account_id, new.location_id, new.id, 'bag',
               'tg_auto_print_bag_on_ready: bag_on_ready activo pero sin impresora activa con doc_type bag'
        where not exists (
          select 1 from print_route_failure_log
          where location_id = new.location_id
            and detail = 'tg_auto_print_bag_on_ready: bag_on_ready activo pero sin impresora activa con doc_type bag'
            and created_at >= now() - interval '30 minutes'
        );
      end if;

      -- Y el rastro de las PEGATINAS (19/09). Se avisa SOLO si este local
      -- tiene impresora de pegatinas y esta DESACTIVADA: eso es alguien que
      -- la apago y un monton de etiquetas que no va a aparecer. Si el local
      -- no tiene ninguna configurada, no grita -- un local que nunca ha
      -- llevado pegatinas no tiene por que.
      --
      -- Aqui dentro ya solo se llega con bag_on_ready activo, asi que este
      -- aviso no puede saltar en un local que saca la bolsa al entrar.
      if not exists (
        select 1 from printer
        where account_id = new.account_id and location_id = new.location_id
          and is_active and 'labels' = any(doc_types)
      ) and exists (
        select 1 from printer
        where account_id = new.account_id and location_id = new.location_id
          and 'labels' = any(doc_types)
      ) then
        insert into print_route_failure_log (account_id, location_id, sale_id, doc_type, detail)
        select new.account_id, new.location_id, new.id, 'labels',
               'tg_auto_print_bag_on_ready: hay impresora de pegatinas pero esta DESACTIVADA - este pedido sale sin pegatinas'
        where not exists (
          select 1 from print_route_failure_log
          where location_id = new.location_id
            and detail = 'tg_auto_print_bag_on_ready: hay impresora de pegatinas pero esta DESACTIVADA - este pedido sale sin pegatinas'
            and created_at >= now() - interval '30 minutes'
        );
      end if;

      -- CADA PAPEL A SU MAQUINA. El bucle coge las impresoras que sacan
      -- bolsa O pegatinas, y dentro cada doc_type solo se encola en una
      -- impresora que lo tenga en sus doc_types. En Alcala son maquinas
      -- DISTINTAS -- Pase {bag} 192.168.1.132, Pegatina {labels}
      -- 192.168.1.151 -- y por eso el filtro NO puede ser 'bag' = any(...):
      -- heredarlo mandaria las pegatinas al papel de la bolsa, o dejaria a
      -- Alcala sin pegatinas y en silencio.
      for v_printer in
        select id, doc_types, copies from printer
        where account_id = new.account_id and location_id = new.location_id
          and is_active and doc_types && array['bag','labels']::text[]
      loop
        -- Orden fijo: primero la bolsa, luego las pegatinas.
        foreach v_doc in array array['bag','labels']::text[] loop
          if v_doc = any (v_printer.doc_types)
             and not exists (
               -- La MISMA guarda de siempre, ahora por doc_type: cerrar,
               -- reabrir y volver a cerrar no encola nada dos veces.
               select 1 from print_job pj
               where pj.sale_id = new.id and pj.source = 'auto'
                 and pj.doc_type = v_doc and pj.printer_id = v_printer.id
             ) then
            for v_i in 1..greatest(1, coalesce(v_printer.copies, 1)) loop
              insert into print_job (account_id, location_id, printer_id, sale_id, doc_type, payload, source, status)
              values (new.account_id, new.location_id, v_printer.id, new.id, v_doc,
                      jsonb_build_object('sale_id', new.id, 'mode', 'by_order'), 'auto', 'pending');
            end loop;
          end if;
        end loop;
      end loop;
    exception when others then
      raise warning 'tg_auto_print_bag_on_ready: fallo inesperado para sale %: %', new.id, sqlerrm;
    end;
  end if;
  return new;
end;
$$;


--
-- Name: tg_auto_print_on_accept(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_auto_print_on_accept() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_printer record; v_doc text; v_i int;
  v_fire boolean := false;
  v_bag_on_ready boolean := false;
begin
  if new.order_status = 'accepted' then
    if TG_OP = 'INSERT' then v_fire := true;
    elsif old.order_status is distinct from new.order_status then v_fire := true;
    end if;
  end if;

  -- TPV sala (S1): una MESA imprime por envíos (pos_table_fire), nunca el
  -- pedido entero al aceptarse.
  if v_fire and new.table_id is not null then v_fire := false; end if;

  if v_fire then
    begin
      select coalesce(k.bag_on_ready, false) into v_bag_on_ready
      from kitchen_time_config k where k.location_id = new.location_id;
      v_bag_on_ready := coalesce(v_bag_on_ready, false);

      if not exists (
        select 1 from printer
        where account_id = new.account_id and location_id = new.location_id and is_active
      ) then
        -- Fallo mudo evitado (11/08): sin esto, el pedido se acepta y JAMAS
        -- imprime nada, sin que nadie se entere. Dedup: 1 rastro por local
        -- cada 30min, no uno por pedido.
        insert into print_route_failure_log (account_id, location_id, sale_id, doc_type, detail)
        select new.account_id, new.location_id, new.id, null,
               'tg_auto_print_on_accept: sin impresoras activas en el local'
        where not exists (
          select 1 from print_route_failure_log
          where location_id = new.location_id
            and detail = 'tg_auto_print_on_accept: sin impresoras activas en el local'
            and created_at >= now() - interval '30 minutes'
        );
      end if;

      for v_printer in
        select id, doc_types, copies from printer
        where account_id = new.account_id and location_id = new.location_id and is_active
      loop
        foreach v_doc in array v_printer.doc_types loop
          -- La BOLSA y las PEGATINAS se saltan aqui SOLO si este local
          -- imprime bolsa al "Listo" (19/09): las pegatinas viajan con la
          -- bolsa. La COCINA nunca se salta: la necesita al entrar.
          if not (v_doc = any (array['bag','labels']) and v_bag_on_ready)
             and not exists (
               select 1 from print_job pj
               where pj.sale_id = new.id and pj.source = 'auto'
                 and pj.doc_type = v_doc and pj.printer_id = v_printer.id
             ) then
            for v_i in 1..greatest(1, coalesce(v_printer.copies, 1)) loop
              insert into print_job (account_id, location_id, printer_id, sale_id, doc_type, payload, source, status)
              values (new.account_id, new.location_id, v_printer.id, new.id, v_doc,
                      jsonb_build_object('sale_id', new.id, 'mode', 'by_order'), 'auto', 'pending');
            end loop;
          end if;
        end loop;
      end loop;
    exception when others then
      -- Antes: `null` — se tragaba CUALQUIER error en silencio absoluto.
      raise warning 'tg_auto_print_on_accept: fallo inesperado para sale %: %', new.id, sqlerrm;
    end;
  end if;

  return new;
end;
$$;


--
-- Name: tg_bank_match_deshecho_impuesto(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_bank_match_deshecho_impuesto() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record;
begin
  for i in select it.tax_return_id from public.bank_match_item it where it.match_id = new.id and it.tax_return_id is not null loop
    update public.tax_return
       set status = case when liquidation_entry_id is not null then 'booked' else 'filed' end,
           bank_match_id = null, payment_entry_id = null, updated_at = now()
     where id = i.tax_return_id and status in ('paid', 'refunded') and bank_match_id = new.id;
    insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message)
    select t.id, t.account_id, t.company_id, auth.uid(), public.conta_impuesto_quien(), 'note',
           'Se deshizo el casado del pago en Bancos: ' || coalesce(new.undo_reason, 'sin motivo') || '.'
      from public.tax_return t where t.id = i.tax_return_id;
  end loop;
  return new;
end $$;


--
-- Name: tg_brand_delivery_policy_misma_cuenta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_brand_delivery_policy_misma_cuenta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from public.brand b where b.id = new.brand_id and b.account_id = new.account_id) then
    raise exception 'brand_delivery_policy: la marca % no es de la cuenta %', new.brand_id, new.account_id
      using errcode = '23514';
  end if;
  if new.location_id <> '00000000-0000-0000-0000-000000000000'::uuid
     and not exists (select 1 from public.locations l where l.id = new.location_id and l.account_id = new.account_id) then
    raise exception 'brand_delivery_policy: el local % no es de la cuenta %', new.location_id, new.account_id
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: tg_clock_entry_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_clock_entry_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_reason text := nullif(current_setting('app.clock_edit_reason', true), '');
  v_actor  text := nullif(current_setting('app.clock_edit_actor',  true), '');
  v_action text;
  v_acct   uuid;
begin
  select l.account_id into v_acct
  from public.employees e join public.locations l on l.id = e.location_id
  where e.id = coalesce(NEW.employee_id, OLD.employee_id);

  if TG_OP = 'UPDATE' then
    if NEW.voided is distinct from OLD.voided then
      v_action := case when NEW.voided then 'void' else 'restore' end;
    else
      v_action := 'edit';
    end if;
    insert into public.clock_entry_audit(
      clock_entry_id, employee_id, account_id, action, actor_user_id, actor_label, reason, before, after)
    values (OLD.id, OLD.employee_id, v_acct, v_action, auth.uid(), v_actor,
            coalesce(v_reason, '(sin motivo — edición directa)'),
            public._clock_snapshot(OLD), public._clock_snapshot(NEW));
    return NEW;

  elsif TG_OP = 'DELETE' then
    insert into public.clock_entry_audit(
      clock_entry_id, employee_id, account_id, action, actor_user_id, actor_label, reason, before, after)
    values (OLD.id, OLD.employee_id, v_acct, 'void', auth.uid(), v_actor,
            coalesce(v_reason, '(sin motivo — borrado físico directo)'),
            public._clock_snapshot(OLD), null);
    return OLD;
  end if;
  return null;
end $$;


--
-- Name: tg_clock_entry_debounce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_clock_entry_debounce() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(new.source,'kiosko') in ('kiosko','movil','tablet') then
    if exists (
      select 1 from public.clock_entries c
      where c.employee_id = new.employee_id
        and coalesce(c.voided,false) = false
        and abs(extract(epoch from (
              coalesce(c.real_datetime,c.datetime) - coalesce(new.real_datetime,new.datetime)
            ))) < 60
    ) then
      raise exception 'DOBLE_FICHAJE_MUY_RAPIDO'
        using hint = 'Ya se registró un fichaje hace unos segundos.';
    end if;
  end if;
  return new;
end $$;


--
-- Name: tg_clock_entry_orden(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_clock_entry_orden() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- A partir de aqui una jornada abierta deja de ser "esta dentro" y pasa a ser
  -- "se olvido la salida". 12 h: por encima del turno mas largo real (el cierre
  -- tardio de Alcala son 5,75 h) y por debajo del hueco entre el cierre de una
  -- noche y la entrada del dia siguiente. No se inventa en cada rama: se declara
  -- aqui una vez.
  c_jornada_rancia constant interval := interval '12 hours';
  v_last     text;
  v_last_at  timestamptz;
  v_ts       timestamptz;
begin
  -- Las correcciones del gestor no pasan por aqui: van por
  -- add_manual_clock_entry, que tiene su propia guarda y su p_force.
  if coalesce(new.source,'') = 'manual' then
    return new;
  end if;

  v_ts := coalesce(new.real_datetime, new.datetime, now());

  select ce.type, ce.real_datetime
    into v_last, v_last_at
  from clock_entries ce
  where ce.employee_id = new.employee_id
    and coalesce(ce.voided,false) = false
    and ce.real_datetime <= v_ts
  order by ce.real_datetime desc
  limit 1;

  -- ── PAUSAS — identico a tg_clock_entry_pause_order, que esta se retira ────
  if new.type in ('pausa_inicio','pausa_fin') then
    if new.type = 'pausa_inicio' then
      if v_last is null or v_last in ('salida','pausa_inicio') then
        raise exception 'PAUSA_FUERA_DE_ORDEN: no se puede iniciar una pausa sin estar fichado dentro'
          using hint = 'Ficha la entrada antes de iniciar la pausa.';
      end if;
    else
      if v_last is distinct from 'pausa_inicio' then
        raise exception 'PAUSA_FUERA_DE_ORDEN: no hay ninguna pausa iniciada que cerrar'
          using hint = 'Solo se puede volver de pausa si antes se inicio una.';
      end if;
    end if;
    return new;
  end if;

  -- ── ENTRADA ──────────────────────────────────────────────────────────────
  if new.type = 'entrada' then
    if v_last in ('entrada','pausa_inicio','pausa_fin') then
      if v_ts - v_last_at < c_jornada_rancia then
        raise exception 'YA_ESTA_DENTRO: hay una jornada abierta desde %',
          to_char(v_last_at at time zone 'Europe/Madrid','DD/MM HH24:MI')
          using hint = 'Ya estas dentro desde las '
                       || to_char(v_last_at at time zone 'Europe/Madrid','HH24:MI')
                       || '. ¿Querias fichar la SALIDA?';
      else
        -- "Ayer olvide la salida". Se acepta para no dejarla sin trabajar, y se
        -- deja dicho de donde viene.
        new.stale_prev_open_at := v_last_at;
      end if;
    end if;
    return new;
  end if;

  -- ── SALIDA ───────────────────────────────────────────────────────────────
  if new.type = 'salida' then
    if v_last is null or v_last = 'salida' then
      raise exception 'NO_ESTA_FICHADO: no hay ninguna entrada abierta que cerrar'
        using hint = 'No hay ninguna entrada abierta. ¿Querias fichar la ENTRADA?';
    end if;
    return new;
  end if;

  return new;
end $$;


--
-- Name: FUNCTION tg_clock_entry_orden(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_clock_entry_orden() IS 'Orden de los fichajes que NO son manuales: pausas (heredado de tg_clock_entry_pause_order, sin cambios) y entrada/salida (30/08/2026). Una ENTRADA sobre una jornada abierta de menos de 12 h se rechaza con YA_ESTA_DENTRO; si la jornada abierta es mas vieja se acepta y se marca en stale_prev_open_at. Una SALIDA sin entrada abierta se rechaza con NO_ESTA_FICHADO.';


--
-- Name: tg_conta_nomina_proponer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_conta_nomina_proponer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  begin
    perform public.conta_proponer_nominas(new.company_id, new.period_month, (date_trunc('month', new.period_month) + interval '1 month - 1 day')::date, 'Sumied (al llegar de la gestoría)');
  exception when others then
    perform public._conta_no_propuesta(new.company_id, 'payroll', new.id::text, 'Nóminas de ' || to_char(new.period_month, 'MM/YYYY'),
      'No he podido proponerla al llegar: ' || sqlerrm, 'Contabilidad › Asientos');
  end;
  return null;
end $$;


--
-- Name: tg_count_line_sella_el_motivo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_count_line_sella_el_motivo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid; v_nom text;
BEGIN
  IF NEW.reason_code IS NOT DISTINCT FROM OLD.reason_code THEN RETURN NEW; END IF;
  IF NEW.reason_code IS NULL OR NEW.reason_code = '' THEN
    NEW.reason_by := NULL; NEW.reason_by_name := NULL; RETURN NEW;
  END IF;
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    -- Sin persona identificada no se inventa un nombre: se deja el hueco.
    NEW.reason_by := NULL; NEW.reason_by_name := NULL; RETURN NEW;
  END IF;
  -- REGLA 9: `user_profiles` es multi-cuenta; se filtra por la cuenta de la linea.
  SELECT up.display_name INTO v_nom FROM public.user_profiles up
   WHERE up.user_id = v_uid AND up.account_id = NEW.account_id LIMIT 1;
  NEW.reason_by := v_uid;
  NEW.reason_by_name := v_nom;
  RETURN NEW;
END;
$$;


--
-- Name: tg_count_line_solo_por_la_puerta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_count_line_solo_por_la_puerta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sello text;
BEGIN
  -- Crear líneas sin contar es lo normal: `_generate_daily_count_core`,
  -- `build_inventory_count` y `request_recount` insertan con counted_qty NULL.
  IF TG_OP = 'INSERT' AND NEW.counted_qty IS NULL THEN
    RETURN NEW;
  END IF;

  -- Un UPDATE que no toca `counted_qty` no es asunto de esta puerta. Aquí
  -- pasan `close_inventory_count` (variación), `rebase_count_system_qty`
  -- (teórico) y el motivo que pone quien aprueba.
  IF TG_OP = 'UPDATE' AND NEW.counted_qty IS NOT DISTINCT FROM OLD.counted_qty THEN
    RETURN NEW;
  END IF;

  v_sello := current_setting('folvy.count_gate', true);

  IF v_sello = NEW.id::text OR v_sello = 'mantenimiento' THEN
    RETURN NEW;
  END IF;

  -- EL MENSAJE ES PARA QUIEN ESTÁ DE PIE DELANTE DE UNA CÁMARA, no para un
  -- programador: dice qué hacer, no qué ha fallado. El código FV002 es lo que
  -- el front usa para recargarse solo.
  RAISE EXCEPTION
    'Esta versión de Folvy es antigua y ya no puede guardar recuentos. Cierra la aplicación y vuelve a abrirla para actualizarla; lo que hayas contado no se ha perdido, vuelve a apuntarlo cuando se actualice.'
    USING ERRCODE = 'FV002',
          DETAIL  = format('inventory_count_line %s: escritura de counted_qty fuera de save_count_line (op %s).', NEW.id, TG_OP),
          HINT    = 'Toda escritura de counted_qty pasa por save_count_line o clear_count_line (§2.2, incidente del 10/09/2026).';
END;
$$;


--
-- Name: FUNCTION tg_count_line_solo_por_la_puerta(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_count_line_solo_por_la_puerta() IS 'Rechaza cualquier escritura de counted_qty que no venga sellada por save_count_line o clear_count_line. Error FV002, que el front usa para recargarse. Incidente del 10/09/2026: un móvil con la versión vieja en caché escribió 12 líneas saltándose el freno.';


--
-- Name: tg_dining_table_same_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_dining_table_same_location() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_z dining_zone;
begin
  select * into v_z from dining_zone where id = new.zone_id;
  if v_z.id is null or v_z.location_id <> new.location_id or v_z.account_id <> new.account_id then
    raise exception 'La zona no es de este local.';
  end if;
  new.updated_at := now();
  return new;
end $$;


--
-- Name: tg_ensure_public_token(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_ensure_public_token() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF new.service_type = 'own_delivery'
     AND (new.public_token IS NULL OR new.public_token = '') THEN
     new.public_token := replace(gen_random_uuid()::text, '-', '');
  END IF;
  RETURN new;
END;
$$;


--
-- Name: tg_fichaje_fuera_del_radio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_fichaje_fuera_del_radio() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_previos integer := 0; v_nombre text; v_local text; v_radio integer; v_loc uuid; v_tipo text;
begin
  begin
    if new.lat is not null and new.lng is not null then
      select count(*) into v_previos from public.clock_entries p
       where p.employee_id = new.employee_id and p.id <> new.id and not p.voided
         and p.within_radius = false and p.lat is not null and p.lng is not null
         and p.datetime between new.datetime - interval '30 days' and new.datetime
         and public._metros(new.lat, new.lng, p.lat, p.lng) <= 200;
    end if;
    if v_previos >= 3 then
      return null;   -- habitual: está en «Fuera del radio» de Equipo, pero no interrumpe
    end if;
    select e.name, coalesce(new.location_id_at_clock, e.location_id) into v_nombre, v_loc
      from public.employees e where e.id = new.employee_id;
    select l.name, l.clock_radius_m into v_local, v_radio from public.locations l where l.id = v_loc;
    v_tipo := case new.type when 'entrada' then 'la entrada' when 'salida' then 'la salida'
                            when 'pausa_inicio' then 'el inicio de la pausa' when 'pausa_fin' then 'el fin de la pausa' else 'un fichaje' end;
    insert into public.aviso_empresa(account_id, location_id, employee_id, clock_entry_id, tipo, clave, titulo, texto)
    values (new.account_id, v_loc, new.employee_id, new.id, 'fuera_del_radio', 'fuera_del_radio:' || new.id,
            format('%s fichó fuera del radio de %s', coalesce(v_nombre, 'Una persona'), coalesce(v_local, 'su local')),
            format('%s fichó %s el %s a las %s a %s de %s (el radio es de %s m). Si fue a propósito (un recado, un evento), no hace falta nada; si no, revísalo en Equipo › Para revisar.',
                   coalesce(v_nombre, 'Una persona'), v_tipo,
                   to_char(new.datetime at time zone 'Europe/Madrid', 'DD/MM'),
                   to_char(new.datetime at time zone 'Europe/Madrid', 'HH24:MI'),
                   case when new.distance_m is null then 'una distancia que no se pudo medir'
                        when new.distance_m >= 1000 then replace(to_char(new.distance_m / 1000.0, 'FM990.0'), '.', ',') || ' km'
                        else new.distance_m || ' m' end,
                   coalesce(v_local, 'su local'), coalesce(v_radio, 200)))
    on conflict (clave) do nothing;
  exception when others then
    begin
      perform public._queue_system_alert('fichaje_fuera_del_radio', 'Fuera del radio: no se pudo crear el aviso',
        format('El fichaje %s cayó fuera del radio y no se pudo avisar al encargado: %s', new.id, sqlerrm),
        'fichaje_fuera_del_radio', interval '6 hours');
    exception when others then null;
    end;
  end;
  return null;
end $$;


--
-- Name: tg_goods_receipt_compras_camino(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_goods_receipt_compras_camino() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'confirmado' or (new.status = 'anulado' and exists (select 1 from goods_receipt_path where goods_receipt_id = new.id)) then
    begin
      perform public._compras_camino_guarda(new.id);
    exception when others then
      begin
        insert into goods_receipt_path (account_id, goods_receipt_id, path, supplier_id, question, reason, error)
        values (new.account_id, new.id, 'error', new.supplier_id, 'error', 'Folvy no pudo decidir por dónde va esta recepción.', sqlerrm)
        on conflict (goods_receipt_id) do update set path = 'error', question = 'error', reason = excluded.reason, error = excluded.error, decided_at = now()
          where goods_receipt_path.consumed_at is null;
      exception when others then
        raise warning 'compras: no se pudo apuntar el camino de la recepción %: %', new.id, sqlerrm;
      end;
    end;
  end if;
  return null;
end $$;


--
-- Name: tg_goods_receipt_line_trust(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_goods_receipt_line_trust() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_loc uuid;
BEGIN
  IF NEW.discrepancy_reason IS NOT DISTINCT FROM OLD.discrepancy_reason THEN
    RETURN NEW;
  END IF;
  SELECT location_id INTO v_loc FROM public.goods_receipt WHERE id = NEW.goods_receipt_id;
  IF v_loc IS NOT NULL THEN
    PERFORM public.refresh_location_receipt_trust(v_loc);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_goods_receipt_path_factura(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_goods_receipt_path_factura() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare g goods_receipt; v jsonb; v_corte date;
begin
  if current_setting('folvy.compras_factura', true) = 'si' then return null; end if;
  if new.path <> 'factura' or new.supplier_invoice_id is not null or new.consumed_at is not null then
    return null;
  end if;
  -- S01c: con una pregunta abierta (la ficha y el papel no dicen lo mismo, o la ficha
  -- no dice cómo factura) no se crea nada. Al cerrarla, este mismo disparador la crea.
  -- (Cerrar una pregunta copia su nombre en question_closed: compras_cerrar_pregunta.)
  if new.question is not null and new.question_closed is distinct from new.question then return null; end if;
  select * into g from goods_receipt where id = new.goods_receipt_id;
  if g.status <> 'confirmado' or g.ai_session_id is null then return null; end if;
  select max(fy.imported_until) into v_corte from fiscal_year fy where fy.company_id = new.company_id;
  perform set_config('folvy.compras_factura', 'si', true);
  if v_corte is not null and g.receipt_date <= v_corte then
    update goods_receipt_path set reason = reason || format(' Es anterior al corte (%s): la lleva el programa anterior.', to_char(v_corte, 'DD/MM/YYYY'))
     where id = new.id and reason not like '%anterior al corte%';
  else
    begin
      v := public._compras_factura_desde_papel(g.account_id, g.ai_session_id, g.supplier_id, g.location_id, new.company_id, g.id, null);
      if coalesce((v->>'sin_importes')::boolean, false) then
        update goods_receipt_path set question = 'factura_sin_importes', question_detail = jsonb_build_object('motivo', v->>'motivo')
         where id = new.id;
      else
        update goods_receipt_path set supplier_invoice_id = (v->>'factura')::uuid, consumed_at = now(),
               question = case when coalesce((v->>'repetida')::boolean, false) then 'factura_repetida' else question end,
               question_detail = case when coalesce((v->>'repetida')::boolean, false)
                                      then jsonb_build_object('motivo', v->>'motivo', 'factura', v->>'factura') else question_detail end
         where id = new.id;
      end if;
    exception when others then
      perform set_config('folvy.compras_factura', 'si', true);
      update goods_receipt_path set question = 'error', error = sqlerrm,
             question_detail = jsonb_build_object('motivo', 'Folvy no pudo crear la factura desde el documento.')
       where id = new.id;
    end;
  end if;
  perform set_config('folvy.compras_factura', '', true);
  return null;
end $$;


--
-- Name: tg_goods_receipt_recompute_average(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_goods_receipt_recompute_average() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item uuid;
begin
  if tg_table_name = 'goods_receipt' then
    for v_item in
      select distinct grl.recipe_item_id
        from goods_receipt_line grl
        join recipe_item ri on ri.id = grl.recipe_item_id and ri.account_id = new.account_id
       where grl.goods_receipt_id = new.id
         and ri.cost_strategy = 'average_weighted'
    loop
      perform public._kitchen_recompute_raw_cost_unguarded(v_item);
    end loop;
  else
    if not exists (select 1 from goods_receipt gr
                    where gr.id = new.goods_receipt_id
                      and gr.status in ('recibido', 'confirmado')) then
      return null;
    end if;
    for v_item in
      select ri.id from recipe_item ri
       where ri.id in (new.recipe_item_id, old.recipe_item_id)
         and ri.account_id = new.account_id
         and ri.cost_strategy = 'average_weighted'
    loop
      perform public._kitchen_recompute_raw_cost_unguarded(v_item);
    end loop;
  end if;
  return null;
end;
$$;


--
-- Name: tg_inventory_count_line_sanity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_inventory_count_line_sanity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_factor  numeric;
  v_cap     numeric;
  v_teorico numeric;
BEGIN
  IF NEW.counted_qty IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.counted_qty IS NOT DISTINCT FROM OLD.counted_qty THEN
    RETURN NEW;
  END IF;

  IF NEW.counted_qty < 0 THEN
    RAISE EXCEPTION 'No se puede contar una cantidad negativa (%). Si el sistema esta en negativo, cuenta lo que hay de verdad: 0 o mas.',
      NEW.counted_qty USING ERRCODE = 'FV001';
  END IF;

  -- Confirmacion explicita: vale SOLO para el valor confirmado.
  IF NEW.counted_qty_confirmed IS NOT NULL
     AND NEW.counted_qty_confirmed = NEW.counted_qty THEN
    NEW.counted_qty_confirmed_at := now();
    RETURN NEW;
  END IF;

  SELECT COALESCE(count_absurd_factor, 1000), COALESCE(count_absurd_abs_cap, 1000000)
    INTO v_factor, v_cap
    FROM public.supply_settings WHERE account_id = NEW.account_id;
  v_factor := COALESCE(v_factor, 1000);
  v_cap    := COALESCE(v_cap, 1000000);

  v_teorico := NEW.system_qty;

  IF v_teorico IS NOT NULL AND v_teorico > 0 THEN
    IF NEW.counted_qty > v_factor * v_teorico THEN
      RAISE EXCEPTION
        'Cantidad fuera de escala: has puesto % y el sistema tiene %. Son % veces mas. Revisa la unidad y las comas; si de verdad has contado eso, confirmalo.',
        trim(to_char(NEW.counted_qty, 'FM999999999999999990.####')),
        trim(to_char(v_teorico,       'FM999999999999999990.####')),
        trim(to_char(round(NEW.counted_qty / v_teorico), 'FM999999999999999990'))
        USING ERRCODE = 'FV001';
    END IF;

    -- ── NUEVO 10/09: la misma red, por debajo ─────────────────────────────
    -- El cero queda fuera: es una respuesta, no un error de dedo.
    IF NEW.counted_qty > 0 AND NEW.counted_qty * v_factor < v_teorico THEN
      RAISE EXCEPTION
        'Cantidad fuera de escala: has puesto % y el sistema tiene %. Son % veces menos. ¿Estas contando en la unidad que te pide (cajas en vez de gramos)? Si de verdad has contado eso, confirmalo; si no queda nada, marca «no queda nada de este producto».',
        trim(to_char(NEW.counted_qty, 'FM999999999999999990.####')),
        trim(to_char(v_teorico,       'FM999999999999999990.####')),
        trim(to_char(round(v_teorico / NEW.counted_qty), 'FM999999999999999990'))
        USING ERRCODE = 'FV001';
    END IF;
  ELSE
    IF NEW.counted_qty > v_cap THEN
      RAISE EXCEPTION
        'Cantidad fuera de escala: has puesto % en unidades base, por encima del tope de %. Revisa la unidad y las comas; si de verdad has contado eso, confirmalo.',
        trim(to_char(NEW.counted_qty, 'FM999999999999999990.####')),
        trim(to_char(v_cap,           'FM999999999999999990'))
        USING ERRCODE = 'FV001';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


