-- Name: tg_journal_entry_liquidacion_anulada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_journal_entry_liquidacion_anulada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
  select t.id, t.account_id, t.company_id, auth.uid(), public.conta_impuesto_quien(), 'note',
         'Se anuló el asiento de liquidación' || coalesce(' ' || new.series || '/' || new.number, '') || ': ' || coalesce(new.void_reason, 'sin motivo') ||
         case when t.status in ('booked', 'offset') then '. Vuelve a «Presentado».' else '.' end,
         jsonb_build_object('asiento', new.id)
    from public.tax_return t where t.liquidation_entry_id = new.id;
  update public.tax_return
     set status = case when status in ('booked', 'offset') then 'filed' else status end, liquidation_entry_id = null, updated_at = now()
   where liquidation_entry_id = new.id;
  return new;
end $$;


--
-- Name: tg_journal_entry_pago_modelo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_journal_entry_pago_modelo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v jsonb;
begin
  if new.status <> 'validado' or old.status = 'validado' then return null; end if;
  for r in select distinct l.withholding_model m, l.withholding_period p from journal_line l
            where l.entry_id = new.id and l.withholding_period is not null and l.withholding_rate_id is null loop
    v := public.conta_modelo_pagado(new.company_id, r.m, r.p);
    if (v->>'declaracion') is not null and (v->>'pendiente')::numeric <= 0 and (v->>'asiento_pago') is null then
      -- Lo mismo que «Casar el cargo» de Impuestos: pagada, con su asiento y, si vino del banco, su casado.
      update tax_return t set payment_entry_id = new.id,
             status = case when t.status in ('filed', 'booked') then 'paid' else t.status end,
             bank_match_id = coalesce(t.bank_match_id, (select m.id from bank_match m where m.journal_entry_id = new.id and m.status = 'vivo' limit 1)),
             updated_at = now()
       where t.id = (v->>'declaracion')::uuid and t.payment_entry_id is null;
      insert into tax_return_event (tax_return_id, account_id, company_id, by_user, by_name, kind, message, detail)
      values ((v->>'declaracion')::uuid, new.account_id, new.company_id, auth.uid(), coalesce(new.validated_by_name, 'Sumied'), 'note',
              format('Pagado: lo dice el asiento %s/%s del %s (%s).', new.series, new.number, to_char(new.entry_date, 'DD/MM/YYYY'), v->>'texto'),
              jsonb_build_object('asiento', new.id, 'pagado', v->'pagado'));
    end if;
  end loop;
  return null;
end $$;


--
-- Name: tg_menu_item_inherit_stock_group(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_menu_item_inherit_stock_group() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_group uuid;
begin
  if new.stock_group_id is null and new.external_id is not null then
    select mi.stock_group_id into v_group
    from menu_item mi
    where mi.account_id = new.account_id
      and mi.external_id = new.external_id
      and mi.stock_group_id is not null
      and mi.archived_at is null
      and mi.id <> new.id
    limit 1;

    if v_group is not null then
      new.stock_group_id := v_group;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: tg_menu_item_override_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_menu_item_override_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();   -- null si escribe un proceso sin JWT
  v_op    uuid := nullif(current_setting('folvy.operation_id', true), '')::uuid;
begin
  if tg_op = 'INSERT' then
    insert into menu_item_override_history (
      account_id, menu_item_id, location_id, channel_id, op,
      price_before, price_after, is_available_before, is_available_after, changed_by, operation_id)
    values (
      new.account_id, new.menu_item_id, new.location_id, new.channel_id, 'insert',
      null, new.price, null, new.is_available, v_actor, v_op);

  elsif tg_op = 'UPDATE' then
    if (new.price IS DISTINCT FROM old.price)
       or (new.is_available IS DISTINCT FROM old.is_available) then
      insert into menu_item_override_history (
        account_id, menu_item_id, location_id, channel_id, op,
        price_before, price_after, is_available_before, is_available_after, changed_by, operation_id)
      values (
        new.account_id, new.menu_item_id, new.location_id, new.channel_id, 'update',
        old.price, new.price, old.is_available, new.is_available, v_actor, v_op);
    end if;

  else -- DELETE
    insert into menu_item_override_history (
      account_id, menu_item_id, location_id, channel_id, op,
      price_before, price_after, is_available_before, is_available_after, changed_by, operation_id)
    values (
      old.account_id, old.menu_item_id, old.location_id, old.channel_id, 'delete',
      old.price, null, old.is_available, null, v_actor, v_op);
  end if;

  return null;  -- AFTER trigger: el valor de retorno se ignora
end;
$$;


