--
-- Name: tg_mirror_delivery_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_mirror_delivery_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state text;
  v_name  text;
  v_phone text;
  v_veh   text;
BEGIN
  v_state := CASE NEW.state
    WHEN 'offered'     THEN 'matching'
    WHEN 'accepted'    THEN 'matched'
    WHEN 'picked_up'   THEN 'in_delivery'
    WHEN 'in_delivery' THEN 'in_delivery'
    WHEN 'delivered'   THEN 'delivered'
    WHEN 'failed'      THEN 'failed'
    WHEN 'canceled'    THEN 'canceled'
    ELSE NEW.state
  END;

  IF NEW.courier_id IS NOT NULL THEN
    SELECT c.name, c.phone, c.transport_type
      INTO v_name, v_phone, v_veh
      FROM public.courier c WHERE c.id = NEW.courier_id;
  END IF;

  UPDATE public.sale s SET
    carrier_code       = 'own_fleet',
    delivery_state     = v_state,
    order_status       = CASE
                           WHEN NEW.state IN ('failed','canceled')
                                AND s.order_status NOT IN ('cancelled','rejected','delivery_failed')
                           THEN 'delivery_failed'
                           ELSE s.order_status
                         END,
    rider_name         = COALESCE(v_name, s.rider_name),
    rider_phone        = COALESCE(v_phone, s.rider_phone),
    rider_transport_type = COALESCE(v_veh, s.rider_transport_type),
    has_courier        = (NEW.courier_id IS NOT NULL),
    transport_price    = COALESCE(NEW.transport_price, s.transport_price),
    dispatch_error     = NULL
  WHERE s.id = NEW.sale_id;

  RETURN NEW;
END;
$$;


--
-- Name: tg_modifier_option_retiro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_modifier_option_retiro() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se apaga: se sella cuando y quien. Si el llamador ya dijo quien --A2c dice
  -- 'last'-- se respeta; si no, fue una persona desde la pantalla.
  IF OLD.is_active AND NOT NEW.is_active THEN
    NEW.deactivated_at := COALESCE(NEW.deactivated_at, now());
    NEW.deactivated_by := COALESCE(NEW.deactivated_by, 'persona');
    -- Y se limpia la marca de reencendido: una opcion APAGADA no puede estar
    -- diciendo «te la volvieron a encender». Eso ya no es verdad.
    NEW.reencendida_at    := NULL;
    NEW.reencendida_sobre := NULL;

  -- Se enciende: el sello de apagado se borra. Una opcion encendida con fecha
  -- de retiro seria una fila que se contradice a si misma.
  ELSIF NOT OLD.is_active AND NEW.is_active THEN
    -- 🔴 PERO SI LA APAGO UNA PERSONA Y LA ENCIENDE EL IMPORTADOR, ESO NO SE
    -- BORRA (14/09). Hasta hoy se borraba, y con ello la unica prueba de que
    -- alguien habia decidido algo: la pasada de madrugada deshacia una
    -- decision y no quedaba rastro en ningun sitio.
    --
    -- Quien la enciende lo dice poniendo `reencendida_sobre`; A2c lo pone, y
    -- solo para las que apago una persona. Si nadie lo dice, la esta
    -- encendiendo una persona --por la pantalla-- y entonces no hay nada que
    -- contar: la marca se limpia.
    IF NEW.reencendida_sobre IS NOT NULL THEN
      NEW.reencendida_at := COALESCE(NEW.reencendida_at, now());
    ELSE
      NEW.reencendida_at    := NULL;
      NEW.reencendida_sobre := NULL;
    END IF;
    NEW.deactivated_at := NULL;
    NEW.deactivated_by := NULL;
  END IF;
  RETURN NEW;
END;
$$;


