--
-- Name: FUNCTION tg_sale_close_on_complete(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_sale_close_on_complete() IS 'A6: sella la venta (close_sale) cuando order_status pasa a completed. Solo UPDATE, a proposito — ver cabecera de la migracion 20260903 trg_sale_close_on_complete.';


--
-- Name: tg_sale_consumption_on_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_consumption_on_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- 0) ANULACION (nuevo): la venta deja de ser valida -> devolver el stock.
  --    Salvo el cierre del dia (16/10): un pedido cerrado como no confirmado
  --    (unconfirmed_at) no se anula: lo cocinado, cocinado esta.
  if tg_op = 'UPDATE'
     and new.unconfirmed_at is null
     and ( coalesce(new.status,'') = 'cancelled'
           or coalesce(new.order_status,'') in ('cancelled','rejected')
           or not coalesce(new.is_active, true) )
     and ( coalesce(old.status,'')       is distinct from coalesce(new.status,'')
           or coalesce(old.order_status,'') is distinct from coalesce(new.order_status,'')
           or coalesce(old.is_active,true) is distinct from coalesce(new.is_active,true) ) then
    perform public.generate_sale_consumption(new.id);
    return new;
  end if;

  -- 1) AL ENTRAR / ACEPTARSE la venta: descuenta ya.
  if new.order_status in ('accepted','received','new','completed')
     and (tg_op = 'INSERT' or old.order_status is distinct from new.order_status)
     and coalesce(new.status,'') <> 'cancelled'
     and coalesce(new.is_active, true) then
    perform public.generate_sale_consumption(new.id);
  end if;

  return new;
end;
$$;


--
-- Name: tg_sale_delivery_alarm(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_delivery_alarm() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.delivery_state is distinct from old.delivery_state
     and new.delivery_state in ('failed', 'canceled', 'cancelled') then
    new.delivery_alarm_at     := now();
    new.delivery_alarm_kind   := new.delivery_state;
    new.delivery_alarm_ack_at := null;
  end if;
  return new;
end;
$$;


--
-- Name: tg_sale_entrega_desde_raw(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_entrega_desde_raw() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare r record;
begin
  if new.source not in ('lastapp', 'hubrise') then return new; end if;
  begin
    select * into r from public.sale_entrega_desde_raw(new.source, new.raw_tab);
    new.customer_phone_code   := r.customer_phone_code;
    new.delivery_instructions := r.delivery_instructions;
    new.order_customer_note   := r.order_customer_note;
  exception when others then
    -- Un pedido nunca se cae por esto.
    raise warning 'tg_sale_entrega_desde_raw: % (venta %)', sqlstate, new.id;
  end;
  return new;
end;
$$;


--
-- Name: tg_sale_line_consumption(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_line_consumption() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale_id uuid; v_sale record; v_n integer; v_state text; v_msg text; v_marca text;
begin
  v_sale_id := new.sale_id;
  if v_sale_id is null then return new; end if;

  -- En UPDATE se mantiene el alcance de antes: solo cuando cambia menu_item_id.
  -- En INSERT entra cualquier line_type (ese es el arreglo).
  if tg_op = 'UPDATE' and new.menu_item_id is not distinct from old.menu_item_id then
    return new;
  end if;

  -- Una sola vez por venta y por transaccion.
  v_marca := 'folvy.consumo_' || replace(v_sale_id::text, '-', '');
  if coalesce(current_setting(v_marca, true), '') = '1' then
    return new;
  end if;

  select id, status, order_status, is_active into v_sale
    from public.sale where id = v_sale_id;
  if not found then return new; end if;

  -- No consumir ventas canceladas ni inactivas.
  if coalesce(v_sale.status,'') = 'cancelled'
     or coalesce(v_sale.order_status,'') in ('cancelled','rejected')
     or not coalesce(v_sale.is_active, true) then
    return new;
  end if;

  perform set_config(v_marca, '1', true);

  v_n := public.generate_sale_consumption(v_sale_id);
  perform public._resolver_fallo_de_consumo(v_sale_id, v_n);
  return new;

exception when others then
  -- No tumbamos la ingesta, pero el fallo deja FILA y ALERTA.
  v_state := sqlstate;
  v_msg   := sqlerrm;
  begin
    perform public._registrar_fallo_de_consumo(v_sale_id, v_state, v_msg);
  exception when others then
    raise warning 'tg_sale_line_consumption: no se pudo apuntar el fallo de la venta % : %',
      v_sale_id, sqlerrm;
  end;
  raise warning 'tg_sale_line_consumption: venta % : %', v_sale_id, v_msg;
  return new;
end;
$$;


--
-- Name: tg_sale_seal_delivered(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_seal_delivered() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.delivery_state is distinct from old.delivery_state
     and new.delivery_state in ('delivered','finish')
     and new.delivered_at is null then
    new.delivered_at := now();
  end if;
  return new;
end;
$$;


--
-- Name: tg_sale_seal_handed_to_courier(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_seal_handed_to_courier() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.delivery_state is distinct from old.delivery_state
     and new.delivery_state = 'in_delivery'
     and new.handed_to_courier_at is null then
    new.handed_to_courier_at := now();
  end if;
  return new;
end;
$$;


--
-- Name: tg_sale_seal_kpi_hitos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_seal_kpi_hitos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.accepted_at is null then
      new.accepted_at := now();
    end if;
    return new;
  end if;
  if new.order_status is distinct from old.order_status then
    if new.accepted_at is null
       and new.order_status in ('received','accepted','in_preparation') then
      new.accepted_at := now();
    end if;
    if new.ready_at is null
       and new.order_status in ('awaiting_collection','awaiting_shipment','in_delivery') then
      new.ready_at := now();
    end if;
  end if;
  -- EL PASE (15/09/2026): reabrir borra el sello. Ver la nota de la
  -- migración; sin esto un pedido reabierto no vuelve al tablero de cocina.
  if new.order_status in ('new','received','accepted','in_preparation')
     and old.order_status is distinct from new.order_status
     and new.ready_at is not null then
    new.ready_at := null;
  end if;
  return new;
end;
$$;


--
-- Name: tg_sale_service_type_por_interruptor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_service_type_por_interruptor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_slug       text;
  v_by         text;
  v_recalcular boolean;
begin
  -- Solo los pedidos que llegan de las plataformas. La tienda propia, el TPV
  -- y lo manual deciden su modalidad ellos mismos (hoy: 22 + 3 + 2 ventas).
  if coalesce(new.source, '') not in ('hubrise', 'lastapp') then return new; end if;
  if new.brand_id is null then return new; end if;
  -- Solo la modalidad de reparto. Recogida y en local no se tocan.
  if new.service_type is null or new.service_type not in ('own_delivery', 'platform_delivery') then
    return new;
  end if;

  -- Una vuelta atrás que devuelve a un pedido la modalidad que tenía la pone
  -- tal cual (supabase/vuelta-atras/20261005T0210…down.sql). Nadie más la usa.
  if coalesce(current_setting('folvy.reparto_tal_cual', true), '') = 'on' then return new; end if;

  if tg_op = 'UPDATE' then
    -- Los webhooks reescriben el pedido en cada cambio de estado y mandan otra
    -- vez su modalidad. Un pedido ya abierto conserva la que se le puso al
    -- entrar, salvo que:
    --   · hasta ahora no se pudiera resolver (sin marca o sin canal), o
    --   · alguien lo pida a propósito en esta transacción
    --     (reparto_cambiar_celda_desde_pedido o el saneado del despliegue).
    v_recalcular :=
         old.service_type is null
      or old.service_type not in ('own_delivery', 'platform_delivery')
      or old.brand_id is null
      or old.channel_id is distinct from new.channel_id
      or coalesce(current_setting('folvy.reparto_recalcular', true), '') = 'on';
    if not v_recalcular then
      new.service_type := old.service_type;
      return new;
    end if;
  end if;

  select sc.slug into v_slug
    from public.sales_channel sc
   where sc.id = new.channel_id and sc.account_id = new.account_id;
  if coalesce(btrim(v_slug), '') = '' then return new; end if;   -- sin canal: como llegue

  select r.delivery_by into v_by
    from public.resolve_delivery_by(new.account_id, new.brand_id, v_slug, new.location_id) r;

  new.service_type := case when v_by = 'own' then 'own_delivery' else 'platform_delivery' end;
  return new;
end;
$$;


--
-- Name: FUNCTION tg_sale_service_type_por_interruptor(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_sale_service_type_por_interruptor() IS 'R02 · Pone el service_type de reparto (own_delivery / platform_delivery) de los pedidos de HubRise y Last con resolve_delivery_by al ENTRAR. Un pedido abierto conserva el suyo. El nombre es el de antes para no renombrar un objeto de Cocina; ya no lee ningún interruptor.';


--
-- Name: tg_sale_uber_quien_reparte(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sale_uber_quien_reparte() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare r record;
begin
  if new.source is distinct from 'hubrise' then return new; end if;
  if new.service_type is null or new.service_type not in ('own_delivery', 'platform_delivery') then return new; end if;
  if lower(coalesce(new.external_channel_text, '')) not like '%uber%' then return new; end if;
  if coalesce(current_setting('folvy.reparto_tal_cual', true), '') = 'on' then return new; end if;
  if new.carrier_order_id is not null then return new; end if;
  if new.delivery_by_reason in ('decidido_propio', 'decidido_uber') then return new; end if;
  begin
    select * into r from public.uber_senales_de_reparto(new.raw_tab);
    if r.calle is null then return new; end if;  -- ilegible: se queda como está
    if r.calle and r.coordenadas and r.cargo_envio then
      new.service_type := 'own_delivery';
      new.delivery_by_reason := null;
    elsif not r.calle and not r.coordenadas and not r.cargo_envio then
      new.service_type := 'platform_delivery';
      new.delivery_by_reason := 'fuera_de_zona';
    else
      new.service_type := 'own_delivery';
      new.delivery_by_reason := 'uber_decidir';
    end if;
  exception when others then
    raise warning 'tg_sale_uber_quien_reparte: % (venta %)', sqlstate, new.id;
  end;
  return new;
end;
$$;


--
-- Name: tg_sales_hourly_agg_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sales_hourly_agg_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_sale record; v_kind text; v_day date; v_hour smallint;
begin
  select s.account_id, s.location_id, s.sold_at, coalesce(s.is_active,true) as act
    into v_sale from public.sale s
   where s.id = coalesce(new.sale_id, old.sale_id);
  if v_sale is null or v_sale.sold_at is null then return coalesce(new, old); end if;

  select coalesce(mc.demand_kind,'otro') into v_kind
  from public.menu_item mi join public.menu_category mc on mc.id = mi.menu_category_id
  where mi.id = coalesce(new.menu_item_id, old.menu_item_id);
  if v_kind is null then return coalesce(new, old); end if;

  v_day  := (v_sale.sold_at at time zone 'Europe/Madrid')::date;
  v_hour := extract(hour from (v_sale.sold_at at time zone 'Europe/Madrid'))::smallint;

  -- recalcular esa celda concreta desde la fuente (evita derivas por sumas incrementales)
  delete from public.sales_hourly_agg
   where account_id=v_sale.account_id and location_id=v_sale.location_id
     and day=v_day and hour=v_hour and demand_kind=v_kind;

  insert into public.sales_hourly_agg (account_id, location_id, day, hour, demand_kind, units, tickets)
  select s.account_id, s.location_id, v_day, v_hour, v_kind,
         coalesce(sum(sl.quantity),0), count(distinct s.id)
  from public.sale s
  join public.sale_line sl on sl.sale_id = s.id
  join public.menu_item mi on mi.id = sl.menu_item_id
  join public.menu_category mc on mc.id = mi.menu_category_id
  where s.account_id = v_sale.account_id and s.location_id = v_sale.location_id
    and coalesce(s.is_active, true)
    and coalesce(mc.demand_kind,'otro') = v_kind
    and (s.sold_at at time zone 'Europe/Madrid')::date = v_day
    and extract(hour from (s.sold_at at time zone 'Europe/Madrid'))::smallint = v_hour
  group by s.account_id, s.location_id
  having coalesce(sum(sl.quantity),0) > 0;

  return coalesce(new, old);
end $$;


--
-- Name: tg_schedule_reject_vacation_conflicts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_schedule_reject_vacation_conflicts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tpl text; v_day text; v_emp text; v_date date;
  v_conflicts text := '';
begin
  if new.cells is null or new.cells = '{}'::jsonb then
    return new;
  end if;
  for v_tpl in select jsonb_object_keys(new.cells) loop
    for v_day in select jsonb_object_keys(new.cells -> v_tpl) loop
      begin
        v_date := new.week_start + (v_day)::int;
      exception when others then
        continue;
      end;
      for v_emp in select jsonb_array_elements_text(new.cells -> v_tpl -> v_day) loop
        if exists (
          select 1 from vacations v
          where v.employee_id = v_emp::uuid
            and v.status = 'aprobada'
            and v_date between v.start_date and v.end_date
        ) then
          v_conflicts := v_conflicts
            || coalesce((select e.name from employees e where e.id = v_emp::uuid), v_emp)
            || ' el ' || to_char(v_date, 'DD/MM/YYYY') || '; ';
        end if;
      end loop;
    end loop;
  end loop;
  if v_conflicts <> '' then
    raise exception 'CUADRANTE_CON_VACACIONES: %', v_conflicts
      using hint = 'Hay empleados asignados en dias de vacaciones aprobadas. Quitalos de esos dias antes de guardar.';
  end if;
  return new;
end $$;


