--
-- Name: theoretical_qty_at(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.theoretical_qty_at(p_recipe_item_id uuid, p_location_id uuid, p_at timestamp with time zone) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT SUM(sm.qty_base)
      FROM public.stock_movement sm
     WHERE sm.recipe_item_id = p_recipe_item_id
       AND sm.location_id    = p_location_id
       AND sm.occurred_at    < p_at
  ), 0)::numeric;
$$;


--
-- Name: ticket_invoice_ajustes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ticket_invoice_ajustes(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_a public.accounts; v_year integer := extract(year from (now() at time zone 'Europe/Madrid'))::integer;
begin
  if p_account is null or not public.belongs_to_account(p_account) then raise exception 'No eres de esta cuenta.' using errcode = '42501'; end if;
  select * into v_a from public.accounts where id = p_account;
  return jsonb_build_object(
    'año', v_year,
    -- Sin el fabricante de Sumied no se pasa a real (verifactu_modo): se avisa aquí.
    'fabricante_falta', not public.verifactu_sistema_completo(),
    'empresas', (select coalesce(jsonb_agg(jsonb_build_object('company_id', c.id, 'nombre', coalesce(c.legal_name, c.trade_name),
                    'nif', c.tax_id, 'verifactu', coalesce(e.modo, 'apagado'), 'real_desde', e.real_desde,
                    'conexion_probada', coalesce(public.verifactu_conexion_probada(case when e.modo = 'real' then 'real' else 'pruebas' end,
                                                   regexp_replace(upper(coalesce(c.tax_id, '')), '^ES', '')), false))
                    order by coalesce(c.legal_name, c.trade_name)), '[]'::jsonb)
                   from public.company c left join public.verifactu_empresa e on e.company_id = c.id
                  where c.account_id = p_account and coalesce(c.is_active, true)),
    'locales', (select coalesce(jsonb_agg(jsonb_build_object('location_id', l.id, 'nombre', l.name, 'activo', l.active,
                    'codigo', lic.code, 'propuesto', public._ticket_codigo_propuesto(l.name, v_a.name),
                    'empresa', (select coalesce(c.legal_name, c.trade_name) from public.location_company lc join public.company c on c.id = lc.company_id
                                 where lc.location_id = l.id and lc.account_id = p_account),
                    'tramo', x.tramo,
                    'serie', case when lic.code is not null then public._ticket_numero_texto(lic.code, v_year, x.tramo, 'F', 1) end,
                    'ultimo', (select last_number from public.ticket_invoice_series s where s.account_id = p_account and s.location_id = l.id
                                 and s.year = v_year and s.kind = 'F' and s.tramo is not distinct from x.tramo),
                    'ultimo_at', (select max(t.issued_at) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id and t.kind = 'F'),
                    'rectificativas', case when lic.code is not null then public._ticket_numero_texto(lic.code, v_year, x.tramo_r, 'R', 1) end,
                    'ultimo_r', (select last_number from public.ticket_invoice_series s where s.account_id = p_account and s.location_id = l.id
                                   and s.year = v_year and s.kind = 'R' and s.tramo is not distinct from x.tramo_r),
                    'numeros', (select count(*) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id),
                    'verifactu_pendientes', (select count(*) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id
                                               and t.verifactu_estado in ('pendiente', 'anulacion_pendiente')))
                    order by l.active desc, l.name), '[]'::jsonb)
                  from public.locations l left join public.location_invoice_code lic on lic.location_id = l.id and lic.account_id = p_account
                  cross join lateral (select public._ticket_tramo(p_account, l.id, v_year, 'F') as tramo,
                                             public._ticket_tramo(p_account, l.id, v_year, 'R') as tramo_r) x
                 where l.account_id = p_account),
    'marcas', (select coalesce(jsonb_agg(jsonb_build_object('brand_id', b.id, 'nombre', b.name, 'propia', coalesce(b.ownership_type, 'own') <> 'licensed',
                    -- F01: quién emite la de una cedida, de su ficha (brand_licensing_agreement);
                    -- si no lo tiene, como antes, la factura de su último pedido de Last (30 días).
                    'emisor', case when b.ownership_type = 'licensed' then coalesce(
                       (select nullif(btrim(a.owner_name), '') from public.brand_licensing_agreement a
                         where a.account_id = p_account and a.brand_id = b.id and a.is_active and a.archived_at is null),
                       (select public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' from public.sale s
                         where s.account_id = p_account and s.brand_id = b.id and s.sold_at > now() - interval '30 days'
                           and public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' is not null
                         order by s.sold_at desc limit 1)) end,
                    'emisor_de', case when b.ownership_type = 'licensed' then
                       case when exists (select 1 from public.brand_licensing_agreement a where a.account_id = p_account and a.brand_id = b.id
                                           and a.is_active and a.archived_at is null and nullif(btrim(a.owner_name), '') is not null)
                            then 'ficha' else 'factura' end end)
                    order by (coalesce(b.ownership_type, 'own') = 'licensed'), b.name), '[]'::jsonb)
                 from public.brand b where b.account_id = p_account and b.is_active and b.archived_at is null),
    -- Pedidos de cedidas de los últimos 7 días sin la factura de Last (sus tiques salen sin la línea).
    'cedidas_sin_factura_7d', (select count(*) from public.sale s join public.brand b on b.id = s.brand_id and b.account_id = s.account_id
                                 where s.account_id = p_account and b.ownership_type = 'licensed' and s.sold_at > now() - interval '7 days'
                                   and nullif(btrim(public.safe_jsonb(s.raw_tab)->'bills'->0->>'number'), '') is null));
end $$;


--
-- Name: ticket_invoice_code_set(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ticket_invoice_code_set(p_location uuid, p_code text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_l public.locations; v_code text := upper(btrim(coalesce(p_code, ''))); v_ya public.location_invoice_code; v_otro text;
        v_year integer := extract(year from (now() at time zone 'Europe/Madrid'))::integer;
begin
  select * into v_l from public.locations where id = p_location;
  if v_l.id is null or not public.belongs_to_account(v_l.account_id) then raise exception 'Ese local no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_of(v_l.account_id) then
    raise exception 'Solo un administrador de la cuenta elige el código de un local.' using errcode = '42501';
  end if;
  if v_code !~ '^[A-Z]{2,3}$' then raise exception 'El código son 2 o 3 letras, sin acentos ni números (por ejemplo, CA).' using errcode = '23514'; end if;
  select * into v_ya from public.location_invoice_code where location_id = p_location and account_id = v_l.account_id;
  if v_ya.code = v_code then
    return jsonb_build_object('codigo', v_code, 'cambiado', false, 'serie', public._ticket_invoice_text(v_code, v_year, 'F', 1));
  end if;
  if v_ya.code is not null and exists (select 1 from public.ticket_invoice where account_id = v_l.account_id and location_id = p_location) then
    raise exception 'El código de % ya es %, y su serie ya tiene números: no se cambia (cambiarlo partiría la serie).', v_l.name, v_ya.code using errcode = '23514';
  end if;
  select l.name into v_otro from public.location_invoice_code c join public.locations l on l.id = c.location_id
   where c.account_id = v_l.account_id and c.code = v_code and c.location_id <> p_location;
  if v_otro is not null then raise exception 'El código % ya es de %: elige otro.', v_code, v_otro using errcode = '23505'; end if;
  insert into public.location_invoice_code (location_id, account_id, code, set_by, set_by_name)
  values (p_location, v_l.account_id, v_code, auth.uid(), p_quien_nombre)
  on conflict (location_id) do update set code = excluded.code, set_at = now(), set_by = excluded.set_by, set_by_name = excluded.set_by_name;
  return jsonb_build_object('codigo', v_code, 'cambiado', true, 'serie', public._ticket_invoice_text(v_code, v_year, 'F', 1));
end $_$;


--
-- Name: ticket_verifactu_pendientes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ticket_verifactu_pendientes(p_max integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v record; v_bien int := 0; v_mal int := 0;
begin
  for v in select id, account_id, location_id, verifactu_estado, number_text from public.ticket_invoice
            where verifactu_estado in ('pendiente', 'anulacion_pendiente')
            order by issued_at limit greatest(coalesce(p_max, 200), 1) loop
    begin
      if v.verifactu_estado = 'pendiente' then perform public._ticket_verifactu_alta(v.id);
      else perform public._ticket_verifactu_anular(v.id); end if;
      v_bien := v_bien + 1;
    exception when others then
      v_mal := v_mal + 1;
      update public.ticket_invoice set verifactu_error = left(sqlerrm, 500), verifactu_intentos = coalesce(verifactu_intentos, 0) + 1 where id = v.id;
      perform public._ticket_aviso('tique_verifactu_pendiente', 'Hay tiques sin su registro de Verifactu',
        'El tique ' || v.number_text || ' sigue sin su registro de Verifactu (' || left(sqlerrm, 300) || '). Se reintenta cada 5 minutos.',
        'tique_verifactu_pendiente:' || v.account_id::text, interval '6 hours', v.account_id, v.location_id, null, 'alto');
    end;
  end loop;
  return jsonb_build_object('registrados', v_bien, 'siguen', v_mal);
end $$;


--
-- Name: FUNCTION ticket_verifactu_pendientes(p_max integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ticket_verifactu_pendientes(p_max integer) IS 'V04 · PR 2. Cada 5 minutos (cron ticket-verifactu-pendientes): los tiques cuyo registro de Verifactu (alta o anulación) quedó pendiente al imprimir o al cancelar, otra vez. Si siguen, aviso alto (cada 6 h por cuenta).';


--
-- Name: toggle_campaign(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_campaign(p_account uuid, p_id uuid, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing coupon%rowtype;
begin
  if not (p_account = any(current_user_account_ids())) then
    raise exception 'forbidden';
  end if;

  select * into v_existing from coupon where id = p_id and account_id = p_account;
  if v_existing.id is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;

  if coalesce(p_active, false) then
    update coupon set active = true, paused_at = null, updated_at = now() where id = p_id;
  else
    update coupon set active = false, paused_at = now(), updated_at = now() where id = p_id;
  end if;

  return jsonb_build_object('ok', true, 'active', coalesce(p_active, false));
end;
$$;


--
-- Name: track_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_by_token(p_token text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select jsonb_build_object(
      'found', true,
      'stage', case
        when da.state = 'delivered' or s.delivery_state = 'delivered'
             or s.order_status in ('completed','delivered') then 'entregado'
        when da.state = 'failed' or s.delivery_state = 'failed' then 'incidencia'
        when da.state in ('picked_up','in_delivery')
             or s.delivery_state = 'in_delivery' then 'en_camino'
        else 'preparando' end,
      'brand', b.name, 'brand_id', b.id, 'brand_logo', b.logo_url,
      'customer_name', s.customer_name, 'delivery_address', s.delivery_address,
      'rider_name', s.rider_name, 'rider_phone', s.rider_phone, 'rider_transport', s.rider_transport_type,
      'rider_lat', s.rider_lat, 'rider_lng', s.rider_lng, 'rider_seen_at', s.rider_seen_at,
      'eta_delivery', s.eta_delivery,
      'dest_lat', null, 'dest_lng', null,
      'pickup_name', l.name, 'pickup_lat', l.lat, 'pickup_lng', l.lng,
      'pickup_phone', l.phone,
      'shop_slug', a.slug, 'shop_logo', a.shop_logo_url,
      'offer', (
        select jsonb_build_object('code', c.code, 'pct', c.value, 'min_subtotal', c.min_subtotal)
        from public.coupon c
        where c.account_id = s.account_id and c.active and 'shop' = any(c.channels)
          and c.discount_type = 'percent' and c.code is not null
          and coalesce(c.origin,'') <> 'agent'
          and (c.starts_at is null or c.starts_at <= now())
          and (c.ends_at   is null or c.ends_at   >= now())
        order by c.value desc limit 1
      )
    )
    from sale s
    left join brand b on b.id = s.brand_id
    left join locations l on l.id = s.location_id
    left join accounts a on a.id = s.account_id
    left join lateral (
      select da2.* from delivery_assignment da2
      where da2.sale_id = s.id and da2.state <> 'canceled'
      order by da2.created_at desc limit 1
    ) da on true
    where s.public_token = p_token limit 1
  ), jsonb_build_object('found', false));
$$;


--
-- Name: training_compliance_matrix(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.training_compliance_matrix(p_account_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_only_mandatory boolean DEFAULT false) RETURNS TABLE(employee_id uuid, employee_name text, doc_id text, role text, location_name text, courses jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'training_compliance_matrix: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with emp as (
    select e.id, e.name, e.dni, e.position, e.location_id, l.name as location_name
    from public.employees e
    join public.locations l on l.id = e.location_id
    where l.account_id = p_account_id
      and e.active = true
      and (p_location_id is null or e.location_id = p_location_id)
  ),
  relevant_courses as (
    select distinct c.id as course_id, c.code, c.reeval_months, c.requires_practical
    from public.course c
    join public.course_assignment ca on ca.course_id = c.id
    where ca.account_id = p_account_id
      and c.status = 'published'
      and (not p_only_mandatory or c.is_mandatory)
  ),
  cell as (
    select
      e.id as employee_id,
      rc.course_id,
      rc.code as course_code,
      rc.reeval_months,
      public.course_state_for_employee(e.id, rc.course_id, p_account_id) as state,
      best.finished_at,
      best.passed,
      best.score_pct,
      best.signed_at
    from emp e
    cross join relevant_courses rc
    left join lateral (
      select at.id, at.finished_at, at.passed, at.score_pct,
        (select max(s.signed_at) from public.course_signature s where s.attempt_id = at.id) as signed_at
      from public.course_attempt at
      join public.course_assignment ca2 on ca2.id = at.assignment_id
      where at.employee_id = e.id
        and ca2.course_id = rc.course_id
        and ca2.account_id = p_account_id
      order by
        ((select max(s2.signed_at) from public.course_signature s2 where s2.attempt_id = at.id) is not null
         and coalesce(at.passed, false)) desc,
        at.started_at desc
      limit 1
    ) best on true
  ),
  cell_state as (
    select
      cell.employee_id,
      cell.course_code,
      cell.state,
      cell.finished_at as completed_at,
      case
        when cell.signed_at is not null and cell.reeval_months is not null
          then cell.signed_at + (cell.reeval_months || ' months')::interval
        else null
      end as expires_at,
      cell.score_pct,
      (cell.signed_at is not null and coalesce(cell.passed, false)) as signed
    from cell
  )
  select
    e.id,
    e.name,
    e.dni,
    e.position,
    e.location_name,
    coalesce(
      (
        select jsonb_object_agg(
          cs.course_code,
          jsonb_build_object(
            'state', cs.state,
            'completed_at', cs.completed_at,
            'expires_at', cs.expires_at,
            'score_pct', cs.score_pct,
            'signed', cs.signed
          )
        )
        from cell_state cs
        where cs.employee_id = e.id
      ),
      '{}'::jsonb
    ) as courses
  from emp e
  order by e.name;
end;
$$;


--
-- Name: training_course_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.training_course_summary(p_account_id uuid) RETURNS TABLE(course_id uuid, course_code text, course_title text, legal_basis text, estimated_minutes integer, section_titles text[], assigned_count integer, trained_count integer, signed_count integer, compliance_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'training_course_summary: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with relevant_courses as (
    select distinct c.id, c.code, c.title, c.legal_basis, c.estimated_minutes
    from public.course c
    join public.course_assignment ca on ca.course_id = c.id
    where ca.account_id = p_account_id and c.status = 'published'
  ),
  emp as (
    select e.id, e.position, e.location_id
    from public.employees e
    join public.locations l on l.id = e.location_id
    where l.account_id = p_account_id and e.active = true
  ),
  targeted as (
    select rc.id as course_id, e.id as employee_id
    from relevant_courses rc
    cross join emp e
    where exists (
      select 1 from public.course_assignment ca
      where ca.course_id = rc.id and ca.account_id = p_account_id
        and (
          ca.employee_id = e.id
          or (ca.role is not null and ca.role = e.position)
          or (ca.location_id is not null and ca.location_id = e.location_id)
        )
    )
  ),
  attempt_status as (
    select
      t.course_id,
      t.employee_id,
      public.course_state_for_employee(t.employee_id, t.course_id, p_account_id) as state
    from targeted t
  ),
  sections as (
    select cs.course_id, array_agg(cs.title order by cs.ord) as titles
    from public.course_section cs
    group by cs.course_id
  ),
  counts as (
    select
      rc.id as course_id,
      (select count(*) from targeted t where t.course_id = rc.id)::int as assigned_count,
      (select count(*) from attempt_status a where a.course_id = rc.id and a.state in ('vigente', 'caducado'))::int as trained_count,
      (select count(*) from attempt_status a where a.course_id = rc.id and a.state = 'vigente')::int as signed_count
    from relevant_courses rc
  )
  select
    rc.id,
    rc.code,
    rc.title,
    rc.legal_basis,
    rc.estimated_minutes,
    coalesce(s.titles, array[]::text[]),
    co.assigned_count,
    co.trained_count,
    co.signed_count,
    case when co.assigned_count > 0
      then round(co.signed_count::numeric / co.assigned_count * 100, 1)
      else 0
    end as compliance_pct
  from relevant_courses rc
  left join sections s on s.course_id = rc.id
  join counts co on co.course_id = rc.id
  order by rc.title;
end;
$$;


--
-- Name: training_data_health(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.training_data_health(p_account_id uuid) RETURNS TABLE(check_kind text, item_count integer, sample_names text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'training_data_health: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with emp as (
    select e.id, e.name, e.dni
    from public.employees e
    join public.locations l on l.id = e.location_id
    where l.account_id = p_account_id and e.active = true
  ),
  sin_dni as (
    select name from emp where dni is null or dni = ''
  ),
  sin_acceso as (
    select e.name from emp e
    where not exists (
      select 1 from public.user_profiles up
      where up.employee_id = e.id and up.account_id = p_account_id and up.active = true
    )
  ),
  curso_sin_asignar as (
    select c.title as name
    from public.course c
    where c.status = 'published'
      and (c.account_id = p_account_id or c.account_id is null)
      and not exists (
        select 1 from public.course_assignment ca
        where ca.course_id = c.id and ca.account_id = p_account_id
      )
  ),
  asignacion_sin_fecha as (
    select coalesce(c.title, ca.id::text) as name
    from public.course_assignment ca
    join public.course c on c.id = ca.course_id
    where ca.account_id = p_account_id and ca.due_at is null
  )
  select 'sin_dni'::text, count(*)::int, (array_agg(name order by name))[1:5] from sin_dni
  union all
  select 'sin_acceso'::text, count(*)::int, (array_agg(name order by name))[1:5] from sin_acceso
  union all
  select 'curso_sin_asignar'::text, count(*)::int, (array_agg(name order by name))[1:5] from curso_sin_asignar
  union all
  select 'asignacion_sin_fecha'::text, count(*)::int, (array_agg(name order by name))[1:5] from asignacion_sin_fecha;
end;
$$;


--
-- Name: training_gaps(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.training_gaps(p_account_id uuid, p_days_ahead integer DEFAULT 30) RETURNS TABLE(employee_id uuid, employee_name text, course_id uuid, course_title text, gap_kind text, due_at timestamp with time zone, days_left integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (public.current_user_is_admin()
          or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'training_gaps: sin acceso a la cuenta %', p_account_id;
  end if;

  return query
  with emp as (
    select e.id, e.name, e.position, e.location_id
    from public.employees e
    join public.locations l on l.id = e.location_id
    where l.account_id = p_account_id and e.active = true
  ),
  relevant_courses as (
    select distinct c.id as course_id, c.title, c.reeval_months, c.requires_practical
    from public.course c
    join public.course_assignment ca on ca.course_id = c.id
    where ca.account_id = p_account_id and c.status = 'published'
  ),
  cell as (
    select
      e.id as employee_id,
      e.name as employee_name,
      rc.course_id,
      rc.title as course_title,
      rc.reeval_months,
      (
        select min(ca.due_at) from public.course_assignment ca
        where ca.course_id = rc.course_id and ca.account_id = p_account_id
          and (
            ca.employee_id = e.id
            or (ca.role is not null and ca.role = e.position)
            or (ca.location_id is not null and ca.location_id = e.location_id)
          )
      ) as due_at,
      (exists (
        select 1 from public.course_assignment ca
        where ca.course_id = rc.course_id and ca.account_id = p_account_id
          and (
            ca.employee_id = e.id
            or (ca.role is not null and ca.role = e.position)
            or (ca.location_id is not null and ca.location_id = e.location_id)
          )
      )) as applies,
      public.course_state_for_employee(e.id, rc.course_id, p_account_id) as state,
      best.passed,
      best.signed_at
    from emp e
    cross join relevant_courses rc
    left join lateral (
      select at.id, at.passed,
        (select max(s.signed_at) from public.course_signature s where s.attempt_id = at.id) as signed_at
      from public.course_attempt at
      where at.employee_id = e.id
        and at.assignment_id in (
          select ca3.id from public.course_assignment ca3
          where ca3.course_id = rc.course_id and ca3.account_id = p_account_id
        )
      order by
        ((select max(s2.signed_at) from public.course_signature s2 where s2.attempt_id = at.id) is not null
         and coalesce(at.passed, false)) desc,
        at.started_at desc
      limit 1
    ) best on true
  ),
  classified as (
    select
      cell.employee_id,
      cell.employee_name,
      cell.course_id,
      cell.course_title,
      cell.due_at,
      case
        when not cell.applies then null
        when cell.state = 'pendiente' then 'nunca_hecho'
        when cell.state = 'pendiente_practica' then 'falta_practica'
        when cell.state = 'caducado' then 'caducado'
        when cell.state = 'vigente' and cell.reeval_months is not null
             and cell.signed_at + (cell.reeval_months || ' months')::interval <= now() + (p_days_ahead || ' days')::interval
          then 'caduca_pronto'
        when cell.state = 'vigente' then null
        when coalesce(cell.passed, false) and cell.signed_at is null then 'sin_firmar'
        else 'en_curso'
      end as gap_kind
    from cell
  )
  select
    classified.employee_id,
    classified.employee_name,
    classified.course_id,
    classified.course_title,
    classified.gap_kind,
    classified.due_at,
    case when classified.due_at is not null then (extract(day from classified.due_at - now()))::int else null end as days_left
  from classified
  where classified.gap_kind is not null
  order by
    case classified.gap_kind
      when 'caducado' then 0
      when 'caduca_pronto' then 1
      when 'sin_firmar' then 2
      when 'falta_practica' then 3
      when 'en_curso' then 4
      when 'nunca_hecho' then 5
      else 6
    end,
    classified.due_at nulls last;
end;
$$;


--
-- Name: training_is_clocked_in(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.training_is_clocked_in(p_employee_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT ce.type in ('entrada','pausa_inicio','pausa_fin')
     FROM clock_entries ce
     WHERE ce.employee_id = p_employee_id AND NOT ce.voided
     ORDER BY ce.datetime DESC
     LIMIT 1),
    false
  );
$$;


--
-- Name: training_notice_mark_status(text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.training_notice_mark_status(p_wamid text, p_status text, p_at timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE training_notice tn
  SET status = CASE WHEN p_status IN ('delivered','read','failed') THEN p_status ELSE tn.status END,
      delivered_at = CASE WHEN p_status='delivered' AND tn.delivered_at IS NULL THEN p_at ELSE tn.delivered_at END,
      read_at      = CASE WHEN p_status='read'      AND tn.read_at      IS NULL THEN p_at ELSE tn.read_at END,
      updated_at   = now()
  WHERE tn.provider_message_id = p_wamid;
  RETURN FOUND;
END;
$$;


