--
-- Name: uber_senales_de_reparto(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uber_senales_de_reparto(p_raw_tab text) RETURNS TABLE(calle boolean, coordenadas boolean, cargo_envio boolean)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare v_t jsonb;
begin
  if left(btrim(coalesce(p_raw_tab, '')), 1) <> '{' then
    return query select null::boolean, null::boolean, null::boolean; return;
  end if;
  -- Ilegible = no lo sé (nulos), no «ninguna señal»: un raw_tab que no se lee
  -- no puede mandar un pedido a «la reparte Uber».
  begin
    v_t := p_raw_tab::jsonb;
  exception when others then
    return query select null::boolean, null::boolean, null::boolean; return;
  end;
  return query select
    nullif(btrim(coalesce(v_t->'customer'->>'address_1', ''), E' \t\r\n'), '') is not null,
    nullif(v_t->'customer'->>'latitude', '') is not null and nullif(v_t->'customer'->>'longitude', '') is not null,
    exists (select 1 from jsonb_array_elements(case when jsonb_typeof(v_t->'charges') = 'array' then v_t->'charges' else '[]'::jsonb end) c
             where coalesce(c->>'type', c->>'charge_type') = 'delivery'
               and coalesce(nullif(regexp_replace(coalesce(c->>'price', ''), '[^0-9.]', '', 'g'), '')::numeric, 0) > 0);
end;
$$;


--
-- Name: FUNCTION uber_senales_de_reparto(p_raw_tab text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.uber_senales_de_reparto(p_raw_tab text) IS 'R03: las tres señales de que un pedido de Uber lo repartimos nosotros (calle, coordenadas y cargo de envío > 0), leídas de raw_tab.';


--
-- Name: unassign_items_from_zones(uuid, uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unassign_items_from_zones(p_account uuid, p_location uuid, p_item_ids uuid[] DEFAULT NULL::uuid[], p_zone_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_affected uuid[];
  v_removed int;
begin
  if p_location is null then
    raise exception 'Falta el local';
  end if;

  -- borra las asignaciones objetivo y recoge los artículos tocados
  with del as (
    delete from recipe_item_storage_area rsa
    using storage_area sa
    where rsa.storage_area_id = sa.id
      and rsa.account_id = p_account
      and sa.location_id = p_location
      and (p_zone_ids is null or rsa.storage_area_id = any (p_zone_ids))
      and (p_item_ids is null or rsa.recipe_item_id = any (p_item_ids))
    returning rsa.recipe_item_id
  )
  select array_agg(distinct recipe_item_id), count(*)
  into v_affected, v_removed
  from del;

  -- re-normaliza la principal de los artículos que aún conservan zonas en el local
  if v_affected is not null then
    with ranked as (
      select rsa.recipe_item_id,
             rsa.storage_area_id,
             (row_number() over (
                partition by rsa.recipe_item_id
                order by rsa.position asc, sa.position asc
             ) - 1) * 10 as new_pos
      from recipe_item_storage_area rsa
      join storage_area sa on sa.id = rsa.storage_area_id
      where rsa.account_id = p_account
        and sa.location_id = p_location
        and rsa.recipe_item_id = any (v_affected)
    )
    update recipe_item_storage_area t
    set position = ranked.new_pos
    from ranked
    where t.recipe_item_id = ranked.recipe_item_id
      and t.storage_area_id = ranked.storage_area_id
      and t.position <> ranked.new_pos;
  end if;

  return jsonb_build_object('removed', coalesce(v_removed, 0));
end;
$$;


--
-- Name: unignore_unmapped_sales(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unignore_unmapped_sales(p_account_id uuid, p_product_name text, p_brand_id uuid DEFAULT NULL::uuid) RETURNS TABLE(resultado text, lineas_afectadas integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_norm  text;
  v_afect integer := 0;
BEGIN
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'unignore_unmapped_sales: sin acceso a la cuenta %', p_account_id;
  END IF;

  v_norm := regexp_replace(
              regexp_replace(btrim(lower(public.unaccent(coalesce(p_product_name,'')))), '\.$', ''),
              '\s+', ' ', 'g'
            );

  UPDATE sale_line sl
  SET unmapped_reason = NULL,
      ignore_reason = NULL,
      ignored_at = NULL,
      map_needs_review = true,
      updated_at = now()
  FROM sale s
  WHERE sl.sale_id = s.id
    AND sl.account_id = p_account_id
    AND s.source = 'lastapp'
    AND sl.menu_item_id IS NULL
    AND coalesce(sl.line_type,'product') = 'product'
    AND sl.map_source <> 'manual'
    AND coalesce(sl.unmapped_reason,'') = 'ignored'
    AND (p_brand_id IS NULL OR s.brand_id = p_brand_id)
    AND regexp_replace(
          regexp_replace(btrim(lower(public.unaccent(coalesce(sl.product_name,'')))), '\.$', ''),
          '\s+', ' ', 'g'
        ) = v_norm;
  GET DIAGNOSTICS v_afect = ROW_COUNT;

  -- Recomputar la razón real de las líneas reabiertas.
  PERFORM public.recast_lastapp_sales(p_account_id);

  RETURN QUERY SELECT 'unignored'::text, v_afect;
END;
$_$;


--
-- Name: unignore_unmapped_sales_scoped(uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unignore_unmapped_sales_scoped(p_account_id uuid, p_product_name text, p_brand_id uuid DEFAULT NULL::uuid, p_include_before_last_count boolean DEFAULT false) RETURNS TABLE(resultado text, lineas_afectadas integer, ventas_reprocesadas integer, ventas_protegidas integer, euros_protegidos numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_norm text; v_afect integer := 0; v_rep record;
BEGIN
  IF NOT (public.current_user_is_admin()
          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN
    RAISE EXCEPTION 'unignore_unmapped_sales_scoped: sin acceso a la cuenta %', p_account_id;
  END IF;

  v_norm := public.sales_product_norm(p_product_name);

  UPDATE sale_line sl
  SET unmapped_reason = NULL,
      ignore_reason = NULL,
      ignored_at = NULL,
      map_needs_review = true,
      updated_at = now()
  FROM sale s
  WHERE sl.sale_id = s.id
    AND sl.account_id = p_account_id
    AND s.source = 'lastapp'
    AND sl.menu_item_id IS NULL
    AND coalesce(sl.line_type,'product') = 'product'
    AND sl.map_source <> 'manual'
    AND coalesce(sl.unmapped_reason,'') = 'ignored'
    AND (p_brand_id IS NULL OR s.brand_id = p_brand_id)
    AND public.sales_product_norm(sl.product_name) = v_norm;
  GET DIAGNOSTICS v_afect = ROW_COUNT;

  SELECT * INTO v_rep
    FROM public._reprocess_product_sales_scoped(p_account_id, p_product_name, p_include_before_last_count);

  resultado := 'unignored'; lineas_afectadas := v_afect;
  ventas_reprocesadas := v_rep.ventas_reprocesadas;
  ventas_protegidas   := v_rep.ventas_protegidas;
  euros_protegidos    := v_rep.euros_protegidos;
  RETURN NEXT;
END;
$$;


--
-- Name: unmark_supplier_invoice_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unmark_supplier_invoice_paid(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_inv supplier_invoice%rowtype; v_name text;
begin
  select * into v_inv from supplier_invoice where id = p_invoice_id for update;
  if not found or not belongs_to_account(v_inv.account_id) then raise exception 'No encuentro esa factura.'; end if;
  if v_inv.status <> 'pagada' then raise exception 'Esa factura no está marcada como pagada.'; end if;
  -- PC01: mientras su pago con asiento siga ahí, sigue pagada. Se deshace
  -- deshaciendo el casado en Bancos o anulando el asiento del pago.
  if coalesce((select sum(amount) from supplier_invoice_payment where invoice_id = p_invoice_id and entry_id is not null), 0) >= coalesce(v_inv.grand_total, 0) - 0.005
     and coalesce(v_inv.grand_total, 0) <> 0 then
    raise exception 'La factura % tiene su pago con asiento: se deshace deshaciendo el casado en Bancos o anulando el asiento del pago.', coalesce(v_inv.invoice_number, '') using errcode = '23514';
  end if;
  v_name := _actor_name(v_inv.account_id);
  update supplier_invoice set status = 'aprobada', paid_at = null, paid_method = null,
         paid_by = null, paid_by_name = null, updated_at = now()
   where id = p_invoice_id;
  insert into supplier_invoice_payment_log (account_id, invoice_id, action, paid_at, paid_method, actor_id, actor_name)
  values (v_inv.account_id, p_invoice_id, 'unpaid', v_inv.paid_at, v_inv.paid_method, auth.uid(), v_name);
end $$;


