--
-- Name: upsert_courier(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_courier(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_id uuid;
begin
  v_acc := (current_user_account_ids())[1];
  if v_acc is null or not current_user_is_admin_or_manager_of(v_acc) then raise exception 'forbidden'; end if;
  v_id := nullif(p->>'id','')::uuid;
  if v_id is null then
    insert into courier(account_id,name,phone,kind,employee_id,transport_type,vehicle_plate,nif,iban,
      assigned_locations,cost_model,cost_value,rate_base,rate_per_km,rate_min_pickup,rate_pickup_fee,rate_tiers,active,on_shift)
    values (v_acc, p->>'name', nullif(p->>'phone',''),
      coalesce(nullif(p->>'kind',''),'freelance'), nullif(p->>'employee_id','')::uuid,
      nullif(p->>'transport_type',''), nullif(p->>'vehicle_plate',''), nullif(p->>'nif',''), nullif(p->>'iban',''),
      case when jsonb_typeof(p->'assigned_locations')='array' then (select coalesce(array_agg(x::uuid),'{}'::uuid[]) from jsonb_array_elements_text(p->'assigned_locations') x) else '{}'::uuid[] end,
      coalesce(nullif(p->>'cost_model',''),'per_order'), nullif(p->>'cost_value','')::numeric,
      nullif(p->>'rate_base','')::numeric, nullif(p->>'rate_per_km','')::numeric,
      nullif(p->>'rate_min_pickup','')::numeric, nullif(p->>'rate_pickup_fee','')::numeric,
      case when jsonb_typeof(p->'rate_tiers')='array' then p->'rate_tiers' else null end,
      coalesce((p->>'active')::boolean,true), coalesce((p->>'on_shift')::boolean,false))
    returning id into v_id;
  else
    update courier set name=p->>'name', phone=nullif(p->>'phone',''),
      kind=coalesce(nullif(p->>'kind',''),kind),
      employee_id=case when p ? 'employee_id' then nullif(p->>'employee_id','')::uuid else employee_id end,
      transport_type=nullif(p->>'transport_type',''), vehicle_plate=nullif(p->>'vehicle_plate',''),
      nif=nullif(p->>'nif',''), iban=nullif(p->>'iban',''),
      assigned_locations=case when jsonb_typeof(p->'assigned_locations')='array' then (select coalesce(array_agg(x::uuid),'{}'::uuid[]) from jsonb_array_elements_text(p->'assigned_locations') x) else assigned_locations end,
      cost_model=coalesce(nullif(p->>'cost_model',''),cost_model), cost_value=nullif(p->>'cost_value','')::numeric,
      rate_base=nullif(p->>'rate_base','')::numeric, rate_per_km=nullif(p->>'rate_per_km','')::numeric,
      rate_min_pickup=nullif(p->>'rate_min_pickup','')::numeric, rate_pickup_fee=nullif(p->>'rate_pickup_fee','')::numeric,
      rate_tiers=case when jsonb_typeof(p->'rate_tiers')='array' then p->'rate_tiers' else rate_tiers end,
      active=coalesce((p->>'active')::boolean,active), on_shift=coalesce((p->>'on_shift')::boolean,on_shift), updated_at=now()
    where id=v_id and account_id=v_acc;
  end if;
  return v_id;
end; $$;


--
-- Name: upsert_courier_bonus(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_courier_bonus(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acc uuid; v_id uuid;
begin
  v_acc := (current_user_account_ids())[1];
  if v_acc is null or not current_user_is_admin_or_manager_of(v_acc) then raise exception 'forbidden'; end if;
  v_id := nullif(p->>'id','')::uuid;
  if v_id is null then
    insert into courier_bonus(account_id,name,period,target_count,reward,location_id,valid_from,valid_to,is_active)
    values (v_acc, coalesce(nullif(p->>'name',''),'Reto'), coalesce(nullif(p->>'period',''),'week'),
      coalesce((p->>'target_count')::int,0), coalesce((p->>'reward')::numeric,0),
      nullif(p->>'location_id','')::uuid, nullif(p->>'valid_from','')::date, nullif(p->>'valid_to','')::date,
      coalesce((p->>'is_active')::boolean,true))
    returning id into v_id;
  else
    update courier_bonus set name=coalesce(nullif(p->>'name',''),name),
      period=coalesce(nullif(p->>'period',''),period), target_count=coalesce((p->>'target_count')::int,target_count),
      reward=coalesce((p->>'reward')::numeric,reward), location_id=nullif(p->>'location_id','')::uuid,
      valid_from=nullif(p->>'valid_from','')::date, valid_to=nullif(p->>'valid_to','')::date,
      is_active=coalesce((p->>'is_active')::boolean,is_active), updated_at=now()
    where id=v_id and account_id=v_acc;
  end if;
  return v_id;
end; $$;


--
-- Name: upsert_delivery_zone_polygon(uuid, uuid, text, jsonb, numeric, numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_delivery_zone_polygon(p_id uuid, p_location_id uuid, p_name text, p_geojson jsonb, p_delivery_fee numeric, p_min_order numeric DEFAULT NULL::numeric, p_eta_min integer DEFAULT NULL::integer, p_priority integer DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_account uuid; v_id uuid; v_geog geography;
begin
  v_account := public._delivery_zone_account_of_location(p_location_id);
  if v_account is null then raise exception 'Local no encontrado'; end if;
  if not public.current_user_is_admin_of(v_account) then raise exception 'Sin permiso'; end if;

  v_geog := ST_SetSRID(ST_GeomFromGeoJSON(p_geojson::text), 4326)::geography;

  if p_id is null then
    insert into public.delivery_zone
      (account_id, location_id, name, method, area, delivery_fee, min_order, eta_min, priority)
    values
      (v_account, p_location_id, p_name, 'polygon', v_geog, p_delivery_fee, p_min_order, p_eta_min, p_priority)
    returning id into v_id;
  else
    update public.delivery_zone set
      name = p_name, area = v_geog,
      delivery_fee = p_delivery_fee, min_order = p_min_order, eta_min = p_eta_min, priority = p_priority
    where id = p_id and account_id = v_account
    returning id into v_id;
    if v_id is null then raise exception 'Zona no encontrada'; end if;
  end if;
  return v_id;
end; $$;


