--
-- Name: upsert_dispatch_rule(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_dispatch_rule(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_id uuid;
  v_chain text[]; v_then text; v_fallback text;
begin
  v_acc := (current_user_account_ids())[1];
  if v_acc is null or not current_user_is_admin_or_manager_of(v_acc) then raise exception 'forbidden'; end if;
  v_id := nullif(p->>'id','')::uuid;

  if jsonb_typeof(p->'carrier_chain')='array' then
    v_chain := (select array_agg(x) from jsonb_array_elements_text(p->'carrier_chain') x where nullif(x,'') is not null);
  end if;
  if v_chain is null or array_length(v_chain,1) is null then
    v_chain := array_remove(ARRAY[nullif(p->>'then_carrier',''), nullif(p->>'fallback_carrier','')], NULL);
  end if;
  v_then     := coalesce(v_chain[1], nullif(p->>'then_carrier',''), 'own_fleet');
  v_fallback := v_chain[2];

  if v_id is null then
    insert into dispatch_rule(account_id,location_id,priority,weekdays,time_from,time_to,min_total,max_total,
      margin_floor_pct,then_carrier,fallback_carrier,carrier_chain,max_distance_km,strategy,is_active)
    values (v_acc, nullif(p->>'location_id','')::uuid, coalesce((p->>'priority')::int,100),
      case when jsonb_typeof(p->'weekdays')='array' then (select array_agg(x::int) from jsonb_array_elements_text(p->'weekdays') x) else null end,
      nullif(p->>'time_from','')::time, nullif(p->>'time_to','')::time,
      nullif(p->>'min_total','')::numeric, nullif(p->>'max_total','')::numeric, nullif(p->>'margin_floor_pct','')::numeric,
      v_then, v_fallback, v_chain, nullif(p->>'max_distance_km','')::numeric,
      coalesce(nullif(p->>'strategy',''),'own_first'),
      coalesce((p->>'is_active')::boolean,true))
    returning id into v_id;
  else
    update dispatch_rule set location_id=nullif(p->>'location_id','')::uuid, priority=coalesce((p->>'priority')::int,priority),
      weekdays=case when jsonb_typeof(p->'weekdays')='array' then (select array_agg(x::int) from jsonb_array_elements_text(p->'weekdays') x) else null end,
      time_from=nullif(p->>'time_from','')::time, time_to=nullif(p->>'time_to','')::time,
      min_total=nullif(p->>'min_total','')::numeric, max_total=nullif(p->>'max_total','')::numeric,
      margin_floor_pct=nullif(p->>'margin_floor_pct','')::numeric,
      then_carrier=v_then, fallback_carrier=v_fallback, carrier_chain=v_chain,
      max_distance_km=nullif(p->>'max_distance_km','')::numeric,
      strategy=coalesce(nullif(p->>'strategy',''),strategy),
      is_active=coalesce((p->>'is_active')::boolean,is_active), updated_at=now()
    where id=v_id and account_id=v_acc;
  end if;
  return v_id;
end; $$;


--
-- Name: upsert_pos_sale(uuid, uuid, uuid, uuid, text, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_pos_sale(p_sale_id uuid, p_account_id uuid, p_location_id uuid, p_brand_id uuid, p_channel_kind text, p_lines jsonb, p_action text, p_payment_method text DEFAULT NULL::text, p_device_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale_id   uuid := p_sale_id;
  v_channel   uuid;
  v_actor     text;
  v_line      jsonb;
  v_repr      jsonb;
  v_vat       numeric;
  v_ltotal    numeric;
  v_lbase     numeric;
  v_base_sum  numeric := 0;
  v_tax_sum   numeric := 0;
  v_total_sum numeric := 0;
  v_status    text;
  v_device    kds_device;
  v_device_id uuid;
  v_result    sale%rowtype;
begin
  if not public._pos_can_operate(p_account_id, p_location_id) then
    raise exception 'upsert_pos_sale: sin acceso a esta cuenta/local';
  end if;
  if p_action not in ('save', 'command', 'charge', 'deliver') then
    raise exception 'upsert_pos_sale: accion no valida %', p_action;
  end if;
  if p_action = 'charge' and p_payment_method not in ('cash', 'card') then
    raise exception 'upsert_pos_sale: cobrar exige payment_method cash|card';
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'upsert_pos_sale: la cuenta no tiene lineas';
  end if;

  select display_name into v_actor from user_profiles
  where user_id = auth.uid() and account_id = p_account_id limit 1;

  v_channel := public._pos_channel_id(p_account_id, coalesce(p_channel_kind, 'counter'));

  -- Dispositivo (T1.c): resuelto por TOKEN en el servidor, igual que las rutas
  -- por token — el cliente nunca manda un device_id propio. Si no resuelve, o
  -- resuelve a un dispositivo de otra cuenta/local, se queda null SIN bloquear
  -- la venta.
  if p_device_token is not null then
    v_device := public.kds_resolve_device(p_device_token);
    if v_device.id is not null
       and v_device.account_id = p_account_id
       and v_device.location_id = p_location_id then
      v_device_id := v_device.id;
    end if;
  end if;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_repr   := public._shop_reprice_line(p_account_id, v_line);
    v_ltotal := coalesce((v_repr->>'lineTotal')::numeric, 0);
    select vat_rate into v_vat from menu_item
    where id = (v_line->>'menuItemId')::uuid and account_id = p_account_id;
    v_vat := coalesce(v_vat, 10);
    v_lbase     := round(v_ltotal / (1 + v_vat / 100.0), 2);
    v_base_sum  := v_base_sum + v_lbase;
    v_tax_sum   := v_tax_sum + (v_ltotal - v_lbase);
    v_total_sum := v_total_sum + v_ltotal;
  end loop;

  if v_sale_id is null then
    insert into sale (
      account_id, location_id, brand_id, channel_id, source, service_type,
      status, order_status, sold_at, opened_at, total, taxable_base, tax,
      payment_method, payment_status, dispatch_mode, pos_short_code,
      raw_tab, created_by, created_by_name, device_id
    ) values (
      p_account_id, p_location_id, p_brand_id, v_channel, 'folvy_pos', 'pickup',
      'open', null, now(), now(), round(v_total_sum, 2), round(v_base_sum, 2), round(v_tax_sum, 2),
      null, null, 'auto', public._pos_next_ticket_code(p_account_id, p_location_id),
      jsonb_build_object('lines', p_lines)::text, auth.uid(), v_actor, v_device_id
    )
    returning id into v_sale_id;
  else
    select * into v_result from sale where id = v_sale_id
      and account_id = p_account_id and location_id = p_location_id;
    if v_result.id is null then
      raise exception 'upsert_pos_sale: venta inexistente o de otra cuenta/local';
    end if;
    -- TPV sala (S1): una cuenta de mesa no pasa por aquí. Su borrar-y-reinsertar
    -- destruiría las líneas ya enviadas a cocina.
    if v_result.table_id is not null then
      raise exception 'upsert_pos_sale: es la cuenta de una mesa — se trabaja desde Sala';
    end if;
    if p_action = 'deliver' then
      if v_result.status <> 'closed' then
        raise exception 'upsert_pos_sale: no se puede marcar Entregado sin cobrar antes';
      end if;
      update sale set order_status = 'completed' where id = v_sale_id;
      select * into v_result from sale where id = v_sale_id;
      return jsonb_build_object('saleId', v_result.id, 'posShortCode', v_result.pos_short_code, 'status', v_result.status, 'orderStatus', v_result.order_status, 'paymentStatus', v_result.payment_status, 'total', v_result.total, 'taxableBase', v_result.taxable_base, 'tax', v_result.tax);
    end if;
    if v_result.status <> 'open' then raise exception 'upsert_pos_sale: la cuenta ya esta cerrada (status=%)', v_result.status; end if;
    update sale set
      brand_id      = p_brand_id,
      channel_id    = v_channel,
      total         = round(v_total_sum, 2),
      taxable_base  = round(v_base_sum, 2),
      tax           = round(v_tax_sum, 2),
      raw_tab       = jsonb_build_object('lines', p_lines)::text,
      updated_at    = now()
    where id = v_sale_id;
  end if;

  perform public._adapt_folvy_pos_order(v_sale_id);

  if p_action in ('command', 'charge') then
    update sale set order_status = coalesce(order_status, 'accepted') where id = v_sale_id;
  end if;

  if p_action = 'charge' then
    update sale set
      status         = 'closed',
      payment_method = p_payment_method,
      payment_status = 'paid',
      paid_at        = now(),
      closed_at      = now()
    where id = v_sale_id;
  end if;

  if p_action = 'deliver' then
    select status into v_status from sale where id = v_sale_id;
    if v_status <> 'closed' then
      raise exception 'upsert_pos_sale: no se puede marcar Entregado sin cobrar antes';
    end if;
    update sale set order_status = 'completed' where id = v_sale_id;
  end if;

  select * into v_result from sale where id = v_sale_id;
  return jsonb_build_object(
    'saleId', v_result.id,
    'posShortCode', v_result.pos_short_code,
    'status', v_result.status,
    'orderStatus', v_result.order_status,
    'paymentStatus', v_result.payment_status,
    'total', v_result.total,
    'taxableBase', v_result.taxable_base,
    'tax', v_result.tax
  );
end;
$$;


--
-- Name: upsert_printer(uuid, uuid, uuid, text, text, jsonb, text[], boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_printer(p_id uuid, p_account_id uuid, p_location_id uuid, p_name text, p_transport text, p_config jsonb, p_doc_types text[], p_is_active boolean, p_copies integer DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  if not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(p_account_id)) then
    raise exception 'upsert_printer: sin acceso a la cuenta %', p_account_id;
  end if;
  if p_transport is distinct from 'escpos_network' then
    raise exception 'upsert_printer: transport no soportado aún (sólo escpos_network): %', p_transport;
  end if;
  if p_id is null then
    insert into printer (account_id, location_id, name, transport, config, doc_types, is_active, copies)
    values (p_account_id, p_location_id, p_name, p_transport, coalesce(p_config,'{}'::jsonb),
            coalesce(p_doc_types, array['bag','kitchen','labels']), coalesce(p_is_active, true),
            greatest(1, least(9, coalesce(p_copies, 1))))
    returning id into v_id;
  else
    update printer set location_id = p_location_id, name = p_name, transport = p_transport,
      config = coalesce(p_config, config), doc_types = coalesce(p_doc_types, doc_types),
      is_active = coalesce(p_is_active, is_active),
      copies = greatest(1, least(9, coalesce(p_copies, copies))), updated_at = now()
    where id = p_id and account_id = p_account_id returning id into v_id;
    if v_id is null then raise exception 'upsert_printer: impresora % no encontrada en la cuenta', p_id; end if;
  end if;
  return v_id;
end;
$$;


--
-- Name: upsert_printer_by_token(text, uuid, text, jsonb, text[], boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_printer_by_token(p_device_token text, p_id uuid, p_name text, p_config jsonb, p_doc_types text[], p_is_active boolean, p_copies integer DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_device kds_device; v_id uuid;
begin
  v_device := public.kds_resolve_device(p_device_token);
  if v_device.id is null then raise exception 'upsert_printer_by_token: token no válido'; end if;
  if p_id is null then
    insert into printer (account_id, location_id, name, transport, config, doc_types, is_active, copies)
    values (v_device.account_id, v_device.location_id, p_name, 'escpos_network', coalesce(p_config,'{}'::jsonb),
            coalesce(p_doc_types, array['bag','kitchen','labels']), coalesce(p_is_active, true),
            greatest(1, least(9, coalesce(p_copies, 1))))
    returning id into v_id;
  else
    update printer set name = p_name, config = coalesce(p_config, config),
      doc_types = coalesce(p_doc_types, doc_types), is_active = coalesce(p_is_active, is_active),
      copies = greatest(1, least(9, coalesce(p_copies, copies))), updated_at = now()
    where id = p_id and account_id = v_device.account_id and location_id = v_device.location_id
    returning id into v_id;
    if v_id is null then raise exception 'upsert_printer_by_token: impresora % no encontrada en el local del dispositivo', p_id; end if;
  end if;
  return v_id;
end;
$$;


--
-- Name: vat_rate_for(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vat_rate_for(p_category_id uuid, p_date date) RETURNS TABLE(rate numeric, equivalence_surcharge numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select r.rate, r.equivalence_surcharge
    from public.vat_category_rate r
   where r.category_id = p_category_id
     and r.valid_from <= p_date
     and (r.valid_to is null or r.valid_to >= p_date)
   order by r.valid_from desc
   limit 1;
$$;


--
-- Name: FUNCTION vat_rate_for(p_category_id uuid, p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.vat_rate_for(p_category_id uuid, p_date date) IS 'C00 (D1): el tipo de IVA de una categoría en una fecha. Lee de tax_rate por el puente vat_category_tax (vista vat_category_rate). Antes leía vat_rate.';


--
-- Name: ventas_cerradas_sin_consumo_watchdog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ventas_cerradas_sin_consumo_watchdog() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_total integer := 0; v_txt text;
  v_cand uuid[];   -- cerradas de 7 dias que deberian haber descontado y no
  v_fuga uuid[];   -- de esas, las que aportan por una linea PROPIA: averia
  v_frio uuid[];   -- de esas, las que solo aportan por lineas RECASADAS EN FRIO
  v_cob  uuid[];   -- de esas, las que no tenian con que: cobertura
  v_recast uuid[]; -- ventas con alguna linea recasada en frio
BEGIN
  -- PASO 0. Esto NO puede ir como CTE: Postgres incorpora las CTE no
  -- recursivas referenciadas una sola vez y el EXISTS acababa colgando de
  -- `sale` entera (20.917 ms, 12/09).
  SELECT COALESCE(array_agg(q.id), '{}'::uuid[]) INTO v_cand FROM (
    SELECT s.id FROM public.sale s
      LEFT JOIN public._ventas_que_deberian_descontar() d ON d.sale_id = s.id
      LEFT JOIN public._ventas_con_consumo()            t ON t.sale_id = s.id
     WHERE COALESCE(s.status,'') = 'closed'
       AND COALESCE(s.order_status,'') NOT IN ('cancelled','rejected')
       AND COALESCE(s.is_active, true)
       AND s.created_at <  now() - interval '24 hours'
       AND s.created_at >= now() - interval '7 days'
       AND s.account_id <> '00000000-0000-0000-0000-000000000001'::uuid
       AND d.sale_id IS NOT NULL AND t.sale_id IS NULL) q;

  -- Una sola vez, fuera del bucle: dentro seria un correlacionado sobre
  -- `sale` entera, que es el error que ya costo 20 s.
  SELECT COALESCE(array_agg(DISTINCT f.sale_id), '{}'::uuid[]) INTO v_recast
    FROM public.sale_line_recast_frio f;

  -- LA VARA ES LA DEL MOTOR (regla 39), no una copia. 23/09: el reparto se
  -- hace por LINEA. Una venta que aporta por una linea NO recasada sigue
  -- siendo FUGA aunque ademas tenga lineas en frio: una averia de verdad no
  -- se esconde detras de una linea recasada. Una sola pasada del motor.
  SELECT COALESCE(array_agg(q.sale_id) FILTER (WHERE q.aporta_linea_propia), '{}'::uuid[]),
         COALESCE(array_agg(q.sale_id) FILTER (WHERE NOT q.aporta_linea_propia), '{}'::uuid[])
    INTO v_fuga, v_frio
  FROM (
    SELECT sl.sale_id,
           bool_or(NOT EXISTS (SELECT 1 FROM public.sale_line_recast_frio f
                                WHERE f.sale_line_id = sl.id)) AS aporta_linea_propia
      FROM public.sale_line sl
      CROSS JOIN LATERAL public._sale_line_raw_consumption(sl.id) r2
     WHERE sl.sale_id = ANY(v_cand)
       AND COALESCE(sl.line_type,'product') = 'product'
       AND sl.ignored_at IS NULL
       AND r2.raw_item_id IS NOT NULL AND COALESCE(r2.qty_base,0) <> 0
     GROUP BY sl.sale_id) q;

  SELECT COALESCE(array_agg(c), '{}'::uuid[]) INTO v_cob
    FROM unnest(v_cand) AS c
   WHERE NOT (c = ANY(v_fuga)) AND NOT (c = ANY(v_frio));

  FOR r IN
    SELECT s.account_id AS acc, COALESCE(a.name, s.account_id::text) AS cuenta,
           count(*) FILTER (WHERE COALESCE(s.status,'') = 'open'
                 AND COALESCE(s.order_status,'') NOT IN ('cancelled','rejected','delivery_failed')
                 AND s.cancelled_at IS NULL AND COALESCE(s.is_active, true)
                 AND s.created_at < now() - interval '24 hours')                    AS viva,
           count(*) FILTER (WHERE COALESCE(s.status,'') = 'open'
                 AND COALESCE(s.order_status,'') IN ('cancelled','rejected','delivery_failed')) AS roto_a,
           count(*) FILTER (WHERE COALESCE(s.order_status,'') = 'cancelled'
                 AND s.cancelled_at IS NULL)                                        AS roto_b,
           count(*) FILTER (WHERE (COALESCE(s.status,'') = 'open'
                     AND COALESCE(s.order_status,'') IN ('cancelled','rejected','delivery_failed'))
                 OR (COALESCE(s.order_status,'') = 'cancelled' AND s.cancelled_at IS NULL)) AS roto_total,
           count(*) FILTER (WHERE s.id = ANY(v_fuga))                               AS fuga,
           count(*) FILTER (WHERE s.id = ANY(v_frio))                               AS frio,
           count(*) FILTER (WHERE s.id = ANY(v_cob))                                AS cobertura,
           count(*) FILTER (WHERE COALESCE(s.status,'') = 'closed'
                 AND COALESCE(s.order_status,'') NOT IN ('cancelled','rejected')
                 AND COALESCE(s.is_active, true)
                 AND s.created_at < now() - interval '7 days'
                 AND d.sale_id IS NOT NULL AND t.sale_id IS NULL)                   AS arrastre,
           count(*) FILTER (WHERE COALESCE(s.status,'') = 'closed'
                 AND COALESCE(s.order_status,'') NOT IN ('cancelled','rejected')
                 AND COALESCE(s.is_active, true)
                 AND s.created_at < now() - interval '7 days'
                 AND d.sale_id IS NOT NULL AND t.sale_id IS NULL
                 AND s.id = ANY(v_recast))                                          AS arrastre_frio
      FROM public.sale s
      LEFT JOIN public.accounts a ON a.id = s.account_id
      LEFT JOIN public._ventas_que_deberian_descontar() d ON d.sale_id = s.id
      LEFT JOIN public._ventas_con_consumo()            t ON t.sale_id = s.id
     WHERE s.account_id <> '00000000-0000-0000-0000-000000000001'::uuid
     GROUP BY s.account_id, COALESCE(a.name, s.account_id::text)
  LOOP
    IF r.viva > 0 THEN
      SELECT string_agg(x.linea, E'\n' ORDER BY x.creada) INTO v_txt FROM (
        SELECT s.created_at AS creada,
               format('%s de %s (%s)', COALESCE(s.pos_short_code, s.platform_order_code, left(s.id::text,8)),
                 COALESCE(l.name,'sin local'),
                 to_char(s.created_at AT TIME ZONE 'Europe/Madrid','DD/MM HH24:MI')) AS linea
          FROM public.sale s LEFT JOIN public.locations l ON l.id = s.location_id
         WHERE s.account_id = r.acc AND COALESCE(s.status,'') = 'open'
           AND COALESCE(s.order_status,'') NOT IN ('cancelled','rejected','delivery_failed')
           AND s.cancelled_at IS NULL AND COALESCE(s.is_active, true)
           AND s.created_at < now() - interval '24 hours'
         ORDER BY s.created_at LIMIT 30) x;
      PERFORM public.encolar_alerta(
        p_kind => 'comanda_viva_sin_cerrar',
        p_subject => format('%s: %s comanda(s) llevan más de 24 h abiertas', r.cuenta, r.viva),
        p_message => 'Son comandas VIVAS: nadie las ha anulado ni rechazado. Mientras no se '
                  || 'cierren, su consumo no se descuenta del almacén.' || E'\n' || COALESCE(v_txt,''),
        p_debounce_kind => 'comanda_viva_sin_cerrar:' || r.acc::text,
        p_debounce_window => interval '24 hours',
        p_account_id => r.acc, p_location_id => NULL, p_brand_id => NULL, p_severity => 'alto');
    END IF;

    IF r.roto_total > 0 THEN
      SELECT string_agg(x.linea, E'\n' ORDER BY x.local) INTO v_txt FROM (
        SELECT COALESCE(l.name,'sin local') AS local,
               format('%s: %s con la comanda abierta y el pedido muerto, %s anuladas sin fecha',
                 COALESCE(l.name,'sin local'),
                 count(*) FILTER (WHERE COALESCE(s.status,'')='open'
                       AND COALESCE(s.order_status,'') IN ('cancelled','rejected','delivery_failed')),
                 count(*) FILTER (WHERE COALESCE(s.order_status,'')='cancelled'
                       AND s.cancelled_at IS NULL)) AS linea
          FROM public.sale s LEFT JOIN public.locations l ON l.id = s.location_id
         WHERE s.account_id = r.acc
           AND ( (COALESCE(s.status,'')='open'
                  AND COALESCE(s.order_status,'') IN ('cancelled','rejected','delivery_failed'))
              OR (COALESCE(s.order_status,'')='cancelled' AND s.cancelled_at IS NULL) )
         GROUP BY COALESCE(l.name,'sin local')) x;
      PERFORM public.encolar_alerta(
        p_kind => 'venta_en_estado_imposible',
        p_subject => format('%s: %s venta(s) en un estado que no puede existir', r.cuenta, r.roto_total),
        p_message => 'NO son comandas vivas: son datos rotos, y no tocan el almacén.' || E'\n'
                  || format('· %s con `status=open` y el pedido anulado, rechazado o con reparto fallido.', r.roto_a) || E'\n'
                  || format('· %s con `order_status=cancelled` y `cancelled_at` vacío: nadie las anuló.', r.roto_b) || E'\n'
                  || '(Las dos listas se solapan: una venta puede estar en las dos.)' || E'\n'
                  || 'Si el estado lo puso un proceso nuestro, el arreglo va en el proceso, no a mano.' || E'\n'
                  || COALESCE(v_txt,''),
        p_debounce_kind => 'venta_en_estado_imposible:' || r.acc::text,
        p_debounce_window => interval '7 days',
        p_account_id => r.acc, p_location_id => NULL, p_brand_id => NULL, p_severity => 'alto');
    END IF;

    IF r.fuga > 0 THEN
      SELECT string_agg(x.linea, E'\n' ORDER BY x.creada) INTO v_txt FROM (
        SELECT s.created_at AS creada,
               format('%s de %s (%s)', COALESCE(s.pos_short_code, s.platform_order_code, left(s.id::text,8)),
                 COALESCE(l.name,'sin local'),
                 to_char(s.created_at AT TIME ZONE 'Europe/Madrid','DD/MM HH24:MI')) AS linea
          FROM public.sale s LEFT JOIN public.locations l ON l.id = s.location_id
         WHERE s.account_id = r.acc AND s.id = ANY(v_fuga)
         ORDER BY s.created_at LIMIT 30) x;
      PERFORM public.encolar_alerta(
        p_kind => 'venta_cerrada_sin_descontar',
        p_subject => format('%s: %s pedido(s) cerrados no han descontado del almacén', r.cuenta, r.fuga),
        p_message => 'Cerrados hace más de 24 h, con escandallo que SÍ da renglones, y sin un solo '
                  || 'movimiento de consumo. Su comida salió del almacén y el almacén no se ha '
                  || 'enterado.' || E'\n' || COALESCE(v_txt,'') || E'\n\n'
                  || format('Arrastre anterior a 7 días en esta cuenta: %s ventas, contadas con la '
                         || 'vara BARATA (plato con ficha), no con la del motor: preguntarle al '
                         || 'escandallo por todas tardaba mas de 60 s. Es una cota alta, no una cifra '
                         || 'fina. No entran en la alarma porque sus ingredientes estan por debajo del '
                         || 'corte de su recuento y el motor no reescribe lo protegido.', r.arrastre)
                  || CASE WHEN r.arrastre_frio > 0 THEN E'\n'
                       || format('De ese arrastre, %s son ventas RECASADAS EN FRÍO el 23/09: tienen '
                              || 'plato y no van a descontar nunca, a propósito. No son avería. '
                              || 'Están en `sale_line_recast_frio`.', r.arrastre_frio)
                     ELSE '' END,
        p_debounce_kind => 'venta_cerrada_sin_descontar:' || r.acc::text,
        p_debounce_window => interval '24 hours',
        p_account_id => r.acc, p_location_id => NULL, p_brand_id => NULL, p_severity => 'critico');
    END IF;

    IF r.cobertura > 0 THEN
      PERFORM public.encolar_alerta(
        p_kind => 'ventas_sin_con_que_descontar',
        p_subject => format('%s: %s venta(s) de 7 dias no tenian con que descontar', r.cuenta, r.cobertura),
        p_message => 'NO es una fuga: es cobertura. Estas ventas se cerraron bien, pero su plato '
                  || 'no tiene escandallo, asi que no habia nada que descontar y el motor hizo lo '
                  || 'correcto escribiendo cero.' || E'\n'
                  || 'Se arregla poniendo la carta y los escandallos de esa cuenta, no tocando el '
                  || 'motor. Va una vez por semana a proposito: no es una averia.',
        p_debounce_kind => 'ventas_sin_con_que_descontar:' || r.acc::text,
        p_debounce_window => interval '7 days',
        p_account_id => r.acc, p_location_id => NULL, p_brand_id => NULL, p_severity => 'aviso');
    END IF;

    -- 5 · RECASADO EN FRIO. Casilla propia, no filtro (regla 7): estas ventas
    -- EXISTEN y su consumo no esta ni va a estar. Esconderlas seria decir
    -- «sin alertas» habiendo filas; contarlas como fuga seria llamar averia a
    -- una decision tomada.
    IF r.frio > 0 THEN
      SELECT string_agg(x.linea, E'\n' ORDER BY x.creada) INTO v_txt FROM (
        SELECT s.created_at AS creada,
               format('%s de %s (%s)', COALESCE(s.pos_short_code, s.platform_order_code, left(s.id::text,8)),
                 COALESCE(l.name,'sin local'),
                 to_char(s.created_at AT TIME ZONE 'Europe/Madrid','DD/MM HH24:MI')) AS linea
          FROM public.sale s LEFT JOIN public.locations l ON l.id = s.location_id
         WHERE s.account_id = r.acc AND s.id = ANY(v_frio)
         ORDER BY s.created_at LIMIT 30) x;
      PERFORM public.encolar_alerta(
        p_kind => 'venta_recasada_en_frio',
        p_subject => format('%s: %s venta(s) casadas en frío, sin consumo a propósito', r.cuenta, r.frio),
        p_message => 'NO es una fuga. Estas ventas se casaron con su plato hacia atrás el 23/09 '
                  || 'SIN generar consumo, por decisión de Julio: recuperar el casado sin '
                  || 'reprocesar stock por debajo del conteo aprobado.' || E'\n'
                  || 'Tienen plato y NUNCA van a tener movimiento de almacén. Eso no se recupera, '
                  || 'y cuadra en el siguiente recuento, no solo.' || E'\n'
                  || 'Cada línea está en `sale_line_recast_frio` con su vía y su importe.' || E'\n'
                  || 'Si una de estas aparece además como fuga, es que tiene OTRA línea sin '
                  || 'recasar: esa sí es avería y sale en el aviso crítico.' || E'\n'
                  || COALESCE(v_txt,''),
        p_debounce_kind => 'venta_recasada_en_frio:' || r.acc::text,
        p_debounce_window => interval '7 days',
        p_account_id => r.acc, p_location_id => NULL, p_brand_id => NULL, p_severity => 'aviso');
    END IF;

    -- La fuga y la cobertura NO se suman: son dos preguntas distintas. El
    -- frio tampoco: no es una averia, es una decision con nombre.
    v_total := v_total + r.viva + r.roto_total + r.fuga;
  END LOOP;
  RETURN v_total;
END;
$$;


--
-- Name: FUNCTION ventas_cerradas_sin_consumo_watchdog(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ventas_cerradas_sin_consumo_watchdog() IS 'Cuenta ventas SIN CONSUMO, lo intentara el motor o no — es el superconjunto que caza los silenciosos. Distinto de consumo_sin_descontar_watchdog, que cuenta ventas con un FALLO REGISTRADO. Tres cuentas que no se mezclan y UNA POR CUENTA (regla 9), sin la cuenta plantilla.';


--
-- Name: ventas_pendientes_al_aprobar(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ventas_pendientes_al_aprobar(p_count_id uuid, p_horas integer DEFAULT 72) RETURNS TABLE(ventas integer, euros numeric, articulos_afectados integer, detalle jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_acc uuid; v_loc uuid; v_items uuid[]; v_cand uuid[]; v_afect uuid[]; v_toca uuid[];
begin
  select ic.account_id, ic.location_id into v_acc, v_loc
    from public.inventory_count ic where ic.id = p_count_id;
  if v_acc is null then
    raise exception 'ventas_pendientes_al_aprobar: el recuento % no existe', p_count_id;
  end if;
  if not public.belongs_to_account(v_acc) then
    raise exception 'ventas_pendientes_al_aprobar: sin acceso a la cuenta %', v_acc;
  end if;

  -- Los articulos que este recuento va a cortar. Las excluidas no cortan.
  select coalesce(array_agg(distinct icl.recipe_item_id), '{}'::uuid[]) into v_items
    from public.inventory_count_line icl
   where icl.inventory_count_id = p_count_id and icl.account_id = v_acc
     and icl.excluded_at is null;

  if array_length(v_items, 1) is null then
    ventas := 0; euros := 0; articulos_afectados := 0; detalle := '[]'::jsonb;
    return next; return;
  end if;

  -- CANDIDATAS: ventas vivas del local sin consumo escrito todavia.
  -- Se saca a un ARRAY antes de preguntar al motor, por lo mismo que el vigia
  -- de ventas cerradas: como CTE, Postgres la incorpora y el lateral acaba
  -- colgando de `sale` entera (20.917 ms medidos el 12/09).
  select coalesce(array_agg(q.id), '{}'::uuid[]) into v_cand from (
    select s.id from public.sale s
      left join public._ventas_con_consumo() t on t.sale_id = s.id
     where s.account_id = v_acc and s.location_id = v_loc
       and s.created_at >= now() - make_interval(hours => greatest(coalesce(p_horas,72),1))
       and coalesce(s.status,'') <> 'cancelled'
       and coalesce(s.order_status,'') not in ('cancelled','rejected')
       and coalesce(s.is_active, true)
       and t.sale_id is null) q;

  if array_length(v_cand, 1) is null then
    ventas := 0; euros := 0; articulos_afectados := 0; detalle := '[]'::jsonb;
    return next; return;
  end if;

  -- LA VARA ES LA DEL MOTOR (regla 39), no una copia del escandallo: solo
  -- cuentan las ventas que de verdad tocarian un articulo de este recuento.
  select coalesce(array_agg(distinct sl.sale_id), '{}'::uuid[]),
         coalesce(array_agg(distinct r.raw_item_id), '{}'::uuid[])
    into v_afect, v_toca
  from public.sale_line sl
  cross join lateral public._sale_line_raw_consumption(sl.id) r
  where sl.sale_id = any(v_cand)
    and coalesce(sl.line_type,'product') = 'product'
    and sl.ignored_at is null
    and r.raw_item_id = any(v_items)
    and coalesce(r.qty_base,0) <> 0;

  select count(*)::integer, coalesce(round(sum(s.total),2),0) into ventas, euros
    from public.sale s where s.id = any(v_afect);
  articulos_afectados := coalesce(array_length(v_toca,1), 0);

  -- El detalle a un clic, como pide el encargo. Tope de 30: la pantalla no es
  -- un informe, y si hay mas de 30 el numero ya ha dicho lo que hacia falta.
  select coalesce(jsonb_agg(d.x order by d.orden), '[]'::jsonb) into detalle from (
    select s.created_at as orden, jsonb_build_object(
             'pedido', coalesce(s.pos_short_code, s.platform_order_code, left(s.id::text,8)),
             'cuando', to_char(s.created_at at time zone 'Europe/Madrid','DD/MM HH24:MI'),
             'euros',  round(s.total,2)) as x
      from public.sale s where s.id = any(v_afect)
      order by s.created_at limit 30) d;

  return next;
end;
$$;


--
-- Name: verifactu_anular_factura(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_anular_factura(p_invoice uuid, p_motivo text, p_confirmacion text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.customer_invoice; v_a public.verifactu_registro; v_reg public.verifactu_registro; v_p jsonb; v_c jsonb; v_sin boolean;
  v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
begin
  select * into v_f from public.customer_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  -- Como anular un asiento: solo un administrador.
  if not public.current_user_is_admin_of(v_f.account_id) then
    raise exception 'Solo un administrador de la cuenta anula una factura emitida.' using errcode = '42501';
  end if;
  v_p := public.verifactu_previsto(p_invoice, 'anular');
  if not coalesce((v_p->>'puede')::boolean, false) then raise exception '%', v_p->>'frase' using errcode = '23514'; end if;
  if p_motivo is null or length(btrim(p_motivo)) = 0 then raise exception 'Para anular la % hay que decir por qué.', v_f.number_text using errcode = '23514'; end if;
  if p_confirmacion is distinct from 'ANULAR' then
    raise exception 'Para anular la %, escribe ANULAR: no se puede deshacer.', v_f.number_text using errcode = '23514';
  end if;
  v_a := public._verifactu_ultima_alta(p_invoice);
  v_sin := v_a.estado = 'incorrecto' and not exists (select 1 from public.verifactu_registro where invoice_id = p_invoice and tipo = 'alta'
                                                       and estado in ('correcto', 'aceptado_con_errores'));
  v_c := public._verifactu_contrasiento(v_f.entry_id, 'factura ' || v_f.number_text || ' anulada (no tenía que emitirse): ' || btrim(p_motivo), v_quien);
  update public.customer_invoice set status = 'anulada' where id = p_invoice;
  -- El registro de anulación, encadenado tras el último de su NIF. Si Hacienda
  -- no tiene el alta (la rechazó y no se subsanó), «sin registro previo».
  v_reg := public._verifactu_registrar(jsonb_build_object(
    'account_id', v_a.account_id, 'company_id', v_a.company_id, 'entorno', v_a.entorno, 'tipo', 'anulacion', 'origen', v_a.origen,
    'invoice_id', v_a.invoice_id, 'alta_id', v_a.id, 'sin_registro_previo', v_sin,
    'nif_emisor', v_a.nif_emisor, 'nombre_emisor', v_a.nombre_emisor, 'num_serie', v_a.num_serie, 'fecha_expedicion', v_a.fecha_expedicion,
    'quien', v_quien));
  perform public._conta_venta_evento(p_invoice, 'anulada',
    'Anulada: no tenía que emitirse (' || btrim(p_motivo) || '). Su asiento nº ' || coalesce(v_c->>'numero_anulado', '?') || ' queda deshecho con el nº '
      || coalesce(v_c->>'numero', '?') || ', y Hacienda recibe su registro de anulación.',
    jsonb_build_object('registro', v_reg.id, 'contraasiento', v_c->>'contraasiento'), v_quien);
  return jsonb_build_object('numero', v_f.number_text, 'registro_id', v_reg.id, 'estado', v_reg.estado, 'sin_registro_previo', v_reg.sin_registro_previo,
    'contraasiento', v_c->>'contraasiento', 'numero_contraasiento', v_c->'numero', 'numero_anulado', v_c->'numero_anulado');
end $$;


--
-- Name: FUNCTION verifactu_anular_factura(p_invoice uuid, p_motivo text, p_confirmacion text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_anular_factura(p_invoice uuid, p_motivo text, p_confirmacion text, p_quien_nombre text) IS 'V03 E3 · «No tenía que haberla emitido»: la factura queda anulada, su asiento se deshace con un contrasiento del mismo día y Hacienda recibe su registro de anulación (encadenado; «sin registro previo» si la había rechazado). Solo un administrador, escribiendo ANULAR, con el motivo, y si verifactu_previsto dice que puede: sin cobros, sin rectificativa y con el mes abierto.';


--
-- Name: verifactu_autorizar_certificado(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_autorizar_certificado(p_company uuid, p_certificate uuid, p_confirmacion text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_co public.company; c public.tax_certificate; v_nif text; v_ant public.verifactu_autorizacion; v_id uuid;
  v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
begin
  if auth.uid() is null then raise exception 'Tienes que entrar con tu usuario.' using errcode = '42501'; end if;
  select * into v_co from public.company where id = p_company;
  if v_co.id is null or not public.belongs_to_account(v_co.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_co.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta autoriza el certificado.' using errcode = '42501';
  end if;
  if p_confirmacion is distinct from 'AUTORIZO' then
    raise exception 'Para autorizar, escribe AUTORIZO: el certificado se usará, sin preguntarte cada vez, solo para enviar a Hacienda los registros de Verifactu.' using errcode = '23514';
  end if;
  select * into c from public.tax_certificate where id = p_certificate and owner_account_id = v_co.account_id;
  if c.id is null then raise exception 'Ese certificado no está en esta cuenta.' using errcode = 'P0002'; end if;
  if c.status <> 'active' then raise exception 'Ese certificado no está en uso (%): sube uno en vigor.', c.status using errcode = '22023'; end if;
  if c.valid_to <= now() then raise exception 'Ese certificado caducó el %: sube uno nuevo.', to_char(c.valid_to at time zone 'Europe/Madrid', 'DD/MM/YYYY') using errcode = '22023'; end if;
  if not public.conta_cert_puede_usar(auth.uid(), c.id) then
    raise exception 'No tienes permiso para presentar con este certificado: lo autoriza quien puede presentar con él.' using errcode = '42501';
  end if;
  v_nif := regexp_replace(upper(coalesce(v_co.tax_id, '')), '^ES', '');
  if c.subject_tax_id_hash is distinct from encode(sha256(convert_to(v_nif, 'UTF8')), 'hex') then
    raise exception 'Ese certificado es de otro NIF (acaba en %), no del de %.', c.subject_tax_id_tail, coalesce(v_co.trade_name, v_co.legal_name) using errcode = '23514';
  end if;
  -- Una vigente por empresa: la de antes (otro certificado, o la misma renovada) se retira.
  select * into v_ant from public.verifactu_autorizacion where company_id = p_company and retirada_at is null for update;
  if v_ant.id is not null then
    update public.verifactu_autorizacion set retirada_at = now(), retirada_por = auth.uid(), retirada_por_nombre = v_quien,
           retirada_motivo = 'Sustituida por una autorización nueva.'
     where id = v_ant.id;
  end if;
  insert into public.verifactu_autorizacion (account_id, company_id, certificate_id, autorizada_por, autorizada_por_nombre)
  values (v_co.account_id, p_company, c.id, auth.uid(), v_quien) returning id into v_id;
  insert into public.verifactu_empresa (company_id, account_id, via, certificate_id, updated_by_name)
  values (p_company, v_co.account_id, 'certificado', c.id, v_quien)
  on conflict (company_id) do update set via = 'certificado', certificate_id = c.id, updated_at = now(), updated_by_name = v_quien;
  return jsonb_build_object('id', v_id, 'certificado_acaba_en', c.subject_tax_id_tail, 'caduca', c.valid_to, 'sustituye', v_ant.id);
end $$;


--
-- Name: FUNCTION verifactu_autorizar_certificado(p_company uuid, p_certificate uuid, p_confirmacion text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_autorizar_certificado(p_company uuid, p_certificate uuid, p_confirmacion text, p_quien_nombre text) IS 'V03. La empresa autoriza, una vez y escribiendo AUTORIZO, usar su certificado solo para enviar Verifactu. Lo hace quien puede presentar con ese certificado; tiene que ser del NIF de la empresa. Sustituye a la vigente, si la hay, y pone la vía del certificado.';


--
-- Name: verifactu_aviso_certificado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_aviso_certificado() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v record; v_n int := 0;
begin
  for v in
    select e.account_id, e.company_id, coalesce(c.legal_name, c.trade_name) as empresa, t.valid_to, e.certificate_id
      from public.verifactu_empresa e
      join public.company c on c.id = e.company_id and c.account_id = e.account_id
      left join public.tax_certificate t on t.id = e.certificate_id and t.removed_at is null
     where e.modo = 'real' and (t.id is null or t.valid_to < now() + interval '30 days')
  loop
    perform public.encolar_alerta(
      p_kind := 'verifactu_certificado',
      p_subject := case when v.valid_to is null then 'Verifactu: ' || v.empresa || ' no tiene certificado para enviar a Hacienda'
                        when v.valid_to < now() then 'Verifactu: el certificado de ' || v.empresa || ' ha caducado'
                        else 'Verifactu: el certificado de ' || v.empresa || ' caduca el ' || to_char(v.valid_to at time zone 'Europe/Madrid', 'DD/MM/YYYY') end,
      p_message := 'Sin un certificado en vigor, las facturas de ' || v.empresa || ' se quedan en la cola y no llegan a Hacienda. Sube el nuevo en Ajustes › Certificado.',
      p_debounce_kind := 'verifactu_certificado:' || v.company_id,
      p_debounce_window := interval '1 day',
      p_account_id := v.account_id,
      p_location_id := null, p_brand_id := null,
      p_severity := case when v.valid_to is null or v.valid_to < now() + interval '7 days' then 'alto' else 'aviso' end);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


--
-- Name: FUNCTION verifactu_aviso_certificado(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_aviso_certificado() IS 'V03 · Cada día (cron verifactu-aviso-certificado): un aviso por empresa con Verifactu en real cuyo certificado caduca en 30 días o menos, ha caducado o no está. Devuelve cuántos avisos ha encolado.';


--
-- Name: verifactu_cert_abrir(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cert_abrir(p_envio uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e public.verifactu_envio; v_emp public.verifactu_empresa; v_a public.verifactu_autorizacion; c public.tax_certificate; v_material text; v_motivo text;
begin
  select * into v_e from public.verifactu_envio where id = p_envio for update;
  if v_e.id is null then return jsonb_build_object('ok', false, 'mensaje', 'Ese envío no está.'); end if;
  select * into v_emp from public.verifactu_empresa where company_id = v_e.company_id;
  select * into v_a from public.verifactu_autorizacion where company_id = v_e.company_id and retirada_at is null;
  select * into c from public.tax_certificate where id = v_a.certificate_id;
  v_motivo := case
    when v_e.entorno <> 'real' then 'Solo se abre el certificado de la empresa para enviar en real.'
    when v_emp.via is distinct from 'certificado' then 'La empresa envía por la vía de colaborador social, que todavía no está abierta.'
    when v_a.id is null then 'La empresa no ha autorizado usar su certificado para Verifactu (o lo ha retirado).'
    when c.id is null or c.status = 'removed' then 'El certificado autorizado se ha quitado: autoriza uno nuevo.'
    when c.valid_to <= now() then 'El certificado autorizado ha caducado: sube uno nuevo y autorízalo.'
    when c.storage <> 'vault' then 'El certificado está en el almacén con clave externa (KMS), que todavía no está preparado.'
    else null end;
  if v_motivo is not null then return jsonb_build_object('ok', false, 'mensaje', v_motivo); end if;
  select decrypted_secret into v_material from vault.decrypted_secrets where id = c.vault_secret_id;
  if v_material is null then return jsonb_build_object('ok', false, 'mensaje', 'El certificado no está en el almacén: vuelve a subirlo.'); end if;
  update public.verifactu_envio set autorizacion_id = v_a.id where id = p_envio;
  return jsonb_build_object('ok', true, 'material', v_material, 'autorizacion_id', v_a.id);
end $$;


--
-- Name: FUNCTION verifactu_cert_abrir(p_envio uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_cert_abrir(p_envio uuid) IS 'V03. Solo la clave de servicio (conta-verifactu): abre el certificado de la empresa para UN envío de Verifactu en real, si la empresa lo ha autorizado y sigue en vigor, y apunta la autorización en el envío. Para nada más.';


--
-- Name: verifactu_cert_abrir_cuadre(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cert_abrir_cuadre(p_cuadre uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_c public.verifactu_cuadre; v_emp public.verifactu_empresa; v_a public.verifactu_autorizacion; c public.tax_certificate; v_material text; v_motivo text;
begin
  select * into v_c from public.verifactu_cuadre where id = p_cuadre;
  if v_c.id is null then return jsonb_build_object('ok', false, 'mensaje', 'Ese cuadre no está.'); end if;
  select * into v_emp from public.verifactu_empresa where company_id = v_c.company_id;
  select * into v_a from public.verifactu_autorizacion where company_id = v_c.company_id and retirada_at is null;
  select * into c from public.tax_certificate where id = v_a.certificate_id;
  v_motivo := case
    when v_c.entorno <> 'real' then 'Solo se abre el certificado de la empresa para consultar en real.'
    when v_emp.via is distinct from 'certificado' then 'La empresa envía por la vía de colaborador social, que todavía no está abierta.'
    when v_a.id is null then 'La empresa no ha autorizado usar su certificado para Verifactu (o lo ha retirado).'
    when c.id is null or c.status = 'removed' then 'El certificado autorizado se ha quitado: autoriza uno nuevo.'
    when c.valid_to <= now() then 'El certificado autorizado ha caducado: sube uno nuevo y autorízalo.'
    when c.storage <> 'vault' then 'El certificado está en el almacén con clave externa (KMS), que todavía no está preparado.'
    else null end;
  if v_motivo is not null then return jsonb_build_object('ok', false, 'mensaje', v_motivo); end if;
  select decrypted_secret into v_material from vault.decrypted_secrets where id = c.vault_secret_id;
  if v_material is null then return jsonb_build_object('ok', false, 'mensaje', 'El certificado no está en el almacén: vuelve a subirlo.'); end if;
  return jsonb_build_object('ok', true, 'material', v_material, 'autorizacion_id', v_a.id);
end $$;


--
-- Name: FUNCTION verifactu_cert_abrir_cuadre(p_cuadre uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_cert_abrir_cuadre(p_cuadre uuid) IS 'V03 E3. Solo la clave de servicio (conta-verifactu): abre el certificado de la empresa para UNA consulta de «Comprobar con Hacienda» en real, con las mismas condiciones que verifactu_cert_abrir para un envío. Para nada más.';


--
-- Name: verifactu_cola_fallo(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cola_fallo(p_envio uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n int;
begin
  update public.verifactu_envio set terminado_at = now(), estado_envio = 'fallo', error = left(p_error, 2000) where id = p_envio;
  update public.verifactu_registro set estado = 'pendiente',
         proximo_intento_at = now() + least(interval '60 minutes', make_interval(mins => power(2, least(intentos, 6))::int))
   where envio_id = p_envio and estado = 'enviando';
  get diagnostics v_n = row_count;
  return jsonb_build_object('envio_id', p_envio, 'vuelven_a_la_cola', v_n);
end $$;


--
-- Name: verifactu_cola_respuesta(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cola_respuesta(p_envio uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_e public.verifactu_envio; v_x jsonb; v_n int := 0; v_sin int;
begin
  select * into v_e from public.verifactu_envio where id = p_envio for update;
  if v_e.id is null then raise exception 'Ese envío no está.' using errcode = 'P0002'; end if;
  update public.verifactu_envio set terminado_at = now(), http_status = (p->>'http_status')::int, estado_envio = p->>'estado_envio',
         tiempo_espera_s = (p->>'tiempo_espera_s')::int, csv = p->>'csv', respuesta = left(p->>'respuesta', 20000)
   where id = p_envio;
  for v_x in select * from jsonb_array_elements(coalesce(p->'registros', '[]'::jsonb)) loop
    update public.verifactu_registro set
           estado = case v_x->>'estado' when 'Correcto' then 'correcto' when 'AceptadoConErrores' then 'aceptado_con_errores' else 'incorrecto' end,
           codigo_error = nullif(v_x->>'codigo', '')::int, descripcion_error = nullif(v_x->>'descripcion', ''),
           csv = p->>'csv', respondido_at = now()
     where id = (v_x->>'id')::uuid and envio_id = p_envio;
    v_n := v_n + 1;
  end loop;
  -- Lo que no vino en la respuesta vuelve a la cola (no se da nada por enviado sin su respuesta).
  update public.verifactu_registro set estado = 'pendiente', proximo_intento_at = now() + interval '1 minute'
   where envio_id = p_envio and estado = 'enviando';
  get diagnostics v_sin = row_count;
  if (p->>'tiempo_espera_s') is not null then
    insert into public.verifactu_flujo (nif_emisor, entorno, tiempo_espera_s, ultimo_envio_at) values (v_e.nif_emisor, v_e.entorno, (p->>'tiempo_espera_s')::int, v_e.empezado_at)
    on conflict (nif_emisor, entorno) do update set tiempo_espera_s = excluded.tiempo_espera_s;
  end if;
  return jsonb_build_object('envio_id', p_envio, 'registros', v_n, 'vuelven_a_la_cola', v_sin);
end $$;


--
-- Name: verifactu_cola_tomar(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cola_tomar(p_entorno text, p_max integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nif text; v_envio uuid; v_cuenta uuid; v_empresa uuid; v_ids uuid[]; v_n int;
begin
  select r.nif_emisor into v_nif
    from public.verifactu_registro r
    left join public.verifactu_flujo f on f.nif_emisor = r.nif_emisor and f.entorno = r.entorno
   where r.entorno = p_entorno and r.estado = 'pendiente' and r.proximo_intento_at <= now()
   group by r.nif_emisor, f.ultimo_envio_at, f.tiempo_espera_s
  having f.ultimo_envio_at is null or f.ultimo_envio_at + make_interval(secs => coalesce(f.tiempo_espera_s, 60)) <= now() or count(*) >= 1000
   order by min(r.generado_at) limit 1;
  if v_nif is null then return null; end if;
  select array_agg(id order by generado_at, id), (array_agg(account_id))[1], (array_agg(company_id))[1] into v_ids, v_cuenta, v_empresa
    from (select id, account_id, company_id, generado_at from public.verifactu_registro
           where entorno = p_entorno and nif_emisor = v_nif and estado = 'pendiente' and proximo_intento_at <= now()
           order by generado_at, id limit least(greatest(coalesce(p_max, 1000), 1), 1000) for update skip locked) x;
  v_n := coalesce(array_length(v_ids, 1), 0);
  if v_n = 0 then return null; end if;
  insert into public.verifactu_envio (account_id, company_id, entorno, nif_emisor, registros) values (v_cuenta, v_empresa, p_entorno, v_nif, v_n) returning id into v_envio;
  update public.verifactu_registro set estado = 'enviando', envio_id = v_envio, intentos = intentos + 1 where id = any(v_ids);
  insert into public.verifactu_flujo (nif_emisor, entorno, ultimo_envio_at) values (v_nif, p_entorno, now())
  on conflict (nif_emisor, entorno) do update set ultimo_envio_at = now();
  return jsonb_build_object('envio_id', v_envio, 'entorno', p_entorno, 'nif_emisor', v_nif, 'company_id', v_empresa,
    'registros', (select jsonb_agg(to_jsonb(r) order by r.generado_at, r.id) from public.verifactu_registro r where r.id = any(v_ids)));
end $$;


--
-- Name: verifactu_comprobar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_comprobar(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.customer_invoice; v_e public.verifactu_empresa; v_emisor public.company; v_d jsonb; v_faltas jsonb;
  v_pais text; v_nif text; v_hoy date := (now() at time zone 'Europe/Madrid')::date;
begin
  select * into v_f from public.customer_invoice where id = p_invoice;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  select * into v_e from public.verifactu_empresa where company_id = v_f.company_id;
  if v_e.company_id is null or v_e.modo = 'apagado' then
    return jsonb_build_object('va', false, 'motivo', 'apagado', 'faltas', '[]'::jsonb);
  end if;
  if v_f.origin = 'cierre_dia' then
    -- Respuesta 1 de Julio (25/10): los cierres del día no se registran mientras el asesor no conteste.
    return jsonb_build_object('va', false, 'motivo', 'cierre_dia', 'faltas', '[]'::jsonb);
  end if;
  select * into v_emisor from public.company where id = v_f.company_id;
  v_d := public._verifactu_desglose(p_invoice);
  v_faltas := v_d->'faltas';
  if not public._verifactu_nif_es_valido(v_emisor.tax_id) then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'empresa_nif', 'codigo_aeat', 4109,
      'frase', 'El NIF de tu empresa (' || coalesce(v_emisor.tax_id, 'vacío') || ') no es un NIF válido: corrígelo en Ajustes › Tu empresa.'));
  end if;
  if v_f.issue_date > v_hoy then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'fecha', 'codigo_aeat', 1112,
      'frase', 'La fecha de la factura es de un día que aún no ha llegado (' || to_char(v_f.issue_date, 'DD/MM/YYYY') || ').'));
  end if;
  if v_e.modo = 'real' and v_f.issue_date < (v_e.real_desde at time zone 'Europe/Madrid')::date then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'fecha', 'codigo_aeat', null,
      'frase', 'Verifactu está en real desde el ' || to_char(v_e.real_desde at time zone 'Europe/Madrid', 'DD/MM/YYYY') || ': una factura nueva no puede llevar una fecha de antes.'));
  end if;
  if v_e.modo = 'real' and v_f.doc_type <> 'rectificativa' and v_f.series_code is distinct from v_e.real_serie then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'serie', 'codigo_aeat', null,
      'frase', 'La serie ' || coalesce(v_f.series_code, '—') || ' se cerró al pasar a real: las facturas nuevas van en la ' || v_e.real_serie || '.'));
  end if;
  -- El destinatario (§3.1.3.13): una completa lo lleva, con NIF español válido o la identificación de su país.
  v_pais := upper(coalesce(nullif(btrim(v_f.customer->>'pais'), ''), 'ES'));
  v_nif := upper(regexp_replace(coalesce(v_f.customer->>'nif', ''), '[\s.\-_/]', '', 'g'));
  if coalesce(btrim(v_f.customer->>'nombre'), '') = '' then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'cliente', 'codigo_aeat', 1189, 'frase', 'Falta el nombre del cliente: una factura completa lo lleva.'));
  end if;
  if v_nif = '' then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'cliente_nif', 'codigo_aeat', 1189, 'frase', 'Falta el NIF del cliente: una factura completa lo lleva.'));
  elsif v_pais = 'ES' and not public._verifactu_nif_es_valido(v_nif) then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'cliente_nif', 'codigo_aeat', 1100,
      'frase', 'El NIF del cliente (' || v_nif || ') no es un NIF español válido: revísalo en su ficha.'));
  elsif v_pais <> 'ES' and public._verifactu_es_ue(v_pais) and not public._verifactu_nif_iva_ue_valido(v_pais, v_nif) then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'cliente_nif', 'codigo_aeat', 1222,
      'frase', 'El NIF-IVA del cliente (' || v_nif || ') no tiene la forma de los de ' || v_pais || ': revísalo en su ficha.'));
  end if;
  if not exists (select 1 from jsonb_array_elements(v_d->'desglose')) and jsonb_array_length(v_faltas) = 0 then
    v_faltas := v_faltas || jsonb_build_array(jsonb_build_object('campo', 'lineas', 'codigo_aeat', null, 'frase', 'La factura no tiene ninguna línea que enviar.'));
  end if;
  return jsonb_build_object('va', true, 'entorno', v_e.modo, 'faltas', v_faltas, 'desglose', v_d->'desglose',
                            'cuota_total', v_d->'cuota_total', 'importe_total', v_d->'importe_total');
end $$;


--
-- Name: FUNCTION verifactu_comprobar(p_invoice uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_comprobar(p_invoice uuid) IS 'V03. Lo que Hacienda rechazaría de esta factura, antes de emitirla: una lista de {campo, codigo_aeat, frase}. La usan la pantalla (para señalar el campo) y el disparador de la emisión (para no emitirla). va = false: no pasa por Verifactu (apagado, o un cierre del día).';


--
-- Name: verifactu_comprobar_cadena(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_comprobar_cadena(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_co public.company; v_nif text; v_ent text; r public.verifactu_registro; v_prev public.verifactu_registro; v_cad public.verifactu_cadena;
  v_esperada text; v_problemas jsonb; v_n int; v_otras int; v_ns text; v_ns_prev text; v_out jsonb := '[]'::jsonb; v_mal int := 0; v_total int := 0;
  v_primera timestamptz; v_ultima timestamptz;
begin
  select * into v_co from public.company where id = p_company;
  if v_co.id is null or not public.belongs_to_account(v_co.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  v_nif := regexp_replace(upper(coalesce(v_co.tax_id, '')), '^ES', '');
  foreach v_ent in array array['real', 'pruebas'] loop
    v_problemas := '[]'::jsonb; v_n := 0; v_otras := 0; v_prev := null; v_ns_prev := null; v_primera := null; v_ultima := null;
    for r in select * from public.verifactu_registro where nif_emisor = v_nif and entorno = v_ent order by generado_at, id loop
      v_n := v_n + 1;
      if r.company_id <> p_company then v_otras := v_otras + 1; end if;
      -- De otra empresa con el mismo NIF (otra cuenta): sin su número.
      v_ns := case when r.company_id = p_company then r.num_serie else 'una factura de otra empresa con este NIF' end;
      v_primera := coalesce(v_primera, r.generado_at); v_ultima := r.generado_at;
      v_esperada := case r.tipo
        when 'alta' then public._verifactu_cadena_alta(r.nif_emisor, r.num_serie, public._verifactu_fecha(r.fecha_expedicion), r.tipo_factura,
                           public._verifactu_importe(r.cuota_total), public._verifactu_importe(r.importe_total), r.huella_anterior, r.fecha_hora_huso)
        else public._verifactu_cadena_anulacion(r.nif_emisor, r.num_serie, public._verifactu_fecha(r.fecha_expedicion), r.huella_anterior, r.fecha_hora_huso) end;
      if r.cadena_huella is distinct from v_esperada then
        v_problemas := v_problemas || jsonb_build_array(jsonb_build_object('registro', r.id, 'num_serie', v_ns, 'tipo', r.tipo, 'que', 'tocado',
          'frase', 'Lo que guarda el registro de la ' || v_ns || ' no es lo que entró en su huella: se ha tocado después de generarlo.'));
      end if;
      if public._verifactu_sha256(r.cadena_huella) is distinct from r.huella then
        v_problemas := v_problemas || jsonb_build_array(jsonb_build_object('registro', r.id, 'num_serie', v_ns, 'tipo', r.tipo, 'que', 'huella',
          'frase', 'La huella del registro de la ' || v_ns || ' no es la de sus datos.'));
      end if;
      if v_prev.id is null then
        if not r.primer_registro or r.huella_anterior is not null then
          v_problemas := v_problemas || jsonb_build_array(jsonb_build_object('registro', r.id, 'num_serie', v_ns, 'tipo', r.tipo, 'que', 'falta_anterior',
            'frase', 'El primer registro que hay (' || v_ns || ') dice que tiene otro antes: falta el principio de la cadena.'));
        end if;
      elsif r.primer_registro or r.huella_anterior is distinct from v_prev.huella or r.anterior_id is distinct from v_prev.id then
        v_problemas := v_problemas || jsonb_build_array(jsonb_build_object('registro', r.id, 'num_serie', v_ns, 'tipo', r.tipo, 'que', 'no_sigue',
          'frase', 'El registro de la ' || v_ns || ' no sigue al de la ' || coalesce(v_ns_prev, '—') || ': falta uno entre los dos, o se ha tocado.'));
      end if;
      if r.fecha_hora_huso is distinct from public._verifactu_fecha_hora_huso(r.generado_at) or (v_prev.id is not null and r.generado_at <= v_prev.generado_at) then
        v_problemas := v_problemas || jsonb_build_array(jsonb_build_object('registro', r.id, 'num_serie', v_ns, 'tipo', r.tipo, 'que', 'hora',
          'frase', 'La hora del registro de la ' || v_ns || ' no es la de cuando se generó, o va antes que el anterior.'));
      end if;
      v_prev := r; v_ns_prev := v_ns;
    end loop;
    select * into v_cad from public.verifactu_cadena where nif_emisor = v_nif and entorno = v_ent;
    if v_cad.nif_emisor is not null or v_n > 0 then
      if coalesce(v_cad.registros, 0) <> v_n or v_cad.ultima_huella is distinct from v_prev.huella or v_cad.ultimo_registro_id is distinct from v_prev.id then
        v_problemas := v_problemas || jsonb_build_array(jsonb_build_object('registro', null, 'num_serie', null, 'tipo', null, 'que', 'cuenta',
          'frase', 'La cadena dice que tiene ' || coalesce(v_cad.registros, 0) || ' registros, y hay ' || v_n
            || case when v_cad.ultimo_registro_id is distinct from v_prev.id then ': no termina en el último que hay' else '' end || '.'));
      end if;
      v_mal := v_mal + jsonb_array_length(v_problemas); v_total := v_total + v_n;
      v_out := v_out || jsonb_build_array(jsonb_build_object('entorno', v_ent, 'nif', v_nif, 'registros', v_n, 'de_otras_empresas', v_otras,
        'desde', v_primera, 'hasta', v_ultima, 'ok', jsonb_array_length(v_problemas) = 0,
        'problemas', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select x from jsonb_array_elements(v_problemas) x limit 50) y),
        'problemas_total', jsonb_array_length(v_problemas)));
    end if;
  end loop;
  return jsonb_build_object('ok', v_mal = 0, 'registros', v_total, 'problemas', v_mal, 'cadenas', v_out, 'comprobada_at', now(),
    'frase', case
      when v_total = 0 then 'Todavía no hay ningún registro de Verifactu de ' || coalesce(v_co.trade_name, v_co.legal_name) || ': no hay cadena que comprobar.'
      when v_mal = 0 then 'La cadena está entera: ' || v_total || case when v_total = 1 then ' registro' else ' registros' end
        || ', cada uno con la huella de sus datos y detrás del anterior. No falta ninguno ni se ha tocado ninguno.'
      else 'La cadena tiene ' || v_mal || case when v_mal = 1 then ' problema' else ' problemas' end || ' en ' || v_total || ' registros: abajo, cuál y dónde.' end);
end $$;


--
-- Name: FUNCTION verifactu_comprobar_cadena(p_company uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_comprobar_cadena(p_company uuid) IS 'V03 E3 · «Comprobar la cadena» (Ajustes › Verifactu): recorre las cadenas de la empresa (su NIF, en real y en pruebas) y dice si falta algún registro o se ha tocado alguno: huella = SHA-256 de lo guardado, lo guardado = lo que sale de sus campos, cada uno detrás del anterior, y la cadena cuenta lo mismo. Solo lee.';


--
-- Name: verifactu_conexion_apuntar(text, text, boolean, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_conexion_apuntar(p_entorno text, p_nif text, p_ok boolean, p_codigo integer, p_mensaje text, p_origen text) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.verifactu_conexion (entorno, nif, ok, codigo, mensaje, origen)
  values (p_entorno, regexp_replace(upper(btrim(p_nif)), '^ES', ''), p_ok, p_codigo, left(p_mensaje, 1000), p_origen)
  returning id
$$;


--
-- Name: FUNCTION verifactu_conexion_apuntar(p_entorno text, p_nif text, p_ok boolean, p_codigo integer, p_mensaje text, p_origen text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_conexion_apuntar(p_entorno text, p_nif text, p_ok boolean, p_codigo integer, p_mensaje text, p_origen text) IS 'V03. Solo el servicio: apunta una prueba de conexión con la AEAT (la abre o la mantiene cerrada para verifactu_modo).';


--
-- Name: verifactu_conexion_probada(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_conexion_probada(p_entorno text, p_nif text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.verifactu_conexion c
                  where c.ok and c.entorno = p_entorno
                    and (p_entorno = 'pruebas' or c.nif = regexp_replace(upper(btrim(coalesce(p_nif, ''))), '^ES', '')))
$$;


--
-- Name: FUNCTION verifactu_conexion_probada(p_entorno text, p_nif text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_conexion_probada(p_entorno text, p_nif text) IS 'V03. ¿Hay una prueba de conexión correcta con la AEAT? En pruebas, cualquiera del entorno de pruebas; en real, una de real con ese NIF. La usa verifactu_modo (el candado) y la pantalla, para decir por qué no deja.';


--
-- Name: verifactu_cuadre_fallo(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cuadre_fallo(p_cuadre uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.verifactu_cuadre set estado = 'fallo', terminado_at = now(), error = left(p_error, 2000) where id = p_cuadre and estado in ('pedido', 'consultando');
  return jsonb_build_object('cuadre_id', p_cuadre, 'fallo', true);
end $$;


--
-- Name: verifactu_cuadre_pagina(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cuadre_pagina(p_cuadre uuid, p_registros jsonb, p_final boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_c public.verifactu_cuadre; v_x jsonb; v_n int := 0; v_res jsonb;
begin
  select * into v_c from public.verifactu_cuadre where id = p_cuadre for update;
  if v_c.id is null then raise exception 'Ese cuadre no está.' using errcode = 'P0002'; end if;
  if v_c.estado <> 'consultando' then raise exception 'Ese cuadre no se está consultando (está %).', v_c.estado using errcode = '23514'; end if;
  for v_x in select * from jsonb_array_elements(coalesce(p_registros, '[]'::jsonb)) loop
    insert into public.verifactu_cuadre_hacienda (cuadre_id, account_id, num_serie, fecha_expedicion, tipo_factura, cuota_total, importe_total, huella,
      estado, codigo_error, descripcion_error, modificado_at)
    values (p_cuadre, v_c.account_id, v_x->>'num_serie', (v_x->>'fecha')::date, nullif(v_x->>'tipo_factura', ''), nullif(v_x->>'cuota_total', '')::numeric,
      nullif(v_x->>'importe_total', '')::numeric, nullif(upper(v_x->>'huella'), ''), v_x->>'estado', nullif(v_x->>'codigo', '')::int,
      left(nullif(v_x->>'descripcion', ''), 500), nullif(v_x->>'modificado', '')::timestamptz)
    on conflict (cuadre_id, num_serie, fecha_expedicion) do update set tipo_factura = excluded.tipo_factura, cuota_total = excluded.cuota_total,
      importe_total = excluded.importe_total, huella = excluded.huella, estado = excluded.estado, codigo_error = excluded.codigo_error,
      descripcion_error = excluded.descripcion_error, modificado_at = excluded.modificado_at;
    v_n := v_n + 1;
  end loop;
  update public.verifactu_cuadre set paginas = paginas + 1 where id = p_cuadre;
  if p_final then
    v_res := public._verifactu_cuadrar(p_cuadre);
    update public.verifactu_cuadre set estado = 'hecho', terminado_at = now(), resultado = v_res where id = p_cuadre;
  end if;
  return jsonb_build_object('cuadre_id', p_cuadre, 'registros', v_n, 'final', p_final);
end $$;


--
-- Name: verifactu_cuadre_pedir(uuid, date, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cuadre_pedir(p_company uuid, p_mes date, p_desde_account uuid DEFAULT NULL::uuid, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_co public.company; v_e public.verifactu_empresa; v_c public.verifactu_cuadre; v_mes date := date_trunc('month', p_mes)::date;
begin
  if p_mes is null then raise exception 'Dime de qué mes.' using errcode = '22023'; end if;
  select * into v_co from public.company where id = p_company;
  if v_co.id is null or not public._verifactu_puede_cuadrar(p_company, p_desde_account) then
    raise exception 'Esa empresa no está, o no la puedes comprobar.' using errcode = '42501';
  end if;
  select * into v_e from public.verifactu_empresa where company_id = p_company;
  if v_e.company_id is null or v_e.modo = 'apagado' then
    raise exception 'Verifactu está apagado en %: no hay nada que comprobar con Hacienda.', coalesce(v_co.trade_name, v_co.legal_name) using errcode = '23514';
  end if;
  if v_mes > date_trunc('month', now() at time zone 'Europe/Madrid')::date then
    raise exception 'Ese mes aún no ha llegado.' using errcode = '23514';
  end if;
  if v_mes < date '2024-10-01' then raise exception 'Verifactu empieza en octubre de 2024: no hay nada antes.' using errcode = '23514'; end if;
  -- Si ya hay uno de ese mes esperando, ese mismo (no se pregunta dos veces).
  select * into v_c from public.verifactu_cuadre where company_id = p_company and entorno = v_e.modo and estado in ('pedido', 'consultando')
     and ejercicio = extract(year from v_mes)::int and periodo = to_char(v_mes, 'MM') order by pedido_at desc limit 1;
  if v_c.id is not null then
    return jsonb_build_object('id', v_c.id, 'ya_estaba', true, 'entorno', v_c.entorno, 'estado', v_c.estado);
  end if;
  insert into public.verifactu_cuadre (account_id, company_id, pedido_por_account, entorno, nif_emisor, nombre_emisor, ejercicio, periodo, pedido_por_nombre)
  values (v_co.account_id, v_co.id, coalesce(p_desde_account, v_co.account_id), v_e.modo, regexp_replace(upper(v_co.tax_id), '^ES', ''),
          coalesce(v_co.legal_name, v_co.trade_name), extract(year from v_mes)::int, to_char(v_mes, 'MM'), coalesce(p_quien_nombre, public.conta_nombre_actor()))
  returning * into v_c;
  return jsonb_build_object('id', v_c.id, 'ya_estaba', false, 'entorno', v_c.entorno, 'estado', v_c.estado);
end $$;


--
-- Name: FUNCTION verifactu_cuadre_pedir(p_company uuid, p_mes date, p_desde_account uuid, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_cuadre_pedir(p_company uuid, p_mes date, p_desde_account uuid, p_quien_nombre text) IS 'V03 E3 · «Comprobar con Hacienda»: pide la consulta de los registros de un mes de la empresa (su cuenta, o la asesoría que la lleva: p_desde_account). Si ya hay una de ese mes esperando, devuelve esa. La hace conta-verifactu.';


--
-- Name: verifactu_cuadre_tomar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cuadre_tomar(p_entorno text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_c public.verifactu_cuadre;
begin
  -- También el que lleva más de 10 minutos «consultando»: la función murió a
  -- mitad (tiempo agotado) y, si no, se quedaría así para siempre.
  select * into v_c from public.verifactu_cuadre
   where entorno = p_entorno and (estado = 'pedido' or (estado = 'consultando' and empezado_at < now() - interval '10 minutes'))
   order by pedido_at limit 1 for update skip locked;
  if v_c.id is null then return null; end if;
  update public.verifactu_cuadre set estado = 'consultando', empezado_at = now(), paginas = 0, error = null where id = v_c.id;
  delete from public.verifactu_cuadre_hacienda where cuadre_id = v_c.id;
  return jsonb_build_object('cuadre_id', v_c.id, 'entorno', v_c.entorno, 'company_id', v_c.company_id, 'nif_emisor', v_c.nif_emisor,
    'nombre_emisor', v_c.nombre_emisor, 'ejercicio', v_c.ejercicio, 'periodo', v_c.periodo);
end $$;


--
-- Name: verifactu_cuadre_ver(uuid, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_cuadre_ver(p_company uuid, p_mes date DEFAULT NULL::date, p_cuadre uuid DEFAULT NULL::uuid, p_desde_account uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_c public.verifactu_cuadre; v_mes date := date_trunc('month', p_mes)::date;
begin
  if not public._verifactu_puede_cuadrar(p_company, p_desde_account) then
    raise exception 'Esa empresa no está, o no la puedes comprobar.' using errcode = '42501';
  end if;
  select * into v_c from public.verifactu_cuadre
   where company_id = p_company and (p_cuadre is null or id = p_cuadre)
     and (v_mes is null or (ejercicio = extract(year from v_mes)::int and periodo = to_char(v_mes, 'MM')))
   order by pedido_at desc limit 1;
  if v_c.id is null then return null; end if;
  return jsonb_build_object('id', v_c.id, 'entorno', v_c.entorno, 'ejercicio', v_c.ejercicio, 'periodo', v_c.periodo, 'estado', v_c.estado,
    'pedido_at', v_c.pedido_at, 'pedido_por', v_c.pedido_por_nombre, 'empezado_at', v_c.empezado_at, 'terminado_at', v_c.terminado_at,
    'paginas', v_c.paginas, 'error', v_c.error, 'resultado', v_c.resultado);
end $$;


--
-- Name: verifactu_despacho_empresas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_despacho_empresas(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_account is null or not public.belongs_to_account(p_account) then raise exception 'No eres de esta cuenta.' using errcode = '42501'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('company_id', c.id, 'nombre', coalesce(c.trade_name, c.legal_name), 'nif', c.tax_id, 'modo', e.modo)
                                    order by coalesce(c.trade_name, c.legal_name)), '[]'::jsonb)
            from public.company c join public.verifactu_empresa e on e.company_id = c.id
           where e.modo <> 'apagado' and c.id in (select public.conta_despacho_clientes(p_account)));
end $$;


--
-- Name: verifactu_despertar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_despertar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_secreto text;
begin
  if not exists (
    select 1 from public.verifactu_registro r
      left join public.verifactu_flujo f on f.nif_emisor = r.nif_emisor and f.entorno = r.entorno
     where r.entorno = 'real' and r.estado = 'pendiente' and r.proximo_intento_at <= now()
       and (f.ultimo_envio_at is null or f.ultimo_envio_at + make_interval(secs => coalesce(f.tiempo_espera_s, 60)) <= now())
  ) then return; end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  if v_secreto is null then
    raise exception 'Falta cron_secret en el Vault: no se puede despertar a conta-verifactu.' using errcode = '55000';
  end if;
  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/conta-verifactu',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := '{}'::jsonb, timeout_milliseconds := 150000);
end $$;


--
-- Name: FUNCTION verifactu_despertar(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_despertar() IS 'V03 · Cada minuto (cron verifactu-despertar, solo en producción): si hay registros de real que el control de flujo deja enviar, llama a conta-verifactu. Si falta el secreto, falla (cron lo apunta), no calla.';


--
-- Name: verifactu_despertar_cuadre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_despertar_cuadre() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_secreto text;
begin
  if not exists (select 1 from public.verifactu_cuadre where entorno = 'real'
                   and (estado = 'pedido' or (estado = 'consultando' and empezado_at < now() - interval '10 minutes'))) then return; end if;
  select decrypted_secret into v_secreto from vault.decrypted_secrets where name = 'cron_secret';
  if v_secreto is null then
    raise exception 'Falta cron_secret en el Vault: no se puede despertar a conta-verifactu.' using errcode = '55000';
  end if;
  perform net.http_post(
    url := 'https://xzmpnchlguibclvxyynt.supabase.co/functions/v1/conta-verifactu',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secreto),
    body := '{"accion":"cuadre"}'::jsonb, timeout_milliseconds := 150000);
end $$;


--
-- Name: FUNCTION verifactu_despertar_cuadre(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_despertar_cuadre() IS 'V03 E3 · Cada minuto (cron verifactu-cuadre, solo en producción): si hay un «Comprobar con Hacienda» de real pedido, llama a conta-verifactu con accion cuadre. Si falta el secreto, falla (cron lo apunta), no calla.';


--
-- Name: verifactu_modo(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_modo(p_company uuid, p_modo text, p_serie text DEFAULT NULL::text, p_confirmacion text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_co public.company; v_e public.verifactu_empresa; v_serie text := upper(btrim(coalesce(p_serie, ''))); v_hoy date := (now() at time zone 'Europe/Madrid')::date;
  v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
begin
  select * into v_co from public.company where id = p_company;
  if v_co.id is null or not public.belongs_to_account(v_co.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_co.account_id) then raise exception 'Solo un administrador o un encargado de la cuenta cambia Verifactu.' using errcode = '42501'; end if;
  if p_modo not in ('apagado', 'pruebas', 'real') then raise exception 'Verifactu va apagado, en pruebas o en real.' using errcode = '22023'; end if;
  insert into public.verifactu_empresa (company_id, account_id) values (v_co.id, v_co.account_id) on conflict (company_id) do nothing;
  select * into v_e from public.verifactu_empresa where company_id = p_company for update;
  if v_e.modo = p_modo then return jsonb_build_object('modo', v_e.modo, 'cambiado', false); end if;
  -- EL CANDADO (respuesta 3 de Julio): a pruebas o a real, solo con una prueba
  -- de conexión correcta con la AEAT apuntada. En pruebas, la del entorno de
  -- pruebas; en real, la de real con el NIF de esta empresa.
  if p_modo in ('pruebas', 'real') and not public.verifactu_conexion_probada(p_modo, v_co.tax_id) then
    raise exception '%', case p_modo
      when 'pruebas' then 'Todavía no se ha probado la conexión con el entorno de pruebas de Hacienda: hasta que salga bien, Verifactu no se puede poner en pruebas.'
      else 'Todavía no se ha probado la conexión con Hacienda con el certificado de esta empresa: hasta que salga bien, Verifactu no se puede pasar a real.' end
      using errcode = '23514';
  end if;
  -- V04 · PR 2: a real, solo con el fabricante de Sumied puesto (la declaración responsable).
  if p_modo = 'real' and not public.verifactu_sistema_completo() then
    raise exception 'Falta quién fabrica Sumied (el nombre y el NIF de la declaración responsable): hasta que esté puesto, Verifactu no se puede pasar a real.'
      using errcode = '23514';
  end if;
  if v_e.modo = 'real' and v_hoy <= v_e.real_obliga_hasta then
    raise exception 'Estás en real desde el %: la ley obliga a seguir así hasta el % (Orden HAC/1177/2024, art. 17.2).',
      to_char(v_e.real_desde at time zone 'Europe/Madrid', 'DD/MM/YYYY'), to_char(v_e.real_obliga_hasta, 'DD/MM/YYYY') using errcode = '23514';
  end if;
  if p_modo = 'real' then
    if p_confirmacion is distinct from 'EMPEZAR' then raise exception 'Para pasar a real, escribe EMPEZAR: desde ese momento no se puede volver a pruebas este año.' using errcode = '23514'; end if;
    if not public._verifactu_nif_es_valido(v_co.tax_id) then raise exception 'El NIF de tu empresa no es válido: corrígelo antes de pasar a real.' using errcode = '23514'; end if;
    if v_serie !~ '^[A-Z0-9][A-Z0-9-]{0,9}$' then raise exception 'La serie nueva va en mayúsculas y cifras (por ejemplo F%).', extract(year from v_hoy)::int using errcode = '23514'; end if;
    if exists (select 1 from public.customer_invoice where company_id = p_company and series_code = v_serie and status <> 'borrador') then
      raise exception 'La serie % ya tiene facturas: la de real empieza nueva.', v_serie using errcode = '23514';
    end if;
    if not exists (select 1 from public.invoice_series where company_id = p_company and code = v_serie) then
      insert into public.invoice_series (account_id, company_id, code, name, doc_type, digits, reset_yearly, starts_at, is_default, is_active)
      values (v_co.account_id, v_co.id, v_serie, 'Facturas (Verifactu)', 'invoice', 4, true, 1, false, true);
    end if;
    update public.verifactu_empresa set modo = 'real', real_desde = now(), real_serie = v_serie,
           real_obliga_hasta = make_date(extract(year from v_hoy)::int, 12, 31), updated_at = now(), updated_by_name = v_quien
     where company_id = p_company;
  else
    update public.verifactu_empresa set modo = p_modo, real_desde = null, real_serie = null, real_obliga_hasta = null,
           pruebas_desde = case when p_modo = 'pruebas' then now() else pruebas_desde end, updated_at = now(), updated_by_name = v_quien
     where company_id = p_company;
  end if;
  select * into v_e from public.verifactu_empresa where company_id = p_company;
  return jsonb_build_object('modo', v_e.modo, 'cambiado', true, 'real_desde', v_e.real_desde, 'real_serie', v_e.real_serie, 'real_obliga_hasta', v_e.real_obliga_hasta);
end $_$;


--
-- Name: FUNCTION verifactu_modo(p_company uuid, p_modo text, p_serie text, p_confirmacion text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_modo(p_company uuid, p_modo text, p_serie text, p_confirmacion text, p_quien_nombre text) IS 'V03 · V04. El interruptor de Verifactu de una empresa: apagado, pruebas o real. A pruebas o a real, solo con una prueba de conexión correcta con la AEAT apuntada (el candado); a real, además con el fabricante de Sumied puesto (verifactu_sistema), escribiendo EMPEZAR y con una serie nueva; obliga hasta el 31/12.';


--
-- Name: verifactu_operacion_poner(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_operacion_poner(p_invoice uuid, p_calificacion text, p_exenta text, p_clave_regimen text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_f public.customer_invoice;
begin
  select * into v_f from public.customer_invoice where id = p_invoice;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_f.account_id) then raise exception 'Solo un administrador o un encargado de la cuenta cambia facturas.' using errcode = '42501'; end if;
  if v_f.status <> 'borrador' then raise exception 'La % ya está emitida: lo que cambie va en una subsanación o una rectificativa.', v_f.number_text using errcode = '23514'; end if;
  if p_calificacion is null and p_exenta is null then
    delete from public.verifactu_operacion where invoice_id = p_invoice;
    return jsonb_build_object('id', p_invoice, 'quitado', true);
  end if;
  insert into public.verifactu_operacion (invoice_id, account_id, company_id, calificacion, exenta, clave_regimen, updated_by_name)
  values (p_invoice, v_f.account_id, v_f.company_id, p_calificacion, p_exenta,
          coalesce(p_clave_regimen, case when p_exenta = 'E2' then '02' else '01' end), coalesce(p_quien_nombre, public.conta_nombre_actor()))
  on conflict (invoice_id) do update set calificacion = excluded.calificacion, exenta = excluded.exenta, clave_regimen = excluded.clave_regimen,
         updated_at = now(), updated_by_name = excluded.updated_by_name;
  return jsonb_build_object('id', p_invoice, 'calificacion', p_calificacion, 'exenta', p_exenta);
end $$;


--
-- Name: verifactu_otros_programas(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_otros_programas(p_company uuid, p_programas text[], p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_co public.company; v_p text[];
begin
  select * into v_co from public.company where id = p_company;
  if v_co.id is null or not public.belongs_to_account(v_co.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_co.account_id) then raise exception 'Solo un administrador o un encargado de la cuenta cambia Verifactu.' using errcode = '42501'; end if;
  select coalesce(array_agg(distinct x order by x), '{}') into v_p from unnest(coalesce(p_programas, '{}')) x;
  if exists (select 1 from unnest(v_p) x where x not in ('tpv', 'tienda', 'excel', 'otro')) then
    raise exception 'Los otros programas son: tpv, tienda, excel u otro.' using errcode = '22023';
  end if;
  insert into public.verifactu_empresa (company_id, account_id, otros_programas, updated_by_name)
  values (v_co.id, v_co.account_id, v_p, coalesce(p_quien_nombre, public.conta_nombre_actor()))
  on conflict (company_id) do update set otros_programas = excluded.otros_programas, updated_at = now(), updated_by_name = excluded.updated_by_name;
  return jsonb_build_object('company_id', v_co.id, 'otros_programas', to_jsonb(v_p));
end $$;


--
-- Name: verifactu_previsto(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_previsto(p_invoice uuid, p_accion text, p_cambios jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.customer_invoice; v_e public.verifactu_empresa; v_a public.verifactu_registro; v_n public.verifactu_registro;
  v_carga jsonb; v_cambios jsonb; v_num text; v_motivo text; v_asiento int; v_mes text; v_rect text;
  r jsonb := jsonb_build_object('accion', p_accion);
begin
  select * into v_f from public.customer_invoice where id = p_invoice;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if p_accion not in ('rectificar', 'anular', 'subsanar') then raise exception 'Qué te has equivocado: rectificar, anular o subsanar.' using errcode = '22023'; end if;
  v_num := coalesce(v_f.number_text, 'factura');
  r := r || jsonb_build_object('numero', v_num, 'cambios', '[]'::jsonb, 'aviso', null);
  if v_f.status = 'borrador' then
    return r || jsonb_build_object('puede', false, 'frase', 'Es un borrador: no tiene número ni ha salido a Hacienda. Cámbialo directamente y guárdalo.');
  end if;
  if v_f.status = 'anulada' then
    return r || jsonb_build_object('puede', false, 'frase', 'La ' || v_num || ' ya está anulada: no se corrige más.');
  end if;
  select * into v_e from public.verifactu_empresa where company_id = v_f.company_id;
  v_a := public._verifactu_ultima_alta(p_invoice);
  v_n := public._verifactu_anulacion_de(p_invoice);
  v_mes := to_char(v_f.issue_date, 'MM/YYYY');

  -- La rectificativa (V01): la factura del cliente está mal.
  if p_accion = 'rectificar' then
    if v_f.doc_type = 'rectificativa' then
      select number_text into v_rect from public.customer_invoice where id = v_f.corrects_id;
      return r || jsonb_build_object('puede', false, 'frase', 'Una rectificativa no se corrige con otra: corrige la factura de origen' || coalesce(', la ' || v_rect, '') || '.');
    end if;
    if exists (select 1 from public.customer_invoice where corrects_id = p_invoice and status = 'borrador') then
      return r || jsonb_build_object('puede', true, 'frase', 'Ya hay una rectificativa de la ' || v_num || ' preparada, sin emitir: se abre esa.');
    end if;
    return r || jsonb_build_object('puede', true,
      'frase', 'Se prepara una rectificativa de la ' || v_num || ' (serie R), enlazada a ella. Al emitirla lleva su número, su PDF y su asiento'
        || case when v_a.id is not null then ', y Hacienda recibe su alta como rectificativa por diferencias (R4)' else '' end
        || '. La ' || v_num || ' no cambia ni se borra: tu cliente recibe la rectificativa.',
      'aviso', 'Es lo que toca si tu cliente tiene la factura y algo de ella está mal: importes, líneas o sus datos.');
  end if;

  -- La anulación: no tenía que haberse emitido.
  if p_accion = 'anular' then
    v_motivo := case
      when v_a.id is null then 'La ' || v_num || ' no tiene registro en Hacienda: si no tenía que haberla emitido, anúlala con una rectificativa («Anularla entera»).'
      when v_n.id is not null then 'La ' || v_num || ' ya tiene su registro de anulación en Hacienda.'
      when v_e.modo is distinct from v_a.entorno then 'Se registró en ' || v_a.entorno || ' y Verifactu está ahora en ' || coalesce(v_e.modo, 'apagado') || ': su anulación ya no se manda.'
      when v_f.doc_type = 'rectificativa' then 'Es una rectificativa: si sobra, se corrige su factura de origen con otra rectificativa.'
      when exists (select 1 from public.customer_invoice_payment where invoice_id = p_invoice) then 'La ' || v_num || ' tiene cobros: el cliente la ha pagado, así que existe. Se corrige con una rectificativa («Anularla entera»).'
      when exists (select 1 from public.customer_invoice where corrects_id = p_invoice and status <> 'borrador') then 'La ' || v_num || ' ya tiene una rectificativa emitida: se corrige con otra rectificativa, no se anula.'
      when exists (select 1 from public.customer_invoice where corrects_id = p_invoice and status = 'borrador') then 'La ' || v_num || ' tiene una rectificativa preparada sin emitir: bórrala o emítela antes.'
      when public.conta_mes_cerrado(v_f.company_id, v_f.issue_date) then 'El mes de ' || v_mes || ' está cerrado: la ' || v_num || ' ya cuenta en lo declarado. Se corrige con una rectificativa («Anularla entera»).'
      when v_f.entry_id is null then 'La ' || v_num || ' no tiene su asiento: no se puede deshacer. Avisa a soporte.'
      else null end;
    if v_motivo is not null then return r || jsonb_build_object('puede', false, 'frase', v_motivo); end if;
    select number into v_asiento from public.journal_entry where id = v_f.entry_id;
    return r || jsonb_build_object('puede', true,
      'frase', 'La ' || v_num || ' queda anulada: no cuenta en tus ventas ni en el IVA de ' || v_mes || ', su asiento'
        || coalesce(' nº ' || v_asiento::text, '') || ' se deshace con un contrasiento del mismo día, y Hacienda recibe un registro de anulación. Su número no se vuelve a usar.'
        || case v_a.estado
             when 'pendiente' then ' Todavía no había salido a Hacienda: le llegan las dos, el alta y la anulación, en el mismo envío.'
             when 'enviando' then ' Se está enviando ahora: la anulación sale en el envío siguiente.'
             when 'incorrecto' then case when exists (select 1 from public.verifactu_registro where invoice_id = p_invoice and tipo = 'alta' and estado in ('correcto', 'aceptado_con_errores'))
               then ' Hacienda rechazó su última subsanación, pero tiene la de antes: es esa la que se anula.'
               else ' Hacienda la rechazó, así que no la tiene: la anulación lo dice («sin registro previo»).' end
             else '' end,
      'aviso', 'Solo si no tenía que haberse emitido: un duplicado, una prueba, la que se hizo a otro cliente antes de mandársela. Si tu cliente la tiene, se corrige con una rectificativa.');
  end if;

  -- La subsanación: lo que solo va a Hacienda.
  v_motivo := case
    when v_a.id is null then 'La ' || v_num || ' no tiene registro en Hacienda: no hay nada que subsanar.'
    when v_n.id is not null then 'La ' || v_num || ' está anulada en Hacienda: no se subsana.'
    when v_e.modo is distinct from v_a.entorno then 'Se registró en ' || v_a.entorno || ' y Verifactu está ahora en ' || coalesce(v_e.modo, 'apagado') || ': ese registro ya no se subsana.'
    when v_a.estado = 'pendiente' then 'La ' || v_num || ' todavía no ha salido a Hacienda: espera a que conteste, y luego subsana si hace falta.'
    when v_a.estado = 'enviando' then 'La ' || v_num || ' se está enviando ahora: espera a que Hacienda conteste.'
    else null end;
  if v_motivo is not null then return r || jsonb_build_object('puede', false, 'frase', v_motivo); end if;
  v_carga := public._verifactu_carga_de_factura(p_invoice, p_cambios->>'descripcion');
  if not coalesce((v_carga->>'va')::boolean, false) then
    return r || jsonb_build_object('puede', false, 'frase', 'Verifactu no está encendido para esta empresa: no se subsana.');
  end if;
  if jsonb_array_length(v_carga->'faltas') > 0 then
    return r || jsonb_build_object('puede', false, 'frase', v_carga->'faltas'->0->>'frase', 'faltas', v_carga->'faltas');
  end if;
  v_cambios := public._verifactu_cambios(v_a, v_carga);
  r := r || jsonb_build_object('cambios', v_cambios);
  if jsonb_array_length(v_cambios) = 0 and v_a.estado = 'correcto' then
    return r || jsonb_build_object('puede', false,
      'frase', 'No hay nada que subsanar: lo que tiene Hacienda es lo que dice la ' || v_num || '. Si lo que está mal es la factura, es una rectificativa.');
  end if;
  return r || jsonb_build_object('puede', true,
    'frase', 'Hacienda recibe un registro nuevo de la ' || v_num || ' que sustituye al que tiene (una subsanación). La factura de tu cliente no cambia: ni su número, ni sus importes, ni su PDF.'
      || case v_a.estado
           when 'incorrecto' then ' Como la rechazó, el registro nuevo lo dice («rechazo previo»).'
           when 'aceptado_con_errores' then case when jsonb_array_length(v_cambios) = 0
             then ' Va igual que la otra vez: sirve si lo que avisó Hacienda' || coalesce(' (' || v_a.codigo_error::text || ')', '') || ' ya está arreglado fuera de Sumied.'
             else '' end
           else '' end);
end $$;


--
-- Name: FUNCTION verifactu_previsto(p_invoice uuid, p_accion text, p_cambios jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_previsto(p_invoice uuid, p_accion text, p_cambios jsonb) IS 'V03 E3 · «Me he equivocado en…» (tablero 27): qué va a pasar si se rectifica, se anula o se subsana una factura emitida, antes de hacerlo. Solo lee. {accion, puede, frase, aviso, cambios [{campo, que, antes, despues}], numero}. verifactu_anular_factura y verifactu_subsanar paran con esta misma frase.';


--
-- Name: verifactu_reenviar(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_reenviar(p_invoice uuid, p_tipo_venta jsonb DEFAULT NULL::jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.customer_invoice; v_e public.verifactu_empresa; v_prev public.verifactu_registro; v_k jsonb; v_reg public.verifactu_registro;
  v_cal text; v_ex text; v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
begin
  select * into v_f from public.customer_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta reenvía facturas a Hacienda.' using errcode = '42501';
  end if;
  select * into v_prev from public.verifactu_registro
   where invoice_id = p_invoice and account_id = v_f.account_id and tipo = 'alta' order by generado_at desc, id desc limit 1;
  if v_prev.id is null then raise exception 'La % no tiene registro en Hacienda: no hay nada que reenviar.', v_f.number_text using errcode = '23514'; end if;
  if v_prev.estado <> 'incorrecto' then
    raise exception 'La % no está rechazada por Hacienda (está %): no hay nada que reenviar.', v_f.number_text,
      case v_prev.estado when 'pendiente' then 'esperando a enviarse' when 'enviando' then 'enviándose' when 'correcto' then 'recibida'
                         when 'aceptado_con_errores' then 'recibida con un aviso' else v_prev.estado end using errcode = '23514';
  end if;
  select * into v_e from public.verifactu_empresa where company_id = v_f.company_id;
  if v_e.modo is distinct from v_prev.entorno then
    raise exception 'Se rechazó en %, y Verifactu está ahora en %: ese registro ya no se reenvía.', v_prev.entorno, coalesce(v_e.modo, 'apagado') using errcode = '23514';
  end if;

  -- El porqué de la venta sin IVA, si viene.
  if p_tipo_venta is not null then
    v_cal := nullif(p_tipo_venta->>'calificacion', ''); v_ex := nullif(p_tipo_venta->>'exenta', '');
    if coalesce(v_cal, '') not in ('', 'N1', 'N2') or coalesce(v_ex, '') not in ('', 'E1', 'E2', 'E3', 'E4', 'E5', 'E6') or (v_cal is null) = (v_ex is null) then
      raise exception 'El tipo de venta sin IVA es una de dos: no sujeta (N1, N2) o exenta (E1 a E6).' using errcode = '22023';
    end if;
    if not exists (select 1 from public.customer_invoice_line l join public.tax_rate t on t.id = l.tax_rate_id
                    where l.invoice_id = p_invoice and t.treatment = 'exempt') then
      raise exception 'La % no tiene líneas sin IVA: no lleva porqué.', v_f.number_text using errcode = '23514';
    end if;
    if public.conta_mes_cerrado(v_f.company_id, v_f.issue_date) then
      raise exception 'El mes de % está cerrado: el porqué ya está en el libro y en lo declarado. Se corrige con una rectificativa.', to_char(v_f.issue_date, 'MM/YYYY') using errcode = '23514';
    end if;
    insert into public.verifactu_operacion (invoice_id, account_id, company_id, calificacion, exenta, clave_regimen, updated_by_name)
    values (p_invoice, v_f.account_id, v_f.company_id, v_cal, v_ex, case when v_ex = 'E2' then '02' else '01' end, v_quien)
    on conflict (invoice_id) do update set calificacion = excluded.calificacion, exenta = excluded.exenta, clave_regimen = excluded.clave_regimen,
           updated_at = now(), updated_by_name = excluded.updated_by_name;
    -- Y su libro: las anotaciones exentas del asiento de la factura.
    update public.vat_book_entry v set qualification = v_cal, exempt_cause = v_ex, operation_key = case when v_ex = 'E2' then '02' else '01' end, updated_at = now()
      from public.journal_line l join public.tax_rate t on t.id = l.tax_rate_id
     where v.entry_id = v_f.entry_id and v.account_id = v_f.account_id and l.id = v.line_id and t.treatment = 'exempt';
  end if;

  v_k := public.verifactu_comprobar(p_invoice);
  if not coalesce((v_k->>'va')::boolean, false) then
    raise exception 'Verifactu no está encendido para esta empresa: no se reenvía.' using errcode = '23514';
  end if;
  if jsonb_array_length(v_k->'faltas') > 0 then
    raise exception '%', (v_k->'faltas'->0->>'frase') using errcode = '23514', detail = (v_k->'faltas')::text, hint = 'verifactu';
  end if;

  v_reg := public._verifactu_registrar(jsonb_build_object(
    'account_id', v_prev.account_id, 'company_id', v_prev.company_id, 'entorno', v_prev.entorno, 'tipo', 'alta',
    'subsanacion', true, 'rechazo_previo', 'S', 'origen', v_prev.origen, 'invoice_id', v_prev.invoice_id,
    'nif_emisor', v_prev.nif_emisor, 'nombre_emisor', v_prev.nombre_emisor, 'num_serie', v_prev.num_serie, 'fecha_expedicion', v_prev.fecha_expedicion,
    'fecha_operacion', v_prev.fecha_operacion, 'tipo_factura', v_prev.tipo_factura, 'tipo_rectificativa', v_prev.tipo_rectificativa,
    'rectificadas', v_prev.rectificadas, 'descripcion', v_prev.descripcion, 'destinatarios', v_prev.destinatarios,
    'desglose', v_k->'desglose', 'cuota_total', v_k->'cuota_total', 'importe_total', v_k->'importe_total', 'quien', v_quien));
  perform public._conta_venta_evento(p_invoice, 'verifactu_reenvio',
    'Reenviada a Hacienda (subsanación del registro rechazado' || coalesce(' con el ' || v_prev.codigo_error, '') || ').', jsonb_build_object('registro', v_reg.id, 'rechazado', v_prev.id), v_quien);
  return jsonb_build_object('registro_id', v_reg.id, 'num_serie', v_reg.num_serie, 'estado', v_reg.estado);
end $$;


--
-- Name: FUNCTION verifactu_reenviar(p_invoice uuid, p_tipo_venta jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_reenviar(p_invoice uuid, p_tipo_venta jsonb, p_quien_nombre text) IS 'V03 E2 · «Corregir y reenviar» (tablero 27): el alta rechazada de una factura se subsana con un registro nuevo (Subsanacion S, RechazoPrevio S), encadenado. Si viene tipo_venta, cambia el porqué de la venta sin IVA y su libro (con el mes abierto).';


--
-- Name: verifactu_retirar_autorizacion(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_retirar_autorizacion(p_company uuid, p_motivo text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_co public.company; v_a public.verifactu_autorizacion; v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
begin
  if auth.uid() is null then raise exception 'Tienes que entrar con tu usuario.' using errcode = '42501'; end if;
  select * into v_co from public.company where id = p_company;
  if v_co.id is null or not public.belongs_to_account(v_co.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_co.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta retira la autorización.' using errcode = '42501';
  end if;
  select * into v_a from public.verifactu_autorizacion where company_id = p_company and retirada_at is null for update;
  if v_a.id is null then return jsonb_build_object('retirada', false, 'mensaje', 'No había ninguna autorización vigente.'); end if;
  update public.verifactu_autorizacion set retirada_at = now(), retirada_por = auth.uid(), retirada_por_nombre = v_quien,
         retirada_motivo = nullif(btrim(coalesce(p_motivo, '')), '')
   where id = v_a.id;
  update public.verifactu_empresa set via = 'colaborador', certificate_id = null, updated_at = now(), updated_by_name = v_quien where company_id = p_company;
  return jsonb_build_object('retirada', true, 'id', v_a.id);
end $$;


--
-- Name: FUNCTION verifactu_retirar_autorizacion(p_company uuid, p_motivo text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_retirar_autorizacion(p_company uuid, p_motivo text, p_quien_nombre text) IS 'V03. Retira la autorización vigente del certificado para Verifactu (quién, cuándo, por qué). La empresa vuelve a la vía de colaborador social; lo que quede en la cola espera.';


--
-- Name: verifactu_simplificada(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_simplificada(p_company uuid, p_datos jsonb, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_co public.company; v_e public.verifactu_empresa; v_l jsonb; v_desglose jsonb := '[]'::jsonb; v_cuota numeric := 0; v_total numeric := 0;
  v_reg public.verifactu_registro; v_fecha date; v_serie text := btrim(coalesce(p_datos->>'num_serie', '')); v_pct numeric;
begin
  select * into v_co from public.company where id = p_company;
  if v_co.id is null or not public.belongs_to_account(v_co.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_co.account_id) then raise exception 'Solo un administrador o un encargado de la cuenta registra facturas.' using errcode = '42501'; end if;
  select * into v_e from public.verifactu_empresa where company_id = p_company;
  if v_e.company_id is null or v_e.modo = 'apagado' then raise exception 'Verifactu está apagado en %: actívalo en Ajustes › Facturación › Verifactu.', coalesce(v_co.trade_name, v_co.legal_name) using errcode = '23514'; end if;
  if v_serie = '' then raise exception 'Falta el número del tique.' using errcode = '23514'; end if;
  if v_serie !~ '^[ !#-&(-;?-~]{1,60}$' then raise exception 'El número del tique («%») lleva caracteres que Hacienda no admite o pasa de 60.', v_serie using errcode = '23514'; end if;
  v_fecha := (p_datos->>'fecha')::date;
  if v_fecha > (now() at time zone 'Europe/Madrid')::date then raise exception 'La fecha del tique es de un día que aún no ha llegado.' using errcode = '23514'; end if;
  if jsonb_array_length(coalesce(p_datos->'lineas', '[]'::jsonb)) = 0 then raise exception 'El tique no tiene líneas.' using errcode = '23514'; end if;
  for v_l in select * from jsonb_array_elements(p_datos->'lineas') loop
    v_pct := (v_l->>'tipo')::numeric;
    if not (v_pct in (0, 4, 10, 21) or (v_pct = 5 and v_fecha between date '2022-07-01' and date '2024-09-30')
            or (v_pct in (2, 7.5) and v_fecha between date '2024-10-01' and date '2024-12-31')) then
      raise exception 'El % %% no es un tipo de IVA en vigor para el %.', to_char(v_pct, 'FM990D##'), to_char(v_fecha, 'DD/MM/YYYY') using errcode = '23514';
    end if;
    if abs((v_l->>'cuota')::numeric - round((v_l->>'base')::numeric * v_pct / 100, 2)) > 10 then
      raise exception 'La cuota de una línea no cuadra con su base y su tipo (Hacienda admite ±10 €).' using errcode = '23514';
    end if;
    v_desglose := v_desglose || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('impuesto', '01', 'clave_regimen', '01', 'calificacion', 'S1',
      'tipo', v_pct, 'base', (v_l->>'base')::numeric, 'cuota', (v_l->>'cuota')::numeric,
      'tipo_recargo', (v_l->>'tipo_recargo')::numeric, 'cuota_recargo', (v_l->>'cuota_recargo')::numeric)));
    v_cuota := v_cuota + (v_l->>'cuota')::numeric + coalesce((v_l->>'cuota_recargo')::numeric, 0);
    v_total := v_total + (v_l->>'base')::numeric + (v_l->>'cuota')::numeric + coalesce((v_l->>'cuota_recargo')::numeric, 0);
  end loop;
  -- §3.1.3.15.8 (código 1150): una simplificada no pasa de 3.000 € (±10 €).
  if v_total > 3010 then raise exception 'Un tique no puede pasar de 3.000 €: haz una factura completa.' using errcode = '23514'; end if;
  v_reg := public._verifactu_registrar(jsonb_build_object(
    'account_id', v_co.account_id, 'company_id', v_co.id, 'entorno', v_e.modo, 'tipo', 'alta', 'origen', 'simplificada',
    'origen_programa', coalesce(p_datos->>'programa', 'otro'), 'origen_ref', p_datos->>'ref',
    'nif_emisor', regexp_replace(upper(v_co.tax_id), '^ES', ''), 'nombre_emisor', coalesce(v_co.legal_name, v_co.trade_name),
    'num_serie', v_serie, 'fecha_expedicion', v_fecha, 'tipo_factura', 'F2',
    'descripcion', coalesce(nullif(btrim(p_datos->>'descripcion'), ''), 'Venta'), 'desglose', v_desglose,
    'cuota_total', v_cuota, 'importe_total', v_total, 'quien', coalesce(p_quien_nombre, public.conta_nombre_actor())));
  return jsonb_build_object('id', v_reg.id, 'huella', v_reg.huella, 'entorno', v_reg.entorno,
    'qr', public.verifactu_url_qr(v_reg.entorno, v_reg.nif_emisor, v_reg.num_serie, v_reg.fecha_expedicion, v_reg.importe_total));
end $_$;


--
-- Name: FUNCTION verifactu_simplificada(p_company uuid, p_datos jsonb, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_simplificada(p_company uuid, p_datos jsonb, p_quien_nombre text) IS 'V03. Registra una factura simplificada (F2) de cualquier programa de la empresa, una a una, con su número: huella encadenada, a la cola, y devuelve el QR. Para el TPV de Folvy cuando se retome.';


--
-- Name: verifactu_sistema_completo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_sistema_completo() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select nullif(btrim(nombre_razon), '') is not null and nif is not null from public.verifactu_sistema where id), false)
$$;


--
-- Name: FUNCTION verifactu_sistema_completo(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_sistema_completo() IS 'V04 · PR 2. ¿Está puesto quién fabrica Sumied (nombre y NIF)? Sin eso no se pasa a real (verifactu_modo) y Ajustes lo avisa.';


--
-- Name: verifactu_sistema_poner(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_sistema_poner(p_nombre text, p_nif text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nif text := regexp_replace(upper(btrim(coalesce(p_nif, ''))), '^ES', '');
begin
  if nullif(btrim(coalesce(p_nombre, '')), '') is null then raise exception 'Falta el nombre de quien fabrica Sumied.' using errcode = '23514'; end if;
  if not public._verifactu_nif_es_valido(v_nif) then raise exception 'El NIF de quien fabrica Sumied (%) no es válido.', v_nif using errcode = '23514'; end if;
  update public.verifactu_sistema set nombre_razon = btrim(p_nombre), nif = v_nif, updated_at = now(), updated_by_name = p_quien_nombre where id;
  return public.verifactu_sistema_ver();
end $$;


--
-- Name: FUNCTION verifactu_sistema_poner(p_nombre text, p_nif text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_sistema_poner(p_nombre text, p_nif text, p_quien_nombre text) IS 'V04 · PR 2. Solo el servicio: pone quién fabrica Sumied (nombre y NIF de la declaración responsable).';


--
-- Name: verifactu_sistema_ver(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_sistema_ver() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('nombre_razon', nullif(btrim(nombre_razon), ''), 'nif', nif) from public.verifactu_sistema where id
$$;


--
-- Name: verifactu_subsanar(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_subsanar(p_invoice uuid, p_descripcion text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_f public.customer_invoice; v_a public.verifactu_registro; v_p jsonb; v_carga jsonb; v_reg public.verifactu_registro;
  v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());
begin
  select * into v_f from public.customer_invoice where id = p_invoice for update;
  if v_f.id is null or not public.belongs_to_account(v_f.account_id) then raise exception 'Esa factura no está.' using errcode = 'P0002'; end if;
  if not public.current_user_is_admin_or_manager_of(v_f.account_id) then
    raise exception 'Solo un administrador o un encargado de la cuenta subsana facturas en Hacienda.' using errcode = '42501';
  end if;
  v_p := public.verifactu_previsto(p_invoice, 'subsanar', jsonb_build_object('descripcion', p_descripcion));
  if not coalesce((v_p->>'puede')::boolean, false) then raise exception '%', v_p->>'frase' using errcode = '23514'; end if;
  v_a := public._verifactu_ultima_alta(p_invoice);
  v_carga := public._verifactu_carga_de_factura(p_invoice, p_descripcion);
  v_reg := public._verifactu_registrar((v_carga - array['va', 'faltas']) || jsonb_build_object(
    'entorno', v_a.entorno, 'tipo', 'alta', 'subsanacion', true,
    'rechazo_previo', case when v_a.estado = 'incorrecto' then 'S' end,
    'fecha_operacion', v_a.fecha_operacion, 'quien', v_quien));
  perform public._conta_venta_evento(p_invoice, 'verifactu_subsanacion',
    'Subsanada en Hacienda: registro nuevo' || case when jsonb_array_length(v_p->'cambios') > 0
      then ' (cambia ' || (select string_agg(lower(c->>'que'), ', ') from jsonb_array_elements(v_p->'cambios') c) || ')' else ', igual que el anterior' end || '.',
    jsonb_build_object('registro', v_reg.id, 'anterior', v_a.id, 'cambios', v_p->'cambios'), v_quien);
  return jsonb_build_object('numero', v_f.number_text, 'registro_id', v_reg.id, 'estado', v_reg.estado, 'cambios', v_p->'cambios',
    'rechazo_previo', v_reg.rechazo_previo);
end $$;


--
-- Name: FUNCTION verifactu_subsanar(p_invoice uuid, p_descripcion text, p_quien_nombre text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_subsanar(p_invoice uuid, p_descripcion text, p_quien_nombre text) IS 'V03 E3 · Subsanar: un registro de alta nuevo de la misma factura (Subsanacion S; RechazoPrevio S si la última se rechazó), encadenado y a la cola, con lo que solo va a Hacienda (la descripción, o volver a mandar una aceptada con un aviso). La factura del cliente no cambia. Para si verifactu_previsto dice que no puede (por ejemplo, si no cambia nada y Hacienda la tiene bien).';


--
-- Name: verifactu_url_qr(text, text, text, date, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verifactu_url_qr(p_entorno text, p_nif text, p_num_serie text, p_fecha date, p_importe numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_entorno when 'real' then 'https://www2.agenciatributaria.gob.es/wlpl/TIKE-CONT/ValidarQR'
                        else 'https://prewww2.aeat.es/wlpl/TIKE-CONT/ValidarQR' end
      || '?nif=' || public._verifactu_url_codificar(upper(btrim(p_nif)))
      || '&numserie=' || public._verifactu_url_codificar(btrim(p_num_serie))
      || '&fecha=' || public._verifactu_fecha(p_fecha)
      || '&importe=' || public._verifactu_importe(p_importe)
$$;


--
-- Name: FUNCTION verifactu_url_qr(p_entorno text, p_nif text, p_num_serie text, p_fecha date, p_importe numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verifactu_url_qr(p_entorno text, p_nif text, p_num_serie text, p_fecha date, p_importe numeric) IS 'V03. La URL del QR de una factura (QR v0.5.0 de la AEAT): solo nif, numserie, fecha e importe, codificados. La misma que src/modules/conta/lib/verifactu/qr.ts.';


--
-- Name: verify_practical_items(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_practical_items(p_attempt_id uuid, p_checks jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_attempt public.course_attempt%rowtype;
  v_account_id uuid;
  v_course_id uuid;
  v_signer_auth_uid uuid;
  v_check jsonb;
  v_item_id uuid;
  v_checked boolean;
  v_item_notes text;
  v_inserted_count int := 0;
begin
  if v_uid is null then
    raise exception 'Sin sesión válida: no se puede verificar sin auth.uid()';
  end if;

  select * into v_attempt from public.course_attempt where id = p_attempt_id;
  if not found then
    raise exception 'Intento no encontrado';
  end if;

  select ca.account_id, ca.course_id into v_account_id, v_course_id
  from public.course_assignment ca where ca.id = v_attempt.assignment_id;

  if not (public.current_user_is_admin() or public.current_user_is_admin_or_manager_of(v_account_id)) then
    raise exception 'verify_practical_items: sin acceso a la cuenta %', v_account_id;
  end if;

  if coalesce(v_attempt.passed, false) is not true then
    raise exception 'Solo se puede verificar la práctica de un intento superado';
  end if;

  select s.auth_uid into v_signer_auth_uid
  from public.course_signature s
  where s.attempt_id = p_attempt_id
  order by s.signed_at desc
  limit 1;
  if v_signer_auth_uid is not null and v_signer_auth_uid = v_uid then
    raise exception 'El verificador no puede ser el propio trabajador que firmó el intento';
  end if;

  for v_check in select * from jsonb_array_elements(p_checks)
  loop
    v_item_id := nullif(v_check ->> 'itemId', '')::uuid;
    v_checked := coalesce((v_check ->> 'checked')::boolean, false);
    v_item_notes := coalesce(v_check ->> 'notes', p_notes);

    if v_item_id is null or not exists (
      select 1 from public.course_practical_item pi where pi.id = v_item_id and pi.course_id = v_course_id
    ) then
      raise exception 'El gesto % no pertenece al curso de este intento', v_item_id;
    end if;

    insert into public.course_practical_check (attempt_id, item_id, checked, verified_by, notes)
    values (p_attempt_id, v_item_id, v_checked, v_uid, v_item_notes);
    v_inserted_count := v_inserted_count + 1;
  end loop;

  begin
    perform public.check_phase_completion_for_assignment(v_attempt.assignment_id);
  exception when others then
    raise warning 'verify_practical_items: check_phase_completion_for_assignment falló para asignación %: %', v_attempt.assignment_id, sqlerrm;
  end;

  return jsonb_build_object('insertedCount', v_inserted_count, 'verifiedAt', now());
end;
$$;


--
-- Name: vigia_avisos_olvido(boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vigia_avisos_olvido(p_dry boolean DEFAULT false, p_ahora timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_hoy timestamptz := ((p_ahora at time zone 'Europe/Madrid')::date)::timestamp at time zone 'Europe/Madrid';
  v_cron boolean := true;
  v_detectados integer := 0;
  r record;
  v_avisos jsonb := '[]'::jsonb;
  v_texto text;
begin
  -- Detecta él mismo: si la función de borde no corre, la cola crece y se ve.
  if not p_dry then
    begin
      v_detectados := public.enqueue_clockout_reminders();
    exception when others then
      perform public._queue_system_alert('avisos_olvido', 'Avisos de olvido: la detección falla',
        format('enqueue_clockout_reminders() falló: %s', sqlerrm), 'avisos_olvido_detectar', interval '6 hours');
    end;
  end if;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    select exists (select 1 from cron.job where jobname = 'clockout-reminder-drain' and active) into v_cron;
  end if;

  for r in
    with hoy as (
      select l.account_id, l.status, l.created_at, l.error, w.de_empresa, w.texto
        from public.clockout_reminder_log l
        left join lateral public.whatsapp_error_en_palabras(l.error) w on l.status = 'failed'
       where l.created_at >= v_hoy
    )
    select h.account_id,
           count(*) filter (where h.status = 'failed' and h.de_empresa) as fallos_empresa,
           count(*) filter (where h.status = 'failed' and not h.de_empresa) as fallos_persona,
           count(*) filter (where h.status = 'queued' and h.created_at < p_ahora - interval '30 minutes') as atascados,
           count(*) filter (where h.status = 'sent') as enviados,
           (array_agg(h.texto order by h.created_at desc) filter (where h.status = 'failed' and h.de_empresa))[1] as motivo
      from hoy h
     group by h.account_id
  loop
    if r.fallos_empresa = 0 and r.atascados = 0 and v_cron then continue; end if;
    v_texto := case
      when r.fallos_empresa > 0 then
        format('%s por WhatsApp. El motivo: %s Hasta que se arregle, nadie recibe el WhatsApp: cada persona lo ve al abrir su portal.',
               case when r.fallos_empresa = 1 then 'Hoy no ha salido 1 aviso de olvido'
                    else format('Hoy no han salido %s avisos de olvido', r.fallos_empresa) end,
               r.motivo)
      when not v_cron then
        'El envío de los avisos de olvido por WhatsApp no está programado: no sale ninguno. Mientras tanto, cada persona lo ve al abrir su portal.'
      else
        format('%s más de 30 minutos para salir: el envío por WhatsApp no está corriendo. Mientras tanto, cada persona lo ve al abrir su portal.',
               case when r.atascados = 1 then 'Hay 1 aviso de olvido esperando' else format('Hay %s avisos de olvido esperando', r.atascados) end)
    end;
    v_avisos := v_avisos || jsonb_build_object('cuenta', r.account_id, 'texto', v_texto,
                  'fallos_empresa', r.fallos_empresa, 'atascados', r.atascados, 'enviados', r.enviados);
    if not p_dry then
      insert into public.aviso_empresa(account_id, tipo, clave, titulo, texto, creado_at)
      values (r.account_id, 'avisos_olvido_fallan',
              'avisos_olvido_fallan:' || r.account_id || ':' || to_char(p_ahora at time zone 'Europe/Madrid', 'YYYY-MM-DD'),
              'Los avisos de olvido de fichaje no están saliendo', v_texto, p_ahora)
      on conflict (clave) do nothing;
      perform public._queue_system_alert('avisos_olvido', 'Avisos de olvido: no salen',
        format('Cuenta %s: %s', r.account_id, v_texto), 'avisos_olvido_' || r.account_id, interval '20 hours');
    end if;
  end loop;
  return jsonb_build_object('detectados', v_detectados, 'cron', v_cron, 'avisos', v_avisos);
end $$;


--
-- Name: FUNCTION vigia_avisos_olvido(p_dry boolean, p_ahora timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.vigia_avisos_olvido(p_dry boolean, p_ahora timestamp with time zone) IS 'L1a PR 3: cada 15 min (cron avisos-olvido-vigia). Detecta los olvidos sin depender de la función de borde y, si hoy los WhatsApp fallan por algo de la empresa o se quedan en cola más de 30 min, avisa a la empresa (aviso_empresa, una vez al día) y a sistema.';


--
-- Name: void_clock_entry(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_clock_entry(p_entry_id uuid, p_reason text, p_actor_label text DEFAULT NULL::text) RETURNS public.clock_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acct uuid; v_emp uuid; v_row public.clock_entries;
begin
  if coalesce(trim(p_reason),'') = '' then raise exception 'MOTIVO_OBLIGATORIO'; end if;
  select employee_id into v_emp from public.clock_entries where id = p_entry_id;
  if v_emp is null then raise exception 'FICHAJE_NO_EXISTE'; end if;
  v_acct := public._account_of_employee(v_emp);
  if not public._puede_corregir(v_emp, v_acct) then raise exception 'NO_AUTORIZADO'; end if;

  perform set_config('app.clock_edit_reason', p_reason, true);
  perform set_config('app.clock_edit_actor', coalesce(p_actor_label,''), true);

  update public.clock_entries set voided = true where id = p_entry_id returning * into v_row;
  return v_row;
end $$;


--
-- Name: void_goods_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_goods_receipt(p_receipt_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_receipt   goods_receipt%ROWTYPE;
  v_mov       stock_movement%ROWTYPE;
  v_line      goods_receipt_line%ROWTYPE;
  v_user      uuid;
  v_user_name text;
  v_reversed  integer := 0;
  v_new_price numeric;
BEGIN
  SELECT * INTO v_receipt FROM goods_receipt WHERE id = p_receipt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'void_goods_receipt: albarán % no existe', p_receipt_id;
  END IF;
  IF NOT (current_user_is_admin()
          OR current_user_is_admin_or_manager_of(v_receipt.account_id)) THEN
    RAISE EXCEPTION 'void_goods_receipt: sin acceso al albarán %', p_receipt_id;
  END IF;
  IF v_receipt.status <> 'confirmado' THEN
    RAISE EXCEPTION 'void_goods_receipt: el albarán % no está confirmado (está %)',
      p_receipt_id, v_receipt.status;
  END IF;
  v_user := auth.uid();
  SELECT display_name INTO v_user_name FROM user_profiles WHERE id = v_user;

  -- 1) Revertir el STOCK (sin cambios respecto al original).
  FOR v_mov IN
    SELECT sm.* FROM stock_movement sm
    JOIN goods_receipt_line grl ON grl.id = sm.source_id
    WHERE sm.source_type = 'goods_receipt_line'
      AND grl.goods_receipt_id = p_receipt_id
      AND sm.movement_type = 'recepcion'
  LOOP
    INSERT INTO stock_movement (
      account_id, location_id, recipe_item_id,
      movement_type, qty_base, unit_cost, cost_provisional,
      source_type, source_id, lot_code, expiry_date,
      occurred_at, notes, created_by, created_by_name
    )
    VALUES (
      v_mov.account_id, v_mov.location_id, v_mov.recipe_item_id,
      'ajuste', -v_mov.qty_base, v_mov.unit_cost, v_mov.cost_provisional,
      'goods_receipt_line', v_mov.source_id, v_mov.lot_code, v_mov.expiry_date,
      now(), 'Reverso por anulación de albarán ' || COALESCE(v_receipt.code, p_receipt_id::text),
      v_user, v_user_name
    );
    PERFORM recompute_location_stock(v_mov.recipe_item_id, v_mov.location_id);
    v_reversed := v_reversed + 1;
  END LOOP;

  -- 2) Marcar la recepción anulada ANTES de recalcular el precio (para que la
  --    recepción superviviente no incluya esta).
  UPDATE goods_receipt SET status = 'anulado', updated_at = now()
    WHERE id = p_receipt_id;

  -- 3) REVERTIR EL last_price de cada línea: al de la recepción CONFIRMADA
  --    superviviente más reciente de ese artículo×proveedor×formato. NULL si
  --    no queda ninguna (no inventamos precio). Solo si hay proveedor en cabecera.
  IF v_receipt.supplier_id IS NOT NULL THEN
    FOR v_line IN
      SELECT * FROM goods_receipt_line
      WHERE goods_receipt_id = p_receipt_id AND recipe_item_id IS NOT NULL
    LOOP
      -- unit_cost (€/base) de la recepción confirmada más reciente que sobrevive,
      -- mismo artículo+proveedor+formato, derivado del ledger ya sellado.
      SELECT sm.unit_cost INTO v_new_price
      FROM stock_movement sm
      JOIN goods_receipt_line grl2 ON grl2.id = sm.source_id AND sm.source_type = 'goods_receipt_line'
      JOIN goods_receipt gr2 ON gr2.id = grl2.goods_receipt_id
      WHERE sm.movement_type = 'recepcion'
        AND sm.recipe_item_id = v_line.recipe_item_id
        AND gr2.supplier_id = v_receipt.supplier_id
        AND gr2.status = 'confirmado'
        AND grl2.purchase_format_id IS NOT DISTINCT FROM v_line.purchase_format_id
        AND gr2.id <> p_receipt_id
      ORDER BY sm.occurred_at DESC
      LIMIT 1;

      -- Escribir el precio recuperado (o NULL) en el article_supplier correspondiente
      -- y recostear el ingrediente y sus platos.
      UPDATE article_supplier
        SET last_price = v_new_price, updated_at = now()
        WHERE account_id = v_receipt.account_id
          AND recipe_item_id = v_line.recipe_item_id
          AND supplier_id = v_receipt.supplier_id
          AND purchase_format_id IS NOT DISTINCT FROM v_line.purchase_format_id
          AND is_active;

      PERFORM kitchen_recompute_raw_cost(v_line.recipe_item_id);
    END LOOP;
  END IF;

  IF v_receipt.purchase_order_id IS NOT NULL THEN
    PERFORM recompute_purchase_order_status(v_receipt.purchase_order_id);
  END IF;

  RETURN v_reversed;
END;
$$;


--
-- Name: warehouse_reliability_queue(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warehouse_reliability_queue(p_account_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.belongs_to_account(p_account_id) then
    raise exception 'warehouse_reliability_queue: sin acceso a la cuenta %', p_account_id;
  end if;

  return (
with rango as (
  select now() - make_interval(days => greatest(p_days, 1)) as desde
),
-- Arrancar por las ventas del rango (idx_sale_sold_at) en vez de por todas las
-- líneas históricas. `materialized` fuerza esta barrera: se resuelve primero y
-- deja un set pequeño (~600 filas) al que enganchar sale_line.
ventas_recientes as materialized (
  select s.id, s.sold_at, s.location_id
    from sale s
   cross join rango r
   where s.account_id = p_account_id
     and s.is_active
     and s.sold_at >= r.desde
     and (p_location_id is null or s.location_id = p_location_id)
),
lineas as (
  select sl.id, sl.product_name, sl.menu_item_id, sl.line_total, sl.ignored_at,
         vr.sold_at, vr.location_id, mi.recipe_item_id
    from ventas_recientes vr
    join sale_line sl on sl.sale_id = vr.id
    left join menu_item mi on mi.id = sl.menu_item_id
   where coalesce(sl.line_type,'product') = 'product'
),
carril_a as (
  select public.sales_product_norm(l.product_name) as norm,
         min(l.product_name) as product_name,
         count(*) as ventas,
         round(sum(coalesce(l.line_total,0))::numeric, 2) as eur,
         max(l.sold_at) as ultima_venta
    from lineas l
   where l.menu_item_id is null and l.ignored_at is null
   group by 1
),
carril_b as (
  select public.sales_product_norm(l.product_name) as norm,
         min(l.product_name) as product_name,
         min(l.recipe_item_id::text)::uuid as recipe_item_id,
         count(*) as ventas,
         round(sum(coalesce(l.line_total,0))::numeric, 2) as eur,
         max(l.sold_at) as ultima_venta
    from lineas l
   where l.menu_item_id is not null and l.ignored_at is null
     and (l.recipe_item_id is null
          or not exists (select 1 from recipe_line rl where rl.parent_item_id = l.recipe_item_id))
   group by 1
),
carril_c as (
  select ri.id as recipe_item_id, ri.name as product_name,
         count(*) as ventas,
         0::numeric as eur,
         max(sm.occurred_at) as ultima_venta,
         (select count(*) from recipe_line rl where rl.child_item_id = ri.id) as en_recetas
    from stock_movement sm
    join recipe_item ri on ri.id = sm.recipe_item_id
   cross join rango r
   where sm.account_id = p_account_id
     and sm.movement_type = 'consumo'
     and sm.occurred_at >= r.desde
     and sm.unit_cost is null
     and (p_location_id is null or sm.location_id = p_location_id)
   group by 1, 2
),
fixes as (
  select distinct on (product_norm) product_norm, fixed_at, recipe_item_id, method
    from sales_mapping_fix
   where account_id = p_account_id and reverted_at is null
   order by product_norm, fixed_at desc
),
verificacion as (
  select f.product_norm,
         count(*) filter (where l.sold_at > f.fixed_at) as ventas_desde,
         count(*) filter (where l.sold_at > f.fixed_at and l.menu_item_id is not null) as ok_desde
    from fixes f
    join lineas l on public.sales_product_norm(l.product_name) = f.product_norm
   group by 1
),
unidas as (
  select 'A' as carril, a.norm, a.product_name, null::uuid as recipe_item_id,
         a.ventas, a.eur, a.ultima_venta, null::bigint as en_recetas
    from carril_a a
  union all
  select 'B', b.norm, b.product_name, b.recipe_item_id, b.ventas, b.eur, b.ultima_venta, null
    from carril_b b
  union all
  select 'C', public.sales_product_norm(c.product_name), c.product_name, c.recipe_item_id,
         c.ventas, c.eur, c.ultima_venta, c.en_recetas
    from carril_c c
)
select coalesce(jsonb_agg(x order by x.carril, x.eur desc, x.ventas desc), '[]'::jsonb)
from (
  select u.carril, u.product_name, u.recipe_item_id, u.ventas, u.eur,
         u.ultima_venta, u.en_recetas,
         f.fixed_at, f.method as fix_method,
         coalesce(v.ventas_desde, 0) as ventas_desde_arreglo,
         coalesce(v.ok_desde, 0)     as ventas_ok_desde_arreglo,
         case
           when f.product_norm is null then 'pendiente'
           when coalesce(v.ventas_desde, 0) = 0 then 'esperando_confirmacion'
           when coalesce(v.ok_desde, 0) >= coalesce(v.ventas_desde, 0) then 'confirmado'
           else 'recaido'
         end as estado
    from unidas u
    left join fixes f on f.product_norm = u.norm
    left join verificacion v on v.product_norm = u.norm
) x
  );
end;
$$;


--
-- Name: FUNCTION warehouse_reliability_queue(p_account_id uuid, p_location_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.warehouse_reliability_queue(p_account_id uuid, p_location_id uuid, p_days integer) IS 'Cola de fiabilidad del almacén: carriles A (sin casar), B (sin escandallo) y C (sin coste), por producto y ordenados por € de impacto, con el estado de verificación de cada arreglo.';


--
-- Name: weekly_rest_minutes_for(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_rest_minutes_for(p_account uuid, p_location uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT bp.weekly_rest_minutes FROM public.break_policy bp
      WHERE bp.account_id = p_account AND bp.location_id = p_location LIMIT 1),
    (SELECT bp.weekly_rest_minutes FROM public.break_policy bp
      WHERE bp.account_id = p_account AND bp.location_id IS NULL LIMIT 1),
    (SELECT bp.weekly_rest_minutes FROM public.break_policy bp
      WHERE bp.account_id = p_account LIMIT 1),
    2160);
$$;


--
-- Name: whatsapp_error_en_palabras(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.whatsapp_error_en_palabras(p_error text) RETURNS TABLE(de_empresa boolean, texto text)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare v_code integer := nullif(substring(coalesce(p_error, '') from '"code"\s*:\s*(\d+)'), '')::integer;
begin
  if p_error is null or btrim(p_error) = '' then
    de_empresa := true; texto := 'El envío falló sin decir por qué.'; return next; return;
  end if;
  if p_error like 'magic_link_failed%' then
    de_empresa := true; texto := 'No se pudo preparar el enlace al portal para el mensaje.'; return next; return;
  end if;
  if p_error like 'sin_username%' then
    de_empresa := false; texto := 'Esa persona no tiene usuario del portal.'; return next; return;
  end if;
  case
    -- Por el código, nunca por «OAuthException»: Meta pone ese tipo también
    -- a los errores de plantilla.
    when v_code in (190, 102) then
      de_empresa := true; texto := 'La llave de WhatsApp de la empresa ha caducado o no es válida: hay que renovarla en Meta.';
    when v_code in (10, 200) then
      de_empresa := true; texto := 'La llave de WhatsApp de la empresa no tiene permiso para mandar mensajes desde ese número.';
    when v_code = 132001 then
      de_empresa := true; texto := 'La plantilla de WhatsApp no existe en Meta (o no está aprobada en español).';
    when v_code in (132000, 132005, 132007, 132012, 132015, 132016, 132068, 132069) then
      de_empresa := true; texto := 'La plantilla de WhatsApp está pausada, desactivada o no encaja con lo que se manda.';
    when v_code in (131031, 368, 131042) then
      de_empresa := true; texto := 'Meta tiene bloqueada la cuenta de WhatsApp de la empresa (o su forma de pago).';
    when v_code in (4, 80007, 130429, 131048, 131056) then
      de_empresa := true; texto := 'Meta está frenando los envíos por exceso de mensajes.';
    when v_code = 131030 then
      de_empresa := true; texto := 'La cuenta de WhatsApp sigue en pruebas y solo puede escribir a los números de su lista.';
    when v_code in (131026, 133010, 131021, 131051) then
      de_empresa := false; texto := 'Ese número no tiene WhatsApp o no puede recibir el mensaje.';
    when v_code = 131047 then
      de_empresa := false; texto := 'Han pasado más de 24 h desde su último mensaje.';
    when v_code is not null then
      de_empresa := true; texto := format('WhatsApp rechazó el mensaje (código %s).', v_code);
    else
      de_empresa := true; texto := 'No se pudo hablar con WhatsApp (la red o Meta no contestaron).';
  end case;
  return next;
end $$;


--
-- Name: whatsapp_estado(text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.whatsapp_estado(p_wamid text, p_estado text, p_at timestamp with time zone DEFAULT now(), p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  update public.clockout_reminder_log
     set entregado_at = case when p_estado in ('delivered', 'read') then coalesce(entregado_at, p_at) else entregado_at end,
         leido_at     = case when p_estado = 'read' then coalesce(leido_at, p_at) else leido_at end,
         status       = case when p_estado = 'failed' then 'failed' else status end,
         error        = case when p_estado = 'failed' then coalesce(p_error, error) else error end,
         updated_at   = now()
   where provider_message_id = p_wamid
   returning id into v_id;
  return v_id is not null;
end $$;


--
-- Name: worker_portal_visibility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_portal_visibility(p_employee_id uuid) RETURNS TABLE(show_hour_bank boolean, show_night_hours boolean, show_labor_cost boolean, show_compliance boolean)
    LANGUAGE sql STABLE
    AS $$
  with g as (select * from public.app_settings where scope='global' limit 1)
  select
    coalesce(g.show_hour_bank_to_employee, false) and coalesce(e.show_hours_balance, true),
    coalesce(g.show_night_hours_to_employee, false),
    coalesce(g.show_labor_cost_to_employee, false),
    coalesce(g.show_compliance_to_employee, false)
  from public.employees e
  left join g on true
  where e.id = p_employee_id;
$$;


--
-- Name: simular(uuid, uuid, uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: r02_prueba; Owner: -
--

CREATE FUNCTION r02_prueba.simular(p_account uuid, p_brand uuid, p_channel uuid, p_location uuid, p_entrada text, p_st text, p_con_dir boolean) RETURNS TABLE(st_final text, carrier text, reason text)
    LANGUAGE plpgsql
    AS $$
declare
  v_id uuid := gen_random_uuid();
  v_st text; v_carrier text; v_reason text;
begin
  begin
    insert into public.sale (id, account_id, location_id, brand_id, channel_id, source, sold_at, total,
                             status, order_status, service_type, delivery_address, raw_tab)
    values (v_id, p_account, p_location, p_brand, p_channel, p_entrada, now(), 10,
            'open', 'new', p_st,
            case when p_con_dir then 'Calle de Prueba 1, 28000 Madrid' end,
            '{"service_type":"delivery"}');
    select s.service_type into v_st from public.sale s where s.id = v_id;
    select d.carrier, d.reason into v_carrier, v_reason from public.resolve_dispatch(v_id) d;
    raise exception 'r02_deshacer';
  exception when raise_exception then
    if sqlerrm <> 'r02_deshacer' then raise; end if;
  end;
  return query select v_st, v_carrier, v_reason;
end;
$$;


--
-- Name: audit_log_entries; Type: TABLE; Schema: auth; Owner: -
--

CREATE TABLE auth.audit_log_entries (
    instance_id uuid,
    id uuid NOT NULL,
    payload json,
    created_at timestamp with time zone,
    ip_address character varying(64) DEFAULT ''::character varying NOT NULL
);


--
-- Name: TABLE audit_log_entries; Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON TABLE auth.audit_log_entries IS 'Auth: Audit trail for user actions.';


--
-- Name: custom_oauth_providers; Type: TABLE; Schema: auth; Owner: -
--

CREATE TABLE auth.custom_oauth_providers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider_type text NOT NULL,
    identifier text NOT NULL,
    name text NOT NULL,
    client_id text NOT NULL,
    client_secret text NOT NULL,
    acceptable_client_ids text[] DEFAULT '{}'::text[] NOT NULL,
    scopes text[] DEFAULT '{}'::text[] NOT NULL,
    pkce_enabled boolean DEFAULT true NOT NULL,
    attribute_mapping jsonb DEFAULT '{}'::jsonb NOT NULL,
    authorization_params jsonb DEFAULT '{}'::jsonb NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    email_optional boolean DEFAULT false NOT NULL,
    issuer text,
    discovery_url text,
    skip_nonce_check boolean DEFAULT false NOT NULL,
    cached_discovery jsonb,
    discovery_cached_at timestamp with time zone,
    authorization_url text,
    token_url text,
    userinfo_url text,
    jwks_uri text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    custom_claims_allowlist text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT custom_oauth_providers_authorization_url_https CHECK (((authorization_url IS NULL) OR (authorization_url ~~ 'https://%'::text))),
    CONSTRAINT custom_oauth_providers_authorization_url_length CHECK (((authorization_url IS NULL) OR (char_length(authorization_url) <= 2048))),
    CONSTRAINT custom_oauth_providers_client_id_length CHECK (((char_length(client_id) >= 1) AND (char_length(client_id) <= 512))),
    CONSTRAINT custom_oauth_providers_discovery_url_length CHECK (((discovery_url IS NULL) OR (char_length(discovery_url) <= 2048))),
    CONSTRAINT custom_oauth_providers_identifier_format CHECK ((identifier ~ '^[a-z0-9][a-z0-9:-]{0,48}[a-z0-9]$'::text)),
    CONSTRAINT custom_oauth_providers_issuer_length CHECK (((issuer IS NULL) OR ((char_length(issuer) >= 1) AND (char_length(issuer) <= 2048)))),
    CONSTRAINT custom_oauth_providers_jwks_uri_https CHECK (((jwks_uri IS NULL) OR (jwks_uri ~~ 'https://%'::text))),
    CONSTRAINT custom_oauth_providers_jwks_uri_length CHECK (((jwks_uri IS NULL) OR (char_length(jwks_uri) <= 2048))),
    CONSTRAINT custom_oauth_providers_name_length CHECK (((char_length(name) >= 1) AND (char_length(name) <= 100))),
    CONSTRAINT custom_oauth_providers_oauth2_requires_endpoints CHECK (((provider_type <> 'oauth2'::text) OR ((authorization_url IS NOT NULL) AND (token_url IS NOT NULL) AND (userinfo_url IS NOT NULL)))),
    CONSTRAINT custom_oauth_providers_oidc_discovery_url_https CHECK (((provider_type <> 'oidc'::text) OR (discovery_url IS NULL) OR (discovery_url ~~ 'https://%'::text))),
    CONSTRAINT custom_oauth_providers_oidc_issuer_https CHECK (((provider_type <> 'oidc'::text) OR (issuer IS NULL) OR (issuer ~~ 'https://%'::text))),
    CONSTRAINT custom_oauth_providers_oidc_requires_issuer CHECK (((provider_type <> 'oidc'::text) OR (issuer IS NOT NULL))),
    CONSTRAINT custom_oauth_providers_provider_type_check CHECK ((provider_type = ANY (ARRAY['oauth2'::text, 'oidc'::text]))),
    CONSTRAINT custom_oauth_providers_token_url_https CHECK (((token_url IS NULL) OR (token_url ~~ 'https://%'::text))),
    CONSTRAINT custom_oauth_providers_token_url_length CHECK (((token_url IS NULL) OR (char_length(token_url) <= 2048))),
    CONSTRAINT custom_oauth_providers_userinfo_url_https CHECK (((userinfo_url IS NULL) OR (userinfo_url ~~ 'https://%'::text))),
    CONSTRAINT custom_oauth_providers_userinfo_url_length CHECK (((userinfo_url IS NULL) OR (char_length(userinfo_url) <= 2048)))
);


