--
-- Name: account_connector; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_connector (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    connector_id uuid NOT NULL,
    status text DEFAULT 'available'::text NOT NULL,
    scope text DEFAULT 'account'::text NOT NULL,
    brand_id uuid,
    location_id uuid,
    credentials_ref text,
    external_account_id text,
    last_sync_at timestamp with time zone,
    last_error text,
    requested_by uuid,
    requested_at timestamp with time zone,
    connected_by uuid,
    connected_at timestamp with time zone,
    is_active boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    config jsonb,
    company_id uuid,
    token_ref text,
    token_expires_at timestamp with time zone,
    CONSTRAINT account_connector_company_scope CHECK (((scope = 'company'::text) = (company_id IS NOT NULL))),
    CONSTRAINT account_connector_scope_check CHECK ((scope = ANY (ARRAY['account'::text, 'brand'::text, 'location'::text, 'company'::text]))),
    CONSTRAINT account_connector_status_check CHECK ((status = ANY (ARRAY['available'::text, 'requested'::text, 'connecting'::text, 'connected'::text, 'paused'::text, 'error'::text, 'down'::text])))
);


--
-- Name: COLUMN account_connector.config; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_connector.config IS 'Campos de configuración NO sensibles del conector (ej. store_ids, auto_accept, verify_signature). Los secretos NO van aquí: se cifran en Vault y se referencian por credentials_ref. (D2)';


--
-- Name: COLUMN account_connector.company_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_connector.company_id IS 'Empresa de la conexión cuando scope = company (Diez: una empresa = una base de datos).';


--
-- Name: COLUMN account_connector.token_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_connector.token_ref IS 'Id en Vault del token de acceso vigente (Diez: 14 días). Nunca el token.';


--
-- Name: COLUMN account_connector.token_expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_connector.token_expires_at IS 'Cuándo caduca el token de token_ref; se renueva antes.';


