-- Name: accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    legal_name text,
    cif text,
    billing_email text,
    billing_phone text,
    billing_address jsonb DEFAULT '{}'::jsonb,
    country text DEFAULT 'ES'::text NOT NULL,
    timezone text DEFAULT 'Europe/Madrid'::text,
    locale text DEFAULT 'es-ES'::text,
    currency text DEFAULT 'EUR'::text,
    status text DEFAULT 'trial'::text NOT NULL,
    is_internal boolean DEFAULT false NOT NULL,
    trial_ends_at timestamp with time zone,
    stripe_customer_id text,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    slug text NOT NULL,
    suspended_at timestamp with time zone,
    suspended_by uuid,
    suspension_reason text,
    archived_at timestamp with time zone,
    deleted_at timestamp with time zone,
    past_due_at timestamp with time zone,
    logo_url text,
    shop_hero_url text,
    shop_tagline text,
    stripe_account_id text,
    shop_fee_bps integer DEFAULT 0 NOT NULL,
    stripe_charges_enabled boolean DEFAULT false NOT NULL,
    stripe_details_submitted boolean DEFAULT false NOT NULL,
    shop_pay_online boolean DEFAULT true NOT NULL,
    shop_pay_cash_pickup boolean DEFAULT false NOT NULL,
    shop_pay_cash_delivery boolean DEFAULT false NOT NULL,
    shop_logo_url text,
    shop_subtitle text,
    shop_coupon_margin_floor_pct numeric,
    business_type text DEFAULT 'dark_kitchen'::text NOT NULL,
    track_base_url text,
    product_brand text,
    tax_advisor_since timestamp with time zone,
    tax_advisor_by uuid,
    firma_registro_mes boolean,
    is_demo boolean,
    CONSTRAINT accounts_business_type_check CHECK ((business_type = ANY (ARRAY['dark_kitchen'::text, 'bar'::text, 'restaurante'::text, 'cafeteria'::text, 'hotel'::text, 'otro'::text, 'otra_actividad'::text]))),
    CONSTRAINT accounts_lifecycle_order CHECK (((deleted_at IS NULL) OR (archived_at IS NULL) OR (deleted_at >= archived_at))),
    CONSTRAINT accounts_product_brand_formato CHECK (((product_brand IS NULL) OR (product_brand ~ '^[a-z][a-z0-9_]{1,40}$'::text))),
    CONSTRAINT accounts_slug_format CHECK (((slug ~ '^[a-z0-9][a-z0-9-]{0,62}[a-z0-9]$'::text) OR ((length(slug) = 1) AND (slug ~ '^[a-z0-9]$'::text)))),
    CONSTRAINT accounts_status_check CHECK ((status = ANY (ARRAY['trial'::text, 'active'::text, 'past_due'::text, 'suspended'::text, 'canceled'::text]))),
    CONSTRAINT accounts_suspended_consistency CHECK ((((suspended_at IS NULL) AND (suspended_by IS NULL) AND (suspension_reason IS NULL)) OR ((suspended_at IS NOT NULL) AND (suspended_by IS NOT NULL) AND (suspension_reason IS NOT NULL))))
);


--
-- Name: TABLE accounts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.accounts IS 'Cuenta empresarial (tenant facturable). Agrupa varios locations.';


--
-- Name: COLUMN accounts.is_internal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.is_internal IS 'Cuentas internas con acceso completo sin requerir suscripcion.';


--
-- Name: COLUMN accounts.suspended_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.suspended_at IS 'Fecha de suspensión temporal de la cuenta. NULL = activa.';


--
-- Name: COLUMN accounts.suspended_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.suspended_by IS 'auth.users.id del platform_admin que suspendió la cuenta.';


--
-- Name: COLUMN accounts.suspension_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.suspension_reason IS 'Razón de la suspensión. Obligatoria si suspended_at NO ES NULL.';


--
-- Name: COLUMN accounts.archived_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.archived_at IS 'Fecha de archivado. NULL = no archivada.';


--
-- Name: COLUMN accounts.deleted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.deleted_at IS 'Fecha de borrado lógico (soft delete). Ventana de gracia 30 días.';


--
-- Name: COLUMN accounts.past_due_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.past_due_at IS 'Momento de entrada en past_due. NULL si no está en impago. Base del cálculo de días de gracia.';


--
-- Name: COLUMN accounts.stripe_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.stripe_account_id IS 'Stripe Connect: cuenta conectada (acct_...) del restaurante. Cobra los pedidos del Shop por direct charge.';


--
-- Name: COLUMN accounts.shop_fee_bps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.shop_fee_bps IS 'Comisión de Folvy sobre el total del pedido del Shop, en puntos básicos (100 = 1%). 0 = sin comisión.';


--
-- Name: COLUMN accounts.product_brand; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.product_brand IS 'C06 · Marca con la que se vendió una cuenta SOLO de contabilidad (id de supabase/functions/_shared/marcas.ts). Null: cuenta de Folvy de siempre.';


--
-- Name: COLUMN accounts.tax_advisor_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.tax_advisor_since IS 'P01. Desde cuándo la cuenta dice que es una asesoría («Soy una asesoría»): enseña «Impuestos de tus clientes». Null = no lo es. Lo pone conta_despacho_marcar.';


--
-- Name: COLUMN accounts.tax_advisor_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.tax_advisor_by IS 'P01. Quién marcó la cuenta como asesoría.';


--
-- Name: COLUMN accounts.firma_registro_mes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.firma_registro_mes IS 'L1a-H (29/10/2026). «Pedir a cada persona que firme su registro del mes» en su portal. NULL o false: apagado (no sale la tarjeta de la firma ni ningún aviso de firma). Lo cambia el administrador de la cuenta con firma_registro_mes_pedir. Las firmas ya hechas no dependen de esto.';


--
-- Name: COLUMN accounts.is_demo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounts.is_demo IS 'DM1 (31/10/2026). Cuenta de demostración: no manda nada fuera (cuenta_puede_salir) y se restaura con un botón. Solo la pone el superadministrador.';


--
-- Name: agent_pause; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_pause (
    account_id uuid NOT NULL,
    agent_key text NOT NULL,
    paused_at timestamp with time zone DEFAULT now() NOT NULL,
    paused_by uuid,
    paused_by_label text
);


--
-- Name: TABLE agent_pause; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.agent_pause IS 'Agentes en pausa POR CUENTA. Una fila = ese agente no trabaja para esa cuenta. El cron sigue corriendo; el agente consulta esto y se salta la cuenta.';


--
-- Name: agent_run_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_run_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    ran_at timestamp with time zone DEFAULT now() NOT NULL,
    signals jsonb NOT NULL,
    decisions jsonb NOT NULL,
    campaigns_created integer DEFAULT 0 NOT NULL
);


--
-- Name: ai_action; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_action (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    agent text NOT NULL,
    tool_name text NOT NULL,
    risk text DEFAULT 'L1'::text NOT NULL,
    status text DEFAULT 'proposed'::text NOT NULL,
    summary text NOT NULL,
    target_table text,
    target_id uuid,
    args jsonb DEFAULT '{}'::jsonb NOT NULL,
    effect_preview jsonb,
    result jsonb,
    rollback_hint jsonb,
    error_message text,
    proposed_by uuid,
    confirmed_by uuid,
    session_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_at timestamp with time zone,
    executed_at timestamp with time zone,
    CONSTRAINT ai_action_risk_check CHECK ((risk = ANY (ARRAY['L0'::text, 'L1'::text, 'L2'::text]))),
    CONSTRAINT ai_action_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'confirmed'::text, 'executed'::text, 'rejected'::text, 'failed'::text, 'rolled_back'::text])))
);


--
-- Name: ai_action_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_action_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    action text NOT NULL,
    source text DEFAULT 'ai'::text NOT NULL,
    table_key text NOT NULL,
    row_id uuid,
    field text,
    before_value jsonb,
    after_value jsonb,
    reason text NOT NULL,
    suggestion_id uuid,
    done_at timestamp with time zone DEFAULT now() NOT NULL,
    done_for uuid,
    done_for_name text,
    undone_at timestamp with time zone,
    undone_by uuid,
    undone_by_name text,
    CONSTRAINT ai_action_log_action_check CHECK ((action = ANY (ARRAY['poner'::text, 'anadir_actividad'::text]))),
    CONSTRAINT ai_action_log_reason_check CHECK ((length(TRIM(BOTH FROM reason)) > 0)),
    CONSTRAINT ai_action_log_source_check CHECK ((source = ANY (ARRAY['ai'::text, 'import'::text])))
);


--
-- Name: TABLE ai_action_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ai_action_log IS 'C00 (§6.3). Toda acción de la IA: qué, sobre qué, por qué, cuándo y para quién. Se deshace desde aquí. Solo lo escriben las funciones conta_ia_*.';


--
-- Name: ai_data_origin; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_data_origin (
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    table_key text NOT NULL,
    row_id uuid NOT NULL,
    field text NOT NULL,
    source text NOT NULL,
    value_set jsonb,
    reason text NOT NULL,
    set_at timestamp with time zone DEFAULT now() NOT NULL,
    set_by uuid,
    CONSTRAINT ai_data_origin_reason_check CHECK ((length(TRIM(BOTH FROM reason)) > 0)),
    CONSTRAINT ai_data_origin_source_check CHECK ((source = ANY (ARRAY['ai'::text, 'import'::text]))),
    CONSTRAINT ai_data_origin_table_key_check CHECK ((table_key = ANY (ARRAY['company'::text, 'company_tax_profile'::text, 'company_activity'::text])))
);


--
-- Name: TABLE ai_data_origin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ai_data_origin IS 'C00 (§6.1). Qué datos puso la IA o una importación, con su motivo y el valor que puso. Lo que no está aquí lo escribió una persona.';


--
-- Name: ai_interaction; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_interaction (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    user_id uuid,
    user_name text,
    surface text NOT NULL,
    module text,
    session_id uuid,
    request jsonb NOT NULL,
    response jsonb,
    tools_used jsonb,
    model text,
    tokens_in integer,
    tokens_out integer,
    duration_ms integer,
    status text DEFAULT 'ok'::text NOT NULL,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_interaction_status_valid CHECK ((status = ANY (ARRAY['ok'::text, 'error'::text, 'cancelled'::text]))),
    CONSTRAINT ai_interaction_surface_valid CHECK ((surface = ANY (ARRAY['chat'::text, 'aicard'::text, 'background'::text])))
);


--
-- Name: ai_memory; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_memory (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    scope text NOT NULL,
    key text NOT NULL,
    value jsonb NOT NULL,
    source text DEFAULT 'inferred'::text NOT NULL,
    confidence numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_memory_conf_range CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))),
    CONSTRAINT ai_memory_scope_valid CHECK ((scope = ANY (ARRAY['vocabulary'::text, 'preference'::text, 'fact'::text, 'snapshot'::text])))
);


--
-- Name: ai_suggestion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_suggestion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    kind text NOT NULL,
    reason_key text NOT NULL,
    title text NOT NULL,
    why text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    decided_by_name text,
    CONSTRAINT ai_suggestion_kind_check CHECK ((kind = ANY (ARRAY['modelo'::text, 'plan'::text]))),
    CONSTRAINT ai_suggestion_status_check CHECK ((status = ANY (ARRAY['open'::text, 'accepted'::text, 'rejected'::text])))
);


--
-- Name: TABLE ai_suggestion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ai_suggestion IS 'C00 (§6.2). Lo que la IA propone. Una rechazada no vuelve por el mismo motivo: (empresa, clase, motivo) es único.';


--
-- Name: allergen; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.allergen (
    code text NOT NULL,
    name_es text NOT NULL,
    name_en text NOT NULL,
    icon text NOT NULL,
    eu_reference text NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: allocation_rule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.allocation_rule (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    location_id uuid NOT NULL,
    pct numeric(7,4) NOT NULL,
    valid_from date NOT NULL,
    valid_to date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT allocation_rule_fechas CHECK (((valid_to IS NULL) OR (valid_to >= valid_from))),
    CONSTRAINT allocation_rule_pct_check CHECK (((pct > (0)::numeric) AND (pct <= (100)::numeric)))
);


--
-- Name: TABLE allocation_rule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.allocation_rule IS 'C04. Cómo se reparte un gasto común entre los locales (porcentajes revisables, con vigencia). Por defecto lo común se queda común y el informe reparte.';


--
-- Name: analysis_account; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_account (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    parent_id uuid,
    account_type text DEFAULT 'expense'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT analysis_account_account_type_check CHECK ((account_type = ANY (ARRAY['expense'::text, 'revenue'::text, 'cost_of_goods'::text, 'other'::text])))
);


--
-- Name: TABLE analysis_account; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.analysis_account IS 'Cuentas de análisis contables (Tspoon "Cuenta de análisis"). Scope cuenta. Soporta jerarquía con parent_id.';


--
-- Name: annual_accounts_choice; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.annual_accounts_choice (
    fiscal_year_id uuid NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    model text NOT NULL,
    proposed_model text NOT NULL,
    figures jsonb DEFAULT '{}'::jsonb NOT NULL,
    reason text,
    chosen_at timestamp with time zone DEFAULT now() NOT NULL,
    chosen_by uuid,
    chosen_by_name text,
    CONSTRAINT annual_accounts_choice_figures_check CHECK ((jsonb_typeof(figures) = 'object'::text)),
    CONSTRAINT annual_accounts_choice_model_check CHECK ((model = ANY (ARRAY['normal'::text, 'abreviado'::text, 'pymes'::text]))),
    CONSTRAINT annual_accounts_choice_proposed_model_check CHECK ((proposed_model = ANY (ARRAY['normal'::text, 'abreviado'::text, 'pymes'::text])))
);


--
-- Name: TABLE annual_accounts_choice; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.annual_accounts_choice IS 'C05 · regla 4. El modelo de cuentas anuales de cada ejercicio: el que propuso Folvy por los límites (LSC 257.1 y 258.1; RD 1515/2007 art. 2.1) y el elegido, que puede ser más completo, nunca menos.';


--
-- Name: annual_accounts_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.annual_accounts_line (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    model text NOT NULL,
    statement text NOT NULL,
    code text NOT NULL,
    parent_code text,
    text text NOT NULL,
    level smallint NOT NULL,
    sort_order integer NOT NULL,
    side text,
    is_total boolean DEFAULT false NOT NULL,
    to_create boolean DEFAULT false NOT NULL,
    legal_ref text NOT NULL,
    source_key text NOT NULL,
    source_sha256 text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT annual_accounts_line_level_check CHECK (((level >= 1) AND (level <= 6))),
    CONSTRAINT annual_accounts_line_model_check CHECK ((model = ANY (ARRAY['normal'::text, 'abreviado'::text, 'pymes'::text]))),
    CONSTRAINT annual_accounts_line_side_check CHECK (((side IS NULL) OR (side = ANY (ARRAY['activo'::text, 'pn_pasivo'::text])))),
    CONSTRAINT annual_accounts_line_statement_check CHECK ((statement = ANY (ARRAY['balance'::text, 'pyg'::text, 'igrpn'::text]))),
    CONSTRAINT annual_accounts_line_text_check CHECK ((length(TRIM(BOTH FROM text)) > 0))
);


--
-- Name: TABLE annual_accounts_line; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.annual_accounts_line IS 'C05. Líneas de los modelos oficiales de cuentas anuales del PGC (RD 1514/2007 y 1515/2007, tercera parte), tal cual el texto consolidado del BOE, más las partidas «a crear» de las normas de elaboración (to_create). Serie: la carga una migración generada; no se edita.';


--
-- Name: annual_accounts_mapping; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.annual_accounts_mapping (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid,
    company_id uuid,
    model text NOT NULL,
    statement text NOT NULL,
    line_code text NOT NULL,
    account_prefix text NOT NULL,
    sign text DEFAULT 'suma'::text NOT NULL,
    by_balance text,
    origin text NOT NULL,
    any_sign boolean DEFAULT false NOT NULL,
    note text,
    legal_ref text,
    excluded boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    CONSTRAINT annual_accounts_mapping_account_prefix_check CHECK ((account_prefix ~ '^[0-9]{1,8}$'::text)),
    CONSTRAINT annual_accounts_mapping_by_balance_check CHECK (((by_balance IS NULL) OR (by_balance = ANY (ARRAY['deudor'::text, 'acreedor'::text])))),
    CONSTRAINT annual_accounts_mapping_model_check CHECK ((model = ANY (ARRAY['normal'::text, 'abreviado'::text, 'pymes'::text]))),
    CONSTRAINT annual_accounts_mapping_origen_empresa CHECK (((company_id IS NULL) = (origin <> 'empresa'::text))),
    CONSTRAINT annual_accounts_mapping_origin_check CHECK ((origin = ANY (ARRAY['boe'::text, 'a_crear'::text, 'resultado'::text, 'defecto'::text, 'empresa'::text]))),
    CONSTRAINT annual_accounts_mapping_serie_o_empresa CHECK (((account_id IS NULL) = (company_id IS NULL))),
    CONSTRAINT annual_accounts_mapping_sign_check CHECK ((sign = ANY (ARRAY['suma'::text, 'resta'::text]))),
    CONSTRAINT annual_accounts_mapping_statement_check CHECK ((statement = ANY (ARRAY['balance'::text, 'pyg'::text, 'igrpn'::text])))
);


--
-- Name: TABLE annual_accounts_mapping; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.annual_accounts_mapping IS 'C05. Línea ↔ cuentas (prefijos). Serie desde el BOE (origin boe/a_crear/resultado/defecto) y cambios por empresa (origin empresa) con historial en annual_accounts_mapping_change. Gana el prefijo más largo; by_balance reparte por el signo del saldo.';


--
-- Name: annual_accounts_mapping_change; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.annual_accounts_mapping_change (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    model text NOT NULL,
    statement text NOT NULL,
    account_prefix text,
    action text NOT NULL,
    from_line text,
    to_line text,
    reason text,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by uuid,
    changed_by_name text,
    CONSTRAINT annual_accounts_mapping_change_action_check CHECK ((action = ANY (ARRAY['cambia'::text, 'deja_fuera'::text, 'estandar'::text])))
);


--
-- Name: TABLE annual_accounts_mapping_change; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.annual_accounts_mapping_change IS 'C05 · regla 9. Rastro de cada cambio del mapeo de una empresa: quién, cuándo, de qué línea a cuál; «estandar» = volvió a la serie del PGC.';


--
-- Name: app_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope text DEFAULT 'global'::text NOT NULL,
    rounding_tolerance_min integer DEFAULT 8 NOT NULL,
    show_hour_bank_to_employee boolean DEFAULT false NOT NULL,
    late_alert_min integer DEFAULT 15 NOT NULL,
    forgot_clockout_min integer DEFAULT 30 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    account_id uuid,
    show_night_hours_to_employee boolean DEFAULT false NOT NULL,
    show_labor_cost_to_employee boolean DEFAULT false NOT NULL,
    show_compliance_to_employee boolean DEFAULT false NOT NULL,
    ctb_diff_pct numeric DEFAULT 10 NOT NULL,
    ctb_diff_eur numeric DEFAULT 15 NOT NULL,
    aviso_olvido_desde time without time zone,
    aviso_olvido_hasta time without time zone,
    CONSTRAINT app_settings_scope_check CHECK ((scope = 'global'::text))
);


--
-- Name: COLUMN app_settings.show_night_hours_to_employee; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.app_settings.show_night_hours_to_employee IS 'F8 Si el trabajador ve sus horas nocturnas en el portal. Default false (prudente).';


--
-- Name: COLUMN app_settings.show_labor_cost_to_employee; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.app_settings.show_labor_cost_to_employee IS 'F8 Si el trabajador ve su coste laboral en el portal. Default false. Dato muy sensible.';


--
-- Name: COLUMN app_settings.show_compliance_to_employee; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.app_settings.show_compliance_to_employee IS 'F8 Si el trabajador ve avisos de convenio/infracciones propios. Default false (evita semaforo de culpa).';


--
-- Name: COLUMN app_settings.ctb_diff_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.app_settings.ctb_diff_pct IS 'Diferencia mínima, en % de lo facturado, para reclamar una línea de cantidad continua (peso/volumen/longitud). Las unidades no usan umbral.';


--
-- Name: COLUMN app_settings.ctb_diff_eur; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.app_settings.ctb_diff_eur IS 'Valor en euros a partir del cual una diferencia se reclama aunque no llegue al %. Evita perdonar en silencio en cantidades grandes.';


--
-- Name: COLUMN app_settings.aviso_olvido_desde; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.app_settings.aviso_olvido_desde IS 'L1a PR 3: desde qué hora (Madrid) puede salir el WhatsApp del olvido. Null: 08:00.';


--
-- Name: COLUMN app_settings.aviso_olvido_hasta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.app_settings.aviso_olvido_hasta IS 'L1a PR 3: hasta qué hora (Madrid) puede salir el WhatsApp del olvido; después, solo el portal. Null: 22:00.';


--
-- Name: appcc_audit_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.appcc_audit_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    section_id uuid NOT NULL,
    code text NOT NULL,
    question text NOT NULL,
    help_text text,
    display_order integer DEFAULT 0,
    scoring_type text DEFAULT 'binary'::text,
    weight integer DEFAULT 1,
    creates_incident_on_fail boolean DEFAULT false,
    incident_severity text,
    CONSTRAINT appcc_audit_items_incident_severity_check CHECK ((incident_severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT appcc_audit_items_scoring_type_check CHECK ((scoring_type = ANY (ARRAY['binary'::text, 'scale_0_5'::text, 'na_allowed'::text]))),
    CONSTRAINT appcc_audit_items_weight_check CHECK (((weight >= 1) AND (weight <= 10)))
);


--
-- Name: appcc_audit_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.appcc_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    event_type text NOT NULL,
    event_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    performed_at timestamp with time zone DEFAULT now() NOT NULL,
    performed_by uuid,
