-- Name: TABLE aviso_empresa; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.aviso_empresa IS 'L1a PR 3: lo que la empresa tiene que saber el mismo día: un fichaje fuera del radio (no el habitual) y que los avisos de olvido dejan de salir. Lo enseña «Equipo» y sale por correo a los administradores y a los encargados del local (clockout-reminder).';


--
-- Name: bank_account_iban; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_account_iban (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    treasury_account_id uuid NOT NULL,
    iban text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    CONSTRAINT bank_account_iban_iban_check CHECK ((iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$'::text))
);


--
-- Name: TABLE bank_account_iban; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_account_iban IS 'B01 (respuesta 3). El IBAN que trajo un extracto y la cuenta de Folvy a la que la persona dijo que va: la siguiente subida de ese IBAN se empareja sola.';


--
-- Name: bank_activity_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_activity_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    movement_id uuid,
    match_id uuid,
    statement_id uuid,
    action text NOT NULL,
    by_who text NOT NULL,
    summary text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    CONSTRAINT bank_activity_log_action_check CHECK ((action = ANY (ARRAY['importado'::text, 'casado'::text, 'enlazado'::text, 'propuesto'::text, 'por_aclarar'::text, 'validado'::text, 'deshecho'::text, 'ignorado'::text, 'regla'::text, 'cierre'::text, 'reabierto'::text, 'agente'::text]))),
    CONSTRAINT bank_activity_log_by_who_check CHECK ((by_who = ANY (ARRAY['folvy'::text, 'persona'::text]))),
    CONSTRAINT bank_activity_log_summary_check CHECK ((length(TRIM(BOTH FROM summary)) > 0))
);


--
-- Name: TABLE bank_activity_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_activity_log IS 'B01. «Lo que ha hecho Folvy» (y la persona): cada importación, casado, propuesta, validación y deshacer, con su frase. Solo crece.';


--
-- Name: bank_agent_run; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_agent_run (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    trigger text NOT NULL,
    ran_at timestamp with time zone DEFAULT now() NOT NULL,
    matched integer DEFAULT 0 NOT NULL,
    proposed integer DEFAULT 0 NOT NULL,
    to_clarify integer DEFAULT 0 NOT NULL,
    before_cutover integer DEFAULT 0 NOT NULL,
    failures integer DEFAULT 0 NOT NULL,
    summary text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    run_by uuid,
    run_by_name text,
    CONSTRAINT bank_agent_run_before_cutover_check CHECK ((before_cutover >= 0)),
    CONSTRAINT bank_agent_run_failures_check CHECK ((failures >= 0)),
    CONSTRAINT bank_agent_run_matched_check CHECK ((matched >= 0)),
    CONSTRAINT bank_agent_run_proposed_check CHECK ((proposed >= 0)),
    CONSTRAINT bank_agent_run_summary_check CHECK ((length(TRIM(BOTH FROM summary)) > 0)),
    CONSTRAINT bank_agent_run_to_clarify_check CHECK ((to_clarify >= 0)),
    CONSTRAINT bank_agent_run_trigger_check CHECK ((trigger = ANY (ARRAY['extracto'::text, 'diario'::text])))
);


--
-- Name: TABLE bank_agent_run; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_agent_run IS 'B01 (respuesta 4). Cada pasada del agente «Conciliación» (después de un extracto, o la del día) y lo que hizo. Su resumen es la banda verde de Bancos.';


--
-- Name: bank_aggregator_connection; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_aggregator_connection (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    provider text NOT NULL,
    bank_name text NOT NULL,
    secret_name text NOT NULL,
    renew_url text,
    enabled boolean DEFAULT true NOT NULL,
    last_run_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bank_aggregator_connection_bank_name_check CHECK ((length(TRIM(BOTH FROM bank_name)) > 0)),
    CONSTRAINT bank_aggregator_connection_provider_check CHECK ((provider ~ '^[a-z0-9-]+$'::text)),
    CONSTRAINT bank_aggregator_connection_renew_url_check CHECK (((renew_url IS NULL) OR (renew_url ~ '^https://'::text))),
    CONSTRAINT bank_aggregator_connection_secret_name_check CHECK ((secret_name ~ '^[A-Z][A-Z0-9_]*$'::text))
);


--
-- Name: TABLE bank_aggregator_connection; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_aggregator_connection IS 'B01c. Qué empresa trae los movimientos de sus bancos sola, por qué proveedor, con qué secreto de las funciones (el credentials.json; aquí solo su NOMBRE) y dónde se renueva el permiso. Solo la escribe una migración: no se ofrece a otros clientes todavía. last_error: por qué no se pudo ni abrir la conexión la última noche (null si se abrió).';


--
-- Name: bank_aggregator_link; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_aggregator_link (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    treasury_account_id uuid NOT NULL,
    provider text NOT NULL,
    external_account_id text NOT NULL,
    consent_id text NOT NULL,
    consent_valid_until timestamp with time zone NOT NULL,
    status text DEFAULT 'activo'::text NOT NULL,
    last_sync_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    bank_name text,
    renew_url text,
    last_run_at timestamp with time zone,
    last_status text,
    last_message text,
    bank_balance numeric(14,2),
    bank_balance_date date,
    last_new integer,
    last_repeated integer,
    last_from date,
    last_to date,
    CONSTRAINT bank_aggregator_link_last_status_check CHECK (((last_status IS NULL) OR (last_status = ANY (ARRAY['al_dia'::text, 'sin_movimientos'::text, 'permiso_caducado'::text, 'fallo'::text])))),
    CONSTRAINT bank_aggregator_link_provider_check CHECK ((provider = ANY (ARRAY['simulado'::text, 'enable_banking'::text, 'open_banking_io'::text, 'revolut'::text]))),
    CONSTRAINT bank_aggregator_link_renew_url_check CHECK (((renew_url IS NULL) OR (renew_url ~ '^https://'::text))),
    CONSTRAINT bank_aggregator_link_status_check CHECK ((status = ANY (ARRAY['activo'::text, 'caducado'::text, 'revocado'::text])))
);


--
-- Name: TABLE bank_aggregator_link; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_aggregator_link IS 'B01 (respuesta 4). Una cuenta del banco conectada por un agregador (PSD2, RDL 19/2018 art. 3.38) y su consentimiento, que caduca a los 180 días. Sin pantalla hasta que exista el contrato.';


--
-- Name: COLUMN bank_aggregator_link.bank_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_aggregator_link.bank_name IS 'B01c. El banco, como se enseña: «Conectada con BBVA».';


--
-- Name: COLUMN bank_aggregator_link.renew_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_aggregator_link.renew_url IS 'B01c. Dónde se renueva el permiso (el botón «Renovar»).';


--
-- Name: COLUMN bank_aggregator_link.last_run_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_aggregator_link.last_run_at IS 'B01c. La última pasada de la noche, haya ido bien o mal (last_sync_at: la última que leyó bien).';


--
-- Name: COLUMN bank_aggregator_link.last_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_aggregator_link.last_status IS 'B01c. Cómo fue la última pasada: al_dia, sin_movimientos, permiso_caducado o fallo (los dos últimos siempre con last_message).';


--
-- Name: COLUMN bank_aggregator_link.bank_balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_aggregator_link.bank_balance IS 'B01c. El saldo contable que dio el banco en la última pasada (bank_balance_date: de qué día).';


--
-- Name: bank_card; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_card (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    treasury_account_id uuid NOT NULL,
    last4 text NOT NULL,
    holder_name text NOT NULL,
    location_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    deactivated_at timestamp with time zone,
    CONSTRAINT bank_card_holder_name_check CHECK ((length(TRIM(BOTH FROM holder_name)) > 0)),
    CONSTRAINT bank_card_last4_check CHECK ((last4 ~ '^[0-9]{4}$'::text))
);


--
-- Name: TABLE bank_card; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_card IS 'B01 (respuesta 3). Una tarjeta de débito de la empresa como medio de pago de su cuenta del banco: solo los últimos 4 dígitos (nunca el número entero), quién la lleva y su local. El motor reconoce por esos dígitos qué tarjeta pagó.';


--
-- Name: bank_match_item; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_match_item (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    match_id uuid NOT NULL,
    supplier_invoice_id uuid,
    channel_settlement_id uuid,
    other_movement_id uuid,
    party_id uuid,
    amount numeric(14,2) NOT NULL,
    marked_by_bank boolean DEFAULT false NOT NULL,
    tax_return_id uuid,
    customer_invoice_id uuid,
    CONSTRAINT bank_match_item_uno CHECK ((num_nonnulls(supplier_invoice_id, channel_settlement_id, other_movement_id, party_id, tax_return_id, customer_invoice_id) >= 1))
);


--
-- Name: TABLE bank_match_item; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_match_item IS 'B01. A qué y por cuánto: una o varias facturas recibidas (pago entero, en partes, varias en un pago), una liquidación, el otro movimiento de un traspaso, o el tercero.';


--
-- Name: COLUMN bank_match_item.tax_return_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_match_item.tax_return_id IS 'I01b. La declaración que paga (o cobra) este movimiento. Deshacer el casado la devuelve a «Contabilizado».';


--
-- Name: COLUMN bank_match_item.customer_invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_match_item.customer_invoice_id IS 'PC01 · La factura emitida que cobra este casado (bank_casar, tipo factura_emitida con «facturas»).';


--
-- Name: bank_month_close; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_month_close (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    treasury_account_id uuid NOT NULL,
    month date NOT NULL,
    bank_balance numeric(14,2),
    book_balance numeric(14,2) NOT NULL,
    difference numeric(14,2),
    loose_count integer NOT NULL,
    loose_amount numeric(14,2) NOT NULL,
    knowingly boolean DEFAULT false NOT NULL,
    reason text,
    status text DEFAULT 'cerrado'::text NOT NULL,
    closed_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_by uuid,
    closed_by_name text,
    reopened_at timestamp with time zone,
    reopened_by_name text,
    reopen_reason text,
    CONSTRAINT bank_month_close_a_sabiendas CHECK (((NOT knowingly) OR (length(TRIM(BOTH FROM COALESCE(reason, ''::text))) > 0))),
    CONSTRAINT bank_month_close_loose_count_check CHECK ((loose_count >= 0)),
    CONSTRAINT bank_month_close_month_check CHECK ((EXTRACT(day FROM month) = (1)::numeric)),
    CONSTRAINT bank_month_close_reabierto CHECK (((status = 'reabierto'::text) = ((reopened_at IS NOT NULL) AND (reopen_reason IS NOT NULL)))),
    CONSTRAINT bank_month_close_status_check CHECK ((status = ANY (ARRAY['cerrado'::text, 'reabierto'::text]))),
    CONSTRAINT bank_month_close_sueltos CHECK ((knowingly OR ((loose_count = 0) AND (COALESCE(difference, (0)::numeric) = (0)::numeric) AND (bank_balance IS NOT NULL))))
);


--
-- Name: TABLE bank_month_close; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_month_close IS 'B01 (respuesta 4). El cierre del mes de un banco: saldo del banco y de contabilidad, la diferencia y lo que la explica. Con movimientos sin casar o diferencia, solo «a sabiendas» y con su porqué.';


--
-- Name: bank_movement; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_movement (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    treasury_account_id uuid NOT NULL,
    statement_id uuid NOT NULL,
    op_date date NOT NULL,
    value_date date NOT NULL,
    amount numeric(14,2) NOT NULL,
    bank_concept text DEFAULT ''::text NOT NULL,
    clean_concept text DEFAULT ''::text NOT NULL,
    common_code text,
    own_code text,
    document_no text,
    reference_1 text,
    reference_2 text,
    fx jsonb,
    fingerprint text NOT NULL,
    soft_fingerprint text NOT NULL,
    before_cutover boolean DEFAULT false NOT NULL,
    status text DEFAULT 'pendiente'::text NOT NULL,
    confidence text,
    reason text,
    proposal jsonb,
    ignored_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    card_id uuid,
    receipt_path text,
    receipt_at timestamp with time zone,
    counterparty text,
    movement_type text,
    CONSTRAINT bank_movement_common_code_check CHECK (((common_code IS NULL) OR (common_code ~ '^\d{2}$'::text))),
    CONSTRAINT bank_movement_confidence_check CHECK (((confidence IS NULL) OR (confidence = ANY (ARRAY['seguro'::text, 'probable'::text, 'duda'::text])))),
    CONSTRAINT bank_movement_ignorado_con_porque CHECK (((status = 'ignorado'::text) = (ignored_reason IS NOT NULL))),
    CONSTRAINT bank_movement_propuesta_con_porque CHECK (((status <> ALL (ARRAY['propuesto'::text, 'por_aclarar'::text])) OR ((reason IS NOT NULL) AND (length(TRIM(BOTH FROM reason)) > 0)))),
    CONSTRAINT bank_movement_status_check CHECK ((status = ANY (ARRAY['pendiente'::text, 'propuesto'::text, 'por_aclarar'::text, 'casado'::text, 'posible_repetido'::text, 'antes_corte_sin_pareja'::text, 'ignorado'::text, 'espera_extracto'::text])))
);


--
-- Name: TABLE bank_movement; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_movement IS 'B01. Un movimiento del banco. Huella única por cuenta (fecha, importe, referencias y orden en el día). posible_repetido: misma fecha, importe y orden que uno traído por otro camino; lo decide la persona. antes_corte_sin_pareja: anterior a la fecha de corte y sin pareja en el libro traído, solo informativo (P4). RGPD: datos de terceros, solo en producción.';


--
-- Name: COLUMN bank_movement.receipt_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_movement.receipt_path IS 'B01. El ticket (foto o PDF) de un pago con tarjeta, en el bucket banco-tickets: <cuenta>/<movimiento>/<huella>.<ext>.';


--
-- Name: COLUMN bank_movement.counterparty; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_movement.counterparty IS 'B02. A quién pagas o quién te paga, limpio (sin tarjeta, asteriscos ni códigos). El texto del banco, en bank_concept.';


--
-- Name: COLUMN bank_movement.movement_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_movement.movement_type IS 'B02. El tipo de movimiento del banco (Norma 43: descripción del concepto común o etiqueta del propio; BBVA Excel: CONCEPTO), aparte del concepto.';


--
-- Name: bank_rule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_rule (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    words text NOT NULL,
    condition jsonb NOT NULL,
    target jsonb NOT NULL,
    origin text NOT NULL,
    status text NOT NULL,
    confirmations integer DEFAULT 0 NOT NULL,
    last_used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    corrections integer,
    CONSTRAINT bank_rule_condicion CHECK (((jsonb_typeof(condition) = 'object'::text) AND (condition ? 'contiene'::text))),
    CONSTRAINT bank_rule_confirmations_check CHECK ((confirmations >= 0)),
    CONSTRAINT bank_rule_destino CHECK (((jsonb_typeof(target) = 'object'::text) AND (target ? 'cuenta'::text))),
    CONSTRAINT bank_rule_origin_check CHECK ((origin = ANY (ARRAY['persona'::text, 'folvy'::text]))),
    CONSTRAINT bank_rule_status_check CHECK ((status = ANY (ARRAY['propuesta'::text, 'activa'::text, 'apagada'::text, 'rechazada'::text]))),
    CONSTRAINT bank_rule_words_check CHECK ((length(TRIM(BOTH FROM words)) > 0))
);


--
-- Name: TABLE bank_rule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_rule IS 'B01. Una regla en palabras («Cuando el concepto tenga "PLENITUDE" → Luz y agua · 62800000»). condition: {contiene, signo?, importe?}; target: {cuenta, tercero_id?}. Las que propone Folvy nacen «propuesta» («Regla nueva, ¿la guardo?»); ninguna cambia sin su registro (bank_rule_log).';


--
-- Name: COLUMN bank_rule.corrections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bank_rule.corrections IS 'B01 (respuesta 4). Veces que la persona casó con otra cosa lo que proponía esta regla. A la segunda, la regla se apaga sola.';


--
-- Name: bank_rule_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_rule_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    action text NOT NULL,
    before jsonb,
    after jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    CONSTRAINT bank_rule_log_action_check CHECK ((action = ANY (ARRAY['creada'::text, 'propuesta'::text, 'aceptada'::text, 'rechazada'::text, 'apagada'::text, 'encendida'::text, 'cambiada'::text, 'usada'::text])))
);


--
-- Name: bank_statement; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_statement (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    treasury_account_id uuid NOT NULL,
    source text NOT NULL,
    format text NOT NULL,
    file_name text,
    file_sha256 text,
    period_from date NOT NULL,
    period_to date NOT NULL,
    opening_balance numeric(14,2),
    closing_balance numeric(14,2),
    movements_count integer NOT NULL,
    new_count integer NOT NULL,
    repeated_count integer NOT NULL,
    possible_repeated_count integer DEFAULT 0 NOT NULL,
    balanced boolean,
    unchecked_reason text,
    continuity text NOT NULL,
    continuity_gap numeric(14,2),
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    imported_by uuid,
    imported_by_name text,
    CONSTRAINT bank_statement_continuity_check CHECK ((continuity = ANY (ARRAY['primero'::text, 'sigue'::text, 'hueco'::text, 'sin_saldo'::text]))),
    CONSTRAINT bank_statement_cuadra CHECK ((balanced IS DISTINCT FROM false)),
    CONSTRAINT bank_statement_file_sha256_check CHECK (((file_sha256 IS NULL) OR (file_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT bank_statement_hueco CHECK (((continuity = 'hueco'::text) = (continuity_gap IS NOT NULL))),
    CONSTRAINT bank_statement_movements_count_check CHECK ((movements_count >= 0)),
    CONSTRAINT bank_statement_new_count_check CHECK ((new_count >= 0)),
    CONSTRAINT bank_statement_periodo CHECK ((period_from <= period_to)),
    CONSTRAINT bank_statement_possible_repeated_count_check CHECK ((possible_repeated_count >= 0)),
    CONSTRAINT bank_statement_repeated_count_check CHECK ((repeated_count >= 0)),
    CONSTRAINT bank_statement_saldos CHECK (((opening_balance IS NULL) = (closing_balance IS NULL))),
    CONSTRAINT bank_statement_sin_saldo CHECK ((((opening_balance IS NULL) = (continuity = 'sin_saldo'::text)) AND ((opening_balance IS NULL) = (balanced IS NULL)) AND ((balanced IS NULL) = (unchecked_reason IS NOT NULL)))),
    CONSTRAINT bank_statement_source_check CHECK (((source = ANY (ARRAY['fichero'::text, 'correo'::text])) OR (source ~ '^agregador:[a-z0-9-]+$'::text)))
);


--
-- Name: TABLE bank_statement; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bank_statement IS 'B01. Un extracto importado de una cuenta. Solo entra si cuadra (saldo inicial + movimientos = saldo final, y en Norma 43 el registro 33); el mismo fichero dos veces para la misma cuenta no entra. continuity: primero / sigue (empieza donde acabó el anterior) / hueco (no: continuity_gap dice cuánto) / sin_saldo (Excel sin saldos: unchecked_reason dice por qué no se comprobó).';


--
-- Name: billing_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    stripe_event_id text,
    processed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: billing_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    included_submodules uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    base_price_eur numeric(10,2) DEFAULT 0 NOT NULL,
    per_location_price numeric(10,2) DEFAULT 0 NOT NULL,
    max_locations integer DEFAULT 0 NOT NULL,
    max_employees integer DEFAULT 0 NOT NULL,
    trial_days integer DEFAULT 14 NOT NULL,
    billing_cycle text DEFAULT 'monthly'::text NOT NULL,
    stripe_price_id text,
    status text DEFAULT 'active'::text NOT NULL,
    sort_order integer DEFAULT 100,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_plans_billing_cycle_check CHECK ((billing_cycle = ANY (ARRAY['monthly'::text, 'annual'::text]))),
    CONSTRAINT billing_plans_status_check CHECK ((status = ANY (ARRAY['active'::text, 'hidden'::text, 'legacy'::text])))
);


--
-- Name: COLUMN billing_plans.max_locations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.billing_plans.max_locations IS '0 = ilimitado';


--
-- Name: COLUMN billing_plans.max_employees; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.billing_plans.max_employees IS '0 = ilimitado';


--
-- Name: brand; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.brand (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    ownership_type text DEFAULT 'own'::text NOT NULL,
    color text,
    logo_url text,
    notes text,
    is_active boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    shop_url text,
    qr_caption text,
    catalog_source text DEFAULT 'folvy'::text NOT NULL,
    cuisine_code text,
    closure_mode text DEFAULT 'normal'::text NOT NULL,
    closure_resume_at timestamp with time zone,
    closure_reason text,
    closure_set_at timestamp with time zone,
    closure_set_by uuid,
    CONSTRAINT brand_catalog_source_chk CHECK ((catalog_source = ANY (ARRAY['folvy'::text, 'pos'::text]))),
    CONSTRAINT brand_closure_mode_check CHECK ((closure_mode = ANY (ARRAY['normal'::text, 'paused'::text]))),
    CONSTRAINT brand_ownership_type_check CHECK ((ownership_type = ANY (ARRAY['own'::text, 'licensed'::text])))
);


--
-- Name: TABLE brand; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.brand IS 'Marcas comerciales operadas por la cuenta. Scope cuenta (compartido entre locales). Las marcas varían en el tiempo: usar is_active/archived_at para preservar histórico de ventas.';


--
-- Name: COLUMN brand.shop_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.shop_url IS 'URL de la tienda propia (Folvy Shop) de esta marca. La consume el QR del ticket de bolsa. NULL = sin tienda, no se pinta QR.';


--
-- Name: COLUMN brand.qr_caption; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.qr_caption IS 'Texto libre que acompaña al QR en el ticket (configurable por el cliente). Si NULL, se usa un texto por defecto.';


--
-- Name: COLUMN brand.catalog_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.catalog_source IS 'Quién manda la carta: folvy=Folvy publica a las plataformas; pos=el TPV/cedente manda y Folvy espeja. El publicador solo actúa sobre folvy.';


--
-- Name: COLUMN brand.closure_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.closure_mode IS 'OBSOLETA desde 01/09/2026: el cierre es POR LOCAL y vive en brand_closure. Ya no la escribe nadie. BORRAR en una segunda pasada (ver disparador abajo).';


--
-- Name: COLUMN brand.closure_resume_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.closure_resume_at IS 'OBSOLETA desde 01/09/2026: ver brand_closure.resume_at.';


--
-- Name: COLUMN brand.closure_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.closure_reason IS 'OBSOLETA desde 01/09/2026: ver brand_closure.reason.';


--
-- Name: COLUMN brand.closure_set_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.closure_set_at IS 'OBSOLETA desde 01/09/2026: ver brand_closure.set_at.';


--
-- Name: COLUMN brand.closure_set_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand.closure_set_by IS 'OBSOLETA desde 01/09/2026: ver brand_closure.set_by.';


