);


--
-- Name: COLUMN brand_channel_rate.location_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand_channel_rate.location_id IS 'Override de tarifa para un local concreto. NULL = aplica a todos los locales de la marca en ese canal. Resolucion: (marca+local) > (marca, local NULL) > channel_rate defecto del canal.';


--
-- Name: brand_channel_target; Type: TABLE; Schema: public; Owner: -
