);


--
-- Name: brand_licensing_agreement; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.brand_licensing_agreement (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    brand_id uuid NOT NULL,
    owner_name text NOT NULL,
    revenue_share_pct numeric,
    reimburses_consumption boolean DEFAULT true NOT NULL,
    starts_on date,
    ends_on date,
    notes text,
    is_active boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    party_id uuid,
    commission_base text DEFAULT 'brand_sales'::text NOT NULL,
    CONSTRAINT bla_commission_base_check CHECK ((commission_base = 'brand_sales'::text)),
    CONSTRAINT bla_dates_order CHECK (((ends_on IS NULL) OR (starts_on IS NULL) OR (ends_on >= starts_on))),
    CONSTRAINT bla_revenue_share_range CHECK (((revenue_share_pct >= (0)::numeric) AND (revenue_share_pct <= (100)::numeric)))
);


--
-- Name: COLUMN brand_licensing_agreement.party_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand_licensing_agreement.party_id IS 'C03. El socio de marca (party con papel brand_partner). Sustituye a owner_name cuando la revisión lo enlaza.';


--
-- Name: COLUMN brand_licensing_agreement.commission_base; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.brand_licensing_agreement.commission_base IS 'C03. Sobre qué se calcula revenue_share_pct: brand_sales = ventas sin IVA de sus marcas en el local y el periodo.';


