    CONSTRAINT company_activity_kind_check CHECK ((kind = ANY (ARRAY['business'::text, 'professional'::text, 'other'::text])))
);


--
-- Name: TABLE company_activity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_activity IS 'C00. Actividades: epígrafe del IAE y CNAE. Una y solo una principal entre las vigentes.';


--
-- Name: company_chart_import; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_chart_import (
