    decision text DEFAULT 'no_facturas'::text NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_name text,
    doc_kind text,
    CONSTRAINT company_inbound_sender_decision_check CHECK ((decision = ANY (ARRAY['no_facturas'::text, 'tipo'::text]))),
    CONSTRAINT company_inbound_sender_doc_kind_check CHECK (((doc_kind IS NULL) OR (doc_kind = ANY (ARRAY['factura'::text, 'ticket'::text, 'liquidacion'::text, 'extracto'::text, 'nomina'::text, 'riders'::text, 'otro'::text])))),
    CONSTRAINT company_inbound_sender_reason_check CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT company_inbound_sender_sender_sha256_check CHECK ((sender_sha256 ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE company_inbound_sender; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_inbound_sender IS 'D01 · Remitentes cuyos correos, aunque lleguen a la dirección de facturas de la empresa, no son facturas (p. ej. los justificantes de entrega de un proveedor). La dirección, por su huella: sha256 de la dirección en minúsculas. Solo el servidor.';


--
-- Name: company_lease; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_lease (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    supplier_id uuid NOT NULL,
    situation text NOT NULL,
    cadastral_ref text,
    street_type text,
    street_name text NOT NULL,
    number_type text,
    street_number text,
    number_qualifier text,
    block text,
    portal text,
    stair text,
    floor text,
    door text,
    complement text,
    locality text,
    municipality text NOT NULL,
    municipality_code text,
    province text NOT NULL,
    postal_code text NOT NULL,
    updated_by uuid,
    updated_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT company_lease_cadastral_ref_check CHECK ((cadastral_ref ~ '^[0-9A-Z]{20}$'::text)),
    CONSTRAINT company_lease_check CHECK (((situation = '4'::text) = (cadastral_ref IS NULL))),
    CONSTRAINT company_lease_municipality_check CHECK ((btrim(municipality) <> ''::text)),
    CONSTRAINT company_lease_municipality_code_check CHECK ((municipality_code ~ '^[0-9]{5}$'::text)),
    CONSTRAINT company_lease_number_type_check CHECK ((number_type = ANY (ARRAY['NUM'::text, 'KM.'::text, 'S/N'::text]))),
    CONSTRAINT company_lease_postal_code_check CHECK ((postal_code ~ '^[0-9]{5}$'::text)),
    CONSTRAINT company_lease_province_check CHECK ((province ~ '^(0[1-9]|[1-4][0-9]|5[0-3])$'::text)),
    CONSTRAINT company_lease_situation_check CHECK ((situation = ANY (ARRAY['1'::text, '2'::text, '3'::text, '4'::text]))),
    CONSTRAINT company_lease_street_name_check CHECK ((btrim(street_name) <> ''::text))
);


--
-- Name: TABLE company_lease; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_lease IS 'S02. El inmueble arrendado de cada arrendador (su ficha de proveedor), con lo que pide el registro de perceptor del 180 (anexo VI): situación, referencia catastral y dirección. Se escribe con conta_impuesto_180_inmueble_poner.';


--
-- Name: company_person; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_person (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
