    created_by uuid,
    signs_accounts boolean DEFAULT false NOT NULL,
    CONSTRAINT company_person_fechas CHECK (((ended_on IS NULL) OR (started_on IS NULL) OR (ended_on >= started_on))),
    CONSTRAINT company_person_full_name_check CHECK ((length(TRIM(BOTH FROM full_name)) > 0)),
    CONSTRAINT company_person_ownership_pct_check CHECK (((ownership_pct IS NULL) OR ((ownership_pct >= (0)::numeric) AND (ownership_pct <= (100)::numeric)))),
    CONSTRAINT company_person_roles_check CHECK ((roles <@ ARRAY['partner'::text, 'administrator'::text, 'representative'::text, 'secretary'::text, 'president'::text, 'filer'::text]))
);


--
-- Name: TABLE company_person; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_person IS 'C00. Socios y cargos. Solo los ven y los tocan los administradores de la cuenta.';


--
-- Name: COLUMN company_person.signs_accounts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.company_person.signs_accounts IS 'Firma las cuentas anuales (depósito en el Registro Mercantil).';


--
-- Name: company_purchase_setting; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_purchase_setting (
    company_id uuid NOT NULL,
    account_id uuid NOT NULL,
    receives_goods boolean NOT NULL,
