    updated_by uuid,
    updated_by_name text
);


--
-- Name: TABLE company_purchase_setting; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_purchase_setting IS 'D01 · Ajustes de compras de una empresa: «Recibe la mercancía con Folvy» (casado con Cocina y «De Cocina» en la bandeja) y «apuntar solo lo seguro». Valor inicial por el dato; después solo lo cambia una persona.';


--
-- Name: company_relation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_relation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    related_company_id uuid,
    third_party_name text,
    third_party_tax_id text,
    kind text NOT NULL,
    from_on date,
    to_on date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    related_is_parent boolean DEFAULT false NOT NULL,
    CONSTRAINT company_relation_con_quien CHECK (((related_company_id IS NOT NULL) OR (third_party_name IS NOT NULL))),
    CONSTRAINT company_relation_dominante_es_grupo CHECK (((NOT related_is_parent) OR (kind = 'group'::text))),
    CONSTRAINT company_relation_kind_check CHECK ((kind = ANY (ARRAY['group'::text, 'joint'::text, 'associate'::text, 'other_related'::text]))),
    CONSTRAINT company_relation_no_consigo CHECK ((related_company_id IS DISTINCT FROM company_id))
);


--
-- Name: TABLE company_relation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_relation IS 'C00. Relación con otra empresa de la cuenta o con un tercero: grupo, multigrupo, asociada u otra vinculada. Solo se guarda; nada la usa todavía.';


--
-- Name: COLUMN company_relation.related_is_parent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.company_relation.related_is_parent IS 'La otra es la entidad dominante del grupo (modelo 200).';


--
-- Name: company_tax_facts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_tax_facts (
    company_id uuid NOT NULL,
    account_id uuid NOT NULL,
    fact text NOT NULL,
    value jsonb,
    origin text NOT NULL,
    said_by uuid,
    said_by_name text,
    said_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT company_tax_facts_check CHECK (((value IS NULL) OR ((fact = 'previous_year_turnover'::text) AND (jsonb_typeof(value) = 'number'::text)) OR ((fact <> 'previous_year_turnover'::text) AND (jsonb_typeof(value) = 'boolean'::text)))),
    CONSTRAINT company_tax_facts_fact_check CHECK ((fact = ANY (ARRAY['pays_with_withholding'::text, 'has_employees'::text, 'pays_professionals'::text, 'rents_premises_with_withholding'::text, 'roi_registered'::text, 'previous_year_turnover'::text, 'redeme'::text, 'withheld_income_70'::text]))),
    CONSTRAINT company_tax_facts_origin_check CHECK ((origin = ANY (ARRAY['alta'::text, 'ajustes'::text, 'asesoria'::text, 'datos'::text])))
);


--
-- Name: TABLE company_tax_facts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_tax_facts IS 'I01a. Datos de la empresa que deciden sus modelos (informe §4 y §7.1), cada uno con quién y cuándo lo dijo. value null = «No lo sé». pays_with_withholding: la pregunta del alta «¿Pagas nóminas o facturas de profesionales con retención?» (junta has_employees y pays_professionals, que quedan para cuando se pregunten por separado). withheld_income_70: autónomo profesional con al menos el 70 % de sus ingresos retenidos.';


--
-- Name: tax_obligation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_obligation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    form_code text NOT NULL,
    cadence text NOT NULL,
    active boolean NOT NULL,
    origin text NOT NULL,
    rule_key text,
    rule_facts jsonb DEFAULT '{}'::jsonb NOT NULL,
    why text NOT NULL,
    reason text,
    payment_mode text DEFAULT 'none'::text NOT NULL,
    payment_treasury_account_id uuid,
    valid_from date DEFAULT CURRENT_DATE NOT NULL,
    valid_to date,
    decided_by uuid,
    decided_by_name text,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tax_obligation_cadence_check CHECK ((cadence = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'annual'::text, 'instalments_202'::text]))),
    CONSTRAINT tax_obligation_check CHECK (((origin <> 'rule'::text) OR (rule_key IS NOT NULL))),
    CONSTRAINT tax_obligation_check1 CHECK (((origin = 'rule'::text) OR ((reason IS NOT NULL) AND (btrim(reason) <> ''::text)))),
    CONSTRAINT tax_obligation_check2 CHECK (((origin <> 'removed'::text) OR (NOT active))),
    CONSTRAINT tax_obligation_check3 CHECK (((origin <> 'added'::text) OR active)),
    CONSTRAINT tax_obligation_check4 CHECK (((valid_to IS NULL) OR (valid_to >= valid_from))),
    CONSTRAINT tax_obligation_check5 CHECK (((payment_mode <> 'direct_debit'::text) OR (payment_treasury_account_id IS NOT NULL))),
    CONSTRAINT tax_obligation_origin_check CHECK ((origin = ANY (ARRAY['rule'::text, 'added'::text, 'removed'::text]))),
    CONSTRAINT tax_obligation_payment_mode_check CHECK ((payment_mode = ANY (ARRAY['direct_debit'::text, 'nrc'::text, 'none'::text]))),
    CONSTRAINT tax_obligation_why_check CHECK ((btrim(why) <> ''::text))
);


--
-- Name: TABLE tax_obligation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_obligation IS 'I01a. Qué modelos presenta la empresa y por qué. why: el porqué en palabras de oficina («Tienes 6 personas en nómina»); rule_key y rule_facts: la regla y los datos (origin rule); reason: el motivo de quien lo añadió o quitó (obligatorio). La vigente: valid_to null.';


--
-- Name: company_tax_forms; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_tax_forms WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.account_id,
    COALESCE(array_agg(o.form_code ORDER BY o.form_code) FILTER (WHERE (o.id IS NOT NULL)), '{}'::text[]) AS tax_forms
   FROM (public.company c
     LEFT JOIN public.tax_obligation o ON (((o.company_id = c.id) AND (o.valid_to IS NULL) AND o.active)))
  GROUP BY c.id, c.account_id;


--
-- Name: VIEW company_tax_forms; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.company_tax_forms IS 'I01a. Los modelos que presenta cada empresa, desde tax_obligation. Sustituye a company_tax_profile.tax_forms, que queda como espejo hasta quitarla (dos pasos, I01b).';


--
-- Name: company_tax_presenter; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_tax_presenter (
    company_id uuid NOT NULL,
    account_id uuid NOT NULL,
    mode text DEFAULT 'company'::text NOT NULL,
    certificate_id uuid,
    advisor_account_id uuid,
    advisor_basis text,
    consented_by uuid,
    consented_by_name text,
    consented_at timestamp with time zone,
    revoked_by uuid,
    revoked_at timestamp with time zone,
    since date DEFAULT CURRENT_DATE NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT company_tax_presenter_advisor_basis_check CHECK ((advisor_basis = ANY (ARRAY['social_collaborator'::text, 'power_of_attorney'::text]))),
    CONSTRAINT company_tax_presenter_check CHECK (((mode = 'company'::text) OR ((advisor_account_id IS NOT NULL) AND (advisor_basis IS NOT NULL) AND (advisor_account_id <> account_id)))),
    CONSTRAINT company_tax_presenter_check1 CHECK (((mode = 'advisor'::text) OR ((advisor_account_id IS NULL) AND (advisor_basis IS NULL)))),
    CONSTRAINT company_tax_presenter_check2 CHECK (((consented_at IS NULL) = (consented_by IS NULL))),
    CONSTRAINT company_tax_presenter_check3 CHECK (((revoked_at IS NULL) OR (consented_at IS NOT NULL))),
    CONSTRAINT company_tax_presenter_mode_check CHECK ((mode = ANY (ARRAY['company'::text, 'advisor'::text])))
);


--
-- Name: TABLE company_tax_presenter; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_tax_presenter IS 'I01a. Quién presenta los impuestos de la empresa: ella misma o su asesoría (colaboradora social o con poder). La asesoría solo accede con el consentimiento de la empresa (consented_*) vivo (sin revoked_at).';


--
-- Name: company_tax_profile; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_tax_profile (
    company_id uuid NOT NULL,
    account_id uuid NOT NULL,
    tax_territory text DEFAULT 'peninsula_baleares'::text NOT NULL,
    vat_scheme_code text,
    vat_cash_basis boolean DEFAULT false NOT NULL,
    vat_surcharge boolean DEFAULT false NOT NULL,
    vat_period text DEFAULT 'quarterly'::text NOT NULL,
    vat_prorata boolean DEFAULT false NOT NULL,
    vat_prorata_pct numeric(5,2),
    sii boolean DEFAULT false NOT NULL,
    chart_kind text DEFAULT 'pymes'::text NOT NULL,
    account_digits smallint DEFAULT 8 NOT NULL,
    tax_forms text[] DEFAULT '{}'::text[] NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    sales_tax_rate_code text,
    journal_autovalidate_sales_day boolean DEFAULT false NOT NULL,
    sales_day_close_time time without time zone DEFAULT '02:00:00'::time without time zone,
    CONSTRAINT company_tax_profile_account_digits_check CHECK (((account_digits >= 6) AND (account_digits <= 12))),
    CONSTRAINT company_tax_profile_chart_kind_check CHECK ((chart_kind = ANY (ARRAY['pymes'::text, 'normal'::text]))),
    CONSTRAINT company_tax_profile_tax_territory_check CHECK ((tax_territory = ANY (ARRAY['peninsula_baleares'::text, 'canarias'::text, 'ceuta_melilla'::text]))),
    CONSTRAINT company_tax_profile_vat_period_check CHECK ((vat_period = ANY (ARRAY['quarterly'::text, 'monthly'::text]))),
    CONSTRAINT company_tax_profile_vat_prorata_pct_check CHECK (((vat_prorata_pct IS NULL) OR ((vat_prorata_pct >= (0)::numeric) AND (vat_prorata_pct <= (100)::numeric))))
);


--
-- Name: TABLE company_tax_profile; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.company_tax_profile IS 'C00. Perfil fiscal de la empresa: territorio, régimen y periodicidad del IVA, plan contable y modelos que presenta.';


--
-- Name: COLUMN company_tax_profile.sales_tax_rate_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.company_tax_profile.sales_tax_rate_code IS 'El IVA de las ventas de la empresa (tax_rate.code de la fila de serie). Lo propone el alta por la actividad; respuesta 3 del C00.';


--
-- Name: COLUMN company_tax_profile.journal_autovalidate_sales_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.company_tax_profile.journal_autovalidate_sales_day IS 'C04. Regla 10: con esta opción (apagada por defecto), las propuestas «Seguro» de ventas del día se validan solas. Nada más se valida solo.';


--
-- Name: COLUMN company_tax_profile.sales_day_close_time; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.company_tax_profile.sales_day_close_time IS 'Cierre del día: a esta hora (de Madrid) se dan por terminadas las ventas del día anterior. Un pedido de marca propia que siga abierto se cierra como no confirmado. Vacío = 2:00.';


--
-- Name: compliance_document; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.compliance_document (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid,
    doc_family text NOT NULL,
    title text NOT NULL,
    supplier_id uuid,
    reference text,
    issued_at date,
    expires_at date,
    review_due_at date,
    file_path text NOT NULL,
    file_size_kb integer,
    mime_type text,
    status text DEFAULT 'pending_review'::text NOT NULL,
    supersedes_id uuid,
    extracted jsonb,
    notes text,
    last_reminder_at timestamp with time zone,
    uploaded_by uuid,
