--
-- Name: TABLE conta_cobro_remesa; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conta_cobro_remesa IS 'PC01 · E3 · Una remesa de recibos domiciliados a clientes (fichero SEPA pain.008, CORE). Su estado se calcula: conta_cobro_remesa_estado.';


--
-- Name: conta_cobro_remesa_linea; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conta_cobro_remesa_linea (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    remesa_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    party_id uuid,
    amount numeric(14,2) NOT NULL,
    iban text NOT NULL,
    mandate_ref text NOT NULL,
    mandate_date date NOT NULL,
    seq text NOT NULL,
    removed_at timestamp with time zone,
    removed_by_name text,
    bank_match_id uuid,
    returned_at timestamp with time zone,
    return_reason text,
    return_fee numeric(14,2),
    return_match_id uuid,
    returned_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT conta_cobro_remesa_linea_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT conta_cobro_remesa_linea_seq_check CHECK ((seq = ANY (ARRAY['FRST'::text, 'RCUR'::text])))
);


--
-- Name: TABLE conta_cobro_remesa_linea; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conta_cobro_remesa_linea IS 'PC01 · E3 · Lo que una remesa de recibos cobra a una factura emitida, con el IBAN y el mandato del cliente en ese momento. Cobrado mientras el casado de su abono (bank_match_id) esté vivo; devuelto mientras lo esté el de su devolución (return_match_id).';


--
-- Name: conta_cobro_remesa_linea_estado; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conta_cobro_remesa_linea_estado WITH (security_invoker='true') AS
 SELECT id,
    account_id,
    company_id,
    remesa_id,
    invoice_id,
    party_id,
    amount,
    iban,
    mandate_ref,
    mandate_date,
    seq,
    removed_at,
    removed_by_name,
    bank_match_id,
    returned_at,
    return_reason,
    return_fee,
    return_match_id,
    returned_by_name,
    created_at,
        CASE
            WHEN (removed_at IS NOT NULL) THEN 'sacada'::text
            WHEN ((return_match_id IS NOT NULL) AND (EXISTS ( SELECT 1
               FROM public.bank_match b
              WHERE ((b.id = l.return_match_id) AND (b.status = 'vivo'::text))))) THEN 'devuelto'::text
            WHEN ((bank_match_id IS NOT NULL) AND (EXISTS ( SELECT 1
               FROM public.bank_match b
              WHERE ((b.id = l.bank_match_id) AND (b.status = 'vivo'::text))))) THEN 'cobrado'::text
            ELSE 'pendiente'::text
        END AS estado,
    ( SELECT m.op_date
           FROM (public.bank_match b
             JOIN public.bank_movement m ON ((m.id = b.movement_id)))
          WHERE ((b.id = l.bank_match_id) AND (b.status = 'vivo'::text))) AS abonado_el,
    ( SELECT m.op_date
           FROM (public.bank_match b
             JOIN public.bank_movement m ON ((m.id = b.movement_id)))
          WHERE ((b.id = l.return_match_id) AND (b.status = 'vivo'::text))) AS devuelto_el
   FROM public.conta_cobro_remesa_linea l;


--
-- Name: VIEW conta_cobro_remesa_linea_estado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.conta_cobro_remesa_linea_estado IS 'PC01 · E3 · El estado de cada recibo de una remesa, calculado de sus casados del banco: pendiente, cobrado, devuelto o sacada.';


--
-- Name: conta_cobro_remesa_estado; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conta_cobro_remesa_estado WITH (security_invoker='true') AS
 WITH l AS (
         SELECT conta_cobro_remesa_linea_estado.remesa_id,
            count(*) FILTER (WHERE (conta_cobro_remesa_linea_estado.estado <> 'sacada'::text)) AS vivas,
            count(*) FILTER (WHERE (conta_cobro_remesa_linea_estado.estado = 'cobrado'::text)) AS cobrados,
            count(*) FILTER (WHERE (conta_cobro_remesa_linea_estado.estado = 'devuelto'::text)) AS devueltos,
            count(*) FILTER (WHERE (conta_cobro_remesa_linea_estado.estado = 'pendiente'::text)) AS pendientes,
            (COALESCE(sum(conta_cobro_remesa_linea_estado.amount) FILTER (WHERE (conta_cobro_remesa_linea_estado.estado <> 'sacada'::text)), (0)::numeric))::numeric(14,2) AS total,
            (COALESCE(sum(conta_cobro_remesa_linea_estado.amount) FILTER (WHERE (conta_cobro_remesa_linea_estado.estado = 'pendiente'::text)), (0)::numeric))::numeric(14,2) AS por_abonar,
            (COALESCE(sum(conta_cobro_remesa_linea_estado.amount) FILTER (WHERE (conta_cobro_remesa_linea_estado.estado = 'cobrado'::text)), (0)::numeric))::numeric(14,2) AS cobrado,
            max(conta_cobro_remesa_linea_estado.abonado_el) AS abonada_el
           FROM public.conta_cobro_remesa_linea_estado
          GROUP BY conta_cobro_remesa_linea_estado.remesa_id
        )
 SELECT r.id,
    r.account_id,
    r.company_id,
    r.code,
    r.treasury_account_id,
    r.charge_date,
    r.file_sha256,
    r.file_at,
    r.file_by,
    r.file_by_name,
    r.created_at,
    r.created_by,
    r.created_by_name,
    COALESCE(l.vivas, (0)::bigint) AS vivas,
    COALESCE(l.cobrados, (0)::bigint) AS cobrados,
    COALESCE(l.devueltos, (0)::bigint) AS devueltos,
    COALESCE(l.pendientes, (0)::bigint) AS pendientes,
    COALESCE(l.total, (0)::numeric) AS total,
    COALESCE(l.por_abonar, (0)::numeric) AS por_abonar,
    COALESCE(l.cobrado, (0)::numeric) AS cobrado,
    l.abonada_el,
    (l.abonada_el + 56) AS plazo_hasta,
        CASE
            WHEN (COALESCE(l.vivas, (0)::bigint) = 0) THEN 'vacia'::text
            WHEN (r.file_at IS NULL) THEN 'preparada'::text
            WHEN (l.pendientes > 0) THEN 'en_banco'::text
            WHEN ((l.abonada_el IS NOT NULL) AND (public.conta_hoy() <= (l.abonada_el + 56))) THEN 'plazo'::text
            ELSE 'cerrada'::text
        END AS estado
   FROM (public.conta_cobro_remesa r
     LEFT JOIN l ON ((l.remesa_id = r.id)));


--
-- Name: VIEW conta_cobro_remesa_estado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.conta_cobro_remesa_estado IS 'PC01 · E3 · El estado de cada remesa de recibos: preparada, en_banco, plazo (de devoluciones, 8 semanas desde el abono), cerrada o vacia.';


