    CONSTRAINT conta_eje_analitico_nombre_plural_check CHECK (((nombre_plural IS NULL) OR ((length(btrim(nombre_plural)) >= 1) AND (length(btrim(nombre_plural)) <= 40))))
);


--
-- Name: TABLE conta_eje_analitico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conta_eje_analitico IS 'S01 (17/10): los ejes de analítica de cada empresa (local → journal_line.location_id, marca → journal_line.brand_id). Sin fila = apagado: ni se pide ni se enseña, pero lo guardado se queda.';


--
