--
-- Name: customer_invoice; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_invoice (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    status text DEFAULT 'borrador'::text NOT NULL,
    doc_type text DEFAULT 'factura'::text NOT NULL,
    origin text DEFAULT 'a_mano'::text NOT NULL,
    series_code text DEFAULT 'F'::text NOT NULL,
    fiscal_year integer,
    number integer,
    number_text text,
    issue_date date DEFAULT ((now() AT TIME ZONE 'Europe/Madrid'::text))::date NOT NULL,
    due_date date,
    party_id uuid,
    customer jsonb DEFAULT '{}'::jsonb NOT NULL,
    location_id uuid,
    payment_method_id uuid,
    notes text,
    email_to text,
    withholding_rate_id uuid,
    surcharge boolean DEFAULT false NOT NULL,
    corrects_id uuid,
    correction_kind text,
    correction_reason text,
    base numeric(14,2) DEFAULT 0 NOT NULL,
    tax numeric(14,2) DEFAULT 0 NOT NULL,
    surcharge_amount numeric(14,2) DEFAULT 0 NOT NULL,
    withholding_amount numeric(14,2) DEFAULT 0 NOT NULL,
    total numeric(14,2) DEFAULT 0 NOT NULL,
    entry_id uuid,
    pdf_path text,
    pdf_sha256 text,
    pdf_bytes integer,
    sent_at timestamp with time zone,
    prev_hash text,
    hash text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    issued_at timestamp with time zone,
    issued_by_name text,
    CONSTRAINT customer_invoice_correction_kind_check CHECK ((correction_kind = ANY (ARRAY['importes'::text, 'anular'::text, 'datos'::text]))),
    CONSTRAINT customer_invoice_doc_type_check CHECK ((doc_type = ANY (ARRAY['factura'::text, 'rectificativa'::text]))),
    CONSTRAINT customer_invoice_numero_al_emitir CHECK (((status = 'borrador'::text) OR ((number IS NOT NULL) AND (number_text IS NOT NULL) AND (fiscal_year IS NOT NULL)))),
    CONSTRAINT customer_invoice_origin_check CHECK ((origin = ANY (ARRAY['a_mano'::text, 'recurrente'::text, 'presupuesto'::text, 'cierre_dia'::text, 'tienda'::text, 'automatica'::text]))),
    CONSTRAINT customer_invoice_pdf_sha256_check CHECK (((pdf_sha256 IS NULL) OR (pdf_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT customer_invoice_rectificativa CHECK (((doc_type = 'rectificativa'::text) = ((corrects_id IS NOT NULL) AND (correction_kind IS NOT NULL)))),
    CONSTRAINT customer_invoice_series_code_check CHECK ((series_code ~ '^[A-Z0-9][A-Z0-9-]{0,9}$'::text)),
    CONSTRAINT customer_invoice_status_check CHECK ((status = ANY (ARRAY['borrador'::text, 'emitida'::text, 'anulada'::text])))
);


