-- Name: TABLE customer_invoice_payment; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.customer_invoice_payment IS 'V01 · Lo cobrado de una factura (puede ser en partes). No hace asiento: el del cobro lo hace Bancos al casar el movimiento.';


--
-- Name: COLUMN customer_invoice_payment.entry_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_invoice_payment.entry_id IS 'V01 · El asiento del cobro en efectivo (570 / 430). Un cobro por banco no lo lleva: lo hace Bancos al casar el movimiento.';


--
-- Name: COLUMN customer_invoice_payment.bank_match_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_invoice_payment.bank_match_id IS 'PC01 · El casado del banco que cobró la factura (su asiento, entry_id, es el del banco). Se va al deshacer el casado.';


--
-- Name: COLUMN customer_invoice_payment.settlement_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_invoice_payment.settlement_id IS 'PC01 · La liquidación de plataforma que cobró los pedidos de esta factura. Se va al descobrar la liquidación. Su asiento es el de la liquidación.';


--
-- Name: conta_factura_cobro; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conta_factura_cobro WITH (security_invoker='true') AS
 WITH c AS (
         SELECT ci.id,
            ci.account_id,
            ci.company_id,
            ci.status,
            ci.total,
            ci.due_date,
            (COALESCE(( SELECT sum(p.amount) AS sum
                   FROM public.customer_invoice_payment p
                  WHERE (p.invoice_id = ci.id)), (0)::numeric))::numeric(14,2) AS cobrado,
            public.conta_factura_es_de_plataforma(ci.id) AS de_plataforma
           FROM public.customer_invoice ci
        )
 SELECT id AS invoice_id,
    account_id,
    company_id,
    total,
    cobrado,
    ((total - cobrado))::numeric(14,2) AS pendiente,
    due_date AS vence,
    de_plataforma,
        CASE
            WHEN (status = 'borrador'::text) THEN 'borrador'::text
            WHEN (status = 'anulada'::text) THEN 'anulada'::text
            WHEN (total < (0)::numeric) THEN
            CASE
                WHEN (abs((total - cobrado)) < 0.005) THEN 'cobrada'::text
                ELSE 'emitida'::text
            END
            WHEN (total = (0)::numeric) THEN 'emitida'::text
            WHEN ((total - cobrado) < 0.005) THEN 'cobrada'::text
            WHEN ((due_date IS NOT NULL) AND (due_date < public.conta_hoy())) THEN
            CASE
                WHEN (de_plataforma AND (NOT public.conta_factura_tiene_liquidacion(id))) THEN 'falta_liquidacion'::text
                ELSE 'vencida'::text
            END
            WHEN (cobrado > (0)::numeric) THEN 'cobrada_parte'::text
            WHEN de_plataforma THEN 'esperando_liquidacion'::text
            WHEN ((due_date IS NOT NULL) AND (due_date <= (public.conta_hoy() + 7))) THEN 'vence_semana'::text
            ELSE 'por_cobrar'::text
        END AS estado,
        CASE
            WHEN ((due_date IS NOT NULL) AND (due_date < public.conta_hoy()) AND ((total - cobrado) >= 0.005) AND (status = 'emitida'::text)) THEN (public.conta_hoy() - due_date)
            ELSE NULL::integer
        END AS dias_vencida
   FROM c;


--
-- Name: VIEW conta_factura_cobro; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.conta_factura_cobro IS 'PC01 · El estado de cobro de cada factura emitida, calculado en un solo sitio. Lo leen todas las pantallas.';


