    file_at timestamp with time zone,
    file_by uuid,
    file_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    validated_solo_at timestamp with time zone,
    validated_solo_entry uuid,
    CONSTRAINT conta_pago_remesa_kind_check CHECK ((kind = ANY (ARRAY['fichero'::text, 'a_mano'::text, 'banco'::text])))
);


--
-- Name: TABLE conta_pago_remesa; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conta_pago_remesa IS 'PC01 · E2 · Una remesa de transferencias a proveedores (fichero SEPA pain.001) o un pago a mano de una factura suelta (kind a_mano, sin fichero). Su estado se calcula: conta_pago_remesa_estado.';


--
-- Name: COLUMN conta_pago_remesa.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conta_pago_remesa.kind IS 'PC01 · E2 · fichero: remesa SEPA que se descarga · a_mano: «Ya la he pagado» · banco (B01 Revolut · PR 2b): mandada por la API del banco desde Sumied.';


--
-- Name: conta_pago_remesa_estado; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conta_pago_remesa_estado WITH (security_invoker='true') AS
 WITH l AS (
         SELECT conta_pago_remesa_linea_estado.remesa_id,
            count(*) FILTER (WHERE (conta_pago_remesa_linea_estado.estado <> ALL (ARRAY['sacada'::text, 'rechazada'::text]))) AS vivas,
            count(*) FILTER (WHERE (conta_pago_remesa_linea_estado.estado = 'pagada'::text)) AS pagadas,
            count(*) FILTER (WHERE (conta_pago_remesa_linea_estado.estado = 'por_confirmar'::text)) AS por_confirmar,
            count(*) FILTER (WHERE (conta_pago_remesa_linea_estado.estado = 'rechazada'::text)) AS rechazadas,
            (COALESCE(sum(conta_pago_remesa_linea_estado.amount) FILTER (WHERE (conta_pago_remesa_linea_estado.estado <> ALL (ARRAY['sacada'::text, 'rechazada'::text]))), (0)::numeric))::numeric(14,2) AS total,
            (COALESCE(sum(conta_pago_remesa_linea_estado.amount) FILTER (WHERE (conta_pago_remesa_linea_estado.estado = ANY (ARRAY['pendiente'::text, 'por_confirmar'::text]))), (0)::numeric))::numeric(14,2) AS por_cargar
           FROM public.conta_pago_remesa_linea_estado
          GROUP BY conta_pago_remesa_linea_estado.remesa_id
        )
 SELECT r.id,
    r.account_id,
    r.company_id,
    r.code,
    r.kind,
    r.treasury_account_id,
    r.pay_date,
    r.file_sha256,
    r.file_at,
    r.file_by,
    r.file_by_name,
    r.created_at,
    r.created_by,
    r.created_by_name,
    r.validated_solo_at,
    r.validated_solo_entry,
    COALESCE(l.vivas, (0)::bigint) AS vivas,
    COALESCE(l.pagadas, (0)::bigint) AS pagadas,
    COALESCE(l.por_confirmar, (0)::bigint) AS por_confirmar,
    COALESCE(l.rechazadas, (0)::bigint) AS rechazadas,
    COALESCE(l.total, (0)::numeric) AS total,
    COALESCE(l.por_cargar, (0)::numeric) AS por_cargar,
        CASE
            WHEN (COALESCE(l.vivas, (0)::bigint) = 0) THEN 'vacia'::text
            WHEN (l.pagadas = l.vivas) THEN 'pagada'::text
            WHEN ((r.kind = ANY (ARRAY['a_mano'::text, 'banco'::text])) OR (r.file_at IS NOT NULL)) THEN 'en_banco'::text
            WHEN (l.por_confirmar > 0) THEN 'preparada'::text
            ELSE 'fichero'::text
        END AS estado
   FROM (public.conta_pago_remesa r
     LEFT JOIN l ON ((l.remesa_id = r.id)));


--
-- Name: VIEW conta_pago_remesa_estado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.conta_pago_remesa_estado IS 'PC01 · E2 · El estado de cada remesa de pagos, calculado de sus líneas: preparada, fichero, en_banco, pagada o vacia. B01 · 2b: la del banco, en_banco desde que se manda.';


