);


--
-- Name: TABLE conta_programa_anterior_registro; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conta_programa_anterior_registro IS 'C06 · Registro de conta_programa_anterior: cada respuesta y cada cambio, con quién y cuándo. Lo escribe su disparador.';


