--
-- Name: supplier_invoice; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    supplier_id uuid,
    location_id uuid,
    code text,
    doc_kind text DEFAULT 'invoice'::text NOT NULL,
    invoice_number text,
    invoice_date date,
    status text DEFAULT 'borrador'::text NOT NULL,
    match_status text DEFAULT 'sin_match'::text NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    ai_session_id uuid,
    raw_document_url text,
    tax_base_total numeric,
    tax_total numeric,
    grand_total numeric,
    corrects_invoice_id uuid,
    notes text,
    needs_review boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    approved_at timestamp with time zone,
    approved_by uuid,
    approved_by_name text,
    due_date date,
    due_date_set_by uuid,
    due_date_set_name text,
    due_date_set_at timestamp with time zone,
    paid_at date,
    paid_method text,
    paid_by uuid,
    paid_by_name text,
    not_duplicate_confirmed_at timestamp with time zone,
    not_duplicate_confirmed_by uuid,
    not_duplicate_confirmed_by_name text,
    read_iban text,
    iban_decision text,
    iban_decision_at timestamp with time zone,
    iban_decision_by uuid,
    iban_decision_by_name text,
    journal_entry_id uuid,
    payment_entry_id uuid,
    withholding_rate_id uuid,
    withholding_amount numeric(14,2),
    company_id uuid,
    vat_non_deductible boolean DEFAULT false NOT NULL,
    arrival_channel text,
    number_key text GENERATED ALWAYS AS (NULLIF(
CASE
    WHEN (upper(regexp_replace(COALESCE(invoice_number, ''::text), '[^A-Za-z0-9]'::text, ''::text, 'g'::text)) ~ '^(SN|SINNUMERO|SINNUM|0+)$'::text) THEN ''::text
    ELSE upper(regexp_replace(COALESCE(invoice_number, ''::text), '[^A-Za-z0-9]'::text, ''::text, 'g'::text))
END, ''::text)) STORED,
    reading_confidence text,
    reading jsonb,
    surcharge_total numeric(14,2),
    inbox_id uuid,
    issuer_name text,
    issuer_tax_id text,
    issuer_address text,
    batch_id uuid,
    brand_id uuid,
    discarded_at timestamp with time zone,
    discarded_by uuid,
    discarded_by_name text,
    discard_reason text,
    status_before_discard text,
    payment_method text,
    no_document_at timestamp with time zone,
    no_document_reason text,
    no_document_by_name text,
    entry_overrides jsonb,
    withholding_base numeric(14,2),
    vat_non_deductible_reason text,
    vat_non_deductible_note text,
    CONSTRAINT supplier_invoice_arrival_channel_check CHECK ((arrival_channel = ANY (ARRAY['subida'::text, 'correo'::text, 'cocina'::text, 'portal'::text]))),
    CONSTRAINT supplier_invoice_descartada_con_motivo CHECK (((status = 'descartada'::text) = ((discarded_at IS NOT NULL) AND (length(TRIM(BOTH FROM COALESCE(discard_reason, ''::text))) > 0) AND (status_before_discard IS NOT NULL)))),
    CONSTRAINT supplier_invoice_doc_kind_check CHECK ((doc_kind = ANY (ARRAY['invoice'::text, 'credit_note'::text]))),
    CONSTRAINT supplier_invoice_iban_decision_check CHECK (((iban_decision IS NULL) OR (iban_decision = ANY (ARRAY['es_el_nuevo'::text, 'no_es_suyo'::text])))),
    CONSTRAINT supplier_invoice_match_status_check CHECK ((match_status = ANY (ARRAY['sin_match'::text, 'ok'::text, 'con_diferencias'::text]))),
    CONSTRAINT supplier_invoice_pagada_con_fecha CHECK (((paid_at IS NULL) OR (status = 'pagada'::text))),
    CONSTRAINT supplier_invoice_paid_method_check CHECK (((paid_method IS NULL) OR (paid_method = ANY (ARRAY['transfer'::text, 'direct_debit'::text, 'card'::text, 'cash'::text, 'prepaid'::text, 'compensation'::text])))),
    CONSTRAINT supplier_invoice_payment_method_check CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['transfer'::text, 'direct_debit'::text, 'card'::text, 'cash'::text, 'prepaid'::text, 'compensation'::text])))),
    CONSTRAINT supplier_invoice_read_iban_format_check CHECK (((read_iban IS NULL) OR (read_iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$'::text))),
    CONSTRAINT supplier_invoice_reading_confidence_check CHECK ((reading_confidence = ANY (ARRAY['seguro'::text, 'probable'::text, 'duda'::text]))),
    CONSTRAINT supplier_invoice_retencion_completa CHECK ((((withholding_rate_id IS NULL) = (withholding_amount IS NULL)) AND ((withholding_amount IS NULL) OR (withholding_amount >= (0)::numeric)))),
    CONSTRAINT supplier_invoice_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'ocr'::text, 'lote'::text, 'liquidacion'::text]))),
    CONSTRAINT supplier_invoice_status_check CHECK ((status = ANY (ARRAY['borrador'::text, 'en_revision'::text, 'aprobada'::text, 'con_discrepancias'::text, 'pagada'::text, 'anulada'::text, 'descartada'::text]))),
    CONSTRAINT supplier_invoice_vat_non_deductible_reason_check CHECK (((vat_non_deductible_reason IS NULL) OR (vat_non_deductible_reason = ANY (ARRAY['no_a_nombre'::text, 'ticket_sin_nif'::text, 'otro'::text]))))
);


--
-- Name: COLUMN supplier_invoice.due_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoice.due_date IS 'C01. Vencimiento. Al aprobar se calcula con las condiciones del proveedor (plazo + días fijos). Si se cambia a mano, due_date_set_* dice quién y cuándo.';


--
-- Name: COLUMN supplier_invoice.paid_at; Type: COMMENT; Schema: public; Owner: -
--

