COMMENT ON TABLE public.supplier_invoice_payment IS 'PC01 · Lo pagado de una factura recibida (puede ser en partes), con su asiento. Gemela de customer_invoice_payment. La escribe Bancos al casar (disparador de bank_match_item) y la quita al deshacer.';


--
-- Name: conta_recibida_pago; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conta_recibida_pago WITH (security_invoker='true') AS
 WITH p AS (
         SELECT si.id,
            si.account_id,
            si.company_id,
            si.status,
            COALESCE(si.grand_total, (0)::numeric) AS total,
            si.due_date,
            (COALESCE(( SELECT sum(x.amount) AS sum
                   FROM public.supplier_invoice_payment x
                  WHERE (x.invoice_id = si.id)), (0)::numeric))::numeric(14,2) AS pagado
           FROM public.supplier_invoice si
        )
 SELECT id AS invoice_id,
    account_id,
    company_id,
    total,
    pagado,
    (GREATEST((total - pagado), (0)::numeric))::numeric(14,2) AS pendiente,
    due_date AS vence,
        CASE
            WHEN (status = 'pagada'::text) THEN 'pagada'::text
            WHEN (status <> 'aprobada'::text) THEN status
            WHEN ((total - pagado) < 0.005) THEN 'pagada'::text
            WHEN ((due_date IS NOT NULL) AND (due_date < public.conta_hoy())) THEN 'vencida'::text
            WHEN (pagado > (0)::numeric) THEN 'pagada_parte'::text
            WHEN (due_date IS NULL) THEN 'sin_vencimiento'::text
            WHEN (due_date <= (public.conta_hoy() + 7)) THEN 'vence_semana'::text
            ELSE 'por_pagar'::text
        END AS estado,
        CASE
            WHEN ((status = 'aprobada'::text) AND (due_date IS NOT NULL) AND (due_date < public.conta_hoy()) AND ((total - pagado) >= 0.005)) THEN (public.conta_hoy() - due_date)
            ELSE NULL::integer
        END AS dias_vencida
   FROM p;


--
-- Name: VIEW conta_recibida_pago; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.conta_recibida_pago IS 'PC01 · El estado de pago de cada factura recibida, calculado en un solo sitio. Lo leen todas las pantallas.';


