    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT corporate_tax_filing_check CHECK (((result_kind = 'zero'::text) = (result_amount = (0)::numeric))),
    CONSTRAINT corporate_tax_filing_check1 CHECK (((origin <> 'manual'::text) OR ((manual_reason IS NOT NULL) AND (btrim(manual_reason) <> ''::text)))),
    CONSTRAINT corporate_tax_filing_fiscal_year_check CHECK (((fiscal_year >= 2000) AND (fiscal_year <= 2100))),
    CONSTRAINT corporate_tax_filing_origin_check CHECK ((origin = ANY (ARRAY['manual'::text, 'justificante'::text]))),
    CONSTRAINT corporate_tax_filing_quota_check CHECK ((quota >= (0)::numeric)),
    CONSTRAINT corporate_tax_filing_result_amount_check CHECK ((result_amount >= (0)::numeric)),
    CONSTRAINT corporate_tax_filing_result_kind_check CHECK ((result_kind = ANY (ARRAY['to_pay'::text, 'to_refund'::text, 'zero'::text])))
);


