    account_id uuid NOT NULL,
    item_type text NOT NULL,
    days_a integer DEFAULT 3 NOT NULL,
    days_b integer DEFAULT 7 NOT NULL,
    days_c integer DEFAULT 14 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT count_cadence_dias_razonables CHECK (((days_a >= 1) AND (days_a <= 365) AND ((days_b >= 1) AND (days_b <= 365)) AND ((days_c >= 1) AND (days_c <= 365))))
);


--
-- Name: TABLE count_cadence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.count_cadence IS 'Cada cuántos días vuelve a salir un artículo en el autoinventario, por cuenta y por tipo. Antes era una constante del código (3/7/14). Decidido el 10/09/2026: el packaging vuelve cada 3 días sea de la clase que sea.';


--
-- Name: country; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.country (
    alpha2 character(2) NOT NULL,
    alpha3 character(3) NOT NULL,
    name_es text NOT NULL,
    source_key text NOT NULL,
    CONSTRAINT country_alpha2_check CHECK ((alpha2 ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT country_alpha3_check CHECK ((alpha3 ~ '^[A-Z]{3}$'::text))
);


--
-- Name: TABLE country; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.country IS 'C00. Países, ISO 3166-1, nombres en español de la Oficina de Publicaciones de la UE.';


--
-- Name: coupon; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.coupon (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    code text,
    name text NOT NULL,
    discount_type text NOT NULL,
    value numeric NOT NULL,
    applies_to text DEFAULT 'subtotal'::text NOT NULL,
    min_subtotal numeric,
    first_order_only boolean DEFAULT false NOT NULL,
    auto_apply boolean DEFAULT false NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    max_redemptions integer,
    max_per_customer integer DEFAULT 1 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    omnibus_ref_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    kind text DEFAULT 'standard'::text NOT NULL,
    frequency_threshold integer,
    origin text DEFAULT 'manual'::text NOT NULL,
    paused_at timestamp with time zone,
    weekdays smallint[],
    time_from time without time zone,
    time_to time without time zone,
    budget_max numeric,
    channels text[] DEFAULT '{shop}'::text[] NOT NULL,
    scope jsonb,
    CONSTRAINT coupon_applies_to_check CHECK ((applies_to = 'subtotal'::text)),
    CONSTRAINT coupon_auto_needs_no_code CHECK (((NOT auto_apply) OR (code IS NULL))),
    CONSTRAINT coupon_discount_type_check CHECK ((discount_type = ANY (ARRAY['percent'::text, 'fixed'::text]))),
    CONSTRAINT coupon_frequency_threshold_check CHECK (((frequency_threshold IS NULL) OR (frequency_threshold >= 2))),
    CONSTRAINT coupon_kind_check CHECK ((kind = ANY (ARRAY['standard'::text, 'frequency'::text, 'item_percent'::text, 'free_delivery'::text, 'bogo'::text, 'free_item'::text]))),
    CONSTRAINT coupon_max_per_customer_check CHECK ((max_per_customer >= 1)),
    CONSTRAINT coupon_max_redemptions_check CHECK (((max_redemptions IS NULL) OR (max_redemptions > 0))),
    CONSTRAINT coupon_min_subtotal_check CHECK (((min_subtotal IS NULL) OR (min_subtotal >= (0)::numeric))),
    CONSTRAINT coupon_origin_check CHECK ((origin = ANY (ARRAY['manual'::text, 'rule'::text, 'agent'::text]))),
    CONSTRAINT coupon_percent_max CHECK (((discount_type <> 'percent'::text) OR (value <= (100)::numeric))),
    CONSTRAINT coupon_value_check CHECK ((value > (0)::numeric)),
    CONSTRAINT coupon_window CHECK (((ends_at IS NULL) OR (starts_at IS NULL) OR (ends_at > starts_at)))
);


--
-- Name: COLUMN coupon.scope; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.coupon.scope IS 'Alcance de campañas de plataforma: {"brand_ids":[uuid...],"menu_item_ids":[uuid...]|null}. NULL en cupones del Shop.';


