    customer_phone text,
    discount_amount numeric NOT NULL,
    reference_subtotal numeric NOT NULL,
    margin_after numeric,
    ts timestamp with time zone DEFAULT now() NOT NULL,
    is_cycle boolean DEFAULT false NOT NULL
);


