    location_id uuid,
    valid_from date,
    valid_to date,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT courier_bonus_kind_check CHECK ((kind = 'quest'::text)),
    CONSTRAINT courier_bonus_period_check CHECK ((period = ANY (ARRAY['day'::text, 'week'::text])))
);


