--
-- Name: course; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.course (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid,
    code text NOT NULL,
    title text NOT NULL,
    summary text,
    legal_basis text,
    delivery_mode text NOT NULL,
    reeval_months integer,
    is_mandatory boolean DEFAULT true NOT NULL,
    appcc_prerequisite boolean DEFAULT false NOT NULL,
    estimated_minutes integer,
    pass_threshold_pct integer DEFAULT 70 NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    adopted_from_course_id uuid,
    requires_practical boolean DEFAULT false NOT NULL,
    category text,
    business_types text[] DEFAULT '{todos}'::text[] NOT NULL,
    level text,
    recommended_order integer,
    cover_url text,
    source_recipe_item_id uuid,
    whatsapp_hook text,
    CONSTRAINT course_business_types_check CHECK ((business_types <@ ARRAY['restaurante'::text, 'bar_cafeteria'::text, 'dark_kitchen'::text, 'delivery'::text, 'hotel'::text, 'cadena'::text, 'catering'::text, 'todos'::text])),
    CONSTRAINT course_category_check CHECK ((category = ANY (ARRAY['cumplimiento'::text, 'cocina'::text, 'delivery'::text, 'sala'::text, 'equipo'::text, 'producto'::text, 'sostenibilidad'::text]))),
    CONSTRAINT course_delivery_mode_check CHECK ((delivery_mode = ANY (ARRAY['folvy_imparte'::text, 'solo_archivo'::text, 'mixto'::text]))),
    CONSTRAINT course_level_check CHECK ((level = ANY (ARRAY['base'::text, 'especialista'::text, 'mando'::text]))),
    CONSTRAINT course_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text])))
);


--
-- Name: TABLE course; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.course IS 'Curso interno (Formación C1). account_id NULL = plantilla global Folvy (patrón ingredient_template).';


--
-- Name: COLUMN course.adopted_from_course_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.adopted_from_course_id IS 'Si esta fila es una copia adoptada de una plantilla global, apunta al course.id original (account_id IS NULL). NULL en la plantilla global y en cursos creados desde cero por la cuenta.';


--
-- Name: COLUMN course.requires_practical; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.requires_practical IS 'Si true, aprobar el test + firmar NO deja el curso "vigente": falta que un admin/manager verifique en el puesto los course_practical_item (estado pendiente_practica en training_compliance_matrix/training_gaps).';


--
-- Name: COLUMN course.category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.category IS 'Eje 1 del catálogo (guía §5.bis): de qué trata. NULL = curso sin clasificar (deuda declarada, no bloquea nada).';


--
-- Name: COLUMN course.business_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.business_types IS 'Eje 2: a qué tipo de negocio le sirve. Vacío o que contenga ''todos'' = aplica a cualquiera. REGLA DURA: un curso category=''cumplimiento'' NUNCA se filtra por esto en el catálogo — si la ley obliga, obliga a todos.';


--
-- Name: COLUMN course.level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.level IS 'Eje 3: a quién va dirigido dentro del local (base/especialista/mando). NULL = sin clasificar.';


--
-- Name: COLUMN course.recommended_order; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.recommended_order IS 'Orden del itinerario sugerido a un empleado nuevo (menor primero). NULL = sin posición sugerida.';


--
-- Name: COLUMN course.cover_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.cover_url IS 'Portada del catálogo (16:9). Puede ser una ruta pública estática (/formacion/portadas/*, servida por Vercel desde public/) o un path del bucket privado course-section-images ({account_id}/covers/..., portada propia del cliente vía "Cambiar portada"). Resolución en 3 capas si es NULL: 1) cover_url, 2) primera course_section con media_url, 3) fondo por categoría en la UI. Se resuelve con courseImagesService.getSignedSectionImageUrls -- MISMA función que ya distingue ruta pública de path de Storage, sin resolver nuevo.';


--
-- Name: COLUMN course.source_recipe_item_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.source_recipe_item_id IS 'Si este curso se generó desde un plato (C7), el recipe_item de origen. NULL = curso no generado (plantilla o creado a mano). Copia, no referencia: el contenido del curso NO se actualiza solo si cambia la receta -- hay que Regenerar explícitamente.';


--
-- Name: COLUMN course.whatsapp_hook; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course.whatsapp_hook IS 'Texto del aviso de WhatsApp al empleado (tono ameno). Nullable: sin gancho, no se envia aviso. Lo propone la IA al publicar; el admin lo edita.';


--
-- Name: course_assignment; Type: TABLE; Schema: public; Owner: -
