    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    account_id uuid NOT NULL,
    employee_id uuid,
    role text,
    location_id uuid,
    due_at timestamp with time zone,
    origin text NOT NULL,
    source_incident_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    path_item_id uuid,
    CONSTRAINT course_assignment_origin_check CHECK ((origin = ANY (ARRAY['manual'::text, 'onboarding'::text, 'reeval_periodica'::text, 'reeval_evento'::text]))),
    CONSTRAINT course_assignment_target_check CHECK (((employee_id IS NOT NULL) OR (role IS NOT NULL) OR (location_id IS NOT NULL)))
);


--
-- Name: TABLE course_assignment; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.course_assignment IS 'A quién va dirigido el curso: por empleado directo, por puesto (role) o por local. Al menos uno de los tres.';


--
-- Name: COLUMN course_assignment.path_item_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course_assignment.path_item_id IS 'training_path_item de origen si esta asignación viene de un itinerario de incorporación. NULL = asignación manual, mandatoria por cuenta, u otro origen.';


