--
-- Name: course_signature; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.course_signature (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    attempt_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    signature_png text NOT NULL,
    signer_name text NOT NULL,
    signer_doc_id text NOT NULL,
    signed_at timestamp with time zone DEFAULT now() NOT NULL,
    ip text,
    user_agent text,
    auth_method text DEFAULT 'employee_session'::text NOT NULL,
    auth_uid uuid,
    course_version integer NOT NULL,
    content_snapshot jsonb
);


--
-- Name: TABLE course_signature; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.course_signature IS 'Firma manuscrita electrónica (no cualificada). auth_uid = auth.uid() resuelto server-side en sign_course_attempt, NUNCA de un parámetro del cliente. course_version = versión del curso en el momento de firmar (si el curso cambia después, el acta sigue diciendo qué firmó exactamente esta persona).';


--
-- Name: COLUMN course_signature.signature_png; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course_signature.signature_png IS 'Path dentro del bucket privado course-signatures (NO el PNG en sí). Servida por URL firmada.';


--
-- Name: COLUMN course_signature.content_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.course_signature.content_snapshot IS 'Congelado en el momento de la firma: título, secciones (ord/title/body) y preguntas con sus opciones (text/isCorrect/explanation) tal como estaban entonces. Es lo que garantiza que el acta pueda mostrar qué firmó exactamente el empleado, incluso si el contenido vivo del curso se edita o se regenera después. NULL = firma anterior a este campo, sin rescatar todavía.';


