--
-- Name: customer_fiscal; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_fiscal (
    party_id uuid NOT NULL,
    account_id uuid NOT NULL,
    legal_name text,
    tax_id_type text,
    country_code text DEFAULT 'ES'::text NOT NULL,
    entity_kind text,
    tax_id_check_status text,
    tax_id_checked_at timestamp with time zone,
    tax_id_verified_at timestamp with time zone,
    fiscal_street text,
    fiscal_postal_code text,
    fiscal_city text,
    fiscal_province text,
    equivalence_surcharge boolean DEFAULT false NOT NULL,
    withholding_rate_id uuid,
    operation_scope text DEFAULT 'domestic'::text NOT NULL,
    exclude_347 boolean DEFAULT false NOT NULL,
    exclude_347_reason text,
    payment_method text,
    payment_terms_days integer,
    payment_fixed_days integer[],
    collection_treasury_id uuid,
    iban text,
    sepa_mandate_ref text,
    sepa_mandate_date date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_fiscal_country_code_check CHECK ((country_code ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT customer_fiscal_entity_kind_check CHECK (((entity_kind IS NULL) OR (entity_kind = ANY (ARRAY['company'::text, 'self_employed'::text, 'person'::text])))),
    CONSTRAINT customer_fiscal_iban_check CHECK (((iban IS NULL) OR (iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$'::text))),
    CONSTRAINT customer_fiscal_motivo_347 CHECK (((NOT exclude_347) OR (length(TRIM(BOTH FROM COALESCE(exclude_347_reason, ''::text))) > 0))),
    CONSTRAINT customer_fiscal_operation_scope_check CHECK ((operation_scope = ANY (ARRAY['domestic'::text, 'eu'::text, 'export'::text]))),
    CONSTRAINT customer_fiscal_payment_method_check CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['transfer'::text, 'direct_debit'::text, 'card'::text, 'cash'::text, 'prepaid'::text])))),
    CONSTRAINT customer_fiscal_payment_terms_days_check CHECK (((payment_terms_days IS NULL) OR ((payment_terms_days >= 0) AND (payment_terms_days <= 365)))),
    CONSTRAINT customer_fiscal_tax_id_check_status_check CHECK (((tax_id_check_status IS NULL) OR (tax_id_check_status = ANY (ARRAY['valid'::text, 'invalid'::text, 'pending'::text])))),
    CONSTRAINT customer_fiscal_tax_id_type_check CHECK (((tax_id_type IS NULL) OR (tax_id_type = ANY (ARRAY['nif_es'::text, 'vat_eu'::text, 'foreign'::text]))))
);


