--
-- Name: TABLE db_health_snapshot_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.db_health_snapshot_log IS 'RLS deny-all intencional (vigia interno de salud de BBDD). Retencion 48h. total_connections = pg_stat_activity filtrado a backend_type=client backend (corregido 11/08). waiting_locks = conteo crudo de TODO pg_stat_activity. writer_count es NULL en las filas del chequeo de cada minuto y solo lleva valor real en la fila que inserta cada 15 min db_health_writer_regression_check() — esperado SIEMPRE 3 cuando no es NULL.';


--
-- Name: db_health_snapshot_log_id_seq; Type: SEQUENCE; Schema: public; Owner: -
