--
-- Name: delivery_zone; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.delivery_zone (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    name text NOT NULL,
    method text NOT NULL,
    radius_m integer,
    center public.geography(Point,4326),
    area public.geography(Polygon,4326),
    postal_codes text[],
    delivery_fee numeric DEFAULT 0 NOT NULL,
    min_order numeric,
    eta_min integer,
    priority integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    fee_source text DEFAULT 'manual'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT delivery_zone_delivery_fee_check CHECK ((delivery_fee >= (0)::numeric)),
    CONSTRAINT delivery_zone_eta_min_check CHECK (((eta_min IS NULL) OR (eta_min >= 0))),
    CONSTRAINT delivery_zone_fee_source_check CHECK ((fee_source = ANY (ARRAY['manual'::text, 'distance'::text, 'broker'::text, 'dynamic'::text]))),
    CONSTRAINT delivery_zone_geometry_chk CHECK ((((method = 'radius'::text) AND (radius_m IS NOT NULL) AND (radius_m > 0) AND (center IS NOT NULL) AND (area IS NULL) AND (postal_codes IS NULL)) OR ((method = 'polygon'::text) AND (area IS NOT NULL) AND (radius_m IS NULL) AND (center IS NULL) AND (postal_codes IS NULL)) OR ((method = 'postal'::text) AND (postal_codes IS NOT NULL) AND (array_length(postal_codes, 1) > 0) AND (radius_m IS NULL) AND (center IS NULL) AND (area IS NULL)))),
    CONSTRAINT delivery_zone_method_check CHECK ((method = ANY (ARRAY['radius'::text, 'polygon'::text, 'postal'::text]))),
    CONSTRAINT delivery_zone_min_order_check CHECK (((min_order IS NULL) OR (min_order >= (0)::numeric)))
);


--
-- Name: TABLE delivery_zone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.delivery_zone IS 'Zonas de entrega por local (Capa 1 del motor de envío). Métodos radio/polígono/CP conviven; coste/mínimo/ETA por zona. Solapamiento lo resuelve el motor (tarifa más baja).';


--
-- Name: COLUMN delivery_zone.fee_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.delivery_zone.fee_source IS 'Origen de la tarifa: manual (hoy) | distance | broker (Capa 2) | dynamic (Capa 3). El motor añade fuentes sin reescribir.';


