-- Name: document_inbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.document_inbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid,
    channel text NOT NULL,
    status text DEFAULT 'recibido'::text NOT NULL,
    email_id text,
    email_to text,
    email_from text,
    email_subject text,
    email_received_at timestamp with time zone,
    link_url text,
    file_bucket text DEFAULT 'receipt-uploads'::text NOT NULL,
    file_path text,
    file_name text,
    mime_type text,
    size_bytes integer,
    sha256 text,
    ai_session_id uuid,
    supplier_invoice_id uuid,
    duplicate_of_invoice_id uuid,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
