    CONSTRAINT entry_template_line_fixed_amount_check CHECK (((fixed_amount IS NULL) OR (fixed_amount > (0)::numeric))),
    CONSTRAINT entry_template_line_position_check CHECK (("position" > 0)),
    CONSTRAINT entry_template_line_side_check CHECK ((side = ANY (ARRAY['debit'::text, 'credit'::text])))
);


--
-- Name: entry_text; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.entry_text (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid,
    company_id uuid,
    is_system boolean DEFAULT false NOT NULL,
