    source_key text,
    sort_order smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT entry_text_purpose_check CHECK ((purpose = ANY (ARRAY['purchase_invoice'::text, 'sales_invoice'::text, 'payment'::text, 'collection'::text, 'other'::text]))),
    CONSTRAINT entry_text_serie CHECK (public.conta_fila_serie_ok(is_system, account_id, company_id, legal_ref, verified_at, source_key)),
    CONSTRAINT entry_text_text_check CHECK ((length(TRIM(BOTH FROM text)) > 0))
);


--
-- Name: TABLE entry_text; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.entry_text IS 'C00. Textos tipo de los apuntes («Su factura n.º *»). El asterisco se sustituye por el número.';


--
-- Name: expense_category; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.expense_category (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    pgc_account_hint text NOT NULL,
    sort_order smallint DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    account_id uuid,
    company_id uuid,
    is_system boolean DEFAULT true NOT NULL,
    example text,
    kind text DEFAULT 'expense'::text NOT NULL,
    legal_ref text,
    verified_at date,
    source_key text,
    supplier_account_leaf text,
    supplier_account_ref text,
    CONSTRAINT expense_category_kind_check CHECK ((kind = ANY (ARRAY['expense'::text, 'income'::text]))),
