    CONSTRAINT expense_category_supplier_account_leaf_check CHECK ((supplier_account_leaf = ANY (ARRAY['4000'::text, '4100'::text]))),
    CONSTRAINT expense_category_supplier_leaf_con_norma CHECK (((supplier_account_leaf IS NULL) = (supplier_account_ref IS NULL)))
);


--
-- Name: TABLE expense_category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.expense_category IS 'C01. Tipos de gasto (catálogo global de Folvy). pgc_account_hint = cuenta del PGC (RD 1514/2007) que le corresponde; C02 lo enlaza con el plan contable de cada cuenta.';


--
-- Name: COLUMN expense_category.supplier_account_leaf; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.expense_category.supplier_account_leaf IS 'C02. De qué hoja cuelga la subcuenta de un proveedor de este tipo de gasto: 4000 (mercancía) o 4100 (servicios). Con su norma en supplier_account_ref.';


--
