--
-- Name: external_compare_day; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_compare_day (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    day date NOT NULL,
    folvy_count integer DEFAULT 0 NOT NULL,
    diez_count integer DEFAULT 0 NOT NULL,
    folvy_debit numeric(14,2) DEFAULT 0 NOT NULL,
    folvy_credit numeric(14,2) DEFAULT 0 NOT NULL,
    diez_debit numeric(14,2) DEFAULT 0 NOT NULL,
    diez_credit numeric(14,2) DEFAULT 0 NOT NULL,
    status text NOT NULL,
    differences jsonb DEFAULT '[]'::jsonb NOT NULL,
    explanation text,
    explained_by uuid,
    explained_by_name text,
    explained_at timestamp with time zone,
    compared_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT external_compare_day_check CHECK (((explained_at IS NULL) = (explanation IS NULL))),
    CONSTRAINT external_compare_day_differences_check CHECK ((jsonb_typeof(differences) = 'array'::text)),
    CONSTRAINT external_compare_day_status_check CHECK ((status = ANY (ARRAY['igual'::text, 'distinto'::text, 'solo_folvy'::text, 'solo_diez'::text])))
);


--
-- Name: TABLE external_compare_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_compare_day IS 'Folvy contra Diez, día a día y al céntimo (Diez no usa analítica: por día, no por local).';


--
-- Name: external_document; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_document (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    source text NOT NULL,
    ext_year text,
    invoice_kind text,
    ext_series text,
    invoice_number text,
    invoice_date date,
    tax_id text,
    file_name text,
    storage_path text,
    sha256 text,
    size_bytes integer,
    entry_id uuid,
    status text NOT NULL,
    reason text,
    attempts smallint DEFAULT 0 NOT NULL,
    last_try_at timestamp with time zone,
    import_run_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT external_document_check CHECK (((status <> 'enlazado'::text) OR ((entry_id IS NOT NULL) AND (storage_path IS NOT NULL) AND (sha256 IS NOT NULL)))),
    CONSTRAINT external_document_check1 CHECK (((status <> 'pendiente_diez'::text) OR ((entry_id IS NOT NULL) AND (storage_path IS NULL)))),
    CONSTRAINT external_document_check2 CHECK (((status <> 'revisar'::text) OR ((storage_path IS NOT NULL) AND (reason IS NOT NULL)))),
    CONSTRAINT external_document_invoice_kind_check CHECK ((invoice_kind = ANY (ARRAY['expedida'::text, 'recibida'::text]))),
    CONSTRAINT external_document_no_requiere_check CHECK (((status <> 'no_requiere'::text) OR ((entry_id IS NOT NULL) AND (storage_path IS NULL) AND (reason IS NOT NULL)))),
    CONSTRAINT external_document_size_bytes_check CHECK (((size_bytes IS NULL) OR (size_bytes >= 0))),
    CONSTRAINT external_document_source_check CHECK ((source = ANY (ARRAY['diez_api'::text, 'diez_zip'::text]))),
    CONSTRAINT external_document_status_check CHECK ((status = ANY (ARRAY['enlazado'::text, 'revisar'::text, 'pendiente_diez'::text, 'no_requiere'::text])))
);


--
-- Name: TABLE external_document; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_document IS 'Documentos de las facturas traídas de Diez (zip del libro de requerimientos o API). Lo que no casa: revisar, sin adivinar.';


--
-- Name: COLUMN external_document.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_document.status IS 'enlazado (fichero y asiento) · revisar (fichero que no casa, con porqué) · pendiente_diez (asiento sin fichero, se reintenta) · no_requiere (asiento que no lleva PDF propio, con porqué).';


--
-- Name: external_entry_snapshot; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_entry_snapshot (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    program text NOT NULL,
    ext_year text NOT NULL,
