    total_debit numeric(14,2) NOT NULL,
    total_credit numeric(14,2) NOT NULL,
    hash text NOT NULL,
    import_run_id uuid,
    read_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT external_entry_snapshot_lines_check CHECK ((jsonb_typeof(lines) = 'array'::text)),
    CONSTRAINT external_entry_snapshot_program_check CHECK ((program = 'diez'::text))
);


--
-- Name: TABLE external_entry_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_entry_snapshot IS 'Cómo estaba cada asiento en Diez cuando se leyó: lo que se compara día a día.';


--
-- Name: external_integration; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_integration (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    external_org_id uuid,
    organization_name text,
    token_secret_name text,
    ownership_type text DEFAULT 'own'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    push_status_enabled boolean DEFAULT false NOT NULL,
    source text DEFAULT 'lastapp'::text NOT NULL,
    access_token text,
    external_catalog_id text,
    external_location_id text,
    connection_name text,
    token_status text DEFAULT 'unknown'::text NOT NULL,
    token_checked_at timestamp with time zone,
    location_id uuid,
    external_account_name text,
    external_location_name text,
    revoke_pending boolean DEFAULT false NOT NULL,
    callback_status text DEFAULT 'unknown'::text NOT NULL,
    callback_checked_at timestamp with time zone,
    CONSTRAINT external_integration_callback_status_check CHECK ((callback_status = ANY (ARRAY['ok'::text, 'missing'::text, 'unknown'::text]))),
    CONSTRAINT external_integration_source_shape_chk CHECK ((((source = 'lastapp'::text) AND (external_org_id IS NOT NULL) AND (token_secret_name IS NOT NULL)) OR ((source = 'hubrise'::text) AND ((NOT is_active) OR (access_token IS NOT NULL)) AND (external_location_id IS NOT NULL)) OR (source <> ALL (ARRAY['lastapp'::text, 'hubrise'::text])))),
    CONSTRAINT external_integration_token_status_check CHECK ((token_status = ANY (ARRAY['ok'::text, 'invalid'::text, 'unknown'::text])))
);


--
-- Name: COLUMN external_integration.push_status_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_integration.push_status_enabled IS 'Si true, Folvy empuja los cambios de order_status a Last (PUT /orders/{tabId}/status). Apagado por defecto.';


--
-- Name: COLUMN external_integration.access_token; Type: COMMENT; Schema: public; Owner: -
