    ext_tax_id text,
    payload_hash text NOT NULL,
    status text DEFAULT 'pendiente'::text NOT NULL,
    attempts smallint DEFAULT 0 NOT NULL,
    last_error text,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    document_id uuid,
    document_status text,
    document_error text,
    document_attached_at timestamp with time zone,
    document_attached_via text,
    document_attached_by uuid,
    document_attached_by_name text,
    next_try_at timestamp with time zone,
    CONSTRAINT external_send_attempts_check CHECK (((attempts >= 0) AND (attempts <= 3))),
    CONSTRAINT external_send_check CHECK (((status <> ALL (ARRAY['enviado'::text, 'enlazado'::text])) OR ((ext_year IS NOT NULL) AND (ext_series IS NOT NULL) AND (ext_number IS NOT NULL)))),
    CONSTRAINT external_send_check1 CHECK (((kind <> 'factura'::text) OR (ext_invoice_number IS NOT NULL) OR (status = ANY (ARRAY['pendiente'::text, 'rechazado'::text])))),
    CONSTRAINT external_send_document_attached_via_check CHECK ((document_attached_via = ANY (ARRAY['diez'::text, 'a_mano'::text]))),
    CONSTRAINT external_send_document_status_check CHECK ((document_status = ANY (ARRAY['pendiente'::text, 'adjunto'::text, 'fallo'::text, 'pendiente_diez'::text]))),
    CONSTRAINT external_send_kind_check CHECK ((kind = ANY (ARRAY['asiento'::text, 'factura'::text]))),
    CONSTRAINT external_send_status_check CHECK ((status = ANY (ARRAY['pendiente'::text, 'enviado'::text, 'enlazado'::text, 'rechazado'::text])))
);


--
-- Name: TABLE external_send; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_send IS 'Lo que Folvy envía a Diez: la clave que devuelve Diez, la huella de lo enviado y como mucho 3 intentos.';


--
-- Name: COLUMN external_send.document_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_send.document_status IS 'El documento en Diez: pendiente (aún no se ha subido), adjunto (Diez lo tiene), fallo (con document_error) o pendiente_diez (C06b R7: la factura está en Diez SIN su PDF, que hay que adjuntar allí; sale en Libros › Pendientes de adjuntar en Diez).';


--
-- Name: COLUMN external_send.document_attached_via; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_send.document_attached_via IS 'C06b R7 · Cómo llegó el PDF a Diez: diez (lo subió Folvy por apiCON y lo leyó de vuelta) o a_mano (una persona lo adjuntó en Diez y lo marcó en Folvy).';


--
-- Name: COLUMN external_send.next_try_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_send.next_try_at IS 'C07 · Cuándo lo vuelve a intentar el servidor (conta-diez-cola). Null: no se reintenta solo (ya está en Diez, o lo tiene que mirar una persona: «Reintentar»).';


