    CONSTRAINT goods_receipt_path_path_check CHECK ((path = ANY (ARRAY['factura'::text, 'pendiente_factura'::text, 'liquidacion'::text, 'a_nombre_de_otro'::text, 'sin_decidir'::text, 'anulada'::text, 'error'::text]))),
    CONSTRAINT goods_receipt_path_question_check CHECK ((question = ANY (ARRAY['a_nombre_de'::text, 'papel_y_ficha'::text, 'ficha_sin_forma'::text, 'sin_papel'::text, 'a_nombre_de_otro'::text, 'error'::text, 'factura_sin_importes'::text, 'factura_repetida'::text])))
);


--
-- Name: TABLE goods_receipt_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.goods_receipt_path IS 'Compras (10/10). Por dónde va cada recepción confirmada: factura, pendiente de factura, liquidación del mes, a nombre de otro o sin decidir; con la pregunta si la hay. supplier_id: de quién es a efectos de compras (el de la recepción, o el que liquida). consumed_at: ya la usó una factura, un casado o una liquidación, y no se vuelve a decidir.';


