    CONSTRAINT stock_movement_source_valid CHECK ((source_type = ANY (ARRAY['goods_receipt_line'::text, 'sale'::text, 'inventory_count'::text, 'transfer'::text, 'adjustment'::text, 'waste'::text]))),
    CONSTRAINT stock_movement_type_valid CHECK ((movement_type = ANY (ARRAY['recepcion'::text, 'consumo'::text, 'ajuste'::text, 'traspaso_entrada'::text, 'traspaso_salida'::text, 'recuento'::text, 'apertura'::text, 'merma'::text])))
);


--
-- Name: goods_receipt_posting_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.goods_receipt_posting_status WITH (security_invoker='on') AS
 SELECT gr.id AS goods_receipt_id,
    gr.account_id,
    gr.location_id,
    gr.code,
    gr.status,
    gr.needs_review,
    gr.receipt_date,
    gr.received_at,
    gr.via_assistant,
    count(l.id) FILTER (WHERE (NOT COALESCE(l.not_goods, false))) AS lines_total,
    count(l.id) FILTER (WHERE ((NOT COALESCE(l.not_goods, false)) AND (sm.id IS NOT NULL))) AS lines_posted,
    count(l.id) FILTER (WHERE ((NOT COALESCE(l.not_goods, false)) AND (sm.id IS NULL))) AS lines_pending,
    count(l.id) FILTER (WHERE COALESCE(l.not_goods, false)) AS lines_not_goods,
    count(l.id) FILTER (WHERE ((NOT COALESCE(l.not_goods, false)) AND (sm.id IS NULL) AND (l.recipe_item_id IS NULL))) AS pending_sin_articulo,
    count(l.id) FILTER (WHERE ((NOT COALESCE(l.not_goods, false)) AND (sm.id IS NULL) AND (l.recipe_item_id IS NOT NULL))) AS pending_sin_cantidad
   FROM ((public.goods_receipt gr
     LEFT JOIN public.goods_receipt_line l ON ((l.goods_receipt_id = gr.id)))
     LEFT JOIN LATERAL ( SELECT sm_1.id
           FROM public.stock_movement sm_1
          WHERE ((sm_1.source_type = 'goods_receipt_line'::text) AND (sm_1.source_id = l.id) AND (sm_1.movement_type = 'recepcion'::text))
         LIMIT 1) sm ON (true))
  GROUP BY gr.id, gr.account_id, gr.location_id, gr.code, gr.status, gr.needs_review, gr.receipt_date, gr.received_at, gr.via_assistant;


--
-- Name: VIEW goods_receipt_posting_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.goods_receipt_posting_status IS 'Lineas / posteadas / pendientes por albaran, con el join correcto (movimiento por LINEA). Fuente unica para "¿entro este albaran al almacen?".';


