--
-- Name: inventory_count_entry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_count_entry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    line_id uuid NOT NULL,
    format_id uuid,
    qty numeric,
    fraction numeric,
    qty_in_base numeric NOT NULL,
    method text NOT NULL,
    attempt smallint DEFAULT 1 NOT NULL,
    counted_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    counted_by_name text,
    recorded_by uuid,
    recorded_by_name text,
    source text DEFAULT 'tablet'::text NOT NULL,
    CONSTRAINT ice_base_no_negativa CHECK ((qty_in_base >= (0)::numeric)),
    CONSTRAINT ice_metodo_coherente CHECK (
CASE method
    WHEN 'formato'::text THEN ((format_id IS NOT NULL) AND (qty IS NOT NULL) AND (qty > (0)::numeric) AND (fraction IS NULL))
    WHEN 'fraccion'::text THEN ((format_id IS NOT NULL) AND (fraction IS NOT NULL) AND (fraction > (0)::numeric))
    WHEN 'peso'::text THEN ((qty IS NOT NULL) AND (qty >= (0)::numeric) AND (fraction IS NULL))
    WHEN 'cero'::text THEN ((qty_in_base = (0)::numeric) AND (fraction IS NULL))
    ELSE NULL::boolean
END),
    CONSTRAINT inventory_count_entry_attempt_check CHECK ((attempt >= 1)),
    CONSTRAINT inventory_count_entry_method_check CHECK ((method = ANY (ARRAY['formato'::text, 'peso'::text, 'fraccion'::text, 'cero'::text]))),
    CONSTRAINT inventory_count_entry_source_check CHECK ((source = ANY (ARRAY['tablet'::text, 'telefono'::text])))
);


--
-- Name: TABLE inventory_count_entry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inventory_count_entry IS 'Cómo se contó cada línea de inventario: una fila por formato, peso, fracción a ojo o cero explícito. counted_qty de la línea es la SUMA de qty_in_base de las entradas del ÚLTIMO intento, y la calcula save_count_line en servidor (§2.2, 10/09/2026). Los intentos anteriores se conservan.';


--
-- Name: COLUMN inventory_count_entry.counted_by_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_entry.counted_by_name IS 'Nombre de quien contó, sellado al guardar. En una corrección por teléfono no es quien teclea.';


--
-- Name: COLUMN inventory_count_entry.recorded_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_entry.recorded_by IS 'Empleado que APUNTÓ la entrada (la oficina). NULL cuando es la misma persona que contó.';


--
-- Name: COLUMN inventory_count_entry.source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_entry.source IS 'tablet = lo tecleó quien contó. telefono = lo dictó a la oficina por teléfono.';


--
-- Name: inventory_count_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_count_line (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    inventory_count_id uuid NOT NULL,
    recipe_item_id uuid NOT NULL,
    storage_area_id uuid,
    "position" integer DEFAULT 100 NOT NULL,
    system_qty numeric,
    counted_qty numeric,
    variance_qty numeric,
    variance_pct numeric,
    variance_value numeric,
    abc_class text,
    within_tolerance boolean,
    reason_code text,
    recount_of uuid,
    counted_by uuid,
    counted_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_to uuid,
    counted_at timestamp with time zone,
    counted_qty_confirmed numeric,
    counted_qty_confirmed_at timestamp with time zone,
    needs_review boolean DEFAULT false NOT NULL,
    reason_note text,
    recount_asked_at timestamp with time zone,
    recount_requested_at timestamp with time zone,
    recount_requested_by uuid,
    recount_assign_to uuid,
    no_reference boolean DEFAULT false NOT NULL,
    reason_by uuid,
    reason_by_name text,
    excluded_at timestamp with time zone,
    excluded_by uuid,
    excluded_by_name text,
    excluded_reason text,
    CONSTRAINT inventory_count_line_abc_class_check CHECK ((abc_class = ANY (ARRAY['A'::text, 'B'::text, 'C'::text]))),
    CONSTRAINT inventory_count_line_reason_code_check CHECK ((reason_code = ANY (ARRAY['merma'::text, 'caducado'::text, 'rotura'::text, 'uso_sin_apuntar'::text, 'traspaso'::text, 'error_recepcion'::text, 'error_conteo'::text, 'robo_desconocido'::text, 'error_escandallo'::text, 'otro'::text])))
);


--
-- Name: COLUMN inventory_count_line.counted_qty_confirmed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.counted_qty_confirmed IS 'Cantidad exacta que el contador confirmo explicitamente tras el aviso de cantidad absurda. Solo vale para ESE valor.';


--
-- Name: COLUMN inventory_count_line.needs_review; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.needs_review IS 'Se contó dos veces y sigue fuera de rango. autoclose_daily_count NO la aplica: espera a quien aprueba (§2.3/§2.4, 10/09/2026).';


--
-- Name: COLUMN inventory_count_line.reason_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.reason_note IS 'La nota que acompaña al motivo. OBLIGATORIA cuando el motivo es «otro».';


--
-- Name: COLUMN inventory_count_line.recount_asked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.recount_asked_at IS 'Cuándo se le pidió a quien contaba que volviera a mirarlo. Con esto puesto, el siguiente guardado de la línea se acepta siempre: el freno frena UNA vez, no deja a nadie atrapado delante de una nevera.';


--
-- Name: COLUMN inventory_count_line.recount_requested_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.recount_requested_at IS 'Quien aprueba ha pedido que se vuelva a contar este artículo. La petición está PENDIENTE mientras no exista una línea hija con recount_of = esta.';


--
-- Name: COLUMN inventory_count_line.recount_assign_to; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.recount_assign_to IS 'A quién se le asigna el recuento. Nunca a quien contó la original (§2.4).';


--
-- Name: COLUMN inventory_count_line.no_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.no_reference IS 'true cuando al guardar no había NINGUNA referencia positiva con la que comparar: ni teórico vivo (> 0) ni último recuento aprobado (> 0). La línea se guardó sin que ningún freno pudiera mirarla. Lo pone save_count_line (10/09/2026); no frena a nadie, marca para la aprobación.';


--
-- Name: COLUMN inventory_count_line.reason_by_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.reason_by_name IS 'Quien puso el motivo, sellado por trigger. NULL en las lineas anteriores al 11/09/2026: antes no se guardaba, y no se inventa hacia atras.';


--
-- Name: COLUMN inventory_count_line.excluded_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_count_line.excluded_at IS 'Linea apartada: NO se aplica al aprobar. La aparta una persona («No aplicar esta linea») o el trigger del ajuste a mano. 11/09/2026: antes solo se podia aprobar todo, y las dos correcciones se sumaban.';


--
-- Name: inventory_count_line_rebase_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_count_line_rebase_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
