    CONSTRAINT investment_good_deductible_pct_check CHECK (((deductible_pct >= (0)::numeric) AND (deductible_pct <= (100)::numeric))),
    CONSTRAINT investment_good_description_check CHECK ((length(TRIM(BOTH FROM description)) > 0)),
    CONSTRAINT investment_good_kind_check CHECK ((kind = ANY (ARRAY['mueble'::text, 'inmueble'::text])))
);


--
-- Name: TABLE investment_good; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.investment_good IS 'C05. Bien de inversión a efectos del IVA (LIVA art. 108; RIVA art. 65): alta, importe, cuota, fecha de entrada en funcionamiento, baja. Las regularizaciones anuales (LIVA arts. 107 y 109) en investment_good_regularization.';


--
-- Name: investment_good_regularization; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.investment_good_regularization (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
