    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT investment_good_regularization_final_prorrata_check CHECK (((final_prorrata >= (0)::numeric) AND (final_prorrata <= (100)::numeric)))
);


--
-- Name: invoice_approval_rule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoice_approval_rule (
