    CONSTRAINT invoice_series_doc_type_check CHECK ((doc_type = ANY (ARRAY['invoice'::text, 'simplified'::text, 'rectifying'::text, 'rectifying_simplified'::text]))),
    CONSTRAINT invoice_series_starts_at_check CHECK ((starts_at >= 1))
);


--
-- Name: TABLE invoice_series; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.invoice_series IS 'C00. Series de numeración por tipo de documento. Solo la definición: el contador llega con las facturas emitidas.';


--
-- Name: COLUMN invoice_series.channel_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoice_series.channel_id IS 'V01 · La serie de las facturas resumen de los cierres de este canal (se crea sola al validar el primero).';


--
-- Name: invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoices (
