    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT invoices_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'issued'::text, 'paid'::text, 'overdue'::text, 'refunded'::text, 'void'::text])))
);


--
-- Name: journal_correction; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_correction (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    origin_key text NOT NULL,
    proposed_code text NOT NULL,
    chosen_code text NOT NULL,
    entry_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    CONSTRAINT journal_correction_origin_key_check CHECK ((length(TRIM(BOTH FROM origin_key)) > 0))
);


--
-- Name: TABLE journal_correction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.journal_correction IS 'C04. Regla 11: una cuenta que la persona cambió en una propuesta. La siguiente propuesta del mismo origen (origin_key: «channel_settlement:<canal>», «supplier_invoice:<proveedor>») lo hace igual y lo dice.';


--
-- Name: journal_dismissal; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_dismissal (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    source_type text NOT NULL,
    source_key text NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    CONSTRAINT journal_dismissal_reason_check CHECK ((length(TRIM(BOTH FROM reason)) > 0))
);


--
-- Name: TABLE journal_dismissal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.journal_dismissal IS 'C04. Una propuesta descartada, con su motivo: Folvy no la vuelve a proponer (source_key: el id del documento, o «local:día» para las ventas del día).';


--
-- Name: journal_entry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_entry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    fiscal_year_id uuid NOT NULL,
    series smallint NOT NULL,
    number integer,
    entry_date date NOT NULL,
    concept text NOT NULL,
    source_type text NOT NULL,
    source_id uuid,
    status text DEFAULT 'borrador'::text NOT NULL,
    confidence text,
    reason text,
    reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    party_id uuid,
    document_ref text,
    document_date date,
    document_url text,
    external_program text,
    external_series text,
    external_number text,
    validated_at timestamp with time zone,
    validated_by uuid,
    validated_by_name text,
    chain_seq bigint,
    prev_hash text,
    hash text,
    reverses_entry_id uuid,
    voided_by_entry_id uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    voided_by_name text,
    void_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    external_year text,
    external_hash text,
    import_run_id uuid,
    CONSTRAINT journal_entry_anulado_completo CHECK ((((status = 'anulado'::text) = (voided_by_entry_id IS NOT NULL)) AND ((status <> 'anulado'::text) OR ((voided_at IS NOT NULL) AND (length(TRIM(BOTH FROM COALESCE(void_reason, ''::text))) > 0))))),
    CONSTRAINT journal_entry_concept_check CHECK ((length(TRIM(BOTH FROM concept)) > 0)),
    CONSTRAINT journal_entry_confidence_check CHECK (((confidence IS NULL) OR (confidence = ANY (ARRAY['seguro'::text, 'probable'::text, 'duda'::text])))),
    CONSTRAINT journal_entry_contraasiento CHECK (((source_type = 'reversal'::text) = (reverses_entry_id IS NOT NULL))),
    CONSTRAINT journal_entry_number_check CHECK (((number IS NULL) OR (number > 0))),
    CONSTRAINT journal_entry_numero_al_validar CHECK (((status = ANY (ARRAY['validado'::text, 'anulado'::text])) = (number IS NOT NULL))),
    CONSTRAINT journal_entry_propuesta_con_porque CHECK (((status <> 'propuesto'::text) OR ((confidence IS NOT NULL) AND (length(TRIM(BOTH FROM COALESCE(reason, ''::text))) > 0)))),
    CONSTRAINT journal_entry_reasons_check CHECK ((jsonb_typeof(reasons) = 'array'::text)),
    CONSTRAINT journal_entry_series_check CHECK ((series = ANY (ARRAY[1, 2, 3, 4, 9]))),
    CONSTRAINT journal_entry_source_type_check CHECK ((source_type = ANY (ARRAY['sales_day'::text, 'sales_adjustment'::text, 'supplier_invoice'::text, 'supplier_payment'::text, 'channel_settlement'::text, 'licensed_settlement'::text, 'payroll'::text, 'bank'::text, 'vat_settlement'::text, 'manual'::text, 'template'::text, 'reversal'::text, 'opening'::text, 'closing'::text, 'migrated'::text, 'purchase_accrual'::text, 'purchase_accrual_reversal'::text, 'customer_invoice'::text, 'customer_payment'::text]))),
    CONSTRAINT journal_entry_status_check CHECK ((status = ANY (ARRAY['propuesto'::text, 'borrador'::text, 'validado'::text, 'anulado'::text]))),
    CONSTRAINT journal_entry_traido CHECK (((source_type = 'migrated'::text) = (external_program IS NOT NULL))),
    CONSTRAINT journal_entry_validado_completo CHECK (((status <> ALL (ARRAY['validado'::text, 'anulado'::text])) OR ((validated_at IS NOT NULL) AND (hash IS NOT NULL) AND (chain_seq IS NOT NULL))))
);


--
-- Name: TABLE journal_entry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.journal_entry IS 'C04. El asiento. Series con el código de Diez y su palabra en pantalla: 1 Ventas, 2 Compras, 3 Banco, 4 General (también apertura, cierre e IVA), 9 Nóminas. El número se pone al validar y no deja huecos; lo validado no se toca: se anula con un contraasiento enlazado.';


--
-- Name: COLUMN journal_entry.source_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_entry.source_type IS 'C04. De dónde sale: sales_day (resumen de ventas del día), sales_adjustment (cancelación o devolución que decide la plataforma), supplier_invoice, supplier_payment, channel_settlement, licensed_settlement, payroll, bank, vat_settlement, manual, template, reversal (contraasiento), opening, closing, migrated (traído).';


--
-- Name: COLUMN journal_entry.chain_seq; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_entry.chain_seq IS 'C04. Orden de validación dentro de la empresa: la huella de cada asiento encadena con la del anterior en este orden.';


--
-- Name: COLUMN journal_entry.external_year; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_entry.external_year IS 'Ejercicio del asiento en el programa de origen (Diez: texto, «2025»).';


--
-- Name: COLUMN journal_entry.external_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_entry.external_hash IS 'Huella de cómo era el asiento en el origen al traerlo: si cambia allí, se ve.';


--
-- Name: journal_entry_document; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_entry_document (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    entry_id uuid NOT NULL,
    kind text NOT NULL,
    storage_path text NOT NULL,
    file_name text NOT NULL,
    sha256 text NOT NULL,
    size_bytes integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    original_name text,
    CONSTRAINT journal_entry_document_file_name_check CHECK ((file_name ~ '^[A-Za-z0-9._-]+\.pdf$'::text)),
    CONSTRAINT journal_entry_document_kind_check CHECK ((kind = ANY (ARRAY['resumen_ventas'::text, 'factura_recibida'::text, 'factura_expedida'::text]))),
    CONSTRAINT journal_entry_document_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT journal_entry_document_size_bytes_check CHECK ((size_bytes > 0))
);


--
-- Name: TABLE journal_entry_document; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.journal_entry_document IS 'El documento de un asiento validado (R15: el Resumen de ventas de un asiento de ventas de una plataforma), en el bucket conta-documentos. Uno por asiento y tipo; no se cambia.';


--
-- Name: COLUMN journal_entry_document.original_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_entry_document.original_name IS 'C06b · El nombre del documento tal como llegó (con espacios, tildes…), para enseñarlo. file_name es el limpio (conta_nombre_fichero).';


--
-- Name: journal_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_line (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    entry_id uuid NOT NULL,
    "position" smallint NOT NULL,
    company_account_id uuid NOT NULL,
    debit numeric(14,2) DEFAULT 0 NOT NULL,
    credit numeric(14,2) DEFAULT 0 NOT NULL,
    concept text,
    location_id uuid,
    is_common boolean DEFAULT false NOT NULL,
    brand_id uuid,
    party_id uuid,
    document_ref text,
    document_date date,
    tax_rate_id uuid,
    tax_base numeric(14,2),
    vat_book text,
    vat_deductible text,
    tax_documents integer DEFAULT 1 NOT NULL,
    withholding_rate_id uuid,
    withholding_base numeric(14,2),
    withholding_model text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    external_counterpart text,
    external_voucher text,
    external_negative_side text,
    withholding_period text,
    CONSTRAINT journal_line_comun_sin_local CHECK ((NOT (is_common AND (location_id IS NOT NULL)))),
    CONSTRAINT journal_line_credit_check CHECK ((credit >= (0)::numeric)),
    CONSTRAINT journal_line_debe_o_haber CHECK (((debit > (0)::numeric) <> (credit > (0)::numeric))),
    CONSTRAINT journal_line_debit_check CHECK ((debit >= (0)::numeric)),
    CONSTRAINT journal_line_deducible_solo_recibidas CHECK (((vat_deductible IS NULL) OR (vat_book = ANY (ARRAY['received'::text, 'investment'::text])))),
    CONSTRAINT journal_line_external_negative_side_check CHECK ((external_negative_side = ANY (ARRAY['debe'::text, 'haber'::text]))),
    CONSTRAINT journal_line_iva_completo CHECK ((((tax_rate_id IS NULL) AND (tax_base IS NULL) AND (vat_book IS NULL) AND (vat_deductible IS NULL)) OR ((tax_rate_id IS NOT NULL) AND (tax_base IS NOT NULL) AND (vat_book IS NOT NULL)))),
    CONSTRAINT journal_line_position_check CHECK (("position" > 0)),
    CONSTRAINT journal_line_retencion_completa CHECK ((((withholding_rate_id IS NULL) AND (withholding_base IS NULL) AND (withholding_model IS NULL) AND (withholding_period IS NULL)) OR ((withholding_rate_id IS NOT NULL) AND (withholding_base IS NOT NULL) AND (withholding_model IS NOT NULL) AND (withholding_period IS NULL)) OR ((withholding_rate_id IS NULL) AND (withholding_base IS NULL) AND (withholding_model IS NOT NULL) AND (withholding_period IS NOT NULL)))),
    CONSTRAINT journal_line_tax_documents_check CHECK ((tax_documents > 0)),
    CONSTRAINT journal_line_vat_book_check CHECK (((vat_book IS NULL) OR (vat_book = ANY (ARRAY['issued'::text, 'received'::text, 'investment'::text, 'not_subject'::text])))),
    CONSTRAINT journal_line_vat_deductible_check CHECK (((vat_deductible IS NULL) OR (vat_deductible = ANY (ARRAY['yes'::text, 'no'::text, 'prorrata'::text])))),
    CONSTRAINT journal_line_withholding_model_check CHECK (((withholding_model IS NULL) OR (withholding_model = ANY (ARRAY['111'::text, '115'::text, '123'::text])))),
    CONSTRAINT journal_line_withholding_period_check CHECK ((withholding_period ~ '^[0-9]{4}-([1-4]T|0[1-9]|1[0-2]|0A)$'::text))
);


--
-- Name: TABLE journal_line; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.journal_line IS 'C04. El apunte: una cuenta de la empresa (solo hojas), Debe o Haber (uno de los dos), local (o «común») y marca; el apunte de IVA lleva base, tipo y libro registro, y el de retención su tipo y modelo.';


--
-- Name: COLUMN journal_line.is_common; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_line.is_common IS 'C04. Gasto común (préstamos y poco más): sin local; el informe lo reparte con allocation_rule.';


--
-- Name: COLUMN journal_line.vat_book; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_line.vat_book IS 'C04. Libro registro del IVA: issued (expedidas), received (recibidas), investment (bienes de inversión), not_subject (no sujeta).';


--
-- Name: COLUMN journal_line.external_counterpart; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_line.external_counterpart IS 'Contrapartida tal como venía de Diez.';


--
-- Name: COLUMN journal_line.external_voucher; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_line.external_voucher IS 'Justificante tal como venía de Diez.';


--
-- Name: COLUMN journal_line.external_negative_side; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_line.external_negative_side IS 'Traída de Diez con importe NEGATIVO: en qué lado iba allí (debe o haber). Folvy la guarda en positivo al otro lado; Libros la marca «En Diez iba en negativo».';


--
-- Name: COLUMN journal_line.withholding_period; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.journal_line.withholding_period IS 'S01d. El periodo del modelo que paga, compensa o devuelve este apunte de la 4751 («2026-3T», «2026-01» o «2026-0A»), con withholding_model y sin withholding_rate_id. Nulo en la retención que nace.';


--
-- Name: journal_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.journal_ledger WITH (security_invoker='true') AS
 SELECT l.id AS line_id,
    l.account_id,
    l.company_id,
    l.entry_id,
    l."position",
    e.fiscal_year_id,
    e.series,
    e.number,
    e.entry_date,
    e.concept AS entry_concept,
    e.status,
    e.source_type,
    e.source_id,
    e.reverses_entry_id,
    e.voided_by_entry_id,
    e.external_program,
    e.external_series,
    e.external_number,
    l.company_account_id,
    a.code AS account_code,
    a.name AS account_name,
    a.template_code,
    l.debit,
    l.credit,
    COALESCE(l.concept, e.concept) AS concept,
    l.location_id,
    l.is_common,
    l.brand_id,
    COALESCE(l.party_id, e.party_id) AS party_id,
    COALESCE(l.document_ref, e.document_ref) AS document_ref,
    COALESCE(l.document_date, e.document_date) AS document_date,
    l.tax_rate_id,
    l.tax_base,
    l.vat_book,
    l.vat_deductible,
    l.withholding_rate_id,
    l.withholding_base,
    l.withholding_model
   FROM ((public.journal_line l
     JOIN public.journal_entry e ON ((e.id = l.entry_id)))
     JOIN public.company_account a ON ((a.id = l.company_account_id)))
  WHERE (e.status = ANY (ARRAY['validado'::text, 'anulado'::text]));


--
-- Name: VIEW journal_ledger; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.journal_ledger IS 'C04. El Mayor: cada apunte de un asiento validado (o anulado: su contraasiento lo compensa), con su cuenta. Con la RLS de quien lee.';


