-- Name: kitchen_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.kitchen_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    indirect_cost_pct_default numeric DEFAULT 0 NOT NULL,
    target_food_cost_pct numeric,
    currency text DEFAULT 'EUR'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    audit_threshold_default numeric DEFAULT 0.70 NOT NULL,
    audit_mode_default text DEFAULT 'shadow'::text NOT NULL,
    audit_shadow_min_samples integer DEFAULT 14 NOT NULL,
    photo_retention_days integer DEFAULT 180 NOT NULL,
    transcription_language text DEFAULT 'es-ES'::text NOT NULL,
    ai_default_model text DEFAULT 'haiku'::text NOT NULL,
    ai_escalation_enabled boolean DEFAULT true NOT NULL,
    version_alert_pct numeric DEFAULT 10 NOT NULL,
    cost_window_days_default integer DEFAULT 30 NOT NULL,
    allow_negative_yield boolean DEFAULT false NOT NULL,
    max_recipe_depth_warning integer DEFAULT 4 NOT NULL,
    price_rounding text DEFAULT 'none'::text NOT NULL,
    labor_target_pct numeric,
    cost_strategy_default text DEFAULT 'avg_window'::text NOT NULL,
    reliability_min_pct numeric DEFAULT 90 NOT NULL,
    target_plate_cost_pct numeric,
    CONSTRAINT kitchen_settings_audit_mode_default_check CHECK ((audit_mode_default = ANY (ARRAY['shadow'::text, 'notify_manager'::text, 'notify_cook'::text]))),
    CONSTRAINT kitchen_settings_cost_strategy_default_check CHECK ((cost_strategy_default = ANY (ARRAY['average_weighted'::text, 'last_purchase'::text, 'fixed'::text]))),
    CONSTRAINT kitchen_settings_cost_window_days_default_range CHECK (((cost_window_days_default >= 7) AND (cost_window_days_default <= 365))),
    CONSTRAINT kitchen_settings_indirect_range CHECK (((indirect_cost_pct_default >= (0)::numeric) AND (indirect_cost_pct_default <= (100)::numeric))),
    CONSTRAINT kitchen_settings_price_rounding_check CHECK ((price_rounding = ANY (ARRAY['none'::text, 'psychological_99'::text, 'half_euro'::text, 'whole_euro'::text]))),
    CONSTRAINT kitchen_settings_target_range CHECK (((target_food_cost_pct IS NULL) OR ((target_food_cost_pct > (0)::numeric) AND (target_food_cost_pct <= (100)::numeric))))
);


--
-- Name: COLUMN kitchen_settings.cost_window_days_default; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_settings.cost_window_days_default IS 'Días de compras que entran en el coste medio ponderado (average_weighted). LA ventana de la cuenta: la lee _article_weighted_cost y nadie más.';


--
-- Name: COLUMN kitchen_settings.reliability_min_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_settings.reliability_min_pct IS 'Umbral mínimo de fiabilidad del casado (% casado por importe sobre total). Por debajo, la señal sales_mapping_reliability se pinta ámbar/rojo. Defecto 90.';


--
