    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    pase_activo boolean DEFAULT false NOT NULL,
    pase_activo_at timestamp with time zone,
    pase_activo_por uuid,
    pase_activo_desde text,
    pase_apagado_motivo text,
    CONSTRAINT kitchen_station_kind_valid CHECK ((kind = ANY (ARRAY['prep'::text, 'expo'::text]))),
    CONSTRAINT kitchen_station_pase_desde_ck CHECK (((pase_activo_desde IS NULL) OR (pase_activo_desde = ANY (ARRAY['pantalla'::text, 'tablet'::text])))),
    CONSTRAINT kitchen_station_pase_solo_en_expo_ck CHECK (((pase_activo = false) OR (kind = 'expo'::text)))
);


--
-- Name: COLUMN kitchen_station.pase_activo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_station.pase_activo IS 'El Pase, por ESTACIÓN. Sólo tiene sentido en kind = expo, y hay un CHECK que lo impide en el resto: ignorarlo daría una pantalla que dice «encendido» y no enciende nada (regla 8).';


--
-- Name: kitchen_time_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.kitchen_time_config (
    location_id uuid NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    green_max_minutes integer DEFAULT 15 NOT NULL,
    amber_max_minutes integer DEFAULT 25 NOT NULL,
    ceiling_minutes integer DEFAULT 30 NOT NULL,
    floor_minutes integer DEFAULT 3 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    bag_on_ready boolean DEFAULT false NOT NULL,
    bag_qr boolean DEFAULT false NOT NULL,
    pase_activo boolean DEFAULT false NOT NULL,
    pase_activo_at timestamp with time zone,
    pase_activo_por uuid,
    pase_activo_desde text,
    pase_apagado_motivo text,
    CONSTRAINT kitchen_time_config_pase_desde_ck CHECK (((pase_activo_desde IS NULL) OR (pase_activo_desde = ANY (ARRAY['pantalla'::text, 'tablet'::text])))),
    CONSTRAINT kitchen_time_config_tramos_coherentes CHECK (((floor_minutes >= 0) AND (floor_minutes < green_max_minutes) AND (green_max_minutes < amber_max_minutes) AND (amber_max_minutes <= ceiling_minutes)))
);


--
-- Name: COLUMN kitchen_time_config.bag_on_ready; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_time_config.bag_on_ready IS 'true = el ticket de BOLSA se imprime al pulsar "Listo" (no al entrar el pedido). Palanca de adopción del KPI. Apagar = vuelve al comportamiento clásico al instante.';


--
-- Name: COLUMN kitchen_time_config.bag_qr; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_time_config.bag_qr IS 'Ticket de bolsa: imprimir QR con el sale_id (asociación pedido↔cámara del frente de visión). Off por defecto; se enciende con un UPDATE, sin APK.';


--
-- Name: COLUMN kitchen_time_config.pase_activo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_time_config.pase_activo IS 'El Pase, por local. Apagado = todo exactamente como antes del 14/09: vuelve «Pedidos» y vuelve la estación expo al tablero. Se enciende desde Ajustes, sin desplegar. Orden de encendido: Alcalá primero (dos tablets con papeles separados), Carabanchel después (una sola tablet lo hace todo).';


--
-- Name: COLUMN kitchen_time_config.pase_activo_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_time_config.pase_activo_at IS 'Cuándo cambió `pase_activo` por última vez. NULL = nunca desde que hay traza.';


--
-- Name: COLUMN kitchen_time_config.pase_activo_por; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_time_config.pase_activo_por IS 'Quién: el usuario si se encendió desde la pantalla, el APARATO (kds_device.id) si se apagó desde la tablet. Cuál de los dos lo dice `pase_activo_desde`.';


--
-- Name: COLUMN kitchen_time_config.pase_activo_desde; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_time_config.pase_activo_desde IS '«pantalla» o «tablet». Sin esto, `pase_activo_por` es un uuid sin contexto.';


--
-- Name: COLUMN kitchen_time_config.pase_apagado_motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.kitchen_time_config.pase_apagado_motivo IS 'Lo que escriba quien apaga, si escribe algo. NUNCA obligatorio: quien está apagando tiene un problema encima; se le pregunta después, no antes.';


