--
-- Name: licensed_settlement; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.licensed_settlement (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid,
    settlement_ref text,
    period_from date NOT NULL,
    period_to date NOT NULL,
    period_grain text DEFAULT 'month'::text,
    service_revenue numeric DEFAULT 0,
    materials_supplied numeric DEFAULT 0,
    stock_invoice_cost numeric DEFAULT 0,
    food_cost numeric DEFAULT 0,
    packaging_cost numeric DEFAULT 0,
    net_settlement numeric DEFAULT 0,
    source text DEFAULT 'ctb_settlement'::text,
    import_key text,
    raw jsonb,
    created_at timestamp with time zone DEFAULT now(),
    formula text DEFAULT 'anterior'::text NOT NULL,
    party_id uuid,
    status text,
    purchases_amount numeric(12,2),
    contributions_amount numeric(12,2),
    brand_sales_base numeric(12,2),
    commission_pct numeric(5,2),
    commission_amount numeric(12,2),
    amount numeric(12,2),
    detail jsonb,
    updated_at timestamp with time zone,
    created_by uuid,
    created_by_name text,
    confirmed_at timestamp with time zone,
    confirmed_by uuid,
    confirmed_by_name text,
    journal_entry_id uuid,
    company_id uuid,
    supplier_id uuid,
    received_invoice_id uuid,
    CONSTRAINT licensed_settlement_confirmada_con_quien CHECK (((status IS NULL) OR (status = 'borrador'::text) OR (confirmed_at IS NOT NULL))),
    CONSTRAINT licensed_settlement_formula_check CHECK ((formula = ANY (ARRAY['anterior'::text, 'compras_aportaciones_comision'::text, 'documentos'::text]))),
    CONSTRAINT licensed_settlement_nueva_completa CHECK (((formula = 'anterior'::text) OR ((formula = 'documentos'::text) AND (party_id IS NOT NULL) AND (location_id IS NOT NULL) AND (company_id IS NOT NULL) AND (supplier_id IS NOT NULL) AND (status IS NOT NULL) AND (settlement_ref IS NOT NULL)) OR ((party_id IS NOT NULL) AND (location_id IS NOT NULL) AND (status IS NOT NULL) AND (purchases_amount IS NOT NULL) AND (contributions_amount IS NOT NULL) AND (brand_sales_base IS NOT NULL) AND (commission_pct IS NOT NULL) AND (commission_amount IS NOT NULL) AND (amount IS NOT NULL)))),
    CONSTRAINT licensed_settlement_status_check CHECK (((status IS NULL) OR (status = ANY (ARRAY['borrador'::text, 'confirmada'::text, 'saldada'::text]))))
);


--
-- Name: COLUMN licensed_settlement.formula; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.licensed_settlement.formula IS 'C03. anterior = las de junio de 2026 (ingresos por servicio − materiales − …), conservadas sin recalcular. compras_aportaciones_comision = la de Julio, por local y periodo.';


--
-- Name: COLUMN licensed_settlement.amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.licensed_settlement.amount IS 'C03. compras − aportaciones + comisión. Positivo: a favor del socio (se le paga); negativo: a tu favor.';


--
-- Name: COLUMN licensed_settlement.detail; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.licensed_settlement.detail IS 'C03. De dónde sale cada línea: albaranes, aportaciones y ventas por marca, con sus ids.';


--
-- Name: COLUMN licensed_settlement.journal_entry_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.licensed_settlement.journal_entry_id IS 'C04. El asiento de la liquidación mensual del socio: compensación de sus cuentas y la comisión como ingreso (705).';


--
-- Name: COLUMN licensed_settlement.received_invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.licensed_settlement.received_invoice_id IS 'Compras (10/10). Su factura de la liquidación, registrada como factura recibida al confirmar.';


