    is_billable boolean DEFAULT true NOT NULL,
    clock_radius_m integer DEFAULT 200 NOT NULL,
    clock_geofence_mode text DEFAULT 'warn'::text NOT NULL,
    receipt_approval text DEFAULT 'trabajador'::text NOT NULL,
    dispatch_mode text DEFAULT 'auto'::text NOT NULL,
    dispatch_broker text DEFAULT 'catcher'::text NOT NULL,
    glovo_pos_hint text,
    city text,
    customer_notify_enabled boolean DEFAULT false NOT NULL,
