    assignment_strategy text DEFAULT 'broadcast'::text NOT NULL,
    offer_timeout_s integer DEFAULT 60 NOT NULL,
    availability_auto_mode text DEFAULT 'manual'::text NOT NULL,
    availability_other_integrators text[] DEFAULT '{}'::text[] NOT NULL,
