    CONSTRAINT locations_assignment_strategy_check CHECK ((assignment_strategy = ANY (ARRAY['broadcast'::text, 'nearest'::text]))),
    CONSTRAINT locations_availability_auto_mode_check CHECK ((availability_auto_mode = ANY (ARRAY['auto'::text, 'manual'::text]))),
    CONSTRAINT locations_clock_geofence_mode_chk CHECK ((clock_geofence_mode = ANY (ARRAY['block'::text, 'warn'::text]))),
    CONSTRAINT locations_dispatch_broker_check CHECK ((dispatch_broker = ANY (ARRAY['catcher'::text, 'jelp'::text, 'uber_direct'::text, 'shipday'::text]))),
    CONSTRAINT locations_dispatch_mode_check CHECK ((dispatch_mode = ANY (ARRAY['auto'::text, 'manual'::text, 'off'::text]))),
    CONSTRAINT locations_hubrise_status_mode_check CHECK ((hubrise_status_mode = ANY (ARRAY['normal'::text, 'busy'::text, 'paused'::text]))),
    CONSTRAINT locations_receipt_approval_check CHECK ((receipt_approval = ANY (ARRAY['trabajador'::text, 'oficina'::text])))
);


--
-- Name: COLUMN locations.hours_balance_close_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.locations.hours_balance_close_day IS 'Día del mes en que se cierra el periodo de bolsa de horas (1-31). El periodo va del día siguiente al día actual del mes siguiente.';


--
-- Name: COLUMN locations.hours_balance_sync_with_gestoria; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.locations.hours_balance_sync_with_gestoria IS 'Si true, el día de cierre sincroniza con la fecha de envío a gestoría. Si false, usa el día configurado en hours_balance_close_day.';


--
-- Name: COLUMN locations.availability_auto_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.locations.availability_auto_mode IS 'auto|manual — interruptor para el futuro auto-86 por stock (el gatillo real es otro frente, fuera de este encargo). manual = comportamiento actual (nadie auto-86a solo).';


--
-- Name: COLUMN locations.availability_other_integrators; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.locations.availability_other_integrators IS 'Otros integradores de pedidos que usa este local además de Folvy (ej. last, otter, deliverect). Folvy NO escribe en ellos; set_product_availability(_by_token) los usa solo para avisar al operario que los desconecte a mano al hacer un 86.';


--
-- Name: COLUMN locations.hubrise_status_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.locations.hubrise_status_mode IS 'normal|busy|paused — estado de aceptación de pedidos del local en HubRise (Cap. C). NO confundir con order_acceptance_config (auto-aceptación por canal×marca).';


--
-- Name: COLUMN locations.hubrise_status_resume_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.locations.hubrise_status_resume_at IS 'Reapertura programada (HubRise reabre solo al llegar esta hora). NULL = indefinido o normal.';


