    CONSTRAINT platform_audit_log_event_type_valid CHECK ((event_type = ANY (ARRAY['account_created'::text, 'account_suspended'::text, 'account_unsuspended'::text, 'account_archived'::text, 'account_unarchived'::text, 'account_deleted'::text, 'account_restored'::text, 'account_status_changed'::text, 'account_modules_changed'::text, 'impersonation_started'::text, 'impersonation_ended'::text, 'admin_created'::text, 'admin_suspended'::text, 'admin_reactivated'::text, 'admin_role_changed'::text, 'admin_2fa_reset'::text, 'admin_permissions_changed'::text, 'seed_data_modified'::text, 'system_config_changed'::text, 'global_notification_sent'::text, 'permission_set_modified'::text, 'account_feature_changed'::text])))
);


