--
-- Name: platform_promo_floor; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_promo_floor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    channel_id uuid NOT NULL,
    menu_item_id uuid NOT NULL,
    floor_pct numeric,
    floor_price numeric,
    ref_price numeric,
    source text DEFAULT 'glovo_portal'::text NOT NULL,
    window_days integer DEFAULT 35 NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    note text,
    CONSTRAINT platform_promo_floor_floor_pct_check CHECK (((floor_pct IS NULL) OR ((floor_pct >= (0)::numeric) AND (floor_pct <= (95)::numeric)))),
    CONSTRAINT platform_promo_floor_source_check CHECK ((source = ANY (ARRAY['glovo_portal'::text, 'reconstructed'::text, 'manual'::text])))
);


--
-- Name: TABLE platform_promo_floor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_promo_floor IS 'Suelo de precio de 35 días por artículo×canal (regla del 5% de Glovo). Lo alimenta el robot (Capa 1) leyendo el tooltip real de Glovo; el offers-agent (Capa 2) lo lee para no proponer descuentos que la plataforma rechaza.';


--
-- Name: platform_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_settings (
    key text NOT NULL,
    value jsonb NOT NULL,
    description text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT platform_settings_key_format CHECK (((key ~* '^[a-z][a-z0-9_]*$'::text) AND ((length(key) >= 3) AND (length(key) <= 100)))),
    CONSTRAINT platform_settings_value_not_null_jsonb CHECK (((value IS NOT NULL) AND (jsonb_typeof(value) IS NOT NULL)))
);


--
-- Name: TABLE platform_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_settings IS 'Configuración global de la plataforma Folvy. Key-value con value jsonb flexible.';


--
-- Name: COLUMN platform_settings.key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_settings.key IS 'Clave única del setting. Formato snake_case: solo letras minúsculas, números, underscores. 3-100 chars.';


--
-- Name: COLUMN platform_settings.value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_settings.value IS 'Valor del setting en jsonb. Puede ser string, number, boolean, object, array.';


--
-- Name: COLUMN platform_settings.description; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_settings.description IS 'Descripción humana del setting.';


--
-- Name: COLUMN platform_settings.updated_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_settings.updated_by IS 'auth.users.id del platform_admin que modificó este setting por última vez. NULL si lo creó seed.';


--
-- Name: platform_store; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_store (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    provider text NOT NULL,
    external_text text NOT NULL,
    external_id text,
    channel_id uuid,
    brand_id uuid,
    location_id uuid,
    treasury_account_id uuid,
    party_id uuid,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_name text,
    updated_at timestamp with time zone,
    updated_by uuid,
    updated_by_name text,
    CONSTRAINT platform_store_external_text_check CHECK ((btrim(external_text) <> ''::text)),
    CONSTRAINT platform_store_provider_check CHECK ((provider = ANY (ARRAY['uber'::text, 'glovo'::text, 'justeat'::text, 'ctb'::text, 'catcher'::text])))
);


--
-- Name: TABLE platform_store; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_store IS 'D01 · El mapa de tiendas de las plataformas: cómo nombra cada una (Uber, Glovo, Just Eat, CTB, Catcher) a cada marca × local → la marca, el local, el canal y la cuenta del banco donde paga. Una tienda nueva entra sin asignar: su marca y su local los da una persona.';


--
-- Name: platform_store_alias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_store_alias (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    store_id uuid NOT NULL,
    provider text NOT NULL,
    texto text NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_store_alias_texto_check CHECK ((btrim(texto) <> ''::text))
);


--
-- Name: TABLE platform_store_alias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_store_alias IS 'V02 · E2. Cada nombre con el que una plataforma ha llamado a una tienda («Marca (dirección)»). Sirve para reconocer lo que no trae el ID de la tienda (el correo de Uber o el de Just Eat). La identidad de la tienda es su ID (platform_store.external_id), nunca su nombre.';


--
-- Name: platform_store_cambio; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_store_cambio (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    store_id uuid NOT NULL,
    kind text NOT NULL,
    antes text,
    ahora text NOT NULL,
    propuesta jsonb DEFAULT '{}'::jsonb NOT NULL,
    settlement_id uuid,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decision text,
    decided_by uuid,
    decided_by_name text,
    CONSTRAINT platform_store_cambio_check CHECK (((decided_at IS NULL) = (decision IS NULL))),
    CONSTRAINT platform_store_cambio_decision_check CHECK (((decision IS NULL) OR (decision = ANY (ARRAY['confirmado'::text, 'descartado'::text])))),
    CONSTRAINT platform_store_cambio_kind_check CHECK ((kind = ANY (ARRAY['nombre'::text, 'direccion'::text])))
);


--
-- Name: TABLE platform_store_cambio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_store_cambio IS 'V02 · E2. Una tienda (la misma por su ID) que llega con otro nombre o en otra dirección. Sumied no la reasigna sola: propone la marca y el local y una persona lo confirma (conta_tienda_cambio_decidir). Lo de antes no se mueve.';


--
-- Name: platform_store_tramo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_store_tramo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    store_id uuid NOT NULL,
    brand_id uuid,
    location_id uuid,
    valid_from date,
    valid_to date,
    motivo text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_name text,
    CONSTRAINT platform_store_tramo_check CHECK (((valid_from IS NULL) OR (valid_to IS NULL) OR (valid_to >= valid_from)))
);


--
-- Name: TABLE platform_store_tramo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_store_tramo IS 'V02 · E2. La marca y el local de una tienda de plataforma, por tramos de fechas (vacío: desde siempre / hasta hoy). Lo vendido un día es de la marca y el local del tramo de ese día; un cambio abre un tramo nuevo y lo de antes no se mueve. platform_store guarda el de hoy.';


--
-- Name: pos_ticket_counter; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pos_ticket_counter (
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    business_date date NOT NULL,
    last_number integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: postal_code_place; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.postal_code_place (
    postal_code text NOT NULL,
    ord integer NOT NULL,
    place_name text NOT NULL,
    community text,
    province text,
    municipality text,
    municipality_code text,
    source_key text DEFAULT 'geonames-cp-es'::text NOT NULL,
    CONSTRAINT postal_code_place_postal_code_check CHECK ((postal_code ~ '^[0-9]{5}$'::text))
);


--
-- Name: TABLE postal_code_place; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.postal_code_place IS 'C00 R4. Código postal → población, de GeoNames (CC BY 4.0). Varias filas por código si tiene varias poblaciones; ord es el orden del fichero.';


--
-- Name: price_operation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.price_operation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    kind text NOT NULL,
    actor uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    scope jsonb NOT NULL,
    entries_count integer NOT NULL,
    writes_count integer NOT NULL,
    reverted_operation_id uuid,
    note text,
    CONSTRAINT price_operation_kind_check CHECK ((kind = ANY (ARRAY['bulk_price'::text, 'revert'::text]))),
    CONSTRAINT price_operation_revert_chk CHECK ((((kind = 'revert'::text) AND (reverted_operation_id IS NOT NULL)) OR ((kind <> 'revert'::text) AND (reverted_operation_id IS NULL))))
);


--
-- Name: TABLE price_operation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.price_operation IS 'Una operacion de precios en lote (o su reverso). El id ES el operation_id que estampa menu_item_override_history.';


--
-- Name: COLUMN price_operation.scope; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.price_operation.scope IS 'Lo que el usuario eligio, tal cual, para que un humano entienda la fila seis meses despues. NO se usa para recalcular nada.';


--
-- Name: COLUMN price_operation.writes_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.price_operation.writes_count IS 'Filas que cambiaron DE VERDAD (las que registro el trigger). Reguardar el mismo precio cuenta como entrada, no como escritura.';


--
-- Name: print_job; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.print_job (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    printer_id uuid,
    sale_id uuid,
    doc_type text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    source text DEFAULT 'auto'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    done_at timestamp with time zone,
    CONSTRAINT print_job_doc_type_check CHECK ((doc_type = ANY (ARRAY['bag'::text, 'kitchen'::text, 'labels'::text]))),
    CONSTRAINT print_job_source_check CHECK ((source = ANY (ARRAY['auto'::text, 'manual'::text, 'reprint'::text]))),
    CONSTRAINT print_job_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'done'::text, 'error'::text, 'cancelled'::text])))
);


--
-- Name: TABLE print_job; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.print_job IS 'Cola de impresión. payload = documento renderizado (inmutable). El adaptador del transporte lo recoge.';


--
-- Name: print_route_failure_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.print_route_failure_log (
    id bigint NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    sale_id uuid,
    doc_type text,
    detail text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE print_route_failure_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.print_route_failure_log IS 'RLS deny-all intencional. Rastro de "pedido aceptado sin impresora activa" (fix/limpieza-kds-viejo-y-prevencion, 11/08). La crea tambien la 0904 con if not exists para que el orden entre 0902 y 0904 no importe.';


--
-- Name: print_route_failure_log_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.print_route_failure_log ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.print_route_failure_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: printer; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.printer (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    name text NOT NULL,
    transport text NOT NULL,
    doc_types text[] DEFAULT ARRAY['bag'::text, 'kitchen'::text, 'labels'::text] NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    copies integer DEFAULT 1 NOT NULL,
    CONSTRAINT printer_copies_chk CHECK (((copies >= 1) AND (copies <= 9))),
    CONSTRAINT printer_transport_check CHECK ((transport = ANY (ARRAY['sunmi_cloud'::text, 'escpos_network'::text, 'epson_epos'::text, 'bluetooth'::text, 'browser_pdf'::text])))
);


--
-- Name: TABLE printer; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.printer IS 'Impresora física. transport define el adaptador; config jsonb lleva lo específico del transporte.';


--
-- Name: COLUMN printer.copies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.printer.copies IS 'Nº de copias por documento que saca esta impresora (1-9).';


--
