    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    target_kind text DEFAULT 'product'::text NOT NULL,
    CONSTRAINT product_availability_identity_chk CHECK (((external_id IS NOT NULL) OR (recipe_item_id IS NOT NULL))),
    CONSTRAINT product_availability_reason_check CHECK ((reason = ANY (ARRAY['manual'::text, 'stock_out'::text, 'schedule'::text]))),
    CONSTRAINT product_availability_target_kind_chk CHECK ((target_kind = ANY (ARRAY['product'::text, 'modifier_option'::text])))
);


--
-- Name: COLUMN product_availability.target_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_availability.target_kind IS 'product -> se empuja como sku_ref · modifier_option -> como option_ref. Mismo anclaje external_id + location_id para los dos.';


