    needs_review boolean DEFAULT false NOT NULL,
    notes text,
    is_active boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    CONSTRAINT purchase_source_check CHECK ((source = ANY (ARRAY['ocr_invoice'::text, 'manual'::text]))),
    CONSTRAINT purchase_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'confirmed'::text])))
);


--
-- Name: purchase_bill_to; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_bill_to (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    name_norm text NOT NULL,
    example text,
    company_id uuid,
    supplier_id uuid,
    is_other boolean DEFAULT false NOT NULL,
    decided_by uuid,
    decided_by_name text,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT purchase_bill_to_uno CHECK (((num_nonnulls(company_id, supplier_id) +
CASE
    WHEN is_other THEN 1
    ELSE 0
END) = 1))
);


--
-- Name: TABLE purchase_bill_to; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.purchase_bill_to IS 'Compras (10/10). Lo que una persona contestó a «¿a nombre de quién va este papel?»: el nombre normalizado (compras_nombre_norm) va a una empresa de la cuenta, a un proveedor (el que liquida) o a otro. Vale para todos los papeles con ese nombre.';


