--
-- Name: sale_capture; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_capture (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    device_id uuid,
    kind text DEFAULT 'pase'::text NOT NULL,
    captured_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    image_path text NOT NULL,
    width integer,
    height integer,
    bytes integer,
    sha256 text,
    purged_at timestamp with time zone,
    hold_until timestamp with time zone,
    CONSTRAINT sale_capture_kind_ck CHECK ((kind = ANY (ARRAY['pase'::text, 'bolsa'::text, 'degradado'::text])))
);


--
-- Name: TABLE sale_capture; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sale_capture IS 'C9 L2: la foto del pase atada a un pedido. Escribe SOLO order-evidence-capture con service_role. Sin PII: el nombre del cliente ya va impreso en la etiqueta que sale en la foto, no se duplica aqui.';


--
-- Name: COLUMN sale_capture.captured_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_capture.captured_at IS 'Hora del DISPOSITIVO. Si difiere de received_at es que la foto se subio en diferido desde la cola local: la captura es contabilidad, no operacion, y el «Listo» nunca espera a la red.';


--
-- Name: COLUMN sale_capture.sha256; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_capture.sha256 IS 'Integridad. La foto que se presenta en una reclamacion tiene que ser demostrablemente la que se hizo.';


--
-- Name: COLUMN sale_capture.purged_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_capture.purged_at IS 'Cuando la purga borro el objeto del bucket. La fila se conserva como recibo de que existio y de que se borro.';


--
-- Name: COLUMN sale_capture.hold_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_capture.hold_until IS 'C9 L2 §5: una foto adjunta a una reclamacion ABIERTA (L4) no se purga hasta que la reclamacion se cierre. La purga respeta esta fecha.';


--
-- Name: sale_consumption_failure; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_consumption_failure (
    sale_id uuid NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid,
    sqlstate text,
    message text NOT NULL,
    first_failed_at timestamp with time zone DEFAULT now() NOT NULL,
    last_failed_at timestamp with time zone DEFAULT now() NOT NULL,
    attempts integer DEFAULT 1 NOT NULL,
    resolved_at timestamp with time zone,
    resolved_movements integer
);


--
-- Name: TABLE sale_consumption_failure; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sale_consumption_failure IS 'Ventas cuyo consumo de almacen fallo. Una fila por venta; se marca resuelta cuando el consumo vuelve a escribirse. 11/09/2026: antes esto era un raise warning que no leia nadie.';


--
-- Name: sale_consumption_skip; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_consumption_skip (
    account_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    recipe_item_id uuid NOT NULL,
    location_id uuid,
    fecha_venta timestamp with time zone NOT NULL,
    corte timestamp with time zone,
    motivo text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE sale_consumption_skip; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sale_consumption_skip IS 'Lo que el corte del recuento protegio: ingredientes de una venta que NO se reescriben porque un recuento aprobado posterior ya los cuadro. Es el informe de por que no se toco, no un fallo.';


--
-- Name: COLUMN sale_consumption_skip.corte; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_consumption_skip.corte IS 'El corte que protegio al ingrediente, si lo hubo. NULO cuando el motivo no es un corte sino un precio indefendible: un ingrediente sin recuento no tiene corte y la nota tiene que poder escribirse igual.';


--
-- Name: sale_fire; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_fire (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    fire_number integer NOT NULL,
    fired_at timestamp with time zone DEFAULT now() NOT NULL,
    fired_by uuid,
    fired_by_name text,
    device_id uuid,
    origin_fire_id uuid,
    origin_table_name text,
    CONSTRAINT sale_fire_fire_number_check CHECK ((fire_number >= 1))
);


--
-- Name: sale_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_line (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    raw_text text NOT NULL,
    product_name text NOT NULL,
    quantity numeric DEFAULT 1 NOT NULL,
    unit_price numeric,
    menu_item_id uuid,
    map_source text DEFAULT 'unmapped'::text NOT NULL,
    map_confidence numeric,
    map_needs_review boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    line_total numeric,
    parent_sale_line_id uuid,
    line_type text DEFAULT 'product'::text NOT NULL,
    modifier_option_id uuid,
    combo_slot_id uuid,
    unmapped_reason text,
    computed_cost numeric,
    cost_computed_at timestamp with time zone,
    external_source text,
    external_product_id text,
    external_brand_id text,
    ignore_reason text,
    ignored_at timestamp with time zone,
    original_unit_price numeric,
    discount_label text,
    kitchen_note text,
    fire_id uuid,
    voided_at timestamp with time zone,
    CONSTRAINT sale_line_line_type_check CHECK ((line_type = ANY (ARRAY['product'::text, 'modifier'::text, 'combo_item'::text]))),
    CONSTRAINT sale_line_map_confidence_range CHECK (((map_confidence IS NULL) OR ((map_confidence >= (0)::numeric) AND (map_confidence <= (1)::numeric)))),
    CONSTRAINT sale_line_map_source_valid CHECK ((map_source = ANY (ARRAY['unmapped'::text, 'manual'::text, 'ai'::text, 'fuzzy'::text, 'pos'::text]))),
    CONSTRAINT sale_line_qty_positive CHECK ((quantity > (0)::numeric)),
    CONSTRAINT sale_line_unmapped_reason_valid CHECK (((unmapped_reason IS NULL) OR (unmapped_reason = ANY (ARRAY['no_brand'::text, 'no_recipe'::text, 'no_menu_item'::text, 'ambiguous'::text, 'ignored'::text, 'delisted'::text, 'extra_desconocido'::text]))))
);


--
-- Name: COLUMN sale_line.unit_price; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_line.unit_price IS 'Precio UNITARIO real (por unidad). Corregido 2026-05-29: antes contenía el total de línea.';


--
-- Name: COLUMN sale_line.line_total; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_line.line_total IS 'Total de la línea (precio unitario × quantity). Fuente original de Last.app.';


--
-- Name: COLUMN sale_line.unmapped_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_line.unmapped_reason IS 'Razón del no-casado (subsistema de fiabilidad). NULL = casada o sin clasificar. no_brand|no_recipe|no_menu_item|ambiguous = automáticas en ingesta/recasado; ignored|delisted = decisión humana en revisión. Ortogonal a map_source.';


--
-- Name: COLUMN sale_line.ignore_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_line.ignore_reason IS 'Motivo corto (texto libre) por el que la línea se marcó como ignorada. NULL si no se ignoró.';


--
-- Name: COLUMN sale_line.ignored_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_line.ignored_at IS 'Momento en que la línea se marcó como ignorada/descatalogada. NULL si no se ignoró.';


--
-- Name: COLUMN sale_line.kitchen_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_line.kitchen_note IS 'TPV T1: nota de cocina por línea (p.ej. "sin cebolla", "poco hecho"). Se imprime en la comanda y se muestra en KDS junto a la línea.';


--
-- Name: sale_line_consumo_esperado; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_line_consumo_esperado (
    account_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    sale_line_id uuid NOT NULL,
    recipe_item_id uuid NOT NULL,
    location_id uuid,
