    fecha_venta timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: sale_line_recast_frio; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_line_recast_frio (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    sale_line_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    sold_at timestamp with time zone NOT NULL,
    menu_item_id uuid NOT NULL,
    via text NOT NULL,
    nombre_en_venta text,
    external_id text,
    line_total numeric,
    motivo_anterior text,
    corte_vigente timestamp with time zone,
    bajo_corte boolean NOT NULL,
    recasado_en timestamp with time zone DEFAULT now() NOT NULL,
    recasado_por text,
    CONSTRAINT sale_line_recast_frio_via_check CHECK ((via = ANY (ARRAY['id'::text, 'nombre'::text])))
);


--
-- Name: TABLE sale_line_recast_frio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sale_line_recast_frio IS 'Lineas casadas hacia atras SIN generar consumo (22/09/2026, decision de Julio). Una fila aqui significa: esta linea tiene menu_item_id y NO tiene movimiento de stock, a proposito. El vigia del 100 % la lee para no contarla como rota.';


--
-- Name: sale_line_void; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_line_void (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    sale_line_id uuid NOT NULL,
    reason_id uuid,
    reason_label text NOT NULL,
    note text,
    original_quantity numeric NOT NULL,
    original_line_total numeric NOT NULL,
    voided_at timestamp with time zone DEFAULT now() NOT NULL,
    voided_by uuid,
    voided_by_name text,
    device_id uuid
);


--
-- Name: sale_table_move; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_table_move (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    kind text NOT NULL,
    from_sale_id uuid NOT NULL,
    to_sale_id uuid NOT NULL,
    from_table_id uuid,
    to_table_id uuid,
    line_ids uuid[],
    covers_moved integer,
    amount_moved numeric,
    moved_at timestamp with time zone DEFAULT now() NOT NULL,
    moved_by uuid,
    moved_by_name text,
    device_id uuid,
    CONSTRAINT sale_table_move_kind_check CHECK ((kind = ANY (ARRAY['move'::text, 'merge'::text, 'lines'::text])))
);


--
-- Name: sale_verification; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sale_verification (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    device_id uuid,
    capture_id uuid,
    modo text DEFAULT 'sombra'::text NOT NULL,
    verificado_at timestamp with time zone DEFAULT now() NOT NULL,
    unidades_esperadas integer,
    unidades_leidas integer,
    completo boolean,
    faltantes jsonb,
    leidas_por_qr integer,
    leidas_por_texto integer,
    lector_ms integer,
    salio_igual boolean DEFAULT false NOT NULL,
    motivo_excepcion text,
    excepcion_por uuid,
    excepcion_por_nombre text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sale_verification_excepcion_ck CHECK (((salio_igual IS FALSE) OR ((motivo_excepcion IS NOT NULL) AND (length(btrim(motivo_excepcion)) > 0)))),
    CONSTRAINT sale_verification_modo_ck CHECK ((modo = ANY (ARRAY['sombra'::text, 'puerta'::text, 'degradado'::text])))
);


--
-- Name: TABLE sale_verification; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sale_verification IS 'C9 L3: resultado de verificar el embolsado de un pedido. Nace inerte: no la escribe nadie hasta que exista el lector. La puerta NO bloquea el pedido, bloquea la afirmacion de que estaba completo.';


--
-- Name: COLUMN sale_verification.modo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_verification.modo IS 'sombra = se guarda y no se enseña (asi nace). puerta = decide si se habilita «Listo». degradado = sin etiquetas impresas, lista manual + foto; no prueba lo mismo y por eso se marca aparte.';


--
-- Name: COLUMN sale_verification.faltantes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_verification.faltantes IS 'CUALES faltan, no cuantas: «falta 1» no sirve en el pase, «falta la 3 de 7, Patatas» si.';


--
-- Name: COLUMN sale_verification.salio_igual; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sale_verification.salio_igual IS 'El pedido salio pese a estar incompleto. No es un caso raro: es el flujo normal cuando el operario firma la excepcion. Lo que queda escrito es que salio incompleto y quien lo firmo.';


--
-- Name: sales_channel; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_channel (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    channel_type text DEFAULT 'delivery'::text NOT NULL,
    color text,
    is_active boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sales_channel_channel_type_check CHECK ((channel_type = ANY (ARRAY['delivery'::text, 'dine_in'::text, 'takeaway'::text, 'catering'::text, 'other'::text])))
);


--
-- Name: TABLE sales_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_channel IS 'Canales de venta. Scope cuenta. Glovo, Uber Eats, Just Eat son los típicos para dark kitchen.';


--
-- Name: sales_day_close_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_day_close_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    location_id uuid,
    sales_day date NOT NULL,
    closed_through date NOT NULL,
    close_time time without time zone NOT NULL,
    order_code text,
    total numeric,
    order_status text,
    delivery_state text,
    closed_at timestamp with time zone DEFAULT now() NOT NULL,
    accion text,
    CONSTRAINT sales_day_close_log_accion CHECK (((accion IS NULL) OR (accion = ANY (ARRAY['revisar'::text, 'restaurado'::text, 'anulado'::text, 'cerrado_sin_confirmar'::text]))))
);


--
-- Name: TABLE sales_day_close_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_day_close_log IS 'Cierre del día: qué pedido se cerró como no confirmado, cuándo y con qué regla (hora de cierre). Lo escribe solo conta_cerrar_dias.';


--
-- Name: COLUMN sales_day_close_log.accion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_day_close_log.accion IS 'C11/C11b (23/10). NULL = anulado por el cierre del día (hasta el 23/10). anulado = cancelado en la plataforma, anulado al cierre. cerrado_sin_confirmar = cerrado como vendido al cierre sin confirmación de la plataforma. revisar = abierto al cierre y no es de plataforma: no se toca. restaurado = anulado por error y devuelto (C11).';


--
-- Name: sales_day_proposal_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_day_proposal_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    location_id uuid NOT NULL,
    sales_day date NOT NULL,
    result text NOT NULL,
    reason text,
    entry_id uuid,
    attempts integer DEFAULT 1 NOT NULL,
    first_at timestamp with time zone DEFAULT now() NOT NULL,
    last_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sales_day_proposal_log_result_check CHECK ((result = ANY (ARRAY['propuesto'::text, 'ya_estaba'::text, 'descartado'::text, 'sin_propuesta'::text, 'fallo'::text])))
);


--
-- Name: TABLE sales_day_proposal_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_day_proposal_log IS 'Cierre del día 2: lo último que hizo el cierre del día con las ventas de cada día y local (propuesto, ya estaba, descartado, sin propuesta y por qué, o fallo). Una fila por día y local; attempts cuenta las pasadas. Lo escribe solo conta_proponer_dias.';


--
-- Name: sales_history_daily; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_history_daily (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    location_id uuid NOT NULL,
    day date NOT NULL,
    scope text DEFAULT 'licensed'::text NOT NULL,
    orders integer DEFAULT 0 NOT NULL,
    dishes numeric DEFAULT 0 NOT NULL,
