    CONSTRAINT secret_expiry_check CHECK ((dias_critico <= dias_aviso)),
    CONSTRAINT secret_expiry_dias_aviso_check CHECK ((dias_aviso > 0)),
    CONSTRAINT secret_expiry_dias_critico_check CHECK ((dias_critico > 0))
);


--
-- Name: TABLE secret_expiry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.secret_expiry IS 'Fechas de caducidad de los secrets de los que dependen los vigias. Solo el NOMBRE y la fecha: ningun valor de token vive aqui. Al renovar, UPDATE de caduca_el -- no se toca ni se redespliega codigo.';


