-- Name: social_copy; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.social_copy (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid,
    pillar text NOT NULL,
    template text DEFAULT 'apetito'::text NOT NULL,
    text text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    weight integer DEFAULT 1 NOT NULL,
    lang text DEFAULT 'es'::text NOT NULL,
    times_used integer DEFAULT 0 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT social_copy_cedida_sin_marca CHECK (((pillar <> 'cedida'::text) OR (POSITION(('{marca}'::text) IN (text)) = 0))),
    CONSTRAINT social_copy_pct_solo_oferta CHECK (((pillar = 'oferta'::text) OR (POSITION(('{pct}'::text) IN (text)) = 0))),
    CONSTRAINT social_copy_pillar_check CHECK ((pillar = ANY (ARRAY['apetito'::text, 'curiosidad'::text, 'cedida'::text, 'evento_calor'::text, 'evento_lluvia'::text, 'evento_generico'::text, 'oferta'::text]))),
    CONSTRAINT social_copy_template_check CHECK ((template = ANY (ARRAY['apetito'::text, 'curiosidad'::text, 'oferta'::text]))),
    CONSTRAINT social_copy_weight_check CHECK ((weight >= 1))
);


