    CONSTRAINT social_post_network_check CHECK ((network = ANY (ARRAY['instagram'::text, 'tiktok'::text, 'facebook'::text]))),
    CONSTRAINT social_post_origin_check CHECK ((origin = ANY (ARRAY['agent'::text, 'manual'::text]))),
    CONSTRAINT social_post_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'scheduled'::text, 'publishing'::text, 'published'::text, 'discarded'::text, 'error'::text])))
);


--
-- Name: COLUMN social_post.ig_creation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.social_post.ig_creation_id IS 'Contenedor de Instagram ya creado y aun sin publicar. Vive 24 h. Si esta puesto, la pasada siguiente NO crea otro: pregunta por este. Se pone a NULL al publicar, y tambien cuando Instagram dice ERROR o EXPIRED.';


--
-- Name: COLUMN social_post.error_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.social_post.error_kind IS 'CLAVE, no frase (las frases viven en el front). esperando · llave_caducada · imagen_no_descargable · rechazado · otro. `esperando` NO es un fallo: la publicacion sigue en cola y no ha gastado intento.';


