    CONSTRAINT stock_waste_reason_valid CHECK ((reason_code = ANY (ARRAY['caducado'::text, 'mal_estado'::text, 'rotura'::text, 'sobreproduccion'::text, 'error_preparacion'::text, 'regalo'::text, 'consumo_personal'::text, 'devolucion_cliente'::text, 'otro'::text])))
);


--
-- Name: storage_area; Type: TABLE; Schema: public; Owner: -
