);


--
-- Name: supplier; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    name text NOT NULL,
    tax_id text,
    email text,
    phone text,
    address text,
    notes text,
    is_active boolean DEFAULT true NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    health_registry_no text,
    notify_group text,
    iva_incluido_en_linea boolean DEFAULT false NOT NULL,
    legal_name text,
    tax_id_type text,
    country_code text DEFAULT 'ES'::text NOT NULL,
    entity_kind text,
    tax_id_verified_at timestamp with time zone,
    tax_id_check_status text,
    tax_id_checked_at timestamp with time zone,
    fiscal_street text,
    fiscal_postal_code text,
    fiscal_city text,
    fiscal_province text,
    vat_regime text,
    usual_vat_rates numeric[] DEFAULT '{}'::numeric[] NOT NULL,
    irpf_withholding_pct numeric,
    expense_category_id uuid,
    default_location_id uuid,
    payment_method text,
    payment_terms_days integer,
    payment_fixed_days smallint[] DEFAULT '{}'::smallint[] NOT NULL,
    iban text,
    iban_verified_at timestamp with time zone,
    bank_name text,
    website text,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    bic text,
    sepa_mandate_ref text,
    sepa_mandate_date date,
    currency text DEFAULT 'EUR'::text NOT NULL,
    early_payment_discount_pct numeric,
    related_party_kind text,
    usual_tax_rate_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    invoicing_frequency text,
    iban_previous text,
    iban_changed_at timestamp with time zone,
    iban_changed_by uuid,
    iban_changed_by_name text,
    import_id uuid,
    invoicing_mode text,
    invoicing_per_location boolean,
    created_from text,
    iban_set_at timestamp with time zone,
    iban_set_by uuid,
    iban_set_by_name text,
    iban_unconfirmed_invoice_id uuid,
    data_from_invoice jsonb,
    invoice_arrival text,
    CONSTRAINT supplier_country_code_check CHECK ((country_code ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT supplier_created_from_check CHECK ((created_from = 'factura'::text)),
    CONSTRAINT supplier_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT supplier_early_discount_check CHECK (((early_payment_discount_pct IS NULL) OR ((early_payment_discount_pct >= (0)::numeric) AND (early_payment_discount_pct <= (100)::numeric)))),
    CONSTRAINT supplier_entity_kind_check CHECK (((entity_kind IS NULL) OR (entity_kind = ANY (ARRAY['company'::text, 'self_employed'::text])))),
    CONSTRAINT supplier_iban_format_check CHECK (((iban IS NULL) OR (iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$'::text))),
    CONSTRAINT supplier_invoice_arrival_check CHECK ((invoice_arrival = ANY (ARRAY['al_momento'::text, 'inicio_mes_siguiente'::text]))),
    CONSTRAINT supplier_invoicing_frequency_check CHECK (((invoicing_frequency IS NULL) OR (invoicing_frequency = ANY (ARRAY['per_delivery'::text, 'weekly'::text, 'fortnightly'::text, 'monthly'::text, 'other'::text])))),
    CONSTRAINT supplier_invoicing_mode_check CHECK ((invoicing_mode = ANY (ARRAY['per_delivery'::text, 'delivery_note_then_invoice'::text, 'monthly_settlement'::text]))),
    CONSTRAINT supplier_irpf_check CHECK (((irpf_withholding_pct IS NULL) OR ((irpf_withholding_pct >= (0)::numeric) AND (irpf_withholding_pct <= (100)::numeric)))),
    CONSTRAINT supplier_payment_method_check CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['transfer'::text, 'direct_debit'::text, 'card'::text, 'cash'::text, 'prepaid'::text])))),
    CONSTRAINT supplier_payment_terms_check CHECK (((payment_terms_days IS NULL) OR ((payment_terms_days >= 0) AND (payment_terms_days <= 365)))),
    CONSTRAINT supplier_related_party_kind_check CHECK (((related_party_kind IS NULL) OR (related_party_kind = ANY (ARRAY['group'::text, 'joint'::text, 'associate'::text, 'other_related'::text])))),
    CONSTRAINT supplier_tax_id_check_status_check CHECK (((tax_id_check_status IS NULL) OR (tax_id_check_status = ANY (ARRAY['valid'::text, 'invalid'::text, 'pending'::text])))),
    CONSTRAINT supplier_tax_id_type_check CHECK (((tax_id_type IS NULL) OR (tax_id_type = ANY (ARRAY['nif_es'::text, 'vat_eu'::text, 'foreign'::text])))),
    CONSTRAINT supplier_vat_regime_check CHECK (((vat_regime IS NULL) OR (vat_regime = ANY (ARRAY['general'::text, 'recargo_equivalencia'::text, 'intracomunitario'::text, 'exento'::text, 'inversion_sujeto_pasivo'::text, 'extranjero'::text]))))
);


--
-- Name: COLUMN supplier.email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.email IS 'OBSOLETA desde C01 (01/10/2026): el email vive en supplier_contact. No leer ni escribir. Se borra en un encargo posterior.';


--
-- Name: COLUMN supplier.phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.phone IS 'OBSOLETA desde C01 (01/10/2026): el teléfono vive en supplier_contact. No leer ni escribir. Se borra en un encargo posterior.';


--
-- Name: COLUMN supplier.address; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.address IS 'OBSOLETA desde C01 (01/10/2026): la dirección fiscal vive en fiscal_*. Su reparto se propone en supplier_proposal. No leer ni escribir.';


--
-- Name: COLUMN supplier.iva_incluido_en_linea; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.iva_incluido_en_linea IS 'ENCARGO 31/08: este proveedor factura con el IVA DENTRO del importe de linea (AMIRSA lo hace). Es una SUGERENCIA para la recepcion: propone el neto y lo ensena antes de guardar, nunca lo aplica en silencio. false = el albaran lista base imponible por linea y suma el IVA al pie (lo habitual). AQUI NO VA EL TIPO: el tipo es del articulo (vat_category/vat_rate, con family_vat_default de cascada) y esta columna solo dice COMO escribe sus importes el proveedor.';


--
-- Name: COLUMN supplier.legal_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.legal_name IS 'C01. Razón social. name sigue siendo el nombre comercial que se ve en la app.';


--
-- Name: COLUMN supplier.tax_id_check_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.tax_id_check_status IS 'C01. valid/invalid/pending. pending = VIES no contestó; la ficha dice «Comprobando con la UE…» y se reintenta. No bloquea.';


--
-- Name: COLUMN supplier.iban; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.iban IS 'C01. Sin espacios y en mayúsculas. Validado ISO 13616 (módulo 97) en el núcleo antes de guardar.';


--
-- Name: COLUMN supplier.related_party_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.related_party_kind IS 'C00. Si el proveedor es parte vinculada: grupo, multigrupo, asociada u otra. Solo se guarda.';


--
-- Name: COLUMN supplier.usual_tax_rate_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.usual_tax_rate_ids IS 'C01b. IVA habituales del proveedor: ids de tax_rate (de serie o de la cuenta). Sustituye a usual_vat_rates.';


--
-- Name: COLUMN supplier.invoicing_frequency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.invoicing_frequency IS 'C01b. Cómo le llegan las facturas: per_delivery (con cada albarán), weekly, fortnightly, monthly u other.';


--
-- Name: COLUMN supplier.iban_changed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.iban_changed_at IS 'C01b · Cuándo se cambió el IBAN desde una factura («Es el nuevo IBAN»). El certificado del banco anterior deja de valer.';


--
-- Name: COLUMN supplier.import_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.import_id IS 'C02c. Ficha creada al traer el plan de otro programa («Traída de … · por completar»). Null en las demás.';


--
-- Name: COLUMN supplier.invoicing_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.invoicing_mode IS 'Compras (10/10). Cómo te factura: per_delivery «Con cada entrega» · delivery_note_then_invoice «Entrega con albarán y factura después» · monthly_settlement «Liquidación mensual». Vacío: no se sabe. Es la costumbre: cada papel decide (goods_receipt_path).';


--
-- Name: COLUMN supplier.invoicing_per_location; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.invoicing_per_location IS 'Compras (10/10). Con delivery_note_then_invoice: una factura por cada local (true) o una para todos. Cada cuánto: invoicing_frequency.';


--
-- Name: COLUMN supplier.created_from; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.created_from IS 'D01 · «factura»: dado de alta desde lo leído en una factura («Traída de factura · por completar»).';


--
-- Name: COLUMN supplier.iban_set_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.iban_set_at IS 'PC01 · E2b · Cuándo se puso el IBAN donde no había (a mano, con «Poner IBAN» o leído de una factura).';


--
-- Name: COLUMN supplier.iban_set_by_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.iban_set_by_name IS 'PC01 · E2b · Quién puso el IBAN donde no había («Sumied» si se leyó de una factura).';


--
-- Name: COLUMN supplier.iban_unconfirmed_invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.iban_unconfirmed_invoice_id IS 'PC01 · E2b · El IBAN de la ficha se leyó de esta factura y nadie lo ha confirmado: para la remesa hasta confirmarlo.';


--
-- Name: COLUMN supplier.data_from_invoice; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.data_from_invoice IS 'S01b · De qué factura sale cada dato de la ficha tomado de una factura: { campo: { factura, facturaId, fecha, quien } } (nif, nombreFiscal, direccion, web, iban).';


--
-- Name: COLUMN supplier.invoice_arrival; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier.invoice_arrival IS 'S01c. Cuándo llegan sus facturas: al_momento (o nulo) o inicio_mes_siguiente (todas juntas a primeros del mes siguiente, como Amirsa). Solo cambia hasta cuándo es normal esperarlas.';


--
-- Name: supplier_alias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_alias (
