    CONSTRAINT supplier_balance_check_provider_check CHECK ((provider = 'catcher'::text))
);


--
-- Name: TABLE supplier_balance_check; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_balance_check IS 'E05 · Cada vez que alguien escribe el saldo que enseña el portal del proveedor (Catcher) y la app lo compara con el de su cuenta prepago (40700001).';


--
-- Name: supplier_batch; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_batch (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    provider text NOT NULL,
    period_from date NOT NULL,
    period_to date NOT NULL,
    label text NOT NULL,
    files jsonb DEFAULT '[]'::jsonb NOT NULL,
    invoice_count integer DEFAULT 0 NOT NULL,
    tax_base_total numeric(14,2),
    tax_total numeric(14,2),
    grand_total numeric(14,2),
    warnings jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    crossed_at timestamp with time zone,
    cross_summary jsonb,
    payment_entry_id uuid,
    CONSTRAINT supplier_batch_check CHECK ((period_to >= period_from)),
    CONSTRAINT supplier_batch_provider_check CHECK ((provider = 'catcher'::text))
);


--
-- Name: TABLE supplier_batch; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_batch IS 'E05 · Un lote de facturas recibidas que el proveedor da de una vez (la quincena de Catcher: ZIP de PDF + Excel FACTURAS + Excel PEDIDOS). Uno por empresa, proveedor y periodo.';


--
-- Name: COLUMN supplier_batch.cross_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_batch.cross_summary IS 'E05 · El último cruce: cuántas facturas cuadran, cuántas por aclarar, la comisión esperada y la cobrada, y el coste por local, marca y plataforma.';


--
-- Name: COLUMN supplier_batch.payment_entry_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_batch.payment_entry_id IS 'E05 · El asiento del pago del lote contra el saldo prepago (40700001), en la serie de tesorería.';


--
-- Name: supplier_batch_issue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_batch_issue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    supplier_invoice_id uuid,
    reason text NOT NULL,
    order_code text,
    ordered_at timestamp with time zone,
    text text NOT NULL,
    difference_cents integer,
    status text DEFAULT 'abierta'::text NOT NULL,
