    resolved_at timestamp with time zone,
    resolved_by uuid,
    resolved_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_batch_issue_check CHECK (((status = 'abierta'::text) = (resolved_at IS NULL))),
    CONSTRAINT supplier_batch_issue_reason_check CHECK ((reason = ANY (ARRAY['no_se_mando'::text, 'dos_pedidos_a_esa_hora'::text, 'cancelado_facturado'::text, 'precio_distinto'::text, 'fuera_de_tarifa'::text, 'sin_tarifa'::text, 'comision_sin_entrega'::text, 'comision_distinta'::text, 'entregado_sin_factura'::text, 'suma_pedidos'::text, 'suma_lote'::text]))),
    CONSTRAINT supplier_batch_issue_status_check CHECK ((status = ANY (ARRAY['abierta'::text, 'aceptada'::text, 'reclamada'::text])))
);


--
-- Name: TABLE supplier_batch_issue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_batch_issue IS 'E05 · «Por aclarar» de un lote: cada cosa que no cuadra al cruzarlo (un pedido, una comisión, una suma), con su porqué; y lo que decidió la persona (aceptada: se da por buena; reclamada: se reclama al proveedor).';


--
-- Name: supplier_batch_order; Type: TABLE; Schema: public; Owner: -
--

