--
-- Name: TABLE supplier_batch_store; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_batch_store IS 'E05 · Cómo se llama cada local en el portal del proveedor (la tienda de Catcher) → el local de la cuenta.';


--
-- Name: supplier_contact; Type: TABLE; Schema: public; Owner: -
