--
-- Name: supplier_invoice_expense; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice_expense (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    supplier_invoice_id uuid NOT NULL,
    "position" integer NOT NULL,
    account_code text NOT NULL,
    location_id uuid,
    is_common boolean DEFAULT false NOT NULL,
    amount numeric(14,2) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE supplier_invoice_expense; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_invoice_expense IS 'D03 · El gasto de una recibida repartido por cuenta (del plan de su empresa) y local, o común. Si tiene filas, manda sobre la cuenta propuesta. Lo escribe conta_recibida_guardar.';


--
-- Name: supplier_invoice_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice_line (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    supplier_invoice_id uuid NOT NULL,
    recipe_item_id uuid,
    raw_text text,
    supplier_code text,
    qty numeric,
    unit_price numeric,
    line_amount numeric,
    vat_pct numeric,
    vat_category_id uuid,
    goods_receipt_line_id uuid,
    map_source text,
    map_needs_review boolean DEFAULT false NOT NULL,
    match_result text,
    match_detail jsonb,
    "position" integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expense_account_code text
);


--
-- Name: COLUMN supplier_invoice_line.expense_account_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_invoice_line.expense_account_code IS 'D01 · La cuenta de gasto de ESTA línea, si no es la del proveedor (la factura de comisión de Uber: comisión a la 623, anuncios a la 627).';


--
-- Name: supplier_invoice_payment_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice_payment_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    action text NOT NULL,
    paid_at date,
    paid_method text,
    due_date date,
    actor_id uuid,
    actor_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_invoice_payment_log_action_check CHECK ((action = ANY (ARRAY['paid'::text, 'unpaid'::text, 'due_date_changed'::text])))
);


--
-- Name: TABLE supplier_invoice_payment_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_invoice_payment_log IS 'C01. Quién marcó una factura de proveedor como pagada, quién lo deshizo y quién cambió su vencimiento a mano. Solo se añade.';


--
-- Name: supplier_invoice_receipt; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice_receipt (
    supplier_invoice_id uuid NOT NULL,
    goods_receipt_id uuid NOT NULL
);


--
-- Name: supplier_invoice_request; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice_request (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    supplier_id uuid,
    expected_id uuid,
    period date NOT NULL,
    to_email text NOT NULL,
    subject text NOT NULL,
    body text NOT NULL,
    status text DEFAULT 'borrador'::text NOT NULL,
    confirmed_at timestamp with time zone,
    confirmed_by uuid,
    confirmed_by_name text,
    sent_at timestamp with time zone,
    provider_message_id text,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_invoice_request_check CHECK (((status <> ALL (ARRAY['confirmado'::text, 'enviado'::text])) OR ((confirmed_at IS NOT NULL) AND (confirmed_by_name IS NOT NULL)))),
    CONSTRAINT supplier_invoice_request_check1 CHECK (((status <> 'enviado'::text) OR (sent_at IS NOT NULL))),
    CONSTRAINT supplier_invoice_request_period_check CHECK ((EXTRACT(day FROM period) = (1)::numeric)),
    CONSTRAINT supplier_invoice_request_status_check CHECK ((status = ANY (ARRAY['borrador'::text, 'confirmado'::text, 'enviado'::text, 'error'::text]))),
    CONSTRAINT supplier_invoice_request_to_email_check CHECK ((to_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'::text))
);


--
-- Name: TABLE supplier_invoice_request; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_invoice_request IS 'D01 · «Pedírsela»: el correo al contacto de facturación del proveedor cuando una factura esperada no llega. Lo confirma una persona antes de que salga.';


--
-- Name: supplier_invoice_tax; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice_tax (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    supplier_invoice_id uuid NOT NULL,
    tax_rate_id uuid,
    vat_pct numeric(5,2) NOT NULL,
    base numeric(14,2) NOT NULL,
    vat_amount numeric(14,2) NOT NULL,
    surcharge_pct numeric(5,2),
    surcharge_amount numeric(14,2) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE supplier_invoice_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_invoice_tax IS 'D01 · El cuadro de impuestos de una factura recibida: base, cuota y recargo por tipo de IVA.';


--
-- Name: supplier_learning; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_learning (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    supplier_id uuid NOT NULL,
    campo text NOT NULL,
    valor text NOT NULL,
    etiqueta text NOT NULL,
    porque text NOT NULL,
    veces integer DEFAULT 0 NOT NULL,
    desde timestamp with time zone,
    hasta timestamp with time zone,
    a_mano boolean DEFAULT false NOT NULL,
    fijado_por uuid,
    fijado_por_nombre text,
    aprendido_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_learning_campo_check CHECK ((campo = ANY (ARRAY['expense_category'::text, 'tax_rates'::text, 'withholding'::text, 'payment'::text, 'iban'::text]))),
    CONSTRAINT supplier_learning_etiqueta_check CHECK ((length(btrim(etiqueta)) > 0)),
    CONSTRAINT supplier_learning_porque_check CHECK ((length(btrim(porque)) > 0)),
    CONSTRAINT supplier_learning_valor_check CHECK ((length(btrim(valor)) > 0)),
    CONSTRAINT supplier_learning_veces_check CHECK ((veces >= 0))
);


--
-- Name: TABLE supplier_learning; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_learning IS 'C01b · Lo que Folvy ha aprendido de cada proveedor (una fila por dato), con su porqué. Se propone en la factura siguiente, nunca se aplica sin confirmación. a_mano = lo fijó una persona con «Cambiar» y gana a lo aprendido.';


--
-- Name: supplier_learning_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_learning_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    supplier_id uuid NOT NULL,
    campo text NOT NULL,
    que text NOT NULL,
    valor text,
    etiqueta text,
    porque text NOT NULL,
    hecho_at timestamp with time zone DEFAULT now() NOT NULL,
    hecho_por uuid,
    hecho_por_nombre text,
    CONSTRAINT supplier_learning_log_campo_check CHECK ((campo = ANY (ARRAY['expense_category'::text, 'tax_rates'::text, 'withholding'::text, 'payment'::text, 'iban'::text]))),
    CONSTRAINT supplier_learning_log_porque_check CHECK ((length(btrim(porque)) > 0)),
    CONSTRAINT supplier_learning_log_que_check CHECK ((que = ANY (ARRAY['aprendido'::text, 'olvidado'::text, 'fijado_a_mano'::text, 'devuelto_a_folvy'::text])))
);


--
-- Name: TABLE supplier_learning_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_learning_log IS 'C01b · «Lo que ha hecho Folvy» con los proveedores: cuándo aprendió u olvidó algo y por qué, y cuándo una persona lo cambió a mano. Solo se añade: no se edita ni se borra.';


--
-- Name: supplier_merge; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_merge (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    kept_supplier_id uuid NOT NULL,
    gone_supplier_id uuid NOT NULL,
    moved jsonb NOT NULL,
    kept_on_gone jsonb DEFAULT '[]'::jsonb NOT NULL,
    filled jsonb DEFAULT '{}'::jsonb NOT NULL,
    party_merge_id uuid,
    summary text NOT NULL,
    done_at timestamp with time zone DEFAULT now() NOT NULL,
    done_by uuid,
    done_by_name text,
    undone_at timestamp with time zone,
    undone_by uuid,
    undone_by_name text,
    CONSTRAINT supplier_merge_check CHECK ((kept_supplier_id <> gone_supplier_id))
);


--
-- Name: TABLE supplier_merge; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_merge IS 'Compras (10/10). Cada fusión de dos fichas de proveedor: qué filas se movieron de la que se va a la que queda (moved, por tabla), lo que se quedó en la que se va por chocar con una clave única (kept_on_gone), los datos de ficha que se rellenaron (filled), la fusión de sus terceros (party_merge_id), quién y cuándo. La deshace supplier_merge_undo.';


--
-- Name: supplier_proposal; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_proposal (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    supplier_id uuid NOT NULL,
    field text NOT NULL,
    value jsonb NOT NULL,
    source text NOT NULL,
    source_id uuid,
    source_label text,
    status text DEFAULT 'pending'::text NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    decided_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_proposal_field_check CHECK ((field = ANY (ARRAY['tax_id'::text, 'legal_name'::text, 'fiscal_address'::text]))),
    CONSTRAINT supplier_proposal_source_check CHECK ((source = ANY (ARRAY['legacy_address'::text, 'supplier_invoice'::text, 'goods_receipt'::text]))),
    CONSTRAINT supplier_proposal_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'rejected'::text])))
);


--
-- Name: TABLE supplier_proposal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_proposal IS 'C01. Datos propuestos para la ficha (nunca se guardan sin confirmación). source_label = lo que se enseña: «Leído de su factura F-…».';


--
-- Name: supplier_rate; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_rate (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    provider text NOT NULL,
    valid_from date NOT NULL,
    params jsonb NOT NULL,
    source text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_name text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_rate_provider_check CHECK ((provider = 'catcher'::text))
);


--
-- Name: TABLE supplier_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.supplier_rate IS 'E05 · La tarifa de un proveedor que factura en lote (Catcher), fechada: vale desde valid_from hasta la siguiente. params: tramos [{hastaKm, precio}], porKmExtra, maximo, bonoLluviaPct, bonoDemandaPct, bonoMaxPct, pedidoExtra, comisionPedido (todo sin IVA).';


--
-- Name: supply_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supply_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    price_alert_pct numeric DEFAULT 15 NOT NULL,
    expiry_alert_days integer DEFAULT 3 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    created_by_name text,
    tol_a_pct numeric DEFAULT 2 NOT NULL,
    tol_b_pct numeric DEFAULT 3 NOT NULL,
    tol_c_pct numeric DEFAULT 5 NOT NULL,
    autoinventory_enabled boolean DEFAULT true NOT NULL,
    autoinventory_per_person integer DEFAULT 8 NOT NULL,
    negotiated_alert_pct numeric DEFAULT 0 NOT NULL,
    drift_alert_pct numeric DEFAULT 25 NOT NULL,
    drift_window_months integer DEFAULT 6 NOT NULL,
    require_separate_approval boolean DEFAULT true NOT NULL,
    neg_stock_rel_pct numeric DEFAULT 5 NOT NULL,
    neg_stock_abs_qty numeric DEFAULT 5 NOT NULL,
    neg_stock_window_days integer DEFAULT 60 NOT NULL,
    dock_pending_window_before_days integer DEFAULT 7 NOT NULL,
    dock_pending_window_after_days integer DEFAULT 3 NOT NULL,
    hung_order_days_threshold integer DEFAULT 14 NOT NULL,
    count_absurd_factor numeric DEFAULT 1000 NOT NULL,
    count_absurd_abs_cap numeric DEFAULT 1000000 NOT NULL,
    count_recount_factor numeric DEFAULT 3 NOT NULL,
    count_contradiction_pct numeric DEFAULT 40 NOT NULL,
    count_repeat_tolerance_pct numeric DEFAULT 5 NOT NULL,
    count_review_pct numeric DEFAULT 25 NOT NULL,
    count_review_eur numeric DEFAULT 5 NOT NULL,
    cost_band_factor numeric DEFAULT 5 NOT NULL
);


--
-- Name: COLUMN supply_settings.negotiated_alert_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.negotiated_alert_pct IS 'Umbral % por encima del precio pactado (negotiated_price) para avisar. 0 = avisa en cuanto el precio entrante supere el pacto.';


--
-- Name: COLUMN supply_settings.drift_alert_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.drift_alert_pct IS 'Umbral % de DERIVA ACUMULADA: precio entrante vs mínimo del periodo. Caza el goteo que el salto puntual no ve. Default 25.';


--
-- Name: COLUMN supply_settings.drift_window_months; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.drift_window_months IS 'Ventana en meses para medir la deriva acumulada. Default 6.';


--
-- Name: COLUMN supply_settings.neg_stock_rel_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.neg_stock_rel_pct IS 'Vigia de stock negativo: % del consumo reciente que debe superar |qty_on_hand| para contar como ALERTA (anti-ruido). Default 5.';


--
-- Name: COLUMN supply_settings.neg_stock_abs_qty; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.neg_stock_abs_qty IS 'Vigia de stock negativo: suelo absoluto en unidad base del articulo (evita ruido en articulos casi sin consumo). Default 5.';


--
-- Name: COLUMN supply_settings.neg_stock_window_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.neg_stock_window_days IS 'Vigia de stock negativo: ventana en dias para el consumo reciente; sin consumo en la ventana, se usa el consumo total historico. Default 60.';


--
-- Name: COLUMN supply_settings.dock_pending_window_before_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.dock_pending_window_before_days IS 'Muelle (OrderReceiveFlow): pedidos "enviado" con expected_date hasta N dias en el pasado siguen en la lista de pendientes. Default 7.';


--
-- Name: COLUMN supply_settings.dock_pending_window_after_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.dock_pending_window_after_days IS 'Muelle (OrderReceiveFlow): pedidos "enviado" con expected_date hasta N dias en el futuro ya aparecen en la lista de pendientes. Default 3.';


--
-- Name: COLUMN supply_settings.hung_order_days_threshold; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.hung_order_days_threshold IS 'Vigia de gestion (Saneado): pedido "enviado" vencido mas de N dias entra en la lista con propuesta de cierre corto. Default 14.';


--
-- Name: COLUMN supply_settings.count_recount_factor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.count_recount_factor IS 'Factor del freno a ciegas contra el teórico vivo (3 = ≥×3 o ≤⅓ → recount).';


--
-- Name: COLUMN supply_settings.count_contradiction_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.count_contradiction_pct IS 'Cuánto puede apartarse un recuento del anterior aprobado, ajustado por los movimientos de por medio, antes de considerarse contradicción (%).';


--
-- Name: COLUMN supply_settings.count_review_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.count_review_pct IS 'Umbral de la pantalla de aprobación: desviación ≥ este % Y ≥ count_review_eur a coste fiable manda la línea a «Revisa antes de aprobar». ORDENA Y ETIQUETA, NO ESCONDE: las que no llegan salen igual, en «Cuadran» (regla 7).';


--
-- Name: COLUMN supply_settings.cost_band_factor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supply_settings.cost_band_factor IS 'Cuántas veces puede apartarse el coste de una recepción del coste de ficha antes de que deje de mover el coste medio (5 = ×5 arriba o abajo). No la rechaza ni la borra: la deja fuera de la media y la lista para corregir.';


--
-- Name: system_alert_queue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_alert_queue (
    id bigint NOT NULL,
    kind text NOT NULL,
    debounce_kind text,
    subject text NOT NULL,
    message text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    request_id bigint,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_attempt_at timestamp with time zone,
    sent_at timestamp with time zone,
    account_id uuid,
    location_id uuid,
    brand_id uuid,
    severity text,
    CONSTRAINT system_alert_queue_severity_chk CHECK (((severity IS NULL) OR (severity = ANY (ARRAY['critico'::text, 'alto'::text, 'aviso'::text, 'info'::text])))),
    CONSTRAINT system_alert_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text])))
);


--
-- Name: TABLE system_alert_queue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.system_alert_queue IS 'Cola con reintento para el canal system-alert (11/08) — patron de customer_notification/training_notice. RLS deny-all. Retencion 7 dias para filas resueltas.';


--
-- Name: COLUMN system_alert_queue.account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_alert_queue.account_id IS 'Negocio del que habla el aviso. NULL = aviso de sistema, no de una cuenta.';


--
-- Name: COLUMN system_alert_queue.location_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_alert_queue.location_id IS 'Local del que habla el aviso. NULL = el hecho no es de un local. Si el hecho SÍ es de un local y esto viene NULL, es un bug (regla 7).';


--
-- Name: COLUMN system_alert_queue.brand_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_alert_queue.brand_id IS 'Marca del que habla el aviso, si aplica.';


--
-- Name: COLUMN system_alert_queue.severity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_alert_queue.severity IS 'critico | alto | aviso | info. NULL = no declarada (llamador aún sin migrar): se trata como ALTO, nunca como bajo.';


--
-- Name: system_alert_queue_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.system_alert_queue ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.system_alert_queue_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: tag; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tag (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    template_id uuid,
    name text NOT NULL,
    color text,
    icon text,
    "group" text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: tag_template; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tag_template (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name_es text NOT NULL,
    name_en text NOT NULL,
    color text,
    icon text,
    "group" text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tag_template_group_check CHECK (("group" = ANY (ARRAY['diet'::text, 'flavor'::text, 'origin'::text, 'commercial'::text, 'operational'::text])))
);


--
-- Name: tax_certificate; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_certificate (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_account_id uuid NOT NULL,
    subject_name text NOT NULL,
    subject_tax_id_hash text NOT NULL,
    subject_tax_id_tail text,
    issuer text NOT NULL,
    serial text NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_to timestamp with time zone NOT NULL,
    fingerprint_sha256 text NOT NULL,
    kind text NOT NULL,
    storage text NOT NULL,
    vault_secret_id uuid,
    kms_key_ref text,
    ciphertext bytea,
    wrapped_key bytea,
    status text DEFAULT 'active'::text NOT NULL,
    uploaded_by uuid,
    uploaded_by_name text,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    removed_at timestamp with time zone,
    removed_by uuid,
    removed_by_name text,
    last_test_at timestamp with time zone,
    last_test_result text,
    last_test_message text,
    CONSTRAINT tax_certificate_check CHECK ((valid_to > valid_from)),
    CONSTRAINT tax_certificate_check1 CHECK (((status = 'removed'::text) = (removed_at IS NOT NULL))),
    CONSTRAINT tax_certificate_check2 CHECK (((status = 'removed'::text) OR ((storage = 'vault'::text) AND (vault_secret_id IS NOT NULL) AND (kms_key_ref IS NULL) AND (ciphertext IS NULL)) OR ((storage = 'kms'::text) AND (kms_key_ref IS NOT NULL) AND (ciphertext IS NOT NULL) AND (vault_secret_id IS NULL)))),
    CONSTRAINT tax_certificate_check3 CHECK (((status <> 'removed'::text) OR ((vault_secret_id IS NULL) AND (ciphertext IS NULL) AND (wrapped_key IS NULL)))),
    CONSTRAINT tax_certificate_fingerprint_sha256_check CHECK ((fingerprint_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tax_certificate_kind_check CHECK ((kind = ANY (ARRAY['legal_representative'::text, 'natural_person'::text, 'other'::text]))),
    CONSTRAINT tax_certificate_last_test_result_check CHECK ((last_test_result = ANY (ARRAY['ok'::text, 'error'::text]))),
    CONSTRAINT tax_certificate_status_check CHECK ((status = ANY (ARRAY['active'::text, 'expired'::text, 'removed'::text]))),
    CONSTRAINT tax_certificate_storage_check CHECK ((storage = ANY (ARRAY['vault'::text, 'kms'::text]))),
    CONSTRAINT tax_certificate_subject_tax_id_hash_check CHECK ((subject_tax_id_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tax_certificate_subject_tax_id_tail_check CHECK ((subject_tax_id_tail ~ '^[0-9A-Z]{3}$'::text))
);


--
-- Name: TABLE tax_certificate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_certificate IS 'I01a. La ficha de un certificado electrónico: de quién es, quién lo emitió, hasta cuándo vale y en qué almacén está (storage). El certificado no está aquí: lo guarda el almacén (pieza 4); el front no lee vault_secret_id, kms_key_ref, ciphertext ni wrapped_key. El NIF del titular, solo su huella y sus tres últimos caracteres.';


--
-- Name: tax_certificate_confirmation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_certificate_confirmation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    certificate_id uuid NOT NULL,
    owner_account_id uuid NOT NULL,
    user_id uuid NOT NULL,
    action text NOT NULL,
    tax_return_id uuid,
    company_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    CONSTRAINT tax_certificate_confirmation_action_check CHECK ((action = ANY (ARRAY['test'::text, 'file'::text, 'query'::text, 'receipt_pdf'::text]))),
    CONSTRAINT tax_certificate_confirmation_check CHECK ((expires_at > created_at))
);


--
-- Name: TABLE tax_certificate_confirmation; Type: COMMENT; Schema: public; Owner: -
--

