--
-- Name: TABLE tax_certificate_grant; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_certificate_grant IS 'I01a. Quién puede usar un certificado: file = puede presentar; view = solo ver. Uno vivo por persona y certificado.';


