    default_for text,
    default_legal_ref text,
    CONSTRAINT tax_form_anual_con_norma CHECK ((((annual_form_code IS NULL) = (annual_legal_ref IS NULL)) AND ((default_for IS NULL) = (default_legal_ref IS NULL)))),
    CONSTRAINT tax_form_code_check CHECK ((code ~ '^[0-9]{3}$'::text)),
    CONSTRAINT tax_form_default_for_valido CHECK (((default_for IS NULL) OR (default_for = 'company_not_sii'::text)))
);


--
-- Name: TABLE tax_form; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_form IS 'C00. Modelos tributarios (303, 111, 115…) con la norma que obliga a presentarlos.';


--
-- Name: COLUMN tax_form.annual_form_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_form.annual_form_code IS 'El resumen anual de este modelo periódico (respuesta 3 del C00).';


--
-- Name: COLUMN tax_form.annual_legal_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_form.annual_legal_ref IS 'La norma que obliga a presentar ese resumen anual.';


--
-- Name: COLUMN tax_form.default_for; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_form.default_for IS 'Para quién va por defecto (company_not_sii: toda sociedad que no lleva el SII).';


--
-- Name: COLUMN tax_form.default_legal_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_form.default_legal_ref IS 'La norma por la que va por defecto, y su excepción.';


--
-- Name: tax_form_deadline; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_form_deadline (
    form_code text NOT NULL,
    cadence text NOT NULL,
    period text NOT NULL,
    months_after smallint NOT NULL,
    day smallint,
    direct_debit boolean NOT NULL,
    legal_ref text NOT NULL,
    CONSTRAINT tax_form_deadline_cadence_check CHECK ((cadence = ANY (ARRAY['quarterly'::text, 'monthly'::text, 'annual'::text, 'instalments_202'::text]))),
    CONSTRAINT tax_form_deadline_day_check CHECK (((day >= 1) AND (day <= 31))),
    CONSTRAINT tax_form_deadline_months_after_check CHECK (((months_after >= 1) AND (months_after <= 12))),
    CONSTRAINT tax_form_deadline_period_check CHECK ((period ~ '^(\*|[1-4]T|0[1-9]|1[0-2]|0A|[1-3]P)$'::text))
);


--
-- Name: TABLE tax_form_deadline; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_form_deadline IS 'I01a. Plazo de presentación de cada modelo y periodo, con su norma: meses tras el último mes del periodo y día (null = último del mes). direct_debit: tiene ingreso domiciliable (Orden EHA/1658/2009, anexo II).';


--
-- Name: tax_holiday; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_holiday (
    day date NOT NULL,
    scope text NOT NULL,
    name text NOT NULL,
    source_key text NOT NULL,
    CONSTRAINT tax_holiday_scope_check CHECK ((scope ~ '^ES(-[A-Z]{2})?$'::text))
);


--
-- Name: TABLE tax_holiday; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_holiday IS 'I01a. Festivos que mueven los plazos de Hacienda. ES: fiestas nacionales del art. 45.1 del RD 2001/1983 (aunque una comunidad las sustituya). ES-MD: los que no se trabaja en la Comunidad de Madrid. Del BOE, por scripts/conta/i01/festivos.mjs.';


--
-- Name: tax_holiday_year; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_holiday_year (
    year integer NOT NULL,
    scope text NOT NULL,
    source_key text NOT NULL,
    provisional_reason text,
    CONSTRAINT tax_holiday_year_scope_check CHECK ((scope ~ '^ES(-[A-Z]{2})?$'::text)),
    CONSTRAINT tax_holiday_year_year_check CHECK (((year >= 2000) AND (year <= 2100)))
);


--
-- Name: TABLE tax_holiday_year; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_holiday_year IS 'I01a. Años con festivos cargados, por ámbito (ES nacional, ES-MD Comunidad de Madrid), con su fuente. provisional_reason: lo que falta para darlos por buenos (null = definitivos).';


--
-- Name: tax_rate; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_rate (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid,
    company_id uuid,
    is_system boolean DEFAULT false NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    example text,
    tax_system text NOT NULL,
    territory text NOT NULL,
    treatment text DEFAULT 'taxed'::text NOT NULL,
    rate numeric(5,2) NOT NULL,
    surcharge_rate numeric(5,2),
    valid_from date NOT NULL,
    valid_to date,
    pgc_input_hint text,
    pgc_output_hint text,
    declared_in text[] DEFAULT '{}'::text[] NOT NULL,
    legal_ref text,
    verified_at date,
    source_key text,
    sort_order smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT tax_rate_rate_check CHECK (((rate >= (0)::numeric) AND (rate <= (100)::numeric))),
    CONSTRAINT tax_rate_serie CHECK (public.conta_fila_serie_ok(is_system, account_id, company_id, legal_ref, verified_at, source_key)),
    CONSTRAINT tax_rate_surcharge_rate_check CHECK (((surcharge_rate IS NULL) OR ((surcharge_rate >= (0)::numeric) AND (surcharge_rate <= (100)::numeric)))),
    CONSTRAINT tax_rate_tax_system_check CHECK ((tax_system = ANY (ARRAY['iva'::text, 'igic'::text, 'ipsi'::text]))),
    CONSTRAINT tax_rate_territory_check CHECK ((territory = ANY (ARRAY['peninsula_baleares'::text, 'canarias'::text, 'ceuta_melilla'::text]))),
    CONSTRAINT tax_rate_treatment_check CHECK ((treatment = ANY (ARRAY['taxed'::text, 'exempt'::text, 'intra_eu'::text, 'reverse_charge'::text, 'not_subject'::text])))
);


--
-- Name: TABLE tax_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_rate IS 'C00 (D1). LA fuente de los porcentajes de impuestos: IVA, recargo de equivalencia, IGIC, IPSI, exentos, intracomunitario e inversión del sujeto pasivo.';


--
-- Name: tax_return; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_return (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    obligation_id uuid,
    form_code text NOT NULL,
    fiscal_year integer NOT NULL,
    cadence text NOT NULL,
    period text NOT NULL,
    sequence smallint DEFAULT 1 NOT NULL,
    kind text DEFAULT 'normal'::text NOT NULL,
    replaces_return_id uuid,
    due_date date NOT NULL,
    due_date_direct_debit date,
    due_provisional text,
    alert_on date,
    status text DEFAULT 'pending'::text NOT NULL,
    not_required_reason text,
    result_kind text,
    amount numeric(14,2),
    previous_period_amount numeric(14,2),
    payment_mode text,
    payment_treasury_account_id uuid,
    nrc text,
    filed_at timestamp with time zone,
    filed_by uuid,
    filed_by_name text,
    filed_via text,
    presenter_kind text,
    certificate_id uuid,
    aeat_csv text,
    aeat_receipt_number text,
    receipt_document_path text,
    outside_csv_pasted_at timestamp with time zone,
    liquidation_entry_id uuid,
    payment_entry_id uuid,
    bank_match_id uuid,
    calculated_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    reviewed_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    aeat_expediente text,
    presenter_tax_id text,
    presenter_name text,
    receipt_source text,
    CONSTRAINT tax_return_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT tax_return_cadence_check CHECK ((cadence = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'annual'::text, 'instalments_202'::text]))),
    CONSTRAINT tax_return_check CHECK (((kind = 'normal'::text) = (replaces_return_id IS NULL))),
    CONSTRAINT tax_return_check1 CHECK (((status <> 'not_required'::text) OR ((not_required_reason IS NOT NULL) AND (btrim(not_required_reason) <> ''::text)))),
    CONSTRAINT tax_return_check2 CHECK (((result_kind IS NULL) OR (amount IS NOT NULL))),
    CONSTRAINT tax_return_check3 CHECK (((result_kind <> ALL (ARRAY['zero'::text, 'no_activity'::text])) OR (amount = (0)::numeric))),
    CONSTRAINT tax_return_check4 CHECK (((result_kind <> ALL (ARRAY['to_pay'::text, 'to_refund'::text, 'to_offset'::text])) OR (amount > (0)::numeric))),
    CONSTRAINT tax_return_check5 CHECK (((status <> ALL (ARRAY['filed'::text, 'booked'::text, 'paid'::text, 'offset'::text, 'refunded'::text])) OR ((filed_at IS NOT NULL) AND (filed_via IS NOT NULL) AND (aeat_csv IS NOT NULL)))),
    CONSTRAINT tax_return_check6 CHECK (((status <> ALL (ARRAY['reviewed'::text, 'filed'::text, 'booked'::text, 'paid'::text, 'offset'::text, 'refunded'::text])) OR (result_kind IS NOT NULL))),
    CONSTRAINT tax_return_check7 CHECK (((payment_mode <> 'direct_debit'::text) OR (payment_treasury_account_id IS NOT NULL))),
    CONSTRAINT tax_return_check8 CHECK (((payment_mode <> 'nrc'::text) OR (nrc IS NOT NULL) OR (status = ANY (ARRAY['pending'::text, 'draft'::text, 'reviewed'::text])))),
    CONSTRAINT tax_return_filed_via_check CHECK ((filed_via = ANY (ARRAY['sumied'::text, 'outside'::text]))),
    CONSTRAINT tax_return_fiscal_year_check CHECK (((fiscal_year >= 2000) AND (fiscal_year <= 2100))),
    CONSTRAINT tax_return_kind_check CHECK ((kind = ANY (ARRAY['normal'::text, 'complementary'::text, 'substitutive'::text]))),
    CONSTRAINT tax_return_payment_mode_check CHECK ((payment_mode = ANY (ARRAY['direct_debit'::text, 'nrc'::text, 'debt_recognition'::text, 'offset'::text, 'refund'::text]))),
    CONSTRAINT tax_return_period_check CHECK ((period ~ '^([1-4]T|0[1-9]|1[0-2]|0A|[1-3]P)$'::text)),
    CONSTRAINT tax_return_presenter_kind_check CHECK ((presenter_kind = ANY (ARRAY['company'::text, 'advisor'::text]))),
    CONSTRAINT tax_return_receipt_source_check CHECK ((receipt_source = ANY (ARRAY['upload'::text, 'aeat_csv'::text]))),
    CONSTRAINT tax_return_result_kind_check CHECK ((result_kind = ANY (ARRAY['to_pay'::text, 'to_refund'::text, 'to_offset'::text, 'zero'::text, 'no_activity'::text]))),
    CONSTRAINT tax_return_sequence_check CHECK ((sequence >= 1)),
    CONSTRAINT tax_return_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'draft'::text, 'reviewed'::text, 'filed'::text, 'booked'::text, 'paid'::text, 'offset'::text, 'refunded'::text, 'not_required'::text])))
);


--
-- Name: TABLE tax_return; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_return IS 'I01a. Una declaración por modelo, empresa, ejercicio, periodo y número de orden (las complementarias y sustitutivas llevan otro). Estado como dato (CHECK) y cada cambio en tax_return_event. Plazos calculados y guardados.';


--
-- Name: COLUMN tax_return.receipt_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_return.receipt_source IS 'I01c (0270). De dónde salió el PDF del justificante: aeat_csv (traído de Hacienda por su CSV, el original) o upload (subido).';


--
-- Name: tax_return_box; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_return_box (
    tax_return_id uuid NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    box text NOT NULL,
    value numeric(16,2),
    value_text text,
    origin text DEFAULT 'calculated'::text NOT NULL,
    manual_reason text,
    source jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tax_return_box_box_check CHECK ((box ~ '^[0-9]{2,3}[A-Z]?$'::text)),
    CONSTRAINT tax_return_box_check CHECK (((value IS NULL) <> (value_text IS NULL))),
    CONSTRAINT tax_return_box_check1 CHECK (((origin <> 'manual'::text) OR ((manual_reason IS NOT NULL) AND (btrim(manual_reason) <> ''::text)))),
    CONSTRAINT tax_return_box_origin_check CHECK ((origin = ANY (ARRAY['calculated'::text, 'manual'::text, 'justificante'::text])))
);


--
-- Name: TABLE tax_return_box; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_return_box IS 'I01a. Las casillas del modelo oficial. source: de qué filas sale cada una. Una casilla puesta a mano lleva su motivo. El fichero oficial se genera de aquí.';


--
-- Name: tax_return_check; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_return_check (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tax_return_id uuid NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    check_key text NOT NULL,
    result text NOT NULL,
    title text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_by uuid,
    accepted_by_name text,
    accepted_at timestamp with time zone,
    accepted_reason text,
    CONSTRAINT tax_return_check_check CHECK (((accepted_at IS NULL) = (accepted_by IS NULL))),
    CONSTRAINT tax_return_check_check1 CHECK (((accepted_at IS NULL) OR ((result = 'warning'::text) AND (accepted_reason IS NOT NULL) AND (btrim(accepted_reason) <> ''::text)))),
    CONSTRAINT tax_return_check_check_key_check CHECK ((check_key = ANY (ARRAY['book_vs_303'::text, 'ledger_477_472'::text, 'sum_303_vs_390'::text, 'sum_111_vs_190'::text, 'sum_115_vs_180'::text, 'third_parties_347'::text, 'mail_invoices_missing'::text, 'out_of_period'::text, 'file_layout'::text, 'previous_offset'::text, 'ledger_4751'::text, 'payees_111'::text, 'withholding_unclassified'::text, 'base_200'::text, 'payees_190_nif'::text, 'payees_190_province'::text, 'payroll_190'::text, 'payees_180_nif'::text, 'payees_180_province'::text, 'lease_180'::text]))),
    CONSTRAINT tax_return_check_result_check CHECK ((result = ANY (ARRAY['ok'::text, 'warning'::text, 'error'::text]))),
    CONSTRAINT tax_return_check_title_check CHECK ((btrim(title) <> ''::text))
);


--
-- Name: TABLE tax_return_check; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_return_check IS 'I01a. Lo que ha comprobado Sumied antes de presentar (tablero 9): ✓ = ok, ! = warning o error. title: lo que se ve, en palabras de oficina. Un aviso se puede dar por bueno, con motivo («Julio la dio por buena el 09/10»); un error, no.';


--
-- Name: tax_return_event; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_return_event (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tax_return_id uuid NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    by_user uuid,
    by_name text,
    kind text NOT NULL,
    from_status text,
    to_status text,
    aeat_service text,
    result text,
    aeat_codes text[],
    message text,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tax_return_event_aeat_service_check CHECK ((aeat_service = ANY (ARRAY['present'::text, 'query'::text, 'receipt_pdf'::text, 'outside_check'::text]))),
    CONSTRAINT tax_return_event_check CHECK (((kind <> 'status'::text) OR (to_status IS NOT NULL))),
    CONSTRAINT tax_return_event_check1 CHECK (((kind <> 'aeat_call'::text) OR ((aeat_service IS NOT NULL) AND (result IS NOT NULL)))),
    CONSTRAINT tax_return_event_kind_check CHECK ((kind = ANY (ARRAY['status'::text, 'calculation'::text, 'check'::text, 'aeat_call'::text, 'note'::text]))),
    CONSTRAINT tax_return_event_result_check CHECK ((result = ANY (ARRAY['ok'::text, 'error'::text])))
);


--
-- Name: TABLE tax_return_event; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_return_event IS 'I01a. Cada cambio de estado de una declaración y cada llamada a Hacienda, con quién, cuándo y el resultado. message: lo que pasó en palabras de oficina (los errores de Hacienda, traducidos); aeat_codes: los códigos tal cual.';


--
-- Name: tax_return_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_return_line (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tax_return_id uuid NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    vat_book_entry_id uuid,
    journal_line_id uuid,
    supplier_invoice_id uuid,
    boxes text[] DEFAULT '{}'::text[] NOT NULL,
    frozen jsonb NOT NULL,
    CONSTRAINT tax_return_line_check CHECK (((vat_book_entry_id IS NOT NULL) OR (journal_line_id IS NOT NULL) OR (supplier_invoice_id IS NOT NULL) OR (frozen ? 'origen'::text)))
);


--
-- Name: TABLE tax_return_line; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tax_return_line IS 'I01a. Qué filas entran en una declaración y cómo eran al declararlas (frozen: base, cuota, tipo, fecha…). Si después se toca una, se ve la diferencia y pide complementaria.';


