    CONSTRAINT ticket_invoice_series_tramo_check CHECK (((tramo IS NULL) OR (tramo ~ '^[B-Z]$'::text))),
    CONSTRAINT ticket_invoice_series_year_check CHECK (((year >= 2024) AND (year <= 2100)))
);


