);


--
-- Name: TABLE vat_category_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.vat_category_tax IS 'C00 (D1). Qué impuesto de tax_rate corresponde a cada categoría de IVA de Cocina, y desde cuándo. Cocina lee de contabilidad, nunca al revés.';


--
-- Name: vat_category_rate; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vat_category_rate WITH (security_invoker='true') AS
 SELECT b.vat_category_id AS category_id,
    t.rate,
    COALESCE(t.surcharge_rate, (0)::numeric) AS equivalence_surcharge,
    GREATEST(b.valid_from, t.valid_from) AS valid_from,
        CASE
            WHEN (b.valid_to IS NULL) THEN t.valid_to
            WHEN (t.valid_to IS NULL) THEN b.valid_to
            ELSE LEAST(b.valid_to, t.valid_to)
        END AS valid_to,
    ((t.name || ' · '::text) || t.legal_ref) AS note,
    t.code AS tax_code
   FROM (public.vat_category_tax b
     JOIN public.tax_rate t ON (((t.code = b.tax_code) AND t.is_system)))
  WHERE (daterange(b.valid_from, b.valid_to, '[]'::text) && daterange(t.valid_from, t.valid_to, '[]'::text));


--
-- Name: VIEW vat_category_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.vat_category_rate IS 'C00 (D1). Lo que antes estaba escrito en vat_rate, ahora derivado de tax_rate por el puente. vat_rate_for lee de aquí desde la tarea 4.';


