--
-- Name: verifactu_atascados; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.verifactu_atascados WITH (security_invoker='true') AS
 SELECT account_id,
    company_id,
    entorno,
    nif_emisor,
    count(*) AS registros,
    min(generado_at) AS desde,
    max(intentos) AS intentos
   FROM public.verifactu_registro r
  WHERE ((estado = ANY (ARRAY['pendiente'::text, 'enviando'::text])) AND (generado_at < (now() - '01:00:00'::interval)))
  GROUP BY account_id, company_id, entorno, nif_emisor;


--
-- Name: VIEW verifactu_atascados; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.verifactu_atascados IS 'V03. Registros que llevan más de una hora sin llegar a Hacienda, por empresa y entorno. Lo vigila la función de envío y avisa.';


