    probada_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT verifactu_conexion_entorno_check CHECK ((entorno = ANY (ARRAY['pruebas'::text, 'real'::text]))),
    CONSTRAINT verifactu_conexion_nif_check CHECK ((nif ~ '^[0-9A-Z]{9}$'::text))
);


--
-- Name: TABLE verifactu_conexion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_conexion IS 'V03. Las pruebas de conexión con la AEAT (una consulta con certificado): entorno, NIF del certificado, si salió bien y qué dijo Hacienda. Sin una correcta, verifactu_modo no deja pasar a pruebas ni a real (el candado). Solo la escribe el servicio.';


--
-- Name: verifactu_cuadre; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifactu_cuadre (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    pedido_por_account uuid NOT NULL,
    entorno text NOT NULL,
    nif_emisor text NOT NULL,
    nombre_emisor text NOT NULL,
    ejercicio integer NOT NULL,
    periodo text NOT NULL,
    estado text DEFAULT 'pedido'::text NOT NULL,
    pedido_at timestamp with time zone DEFAULT now() NOT NULL,
    pedido_por_nombre text,
    empezado_at timestamp with time zone,
    terminado_at timestamp with time zone,
    paginas integer DEFAULT 0 NOT NULL,
    error text,
    resultado jsonb,
    CONSTRAINT verifactu_cuadre_ejercicio_check CHECK (((ejercicio >= 2024) AND (ejercicio <= 2100))),
    CONSTRAINT verifactu_cuadre_entorno_check CHECK ((entorno = ANY (ARRAY['pruebas'::text, 'real'::text]))),
    CONSTRAINT verifactu_cuadre_estado_check CHECK ((estado = ANY (ARRAY['pedido'::text, 'consultando'::text, 'hecho'::text, 'fallo'::text]))),
    CONSTRAINT verifactu_cuadre_nif_emisor_check CHECK ((nif_emisor ~ '^[0-9A-Z]{9}$'::text)),
    CONSTRAINT verifactu_cuadre_periodo_check CHECK ((periodo ~ '^(0[1-9]|1[0-2])$'::text))
);


--
-- Name: TABLE verifactu_cuadre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_cuadre IS 'V03 E3. «Comprobar con Hacienda»: una consulta a la AEAT de los registros de un mes de una empresa (su NIF y su entorno), y su cuadre con los de Sumied. La pide la pantalla (o el despacho de su asesoría); la hace conta-verifactu; el resultado lo calcula la base.';


--
-- Name: verifactu_cuadre_hacienda; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifactu_cuadre_hacienda (
    cuadre_id uuid NOT NULL,
    account_id uuid NOT NULL,
    num_serie text NOT NULL,
    fecha_expedicion date NOT NULL,
    tipo_factura text,
    cuota_total numeric(14,2),
    importe_total numeric(14,2),
    huella text,
    estado text NOT NULL,
    codigo_error integer,
    descripcion_error text,
    modificado_at timestamp with time zone,
    CONSTRAINT verifactu_cuadre_hacienda_estado_check CHECK ((estado = ANY (ARRAY['Correcto'::text, 'AceptadoConErrores'::text, 'Anulado'::text])))
);


--
-- Name: TABLE verifactu_cuadre_hacienda; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_cuadre_hacienda IS 'V03 E3. Lo que contestó la AEAT en una consulta (RespuestaConsultaLR.xsd): una fila por factura con su último estado (Correcto, AceptadoConErrores o Anulado), su huella y sus importes.';


--
-- Name: verifactu_empresa; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifactu_empresa (
    company_id uuid NOT NULL,
    account_id uuid NOT NULL,
    modo text DEFAULT 'apagado'::text NOT NULL,
    via text DEFAULT 'colaborador'::text NOT NULL,
    certificate_id uuid,
    pruebas_desde timestamp with time zone,
    real_desde timestamp with time zone,
    real_serie text,
    real_obliga_hasta date,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_name text,
    otros_programas text[],
    CONSTRAINT verifactu_empresa_check CHECK (((modo = 'real'::text) = (real_desde IS NOT NULL))),
    CONSTRAINT verifactu_empresa_check1 CHECK (((modo <> 'real'::text) OR ((real_serie IS NOT NULL) AND (real_obliga_hasta IS NOT NULL)))),
    CONSTRAINT verifactu_empresa_modo_check CHECK ((modo = ANY (ARRAY['apagado'::text, 'pruebas'::text, 'real'::text]))),
    CONSTRAINT verifactu_empresa_real_serie_check CHECK (((real_serie IS NULL) OR (real_serie ~ '^[A-Z0-9][A-Z0-9-]{0,9}$'::text))),
    CONSTRAINT verifactu_empresa_via_check CHECK ((via = ANY (ARRAY['certificado'::text, 'colaborador'::text])))
);


--
-- Name: TABLE verifactu_empresa; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_empresa IS 'V03. Verifactu por empresa: apagado (de partida), pruebas (al entorno de pruebas de la AEAT; las facturas llevan «PRUEBA») o real. Real obliga hasta el 31/12 de ese año (Orden HAC/1177/2024, art. 17.2): no se vuelve atrás antes. Al pasar a real, una serie nueva (real_serie); las de antes se cierran y no se envían. via: con el certificado de la empresa o como colaborador social (preparada y apagada).';


--
-- Name: COLUMN verifactu_empresa.otros_programas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.verifactu_empresa.otros_programas IS 'V03 E2 · Con qué otros programas factura la empresa (tablero 25): tpv, tienda, excel, otro. null = no lo ha dicho; vacío = solo con Sumied.';


--
-- Name: verifactu_envio; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifactu_envio (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    entorno text NOT NULL,
    nif_emisor text NOT NULL,
    registros integer NOT NULL,
    empezado_at timestamp with time zone DEFAULT now() NOT NULL,
    terminado_at timestamp with time zone,
    http_status integer,
    estado_envio text,
    tiempo_espera_s integer,
    csv text,
    error text,
    respuesta text,
    autorizacion_id uuid,
    CONSTRAINT verifactu_envio_entorno_check CHECK ((entorno = ANY (ARRAY['pruebas'::text, 'real'::text]))),
    CONSTRAINT verifactu_envio_estado_envio_check CHECK ((estado_envio = ANY (ARRAY['Correcto'::text, 'ParcialmenteCorrecto'::text, 'Incorrecto'::text, 'fallo'::text])))
);


--
-- Name: TABLE verifactu_envio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_envio IS 'V03. Cada envío a la AEAT (un lote de hasta 1.000 registros de un mismo NIF): cuándo, cuántos, lo que contestó (estado del envío, CSV, TiempoEsperaEnvio) o el fallo. La respuesta se guarda recortada.';


--
-- Name: COLUMN verifactu_envio.autorizacion_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.verifactu_envio.autorizacion_id IS 'V03. Con qué autorización del certificado salió este envío (en real, por la vía del certificado). Nulo en pruebas y por la vía de colaborador social.';


--
-- Name: verifactu_factura_estado; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.verifactu_factura_estado WITH (security_invoker='true') AS
 SELECT ci.id AS invoice_id,
    ci.account_id,
    ci.company_id,
    COALESCE(r.estado, 'no_se_envia'::text) AS estado,
    r.entorno,
    r.id AS registro_id,
    r.huella,
    r.codigo_error,
    r.descripcion_error,
    r.generado_at,
    r.respondido_at,
    r.intentos,
    r.proximo_intento_at,
        CASE
            WHEN (r.id IS NOT NULL) THEN public.verifactu_url_qr(r.entorno, r.nif_emisor, r.num_serie, r.fecha_expedicion, r.importe_total)
            ELSE NULL::text
        END AS url_qr
   FROM (public.customer_invoice ci
     LEFT JOIN LATERAL ( SELECT x.id,
            x.account_id,
            x.company_id,
            x.entorno,
            x.tipo,
            x.subsanacion,
            x.rechazo_previo,
            x.sin_registro_previo,
            x.origen,
            x.invoice_id,
            x.origen_programa,
            x.origen_ref,
            x.alta_id,
            x.nif_emisor,
            x.nombre_emisor,
            x.num_serie,
            x.fecha_expedicion,
            x.fecha_operacion,
            x.tipo_factura,
            x.tipo_rectificativa,
            x.rectificadas,
            x.descripcion,
            x.destinatarios,
            x.desglose,
            x.cuota_total,
            x.importe_total,
            x.primer_registro,
            x.anterior_id,
            x.anterior_num_serie,
            x.anterior_fecha,
            x.huella_anterior,
            x.fecha_hora_huso,
            x.generado_at,
            x.cadena_huella,
            x.huella,
            x.estado,
            x.envio_id,
            x.intentos,
            x.proximo_intento_at,
            x.codigo_error,
            x.descripcion_error,
            x.csv,
            x.respondido_at,
            x.created_by_name
           FROM public.verifactu_registro x
          WHERE (x.invoice_id = ci.id)
          ORDER BY x.generado_at DESC
         LIMIT 1) r ON (true))
  WHERE (ci.status <> 'borrador'::text);


--
-- Name: VIEW verifactu_factura_estado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.verifactu_factura_estado IS 'V03. El estado de cada emitida con Hacienda (el último registro de su factura): pendiente, enviando, correcto, aceptado_con_errores, incorrecto o no_se_envia; y la URL de su QR.';


--
-- Name: verifactu_flujo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifactu_flujo (
    nif_emisor text NOT NULL,
    entorno text NOT NULL,
    tiempo_espera_s integer DEFAULT 60 NOT NULL,
    ultimo_envio_at timestamp with time zone,
    CONSTRAINT verifactu_flujo_entorno_check CHECK ((entorno = ANY (ARRAY['pruebas'::text, 'real'::text]))),
    CONSTRAINT verifactu_flujo_tiempo_espera_s_check CHECK ((tiempo_espera_s >= 0))
);


--
-- Name: TABLE verifactu_flujo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_flujo IS 'V03. El control de flujo de la AEAT por NIF (Orden HAC/1177/2024, art. 16.2): no se vuelve a enviar hasta que pasen tiempo_espera_s desde el último envío, salvo que haya 1.000 registros esperando. Cada respuesta trae el valor nuevo.';


--
-- Name: verifactu_operacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifactu_operacion (
    invoice_id uuid NOT NULL,
    account_id uuid NOT NULL,
    company_id uuid NOT NULL,
    calificacion text,
    exenta text,
    clave_regimen text DEFAULT '01'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_name text,
    CONSTRAINT verifactu_operacion_calificacion_check CHECK ((calificacion = ANY (ARRAY['S1'::text, 'S2'::text, 'N1'::text, 'N2'::text]))),
    CONSTRAINT verifactu_operacion_check CHECK (((calificacion IS NULL) OR (exenta IS NULL))),
    CONSTRAINT verifactu_operacion_check1 CHECK (((calificacion IS NOT NULL) OR (exenta IS NOT NULL))),
    CONSTRAINT verifactu_operacion_clave_regimen_check CHECK ((clave_regimen ~ '^[0-9]{2}$'::text)),
    CONSTRAINT verifactu_operacion_exenta_check CHECK ((exenta = ANY (ARRAY['E1'::text, 'E2'::text, 'E3'::text, 'E4'::text, 'E5'::text, 'E6'::text])))
);


--
-- Name: TABLE verifactu_operacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_operacion IS 'V03. Por qué una factura va sin IVA, para su registro de Verifactu: calificación (S2 inversión del sujeto pasivo; N1/N2 no sujeta; N2 = por reglas de localización, p. ej. un servicio a una empresa de fuera de la UE) o causa de exención (E1 art. 20; E2 exportación, con la clave 02; E5 entrega a otro país de la UE…). Se elige en el borrador; el registro la copia al emitir.';


--
-- Name: verifactu_sistema; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verifactu_sistema (
    id boolean DEFAULT true NOT NULL,
    nombre_razon text,
    nif text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_name text,
    CONSTRAINT verifactu_sistema_id_check CHECK (id),
    CONSTRAINT verifactu_sistema_nif_check CHECK (((nif IS NULL) OR (nif ~ '^[0-9A-Z]{9}$'::text)))
);


--
-- Name: TABLE verifactu_sistema; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.verifactu_sistema IS 'V04 · PR 2. Quién fabrica Sumied (NombreRazon y NIF del SistemaInformatico, la declaración responsable). Una sola fila. Nace vacía: sin esto, verifactu_modo no deja pasar a real y Ajustes lo avisa. Lo pone el servicio (verifactu_sistema_poner).';


