COMMENT ON TABLE public.whatsapp_entrada IS 'L1a PR 3: todo lo que llega al webhook de WhatsApp, también lo rechazado (sin la firma de Meta, o con una que no cuadra). Sin políticas: solo la clave de servicio.';


--
-- Name: withholding_rate; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.withholding_rate (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid,
    company_id uuid,
    is_system boolean DEFAULT false NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    example text,
    rate numeric(5,2) NOT NULL,
    model_190_key text,
    model_190_subkey text,
    filed_in text NOT NULL,
    valid_from date NOT NULL,
    valid_to date,
    pgc_hint text,
    legal_ref text,
    verified_at date,
    source_key text,
    sort_order smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT withholding_rate_filed_in_check CHECK ((filed_in = ANY (ARRAY['111'::text, '115'::text, '123'::text]))),
    CONSTRAINT withholding_rate_rate_check CHECK (((rate >= (0)::numeric) AND (rate <= (100)::numeric))),
    CONSTRAINT withholding_rate_serie CHECK (public.conta_fila_serie_ok(is_system, account_id, company_id, legal_ref, verified_at, source_key))
);


--
-- Name: TABLE withholding_rate; Type: COMMENT; Schema: public; Owner: -
