--

ALTER TABLE public.vacations ENABLE ROW LEVEL SECURITY;

--
-- Name: vacations vacations_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY vacations_delete ON public.vacations FOR DELETE TO authenticated USING ((public.current_user_is_admin_of(account_id) OR (EXISTS ( SELECT 1
   FROM public.employees e
  WHERE ((e.id = vacations.employee_id) AND public.current_user_manages_location(e.location_id)))) OR (public.current_user_is_employee(employee_id, account_id) AND (status = 'solicitada'::text))));


--
-- Name: vacations vacations_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY vacations_insert ON public.vacations FOR INSERT TO authenticated WITH CHECK ((public.current_user_is_admin_of(account_id) OR (EXISTS ( SELECT 1
   FROM public.employees e
  WHERE ((e.id = vacations.employee_id) AND public.current_user_manages_location(e.location_id)))) OR (public.current_user_is_employee(employee_id, account_id) AND (status = 'solicitada'::text))));


--
-- Name: vacations vacations_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY vacations_read ON public.vacations FOR SELECT TO authenticated USING ((public.current_user_is_admin_of(account_id) OR public.current_user_is_employee(employee_id, account_id) OR ((type <> 'baja_medica'::text) AND public.current_user_ve_persona(employee_id, account_id))));


--
-- Name: vacations vacations_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY vacations_update ON public.vacations FOR UPDATE TO authenticated USING ((public.current_user_is_admin_of(account_id) OR (EXISTS ( SELECT 1
   FROM public.employees e
  WHERE ((e.id = vacations.employee_id) AND public.current_user_manages_location(e.location_id)))) OR (public.current_user_is_employee(employee_id, account_id) AND (status = 'solicitada'::text)))) WITH CHECK ((public.current_user_is_admin_of(account_id) OR (EXISTS ( SELECT 1
   FROM public.employees e
  WHERE ((e.id = vacations.employee_id) AND public.current_user_manages_location(e.location_id)))) OR (public.current_user_is_employee(employee_id, account_id) AND (status = ANY (ARRAY['solicitada'::text, 'cancelada'::text])))));


